INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 1, 'Na počátku stvořil Bůh nebe a zemi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 2, 'Země pak byla nesličná a pustá, a tma byla nad propastí, a Duch Boží vznášel se nad vodami.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 3, 'I řekl Bůh: Buď světlo! I bylo světlo.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 4, 'A viděl Bůh světlo, že bylo dobré; i oddělil Bůh světlo od tmy.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 5, 'A nazval Bůh světlo dnem, a tmu nazval nocí. I byl večer a bylo jitro, den první.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 6, 'Řekl také Bůh: Buď obloha u prostřed vod, a děl vody od vod!');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 7, 'I učinil Bůh tu oblohu, a oddělil vody, kteréž jsou pod oblohou, od vod, kteréž jsou nad oblohou. A stalo se tak.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 8, 'I nazval Bůh oblohu nebem. I byl večer a bylo jitro, den druhý.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 9, 'Řekl také Bůh: Shromažďte se vody, kteréž jsou pod nebem, v místo jedno, a ukaž se místo suché! A stalo se tak.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 10, 'I nazval Bůh místo suché zemí, shromáždění pak vod nazval mořem. A viděl Bůh, že to bylo dobré.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 11, 'Potom řekl Bůh: Zploď země trávu, a bylinu vydávající símě, a strom plodný, nesoucí ovoce podlé pokolení svého, v němž by bylo símě jeho na zemi. A stalo se tak.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 12, 'Nebo země vydala trávu, a bylinu nesoucí semeno podlé pokolení svého, i strom přinášející ovoce, v němž bylo símě jeho, podlé pokolení jeho. A viděl Bůh, že to bylo dobré.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 13, 'I byl večer a bylo jitro, den třetí.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 14, 'Opět řekl Bůh: Buďte světla na obloze nebeské, aby oddělovala den od noci, a byla na znamení a rozměření časů, dnů a let.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 15, 'A aby svítila na obloze nebeské, a osvěcovala zemi. A stalo se tak.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 16, 'I učinil Bůh dvě světla veliká, světlo větší, aby správu drželo nade dnem, a světlo menší, aby správu drželo nad nocí; též i hvězdy.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 17, 'A postavil je Bůh na obloze nebeské, aby osvěcovala zemi;');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 18, 'A aby správu držela nade dnem a nocí, a oddělovala světlo od tmy. A viděl Bůh, že to bylo dobré.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 19, 'I byl večer a bylo jitro, den čtvrtý.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 20, 'Řekl ještě Bůh: Vydejte vody hmyz duše živé v hojnosti, a ptactvo, kteréž by létalo nad zemí pod oblohou nebeskou!');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 21, 'I stvořil Bůh velryby veliké a všelijakou duši živou, hýbající se, kteroužto v hojnosti vydaly vody podlé pokolení jejich, a všeliké ptactvo křídla mající, podlé pokolení jeho. A viděl Bůh, že to bylo dobré.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 22, 'I požehnal jim Bůh, řka: Ploďtež se a množte se, a naplňte vody mořské; též ptactvo ať se rozmnožuje na zemi!');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 23, 'I byl večer a bylo jitro, den pátý.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 24, 'Řekl též Bůh: Vydej země duši živou, jednu každou podlé pokolení jejího, hovada a zeměplazy, i zvěř zemskou, podlé pokolení jejího. A stalo se tak.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 25, 'I učinil Bůh zvěř zemskou podlé pokolení jejího, též hovada vedlé pokolení jejich, i všeliký zeměplaz podlé pokolení jeho. A viděl Bůh, že bylo dobré.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 26, 'Řekl opět Bůh: Učiňme člověka k obrazu našemu, podlé podobenství našeho, a ať panují nad rybami mořskými, a nad ptactvem nebeským, i nad hovady, a nade vší zemí, i nad všelikým zeměplazem hýbajícím se na zemi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 27, 'I stvořil Bůh člověka k obrazu svému, k obrazu Božímu stvořil jej, muže a ženu stvořil je.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 28, 'A požehnal jim Bůh, a řekl jim Bůh: Ploďtež se a rozmnožujte se, a naplňte zemi, a podmaňte ji, a panujte nad rybami mořskými, a nad ptactvem nebeským, i nad všelikým živočichem hýbajícím se na zemi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 29, 'Řekl ještě Bůh: Aj, dal jsem vám všelikou bylinu, vydávající símě, kteráž jest na tváři vší země, a všeliké stromoví, (na němž jest ovoce stromu), nesoucí símě; to bude vám za pokrm.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 30, 'Všechněm pak živočichům zemským, i všemu ptactvu nebeskému, a všemu tomu, což se hýbe na zemi, v čemž jest duše živá, všelikou bylinu zelenou dal jsem ku pokrmu. I stalo se tak.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 31, 'A viděl Bůh vše, což učinil, a aj, bylo velmi dobré. I byl večer a bylo jitro, den šestý.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 1, 'A tak dokonána jsou nebesa a země, i všecko vojsko jejich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 2, 'A dokonal Bůh dne sedmého dílo své, kteréž dělal; a odpočinul v den sedmý ode všeho díla svého, kteréž byl dělal.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 3, 'I požehnal Bůh dni sedmému a posvětil ho; nebo v něm odpočinul Bůh ode všeho díla svého, kteréž byl stvořil, aby učiněno bylo.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 4, 'Tiť jsou rodové nebes a země, (když stvořena jsou v den, v němž učinil Hospodin Bůh zemi i nebe),');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 5, 'I každé chrastiny polní, dříve než byla na zemi, i všeliké byliny polní, prvé než vzcházela; nebo ještě byl nedštil Hospodin Bůh na zemi, aniž byl který člověk, ješto by dělal zemi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 6, 'A aniž pára vystupovala z země, aby svlažovala všecken svrchek země.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 7, 'I učinil Hospodin Bůh člověka z prachu země, a vdechl v chřípě jeho dchnutí života, i byl člověk v duši živou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 8, 'Štípil pak byl Hospodin Bůh ráj v Eden na východ, a postavil tam člověka, jehož byl učinil.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 9, 'A vyvedl Hospodin Bůh z země všeliký strom na pohledění libý, a ovoce k jídlu chutné; též strom života u prostřed ráje, i strom vědění dobrého a zlého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 10, '(A řeka vycházela z Eden, k svlažování ráje, a odtud dělila se, a byla ve čtyři hlavní řeky.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 11, 'Jméno jedné Píson, ta obchází všecku zemi Hevilah, kdež jest zlato.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 12, 'A zlato země té jest výborné; tam jest i bdelium, a kámen onychin.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 13, 'Jméno pak druhé řeky Gihon, ta obchází všecku zemi Chus.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 14, 'A jméno řeky třetí Hiddekel, kteráž teče k východní straně Assyrské země. A řeka čtvrtá jest Eufrates.)');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 15, 'Pojav tedy Hospodin Bůh člověka, postavil jej v ráji v zemi Eden, aby jej dělal a ostříhal ho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 16, 'I zapověděl Hospodin Bůh člověku, řka: Z každého stromu rajského svobodně jísti budeš;');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 17, 'Ale z stromu vědění dobrého a zlého nikoli nejez; nebo v který bys koli den z něho jedl, smrtí umřeš.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 18, 'Řekl byl také Hospodin Bůh: Není dobré člověku býti samotnému; učiním jemu pomoc, kteráž by při něm byla.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 19, '(Nebo když byl učinil Hospodin Bůh z země všelikou zvěř polní, i všecko ptactvo nebeské, přivedl je k Adamovi, aby pohleděl na ně, jaké by jméno kterému dáti měl; a jak by koli nazval Adam kterou duši živou, tak aby jmenována byla.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 20, 'I dal Adam jména všechněm hovadům, i ptactvu nebeskému, a všeliké zvěři polní; Adamovi pak není nalezena pomoc, kteráž by při něm byla.)');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 21, 'Protož uvedl Hospodin Bůh tvrdý sen na Adama, i usnul; a vyňal jedno z žeber jeho, a to místo vyplnil tělem.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 22, 'A z toho žebra, kteréž vyňal z Adama, vzdělal Hospodin Bůh ženu, a přivedl ji k Adamovi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 23, 'I řekl Adam: Teď tato jest kost z kostí mých a tělo z těla mého; tato slouti bude mužatka, nebo z muže vzata jest.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 24, 'Z té příčiny opustí muž otce svého i matku svou, a přídržeti se bude manželky své, i budou v jedno tělo.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 25, 'Byli pak oba dva nazí, Adam i žena jeho, a nestyděli se.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 1, 'Had pak byl nejchytřejší ze všech živočichů polních, kteréž byl učinil Hospodin Bůh. A ten řekl ženě: Tak-liž jest, že vám Bůh řekl: Nebudete jísti z každého stromu rajského?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 2, 'I řekla žena hadu: Ovoce stromů rajských jíme;');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 3, 'Ale o ovoci stromu, kterýž jest u prostřed ráje, řekl Bůh: Nebudete ho jísti, aniž se ho dotknete, abyste nezemřeli.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 4, 'I řekl had ženě: Nikoli nezemřete smrtí!');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 5, 'Ale ví Bůh, že v kterýkoli den z něho jísti budete, otevrou se oči vaše; a budete jako bohové, vědouce dobré i zlé.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 6, 'Viduci tedy žena, že dobrý jest strom k jídlu i příjemný očima, a k nabytí rozumnosti strom žádostivý, vzala z ovoce jeho a jedla; dala také i muži svému s sebou, a on jedl.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 7, 'Tedy otevříny jsou oči obou dvou, a poznali, že jsou nazí; i navázali lístí fíkového a nadělali sobě věníků.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 8, 'A v tom uslyšeli hlas Hospodina Boha chodícího po ráji k větru dennímu; i skryl se Adam a žena jeho před tváří Hospodina Boha, u prostřed stromoví rajského.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 9, 'I povolal Hospodin Bůh Adama, a řekl jemu: Kdež jsi?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 10, 'Kterýžto řekl: Hlas tvůj slyšel jsem v ráji a bál jsem se, že jsem nahý; protož skryl jsem se.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 11, 'I řekl Bůh: Kdožť oznámil, že jsi nahý? Nejedl-lis ale z toho stromu, z něhožť jsem jísti zapověděl?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 12, 'I řekl Adam: Žena, kterouž jsi mi dal, aby byla se mnou, ona mi dala z stromu toho, a jedl jsem.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 13, 'I řekl Hospodin Bůh ženě: Což jsi to učinila? I řekla žena: Had mne podvedl, i jedla jsem.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 14, 'Tedy řekl Hospodin Bůh hadu: Že jsi to učinil, zlořečený budeš nade všecka hovada a nade všecky živočichy polní; po břiše svém plaziti se budeš, a prach žráti budeš po všecky dny života svého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 15, 'Nad to, nepřátelství položím mezi tebou a mezi ženou, i mezi semenem tvým a semenem jejím; ono potře tobě hlavu, a ty potřeš jemu patu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 16, 'Ženě pak řekl: Velice rozmnožím bolesti tvé a počínání tvá, s bolestí roditi budeš děti, a pod mocí muže tvého bude žádost tvá, a on panovati bude nad tebou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 17, 'Adamovi také řekl: Že jsi uposlechl hlasu ženy své, a jedl jsi z stromu toho, kterýžť jsem zapověděl, řka: Nebudeš jísti z něho; zlořečená země pro tebe, s bolestí jísti budeš z ní po všecky dny života svého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 18, 'Trní a bodláčí tobě ploditi bude, i budeš jísti byliny polní.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 19, 'V potu tváři své chléb jísti budeš, dokavadž se nenavrátíš do země, poněvadž jsi z ní vzat. Nebo prach jsi a v prach se navrátíš.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 20, 'Dal pak byl Adam jméno ženě své Eva, proto že ona byla mátě všech živých.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 21, 'I zdělal Hospodin Bůh Adamovi a ženě jeho oděv kožený, a přioděl je.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 22, 'Tedy řekl Hospodin Bůh: Aj, člověk učiněn jest jako jeden z nás, věda dobré i zlé; pročež nyní, aby nevztáhl ruky své, a nevzal také z stromu života, a jedl by, i byl by živ na věky, vyžeňme jej.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 23, 'I vypustil jej Hospodin Bůh z zahrady Eden, aby dělal zemi, z níž vzat byl.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 24, 'A tak vyhnal člověka a osadil zahradu Eden cherubíny k východní straně s mečem plamenným blýskajícím se, aby ostříhali cesty k stromu života.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 1, 'Adam pak poznal Evu ženu svou, kterážto počavši, porodila Kaina a řekla: Obdržela jsem muže na Hospodinu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 2, 'A opět porodila bratra jeho Abele. I byl Abel pastýř ovcí, a Kain byl oráč.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 3, 'Po mnohých pak dnech stalo se, že obětoval Kain z úrody zemské obět Hospodinu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 4, 'Ano i Abel také obětoval z prvorozených věcí stáda svého, a z tuku jejich. I vzhlédl Hospodin na Abele a na obět jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 5, 'Na Kaina pak a na obět jeho nevzhlédl. Protož rozlítil se Kain náramně, a opadla tvář jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 6, 'I řekl Hospodin Kainovi: Proč jsi se tak rozpálil hněvem? A proč jest opadla tvář tvá?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 7, 'Zdaliž nebudeš příjemný, budeš-li dobře činiti? Pakli nebudeš dobře činiti, hřích ve dveřích leží; a pod mocí tvou bude žádost jeho, a ty panovati budeš nad ním.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 8, 'I mluvil Kain k Abelovi bratru svému. Stalo se pak, když byli na poli, že povstav Kain proti Abelovi bratru svému, zabil jej.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 9, 'I řekl Hospodin Kainovi: Kdež jest Abel bratr tvůj? Kterýž odpověděl: Nevím. Zdaliž jsem já strážným bratra svého?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 10, 'I řekl Bůh: Co jsi učinil? Hlas krve bratra tvého volá ke mně z země.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 11, 'Protož nyní zlořečený budeš i od té země, kteráž otevřela ústa svá, aby přijala krev bratra tvého z ruky tvé.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 12, 'Když budeš dělati zemi, nebude více vydávati moci své tobě; tulákem a běhounem budeš na zemi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 13, 'I řekl Kain Hospodinu: Většíť jest nepravost má, než aby mi odpuštěna býti mohla.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 14, 'Aj, vyháníš mne dnes z země této, a před tváří tvou skrývati se budu, a budu tulákem a běhounem na zemi. I přijde na to, že kdo mne koli nalezne, zabije mne.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 15, 'I řekl mu Hospodin: Zajisté kdo by koli zabil Kaina, nad tím sedmnásobně mštěno bude. Pročež vložil Hospodin znamení na Kaina, aby ho žádný nezabil, kdo by jej koli nalezl.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 16, 'Tedy odšed Kain od tváři Hospodinovy, bydlil v zemi Nód, k východní straně naproti Eden.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 17, 'Poznal pak Kain ženu svou, kterážto počala a porodila Enocha. I stavěl město, a nazval jméno města toho jménem syna svého Enoch.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 18, 'I narodil se Enochovi Irád, a Irád zplodil Maviaele, Maviael pak zplodil Matuzaele, a Matuzael zplodil Lámecha.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 19, 'Vzal sobě pak Lámech dvě ženy; jméno jedné Ada, a jméno druhé Zilla.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 20, 'I porodila Ada Jábale, kterýž byl otec přebývajících v staních a stádo pasoucích.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 21, 'A jméno bratra jeho Jubal; ten byl otec všech hrajících na harfu a nástroje hudebné.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 22, 'A Zilla také porodila Tubalkaina, kterýž byl řemeslník všelikého díla od mědi a od železa. Sestra pak Tubalkainova byla Noéma.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 23, 'I řekl Lámech ženám svým, Adě a Zille: Slyšte hlas můj, ženy Lámechovy, poslouchejte řeči mé, že jsem zabil muže k ráně své a mládence k zsinalosti své.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 24, 'Jestližeť sedmnásobně pomštěno bude pro Kaina, tedy pro Lámecha sedmdesátekrát sedmkrát.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 25, 'Poznal pak ještě Adam ženu svou, i porodila syna a nazvala jméno jeho Set; nebo řekla: Dal mi Bůh jiné símě místo Abele, kteréhož zabil Kain.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 26, 'Setovi pak také narodil se syn, a nazval jméno jeho Enos. Tehdáž začalo se vzývání jména Hospodinova.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 1, 'Tato jest kniha rodů Adamových. V ten den, v kterémž stvořil Bůh člověka, ku podobenství Božímu učinil ho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 2, 'Muže a ženu stvořil je a požehnal jim, a nazval jméno jejich Adam v ten den, když stvořeni jsou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 3, 'Byl pak Adam ve stu a třidcíti letech, když zplodil syna ku podobenství svému a k obrazu svému, a nazval jméno jeho Set.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 4, 'I bylo dnů Adamových po zplození Seta osm set let, a plodil syny a dcery.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 5, 'A tak bylo všech dnů Adamových, v kterýchž byl živ, devět set a třidceti let, i umřel.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 6, 'Set pak byl ve stu a pěti letech, když zplodil Enosa.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 7, 'A po zplození Enosa živ byl Set osm set a sedm let, a plodil syny a dcery.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 8, 'I bylo všech dnů Setových devět set a dvanácte let, i umřel.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 9, 'Byl pak Enos v devadesáti letech, když zplodil Kainana.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 10, 'A po zplození Kainana živ byl Enos osm set a patnácte let, a plodil syny a dcery.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 11, 'I bylo všech dnů Enosových devět set a pět let, i umřel.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 12, 'Kainan pak byl v sedmdesáti letech, když zplodil Mahalaleele.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 13, 'A po zplození Mahalaleele živ byl Kainan osm set a čtyřidceti let, a plodil syny a dcery.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 14, 'I bylo všech dnů Kainanových devět set a deset let, i umřel.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 15, 'Mahalaleel pak byl v šedesáti a pěti letech, když zplodil Járeda.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 16, 'A po zplození Járeda živ byl Mahalaleel osm set a třidceti let, a plodil syny a dcery.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 17, 'I bylo všech dnů Mahalaleelových osm set devadesáte a pět let, i umřel.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 18, 'Járed pak byl ve stu šedesáti a dvou letech, když zplodil Enocha.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 19, 'A po zplození Enocha živ byl Járed osm set let, a plodil syny a dcery.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 20, 'I bylo všech dnů Járedových devět set šedesáte a dvě létě, i umřel.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 21, 'Enoch pak byl v šedesáti a pěti letech, když zplodil Matuzaléma.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 22, 'A chodil Enoch stále s Bohem po zplození Matuzaléma tři sta let, a plodil syny a dcery.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 23, 'I bylo všech dnů Enochových tři sta šedesáte a pět let.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 24, 'A chodil Enoch stále s Bohem a nebyl více vidín; nebo vzal ho Bůh.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 25, 'Matuzalém pak byl ve stu osmdesáti sedmi letech, když zplodil Lámecha.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 26, 'A po zplození Lámecha živ byl Matuzalém sedm set osmdesáte a dvě létě, a plodil syny a dcery.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 27, 'I bylo všech dnů Matuzalémových devět set šedesáte a devět let, i umřel.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 28, 'Lámech pak byl ve stu osmdesáti a dvou letech, když zplodil syna,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 29, 'Jehož jméno nazval Noé, řka: Tento nám odpočinutí způsobí od díla našeho, od práce rukou našich, kterouž máme s zemí, jížto zlořečil Hospodin.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 30, 'A živ byl Lámech potom, když zplodil Noé, pět set devadesáte a pět let, a plodil syny a dcery.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 31, 'I bylo všech dnů Lámechových sedm set sedmdesáte a sedm let, i umřel.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 32, 'A když byl Noé v pěti stech letech, zplodil Sema, Chama a Jáfeta.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 1, 'Stalo se pak, když se počali množiti lidé na zemi, a dcery se jim zrodily,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 2, 'Že vidouce synové Boží dcery lidské, any krásné jsou, brali sobě ženy ze všech, kteréž oblibovali.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 3, 'Pročež řekl Hospodin: Nebude se nesnaditi duch můj s člověkem na věky, proto že také tělo jest, a bude dnů jeho sto a dvadceti let.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 4, 'Obrové pak byli na zemi v těch dnech; ano i potom, když vcházeli synové Boží k dcerám lidským, ony rodily jim. To jsou ti mocní, kteříž zdávna byli, muži na slovo vzatí.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 5, 'Ale když viděl Hospodin, an se rozmnožuje zlost lidská na zemi, a že by všeliké myšlení srdce jejich nebylo než zlé po všecken čas,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 6, 'Litoval Hospodin, že učinil člověka na zemi, a bolest měl v srdci svém.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 7, 'Tedy řekl Hospodin: Vyhladím z země člověka, kteréhož jsem stvořil, od člověka až do hovada, až do zeměplazu, až i do ptactva nebeského; nebo líto mi, že jsem je učinil.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 8, 'Ale Noé našel milost před Hospodinem.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 9, 'Tito jsou příběhové Noé: Noé muž spravedlivý, dokonalý byl za svého věku, s Bohem ustavičně chodil Noé.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 10, '(Zplodil pak Noé tři syny: Sema, Chama a Jáfeta.)');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 11, 'Ale země byla porušena před Bohem, a naplněna byla země nepravostí.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 12, 'Viděl tedy Bůh zemi, a aj, porušena byla, nebo bylo porušilo všeliké tělo cestu svou na zemi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 13, 'Protož řekl Bůh k Noé: Konec všelikého těla přichází přede mne, nebo naplněna jest země nepravostí od nich; z té příčiny, hle, již zkazím je s zemí.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 14, 'Učiň sobě koráb z dříví gofer; příhrady zděláš v tom korábu, a oklejuješ jej vnitř i zevnitř klím.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 15, 'A na tento způsob uděláš jej: Tří set loktů bude dlouhost toho korábu, padesáti loktů širokost jeho a třidceti loktů vysokost jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 16, 'Okno uděláš v korábu, a svrchkem na loket vysokým zavřeš jej; dvéře také korábu v boku jeho postavíš, a pokoje spodní, druhé i třetí zděláš v něm.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 17, 'Já pak, aj, já uvedu potopu vod na zemi, aby zkaženo bylo všeliké tělo, v němž jest duch života pod nebem. Cožkoli bude na zemi, umře.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 18, 'S tebou však učiním smlouvu svou; a vejdeš do korábu, ty i synové tvoji, žena tvá i ženy synů tvých s tebou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 19, 'A ze všech živočichů všelikého těla, po dvém z každého uvedeš do korábu, abys je živé zachoval s sebou; samec a samice budou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 20, 'Z ptactva podlé pokolení jeho, a z hovad podlé pokolení jejich, ze všelikého také zeměplazu podlé pokolení jeho, po dvém z každého vejdou k tobě, aby živi zůstali.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 21, 'Ty pak nabeř s sebou všeliké potravy, kteráž se jísti může, a shromažď sobě, aby byla tobě i jim ku pokrmu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 22, 'I učinil Noé podlé všeho, jakž mu rozkázal Bůh, tak učinil.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 1, 'Potom řekl Hospodin k Noé: Vejdiž ty i všecka čeled tvá do korábu; nebo jsem tě viděl spravedlivého před sebou v národu tomto.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 2, 'Ze všech hovad čistých vezmeš sobě sedmero a sedmero, samce a samici jeho, ale z hovad nečistých dvé a dvé, samce a samici jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 3, 'Z ptactva také nebeského sedmero a sedmero, samce a samici, aby živé zachováno bylo símě na vší zemi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 4, 'Nebo po dnech ještě sedmi já dštíti budu na zemi za čtyřidceti dnů a čtyřidceti nocí; a vyhladím se svrchku země všelikou podstatu, kterouž jsem učinil.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 5, 'Tedy učinil Noé všecko tak, jakž mu přikázal Hospodin.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 6, '(Byl pak Noé v šesti stech letech, když ta potopa přišla na zemi.)');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 7, 'A protož přišel Noé a synové jeho, i žena jeho, i ženy synů jeho s ním k korábu, pro vody potopy.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 8, 'Z hovad také čistých i z hovad nečistých, i z ptactva a ze všeho, což se hýbe na zemi,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 9, 'Po dvém vešli k Noé do korábu, samec a samice, tak jakž byl rozkázal Bůh Noé.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 10, 'Stalo se pak po sedmi dnech, že vody potopy přišly na zemi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 11, 'Léta šestistého věku Noé, druhého měsíce, sedmnáctého dne téhož měsíce, v ten den protrženy jsou všecky studnice propasti veliké, a průduchové nebeští otevříni jsou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 12, 'I byl příval na zemi čtyřidceti dní a čtyřidceti nocí.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 13, 'Toho dne všel Noé, Sem a Cham i Jáfet, synové Noé, žena Noé, a tři ženy synů jeho s ním do korábu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 14, 'Oni i všeliký živočich podlé pokolení svého, i všeliké hovado podlé pokolení svého, a všeliký zeměplaz, kterýž se hýbe na zemi, podlé pokolení svého, i všeliké ptactvo vedlé pokolení svého, všelijací ptáci, všecko, což křídla má,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 15, 'Vešli k Noé do korábu, po dvém ze všelikého těla, v němž byl duch života.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 16, 'A což jich vešlo, samec a samice ze všelikého těla vešli, tak jakž byl přikázal jemu Bůh, a zavřel Hospodin po něm.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 17, 'A když byla potopa za čtyřidceti dnů na zemi, tedy rozmnoženy jsou vody, až i vyzdvihly koráb, a vznesly jej od země.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 18, 'Nebo zmohly se vody a rozmnoženy jsou velmi nad zemí, i zplýval koráb na vodách.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 19, 'A tak náramně rozmohly se vody nad zemí, že přikryty jsou všecky hory nejvyšší, kteréž byly pode vším nebem.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 20, 'Patnácte loktů zvýší rozmohly se vody, když přikryty jsou hory.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 21, 'I umřelo všeliké tělo, kteréž se hýbe na zemi, tak z ptactva, jako z hovad a živočichů, i všelikého hmyzu, kterýž se plazí po zemi, i každého člověka.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 22, 'Všecko, což mělo dýchání ducha života v chřípích svých, ze všeho, což bylo na suše, pomřelo.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 23, 'A tak vyhladil Bůh všelikou podstatu, kteráž byla na tváři země, od člověka až do hovada, až do zeměplazu, a až do ptactva nebeského, vyhlazeno jest, pravím, z země; a zůstal toliko Noé, a kteříž s ním byli v korábu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 24, 'I trvaly vody nad zemí za sto a padesáte dnů.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 1, 'Rozpomenul se pak Bůh na Noé, i všecky živočichy a všecka hovada, kteráž byla s ním v korábu; pročež uvedl Bůh vítr na zemi, i zastavily se vody.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 2, 'A zavříny jsou studnice propasti i průduchové nebeští, a zastaven jest příval s nebe.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 3, 'I navrátily se vody se svrchku země, odcházejíce zase, a opadly vody po stu a padesáti dnech,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 4, 'Tak že odpočinul koráb sedmého měsíce, v sedmnáctý den toho měsíce na horách Ararat.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 5, 'Když pak vody odcházely a opadaly až do desátého měsíce, prvního dne téhož desátého měsíce ukázali se vrchové hor.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 6, 'I stalo se po čtyřidcíti dnech, otevřev Noé okno v korábu, kteréž byl udělal,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 7, 'Vypustil krkavce. Kterýžto vyletuje zase se vracoval, dokudž nevyschly vody na zemi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 8, 'Potom vypustil holubici od sebe, aby věděl, již-li by opadly vody se svrchku země.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 9, 'Kterážto když nenašla, kde by odpočinula noha její, navrátila se k němu do korábu; nebo vody byly po vší zemi. On pak vztáhna ruku svou, vzal ji, a vnesl k sobě do korábu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 10, 'A počekal ještě sedm dní jiných, a opět vypustil holubici z korábu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 11, 'I přiletěla k němu holubice k večerou, a aj, list olivový utržený v ústech jejích. Tedy poznal Noé, že opadly vody se svrchku země.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 12, 'I čekal ještě sedm dní jiných, a opět vypustil holubici, kterážto nevrátila se k němu více.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 13, 'I stalo se šestistého prvního léta, v první den měsíce prvního, že vyschly vody na zemi. I odjal Noé přikrytí korábu a uzřel, ano již oschl svrchek země.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 14, 'Druhého pak měsíce, v dvadcátý sedmý den téhož měsíce oschla země.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 15, 'I mluvil Bůh k Noé, řka:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 16, 'Vyjdi z korábu, ty i žena tvá, a synové tvoji, i ženy synů tvých s tebou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 17, 'Všecky živočichy, kteříž jsou s tebou ze všelikého těla, tak z ptactva jako z hovad a všelikého zeměplazu, kterýž se hýbe na zemi, vyveď s sebou; ať se v hojnosti rozplozují na zemi, a rostou a množí se na zemi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 18, 'I vyšel Noé a synové jeho, i žena jeho a ženy synů jeho s ním;');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 19, 'Každý živočich, každý zeměplaz a všecko ptactvo, všecko, což se hýbe na zemi, po pokoleních svých vyšlo z korábu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 20, 'Tedy vzdělal Noé oltář Hospodinu, a vzav ze všech hovad čistých i ze všeho ptactva čistého, obětoval zápaly na tom oltáři.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 21, 'I zachutnal Hospodin vůni tu příjemnou, a řekl Hospodin v srdci svém: Nebudu více zlořečiti zemi pro člověka, proto že myšlení srdce lidského zlé jest od mladosti jeho; aniž budu více bíti všeho, což živo jest, jako jsem učinil.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 22, 'Nýbrž dokavadž země trvati bude, setí a žeň, studeno i horko, léto a zima, den také a noc nepřestanou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 1, 'Tedy požehnal Bůh Noé i synům jeho a řekl jim: Ploďtež se a rozmnožujte se, a naplňte zemi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 2, 'Strach váš a hrůza vaše buď na všeliký živočich země, a na všecko ptactvo nebeské. Všecko, což se hýbe na zemi, a všecky ryby mořské v ruce vaše dány jsou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 3, 'Všecko, což se hýbe a jest živo, bude vám za pokrm; jako i bylinu zelenou, dal jsem vám to všecko.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 4, 'A však masa s duší jeho, kteráž jest krev jeho, nebudete jísti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 5, 'A zajisté krve vaší, duší vašich vyhledávati budu; z rukou každého hovada vyhledávati jí budu, i z ruky člověka, ano i z ruky každého bratra jeho budu vyhledávati duše člověka.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 6, 'Kdo by koli vylil krev člověka, skrze člověka vylita bude krev jeho; nebo k obrazu svému učinil Bůh člověka.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 7, 'Vy pak ploďte a množte se; v hojnosti se rozploďte na zemi, a rozmnoženi buďte na ní.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 8, 'I mluvil Bůh k Noé a synům jeho s ním, řka:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 9, 'Já zajisté vcházím v smlouvu svou s vámi, i s semenem vaším po vás,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 10, 'A se všelikou duší živou, kteráž jest s vámi, z ptactva, z hovad a ze všech živočichů zemských, kteříž jsou s vámi, ode všech, kteříž vyšli z korábu, až do všelikého živočicha zemského.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 11, 'Protož utvrzuji smlouvu svou s vámi, že nebude vyhlazeno více všeliké tělo vodami potopy; aniž bude více potopa k zkažení země.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 12, 'I řekl Bůh: Totoť bude znamení smlouvy, kteréž já dávám, mezi mnou a mezi vámi, a mezi všelikou duší živou, kteráž jest s vámi, po všecky věky.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 13, 'Duhu svou postavil jsem na oblaku, a bude na znamení smlouvy mezi mnou a mezi zemí.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 14, 'A budeť, když uvedu mračný oblak nad zemí, a ukáže se duha na oblaku,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 15, 'Že se rozpomenu na smlouvu svou, kteráž jest mezi mnou a mezi vámi a mezi všelikou duší živou v každém těle; a nebudou více vody ku potopě, aby zahladily všeliké tělo.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 16, 'Nebo když bude duha ta na oblaku, popatřím na ni, abych se rozpomenul na smlouvu věčnou mezi Bohem a mezi všelikou duší živou v každém těle, kteréž jest na zemi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 17, 'I řekl Bůh k Noé: Toť jest znamení smlouvy, kterouž jsem utvrdil mezi sebou a mezi všelikým tělem, kteréž jest na zemi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 18, 'Byli pak synové Noé, kteříž vyšli z korábu: Sem, Cham a Jáfet; a Cham byl otec Kanánův.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 19, 'Ti tři jsou synové Noé, a ti se rozprostřeli po vší zemi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 20, 'Noé pak obíraje se s zemí, začal dělati vinice.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 21, 'A pije víno, opil se, a obnažil se u prostřed stanu svého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 22, 'Viděl pak Cham, otec Kanánův, hanbu otce svého, a pověděl oběma bratřím svým vně.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 23, 'Tedy vzali Sem a Jáfet oděv, kterýžto oba položili na ramena svá, a jdouce zpátkem, zakryli hanbu otce svého; tváři pak jich byly odvráceny, a hanby otce svého neviděli.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 24, 'Procítiv pak Noé po svém víně, zvěděl, co mu učinil syn jeho mladší.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 25, 'I řekl: Zlořečený Kanán, služebník služebníků bude bratřím svým.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 26, 'Řekl také: Požehnaný Hospodin, Bůh Semův, a buď Kanán služebníkem jejich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 27, 'Rozšiřiž Bůh milostivě Jáfeta, aby bydlil v stáncích Semových, a buď Kanán služebníkem jejich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 28, 'Živ pak byl Noé po potopě tři sta a padesáte let.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 29, 'A tak bylo všech dnů Noé devět set a padesáte let; i umřel jest.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 1, 'Tito jsou pak rodové synů Noé, Sema, Chama a Jáfeta, jimž se tito synové zrodili po potopě.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 2, 'Synové Jáfetovi: Gomer a Magog, a Madai, a Javan, a Tubal, a Mešech, a Tiras.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 3, 'Synové pak Gomerovi: Ascenez, Rifat, a Togorma.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 4, 'Synové pak Javanovi: Elisa a Tarsis, Cetim a Dodanim.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 5, 'Od těch rozděleni jsou ostrovové národů po krajinách jejich, každý podlé jazyku svého, vedlé čeledi své, v národech svých.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 6, 'Synové pak Chamovi: Chus a Mizraim a Put a Kanán.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 7, 'A synové Chusovi: Sába, Evila, a Sabata, a Regma, a Sabatacha. Synové pak Regmovi: Sába a Dedan.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 8, 'Zplodil také Chus Nimroda; onť jest počal býti mocným na zemi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 9, 'To byl silný lovec před Hospodinem; protož se říká: Jako Nimrod silný lovec před Hospodinem.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 10, 'Počátek pak jeho království byl Babylon a Erech, Achad a Chalne, v zemi Sinear.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 11, 'Z země té vyšel do Assur, kdežto vystavěl Ninive, a Rohobot město, a Chále,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 12, 'A Rezen mezi Ninive a mezi Chále; toť jest město veliké.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 13, 'Mizraim pak zplodil Ludim a Anamim, a Laabim, a Neftuim,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 14, 'A Fetruzim, a Chasluim, (odkudž pošli Filistinští) a Kafturim.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 15, 'Kanán pak zplodil Sidona prvorozeného svého, a Het,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 16, 'A Jebuzea, a Amorea, a Gergezea,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 17, 'A Hevea, a Aracea, a Sinea,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 18, 'A Aradia, a Samarea, a Amatea; a potom odtud rozprostřely se čeledi Kananejských.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 19, 'A bylo pomezí Kananejských od Sidonu, když jdeš k Gerar až do Gázy; a odtud když jdeš k Sodomě a Gomoře, a Adama a Seboim až do Lázy.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 20, 'Ti jsou synové Chamovi po čeledech svých, vedlé jazyků svých, po krajinách svých, v národech svých.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 21, 'Semovi také, otci všech synů Heber, bratru Jáfeta staršího zrozeni jsou synové.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 22, 'A tito jsou synové Semovi: Elam, a Assur, a Arfaxad, a Lud, a Aram.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 23, 'Synové pak Aramovi: Hus, a Hul, a Geter, a Mas.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 24, 'Potom Arfaxad zplodil Sále; a Sále zplodil Hebera.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 25, 'Heberovi také narodili se dva synové; jméno jednoho Peleg, proto že za dnů jeho rozdělena byla země, a jméno bratra jeho Jektan.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 26, 'Jektan pak zplodil Elmodada, a Salefa, a Azarmota, a Járe,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 27, 'A Adoráma, a Uzala, a Dikla,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 28, 'A Obale, a Abimahele, a Sebai,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 29, 'A Ofira, a Evila, a Jobaba; všickni ti jsou synové Jektanovi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 30, 'A bylo bydlení jejich od Mesa, když jdeš k Sefar hoře na východ slunce.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 31, 'Tiť jsou synové Semovi po čeledech svých, vedlé jazyků svých, po krajinách svých, v národech svých.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 32, 'Ty jsou čeledi synů Noé po rodech svých, v národech svých; a od těch rozdělili se národové na zemi po potopě.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 1, 'Byla pak všecka země jazyku jednoho a řeči jedné.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 2, 'I stalo se, když se brali od východu, nalezli pole v zemi Sinear, a bydlili tam.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 3, 'A řekli jeden druhému: Nuže, nadělejme cihel, a vypalme je ohněm. I měli cihly místo kamení, a zemi lepkou místo vápna.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 4, 'Nebo řekli: Nuže, vystavějme sobě město a věži, jejíž by vrch dosahal k nebi; a tak učiňme sobě jméno, abychom nebyli rozptýleni po vší zemi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 5, 'Sstoupil pak Hospodin, aby viděl to město a věži, kterouž stavěli synové lidští.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 6, 'A řekl Hospodin: Aj, lid jeden a jazyk jeden všechněch těchto, a toť jest začátek díla jejich; nyní pak nedadí sobě v tom překaziti, což umínili dělati.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 7, 'Protož sstupme a změťme tam jazyk jejich, aby jeden druhého jazyku nerozuměl.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 8, 'A tak rozptýlil je Hospodin odtud po vší zemi; i přestali stavěti města toho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 9, 'Protož nazváno jest jméno jeho Bábel; nebo tu zmátl Hospodin jazyk vší země; a odtud rozptýlil je Hospodin po vší zemi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 10, 'Titoť jsou rodové Semovi: Sem, když byl ve stu letech, zplodil Arfaxada ve dvou letech po potopě.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 11, 'A byl živ Sem po zplození Arfaxada pět set let; a plodil syny a dcery.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 12, 'Arfaxad pak živ byl pět a třidceti let, a zplodil Sále.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 13, 'A po zplození Sále živ byl Arfaxad čtyři sta a tři léta; a plodil syny a dcery.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 14, 'Sále také živ byl třidceti let, a zplodil Hebera.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 15, 'A živ byl Sále po zplození Hebera čtyři sta a tři léta; a plodil syny a dcery.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 16, 'Živ pak byl Heber čtyři a třidceti let, a zplodil Pelega.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 17, 'A živ byl Heber po zplození Pelega čtyři sta a třidceti let; a plodil syny a dcery.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 18, 'Peleg pak živ byl třidceti let, a zplodil Réhu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 19, 'A živ byl Peleg po zplození Réhu dvě stě a devět let; a plodil syny a dcery.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 20, 'Réhu také živ byl třidceti a dvě létě, a zplodil Sáruga.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 21, 'A po zplození Sáruga živ byl Réhu dvě stě a sedm let; a plodil syny a dcery.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 22, 'Živ pak byl Sárug třidceti let, a zplodil Náchora.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 23, 'A byl živ Sárug po zplození Náchora dvě stě let; a plodil syny a dcery.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 24, 'Náchor pak živ byl dvadceti a devět let, a zplodil Táre.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 25, 'A živ byl Náchor po zplození Táre sto a devatenácte let; a plodil syny a dcery.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 26, 'Živ pak byl Táre sedmdesáte let, a zplodil Abrama, Náchora a Hárana.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 27, 'Tito jsou pak rodové Táre: Táre zplodil Abrama, Náchora a Hárana; Háran pak zplodil Lota.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 28, 'Umřel pak Háran prvé než Táre otec jeho v zemi narození svého, totiž v Ur Kaldejských.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 29, 'I zpojímali sobě ženy Abram a Náchor; jméno ženy Abramovy Sarai, a jméno ženy Náchorovy Melcha, dcera Háranova, kterýž byl otec Melchy a Jeschy.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 30, 'Byla pak Sarai neplodná, a neměla dětí.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 31, 'I vzal Táre Abrama syna svého, a Lota syna Háranova, vnuka svého, a Sarai nevěstu svou, ženu Abrama syna svého, a vyšli spolu z Ur Kaldejských, aby se brali do země Kananejské, a přišli až do Cháran, a bydlili tam.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 32, 'A byli dnové Táre dvě stě a pět let; i umřel Táre v Cháran.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 1, 'Nebo byl řekl Hospodin Abramovi: Vyjdi z země své a z příbuznosti své, i z domu otce svého do země, kterouž ukáži tobě.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 2, 'A učiním tě v národ veliký, a požehnám tobě, a zvelebím jméno tvé, a budeš požehnání.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 3, 'Požehnám také dobrořečícím tobě, a zlořečícím tobě zlořečiti budu; ano požehnány budou v tobě všecky čeledi země.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 4, 'I vyšel Abram, tak jakž mu byl mluvil Hospodin, a šel s ním Lot. (Byl pak Abram v sedmdesáti pěti letech, když vyšel z Cháran.)');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 5, 'A vzal Abram Sarai manželku svou, a Lota syna bratra svého, a všecko zboží své, kteréhož nabyli, i duše, kterýchž dosáhli v Cháran. A vyšedše, brali se do země Kananejské, až i přišli do ní.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 6, 'I prošel Abram tu zemi až k místu Sichem, to jest až k rovině More. A tehdáž Kananejští byli v zemi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 7, 'I ukázal se Hospodin Abramovi a řekl: Semeni tvému dám zemi tuto. Tedy vzdělal tu oltář Hospodinu, kterýž se byl ukázal jemu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 8, 'A odtud podal se k hoře, kteráž leží na východ od Bethel, kdežto rozbil stan svůj, tak že mu Bethel byl na západ, Hai pak na východ; i vzdělal tam oltář Hospodinu, a vzýval jméno Hospodinovo.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 9, 'Potom hnul se Abram dále, a odebral se odtud ku poledni.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 10, 'Byl pak hlad v té zemi; protož sstoupil Abram do Egypta, aby tam byl pohostinu; nebo veliký byl hlad v té zemi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 11, 'I stalo se, že když přicházel blízko k Egyptu, řekl k Sarai manželce své: Aj, nyní znám, že jsi žena krásné tváři.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 12, 'A stane se, že když tě uzří Egyptští, řeknou: To jest manželka jeho; i zabijí mne, tebe pak živé nechají.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 13, 'Prav medle, že jsi sestra má, aby mi dobře bylo příčinou tvou, a živa zůstala duše má pro tebe.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 14, 'I stalo se, když všel Abram do Egypta, viděli Egyptští ženu, že krásná byla náramně.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 15, 'A vidouce ji knížata Faraonova, schválili ji před ním; i vzata jest žena do domu Faraonova.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 16, 'Kterýžto i Abramovi dobře učinil pro ni; a měl ovce a voly a osly, i služebníky a děvky, též oslice a velbloudy.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 17, 'Ale Hospodin trápil Faraona ranami velikými, i dům jeho, pro Sarai manželku Abramovu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 18, 'Protož povolal Farao Abrama a řekl: Cos mi to učinil? Pročežs mi neoznámil, že ona manželka tvá jest?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 19, 'Proč jsi řekl: Sestra má jest? A vzal jsem ji sobě za ženu. Protož nyní, teď máš manželku svou, vezmi a jdi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 20, 'I poručil o něm Farao mužům, a propustili ho, i manželku jeho i všecko, což měl.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 1, 'Vstoupil tedy Abram z Egypta on i žena jeho i všecko, což měl, a Lot s ním, ku poledni.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 2, '(Byl pak Abram bohatý velmi na dobytek, na stříbro i na zlato.)');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 3, 'A šel cestami svými od poledne až do Bethel, až k místu tomu, kdež prvé byl stánek jeho, mezi Bethel a Hai,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 4, 'K místu oltáře, kterýž tam byl prvé vzdělal, kdežto vzýval Abram jméno Hospodinovo.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 5, 'Také i Lot, kterýž s Abramem chodil, měl ovce a voly i stany.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 6, 'A nemohla jim země postačovati, aby spolu bydlili, proto že zboží jich bylo veliké, tak že nemohli spolu bydliti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 7, 'Odkudž vznikla nesnáz mezi pastýři stáda Abramova a mezi pastýři stáda Lotova; nebo Kananejští a Ferezejští tehdáž bydlili v zemi té.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 8, 'Řekl tedy Abram k Lotovi: Nechžť, prosím, není nesnáze mezi mnou a tebou, a mezi pastýři mými a pastýři tvými, poněvadž muži bratří jsme.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 9, 'Zdaliž není před tebou všecka země? Odděl se, prosím, ode mne. Půjdeš-li na levo, já na pravo se držeti budu; pakli půjdeš na pravo, na levo se držeti budu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 10, 'Pozdvih tedy Lot očí svých, spatřil všecku rovinu vůkol Jordánu, kteráž před tím, než Hospodin zkazil Sodomu a Gomoru, všecka až k Ségor svlažována byla, jako zahrada Hospodinova, a jako země Egyptská.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 11, 'I zvolil sobě Lot všecku rovinu Jordánskou, a bral se k východu; a tak oddělili se jeden od druhého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 12, 'Abram bydlil v zemi Kananejské, ale Lot přebýval v městech té roviny, podav stanů až k Sodomě.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 13, 'Lidé pak Sodomští byli zlí, a hříšníci před Hospodinem velicí.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 14, 'I řekl Hospodin Abramovi, když se oddělil od něho Lot: Pozdvihni nyní očí svých, a pohleď z místa, na němž jsi, na půlnoci a na poledne, i na východ a na západ.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 15, 'Nebo všecku zemi, kterouž vidíš, tobě dám a semeni tvému až na věky.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 16, 'A rozmnožím símě tvé jako prach země; nebo jestliže kdo bude moci sčísti prach země, tedy i símě tvé sečteno bude.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 17, 'Vstaň, projdi tu zemi na dýl i na šíř její; nebo tobě ji dám.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 18, 'Tedy Abram hnuv se s stanem, přišel a bydlil v rovinách Mamre, kteréž jsou při Hebronu, kdežto vzdělal oltář Hospodinu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 1, 'Stalo se pak ve dnech těch, že Amrafel král Sinearský, Arioch král Elasarský, Chedorlaomer král Elamitský, a Thádal král Goimský,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 2, 'Vyzdvihli válku proti Bérovi králi Sodomskému, a proti Bersovi králi Gomorskému, a Senábovi králi Adamatskému, a Semeberovi králi Seboimskému, a králi Bélamskému, to jest Ségorskému.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 3, 'Všickni tito sjeli se do údolí Siddim, to jest již moře solné.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 4, 'Dvanácte let sloužili Chedorlaomerovi, třináctého pak léta zprotivili se.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 5, 'Protož léta čtrnáctého přitáhl Chedorlaomer a králové, kteříž byli s ním, a pobili Refaimské v Astarotu Karnaimských, a Zuzimské v Cham, a Eminské na rovinách Kariataimských,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 6, 'A Horejské na hoře jich Seir, až k rovině Fáran, kteráž leží nad pouští.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 7, 'A vracejíce se, přitáhli k En Misfat, kteráž již jest Kádes, a pohubili všecku krajinu Amalechitského, také i Amorejského, bydlícího v Hasesontamar.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 8, 'Protož vytáhl král Sodomský, a král Gomorský, a král Adamatský, a král Seboimský, a král Bélamský, to jest Ségorský, a sšikovali se proti nim k bitvě v údolí Siddim,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 9, 'Proti Chedorlaomerovi králi Elamitskému, a Thádalovi králi Goimskému, a Amrafelovi králi Sinearskému, i Ariochovi králi Elasarskému, čtyři králové proti pěti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 10, '(V údolí pak Siddim bylo mnoho studnic klejovatých.) I utíkajíce král Sodomský a Gomorský, padli tam; a kteří pozůstali, utekli na hory.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 11, 'A pobravše všecko zboží Sodomských a Gomorských, a všecky potravy jich, odtáhli.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 12, 'Vzali také Lota, a zboží jeho, syna bratra Abramova, a odjeli; nebo on bydlil v Sodomě.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 13, 'Přišel pak jeden, kterýž byl utekl, a zvěstoval Abramovi Hebrejskému, kterýž tehdáž bydlil v rovinách Mamre Amorejského, bratra Eškolova a bratra Anerova; nebo ti měli smlouvu s Abramem.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 14, 'Uslyšev tedy Abram, že by zajat byl bratr jeho, vypravil způsobných k boji a v domě svém zrozených služebníků tři sta a osmnácte, a honil je až k Dan.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 15, 'A odděliv se, připadl na ně v noci, on i služebníci jeho, a porazil je; a stíhal je až k Chobah, kteréž leží na levo Damašku.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 16, 'I odjal zase všecko zboží; také i Lota bratra svého s statkem jeho zase přivedl, ano i ženy a lid.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 17, 'Tedy vyšel král Sodomský proti němu, když se navracoval od pobití Chedorlaomera a králů, kteříž byli s ním, k údolí Sáveh, kteréž jest údolí královské.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 18, 'Melchisedech také král Sálem, vynesl chléb a víno; a ten byl kněz Boha silného nejvyššího.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 19, 'I požehnal mu a řekl: Požehnaný Abram Bohu silnému nejvyššímu, kterýž vládne nebem a zemí;');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 20, 'A požehnaný Bůh silný nejvyšší, kterýž dal nepřátely tvé v ruce tvé. I dal mu Abram desátky ze všech věcí.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 21, 'Král pak Sodomský řekl Abramovi: Dej mi lid, a zboží vezmi sobě.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 22, 'I řekl Abram králi Sodomskému: Pozdvihl jsem ruky své k Hospodinu, Bohu silnému nejvyššímu, kterýž vládne nebem i zemí,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 23, 'Že nevezmu od niti až do řeménka obuvi ze všech věcí, kteréž jsou tvé, abys neřekl: Já jsem obohatil Abrama,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 24, 'Kromě toliko toho, což snědli bojovníci, a dílu mužů, kteříž se mnou šli, totiž Aner, Eškol a Mamre; oni nechať vezmou díl svůj.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 1, 'Když pak ty věci pominuly, stalo se slovo Hospodinovo k Abramovi u vidění, řkoucí: Neboj se, Abrame; já budu pavéza tvá, a odplata tvá velmi veliká.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 2, 'Jemužto řekl Abram: Panovníče Hospodine, což mi dáš, poněvadž já scházím bez dětí, a ten, jemuž zanechám domu svého, bude Damašský Eliezer?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 3, 'Řekl ještě Abram: Aj, mně jsi nedal semene; a aj, schovanec můj bude mým dědicem.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 4, 'A aj, slovo Hospodinovo k němu, řkuci: Nebudeť ten dědicem tvým, ale kterýž vyjde z života tvého, ten dědicem tvým bude.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 5, 'I vyvedl jej ven a řekl: Vzhlédniž nyní k nebi, a sečti hvězdy, budeš-li je však moci sčísti? Řekl mu ještě: Tak bude símě tvé.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 6, 'I uvěřil Hospodinu, a počteno mu to za spravedlnost.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 7, '(Nebo byl řekl jemu: Já jsem Hospodin, kterýž jsem tě vyvedl z Ur Kaldejských, aťbych dal zemi tuto k dědičnému vládařství.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 8, 'I řekl: Panovníče Hospodine, po čem poznám, že ji dědičně obdržím?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 9, 'I odpověděl jemu: Vezmi mně jalovici tříletou, a kozu tříletou, a skopce tříletého, hrdličku také a holoubátko.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 10, 'Kterýžto vzav ty všecky věci, zroztínal je na poly, a rozložil na dvě straně, jednu polovici proti druhé; ptáků pak nezroztínal.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 11, 'Ptáci pak sedali na ta mrtvá těla, a Abram je sháněl.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 12, 'I stalo se, když slunce zapadalo, že dřímota těžká připadla na Abrama; a aj, hrůza a tma veliká obklíčila jej).');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 13, 'Řekl tedy Bůh Abramovi: To zajisté věz, že pohostinu bude símě tvé v zemi cizí, a v službu je podrobí, a trápiti je budou za čtyři sta let.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 14, 'Však národ, jemuž sloužiti budou, já souditi budu; a potom vyjdou s velikým zbožím.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 15, 'Ty pak půjdeš k otcům svým v pokoji; a pohřben budeš v starosti dobré.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 16, 'A čtvrté pokolení sem se navrátí; nebť ještě není doplněna nepravost Amorejských.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 17, 'I stalo se, když zapadlo slunce, a tma bylo, a aj, ukázala se pec kouřící se, a pochodně ohnivá, kteráž šla mezi díly těmi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 18, 'V ten den učinil Hospodin smlouvu s Abramem, řka: Semeni tvému dám zemi tuto, od řeky Egyptské až do řeky té veliké, řeky Eufraten:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 19, 'Cinejské, Cenezejské, Cethmonské,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 20, 'A Hetejské, Ferezejské, a Refaimské,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 21, 'Amorejské, i Kananejské také, a Gergezejské a Jebuzejské.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 1, 'Sarai pak manželka Abramova jemu nerodila; a měla děvku Egyptskou, jménem Agar.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 2, 'I řekla Sarai Abramovi: Aj, nyní Hospodin zavřel život můj, abych nerodila; vejdi, prosím, k děvce mé, zda bych aspoň z ní mohla míti syny. I povolil Abram řeči Sarai.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 3, 'Tedy vzavši Sarai manželka Abramova Agar Egyptskou děvku svou, po desíti letech, jakž bydliti počal Abram v zemi Kananejské, dala ji Abramovi muži svému za ženu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 4, 'I všel k Agar, kterážto počala. Viduci pak ona, že počala, zlehčila sobě paní svou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 5, 'I řekla Sarai Abramovi: Křivdou mou tys vinen; já jsem dala děvku svou v lůno tvé, kterážto viduci, že počala, zlehčila mne sobě. Sudiž Hospodin mezi mnou a mezi tebou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 6, 'I řekl Abram k Sarai: Aj, děvka tvá v moci tvé; učiň s ní, cožť se za dobré vidí. Tedy trápila ji Sarai, a ona utekla od ní.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 7, 'Našel ji pak anděl Hospodinův u studnice vody na poušti, u studnice té, kteráž jest při cestě Sur.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 8, 'A řekl: Agar, děvko Sarai, odkud jdeš, a kam se béřeš? I řekla: Od tváři Sarai paní své já utíkám.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 9, 'Tedy řekl jí anděl Hospodinův: Navrať se ku paní své, a pokoř se pod ruku její.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 10, 'Opět řekl anděl Hospodinův: Velice rozmnožím símě tvé, aniž bude moci sečteno býti pro množství.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 11, 'Potom také řekl anděl Hospodinův: Aj, ty jsi těhotná, a tudíž porodíš syna, a nazůveš jméno jeho Izmael; nebo uslyšel Hospodin trápení tvé.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 12, 'Budeť pak lítý člověk; ruce jeho proti všechněm, a ruce všech proti němu; a před tváří všech bratří svých bydliti bude.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 13, 'I nazvala Agar jméno Hospodinovo, kterýž mluvil jí: Ty jsi silný Bůh vidění; nebo řekla: Zdaliž teď také nevidím po tom, kterýž mne viděl?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 14, 'Protož nazvala studnici tu studnicí Živého vidoucího mne. Aj, ta jest mezi Kádes a Barad.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 15, 'Porodila pak Agar Abramovi syna; a nazval Abram jméno syna svého, kteréhož porodila Agar, Izmael.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 16, 'Abram pak byl v osmdesáti šesti letech, když mu porodila Agar Izmaele.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 1, 'Když pak Abram byl v devadesáti devíti letech, ukázal se mu Hospodin, a řekl jemu: Já jsem Bůh silný všemohoucí; chodiž ustavičně přede mnou a budiž dokonalým.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 2, 'A učiním smlouvu svou mezi sebou a tebou a rozmnožím tě náramně velmi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 3, 'Padl pak Abram na tvář svou; i mluvil Bůh s ním, řka:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 4, 'Jáť jsem, aj, smlouva má s tebou, a budeš otcem národů mnohých.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 5, 'Aniž více slouti bude jméno tvé Abram, ale bude jméno tvé Abraham; nebo otcem mnohých národů učinil jsem tě.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 6, 'A učiním, abys se rozplodil náramně velmi, a rozšířím tě v národy; i králové z tebe vyjdou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 7, 'Utvrdím také smlouvu svou mezi sebou a tebou, i mezi semenem tvým po tobě, po rodech jejich, za smlouvu věčnou, totiž abych byl Bohem tvým i semene tvého po tobě.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 8, 'Nadto dám tobě i semeni tvému po tobě zemi, v nížto obýváš pohostinu, všecku zemi Kananejskou k vládařství věčnému; a budu jejich Bohem.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 9, 'Řekl ještě Bůh Abrahamovi: Ty pak ostříhati budeš smlouvy mé, ty i símě tvé po tobě, po rodech svých.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 10, 'Tatoť jest smlouva má mezi mnou a mezi vámi, i mezi semenem tvým po tobě, kteréž ostříhati budete: Aby obřezán byl mezi vámi každý pohlaví mužského.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 11, 'Obřežete pak tělo hanby své; a to bude znamením smlouvy mezi mnou a mezi vámi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 12, 'Každý tedy pohlaví mužského osmého dne obřezán bude mezi vámi po rodech vašich, doma narozený i koupený za stříbro, z kterých by koli cizozemců byl, jenž není z semene tvého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 13, 'Konečně ať jest obřezán narozený v domě tvém, i koupený za peníze tvé; a budeť smlouva má na těle vašem za smlouvu věčnou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 14, 'Neobřezaný pak pacholík, kterýž by neobřezal těla neobřízky své, vyhlazena zajisté bude duše ta z lidu svého; nebo smlouvu mou zrušil.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 15, 'Řekl také Bůh Abrahamovi: Sarai manželce své nebudeš říkati Sarai, ale Sára bude jméno její.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 16, 'Nebo požehnám jí a dámť z ní syna; požehnámť jí, a bude v národy; králové národů z ní vyjdou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 17, 'Tedy padl Abraham na tvář svou, a zasmáv se, řekl v srdci svém: Zdali stoletému narodí se syn? A zdali Sára v devadesáti letech porodí?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 18, 'I řekl Abraham Bohu: Ó byť jen Izmael živ byl před tebou!');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 19, 'Jemužto řekl Bůh: Nýbrž Sára manželka tvá porodí tobě syna, a nazůveš jméno jeho Izák; i utvrdím smlouvu svou s ním za smlouvu věčnou, i s semenem jeho po něm.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 20, 'Také o Izmaele uslyšel jsem tě; a aj, požehnám jemu, a učiním to, aby se rozplodil, a rozmnožím ho náramně velmi; dvanáctero knížat zplodí, a rozšířím jej v národ veliký.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 21, 'Ale smlouvu svou utvrdím s Izákem, kteréhožť porodí Sára po roce, při tomto času.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 22, 'A když dokonal Bůh řeč svou s ním, vstoupil od Abrahama.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 23, 'Vzal tedy Abraham Izmaele syna svého, i všecky zrozené v domě svém, i všecky koupené za stříbro své, každého, kdož byl pohlaví mužského, z domácích svých, a obřezal tělo neobřízky jejich hned v ten den, jakž s ním Bůh mluvil.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 24, 'A byl Abraham v devadesáti devíti letech, když obřezáno bylo tělo neobřízky jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 25, 'Izmael pak syn jeho byl v třinácti letech, když obřezáno bylo tělo neobřízky jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 26, 'Jednoho a téhož dne obřezáni jsou, Abraham a Izmael syn jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 27, 'I všickni domácí jeho, doma zrození i za stříbro od cizozemce koupení, obřezáni jsou s ním.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 1, 'Ukázal se pak jemu Hospodin v rovině Mamre; a on seděl u dveří stanu, když veliké horko na den bylo.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 2, 'A když pozdvihl očí svých, viděl, a aj, tři muži stáli naproti němu. Kteréžto jakž uzřel, běžel jim vstříc ode dveří stanu, a sklonil se až k zemi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 3, 'A řekl: Pane můj, jestliže jsem nyní nalezl milost před očima tvýma, prosím, nepomíjej služebníka svého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 4, 'Přineseno bude trochu vody, a umyjete nohy své, a odpočinete pod stromem.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 5, 'Zatím přinesu kus chleba, a posilníte srdce svého; potom půjdete, poněvadž mimo služebníka svého jdete. I řekli: Tak učiň, jakž jsi mluvil.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 6, 'Tedy pospíšil Abraham do stanu k Sáře, a řekl: Spěšně tři míry mouky bělné zadělej, a napec podpopelných chlebů.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 7, 'Abraham pak běžel k stádu; a vzav tele mladé a dobré, dal služebníku, kterýžto pospíšil připraviti je.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 8, 'Potom vzav másla a mléka, i tele, kteréž připravil, položil před ně; sám pak stál při nich pod stromem, i jedli.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 9, 'Řekli pak jemu: Kde jest Sára manželka tvá? Kterýžto odpověděl: Teď v stanu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 10, 'A řekl: Jistotně se navrátím k tobě vedlé času života, a aj, syna míti bude Sára manželka tvá. Ale Sára poslouchala u dveří stanu, kteréž byly za ním.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 11, 'Abraham pak i Sára byli staří a sešlého věku, a přestal byl Sáře běh ženský.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 12, 'I smála se Sára sama v sobě, řkuci: Teprv když jsem se sstarala, v rozkoše se vydám? A ještě i pán můj se sstaral.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 13, 'Tedy řekl Hospodin Abrahamovi: Proč jest se smála Sára, řkuci: Zdaliž opravdu ještě roditi budu, a já se sstarala?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 14, 'Zdaliž co skrytého bude před Hospodinem? K času určitému navrátím se k tobě vedlé času života, a Sára bude míti syna.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 15, 'Zapřela pak Sára a řekla: Nesmála jsem se; nebo se bála. I řekl Hospodin: Neníť tak, ale smála jsi se.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 16, 'Tedy vstavše odtud muži ti, obrátili se k Sodomě; Abraham pak šel s nimi, aby je provodil.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 17, 'A řekl Hospodin: Zdali já zatajím před Abrahamem, což dělati budu?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 18, 'Poněvadž Abraham jistotně bude v národ veliký a silný, a požehnáni budou v něm všickni národové země.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 19, 'Nebo znám jej; protož přikáže synům svým a domu svému po sobě, aby ostříhali cesty Hospodinovy, a činili spravedlnost a soud, aťby naplnil Hospodin Abrahamovi, což mu zaslíbil.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 20, 'I řekl Hospodin: Proto že rozmnožen jest křik Sodomských a Gomorských, a hřích jejich že obtížen jest náramně:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 21, 'Sstoupím již a pohledím, jestliže podle křiku jejich, kterýž přišel ke mně, činili, důjde na ně setření; a pakli toho není, zvím.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 22, 'A obrátivše se odtud muži, šli do Sodomy; Abraham pak ještě stál před Hospodinem.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 23, 'V tom přistoupiv Abraham, řekl: Zdali také zahladíš spravedlivého s bezbožným?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 24, 'Bude-li padesáte spravedlivých v tom městě, zdali předce zahubíš, a neodpustíš místu pro padesáte spravedlivých, kteříž jsou v něm?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 25, 'Odstup to od tebe, abys takovou věc učiniti měl, abys usmrtil spravedlivého s bezbožným; takť by byl spravedlivý jako bezbožný. Odstup to od tebe; zdaliž soudce vší země neučiní soudu?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 26, 'I řekl Hospodin: Jestliže naleznu v Sodomě, v městě tom, padesáte spravedlivých, odpustím všemu tomu místu pro ně.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 27, 'A odpovídaje Abraham, řekl: Aj, nyní chtěl bych mluviti ku Pánu svému, ačkoli jsem prach a popel.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 28, 'Co pak, nedostane-li se ku padesáti spravedlivým pěti, zdali zkazíš pro těch pět všecko město? I řekl: Nezahladím, jestliže najdu tam čtyřidceti pět.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 29, 'Opět mluvil Abraham a řekl: Snad nalezeno bude tam čtyřidceti? A odpověděl: Neučiním pro těch čtyřidceti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 30, 'I řekl Abraham: Prosím, nechť se nehněvá Pán můj, že mluviti budu: Snad se jich nalezne tam třidceti? Odpověděl: Neučiním, jestliže naleznu tam třidceti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 31, 'A opět řekl: Aj, nyní počal jsem mluviti ku Pánu svému: Snad se nalezne tam dvadceti? Odpověděl: Nezahladím i pro těch dvadceti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 32, 'Řekl ještě: Prosím, ať se nehněvá Pán můj, jestliže jednou ještě mluviti budu: Snad se jich najde tam deset? Odpověděl: Nezahladím i pro těch deset.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 33, 'I odšel Hospodin, když dokonal řeč k Abrahamovi; Abraham pak navrátil se k místu svému.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 1, 'Přišli pak dva andělé do Sodomy u večer, a Lot seděl v bráně Sodomské. Kteréžto když uzřel, vstav, šel jim v cestu a sklonil se tváří až k zemi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 2, 'A řekl: Aj, prosím páni moji, uchylte se nyní do domu služebníka svého, a zůstaňte přes noc; umyjete také nohy své a ráno vstanouce, půjdete cestou svou. Oni pak odpověděli: Nikoli, ale přenocujeme na ulici.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 3, 'Ale když on je velmi nutil, obrátivše se k němu, vešli do domu jeho. I udělal jim hody, a napekl chlebů přesných, i jedli.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 4, 'Prvé pak než lehli, muži města toho, muži Sodomští, osuli se vůkol domu toho, od mladého až do starého, všecken lid odevšad.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 5, 'I volali na Lota, a řekli jemu: Kde jsou ti muži, kteříž přišli k tobě v noci? Vyveď je k nám, ať je poznáme.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 6, 'I vyšel k nim Lot ven, a zavřel po sobě dvéře.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 7, 'A řekl: Prosím, bratří moji, nečiňte zlého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 8, 'Aj, mám teď dvě dcery, kteréžto nepoznaly muže; vyvedu je nyní k vám, čiňte s nimi, jak se vám líbí; toliko mužům těmto nic nečiňte, poněvadž vešli pod stín střechy mé.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 9, 'I řekli: Odejdi tam! A mluvili: Sám se dostal sem pohostinu, a chce nás souditi? Nyní tobě hůř uděláme, než jim. I obořili se násilně na muže toho, totiž na Lota, a přistoupili, aby vylomili dvéře.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 10, 'Tedy muži ti vztáhli ven ruku svou, a uvedli Lota k sobě do domu, a dvéře zavřeli.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 11, 'A ty muže, kteříž byli přede dveřmi domu, ranili slepotou velikou, od nejmenšího až do největšího, tak že ustali, hledajíce dveří.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 12, 'I řekli muži k Lotovi: Máš-li ještě zde koho, buď zetě neb syny své, neb dcery své, i všecko, což máš v městě, vyveď z místa tohoto.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 13, 'Nebo zkazíme místo toto, proto že se velmi rozmohl křik jejich před Hospodinem, a poslal nás Hospodin, abychom zkazili je.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 14, 'Vyšed tedy Lot, mluvil k zeťům svým, kteříž již měli pojímati dcery jeho, a řekl: Vstaňte, vyjděte z místa tohoto, nebo zkazí Hospodin město toto. Ale zdálo se zeťům jeho, jako by žertoval.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 15, 'A když zasvitávalo, nutili andělé Lota, řkouce: Vstaň, vezmi ženu svou a dvě dcery své, kteréž tu jsou, abys nezahynul v pomstě města.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 16, 'A když prodléval, chopili muži ruku jeho, a ruku ženy jeho, a ruku dvou dcer jeho, nebo se slitoval nad ním Hospodin; i vyvedli jej, a pustili za městem.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 17, 'A stalo se, když je vedli ven, řekl jeden: Zachovejž život svůj, neohlédej se zpět, ani se zastavuj na vší této rovině; ujdi na horu, abys nezahynul.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 18, 'I řekl jim Lot: Ne tak, prosím, páni moji.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 19, 'Aj, nyní nalezl služebník tvůj milost před očima tvýma, a veliké jest milosrdenství tvé, kteréž jsi učinil se mnou, když jsi zachoval duši mou; ale jáť nebudu moci ujíti na tu horu, aby mne nepostihlo to zlé, a umřel bych.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 20, 'Hle, teď jest toto město blízko, do něhož bych utekl, a toť jest malé; prosím, nechť tam ujdu; však pak neveliké jest, a živa bude duše má.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 21, 'I řekl k němu: Aj, uslyšel jsem žádost tvou i v této věci, abych nepodvrátil města toho, o němž jsi mluvil.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 22, 'Pospěšiž, ujdi tam; neboť nebudu moci učiniti ničehož, dokudž tam nedojdeš. A z té příčiny nazváno jest jméno města toho Ségor.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 23, 'Slunce vzcházelo nad zemi, když Lot všel do Ségor.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 24, 'A Hospodin dštil na Sodomu a na Gomoru sirou a ohněm od Hospodina s nebe.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 25, 'A podvrátil ta města i všecku tu rovinu, všecky také obyvatele těch měst, i všecko, což roste z země.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 26, 'I ohlédla se žena jeho, jduc za ním, a obrácena jest v sloup solný.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 27, 'Vstav pak Abraham ráno, pospíšil k místu tomu, kdež byl stál před Hospodinem.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 28, 'A pohleděv k Sodomě a Gomoře, i na všecku zemi té roviny, uzřel, a aj, vystupoval dým z země té, jako dým z vápenice.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 29, 'Stalo se tedy, když kazil Bůh města té roviny, že se rozpomenul Bůh na Abrahama, a vytrhl Lota z prostředku podvrácení, když podvracel města, v nichž bydlil Lot.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 30, 'Potom vyšel Lot z Ségor, a bydlil na hoře té, a obě dvě dcery jeho s ním; nebo nesměl bydliti v Ségor. I bydlil v jeskyni s oběma dcerami svými.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 31, 'I řekla prvorozená k mladší: Otec náš jest již starý, a není žádného muže na zemi, ješto by všel k nám podlé obyčeje vší země.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 32, 'Poď, dejme píti otci našemu vína, a spěme s ním, abychom zachovaly z otce našeho símě.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 33, 'I daly píti otci svému vína té noci; a všedši prvorozená, spala s otcem svým, kterýžto necítil, ani když lehla, ani když vstala.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 34, 'Nazejtří pak řekla prvorozená k mladší: Aj, spala jsem včerejší noci s otcem svým; dejme mu píti vína ještě této noci; potom vejduc, spi s ním, a zachovejme símě z otce našeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 35, 'I daly píti ještě té noci otci svému vína; a vstala ta mladší, a spala s ním; on pak necítil, ani když ona lehla, ani když vstala.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 36, 'A tak počaly obě dcery Lotovy z otce svého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 37, 'I porodila prvorozená syna, a nazvala jméno jeho Moáb; onť jest otec Moábských až do dnešního dne.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 38, 'I mladší také porodila syna, a nazvala jméno jeho Ben Ammon; onť jest otcem Ammonitských až do dnešního dne.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 1, 'Odtud bral se Abraham do země polední, aby bydlil mezi Kádes a Sur; i byl pohostinu v Gerar;');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 2, 'Kdežto pravil Abraham o Sáře manželce své: Sestra má jest. Tedy poslav Abimelech, král Gerarský, vzal Sáru.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 3, 'Ale přišed Bůh k Abimelechovi ve snách v noci, řekl jemu: Aj, ty již umřeš pro ženu, kterouž jsi vzal, poněvadž jest vdaná za muže.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 4, 'Abimelech pak nepřiblížil se k ní; protož řekl: Pane, zdaž také spravedlivý národ zabiješ?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 5, 'Zdaliž mi sám nepravil: Sestra má jest? A ona též pravila: Bratr můj jest. V upřímnosti srdce svého a v nevinnosti rukou svých učinil jsem to.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 6, 'I řekl jemu Bůh ve snách: Jáť také vím, že v upřímnosti srdce svého učinil jsi to, a já také zdržel jsem tě, abys nezhřešil proti mně; protož nedalť jsem se jí dotknouti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 7, 'Nyní tedy, navrať ženu muži tomu; nebo prorok jest, a modliti se bude za tebe, a živ budeš. Pakli jí nenavrátíš, věz, že smrtí umřeš ty i všecko, což tvého jest.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 8, 'A vstav Abimelech ráno, svolal všecky služebníky své, a vypravoval všecka slova ta v uši jejich. I báli se ti muži velmi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 9, 'Potom povolav Abimelech Abrahama, řekl jemu: Co jsi nám to učinil? A co jsem zhřešil proti tobě, že jsi uvedl na mne a na království mé hřích veliký? Učinils mi, čehož jsi učiniti neměl.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 10, 'A řekl opět Abimelech Abrahamovi: Cos myslil, žes takovou věc učinil?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 11, 'Odpověděl Abraham: Řekl jsem: Jistě že není bázně Boží na místě tomto, a zabijí mne pro ženu mou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 12, 'A také v pravdě jest sestra má, dcera otce mého, však ne dcera matky mé; a pojal jsem ji sobě za manželku.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 13, 'Když pak vyvedl mne Bůh z domu otce mého, abych pohostinu bydlil, tedy řekl jsem jí: Toto mi dobrodiní učiníš: Na každém místě, kamž půjdeme, prav o mně: Bratr můj jest.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 14, 'Tedy vzav Abimelech ovce a voly, služebníky také a děvky, dal je Abrahamovi; a navrátil mu Sáru manželku jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 15, 'A řekl Abimelech: Aj, země má před tebou; kdežť se koli příhodné býti vidí, tu přebývej.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 16, 'Sáře pak řekl: Aj, dal jsem tisíc stříbrných bratru tvému, hle, onť jest tobě zástěrou očí u všech, kteříž jsou s tebou. A všemi těmito věcmi Sára poučena byla.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 17, 'I modlil se Abraham Bohu, a uzdravil Bůh Abimelecha, a ženu jeho, a děvky jeho; i rodily.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 18, 'Nebo byl zavřel Hospodin každý život ženský v domě Abimelechově, pro Sáru manželku Abrahamovu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 1, 'Navštívil pak Hospodin Sáru, tak jakž byl řekl; a učinil Hospodin Sáře, jakož byl mluvil.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 2, 'Nebo počala a porodila Sára Abrahamovi syna v starosti jeho, v ten čas, kterýž předpověděl Bůh.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 3, 'A nazval Abraham jméno syna svého, kterýž se mu narodil, jehož porodila Sára, Izák.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 4, 'A obřezal Abraham syna svého Izáka, když byl v osmi dnech, tak jakž mu byl přikázal Bůh.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 5, 'Byl pak Abraham ve stu letech, když se mu narodil Izák syn jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 6, 'I řekla Sára: Radost mi učinil Bůh; kdokoli uslyší, radovati se bude spolu se mnou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 7, 'A přidala: Kdo by byl řekl Abrahamovi, že bude Sára děti kojiti? A však jsem porodila syna v starosti jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 8, 'I rostlo dítě a ostaveno jest. Tedy učinil Abraham veliké hody v ten den, v němž ostaven byl Izák.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 9, 'Viděla pak Sára, že syn Agar Egyptské, kteréhož porodila Abrahamovi, jest posměvač.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 10, 'I řekla Abrahamovi: Vyvrz děvku tuto i syna jejího; neboť nebude dědicem syn děvky té s synem mým Izákem.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 11, 'Ale Abraham velmi těžce nesl tu řeč, pro syna svého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 12, 'I řekl Bůh Abrahamovi: Nestěžuj sobě o dítěti a o děvce své; cožkoli řekla tobě Sára, povol řeči její, nebo v Izákovi nazváno bude tobě símě.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 13, 'A však i syna děvky učiním v národ; nebo tvé símě jest.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 14, 'Vstal tedy Abraham velmi ráno, a vzav chléb a láhvici vody, dal Agar a vložil na rameno její, a pustil ji od sebe i s dítětem. Kterážto odešla a chodila po poušti Bersabé.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 15, 'A když nebylo vody v láhvici, povrhla dítě pod jedním stromem.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 16, 'A odšedši, sedla naproti tak daleko, jako by mohl z lučiště dostřeliti; nebo pravila: Nebudu se dívati na smrt dítěte. Seděla tedy naproti, a pozdvihši hlasu svého, plakala.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 17, 'I uslyšel Bůh hlas dítěte; a anděl Boží s nebe zavolal na Agar, a řekl jí: Coť jest, Agar? Neboj se; nebo Bůh uslyšel hlas dítěte z místa, na kterémž jest.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 18, 'Vstaň, vezmi dítě, a ujmi je rukou svou; nebo v národ veliký učiním je.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 19, 'A otevřel Bůh oči její, aby uzřela studnici vody. I šla a naplnila láhvici vodou, a napojila dítě.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 20, 'A Bůh byl s dítětem, kteréžto zrostlo a bydlilo na poušti, a byl z něho střelec.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 21, 'Bydlil pak na poušti Fáran; i vzala mu matka jeho ženu z země Egyptské.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 22, 'Stalo se pak toho času, že mluvil Abimelech a Fikol, kníže vojska jeho, k Abrahamovi těmito slovy: Bůh s tebou jest ve všech věcech, kteréž ty činíš.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 23, 'Protož nyní, přisáhni mi teď skrze Boha: Toto ať se stane, jestliže mi sklamáš, neb synu mému, aneb vnuku mému; vedlé milosrdenství, kteréž jsem já učinil s tebou, i ty že učiníš se mnou a s zemí, v níž jsi byl pohostinu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 24, 'I řekl Abraham: A já přisáhnu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 25, '(A přitom domlouval se Abraham na Abimelecha o studnici vody, kterouž mu mocí odjali služebníci Abimelechovi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 26, 'I řekl Abimelech: Nevím, kdo by učinil takovou věc; a aniž jsi ty mi oznámil, aniž jsem já také co slyšel, až dnes.)');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 27, 'Vzav tedy Abraham ovce i voly dal Abimelechovi; a vešli oba dva v smlouvu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 28, 'A postavil Abraham sedm jehnic stáda obzvlášť.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 29, 'I řekl Abimelech Abrahamovi: K čemu jest těchto sedm jehnic, kteréž jsi postavil obzvlášť?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 30, 'Odpověděl: Že sedm těch jehnic vezmeš z ruky mé, aby mi to bylo na svědectví, že jsem kopal studnici tuto.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 31, 'Pročež nazváno jest to místo Bersabé, že tu oba dva přisáhli.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 32, 'A tak učinili smlouvu v Bersabé. Vstav pak Abimelech a Fikol, kníže vojska jeho, navrátili se do země Filistinské.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 33, 'I nasázel stromoví v Bersabé, a vzýval tam jméno Hospodina, Boha silného, věčného.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 34, 'A bydlil Abraham v zemi Filistinské za mnoho dní.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 1, 'Když pak ty věci pominuly, zkusil Bůh Abrahama, a řekl k němu: Abrahame! Kterýžto odpověděl: Teď jsem.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 2, 'I řekl: Vezmi nyní syna svého, toho jediného svého, kteréhož miluješ, Izáka, a jdi do země Moria; a obětuj ho tam v obět zápalnou na jedné hoře, o níž povím tobě.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 3, 'Tedy vstav Abraham velmi ráno, osedlal osla svého a vzal dva služebníky své s sebou, a Izáka syna svého; a nasekav dříví k oběti zápalné, vstal a bral se k místu, o němž pověděl mu Bůh.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 4, 'Třetího pak dne pozdvihl Abraham očí svých, a uzřel to místo zdaleka.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 5, 'A řekl Abraham služebníkům svým: Pozůstaňte vy tuto s oslem, já pak a dítě půjdeme tamto; a pomodlíce se, navrátíme se k vám.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 6, 'Tedy vzal Abraham dříví k zápalné oběti, a vložil je na Izáka syna svého; sám pak nesl v ruce své oheň a meč. I šli oba spolu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 7, 'Mluvě pak Izák Abrahamovi otci svému, řekl: Otče můj! Kterýž odpověděl: Co chceš, synu můj? A řekl: Aj, teď oheň a dříví, a kdež hovádko k zápalné oběti?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 8, 'Odpověděl Abraham: Bůh opatří sobě hovádko k oběti zápalné, synu můj. A šli předce oba spolu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 9, 'A když přišli k místu, o němž mu byl mluvil Bůh, udělal tu Abraham oltář, a srovnal dříví; a svázav syna svého, vložil ho na oltář na dříví.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 10, 'I vztáhl Abraham ruku svou, a vzal meč, aby zabil syna svého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 11, 'Tedy zavolal na něho anděl Hospodinův s nebe a řekl: Abrahame, Abrahame! Kterýžto odpověděl: Aj, já.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 12, 'I řekl jemu: Nevztahuj ruky své na dítě, aniž mu co čiň; neboť jsem již poznal, že se Boha bojíš, když jsi neodpustil synu svému, jedinému svému pro mne.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 13, 'A pozdvih Abraham očí svých, viděl, a hle, skopec za ním vězel v trní za rohy své. I šel Abraham a vzal skopce toho, a obětoval jej v obět zápalnou místo syna svého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 14, 'A nazval Abraham jméno místa toho: Hospodin opatří. Odkudž říká se do dnes: Na hoře Hospodinově opatří se.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 15, 'Zvolal pak anděl Hospodinův na Abrahama podruhé s nebe,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 16, 'A řekl: Skrze sebe samého přisáhl jsem, praví Hospodin, poněvadž jsi učinil tu věc, že jsi neodpustil synu svému, jedinému svému:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 17, 'Požehnám velmi tobě, a velice rozmnožím símě tvé jako hvězdy nebeské, a jako písek, kterýž jest na břehu mořském; nadto dědičně vládnouti bude símě tvé branami nepřátel svých.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 18, 'Ano požehnáni budou v semeni tvém všickni národové země, proto že jsi uposlechl hlasu mého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 19, 'Tedy navrátil se Abraham k služebníkům svým; a vstavše, šli spolu do Bersabé; nebo bydlil Abraham v Bersabé.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 20, 'A když se tyto věci staly, zvěstováno jest Abrahamovi v tato slova: Aj, porodila také Melcha syny Náchorovi, bratru tvému:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 21, 'Husa prvorozeného svého, a Buza bratra jeho, a Chamuele, otce Aramova;');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 22, 'A Kazeda a Azana, a Feldasa, a Jidlafa i Bathuele.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 23, 'Bathuel pak zplodil Rebeku. Osm těchto porodila Melcha Náchorovi, bratru Abrahamovu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 24, 'Ale i ženina jeho, jejíž jméno bylo Réma, porodila také ona Tábe a Gahama, Thása a Máchu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 1, 'Živa pak byla Sára sto a sedmmecítma let; ta jsou léta života Sáry.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 2, 'A umřela v městě Arbe, kteréž slove Hebron, v zemi Kananejské. I přišel Abraham, aby kvílil nad Sárou, a plakal jí.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 3, 'Potom vstav Abraham od mrtvého svého, mluvil k synům Het, řka:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 4, 'Hostem a příchozím jsem u vás; dejte mi místo ku pohřbu u vás, abych pochoval mrtvého svého od tváři své.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 5, 'A odpovídajíce synové Het Abrahamovi, řekli jemu:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 6, 'Slyš nás, pane milý! Kníže Boží jsi u prostřed nás, v nejpřednějších hrobích našich pochovej mrtvého svého; žádný z nás hrobu svého nebude zbraňovati tobě, abys neměl pochovati v něm mrtvého svého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 7, 'Abraham pak vstav, poklonil se lidu země té, totiž synům Het.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 8, 'A mluvil s nimi, řka: Jestliže se vám líbí, abych pochoval mrtvého svého od tváři své, slyšte mne, a přimluvte se za mne k Efronovi synu Sohar,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 9, 'Ať mi dá jeskyni Machpelah, kterouž má na konci pole svého; za slušné peníze ať mi ji dá u prostřed vás, k dědičnému pohřbu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 10, '(Ten pak Efron seděl u prostřed synů Het.) Tedy odpověděl Efron Hetejský Abrahamovi při přítomnosti synů Het, přede všemi, kteříž vcházejí do brány města jeho, řka:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 11, 'Nikoli, pane můj, ale slyš mne: Pole to dávám tobě, dávámť také i jeskyni, kteráž na něm jest; před očima synů lidu svého dávám ji tobě; pochovejž mrtvého svého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 12, 'Tedy poklonil se Abraham před lidem země té,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 13, 'A mluvil k Efronovi v přítomnosti lidu země, řka: A však jestliže ty jsi ten, prosím, vyslyš mne! Dámť stříbro za pole, vezmi je ode mne, a pochovám mrtvého svého tam.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 14, 'A odpovídaje Efron Abrahamovi, řekl jemu:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 15, 'Můj pane, poslechni mne: Země ta za čtyři sta lotů stříbrných jest; ale mezi mnou a tebou co jest o to? Mrtvého svého pochovej.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 16, 'I uposlechl Abraham Efrona, a odvážil mu stříbra, jakž oznámil při přítomnosti synů Het, čtyři sta lotů stříbrných, běžných mezi kupci.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 17, 'A odvedeno jest pole Efronovo, kteréž bylo v Machpelah, proti Mamre, pole a jeskyně na něm, a všecko stromoví, což ho na tom poli i na všech mezech jeho vůkol,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 18, 'Abrahamovi v držení, před očima synů Het, a všech, kteříž vcházejí do brány města toho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 19, 'A potom pochoval Abraham Sáru, manželku svou, v jeskyni pole Machpelah, proti Mamre, (to slove Hebron), v zemi Kananejské.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 20, 'Protož odevzdáno jest pole to i jeskyně, kteráž byla na něm, Abrahamovi k dědičnému pohřbu od synů Het.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 1, 'Abraham pak již byl starý a sešlého věku; a Hospodin požehnal mu ve všech věcech.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 2, 'Tedy řekl Abraham služebníku svému staršímu v domě svém, kterýž spravoval všecky věci jeho: Vlož nyní ruku svou pod bedro mé,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 3, 'Abych tě zavázal přísahou skrze Hospodina, Boha nebe a Boha země, abys nebral manželky synu mému ze dcer Kananejských, mezi nimiž já bydlím.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 4, 'Ale půjdeš do země mé a příbuznosti mé; a odtud vezmeš manželku synu mému Izákovi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 5, 'I řekl jemu služebník ten: Kdyby pak nechtěla žena ta se mnou jíti do země této, mám-li zase uvésti syna tvého do země, z níž jsi vyšel?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 6, 'Kterýžto odpověděl: Hleď, abys zase neuvodil syna mého tam.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 7, 'Hospodin Bůh nebe, kterýž vzal mne z domu otce mého a z vlasti mé, a mluvil mi, a kterýž mi přisáhl, řka: Semeni tvému dám zemi tuto, onť pošle anděla svého před tebou, a vezmeš manželku synu mému odtud.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 8, 'Jestliže by pak žena ta nechtěla jíti s tebou, svoboden budeš od této přísahy mé; toliko syna mého neuvoď tam zase.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 9, 'Tedy vložil služebník ten ruku svou pod bedro Abrahama, pána svého, a přisáhl jemu na tu řeč.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 10, 'A vzal služebník ten deset velbloudů z velbloudů pána svého, aby se bral; (nebo měl všecken statek pána svého v rukou svých.) I vstav, bral se k Aram Naharaim do města Náchor.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 11, 'A zastavil se s velbloudy před městem, u studnice vody k večerou, času toho, když vycházejí vážiti vody.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 12, 'A řekl: Hospodine, Bože pána mého Abrahama, dejž, prosím, ať se potká se mnou dnes to, čehož hledám; a učiň milosrdenství se pánem mým Abrahamem.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 13, 'Aj, já stojím u studnice vody, a dcery mužů města tohoto vycházejí, aby vážily vodu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 14, 'Děvečka tedy, kteréž bych řekl: Nachyl medle věderce svého, ať se napiji, a ona by řekla: Pí, také i velbloudy tvé napojím, ta aby byla, kterouž jsi způsobil služebníku svému Izákovi; a po tomť poznám, že jsi milosrdenství učinil se pánem mým.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 15, 'I stalo se prvé, než on přestal mluviti, aj, Rebeka, kteráž se narodila Bathuelovi, synu Melchy, manželky Náchora bratra Abrahamova, vycházela, a věderce její bylo na rameni jejím.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 16, 'A byla děvečka na pohledění velmi krásná, panna, a muž nepoznal jí; kterážto sešla k studnici té, a naplnivši věderce své, šla vzhůru.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 17, 'Tedy běžel služebník ten proti ní, a řekl: Dej mi píti, prosím, maličko vody z věderce svého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 18, 'I řekla: Napí se, pane můj. A rychle složila věderce své na ruku svou a dala mu píti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 19, 'A davši mu píti, řekla: Také velbloudům tvým navážím, dokudž se nenapijí.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 20, 'Tedy rychle vylila z věderce svého do koryta, a běžela ještě k studnici, aby vážila vodu; a vážila všechněm velbloudům jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 21, 'Muž pak ten s užasnutím divil se jí mlče, rozjímaje, aby zvěděl, zdařil-li Hospodin cestu jeho, čili nic.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 22, 'I stalo se, když přestali píti velbloudové, vyňav muž náušnici zlatou, ztíží půl lotu, a dvě náramnice, dal na ruce její, kteréž vážily deset lotů zlata.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 23, 'A řekl: Čí jsi dcera? Pověz mi, prosím, jest-li v domě otce tvého nám místo, kdež bychom přes noc zůstali?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 24, 'Jemužto odpověděla: Dcera jsem Bathuele, syna Melchy, kteréhož porodila Náchorovi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 25, 'Řekla ještě k němu: Slámy také a potravy hojně u nás jest, ano i místo, kdež byste přes noc zůstali.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 26, 'Tedy skloniv hlavu, poklonu učinil Hospodinu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 27, 'A řekl: Požehnaný Hospodin, Bůh pána mého Abrahama, kterýž neodjal milosrdenství svého a pravdy své od pána mého, mne také na cestě vedl Hospodin k domu bratří pána mého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 28, 'I běžela děvečka, a oznámila v domě matky své tak, jakž se stalo.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 29, 'A měla Rebeka bratra, jménem Lábana; ten běžel k muži tomu ven k studnici.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 30, 'Nebo uzřev náušnici a náramnice na rukou sestry své, a slyšev slova Rebeky sestry své, ana praví: Tak mluvil ke mně člověk ten, přišel k muži, a on stál při velbloudích u studnice.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 31, 'Jemuž řekl: Vejdi, požehnaný Hospodinův. Proč bys stál vně, kdyžť jsem připravil dům a místo velbloudům?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 32, 'Tedy všel muž ten do domu, a odsedlal velbloudy, a dal Lában slámy a potravy velbloudům, i vody k umytí noh jeho a noh mužů těch, kteří s ním byli.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 33, 'A položil předeň chléb, aby jedl. Ale on řekl: Nebudu jísti, dokudž nevypravím řečí svých. I řekl Lában: Mluv.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 34, 'Tedy řekl: Služebník Abrahamův jsem já.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 35, 'A Hospodin požehnal pánu mému velice, tak že veliký učiněn jest; nebo dal mu ovce a voly, stříbro a zlato, služebníky a děvky, velbloudy a osly.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 36, 'A porodila Sára, manželka pána mého, pánu mému v starosti své syna, jemuž dal, cožkoli má.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 37, 'I zavázal mne přísahou pán můj, řka: Nevezmeš manželky synu mému ze dcer Kananejských, v jejichž zemi já bydlím.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 38, 'Ale k domu otce mého půjdeš, a k rodině mé, a odtud vezmeš manželku synu mému.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 39, 'A když jsem řekl pánu svému: Snad nepůjde žena ta se mnou?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 40, 'Odpověděl mi: Hospodin, před jehož oblíčejem ustavičně jsem chodil, pošle anděla svého s tebou, a šťastnou způsobí cestu tvou, a vezmeš manželku synu mému z rodiny mé, a z domu otce mého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 41, 'A budeš svoboden od přísahy mé, když bys přišel k rodině mé; a jestliže by nedali tobě, budeš prost od přísahy mé.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 42, 'Protož dnes přišed k studnici, řekl jsem: Hospodine, Bože pána mého Abrahama, jestliže ty nyní šťastně spravuješ cestu mou, po níž já jdu,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 43, 'Aj, já stojím u studnice vody; protož, nechžť panna, kteráž vyjde vážiti vody, když bych jí řekl: Dej mi píti nyní maličko vody z věderce svého,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 44, 'A ona by mi odpověděla: I ty pí, i velbloudům tvým také navážím, ta ať jest manželka, kterouž způsobil Hospodin synu pána mého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 45, 'Prvé pak než jsem já přestal mluviti v srdci svém, aj, Rebeka vycházela mající věderce své na rameni svém, a sšedši k studnici, vážila. I řekl jsem jí: Prosím, dej mi píti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 46, 'Ona pak rychle složila věderce své s sebe, a řekla: Pí, také i velbloudy tvé napojím. Tedy pil jsem, a napojila také velbloudy.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 47, 'I ptal jsem se jí, a řekl jsem: Čí jsi dcera? Ona odpověděla: Dcera Bathuele, syna Náchorova, jehož mu porodila Melcha. Tedy dal jsem náušnici na tvář její, a náramnice na ruce její.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 48, 'A skloniv hlavu, poklonu jsem učinil Hospodinu, a dobrořečil jsem Hospodina, Boha pána mého Abrahama, kterýž vedl mne po cestě přímé, abych dceru bratra pána svého vzal synu jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 49, 'Protož nyní, činíte-li milosrdenství, a pravdu se pánem mým, oznamte mi; pakli nic, také mi oznamte, a obrátím se na pravo neb na levo.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 50, 'Tedy odpověděli Lában a Bathuel, řkouce: Od Hospodina vyšla jest věc tato; nemůžemeť odepříti v ničemž.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 51, 'Aj, Rebeka před tebou, vezmiž ji a jeď; a nechť jest manželkou synu pána tvého, jakož mluvil Hospodin.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 52, 'I stalo se, že jakž uslyšel služebník Abrahamův slova jejich, poklonil se Hospodinu až k zemi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 53, 'A vyňav služebník ten nádoby stříbrné a nádoby zlaté a oděv, dal Rebece; drahé také dary dal bratru jejímu a matce její.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 54, 'Tedy jedli a pili, on i muži, kteříž byli s ním, a zůstali tu přes noc. Ráno pak když vstali, řekl: Propusťte mne ku pánu mému.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 55, 'I odpověděl bratr její a matka: Nechať pozůstane děvečka s námi za některý den, aspoň za deset; potom půjdeš.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 56, 'On pak řekl jim: Nezdržujte mne, poněvadž Hospodin šťastnou způsobil cestu mou; propusťtež mne, ať jdu ku pánu svému.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 57, 'I řekli: Zavolejme děvečky a zeptejme se, co dí k tomu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 58, 'Tedy zavolali Rebeky, a řekli jí: Chceš-li jíti s mužem tímto? I řekla: Půjdu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 59, 'A propouštějíce Rebeku sestru svou a chovačku její, služebníka také Abrahamova s muži jeho,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 60, 'Požehnali Rebeky a mluvili jí: Sestro naše, ty buď v tisíce tisíců, a símě tvé dědičně obdrž brány nepřátel svých.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 61, 'Tedy vstala Rebeka a děvečky její, a vsedše na velbloudy, jely za mužem tím. A tak vzal služebník ten Rebeku, a odjel.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 62, 'Izák pak šel, navracuje se od studnice Živého vidoucího mne; nebo bydlil v zemi polední.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 63, 'A vyšel Izák k přemyšlování na pole, když se chýlilo k večerou; a pozdvih očí svých, uzřel, an velbloudové jdou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 64, 'Pozdvihla také Rebeka očí svých, a uzřevši Izáka, ssedla s velblouda.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 65, '(Nebo řekla byla služebníku: Kdo jest ten muž, kterýž jde po poli proti nám? Odpověděl služebník: To jest pán můj.) I vzala rouchu, a přistřela se.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 66, 'Tedy vypravoval služebník Izákovi vše, což působil.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 67, 'I uvedl ji Izák do stanu Sáry matky své, a vzal Rebeku, a měl ji za manželku, a miloval ji. I potěšil se Izák po smrti matky své.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 1, 'Abraham pak opět pojal ženu jménem Ceturu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 2, 'Kterážto porodila jemu Zamrana, a Jeksana, a Madana, a Madiana, Jezbocha a Suecha.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 3, 'Jeksan potom zplodil Sábu a Dedana. Synové pak Dedanovi byli: Assurim, a Latuzim, a Laomin.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 4, 'Ale synové Madianovi: Efa, a Efer, a Enoch, a Abida, a Helda; všickni ti synové byli Cetury.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 5, 'I dal Abraham Izákovi všecko, což měl.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 6, 'Synům pak ženin svých dal Abraham dary, a odeslal je od Izáka syna svého, ještě živ jsa, k východu do země východní.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 7, 'Tito pak jsou dnové let života Abrahamova, v nichž byl živ: Sto sedmdesáte a pět let.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 8, 'I skonal a umřel Abraham v starosti dobré, stár jsa a plný dnů; a připojen jest k lidu svému.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 9, 'Tedy pochovali ho Izák a Izmael synové jeho v jeskyni Machpelah, na poli Efrona, syna Sohar Hetejského, naproti Mamre,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 10, 'Na tom poli, kteréž byl koupil Abraham od synů Het; tu pochován jest Abraham i Sára manželka jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 11, 'Po smrti pak Abrahamově požehnal Bůh Izákovi synu jeho, a bydlil Izák u studnice Živého vidoucího mne.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 12, 'Tito jsou pak rodové Izmaele syna Abrahamova, jehož porodila Agar Egyptská, děvka Sářina, Abrahamovi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 13, 'A tato jsou jména synů Izmaelových, jimiž se jmenují po rodech svých: Prvorozený Izmaelův Nabajot, po něm Cedar, a Adbeel a Mabsan,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 14, 'A Masma, a Dumah a Massa,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 15, 'Hadar a Tema, Jetur, Nafis a Cedma.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 16, 'Ti jsou synové Izmaelovi, a ta jména jejich, po vsech jejich, a po městech jejich, dvanáctero knížat po čeledech jejich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 17, '(Bylo pak života Izmaelova sto třidceti a sedm let, i skonal; a umřev, připojen jest k lidu svému.)');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 18, 'A bydlili od Hevilah až do Sur, jenž jest proti Egyptu, když jdeš do Assyrie; před tváří všech bratří svých položil se.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 19, 'Tito jsou také rodové Izáka syna Abrahamova: Abraham zplodil Izáka.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 20, 'Byl pak Izák ve čtyřidcíti letech, když sobě vzal za manželku Rebeku, dceru Bathuele Syrského, z Pádan Syrské, sestru Lábana Syrského.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 21, 'I modlil se Izák pokorně Hospodinu za manželku svou; nebo byla neplodná. A uslyšel jej Hospodin; a tak počala Rebeka manželka jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 22, 'A když se děti potiskali v životě jejím, řekla: Má-liť tak býti, proč jsem já počala? Šla tedy, aby se otázala Hospodina.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 23, 'I řekl jí Hospodin: Dva národové jsou v životě tvém, a dvůj lid z života tvého se rozdělí; lid pak jeden nad druhý bude silnější, a větší sloužiti bude menšímu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 24, 'A když se naplnili dnové její, aby porodila, a aj, blíženci byli v životě jejím.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 25, 'I vyšel první ryšavý všecken, a jako oděv chlupatý; i nazvali jméno jeho Ezau.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 26, 'Potom pak vyšel bratr jeho, a rukou svou držel Ezau za patu; pročež nazváno jest jméno jeho Jákob. A byl Izák v šedesáti letech, když ona je porodila.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 27, 'A když dorostli ti děti, byl Ezau lovec umělý, chodě po polích; Jákob pak byl muž prostý a v staních bydlil.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 28, 'I byl Izák laskav na Ezau, proto že z lovu jeho míval pokrm; ale Rebeka laskava byla na Jákoba.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 29, 'Uvařil pak Jákob krmičku. Tedy Ezau přišel z pole zemdlený,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 30, 'A řekl Jákobovi: Dej mi, prosím, jísti krmě té červené, nebo jsem umdlel. (Protož nazváno jest jméno jeho Edom.)');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 31, 'Odpověděl Jákob: Prodej mi dnes hned prvorozenství své.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 32, 'I řekl Ezau: Aj, já k smrti se blížím, k čemuž mi tedy to prvorozenství?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 33, 'Dí Jákob: Přisáhni mi dnes hned. I přisáhl mu, a prodal prvorozenství své Jákobovi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 34, 'Tedy Jákob dal Ezauchovi chleba a té krmě z šocovice. Kterýžto jedl a pil, a vstav, odšel; a tak pohrdl Ezau prvorozenstvím.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 1, 'Byl pak opět hlad na zemi, mimo hlad první, kterýž byl za dnů Abrahamových. Tedy odebral se Izák k Abimelechovi králi Filistinskému do Gerar.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 2, 'Nebo ukázal se jemu Hospodin a řekl: Nesstupuj do Egypta; ale bydli v zemi, kterouž oznámím tobě.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 3, 'Budiž tedy pohostinu v zemi této, a budu s tebou, a požehnám tobě; nebo tobě a semeni tvému dám všecky země tyto, a utvrdím přísahu, kterouž jsem přisáhl Abrahamovi, otci tvému.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 4, 'Rozmnožím také símě tvé jako hvězdy nebeské, a dám semeni tvému všecky země tyto, a požehnáni budou v semeni tvém všickni národové země;');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 5, 'Protože uposlechl Abraham hlasu mého, a ostříhal nařízení mých, přikázaní mých, ustanovení mých a zákonů mých.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 6, 'Bydlil tedy Izák v Gerar.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 7, 'Ptali se pak muži místa toho o manželce jeho. Kterýžto odpověděl: Sestra má jest; nebo nesměl říci: Manželka má jest, mysle sobě: Aby mne nezabili muži místa toho pro Rebeku. Nebo byla krásná na pohledění.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 8, 'I přihodilo se, když již čas nějaký tam bydlil, že vyhlédal Abimelech král Filistinský z okna a uzřel Izáka, an pohrává s Rebekou manželkou svou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 9, 'Protož povolav Abimelech Izáka, řekl: Aj, v pravdě manželka tvá to jest. Jakž to, že jsi pravil: Sestra má jest? I odpověděl jemu Izák: Nebo jsem řekl sám u sebe: Abych snad neumřel pro ni.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 10, 'I řekl Abimelech: Což jsi to učinil nám? O málo, že by byl spal někdo z lidu s manželkou tvou, a ty byl bys uvedl na nás vinu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 11, 'I přikázal Abimelech všemu lidu, řka: Kdo by se dotkl člověka toho, aneb manželky jeho, smrtí umře.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 12, 'Sel pak Izák v zemi té, a shledal v tom roce sto měr; nebo požehnal mu Hospodin.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 13, 'I rostl muž ten, a prospíval vždy více v zrostu, až i zrostl velmi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 14, 'Nebo měl stáda ovcí i stáda volů, a čeledi mnoho; pročež záviděli mu Filistinští.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 15, 'A všecky studnice, kteréž vykopali služebníci otce jeho za dnů Abrahama otce jeho, zařítili Filistinští, zasypavše je prstí.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 16, 'I řekl Abimelech Izákovi: Odejdi od nás; nebo mnohem mocnější jsi než my.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 17, 'Tedy odšel odtud Izák, a rozbil stany v údolí Gerar, a bydlil tu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 18, 'A kopal zase Izák studnice vod, kteréž byli vykopali za dnů Abrahama otce jeho, a kteréž zařítili Filistinští po smrti Abrahamově; a nazval je těmi jmény, kterýmiž je jmenoval otec jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 19, 'I kopali služebníci Izákovi v tom údolí, a nalezli tam studnici vody živé.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 20, 'Vadili se pak pastýři Gerarští s pastýři Izákovými, pravíce: Naše jest voda. Pročež nazval jméno studnice té Esek, že se vadili s ním.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 21, 'Vykopali také jinou studnici, a nesnáz byla i o tu; pročež dal jí jméno Sitnah.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 22, 'I hnul se odtud, a kopal jinou studnici, o kterouž se nevadili; protož nazval jméno její Rehobot. Nebo řekl: Nyní uprostrannil nám Hospodin, a vzrostli jsme na zemi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 23, 'Vstoupil pak odtud do Bersabé.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 24, 'A ukázal se mu Hospodin v tu noc, a řekl: Já jsem Bůh Abrahama otce tvého; neboj se, nebo s tebou já jsem, a požehnám tobě, a rozmnožím símě tvé pro Abrahama služebníka svého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 25, 'I vzdělal tu oltář, a vzýval jméno Hospodinovo, a rozbil tu stan svůj; a služebníci Izákovi vykopali tam studnici.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 26, 'Abimelech pak přijel k němu z Gerar, a Ochozat, přítel jeho, a Fikol, kníže vojska jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 27, 'I řekl jim Izák: Z jaké příčiny přišli jste ke mně? Poněvadž vy nenáviděli jste mne, a vybyli jste mne od sebe.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 28, 'Kteřížto odpověděli: Patrně jsme to shledali, že jest Hospodin s tebou, i řekli jsme: Učiňme nyní přísahu mezi sebou, mezi námi a mezi tebou; a učiníme smlouvu s tebou:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 29, 'Že neučiníš nám nic zlého, jako i my nedotkli jsme se tebe, a jakž jsme my toliko dobře činili tobě, a propustili jsme tě v pokoji; ty nyní tedy povol tomu, požehnaný Hospodinův.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 30, 'Tedy učinil jim hody, i jedli a pili.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 31, 'A vstavše velmi ráno, přisáhli jeden druhému. I propustil je Izák, a oni odešli od něho v pokoji.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 32, 'Toho dne přišli služebníci Izákovi, a oznámili mu o studnici, kterouž kopali, řkouce: Nalezli jsme vodu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 33, 'I nazval ji Seba. Protož jméno města toho jest Bersabé až do dnešního dne.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 34, 'Ezau pak jsa v letech čtyřidcíti, pojal ženu Judit, dceru Béry Hetejského, a Bazematu, dceru Elona Hetejského.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 35, 'A kormoutily Izáka a Rebeku.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 1, 'Když se pak sstaral Izák, a pošly byly oči jeho, tak že neviděl, povolal Ezau syna svého staršího, a řekl jemu: Synu můj. Kterýžto odpověděl: Aj, teď jsem.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 2, 'I dí: Aj, já jsem se již sstaral, a nevím dne smrti své.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 3, 'Protož nyní vezmi medle nástroje své, toul svůj a lučiště své, a vyjda do pole, ulov mi zvěřinu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 4, 'A přistroj mi krmi chutnou, jakž já rád jídám, a přines mi, a budu jísti, aťby požehnala duše má, prvé než umru.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 5, '(Slyšela pak Rebeka, když mluvil Izák s Ezau synem svým.) I odšel Ezau na pole, aby ulovil zvěřinu a přinesl.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 6, 'Tedy řekla Rebeka Jákobovi synu svému takto: Aj, slyšela jsem, když otec tvůj mluvil k Ezau bratru tvému, a pravil:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 7, 'Přines mi něco z lovu, a přistroj mi krmě chutné, abych jedl, a požehnámť před Hospodinem, prvé než umru.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 8, 'Nyní tedy, synu můj, poslechni hlasu mého v tom, což já přikazuji tobě.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 9, 'Jdi medle k stádu, a odtud mi vezmi dva kozelce výborné, abych přistrojila z nich krmě chutné otci tvému, jakž on rád jídá.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 10, 'A přineseš otci svému, a on jísti bude, na to, aby požehnal tobě, prvé než umře.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 11, 'I řekl Jákob Rebece matce své: Víš, že Ezau bratr můj jest člověk chlupatý, a já jsem člověk hladký.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 12, 'Jestliže omaká mne otec můj, tedy zůstanu u něho za podvodného; a tak uvedu na sebe zlořečenství, a ne požehnání.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 13, 'Jemužto odpověděla matka: Nechť jest na mne zlořečenství tvé, synu můj; jen ty poslechni hlasu mého, a jdi, přines mi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 14, 'Tedy odšed, vzal, a přinesl matce své. I připravila matka jeho krmě chutné, jakž otec jeho rád jídal.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 15, 'A vzala Rebeka nejlepší šaty Ezau syna svého staršího, kteréž měla u sebe v domě, a oblékla Jákoba, syna svého mladšího.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 16, 'A kožkami kozelčími obvinula ruce jeho, a díl hladký hrdla jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 17, 'I dala chléb a krmě chutné, kteréž připravila, v ruce Jákoba syna svého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 18, 'A on přišed k otci svému, řekl: Otče můj! Kterýžto odpověděl: Aj, teď jsem. Kdož jsi ty, synu můj?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 19, 'I dí Jákob otci svému: Já jsem Ezau, prvorozený tvůj. Učinil jsem, jakž jsi mi poručil. Vstaň, prosím, sedni a jez z lovu mého, aby mi požehnala duše tvá.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 20, 'Tedy řekl Izák synu svému: Což to? Brzys to nalezl, synu můj. A on dí: Nebo Hospodin Bůh tvůj způsobil to, aby mi se pojednou nahodilo.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 21, 'I řekl Izák Jákobovi: Přistupiž, ať omakám tě, synu můj, ty-li jsi syn můj Ezau, či nejsi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 22, 'Tedy přistoupil Jákob k Izákovi otci svému; a on omakal ho, i řekl: Hlas jest hlas Jákobův, ale ruce tyto ruce Ezau.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 23, 'A nepoznal ho; nebo byly ruce jeho, jako ruce Ezau bratra jeho, chlupaté. I požehnal mu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 24, 'A řekl: Ty-liž jsi pak syn můj Ezau? Odpověděl: Já.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 25, 'I řekl: Podejž mi, ať jím z lovu syna svého, aby tobě požehnala duše má. Tedy podal mu, a on jedl. Přinesl mu také vína, a on pil.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 26, 'I řekl jemu Izák otec jeho: Přistupiž nyní, a polib mne, synu můj.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 27, 'I přistoupil a políbil ho. A jakž ucítil Izák vůni roucha jeho, požehnal mu, řka: Pohleď, vůně syna mého jest jako vůně pole, jemuž požehnal Hospodin.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 28, 'Dejž tobě Bůh z rosy nebeské, a z tučnosti zemské, i hojnost obilé a vína.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 29, 'Nechažť slouží tobě lidé, a sklánějí se před tebou národové. Budiž pánem bratří svých, a ať se sklánějí před tebou synové matky tvé. Kdož by zlořečili tobě, nechť jsou zlořečení, a kdo by dobrořečili tobě, požehnaní.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 30, 'A když přestal Izák požehnání dávati Jákobovi, a sotva že vyšel Jákob od Izáka otce svého, Ezau bratr jeho přišel z lovu svého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 31, 'A připraviv i on krmě chutné, přinesl otci svému a řekl mu: Nechžť vstane otec můj, a jí z lovu syna svého, aby mi požehnala duše tvá.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 32, 'I řekl jemu Izák otec jeho: Kdo jsi ty? Dí on: Já jsem syn tvůj, prvorozený tvůj Ezau.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 33, 'Tedy zhrozil se Izák hrůzou velikou náramně, a řekl: Kdo pak a kde jest ten, ješto uloviv zvěřinu, přinesl mi? A já jsem jedl ze všeho, prvé než jsi ty přišel, a požehnal jsem mu, a budeť požehnaným.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 34, 'Uslyšev Ezau slova otce svého, zkřikl hlasem velikým, a hořkostí naplněn jest náramně, a řekl otci svému: Požehnejž mně, i mně také, můj otče!');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 35, 'Kterýžto řekl: Přišel bratr tvůj podvodně a uchvátil požehnání tvé.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 36, 'Tedy řekl: Právětě nazváno jméno jeho Jákob; nebo již po dvakráte mne podvedl, prvorozenství mé odjal, a teď nyní uchvátil požehnání mé. Řekl ještě: Zdali jsi nezachoval i mně požehnání?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 37, 'Odpověděl Izák a řekl k Ezau: Aj, ustavil jsem ho pánem nad tebou, a všecky bratří jeho dal jsem mu za služebníky; obilím také a vínem opatřil jsem ho. Což tedy již tobě učiniti mohu, synu můj?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 38, 'I řekl Ezau otci svému: Zdaliž to jedno toliko máš požehnání, otče můj? Požehnejž mně, i mně také, můj otče! I povýšil Ezau hlasu svého a plakal.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 39, 'Tedy odpověděl Izák otec jeho, a řekl k němu: Aj, v tučnostech země bude bydlení tvé a v rose nebeské s hůry;');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 40, 'A v meči svém živ budeš, a bratru svému sloužiti budeš; ale přijde čas, že budeš panovati a svržeš jho jeho s šíje své.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 41, 'Protož v nenávisti měl Ezau Jákoba pro požehnání, jímž požehnal mu otec jeho, a řekl v srdci svém: Přiblížíť se dnové smutku otce mého, a zabiji Jákoba, bratra svého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 42, 'I oznámena jsou Rebece slova Ezau, staršího syna jejího. Pročež ona poslavši, povolala Jákoba syna svého mladšího, a řekla jemu: Hle, Ezau bratr tvůj těší se tím, že tě zabije.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 43, 'Protož nyní, synu můj, poslechni hlasu mého, a vstana, utec k Lábanovi, bratru mému do Cháran.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 44, 'A pobuď s ním za některý čas, až by se odvrátila prchlivost bratra tvého,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 45, 'A přestalo rozhněvání bratra tvého na tebe, a zapomenul by na to, což jsi mu učinil. Potom já pošli a vezmu tě odtud. Proč mám zbavena býti obou synů jednoho dne?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 46, 'I řekla Rebeka Izákovi: Stýště mi se živu býti pro dcery Het. Vezme-li Jákob ženu ze dcer Het, jako tyto jsou ze dcer země této, k čemu mi život?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 1, 'Povolal pak Izák Jákoba, a požehnal jemu, a přikázal mu, řka: Nepojímej ženy ze dcer Kananejských.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 2, 'Ale vstana, jdi do Pádan Syrské do domu Bathuele, otce matky své, a pojmi sobě odtud manželku ze dcer Lábana ujce svého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 3, 'A Bůh silný všemohoucí požehnejž tobě, a dejžť zrůst, a rozmnožiž tě, abys byl v zástup mnohého lidu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 4, 'A dejž tobě požehnání Abrahamovo, tobě i semeni tvému s tebou, abys dědičně obdržel zemi, v níž pohostinu jsi, kterouž dal Bůh Abrahamovi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 5, 'I odeslal Izák Jákoba, kterýžto šel do Pádan Syrské k Lábanovi synu Bathuele Syrského, bratru Rebeky matky Jákobovy a Ezau.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 6, 'Vida pak Ezau, že požehnání dal Izák Jákobovi, a že ho odeslal do Pádan Syrské, aby sobě odtud vzal manželku, a že, když mu požehnání dával, přikázal mu, řka: Nepojmeš ženy ze dcer Kananejských;');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 7, 'A že by uposlechl Jákob otce svého a matky své a odšel do Pádan Syrské;');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 8, 'Vida také Ezau, že dcery Kananejské těžké byly v očích Izákovi otci jeho:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 9, 'Tedy odšel Ezau k Izmaelovi, a mimo prvnější ženy své, pojal sobě za ženu Mahalat, dceru Izmaele, syna Abrahamova, sestru Nabajotovu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 10, 'Vyšed pak Jákob z Bersabé, šel do Cháran.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 11, 'I trefil na jedno místo, na kterémžto zůstal přes noc, (nebo slunce již bylo zapadlo,) a nabrav kamení na místě tom, položil pod hlavu svou, a spal na témž místě.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 12, 'I viděl ve snách, a aj, žebřík stál na zemi, jehožto vrch dosahal nebe; a aj, andělé Boží vstupovali a sstupovali po něm.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 13, 'A aj, Hospodin stál nad ním, a řekl: Já jsem Hospodin, Bůh Abrahama otce tvého, a Bůh Izákův; zemi tu, na kteréž ty spíš, tobě dám a semeni tvému.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 14, 'A bude símě tvé jako prach země; nebo rozmůžeš se k západu, i k východu, na půlnoci, i ku poledni; nad to požehnány budou v tobě všecky čeledi země, a v semeni tvém.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 15, 'A aj, já jsem s tebou, a ostříhati tě budu, kamžkoli půjdeš, a přivedu tě zase do země této; nebo neopustím tebe, až i učiním, což jsem mluvil tobě.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 16, 'Procítiv pak Jákob ze sna svého, řekl: V pravdě Hospodin jest na místě tomto, a já jsem nevěděl.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 17, '(Nebo zhroziv se, řekl: Jak hrozné jest místo toto! Není jiného,jediné dům Boží, a tu jest brána nebeská.)');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 18, 'Vstav pak Jákob ráno, vzal kámen, kterýž byl podložil pod hlavu svou, a postavil jej na znamení pamětné, a polil jej svrchu olejem.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 19, 'Protož nazval jméno místa toho Bethel, ješto prvé to město sloulo Lůza.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 20, 'Zavázal se také Jákob slibem, řka: Jestliže Bůh bude se mnou, a ostříhati mne bude na cestě této, kterouž já jdu; a dá-li mi chléb ku pokrmu a roucho k oděvu,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 21, 'A navrátím-li se v pokoji do domu otce svého, a bude mi Hospodin za Boha:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 22, 'Kámen tento, kterýž jsem postavil na památku, bude domem Božím; a ze všech věcí, kteréž mi dáš, desátky spravedlivě tobě dám.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 1, 'Tedy Jákob vstav, odšel do země východní.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 2, 'A pohleděv, uzřel studnici v poli a tři stáda ovcí, ana se složila při ní; nebo z té studnice napájeli stáda; a kámen veliký byl navrchu studnice.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 3, 'Shánívána pak tam bývala všecka stáda, a teprv odvalovali kámen ten od vrchu té studnice, a napájeli dobytky; potom zas přivalovali kámen na vrch studnice, na místo jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 4, 'Tedy řekl jim Jákob: Bratří moji, odkud jste? Kteřížto odpověděli: Jsme z Cháran.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 5, 'I řekl jim: Znáte-li Lábana, syna Náchorova? A oni řekli: Známe.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 6, 'I dí opět k nim: Dobře-li se má? Odpověděli: Dobře, a aj, Ráchel dcera jeho tamto jde s dobytkem.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 7, 'Tedy řekl: Však ještě daleko do večera, aniž ještě čas, aby dobytek byl sehnán; napojte stáda, a jděte, paste.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 8, 'A oni odpověděli: Nemůžeme, než až se všecka stáda seženou, a odvalen bude kámen od svrchku studnice, abychom napojili ovce.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 9, 'Když on ještě mluvil s nimi, přišla k tomu Ráchel s stádem otce svého; neb ona pásla stádo.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 10, 'Tedy Jákob uzřev Ráchel, dceru Lábana ujce svého, a stádo jeho, přistoupil a odvalil ten kámen od vrchu studnice, a napojil stádo Lábana ujce svého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 11, 'A políbil Jákob Ráchel, a povýšiv hlasu svého, plakal.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 12, 'Oznámil jí pak byl Jákob, že jest bratr otce jejího, a že jest syn Rebeky; a ona přiběhši, oznámila to otci svému.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 13, 'I stalo se, když Lában uslyšel pověst o Jákobovi, synu sestry své, že vyběhl proti němu, a objav ho, políbil, a uvedl do domu svého; on pak vypravoval Lábanovi o všech těch věcech.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 14, 'Jemužto odpověděl Lában: Jistě kost má a tělo mé jsi. I zůstal s ním přes celý měsíc.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 15, 'Tedy řekl Lában Jákobovi: Zdali proto, že jsi bratr můj, darmo mi sloužiti budeš? Pověz mi, jaká má býti mzda tvá?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 16, '(Měl pak Lában dvě dcery; jméno starší Lía, a jméno mladší Ráchel.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 17, 'Než Lía měla oči mdlé, ale Ráchel byla pěkné postavy a krásné tváři.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 18, 'I miloval Jákob Ráchel.) Řekl tedy: Buduť sloužiti sedm let za Ráchel, dceru tvou mladší.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 19, 'Odpověděl Lában: Lépeť jest, abych ji tobě dal, nežli bych ji dal muži jinému; zůstaniž se mnou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 20, 'Takž Jákob sloužil za Ráchel sedm let; a bylo před očima jeho jako něco málo dnů, proto že laskav byl na ni.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 21, 'Potom řekl Jákob k Lábanovi: Dejž mi ženu mou; nebo vyplněni jsou dnové moji, abych všel k ní.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 22, 'Tedy sezval Lában všecky muže místa toho, a učinil hody.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 23, 'U večer pak vzav Líu, dceru svou, uvedl ji k němu; a on všel k ní.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 24, 'Dal také Lában Zelfu děvku svou Líe, dceři své, za služebnici.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 25, 'A když bylo ráno, poznal, že jest Lía. I řekl k Lábanovi: Což jsi mi to učinil? Zdaliž jsem za Ráchel nesloužil u tebe? Pročežs mne tedy oklamal?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 26, 'Odpověděl Lában: Nebývá toho v kraji našem, aby vdávána byla mladší dříve, než prvorozená.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 27, 'Vyplň týden této; dámeť potom i tuto za službu, kterouž sloužiti budeš u mne ještě sedm let jiných.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 28, 'I udělal tak Jákob, a vyplnil týden její. Potom dal mu Ráchel dceru svou za manželku.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 29, 'Dal také Lában Ráchel, dceři své, Bálu, děvku svou za služebnici.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 30, 'Tedy všel také k Ráchel, a miloval ji více než Líu; i sloužil u něho ještě sedm let jiných.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 31, 'Vida pak Hospodin, že Lía nemá lásky, otevřel život její; a Ráchel nechal neplodné.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 32, 'Tedy počala Lía a porodila syna, a nazvala jméno jeho Ruben; nebo řekla: Jistě viděl Hospodin trápení mé; jižť nyní milovati mne bude muž můj.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 33, 'I počala opět a porodila syna, a řekla: Jistě uslyšel Hospodin, že jsem v nenávisti, protož dal mi i tohoto. A nazvala jméno jeho Simeon.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 34, 'A opět počala a porodila syna, a řekla: Již nyní připojí se ke mně muž můj, nebo jsem mu porodila tři syny. Z té příčiny nazváno jest jméno jeho Léví.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 35, 'I počala ještě a porodila syna, a řekla: Již nyní chváliti budu Hospodina. Pročež nazvala jméno jeho Juda; i přestala roditi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 1, 'Viduci pak Ráchel, že by nerodila Jákobovi, záviděla sestře své, a řekla Jákobovi: Dej mi syny; pakli nedáš, umru.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 2, 'Pročež rozhněval se velmi Jákob na Ráchel, a řekl: Zdali já jsem za Boha, kterýžť nedal plodu života?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 3, 'Řekla ona: Hle, děvka má Bála; vejdi k ní, aby rodila na kolena má, a budu míti já také syny z ní.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 4, 'I dala mu Bálu děvku svou za ženu; a všel k ní Jákob.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 5, 'Tedy počavši Bála, porodila Jákobovi syna.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 6, 'I řekla Ráchel: Soudil Bůh při mou, a uslyšel také hlas můj, a dal mi syna. Protož nazvala jméno jeho Dan.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 7, 'Opět počavši Bála, děvka Ráchel, porodila syna druhého Jákobovi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 8, 'I řekla Ráchel: Tuhé jsem odpory měla s sestrou svou, a všakť jsem přemohla. A nazvala jméno jeho Neftalím.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 9, 'Viduci pak Lía, že by přestala roditi, vzala Zelfu děvku svou, a dala ji Jákobovi za ženu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 10, 'A porodila Zelfa, děvka Líe, Jákobovi syna.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 11, 'Protož řekla Lía: Již přišel zástup. A nazvala jméno jeho Gád.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 12, 'Porodila také Zelfa děvka Líe syna druhého Jákobovi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 13, 'A řekla Lía: To na mé štěstí; nebo šťastnou mne nazývati budou ženy. A nazvala jméno jeho Asser.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 14, 'Vyšel pak Ruben v čas žně pšeničné, a nalezl pěkná jablečka na poli, a přinesl je Líe matce své. I řekla Ráchel Líe: Dej mi, prosím, těch jableček syna svého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 15, 'Jížto ona odpověděla: Máloť se snad zdá, že jsi vzala muže mého; chceš také užívati jableček syna mého? I řekla Ráchel: Nechažť tedy spí s tebou této noci za jablečka syna tvého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 16, 'Když pak navracoval se Jákob s pole večer, vyšla Lía proti němu, a řekla: Ke mně vejdeš; nebo ze mzdy najala jsem tě za jablečka syna svého. I spal s ní té noci.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 17, 'A uslyšel Bůh Líu; kterážto počala a porodila Jákobovi syna pátého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 18, 'I řekla Lía: Dal mi Bůh mzdu mou, i potom, když jsem dala děvku svou muži svému. Pročež nazvala jméno jeho Izachar.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 19, 'A počala opět Lía, a porodila šestého syna Jákobovi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 20, 'I řekla Lía: Obdařil mne Bůh darem dobrým; již nyní bydliti bude se mnou muž můj, nebo porodila jsem mu šest synů. A nazvala jméno jeho Zabulon.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 21, 'Potom porodila dceru; a nazvala jméno její Dína.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 22, 'A rozpomenuv se Bůh na Ráchel,uslyšel jí, a otevřel život její.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 23, 'Tedy počala a porodila syna, a řekla: Odjal Bůh pohanění mé.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 24, 'A nazvala jméno jeho Jozef, řkuci: Přidejž mi Hospodin syna jiného.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 25, 'Stalo se pak, když porodila Ráchel Jozefa, řekl Jákob Lábanovi: Propusť mne, ať odejdu na místo své a do země své.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 26, 'Dej mi ženy mé a dítky mé, za kteréž jsem sloužil tobě, ať odejdu; nebo ty znáš službu mou, kterouž jsem sloužil tobě.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 27, 'I řekl mu Lában: Jestliže nyní nalezl jsem milost před očima tvýma, zůstaň se mnou, nebo v skutku jsem poznal, že požehnal mi Hospodin pro tebe.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 28, 'Řekl také: Oznam mi ze jména mzdu svou a dámť ji.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 29, 'Jemužto odpověděl: Ty víš, jak jsem sloužil tobě, a jaký byl dobytek tvůj při mně.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 30, 'Nebo to málo, kteréž jsi měl přede mnou, zrostlo velmi, a požehnalť Hospodin, jakž jsem k tobě nohou vkročil. A nyní, kdy pak já své hospodářství opatrovati budu?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 31, 'A řekl: Coť mám dáti? Odpověděl Jákob: Nedávej mi nic. Jestliže mi učiníš toto, zase pásti budu a ostříhati dobytka tvého:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 32, 'Projdu skrze všecka stáda tvá dnes, vyměšuje z nich každé dobytče peřesté a strakaté, a každé dobytče načernalé mezi ovcemi, a strakaté a peřesté mezi kozami; a takové budou mzda má.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 33, 'A osvědčena potom bude spravedlnost má před tebou, když přijde na mzdu mou: Cožkoli nebude peřestého, neb strakatého mezi kozami, a načernalého mezi ovcemi, za krádež bude mi to počteno.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 34, 'I řekl Lában: Hle, ó by tak bylo, jakž jsi mluvil.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 35, 'A odloučil toho dne kozly přepásané na nohách a strakaté, a všecky kozy peřesté a strakaté, všecko, na čemž byla místa bílá, všecko také načernalé mezi dobytkem, a dal v ruce synů svých.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 36, 'Uložil pak mezi sebou a Jákobem místo vzdálí tří dní cesty; a Jákob pásl ostatek dobytka Lábanova.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 37, 'Nabral pak sobě Jákob prutů topolových zelených, a lískových a kaštanových; a poobloupil s nich po místech kůru až do bělosti, kteráž byla na prutech.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 38, 'A nakladl těch prutů tak obloupených do žlábků a koryt, (v nichž bývá voda, k nimž přicházel dobytek, aby pil), proti dobytku, aby počínaly, když by přicházely píti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 39, 'I počínaly ovce, hledíce na ty pruty, a rodily jehňata přepásaná na nohách, a peřestá i strakatá.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 40, 'Potom ta jehňata odloučil Jákob, a dobytek stáda Lábanova obrátil tváří k těm přepásaným na nohách, a ke všemu načernalému; a své stádo postavil obzvlášť, a neobrátil ho k stádu Lábanovu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 41, 'A bylo, že kdyžkoli silnější připouštíny bývaly, kladl Jákob ty pruty před oči ovcem do koryt, aby počínaly, hledíce na pruty.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 42, 'Když pak pozdní dobytek připouštín býval, nekladl jich; a tak býval pozdní Lábanův a ranný Jákobův.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 43, 'Vzrostl tedy muž ten náramně velmi, a měl dobytka mnoho, děvek i služebníků, velbloudů i oslů.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 1, 'Když pak uslyšel Jákob slova synů Lábanových, ani praví: Pobral Jákob všecko, co měl otec náš, a z těch věcí, kteréž byly otce našeho, způsobil sobě tu všecku slávu;');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 2, 'A viděl tvář Lábanovu, a aj, nebyla k němu tak jako prvé:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 3, 'I řekl mu Hospodin: Navrať se do země otců svých, a k příbuznosti své, a budu s tebou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 4, 'Protož poslav Jákob, vyvolal Ráchele a Líe na pole k stádu svému.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 5, 'A řekl jim: Vidím tvář otce vašeho, že není ke mně tak jako prvé, ješto Bůh otce mého byl se mnou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 6, 'A vy samy víte, že vší svou silou sloužil jsem otci vašemu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 7, 'Ale otec váš oklamal mne, a na desetkráte změnil mzdu mou; však nedopustil mu Bůh, aby mi zle učinil.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 8, 'Když takto řekl: Co bude peřestého, to nechť jest mzda tvá, tedy všecky ovce rodily peřestý plod. Když pak takto řekl: Co přepásaného na nohách, to bude mzda tvá, tedy všecky ovce rodily přepásané na nohách.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 9, 'A tak odjal Bůh stádo otce vašeho a dal mně.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 10, 'Nebo takto bylo: Tehdáž, když se dobytek běžel, já jsem pozdvihl očí svých, a viděl jsem ve snách, a aj, berani scházející se s ovcemi byli přepásaní na nohách, peřestí a skropení.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 11, 'Tedy řekl mi anděl Boží ve snách: Jákobe! A já jsem odpověděl: Teď jsem.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 12, 'I řekl: Pozdvihni nyní očí svých a pohleď, že všickni berani scházející se s ovcemi jsou přepásaní na nohách, peřestí a skropení; nebo jsem viděl všecko, co tobě Lában dělá.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 13, 'Já jsem ten silný Bůh, kterýž jsem se ukázal tobě v Bethel, kdež jsi pomazal kamene, kdež jsi mi se slibem zavázal; vstaniž nyní, vyjdi z země této, a navrať se do země příbuznosti své.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 14, 'Tedy odpověděly mu Ráchel a Lía, řkouce: Zdaž ještě máme díl jaký a dědictví v domě otce našeho?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 15, 'Zdaliž nejsme počteny před ním za cizí? Nebo prodal nás, ano i peníze naše do čista utratil.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 16, 'Všecko zajisté bohatství, kteréž odjal Bůh otci našemu, naše jest a synů našich; protož nyní učiň vše, což mluvil tobě Bůh.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 17, 'Vstav tedy Jákob, vsadil syny své a ženy své na velbloudy.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 18, 'A pobral všecken dobytek svůj, a všecko jmění své, kteréhož byl dosáhl, dobytek svého vychování, kteréhož nabyl v Pádan Syrské, aby se navrátil k Izákovi otci svému do země Kananejské.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 19, '(Lában pak byl odšel, aby střihl ovce své. V tom ukradla Ráchel modly, kteréž měl otec její.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 20, 'I ušel Jákob tajně od Lábana Syrského, neoznámiv mu, že jde pryč.)');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 21, 'Takž ušel se vším, což měl; a vstav, přepravil se přes řeku, a bral se přímo k hoře Galádské.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 22, 'I povědíno jest Lábanovi dne třetího, že utekl Jákob.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 23, 'Tedy on vzav bratří své s sebou, honil ho za dnů sedm; a postihl ho na hoře Galádské.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 24, '(Přišed pak Bůh k Lábanovi Syrskému ve snách noci té, řekl mu: Varuj se, abys nemluvil s Jákobem nic jináč než přátelsky.)');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 25, 'Dohonil tedy Lában Jákoba; a Jákob již byl rozbil stan svůj na té hoře; Lában také položil se s bratřími svými na též hoře Galádské.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 26, 'I řekl Lában k Jákobovi: Cos to učinil? Nebo jsi ušel tajně, a odvedls dcery mé jako zjímané mečem.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 27, 'Proč jsi tajně utekl, a vykradl se ode mne, a nepověděls mi, ješto bych tě byl vesele sprovodil s zpěvy, s bubnem a s harfou?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 28, 'A nedopustils mi, abych políbil synů svých a dcer svých? Nemoudřes jistě udělal, čině tak.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 29, 'Mělť bych dosti s to moci, abych vám zle učinil, ale Bůh otce vašeho mluvil mi noci pominulé, řka: Hleď, abys nemluvil s Jákobem nic jináč, než přátelsky.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 30, 'Ale již to tam, poněvadž jsi předce odšel, roztouživ se po domu otce svého; než proč jsi ukradl bohy mé?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 31, 'Tedy Jákob odpovídaje Lábanovi, řekl: Ušel jsem tajně; nebo jsem se bál a řekl jsem, že bys snad mocí odjal dcery své.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 32, 'Nalezneš-li pak u koho bohy své, nechať ten umře; před bratřími našimi ohledej sobě, jest-li co u mne tvého, a vezmi sobě. Ale nevěděl Jákob, že Ráchel je ukradla.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 33, 'Všed tedy Lában do stanu Jákobova, a do stanu Líe, a do stanu obou děvek, nic nenalezl. A vyšed z stanu Líe, všel do stanu Ráchel.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 34, 'Ráchel pak vzavši modly, vložila je pod sedlo, kteréž na velbloudu bývá, a sedla na ně. I přemetal Lában všecken stan, ale nic nenalezl.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 35, 'A ona řekla otci svému: Nechť to není proti mysli, pane můj, že nemohu povstati proti tobě; nebo vedlé běhu ženského nyní mi se přihodilo. A všecko přehledav, nenalezl modl.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 36, 'Protož rozhněvav se Jákob, tuze se domlouval na Lábana. I odpověděl Jákob, a řekl Lábanovi: Jaké jest přestoupení mé? Jaký hřích můj, že rozpáliv se, honíš mne?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 37, 'Nu již jsi přemetal všecky mé věci, a cos nalezl ze všech věcí domu svého? Polož teď před bratřími mými a bratřími svými, nechť rozeznají mezi námi dvěma.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 38, 'Byl jsem již dvadceti let s tebou; ovce tvé ani kozy tvé nikdy nezmetaly; a skopců stáda tvého nejedl jsem.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 39, 'Co od zvěři roztrháno, toho jsem neodvodil tobě; sám jsem tu škodu nahražoval, a ty jsi z ruky mé vyhledával toho, jako i toho, co bylo ukradeno ve dne aneb v noci.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 40, 'Bývalo tak, že ve dne trápilo mne horko, a v noci mráz, tak že odcházel i sen můj od očí mých.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 41, 'Již dvadceti let, jakž jsem v domě tvém; sloužil jsem tobě čtrnácte let za dvě dcery tvé, a šest let za dobytek tvůj, a změnils mzdu mou na desetkrát.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 42, 'A kdyby Bůh otce mého, Bůh Abrahamův, a strach Izákův nebyl se mnou, jistě bys ty byl nyní pustil mne prázdného; ale trápení mé, a práci rukou mých viděl Bůh, protož tě pominulé noci trestal.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 43, 'Odpovídaje pak Lában, dí Jákobovi: Dcery tyto jsou dcery mé a synové tito jsou synové moji, i dobytek tento můj dobytek jest, ano cokoli vidíš, mé jest; ale což mám již učiniti dcerám těmto svým aneb synům jich, kteréž zrodily?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 44, 'Protož poď, vejděme v smlouvu já a ty, aby byla na svědectví mezi mnou a tebou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 45, 'Tedy Jákob vzal kámen, a postavil jej vzhůru na znamení.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 46, 'A řekl bratřím svým: Nasbírejte kamení. A nabravše kamení, udělali hromadu, a jedli tu na té hromadě.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 47, 'I nazval ji Lában Jegar Sahadutha, a Jákob nazval ji Gál Ed.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 48, 'Nebo řekl Lában: Tato hromada nechžť jest svědkem od dnešku mezi mnou a tebou. Protož nazval jméno její Gál Ed,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 49, 'A Mispah; nebo řekl Lában: Nechať Hospodin hledí na mne a na tebe, když se rozejdeme od sebe.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 50, 'Jestliže bys trápil dcery mé, a uvedl bys jiné ženy na dcery mé, žádného člověka není s námi; hlediž, Bůh jest svědek mezi mnou a tebou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 51, 'A řekl ještě Lában Jákobovi: Aj, hromada tato, a aj, sloup, kterýž jsem postavil mezi sebou a tebou,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 52, 'Svědkem ať jest hromada tato, svědkem také sloup tento, já že nepůjdu dále k tobě za hromadu tuto, a ty tolikéž že nepůjdeš dále ke mně za hromadu tuto a sloup tento, k činění zlého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 53, 'Bůh Abrahamův, a Bůh Náchorův, Bůh otce jejich nechť soudí mezi námi. Přisáhl tedy Jákob skrze strach otce svého Izáka.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 54, 'Nabil také Jákob hovad na té hoře, a pozval bratří svých, aby hodovali; i hodovali a zůstali přes noc na též hoře.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 55, 'I vstal Lában velmi ráno, a políbiv synů svých a dcer svých, požehnal jich; i odšel a navrátil se k místu svému.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 1, 'Jákob pak odšel cestou svou, a potkali se s ním andělé Boží.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 2, 'I řekl Jákob, když je viděl: Vojsko Boží jest toto. A nazval jméno místa toho Mahanaim.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 3, 'Poslal pak Jákob posly před sebou k bratru svému Ezau, do země Seir, do kraje Idumejského.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 4, 'A přikázal jim, řka: Takto povězte pánu mému Ezau: Totoť vzkazuje služebník tvůj Jákob: U Lábana jsem byl pohostinu, a zůstával až do tohoto času.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 5, 'A mám voly a osly, ovce, a služebníky i děvky; a poslal jsem, abych se ohlásil pánu svému, a našel milost před očima tvýma.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 6, 'I navrátili se poslové k Jákobovi, řkouce: Přišli jsme k bratru tvému Ezau, kterýž také jde proti tobě, a čtyři sta mužů s ním.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 7, 'Jákob pak bál se velmi, a rmoutil se náramně. Tedy rozdělil lid, kterýž s sebou měl, ovce také a voly, a velbloudy na dva houfy.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 8, 'Nebo řekl: Jestliže by přišel Ezau k houfu jednomu, a pobil by jej, bude aspoň zadní houf zachován.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 9, 'I řekl Jákob: Bože otce mého Abrahama, a Bože otce mého Izáka, Hospodine, kterýž jsi mi řekl: Navrať se do země své, a k příbuznosti své, a dobře učiním tobě,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 10, 'Menší jsem všech milosrdenství a vší pravdy, kterouž jsi učinil s služebníkem svým; nebo s holí svou přešel jsem Jordán tento, nyní pak dva houfy mám.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 11, 'Vytrhni mne, prosím, z ruky bratra mého, z ruky Ezau; nebť se ho bojím, aby přijda, nepohubil mne i matky s dětmi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 12, 'Však jsi ty řekl: Dobře učiním tobě, a rozmnožím símě tvé jako písek mořský, kterýžto pro množství sečten býti nemůže.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 13, 'I zůstal tu noci té; a vzal z toho, což bylo před rukama, poctu bratru svému Ezau:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 14, 'Totiž dvě stě koz, a kozlů dvadceti, ovec dvě stě, a beranů dvadceti,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 15, 'Velbloudů s mladými jich třidceti, krav čtyřidceti, volů deset, oslic dvadceti, a oslátek deset.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 16, 'A poručil je služebníkům svým, každé stádo obzvláštně, a řekl služebníkům svým: Jděte přede mnou, a stádo od stáda ať jde opodál.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 17, 'I poručil přednímu, řka: Když se potká s tebou Ezau bratr můj, a optá se tebe, řka Čí jsi? a kam jdeš? a čí jest to stádo před tebou?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 18, 'Řekneš: Jsem služebníka tvého Jákoba, a dar tento jest poslán pánu mému Ezau; a teď i sám jde za námi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 19, 'Poručil také druhému i třetímu, a všechněm jdoucím za těmi stády, řka: V táž slova mluvte k Ezau, když byste naň trefili.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 20, 'A díte také: Aj, služebník tvůj Jákob za námi; nebo řekl: Ukrotím tvář jeho darem, kterýž jde přede mnou, a potom uzřím tvář jeho; snad přijme tvář mou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 21, 'A tak předšel dar před ním; on pak zůstal tu noc při houfu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 22, 'A vstav ještě v noci, vzal obě ženy své, a dvě děvky své, a jedenácte synů svých, a přešel přes brod Jabok.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 23, 'Vzav tedy je, přepravil je přes tu řeku; přepravil také i vše, což měl.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 24, 'A zůstal Jákob sám; a tu zápasil s ním muž až do svitání.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 25, 'A vida, že ho nepřemůže, obrazil jej v příhbí vrchní stehna jeho; i vyvinulo se příhbí stehna Jákobova, když zápasil s ním.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 26, 'A řekl: Pusť mne, nebť zasvitává. I řekl: Nepustím tě, leč mi požehnáš.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 27, 'I řekl jemu: Jaké jest jméno tvé? Odpověděl: Jákob.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 28, 'I dí: Nebude více nazýváno jméno tvé toliko Jákob, ale také Izrael; nebo jsi statečně zacházel s Bohem i lidmi, a přemohls.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 29, 'I otázal se Jákob, řka: Oznam, prosím, jméno své. Kterýžto odpověděl: Proč se ptáš na jméno mé? I dal mu tu požehnání.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 30, 'Tedy nazval Jákob jméno místa toho Fanuel; nebo jsem prý viděl Boha tváří v tvář, a zachována jest duše má.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 31, 'I vzešlo mu slunce, když pominul místa toho Fanuel, a kulhal na nohu svou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 32, 'Protož nejedí synové Izraelští až do tohoto dne té žily krátké, kteráž jest v vrchním příhbí stehna, proto že obrazil příhbí stehna Jákobova na žile krátké.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 1, 'Pozdvih pak očí svých Jákob, uzřel, an Ezau jde, a čtyři sta mužů s ním; i rozdělil syny Líe zvlášť a Ráchele zvlášť, a obou děvek zvlášť.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 2, 'Postavil, pravím, děvky s syny jejich napřed, potom Líu s syny jejími za nimi, Ráchel pak a Jozefa nejzáze.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 3, 'A sám šel před nimi, a poklonil se až k zemi po sedmkrát, až právě přišel k bratru svému.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 4, 'I běžel Ezau proti němu, a objal ho; a pad na šíji jeho, líbal ho. I plakali.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 5, 'Pozdvih pak očí svých, a spatřiv ženy s dětmi, řekl: Kdo jsou onino s tebou? Odpověděl: Jsou dítky, kteréž Bůh dal z milosti služebníku tvému.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 6, 'Mezi tím přiblížily se děvky s syny svými, i poklonili se.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 7, 'Přiblížila se také Lía s syny svými, a poklonili se; a potom přiblížil se Jozef a Ráchel, a také se poklonili.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 8, 'I řekl Ezau: K čemu jest všecken ten houf, kterýž jsem potkal? Odpověděl: Abych nalezl milost před očima pána mého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 9, 'Tedy řekl Ezau: Mám hojně, bratře můj; nech sobě, což tvého jest.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 10, 'I řekl Jákob: Nezbraňuj se, prosím; jestliže jsem nyní nalezl milost před očima tvýma, přijmi dar můj z ruky mé, poněvadž jsem viděl tvář tvou, jako bych viděl tvář Boží, a laskavě jsi mne přijal.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 11, 'Přijmi, prosím, dar můj obětovaný tobě, poněvadž štědře obdařil mne Bůh, a mám všeho dosti. Takž ho přinutil, a on vzal.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 12, 'I dí: Poď, a jděme; já půjdu s tebou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 13, 'I řekl k němu Jákob: Ví pán můj, že děti jsou outlí, a mám s sebou ovce i krávy březí; kteréžto budou-li hnány přes moc jeden den, pomře mi všecken dobytek.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 14, 'Nechžť medle jde pán můj před služebníkem svým, já pak poznenáhlu se poberu, tak jakž bude moci jíti stádo, kteréž před sebou mám, a jakž postačiti budou moci děti, až tak dojdu ku pánu svému do Seir.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 15, 'I řekl Ezau: Nechť ale pozůstavím něco lidu, kterýž mám s sebou. I odpověděl: K čemu to? Nechť toliko naleznu milost před očima pána svého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 16, 'Tedy Ezau toho dne navrátil se cestou svou do Seir.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 17, 'Jákob pak bral se do Sochot, a ustavěl sobě dům, a dobytku svému zdělal stáje; protož nazval jméno místa toho Sochot.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 18, 'A tak Jákob navracuje se z Pádan Syrské, přišel ve zdraví k městu Sichem, kteréž jest v zemi Kananejské, a položil se před městem.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 19, 'I koupil díl pole toho, na němž byl rozbil stan svůj, od synů Emora, otce Sichemova, za sto ovec.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 20, 'A postavil tu oltář, kterémužto dal jméno Bůh silný, Bůh Izraelský.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 1, 'Vyšla pak Dína, dcera Líe, kterouž porodila Jákobovi, aby se dívala na dcery té země.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 2, 'Kteroužto uzřev Sichem, syn Emora Hevejského, knížete v krajině té, vzal ji, i ležel s ní, a ponížil jí.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 3, 'I připojila se duše jeho k Díně, dceři Jákobově; a zamilovav děvečku, mluvil k srdci jejímu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 4, 'Mluvil potom Sichem k Emorovi, otci svému, těmito slovy: Vezmi mi děvečku tuto za manželku.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 5, 'Uslyšev pak Jákob, že poškvrnil Díny dcery jeho, (a synové jeho byli s stádem na poli,) mlčel, až oni přišli.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 6, 'Tedy vyšel Emor, otec Sichemův, k Jákobovi, aby mluvil s ním o to.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 7, 'A v tom synové Jákobovi přišli s pole; a uslyšavše o tom, bolestí naplněni jsou muži ti, a rozhněvali se velmi, proto že hanebnou věc učinil v Izraeli, ležav se dcerou Jákobovou, čehož činiti nenáleželo.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 8, 'I mluvil Emor s nimi na tento způsob: Sichem, syn můj, hoří milostí k vaší dceři; prosím, dejte mu ji za manželku.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 9, 'A spřízněte se s námi: Dcery své dávejte nám, a naše dcery pojímejte sobě.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 10, 'A bydlete s námi, nebo všecka země bude před vámi; osaďte se a obchod veďte v ní, a vládněte jí.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 11, 'Mluvil i Sichem otci jejímu, a bratřím jejím: Nechť naleznu milost před očima vašima, dám, co mi koli díte.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 12, 'Jmenujte mi věno i dary jak chcete veliké, dám, jak mi koli řeknete; jen mi tu děvečku dejte za manželku.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 13, 'Odpovídajíce pak synové Jákobovi Sichemovi a Emorovi, otci jeho, lstivě mluvili, proto že poškvrnil Díny sestry jich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 14, 'A řekli jim: Nemůžeme učiniti toho, abychom dali sestru svou za muže neobřezaného; nebo to ohavnost jest u nás.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 15, 'Než na tento způsob vám povolíme: Jestliže se chcete srovnati s námi, aby obřezán byl každý z vás pohlaví mužského:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 16, 'Tedy budeme dávati dcery své vám, a dcery vaše bráti sobě; a budeme bydliti s vámi, a budeme lid jeden.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 17, 'Pakli neuposlechnete nás, abyste se obřezali, vezmeme zase dceru svou a odejdeme.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 18, 'Tedy líbila se řeč jejich Emorovi i Sichemovi, synu Emorovu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 19, 'A nemeškal mládenec učiniti toho; nebo se mu zalíbila dcera Jákobova. A on byl nejvzácnější ze všech v domě otce svého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 20, 'I přišel Emor a Sichem, syn jeho, k bráně města svého; a mluvili mužům města svého, řkouce:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 21, 'Muži tito pokojně se mají k nám, nechť tedy bydlí v zemi této, a obchod vedou v ní, (nebo země jest dosti široká a prostranná před nimi;) dcery jejich budeme sobě bráti za manželky, a dcery své budeme dávati jim.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 22, 'Než na tento způsob přivolí nám ti muži k tomu, aby bydlili s námi, a abychom byli jeden lid: Jestliže obřezán bude každý pohlaví mužského mezi námi, tak jako oni jsou obřezáni.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 23, 'Dobytek jejich a statek jejich, i všecka hovada jejich, zdaliž nebudou naše? Toliko v tom jim povolme, a budou bydliti s námi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 24, 'I uposlechli Emora a Sichema, syna jeho, všickni vycházející branou města jeho; a obřezali se všickni pohlaví mužského, což jich koli vycházelo z brány města jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 25, 'A toť dne třetího, když oni největší bolest měli, dva synové Jákobovi, Simeon a Léví, bratří Díny, vzav každý z nich meč svůj, vpadli do města směle, a pomordovali všecky pohlaví mužského.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 26, 'Emora také a Sichema, syna jeho, zamordovali mečem, a vzavše Dínu z domu Sichemova, odešli.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 27, 'Potom synové Jákobovi přišedše na zbité, vzebrali město, proto že poškvrnili sestry jejich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 28, 'Stáda jejich, a voly i osly jejich, a což bylo v městě i po poli, pobrali.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 29, 'K tomu i všecko jmění jejich, a všecky malé dítky jejich, a ženy jejich zajali, a vybrali, co kde v domích bylo.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 30, 'Řekl pak Jákob Simeonovi a Léví: Zkormoutili jste mne, a zošklivili jste mne u obyvatelů krajiny této, u Kananejských a Ferezejských, a já jsem s malým počtem lidí. Seberou-li se na mne, zbijí mne, a tak vyhlazen budu já i dům můj.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 31, 'A oni odpověděli: A což měli jako nevěstky zle užívati sestry naší?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 1, 'Potom mluvil Bůh k Jákobovi: Vstana, vstup do Bethel, a bydli tam; a udělej tam oltář Bohu silnému, kterýž se ukázal tobě, kdyžs utíkal před Ezau bratrem svým.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 2, 'Tedy řekl Jákob čeládce své, a všechněm, kteříž s ním byli: Odvrzte bohy cizí, kteréž máte mezi sebou, a očisťte se, a změňte roucha svá.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 3, 'A vstanouce, vstupme do Bethel, a udělám tam oltář silnému Bohu, kterýž vyslyšel mne v den ssoužení mého, a byl se mnou na cestě, kterouž jsem šel.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 4, 'Tedy dali Jákobovi všecky bohy cizí, kteréž měli, i náušnice, kteréž byly na uších jejich; i zakopal je Jákob pod tím dubem, kterýž byl u Sichem.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 5, 'I brali se odtud. (A byl strach Boží na městech, kteráž byla vůkol nich, a nehonili synů Jákobových.)');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 6, 'Tedy přišel Jákob do Lůz, kteréž jest v zemi Kananejské, (to již slove Bethel,) on i všecken lid, kterýž byl s ním.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 7, 'I vzdělal tu oltář, a nazval to místo Bůh silný Bethel; nebo tu se mu byl zjevil Bůh, když utíkal před bratrem svým.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 8, 'Tehdy umřela Debora, chovačka Rebeky, a pochována jest pod Bethel, pod dubem; i nazval jméno jeho Allon Bachuth.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 9, 'Ukázal se pak opět Bůh Jákobovi, když se navracoval z Pádan Syrské, a požehnal mu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 10, 'I řekl jemu Bůh: Jméno tvé jest Jákob. Nebude více nazýváno jméno tvé toliko Jákob, ale Izrael také bude jméno tvé. Protož nazval jméno jeho Izrael.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 11, 'Řekl ještě Bůh jemu: Já jsem Bůh silný všemohoucí; rostiž a množ se; národ, nýbrž množství národů bude z tebe, i králové z bedr tvých vyjdou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 12, 'A zemi tu, kterouž jsem dal Abrahamovi a Izákovi, tobě ji dám; semeni také tvému po tobě dám tu zemi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 13, 'I vstoupil od něho Bůh z místa, na kterémž mluvil s ním.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 14, 'Jákob pak vyzdvihl znamení pamětné na místě tom, na kterémž mluvil s ním, sloup kamenný; a pokropil ho skropením, a svrchu polil jej olejem.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 15, 'A nazval Jákob jméno místa toho, na kterémž mluvil s ním Bůh, Bethel.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 16, 'I brali se z Bethel, a bylo již nedaleko do Efraty. I porodila Ráchel, a těžkosti trpěla roděci.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 17, 'A když s těžkostí rodila, řekla jí baba: Neboj se, nebo také tohoto syna míti budeš.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 18, 'I stalo se, když k smrti pracovala, (nebo umřela,) nazvala jméno jeho Ben Oni; ale otec jeho nazval ho Beniaminem.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 19, 'I umřela Ráchel, a pochována jest na cestě k Efratě, jenž jest Betlém.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 20, 'A postavil Jákob znamení pamětné nad hrobem jejím; toť jest znamení hrobu Ráchel až do dnešního dne.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 21, 'I odebral se odtud Izrael, a rozbil stan svůj za věží Eder.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 22, 'Stalo se pak také, když bydlil Izrael v té krajině, že Ruben šel, a spal s Bálou, ženinou otce svého; o čemž uslyšel Izrael. Bylo pak synů Jákobových dvanácte.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 23, 'Synové pak Líe: Prvorozený Jákobův Ruben, potom Simeon, a Léví, a Juda, a Izachar, a Zabulon.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 24, 'Synové Ráchel: Jozef a Beniamin.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 25, 'A synové Bály, děvky Ráchel: Dan a Neftalím.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 26, 'A synové Zelfy, děvky Líe: Gád a Asser. Tiť jsou synové Jákobovi, kteříž mu zrozeni jsou v Pádan Syrské.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 27, 'Tedy přišel Jákob k Izákovi otci svému do Mamre, do města Arbe, jenž jest Hebron, kdežto bydlil pohostinu Abraham a Izák.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 28, 'A bylo dnů Izákových sto osmdesáte let.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 29, 'I dokonal Izák, a umřel, a připojen jest k lidu svému, stár jsa a plný dnů; i pochovali ho Ezau a Jákob, synové jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 1, 'Tito jsou pak rodové Ezau, kterýž měl přijmí Edom.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 2, 'Ezau pojal sobě ženy ze dcer Kananejských, Adu, dceru Elona Hetejského, a Olibamu, dceru Anovu, dceru Sebeona Hevejského,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 3, 'A Bazematu, dceru Izmaelovu, sestru Nabajotovu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 4, 'I porodila Ada Ezauchovi Elifaza, a Bazemat porodila Rahuele.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 5, 'Olibama pak porodila Jehusa, a Jheloma, a Koré. Ti jsou synové Ezau, kteříž se mu zrodili v zemi Kananejské.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 6, 'I pobral Ezau ženy své, i syny své, a dcery své, a všecku čeleď svou, i dobytek svůj, a všecka hovada svá, i všecko jmění své, kteréhož nabyl v zemi Kananejské, a odebral se do země Seir, před příchodem Jákoba bratra svého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 7, 'Nebo zboží jejich bylo tak veliké, že nemohli bydliti spolu; aniž ta země, v níž oni pohostinu byli, mohla jich snésti, pro dobytky jejich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 8, 'Protož bydlil Ezau na hoře Seir; Ezau pak ten jest Edom.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 9, 'A tak tito jsou rodové Ezau, otce Idumejských, na hoře Seir.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 10, 'Tato byla jména synů Ezau: Elifaz, syn Ady, ženy Ezau; Rahuel, syn Bazematy, ženy Ezau.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 11, 'Synové pak Elifazovi byli: Teman, Omar, Sefo, a Gatam a Kenaz.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 12, 'Tamna pak byla ženina Elifaza, syna Ezau. Ta porodila Elifazovi Amalecha. Ti jsou synové Ady, ženy Ezau.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 13, 'Synové pak Rahuelovi tito: Nahat, Zára, Samma a Méza. To byli synové Bazematy, ženy Ezau.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 14, 'A tito byli synové Olibamy, dcery Anovy, dcery Sebeonovy, ženy Ezau, kteráž porodila Ezauchovi Jehusa, Jheloma a Koré.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 15, 'Tito všickni byli knížata synů Ezau. Synové Elifaza prvorozeného Ezau: Kníže Teman, kníže Omar, kníže Sefo, kníže Kenaz,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 16, 'Kníže Koré, kníže Gatam, kníže Amalech. Ta jsou knížata pošlá z Elifaza v zemi Idumejské; ti jsou synové Ady.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 17, 'Tito pak jsou synové Rahuele, syna Ezau: Kníže Nahat, kníže Zára, kníže Samma, kníže Méza. Ta knížata pošla z Rahuele, v zemi Idumejské; to jsou synové Bazematy, ženy Ezau.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 18, 'A synové Olibamy, ženy Ezau, tito jsou: Kníže Jehus, kníže Jhelom, kníže Koré. To jsou knížata z Olibamy, dcery Anovy, ženy Ezau.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 19, 'Tiť jsou synové Ezau, a ta knížata jejich; onť jest Edom.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 20, 'Tito pak jsou synové Seir, totiž Horejští, obyvatelé země té: Lotan, Sobal, Sebeon a Ana,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 21, 'A Dison, Eser a Dízan. Ta jsou knížata Horejská, synové Seir, v zemi Idumejské.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 22, 'Synové Lotanovi byli: Hori a Hemam; a sestra Lotanova Tamna.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 23, 'Synové pak Sobalovi tito: Alvan, Manáhat, Ebal, Sefo a Onam.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 24, 'A tito synové Sebeonovi: Aia a Ana. To jest ten Ana, kterýž nalezl mezky na poušti, když pásl osly Sebeona otce svého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 25, 'Tito pak děti Anovi: Dison a Olibama, dcera Anova.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 26, 'A synové Dízanovi tito: Hamdan, Eseban, Jetran a Charan.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 27, 'Synové Eser tito: Balaan, Závan a Achan.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 28, 'Tito synové Dízanovi: Hus a Aran.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 29, 'Tato jsou knížata Horejská: Kníže Lotan, kníže Sobal, kníže Sebeon, kníže Ana,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 30, 'Kníže Dison, kníže Eser, kníže Dízan. To byla knížata Horejská, po knížetstvích svých v zemi Seir.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 31, 'Tito pak byli králové, kteříž kralovali v zemi Idumejské, prvé než kraloval král nad syny Izraelskými.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 32, 'Kraloval tedy v Edom Béla, syn Beorův, a jméno města jeho Denaba.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 33, 'I umřel Béla, a kraloval místo něho Jobab, syn Záre z Bozra.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 34, 'I umřel Jobab, a kraloval na místě jeho Husam z země Temanské.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 35, 'Umřel i Husam, a kraloval místo něho Adad, syn Badadův, kterýž porazil Madianské v krajině Moábské; a jméno města jeho Avith.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 36, 'Když pak umřel Adad, kraloval místo něho Semla z Masreka.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 37, 'A po smrti Semlově kraloval na místě jeho Saul z Rohobot od řeky.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 38, 'Umřel i Saul, a kraloval místo něho Bálanan, syn Achoborův.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 39, 'A když i Bálanan umřel, syn Achoborův, kraloval na místě jeho Adar; a jméno města jeho Pahu; jméno pak ženy jeho Mehetabel, dcera Matredy, dcery Mezábovy.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 40, 'Ta jsou jména knížat pošlých z Ezau, po čeledech jejich, po místech jejich, vedlé jmen jejich: Kníže Tamna, kníže Alva, kníže Jetet,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 41, 'Kníže Olibama, kníže Ela, kníže Finon.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 42, 'Kníže Kenaz, kníže Teman, kníže Mabsar.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 43, 'Kníže Magdiel, kníže Híram. Tať jsou knížata Idumejská, tak jakž kteří bydlili v zemi dědictví svého. Toť jest ten Ezau, otec Idumejských.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 1, 'Jákob pak bydlil v zemi putování otce svého, v zemi Kananejské.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 2, 'Tito jsou příběhové Jákobovi: Jozef, když byl v sedmnácti letech, pásl s bratřími svými dobytek, (a byl mládenček), s syny Bály a Zelfy, žen otce svého. A oznamoval Jozef zlou pověst o nich otci svému.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 3, 'Izrael pak miloval Jozefa nad všecky syny své; nebo v starosti své zplodil jej. A udělal mu sukni proměnných barev.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 4, 'A když spatřili bratří jeho, že ho miluje otec jejich nad všecky bratří jeho, nenáviděli ho, aniž mohli pokojně k němu promluviti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 5, 'Měl pak Jozef sen, a vypravoval jej bratřím svým; pročež v větší nenávisti ho měli.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 6, 'Nebo pravil jim: Slyšte, prosím, sen, kterýž jsem měl.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 7, 'Hle, vázali jsme snopy na poli, a aj, povstal snop můj, a stál. Vůkol také stáli snopové vaši, a klaněli se snopu mému.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 8, 'Jemužto odpověděli bratří jeho: Zdaliž kralovati budeš nad námi, aneb pánem naším budeš? Z té příčiny ještě více nenáviděli ho pro sny jeho, a pro slova jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 9, 'Potom ještě měl jiný sen, a vypravoval jej bratřím svým, řka: Hle, opět jsem měl sen, a aj, slunce a měsíc, a jedenácte hvězd klanělo mi se.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 10, 'I vypravoval otci svému a bratřím svým. A domlouval mu otec jeho, a řekl jemu: Jakýž jest to sen, kterýž jsi měl? Zdaliž přijdeme, já a matka tvá i bratří tvoji, abychom se klaněli před tebou až k zemi?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 11, 'Tedy záviděli mu bratří jeho; ale otec jeho měl pozor na tu věc.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 12, 'Odešli pak bratří jeho, aby pásli dobytek otce svého v Sichem.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 13, 'A řekl Izrael Jozefovi: Zdaliž nepasou bratří tvoji v Sichem? Poď, a pošli tě k nim. Kterýžto odpověděl: Aj, teď jsem.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 14, 'I řekl jemu: Jdi nyní, zvěz, jak se mají bratří tvoji, a co se děje s dobytkem; a zase mi povíš o tom. A tak poslal ho z údolí Hebron, a on přišel do Sichem.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 15, 'Našel ho pak muž nějaký, an bloudí po poli. I zeptal se ho muž ten, řka: Čeho hledáš?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 16, 'Odpověděl: Bratří svých hledám; pověz mi, prosím, kde oni pasou?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 17, 'I řekl muž ten: Odešli odsud; nebo slyšel jsem je, ani praví: Poďme do Dothain. Tedy šel Jozef za bratřími svými, a našel je v Dothain.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 18, 'Kteřížto, jakž ho uzřeli zdaleka, prvé než k nim došel, ukládali o něm, aby jej zahubili.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 19, 'Nebo řekli jeden druhému: Ej, mistr snů teď jde.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 20, 'Nyní tedy poďte, a zabíme jej, a uvržeme ho do některé čisterny, a díme: Zvěř lítá sežrala jej. I uzříme, nač jemu vyjdou snové jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 21, 'A uslyšev to Ruben, aby ho vytrhl z ruky jejich, (nebo řekl: Neodjímejme mu hrdla,)');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 22, 'Řekl jim Ruben: Nevylévejte krve. Vrzte jej do této čisterny, kteráž jest na poušti, a nevztahujte ruky na něj. Ale on chtěl vysvoboditi ho z ruky jejich, a pomoci mu, aby se navrátil k otci svému.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 23, 'A když přišel Jozef k bratřím svým, strhli s něho sukni jeho, sukni proměnných barev, kterouž měl na sobě.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 24, 'A pochopivše, uvrhli jej do čisterny. Čisterna pak ta byla prázdná, v níž ne bylo vody.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 25, 'I usadili se, aby jedli chléb. A pozdvihše očí svých, uzřeli, a aj, množství Izmaelitských přicházejících z Galád, kteřížto na velbloudích svých nesli vonné věci a kadidlo a mirru do Egypta.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 26, 'I řekl Juda bratřím svým: Jaký zisk míti budeme, zabijeme-li bratra svého, a zatajíme-li krve jeho?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 27, 'Poďte, prodejme ho Izmaelitským, a nevztahujme na něj rukou svých, nebo bratr náš, tělo naše jest. I uposlechli ho bratří jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 28, 'Když pak mimo ně jeli muži ti, kupci Madianští, vytáhli a vyvedli Jozefa z té čisterny, a prodali jej Izmaelitským za dvadceti stříbrných. Ti zavedli Jozefa do Egypta.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 29, 'A navrátil se Ruben k čisterně, a aj, již ne bylo Jozefa v ní. I roztrhl roucha svá.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 30, 'A navrátiv se k bratřím svým, řekl: Pacholete není, a já kam se mám podíti?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 31, 'Tedy vzali sukni Jozefovu, a zabivše kozla, smočili sukni tu ve krvi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 32, 'A poslali sukni tu proměnných barev, a dali ji donésti k otci svému, aby řekli: Tuto jsme nalezli; pohleď nyní, jest-li sukně syna tvého, či není?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 33, 'A on poznav ji, řekl: Sukně syna mého jest; zvěř lítá sežrala jej, konečně roztrhán jest Jozef.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 34, 'I roztrhl Jákob roucha svá, a vloživ žíni na bedra svá, zámutek nesl po synu svém za mnoho dní.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 35, 'Sešli se pak všickni synové jeho, a všecky dcery jeho, aby ho těšili. Ale on nedal se potěšiti, a řekl: Nýbrž já tak v zámutku sstoupím za synem svým do hrobu. A plakal ho otec jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 36, 'Mezi tím Madianští prodali Jozefa do Egypta Putifarovi, dvořeninu Faraonovu, hejtmanu žoldnéřů.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 1, 'Stalo se pak v ten čas, že sstupuje Juda od bratří svých, uchýlil se k muži Odolamitskému, jehož jméno bylo Híra.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 2, 'I uzřel tam Juda dceru muže Kananejského, kterýž sloul Sua; a pojav ji, všel k ní.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 3, 'Kterážto počala a porodila syna; i nazval jméno jeho Her.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 4, 'A počavši opět, porodila syna; a nazvala jméno jeho Onan.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 5, 'Porodila pak ještě syna, jehož jméno nazvala Séla. A byl Juda v Chezib, když ona jej porodila.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 6, 'I dal Juda Herovi prvorozenému svému manželku, jménem Támar.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 7, 'A byl Her, prvorozený Judův, zlý před očima Hospodina; i zabil jej Hospodin.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 8, 'Tedy řekl Juda Onanovi: Vejdi k ženě bratra svého, a podlé příbuznosti pojmi ji, abys vzbudil símě bratru svému.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 9, 'Věděl pak Onan, že to símě nebude jeho. Protož kdykoli vcházel k ženě bratra svého, vypouštěl símě na zem, aby nezplodil synů bratru svému.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 10, 'I nelíbilo se Hospodinu to, co dělal Onan; protož ho také zabil.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 11, 'Tedy řekl Juda k Támar nevěstě své: Pobuď v domě otce svého vdovou, dokudž nedoroste Séla, syn můj. (Nebo řekl: Aby on také neumřel, jako i bratří jeho.) I odešla Támar, a bydlila v domě otce svého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 12, 'A po mnohých dnech umřela dcera Suova, manželka Judova. Kterýžto potěšiv se zas, šel do Tamnas k těm, kteříž střihli ovce jeho, a s ním Híra Odolamitský, přítel jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 13, 'I oznámeno jest Támar těmito slovy: Aj, tchán tvůj vstupuje do Tamnas, aby střihl ovce své.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 14, 'Tedy ona složivši s sebe šaty své vdovské, zavila se v rouchu, a oděla se a seděla na rozcestí, kudy se jde do Tamnas. Nebo viděla, že Séla dorostl, a že není dána jemu za manželku.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 15, 'Kteroužto uzřev Juda, za to měl, že jest nevěstka; nebo zakryla tvář svou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 16, 'Protož uchýliv se k ní s cesty, řekl: Dopusť medle, ať vejdu k tobě. (Nebo nevěděl, aby nevěsta jeho byla.) I řekla: Co mi dáš, jestliže vejdeš ke mně?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 17, 'Odpověděl: Pošliť kozelce z stáda. Dí ona: Kdybys něco zastavil, dokavadž nepošleš.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 18, 'I řekl: Cožť mám dáti v zástavě? Odpověděla ona: Pečetní prsten svůj, a halži svou, a hůl svou, kterouž máš v ruce své. I dal jí, a všel k ní; a počala z něho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 19, 'Tedy vstavši, odešla, a sňavši rouchu svou s sebe, oblékla se v šaty své vdovské.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 20, 'I poslal Juda kozelce po příteli svém Odolamitském, aby vzal zase základ od ženy. A nenalezl jí.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 21, 'I ptal se mužů toho místa, řka: Kde jest ta nevěstka, kteráž seděla na rozcestí této cesty? Řekli oni: Nebylotě zde nevěstky.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 22, 'Tedy navrátiv se k Judovi, řekl: Nenašel jsem jí; a také muži místa toho pravili: Nebylo zde nevěstky.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 23, 'I řekl Juda: Nechť sobě to má, abychom neuvedli se v lehkost. Jáť jsem poslal toho kozelce, ale tys jí nenalezl.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 24, 'I stalo se okolo tří měsíců, že oznámili Judovi, řkouce: Dopustila se smilství Támar nevěsta tvá, a jest již i těhotná z smilství. I řekl Juda: Vyveďte ji, aby byla upálena.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 25, 'Když pak vedena byla, poslala k tchánu svému, řkuci: Z muže, jehož tyto věci jsou, těhotná jsem. A při tom řekla: Pohleď, prosím, čí jsou tyto věci, pečetní prsten, halže a hůl tato?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 26, 'Tedy pohleděv na to Juda, řekl: Spravedlivějšíť jest než já, poněvadž jsem nedal jí Sélovi synu svému. A více jí nepoznával.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 27, 'Stalo se pak, že když přišel čas porodu jejího, aj, bliženci v životě jejím.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 28, 'A když rodila, jeden z nich vyskytl ruku, kteroužto chytivši baba, uvázala na ni červenou nitku, řkuci: Ten vyjde prvé.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 29, 'Když pak vtáhl ruku svou zase, hle, vyšel bratr jeho. I řekla: Jak jsi protrhl? Tvéť jest protržení. I nazváno jest jméno jeho Fáres.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 30, 'A potom vyšel bratr jeho, kterýž měl na ruce nitku červenou. I nazváno jest jméno jeho Zára.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 1, 'Jozef pak doveden byl do Egypta; a koupil ho Putifar, dvořenin Faraonův, nejvyšší nad drabanty, muž Egyptský, od Izmaelitských, kteříž ho tam dovedli.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 2, 'Byl pak Hospodin s Jozefem, a všecko se mu šťastně vedlo, a bydlil v domě pána svého toho Egyptského.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 3, 'A viděl pán jeho, že Hospodin byl s ním, a že všecko, což činil, Hospodin k prospěchu přivedl v rukou jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 4, 'Tedy nalezl Jozef milost před očima jeho, a sloužil mu. I představil ho domu svému, a všecko, což měl, dal v ruku jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 5, 'A hned, jakž ustanovil ho nad domem svým, a nade vším, což měl, požehnal Hospodin domu Egyptského toho pro Jozefa. A bylo požehnání Hospodinovo na všech věcech, kteréž měl doma i na poli.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 6, 'Všech tedy věcí, kteréž měl, zanechal v rukou Jozefových; aniž o čem, tak jako on, věděl, jediné o chlebě, kterýž jedl. Byl pak Jozef ušlechtilé postavy a krásného vzezření.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 7, 'I stalo se potom, že vzhlédala žena pána jeho očima svýma na Jozefa, a řekla: Spi se mnou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 8, 'Kterýžto odpíraje, řekl ženě pána svého: Aj, pán můj neví tak jako já, co jest v domě, a všecko, což má, dal v ruce mé.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 9, 'Není žádného přednějšího nade mne v domě tomto, aniž co vyňal z správy mé, kromě tebe, jelikož jsi ty manželka jeho. Jak bych tedy učinil takovou nešlechetnost, a hřešil i proti Bohu?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 10, 'A když mluvila ona Jozefovi den po dni, nepovolil jí, aby spal s ní, ani aby býval s ní.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 11, 'Tedy dne jednoho, když přišel do domu k práci své, a nebylo tu žádného z domácích v domě,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 12, 'Chytila jej ona za roucho jeho, řkuci: Lež se mnou. On pak nechav roucha svého v rukou jejích, utekl, a vyšel ven.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 13, 'A ona viduci, že nechal roucha svého v rukou jejích a vyběhl ven,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 14, 'Svolala domácí své, a řekla k nim takto: Pohleďte, přivedl nám muže Hebrejského, kterýž by měl posměch z nás; nebo přišel ke mně, aby ležel se mnou; i křičela jsem hlasem velikým.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 15, 'A když uslyšel, že jsem hlasu svého pozdvihla a křičela, nechav roucha svého u mne, utekl a vyšel ven.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 16, 'Tedy schovala roucho jeho u sebe, až přišel pán jeho do domu svého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 17, 'K němuž mluvila v tato slova, řkuci: Přišel ke mně služebník ten Hebrejský, kteréhožs přivedl nám, aby mi lehkost učinil.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 18, 'A když jsem hlasu svého pozdvihla a křičela, tedy nechal roucha svého u mne, a utekl ven.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 19, 'I stalo se, že, když uslyšel pán jeho slova ženy své, kteráž mluvila mu, pravěci: Tak mi učinil služebník tvůj, rozhněval se velmi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 20, 'Protož vzal ho pán jeho, a dal jej do věže žalářné, v to místo, kdež vězňové královští seděli; i byl tam v žaláři.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 21, 'Byl pak Hospodin s Jozefem, a naklonil se k němu milosrdenstvím; a dal jemu milost u vládaře nad žalářem.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 22, 'I dal vládař žaláře v moc Jozefovi všecky vězně, kteříž byli v věži žalářné; a cožkoli tam činiti měli, on to spravoval.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 23, 'Aniž vládař žaláře k čemu dohlídal,což jemu svěřil; proto že Hospodin byl s ním, a což on činil, Hospodin tomu prospěch dával.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 1, 'Stalo se potom, že šeňkýř krále Egyptského a pekař provinili proti pánu svému, králi Egyptskému.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 2, 'I rozhněval se Farao na oba úředníky své, na vládaře nad šeňkýři, a na vládaře nad pekaři.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 3, 'A dal je do vězení v domě nejvyššího nad drabanty, do věže žalářné, v místo, v němž Jozef vězněm byl.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 4, 'I postavil jim nejvyšší nad drabanty Jozefa k službě; a byli drahně dní u vězení.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 5, 'I měli sen oba dva, každý z nich sen svůj noci jedné, každý podlé vyložení sna svého, šeňkýř i pekař krále Egyptského, kteříž seděli v věži.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 6, 'Tedy přišel k nim Jozef ráno, a hleděl na ně; a aj, byli smutní.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 7, 'I optal se těch úředníků Faraonových, kteříž s ním byli v vězení v domě pána jeho, řka: Proč jsou dnes tváři vaše smutnější?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 8, 'Kteřížto odpověděli jemu: Měli jsme sen, a nemáme, kdo by jej vyložil. I řekl jim Jozef: Zdaliž Boží nejsou výkladové? Pravte mi medle.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 9, 'Tedy správce nad šeňkýři vypravoval sen svůj Jozefovi, a řekl jemu: Zdálo se mi ve snách, že jsem viděl před sebou vinný kmen,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 10, 'A na tom kmenu tři ratolesti; a ten kmen jako by pupence pouštěl, a vycházel květ jeho, až k sezrání přišli hroznové jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 11, 'A já maje koflík Faraonův v ruce své, bral jsem hrozny, a vytlačoval je do koflíka Faraonova, a podával jsem koflíka Faraonovi do rukou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 12, 'I řekl jemu Jozef: Toto jest vyložení jeho: Ti tři révové jsou tři dnové.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 13, 'Po třech dnech povýší Farao hlavy tvé, a k úřadu tvému tě navrátí; i budeš podávati koflíka Faraonova do ruky jeho podlé obyčeje prvního, když jsi byl šeňkýřem jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 14, 'Ale mějž mne v své paměti, kdyžť se dobře povede; a učiň, prosím, se mnou to milosrdenství, abys zmínku učinil o mně před Faraonem, a vysvobodil mne z domu tohoto.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 15, 'Nebo kradmo jsem vzat z země Židovské; a zde jsem ničeho neučinil, pročež by mne do tohoto vězení dali.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 16, 'Vida pak správce nad pekaři, že dobře vyložil, řekl Jozefovi: Mně také zdálo se ve snách, ano tři košové pletení na hlavě mé.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 17, 'A v koši vrchním byli všelijací pokrmové Faraonovi dílem pekařským strojení, a ptáci jedli je z koše nad hlavou mou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 18, 'I odpověděl Jozef a řekl: Toto jest vyložení jeho: Tři košové jsou tři dnové.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 19, 'Po třech dnech odejme tobě Farao hlavu tvou, a oběsí tě na dřevě; i budou jísti ptáci maso tvé s tebe.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 20, 'Tedy stalo se v den třetí, v den pamatný narození Faraonova, že učinil hody všechněm služebníkům svým; i počítal hlavu vládaře nad šeňky, i hlavu vládaře nad pekaři, mezi služebníky svými.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 21, 'A navrátil nejvyššího nad šeňky k místu jeho, aby podával koflíku Faraonovi do ruky.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 22, 'Vládaře pak nad pekaři oběsil, tak jakž jim byl sen vyložil Jozef.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 23, 'A nezpomenul správce nad šeňky na Jozefa, ale zapomenul na něj.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 1, 'Stalo se pak po dvou letech, měl Farao sen. Zdálo mu se, že stál nad potokem.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 2, 'A aj, z toho potoku vycházelo sedm krav, pěkných na pohledění a tlustých, kteréžto pásly se na mokřinách.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 3, 'A aj, sedm krav jiných vycházelo za nimi z potoku, šeredných na pohledění a hubených, kteréžto stály podlé oněch krav při břehu potoka.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 4, 'A ty krávy na pohledění šeredné a hubené sežraly oněch sedm krav na pohledění pěkných a tlustých. I procítil Farao.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 5, 'A když usnul zase, zdálo se jemu podruhé. A aj, sedm klasů vyrostlo z stébla jednoho, plných a pěkných.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 6, 'A aj, sedm klasů tenkých a východním větrem usvadlých vzcházelo za nimi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 7, 'A ti klasové tencí pohltili sedm oněch klasů zdařilých a plných. I procítiv Farao, a aj, byl sen.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 8, 'Když pak bylo ráno, zkormoucena byla mysl jeho; a poslav, svolal všecky hadače Egyptské, a všecky mudrce jejich. I vypravoval jim Farao sny své; a nebylo žádného, kdo by je vyložil Faraonovi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 9, 'Tedy mluvil nejvyšší šeňk Faraonovi takto: Na provinění své rozpomínám se dnes.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 10, 'Farao rozhněvav se na služebníky své, dal mne byl do vězení v domě nejvyššího nad drabanty, mne a správce nad pekaři.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 11, 'Měli jsme pak sen jedné noci, on i já, jeden každý podlé vyložení snu svého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 12, 'A byl tam s námi mládenec Hebrejský, služebník nejvyššího nad drabanty, jemuž když jsme vypravovali, vykládal nám sny naše; jednomu každému podlé snu jeho vykládal.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 13, 'A stalo se, že jakž vykládal nám, tak bylo: Já jsem navrácen k úřadu svému, a on oběšen.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 14, 'Tedy poslav Farao, povolal Jozefa, a rychle vypustili ho z žaláře. Kterýžto oholiv se, a změniv roucho své, přišel k Faraonovi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 15, 'I řekl Farao Jozefovi: Měl jsem sen, a není, kdo by jej vyložil; o tobě pak slyšel jsem to, že když uslyšíš sen, umíš jej vyložiti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 16, 'Odpověděl Jozef Faraonovi, řka: Není to má věc; Bůh oznámí šťastné věci Faraonovi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 17, 'Tedy řekl Farao Jozefovi: Zdálo mi se ve snách, že jsem stál na břehu potoka.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 18, 'A aj, z potoka toho vystupovalo sedm krav tlustých a pěkných, kteréžto pásly se na mokřinách.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 19, 'A aj, sedm jiných krav vystupovalo za nimi churavých a šeredných velmi a hubených; neviděl jsem tak šeredných ve vší zemi Egyptské.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 20, 'A sežraly krávy ty hubené a šeredné sedm krav prvnějších tlustých.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 21, 'A ač dostaly se do břicha jejich, však nebylo znáti, by se dostaly v střeva jejich; nebo na pohledění byly mrzké, jako i před tím. I procítil jsem.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 22, 'Viděl jsem také ve snách, ano sedm klasů vyrostlo z stébla jednoho plných a pěkných.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 23, 'A aj, sedm klasů drobných, tenkých a východním větrem usvadlých vycházelo za nimi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 24, 'I pohltili klasové ti drobní sedm klasů pěkných. Což když jsem vypravoval hadačům, nebyl, kdo by mi vyložil.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 25, 'Odpověděl Jozef Faraonovi: Sen Faraonův jednostejný jest. Což Bůh činiti bude, to ukázal Faraonovi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 26, 'Sedm krav pěkných jest sedm let, a sedm klasů pěkných tolikéž jest sedm let; sen jest jednostejný.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 27, 'Sedm pak hubených krav a šeredných, vystupujících za nimi, sedm let jest; a sedm klasů drobných a větrem východním usvadlých bude sedm let hladu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 28, 'Toť jest, což jsem mluvil Faraonovi: Což Bůh činiti bude, ukazuje Faraonovi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 29, 'Aj, sedm let nastane, v nichž hojnost veliká bude ve vší zemi Egyptské.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 30, 'A po nich nastane sedm let hladu,v nichž v zapomenutí přijde všecka ta hojnost v zemi Egyptské; a zhubí hlad zemi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 31, 'Aniž poznána bude hojnost ta v zemi, pro hlad, kterýž přijde potom; nebo velmi veliký bude.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 32, 'Že pak opětován jest sen Faraonovi podvakrát, znamená, že jistá věc jest od Boha, a že tím spíše Bůh vykoná to.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 33, 'Protož nyní ať vyhledá Farao muže opatrného a moudrého, kteréhož by ustanovil nad zemí Egyptskou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 34, 'To ať učiní Farao, a postaví úředníky nad zemí, a béře pátý díl z úrod země Egyptské, po sedm let hojných.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 35, 'Ať shromáždí všeliké potravy těch úrodných let nastávajících, a sklidí obilí k ruce Faraonovi; a potravy v městech ať se chovají pilně.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 36, 'A budou pokrmové ti za poklad zemi této k sedmi letům hladu, kteráž budou v zemi Egyptské, aby nebyla zkažena země tato hladem.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 37, 'I líbila se řeč ta Faraonovi i všechněm služebníkům jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 38, 'Tedy řekl Farao služebníkům svým: Najdeme-liž podobného tomuto muži, v němž by byl Duch Boží?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 39, 'Jozefovi pak řekl: Poněvadž Bůh dal znáti tobě všecko toto, neníť žádného tak rozumného a moudrého, jako ty jsi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 40, 'Ty budeš nad domem mým, a líbati bude tvář tvou všecken lid můj; stolicí toliko královskou vyšší nad tebe budu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 41, 'Řekl také Farao Jozefovi: Aj, ustanovil jsem tě nade vší zemí Egyptskou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 42, 'A sňav Farao prsten svůj s ruky své, dal jej na ruku Jozefovu, a oblékl ho v roucho kmentové, a vložil zlatý řetěz na hrdlo jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 43, 'A dal ho voziti na svém druhém voze, a volali před ním: Klanějte se! I ustanovil ho nade vší zemí Egyptskou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 44, 'A řekl Farao Jozefovi: Já jsem Farao, a bez dopuštění tvého nepozdvihne žádný ruky své ani nohy své ve vší zemi Egyptské.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 45, 'A dal Farao jméno Jozefovi Safenat Paneach, a dal mu Asenat dceru Putifera, knížete On, za manželku. I vyšel Jozef na zemi Egyptskou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 46, '(Jozef pak byl ve třidcíti letech, když stál před Faraonem králem Egyptským.) A vyšed od tváři Faraonovy, projel všecku zemi Egyptskou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 47, 'A vydala země po sedm let úrodných obilí hojnost.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 48, 'I nahromáždil všelijakých potrav v těch sedmi letech hojných v zemi Egyptské, a složil potravu tu v městech; úrody polní jednoho každého města, kteréž byly okolo něho, složil v něm.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 49, 'A tak nahromáždil Jozef obilí velmi mnoho, jako jest písku mořského, tak že přestali počítati; nebo mu nebylo počtu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 50, 'Jozefovi pak narodili se dva synové, prvé než přišel rok hladu, kteréž mu porodila Asenat, dcera Putifera, knížete On.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 51, 'A nazval Jozef jméno prvorozeného Manasses, řka: Nebo způsobil to Bůh, abych zapomenul na všecky práce své, a na všecken dům otce svého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 52, 'Jméno pak druhého nazval Efraim, řka: Nebo dal mi Bůh zrůst v zemi trápení mého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 53, 'Tedy pominulo sedm let hojných v zemi Egyptské;');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 54, 'A počalo sedm let hladu přicházeti, jakž byl předpověděl Jozef. I byl hlad po všech krajinách, ale po vší zemi Egyptské byl chléb.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 55, 'Potom také nedostatek trpěla všecka země Egyptská, a volal lid k Faraonovi o chléb. I řekl Farao všechněm Egyptským: Jděte k Jozefovi, což vám rozkáže, učiníte.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 56, 'A byl hlad na tváři vší země. Tedy otevřel Jozef všecky obilnice, v nichž obilí bylo, a prodával Egyptským; nebo rozmohl se hlad v zemi Egyptské.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 57, 'A všickni obyvatelé země přicházeli do Egypta k Jozefovi, aby kupovali; nebo rozmohl se byl hlad po vší zemi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 1, 'Vida pak Jákob, že by potrava byla v Egyptě, řekl synům svým: Co hledíte jeden na druhého?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 2, 'I mluvil jim: Aj, slyšel jsem, že mají potravu v Egyptě; jděte tam, a kupte nám odtud, abychom živi byli a nezemřeli.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 3, 'Tedy šlo deset bratrů Jozefových, aby nakoupili obilí v Egyptě.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 4, 'Ale Beniamina, bratra Jozefova, neposlal Jákob s bratřími jeho, nebo řekl: Aby se mu tam něco zlého nepřihodilo.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 5, 'I šli synové Izraelovi spolu s jinými, aby kupovali; nebo byl hlad v zemi Kananejské.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 6, 'Jozef pak byl nejvyšší správce v zemi té; on prodával obilí všemu lidu země. Tedy přišli bratří Jozefovi, a skláněli se před ním tváří až k zemi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 7, 'A uzřev Jozef bratří své, poznal je; a ukázal se k nim jako cizí, a tvrdě mluvil k nim,řka jim: Odkud jste přišli? I odpověděli: Z země Kananejské, abychom nakoupili potrav.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 8, 'Poznal, pravím, Jozef bratří své, ale oni nepoznali ho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 9, 'Tedy zpomenul Jozef na sny, kteréž měl o nich, a řekl jim: Špehéři jste, a přišli jste, abyste shlédli nepevná místa země.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 10, 'Kteřížto odpověděli jemu: Nikoli, pane můj, ale služebníci tvoji přišli, aby nakoupili pokrmů.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 11, 'Všickni my synové jednoho muže jsme, upřímí jsme; nikdyť jsou nebyli služebníci tvoji špehéři.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 12, 'Jimž zase řekl: Není tak, ale přišli jste, abyste shlédli nepevná místa země.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 13, 'Odpověděli oni: Dvanácte nás bratří služebníků tvých bylo, synů muže jednoho v zemi Kananejské; a aj, nejmladší s otcem naším nyní jest doma, a jednoho není.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 14, 'I řekl jim Jozef: Toť jest, což jsem mluvil vám, když jsem řekl: Špehéři jste.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 15, 'Touto věcí zkušeni budete: Živť jest Farao, že nevyjdete odsud, až přijde sem bratr váš mladší.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 16, 'Vyšlete z sebe jednoho, ať vezma, přivede bratra vašeho; vy pak u vězení zůstaňte, a zkušena budou vaše slova, pravdu-li jste mluvili. Pakli nic, živť jest Farao, že jste špehéři.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 17, 'Tedy dal je všecky spolu do vězení za tři dni.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 18, 'Třetího pak dne řekl jim Jozef: Toto učiňte, abyste živi byli; neboť já se bojím Boha.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 19, 'Jste-li šlechetní muži, jeden bratr váš ať jest ukován v žaláři, v němž jste byli; vy pak jděte, a odneste obilí k zapuzení hladu domů vašich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 20, 'Bratra pak svého mladšího přivedete ke mně; a pravdomluvná prokázána budou vaše slova, a nezemřete. Tedy učinili tak.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 21, 'I mluvil jeden k druhému: Jistě provinili jsme proti bratru svému. Nebo viděli jsme ssoužení duše jeho, když nás pokorně prosil, a nevyslyšeli jsme ho; protož přišlo na nás ssoužení toto.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 22, 'Odpověděl pak jim Ruben, řka: Zdaliž jsem tehdy vám nepravil těmito slovy: Nehřešte proti pacholeti. Ale neposlechli jste; pročež také krve jeho, hle, vyhledává se.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 23, 'A nevěděli oni, že by rozuměl Jozef; nebo skrze tlumače mluvil jim.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 24, 'A odvrátiv se od nich, plakal. Potom navrátiv se k nim, mluvil s nimi, a vzav Simeona z nich, svázal ho před očima jejich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 25, 'Přikázal pak Jozef, aby naplněni byli pytlové jejich obilím, a navráceny peníze jejich jednomu každému do pytle jeho, a aby dána jim byla potrava na cestu. I stalo se tak.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 26, 'A vloživše obilí svá na osly své, odešli odtud.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 27, 'A rozvázav jeden z nich pytel svůj, aby dal obrok oslu svému v hospodě, uzřel peníze své, kteréž byly na vrchu v pytli jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 28, 'I řekl bratřím svým: Navráceny jsou mi peníze mé, a aj, jsou v pytli mém. Tedy užasli se, a předěšeni jsouce, mluvili jeden k druhému: Což nám to učinil Bůh?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 29, 'Navrátivše se pak k Jákobovi otci svému do země Kananejské, vypravovali jemu všecko, co se jim přihodilo, pravíce:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 30, 'Muž ten, pán země, mluvil k nám tvrdě, a dal nás do vězení, jako špehéře země.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 31, 'A řekli jsme jemu: Upřímí jsme, nikdy jsme nebyli špehéři.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 32, 'Dvanácte bylo nás bratří, synů otce našeho, z nichž jednoho není, a mladší nyní jest s otcem naším v zemi Kananejské.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 33, 'I řekl nám muž ten, pán země té: Po tomto poznám, že upřímí jste: Bratra vašeho jednoho zanechte u mne, a obilí k zapuzení hladu od domů vašich vezmouce, odejděte.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 34, 'A přiveďte bratra svého mladšího ke mně, abych poznal, že nejste špehéři, ale upřímí; tehdy bratra vašeho vrátím vám, a budete moci v zemi této obchod vésti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 35, 'I stalo se, že, když vyprazdňovali pytle své, a aj, jeden každý měl uzlík peněz svých v pytli svém. Vidouce pak oni i otec jejich uzlíky peněz svých, báli se.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 36, 'I řekl jim Jákob otec jejich: Mne jste zbavili synů: Jozefa není, Simeona nemám, a Beniamina vezmete. Na mneť jsou se tyto všecky věci svalily.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 37, 'Tedy řekl Ruben otci svému těmito slovy: Dva syny mé zabí, jestliže ho nepřivedu zase k tobě; poruč ho v ruce mé, a já zase přivedu ho k tobě.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 38, 'I řekl: Nesstoupíť syn můj s vámi. Nebo bratr jeho umřel, a on sám pozůstal; a přihodilo-li by se mu co zlého na té cestě, kterouž půjdete, uvedli byste šediny mé s bolestí do hrobu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 1, 'Byl pak hlad veliký v krajině té.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 2, 'I stalo se, když vytrávili obilí, kteréž přinesli z Egypta, že řekl k nim otec jejich: Jděte zase, a nakupte nám něco potravy.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 3, 'I mluvil k němu Juda těmito slovy: Velice se zařekl muž ten, řka: Neuzříte tváři mé, nebude-li bratr váš s vámi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 4, 'Jestliže pošleš bratra našeho s námi, půjdeme a nakoupíme tobě potravy;');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 5, 'Pakli nepošleš, nepůjdeme. Nebo pověděl nám muž ten: Neuzříte tváři mé, nebude-li bratr váš s vámi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 6, 'I řekl Izrael: Proč jste mi tak zle učinili, oznámivše muži tomu, že máte ještě bratra?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 7, 'Odpověděli: Pilně vyptával se muž ten na nás, i na rod náš, mluvě: Jest-li živ ještě otec váš? Máte-li bratra? A dali jsme mu zprávu na ta slova. Zdaž jsme to jak věděti mohli, že dí: Přiveďte bratra svého?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 8, 'I řekl Juda Izraelovi, otci svému: Pošli to pachole se mnou, a vstanouce, půjdeme, abychom živi byli, a nezemřeli, i my, i ty, i maličcí naši.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 9, 'Já slibuji za něj; z ruky mé vyhledávej ho. Jestliže nepřivedu ho k tobě, a nepostavím ho před tebou, vinen budu hříchem tobě po všecky dny.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 10, 'A kdybychom byli neprodlévali, jistě již bychom se byli dvakrát vrátili.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 11, 'I řekl jim Izrael otec jejich: Jestližeť tak býti musí, učiňtež toto: Nabeřte nejvzácnějších užitků země do nádob svých, a doneste muži tomu dar, něco kadidla, a trochu strdi, a vonných věcí a mirry, daktylů a mandlů.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 12, 'Peníze také dvoje vezměte v ruce své, a peníze vložené na vrch do pytlů vašich zase doneste v rukou svých; snad z omýlení to přišlo.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 13, 'Bratra svého také vezměte, a vstanouce, jděte zase k muži tomu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 14, 'A Bůh silný všemohoucí dejž vám najíti milost před mužem tím, ať propustí vám onoho bratra vašeho i tohoto Beniamina. Jáť pak zbaven jsa synů, jako osiřelý budu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 15, 'Tedy vzali muži ti dar ten, a dvoje peníze vzali v ruce své, a Beniamina; a vstavše, sstoupili do Egypta, a postavili se před Jozefem.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 16, 'Vida pak Jozef Beniamina s nimi, řekl tomu, kterýž spravoval dům jeho: Uveď tyto muže do domu, a zabí hovado a připrav; nebo se mnou jísti budou muži ti o poledni.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 17, 'I učinil muž ten, jakž rozkázal Jozef, a uvedl ty lidi do domu Jozefova.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 18, 'Báli se pak muži ti, když uvedeni byli do domu Jozefova, a řekli: Pro ty peníze, kteréž prvé vloženy byly do pytlů našich, sem uvedeni jsme, aby obvině, obořil se na nás, a vzal nás za služebníky i osly naše.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 19, 'A přistoupivše k muži tomu, kterýž spravoval v domě Jozefově, mluvili k němu ve dveřích domu,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 20, 'A řekli: Slyš mne, pane můj. Přišli jsme byli ponejprvé kupovati potrav.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 21, 'I přihodilo se, když jsme do hospody přišli, a rozvazovali pytle své, a aj, peníze jednoho každého byly svrchu v pytli jeho, peníze naše podlé váhy své; a přinesli jsme je zase v rukou svých.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 22, 'Jiné také peníze přinesli jsme v rukou svých, abychom nakoupili potravy; nevíme, kdo jest zase vložil peníze naše do pytlů našich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 23, 'A on odpověděl: Mějte o to pokoj, nebojte se. Bůh váš, a Bůh otce vašeho dal vám poklad do pytlů vašich; penízeť jsem vaše já přijal. I vyvedl k nim Simeona.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 24, 'Uved tedy muž ten lidi ty do domu Jozefova, dal jim vody, aby umyli nohy své, dal také obrok oslům jejich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 25, 'Mezi tím připravili dar ten, dokudž nepřišel Jozef v poledne; nebo slyšeli, že by tu měli jísti chléb.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 26, 'Tedy přišel Jozef domů. I přinesli mu dar, kterýž měli v rukou svých, a klaněli se jemu až k zemi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 27, 'I ptal se jich, jak se mají, a řekl: Zdráv-liž jest otec váš starý, o němž jste pravili? Živ-li jest ještě?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 28, 'Kteřížto odpověděli: Zdráv jest služebník tvůj otec náš, a ještě živ jest. A sklánějíce hlavy, poklonu mu činili.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 29, 'Pozdvih pak očí svých, viděl Beniamina bratra svého, syna matky své, a řekl: Tento-li jest bratr váš mladší, o němž jste mi pravili? I řekl: Učiniž Bůh milost s tebou, synu můj!');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 30, 'Tedy pospíšil Jozef, (nebo pohnula se střeva jeho nad bratrem jeho,) a hledal, kde by mohl plakati; a všed do pokoje, plakal tam.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 31, 'Potom umyv tvář svou, vyšel zase, a zdržoval se, a řekl: Klaďte chléb.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 32, 'I kladli jemu zvláště, a jim obzvláště, Egyptským také, kteříž s ním jídali, obzvláštně; nebo nemohou Egyptští jísti s Židy chleba, proto že to ohavnost jest Egyptským.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 33, 'Tedy seděli proti němu, prvorozený podlé prvorozenství svého, a mladší podlé mladšího věku svého. I divili se muži ti vespolek.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 34, 'A bera jídlo před sebou, podával jim; Beniaminovi pak dostalo se pětkrát více než jiným. I hodovali a hojně se s ním napili.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 1, 'Rozkázal pak tomu, kterýž spravoval dům jeho, řka: Naplň pytle mužů těch potravou, co by jen unésti mohli; a peníze každého polož zas do pytle jeho na vrch.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 2, 'A koflík můj, koflík stříbrný, vlož na vrch do pytle mladšího s penězi jeho za obilí. I učinil podlé řeči Jozefovy, kterouž mluvil.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 3, 'Ráno pak propuštěni jsou ti muži, oni i oslové jejich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 4, 'A když vyšli z města, a nedaleko ještě byli, řekl Jozef správci domu svého: Vstaň, hoň muže ty, a dohoně se jich, mluv k nim: Pročež jste se odplatili zlým za dobré?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 5, 'Zdaliž to není ten koflík, z kteréhož píjí pán můj? A z tohoť on jistým zkušením pozná, jací jste vy. Zle jste učinili, co jste učinili.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 6, 'Tedy dohoniv se jich, mluvil jim slova ta.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 7, 'Kteřížto odpověděli jemu: Proč mluví pán můj taková slova? Odstup od služebníků tvých, aby co takového učinili.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 8, 'A my ty peníze, kteréž jsme našli na vrchu v pytlích svých, přinesli jsme tobě zase z země Kananejské; jakž bychom tedy krásti měli z domu pána tvého stříbro neb zlato?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 9, 'U koho z služebníků tvých nalezeno bude, nechžť umře ten; a my také budeme pána tvého služebníci.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 10, 'I řekl: Nu dobře, nechť jest podlé řeči vaší. U koho se nalezne, ten bude mým služebníkem, a vy budete bez viny.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 11, 'Protož rychle každý složil pytel svůj na zem, a rozvázal každý pytel svůj.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 12, 'I přehledával, od staršího počal, a na mladším přestal; i nalezen jest koflík v pytli Beniaminovu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 13, 'Tedy oni roztrhše roucha svá, vložil každý břímě na osla svého, a vrátili se do města.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 14, 'I přišel Juda s bratřími svými do domu Jozefova, (on pak ještě tam byl,) a padli před ním na zemi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 15, 'I dí jim Jozef: Jakýž jest to skutek, který jste učinili? Zdaž nevíte, že takový muž, jako jsem já, umí poznati?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 16, 'Tedy řekl Juda: Což díme pánu svému? co mluviti budeme? a čím se ospravedlníme? Bůhť jest našel nepravost služebníků tvých. Aj, služebníci jsme pána svého, i my i ten, u něhož nalezen jest koflík.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 17, 'Odpověděl Jozef: Odstup ode mne, abych to učinil. Muž, u něhož nalezen jest koflík, ten bude mým služebníkem; vy pak jděte u pokoji k otci svému.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 18, 'I přistoupil k němu Juda a řekl: Slyš mne, pane můj. Prosím, nechažť promluví služebník tvůj slovo v uši pána svého, a nehněvej se na služebníka svého; nebo jsi ty jako sám Farao.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 19, 'Pán můj ptal se služebníků svých, řka: Máte-li otce, neb bratra?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 20, 'A odpověděli jsme pánu mému: Máme otce starého, a pachole v starosti jeho zplozené malé, jehož bratr umřel, a on sám pozůstal po mateři své, a otec jeho miluje jej.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 21, 'I řekl jsi služebníkům svým: Přiveďte ho ke mně, a pohledím na něj.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 22, 'A řekli jsme pánu mému: Nemůžeť pachole opustiti otce svého; nebo opustí-li otce svého, on umře.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 23, 'Ty pak řekl jsi služebníkům svým: Nepřijde-li bratr váš mladší s vámi, nepokoušejte se více viděti tváři mé.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 24, 'I stalo se, když jsme se vrátili k služebníku tvému, otci mému, a jemu vypravovali slova pána svého,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 25, 'Že řekl otec náš: Jděte zase, nakupte nám něco potravy.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 26, 'Odpověděli jsme: Nemůžeme jíti, než bude-li bratr náš mladší s námi, tedy půjdeme; nebo bychom nemohli viděti tváři toho muže, nebyl-li by bratr náš nejmladší s námi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 27, 'I řekl nám služebník tvůj, otec můj: Vy víte, že dva toliko syny porodila mi žena má.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 28, 'A vyšel jeden ode mne, o němž jsem pravil: Jistě roztrhán jest, a neviděl jsem ho dosavad.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 29, 'Vezmete-li i tohoto ode mne, a přišlo by na něj něco zlého, tedy uvedete šediny mé s trápením do hrobu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 30, 'Tak tedy, když přijdu k služebníku tvému, otci svému, a pacholete nebude s námi, (ješto duše jeho spojena jest s duší tohoto):');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 31, 'Přijde na to, když uzří, že pacholete není, umře; a uvedou služebníci tvoji šediny služebníka tvého, otce svého, s žalostí do hrobu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 32, 'Nebo služebník tvůj slíbil za pachole, abych je vzal od otce svého, řka: Jestliže ho nepřivedu zase k tobě, tedy vinen budu hříchem otci mému po všecky dny.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 33, 'Protož nyní nechť zůstane, prosím, služebník tvůj místo pacholete tohoto za služebníka pánu svému, a pachole ať vstoupí s bratry svými.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 34, 'Nebo jak bych já vstoupil k otci svému, kdyby tohoto pacholete nebylo se mnou? Leč bych chtěl viděti trápení, kteréž by přišlo na otce mého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 1, 'Jozef pak nemoha se déle zdržeti, přede všemi přístojícími zvolal: Kažte všechněm ven! I nezůstal žádný s nimi, když se známil Jozef s bratřími svými.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 2, 'Potom pozdvihl hlasu svého s pláčem; a slyšeli to Egyptští, slyšel také dům Faraonův.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 3, 'I řekl Jozef bratřím svým: Já jsem Jozef. Ještě-li jest živ otec můj? A nemohli mu odpovědíti bratří jeho; nebo se ho velmi ulekli.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 4, 'Tedy řekl Jozef bratřím svým: Přistuptež medle ke mně. I přistoupili. A řekl: Já jsem Jozef bratr váš, kteréhož jste prodali do Egypta.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 5, 'Protož nyní nermuťte se, a neztěžujte sobě toho, že jste mne sem prodali; nebo pro zachování života vašeho poslal mne Bůh před vámi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 6, 'Nebo dvě létě již hlad jest v zemi, a ještě pět let přijde, v nichž nebudou orati, ani žíti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 7, 'Poslal mne, pravím, Bůh před vámi, pro zachování vás ostatků na zemi, a pro zachování životů vašich vysvobozením velikým.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 8, 'Tak tedy ne vy jste mne poslali sem, ale Bůh, kterýž mne dal za otce Faraonovi, a za pána všemu domu jeho, a panovníka po vší zemi Egyptské.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 9, 'Pospěšte a vstupte k otci mému, a rcete jemu: Toto praví syn tvůj Jozef: Učinil mne Bůh pánem všeho Egypta; přijdiž ke mně, neprodlévej.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 10, 'A bydliti budeš v zemi Gesen; a budeš blízko mne, ty i synové tvoji, i vnukové tvoji, stáda tvá, a volové tvoji, a cožkoli máš.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 11, 'A budu tě chovati tam, (nebo ještě pět let hlad bude), abys snad pro hlad nezahynul, ty i dům tvůj, a cožkoli máš.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 12, 'A aj, oči vaše vidí, i oči bratra mého Beniamina, že ústa má mluví vám.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 13, 'Povíte také otci mému o vší slávě mé v Egyptě, a což jste koli viděli; pospěštež tedy, a přiveďte otce mého sem.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 14, 'Tedy padl na šíji Beniamina bratra svého, a plakal; Beniamin také plakal na šíji jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 15, 'A políbiv všech bratří svých, plakal nad nimi; a potom mluvili bratří jeho s ním.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 16, 'Slyšána pak jest v domě Faraonově pověst tato: Přišli bratří Jozefovi. I bylo to velmi vděčné Faraonovi i všechněm služebníkům jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 17, 'A řekl Farao Jozefovi: Rci bratřím svým: Toto učiňte: Naložíce na hovada svá, jděte, a navraťte se do země Kananejské.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 18, 'A vezmouce otce svého a čeládky své, přiďte ke mně, a dám vám dobré místo v zemi Egyptské, a jísti budete tuk země této.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 19, 'Ty pak rozkaž jim: Toto učiňte: Vezměte sobě z země Egyptské vozy pro děti a ženy své, a vezměte otce svého, a přiďte.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 20, 'Aniž se ohlédejte na nábytky své; nebo nejlepší místo ve vší zemi Egyptské vaše bude.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 21, 'I učinili tak synové Izraelovi. A dal jim Jozef vozy podlé rozkázaní Faraonova; dal také jim pokrmy na cestu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 22, 'Všechněm jim dal, každému dvoje šaty; ale Beniaminovi dal tři sta stříbrných, a patery šaty jiné a jiné.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 23, 'Otci pak svému poslal tyto věci: Deset oslů, kteříž nesli z nejlepších věcí Egyptských, a deset oslic, kteréž nesly obilí, a chléb a pokrmy otci jeho na cestu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 24, 'A propouštěje bratří své, aby odešli, řekl jim: Nevaďtež se na cestě.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 25, 'Tedy brali se z Egypta, a přišli do země Kananejské k Jákobovi otci svému.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 26, 'A zvěstovali jemu, řkouce: Jozef ještě živ jest, ano i panuje ve vší zemi Egyptské. I omdlelo srdce jeho; nebo slyšev to nevěřil jim.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 27, 'Tedy vypravovali jemu všecka slova Jozefova, kteráž mluvil jim; a vida vozy, kteréž poslal Jozef pro něho, okřál duch Jákoba otce jejich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 28, 'I řekl Izrael: Dostiť jest, když ještě syn můj živ jest; půjdu a uzřím ho, prvé než umru.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 1, 'Tedy bral se Izrael se vším, což měl; a přišed do Bersabé, obětoval oběti Bohu otce svého Izáka.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 2, 'I mluvil Bůh Izraelovi u vidění nočním, řka: Jákobe, Jákobe! Kterýžto odpověděl: Aj, teď jsem.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 3, 'I řekl: Já jsem ten Bůh silný, Bůh otce tvého. Neboj se sstoupiti do Egypta, nebo v národ veliký tam tebe učiním.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 4, 'Já sstoupím s tebou do Egypta, a já tě také i zase přivedu; a Jozef položí ruku svou na oči tvé.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 5, 'Vstal tedy Jákob z Bersabé; a synové Izraelovi vzali Jákoba otce svého, a děti své s ženami svými na vozy, kteréž poslal pro něho Farao.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 6, 'Pobrali také dobytek svůj, a zboží své, kteréhož nabyli v zemi Kananejské; a přišli do Egypta, Jákob i všecko símě jeho s ním.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 7, 'Syny i vnuky, dcery i vnučky své, a všecku rodinu svou uvedl s sebou do Egypta.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 8, 'A tato jsou jména synů Izraelových, kteříž vešli do Egypta: Jákob a synové jeho. Prvorozený Jákobův Ruben.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 9, 'A synové Rubenovi: Enoch, Fallu, Ezron a Charmi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 10, 'Synové pak Simeonovi: Jamuel, Jamin, Ahod, Jachin, Sohar a Saul, syn jedné ženy Kananejské.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 11, 'Synové Léví: Gerson, Kahat a Merari.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 12, 'Synové Judovi: Her, Onan, Séla, Fáres a Zára. (Ale umřel Her a Onan v zemi Kananejské.) Fáres pak měl syny: Ezrona a Hamule.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 13, 'Synové Izacharovi: Tola, Fua, Job a Simron.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 14, 'A synové Zabulonovi: Sared, Elon a Jahelel.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 15, 'Tiť jsou synové Líe, kteréž porodila Jákobovi v Pádan Syrské, a Dínu, dceru jeho. Všech duší synů i dcer jeho bylo třidceti a tři.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 16, 'Synové Gád: Sefon, Aggi, Suni, Esebon, Heri, Arodi a Areli.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 17, 'Synové Asser: Jemna, Jesua, Jesui, Beria, a Serach sestra jejich. Synové pak Beriovi: Heber a Melchiel.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 18, 'To jsou synové Zelfy, kterouž Lában dal Líe dceři své; a ty porodila Jákobovi, šestnácte duší.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 19, 'Synové pak Ráchel, manželky Jákobovy: Jozef a Beniamin.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 20, 'A Jozefovi narodili se v zemi Egyptské z Asenat, dcery Putifera knížete On, Manasses a Efraim.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 21, 'Ale synové Beniaminovi: Béla, Becher, Asbel, Gera, Náman, Echi, Roz, Mufim, Chuppim a Ared.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 22, 'Tiť jsou synové Ráchel, kteréž porodila Jákobovi; všech duší čtrnáct.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 23, 'A syn Danův: Chusim.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 24, 'Synové pak Neftalím: Jaziel, Guni, Jezer a Sallem.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 25, 'Ti jsou synové Bály, kterouž Lában dal Ráchel dceři své, a ty porodila Jákobovi; všech duší sedm.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 26, 'Všech duší, kteréž vešly s Jákobem do Egypta, což jich pošlo z bedr jeho, kromě žen synů Jákobových, všech duší bylo šedesáte a šest.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 27, 'K tomu synové Jozefovi, kteříž se jemu narodili v Egyptě, dva. A tak všech duší domu Jákobova, kteréž vešly do Egypta, bylo sedmdesáte.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 28, 'Poslal pak Judu napřed k Jozefovi, aby oznámil jemu prvé, než přišel do Gesen. A tak přišli do země Gesen.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 29, 'Jozef pak zapřáh do svého vozu, vyjel vstříc Izraelovi otci svému do Gesen; a jakž ho Jákob uzřel, padl na jeho šíji, a plakal dlouho na šíji jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 30, 'I řekl Izrael Jozefovi: Nechť již umru, když jsem viděl tvář tvou; nebo ty ještě jsi živ.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 31, 'Jozef pak řekl bratřím svým a domu otce svého: Pojedu a zvěstuji Faraonovi, a dím jemu: Bratří moji a dům otce mého, kteříž bydlili v zemi Kananejské, přišli ke mně.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 32, 'Ale jsou pastýři stáda, nebo s dobytkem se obírají; protož ovce své a voly, i cožkoli mají, přihnali.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 33, 'A když by povolal vás Farao, a řekl: Jaký jest obchod váš?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 34, 'Odpovíte: Dobytkem se živili služebníci tvoji od mladosti své až do této chvíle, i my i otcové naši; abyste bydlili v zemi Gesen; nebo v mrzkosti mají Egyptští všecky pastýře stáda.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 1, 'A protož přišed Jozef, oznámil Faraonovi, a řekl: Otec můj a bratří moji, s drobným i větším dobytkem svým i se vším, což mají, přišli z země Kananejské, a aj, jsou v zemi Gesen.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 2, 'A vzav z počtu bratří svých pět mužů, postavil je před Faraonem.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 3, 'I řekl Farao bratřím jeho: Jaký jest obchod váš? Kteřížto odpověděli Faraonovi: Pastýři ovcí jsou služebníci tvoji, i my, i otcové naši.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 4, 'Řekli ještě Faraonovi: Abychom pohostinu byli v zemi této, přišli jsme; nebo není pastvy dobytku, kterýž mají služebníci tvoji, nebo hlad veliký jest v zemi Kananejské; protož nyní prosíme, nechať bydlí služebníci tvoji v zemi Gesen.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 5, 'I mluvil Farao Jozefovi, řka: Otec tvůj a bratří tvoji přišli k tobě.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 6, 'Země Egyptská před tebou jest; v nejlepším kraji země této osaď otce svého a bratří své, nechť bydlí v zemi Gesen. A srozumíš-li, že jsou mezi nimi muži rozšafní, ustanovíš je úředníky nad dobytkem, kterýž mám.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 7, 'Uvedl také Jozef Jákoba otce svého, a postavil ho před Faraonem; a pozdravil Jákob Faraona.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 8, 'Tedy řekl Farao k Jákobovi: Kolik jest let života tvého?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 9, 'Odpověděl Jákob Faraonovi: Dnů let putování mého sto a třidceti let jest; nemnozí a zlí byli dnové let života mého, a nedošli dnů let života otců mých, v nichž živi byli.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 10, 'A požehnav Jákob Faraona, vyšel od něho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 11, 'I osadil Jozef otce svého a bratří své, a dal jim vládařství v zemi Egyptské v kraji výborném, v zemi Ramesses, jakž rozkázal Farao.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 12, 'A opatroval Jozef otce svého, a bratří své, a všecken dům jeho chlebem, až do nejmenších.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 13, 'A chleba nebylo ve vší zemi; nebo veliký hlad byl velmi, a trápení veliké bylo na zemi Egyptské a zemi Kananejské od hladu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 14, 'Shromáždil pak Jozef všecky peníze, což jich nalezeno v zemi Egyptské a v zemi Kananejské, za potravy, kteréž kupovali; a vnesl Jozef peníze do domu Faraonova.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 15, 'A když utratili peníze z země Egyptské a z země Kananejské, přicházeli všickni Egyptští k Jozefovi, řkouce: Dej nám chleba; nebo proč mříti máme před tebou pro nedostatek peněz?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 16, 'I řekl Jozef: Dejte dobytky své, a dám vám chleba za dobytky vaše, poněvadž se vám peněz nedostává.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 17, 'Tedy přivedli dobytky své k Jozefovi; i dal jim Jozef potrav za koně a za stáda ovcí, a za stáda volů i za osly; a přechoval je chlebem, za všecky dobytky jejich, toho roku.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 18, 'A po roce tom přišli k němu léta druhého, a řekli mu: Nebudeme tajiti před pánem svým, že jsme všecky peníze utratili, i stáda dobytků jsou u pána našeho; nezůstávají nám před pánem naším kromě těla naše a dědiny naše.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 19, 'I proč máme mříti před očima tvýma? I my i rolí naše hyne. Kup nás i rolí naši za chléb, a budeme my i rolí naše ve službě Faraonovi; a dej nám semena, abychom živi byli a nezemřeli, a rolí aby nespustla.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 20, 'Tedy koupil Jozef všecku zemi Egyptskou Faraonovi; nebo prodali Egyptští jeden každý pole své, proto že se rozmohl mezi nimi hlad. I dostala se země Faraonovi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 21, 'Lid pak převedl do měst, od jednoho pomezí Egyptského až do druhého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 22, 'Rolí toliko kněžských nekoupil. Nebo kněží uloženou potravu měli od Faraona, a jedli z uložených pokrmů svých, kteréž dával jim Farao; protož neprodali rolí svých.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 23, 'I řekl Jozef lidu: Aj, koupil jsem vás dnes i rolí vaše Faraonovi; teď máte semeno, osívejtež tedy ji.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 24, 'A když se urodí, dáte pátý díl Faraonovi, a čtyři díly zůstavíte sobě k semenu a ku pokrmu svému a těm, kteříž jsou v domích vašich, i ku pokrmu dítkám svým.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 25, 'Tedy řekli: Zachoval jsi životy naše. Nechať nalezneme milost v očích pána svého, a budeme služebníci Faraonovi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 26, 'I ustanovil to Jozef za právo až do tohoto dne, po vší zemi Egyptské, aby dáván byl Faraonovi pátý díl; toliko samy rolí kněžské nebyly Faraonovy.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 27, 'A tak bydlil Izrael v zemi Egyptské v krajině Gesen; a osadili se v ní, a rozplodili se, a rozmnoženi jsou velmi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 28, 'Živ pak byl Jákob v zemi Egyptské sedmnácte let; a bylo dnů Jákobových, a let života jeho, sto čtyřidceti sedm let.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 29, 'I přiblížili se dnové Izraelovi, aby umřel. A povolav syna svého Jozefa, řekl jemu: Jestliže jsem nalezl milost v očích tvých, vlož, prosím, ruku svou pod bedro mé, a učiň se mnou milosrdenství a pravdu. Prosím, nepochovávej mne v Egyptě.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 30, 'Když spáti budu s otci svými, vyneseš mne z Egypta, a pochováš mne v hrobě jejich. Tedy řekl jemu: Já učiním podlé slova tvého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 31, 'I řekl Jákob: Přisáhni mi. Tedy přisáhl jemu. I sklonil se Izrael k hlavám lůže.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 1, 'Stalo se pak potom, že povědíno jest Jozefovi: Aj, otec tvůj nemocen jest. I vzal s sebou dva syny své, Manasse a Efraima.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 2, 'Tedy oznámeno jest Jákobovi a povědíno: Aj, syn tvůj Jozef přišel k tobě.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 3, 'A posilniv se Izrael, usadil se na ložci a řekl Jozefovi: Bůh silný všemohoucí ukázav mi se v Lůza v zemi Kananejské, požehnal mi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 4, 'A řekl ke mně: Aj, já rozplodím tě a rozmnožím tebe, a učiním tě v zástupy lidí; dám také zemi tuto semeni tvému po tobě za dědictví věčné.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 5, 'Protož nyní, dva synové tvoji, kteřížť jsou se zrodili v zemi Egyptské, prvé než jsem přišel k tobě do Egypta, moji jsou; Efraim a Manasses budou mi jako Ruben a Simeon.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 6, 'Ale děti, kteréž po těchto zplodíš, tvoji budou; jménem bratří svých jmenováni budou v dědictvích svých.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 7, 'Nebo když jsem se vracel z Pádan, umřela mi Ráchel v zemi Kananejské na cestě, když již nedaleko bylo do Efraty; a pochoval jsem ji tam u cesty k Efratě, jenž jest Betlém.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 8, 'Uzřev potom Izrael syny Jozefovy, řekl: Kdo jsou onino?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 9, 'Odpověděl Jozef otci svému: Synové moji jsou, kteréž dal mi Bůh zde. I řekl:Přiveď je medle ke mně, a požehnám jim');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 10, '(Oči pak Izraelovy mdlé byly pro starost, a nemohl dobře viděti.) I přivedl je k němu, a on líbal a objímal je.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 11, 'I řekl Izrael Jozefovi: Nemyslilť jsem já, abych měl kdy viděti tvář tvou, a aj, dal mi Bůh, abych viděl i símě tvé.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 12, 'Tedy vzav je Jozef z klína jeho, sklonil se tváří až k zemi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 13, 'A vzav oba, Efraima na pravou stranu sobě, Izraelovi pak na levou, a Manassesa na levou sobě, Izraelovi pak na pravou, postavil je před ním.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 14, 'Tedy vztáh Izrael pravici svou, vložil ji na hlavu Efraimovu, kterýž byl mladší, levici pak svou na hlavu Manassesovu, naschvál přeloživ ruce, ačkoli Manasses byl prvorozený.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 15, 'I požehnal Jozefovi, řka: Bůh, před jehož oblíčejem ustavičně chodili otcové moji Abraham a Izák, Bůh, kterýž mne spravoval po všecken život můj až do dne tohoto;');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 16, 'Anděl ten, kterýž vytrhl mne ze všeho zlého, požehnejž dítek těchto; a ať slovou synové moji a synové otců mých Abrahama a Izáka; a ať se jako hmyz rozmnoží u prostřed země.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 17, 'Vida pak Jozef, že vložil otec jeho ruku svou pravou na hlavu Efraimovu, nerád byl tomu. I zdvihl ruku otce svého, aby ji přenesl s hlavy Efraimovy na hlavu Manassesovu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 18, 'A řekl jemu: Ne tak, otče můj; nebo toto jest prvorozený, vložiž pravici svou na hlavu jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 19, 'Ale nepovolil otec jeho, a řekl: Vím, synu můj, vím; takéť i on bude v lid, a také i on vzroste; však bratr jeho mladší více poroste než on, a símě jeho bude u veliké množství národů.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 20, 'I požehnal jim v ten den, řka: Skrze tebe požehnání bude dávati Izrael takto: Učiniž tobě Bůh jako Efraimovi a jako Manassesovi. I představil Efraima Manassesovi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 21, 'Řekl také Izrael Jozefovi: Aj, já umírám, a budeť Bůh s vámi, a zase vás přivede do země otců vašich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 22, 'Já pak dal jsem tobě jeden díl výš nad bratří tvé, kteréhož jsem mečem svým a lučištěm svým dosáhl z ruky Amorejského.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 1, 'Povolal pak Jákob synů svých, a řekl: Sejděte se, a oznámím vám, co se s vámi díti bude potomních dnů.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 2, 'Shromažďte se a slyšte synové Jákobovi, poslyšte Izraele otce svého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 3, 'Ruben, prvorozený můj jsi ty, síla má, a počátek moci mé, vyvýšenost důstojenství a vyvýšenost síly.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 4, 'Prudce sběhneš jako voda. Nebudeš vyvýšen, proto že jsi vstoupil na lůže otce svého; a jakž jsi poškvrnil postele mé, zmizelo vyvýšení tvé.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 5, 'Simeon a Léví bratří, nástrojové nepravosti jsou v příbytcích jejich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 6, 'Do tajné rady jejich nevcházej duše má, k shromáždění jejich nepřipojuj se slávo má; nebo v prchlivosti své zbili muže, a svévolně vyvrátili zed.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 7, 'Zlořečená prchlivost jejich, nebo neustupná; i hněv jejich, nebo zatvrdilý jest. Rozdělím je v Jákobovi, a rozptýlím je v Izraeli.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 8, 'Judo, ty jsi, tebe chváliti budou bratří tvoji; ruka tvá bude na šíji nepřátel tvých; klaněti se budou tobě synové otce tvého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 9, 'Lvíče Juda, z loupeže, synu můj, vrátil jsi se; schýliv se, ležel jako lev a jako lvice; kdo zbudí ho?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 10, 'Nebude odjata berla od Judy, ani vydavatel zákona od noh jeho, dokudž nepřijde Sílo; a k němu se shromáždí národové.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 11, 'Uváže k vinnému kmenu osle své, a k výbornému kmenu oslátko oslice své. Práti bude u víně roucho své, a v červeném víně oděv svůj.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 12, 'Červenějších očí bude nad víno, a zubů bělejších nad mléko.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 13, 'Zabulon bydliti bude na břehu mořském, a na přístavu lodí, a pomezí jeho až k Sidonu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 14, 'Izachar osel silný, ležící mezi dvěma břemeny.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 15, 'A vida odpočinutí, že jest dobré, a zemi, že jest rozkošná, sehne rameno své k nošení, a dávati bude daně.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 16, 'Dan souditi bude lid svůj, jako jedno z pokolení Izraelských.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 17, 'Budeť Dan jako had podlé cesty, jako had rohatý podlé stezky, štípaje kopyta koně, aby spadl jezdec jeho zpět.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 18, 'Spasení tvého očekávám, ó Hospodine!');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 19, 'Gád, vojsko přemůže jej, však on svítězí potom.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 20, 'Asser, tučný bude pokrm jeho, a onť vydávati bude rozkoše královské.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 21, 'Neftalím jako laň vypuštěná, vydávaje výmluvnosti krásné.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 22, 'Ratolest rostoucí Jozef, ratolest rostoucí podlé studnice; ratolesti vycházely nad zed.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 23, 'Ačkoli hořkostí naplnili jej, a stříleli na něj, a v tajné nenávisti měli ho střelci:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 24, 'Však zůstalo v síle lučiště jeho, a zsilila se ramena rukou jeho z rukou mocného Jákobova; odkudž byl pastýř a kámen Izraelův;');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 25, 'Od silného Boha, jemuž sloužil otec tvůj, kterýž spomáhá tobě, a od všemohoucího, kterýž požehná tobě požehnáními nebeskými s hůry, požehnáními propasti ležící hluboko, požehnáním prsů a života.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 26, 'Požehnání otce tvého silnější budou nad požehnání předků mých, až k končinám pahrbků věčných; budou nad hlavou Jozefovou, a na vrchu hlavy Nazarejského mezi bratřími jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 27, 'Beniamin, vlk dravý, ráno bude jísti loupež, a večer rozdělí kořisti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 28, 'Všech těchto pokolení Izraelských jest dvanácte; a to jest, což mluvil jim otec jejich; požehnal jim také, jednomu každému vedlé požehnání jeho požehnal.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 29, 'A poroučeje jim, řekl: Já připojen budu k lidu svému; pochovejte mne s otci mými v jeskyni té, kteráž jest na poli Efrona Hetejského,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 30, 'V jeskyni, kteráž jest na poli Machpelah, jenž jest naproti Mamre v zemi Kananejské, kterouž koupil Abraham spolu s polem tím od Efrona Hetejského k dědičnému pohřbu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 31, 'Tam pochovali Abrahama a Sáru ženu jeho; tam pochovali Izáka a Rebeku ženu jeho; tam také pochovali Líu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 32, 'Koupeno pak bylo pole a jeskyně, kteráž na něm, od synů Het.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 33, 'A když přestal Jákob přikazovati synům svým, složil nohy své na ložci a umřel; a připojen jest k lidu svému.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 1, 'Tedy padl Jozef na tvář otce svého, a plakal nad ním, líbaje ho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 2, 'A poručil služebníkům svým lékařům, aby vonnými věcmi pomazali otce jeho. I pomazali lékaři vonnými věcmi Izraele.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 3, 'A vyplnilo se při něm čtyřidceti dní; (nebo tak vyplňují se dnové těch, kteříž mazáni bývají vonnými věcmi). I plakali ho Egyptští za sedmdesáte dní.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 4, 'Když pak dnové pláče toho pominuli, mluvil Jozef k domu Faraonovu, řka: Jestliže jsem nyní nalezl milost před očima vašima, mluvte, prosím, v uši Faraonovy, a rcete:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 5, 'Otec můj přísahou mne zavázal, řka: Aj, já umírám; v hrobě mém, kterýž jsem sobě vykopal v zemi Kananejské, tam mne pochovej. Nyní tedy, prosím, nechť vstoupím a pochovám otce svého, a navrátím se zase.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 6, 'I řekl Farao: Vstup a pochovej otce svého tak, jakž tě přísahou zavázal.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 7, 'Tedy vstoupil Jozef, aby pochoval otce svého, a vstoupili s ním všickni služebníci Faraonovi, starší domu jeho a všickni starší země Egyptské,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 8, 'Všecken také dům Jozefův, a všickni bratří jeho i dům otce jeho; toliko dětí svých, ovec a volů nechali v zemi Gesen.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 9, 'Vstoupili s ním také i vozové a jezdci, a bylo vojsko to veliké velmi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 10, 'I přišli až k místu Atád, kteréž jest při brodu Jordánském, a kvílili tam kvílením velikým a velmi žalostným; i držel tu zámutek po otci svém za dnů sedm.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 11, 'Vidouce pak obyvatelé země té, totiž Kananejští, zámutek na místě tom Atád, řekli: Těžký to mají zámutek Egyptští. Protož nazváno jest jméno jeho Abel Mizraim, a to jest při brodu Jordánském.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 12, 'Učinili tedy s ním synové jeho tak, jakž jim byl poručil.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 13, 'A donesše ho do země Kananejské, pochovali ho v jeskyni na poli Machpelah, kterouž byl koupil Abraham s tím polem k dědičnému pohřbu od Efrona Hetejského, naproti Mamre.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 14, 'A když pochoval Jozef otce svého, navrátil se do Egypta s bratřími svými a se všemi, kteříž byli vstoupili s ním, aby pochovali otce jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 15, 'Vidouce pak bratří Jozefovi, že umřel otec jejich, řekli: Snad v nenávisti nás míti bude Jozef, a vrchovatě nahradí nám všecko zlé, kteréž jsme jemu činili.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 16, 'Protož vzkázali Jozefovi, řkouce: Otec tvůj ještě před smrtí svou přikázal, řka:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 17, 'Takto díte Jozefovi: Prosím, odpusť již bratřím svým přestoupení a hřích jejich; nebo zle učinili tobě. Protož již odpusť, prosím, přestoupení služebníkům Boha, jehož ctil otec tvůj. I rozplakal se Jozef, když k němu mluvili.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 18, 'Přistoupili potom také bratří jeho, a padše před ním, řekli: Aj, my jsme služebníci tvoji.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 19, 'Jimž odpověděl Jozef: Nebojte se; nebo zdaliž jsem já vám za Boha?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 20, 'Vy zajisté skládali jste proti mně zlé; ale Bůh obrátil to v dobré, aby učinil to, což vidíte nyní, a při životu zachoval lid mnohý.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 21, 'Protož nebojte se již; já chovati vás budu i děti vaše. A tak těšil je, a mluvil k srdci jejich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 22, 'Bydlil pak Jozef v Egyptě, on i dům otce jeho, a živ byl Jozef sto a deset let.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 23, 'A viděl Jozef syny Efraimovy až do třetího pokolení; ano i synové Machira, syna Manassesova, vychováni jsou u Jozefa.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 24, 'Mluvil potom Jozef bratřím svým: Já tudíž umru; Bůh pak jistotně navštíví vás, a vyvede vás z země této do země, kterouž přisáhl Abrahamovi, Izákovi a Jákobovi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 25, 'Protož přísahou zavázal Jozef syny Izraelovy, řka: Když navštíví vás Bůh, vynestež kosti mé odsud.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 26, 'I umřel Jozef, když byl ve stu a v desíti letech; a pomazán jsa vonnými věcmi, vložen jest do truhly v Egyptě.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 1, 'Tato jsou pak jména synů Izraelských, kteříž vešli do Egypta s Jákobem; každý s čeledí svou přišel:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 2, 'Ruben, Simeon, Léví a Juda;');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 3, 'Izachar, Zabulon a Beniamin;');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 4, 'Dan a Neftalím, Gád a Asser.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 5, 'A bylo všech osob pošlých z bedr Jákobových sedmdesáte duší; Jozef pak byl v Egyptě.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 6, 'I umřel Jozef a všickni bratří jeho, a všecken ten rod.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 7, 'Synové pak Izraelští rozmnožili se a rodili se v hojnosti; a rozhojňovali se, i zsilili se náramně velmi, a naplněna jest jimi země.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 8, 'V tom povstal král nový v Egyptě, kterýž neznal Jozefa.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 9, 'Ten řekl lidu svému: Aj, lid synů Izraelských jest mnohý a silnější nad nás.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 10, 'Nuže, opatrně sobě počínejme před ním, aby se nerozmohl; a když by přišla válka, aby se nepřipojil i on k nepřátelům našim, a nebojoval proti nám, a nevyšel z země.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 11, 'Protož ustanovili nad ním úředníky, kteříž by plat vybírali, aby je trápili břemeny svými. I vystavěl lid Izraelský Faraonovi města skladů, Fiton a Ramesses.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 12, 'Ale čím více trápili jej, tím více rostl a tím se více rozmáhal. I vzali sobě syny Izraelské v ošklivost.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 13, 'A tak podrobovali Egyptští syny Izraelské v službu těžkou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 14, 'A k hořkosti přivodili život jejich robotami těžkými, v hlině a cihlách a ve všelijakém díle na poli, mimo všelikou potřebu svou, k níž práce jejich užívali nenáležitě a bez lítosti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 15, 'I poručil král Egyptský babám Hebrejským, z nichž jedna sloula Sefora a druhá Fua,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 16, 'A řekl: Když budete pomáhati ženám Hebrejským při porodu, a uzříte, že již rodí, byl-li by syn, zabíte ho, pakli dcera, tedy ať jest živa.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 17, 'Bály se pak ty baby Boha, a nečinily tak, jakž jim poručil král Egyptský, ale živých nechávaly pacholíků.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 18, 'Povolav tedy bab král Egyptský, mluvil jim: Proč jste to učinily, že jste živé zachovaly pacholíky?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 19, 'I odpověděly baby Faraonovi: Nejsou ženy Hebrejské jako ženy Egyptské; nebo ony jsou silnějšího přirození. Dříve než přijde k nim baba, ony porodí.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 20, 'I učinil dobře Bůh těm babám. A rozmnožen jest lid, a zsilili se velmi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 21, 'Stalo se pak proto, že se bály baby ty Boha, vzdělal jim domy.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 22, 'I přikázal Farao všemu lidu svému, řka: Každého syna, kterýž se narodí, do řeky uvrzte; každé pak dcery nechte živé.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 1, 'Odšed pak muž jeden z domu Léví, vzal dceru z pokolení Léví.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 2, 'I počala žena ta, a porodila syna; a viduci, že jest krásný, kryla ho za tři měsíce.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 3, 'A když ho nemohla déle tajiti, vzala mu ošitku z sítí, a omazala ji klím a smolou; a vložila do ní to dítě, a vyložila do rákosí u břehu řeky.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 4, 'A postavila sestru jeho zdaleka, aby zvěděla, co se s ním díti bude.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 5, 'A v tom sešla dcera Faraonova, aby se myla v řece; a děvečky její procházely se po břehu řeky. A uzřevši ošitku mezi rákosím, poslala děvečku svou, a vzala ji.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 6, 'A když otevřela, uzřela dítě; a aj, plakalo pacholátko. A slitovavši se nad ním, řekla: Z dětí Hebrejských jest toto.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 7, 'I řekla sestra jeho k dceři Faraonově: Mám-li jíti a zavolati tobě chůvy z žen Hebrejských, kteráž by odchovala tobě dítě?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 8, 'Odpověděla dcera Faraonova: Jdi. Tedy šla děvečka a zavolala matky toho dítěte.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 9, 'I řekla jí dcera Faraonova: Vezmi toto dítě, a odchovej mi je; a jáť dám mzdu tvou. I vzala žena dítě, a chovala je.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 10, 'A když odrostlo pachole, dovedla je k dceři Faraonově, kteráž jej měla za syna; a nazvala jméno jeho Mojžíš, řkuci: Nebo jsem ho z vody vytáhla.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 11, 'I stalo se ve dnech těch, když vyrostl Mojžíš, že vyšel k bratřím svým, a hleděl na trápení jejich. Uzřel také muže Egyptského, an tepe muže Hebrejského, jednoho z bratří jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 12, 'A sem i tam se ohlédna, vida, že žádného tu není, zabil Egyptského, a zahrabal jej v písku.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 13, 'Vyšed potom druhého dne, a aj, dva muži Hebrejští vadili se. I řekl tomu, kterýž křivdu činil: Proč tepeš bližního svého?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 14, 'Kterýžto odpověděl: Kdo tě ustanovil knížetem a soudcí nad námi? Zdali zabiti mne myslíš, jako jsi zabil Egyptského? Protož ulekl se Mojžíš a řekl: Jistě známá jest ta věc.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 15, 'A uslyšav Farao tu věc, hledal zabiti Mojžíše. Ale Mojžíš utekl od tváři Faraonovy, a bydlil v zemi Madianské; i usadil se podlé studnice.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 16, 'Kníže pak Madianské mělo sedm dcer. Kteréžto přišedše, vážily vodu, a nalívaly do koryt, aby napájely dobytek otce svého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 17, 'I přišli pastýři, a odehnali je. Tedy Mojžíš vstav, pomohl jim a napojil dobytek jejich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 18, 'A když se navrátily k Raguelovi, otci svému, řekl on: Jakž jste to dnes tak brzo přišly?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 19, 'Odpověděly: Muž Egyptský vysvobodil nás z ruky pastýřů; ano také ochotně navážil nám vody, a napojil dobytek.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 20, 'I řekl dcerám svým: Kdež pak jest? Pročež jste pustily muže toho? Povolejte ho, ať pojí chleba.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 21, 'A svolil Mojžíš k tomu, aby bydlil s mužem tím. Kterýžto dal Zeforu, dceru svou, Mojžíšovi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 22, 'I porodila syna, a nazval jméno jeho Gerson; nebo řekl: Příchozí jsem byl v zemi cizí.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 23, 'Stalo se pak po mnohých časích, že umřel král Egyptský; a synové Izraelští úpěli pro roboty, a křičeli. I vstoupil k Bohu křik jejich pro roboty.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 24, 'A uslyšel Bůh naříkání jejich, a rozpomenul se Bůh na smlouvu svou s Abrahamem, Izákem a Jákobem.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 25, 'I vzhlédl Bůh na syny Izraelské, a poznal Bůh.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 1, 'Mojžíš pak pásl dobytek Jetry tchána svého, kněze Madianského, a hnav stádo po poušti, přišel až k hoře Boží Oréb.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 2, 'Tedy ukázal se mu anděl Hospodinův v plameni ohně z prostředku kře. I viděl, a aj, keř hořel ohněm, a však neshořel.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 3, 'Protož řekl Mojžíš: Půjdu nyní, a spatřím vidění toto veliké, proč neshoří keř.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 4, 'Vida pak Hospodin, že jde, aby pohleděl, zavolal naň Bůh z prostředku kře, a řekl: Mojžíši, Mojžíši! Kterýžto odpověděl: Aj, teď jsem.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 5, 'I řekl: Nepřistupuj sem, szuj obuv svou s noh svých; nebo místo, na kterémž ty stojíš, země svatá jest.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 6, 'A řekl: Já jsem Bůh otce tvého, Bůh Abrahamův, Bůh Izákův, a Bůh Jákobův. I zakryl Mojžíš tvář svou, (nebo se bál), aby nepatřil na Boha.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 7, 'Jemužto řekl Hospodin: Zřetelně viděl jsem trápení lidu mého, kterýž jest v Egyptě; a křik jejich pro přísnost úředníků jeho slyšel jsem; nebo znám bolesti jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 8, 'Protož jsem sstoupil, abych vysvobodil jej z ruky Egyptských, a vyvedl jej z země té do země dobré a prostranné, do země oplývající mlékem a strdí, na místa Kananejského a Hetejského, a Amorejského a Ferezejského, a Hevejského a Jebuzejského.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 9, 'Nebo nyní, aj, křik synů Izraelských přišel ke mně; viděl jsem také i ssoužení, jímž je ssužují Egyptští.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 10, 'Protož, nyní poď a pošli tě k Faraonovi; a vyvedeš lid můj, syny Izraelské z Egypta.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 11, 'I řekl Mojžíš Bohu: Kdo jsem já, abych šel k Faraonovi, a abych vyvedl syny Izraelské z Egypta?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 12, 'I odpověděl: Však budu s tebou; a toto budeš míti znamení, že jsem já tě poslal: Když vyvedeš lid ten z Egypta, sloužiti budete Bohu na hoře této.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 13, 'I řekl Mojžíš Bohu: Aj, já půjdu k synům Izraelským a dím jim: Bůh otců vašich poslal mne k vám. Řeknou-li mi: Které jest jméno jeho? co jim odpovím?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 14, 'I řekl Bůh Mojžíšovi: JSEM, KTERÝŽ JSEM. Řekl dále: Takto díš synům Izraelským: JSEM poslal mne k vám.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 15, 'Řekl ještě Bůh Mojžíšovi: Takto díš synům Izraelským: Hospodin, Bůh otců vašich, Bůh Abrahamův, Bůh Izákův, a Bůh Jákobův poslal mne k vám; toť jest jméno mé na věčnost, a tať jest památka má po všecky věky.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 16, 'Jdi, a shromáždě starší Izraelské, mluv jim: Hospodin Bůh otců vašich ukázal mi se, Bůh Abrahamův, Bůh Izákův, a Bůh Jákobův, řka: Rozpomínaje, rozpomenul jsem se na vás, a na to, co se vám dálo v Egyptě.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 17, 'Protož jsem řekl: Vyvedu vás z trápení Egyptského do země Kananejského, a Hetejského, a Amorejského, a Ferezejského, a Hevejského, a Jebuzejského, do země oplývající mlékem a strdí.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 18, 'I poslechnou hlasu tvého. Půjdeš pak ty a starší Izraelští k králi Egyptskému, a díte jemu: Hospodin Bůh Hebrejský potkal se s námi; protož nyní, nechť medle jdeme cestou tří dnů na poušť, abychom obětovali Hospodinu Bohu našemu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 19, 'Ale já vím, žeť vám nedopustí král Egyptský jíti, leč v ruce silné.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 20, 'Protož vztáhnu ruku svou, a bíti budu Egypt divnými věcmi svými, kteréž činiti budu u prostřed něho; a potom propustí vás.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 21, 'A dám milost lidu tomuto před očima Egyptských. I stane se, že když půjdete, neodejdete prázdní.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 22, 'Ale vypůjčí žena od sousedy své, a od hospodyně domu svého klínotů stříbrných, a klínotů zlatých a roucha; i vložíte to na syny a na dcery své, a tak obloupíte Egypt.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 1, 'Odpověděl pak Mojžíš, a řekl: Aj, neuvěří mi, ani uposlechnou hlasu mého; nebo řeknou: Neukázalť se tobě Hospodin.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 2, 'Tedy řekl jemu Hospodin: Co jest to v ruce tvé? Odpověděl: Hůl.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 3, 'I řekl: Vrz ji na zem. I povrhl ji na zem, a obrácena jest v hada; a utíkal Mojžíš před ním.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 4, 'Tedy řekl Hospodin Mojžíšovi: Vztáhni ruku svou, a chyť ho za ocas. Kterýžto vztáh ruku svou, chytil jej, a obrácen jest v hůl v rukou jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 5, 'Aby věřili, že se ukázal tobě Hospodin, Bůh otců jejich, Bůh Abrahamův, Bůh Izákův a Bůh Jákobův.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 6, 'Potom zase řekl jemu Hospodin: Vlož nyní ruku svou za ňadra svá. I vložil ruku svou za ňadra svá; a vyňal ji, a aj, ruka jeho byla malomocná, bílá jako sníh.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 7, 'Řekl opět: Vlož ruku svou zase v ňadra svá. Kterýž vložil ruku svou zase v ňadra svá; a vyňal ji z ňader svých, a aj, učiněna jest zase jako jiné tělo jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 8, 'I budeť, jestliže neuvěří tobě, a neposlechnou hlasu a znamení prvního, uvěří hlasu a znamení druhému.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 9, 'A pakli neuvěří ani těm dvěma znamením, a neuposlechnou hlasu tvého, tedy nabereš vody z řeky, a vyliješ ji na zem; a promění se vody, kteréž vezmeš z řeky, a obrátí se v krev na zemi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 10, 'I řekl Mojžíš Hospodinu: Prosím, Pane, nejsem muž výmluvný, aniž prvé, ani jakž jsi mluvil s služebníkem svým; nebo zpozdilých úst a neohbitého jazyku jsem.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 11, 'Jemuž odpověděl Hospodin: Kdo dal ústa člověku? Aneb kdo může učiniti němého, neb hluchého, vidoucího, neb slepého? Zdali ne já Hospodin?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 12, 'Nyní tedy jdi, a já budu v ústech tvých, a naučím tě, co bys mluviti měl.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 13, 'I řekl: Slyš mne, Pane, pošli, prosím, toho, kteréhož poslati máš.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 14, 'A rozhněvav se velmi Hospodin na Mojžíše, řekl: Zdaliž nemáš Arona bratra svého z pokolení Léví? Vím, že on výmluvný jest; ano aj, sám vyjde v cestu tobě, a vida tebe, radovati se bude v srdci svém.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 15, 'Ty mluviti budeš k němu, a vložíš slova v ústa jeho; a já budu v ústech tvých a v ústech jeho, a naučím vás, co byste měli činiti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 16, 'A on mluviti bude za tebe k lidu; a bude tobě on za ústa, a ty budeš jemu za Boha.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 17, 'Hůl pak tuto vezmeš v ruku svou, kterouž činiti budeš ta znamení.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 18, 'Tedy odšed Mojžíš, navrátil se k Jetrovi tchánu svému, a řekl jemu: Nechť jdu nyní, a navrátím se k bratřím svým, kteříž jsou v Egyptě, a pohledím, jsou-li ještě živi. I řekl Jetro Mojžíšovi: Jdi v pokoji.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 19, 'Nebo řekl byl Hospodin Mojžíšovi v zemi Madianské: Jdi, navrať se do Egypta; nebo zemřeli jsou všickni muži, kteříž hledali bezživotí tvého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 20, 'A vzav Mojžíš ženu svou, a syny své, vsadil je na osla, aby se navrátil do země Egyptské; vzal také Mojžíš hůl Boží v ruku svou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 21, 'I řekl Hospodin Mojžíšovi: Když půjdeš a navrátíš se do Egypta, hleď, abys všecky zázraky, kteréž jsem složil v ruce tvé, činil před Faraonem. Jáť pak zatvrdím srdce jeho, aby nepropustil lidu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 22, 'Protož díš Faraonovi: Toto praví Hospodin: Syn můj, prvorozený můj jest Izrael.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 23, 'I řekl jsem tobě: Propusť syna mého, ať slouží mi; a nechtěl jsi ho propustiti. Aj, já zabiji syna tvého, prvorozeného tvého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 24, 'I stalo se, když byl Mojžíš na cestě v hospodě, že se obořil na něj Hospodin, a hledal ho usmrtiti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 25, 'Tedy vzala Zefora nůž ostrý, a obřezala neobřízku syna svého, kteroužto vrhla k nohám jeho, řkuci: Zajisté ženich krví jsi mi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 26, 'I nechal ho. Ona pak nazvala ho tehdáž ženichem krví pro obřezání.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 27, 'Řekl také Hospodin Aronovi: Jdi vstříc Mojžíšovi na poušť. I šel a potkal se s ním na hoře Boží, a políbil ho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 28, 'A vypravoval Mojžíš Aronovi všecka slova Hospodinova, kterýž ho poslal, i o všech znameních, kteráž přikázal jemu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 29, 'Tedy šel Mojžíš s Aronem, a shromáždili všecky starší synů Izraelských.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 30, 'I mluvil Aron všecka slova, kteráž byl mluvil Hospodin k Mojžíšovi, a činil znamení před očima lidu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 31, 'A uvěřil lid, když uslyšeli, že navštívil Hospodin syny Izraelské, a že viděl ssoužení jejich. A sklonivše se, poklonu učinili.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 1, 'Potom pak přišli Mojžíš s Aronem, a řekli Faraonovi: Takto praví Hospodin, Bůh Izraelský: Propusť lid můj, ať mi slaví svátky na poušti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 2, 'Odpověděl Farao: Kdo jest Hospodin, abych poslechl hlasu jeho a propustil Izraele? Hospodina neznám, Izraele také nepropustím.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 3, 'I řekli: Bůh Hebrejský potkal se s námi. Nechť medle jdeme cestou tří dní na poušť, a obětujeme Hospodinu Bohu našemu, aby nedopustil na nás moru neb meče.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 4, 'I řekl jim král Egyptský: Proč ty Mojžíši a Arone, odtrhujete lid od prací jejich? Jděte k robotám svým.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 5, 'Řekl také Farao: Hle, již nyní mnoho jest lidu toho v zemi, a vy odvozujete je od robot jejich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 6, 'I přikázal Farao v ten den úředníkům nad lidem a šafářům jeho, řka:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 7, 'Nedávejte již více slámy lidu k dělání cihel jako prvé; nechať jdou sami a sbírají sobě slámu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 8, 'Však touž summu cihel, kterouž udělávali prvé, uložte na ně, nic neujímejte z ní; neboť zahálejí, a protož volají, řkouce: Poďme, obětujme Bohu našemu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 9, 'Nechť se přitíží robot mužům těm; a nechť pracují v nich, aby se neohlédali na slova lživá.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 10, 'Vyšedše tedy úředníci nad lidem a šafáři jeho, mluvili k lidu, řkouce: Takto praví Farao: Já nebudu vám dávati slámy.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 11, 'Sami jděte, beřte sobě slámu, kdekoli naleznete; ale nic nebude ujato díla vašeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 12, 'I rozběhl se lid po vší zemi Egyptské, aby trhal strniště místo slámy.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 13, 'A úředníci nutili je, řkouce: Vyplňte díla svá, úkol denní v den jeho, jako když sláma byla.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 14, 'I biti jsou šafáři synů Izraelských, kteréž ustanovili nad nimi úředníci Faraonovi, a mluveno k nim: Proč jste nevyplnili úkolu svého v díle cihel, jako prvé, ani včera ani dnes?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 15, 'I přišli šafáři synů Izraelských, a volali k Faraonovi, řkouce: Proč tak děláš služebníkům svým?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 16, 'Slámy se nedává služebníkům tvým, a říkají nám: Dělejte cihly; a hle, služebníci tvoji biti bývají, a hřeší lid tvůj.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 17, 'I řekl: Zahálíte, zahálíte, a protož mluvíte: Poďme, obětujme Hospodinu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 18, 'Protož nyní jděte, dělejte; slámy se vám dávati nebude, ale vy summu cihel vyplňujte.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 19, 'Vidouce šafáři synů Izraelských, že zle s nimi, poněvadž řečeno: Neujmete počtu cihel vašich z úkolu denního v den jeho,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 20, 'Potkali se s Mojžíšem a Aronem, kteříž stáli, aby jim vstříc vyšli, když by se vraceli od Faraona.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 21, 'A mluvili jim: Pohlediž Hospodin na vás, a suď; nebo zošklivili jste nás před Faraonem a služebníky jeho, a dali jste meč v ruku jejich, aby nás zamordovali.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 22, 'I navrátil se Mojžíš k Hospodinu a řekl: Pane, proč jsi tyto zlé věci uvedl na lid tento? Proč jsi mne sem poslal?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 23, 'Nebo od té chvíle, jakž jsem všel k Faraonovi, abych mluvil jménem tvým, hůře nakládá s lidem tímto, a ty jsi vždy nevysvobodil lidu svého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 1, 'Odpověděl Hospodin Mojžíšovi: Nyní uzříš, co učiním Faraonovi; nebo v ruce silné propustí je, a v ruce mocné vyžene je z země své.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 2, 'Mluvil ještě Bůh k Mojžíšovi a řekl jemu: Já jsem Hospodin.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 3, 'Ukázalť jsem se zajisté Abrahamovi, Izákovi a Jákobovi v tom, že jsem Bůh silný všemohoucí; ale v jménu svém, Hospodin, nejsem poznán od nich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 4, 'K tomu utvrdil jsem smlouvu svou s nimi, že jim dám zemi Kananejskou, zemi putování jejich, v níž pohostinu byli.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 5, 'Nad to, já slyšel jsem křik synů Izraelských, kteréž Egyptští v službu podrobují, a rozpomenul jsem se na smlouvu svou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 6, 'Protož pověz synům Izraelským: Já jsem Hospodin, a vyvedu vás z robot Egyptských, a vytrhnu vás z služby jejich, a vysvobodím vás v ruce vztažené a skrze soudy veliké.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 7, 'A vezmu vás sobě za lid, a budu vám za Boha; a zvíte, že jsem Hospodin Bůh váš, vysvobozující vás z robot Egyptských.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 8, 'Uvedu vás také do země, o níž jsem, zdvihna ruku svou, přisáhl, že ji dám Abrahamovi, Izákovi a Jákobovi; a dám ji vám v dědictví; Já Hospodin.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 9, 'I mluvil tak Mojžíš synům Izraelským; ale neslyšeli Mojžíše pro úzkost ducha a službu přetěžkou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 10, 'Protož mluvil Hospodin Mojžíšovi, řka:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 11, 'Vejdi, mluv Faraonovi králi Egyptskému, ať propustí syny Izraelské z země své.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 12, 'I mluvil Mojžíš před Hospodinem, řka: Hle, synové Izraelští neposlechli mne, kterakž tedy poslechne mne Farao, a já jsem zpozdilý v řeči?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 13, 'I mluvil Hospodin Mojžíšovi a Aronovi, a přikázaní dal jim k synům Izraelským a k Faraonovi králi Egyptskému, aby vyvedli syny Izraelské z země Egyptské.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 14, 'Tito jsou přední v čeledech otců svých. Synové Rubenovi, prvorozeného Izraelova: Enoch, Fallu, Ezron a Charmi. Ty jsou čeledi Rubenovy.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 15, 'Synové pak Simeonovi: Jamuel, Jamin, Ahod, Jachin, Sohar a Saul, syn Kananejské. Ty jsou čeledi Simeonovy.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 16, 'A tato jsou jména synů Léví v rodech jejich: Gerson, Kahat a Merari. Let pak života Léví bylo sto třidceti a sedm let.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 17, 'Synové Gerson: Lebni a Semei po čeledech svých.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 18, 'A synové Kahat: Amram, Izar, Hebron a Uziel. Let pak života Kahat bylo sto třidceti a tři léta.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 19, 'A synové Merari: Moholi a Musi. Ty jsou čeledi Léví v rodech svých.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 20, 'Pojal pak Amram ženu Jochebed, tetu svou, sobě za manželku, kterážto porodila mu Arona a Mojžíše. A let života Amramova bylo sto třidceti a sedm let.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 21, 'Synové také Izarovi: Chore, Nefeg a Zechri.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 22, 'A synové Uzielovi: Mizael, Elzafan a Sethri.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 23, 'Pojal pak Aron Alžbětu, dceru Aminadabovu, sestru Názonovu, sobě za manželku; kterážto porodila jemu Nádaba, Abiu, Eleazara a Itamara.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 24, 'Synové pak Chore: Asser, Elkana a Abiazaf. Ty jsou čeledi Choritských.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 25, 'Eleazar pak syn Aronův vzal jednu ze dcer Putielových sobě za manželku; kteráž mu porodila Fínesa. Ti jsou přední z otců Levítských po čeledech svých.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 26, 'To jest ten Aron a Mojžíš, jimž řekl Hospodin: Vyveďte syny Izraelské z země Egyptské po houfích jejich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 27, 'Tito jsou, kteříž mluvili Faraonovi, králi Egyptskému, aby vyvedli syny Izraelské z Egypta; toť jest ten Mojžíš a Aron.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 28, 'Stalo se pak, když mluvil Hospodin k Mojžíšovi v zemi Egyptské,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 29, 'Že mu řekl takto: Já Hospodin; mluv k Faraonovi, králi Egyptskému, všecko, což já mluvím tobě.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 30, 'A řekl Mojžíš před Hospodinem: Aj, já jsem zpozdilý v řeči, kterakž tedy poslouchati mne bude Farao?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 1, 'I řekl Hospodin Mojžíšovi: Aj, ustanovil jsem tě za Boha Faraonovi; Aron pak bratr tvůj bude prorokem tvým.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 2, 'Ty mluviti budeš všecko, což tobě přikáži; Aron pak bratr tvůj mluviti bude k Faraonovi, aby propustil syny Izraelské z země své.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 3, 'Ale jáť zatvrdím srdce Faraonovo, a množiti budu znamení svá a zázraky své v zemi Egyptské.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 4, 'Aniž poslechne vás Farao. I vzložím ruku svou na Egypt, a vyvedu vojska svá, lid svůj, syny Izraelské, z země Egyptské skrze soudy veliké.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 5, 'I zvědíť Egyptští, že já jsem Hospodin, když vztáhnu ruku svou na Egypt; a vyvedu syny Izraelské z prostředku jich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 6, 'Tedy učinil Mojžíš a Aron tak; jakž přikázal jim Hospodin, tak učinili.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 7, 'A byl Mojžíš v osmdesáti, Aron pak v osmdesáti a třech letech, když mluvili s Faraonem.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 8, 'I řekl Hospodin Mojžíšovi a Aronovi takto:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 9, 'Když mluviti k vám bude Farao, řka: Ukažte od sebe zázrak, tedy díš Aronovi: Vezmi hůl svou, a povrz před Faraonem, i obrátí se v hada.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 10, 'Tedy všel Mojžíš s Aronem k Faraonovi, a učinili tak, jakž přikázal Hospodin; a povrhl Aron hůl svou před Faraonem i před služebníky jeho, a obrácena jest v hada.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 11, 'Povolal pak také Farao mudrců a čarodějníků; a učinili i ti čarodějníci Egyptští skrze čáry své tolikéž.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 12, 'Nebo povrhl každý z nich hůl svou, a obráceny jsou v hady; ale požřela hůl Aronova hole jejich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 13, 'I posililo se srdce Faraonovo, a neuposlechl jich, tak jakž byl mluvil Hospodin.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 14, 'Protož řekl Hospodin Mojžíšovi: Obtížilo se srdce Faraonovo; nechce propustiti lidu toho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 15, 'Jdi k Faraonovi ráno, aj, půjde ven k vodě, a stůj naproti němu při břehu řeky; a hůl, kteráž obrácena byla v hada, vezmeš do ruky své.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 16, 'A díš mu: Hospodin Bůh Hebrejský poslal mne k tobě, aťbych řekl: Propusť lid můj, aby sloužili mi na poušti; a aj, neuposlechls až dosavad.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 17, 'Protož takto praví Hospodin: Po tomto poznáš, že já jsem Hospodin: Aj, já udeřím holí, kteráž jest v ruce mé, na vody, kteréž jsou v řece, a obráceny budou v krev.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 18, 'A ryby, kteréž jsou v řece, pomrou; i nasmradí se řeka, a ustávati budou Egyptští, hledajíce vody, kterouž by pili z řeky.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 19, 'Protož řekl Hospodin Mojžíšovi: Rci Aronovi: Vezmi hůl svou, a vztáhni ruku svou na vody Egyptské, na řeky jejich, na potoky jejich, i na jezera jejich, a na všecka shromáždění vod jejich, aby se obrátily v krev; i bude krev po vší zemi Egyptské, tak v nádobách dřevěných, jako kamenných.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 20, 'Tedy učinili tak Mojžíš a Aron, jakž byl přikázal Hospodin; a zdvihna hůl, udeřil v vodu, kteráž byla v řece, před očima Faraonovýma a před očima služebníků jeho; i obráceny jsou všecky vody, kteréž byly v řece, v krev.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 21, 'Ryby pak, kteréž byly v řece, pomřely, a nasmradila se řeka, tak že nemohli Egyptští píti vody z řeky; a byla krev po vší zemi Egyptské.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 22, 'To též učinili i čarodějníci Egyptští skrze čáry své. I zsililo se srdce Faraonovo, aby neuposlechl jich, tak jakž byl mluvil Hospodin.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 23, 'A odvrátiv se Farao, přišel do domu svého; a ani k tomu nepřiložil srdce svého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 24, 'Kopali pak všickni Egyptští vůkol řeky, hledajíce vody ku pití; nebo nemohli píti vody z řeky.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 25, 'A vyplnilo se dní sedm, jakž ranil Hospodin řeku.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 1, 'I mluvil Hospodin k Mojžíšovi: Vejdi k Faraonovi a rci jemu: Takto praví Hospodin: Propusť lid můj, ať mi slouží.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 2, 'Pakli nebudeš chtíti propustiti, aj, já raním všecky krajiny tvé žabami.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 3, 'A vydá řeka množství žab, kteréž vystoupí a polezou do domu tvého a do pokoje, v němž líháš, a na ložce tvé, a do domů služebníků tvých i lidu tvého, a do pecí tvých a do těsta tvého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 4, 'I na tebe a na lid tvůj, i na všecky služebníky tvé polezou žáby.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 5, 'I řekl Hospodin Mojžíšovi: Rci Aronovi: Vztáhni ruku svou s holí svou na řeky, na potoky a na jezera, a vyveď žáby na zemi Egyptskou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 6, 'I vztáhl Aron ruku svou na vody Egyptské; a vystoupily žáby a přikryly zemi Egyptskou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 7, 'A učinili tolikéž čarodějníci skrze své čáry; a udělali, že vyšly žáby na zemi Egyptskou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 8, 'Tedy Farao povolav Mojžíše a Arona, řekl: Modlte se Hospodinu, ať odejme žáby ode mne a od lidu mého; a propustím ten lid, aby obětovali Hospodinu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 9, 'I řekl Mojžíš Faraonovi: Poctím tě tím, a pověz, kdy bych se měl modliti za tě a za služebníky tvé, a za lid tvůj, aby vypléněny byly žáby od tebe, i z domů tvých; toliko v řece zůstanou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 10, 'Kterýžto odpověděl: Zítra. A Mojžíš řekl: Podlé slova tvého nechť jest, abys věděl, že žádného takového není, jako Hospodin Bůh náš.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 11, 'I odejdou žáby od tebe a od domů tvých, i od služebníků tvých a od lidu tvého; toliko v řece zůstanou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 12, 'Tedy vyšel Mojžíš s Aronem od Faraona. I volal Mojžíš k Hospodinu, aby odjaty byly žáby, kteréž byl dopustil na Faraona.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 13, 'I učinil Hospodin podlé slova Mojžíšova; a vymřely žáby z domů, ze vsí i z polí.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 14, 'I shrnuli je na hromady; a nasmradila se země.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 15, 'Vida pak Farao, že by dáno bylo oddechnutí, více zatvrdil se v srdci svém, a neuposlechl jich, jakož byl mluvil Hospodin.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 16, 'I řekl Hospodin Mojžíšovi: Rci k Aronovi: Vztáhni hůl svou, a udeř v prach země, aby obrátil se v stěnice na vší zemi Egyptské.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 17, 'Kteříž učinili tak. Nebo vztáhl Aron ruku svou s holí svou, a udeřil prach země. I byly stěnice na lidech i hovadech; všecken prach země obrátil se v stěnice ve vší zemi Egyptské.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 18, 'Dělali také tak čarodějníci skrze čáry své, aby vyvedli stěnice, ale nemohli. A byly stěnice na lidech i hovadech.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 19, 'Tedy řekli čarodějníci Faraonovi: Prst Boží toto jest. A posililo se srdce Faraonovo, aniž poslechl jich, jakož mluvil Hospodin.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 20, 'Řekl pak Hospodin Mojžíšovi: Vstaň ráno a stůj před Faraonem. Hle vyjde k vodě, a díš k němu: Takto praví Hospodin: Propusť lid můj, ať mi slouží.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 21, 'Pakli nepropustíš lidu mého, hle, já pošli na tě a na služebníky tvé, a na lid tvůj, a na domy tvé směsici všelikých škodlivých žížal; a naplněni budou domové Egyptští těmi žížalami, nad to i země ta, na níž oni jsou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 22, 'A oddělím v ten den zemi Gesen, v níž lid můj zůstává, aby tam nebylo směsice té; abys věděl, že jsem já Hospodin u prostřed země.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 23, 'A vysvobozením rozdíl učiním mezi lidem svým a lidem tvým. Zítra bude znamení toto.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 24, 'I učinil Hospodin tak. Nebo přišla těžká směsice škodlivých žížal na dům Faraonův, a do domů služebníků jeho i na všecku zemi Egyptskou; a nakazila se země od té směsice.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 25, 'Povolal pak Farao Mojžíše a Arona, a řekl: Jděte, obětujte Bohu svému tu v zemi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 26, 'I řekl Mojžíš: Nenáleží nám tak činiti; nebo ohavnost Egyptských obětovali bychom Hospodinu Bohu našemu. A jestliže bychom obětovali to, což jest ohavnost před očima Egyptských, zdaž by nás neukamenovali?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 27, 'Cestou tří dnů půjdeme na poušť, a obětovati budeme Hospodinu Bohu našemu, jakž nám rozkázal.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 28, 'I řekl Farao: Já propustím vás, abyste obětovali Hospodinu Bohu svému na poušti, však dále abyste nikoli neodcházeli. Modltež se za mne.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 29, 'Odpověděl Mojžíš: Aj, já vycházím od tebe, a modliti se budu Hospodinu, aby odešla ta směsice od tebe, od služebníků tvých i od lidu tvého zítra; avšak ať Farao více nezklamává, nepropouštěje lidu, aby obětovali Hospodinu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 30, 'A vyšed Mojžíš od Faraona, modlil se Hospodinu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 31, 'I učinil Hospodin podlé slova Mojžíšova, a odjal tu směsici od Faraona, od služebníků jeho i od lidu jeho, tak že ani jedné žížaly nezůstalo.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 32, 'Ale Farao ztížil srdce své také i tehdáž, a nepropustil lidu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 1, 'Tedy řekl Hospodin Mojžíšovi: Vejdi k Faraonovi, a mluv k němu: Takto praví Hospodin, Bůh Hebrejský: Propusť lid můj, ať mi slouží.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 2, 'Pakli nebudeš chtíti propustiti, než předce držeti je budeš:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 3, 'Aj, ruka Hospodinova bude na dobytku tvém, kterýž jest na poli, na koních, na oslích, na velbloudích, na volích a na ovcech, mor těžký velmi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 4, 'A učiní Hospodin rozdíl mezi dobytky Izraelských a mezi dobytky Egyptských, aby nic neumřelo ze všeho, což jest synů Izraelských.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 5, 'A uložil Hospodin čas jistý, řka: Zítra učiní Hospodin věc takovou na zemi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 6, 'I učinil Hospodin tu věc na zejtří, a pomřel všecken dobytek Egyptským; z dobytku pak synů Izraelských ani jedno neumřelo.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 7, 'I poslal Farao, a aj, neumřelo z dobytků Izraelských ani jedno. Ale obtíženo jest srdce Faraonovo, a nepropustil lidu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 8, 'I řekl Hospodin Mojžíšovi a Aronovi: Vezměte sobě plné hrsti své popela z peci, a ať jej sype Mojžíš k nebi před očima Faraonovýma.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 9, 'I obrátí se v prach po vší zemi Egyptské, a budou z něho na lidech i na hovadech vředové prýštící se neštovicemi po vší zemi Egyptské.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 10, 'Nabravše tedy popela z peci, stáli před Faraonem, a sypal jej Mojžíš k nebi. I byli vředové plní neštovic, prýštící se na lidech i na hovadech.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 11, 'Aniž mohli čarodějníci státi před Mojžíšem pro vředy; nebo byli vředové na čarodějnících i na všech Egyptských.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 12, 'I zsilil Hospodin srdce Faraonovo, a neposlechl jich, tak jakž byl mluvil Hospodin k Mojžíšovi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 13, 'Tedy řekl Hospodin Mojžíšovi: Vstana ráno, postav se před Faraonem, a rci k němu: Takto praví Hospodin, Bůh Hebrejský: Propusť lid můj, ať mi slouží.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 14, 'Nebo já teď již pošli všecky rány své na srdce tvé, i na služebníky tvé a na lid tvůj, abys věděl, žeť není podobného mně na vší zemi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 15, 'Nebo nyní, když jsem vztáhl ruku svou, byl bych tebe také ranil i lid tvůj morem tím; a tak bys byl vyhlazen z země.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 16, 'Ale však proto jsem tě zachoval, abych ukázal na tobě moc svou, a aby vypravovali jméno mé na vší zemi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 17, 'Ještě ty pozdvihuješ se proti lidu mému, nechtěje ho propustiti?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 18, 'Aj, já dštíti budu zítra v tentýž čas krupobitím těžkým náramně, jakéhož nebylo v Egyptě od toho dne, jakž založen jest, až do tohoto času.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 19, 'Protož nyní pošli, shromažď dobytek svůj a cokoli máš na poli. Na všecky lidi i hovada, kteráž by nalezena byla na poli, a nebyla by shromážděna do domu, spadne krupobití, a pomrou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 20, 'Kdo tedy z služebníků Faraonových ulekl se slova Hospodinova, svolal hbitě služebníky své i dobytek svůj do domu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 21, 'Ale kdož nepřiložil srdce svého k slovu Hospodinovu, nechal služebníků svých a dobytka svého na poli.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 22, 'I řekl Hospodin Mojžíšovi: Vztáhni ruku svou k nebi, ať jest krupobití po vší zemi Egyptské, na lidi i na hovada i na všelikou bylinu polní v zemi Egyptské.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 23, 'Tedy vztáhl Mojžíš hůl svou k nebi, a Hospodin vydal hřímání a krupobití. I sstoupil oheň na zem, a dštil Hospodin krupobitím na zemi Egyptskou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 24, 'I bylo krupobití a oheň smíšený s krupobitím těžký velmi, jakéhož nebylo nikdy ve vší zemi Egyptské, jakž v ní bydliti lidé začali.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 25, 'I ztloukly kroupy po vší zemi Egyptské, cožkoli bylo na poli od člověka až do hovada; všecku také bylinu polní potloukly kroupy, i všecko stromoví na poli zpřerážely.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 26, 'Toliko v zemi Gesen, v níž byli synové Izraelští, nebylo krupobití.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 27, 'Poslav tedy Farao, povolal Mojžíše a Arona a řekl jim: Zhřešil jsem i nyní. Hospodinť jest spravedlivý, ale já a lid můj bezbožní jsme.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 28, 'Modlte se Hospodinu, (nebo dosti jest), ať není hřímání Božího a krupobití. Tedy propustím vás, aniž déle zůstávati budete.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 29, 'I řekl jemu Mojžíš: Když vyjdu ven z města, rozprostru ruce své k Hospodinu, a hřímání přestane, i krupobití více nebude, abys poznal, že Hospodinova jest země.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 30, 'Ale vím, že ani ty, ani služebníci tvoji ještě se nebudete báti tváři Hospodina Boha.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 31, 'I potlučen jest len a ječmen; nebo ječmen se byl vymetal, len také byl v hlávkách.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 32, 'Ale pšenice a špalda nebyla ztlučena, nebo pozdní byla.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 33, 'Tedy Mojžíš vyšed od Faraona z města, rozprostřel ruce své k Hospodinu. I přestalo hřímání a krupobití, a ani déšť nelil se na zemi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 34, 'Uzřev pak Farao, že přestal déšť a krupobití a hřímání, opět hřešil; a více obtížil srdce své, on i služebníci jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 35, 'I zsililo se srdce Faraonovo, a nepropustil synů Izraelských, tak jakž byl mluvil Hospodin skrze Mojžíše.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 1, 'I řekl Hospodin Mojžíšovi: Vejdi k Faraonovi, ačkoli jsem já obtížil srdce jeho, a srdce služebníků jeho, abych učinil divy tyto své u prostřed nich;');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 2, 'A abys ty vypravoval v uši synů svých i vnuků svých, co jsem učinil v Egyptě, a znamení má, kteráž jsem prokázal na nich; abyste věděli, že já jsem Hospodin.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 3, 'I všel Mojžíš s Aronem k Faraonovi, a řekli jemu: Takto praví Hospodin Bůh Hebrejský: Dokavadž nechceš se ponížiti přede mnou? Propusť lid můj, ať mi slouží.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 4, 'Pakli nechceš propustiti lidu mého, aj, já uvedu zítra kobylky na krajinu tvou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 5, 'A přikryjí svrchek země, aby jí nebylo viděti, a snědí ostatky pozůstalé, kteříž vám zanecháni jsou po krupobití; zhryzou vám také každý strom pučící se na poli.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 6, 'A naplní domy tvé, i domy všech služebníků tvých, a domy všech Egyptských; čehož neviděli otcové tvoji a otcové otců tvých, od počátku bytu svého na zemi až do dne tohoto. A odvrátiv se, vyšel od Faraona.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 7, 'Řekli pak služebníci Faraonovi k němu: Dokavadž tento bude nám osídlem? Propusť ty muže, ať slouží Hospodinu Bohu svému. Zdaž ještě nevíš, že zkažen jest Egypt?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 8, 'I zavolán jest Mojžíš s Aronem před Faraona. Jimž řekl: Jděte, služte Hospodinu Bohu svému. Kdo jsou ti, kteříž jíti mají?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 9, 'A odpověděl Mojžíš: S dítkami i s starými našimi půjdeme, s syny i s dcerami našimi, s ovcemi a s větším dobytkem naším odejdeme; nebo slavnost Hospodinovu držeti máme.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 10, 'Tedy řekl jim: Nechať jest tak Hospodin s vámi, jako já propustím vás i dítky vaše. Hleďte, nebo zlé jest před tváři vaší.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 11, 'Ne budeť tak. Jděte vy sami muži, a služte Hospodinu, nebo toho vy toliko žádáte. I vyhnáni jsou od tváři Faraonovy.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 12, 'Tedy řekl Hospodin Mojžíšovi: Vztáhni ruku svou na zemi Egyptskou pro kobylky, ať vystoupí na zemi Egyptskou, a sežerou všelikou bylinu země té, cožkoli zůstalo po krupobití.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 13, 'I vztáhl Mojžíš hůl svou na zemi Egyptskou; a Hospodin uvedl vítr východní na zemi, aby vál celého toho dne a celou noc. A když bylo ráno, vítr východní přinesl kobylky.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 14, 'A vystoupily kobylky na všecku zemi Egyptskou, a připadly na všecky končiny Egyptské nesčíslně. Před těmi nebylo takových kobylek, aniž po těch takové budou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 15, 'I přikryly veškeren svrchek země, tak že pro ně nebylo lze znáti země; a sežraly všelikou bylinu země, a všeliké ovoce na stromích, kteréž zůstalo po krupobití; a nepozůstalo nic zeleného na stromích a bylinách polních ve vší zemi Egyptské.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 16, 'Tedy Farao spěšně povolav Mojžíše s Aronem, řekl: Zhřešil jsem proti Hospodinu Bohu vašemu, i proti vám.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 17, 'Ale nyní, odpusť, prosím, hřích můj aspoň tento, a modlte se Hospodinu Bohu vašemu, ať jen tuto smrt odejme ode mne.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 18, 'Protož vyšed Mojžíš od Faraona, modlil se Hospodinu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 19, 'I obrátil Hospodin vítr západní tuhý velmi, kterýžto zachvátiv kobylky, uvrhl je do moře Rudého, tak že nezůstalo žádné kobylky ve vší krajině Egyptské.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 20, 'Ale obtížil Hospodin srdce Faraonovo, a nepropustil synů Izraelských.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 21, 'I řekl Hospodin Mojžíšovi: Vztáhni ruku svou k nebi, a bude tma na zemi Egyptské, a makati ji budou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 22, 'I vztáhl Mojžíš ruku svou k nebi, a byla tma přehustá po vší zemi Egyptské za tři dni.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 23, 'Aniž viděl jeden druhého, a aniž kdo vstal z místa svého za tři dni; ale synové Izraelští všickni měli světlo v příbytcích svých.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 24, 'Potom povolav Farao Mojžíše, řekl: Jděte, služte Hospodinu. Toliko ovce vaše a větší dobytek váš nechať zůstane, také dítky vaše půjdou s vámi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 25, 'Odpověděl Mojžíš: Dáš také v ruce naše oběti a zápaly, kteréž bychom obětovali Hospodinu Bohu našemu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 26, 'A protož také dobytek náš půjde s námi, a nezůstane ani kopyta; nebo z nich vezmeme ku poctě Hospodinu Bohu našemu. My pak nevíme, čím sloužiti máme Hospodinu, dokudž nepřijdeme tam.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 27, 'Zatvrdil pak Hospodin srdce Faraonovo, tak že nechtěl propustiti jich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 28, 'I řekl mu Farao: Odejdi ode mne, a varuj se, abys více neviděl tváři mé; nebo v který den uzříš tvář mou, umřeš.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 29, 'Odpověděl Mojžíš: Dobře jsi řekl; neuzřímť více tváři tvé.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 11, 1, 'Řekl pak byl Hospodin Mojžíšovi: Ještě ránu jednu uvedu na Faraona a na Egypt, potom propustí vás odsud; propustí docela, anobrž vypudí vás odsud.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 11, 2, 'Mluv nyní v uši lidu, ať vypůjčí jeden každý od bližního svého, a každá od bližní své klínotů stříbrných a klínotů zlatých.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 11, 3, 'A dal Hospodin milost lidu před očima Egyptských. (Sám také Mojžíš veliký byl velmi v zemi Egyptské, před očima služebníků Faraonových i před očima lidu.)');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 11, 4, 'I řekl Mojžíš: Takto praví Hospodin: O půlnoci já půjdu prostředkem Egypta.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 11, 5, 'A pomře všecko prvorozené v zemi Egyptské, od prvorozeného Faraonova, jenž seděti měl na stolici jeho, až do prvorozeného děvky, kteráž jest při žernovu, i všecko prvorozené hovad.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 11, 6, 'I bude křik veliký po vší zemi Egyptské, jakéhož nebylo prvé, a jakéhož nikdy nebude více.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 11, 7, 'U synů pak Izraelských nikdež nehne pes jazykem svým, ovšem pak ani člověk ani hovado, abyste věděli, že rozdíl učinil Hospodin mezi Egyptskými a Izraelskými.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 11, 8, 'I sstoupí všickni tito služebníci tvoji ke mně, a skláněti mi se budou, řkouce: Vyjdi, ty i všecken lid, kterýž jest pod správou tvou; a potom vyjdu. A vyšel od Faraona s velikým hněvem.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 11, 9, 'I řekl Hospodin Mojžíšovi: Neposlechneť vás Farao, abych rozmnožil zázraky své v zemi Egyptské.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 11, 10, 'Ale Mojžíš a Aron činili všecky ty zázraky před Faraonem; Hospodin pak zatvrdil srdce Faraonovo, tak že nepropustil synů Izraelských z země své.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 1, 'Mluvil pak Hospodin k Mojžíšovi a k Aronovi v zemi Egyptské, řka:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 2, 'Tento měsíc počátek měsíců vám bude; první vám bude mezi měsíci ročními.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 3, 'Mluvte ke všemu shromáždění Izraelskému, řkouce: Desátého dne měsíce tohoto vezmete sobě jeden každý beránka po čeledech, beránka na každý dům.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 4, 'Byl-li by pak dům tak malý, že by s beránka býti nemohl, přivezme souseda svého, kterýž jest blízký domu jeho, podlé počtu duší; jeden každý počte tolik osob, kolikž by jich snísti mohlo beránka.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 5, 'Beránka bez vady, samce ročního míti budete, kteréhož z ovcí aneb z koz vezmete.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 6, 'A chovati ho budete až do čtrnáctého dne měsíce tohoto; a zabije ho všecko množství shromáždění Izraelského k večerou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 7, 'A vezmouce krve, pomaží obou veřejí a nade dveřmi u domů, v nichž jej jísti budou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 8, 'I budou jísti noci té maso pečené ohněm, s chleby přesnými; s bylinami hořkými jísti jej budou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 9, 'Nebudete jísti z něho nic surového ani v vodě vařeného, ale pečené ohněm, s hlavou jeho i s nohami a droby.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 10, 'Nezanecháte z něho ničehož do jitra; pakli by co pozůstalo z něho až do jitra, ohněm spálíte.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 11, 'Takto jej pak jísti budete: Bedra svá přepásaná míti budete, obuv svou na nohách svých a hůl svou v ruce své, a jísti budete s chvátáním; nebo Jití jest Hospodinovo.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 12, 'V tu noc zajisté půjdu po zemi Egyptské, a budu bíti všecko prvorozené v zemi Egyptské, od člověka až do hovada, a nade všemi bohy Egyptskými učiním soud: Já Hospodin.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 13, 'Krev pak ta na domích, v nichž budete, budeť vám na znamení; a když uzřím krev, pominu vás, a nebude mezi vámi rána zahubující, když bíti budu prvorozené v zemi Egyptské.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 14, 'A budeť vám den ten na památku, a slaviti jej budete slavný Hospodinu po rodech svých; právem věčným slaviti jej budete.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 15, 'Za sedm dní přesné chleby jísti budete, a hned prvního dne vyprázdníte kvas z domů vašich; nebo kdožkoli jedl by co kvašeného od prvního až do sedmého dne, vyhlazena bude duše ta z Izraele.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 16, 'A v den první budeť shromáždění svaté; dne také sedmého shromáždění svaté míti budete. Žádného díla nebude děláno v nich; toliko čehož se užívá k jídlu od každého, to samo připraveno bude od vás.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 17, 'A ostříhati budete přesnic, nebo v ten den vyvedl jsem vojska vaše z země Egyptské; protož zachovávati budete den ten po rodech svých právem věčným.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 18, 'Prvního měsíce, čtrnáctého dne téhož měsíce, u večer jísti budete chleby přesné, až do dne jedenmecítmého téhož měsíce k večerou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 19, 'Za sedm dní nebude nalezeno kvasu v domích vašich; nebo kdo by koli jedl něco kvašeného, vyhlazena bude duše ta z shromáždění Izraelského, tak příchozí jako zrozený v zemi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 20, 'Nic kvašeného jísti nebudete, ale ve všech příbytcích vašich jísti budete chleby přesné.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 21, 'Tedy svolal Mojžíš všecky starší Izraelské, a řekl jim: Vybeřte a vezměte sobě beránka po čeledech svých, a zabíte Fáze.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 22, 'Vezmete také svazček yzopu, a omočíte v krvi, kteráž bude v medenici, a pomažete nade dveřmi a na obou veřejích tou krví, kteráž bude v nádobě; z vás pak žádný nevycházej ze dveří domu svého až do jitra.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 23, 'Neboť půjde Hospodin, aby bil Egypt, a kde uzří krev nade dveřmi a na obou veřejích, přeskočí Hospodin ty dvéře, aniž dopustí zhoubci vjíti do domů vašich k hubení.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 24, 'Protož ostříhati budete věci této za ustanovení tobě i synům tvým až na věky.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 25, 'A když vejdete do země, kterouž dá Hospodin vám, jakž zaslíbil, zachovávati budete službu tuto.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 26, 'Když by pak řekli vám synové vaši: Jaká jest to služba vaše?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 27, 'Tedy díte: Obět Fáze toto jest Hospodinu, kterýž pominul domů synů Izraelských v Egyptě, když bil Egypt, domy pak naše vysvobodil. A lid sklonivše hlavy, poklonu učinili.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 28, 'A rozšedše se synové Izraelští, učinili, jakž byl Hospodin přikázal Mojžíšovi a Aronovi; tak a nejinak učinili.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 29, 'Stalo se pak o půlnoci, pobil Hospodin všecko prvorozené v zemi Egyptské, od prvorozeného Faraonova, kterýž seděti měl na stolici jeho, až do prvorozeného vězně, kterýž byl v žaláři, i všecko prvorozené hovad.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 30, 'Tedy vstal Farao noci té, a všickni služebníci jeho i všickni Egyptští, a vzešel křik veliký v Egyptě; nebo žádného nebylo domu, v němž by nebylo něčeho mrtvého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 31, 'A povolav Mojžíše a Arona v noci, řekl: Vstaňte, vyjděte z prostředku lidu mého, i vy i synové Izraelští, a odejdouce, služte Hospodinu, jakž jste mluvili.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 32, 'Ovce také vaše i voly vaše vezměte, jakž jste žádali, a jděte; a dejte mi také požehnání.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 33, 'I nutkali Egyptští lid, aby co nejrychleji vyšli z země; nebo pravili: Všickni již teď zemřeme.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 34, 'Protož vzal lid těsto své, prvé než zkysalo, obaliv je v šaty své, na ramena svá.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 35, 'Učinili pak synové Izraelští podlé rozkazu Mojžíšova; nebo vyžádali byli od Egyptských klínotů stříbrných a zlatých, i šatů.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 36, 'A Hospodin dal milost lidu před očima Egyptských, tak že půjčovali jim. I obloupili Egyptské.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 37, 'Tedy táhli synové Izraelští z Ramesses k Sochot, okolo šestkrát sto tisíc pěších, mužů toliko kromě dětí.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 38, 'Ano také jiného lidu mnoho vyšlo s nimi, ovec také a volů, dobytka velmi mnoho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 39, 'I napekli z těsta, kteréž vynesli z Egypta, koláčů nekvašených; nebo ještě bylo nezkynulo, proto že vypuzeni byli z Egypta, a nemohli prodlévati, a ani pokrmů na cestu nepřipravili sobě.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 40, 'Čas pak bydlení synů Izraelských, kteříž byli v Egyptě, byl čtyři sta a třidceti let.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 41, 'A když se vyplnilo čtyři sta a třidceti let, právě toho dne vyšla všecka vojska Hospodinova z země Egyptské.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 42, 'Noc tato pilně ostříhána býti má Hospodinu, v níž vyvedl je z země Egyptské; tať tedy noc Hospodinova ostříhána bude ode všech synů Izraelských po národech jejich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 43, 'I řekl Hospodin Mojžíšovi a Aronovi: Tentoť bude řád při slavnosti Fáze: Žádný cizozemec nebude jísti z něho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 44, 'Každý pak služebník váš za stříbro koupený, když by obřezán byl, teprv jísti bude z něho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 45, 'Příchozí a nájemník nebude jísti z něho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 46, 'V témž domě jísti jej budeš, nevyneseš z domu ven masa jeho; a kostí v něm nezlámete.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 47, 'Všecko shromáždění Izraelské tak s ním učiní.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 48, 'Jestliže by pak cizozemec bydlil s tebou pohostinu, a slaviti by chtěl Fáze Hospodinu, prvé obřezán bude každý pohlaví mužského; a tehdy přistoupí k slavení jeho, a bude jako tu v zemi zrozený; žádný pak neobřezaný nebude jísti z něho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 49, 'Jednostejné právo bude tu zrodilému a příchozímu, kterýž jest pohostinu u prostřed vás.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 50, 'Tedy učinili všickni synové Izraelští, jakž přikázal Hospodin Mojžíšovi a Aronovi; tak učinili.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 51, 'A tak stalo se právě toho dne, že vyvedl Hospodin syny Izraelské z země Egyptské s vojsky jejich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 1, 'I mluvil Hospodin k Mojžíšovi, řka:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 2, 'Posvěť mi všeho prvorozeného, cožkoli otvírá každý život mezi syny Izraelskými, tak z lidí jako z hovad, nebo mé jest.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 3, 'Protož řekl Mojžíš lidu: Pamatujte na den tento, v kterémž jste vyšli z Egypta, z domu služby; nebo v silné ruce vyvedl vás odsud Hospodin, aniž kdo jez co kvašeného.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 4, 'Dnes vycházíte vy, měsíce Abib.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 5, 'Když tedy uvede tě Hospodin do země Kananejských, Hetejských, Amorejských, Hevejských a Jebuzejských, tak jakž přisáhl otcům tvým, a dá tobě zemi oplývající mlékem a strdí: tedy vykonávati budeš službu tuto v tento měsíc.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 6, 'Za sedm dní jísti budeš chleby přesné, dne pak sedmého slavnost bude Hospodinova.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 7, 'Přesní chlebové jedeni budou za dnů sedm, aniž spatříno bude u tebe co kvašeného, aniž se uhlédá u tebe kvas ve všech končinách tvých.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 8, 'A vypravovati budeš synu svému v ten den, řka: Proto, což mi učinil Hospodin, když jsem vycházel z Egypta.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 9, 'A budeť tobě to jako nějaké znamení na ruce tvé, a jako památka před očima tvýma, aby zákon Hospodinův byl v ústech tvých; nebo v ruce silné vyvedl tě Hospodin z Egypta.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 10, 'Protož zachovávati budeš ustanovení toto v čas jistý, rok po roce.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 11, 'A když by tě uvedl Hospodin do země Kananejských, tak jakž přisáhl tobě a otcům tvým, a dal by ji tobě:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 12, 'Tedy všecko, což otvírá život, oddělíš Hospodinu, i každý plod hovada tvého otvírající život, což by koli bylo samců, Hospodinovo jest.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 13, 'Každé pak prvorozené osle vyplatíš hovádkem; pakli bys nevyplatil, zlom jemu šíji; každého také prvorozeného člověka mezi syny svými vyplatíš.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 14, 'A když by se tebe vzeptal syn tvůj potom, a řekl: Co jest to? tedy povíš jemu: V ruce silné vyvedl nás Hospodin z Egypta, z domu služebnosti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 15, 'Nebo když se byl zatvrdil Farao, a nechtěl nás propustiti, pobil Hospodin všecko prvorozené v zemi Egyptské, od prvorozeného z lidí, až do prvorozeného z hovad; i tou příčinou já obětuji Hospodinu všecky samce otvírající život, ale všecko prvorozené z synů svých vyplacuji.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 16, 'Mějž to tedy jako znamení na ruce své, a jako náčelník mezi očima svýma, že v ruce silné vyvedl nás Hospodin z Egypta.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 17, 'Stalo se pak, když pustil Farao lid, že nevedl jich Bůh cestou země Filistinské, ačkoli bližší byla; nebo řekl Bůh: Aby nepykal lid, když by uzřel, an válka nastává, a nevrátili se do Egypta.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 18, 'Ale obvedl Bůh lid cestou přes poušť, kteráž jest při moři Rudém. A vojensky zpořádaní vyšli synové Izraelští z země Egyptské.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 19, 'Vzal také Mojžíš kosti Jozefovy s sebou; nebo byl přísahou zavázal syny Izraelské, řka: Jistotně navštíví vás Bůh, protož vyneste odsud kosti mé s sebou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 20, 'Vytáhše tedy z Sochot, položili se v Etam při kraji pouště.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 21, 'Hospodin pak předcházel je ve dne v sloupu oblakovém, aby je vedl cestou, v noci pak v sloupu ohnivém, aby svítil jim, aby ve dne i v noci jíti mohli.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 22, 'Neodjal sloupu oblakového ve dne, ani ohnivého sloupu v noci od tváři toho lidu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 1, 'Mluvil pak Hospodin k Mojžíšovi, řka:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 2, 'Mluv k synům Izraelským, ať navrátíce se, rozbijí stany před Fiarot, mezi Magdalem a mořem, proti Belsefon; naproti němu rozbijete stany při moři.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 3, 'A dí Farao o synech Izraelských: Ssouženi jsou na zemi, sevřela je poušť.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 4, 'I zatvrdím srdce Faraonovo, a honiti je bude, a oslaven budu v Faraonovi a ve všem vojsku jeho; a zvědí Egyptští, že já jsem Hospodin. I učinili tak.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 5, 'Povědíno pak bylo králi Egyptskému, že by lid utíkal. I obráceno jest srdce Faraonovo a služebníků jeho proti lidu, a řekli: Co jsme to učinili, že jsme propustili Izraele, aby nesloužil nám?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 6, 'Protož zapřáhl do svého vozu, a lid svůj vzal s sebou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 7, 'A vzal šest set vozů vybraných, i všecky vozy Egyptské, nad nimiž nade všemi byli hejtmané.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 8, 'I zatvrdil Hospodin srdce Faraona krále Egyptského, tak že honil syny Izraelské; synové pak Izraelští vyšli v ruce vyvýšené.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 9, 'I honili je Egyptští, a postihli je, když se položili při moři, všickni vozové Faraonovi, a jezdci jeho i vojsko jeho podlé Fiarot, před Belsefon.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 10, 'A když se přiblížil Farao, pozdvihli synové Izraelští očí svých, a aj, Egyptští táhnou za nimi. I báli se velmi, a volali synové Izraelští k Hospodinu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 11, 'A řekli Mojžíšovi: Zdali proto, že ne bylo hrobů v Egyptě, vyvedl jsi nás, abychom zemřeli na poušti? Co jsi nám to učinil, že jsi vyvedl nás z Egypta?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 12, 'Zdali jsme toho nemluvili tobě ještě v Egyptě, řkouce: Nech nás, ať sloužíme Egyptským? Nebo lépe bylo nám sloužiti Egyptským, než zemříti na poušti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 13, 'I řekl Mojžíš lidu: Nebojte se, stůjte a vizte spasení Hospodinovo, kteréž vám způsobí dnes; nebo Egyptských, kteréž jste viděli dnes, neuzříte nikdy více až na věky.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 14, 'Hospodin bojovati bude za vás, a vy mlčeti budete.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 15, 'I řekl Hospodin Mojžíšovi: Co voláš ke mně? Mluv synům Izraelským, ať jdou předce.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 16, 'Ty pak zdvihni hůl svou, a vztáhni ruku svou na moře, a rozděl je; a nechať jdou synové Izraelští prostředkem moře po suše.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 17, 'Jáť pak, aj, já zatvrdím srdce Egyptských, a vejdou za nimi; i budu oslaven v Faraonovi, a ve všem vojsku jeho, v vozích jeho i v jezdcích jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 18, 'A zvědí Egyptští, že já jsem Hospodin, když oslaven budu v Faraonovi, v vozích jeho a v jezdcích jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 19, 'I bral se anděl Boží, kterýž byl prvé předcházel vojsko Izraelské, a šel z zadu za nimi; nebo hnul se sloup oblakový, kterýž byl před nimi, a stál z zadu za nimi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 20, 'A přišed mezi vojska Egyptských a vojska Izraelská, byl Egyptským oblakem a tmou, Izraelským pak osvěcoval noc, tak aby nepřiblížili se jedni k druhým přes celou noc.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 21, 'I vztáhl Mojžíš ruku svou na moře, a Hospodin rozdělil moře větrem východním prudce vějícím přes celou noc; a učinil moře v suchost, když se rozstoupily vody.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 22, 'Tedy šli synové Izraelští prostředkem moře po suše, a vody jim byly jako zed po pravé i po levé straně.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 23, 'A honíce je Egyptští, vešli za nimi do prostřed moře, všecka jízda Faraonova, vozové i jízdní jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 24, 'Stalo se pak v bdění jitřním, že pohleděl Hospodin na vojska Egyptských z sloupu ohně a oblaku, a zmátl vojsko Egyptské.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 25, 'A odjal kola vozů jejich, aby je těžce táhli. I řekli Egyptští: Utecme před Izraelem, nebo Hospodin bojuje za ně proti Egyptským.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 26, 'Tedy řekl Hospodin Mojžíšovi: Vztáhni ruku svou na moře, ať se zase vrátí vody na Egyptské, na vozy jejich a na jezdce jejich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 27, 'I vztáhl Mojžíš ruku svou na moře, a navrátilo se moře ráno k moci své, a Egyptští utíkali proti němu; a vrazil Hospodin Egyptské do prostřed moře.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 28, 'A navrátivše se vody, zatopily vozy i jezdce se vším vojskem Faraonovým, což jich koli vešlo za nimi do moře, tak že nezůstal z nich ani jeden.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 29, 'Ale synové Izraelští šli po suchu prostředkem moře, a vody jim byly místo zdi po pravé i po levé straně.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 30, 'A tak vysvobodil Hospodin v ten den Izraele z ruky Egyptských; a viděl Izrael Egyptské mrtvé na břehu mořském.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 31, 'Viděl také Izrael moc velikou, kterouž prokázal Hospodin na Egyptských. I bál se lid Hospodina, a věřili Hospodinu i Mojžíšovi, služebníku jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 1, 'Tehdy zpíval Mojžíš a synové Izraelští píseň tuto Hospodinu, a řekli takto: Zpívati budu Hospodinu, neboť jest slavně zveleben; koně i s jezdcem uvrhl do moře.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 2, 'Síla má a píseň jest Hospodin, nebo vysvobodil mne. Onť jest Bůh můj silný, protož stánek vzdělám jemu; onť jest Bůh otce mého, protož vyvyšovati ho budu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 3, 'Hospodin jest udatný bojovník, Hospodin jméno jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 4, 'Vozy Faraonovy i vojsko jeho uvrhl do moře; a nejpřednější hejtmané jeho ztopeni jsou v moři Rudém.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 5, 'Propasti přikryly je; vpadli do hlubiny jako kámen.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 6, 'Pravice tvá, Hospodine, zvelebena jest v síle, pravice tvá, ó Hospodine, potřela nepřítele.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 7, 'A ve mnohé vyvýšenosti své podvrátil jsi povstávající proti tobě; pustils hněv svůj, kterýžto sežral je jako strniště.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 8, 'A duchem chřípí tvých shromážděny jsou vody, stály tekuté vody jako hromada, ssedly se propasti u prostřed moře.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 9, 'Řekl nepřítel: Honiti budu, dohoním se, budu děliti loupeže, nasytí se jimi duše má, vytrhnu meč svůj, zahladí je ruka má.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 10, 'Povanul jsi větrem svým, i přikrylo je moře; pohlceni jsou jako olovo v prudkých vodách.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 11, 'Kdo podobný tobě mezi silnými, ó Hospodine? Kdo jest tak, jako ty, velebný v svatosti, hrozný v chvalách, činící divy?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 12, 'Vztáhls pravici svou, i požřela je země.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 13, 'Zprovodíš v milosrdenství svém lid tento, kterýž jsi vykoupil; laskavě povedeš jej v síle své k příbytku svatosti své.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 14, 'Uslyší lidé, bouřiti se budou; bolest zachvátí obyvatele Filistinské.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 15, 'Tedy zkormoucena budou knížata Idumejská, silné Moábské podejme strach, rozplynou se všickni obyvatelé Kananejští.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 16, 'Připadne na ně strach a lekání, pro velikost ramene tvého; mlčeti budou jako kámen, dokudž nepřejde lid tvůj, ó Hospodine, dokudž nepřejde lid ten, kteréhožs sobě dobyl.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 17, 'Uvedeš je, a štípíš je na hoře dědictví svého, na místě, kteréž jsi k příbytku svému připravil, Hospodine, v svatyni, kterouž utvrdí ruce tvé, Pane.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 18, 'Hospodin kralovati bude na věky věků.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 19, 'Nebo vešli koni Faraonovi s vozy jeho i s jezdci jeho do moře, a obrátil na ně Hospodin vody mořské, synové pak Izraelští šli po suše u prostřed moře.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 20, 'I vzala Maria prorokyně, sestra Aronova, buben v ruku svou, a vyšly za ní všecky ženy s bubny a s píšťalami.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 21, 'I odpovídala jim Maria: Zpívejte Hospodinu, poněvadž slavně zveleben jest; koně i s jezdcem uvrhl do moře.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 22, 'Hnul pak Mojžíš lidem Izraelským od moře Rudého, a táhli na poušť Sur. I šli tři dni po poušti, a nenalezli vod.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 23, 'A přišedše do Marah, nemohli píti vod z Marah, nebo byly hořké; protož nazváno jest jméno jeho Marah.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 24, 'Z té příčiny reptal lid na Mojžíše, řka: Co budeme píti?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 25, 'I volal k Hospodinu, a ukázal mu Hospodin dřevo, kteréž jakž uvrhl do vod, učiněny jsou sladké vody. Tu vydal jemu práva a soudy, a tu ho zkusil.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 26, 'A řekl: Jestliže skutečně poslouchati budeš hlasu Hospodina Boha svého, a činiti budeš, což spravedlivého jest před očima jeho, a nakloníš uší k přikázaním jeho, a ostříhati budeš všech ustavení jeho: žádné nemoci, kterouž jsem dopustil na Egypt, nedopustím na tebe; nebo já jsem Hospodin, kterýž tě uzdravuji.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 27, 'I přišli do Elim, kdež bylo dvanácte studnic vod a sedmdesáte palm; i rozbili tu stany při vodách.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 1, 'Když se pak hnuli z Elim, přišlo všecko množství synů Izraelských na poušť Sin, kteráž jest mezi Elim a Sinai, v patnáctý den druhého měsíce po vyjití z země Egyptské.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 2, 'I reptalo všecko shromáždění synů Izraelských proti Mojžíšovi a proti Aronovi na poušti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 3, 'A mluvili jim synové Izraelští: Ó bychom byli zemřeli od ruky Hospodinovy v zemi Egyptské, když jsme sedávali nad hrnci masa, když jsme se najídali chleba do sytosti! A teď vyvedli jste nás na tuto poušť, abyste zmořili všecko shromáždění toto hladem.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 4, 'I řekl Hospodin Mojžíšovi: Aj, já dám vám chleba s nebe jako déšť, a vycházeti bude lid a sbírati, což by postačilo na každý den, abych ho zkusil, bude-li choditi v zákoně mém, či nebude.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 5, 'V den pak šestý přistrojí sobě to, co přinesou; a bude toho dvakrát více, než toho, což sbírati mají na každý den.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 6, 'Tedy mluvil Mojžíš a Aron všechněm synům Izraelským: U večer poznáte, že Hospodin vyvedl vás z země Egyptské.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 7, 'A ráno uzříte slávu Hospodinovu; neboť jest slyšel reptání vaše proti Hospodinu. My zajisté co jsme, že repcete proti nám?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 8, 'Mluvil dále Mojžíš: Z toho, pravím, poznáte, když vám dá Hospodin u večer masa, abyste se najedli, a chleba ráno do sytosti, poněvadž slyšel Hospodin reptání vaše, jimiž jste na něj reptali. Nebo my co jsme? Ne proti námť jsou reptání vaše, ale proti Hospodinu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 9, 'I řekl Mojžíš Aronovi: Mluv ke všemu shromáždění synů Izraelských: Přistuptež před oblíčej Hospodinův; neboť jest slyšel reptání vaše.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 10, 'Stalo se pak, když mluvil Aron ke všemu shromáždění synů Izraelských, že se obrátili tváří k poušti, a aj, sláva Hospodinova ukázala se v oblaku.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 11, '(A již byl mluvil Hospodin k Mojžíšovi, řka:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 12, 'Slyšelť jsem reptání synů Izraelských. Mluviž jim a pověz: K večerou jísti budete maso, a ráno chlebem nasyceni budete, abyste poznali, že já jsem Hospodin Bůh váš.)');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 13, 'Tedy stalo se u večer, že přiletěly křepelky a přikryly tábor; ráno pak spadla rosa okolo táboru.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 14, 'A když přestalo padání rosy, aj, ukázalo se po vrchu pouště drobného cosi a okrouhlého, drobného jako jíní na zemi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 15, 'Což vidouce synové Izraelští, řekli jeden druhému: Man jest toto. Nebo nevěděli, co by bylo. Tedy řekl jim Mojžíš: To jest ten chléb, kterýž vám dal Hospodin ku pokrmu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 16, 'To jest, o čemž přikázal Hospodin: Nasbírejte sobě toho každý k svému pokrmu; gomer na jednoho člověka vedlé počtu osob vašich, každý na ty, kteříž jsou v stanu jeho, vezmete.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 17, 'I učinili tak synové Izraelští, a nasbírali jiní více, jiní méně.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 18, 'Potom měřili na gomer. A nezbylo tomu, kdo nasbíral mnoho, a ten, kdo nasbíral málo, neměl nedostatku; ale každý, což mohl snísti, nasbíral.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 19, 'I řekl jim Mojžíš: Žádný ať nic z toho nepozůstavuje k jitru.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 20, 'Ale neuposlechli Mojžíše. Nebo někteří zanechali díl z toho až do jitra; i zčervivělo a zsmradilo se. Pročež rozhněval se na ně Mojžíš.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 21, 'Tak tedy sbírali to každého jitra, každý což snísti mohl. A když horké bylo slunce, tedy se ta manna rozpouštěla.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 22, 'Když pak bylo v den šestý, nasbírali toho chleba dvojnásobně, po dvou gomer na každého; protož přišla všecka knížata toho shromáždění, a pověděli Mojžíšovi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 23, 'Kterýžto řekl jim: Toť jest, což mluvil Hospodin: Odpočinutí soboty svaté Hospodinu bude zítra. Což byste měli péci, pecte, a což byste vařiti měli, vařte dnes; což pak koli zbude, nechte sobě a schovejte to k jitru.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 24, 'Protož schovali to do rána, jakž přikázal Mojžíš; a nezsmradilo se, ani v něm červů nebylo.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 25, 'I řekl Mojžíš: Jeztež to dnes, poněvadž sobota jest dnes Hospodinu; dnes toho nenaleznete na poli.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 26, 'Po šest dní budete to sbírávati, den pak sedmý sobota jest; nebude bývati manny v ní.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 27, 'Stalo se pak dne sedmého, že vyšli někteří z lidu sbírat, a nenašli.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 28, 'Tedy řekl Hospodin Mojžíšovi: I dokudž zpěčovati se budete přikázaní mých ostříhati a zákonů mých?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 29, 'Viztež, žeť Hospodin vám dal sobotu, a proto on vám dává v den šestý chleba na dva dni. Zůstaňte každý v svém, aniž kdo vycházej z místa svého v den sedmý.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 30, 'I odpočinul lid v den sedmý.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 31, 'Nazval pak lid Izraelský jméno toho chleba man; kterýž byl jako símě koliandrové, a bílý, a chut jeho jako koláče s medem.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 32, 'Řekl také Mojžíš: Toť jest, což přikázal Hospodin: Naplň gomer tou mannou, aby chována byla na budoucí věky vaše, aby viděli pokrm, kterýž jsem vám dával jísti na poušti, když jsem vás vyvedl z země Egyptské.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 33, 'I řekl Mojžíš Aronovi: Vezmi jedno věderce, a vsyp do něho plné gomer manny; a nech jí před tváří Hospodinovou, aby chována byla na budoucí věky vaše.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 34, 'A protož jakž byl přikázal Hospodin Mojžíšovi, nechal jí Aron před svědectvím, aby tu chována byla.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 35, 'Jedli pak synové Izraelští mannu za čtyřidceti let, dokudž nevešli do země, v níž bydliti měli; mannu jedli, dokudž nepřišli k končinám země Kananejské.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 36, 'Gomer pak jest desátý díl efi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 1, 'Tedy když se odebralo všecko shromáždění synů Izraelských z pouště Sin, po stanovištích svých vedlé rozkazu Hospodinova, položili se v Rafidim, kdež nebylo vod, kteréž by lid píti mohl.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 2, 'Protož domlouval se lid na Mojžíše, pravě: Dejte nám vody, abychom pili. Jimž odpověděl Mojžíš: Proč se na mne domlouváte? Proč pokoušíte Hospodina?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 3, 'I žíznil tu lid pro nedostatek vod, a reptal na Mojžíše a mluvil: Proč jsi vyvedl nás z Egypta, abys mne s syny i dobytky mými žízní zmořil?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 4, 'Tedy volal Mojžíš k Hospodinu, řka: Což mám činiti s tím lidem? Však již tudíž ukamenují mne.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 5, 'I řekl Hospodin Mojžíšovi: Jdiž před lidem, pojma s sebou některé z starších Izraelských; hůl také svou, kterouž jsi udeřil v vodu, vezmi do ruky své a jdi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 6, 'Aj, já státi budu před tebou tam na skále, na Orébě; i udeříš v skálu, a vyjdou z ní vody, kteréž bude píti lid. I učinil tak Mojžíš před očima starších Izraelských.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 7, 'A dal jméno místu tomu Massah a Meribah, pro reptání synů Izraelských, a že pokoušeli Hospodina, řkouce: Jest-li Hospodin u prostřed nás, či není?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 8, 'Přitáhl pak Amalech, a bojoval s Izraelem v Rafidim.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 9, 'I řekl Mojžíš k Jozue: Vybeř nám některé muže, a vytáhna, bojuj s Amalechem; já zítra státi budu na vrchu hory, a hůl Boží v ruce své míti budu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 10, 'Tedy Jozue udělal tak, jakž mu poručil Mojžíš, a bojoval s Amalechem; Mojžíš pak, Aron a Hur vstoupili na vrch hory.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 11, 'A dokudž Mojžíš vzhůru držel ruce své, vítězil Izrael; ale jakž opouštěl ruku svou, přemáhal Amalech.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 12, 'Ale že ruce Mojžíšovy byly obtíženy, protož vzavše kámen, podložili pod něho, a on sedl na něm; Aron pak a Hur podpírali ruce jeho, jeden z jedné, druhý z druhé strany. I byly obě ruce jeho vztažené až do západu slunce.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 13, 'A tak porazil Jozue Amalecha i lid jeho mečem.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 14, 'Mluvil potom Hospodin k Mojžíšovi: Vpiš to do knih na památku, a pilně to vkládej v uši Jozue, že do konce vyhladím památku Amalechovu všudy pod nebem.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 15, 'Tedy vzdělal Mojžíš oltář a nazval jméno jeho: Hospodin korouhev má.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 16, 'Nebo řekl: Tak má jmenován býti, proto že ruka nad trůnem Hospodinovým osvědčuje boj Hospodinův proti Amalechovi od národu až do národu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 1, 'Uslyšel pak Jetro, kníže Madianské, test Mojžíšův, o všech věcech, kteréž učinil Bůh Mojžíšovi a Izraelovi, lidu svému, že vyvedl Hospodin Izraele z Egypta.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 2, 'A vzal Jetro, test Mojžíšův, Zeforu manželku Mojžíšovu, kterouž byl odeslal,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 3, 'A dva syny její, z nichž jméno jednoho Gerson; nebo řekl: Příchozí jsem byl v zemi cizí;');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 4, 'Jméno pak druhého Eliezer; nebo řekl: Bůh otce mého spomocník můj byl, a vytrhl mne od meče Faraonova.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 5, 'I přišel Jetro, test Mojžíšův, s syny jeho i s ženou jeho k Mojžíšovi na poušť, kdež se byl položil při hoře Boží.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 6, 'A vzkázal Mojžíšovi: Já, test tvůj Jetro, jdu k tobě, i žena tvá a oba synové její s ní.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 7, 'I vyšel Mojžíš proti testi svému, a pokloniv se, políbil ho. I ptal se jeden druhého, jak se má; potom vešli do stanu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 8, 'A vypravoval Mojžíš testi svému všecko, což učinil Hospodin Faraonovi a Egyptským pro Izraele, a o všech nevolech, kteréž přicházely na ně na cestě, a jak je vysvobodil Hospodin.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 9, 'I radoval se Jetro ze všeho dobrého, což učinil Hospodin Izraelovi, a že vytrhl jej z ruky Egyptských.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 10, 'A řekl Jetro: Požehnaný Hospodin, kterýž vytrhl vás z ruky Egyptských a z ruky Faraonovy, kterýž vytrhl ten lid z poroby Egyptské.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 11, 'Nyní jsem poznal, že větší jest Hospodin nade všecky bohy; nebo touž věcí, kterouž se vyvyšovali, on je převýšil.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 12, 'A vzal Jetro, test Mojžíšův, zápal a oběti, kteréž obětoval Bohu. Potom přišel Aron a všickni starší Izraelští, aby jedli chléb s tchánem Mojžíšovým před Bohem.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 13, 'Nazejtří pak posadil se Mojžíš, aby soudil lid; a stál lid před Mojžíšem od jitra až do večera.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 14, 'Vida pak test Mojžíšův všecku práci jeho při lidu, řekl: Co jest to, což děláš s lidem? Proč ty sám sedíš, a všecken lid stojí před tebou od jitra až do večera?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 15, 'Odpověděl Mojžíš tchánu svému: Přichází ke mně lid raditi se s Bohem.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 16, 'Když mají o nějakou věc činiti, přicházejí ke mně, a soud činím mezi stranami, a oznamuji rady Boží a ustanovení jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 17, 'I řekl jemu test Mojžíšův: Nedobře děláš.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 18, 'Tudíž tak ustaneš i ty i lid, kterýž s tebou jest. Nad možnost tvou těžká jest tato věc, nebudeš jí moci sám dosti učiniti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 19, 'Protož nyní uposlechni řeči mé; poradím tobě, a bude Bůh s tebou. Stůj ty za lid před Bohem, a donášej věci nesnadné k Bohu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 20, 'A vysvětluj jim řády a zákony, a oznamuj jim cestu, po níž by šli, a co by dělati měli.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 21, 'Vyhledej také ze všeho lidu muže statečné, bohabojné, muže pravdomluvné, kteříž v nenávisti mají lakomství, a ustanov z nich knížata nad tisíci, setníky, padesátníky a desátníky.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 22, 'Oni ať soudí lid každého času. Což bude většího, vznesou na tebe, a menší pře sami nechť soudí; a tak lehčeji bude tobě, když jiní ponesou břímě s tebou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 23, 'Jestliže to učiníš a rozkážeť Bůh, budeš moci trvati; také i všecken lid tento navracovati se bude k místům svým pokojně.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 24, 'Tedy uposlechl Mojžíš řeči tchána svého, a učinil všecko, což on řekl.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 25, 'A vybral Mojžíš muže statečné ze všeho Izraele, a ustanovil je hejtmany nad lidem, knížata nad tisíci, setníky, padesátníky a desátníky,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 26, 'Kteříž soudili lid každého času. Nesnadnější věci vznášeli na Mojžíše, všecky pak menší pře sami soudili.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 27, 'Potom propustil Mojžíš tchána svého; i odšel do země své.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 1, 'Měsíce třetího po vyjití synů Izraelských z země Egyptské, v ten den přišli na poušť Sinai.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 2, 'Nebo hnuvše se z Rafidim, přišli až na poušť Sinai a položili se na té poušti; a tu rozbili Izraelští stany naproti hoře.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 3, 'Mojžíš pak vstoupil k Bohu. A mluvil hlasem k němu Hospodin s té hory, řka: Takto díš domu Jákobovu, a oznámíš synům Izraelským:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 4, 'Sami jste viděli, co jsem učinil Egyptským, a jak jsem vás nesl na křídlách orličích, a přivedl jsem vás k sobě.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 5, 'Protož nyní, jestliže skutečně poslouchati budete hlasu mého, a ostříhati smlouvy mé, budete mi lid zvláštní mimo všecky lidi, ačkoli má jest všecka země.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 6, 'A vy budete mi království kněžské a národ svatý. Tať jsou slova, kteráž mluviti budeš synům Izraelským.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 7, 'Protož přišel Mojžíš a svolav starší lidu, předložil jim všecka slova ta, kteráž mu přikázal Hospodin.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 8, 'Odpověděl pak všecken lid společně, a řekl: Cožkoli mluvil Hospodin, budeme činiti. A oznámil zas Mojžíš Hospodinu slova lidu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 9, 'I řekl Hospodin Mojžíšovi: Aj, já půjdu k tobě v hustém oblaku, aby slyšel lid, když mluviti budu s tebou, ano také, aby tobě věřil na věky. Nebo byl oznámil Mojžíš Hospodinu slova lidu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 10, 'Řekl dále Hospodin Mojžíšovi: Jdi k lidu, a posvěť jich dnes a zítra; a nechť svá roucha zeperou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 11, 'A ať jsou hotovi ke dni třetímu, nebo v den třetí sstoupí Hospodin před očima všeho lidu na horu Sinai.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 12, 'Uložíš pak lidu meze všudy vůkol a povíš: Varujte se, abyste nevstupovali na horu, ani nedotýkali se krajů jejích. Kdož by se koli dotkl hory, smrtí umře.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 13, 'Nedotkneť se ho ruka, ale ukamenován neb zastřelen bude; buď že by hovado bylo, buď člověk, nebudeť živ. Když se zdlouha troubiti bude, teprv oni vstoupí na horu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 14, 'Sstoupiv tedy Mojžíš s hůry k lidu, posvětil ho; a oni zeprali roucha svá.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 15, 'I mluvil k lidu: Buďtež hotovi ke dni třetímu; nepřistupujte k manželkám svým.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 16, 'I stalo se dne třetího, když bylo ráno, že bylo hřímání s blýskáním a oblak hustý na té hoře, zvuk také trouby velmi tuhý, až se zhrozil všecken lid, kterýž byl v ležení.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 17, 'Tedy Mojžíš vyvedl lid z ležení vstříc Bohu; a lid stál dole pod horou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 18, 'Hora pak Sinai všecka se kouřila, proto že sstoupil na ni Hospodin v ohni, a vystupoval dým její jako dým z vápenice, a třásla se všecka hora velmi hrubě.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 19, 'Zvuk také trouby více se rozmáhal, a silil se náramně. Mojžíš mluvil, a Bůh mu odpovídal hlasem.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 20, 'Sstoupil pak Hospodin na horu Sinai, na vrch hory; a když povolal Hospodin Mojžíše na vrch hory, vstoupil Mojžíš.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 21, 'I řekl Hospodin Mojžíšovi: Sstup, osvědč lidu, ať se nevytrhují k Hospodinu, chtějíce ho viděti, aby nepadlo jich množství;');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 22, 'Nýbrž ani sami kněží, kteříž, majíce přistupovati k Hospodinu, posvěcují se, aby se neobořil na ně Hospodin.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 23, 'Mojžíš pak řekl Hospodinu: Nebudeť moci lid vstoupiti na horu Sinai, poněvadž jsi ty osvědčil nám, řka: Obmez horu a posvěť ji.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 24, 'I řekl jemu Hospodin: Jdi, sstup, a potom vstup ty a Aron s tebou. Kněží pak a lid ať se nepokoušejí vstoupiti k Hospodinu, aby se na ně neobořil.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 25, 'I sešel Mojžíš k lidu, a to jim oznámil.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 1, 'I mluvil Bůh všecka slova tato, řka:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 2, 'Já jsem Hospodin Bůh tvůj, kterýž jsem tě vyvedl z země Egyptské, z domu služby.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 3, 'Nebudeš míti bohů jiných přede mnou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 4, 'Neučiníš sobě rytiny, ani jakého podobenství těch věcí, kteréž jsou na nebi svrchu, ani těch, kteréž na zemi dole, ani těch, kteréž u vodách pod zemí.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 5, 'Nebudeš se jim klaněti, ani jich ctíti. Nebo já jsem Hospodin Bůh tvůj, Bůh silný, horlivý, navštěvující nepravost otců na synech do třetího i čtvrtého pokolení těch, kteříž nenávidí mne,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 6, 'A činící milosrdenství nad tisíci těmi, kteříž mne milují, a ostříhají přikázaní mých.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 7, 'Nevezmeš jména Hospodina Boha svého nadarmo; neboť nenechá bez pomsty Hospodin toho, kdož by bral jméno jeho nadarmo.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 8, 'Pomni na den sobotní, abys jej světil.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 9, 'Šest dní pracovati budeš, a dělati všeliké dílo své;');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 10, 'Ale dne sedmého odpočinutí jest Hospodina Boha tvého. Nebudeš dělati žádného díla, ty i syn tvůj i dcera tvá, služebník tvůj i děvka tvá, hovado tvé i příchozí, kterýž jest v branách tvých.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 11, 'Nebo v šesti dnech učinil Hospodin nebe a zemi, moře a všecko, což v nich jest, a odpočinul dne sedmého; protož požehnal Hospodin dne sobotního, a posvětil ho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 12, 'Cti otce svého i matku svou, ať se prodlejí dnové tvoji na zemi, kterouž Hospodin Bůh tvůj dá tobě.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 13, 'Nezabiješ.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 14, 'Nesesmilníš.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 15, 'Nepokradeš.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 16, 'Nepromluvíš proti bližnímu svému křivého svědectví.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 17, 'Nepožádáš domu bližního svého, aniž požádáš manželky bližního svého, ani služebníka jeho, ani děvky jeho, ani vola jeho, ani osla jeho, ani cožkoli jest bližního tvého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 18, 'Veškeren pak lid viděl hřímání to a blýskání, a zvuk trouby, a horu kouřící se. To když viděl lid, pohnuli se a stáli zdaleka.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 19, 'A řekli Mojžíšovi: Mluv ty s námi, a poslouchati budeme; a nechť nemluví s námi Bůh, abychom nezemřeli.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 20, 'Odpověděl Mojžíš lidu: Nebojte se; nebo pro zkušení vás sám Bůh přišel, aby bázeň jeho byla mezi vámi, abyste nehřešili.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 21, 'Tedy stál lid zdaleka; Mojžíš pak přistoupil k mrákotě, kdež byl Bůh.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 22, 'I řekl Hospodin Mojžíšovi: Tak povíš synům Izraelským: Vy jste sami viděli, že s nebe mluvil jsem s vámi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 23, 'Protož nevyzdvihujte ničehož ku poctě se mnou; bohů stříbrných a bohů zlatých neučiníte sobě.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 24, 'Oltář z země uděláš mi a obětovati budeš na něm zápaly své, a pokojné oběti své, ovce své a voly své. Na kterémkoli místě rozkáži slaviti památku jména svého, přijdu k tobě a požehnám tobě.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 25, 'Jestliže mi pak vzděláš oltář kamenný, nedělej ho z kamene tesaného; nebo jestliže pozdvihneš železa na něj, poškvrníš ho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 26, 'Aniž po stupních vstupovati budeš k oltáři mému, aby hanba tvá u něho odkryta nebyla.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 1, 'Tito jsou pak soudové, kteréž jim předložíš:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 2, 'Jestliže koupíš k službě Žida, šest let sloužiti bude, a sedmého odejde svobodný darmo.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 3, 'Přišel-li by sám toliko, sám také odejde; pakli měl ženu, vyjde s ním i žena jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 4, 'Jestliže pán jeho dá mu ženu, a ona zrodí jemu syny neb dcery: žena ta i děti její budou pána jeho, on pak sám toliko odejde.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 5, 'Pakli by řekl služebník: Miluji pána svého, manželku svou a syny své, nevyjdu svobodný:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 6, 'Tedy postaví ho pán jeho před soudci, a přivede ho ke dveřím neb k veřeji, a probodne pán jeho ucho jemu špicí; i zůstaneť služebníkem jeho na věky.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 7, 'Když by pak prodal někdo dceru svou, aby byla děvkou, nevyjdeť tak, jako vycházejí služebníci.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 8, 'Nelíbila-li by se pánu svému, kterýž jí sobě ještě nezasnoubil, dopustí ji vyplatiti. Lidu cizímu nebude míti práva prodati ji, poněvadž zhřešil proti ní.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 9, 'Pakli by synu svému ji zasnoubil, učiníť jí tak, jakž obyčej jest činiti dcerám.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 10, 'A dal-li by mu jinou, z stravy její, oděvu jejího, a přívětivosti manželské nic této neujme.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 11, 'Neudělal-li by nic z toho trojího, vyjde darmo bez stříbra.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 12, 'Kdo by ubil člověka, až by od toho umřel, smrtí umře.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 13, 'Když by pak neukládal o bezživotí jeho, než Bůh dal by jej v ruce jeho: tedy uložím tobě místo, do něhož by takový mohl uteci.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 14, 'Pakli by kdo tak pyšně sobě počínal proti bližnímu svému, že by ho lstivě zabil, i od oltáře mého odtrhneš jej, aby umřel.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 15, 'Kdo by otce svého neb matku svou bil, smrtí ať umře.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 16, 'Kdo by pak, ukradna někoho, prodal jej, a nalezen by byl v ruce jeho, smrtí ať umře.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 17, 'I ten, kdož by zlořečil otci svému neb mateři své, smrtí ať umře.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 18, 'Když by se svadili muži, a urazil by který bližního svého kamenem neb pěstí, a ten by neumřel, než složil se na lůži;');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 19, 'A potom by povstal a chodil vně o holi své: již nebude vinen ten, kdož urazil; toliko co zatím obmeškal, to jemu nahradí, a na vyhojení jeho naloží.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 20, 'Když by pak ubil kdo služebníka svého neb děvku svou kyjem, tak že by umřel mu v ruce jeho: pomstou pomštěno bude nad takovým.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 21, 'A však jestliže by den neb dva přečkal, neponese pomsty, nebo jej zaplatil.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 22, 'Když by se svadili muži, a urazili ženu těhotnou, tak že by vyšel z ní plod její, však by se zhouba nestala: pokutován bude, jakž by uložil naň muž té ženy, a dá vedlé uznání soudců.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 23, 'Pakliť by smrt přišla, tedy dáš život za život,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 24, 'Oko za oko, zub za zub, ruku za ruku, nohu za nohu,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 25, 'Spáleninu za spáleninu, ránu za ránu, modřinu za modřinu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 26, 'Jestliže by kdo urazil služebníka svého v oko, aneb děvku svou v oko, tak že by jej o ně připravil: svobodného jej propustí za oko jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 27, 'Pakli by zub služebníku svému neb zub děvce své vyrazil, svobodného jej propustí za zub jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 28, 'Jestliže by vůl utrkl muže neb ženu, tak že by umřel člověk: ukamenován bude ten vůl, aniž jedeno bude maso jeho, však pán vola toho bez viny bude.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 29, 'Než byl-liť by vůl trkavý prvé, a bylo by to osvědčeno pánu jeho, on pak nezavřel by ho, a v tom zabil by muže neb ženu: vůl ten ukamenován bude, a pán jeho také umře.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 30, 'Pakliť mu bude uloženo, aby se vyplatil: tedy dá výplatu za život svůj, jakážkoli na něj uložena bude.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 31, 'Buď že by syna utrkl, buď dceru, podlé soudu toho stane se jemu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 32, 'Jestliže by služebníka vůl ztrkal neb děvku, třidceti lotů stříbra dá pánu jeho, a vůl ten bude ukamenován.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 33, 'Kdyby kdo odhradil studnici, a neb vykopal někdo studnici, a zase jí nepřikryl, a vpadl by tam vůl neb osel:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 34, 'Pán té studnice nahradí to, a peníze položí pánu jeho, a což se zabilo, to sobě míti bude.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 35, 'A ustrčil-li by vůl něčí vola sousedova, že byl umřel: tedy prodadí vola toho živého, a podělí se penězi jeho; i s zabitým volem také se rozdělí.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 36, 'Pakli vědíno bylo, že vůl byl trkavý prvé, a nezavřel ho pán jeho: bez výmluvy ať dá vola za vola, a zabitý ať mu zůstane.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 1, 'Jestliže by kdo ukradl vola aneb dobytče, a zabil by je neb prodal: pět volů navrátí za toho vola, a čtvero dobytčat za to dobytče.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 2, '(Jestliže by zloděj zastižen byl při podkopávání a ubit jsa, umřel by: ten, kdo ho ranil, nebude vinen smrtí.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 3, 'Pakli by to ve dne učinil, smrtí vinen bude.) Bez prodlévání ať navrátí; pakli nemá co, prodán bude pro zlodějství své.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 4, 'Jestliže nalezena bude v rukou jeho krádež, buď vůl, neb osel, buď dobytče ještě živé, dvénásobně navrátí.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 5, 'Jestliže by kdo spásl pole neb vinici, a vpustil hovado své, aby se páslo na cizím poli: což nejlepšího má na poli svém neb vinici své, tím tu škodu nahradí.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 6, 'Vyšel-li by oheň, a chytilo by se trní, a shořel by stoh neb stojaté obilí neb pole: nahradí ten, kdož zapálil, to, což shořelo.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 7, 'Kdyby někdo dal schovati bližnímu svému peníze neb nádoby, a bylo by ukradeno z domu muže toho, jestliže nalezen bude zloděj, dvojnásobně navrátí.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 8, 'Pakli nebude zloděj nalezen, tedy postaven bude pán domu toho před soudce, a přisáhne, že nevztáhl ruky své na věc bližního svého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 9, 'O všelijakou věc, o niž by byla nesnáz, buď o vola neb osla, dobytče neb roucho, pro všelikou věc ztracenou, když by kdo pravil, že to jest: před soudce přijde pře obou dvou; ten, kohož oni vinného usoudí, dvojnásobně navrátí bližnímu svému.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 10, 'Jestliže by kdo dal bližnímu svému k chování osla neb vola, neb dobytče a jakékoli hovado, a umřelo by neb ochromělo, neb zajato bylo, že žádný neviděl:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 11, 'Přísaha Hospodinova vkročí mezi oba, že nevztáhl ruky své k věci bližního svého; a přijme jej v tom pán věci té, a onen nebude povinen navraceti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 12, 'Pakli by krádeží vzato bylo od něho, navrátiti zase má pánu jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 13, 'Pakli by udáveno bylo, postaví svědka a nebude povinen upláceti toho, což udáveno jest.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 14, 'Kdyby pak někdo vypůjčil něčeho od bližního svého, a ochromělo by aneb umřelo v nepřítomnosti pána jeho, bez výmluvy navrátí zase.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 15, 'Pakli by pán jeho byl s ním, není povinen platiti, poněvadž bylo za peníze najaté, a přišlo za mzdu svou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 16, 'Jestliže by kdo namluvil pannu, kteráž není zasnoubena, a spal by s ní: dáť jí věno, a vezme ji sobě za manželku.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 17, 'Pakli by otec její nikoli nechtěl jí dáti jemu, odváží stříbra podlé obyčeje věna panenského.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 18, 'Čarodějnici nedáš živu býti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 19, 'Kdo by koli scházel se s hovadem, smrtí ať umře.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 20, 'Kdo by obětoval bohům, kromě samému Hospodinu, jako proklatý vyhlazen bude.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 21, 'Příchozímu neučiníš křivdy, aniž utiskneš ho; nebo příchozí byli jste v zemi Egyptské.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 22, 'Žádné vdovy neb sirotka trápiti nebudete.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 23, 'Pakli bez lítosti trápiti je budete, a oni by volali ke mně, vězte, že vyslyším křik jejich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 24, 'A rozhněvá se prchlivost má, i zbiji vás mečem; a budou ženy vaše vdovy a děti vaši sirotci.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 25, 'Půjčíš-li peněz lidu mému chudému, kterýž jest s tebou: nebudeš jemu jako lichevník, aniž ho lichvou obtížíš.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 26, 'Pakli v základu vezmeš roucho bližního svého, do západu slunce jemu je navrátíš.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 27, 'Nebo ten jediný má oděv, to jest roucho, jímž přikrývá tělo své, a na němž spí. Když bude volati ke mně, tedy uslyším, nebo jsem milosrdný.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 28, 'Soudcům nebudeš utrhati, a knížeti lidu svého zlořečiti nebudeš.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 29, 'Z hojnosti obilí, a tekutých věcí svých neobmeškáš prvotin obětovati. Prvorozeného z synů svých mně dáš.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 30, 'Tak učiníš s volem svým a s dobytkem svým: Sedm dní bude s matkou svou, dne pak osmého mně je dáš.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 31, 'Lid svatý budete mi, a nebudete jísti masa z udáveného na poli; psu je vržete.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 1, 'Nebudeš vynášeti pověsti lživé. Neklaď s bezbožným ruky své, abys měl býti s ním svědek nepravý.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 2, 'Nepostoupíš po množství ke zlému, a nebudeš se přimlouvati k rozepři, tak abys se uchýlil po větším počtu k převrácení soudu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 3, 'Ani chudého šanovati nebudeš v při jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 4, 'Trefil-li bys na vola nepřítele svého neb osla jeho, an bloudí, obrátíš a dovedeš ho k němu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 5, 'Uzřel-li bys an osel toho, jenž tě má v nenávisti, leží pod břemenem svým, zdaž se zdržíš, abys mu neměl pomoci? Nýbrž opravdově pomůžeš jemu, spolu s tím, kdož tě v nenávisti má.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 6, 'Nepřevrátíš soudu chudého svého v jeho při.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 7, 'Od slova lživého vzdálíš se. Nevinného a spravedlivého nezabiješ, nebo já neospravedlním bezbožného.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 8, 'Aniž bráti budeš darů, nebo dar oslepuje i prozřetelné, a převrací slova spravedlivých.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 9, 'Příchozího nebudeš ssužovati; nebo sami znáte, jaký jest život příchozích, poněvadž pohostinu jste byli v zemi Egyptské.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 10, 'Po šest let osívati budeš zemi svou, a shromažďovati úrodu její;');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 11, 'Sedmého pak léta ponecháš jí, ať odpočine, aby jedli chudí lidu tvého. Co pak zůstane po nich, pojí zvěř polní. Tak uděláš s vinicí svou i s olivovím svým.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 12, 'Šest dní budeš dělati díla svá, dne pak sedmého přestaneš, aby odpočinul vůl tvůj i osel tvůj, a oddechl syn děvky tvé i příchozí.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 13, 'Ve všech těch věcech, kteréž mluvil jsem vám, ostříhati se budete. Jména bohů cizích ani připomínati nebudete, aniž bude slyšáno z úst tvých.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 14, 'Třikrát slaviti mi budeš svátek na každý rok.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 15, 'Slavnosti přesnic ostříhati budeš. Sedm dní jísti budeš chleby přesné, jakž jsem přikázal tobě, v čas vyměřený měsíce Abib; nebo v ten vyšel jsi z Egypta. Aniž se ukážete přede mnou prázdní.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 16, 'A držeti budeš slavnost žně, když mi obětovati budeš prvotiny prací svých z toho, což jsi vsel na poli. Slavnost také sklizení držeti budeš při vyjití roku, když sklidíš práce své z pole.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 17, 'Třikrát v roce ukáže se každý z tvých pohlaví mužského před tváří Panovníka Hospodina.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 18, 'Nebudeš obětovati krve z oběti mé, dokavadž u tebe kvas jest, aniž zůstane tuk slavnosti mé do jitra.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 19, 'Prvotiny prvních úrod země své přinášeti budeš do domu Hospodina Boha svého. Nebudeš vařiti kozelce v mléku mateře jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 20, 'Aj, já pošli anděla před tebou, aby ostříhal tebe na cestě, a přivedl tě na místo, kteréž jsem připravil.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 21, 'Šetrně se měj před ním, a poslouchej hlasu jeho. Nepopouzej ho, neboť nepromine přestoupení vašeho, poněvadž jméno mé jest u prostřed něho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 22, 'Nebo budeš-li věrně poslouchati hlasu jeho, a činiti, cožť bych koli řekl: tedy nepřítelem budu nepřátel tvých, a trápiti budu ty, jenž tebe trápí.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 23, 'Nebo půjde anděl můj před tebou, a uvede tě do země Amorejského a Hetejského, Ferezejského a Kananejského, Hevejského a Jebuzejského, kteréž vyhladím.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 24, 'Nebudeš se klaněti bohům jejich, ani jim sloužiti, aniž dělati budeš tak, jako oni dělají; ale z gruntu vyvrátíš je, a obrazy jejich na kusy stroskoceš.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 25, 'Sloužiti pak budete Hospodinu Bohu svému, a požehnáť chlebu tvému i vodám tvým; a odejmu nemoc z prostředku tvého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 26, 'Nebudeť, která by potratila, ani neplodná v zemi tvé; počet dnů tvých doplním.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 27, 'Strach svůj pustím před tebou, a předěsím všeliký lid, proti kterémuž vyjdeš, a způsobím to, aby všickni nepřátelé tvoji utíkali před tebou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 28, 'Pošli i sršně před tebou, aby vyhnali Hevea, a Kananea a Hetea před tváří tvou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 29, 'Nevyženu ho od tváři tvé v jednom roce, aby se země neobrátila v poušť, a nerozmnožily se proti tobě šelmy divoké.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 30, 'Pomalu vyháněti jej budu od tváři tvé, až bys ty se rozplodil, a dědičně mohl ujíti zemi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 31, 'Položím pak meze tvé od moře Rudého až k moři Filistinskému, a od pouště až k řece; nebo v ruce vaše dám obyvatele země, a vyženeš je od tváři své.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 32, 'Neučiníš s nimi a bohy jejich smlouvy.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 33, 'Nebudou bydliti v zemi tvé, aby nepřipravili tě k hříchu proti mně, když bys ctil bohy jejich; nebo by to bylo tobě osídlem.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 1, 'Mojžíšovi pak řekl: Vstup k Hospodinu ty a Aron, Nádab a Abiu, a sedmdesáte z starších Izraelských, a klaněti se budete zdaleka.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 2, 'Sám pak toliko Mojžíš vstoupí k Hospodinu, ale oni se nepřiblíží; aniž lid vstoupí s ním.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 3, 'Tedy přišel Mojžíš, a vypravoval lidu všecka slova Hospodinova a všecky soudy. I odpověděl všecken lid jedním hlasem, a řekli: Všecka slova, kteráž mluvil Hospodin, učiníme.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 4, 'Napsal pak Mojžíš všecka slova Hospodinova, a vstav ráno, vzdělal oltář pod horou, a dvanácte sloupů podlé počtu dvanáctera pokolení Izraelského.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 5, 'A poslal mládence z synů Izraelských, kteříž obětovali zápaly; a obětovali oběti pokojné Hospodinu, totiž voly.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 6, 'I vzav Mojžíš polovici krve, vlil do medenic, a polovici druhou vylil na oltář.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 7, 'Vzav také knihu smlouvy, četl v uších lidu. Kteříž řekli: Cožkoli mluvil Hospodin, činiti a poslouchati budeme.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 8, 'Vzal také Mojžíš krev a pokropil lidu a řekl: Aj, krev smlouvy, kterouž učinil s vámi Hospodin při všech těchto věcech.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 9, 'Potom vstoupili Mojžíš a Aron, Nádab a Abiu a sedmdesáte z starších Izraelských,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 10, 'A viděli Boha Izraelského. A pod nohami jeho bylo jako dílo z kamene zafirového, a jako nebe, když jest jasné.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 11, 'Na knížata pak synů Izraelských nevztáhl ruky své, ačkoli viděli Boha, a potom jedli i pili.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 12, 'I řekl Hospodin Mojžíšovi: Vstup ke mně na horu a buď tam; a dám tobě tabule kamenné, zákon i přikázaní, kteráž jsem napsal, abys je učil.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 13, 'Tedy vstal Mojžíš a Jozue služebník jeho; i vstoupil Mojžíš na horu Boží.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 14, 'Starším pak řekl: Zůstaňte tuto, dokudž se nenavrátíme k vám. A teď Aron a Hur jsou s vámi, kdož by měl rozepři, k nim ať jde.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 15, 'Tedy vstoupil Mojžíš na horu, a přikryl oblak horu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 16, 'I přebývala sláva Hospodinova na hoře Sinai, a přikryl ji oblak za šest dní; a dne sedmého zavolal na Mojžíše z prostřed oblaku.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 17, 'A tvárnost slávy Hospodinovy byla jako spalující oheň na vrchu hory, před očima synů Izraelských.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 18, 'I všel Mojžíš do prostřed oblaku a vstoupil na horu. A byl Mojžíš na hoře čtyřidceti dní a čtyřidceti nocí.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 1, 'I mluvil Hospodin k Mojžíšovi, řka:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 2, 'Mluv k synům Izraelským, ať mi vybírají obět vzhůru pozdvižení. Od každého člověka, kterýž by ji z srdce dobrovolně dal, přijměte takovou obět mou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 3, 'Tatoť pak jest obět pozdvižení, kterouž budete bráti od nich: Zlato, a stříbro, a měď,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 4, 'Postavec modrý, šarlat, a červec dvakrát barvený, bílé hedbáví a srsti kozí;');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 5, 'Též kůže skopcové na červeno barvené, a kůže jezevčí, a dříví setim,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 6, 'Olej k svícení, vonné věci na olej ku pomazování, a pro kadění vonné věci;');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 7, 'Kamení onychinové, a jiné kamení k vsazování do náramníku a náprsníku.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 8, 'I udělajíť mi svatyni, abych bydlil u prostřed nich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 9, 'Vedlé všeho, jakž já ukazuji tobě podobenství stánku a podobenství všech nádob jeho, tak uděláte.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 10, 'Udělají také truhlu z dříví setim. Půl třetího lokte bude dlouhost její, půl druhého lokte širokost její, půl druhého také lokte vysokost její.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 11, 'A obložíš ji zlatem čistým, vnitř i zevnitř obložíš ji; a uděláš nad ní vůkol korunu zlatou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 12, 'Sliješ k ní také čtyři kruhy zlaté, kteréž přiděláš ke čtyřem úhlům jejím, dva totiž kruhy po jedné straně její, a dva kruhy po druhé straně její.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 13, 'Uděláš k tomu i sochory z dříví setim, a obložíš je zlatem.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 14, 'I uvlečeš sochory do kruhů po stranách té truhly, aby na nich nošena byla truhla.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 15, 'V kruzích té truhly budou bývati sochorové; nebudou vytahováni z nich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 16, 'A dáš do truhly svědectví, kteréž dám tobě.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 17, 'Uděláš i slitovnici z zlata čistého. Půl třetího lokte bude dlouhost její, půl druhého pak lokte širokost její.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 18, 'Uděláš také dva cherubíny zlaté, z taženého zlata uděláš je na dvou koncích slitovnice.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 19, 'Uděláš pak cherubína jednoho na jednom konci, a cherubína druhého na druhém konci; na slitovnici uděláte cherubíny na obou koncích jejích.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 20, 'A budou míti cherubínové křídla vztažená svrchu, zastírajíce křídly svými slitovnici, a tváři jejich obráceny budou jednoho k druhému; k slitovnici budou tváři cherubínů.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 21, 'Dáš pak slitovnici svrchu na truhlu, a do truhly vložíš svědectví, kteréž dám tobě.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 22, 'A tam budu přicházeti k tobě, a s tebou z té slitovnice, z prostředku dvou cherubínů, kteříž jsou nad truhlou svědectví, mluviti o všecko, cožť bych poroučeti chtěl k synům Izraelským.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 23, 'Uděláš také stůl z dříví setim. Dvou loket bude dlouhost jeho, a na loket širokost jeho, půl druhého pak lokte vysokost jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 24, 'A obložíš jej zlatem čistým, a uděláš mu okolek zlatý vůkol.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 25, 'Uděláš také okolo něho lištu čtyř prstů zšíří; a okolek zlatý uděláš okolo té lišty.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 26, 'Uděláš u něho i čtyři kruhy zlaté, kteréž vpustíš do čtyř úhlů, kteříž jsou ve čtyřech nohách jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 27, 'Pod tou lištou budou kruhové, skrze něž provlačováni budou sochorové k nošení stolu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 28, 'Ty pak sochory uděláš z dříví setim, a obložíš je zlatem; i bude stůl nošen na nich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 29, 'Uděláš také misy jeho, a lžice jeho, a přikryvadla jeho, a koflíky jeho, k přikrývání; z čistého zlata naděláš toho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 30, 'A klásti budeš na ten stůl chleby předložení před tvář mou ustavičně.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 31, 'Uděláš také svícen z zlata čistého, z taženého zlata ať jest ten svícen; sloupec jeho i prutové jeho, misky jeho a koule jeho, i květové jeho z něho budou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 32, 'A šest prutů vycházeti bude z boků jeho, tři prutové svícnu s jedné strany jeho, a tři prutové s druhé strany jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 33, 'Tři misky udělané na způsob pecky mandlové ať jsou na prutu jednom, a koule a květ, a tři misky udělané na způsob pecky mandlové na prutu druhém, a koule a květ; takž i na jiných šesti prutech z svícnu vycházejících.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 34, 'Na svícnu také budou čtyři misky udělané na způsob mandlové pecky, a koule jeho, i květové jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 35, 'A bude koule pode dvěma pruty z něho, koule též pod druhými dvěma pruty z něho, koule opět pod jinými dvěma pruty z něho; a tak pod šesti pruty vycházejícími z svícna.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 36, 'Koule jejich i prutové jejich z něho budou; všecko to z cela kované z zlata čistého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 37, 'Uděláš i sedm lamp na něj; a bude je rozsvěcovati kněz, aby svítily po stranách jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 38, 'I utěradla jeho, i nádoby k oharkům jeho z zlata čistého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 39, 'Z centnéře zlata čistého uděláno bude to se vším tím nádobím.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 40, 'Hlediž pak, abys udělal podlé podobenství toho, kteréž tobě ukázáno jest na hoře.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 1, 'Příbytek pak uděláš z desíti čalounů, kteříž budou z bílého hedbáví soukaného, a z postavce modrého, a z šarlatu, a z červce dvakrát barveného; a cherubíny dílem řemeslným uděláš.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 2, 'Dlouhost čalounu jednoho osm a dvadceti loket, a širokost čalounu jednoho čtyři lokty; míra jedna bude všech čalounů.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 3, 'Pět čalounů spolu spojeno bude jeden s druhým, a pět druhých čalounů též spolu spojeno bude jeden s druhým.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 4, 'A naděláš i ok z hedbáví modrého po kraji čalounu jednoho na konci, kde se má spojovati s druhým; a tolikéž uděláš na kraji čalounu druhého na konci v spojení druhém.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 5, 'Padesáte ok uděláš na čalounu jednom, a padesáte ok uděláš po kraji čalounu, kterýmž má připojen býti k druhému; oko jedno proti druhému aby bylo.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 6, 'Uděláš také padesáte haklíků zlatých a spojíš čalouny jeden s druhým haklíky těmi; a tak bude příbytek jeden.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 7, 'Nadto uděláš houní z srstí kozích na stánek k přistírání příbytku po vrchu; jedenácte takových houní uděláš.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 8, 'Dlouhost houně jedné třidceti loktů, a širokost houně jedné čtyř loktů; jednostejná míra těch jedenácti houní bude.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 9, 'A spojíš pět houní obzvláštně, a šest houní opět obzvláštně, a přehneš na dvé houni šestou napřed v čele stánku.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 10, 'Uděláš pak padesáte ok po kraji houně jedné na konci, kdež se spojovati má, a padesáte ok po kraji houně k spojení druhému.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 11, 'Uděláš také haklíků měděných padesát, kteréž vepneš do ok, a spojíš stánek, aby byl jedno.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 12, 'Co pak zbývá houní po přikrytí stánku, totiž půl houně přesahující, převisne při zadní straně příbytku.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 13, 'A loket s jedné a loket s druhé strany, zbývající na dýl z houní stánku, převisne po stranách příbytku sem i tam, aby jej přikrýval.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 14, 'Uděláš také přikrytí na stánek z koží skopových na červeno barvených, přikrytí také z koží jezevčích svrchu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 15, 'Naděláš k příbytku i desk stojatých z dříví setim.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 16, 'Desíti loktů dlouhost dsky, a půl druhého lokte širokost dsky jedné.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 17, 'Dva čepy dska jedna míti bude, podobně jako stupně u schodu zpořádané, jeden proti druhému; tak uděláš u všech desk příbytku.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 18, 'Zděláš pak desky k příbytku, dvadceti desk k straně polední, k větru polednímu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 19, '(A čtyřidceti podstavků stříbrných uděláš pod dvadceti desk; dva podstavky pod jednu dsku ke dvěma čepům jejím, a dva podstavky pod dsku druhou pro dva čepy její.)');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 20, 'Na druhé pak straně příbytku k straně půlnoční dvadceti desk,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 21, 'A čtyřidceti podstavků jejich stříbrných; dva podstavky pod jednu dsku a dva podstavky pod dsku druhou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 22, 'Na straně také příbytku k západu šest uděláš desk.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 23, 'A dvě dsky uděláš v obou dvou úhlech příbytku;');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 24, 'Kteréž budou spojené pozpodu, a tolikéž spojené svrchu k jednomu kruhu; tak bude při dvou těch, ve dvou úhlech budou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 25, 'A tak bude osm desk, a podstavkové jejich stříbrní, šestnácte podstavků; dva podstavkové pod dskou jednou a dva podstavkové pod dskou druhou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 26, 'Naděláš také svlaků z dříví setim. Pět jich bude dskám k straně příbytku jedné,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 27, 'A pět svlaků dskám při straně příbytku druhé, a pět svlaků dskám k straně západní příbytku dosahující k oběma úhlům.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 28, 'Ale prostřední svlak u prostřed desk provleče se od jednoho konce k druhému.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 29, 'Ty pak dsky obložíš zlatem, a kruhy k nim uděláš zlaté, do nichž by svlakové byli uvlačováni; a obložíš i svlaky zlatem.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 30, 'A tak vyzdvihneš příbytek podlé způsobu toho, kterýž tobě ukázán na hoře.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 31, 'Uděláš i oponu z postavce modrého, a z šarlatu, a z červce dvakrát barveného, a z bílého hedbáví soukaného; dílem řemeslným uděláš ji s cherubíny.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 32, 'A zavěsíš ji na čtyřech sloupích z dříví setim, obložených zlatem, (hákové jejich zlatí), na čtyřech podstavcích stříbrných.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 33, 'A dáš oponu na háky, a vneseš vnitř za oponu truhlu svědectví; a oddělovati vám bude ta opona svatyni od svatyně svatých.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 34, 'Položíš také slitovnici na truhlu svědectví v svatyni svatých.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 35, 'A postavíš stůl vně před oponou, svícen pak naproti stolu v straně příbytku polední, a stůl dáš na stranu půlnoční.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 36, 'A uděláš zastření dveří stánku z postavce modrého a z šarlatu, a z červce dvakrát barveného, a z bílého hedbáví přesukovaného, dílem vyšívaným.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 37, 'K zastření pak tomu uděláš pět sloupů z dříví setim, kteréž obložíš zlatem, a hákové jejich zlatí; a sleješ k nim pět podstavků měděných.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 1, 'Uděláš také oltář z dříví setim pěti loket zdýlí a pěti loket zšíří; čtverhranatý bude oltář, a tří loket zvýší bude.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 2, 'A zděláš mu rohy na čtyřech úhlech jeho; z něho budou rohové jeho; a obložíš jej mědí.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 3, 'Naděláš také k němu hrnců, do kterýchž by popel bral, a lopat a kotlíku, a vidliček a nádob k uhlí. Všecka nádobí jeho z mědi uděláš.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 4, 'Uděláš mu i rošt mřežovaný měděný, a u té mříže čtyři kruhy měděné na čtyřech rozích jejích.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 5, 'A dáš ji pod okolek oltáře do vnitřku; a bude ta mříže až do polu oltáře.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 6, 'Uděláš k tomu oltáři i sochory z dříví setim, a mědí je okuješ.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 7, 'A ti sochorové provlečeni budou skrze ty kruhy; a budou sochorové ti na obou stranách oltáře, když nošen bude.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 8, 'Uděláš jej z desk, aby byl vnitř prázdný; jakž ukázáno tobě na hoře, tak udělají.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 9, 'Uděláš také síň příbytku k straně polední; koltry síně té očkovaté budou z bílého hedbáví soukaného; sto loket zdélí ať má kraj jeden.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 10, 'Sloupů pak bude k nim dvadcet, a podstavků k nim měděných dvadcet; háky na sloupích a přepásaní jich stříbrné.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 11, 'A tak i strana půlnoční na dýl ať má koltry očkovaté sto loket zdýlí, a sloupů svých dvadceti, a podstavků k nim měděných dvadceti; háky na sloupích a přepásaní jich stříbrné.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 12, 'Na šíř pak té síně k straně západní budou koltry očkovaté padesáti loktů zdýlí, a sloupů k nim deset, a podstavků jejich deset.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 13, 'A širokost síně v straně přední na východ bude padesáti loktů.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 14, 'Patnácti loktů budou koltry očkovaté k straně jedné, sloupové k nim tři, a podstavkové jejich tři.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 15, 'A k straně druhé patnácti loktů zdýlí budou koltry očkovaté, sloupové jejich tři, a podstavkové jejich tři.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 16, 'K bráně pak té síně uděláno bude zastření dvadcíti loktů z postavce modrého a šarlatu, a z červce dvakrát barveného, a bílého hedbáví soukaného, dílem krumpéřským, sloupové k němu čtyři, a podstavkové jejich čtyři.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 17, 'Všickni sloupové síně vůkol přepásaní budou stříbrem; hákové pak jejich budou stříbrní, a podstavkové jejich mědění.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 18, 'Dlouhost síně bude sto loket, a širokost padesáte, všudy jednostejná, vysokost pak pěti loktů, z bílého hedbáví soukaného, a podstavkové budou mědění.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 19, 'Všecka nádobí příbytku, ke vší službě jeho, a všickni kolíkové jeho, i všickni kolíkové síně z mědi budou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 20, 'Ty také přikaž synům Izraelským, ať nanesou oleje olivového čistého, vytlačeného k svícení, aby lampy vždycky rozsvěcovány byly.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 21, 'V stánku úmluvy před oponou, kteráž zastírati bude svědectví, spravovati je budou Aron a synové jeho od večera až do jitra před Hospodinem. Toť bude řád věčný, kterýž zachovávati budou potomci jejich mezi syny Izraelskými.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 1, 'Ty pak přijmi k sobě Arona bratra svého s syny jeho z prostředku synů Izraelských, aby úřad kněžský konali přede mnou: Aron, Nádab, Abiu, Eleazar a Itamar, synové Aronovi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 2, 'A uděláš roucha svatá Aronovi bratru svému k slávě a k ozdobě.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 3, 'Ty také mluviti budeš se všechněmi umělými řemeslníky, kteréž jsem naplnil duchem moudrosti, aby dělali roucha Aronovi ku posvěcení jeho, v nichž by úřad kněžský konal přede mnou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 4, 'Tato pak jsou roucha, kteráž udělají, náprsník, náramenník, plášť a sukni s oky, čepici a pás. Takové šaty svaté udělají Aronovi bratru tvému a synům jeho, aby úřad kněžský konali přede mnou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 5, 'A vezmou řemeslníci zlato a modrý postavec, a šarlat a červec dvakrát barvený a kment.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 6, 'Udělají pak náramenník z zlata, z postavce modrého a šarlatu, z červce dvakrát barveného a hedbáví bílého, přesukovaného dílem řemeslným.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 7, 'Dva vrchní kraje spojená míti bude na dvou koncích svých, a tak se spolu držeti bude.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 8, 'Přepásaní pak přes ten náramenník, kteréž na něm bude, podobné bude dílu jeho; z týchž věcí bude, totiž z zlata, z postavce modrého a z šarlatu, a z červce dvakrát barveného, a z hedbáví bílého přesukovaného.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 9, 'Vezmeš také dva kameny onychinové, a vyryješ na nich jména synů Izraelských.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 10, 'Šest jmen jejich na kameni jednom, a jmen šest ostatních na kameni druhém, podlé pořádku narození jejich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 11, 'Dílem řemeslníka, kterýž řeže na kameni, a kterýž vyrývá pečeti, vyryješ na těch dvou kameních jména synů Izraelských; do zlata je vsadíš.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 12, 'A položíš dva kameny ty na vrchních krajích náramenníku, kameny pro pamět na syny Izraelské; a nositi bude Aron jména jejich před Hospodinem na obou ramenách svých na památku.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 13, 'Uděláš i haklíky zlaté.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 14, 'A dva řetízky z zlata čistého jednostejně uděláš dílem točeným, a zavěsíš řetízky ty stočené na ty haklíky.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 15, 'Uděláš také náprsník soudu dílem řemeslným, takovým dílem, jako náramenník uděláš jej z zlata, z postavce modrého, z šarlatu, z červce dvakrát barveného, a z bílého hedbáví přesukovaného.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 16, 'Čtverhraný bude a dvojnásobní; pídi dlouhost, a pídi širokost jeho bude.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 17, 'A vysadíš jej všudy kamením drahým. Čtyřmi řady ať jest kamení, pořádkem tímto: Sardius, topazius a smaragdus v prvním řadu;');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 18, 'V druhém pak zpořádaní karbunkulus, zafir a jaspis;');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 19, 'A v řadu třetím linkurius, achates a ametyst;');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 20, 'V čtvrtém řadu chryzolit, onychin a beryl. Vsazeni budou do zlata v svém pořádku.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 21, 'Těch pak kamenů s jmény synů Izraelských bude dvanácte, podlé jmen jejich, dílem řežících pečeti; jeden každý podlé jména svého, pro dvanáctero pokolení budou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 22, 'Uděláš i k náprsníku řetízky jednostejné dílem točeným z zlata čistého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 23, 'Uděláš také k náprsníku dva kroužky zlaté, a dáš je na dva kraje náprsníka.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 24, 'A prostrčíš dva řetízky zlaté skrze dva kroužky po krajích náprsníka.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 25, 'A druhé konce těch dvou řetízků připneš k haklíkům, a dáš na vrchní kraje náramenníka po předu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 26, 'Uděláš i dva kroužky zlaté, kteréž dáš na dva kraje náprsníka, na tu obrubu jeho, kteráž jest po té straně k náramenníku do vnitřku.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 27, 'Uděláš ještě dva jiné kroužky zlaté, kteréž dáš na dvě strany náramenníka zespod po předu naproti spojení jeho, svrchu nad přepásaním náramenníka.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 28, 'Tak svíží náprsník ten, kroužky jeho s kroužky náramenníka, tkanicí z postavce modrého, aby byl nad přepásaním náramenníka, a neodevstával náprsník od náramenníka.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 29, 'I bude nositi Aron jména synů Izraelských na náprsníku soudu na srdci svém, když vcházeti bude do svatyně, na památku před Hospodinem ustavičně.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 30, 'Položíš pak do náprsníku soudu urim a thumim, aby bylo na srdci Aronově, když vcházeti bude před Hospodina; a nositi bude Aron soud synů Izraelských na srdci svém před Hospodinem vždycky.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 31, 'Uděláš také plášť pod náramenník, všecken z postavce modrého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 32, 'A bude na vrchu v prostřed něho díra; okolek její všudy vůkol dílem tkaným, jako obojek u pancíře bude, aby se neroztrhl.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 33, 'Uděláš i na podolku jeho jablka zrnatá z hedbáví modrého, z šarlatu a z červce dvakrát barveného, na podolku jeho vůkol, a zvonečky zlaté mezi nimi vůkol.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 34, 'Zvonček zlatý a jablko zrnaté, opět za tím zvonček zlatý a jablko zrnaté na podolku pláště vůkol.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 35, 'A bude to míti na sobě Aron při službách, aby slyšán byl zvuk jeho, když vcházeti bude do svatyně před Hospodina, i když vycházeti bude, aby neumřel.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 36, 'Uděláš také plech z zlata čistého, a vyryješ na něm dílem vyrývajících pečeti: Svatost Hospodinu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 37, 'Kterýž dáš na tkanici z modrého postavce, a bude na čepici; napřed na čepici bude.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 38, 'I bude nad čelem Aronovým, aby nesl Aron nepravosti posvěcených věcí, kterýchž by posvětili synové Izraelští při všech dařích posvěcených věcí svých; a bude nad čelem jeho vždycky, aby příjemné je činil před Hospodinem.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 39, 'Uděláš také sukni z hedbáví bílého vázanou s oky; uděláš i čepici z hedbáví bílého; pás také uděláš dílem krumpéřským.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 40, 'Synům také Aronovým zděláš sukně; pasy také jim uděláš a klobouky k slávě a k ozdobě.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 41, 'A oblečeš v ně Arona bratra svého a syny jeho s ním, a pomažeš jich, a naplníš ruce jejich, a posvětíš mi jich, aby úřad kněžský konali přede mnou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 42, 'Nadělej jim i košilek lněných k zakrytí nahoty těla; od bedr až do stehen budou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 43, 'A ať je na sobě mají Aron i synové, když vcházeti budou do stánku úmluvy, aneb když přistupovati budou k oltáři, aby sloužili v svatyni; a neponesou nepravosti, aniž zemrou. Řád tento bude věčný jemu i potomkům jeho po něm.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 1, 'Toto také učiníš jim ku posvěcení jich, aby úřad kněžský konali přede mnou: Vezmi volka jednoho ještě mladého a skopce dva bez vady.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 2, 'Chleby též přesné a koláče přesné s olejem smíšené, a oplatky přesné polité olejem; z běli pšeničné naděláš toho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 3, 'A vklada to do koše jednoho, obětovati to budeš v koši, spolu s tím volkem a dvěma skopci.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 4, 'Potom Aronovi a synům jeho přistoupiti kážeš ke dveřím stánku úmluvy, a umyješ je vodou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 5, 'A vezma roucha, oblečeš Arona v sukni, a v plášť náležící pod náramenník, a v náramenník, a v náprsník, a přepášeš ho pasem náramenníka.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 6, 'Vstavíš i čepici na hlavu jeho, a korunu svatosti vstavíš na čepici.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 7, 'Naposledy vezmeš olej pomazání, a vyleje na hlavu jeho, pomažeš ho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 8, 'Potom synům jeho přistoupiti kážeš, a zobláčíš je v sukně.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 9, 'A zopasuješ je pasy, Arona i syny jeho, a vstavíš jim čepičky na hlavu. I budouť míti kněžství řádem věčným; a posvětíš ruky Aronovy a ruky synů jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 10, 'Přivedeš také volka před stánek úmluvy, i vloží Aron a synové jeho ruce své na hlavu volka.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 11, 'A zabiješ volka před Hospodinem u dveří stánku úmluvy.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 12, 'A nabera krve z volka, pomažeš na rozích oltáře prstem svým, a všecku krev vyleješ k spodku oltáře.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 13, 'Vezmeš pak všecken tuk přikrývající droby a branici s jater, a dvě ledviny s tukem, kterýž jest na nich, a zapálíš to na oltáři.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 14, 'Maso pak z toho volka, a kůži s lejny jeho spálíš ohněm vně za stany; nebo obět za hříchy jest.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 15, 'Skopce také jednoho vezmeš, a vloží Aron a synové jeho ruce své na hlavu toho skopce.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 16, 'A zabiješ toho skopce, a nabera krve jeho, pokropíš oltáře na vrchu vůkol.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 17, 'Skopce pak rozsekáš na kusy, a vymyje droby jeho i nohy, vkladeš je na ty kusy z něho a na hlavu jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 18, 'A potom všeho skopce zapálíš na oltáři; nebo zápal ten jest Hospodinu vůně příjemná, obět ohnivá jest Hospodinu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 19, 'Vezmeš také skopce druhého; i vloží Aron a synové jeho ruce své na hlavu téhož skopce.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 20, 'A zabiješ skopce toho, a vezma krev jeho, pomažeš jí konce ucha Aronova, a konce pravého ucha synů jeho, i palce na pravé ruce jejich, a palce na pravé noze jejich; a vykropíš tu krev na oltář vůkol.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 21, 'A vezma krve, kteráž bude na oltáři, a oleje pomazání, pokropíš Arona a roucha jeho i synů jeho a roucha jejich s ním; a budeť posvěcen on i roucho jeho, i synové jeho, a roucho synů jeho s ním.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 22, 'Potom vezmeš z skopce tuk a ocas, a tuk přikrývající droby, a branici s jater, a dvě ledviny s tukem, kterýž jest na nich, a plece pravé, (nebo skopec naplnění jest,)');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 23, 'A jeden pecník chleba, a jeden koláč chleba s olejem, a oplatek jeden z koše chlebů přesných, kterýž jest před Hospodinem.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 24, 'A dáš to vše v ruce Aronovy a v ruce synů jeho, a obraceti to budeš sem i tam, aby byla obět obracení před Hospodinem.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 25, 'Potom vezma to z rukou jejich, zapálíš na oltáři v zápal, k vůni příjemné před Hospodinem. Toť jest obět ohnivá Hospodinu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 26, 'Vezmeš také hrudí z skopce posvěcení, kterýž bude Aronův, a obraceti je budeš sem i tam, aby byla obět obracení před Hospodinem; a budeť na tvůj díl.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 27, 'Posvětíš tedy hrudí obracení, a plece pozdvižení, kteréž obracíno a kteréž pozdvihováno bylo z skopce posvěcení, z toho, kterýž bude Aronův, a z toho, kterýž bude synů jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 28, 'A bude to Aronovi a synům jeho právem věčným od synů Izraelských, když obět pozdvižení bude. Nebo pozdvižení bude od synů Izraelských, z obětí jejich pokojných; pozdvižení jejich náleží Hospodinu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 29, 'Roucha pak svatá, kteráž jsou Aronova, zůstanou synům jeho po něm, aby pomazováni byli v nich, a aby posvěcovány byly v nich ruce jejich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 30, 'Sedm dní bude v nich choditi kněz, kterýž bude na jeho místě z synů jeho, kterýž vcházeti bude do stánku úmluvy, aby sloužil v svatyni.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 31, 'Skopce pak posvěcení vezma, uvaříš maso jeho na místě svatém.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 32, 'A budeť jísti Aron s syny svými maso toho skopce a chléb, kterýž jest v koši u dveří stánku úmluvy.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 33, 'Jísti budou to ti, za něž očištění se stalo ku posvěcení rukou jejich, aby posvěceni byli. Cizí pak nebude jísti, nebo svatá věc jest.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 34, 'Zůstalo-li by co masa posvěcení a chleba až do jitra, spálíš ostatky ohněm; nebude jedeno, nebo svatá věc jest.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 35, 'Tak tedy uděláš s Aronem a syny jeho vedlé všeho, což jsem přikázal tobě; za sedm dní posvěcovati budeš rukou jejich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 36, 'A volka za hřích obětovati budeš na každý den na očištění, a krví za hřích pokropíš oltáře, čině očištění na něm, a pomažeš ho ku posvěcení jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 37, 'Za sedm dní očišťování konati budeš na oltáři, a posvětíš ho, a ten oltář bude nejsvětější. Cokoli dotkne se oltáře, posvěceno bude.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 38, 'A toto jest, což obětovati budeš na oltáři, beránky roční dva, na každý den ustavičně.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 39, 'Jednoho beránka obětovati budeš ráno, a beránka druhého obětovati budeš k večerou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 40, 'A desátý díl efi běli smíšené s olejem vytlačeným, jehož by bylo s čtvrtý díl hin, a k oběti mokré čtvrtý díl hin vína na jednoho beránka.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 41, 'Tolikéž beránka druhého obětovati budeš k večerou. Jako při oběti suché ranní, a jako při mokré oběti její, tak při této učiníš, aby byla vůně příjemná, obět ohnivá Hospodinu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 42, 'Zápalná obět tato ustavičná ať jest po všecky věky vaše u dveří stánku úmluvy před Hospodinem, kdež přicházeti budu k vám, abych tam s tebou mluvil.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 43, 'A tam přicházeti budu k synům Izraelským, a posvěceno bude místo slávou mou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 44, 'Nebo posvětím stánku úmluvy i oltáře; Arona také a synů jeho posvětím, aby mi úřad kněžský konali.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 45, 'A bydliti budu u prostřed synů Izraelských, a budu jim za Boha.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 46, 'A zvědíť, že já jsem Hospodin Bůh jejich, kterýž jsem je vyvedl z země Egyptské, abych přebýval u prostřed nich, já Hospodin Bůh jejich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 1, 'Uděláš i oltář, na němž by se kadilo; z dříví setim uděláš jej.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 2, 'Lokte zdélí, a lokte zšíří, čtverhraný bude, a dvou loket zvýší; z něho budou rohy jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 3, 'Obložíš pak jej zlatem čistým, svrchek jeho i po stranách vůkol i rohy jeho; a uděláš mu korunu zlatou vůkol.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 4, 'Po dvou také kruzích zlatých uděláš u něho, pod korunou ve dvou úhlech jeho, po obou stranách jeho; a skrze ně provlečeš sochory, aby nošen byl na nich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 5, 'Ty pak sochory uděláš z dříví setim, a obložíš je zlatem.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 6, 'A postavíš jej před oponou, za kterouž jest truhla svědectví, před slitovnicí, kteráž jest nad svědectvím, kdež přicházeti budu k tobě.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 7, 'I kaditi bude na něm Aron kadidlem z vonných věcí; každého jitra, když spraví světla, kaditi bude.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 8, 'Tolikéž když rozsvítí Aron lampy k večerou, kaditi bude kaděním vonných věcí ustavičně před Hospodinem po rodech vašich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 9, 'Nevložíte na něj kadidla cizího, ani zápalu, ani oběti suché, ani oběti mokré obětovati budete na něm.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 10, 'Toliko očištění vykoná nad rohy jeho Aron jednou v roce, krví oběti za hřích v den očišťování; jednou v roce očištění vykoná na něm po rodech vašich; svatosvaté jest Hospodinu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 11, 'Mluvil pak Hospodin k Mojžíšovi, řka:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 12, 'Když vyzdvihneš hlavní summu synů Izraelských náležejících ku počtu, dá jeden každý výplatu duše své Hospodinu, když je počítati budeš, aby nebyla na nich rána, když sečteni budou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 13, 'Toto pak dají: Každý z těch, kteří jdou v počet, půl lotu dá, podlé lotu svatyně. (Dvadceti peněz platí ten lot.) Půl lotu obět pozdvižení bude Hospodinu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 14, 'Kdožkoli jde v počet od dvadcíti let a výše, tu obět pozdvižení ať dá Hospodinu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 15, 'Bohatý nedá více, a chudý nedá méně, než půl lotu, když dávati budou obět pozdvižení Hospodinu k očištění duší vašich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 16, 'A vezma stříbro očištění od synů Izraelských, dáš je na potřeby k službě stánku úmluvy; a bude to synům Izraelským na památku před Hospodinem k očištění duší vašich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 17, 'Mluvil také Hospodin k Mojžíšovi, řka:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 18, 'Uděláš i umyvadlo měděné k umývání a podstavek jeho měděný, a postavíš je mezi stánkem úmluvy a oltářem, a naleješ do něho vody.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 19, 'Umývati budou z něho Aron i synové jeho ruce své i nohy své.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 20, 'Když vcházeti budou do stánku úmluvy, umývati se budou vodou, aby nezemřeli, aneb když by měli přistupovati k oltáři, aby sloužili, a zapalovali obět ohnivou Hospodinu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 21, 'I budou umývati ruce i nohy své, aby nezemřeli. A bude jim ustanovení toto věčné, Aronovi i semeni jeho po rodech jejich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 22, 'Mluvil také Hospodin k Mojžíšovi, řka:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 23, 'Ty pak vezmi sobě vonných věcí předních: Mirry nejčistší pět set lotů, a skořice vonné polovici toho, totiž dvě stě a padesát, a prustvorce vonného dvě stě a padesát;');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 24, 'Kasie pak pět set lotů na váhu svatyně, oleje olivového míru hin.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 25, 'A uděláš z toho olej pomazání svatého, mast nejvýbornější dílem apatykářským. Olej pomazání svatého bude.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 26, 'Pomažeš jím stánku úmluvy i truhly svědectví,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 27, 'A stolu i všech nádob k němu, svícnu i všech nádob jeho, i oltáře, na němž se kadí;');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 28, 'Oltáře také, na němž se pálí oběti, a všech nádob jeho, i umyvadla s podstavkem jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 29, 'Tak posvětíš jich, aby byly nejsvětější. Cožkoli dotkne se jich, posvěceno bude.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 30, 'Arona také a synů jeho pomažeš, a posvětíš jich, aby úřad kněžský konali přede mnou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 31, 'K synům pak Izraelským mluviti budeš, řka: Tento olej pomazání svatého bude mi v národech vašich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 32, 'Tělo člověka nebude mazáno jím, a podlé složení jeho neuděláte podobného. Svatýť jest, svatý vám bude.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 33, 'Kdo by koli udělal mast podobnou, a neb mazal by jí cizího, vyhlazen bude z lidu svého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 34, 'I řekl Hospodin Mojžíšovi: Vezmi sobě vonných věcí, balsamu, onychi, galbanu vonného, a kadidla čistého; jednostejná váha toho bude.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 35, 'A uděláš z toho kadidlo, složení dílem apatykářským smíšené, čisté a svaté.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 36, 'A ztluka to drobně, klásti budeš z něho před svědectvím v stánku úmluvy, kdež přicházeti budu k tobě. Nejsvětější to vám bude.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 37, 'Neuděláte sobě kadidla podlé složení tohoto, kteréž připravíš; za svatou věc tobě bude pro Hospodina.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 38, 'Kdo by koli dělal co podobného k vůni sobě, vyhlazen bude z lidu svého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 1, 'I mluvil Hospodin k Mojžíšovi, řka:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 2, 'Hle, povolal jsem ze jména Bezeleele, syna Uri, syna Hur, z pokolení Judova.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 3, 'A naplnil jsem ho duchem Božím, moudrostí a rozumností, i uměním všelijakého řemesla,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 4, 'Aby vtipně smysliti uměl, což by koli řemeslně uděláno býti mohlo z zlata a z stříbra i z mědi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 5, 'I v řezání kamení drahého k vsazování, i v umělém vysazování na dřevě aby dělal všelijaké dílo.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 6, 'A aj, já přidal jsem jemu Aholiaba, syna Achisamechova, z pokolení Dan. A v srdci každého vtipného složil jsem moudrost, aby spravili vše, což jsem přikázal tobě:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 7, 'Stánek úmluvy a truhlu svědectví, a slitovnici, kteráž má býti na ní, i všelijaké nádobí stánku;');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 8, 'Stůl také a nádoby k němu, i svícen čistý se všemi nádobami jeho, a oltář pro kadění;');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 9, 'Též oltář k zápalům se všemi nádobami jeho, a umyvadlo s podstavkem jeho;');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 10, 'I roucha k službě, i roucha svatá Aronovi knězi, i roucha synů jeho, aby mi úřad kněžský konali;');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 11, 'I olej pomazání a kadidlo vonné do svatyně. Všecko tak, jakž jsem přikázal tobě, udělají.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 12, 'Mluvil také Hospodin k Mojžíšovi, řka:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 13, 'Ty pak mluv k synům Izraelským a rci: A však sobot mých ostříhati budete. Nebo to znamením jest mezi mnou a vámi po rodech vašich, aby známo bylo, že já jsem Hospodin, kterýž vás posvěcuji.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 14, 'Protož ostříhati budete soboty, nebo svatá jest vám. Kdož by ji poškvrnil, smrtí umře; a kdo by koli dělal v ní dílo, vyhlazena bude ta duše z prostředku lidu svého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 15, 'Šest dní děláno bude dílo, ale v den sedmý sobota odpočinutí jest, svatost Hospodinu. Každý, kdož by dělal dílo v den sobotní, smrtí umře.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 16, 'Protož ostříhati budou synové Izraelští soboty, tak aby světili sobotu po rodech svých smlouvou věčnou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 17, 'Mezi mnou a syny Izraelskými za znamení jest na věčnost; nebo šest dní činil Hospodin nebe i zemi, v den pak sedmý přestal a odpočinul.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 18, 'I dal Pán Mojžíšovi po dokonání těchto řečí s ním na hoře Sinai dvě dsky svědectví, dsky kamenné, psané prstem Božím.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 1, 'Vida pak lid, že by prodléval Mojžíš sstoupiti s hůry, sebrali se proti Aronovi a řekli jemu: Vstaň, udělej nám bohy, kteříž by šli před námi; nebo Mojžíšovi, muži tomu, kterýž vyvedl nás z země Egyptské, nevíme, co se přihodilo.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 2, 'I řekl jim Aron: Odejměte náušnice zlaté, kteréž jsou na uších žen vašich, synů vašich i dcer vašich, a přineste ke mně.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 3, 'Tedy strhl všecken lid náušnice zlaté, kteréž byly na uších jejich, a přinesli k Aronovi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 4, 'Kteréžto vzav z rukou jejich, dal je do formy, a udělal z nich tele slité. I řekli: Tito jsou bohové tvoji, Izraeli, kteříž tě vyvedli z země Egyptské.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 5, 'Což vida Aron, vzdělal oltář před ním. I volal Aron, a řekl: Slavnost Hospodinova zítra bude.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 6, 'A nazejtří vstavše velmi ráno, obětovali zápaly, a přivedli oběti pokojné. I sedl lid, aby jedl a pil, potom vstali, aby hrali.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 7, 'Mluvil pak Hospodin k Mojžíšovi: Jdi, sstup, nebo porušil se lid tvůj, kterýž jsi vyvedl z země Egyptské.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 8, 'Sešli brzo s cesty, kterouž jsem přikázal jim. Udělali sobě tele slité, a klaněli se mu, a obětovali jemu, řkouce: Tito jsou bohové tvoji, Izraeli, kteříž tě vyvedli z země Egyptské.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 9, 'Řekl také Hospodin Mojžíšovi: Viděl jsem lid tento, a aj, lid jest tvrdé šíje.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 10, 'Protož nyní nech mne, abych v hněvě prchlivosti své vyhladil je, tebe pak učiním v národ veliký.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 11, 'I modlil se Mojžíš Hospodinu Bohu svému, a řekl: Pročež, ó Hospodine, rozněcuje se prchlivost tvá na lid tvůj, kterýž jsi vyvedl z země Egyptské v síle veliké a v ruce mocné?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 12, 'A proč mají mluviti Egyptští, řkouce: Lstivě je vyvedl, aby zmordoval je na horách, a aby vyhladil je se svrchku země? Odvrať se od hněvu prchlivosti své, a lituj zlého, kteréžs uložil uvésti na lid svůj.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 13, 'Rozpomeň se na Abrahama, Izáka a Izraele, služebníky své, jimž jsi zapřisáhl skrze sebe samého a mluvil jsi jim: Rozmnožím símě vaše jako hvězdy nebeské, a všecku zemi tuto, o kteréž jsem mluvil, dám semeni vašemu, a dědičně obdržíte ji na věky.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 14, 'I litoval Hospodin zlého, kteréž řekl, že učiní lidu svému.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 15, 'A obrátiv se Mojžíš, sstoupil s hůry, dvě dsky svědectví maje v rukou svých, dsky po obou stranách psané; s jedné i s druhé strany byly popsané.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 16, 'A dsky ty dílo Boží byly; písmo také písmo Boží bylo vyryté na dskách.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 17, 'Uslyšev pak Jozue hlas lidu křičícího, řekl Mojžíšovi: Hřmot boje v táboru jest.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 18, 'Kterýžto odpověděl: Není to křik vítězících, ani křik poražených, hlas zpívajících já slyším.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 19, 'I stalo se, když se přiblížil k stanům, že uzřel tele a tance. A rozhněvav se Mojžíš velmi, povrhl z rukou svých dsky, a rozrazil je pod Horou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 20, 'Vzal také tele, kteréž byli udělali, a spálil je v ohni, a setřel je až na prach, a vsypav na vodu, dal píti synům Izraelským.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 21, 'A řekl Mojžíš Aronovi: Coť učinil lid tento, že jsi uvedl na něj hřích veliký?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 22, 'Odpověděl Aron: Nehněvej se, pane můj. Ty víš, že lid tento k zlému nakloněn jest.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 23, 'Nebo řekli mi: Udělej nám bohy, kteříž by šli před námi; nebo Mojžíšovi, muži tomu, kterýž vyvedl nás z země Egyptské, nevíme, co se stalo.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 24, 'Jimž jsem odpověděl: Kdo má zlato, strhněte je s sebe. I dali mi, a uvrhl jsem je do ohně, a udělalo se to tele.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 25, 'A vida Mojžíš lid obnažený, že obnažil jej Aron ku potupě před nepřátely, kteříž povstati měli proti nim,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 26, 'Stoje v bráně táboru, řekl: Kdo jest Hospodinův, přistup ke mně. I shromáždili se k němu všickni synové Léví.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 27, 'Jimž řekl: Tak praví Hospodin Bůh Izraelský: Připaš jeden každý meč svůj k boku svému; přejděte sem i tam od brány táboru k bráně, a zabí jeden každý bratra svého, a každý přítele svého i bližního svého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 28, 'I učinili synové Léví podlé řeči Mojžíšovy, a padlo jich v ten den z lidu na tři tisíce mužů.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 29, 'Nebo řekl byl Mojžíš: Posvěťtež dnes rukou svých Hospodinu, jeden každý na synu svém a na bratru svém, aby vám dal dnes požehnání.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 30, 'A když bylo nazejtří, řekl Mojžíš lidu: Vy jste zhřešili hříchem velikým. Protož nyní vstoupím k Hospodinu, zda bych ho ukrotil pro hřích váš.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 31, 'Tedy navrátiv se Mojžíš k Hospodinu, řekl: Prosím, zhřešilť jest lid ten hříchem velikým; nebo udělali sobě bohy zlaté.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 32, 'Nyní pak neb odpusť hřích jejich, a pakli nic, vymaž mne, prosím, z knihy své, kteroužs psal.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 33, 'I řekl Hospodin Mojžíšovi: Kdo zhřešil proti mně, toho vymaži z knihy své.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 34, 'Protož nyní jdi, veď lid tento, kamž jsem rozkázal tobě. Aj, anděl můj půjde před tebou; v den pak navštívení mého navštívím i na nich hřích jejich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 35, 'I bil Hospodin lid, proto že učinili tele, kteréž byl udělal Aron.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 1, 'I mluvil Hospodin k Mojžíšovi: Jdi, vstup odsud, ty i lid, kterýž jsi vyvedl z země Egyptské do země, kterouž jsem přisáhl Abrahamovi, Izákovi a Jákobovi, řka: Semeni tvému dám ji,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 2, '(A pošli před tebou anděla, a vyženu Kananea, Amorea, Hetea, Ferezea, Hevea a Jebuzea,)');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 3, 'Do země oplývající mlékem a strdí. Neboť sám nevstoupím s tebou, proto že lid tvrdé šíje jsi, abych nezahubil tebe na cestě.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 4, 'A uslyšav lid řeč tuto přezlou, zámutek nesli, aniž vzal kdo okrasy své na sebe.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 5, 'Nebo byl řekl Hospodin Mojžíšovi: Mluv synům Izraelským: Vy jste lid tvrdé šíje; jakž jen jedinou vstoupím mezi vás, zahladím vás. Protož již, slož okrasu svou s sebe, a zvím, co učiniti mám s tebou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 6, 'I svlékli s sebe synové Izraelští okrasy své u hory Oréb.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 7, 'Mojžíš pak vzav stánek, rozbil jej sobě vně za stany, vzdáliv se od táboru, a nazval jej stánkem úmluvy. Tedy kdokoli hledal Hospodina, ven choditi musil k stánku úmluvy, kterýž byl vně za stany.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 8, 'K tomu také, když vycházel Mojžíš k stánku, povstával všecken lid a stál každý u dveří stanu svého, a hleděli za Mojžíšem, dokudž nevšel do stánku.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 9, 'Bývalo pak toto, že když vcházíval Mojžíš do stánku, sstupoval sloup oblakový, a stával u dveří stánku, a mluvil s Mojžíšem.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 10, 'A všecken lid vida sloup oblakový, an stojí u dveří stánku, povstávali všickni, a klaněli se každý u dveří stanu svého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 11, 'A mluvíval Hospodin k Mojžíšovi tváří v tvář, tak jako mluví člověk s přítelem svým. Potom navracel se do táboru, ale služebník jeho Jozue, syn Nun, mládenec, neodcházel z stánku.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 12, 'I řekl Mojžíš Hospodinu: Pohleď, ty velíš mi, abych vedl lid tento, a neoznámils mi, koho pošleš se mnou, ještos pravil: Znám tě ze jména, k tomu také nalezl jsi milost přede mnou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 13, 'Již tedy, jestliže jsem jen nalezl milost před tebou, oznam mi, prosím, cestu svou, abych tě poznal, a abych nalezl milost před tebou; a pohleď, že národ tento jest lid tvůj.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 14, 'I odpověděl: Tvář má předcházeti vás bude, a dámť odpočinutí.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 15, 'I řekl: Nemá-liť předcházeti nás tvář tvá, nevyvozuj nás odsud.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 16, 'Nebo po čem poznáno bude zde, že jsem nalezl milost před tebou, já i lid tvůj? Zdali ne po tom, když půjdeš s námi, a když odděleni budeme, já a lid tvůj, ode všeho lidu, kterýž jest na tváři země?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 17, 'I řekl Hospodin Mojžíšovi: I tu také věc, kterouž jsi pravil, učiním; nebo jsi nalezl milost přede mnou, a znám tě ze jména.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 18, 'Řekl opět: Okažiž mi, prosím, slávu svou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 19, 'Kterýž odpověděl: Já způsobím to, aby šlo mimo tebe před tváří tvou všecko dobré mé, a zavolám ze jména: Hospodin před tváří tvou. Smiluji se, nad kýmž se smiluji, a slituji se, nad kýmž se slituji.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 20, 'Řekl také: Nebudeš moci viděti tváři mé; neboť neuzří mne člověk, aby živ zůstal.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 21, 'I to řekl Hospodin: Aj, místo u mne, a staneš na skále.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 22, 'A když tudy půjde sláva má, postavím tě v rozsedlině skály, a přikryji tě rukou svou, dokudž nepřejdu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 23, 'Potom odejmu ruku svou, i uzříš hřbet můj, ale tvář má nebude spatřína.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 1, 'I řekl Hospodin k Mojžíšovi: Vyteš sobě dvě dsky kamenné podobné prvním, a napíši na dskách těch slova, kteráž byla na dskách prvních, kteréž jsi rozrazil.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 2, 'Budiž tedy hotov ráno, a vstoupíš v jitře na horu Sinai, a staneš přede mnou na vrchu hory té.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 3, 'Žádný ať nevstupuje s tebou, aniž také kdo vidín bude na vší hoře; ani ovce neb volové pásti se budou naproti hoře této.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 4, 'Tedy Mojžíš vytesal dvě dsky kamenné podobné prvním, a vstav ráno, vstoupil na horu Sinai, jakž mu přikázal Hospodin, a vzal v ruku svou dvě dsky kamenné.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 5, 'I sstoupil Hospodin v oblaku, a stál s ním tam, a zavolal ze jména: HOSPODIN.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 6, 'Nebo pomíjeje Hospodin tvář jeho, volal: Hospodin, Hospodin, Bůh silný, lítostivý a milostivý, dlouhočekající a hojný v milosrdenství a pravdě,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 7, 'Milosrdenství čině tisícům, odpouštěje nepravost a přestoupení i hřích, a kterýž nikoli neospravedlňuje vinného, navštěvuje nepravost otců na synech, a na synech synů do třetího i čtvrtého pokolení.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 8, 'Mojžíš pak rychle sklonil hlavu k zemi, a poklonu učinil.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 9, 'A řekl: Prosím, našel-li jsem milost v očích tvých, Pane, nechť jde, prosím, Pán u prostřed nás, nebo lid jest tvrdé šíje, a milostiv buď nepravosti naší a hříchu našemu, a měj nás za dědictví.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 10, 'Kterýžto řekl: Aj, já učiním smlouvu přede vším lidem tvým. Učiním divné věci, kteréž nejsou učiněny na vší zemi a ve všech národech, a viděti bude všecken lid, (mezi nimiž jsi,) skutky Hospodinovy; nebo hrozné bude to, což já učiním s tebou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 11, 'Zachovej to, což já dnes tobě přikazuji. Aj, já vyženu před tváří tvou Amorea a Kananea, Hetea a Ferezea, Hevea a Jebuzea.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 12, 'Varuj se pak, abys nečinil smlouvy s obyvateli země té, do kteréž vejdeš, ať by nebyli osídlem u prostřed tebe.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 13, 'Ale zboříte oltáře jejich, a modly jejich polámete, a jejich háje posekáte.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 14, 'Nebo nebudeš se klaněti Bohu jinému, proto že Hospodin jest, jméno má horlivý, Bůh silný, horlivý jest.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 15, 'Nevcházej v smlouvu s obyvateli země té, aby když by smilnili, jdouce po bozích svých, a obětovali bohům svým, nepovolali tě, a jedl bys z oběti jejich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 16, 'A abys nebral ze dcer jeho synům svým, i smilnily by dcery jejich, jdouce po bozích svých, a naučily by smilniti syny tvé, jdouce po bozích svých.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 17, 'Bohů slitých neuděláš sobě.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 18, 'Slavnost přesnic zachovávati budeš. Za sedm dní jísti budeš chleby nekvašené, jakž jsem přikázal tobě, v čas vyměřený měsíce Abib; nebo měsíce toho vyšel jsi z Egypta.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 19, 'Všecko což otvírá život, mé jest, i všeliký samec v dobytku tvém, prvorozený z volů a ovcí.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 20, 'Ale prvorozené osle vyplatíš dobytčetem; pakli bys nevyplatil, šíji zlomíš jemu. Každého prvorozeného z synů svých vyplatíš, aniž ukáží se přede mnou prázdní.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 21, 'Šest dní pracovati budeš, dne pak sedmého přestaneš; v čas orání i žně přestaneš.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 22, 'A učiníš sobě slavnost téhodnů, svátek prvotin žně pšeničné a slavnost klizení po vyjití každého roku.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 23, 'Třikrát v roce ukáže se každý z vás pohlaví mužského před oblíčejem Panovníka Hospodina, Boha Izraelského.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 24, 'Nebo vyvrhu národy od tváři tvé a rozšířím meze tvé, aniž kdo sáhne na zemi tvou, když vstoupíš, abys se ukázal před Hospodinem Bohem svým třikrát v roce.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 25, 'Nebudeš obětovati krve oběti mé, dokavadž u tebe kvas jest, aniž zůstane do jitra obět slavnosti Fáze.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 26, 'Prvotiny prvních úrod země své přinášeti budeš do domu Hospodina Boha svého. Nebudeš vařiti kozelce v mléce matky jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 27, 'I řekl Hospodin Mojžíšovi: Napiš sobě slova tato; nebo podlé slov těch učinil jsem smlouvu s tebou a s Izraelem.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 28, 'Byl pak tam s Hospodinem čtyřidceti dní a čtyřidceti nocí, chleba nejedl a vody nepil; a napsal na dskách slova té smlouvy, totiž deset slov.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 29, 'I stalo se, když sstupoval Mojžíš s hory Sinai, (a měl dvě dsky svědectví v rukou svých, když sstupoval s hory,) nevěděl, že by se stkvěla kůže tváři jeho, když mluvil s ním.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 30, 'A viděl Aron i všickni synové Izraelští Mojžíše, a aj, stkvěla se kůže tváři jeho, a nesměli přistoupiti k němu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 31, 'Ale Mojžíš zavolal jich, a navrátili se k němu Aron i všecka knížata shromáždění toho, a mluvil Mojžíš s nimi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 32, 'Potom přišli také k němu všickni synové Izraelští, jimžto přikázal všecko, což s ním mluvil Hospodin na hoře Sinai.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 33, 'Dokudž pak mluvil Mojžíš s nimi, měl zástěru na tváři své.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 34, 'Ale když vcházel Mojžíš před tvář Hospodina, aby mluvil s ním, odjímal zástěru, dokudž nevyšel. Vyšed pak, mluvil synům Izraelským, což mu bylo rozkázáno.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 35, 'Tedy viděli synové Izraelští tvář Mojžíšovu, že se stkvěla kůže tváři jeho. A kladl zase Mojžíš zástěru na tvář svou, dokudž nevcházel, aby mluvil s ním.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 1, 'Tedy svolal Mojžíš všecko shromáždění synů Izraelských, a řekl jim: Tato jsou slova, kteráž přikázal vám Hospodin, abyste je činili.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 2, 'Šest dní děláno bude dílo, ale v sedmý den mějte svátek, sobotu odpočinutí Hospodinova. Kdo by dělal v něm dílo, umře.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 3, 'Nezanítíte ohně nikdež v příbytcích svých v den sobotní.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 4, 'Mluvil také Mojžíš ke všemu shromáždění synů Izraelských takto: Toto jest slovo, kteréž přikázal Hospodin, řka:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 5, 'Sebeřte z sebe obět pozdvižení Hospodinu. Každý, kdož jest ochotný v srdci svém, přinese tu obět Hospodinu: Zlato, stříbro a měď,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 6, 'A postavec modrý, a šarlat, a červec dvakrát barvený, a bílé hedbáví, a kozí srsti;');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 7, 'Též kůže skopců na červeno barvené, a kůže jezevčí, a dříví setim,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 8, 'A olej k svícení a vonné věci na olej ku pomazání a pro kadění vonné,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 9, 'A kamení onychinové, a jiné kamení k vsazování do náramenníku a náprsníku.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 10, 'A všickni, kdož jsou vtipní mezi vámi, přijdou a dělati budou, cožkoli přikázal Hospodin:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 11, 'Příbytek, stánek jeho i přikrytí jeho a háky jeho, dsky jeho, svlaky jeho, sloupy jeho i podstavky jeho;');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 12, 'Truhlu s sochory jejími, slitovnici a oponu zastření;');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 13, 'Stůl i sochory k němu se všemi nádobami jeho, i chléb předložení;');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 14, 'A svícen k svícení s nádobami jeho i lampy jeho, a olej k svícení;');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 15, 'Též oltář pro kadění a sochory jeho, i olej pomazání a kadidlo z vonných věcí, i zastření dveří v příbytku;');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 16, 'Oltář k zápalu a rošt jeho měděný a sochory jeho, i všecka nádobí jeho, i umyvadlo s podstavkem jeho;');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 17, 'Koltry očkovaté k síni, sloupy její a podstavky její, i zastření brány do síně;');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 18, 'Kolíky k příbytku, a kolíky síně s provázky jejich;');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 19, 'Roucha k službě, k přisluhování v svatyni, i roucho svaté Arona kněze, i roucho synů jeho k konání úřadu kněžského.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 20, 'Vyšlo tedy všecko shromáždění synů Izraelských od tváři Mojžíšovy,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 21, 'A přišli, každý muž, kteréhož ponuklo srdce jeho, a každý, v němž duch jeho byl dobrovolný, a přinesli obět pozdvižení Hospodinu, k dílu stánku úmluvy a ke vší službě jeho, i k rouchu svatému.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 22, 'Přicházeli muži i ženy, každý, kdož byl ochotný v srdci, a přinášeli spinadla, a náušnice, a prsteny, a záponky z pravých rukou, všelijaké nádobí zlaté, a kdožkoli obětoval obět zlata Hospodinu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 23, 'Každý, kdož měl postavec modrý a šarlat, a červec dvakrát barvený, a bílé hedbáví a kozí srsti, a kůže skopců na červeno barvené, a kůže jezevčí, přinesl to.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 24, 'Kdokoli obětoval obět stříbra a mědi, přinášeli to za obět pozdvižení Hospodinu; každý také, kdo měl dříví setim, ke všelikému dílu služebnosti, přinášeli je.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 25, 'Ano i všecky ženy vtipné rukama svýma předly, a přinesly, co napředly, postavec modrý a šarlat, a červec dvakrát barvený a bílé hedbáví.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 26, 'Všecky pak ženy, kterýchž ponuklo srdce jejich, aby předly uměle, předly srsti kozí.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 27, 'Knížata pak přinášeli kamení onychinové, a jiné kamení k vsazování do náramenníku a náprsníku,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 28, 'Též vonné věci a olej k svícení, a k oleji pomazání, a k vonnému kadidlu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 29, 'Každý muž i žena, v nichž ochotné srdce jejich bylo k tomu, aby přinášeli potřeby ke všelikému dílu, kteréž byl přikázal dělati Hospodin skrze Mojžíše, přinášeli synové Izraelští obět dobrovolnou Hospodinu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 30, 'Tedy řekl Mojžíš synům Izraelským: Pohleďte, povolal ze jména Hospodin Bezeleele, syna Uri, syna Hur, z pokolení Judova.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 31, 'A naplnil ho duchem Božím, moudrostí, rozumností i uměním všelijakého řemesla,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 32, 'Aby vtipně smysliti uměl, jak by se co dělati mělo na zlatu a stříbru a mědi,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 33, 'I v řemeslném strojení kamenů k vsazování, i v díle od dřeva, aby dělal všelijakým řemeslem vtipným.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 34, 'Dal nadto v srdce jeho i to, aby učiti mohl on i Aholiab, syn Achisamechův z pokolení Dan.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 35, 'Naplnil je moudrostí srdce, aby dělali všelijaké dílo tesařské a řemeslné, i krumpéřské a vytkávané z postavce modrého a šarlatu, a červce dvakrát barveného, a bílého hedbáví, a aby dělali všelijaké dílo a vymýšleli vtipné věci.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 1, 'Tedy dělal Bezeleel a Aholiab i všeliký muž vtipný, jimž dal Hospodin moudrost a rozumnost, aby uměli dělati všeliké dílo k službě svatyně, všecko, což přikázal Hospodin.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 2, 'Povolal pak Mojžíš Bezeleele a Aholiaba i každého muže vtipného, v jehož srdce dal Hospodin moudrost, každého také, kohož ponoukalo srdce jeho, aby přistoupil ku práci díla toho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 3, 'A vzali od Mojžíše všecky dary, kteréž přinesli synové Izraelští k dílu služebnému svatyně, aby dělali je. Ale oni vždy předce přinášeli k němu každého jitra dary dobrovolné.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 4, 'Tedy přišli všickni vtipní dělníci díla svatyně, každý od díla svého, kteréž dělali,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 5, 'A mluvili k Mojžíšovi těmi slovy: Mnohem více přináší lid, nežli potřebí jest k dělání díla, kteréž přikázal Hospodin dělati.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 6, 'I rozkázal Mojžíš, aby provoláno bylo v vojště takto: Muž ani žena, žádný nepřinášej více oběti k svatyni. I zbráněno jest lidu, aby nenosili.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 7, 'Nebo měli potřeb hojně dosti k dělání všelikého díla, tak že zbývalo.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 8, 'I dělal každý vtipný z dělníků těch dílo to, příbytek z desíti čalounů, kteříž byli z bílého hedbáví přesukovaného, a z postavce modrého a šarlatu, a z červce dvakrát barveného; cherubíny dílem řemeslným udělal na nich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 9, 'Dlouhost čalounu jednoho osm a dvadceti loktů, a čtyř loktů širokost čalounu jednoho; všickni čalounové byli jednostejné míry.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 10, 'Potom spojil pět čalounů jeden s druhým, a pět jiných čalounů spojil jeden s druhým.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 11, 'Nadělal i ok z hedbáví modrého po kraji čalounu jednoho na konci, kde se spojovati má s druhým, a tolikéž udělal na kraji čalounu druhého na konci v spojení druhém.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 12, 'Padesáte ok udělal na čalounu jednom, a padesáte ok udělal po kraji čalounu, kterýmž připojen byl k druhému; oko jedno proti druhému bylo.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 13, 'Udělal i padesáte haklíků zlatých a spojil čalouny jeden s druhým haklíky těmi; a tak udělán jest příbytek jeden.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 14, 'Nadto nadělal houní z srstí kozích na stánek, k přistírání příbytku po vrchu; jedenácte houní udělal.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 15, 'Dlouhost houně jedné třidceti loktů, a širokost houně jedné čtyř loktů; jednostejná míra byla těch jedenácti houní.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 16, 'A spojil pět houní obzvláštně, a šest houní obzvláštně.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 17, 'Udělal také padesáte ok po kraji houně na konci, kdež se spojovati má, a padesáte ok udělal po kraji houně v spojení druhém.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 18, 'Udělal k tomu haklíků měděných padesáte k spojení stánku, aby byl jedno.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 19, 'Nadto udělal přikrytí stánku z koží skopcových na červeno barvených, a přikrytí z koží jezevčích svrchu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 20, 'Nadělal k příbytku i desk z dříví setim stojatých.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 21, 'Desíti loktů dlouhost dsky, a půl druhého širokost dsky každé.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 22, 'Dva čepy měla dska jedna, podobně jako stupně u schodu spořádané, jeden proti druhému; tak udělal u všech desk příbytku.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 23, 'Zdělal i dsky k příbytku, dvadceti desk k straně polední, k větru polednímu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 24, 'A čtyřidceti podstavků stříbrných udělal pode dvadceti desk, dva podstavky pod jednu dsku ke dvěma čepům jejím, a dva podstavky pod dsku druhou pro dva čepy její.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 25, 'Na druhé pak straně příbytku k straně půlnoční udělal dvadceti desk,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 26, 'A čtyřidceti podstavků jejich stříbrných, dva podstavky pod jednu dsku a dva podstavky pod dsku druhou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 27, 'Na straně pak příbytku k západu udělal šest desk.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 28, 'Dvě dsky udělal v úhlech po obou stranách příbytku.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 29, 'A byly spojené po spodu a tolikéž spojené svrchu k jednomu kruhu; tak udělal po obou stranách ve dvou úhlech.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 30, 'A tak bylo osm desk a podstavků jejich stříbrných šestnácte, dva podstavkové pod každou dskou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 31, 'Nadělal i svlaků z dříví setim, pět ke dskám straně příbytku jedné,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 32, 'A pět svlaků ke dskám druhé strany příbytku, a pět svlaků ke dskám strany příbytku západní, dosahujících k oběma úhlům.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 33, 'A svlak prostřední udělal, aby šel po prostředku desk od jednoho kraje k druhému.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 34, 'Dsky pak obložil zlatem a kruhy jejich udělal z zlata, aby v nich svlaky byly; a obložil svlaky zlatem.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 35, 'Udělal také oponu z postavce modrého a šarlatu, a z červce dvakrát barveného, a z bílého hedbáví přesukovaného; dílem řemeslným udělal ji s figurami cherubínů.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 36, 'A udělal pro ni čtyři sloupy z dříví setim, a obložil je zlatem; hákové pak jejich byli zlatí, a slil k nim čtyři podstavky stříbrné.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 37, 'Udělal také zastření ke dveřům stánku z postavce modrého, z šarlatu a z červce dvakrát barveného a z bílého hedbáví přesukovaného, dílem krumpéřským,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 38, 'A sloupů k tomu zastření pět s háky jejich, (obložil pak makovice a přepásaní jich zlatem,) a podstavků pět měděných.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 1, 'Udělal také Bezeleel truhlu z dříví setim, jejíž dlouhost byla půl třetího lokte, a půl druhého lokte širokost, vysokost také půl druhého lokte.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 2, 'A obložil ji zlatem čistým vnitř i zevnitř, a udělal jí korunu zlatou vůkol.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 3, 'Slil jí také čtyři kruhy zlaté ke čtyřem úhlům jejím, dva totiž kruhy po jedné straně její, a dva kruhy po druhé straně její.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 4, 'Zdělal i sochory z dříví setim a obložil je zlatem.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 5, 'A uvlékl sochory do kruhů po stranách truhly; aby na nich nošena byla truhla.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 6, 'Udělal také slitovnici z zlata čistého. Půl třetího lokte byla dlouhost její, a půl druhého lokte širokost její.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 7, 'Udělal i dva cherubíny z zlata, z taženého zlata udělal je na dvou koncích slitovnice,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 8, 'Cherubína jednoho na jednom konci a cherubína druhého na druhém konci; na slitovnici udělal cherubíny, na obou koncích jejích.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 9, 'Ti pak cherubínové měli křídla vztažená svrchu nad ní, zastírajíce křídly svými slitovnici; a tváři jejich byly obráceny jedna k druhé, k slitovnici byly obráceny tváři cherubínů.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 10, 'Udělal i stůl z dříví setim. Dvou loket byla dlouhost jeho a na loket širokost jeho, půl druhého pak lokte vysokost.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 11, 'A obložil jej zlatem čistým, i korunu zlatou udělal mu vůkol.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 12, 'Udělal mu i lištu dlani zšíří vůkol, a udělal korunu zlatou okolo té lišty.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 13, 'Slil také k němu čtyři kruhy zlaté a vpustil je do čtyř úhlů, kteříž byli na čtyřech nohách jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 14, 'Proti té liště byli kruhové, skrze něž by provlačováni byli sochorové k nošení stolu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 15, 'Udělal i sochory z dříví setim, kteréžto obložil zlatem k nošení stolu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 16, 'A zdělal nádoby, kteréž byly na stole, misy jeho a lžice jeho, a koflíky jeho, a přikryvadla k přikrývání z čistého zlata.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 17, 'Udělal také svícen z zlata čistého, z taženého zlata udělal svícen; sloupec jeho i prutové jeho, misky jeho, koule jeho i květové jeho z něho byli.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 18, 'Šest pak prutů bylo po stranách jeho, tři prutové s jedné strany jeho, a tři prutové s druhé strany jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 19, 'Tři misky na způsob pecky mandlové udělány byly na prutu jednom, a koule a květ, a tři misky na způsob pecky mandlové udělány na prutu druhém, a koule a květ; tak i na jiných šesti prutech z svícnu vycházejících.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 20, 'Na svícnu také byly čtyři misky, udělané na způsob mandlové pecky, a koule jeho i květové jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 21, 'A byla koule pode dvěma pruty z něho, a koule druhá pode dvěma pruty z něho, a koule třetí pode dvěma pruty z něho, a tak pod šesti pruty vycházejícími z něho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 22, 'Koule jejich i prutové jejich z něho byli, všecko hned jedním tažením z zlata čistého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 23, 'Udělal i lamp jeho sedm, i utěradla jeho, i nádoby k oharkům jeho z zlata čistého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 24, 'Z centnéře zlata čistého udělal jej se vším tím nádobím.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 25, 'Udělal také oltář pro kadění z dříví setim, lokte zdélí a lokte zšíří, čtverhraný, dvou pak loket zvýší; z něho byli rohové jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 26, 'A obložil jej zlatem čistým, svrchek jeho i po stranách vůkol, i rohy jeho; a udělal mu korunu zlatou vůkol.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 27, 'Po dvou podobně kruzích zlatých udělal u něho, pod korunou ve dvou úhlech jeho, po dvou stranách jeho, skrze něž by provlačováni byli sochorové, aby nošen byl na nich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 28, 'A zdělal ty sochory z dříví setim, a obložil je zlatem.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 29, 'Nadělal také oleje pomazání svatého, a kadidla z vonných věcí, čistého, dílem apatykářským.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 1, 'Udělal také oltář k zápalu z dříví setim, pěti loket zdélí a pěti loket zšíří, čtverhraný, a tří loket zvýší.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 2, 'A zdělal mu rohy na čtyřech úhlech jeho; z něho byli rohové jeho, a obložil jej mědí.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 3, 'Nadělal také všelijakých nádob k oltáři, hrnců a lopat, a kotlíků a vidliček, a nádob jeho k uhlí; všecka nádobí jeho udělal měděná.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 4, 'Udělal k oltáři i rošt mřežovaný, měděný, pod okolkem oltáře dole, až do prostřed něho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 5, 'A slil čtyři kruhy na čtyřech krajích k roštu měděnému, v nichž by sochorové bývali.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 6, 'Sochory pak udělal z dříví setim a obložil je mědí.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 7, 'A uvlékl ty sochory do těch kruhů po obou stranách oltáře k nošení jeho na nich; prázdný z prken udělal jej.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 8, 'Udělal též umyvadlo měděné, a podstavek jeho měděný z zrcadel houfně přicházejících žen, kteréž přicházely ke dveřím stánku úmluvy.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 9, 'Udělal také síň k straně polední; koltry očkovaté síně té z bílého hedbáví přesukovaného na sto loket,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 10, 'Sloupů jejich dvadceti, a k nim podstavků dvadceti z mědi, háky na sloupích, a přepásaní jejich z stříbra.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 11, 'Tolikéž k straně půlnoční koltry na sto loket, sloupů k nim dvadceti a podstavků jejich dvadceti z mědi, háky na sloupích a přepásaní jejich z stříbra.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 12, 'K straně pak západní koltry očkovaté na padesáte loket, sloupů k nim deset a podstavků jejich deset, háky na sloupích a přepásaní jejich z stříbra.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 13, 'A v straně přední na východ padesáti loktů,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 14, 'Koltry očkovaté patnácti loktů byly při straně jedné, sloupové k nim tři, a podstavkové jejich tři.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 15, 'A k straně druhé, u brány síně té, jakž tam, tak tuto, koltry očkovaté patnácti loktů, sloupové k nim tři a podstavkové jejich tři.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 16, 'Všecky koltry síně vůkol očkovaté z bílého hedbáví přesukovaného.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 17, 'Podstavkové pak sloupů z mědi, hákové na sloupích a přepásaní jich z stříbra, a obložení makovic jejich z stříbra; všickni také sloupové síně přepásáni byli stříbrem.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 18, 'Zastření pak brány síňce dílem krumpéřským z postavce modrého a šarlatu, a červce dvakrát barveného a hedbáví bílého přesukovaného; dlouhost jeho dvadceti loktů, výsost pak šířky pěti loktů, jako i jiných koltr síně očkovatých.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 19, 'A sloupové k ní čtyři a podstavkové jejich čtyři z mědi, hákové jejich stříbrní, a obložení makovic jejich a přepásaní jejich z stříbra.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 20, 'Všickni pak kolíkové příbytku a síně vůkol byli z mědi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 21, 'Tyto jsou věci vyčtené k příbytku, příbytku svědectví, kteréž jsou vyčteny podlé rozkázaní Mojžíšova, skrze Itamara, syna Arona kněze, k službě Levítů.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 22, 'A Bezeleel, syn Uri, syna Hur, z pokolení Juda, udělal všecky tyto věci, kteréž přikázal Hospodin Mojžíšovi;');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 23, 'A s ním Aholiab, syn Achisamechův z pokolení Dan, tesař a vtipný řemeslník, a krumpéř na modrém postavci a šarlatu, a červci dvakrát barveném a kmentu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 24, 'Všeho zlata vynaloženého na samo dílo, na všecko dílo svatyně, (bylo pak zlato obětované,) devět a dvadceti centnéřů, a sedm set třidceti lotů podlé váhy svatyně.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 25, 'Stříbra pak od těch, jenž náležejí ku počtu shromáždění, sto centnéřů, a tisíc sedm set sedmdesáte pět lotů podlé váhy svatyně.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 26, 'Půl lotu z každé hlavy podlé váhy svatyně, ode všech jdoucích v počet od dvadcíti let a výše, jichž bylo šestkrát sto tisíc, tři tisíce pět set a padesáte.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 27, 'A bylo sto centnéřů stříbra k slévání podstavků svatyně a podstavků opony; sto podstavků ze sta centnéřů, centnéř do podstavku.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 28, 'A z tisíce sedmi set sedmdesáti pěti lotů udělal háky na sloupy, a obložil makovice jejich a přepásal je.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 29, 'Mědi pak obětované bylo sedmdesáte centnéřů a dva tisíce a čtyři sta lotů.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 30, 'A udělal z ní podstavky ke dveřům stánku svědectví a oltář měděný, a rošt měděný k němu, a všecky nádoby oltáře,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 31, 'A podstavky síně vůkol a podstavky brány síně, všecky také kolíky příbytku a všecky kolíky síňce vůkol.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 1, 'Z modrého pak postavce a šarlatu a červce dvakrát barveného udělali roucha k službě, k přisluhování v svatyni. Udělali i roucho svaté, kteréž by bylo Aronovi, jakž byl přikázal Hospodin Mojžíšovi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 2, 'A udělal náramenník z zlata, postavce modrého a šarlatu, a červce dvakrát barveného, a bílého hedbáví přesukovaného.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 3, 'I nadělali plíšků zlatých, a nastříhali z nich nití, aby jimi províjeli skrze modrý postavec a šarlat, a červec dvakrát barvený a bílé hedbáví, dílem řemeslným.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 4, 'Náramky u něho udělali tak, aby se jeden s druhým spojiti mohl; na dvou krajích svých spojoval se.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 5, 'Přepásaní také náramenníka, kteréž bylo na něm, z týchž věcí bylo a týmž dílem, z zlata, postavce modrého a šarlatu a červce dvakrát barveného, a bílého hedbáví přesukovaného, jakž byl přikázal Hospodin Mojžíšovi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 6, 'Přisadili i kamení onychinové, vložené a vsazené do zlata, řezané tak, jako ryty bývají pečeti, s jmény synů Izraelských.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 7, 'A vložil je na vrchní kraje náramenníku, aby byli kamenové pro pamět na syny Izraelské, jakž byl přikázal Hospodin Mojžíšovi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 8, 'Udělal i náprsník dílem řemeslným, takovým dílem jako náramenník, z zlata, postavce modrého a šarlatu, a červce dvakrát barveného, a bílého hedbáví přesukovaného.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 9, 'Čtverhranatý byl; dvojnásobní udělali náprsník, na píd zdélí, a na píd zšíří, dvojnásobní.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 10, 'A vysadili jej čtyřmi řady kamení drahého pořádkem tímto: Sardius, topazius a smaragdus v řadu prvním;');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 11, 'V řadu pak druhém karbunkulus, zafir a jaspis;');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 12, 'A v řadu třetím linkurius, achates a ametyst;');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 13, 'A v čtvrtém řadu chrysolit, onychin a beryl, vložení a vsazení do zlata v svém pořádku.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 14, 'Těch pak kamenů s jmény synů Izraelských bylo dvanácte vedlé jmen jejich, vyrytých, jako pečet ryta bývá, každý vedlé jména svého pro dvanáctero pokolení.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 15, 'Udělali i k náprsníku řetízky jednostejné, dílem točeným z zlata čistého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 16, 'Udělali také dva haklíky zlaté, a dva kroužky zlaté, a připjali ty dva kroužky na dvou krajích náprsníku.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 17, 'A prostrčili dva řetízky zlaté skrze dva kroužky na krajích náprsníku.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 18, 'Druhé pak dva konce dvou řetízků vpjali do dvou těch haklíků, a dali je na vrchní kraje náramenníku po předu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 19, 'Udělali též dva kroužky zlaté, kteréž dali na dva kraje náprsníku, na té obrubě jeho, kteráž byla po straně náramenníka po spodu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 20, 'Udělali ještě dva jiné kroužky zlaté, kteréž dali na dvě strany náramenníka zespod po předu, proti spojení jeho, kteréž jest nad přepásaním náramenníka.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 21, 'I přivázali náprsník od kroužků jeho k kroužkům toho náramenníka tkanicí hedbáví modrého, aby byl nad přepásaním náramenníka, a aby neodevstával náprsník od náramenníka, jakž byl přikázal Hospodin Mojžíšovi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 22, 'Udělal také plášť náležející k náramenníku, dílem vytkávaným, všecken z postavce modrého,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 23, 'A díru u prostřed pláště, jako díra v pancíři; okolek byl po kraji jejím vůkol, aby se neroztrhl.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 24, 'Udělali také na podolku pláště jablka zrnatá z postavce modrého a šarlatu, a červce dvakrát barveného, a bílého hedbáví přesukovaného.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 25, 'Nadělali i zvonečků z zlata čistého, a zzavěšovali zvonečky ty mezi jablky zrnatými u podolku pláště vůkol, u prostřed mezi jablky zrnatými;');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 26, 'Zvonček a jablko zrnaté, opět za tím zvonček a jablko zrnaté u podolku pláště vůkol, k užívání toho při službě, jakž byl přikázal Hospodin Mojžíšovi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 27, 'Potom udělali sukni z bílého hedbáví dílem vytkávaným, Aronovi a synům jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 28, 'I čepici z bílého hedbáví, a klobouky ozdobné z bílého hedbáví, a košilky tenké z bílého hedbáví přesukovaného,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 29, 'Pás také z bílého hedbáví přesukovaného, a postavce modrého a šarlatu, a červce dvakrát barveného, dílem krumpéřským, jakž byl přikázal Hospodin Mojžíšovi,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 30, 'Udělali i plech koruny svaté z zlata čistého, a napsali na něm písmo dílem vyrývajících pečeti: Svatost Hospodinu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 31, 'A dali do něho tkanici z hedbáví modrého, aby přivázán byl k čepici na hoře, jakž byl přikázal Hospodin Mojžíšovi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 32, 'A tak dokonáno jest všecko dílo příbytku stánku úmluvy; a učinili synové Izraelští všecko, jakž přikázal Hospodin Mojžíšovi, tak učinili,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 33, 'A přinesli příbytek ten k Mojžíšovi, stánek i všecka nádobí jeho, háky jeho, dsky jeho, svlaky jeho, i sloupy jeho a podstavky jeho,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 34, 'Přikrytí také z koží skopových na červeno barvených, a přikrytí z koží jezevčích i oponu zastření,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 35, 'Truhlu svědectví s sochory jejími i slitovnici,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 36, 'Stůl, všecka nádobí jeho i chléb předložení,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 37, 'Svícen čistý, lampy jeho, lampy zpořádané, i všecka nádobí jeho, i olej k svícení,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 38, 'Též oltář zlatý a olej pomazání a kadidlo z vonných věcí a zastření ke dveřům stánku,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 39, 'Oltář měděný a rošt jeho měděný, sochory jeho a všecka nádobí jeho, i umyvadlo a podstavek jeho,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 40, 'Očkovaté koltry síně a sloupy k nim s podstavky jejich, i zastření k bráně té síně, provazy také její a kolíky i všecka nádobí k službě příbytku, k stánku úmluvy,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 41, 'Roucha k službě, k přisluhování v svatyni, roucho svaté Arona kněze i roucho synů jeho k konání úřadu kněžského.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 42, 'Vedlé všeho, což přikázal Hospodin Mojžíšovi, tak udělali synové Izraelští všecko to dílo.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 43, 'A viděl Mojžíš všecko to dílo, a aj, udělali je, jakž byl přikázal Hospodin, tak udělali. I požehnal jim Mojžíš.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 1, 'Potom mluvil Hospodin k Mojžíšovi, řka:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 2, 'V den měsíce prvního, prvního dne téhož měsíce vyzdvihneš příbytek, stánek úmluvy.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 3, 'A postavíš tam truhlu svědectví a zastřeš ji oponou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 4, 'Vneseš i stůl a zřídíš řád jeho, vneseš také svícen a rozsvítíš lampy jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 5, 'Postavíš též oltář zlatý pro kadění naproti truhle svědectví, a zavěsíš zastření ve dveřích příbytku.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 6, 'Potom postavíš oltář k zápalům přede dveřmi příbytku stánku úmluvy.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 7, 'Postavíš také umyvadlo mezi stánkem úmluvy a mezi oltářem, do něhož naleješ vody.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 8, 'Naposledy vyzdvihneš síň vůkol a zavěsíš zastření brány síně.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 9, 'Tedy vezmeš olej pomazání a pomažeš příbytku a všech věcí, kteréž v něm jsou, a posvětíš ho i všech nádob jeho, a bude svatý.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 10, 'Pomažeš i oltáře zápalu a všech nádob jeho a posvětíš oltáře, a budeť oltář svatý.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 11, 'Pomažeš také umyvadla a podstavku jeho, a posvětíš ho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 12, 'A přistoupiti kážeš Aronovi i synům jeho ke dveřím stánku svědectví, a umyješ je vodou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 13, 'A oblečeš Arona v roucha svatá a pomažeš ho a posvětíš ho, aby úřad kněžský konal přede mnou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 14, 'Synům také jeho přistoupiti kážeš, a zobláčíš je v sukně.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 15, 'A pomažeš jich, tak jako jsi pomazal otce jejich, aby úřad kněžský konali přede mnou, aby jim bylo pomazání jejich toto k kněžství věčnému po rodech jejich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 16, 'I učinil Mojžíš tak. Všecko, jakž mu rozkázal Hospodin, tak učinil.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 17, 'I stalo se měsíce prvního léta druhého, prvního dne měsíce, že vyzdvižen jest příbytek.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 18, 'Mojžíš tedy vyzdvihl příbytek a podložil podstavky jeho a postavil dsky jeho, a provlékl svlaky jeho, a vyzdvihl sloupy jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 19, 'Potom postavil stánek v příbytku a dal přikrytí stánku svrchu na něj, jakož mu byl přikázal Hospodin.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 20, 'A vzav svědectví, vložil je do truhly, uvlékl také sochory k truhle a dal slitovnici svrchu na truhlu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 21, 'I vnesl truhlu do příbytku a zavěsil oponu zastření, a zastřel truhlu svědectví, jakož byl přikázal Hospodin Mojžíšovi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 22, 'Postavil i stůl v stánku úmluvy k straně příbytku půlnoční, vně před oponou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 23, 'A zřídil na něm zpořádaní chlebů před Hospodinem, jakž přikázal Hospodin Mojžíšovi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 24, 'A postavil svícen v stánku úmluvy naproti stolu, v straně příbytku ku poledni.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 25, 'A rozsvítil lampy před Hospodinem, jakož přikázal Hospodin Mojžíšovi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 26, 'Postavil také oltář zlatý v stánku úmluvy před oponou,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 27, 'A kadil na něm kadidlem vonným, jakž přikázal Hospodin Mojžíšovi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 28, 'Zavěsil také zastření dveří příbytku.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 29, 'A oltář zápalu postavil ke dveřům příbytku stánku úmluvy, a obětoval na něm oběti zápalné a suché, jakož přikázal Hospodin Mojžíšovi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 30, 'A postavil umyvadlo mezi stánkem úmluvy a mezi oltářem, do něhož nalil vody k umývání.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 31, 'A umýval z něho Mojžíš, Aron a synové jeho ruce své i nohy své.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 32, 'Když vcházeli do stánku úmluvy, a když přistupovali k oltáři, umývali se, jakož přikázal Hospodin Mojžíšovi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 33, 'Naposledy vyzdvihl síň vůkol příbytku a oltáře, a zavěsil zastření brány síně. A tak dokonal Mojžíš dílo to.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 34, 'Tedy přikryl oblak stánek úmluvy, a sláva Hospodinova naplnila příbytek.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 35, 'A nemohl Mojžíš vjíti do stánku úmluvy; nebo byl nad ním oblak, a sláva Hospodinova naplnila příbytek.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 36, 'Když pak odnášel se oblak s příbytku, brali se synové Izraelští po všech taženích svých.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 37, 'Pakli se neodnášel oblak, nehýbali se až do dne, v němž se zdvihl.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 38, 'A byl oblak Hospodinův nad příbytkem ve dne, a oheň býval v noci na něm, před očima všeho domu Izraelského ve všech taženích jejich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 1, 'Povolal pak Hospodin Mojžíše, a mluvil k němu z stánku úmluvy, řka:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 2, 'Mluv k synům Izraelským a rci jim: Když by kdo z vás obětoval obět Hospodinu, z hovad, totiž z volů aneb z drobného dobytka obětovati budete obět svou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 3, 'Jestliže zápalná obět jeho byla by z skotů, samce bez vady obětovati bude. U dveří stánku úmluvy obětovati jej bude dobrovolně, před oblíčejem Hospodinovým.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 4, 'A vloží ruku svou na hlavu oběti zápalné, i bude příjemná jemu k očištění jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 5, 'Tedy zabije volka toho před tváří Hospodinovou, a obětovati budou kněží, synové Aronovi, krev, a pokropí tou krví oltáře svrchu vůkol, kterýž jest u dveří stánku úmluvy.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 6, 'I stáhne kůži s oběti zápalné, a rozseká ji na díly své.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 7, 'A dají synové Arona kněze oheň na oltář, a narovnají dříví na tom ohni.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 8, 'Potom zpořádají kněží, synové Aronovi, díly ty, hlavu i tuk, na dříví vložené na oheň, kterýž jest na oltáři.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 9, 'A droby jeho i nohy jeho vymyjete vodou. I páliti bude kněz všecko to na oltáři; zápal jest v obět ohnivou, vůně spokojující Hospodina.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 10, 'Jestliže pak z drobného dobytka bude obět jeho, z ovcí aneb z koz k oběti zápalné, samce bez poškvrny obětovati bude.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 11, 'A zabije ho při straně oltáře půlnoční před tváří Hospodinovou, a pokropí kněží, synové Aronovi, krví oltáře vůkol.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 12, 'I rozseká ho na díly jeho s hlavou jeho i tukem jeho, a zpořádá je kněz na dříví vložené na oheň, kterýž jest na oltáři.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 13, 'A střeva jeho i nohy jeho vymyje vodou. Tedy obětovati bude kněz všecko to, a páliti bude to na oltáři; zápal jest v obět ohnivou, vůně spokojující Hospodina.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 14, 'Jestliže pak z ptactva obět zápalnou obětovati bude Hospodinu, tedy ať obětuje z hrdliček aneb z holoubat obět svou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 15, 'I vloží je kněz na oltář a nehtem natrhne hlavy jeho, a zapálí na oltáři, vytlače krev jeho na stranu oltáře.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 16, 'Odejme také vole jeho s nečistotami jeho, a povrže je blízko oltáře k straně východní na místo, kdež jest popel.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 17, 'A natrhne ho za křídla jeho, kterýchž však neodtrhne. I páliti bude je kněz na oltáři na dříví, kteréž jest na ohni; zápalť jest v obět ohnivou, vůně spokojující Hospodina.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 1, 'Když by pak který člověk obětoval dar oběti suché Hospodinu, mouka bělná bude obět jeho. I poleje ji olejem a vloží na ni kadidlo.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 2, 'Přinese ji pak k synům Aronovým kněžím, a vezme odtud plnou hrst svou té mouky bělné a toho oleje se vším kadidlem jejím; i páliti to bude kněz na památku její na oltáři v obět ohnivou, vůně spokojující Hospodina.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 3, 'Ostatek pak té oběti suché bude Aronovi i synům jeho, svaté svatých, z ohnivých obětí Hospodinových.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 4, 'Když bys pak obětoval dar oběti suché, pečené v peci, ať jsou z mouky bělné koláčové nekvašení, zadělaní olejem, aneb oplatkové přesní olejem pomazaní.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 5, 'Jestliže pak obět suchou na pánvici smaženou obětovati budeš, bude z mouky bělné olejem zadělané a nenakvašené.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 6, 'Rozlámeš ji na kusy a naleješ na ni oleje, obět suchá jest.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 7, 'Pakli obět suchou v kotlíku připravenou obětovati budeš, z mouky bělné s olejem bude.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 8, 'I přineseš obět suchou, kteráž z těch věcí bude Hospodinu, a dáš ji knězi, kterýžto donese ji k oltáři.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 9, 'A vezma kněz z oběti té pamětné její, páliti je bude na oltáři, v obět ohnivou, vůně spokojující Hospodina.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 10, 'Což pak zůstane z oběti té suché, bude Aronovi i synům jeho, svaté svatých, z ohnivých obětí Hospodinových.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 11, 'Žádná obět suchá, kterouž obětovati budete Hospodinu, nebude kvašena; nebo nižádného kvasu, ani medu nebudete obětovati v obět ohnivou Hospodinu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 12, 'V oběti prvotin toliko obětovati budete je Hospodinu, ale na tento oltář neobětujte jich u vůni spokojující.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 13, 'Také všeliký dar suché oběti své solí osolíš, a neodejmeš soli smlouvy Boha svého od suché oběti své. Při každé oběti své sůl obětovati budeš.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 14, 'Jestliže bys pak obětoval obět suchou z prvotin Hospodinu, klasy nové ohněm upražíš, a což vymneš z těch klasů nových, to obětovati budeš, suchou obět prvotin svých.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 15, 'A poleješ ji svrchu olejem, kadidlo také vložíš na ni; obět suchá jest.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 16, 'I páliti bude kněz pamětné její z obilí zetřeného, a z oleje toho, se vším tím kadidlem jejím; v obět ohnivou bude Hospodinu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 1, 'Jestliže pak obět pokojná bude obět jeho, když by z skotů obětoval, buď vola neb krávu, bez vady bude obětovati je před tváří Hospodinovou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 2, 'Tedy položí ruku svou na hlavu oběti své, i zabije ji u dveří stánku úmluvy; a kropiti budou kněží synové Aronovi krví na oltář vůkol.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 3, 'Potom obětovati bude z oběti pokojné ohnivou obět Hospodinu, tuk střeva kryjící, i všeliký tuk, kterýž jest na nich,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 4, 'Též obě ledvinky s tukem, kterýž jest na nich i na slabinách, tolikéž i branici, kteráž jest na jatrách; s ledvinkami odejme ji.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 5, 'I páliti to budou synové Aronovi na oltáři spolu s obětí zápalnou, kteráž bude na dříví vloženém na oheň; obět zajisté ohnivá jest, vůně spokojující Hospodina.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 6, 'Jestliže pak z drobného dobytka bude obět jeho v obět pokojnou Hospodinu, samce aneb samici, bez poškvrny obětovati bude ji.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 7, 'Jestliže by obětoval beránka, obět svou, tedy obětovati jej bude před tváří Hospodinovou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 8, 'A vloží ruku svou na hlavu oběti své, a zabije ji před stánkem úmluvy, a kropiti budou synové Aronovi krví její na oltář vůkol.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 9, 'Potom obětovati bude z oběti pokojné obět ohnivou Hospodinu, tuk její i ocas celý, kterýž od hřbetu odejme, též i tuk střeva kryjící se vším tím tukem, kterýž jest na nich,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 10, 'Též obě dvě ledvinky s tukem, kterýž jest na nich i na slabinách, ano i branici, kteráž jest na jatrách; s ledvinkami odejme ji.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 11, 'I páliti to bude kněz na oltáři; pokrm jest oběti ohnivé Hospodinovy.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 12, 'Jestliže pak koza byla by obět jeho, tedy bude ji obětovati před oblíčejem Hospodinovým.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 13, 'A vloží ruku svou na hlavu její, a zabije ji před stánkem úmluvy; i kropiti budou synové Aronovi krví její na oltáři vůkol.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 14, 'Potom obětovati bude z ní obět svou v obět ohnivou Hospodinu, tuk střeva kryjící, i všecken tuk, kterýž jest na nich,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 15, 'Též obě dvě ledvinky s tukem, kterýž jest na nich i na slabinách, ano i branici, kteráž jest na jatrách; s ledvinkami odejme ji.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 16, 'I páliti to bude kněz na oltáři, pokrm oběti ohnivé u vůni příjemnou. Všecken tuk Hospodinu bude.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 17, 'Právem věčným po rodech vašich, ve všech příbytcích vašich žádného tuku a žádné krve nebudete jísti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 1, 'Mluvil také Hospodin k Mojžíšovi, řka:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 2, 'Mluv synům Izraelským a rci: Když by kdo zhřešil z poblouzení proti některému ze všech přikázaní Hospodinových, čině, čehož býti nemá, a přestoupil by jedno z nich;');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 3, 'Jestliže by kněz pomazaný zhřešil hříchem jiných lidí: tedy obětovati bude za hřích svůj, kterýmž zhřešil, volka mladého bez poškvrny Hospodinu v obět za hřích.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 4, 'I přivede volka toho ke dveřím stánku úmluvy před oblíčej Hospodinův, a položí ruku svou na hlavu volka toho, a zabije ho před oblíčejem Hospodinovým.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 5, 'Tedy vezme kněz pomazaný krve z toho volka, a vnese ji do stánku úmluvy.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 6, 'Potom omočí kněz prst svůj v té krvi, a kropiti jí bude sedmkráte před Hospodinem, před oponou svatyně.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 7, 'Pomaže také kněz tou krví rohů oltáře, na němž se kadí vonnými věcmi před Hospodinem, kterýž jest v stánku úmluvy, a ostatek krve volka toho vyleje k spodku oltáře zápalu, kterýž jest u dveří stánku úmluvy.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 8, 'Všecken pak tuk volka toho za hřích vyjme z něho, totiž tuk přikrývající střeva a všecken tuk, kterýž jest na nich,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 9, 'Též obě dvě ledvinky s tukem, kterýž jest na nich i na slabinách, tolikéž i branici, kteráž jest na jatrách, s ledvinkami odejme ji,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 10, 'Tak jako se odjímá od volka oběti pokojné, a páliti to bude kněz na oltáři zápalu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 11, 'Kůži pak volka toho, i všecko maso jeho s hlavou i s nohami jeho, střeva jeho i s lejny jeho,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 12, 'A tak celého volka vynese ven za stany na místo čisté, tam kdež se popel vysýpá, a spálí jej na dříví ohněm; na místě, kdež se popel vysýpá, spálen bude.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 13, 'Jestliže by pak všecko množství Izraelské pobloudilo, a byla by ta věc skrytá před očima shromáždění toho, a učinili by proti některému ze všech přikázaní Hospodinových, čehož by býti nemělo, tak že by vinni byli,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 14, 'A byl by poznán hřích, kterýmž zhřešili: tedy obětovati bude shromáždění volka mladého v obět za hřích, a přivedou ho před stánek úmluvy.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 15, 'I položí starší shromáždění toho ruce své na hlavu volka před Hospodinem, a zabije volka před Hospodinem.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 16, 'I vnese kněz pomazaný z krve volka toho do stánku úmluvy,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 17, 'A omoče kněz prst svůj v té krvi, kropiti jí bude sedmkráte před Hospodinem, před oponou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 18, 'Pomaže také kněz tou krví rohů oltáře, kterýž jest před Hospodinem v stánku úmluvy; potom všecku krev pozůstávající vyleje k spodku oltáře zápalu, kterýž jest u dveří stánku úmluvy.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 19, 'Všecken také tuk jeho vyjme z něho, a páliti bude na oltáři.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 20, 'S tím pak volkem tak učiní, jako učinil s volkem za hřích obětovaným, rovně tak učiní s ním. A tak očistí je kněz, i bude jim odpuštěno.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 21, 'Volka pak vynese ven z táboru a spálí jej, jako spálil volka prvního; nebo obět za hřích shromáždění jest.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 22, 'Jestliže pak kníže zhřeší, a učiní proti některému ze všech přikázaní Hospodina Boha svého, čehož býti nemělo, a to z poblouzení, tak že vinen bude,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 23, 'A byl by znám hřích jeho, jímž zhřešil: tedy přivede obět svou z koz, samce bez poškvrny.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 24, 'I položí ruku svou na hlavu toho kozla a zabije ho na místě, kdež se bijí oběti zápalné před Hospodinem; obět za hřích jest.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 25, 'A vezma kněz z krve oběti za hřích na prst svůj, pomaže rohů oltáře zápalu, ostatek pak krve jeho vyleje k spodku oltáře zápalu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 26, 'Všecken také tuk jeho páliti bude na oltáři, jako i tuk obětí pokojných. A tak očistí jej kněz od hříchu jeho, a odpuštěn bude jemu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 27, 'Jestliže pak zhřeší člověk z lidu obecného z poblouzení, učině proti některému přikázaní Hospodinovu, čehož by nemělo býti, tak že vinen bude,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 28, 'A byl by znám hřích jeho, kterýmž zhřešil: tedy přivede obět svou z koz, samici bez poškvrny, za hřích svůj, jímž zhřešil.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 29, 'I položí ruku svou na hlavu oběti té za hřích a zabije tu obět za hřích na místě obětí zápalných.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 30, 'A vezma kněz z krve její na prst svůj, pomaže rohů oltáře zápalu, a ostatek krve její vyleje u spodku oltáře.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 31, 'Všecken také tuk její odejme, jako se odjímá tuk od obětí pokojných, a páliti jej bude kněz na oltáři u vůni příjemnou Hospodinu. A tak očistí jej kněz, a bude mu odpuštěno.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 32, 'Pakli by z ovcí přinesl obět svou za hřích, samici bez poškvrny přinese.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 33, 'A vloží ruku svou na hlavu té oběti za hřích a zabije ji v obět za hřích na místě, kdež se bijí oběti zápalné.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 34, 'Potom vezma kněz krve z oběti té za hřích na prst svůj, pomaže rohů oltáře zápalu, ostatek pak krve její vyleje k spodku oltáře.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 35, 'Všecken také tuk její odejme, jakž se odjímá tuk beránka z obětí pokojných, a páliti jej bude kněz na oltáři v obět ohnivou Hospodinu. A tak očistí jej kněz od hříchu jeho, kterýmž zhřešil, a odpuštěn bude jemu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 1, 'Zhřešil-li by člověk, tak že slyše hlas zakletí a jsa svědkem toho, což viděl neb slyšel, a neoznámil by, poneseť pokutu za nepravost svou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 2, 'Aneb jestliže by se dotkl člověk některé věci nečisté, buďto těla zvěři nečisté, buďto těla hovada nečistého, aneb těla žížaly nečisté, a bylo by to skryto před ním, tedy nečistý bude a vinen jest.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 3, 'Aneb jestliže by se dotkl nečistoty člověka, jaká by koli byla nečistota jeho, kterouž se poškvrňuje, a bylo by to skryto před ním, a potom poznal by to, vinen jest.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 4, 'Aneb jestliže by se kdo zapřisáhl, vynášeje to rty svými, že učiní něco zlého aneb dobrého, a to o jakékoli věci, o níž člověk s přísahou obyčej má mluviti, a bylo by to skryto před ním, a potom by poznal, že vinen jest jednou věcí z těch,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 5, 'Když tedy vinen bude jednou věcí z těch: vyzná hřích svůj,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 6, 'A přivede obět za vinu svou Hospodinu, za hřích svůj, kterýmž zhřešil, samici z dobytku drobného, ovci aneb kozu za hřích, a očistíť jej kněz od hříchů jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 7, 'A pakli by s to býti nemohl, aby dobytče obětoval, tedy přinese obět za vinu svou, kterouž zhřešil, dvě hrdličky aneb dvé holoubátek Hospodinu, jedno v obět za hřích a druhé v obět zápalnou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 8, 'I přinese je k knězi, a on obětovati bude nejprvé to, kteréž má býti v obět za hřích, a nehtem natrhne hlavy jeho naproti tylu jeho, však nerozdělí jí.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 9, 'I pokropí krví z oběti za hřích strany oltáře, a což zůstane krve, vytlačí ji k spodku oltáře; nebo obět za hřích jest.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 10, 'Z druhého pak učiní obět zápalnou vedlé obyčeje. A tak očistí jej kněz od hříchu jeho, kterýmž zhřešil, a bude mu odpuštěn.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 11, 'A pakli nemůže s to býti, aby přinesl dvě hrdličky aneb dvé holoubátek, tedy přinese obět svou ten, kterýž zhřešil, desátý díl míry efi mouky bělné v obět za hřích. Nenalejeť na ni oleje, aniž položí na ni kadidla, nebo obět za hřích jest.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 12, 'Kterouž když přinese k knězi, tedy kněz vezma z ní plnou hrst svou, pamětné její, páliti to bude na oltáři mimo obět ohnivou Hospodinu, obět za hřích jest.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 13, 'I očistí jej kněz od hříchu jeho, kterýmž zhřešil v kterékoli věci z těch, a budeť mu odpuštěn; ostatek pak bude knězi jako při oběti suché.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 14, 'Mluvil opět Hospodin k Mojžíšovi, řka:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 15, 'Kdyby člověk přestoupil přestoupením, a zhřešil by z poblouzení, ujímaje věcí posvěcených Hospodinu: tedy přinese obět za vinu svou Hospodinu, skopce bez poškvrny z drobného dobytka, podlé ceny tvé, nejníž za dva loty stříbra, vedlé lotu svatyně, za vinu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 16, 'A tak, což zhřešil, ujímaje posvěcených věcí, nahradí, a pátý díl nad to přidá, dada to knězi; kněz pak očistí jej skrze skopce oběti za vinu, a bude jemu odpuštěna.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 17, 'Jestliže by pak člověk zhřešil, a učinil by proti některému ze všech přikázaní Hospodinových, čehož by nemělo býti, neznaje toho, a byl by vinen, rovně též ponese nepravost svou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 18, 'A přivede skopce bez poškvrny z drobného dobytka vedlé ceny tvé v obět za vinu k knězi. I očistí jej kněz od poblouzení jeho, kterýmž pobloudil a o němž nevěděl, a bude mu odpuštěno.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 19, 'Obět za provinění jest, nebo zavinil Hospodinu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 1, 'Mluvil opět Hospodin k Mojžíšovi, řka:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 2, 'Kdyby člověk zhřešil a přestoupením přestoupil proti Hospodinu, buď že by oklamal bližního svého v věci sobě svěřené, aneb v spolku nějakém, aneb mocí by vzal něco, aneb lstivě podvedl bližního svého,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 3, 'Buď že nalezna ztracenou věc, zapřel by mu ji, buď že by přisáhl falešně, kteroukoli věcí z těch, kterouž přihází se člověku učiniti a zhřešiti jí,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 4, 'Když by tedy zhřešil a vinen byl: navrátí zase tu věc, kterouž mocí sobě vzal, aneb tu, kteréž lstivě s útiskem dosáhl, aneb tu, kteráž mu svěřena byla, aneb ztracenou věc, kterouž nalezl,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 5, 'Aneb o kterékoli věci falešně přisáhl: tedy navrátí to z cela, a nad to pátý díl toho přidá tomu, číž bylo; to navrátí v den oběti za hřích svůj.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 6, 'Obět pak za hřích svůj přivede Hospodinu z drobného dobytku, skopce bez poškvrny, vedlé ceny tvé, v obět za vinu knězi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 7, 'I očistí jej kněz před Hospodinem, a odpuštěno mu bude, jedna každá z těch věcí, kterouž by učinil a jí vinen byl.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 8, 'I mluvil Hospodin k Mojžíšovi, řka:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 9, 'Přikaž Aronovi i synům jeho a rci: Tento bude řád při oběti zápalné: (slove pak obět zápalná od pálení na oltáři celou noc až do jitra, nebo oheň na oltáři vždycky hořeti bude,)');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 10, 'Obleče se kněz v roucho své lněné, a košilku lněnou vezme na tělo své, a vyhrabe popel, když oheň spálí obět zápalnou na oltáři, a vysype jej u oltáře.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 11, 'Potom svleče šaty své a obleče se v roucho jiné, a vynese popel ven z stanů na místo čisté.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 12, 'Oheň pak, kterýž jest na oltáři, bude hořeti na něm, nebude uhašován. A bude zapalovati jím kněz dříví každého jitra, a zpořádá na něm obět zápalnou, a páliti bude na něm tuk pokojných obětí.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 13, 'Oheň ustavičně hořeti bude na oltáři, a nebudeť uhašen.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 14, 'Tento pak bude řád při oběti suché, kterouž obětovati budou synové Aronovi Hospodinu u oltáře:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 15, 'Vezme hrst bělné mouky z oběti té a z oleje jejího, se vším tím kadidlem, kteréž bude na oběti suché, a páliti to bude na oltáři u vůni líbeznou, pamětné její Hospodinu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 16, 'Což pak zůstane z ní, to jísti budou Aron i synové jeho; přesné jísti se bude na místě svatém, v síni stánku úmluvy jísti to budou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 17, 'Nebude vařeno s kvasem, nebo jsem jim to dal za díl z obětí mých ohnivých; svaté svatých to jest, jako i obět za hřích a jako obět za vinu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 18, 'Každý mužského pohlaví z synů Aronových jísti bude to právem věčným po rodech vašich, z ohnivých obětí Hospodinových. Což by se koli dotklo toho, svaté bude.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 19, 'I mluvil Hospodin k Mojžíšovi, řka:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 20, 'Tato jest obět Aronova a synů jeho, kterouž obětovati budou Hospodinu v den pomazání jeho: Desátý díl míry efi mouky bělné za obět suchou ustavičnou, polovici toho ráno a polovici u večer.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 21, 'Na pánvici s olejem strojena bude; smaženou přineseš ji, a pečené kusy oběti suché obětovati budeš u vůni spokojující Hospodina.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 22, 'A kněz, kterýž z synů jeho po něm pomazán bude, ať ji obětuje právem věčným. Hospodinu všecko to páleno bude.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 23, 'A všeliká suchá obět kněžská celá spálena bude; nebudeť jedena.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 24, 'Mluvil pak Hospodin k Mojžíšovi, řka:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 25, 'Mluv Aronovi a synům jeho a rci: Tento bude řád oběti za hřích: Na místě, kdež se zabijí obět zápalná, zabita bude obět za hřích před Hospodinem; svatá svatých jest.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 26, 'Kněz obětující tu obět za hřích budeť jísti ji; na místě svatém jedena bude v síni stánku úmluvy.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 27, 'Což by se koli dotklo masa jejího, svaté bude; a jestliže by krví její šaty skropeny byly, to, což skropeno jest, obmyješ na místě svatém.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 28, 'A nádoba hliněná, v níž by vařeno bylo, rozražena bude; pakli by v nádobě měděné vařeno bylo, vytřena a vymyta bude vodou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 29, 'Všeliký pohlaví mužského mezi kněžími jísti to bude; svaté svatých jest.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 30, 'Ale žádná obět za hřích, (z jejížto krve něco vneseno bylo by do stánku úmluvy k očištění v svatyni,) nebude jedena; ohněm spálena bude.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 1, 'Tento pak bude řád oběti za provinění; svatá svatých jest.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 2, 'Na kterémž místě zabijí se obět zápalná, na témž zabijí i obět za vinu, a pokropí krví její oltáře svrchu vůkol.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 3, 'Všecken pak tuk její obětovati bude z ní, ocas i tuk střeva přikrývající.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 4, 'Též obě dvě ledvinky s tukem, kterýž jest na nich i na slabinách; a branici, kteráž jest na jatrách, s ledvinkami odejme.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 5, 'I bude páliti to kněz na oltáři v obět ohnivou Hospodinu; obět za provinění jest.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 6, 'Všeliký pohlaví mužského mezi kněžími jísti bude ji, na místě svatém jedena bude; svatá svatých jest.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 7, 'Jakož obět za hřích, tak obět za vinu, jednostejné právo míti budou; knězi, kterýž by ho očišťoval, přináležeti bude.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 8, 'Knězi pak, kterýž by něčí obět zápalnou obětoval, kůže té oběti zápalné, kterouž obětoval, přináležeti bude.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 9, 'Nadto všeliká obět suchá, kteráž v peci pečena bude, a všecko, což na pánvici aneb v kotlíku strojeno bude, knězi, kterýž to obětuje, přináležeti bude.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 10, 'Tolikéž všeliká obět suchá olejem zadělaná aneb upražená, všechněm synům Aronovým přináležeti bude, a to jednomu jako druhému.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 11, 'Tento pak bude řád oběti pokojné, kterouž by obětoval Hospodinu:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 12, 'Jestliže by ji obětoval v oběti chvály, tedy obětovati bude v obět chvály koláče nekvašené, olejem zadělané a oplatky nekvašené, olejem pomazané a mouku bělnou smaženou, s těmi koláči olejem zadělanými.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 13, 'Mimo ty koláče také chléb kvašený obětovati bude obět svou, v obět chvály pokojných obětí svých.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 14, 'A budeť obětovati z něho jeden pecník, ze vší té oběti Hospodinu obět ku pozdvižení, a ten přináležeti bude tomu knězi, kterýž kropil krví té oběti pokojné.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 15, 'Maso pak obět, z té oběti chvály, jenž jest obět pokojná, v den obětování jejího jedeno bude, aniž co zůstane z něho do jitra.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 16, 'Jestliže by pak z slibu aneb z dobré vůle obětoval obět svou, tolikéž v den obětování jejího jedena bude; a jestliže by co zůstalo z toho, tedy na druhý den jísti se bude.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 17, 'Jestliže by pak co masa z té oběti zůstalo do třetího dne, ohněm spáleno bude.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 18, 'Pakli by kdo předce jedl maso oběti pokojné dne třetího, nebudeť příjemný ten, kterýž ji obětoval, aniž přijata bude, ale ohavnost bude, a kdož by koli jedl je, ponese nepravost svou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 19, 'Též maso, kteréž by se dotklo něčeho nečistého, nebude jedeno, ale ohněm spáleno bude; maso pak jiné, kdož by koli čistý byl, bude moci jísti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 20, 'Nebo člověk, kterýž by jedl maso z oběti pokojné, kteráž jest Hospodinu obětována, a byl by poškvrněný: tedy vyhlazen bude člověk ten z lidu svého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 21, 'A kdož by se dotkl něčeho nečistého, buďto nečistoty člověka, buď hovada nečistého aneb všeliké ohavnosti nečisté, a jedl by maso z oběti pokojné, kteráž jest Hospodinu posvěcena: tedy vyhlazen bude člověk ten z lidu svého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 22, 'Mluvil také Hospodin k Mojžíšovi, řka:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 23, 'Mluv k synům Izraelským a rci jim: Žádného tuku z vola, aneb z ovce, aneb z kozy nebudete jísti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 24, 'Ačkoli tuk mrtvého a tuk udáveného hovada může užíván býti k všeliké potřebě, ale jísti ho nikoli nebudete.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 25, 'Nebo kdož by koli jedl tuk z hovada, kteréž obětovati bude člověk v obět ohnivou Hospodinu, vyhlazen bude člověk ten, kterýž jedl, z lidu svého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 26, 'Tolikéž krve žádné jísti nebudete ve všech příbytcích svých, buď z ptactva, buď z hovada.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 27, 'Všeliký člověk, kterýž by jedl jakou krev, vyhlazen bude z lidu svého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 28, 'Mluvil opět Hospodin k Mojžíšovi, řka:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 29, 'Mluv k synům Izraelským a rci: Kdož by obětoval obět svou pokojnou Hospodinu, on sám přinese obět svou Hospodinu z obětí pokojných svých.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 30, 'Ruce jeho obětovati budou obět ohnivou Hospodinu. Tuk s hrudím přinese, a hrudí aby bylo v obět sem i tam obracení před Hospodinem.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 31, 'Páliti pak bude kněz tuk na oltáři, ale hrudí to zůstane Aronovi i synům jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 32, 'A plece pravé dáte knězi ku pozdvižení z obětí pokojných vašich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 33, 'Kdožkoli z synů Aronových obětovati bude krev obětí pokojných a tuk, tomu se dostane plece pravé na díl jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 34, 'Nebo hrudí sem i tam obracení a plece vzhůru pozdvižení vzal jsem od synů Izraelských z obětí pokojných jejich, a dal jsem je Aronovi knězi i synům jeho právem věčným od synů Izraelských.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 35, 'Toť jest díl pomazání Aronova, a pomazání synů jeho z ohnivých obětí Hospodinových, ode dne toho, v kterémž jim přistoupiti rozkázal k vykonávání kněžství Hospodinu,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 36, 'Kterýž přikázal Hospodin, aby jim ode dne, v kterémž jich pomazal, dáván byl od synů Izraelských právem věčným po rodech jejich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 37, 'Tenť jest řád oběti zápalné, oběti suché, oběti za hřích, oběti za vinu, a posvěcování i obětí pokojných,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 38, 'Kteréž přikázal Hospodin Mojžíšovi na hoře Sinai toho dne, když přikázal synům Izraelským, aby obětovali oběti své Hospodinu na poušti Sinai.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 1, 'I mluvil Hospodin k Mojžíšovi, řka:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 2, 'Vezmi Arona a syny jeho s ním, i roucha jejich a olej pomazání, též volka k oběti za hřích, a dva skopce, a koš s přesnými chleby,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 3, 'A shromažď všecko množství ke dveřím stánku úmluvy.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 4, 'I učinil Mojžíš, jakž přikázal jemu Hospodin, a shromáždilo se všecko množství ke dveřím stánku úmluvy.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 5, 'Tedy řekl Mojžíš tomu množství: Totoť jest to slovo, kteréž přikázal vykonati Hospodin.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 6, 'A rozkázav přistoupiti Mojžíš Aronovi a synům jeho, umyl je vodou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 7, 'A oblékl jej v sukni a přepásal ho pasem, a oděv ho pláštěm, dal náramenník svrchu na něj, a připásal jej pasem náramenníka a otáhl ho jím.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 8, 'A vložil na něj náprsník, do něhožto dal urim a thumim.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 9, 'Potom vstavil čepici na hlavu jeho; a dal na čepici jeho po předu plech zlatý, korunu svatou, jakož přikázal Hospodin Mojžíšovi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 10, 'Vzal také Mojžíš olej pomazání a pomazal příbytku i všech věcí, kteréž byly v něm, a posvětil jich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 11, 'A pokropil jím oltáře sedmkrát, a pomazal oltáře i všeho nádobí jeho, též umyvadla i s podstavkem jeho, aby to všecko posvěceno bylo.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 12, 'Vlil také oleje pomazání na hlavu Aronovu, a pomazal ho ku posvěcení jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 13, 'Rozkázal také Mojžíš přistoupiti synům Aronovým, a zobláčel je v sukně, a opásal je pasem, a vstavil na ně klobouky, jakož byl přikázal Hospodin jemu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 14, 'A přivedl volka k oběti za hřích, i položil Aron a synové jeho ruce své na hlavu volka oběti za hřích.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 15, 'I zabil jej a vzal krev jeho, a pomazal rohů oltáře vůkol prstem svým, a tak očistil oltář. Ostatek pak krve vylil k spodku oltáře a posvětil ho k očišťování na něm.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 16, 'Vzal také všecken tuk, kterýž byl na střevách, a branici s jater a obě ledvinky i tuk jejich, a pálil to Mojžíš na oltáři.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 17, 'Volka pak toho i kůži jeho, i maso jeho, i lejna jeho spálil ohněm vně za stany, jakož byl přikázal Hospodin Mojžíšovi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 18, 'Potom přivedl skopce oběti zápalné, a položil Aron i synové jeho ruce své na hlavu toho skopce.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 19, 'I zabil jej, a pokropil Mojžíš krví oltáře po vrchu vůkol.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 20, 'Skopce také rozsekal na kusy jeho, a pálil Mojžíš hlavu, kusy i tuk.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 21, 'Střeva pak a nohy vymyl vodou, a tak spálil Mojžíš všeho skopce na oltáři. I byl zápal u vůni líbeznou, obět ohnivá Hospodinu, jakož přikázal Hospodin Mojžíšovi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 22, 'Rozkázal také přivésti skopce druhého, skopce posvěcení, a položil Aron i synové jeho ruce své na hlavu skopce.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 23, 'I zabil jej, a vzav Mojžíš krve jeho, pomazal jí konce pravého ucha Aronova a palce ruky jeho pravé, i palce nohy jeho pravé.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 24, 'Tolikéž synům Aronovým rozkázav přistoupiti, pomazal kraje ucha jejich pravého a palce ruky jejich pravé, též palce nohy jejich pravé, a vykropil krev na oltář svrchu vůkol.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 25, 'Potom vzal tuk a ocas i všecken tuk přikrývající droby a branici s jater, též obě dvě ledvinky i tuk jejich i plece pravé.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 26, 'Také z koše přesných chlebů, kteříž byli před Hospodinem, vzal jeden koláč přesný a jeden pecník chleba s olejem a jeden oplatek, a položil to s tukem a s plecem pravým.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 27, 'A dal to všecko v ruce Aronovy a v ruce synů jeho, rozkázav obraceti sem i tam v obět obracení před Hospodinem.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 28, 'Potom vzav z rukou jejich, pálil to na oltáři v zápal. Posvěcení toto jest u vůni rozkošnou, obět ohnivá Hospodinu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 29, 'Vzal také Mojžíš hrudí a obracel je sem i tam v obět obracení před Hospodinem; a z skopce posvěcení dostal se Mojžíšovi díl, jakož mu byl přikázal Hospodin.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 30, 'Vzal také Mojžíš oleje pomazání a krve, kteráž byla na oltáři, a pokropil Arona i roucha jeho, též synů Aronových a roucha jejich s ním. A tak posvětil Arona i roucha jeho, též synů jeho i roucha jejich s ním.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 31, 'I řekl Mojžíš Aronovi a synům jeho: Vařte to maso u dveří stánku úmluvy, a jezte je tu, i chléb, kterýž jest v koši posvěcení, jakož jsem přikázal, řka: Aron a synové jeho jísti budou je.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 32, 'Což by pak zůstalo masa i chleba toho, ohněm to spálíte.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 33, 'A ze dveří stánku úmluvy za sedm dní nevycházejte až do dne, v kterémž by se vyplnili dnové svěcení vašeho; nebo za sedm dní posvěcovány budou ruce vaše.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 34, 'Jakož se stalo dnešní den, tak přikázal Hospodin činiti k očištění vašemu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 35, 'Protož u dveří stánku úmluvy zůstanete ve dne i v noci za sedm dní, a ostříhati budete nařízení Hospodinova, abyste nezemřeli; nebo tak mi jest přikázáno.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 36, 'Učinil tedy Aron i synové jeho všecky věci, kteréž přikázal Hospodin skrze Mojžíše.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 1, 'Stalo se pak dne osmého, povolal Mojžíš Arona a synů jeho i starších Izraelských.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 2, 'I řekl Aronovi: Vezmi sobě tele k oběti za hřích, a skopce k oběti zápalné, obé bez poškvrny, a obětuj před Hospodinem.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 3, 'K synům pak Izraelským mluviti budeš, řka: Vezměte kozla k oběti za hřích, a tele a beránka, roční, bez vady, k oběti zápalné,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 4, 'Vola také a skopce k oběti pokojné, abyste obětovali před Hospodinem, a obět suchou zadělanou olejem; nebo dnes se vám ukáže Hospodin.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 5, 'Tedy vzali ty věci, kteréž přikázal Mojžíš před stánkem úmluvy, a přistoupivši všecko shromáždění, stáli před Hospodinem.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 6, 'I řekl Mojžíš: Toto jest ta věc, kterouž přikázal Hospodin. Vykonejtež ji, a ukáže se vám sláva Hospodinova.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 7, 'Aronovi pak řekl Mojžíš: Přistup k oltáři a obětuj obět za hřích svůj, a obět zápalnou svou k vykonání očištění za sebe i za lid tento; obětuj také obět lidu všeho, a učiň očištění za ně, jakož přikázal Hospodin.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 8, 'Přistoupiv tedy Aron k oltáři, zabil tele své k oběti za hřích.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 9, 'I dali mu synové Aronovi krev. Kterýžto omočiv prst svůj ve krvi, pomazal rohů oltáře, ostatek pak krve vylil k spodku oltáře.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 10, 'Ale tuk a ledvinky, i branici s jater té oběti za hřích pálil na oltáři, jakož byl přikázal Hospodin Mojžíšovi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 11, 'Maso pak s kůží spálil vně za stany.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 12, 'Zabil také obět zápalnou. I podali mu synové Aronovi krve, kterouž pokropil po vrchu oltáře vůkol.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 13, 'Podali jemu také i oběti zápalné s kusy jejími i hlavy její, a pálil ji na oltáři.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 14, 'A vymyv střeva i nohy její, pálil je s obětí zápalnou na oltáři.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 15, 'Obětoval také obět všeho lidu. A vzav kozla oběti za hřích, kterýž byl všeho lidu, zabil jej a obětoval ho za hřích jako i prvního.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 16, 'Obětoval též obět zápalnou a učinil ji vedlé obyčeje.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 17, 'Tolikéž i obět suchou obětoval, a vzav plnou hrst z ní, pálil to na oltáři, mimo obět zápalnou jitřní.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 18, 'Zabil ještě i vola a skopce k oběti pokojné, kteráž byla za lid. I podali mu synové Aronovi krve, kterouž pokropil oltáře po vrchu vůkol.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 19, 'Dali jemu také tuk z vola a z skopce ocas, a tuk přikrývající střeva i ledvinky a branici s jater.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 20, 'A položili všecken tuk na hrudí; i pálil ten tuk na oltáři.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 21, 'Hrudí pak a plece pravé obracel sem i tam Aron v obět obracení před Hospodinem, jakož byl přikázal Mojžíšovi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 22, 'Potom Aron pozdvihna rukou svých k lidu, dal jim požehnání, a sstoupil od obětování oběti za hřích a oběti zápalné i oběti pokojné.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 23, 'Tedy všel Mojžíš s Aronem do stánku úmluvy; a když vycházeli z něho, požehnání dávali lidu. I ukázala se sláva Hospodinova všemu lidu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 24, 'Nebo sstoupil oheň od tváři Hospodina, a spálil na oltáři obět zápalnou i všecken tuk. Což když uzřel veškeren lid, zkřikli a padli na tváři své.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 1, 'Synové pak Aronovi Nádab a Abiu, vzavše jeden každý kadidlnici svou, dali do nich oheň a položili na něj kadidlo, a obětovali před Hospodinem oheň cizí, čehož jim byl nepřikázal.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 2, 'Protož sstoupiv oheň od Hospodina, spálil je; a zemřeli tu před Hospodinem.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 3, 'I řekl Mojžíš Aronovi: Toť jest, což mluvil Hospodin, řka: V těch, kteříž přistupují ke mně, posvěcen budu, a před oblíčejem všeho lidu oslaven budu. I mlčel Aron.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 4, 'Tedy povolal Mojžíš Mizaele a Elizafana, synů Uziele, strýce Aronova, a řekl jim: Poďte a vyneste bratří své od svatyně ven za stany.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 5, 'I přišli a vynesli je v sukních jejich ven za stany, jakž byl rozkázal Mojžíš.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 6, 'Mluvil pak Mojžíš Aronovi, Eleazarovi a Itamarovi, synům jeho: Hlav svých neodkrývejte a roucha svého neroztrhujte, abyste nezemřeli, a aby se Bůh na všecko množství nerozhněval; ale bratří vaši, všecka rodina Izraelská, budou plakati nad tím spálením, kteréž uvedl Hospodin.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 7, 'Vy pak ze dveří stánku úmluvy nevycházejte, abyste nezemřeli; nebo olej pomazání Hospodinova jest na vás. I učinili vedlé rozkázaní Mojžíšova.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 8, 'Mluvil také Hospodin Aronovi, řka:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 9, 'Vína a nápoje opojného nebudeš píti, ty ani synové tvoji s tebou, kdyžkoli budete míti vcházeti do stánku úmluvy, abyste nezemřeli, (ustanovení věčné to bude po rodech vašich);');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 10, 'Také abyste rozeznati mohli mezi svatým a neposvěceným, a mezi čistým a nečistým;');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 11, 'Též abyste učili syny Izraelské všechněm ustanovením, kteráž mluvil Hospodin k nim skrze Mojžíše.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 12, 'Mluvil pak Mojžíš Aronovi, Eleazarovi a Itamarovi, synům jeho, kteříž živi zůstali: Vezměte obět suchou, kteráž zůstala z ohnivých obětí Hospodinových, a jezte ji s přesnicemi u oltáře; nebo svatá svatých jest.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 13, 'Protož jísti budete ji na místě svatém, nebo to jest právo tvé a právo synů tvých z ohnivých obětí Hospodinových; tak zajisté jest mi přikázáno.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 14, 'Hrudí pak sem i tam obracení, a plece vznášení jísti budete na místě čistém, ty i synové tvoji, i dcery tvé s tebou; nebo to právem tobě a synům tvým dáno jest z pokojných obětí synů Izraelských.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 15, 'Plece vzhůru vznášení a hrudí sem i tam obracení s obětmi ohnivými tuků, kteréž přinesou, aby sem i tam obracíno bylo, tak jako obět obracení před Hospodinem, bude tobě i synům tvým s tebou právem věčným, jakož přikázal Hospodin.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 16, 'Mojžíš pak hledal pilně kozla k oběti za hřích, a hle, již spálen byl. Tedy rozhněval se na Eleazara a Itamara, syny Aronovy pozůstalé, a řekl:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 17, 'Pročež jste nejedli oběti za hřích na místě svatém? Nebo svatá svatých byla, poněvadž ji dal vám, abyste nesli nepravost všeho množství k očištění jejich před Hospodinem.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 18, 'A hle, ani krev její není vnesena do vnitřku svatyně. Jísti jste měli ji v svatyni, jakož jsem byl přikázal.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 19, 'Tedy odpověděl Aron Mojžíšovi: Aj, dnes obětovali obět svou za hřích a obět svou zápalnou před Hospodinem, ale přihodila se mně taková věc, že, kdybych byl jedl obět za hřích dnes, zdali by se to líbilo Hospodinu?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 20, 'Což když uslyšel Mojžíš, přestal na tom.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 1, 'I mluvil Hospodin Mojžíšovi a Aronovi, řka jim:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 2, 'Mluvte k synům Izraelským, řkouce: Tito jsou živočichové, kteréž jísti budete ze všech hovad, kteráž jsou na zemi:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 3, 'Všeliké hovado, kteréž má kopyta rozdělená, tak aby rozdvojená byla, a přežívá, jísti budete.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 4, 'A však z těch, kteráž přežívají, a z těch, kteráž kopyta rozdělená mají, nebudete jísti, jako velblouda; nebo ač přežívá, ale kopyta rozděleného nemá, nečistý vám bude.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 5, 'Ani králíka, kterýž ač přežívá, ale kopyta rozděleného nemá, nečistý vám bude.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 6, 'Ani zajíce; nebo ač přežívá, ale kopyta rozděleného nemá, nečistý vám bude.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 7, 'Tolikéž ani svině; nebo ač má rozdělené kopyto, tak že se rozdvojuje, ale nepřežívá, nečistá bude vám.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 8, 'Masa jejich nebudete jísti, ani těla jejich mrtvého se dotýkati, nečistá budou vám.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 9, 'Ze všech pak živočichů, kteříž u vodách jsou, tyto jísti budete: Všecko, což má plejtvy a šupiny u vodách mořských i v řekách, jísti budete.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 10, 'Všecko pak, což nemá plejtví a šupin v moři i v řekách, buď jakýkoli hmyz vodný, aneb jakákoli duše živá u vodách, ohavností bude vám.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 11, 'A tak v ohavnosti vám budou, abyste masa jejich nejedli a těla jejich v ohyzdnosti měli.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 12, 'Což tedy nemá plejtví a šupin u vodách, to v ohavnosti míti budete.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 13, 'Z ptactva pak tyto v ohavnosti míti budete, jichžto nebudete jísti, nebo ohavnost jsou, jako jest orel, noh a orlice mořská,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 14, 'Též sup, káně a luňák vedlé pokolení svého,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 15, 'A všeliký krkavec vedlé pokolení svého,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 16, 'Také pstros, sova, vodní káně, a jestřáb vedlé pokolení svého,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 17, 'A bukač, křehař a kalous,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 18, 'A porfirián, pelikán a labut,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 19, 'Též čáp a kalandra vedlé pokolení svého, dedek a netopýř.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 20, 'Všeliký zeměplaz křídla mající, kterýž na čtyřech nohách chodí, v ohavnosti míti budete.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 21, 'A však ze všelikého zeměplazu křídla majícího, kterýž na čtyřech nohách chodí, jísti budete ty, kteříž mají stehénka na nohách svých, aby skákali na nich po zemi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 22, 'Titoť pak jsou, kteréž jísti budete: Arbes vedlé pokolení svého, sálem vedlé pokolení svého, chargol vedlé pokolení svého, a chagab vedlé pokolení svého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 23, 'Jiný pak zeměplaz všeliký křídla mající, kterýž na čtyřech nohách chodí, v ohavnosti míti budete.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 24, 'Nebo těmi byste se poškvrňovali. Protož kdož by se koli dotkl těla jich, nečistý bude až do večera.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 25, 'A kdož by koli nesl těla jich, zpéřeť roucho své a nečistý bude až do večera.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 26, 'Všeliké hovado, kteréž má rozdělené kopyto, ale není rozdvojené, a nepřežívá, nečisté vám bude. Kdož by koli jeho se dotekl, nečistý bude.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 27, 'A cožkoli chodí na tlapách svých ze všech hovad čtvernohých, nečisté bude vám. Kdož by koli dotkl se těl jejich, nečistý bude až do večera.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 28, 'A kdož by koli nesl těla jejich, zpéře roucha svá a nečistý bude až do večera; nebo nečistá jsou vám.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 29, 'Také i toto vám nečisté bude mezi zeměplazy, kteříž lezou po zemi: Kolčava a myš a žába, každé vedlé pokolení svého;');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 30, 'Též ježek a ještěrka, hlemejžď, štír a krtice.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 31, 'Tyto věci nečisté vám budou ze všelijakého zeměplazu. Kdož by se koli dotkl jich mrtvých, nečistý bude až do večera.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 32, 'A všeliká věc, na kterouž by padlo něco z těch již mrtvých těl, nečistá bude, buď nádoba dřevěná, neb roucho, neb kůže, aneb pytel. A všeliká nádoba, kteréž se k dílu nějakému užívá, do vody vložena bude a nečistá zůstane až do večera, potom čistá bude.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 33, 'Všeliká pak nádoba hliněná, do níž by něco toho upadlo, i což by koli v ní bylo, nečisté bude, ona pak rozražena bude.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 34, 'Všeliký také pokrm, jehož se užívá, jestliže by na něj voda vylita byla, nečistý bude; a všeliký nápoj ku pití příhodný v každé nádobě nečisté bude nečistý.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 35, 'A všecko, na čež by něco z těla jejich upadlo, nečisté bude. Pec a kotliště zbořeno bude, nebo nečisté jest; protož za nečisté je míti budete.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 36, 'Ale studnice a čisterna, i všeliké shromáždění vod, čistá budou; však což by se dotklo umrliny jejich, nečisté bude.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 37, 'Jestliže by pak něco z mrchy jejich upadlo na některé semeno, kteréž síti obyčej jest, čisté bude.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 38, 'Ale když by polito bylo vodou semeno, a potom padlo by něco z umrliny jejich na ně, nečisté bude vám.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 39, 'Jestliže by umřelo hovado z těch, kteráž vám jsou ku pokrmu, kdož by se koli mrchy jeho dotkl, nečistý bude až do večera.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 40, 'Kdo by jedl z těla toho, zpéřeť roucha svá a nečistý bude až do večera. Také i ten, kterýž by vynesl tu mrchu, zpéře roucha svá, a nečistý bude až do večera.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 41, 'Tolikéž všeliký zeměplaz, kterýž se plazí po zemi, v ohavnosti bude vám; nebudete ho jísti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 42, 'Ničeho, což se plazí na prsech, aneb cožkoli čtvermo leze, aneb více má noh, ze všeho zeměplazu, kterýž se plazí po zemi, nebudete jísti nebo jsou ohavnost.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 43, 'Nezohavujtež duší svých žádným zeměplazem, kterýž se plazí, a nepoškvrňujte se jimi, abyste nečistí nebyli učiněni skrze ně.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 44, 'Nebo já jsem Hospodin Bůh váš; protož posvěťtež se, a svatí buďte, nebo já svatý jsem, a nepoškvrňujte duší svých žádným zeměplazem, kterýž se plazí po zemi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 45, 'Nebo já jsem Hospodin, kterýž jsem vás vyvedl z země Egyptské, abych vám byl za Boha; protož svatí buďte, nebo já jsem svatý.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 46, 'Toť jest právo strany hovada, ptactva a všeliké duše živé, kteráž se hýbe u vodách, a každé duše živé, kteráž se plazí na zemi,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 47, 'Aby rozdíl činěn byl mezi nečistým a čistým, a mezi živočichy, kteříž se mají jísti, a mezi živočichy, kteříž se nemají jísti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 12, 1, 'I mluvil Hospodin k Mojžíšovi, řka:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 12, 2, 'Mluv synům Izraelským a rci: Žena počnuc, porodí-li pacholíka, nečistá bude za sedm dní; podlé počtu dnů, v nichž odděluje se pro nemoc svou, nečistá bude.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 12, 3, 'Potom dne osmého obřezáno bude tělo neobřízky jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 12, 4, 'Ona pak ještě za třidceti a tři dni zůstávati bude v očišťování se od krve. Nižádné věci svaté se nedotkne a k svatyni nepůjde, dokudž se nevyplní dnové očištění jejího.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 12, 5, 'Pakli děvečku porodí, nečistá bude za dvě neděle vedlé nečistoty oddělení svého, a šedesáte šest dní zůstávati bude v očištění od krve.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 12, 6, 'Když pak vyplní se dnové očištění jejího po synu aneb po dceři, přinese beránka ročního na obět zápalnou, a holoubátko aneb hrdličku na obět za hřích, ke dveřím stánku úmluvy, knězi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 12, 7, 'Kterýž obětovati ji bude před Hospodinem, a očistí ji, a tak očištěna bude od toku krve své. Ten jest zákon té, kteráž porodila pacholíka aneb děvečku.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 12, 8, 'Pakli nebude moci býti s beránka, tedy vezme dvé hrdličátek, aneb dvé holoubátek, jedno v obět zápalnou a druhé v obět za hřích. I očistí ji kněz, a tak čistá bude.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 1, 'Mluvil také Hospodin Mojžíšovi a Aronovi, řka:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 2, 'Člověk ješto by na kůži těla jeho byla nějaká oteklina aneb prašivina, aneb poškvrna pobělavá, a bylo by na kůži těla jeho něco podobného k ráně malomocenství: tedy přiveden bude k Aronovi knězi, aneb k některému z synů jeho kněží.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 3, 'I pohledí kněz na ránu, kteráž jest na kůži těla jeho. Jestliže chlupové na té ráně zbělejí, a ta rána bude-li na pohledění hlubší nežli jiná kůže těla jeho, rána malomocenství jest. Když tedy spatří ji kněz, za nečistého vyhlásí jej.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 4, 'Pakli by poškvrna pobělavá byla na kůži těla jeho, a rána ta nebyla by hlubší nežli jiná kůže, a chlupové její nezběleli by: tedy rozkáže zavříti kněz majícího takovou ránu za sedm dní.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 5, 'Potom pohledí na něj kněz v den sedmý, a jestli rána ta zůstává tak před očima jeho a nerozmáhá se po kůži: tedy rozkáže ho zavříti kněz po druhé za sedm dní.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 6, 'I pohledí na ni kněz v den sedmý po druhé, a jestliže ta rána pozčernalá bude, a nerozmohla by se po kůži: tedy za čistého vyhlásí ho kněz, nebo prašivina jest. I zpéře roucha svá a čistý bude.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 7, 'Pakliť by se dále rozmohla ta prašivina po kůži jeho, již po ukázání se knězi k očištění svému, tedy ukáže se znovu knězi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 8, 'I pohledí na něj kněz, a jestliže se rozmohla ta prašivina po kůži jeho, za nečistého vyhlásí jej kněz, nebo malomocenství jest.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 9, 'Rána malomocenství když bude na člověku, přiveden bude k knězi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 10, 'I pohledí na něj kněz, a bude-li oteklina bílá na kůži, až by učinila chlupy bílé, byť pak i zdravé maso bylo na té oteklině:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 11, 'Malomocenství zastaralé jest na kůži těla jeho. Protož za nečistého vyhlásí jej kněz, a nedá ho zavříti, nebo zjevně nečistý jest.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 12, 'Jestliže by se pak vylilo malomocenství po kůži, a přikrylo by malomocenství všecku kůži nemocného, od hlavy jeho až do noh jeho, všudy kdež by kněz očima viděti mohl:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 13, 'I pohledí na něj kněz, a přikrylo-li by malomocenství všecko tělo jeho, tedy za čistého vyhlásí nemocného. Nebo všecka ta rána v bělost se změnila, protož čistý jest.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 14, 'Ale kdykoli ukáže se na ní živé maso, nečistý bude.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 15, 'I pohledí kněz na to živé maso a vyhlásí jej za nečistého, nebo to maso živé nečisté jest, malomocenství jest.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 16, 'Když by pak odešlo zase maso živé a změnilo by se v bělost, tedy přijde k knězi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 17, 'A vida kněz, že obrátila se rána ta v bělost, za čistou vyhlásí ji; čistá jest.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 18, 'Když by pak byl na kůži těla vřed, a byl by zhojen,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 19, 'Byla-li by na místě vředu toho oteklina bílá, aneb poškvrna pobělavá a náryšavá, tedy ukázána bude knězi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 20, 'A vida kněz, že na pohledění to místo jest nižší nežli jiná kůže, a chlupové na něm by zběleli, za nečistého vyhlásí jej kněz. Rána malomocenství jest, kteráž na vředu vyrostla.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 21, 'Pakli, když pohledí na ni kněz, uzří, že chlupové nezběleli na něm, a není nižší nežli jiná kůže, ale že jest pozčernalé místo, tedy zavře ho kněz za sedm dní.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 22, 'Pakliť by šíře se rozmáhala po kůži, za nečistého vyhlásí jej kněz; rána malomocenství jest.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 23, 'Pakli by ta poškvrna pobělavá zůstávala na místě svém, a nerozmáhala by se, znamení toho vředu jest; protož za čistého vyhlásí jej kněz.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 24, 'Tělo, na jehož kůži byla by spálenina od ohně, a po zhojení té spáleniny zůstala by poškvrna pobělavá a náryšavá, anebo bílá toliko:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 25, 'Pohledí na ni kněz, a jestliže chlupové na ní zběleli, a lsknou se, způsob také její jest hlubší nežli jiné kůže vůkol: malomocenství jest, kteréž zrostlo na spálenině; protož za nečistého vyhlásí jej kněz, nebo rána malomocenství jest.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 26, 'Pakli uzří kněz, an na poškvrně pobělavé není žádného chlupu bílého, a že nižší není nežli jiná kůže, ale že jest pozčernalá, poručí ho zavříti kněz za sedm dní.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 27, 'I pohledí na ni kněz dne sedmého. Jestliže se více rozmohla po kůži, tedy za nečistého vyhlásí jej; nebo rána malomocenství jest.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 28, 'Pakli bělost lsknutá na svém místě zůstávati bude, a nerozmůže se po kůži, ale bude pozčernalá: zprýštění od spáleniny jest; za čistého vyhlásí jej kněz, nebo šrám spáleniny jest.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 29, 'Byla-li by pak rána na hlavě aneb na bradě muže neb ženy,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 30, 'Tedy pohledí kněz na tu ránu, a jestliže způsob její bude hlubší nežli jiná kůže, a bude na ní vlas prožlutlý a tenký: tedy za nečistého vyhlásí jej kněz, nebo poškvrna černá jest; malomocenství na hlavě aneb na bradě jest.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 31, 'Když pak pohledí kněz na ránu poškvrny černé a uzří, že způsob její není hlubší nežli jiná kůže, a že není vlasu černého na ní: zavříti dá kněz majícího ránu poškvrny černé za sedm dní.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 32, 'I pohledí kněz na tu ránu dne sedmého, a aj, nerozmohla se ta poškvrna černá, a není vlasu žlutého na ní, a způsob té poškvrny černé není hlubší nežli kůže:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 33, 'Tedy oholen bude člověk ten, ale poškvrny té černé nedá holiti. I dá zavříti kněz majícího tu poškvrnu za sedm dní po druhé.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 34, 'I pohledí kněz na poškvrnu černou dne sedmého, a jestliže se nerozmohla poškvrna černá dále po kůži, a místo její není-li hlubší nežli jiná kůže: za čistého vyhlásí ho kněz, i zpéře roucha svá a čistý bude.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 35, 'Pakli by se dále rozmohla poškvrna ta černá po kůži, již po očištění jeho,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 36, 'Tedy pohledí na ni kněz, a uzří-li, že se dále rozmohla ta poškvrna černá po kůži, nebude více šetřiti vlasu žlutého; nečistý jest.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 37, 'Pakli poškvrna černá tak zůstává před očima jeho, a černý vlas vzrostl by na ní, tedy zhojena jest ta poškvrna černá; čistý jest, a za čistého vyhlásí jej kněz.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 38, 'Když by na kůži těla muže aneb ženy byly poškvrny, totiž poškvrny pobělavé,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 39, 'I pohledí kněz, a jestliže budou na kůži těla jejich poškvrny bílé, pozčernalé, tedy poškvrna bílá jest, kteráž na kůži zrostla; čistý jest.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 40, 'Muž, z jehož by hlavy vlasové slezli, lysý jest a čistý jest.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 41, 'Jestliže pak po jedné straně obleze hlava jeho, nálysý jest a čistý jest.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 42, 'Pakli na té lysině, aneb na tom oblysení byla by rána bílá a ryšavá, tedy malomocenství zrostlo na lysině jeho, aneb na oblysení jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 43, 'I pohledí na něj kněz, a uzří-li oteklinu rány bílou a ryšavou na lysině jeho, aneb na oblysení jeho, jako způsob malomocenství na kůži těla:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 44, 'Člověk malomocný jest a nečistý jest. Bez meškání za nečistého vyhlásí jej kněz, nebo na hlavě jeho jest malomocenství jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 45, 'Malomocný pak, na němž by ta rána byla, bude míti roucho roztržené a hlavu odkrytou a ústa zastřená, a Nečistý, nečistý jsem! volati bude.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 46, 'Po všecky dny, v nichž ta rána bude na něm, za nečistého jmín bude; nebo nečistý jest. Sám bydliti bude, vně za stany bude přebývání jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 47, 'Když by pak na rouchu byla rána malomocenství, buď na rouchu soukenném aneb na rouchu lněném,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 48, 'Buď na osnově aneb na outku ze lnu aneb z vlny, buď na kůži aneb na každé věci kožené,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 49, 'A byla by ta rána zelená neb náryšavá na rouchu aneb na kůži, aneb na osnově, aneb na outku, aneb na kterékoli nádobě kožené: rána malomocenství jest, ukázána bude knězi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 50, 'I pohledí kněz na tu ránu, a dá zavříti tu věc mající ránu za sedm dní.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 51, 'A pohledě na tu ránu dne sedmého, uzří-li, že se dále rozmohla ta rána na rouchu, neb po osnově anebo po outku, aneb na kůži, k čemuž by jí koli užíváno bylo: rána ta malomocenství rozjídavá jest, věc nečistá jest.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 52, 'I spálí to roucho aneb osnovu, aneb outek z vlny neb ze lnu, aneb jakoukoli nádobu koženou, na níž by byla rána ta; nebo malomocenství škodlivé jest, protož ohněm spáleno bude.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 53, 'Pakli pohledě kněz, uzřel by, že se nerozmohla rána ta na rouchu, aneb na osnově, aneb na outku, aneb na kterékoli nádobě kožené:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 54, 'Rozkáže kněz, aby zeprali tu věc, na níž byla by rána, i káže ji zavříti za sedm dní po druhé.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 55, 'I pohledí kněz po zeprání té věci na ránu. Jestliže nezměnila rána barvy své, byť se pak nerozmohla dále, předce nečistá jest. Ohněm spálíš ji; nebo rozjídavá věc jest na vrchní neb spodní straně její.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 56, 'Pakli pohledě kněz, uzřel by, an pozčernala rána po zeprání svém, odtrhne ji od roucha aneb od kůže, aneb od osnovy, aneb od outku.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 57, 'Jestliže se pak ukáže ještě na rouchu aneb na osnově, aneb na outku, aneb na kterékoli nádobě kožené, malomocenství rozjídající se jest. Ohněm spálíš věc tu, na kteréž by ta rána byla.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 58, 'Roucho pak aneb osnovu, aneb outek, aneb kteroukoli nádobu koženou, když bys zepral, a odešla by od ní ta rána, ještě po druhé zpéřeš, a čisté bude.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 59, 'Tenť jest zákon o ráně malomocenství na rouchu soukenném aneb lněném, aneb na osnově, aneb na outku, aneb na kterékoli nádobě kožené, kterak má za čistou aneb za nečistou uznána býti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 1, 'I mluvil Hospodin k Mojžíšovi, řka:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 2, 'Tento bude řád při malomocném v den očišťování jeho: K knězi přiveden bude.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 3, 'I vyjde kněz ven z stanů a pohledí na něj, a uzří-li, že uzdravena jest rána malomocenství malomocného:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 4, 'Rozkáže kněz tomu, kterýž se očišťuje, vzíti dva vrabce živé a čisté, a dřevo cedrové, a červec dvakrát barvený, a yzop.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 5, 'I rozkáže kněz zabiti vrabce jednoho, a vycediti krev z něho do nádoby hliněné nad vodou živou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 6, 'A vezme vrabce živého a dřevo cedrové, též červec dvakrát barvený, a yzop, a omočí to všecko i s vrabcem živým ve krvi vrabce zabitého nad vodou živou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 7, 'Tedy pokropí toho, kterýž se očišťuje od malomocenství, sedmkrát, a za čistého jej vyhlásí, i pustí vrabce živého na pole.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 8, 'Ten pak, kterýž se očišťuje, zpéře roucho své a oholí všecky vlasy své, umyje se vodou, a čistý bude. Potom vejde do táboru, a bydliti bude vně, nevcházeje do stanu svého za sedm dní.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 9, 'Dne pak sedmého sholí všecky vlasy své, hlavu i bradu svou, i obočí své, a tak všecky vlasy své sholí; zpéře také roucha svá a tělo své umyje vodou, a tak očistí se.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 10, 'Dne pak osmého vezme dva beránky bez poškvrny, a ovci jednu roční bez poškvrny, a tři desetiny efi mouky bělné k oběti suché, olejem zadělané, a oleje jednu mírku.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 11, 'Kněz pak, kterýž očišťuje, postaví toho člověka očišťujícího se s těmi věcmi před Hospodinem u dveří stánku úmluvy.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 12, 'I vezme kněz beránka jednoho, kteréhožto obětovati bude v obět za hřích, a mírku oleje, a obraceti bude tím sem i tam v obět obracení před Hospodinem.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 13, 'A zabije beránka toho na místě, kdež se zabijí obět za hřích a obět zápalná, totiž na místě svatém; nebo jakož obět za hřích, tak obět za vinu knězi přináleží, svatá svatých jest.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 14, 'I vezme kněz krve z oběti za hřích, a pomaže jí kraje ucha pravého člověka toho, kterýž se očišťuje, a palce ruky jeho pravé, a palce nohy jeho pravé.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 15, 'Vezme také kněz z té mírky oleje, a naleje na ruku svou levou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 16, 'A omoče prst svůj pravý v tom oleji, kterýž má na ruce své levé, pokropí z něho prstem svým sedmkrát před Hospodinem.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 17, 'Z ostatku pak oleje toho, kterýž má na ruce své, pomaže kněz kraje ucha pravého člověka toho, kterýž se očišťuje, a palce pravé ruky jeho, a palce pravé nohy jeho, na krev oběti za vinu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 18, 'Což pak zůstane oleje, kterýž jest v ruce kněze, pomaže tím hlavy toho, kterýž se očišťuje; a tak očistí jej kněz před Hospodinem.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 19, 'Učiní také kněz obět za hřích, a očistí očišťujícího se od nečistoty jeho. A potom zabije obět zápalnou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 20, 'I bude obětovati kněz tu obět zápalnou, i obět suchou na oltáři; a tak očistí jej, i bude čistý.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 21, 'Jestliže pak bude chudý, tak že by s to býti nemohl, tedy vezme jednoho beránka v obět za provinění, k obracení jí sem i tam pro očištění své, a desátý díl mouky bělné olejem zadělané k oběti suché, a mírku oleje,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 22, 'Též dvě hrdličky aneb dvé holoubátek, kteréž by mohl míti, a bude jedno v obět za hřích, a druhé v obět zápalnou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 23, 'I přinese je v osmý den očišťování svého knězi, ke dveřům stánku úmluvy před Hospodina.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 24, 'Tedy kněz vezma beránka oběti za vinu a mírku oleje, obraceti je bude sem i tam v obět obracení před Hospodinem.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 25, 'I zabije beránka oběti za provinění, a vezma krve z oběti za provinění, pomaže jí kraje ucha pravého člověka toho, kterýž se očišťuje, a palce ruky jeho pravé, a palce nohy jeho pravé.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 26, 'Oleje také naleje kněz na ruku svou levou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 27, 'A omoče prst svůj pravý v oleji, kterýž bude na ruce jeho levé, pokropí jím sedmkrát před Hospodinem.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 28, 'Pomaže také kněz olejem, kterýž má na ruce své, kraje ucha pravého toho, kdož se čistí, a palce pravé ruky jeho, a palce pravé nohy jeho, na místě krve z oběti za vinu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 29, 'Což pak zůstává oleje, kterýž jest v ruce kněze, pomaže jím hlavy toho, kterýž se očišťuje; a tak očistí jej před Hospodinem.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 30, 'Tolikéž učiní i s hrdličkou jednou aneb s holoubátkem z těch, kteréž zjednati mohl.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 31, 'Z těch, kterýchž dostati mohl, obětovati bude jedno za hřích a druhé v obět zápalnou s obětí suchou; a tak očistí kněz očišťujícího se před Hospodinem.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 32, 'Ten jest zákon toho, na komž by se ukázala rána malomocenství, a kterýž by nemohl býti s ty věci k očištění svému přináležité.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 33, 'I mluvil Hospodin Mojžíšovi a Aronovi, řka:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 34, 'Když vejdete do země Kananejské, kterouž já vám za dědictví dávám, a dopustil bych ránu malomocenství na některý dům země, kterouž vládnouti budete,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 35, 'Tedy přijde hospodář domu a oznámí knězi řka: Zdá mi se, jako by byla rána malomocenství na domě.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 36, 'I rozkáže kněz vyprázdniti dům, dříve než by všel do něho hleděti na tu ránu, aby nebylo poškvrněno něco z těch věcí, kteréž v domě jsou. Potom pak vejde, aby pohleděl na ten dům.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 37, 'Tedy vida ránu tu, uzří-li, že rána jest na stěnách domu, totiž důlkové názelení aneb náčervení, a na pohledění jsou nižší než stěna jinde:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 38, 'Vyjde kněz z domu toho ke dveřím jeho, a dá zavříti dům ten za sedm dní.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 39, 'A v den sedmý navrátí se kněz, a uzří-li, ano se rozmohla rána na stěnách domu toho:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 40, 'Rozkáže vyníti kamení, na němž by rána taková byla, a vyvrci je ven za město na místo nečisté.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 41, 'Dům pak rozkáže vystrouhati vnitř všudy vůkol; a vysypou prach ten, kterýž sstrouhali, vně za městem na místo nečisté.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 42, 'A vezmouce jiné kamení, vyplní jím místo onoho kamení; tolikéž hliny jiné vezmouce, vymaží dům.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 43, 'Pakliť by se navrátila rána, a vzrostla by v tom domě po vyvržení kamení a vystrouhání domu, i po vymazání jeho,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 44, 'Tedy vejda kněz, uzří-li, an se rozmohla rána v domě, malomocenství rozjídající se jest v tom domě, nečistý jest.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 45, 'I rozboří ten dům a kamení jeho, i dříví jeho, a všecko mazání domu toho, a vynosí ven za město na místo nečisté.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 46, 'Jestliže by pak kdo všel do domu toho v ten čas, když zavřín byl, nečistý bude až do večera.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 47, 'A jestliže by kdo spal v tom domě, zpéře roucha svá; tolikéž jestliže by kdo jedl v tom domě, zpéře roucha svá.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 48, 'Jestliže by pak kněz vejda tam, uzřel, že se nerozmohla rána v domě po obnovení jeho, tedy za čistý vyhlásí dům ten; nebo uzdravena jest rána jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 49, 'A vezma k očištění domu toho dva vrabce a dřevo cedrové, a červec dvakrát barvený a yzop,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 50, 'I zabije vrabce jednoho, a vycedí krev do nádoby hliněné nad vodou živou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 51, 'A vezme dřevo cedrové a yzop, a červec dvakrát barvený, a vrabce živého, omočí to všecko ve krvi vrabce zabitého a u vodě živé, a pokropí domu toho sedmkrát.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 52, 'A tak když očistí dům ten krví vrabce a vodou živou a ptákem živým, dřevem cedrovým, yzopem a červcem dvakrát barveným:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 53, 'Vypustí ven vrabce živého z města na pole, a očistí dům ten, i budeť čistý.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 54, 'Ten jest zákon o všeliké ráně malomocenství a poškvrny černé,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 55, 'A malomocenství roucha i domu,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 56, 'I otekliny, prašiviny a poškvrny pobělavé,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 57, 'K ukázání, kdy jest kdo čistý, aneb kdy jest kdo nečistý. Tenť jest zákon malomocenství.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 1, 'Mluvil pak Hospodin Mojžíšovi a Aronovi, řka:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 2, 'Mluvte synům Izraelským a rcete jim: Když by který muž trpěl tok semene z těla svého, nečistý bude.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 3, 'Tato pak bude nečistota jeho v toku jeho: Jestliže vypěňuje tělo jeho tok svůj, aneb že by se zastavil tok v těle jeho, nečistota jeho jest.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 4, 'Každé lůže, na němž by ležel, kdož má tok semene, nečisté bude; a všecko, na čemž by seděl, nečisté bude.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 5, 'A kdož by se dotekl lůže jeho, zpéře roucha svá, a umyje se vodou, a bude nečistý až do večera.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 6, 'A kdo by sedl na to, na čemž seděl ten, kdož má tok semene, zpéře roucha svá, a umyje se vodou, i bude nečistý až do večera.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 7, 'Jestliže by se kdo dotekl těla trpícího tok semene, zpéře roucha svá, a umyje se vodou, i bude nečistý až do večera.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 8, 'A jestliže by ten, kdož trpí tok semene, plinul na čistého, zpéře roucha svá, a umyje se vodou, i bude nečistý až do večera.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 9, 'Každé sedlo, na němž by seděl ten, kdož má tok semene, nečisté bude.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 10, 'A kdož by koli dotekl se něčeho, což bylo pod ním, nečistý bude až do večera; a kdož by co z toho nesl, zpéře roucha svá, a umyje se vodou, a bude nečistý až do večera.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 11, 'Kohož by se pak dotekl ten, kdož má tok semene, a neumyl rukou svých vodou, zpéře roucha svá, a umyje se vodou, i bude nečistý až do večera.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 12, 'Nádoba hliněná, kteréž by se dotekl ten, kdo má tok semene, bude rozbita, a každá nádoba dřevěná vodou vymyta bude.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 13, 'Když by pak očištěn byl ten, kdož tok semene trpěl, od toku svého, sečte sedm dní po svém očištění, a zpéře roucha svá, a vodou živou zmyje tělo své, i bude čist.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 14, 'Potom dne osmého vezme sobě dvě hrdličky aneb dvé holoubátek, a přijda před Hospodina ke dveřím stánku úmluvy, dá je knězi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 15, 'Kterýž obětovati je bude, jedno za hřích a druhé v obět zápalnou; a očistí jej kněz před Hospodinem od toku jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 16, 'Muž, z něhož by vyšlo símě scházení, zmyje vodou všecko tělo své, a bude nečistý až do večera.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 17, 'Každé roucho i každá kůže, na níž by bylo símě scházení, zeprána bude vodou, a nečistá bude až do večera.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 18, 'Žena také, s kterouž by obýval muž scházením semene, oba zmyjí se vodou, a nečistí budou až do večera.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 19, 'Žena pak, když by trpěla nemoc svou, a tok krve byl by z těla jejího, za sedm dní oddělena bude; každý, kdož by se jí dotekl, nečistý bude až do večera.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 20, 'Na čemž by koli ležela v čas oddělení svého, nečistéť bude; tolikéž, na čem by koli seděla, nečisté bude.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 21, 'Také kdož by se dotekl lůže jejího, zpéře roucho své, a umyje se vodou, i bude nečistý až do večera.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 22, 'Kdož by se koli dotekl toho, na čemž seděla, zpéře roucha svá, a umyje se vodou, i bude nečistý až do večera.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 23, 'Což by koli bylo na lůži tom, neb na jaké by koli věci seděla, a dotekl by se toho někdo, nečistý bude až do večera.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 24, 'Jestliže by kdo spal s ní, a byla by nečistota její na něm, nečistý bude za sedm dní; i každé lůže, na němž by spal, nečisté bude.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 25, 'Žena pak trpěla-li by krvotok po mnohé dny, kromě času nemoci své, totiž krvotok by trpěla přes čas přirozené nemoci: po všecky dny toku nečistoty své, jako i v čas nemoci své přirozené, nečistá bude.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 26, 'Každé lůže, na němž by spala po všecky dny toku svého, bude jí jako lůže v přirozené nemoci její; a každá věc, na kteréž by seděla, nečistá bude, podlé nečistoty přirozené nemoci její.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 27, 'Kdož by koli dotekl se těch věcí, nečistý bude. Protož zpéře roucho své, a umyje se vodou, i bude nečistý až do večera.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 28, 'Když pak očištěna bude od toku svého, sečte sobě sedm dní, a potom očišťovati se bude.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 29, 'A v den osmý vezme sobě dvě hrdličky aneb dvé holoubátek, a přinese je knězi ke dveřím stánku úmluvy.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 30, 'Z nichž jedno obětovati bude kněz v obět za hřích, a druhé v obět zápalnou, a očistí ji kněz před Hospodinem od toku nečistoty její.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 31, 'I budete oddělovati syny Izraelské od nečistot jejich, aby nezemřeli pro nečistoty své, když by poškvrnili příbytku mého, kterýž jest u prostřed nich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 32, 'Toť jest právo trpícího tok semene, i toho, z něhož vychází símě scházení, jímž poškvrněn bývá,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 33, 'Též nemocné ženy v oddělení jejím, i všelikého trpícího tok svůj, buď mužského pohlaví neb ženského, a muže, kterýž by spal s nečistou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 1, 'Mluvil pak Hospodin k Mojžíšovi po smrti dvou synů Aronových, kteřížto, když předstoupili před Hospodina, zemřeli,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 2, 'A řekl Hospodin Mojžíšovi: Mluv Aronovi bratru svému, ať nevchází každého času do svatyně za oponu před slitovnici, kteráž jest na truhle, aby neumřel; nebo já v oblace ukáži se nad slitovnicí.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 3, 'S tímto vcházeti bude Aron do svatyně: S volkem mladým, kterýž bude v obět za hřích, a s beranem k oběti zápalné.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 4, 'V sukni lněnou svatou obleče se, a košilku lněnou bude míti na těle hanby své, pasem také lněným opáše se, a čepici lněnou vstaví na hlavu, roucha zajisté svatá jsou tato; i umyje vodou tělo své a obleče se v ně.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 5, 'Od shromáždění pak synů Izraelských vezme dva kozly k oběti za hřích, a jednoho berana k zápalné oběti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 6, 'I bude obětovati Aron volka svého v obět za hřích, a očistí sebe i dům svůj.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 7, 'Potom vezme ty dva kozly a postaví je před Hospodinem u dveří stánku úmluvy.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 8, 'I dá Aron na ty dva kozly losy, los jeden Hospodinu, a los druhý Azazel.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 9, 'A obětovati bude Aron kozla toho, na něhož by los padl Hospodinu, obětovati jej bude za hřích.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 10, 'Kozla pak toho, na něhož přišel los Azazel, postaví živého před Hospodinem, aby skrze něho učinil očištění, a pustí ho na poušť k Azazel.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 11, 'I bude obětovati Aron volka svého v obět za hřích, a očistí sebe i dům svůj, a zabije volka svého v obět za hřích.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 12, 'Vezme také plnou kadidlnici uhlí řeřavého s oltáře, kterýž jest před tváří Hospodinovou, a plné obě hrsti své vonných věcí stlučených, a vnese za oponu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 13, 'A vloží kadidlo to na oheň před Hospodinem, a dým kadění toho přikryje slitovnici, kteráž jest nad svědectvím, a neumře.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 14, 'Potom vezma krve volka toho, pokropí prstem svým na slitovnici k východu; tolikéž před slitovnicí kropiti bude sedmkrát krví tou prstem svým.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 15, 'Zabije také v obět za hřích kozla toho, kterýž jest lidu, a vnese krev jeho do vnitřku za oponu, a učiní se krví jeho, jakož učinil se krví volka, totiž pokropí jí na slitovnici a před slitovnicí.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 16, 'A očistí svatyni od nečistot synů Izraelských a od přestoupení jejich i všech hříchů jejich. Totéž učiní i stánku úmluvy, kterýž jest mezi nimi u prostřed nečistot jejich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 17, '(Žádný pak člověk ať není v stánku úmluvy, když on vchází k očišťování do svatyně, dokudž by on zase nevyšel a očištění za sebe, za dům svůj i za všecko množství Izraelské nevykonal.)');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 18, 'Vyjde pak k oltáři, kterýž jest před Hospodinem, a očistí jej. A vezma krve volka toho, a ze krve kozla, dá na rohy oltáře vůkol.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 19, 'A pokropí ho svrchu krví tou prstem svým sedmkrát, a očistí jej i posvětí ho od nečistot synů Izraelských.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 20, 'A když by dokonal očištění svatyně a stánku úmluvy a oltáře, obětovati bude kozla živého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 21, 'A vlože Aron obě ruce své na hlavu kozla živého, vyznávati bude nad ním všecky nepravosti synů Izraelských, a všecka přestoupení jejich se všemi hříchy jejich, a vloží je na hlavu kozla, a vyžene ho člověk k tomu zřízený na poušť.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 22, '(Kozel ten zajisté ponese na sobě všecky nepravosti jejich do země pusté.) A pustí kozla toho na poušti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 23, 'Potom pak přijda Aron do stánku úmluvy, svleče s sebe roucha lněná, v něž se byl oblékl, když vjíti měl do svatyně, a nechá jich tu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 24, 'A umyje tělo své vodou na místě svatém, a obleče se zase v roucha svá, a vyjda, obětovati bude obět zápalnou svou a obět zápalnou lidu, a očistí sebe i lid.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 25, 'A tuk oběti za hřích páliti bude na oltáři.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 26, 'Ten pak, kterýž vyvedl kozla na Azazel, zpéře roucha svá, a zmyje tělo své vodou, a potom vejde do stanů.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 27, 'Volka pak za hřích a kozla za hřích, jejichž krev vnesena byla k vykonání očištění v svatyni, vynese ven z táboru, a spálí ohněm kůže jejich, i maso jejich, i lejna jejich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 28, 'Kdož by pak spálil je, zpéře roucha svá, a umyje tělo své vodou, a potom vejde do táboru.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 29, 'Bude vám i toto za věčné ustanovení: Sedmého měsíce, desátého dne téhož měsíce ponižovati budete duší svých, a žádného díla nebudete dělati, ani doma zrozený, ani příchozí, kterýž jest pohostinu mezi vámi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 30, 'Nebo v ten den očistí vás, abyste očištěni byli; ode všech hříchů svých před Hospodinem očištěni budete.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 31, 'Sobota odpočinutí bude vám, a ponižovati budete duší svých ustanovením věčným.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 32, 'Očišťovati pak bude kněz, kterýž jest pomazaný, a jehož ruce posvěceny jsou k vykonávání úřadu kněžského místo otce svého, a obleče se v roucha lněná, roucha svatá.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 33, 'A očistí svatyni svatou a stánek úmluvy, očistí také i oltář, i kněží, i všecken lid shromážděný očistí.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 34, 'A bude vám to ustanovením věčným k očišťování synů Izraelských ode všech hříchů jejich, každého roku jednou. I učinil Mojžíš tak, jakž jemu byl přikázal Hospodin.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 1, 'I mluvil Hospodin Mojžíšovi, řka:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 2, 'Mluv k Aronovi a synům jeho i ke všechněm synům Izraelským, a rci jim: Tato jest věc, kterouž přikázal Hospodin, řka:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 3, 'Kdož by koli z domu Izraelského zabil vola aneb beránka, neb kozu, buď mezi stany, aneb kdož by zabil vně za stany,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 4, 'A ke dveřím stánku úmluvy nepřivedl by ho, aby obětoval obět Hospodinu před příbytkem Hospodinovým: vinen bude krví, nebo krev vylil; protož vyhlazen bude muž ten z prostředku lidu svého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 5, 'Přivedou tedy synové Izraelští oběti své, kteréž by na poli zabíjeti chtěli, přivedou je, pravím, k Hospodinu ke dveřím stánku úmluvy, k knězi, a obětovati budou oběti pokojné Hospodinu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 6, 'A pokropí kněz krví na oltáři Hospodinovu u dveří stánku úmluvy, a páliti bude tuk u vůni líbeznou Hospodinu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 7, 'A nikoli více nebudou obětovati obětí svých ďáblům, po nichžto odcházejíce, oni smilní. Zákon tento bude jim věčný i všechněm potomkům jejich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 8, 'Protož povíš jim: Kdož by koli z domu Izraelského aneb z příchozích, kteříž by pohostinu byli mezi vámi, obětoval zápal aneb jinou obět,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 9, 'A ke dveřím stánku úmluvy nepřivedl by jí, aby ji obětoval Hospodinu: tedy vyhlazen bude člověk ten z lidu svého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 10, 'A kdož by koli z domu Izraelského aneb z příchozích, kteříž jsou pohostinu mezi nimi, jedl jakou krev: postavím tvář svou proti člověku tomu, a vyhladím jej z prostředku lidu jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 11, 'Nebo duše všelikého těla ve krvi jest, já pak oddal jsem vám ji k oltáři, k očišťování duší vašich. Nebo sama krev na duši očišťuje.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 12, 'Protož řekl jsem synům Izraelským: Nižádný z vás nebude jísti krve; ani příchozí, kterýž pohostinu jest mezi vámi, nebude krve jísti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 13, 'A kdož by koli z synů Izraelských aneb z příchozích, kteříž jsou pohostinu mezi vámi, honě, ulovil zvíře aneb ptáka, což se jísti může, tedy vycedí krev jeho a zasype ji prstí.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 14, 'Nebo duše všelikého těla jest krev jeho, kteráž jest v duši jeho. Protož jsem pověděl synům Izraelským: Krve žádného těla jísti nebudete, nebo duše všelikého těla jest krev jeho; kdož by koli jedl ji, vyhlazen bude.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 15, 'Kdož by pak koli jedl tělo mrtvé aneb udávené, buď on doma zrozený aneb příchozí: zpéře roucha svá, a umyje se vodou, a nečistý bude až do večera, potom pak čistý bude.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 16, 'A pakli nezpéře roucha svého, a těla svého neumyje, tedy ponese nepravost svou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 1, 'I mluvil Hospodin k Mojžíšovi, řka:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 2, 'Mluv synům Izraelským a rci jim: Já jsem Hospodin Bůh váš.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 3, 'Vedlé skutků země Egyptské, v níž jste bydlili, nečiňte, ani podlé skutků země Kananejské, do kteréž já vás uvozuji, činiti budete, a v ustanoveních jejich nechoďte.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 4, 'Soudy mé čiňte a ustanovení mých ostříhejte, abyste chodili v nich: Já jsem Hospodin Bůh váš.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 5, 'Ostříhejte ustanovení mých a soudů mých. Člověk ten, kterýž by je činil, živ bude v nich: Já jsem Hospodin.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 6, 'Nižádný člověk k žádné přítelkyni krevní nepřistupuj k obnažení hanby její: Já jsem Hospodin.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 7, 'Hanby otce svého a matky své neodkryješ; matka tvá jest, neodkryješ hanby její.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 8, 'Hanby ženy otce svého neodkryješ; nebo hanba otce tvého jest.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 9, 'Hanby sestry své, dcery otce svého aneb dcery matky své, kteráž doma zplozena aneb vně zplozena jest, neodkryješ hanby jejich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 10, 'Hanby vnučky své, buď po synu neb dceři své, neodkryješ; nebo hanba tvá jsou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 11, 'Hanby dcery manželky otce svého, kteráž jest zplozena od otce tvého, tvá sestra jest, neodkryješ hanby její.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 12, 'Hanby sestry otce svého neodkryješ; nebo krevní přítelkyně otce tvého jest.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 13, 'Hanby sestry matky své neodkryješ; nebo krevní přítelkyně matky tvé jest.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 14, 'Hanby bratra otce svého neodkryješ; k manželce jeho nevejdeš, stryna tvá jest.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 15, 'Hanby nevěsty své neodkryješ; manželka jest syna tvého, neodkryješ hanby její.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 16, 'Hanby manželky bratra svého neodkryješ; nebo hanba bratra tvého jest.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 17, 'Hanby ženy a dcery její neodkryješ. Vnučky její po synu neb po dceři její nepojmeš, abys odkryl hanbu její; nebo krevní jsou, a nešlechetnost jest.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 18, 'Nevezmeš sobě ženy k ženě první, abys ssoužil ji, odkrývaje hanbu její za života jejího.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 19, 'Také k ženě, když jest v své nemoci nečisté, nepřistoupíš, odkrývaje hanbu její.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 20, 'S manželkou bližního svého nebudeš obcovati, poškvrňuje se s ní.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 21, 'Nedopustíš, aby kdo z semene tvého proveden byl skrze oheň modly Moloch, abys nepoškvrnil jména Boha svého: Já jsem Hospodin.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 22, 'Nebudeš obcovati s mužským pohlavím, scházeje se s ním jako s ženou; nebo ohavnost jest.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 23, 'A s žádným hovadem nebudeš obcovati, poškvrňuje se s ním; ani žena nepoddá se hovadu, aby s ním obývala; nebo mrzkost jest.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 24, 'A protož nepoškvrňujtež se žádnou touto věcí; nebo těmito všemi věcmi poškvrnili se pohané, kteréž já vyvrhu od tváři vaší.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 25, 'Nebo poškvrnila se země, a navštívím nepravost její na ní, a vyvrátí země obyvatele své.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 26, 'Ale vy ostříhejte ustanovení mých a soudů mých, a nečiňte nižádných ohavností těchto, tak domácí jako příchozí, kterýž jest pohostinu u prostřed vás.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 27, '(Nebo všecky ty ohavnosti činili lidé země té, kteříž byli před vámi, čímž poškvrněna jest země.)');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 28, 'Aby nevyvrátila vás země, proto že byste jí poškvrnili, jako vyvrátila národ, kterýž byl před vámi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 29, 'Nebo kdož by koli dopustil se některé ze všech ohavností těch: duše zajisté, kteréž by činily to, vyhlazeny budou z prostředku lidu svého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 30, 'Protož ostříhejte přikázaní mých, abyste nečinili ničeho z obyčejů ohavných, kteříž činěni jsou před vámi, aniž sebe jimi poškvrňujte: Já jsem Hospodin Bůh váš.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 1, 'I mluvil Hospodin k Mojžíšovi, řka:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 2, 'Mluv ke všemu množství synů Izraelských a rci jim: Svatí buďte, nebo svatý jsem, já Hospodin Bůh váš.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 3, 'Jeden každý matky své a otce svého báti se budete. A sobot mých ostříhejte, nebo já jsem Hospodin Bůh váš.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 4, 'Neobracejte se k modlám, a bohů litých nedělejte sobě: Já jsem Hospodin Bůh váš.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 5, 'A když obětovati budete oběti pokojné Hospodinu, z dobré vůle své obětovati budete je.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 6, 'Kterého dne obětovati budete, jísti budete je, i nazejtří; což by pak zůstalo až do třetího dne, ohněm spáleno bude.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 7, 'Pakli předce jísti budete dne třetího, věc ohavná bude, a nebude oblíbena.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 8, 'Kdož by to jedl, pokutu nepravosti své ponese; nebo svatosti Hospodinovy poškvrnil, protož vyhlazena bude duše ta z lidu svého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 9, 'Když budete žíti obilé země vaší, nesežneš naskrze všeho pole svého, a nebudeš sbírati pozůstalých klasů žně své.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 10, 'Tolikéž ostatků vinice své nebudeš bráti, a zrní vinice své nebudeš sbírati; chudému a příchozímu zanecháš toho: Já jsem Hospodin Bůh váš.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 11, 'Nekraďte a nelžete, a nižádný neoklamávej bližního svého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 12, 'Nepřisahejte křivě ve jméno mé, aniž kdo poškvrňuj jména Boha svého: Já jsem Hospodin.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 13, 'Neutiskneš mocí bližního svého, aniž obloupíš ho. Nezůstane mzda dělníka u tebe až do jitra.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 14, 'Hluchému nebudeš zlořečiti, a před slepým nepoložíš úrazu, ale báti se budeš Boha svého, nebo já jsem Hospodin.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 15, 'Neučiníš neprávě v soudu. Nepřijmeš osoby chudého, aniž šanovati budeš osoby bohatého; spravedlivě souditi budeš bližního svého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 16, 'Nebudeš choditi jako utrhač v lidu svém, aniž státi budeš na hrdlo bližnímu svému: Já jsem Hospodin.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 17, 'Nebudeš nenáviděti bratra svého v srdci svém; svobodně potresceš bližního svého, a nesneseš na něm hříchu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 18, 'Nebudeš se mstíti, aniž držeti budeš hněvu proti synům lidu svého, ale milovati budeš bližního svého jako sebe samého: Já jsem Hospodin.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 19, 'Ustanovení mých ostříhejte. Hovadu svému nedáš se scházeti s hovadem jiného pokolení. Pole svého neposeješ rozdílným semenem, a rouchem z rozdílných věcí, jako z vlny a ze lnu, setkaným nebudeš se odívati.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 20, 'Jestliže by muž spal s ženou, a obcoval s ní, kteráž děvkou jsuc, byla by zasnoubená jinému muži, a nebyla by žádnou mzdou vykoupena, ani propuštěna: oba dva zmrskáni budou, a neumrouť; nebo nebyla svobodná učiněna.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 21, 'On pak přivede obět za vinu svou Hospodinu ke dveřím stánku úmluvy, skopce za vinu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 22, 'I očistí jej kněz skopcem, kterýž se obětuje za vinu před Hospodinem, od hříchů jeho, kterýmž zhřešil, a bude mu odpuštěn hřích jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 23, 'Když pak vejdete do země, a nasázíte všelikého stromoví ovoce nesoucího, tedy obřežete neobřezání jeho, totiž ovoce jeho. Po tři léta budete míti je za neobřezané, protož nebude jedeno.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 24, 'Čtvrtého pak léta bude všeliké ovoce jeho posvěcené k chválení Hospodina,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 25, '(Pátého teprv léta jísti budete ovoce jeho), aby rozmnožil vám úrody jeho; nebo já jsem Hospodin Bůh váš.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 26, 'Nic nebudete jísti se krví. Nebudete hádati, aniž na časích zakládati budete.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 27, 'Nebudeš střihati vlasů hlavy své okrouhle, aniž zohaví kdo brady své.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 28, 'Nad mrtvým pak nebudete řezati těla svého, a žádného znamení vyrytého na sobě neučiníte: Já jsem Hospodin.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 29, 'Nepoškvrňuj dcery své, dopouštěje smilniti jí, aby země nesmilnila a nebyla naplněna nešlechetností.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 30, 'Sobot mých ostříhati budete, a svatyně mé báti se budete: Já jsem Hospodin.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 31, 'Neobracejte se k hadačům a věšťcům, ani od nich rady beřte, poškvrňujíce se s nimi: Já jsem Hospodin Bůh váš.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 32, 'Před člověkem šedivým povstaň, a cti osobu starého, a boj se Boha svého, nebo já jsem Hospodin.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 33, 'Jestliže bude pohostinu u tebe příchozí v zemi vaší, nečiňte jemu křivdy.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 34, 'Jakožto jeden z doma zrozených vašich, tak bude vám příchozí, kterýž jest u vás pohostinu, a milovati ho budeš jako sebe samého; nebo i vy pohostinu jste byli v zemi Egyptské: Já jsem Hospodin Bůh váš.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 35, 'Nečiňte neprávě v soudu, v rozměřování, v váze a v míře.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 36, 'Závaží spravedlivé, kámen spravedlivý, korec spravedlivý, pintu spravedlivou míti budete: Já jsem Hospodin Bůh váš, kterýž jsem vás vyvedl z země Egyptské.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 37, 'Protož ostříhejte všech ustanovení mých a všech soudů mých, a čiňte je, nebo já jsem Hospodin.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 1, 'Mluvil pak Hospodin k Mojžíšovi, řka:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 2, 'Synům také Izraelským díš: Kdo by koli z synů Izraelských a z příchozích, kteříž by byli pohostinu v Izraeli, dal z semene svého modle Moloch, smrtí umře. Lid země té kamením jej uhází.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 3, 'Nebo já postavím tvář svou proti takovému, a vyhladím ho z prostředku lidu jeho, proto že z semene svého dal modle Moloch, a tak zprznil svatyni mou, a poškvrnil jména svatosti mé.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 4, 'Jestliže by pak lid země té všelijak přehlídal to na člověku tom, kterýž by dal z semene svého modle Moloch, a nezahubil by ho:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 5, 'Tedy já postavím tvář svou proti muži tomu a proti čeledi jeho, a vyhladím ho i všecky, kteříž smilníce, odcházeli po něm, aby smilnili, následujíce Molocha, z prostředku lidu jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 6, 'Duše, kteráž by se obrátila k hadačům a věšťcům, aby smilnila, postupujíc po nich: postavím tvář svou proti duši té, a vyhladím ji z prostředku lidu jejího.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 7, 'A protož posvěťte se a buďte svatí, nebo já jsem Hospodin Bůh váš.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 8, 'A ostříhejte ustanovení mých, a čiňte je: Já jsem Hospodin posvětitel váš.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 9, 'Kdož by koli zlořečil otci svému neb matce své, smrtí umře. Otci svému a matce své zlořečil, krev jeho bude na něm.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 10, 'Muž pak, kterýž by se cizoložství dopustil s ženou něčí, že zcizoložil s ženou bližního svého, smrtí umře cizoložník ten i cizoložnice.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 11, 'A kdož by koli obcoval s ženou otce svého, hanbu otce svého odkryl. Smrtí umrou oba dva, krev jejich bude na ně.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 12, 'Kdož by pak obcoval s nevěstou svou, smrtí umrou oba dva. Mrzkosti se dopustili, krev jejich bude na ně.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 13, 'A kdož by se scházel s pohlavím mužským jako s ženou, ohavnost učinili oba dva. Smrtí umrou, krev jejich bude na ně.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 14, 'A kdož by vzal ženu a matku její, nešlechetnost jest. Ohněm spálí i jej i je, aby nebylo nešlechetností u prostřed vás.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 15, 'Kdož by pak obcoval s hovadem, smrtí umře, a hovado zabijete.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 16, 'Tolikéž žena, kteráž by přistoupila k některému hovadu, aby obcovala s ním, zabiješ ji i to hovado. Smrtí umrou, krev jejich bude na ně.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 17, 'Kdož by koli vezma sestru svou, dceru otce svého, aneb dceru matky své, viděl by hanbu její, a ona také viděla by hanbu jeho, mrzkost jest. Protož vyhlazeni budou před očima synů lidu svého; nebo hanbu sestry své odkryl, nepravost svou ponese.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 18, 'A kdož by koli spal s ženou v její nemoci a obnažil by hanbu její, a tok její by odkryl, i ona ukázala by krvotok svůj: vyhlazeni budou oba z prostředku lidu svého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 19, 'Hanby sestry matky své a sestry otce svého neodkryješ. Nebo kdož by to učinil, krevní přítelkyni svou by obnažil; protož nepravost svou ponesou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 20, 'Kdož by pak spal s ženou strýce svého, hanbu strýce svého odkryl. Ponesou hřích svůj, bez dětí zemrou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 21, 'Tolikéž kdož by vzal manželku bratra svého, mrzkost jest. Hanbu bratra svého obnažil, protož bez dětí budou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 22, 'Ostříhejtež tedy všech ustanovení mých a všech soudů mých, a čiňte je, aby nevyvrátila vás země, do níž já uvozuji vás, abyste v ní bydlili.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 23, 'Aniž choďte v ustanoveních národu toho, kterýž já vyvrhu od tváři vaší; nebo všecky ty věci činili, a měl jsem je v ošklivosti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 24, 'Vám jsem pak řekl: Vládnouti budete zemí jejich, a já dám ji vám, abyste ji dědičně obdrželi, zemi tekoucí mlékem a strdí. Já jsem Hospodin Bůh váš, kterýž jsem vás oddělil od jiných národů.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 25, 'Protož vy mějte rozdíl mezi hovadem čistým a nečistým, a mezi ptákem čistým a nečistým, a nepoškvrňujte duší svých hovady a ptactvem, a tím vším, což se plazí po zemi, kteréž jsem já vám oddělil, abyste je měli za nečisté.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 26, 'Ale budete mi svatí; nebo svatý jsem já Hospodin, a oddělil jsem vás od jiných národů, abyste byli moji.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 27, 'Muž pak neb žena, kteříž by měli ducha čarodějného a věštího, smrtí umrou. Kamením uházejí je, krev jejich bude na ně.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 1, 'Řekl také Hospodin Mojžíšovi: Mluv kněžím synům Aronovým a rci jim: Při mrtvém nepoškvrní se žádný z vás v lidu svém.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 2, 'Toliko při krevním příteli svém, mateři neb otci svém, synu neb dceři své a bratru svém,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 3, 'Též při sestře své, panně sobě nejbližší, kteráž neměla muže, při té poškvrní se.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 4, 'Nepoškvrní se při knížeti lidu svého, tak aby nečistý byl.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 5, 'Nebudou dělati sobě lysiny na hlavě své, vytrhávajíce sobě vlasy. A brady své nebudou holiti, ani těla svého řezati.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 6, 'Budou svatí Bohu svému, aniž poškvrní jména Boha svého; nebo oběti ohnivé Hospodinovy, chléb Boha svého obětují, protož svatí budou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 7, 'Ženy nevěstky aneb poškvrněné nevezmou sobě, a ženy zahnané od muže jejího nepojmou; nebo svatý jest jeden každý z nich Bohu svému.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 8, 'Ty také, lide, za svatého budeš jej míti, nebo chléb Boha tvého obětuje. Protož svatý bude tobě, nebo já svatý jsem Hospodin, kterýž posvěcuji vás.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 9, 'Dcera pak některého kněze, když by se smilství dopustila, otce svého poškvrnila. Ohněm spálena buď.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 10, 'Kněz pak nejvyšší mezi bratřími svými, na jehožto hlavu vylit jest olej pomazání, a posvětil rukou svých, aby obláčel se v roucho svaté, hlavy své neodkryje a roucha svého neroztrhne.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 11, 'Aniž k kterému tělu mrtvému přistoupí, a aniž při otci aneb mateři své poškvrní se.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 12, 'Nevyjde z svatyně a nepoškvrní svatyně Boha svého; nebo koruna oleje pomazání Boha jeho jest na něm: Já jsem Hospodin.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 13, 'On také ženu v panenství jejím za manželku sobě pojme.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 14, 'Vdovy, aneb zahnané, aneb poškvrněné, nevěstky, žádné z těch nebude sobě bráti, ale pannu z lidu svého vezme sobě za manželku.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 15, 'A nepoškvrní semene svého v rodu svém, nebo já jsem Hospodin posvětitel jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 16, 'Mluvil opět Hospodin Mojžíšovi, řka:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 17, 'Mluv k Aronovi a rci: Kdožkoli z semene tvého po všech rodech svých bude míti na sobě vadu, nechť nepřistupuje, aby obětoval chléb Boha svého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 18, 'Nebo žádný muž, kterýž by měl na sobě vadu, nemá přistupovati: Muž slepý, aneb kulhavý, aneb mající oud některý příliš malý, aneb příliš veliký,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 19, 'Aneb muž, kterýž by měl zlámanou nohu, aneb zlámanou ruku,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 20, 'Aneb hrbovatý, aneb krhavý, aneb kterýž má bělmo na oku svém, aneb prašivost ustavičnou, neb lišeje, aneb stlačené lůno.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 21, 'Nižádný muž, kterýž by měl na sobě nějakou vadu, z semene Arona kněze, nepřistoupí, aby obětoval oběti ohnivé Hospodinu; nebo vada na něm jest. Nepřistoupíť, aby obětoval chléb Boha svého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 22, 'Chléb však Boha svého z věcí svatosvatých a z věcí svatých jísti bude.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 23, 'Ale za oponu nebude vcházeti a k oltáři nebude přistupovati, nebo vada jest na něm, aby nepoškvrnil svatyně mé; nebo já jsem Hospodin posvětitel jejich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 24, 'Ta slova mluvil Mojžíš k Aronovi a k synům jeho, i ke všechněm synům Izraelským.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 1, 'I mluvil Hospodin k Mojžíšovi, řka:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 2, 'Mluv Aronovi a synům jeho, ať se zdržují od věcí těch, kteréž jsou posvěceny od synů Izraelských, a ať nepoškvrňují jména svatého mého v tom, což mi oni posvěcují: Já jsem Hospodin.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 3, 'Rci jim: Kdo by koli ze všeho semene vašeho v pronárodech vašich přistoupil ku posvěceným věcem, kterýchž by posvětili synové Izraelští Hospodinu, když nečistota jeho na něm jest, vyhlazena bude duše ta od tváři mé: Já jsem Hospodin.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 4, 'Kdo by koli z semene Aronova byl malomocný, aneb tok semene trpící, nebude jísti z věcí posvěcených, dokavadž by se neočistil. A kdož by se koli dotekl nečistoty těla mrtvého, aneb toho, z něhož by vyšlo símě scházení,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 5, 'Aneb kdo by se dotkl kterého zeměplazu, jímž by se poškvrnil, aneb člověka, pro něhož by byl nečistý vedlé všelijaké nečistoty jeho:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 6, 'Člověk, kterýž by se čehokoli toho dotekl, nečistý bude až do večera, a nebude jísti z věcí posvěcených, leč by umyl tělo své vodou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 7, 'A po západu slunce čistý bude, a potom bude moci jísti z věcí posvěcených, nebo pokrm jeho jest.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 8, 'Mrchy a udáveného jísti nebude, aby se tím nepoškvrnil: Já jsem, Hospodin.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 9, 'Protož ostříhati budou přisluhování mých, aby hříchů na se neuvedli, a nezemřeli v něm, proto že je zprznili: Jáť jsem Hospodin posvětitel jejich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 10, 'Žádný cizí nebude jísti z věcí posvěcených, ani podruh kněžský, ani nájemník nebude jísti věcí posvěcených.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 11, 'Koupil-li by kněz člověka za své peníze, ten jísti bude z věcí těch, též v domě jeho zplozený; ti budou jísti z pokrmu jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 12, 'Ale dcera knězova, kteráž by se vdala za muže z jiného pokolení, ta z obětí vzhůru pozdvižených, totiž věcí svatých, nebude jísti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 13, 'Kdyby pak dcera knězova ovdověla, aneb zahnána byla od muže, nemající plodu, a navrátila by se do domu otce svého: tak jako v dětinství svém chléb otce svého jísti bude, cizí pak žádný nebude jísti z něho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 14, 'Jedl-li by pak kdo z nedopatření věci posvěcené, pátý díl nad to přidá knězi, a nahradí jemu tu věc posvěcenou,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 15, 'Aby nepoškvrňovali věcí svatých, kteréž by synové Izraelští obětovali Hospodinu,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 16, 'A neuvozovali na ně pokuty za provinění, že jedli věci posvěcené jejich; nebo já jsem Hospodin, kterýž jich posvěcuji.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 17, 'Dále mluvil Hospodin Mojžíšovi, řka:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 18, 'Mluv k Aronovi a k synům jeho i ke všechněm synům Izraelským, a rci jim: Kdož by koli z domu Izraelského aneb z pohostinných, kteříž jsou v Izraeli, obětovali obět svou vedlé všech slibů svých, vedlé všech darů dobrovolných svých, kteréž by obětovali Hospodinu v obět zápalnou:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 19, 'Z dobré vůle své obětovati budete samce bez poškvrny, z skotů, z ovcí a z koz.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 20, 'Což by koli mělo na sobě vadu, nebudete toho obětovati; nebo nebude příjemné od vás.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 21, 'Pakli by kdo obětoval obět pokojnou Hospodinu, vykonávaje slib svůj, aneb dobrovolný dar, buď z skotů, aneb z bravů: ať jest bez vady, aby bylo příjemné; nebudeť žádné poškvrny na něm.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 22, 'Slepého aneb polámaného, osekaného aneb uhřivého, prašivého aneb s lišeji, takového neobětujte Hospodinu a nedávejte jich k ohnivé oběti na oltář Hospodinův.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 23, 'Vola neb dobytče s nedorostlými neb přerostlými oudy, v dobrovolný zajisté dar obětovati je budeš, ale za slib nebude příjemný.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 24, 'Ztlačeného aneb ztlučeného, odtrženého, vykleštěného nebudete obětovati Hospodinu; neučiníte toho v zemi vaší.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 25, 'A z ruky cizozemce nebudete obětovati chleba Bohu svému ze všech těch věcí, nebo porušení jejich jest na nich; vadu mají, nebudou příjemné od vás.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 26, 'Mluvil také Hospodin k Mojžíšovi, řka:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 27, 'Vůl neb beran, aneb koza, když se urodí, za sedm dní při matce své zanecháno bude, osmého pak dne i potom bude příjemné k oběti ohnivé Hospodinu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 28, 'Krávy pak a dobytčete s mladým jeho nezabijete jednoho dne.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 29, 'A když byste obětovali obět chvály Hospodinu, dobrovolně ji obětovati budete.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 30, 'V tentýž den snědena bude a nepozůstavíte z ní ničeho až do jitra: Já jsem Hospodin.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 31, 'Protož ostříhejte přikázaní mých a čiňte je: Já jsem Hospodin.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 32, 'A nepoškvrňujte jména svatého mého, i buduť posvěcen u prostřed synů Izraelských: Já jsem Hospodin posvětitel váš,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 33, 'Kterýž jsem vás vyvedl z země Egyptské, abych vám byl za Boha: Já jsem Hospodin.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 1, 'Mluvil opět Hospodin Mojžíšovi, řka:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 2, 'Mluv k synům Izraelským a rci jim: Slavnosti Hospodinovy, kteréž nazývati budete shromáždění svatá, tyto jsou slavnosti mé:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 3, 'Šest dní dělati budete, dne pak sedmého sobota odpočinutí jest, shromáždění svaté bude. Žádného díla nedělejte, nebo jest sobota Hospodinova, ve všech příbytcích vašich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 4, 'Protož tyto jsou slavnosti Hospodinovy, shromáždění svatá, kteréž slaviti budete v časy jich určité:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 5, 'Měsíce prvního, čtrnáctého dne téhož měsíce u večer bude Fáze Hospodinovo.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 6, 'A patnáctého dne téhož měsíce svátek přesnic bude Hospodinu; za sedm dní přesné chleby jísti budete.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 7, 'Dne prvního sbor svatý míti budete; žádného díla robotného nebudete dělati.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 8, 'Ale obětovati budete obět ohnivou Hospodinu za sedm dní. Dne také sedmého sbor svatý bude; žádného díla robotného nebudete dělati.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 9, 'I mluvil Hospodin k Mojžíšovi, řka:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 10, 'Mluv k synům Izraelským a rci jim: Když vejdete do země, kterouž já dávám vám, a žíti budete obilí její, tedy přinesete snopek prvotiny žně vaší k knězi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 11, 'Kterýž obraceti bude sem i tam snopek ten před Hospodinem, aby byl příjemnou obětí za vás; nazejtří po sobotě obraceti jej bude kněz.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 12, 'Kterého dne obraceti budete snopek ten, téhož zabijete beránka ročního bez poškvrny v obět zápalnou Hospodinu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 13, 'Též i obět suchou jeho, dvě desetiny mouky bělné olejem zadělané, v obět ohnivou Hospodinu u vůni příjemnou, a mokrou obět jeho, vína čtvrtý díl míry hin.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 14, 'Chleba pak, ani pražmy, ani zrní vymnutého nebudete jísti, až právě do toho dne, když obětovati budete obět Bohu svému. Ustanovení to věčné bude v pronárodech vašich, ve všech příbytcích vašich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 15, 'Počtete sobě také od prvního dne po sobotě, ode dne, v němž jste obětovali snopek sem i tam obracení, (plných sedm téhodnů ať jest),');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 16, 'Až do prvního dne po sedmém téhodni, sečtete padesáte dní, a tehdy obětovati budete novou obět suchou Hospodinu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 17, 'Z příbytků svých přinesete chleby sem i tam obracení, dva bochníky ze dvou desetin mouky bělné budou; kvašené je upečete, prvotiny jsou Hospodinu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 18, 'A s tím chlebem obětovati budete sedm beránků ročních bez vady, a volka mladého jednoho, a skopce dva; obět zápalná budou Hospodinu, s obětmi svými suchými i mokrými, obět ohnivá vůně spokojující Hospodina.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 19, 'Zabijete také kozla jednoho za hřích, a dva beránky roční k oběti pokojné.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 20, 'I bude je kněz sem i tam obraceti s chleby prvotin v obět sem i tam obracení před Hospodinem, i s těmi dvěma beránky; a budou svaté věci Hospodinu, a dostanou se knězi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 21, 'I vyhlásíte v ten den slavnost, shromáždění svaté míti budete, žádného díla robotného nebudete dělati. Ustanovení to bude věčné ve všech příbytcích vašich, v pronárodech vašich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 22, 'A když budete žíti obilé krajiny vaší, nesežneš všeho až do konce pole svého, a pozůstalých klasů po žni své nebudeš sbírati; chudému a příchozímu zanecháš jich: Já jsem Hospodin Bůh váš.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 23, 'Mluvil ještě Hospodin k Mojžíšovi, řka:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 24, 'Mluv synům Izraelským takto: Měsíce sedmého, v první den téhož měsíce, budete míti odpočinutí, památku troubení, shromáždění svaté držíce.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 25, 'Žádného díla robotného nebudete dělati, a budete obětovati obět ohnivou Hospodinu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 26, 'Mluvil také Hospodin k Mojžíšovi, řka:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 27, 'Desátý pak den každého měsíce sedmého den očišťování jest. Shromáždění svaté míti budete, a ponižovati budete životů svých, a obětovati obět ohnivou Hospodinu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 28, 'Žádného díla nebudete dělati v ten den; nebo den očišťování jest, k očišťování vás před Hospodinem Bohem vaším.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 29, 'A všeliká duše, kteráž by neponižovala se toho dne, vyhlazena bude z lidu svého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 30, 'Kdož by koli dílo nějaké dělal toho dne, zatratím člověka toho z lidu jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 31, 'Žádného díla nedělejte. Ustanovení to bude věčné v pronárodech vašich, ve všech příbytcích vašich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 32, 'Sobotu odpočinutí míti budete, když ponižovati budete duší svých, devátého dne téhož měsíce u večer; od večera až do druhého večera držeti budete sobotu svou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 33, 'Mluvil také Hospodin k Mojžíšovi, řka:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 34, 'Mluv synům Izraelským a rci: Každého patnáctého dne měsíce sedmého slavnost stánků za sedm dní bude Hospodinu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 35, 'Dne prvního shromáždění svaté bude; žádného díla robotného nebudete dělati.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 36, 'Za sedm dní obětovati budete obět ohnivou Hospodinu. Dne osmého shromáždění svaté míti budete, a obětovati budete obět ohnivou Hospodinu; svátek jest, žádného díla robotného nebudete dělati.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 37, 'To jsou slavnosti Hospodinovy, kteréž slaviti budete, mívajíce shromáždění svatá, abyste v nich obětovali obět ohnivou Hospodinu, zápal, obět suchou, obět pokojnou, a oběti mokré, jedno každé ve dni svém,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 38, 'Kromě sobot Hospodinových, a kromě darů vašich, i všech slibů vašich a kromě všech dobrovolných obětí vašich, kteréž dávati budete Hospodinu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 39, 'A však dne patnáctého toho měsíce sedmého, když byste shromáždili úrody země, světiti budete svátek Hospodinův za sedm dní. Dne prvního odpočinutí bude, tolikéž dne osmého bude odpočinutí.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 40, 'A naberouce sobě dne prvního ovoce z stromů krásných, a ratolestí palmových, a větvoví z stromů hustých, a vrbí od potoku, veseliti se budete před Hospodinem Bohem svým za sedm dní.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 41, 'A tak držeti budete ten svátek Hospodinův za sedm dní každého roku. Ustanovení to bude věčné v pronárodech vašich; každého měsíce sedmého slaviti jej budete.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 42, 'V staních zůstanete za sedm dní. Kdožkoli doma zrozený jest v Izraeli, v staních zůstávati budete,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 43, 'Aby věděli potomci vaši, že jsem choval v staních syny Izraelské, když jsem je vyvedl z země Egyptské: Já Hospodin Bůh váš.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 44, 'I oznámil Mojžíš slavnosti Hospodinovy synům Izraelským.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 1, 'Mluvil pak Hospodin k Mojžíšovi, řka:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 2, 'Přikaž synům Izraelským, ať přinesou tobě oleje olivového, čistého, vytlačeného, k svícení, aby lampy ustavičně rozsvěcovány byly.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 3, 'Před oponou svědectví v stánku úmluvy zpořádá je Aron, aby hořely od večera až do jitra před Hospodinem vždycky. Toť bude ustanovení věčné v národech vašich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 4, 'Na svícen čistý rozstavovati bude lampy před Hospodinem vždycky.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 5, 'A vezma mouky bělné, upečeš z ní dvanácte koláčů; jeden každý koláč bude ze dvou desetin efi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 6, 'A rozkladeš je dvěma řady, šest v řadu jednom, na stole čistém před Hospodinem.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 7, 'Dáš také na každý řad kadidla čistého, aby bylo za každý chléb ten kouření pamětné v obět ohnivou Hospodinu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 8, 'Každého dne sobotního klásti budete je řadem před Hospodinem vždycky, berouce je od synů Izraelských smlouvou věčnou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 9, 'I budou Aronovi a synům jeho, kteřížto jísti budou je na místě svatém; nebo nejsvětější věc jest jim z obětí ohnivých Hospodinových právem věčným.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 10, 'Vyšel pak syn ženy Izraelské, kteréhož měla s mužem Egyptským, mezi syny Izraelskými, a vadili se v staních syn ženy té Izraelské s mužem Izraelským.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 11, 'I zlořečil syn ženy té Izraelské a rouhal se jménu Božímu. Tedy přivedli ho k Mojžíšovi. (Jméno pak matky jeho bylo Salumit, dcera Dabri, z pokolení Dan.)');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 12, 'A dali jej do vězení, až by jim bylo oznámeno, co s ním Bůh káže učiniti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 13, 'Mluvil pak Hospodin k Mojžíšovi, řka:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 14, 'Vyveď toho ruhače ven z stanů, a nechať všickni ti, kteříž slyšeli, vloží ruce na hlavu jeho, a všecken lid ať ho ukamenuje.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 15, 'Mluvě pak k synům Izraelským, díš jim: Kdož by koli zlořečil Bohu svému, poneseť hřích svůj.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 16, 'Kdož by zlořečil jménu Hospodinovu, smrtí umře, a všecko shromáždění bez milosti ukamenuje jej. Tak cizí, jako doma zchovaný, když by zlořečil jménu Hospodinovu, smrtí umře.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 17, 'Zabil-li by kdo kterého člověka, smrtí umře.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 18, 'Jestliže by pak zabil hovado, navrátí jiné, hovado za hovado.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 19, 'Kdož by pak zohavil bližního svého, vedlé toho, jakž on učinil, tak se staň jemu:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 20, 'Zlámaní za zlámaní, oko za oko, zub za zub. Jakouž by ohavu učinil na těle člověka, taková zase učiněna bude jemu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 21, 'Kdož by zabil hovado, navrátí jiné, ale kdož by zabil člověka, umře.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 22, 'Jednostejné právo míti budete. Jakož příchozímu, tak domácímu stane se; nebo já jsem Hospodin Bůh váš.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 23, 'Tedy mluvil Mojžíš k synům Izraelským ty věci. I vyvedli toho ruhače ven za stany, a kamením ho zametali. Učinili, pravím, synové Izraelští vedlé toho, jakož přikázal Hospodin Mojžíšovi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 1, 'Mluvil ještě Hospodin k Mojžíšovi na hoře Sinai, řka:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 2, 'Mluv synům Izraelským a rci jim: Když vejdete do země, kterouž já dávám vám, odpočívati bude země, nebo sobota jest Hospodinova.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 3, 'Šest let osívati budeš rolí svou, a šest let obřezovati budeš vinici svou a sbírati úrody její.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 4, 'Sedmého pak léta sobotu odpočinutí bude míti země, sobotu Hospodinovu; nebudeš na poli svém síti a vinice své řezati.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 5, 'Což se samo od sebe zrodí obilí tvého, nebudeš toho žíti, a hroznů vinice zanechané od tebe nebudeš sbírati. Rok odpočinutí bude míti země.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 6, 'Ale ovoce země toho odpočinutí budete míti ku pokrmu, ty i služebník tvůj, i děvka tvá, i nájemník tvůj, i příchozí tvůj, kterýž bydlí u tebe,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 7, 'I hovado tvé, i všeliký živočich, kterýž jest v zemi tvé, všecky úrody její budou míti ku pokrmu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 8, 'Sečteš také sobě sedm téhodnů let, totiž sedmkrát sedm let, tak aby čas sedmi téhodnů let učinil tobě čtyřidceti devět let.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 9, 'Tedy dáš troubiti trubou veselé všudy sedmého měsíce v desátý den; v den očišťování dáš troubiti trubou po vší zemi vaší.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 10, 'I posvětíte léta padesátého, a vyhlásíte svobodu v zemi té všechněm obyvatelům jejím. Léto milostivé toto míti budete, abyste se navrátili jeden každý k statku svému, a jeden každý k čeledi své zase přijde.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 11, 'Ten rok milostivý padesátého léta míti budete; nebudete síti, ani žíti toho, což by samo od sebe vzrostlo, ani sbírati vína opuštěných vinic léta toho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 12, 'Nebo milostivé léto jest, protož za svaté je míti budete; ze všelikého pole jísti budete úrody jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 13, 'Toho léta milostivého navrátí se jeden každý k statku svému.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 14, 'Když nějakou věc prodáš bližnímu svému, aneb koupíš něco od bližního svého, nikoli neutiskujte jeden druhého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 15, 'Vedlé počtu let po létu milostivém koupíš od bližního svého, a vedlé počtu let, v kterýchž úrody bráti máš, prodá tobě.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 16, 'Čím více bude let, tím větší placení bude, a čím méně let, tím, menší placení bude; nebo počet úrod prodá tobě.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 17, 'Protož nikoli neoklamávejte jeden druhého, ale boj se každý Boha svého; nebo já jsem Hospodin Bůh váš.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 18, 'Ostříhejte ustanovení mých a soudy mé zachovávejte a čiňte je, a bydliti budete v zemi té bezpečně.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 19, 'A přinese vám země úrody své; i budete jísti až do sytosti, bydlíce bezpečně v ní.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 20, 'Pakli díte: Co budeme jísti léta sedmého, jestliže nebudeme síti, ani shromažďovati užitků svých?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 21, 'Dám požehnání své vám léta šestého, tak že přinese úrody na tři léta.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 22, 'I budete síti léta osmého, a jísti úrody staré až do léta devátého; dokudž by nezrostly úrody jeho, jísti budete staré.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 23, 'Země pak nebude prodávána v manství; nebo má jest země, a vy jste příchozí a podruzi u mne.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 24, 'A po vší zemi vládařství svého dopustíte dávati výplatu země.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 25, 'Jestliže by ochudl bratr tvůj, tak že by prodal něco z statku svého, tedy přijde příbuzný jeho, nejbližší jeho, a vyplatí prodanou věc od bratra svého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 26, 'Pakli kdo nemaje výplatce, mohl by tomu sám dosti učiniti, tak že shledal by, což potřebí k vyplacení:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 27, 'Tedy počte léta prodaje svého, a navrátí, což zůstane, tomu, jemuž prodal; tak zase přijde k statku svému.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 28, 'Pakli by nemohl shledati toho, což by navrátiti měl, tedy zůstane věc prodaná v rukou toho, kterýž ji koupil, až do léta milostivého. I postoupí mu ji v čas léta milostivého, a on navrátí se zase k dědictví svému.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 29, 'Když by kdo prodal dům k bydlení v městě hrazeném, bude míti právo k vyplacení jeho, dokudž nevyplní se rok prodaje jeho. Za celý rok bude míti právo k vyplacení jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 30, 'Pakliť ho nevyplatí dříve, než vyjde ten celý rok, tedy zůstane dům ten v městě hrazeném tomu, kterýž jej koupil, dědičně v pronárodech jeho, aniž ho postoupí v létě milostivém.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 31, 'Domové pak ve vsech, kteréž nejsou zdí ohrazené, tak jako pole země počítati se budou. Budou moci býti vyplacováni, a léta milostivého navráceni budou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 32, 'Ale města Levítská, a domové v městech dědictví jejich, ti vždycky vyplaceni mohou býti od Levítů.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 33, 'Ten pak, kdož vyplacuje, ať jest z Levítů. Aneb ať vyjde kupec z koupeného domu a města dědictví jeho v čas léta milostivého; nebo domové měst Levítských jsou dědictví jejich mezi syny Izraelskými.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 34, 'Pole pak na předměstí měst jejich nebude prodáváno, nebo dědictví jejich věčné jest.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 35, 'Jestliže by schudl bratr tvůj, a ustaly by ruce jeho u tebe, posilníš ho; též příchozí aneb podruh živiti se bude při tobě.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 36, 'Nevezmeš od něho lichvy aneb úroku, ale báti se budeš Boha svého, aby se mohl bratr tvůj živiti u tebe.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 37, 'Peněz svých nedáš jemu na lichvu, aniž pro zisk půjčovati budeš obilí svého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 38, 'Já jsem Hospodin Bůh váš, kterýž jsem vyvedl vás z země Egyptské, abych vám dal zemi Kananejskou, a byl vám za Boha.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 39, 'Jestliže by pak schudl bratr tvůj u tebe, tak že by se prodal tobě, nebudeš ho podrobovati v dílo otrocké.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 40, 'Jakožto nájemník a jako podruh bude při tobě; až do léta milostivého sloužiti bude u tebe.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 41, 'Potom vyjde od tebe s dětmi svými, a navrátí se k čeledi své, a v dědictví otců svých navrátí se.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 42, 'Nebo jsou služebníci moji, kteréž jsem vyvedl z země Egyptské; nebudou prodáváni tak jako jiní služebníci.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 43, 'Nebudeš panovati nad ním tvrdě, ale báti se budeš Boha svého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 44, 'Služebník pak tvůj aneb děvka tvá, kteréž míti budeš, budou z národů těch, kteříž jsou vůkol vás; z nich kupovati budete služebníky a děvky.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 45, 'I od synů bydlitelů, kteříž jsou u vás pohostinu, od těch kupovati budete, a z čeledí těch, kteříž jsou s vámi, kteréž zplodili v zemi vaší, a budou vám v dědictví.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 46, 'A vládnouti budete jimi právem dědičným, i synové vaší po vás, abyste je dědičně obdrželi. Na věčnost služby jejich užívati budete, ale nad bratřími svými, syny Izraelskými, nižádný nad bratrem svým nebude tvrdě panovati.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 47, 'Jestliže by pak zbohatl příchozí aneb host, kterýž bydlí s tebou, a bratr tvůj přišel by na chudobu při něm, tak že by se prodal příchozímu aneb hosti tvému, aneb obyvateli, kterýž jest z čeledi cizí,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 48, 'Když by se tedy prodal, může zase vyplacen býti. Někdo z bratří jeho vyplatí ho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 49, 'Buďto strýc jeho, aneb syn strýce jeho vyplatí jej, aneb někdo z přátel krevních jeho, z rodiny jeho, vyplatí ho; aneb jestli potom sám bude moci s to býti, vyplatí se.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 50, 'I počte se s tím, kterýž ho koupil, od léta, v kterémž se jemu prodal, až do léta milostivého, aby peníze, za něž jest prodán, byly vedlé počtu let; a jakožto s nájemníkem, tak se s ním stane.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 51, 'Jestliže ještě mnoho let zůstává k létu milostivému, vedlé nich navrátí výplatu svou z peněz, za něž koupen jest.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 52, 'Pakli málo zůstává let do léta milostivého, tedy počte se s ním, a vedlé počtu let jeho navrátí výplatu svou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 53, 'Tak jako s čeledínem ročním nakládáno bude s ním; nebude nad ním tvrdě panovati před očima tvýma.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 54, 'Pakli by se nevyplatil v těch letech, tedy vyjde léta milostivého on, i synové jeho s ním.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 55, 'Nebo synové Izraelští jsou moji služebníci, služebníci moji jsou, kteréž jsem vyvedl z země Egyptské: Já Hospodin Bůh váš.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 1, 'Nedělejte sobě modl, ani obrazu rytého, aneb sloupu nevyzdvihnete sobě, ani kamene malovaného v zemi vaší nestavějte, abyste se jemu klaněli; nebo já jsem Hospodin Bůh váš.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 2, 'Sobot mých ostříhejte, a svatyně mé se bojte: Já jsem Hospodin.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 3, 'Jestliže v ustanoveních mých choditi budete, a přikázaní mých ostříhajíce, budete je činiti:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 4, 'Tedy dám vám deště vaše časy svými, a země vydá úrody své, a stromoví polní vydá ovoce své,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 5, 'Tak že mlácení postihne vinobraní, a vinobraní postihne setí. I budete jísti chléb svůj do sytosti, a přebývati budete bezpečně v zemi své.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 6, 'Nebo dám pokoj v zemi, i budete spáti, a nebude, kdo by vás předěsil; vypléním i zvěř zlou z země, a meč nebude procházeti země vaší.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 7, 'Nýbrž honiti budete nepřátely své, a padnou před vámi od meče.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 8, 'Pět vašich honiti jich bude sto, a sto vašich honiti bude deset tisíců, i padnou nepřátelé vaši před vámi od meče.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 9, 'Nebo obrátím tvář svou k vám, a dám vám zrůst, a rozmnožím vás, a utvrdím smlouvu svou s vámi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 10, 'A jísti budete úrody několikaleté, a když nové přijdou, staré vyprázdníte.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 11, 'Vzdělám příbytek svůj u prostřed vás, a duše má nebude vás nenáviděti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 12, 'A procházeti se budu mezi vámi, a budu Bohem vaším, a vy budete lidem mým.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 13, 'Já jsem Hospodin Bůh váš, kterýž jsem vyvedl vás z země Egyptských, abyste jim nesloužili, a polámal jsem závory jha vašeho, abyste chodili prosti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 14, 'Pakli nebudete mne poslouchati, a nebudete činiti všech přikázaní těchto,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 15, 'A jestli ustanovení má zavržete, a soudy mé zoškliví-li sobě duše vaše, tak abyste nečinili všech přikázaní mých, a zrušili byste smlouvu mou:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 16, 'Já také toto učiním vám: Uvedu na vás strach, souchotiny a zimnici pálčivou, což zkazí oči vaše, a bolestí naplní duši. Semeno své nadarmo síti budete, nebo nepřátelé vaši snědí je.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 17, 'Postavím zůřivou tvář svou proti vám, tak že poraženi budete od nepřátel svých, a panovati budou nad vámi ti, kteříž vás nenávidí. Utíkati budete, ano vás žádný nehoní.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 18, 'Jestliže ani tak poslouchati mne nebudete, tedy ještě sedmkrát více trestati vás budu pro hříchy vaše.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 19, 'A potru vyvýšenost síly vaší, a učiním nebe nad vámi jako železo, a zemi vaši jako měď.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 20, 'Nadarmo bude vynaložena síla vaše, nebo země vaše nevydá vám úrody své, a stromoví země nevydá ovoce svého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 21, 'Jestliže pak se mnou maní zacházeti budete, a nebudete mne chtíti poslouchati, tedy přidám na vás sedmkrát více ran vedlé hříchů vašich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 22, 'A pustím na vás zvěř polní, kteráž uvede na vás sirobu, a vyhubí hovada vaše a umenší vás; i zpustnou cesty vaše.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 23, 'Pakli ani potom nenapravíte se, ale vždy se mnou maní zacházeti budete,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 24, 'I já s vámi maní zacházeti budu, a bíti vás budu sedmkrát více pro hříchy vaše.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 25, 'A uvedu na vás meč, kterýž vrchovatě pomstí zrušení smlouvy. I shrnete se do měst svých; tam pošli mor mezi vás, a dáni budete v ruce nepřátelům.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 26, 'A když polámi vám hůl chleba, tedy deset žen péci bude chléb váš v peci jedné, a zase chléb váš odvažovati vám budou. Budete pak jísti, a nenasytíte se.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 27, 'Pakli i s tím nebudete mne poslouchati, ale předce maní se mnou zacházeti budete:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 28, 'I já také v hněvě maní s vámi zacházeti budu, a trestati vás budu i já sedmkrát více pro hříchy vaše.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 29, 'A budete jísti těla synů svých, a těla dcer svých.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 30, 'A zkazím výsosti vaše, a vypléním slunečné obrazy vaše, a skladu těla vaše na špalky ukydaných bohů vašich, a duše má bude vás nenáviděti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 31, 'Města vaše dám v zpuštění, a učiním, aby zpustly svatyně vaše, aniž více zachutnám oběti vůně příjemné vaší.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 32, 'Já zpustím zemi, tak že ztrnou nad ní nepřátelé vaši, kteříž bydliti budou v ní.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 33, 'Vás pak rozptýlím mezi národy, a učiním, aby s dobytým mečem vás honili. I bude země vaše vyhubena, a města vaše zpustnou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 34, 'A tehdy země užive sobot svých po všecky dny, v nichž pustá bude, vy pak budete v zemi nepřátel svých. Tehdáž, pravím, odpočine země, a užive sobot svých.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 35, 'Po všecky dny, v nichž pustá bude, odpočívati bude; nebo neodpočívala v soboty vaše, když jste vy bydlili v ní.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 36, 'Kteříž pak ještě pozůstanou z vás, uvedu strach na srdce jejich v krajinách nepřátel jejich, tak že zažene je chřest listu větrem chřestícího. I budou utíkati, rovně jako před mečem, a padnou, an jich žádný honiti nebude.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 37, 'A budou padati jeden přes druhého jakožto od meče, ač jich žádný honiti nebude; aniž kdo z vás bude moci ostáti před nepřátely svými.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 38, 'I zahynete mezi národy, a zžíře vás země nepřátel vašich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 39, 'Kteříž pak pozůstanou z vás, svadnouti budou pro nepravost svou v zemi nepřátel vašich, ano i pro nepravosti otců vašich s nimi usvadnou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 40, 'Ale jestliže budou vyznávati nepravost svou, a nepravost otců svých vedlé přestoupení svého, kterýmž přestoupili proti mně, a maní se mnou zacházeli,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 41, 'I já také že jsem maní s nimi zacházel, a uvedl je do země nepřátel jejich; jestliže, pravím, tehdáž poníží se srdce jejich neobřezané, a schválí pokutu nepravosti své:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 42, 'Tedy rozpomenu se na smlouvu svou s Jákobem, a na smlouvu svou s Izákem, i na smlouvu svou s Abrahamem rozpomenu se; také i na tu zemi pamětliv budu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 43, 'Mezi tím země jsuc jich zbavena, užive sobot svých, kdyžto zpuštěna bude pro ně. Tehdáž oni schválí pokutu nepravosti své proto, že všelijak soudy mými pohrdali, a ustanovení má zošklivila sobě duše jejich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 44, 'A však i tak, když by v zemi nepřátel svých byli, nezavrhl bych jich, a nezošklivil jich sobě, abych je měl do konce zkaziti, a zrušiti smlouvu svou s nimi; nebo já jsem Hospodin Bůh jejich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 45, 'Ale rozpomenu se na ně pro smlouvu učiněnou s předky jejich, kteréž jsem vyvedl z země Egyptské před očima pohanů, abych jim byl za Boha: Já Hospodin.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 46, 'Ta jsou ustanovení a soudové, i zákonové, kteréž vydal Hospodin na hoře Sinai skrze Mojžíše, aby byli mezi ním a mezi syny Izraelskými.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 1, 'Mluvil také Hospodin k Mojžíšovi, řka:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 2, 'Mluv synům Izraelským a rci jim: Když by kdo slibem oddal duše Hospodinu, vedlé ceny tvé dá výplatu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 3, 'Tato pak bude cena tvá: Osobě mužského pohlaví, počna od toho, kterýž jest ve dvadcíti letech, až do šedesátiletého, uložíš výplatu padesáte lotů stříbra vedlé lotu svatyně.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 4, 'Pakli ženského pohlaví bude, uložíš výplatu třidceti lotů.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 5, 'A od pětiletých až do dvadcítiletých uložíš výplatu, za osobu mužského pohlaví dvadceti lotů, ženského pak deset lotů.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 6, 'A od dítěte jednoho měsíce zstáří až do pětiletých, uložíš za pachole pět lotů stříbra, a za děvče tři loty stříbra.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 7, 'Od šedesáti pak let a výše, bude-li muž, uložíš výplatu patnácte lotů, a ženě deset lotů.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 8, 'Pakli bude tak chudý, že by nemohl uložené výplaty dáti, tedy postaven bude před knězem, aby mu kněz uložil výplatu. Podlé toho, seč bude moci býti ten, kdož slib učinil, uloží mu výplatu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 9, 'Jestliže by pak kdo hovado z těch, kteréž se obětují Hospodinu, slíbil, každé, kteréž dá z nich Hospodinu, svaté bude.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 10, 'Nesmění ho, aniž dá jiného za ně, lepšího za horší, aneb horšího za lepší. Jestliže by pak jakýmkoli způsobem je směnil, hovado za hovado, tedy ono i toto, kteréž za ně dáno, svaté bude.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 11, 'Pakli by které nečisté hovado slíbil, z jehož pokolení neobětují oběti Hospodinu, tedy postaví to hovado před knězem.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 12, 'A bude je šacovati kněz, buď ono dobré aneb zlé. Jakž je kněz cení, tak buď.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 13, 'Pakli bude chtíti vyplatiti je, přidá pátý díl nad cenu tvou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 14, 'Když by pak někdo posvětil domu svého, aby byl svatý Hospodinu, bude jej kněz ceniti, buďto že by dobrý byl aneb zlý. Jakž jej procení kněz, tak zůstane.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 15, 'Pakli ten, kterýž posvětil domu svého, chtěl by jej vyplatiti, přidá pátý díl peněz nad cenu tvou, i bude jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 16, 'Jestliže by kdo díl pole dědictví svého posvětil Hospodinu, tedy budeš je ceniti vedlé toho, jakž se osívá. Chomer ječmene kde se vseje, za padesáte lotů stříbra ceněno bude.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 17, 'Jestliže by hned od léta milostivého posvětil pole svého, tedy vedlé ceny tvé zůstane.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 18, 'Pakli by po létě milostivém posvětil pole svého, tedy sečte mu kněz peníze vedlé počtu let zůstávajících ještě do léta milostivého, i odejme to z ceny tvé.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 19, 'Chtěl-li by pak vyplatiti pole ten, kterýž ho posvětil, přidá pátý díl peněz nad cenu tvou, a zůstane jemu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 20, 'Nevyplatil-li by pak pole toho, a prodáno by bylo někomu jinému, nemůže víc vyplaceno býti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 21, 'I bude pole to, když svobodné vyjde léta milostivého, svaté Hospodinovo, jakožto pole posvěcené; knězi bude v dědictví jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 22, 'Jestliže pak pole koupené, kteréž by nebylo z pole dědictví jeho, posvětil Hospodinu,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 23, 'Tedy sečte mu kněz summu ceny jeho až do léta milostivého, i dá cenu jeho v ten den, jako posvěcenou Hospodinu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 24, 'V létě milostivém navrátí se pole k tomu, od kohož bylo koupeno, jehož dědictví jest pole to.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 25, 'Všeliká pak cena tvá bude vedlé lotu svatyně. Lot pak váží dvadceti haléřů.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 26, 'Ale prvorozeného, což právem prvorozenství dává se Hospodinu z hovad, nižádný neposvětí, buďto z skotů aneb z bravů; Hospodinovo jest prvé.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 27, 'A jestliže by z hovad nečistých bylo, vyplatí je vedlé ceny tvé, a přidá pátý díl nad ní. Pakliť nebude vyplaceno, tedy nechť jest prodáno vedlé ceny tvé.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 28, 'Všeliká pak věc posvěcená, kterouž by někdo slibem posvětil Hospodinu ze všech věcí, kteréž má, buď z lidí aneb z hovad, aneb z pole dědictví svého, nebude prodávána, ani vyplacována; nebo všecko, což takovým slibem posvěceno jest, věc nejsvětější bude Hospodinu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 29, 'Všeliké hovado tak oddané, kteréž slibem tím se oddává od člověka, nebude vyplacováno, ale smrtí umře.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 30, 'Všickni také desátkové země, buď z semene země, aneb z ovoce stromů, Hospodinovi budou; nebo posvěceni jsou Hospodinu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 31, 'Bude-li kdo chtíti vyplatiti desátky své, pátý díl jejich přidá nad ně.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 32, 'A všeliký desátek z volů aneb drobného dobytka, jakž přichází pod hůl pastýře, každý ten desátek svatý bude Hospodinu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 33, 'Nebude vyhledávati, dobré-li by bylo čili zlé, aniž ho smění. Pakli je předce smění, bude to i ono odměněné svaté, a nebude vyplaceno.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 34, 'Ta jsou přikázaní, kteráž přikázal Hospodin Mojžíšovi na hoře Sinai, aby je oznámil synům Izraelským.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 1, 'Mluvil pak Hospodin k Mojžíšovi na poušti Sinai, v stánku úmluvy, prvního dne měsíce druhého, léta druhého po vyjití jejich z země Egyptské, řka:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 2, 'Sečtěte summu všeho množství synů Izraelských po čeledech jejich, a po domích otců jejich, vedlé počtu jmen každého pohlaví mužského po hlavách jejich,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 3, 'Od dvadcítiletých a výše všecky, kteříž by mohli jíti k boji v Izraeli, sečtěte je po houfích jejich, ty a Aron.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 4, 'A bude s vámi z každého pokolení jeden muž, kterýž by přední byl v domě otců svých.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 5, 'Tato pak jsou jména mužů, kteříž stanou s vámi: Z pokolení Rubenova Elisur, syn Sedeurův;');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 6, 'Z Simeonova Salamiel, syn Surisaddai;');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 7, 'Z Judova Názon, syn Aminadabův;');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 8, 'Z Izacharova Natanael, syn Suar;');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 9, 'Z Zabulonova Eliab, syn Helonův;');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 10, 'Z synů Jozefových, z pokolení Efraimova Elisama, syn Amiudův; z Manassesova Gamaliel, syn Fadasurův;');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 11, 'Z Beniaminova Abidan, syn Gedeonův;');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 12, 'Z pokolení Dan Ahiezer, syn Amisaddai;');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 13, 'Z Asser Fegiel, syn Ochranův;');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 14, 'Z pokolení Gád Eliazaf, syn Duelův;');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 15, 'Z Neftalímova Ahira, syn Enanův.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 16, 'Ti jsou slovoutní z lidu, knížata pokolení otců svých, ti jako hlavy tisíců Izraelských budou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 17, 'Vzal tedy Mojžíš a Aron muže ty, kteříž jmenováni byli,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 18, 'A shromáždili všecko množství prvního dne měsíce druhého, kteříž přiznávali se k rodům svým po čeledech svých, po domích otců svých, a vedlé počtu jmen, od dvadcítiletých a výše po osobách svých.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 19, 'Jakož byl přikázal Hospodin Mojžíšovi, tak sčetl je na poušti Sinai.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 20, 'I bylo synů Rubena prvorozeného Izraelova, rodiny jejich, po čeledech jejich, po domích otců jejich, a podlé počtu jmen, po hlavách jejich, všech pohlaví mužského, od dvadcítiletých a výše, všech, kteříž mohli jíti k boji,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 21, 'A načteno jich z pokolení Rubenova čtyřidceti šest tisíců a pět set.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 22, 'Z synů Simeonových, rodiny jejich, po čeledech jejich, po domích otců jejich, sečtených jeho vedlé počtu jmen, po hlavách jejich, všech pohlaví mužského od dvadcítiletých a výše, všech, kteříž mohli jíti k boji,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 23, 'Načteno jich z pokolení Simeonova padesáte devět tisíců a tři sta.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 24, 'Z synů Gádových, rodiny jejich, po čeledech jejich, po domích otců jejich, podlé počtu jmen, od dvadcítiletých a výše, všech, kteříž mohli bojovati,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 25, 'Načteno jich z pokolení Gádova čtyřidceti pět tisíců, šest set a padesát.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 26, 'Z synů Judových, rodiny jejich, po čeledech jejich, po domích otců jejich, vedlé počtu jmen, od dvadcíti let a výše, všech, kteříž mohli jíti k boji,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 27, 'Načteno jich z pokolení Judova sedmdesáte čtyři tisíce a šest set.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 28, 'Z synů Izacharových, rodiny jejich, po čeledech jejich, po domích otců jejich, podlé počtu jmen, od dvadcítiletých a výše, všech, kteříž mohli jíti k boji,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 29, 'Načteno jich z pokolení Izacharova padesáte čtyři tisíce a čtyři sta.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 30, 'Z synů Zabulonových, rodiny jejich, po čeledech jejich, po domích otců jejich, podlé počtu jmen, od dvadcítiletých a výše, všech, kteříž mohli jíti k boji,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 31, 'Načteno jich z pokolení Zabulonova padesáte sedm tisíců a čtyři sta.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 32, 'Z synů Jozefových, a nejprv, synů Efraimových, rodiny jejich, po čeledech jejich, po domích otců jejich, podlé počtu jmen, od dvadcítiletých a výše, všech, kteříž mohli jíti k boji,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 33, 'Načteno jich z pokolení Efraimova čtyřidceti tisíc a pět set.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 34, 'Potom z synů Manassesových, rodiny jejich, po čeledech jejich, po domích otců jejich, vedlé počtu jmen, od dvadcítiletých a výše, všech, kteříž vycházeli k boji,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 35, 'Načteno jich z pokolení Manassesova třidceti dva tisíce a dvě stě.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 36, 'Z synů Beniaminových, rodiny jejich, po čeledech jejich, po domích otců jejich, vedlé počtu jmen, od dvadcítiletých a výše, všech, kteříž mohli jíti do boje,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 37, 'Načteno jich z pokolení Beniaminova třidceti pět tisíců a čtyři sta.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 38, 'Z synů Dan, rodiny jejich, po čeledech jejich, po domích otců jejich, vedlé počtu jmen, od dvadcítiletých a výše, všech, kteříž vycházeli k boji,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 39, 'Načteno jich z pokolení Dan šedesáte dva tisíce a sedm set.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 40, 'Z synů Asser, rodiny jejich, po čeledech jejich, po domích otců jejich, vedlé počtu jmen, od dvadcítiletých a výše, všech, kteříž mohli jíti na vojnu,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 41, 'Načteno jich z pokolení Asser čtyřidceti jeden tisíců a pět set.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 42, 'Z synů Neftalímových, rodiny jejich, po čeledech jejich, po domích otců jejich, vedlé počtu jmen, od dvadcítiletých a výše, všech, kteříž mohli jíti k boji,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 43, 'Načteno jich z pokolení Neftalímova padesáte tři tisíce a čtyři sta.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 44, 'Ten jest počet těch, kteréž sečtl Mojžíš a Aron a knížata Izraelská, dvanácte mužů, kteříž byli vybráni po jednom z domů otců svých.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 45, 'I bylo všech sečtených synů Izraelských po domích otců jejich, od dvadcítiletých a výše, všech, kteříž mohli vycházeti k boji v Izraeli,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 46, 'Všech sečtených bylo šestkrát sto tisíc, a tři tisíce, pět set a padesáte.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 47, 'Levítové pak vedlé pokolení otců svých nejsou počítáni mezi ně.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 48, 'Nebo byl mluvil Hospodin k Mojžíšovi, řka:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 49, 'Pokolení Levítského nebudeš počítati, a nepřičteš jich k synům Izraelským,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 50, 'Ale ustanovíš Levíty nad příbytkem svědectví, a nade vším nádobím jeho, a nade všemi věcmi, kteréž přináležejí k němu. Oni nositi budou příbytek i všecka nádobí jeho, oni přisluhovati budou jemu, a vůkol příbytku klásti se budou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 51, 'Když se pak s místa bude míti hýbati příbytek, složí jej Levítové; a když se bude klásti příbytek, vyzdvihnou jej Levítové. Kdož by koli cizí přistoupil, umře.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 52, 'I budouť se klásti synové Izraelští, jeden každý v ležení svém, a jeden každý pod praporcem svým, a po houfích svých.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 53, 'Levítové pak klásti se budou vůkol příbytku svědectví, aby nepřišlo rozhněvání mé na shromáždění synů Izraelských; i budou Levítové držeti stráž u příbytku svědectví.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 54, 'Učinili tedy to synové Izraelští; všecko, jakž přikázal Hospodin Mojžíšovi, tak učinili.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 1, 'Mluvil také Hospodin k Mojžíšovi a Aronovi, řka:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 2, 'Synové Izraelští klásti se budou jeden každý pod korouhví svou, při praporci domu otců svých; vůkol stánku úmluvy opodál klásti se budou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 3, 'Tito pak rozbijí stany k východní straně: Korouhev vojska Judova po houfích svých, a kníže synů Juda Názon, syn Aminadabův,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 4, 'A u vojště jeho lidu sečteného sedmdesáte čtyři tisíce a šest set.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 5, 'Podlé něho pak položí se pokolení Izachar, a kníže synů Izachar Natanael, syn Suar,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 6, 'A u vojště jeho lidu sečteného padesáte čtyři tisíce a čtyři sta.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 7, 'Pokolení Zabulon podlé nich, a kníže synů Zabulon Eliab, syn Helonův,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 8, 'A u vojště jeho lidu sečteného padesáte sedm tisíců a čtyři sta.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 9, 'Summa všech sečtených u vojště Judově sto osmdesáte šest tisíců a čtyři sta, po houfích jejich. Ti napřed potáhnou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 10, 'Korouhev vojska Rubenova klásti se bude ku poledni po houfích svých, a kníže synů Ruben Elisur, syn Sedeurův,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 11, 'A u vojště jeho lidu sečteného čtyřidceti šest tisíců a pět set.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 12, 'Podlé něho pak položí se pokolení Simeonovo, a kníže synů Simeon Salamiel, syn Surisaddai,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 13, 'A u vojště jeho lidu sečteného padesáte devět tisíců a tři sta.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 14, 'Potom pokolení Gád, a kníže synů Gád Eliazaf, syn Ruelův,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 15, 'A u vojště jeho lidu sečteného čtyřidceti pět tisíců, šest set a padesáte.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 16, 'Summa všech sečtených u vojště Rubenově sto padesáte a jeden tisíců, čtyři sta a padesáte, po houfích svých. A ti za prvními potáhnou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 17, 'Potom půjde stánek úmluvy s vojskem Levítů u prostřed všeho vojska. Jakýmž pořádkem klásti se budou, takovým potáhnou, každý v svém šiku pod korouhví svou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 18, 'Korouhev vojska Efraimova po houfích svých bude k západu, a kníže synů Efraimových Elisama, syn Amiudův,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 19, 'A u vojště jeho lidu sečteného čtyřidceti tisíc a pět set.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 20, 'Podlé něho pak položí se pokolení Manassesovo, a kníže synů Manassesových Gamaliel, syn Fadasurův,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 21, 'A u vojště jeho lidu sečteného třidceti dva tisíce a dvě stě.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 22, 'Potom položí se pokolení Beniaminovo, a kníže synů Beniamin Abidan, syn Gedeonův,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 23, 'A u vojště jeho lidu sečteného třidceti pět tisíců a čtyři sta.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 24, 'Summa všech sečtených u vojště Efraimově sto osm tisíců a sto osob, po houfích jejich. A tito za druhými potáhnou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 25, 'Korouhev vojska Dan bude k straně půlnoční, po houfích svých, a kníže synů Dan Ahiezer, syn Amisaddai,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 26, 'A u vojště jeho lidu sečteného šedesáte dva tisíce a sedm set.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 27, 'Podlé něho položí se pokolení Asser, a kníže Asser Fegiel, syn Ochranův,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 28, 'A u vojště jeho lidu sečteného čtyřidceti jeden tisíc a pět set.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 29, 'Za nimi pokolení Neftalímovo, a kníže synů Neftalímových Ahira, syn Enanův,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 30, 'A u vojště jeho lidu sečteného padesáte tři tisíce a čtyři sta.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 31, 'Summa všech sečtených u vojště Dan sto padesáte sedm tisíců a šest set. Oni nazad potáhnou při praporcích svých.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 32, 'Ta jest summa synů Izraelských po domích otců jejich, všech sečtených v celém vojště po houfích jejich, šestkrát sto tisíců, tři tisíce, pět set a padesáte.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 33, 'Levítové pak nejsou počítáni mezi syny Izraelské, jakož přikázal Hospodin Mojžíšovi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 34, 'I učinili synové Izraelští všecko; jakž přikázal Hospodin Mojžíšovi, tak rozbijeli stany při korouhvech svých, a tak táhli jeden každý po čeledech svých a po domích otců svých.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 1, 'Tito jsou příběhové Aronovi a Mojžíšovi od toho dne, když mluvil Hospodin s Mojžíšem na hoře Sinai.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 2, 'A tato jsou jména synů Aronových: Prvorozený Nádab, potom Abiu, Eleazar a Itamar.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 3, 'Ta jsou jména synů Aronových, kněží pomazaných, jejichžto ruce naplněny, aby úřad kněžství konali.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 4, 'Umřel pak Nádab a Abiu před Hospodinem, když obětovali cizí oheň před Hospodinem na poušti Sinai, a neměli synů. Protož konal úřad kněžský Eleazar a Itamar před tváří Arona otce svého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 5, 'Mluvil pak Hospodin k Mojžíšovi, řka:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 6, 'Rozkaž přistoupiti pokolení Léví, a postav je před Aronem knězem, aby mu přisluhovali,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 7, 'A drželi stráž jeho, i stráž všeho množství před stánkem úmluvy k vykonávání služby příbytku,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 8, 'Též aby ostříhali všeho nádobí stánku úmluvy, a drželi stráž synů Izraelských a konali služby příbytku.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 9, 'Dáš tedy Levíty Aronovi i synům jeho; vlastně dáni jsou mu oni z synů Izraelských.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 10, 'Arona pak a syny jeho představíš, aby ostříhali kněžství svého; nebo přistoupil-li by kdo cizí, umře.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 11, 'I mluvil Hospodin Mojžíšovi, řka:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 12, 'Aj, já vzal jsem Levíty z prostředku synů Izraelských na místo všelikého prvorozeného, kteréž otvírá život mezi syny Izraelskými. Protož moji budou Levítové.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 13, 'Nebo mně přináleží všecko prvorozené. Od toho dne, když jsem pobil všecko prvorozené v zemi Egyptské, posvětil jsem sobě všeho prvorozeného v Izraeli od člověka až do hovada. Mně bude: Já Hospodin.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 14, 'Mluvil také Hospodin k Mojžíšovi na poušti Sinai, řka:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 15, 'Sečti syny Léví vedlé domů otců jejich, po čeledech jejich, každého pohlaví mužského; zstáří jednoho měsíce a výše počítati budeš je.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 16, 'I sčetl je Mojžíš podlé řeči Hospodinovy, jakž rozkázáno mu bylo.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 17, 'I byli synové Léví ze jména tito: Gerson, Kahat a Merari.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 18, 'Tato pak jsou jména synů Gersonových po čeledech jejich: Lebni a Semei.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 19, 'A synové Kahat po čeledech svých: Amram a Izar, Hebron a Uziel.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 20, 'Synové pak Merari po čeledech svých: Moholi a Musi. Ty jsou čeledi Léví vedlé domů otců svých.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 21, 'Od Gersona čeled Lebnitská a čeled Semejská. Ty jsou čeledi Gersonovy.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 22, 'A načteno jich v počtu všech pohlaví mužského zstáří jednoho měsíce a výše sedm tisíců a pět set.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 23, 'Čeledi Gersonovy za příbytkem klásti se budou k straně západní.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 24, 'Kníže pak domu otce Gersonitských bude Eliazaf, syn Laelův.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 25, 'A k opatrování synům Gersonovým při stánku úmluvy náležeti bude příbytek i stánek, přikrytí jeho i zastření dveří stánku úmluvy,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 26, 'A očkovaté koltry k síni, i zavěšení dveří síně, kteráž jest před příbytkem a při oltáři vůkol, i provazové jeho ke všeliké potřebě jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 27, 'Od Kahat pak pošla čeled Amramitská a čeled Izaritská, a čeled Hebronitská, a čeled Uzielitská. Ty jsou čeledi Kahat.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 28, 'V počtu všech pohlaví mužského zstáří jednoho měsíce a výše bylo osm tisíců a šest set, držících stráž při svatyni.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 29, 'Čeledi synů Kahat klásti se budou k straně příbytku polední,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 30, 'A kníže domu otcovského v čeledech Kahat Elizafan, syn Uzielův.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 31, 'V jejich pak opatrování bude truhla, stůl, svícen, oltářové a nádobí svatyně, jímž přisluhovati budou, a opona i všecko, což přináleží k ní.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 32, 'Kníže pak nad knížaty Levítskými Eleazar, syn Arona kněze, ustavený nad těmi, kteříž drží stráž při svatyni.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 33, 'Od Merari pak čeled Moholitská a čeled Musitská. Ty jsou čeledi Merari.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 34, 'A načteno jich v počtu všech mužského pohlaví zstáří jednoho měsíce a výše šest tisíců a dvě stě.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 35, 'A kníže domu otcovského v čeledech Merari Suriel, syn Abichailův. A ti klásti se budou k straně příbytku půlnoční.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 36, 'Toto pak poručeno k opatrování synům Merari: Dsky příbytku a svlakové jeho, sloupové a podstavkové a všecka nádobí jeho i všecka práce při nich,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 37, 'Tolikéž sloupové síně vůkol i podstavkové jejich, kolíkové i provazové jejich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 38, 'Položí se pak před příbytkem po přední straně před stánkem úmluvy od východu slunce Mojžíš a Aron i synové jeho, držíce stráž při svatyni, stráž za syny Izraelské. Jiný přistoupil-li by kdo, umře.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 39, 'Všech sečtených Levítů, kteréž sečtl Mojžíš s Aronem vedlé poručení Hospodinova, po čeledech jejich, všech pohlaví mužského jednoho měsíce zstáří a výše dvamecítma tisíců.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 40, 'I řekl Hospodin k Mojžíšovi: Sečti všecky prvorozené mužského pohlaví mezi syny Izraelskými jednoho měsíce zstáří a výše, a sečti summu jmen jejich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 41, 'A vezmeš mi Levíty, (jáť jsem Hospodin,) místo všech prvorozených mezi syny Izraelskými, i hovada Levítů místo všeho prvorozeného mezi hovady synů Izraelských.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 42, 'Když pak sčetl Mojžíš, jakož mu přikázal Hospodin, všecky prvorozené mezi syny Izraelskými,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 43, 'Bylo všech prvorozených pohlaví mužského vedlé počtu jmen, jednoho měsíce zstáří a výše sečtených jich, dvamecítma tisíců, dvě stě, sedmdesáte a tři.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 44, 'A mluvil Hospodin k Mojžíšovi, řka:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 45, 'Vezmi Levíty místo všech prvorozených z synů Izraelských, i hovada Levítů za hovada jejich; i budou moji Levítové: Já jsem Hospodin.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 46, 'K vyplacení pak těch dvou set, sedmdesáti a tří, kteříž zbývají nad počet Levítů z prvorozených synů Izraelských,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 47, 'Vezmeš pět lotů z každé hlavy, (vedlé lotu svatyně bráti budeš, lot pak dvadceti haléřů váží),');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 48, 'A dáš ty peníze Aronovi a synům jeho, výplatu těch, kteříž zbývají nad počet jejich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 49, 'Vzal tedy Mojžíš peníze výplaty od těch, kteříž zbývali, kromě těch, kteréž vykoupili sebou Levítové,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 50, 'Od prvorozených synů Izraelských vzal peněz tisíc, tři sta, šedesáte pět lotů, vedlé lotu svatyně.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 51, 'I dal ty peníze výplaty Aronovi a synům jeho, podlé řeči Hospodinovy, jakož byl přikázal jemu Hospodin.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 1, 'I mluvil Hospodin k Mojžíšovi a k Aronovi, řka:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 2, 'Sečti summu synů Kahat z prostředku synů Léví po čeledech jejich a po domích otců jejich,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 3, 'Od třidcítiletých a výše až do padesátiletých, kteříž by způsobní jsouce k boji, mohli práci vésti při stánku úmluvy.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 4, 'Tato pak bude práce synů Kahat při stánku úmluvy svatyně svatých:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 5, 'Když by se měla vojska hnouti s místa, přijde Aron s syny svými a sejmou oponu zastření, a přikryjí ní truhlu svědectví.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 6, 'A na to dají přikrytí z koží jezevčích, a přistrou svrchu rouchem z samého postavce modrého, a provlekou sochory její.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 7, 'Na stůl pak chlebů předložení prostrou roucho z postavce modrého, a dají na něj misy a kadidlnice a koflíky a přikryvadla k přikrývání; a chléb ustavičně na něm bude.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 8, 'A prostrou na to roucho z červce dvakrát barveného, a přikryjí to přistřením z koží jezevčích, a provlekou sochory jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 9, 'Vezmou také roucho z postavce modrého, a přikryjí svícen světla a lampy jeho, i utěradla jeho, i nádoby k oharkům jeho, a všecky nádoby k oleji jeho, jichž při něm užívají.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 10, 'A obvinou jej se všechněmi nádobami jeho přikrytím z koží jezevčích, a vloží na sochory.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 11, 'Na oltář pak zlatý prostrou roucho z postavce modrého, a přikryjí jej přikrytím z koží jezevčích, a provlekou sochory.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 12, 'Vezmou i všecky nádoby k službě, jimiž přisluhovali v svatyni, a zavinouce do roucha z postavce modrého, přikryjí je přikrytím z koží jezevčích, a vloží na sochory.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 13, 'Vyprázdní i popel z oltáře, a prostrou na něj roucho šarlatové.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 14, 'A vloží svrchu všecko nádobí jeho, jímž přisluhují na něm, nádoby k uhlí, vidličky, pometla, kotlíky a všecko nádobí oltáře, a přistrouce jej přikrytím z koží jezevčích, uvlekou sochory jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 15, 'A když to vykoná Aron s syny svými, a přikryje svatyni i všecka nádobí její, a již by se měla hýbati vojska, tedy přijdou synové Kahat, aby nesli; ale nedotknou se svatyně, aby nezemřeli. Ta jest práce synů Kahat při stánku úmluvy.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 16, 'Eleazar pak, syn Arona kněze, pečovati bude o olej k svícení a kadění vonnými věcmi a obět ustavičnou i o olej pomazání, svěřený sobě maje všecken příbytek a všecky věci, kteréž v něm jsou, svatyni a nádoby její.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 17, 'A mluvil Hospodin k Mojžíšovi a Aronovi, řka:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 18, 'Hleďtež, abyste nevyhladili pokolení čeledi Kahat z prostředku Levítů.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 19, 'Ale toto učiníte jim, aby zachováni byli a nezemřeli, když by přistupovali k svatyni svatých: Aron a synové jeho přijdouce, zřídí je, jednoho každého ku práci a břemenu jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 20, 'A onino nepřicházejte hleděti na věci svaté, když zavinovány bývají, aby nezemřeli.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 21, 'Mluvil opět Hospodin k Mojžíšovi, řka:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 22, 'Sečti také syny Gersonovy po domích otců jich a po čeledech jejich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 23, 'Od třidcítiletých a výše až do padesátiletých sečteš je, kteříž by způsobní jsouce k boji, mohli konati službu při stánku úmluvy.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 24, 'Tato pak bude práce čeledí Gersonových v službě a nošení:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 25, 'Nositi budou kortýny příbytku a stánek úmluvy s přikrytím jeho, a přikrytí z koží jezevčích, kteréž svrchu na něm jest, a zastření dveří stánku úmluvy,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 26, 'A očkovaté koltry síně, a zastření brány síně, kteráž jest při stanu a při oltáři vůkol, a provazy její, a všecky nádoby přisluhování jejich, a čehožkoli užívají při službě své.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 27, 'Vedlé rozkazu Aronova a synů jeho konati budou všecky služby své synové Gersonovi při všech pracech svých, a při všech službách svých, a svěříte jim k ostříhání všecka břemena jejich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 28, 'Ta jest práce čeledí synů Gersonových v stánku úmluvy, a Itamar, syn Arona kněze, stráž nad nimi držeti bude.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 29, 'Syny také Merari po čeledech jejich a domích otců jejich sečteš.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 30, 'Od třidcítiletých a výše až do padesátiletých sečteš všecky, kteříž by způsobní jsouce k boji, mohli konati službu při stánku úmluvy.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 31, 'Tato pak bude povinnost práce jejich, nad všecku službu jejich při stánku úmluvy: Dsky příbytku a svlaky jeho, i sloupy s podstavky jeho nositi,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 32, 'Sloupy také vůkol síně s podstavky jejich, kolíky a provazy jejich, se všechněmi potřebami, i se vším přisluhováním jejich. A ze jména vyčtete nádoby svěřené jim k ostříhání.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 33, 'Ta bude práce čeledí synů Merari při všech službách jejich při stánku úmluvy, pod spravou Itamara, syna Arona kněze.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 34, 'I sečtl Mojžíš s Aronem a s knížaty lidu syny Kahat po čeledech jejich, a po domích otců jejich,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 35, 'Od třidcítiletých a výše až do padesátiletých, kteříž by způsobní jsouce k boji, mohli konati službu při stánku úmluvy.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 36, 'A bylo jich sečtených po čeledech jejich dva tisíce, sedm set, padesáte.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 37, 'Ti jsou sečteni z čeledi Kahat, všickni služebníci při stánku úmluvy, kteréž sčetl Mojžíš s Aronem podlé rozkazu Hospodinova skrze Mojžíše.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 38, 'Sečtených také synů Gersonových po čeledech jejich, a po domích otců jejich,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 39, 'Od třidcítiletých a výše až do padesátiletých, kteříž by způsobní jsouce k boji, mohli konati službu při stánku úmluvy,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 40, 'Sečtených jich po čeledech jejich, po domích otců jejich, dva tisíce, šest set, třidceti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 41, 'Ti jsou sečteni z čeledí synů Gersonových, všickni přisluhující v stánku úmluvy, kteréž sečtli Mojžíš s Aronem k rozkazu Hospodinovu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 42, 'Sečtených pak z čeledí synů Merari po čeledech jejich, po domích otců jejich,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 43, 'Od třidcítiletých a výše až do padesátiletých, kteříž by způsobní jsouce k boji, mohli konati službu při stánku úmluvy,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 44, 'Načteno jich po čeledech jejich tři tisíce a dvě stě.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 45, 'Ti jsou sečteni z čeledí synů Merari, kteréž sčetl Mojžíš s Aronem podlé rozkazu Hospodinova skrze Mojžíše.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 46, 'Všech sečtených, kteréž sčetl Mojžíš s Aronem a s knížaty Izraelskými z Levítů po čeledech jejich a po domích otců jejich,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 47, 'Od těch, kteříž byli ve třidcíti letech a výše, až do padesátiletých, kteřížkoli přináležejí k vykonávání služby přisluhování a práce břemena při stánku úmluvy,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 48, 'Sečtených těch bylo osm tisíců, pět set a osmdesáte.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 49, 'Vedlé rozkazu Hospodinova sečtl je Mojžíš, jednoho každého vedlé přisluhování jeho, a vedlé břemene jeho. Sečteni pak jsou ti, kteréž rozkázal čísti Hospodin Mojžíšovi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 1, 'I mluvil Hospodin k Mojžíšovi, řka:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 2, 'Přikaž synům Izraelským, ať vyženou z stanů každého malomocného a každého trpícího tok semene, i každého nad mrtvým poškvrněného.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 3, 'I muže i ženu vyženete, ven za stany vyženete je, aby nepoškvrňovali vojska těch, mezi nimiž já přebývám.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 4, 'I učinili tak synové Izraelští, a vyhnali je ven za stany. Jakož byl mluvil Hospodin k Mojžíšovi, tak učinili synové Izraelští.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 5, 'Mluvil také Hospodin k Mojžíšovi, řka:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 6, 'Mluv k synům Izraelským: Muž aneb žena, když učiní nějaký hřích lidský, dopouštěje se výstupku proti Hospodinu, a byla by vinna duše ta:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 7, 'Tedy vyzná hřích svůj, kterýž učinil, navrátí pak to, čímž vinen byl, v cele, a pátý díl přidá nad to, a dá tomu, proti komuž zavinil.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 8, 'A neměl-li by muž ten přítele, jemuž by nahradil tu škodu, pokuta dána buď Hospodinu a knězi, mimo skopce očištění, jímž očištěn býti má.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 9, 'Též všeliká obět všech věcí posvěcených od synů Izraelských, kterouž přinesou knězi, jemu se dostane.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 10, 'Tak i věci posvěcené od kohokoli jemu se dostanou; a dal-li kdo co knězi, také jeho bude.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 11, 'Mluvil ještě Hospodin k Mojžíšovi, řka:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 12, 'Mluv k synům Izraelským a rci jim: Kdyby od některého muže uchýlila se žena, a dopustila by se výstupku proti němu,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 13, 'Tak že by obýval někdo jiný s ní, a bylo by to skryto před očima muže jejího, a tajila by se, jsuci poškvrněna, a svědka by nebylo proti ní, a ona nebyla by postižena;');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 14, 'Pohnul-li by se duch muže horlivostí velikou, tak že by horlil proti ženě své, kteráž by poškvrněna byla; aneb pohnul-li by se duch muže velikou horlivostí, tak že by horlil proti ženě své, kteráž by poškvrněna nebyla:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 15, 'Tedy přivede muž ženu svou k knězi, a přinese obět její při ní, desátý díl efi mouky ječné. Nenalejeť na ni oleje, aniž dá na ni kadidla; nebo obět veliké horlivosti jest, obět suchá pamětná, uvozující v pamět nepravost.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 16, 'I bude ji kněz obětovati, a postaví ji před Hospodinem.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 17, 'A nabere vody svaté do nádoby hliněné, a vezma prachu, kterýž jest na zemi v příbytku, dá jej do té vody.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 18, 'Potom postaví kněz ženu tu před Hospodinem, a odkryje hlavu její, a dá jí do rukou obět suchou pamětnou, kteráž jest obět veliké horlivosti; v ruce pak kněze bude voda hořká zlořečená.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 19, 'I zaklínati bude ji kněz a řekne k ní: Jestliže neobcoval s tebou žádný, a jestliže jsi neuchýlila se k nečistotě od muže svého, budiž čistá od vody této hořké zlořečené.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 20, 'Paklis se uchýlila od muže svého a nečistá jsi, a obcoval-li někdo jiný s tebou kromě manžela tvého,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 21, '(Zaklínati pak bude kněz tu ženu, čině klatbu zlořečenství, a řekne jí:) Dejž tebe Hospodin v zlořečení a v prokletí u prostřed lidu tvého, dopustě, aby lůno tvé hnilo a břicho tvé oteklo.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 22, 'Vejdiž voda zlořečená tato do života tvého, aby oteklo břicho tvé, a lůno tvé shnilo. I odpoví žena ta: Amen, amen.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 23, 'Napíše pak všecko zlořečenství toto do knihy, a smyje je tou vodou hořkou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 24, 'I dá ženě, aby pila vodu hořkou a zlořečenou; a vejdeť do ní voda zlořečená, a obrátí se v hořkosti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 25, 'Potom vezme kněz z ruky ženy obět veliké horlivosti, a obraceti ji bude sem i tam před Hospodinem, a bude ji obětovati na oltáři.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 26, 'A vezma plnou hrst pamětného jejího z oběti suché, páliti to bude na oltáři; a potom dá vypíti ženě tu vodu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 27, 'A když jí dá píti tu vodu, stane se, jestliže nečistá byla, a dopustila se výstupku proti muži svému, že vejde do ní voda zlořečená, a obrátí se v hořkost, i odme se břicho její, a vyhnije lůno její; i bude žena ta v zlořečení u prostřed lidu svého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 28, 'Pakli není poškvrněna žena ta, ale čistá jest, tedy bez viny bude, a roditi bude děti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 29, 'Ten jest zákon veliké horlivosti, když by se uchýlila žena od muže svého, a byla by poškvrněna,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 30, 'Aneb když by se pohnul duch veliké horlivosti v manželu, tak že by horlil velmi proti ženě své, aby postavil ji před Hospodinem, a aby vykonal při ní kněz všecko vedlé zákona tohoto.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 31, 'I bude ten muž očištěn od hříchu, žena pak ponese nepravost svou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 1, 'I mluvil Hospodin k Mojžíšovi, řka:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 2, 'Mluv k synům Izraelským a rci jim: Muž neb žena, když se oddělí, činíce slib nazareův, aby se oddali Hospodinu,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 3, 'Od vína i nápoje opojného zdrží se, octa vinného a octa z nápoje opojného nebude píti, ani co vytlačeného z hroznů, zelených hroznů ani suchých nebude jísti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 4, 'Po všecky dny nazarejství svého nebude jísti žádné věci pocházející z vinného kmene, od zrnka až do šupiny.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 5, 'Po všecky dny slibu nazarejství svého břitva nevejde na hlavu jeho, dokavadž by se nevyplnili dnové, v nichž se oddělil Hospodinu. Svatý bude, a nechá růsti vlasů hlavy své.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 6, 'Po všecky dny, v nichž se oddělí Hospodinu, k tělu mrtvému nevejde.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 7, 'Nad otcem svým aneb nad matkou svou, nad bratrem svým aneb nad sestrou svou, kdyby zemřeli, nebude se poškvrňovati; nebo posvěcení Boha jeho jest na hlavě jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 8, 'Po všecky dny nazarejství svého svatý bude Hospodinu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 9, 'Umřel-li by pak kdo blízko něho náhlou smrtí, a poškvrnil-li by hlavy v nazarejství jeho, oholí hlavu svou v den očišťování svého; dne sedmého oholí ji.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 10, 'A dne osmého přinese dvě hrdličky, aneb dvé holoubátek knězi, ke dveřím stánku úmluvy.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 11, 'I bude kněz obětovati jedno za hřích, a druhé v zápalnou obět, a očistí jej od toho, čímž zhřešil nad mrtvým, a posvětí hlavy jeho v ten den.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 12, 'A oddělí Hospodinu dny nazarejství svého, a přinese beránka ročního za provinění, a dnové první přijdou v nic; nebo poškvrněno jest nazarejství jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 13, 'Tento pak jest zákon nazareův: V ten den, když se vyplní čas nazarejství jeho, přijde ke dveřím stánku úmluvy.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 14, 'A bude obětovati obět svou Hospodinu, beránka ročního bez poškvrny, jednoho v obět zápalnou, a ovci jednu roční bez poškvrny v obět za hřích, a skopce jednoho bez poškvrny v obět pokojnou,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 15, 'A koš chlebů přesných, koláče z mouky bělné olejem zadělané, a pokruty nekvašené, olejem pomazané, s obětmi jejími suchými i mokrými.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 16, 'Kteréžto věci obětovati bude kněz před Hospodinem, a učiní obět za hřích jeho, i zápalnou obět jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 17, 'Skopce také obětovati bude v obět pokojnou Hospodinu, spolu s košem chlebů přesných; tolikéž obětovati bude kněz i obět suchou i mokrou jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 18, 'Tedy oholí nazareus u dveří stánku úmluvy hlavu nazarejství svého, a vezma vlasy z hlavy nazarejství svého, vloží je na oheň, kterýž jest pod obětí pokojnou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 19, 'Potom vezme kněz plece vařené z skopce toho, a jeden koláč přesný z koše, a pokrutu nekvašenou jednu, a dá v ruce nazarejského, když by oholeno bylo nazarejství jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 20, 'I bude obraceti kněz ty věci sem i tam v obět obracení před Hospodinem; a ta věc svatá přináležeti bude knězi mimo hrudí obracení, i plece pozdvižení. A již potom nazareus bude moci víno píti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 21, 'Ten jest zákon nazarea, kterýž slib učinil, a jeho obět Hospodinu za oddělení jeho, kromě toho, což by více učiniti mohl. Vedlé slibu svého, kterýž učinil, tak učiní podlé zákona oddělení svého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 22, 'I mluvil Hospodin k Mojžíšovi, řka:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 23, 'Mluv k Aronovi a synům jeho a rci: Takto budete požehnání dávati synům Izraelským, mluvíce k nim:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 24, 'Požehnejž tobě Hospodin, a ostříhejž tebe.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 25, 'Osvěť Hospodin tvář svou nad tebou, a buď milostiv tobě.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 26, 'Obratiž Hospodin tvář svou k tobě, a dejž tobě pokoj.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 27, 'I budou vzývati jméno mé nad syny Izraelskými, a já jim žehnati budu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 1, 'I stalo se toho dne, když dokonal Mojžíš a vyzdvihl příbytek, a pomazal i posvětil ho se všechněmi nádobami jeho, také oltáře a všeho nádobí jeho pomazal a posvětil,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 2, 'Že přistupujíce knížata Izraelská, přední v domích otců svých, (ti byli knížata pokolení, postavení nad sečtenými,)');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 3, 'Obětovali dar svůj před Hospodinem, šest vozů přikrytých a dvanácte volů. Dvé knížat dalo jeden vůz, a jeden každý jednoho vola, i obětovali to před příbytkem.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 4, 'I řekl Hospodin Mojžíšovi, řka:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 5, 'Vezmi ty věci od nich, ať jsou ku potřebě při službě stánku úmluvy, a dej je Levítům, každé čeledi podlé přisluhování jejího.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 6, 'Vzav tedy Mojžíš ty vozy i voly, dal je Levítům.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 7, 'Dva vozy a čtyři voly dal synům Gersonovým vedlé přisluhování jejich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 8, 'Čtyři pak vozy a osm volů dal synům Merari vedlé přisluhování jejich, kteříž byli pod spravou Itamara, syna Aronova, kněze.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 9, 'Synům pak Kahat nic nedal; nebo přisluhování svatyně k nim přináleželo, a na ramenou nositi měli.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 10, 'Obětovali tedy knížata ku posvěcování oltáře v ten den, když pomazán byl; obětovali, pravím, dar svůj před oltářem.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 11, 'Řekl pak Hospodin Mojžíšovi: Jedno kníže v jeden den, druhé kníže v druhý den, pořád obětovati budou dar svůj ku posvěcení oltáře.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 12, 'Protož obětoval prvního dne dar svůj Názon, syn Aminadabův, z pokolení Judova.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 13, 'Dar pak jeho byl misa stříbrná jedna, sto třidceti lotů ztíží; též báně jedna stříbrná, sedmdesáti lotů ztíží, jakž jest lot svatyně; obě dvě nádoby plné mouky bělné, olejem zadělané k oběti suché;');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 14, 'Kadidlnice jedna z desíti lotů zlata, plná kadidla;');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 15, 'Volek jeden mladý, skopec jeden, a beránek roční jeden k oběti zápalné;');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 16, 'Kozel jeden za hřích;');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 17, 'A k oběti pokojné volové dva, skopců pět, kozlů pět, a beránků ročních pět. Ta byla obět Názona, syna Aminadabova.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 18, 'Druhého dne obětoval Natanael, syn Suar, kníže z pokolení Izachar.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 19, 'Obětoval dar svůj misu stříbrnou jednu, sto třidceti lotů ztíží; báni stříbrnou jednu, sedmdesáti lotů ztíží vedlé lotu svatyně; obě dvě nádoby plné mouky bělné, olejem zadělané k oběti suché;');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 20, 'Kadidlnici jednu z desíti lotů zlata, plnou kadidla;');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 21, 'Volka mladého jednoho, skopce jednoho, a beránka ročního jednoho k oběti zápalné;');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 22, 'Kozla jednoho za hřích;');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 23, 'A k oběti pokojné voly dva, skopců pět, kozlů pět, a beránků ročních pět. Ten byl dar Natanaele, syna Suar.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 24, 'Dne třetího kníže synů Zabulonových Eliab, syn Helonův.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 25, 'Dar pak jeho byl misa stříbrná jedna, kteráž sto třidceti lotů vážila; báně stříbrná jedna, sedmdesáti lotů ztíží vedlé lotu svatyně; obě dvě nádoby plné mouky bělné, olejem zadělané k oběti suché;');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 26, 'Kadidlnice jedna z desíti lotů zlata, plná kadidla;');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 27, 'Volek jeden mladý, skopec jeden, beránek roční jeden k oběti zápalné;');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 28, 'Kozel jeden za hřích;');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 29, 'A k oběti pokojné volové dva, skopců pět, kozlů pět, a beránků ročních pět. Ta byla obět Eliaba, syna Helonova.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 30, 'Čtvrtého dne kníže synů Rubenových Elisur, syn Sedeurův.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 31, 'Dar jeho byl misa stříbrná jedna, kteráž sto třidceti lotů vážila; báně stříbrná jedna, sedmdesáti lotů ztíží vedlé lotu svatyně; obě dvě nádoby plné mouky bělné, olejem zadělané v obět suchou;');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 32, 'Kadidlnice jedna z desíti lotů zlata, plná kadidla;');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 33, 'Volek jeden mladý, skopec jeden, beránek roční jeden k oběti zápalné;');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 34, 'Kozel jeden za hřích;');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 35, 'A k oběti pokojné volové dva, skopců pět, kozlů pět, beránků ročních pět. Ten byl dar Elisura, syna Sedeurova.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 36, 'Dne pátého kníže synů Simeonových, Salamiel, syn Surisaddai;');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 37, 'Obět jeho byla misa stříbrná jedna, kteráž sto třidceti lotů vážila; báně stříbrná jedna, sedmdesáti lotů ztíží vedlé lotu svatyně; obě dvě nádoby plné mouky bělné, olejem zadělané k oběti suché;');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 38, 'Kadidlnice jedna z desíti lotů zlata, plná kadidla;');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 39, 'Volek jeden mladý, skopec jeden, beránek roční jeden k oběti zápalné;');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 40, 'Kozel jeden za hřích;');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 41, 'A na obět pokojnou volové dva, skopců pět, kozlů pět, beránků ročních pět. Ta byla obět Salamiele, syna Surisaddai.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 42, 'Dne šestého kníže synů Gád, Eliazaf, syn Duelův.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 43, 'Dar jeho byl misa stříbrná jedna, kteráž sto třidceti lotů vážila; báně stříbrná jedna, sedmdesáti lotů ztíží vedlé lotu svatyně; obě dvě nádoby plné mouky bělné, olejem zadělané k oběti suché;');
