INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 55, 'Dar jeho byl misa stříbrná jedna, kteráž sto třidceti lotů vážila; báně stříbrná jedna, sedmdesáti lotů ztíží vedlé lotu svatyně; obě dvě nádoby plné mouky bělné, olejem zadělané k oběti suché;');
