INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 64, 'Kozel jeden za hřích;');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 65, 'A k oběti pokojné volové dva, skopců pět, kozlů pět, beránků ročních pět. Ten byl dar Abidanův, syna Gedeonova.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 66, 'Desátého dne kníže synů Dan, Ahiezer, syn Amisaddai.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 67, 'Obět jeho misa stříbrná jedna, jejížto váha byla sto třidceti lotů; báně stříbrná jedna, sedmdesáti lotů ztíží vedlé lotu svatyně; obě plné mouky bělné, olejem zadělané k oběti suché;');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 68, 'Kadidlnice jedna z desíti lotů zlata, plná kadidla;');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 69, 'Volek jeden mladý, skopec jeden, beránek roční jeden k oběti zápalné;');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 70, 'Kozel jeden za hřích;');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 71, 'A k oběti pokojné volové dva, skopců pět, kozlů pět, a beránků ročních pět. Ten byl dar Ahiezera, syna Amisaddai.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 72, 'Jedenáctého dne kníže synů Asser, Fegiel, syn Ochranův.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 73, 'Obět jeho misa stříbrná jedna, jejížto váha byla sto třidceti lotů; báně stříbrná jedna, sedmdesáti lotů ztíží vedlé lotu svatyně; obě dvě nádoby plné mouky bělné, olejem zadělané k oběti suché;');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 74, 'Kadidlnice jedna z desíti lotů zlata, plná kadidla;');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 75, 'Volek jeden mladý, skopec jeden, beránek roční jeden k oběti zápalné;');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 76, 'Kozel jeden za hřích;');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 77, 'A k oběti pokojné volové dva, skopců pět, kozlů pět, beránků ročních pět. Ten byl dar Fegiele, syna Ochranova.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 78, 'Dvanáctého dne kníže synů Neftalím, Ahira, syn Enanův.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 79, 'Obět jeho byla misa stříbrná jedna, jejížto váha byla sto třidceti lotů; báně stříbrná jedna, sedmdesáti lotů ztíží vedlé lotu svatyně; obě dvě nádoby plné mouky bělné, olejem zadělané k oběti suché;');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 80, 'Kadidlnice jedna z desíti lotů zlata, plná kadidla;');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 81, 'Volek mladý jeden, skopec jeden, beránek roční jeden k oběti zápalné;');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 82, 'Kozel jeden za hřích;');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 83, 'A k oběti pokojné volové dva, skopců pět, kozlů pět, beránků ročních pět. Ta byla obět Ahiry, syna Enanova.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 84, 'Toť jest posvěcení oltáře (toho dne, když pomazán jest,) od knížat Izraelských: Mis stříbrných dvanácte, bání stříbrných dvanácte, kadidlnic zlatých dvanácte.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 85, 'Sto třidceti lotů vážila jedna misa stříbrná, a sedmdesáte báně jedna; všecko nádobí stříbrné vážilo dva tisíce a čtyři sta lotů na lot svatyně.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 86, 'Kadidlnic zlatých dvanácte, plných kadidla; deset lotů vážila každá kadidlnice na váhu svatyně. Všecky kadidlnice zlaté sto a dvadceti lotů vážily.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 87, 'Všeho dobytka k oběti zápalné dvanácte volků, skopců dvanácte, beránků ročních dvanácte s obětí jejich suchou, a kozlů dvanácte za hřích.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 88, 'Všeho pak dobytka k oběti pokojné čtyřmecítma volů, skopců šedesáte, kozlů šedesáte, beránků ročních šedesáte. To bylo posvěcení oltáře, když pomazán byl.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 89, 'Potom když vcházel Mojžíš do stánku úmluvy, aby mluvil s Bohem, tedy slýchal hlas mluvícího k sobě z slitovnice, kteráž byla nad truhlou svědectví mezi dvěma cherubíny, a mluvíval k němu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 1, 'I mluvil Hospodin k Mojžíšovi, řka:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 2, 'Mluv k Aronovi a rci jemu: Když rozsvěcovati budeš lampy, ven z svícnu sedm lamp svítiti má.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 3, 'I učinil Aron tak; ven z svícnu světlo od sebe dávající rozsvítil lampy jeho, jakož přikázal Hospodin Mojžíšovi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 4, 'Bylo pak dílo svícnu takové: Z taženého zlata byl všecken, až i sloupec jeho i květové jeho z taženého zlata byli; podlé podobenství toho, kteréž ukázal Hospodin Mojžíšovi, tak udělal svícen.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 5, 'Mluvil také Hospodin k Mojžíšovi, řka:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 6, 'Vezmi Levíty z prostředku synů Izraelských, a očisť je.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 7, 'Tímto pak způsobem očišťovati je budeš: Pokropíš jich vodou očištění; oholí všecko tělo své, a zperou roucha svá, a očištěni budou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 8, 'Potom vezmou volka mladého a obět suchou z mouky bělné, olejem skropené; a druhého volka mladého vezmeš k oběti za hřích.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 9, 'Tedy přistoupiti rozkážeš Levítům před stánek úmluvy, a shromáždíš všecko množství synů Izraelských.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 10, 'Postavíš Levíty před Hospodinem, a vloží synové Izraelští ruce své na Levíty.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 11, 'A obětovati bude Aron Levíty v obět před Hospodinem od synů Izraelských, aby vykonávali službu Hospodinu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 12, 'Levítové pak vloží ruce své na hlavy těch volků; a obětovati budeš jednoho za hřích, a druhého v obět zápalnou Hospodinu k očištění Levítů.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 13, 'A postavíš Levíty před Aronem a před syny jeho, a obětovati je budeš v obět Hospodinu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 14, 'I oddělíš Levíty z prostředku synů Izraelských, aby moji byli Levítové.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 15, 'Potom pak přijdou Levítové, aby přisluhovali při stánku úmluvy, když bys očistil je a obětoval v obět.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 16, 'Nebo vlastně dáni jsou mi z prostředku synů Izraelských za všecky otvírající život, za prvorozené ze všech synů Izraelských vzal jsem je sobě.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 17, 'Nebo mé jest všecko prvorozené mezi syny Izraelskými, tak z lidí jako z hovad; od toho dne, jakž jsem pobil všecko prvorozené v zemi Egyptské, posvětil jsem jich sobě.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 18, 'Vzal jsem pak Levíty za všecky prvorozené synů Izraelských.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 19, 'A dal jsem Levíty darem Aronovi i synům jeho z prostředku synů Izraelských, aby konali službu místo synů Izraelských při stánku úmluvy, a očišťovali od hříchů syny Izraelské; a tak nepřijde na syny Izraelské rána, kteráž by přišla, kdyby přistupovali synové Izraelští k svatyni.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 20, 'I učinili Mojžíš a Aron i všecko množství synů Izraelských při Levítích všecko to, což přikázal Hospodin Mojžíšovi o Levítích; tak s nimi učinili synové Izraelští.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 21, 'A očistili se Levítové a zeprali roucha svá; a obětoval je Aron v obět před Hospodinem, a očistil je Aron, aby byli čisti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 22, 'Potom teprv přistoupili Levítové k vykonávání služby své při stánku úmluvy, před Aronem i před syny jeho; jakž přikázal Hospodin Mojžíšovi o Levítích, tak s nimi učinili.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 23, 'I mluvil opět Hospodin k Mojžíšovi, řka:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 24, 'I toto k Levítům přináleží: V pětmecítma letech zstáří a výše jeden každý z nich přistoupí, a postaví se k ochotnému práce konání v službě při stánku úmluvy.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 25, 'V padesáti pak letech přestane od práce služby té, a více přisluhovati nebude.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 26, 'Ale přisluhovati bude bratřím svým při stánku úmluvy stráž držícím, sám pak služeb konati nebude. Tak učiníš s Levíty při pracech jejich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 1, 'Mluvil pak Hospodin k Mojžíšovi na poušti Sinai, léta druhého po vyjití z země Egyptské, měsíce prvního, řka:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 2, 'Slaviti budou synové Izraelští velikunoc v čas svůj vyměřený.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 3, 'Čtrnáctého dne měsíce toho u večer budete ji slaviti jistým časem svým, vedlé všech ustanovení jejích, a podlé všech řádů jejích slaviti ji budete.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 4, 'I mluvil Mojžíš k synům Izraelským, aby slavili Fáze.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 5, 'Tedy slavili Fáze v měsíci prvním, čtrnáctého dne u večer na poušti Sinai; vedlé všeho toho, což přikázal Hospodin Mojžíšovi, tak učinili synové Izraelští.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 6, 'I byli někteří muži, ješto se poškvrnili při mrtvém, kteříž nemohli slaviti Fáze toho dne. I přistoupili před Mojžíše a Arona v ten den,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 7, 'A promluvili muži ti k němu: My jsme se poškvrnili nad mrtvým. Nebude-liž nám zbráněno obětovati oběti Hospodinu v jistý čas spolu s syny Izraelskými?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 8, 'I řekl jim Mojžíš: Počekejte, až uslyším, co vám učiniti rozkáže Hospodin.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 9, 'Mluvil pak Hospodin k Mojžíšovi, řka:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 10, 'Mluv k synům Izraelským a rci: Kdož by koli byl poškvrněný nad mrtvým, aneb byl by na cestě daleké, buď z vás aneb z potomků vašich, budeť slaviti Fáze Hospodinu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 11, 'Měsíce druhého, čtrnáctého dne u večer slaviti budou je, s chleby nekvašenými, a s řeřichami jísti je budou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 12, 'Nezanechajíť ho nic až do jitra, a kosti v něm nezlámí; vedlé všelikého ustanovení Fáze budou je slaviti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 13, 'Ale člověk ten, kterýž by byl čistý, a nebyl na cestě, a však by zanedbal slaviti Fáze, vyhlazena bude duše ta z lidu svého; nebo oběti Hospodinu neobětoval v jistý čas její; hřích svůj ponese člověk ten.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 14, 'Jestliže by s vámi bydlil příchozí, a slavil by Fáze Hospodinu, vedlé ustanovení Fáze, a vedlé řádu jeho bude je slaviti. Ustanovení jednostejné bude vám, tak příchozímu, jako obyvateli v zemi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 15, 'Toho pak dne, v kterémž vyzdvižen jest příbytek, přikryl oblak příbytek, a stál nad stánkem svědectví; u večer pak bývalo nad příbytkem na pohledění jako oheň až do jitra.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 16, 'Tak bývalo ustavičně, oblak přikrýval jej ve dne, záře pak ohnivá v noci.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 17, 'A když se zdvihl oblak od stánku, hned také hýbali se synové Izraelští; a na kterém místě pozůstal oblak, tu také kladli se synové Izraelští.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 18, 'K rozkazu Hospodinovu hýbali se synové Izraelští, a k rozkazu Hospodinovu kladli se; po všecky dny, dokudž zůstával oblak nad příbytkem, i oni leželi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 19, 'Když pak trval oblak nad příbytkem po mnohé dny, tedy drželi synové Izraelští stráž Hospodinovu, a netáhli odtud.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 20, 'A když oblak byl nad příbytkem po nemnohé dny, k rozkazu Hospodinovu kladli se, a k rozkazu Hospodinovu hýbali se.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 21, 'Kdyžkoli byl oblak od večera až do jitra, a v jitře se vznesl, hned i oni šli; buď že trval přes den a noc, (jakž kdy vznášel se oblak, tak oni táhli,)');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 22, 'Buď že za dva dni, aneb za měsíc, aneb za rok prodléval oblak nad příbytkem, zůstávaje nad ním, synové Izraelští také leželi, a nehnuli se; když pak on vznášel se, též i oni táhli.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 23, 'K rozkazu Hospodinovu kladli se, a k rozkazu Hospodinovu hýbali se, stráž Hospodinovu držíce podlé rozkazu jeho skrze Mojžíše.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 1, 'I mluvil Hospodin k Mojžíšovi, řka:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 2, 'Udělej sobě dvě trouby stříbrné. Dílem taženým uděláš je, kterýchž užívati budeš k svolání všeho množství, a když by se mělo hnouti vojsko.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 3, 'Protož kdyžkoli zatroubí na ně, shromáždí se k tobě všecko množství ke dveřím stánku úmluvy.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 4, 'Jestliže v jednu toliko zatroubí, tedy shromáždí se k tobě knížata, přední lidu Izraelského.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 5, 'Pakli by s nějakým přetrubováním troubili, hnou se s místa, kteříž leželi k východní straně.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 6, 'Když by pak troubili s přetrubováním po druhé, tedy hnou se ti, kteříž leželi ku poledni. S přetrubováním troubiti budou k tažení svému.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 7, 'Ale když byste měli svolati všecko množství, prostě bez přetrubování troubiti budete.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 8, 'Synové Aronovi kněží trubami těmi budou troubiti, a bude vám to ustanovení věčné v pronárodech vašich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 9, 'Když vyjdete na vojnu v zemi vaší proti nepříteli ssužujícímu vás, s přetrubováním troubiti budete v trouby ty, a budete v paměti před Hospodinem Bohem svým, a zachováni budete od nepřátel svých.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 10, 'V den také veselí vašeho, a při slavnostech svých, a při začátcích měsíců vašich troubiti budete v trouby ty k obětem svým zápalným a pokojným, i budou vám na památku před Bohem vaším: Já Hospodin Bůh váš.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 11, 'I stalo se léta druhého, dvadcátý den měsíce druhého, že se vyzdvihl oblak z příbytku svědectví.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 12, 'I táhli synové Izraelští po svých taženích z pouště Sinai; a zastavil se oblak na poušti Fáran.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 13, 'Takto nejprvé brali se z rozkazu Hospodinova skrze Mojžíše:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 14, 'Šla napřed korouhev vojska synů Juda po houfích svých, a nad nimi byl Názon, syn Aminadabův.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 15, 'Nad vojskem pak pokolení synů Izachar byl Natanael, syn Suar.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 16, 'A nad vojskem pokolení synů Zabulon Eliab, syn Helonův.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 17, 'Složen jest také i příbytek, a šli synové Gersonovi a synové Merari nesouce příbytek.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 18, 'Potom šla korouhev vojska Rubenova po houfích svých, a nad nimi byl Elisur, syn Sedeurův.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 19, 'Nad vojskem pak pokolení synů Simeon Salamiel, syn Surisaddai.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 20, 'A nad vojskem pokolení synů Gád Eliazaf, syn Duelův.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 21, 'Šli také i Kahatští, nesouce svatyni; onino pak vyzdvihovali příbytek, až i tito přišli.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 22, 'Potom šla korouhev vojska synů Efraim po houfích svých, a nad nimi byl Elisama, syn Amiudův.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 23, 'Nad vojskem pak pokolení synů Manasse Gamaliel, syn Fadasurův.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 24, 'A nad vojskem pokolení synů Beniamin Abidan, syn Gedeonův.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 25, 'Šla potom i korouhev vojska synů Dan, obsahující ostatek vojska po houfích svých, a nad vojskem jeho Ahiezer, syn Amisaddai.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 26, 'Nad vojskem pak pokolení synů Asser Fegiel, syn Ochranův.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 27, 'A nad vojskem pokolení synů Neftalím Ahira, syn Enanův.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 28, 'Ta jsou tažení synů Izraelských po houfích jejich, a tím pořádkem táhli.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 29, 'Řekl pak Mojžíš Chobabovi, synu Raguelovu Madianskému, tchánu svému: My se béřeme k místu, o kterémž řekl Hospodin: Dám je vám. Protož poď s námi, a dobře učiníme tobě; nebo Hospodin mnoho dobrého zaslíbil Izraelovi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 30, 'Kterýž odpověděl jemu: Nepůjdu, ale k zemi své a k příbuznosti své se navrátím.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 31, 'I řekl Mojžíš: Neopouštěj medle nás; nebo ty jsi svědom na poušti, kde bychom se měli klásti, a budeš nám za vůdce.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 32, 'Když pak půjdeš s námi, a přijde to dobré, jímž dobře učiní nám Hospodin, tedy i tobě dobře učiníme.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 33, 'A tak brali se od hory Hospodinovy cestou tří dnů, (a truhla smlouvy Hospodinovy předcházela je,) cestou tří dnů, pro vyhlédání sobě místa k odpočinutí.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 34, 'A oblak Hospodinův byl nad nimi ve dne, když se hýbali z ležení.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 35, 'Když pak počínali jíti s truhlou, říkával Mojžíš: Povstaniž Hospodine, a rozptýleni buďte nepřátelé tvoji, a ať utíkají před tváří tvou, kteříž tě v nenávisti mají.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 36, 'Když pak stavína byla, říkával: Navratiž se, Hospodine, k desíti tisícům tisíců Izraelských.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 1, 'I stalo se, že lid ztěžoval a stýskal sobě, což se nelíbilo Hospodinu. Protož, slyše to Hospodin, rozhněval se náramně, a roznítil se proti nim oheň Hospodinův, a spálil zadní díl vojska.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 2, 'Tedy volal lid k Mojžíšovi. I modlil se Mojžíš Hospodinu, a uhasl oheň.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 3, 'I nazval jméno místa toho Tabbera; nebo rozpálil se proti nim oheň Hospodinův.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 4, 'Lid pak k nim přimíšený napadla žádost náramná; a obrátivše se, plakali i synové Izraelští a řekli: Kdo nám to dá, abychom se masa najedli?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 5, 'Rozpomínáme se na ryby, jichž jsme dosti v Egyptě darmo jídali, na okurky a melouny, též na por, cibuli a česnek.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 6, 'A nyní duše naše vyprahlá, nic jiného nemá, kromě tu mannu před očima svýma.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 7, '(Manna pak byla jako semeno koliandrové, a barva její jako barva bdelium.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 8, 'I vycházíval lid, a sbírali a mleli žernovy, neb tloukli v moždířích, a smažili na pánvici, aneb koláče podpopelné dělali z ní; chut pak její byla jako chut nového oleje.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 9, 'Když pak sstupovala rosa na vojsko v noci, tedy sstupovala také i manna.)');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 10, 'Tedy uslyšel Mojžíš, an lid pláče po čeledech svých, každý u dveří stanu svého. Pročež roznítila se prchlivost Hospodinova náramně; Mojžíšovi to také těžké bylo.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 11, 'I řekl Mojžíš Hospodinu: Proč jsi tak zle učinil služebníku svému? Proč jsem nenalezl milosti před očima tvýma, že jsi vložil břímě všeho lidu tohoto na mne?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 12, 'Zdaliž jsem já počal všecken lid tento? Zdali jsem já zplodil jej, že mi díš: Nes jej na rukou svých, jako nosí chůva děťátko, do země té, kterouž jsi s přísahou zaslíbil otcům jejich?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 13, 'Kde mám nabrati masa, abych dal všemu lidu tomuto? Nebo plačí na mne, řkouce: Dej nám masa, ať jíme.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 14, 'Nemohuť já sám nésti všeho lidu tohoto, nebo jest to nad možnost mou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 15, 'Pakli mi tak dělati chceš, prosím, zabí mne raději, jestliže jsem nalezl milost před očima tvýma, abych více nehleděl na trápení své.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 16, 'Tedy řekl Hospodin Mojžíšovi: Shromažď mi sedmdesáte mužů z starších Izraelských, kteréž znáš, že jsou starší v lidu a správcové jeho; i přivedeš je ke dveřím stánku úmluvy, a státi budou tam s tebou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 17, 'A já sstoupím a mluviti budu s tebou, a vezmu z ducha, kterýž jest na tobě, a dám jim. I ponesou s tebou břímě lidu, a tak ty ho sám neponeseš.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 18, 'Lidu pak díš: Posvěťtež se k zítřku, a budete jísti maso; nebo jste plakali v uších Hospodinových, řkouce: Kdo nám dá najísti se masa? Jistě že lépe nám bylo v Egyptě. I dá vám Hospodin masa, a budete jísti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 19, 'Nebudete toliko jeden den jísti, ani dva, ani pět, ani deset, ani dvadcet,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 20, 'Ale za celý měsíc, až vám chřípěmi poleze, a zoškliví se, proto že jste pohrdli Hospodinem, kterýž jest u prostřed vás, a plakali jste před ním, říkajíce: Proč jsme vyšli z Egypta?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 21, 'I řekl Mojžíš: Šestkrát sto tisíců pěších jest tohoto lidu, mezi nimiž já jsem, a ty pravíš: Dám jim masa, aby jedli za celý měsíc.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 22, 'Zdali ovcí a volů nabije se jim, aby jim postačilo? Aneb zdali všecky ryby mořské shromáždí se jim, aby jim dosti bylo?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 23, 'Tedy řekl Hospodin Mojžíšovi: Zdali ruka Hospodinova ukrácena jest? Již nyní uzříš, přijde-li na to, což jsem mluvil, čili nic.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 24, 'Vyšed tedy Mojžíš, mluvil lidu slova Hospodinova, a shromáždiv sedmdesáte mužů z starších lidu, postavil je vůkol stánku.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 25, 'I sstoupil Hospodin v oblaku a mluvil k němu, a vzav z ducha, kterýž byl na něm, dal sedmdesáti mužům starším. I stalo se, když odpočinul na nich ten duch, že prorokovali, ale potom nikdy více.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 26, 'Byli pak zůstali v staních dva muži, jméno jednoho Eldad, a druhého Medad, na nichž také odpočinul duch ten, nebo i oni napsáni byli, ačkoli nevyšli k stánku. I ti také prorokovali v staních.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 27, 'Tedy přiběh služebník, oznámil to Mojžíšovi, řka: Eldad a Medad prorokují v staních.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 28, 'Jozue pak, syn Nun, služebník Mojžíšův, jeden z mládenců jeho, dí k tomu: Pane můj, Mojžíši, zabraň jim.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 29, 'Jemuž odpověděl Mojžíš: Proč ty horlíš pro mne? Nýbrž ó kdyby všecken lid Hospodinův proroci byli, a aby dal Hospodin ducha svého na ně!');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 30, 'I navrátil se Mojžíš do stanů s staršími Izraelskými.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 31, 'Tedy strhl se vítr od Hospodina, a zachvátiv křepelky od moře, spustil je na stany tak široce a dlouze, co by mohl za jeden den cesty ujíti všudy vůkol táboru, takměř na dva lokty zvýší nad zemí.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 32, 'Protož vstav lid, celý ten den a celou noc, i celý druhý den shromažďovali sobě ty křepelky; a kdož nejméně nashromáždil, měl jich s deset měr. I rozvěšeli je sobě pořád okolo stanů.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 33, 'Ještě maso vězelo v zubích jejich, a nebylo právě sžvýkáno, když hněv Hospodinův vzbudil se na lid. I ranil Hospodin lid ranou velikou náramně.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 34, 'Protož nazváno jest jméno místa toho Kibrot Hattáve; nebo tu pochovali lid, kterýž žádal masa.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 35, 'I bral se lid z Kibrot Hattáve na poušť Hazerot, a pozůstali v Hazerot.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 1, 'A mluvila Maria i Aron proti Mojžíšovi příčinou manželky Madianky, kterouž sobě vzal; nebo byl pojal manželku Madianku.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 2, 'A řekli: Zdaliž jen toliko skrze Mojžíše mluvil Hospodin? Zdaž také nemluvil skrze nás? I slyšel to Hospodin.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 3, '(Byl pak Mojžíš člověk nejtišší ze všech lidí, kteříž byli na tváři země.)');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 4, 'A i hned řekl Hospodin Mojžíšovi a Aronovi i Marii: Vyjděte vy tři k stánku úmluvy. I vyšli toliko oni tři.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 5, 'Tedy sstoupil Hospodin v sloupu oblakovém, a stál u dveří stánku. I zavolal Arona a Marie, a vyšli oba dva.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 6, 'Jimž řekl: Slyšte nyní slova má: Prorok když jest mezi vámi, já Hospodin u vidění ukáži se jemu, ve snách mluviti budu s ním.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 7, 'Ale není takový služebník můj Mojžíš, kterýž ve všem domě mém věrný jest.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 8, 'Ústy k ústům mluvím s ním, ne u vidění, ani v zavinutí, a podobnost Hospodinovu spatřuje. Pročež jste tedy neostýchali se mluviti proti služebníku mému Mojžíšovi?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 9, 'I roznícena jest prchlivost Hospodinova na ně, a odšel.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 10, 'Oblak také zdvihl se s stánku. A aj, Maria byla malomocná, bílá jako sníh. A pohleděl Aron na Marii, ana malomocná.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 11, 'Tedy řekl Aron Mojžíšovi: Poslyš mne, pane můj, prosím, nevzkládej na nás té pokuty za hřích ten, jehož jsme se bláznivě dopustili, a jímž jsme zhřešili.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 12, 'Prosím, ať není tato jako mrtvý plod, kterýž když vychází z života matky své, polovici těla jeho zkaženého bývá.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 13, 'I volal Mojžíš k Hospodinu, řka: Ó Bože silný, prosím, uzdraviž ji.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 14, 'Odpověděl Hospodin Mojžíšovi: Kdyby otec její plinul jí na tvář, zdaž by se nemusila styděti za sedm dní? Protož ať jest vyobcována ven z stanů za sedm dní, a potom zase uvedena bude.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 15, 'Tedy vyloučena jest Maria ven z stanů za sedm dní; a lid nehnul se odtud, až zase uvedena jest Maria.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 16, 'Potom pak bral se lid z Hazerot, a položil se na poušti Fáran.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 1, 'I mluvil Hospodin k Mojžíšovi, řka:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 2, 'Pošli sobě muže, kteříž by spatřili zemi Kananejskou, kterouž já dám synům Izraelským; jednoho muže z každého pokolení otců jejich vyšlete, ty, kteříž by byli přednější mezi nimi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 3, 'Poslal je tedy Mojžíš z pouště Fáran, jakž byl rozkázal Hospodin; a všickni ti muži byli knížata mezi syny Izraelskými.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 4, 'Tato jsou pak jména jejich: Z pokolení Ruben Sammua, syn Zakurův;');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 5, 'Z pokolení Simeon Safat, syn Huri;');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 6, 'Z pokolení Juda Kálef, syn Jefonův;');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 7, 'Z pokolení Izachar Igal, syn Jozefův;');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 8, 'Z pokolení Efraim Ozeáš, syn Nun;');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 9, 'Z pokolení Beniamin Falti, syn Rafův;');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 10, 'Z pokolení Zabulon Gaddehel, syn Sodi;');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 11, 'Z pokolení Jozef a z pokolení Manasses Gaddi, syn Susi;');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 12, 'Z pokolení Dan Amiel, syn Gemalův;');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 13, 'Z pokolení Asser Setur, syn Michaelův;');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 14, 'Z pokolení Neftalím Nahabi, syn Vafsi;');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 15, 'Z pokolení Gád Guhel, syn Máchův;');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 16, 'Ta jsou jména mužů, kteréž poslal Mojžíš, aby shlédli zemi. I přezděl Mojžíš Ozeovi, synu Nun, Jozue.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 17, 'Tedy poslal je Mojžíš, aby prohlédli zemi Kananejskou, a řekl jim: Jděte tudyto při straně polední a vejděte na hory.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 18, 'A shlédněte, jaká jest země ta, i lid, kterýž bydlí v ní, silný-li jest či mdlý? málo-li jich, či mnoho?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 19, 'A jaká jest též země ta, v níž on bydlí, dobrá-li jest, či zlá? a jaká jsou města, v nichž přebývají, v staních-li, či v hrazených místech?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 20, 'Tolikéž jaká jest země, úrodná-li, či neúrodná, jest-li na ní stromoví, či není? A buďte udatné mysli, a přineste nám z ovoce té země. A byl tehdáž čas, v němžto hroznové zaměkali.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 21, 'Odšedše tedy, prohlédli tu zemi od pouště Tsin až do Rohob, kudy se jde do Emat.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 22, 'I šli stranou polední, a přišli až do Hebronu, kdežto byli Achiman a Sesai a Tolmai, synové Enakovi. Hebron pak o sedm let prvé ustaveno jest, nežli Soan, město Egyptské.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 23, 'Potom přišli až do údolí Eškol, a tu uřezali ratolest s hroznem jedním jahodek plným, a nesli jej na sochoře dva; též i jablka zrnatá i fíky té země.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 24, 'I nazváno jest to místo Nehel Eškol, od hroznu, kterýž tu uřezali synové Izraelští.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 25, 'Navrátili se pak zase, prošedše zemi, po čtyřidcíti dnech.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 26, 'A jdouce, přišli k Mojžíšovi a k Aronovi i ke všemu množství synů Izraelských, na poušti Fáran v Kádes, a oznámili jim i všemu množství to, co spravili, a ukázali jim ovoce země té.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 27, 'A vypravujíce jim, řekli: Přišli jsme do země, do kteréž jsi nás poslal, kteráž v pravdě oplývá mlékem a strdí, a toto jest ovoce její.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 28, 'Než že lid jest silný, kterýž bydlí v zemi té, města také pevná jsou a veliká velmi, k tomu i syny Enakovy tam jsme viděli.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 29, 'Amalech bydlí v kraji poledním, a Hetejský, Jebuzejský a Amorejský bydlejí na horách, Kananejský pak bydlí při moři a při břehu Jordánském.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 30, 'I krotil Kálef lid bouřící se proti Mojžíšovi, a mluvil: Jděme předce, a opanujme zemi, nebo zmocníme se jí.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 31, 'Ale muži ti, kteříž chodili s ním, pravili: Nikoli nebudeme moci vstoupiti proti lidu tomu, nebo silnější jest nežli my.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 32, 'I zhaněli a zošklivili zemi shlédnutou synům Izraelským, mluvíce: Země, již jsme prošli a spatřili, jest země taková, ješto hubí obyvatele své; a všecken lid, kterýž jsme viděli u prostřed ní, jsou muži postavy vysoké velmi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 33, 'Také jsme tam viděli obry, syny Enakovy, kteříž jsou větší než jiní obrové, ješto se nám zdálo, že jsme proti nim jako kobylky, a takoví jsme se i jim zdáli.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 1, 'Tehdy pozdvihše se všecko množství, křičeli, a plakal lid v tu noc.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 2, 'A reptali proti Mojžíšovi i proti Aronovi všickni synové Izraelští, a řeklo k nim všecko množství: Ó bychom byli zemřeli v zemi Egyptské, aneb na této poušti, ó bychom byli zemřeli!');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 3, 'A proč Hospodin vede nás do země té, abychom padli od meče, ženy naše i dítky naše aby byly v loupež? Není-liž nám lépe navrátiti se zase do Egypta?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 4, 'I řekli jeden druhému: Ustanovme sobě vůdci, a navraťme se do Egypta.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 5, 'Tedy padli Mojžíš a Aron na tváři své přede vším množstvím shromáždění synů Izraelských.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 6, 'Jozue pak, syn Nun, a Kálef, syn Jefonův, z těch, kteříž byli shlédli zemi, roztrhli roucha svá,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 7, 'A mluvili ke všemu množství synů Izraelských, řkouce: Země, kterouž jsme prošli a vyšetřili, jest země velmi velice dobrá.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 8, 'Bude-li Hospodin laskav na nás, uvedeť nás do země té, a dá ji nám, a to zemi takovou, kteráž oplývá mlékem a strdí.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 9, 'Toliko nepozdvihujte se proti Hospodinu, ani se bojte lidu země té, nebo jako chléb náš jsou. Odešlatě od nich ochrana jejich, ale s námi jest Hospodin; nebojtež se jich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 10, 'Tedy mluvilo všecko množství, aby je kamením uházeli, ale sláva Hospodinova ukázala se nad stánkem úmluvy všechněm synům Izraelským.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 11, 'I řekl Hospodin Mojžíšovi: I dokavadž popouzeti mne bude lid ten? A dokud nebudou mi věřiti pro tak mnohá znamení, kteráž jsem činil u prostřed nich?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 12, 'Raním jej morem a rozženu jej, tebe pak učiním v národ veliký a silnější, nežli jest tento.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 13, 'I řekl Mojžíš Hospodinu: Ale uslyšíť to Egyptští, z jejichž prostředku vyvedl jsi lid tento v síle své,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 14, 'A řeknou s obyvateli země té: (nebo slyšeli, že jsi ty, ó Hospodine, byl u prostřed lidu tohoto, a že jsi okem v oko spatřován byl, ó Hospodine, a oblak tvůj stál nad nimi, a v sloupě oblakovém předcházel jsi je ve dne, a v sloupě ohnivém v noci),');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 15, 'Když tedy zmoříš lid ten, všecky až do jednoho, mluviti budou národové, kteříž slyšeli pověst o tobě, říkajíce:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 16, 'Proto že nemohl Hospodin uvésti lidu toho do země, kterouž jim s přísahou zaslíbil, zmordoval je na poušti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 17, 'Nyní tedy, prosím, nechať jest zvelebena moc Páně, jakož jsi mluvil, řka:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 18, 'Hospodin dlouhočekající a hojný v milosrdenství, odpouštějící nepravost a přestoupení, kterýž však z vinného nečiní nevinného, ale navštěvuje nepravost otců na synech do třetího i čtvrtého pokolení.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 19, 'Odpusť, prosím, nepravost lidu tohoto podlé velikého milosrdenství svého, tak jako jsi odpouštěl lidu tomuto, jakž vyšel z Egypta až dosavad.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 20, 'I řekl Hospodin: Odpustil jsem vedlé slova tvého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 21, 'A však živ jsem já, a sláva má naplňuje všecku zemi,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 22, 'Že všickni ti, kteříž viděli slávu mou a znamení má, kteráž jsem činil v Egyptě a na poušti této, a kteříž pokoušeli mne již desetkrát, aniž uposlechli hlasu mého,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 23, 'Neuzří země té, kterouž jsem s přísahou zaslíbil otcům jejich, aniž jí kdo z těch, kteříž mne popouzeli, uhlédá.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 24, 'Ale služebníka svého Kálefa, (nebo v něm byl jiný duch, a cele následoval mne,) uvedu jej do země, do kteréž chodil, a símě jeho dědičně obdrží ji.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 25, 'Ale poněvadž Amalechitský a Kananejský bydlí v tom údolí, obraťte se zase zítra, a beřte se na poušť cestou k moři Rudému.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 26, 'Mluvil také Hospodin k Mojžíšovi a Aronovi, řka:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 27, 'Až dokud snášeti budu množství toto zlé, kteréž repce proti mně? Až dokud reptání synů Izraelských, kteříž repcí proti mně, slyšeti budu?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 28, 'Rci jim: Živ jsem já, praví Hospodin, žeť vám učiním tak, jakž jste mluvili v uši mé:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 29, 'Na poušti této padnou mrtvá těla vaše, a všickni, kteříž jste sečteni, podlé všeho počtu vašeho od majících let dvadceti a výše, kteříž jste reptali proti mně,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 30, 'Nevejdete, pravím, vy do země, o kteréž, zdvihna ruku svou, přisáhl jsem, že vás osadím v ní, jediné Kálef, syn Jefonův, a Jozue, syn Nun.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 31, 'Ale dítky vaše malé, o nichž jste řekli, že v loupež budou, ty uvedu, aby užívali země té, kterouž jste vy pohrdli.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 32, 'Těla pak vaše mrtvá padnou na poušti této.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 33, 'A synové vaši budou tuláci na poušti této čtyřidceti let, a ponesou pokutu smilství vašeho, až do konce vyhynou těla vaše na poušti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 34, 'Podlé počtu dnů, v nichž jste procházeli zemi tu, totiž čtyřidceti dnů, jeden každý den za rok počítaje, ponesete nepravosti své čtyřidceti let, a poznáte pomstu svého odtržení se ode mne.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 35, 'Já Hospodin mluvil jsem, že to učiním všemu tomuto množství zlému, kteréž se zrotilo proti mně; na poušti této do konce zhynou, a tu zemrou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 36, 'Muži pak ti, kteréž poslal byl Mojžíš k shlédnutí země té, a kteříž, navrátivše se, uvedli v reptání proti němu všecko množství to, haněním ošklivíce zemi,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 37, 'Ti, řku, muži, kteříž haněli zemi, ranou těžkou zemřeli před Hospodinem.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 38, 'Jozue pak, syn Nun, a Kálef, syn Jefonův, živi zůstali z mužů těch, kteříž chodili k vyšetření země.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 39, 'Tedy mluvil Mojžíš slova ta ke všechněm synům Izraelským; i plakal lid velmi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 40, 'A vstavše ráno, vstoupili na vrch hory, a řekli: Aj, my hotovi jsme, abychom šli k místu, o němž mluvil Hospodin; nebo jsme zhřešili.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 41, 'Jimž řekl Mojžíš: Proč jest to, že vy přestupujete přikázaní Hospodinovo? ješto vám to na dobré nevyjde.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 42, 'Nevstupujte, nebo Hospodin není u prostřed vás, abyste nebyli poraženi od nepřátel vašich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 43, 'Amalechitský zajisté a Kananejský jest tu před vámi, a padnete od meče, proto že jste se odvrátili od následování Hospodina, aniž také Hospodin bude s vámi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 44, 'Oni pak předce usilovali vstoupiti na vrch hory, ale truhla smlouvy Hospodinovy a Mojžíš nevycházeli z stanů.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 45, 'Tedy sstoupili Amalechitský a Kananejský, kteříž bydlili na těch horách, a porazili je, a potírali je až do Horma.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 1, 'Mluvil opět Hospodin k Mojžíšovi, řka:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 2, 'Mluv k synům Izraelským a rci jim: Když vejdete do země přebývání vašich, kterouž já dám vám,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 3, 'A budete chtíti obětovati obět ohnivou Hospodinu v zápal, aneb obět buď slíbenou, buď dobrovolnou, aneb při slavnostech vašich, abyste učinili vůni spokojující Hospodina, buďto z skotů, aneb z drobného dobytku:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 4, 'Tedy kdož by koli obětoval dar svůj Hospodinu, obětuj obět suchou, desátý díl efi mouky bělné, zadělané olejem, jehož bude čtvrtý díl míry hin.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 5, 'A vína v obět mokrou čtvrtinku hin obětovati budeš při zápalu, aneb při oběti vítězné k jednomu každému beránku.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 6, 'Při beranu pak obětovati budeš obět suchou, mouky bělné dvě desetiny, zadělané olejem, třetinkou míry hin.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 7, 'Vína také k oběti mokré třetí díl míry hin obětovati budeš u vůni spokojující Hospodina.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 8, 'Jestliže pak obětovati budeš volka v obět zápalnou, aneb v obět k splnění slibu, aneb v obět pokojnou Hospodinu:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 9, 'Tedy budeš obětovati spolu s volkem obět suchou, tři desetiny mouky bělné, zadělané olejem, jehož by byla půlka hin.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 10, 'A vína k oběti mokré obětovati budeš půlku hin. Ta jest obět ohnivá vůně spokojující Hospodina.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 11, 'Tak uděláte s každým volem i s každým skopcem, i s dobytčetem, buď ono z ovec neb z koz.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 12, 'Podlé toho, jakž mnoho jich obětovati budete, tak se zachováte při jednom každém z nich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 13, 'Všeliký obyvatel tak bude to vykonávati, aby obětoval obět ohnivou vůně spokojující Hospodina.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 14, 'Takž bude-li u vás i příchozí, aneb kdokoli mezi vámi v pronárodech vašich, a bude obětovati obět ohnivou vůně spokojující Hospodina, jakž vy se při tom chováte, tak i on chovati se bude.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 15, 'V shromáždění tomto ustanovení jednostejné buď vám i příchozímu, kterýž by u vás byl, ustanovení věčné v pronárodech vašich; jakož vy, tak příchozí bude před Hospodinem.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 16, 'Zákon jednostejný a pořádek jednostejný bude vám i přichozímu, kterýž by u vás byl.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 17, 'Mluvil také Hospodin k Mojžíšovi, řka:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 18, 'Mluv k synům Izraelským a rci jim: Když přijdete do země, do kteréž já uvedu vás,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 19, 'Tedy, když počnete jísti chléb země, obětovati budete obět vzhůru pozdvižení Hospodinu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 20, 'Z prvotin těsta vašeho koláč obětovati budete v obět vzhůru pozdvižení; tak jako obět z humna, obětovati budete ji.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 21, 'Z prvotin těsta vašeho dávati budete Hospodinu obět vzhůru pozdvižení, vy i potomci vaši.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 22, 'A když byste pozbloudili, a neučinili všech přikázaní těch, kteráž mluvil Hospodin k Mojžíšovi,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 23, 'Totiž všech věcí, kteréž přikázal Hospodin vám skrze Mojžíše, od toho dne, v kterémž přikázaní vydal Hospodin, i potom v pronárodech vašich:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 24, 'Tedy jestliže z nedopatření všeho shromáždění to stalo se, obětovati bude všecko množství volka mladého jednoho v obět zápalnou, k vůni spokojující Hospodina, též obět suchou, a obět mokrou při něm podlé pořádku, a kozla jednoho v obět za hřích.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 25, 'I očistí kněz všecko množství synů Izraelských, a odpuštěno jim bude; nebo poblouzení jest. A oni také obětovati budou obět svou, obět ohnivou Hospodinu, a obět za hřích svůj před Hospodinem za poblouzení své.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 26, 'I bude odpuštěno všemu shromáždění synů Izraelských i příchozímu, kterýž jest pohostinu u prostřed nich; nebo všeho lidu poblouzení jest.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 27, 'Jestliže by pak člověk jeden zhřešil z poblouzení, bude obětovati kozu roční v obět za hřích.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 28, 'I očistí kněz duši pobloudilou, kteráž zhřešila poblouzením před Hospodinem; očistí ji, a budeť jí odpuštěno.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 29, 'Domácímu mezi syny Izraelskými i příchozímu, kterýž pohostinu mezi nimi jest, zákon tento jednostejný bude vám, když by kdo zhřešil z poblouzení.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 30, 'Člověk pak, kterýž by z pychu svévolně zhřešil, tak doma zrozený jako příchozí, takový potupil velice Hospodina; protož vyhlazen bude z prostředku lidu svého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 31, 'Nebo slovem Hospodinovým pohrdl, a přikázaní jeho za nic sobě položil; protož konečně vyhlazen bude člověk ten, a nepravost jeho zůstane na něm.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 32, 'Stalo se pak, když synové Izraelští byli na poušti, že nalezli jednoho, an sbírá dříví v den sobotní.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 33, 'A ti, kteříž ho nalezli sbírajícího dříví, přivedli jej k Mojžíšovi a k Aronovi i ke všemu množství.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 34, 'I dali jej do vězení; nebo ještě nebylo jim oznámeno, co by s ním mělo činěno býti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 35, 'I řekl Hospodin Mojžíšovi: Smrtí ať umře člověk ten; nechať ho bez milosti ukamenuje všecko množství vně za stany.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 36, 'A protož vyvedli jej všecko množství ven za stany, a uházeli ho kamením, až umřel, jakož rozkázal Hospodin.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 37, 'I mluvil Hospodin k Mojžíšovi, řka:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 38, 'Mluv k synům Izraelským a rci jim, ať sobě dělají třepení široké na podolcích oděvů svých všickni rodové jejich, a ať dávají nad třepením šňůrku modrou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 39, 'A to budete míti za premování, na něžto hledíce, rozpomínati se budete na všecka přikázaní Hospodinova, abyste je činili, a nepustíte se po žádosti srdce svého, a po očích svých, jichžto následujíce, smilnili byste,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 40, 'Ale abyste pamatovali a činili všecka přikázaní má, a byli svatí Bohu svému.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 41, 'Já jsem Hospodin Bůh váš, kterýž jsem vyvedl vás z země Egyptské, abych vám byl za Boha: Já Hospodin Bůh váš.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 1, 'Chóre pak syn Izarův, syna Kahat z pokolení Léví, vytrhl se z jiných, tolikéž Dátan a Abiron, synové Eliabovi, také Hon, syn Feletův, z synů Rubenových,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 2, 'A povstali proti Mojžíšovi, i jiných mužů z synů Izraelských dvě stě a padesáte, knížata shromáždění, kteříž svoláváni byli do rady, muži slovoutní.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 3, 'A sebravše se proti Mojžíšovi a proti Aronovi, řekli jim: Příliště to již na vás; všecko zajisté množství toto, všickni tito svatí jsou, a u prostřed nich jest Hospodin. Pročež se tedy vyzdvihujete nad shromážděním Hospodinovým?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 4, 'To když uslyšel Mojžíš, padl na tvář svou,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 5, 'A mluvil k Chóre a ke vší rotě jeho, řka: Ráno ukáže Hospodin, kdo jsou jeho, a kdo jest svatý, i kdo před něj předstupovati má; nebo kohožkoli vyvolil, tomu rozkáže přistoupiti k sobě.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 6, 'Toto učiňte: Vezměte sobě kadidlnice, ty Chóre i všecko shromáždění tvé,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 7, 'A naklaďte do nich uhlí, a vložte na ně kadidla před Hospodinem zítra; i stane se, že kohožkoli vyvolí Hospodin, ten bude svatý. Příliště to již na vás, synové Léví.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 8, 'I řekl Mojžíš k Chóre: Slyšte, prosím, synové Léví.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 9, 'Zdaliž málo vám to jest, že vás oddělil Bůh Izraelský ode všeho množství Izraelského, a rozkázal vám přistupovati k sobě, abyste vykonávali službu příbytku Hospodinova, a abyste stáli před shromážděním, a sloužili jim,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 10, 'A vzal tě sobě, a všecky bratří tvé syny Léví s tebou, a že ještě přes to i kněžství hledáte?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 11, 'Protož věz, že ty a všickni tvoji jste ti, kteříž se rotíte proti Hospodinu; nebo Aron co jest, že jste reptali proti němu?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 12, 'Tedy poslal Mojžíš, aby zavolali Dátana a Abirona, synů Eliabových. Kteříž odpověděli: Nepůjdem.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 13, 'Cožť se ještě málo zdá, že jsi vyvedl nás z země oplývající mlékem a strdí, abys nás zmořil na poušti, že také chceš i panovati nad námi, a rozkazovati nám?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 14, 'A ještě jsi nás neuvedl do země oplývající mlékem a strdí, aniž jsi nám dal v dědictví rolí a vinic. Zdali oči mužům těmto vyloupiti chceš? Nepůjdeme.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 15, 'I rozhněval se Mojžíš velmi, a řekl k Hospodinu: Nepatřiž na oběti jejich. Ani jednoho osla od nich jsem nevzal, aniž jsem komu z nich co zlého učinil.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 16, 'Potom řekl Mojžíš k Chóre: Ty a všickni tvoji, postavte se zítra před Hospodinem, ty i oni, též i Aron.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 17, 'A vezmouce jeden každý kadidlnici svou, dáte do nich kadidla, a postavíte se před Hospodinem, jeden každý s kadidlnicí svou; dvě stě a padesáte kadidlnic bude, ty také i Aron, každý s kadidlnicí svou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 18, 'Tedy vzal jeden každý kadidlnici svou, a nabravše do nich uhlí, vložili na ně i kadidla, a stáli u dveří stánku úmluvy, i Mojžíš i Aron.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 19, 'Chóre pak již byl sebral proti nim všecko množství ke dveřím stánku úmluvy; i ukázala se sláva Hospodinova všemu množství.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 20, 'I mluvil Hospodin k Mojžíšovi a k Aronovi, řka:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 21, 'Oddělte se z prostředku množství tohoto, ať je v okamžení zahladím.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 22, 'Kteřížto padše na tváři své, řekli: Bože silný, Bože duchů i všelikého těla, jediný tento člověk zhřešil, a což na všecko shromáždění hněvati se budeš?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 23, 'Tedy mluvil Hospodin k Mojžíšovi, řka:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 24, 'Mluv k množství a rci: Odstupte od příbytku Chóre, Dátana a Abirona.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 25, 'A vstav Mojžíš, šel k Dátanovi a Abironovi; i šli za ním starší Izraelští.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 26, 'A mluvil k množství, řka: Odstupte, prosím, od stanů bezbožných mužů těchto, aniž se čeho dotýkejte, což jejich jest, abyste nebyli zachváceni ve všech hříších jejich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 27, 'I odstoupili se všech stran od příbytku Chóre, Dátana a Abirona; ale Dátan a Abiron vyšedše, stáli u dveří stanů svých, i ženy jejich a synové jejich, i maličcí jejich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 28, 'Tedy řekl Mojžíš: Po tomto poznáte, že Hospodin poslal mne, abych činil všecky skutky tyto, a že nic o své ujmě ne činím:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 29, 'Jestliže tak jako jiní lidé mrou, zemrou i tito, a navštívením obecným všechněm lidem jestliže navštíveni budou, neposlal mne Hospodin.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 30, 'Pakliť něco nového učiní Hospodin, a země, otevra ústa svá, požře je se vším, což mají, a sstoupí-li za živa do pekla, tedy poznáte, že jsou popouzeli muži ti Hospodina.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 31, 'I stalo se, když přestal mluviti slov těch, že rozstoupila se země pod nimi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 32, 'A otevřevši země ústa svá, požřela je i domy jejich i všecky lidi, kteříž byli s Chóre, i všecken statek jejich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 33, 'A tak sstoupili oni se vším, což měli, za živa do pekla, a přikryla je země; i zahynuli z prostředku shromáždění.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 34, 'Všickni pak Izraelští, kteříž byli vůkol nich, utíkali, slyšíce křik jejich; nebo řekli: Utecme, aby i nás nesehltila země.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 35, 'Vyšel také oheň od Hospodina, a spálil těch dvě stě a padesáte mužů, kteříž kadili.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 36, 'Tedy mluvil Hospodin k Mojžíšovi, řka:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 37, 'Rci Eleazarovi, synu Arona kněze, ať sbéře kadidlnice z toho spáleniště, a uhlí z nich pryč rozmece, nebo posvěceny jsou,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 38, 'Kadidlnice totiž těch, kteříž proti svým dušem hřešili, a ať je rozkuje na plechy k obložení oltáře; nebo kadili jimi před Hospodinem, protož posvěceny jsou, a budou na znamení synům Izraelským.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 39, 'I sebral Eleazar kněz kadidlnice měděné, jimiž kadili ti, kteříž spáleni jsou, a rozkovali je k obložení oltáře,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 40, 'Pro budoucí pamět synům Izraelským, aby nepřistupoval žádný jiný, kdož by nebyl z rodu Aronova, k kadění před Hospodinem, aby se mu nestalo jako Chóre a jako rotě jeho, jakož byl mluvil jemu Hospodin skrze Mojžíše.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 41, 'Nazejtří pak reptalo všecko množství synů Izraelských na Mojžíše a na Arona, řkouce: Vy jste příčinou smrti lidu Hospodinova.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 42, 'I stalo se, když se opět sbíral lid proti Mojžíšovi a proti Aronovi, že se ohlédli k stánku úmluvy, a aj, přikryl jej oblak, a ukázala se sláva Hospodinova.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 43, 'Přišel také Mojžíš s Aronem před stánek úmluvy.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 44, 'I mluvil Hospodin k Mojžíšovi, řka:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 45, 'Vyjděte z prostředku množství tohoto, a zahladím je v okamžení. I padli na tváři své.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 46, 'Tedy řekl Mojžíš Aronovi: Vezma kadidlnici, dej do ní uhlí z oltáře, a vlož kadidla, a běž rychle k množství a očisť je; nebo vyšla prchlivost od tváři Hospodinovy, a již rána se začala.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 47, 'I vzav Aron kadidlnici, jakž rozkázal Mojžíš, běžel do prostřed shromáždění, (a aj, rána již se byla začala v lidu,) a zakadiv, očistil lid.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 48, 'A stál mezi mrtvými a živými; i zastavena jest rána.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 49, 'Bylo pak těch, kteříž od té rány zemřeli, čtrnácte tisíců a sedm set, kromě těch, jenž zemřeli příčinou Chóre.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 50, 'I navrátil se Aron k Mojžíšovi, ke dveřím stánku úmluvy, když ta rána přetržena byla.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 1, 'Tedy mluvil Hospodin k Mojžíšovi, řka:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 2, 'Mluv k synům Izraelským, a vezmi od nich po jednom prutu z každého domu otců, totiž ode všech knížat jejich, vedlé domů otců jich dvanácte prutů, a jednoho každého jméno napíšeš na prutu jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 3, 'Jméno pak Aronovo napíšeš na prutu Léví; nebo jeden každý prut bude místo jednoho předního z domu otců jejich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 4, 'I necháš jich v stánku úmluvy před svědectvím, kdež přicházím k vám.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 5, 'I stane se, že kohož vyvolím, toho prut zkvetne; a tak spokojím a svedu s sebe reptání synů Izraelských, kterýmž repcí na vás.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 6, 'Ty věci když mluvil Mojžíš k synům Izraelským, dali jemu všecka jejich knížata pruty své, jedno každé kníže prut z domu otce svého, totiž prutů dvanácte, prut pak Aronův byl též mezi pruty jejich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 7, 'I zanechal Mojžíš prutů před Hospodinem v stánku svědectví.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 8, 'Nazejtří pak přišel Mojžíš do stánku svědectví, a aj, vyrostl prut Aronův z domu Léví, a vypustiv z sebe pupence, zkvetl a vydal mandly zralé.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 9, 'I vynesl Mojžíš všecky ty pruty od tváři Hospodinovy ke všechněm synům Izraelským; a uzřevše je, vzali jeden každý prut svůj.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 10, 'Řekl pak Hospodin Mojžíšovi: Dones zase prut Aronův před svědectví, aby chován byl na znamení proti buřičům zpurným, a tak přítrž učiníš reptání jejich na mne, aby nezemřeli.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 11, 'I učinil tak Mojžíš; jakž byl přikázal jemu Hospodin, tak učinil.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 12, 'Tedy mluvili synové Izraelští k Mojžíšovi, řkouce: Hle, již mřeme, mizíme a všickni my hyneme.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 13, 'Kdožkoli blízko přistoupá k příbytku Hospodinovu, umírá. Všickni-liž smrtí zhyneme?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 1, 'A protož řekl Hospodin Aronovi: Ty a synové tvoji i dům otce tvého s tebou ponesete nepravost svatyně; ty také i synové tvoji s tebou ponesete nepravost kněžství svého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 2, 'Bratří také své, pokolení Léví, čeled otce svého připoj k sobě, ať jsou při tobě a posluhují tobě; ty pak a synové tvoji s tebou před stánkem svědectví sloužiti budete.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 3, 'A pilně ostříhati budou rozkázaní tvého, bedlivi jsouce při všem stánku; a však ať k nádobám svatyně a k oltáři nepřistupují, aby nezemřeli i oni i vy.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 4, 'A přídržeti se budou tebe, pilně ostříhajíce stánku úmluvy při všech službách jeho; a cizí žádný nepřistupuj k vám.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 5, 'Protož pilně ostříhejte svatyně i služby oltáře, ať nepřichází více zůřivá prchlivost na syny Izraelské,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 6, 'Poněvadž jsem já vybral bratří vaše Levíty z synů Izraelských vám, za dar dané Hospodinu, aby konali službu při stánku úmluvy.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 7, 'Ty pak a synové tvoji s tebou ostříhati budete kněžství svého při všech věcech přináležejících k oltáři, a kteréž jsou za oponou, a sloužiti budete. Úřad kněžství vašeho darem jsem vám dal, protož, přistoupil-li by kdo cizí, umře.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 8, 'Mluvil také Hospodin k Aronovi: Aj, já dal jsem tobě k ostříhání oběti své, kteréž se vzhůru pozdvihují; všecko také, což se posvěcuje od synů Izraelských, tobě jsem dal pro pomazání i synům tvým ustanovením věčným.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 9, 'Toto bude tvé z věcí posvěcených, kteréž nepřicházejí na oheň: Všeliká obět jejich, buď suchá obět jejich, neb obět za hřích jejich, aneb obět za provinění jejich, kteréž mi dávati budou, svatosvaté tobě bude to i synům tvým.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 10, 'V svatyni budeš je jísti, každý pohlaví mužského bude je jísti; svaté bude tobě.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 11, 'Tvá tedy bude obět darů jejich, kteráž vzhůru pozdvižena bývá; každou také obět synů Izraelských, kteráž sem i tam obracína bývá, tobě jsem dal a synům tvým, i dcerám tvým s tebou ustanovením věčným. Každý, kdož jest čistý v domě tvém, bude je jísti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 12, 'Všecko, což předního jest z oleje, a což nejlepšího jest vína a obilé, prvotiny těch věcí, kteréž dají Hospodinu, dal jsem tobě.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 13, 'Prvotiny všech věcí, kteréž rostly v zemi jejich, ty přinesou Hospodinu, a tvé budou. Každý, kdož jest čistý v domě tvém, jísti je bude.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 14, 'Všecko oddané Bohu v Izraeli tvé bude.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 15, 'Cožkoli otvírá život všelikého těla, kteréž obětováno bývá Hospodinu, tak z lidí jako z hovad, tvé bude; prvorozené však z lidí, vyplaceno bude, prvorozené také z nečistých hovad vyplatiti kážeš.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 16, 'Výplata pak jeho, když mu již jeden měsíc bude, vedlé ceny tvé bude pěti loty stříbra podlé lotu svatyně; dvadceti peněz váží lot.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 17, 'Ale prvorozeného z volů, neb z ovcí, neb z koz, nedáš vyplatiti; nebo posvěceny jsou. Krev jejich vykropíš na oltář, a tuk jejich zapálíš, aby byl obětí ohnivou vůně spokojující Hospodina.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 18, 'Maso pak jejich tvé bude; jako hrudí z oběti sem i tam obracení, a jako plece pravé tvé bude.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 19, 'Každou obět vzhůru pozdvižení z věcí posvěcených, kteréž přinášejí synové Izraelští Hospodinu, dal jsem tobě, a synům tvým, i dcerám tvým s tebou ustanovením věčným, smlouvou trvánlivou a věčnou před Hospodinem, tobě i semeni tvému s tebou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 20, 'Mluvil také Hospodin k Aronovi: V zemi jejich, dědictví ani dílu svého mezi nimi nebudeš míti; já jsem díl tvůj, a dědictví tvé u prostřed synů Izraelských.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 21, 'Synům pak Léví, aj, dal jsem všecky desátky v Izraeli za dědictví, za službu jejich, kterouž vykonávají, sloužíce při stánku úmluvy.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 22, 'A synové Izraelští nechať nepřistupují k stánku úmluvy, aby nenesli hříchu a nezemřeli.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 23, 'Ale sami Levítové konati budou službu při stánku úmluvy, a sami ponesou nepravost svou. Ustanovení věčné v pronárodech vašich to bude, aby dědictví nemívali mezi syny Izraelskými.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 24, 'Nebo desátky synů Izraelských, kteréž přinášeti budou Hospodinu v obět vzhůru pozdvižení, dal jsem Levítům za dědictví; protož jsem o nich řekl: U prostřed synů Izraelských nebudou míti dědictví.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 25, 'I mluvil Hospodin k Mojžíšovi, řka:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 26, 'Mluv k Levítům a rci jim: Když vezmete desátky od synů Izraelských, kteréž jsem vám dal od nich za dědictví vaše, tedy přinesete z nich obět vzhůru pozdvižení Hospodinu, desátky z desátků.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 27, 'A počtena vám bude ta obět vaše jako obilí z humna, a jako víno od presu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 28, 'Tak vy také přinesete obět vzhůru pozdvižení Hospodinu ze všech desátků svých, kteréž vezmete od synů Izraelských, a dáte z nich obět Hospodinovu Aronovi knězi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 29, 'Ze všech darů svých přinesete každou obět vzhůru pozdvižení Hospodinu, díl posvěcený všeho, což nejlepšího jest.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 30, 'Díš jim také: Když obětovati budete z toho, což nejlepšího jest, počteno bude Levítům jako úrody z humna, a jako úrody od presu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 31, 'Jísti pak budete ty desátky na všelikém místě vy i čeled vaše; nebo mzda vaše jest za službu vaši při stánku úmluvy.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 32, 'A neponesete pro to hříchu, když obětovati budete to, což nejlepšího jest; a tak nepoškvrníte věcí posvěcených od synů Izraelských, a nezemřete.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 1, 'I mluvil Hospodin k Mojžíšovi a k Aronovi, řka:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 2, 'Toto jest ustanovení zákona, kteréž přikázal Hospodin, řka: Mluv k synům Izraelským, ať vezmouce, přivedou k tobě jalovici červenou bez vady, na níž by nebylo poškvrny, a na kterouž by ještě jho nebylo kladeno.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 3, 'A dáte ji Eleazarovi knězi, kterýž vyvede ji ven z stanů, a rozkáže ji zabiti před sebou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 4, 'A vezma Eleazar kněz krve její na prst svůj, kropiti bude jí naproti stánku úmluvy sedmkrát.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 5, 'Potom káže tu jalovici spáliti před očima svýma; kůži její, i maso její, i krev její s lejny jejími dá spáliti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 6, 'A vezma kněz dřeva cedrového, yzopu a červce dvakrát barveného, uvrže to vše do ohně, v kterémž ta jalovice hoří.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 7, 'I zpéře kněz roucha svá, a tělo své umyje vodou; potom vejde do stanů, a bude nečistý až do večera.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 8, 'Takž také i ten, kterýž ji pálil, zpéře roucha svá u vodě, a tělo své obmyje vodou, a nečistý bude až do večera.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 9, 'Popel pak té jalovice spálené smete muž čistý, a vysype jej vně za stany na místě čistém, aby byl všechněm synům Izraelským chován k vodě očištění, kteráž bude k očištění za hřích.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 10, 'A ten, kdož by smetl popel té jalovice, zpéře roucha svá a nečistý bude až do večera. A budou to míti synové Izraelští i příchozí, kterýž jest pohostinu u prostřed nich, za ustanovení věčné.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 11, 'Kdo by se dotkl těla kteréhokoli mrtvého člověka, nečistý bude za sedm dní.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 12, 'Takový očišťovati se bude tou vodou dne třetího a dne sedmého, i bude čistý; neočistí-li se pak dne třetího a dne sedmého, nebudeť čistý.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 13, 'Kdo by koli, dotkna se těla mrtvého člověka, kterýž umřel, neočistil se, příbytku Hospodinova poškvrnil. Protož vyhlazena bude duše ta z Izraele, nebo vodou očišťování není pokropen; nečistýť bude, a nečistota jeho zůstává na něm.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 14, 'Tento jest také zákon, kdyby člověk umřel v stanu: Kdo by koli všel do toho stanu, a kdo by koli byl v stanu, nečistý bude za sedm dní.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 15, 'Tolikéž všeliká nádoba odkrytá, kteráž by neměla svrchu přikryvadla na sobě, nečistá bude.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 16, 'Tak kdož by se koli dotkl na poli buď mečem zabitého, aneb mrtvého, buďto kosti člověka, aneb hrobu, nečistý bude za sedm dní.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 17, 'A vezmou pro nečistého popela z spálené za hřích, a nalejí na něj vody živé do nádoby.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 18, 'Potom vezme člověk čistý yzopu, a omočí jej v té vodě, a pokropí stanu, i všeho nádobí i lidí, kteříž by tu byli, tolikéž toho, kterýž dotkl se kosti, aneb zabitého, aneb mrtvého, aneb hrobu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 19, 'Pokropí tedy čistý nečistého v den třetí a v den sedmý; a když jej očistí dne sedmého, zpéře šaty své, a umyje se vodou, a čistý bude u večer.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 20, 'Jestliže by pak kdo nečistý jsa, neočistil se, vyhlazena bude duše ta z prostředku shromáždění; nebo svatyně Hospodinovy poškvrnil, vodou očišťování nejsa pokropen; nečistý jest.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 21, 'I bude jim to za ustanovení věčné. Kdož by pak tou vodou očišťování kropil, zpéře roucha svá, a kdož by se dotkl vody očišťování, nečistý bude až do večera.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 22, 'Čehokoli dotkl by se nečistý, nečisté bude; člověk také, kterýž by se dotkl toho, nečistý bude až do večera.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 1, 'I přitáhlo všecko množství synů Izraelských na poušť Tsin, měsíce prvního; i pozůstal lid v Kádes, kdež umřela Maria, a tu jest pochována.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 2, 'A když množství to nemělo vody, sešli se proti Mojžíšovi, a proti Aronovi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 3, 'I domlouval se lid na Mojžíše, a mluvili, řkouce: Ó kdybychom i my byli zemřeli, když zemřeli bratří naši před Hospodinem!');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 4, 'Proč jste jen uvedli shromáždění Hospodinovo na poušť tuto, abychom zde pomřeli i my i dobytek náš?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 5, 'A proč jste nás vyvedli z Egypta, abyste uvedli nás na toto zlé místo, na němž se nerodí ani obilí, ani fíků, ani hroznů, ani jablek zrnatých, na kterémž ani vody ku pití není?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 6, 'Tedy odšel Mojžíš s Aronem od tváři shromáždění ke dveřím stánku úmluvy, a padli na tváři své; i ukázala se sláva Hospodinova nad nimi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 7, 'A mluvil Hospodin k Mojžíšovi, řka:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 8, 'Vezmi hůl, a shromáždíce všecko množství, ty i Aron bratr tvůj, mluvte k skále této před očima jejich, a vydá vodu svou. I vyvedeš jim vodu z skály, a dáš nápoj všemu množství i dobytku jejich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 9, 'Tedy vzal Mojžíš hůl před tváří Hospodinovou, jakž rozkázal jemu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 10, 'I svolali Mojžíš s Aronem všecko množství před skálu, a řekl jim: Slyštež nyní, ó reptáci: Zdali z skály této vyvedeme vám vodu?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 11, 'I pozdvihl Mojžíš ruky své, a udeřil v skálu holí svou po dvakrát; i vyšly vody hojné, a pilo všecko množství i dobytek jejich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 12, 'Potom řekl Hospodin Mojžíšovi a Aronovi: Že jste mi nevěřili, abyste posvětili mne před očima synů Izraelských, proto neuvedete shromáždění tohoto do země, kterouž jsem jim dal.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 13, 'Toť jsou ty vody sváru, o kteréž svařili se synové Izraelští s Hospodinem, a posvěcen jest v nich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 14, 'I poslal Mojžíš posly z Kádes k králi Edom, aby řekli: Totoť vzkazuje bratr tvůj Izrael: Ty víš o všech těžkostech, kteréž přišly na nás,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 15, 'Že sstoupili otcové naši do Egypta, a bydlili jsme tam za mnoho let. Egyptští pak ssužovali nás i otce naše.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 16, 'A volali jsme k Hospodinu, kterýž uslyšel hlas náš, a poslav anděla, vyvedl nás z Egypta, a aj, již jsme v Kádes městě, při pomezí tvém.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 17, 'Nechť, prosím, projdeme skrze zemi tvou. Nepůjdeme přes rolí, ani přes vinice, aniž píti budeme vody z čí studnice; cestou královskou půjdeme a neuchýlíme se na pravo ani na levo, dokavadž nepřejdeme mezí tvých.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 18, 'Jemužto odpověděl Edom: Nechoď skrze mou zemi, abych s mečem nevyšel v cestu tobě.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 19, 'I řekli mu synové Izraelští: Obecnou silnicí půjdeme, a jestliže vody tvé napili bychom se, buď my neb dobytek náš, zaplatíme ji; nic jiného nežádáme, toliko pěší abychom prošli.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 20, 'Odpověděl: Neprojdeš. A vytáhl proti nim Edom s množstvím lidu a s silou velikou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 21, 'Když tedy nedopustil Edom Izraelovi, aby přešel meze jeho, uchýlil se Izrael od něho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 22, 'A hnuvše se synové Izraelští i všecko množství jejich z Kádes, přišli na horu řečenou Hor.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 23, 'I mluvil Hospodin k Mojžíšovi a Aronovi na hoře Hor, při pomezí země Edom, řka:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 24, 'Připojen bude Aron k lidu svému; nebo nevejde do země, kterouž jsem dal synům Izraelským, proto že jste odporni byli řeči mé při vodách sváru.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 25, 'Pojmi Arona a Eleazara syna jeho, a uvedeš je na horu Hor.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 26, 'A svlečeš Arona z roucha jeho, a oblečeš v ně Eleazara syna jeho; nebo Aron připojen bude k lidu svému, a tam umře.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 27, 'I učinil Mojžíš, jakž rozkázal Hospodin, a vstoupili na horu Hor před očima všeho množství.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 28, 'A svlékl Mojžíš Arona z roucha jeho, a oblékl v ně Eleazara syna jeho. I umřel tam Aron na pahrbku hory, Mojžíš pak a Eleazar sstoupili s hory.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 29, 'Vidouce pak všecko množství, že umřel Aron, plakali ho za třidceti dní všecken dům Izraelský.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 1, 'To když uslyšel Kananejský král v Arad, kterýž bydlil na poledne, že by táhl Izrael tou cestou, kterouž byli špehéři šli, bojoval s ním, a zajal jich množství.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 2, 'Tedy Izrael učinil slib Hospodinu, řka: Jestliže dáš lid tento v ruce mé, do gruntu zkazím města jejich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 3, 'I uslyšel Hospodin hlas Izraele a dal mu Kananejské, kterýžto do gruntu zkazil je i města jejich, a nazval jméno toho místa Horma.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 4, 'Potom hnuli se s hory Hor cestou k moři Rudému, aby obešli zemi Idumejskou; i ustával lid velice na cestě.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 5, 'A mluvil lid proti Bohu a proti Mojžíšovi: Proč jste vyvedli nás z Egypta, abychom zemřeli na poušti? Nebo ani chleba ani vody není, a duše naše chléb tento ničemný sobě již zošklivila.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 6, 'Protož dopustil Hospodin na lid hady ohnivé, kteříž jej štípali, tak že množství lidu zemřelo z Izraele.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 7, 'Tedy přišel lid k Mojžíšovi a řekli: Zhřešili jsme, nebo jsme mluvili proti Hospodinu a proti tobě; modl se Hospodinu, ať odejme od nás ty hady. I modlil se Mojžíš za lid.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 8, 'I řekl Hospodin Mojžíšovi: Udělej sobě hada podobného těm ohnivým, a vyzdvihni jej na sochu; a každý ušťknutý, když pohledí na něj, živ bude.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 9, 'I udělal Mojžíš hada měděného, a vyzdvihl jej na sochu; a stalo se, když ušťkl had někoho, a on vzhlédl na hada měděného, že zůstal živ.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 10, 'Tedy hnuli se odtud synové Izraelští, a položili se v Obot.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 11, 'Potom pak hnuvše se z Obot, položili se při pahrbcích hor Abarim na poušti, kteráž jest naproti zemi Moábské k východu slunce.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 12, 'Odtud brali se, a položili se v údolí Záred.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 13, 'Opět hnuvše se odtud, položili se u brodu potoka Arnon, kterýž jest na poušti, a vychází z končin Amorejských. Nebo Arnon jest pomezí Moábské mezi Moábskými a Amorejskými.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 14, 'Protož praví se v knize bojů Hospodinových, že proti Vahebovi u vichřici bojoval, a proti potokům Arnon.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 15, 'Nebo tok těch potoků, kterýž se nachyluje ku položení Ar, ten jde vedlé pomezí Moábského.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 16, 'A odtud táhli do Beer; a to jest to Beer, o němž byl řekl Hospodin k Mojžíšovi: Shromažď lid, a dám jim vodu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 17, 'Tedy zpíval lid Izraelský písničku tuto: Vystupiž studnice, prozpěvujte o ní;');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 18, 'Studnice, kterouž kopala knížata, kterouž vykopali přední z lidu s vydavatelem zákona holemi svými. Z pouště pak brali se do Matana,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 19, 'A z Matana do Nahaliel, z Nahaliel do Bamot,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 20, 'A z Bamot do údolí, kteréž jest na poli Moábském, až k vrchu hory, kteráž leží na proti poušti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 21, 'Tedy poslal lid Izraelský posly k Seonovi králi Amorejskému, řka:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 22, 'Nechť jdeme skrze zemi tvou. Neuchýlíme se ani do pole, ani do vinic, ani z studnic vody píti nebudeme, ale cestou královskou půjdeme, dokavadž nepřejdeme pomezí tvého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 23, 'I nedopustil Seon jíti lidu Izraelskému skrze krajinu svou, nýbrž sebrav Seon všecken lid svůj, vytáhl proti lidu Izraelskému na poušť, a přitáh do Jasa, bojoval proti Izraelovi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 24, 'I porazil jej lid Izraelský mečem, a vzal v dědictví zemi jeho, od Arnon až do Jabok, a až do země synů Ammon; nebo pevné bylo pomezí Ammonitských.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 25, 'Tedy vzal Izrael všecka ta města, a přebýval ve všech městech Amorejských, v Ezebon a ve všech městečkách jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 26, 'Nebo Ezebon bylo město Seona krále Amorejského, kterýž když bojoval proti králi Moábskému prvnímu, vzal mu všecku zemi jeho z rukou jeho až do Arnon.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 27, 'Protož říkávali v přísloví: Poďte do Ezebon, aby vystaveno bylo a vzděláno město Seonovo.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 28, 'Nebo oheň vyšel z Ezebon, a plamen z města Seon, i spálil Ar Moábských a obyvatele výsosti Arnon.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 29, 'Běda tobě Moáb, zahynuls lide Chámos; dal syny své v utíkání, a dcery své v zajetí králi Amorejskému Seonovi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 30, 'A království jejich zahynulo od Ezebon až do Dibon, a vyhladili jsme je až do Nofe, kteréž jest až k Medaba.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 31, 'A tak bydlil Izrael v zemi Amorejské.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 32, 'Potom poslal Mojžíš, aby shlédli Jazer, kteréž vzali i s městečky jeho; a tak vyhnal Amorejské, kteříž tam bydlili.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 33, 'Obrátivše se pak, táhli cestou k Bázan. I vytáhl Og, král Bázan, proti nim, on i všecken lid jeho, aby bojoval v Edrei.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 34, 'Tedy řekl Hospodin Mojžíšovi: Neboj se ho; nebo v ruce tvé dal jsem jej, i všecken lid jeho, i zemi jeho, a učiníš jemu tak, jakož jsi učinil Seonovi, králi Amorejskému, kterýž bydlil v Ezebon.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 35, 'I porazili jej i syny jeho, i všecken lid jeho, tak že žádný živý po něm nezůstal, a uvázali se dědičně v zemi jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 1, 'I táhli synové Izraelští a položili se na polích Moábských, nedocházeje k Jordánu, naproti Jerichu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 2, 'A viděl Balák, syn Seforův, všecko, co učinil Izrael Amorejskému.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 3, 'I bál se Moáb toho lidu velmi, proto že ho bylo mnoho, a svíral se pro přítomnost synů Izraelských.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 4, 'Protož řekl Moáb k starším Madianským: Tudíž toto množství požere všecko, což jest vůkol nás, jako sžírá vůl trávu polní. Byl pak Balák, syn Seforův, toho času králem Moábským.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 5, 'I poslal posly k Balámovi, synu Beorovu, do města Petor, kteréž jest při řece v zemi vlasti jeho, aby povolal ho, řka: Aj, lid vyšel z Egypta, aj, přikryl svrchek země, a usazuje se proti mně.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 6, 'Protož nyní poď medle, zlořeč mně k vůli lidu tomuto, nebo silnější mne jest; snad svítězím nad ním, a porazím jej, aneb vyženu z země této. Vím zajisté, že komuž ty žehnáš, požehnaný bude, a komuž ty zlořečíš, bude zlořečený.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 7, 'Tedy šli starší Moábští a starší Madianští, nesouce v rukou svých peníze za zlořečení; i přišli k Balámovi, a vypravovali mu slova Balákova.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 8, 'On pak řekl jim: Pobuďte zde přes tuto noc, a dám vám odpověd, jakž mi mluviti bude Hospodin. I zůstala knížata Moábská s Balámem.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 9, 'Přišel pak Bůh k Balámovi a řekl: Kdo jsou ti muži u tebe?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 10, 'Odpověděl Balám Bohu: Balák, syn Seforův, král Moábský, poslal ke mně, řka:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 11, 'Aj, lid ten, kterýž vyšel z Egypta, přikryl svrchek země; protož nyní poď, proklň mi jej, snad svítězím, bojuje s ním, a vyženu jej.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 12, 'I řekl Bůh k Balámovi: Nechoď s nimi, aniž zlořeč lidu tomu, nebo požehnaný jest.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 13, 'Tedy Balám vstav ráno, řekl knížatům Balákovým: Navraťte se do země své, nebo nechce mi dopustiti Hospodin, abych šel s vámi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 14, 'A vstavše knížata Moábská, přišli k Balákovi a řekli: Nechtěl Balám jíti s námi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 15, 'Tedy opět poslal Balák více knížat a znamenitějších, nežli první.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 16, 'Kteříž přišedše k Balámovi, řekli jemu: Toto praví Balák, syn Seforův: Nezpěčuj se, prosím, přijíti ke mně.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 17, 'Nebo velikou ctí tě ctíti chci, a což mi koli rozkážeš, učiním; protož přiď, prosím, proklň mi lid tento.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 18, 'Odpovídaje pak Balám, řekl služebníkům Balákovým: Byť mi pak dal Balák plný dům svůj stříbra a zlata, nemohl bych přestoupiti slova Hospodina Boha svého, a učiniti proti němu malé neb veliké věci.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 19, 'Nyní však zůstaňte, prosím, zde i vy také této noci, abych zvěděl, co dále mluviti bude Hospodin se mnou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 20, 'Přišed pak Bůh k Balámovi v noci, řekl jemu: Poněvadž proto, aby povolali tě, přišli muži tito, vstana, jdi s nimi, a však což přikáži tobě, to čiň.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 21, 'Tedy Balám vstav ráno, osedlal oslici svou, a bral se s knížaty Moábskými.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 22, 'Ale rozpálil se hněv Boží, proto že jel s nimi, a postavil se anděl Hospodinův na cestě, aby mu překazil; on pak seděl na oslici své, maje s sebou dva služebníky své.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 23, 'A když uzřela oslice anděla Hospodinova, an stojí na cestě, a meč jeho vytržený v ruce jeho, uhnula se s cesty, a šla polem. I bil ji Balám, aby ji navedl zase na cestu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 24, 'A anděl Hospodinův stál na stezce u vinice mezi dvěma zídkami.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 25, 'Viduci pak oslice anděla Hospodinova, přitiskla se ke zdi, přitřela také nohu Balámovi ke zdi; pročež opět bil ji.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 26, 'Potom anděl Hospodinův šel dále, a stál v úzkém místě, kdež nebylo žádné cesty k uchýlení se na pravo neb na levo.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 27, 'A viduci oslice anděla Hospodinova, padla pod Balámem; pročež rozhněval se velmi Balám, a bil oslici kyjem.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 28, 'I otevřel Hospodin ústa oslice, a řekla Balámovi: Cožť jsem učinila, že již po třetí mne biješ?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 29, 'Řekl Balám k oslici: To, že jsi mne v posměch uvedla. Ó bych měl meč v rukou, jistě bych tě již zabil.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 30, 'Odpověděla oslice Balámovi: Zdaliž nejsem oslice tvá? Jezdíval jsi na mně, jak jsi mne dostal, až do dnes; zdaliž jsem kdy obyčej měla tak činiti tobě? Kterýž odpověděl: Nikdy.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 31, 'V tom otevřel Hospodin oči Balámovy, i uzřel anděla Hospodinova, an stojí na cestě, maje meč dobytý v ruce své; a nakloniv hlavy, poklonu učinil na tvář svou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 32, 'I mluvil k němu anděl Hospodinův: Proč jsi bil oslici svou po třikrát? Aj, já vyšel jsem, abych se protivil tobě; nebo uchýlil jsi se s cesty přede mnou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 33, 'Když viděla mne oslice, vyhnula mi již po třikrát; a byť mi se byla nevyhnula, již bych byl také tebe zabil, a jí živé nechal.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 34, 'Odpověděl Balám andělu Hospodinovu: Zhřešilť jsem, nebo jsem nevěděl, že ty stojíš proti mně na cestě; protož nyní, jestliže se nelíbí tobě, raději navrátím se domů.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 35, 'Řekl anděl Hospodinův k Balámovi: Jdi s muži těmi, avšak slovo, kteréž mluviti budu tobě, to mluviti budeš. Tedy šel Balám s knížaty Balákovými.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 36, 'Uslyšev pak Balák o příchodu Balámovu, vyšel proti němu do města Moábského, kteréž bylo při řece Arnon, jenž jest při konci pomezí.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 37, 'I řekl Balák Balámovi: Zdaliž jsem víc než jednou neposílal pro tě? Pročež jsi tedy nepřišel ke mně? Proto-li, že bych tě náležitě uctiti nemohl?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 38, 'Odpověděl Balám Balákovi: Aj, již jsem přišel k tobě; nyní pak zdaliž všelijak budu co moci mluviti? Slovo, kteréž vložil Bůh v ústa má, to mluviti budu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 39, 'I bral se Balám s Balákem, a přijeli do města Husot.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 40, 'Kdežto nabiv Balák volů a ovec, poslal k Balámovi a k knížatům, kteříž s ním byli.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 41, 'Nazejtří pak ráno, pojav Balák Baláma, uvedl ho na výsosti modly Bál, odkudž shlédl i nejdalší díl lidu Izraelského.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 1, 'A řekl Balám Balákovi: Udělej mi tuto sedm oltářů, a připrav mi také sedm volků a sedm skopců.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 2, 'I udělal Balák, jakž mluvil Balám. Tedy obětoval Balák a Balám volka a na každém oltáři.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 3, 'Řekl pak Balám Balákovi: Postůj při oběti své zápalné, a půjdu, zdali by se potkal se mnou Hospodin, a což by koli mně ukázal, povím tobě. I odšel sám.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 4, 'I potkal se Bůh s Balámem, a řekl jemu Balám: Sedm oltářů zpořádal jsem, a obětoval jsem volka a skopce na každém oltáři.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 5, 'Vložil pak Hospodin slovo v ústa Balámova a řekl: Navrať se k Balákovi a tak mluv.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 6, 'I navrátil se k němu, a nalezl jej, an stojí při oběti své zápalné, i všecka knížata Moábská.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 7, 'Tedy vzav před sebe přísloví své, řekl: Z Aram přivedl mne Balák král Moábský, z hor východních, řka: Poď, zlořeč mi k vůli Jákoba, a poď, vydej klatbu na Izraele.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 8, 'Proč bych zlořečil, komuž Bůh silný nezlořečí? A proč bych klel, kohož Hospodin neproklíná?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 9, 'Když s vrchu skal hledím na něj, a s pahrbků spatřuji jej, aj, lid ten sám bydlí, a k jiným národům se nepřiměšuje.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 10, 'Kdo sečte prach Jákobův? a kdo počet? Kdo sečte čtvrtý díl Izraelského lidu? Ó bych já umřel smrtí spravedlivých, a dokonání mé ó by bylo jako i jeho!');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 11, 'I řekl Balák Balámovi: Což mi to děláš? Abys zlořečil nepřátelům mým, povolal jsem tě, a ty pak ustavičně dobrořečíš jim.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 12, 'Kterýž odpovídaje, řekl: Zdali toho, což Hospodin vložil v ústa má, nemám šetřiti, abych tak mluvil?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 13, 'I řekl jemu Balák: Poď, prosím, se mnou na jiné místo, odkudž bys viděl jej, (toliko zadní díl jeho viděti budeš, a všeho nebudeš viděti,) a proklň mi jej odtud.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 14, 'I pojav jej, vyvedl ho na rovinu Zofim, na vrch jednoho pahrbku, a udělav sedm oltářů, obětoval volka a skopce na každém oltáři.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 15, 'Řekl pak Balákovi: Postůj tuto při zápalné oběti své, a já půjdu tamto vstříc Hospodinu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 16, 'I potkal se Hospodin s Balámem, a vloživ slovo v ústa jeho, řekl: Navrať se k Balákovi a mluv tak.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 17, 'Přišel tedy k němu, a hle, on stál při zápalné oběti své, a knížata Moábská s ním. Jemužto řekl Balák: Co mluvil Hospodin?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 18, 'A on vzav přísloví své, řekl: Povstaň Baláku a slyš, pozoruj mne, synu Seforův.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 19, 'Bůh silný není jako člověk, aby klamal, a jako syn člověka, aby se měnil. Což by řekl, zdaliž neučiní? Což by promluvil, zdali neutvrdí toho?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 20, 'Hle, abych dobrořečil, přijal jsem to na sebe; nebo dobrořečilť jest, a já toho neodvolám.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 21, 'Nepatříť na nepravosti v Jákobovi, aniž hledí na přestoupení v Izraeli; Hospodin Bůh jeho jestiť s ním, a zvuk krále vítězícího v něm.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 22, 'Bůh silný vyvedl je z Egypta, jako silou jednorožcovou byv jim.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 23, 'Nebo není kouzlů proti Jákobovi, ani zaklínání proti Izraelovi; již od toho času vypravováno bude o Jákobovi a Izraelovi, co učinil s ním Bůh silný.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 24, 'Aj, lid jakožto silný lev povstane, a jakožto lvíče vzchopí se; nepoloží se, dokudž by nejedl loupeže, a dokudž by nevypil krve zbitých.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 25, 'I řekl Balák Balámovi: Aniž mu již zlořeč více, ani dobrořeč.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 26, 'Jemuž odpověděl Balám, řka: Zdaližť jsem nepravil, že, což by mi koli mluvil Hospodin, to učiním?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 27, 'I řekl Balák Balámovi: Poď, prosím, povedu tě na jiné místo, odkudž snad líbiti se bude Bohu, abys mi je proklel.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 28, 'A pojav Balák Baláma, uvedl jej na vrch hory Fegor, kteráž leží naproti poušti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 29, 'Tedy řekl Balám Balákovi: Udělej mi tuto sedm oltářů, a připrav mi také sedm volků a sedm skopců.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 30, 'I učinil Balák, jakž řekl Balám, a obětoval volka a skopce na každém oltáři.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 1, 'Vida pak Balám, že by se líbilo Hospodinu, aby dobrořečil Izraelovi, již více nešel jako prvé, jednou i po druhé, k čárům svým, ale obrátil tvář svou proti poušti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 2, 'A pozdvih očí svých, viděl Izraele bydlícího v staních po svých pokoleních, a byl nad ním duch Boží.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 3, 'I vzav podobenství své, dí: Řekl Balám, syn Beorův, řekl muž mající otevřené oči,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 4, 'Řekl slyšící výmluvnosti Boha silného, kterýž vidění všemohoucího vidí, kterýž když padne, otevřené má oči:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 5, 'Jak velmi krásní jsou stánkové tvoji, Jákobe, příbytkové tvoji, Izraeli!');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 6, 'Tak jako se potokové rozšiřují, jako zahrady vedlé řeky, jako stromoví aloes, kteréž štípil Hospodin, jako cedrové podlé vod.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 7, 'Poteče voda z okovu jeho, a símě jeho u vodách mnohých. A král jeho vyvýšen bude více než Agag, a vyzdvihne se království jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 8, 'Bůh silný vyvedl jej z Egypta, jako udatnost jednorožcova jest jemu; sžereť národy protivné sobě, a kosti jich potře a střelami svými prostřílí.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 9, 'Složil se a ležel jako lvíče, a jako lev zůřivý; kdo jej zbudí? Kdo by požehnání dával tobě, požehnaný bude, a kdožť by zlořečil, bude zlořečený.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 10, 'Tedy zapáliv se hněvem Balák proti Balámovi, tleskl rukama svýma a řekl Balámovi: Abys zlořečil nepřátelům mým, povolal jsem tebe, a aj, ustavičně dobrořečil jsi jim již po třikrát.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 11, 'Protož nyní navrať se raději k místu svému. Bylť jsem řekl: Velikou ctí tě ctíti chci, a hle, Hospodin zbavil tě cti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 12, 'Jemuž odpověděl Balám: Však hned poslům tvým, kteréž jsi poslal ke mně, mluvil jsem, řka:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 13, 'Byť mi dal Balák plný dům svůj stříbra a zlata, nebudu moci přestoupiti řeči Hospodinovy, abych činil dobré neb zlé sám od sebe; což mi Hospodin oznámí, to mluviti budu,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 14, '(Ale však ještě já, již odcházeje k lidu svému, počkej, poradím tobě,) co učiní lid ten lidu tvému v posledních dnech.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 15, 'Tedy vzav podobenství své, dí: Řekl Balám, syn Beorův, řekl muž mající oči otevřené,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 16, 'Řekl slyšící výmluvnosti Boha silného, kterýž zná naučení nejvyššího, a vidění všemohoucího vidí, kterýž když padne, otevřené má oči:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 17, 'Uzřímť jej, ale ne nyní, pohledím na něj, ale ne z blízka. Vyjdeť hvězda z Jákoba, a povstane berla z Izraele, kteráž poláme knížata Moábská, a zkazí všecky syny Set.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 18, 'I bude Edom podmaněn, a Seir v vládařství přijde nepřátelům svým; nebo Izrael zmužile sobě počínati bude.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 19, 'Panovati bude pošlý z Jákoba, a zahladí ostatky z každého města.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 20, 'A když uzřel Amalecha, vzav podobenství své, řekl: Jakož počátek národů Amalech, tak konec jeho do gruntu zahyne.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 21, 'Uzřev pak Cinea, vzav podobenství své, řekl: Pevný jest příbytek tvůj, a na skále založils hnízdo své;');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 22, 'Ale však vyhnán bude Cineus, Assur zajatého jej povede.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 23, 'Opět vzav podobenství své, řekl: Ach, kdo bude živ, když toto učiní Bůh silný?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 24, 'A bárky z země Citim připlynou a ssouží Assyrské, ssouží také Židy, ale i ten lid do konce zahyne.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 25, 'Potom vstav Balám, odšel a navrátil se na místo své; Balák také odšel cestou svou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 1, 'V tom, když pobyl Izrael v Setim, počal lid smilniti s dcerami Moábskými.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 2, 'Kteréž pozvaly lidu k obětem bohů svých; i jedl lid, a klaněli se bohům jejich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 3, 'I připojil se lid Izraelský k modle Belfegor, a popudila se prchlivost Hospodinova proti Izraelovi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 4, 'I řekl Hospodin Mojžíšovi: Vezmi všecka knížata lidu, a zvěšej ty nešlechetníky Hospodinu před sluncem, aby se odvrátila prchlivost Hospodinova od Izraele.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 5, 'I řekl Mojžíš soudcům Izraelským: Zabí jeden každý z svých všelikého, kterýž se připojil k modle Belfegor.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 6, 'A aj, jeden z synů Izraelských přišel, a přivedl k bratřím svým ženu Madianku, na odivu Mojžíšovi i všemu množství synů Izraelských; oni pak plakali u dveří stánku úmluvy.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 7, 'To když uzřel Fínes, syn Eleazara, syna Aronova, kněze, vyvstal z prostředku množství toho, a vzal kopí do ruky své.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 8, 'A všed za mužem Izraelským do stanu, probodl je oba dva, muže Izraelského, i ženu tu skrze břicho její; i odvrácena jest rána od synů Izraelských.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 9, 'Zhynulo jich pak od té rány dvadceti čtyři tisíce.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 10, 'Tedy mluvil Hospodin k Mojžíšovi, řka:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 11, 'Fínes, syn Eleazara kněze, syna Aronova, odvrátil prchlivost mou od synů Izraelských, kdyžto horlil horlivostí mou u prostřed nich, tak abych neshladil synů Izraelských v horlivosti své.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 12, 'Protož díš: Aj, já dám jemu smlouvu svou pokoje.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 13, 'I bude míti on i símě jeho po něm smlouvu kněžství věčného, proto že horlil pro Boha svého, a očistil syny Izraelské.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 14, 'A bylo jméno muže Izraelského zabitého, kterýž byl zabit s Madiankou, Zamri, syn Sálův, kníže domu otce svého z pokolení Simeonova.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 15, 'Jméno pak ženy Madianky zabité, Kozbi, dcera Sur, kterýž byl přední v národu svém, v domě otce svého mezi Madianskými.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 16, 'I mluvil Hospodin k Mojžíšovi, řka:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 17, 'Nepřátelsky zacházejte s těmi Madianskými, a zbíte je.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 18, 'Nebo i oni nepřátelsky a lstivě chovali se k vám, a oklamali vás skrze modlu Fegor, a skrze Kozbu, dceru knížete Madianského, sestru svou, kteráž zabita jest v den pomsty přišlé z příčiny Fegor.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 1, 'I stalo se po té ráně, že mluvil Hospodin k Mojžíšovi a Eleazarovi, synu Arona kněze, řka:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 2, 'Sečtěte všecko množství synů Izraelských, od dvadcítiletých a výše po domích otců jejich, všecky, kteříž by mohli jíti k boji v Izraeli.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 3, 'Tedy mluvil Mojžíš a Eleazar kněz k nim na polích Moábských, při Jordánu proti Jerichu, řka:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 4, 'Sečtěte lid od dvadceti let majících a výše, jakž rozkázal Hospodin Mojžíšovi a synům Izraelským, kteříž byli vyšli z země Egyptské.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 5, 'Ruben prvorozený byl Izraelův. Synové Rubenovi: Enoch, z něhož pošla čeled Enochitská; Fallu, z něhož čeled Fallutská;');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 6, 'Ezron, z něhož čeled Ezronitská; Charmi, z něhož čeled Charmitská.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 7, 'Ty jsou čeledi Rubenovy. A bylo jich sečtených čtyřidceti tři tisíce, sedm set a třidceti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 8, 'A syn Fallův Eliab.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 9, 'Synové pak Eliabovi: Nemuel, a Dátan, a Abiron. To jsou ti, Dátan a Abiron, přední z shromáždění, kteříž se vadili s Mojžíšem a s Aronem v spiknutí Chóre, když odporni byli Hospodinu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 10, 'Pročež otevřela země ústa svá, a požřela je i Chóre, tehdáž když zemřela ta rota, a oheň spálil těch dvě stě a padesáte mužů, kteříž byli za příklad jiným.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 11, 'Synové pak Chóre nezemřeli.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 12, 'Synové Simeonovi po čeledech svých: Namuel, z něhož čeled Namuelitská; Jamin, z něhož čeled Jaminská; Jachin, z něhož čeled Jachinská;');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 13, 'Sohar, z něhož čeled Soharská; Saul, z něhož čeled Saulitská.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 14, 'Ty jsou čeledi Simeonovy, jichž bylo dvamecítma tisíců a dvě stě.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 15, 'Synové Gád po čeledech svých: Sefon, z něhož čeled Sefonitská; Aggi, z něhož čeled Aggitská; Suni, z něhož čeled Sunitská;');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 16, 'Ozni, z něhož čeled Oznitská; Heri, z něhož čeled Heritská;');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 17, 'Arodi, z něhož čeled Aroditská; Areli, z něhož čeled Arelitská.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 18, 'Ty jsou čeledi synů Gád, podlé toho, jakž sečteni jsou, čtyřidceti tisíců a pět set.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 19, 'Synové Judovi: Her a Onan; ale zemřeli Her i Onan v zemi Kanánské.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 20, 'Byli pak synové Judovi po čeledech svých: Séla, z něhož čeled Sélanitská; Fáres, z něhož čeled Fáresská; Zára, z něhož čeled Záretská.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 21, 'Byli pak synové Fáresovi: Ezron, z něhož čeled Ezronitská; Hamul, z něhož čeled Hamulská.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 22, 'Ty jsou čeledi Judovy, podlé toho, jakž sečteni jsou, sedmdesáte šest tisíců a pět set.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 23, 'Synové Izacharovi po čeledech svých: Tola, z něhož čeled Tolatská; Fua, z něhož čeled Fuatská;');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 24, 'Jasub, z něhož čeled Jasubská; Simron, z něhož čeled Simronská.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 25, 'Ty jsou čeledi Izacharovy, podlé toho, jakž sečteni jsou, šedesáte čtyři tisíce a tři sta.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 26, 'Synové Zabulonovi po čeledech svých: Sared, z něhož čeled Saredská; Elon, z něhož čeled Elonská; Jahelel, z něhož čeled Jahelelská.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 27, 'Ty jsou čeledi Zabulonovy, podlé toho jakž sečteni jsou, šedesáte tisíc a pět set.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 28, 'Synové Jozefovi po čeledech svých: Manasses a Efraim.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 29, 'Synové Manassesovi: Machir, z něhož čeled Machirská. A Machir zplodil Galáda, z něhož čeled Galádská.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 30, 'Ti jsou synové Galád: Jezer, z něhož čeled Jezerská; Helek, z něhož čeled Helekitská;');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 31, 'Asriel, z něhož čeled Asrielská; Sechem, z něhož čeled Sechemská;');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 32, 'Semida, z něhož čeled Semidatská; Hefer, z něhož čeled Heferská.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 33, 'A Salfad, syn Heferův, neměl synů, než toliko dcery, jichž jsou tato jména: Mahla, Noa, Hegla, Melcha a Tersa.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 34, 'Ty jsou čeledi Manassesovy, a načteno jich padesáte dva tisíce a sedm set.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 35, 'Ale synové Efraimovi po čeledech svých: Sutala, z něhož čeled Sutalitská; Becher, z něhož čeled Becherská; Tehen, z něhož čeled Tehenská.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 36, 'A ti jsou synové Sutalovi: Heran, z něhož čeled Heranská.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 37, 'Ty jsou čeledi synů Efraimových, podlé toho, jakž sečteni jsou, třidceti dva tisíce a pět set. Ti jsou synové Jozefovi po čeledech svých.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 38, 'Synové pak Beniaminovi po čeledech svých: Béla, z něhož čeled Bélitská; Asbel, z něhož čeled Asbelská; Ahiram, z něhož čeled Ahiramská;');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 39, 'Sufam, z něhož čeled Sufamská; Hufam, z něhož čeled Hufamská.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 40, 'Byli pak synové Béla: Ared a Náman; z Ared čeled Aredská, z Náman čeled Námanská.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 41, 'Ti jsou synové Beniaminovi po čeledech svých, podlé toho, jakž sečteni jsou, čtyřidceti pět tisíců a šest set.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 42, 'Tito pak synové Danovi po čeledech svých: Suham, z něhož čeled Suhamská. Ta jest rodina Danova po čeledech svých.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 43, 'Všech čeledí Suhamských, jakž sečteni jsou, šedesáte čtyři tisíce a čtyři sta.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 44, 'Synové Asser po čeledech svých: Jemna, z něhož čeled Jemnitská; Jesui, z něhož čeled Jesuitská;');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 45, 'Beria, z něhož čeled Berietská. Synové Beriovi: Heber, z něhož čeled Heberská; Melchiel, z něhož čeled Melchielská.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 46, 'Jméno pak dcery Asser bylo Serach.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 47, 'Ty jsou čeledi synů Asser, tak jakž sečteni jsou, padesáte tři tisíce a čtyři sta.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 48, 'Synové Neftalímovi po čeledech svých: Jasiel, z něhož čeled Jasielská; Guni, z něhož čeled Gunitská;');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 49, 'Jezer, z něhož čeled Jezerská; Sallem, z něhož čeled Sallemská.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 50, 'Ta jest rodina Neftalímova po čeledech svých, tak jakž sečteni jsou, čtyřidceti pět tisíců a čtyři sta.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 51, 'Ten jest počet synů Izraelských, šestkrát sto tisíců a jeden tisíc, sedm set a třidceti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 52, 'Mluvil pak Hospodin k Mojžíšovi, řka:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 53, 'Těmto rozdělena bude země k dědictví podlé počtu jmen.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 54, 'Většímu počtu větší dědictví dáš, a menšímu menší; jednomu každému vedlé počtu sečtených jeho dáno bude dědictví jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 55, 'A však losem ať jest rozdělena země; vedlé jmen pokolení otců svých dědictví vezmou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 56, 'Losem děleno bude dědictví její, buď jich mnoho neb málo.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 57, 'Tito pak jsou sečteni z Levítů po čeledech svých: Gerson, z něhož čeled Gersonitská; Kahat, z něhož čeled Kahatská; Merari, z něhož čeled Meraritská.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 58, 'Ty jsou čeledi Léví: Čeled Lebnitská, čeled Hebronitská, čeled Moholitská, čeled Musitská, čeled Choritská. Kahat pak zplodil Amrama.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 59, 'A jméno manželky Amramovy Jochebed, dcera Léví, kteráž se mu narodila v Egyptě; ona pak porodila Amramovi Arona a Mojžíše, a Marii sestru jejich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 60, 'Aronovi pak zrozeni jsou: Nádab a Abiu, Eleazar a Itamar.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 61, 'Ale Nádab a Abiu zemřeli, když obětovali oheň cizí před Hospodinem.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 62, 'I bylo jich načteno třimecítma tisíců, všech pohlaví mužského zstáří měsíce jednoho a výše; nebo nebyli počteni mezi syny Izraelskými, proto že jim nebylo dáno dědictví mezi syny Izraelskými.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 63, 'Tito sečteni jsou od Mojžíše a Eleazara kněze; oni sečtli syny Izraelské na polích Moábských při Jordánu, naproti Jerichu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 64, 'Mezi těmito pak nebyl žádný z oněch sečtených od Mojžíše a Arona kněze, když počítali syny Izraelské na poušti Sinai;');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 65, '(Nebo řekl byl Hospodin o nich: Smrtí zemrou na poušti;) a žádný z nich nepozůstal, jediné Kálef, syn Jefonův, a Jozue, syn Nun.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 1, 'Tehdy přistoupily dcery Salfada, syna Heferova, syna Galád, syna Machir, syna Manasse, z pokolení Manasse, syna Jozefova. Tato pak jsou jména dcer jeho: Mahla, Noa, Hegla, Melcha a Tersa.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 2, 'A postavily se před Mojžíšem a před Eleazarem knězem, i před knížaty a vším množstvím, u dveří stánku úmluvy, a řekly:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 3, 'Otec náš umřel na poušti, kterýž však nebyl z spolku těch, kteříž se zrotili proti Hospodinu v rotě Chóre; nebo pro hřích svůj umřel, synů žádných nemaje.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 4, 'Což vyhlazeno býti má jméno otce našeho z čeledi jeho, proto že neměl syna? Dej nám dědictví mezi bratřími otce našeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 5, 'I vznesl tu věc Mojžíš na Hospodina.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 6, 'Kterýž odpověděl Mojžíšovi, řka:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 7, 'Dobře mluví dcery Salfad. Dejž jim bez odporu právo dědictví mezi bratřími otce jejich, a přenes dědictví otce jejich na ně.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 8, 'K synům pak Izraelským toto mluviti budeš: Když by kdo umřel, nemaje syna, tedy přenesete dědictví jeho na dceru jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 9, 'Pakli by ani dcery neměl, tedy dáte dědictví jeho bratřím jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 10, 'Pakli by ani bratří neměl, tedy dáte dědictví jeho bratřím otce jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 11, 'Pakli by ani strýců neměl, tedy dáte dědictví jeho příteli jeho, kterýž jest nejbližší jemu v rodu jeho, aby dědičně obdržel je. A bude to synům Izraelským za ustanovení soudné, jakož přikázal Hospodin Mojžíšovi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 12, 'Řekl také Hospodin Mojžíšovi: Vstup na horu tuto Abarim, a spatř zemi, kterouž jsem dal synům Izraelským.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 13, 'A když spatříš ji, připojen budeš k lidu svému i ty, jako připojen jest Aron bratr tvůj,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 14, 'Poněvadž jste odporovali řeči mé na poušti Tsin, při odporování všeho množství, kdež jste mne měli posvětiti při vodách před očima jejich. To jsou ty vody sváru v Kádes, na poušti Tsin.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 15, 'I řekl Mojžíš Hospodinu, řka:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 16, 'Opatřiž Hospodin Bůh duchů, Bůh všelikého těla, shromáždění toto mužem hodným,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 17, 'Kterýž by vycházel před nimi, a kterýž by vcházel před nimi, kterýž by vyvodil a zase uvodil je, aby nebylo shromáždění Hospodinovo jako ovce, kteréž nemají pastýře.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 18, 'I řekl Hospodin Mojžíšovi: Vezmi k sobě Jozue, syna Nun, muže, v kterémž jest duch můj, a vlož ruku svou na něj.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 19, 'A postavě jej před Eleazarem knězem a přede vším shromážděním, dáš jemu naučení před očima jejich,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 20, 'A udělíš jemu slávy své, aby ho poslouchalo všecko množství synů Izraelských.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 21, 'Kterýž před Eleazarem knězem postavě se, ptáti se ho bude na soud urim před Hospodinem. K rozkazu jeho vyjdou, a k rozkazu jeho vejdou, on i všickni synové Izraelští s ním, a všecko shromáždění.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 22, 'I učinil Mojžíš tak, jakž mu byl rozkázal Hospodin, a pojav Jozue, postavil jej před Eleazarem knězem a přede vším shromážděním.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 23, 'A vloživ ruce své na něj, dal jemu naučení, jakž mluvil Hospodin skrze Mojžíše.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 1, 'Mluvil také Hospodin k Mojžíšovi, řka:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 2, 'Přikaž synům Izraelským a rci jim: Obětí mých, chleba mého, v obětech mých ohnivých u vůni spokojující mne, nezanedbávejte mi přinášeti v čas k tomu vyměřený.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 3, 'Díš tedy jim: Tato jest obět ohnivá, kterouž obětovati budete Hospodinu: Beránky roční bez poškvrny dva, každého dne v obět zápalnou ustavičně.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 4, 'Beránka jednoho obětovati budeš ráno, a beránka druhého obětovati budeš k večerou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 5, 'Desátý také díl míry efi mouky bělné, v obět suchou, zadělané olejem nejčistším, čtvrtou částkou míry hin.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 6, 'Ta jest obět zápalná ustavičná, kteráž obětována jest na hoře Sinai u vůni příjemnou, v obět ohnivou Hospodinu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 7, 'A obět mokrá její, čtvrtý díl míry hin na každého beránka; v svatyni obětuj obět mokrou silného nápoje Hospodinu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 8, 'Beránka pak druhého obětovati budeš k večerou, tak jako obět suchou jitřní, a jako obět mokrou její obětovati budeš v obět ohnivou, u vůni spokojující Hospodina.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 9, 'Dne také sobotního dva beránky roční bez poškvrny, a dvě desetiny mouky bělné, olejem zadělané v obět suchou s obětí její mokrou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 10, 'Ta bude obět zápalná sobotní každého dne sobotního, mimo zápalnou obět ustavičnou a mokrou obět její.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 11, 'Také na nov měsíců vašich obětovati budete obět zápalnou Hospodinu, volky mladé dva, skopce jednoho, beránků ročních bez poškvrny sedm;');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 12, 'A tři desetiny mouky bělné, olejem zadělané v obět suchou při každém volku, a dvě desetiny mouky bělné, olejem zadělané v obět suchou při každém skopci;');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 13, 'A jednu desetinu mouky bělné olejem zadělané v obět suchou při každém beránku, k oběti zápalné u vůni příjemnou, v obět ohnivou Hospodinu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 14, 'Tyto pak oběti mokré jejich z vína: Půl míry hin bude při každém volku, a třetí částka hin při skopci, a čtvrtá částka hin při každém beránku. Ta jest obět zápalná k nov měsíci, každého měsíce přes celý rok.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 15, 'Kozla také jednoho v obět za hřích, mimo obět ustavičnou, obětovati budete Hospodinu s mokrou obětí jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 16, 'Měsíce pak prvního, čtrnáctý den téhož měsíce velikanoc bude Hospodinu,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 17, 'A v patnáctý den téhož měsíce slavnost; za sedm dní chleby nekvašené jísti budete.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 18, 'Prvního dne shromáždění svaté bude, žádného díla robotného nebudete dělati v něm.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 19, 'Obětovati pak budete obět ohnivou v zápal Hospodinu, volky mladé dva, skopce jednoho, a sedm beránků ročních; bez poškvrny budou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 20, 'A suchou obět při nich, totiž mouku bělnou, olejem zadělanou, tři desetiny při každém volku, a dvě desetiny při každém skopci obětovati budete.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 21, 'A jednu desetinu obětovati budeš při každém beránku z těch sedmi beránků,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 22, 'A kozla v obět za hřích jednoho k očištění vás.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 23, 'Mimo obět zápalnou jitřní, kteráž jest obět ustavičná, obětovati budete to.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 24, 'Tak obětovati budete každého dne za těch sedm dní pokrm oběti ohnivé, u vůni spokojující Hospodina, mimo zápalnou obět ustavičnou, a obět mokrou její.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 25, 'Sedmého pak dne shromáždění svaté míti budete, žádného díla robotného nebudete dělati.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 26, 'V den také prvotin, když obětovati budete novou obět suchou Hospodinu, vyplníc téhodny vaše, shromáždění svaté míti budete; žádného díla robotného nebudete dělati.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 27, 'A obětovati budete obět zápalnou, u vůni spokojující Hospodina, volky mladé dva, skopce jednoho, beránků ročních sedm,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 28, 'A obět suchou jejich, mouky bělné olejem zadělané tři desetiny při každém volku, dvě desetiny při každém skopci,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 29, 'Jednu desetinu při každém beránku z těch sedmi beránků,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 30, 'Kozla jednoho k očištění vašemu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 31, 'To mimo obět zápalnou ustavičnou, a obět suchou její obětovati budete; bez poškvrny ať jsou s obětmi svými mokrými.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 1, 'Měsíce pak sedmého v první den jeho shromáždění svaté míti budete, žádného díla robotného nebudete dělati; to jest den troubení vašeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 2, 'A obětovati budete zápal u vůni příjemnou Hospodinu, volka mladého jednoho, skopce jednoho, beránků ročních bez poškvrny sedm;');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 3, 'A obět suchou při nich z mouky bělné olejem zadělané, tři desetiny na každého volka, a dvě desetiny na každého skopce;');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 4, 'A desetina jedna na každého beránka z sedmi beránků;');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 5, 'A kozla jednoho v obět za hřích k očištění vás.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 6, 'Mimo zápalnou obět novoměsíčnou s obětí její suchou, a mimo obět zápalnou ustavičnou s obětí její suchou, a s obětmi jejich mokrými vedlé pořádku jejich, u vůni příjemnou, v obět ohnivou Hospodinu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 7, 'V desátý pak den téhož měsíce sedmého shromáždění svaté míti budete, a ponižovati budete životů svých; žádného díla nebudete dělati.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 8, 'A obětovati budete obět zápalnou Hospodinu u vůni příjemnou, volka mladého jednoho, skopce jednoho, beránků ročních sedm, a ti ať jsou bez poškvrny;');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 9, 'A obět suchou jejich z mouky bělné olejem zadělané, tři desetiny na každého volka, a dvě desetiny na každého skopce;');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 10, 'A desetina jedna na každého beránka z těch sedmi beránků;');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 11, 'Kozla jednoho v obět za hřích, mimo obět za hřích k očištění, a mimo zápal ustavičný s obětí suchou jeho, a s obětmi mokrými jejich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 12, 'V patnáctý také den měsíce sedmého shromáždění svaté míti budete; žádného díla robotného nebudete dělati, ale slaviti budete svátek Hospodinu za sedm dní.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 13, 'A obětovati budete zápal v obět ohnivou u vůni spokojující Hospodina, volků mladých třinácte, skopce dva, beránků ročních čtrnácte, a ti ať jsou bez poškvrny;');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 14, 'Též obět suchou jejich z mouky bělné olejem zadělané, tři desetiny na každého volka z třinácti volků, dvě desetiny na každého skopce z těch dvou skopců,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 15, 'A jednu desetinu na každého beránka z těch čtrnácti beránků;');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 16, 'A kozla jednoho v obět za hřích, mimo zápal ustavičný s obětí jeho suchou i mokrou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 17, 'Potom dne druhého volků mladých dvanácte, skopce dva, beránků ročních bez poškvrny čtrnácte,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 18, 'S obětí suchou při nich, a s obětmi mokrými jejich při každém volku, skopci i beránku vedlé počtu jejich, jakž jest obyčej;');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 19, 'A kozla jednoho v obět za hřích, mimo zápal ustavičný s obětí suchou jeho a s obětmi mokrými jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 20, 'Dne pak třetího volků jedenácte, skopce dva, a beránků ročních bez poškvrny čtrnácte,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 21, 'S obětí suchou a s obětmi mokrými jejich při každém volku, skopci i beránku, vedlé počtu jejich, jakž jest obyčej;');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 22, 'A kozla v obět za hřích jednoho, mimo obět zápalnou ustavičnou s obětí její suchou i mokrou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 23, 'Dne pak čtvrtého volků deset, skopce dva, beránků ročních bez poškvrny čtrnácte,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 24, 'S obětí suchou i s obětmi mokrými jejich při každém volku, skopci a beránku, vedlé počtu jejich, jakž jest obyčej;');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 25, 'A kozla jednoho v obět za hřích, mimo obět zápalnou ustavičnou s obětí její suchou i mokrou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 26, 'Dne také pátého volků devět, skopce dva, beránků ročních bez poškvrny čtrnácte,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 27, 'S obětí suchou i s obětmi mokrými jejich při každém volku, skopci i beránku, vedlé počtu jejich, jakž jest obyčej;');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 28, 'A kozla jednoho v obět za hřích, mimo obět zápalnou ustavičnou s obětí její suchou i mokrou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 29, 'A dne šestého volků osm, skopce dva, beránků ročních bez poškvrny čtrnácte,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 30, 'S obětí suchou a s obětmi mokrými jejich při každém volku, skopci i beránku, vedlé počtu jejich, jakž jest obyčej;');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 31, 'A kozla jednoho v obět za hřích, mimo obět zápalnou ustavičnou s obětí její suchou i s obětmi mokrými.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 32, 'Tolikéž dne sedmého volků sedm, skopce dva, beránků ročních bez poškvrny čtrnácte,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 33, 'S obětí suchou i s obětmi mokrými jejich na volky, skopce i beránky, vedlé počtu jejich, jakž jest obyčej;');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 34, 'A kozla jednoho v obět za hřích, mimo obět zápalnou ustavičnou s obětí její suchou i mokrou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 35, 'Dne pak osmého slavnost míti budete; žádného díla robotného nebudete dělati.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 36, 'A obětovati budete obět zápalnou, v obět ohnivou vůně spokojující Hospodina, volka jednoho, skopce jednoho, a beránků ročních sedm bez poškvrny,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 37, 'S obětí suchou i s obětmi mokrými jejich při volku, skopci i beráncích, vedlé počtu jejich, jakž jest obyčej;');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 38, 'A kozla jednoho v obět za hřích, mimo obět zápalnou ustavičnou s obětí její suchou i mokrou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 39, 'Ty věci vykonávati budete Hospodinu při slavnostech vašich, kromě toho, což byste z slibu aneb z dobré vůle své obětovali, buď zápalné, aneb suché, aneb mokré, aneb pokojné oběti vaše.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 40, 'I oznámil Mojžíš synům Izraelským všecky ty věci, kteréž přikázal jemu Hospodin.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 1, 'Mluvil také Mojžíš knížatům pokolení synů Izraelských, řka: Totoť jest, což přikázal Hospodin:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 2, 'Jestliže by muž slib aneb přísahu učinil Hospodinu, závazkem zavazuje duši svou, nezruší slova svého; podlé všeho, což vyšlo z úst jeho, učiní.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 3, 'Když by pak osoba ženského pohlaví učinila slib Hospodinu, a závazkem zavázala se v domě otce svého v mladosti své,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 4, 'A slyše otec její slib a závazek její, jímž zavázala duši svou, mlčel by k tomu: tedy stálí budou všickni slibové její, i každý závazek, jímž zavázala se, stálý bude.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 5, 'Jestliže by pak to zrušil otec její toho dne, když slyšel všecky ty sliby a závazky její, jimiž zavázala duši svou, nebudouť stálí; a Hospodin odpustí jí, nebo otec její to zrušil.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 6, 'Pakli by vdaná byla za muže, a měla by slib na sobě, aneb pronesla by ústy svými něco, čímž by se zavázala,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 7, 'A slyše muž její, nic by jí neřekl toho dne, kteréhož slyšel: stálí budou slibové její, i závazkové, jimiž zavázala duši svou, stálí budou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 8, 'Jestliže by pak muž její toho dne, jakž uslyšel, odepřel tomu, a zrušil slib, kterýž na sobě měla, aneb něco rty svými pronesla, čímž by se zavázala, také odpustí jí Hospodin.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 9, 'Všeliký pak slib vdovy aneb ženy zahnané, jímž by se zavázala, stálý bude.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 10, 'Ale jestliže v domě muže svého slíbila, a závazkem zavázala se s přísahou,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 11, 'A slyše to muž její, mlčel k tomu a neodepřel: tedy stálí budou všickni slibové její, a všickni závazkové, jimiž se zavázala, stálí budou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 12, 'Pakli docela odepřel muž její toho dne, jakž uslyšel, všeliký slib, kterýž vyšel z úst jejích, a závazek, jímž zavázala se, nebude stálý; muž její zrušil to, a Hospodin jí odpustí.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 13, 'Všelikého slibu a každého závazku s přísahou učiněného o trápení života jejího, muž její potvrdí jeho, a muž její zruší jej.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 14, 'Pakli by muž její den po dni mlčel, tedy potvrdí všech slibů jejích, a všech závazků jejích, kteréž na sobě má; potvrdilť jest jich, nebo neodepřel jí v den ten, když to uslyšel.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 15, 'Jestliže by pak slyše, potom teprv zrušiti to chtěl, tedy on ponese nepravost její.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 16, 'Ta jsou ustanovení, kteráž přikázal Hospodin Mojžíšovi, mezi mužem a ženou jeho, mezi otcem a dcerou jeho v mladosti její, dokudž jest v domě otce svého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 1, 'Mluvil opět Hospodin k Mojžíšovi, řka:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 2, 'Pomsti prvé synů Izraelských nad Madianskými, a potom připojen budeš k lidu svému.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 3, 'Mluvil tedy Mojžíš k lidu, řka: Vypravte některé z sebe k boji, aby šli proti Madianským a vykonali pomstu Hospodinovu nad nimi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 4, 'Po tisíci z pokolení, ze všech pokolení Izraelských vyšlete k boji.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 5, 'I vydáno jest z mnohých tisíců Izraelských po tisíci z každého pokolení, totiž dvanácte tisíců způsobných k boji.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 6, 'I poslal je Mojžíš po tisíci z každého pokolení k boji, a Fínesa syna Eleazara kněze s nimi; a nádoby svaté i trouby k troubení byly v ruce jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 7, 'Tedy bojovali proti Madianským, jakož byl přikázal Hospodin Mojžíšovi, a zbili všecky pohlaví mužského.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 8, 'Pobili také krále Madianské mezi jinými, kteréž porazili, totiž Evi, Rekem, Sur, Hur a Rebe, pět králů Madianských; Baláma také, syna Beorova, zabili mečem.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 9, 'A zajali synové Izraelští ženy Madianské i děti jejich; všecka hovada jejich, i všechny dobytky jejich, a všecka zboží jejich pobrali.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 10, 'Všecka také města jejich, v kterýchž svá obydlí měli, i všecky hrady jejich vypálili ohněm.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 11, 'A všecku loupež i všecky kořisti pobravše, lidi i hovada,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 12, 'Vedli je k Mojžíšovi a k Eleazarovi knězi, a ke všemu množství synů Izraelských, i zajaté i kořisti, i loupeže, k vojsku na roviny Moábské, kteréž jsou při Jordánu naproti Jerichu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 13, 'I vyšli Mojžíš a Eleazar kněz a všecka knížata shromáždění proti nim ven za stany.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 14, 'Tedy rozhněval se Mojžíš na vůdce vojska, hejtmany nad tisíci a setníky, kteříž se navraceli z boje,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 15, 'A řekl jim Mojžíš: A což jste zachovali všecky ženy?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 16, 'Ej, onyť jsou hle synům Izraelským, podlé rady Balámovy, daly příčinu k přestoupení proti Hospodinu, při modlářství Fegor, pročež ona rána přišla byla na lid Hospodinův.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 17, 'Protož nyní zmordujte všecky děti pohlaví mužského, a všecky ženy, kteréž poznaly muže.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 18, 'Všecky pak panny, kteréž nepoznaly muže, zachovejte sobě živé.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 19, 'Vy pak zůstaňte vně za stany za sedm dní; všickni, kteřížkoli jste někoho zabili, aneb kteříž jste se zabitého dotkli, očišťovati se budete dne třetího a dne sedmého, sebe i zajaté své.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 20, 'Všeliké také roucho a všecky věci kožené, i všelijaké dílo z srstí kozích, i všelikou nádobu dřevěnou očistíte.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 21, 'I řekl Eleazar kněz vojákům, kteříž byli šli k boji: Toto jest ustanovení zákona, kteréž byl přikázal Hospodin Mojžíšovi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 22, 'Zlato však, stříbro, měď, železo, cín a olovo,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 23, 'A cožkoli trpí oheň, ohněm přepálíte, a přečištěno bude, však tak, když vodou očišťování obmyto bude; což pak nemůže ohně strpěti, to skrze vodu protáhnete.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 24, 'Zpéřete také roucha svá v den sedmý, a čistí budete; a potom vejdete do stanů.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 25, 'Mluvil i to Hospodin k Mojžíšovi, řka:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 26, 'Sečti summu kořistí zajatých, tak z lidí jako z hovad, ty a Eleazar kněz, a přední z čeledi otců v lidu;');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 27, 'A rozdělíš ty kořisti na dva díly, jeden mezi vojáky, kteříž byli vytáhli na vojnu, a druhý mezi všecko shromáždění.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 28, 'A vezmeš díl na Hospodina od mužů bojovných, kteříž byli vyšli na vojnu, jednu duši z pěti set, buďto z lidí neb z hovad, neb z oslů, neb z ovcí.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 29, 'Z jejich polovice to vezmete, a dáte Eleazarovi knězi obět vzhůru pozdvižení Hospodinu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 30, 'Z polovice pak té, kteráž jest synů Izraelských, vezmeš jedno z padesáti, buďto z lidí neb z volů, neb z oslů, neb z ovcí, a tak ze všelijakých hovad, a dáš to Levítům, držícím stráž příbytku Hospodinova.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 31, 'I učinil Mojžíš a Eleazar kněz tak, jakž byl rozkázal Hospodin Mojžíšovi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 32, 'A bylo té kořisti z pozůstalé ještě loupeže, kteréž nabral lid válečný, ovec šestkrát sto tisíc, sedmdesáte a pět tisíců;');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 33, 'A volů sedmdesáte a dva tisíce;');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 34, 'Oslů šedesáte a jeden tisíců;');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 35, 'A panen, kteréž mužů nepoznaly, všech dva a třidceti tisíců.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 36, 'Dostala se pak polovice jedna na díl těm, kteříž byli vytáhli na vojnu, dobytka drobného v počtu třikrát sto tisíc, třidceti a sedm tisíců a pět set,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 37, 'A na díl vzatý Hospodinu dobytka drobného šest set, sedmdesáte pět.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 38, 'A z volů šest a třidceti tisíců, z nichž přišlo na díl Hospodinu sedmdesáte a dva.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 39, 'Oslů také třidceti tisíc a pět set, z nichž přišlo na díl Hospodinu šedesáte a jeden.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 40, 'A lidí šestnácte tisíců, z nichž přišlo na díl Hospodinu třidceti a dvě duše.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 41, 'Dal tedy Mojžíš díl oddělený Hospodinu Eleazarovi knězi, jakž byl přikázal Hospodin Mojžíšovi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 42, 'Z druhé pak polovice synů Izraelských, kterouž vzal Mojžíš od těch mužů, jenž bojovali,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 43, '(A bylo té polovice k shromáždění přináležející z ovec třikrát sto tisíc, třidceti a sedm tisíců a pět set;');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 44, 'Volů třidceti šest tisíců;');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 45, 'Oslů třidceti tisíců a pět set;');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 46, 'A lidí šestnácte tisíců;)');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 47, 'Z té tedy polovice synů Izraelských vzal Mojžíš po jednom zajatém z padesáti, tak z lidí jako z hovad, a dal to Levítům, držícím stráž příbytku Hospodinova, jakž byl přikázal Hospodin Mojžíšovi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 48, 'Tedy přistoupili k Mojžíšovi vývodové vojska, hejtmané nad tisíci a setníci,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 49, 'A řekli jemu: My služebníci tvoji sečtli jsme počet bojovníků, kteréž jsme měli pod spravou naší, a neubyl ani jeden z nás.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 50, 'A protož obětujeme obět Hospodinu, každý z toho, čehož jest dostal, nádobí zlaté, zápony, náramky, prsteny, náušnice a řetízky, aby očištěny byly duše naše před Hospodinem.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 51, 'Vzal tedy Mojžíš a Eleazar kněz od nich to zlato všelikého díla řemeslného.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 52, 'Bylo pak všeho zlata odděleného, kteréž obětováno Hospodinu, šestnácte tisíců, sedm set a padesáte lotů, od hejtmanů nad tisíci a od setníků.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 53, '(Muži zajisté bojovní, což loupeží vzali, to sobě měli.)');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 54, 'A vzavše Mojžíš a Eleazar kněz od hejtmanů nad tisíci a setníků to zlato, vnesli je do stánku úmluvy, na památku synů Izraelských před Hospodinem.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 1, 'Měli pak synové Ruben a synové Gád dobytka velmi mnoho, a uzřeli zemi Jazer a zemi Galád, ano místo to místo příhodné pro dobytek.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 2, 'Protož přistoupivše synové Gád a synové Ruben, mluvili k Mojžíšovi a k Eleazarovi knězi a knížatům shromáždění, řkouce:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 3, 'Atarot a Dibon, a Jazer a Nemra, Ezebon a Eleale, a Saban a Nébo a Beon,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 4, 'Země, kterouž zbil Hospodin před shromážděním Izraelským, jest země příhodná ku pastvě dobytku, a my služebníci tvoji máme drahně dobytka.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 5, '(Protož řekli:) Jestliže jsme nalezli milost před očima tvýma, nechť jest dána krajina ta služebníkům tvým k vládařství, ať nechodíme za Jordán.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 6, 'I odpověděl Mojžíš synům Gád a synům Ruben: Což bratří vaši půjdou sami k boji, a vy zde zůstanete?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 7, 'I proč roztrhujete mysli synů Izraelských, aby nesměli jíti do země, kterouž jim dal Hospodin?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 8, 'Takť jsou učinili otcové vaši, když jsem je poslal z Kádesbarne, aby prohlédli zemi tu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 9, 'Kteřížto, když přišli až k údolí Eškol a shlédli zemi, potom vrátivše se, odvrátili mysl synů Izraelských, aby nešli do země, kterouž dal jim Hospodin.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 10, 'Čímž popuzen jsa k hněvu Hospodin v den ten, přisáhl, řka:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 11, 'Zajisté že lidé ti, kteříž vyšli z Egypta, od dvadcítiletých a výše, neuzří země té, kterouž jsem s přísahou zaslíbil Abrahamovi, Izákovi a Jákobovi, nebo ne cele následovali mne,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 12, 'Kromě Kálefa, syna Jefonova Cenezejského, a Jozue, syna Nun, nebo cele následovali Hospodina.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 13, 'I popudila se prchlivost Hospodinova na Izraele, a učinil, aby byli tuláci na poušti za čtyřidceti let, dokudž nezahynul všecken ten věk, kterýž činil zlé před očima Hospodinovýma.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 14, 'A hle, vy nastoupili jste na místo otců svých, plémě lidí hříšných, abyste vždy přidávali k hněvu prchlivosti Hospodinovy na Izraele.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 15, 'Jestliže se odvrátíte od následování jeho, i onť také opustí jej na poušti této, a tak budete příčina zahynutí všeho lidu tohoto.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 16, 'Přistoupivše pak znovu, řekli jemu: Stáje dobytkům a stádům svým zde vzděláme, a města dítkám svým,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 17, 'Sami pak v odění pohotově budeme, statečně sobě počínajíce před syny Izraelskými, dokavadž jich neuvedeme na místo jejich; mezi tím zůstanou dítky naše v městech hrazených, pro bezpečnost před obyvateli země.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 18, 'Nenavrátíme se do domů svých, až prvé vládnouti budou synové Izraelští jeden každý dědictvím svým;');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 19, 'Aniž vezmeme jakého dědictví s nimi za Jordánem neb dále, když dosáhneme dědictví svého z této strany Jordánu, k východu slunce.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 20, 'I odpověděl jim Mojžíš: Jestliže učiníte tak, jakž jste mluvili, a jestliže půjdete v odění před Hospodinem k boji,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 21, 'A šli byste za Jordán vy všickni v odění před Hospodinem, dokavadž by nevyhnal nepřátel svých od tváři své,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 22, 'A nebyla podmaněna všecka země před Hospodinem: potom navrátíte se, a budete bez viny před Hospodinem i před Izraelem; tak přijde země tato vám v dědictví před Hospodinem.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 23, 'Pakli neučiníte toho, hle, zhřešíte proti Hospodinu, a vězte, že pomsta vaše přijde na vás.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 24, 'Stavějte sobě tedy města pro dítky, a stáje pro dobytky své, a což vyšlo z úst vašich, učiňte.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 25, 'I odpovědělo pokolení synů Gád a synů Ruben Mojžíšovi, řka: Služebníci tvoji učiní, jakž pán náš rozkazuje.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 26, 'Dítky naše a ženy naše, dobytek náš a všecka hovada naše, tu zůstanou v městech Galád,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 27, 'Služebníci pak tvoji přejdou jeden každý v odění způsobný před Hospodinem k boji, jakož mluví pán můj.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 28, 'I poručil o nich Mojžíš Eleazarovi knězi a Jozue, synu Nun, a předním v čeledech pokolení synů Izraelských,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 29, 'A řekl jim: Jestliže přejdou synové Gád a synové Ruben s vámi za Jordán všickni hotovi k boji před Hospodinem, a byla by již podmaněna země před vámi, dáte jim zemi Galád k vládařství.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 30, 'Pakli by nešli v odění s vámi, tedy dědictví míti budou u prostřed vás v zemi Kanán.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 31, 'I odpověděli synové Gád a synové Ruben, řkouce: Jakž mluvil Hospodin služebníkům tvým, tak učiníme:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 32, 'My půjdeme v odění před Hospodinem do země Kanán, a zůstane nám v dědictví vládařství naše z této strany Jordánu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 33, 'Tedy dal jim Mojžíš, synům totiž Gád a synům Ruben a polovici pokolení Manasses, syna Jozefova, království Seona, krále Amorejského, a království Oga, krále Bázanského, zemi s městy jejími při pomezích, i města země té všudy vůkol.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 34, 'A vzdělali synové Gád, Dibon, Atarot a Aroer,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 35, 'A Atrot, Sofan, Jazer a Jegbaa,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 36, 'A Betnemra a Betaran, města hrazená, a stáje pro dobytky.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 37, 'Synové pak Ruben vystavěli Ezebon, Eleale a Kariataim,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 38, 'A Nébo a Balmeon, změnivše jim jména; také Sabma, a dali jiná jména městům, kteráž vzdělali.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 39, 'Táhli pak synové Machir, syna Manassesova, do Galád, a vzavše tu krajinku, vyhnali Amorejského, kterýž tam bydlil.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 40, 'I dal Mojžíš zemi Galád Machirovi, synu Manassesovu, a bydlil v ní.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 41, 'Jair také syn Manassesův táhl a vzal vsi jejich, a nazval je vsi Jairovy.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 42, 'Nobe také táhl, a vzal Kanat a městečka jeho, a nazval je Nobe od jména svého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 1, 'Tato jsou tažení synů Izraelských, kteříž vyšli z země Egyptské po houfích svých, pod spravou Mojžíše a Arona.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 2, 'Sepsal pak Mojžíš vycházení jejich podlé toho, jakž táhli k rozkazu Hospodinovu. Tato jsou tedy vycházení jejich podlé toho, jakž táhli.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 3, 'Nejprv z Ramesses jdouce prvního měsíce, v patnáctý den téhož prvního měsíce, nazejtří po slavnosti Fáze vyšli synové Izraelští v ruce silné před očima všech Egyptských,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 4, 'Kdyžto Egyptští pochovávali všecky prvorozené, kteréž zbil Hospodin mezi nimi, a při bozích jejich vykonal Hospodin soudy své.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 5, 'Hnuvše se tedy synové Izraelští z Ramesses, položili se v Sochot.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 6, 'Potom hnuvše se z Sochot, položili se v Etam, jenž jest při kraji pouště.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 7, 'A hnuvše se z Etam, navrátili se zase k Fiarot, jenž jest před Belsefon, a položili se před Magdalem.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 8, 'A hnuvše se z Fiarot, šli prostředkem moře na poušť, a ušedše tří dnů cesty po poušti Etam, položili se v Marah.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 9, 'Jdouce pak z Marah, přišli do Elim, kdežto bylo dvanácte studnic vod, a sedmdesáte palm. I položili se tu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 10, 'A hnuvše se z Elim, položili se u moře Rudého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 11, 'Potom hnuvše se od moře Rudého, položili se na poušti Sin.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 12, 'A když se hnuli z pouště Sin, položili se v Dafka.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 13, 'A hnuvše se z Dafka, položili se v Halus.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 14, 'Hnuvše se pak z Halus, rozbili stany v Rafidim, kdežto lid neměl vody ku pití.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 15, 'A hnuvše se z Rafidim, položili se na poušti Sinai.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 16, 'Hnuvše se pak z pouště Sinai, položili se v Kibrot Hattáve.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 17, 'A když se hnuli z Kibrot Hattáve, položili se v Hazerot.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 18, 'Hnuvše se pak z Hazerot, položili se v Retma.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 19, 'A z Retma hnuvše se, položili se v Remmon Fáres.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 20, 'Potom hnuvše se z Remmon Fáres, položili se v Lebna.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 21, 'A hnuvše se z Lebna, položili se v Ressa.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 22, 'A hnuvše se z Ressa, položili se v Cehelot.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 23, 'Z Cehelot pak hnuvše se, položili se na hoře Sefer.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 24, 'A když se hnuli s hory Sefer, položili se v Arad.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 25, 'A hnuvše se z Arad, položili se v Machelot.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 26, 'Potom hnuvše se z Machelot, položili se v Tahat.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 27, 'A hnuvše se z Tahat, položili se v Tár.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 28, 'A když se hnuli z Tár, položili se v Metka.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 29, 'A hnuvše se z Metka, položili se v Esmona.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 30, 'Z Esmona pak hnuvše se, položili se v Moserot.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 31, 'A když se hnuli z Moserot, položili se v Benejakan.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 32, 'A hnuvše se z Benejakan, položili se v Chor Gidgad.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 33, 'A hnuvše se z Chor Gidgad, položili se v Jotbata.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 34, 'Když se pak hnuli z Jotbata, položili se v Habrona.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 35, 'A z Habrona hnuvše se, položili se v Aziongaber.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 36, 'A odtud hnuvše se, položili se na poušti Tsin, jenž jest Kádes.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 37, 'A hnuvše se z Kádes, položili se na hoře řečené Hor, při končinách země Edomské.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 38, 'Tu vstoupil Aron kněz na horu, jenž slove Hor, k rozkazu Hospodinovu, a umřel tam, léta čtyřidcátého po vyjití synů Izraelských z země Egyptské, v první den měsíce pátého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 39, 'A byl Aron ve stu ve dvadcíti a třech letech, když umřel na hoře Hor.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 40, 'Uslyšel také Kananejský král v Arad, kterýž bydlil na poledne v zemi Kananejské, že by táhli synové Izraelští.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 41, 'Tedy hnuvše se s hory Hor, položili se v Salmona.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 42, 'A hnuvše se z Salmona, položili se v Funon.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 43, 'Z Funon pak hnuvše se, položili se v Obot.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 44, 'A když se hnuli z Obot, rozbili stany při pahrbcích hor Abarim, na pomezí Moábském.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 45, 'Potom hnuvše se od těch pahrbků, položili se v Dibongad.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 46, 'Z Dibongad hnuvše se, položili se v Helmondeblataim.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 47, 'A když se hnuli z Helmondeblataim, položili se na horách Abarim proti Nébo.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 48, 'Odšedše pak z hor Abarim, položili se na rovinách Moábských, při Jordánu proti Jerichu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 49, 'A rozbili stany při Jordánu, od Betsimot až do Abelsetim, na rovinách Moábských.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 50, 'Mluvil pak Hospodin k Mojžíšovi na rovinách Moábských, při Jordánu naproti Jerichu, řka:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 51, 'Mluv k synům Izraelským a rci jim: Když přejdete Jordán, a vejdete do země Kananejské,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 52, 'Vyžeňte všecky obyvatele země té od tváři vaší, a zkazte všecky rytiny jejich; i všecky obrazy slité jejich zkazte, všecky také výsosti jejich zbořte.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 53, 'A když vyženete obyvatele země, bydliti budete v ní; nebo vám jsem dal tu zemi, abyste jí dědičně vládli.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 54, 'Kteroužto rozdělíte sobě k dědictví losem, vedlé čeledí svých. Kterých jest více, těm větší dědictví dáte, kterých pak jest méně, těm menší dědictví dáte. Na kterém místě komu los padne, to jemu bude; podlé pokolení otců svých dědictví dosáhnete.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 55, 'Pakli nevyženete obyvatelů země od tváři své, tedy ti, kterýchž zanecháte, budou vám jako trní v očích vašich, a jako ostnové po bocích vašich, a budou vás ssužovati na zemi, na kteréž vy bydliti budete.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 56, 'A na to přijde, abych to, což jsem jim umínil učiniti, vám učinil.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 1, 'Mluvil také Hospodin k Mojžíšovi, řka:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 2, 'Přikaž synům Izraelským a rci jim: Když vejdete do země Kanán, (tať jest země, kteráž se dostane vám v dědictví, země Kananejská s pomezími svými,)');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 3, 'Strana polední vaše bude poušť Tsin vedlé pomezí Edomských; a bude vaše pomezí polední od břehu moře slaného k východu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 4, 'A zatočí se to pomezí polední k Maleakrabim, a půjde až k Tsin, a potáhne se od poledne přes Kádesbarne; a odtud vyjde ke vsi Addar, a vztáhne se až k Asmon.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 5, 'Od Asmon zatočí se pomezí to vůkol až ku potoku Egyptskému, a tu se skonávati bude k západu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 6, 'Pomezí pak západní budete míti moře veliké; to bude vaše pomezí západní.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 7, 'A pomezí půlnoční toto míti budete: Od moře velikého vyměříte sobě k hoře řečené Hor.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 8, 'Od hory Hor vyměříte sobě, až kde se vchází do Emat, a skonávati se bude pomezí to u Sedad.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 9, 'A odtud půjde pomezí to k Zefronu, a konec jeho u vsi Enan; to bude pomezí vaše k straně půlnoční.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 10, 'Vyměříte sobě také pomezí k východu od vsi Enan až do Sefama.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 11, 'A od Sefama schýlí se to pomezí až k Reblata, od východu maje Ain; a schýlí se pomezí to, a přijde k straně moře Ceneret k východu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 12, 'A vztáhne se to pomezí k Jordánu, a bude konec jeho u slaného moře. Ta země vaše bude po svých pomezích vůkol.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 13, 'Tedy oznámil to Mojžíš synům Izraelským, řka: Ta jest země, kterouž dědičně obdržíte losem, jakož přikázal Hospodin, abych ji dal devateru pokolení a polovici pokolení Manassesova.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 14, 'Nebo vzalo pokolení synů Ruben po domích otců svých, a pokolení synů Gád po domích otců svých, a polovice pokolení Manassesova vzali dědictví své.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 15, 'Půl třetího pokolení vzali dědictví své před Jordánem proti Jerichu, k straně na východ slunce.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 16, 'Mluvil opět Hospodin k Mojžíšovi, řka:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 17, 'Tato jsou jména mužů, kteříž v dědictví rozdělí vám zemi: Eleazar kněz, a Jozue, syn Nun.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 18, 'Kníže také jedno z každého pokolení vezmete k rozdělování dědictví země.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 19, 'A tato jsou jména mužů: Z pokolení Juda Kálef, syn Jefonův;');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 20, 'Z pokolení synů Simeon Samuel, syn Amiudův;');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 21, 'Z pokolení Beniaminova Helidad, syn Chaselonův;');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 22, 'Z pokolení synů Dan kníže Bukci, syn Jogli;');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 23, 'Z synů Jozefových z pokolení synů Manasses kníže Haniel, syn Efodův;');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 24, 'Z pokolení synů Efraim kníže Kamuel, syn Seftanův;');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 25, 'A z pokolení synů Zabulon kníže Elizafan, syn Farnachův;');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 26, 'Z pokolení synů Izachar kníže Faltiel, syn Ozanův;');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 27, 'A z pokolení synů Asser kníže Ahiud, syn Salonův;');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 28, 'A z pokolení synů Neftalím kníže Fedael, syn Amiudův.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 29, 'Ti jsou, jimž přikázal Hospodin, aby rozdělili země k dědictví synům Izraelským v zemi Kananejské.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 1, 'I mluvil Hospodin k Mojžíšovi na rovinách Moábských, při Jordánu proti Jerichu, řka:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 2, 'Přikaž synům Izraelským, ať dadí Levítům z dědictví, kterýmž vládnouti budou, města k bydlení, i podměstí měst vůkol nich,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 3, 'Aby měli města k bydlení, podměstí pak jejich pro dobytky jejich, i pro statky jejich, a pro všecka hovada jejich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 4, 'Podměstí pak měst, kteráž dáte Levítům, vzdálí budou ode zdi městské na tisíc loktů zevnitř vůkol.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 5, 'Protož vyměříte vně za každým městem na východ slunce dva tisíce loktů, na poledne též dva tisíce loktů, také na západ dva tisíce loktů, i na půlnoci dva tisíce loktů, tak aby bylo město v prostředku. Ta bude míra podměstí měst jejich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 6, 'Z těch pak měst, kteráž dáte Levítům, oddělíte šest měst k útočišti, aby tam utekl, kdož by někoho zabil; a k těm přidáte jim ještě čtyřidceti dvě města.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 7, 'I bude všech měst, kteráž dáte Levítům, čtyřidceti osm měst i s podměstími jejich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 8, 'Těch pak měst, kteráž dáte z vládařství synů Izraelských, od těch, kteříž více mají, více vezmete, a od těch, kteříž méně mají, méně vezmete; jedno každé pokolení vedlé velikosti dědictví, jímž vládnouti budou, dá z měst svých Levítům.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 9, 'I mluvil Hospodin k Mojžíšovi, řka:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 10, 'Mluv k synům Izraelským a rci jim: Když přejdete Jordán, a vejdete do země Kananejské,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 11, 'Vybéřete sobě města, a ta města budete míti k utíkání, aby tam utekl ten, kterýž by někoho zabil z nedopatření.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 12, 'A budou vám ta města k útočišti před přítelem, aby neumřel ten, kdož zabil, dokudž by se nepostavil před shromážděním k soudu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 13, 'Z těch tedy měst, kteráž dáte, šest měst k útočišti míti budete.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 14, 'Tři města dáte před Jordánem, též tři města dáte v zemi Kananejské; i budou města útočiště.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 15, 'Synům Izraelským i příchozímu, i podruhu mezi nimi bude těch šest měst k útočišti, aby tam utekl, kdož by koli ranil někoho z nedopatření.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 16, 'Jestliže by pak železem ranil někoho, tak až by umřel, vražedlník jest; smrtí umře vražedlník takový.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 17, 'Pakli by hodě kamenem, jímž by mohl zabiti, udeřil někoho, tak že by umřel, vražedlník jest; smrtí umře vražedlník takový.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 18, 'Pakli by hodě dřevem, kterýmž by mohl zabiti, udeřil někoho, tak že by umřel, vražedlník jest; smrtí umře vražedlník takový.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 19, 'Přítel zabitého zabije vražedlníka toho; kdyžkoli ho dostane, on sám zabije ho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 20, 'Aneb jestliže by z nenávisti strčil někým, aneb shodil by něco na něho z úkladu, tak že by od toho umřel;');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 21, 'Aneb jestliže by z nepřátelství rukou udeřil někoho, tak že by umřel: smrtí umře bitec ten, vražedlník jest; přítel zabitého zabije vražedlníka toho, jakž ho nejprv dostane.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 22, 'Jestliže by pak náhodou a ne z nepřátelství strčil někým, aneb shodil by na něho nějakou věc bez úkladu;');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 23, 'Aneb jaký koli kámen, od něhož by umříti mohl, shodil by na něj z nedopatření, tak že by umřel, nebyv s ním v nepřátelství, ani nehledaje zlého jeho:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 24, 'Tedy souditi bude shromáždění mezi bitcem a mezi přítelem zabitého vedlé soudů těchto.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 25, 'A vysvobodí shromáždění vražedlníka toho z rukou přítele zabitého, a káže se jemu navrátiti shromáždění k městu útočiště jeho, do něhož utekl; i bude bydliti v něm, dokudž neumře kněz nejvyšší, kterýž pomazán jest olejem svatým.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 26, 'Jestliže by pak ten, kterýž zabil člověka, vyšel z mezí města útočiště svého, do něhož utekl,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 27, 'A přítel zabitého našel by jej vně, an přešel meze města útočiště svého, a zabil by přítel zabitého vražedlníka toho, nebude vinen krví.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 28, 'Nebo v městě útočiště svého bydliti má, dokudž by neumřel kněz nejvyšší. Když by pak umřel kněz nejvyšší, navrátí se vražedlník do země vládařství svého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 29, 'A bude vám toto za ustanovení soudné v pronárodech vašich, ve všech příbytcích vašich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 30, 'Kdož by koli měl na smrt vydati někoho, podlé vyznání svědků sáhne na vražedlníka; ale jeden svědek nebude moci svědčiti proti někomu na smrt.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 31, 'Nevezmete pak výplaty za člověka vražedlníka, kterýž, jsa nešlechetný, jest smrti hoden, než smrtí ať umře.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 32, 'Aniž také vezmete výplaty od toho, kterýž utekl do města útočiště svého, aby se navrátil k bydlení do země své, prvé než by umřel kněz,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 33, 'Abyste nepoškvrnili země, v níž jste. Nebo krev taková poškvrnila by země, aniž také země očištěna býti může od krve, kteráž jest vylita na ní, jediné krví toho, kterýž vylil ji.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 34, 'Protož nepoškvrňujte země, v kteréž bydlíte, kdežto já přebývám; nebo já Hospodin přebývám u prostřed synů Izraelských.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 36, 1, 'Přistoupili pak starší z čeledi synů Galád, syna Machir, syna Manassesova, z čeledi synů Jozefových, a mluvili před Mojžíšem a před knížaty předními z synů Izraelských,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 36, 2, 'A řekli: Tobě pánu mému přikázal Hospodin, abys losem dal zemi v dědictví synům Izraelským; přikázáno jest také pánu mému od Hospodina, aby dal dědictví Salfada, bratra našeho, dcerám jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 36, 3, 'Kteréž jestliže někomu z pokolení synů Izraelských, kromě z pokolení svého, dány budou za manželky, odejde dědictví jejich od dědictví otců našich, a přidáno bude k dědictví pokolení toho, do kteréhož by se vdaly, a tak z losu dědictví našeho ubude.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 36, 4, 'A když budou míti synové Izraelští léto milostivé, připojeno bude dědictví jejich k dědictví pokolení toho, do kteréhož by se vdaly, a tak od dědictví pokolení otců našich odtrženo bude dědictví jejich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 36, 5, 'Tedy přikázal Mojžíš synům Izraelským podlé řeči Hospodinovy, řka: Dobře pokolení synů Jozefových mluví.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 36, 6, 'To jest, což přikázal Hospodin o dcerách Salfadových, řka: Za kohož se jim líbiti bude, nechť se vdadí, však v čeledi domu otce svého ať se vdávají,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 36, 7, 'Aby nebylo přenášíno dědictví synů Izraelských z pokolení na pokolení; nebo synové Izraelští jeden každý přídržeti se bude dědictví pokolení otců svých.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 36, 8, 'A každá dcera z pokolení synů Izraelských, kteráž by měla dědictví, za někoho z čeledi pokolení otce svého vdá se, aby vládli synové Izraelští jeden každý dědictvím otců svých,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 36, 9, 'Aby nebylo přenášíno vládařství z jednoho pokolení na druhé pokolení, ale jeden každý z pokolení synů Izraelských dědictví svého přídržeti se bude.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 36, 10, 'Jakož přikázal Hospodin Mojžíšovi, tak učinily dcery Salfadovy.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 36, 11, 'Nebo Mahla, Tersa a Hegla, Melcha a Noa, dcery Salfad, vdaly se za syny strýců svých.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 36, 12, 'Do čeledi synů Manasse, syna Jozefova, vdaly se, a zůstalo dědictví jejich při pokolení čeledi otce jejich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 36, 13, 'Tato jsou přikázaní a soudové, kteréž přikázal Hospodin skrze Mojžíše synům Izraelským, na rovinách Moábských, při Jordánu proti Jerichu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 1, 'Tato jsou slova, kteráž mluvil Mojžíš ke všemu lidu Izraelskému před Jordánem na poušti, na rovinách proti moři Rudému, mezi Fáran a Tofel a Lában a Hazerot a Dizahab.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 2, 'Jedenácte dní cesty jest od Oréb přes hory Seir až do Kádesbarne.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 3, 'Stalo se pak čtyřidcátého léta, jedenáctého měsíce, v první den téhož měsíce, že mluvil Mojžíš synům Izraelským všecky věci, kteréž jemu byl přikázal Hospodin oznámiti jim,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 4, 'Kdyžto již byl zabil Seona, krále Amorejského, kterýž bydlil v Ezebon, a Oga, krále Bázan, kterýž bydlil v Astarot, zabil v Edrei.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 5, 'Před Jordánem, v zemi Moábské, počal Mojžíš vysvětlovati zákona tohoto, řka:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 6, 'Hospodin Bůh náš mluvil k nám na Orébě, řka: Dosti jste již na hoře této bydlili.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 7, 'Obraťte se, táhněte a jděte k hoře Amorejských, na všecko vůkolí její, buď na roviny, na hory, na údolí, na poledne, i na břehy mořské, k zemi Kananejské a k Libánu, až k řece veliké, k řece Eufrates.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 8, 'Ej, ukázal jsem vám tu zemi; vejdětež do ní, a dědičně vládněte jí, kterouž s přísahou zaslíbil dáti Hospodin otcům vašim, Abrahamovi, Izákovi a Jákobovi, i semeni jejich po nich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 9, 'A mluvil jsem k vám toho času, řka: Nemohuť sám nésti vás.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 10, 'Hospodin Bůh váš rozmnožil vás, a hle, rozmnoženi jste dnes jako hvězdy nebeské.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 11, '(Hospodin Bůh otců vašich rozmnožiž vás nad to, jakž jste nyní, tisíckrát více, a požehnej vám, jakož jest mluvil vám.)');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 12, 'Kterak bych nesl sám práci vaši, břímě vaše a nesnáze vaše?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 13, 'Vydejte z sebe muže moudré a opatrné, a zkušené z pokolení svých, abych je vám představil.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 14, 'I odpověděli jste mi a řekli jste: Dobráť jest ta věc, kterouž jsi učiniti rozkázal.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 15, 'Vzav tedy přední z pokolení vašich, muže moudré a zkušené, ustanovil jsem je knížaty nad vámi, hejtmany nad tisíci, setníky, padesátníky, desátníky a správce v pokoleních vašich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 16, 'Přikázal jsem také soudcům vašim toho času, řka: Vyslýchejte pře mezi bratřími svými, a suďte spravedlivě mezi mužem a bratrem jeho, i mezi příchozím jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 17, 'Nebudete přijímati osoby v soudu; jakž malého tak i velikého slyšeti budete, nebudete se báti žádného, nebo Boží soud jest. Jestliže byste pak měli jakou věc nesnadnou, vznesete na mne, a vyslyším ji.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 18, 'Přikázal jsem vám, pravím, toho času všecko, co byste činiti měli.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 19, 'Potom pak hnuvše se z Oréb, přešli jsme všecku poušť tuto velikou a hroznou, kterouž jste viděli, jdouce cestou k hoře Amorejských, jakož nám byl přikázal Hospodin Bůh náš, a přišli jsme až do Kádesbarne.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 20, 'I řekl jsem vám: Přišli jste až k hoře Amorejské, kterouž Hospodin Bůh náš dává nám.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 21, 'Ej, dal Hospodin Bůh tvůj tu zemi tobě; vstupiž a vládni jí, jakož řekl Hospodin Bůh otců tvých tobě; neboj se, aniž se strachuj.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 22, 'Vy pak všickni přistoupili jste ke mně a řekli jste: Pošleme muže před sebou, kteříž by nám shlédli zemi, a oznámili by nám něco o cestě, kterouž bychom vstoupiti měli, i města, do nichž bychom přijíti měli.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 23, 'Kterážto řeč líbila se mně, a vzal jsem z vás dvanácte mužů, jednoho muže z každého pokolení.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 24, 'A oni obrátivše se a vstoupivše na horu, přišli až k údolí Eškol a shlédli zemi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 25, 'Nabrali také s sebou ovoce země té, a přinesli nám, a oznámili nám o těch věcech, řkouce: Dobráť jest země, kterouž Hospodin Bůh náš dává nám.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 26, 'A však jste nechtěli jíti, ale odpírali jste řeči Hospodina Boha svého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 27, 'A reptali jste v staních svých, řkouce: Proto že nás v nenávisti měl Hospodin, vyvedl nás z země Egyptské, aby nás vydal v ruce Amorejského, a zahladil nás.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 28, 'Kam bychom šli? Bratří naši zstrašili srdce naše, pravíce: Lid ten jest větší a vyšší nežli my, města veliká a hrazená až k nebi, ano i syny Enakovy tam jsme viděli.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 29, 'I řekl jsem vám: Nebojte se, ani se strachujte jich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 30, 'Hospodin Bůh váš, kterýž jde před vámi, onť bojovati bude za vás rovně tak, jakž učinil s vámi v Egyptě, před očima vašima.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 31, 'Ano i na poušti viděl jsi, kterak nesl tebe Hospodin Bůh tvůj, jako nosí člověk syna svého, a to po vší cestě, kterouž jste šli, až jste přišli na toto místo.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 32, 'A ani tak uvěřili jste Hospodinu Bohu svému,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 33, 'Kterýž k vyhledání vám místa, na kterémž byste se klásti měli, v noci předcházel vás cestou v ohni, aby vám ukázal cestu, kterouž byste měli jíti, a v oblace ve dne.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 34, 'Uslyšel pak Hospodin hlas řečí vašich, a rozhněval se, a přisáhl, řka:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 35, 'Jistě že nižádný z lidí těchto pokolení zlého neuzří země té dobré, kterouž jsem s přísahou zaslíbil dáti otcům vašim,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 36, 'Kromě Kálefa, syna Jefonova; tenť ji uzří, a jemu dám zemi, po níž chodil, i synům jeho, proto že cele následoval Hospodina.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 37, 'Ano i na mne rozhněval se Hospodin příčinou vaší, řka: Také ani ty nevejdeš tam.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 38, 'Jozue, syn Nun, kterýž stojí před tebou, onť vejde tam, jeho posilň, nebo on rozdělí ji losem Izraelovi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 39, 'A dítky vaše, o kterýchž jste pravili, že v loupež budou, a synové vaši, kteříž ještě neznají dobrého ani zlého, oni vejdou do ní, a jim dám ji; oni dědičně ji obdrží.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 40, 'Vy pak obrátíce se, jděte na poušť cestou k moři Rudému.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 41, 'A odpověděvše, řekli jste ke mně: Zhřešiliť jsme Hospodinu. My vstoupíme a budeme bojovati podlé toho všeho, jakž rozkázal nám Hospodin Bůh náš. A vzavše všickni odění svá válečná na sebe, hotovi jste byli vstoupiti na horu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 42, 'Hospodin pak řekl mi: Rci jim: Nevstupujte a nebojujte, neboť nejsem u prostřed vás, abyste nebyli poraženi před nepřátely svými.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 43, 'A když jsem vám to mluvil, neuposlechli jste, nýbrž odporni jste byli řeči Hospodinově, a všetečně vstoupili jste na horu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 44, 'Tedy vytáhl Amorejský, kterýž bydlil na té hoře, proti vám, a honili vás, jako činívají včely, a potřeli vás na hoře Seir až do Horma.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 45, 'A navrátivše se, plakali jste před Hospodinem, ale neuslyšel Hospodin hlasu vašeho, a uší svých nenaklonil k vám.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 46, 'I zůstali jste v Kádes za mnohé dny, podlé počtu dnů, v nichž jste tam byli.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 1, 'Potom obrátivše se, táhli jsme na tu poušť cestou k moři Rudému, jakož mluvil Hospodin ke mně, a obcházeli jsme horu Seir za dlouhý čas,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 2, 'Až mi řekl Hospodin takto:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 3, 'Dosti jste již obcházeli horu tuto, obraťtež se k straně půlnoční.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 4, 'A lidu přikaž, řka: Půjdete přes pomezí bratří svých synů Ezau, kteříž bydlí v Seir. Ačkoli budou se vás báti, hleďte však pilně,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 5, 'Abyste jich nedráždili; nebo nedám vám z země jejich ani šlepěje nožné, proto že v dědictví Ezau dal jsem horu Seir.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 6, 'Pokrmů koupíte od nich za peníze, a jísti budete, i vody také ku pití za peníze od nich jednati budete.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 7, 'Nebo Hospodin Bůh tvůj požehnal tobě při všeliké práci rukou tvých, a zná, že jdeš přes poušť velikou tuto; již čtyřidceti let Hospodin Bůh tvůj byl s tebou, aniž jsi měl v čem nedostatku.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 8, 'A šli jsme od bratří našich, synů Ezau, kteříž bydlí v Seir, s cesty polní od Elat a od Aziongaber, a uchýlili jsme se, abychom šli cestou po poušti Moábské.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 9, 'I řekl mi Hospodin: Neškoď Moábským, ani jich popouzej k boji, nebo nedám tobě v zemi jejich dědictví, poněvadž synům Lot dal jsem Ar v dědictví.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 10, '(Emim prvé bydlili v ní, lid veliký a mnohý, a vysokého zrostu, jako Enakim.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 11, 'Oni také za obry držáni byli jako Enakim, ale Moábští říkali jim Emim.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 12, 'V Seir pak bydlili prvé Horejští, kteréž synové Ezau vyhnali, a zahladili je před tváří svou, a bydlili tu místo nich, jako učinil Izrael v zemi vládařství svého, kterouž jim dal Hospodin.)');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 13, 'Nyní vstanouce, přejděte potok Záred. I přešli jsme potok Záred.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 14, 'Času pak, v němž jsme šli z Kádesbarne, až jsme přešli potok Záred, bylo let třidceti osm, dokavadž nebyl vyhlazen všecken věk mužů bojovných z prostřed stanů, jakož jim přisáhl Hospodin.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 15, 'Nebo ruka Hospodinova byla proti nim k setření jich z prostředku stanů, dokudž nevyhladil jich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 16, 'I stalo se, když všickni muži ti bojovní vyhynuli z prostředku lidu,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 17, 'Že mluvil Hospodin ke mně, řka:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 18, 'Ty přejdeš dnes pomezí Moábské k městu Ar,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 19, 'A přiblížíš se k synům Ammon. Nessužujž jich a nepopouzej jich k boji, nebo nedám tobě v zemi synů Ammon dědictví, poněvadž synům Lotovým dal jsem ji k vládařství.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 20, '(I ona také držána byla za zemi obrů; nebo obrové před tím bydlili v ní, kterýmž Ammonitští říkali Zamzomim,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 21, 'Lid veliký a mnohý, a vysokého zrostu, jako Enakim. Ale zahladil je Hospodin před tváří jejich, a vešli v dědictví jejich, a bydlili na místě jejich,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 22, 'Jakož učinil synům Ezau bydlícím v Seir, pro něž vyhladil Horejské před tváří jejich, i vešli v dědictví jejich, a bydlili na místě jejich až do dnešního dne.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 23, 'Hevejské také, kteříž bydlili v Azerim až do Gáza, Kaftorejští, kteříž vyšli z Kaftor, zahladili je, a bydlili na místě jejich.)');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 24, 'Vstanouce, beřte se a přejděte potok Arnon. Hle, dal jsem v ruce tvé Seona, krále Ezebon Amorejského, a zemi jeho; začniž jí vládnouti, a bojuj válečně proti němu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 25, 'Dnes počnu pouštěti strach a lekání se tebe na lidi, kteříž jsou pode vším nebem, tak že kteřížkoli uslyší pověst o tobě, třásti a lekati se budou tváři tvé.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 26, 'I poslal jsem posly z pouště Kedemot k Seonovi, králi Ezebon, s slovy pokojnými, řka:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 27, 'Nechť projdu skrze zemi tvou, přímo cestou půjdu, neuchýlím se ani na pravo ani na levo.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 28, 'Pokrmů za peníze prodáš mi, abych jedl, vody také za peníze dáš mi, a píti budu; toliko pěšky projdu,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 29, 'Jakož mi učinili synové Ezau, kteříž bydlí v Seir, a Moábští, kteříž bydlí v Ar, dokudž nepřejdu Jordánu, jda k zemi, kterouž Hospodin Bůh náš dává nám.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 30, 'Ale nechtěl dopustiti Seon, král Ezebon, abychom prošli zemi jeho; nebo byl zatvrdil Hospodin Bůh tvůj ducha jeho, a ztužil srdce jeho, aby dal jej v ruce tvé, jakož se vidí podnes.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 31, '(Nebo řekl mi byl Hospodin: Aj, již jsem počal v moc dávati tobě Seona i zemi jeho; začniž jí vládnouti, abys dědičně obdržel zemi jeho.)');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 32, 'A vytáhl byl Seon proti nám, on i všecken lid jeho k boji do Jasa.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 33, 'I dal jej nám Hospodin Bůh náš, a porazili jsme ho s syny jeho i se vším lidem jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 34, 'Vzali jsme také toho času všecka města jeho, a dali jsme v prokletí lid těch všech měst, i ženy i děti, žádného nepozůstavivše.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 35, 'Toliko hovada rozebrali jsme sobě, a kořisti z měst, kterýchž jsme dobyli.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 36, 'Od Aroer jenž jest na břehu potoka Arnon, a od města, kteréž jest v údolí, až do Galád nebylo města, kteréž by ostáti mohlo před námi; všecka nám dal Hospodin Bůh náš.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 37, 'Toliko k zemi synů Ammon nepřiblížils se, ani k žádné krajině ležící při potoku Jabok, ani k městům na horách, a k žádnému místu, kteréž zapověděl Hospodin Bůh náš.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 1, 'Potom obrátivše se, táhli jsme cestou k Bázan. I vytáhl Og, král Bázan, proti nám, on i všecken lid jeho k bitvě do Edrei.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 2, 'I řekl mi Hospodin: Neboj se ho, nebo v ruce tvé dal jsem jej, i všecken lid jeho i zemi jeho, a učiníš jemu tak, jako jsi učinil Seonovi, králi Amorejskému, kterýž bydlil v Ezebon.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 3, 'Dal tedy Hospodin Bůh náš v ruce naše i Oga, krále Bázan, a všecken lid jeho, i porazili jsme jej, tak že jsme nepozůstavili po něm žádného živého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 4, 'Dobyli jsme také téhož času všech měst jeho; nebylo města, kteréhož bychom jim neodjali, šedesáte měst, všecku krajinu Argob, království Oga v Bázan.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 5, 'Všecka ta města byla ohražená zdmi vysokými, branami a závorami, kromě měst otevřených, jichž bylo velmi mnoho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 6, 'A vyplénili jsme je, jako jsme učinili Seonovi, králi Ezebon, vyhladivše všecka města, muže, ženy i dítky.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 7, 'Všecka pak hovada a kořisti měst rozebrali jsme sobě.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 8, 'Vzali jsme také téhož času zemi z ruky dvou králů Amorejských, kteráž byla před Jordánem, od potoku Arnon až k hoře Hermon,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 9, '(Sidonští říkají Hermonu Sarion, a Amorejští říkají jemu Sanir,)');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 10, 'Všecka města v kraji, a všecken Galád, a všecken Bázan až do Sálecha a Edrei, kteráž byla města království Og v Bázan.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 11, 'Sám toliko Og, král v Bázan, z jiných obrů byl pozůstal. Aj, lůže jeho, lůže železné, ještě zůstává v Rabbat synů Ammon, devíti loktů zdýlí, a čtyř loket zšíří, jakž jest loket muže.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 12, 'Když tedy zemi tu obdrželi jsme dědičně toho času, krajinu od Aroer, jenž jest při potoku Arnon, a polovici hory Galád i města její, dal jsem pokolení Ruben a Gád.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 13, 'Ostatek pak Galád a všecku zemi Bázan, království Oga, dal jsem polovici pokolení Manassesova, totiž všecku krajinu Argob, všecku Bázan, kteráž sloula země obrů.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 14, 'Jair, syn Manasse, vzal všecku krajinu Argob, až ku pomezí Gessuri a Machati; pročež nazval zemi Bázan od jména svého Havot Jair až do dnešního dne.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 15, 'Machirovi pak dal jsem Galád.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 16, 'A Rubenovu a Gádovu pokolení dal jsem krajinu od Galád až ku potoku Arnon, polovici potoka s pomezím až ku potoku Jabok, kdež jsou hranice synů Ammonitských,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 17, 'A roviny tyto i Jordán s pomezím od Ceneret až k moři pustému, jenž jest moře slané, ležící pod horou Fazga k východu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 18, 'A přikázal jsem vám toho času, řka: Hospodin Bůh váš dal vám zemi tuto, abyste ji dědičně obdrželi; vezmouce odění na sebe, půjdete před bratřími vašimi, syny Izraelskými, kteřížkoli silní jste.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 19, 'Toliko ženy vaše a dítky vaše, a dobytek váš, (nebo vím, že mnoho dobytka máte,) zůstanou v městech vašich, kteráž jsem dal vám,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 20, 'Dokudž by nedal odpočinutí Hospodin bratřím vašim jako i vám, aby i oni dědičně obdrželi zemi, kterouž Hospodin Bůh váš dává jim za Jordánem; tedy navrátíte se jeden každý k dědictví svému, kteréž jsem dal vám.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 21, 'Také i Jozue přikázal jsem toho času, řka: Oči tvé vidí všecko, co učinil Hospodin Bůh váš těm dvěma králům; takť učiní Hospodin všechněm královstvím, do kterýchž ty půjdeš.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 22, 'Nebojtež se jich, nebo Hospodin Bůh váš, onť jest, kterýž bojuje za vás.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 23, 'A tehdáž prosil jsem Hospodina, řka:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 24, 'Panovníče Hospodine, ty jsi počal ukazovati služebníku svému velikost svou a ruku svou přesilnou; nebo kdo jest Bůh silný na nebi aneb na zemi, ješto by činiti mohl skutky podobné tvým, a moci podobné tobě?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 25, 'Prosím, nechť vejdu a uzřím zemi tu výbornou, kteráž jest za Jordánem, horu tu výbornou i Libán.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 26, 'Pohnul se pak Hospodin na mne pro vás a neuslyšel mne, ale řekl mi: Dosti máš, nemluv více o to se mnou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 27, 'Vstup na vrch hory Fazga, a pozdvihna očí svých k západu a k půlnoci, ku poledni i k východu, hleď očima svýma; nebo nepřejdeš Jordánu tohoto.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 28, 'Ale přikaž Jozue, a posilň ho, i potvrď ho; nebo půjde před lidem tímto, a on uvede jim v dědictví zemi, kterouž uzříš.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 29, 'I zůstali jsme v údolí naproti Betfegor.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 1, 'Nyní tedy, ó Izraeli, slyš ustanovení a soudy, kteréž já učím vás činiti, abyste živi byli, a vejdouce, dědičně vládli zemí, kterouž Hospodin Bůh otců vašich vám dává.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 2, 'Nepřidáte nic k slovu, kteréž já přikazuji vám, aniž co ujmete od něho, abyste tak přikázaní Hospodina Boha svého, kteréž já přikazuji vám, zachovali.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 3, 'Oči vaše viděly, co učinil Hospodin pro Belfegor, jak všecky lidi, kteříž odešli po Belfegor, vyhladil Hospodin Bůh tvůj z prostředku tvého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 4, 'Vy pak, přídržející se Hospodina Boha vašeho, živi jste do dnešního dne všickni.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 5, 'Viztež, učilť jsem vás ustanovením a soudům, jakž mi přikázal Hospodin Bůh můj, abyste tak činili v zemi, do kteréž vejdete k dědičnému držení jí.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 6, 'Ostříhejtež tedy a čiňte je, nebo to jest moudrost vaše a opatrnost vaše před očima národů, kteříž, slyšíce všecka ustanovení tato, řeknou: Jistě lid moudrý a rozumný národ veliký tento jest.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 7, 'Nebo který národ tak veliký jest, kterýž by měl bohy sobě tak blízké, jako jest Hospodin Bůh váš ve všem volání našem k němu?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 8, 'A který jest národ tak veliký, kterýž by měl ustanovení a soudy spravedlivé, jako jest všecken zákon tento, kterýž já vám dnes předkládám?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 9, 'A však hleď se a bedlivě ostříhej duše své, abys nezapomenul na ty věci, kteréž viděly oči tvé, a aby nevyšly z srdce tvého po všecky dny života tvého; a v známost je uvedeš synům i vnukům svým.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 10, 'A nezapomínej, že jsi onoho dne stál před Hospodinem Bohem svým na Orébě, když mi byl řekl Hospodin: Shromažď mi lid, ať jim předložím slova má, z nichž by se učili mne báti po všecky dny, dokudž živi budou na zemi, a témuž aby syny své učili.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 11, 'Tedy přistoupili jste, a stáli jste pod horou; (hora pak ta hořela ohněm až do samého nebe, a byly na ní tmy, oblak a mrákota.)');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 12, 'I mluvil k vám Hospodin z prostředku ohně. Hlas slov slyšeli jste, ale obrazu žádného jste neviděli kromě hlasu,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 13, 'Jímž vyhlásil vám smlouvu svou, kteréžto přikázal vám ostříhati, totiž desíti slov, a napsal je na dvou dskách kamenných.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 14, 'Mně také přikázal Hospodin toho času, abych učil vás ustanovením a soudům, abyste činili je v zemi, do kteréž jdete k dědičnému držení jí.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 15, 'Protož pilně pečujte o duše své, (nebo neviděli jste žádného obrazu toho dne, když k vám mluvil Hospodin na Orébě z prostředku ohně,)');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 16, 'Abyste neporušili cesty své, a neučinili sobě rytiny aneb podobenství nějakého obrazu, tvárnosti muže neb ženy,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 17, 'Podobenství nějakého hovada, kteréž jest na zemi, aneb podobenství jakéhokoli ptáka křídla majícího, kterýž létá v povětří,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 18, 'Podobenství jakéhokoli zeměplazu na zemi, aneb podobenství jakékoli ryby, kteráž jest u vodě pod zemí.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 19, 'Ani pozdvihuj očí svých k nebi, abys, vida slunce a měsíc, i hvězdy se vším zástupem nebeským a ponuknut jsa, klaněl bys se jim a sloužil bys jim, ješto ty věci oddal Hospodin Bůh tvůj všechněm lidem pode vším nebem,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 20, 'Vás pak vzal Hospodin, a vyvedl vás jako z peci železné z Egypta, abyste byli jeho lid dědičný, jako jste dne tohoto.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 21, 'Ale na mne rozhněval se Hospodin příčinou vaší, a přisáhl, že nepřejdu Jordánu, ani nevejdu do země té výborné, kterouž Hospodin Bůh tvůj dává tobě v dědictví.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 22, 'Nebo já umru v zemi této, a nepřejdu Jordánu, vy pak přejdete, a dědičně obdržíte zemi tu výbornou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 23, 'Hleďtež, abyste se nezapomínali na smlouvu Hospodina Boha svého, kterouž učinil s vámi, a nečinili sobě rytiny, aneb obrazu jakékoli věci, jakož přikázal tobě Hospodin Bůh tvůj.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 24, 'Nebo Hospodin Bůh tvůj jest oheň sžírající, Bůh silný, horlivý.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 25, 'Když zplodíš syny a vnuky, a zstaráte se v zemi té, jestliže porušíte cestu svou, a uděláte rytinu ku podobenství jakékoli věci, aneb učiníte něco zlého před očima Hospodina Boha svého, popouzejíce ho:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 26, 'Osvědčuji proti vám dnes před nebem i zemí, že hrozně a rychle vyhlazeni budete z země, do kteréž půjdete přes Jordán, abyste vládli jí. Nedlouho bydliti budete v ní, ale do konce vyhlazeni budete.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 27, 'A rozptýlí vás Hospodin mezi národy, a maličký počet vás zůstane mezi pohany, do kterýchž zavede vás Hospodin,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 28, 'A sloužiti tam budete bohům, dílu rukou lidských, dřevu a kameni, ješto nevidí ani slyší, ani jedí, ani čijí.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 29, 'Jestliže pak i tam hledati budeš Hospodina Boha svého, tedy nalezneš, budeš-li ho hledati z celého srdce svého a z celé duše své.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 30, 'Kdyžť úzko bude, a přijdou na tě všecky ty věci, naposledy však, jestliže bys se navrátil k Hospodinu Bohu svému, a poslouchal bys hlasu jeho,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 31, '(Poněvadž Hospodin Bůh tvůj jest Bůh silný, milosrdný,) neopustí tebe, ani tě nezkazí, ani zapomene se na smlouvu otců tvých, kterouž s přísahou utvrdil jim.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 32, 'Nebo ptej se nyní na dni staré, kteříž byli před tebou, od toho dne, v kterémž stvořil Bůh člověka na zemi, a od jednoho kraje nebe až do druhého, stala-li se kdy věc podobná této tak veliké, aneb slýcháno-li kdy co takového?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 33, 'Zdali kdy slyšel který lid hlas Boha mluvícího z prostředku ohně, jako jsi ty slyšel a živ zůstal?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 34, 'Aneb zdali se kdy který Bůh pokusil, aby přijda, vzal sobě národ některý z jiného národu s zkušováním, znameními a s zázraky, skrze boje a ruku silnou, v rameni vztaženém a v hrůzi veliké, jako učinil všecko toto pro vás Hospodin Bůh váš v Egyptě před očima vašima?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 35, 'Toběť jest to ukázáno, abys věděl, že Hospodin jest Bůh, a že není jiného kromě něho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 36, 'Dalť s nebe slyšeti hlas svůj, aby vyučil tebe, a na zemi ukázal tobě oheň svůj veliký, a slova jeho slyšel jsi z prostředku ohně.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 37, 'Proto že miloval otce tvé, vyvolil símě jejich po nich, a vyvedl tě před sebou mocí svou velikou z Egypta,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 38, 'Aby vyžena národy veliké a silnější, než jsi ty, před tváří tvou, uvedl tebe a dal tobě zemi jejich v dědictví, jakož dnes vidíš.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 39, 'Věziž tedy dnes a obnov to v srdci svém, že Hospodin jest Bůh na nebi svrchu i na zemi dole, a není žádného jiného.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 40, 'Protož ostříhej po všecky dny ustanovení a přikázaní jeho, kteráž já dnes přikazuji tobě, aby dobře bylo tobě i synům tvým po tobě, a abys prodlil dnů v zemi, kterouž Hospodin Bůh tvůj dá tobě.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 41, 'Tehdy oddělil Mojžíš tři města před Jordánem k východu slunce,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 42, 'Aby utekl do nich vražedlník, kterýž by zabil bližního svého nechtě, a neměl by ho před tím v nenávisti; když by utekl do jednoho z těch měst, aby živ zůstal:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 43, 'Bozor na poušti, na rovinách v kraji Rubenitských, a Rámot v Galád, v pokolení Gád, a Golan v Bázan, v pokolení Manasse.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 44, 'Ten jest zákon, kterýž předložil Mojžíš synům Izraelským,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 45, 'A tato jsou svědectví a ustanovení i soudové, kteréž předložil Mojžíš synům Izraelským, když vyšli z Egypta,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 46, 'Před Jordánem v údolí naproti Betfegor, v zemi Seona, krále Amorejského, kterýž bydlil v Ezebon, jejž porazil Mojžíš a synové Izraelští, když vyšli z Egypta,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 47, 'A uvázali se dědičně v zemi jeho, a v zemi Oga, krále Bázan, dvou králů Amorejských, v zemi, kteráž jest před Jordánem k východu slunce,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 48, 'Od Aroer, (jenž leží při břehu potoka Arnon,) až k hoře Sion, kteráž jest Hermon,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 49, 'I ve všecku rovinu před Jordánem k východu až k moři pustému, ležící pod horou Fazga.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 1, 'I svolal Mojžíš všecken lid Izraelský, a řekl jim: Slyš, Izraeli, ustanovení a soudy, kteréž já dnes mluvím v uši vaše; naučte se jim, a v skutku jich ostříhejte.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 2, 'Hospodin Bůh náš učinil s námi smlouvu na Orébě.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 3, 'Ne s otci našimi učinil Hospodin tu smlouvu, ale s námi, kteříž zde jsme nyní my všickni živí.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 4, 'Tváří v tvář mluvil Hospodin s vámi na té hoře z prostředku ohně,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 5, '(Já jsem pak stál mezi Hospodinem a mezi vámi toho času, abych oznámil vám řeč Hospodinovu; nebo jste se báli ohně, a nevstoupili jste na horu), řka:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 6, 'Já jsem Hospodin Bůh tvůj, kterýž jsem tě vyvedl z země Egyptské z domu služby.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 7, 'Nebudeš míti bohů jiných přede mnou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 8, 'Neučiníš sobě rytiny, ani jakého podobenství těch věcí, kteréž jsou na nebi svrchu, ani těch, kteréž na zemi dole, ani těch, kteréž jsou u vodách pod zemí.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 9, 'Nebudeš se jim klaněti, ani jich ctíti. Nebo já jsem Hospodin Bůh tvůj, Bůh silný, horlivý, navštěvující nepravost otců na synech do třetího i čtvrtého pokolení těch, kteříž nenávidí mne,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 10, 'A činící milosrdenství nad tisíci těch, kteříž mne milují, a ostříhají přikázaní mých.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 11, 'Nevezmeš jména Hospodina Boha svého nadarmo, neboť nenechá bez pomsty Hospodin toho, kdož by bral jméno jeho nadarmo.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 12, 'Ostříhej dne sobotního, abys jej světil, jakož přikázal tobě Hospodin Bůh tvůj.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 13, 'Šest dní pracovati budeš, a dělati všeliké dílo své;');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 14, 'Ale dne sedmého odpočinutí jest Hospodina Boha tvého. Nebudeš dělati žádného díla, ty i syn tvůj i dcera tvá, i služebník tvůj i děvka tvá, vůl i osel tvůj i všeliké hovado tvé, i příchozí tvůj, kterýž jest v branách tvých, aby odpočinul služebník tvůj a děvka tvá jako i ty.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 15, 'A pamatuj, že jsi byl služebníkem v zemi Egyptské, a vyvedl tě Hospodin Bůh tvůj odtud v ruce silné, a v rameni vztaženém. Protož přikázal tobě Hospodin Bůh tvůj, abys světil den sváteční.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 16, 'Cti otce svého i matku svou, jakož přikázal tobě Hospodin Bůh tvůj, aby se prodleli dnové tvoji, a aby tobě dobře bylo na zemi, kterouž Hospodin Bůh tvůj dá tobě.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 17, 'Nezabiješ.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 18, 'Nesesmilníš.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 19, 'Nepokradeš.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 20, 'Nepromluvíš proti bližnímu svému křivého svědectví.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 21, 'Nepožádáš manželky bližního svého, aniž požádáš domu bližního svého, pole jeho, neb služebníka jeho, aneb děvky jeho, vola jeho neb osla jeho, aneb čehokoli z těch věcí, kteréž jsou bližního tvého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 22, 'Ta slova mluvil Hospodin ke všemu shromáždění vašemu na hoře z prostředku ohně, oblaku a mrákoty, hlasem velikým, a nepřidal nic více, a napsal je na dvou dskách kamenných, kteréž mně dal.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 23, 'Vy pak když jste uslyšeli hlas z prostředku tmy, (nebo hora ohněm hořela,) přistoupili jste ke mně všickni vůdcové pokolení vašich a starší vaši,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 24, 'A řekli jste: Ej, ukázal nám Hospodin Bůh náš slávu svou a velikost svou, a slyšeli jsme hlas jeho z prostředku ohně; dnešního dne viděli jsme, že Bůh mluvil s člověkem, a on živ zůstal.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 25, 'Protož nyní proč máme zemříti? Nebo sežral by nás oheň veliký tento; jestli více slyšeti budeme hlas Hospodina Boha našeho, zemřeme.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 26, 'Nebo co jest všeliké tělo, aby slyše hlas Boha živého mluvícího z prostředku ohně, jako my, mělo živo býti?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 27, 'Přistup ty a slyš všecky věci, kteréž mluviti bude Hospodin Bůh náš; potom ty mluviti budeš nám, což by koli řekl tobě Hospodin Bůh náš, a my slyšeti i činiti budeme.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 28, 'Uslyšev pak Hospodin hlas řečí vašich, když jste mluvili ke mně, řekl mi Hospodin: Slyšel jsem hlas řeči lidu tohoto, kterouž mluvili tobě. Cožkoli mluvili, dobřeť jsou mluvili.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 29, 'Ó kdyby bylo jejich srdce takové, aby se báli mne a ostříhali přikázaní mých po všeliký čas, aby jim dobře bylo i synům jejich na věky!');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 30, 'Jdi, rci jim: Navraťte se k stanům vašim.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 31, 'Ty pak stůj tuto při mně, a oznámím tobě všecka přikázaní, ustanovení i soudy, kterýmž je učiti budeš, aby je činili v zemi, kterouž já dávám jim, aby jí dědičně vládli.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 32, 'Hleďtež tedy, abyste činili, jakž přikázal vám Hospodin Bůh váš; neuchylujte se na pravo ani na levo.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 33, 'Po vší té cestě, kterouž vám přikázal Hospodin Bůh váš, choditi budete, abyste živi byli, a dobře bylo vám, a abyste prodlili dnů na zemi, kterouž dědičně obdržíte.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 1, 'Toto pak jest přikázaní, ustanovení a soudové, kteréž přikázal Hospodin Bůh váš, abych učil vás, abyste činili je v zemi, do kteréž jdete k dědičnému držení jí,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 2, 'Abys se bál Hospodina Boha svého, ostříhaje všech ustanovení jeho a přikázaní jeho, kteráž já přikazuji tobě, ty i syn tvůj i vnuk tvůj, po všecky dny života svého, aby se prodlili dnové tvoji.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 3, 'Slyšiž tedy, Izraeli, a hleď tak skutečně činiti, aby tobě dobře bylo, a abyste se velmi rozmnožili, (jakož mluvil Hospodin Bůh otců tvých tobě,) v zemi oplývající mlékem a strdí.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 4, 'Slyš, Izraeli, Hospodin Bůh náš, Hospodin jeden jest.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 5, 'Protož milovati budeš Hospodina Boha svého z celého srdce svého, a ze vší duše své, a ze vší síly své.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 6, 'A budou slova tato, kteráž já přikazuji tobě dnes, v srdci tvém.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 7, 'A budeš je často opětovati synům svým, a mluviti o nich, když sedneš v domě svém, když půjdeš cestou, a léhaje i vstávaje.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 8, 'Uvážeš je za znamení na ruce své, a jako náčelník mezi očima svýma.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 9, 'Napíšeš je také na veřejích domu svého a na branách svých.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 10, 'A když tě uvede Hospodin Bůh tvůj do země, kterouž s přísahou zaslíbil otcům tvým, Abrahamovi, Izákovi a Jákobovi, že ji tobě dá, i města veliká a výborná, kterýchžs nestavěl,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 11, 'A domy plné všech dobrých věcí, kterýchž jsi nenaplnil, a studnice vykopané, kterýchž jsi nekopal, a vinice i olivoví, jichž jsi neštípil, a jedl bys a nasytil se:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 12, 'Varuj se, abys nezapomenul na Hospodina, kterýž tě vyvedl z země Egyptské, z poroby těžké.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 13, 'Hospodina Boha svého báti se budeš, a jemu sloužiti, a ve jméno jeho přisahati.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 14, 'Neodejdeš po bozích cizích, z bohů jiných národů, kteříž vůkol vás jsou,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 15, '(Nebo Bůh silný, horlivý, Hospodin tvůj u prostřed tebe jest,) aby se neroznítila prchlivost Hospodina Boha tvého na tebe, a shladil by tě se svrchku země.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 16, 'Nebudete pokoušeti Hospodina Boha svého, jako jste pokoušeli v Massah.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 17, 'Pilně ostříhejte přikázaní Hospodina Boha svého, a svědectví jeho, i ustanovení jeho, kteráž přikázal tobě,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 18, 'A čiň to, což pravého a dobrého jest před očima Hospodinovýma, aby tobě dobře bylo, a vejda, abys dědičně obdržel zemi výbornou, kterouž s přísahou zaslíbil Hospodin otcům tvým,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 19, 'Aby vypudil všecky nepřátely tvé od tváři tvé, jakož mluvil Hospodin.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 20, 'Když by se potom syn tvůj otázal tebe, řka: Co jsou to za svědectví a ustanovení i soudy, kteréž přikázal Hospodin Bůh náš vám?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 21, 'Tedy díš synu svému: Služebníci jsme byli Faraonovi v Egyptě, i vyvedl nás Hospodin z Egypta v ruce silné.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 22, 'A činil Hospodin znamení a zázraky veliké a škodlivé v Egyptě proti Faraonovi, a proti všemu domu jeho před očima našima,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 23, 'Nás pak vyvedl odtud, aby uvedl nás, a dal nám zemi, kterouž s přísahou zaslíbil otcům našim.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 24, 'Protož přikázal nám Hospodin, abychom ostříhali všech ustanovení těchto, bojíce se Hospodina Boha svého, aby nám dobře bylo po všecky dny, a aby zachoval nás při životu, jakž to činí i v dnešní den.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 25, 'A spravedlnost míti budeme, když ostříhati budeme a činiti všecka přikázaní tato před Hospodinem Bohem svým, jakož přikázal nám.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 1, 'Když pak tebe uvede Hospodin Bůh tvůj do země, do kteréž ty již vcházíš, abys vládl jí, a vypléní národy mnohé od tváři tvé, Hetea, Gergezea, Amorea, Kananea, Ferezea, Hevea a Jebuzea, sedm národů větších a silnějších, nežli jsi ty,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 2, 'A dá je Hospodin Bůh tvůj tobě, abys je pobil: jako proklaté vypléníš je, nevejdeš s nimi v smlouvu, aniž slituješ se nad nimi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 3, 'Nikoli nespřízníš se s nimi; dcery své nedáš synu jejich, a dcery jejich nevezmeš synu svému.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 4, 'Neboť by odvedla syna tvého od následování mne, a sloužili by bohům cizím, pročež popudila by se prchlivost Hospodinova na vás, a zahladila by tě rychle.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 5, 'Ale raději toto jim učiňte: Oltáře jejich zbořte, modly jejich stroskotejte, háje také posekejte, a rytiny jejich ohněm spalte.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 6, 'Nebo ty lid svatý jsi Hospodinu Bohu svému; tebe vyvolil Hospodin Bůh tvůj, abys jemu byl lidem zvláštním, mimo všecky národy, kteříž jsou na zemi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 7, 'Ne proto, že by vás více bylo nad jiné národy, připojil se k vám Hospodin, a vyvolil vás, (nebo menší vás počet byl nežli jiných národů,)');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 8, 'Ale proto, že miloval vás Hospodin, a splniti chtěl přísahu, kterouž přisáhl otcům vašim, vyvedl vás v ruce silné, a vysvobodil vás z domu služby, z ruky Faraona, krále Egyptského.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 9, 'I zvíš, že Hospodin Bůh tvůj jest Bůh, Bůh silný a pravdomluvný, ostříhající smlouvy a milosrdenství těm, kteříž ho milují a ostříhají přikázaní jeho, až do tisícího kolena,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 10, 'Odplacující tomu, kterýž ho nenávidí, v tvář jeho, tak aby zahladil jej. Nebudeť prodlévati; kdož ho nenávidí, v tvář jeho odplatí jemu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 11, 'Protož ostříhej přikázaní a ustanovení i soudů, kteréž já tobě dnes přikazuji, abys je činil.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 12, 'I budeť to, že když poslouchati budete soudů těchto a ostříhati i činiti je, také Hospodin Bůh tvůj ostříhati bude tobě smlouvy a milosrdenství, kteréž s přísahou zaslíbil otcům tvým.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 13, 'A bude tě milovati, i požehná tobě a rozmnoží tebe. Nebo požehná plodu života tvého a úrodám země tvé, obilí tvému, vínu tvému a oleji tvému, plodu skotů tvých i stádům bravů tvých v zemi, kterouž s přísahou zaslíbil otcům tvým, že ji tobě dá.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 14, 'Požehnaný budeš nad všecky národy; nebude u tebe neplodný aneb neplodná, ani mezi hovady tvými.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 15, 'Vzdálí také od tebe Hospodin všeliký neduh, a všecky zlé nemoci Egyptské, kteréž znáš; nevzloží jich na tebe, ale vzloží je na všecky, kteříž tě nenávidí.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 16, 'A shladíš všecky národy, kteréž Hospodin Bůh tvůj dá tobě. Neslituje se nad nimi oko tvé, aniž sloužiti budeš bohům jejich, nebo to bylo by tobě osídlem.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 17, 'Řekl-li bys v srdci svém: Větší jsou národové tito nežli já, kterak budu moci vyhnati je?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 18, 'Neboj se jich, ale pilně pamatuj na to, co učinil Hospodin Bůh tvůj Faraonovi a všechněm Egyptským,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 19, 'Na pokušení veliká, kteráž viděly oči tvé, i znamení a zázraky, a ruku silnou a rámě vztažené, v kterémž vyvedl tě Hospodin Bůh tvůj. Takť učiní Hospodin Bůh tvůj všechněm národům, kterýchž bys se obával.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 20, 'Nadto sršně pošle Hospodin Bůh tvůj na ně, dokudž by nezhynuli, kteříž by pozůstali, a kteříž by se skryli před tebou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 21, 'Nelekejž se strachu jejich, nebo Hospodin Bůh tvůj jest u prostřed tebe, Bůh silný, veliký a hrozný.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 22, 'I vypléní Hospodin Bůh tvůj národy ty od tváři tvé pomalu; nebudeš moci pojednou jich shladiti, aby se nerozmnožila proti tobě zvěř polní.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 23, 'A však dá je Hospodin Bůh tvůj tobě, a setře je setřením velikým, dokudž nebudou vyhlazeni.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 24, 'Vydá i krále jejich v ruce tvé, a vyhladíš jméno jejich pod nebem; neostojíť žádný před tebou, až je i vyhladíš.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 25, 'Ryté bohy jejich ohněm popálíš; nepožádáš stříbra a zlata, kteréž jest na nich, aniž ho sobě vezmeš, aby nebylo tobě osídlem, nebo ohavnost jest Hospodinu Bohu tvému.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 26, 'Aniž vneseš ohavnosti do domu svého, abys nebyl proklatý, jako i ona; všelijak v ohyzdnosti a v ohavnosti budeš míti ji, nebo proklatá jest.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 1, 'Všelikého přikázaní, kteréž já přikazuji tobě dnes, skutečně ostříhejte, abyste živi byli a rozmnožili se, a vešli k dědičnému obdržení země, kterouž s přísahou zaslíbil Hospodin otcům vašim.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 2, 'A rozpomínati se budeš na všecku cestu, kterouž tě vedl Hospodin Bůh tvůj již teď čtyřidceti let po poušti, aby ponížil tebe a zkusil tě, aby známé bylo, co jest v srdci tvém, budeš-li ostříhati přikázaní jeho, čili nic.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 3, 'I ponížil tě a dopustil na tebe hlad, potom tě krmil mannou, kteréž jsi ty neznal, ani otcové tvoji, aby známé učinil tobě, že ne samým chlebem živ bude člověk, ale vším tím, což vychází z úst Hospodinových, živ bude člověk.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 4, 'Roucho tvé nevetšelo na tobě, a noha tvá se neodhnetla, již od čtyřidceti let.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 5, 'Znejž tedy v srdci svém, že jakož cvičí člověk syna svého, tak Hospodin Bůh tvůj cvičí tebe.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 6, 'A ostříhej přikázaní Hospodina Boha svého, chodě po cestách jeho, a boje se jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 7, 'Nebo Hospodin Bůh tvůj uvozuje tě do země výborné, země, v níž jsou potokové vod, studnice a propasti prýštící se po údolích i po horách,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 8, 'Do země hojné na pšenici a ječmen, na vinice a fíky a jablka zrnatá, do země, v níž jest hojnost olivoví olej přinášejícího a medu,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 9, 'Země, v níž bez nedostatku chléb jísti budeš, a v ničemž nouze trpěti nebudeš, země, jejíž kamení jest železo, a z hor jejích měď sekati budeš.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 10, 'Kdyžkoli jísti budeš a nasytíš se, dobrořečiti budeš Hospodina Boha svého za zemi výbornou, kterouž dal tobě.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 11, 'Aniž se kdy toho dopouštěj, abys se měl zapomenouti na Hospodina Boha svého, a neostříhati přikázaní a soudů jeho i ustanovení jeho, kteráž já dnes přikazuji tobě,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 12, 'Aby, když bys jedl a nasycen byl, a domů krásných nastavěje, v nich bys bydlil,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 13, 'A volové i ovce tvé rozmnoženy byly by, stříbra také a zlata měl bys mnoho, a hojnost ve všech věcech svých,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 14, 'Nepozdvihlo se srdce tvé, a zapomenul bys na Hospodina Boha svého, kterýž tě vyvedl z země Egyptské, z domu služby,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 15, 'A vedl tě přes poušť velikou a hroznou, na níž byli hadové ohniví a štírové, poušť žíznivou, na níž nebylo žádné vody, a vyvedl tobě vodu z přetvrdé skály,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 16, 'Kterýž tě krmil na poušti mannou, o kteréž nevěděli otcové tvoji, aby tě potrápil a zkusil tebe, naposledy však aby dobře učinil tobě.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 17, 'Aniž říkej v srdci svém: Moc má a síla ruky mé způsobila mi tato zboží,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 18, 'Ale pamatuj na Hospodina Boha svého, nebo on dává tobě moc k dobývání zboží, aby utvrdil smlouvu svou, kterouž s přísahou učinil s otci tvými, jakož to ukazuje dnešní den.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 19, 'Pakli zapomena se na Hospodina Boha svého, postoupil bys po bozích cizích, a sloužil bys jim a klaněl bys se jim: osvědčuji proti vám dnes, že konečně zahynete.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 20, 'Jako pohané, kteréž Hospodin zahladil před tváří vaší, tak zahynete, proto že jste neposlouchali hlasu Hospodina Boha svého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 1, 'Slyš, Izraeli, ty přejdeš dnes přes Jordán, abys vejda, dědičně vládl národy většími a silnějšími, než jsi ty, městy velikými a ohrazenými až k nebi,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 2, 'Lidem velikým a vysokým, syny Enakovými, o kterýchž víš, a o kterýchž jsi slyšel praviti: Kdo se postaví proti synům Enakovým?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 3, 'Protož věziž dnes, že Hospodin Bůh tvůj, kterýž jde před tebou, jest jako oheň spalující. On vyhladí je, a on sníží je před tebou; i vyženeš je a vyhladíš je rychle, jakož mluvil tobě Hospodin.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 4, 'Neříkejž v srdci svém, když by je zapudil Hospodin Bůh tvůj od tváři tvé, řka: Pro spravedlnost mou uvedl mne Hospodin, abych dědičně obdržel zemi tuto, tak jako pro bezbožnost národů těch Hospodin vyhnal je od tváři tvé.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 5, 'Ne pro spravedlnost svou a pravost srdce svého ty jdeš, abys dědičně obdržel zemi jejich, ale pro bezbožnost národů těch Hospodin Bůh tvůj vyhání je od tváři tvé, a aby splnil slovo, kteréž s přísahou zaslíbil otcům tvým, Abrahamovi, Izákovi a Jákobovi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 6, 'Protož věziž, že ne pro spravedlnost tvou Hospodin Bůh tvůj dává tobě zemi tu výbornou, abys dědičně držel ji, poněvadž jsi lid tvrdé šíje.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 7, 'Pamatujž a nezapomínej, že jsi k hněvu popouzel Hospodina Boha svého na poušti; hned od toho dne, když jsi vyšel z země Egyptské, až jste přišli na místo toto, odporni jste byli Hospodinu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 8, 'Také i na Orébě popudili jste k hněvu Hospodina, a rozhněval se na vás Hospodin, aby vás shladil.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 9, 'Když jsem vstoupil na horu, abych vzal dsky kamenné, dsky smlouvy, kterouž učinil s vámi Hospodin, tehdáž jsem trval na hoře čtyřidceti dní a čtyřidceti nocí, chleba nejeda a vody nepije.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 10, 'I dal mi Hospodin dvě dsky kamenné, psané prstem Božím, na nichž byla všecka ta slova, kteráž mluvil vám Hospodin na hoře z prostředku ohně v den shromáždění.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 11, 'Po skonání pak čtyřidceti dnů a čtyřidceti nocí dal mi Hospodin dvě dsky kamenné, dsky smlouvy.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 12, 'I řekl mi Hospodin: Vstana, sstup rychle odsud, nebo poškvrnil se lid tvůj, kterýž jsi vyvedl z Egypta; sešli brzy s cesty, kterouž jsem jim přikázal, a učinili sobě slitinu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 13, 'Mluvil také Hospodin ke mně, řka: Viděl jsem lid ten, a jistě lid tvrdošijný jest.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 14, 'Pusť mne, ať je setru, a zahladím jméno jejich pod nebem, tebe pak učiním v národ větší a silnější, nežli jest tento.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 15, 'Tedy obrátiv se, sstoupil jsem s hory, (hora pak hořela ohněm), dvě dsky smlouvy maje v obou rukou svých.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 16, 'Když jsem pak pohleděl a uzřel jsem, že jste zhřešili Hospodinu Bohu vašemu, udělavše sobě tele lité, (brzy jste byli sešli s cesty, kterouž přikázal vám Hospodin):');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 17, 'Pochytiv ty dvě dsky, povrhl jsem je z obou rukou svých, a polámal jsem je před očima vašima.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 18, 'A padna, ležel jsem před Hospodinem jako i prvé, čtyřidceti dní a čtyřidceti nocí, chleba nejeda a vody nepije, pro všecky hříchy vaše, kterýmiž jste byli zhřešili, činíce to, což zlého jest před očima Hospodinovýma, a popouzejíce jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 19, 'Nebo bál jsem se prchlivosti a hněvu, kterýmž se byl popudil Hospodin proti vám, aby zahladil vás, a uslyšel mne Hospodin i tehdáž.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 20, 'Na Arona též rozhněval se byl Hospodin náramně, tak že ho zahladiti chtěl; tedy modlil jsem se také za Arona téhož času.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 21, 'Hřích pak váš, kterýž jste byli učinili, totiž tele, vzav, spálil jsem je ohněm a zdrobil jsem je, tluka je dobře, dokudž nebylo setříno na prach. Potom vsypal jsem prach jeho do potoka, kterýž tekl s té hory.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 22, 'Ano i v Tabbera a v Massah a v Kibrot Hattáve popouzeli jste Hospodina k hněvu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 23, 'A když vás poslal Hospodin z Kádesbarne, řka: Vstupte a opanujte zemi tu, kterouž jsem vám dal, odporni jste byli řeči Hospodina Boha svého, a nevěřili jste jemu, aniž jste uposlechli hlasu jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 24, 'Odporni jste byli Hospodinu od toho dne, jakž jsem vás poznal.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 25, 'A padna, ležel jsem před Hospodinem čtyřidceti dní a čtyřidceti nocí, v nichž jsem rozprostíral se; nebo řekl Hospodin, že vás chce zahladiti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 26, 'I modlil jsem se Hospodinu, řka: Panovníče Hospodine, nezatracujž lidu svého, a to dědictví svého, kteréž jsi vykoupil velikomocností svou, kteréž jsi vyvedl z Egypta v ruce silné.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 27, 'Rozpomeniž se na služebníky své, Abrahama, Izáka a Jákoba; nepatřiž na tvrdost lidu tohoto, na bezbožnost jeho a na hříchy jeho,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 28, 'Aby neřekli obyvatelé země té, z níž jsi nás vyvedl: Proto že nemohl Hospodin uvésti jich do země, kterouž zaslíbil jim, aneb že je měl v nenávisti, vyvedl je, aby je pobil na poušti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 29, 'Však oni jsou lid tvůj a dědictví tvé, kteréž jsi vyvedl v síle své veliké a v rameni svém vztaženém.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 1, 'Toho času řekl mi Hospodin: Vyhlaď sobě dvě dsky kamenné, podobné prvním, a vstup ke mně na horu, a udělej sobě truhlu dřevěnou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 2, 'I napíši na dskách těch slova, kteráž byla na dskách prvních, kteréž jsi rozrazil, a vložíš je do té truhly.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 3, 'Tedy udělal jsem truhlu z dříví setim, a vyhladiv dvě dsky kamenné, podobné prvním, vstoupil jsem na horu, nesa ty dvě dsky v rukou svých.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 4, 'I napsal na těch dskách, tak jakž prvé byl napsal, deset slov, kteráž mluvil k vám Hospodin na hoře z prostředku ohně v den shromáždění onoho, a dal je Hospodin mně.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 5, 'A obrátiv se, sstoupil jsem s hory té, a vložil jsem ty dsky do truhly, kterouž jsem byl udělal, a byly tam, jakož mi přikázal Hospodin.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 6, 'Synové pak Izraelští hnuli se z Beerot synů Jakan do Moserah. Tam umřel Aron, a tu jest pochován; i konal úřad kněžský na místě jeho Eleazar, syn jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 7, 'Odtud táhli do Gadgad, a z Gadgad do Jotbata, do země vod tekutých.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 8, 'Toho času oddělil Hospodin pokolení Léví, aby nosili truhlu smlouvy Hospodinovy, a aby stáli před Hospodinem k službě jemu, a k dobrořečení ve jménu jeho až do dnešního dne.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 9, 'Pročež nemělo pokolení Léví dílu a dědictví s bratřími svými, nebo Hospodin jest dědictví jeho, jakož mluvil k němu Hospodin Bůh tvůj.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 10, 'Já pak zůstal jsem na té hoře jako dnů prvních, čtyřidceti dní a čtyřidceti nocí, a uslyšel mne Hospodin i tehdáž, a nechtěl shladiti tebe.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 11, 'Potom řekl mi Hospodin: Vstaň, jdi, předcházeje lid, aby vešli a vládli zemí, kterouž jsem s přísahou zaslíbil otcům jejich, že jim ji dám.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 12, 'Nyní tedy, Izraeli, čeho žádá Hospodin Bůh tvůj od tebe? Jediné abys se bál Hospodina Boha svého, a chodil po všech cestách jeho, a abys miloval ho, a sloužil Hospodinu Bohu svému v celém srdci svém, a ve vší duši své,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 13, 'Ostříhaje přikázaní Hospodinových a ustanovení jeho, kteráž já přikazuji tobě dnes k tvému dobrému.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 14, 'Aj, Hospodina Boha tvého jest nebe i nebesa nebes, země a všecky věci, kteréž jsou na ní.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 15, 'Však toliko v otcích tvých zalíbilo se Hospodinu, aby je zamiloval, a vyvolil símě jejich po nich, vás totiž ze všech národů, jakož dnes vidíš.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 16, 'Protož obřežtež neobřízku srdce svého, a šíje své nezatvrzujte více.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 17, 'Nebo Hospodin Bůh váš, on jest Bůh bohů, a Pán pánů, Bůh silný, veliký, mocný a hrozný, kterýž nepřijímá osoby, ani béře darů.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 18, 'Čině soud sirotku a vdově, miluje také příchozího, dávaje mu chléb a oděv.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 19, 'Protož milujte hostě, nebo jste byli hosté v zemi Egyptské.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 20, 'Hospodina Boha svého báti se budeš, jemu sloužiti, a jeho se přídržeti, a ve jménu jeho přisahati budeš.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 21, 'Onť jest chvála tvá, a onť jest Bůh tvůj, kterýž učinil s tebou tyto veliké a hrozné věci, kteréž viděly oči tvé.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 22, 'V sedmdesáti dušech sstoupili otcové tvoji do Egypta, nyní pak rozmnožil tě Hospodin Bůh tvůj, abys byl v množství jako hvězdy nebeské.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 1, 'Milujž tedy Hospodina Boha svého a ostříhej nařízení jeho, ustanovení a soudů jeho, i přikázaní jeho po všecky dny.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 2, 'A znejtež dnes (nebo ne k samým synům vašim mluvím, kteříž neznali toho, ani neviděli,) trestání Hospodina Boha svého, důstojnost jeho, ruku jeho silnou a rámě jeho vztažené,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 3, 'A znamení i skutky jeho, kteréž činil u prostřed Egypta Faraonovi, králi Egyptskému, i vší zemi jeho,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 4, 'A co učinil vojsku Egyptskému, koňům i vozům jeho, kterýž uvedl vody moře Rudého na ně, když vás honili, a shladil je Hospodin až do dnešního dne;');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 5, 'Také co učinil vám na poušti, dokudž jste nepřišli až k místu tomuto,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 6, 'A co učinil Dátanovi a Abironovi, synům Eliaba, syna Rubenova, když země otevřela ústa svá, a požřela je i čeledi jejich, stany jejich se vším statkem jejich, kterýž při sobě měli, u prostřed všeho Izraele.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 7, 'Ale oči vaše viděly všecky skutky Hospodinovy veliké, kteréž činil.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 8, 'Protož ostříhejte všech přikázaní, kteráž já dnes přikazuji vám, abyste zmocněni byli, a vejdouce, dědičně obdrželi zemi, do kteréž vy jdete k dědičnému jí obdržení,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 9, 'A aby se prodlili dnové vaši na zemi, kterouž s přísahou zaslíbil dáti Hospodin otcům vašim i semeni jejich, zemi mlékem a strdí oplývající.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 10, 'Nebo země, do kteréž ty již vcházíš, abys ji dědičně obdržel, není jako země Egyptská, z níž jsi vyšel, v kteréž jsi rozsíval símě své, a svlažoval ji do ustání noh svých jako zahradu bylinnou:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 11, 'Ale země, do kteréž vy jdete, abyste jí dědičně vládli, jest země hornatá, mající i údolí, kteráž z deště nebeského svlažována bývá vodou,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 12, 'Země, o kterouž Hospodin Bůh tvůj pečuje, a vždycky oči Hospodina Boha tvého obráceny jsou na ni, od počátku roku až do konce jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 13, 'Protož jestliže opravdově poslouchati budete přikázaní mých, kteráž já vám dnes přikazuji, milujíce Hospodina Boha svého a sloužíce jemu z celého srdce svého a ze vší duše své,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 14, 'Dám déšť zemi vaší časem svým, ranní i pozdní, a sklízeti budeš obilé své, víno své i olej svůj.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 15, 'Dám i pastvu na poli tvém pro hovada tvá, a budeš jísti až do sytosti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 16, 'Vystříhejtež se tedy, aby nebylo svedeno srdce vaše, abyste odstupujíce, nesloužili bohům cizím, a neklaněli se jim.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 17, 'Pročež Hospodin velice by se na vás rozhněval, a zavřel by nebe, aby deště nedávalo, a země aby nedávala úrody své; i zahynuli byste rychle z země výborné, kterouž Hospodin vám dává.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 18, 'Ale složte tato slova má v srdci svém a v mysli své, a uvažte je sobě za znamení na rukou svých, a budou jako náčelník mezi očima vašima.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 19, 'A vyučujte jim syny své, rozmlouvajíce o nich, když sedneš v domě svém, aneb když půjdeš cestou, když lehneš i když vstaneš.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 20, 'Napíšeš je také na veřejích domu svého i na branách svých,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 21, 'Aby byli rozmnoženi dnové vaši a dnové synů vašich na zemi, kterouž s přísahou zaslíbil Hospodin otcům vašim, že ji dá jim, dokudž nebe trvá nad zemí.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 22, 'Nebo jestliže bedlivě ostříhati budete všech přikázaní těchto, kteráž já přikazuji vám, abyste je činili, milujíce Hospodina Boha svého, a chodíce po všech cestách jeho, a přídržejíce se jeho:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 23, 'Tedy vyžene Hospodin všecky ty národy od tváři vaší, a vládnouti budete dědičně národy většími i silnějšími, nežli jste vy.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 24, 'Všeliké místo, na kteréž by vstoupila noha vaše, vaše bude; od pouště a od Libánu, a od řeky Eufraten až k moři nejdalšímu bude pomezí vaše.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 25, 'Nepostaví se žádný proti vám; strach a bázeň vás pustí Hospodin Bůh váš na tvář vší země, po kteréž choditi budete, jakož jest mluvil vám.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 26, 'Hle, já předkládám vám dnes požehnání i zlořečení,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 27, 'Požehnání, budete-li poslouchati přikázaní Hospodina Boha svého, kteráž já dnes přikazuji vám,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 28, 'Zlořečení pak, jestliže byste neposlouchali přikázaní Hospodina Boha svého, ale sešli byste s cesty, o kteréž já dnes přikazuji vám, následujíce bohů cizích, kterýchž neznáte.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 29, 'A když by tě uvedl Hospodin Bůh tvůj do země, do kteréž ty jdeš, abys dědičně vládl jí, tedy dáš požehnání toto na hoře Garizim, a zlořečení na hoře Hébal,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 30, 'Kteréž jsou za Jordánem, za cestou chýlící se k západu slunce, v zemi Kananejského, jenž bydlí na rovinách naproti Galgala, blízko rovin More.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 31, 'Nebo vy půjdete přes Jordán, abyste vešli a dědičně vládli zemí, kterouž Hospodin Bůh váš dá vám; i obdržíte ji dědičně, a budete v ní bydliti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 32, 'Hleďtež tedy, abyste činili všecka ustanovení a soudy, kteréž já dnes vám předkládám.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 1, 'Tato jsou ustanovení a soudové, kterýchž ostříhati budete, činíce je v zemi, kterouž Hospodin Bůh otců tvých dá tobě, abys dědičně vládl jí po všecky dny, v nichž živi budete na zemi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 2, 'Zkazíte do gruntu všecka místa, na nichž sloužili národové, (kteréž vy dědičně opanujete,) bohům svým, na vrších vysokých a na pahrbcích, a pod každým stromem ratolestným.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 3, 'Oltáře jejich zbořte, a obrazy jejich ztlucte, háje také jejich ohněm spalte a rytiny bohů jejich stroskotejte, a vyhlaďte jméno jejich z místa toho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 4, 'Neučiníte tak Hospodinu Bohu svému,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 5, 'Ale kteréž by místo vyvolil Hospodin Bůh váš ze všech pokolení vašich, aby položil jméno své tu, a bydlil na něm, hledati ho, a tam choditi budete.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 6, 'Tam také přinášeti budete zápaly své a oběti i desátky své, oběti rukou svých i sliby své, dobrovolné oběti své, i prvorozené z skotů a bravů svých,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 7, 'A jísti budete tam před Hospodinem Bohem svým, a veseliti se budete v každé věci, k níž přičiníte ruky své, vy i domové vaši, v nichž požehnal tobě Hospodin Bůh tvůj.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 8, 'Nebudete dělati tak, jakž my nyní zde činíme, jeden každý což se mu dobrého vidí.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 9, 'Nebo až dosavad nepřišli jste k odpočinutí a dědictví, kteréž Hospodin Bůh tvůj dává tobě.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 10, 'Ale když přejdouce Jordán, bydliti budete v zemi, kterouž Hospodin Bůh váš dá vám, abys jí vládl právem dědičným, a odpočinutí dá vám ode všech vůkol nepřátel vašich, a bydliti budete bezpečně:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 11, 'Tedy k místu tomu, kteréž by vyvolil Hospodin Bůh váš, aby tam přebývalo jméno jeho, přinášeti budete všecky věci, kteréž já přikazuji vám, zápaly své, oběti své a desátky své, a oběti rukou svých a všecko, což předního jest v slibích vašich, kteréž byste činili Hospodinu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 12, 'A veseliti se budete před Hospodinem Bohem svým, vy i synové vaši i dcery vaše, služebníci vaši i děvky vaše, i Levíta, kterýž jest v branách tvých, nebo nemají dílu a dědictví s vámi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 13, 'Vystříhej se, abys neobětoval zápalných obětí svých na žádném místě, kteréž bys sobě obhlédl.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 14, 'Ale na tom místě, kteréž by vyvolil Hospodin v jednom z pokolení tvých, tam obětovati budeš zápaly své, a tam učiníš všecko, což já přikazuji tobě.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 15, 'A však jestliže by se kdy zalíbilo duši tvé, zabiješ sobě, a jísti budeš maso vedlé požehnání Hospodina Boha svého, kteréž by dal tobě ve všech městech tvých; nečistý i čistý jísti je bude, jako srnu i jelena.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 16, 'Krve toliko jísti nebudete, na zemi vycedíte ji jako vodu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 17, 'Nebudeš moci jísti v městě svém desátků obilí svého, vína a oleje svého, i prvorozených skotů a bravů svých, i všeho, k čemuž se slibem zavážeš, dobrovolných obětí svých a obětí rukou svých.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 18, 'Ale před Hospodinem Bohem svým jísti je budeš na místě, kteréž vyvolil Hospodin Bůh tvůj, ty i syn tvůj i dcera tvá, služebník tvůj a děvka tvá, i Levíta, kterýž jest v branách tvých, a veseliti se budeš před Hospodinem Bohem svým ve všech věcech, k nimž bys přičinil ruky své.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 19, 'Vystříhejž se, abys neopouštěl Levítů v zemi své po všecky dny své.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 20, 'Když rozšíří Hospodin Bůh tvůj pomezí tvé, jakož mluvil tobě, a řekl bys sám v sobě: Budu jísti maso, proto že žádá duše tvá jísti maso, vedlé vší líbosti své jísti budeš maso.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 21, 'Jestliže by daleko bylo od tebe místo, kteréž vyvolí Hospodin Bůh tvůj, aby přebývalo tam jméno jeho, zabiješ hovado z skotů neb bravů svých, kteréž by dal Hospodin tobě, jakžť jsem přikázal tobě, a jísti budeš v městě svém, vedlé vší líbosti duše své.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 22, 'Jakž se jídá srna a jelen, tak je jísti budeš; nečistý i čistý bude je jísti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 23, 'Toliko buď stálý, abys krve nejedl; nebo krev jest duše, protož nebudeš jísti duše s masem jejím.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 24, 'Nejeziž jí, ale na zem ji vyceď jako vodu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 25, 'Nebudeš jísti jí, aby tobě dobře bylo i synům tvým po tobě, když bys činil, což dobrého jest před očima Hospodinovýma.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 26, 'Ale posvěcené věci své, kteréž bys měl, a což bys slíbil, vezmeš, a doneseš na místo, kteréž vyvolí Hospodin,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 27, 'A obětovati budeš oběti své zápalné, maso a krev, na oltář Hospodina Boha svého; ale krev jiných obětí tvých vylita bude na oltář Hospodina Boha tvého, maso pak jísti budeš.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 28, 'Ostříhej a poslouchej všech slov těchto, kteráž já přikazuji tobě, aby tobě dobře bylo i synům tvým po tobě až na věky, když bys činil, což dobrého a pravého jest, před očima Hospodina Boha svého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 29, 'Když by pak vyplénil Hospodin Bůh tvůj od tváři tvé národy ty, k nimž ty tudíž vejdeš, abys dědičně vládl jimi, a dědičně je opanoval, a bydlil v zemi jejich,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 30, 'Vystříhej se, abys neuvázl v osídle, jda za nimi, když by již vyhlazeni byli od tváři tvé. Nevyptávej se na bohy jejich, říkaje: Jak jsou sloužili národové ti bohům svým, tak i já učiním.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 31, 'Neučiníš tak Hospodinu Bohu svému, nebo všecko, což v ohavnosti má Hospodin, a čehož nenávidí, činili bohům svým; také i syny své a dcery své ohněm pálili ke cti bohům svým.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 32, 'Cožkoli já přikazuji vám, ostříhati budete, činíce to; nepřidáte k tomu, aniž co z toho ujmete.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 1, 'Povstal-li by u prostřed tebe prorok, aneb někdo, ješto by míval sny, a ukázal by tobě znamení aneb zázrak,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 2, 'Byť se pak i stalo to znamení aneb zázrak, a mluvil by tobě, řka: Poďme, následujme bohů cizích, (kterýchž neznáš,) a služme jim:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 3, 'Neuposlechneš slov proroka toho, ani snáře, nebo zkušuje vás Hospodin Bůh váš, aby známé bylo, milujete-li Hospodina Boha svého z celého srdce svého a z celé duše své.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 4, 'Hospodina Boha svého následujte, a jeho se bojte, přikázaní jeho ostříhejte, hlasu jeho poslouchejte, jemu služte a jeho se přídržte.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 5, 'Prorok pak ten aneb snář zamordován bude, nebo mluvil to, čímž by odvrátil vás od Hospodina Boha vašeho, (kterýž vyvedl vás z země Egyptské, a vykoupil tě z domu služby,) aby tě srazil s cesty, kterouž přikázal tobě Hospodin Bůh tvůj, abys chodil po ní; a tak odejmeš zlé z prostředku svého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 6, 'Jestliže by tě tajně nabádal bratr tvůj, syn matky tvé, aneb syn tvůj, aneb dcera tvá, aneb manželka, kteráž jest v lůně tvém, aneb přítel tvůj, kterýžť by milý byl jako duše tvá, řka: Poďme a služme bohům cizím, (kterýchž jsi neznal ty ani otcové tvoji,)');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 7, 'Z bohů pohanských, kteříž vůkol vás jsou, buď blízko aneb daleko od tebe, od jednoho konce země až do druhého konce jejího,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 8, 'Nepovoluj jemu, aniž ho poslouchej; neodpustíť mu oko tvé, aniž se slituješ, aniž zatajíš ho,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 9, 'Ale bez milosti zabiješ jej; ruka tvá nejprv na něj bude vztažena, abys ho zabil, a potom ruce všeho lidu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 10, 'A ukamenuješ jej až do smrti, nebo chtěl odvésti tebe od Hospodina Boha tvého, kterýž tě vyvedl z země Egyptské, z domu služby,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 11, 'Aby všecken lid Izraelský, uslyšíce to, báli se, a nečinili více něco podobného věci této nejhorší u prostřed tebe.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 12, 'Uslyšel-li bys o některém městě svém, kteréž Hospodin Bůh tvůj dá tobě, abys tam bydlil, ani praví:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 13, 'Vyšli muži, lidé nešlechetní z prostředku tvého, kteříž svedli spoluobyvatele své, řkouce: Poďme, služme bohům cizím, kterýchž neznáte:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 14, 'Tedy vyhledej a vyzvěz a dobře se na to vyptej, a jestliže jest pravda a jistá věc, že ohavnost se stala u prostřed tebe,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 15, 'Zbiješ obyvatele města toho mečem, a jako věc proklatou zkazíš je i všecko, což by v něm bylo, hovada také jeho mečem pobiješ.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 16, 'A všecky kořisti jeho shromáždíš u prostřed ulice jeho, a spálíš ohněm to město i všecky kořisti jeho docela Hospodinu Bohu svému, aby byla hromada rumu věčná; a nebude více staveno.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 17, 'A nevezmeš ničehož z věcí proklatých, aby Hospodin odvrátil se od hněvu prchlivosti své, a učinil tobě milosrdenství svá, a smiloval se nad tebou, i rozmnožil tě, jakož s přísahou zaslíbil otcům tvým.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 18, 'Protož poslouchati budeš hlasu Hospodina Boha svého, ostříhaje všech přikázaní jeho, kteráž já dnes přikazuji tobě, abys činil, což pravého jest, před očima Hospodina Boha svého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 1, 'Synové jste Hospodina Boha vašeho, protož nebudete se řezati, aniž sobě uděláte lysiny mezi očima vašima nad mrtvým.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 2, 'Nebo lid svatý jsi Hospodinu Bohu svému, a tebe vyvolil Hospodin, abys jemu byl za lid zvláštní ze všech národů, kteříž jsou na tváři země.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 3, 'Nebudeš jísti žádné věci ohavné.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 4, 'Tato jsou hovada, kteráž jísti budete: Voly, ovce a kozy,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 5, 'Jelena, dannele, srnu, kamsíka, jezevce, bůvola a losa.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 6, 'Každé hovado, kteréž má kopyta rozdělená, tak aby rozdvojená byla, a přežívá mezi hovady, jísti je budete.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 7, 'A však ne všech přežívajících, aneb těch, kteráž kopyta rozdělená mají, budete jísti, jako velblouda, zajíce a králíka; nebo ač přežívají, však kopyta rozděleného nemají, nečistá jsou vám.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 8, 'Též svině, nebo rozdělené majíc kopyto, nepřežívá, nečistá vám bude; masa jejího jísti nebudete, a mrchy její se nedotknete.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 9, 'Ze všech pak živočichů, kteříž u vodách jsou, tyto jísti budete: Cožkoli má plejtvy a šupiny, jísti budete.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 10, 'Což pak nemá plejtví a šupin, toho jísti nebudete; nečisté vám bude.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 11, 'Všecko ptactvo čisté jísti budete.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 12, 'Těchto pak jísti nebudete: Orla, noha, orlice mořské,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 13, 'A sokola, supa a luňáka vedlé pokolení jeho,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 14, 'A žádného krkavce vedlé pokolení jeho,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 15, 'Pstrosa, sovy, vodní káně a krahulce vedlé pokolení jeho,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 16, 'Raroha, kalousa a labuti,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 17, 'Pelikána, porfiriána a křehaře,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 18, 'Čápa, volavky vedlé pokolení jejího, dedka a netopýře.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 19, 'A všeliký zeměplaz létající nečistý bude vám, nebudete ho jísti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 20, 'Každého ptáka čistého jísti budete.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 21, 'Žádné umrliny jísti nebudete; příchozímu, kterýž jest v branách tvých, dáš ji, a jísti ji bude, aneb prodáš cizozemci, nebo lid svatý jsi Hospodinu Bohu svému. Nebudeš vařiti kozelce v mléce matky jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 22, 'Ochotně dávati budeš desátky ze všech užitků semene svého, kteřížť by přišli s pole každého roku.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 23, 'A jísti budeš před Hospodinem Bohem svým, (na místě, kteréž by vyvolil, aby tam přebývalo jméno jeho,) desátky z obilí, vína i oleje svého, a prvorozené z volů svých a drobného dobytka svého, abys se učil báti Hospodina Boha svého po všecky dny.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 24, 'Jestliže by pak daleká byla cesta, a nemohl bys donésti toho, proto že daleko jest od tebe to místo, kteréž by vyvolil Hospodin Bůh tvůj k přebývání tam jména svého, když požehná tobě Hospodin Bůh tvůj:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 25, 'Tedy zpeněžíš je, a svázané peníze vezma v ruku svou, půjdeš k místu, kteréž by vyvolil Hospodin Bůh tvůj,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 26, 'A vynaložíš ty peníze na všecko, čehož žádá duše tvá, na voly, na ovce, na víno, aneb jiný nápoj silný, a na všecko, čehož by sobě žádala duše tvá, a jísti budeš tam před Hospodinem Bohem svým, a veseliti se budeš ty i dům tvůj.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 27, 'Levíty pak, kterýž by v branách tvých bydlil, neopustíš, nebo nemá dílu a dědictví s tebou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 28, 'Každého léta třetího oddělíš všecky desátky z užitků svých toho léta, a složíš je v branách svých.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 29, 'I přijde Levíta, (nebo nemá dílu a dědictví s tebou,) a host a sirotek i vdova, kteříž jsou v branách tvých, i budou jísti a nasytí se, aby požehnal tobě Hospodin Bůh tvůj při všelikém díle rukou tvých, kteréž bys dělal.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 1, 'Každého léta sedmého odpouštěti budeš.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 2, 'Tento pak bude způsob odpuštění, aby odpustil každý věřitel, kterýž rukou svou půjčil to, čehož půjčil bližnímu svému; nebude upomínati bližního svého aneb bratra svého, nebo vyhlášeno jest odpuštění Hospodinovo.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 3, 'Cizozemce upomínati budeš, ale to, což bys měl u bratra svého, propustí ruka tvá.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 4, 'Toliko aby nuzným někdo nebyl příčinou tvou, poněvadž hojně požehná tobě Hospodin v zemi, kterouž Hospodin Bůh tvůj dá tobě v dědictví, abys jí dědičně vládl:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 5, 'Jestliže však pilně poslouchati budeš hlasu Hospodina Boha svého, tak abys hleděl činiti každé přikázaní toto, kteréž já tobě dnes přikazuji.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 6, 'Hospodin zajisté Bůh tvůj požehná tobě, jakož mluvil tobě, tak že budeš moci půjčovati národům mnohým, tobě pak nebude potřeba vypůjčovati; i budeš panovati nad národy mnohými, ale oni nad tebou nebudou panovati.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 7, 'Byl-li by u tebe nuzný někdo z bratří tvých, v některém městě tvém, v zemi tvé, kterouž Hospodin Bůh tvůj dá tobě, nezatvrdíš srdce svého, a nezavřeš ruky své před nuzným bratrem svým:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 8, 'Ale štědře otevřeš jemu ruku svou, a ochotně půjčíš jemu, jakž by mnoho potřeboval toho, v čemž by nouzi měl.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 9, 'Vystříhej se, aby nebylo něco nepravého v srdci tvém, a řekl bys: Blíží se rok sedmý, jenž jest rok odpuštění, a bylo by nešlechetné oko tvé k bratru tvému nuznému, tak že bys neudělil jemu, pročež by volal proti tobě k Hospodinu, a byl by na tobě hřích:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 10, 'Ale ochotně dáš jemu, a nebude srdce tvé neupřímé, když bys dával jemu; nebo tou příčinou požehná tobě Hospodin Bůh tvůj ve všech skutcích tvých a ve všem díle, k kterémuž bys vztáhl ruku svou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 11, 'Nebo nebudete bez chudých v zemi vaší; protož přikazuji tobě, řka: Abys ochotně otvíral ruku svou bratru svému, chudému svému a nuznému svému v zemi své.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 12, 'Jestliže by prodán byl tobě bratr tvůj Žid aneb Židovka, a sloužil by tobě za šest let, sedmého léta propustíš jej od sebe svobodného.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 13, 'A když jej propustíš svobodného od sebe, nepustíš ho prázdného.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 14, 'Štědře darovati jej budeš dary z dobytka svého, z stodoly a z vinice své; v čemž požehnal tobě Hospodin Bůh tvůj, z toho dáš jemu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 15, 'A pamatuj, že jsi služebníkem byl v zemi Egyptské, a že tě vykoupil Hospodin Bůh tvůj, protož já to dnes tobě přikazuji.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 16, 'Pakliť by řekl: Nepůjdu od tebe, proto že by tě miloval i dům tvůj, a že mu dobře u tebe,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 17, 'Tedy vezma špici, probodneš ucho jeho na dveřích, a bude u tebe služebníkem na věky. Takž podobně i děvce své učiníš.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 18, 'Nechť není za těžké před očima tvýma, když bys ho svobodného propustil od sebe, nebo dvojnásob více, než ze mzdy nájemník, sloužil tobě šest let; i požehná tobě Hospodin ve všech věcech, kteréž činiti budeš.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 19, 'Všeho prvorozeného, což se narodí z skotů tvých neb z bravů tvých, samce posvětíš Hospodinu Bohu svému. Nebudeš dělati prvorozeným volkem svým, a nebudeš holiti prvorozených ovec svých.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 20, 'Před Hospodinem Bohem svým budeš je jísti na každý rok na místě, kteréž by vyvolil Hospodin, ty i čeled tvá.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 21, 'Pakliť by na něm byla vada, že by kulhavé aneb slepé bylo, aneb mělo by jakoukoli škodlivou vadu, nebudeš ho obětovati Hospodinu Bohu svému.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 22, 'V branách svých budeš je jísti, buďto čistý neb nečistý, rovně jako srnu aneb jelena;');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 23, 'Toliko krve jeho nebudeš jísti, ale na zem vycedíš ji jako vodu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 1, 'Ostříhej měsíce Abib, abys slavil Fáze Hospodinu Bohu svému, nebo toho měsíce Abib vyvedl tě Hospodin Bůh tvůj z Egypta v noci.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 2, 'A obětovati budeš Fáze Hospodinu Bohu svému z bravů i skotů na místě, kteréž by vyvolil Hospodin, aby tam přebývalo jméno jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 3, 'Nebudeš v něm jísti nic kvašeného. Za sedm dní jísti budeš přesnice, chléb trápení, (nebo s chvátáním vyšel jsi z země Egyptské,) abys pamatoval na den, v kterémž jsi vyšel z země Egyptské, po všecky dny života svého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 4, 'Aniž spatřín bude u tebe kvas ve všech končinách tvých za sedm dní, a nezůstane nic přes noc masa toho, kteréž bys obětoval u večer toho dne prvního, až do jitra.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 5, 'Nebudeš moci obětovati Fáze v každém městě svém, kteréž Hospodin Bůh tvůj dává tobě,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 6, 'Ale na místě, kteréž by vyvolil Hospodin Bůh tvůj, aby přebývalo tam jméno jeho, tu obětovati budeš Fáze, a to u večer, při západu slunce v jistý čas vyjití tvého z Egypta.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 7, 'Péci pak budeš a jísti na místě, kteréž by vyvolil Hospodin Bůh tvůj, a ráno navracuje se, půjdeš do stanů svých.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 8, 'Šest dní jísti budeš přesnice, dne pak sedmého bude slavnost Hospodinu Bohu tvému; ničehož v ní dělati nebudeš.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 9, 'Sedm téhodnů sečteš sobě; od začátku žně začneš počítati sedm téhodnů.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 10, 'Tehdy slaviti budeš slavnost téhodnů Hospodinu Bohu svému; seč budeš moci býti, to dáš dobrovolně vedlé toho, jakžť by požehnal Hospodin Bůh tvůj.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 11, 'I veseliti se budeš před Hospodinem Bohem svým, ty i syn tvůj i dcera tvá, služebník tvůj a děvka tvá, i Levíta, kterýž by byl v branách tvých, a příchozí, sirotek i vdova, kteříž by byli u prostřed tebe, na místě, kteréž by vyvolil Hospodin Bůh tvůj k přebývání tam jména svého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 12, 'A tak rozpomínati se budeš, že jsi byl služebníkem v Egyptě, když ostříhati a vykonávati budeš ustanovení tato.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 13, 'Slavnost stanů světiti budeš za sedm dní, když shromáždíš s pole svého a z vinice své.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 14, 'I budeš se veseliti v slavnosti své, ty i syn tvůj i dcera tvá, služebník tvůj a služebnice tvá, Levíta i příchozí, sirotek i vdova, kteříž by byli v branách tvých.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 15, 'Sedm dní svátek světiti budeš Hospodinu Bohu svému na místě, kteréž by vyvolil Hospodin, když požehná tobě Hospodin Bůh tvůj ve všech úrodách tvých, a ve všeliké práci rukou tvých, a tak budeš vesel.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 16, 'Třikrát v roce postaví se každý pohlaví mužského před Hospodinem Bohem tvým na místě, kteréž by vyvolil, na slavnost přesnic, na slavnost téhodnů a na slavnost stanů, a neukážeť se před Hospodinem prázdný;');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 17, 'Každý podlé daru sobě daného, vedlé požehnání Hospodina Boha tvého, jehož on udělil tobě.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 18, 'Soudce a správce ustanovíš sobě ve všech městech svých, kteráž Hospodin Bůh tvůj dá tobě v každém pokolení tvém, kteříž souditi budou lid soudem spravedlivým.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 19, 'Neuchýlíš soudu, a nebudeš šetřiti osoby, aniž přijmeš daru; nebo dar oslepuje oči moudrých, a převrací slova spravedlivých.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 20, 'Spravedlivě spravedlnosti následovati budeš, abys živ byl, a dědičně vládl zemí, kterouž Hospodin Bůh tvůj dává tobě.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 21, 'Nevysadíš sobě háje jakýmkoli dřívím u oltáře Hospodina Boha svého, kterýž uděláš sobě,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 22, 'Ani vyzdvihneš sobě modly, což v ohavnosti má Hospodin Bůh tvůj.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 1, 'Nebudeš obětovati Hospodinu Bohu svému vola aneb dobytčete, na němž by vada byla, aneb jakákoli věc zlá, nebo ohavnost jest Hospodinu Bohu tvému.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 2, 'Bude-li nalezen u prostřed tebe v některém městě tvém, kteráž Hospodin Bůh tvůj dá tobě, muž aneb žena, ješto by se dopouštěl zlého před očima Hospodina Boha tvého, přestupuje smlouvu jeho,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 3, 'A odejda, sloužil by bohům cizím, a klaněl by se jim, buď slunci neb měsíci, aneb kterému rytířstvu nebeskému, čehož jsem nepřikázal,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 4, 'A bylo by povědíno tobě, a slyšel bys o tom, tedy vyptáš se pilně na to, a jestliže bude pravda a věc jistá, že by se stala taková ohavnost v Izraeli:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 5, 'Bez lítosti vyvedeš muže toho aneb ženu tu, kteříž to zlé páchali, k branám svým, muže toho aneb ženu, a kamením je uházíš, ať zemrou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 6, 'V ústech dvou aneb tří svědků zabit bude ten, kdož umříti má, nebudeť pak zabit podlé vyznání svědka jednoho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 7, 'Ruka svědků nejprv bude proti němu k zabití jeho, a potom ruce všeho lidu, a tak odejmeš zlé z prostředku svého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 8, 'Bylo-li by při soudu něco nesnadného, mezi krví a krví, mezi pří a pří, mezi ranou a ranou, v jakékoli rozepři v branách tvých, tedy vstana, půjdeš k místu, kteréž by vyvolil Hospodin Bůh tvůj,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 9, 'A přijdeš k kněžím Levítského pokolení aneb k soudci, kterýž by tehdáž byl, i budeš se jich ptáti, a oznámíť výpověd soudu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 10, 'Učiníš tedy vedlé naučení, kteréž by vynesli z místa toho, kteréž by vyvolil Hospodin, a hleď, abys všecko, čemuž by tě učili, tak vykonal.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 11, 'Podlé vyrčení zákona, kterémuž by tě naučili, a podlé rozsudku, kterýžť by vypověděli, učiníš; neuchýlíš se od slova sobě oznámeného ani na pravo ani na levo.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 12, 'Jestliže by pak kdo v zpouru se vydal, tak že by neposlechl kněze postaveného tam k službě před Hospodinem Bohem tvým, aneb soudce, tedy ať umře člověk ten, a odejmeš zlé z Izraele,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 13, 'Aby všecken lid uslyšíce, báli se, a více v zpouru se nevydávali.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 14, 'Když vejdeš do země, kterouž Hospodin Bůh tvůj dá tobě, abys ji dědičně obdržel, a budeš v ní bydliti, a řekneš: Ustanovím nad sebou krále, jako i jiní národové mají, kteříž jsou vůkol mne:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 15, 'Toho toliko ustanovíš nad sebou krále, kteréhož by vyvolil Hospodin Bůh tvůj. Z prostředku bratří svých ustanovíš nad sebou krále; nebudeš moci ustanoviti nad sebou člověka cizozemce, kterýž by nebyl bratr tvůj.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 16, 'A však ať nemívá mnoho koňů, a ať neobrací zase lidu do Egypta, z příčiny rozmnožení koňů, zvláště poněvadž Hospodin vám řekl: Nevracujte se zase cestou touto více.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 17, 'Nebudeť také míti mnoho žen, aby se neodvrátilo srdce jeho; stříbra také aneb zlata ať sobě příliš nerozmnožuje.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 18, 'Když pak dosedne na stolici království svého, vypíše sobě připomenutý zákon tento do knihy z té, kteráž bude před oblíčejem kněží Levítských.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 19, 'A bude jej míti při sobě, a čísti jej bude po všecky dny života svého, aby se naučil báti Hospodina Boha svého, a aby ostříhal všech slov zákona tohoto i ustanovení těch, a činil je,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 20, 'Aby nepozdvihlo se srdce jeho nad bratří jeho, a neuchýlilo se od přikázaní na pravo aneb na levo, aby dlouho živ byl v království svém, on i synové jeho u prostřed Izraele.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 1, 'Nebudou míti kněží Levítští a všecko pokolení Levítské dílu a dědictví s jiným lidem Izraelským, oběti ohnivé Hospodinovy a dědictví jeho jísti budou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 2, 'Dědictví nebudou míti u prostřed bratří svých, Hospodin jest dědictví jejich, jakož jim mluvil.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 3, 'Toto pak náležeti bude kněžím od lidu, od obětujících obět, buď vola neb dobytče: Dáno bude knězi plece, a líce a žaludek.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 4, 'Prvotiny obilé svého, vína a oleje svého, i prvotiny vlny z ovec svých dáš jemu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 5, 'Nebo jej vyvolil Hospodin Bůh tvůj ze všech pokolení tvých, aby stál k službě ve jménu Hospodina, on i synové jeho po všecky dny.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 6, 'Když by pak přišel který Levíta z některého města tvého, ze všeho Izraele, kdež bydlil, a přišel by s velikou žádostí duše své na místo, kteréž by vyvolil Hospodin:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 7, 'Sloužiti bude ve jménu Hospodina Boha svého, jako i jiní bratří jeho Levítové, kteříž tu stojí před Hospodinem.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 8, 'Díl rovný jísti budou, (bez škody toho, což by každý z nich prodal,) vedlé čeledi otců.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 9, 'Když vejdeš do země, kterouž Hospodin Bůh tvůj dává tobě, neuč se činiti podlé ohavností národů těch.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 10, 'Nebude nalezen v tobě, kdož by vedl syna svého aneb dceru svou skrz oheň, ani věštěc, ani planétník, ani čarodějník, ani kouzedlník.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 11, 'Ani losník, ani zaklinač, ani hadač, ani černokněžník.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 12, 'Nebo ohavnost jest Hospodinu, kdožkoli činí to, a pro takové ohavnosti Hospodin Bůh tvůj vymítá je od tváři tvé.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 13, 'Dokonalý budeš před Hospodinem Bohem svým.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 14, 'Nebo národové ti, kterýmiž vládnouti budeš, planetářů a věšťců poslouchají, tobě pak toho nedopouští Hospodin Bůh tvůj.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 15, 'Proroka z prostředku tvého, z bratří tvých, jako já jsem, vzbudí tobě Hospodin Bůh tvůj; jeho poslouchati budete,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 16, 'Podlé všeho toho, jakž jsi žádal od Hospodina Boha svého, na Orébě, v den shromáždění, řka: Ať více neslyším hlasu Hospodina Boha svého, ani více vidím ohně toho velikého, abych neumřel.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 17, 'Pročež mi řekl Hospodin: Dobře mluvili, což jsou mluvili.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 18, 'Proroka vzbudím jim z prostředku bratří jejich, jako jsi ty, a položím slova má v ústa jeho, a bude jim mluviti všecko, což mu přikáži.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 19, 'I budeť, že kdo by koli neposlouchal slov mých, kteráž mluviti bude ve jménu mém, já vyhledávati budu na něm.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 20, 'Prorok pak, kterýž by pyšně se vystavoval, mluvě slovo ve jménu mém, kteréhož jsem mluviti jemu nepřikázal, a kterýž by mluvil ve jménu bohů cizích, takový prorok ať umře.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 21, 'Jestliže pak díš v srdci svém: Kterak poznáme slovo to, jehož by nemluvil Hospodin?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 22, 'Když by mluvil něco prorok ve jménu Hospodinovu, a však by se toho nestalo, aniž by přišlo, toť jest to slovo, jehož nemluvil Hospodin; z pychuť jest to mluvil prorok ten, nebojž se ho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 1, 'Když by vyhladil Hospodin Bůh tvůj národy, jejichžto zemi Hospodin Bůh tvůj dává tobě, a opanoval bys je dědičně, a bydlil bys v městech jejich i v domích jejich:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 2, 'Oddělíš sobě tři města u prostřed země své, kterouž Hospodin Bůh tvůj dává tobě, abys ji dědičně obdržel.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 3, 'Spravíš sobě cesty, a rozdělíš na tři díly všecku krajinu země své, kterouž v dědictví dá tobě Hospodin Bůh tvůj, i bude utíkati tam každý vražedlník:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 4, '(Totoť pak bude právo vražedlníka, kterýž by tam utekl, aby živ byl: Kdož by zabil bližního svého nechtě, aniž by ho nenáviděl prvé.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 5, 'Jako vejda někdo s bližním svým do lesa sekati dříví, rozvedl by rukou svou sekeru, aby uťal dřevo, a ona by spadla s topořiště, a trefila by bližního jeho, tak že by umřel, ten uteče do některého z měst těchto, a živ bude.)');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 6, 'Aby přítel zabitého, stihaje vražedlníka toho, když by se rozpálilo srdce jeho, nedohonil ho na daleké cestě, a ranil smrtedlně, ješto by nebyl hoden smrti, poněvadž ho prvé neměl v nenávisti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 7, 'Protož já přikazuji tobě, řka: Tři města oddělíš sobě.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 8, 'Pakli by rozšířil Hospodin Bůh tvůj končiny tvé, jakož s přísahou zaslíbil otcům tvým, a dal by tobě všecku tu zemi, kterouž řekl dáti otcům tvým:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 9, '(Když bys ostříhal všech přikázaní těchto, čině je, kteráž já dnes přikazuji tobě, abys miloval Hospodina Boha svého, a chodil po cestách jeho po všecky dny,) tedy přidáš sobě ještě tři města mimo tři onano,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 10, 'Aby nebyla vylita krev nevinná u prostřed země tvé, kterouž Hospodin Bůh tvůj dá tobě v dědictví, a aby nebyla na tobě krev.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 11, 'Ale byl-li by kdo, maje v nenávisti bližního svého, a činil by úklady jemu, a povstana proti němu, ranil by ho smrtedlně, tak že by umřel, a utekl by do některého z těch měst:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 12, 'Tedy pošlí starší města toho, a vezmou jej odtud, a dají v ruce přítele toho zabitého, aby umřel.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 13, 'Neodpustí jemu oko tvé, ale svedeš krev nevinnou z Izraele, i bude dobře tobě.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 14, 'Nepřeneseš meze bližního svého, kterouž vymezili předkové v dědictví tvém, kteréž obdržíš v zemi, jižto Hospodin Bůh tvůj dává tobě, abys ji dědičně obdržel.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 15, 'Nepovstane svědek jeden proti někomu z příčiny jakékoli nepravosti, a jakéhokoli hříchu ze všech hříchů, kterýmiž by kdo hřešil; v ústech dvou svědků aneb v ústech tří svědků stane slovo.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 16, 'Povstal-li by svědek falešný proti někomu, aby svědčil proti němu, že odstoupil od Boha,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 17, 'Tedy postaví se ti dva muži, kteříž tu rozepři mají před Hospodinem, před kněžími aneb před soudci, kteříž by za dnů těch byli.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 18, 'A když se pilně vyptají soudcové, poznají-li, že svědek ten jest svědek lživý, mluvě falešné svědectví proti bližnímu svému,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 19, 'Tak jemu učiňte, jakž on myslil učiniti bratru svému. I odejmeš zlé z prostředku svého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 20, 'A kteříž zůstanou, slyšíce to, báti se budou, a nikoli více nedopustí se takových zlých věcí u prostřed tebe.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 21, 'A neslituje se oko tvé; život za život, oko za oko, zub za zub, ruka za ruku, noha za nohu bude.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 1, 'Když bys vytáhl na vojnu proti nepřátelům svým, a uzřel bys koně a vozy, a lid větší, nežli ty máš, neboj se jich, nebo Hospodin Bůh tvůj s tebou jest, kterýž tě vyvedl z země Egyptské.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 2, 'A když byste se již potýkati měli, přistoupí kněz, a mluviti bude k lidu,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 3, 'A dí jim: Slyš, Izraeli, vy jdete dnes k boji proti nepřátelům svým, nebudiž strašlivé srdce vaše, nebojte se a nestrachujte, ani se jich lekejte.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 4, 'Nebo Hospodin Bůh váš, kterýž jde s vámi, bojovati bude za vás proti nepřátelům vašim, aby zachoval vás.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 5, 'Potom mluviti budou hejtmané k lidu, řkouce: Jest-li kdo z vás, ješto vystavěl dům nový, a ještě nepočal bydliti v něm, odejdi a navrať se do domu svého, aby nezahynul v bitvě, a někdo jiný aby nezačal bydliti v něm.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 6, 'A kdo jest, ješto štípil vinici, a ještě nepřišla k obecnému užívání, odejdi a navrať se k domu svému, aby snad nezahynul v bitvě, aby někdo jiný k obecnému užívání nepřivedl jí.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 7, 'A kdo jest, ješto by měl zasnoubenou manželku, a ještě by jí nepojal, odejdi a navrať se do domu svého, aby neumřel v boji, a někdo jiný nevzal jí.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 8, 'Přidadí i toto hejtmané, mluvíce k lidu, a řeknou: Kdo jest bázlivý a lekavého srdce, odejdi a navrať se do domu svého, aby nezemdlil srdce bratří svých, jako jest srdce jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 9, 'A když přestanou hejtmané mluviti k lidu, tedy představí lidu vůdce houfů.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 10, 'Když přitáhneš k některému městu, abys ho dobýval, podáš jemu pokoje.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 11, 'Jestliže pokoj sobě podaný přijmou a otevrou tobě, všecken lid, kterýž by nalezen byl v něm, pod plat uvedeni jsouce, tobě sloužiti budou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 12, 'Pakli by v pokoj s tebou nevešli, ale bojovali proti tobě, oblehneš je;');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 13, 'A když by je Hospodin Bůh tvůj dal v ruku tvou, tedy zbiješ v něm ostrostí meče všecky pohlaví mužského.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 14, 'Ženy pak, dítky a hovada, i cožkoli bylo by v městě, všecky kořisti jeho rozbituješ sobě, a užívati budeš kořistí nepřátel svých, kteréž by dal tobě Hospodin Bůh tvůj.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 15, 'Tak učiníš všechněm městům daleko vzdáleným od tebe, kteráž nejsou z měst národů těchto.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 16, 'Z měst pak lidu toho, kterýž Hospodin Bůh tvůj dává tobě v dědictví, žádné duše živiti nebudeš,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 17, 'Ale dokonce vyhladíš je: Hetea, Amorea, Kananea, Ferezea, Hevea a Jebuzea, jakož přikázal tobě Hospodin Bůh tvůj,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 18, 'Aby vás neučili činiti vedlé všech ohavností svých, kteréž činí bohům svým, i hřešili byste proti Hospodinu Bohu svému.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 19, 'Když oblehneš město některé, za dlouhý čas dobývaje ho, abys je vzal, nezkazíš stromů jeho, sekerou je vytínaje, nebo z nich ovoce jísti budeš; protož jich nevysekáš, (nebo potrava člověka jest strom polní,) chtěje užívati jich k obraně své.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 20, 'A však stromoví, kteréž znáš, že nenese ovoce ku pokrmu, pohubíš a posekáš, a vzděláš ohrady proti městu tomu, kteréž s tebou bojuje, dokudž ho sobě nepodmaníš.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 1, 'Když by nalezen byl zabitý (v zemi, kterouž Hospodin Bůh tvůj dává tobě, abys dědičně vládl jí,) ležící na poli, a nebylo by vědíno, kdo by ho zabil,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 2, 'Tedy vyjdou starší tvoji a soudcové tvoji, a měřiti budou k městům, kteráž jsou vůkol toho zabitého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 3, 'A když nalezeno bude město nejbližší toho zabitého, tedy vezmou starší města toho jalovici z stáda, kteréž ještě nebylo užíváno, a kteráž netáhla ve jhu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 4, 'I uvedou starší toho města jalovici tu do údolí pustého, kteréž nikdy nebylo děláno aneb oseto, a setnou šíji jalovice v tom údolí.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 5, 'Potom přistoupí kněží synové Léví; (nebo je Hospodin Bůh tvůj vyvolil, aby přisluhovali jemu, a požehnání dávali ve jménu Hospodinovu, vedlé jejichž výpovědi stane všeliká rozepře a každá rána.)');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 6, 'Všickni také starší toho města, kteříž jsou nejbližší toho zabitého, umyjí ruce své nad jalovicí sťatou v tom údolí,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 7, 'A osvědčovati budou, řkouce: Nevylilyť jsou ruce naše krve té, aniž oči naše viděly vražedlníka.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 8, 'Očisť lid svůj Izraelský, kterýž jsi vykoupil, Hospodine, a nepřičítej krve nevinné lidu svému Izraelskému. I bude sňata s nich vina té krve.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 9, 'Ty pak odejmeš krev nevinnou z prostředku svého, když učiníš, což pravého jest před očima Hospodinovýma.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 10, 'Když bys vytáhl na vojnu proti nepřátelům svým, a dal by je Hospodin Bůh tvůj v ruce tvé, a zajal bys z nich mnohé;');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 11, 'Uzříš-li mezi zajatými ženu krásného oblíčeje, a zamiluješ ji, tak abys ji sobě vzal za manželku:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 12, 'Uvedeš ji do domu svého, i oholí sobě hlavu, a obřeže nehty své;');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 13, 'A složíc roucho své s sebe, v kterémž jest jata, zůstane v domě tvém, a plakati bude otce svého i matky své za celý měsíc; a potom vejdeš k ní, a budeš její manžel, a ona bude manželka tvá.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 14, 'Pakliť by se nelíbila, tedy propustíš ji svobodnou; ale nikoli neprodávej jí za peníze, ani nekupč jí, poněvadž jsi jí ponížil.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 15, 'Měl-li by kdo dvě ženy, jednu v milosti a druhou v nenávisti, a zplodily by mu syny, milá i nemilá, a byl-li by syn prvorozený nemilé:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 16, 'Tedy když dědice ustavovati bude nad tím, což by měl, nebude moci dáti práva prvorozenství synu milé před synem prvorozeným nemilé,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 17, 'Ale prvorozeného syna nemilé při prvorozenství zůstaví, a dá jemu dva díly ze všeho, což by měl; nebo on jest počátek síly jeho, jeho jest právo prvorozenství.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 18, 'Měl-li by kdo syna zpurného a protivného, ješto by neposlouchal hlasu otce svého a hlasu matky své, a jsa trestán, neuposlechl by jich:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 19, 'Tedy vezmouce ho otec i matka jeho, vyvedou jej k starším města svého, k bráně místa přebývání svého,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 20, 'A řeknou starším města svého: Syn náš tento, jsa zpurný a protivný, neposlouchá hlasu našeho, žráč a opilec jest.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 21, 'Tehdy všickni lidé města toho uházejí jej kamením a umřeť; a tak odejmeš zlé z prostředku svého, a všecken Izrael uslyšíce, báti se budou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 22, 'Když by kdo zhřešil, že by hoden byl smrti, a byl by odsouzen k ní a pověsil bys ho na dřevě:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 23, 'Nezůstane přes noc tělo jeho na dřevě, ale hned v ten den pochováš jej, nebo zlořečený jest před Bohem pověšený; protož nepoškvrňuj země své, kterouž Hospodin Bůh tvůj dává tobě v dědictví.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 1, 'Jestliže bys uzřel vola aneb dobytče bratra svého, an bloudí, nepomineš jich, ale přivedeš je až k bratru svému.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 2, 'Byť pak nebyl blízký bratr tvůj a neznal bys ho, uvedeš je však do domu svého, a bude u tebe, dokudž by se po něm neptal bratr tvůj, a navrátíš mu je.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 3, 'Tolikéž učiníš s oslem jeho, s oděvem jeho, také i se všelikou věcí ztracenou bratra svého, kteráž by mu zhynula; když bys ji nalezl, nepomineš jí.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 4, 'Vida osla bratra svého aneb vola jeho pod břemenem ležící na cestě, nepomineš jich, ale i hned ho s ním pozdvihneš.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 5, 'Žena nebude nositi oděvu mužského, aniž se obláčeti bude muž v roucho ženské, nebo ohavnost před Hospodinem Bohem tvým jest, kdožkoli činí to.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 6, 'Když bys našel hnízdo ptačí před sebou na cestě, na jakémkoli stromu aneb na zemi, s mladými neb vejci, a matka seděla by na mladých aneb na vejcích: nevezmeš matky s mladými,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 7, 'Ale hned pustíš matku a mladé vezmeš sobě, aby tobě dobře bylo, a abys prodlil dnů svých.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 8, 'Když bys stavěl dům nový, udělej zabradla vůkol střechy své, abys neuvedl viny krve na dům svůj, když by kdo upadl s něho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 9, 'Neposeješ vinice své směsicí rozličného semene, aby nebyl poškvrněn užitek semene, kteréž jsi vsel, i ovoce vinice.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 10, 'Nebudeš orati volem a oslem spolu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 11, 'Neoblečeš roucha z rozdílných věcí, z vlny a lnu setkaného.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 12, 'Prýmy zděláš sobě na čtyřech rozích oděvu svého, jímž se odíváš.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 13, 'Když by pojal někdo ženu, a všel by k ní, a potom měl by ji v nenávisti,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 14, 'A dal by příčinu k řečem o ní, v zlou pověst ji obláčeje a mluvě: Ženu tuto vzal jsem, a všed k ní, nenalezl jsem jí pannou:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 15, 'Tedy otec děvečky a matka její vezmouce přinesou znamení panenství děvečky k starším města svého k bráně.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 16, 'A dí otec děvečky k starším: Dceru svou dal jsem muži tomuto za manželku, kterýž ji v nenávisti má.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 17, 'A hle, sám příčinu dal řečem o ní, mluvě: Nenalezl jsem při dceři tvé panenství, a teď hle, znamení panenství dcery mé. I roztáhnou roucho to před staršími města.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 18, 'Tedy starší města toho jmou muže a trestati ho budou,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 19, 'A uloží jemu pokutu sto lotů stříbra, kteréž dají otci děvečky, proto že vynesl zlou pověst proti panně Izraelské. I bude ji míti za manželku, kteréž nebude moci propustiti po všecky dny své.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 20, 'Jináč byla-li by pravá žaloba ta, a nebylo by nalezeno panenství při děvečce:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 21, 'Tedy vyvedou děvečku ke dveřím otce jejího, a uházejí ji lidé města toho kamením, a umře; nebo dopustila se nešlechetnosti v Izraeli, smilnivši v domě otce svého. Tak odejmeš zlé z prostředku sebe.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 22, 'Kdyby kdo postižen byl, že obýval s ženou manželkou cizí, tedy umrou oni oba dva, muž, kterýž obýval s tou ženou, i žena také; i odejmeš zlé z Izraele.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 23, 'Byla-li by děvečka panna zasnoubená muži, a nalezna ji někdo v městě, obýval by s ní:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 24, 'Vyvedete oba dva k bráně města toho, a uházíte je kamením, a umrou, děvečka, proto že nekřičela, jsuci v městě, a muž proto, že ponížil ženy bližního svého; a odejmeš zlé z prostředku svého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 25, 'Pakli na poli nalezl by muž děvečku zasnoubenou, a násilí jí učině, obýval by s ní: smrtí umře muž ten sám,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 26, 'Děvečce pak nic neučiníš. Nedopustila se hříchu hodného smrti; nebo jakož povstává někdo proti bližnímu svému a morduje život jeho, tak i při této věci.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 27, 'Na poli zajisté nalezl ji; křičela děvečka zasnoubená, a žádný tu nebyl, kdo by ji vysvobodil.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 28, 'Jestliže by nalezl někdo děvečku pannu, kteráž by zasnoubena nebyla, a vezma ji, obýval by s ní, a byli by postiženi:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 29, 'Tedy dá muž ten, kterýž by obýval s ní, otci děvečky padesáte stříbrných, a bude jeho manželka, protože ponížil jí; nebude moci jí propustiti po všecky dny své.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 30, 'Nevezme žádný manželky otce svého, a neodkryje podolka otce svého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 1, 'Nevejde do shromáždění Hospodinova, kdož by měl stlučené aneb odňaté lůno.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 2, 'Aniž vejde do shromáždění Hospodinova syn postranní; také i desáté koleno jeho nevejde do shromáždění Hospodinova.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 3, 'Ammonitský tolikéž ani Moábský nevejde do shromáždění Hospodinova, ani desáté koleno jejich nevejde do shromáždění Hospodinova až na věky.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 4, 'Proto že proti vám nevyšli s chlebem a s vodou na cestě, když jste šli z Egypta, a že ze mzdy najal proti tobě Baláma, syna Beor, z Petor Mezopotamie Syrské, aby zlořečil tobě:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 5, '(Ačkoli nechtěl Hospodin Bůh tvůj slyšeti Baláma, ale obrátil Hospodin Bůh tvůj tobě zlořečení v požehnání, nebo miloval tebe Hospodin Bůh tvůj.)');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 6, 'Nebudeš hledati pokoje jejich ani dobrého jejich po všecky dny své na věky.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 7, 'Nebudeš míti v ohavnosti Idumejského, nebo bratr tvůj jest, aniž Egyptského v ohavnosti míti budeš, nebo jsi byl pohostinu v zemi jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 8, 'Synové, kteříž se jim zrodí v třetím kolenu, vejdou do shromáždění Hospodinova.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 9, 'Když bys vytáhl vojensky proti nepřátelům svým, vystříhej se od všeliké zlé věci.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 10, 'Bude-li mezi vámi kdo, ješto by poškvrněn byl příhodou noční, vyjde ven z stanů, a nevejde do nich;');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 11, 'Ale když bude k večerou, umyje se vodou, a po západu slunce vejde do stanů.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 12, 'Také místo budeš míti vně za stany, abys tam chodíval ven;');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 13, 'A budeš míti kolík mezi jinými nástroji svými, a když bys chtěl sednouti vně, vykopáš jím důlek, a obrátě se, zahrabeš nečistotu svou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 14, 'Nebo Hospodin Bůh tvůj chodí u prostřed stanů tvých, aby tě vysvobodil, a dal tobě nepřátely tvé; protož ať jest příbytek tvůj svatý, tak aby nespatřil při tobě mrzkosti nějaké, pročež by se odvrátil od tebe.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 15, 'Nevydáš služebníka pánu jeho, kterýž k tobě utekl od pána svého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 16, 'S tebou bydliti bude u prostřed tebe na místě, kteréž by vyvolil v některém městě tvém, kdežkoli jemu se líbiti bude; nebudeš ho mocí utiskati.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 17, 'Nebude nevěstka žádná z dcer Izraelských, ani nečistý smilník z synů Izraelských.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 18, 'Nepřineseš mzdy nevěstky, a mzdy psa do domu Hospodina Boha svého z jakéhokoli slibu, nebo to obé ohavnost jest Hospodinu Bohu tvému.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 19, 'Nedáš na lichvu bratru svému ani peněz, ani pokrmu, ani jakékoli věci, kteráž se dává na lichvu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 20, 'Cizímu půjčíš na lichvu, ale bratru svému nedáš na lichvu, aby požehnal tobě Hospodin Bůh tvůj při všech věcech, k kterýmž bys vztáhl ruku svou v zemi, do níž vejdeš, abys dědičně obdržel ji.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 21, 'Když bys učinil slib Hospodinu Bohu svému, neprodlévej splniti ho; nebo konečně toho vyhledávati bude Hospodin Bůh tvůj od tebe, a byl by na tobě hřích.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 22, 'Pakli nebudeš slibovati, nebude na tobě hříchu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 23, 'Což jednou vyšlo z úst tvých, to splníš, a učiníš, jakž jsi slíbil Hospodinu Bohu svému dobrovolně, což jsi vynesl ústy svými.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 24, 'Všel-li bys do vinice bližního svého, jísti budeš hrozny podlé žádosti své do sytosti své, ale do nádoby své nevložíš.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 25, 'Všel-li bys do obilí bližního svého, natrháš sobě klasů rukou svou, ale srpem nebudeš žíti obilí bližního svého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 1, 'Pojal-li by muž ženu a byl by manželem jejím, přihodilo by se pak, že by nenašla milosti před očima jeho pro nějakou mrzkost, kterouž by nalezl na ní, i napsal by jí lístek zapuzení a dal v ruku její, a vyhnal by ji z domu svého;');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 2, 'A vyjduci z domu jeho, odešla by a vdala se za druhého muže;');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 3, 'A ten také muž poslední v nenávisti maje ji, napsal by lístek zapuzení a dal v ruce její, a vyhnal by ji z domu svého; aneb umřel by muž její poslední, kterýž vzal ji sobě za manželku:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 4, 'Nebude moci manžel její první, kterýž ji vyhnal, zase ji vzíti sobě za manželku, když již příčinou jeho poškvrněna jest; nebo ohavnost jest před Hospodinem. Protož nedopouštěj hřešiti lidu země, kterouž Hospodin Bůh tvůj dává tobě v dědictví.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 5, 'Když by někdo v nově pojal ženu, nevyjde k boji, aniž na něj vzkládána bude jaká obecní práce; svoboden bude v domě svém za jeden rok, a veseliti se bude s manželkou svou, kterouž pojal.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 6, 'Žádný nevezme v zástavě svrchního i spodního žernovu, nebo takový bral by duši v základu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 7, 'Byl-li by postižen někdo, že ukradl člověka z bratří svých synů Izraelských, a k zisku by sobě jej přivedl aneb prodal jej: umře zloděj ten, a odejmeš zlé z prostředku svého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 8, 'Šetř se při ráně malomocenství, abys ostříhal pilně a činil všecko, jakž učiti budou vás kněží Levítové; jakož přikázal jsem jim, ostříhati toho budete a tak činiti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 9, 'Pomni na ty věci, které učinil Hospodin Bůh tvůj Marii na cestě, když jste vyšli z Egypta.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 10, 'Půjčil-li bys bližnímu svému něčeho, nevejdeš do domu jeho, abys vzal něco v zástavě od něho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 11, 'Ale vně staneš, a člověk, jemuž jsi půjčil, vynese tobě základ svůj ven.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 12, 'Jestliže by pak byl člověk chudý, nebudeš spáti s základem jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 13, 'Bez prodlévání navrátíš jemu zastavenou věc jeho při západu slunce, aby leže v šatech svých, dobrořečil tobě, a bude to za spravedlnost tobě před Hospodinem Bohem tvým.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 14, 'Neutiskneš nájemníka chudého a nuzného, tak z bratří svých jako z příchozích, kteříž jsou v zemi tvé v branách tvých.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 15, 'Na každý den dáš jemu mzdu jeho, prvé nežli by slunce zapadlo; nebo chudý jest, a tím se živí, aby neúpěl proti tobě k Hospodinu, a byl by na tobě hřích.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 16, 'Nebudou na hrdle trestáni otcové za syny, ani synové trestáni budou na hrdle za otce, jeden každý za svůj hřích umře.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 17, 'Nepřevrátíš soudu příchozímu neb sirotku, ani vezmeš v základu roucha vdovy,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 18, 'Ale pamatuj, že jsi byl služebníkem v Egyptě, a že tě vykoupil Hospodin Bůh tvůj odtud; protož přikazujiť, abys činil toto.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 19, 'Když bys žal obilí své na poli svém, a zapomenul bys tam některého snopu, nenavrátíš se, abys jej vzal; příchozímu, sirotku a vdově to bude, aby požehnal tobě Hospodin Bůh tvůj při všelikém díle rukou tvých.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 20, 'Když bys třásl olivy své, nebudeš shledávati po každé ratolesti za sebou; příchozímu, sirotku a vdově to zůstane.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 21, 'Když bys sbíral víno na vinici své, nebudeš paběrovati jahodek za sebou; příchozímu, sirotku a vdově to bude.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 22, 'Pamatuj, že jsi byl služebníkem v zemi Egyptské; protož přikazujiť, abys to činil.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 1, 'Vznikla-li by jaká nesnáz mezi některými, a přistoupili by k soudu, aby je rozsoudili, tedy spravedlivého ospravedlní, a nepravého odsoudí.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 2, 'Bude-li pak hoden mrskání nepravý, tedy káže ho položiti soudce a mrskati před sebou, vedlé nepravosti jeho v jistý počet ran.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 3, 'Čtyřidcetikrát káže ho mrštiti, aniž přidá více, aby, jestliže by jej nadto mrskal ranami mnohými, nebyl příliš zlehčen bratr tvůj před očima tvýma.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 4, 'Nezavížeš úst vola mlátícího.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 5, 'Když by bratří spolu bydlili, a umřel by jeden z nich, nemaje syna, nevdá se ven žena toho mrtvého za jiného muže; bratr jeho vejde k ní, a vezme ji sobě za manželku, a právem švagrovství přižení se k ní.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 6, 'Prvorozený pak, kteréhož by porodila, nazván bude jménem bratra jeho mrtvého, aby nebylo vyhlazeno jméno jeho z Izraele.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 7, 'Nechtěl-li by pak muž ten pojíti příbuzné své, tedy přijde příbuzná jeho k bráně před starší a řekne: Nechce příbuzný můj vzbuditi bratru svému jména v Izraeli, a nechce podlé práva švagrovství pojíti mne.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 8, 'Tedy povolají ho starší města toho, a mluviti budou s ním; a stoje, řekl-li by: Nechci jí pojíti,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 9, 'Přistoupí příbuzná jeho k němu před staršími, a szuje střevíc jeho s nohy jeho, a pline mu na tvář a odpoví, řkuci: Tak se má státi muži tomu, kterýž by nechtěl vzdělati domu bratra svého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 10, 'I bude nazváno jméno jeho v Izraeli: Dům bosého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 11, 'Když by se svadili někteří spolu jeden s druhým, a přistoupila by žena jednoho, aby vysvobodila muže svého z ruky bijícího jej, i vztáhla by ruku svou a uchopila by ho za lůno:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 12, 'Tedy utneš ruku její, neslituje se nad ní oko tvé.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 13, 'Nebudeš míti v pytlíku svém nejednostejného kamene, většího a menšího.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 14, 'Aniž budeš míti v domě svém nejednostejného korce, většího a menšího.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 15, 'Váhu celou a spravedlivou míti budeš, též míru celou a spravedlivou budeš míti, aby se prodlili dnové tvoji v zemi, kterouž Hospodin Bůh tvůj dává tobě.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 16, 'Nebo v ohavnosti jest Hospodinu Bohu tvému, kdožkoli činí ty věci, všeliký činící nepravost.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 17, 'Pamatuj na to, coť učinil Amalech na cestě, když jste šli z Egypta:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 18, 'Kterak vyšed tobě v cestu, zadní houf tvůj všech mdlých, kteříž šli za tebou, pobil, když jsi ty byl zemdlený a ustalý, a nebál se Boha.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 19, 'Protož když byl Hospodin Bůh tvůj dal tobě odpočinutí ode všech nepřátel tvých vůkol v zemi, kterouž Hospodin Bůh tvůj dává tobě v dědictví, abys dědičně obdržel ji, vyhladíš památku Amalecha pod nebem; nezapomínejž na to.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 1, 'Když pak vejdeš do země, kterouž Hospodin Bůh tvůj dává tobě v dědictví, a opanuje ji, bydliti v ní budeš:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 2, 'Vezmeš prvotin všeho ovoce země té, kteréž obětovati budeš z země své, již Hospodin Bůh tvůj dává tobě, a vlože do koše, půjdeš k místu, kteréž by Hospodin Bůh tvůj k přebývání tam jménu svému vyvolil.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 3, 'A přijda k knězi, kterýž těch dnů bude, díš jemu: Vyznávám dnes Hospodinu Bohu svému, že jsem všel do země, kterouž s přísahou zaslíbil Hospodin otcům našim, že ji nám dá.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 4, 'I vezma kněz z ruky tvé koš, postaví jej před oltářem Hospodina Boha tvého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 5, 'A mluviti budeš před Hospodinem Bohem svým, řka: Syrský chudý otec můj sstoupil do Egypta s nemnohými osobami, a byv tam pohostinu, vzrostl v národ veliký, silný a mnohý.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 6, 'A když zle nakládali s námi Egyptští, trápíce nás, a vzkládajíce na nás službu těžkou,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 7, 'Volali jsme k Hospodinu Bohu otců našich, a vyslyšev Hospodin hlas náš, popatřil na trápení naše, práci naši a ssoužení naše.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 8, 'I vyvedl nás Hospodin z Egypta v ruce silné a v rameni vztaženém, v strachu velikém, a znameních i zázracích.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 9, 'A uvedl nás na toto místo, a dal nám zemi tuto oplývající mlékem a strdí.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 10, 'Protož nyní, hle, přinesl jsem prvotiny úrod země, kterouž jsi mi dal, ó Hospodine. I necháš toho před Hospodinem Bohem svým, a pokloníš se před ním.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 11, 'I veseliti se budeš ve všech dobrých věcech, kteréž by tobě dal Hospodin Bůh tvůj, i domu tvému, ty i Levíta i příchozí, kterýž jest u prostřed tebe.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 12, 'Když bys pak vyplnil všecky desátky ze všech úrod svých léta třetího, jenž rok desátků jest, a dal bys Levítovi, příchozímu, sirotku i vdově, a jedli by v branách tvých a nasyceni byli:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 13, 'Tedy díš před Hospodinem Bohem svým: Vynesl jsem, což posvěceného bylo, z domu svého, a dal jsem také Levítovi, příchozímu, sirotku a vdově vedlé všelikého přikázaní tvého, kteréž jsi mi přikázal; nepřestoupil jsem žádného z přikázaní tvých, aniž jsem zapomenul na ně.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 14, 'Nejedl jsem v zámutku svém z toho, a neujal jsem z toho k věci obecné, aniž jsem dal něco odtud ku pohřbu; poslechl jsem hlasu Hospodina Boha svého, učinil jsem podlé všeho, což jsi mi přikázal.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 15, 'Popatřiž z příbytku svatého svého s nebe, a požehnej lidu svému Izraelskému a zemi, kterouž jsi dal nám, jakož jsi s přísahou zaslíbil otcům našim, zemi oplývající mlékem a strdí.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 16, 'Dnes Hospodin Bůh tvůj přikazuje tobě, abys ostříhal ustanovení těchto a soudů; ostříhejž tedy a čiň je z celého srdce svého a ze vší duše své.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 17, 'Dnes i ty připověděls se k Hospodinu, že jej budeš míti za Boha, a choditi budeš po cestách jeho, a ostříhati ustanovení jeho, a přikázaní i soudů jeho, a poslouchati hlasu jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 18, 'Hospodin také připověděl se k tobě dnes, že tě bude míti za lid zvláštní, jakož mluvil tobě, abys ostříhal všech přikázaní jeho,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 19, 'A že tě vyvýší nade všecky národy, kteréž učinil, abys byl vzácnější, slovoutnější a slavnější nad ně, a tak lid svatý Hospodinu Bohu svému, jakož jest mluvil.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 1, 'I přikázal Mojžíš a starší Izraelští lidu, řkouce: Ostříhejž každého přikázaní, kteréž já přikazuji vám dnes.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 2, 'A když přejdeš přes Jordán do země, kterouž Hospodin Bůh tvůj dává tobě, vyzdvihneš sobě kameny veliké, a obvržeš je vápnem.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 3, 'A napíšeš na nich všecka slova zákona tohoto, když přejdeš, abys všel do země, kterouž Hospodin Bůh tvůj dává tobě, do země oplývající mlékem a strdí, jakož jest mluvil Hospodin Bůh otců tvých tobě.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 4, 'Když tedy přejdeš Jordán a vyzdvihneš ty kameny, kteréž já přikazuji vám dnes, na hoře Hébal, a obvržeš je vápnem,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 5, 'A vzděláš tam oltář Hospodinu Bohu svému: oltář z kamenů, jichž nebudeš tesati železem,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 6, 'Z kamení celého vzděláš oltář Hospodinu Bohu svému, abys na něm obětoval oběti zápalné Hospodinu Bohu svému.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 7, 'Obětovati budeš i oběti pokojné, a jísti tu a veseliti se před Hospodinem Bohem svým.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 8, 'Napíšeš pak na těch kameních všecka slova zákona toho dobře a zřetelně.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 9, 'I mluvil Mojžíš a kněží Levítští ke všemu Izraelovi, řkouce: Pozoruj a slyš, Izraeli, dnes učiněn jsi lidem Hospodina Boha svého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 10, 'Protož poslouchej hlasu Hospodina Boha svého, a zachovávej přikázaní jeho i ustanovení jeho, kteráž já tobě dnes přikazuji.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 11, 'I přikázal Mojžíš v ten den lidu, řka:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 12, 'Tito stanou, aby dobrořečili lidu na hoře Garizim, když byste přešli Jordán: Simeon, Léví, Juda, Izachar, Jozef a Beniamin.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 13, 'Tito pak stanou, aby zlořečili na hoře Hébal: Ruben, Gád, Asser, Zabulon, Dan a Neftalím.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 14, 'I budou osvědčovati Levítové, a řeknou ke všechněm mužům Izraelským vysokým hlasem:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 15, 'Zlořečený člověk, kterýž by udělal rytinu aneb věc slitou, ohavnost Hospodinu, dílo rukou řemeslníka, by ji pak i do skrýše odložil. I odpoví všecken lid a řekne: Amen.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 16, 'Zlořečený, kdož sobě zlehčuje otce svého a matku svou; i řekne všecken lid: Amen.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 17, 'Zlořečený, kdož přenáší mezník bližního svého; i řekne všecken lid: Amen.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 18, 'Zlořečený, kdož zavodí slepého, aby bloudil po cestě; i řekne všecken lid: Amen.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 19, 'Zlořečený, kdož převrací spravedlnost příchozího, sirotka a vdovy; a odpoví všecken lid: Amen.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 20, 'Zlořečený, kdož by obýval s manželkou otce svého, nebo odkryl podolek otce svého; i řekne všecken lid: Amen.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 21, 'Zlořečený, kdož by obýval s kterýmkoli hovadem; i dí všecken lid: Amen.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 22, 'Zlořečený, kdož by obýval s sestrou svou, dcerou otce svého, aneb dcerou matky své; i řekne všecken lid: Amen.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 23, 'Zlořečený, kdož by obýval s svegruší svou; i odpoví všecken lid: Amen.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 24, 'Zlořečený, kdož by zbil bližního svého tajně; i řekne všecken lid: Amen.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 25, 'Zlořečený, kdož by vzal dary, aby zabil člověka nevinného; i dí všecken lid: Amen.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 26, 'Zlořečený, kdož by nezůstal v řečech zákona tohoto a nečinil jich; a řekne všecken lid: Amen.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 1, 'Jestliže pak opravdově poslušen budeš hlasu Hospodina Boha svého, ostříhaje a čině všecka přikázaní jeho, kteráž já dnes přikazuji tobě, vyvýší tě Hospodin Bůh tvůj nade všecky národy země.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 2, 'A přijdou na tě všecka požehnání tato, a vyplní se při tobě, když jen poslušen budeš hlasu Hospodina Boha svého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 3, 'Požehnaný budeš v městě, požehnaný i na poli.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 4, 'Požehnaný plod života tvého, úrody země tvé, i plod dobytka tvého, prvorozené skotů tvých i stáda bravů tvých.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 5, 'Požehnaný koš tvůj i díže tvá.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 6, 'Požehnaný budeš vcházeje, požehnaný i vycházeje.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 7, 'A učiní Hospodin, že nepřátelé tvoji, kteříž by povstali proti tobě, poraženi budou před tebou; jednou cestou vytáhnou proti tobě, a sedmi cestami před tebou utíkati budou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 8, 'Přikáže Hospodin požehnání svému, aby s tebou bylo v špižírnách tvých a při všem, k čemu bys koli přičinil ruku svou, a požehná tobě v zemi, kterouž Hospodin Bůh tvůj dává tobě.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 9, 'Vystaví tě sobě Hospodin za lid svatý, jakož zapřisáhl tobě, když ostříhati budeš přikázaní Hospodina Boha svého, a choditi po cestách jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 10, 'I uzří všickni národové země, že jméno Hospodinovo vzýváno jest nad tebou, a budou se báti tebe.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 11, 'Učiní také Hospodin, že hojnost míti budeš všeho dobrého, plodu života svého, i plodu dobytků svých, i úrod zemských v zemi, kterouž s přísahou zaslíbil otcům tvým, že ji tobě dá.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 12, 'Otevře Hospodin tobě poklad svůj výborný, nebe, aby vydalo déšť zemi tvé časem svým, a požehná všelikému dílu ruky tvé, tak že mnohým národům půjčovati budeš, sám pak nic nevypůjčíš.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 13, 'I ustanoví tě Hospodin za hlavu a ne za ocas, a budeš vždycky vyšší, a nikdy nižší, když poslouchati budeš přikázaní Hospodina Boha svého, kteráž já dnes tobě přikazuji, abys ostříhal a činil je.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 14, 'A neuchýlíš se od žádného slova, kteráž já dnes přikazuji tobě, ani na pravo ani na levo, odcházeje po bozích cizích, abys jim sloužil.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 15, 'Jestliže pak hlasu Hospodina Boha svého poslouchati, a všech přikázaní a ustanovení jeho, kteráž já dnes přikazuji tobě, ostříhati a činiti nebudeš, přijdou na tě všecka zlořečenství tato a postihnou tě.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 16, 'Zlořečený budeš v městě, zlořečený i na poli.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 17, 'Zlořečený koš tvůj, a zlořečená díže tvá.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 18, 'Zlořečený plod života tvého i úrody země tvé, prvorozené skotů tvých i stáda bravů tvých.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 19, 'Zlořečený budeš vcházeje, zlořečený i vycházeje.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 20, 'Pošle Hospodin na tě zlořečení, zkormoucení a bídu při všem, k čemuž bys koli přičinil ruky své a což bys koli dělal, dokudž nebudeš vyhlazen, a nezahyneš v náhle pro zlé skutky tvé, skrze něž jsi opustil mne.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 21, 'Dopustí Hospodin, aby se přídržely tebe morní bolesti, až tě i vypléní z země, do níž se béřeš, abys ji dědičně opanoval.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 22, 'Bíti tě bude Hospodin souchotinami, zimnicí, pálivostí, horkem, mečem, suchem a rudou, a budou tě stíhati, až tě i zkazí.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 23, 'I to nebe, kteréž jest nad hlavou tvou, bude měděné, a země, kteráž jest pod tebou, železná.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 24, 'Dá Hospodin zemi tvé místo deště prach a popel, a toť s nebe sstoupí na tě, dokudž bys nebyl vyhlazen.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 25, 'Učiní i to Hospodin, že poražen budeš od nepřátel svých; jednou cestou vytáhneš proti nim, a sedmi cestami utíkati budeš od tváři jejich, a musíš se smýkati po všech královstvích země.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 26, 'I budou těla vaše mrtvá za pokrm všemu ptactvu nebeskému, a šelmám zemským, a nebude, kdo by je odehnal.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 27, 'Raní tě Hospodin vředem Egyptským, neduhy na zadku, prašivinami a svrabem nezhojitelným.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 28, 'Raní tě Hospodin pominutím smyslu, slepotou a tupostí srdce,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 29, 'Tak že o poledni makati budeš, jako maká slepý ve tmě, a nebudeš míti prospěchu na cestách svých; k tomu také utiskán budeš, a loupen po všecky dny, a nebude, kdo by tě vysvobodil.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 30, 'Manželku sobě zasnoubíš, a jiný s ní obývati bude; dům vystavíš, a nebudeš bydliti v něm; vinici štípíš, a sbírati na ní nebudeš.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 31, 'Vůl tvůj před tvýma očima zabit bude, a ty jeho jísti nebudeš; osel tvůj uchvácen bude před tváří tvou, anižť se zase navrátí; dobytek tvůj vydán bude nepřátelům tvým, a žádný ho nevysvobodí.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 32, 'Synové tvoji a dcery tvé cizímu národu vydáni budou, a oči tvé na to hledíce, umdlívati budou pro ně celého dne, a nebude síly v ruce tvé.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 33, 'Úrody země tvé i všecko úsilí tvé sžíře národ, kteréhož ty neznáš, a nebudeš než potlačený a potřený po všecky dny.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 34, 'A omámený budeš nad těmi věcmi, kteréž viděti budou oči tvé.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 35, 'Raní tě Hospodin vředem nejhorším na kolenou i na lýtkách, tak že se nebudeš moci zhojiti, od spodku nohy tvé až do vrchu hlavy.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 36, 'Zavede tě Hospodin i krále tvého, kteréhož ustanovíš nad sebou, do národu, kteréhož jsi ty neznal, ani předkové tvoji, a sloužiti tam budeš bohům cizím, dřevu a kameni.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 37, 'A budeš k užasnutí a přísloví i v rozprávku všechněm národům, mezi kteréž zavede tě Hospodin.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 38, 'Mnoho semene vyneseš na pole k rozsívání, a málo shromáždíš, nebo sžerou to kobylky.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 39, 'Vinice štípíš a dělati je budeš, ale vína píti ani sbírati nebudeš, nebo červ sžíře je.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 40, 'Olivoví hojnost míti budeš ve všech končinách svých, a však olejem se pomazovati nebudeš, nebo sprchne ovoce s olivy tvé.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 41, 'Synů a dcer naplodíš, a nebudeš jich míti, nebo zajati budou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 42, 'Všecko stromoví tvé i úrody země tvé kobylky zkazí.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 43, 'Cizozemec, kterýž s tebou přebývá, vzroste nad tebe, ty pak velice ponižovati se musíš.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 44, 'On půjčovati bude tobě, a ty nebudeš míti, co bys půjčil jemu; on bude přednější, a ty poslednější.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 45, 'A přijdou na tebe všecka zlořečenství tato a stíhati tě budou, a obklíčí tě, až i zahyneš, jestliže bys neuposlechl hlasu Hospodina Boha svého, a neostříhal přikázaní a ustanovení jeho, kteráž přikázal tobě.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 46, 'A budou rány tyto znamením a zázrakem na tobě i semeni tvém až na věky,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 47, 'Proto že jsi nesloužil Hospodinu Bohu svému s potěšením a veselím srdce, maje hojnost všech věcí.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 48, 'A protož nepříteli svému, kteréhož poslal na tebe Hospodin, sloužiti musíš v hladu, žízni, v nahotě a v nedostatku všech věcí; a vloží na šíji tvou jho železné, dokudž tě nesetře.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 49, 'Přivede Hospodin na tebe národ z daleka, od nejdalších končin země, jako letí orlice, národ, jehož jazyku nerozumíš,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 50, 'Národ nestydatý, kterýž ani starce nebude šanovati, a nad dítětem se neslituje.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 51, 'A sžíře plod dobytků tvých i úrody země tvé, dokudž nebudeš vyhlazen; a nezanechá tobě obilí, vína mladého a oleje, prvorozeného z skotů tvých, ani stáda bravů tvých, až tě i vyhladí.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 52, 'A oblehne tě ve všech městech tvých, dokudž by nepadly zdi tvé vysoké a pevné, v nichž ty doufáš po vší zemi své; obležen, pravím, budeš ve všech městech svých, po vší zemi své, kterouž Hospodin Bůh tvůj dal tobě,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 53, 'Tak že v obležení a ssoužení, jímž ssouží tě nepřítel tvůj, jísti budeš plod života svého, maso synů svých a dcer svých, kteréž by dal tobě Hospodin Bůh tvůj.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 54, 'Člověk mezi vámi rozmazaný a v rozkoši schovaný záviděti bude bratru svému, i vlastní ženě své, i ostatním synům svým, kterýchž ještě zanechal,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 55, 'Tak že neudělí žádnému z nich masa synů svých, kteréž jísti bude, proto že nezůstalo jemu nic jiného v obležení a v ssoužení, jímž ssouží tě nepřítel tvůj ve všech městech tvých.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 56, 'Rozmazaná mezi vámi a v rozkoši schovaná žena, kteráž rozmazaností a rozkoší velikou ledva nohou země se dotkla, vlastnímu muži svému a synu svému i dceři své,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 57, 'Také i lůžka svého, kteréž z ní vychází při porodu, ano i synů svých, kteréž zplodí, záviděti bude; nebo jísti je bude tajně pro nedostatek všech věcí v obležení a ssoužení, jímž ssouží tě nepřítel tvůj v městech tvých.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 58, 'Nebudeš-li ostříhati a činiti všech slov zákona tohoto, kteráž psána jsou v knize této, abys se bál toho veleslavného a hrozného jména Hospodina Boha svého:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 59, 'Rozmnoží ku podivení Hospodin rány tvé, a rány semene tvého, rány veliké a trvánlivé, i nemoci těžké a dlouhé.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 60, 'A obrátí na tebe všecky neduhy Egyptské, jichžs se strašil, a přichytí se tebe.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 61, 'Všelijaký také neduh a všelikou ránu, kteráž není psána v knize zákona tohoto, uvede Hospodin na tebe, dokudž nebudeš vyhlazen.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 62, 'A zůstane vás maličko, ješto vás prvé bylo mnoho, jako hvězd nebeských, proto že jsi neposlouchal hlasu Hospodina Boha svého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 63, 'I stane se, že jakož se veselil Hospodin nad vámi, dobře vám čině a rozmnožuje vás, tak veseliti se bude Hospodin nad vámi, když vás zkazí a vyhladí, a vypléněni budete z země, do kteréž jdete, abyste dědičně vládli jí.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 64, 'A rozptýlí tě Hospodin mezi všecky národy, od jednoho konce země až do druhého, a budeš tam sloužiti bohům cizím, kterýchž ty neznáš, ani otcové tvoji, dřevu a kameni.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 65, 'A mezi národy těmi neoddechneš, aniž bude míti odpočinutí spodek nohy tvé; tam také dá Hospodin tobě srdce lekavé, a oči blíkavé, a truchlost mysli.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 66, 'I bude život tvůj nejistý před tebou, a strašiti se budeš v noci i ve dne, a nikdež nebudeš jist svým životem.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 67, 'Ráno díš: Ó by již byl večer! a večer díš: Ó by již bylo jitro! pro strach srdce svého, jímž se lekáš, a pro ty věci, na něž očima svýma hleděti musíš.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 68, 'A zavede tě Hospodin do Egypta na lodech, cestou, o níž jsem řekl tobě: Nebudeš jí viděti více; a tam prodávati se budete nepřátelům svým za služebníky a děvky, a nebude, kdo by koupil.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 1, 'Tato jsou slova smlouvy, kteráž přikázal Hospodin Mojžíšovi učiniti s syny Izraelskými v zemi Moábské, mimo onu smlouvu, kterouž učinil s nimi na Orébě.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 2, 'I svolav Mojžíš všecken lid Izraelský, řekl jim: Vy sami viděli jste všecky věci, kteréž učinil Hospodin před očima vašima v zemi Egyptské, Faraonovi, i všechněm služebníkům jeho, i vší zemi jeho,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 3, 'Zkušování veliká, kteráž viděly oči tvé, znamení i zázraky ty veliké.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 4, 'A však nedal vám Hospodin srdce k srozumění, a očí k vidění, a uší k slyšení až do tohoto dne.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 5, 'A vedl jsem vás čtyřidceti let po poušti, nezvetšela roucha vaše na vás, a obuv vaše neztrhala se na nohách vašich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 6, 'Chleba jste nejedli, vína a nápoje opojného jste nepili, abyste poznali, že já jsem Hospodin Bůh váš.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 7, 'A když jste přišli na toto místo, vytáhl Seon, král Ezebon, a Og, král Bázan, proti nám k boji, a porazili jsme je,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 8, 'A vzali jsme zemi jejich, i dali jsme ji v dědictví pokolení Rubenovu a Gádovu, a polovici pokolení Manassesova.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 9, 'Ostříhejtež tedy slov smlouvy této a čiňte je, aby se vám šťastně vedlo všecko, což byste činili.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 10, 'Vy všickni dnes stojíte před Hospodinem Bohem svým, knížata vaše v pokoleních vašich, starší vaši a úředníci vaši, všickni muži Izraelští,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 11, 'Dítky vaše i ženy vaše, i příchozí vaši, kteříž bydlejí u prostřed stanů vašich, i ten, kterýž dříví seká, i ten, kterýž váží vodu,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 12, 'Abyste vešli v smlouvu Hospodina Boha svého, a v přísahu jeho, v kteroužto smlouvu Hospodin Bůh tvůj dnes vchází s tebou,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 13, 'Aby tě sobě dnes postavil za lid, a on byl tobě za Boha, jakož mluvil tobě, a jakož s přísahou zaslíbil otcům tvým, Abrahamovi, Izákovi a Jákobovi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 14, 'A ne s vámi samými činím smlouvu tuto a přísahu tuto,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 15, 'Ale i s každým tím, jenž tuto dnes s námi stojí před Hospodinem Bohem naším, i s tím, jehož není tuto dnes s námi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 16, 'Nebo vy víte, kterak jsme bydlili v zemi Egyptské, a kterak jsme šli prostředkem těch národů, až jsme naskrze prošli.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 17, 'A viděli jste ohavnosti jejich i modly jejich, dřevo i kámen, stříbro i zlato, kteréž jest při nich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 18, 'Hleďtež, ať nebývá mezi vámi muže, aneb ženy, aneb čeledi, aneb pokolení, jehož by srdce odvrátilo se dnes od Hospodina Boha našeho, a šel by sloužiti bohům těch národů; ať nebývá mezi vámi kořene plodícího jed a hořkost.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 19, 'I stalo by se, že uslyše takový slova zlořečení tohoto, dobrořečil by sobě v srdci svém, řka: Pokoj míti budu, bychť pak i chodil podlé žádosti srdce svého; i přidal by opilou žíznivé.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 20, 'Nechceť Hospodin odpustiti takovému, nebo tehdáž rozpálí se prchlivost Hospodinova a zůřivost jeho proti takovému člověku, tak že připadne na něj všeliké zlořečení, o kterémž psáno jest v knize této; i vyhladí Hospodin jméno jeho pod nebem.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 21, 'A odloučí jej Hospodin s jeho zlým ode všech pokolení Izraelských, vedlé všech zlořečení smlouvy zapsané v této knize zákona,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 22, 'Tak že řekne věk potomní, synové vaši, kteříž povstanou po vás, i cizozemec, kterýž přijde z země daleké, (když uzří rány země této, i neduhy její, kteréž uvedl na ni Hospodin,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 23, 'Sirou a solí vypálenou všecku tu zemi, a že se nemůž síti, ani co vzcházeti, ani jaké byliny růsti na ní, rovně jako na místě, kdež jest podvrácena Sodoma a Gomora, Adama a Seboim, kteréž podvrátil Hospodin v hněvě svém a v prchlivosti své,)');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 24, 'Řeknou všickni národové: Proč jest tak učinil Hospodin zemi této? Kteraký jest to hněv prchlivosti jeho náramné?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 25, 'A bude odpovědíno: Proto že opustili smlouvu Hospodina Boha otců svých, kterouž učinil s nimi, když je vyvedl z země Egyptské.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 26, 'Nebo odcházejíce, sloužili bohům cizím a klaněli se jim, bohům, kterýchž neznali, kteříž se s nimi také ničímž dobrým nezdělili.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 27, 'I rozhněvala se prchlivost Hospodinova na tu zemi, tak že uvedl na ni všecko zlořečení zapsané v knize této.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 28, 'Protož vyplénil je Hospodin z země jejich v hněvě, v rozpálení a v prchlivosti veliké, a vyvrhl je do země jiné, jakž to ukazuje dnešní den.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 29, 'Věci skryté jsou Hospodina Boha našeho, věci pak zjevené ty jsou naše a synů našich, abychom plnili všecka slova zákona tohoto.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 1, 'Když pak přijdou na tě všecka slova tato, požehnání i zlořečenství, kterážť jsem předložil, a rozpomeneš se v srdci svém, kdež bys koli byl mezi národy, do kterýchž by tě rozehnal Hospodin Bůh tvůj,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 2, 'A obrátě se k Hospodinu Bohu svému, poslouchal bys hlasu jeho ve všem, jakž já přikazuji tobě dnes, ty i synové tvoji, z celého srdce svého a ze vší duše své:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 3, 'Tehdy přivede zase Hospodin Bůh tvůj zajaté tvé a smiluje se nad tebou, a obrátě se, shromáždí tě ze všech národů, mezi něž rozptýlil tě Hospodin Bůh tvůj.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 4, 'Byť pak někdo z tvých i na konec světa zahnán byl, odtud zase shromáždí tě Hospodin Bůh tvůj, a odtud půjme tě,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 5, 'A uvede tě zase Hospodin Bůh tvůj do země, kterouž dědičně vládli otcové tvoji, a opanuješ ji, a dobřeť učiní a rozmnoží tě více nežli otce tvé.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 6, 'A obřeže Hospodin Bůh tvůj srdce tvé a srdce semene tvého, abys miloval Hospodina Boha svého z celého srdce svého, a ze vší duše své, abys živ byl.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 7, 'Všecka pak zlořečenství tato obrátí Hospodin Bůh tvůj na nepřátely tvé a na ty, jenž v nenávisti měli tebe, a protivili se tobě.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 8, 'Ty tedy obrátě se, když poslouchati budeš hlasu Hospodina Boha svého, a činiti všecka přikázaní jeho, kteráž já tobě dnes přikazuji:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 9, 'Dáť Hospodin Bůh tvůj prospěch při všem díle rukou tvých, v plodu života tvého i v plodu dobytka tvého, a v úrodách země tvé, tobě k dobrému. Nebo zase veseliti se bude Hospodin z tebe, dobře čině tobě, jakož veselil se z otců tvých,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 10, 'Jestliže bys však poslouchal hlasu Hospodina Boha svého, a ostříhal přikázaní jeho a ustanovení jeho, napsaných v knize zákona tohoto, když bys se obrátil k Hospodinu Bohu svému celým srdcem svým a celou duší svou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 11, 'Nebo přikázaní toto, kteréž přikazuji tobě dnes, není skryté před tebou, ani vzdálené od tebe.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 12, 'Není na nebi, abys řekl: Kdo nám vstoupí do nebe, aby vezma, přinesl a oznámil je nám, abychom je plnili?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 13, 'Ani za mořem jest, abys řekl: Kdo se nám přeplaví za moře, aby je přinesl a oznámil nám, abychom plnili je?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 14, 'Ale velmi blízko tebe jest slovo, v ústech tvých a v srdci tvém, abys činil to:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 15, '(Hle, předložil jsem tobě dnes život a dobré, smrt i zlé,)');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 16, 'Což já přikazuji tobě dnes, abys miloval Hospodina Boha svého, chodě po cestách jeho a ostříhaje přikázaní jeho, ustanovení a soudů jeho, abys živ jsa, rozmnožen byl, a požehnal tobě Hospodin Bůh tvůj v zemi, do kteréž jdeš, abys ji dědičně obdržel.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 17, 'Pakli se odvrátí srdce tvé, a nebudeš poslouchati, ale přiveden jsa k tomu, klaněti se budeš bohům cizím a jim sloužiti:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 18, 'Ohlašuji vám dnes, že jistotně zahynete, aniž prodlíte dnů svých v zemi, do kteréž se přes Jordán béřeš, abys ji dědičně obdržel.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 19, 'Osvědčuji proti tobě dnes nebem a zemí, žeť jsem život i smrt předložil, požehnání i zlořečenství; vyvoliž sobě tedy život, abys živ byl ty i símě tvé,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 20, 'A miloval Hospodina Boha svého, poslouchaje hlasu jeho a přídrže se jeho, (nebo on jest život tvůj, a dlouhost dnů tvých), abys bydlil v zemi, kterouž s přísahou zaslíbil Hospodin otcům tvým Abrahamovi, Izákovi a Jákobovi, že jim ji dá.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 1, 'Přišed tedy Mojžíš, mluvil slova ta ke všemu Izraelovi,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 2, 'A řekl jim: Ve stu a ve dvadcíti letech jsem dnes, nemohuť již více vycházeti a vcházeti; a také řekl Hospodin ke mně: Nepřejdeš Jordánu tohoto.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 3, 'Hospodin Bůh tvůj předcházející tebe vyhladí ty národy od tváři tvé, a ty dědičně je opanuješ, a Jozue tento půjde před tebou, jakož řekl Hospodin.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 4, 'I učiní Hospodin jim, jakož učinil Seonovi a Ogovi králům Amorejským a zemi jejich, kteréž vyhladil.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 5, 'Protož když je dá Hospodin vám, tedy učiníte jim vedlé každého přikázaní, kteréž jsem přikázal vám.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 6, 'Buďte silní a zmužile se mějte, nebojte se, ani se lekejte tváři jejich, nebo Hospodin Bůh tvůj, on jde s tebou, neopustíť a nezanechá tebe.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 7, 'Tedy povolal Mojžíš Jozue a řekl jemu před očima všeho Izraele: Budiž silný a zmužile se měj, nebo ty vejdeš s lidem tímto do země, kterouž s přísahou zaslíbil Hospodin otcům jejich, že ji dá jim, a ty ji rozdělíš jim v dědictví.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 8, 'Hospodin pak předcházející tě, onť bude s tebou, neopustí tě, aniž tě zanechá; neboj se, ani se strachuj.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 9, 'I napsal Mojžíš zákon tento a dal jej kněžím, synům Léví, kteříž nosili truhlu smlouvy Hospodinovy, a všechněm starším Izraelským.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 10, 'A přikázal jim Mojžíš, řka: Každého léta sedmého, v jistý čas léta odpuštění, v svátek stanů,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 11, 'Když přijde všecken Izrael a postaví se před Hospodinem Bohem tvým na místě, kteréž by vyvolil, čísti budeš zákon tento přede vším Izraelem v uších jejich,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 12, 'Shromáždě lid, muže i ženy, i děti, i příchozí své, kteříž jsou v branách tvých, aby slyšíce, učili se a báli se Hospodina Boha vašeho, a hleděli činiti všecka slova zákona tohoto.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 13, 'Synové také jejich, kteříž ještě toho nepoznali, ať slyší a učí se báti Hospodina Boha vašeho po všecky dny, v nichž živi budete na zemi, do níž, přejdouce Jordán, vejdete, abyste ji dědičně obdrželi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 14, 'I řekl Hospodin Mojžíšovi: Aj, již se přiblížili dnové tvoji, abys umřel. Povolej Jozue, a postavte se oba v stánku úmluvy, a přikáži jemu. Šel tedy Mojžíš a Jozue, a postavili se v stánku úmluvy.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 15, 'I ukázal se Hospodin v stánku v sloupě oblakovém, a postavil se sloup oblakový nade dveřmi stánku.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 16, 'Řekl pak Hospodin Mojžíšovi: Aj, ty již usneš s otci svými, potom lid tento vstana, smilniti bude, následuje bohů cizozemců země této, do níž vchází, aby bydlil u prostřed ní; tu mne opustí a zruší smlouvu mou, kterouž jsem učinil s ním.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 17, 'Protož rozhněvá se na něj prchlivost má v ten den, a opustím je, i skryji tvář svou od nich, a bude sežrán, i přijdou na něj mnohé věci zlé a úzkosti. I řekne v ten den: Zdaliž ne proto přišly na mne tyto zlé věci, že Bůh můj není u prostřed mne?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 18, 'Já pak daleko skryji tvář svou v ten den pro všecko to zlé, kteréž páchal, jakž se obrátil k bohům cizím.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 19, 'Protož nyní napište sobě píseň tuto, a uč jí syny Izraelské; vlož ji v ústa jejich, aby ta píseň byla mi za svědka proti synům Izraelským.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 20, 'Nebo uvedu jej do země, kterouž jsem s přísahou zaslíbil otcům jeho, oplývající mlékem a strdí, kdežto bude jísti a nasytí se a ztuční. Tehdy obrátí se k bohům cizím a sloužiti bude jim, i popudí mne a zruší smlouvu mou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 21, 'A když přijdou na něj mnohé zlé věci a úzkosti, tehdy bude jemu tato píseň na svědectví, (nebo nepřijde v zapomenutí, aniž odejde od úst semene jeho). Známť zajisté myšlení jeho, a co on ještě dnes činiti bude, prvé nežli jej uvedu do země, kterouž jsem s přísahou zaslíbil.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 22, 'Tedy napsal Mojžíš tu píseň v ten den a učil jí syny Izraelské.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 23, 'Potom dal přikázaní Jozue, synu Nun, řka: Budiž silný, a měj se zmužile, nebo ty uvedeš syny Izraelské do země, kterouž jsem jim s přísahou zaslíbil, a já budu s tebou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 24, 'Stalo se pak, když napsal Mojžíš slova zákona tohoto v knize, a dokonal je,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 25, 'Že přikázal Levítům, kteříž nosili truhlu smlouvy Hospodinovy, řka:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 26, 'Vezměte tu knihu zákona a vložte ji v straně truhly smlouvy Hospodina Boha vašeho, ať jest tam proti vám na svědectví.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 27, 'Nebo já znám zpouru tvou a zatvrdilost šíje tvé. Aj, poněvadž, když jsem já ještě živ nyní s vámi, zpurní jste bývali Hospodinu, čím tedy více, když já umru?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 28, 'Shromažďte ke mně všecky starší pokolení svých a správce vaše, abych mluvil v uši jejich slova tato, a osvědčil proti nim nebem i zemí.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 29, 'Nebo vím, že po mé smrti velmi porušíte se a vystoupíte z cesty, kterouž jsem přikázal vám; pročež přijde na vás toto zlé v posledních dnech, když byste činili to, což se nelíbí Hospodinu, popouzejíce ho dílem rukou svých.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 30, 'Mluvil tedy Mojžíš v uši všeho shromáždění Izraelského slova písně této, až je i dokonal.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 1, 'Pozorujte nebesa a mluviti budu, poslyš i země výmluvností úst mých.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 2, 'Sstupiž jako déšť naučení mé, spadniž jako rosa výmluvnost má, jako tichý déšť na mladistvou trávu, a jako příval na odrostlou bylinu,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 3, 'Nebo jméno Hospodinovo slaviti budu. Vzdejtež velebnost Bohu našemu,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 4, 'Skále té, jejíž skutkové jsou dokonalí, nebo všecky cesty jeho jsou spravedlivé. Bůh silný, pravdomluvný, a není nepravosti v něm, spravedlivý a přímý jest.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 5, 'Ale pokolení převrácené a zavilé zpronevěřilo se jemu mrzkostí vlastní svou, jakáž vzdálena jest od synů jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 6, 'Tím-liž jste se odplacovati měli Hospodinu, lide bláznivý a nemoudrý? Zdaliž on není otec tvůj, kterýž tě sobě dobyl? On učinil tebe a utvrdil tě.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 7, 'Rozpomeň se na dny staré, považte let každého věku; vzeptej se otce svého, a oznámí tobě, starců svých, a povědí tobě.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 8, 'Když dědictví rozděloval Nejvyšší národům, když rozsadil syny Adamovy, rozměřil meze národům vedlé počtu synů Izraelských.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 9, 'Nebo díl Hospodinův jest lid jeho, Jákob provazec dědictví jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 10, 'Nalezl jej v zemi pusté, a na poušti veliké a hrozné; vůkol vedl jej, vyučil jej, a ostříhal ho, jako zřítedlnice oka svého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 11, 'Jako orlice ponouká orličátek svých, sedí na mladých svých, roztahuje křídla svá, béře je, a nosí je na křídlách svých:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 12, 'Tak Hospodin sám vedl jej, a nebylo s ním boha cizozemců.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 13, 'Zprovodil jej na vysoká místa země, aby jedl úrody polní, a učinil, aby ssál med z skály, a olej z kamene přetvrdého,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 14, 'Máslo od krav a mléko od ovcí, s nejtučnějšími beránky a skopci z Bázan a kozly s jádrem zrn pšeničných, a červené víno výborné aby pil.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 15, 'Takž Izrael ztučněv, zpíčil se; vytyl jsi a ztlustl, tukem jsi obrostl; i opustil Boha stvořitele svého, a zlehčil sobě Boha spasení svého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 16, 'K horlení popudili ho cizími bohy, ohavnostmi zdráždili jej.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 17, 'Obětovali ďáblům, ne Bohu, bohům, jichž neznali, novým, kteříž z blízka přišli, jichžto se nic nestrašili otcové vaši.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 18, 'Na skálu, kteráž zplodila tě, zapomenul jsi; zapomněl jsi na Boha silného, stvořitele svého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 19, 'To když viděl Hospodin, popudil se hněvem proti synům a dcerám svým,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 20, 'A řekl: Skryji před nimi tvář svou, podívám se posledním věcem jejich; nebo národ převrácený jest, synové, v nichž není žádné víry.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 21, 'Oniť jsou mne popudili k horlení skrze to, což není Bůh silný, rozhněvali mne svými marnostmi. I jáť popudím jich k závisti skrze ty, kteříž nejsou lid, skrze národ bláznivý k hněvu jich popudím.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 22, 'Nebo oheň zápalen jest v prchlivosti mé, a hořeti bude až do nejhlubšího pekla, a sžíře zemi i úrody její, a zapálí základy hor.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 23, 'Shromáždím na ně zlé věci, střely své vystřílím na ně.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 24, 'Hladem usvadnou, a neduhy pálčivými a nakažením morním přehořkým žráni budou; také zuby šelm pošli na ně s jedem hadů zemských.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 25, 'Meč uvede sirobu vně, a v pokojích bude strach, tak na mládenci jako panně, dítěti prsí požívajícím i muži šedivém.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 26, 'Ano, řekl bych: Rozptýlím je po koutech, rozkáži přestati mezi lidmi paměti jejich,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 27, 'Bych se pýchy nepřítele neobával, aby spatříce to nepřátelé jejich, neřekli: Ruka naše nepřemožená byla, neučinilť jest Hospodin ničeho z těch věcí.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 28, 'Nebo národ ten nesmyslný jest a nemající rozumnosti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 29, 'Ó by moudří byli, rozuměliť by tomu, prohlédali by na poslední věci své.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 30, 'Jak by jich jeden honiti mohl tisíc, a dva pryč zahnati deset tisíců? Jediné že Bůh skála jejich prodal je, a Hospodin vydal je.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 31, 'Nebo Bůh skála naše není jako skála jejich, což nepřátelé naši sami souditi mohou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 32, 'Nebo z kmene Sodomského kmen jejich, a z réví Gomorských hroznové jejich, hroznové jedovatí, zrní hořkosti plné.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 33, 'Jed draků víno jejich, a jed lítý nejjedovatějšího hada.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 34, 'Zdaliž to není schováno u mne? zapečetěno v pokladnicích mých?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 35, 'Máť jest pomsta a odplata, časemť svým klesne noha jejich; nebo blízko jest den zahynutí jejich, a budoucí věci zlé rychle připadnou na ně.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 36, 'Souditi zajisté bude Hospodin lid svůj, a nad služebníky svými lítost míti bude, když uzří, že odešla síla, a že jakož zajatý tak i zanechaný s nic býti nemůže.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 37, 'I dí: Kde jsou bohové jejich? skála, v níž naději měli?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 38, 'Z jejichžto obětí tuk jídali, a víno z obětí jejich mokrých píjeli? Nechať vstanou a spomohou vám, nechť vám skrejší jest skála ta.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 39, 'Pohleďtež již aspoň, že já jsem, já jsem sám, a že není Boha kromě mne. Já mohu usmrtiti i obživiti, já raniti i uzdraviti, a není žádného, kdo by vytrhl z ruky mé.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 40, 'Nebo já pozdvihám k nebi ruky své, a pravím: Živ jsem já na věky.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 41, 'Jakž nabrousím ostří meče svého, a uchopí soud ruka má, učiním pomstu nad nepřátely svými, a těm, jenž v nenávisti mne měli, odplatím.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 42, 'Opojím střely své krví, a meč můj sžere maso, a to krví raněných a zajatých, jakž jen začnu pomsty uvoditi na nepřátely.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 43, 'Veselte se pohané s lidem jeho, neboť pomstí krve služebníků svých, a uvede pomstu na nepřátely své, a očistí zemi svou a lid svůj.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 44, 'I přišel Mojžíš, a mluvil všecka slova písně této v uši lidu, on a Jozue, syn Nun.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 45, 'A když dokonal Mojžíš mluvení všech slov těch ke všemu množství Izraelskému,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 46, 'Řekl jim: Přiložtež srdce svá ke všechněm slovům, kteráž já dnes osvědčuji vám, a přikažte to synům svým, aby ostříhali všech slov zákona tohoto, a činili je.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 47, 'Nebo není daremné slovo, abyste jím pohrdnouti měli, ale jest život váš; a v slovu tom prodlíte dnů svých na zemi, kterouž abyste dědičně obdrželi, půjdete přes Jordán.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 48, 'Téhož dne mluvil Hospodin k Mojžíšovi, řka:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 49, 'Vstup na horu tuto Abarim, na vrch Nébo, kteráž jest v zemi Moábské naproti Jerichu, a spatř zemi Kananejskou, kterouž já dávám synům Izraelským právem dědičným.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 50, 'A umřeš na vrchu, na kterýž vejdeš, a připojen budeš k lidu svému, jako umřel Aron, bratr tvůj, na hoře řečené Hor, a připojen jest k lidu svému.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 51, 'Nebo jste zhřešili proti mně u prostřed synů Izraelských, při vodách odpírání v Kádes, na poušti Tsin, proto že jste neposvětili mne u prostřed synů Izraelských.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 52, 'Před sebou zajisté uzříš zemi tu, ale tam nevejdeš do země té, kterouž dávám synům Izraelským.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 1, 'Toto pak jest požehnání, kterýmž požehnal Mojžíš, muž Boží, synů Izraelských před svou smrtí,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 2, 'A řekl: Hospodin z Sinai přišel, a vzešel jim z Seir, zastkvěl se s hory Fáran, a přišel s desíti tisíci svatých, z jehožto pravice oheň zákona svítil jim.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 3, 'Jak velice miluješ lidi! Všickni svatí jeho jsou v ruce tvé, oni také přivinuli se k nohám tvým, vezmouť prospěch z výmluvností tvých.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 4, 'Zákon vydal nám Mojžíš, dědičný shromáždění Jákobovu,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 5, '(Nebo byl v Izraeli jako král,) když přední z lidu shromáždili se, i všecka pokolení Izraelská.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 6, 'Buď živ Ruben a neumírej, a muži jeho ať jsou bez počtu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 7, 'Tolikéž požehnal i Judovi a řekl: Vyslyš, Hospodine, hlas Judův, a k lidu svému jej sprovozuj; ruce jeho budou bojovati za něj, a ty jemu spomáhati budeš proti nepřátelům jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 8, 'O Léví také řekl: Thumim tvé a urim tvé bylo, Pane, při muži svatém tvém, kteréhož jsi zkusil v pokušení, a kterýž podlé tebe měl nesnáz při vodách Meribah,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 9, 'Kterýž řekl otci svému a matce své: Neohlédám se na vás; a bratří svých neznal, a o synech svých nevěděl; nebo ostříhají výmluvností tvých, a smlouvu tvou zachovávají.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 10, 'Vyučovati budou soudům tvým Jákoba, a zákonu tvému Izraele, a klásti budou kadidlo před tváří tvou, a obět zápalnou na oltáři tvém.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 11, 'Požehnejž, Hospodine, rytěřování jeho, a v práci rukou jeho zalib se tobě. Zlomuj ledví nepřátel jeho a těch, kteříž ho nenávidí, aby nepovstali.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 12, 'A o Beniaminovi řekl: Milý jest Hospodinu, bezpečně s ním bydliti bude; ochraňovati jej bude každého dne, a mezi rameny jeho přebývati.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 13, 'O Jozefovi pak řekl: Požehnaná země jeho od Hospodina pro nejlepší věci nebeské, pro rosu a vrchoviště zespod se prýštící,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 14, 'A pro nejlepší úrody sluncem vyzralé, a pro nejlepší věci časem měsíců došlé,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 15, 'I pro rozkoše hor nejstarších, a pro rozkoše pahrbků věčných,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 16, 'Pro nejlepší věci země i plnost její, vyplývající z milosti ve kři přebývajícího. Přijdiž to požehnání na hlavu Jozefovu, a na vrch hlavy odděleného z jiných bratří jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 17, 'Prvorozeného, vola toho krása veliká bude, a rohové jednorožce rohové jeho, jimiž on trkati bude národy napořád až do končin země. A toť jsou mnozí tisícové Efraimovi a tisícové Manassesovi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 18, 'O Zabulonovi také řekl: Vesel se Zabulon u vycházení svém, a Izachar v staních svých.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 19, 'Lidi na horu Boží svolají, a budou obětovati oběti spravedlnosti; nebo hojnost mořskou ssáti budou, a skryté poklady v písku.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 20, 'Gádovi pak řekl: Požehnaný, kterýž rozšiřuje Gáda. Onť jakožto lev bydliti bude, a uchvátí rameno i s hlavou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 21, 'Kterýž opatřil ho prvotinami; nebo tam podílem skrze vydavatele zákona ubezpečen jest. Protož pobéřeť se s knížaty lidu, a spravedlnost Hospodinovu i soudy jeho s Izraelem vykonávati bude.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 22, 'O Danovi pak řekl: Dan jako lvíče lvové vyskakovati bude z Bázan.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 23, 'A Neftalímovi řekl: Ó Neftalíme, sytý přízní Páně, plný požehnání Hospodinova, západní a polední stranu přijmi za dědictví.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 24, 'O Asserovi také řekl: Asser požehnaný nad jiné syny, budeť milý bratřím svým, omočí v oleji nohu svou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 25, 'Železo a měď pod šlepějemi tvými; pokudž trvati budou dnové tvoji, slovoutný budeš.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 26, 'Neníť žádného, jako Bůh silný, ó Izraeli, kterýž se vznáší na nebesích ku pomoci tobě, a u velebnosti své na oblacích nejvyšších.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 27, 'Ochrana tvá buď Bůh věčný, a zespod ramena věčnosti, kterýž vyžene nepřátely před tebou, aneb řekne: Vyhlaď je,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 28, 'Aby sám bezpečně bydlil Izrael, rodina Jákobova, a to v zemi obilím a vínem oplývající, jehož nebesa také i rosu vydávati budou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 29, 'Blahoslavený jsi, Izraeli. Kdo jest podobný tobě, lide vysvobozený skrze Hospodina, jenž jest pavéza spomožení tvého a meč důstojnosti tvé? Tvoji zajisté nepřátelé poníženi budou, ale ty po všech vyvýšenostech jejich šlapati budeš.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 34, 1, 'Tedy vstoupil Mojžíš z rovin Moábských na horu Nébo, na vrch hory, kteráž jest proti Jerichu, a ukázal jemu Hospodin všecku zemi Galád až do Dan,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 34, 2, 'I všecku Neftalím, a zemi Efraim a Manasse, a všecku zemi Juda až k moři nejdalšímu,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 34, 3, 'Polední také stranu a roviny údolí Jericha, města palmovím osazeného, až do Segor.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 34, 4, 'A řekl jemu Hospodin: Tato jest země, kterouž s přísahou zaslíbil jsem Abrahamovi, Izákovi a Jákobovi, řka: Semeni tvému dám ji. Způsobil jsem to, abys ji viděl očima svýma, však do ní nevejdeš.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 34, 5, 'I umřel tam Mojžíš, služebník Hospodinův, v zemi Moábské, vedlé řeči Hospodinovy.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 34, 6, 'A pochoval jej v Gai, v zemi Moábské naproti Betfegor, a žádný nezvěděl o jeho hrobu až do tohoto dne.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 34, 7, 'Byl pak Mojžíš ve stu a dvadcíti letech, když umřel, a nepošly oči jeho, aniž síla odešla od něho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 34, 8, 'I plakali synové Izraelští Mojžíše na rovinách Moábských třidceti dní, a vyplněni jsou dnové pláče a kvílení nad Mojžíšem.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 34, 9, 'Jozue pak, syn Nun, naplněn jest duchem moudrosti; nebo byl vložil Mojžíš ruce své na něj. I poslouchali ho synové Izraelští, a činili, jakož přikázal Hospodin skrze Mojžíše.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 34, 10, 'Ale nepovstal více prorok v Izraeli podobný Mojžíšovi, (kteréhož by tak znal Hospodin tváří v tvář,)');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 34, 11, 'Ve všech znameních a zázracích, pro něž poslal jej Hospodin, aby činil je v zemi Egyptské, před Faraonem a přede všechněmi služebníky jeho, a vší zemí jeho,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 34, 12, 'Také i ve všech skutcích ruky silné, a ve všeliké hrůzi veliké, kteréžto věci činil Mojžíš před očima všeho Izraele.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 1, 'Stalo se pak po smrti Mojžíše, služebníka Hospodinova, že mluvil Hospodin k Jozue, synu Nun, služebníku Mojžíšovu, řka:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 2, 'Mojžíš, služebník můj, umřel; protož nyní vstaň, přejdi Jordán tento, ty i všecken lid tento, a jdi do země, kterouž já dávám synům Izraelským.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 3, 'Každé místo, po kterémž šlapati budete nohama svýma, dal jsem vám, jakož jsem mluvil k Mojžíšovi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 4, 'Od pouště a Libánu toho až k řece veliké, řece Eufrates, všecka země Hetejská až do moře velikého na západ slunce bude pomezí vaše.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 5, 'Neostojí žádný před tebou po všecky dny života tvého; jakož jsem byl s Mojžíšem, tak budu s tebou; nenechám tebe samého, aniž tě opustím.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 6, 'Posilniž se a zmužile se měj, nebo ty uvedeš v dědictví lidu tomuto zemi, kterouž jsem s přísahou zaslíbil otcům jejich, že ji dám jim.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 7, 'Toliko posilň se a udatně sobě počínej, abys ostříhal a činil všecko podlé zákona, kterýž přikázal tobě Mojžíš, služebník můj; neuchyluj se od něho na pravo ani na levo, abys byl opatrný ve všem, k čemuž se obrátíš.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 8, 'Neodejdeť kniha zákona tohoto od úst tvých, ale přemyšlovati budeš o něm dnem i nocí, abys ostříhal a činil všecko podlé toho, což psáno jest v něm; nebo tehdáž šťastný budeš na cestách svých, a tehdáž opatrný budeš.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 9, 'Zdaliž jsem nepřikázal tobě, řka: Posilni se a zmužile se měj, neboj se, ani lekej, nebo s tebou jest Hospodin Bůh tvůj, kamž se koli obrátíš.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 10, 'Tedy přikázal Jozue správcům lidu, řka:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 11, 'Projděte skrze tábor a přikažte lidu, řkouce: Nachystejte sobě potravy, nebo po třech dnech půjdete přes Jordán tento, abyste vejdouce, opanovali zemi, kterouž Hospodin Bůh váš dává vám k dědičnému vládařství.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 12, 'Rubenovu pak pokolení a Gádovu, a polovici pokolení Manassesova mluvil Jozue, řka:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 13, 'Pomněte na to, co vám přikázal Mojžíš služebník Hospodinův, když řekl: Hospodin Bůh váš způsobil vám odpočinutí, že vám dal zemi tuto.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 14, 'Ženy vaše, dítky vaše i dobytek váš nechť zůstanou v zemi, kterouž dal vám Mojžíš s této strany Jordánu, vy pak jděte vojensky zpořádaní před bratřími svými, kteříkoli jste muži silní, a pomáhejte jim,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 15, 'Dokudž nedá odpočinutí Hospodin bratřím vašim jako i vám, a neobdrží dědičně také i oni země, kterouž Hospodin Bůh váš dává jim. Potom navrátíte se do země dědictví svého, kterouž dal vám Mojžíš, služebník Hospodinův, s této strany Jordánu, k východu slunce, a dědičně vlásti jí budete.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 16, 'I odpověděli k Jozue, řkouce: Všecko, což jsi nám rozkázal, učiníme, a kamžkoli pošleš nás, půjdeme.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 17, 'Rovně jakž jsme poslouchali Mojžíše, tak poslouchati budeme tebe; jediné nechť jest Hospodin Bůh tvůj s tebou, jako byl s Mojžíšem.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 18, 'Kdo by koli odporný byl rozkázaní tvému, a neposlouchal by řečí tvých ve všech věcech, kteréž bys přikázal jemu, umřeť; toliko posilň se a zmužile se měj.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 1, 'Poslal pak byl Jozue, syn Nun, z Setim dva muže špehéře tajně, řka: Jděte, shlédněte zemi, zvlášť Jericho. I šli a vešli do domu ženy nevěstky, jejíž jméno bylo Raab, a odpočinuli tu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 2, 'Ale jakž oznámeno bylo králi Jericha a povědíno: Aj, muži přišli sem této noci z synů Izraelských, aby shlédli zemi,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 3, 'Tedy poslal král Jericha k Raab, řka: Vyveď muže, kteříž přišli k tobě, a vešli do domu tvého, nebo k vyšpehování vší země přišli.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 4, '(Pojavši pak žena ty dva muže, skryla je.) Kteráž odpověděla: Pravda jest, přišliť jsou ke mně muži, ale nevěděla jsem, odkud jsou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 5, 'A když bránu zavírati měli v soumrak, vyšli muži ti, a nevím, kam jsou šli; hoňte je rychle, nebo dostihnete jich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 6, 'Ale ona rozkázala jim vstoupiti na střechu, a skryla je v pazdeří lněném, kteréž byla skladla na střeše.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 7, 'Muži pak vyslaní honili je cestou Jordánskou až k brodům; a zavřína jest brána, jakž vyšli ti, kteříž je honili.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 8, 'Prvé pak, než usnuli špehéři, vstoupila k nim ona na střechu,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 9, 'A řekla mužům těm: Vím, že Hospodin dal vám zemi tuto, nebo připadl na nás strach váš, tak že oslábli všickni obyvatelé země před tváří vaší.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 10, 'Slyšeli jsme zajisté, jak vysušil Hospodin vody moře Rudého před tváří vaší, když jste vyšli z Egypta, a co jste učinili dvěma králům Amorejským, kteříž byli za Jordánem, Seonovi a Ogovi, kteréž jste zahladili jako proklaté.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 11, 'Což když jsme uslyšeli, osláblo srdce naše, aniž zůstává více v kom duše před tváří vaší, nebo Hospodin Bůh váš jest Bůh na nebi svrchu, i na zemi dole.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 12, 'Nyní tedy, prosím, přisáhněte mi skrze Hospodina, poněvadž jsem učinila vám milosrdenství, že i vy učiníte s domem otce mého milosrdenství, a dáte mi znamení jisté,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 13, 'Že budete živiti otce mého i matku mou, bratří mé i sestry mé a všecko, cožkoli jejich jest, a vysvobodíte duše naše od smrti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 14, 'I řekli jí muži ti: Duše naše za vás nechť jsou na smrt; jestliže však nepronesete řeči naší této, takť se jistě stane, že když nám dá Hospodin zemi tuto, tehdy učiníme s tebou milosrdenství a pravdu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 15, 'Protož spustila je oknem po provazu; nebo dům její byl při zdi městské, a na zdi ona bydlila.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 16, 'I řekla jim: Jděte k této hoře, aby se nepotkali s vámi, kteříž vás honí, a krejte se tam za tři dni, až se oni zase navrátí, a potom půjdete cestou svou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 17, 'Tedy řekli muži k ní: Prosti budeme od této přísahy tvé, kterouž jsi zavázala nás,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 18, 'Jestliže, když vejdeme do země, neuvážeš provázku tohoto z nití hedbáví červeného dvakrát barveného v tomto okně, jímž jsi nás spustila, také otce svého a matky své, i bratří svých, a všeho domu otce svého neshromáždíš-li k sobě do domu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 19, 'Také kdo by vyšel ven ze dveří domu tvého, krev jeho bude na hlavu jeho, ale my budeme bez viny; a každého toho, kdož bude s tebou v domě, jestliže by se kdo rukou dotekl, krev jeho na hlavy naše připadni.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 20, 'Jestliže pak proneseš tuto řeč naši, budeme prosti od přísahy tvé, kterouž jsi nás zavázala.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 21, 'Odpověděla ona: Nechť jest tak, jakž jste řekli. I propustila je a odešli; i uvázala provázek z hedbáví červeného dvakrát barveného v tom okně.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 22, 'Odšedše pak, přišli na horu, a pobyli tam za tři dni, dokudž se nenavrátili, kteříž je honili; nebo jich hledali ti, kteříž je honili po všech cestách, ale nic nenalezli.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 23, 'Ti pak dva muži sšedše s hory, navrátili se a přeplavili se přes Jordán; i přišli k Jozue, synu Nun, a vypravovali jemu všecko, co se s nimi dálo.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 24, 'A řekli k Jozue: Dalť jest Hospodin v ruce naše všecku zemi, nebo se zděsili všickni obyvatelé země tváři naší.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 1, 'Vstal pak Jozue velmi ráno, a hnuvše se z Setim, přišli až k Jordánu, on i všickni synové Izraelští, a přenocovali tu, prvé nežli šli přes něj.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 2, 'I stalo se, že třetího dne správcové šli prostředkem stanů,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 3, 'A přikazovali lidu, řkouce: Když uzříte truhlu smlouvy Hospodina Boha svého a kněží Levítské, ani ji nesou, vy také hnete se s místa svého a půjdete za ní,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 4, '(A však místo mezi vámi a mezi ní bude okolo dvou tisíc loket míry obecné, nepřibližujte se k ní), abyste viděli cestu, kterouž byste jíti měli; nebo nešli jste tou cestou prvé.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 5, 'Řekl pak byl Jozue lidu: Posvěťtež se, zítra zajisté učiní Hospodin divné věci mezi vámi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 6, 'Potom řekl Jozue kněžím těmi slovy: Vezměte truhlu smlouvy, a jděte před lidem. I vzali truhlu smlouvy a brali se před lidem.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 7, 'Nebo řekl byl Hospodin k Jozue: V tento den začnu tebe zvelebovati před očima všeho Izraele, aby poznali, že jakož jsem byl s Mojžíšem, tak budu s tebou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 8, 'Protož ty přikaž kněžím, kteříž nosí truhlu smlouvy, a rci: Když vejdete na kraj vody Jordánské, zastavte se v Jordáně.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 9, 'Řekl také Jozue synům Izraelským: Přistupte sem, a slyšte slova Hospodina Boha vašeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 10, 'I řekl Jozue: Po tomto poznáte, že Bůh silný živý jest u prostřed vás, a že konečně vyžene od tváři vaší Kananejského, Hetejského, Hevejského, Ferezejského, Gergezejského, Amorejského a Jebuzejského:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 11, 'Aj, truhla smlouvy Panovníka vší země půjde před vámi přes Jordán.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 12, 'Protož nyní vezměte sobě dvanácte mužů z pokolení Izraelských, po jednom muži z každého pokolení.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 13, 'I bude, že hned jakž se zastaví kněží, nesoucí truhlu Hospodina Panovníka vší země, u vodě Jordánské, vody Jordánu rozdělí se, a vody tekoucí s vrchu zůstanou v jedné hromadě.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 14, 'Stalo se tedy, když se bral lid z stanů svých, aby šli přes Jordán, a kněží, kteříž nesli truhlu smlouvy, před nimi,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 15, 'A když ti, kteříž nesli truhlu, přišli až k Jordánu, a kněží, nesoucí truhlu, omočili nohy v kraji vod: (Jordán pak rozvodňuje se a vystupuje ze všech břehů svých v každý čas žně),');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 16, 'Že se zastavily vody, kteréž s hůry přicházely, a shrnuly se v hromadu jednu velmi daleko od Adam města, kteréž leží k straně Sartan, kteréž pak odcházely k moři dolů, k moři slanému sešly a sběhly, a lid přešel naproti Jerichu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 17, 'Stáli pak kněží, kteříž nesli truhlu smlouvy Hospodinovy na suše u prostřed Jordánu, nehýbajíce se, (a všecken Izrael šel po suše), až se lid všecken přepravil přes Jordán.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 1, 'I stalo se, když již všecken národ přešel Jordán, (nebo byl řekl Hospodin k Jozue, řka:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 2, 'Vezměte sobě z lidu dvanácte mužů, po jednom muži z každého pokolení,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 3, 'A přikažte jim, řkouce: Vezměte sobě odsud z prostřed Jordánu, s místa, na němž stály nohy kněžské nepohnutě, dvanácte kamenů, a vyneste je s sebou, a sklaďte v ležení, v kterémž přes tuto noc pozůstanete),');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 4, 'Že povolav Jozue dvanácti mužů, kteréž k tomu zřídil z synů Izraelských, po jednom muži z každého pokolení,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 5, 'I řekl jim Jozue: Jděte před truhlou Hospodina Boha svého do prostřed Jordánu a vezměte sobě každý kámen jeden na rameno své, vedlé počtu pokolení synů Izraelských,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 6, 'Aby to bylo na znamení mezi vámi. Když by potom tázali se synové otců svých, řkouce: K čemu jsou vám ti kamenové?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 7, 'Odpovíte jim, že se rozdělily vody Jordánské před truhlou smlouvy Hospodinovy, (když, pravím, šla přes Jordán, rozdělily se vody Jordánské), i zůstávají kamenové tito na památku synům Izraelským až na věky.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 8, 'I učinili synové Izraelští tak, jakž přikázal Jozue, a vzali dvanácte kamenů z prostředku Jordánu, jakož mluvil Hospodin k Jozue, vedlé počtu pokolení synů Izraelských, a přinesli je s sebou na první stanoviště, a tu je složili.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 9, 'Jozue také vyzdvihl dvanácte kamenů u prostřed Jordánu na místě, kdež stály nohy kněží nesoucích truhlu smlouvy, a byli tam až do tohoto dne.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 10, 'Kněží pak, jenž nesli truhlu, stáli u prostřed Jordánu, dokudž se nevyplnilo všeliké slovo, kteréž přikázal Hospodin Jozue, aby oznámil lidu podlé všeho, jakž byl přikázal Mojžíš Jozue. I pospíšil lid a přešli.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 11, 'Když pak již přešel všecken lid, přešla také truhla Hospodinova i kněží, an lid na to hledí.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 12, 'Přešli i synové Rubenovi a synové Gádovi, a polovice pokolení Manassesova, vojensky zpořádaní před syny Izraelskými, jakož byl mluvil k nim Mojžíš.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 13, 'Okolo čtyřidcíti tisíců oděných bojovníků šlo před Hospodinem k boji na roviny Jericha.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 14, 'V ten den zvelebil Hospodin Jozue před očima všeho Izraele. I báli se ho, jako se báli Mojžíše po všecky dny života jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 15, 'Mluvil pak Hospodin k Jozue, řka:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 16, 'Přikaž kněžím, kteříž nesou truhlu svědectví, ať vystoupí z Jordánu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 17, 'I přikázal Jozue kněžím, řka: Vystupte z Jordánu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 18, 'Když pak vystupovali kněží, jenž nesli truhlu smlouvy Hospodinovy, z prostřed Jordánu, jakž jen vytrhli kněží nohy na sucho, navrátily se vody Jordánské k místu svému, a tekly předce jako i prvé ve všech březích svých.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 19, 'Vyšed pak lid z Jordánu desátého dne měsíce prvního, položili se v Galgala k straně východní Jericha;');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 20, 'A dvanácte kamenů těch, kteréž vynesli z Jordánu, postavil Jozue v Galgala.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 21, 'A mluvil k synům Izraelským takto: Když by se otázali potom synové vaši otců svých, řkouce: Co ti kamenové znamenají?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 22, 'Oznámíte synům svým a díte: Po suše přešel Izrael Jordán tento.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 23, 'Nebo vysušil Hospodin Bůh váš vody Jordánské před tváří vaší, až jste přešli, jakož učinil Hospodin Bůh váš moři Rudému, kteréž vysušil před tváří naší, až jsme přešli,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 24, 'Aby poznali všickni národové země ruku Hospodinovu, že silná jest, a abyste se báli Hospodina Boha vašeho po všecky dny.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 5, 1, 'Stalo se pak, když uslyšeli všickni králové Amorejští, kteříž bydlili za Jordánem k západu, a všickni králové Kananejští, kteříž bydlili při moři, že vysušil Hospodin vody Jordánské před syny Izraelskými, dokudž ho nepřešli: zemdlelo srdce jejich, aniž zůstalo více v nich duše před tváří synů Izraelských.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 5, 2, 'Toho času řekl Hospodin k Jozue: Udělej sobě nože ostré, a obřež opět syny Izraelské po druhé.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 5, 3, 'I udělal sobě Jozue nože ostré, a obřezal syny Izraelské na pahrbku Aralot.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 5, 4, 'Tato pak jest příčina, pro kterouž je obřezal Jozue, že všecken lid, kterýž byl vyšel z Egypta, pohlaví mužského, všickni muži bojovní zemřeli byli na poušti na cestě po vyjití z Egypta.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 5, 5, 'Nebo obřezán byl všecken lid, kterýž byl vyšel, ale žádného z toho lidu, kterýž se zrodil na poušti, na cestě po vyjití z Egypta, neobřezali.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 5, 6, '(Nebo čtyřidceti let chodili synové Izraelští po poušti, dokudž nezahynul všecken národ mužů bojovných, kteříž byli vyšli z Egypta, ješto neposlouchali hlasu Hospodinova, jimžto zapřisáhl Hospodin, že neukáže jim země, kterouž s přísahou zaslíbil dáti otcům jejich, že ji nám dá, zemi oplývající mlékem a strdí.)');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 5, 7, 'Ale syny jejich, kteréž postavil na místo jejich, ty obřezal Jozue, že byli neobřezaní; nebo žádný jich neobřezoval na cestě.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 5, 8, 'Když pak byl všecken lid obřezán, zůstali na místě svém v ležení, dokudž se nezhojili.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 5, 9, 'I řekl Hospodin k Jozue: Dnes jsem odjal pohanění Egyptské od vás. A nazval jméno místa toho Galgal až do tohoto dne.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 5, 10, 'Když pak ležení měli synové Izraelští v Galgala, slavili velikunoc čtrnáctého dne toho měsíce u večer, na rovinách Jericha.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 5, 11, 'I jedli z úrod té země na zejtří po velikonoci chleby nekvašené, a pražmu téhož dne.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 5, 12, 'I přestala manna na zejtří, když jedli z obilé té země, a již více neměli synové Izraelští manny, ale jedli z úrod země Kananejské toho roku.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 5, 13, 'Stalo se pak, když byl Jozue na poli Jericha, že pozdvihl očí svých a viděl, an muž stojí naproti němu, maje v ruce meč dobytý. I šel Jozue k němu, a řekl jemu: Jsi-li náš, čili nepřátel našich?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 5, 14, 'I odpověděl: Nikoli, ale já jsem kníže vojska Hospodinova, a nyní jsem přišel. I padl Jozue tváří svou na zem, a pokloniv se, řekl jemu: Co pán můj chce mluviti služebníku svému?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 5, 15, 'Tedy odpověděl kníže vojska Hospodinova k Jozue: Szuj obuv svou s noh svých, nebo místo, na němž stojíš, svaté jest. I učinil tak Jozue.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 1, 'Jericho pak velmi pilně zavříno bylo pro strach synů Izraelských, a žádný nevycházel ven, ani tam nevcházel.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 2, 'I řekl Hospodin k Jozue: Aj, dal jsem v ruku tvou Jericho, a krále jeho s silnými muži jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 3, 'Protož obcházeti budete město všickni muži bojovní, okolo města chodíce, jednou za den; tak učiníš po šest dní.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 4, 'Kněží pak sedm ať nesou sedm trub z rohů beraních před truhlou; dne pak sedmého obejdete město sedmkrát, a kněží troubiti budou v trouby.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 5, 'A když zdlouha troubiti budou na roh beraní, jakž nejprvé uslyšíte hlas trouby, zkřikne všecken lid křikem velikým, i oboří se zed městská na místě svém, a vejde lid do města, jeden každý proti místu, kdež stál.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 6, 'Tedy povolav Jozue, syn Nun, kněží, řekl jim: Vezměte truhlu smlouvy, a sedm kněží ať vezmou sedm trub beraních před truhlou Hospodinovou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 7, 'Řekl také lidu: Jděte a obejděte město, a zbrojní ať jdou před truhlou Hospodinovou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 8, 'A když to oznámil Jozue lidu, sedm kněží, nesouce sedm trub beraních, šli před truhlou Hospodinovou, a troubili v trouby; truhla také smlouvy Hospodinovy brala se za nimi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 9, 'Zbrojní pak šli před kněžími, kteříž troubili na trouby, a ostatní šli za truhlou, jdouce a v trouby troubíce.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 10, '(Lidu pak byl přikázal Jozue, řka: Nebudete křičeti, ani slyšán bude hlas váš, ani vyjde slovo z úst vašich až do dne toho, v němž řeknu vám: Křičte, i budete křičeti.)');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 11, 'Tedy obešla truhla Hospodinova město vůkol jednou, a navrátili se do stanů a zůstali v nich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 12, 'Opět povstal Jozue ráno a kněží nesli truhlu Hospodinovu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 13, 'Sedm pak kněží, nesouce sedm trub beraních, předcházeli truhlu Hospodinovu, jdouce, a troubili v trouby; a zbrojní šli před nimi, a ostatní šli za truhlou Hospodinovou, když kněží šli, v trouby troubíce.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 14, 'I obešli město druhého dne opět, a navrátili se do stanů. Tak činili po šest dní.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 15, 'V den pak sedmý vstali, jakž zasvitávalo, a obešli město týmž způsobem sedmkrát; toliko toho dne obešli město sedmkrát.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 16, 'Stalo se pak, když po sedmé obcházeli, a kněží v trouby troubili, řekl Jozue lidu: Křičtež již, dalť jest Hospodin vám město.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 17, 'A budiž to město proklaté, ono i všecky věci, kteréž v něm jsou, Hospodinu; toliko Raab nevěstka ať jest živa, ona i všickni, kteříž by s ní byli v domě, nebo skryla posly, kteréž jsme byli poslali.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 18, 'Avšak vystříhejte se od proklatého, abyste i vy nebyli učiněni proklatí, berouce z proklatých věcí, a uvedli byste stany Izraelské v prokletí, a zkormoutili byste je.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 19, 'Všecko pak stříbro a zlato, a nádoby měděné a železné, svaté bude Hospodinu; na poklad Hospodinu složeno bude.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 20, 'Tedy křičel lid, když zatroubili v trouby. Nebo když slyšel lid hlas trub, křičeli i oni křikem velikým, i obořila se zed na místě svém. Tedy všel lid do města, jeden každý proti místu, kdež stál. I vzali je.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 21, 'A pohubili ostrostí meče jako proklaté všecko, což bylo v městě, od muže až do ženy, od dítěte až do starce, a až do vola, dobytčete i osla.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 22, 'Dvěma pak mužům, kteříž shlédli zemi, řekl Jozue: Vejděte do domu ženy nevěstky, a vyveďte ji odtud, i všecky věci, kteréž má, jakož jste jí přisáhli.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 23, 'I všedše mládenci špehéři, vyvedli Raab a otce jejího, i matku její a bratří její i všecko, což měla, a všecku rodinu její vyvedli, a nechali jich vně za stany Izraelskými.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 24, 'Město pak spálili ohněm, i všecko, což v něm bylo, stříbro však a zlato a nádoby měděné a železné složili na poklad v domě Hospodinově.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 25, 'Raab také nevěstku, a dům otce jejího i všecko, což měla, živé zůstavil Jozue; a bydlila v lidu Izraelském až do tohoto dne, nebo skryla posly, kteréž poslal Jozue k shlédnutí Jericha.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 26, 'Toho času vydal klatbu Jozue, řka: Zlořečený buď před Hospodinem muž ten, kterýž by povstal, aby stavěl město Jericho. V prvorozeném svém založí je, a v nejmenším postaví brány jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 27, 'Byl pak Hospodin s Jozue, a rozhlásila se pověst o něm po vší zemi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 1, 'Zhřešili pak synové Izraelští přestoupením při věcech proklatých; nebo Achan, syn Charmi, syna Zabdi, syna Záre, z pokolení Juda, vzal něco z věcí proklatých. Pročež rozpálila se prchlivost Hospodinova na syny Izraelské.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 2, 'Nebo když poslal Jozue muže některé od Jericha do Hai, kteréž bylo blízko Betaven, k východní straně Bethel, a mluvil k nim, řka: Vstupte a shlédněte zemi, vstoupili tedy muži ti, a shlédli Hai.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 3, 'Kteřížto navrátivše se k Jozue, řekli jemu: Nechť nevstupuje všecken lid tento, okolo dvou tisíc mužů neb okolo tří tisíců mužů nechť vstoupí, a dobudouť Hai; neobtěžuj všeho lidu, vysílaje jej tam, nebo málo jest oněchno.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 4, 'Tedy vytáhlo jich z lidu tam okolo tří tisíc mužů, a utekli před muži města Hai.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 5, 'I zabili z nich obyvatelé Hai okolo třidcíti a šesti mužů, a honili je od brány až k Sabarim, a porazili je, když s vrchu utíkali. I rozpustilo se srdce lidu, a bylo jako voda.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 6, 'Tedy Jozue roztrhl roucho své, a padl tváří svou na zem před truhlou Hospodinovou, a ležel až do večera, ano i starší Izraelští, a sypali prach na hlavy své.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 7, 'I řekl Jozue: Ach, Panovníče Hospodine, proč jsi kdy převedl lid tento přes Jordán, abys nás vydal v ruku Amorejského, tak aby nás zahubil? Ó kdybychom byli raději zůstali za Jordánem.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 8, 'Ó Pane, což mám říci, když již lid Izraelský utíká před nepřátely svými?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 9, 'Nebo uslyšíce Kananejští a všickni obyvatelé země, obklíčí nás vůkol, a vyhladí jméno naše z země. I což to učiníš jménu svému velikému?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 10, 'I řekl Hospodin k Jozue: Vstaň. Proč jsi padl na tvář svou?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 11, 'Zhřešil Izrael, tak že smlouvu mou přestoupili, kterouž jsem jim přikázal; nebo jsou i vzali z věcí proklatých, k tomu i ukradli, také i sklamali, nad to i odložili mezi nádobí svá.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 12, 'Protož nebudou moci synové Izraelští ostáti před nepřátely svými, utíkati budou před nepřátely svými, nebo poškvrnili se věcí proklatou. Nebuduť více s vámi, leč vyhladíte prokletí to z prostředku svého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 13, 'Vstaň, posvěť lidu a rci: Posvěťte se k zítřku; nebo takto praví Hospodin Bůh Izraelský: Věc proklatá jest u prostřed tebe, Izraeli, nebudeš moci ostáti před nepřátely svými, dokudž neodejmeš prokletí toho z prostředku svého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 14, 'Protož přistupovati budete ráno po pokoleních svých, a pokolení, kteréž ukáže Hospodin, přistupovati bude po rodech, takž rod, kterýž ukáže Hospodin, přistupovati bude po domích, a dům, kterýž ukáže Hospodin, přistupovati bude po osobách.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 15, 'Kdož pak postižen bude vinný věcí proklatou, ohněm spálen bude, on i všecko, což jeho jest, proto že přestoupil smlouvu Hospodinovu, a že učinil nešlechetnost v Izraeli.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 16, 'Vstav tedy Jozue ráno, kázal přistupovati Izraelovi po pokoleních jejich. I postiženo jest pokolení Judovo.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 17, 'Tedy když kázal přistupovati čeledem Juda, postižena jest čeled Záre. Potom kázal přistupovati čeledi Záre po osobách, a postižen jest Zabdi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 18, 'I kázal přistupovati domu jeho po osobách, i postižen jest Achan, syn Charmi, syna Zabdi, syna Záre z pokolení Judova.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 19, 'I řekl Jozue Achanovi: Synu můj, dej, prosím, chválu Hospodinu Bohu Izraelskému, a vyznej se jemu, a oznam mi aspoň již, co jsi učinil, netaj již toho přede mnou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 20, 'Tedy odpovídaje Achan k Jozue, řekl: Pravdať jest, já jsem zhřešil proti Hospodinu Bohu Izraelskému, tak že to a toto jsem učinil.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 21, 'Viděl jsem mezi loupeží plášť jeden Babylonský pěkný, a dvě stě lotů stříbra, a prut zlatý jeden, padesáte lotů ztíží, čehož požádav, vzal jsem to, a aj, jsou ty věci skryté v zemi prostřed stanu mého, a stříbro pod tím.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 22, 'Tedy poslal Jozue posly, kteříž běželi do stanu, a aj, bylo to skryto v stanu jeho, a stříbro pod tím.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 23, 'A vzavše to z stanu, přinesli k Jozue a ke všechněm synům Izraelským, a položili ty věci před Hospodinem.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 24, 'Vzav tedy Jozue a všecken Izrael s ním Achana, syna Záre, a stříbro i plášť, i prut zlatý, i syny jeho, i dcery jeho, voly a osly, dobytek i stan jeho i všecko, což měl, vyvedli je do údolí Achor.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 25, 'Kdež řekl Jozue: Proč jsi zkormoutil nás? Zkormutiž tebe Hospodin v tento den. I uházel jej všecken lid kamením, a spálili je ohněm, ukamenovavše je kamením.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 26, 'Potom nametali naň hromadu kamení velikou, kteráž trvá až do tohoto dne; a tak odvrácen jest Hospodin od hněvu prchlivosti své. Protož nazváno jest jméno místa toho údolí Achor, až do dnešního dne.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 1, 'I řekl Hospodin k Jozue: Neboj se, ani se strachuj; pojmi s sebou všecken lid bojovný, a vstana, táhni k Hai. Aj, dal jsem v ruku tvou krále Hai a lid jeho, město i zemi jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 2, 'A učiníš Hai a králi jeho, jako jsi učinil Jerichu a králi jeho, loupež však a dobytky jeho rozbitujete mezi sebe. Zdělejž sobě zálohy k městu po zadu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 3, 'Tedy vstal Jozue a všecken lid bojovný, aby táhli k Hai. I vybral Jozue třidcet tisíců mužů velmi silných, a předeslal je v noci.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 4, 'A přikázal jim, řka: Šetřtež vy, kteříž uděláte zálohy městu po zadní straně města, abyste nebyli příliš daleko od něho, ale buďte všickni pohotově.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 5, 'Já pak i všecken lid, kterýž se mnou jest, přitáhneme k městu. A když oni nám vyjdou vstříc, jako prvé, utíkati budeme před nimi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 6, 'Tedy honiti budou nás, až bychom poodvedli jich od města, (nebo řeknou: Utíkají před námi, jako prvé), utíkajíce před nimi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 7, 'Vy mezi tím vyskočíte z záloh, a vyženete ostatní obyvatele města, nebo dá je Hospodin Bůh váš v ruku vaši.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 8, 'A když vezmete město, zapálíte je ohněm, podlé slova Hospodinova učiníte; šetřtež toho, což jsem přikázal vám.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 9, 'I poslal Jozue, a oni šli k zálohám, a zůstali mezi Bethel a Hai, od západní strany Hai; Jozue pak zůstal té noci u prostřed lidu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 10, 'Potom vstav Jozue velmi ráno, sečtl lid, i bral se napřed, on a starší Izraelští před lidem k Hai.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 11, 'Všecken také lid bojovný, kterýž byl s ním, táhnouce, přiblížili se, až přišli naproti městu, a položili se po straně půlnoční Hai; údolí pak bylo mezi nimi a mezi Hai.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 12, 'Vzal pak byl okolo pěti tisíc mužů, kteréž postavil v zálohách mezi Bethel a Hai, od západní strany města.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 13, 'I přiblížil se lid, totiž všecko vojsko, kteréž bylo od půlnoční strany města, a kteříž byli v zálohách jeho od západní strany města; a tak vtáhl Jozue noci té do prostřed údolí.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 14, 'I stalo se, že když je uzřel král Hai, pospíšili, a ráno vstavše, vyšli lidé města vstříc Izraelovi k boji, on i všecken lid jeho toho času před rovinu; nevěděl pak, že zálohy udělány byly jemu po zadu města.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 15, 'I postoupil Jozue a všecken Izrael před nimi, a utíkali cestou pouště.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 16, 'I svolán jest všecken lid v městě, aby je honili. I honili Jozue, a vzdálili se od města svého,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 17, 'Tak že nezůstal žádný z obyvatelů Hai a Bethel, kdo by nevyšel, aby honil Izraele; a nechali města otevřeného, a honili Izraele.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 18, 'Řekl pak Hospodin k Jozue: Zdvihni korouhev, kterouž máš v rukou svých, proti Hai, nebo v ruce tvé dám je. I zdvihl Jozue korouhev, kterouž měl v ruce své, proti městu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 19, 'Tedy, kteříž byli v zálohách, rychle vyskočili z místa svého, a běželi, když pozdvihl ruky své, a všedše do města, vzali je, a spěšně zapálili město ohněm.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 20, 'Muži pak města Hai ohlédše se nazpět, uzřeli, a aj, vstupoval dým města k nebi, a neměli místa k utíkání sem ani tam; nebo lid, kterýž utíkati počal k poušti, obrátil se na ty, kteříž je honili.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 21, 'Jozue zajisté a všecken Izrael, když viděli, že z záloh vzali město, a že se vznáší dým města, obrátili se, a bili muže Hai.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 22, 'Onino také vyšli z města proti nim, a obklíčil Izrael nepřátely své, jedni odsud, druzí od onud; a zmordovali je, tak že žádný živ nezůstal ani neušel.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 23, 'Ale krále Hai jali živého, a přivedli ho k Jozue.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 24, 'Když pak pomordoval Izrael všecky obyvatele Hai v poli, totiž na poušti, kamž je honili, a padli ti všickni od ostrosti meče, až i zahlazeni jsou: navrátil se všecken Izrael do Hai, a zmordovali ostatky jeho mečem.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 25, 'A bylo všech, kteříž padli v ten den, od muže až do ženy, dvanácte tisíců; všickni ti byli z Hai.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 26, 'Ale Jozue nespustil ruky své, kterouž vyzdvihl korouhev, dokudž nebyli zmordováni všickni obyvatelé Hai.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 27, 'Toliko hovada a loupež města toho rozbitovali mezi sebou synové Izraelští podlé slova Hospodinova, kteréž on přikázal Jozue.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 28, 'Tedy vypálil Jozue Hai, a položil je v hromadu věčnou a pustinu, až do tohoto dne.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 29, 'Krále pak Hai oběsil na dřevě, a nechal ho tam až do večera. A když zapadlo slunce, rozkázal Jozue, aby složili tělo jeho s dřeva, a povrhli je u brány města, a nametali na ně hromadu kamení velikou, kteráž trvá až do dnešního dne.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 30, 'Tedy vzdělal Jozue oltář Hospodinu Bohu Izraelskému na hoře Hébal,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 31, '(Jakož přikázal Mojžíš, služebník Hospodinův, synům Izraelským, jakož psáno jest v knize zákona Mojžíšova,) oltář z kamení celého, nad nímž nebylo zdviženo železo, a obětovali na něm oběti zápalné Hospodinu, obětovali i oběti pokojné.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 32, 'Napsal také tam na kameních výpis zákona Mojžíšova, kterýž psal před syny Izraelskými.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 33, 'Všecken pak Izrael a starší jeho, i správcové i soudcové jeho stáli po obou stranách truhly před kněžími Levítskými, kteříž nosili truhlu smlouvy Hospodinovy, tak cizí jako doma zrozený, polovice jich proti hoře Garizim, a polovice proti hoře Hébal, jakož byl prvé přikázal Mojžíš, služebník Hospodinův, aby dobrořečil lidu Izraelskému nejprvé.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 34, 'A potom četl všecka slova zákona, požehnání i zlořečení, tak jakž psáno jest v knize zákona.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 35, 'Nebylo ani slova ze všeho, což přikázal Mojžíš, jehož by nečetl Jozue přede vším shromážděním Izraelským, i ženami i dětmi i příchozími, kteříž šli u prostřed nich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 1, 'To když uslyšeli všickni králové, kteříž bydlili za Jordánem, na horách i na rovinách, a na všem břehu moře velikého naproti Libánu: Hetejský, Amorejský, Kananejský, Ferezejský, Hevejský a Jebuzejský,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 2, 'Sebrali se spolu, aby bojovali proti Jozue a proti Izraeli jednomyslně.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 3, 'Ale obyvatelé Gabaon uslyšavše, co učinil Jozue Jerichu a Hai,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 4, 'Učinili i oni chytře. Nebo odšedše, ukázali se, jako by zdaleka poslové byli, a vzali pytle staré na osly své, a kožené láhvice vinné vetché, zedrané a zzašívané,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 5, 'Obuv také starou a splácenou na nohy své, též šaty otřelé na sebe; a všecken chléb, kterýž sobě na cestu vzali, vyschlý byl a zdrobený.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 6, 'I šli k Jozue do ležení v Galgala, a řekli jemu i mužům Izraelským: Z země daleké jsme přišli, protož nyní učiňte s námi smlouvu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 7, 'Tedy odpověděli muži Izraelští k Hevejským: Snad u prostřed nás vy bydlíte, i kterakž bychom s vámi učinili smlouvu?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 8, 'Ale oni odpověděli Jozue: Služebníci tvoji jsme. Jimž řekl Jozue: Kdo pak jste, a odkud jste přišli?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 9, 'Odpověděli jemu: Z země velmi daleké přišli služebníci tvoji ve jménu Hospodina Boha tvého; nebo jsme slyšeli pověst jeho a všecky věci, kteréž činil v Egyptě,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 10, 'A všecko, což učinil dvěma králům Amorejským, kteříž bydlili za Jordánem, Seonovi, králi Ezebon, a Ogovi, králi Bázan, kterýž byl v Astarot.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 11, 'I řekli nám starší naši a všickni obyvatelé země naší těmito slovy: Nabeřte sobě potravy na cestu, a jděte jim vstříc, a rcete jim: Služebníci vaši jsme, protož nyní učiňte s námi smlouvu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 12, 'Totoť jest chléb náš; horký jsme na cestu vzali z domů svých v ten den, když jsme vyšli, abychom k vám šli, a hle, nyní již vyschl a zdrobil se.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 13, 'A tyto kožené láhvice vinné nové byly, když jsme je naplnili, a již hle, potrhané jsou; tolikéž tento oděv náš a obuv naše zvetšela, pro přílišnou cesty dalekost.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 14, 'I přijali to muži ti z pokrmů jejich, a úst Hospodinových neotázali se.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 15, 'A učinil s nimi Jozue pokoj, a všel s nimi v smlouvu, aby jich při životu zanechal; také i knížata shromáždění přísahu jim učinili.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 16, 'Po třech pak dnech, po té smlouvě s nimi učiněné, uslyšeli, že by velmi blízko jich byli, a že by u prostřed nich bydlili.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 17, 'Jdouce tedy synové Izraelští, přitáhli k městům jejich třetího dne; města pak jejich byla Gabaon a Kafira a Berot a Kariatjeharim.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 18, 'Ale nezbili jich synové Izraelští, proto že přísahu jim učinili knížata shromáždění skrze Hospodina Boha Izraelského. A reptalo všecko shromáždění proti knížatům.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 19, 'Tedy řekla všecka knížata všemu shromáždění: My jsme jim přísahu učinili skrze Hospodina Boha Izraelského, protož nyní nemůžeme se jich dotknouti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 20, 'Toto jim učiníme: Zanecháme jich při životu, aby nebylo na nás rozhněvání pro přísahu, kterouž jsme jim učinili.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 21, 'Řekli jim knížata i to: Nechť jsou živi a drva sekají, a vodu nosí všemu shromáždění. I přestali na tom, jakož jim mluvila knížata.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 22, 'Povolal jich pak Jozue a mluvil k nim, řka: Proč jste nás podvedli, řkouce: Velmi jsme dalecí od vás? A vy u prostřed nás bydlíte.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 23, 'Protož nyní zlořečení jste, a nepřestanou z vás služebníci, a kteříž by dříví sekali a vodu nosili do domu Boha mého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 24, 'Kteříž odpovídajíce Jozue, řekli: Za věc jistou oznámeno bylo služebníkům tvým, kterak přikázal Hospodin Bůh tvůj Mojžíšovi služebníku svému, dáti vám zemi tuto, a vyhladiti všecky obyvatele země této před tváří vaší; protož strachovali jsme se vás, bojíce se za životy své před vámi, a učinili jsme to.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 25, 'A hle, nyní v ruce tvé jsme; cožť se dobrého a spravedlivého vidí učiniti s námi, to učiň.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 26, 'I učinil jim tak, a vysvobodil je z rukou synů Izraelských, aby jich nepobili.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 27, 'A ustanovil je Jozue v ten den, aby dříví sekali a vodu nosili všemu shromáždění, i k oltáři Hospodinovu, až do tohoto dne, na místě, kteréž by vyvolil.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 1, 'Uslyšev pak Adonisedech, král Jeruzalémský, že Jozue vzal město Hai, a jako proklaté zkazil je, (nebo jakž učinil Jerichu a králi jeho, tak učinil Hai a králi jeho,) a že pokoj učinili obyvatelé Gabaon s Izraelem, a bydlí u prostřed něho,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 2, 'I bál se velmi, proto že město veliké bylo Gabaon, jako jedno z měst královských, a že bylo větší než Hai, a všickni muži jeho udatní.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 3, 'Protož poslal Adonisedech, král Jeruzalémský, k Ohamovi, králi Hebron, a k Faramovi, králi Jarmut, a k Jafiovi, králi Lachis, a k Dabirovi, králi Eglon, řka:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 4, 'Sjeďte se ke mně, a pomozte mi, abychom dobyli Gabaon, proto že pokoj učinili s Jozue a s syny Izraelskými.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 5, 'I shromáždilo se a vytáhlo pět králů Amorejských, král Jeruzalémský, král Hebron, král Jarmut, král Lachis, král Eglon, oni i všecka vojska jejich, a položivše se u Gabaon, dobývali ho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 6, 'Tedy poslali muži Gabaon k Jozue do ležení v Galgala, řkouce: Neodjímejž ruky své od služebníků svých; přitáhni rychle k nám, zachovej nás a spomoz nám; nebo sebrali se proti nám všickni králové Amorejští bydlící na horách.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 7, 'I táhl Jozue z Galgala, on i všecken lid bojovný s ním, všickni muži udatní.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 8, '(Nebo byl řekl Hospodin k Jozue: Neboj se jich, v ruce tvé zajisté dal jsem je, neostojíť žádný z nich před oblíčejem tvým.)');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 9, 'I připadl na ně Jozue v náhle, nebo celou noc táhl z Galgala.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 10, 'A potřel je Hospodin před Izraelem, kterýžto pobil je ranou velikou u Gabaon, a honil je cestou, kudy se jde k Betoron, a bil je až do Azeka a až do Maceda.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 11, 'I stalo se, když utíkali před tváří Izraele, sstupujíce do Betoron, že Hospodin metal na ně kamení veliké s nebe, až k Azeku, a mřeli. Více jich zemřelo od krupobití kamenného, než jich pobili synové Izraelští mečem.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 12, 'Tedy mluvil Jozue k Hospodinu v den, v kterýž dal Hospodin Amorejského v moc synům Izraelským, a řekl před syny Izraelskými: Slunce v Gabaon zastav se, a měsíc v údolí Aialon.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 13, 'I zastavilo se slunce, a stál měsíc, dokudž nepomstil se lid nad nepřátely svými. Zdali není toho napsáno v knize Upřímého? Tedy stálo slunce u prostřed nebe, a nepospíchalo k západu, jako za jeden celý den.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 14, 'Nebylo dne takového prvé ani potom, jako když vyslyšel Hospodin hlas člověka; nebo Hospodin bojoval za Izraele.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 15, 'I navracel se Jozue i všecken Izrael s ním do táboru v Galgala.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 16, 'Uteklo pak bylo těch králů pět, a skryli se v jeskyni při Maceda.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 17, 'I oznámeno bylo Jozue těmi slovy: Nalezeno jest pět králů, kteříž se skryli v jeskyni při Maceda.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 18, 'I řekl Jozue: Přivalte kamení veliké k díře té jeskyně, a osaďte ji muži, aby ostříhali jich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 19, 'Vy pak nezastavujte se, hoňte nepřátely své, a bíte je po zadu, a nedejte jim vjíti do měst jejich, nebo dal je Hospodin Bůh váš v ruku vaši.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 20, 'Když pak přestali Jozue a synové Izraelští bíti jich porážkou velikou velmi, až i zahlazeni byli; a kteříž živi pozůstali z nich, utekli do měst hrazených:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 21, 'Navrátil se všecken lid do ležení k Jozue do Maceda ve zdraví; nepohnul proti synům Izraelským žádný jazykem svým.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 22, 'Potom řekl Jozue: Odhraďte díru u jeskyně, a vyveďte ke mně pět králů těch z jeskyně.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 23, 'I učinili tak, a vyvedli k němu pět králů těch z jeskyně, krále Jeruzalémského, krále Hebron, krále Jarmut, krále Lachis, krále Eglon.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 24, 'A když vyvedli ty krále k Jozue, svolav všecky muže Izraelské, řekl vývodám mužů bojovných, kteříž s ním v tažení tom byli: Přistupte sem, a šlapejte nohama svýma na hrdla těch králů. Kteřížto přistoupivše, šlapali nohama svýma na hrdla jejich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 25, 'I řekl jim Jozue: Nebojte se ani strachujte, posilňte se a buďte zmužilí, nebo tak učiní Hospodin všechněm nepřátelům vašim, proti nimž bojujete.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 26, 'Potom bil je Jozue a zmordoval, a pověsil je na pěti dřevích; a viseli na dřevích až do večera.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 27, 'Když pak zapadlo slunce, k rozkazu Jozue složili je s dřev, a uvrhli je do jeskyně, v kteréž se byli skryli, a přivalili kamení veliké k díře jeskyně, kteréž jest tu až do tohoto dne.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 28, 'Téhož dne také dobyl Jozue Maceda, a pohubil je mečem, i krále jejich pobil spolu s nimi, a všecky lidi, kteříž byli v něm. Neživil žádného, ale učinil králi Maceda, jako učinil králi Jericha.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 29, 'Táhl potom Jozue a všecken Izrael s ním z Maceda k Lebnu, a dobýval Lebna.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 30, 'I vydal je také Hospodin v ruku Izraelovi i krále jeho, a pobil je mečem, a všecky duše, kteréž byly v něm; nenechal tam žádného živého, a učinil králi jeho, jako učinil králi Jericha.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 31, 'Táhl také Jozue a všecken Izrael s ním z Lebna do Lachis, a položivše se u něho, dobývali ho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 32, 'I dal Hospodin Lachis v ruku Izraele, a dobyl ho druhého dne, a pohubil je mečem i všecky lidi, kteříž byli v něm, rovně tak, jakž učinil Lebnu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 33, 'Tehdy přitáhl Horam, král Gázer, aby pomoc dal Lachis. I porazil jej Jozue i lid jeho, tak že nepozůstavil žádného živého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 34, 'Táhl potom Jozue a všecken Izrael s ním z Lachis do Eglon, a položivše se naproti, bojovali proti němu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 35, 'A vzali je toho dne, a pobili je mečem, a všecky duše, kteréž byly v něm, dne toho pomordovali, rovně tak, jakž učinili Lachis.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 36, 'Vstoupil pak Jozue a všecken Izrael s ním z Eglon do Hebron, a dobývali ho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 37, 'I vzali je a zhubili mečem i krále jeho, i všecka města jeho, i každého člověka, kterýž byl v něm; nepozůstavil žádného živého, podobně tak, jakož učinil Eglon. I zahladil je i všelikou duši, kteráž byla v něm.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 38, 'Potom navracuje se Jozue a všecken Izrael s ním, přišli do Dabir, a dobýval ho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 39, 'I vzal je a krále jeho i všecka města jeho, a pohubili je mečem, a všelikou duši, kteráž byla v něm, jako proklaté vyhladili. Nepozůstavili žádného živého; jakož učinil Hebron, tak učinil Dabir i králi jeho, a jakož učinil Lebnu a králi jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 40, 'A tak pohubil Jozue všecku zemi po horách, i polední stranu, i roviny a údolí, i všecky krále jejich. Nepozůstavil žádného živého, ale všelikou duši vyhladil, jakož přikázal Hospodin Bůh Izraelský.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 41, 'Pohubil tedy Jozue všecko od Kádesbarne až do Gázy, a všecku zemi Gosen až do Gabaon.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 42, 'A všecky krále ty a zemi jejich vzal Jozue pojednou, nebo Hospodin Bůh Izraelský bojoval za Izraele.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 43, 'Potom navrátil se Jozue a všecken Izrael s ním do ležení, kteréž bylo v Galgala.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 1, 'To když uslyšel Jabín, král Azor, poslal k Jobábovi, králi Mádon, a k králi Simron, a k králi Achzaf,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 2, 'I k králům, kteříž bydlili k straně půlnoční na horách i na rovinách ku polední Ceneret, i na rovinách a v krajinách Dor na západ,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 3, 'K Kananejskému na východ i na západ, a k Amorejskému, Hetejskému, Ferezejskému a Jebuzejskému na horách, a k Hevejskému pod horou Hermon v zemi Masfa.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 4, 'I vytáhli všickni ti a všecka vojska jejich s nimi, lid mnohý jako písek, kterýž jest na břehu mořském nesčíslný, i koňů i vozů velmi mnoho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 5, 'A smluvivše se všickni králové ti, přitáhli a položili se spolu při vodách Merom, aby bojovali proti Izraelovi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 6, 'Řekl pak Hospodin k Jozue: Neboj se jich, nebo zítra o této chvíli vydám všecky tyto k zabití Izraelovi; koňům jejich žily podřežeš, a vozy jejich ohněm spálíš.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 7, 'Tedy vytáhl Jozue a s ním všecken lid válečný proti nim k vodám Merom rychle, a udeřili na ně.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 8, 'I dal je Hospodin v ruku Izraelovi, a porazili je. I honili je až k Sidonu velikému, a až k vodám Maserefot, a k údolí Masfe na východ, a pobili je, tak že nepozůstavili žádného živého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 9, 'A učinil jim Jozue, jakož byl rozkázal jemu Hospodin, koňům jejich žily zpodřezoval, a vozy jejich ohněm popálil.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 10, 'Potom navrátiv se Jozue téhož času, dobyl Azor, a krále jeho zabil mečem. Azor pak bylo prvé nejznamenitější mezi všemi království těmi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 11, 'Pobili také všecko, cožkoli v něm živo bylo, mordujíce je mečem, tak že nezůstalo žádného živého; Azor pak spálil ohněm.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 12, 'Takž podobně učinil všechněm městům králů těch, a všecky krále jejich zjímal Jozue, a zbiv je mečem, vyhladil je, jakož přikázal Mojžíš, služebník Hospodinův.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 13, 'A však žádného města z těch, kteráž ještě zůstala v ohradě své, nespálil Izrael, kromě samého Azor, kteréž spálil Jozue.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 14, 'A všecky loupeže měst těch i hovada rozdělili mezi sebou synové Izraelští; toliko všecky lidi zbili mečem, dokudž nevyhladili jich, nenechavše žádného živého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 15, 'Jakož byl přikázal Hospodin Mojžíšovi, služebníku svému, tak přikázal Mojžíš Jozue, a Jozue tak činil; nepominul ničeho toho, což byl přikázal Hospodin Mojžíšovi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 16, 'A tak vzal Jozue všecku tu zemi, hory i všecku stranu polední, i všecku zemi Gosen, i roviny, i pole, totiž hory Izraelské i roviny jejich,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 17, 'Od hory Halak, kteráž se táhne do Seir, až k Balgad na rovině Libánské, pod horou Hermon; všecky také krále jejich zjímal, a zbil je i zmordoval.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 18, 'Po mnohé dny Jozue vedl válku se všechněmi těmi králi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 19, 'A nebylo města, ješto by v pokoj vešlo s syny Izraelskými, kromě Hevejských obyvatelů v Gabaon; jiná všecka válkou vzali.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 20, 'Nebo od Hospodina to bylo, že jsou zatvrdili byli srdce své, tak aby vyšli válečně proti Izraelovi, a aby je v prokletí vydal, a neučinil jim milosti, ale aby je zahubil, jakož přikázal Hospodin Mojžíšovi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 21, 'Toho pak času přitáhl Jozue a vyplénil Enaky z těch hor, totiž z Hebronu, z Dabir a z Anab, i ze všeliké hory Judské, a ze všeliké hory Izraelské; spolu s městy jejich vyhladil je Jozue.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 22, 'Nezůstal žádný z Enaků v zemi synů Izraelských; toliko v Gáze, v Gát a v Azotu zůstali.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 23, 'Tak tedy vzal Jozue všecku tu zemi, jakž byl rozkázal Hospodin Mojžíšovi, a dal ji Jozue v dědictví Izraelovi vedlé dílů jejich, po pokoleních jejich. I odpočinula země od válek.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 1, 'Tito pak jsou králové té země, kteréž pobili synové Izraelští, a opanovali zemi jejich, za Jordánem k východu slunce, od potoku Arnon až k hoře Hermon i všecky roviny k východu:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 2, 'Seon, král Amorejský, kterýž bydlil v Ezebon, a panoval od Aroer, kteréž leží při břehu potoka Arnon, a u prostřed potoka toho, a polovici Galád, až do potoka Jabok, kterýž jest na pomezí synů Ammon,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 3, 'A od rovin až k moři Ceneret k východu, a až k moři pouště, jenž jest moře slané k východu, kudyž se jde k Betsimot, a od polední strany ležící pod horou Fazga.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 4, 'Pomezí také Oga, krále Bázan, z ostatků Refaimských, kterýž bydlil v Astarot a v Edrei,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 5, 'A kterýž panoval na hoře Hermon a v Sálecha, i ve vší krajině Bázan až ku pomezí Gessuri a Machati, a nad polovicí Galád, ku pomezí Seona, krále Ezebon.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 6, 'Mojžíš, služebník Hospodinův, a synové Izraelští pobili je; a dal ji Mojžíš služebník Hospodinův k vládařství pokolení Rubenovu, Gádovu a polovici pokolení Manassesova.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 7, 'Tito pak jsou králové země té, kteréž pobil Jozue a synové Izraelští za Jordánem k západu, od Balgad, kteréž jest na poli Libánském, až k hoře lysé, kteráž se táhne až do Seir, a dal ji Jozue pokolením Izraelským k vládařství po dílích jejich,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 8, 'Na horách i na rovinách, i po polích, i v údolích, i na poušti a na poledne, zemi Hetejského, Amorejského, Kananejského, Ferezejského, Hevejského a Jebuzejského:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 9, 'Král Jericha jeden, král Hai, kteréž bylo na straně Bethel, jeden;');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 10, 'Král Jeruzalémský jeden, král Hebron jeden;');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 11, 'Král Jarmut jeden, král Lachis jeden;');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 12, 'Král Eglon jeden, král Gázer jeden;');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 13, 'Král Dabir jeden, král Gader jeden;');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 14, 'Král Horma jeden, král Arad jeden;');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 15, 'Král Lebna jeden, král Adulam jeden;');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 16, 'Král Maceda jeden, král Bethel jeden;');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 17, 'Král Tafua jeden, král Chefer jeden;');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 18, 'Král Afek jeden, král Sáron jeden;');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 19, 'Král Mádon jeden, král Azor jeden;');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 20, 'Král Simron Meron jeden, král Achzaf jeden;');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 21, 'Král Tanach jeden, král Mageddo jeden;');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 22, 'Král Kedes jeden, král Jekonam z Karmelu jeden;');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 23, 'Král Dor z krajiny Dor jeden, král z Goim v Galgal jeden;');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 24, 'Král Tersa jeden. Všech králů třidceti a jeden.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 1, 'Jozue pak již byl starý a sešlý věkem. I řekl jemu Hospodin: Tys se již sstaral, a jsi sešlého věku, země pak zůstává velmi mnoho k opanování.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 2, 'Tato jest země, kteráž zůstává: Všecky končiny Filistinské a všecka Gessuri,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 3, 'Od Níle, kterýž jest naproti Egyptu, až ku pomezí Akaron na půlnoci, kterážto krajina Kananejským se přičítá, v níž jest patero knížetství Filistinských: Gazejské, Azotské, Aškalonitské, Getejské a Akaronitské, a to bylo Hevejské;');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 4, 'Na poledne pak všecka země Kananejská a Mára, kteréž jest Sidonských až do Afeka, a až ku pomezí Amorejského;');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 5, 'Též země Giblická, a všecken Libán k východu slunce, od Balgad pod horou Hermon, až kde se vchází do Emat.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 6, 'Všecky obyvatele té hory, od Libánu až k vodám Maserefot, všecky Sidonské já vyženu od tváři synů Izraelských; toliko ty rozděl ji losem lidu Izraelskému v dědictví, jakožť jsem přikázal.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 7, 'Protož nyní rozděl zemi tu v dědictví devateru pokolení, a polovici pokolení Manassesova,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 8, 'Poněvadž druhá polovice a pokolení Rubenovo a Gádovo vzali díl svůj, kterýž jim dal Mojžíš před Jordánem k východu, jakož dal jim Mojžíš služebník Hospodinův,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 9, 'Od Aroer, kteréž jest při břehu potoka Arnon, i města u prostřed potoka, i všecky roviny Medaba až do Dibon,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 10, 'I všecka města Seona, krále Amorejského, kterýž kraloval v Ezebon, až ku pomezí synů Ammon,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 11, 'A Galád, i pomezí Gessuri a Machati, všecku horu Hermon, i všecken Bázan až do Sálecha,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 12, 'Všecko království Oga v Bázan, kterýž kraloval v Astarot a v Edrei, kterýž byl pozůstal z ostatků Refaim, když je pobil Mojžíš, a zahladil je.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 13, 'Nevyhnali pak synové Izraelští Gessuri a Machati, protož bydlil Gessura a Machata u prostřed Izraele až do dnešního dne.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 14, 'Toliko pokolení Léví nedal dědictví; oběti ohnivé Hospodina Boha Izraelského jsou dědictví jeho, jakož mluvil jemu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 15, 'Dal pak Mojžíš pokolení synů Ruben po čeledech jejich dědictví.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 16, 'A bylo jejich pomezí od Aroer, kteréž jest při břehu potoka Arnon, i město, kteréž jest u prostřed potoka, i všecky roviny, kteréž jsou při Medaba,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 17, 'Ezebon i všecka města jeho, kteráž byla na rovinách, Dibon a Bamotbal a Betbalmeon,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 18, 'Jasa a Kedemot a Mefat,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 19, 'A Kariataim a Sabma, a Saratazar na hoře údolí,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 20, 'A Betfegor i Assedot, Fazga a Betsimot.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 21, 'Všecka také města v kraji, i všecko království Seona, krále Amorejského, kterýž kraloval v Ezebon, jehožto zabil Mojžíš i s knížaty Madianskými, Evi i Rekem, Sur, Hur a Rebe, vývodami Seonovými, obyvateli té země.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 22, 'Ano i Baláma, syna Beorova, věšťce, zabili synové Izraelští mečem, s jinými, kteříž zbiti od nich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 23, 'I bylo pomezí synů Rubenových Jordán s mezemi svými. To jest dědictví synů Rubenových po čeledech jejich, města i vsi jejich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 24, 'Dal také Mojžíš pokolení Gád, synům Gádovým, po čeledech jejich dědictví.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 25, 'A bylo jejich pomezí Jazer i všecka města Galád, a polovice země synů Ammon až do Aroer, kteréž jest naproti Rabba,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 26, 'A od Ezebon až do Rámot, Masfe a Betonim, a od Mahanaim až ku pomezí Dabir;');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 27, 'V údolí také Betaram a Betnemra, a Sochot, a Sefon, ostatek království Seona, krále Ezebon, i Jordán s pomezím svým až k kraji moře Ceneret za Jordánem na východ.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 28, 'To jest dědictví synů Gád po čeledech jejich, města i vsi jejich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 29, 'Dal také Mojžíš polovici pokolení Manassesova dědictví, i bylo polovice pokolení synů Manassesových, po čeledech jejich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 30, 'Pomezí jejich od Mahanaim, všecken Bázan, všecko království Oga, krále Bázan, i všecky vesnice Jair, kteréž jsou v Bázan, šedesáte měst,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 31, 'A polovice Galád, a Astarot, a Edrei, města království Oga v Bázan. To dal synům Machirovým, syna Manassesova, polovici synů Machirových, po čeledech jejich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 32, 'Ta jsou dědictví, kteráž rozdělil Mojžíš na rovinách Moábských před Jordánem proti Jerichu k východu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 33, 'Pokolení pak Léví nedal Mojžíš dědictví; Hospodin Bůh Izraelský jest dědictví jejich, jakož mluvil jim.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 14, 1, 'Toto pak jest, což dědičně obdrželi synové Izraelští v zemi Kanán, což uvedli jim právem dědičným k vládařství Eleazar kněz, a Jozue, syn Nun, a přední z otců, v pokolení synů Izraelských,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 14, 2, 'Losem dělíce dědictví jejich, jakož přikázal Hospodin skrze Mojžíše, aby dal devateru pokolení a polovici pokolení.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 14, 3, 'Nebo byl dal Mojžíš dědictví půltřetímu pokolení před Jordánem, Levítům pak nedal dědictví u prostřed nich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 14, 4, 'Nebo synů Jozefových bylo dvoje pokolení, Manassesovo a Efraimovo; a nedali dílu Levítům v zemi, kromě měst k bydlení, a podměstí jejich pro dobytek a stáda jejich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 14, 5, 'Jakož přikázal Hospodin Mojžíšovi, tak učinili synové Izraelští, a rozdělili zemi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 14, 6, 'Přistoupili pak synové Juda k Jozue v Galgala, i promluvil k němu Kálef, syn Jefonův, Cenezejský: Ty víš, co jest mluvil Hospodin k Mojžíšovi, muži Božímu, z příčiny mé a tvé v Kádesbarne.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 14, 7, 'Ve čtyřidceti letech byl jsem, když mne poslal Mojžíš, služebník Hospodinův, z Kádesbarne k spatření země, a oznámil jsem jemu tu věc, jakž bylo v srdci mém.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 14, 8, 'Ale bratří moji, kteříž šli se mnou, zkormoutili srdce lidu, já pak cele kráčel jsem za Hospodinem Bohem svým.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 14, 9, 'I přisáhl Mojžíš toho dne, řka: Jistě že země, po kteréž jsi chodil nohama svýma, bude v dědictví tobě i synům tvým až na věky, proto že jsi cele následoval Hospodina Boha mého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 14, 10, 'A nyní, aj, propůjčil mi Hospodin života, jakož zaslíbil. Již čtyřidceti a pět let jest od toho času, jakž toto mluvil Hospodin k Mojžíšovi, a jakž chodil Izrael po poušti, a aj, již dnes jsem v osmdesáti pěti letech,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 14, 11, 'A ještě nyní jsem při síle jako tehdáž, když poslal mne Mojžíš. Jaká byla síla má tehdáž, taková i nyní síla má jest k boji, a k vycházení i k vcházení.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 14, 12, 'Protož nyní dej mi horu tuto, o níž mluvil Hospodin onoho dne, nebo ty slyšel jsi toho dne, že Enakim jsou tam, a města veliká a pevně hrazená. Bude-li Hospodin se mnou, vyhladím je, jakož mluvil Hospodin.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 14, 13, 'I požehnal mu Jozue, a dal Hebron Kálefovi, synu Jefone, v dědictví.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 14, 14, 'Protož dostal se Hebron Kálefovi, synu Jefona Cenezejského, v dědictví až do tohoto dne, proto že cele kráčel za Hospodinem Bohem Izraelským.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 14, 15, 'Sloulo pak Hebron prvé město Arbe, kterýžto Arbe byl člověk veliký mezi Enakim. I odpočinula země od bojů.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 1, 'Tento pak byl los pokolení synů Juda po čeledech jejich, při pomezí Edomském a poušti Tsin ku poledni, k straně polední.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 2, 'I byla jejich meze polední kraj moře slaného od zátoky, kteráž se chýlí ku poledni.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 3, 'Odkudž jda na poledne k vrchu Akrabim, přechází Tsin, a táhne se od poledne k Kádesbarne, i přichází až do Ezron, a odtud točí se k Addar, a obchází Karkaha.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 4, 'Odtud jde do Asmona, a vychází ku potoku Egyptskému, a přichází meze ta až k západu. To budete míti pomezí na poledne.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 5, 'Meze pak na východ jest moře slané, až k kraji Jordánu, a meze strany půlnoční jest od zátoky moře a od kraje Jordánu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 6, 'Odkudž jde meze ta do Betogla, a táhne se od půlnoci do Betaraba; a odtud přichází k kameni Bohana syna Rubenova.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 7, 'A vstupuje ta meze do Dabir od údolí Achor, a na půlnoci chýlí se k Galgala, kteréž jest naproti vcházení do Adomim, jenž jest údolí tomu ku poledni, a přechází k vodám Ensemes, a skonává se u studnice Rogel.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 8, 'Odtud jde ta meze přes údolí synů Hinnom k straně Jebus od poledne, jenž jest Jeruzalém, odkudž vstupuje táž meze k vrchu hory, kteráž jest naproti údolí Hinnom na západ, a kteráž jest na konci údolí Refaim na půlnoci.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 9, 'Obchází pak ta meze od vrchu té hory k studnici vody Neftoa, a vychází k městům hory Efron; a odtud jde ta meze do Bála, jenž jest Kariatjeharim.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 10, 'Potom točí se ta meze od Bála na západ k hoře Seir, a odtud jde k straně hory Jeharimských od půlnoci, jenž jest Cheslon, a sstupuje do Betsemes, a přichází do Tamna.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 11, 'A vychází ta meze v stranu Akaron na půlnoci, a točí se vůkol k Sechronu, a přechází až k hoře Bála, a odtud táhne se do Jebnael, i dochází ta meze k moři.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 12, 'Potom západní pomezí jest při moři velikém a mezech jeho. To jest pomezí synů Juda vůkol, po čeledech jejich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 13, 'Kálefovi pak, synu Jefone, dal díl u prostřed synů Juda, podlé řeči Hospodinovy k Jozue, město Arbe, otce Enakova, jenž jest Hebron.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 14, 'I vyhnal odtud Kálef tři syny Enakovy: Sesai a Achimana a Tolmai, rodinu Enakovu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 15, 'A odtud vstoupil k obyvatelům Dabir, kteréž prvé sloulo Kariatsefer.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 16, 'I řekl Kálef: Kdo by dobyl Kariatsefer a vzal je, dám jemu Axu dceru svou za manželku.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 17, 'Dobyl ho pak Otoniel syn Cenezův, příbuzný Kálefův, i dal jemu Axu dceru svou za manželku.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 18, 'I stalo se, že když přišla k němu, ponukla ho, aby prosil otce jejího za pole; protož ssedla s osla. I řekl jí Kálef: Což tě?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 19, 'A ona odpověděla: Dej mi dar, poněvadž jsi mi dal zemi suchou, dejž mi také studnice vod. I dal jí studnice horní a studnice dolní.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 20, 'To jest dědictví pokolení synů Juda po čeledech jejich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 21, 'Tato pak jsou města v končinách pokolení synů Juda, podlé pomezí Edom na poledne: Kabsael, Eder a Jagur;');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 22, 'A Cina, a Dimona, a Adada;');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 23, 'A Kedes, a Azor, a Jetnan;');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 24, 'Zif a Telem, a Balot;');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 25, 'Též Azor, Chadat a Kariot, Ezron, jenž jest Azor;');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 26, 'Amam a Sama, a Molada;');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 27, 'A Azar Gadda, a Esmon, a Betfelet;');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 28, 'Též Azarsual, a Bersabé, a Baziothia;');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 29, 'Bála a Im, a Esem;');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 30, 'A Eltolad, a Chesil, a Horma;');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 31, 'A Sicelech, a Medemena, a Sensenna;');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 32, 'A Lebaot, a Selim, též Ain a Remmon; všech měst dvadceti a devět i vsi jejich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 33, 'Na rovinách pak: Estaol a Zaraha, a Asna;');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 34, 'A Zanoe, a Engannim, Tafua a Enaim;');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 35, 'Jarmut, Adulam, Socho a Azeka;');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 36, 'A Saraim, Aditaim, a Gedera, a Gederotaim, měst čtrnácte i vsi jejich;');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 37, 'Senan a Adassa, a Magdalgad;');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 38, 'Delean a Masfa, a Jektehel;');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 39, 'Lachis, Baskat a Eglon;');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 40, 'Chebon, Lemam a Cetlis;');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 41, 'Gederot, Betdagon, a Naama, i Maceda, měst šestnáct a vsi jejich;');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 42, 'Lebna, Eter a Asan;');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 43, 'Jefta, Asna a Nesib;');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 44, 'Ceila, Achzib a Maresa, měst devět i vsi jejich;');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 45, 'Akaron a městečka, i vsi jeho;');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 46, 'Od Akaron až k moři všecka města, kteráž se chýlí k Azotu, i vsi jejich;');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 47, 'Azot, městečka jeho i vsi jeho; Gáza, městečka jeho i vsi jeho až ku potoku Egyptskému, i moře veliké s pomezím svým.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 48, 'A na horách: Samir, Jeter a Socho;');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 49, 'Danna a město Sanna, jenž jest Dabir;');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 50, 'Anab, Estemo a Anim;');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 51, 'Gosen, Holon a Gilo, měst jedenácte i vsi jejich;');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 52, 'Arab, Duma a Esan;');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 53, 'Janum, Bettafua a Afeka;');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 54, 'Též Atmata a Kariatarbe, jenž jest Hebron, a Sior, měst devět a vsi jejich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 55, 'Maon, Karmel a Zif, a Juta;');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 56, 'Jezreel a Jukadam, a Zanoe;');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 57, 'Kain, Gabaa a Tamna, měst deset i vsi jejich;');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 58, 'Alul, Betsur a Gedor;');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 59, 'Maret, Betanot a Eltekon, měst šest i vsi jejich;');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 60, 'Kariatbaal, kteréž jest Kariatjeharim, a Rebba, města dvě i vsi jejich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 61, 'Na poušti: Betaraba, Middin a Sechacha;');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 62, 'A Nibsam, a město solné, a Engadi, měst šest i vsi jejich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 63, 'Jebuzejských pak obyvatelů Jeruzaléma nemohli synové Juda vypléniti, protož bydlil Jebuzejský s syny Judskými v Jeruzalémě až do tohoto dne.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 16, 1, 'Potom padl los synům Jozefovým, od Jordánu proti Jerichu při vodách Jerišských k východu, poušť, kteráž se začíná od Jericha přes hory Bethel.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 16, 2, 'A od Bethel vychází do Lůza, a přichází ku pomezí Archi do Atarot.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 16, 3, 'Potom jde k moři ku pomezí Jefleti, až ku pomezí Betoron dolního, a až k Gázer, a skonává se při moři.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 16, 4, 'I vzali dědictví své synové Jozefovi, Manasses a Efraim.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 16, 5, 'Byla pak meze synů Efraimových po čeledech jejich, ta byla meze dědictví jejich na východ, od Atarot Addar až do Betoron vrchního.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 16, 6, 'A vychází meze ta k moři při Michmetat od půlnoční strany, a obchází meze k východu Tanatsilo, a přechází ji od východu k Janoe.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 16, 7, 'A sstupuje z Janoe do Atarot a Nárat, a přichází do Jericha, a vychází k Jordánu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 16, 8, 'Od Tafue meze jde k moři ku potoku Kána, a skonává se při moři. To jest dědictví pokolení synů Efraim po čeledech jejich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 16, 9, 'Města pak oddělená synům Efraimovým byla u prostřed dědictví synů Manassesových, všecka města s vesnicemi svými.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 16, 10, 'A nevyplénili Kananea bydlícího v Gázer. I bydlil Kananejský u prostřed Efraima až do dnes, dávaje plat.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 1, 'A tento byl los Manassesův (nebo on jest prvorozený Jozefův): Machirovi prvorozenému Manassesovu, otci Gálad, proto že byl muž bojovný, dostal se Galád a Bázan.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 2, 'Dostalo se také jiným synům Manassesovým po čeledech jejich, synům Abiezer, a synům Helek, a synům Asriel, i synům Sechem, a synům Hefer, a synům Semida. (Nebo ti jsou synové Manassesovi, syna Jozefova, muži po rodech svých.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 3, 'Ale Salfad, syn Hefer, syna Galád, syna Machir, syna Manasse, neměl synů, než dcery toliko, jejichž jsou tato jména: Mahla a Noa, Hegla, Melcha a Tersa.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 4, 'Kteréžto přistoupivše před Eleazara kněze, a před Jozue, syna Nun, i před knížata, řekly: Hospodin přikázal Mojžíšovi, aby nám dal dědictví u prostřed bratří našich. I dal jim Jozue podlé rozkázaní Hospodinova dědictví u prostřed bratří otce jejich.)');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 5, 'Dostalo se provazců Manassesovi deset, krom země Galád a Bázan, kteráž byla před Jordánem.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 6, 'Nebo dcery Manassesovy obdržely dědictví mezi syny jeho, země pak Galád přišla jiným synům Manassesovým.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 7, 'A byla meze Manassesova od Asser, Michmetat, jenž jest před Sichem, a táhne se na pravou stranu k obyvatelům Entafue.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 8, '(Manassesova zajisté byla země Tafue, ale Tafue podlé pomezí Manassesova jest synů Efraimových.)');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 9, 'Odkudž sstupuje pomezí ku potoku Kána, na poledne tomu potoku, a tu jsou města Efraimova u prostřed měst Manassesových; pomezí pak Manassesovo jest na půlnoci toho potoka, a skonává se při moři.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 10, 'Na poledne jest díl Efraimův, a na půlnoci Manassesův, moře pak jest pomezí jejich; a v pokolení Asser sbíhají se na půlnoci, v pokolení pak Izachar na východ.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 11, 'Nebo dědictví Manassesovo jest mezi Izacharovým a Asserovým, Betsan i městečka jeho, a Jibleam a městečka jeho; též obyvatelé Dor a městečka jeho, a obyvatelé Endor a městečka jeho; také obyvatelé Tanach a městečka jeho, i obyvatelé Mageddo a městečka jeho; tři ty krajiny.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 12, 'Ale synové Manassesovi nemohli vypléniti obyvatelů těch měst; protož směleji počal Kananejský bydliti v zemi té.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 13, 'Když se pak zsilili synové Izraelští, uvedli sobě Kananejské pod plat, a nevyhladili jich do konce.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 14, 'Tedy mluvili synové Jozefovi k Jozue, řkouce: Proč jsi nám dal dědictví toliko los jeden a provazec jeden, poněvadž jsme lid mnohý; nebo až dosavad žehnal nám Hospodin.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 15, 'I řekl jim Jozue: Poněvadž jsi lid tak mnohý, vejdi do lesa, a vyplaň sobě tam v zemi Ferezejské a Refaimské, jestližeť jest malá hora Efraim.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 16, 'Jemuž odpověděli synové Jozefovi: I tak nám nepostačí ta hora; přes to vozy železné mají všickni Kananejští, kteříž bydlejí v luzích těch, i ti, kteříž jsou v Betsan a v městečkách jeho, i ti, kteříž jsou v údolí Jezreel.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 17, 'I řekl Jozue domu Jozefovu, Efraimovu a Manassesovu, řka: Lid mnohý a silný jsi, nebudeš míti toliko dílu jednoho,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 18, 'Ale horu budeš míti. Jestližeť překáží les, tedy vysekáš jej, a obdržíš končiny její; nebo vyhladíš Kananejského, ačkoli má vozy železné a jest silný.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 1, 'Shromáždilo se pak všecko množství synů Izraelských do Sílo, a tu postavili stánek úmluvy, když již země od nich podmaněna byla.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 2, 'Pozůstalo pak z synů Izraelských, jimž ještě nebylo rozděleno dědictví jejich, sedmero pokolení.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 3, 'I řekl Jozue synům Izraelským: I dokudž zanedbáváte vjíti, abyste se uvázali v zemi, kterouž vám dal Hospodin Bůh otců vašich?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 4, 'Vydejte z sebe z každého pokolení tři muže, ať je pošli, aby vstanouce, zchodili zemi, a popsali ji vedlé dědictví svých; potom navrátí se ke mně.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 5, 'I rozdělí ji na sedm dílů. Juda zůstane v končinách svých od poledne, a čeledi Jozefovy zůstanou v končinách svých od půlnoci.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 6, 'Vy pak, když popíšete zemi na sedm dílů, přinesete sem ke mně; tedy uvrhu vám losy zde před Hospodinem Bohem naším.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 7, 'Nebo nemají dílu Levítové u prostřed vás, proto že kněžství Hospodinovo jest dědictví jejich; Gád pak a Ruben, a polovice pokolení Manassesova, vzali dědictví své před Jordánem na východ, kteréž dal jim Mojžíš, služebník Hospodinův.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 8, 'Protož vstavše muži ti, odešli. A přikázal Jozue těm, kteříž šli, aby popsali zemi, řka: Jděte a projděte zemi, a popište ji; potom navraťte se ke mně, a uvrhu zde losy před Hospodinem v Sílo.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 9, 'Tedy odešli muži, a prošedše zemi, popsali ji po městech na sedm dílů na knize, a navrátili se k Jozue do stanů v Sílo.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 10, 'I uvrhl jim losy Jozue v Sílo před Hospodinem, a rozdělil tu Jozue zemi synům Izraelským vedlé dílů jejich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 11, 'Padl pak los pokolení synů Beniaminových po čeledech jejich, a přišla meze dílu jejich mezi syny Juda a syny Jozefovy.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 12, 'A byla meze jejich k straně půlnoční od Jordánu, a šla při straně půlnoční Jericha, a táhla se na hory k moři, a skonávala se při poušti Betaven.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 13, 'A odtud přechází ta meze do Lůz, při straně Lůz polední, (jenž jest Bethel,) a chýlí se ta meze do Atarot Addar vedlé hory, kteráž jest od poledne Betoron dolního.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 14, 'Odkudž obchází vůkol k straně moře na poledne od hory, kteráž jest proti Betoron ku polední, a konec její jest Kariatbaal, (jenž jest Kariatjeharim), město synů Juda. Ta jest strana západní.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 15, 'Strana pak ku poledni od konce Kariatjeharim, a vychází ta meze k moři, a přichází až k studnici vod Neftoa.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 16, 'A táhne se táž meze k konci hory, kteráž jest naproti údolí synů Hinnom, a jest v údolí Refaim na půlnoci, a běží skrze údolí Hinnom po straně Jebuzea na poledne, a přichází k studnici Rogel.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 17, 'Potom točí se od půlnoci, a dochází k Ensemes, a vychází do Gelilot, kteréž jest naproti místu, kudy se jde do Adomim, a sstupuje k kameni Bohana, syna Rubenova.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 18, 'Odtud přechází k straně, kteráž jest naproti rovinám strany půlnoční, a táhne se do Araba.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 19, 'Odtud jde k straně Betogla na půlnoci, a skonává se meze ta při zátoce moře slaného od půlnoční strany, tu kdež vpadá Jordán do moře na polední straně. To jest pomezí ku poledni.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 20, 'Jordán také je odděluje k straně východní. To jest dědictví synů Beniaminových s mezemi svými vůkol a vůkol po čeledech jejich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 21, 'A byla města tato pokolení synů Beniaminových po čeledech jejich: Jericho, Betogla a údolí Kasis;');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 22, 'A Betaraba, Semaraim a Bethel;');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 23, 'A Avim, též Afara a Ofra;');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 24, 'A Cefer, Hamona, Ofni a Gaba, měst dvanáct a vsi jejich;');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 25, 'Gabaon, Ráma a Berot;');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 26, 'Masfa, Kafira a Mosa;');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 27, 'Rekem, Jarefel a Tarela;');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 28, 'A Sela, Elef a Jebus, (jenž jest Jeruzalém,) Gibat, Kariat, měst čtrnácte i vsi jejich. To jest dědictví synů Beniaminových po čeledech jejich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 1, 'Potom padl los druhý Simeonovi, pokolení synů Simeonových, po čeledech jejich, a bylo dědictví jejich u prostřed dědictví synů Juda.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 2, 'A přišlo jim v dědictví jejich Bersabé, Seba a Molada;');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 3, 'Azarsual a Bala, též Esem;');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 4, 'Eltolad a Betul, a Horma;');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 5, 'Sicelech a Betmarchabot, a Azarsusa;');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 6, 'Betlebaot a Sarohem, měst třinácte i vsi jejich;');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 7, 'Ain, Remmon, též Eter a Asan, města čtyři i vsi jejich;');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 8, 'I všecky vsi, kteréž byly vůkolí měst těch, až do Balatber a Rámat poledního. To jest dědictví pokolení synů Simeonových po čeledech jejich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 9, 'Z podílu synů Judových bylo dědictví synů Simeonových; nebo díl synů Judových byl jim příliš veliký, protož u prostřed dědictví jejich vzali dědictví synové Simeonovi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 10, 'Potom přišel třetí los synům Zabulon po čeledech jejich, a jest meze dědictví jejich až do Sarid.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 11, 'Odkudž vstupuje meze jejich podlé moře k Merala, a přichází až do Debaset, a běží až ku potoku, kterýž jest proti Jekonam.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 12, 'Obrací se pak od Sarid nazpátek k východu slunce, ku pomezí Chazelet Tábor, a odtud táhne se k Daberet, a vstupuje do Jafie.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 13, 'Odtud přechází zase k východu, do Gethefer a do Itakasin, odkudž vychází do Remmon, a točí se k Nea.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 14, 'Točí se také táž meze od půlnoci do Anaton, a dochází až k údolí Jeftael;');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 15, 'A Katet, Naalol, Simron, Idala a Betlém, měst dvanácte i vsi jejich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 16, 'To jest dědictví synů Zabulonových po čeledech jejich, ta města i vsi jejich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 17, 'Izacharovi také padl los čtvrtý, totiž synům Izacharovým po čeledech jejich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 18, 'A meze jejich: Jezreel, Kasalat a Sunem;');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 19, 'Hafaraim, Sion, též Anaharat;');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 20, 'Rabbot, Kesion a Abez,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 21, 'Ramet, Engannim a Enhada, i Betfeses.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 22, 'Odkudž přibíhá meze k Táboru a k Sehesima a k Betsemes, a dochází až k Jordánu, měst šestnácte i vsi jejich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 23, 'To jest dědictví pokolení synů Izacharových po čeledech jejich, ta města i vsi jejich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 24, 'Padl také los pátý pokolení synů Asser po čeledech jejich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 25, 'A byla meze jejich: Helkat a Chali, a Beten, a Achzaf;');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 26, 'Elmelech, též Amaad a Mesal, a přibíhá až na Karmel k moři, a do Sichor Libnat;');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 27, 'A obrací se k východu slunce do Betdagon, a dosahá k losu Zabulonovu, a do údolí Jeftael k půlnoci, a do Betemek a Nehiel, a táhne se do Kábul na levou stranu,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 28, 'A do Ebron a Rohob, a Hamon a Kána až do Sidonu velikého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 29, 'Odtud se navrací ta meze do Ráma až k městu hrazenému Zor; tu se obrací do Chosa, a skonává se při moři podlé vyměření v Achziba.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 30, 'K tomu přísluší Afek a Rohob, měst dvamecítma i vsi jejich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 31, 'To jest dědictví pokolení synů Asser po čeledech jejich, ta města i vsi jejich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 32, 'Synům Neftalímovým padl los šestý, po čeledech jejich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 33, 'A byla meze jejich od Helef a od Elon do Sananim, a Adami, Nekeb a Jebnael, až do Lekum, a skonává se u Jordánu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 34, 'Potom navracuje se meze na západ k Azanot Tábor, a odtud jde do Hukuka, a vpadá k losu Zabulonovu od poledne, a k Asserovu přibíhá od západu, a k Judovu při Jordánu na východ slunce.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 35, 'Města pak hrazená jsou: Assedim, Ser a Emat, Rechat a Ceneret;');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 36, 'Adama, Ráma a Azor;');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 37, 'Kedes, Edrei a Enazor;');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 38, 'Jeron, Magdalel, Horem, Betanat a Betsemes, měst devatenácte i vsi jejich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 39, 'To jest dědictví pokolení synů Neftalím po čeledech jejich, ta města s vesnicemi svými.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 40, 'Na pokolení synů Dan po čeledech jejich padl los sedmý.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 41, 'A byla meze dědictví jejich: Zaraha a Estaol, a Hirsemes;');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 42, 'Salbin, Aialon a Jetela;');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 43, 'Elon, Tamna a Ekron;');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 44, 'Elteke, Gebbeton a Baalat;');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 45, 'Jehud, Beneberak a Getremmon;');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 46, 'Mehaiarkon a Rakon s pomezím, kteréž jest naproti Joppe.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 47, 'Přišlo pak pomezí synům Dan příliš malé. Protož vstoupili synové Dan, a bojovali proti Lesen, a dobyvše ho, pobili obyvatele ostrostí meče, a vzavše je v dědictví, bydlili tam, a přezděli Lesenu Dan, vedlé jména Dan otce svého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 48, 'To jest dědictví pokolení synů Dan po čeledech jejich, ta města i vsi jejich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 49, 'Když pak přestali děliti se zemí po mezech jejích, dali synové Izraelští dědictví Jozue, synu Nun, mezi sebou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 50, 'Podlé rozkázaní Hospodinova dali jemu město, kteréhož žádal, Tamnatsára, na hoře Efraim. I vystavěl město, a přebýval v něm.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 51, 'Ta jsou dědictví, kteráž dali k vládařství Eleazar kněz a Jozue syn Nun, i přední z otců pokolení synů Izraelských, losem v Sílo před Hospodinem, u dveří stánku úmluvy, a tak dokonali rozdělování země.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 20, 1, 'I mluvil Hospodin k Jozue, řka:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 20, 2, 'Mluv k synům Izraelským, a rci jim: Oddejte z těch měst vašich města útočišťná, o nichž jsem mluvil vám skrze Mojžíše,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 20, 3, 'Aby tam utekl vražedlník, kterýž by zabil člověka nechtě a z nevědomí. I budou vám útočiště před přítelem zabitého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 20, 4, 'A když by utekl do jednoho z těch měst, stane u vrat v bráně města, a oznámí starším města toho při svou; i přijmou ho do města k sobě, a dají mu místo, i bydliti bude u nich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 20, 5, 'Když by jej pak honil přítel toho zabitého, nevydají vražedlníka v ruce jeho; nebo nechtě udeřil bližního svého, neměv ho prvé v nenávisti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 20, 6, 'A bydliti bude v městě tom, dokudž nestane před shromážděním k soudu, až do smrti kněze velikého, kterýž by byl toho času; nebo tehdáž navrátí se vražedlník, a přijde do města svého a do domu svého, do města, odkudž utekl.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 20, 7, 'I oddělili Kádes v Galilei na hoře Neftalím, a Sichem na hoře Efraim, a město Arbe, (jenž jest Hebron,) na hoře Juda.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 20, 8, 'Před Jordánem pak proti Jerichu k východu oddělili Bozor, kteréž leží na poušti v rovině pokolení Rubenova, a Rámot v Galád z pokolení Gádova, a Golan v Bázan z pokolení Manassesova.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 20, 9, 'Ta města byla útočišťná všechněm synům Izraelským, i příchozímu, kterýž pohostinu jest mezi nimi, aby utekl tam, kdo by koli zabil někoho nechtě, a nesešel od ruky přítele toho zabitého prvé, než by stál před shromážděním.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 1, 'Přistoupili pak přední z otců Levítského pokolení k Eleazarovi knězi, a k Jozue, synu Nun, a k předním z otců pokolení synů Izraelských,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 2, 'A mluvili k nim v Sílo, v zemi Kananejské, řkouce: Hospodin přikázal skrze Mojžíše, abyste nám dali města k přebývání, i podměstí jejich pro dobytky naše.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 3, 'Dali tedy synové Izraelští Levítům z dědictví svého, vedlé rozkázaní Hospodinova, města tato i podměstí jejich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 4, 'Padl pak los čeledem Kahat, i dáno losem synům Arona kněze, Levítům, z pokolení Juda, a z pokolení Simeon, i z pokolení Beniaminova měst třinácte.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 5, 'A jiným synům Kahat, z čeledí pokolení Efraimova, a z pokolení Danova, a z polovice pokolení Manassesova losem dáno měst deset.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 6, 'Synům pak Gerson, z čeledí pokolení Izacharova, a z pokolení Asserova, též z pokolení Neftalímova, a z polovice pokolení Manassesova v Bázan losem dáno měst třinácte.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 7, 'Synům Merari po čeledech jejich, z pokolení Rubenova a z pokolení Gádova, též z pokolení Zabulonova měst dvanácte.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 8, 'Dali tedy synové Izraelští Levítům ta města i předměstí jejich, (jakož přikázal Hospodin skrze Mojžíše,) losem.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 9, 'A tak z pokolení synů Judových, a z pokolení synů Simeonových dána jsou města, kterýchž tuto jména jsou položena.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 10, 'A dostal se první díl synům Aronovým, z čeledí Kahat, z synů Léví; nebo jim padl los první.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 11, 'Dáno jest tedy jim město Arbe, otce Enakova, (jenž jest Hebron,) na hoře Juda, a předměstí jeho vůkol něho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 12, 'Ale pole města toho i vsi jeho dali Kálefovi synu Jefone k vládařství jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 13, 'Synům tedy Arona kněze dali město útočišťné vražedlníku, Hebron i předměstí jeho, a Lebno i předměstí jeho;');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 14, 'A Jeter s předměstím jeho, též Estemo a předměstí jeho;');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 15, 'Holon i předměstí jeho, a Dabir s podměstím jeho;');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 16, 'Také Ain s předměstím jeho, a Juta s podměstím jeho, i Betsemes a předměstí jeho, měst devět z toho dvojího pokolení.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 17, 'Z pokolení pak Beniaminova dali Gabaon a předměstí jeho, a Gaba s předměstím jeho;');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 18, 'Též Anatot a podměstí jeho, i Almon s předměstím jeho, města čtyři.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 19, 'Všech měst synů Aronových kněží třinácte měst s předměstími jejich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 20, 'Čeledem pak synů Kahat, Levítům, kteříž pozůstali z synů Kahat, (byla pak města losu jejich z pokolení Efraim,)');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 21, 'Dali jim město útočišťné vražedlníku, Sichem i předměstí jeho, na hoře Efraim, a Gázer s předměstím jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 22, 'Též Kibsaim a předměstí jeho, a Betoron s předměstím jeho, města čtyři.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 23, 'Z pokolení pak Dan: Elteke a předměstí jeho, a Gebbeton s předměstím jeho;');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 24, 'Též Aialon a předměstí jeho, a Getremmon s podměstím jeho, města čtyři.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 25, 'Z polovice pak pokolení Manassesova: Tanach a podměstí jeho, a Getremmon s předměstím jeho, města dvě.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 26, 'Všech měst deset s předměstími jejich čeledem synům Kahat ostatním.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 27, 'Synům také Gersonovým, z čeledí Levítských, z polovice pokolení Manassesova dali město útočišťné vražedlníku, Golan v Bázan a předměstí jeho, a Bozran s předměstím jeho, města dvě.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 28, 'Z pokolení Izacharova: Kesion a podměstí jeho, a Daberet s předměstím jeho;');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 29, 'Jarmut a předměstí jeho, a Engannim s předměstím jeho, města čtyři.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 30, 'Z pokolení pak Asserova: Mesal a předměstí jeho, též Abdon a podměstí jeho;');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 31, 'Helkat s předměstím jeho, a Rohob s podměstím jeho, města čtyři.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 32, 'Z pokolení také Neftalímova: Město útočišťné vražedlníku, Kedes v Galilei a předměstí jeho, a Hamotdor s předměstím jeho, a Kartam s předměstím jeho, města tři.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 33, 'Všech měst Gersonitských po čeledech jejich, třinácte měst s předměstími jejich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 34, 'Čeledem pak synů Merari, Levítům ostatním, dali z pokolení Zabulonova Jekonam a předměstí jeho, Karta a předměstí jeho;');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 35, 'Damna a předměstí jeho, Naalol a předměstí jeho, města čtyři.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 36, 'Z pokolení pak Rubenova: Bozor a předměstí jeho, a Jasa a předměstí jeho;');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 37, 'Kedemot a předměstí jeho, a Mefat s podměstím jeho, města čtyři.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 38, 'A z pokolení Gádova: Město útočišťné vražedlníku, Rámot v Galád a předměstí jeho, a Mahanaim s předměstím jeho;');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 39, 'Ezebon a podměstí jeho, Jazer s podměstím jeho, města čtyři.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 40, 'Všech měst synů Merari po čeledech jejich, kteříž ostatní byli z čeledí Levítských, bylo podlé losu jejich měst dvanácte.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 41, 'A tak všech měst Levítských u prostřed vládařství synů Izraelských měst čtyřidceti osm s předměstími svými.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 42, 'Mělo pak to město jedno každé obzvláštně svá předměstí vůkol sebe, a taková byla všecka ta města.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 43, 'Dal tedy Hospodin Izraelovi všecku tu zemi, kterouž s přísahou zaslíbil dáti otcům jejich; i opanovali ji dědičně, a bydlili v ní.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 44, 'Dal také Hospodin jim odpočinutí se všech stran podlé všeho, jakž byl s přísahou zaslíbil otcům jejich, aniž kdo byl, ješto by ostál proti nim ze všech nepřátel jejich; všecky nepřátely jejich dal Hospodin v ruku jejich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 45, 'Nepominulo ani jedno slovo ze všelikého slova dobrého, kteréž mluvil Hospodin k domu Izraelskému, ale všecko se tak stalo.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 1, 'Toho času povolav Jozue Rubenitských, Gáditských a polovice pokolení Manassesova,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 2, 'Řekl jim: Vy jste ostříhali všeho, což přikázal vám Mojžíš, služebník Hospodinův, a poslouchali jste hlasu mého ve všem, což jsem přikázal vám.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 3, 'Neopustili jste bratří svých již za dlouhý čas až do dne tohoto, ale bedlivě jste ostříhali přikázaní Hospodina Boha vašeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 4, 'Nyní pak již odpočinutí dal Hospodin Bůh váš bratřím vašim, jakož mluvil jim; již tedy navraťte se a beřte se do stanů svých, do země vládařství svého, kteréž vám dal Mojžíš, služebník Hospodinův, před Jordánem.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 5, 'Toliko hleďte pilně zachovávati a plniti přikázaní a zákon, kterýž přikázal vám Mojžíš, služebník Hospodinův, a milovati Hospodina Boha svého a choditi po všech cestách jeho, a zachovávajíce přikázaní jeho, přídržeti se ho, a sloužiti jemu celým srdcem svým a celou duší svou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 6, 'A požehnav jim Jozue, propustil je; i odešli do stanů svých.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 7, '(Polovici pak pokolení Manassesova dal byl Mojžíš dědictví v Bázan, a druhé polovici jeho dal Jozue s bratřími jejich za Jordánem k západu.) A když je propouštěl Jozue do stanů jejich, požehnal jim,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 8, 'A mluvil k nim, řka: S bohatstvím velikým navracujete se do stanů svých a s dobytky velmi mnohými, s stříbrem a zlatem, s mědí a železem a rouchem velmi mnohým; rozděltež se loupeží nepřátel svých s bratřími svými.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 9, 'Tedy navracujíce se, odešli synové Rubenovi a synové Gádovi a polovice pokolení Manassesova od synů Izraelských z Sílo, jenž jest v zemi Kananejské, aby šli do země Galád, do země vládařství svého, v kteréž dědictví obdrželi, vedlé řeči Hospodinovy skrze Mojžíše.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 10, 'A přišedše ku pomezí při Jordánu, kteréž jest v zemi Kananejské, i vzdělali tu synové Rubenovi, a synové Gádovi, a polovice pokolení Manassesova oltář nad Jordánem, oltář veliký ku podivení.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 11, 'Uslyšeli pak synové Izraelští, že praveno bylo: Aj, vystavěli synové Rubenovi a synové Gádovi, a polovice pokolení Manassesova oltář naproti zemi Kananejské, při pomezi u Jordánu, kdež přešli synové Izraelští.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 12, 'Uslyševše, pravím, synové Izraelští, sešlo se všecko množství jejich do Sílo, aby táhli proti nim k boji.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 13, 'I poslali synové Izraelští k synům Rubenovým a k synům Gádovým a ku polovici pokolení Manassesova do země Galád Fínesa, syna Eleazara kněze,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 14, 'A deset knížat s ním, po jednom knížeti z každého domu otcovského, ze všech pokolení Izraelských. (Každý pak z nich byl přední v domě otců svých v tisících Izraele.)');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 15, 'Ti přišli k synům Rubenovým a k synům Gádovým a ku polovici pokolení Manassesova do země Galád, a mluvili s nimi, řkouce:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 16, 'Toto praví všecko shromáždění Hospodinovo: Jaké jest to přestoupení, jímž jste přestoupili proti Bohu Izraelskému, odvrátivše se dnes, abyste nešli za Hospodinem, vzdělavše sobě oltář, abyste se protivili dnes Hospodinu?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 17, 'Ještě-liž se nám malá zdá nepravost modly Fegor, od níž nejsme očištěni až do dnes, pročež byla rána v shromáždění Hospodinovu,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 18, 'Že vy přes to odvracujete se dnes, abyste nešli za Hospodinem? I stane se, poněvadž vy dnes odporujete Hospodinu, že on zítra na všecko shromáždění Izraelské rozhněvá se.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 19, 'Jestližeť jest nečistá země vládařství vašeho, přejděte do země vládařství Hospodinova, v níž přebývá stánek Hospodinův, a dědictví vezměte mezi námi; toliko proti Hospodinu se nepostavujte, a nebuďte odporní nám, stavějíce sobě oltář mimo oltář Hospodina Boha našeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 20, 'Zdali Achan syn Záre nedopustil se přestoupení při věci proklaté? A přišlo rozhněvání na všecko shromáždění Izraelské, a on sám jeden zhřešiv, nezahynul pro svou nepravost sám.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 21, 'I odpověděli synové Rubenovi a synové Gádovi a polovice pokolení Manassesova, a mluvili s knížaty tisíců Izraelských:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 22, 'Silný Bůh Hospodin, silný Bůh Hospodin, onť ví, ano sám Izrael pozná, žeť jsme ne z zpoury a všetečnosti proti Hospodinu to učinili, jináč nezachovávejž nás ani dne tohoto.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 23, 'Jistě žeť jsme nestavěli sobě oltáře k tomu, abychom se odvrátiti měli a nejíti za Hospodinem, ani k obětování na něm zápalů a obětí suchých, a k obětování na něm obětí pokojných, sic jináč Hospodin sám ať to vyhledává.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 24, 'Anobrž raději obávajíce se té věci, učinili jsme to, myslíce: Potom mluviti budou synové vaši synům našim, řkouce: Co vám do Hospodina Boha Izraelského?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 25, 'Poněvadž meze položil Hospodin mezi námi a vámi, ó synové Rubenovi a synové Gádovi, Jordán tento, nemáte vy dílu v Hospodinu. I odvrátí synové vaši syny naše od bázně Hospodinovy.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 26, 'Protož jsme řekli: Přičiňme se a vzdělejme oltář, ne pro zápaly a oběti,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 27, 'Ale aby byl svědkem mezi námi a vámi, a mezi potomky našimi po nás, k vykonávání služby Hospodinu před ním zápaly našimi, a obětmi našimi a pokojnými obětmi našimi, a aby neřekli potom synové vaši synům našim: Nemáte dílu v Hospodinu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 28, 'Protož jsme řekli: Jestliže by potom mluvili nám neb potomkům našim, tedy odpovíme: Vizte podobenství oltáře Hospodinova, kterýž učinili otcové naši, ne pro zápaly ani oběti, ale aby byl na svědectví mezi námi a vámi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 29, 'Odstup to od nás, abychom odporovati měli Hospodinu, a odvraceti se dnes a nejíti za Hospodinem, stavějíce oltář k zápalům, k obětem suchým a jiným obětem, mimo oltář Hospodina Boha našeho, kterýž jest před stánkem jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 30, 'Uslyšev pak Fínes kněz a knížata shromáždění a přední z tisíců Izraelských, kteříž s ním byli, slova, kteráž mluvili synové Rubenovi a synové Gádovi a synové Manassesovi, líbilo se jim.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 31, 'I řekl Fínes, syn Eleazara kněze, synům Rubenovým a synům Gádovým, i synům Manassesovým: Nyní jsme poznali, že u prostřed nás jest Hospodin, a že jste se nedopustili proti Hospodinu přestoupení toho, a tak vysvobodili jste syny Izraelské z ruky Hospodinovy.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 32, 'Tedy navrátil se Fínes, syn Eleazara kněze, i ta knížata od synů Rubenových a od synů Gádových z země Galád do země Kananejské k synům Izraelským a oznámili jim tu věc.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 33, 'I líbilo se to synům Izraelským, a dobrořečili Boha synové Izraelští, a již více nemluvili o to, aby táhli proti nim k boji a zkazili zemi, v kteréž synové Rubenovi a synové Gádovi bydlili.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 34, 'Nazvali pak synové Rubenovi a synové Gádovi oltář ten Ed, řkouce: Nebo svědkem bude mezi námi, že Hospodin jest Bůh.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 1, 'I stalo se po mnohých dnech, když dal Hospodin odpočinutí Izraelovi ode všech nepřátel jejich vůkol, a Jozue se sstaral a sešel věkem,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 2, 'Že povolav Jozue všeho Izraele, starších jeho i předních jeho soudců i správců jeho, řekl jim: Já jsem se sstaral a sešel věkem.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 3, 'A vy jste viděli všecko to, co jest učinil Hospodin Bůh váš všechněm národům těm před oblíčejem vaším; nebo Hospodin Bůh váš onť bojoval za vás.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 4, 'Pohleďte, losem rozdělil jsem vám ty národy pozůstalé v dědictví po pokoleních vašich od Jordánu, i všecky národy, kteréž jsem vyplénil až k moři velikému na západ slunce.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 5, 'Hospodin pak Bůh váš onť je vyžene od tváři vaší, a vypudí je před oblíčejem vaším, a vy dědičně obdržíte zemi jejich, jakož mluvil vám Hospodin Bůh váš.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 6, 'Protož zmužile se mějte, abyste ostříhali a činili všecko, což psáno jest v knize zákona Mojžíšova, a neodstupovali od něho na pravo ani na levo.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 7, 'Nesměšujte se s těmi národy, kteříž pozůstávají s vámi, a jména bohů jejich nepřipomínejte, ani skrze ně přisahejte, aniž jim služte, ani se jim klanějte.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 8, 'Ale přídržte se Hospodina Boha svého, jakož jste činili až do tohoto dne.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 9, 'I budeť, že jakož jest vyhnal Hospodin od tváři vaší národy veliké a silné, aniž ostál kdo před oblíčejem vaším až do tohoto dne:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 10, 'Tak jeden z vás honiti bude tisíc, nebo Hospodin Bůh váš onť bojuje za vás, jakož mluvil vám.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 11, 'Toho tedy nejpilnější buďte, abyste milovali Hospodina Boha svého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 12, 'Nebo jestliže předce se odvrátíte, a připojíte se k těm pozůstalým národům, k těm, kteříž zůstávají mezi vámi, a vejdete s nimi v příbuzenství a smísíte se s nimi a oni s vámi:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 13, 'Tedy jistotně vězte, že Hospodin Bůh váš nebude více vyháněti všech národů těch od tváři vaší, ale budou vám osídlem a úrazem i bičem na bocích vašich, a trním v očích vašich, dokudž nezahynete z země této výborné, kterouž vám dal Hospodin Bůh váš.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 14, 'A hle, já nyní odcházím podlé způsobu všech lidí, poznejtež tedy vším srdcem svým a celou duší svou, že nepochybilo ani jedno slovo ze všech slov nejlepších, kteráž mluvil Hospodin Bůh váš o vás; všecko se naplnilo vám, ani jediné slovo z nich nepominulo.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 15, 'Jakož tedy naplnilo se vám dnes každé slovo dobré, kteréž mluvil k vám Hospodin Bůh váš, takť uvede na vás každé slovo zlé, dokudž nevyhladí vás z země této výborné, kterouž dal vám Hospodin Bůh váš,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 16, 'Jestliže přestoupíte smlouvu Hospodina Boha svého, kterouž přikázal vám, a jdouce, sloužiti budete bohům cizím, a klaněti se jim. I rozhněvá se prchlivost Hospodinova na vás, a zahynete rychle z země této výborné, kterouž vám dal.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 1, 'Shromáždil pak Jozue všecka pokolení Izraelská v Sichem a svolal starší Izraelské a přední z nich, i soudce a správce jejich, i postavili se před oblíčejem Božím.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 2, 'I řekl Jozue všemu lidu: Toto praví Hospodin Bůh Izraelský: Za řekou bydlili otcové vaši za starodávna, jmenovitě Táre, otec Abrahamův a otec Náchorův, a sloužili bohům cizím.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 3, 'I vzal jsem otce vašeho Abrahama z místa, kteréž jest za řekou, a provedl jsem jej skrze všecku zemi Kananejskou, a rozmnožil jsem símě jeho, dav jemu Izáka.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 4, 'A Izákovi dal jsem Jákoba a Ezau. I dal jsem Ezau horu Seir, aby vládl jí; Jákob pak a synové jeho sstoupili do Egypta.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 5, 'I poslal jsem Mojžíše a Arona, a zbil jsem Egypt, a když jsem to učinil u prostřed něho, potom vyvedl jsem vás.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 6, 'A vyvedl jsem otce vaše z Egypta, i přišli jste k moři, a honili Egyptští otce vaše s vozy a jezdci až k moři Rudému.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 7, 'Tedy volali k Hospodinu, kterýž postavil mrákotu mezi vámi a Egyptskými, a uvedl na ně moře, i zatopilo je; anobrž viděly oči vaše i to, co jsem učinil při Egyptu, a bydlili jste na poušti za dlouhý čas.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 8, 'Potom uvedl jsem vás do země Amorejského, kterýž bydlil za Jordánem, a bojovali s vámi; i dal jsem je v ruku vaši, a opanovali jste zemi jejich, a zahladil jsem je před tváří vaší.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 9, 'Povstal pak Balák syn Seforův, král Moábský, a bojoval s Izraelem; i poslav, povolal Baláma syna Beorova, aby zlořečil vám.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 10, 'Ale nechtěl jsem slyšeti Baláma, pročež stále dobrořečil vám, a tak vysvobodil jsem vás z ruky jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 11, 'A když jste přešli Jordán, přišli jste k Jerichu; i bojovali proti vám muži Jericha, Amorejští, a Ferezejští, a Kananejští, a Hetejští, a Gergezejští, a Hevejští, a Jebuzejští, a dal jsem je v ruku vaši.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 12, 'Poslal jsem před vámi i sršně, kteřížto vyhnali je od tváři vaší, dva krále Amorejské; ne mečem ani lučištěm svým tys je vyhnal.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 13, 'A dal jsem vám zemi, v níž jste nepracovali, a města, kterýchž jste nestavěli, v nichž bydlíte; vinic a olivoví, kteréhož jste neštípili, užíváte.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 14, 'Protož nyní bojte se Hospodina, a služte jemu v dokonalosti a v pravdě, a odvrzte bohy, jimž sloužili otcové vaši za řekou a v Egyptě, a služte Hospodinu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 15, 'Pakli se vám zdá zle sloužiti Hospodinu, vyvolte sobě dnes, komu byste sloužili, buď bohy, jimž sloužili otcové vaši, kteříž byli za řekou, buď bohy Amorejských, v jichž zemi bydlíte; jáť pak a dům můj sloužiti budeme Hospodinu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 16, 'Jemuž odpověděl lid, řka: Odstup to od nás, abychom opustiti měli Hospodina a sloužiti bohům cizím.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 17, 'Nebo Hospodin Bůh náš onť jest, kterýž vyvedl nás i otce naše z země Egyptské, z domu služebnosti, a kterýž činil před očima našima znamení ta veliká, a choval nás na vší cestě, po níž jsme šli, a mezi všemi národy, skrze něž jsme prošli.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 18, 'A vypudil Hospodin všecky národy, zvláště Amorejského, obyvatele země této, před tváří naší; my také sloužiti budeme Hospodinu, nebo on jest Bůh náš.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 19, 'I řekl Jozue lidu: Nebudete moci sloužiti Hospodinu, nebo Bůh svatý jest, Bůh silný horlivý jest, nesnese nepravostí vašich a hříchů vašich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 20, 'Jestliže byste opustíce Hospodina, sloužili bohům cizozemců, obrátí se a zle učiní vám, a zkazí vás, poněvadž prvé dobře učinil vám.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 21, 'Jemuž odpověděl lid: Nikoli, ale Hospodinu sloužiti budeme.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 22, 'I řekl Jozue lidu: Svědkové budete sami proti sobě, že jste sobě vyvolili Hospodina, abyste jemu sloužili. Tedy odpověděli: Svědkové jsme.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 23, 'Jimž on řekl: Odvrztež tedy nyní bohy cizozemců, kteříž jsou u prostřed vás, a nakloňte srdcí svých k Hospodinu Bohu Izraelskému.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 24, 'Odpověděl lid Jozue: Hospodinu Bohu našemu sloužiti a hlasu jeho poslouchati budeme.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 25, 'A tak učinil Jozue toho dne smlouvu s lidem, a předložil jim ustanovení a soudy v Sichem.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 26, 'A zapsal Jozue slova ta do knihy zákona Božího; vzav také kámen veliký, postavil jej tu pod dubem, kterýž byl u svatyně Hospodinovy.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 27, 'I řekl Jozue všemu lidu: Aj, kámen tento bude mezi námi na svědectví, nebo on slyšel všecka slova Hospodinova, kteráž mluvil s námi, a bude na svědectví proti vám, abyste snad neklamali proti Bohu svému.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 28, 'A rozpustil Jozue lid, jednoho každého do dědictví jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 29, 'I stalo se po vykonání těch věcí, že umřel Jozue syn Nun, služebník Hospodinův, jsa ve stu a desíti letech.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 30, 'A pochovali ho v krajině dědictví jeho, v Tamnatsáre, kteréž jest na hoře Efraim k straně půlnoční hory Gás.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 31, 'I sloužil Izrael Hospodinu po všecky dny Jozue, i po všecky dny starších, kteříž dlouho živi byli po Jozue, a kteříž povědomi byli všech skutků Hospodinových, kteréž učinil Izraelovi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 32, 'Kosti pak Jozefovy, kteréž byli vynesli synové Izraelští z Egypta, pochovali v Sichem, v dílu pole, kteréž koupil Jákob od synů Emora otce Sichemova za sto peněz; i byly u synů Jozefových v dědictví jejich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 33, 'Eleazar také, syn Aronův, umřel, a pochovali jej na pahrbku Fínesa syna jeho, kterýž dán byl jemu na hoře Efraim.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 1, 'Stalo se pak po smrti Jozue, otázali se synové Izraelští Hospodina, řkouce: Kdo z nás potáhne proti Kananejskému napřed, aby bojoval s ním?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 2, 'Jimž řekl Hospodin: Juda nechť táhne, aj, dal jsem tu zemi v ruku jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 3, '(Řekl pak byl Juda Simeonovi bratru svému: Potáhni se mnou k dobývání losu mého, abychom bojovali proti Kananejskému, a já také potáhnu s tebou k dobývání losu tvého. I táhl s ním Simeon.)');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 4, 'Tedy vytáhl Juda, i dal Hospodin Kananejského a Ferezejského v ruce jejich, a porazili z nich v Bezeku deset tisíc mužů.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 5, 'Nebo nalezše Adonibezeka v Bezeku, bojovali proti němu, a porazili Kananejského i Ferezejského.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 6, 'Když pak utíkal Adonibezek, honili ho, a chytivše jej, zutínali mu palce u rukou i noh.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 7, 'Tedy řekl Adonibezek: Sedmdesáte králů s uťatými palci u rukou i noh svých sbírali drobty pod stolem mým; jakž jsem činil, tak odplatil mi Bůh. I přivedli jej do Jeruzaléma, a tam umřel.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 8, 'Nebo byli vybojovali synové Juda Jeruzalém, a vzavše jej, zbili obyvatele jeho ostrostí meče a město vypálili.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 9, 'Potom také vytáhli synové Judovi, aby bojovali proti Kananejskému, bydlícímu na horách při straně polední i na rovinách.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 10, 'Nebo byl vytáhl Juda proti Kananejskému, kterýž bydlil v Hebronu, (jméno pak Hebronu prvé bylo Kariatarbe,) a pobil Sesaie, a Achimana, a Tolmaie.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 11, 'A odtud byl táhl na obyvatele Dabir, (jméno pak Dabir prvé bylo Kariatsefer).');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 12, 'Kdežto řekl Kálef: Kdo by dobyl Kariatsefer a vzal by je, dám jemu Axu dceru svou za manželku.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 13, 'Tedy dobyl ho Otoniel, syn Cenezův, bratra Kálefova mladšího, i dal jemu Axu dceru svou za manželku.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 14, 'Stalo se pak, že když přišla k němu, ponukla ho, aby prosil otce jejího za pole; i ssedla s osla. A řekl jí Kálef: Cožť jest?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 15, 'A ona odpověděla: Dej mi dar; poněvadžs mi dal zemi suchou, dej mi také studnice vod. I dal jí Kálef studnice v horních i dolních končinách.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 16, 'Synové také Cinejského, tchána Mojžíšova, odebrali se z města palmového s syny Juda na poušť Judovu, jenž jest k straně polední městu Arad; a odšedše, bydlili s lidem tím.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 17, 'Potom táhl Juda s Simeonem, bratrem svým, a porazili Kananejské přebývající v Sefat, a zkazili je. I nazváno jest jméno města toho Horma.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 18, 'Dobyl také Juda Gázy a pomezí jeho, i Aškalonu s pomezím jeho, též Akaronu a pomezí jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 19, 'Nebo byl Hospodin s Judou, a vyhnal obyvatele hor, ale nevyhnal obyvatelů údolí, proto že vozy železné měli.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 20, 'I dali Kálefovi Hebron, jakož byl mluvil Mojžíš, a vyhnal odtud tři syny Enakovy.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 21, 'Jebuzejského pak, bydlícího v Jeruzalémě, nevyhnali synové Beniamin; protož bydlil Jebuzejský v Jeruzalémě s syny Beniamin až do tohoto dne.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 22, 'Vytáhla také i čeled Jozefova do Bethel, a Hospodin byl s nimi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 23, 'Nebo shlédla čeled Jozefova Bethel, kteréhožto města jméno prvé bylo Lůza.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 24, 'Uzřevše pak ti špehéři muže vycházejícího z města, řekli jemu: Medle ukaž nám, kudy bychom mohli vjíti do města, a učinímeť milost.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 25, 'Kterýžto ukázal jim, kudy by mohli vjíti do města; i vyhubili to město mečem, muže pak toho se vší čeledí jeho propustili.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 26, 'I šel muž ten do země Hetejských, kdež vystavěl město, a nazval jméno jeho Lůza; to jest jméno jeho až do tohoto dne.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 27, 'Manasses také nevyhnal obyvatelů Betsan a městeček jeho, ani Tanach a městeček jeho, ani obyvatelů Dor a Jibleam, a Mageddo a městeček jejich; i počal Kananejský svobodně bydliti v zemi té.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 28, 'Když se pak zsilil Izrael, uvedl Kananejského pod plat, a maje jej vyhnati, nevyhnal.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 29, 'Efraim také nevyhnal Kananejského bydlícího v Gázer, protož bydlil Kananejský u prostřed něho v Gázer.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 30, 'Zabulon též nevyhnal obyvatelů Cetron, a obyvatelů Naalol, protož bydlil Kananejský u prostřed něho, a dával jemu plat.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 31, 'Asser také nevyhnal obyvatelů Acho a obyvatelů Sidonu, ani Ahalab, ani Achzib, ani Helba, ani Afek, ani Rohob.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 32, 'I bydlil Asser mezi Kananejskými obyvateli země té, nebo nevyhnal jich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 33, 'Též Neftalím nevyhnal obyvatelů Betsemes, ani obyvatelů Betanat, protož bydlil mezi Kananejskými přebývajícími v zemi té; a však obyvatelé Betsemes a Betanat dávali jim plat.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 34, 'Ssužovali pak Amorejští syny Dan na horách, tak že nedali jim scházeti do údolí.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 35, 'Nebo počal Amorejský svobodně bydliti na hoře Heres, v Aialon a v Salbim, ale když se zsilila ruka čeledi Jozefovy, uvedeni jsou pod plat.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 36, 'Pomezí pak Amorejského bylo od začátku hor Akrabim, od skály jejich i výše.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 1, 'Vstoupil pak anděl Hospodinův z Galgala do Bochim a řekl: Vyvedl jsem vás z Egypta a uvedl jsem vás do země, kterouž jsem s přísahou zaslíbil otcům vašim, a řekl jsem: Nezruším smlouvy své s vámi na věky.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 2, 'Vy také nečiňte smlouvy s obyvateli země této, oltáře jejich rozkopejte; ale neposlechli jste hlasu mého. Co jste to učinili?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 3, 'Pročež také jsem řekl: Nevyhladím jich před tváří vaší, ale budou vám jako trní, a bohové jejich budou vám osídlem.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 4, 'I stalo se, když mluvil anděl Hospodinův slova tato všechněm synům Izraelským, že pozdvihl hlasu svého lid a plakal.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 5, 'I nazvali jméno místa toho Bochim, a obětovali tu Hospodinu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 6, 'Rozpustil pak byl Jozue lid, a rozešli se synové Izraelští, jeden každý do dědictví svého, aby vládli zemí.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 7, 'I sloužil lid Hospodinu po všecky dny Jozue, a po všecky dny starších, kteříž dlouho živi byli po Jozue, jenž viděli všecky skutky veliké Hospodinovy, kteréž učinil Izraelovi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 8, 'Ale když umřel Jozue syn Nun, služebník Hospodinův, jsa ve stu a desíti letech,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 9, 'A pochovali ho v krajině dědictví jeho, v Tamnatheres, na hoře Efraim, k straně půlnoční hory Gás;');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 10, 'Také když všecken věk ten připojen jest k otcům svým, a povstal jiný věk po nich, kteříž neznali Hospodina, ani skutků, kteréž učinil Izraelovi:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 11, 'Tedy činili synové Izraelští to, což jest zlého před očima Hospodinovýma, a sloužili modlám,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 12, 'Opustivše Hospodina Boha otců svých, kterýž je vyvedl z země Egyptské, a odešli za bohy cizími, bohy těch národů, kteříž byli vůkol nich, a klaněli se jim; pročež popudili Hospodina.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 13, 'Nebo opustivše Hospodina, sloužili Bálovi i Astarotům.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 14, 'I rozpálila se prchlivost Hospodinova na Izraele, a vydal je v ruku loupežníků, kteříž je zloupili; vydal je, pravím, v ruku nepřátel jejich vůkol, tak že nemohli více ostáti před nepřátely svými.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 15, 'Kamžkoli vycházeli, ruka Hospodinova byla proti nim ke zlému, jakož byl mluvil Hospodin, a jakož byl zapřisáhl jim Hospodin; i ssouženi byli náramně.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 16, 'Vzbuzoval pak Hospodin soudce, kteříž vysvobozovali je z rukou zhoubců jejich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 17, 'Ale ani soudců svých neposlouchali, nebo smilnili, odcházejíce za bohy cizími, a klaněli se jim. Odcházeli rychle s cesty, po kteréž chodili otcové jejich, tak že poslouchati majíce přikázaní Hospodinových, nečinili toho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 18, 'A když vzbuzoval jim Hospodin soudce, býval Hospodin s každým soudcím, a vysvobozoval je z ruky nepřátel jejich po všecky dny soudce; (nebo želel Hospodin naříkání jejich, k němuž je přivodili ti, kteříž je ssužovali a utiskali).');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 19, 'Po smrti pak soudce navracejíce se zase, pohoršovali cest svých více nežli otcové jejich, odcházejíce za bohy cizími, a sloužíce i klanějíce se jim; nic neulevili z skutků jejich zlých a cesty jejich převrácené.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 20, 'Protož rozpálila se prchlivost Hospodinova proti Izraelovi, a řekl: Proto že přestoupil národ tento smlouvu mou, kterouž jsem učinil s otci jejich, a neposlouchali hlasu mého:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 21, 'Já také více nevyhladím žádného od tváři jejich z národů, kterýchž zanechal Jozue, když umřel,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 22, 'Abych skrze ně zkušoval Izraele, budou-li ostříhati cesty přikázaní Hospodinových, chodíce v nich, jakož ostříhali otcové jejich, čili nic.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 23, 'I zanechal Hospodin národů těch, a nevyhnal jich rychle, aniž dal jich v ruku Jozue.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 1, 'Tito pak jsou národové, kterýchž zanechal Hospodin, aby skrze ně zkušoval Izraele, totiž všech, kteříž nevěděli o žádných válkách Kananejských,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 2, 'Aby aspoň zvěděli věkové synů Izraelských, a poznali, co jest to válka, čehož první nevěděli:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 3, 'Patero knížat Filistinských, a všickni Kananejští a Sidonští a Hevejští bydlící na hoře Libánské od hory Balhermon až tam, kudy se vchází do Emat.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 4, 'Ti pozůstali, aby zkušován byl skrze ně Izrael, a aby známé bylo, budou-li poslouchati přikázaní Hospodinových, kteráž přikázal otcům jejich skrze Mojžíše.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 5, 'Bydlili tedy synové Izraelští u prostřed Kananejských, Hetejských a Amorejských, a Ferezejských a Hevejských a Jebuzejských,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 6, 'A brali sobě dcery jejich za manželky, a dcery své dávali synům jejich, a sloužili bohům jejich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 7, 'Činili tedy synové Izraelští to, což jest zlého před očima Hospodinovýma, a zapomenuvše se na Hospodina Boha svého, sloužili Bálům a Asserotům.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 8, 'Protož rozpálila se prchlivost Hospodinova na Izraele, a vydal jej v ruku Chusana Risataimského, krále Syrského v Mezopotamii; i sloužili synové Izraelští Chusanovi Risataimskému osm let.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 9, 'Volali pak synové Izraelští k Hospodinu, i vzbudil Hospodin vysvoboditele synům Izraelským, aby je vysvobodil, Otoniele syna Cenezova bratra Kálefova mladšího,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 10, 'Na němž byl duch Hospodinův, a soudil lid Izraelský. Když pak vytáhl k boji, dal Hospodin v ruce jeho Chusana Risataimského, krále Syrského, a zmocnila se ruka jeho nad Chusanem Risataimským.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 11, 'A tak v pokoji byla země za čtyřidceti let; i umřel Otoniel, syn Cenezův.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 12, 'Takž opět činili synové Izraelští to, což jest zlého před očima Hospodinovýma. I zsilil Hospodin Eglona, krále Moábského, proti Izraelovi, proto že činili zlé věci před očima Hospodinovýma.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 13, 'Nebo shromáždil k sobě syny Ammonovy a Amalechovy, a vytáh, porazil Izraele, a opanovali město palmové.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 14, 'I sloužili synové Izraelští Eglonovi králi Moábskému osmnácte let.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 15, 'Potom volali synové Izraelští k Hospodinu. I vzbudil jim Hospodin vysvoboditele Ahoda, syna Gery Beniaminského, muže rukou pravou nevládnoucího. I poslali synové Izraelští po něm dar Eglonovi králi Moábskému.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 16, '(Připravil pak sobě Ahod meč na obě straně ostrý, lokte zdélí, a připásal jej sobě pod šaty svými po pravé straně.)');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 17, 'I přinesl dar Eglonovi králi Moábskému. Eglon pak byl člověk velmi tlustý.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 18, 'A když dodal daru, propustil lid, kterýž byl přinesl dar.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 19, 'Sám pak vrátiv se od lomů blízko Galgala, řekl: Tajnou věc mám k tobě, ó králi. I řekl král: Mlč. A vyšli od něho všickni, kteříž stáli při něm.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 20, 'Tehdy Ahod přistoupil k němu, (on pak seděl na paláci letním sám). I řekl mu Ahod: Řeč Boží mám k tobě. I vstal z stolice své.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 21, 'Tedy sáhna Ahod rukou svou levou, vzal meč u pravého boku svého a vrazil jej do břicha jeho,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 22, 'Tak že i jilce za ostřím vešly tam, a zavřel se tukem meč, (nebo nevytáhl meče z břicha jeho;) i vyšla lejna.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 23, 'Potom vyšel Ahod přes síň, a zavřel dvéře paláce po sobě, a zamkl.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 24, 'Když pak on odšel, služebníci jeho přišedše, uzřeli, a hle, dvéře palácu zamčíny. Tedy řekli: Jest na potřebě v pokoji letním.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 25, 'A když očekávali dlouho, až se styděli, a aj, neotvíral dveří paláce, tedy vzali klíč a otevřeli, a hle, pán jejich leží na zemi mrtvý.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 26, 'Ahod pak mezi tím, když oni prodlévali, ušel, a přešed lomy, přišel do Seirat.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 27, 'A přišed k svým, troubil v troubu na hoře Efraim; i sstoupili s ním synové Izraelští s hory, a on napřed šel.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 28, 'Nebo řekl jim: Poďte za mnou, dalť jest zajisté Hospodin Moábské, nepřátely vaše, v ruku vaši. Tedy táhli za ním, a vzavše Moábským brody Jordánské, nedali žádnému přejíti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 29, 'I pobili tehdáž Moábských okolo desíti tisíc mužů, každého bohatého a všelikého silného muže, aniž kdo ušel.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 30, 'I snížen jest Moáb v ten den pod mocí Izraele, a pokoj měla země za osmdesáte let.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 31, 'Po něm pak byl Samgar, syn Anatův, a pobil Filistinských šest set mužů ostnem volů, a vysvobodil i on Izraele.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 1, 'Po smrti pak Ahoda činili opět synové Izraelští to, což jest zlého před očima Hospodinovýma.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 2, 'I vydal je Hospodin v ruce Jabína krále Kananejského, kterýž kraloval v Azor; (a kníže vojska jeho byl Zizara,) sám pak bydlil v Haroset pohanském.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 3, 'Tedy volali synové Izraelští k Hospodinu; nebo devět set vozů železných měl, a on násilně ssužoval Izraele za dvadceti let.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 4, 'Debora pak žena prorokyně, manželka Lapidotova, soudila lid Izraelský toho času.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 5, '(A bydlila Debora pod palmou, mezi Ráma a mezi Bethel na hoře Efraim), i chodili k ní synové Izraelští k soudu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 6, 'Kterážto poslavši, povolala Baráka, syna Abinoemova, z Kádes Neftalímova, a řekla jemu: Zdaližť nerozkázal Hospodin Bůh Izraelský: Jdi, a shromáždě lid na horu Tábor, vezmi s sebou deset tisíc mužů z synů Neftalím a z synů Zabulon.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 7, 'Nebo přitáhnu k tobě ku potoku Císon Zizaru kníže vojska Jabínova, a vozy jeho i množství jeho, a dám jej v ruku tvou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 8, 'I řekl jí Barák: Půjdeš-li se mnou, půjdu; pakli nepůjdeš se mnou, nepůjdu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 9, 'Kteráž odpověděla: Jáť zajisté půjdu s tebou, ale nebudeť s slávou tvou cesta, kterouž půjdeš, nebo v ruku ženy dá Hospodin Zizaru. Tedy vstavši Debora, šla s Barákem do Kádes.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 10, 'Svolav pak Barák Zabulonské a Neftalímské do Kádes, vyvedl za sebou deset tisíc mužů; a šla s ním i Debora.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 11, 'Heber pak Cinejský oddělil se od Kaina, od synů Chobab, tchána Mojžíšova, a rozbil stany své až k Elon v Sananim, jenž jest v Kádes.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 12, 'Oznámeno pak bylo Zizarovi, že vytáhl Barák syn Abinoemův na horu Tábor.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 13, 'Protož shromáždil Zizara všecky vozy své, devět set vozů železných, a všecken lid, kterýž měl s sebou z Haroset pohanského, ku potoku Císon.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 14, 'I řekla Debora Barákovi: Vstaň, nebo tento jest den, v němž dal Hospodin Zizaru v ruku tvou. Zdali Hospodin nevyšel před tebou? I sstoupil Barák s hory Tábor, a deset tisíc mužů za ním.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 15, 'A porazil Hospodin Zizaru a všecky ty vozy, i všecka ta vojska ostrostí meče před Barákem; a sskočiv Zizara s vozu, utíkal pěšky.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 16, 'Ale Barák honil ty vozy a vojsko až do Haroset pohanského; i padlo všecko vojsko Zizarovo od ostrosti meče, tak že nezůstalo ani jednoho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 17, 'Zizara pak utíkal pěšky k stanu Jáhel, manželky Hebera Cinejského; nebo pokoj byl mezi Jabínem králem Azor a mezi čeledí Hebera Cinejského.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 18, 'I vyšedši Jáhel v cestu Zizarovi, řekla jemu: Uchyl se, pane můj, uchyl se ke mně, neboj se. I uchýlil se k ní do stanu, a přistřela jej huní.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 19, 'Kterýž řekl jí: Dej mi, prosím, píti maličko vody, nebo žízním. A otevřevši nádobu mléčnou, dala mu píti a přikryla ho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 20, 'Řekl také jí: Stůj u dveří stanu, a přišel-li by kdo, a ptal se tebe, řka: Jest-li zde kdo? odpovíš: Není.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 21, 'Potom vzala Jáhel manželka Heberova hřeb od stanu, vzala též kladivo v ruku svou, a všedši k němu tiše, vrazila hřeb do židovin jeho, až uvázl v zemi; (nebo ustav, tvrdě byl usnul,) a tak umřel.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 22, 'A aj, Barák honil Zizaru. I vyšla Jáhel vstříc jemu, a řekla mu: Poď, a ukážiť muže, kteréhož hledáš. I všel k ní, a aj, Zizara ležel mrtvý na zemi, a hřeb v židovinách jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 23, 'A tak ponížil Bůh toho dne Jabína krále Kananejského před syny Izraelskými.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 24, 'I dotírala ruka synů Izraelských vždy více, a silila se proti Jabínovi králi Kananejskému, až i vyhladili téhož Jabína krále Kananejského.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 1, 'Zpívala pak písničku Debora a Barák syn Abinoemův v ten den, řkouc:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 2, 'Pro pomstu učiněnou v Izraeli, a pro lid, kterýž se k tomu dobrovolně měl, dobrořečte Hospodinu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 3, 'Slyštež králové, a ušima pozorujte knížata, já, já zpívati budu Hospodinu, žalmy zpívati budu Hospodinu Bohu Izraelskému.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 4, 'Hospodine, když jsi vyšel z Seir, když jsi se bral z pole Edomského, třásla se země, nebesa dštila, a oblakové déšť vydali.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 5, 'Hory se rozplynuly od tváři Hospodinovy, i ta hora Sinai třásla se před tváří Hospodina Boha Izraelského.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 6, 'Za dnů Samgara syna Anatova, a za dnů Jáhel spustly silnice, kteříž pak šli stezkami, zacházeli cestami křivými.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 7, 'Spustly vsi v Izraeli, spustly, pravím, až jsem povstala já Debora, povstala jsem matka v Izraeli.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 8, 'Kterýžto kdyžkoli sobě zvoloval bohy nové, tedy bývala válka v branách, pavézy pak ani kopí nebylo vidíno mezi čtyřidcíti tisíci v Izraeli.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 9, 'Srdce mé nakloněno jest k správcům Izraelským a k těm, kteříž tak ochotní byli mezi jinými. Dobrořečtež Hospodinu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 10, 'Kteříž jezdíte na bílých oslicích, kteříž bydlíte při Middin, a kteříž chodíte po cestách, vypravujtež,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 11, 'Že vzdálen hluk střelců na místech, kdež se voda váží; i tam vypravujte hojnou spravedlnost Hospodinovu, hojnou spravedlnost k obyvatelům vsí jeho v Izraeli; tehdážť vstupovati bude k branám lid Hospodinův.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 12, 'Povstaň, povstaň, Deboro, povstaniž, povstaniž a vypravuj píseň, povstaň, Baráku, a zajmi jaté své, synu Abinoemův.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 13, 'Tehdážtě potlačenému dopomoženo k opanování silných reků z lidu; Hospodintě mi ku panování dopomohl nad silnými.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 14, 'Z Efraima kořen jejich bojoval proti Amalechitským; za tebou, Efraime, Beniamin s lidem tvým; z Machira táhli vydavatelé zákona, a z Zabulona písaři.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 15, 'Knížata také z Izachar s Deborou, ano i všecko pokolení Izacharovo, jako i Barák do údolí poslán jest pěšky, ale veliké hrdiny u sebe jsou v podílu Rubenovu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 16, 'Jak jsi mohl mlče seděti mezi dvěma ohradami, poslouchaje řvání stád? Veliké hrdiny u sebe jsou v podílu Rubenovu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 17, 'Zdali i Galád před Jordánem nebydlil? Ale Dan proč zůstal při lodech? Asser seděl na břehu mořském, a v lomích svých bydlil.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 18, 'Zabulon, lid udatný, vynaložil duši svou na smrt, též i Neftalím na vysokých místech pole.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 19, 'Králové přitáhše, bojovali, tehdáž bojovali králové Kananejští v Tanach při vodách Mageddo, a však kořisti stříbra nevzali.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 20, 'S nebe bojováno, hvězdy z míst svých bojovaly proti Zizarovi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 21, 'Potok Císon smetl je, potok Kedumim, potok Císon; všecko to pošlapala jsi, duše má, udatně.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 22, 'Tehdáž otloukla se kopyta koňů od dupání velikého pod jezdci silnými.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 23, 'Zlořečte Merozu, praví anděl Hospodinův, zlořečte velice obyvatelům jeho, nebo nepřišli na pomoc Hospodinu, ku pomoci Hospodinu proti silným.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 24, 'Požehnaná buď nad jiné ženy Jáhel, manželka Hebera Cinejského, nad ženy v staních bydlící buď požehnaná.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 25, 'On vody žádal, ona mléka dala, v koflíku knížecím podala másla.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 26, 'Levou ruku svou k hřebu vztáhla, a pravou ruku svou k kladivu dělníků, i udeřila Zizaru, a ztloukla hlavu jeho, probodla a prorazila židoviny jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 27, 'U noh jejích skrčil se, padl, ležel, u noh jejích skrčil se, padl; kdež se skrčil, tu padl zabitý.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 28, 'Vyhlídala z okna skrze mříži, a naříkala matka Zizarova, řkuci: Proč se tak dlouho vůz jeho nevrací? Proč prodlévají vraceti se domů vozové jeho?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 29, 'Moudřejší pak z předních služebnic jejích odpovídaly, i ona sama také sobě odpovídala:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 30, 'Zdali ale dosáhli něčeho, a dělí kořisti? Děvečku jednu neb dvě na každého muže, loupeže rozdílných barev samému Zizarovi, kořisti rozdílných barev krumpovaným dílem, roucho rozdílných barev krumpovaným dílem na hrdlo loupežníků.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 31, 'Tak ať zahynou všickni nepřátelé tvoji, ó Hospodine, tebe pak milující ať jsou jako slunce vzcházející v síle své. I byla v pokoji země za čtyřidceti let.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 1, 'Činili pak synové Izraelští to, což jest zlého před očima Hospodinovýma, i vydal je Hospodin v ruku Madianským za sedm let.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 2, 'A zmocnila se velmi ruka Madianských nad Izraelem, tak že synové Izraelští před Madianskými zdělali sobě jámy, kteréž jsou na horách, a jeskyně a pevnosti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 3, 'A bývalo, že jakž co oseli Izraelští, přitáhl Madian a Amalech a národ východní, povstávaje proti nim.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 4, 'Kteřížto rozbijeli stany proti nim, a kazili úrody země, až kudy se vchází do Gázy, a nenechávali potravy v Izraeli, ani ovce, ani vola, ani osla.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 5, 'Nebo i sami i s stády svými i s stany přitáhli, a jako kobylky ve množství přicházívali, aniž jich neb velbloudů jejich byl počet; tak přicházejíce do země, hubili ji.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 6, 'Tedy znuzen byl velmi Izrael od Madianských, protož volali synové Izraelští k Hospodinu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 7, 'Když pak volali synové Izraelští k Hospodinu příčinou Madianských,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 8, 'Poslal Hospodin muže proroka k synům Izraelským, a řekl jim: Takto praví Hospodin Bůh Izraelský: Já jsem vás vyvedl z Egypta, a vyvedl jsem vás z domu služby,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 9, 'A vytrhl jsem vás z rukou Egyptských a z rukou všech, jenž vás ssužovali, kteréž jsem vyhnal před tváří vaší, a dal jsem vám zemi jejich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 10, 'I řekl jsem vám: Já jsem Hospodin Bůh váš, nebojte se bohů Amorejských, v jejichž zemi bydlíte. Ale neposlechli jste hlasu mého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 11, 'Tedy přišel anděl Hospodinův a posadil se pod dubem, jenž byl v Ofra, kteréž bylo Joasa Abiezeritského. Gedeon pak syn jeho mlátil obilí na humně, aby vezma, utekl s tím před Madianskými.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 12, 'I ukázal se jemu anděl Hospodinův, a řekl jemu: Hospodin s tebou, muži udatný.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 13, 'Odpověděl jemu Gedeon: Ó Pane můj, jestliže Hospodin s námi jest, pročež pak na nás přišlo všecko toto? A kde jsou všickni divové jeho, o kterýchž vypravovali nám otcové naši, řkouce: Zdaliž nás z Egypta nevyvedl Hospodin? A nyní opustil nás Hospodin a vydal v ruku Madianských.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 14, 'A pohleděv na něj Hospodin, řekl: Jdi v této síle své, a vysvobodíš Izraele z ruky Madianských. Zdaliž jsem tě neposlal?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 15, 'Kterýž odpověděl jemu: Poslyš mne, Pane můj, čím já vysvobodím Izraele? Hle, rod můj chaterný jest v pokolení Manassesovu, a já nejmenší v domě otce svého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 16, 'Tedy řekl jemu Hospodin: Poněvadž já budu s tebou, protož zbiješ Madianské jako muže jednoho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 17, 'Jemuž on řekl: Prosím, jestliže jsem nalezl milost před očima tvýma, dej mi znamení, že ty mluvíš se mnou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 18, 'Prosím, neodcházej odsud, až zase přijdu k tobě, a vynesu obět svou a položím před tebou. Odpověděl on: Jáť posečkám, až se navrátíš.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 19, 'Tedy Gedeon všed do domu, připravil kozelce, a po měřici mouky přesných chlebů. I vložil maso do koše, a polívku vlil do hrnce, i vynesl to k němu pod dub a obětoval.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 20, 'I řekl jemu anděl Boží: Vezmi to maso a chleby ty nekvašené, a polož na tuto skálu, a polívkou polej. I učinil tak.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 21, 'Potom zdvihl anděl Hospodinův konec holi, kterouž měl v rukou svých, a dotekl se masa a chlebů přesných; i vystoupil oheň z skály té, a spálil to maso i chleby přesné. A v tom anděl Hospodinův odšel od očí jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 22, 'A vida Gedeon, že by anděl Hospodinův byl, řekl: Ach, Panovníče Hospodine, proto-liž jsem viděl anděla Hospodinova tváří v tvář, abych umřel?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 23, 'I řekl jemu Hospodin: Měj pokoj, neboj se, neumřeš.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 24, 'Protož vzdělal tu Gedeon oltář Hospodinu, a nazval jej: Hospodin pokoje, a až do tohoto dne ještě jest v Ofra Abiezeritského.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 25, 'Stalo se pak té noci, že řekl jemu Hospodin: Vezmi volka vyspělého, kterýž jest otce tvého, totiž volka toho druhého sedmiletého, a zboříš oltář Bálův, kterýž jest otce tvého, háj také, kterýž jest vedlé něho, posekáš.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 26, 'A vzděláš oltář Hospodinu Bohu svému na vrchu skály této, na rovině její, a vezma volka toho druhého, obětovati budeš obět zápalnou s dřívím háje, kterýž posekáš.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 27, 'Tedy vzal Gedeon deset mužů z služebníků svých, a učinil, jakž mluvil jemu Hospodin; a boje se čeledi otce svého a mužů města, neučinil toho ve dne, ale v noci.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 28, 'Když pak vstali muži města ráno, uzřeli zbořený oltář Bálův, a háj, kterýž byl vedlé něho, že byl posekaný, a volka toho druhého obětovaného v obět zápalnou na oltáři v nově vzdělaném.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 29, 'I mluvili jeden k druhému: Kdo to udělal? A vyhledávajíce, vyptávali se a pravili: Gedeon syn Joasův to učinil.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 30, 'Tedy řekli muži města k Joasovi: Vyveď syna svého, ať umře, proto že zbořil oltář Bálův, a že posekal háj, kterýž byl vedlé něho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 31, 'Odpověděl Joas všechněm stojícím před sebou: A což se vy nesnadniti chcete o Bále? Zdali vy jej vysvobodíte? Kdož by se zasazoval o něj, ať jest zabit hned jitra tohoto. Jestližeť jest bohem, nechať se sám zasazuje o to, že jest rozbořen oltář jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 32, 'I nazval jej toho dne Jerobálem, řka: Nechť se zasadí Bál proti němu, že zbořil oltář jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 33, 'Tedy všickni Madianští a Amalechitští a národové východní shromáždili se spolu, a přešedše Jordán, položili se v údolí Jezreel.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 34, 'Duch pak Hospodinův posilnil Gedeona, kterýžto zatroubiv v troubu, svolal Abiezeritské k sobě.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 35, 'A poslal posly ke všemu pokolení Manassesovu, a svoláno jest k němu; poslal též posly k Asserovi, k Zabulonovi a k Neftalímovi, i přitáhli jim na pomoc.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 36, 'Tedy mluvil Gedeon k Bohu: Vysvobodíš-li skrze ruku mou Izraele, jakož jsi mluvil,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 37, 'Aj, já položím rouno toto na humně. Jestliže rosa bude toliko na rouně, a na vší zemi vůkol sucho, tedy věděti budu, že vysvobodíš skrze ruku mou Izraele, jakož jsi mluvil.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 38, 'I stalo se tak. Nebo vstav nazejtří, stlačil rouno, a vyžďal rosu z něho, i byl plný koflík vody.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 39, 'Řekl také Gedeon Bohu: Nerozpaluj se prchlivost tvá proti mně, že promluvím ještě jednou. Prosím, nechažť zkusím ještě jednou na rouně. Nechť jest, prosím, samo rouno suché, a na vší zemi rosa.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 40, 'I učinil Bůh té noci tak, a bylo samo rouno suché, a na vší zemi byla rosa.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 1, 'Tedy vstav ráno Jerobál, (jenž jest Gedeon,) i všecken lid, kterýž byl s ním, položili se při studnici Charod, vojska pak Madianských byla jim na půlnoci před vrchem More v údolí.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 2, 'I řekl Hospodin Gedeonovi: Příliš mnoho jest lidu s tebou, protož nedám Madianských v ruce jejich, aby se nechlubil Izrael proti mně, řka: Ruka má spomohla mi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 3, 'A protož provolej hned, ať slyší lid, a řekni: Kdo jest strašlivý a lekavý, navrať se zase, a odejdi ráno pryč k hoře Galád. I navrátilo se z lidu dvamecítma tisíců, a deset tisíc zůstalo.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 4, 'Řekl opět Hospodin Gedeonovi: Ještě jest mnoho lidu; kaž jim sstoupiti k vodám, a tam jej tobě zkusím. I bude, že o komžkoli řeknu: Tento půjde s tebou, ten ať s tebou jde, a o komžkoli řeknu tobě: Tento nepůjde s tebou, ten ať nechodí.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 5, 'I kázal sstoupiti lidu k vodám, a řekl Hospodin k Gedeonovi: Každého, kdož chlemtati bude jazykem svým z vody, jako chlemce pes, postavíš obzvláštně, tolikéž každého, kdož se přisehne na kolena svá ku pití.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 6, 'I byl počet těch, kteříž chlemtali, rukama svýma k ústům svým vodu nosíce, tři sta mužů, ostatek pak všeho lidu sehnuli se na kolena svá ku pití vody.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 7, 'I řekl Hospodin Gedeonovi: Ve třech stech mužů, kteříž chlemtali, vysvobodím vás, a vydám Madianské v ruku tvou, ale ostatek všeho lidu nechť se vrátí, jeden každý k místu svému.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 8, 'A protož nabral ten lid v ruce své potravy a trouby své; jiné pak muže Izraelské všecky propustil, jednoho každého do stanů jejich, toliko tři sta těch mužů zanechal při sobě. Vojska pak Madianských ležela pod ním v údolí.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 9, 'I stalo se, že noci té řekl jemu Hospodin: Vstana, sstup k vojsku, nebo dal jsem je v ruku tvou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 10, 'Pakli nesmíš sjíti sám, sejdi s Půrou služebníkem svým do vojska,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 11, 'A uslyšíš, co mluviti budou; i posilní se z toho ruce tvé, tak že směle půjdeš proti vojsku tomu. Sstoupil tedy on a Půra služebník jeho k kraji oděnců, kteříž byli v vojště.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 12, 'Madian pak a Amalech i všecken lid východní leželi v údolí, jako kobylky u velikém množství, ani velbloudů jejich počtu nebylo, jako písek, kterýž jest na břehu mořském v nesčíslném množství.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 13, 'A když přišel Gedeon, aj, jeden vypravoval bližnímu svému sen, a řekl: Hle, zdálo mi se, že pecen chleba ječmenného valil se do vojska Madianského, a přivaliv se na každý stan, udeřil na něj, až padl, a podvrátil jej svrchu, a tak ležel každý stan.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 14, 'Jemužto odpovídaje bližní jeho, řekl: Není to nic jiného, jediné meč Gedeona syna Joasova, muže Izraelského; dalť jest Bůh v ruku jeho Madianské i všecka tato vojska.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 15, 'Stalo se pak, že když uslyšel Gedeon vypravování snu i vyložení jeho, poklonil se Bohu, a vrátiv se k vojsku Izraelskému, řekl: Vstaňte, nebo dal Hospodin v ruku vaši vojska Madianská.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 16, 'Rozdělil tedy tři sta mužů na tři houfy, a dal trouby v ruku každému z nich a báně prázdné, a v prostředku těch bání byly pochodně.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 17, 'I řekl jim: Jakž na mně uzříte, tak učiníte; nebo hle, já vejdu na kraj vojska, a jakž já tehdáž budu dělati, tak uděláte.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 18, 'Nebo troubiti budu já v troubu i všickni, jenž se mnou budou, tehdy vy také troubiti budete v trouby vůkol všeho vojska, a řeknete: Meč Hospodinův a Gedeonův.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 19, 'Všel tedy Gedeon a sto mužů, kteříž s ním byli, na kraj vojska při začátku bdění prostředního, jen že byli proměnili stráž; i troubili v trouby, a roztřískali báně, kteréž měli v rukou svých.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 20, 'Tedy ti tři houfové troubili v trouby, roztřískavše báně, a drželi v ruce své levé pochodně, v pravé pak ruce své trouby, aby troubili, i křičeli: Meč Hospodinův a Gedeonův.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 21, 'A postavili se každý na místě svém vůkol ležení; i zděšena jsou všecka vojska, a křičíce, utíkali.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 22, 'Když pak troubilo v trouby těch tři sta mužů, obrátil Hospodin meč jednoho proti druhému, a to po všem ležení. Utíkalo tedy vojsko až k Betseta do Zererat, a až ku pomezí Abelmehula u Tebat.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 23, 'Shromáždivše se pak muži Izraelští z Neftalím a z Asser a ze všeho pokolení Manassesova, honili Madianské.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 24, 'I rozeslal Gedeon posly na všecky hory Efraimské, řka: Vyjděte v cestu Madianským, a zastupte jim vody až k Betabaře a Jordánu. Tedy shromáždivše se všickni muži Efraim, zastoupili vody až k Betabaře a Jordánu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 25, 'A chytili dvé knížat Madianských, Goréba a Zéba. I zabili Goréba na skále Goréb a Zéba zabili v lisu Zéb, a honili Madianské, hlavu pak Gorébovu a Zébovu přinesli k Gedeonovi za Jordán.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 1, 'Muži pak Efraim řekli jemu: Co jsi nám to učinil, že jsi nepovolal nás, když jsi táhl k boji proti Madianským? A tuze se na něj domlouvali.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 2, 'Jimž odpověděl: Zdaž jsem co takového provedl, jako vy? Zdaliž není lepší paběrování Efraimovo, než vinobraní Abiezerovo?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 3, 'V ruce vaše dal Bůh knížata Madianská Goréba a Zéba, a co jsem já mohl takového učiniti, jako vy? I spokojil se duch jejich k němu, když mluvil ta slova.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 4, 'Když pak přišel Gedeon k Jordánu, přešel jej, a tři sta mužů, kteříž byli s ním, ustalí, honíce nepřátely.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 5, 'Protož řekl mužům Sochot: Dejte, prosím, po pecníku chleba lidu, kterýž za mnou jde, nebo ustali, a já honím Zebaha a Salmuna, krále ty Madianské.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 6, 'I řekl jemu jeden z knížat Sochot: Což již moc Zebahova a Salmunova jest v ruce tvé, abychom dali vojsku tvému chleba?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 7, 'Jimž řekl Gedeon: Z té příčiny, když dá Hospodin Zebaha a Salmuna v ruku mou, tehdy zmrskám těla vaše trním a bodláčím z pouště té.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 8, 'I táhl odtud do Fanuel, a podobně mluvil k nim, ale obyvatelé Fanuel odpověděli jemu tolikéž, jako muži Sochot.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 9, 'I řekl obyvatelům Fanuel: Když se navrátím v pokoji, zbořím věži tuto.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 10, 'Zebah pak a Salmun byli v Karkara spolu s vojsky svými, takměř patnácte tisíců, všickni, což jich bylo pozůstalo ze všeho vojska národů východních, zbitých pak bylo sto a dvadceti tisíc mužů bojovníků.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 11, 'I táhna Gedeon cestou bydlících v staních od východní strany Nobe a Jegbaa, udeřil na to vojsko, kteréžto vojsko sobě počínalo bezpečně.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 12, 'Když pak utíkali Zebah a Salmun, honil je, a jal oba dva ty krále Madianské, Zebaha a Salmuna, a všecko vojsko jejich předěsil.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 13, 'I navracel se Gedeon syn Joasův z bitvy před východem slunce.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 14, 'I jav mládence z obyvatelů Sochotských, vyptával se ho; kterýž sepsal mu knížata Sochot a starší jeho, sedmdesáte sedm mužů.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 15, 'Přišed pak k obyvatelům Sochot, řekl: Aj, Zebah a Salmun, pro něž jste mi utrhali, řkouce: Zdali moc Zebaha a Salmuna jest v ruce tvé, abychom dali ustalým mužům tvým chleba?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 16, 'Protož vzav starší města a trní s bodláčím z pouště té, dal na nich příklad jiným mužům Sochot.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 17, 'I věži Fanuel rozbořil, a pobil muže města.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 18, 'Potom řekl Zebahovi a Salmunovi: Jací to byli muži, kteréž jste pobili na hoře Tábor? Odpověděli oni: Takoví jako ty, jeden každý na pohledění byl jako syn královský.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 19, 'I dí: Bratří moji, synové matky mé byli. Živť jest Hospodin, byste byli živili je, nepobil bych vás.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 20, 'Tedy řekl k Jeter prvorozenému svému: Vstaň, pobí je. Ale mládenček nevytáhl meče svého, proto že se bál, nebo byl ještě mládenček.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 21, 'I řekl Zebah a Salmun: Vstaň ty a oboř se na nás, nebo jaký jest muž, taková i síla jeho. Vstav tedy Gedeon, zabil Zebaha a Salmuna, a vzal halže, kteréž byly na hrdlech velbloudů jejich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 22, 'Potom řekli muži Izraelští Gedeonovi: Panuj nad námi i ty i syn tvůj, také syn syna tvého, nebo vysvobodil jsi nás z ruky Madianských.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 23, 'I odpověděl jim Gedeon: Nebuduť já panovati nad vámi, aniž panovati bude nad vámi syn můj, Hospodin panovati bude nad vámi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 24, 'Řekl jim také Gedeon: Žádost tuto vzložím toliko na vás, abyste mi dali jeden každý náušnici z loupeží svých; (nebo náušnice zlaté měli, proto že Izmaelitští byli.)');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 25, 'I odpověděli: Rádi dáme. A prostřevše roucho, metali na ně každý náušnici z loupeží svých.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 26, 'Byla pak váha náušnic zlatých, kteréž vyžádal, tisíc a sedm set lotů zlata, kromě halží a zlatých jableček, i roucha šarlatového, kteréž na sobě měli králové Madianští, a kromě halží, kteréž byly na hrdlech velbloudů jejich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 27, 'I udělal z toho Gedeon efod, a složil jej v městě svém Ofra. I smilnil tam všecken Izrael, chodě za ním, a byl Gedeonovi i domu jeho osídlem.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 28, 'Madianští pak sníženi jsou před syny Izraelskými, aniž potom pozdvihli hlavy své; a tak byla v pokoji země za čtyřidceti let ve dnech Gedeonových.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 29, 'A odšed Jerobál syn Joasův, přebýval v domě svém.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 30, 'Měl pak Gedeon sedmdesáte synů, kteříž pošli z bedr jeho; nebo měl žen mnoho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 31, 'Ženina také jeho, kterouž měl v Sichem, i ta porodila jemu syna, a dala mu jméno Abimelech.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 32, 'A když umřel Gedeon syn Joasův v starosti dobré, pochován jest v hrobě Joasa otce svého v Ofra Abiezeritského.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 33, 'Stalo se pak po smrti Gedeonově, že se odvrátili synové Izraelští a smilnili, jdouce za modlami, a vzali sobě Bále Berit za boha.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 34, 'A nerozpomenuli se synové Izraelští na Hospodina Boha svého, kterýž je vytrhl z ruky všech nepřátel jejich vůkol.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 35, 'A neučinili milosrdenství s domem Jerobále Gedeona, jako on všecko dobré činil Izraelovi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 1, 'Nebo odšed Abimelech syn Jerobálův do Sichem k bratřím matky své, mluvil k nim i ke vší čeledi domu otce matky své, řka:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 2, 'Mluvte, prosím, ke všechněm mužům Sichemským: Co jest lépe vám, to-li, aby panovalo nad vámi sedmdesáte mužů, totiž všickni synové Jerobálovi, čili aby panoval nad vámi muž jeden? Pamatujte pak, že jsem já kost vaše a tělo vaše.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 3, 'Tedy mluvili bratří matky jeho o něm ke všechněm mužům Sichemským všecka slova tato, a naklonilo se srdce jejich k Abimelechovi, nebo řekli: Bratr náš jest.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 4, 'I dali jemu sedmdesáte lotů stříbra z domu Bále Berit, na něž sobě najal Abimelech služebníky, povaleče a tuláky, aby chodili za ním.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 5, 'A přišed do domu otce svého do Ofra, zmordoval bratří své, syny Jerobálovy, sedmdesáte mužů, na jednom kameni; toliko zůstal Jotam syn Jerobálův nejmladší, nebo se byl skryl.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 6, 'Tedy shromáždili se všickni muži Sichemští i všecken dům Mello, i šli, a ustanovili sobě Abimelecha za krále na rovinách u sloupu, kterýž jest u Sichem.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 7, 'To když pověděli Jotamovi, odejda, postavil se na vrchu hory Garizim, a pozdvihna hlasu svého, volal, a řekl jim: Poslyšte mne muži Sichemští, a uslyš vás Bůh.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 8, 'Sešlo se některého času dříví, aby pomazalo nad sebou krále. I řekli olivě: Kraluj nad námi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 9, 'Jimžto odpověděla oliva: Zdali já, opustě svou tučnost, kterouž ctěn bývá Bůh i lidé, půjdu, abych byla postavena nad stromy?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 10, 'I řeklo dříví fíku: Poď ty a kraluj nad námi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 11, 'Jimž odpověděl fík: Zdali já, opustě sladkost svou a ovoce své výborné, půjdu, abych postaven byl nad stromy?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 12, 'Řeklo opět dříví vinnému kořenu: Poď ty a kraluj nad námi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 13, 'Jimž odpověděl vinný kořen: Zdali já, opustě své víno, kteréž obveseluje Boha i lidi, půjdu, abych postaven byl nad stromy?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 14, 'Naposledy řeklo všecko dříví bodláku: Poď ale ty a kraluj nad námi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 15, 'I odpověděl bodlák dříví: Jestliže v pravdě béřete vy mne sobě za krále, poďte, odpočívejte pod stínem mým; pakli nic, vyjdi oheň z bodláku a spal cedry Libánské.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 16, 'Tak i nyní, jestliže jste právě a upřímě učinili, ustavivše Abimelecha za krále, a jestliže jste dobře učinili Jerobálovi a domu jeho, a jestliže podlé dobrodiní rukou jeho odplatili jste se jemu;');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 17, '(Nebo otec můj bojoval za vás a opovážil se života svého, aby vás vysvobodil z ruky Madianských,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 18, 'Vy pak teď povstali jste proti domu otce mého, a zmordovali jste syny jeho, sedmdesáte mužů na jednom kameni, a ustanovili jste krále Abimelecha, syna děvky jeho, nad muži Sichemskými, proto že bratr váš jest);');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 19, 'Jestliže, řku, právě a upřímě udělali jste Jerobálovi i domu jeho dne tohoto, veselte se z Abimelecha, a on také nechť se veselí z vás;');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 20, 'Pakli nic, nechť vyjde oheň z Abimelecha a sžíře muže Sichemské i dům Mello, nechť vyjde také oheň od mužů Sichemských a z domu Mello a sžíře Abimelecha.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 21, 'Tedy utekl Jotam, a utíkaje, odšel do Beera, a zůstal tam, boje se Abimelecha bratra svého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 22, 'I panoval Abimelech nad Izraelem tři léta.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 23, 'Poslal pak Bůh ducha zlého mezi Abimelecha a mezi muže Sichemské, a zpronevěřili se muži Sichemští Abimelechovi,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 24, 'Aby pomštěna byla křivda sedmdesáti synů Jerobálových, a aby krev jejich přišla na Abimelecha bratra jejich, kterýž zmordoval je, a na muže Sichemské, kteříž posilnili rukou jeho, aby zmordoval bratří své.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 25, 'Nebo učinili muži Sichemští jemu zálohy na vrších hor, a loupili všecky chodíci mimo ně tou cestou; kterážto věc povědína jest Abimelechovi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 26, 'Syn pak Ebedův Gál, jda s bratřími svými, přišel do Sichem, i těšili se z něho muži Sichemští.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 27, 'A vyšedše na pole, sbírali víno své a tlačili i veselili se; a všedše do chrámu bohů svých, jedli a pili, a zlořečili Abimelechovi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 28, 'Řekl pak Gál syn Ebedův: Kdo jest Abimelech? A jaké jest Sichem, abychom sloužili jemu? Zdaliž není syn Jerobálův, a Zebul úředník jeho? Služte raději mužům Emora, otce Sichemova; nebo proč my máme sloužiti tomuto?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 29, 'Ale ó kdyby tento lid byl v ruce mé, abych shladil Abimelecha! I řekl Abimelechovi: Sbeř sobě vojsko, a vyjdi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 30, 'Uslyšav pak Zebul, úředník města toho, slova Gále syna Ebedova, rozhněval se náramně.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 31, 'I poslal posly k Abimelechovi tajně, řka: Hle, Gál syn Ebedův i bratří jeho přišli do Sichem, a hle, bojovati budou s městem proti tobě.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 32, 'Protož nyní vstana nočně, ty i lid, kterýž jest s tebou, zdělej zálohy v poli.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 33, 'A ráno, když bude slunce vycházeti, vstana, udeříš na město, a když on i lid, kterýž jest s ním, vyjde proti tobě, učiníš jemu to, což se naskytne ruce tvé.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 34, 'A protož vstal Abimelech i všecken lid, kterýž s ním byl v noci, a učinili zálohy u Sichem na čtyřech místech.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 35, 'I vyšel Gál syn Ebedův, a postavil se v bráně města; vyvstal pak Abimelech i lid, kterýž s ním byl, z záloh.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 36, 'A uzřev Gál ten lid, řekl Zebulovi: Hle, lid sstupuje s vrchu hor. Jemuž odpověděl Zebul: Stín hor vidíš, jako nějaké lidi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 37, 'Tedy opět promluvil Gál, řka: Hle, lid sstupuje s vrchu, nebo houf jeden táhne cestou rovin Monenim.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 38, 'Řekl pak jemu Zebul: Kde jsou nyní ústa tvá, jimižs mluvil: Kdo jest Abimelech, abychom sloužili jemu? Zdaliž toto není lid ten, kterýmž jsi pohrdal? Vytáhniž nyní, a bojuj proti němu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 39, 'I vytáhl Gál před lidmi Sichemskými, a bojoval proti Abimelechovi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 40, 'Ale Abimelech honil ho utíkajícího před tváří svou, a padlo raněných mnoho až k bráně.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 41, 'Zůstal pak Abimelech v Aruma, a Zebul vyhnal Gále i bratří jeho, aby nezůstávali v Sichem.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 42, 'Nazejtří pak vytáhl lid do pole, i oznámeno jest to Abimelechovi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 43, 'Tedy on pojal lid svůj, a rozdělil jej na tři houfy, zdělav zálohy v polích, a vida, an lid vychází z města, vyskočil na ně a zbil je.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 44, 'Nebo Abimelech a houf, kterýž byl s ním, udeřili na ně a postavili se u brány města, druzí pak dva houfové obořili se na všecky ty, kteříž byli v poli, a zbili je.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 45, 'Abimelech pak dobýval města celý ten den, až ho i dobyl, a lid, kterýž v něm byl, pobil, a zbořiv město, posál je solí.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 46, 'Uslyševše pak všickni muži věže Sichemské, vešli do hradu svého, chrámu boha Berit.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 47, 'A oznámeno jest Abimelechovi, že se tam shromáždili všickni muži věže Sichemské.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 48, 'Tedy vstoupil Abimelech na horu Salmon, on i všecken lid, kterýž byl s ním, a nabrav seker s sebou, nasekal ratolestí s stromů, kterýchž nabral a vložil na rameno své. I řekl lidu, kterýž byl s ním: Což jste viděli, že jsem učinil, spěšně učiňte tak jako já.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 49, 'I uťal sobě jeden každý ze všeho lidu ratolest, a jdouce za Abimelechem, skladli je u hradu, a zapálili jimi hrad. I zemřeli tam všickni muži věže Sichemské téměř tisíc mužů a žen.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 50, 'Odšel pak Abimelech do Tébes, a položil se u Tébes, i dobyl ho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 51, 'Byla pak věže pevná u prostřed města, a utekli tam všickni muži i ženy, i všickni přední města toho, a zavřeli po sobě, vstoupivše na vrch věže.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 52, 'Tehdy přišed Abimelech až k věži, dobýval jí, a přistoupil až ke dveřím věže, aby je zapálil ohněm.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 53, 'V tom žena nějaká svrhla kus žernovu na hlavu Abimelechovu, a prorazila hlavu jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 54, 'A on rychle zavolav mládence, kterýž nosil zbroj jeho, řekl jemu: Vytrhni meč svůj a zabí mne, aby potom nepravili o mně: Žena zabila ho. I probodl jej služebník jeho, a umřel.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 55, 'Uzřevše pak synové Izraelští, že by umřel Abimelech, odešli jeden každý k místu svému.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 56, 'A tak odměnil Bůh zlým Abimelechovi za nešlechetnost, kterouž páchal proti otci svému, zmordovav sedmdesáte bratří svých.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 57, 'Tolikéž i všecku nešlechetnost mužů Sichemských vrátil Bůh na hlavu jejich, a přišlo na ně zlořečení Jotama syna Jerobálova.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 1, 'Povstal pak po Abimelechovi k obhajování Izraele Tola, syn Fua, syna Dodova, muž z pokolení Izachar, a ten bydlil v Samir na hoře Efraim.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 2, 'I soudil Izraele za třimecítma let, a umřev, pochován jest v Samir.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 3, 'Po něm povstal Jair Galádský, a soudil Izraele za dvamecítma let.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 4, 'A měl třidceti synů, kteříž jezdili na třidcíti mezcích; a měli třidceti měst, kteráž sloula vsi Jairovy až do dnešního dne, a ty jsou v zemi Galád.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 5, 'I umřel Jair, a pochován jest v Kamon.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 6, 'Opět pak synové Izraelští činili to, což jest zlého před očima Hospodinovýma; nebo sloužili Bálům a Astarot, to jest, bohům Syrským, bohům Sidonským a bohům Moábským, tolikéž i bohům synů Ammon, i bohům Filistinským, tak že opustili Hospodina, a nesloužili jemu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 7, 'Protož roznítila se prchlivost Hospodinova na Izraele, a vydal je v ruku Filistinských a v ruku Ammonitských,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 8, 'Kteříž stírali a potlačovali syny Izraelské toho roku, i potom za osmnácte let, všecky syny Izraelské, kteříž byli před Jordánem v zemi Amorejského, kteráž jest v Galád.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 9, 'Přešli pak Ammonitští i Jordán, aby bojovali také proti Judovi, a proti Beniaminovi, i proti domu Efraimovu; i byl Izrael náramně ssoužen.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 10, 'Tedy volali synové Izraelští k Hospodinu, řkouce: Zhřešiliť jsme tobě, tak že jsme opustili tě Boha svého, a sloužili jsme Bálům.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 11, 'Ale Hospodin řekl synům Izraelským: Zdaliž jsem od Egyptských a od Amorejských a od Ammonitských a Filistinských,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 12, 'Tolikéž od Sidonských, a Amalechitských, i od Maonitských, vás ssužujících, když jste volali ke mně, nevysvobodil vás z ruky jejich?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 13, 'A vy opustili jste mne a sloužili jste bohům cizím, protož nevysvobodím vás více.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 14, 'Jděte a volejte k bohům, kteréž jste sobě zvolili; oni nechť vás vysvobodí v čas ssoužení vašeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 15, 'I řekli synové Izraelští Hospodinu: Zhřešili jsme; učiň s námi, cožť se dobře líbí, a však vysvoboď nás, prosíme, v tento čas.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 16, 'Protož vyvrhše bohy cizí z prostředku svého, sloužili Hospodinu, a zželelo se duši jeho nad trápením Izraele.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 17, 'Svolali se pak Ammonitští, a položili se v Galád; shromáždili se také synové Izraelští, a položili se v Masfa.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 18, 'I řekli lid s knížaty Galád jedni druhým: Kdokoli počne bojovati proti Ammonitským, bude vůdce všech obyvatelů Galád.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 1, 'Jefte pak Galádský byl muž udatný a byl syn ženy nevěstky, z níž zplodil Galád řečeného Jefte.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 2, 'Ale i manželka Galádova naplodila mu synů, a když dorostli synové manželky té, vyhnali Jefte. Nebo řekli jemu: Nebudeš děditi v domě otce našeho, nebo jsi postranní ženy syn.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 3, 'Protož utekl Jefte od tváři bratří svých, a bydlil v zemi Tob; a sběhli se k Jefte lidé povaleči, a vycházeli s ním.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 4, 'Stalo se pak po těch dnech, že bojovali Ammonitští proti Izraelským.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 5, 'A když počali bojovati Ammonitští proti nim, odešli starší Galádští, aby zase přivedli Jefte z země Tob.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 6, 'I řekli k Jefte: Poď a buď vůdce náš, abychom bojovali proti Ammonitským.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 7, 'Odpověděl Jefte starším Galádským: Zdaliž jste vy mne neměli v nenávisti, a nevyhnali jste mne z domu otce mého? Pročež tedy nyní přišli jste ke mně, když ssouženi jste?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 8, 'I řekli starší Galádští k Jefte: Proto jsme se nyní navrátili k tobě, abys šel s námi a bojoval proti Ammonitským, a byl nám všechněm obyvatelům Galádským za vůdce.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 9, 'Tedy odpověděl Jefte starším Galádským: Poněvadž mne zase uvodíte, abych bojoval proti Ammonitským, když by mi je dal Hospodin v moc, budu-li vám za vůdce?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 10, 'I řekli starší Galádští k Jefte: Hospodin bude svědkem mezi námi, jestliže neučiníme vedlé slova tvého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 11, 'A tak šel Jefte s staršími Galádskými, a představil jej sobě lid za vůdci a kníže, a mluvil Jefte všecka slova svá před Hospodinem v Masfa.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 12, 'Potom poslal Jefte posly k králi Ammonitskému s tímto poručením: Co máš ke mně, že jsi vytáhl na mne, abys bojoval proti zemi mé?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 13, 'I odpověděl král Ammonitský poslům Jefte: Že vzal Izrael zemi mou, když vyšel z Egypta, od Arnon až k Jaboku a až k Jordánu; protož nyní vrať mi ji pokojně.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 14, 'Opět pak poslal Jefte posly k králi Ammonitskému,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 15, 'A řekl jemu: Takto praví Jefte: Nevzalť Izrael země Moábské, ani země synů Ammonových.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 16, 'Ale když vyšli z Egypta, šel Izrael přes poušť až k moři Rudému, a přišel do Kádes.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 17, 'Odkudž poslal Izrael posly k králi Edomskému, řka: Prosím, nechť projdu skrze zemi tvou. A nechtěl ho slyšeti král Edomský. Poslal také k králi Moábskému, a nechtěl povoliti. A tak zůstal Izrael v Kádes.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 18, 'Potom když šel přes poušť, obcházel zemi Edomskou a zemi Moábskou, a přišed od východu slunce zemi Moábské, položil se před Arnon, a nevešli na pomezí Moábské; nebo Arnon jest meze Moábských.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 19, 'Protož poslal Izrael posly k Seonovi králi Amorejskému, to jest, k králi Ezebon, a řekl jemu Izrael: Prosím, nechť projdu skrze zemi tvou až k místu svému.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 20, 'Ale Seon nedověřoval Izraelovi, aby přejíti měl pomezí jeho. Protož shromáždil Seon všecken lid svůj, a položili se v Jasa, a bojoval proti Izraelovi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 21, 'I dal Hospodin Bůh Izraelský Seona i všecken lid jeho v ruku Izraelských, a porazili je. I opanoval dědičně Izrael všecku zemi Amorejského, té země obyvatele.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 22, 'A tak opanovali všecko pomezí Amorejského od Arnon až k Jaboku a od pouště až k Jordánu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 23, 'Když tedy Hospodin Bůh Izraelský vyhladil Amorejského od tváři lidu svého Izraelského, proč ty chceš panovati nad ním?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 24, 'Zdaliž tím, což tobě dal Chámos bůh tvůj k vládařství, vládnouti nemáš? Takž, kterékoli vyhladil Hospodin Bůh náš od tváři naší, jejich dědictvím my vládneme.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 25, 'K tomu pak, zdali jsi ty čím lepší Baláka syna Seforova, krále Moábského? Zdali se kdy vadil s Izraelem? Zdali kdy bojoval proti nim?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 26, 'Ješto již bydlí Izrael v Ezebon a ve vsech jeho, i v Aroer, a ve vsech jeho, i ve všech městech, kteráž jsou při pomezí Arnon, za tři sta let. Proč jste jí neodjali v tak dlouhém času?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 27, 'Protož ne já provinil jsem proti tobě, ale ty mně zle činíš, bojuje proti mně. Nechť soudí Hospodin soudce dnes mezi syny Izraelskými a mezi syny Ammonovými.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 28, 'Král pak Ammonitský neuposlechl slov Jefte, kteráž vzkázal jemu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 29, 'V tom nadšen byl Jefte duchem Hospodinovým, i táhl skrze Galád a Manasse, prošel i Masfa v Galád, a z Masfy v Galád táhl proti Ammonitským.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 30, '(Učinil pak Jefte slib Hospodinu, a řekl: Jestliže jistotně dáš mi Ammonitské v ruku mou:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 31, 'I stane se, že což by koli vyšlo ze dveří domu mého mně vstříc, když se vrátím v pokoji od Ammonitských, bude Hospodinovo, abych to obětoval v obět zápalnou.)');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 32, 'Přitáhl tedy Jefte na Ammonitské, aby bojoval proti nim, a dal je Hospodin v ruku jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 33, 'I pobil je od Aroer, až kudy se jde do Mennit, dvadceti měst, a až do Abel vinic porážkou velikou velmi; a sníženi jsou Ammonitští před syny Izraelskými.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 34, 'Když se pak navracoval Jefte do Masfa k domu svému, aj, dcera jeho vyšla jemu vstříc s bubny a s houfem plésajících; kterouž měl toliko jedinou, aniž měl kterého syna aneb jiné dcery.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 35, 'Stalo se pak, že když uzřel ji, roztrhl roucha svá a řekl: Ach, dcero má, velices mne ponížila; nebo jsi z těch, jenž mne kormoutí, poněvadž jsem tak řekl Hospodinu, aniž budu moci odvolati toho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 36, 'Jemuž ona odpověděla: Můj otče, jestliže jsi tak řekl Hospodinu, učiň mi podlé toho, jakžs mluvil; kdyžť jen dal Hospodin pomstu nad nepřátely tvými, Ammonitskými.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 37, 'Řekla také otci svému: Nechť toliko toto obdržím: Odpusť mne na dva měsíce, ať jdu a vejdu na hory a opláči panenství svého, já i družičky mé.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 38, 'Kterýž řekl: Jdi. I propustil ji na dva měsíce. Odešla tedy ona i družičky její, a plakala panenství svého na horách.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 39, 'A při dokonání dvou měsíců navrátila se k otci svému, a vykonal při ní slib svůj, kterýž byl učinil. Ona pak nepoznala muže. I byl ten obyčej v Izraeli,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 40, 'Že každého roku scházívaly se dcery Izraelské, aby plakaly nad dcerou Jefte Galádského za čtyři dni v roce.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 12, 1, 'Shromáždili se pak muži Efraim, a přešedše k straně půlnoční, řekli k Jefte: Proč jsi vyšel k boji proti Ammonitským, a nepovolal jsi nás, abychom šli s tebou? Dům tvůj i tebe ohněm spálíme.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 12, 2, 'K nimž řekl Jefte: Nesnáz jsem měl já a lid můj s Ammonitskými velikou; tedy povolal jsem vás, ale nevysvobodili jste mne z ruky jejich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 12, 3, 'Protož vida, že jste mne nevysvobodili, odvážil jsem se života svého, a táhl jsem proti Ammonitským, i dal je Hospodin v ruku mou. Ale proč jste dnes přišli ke mně? Zdali abyste bojovali proti mně?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 12, 4, 'Tedy shromáždil Jefte všecky muže Galádské, a bojoval s Efraimem. I porazili muži Galád Efraimské, nebo pravili poběhlci Efraimští: Vy Galádští jste u prostřed Efraima a u prostřed Manassesa.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 12, 5, 'Odjali Galádští též i brody Jordánské Efraimským. A bylo, že když kdo z utíkajících Efraimských řekl: Nechať přejdu, řekli jemu muži Galádští: Jsi-li Efratejský? Jestliže řekl: Nejsem,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 12, 6, 'Tedy řekli jemu: Rci hned Šibolet. I řekl: Sibolet, aniž dobře mohl vyřknouti toho. Tedy pochytíce jej, zamordovali ho u brodu Jordánského. I padlo toho času z Efraima čtyřidceti a dva tisíce.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 12, 7, 'Soudil pak Jefte Izraele šest let; a umřel Jefte Galádský, a pochován jest v jednom z měst Galádských.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 12, 8, 'Potom soudil po něm Izraele Abesam z Betléma.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 12, 9, 'A měl třidceti synů a třidceti dcer, kteréž rozevdal od sebe, a třidceti žen přivedl od jinud synům svým. I soudil Izraele sedm let.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 12, 10, 'A umřev Abesam, pochován jest v Betlémě.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 12, 11, 'Po něm pak soudil Izraele Elon Zabulonský; ten soudil Izraele deset let.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 12, 12, 'I umřel Elon Zabulonský, a pochován jest v Aialon, v zemi Zabulon.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 12, 13, 'Potom soudil Izraele Abdon syn Hellelův Faratonský.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 12, 14, 'Ten měl čtyřidceti synů a třidceti vnuků, kteříž jezdili na sedmdesáti mezcích; i soudil Izraele osm let.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 12, 15, 'Umřev pak Abdon syn Hellelův Faratonský, pohřben jest v Faraton, v zemi Efraim na hoře Amalechitské.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 1, 'Tedy opět synové Izraelští činili to, což jest zlého před očima Hospodinovýma, i vydal je Hospodin v ruce Filistinských za čtyřidceti let.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 2, 'Byl pak muž jeden z Zaraha, z čeledi Dan, jménem Manue, jehož manželka byla neplodná a nerodila.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 3, 'I ukázal se anděl Hospodinův ženě té a řekl jí: Aj, nyní jsi neplodná, aniž jsi rodila; počneš pak a porodíš syna.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 4, 'Protož nyní vystříhej se, abys vína nepila aneb nápoje opojného, a abys nejedla nic nečistého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 5, 'Nebo aj, počneš a porodíš syna, a břitva ať nevchází na hlavu jeho, nebo bude to dítě od života Nazarejský Boží, a tenť počne vysvobozovati Izraele z ruky Filistinských.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 6, 'I přišla žena a pověděla to muži svému, řkuci: Muž Boží přišel ke mně, jehož oblíčej byl jako oblíčej anděla Božího, hrozný velmi, a neotázala jsem se jeho, odkud by byl, ani mi svého jména neoznámil.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 7, 'Ale řekl mi: Aj, počneš a porodíš syna, protož nyní nepí vína aneb nápoje opojného, aniž jez co nečistého, nebo to dítě od života bude Nazarejský Boží až do dne smrti své.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 8, 'Tedy Manue modlil se Hospodinu a řekl: Vyslyš mne, můj Pane, prosím, nechť muž Boží, kteréhož jsi byl poslal, zase přijde k nám, a naučí nás, co máme dělati s dítětem, kteréž se má naroditi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 9, 'I vyslyšel Bůh hlas Manue; nebo přišel anděl Boží opět k ženě té, když seděla na poli. Manue pak muž její nebyl s ní.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 10, 'A protož s chvátáním běžela žena ta, a oznámila muži svému, řkuci jemu: Hle, ukázal se mi muž ten, kterýž byl ke mně prvé přišel.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 11, 'Vstav pak Manue, šel za manželkou svou, a přišed k muži tomu, řekl jemu: Ty-li jsi ten muž, kterýž jsi mluvil k manželce mé? Odpověděl: Jsem.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 12, 'I řekl Manue: Nechť se nyní stane slovo tvé, ale jaká péče o to dítě a správa při něm býti má?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 13, 'Odpověděl anděl Hospodinův Manue: Ode všeho toho, o čemž jsem oznámil ženě, ať se ona vystříhá.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 14, 'Ničeho, což pochází z vinného kmene, ať neužívá, to jest, vína aneb nápoje opojného ať nepije, a nic nečistého ať nejí; cožkoli jsem jí přikázal, ať ostříhá.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 15, 'Tedy řekl Manue andělu Hospodinovu: Medle, nechť tě pozdržíme, a připravímeť kozlíka.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 16, 'I odpověděl anděl Hospodinův Manue: Bys mne i pozdržel, nebuduť jísti pokrmu tvého, ale jestliže připravíš obět zápalnou, Hospodinu ji obětuj. Nebo nevěděl Manue, že byl anděl Hospodinův.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 17, 'Řekl opět Manue andělu Hospodinovu: Jaké jest jméno tvé, abychom, když se naplní řeč tvá, poctili tebe?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 18, 'Jemuž odpověděl anděl Hospodinův: Proč se ptáš na jméno mé, kteréž jest divné?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 19, 'Vzav tedy Manue kozlíka a obět suchou, obětoval to na skále Hospodinu, a on divnou věc učinil, an na to hledí Manue a manželka jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 20, 'Nebo když vstupoval plamen s oltáře k nebi, vznesl se anděl Hospodinův v plameni s oltáře, Manue pak a manželka jeho vidouce to, padli na tvář svou na zemi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 21, 'A již se více neukázal anděl Hospodinův Manue ani manželce jeho. Tedy porozuměl Manue, že byl anděl Hospodinův.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 22, 'I řekl Manue manželce své: Jistě my zemřeme, nebo jsme Boha viděli.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 23, 'Jemuž odpověděla manželka jeho: Kdyby nás chtěl Hospodin usmrtiti, nebyl by přijal z rukou našich oběti zápalné a suché, aniž by nám byl ukázal čeho toho, aniž by na tento čas byl nám ohlásil věcí takových.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 24, 'A tak žena ta porodila syna a nazvala jméno jeho Samson. I rostlo dítě, a žehnal jemu Hospodin.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 25, 'I počal ho Duch Hospodinův ponoukati v Mahane Dan, mezi Zaraha a Estaol.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 1, 'Šel pak Samson do Tamnata, a uzřel tam ženu ze dcer Filistinských.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 2, 'A navrátiv se, oznámil otci svému a mateři své, řka: Viděl jsem ženu v Tamnata ze dcer Filistinských, protož nyní vezměte mi ji za manželku.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 3, 'I řekl mu otec jeho a matka jeho: Zdali není mezi dcerami bratří tvých a ve všem lidu mém ženy, že sobě vzíti chceš manželku z Filistinských neobřezaných? Odpověděl Samson otci svému: Tuto vezměte mi, nebť mi se líbí.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 4, 'Otec pak jeho a matka jeho nevěděli, by to od Hospodina bylo, a že příčiny hledá od Filistinských; nebo toho času panovali Filistinští nad Izraelem.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 5, 'Tedy šel Samson a otec jeho i matka jeho do Tamnata. Když pak přišli k vinicím Tamnatským, a aj, lev mladý řvoucí potkal se s ním.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 6, 'I sstoupil na něj Duch Hospodinův, a roztrhl lva, jako by roztrhl kozelce, ačkoli nic neměl v rukou svých. A neoznámil otci ani mateři své, co učinil.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 7, 'Přišed tedy, mluvil s ženou tou, a líbila se Samsonovi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 8, 'Navracuje se pak po několika dnech, aby ji pojal, uchýlil se, aby pohleděl na mrtvého lva, a aj, v těle jeho byl roj včel a med.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 9, 'A vybrav jej na ruce své, šel cestou a jedl; a přišed k otci svému a mateři své, dal jim, i jedli. Ale nepověděl jim, že z mrtvého lva vyňal ten med.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 10, 'Tedy šel otec jeho k ženě té, a učinil tam Samson hody, nebo tak činívali mládenci.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 11, 'Když pak jej viděli tam, vybrali z sebe třidceti tovaryšů, aby byli při něm.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 12, 'I řekl jim Samson: Vydám vám pohádku, kterouž jestliže mi právě vysvětlíte za sedm dní těchto hodů a uhodnete, dám vám třidceti čechlů a třidcatero roucho proměnné.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 13, 'Jestliže mi pak nebudete moci uhodnouti, dáte vy mně třidceti čechlů a třidcatero roucho proměnné. Kteříž odpověděli jemu: Vydej pohádku svou, ať ji slyšíme.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 14, 'I řekl jim: Z zžírajícího vyšel pokrm, a z silného vyšla sladkost. I nemohli uhodnouti pohádky té za tři dni.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 15, 'Stalo se pak dne sedmého, (nebo byli řekli ženě Samsonově: Namluv muže svého, ať nám vyloží tu pohádku, ať nespálíme tě i domu otce tvého ohněm. Proto-liž, abyste našeho statku dostali, pozvali jste nás? Či co?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 16, 'I plakala žena Samsonova na něj, řkuci: Jistě nenávidíš mne a nemiluješ mne; pohádku jsi vydal synům lidu mého, a mně jí nechceš povědíti. Kterýž řekl jí: Hle, otci mému a mateři neoznámil jsem, a tobě mám povědíti?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 17, 'I plakala na něj do sedmého dne, v nichž měli hody). Dne tedy sedmého pověděl jí, nebo trápila jej; kterážto oznámila pohádku synům lidu svého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 18, 'Muži tedy města toho dne sedmého, prvé než slunce zapadlo, řekli jemu: Co sladšího nad med, a co silnějšího nad lva? Kterýž řekl jim: Byste byli neorali mou jalovičkou, neuhodli byste pohádky mé.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 19, 'I sstoupil na něj Duch Hospodinův, a šel do Aškalon, a pobil z nich třidceti mužů. A vzav loupeže jejich, dal šaty proměnné těm, jenž uhodli pohádku, a rozhněvav se velmi, odšel do domu otce svého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 20, 'Žena pak Samsonova dostala se jednomu z tovaryšů jeho, kteréhož on byl k sobě připojil.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 1, 'Stalo se pak po několika dnech, v čas žně pšeničné, že chtěje navštíviti Samson ženu svou, a přinésti s sebou kozlíka, řekl: Vejdu k ženě své do pokoje. A nedopustil mu otec její vjíti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 2, 'I řekl otec její: Domníval jsem se zajisté, že ji máš v nenávisti, protož dal jsem ji tovaryši tvému. Zdaliž není sestra její mladší pěknější než ona? Nechať jest tedy tvá místo oné.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 3, 'I řekl jim Samson: Nebuduť já potom vinen Filistinským, když jim zle učiním.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 4, 'Odšed tedy Samson, nalapal tři sta lišek, a vzav pochodně, obrátil jeden ocas k druhému, a dal vše jednu pochodni mezi dva ocasy do prostředka.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 5, 'Potom zapálil ty pochodně, a pustil do obilí Filistinských, a popálil, jakž sžaté tak nesžaté, i vinice i olivoví.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 6, 'I řekli Filistinští: Kdo je to učinil? Jimž odpovědíno: Samson zeť Tamnejského, proto že vzal ženu jeho a dal ji tovaryši jeho. Tedy přišedše Filistinští, spálili ji ohněm i otce jejího.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 7, 'Tedy řekl jim Samson: Ač jste učinili tak, však až se lépe vymstím nad vámi, teprv přestanu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 8, 'I zbil je na hnátích i na bedrách porážkou velikou, a odšed, usadil se na vrchu skály Etam.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 9, 'Pročež vytáhli Filistinští, a rozbivše stany proti Judovi, rozložili se až do Lechi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 10, 'Muži pak Juda řekli: Proč jste vytáhli proti nám? I odpověděli: Vytáhli jsme, abychom svázali Samsona, a učinili jemu tak, jako on nám učinil.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 11, 'Tedy vyšlo tři tisíce mužů Juda k vrchu skály Etam, a řekli Samsonovi: Nevíš-liž, že panují nad námi Filistinští? Pročež jsi tedy nám to učinil? I odpověděl jim: Jakž mi učinili, tak jsem jim učinil.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 12, 'Řekli také jemu: Přišli jsme, abychom tě svázali a vydali v ruku Filistinským. Tedy odpověděl jim Samson: Přisáhněte mi, že vy se na mne neoboříte.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 13, 'Tedy mluvili jemu, řkouce: Nikoli, jediné tuze svížíce, vydáme tě v ruku jejich, ale nezabijeme tě. I svázali ho dvěma provazy novými, a svedli jej s skály.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 14, 'Kterýž když přišel až do Lechi, Filistinští radostí křičeli proti němu. Přišel pak na něj Duch Hospodinův, a učiněni jsou provazové, kteříž byli na rukou jeho, jako niti lněné, když v ohni hoří, i spadli svazové s rukou jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 15, 'Tedy našel čelist osličí ještě vlhkou, a vztáh ruku svou, vzal ji a pobil ní tisíc mužů.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 16, 'Protož řekl Samson: Čelistí osličí hromadu jednu, nýbrž dvě hromady, čelistí osličí zbil jsem tisíc mužů.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 17, 'A když přestal mluviti, povrhl čelist z ruky své, a nazval to místo Ramat Lechi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 18, 'Žíznil pak velice, i volal k Hospodinu a řekl: Ty jsi učinil skrze ruce služebníka svého vysvobození toto veliké, nyní pak již žízní umru, aneb upadnu v ruku těch neobřezaných.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 19, 'Tedy otevřel Bůh skálu v Lechi, i vyšly z ní vody, a napil se; i okřál, a jako ožil. Protož nazval jméno její studnice vzývajícího, kteráž jest v Lechi až do dnešního dne.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 20, 'Soudil pak Izraele za času Filistinských dvadceti let.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 1, 'Odšel pak Samson do Gázy, a uzřev tam ženu nevěstku, všel k ní.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 2, 'I povědíno obyvatelům Gázy: Samson přišel sem. Kteříž obeslavše se, střáhli na něj v bráně města přes celou noc, a stavěli se tiše té celé noci, řkouce: Až ráno zabijeme jej.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 3, 'Spal pak Samson až do půl noci, a o půl noci vstal, a pochytiv vrata brány městské s oběma veřejemi a s závorou, vložil na ramena svá a vnesl je na vrch hory, kteráž byla naproti Hebronu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 4, 'Potom pak zamiloval ženu v údolí Sorek, jejíž jméno bylo Dalila.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 5, 'I přišli knížata Filistinská k ní a řekli jí: Oklamej ho a zvěz, v čem jest síla jeho tak veliká, a jak bychom přemohli jej, abychom svížíce, skrotili jej; tobě pak jeden každý z nás dáme tisíc a sto lotů stříbra.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 6, 'Tedy řekla Dalila Samsonovi: Prosím, oznam mi, v čem jest tak veliká síla tvá, a čím bys svázán a zemdlen býti mohl?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 7, 'Odpověděl jí Samson: Kdyby mne svázali sedmi houžvemi surovými, kteréž ještě neuschly, tedy zemdlím, a budu jako jiný člověk.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 8, 'I přinesli jí knížata Filistinská sedm houžví surových, kteréž ještě neuschly, a svázala ho jimi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 9, '(V zálohách pak nastrojeni byli někteří u ní v komoře.) I řekla jemu: Filistinští na tě, Samsone. A on roztrhl houžve, jako by přetrhl nit koudelnou, přistrče k ohni, a není poznána síla jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 10, 'Tedy řekla Dalila Samsonovi: Aj, oklamals mne a lživě jsi mi mluvil. Prosím, oznam mi nyní, čím bys mohl svázán býti?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 11, 'Kterýž odpověděl jí: Kdyby mne tuze svázali novými provazy, jimiž by ještě nic děláno nebylo, tedy zemdlím a budu jako kdokoli jiný z lidí.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 12, 'I vzala Dalila provazy nové a svázala ho jimi, a řekla jemu: Filistinští na tě, Samsone. (Zálohy pak nastrojeny byly v komoře.) I roztrhl je na rukou svých jako nitku.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 13, 'Tedy řekla Dalila Samsonovi: Až dosavad jsi mne svodil, a mluvils mi lež. Pověziž mi, čím bys svázán býti mohl. Odpověděl jí: Kdybys přivila sedm pramenů z vlasů hlavy mé k vratidlu tkadlcovskému.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 14, 'Což učinivši, zarazila hřebem, a řekla jemu: Filistinští na tě, Samsone. A procítiv ze sna svého, vytrhl hřeb, osnovu i s vratidlem.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 15, 'Opět řekla jemu: Kterak ty pravíš: Miluji tě, poněvadž srdce tvé není se mnou? Již jsi mne potřikrát oklamal a neoznámils mi, v čem jest tak veliká síla tvá.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 16, 'Když tedy trápila jej slovy svými každého dne, a obtěžovala jej, umdlena jest duše jeho, jako by již měl umříti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 17, 'I otevřel jí cele srdce své a řekl jí: Břitva nevešla nikdy na hlavu mou, nebo Nazarejský Boží jsem od života matky své. Kdybych oholen byl, odešla by ode mne síla má, a zemdlel bych a byl jako jiný člověk.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 18, 'Viduci pak Dalila, že by cele otevřel jí srdce své, poslala a zavolala knížat Filistinských těmi slovy: Poďte ještě jednou, nebo otevřel mi cele srdce své. Tedy přišli knížata Filistinská k ní, nesouce stříbro v rukou svých.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 19, 'I uspala ho na klíně svém a povolala holiče, i dala oholiti sedm pramenů vlasů hlavy jeho. I počala jím strkati, když odešla od něho síla jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 20, 'A řekla: Filistinští na tě, Samsone. Procítiv pak ze sna svého, řekl: Vyjdu jako i prvé, a probiji se skrze ně. Nevěděl však, že Hospodin odstoupil od něho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 21, 'Tedy javše ho Filistinští, vyloupili mu oči, a dovedše ho do Gázy, svázali jej dvěma řetězy železnými. A mlel v domě vězňů.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 22, 'Potom počaly mu vlasy na hlavě odrostati po oholení.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 23, 'Knížata pak Filistinská shromáždili se, aby obětovali obět velikou bohu svému Dágonovi a aby se veselili; nebo řekli: Dalť jest bůh náš v ruce naše Samsona nepřítele našeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 24, 'A když uzřel jej lid, chválili boha svého; nebo pravili: Dalť jest bůh náš v ruce naše nepřítele našeho a zhoubce země naší, kterýž mnohé z našich zmordoval.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 25, 'I stalo, když se rozveselilo srdce jejich, že řekli: Zavolejte Samsona, aby kratochvílil před námi. Tedy povolali Samsona z domu vězňů, aby hral před nimi; i postavili ho mezi sloupy.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 26, 'Nebo řekl Samson pacholeti, kteréž ho za ruku vodilo: Přiveď mne, ať mohu omakati sloupy, na nichž dům stojí, a zpodepříti se na ně.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 27, 'Dům pak plný byl mužů a žen, a byla tam všecka knížata Filistinská, ano i na vrchu okolo tří tisíc mužů a žen, kteříž dívali se, když Samson hral.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 28, 'I volal Samson k Hospodinu, a řekl: Panovníče Hospodine, prosím, rozpomeň se na mne, a posilni mne, žádám, toliko aspoň jednou, ó Bože, abych se jednou pomstíti mohl za své obě oči nad Filistinskými.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 29, 'Objav tedy Samson oba sloupy prostřední, na nichž dům ten stál, zpolehl na ně, na jeden pravou a na druhý levou rukou svou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 30, 'Potom řekl Samson: Nechť umře život můj s Filistinskými. A nalehl silně, i padl dům na knížata a na všecken lid, kterýž byl v něm; i bylo mrtvých, kteréž pobil on umíraje, více než těch, kteréž pobil, živ jsa.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 31, 'Tedy přišli přátelé jeho, a všecken dům otce jeho, a vzavše jej, odešli, a pochovali jej mezi Zaraha a Estaol v hrobě Manue otce jeho. A on soudil lid Izraelský dvadceti let.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 17, 1, 'Byl pak muž nějaký s hory Efraim, jehož jméno bylo Mícha.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 17, 2, 'Kterýž řekl matce své: Ten tisíc a sto stříbrných, kteříž vzati byli tobě, pro něž jsi zlořečila a mluvilas přede mnou, hle, stříbro to u mne jest, já jsem je vzal. I řekla matka jeho: Požehnaný jsi, synu můj, od Hospodina.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 17, 3, 'Navrátil tedy ten tisíc a sto stříbrných matce své. I řekla matka jeho: Jižť jsem zajisté posvětila stříbro to Hospodinu z ruky své, a tobě synu svému, aby udělán byl obraz rytý a slitý. Protož nyní dám je tobě.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 17, 4, 'On pak navrátil to stříbro matce své, z něhož vzala matka jeho dvě stě stříbrných, a dala zlatníku. I udělal z nich obraz rytý a slitý, kterýž byl v domě Míchově.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 17, 5, 'Měl pak ten Mícha chrám bohů, i udělal efod a terafim, a naplnil ruce jednoho z synů svých, aby mu byl knězem.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 17, 6, 'Toho času nebylo krále v Izraeli; jeden každý, což se mu za dobré vidělo, to činil.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 17, 7, 'Byl pak mládenec z Betléma Judova, totiž z čeledi Judovy, kterýž, jsa Levíta, byl tam pohostinu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 17, 8, 'Odšel tedy člověk ten z města Betléma Judova, aby byl pohostinu, kdež by se mu koli nahodilo. I přišel na horu Efraim, až k domu Míchovu, jda cestou svou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 17, 9, 'Jemuž řekl Mícha: Odkud jdeš? Odpověděl mu: Já jsem Levíta, z Betléma Judova beru se, abych byl pohostinu, kdež by mi se koli nahodilo.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 17, 10, 'I řekl jemu Mícha: Zůstaň u mne, a buď mi za otce a za kněze, a buduť dávati deset stříbrných na každý rok, a dvoje roucho i stravu tvou. I šel Levíta.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 17, 11, 'Líbilo se pak Levítovi zůstati u muže toho, a byl u něho mládenec ten, jako jeden z synů jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 17, 12, 'I posvětil Mícha rukou Levíty, a byl mu mládenec ten za kněze; i bydlil v domě jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 17, 13, 'Řekl pak Mícha: Nyníť vím, že mi dobře učiní Hospodin, proto že mám toho Levítu za kněze.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 1, 'V těch dnech nebylo krále v Izraeli, a toho času pokolení Dan hledalo sobě dědičného místa k bydlení, nebo se mu ještě nebylo dostalo dílu u prostřed synů Izraelských až do dne toho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 2, 'Tedy poslali synové Dan z čeledi své pět mužů z končin svých, mužů silných z Zaraha a Estaol, aby spatřili zemi a pilně prohlédli ji, a řekli jim: Jděte, shlédněte zemi. Kteřížto když přišli na horu Efraim až do domu Míchova, přenocovali tam.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 3, 'Když pak byli blízko domu Míchova, poznali hlas toho mládence Levíty, a uchýlivše se tam, řekli jemu: Kdo tě sem přivedl? Co ty zde děláš? A co ty zde máš?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 4, 'Odpověděl jim: Toto mi a toto učinil Mícha, a ze mzdy najal mne, abych byl jeho knězem.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 5, 'I řekli jemu: Poraď se, prosíme, s Bohem, abychom věděli, zdaří-li se nám cesta naše, kterouž jdeme.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 6, 'Odpověděl jim kněz: Jděte v pokoji, Hospodinť spravuje cestu vaši, po níž jdete.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 7, 'Tedy odešlo pět mužů těch, a přišli do Lais, a viděli lid, kterýž tam byl, bezpečně bydlící, vedlé obyčeje Sidonských v zahálce a bezpečnosti, a že nebylo, co by je kormoutiti mělo v té zemi, ani kdo by dědičně ujíti chtěl království. K tomu i od Sidonských vzdáleni byli, aniž spříznění jaké s kým měli.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 8, 'Když se pak navrátili k bratřím svým do Zaraha a Estaol, řekli jim bratří jejich: Což vy?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 9, 'I odpověděli: Vstaňte a táhněme na ně, nebo shlédli jsme tu zemi, a aj, velmi dobrá jest; a vy mlčíte? Nelenujtež se táhnouti, a vjíti k opanování té země.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 10, '(Když přijdete, vejdete k lidu bezpečnému, a do země prostranné;) nebo dal ji Bůh v ruku vaši, místo, v němž není žádného nedostatku jakýchkoli věcí, kteréž na zemi býti mohou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 11, 'Tedy vyšlo z čeledi Dan odtud, totiž z Zaraha a Estaol, šest set mužů oděných v odění válečné.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 12, 'A vytáhše, položili se u Kariatjeharim Judova; pročež nazvali to místo Mahane Dan až do dnešního dne, a jest za Kariatjeharim.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 13, 'A odtud táhnouce na horu Efraim, přišli až k domu Míchovu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 14, 'I mluvilo těch pět mužů, kteříž chodili k shlédnutí země Lais, a řekli bratřím svým: Víte-liž, že v domích těchto jest efod a terafim, a rytina a slitina? Protož nyní vězte, co máte činiti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 15, 'A uchýlivše se tam, vešli do domu mládence Levíty v domě Míchově, a pozdravili ho pokojně.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 16, 'Ale šest set mužů oděných v zbroj svou válečnou, kteříž byli z pokolení Dan, stáli přede dveřmi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 17, 'A šedše pět mužů, kteříž chodili k shlédnutí země, vešli tam a vzali rytinu a efod a terafim a slitinu; kněz pak stál u vrat brány s šesti sty muži oděnými v zbroji.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 18, 'A ti, kteříž vešli do domu Míchova, vzali rytinu, efod a terafim, a slitinu. I řekl jim kněz: Což to děláte?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 19, 'Kteříž odpověděli: Mlč, vlož ruku svou na ústa svá a poď s námi, a budeš nám za otce a za kněze. Což jest lépe tobě, knězem-li býti v domě jednoho člověka, či býti knězem pokolení a čeledi v Izraeli?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 20, 'I zradovalo se srdce kněze, a vzav efod a terafim a rytinu, šel u prostřed lidu toho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 21, 'A obrátivše se odešli, a pustili napřed děti a dobytek, a což měli dražšího.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 22, 'Když pak opodál byli od domu Míchova, tedy muži, kteříž bydlili v domích blízkých domu Míchova, shromáždili se a honili syny Dan.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 23, 'I volali za syny Dan. Kteříž ohlédše se, řekli Míchovi: Cožtě, že jsi jich tolik shromáždil?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 24, 'Odpověděl: Bohy mé, kteréž jsem udělal, vzali jste, i kněze, a odcházíte. Což pak již budu míti? A ještě se ptáte: Coť jest?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 25, 'Jemuž odpověděli synové Dan: Hlediž, ať více neslyšíme hlasu tvého za sebou, sic jináč oboří se na vás muži hněviví, a ztratíš duši svou i duše domu svého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 26, 'I brali se muži Dan cestou svou. A vida Mícha, že by silnější byli nežli on, obrátiv se, šel do domu svého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 27, 'Oni pak vzavše, což byl udělal Mícha, i kněze, kteréhož měl, přitáhli do Lais k lidu zahálivému a bezpečnému; i pobili je ostrostí meče, a město vypálili ohněm.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 28, 'A nebylo žádného, kdo by jim spomohl; nebo daleko byl Sidon, aniž měli spříznění s kterými lidmi. Město pak bylo v údolí, kteréž jest v Betrohob. A vystavěvše zase město, bydlili v něm.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 29, 'A nazvali jméno města toho Dan, od jména otce svého, kterýž narozen byl Izraelovi, ješto prvé jméno města toho bylo Lais.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 30, 'Postavili pak sobě synové Dan tu rytinu, a Jonatan syn Gersonův, syna Mojžíšova, on i synové jeho byli kněžími v pokolení Dan, až do dne zajetí obyvatelů země.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 31, 'Vystavili tedy sobě tu rytinu, kterouž udělal Mícha, a byla tam po všecky dny, v nichž dům Boží byl v Sílo.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 1, 'Stalo se také toho času, když krále nebylo v Izraeli, že muž nějaký Levíta, jsa pohostinu při straně hory Efraimské, pojal sobě ženu ženinu z Betléma Judova.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 2, 'Kterážto ženina smilnila u něho. I odešla od něho do domu otce svého do Betléma Judova, a byla tam plné čtyři měsíce.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 3, 'Vstav pak muž její, šel za ní, aby namluvě ji, zase ji přivedl, maje s sebou mládence svého a dva osly. Tedy ona uvedla jej do domu otce svého. Kteréhož když uzřel otec té děvky, zradoval se z příchodu jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 4, 'I zdržel jej tchán jeho, otec té děvky, tak že pozůstal u něho za tři dni. Tu také jídali i píjeli i nocovali.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 5, 'Dne pak čtvrtého, když tím raněji vstali, vstal i on, aby odšel. Tedy řekl otec té děvky k zeti svému: Posilni se kouskem chleba, a potom půjdete.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 6, 'Sedli tedy a pojedli oba spolu, a napili se. Potom řekl otec děvky k muži: Posediž medle, nýbrž pobuď přes noc, a buď mysli veselé.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 7, 'Když pak vstal ten muž, chtěje předce jíti, mocí jej zdržel test jeho. A tak se vrátil a zůstal tu přes noc.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 8, 'Potom dne pátého vstal tím raněji, aby se bral. I řekl otec té děvky: Posilň se, prosím. I prodlili, až se den nachýlil, nebo jedli oba.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 9, 'Tedy vstal muž ten, aby šel, on i ženina jeho i mládenec jeho. I řekl mu tchán jeho, otec děvky: Aj, již se den nachýlil k večerou, medle zůstaňte přes noc; aj, dokonává se den, pobuď přes noc zde, a buď mysli veselé, a zítra tím raněji vypravíte se na cestu svou, a půjdeš k příbytku svému.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 10, 'On pak nechtěl zůstati přes noc, ale vstav, odšel, a přišel proti Jebus, jenž jest Jeruzalém, a s ním dva oslové s břemeny i ženina jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 11, 'Když pak byli blízko Jebus, a den se velmi nachýlil, řekl mládenec pánu svému: Poď, prosím, obraťme se do města toho Jebuzejského, abychom v něm přenocovali.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 12, 'Jemuž odpověděl pán jeho: Neobrátíme se do města cizozemců, kteréž není synů Izraelských, ale půjdeme až do Gabaa.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 13, 'Řekl ještě mládenci svému: Poď, abychom přišli k některému z těch míst, a zůstali přes noc v Gabaa aneb v Ráma.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 14, 'Pomíjejíce tedy, odešli, a zapadlo jim slunce blízko Gabaa, kteréž jest Beniaminských.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 15, 'I obrátili se tam, aby vejdouce, zůstali přes noc v Gabaa. A když tam všel, posadil se na ulici města, proto že nebyl, kdo by je přijal do domu a dal jim nocleh.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 16, 'A aj, muž starý vracoval se od práce své s pole u večer, kterýž také byl s hory Efraimovy, a bydlil pohostinu v Gabaa; ale lidé místa toho byli synové Jemini.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 17, 'A když pozdvihl očí svých, uzřel muže toho pocestného na ulici města. I řekl jemu ten stařec: Kam se béřeš, a odkud jdeš?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 18, 'Jemuž odpověděl: Jdeme z Betléma Judova až k stranám hory Efraimovy, odkudž jsem; nebo jsem byl odšel do Betléma Judova. Jduť pak do domu Hospodinova, a není žádného, kdo by mne přijal do domu;');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 19, 'Ješto mám i slámu a obrok pro osly své, tolikéž i chléb, ano i víno pro sebe a děvku tvou, a mládence, kterýž jest s služebníkem tvým, tak že v ničemž nemáme nedostatku.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 20, 'I řekl muž ten starý: Měj ty pokoj. Čehoť se koli nedostává, nechť já to opatřím, ty toliko na ulici nezůstávej přes noc.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 21, 'Tedy uvedl jej do domu svého, a obrok dal oslům; potom umyvše nohy své, jedli a pili.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 22, 'A když očerstvili srdce své, aj, muži města toho, muži nešlechetní, obklíčivše dům, tloukli na dvéře a mluvili tomu muži starci, hospodáři domu, řkouce: Vyveď muže toho, kterýž všel do domu tvého, abychom ho poznali.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 23, 'K nimžto vyšed muž ten, hospodář domu, řekl jim: Nikoli, bratří moji, nečiňte, prosím, zlého, poněvadž všel ten muž do domu mého, neprovoďte nešlechetnosti té.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 24, 'Aj, dceru svou, kteráž pannou jest, a ženinu jeho, ty hned vyvedu, i ponížíte jich, aneb učiníte jim, což se vám za dobré vidí; jen muži tomu nečiňte věci té hanebné.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 25, 'Ale nechtěli ho uposlechnouti muži ti. Pojav tedy muž ten ženinu svou, vyvedl ji k nim ven, i poznali ji, a zle jí požívali přes celou noc až do jitra; potom pustili ji, když počínalo zasvitávati.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 26, 'V svitání pak přišla žena ta, a padši, ležela u dveří domu toho muže, kdež byl pán její, až se rozednilo.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 27, 'Když pak vstal pán její ráno, otevřev dvéře domu, vycházel, aby se bral dále cestou svou. A aj, žena ta, ženina jeho, ležela u dveří domu, a ruce její byly na prahu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 28, 'Jížto řekl: Vstaň, a poďme. A nic neodpověděla. Vzav tedy ji na osla, a vstav muž ten, odšel k místu svému.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 29, 'Když pak přišel do domu svého, vzal meč, a pochytiv ženinu svou, rozsekal ji s kostmi jejími na dvanácte kusů, a rozeslal ji po všech končinách Izraelských.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 30, 'A bylo, že kdožkoli uzřel, pravil: Nikdy se nestalo ani vidíno bylo co podobného od toho času, jakž vyšli synové Izraelští z země Egyptské, až do tohoto dne. Posuďte toho pilně, poraďte se a promluvte o to.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 1, 'I vyšli všickni synové Izraelští, a shromáždilo se všecko množství jednomyslně od Dan až do Bersabé, i země Galád, k Hospodinu do Masfa.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 2, 'Kdežto postavili se přední všeho lidu, všecka pokolení Izraelská v shromáždění lidu Božího, čtyřikrát sto tisíc lidu pěšího válečného.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 3, '(Uslyšeli pak synové Beniamin, že by sešli se synové Izraelští v Masfa.) I řekli synové Izraelští: Povězte, kterak se stala nešlechetnost ta?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 4, 'I odpověděv muž Levíta, manžel ženy zamordované, řekl: Do Gabaa kteréž jest Beniaminovo, přišel jsem s ženinou svou, abych tam přenocoval.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 5, 'Tedy povstavše proti mně muži Gabaa, obklíčili mne v domě v noci, myslíce mne zamordovati, ženinu pak mou trápili, tak že umřela.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 6, 'Pročež vzav ženinu svou, rozsekal jsem ji na kusy, a rozeslal jsem ji do všech krajin dědictví Izraelského; nebo nešlechetnosti a mrzkosti se dopustili v Izraeli.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 7, 'Aj, všickni vy synové Izraelští jste; považte toho mezi sebou, a raďte se o to.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 8, 'A povstav všecken lid jednomyslně, řekli: Nenavrátí se žádný z nás do příbytku svého, aniž odejde kdo do domu svého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 9, 'Ale nyní toto učiníme Gabaa, losujíce proti němu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 10, 'Vezmeme deset mužů ze sta po všech pokoleních Izraelských, a sto z tisíce, a tisíc z desíti tisíců, aby dodávali potravy lidu, kterýž by přitáhna do Gabaa Beniaminova, pomstil všech nešlechetností jeho, kterýchž se dopustilo v Izraeli.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 11, 'I sebrali se všickni muži Izraelští na to město, snesše se za jednoho člověka.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 12, 'Poslala pak pokolení Izraelská muže do všech čeledí synů Beniamin, řkouce: Jaký to zlý skutek stal se mezi vámi?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 13, 'Nyní tedy vydejte ty muže bezbožné, kteříž jsou v Gabaa, ať je zbijeme a odejmeme zlé z Izraele. Ale nechtěli Beniaminští slyšeti hlasu bratří svých, synů Izraelských.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 14, 'Nýbrž shromáždili se synové Beniamin z měst svých do Gabaa, aby vytáhli k boji proti synům Izraelským.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 15, 'Toho dne načteno jest synů Beniamin z měst jejich dvadceti šest tisíc mužů bojovných, kromě obyvatelů Gabaa, jichž načteno bylo šest set mužů vybraných.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 16, 'Mezi kterýmžto vším lidem bylo sedm set mužů vybraných, neužívajících pravé ruky své, z nichž každý z praku kamením házeli k vlasu, a nechybovali se.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 17, 'Mužů pak Izraelských načteno jest kromě Beniaminských čtyřikrát sto tisíc mužů bojovných; všickni tito byli muži udatní.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 18, 'Vstavše pak, brali se do domu Boha silného, a tázali se Boha, a řekli synové Izraelští: Kdo z nás půjde napřed k boji proti synům Beniamin? I řekl Hospodin: Juda půjde napřed.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 19, 'A tak ráno vstavše synové Izraelští, položili se proti Gabaa.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 20, 'I táhli muži Izraelští k boji proti synům Beniamin, a sšikovali se muži Izraelští k bitvě proti Gabaa.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 21, 'Vyšedše pak synové Beniamin z Gabaa, porazili z Izraele toho dne dvamecítma tisíc mužů na zem.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 22, 'A posilnivše se muži lidu Izraelského, spořádali se zase k boji na místě, na kterémž se prvního dne zřídili.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 23, 'Prvé pak šli synové Izraelští, a plakali před Hospodinem až do večera. I tázali se Hospodina těmi slovy: Půjdeme-li ještě k boji proti synům Beniamina bratra našeho? Odpověděl Hospodin: Jděte proti nim.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 24, 'Tedy potýkali se synové Izraelští s syny Beniamin druhého dne.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 25, 'A vyšedše synové Beniamin z Gabaa na ně druhého dne, porazili z synů Izraelských opět osmnácte tisíc mužů na zem, vše mužů bojovných.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 26, 'Protož vstoupili všickni synové Izraelští a všecken lid, a přišli do domu Boha silného. I plakali, usadivše se tam před Hospodinem, a postili se toho dne až do večera; obětovali též oběti zápalné a pokojné před Hospodinem.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 27, 'I tázali se synové Izraelští Hospodina, (nebo tu byla truhla smlouvy Boží v těch dnech,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 28, 'A Fínes syn Eleazara, syna Aronova, stál před ní v ten čas,) řkouce: Půjdeme-li ještě k boji proti synům Beniamina bratra našeho, čili tak necháme? Odpověděl Hospodin: Jděte, nebo zítra dám je v ruku vaši.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 29, 'Tedy Izraelští zdělali zálohy proti Gabaa všudy vůkol.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 30, 'I šli synové Izraelští proti synům Beniamin dne třetího, a sšikovali se proti Gabaa, jako prvé jednou i podruhé.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 31, 'Vyšedše pak synové Beniamin proti lidu, odtrhli se od města, a počali bíti a mordovati lidu, jako prvé jednou i druhé po stezkách, (z nichž jedna šla k Bethel a druhá do Gabaa), i po poli, a zbili okolo třidcíti mužů z Izraele.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 32, 'A řekli synové Beniamin: Padají před námi jako i prvé. Synové pak Izraelští řekli byli: Utíkejme, abychom je odtrhli od města až k stezkám.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 33, 'A v tom všickni synové Izraelští vstavše z místa svého, sšikovali se v Baltamar; zálohy také Izraelovy vyskočily z místa svého z trávníků Gabaa.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 34, 'Tedy vyšlo proti Gabaa deset tisíc mužů vybraných ze všeho Izraele, a bitva se rozmáhala; oni pak nevěděli o tom, že je potkati mělo zlé.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 35, 'I porazil Hospodin Beniamina před Izraelem, a zbili synové Izraelští z Beniaminských dne toho pětmecítma tisíc a sto mužů, vše bojovných.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 36, 'A vidouce synové Beniamin, že by poraženi byli, (nebo muži Izraelští ustupovali z místa Beniaminským, ubezpečivše se na zálohy, kteréž zdělali proti Gabaa.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 37, 'Zálohy pak pospíšily a obořily se na Gabaa, a rozvláčně troubivše zálohy, zbily všecko město ostrostí meče.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 38, 'Měli pak muži Izraelští s zálohami jistý čas uložený, aby když by oni zapálili město,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 39, 'Obrátili se synové Izraelští k boji. Beniaminští pak počali bíti a mordovati, a zbili z synů Izraelských okolo třidcíti mužů; nebo řekli: Jistě že padají před námi jako v první bitvě.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 40, 'Oheň pak počal vzhůru jíti z města, a sloup dymový. A ohlédše se Beniaminští zpět, uzřeli, an vstupuje oheň města k nebi.)');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 41, 'A že muži Izraelští obrátili se, i zděšeni jsou muži Beniamin, nebo viděli, že zahynutí jim nastává.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 42, 'I utíkali před muži Izraelskými cestou ku poušti, a bojovníci postihali je, a kteří z měst vyšli, mordovali je mezi sebou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 43, 'A tak obklíčili Beniaminské, a honili i porazili je, od Manuha až naproti Gabaa k východu slunce.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 44, 'Tedy padlo Beniaminských osmnácte tisíc mužů; všickni ti byli muži silní.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 45, 'Těch pak, kteříž obrátivše se, utíkali na poušť k skále Remmon, zpaběrovali po cestách pět tisíc mužů; potom honili je až k Gidom, a zbili z nich dva tisíce mužů.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 46, 'A tak bylo všech, kteříž padli v ten den z Beniaminských, pětmecítma tisíc mužů bojovných, vše mužů silných.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 47, 'I obrátilo se na poušť a uteklo k skále Remmon šest set mužů, kteříž zůstali v skále Remmon za čtyři měsíce.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 48, 'Potom muži Izraelští navrátili se k synům Beniamin, a zbili je ostrostí meče, tak lidi v městech jako hovada, i všecko, což nalezeno bylo; také i všecka města, kteráž ještě pozůstávala, ohněm vypálili.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 1, 'Nadto každý z mužů Izraelských přísahou se byli zavázali v Masfa, řkouce: Žádný z nás nedá dcery své Beniaminským za manželku.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 2, 'Protož všel lid do domu Boha silného, a seděli tam až do večera před Bohem, a pozdvihše hlasu svého, plakali pláčem velikým.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 3, 'A řekli: Proč Hospodine, Bože Izraelský, stalo se toto v Izraeli, aby dnes ubylo jedno pokolení z Izraele?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 4, 'Nazejtří pak ráno vstal lid, a vzdělali tam oltář, a obětovali oběti zápalné a pokojné.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 5, 'Řekli pak synové Izraelští: Jest-li kdo, ješto nepřišel do shromáždění tohoto ze všech pokolení Izraelských k Hospodinu? (Nebo se byli velice zapřisáhli proti tomu, kdož by nepřišel k Hospodinu do Masfa, řkouce: Bez milosti ať umře.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 6, 'Nebo litujíce synové Izraelští Beniamina bratra svého, řekli: Dnes vyhlazeno jest jedno pokolení z Izraele.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 7, 'Jakž tedy učiníme s těmi ostatky, aby ženy měli, poněvadž jsme se přísahou zavázali skrze Hospodina, že jim nedáme dcer svých za manželky?)');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 8, 'Řekli tedy: Jest-li kdo z pokolení Izraelských, ješto nepřišel k Hospodinu do Masfa? A aj, nepřišel byl žádný do vojska z Jábes Galád do shromáždění.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 9, 'Nebo když sečten byl lid, a aj, nebylo tam žádného z obyvatelů Jábes Galád.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 10, 'Protož poslalo tam shromáždění to dvanácte tisíc mužů nejsilnějších, a přikázali jim, řkouce: Jděte a pobíte obyvatele Jábes Galád ostrostí meče, ženy i děti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 11, 'Toto pak učiníte: Všecky mužského pohlaví, a každou ženu, kteráž muže poznala, zamordujete.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 12, 'Nalezli tedy mezi obyvateli Jábes Galád čtyři sta děveček panen, kteréž nepoznaly muže, a přivedli je do vojska v Sílo, kteréž bylo v zemi Kananejské.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 13, 'Tedy poslalo všecko to shromáždění, a mluvili k synům Beniamin, kteříž byli v skále Remmon, a povolali jich v pokoji.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 14, 'Protož navrátili se Beniaminští toho času. I dali jim ženy, kteréž živé zachovali z žen Jábes Galád, ale ani tak se jim nedostávalo jich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 15, 'Lidu pak líto bylo Beniamina, proto že učinil Hospodin mezeru v pokoleních Izraelských.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 16, 'Řekli tedy starší shromáždění toho: Jak učiníme s těmi pozůstalými, aby měli ženy? Nebo vyhlazeny jsou ženy z pokolení Beniamin.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 17, 'Řekli také: Dědictví Beniaminovo pozůstalým náleží, aby nezahynulo pokolení z Izraele.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 18, 'My pak nemůžeme jim dáti dcer svých za manželky; (nebo se byli přísahou zavázali synové Izraelští, řkouce: Zlořečený buď, kdož by dal manželku synům Beniamin.)');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 19, 'Potom řekli: Aj, slavnost Hospodinova bývá v Sílo každého roku na místě, kteréž jest s půlnoční strany domu Boha silného, k východu slunce cestě, kterouž se chodí od domu Boha silného do Sichem, a Lebnu jest na poledne.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 20, 'Přikázali tedy synům Beniamin, řkouce: Jděte a skrejte se v vinicích.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 21, 'A šetřte, a aj, když vyjdou dcery Sílo plésati v houfích, tedy vyskočíte z vinic a pochytíte sobě každý manželku svou ze dcer Sílo, a odejdete do země Beniamin.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 22, 'Když pak přijdou otcové jejich aneb bratří jejich, aby se před námi soudili, tedy řekneme jim: Slitujte se nad námi místo nich, nebo v té válce nevzali jsme pro každého z nich manželky; také jste vy jim nedali jich, a tak nebudete nic vinni.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 23, 'Tedy učinili tak synové Beniamin, a přivedli sobě manželky vedlé počtu svého z těch plésajících, kteréž uchvátili; a odšedše, navrátili se k dědictví svému, a vzdělavše zase města svá, bydlili v nich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 24, 'A tak odešli odtud synové Izraelští toho času, jeden každý k svému pokolení a k čeledi své; a vrátili se odtud jeden každý k dědictví svému.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 25, 'Těch dnů nebylo krále v Izraeli, ale každý, což se mu vidělo, to činil.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 1, 'Stalo se pak za času soudců, že byl hlad v zemi. I odšel člověk z Betléma Judova, a bydlil pohostinu v krajině Moábské s manželkou svou a se dvěma syny svými.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 2, 'Jméno pak muže toho Elimelech, a jméno ženy jeho Noémi, jméno také dvou synů jeho Mahalon a Chelion, Efratejští z Betléma Judova; a přišedše do krajiny Moábské, bydlili tam.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 3, 'Umřel pak Elimelech, muž Noémi; i pozůstala ona s oběma syny svými.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 4, 'Kteříž pojali sobě ženy Moábské; jméno jedné bylo Orfa a jméno druhé Rut. I bydlili tam téměř deset let.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 5, 'Umřeli také oni oba dva, Mahalon i Chelion, a zůstala žena ta po dvou synech svých a manželu svém.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 6, 'Tedy vstavši ona s nevěstami svými, navracela se z krajiny Moábské; nebo slyšela v krajině Moábské, že Hospodin navštívil lid svůj, dav jemu chléb.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 7, 'Vyšedši tedy z místa, na němž bydlila, a obě nevěsty její s ní, daly se na cestu, aby se navrátily do země Judské.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 8, 'Řekla pak Noémi oběma nevěstám svým: Jděte, navraťte se jedna každá do domu matky své. Učiniž Hospodin s vámi milosrdenství, jakož jste i vy činili s mrtvými syny mými i se mnou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 9, 'Dejž vám Hospodin, abyste nalezly odpočinutí, jedna každá v domě muže svého. I políbila jich, ony pak pozdvihše hlasu svého, plakaly.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 10, 'A řekly jí: Obrátíme se raději s tebou k lidu tvému.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 11, 'I řekla Noémi: Navraťte se, dcerky mé. Proč chcete jíti se mnou? Zdaliž ještě budu míti syny, aby byli vaši muži?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 12, 'Navraťte se, dcerky mé, a odejděte, neboť jsem již stará k vdání; nýbrž bych i řekla, že mám naději, bych i noci této se vdala a syny zrodila,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 13, 'Zdaž byste na ně čekaly, až by dorostli? Zdaliž tou příčinou meškati se budete, abyste se neměly vdáti? Ne tak, mé dcerky, nebo mé trápení větší jest nežli vaše, proto že ruka Hospodinova jest proti mně.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 14, 'Ony pak pozdvihše hlasu, opět plakaly. A Orfa políbivši svegruši svou, odešla, Rut pak přídržela se jí.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 15, 'Kteréžto řekla Noémi: Aj, přítelkyně tvá navrátila se k lidu svému a k bohům svým, navratiž se také za ní.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 16, 'Ale Rut řekla: Nenuť mne, abych tě opustiti a od tebe odjíti měla. Nebo kamž se koli obrátíš, půjdu, a kdekoli bydliti budeš, i já bydliti budu; lid tvůj lid můj, a Bůh tvůj Bůh můj.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 17, 'Kdekoli umřeš, umru, a tu pochována budu. Toto mi učiň Hospodin, a toto přidej, že toliko smrt rozdělí mne s tebou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 18, 'Tedy viduci, že se na tom ustavila, aby šla s ní, přestala k ní mluviti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 19, 'I šly obě dvě spolu, až přišly k Betlému. I stalo se, že když přišly do Betléma, roznesla se pověst o nich po všem městě, a pravili: To-li jest ta Noémi?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 20, 'Jimž ona řekla: Nenazývejte mne Noémi, říkejte mi Mara; nebo hořkostí velikou naplnil mne Všemohoucí.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 21, 'Vyšla jsem plná, teď pak prázdnou mne zase Hospodin přivedl. Pročež tedy nazýváte mne Noémi, poněvadž mne Hospodin ssoužil, a Všemohoucí mne znuzil?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 22, 'A navrátila se Noémi s Rut Moábskou, nevěstou svou; navrátila se pak z krajiny Moábské. I přišly do Betléma, když počínali žíti ječmene.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 1, 'Měla pak Noémi přítele po manželu svém, muže mocného z čeledi Elimelechovy, jménem Bóza.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 2, 'I řekla Rut Moábská Noémi: Nechť medle jdu na pole sbírati klasů za tím, kdož by mi toho přál. Jížto ona řekla: Jdi, dcero má.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 3, 'Šla tedy, a přišedši, sbírala klasy na poli za ženci. Přihodilo se pak, že přišla na díl pole toho, kteréž přináleželo Bózovi, jenž byl z čeledi Elimelechovy.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 4, 'A v tom přišel Bóz z Betléma, a řekl žencům: Hospodin s vámi. Kteříž odpověděli jemu: Požehnejž tobě Hospodin.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 5, 'I řekl Bóz služebníku svému, kterýž postaven byl nad ženci: Čí jest tato mladice?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 6, 'Odpověděl služebník ten, kterýž postaven byl nad ženci, a řekl: Jest mladice Moábská, kteráž přišla s Noémi z země Moábské.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 7, 'A řekla mi: Prosím, nechť sbírám a shromažďuji klasy mezi snopy za ženci. A přišedši, trvá od jitra až dosavad, kromě že na chvilku doma pobyla.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 8, 'Tedy řekl Bóz k Rut: Slyš, dcero má, nechoď sbírati na jiné pole, aniž odcházej odsud, ale přídrž se teď děvek mých.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 9, 'Zůstávej na tom poli, na němž budou žíti, a choď za nimi, nebo jsem přikázal služebníkům svým, aby se tebe žádný nedotýkal. Bude-liť se chtíti píti, jdi k nádobám, a napí se té vody, kteréž by navážili služebníci moji.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 10, 'Tedy ona padla na tvář svou, a schýlivši se k zemi, řekla jemu: Odkudž mi to, že jsem nalezla milost před tebou, abys se známil ke mně, kteráž jsem cizozemka.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 11, 'Odpověděl Bóz a řekl: O všemť mi oznámeno jest, co jsi koli činila svegruši své po smrti muže svého, a že opustivši otce svého a matku svou, i zemi, v kteréžs se narodila, šla jsi mezi lid, kteréhožs prvé neznala.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 12, 'Odplatiž tobě Hospodin za skutek tvůj, a budiž mzda tvá dokonalá od Hospodina Boha Izraelského, poněvadž jsi přišla, abys pod křídly jeho doufala.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 13, 'Kterážto řekla: Nalezla jsem milost před tebou, pane můj, poněvadž jsi mne potěšil, a mluvils k srdci děvky své, ješto nejsem podobná jedné z děvek tvých.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 14, 'Tedy řekl jí Bóz: Když bude čas jísti, přistup sem, a pojez chleba, a omoč skyvu svou v octě. I posadila se při žencích, a podal jí pražmy; ona pak jedla až do sytosti, a ještě jí zbylo.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 15, 'I vstala, aby sbírala. Přikázal pak Bóz služebníkům svým, řka: Byť pak i mezi snopy sbírala, nezbraňujte jí.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 16, 'Nýbrž naschvál jí upouštějte z snopů a nechávejte, ať sbírá, a nedomlouvejte jí.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 17, 'Sbírala tedy na poli tom až do večera, a což sebrala, to vymlátila; i byla téměř míra efi ječmene.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 18, 'Kterýž vzavši, přišla do města, a viděla svegruše její to, což nasbírala. Vyňala také a dala jí to, což pozůstalo po nasycení jejím.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 19, 'I řekla jí svegruše její: Kdes sbírala dnes, a kdes pracovala? Budiž požehnaný ten, kterýž tě přijal. Tedy oznámila svegruši své, u koho pracovala, řkuci: Jméno muže, u kteréhož jsem pracovala dnes, jest Bóz.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 20, 'I řekla Noémi nevěstě své: Požehnanýť jest od Hospodina, že nepřestal milosrdenství svého nad živými i mrtvými. I to ještě k ní řekla Noémi: Blízký přítel náš a z příbuzných našich jest muž ten.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 21, 'Řekla jí také Rut Moábská: I to mi ještě řekl: Čeládky mé přídrž se, dokavadž by všeho, což mého jest, nedožali.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 22, 'Tedy řekla Noémi Rut nevěstě své: Dobré jest tedy, dcero má, abys vycházela s děvečkami jeho, ať by na jiném poli něco nepřekazili.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 23, 'A tak se přídržela Rut děvek Bózových, a sbírala klasy, dokudž nesžali ječmene a pšenice, a bydlela u svegruše své.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 1, 'Řekla jí potom Noémi svegruše její: Má dcero, nemám-liž pohledati tobě odpočinutí, aby tobě dobře bylo?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 2, 'Anobrž zdaliž Bóz ten příbuzný náš, s jehož jsi děvečkami byla, nebude víti ječmene na humně noci této?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 3, 'Protož umej se a pomaž, roucho své také oblec, a jdi na humno, však tak, aby nebylo známé muži tomu, prvé než by přestal jísti a píti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 4, 'A když půjde ležeti, znamenej místo, na kterémž lehne, a přijduc, pozdvihneš pláště u noh jeho, a tu se položíš; on pak oznámí tobě, co bys měla činiti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 5, 'Jížto Rut řekla: Cokoli mi rozkážeš, učiním.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 6, 'Šla tedy na to humno, a učinila všecko, což jí rozkázala svegruše její.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 7, 'Když pak pojedl Bóz a napil se, a rozveselilo se srdce jeho, šel spáti vedlé stohu; přišla i ona tiše, a pozdvihši pláště u noh jeho, položila se.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 8, 'A když bylo o půl noci, ulekl se muž ten a zchopil se, a aj, žena leží u noh jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 9, 'I řekl: Kdo jsi ty? A ona odpověděla: Já jsem Rut, děvka tvá. Vztáhni křídlo pláště svého na děvku svou, nebo příbuzný jsi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 10, 'A on řekl: Požehnaná jsi ty od Hospodina, dcero má. Větší jsi nyní pobožnosti dokázala, nežli prvé, že jsi nehledala mládenců bohatých aneb chudých.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 11, 'Protož nyní, dcero má, neboj se; vše, čehož žádáš, učiním tobě, nebo víť všecko město lidu mého, že jsi ty žena šlechetná.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 12, 'A také jest to pravé, že jsem příbuzný tvůj, ale jestiť příbuzný bližší nežli já.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 13, 'Odpočiniž tu přes noc, a když bude ráno, jestližeť on bude chtíti práva příbuznosti k tobě užiti, dobře, nechť užive. Pakliť nebude chtíti práva užiti k tobě, já právem příbuznosti pojmu tebe, živť jest Hospodin. Spiž tu až do jitra.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 14, 'A tak spala u noh jeho až do jitra. Potom vstala prvé, nežli by kdo poznati mohl bližního svého; nebo pečoval Bóz, aby někdo nezvěděl, že přišla žena ta na humno.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 15, 'A řekl: Přines loktušku, kterouž se odíváš, a drž ji. A když ji držela, naměřiv jí šest měr ječmene, vložil na ni. I vešla do města.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 16, 'A přišla k svegruši své. Kteráž řekla: Kdo jsi ty, dcero má? I vypravovala jí všecko, což jí učinil muž ten.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 17, 'A řekla: Šest měr těchto ječmene dal mi, nebo řekl ke mně: Nenavrátíš se prázdná k svegruši své.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 18, 'I řekla jí Noémi: Počekej, dcero má, až porozumíš, jak to padne; neboť neobleví muž ten, až tu věc dnes k místu přivede.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 1, 'Tedy Bóz všed do brány, posadil se tam. A aj, příbuzný ten, o němž on byl mluvil, šel tudy. I řekl jemu: Poď sem, a poseď tuto. Kterýž zastaviv se, sedl.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 2, 'A vzav Bóz deset mužů z starších města toho, řekl: Posaďte se tuto. I posadili se.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 3, 'Tedy řekl příbuznému tomu: Díl pole, kteréž bylo bratra našeho Elimelecha, prodala Noémi, kteráž se navrátila z krajiny Moábské.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 4, 'A já jsem umínil netajiti toho před tebou, a pravímť: Ujmi pole to před přísedícími těmito a staršími lidu mého. Jestliže chceš koupiti, kup; pakli nekoupíš, oznam mi. Nebo vím, že kromě tebe není žádného, kterýž by měl právo koupiti je, a já jsem po tobě. Tedy on řekl: Já koupím.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 5, 'I řekl Bóz: Když ujmeš pole to od Noémi, tedy i Rut Moábskou, manželku mrtvého, sobě pojmeš, abys vzbudil jméno mrtvého v dědictví jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 6, 'Odpověděl příbuzný ten: Nemohuť koupiti, abych snad nezahladil dědictví svého. Uživ ty práva příbuznosti mé, nebo já ho nemohu užiti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 7, '(Byl pak ten obyčej od starodávna v Izraeli při koupi a směnách, ku potvrzení všelijakého jednání, že szul jeden obuv svou, a dal ji druhému. A to bylo na svědectví té věci v Izraeli.)');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 8, 'Protož řekl příbuzný Bózovi: Ujmi ty. I szul obuv svou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 9, 'Tedy řekl Bóz starším těm a všemu lidu: Vy svědkové jste dnes, že jsem ujal všecko, což bylo Elimelechovo, i všecko to, což bylo Chelionovo a Mahalonovo, od Noémi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 10, 'Ano i Rut Moábskou, ženu Mahalonovu, vzal jsem sobě za manželku, abych vzbudil jméno mrtvého v dědictví jeho, a aby nebylo zahlazeno jméno mrtvého z bratří jeho, a z brány místa jeho. Vy svědkové jste dnes toho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 11, 'I řekl všecken lid, kterýž byl v bráně města, i starší: Svědkové jsme. Dejž Hospodin, aby žena vcházející do domu tvého byla jako Ráchel a jako Lía, kteréžto dvě vzdělaly dům Izraelský. Počínejž sobě zmužile v Efratě, a dosáhni jména v Betlémě.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 12, 'A ať jest dům tvůj jako dům Fáresa, (kteréhož porodila Támar Judovi,) z semene toho, kteréž by dal tobě Hospodin s mladicí touto.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 13, 'A tak Bóz pojal sobě Rut, a byla manželkou jeho. A když všel k ní, dal jí to Hospodin, že počala a porodila syna.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 14, 'I řekly ženy Noémi: Požehnaný Hospodin, kterýž nedopustil toho, abys měla zbavena býti příbuzného v tento čas, tak aby trvalo v Izraeli jméno jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 15, 'Onť očerství duši tvou, a chovati tě bude v starosti tvé; nebo nevěsta tvá, kteráž tě miluje, porodila ho, kteráž tobě lepší jest, nežli sedm synů.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 16, 'Tedy vzavši Noémi dítě, položila je na klín svůj, a byla pěstounkou jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 17, 'Daly mu pak jméno sousedy, kteréž pravily: Narodil se syn Noémi, a nazvaly ho jménem Obéd. Onť jest otec Izai, otce Davidova.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 18, 'A tito jsou rodové Fáresovi: Fáres zplodil Ezrona;');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 19, 'Ezron pak zplodil Rama, Ram pak zplodil Aminadaba;');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 20, 'Aminadab pak zplodil Názona, Názon pak zplodil Salmona;');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 21, 'Salmon pak zplodil Bóza, Bóz pak zplodil Obéda;');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 22, 'Obéd pak zplodil Izai, Izai pak zplodil Davida.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 1, 'Byl muž nějaký z Ramataim Zofim, s hory Efraim, jehož jméno bylo Elkána, syn Jerochama, syna Elihu, syna Tohu, syna Zuf Efratejského.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 2, 'A ten měl dvě ženy, jméno jedné Anna, a jméno druhé Penenna. Měla pak Penenna děti, ale Anna neměla dětí.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 3, 'I chodíval muž ten z města svého každého roku, aby se klaněl a obětoval Hospodinu zástupů, do Sílo, kdež byli dva synové Elí, Ofni a Fínes, kněží Hospodinovi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 4, 'Když pak přišel den, v němž obětoval Elkána, dal Penenně manželce své, a všechněm synům i dcerám jejím díly.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 5, 'Anně pak dal díl jeden výborný, nebo Annu miloval, ale Hospodin zavřel byl život její.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 6, 'Přesto kormoutila ji také velmi protivnice její, toliko aby ji popouzela, proto že Hospodin zavřel byl život její.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 7, 'To když činíval každého roku, a Anna též chodívala do domu Hospodinova, tak ji kormoutívala protivnice; ona pak plakávala a nic nejídala.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 8, 'Tedy řekl jí Elkána muž její: Anna, proč pláčeš? A proč nejíš? Proč tak truchlí srdce tvé? Zdaliž já nejsem tobě lepší nežli deset synů?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 9, 'Vstala tedy Anna, když pojedli v Sílo a napili se; a Elí kněz seděl na stolici u veřeje chrámu Hospodinova.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 10, 'Ona pak jsuci v hořkosti srdce, modlila se Hospodinu a plakala velmi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 11, 'A učinila slib, řkuci: Hospodine zástupů, jestliže vzhlédneš na trápení děvky své a rozpomeneš se na mne, a nezapomeneš na děvku svou, ale dáš služebnici své plod pohlaví mužského: tedy dám jej tobě, Hospodine, po všecky dny života jeho, a břitva nevejde na hlavu jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 12, 'I stalo se, když se dlouho modlila před Hospodinem, že Elí pozor měl na ústa její.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 13, 'Ale Anna mluvila v srdci svém; toliko rtové její se hýbali, hlasu pak jejího nebylo slyšeti. I domníval se Elí, že by opilá byla.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 14, 'Protož řekl jí Elí: Dlouho-liž budeš opilá? Vystřízvěj z vína svého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 15, 'Odpověděla Anna, řkuci: Nikoli, pane můj, žena jsem ducha truchlivého, ani vína ani nápoje opojného jsem nepila, ale vylila jsem duši svou před Hospodinem.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 16, 'Nepřirovnávejž děvky své k ženě bezbožné, nebo z velikého myšlení a hořkosti své mluvila jsem až dosavad.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 17, 'Jíž odpověděl Elí, řka: Jdiž u pokoji, a Bůh Izraelský dejž tobě k prosbě tvé, zač jsi ho prosila.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 18, 'I řekla: Ó by nalezla děvka tvá milost před očima tvýma! Tedy odšedši žena cestou svou, pojedla, a tvář její nebyla více smutná.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 19, 'I vstali velmi ráno, a poklonu učinivše před Hospodinem, navrátili se, a přišli do domu svého do Ramata. Poznal pak Elkána Annu manželku svou, a Hospodin rozpomenul se na ni.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 20, 'I stalo se po vyplnění dnů, jakž počala Anna, že porodila syna, a nazvala jméno jeho Samuel; nebo řekla: Vyprosila jsem ho na Hospodinu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 21, 'Šel pak muž ten Elkána se vší čeledí svou, aby obětoval Hospodinu obět výroční a slib svůj.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 22, 'Ale Anna nešla, nebo řekla muži svému: Až odchovám dítě, tehdy povedu je, aby ukáže se před Hospodinem, zůstalo tam na věky.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 23, 'I řekl jí Elkána muž její: Učiň, cožť se dobrého vidí, zůstaň, dokudž neodchováš jeho. Ó by toliko utvrdil Hospodin slovo své! A tak zůstala žena, a krmila syna svého, až jej i odchovala.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 24, 'Potom, když ho odchovala, vedla jej s sebou, se třmi volky a jednou efi mouky a nádobou vína, i uvedla jej do domu Hospodinova v Sílo; dítě pak ještě bylo malé.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 25, 'Tedy zabili volka a přivedli dítě k Elí.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 26, 'Ona pak řekla: Poslyš mne, pane můj. Jako jest živa duše tvá, pane můj, já jsem žena ta, kteráž jsem stála tuto s tebou, modleci se Hospodinu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 27, 'Za toto dítě jsem prosila, a dal mi Hospodin k prosbě mé to, čehož jsem prosila od něho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 28, 'Protož já také oddávám jej Hospodinu; po všecky dny, v nichž živ bude, oddanýť jest Hospodinu. A učinil tu poklonu Hospodinu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 1, 'I modlila se Anna a řekla: Zplésalo srdce mé v Hospodinu, a vyzdvižen jest roh můj v Hospodinu; rozšířila se ústa má proti nepřátelům mým, nebo rozveselila jsem se v spasení tvém.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 2, 'Neníť žádný tak svatý jako Hospodin; nýbrž žádného není kromě tebe, neníť žádný tak silný jako Bůh náš.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 3, 'Nemluvtež již více hrdě, a nevycházej z úst vašich slovo pyšné; nebo Bůh silný vševědoucí jest Hospodin, a usilování jeho jemu nepochybují.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 4, 'Lučiště i silní potříni jsou, a mdlí opásáni jsou silou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 5, 'Sytí z chleba jednají se k dílu, a hladovití přestali lačněti, tak že neplodná porodila sedmero, a kteráž mnoho dětí měla, zemdlena jest.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 6, 'Hospodin umrtvuje i obživuje, uvodí do pekla i vyvodí.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 7, 'Hospodin ochuzuje i zbohacuje, ponižuje i povyšuje.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 8, 'Nuzného vyzdvihuje z prachu, a z hnoje vyvyšuje chudého, aby je posadil s knížaty, a stolici slávy dědičně jim dal; nebo Hospodinovy jsou stežeje země, na nichž založil okršlek.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 9, 'Onť ostříhá noh svatých svých, ale bezbožní ve tmě umlknou; nebo ne v síle záleží síla člověka.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 10, 'Kteříž se protiví Hospodinu, setříni budou, na takové s nebe hřímati bude. Hospodin souditi bude končiny země, a dá sílu králi svému, a vyvýší roh pomazaného svého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 11, 'I navrátil se Elkána do Ramaty, do domu svého, a pacholátko přisluhovalo Hospodinu při knězi Elí.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 12, 'Synové pak Elí byli bezbožní, a neznali Hospodina.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 13, 'Nebo těch kněží obyčej při lidu byl: Kdokoli obětoval obět, přicházel kněžský mládenec, když se maso vařilo, maje v ruce své hák třízubý,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 14, 'A vrazil jej do nádoby neb do kotlíku, neb do pánve, aneb do hrnce, a cokoli zachytil hák, to sobě bral kněz. Tak činívali všemu lidu Izraelskému, kteříž tam přicházeli do Sílo.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 15, 'Nýbrž, prvé než tuk zapalovali, přicházel mládenec kněžský a říkal člověku, kterýž obětoval: Dej masa, ať upeku knězi, nebo nevezme od tebe masa vařeného, ale surové.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 16, 'Jemuž odpověděl-li člověk ten: Nechť jest prvé zapálen tuk, a potom vezmeš sobě, čehož žádá duše tvá, on říkal: Nikoli, ale dej hned; jestliže pak nedáš, mocí vezmu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 17, 'I byl to hřích mládenců těch před Hospodinem velmi veliký; nebo pohrdali lidé obětmi Hospodinovými.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 18, 'Samuel pak přisluhoval před Hospodinem, mládenček, oděný jsa efodem lněným.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 19, 'A matka jeho dělávala mu sukničku malou, a přinášela jemu každého roku, když přicházela s mužem svým k obětování oběti výroční.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 20, 'I požehnal Elí Elkánovi a manželce jeho, řka: Dejž tobě Hospodin símě z ženy této za oddaného, kteréhož jsi vyžádal na Hospodinu. I odešli na místo své.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 21, 'Tedy navštívil Hospodin Annu, kteráž počala a porodila tři syny a dvě dcery. Ale mládenček Samuel rostl před Hospodinem.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 22, 'Elí pak byl starý velmi a slyšel všecky věci, kteréž činili synové jeho všemu Izraeli, a kterak obývali s ženami, kteréž přisluhovaly u dveří stánku úmluvy.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 23, 'I řekl jim: Proč činíte takové věci? Nebo já slyším zlé slovo o vás ode všeho lidu tohoto.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 24, 'Nikoli, synové moji, neboť není dobrá pověst, kterouž já slyším, že odvracíte lid Hospodinův.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 25, 'Zhřeší-li člověk proti člověku, souditi ho bude soudce; pakli kdo zhřeší proti Hospodinu, kdo se zasadí o něho? Ale neuposlechli hlasu otce svého, nebo je chtěl zbíti Hospodin.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 26, 'Ale mládenček Samuel prospíval a rostl, a milý byl, jakož před Hospodinem, tak i před lidmi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 27, 'I přišel muž Boží k Elí a řekl jemu: Takto praví Hospodin: Zdaliž jsem se patrně nezjevil domu otce tvého, když byli v Egyptě, v domě Faraonově?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 28, 'A vyvolil jsem ho sobě ze všech pokolení Izraelských za kněze, aby obětoval na oltáři mém, a aby kadil vonnými věcmi a nosil efod přede mnou; dal jsem také domu otce tvého všecky ohnivé oběti synů Izraelských.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 29, 'Proč pošlapáváte obět mou, i suchou obět mou, kterouž jsem přikázal v příbytku tomto? A víces ctil syny své nežli mne, abyste tyli prvotinami všech obětí suchých Izraele lidu mého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 30, 'Protož praví Hospodin Bůh Izraelský: Řeklť jsem byl zajisté, dům tvůj a dům otce tvého přisluhovati měl přede mnou až na věky, ale nyní praví Hospodin: Odstup to ode mne; nebo těch, kteříž mne ctí, poctím, kteříž pak mnou pohrdají, v pohrdání přijdou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 31, 'Aj, dnové přicházejí, že odetnu rámě tvé a rámě domu otce tvého, aby nebylo starce v domě tvém.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 32, 'A viděti budeš protivníka v příbytku Páně, ve všem, čehož Bůh štědře udíleti bude Izraelovi, aniž bude starce v domě tvém po všecky dny.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 33, 'A ačkoli nevyhladím do konce muže od oltáře svého, abych trápil oči tvé a bolestí ssužoval duši tvou, všecko však množství domu tvého zemrou v věku vyspělém.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 34, 'A to měj za znamení, což přijde na dva syny tvé, Ofni a Fínesa: oba jednoho dne umrou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 35, 'Vzbudím pak sobě kněze věrného, kterýž vedlé srdce mého a vedlé duše mé vše konati bude, a vzdělám jemu dům stálý, aby přisluhoval před pomazaným mým po všecky dny.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 36, 'A budeť, že kdožkoli pozůstane z domu tvého, přijde, aby se poklonil jemu, pro peníz stříbrný a pro skyvu chleba, a řekne: Připusť mne, prosím, k jedné třídě kněžské, abych jedl chléb.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 1, 'Mládenček pak Samuel přisluhoval Hospodinu při Elí, a řeč Hospodinova byla vzácná v těch dnech, aniž bývalo vidění zjevného.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 2, 'Stalo se pak jednoho dne, když Elí ležel na místě svém, (a již byl počal scházeti na oči, a nemohl viděti,)');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 3, 'Samuel také spal, a světlo Boží ještě zhašeno nebylo v chrámě Hospodinově, v němž byla truhla Boží,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 4, 'Že zavolal Hospodin Samuele. Kterýž řekl: Teď jsem.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 5, 'I běžel k Elí a řekl: Teď jsem, nebo jsi mne volal. I odpověděl: Nevolal jsem, jdi zase spáti. Kterýž odšed, spal.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 6, 'Opět pak Hospodin zavolal Samuele. A vstav Samuel, šel k Elí a řekl: Teď jsem, nebo jsi mne volal. I odpověděl: Nevolalť jsem, synu můj; jdi zase, spi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 7, 'Samuel pak ještě neznal Hospodina, a ještě nebyla mu zjevena řeč Hospodinova.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 8, 'Tedy opět Hospodin zavolal Samuele po třetí. Kterýžto vstav, šel k Elí a řekl: Teď jsem, nebo jsi mne volal. Tedy srozuměl Elí, že byl Hospodin volal mládence.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 9, 'I řekl Elí k Samuelovi: Jdi, spi, a bude-li tě volati, řekneš: Mluv, Hospodine, nebo slyší služebník tvůj. Odšel tedy Samuel, a spal na místě svém.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 10, 'I přišel Hospodin, a stál a zavolal, jako i prvé, a řekl: Samueli, Samueli! Odpověděl Samuel: Mluv, nebo slyší služebník tvůj.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 11, 'I řekl Hospodin Samuelovi: Aj, já učiním věc takovou v Izraeli, kterouž kdokoli uslyší, zníti jemu bude v obou uších jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 12, 'V ten den uvedu na Elí všecko to, což jsem mluvil proti domu jeho; počnuť i dokonám.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 13, 'A ukáži jemu, že já soudím dům jeho až na věky pro nepravost, o níž věděl; nebo znaje, že na se zlořečenství uvodí synové jeho, a však nezbránil jim.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 14, 'A protož jsem zapřisáhl domu Elí, že nebude vyčištěna nepravost domu Elí žádnou obětí, ani obětí suchou až na věky.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 15, 'I spal Samuel až do jitra, a otevřel dvéře domu Hospodinova; ostýchal se pak Samuel oznámiti Elí toho vidění.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 16, 'Tedy povolal Elí Samuele a řekl: Samueli, synu můj. Kterýž odpověděl: Teď jsem.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 17, 'I řekl: Jaká jest to řeč, kterouž mluvil tobě? Netaj medle přede mnou. Toto učiň tobě Bůh a toto přidej, jestliže co zatajíš přede mnou ze všech slov, kteráž mluvil tobě.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 18, 'A tak oznámil jemu Samuel všecka slova, a ničeho nezatajil před ním. A on řekl: Hospodinť jest, nechť učiní, což ráčí.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 19, 'Rostl pak Samuel, a Hospodin byl s ním, tak že nedopustil padnouti žádnému slovu jeho na zem.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 20, 'Z čehož poznal všecken Izrael od Dan až do Bersabé, že Samuel jest věrný prorok Hospodinův.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 21, 'Nebo se jemu i potom ukazoval Hospodin v Sílo, jakož se byl prvé zjevil Hospodin Samuelovi v Sílo, skrze řeč Hospodinovu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 1, 'I stalo se vedlé řeči Samuelovy všemu lidu Izraelskému. Nebo když vytáhl Izrael proti Filistinským k boji, a položili se při Eben-Ezer, Filistinští pak položili se v Afeku;');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 2, 'A když se sšikovali Filistinští proti Izraelovi, a již se potýkali: poražen jest Izrael od Filistinských, tak že jich zbito v té bitvě na poli takměř čtyři tisíce mužů.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 3, 'I navrátil se lid do stanů, a řekli starší Izraelští: Proč nás dnes Hospodin porazil před Filistinskými? Vezměme k sobě z Sílo truhlu smlouvy Hospodinovy, ať přijde mezi nás, a vysvobodí nás z rukou nepřátel našich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 4, 'Poslal tedy lid do Sílo, a vzali odtud truhlu smlouvy Hospodina zástupů, sedícího na cherubínech. Byli také tam dva synové Elí s truhlou smlouvy Boží, Ofni a Fínes.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 5, 'Když pak přinesena byla truhla smlouvy Hospodinovy do vojska, zkřikl všecken Izrael s velikým plésáním, až země vzněla.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 6, 'Uslyševše pak Filistinští hluk plésání, řekli: Jaký jest to hlas výskání velikého tohoto v vojště Hebrejském? I poznali, že truhla Hospodinova přišla do vojska.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 7, 'Protož báli se Filistinští, když praveno bylo: Přišel Bůh do vojska jejich; a řekli: Běda nám, nebo nebylo prvé nic k tomu podobného.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 8, 'Běda nám! Kdo nás vysvobodí z ruky těch bohů silných? Tiť jsou bohové, kteříž zbili Egypt všelikou ranou i na poušti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 9, 'Posilňte se a buďte muži, ó Filistinští, abyste nesloužili těm Hebrejským, jako oni sloužili vám; buďtež tedy muži a bojujte.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 10, 'Bojovali tedy Filistinští, a poražen jest Izrael, a utíkali jeden každý do stanu svého. I byla ta porážka veliká velmi, nebo padlo z Izraele třidceti tisíc pěších;');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 11, 'Také truhla Boží vzata, a dva synové Elí zabiti, Ofni a Fínes.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 12, 'Běže pak jeden Beniaminský z bitvy, přišel do Sílo téhož dne, maje roucho roztržené a hlavu prstí posypanou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 13, 'Přišel tedy, a aj, Elí seděl na stolici při cestě, hledě, nebo srdce jeho lekalo se za truhlu Boží; a když všel muž ten, a oznámil v městě, kvílilo všecko město.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 14, 'A uslyšev Elí hlas křiku toho, řekl: Jaký jest to hlas hřmotu tohoto? Muž pak ten pospíchaje, přiběhl, aby oznámil Elí.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 15, '(A byl Elí v devadesáti a osmi letech; oči také jeho byly již pošly, a nemohl viděti.)');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 16, 'I řekl muž ten k Elí: Já jdu z bitvy, z bitvy zajisté utekl jsem dnes. I dí jemu on: Co se tam stalo, můj synu?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 17, 'Odpověděl ten posel a řekl: Utekl Izrael před Filistinskými, také i porážka veliká stala se v lidu, ano i oba synové tvoji zabiti jsou, Ofni a Fínes, a truhla Boží jest vzata.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 18, 'I stalo se, že jakž jmenoval truhlu Boží, spadl Elí s stolice nazpět při úhlu brány, a tak zlomiv šíji, umřel; nebo byl muž starý a těžký. On soudil Izraele čtyřidceti let.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 19, 'Nevěsta pak jeho, manželka Fínesova, jsuc těhotná a blízká porodu, uslyševši také tu pověst, že by truhla Boží vzata byla, a že umřel tchán její i muž její, sklonila se a porodila; nebo se obořily na ni úzkosti její.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 20, 'A v ten čas, když ona umírala, řekly, kteréž stály při ní: Neboj se, však jsi porodila syna. Kteráž nic neodpověděla, aniž toho připustila k srdci svému.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 21, 'I nazvala dítě Ichabod, řkuci: Přestěhovala se sláva z Izraele; proto že vzata byla truhla Boží, a umřel tchán i muž její.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 22, 'Protož řekla: Přestěhovala se sláva z Izraele, nebo vzata jest truhla Boží.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 5, 1, 'Filistinští pak vzali truhlu Boží, a zanesli ji z Eben-Ezer do Azotu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 5, 2, 'Vzali tedy Filistinští truhlu Boží, a vnesli ji do domu modly Dágon, a postavili ji vedlé Dágona.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 5, 3, 'A když Azotští na zejtří ráno vstali, aj, Dágon povalený ležel tváří svou na zemi před truhlou Hospodinovou. I vzali Dágona a postavili jej na místo jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 5, 4, 'A když opět ráno nazejtří vstali, aj, Dágon, jakž upadl, ležel tváří svou na zemi před truhlou Hospodinovou; hlava pak Dágonova a obě dlaně rukou jeho odražené byly na prahu, jen ho špalek zůstal.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 5, 5, 'Protož kněží Dágonovi a všickni, kteříž vcházejí do domu Dágonova, nešlapají na prah Dágonův v Azotu až do tohoto dne.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 5, 6, 'Tedy ztížena jest ruka Hospodinova nad Azotskými, a pohubila je, (nebo ranila je neduhy na zadku), Azot i končiny jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 5, 7, 'Vidouce pak muži Azotští, co se děje, řekli: Nechť nezůstává truhla Boha Izraelského u nás, nebo těžká jest ruka jeho proti nám, a proti Dágonovi bohu našemu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 5, 8, 'I obeslali a shromáždili všecka knížata Filistinská k sobě, a řekli: Co učiníme s truhlou Boha Izraelského? Odpověděli: Nechť jest doprovozena do Gát truhla Boha Izraelského. I zprovodili tam truhlu Boha Izraelského.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 5, 9, 'Stalo se pak, když ji vyprovázeli, že ruka Hospodinova přikročila k městu trápením velikým velmi, a ranila muže města od malého až do velikého, a nametalo se jim v tajných místech plno vředů.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 5, 10, 'Z té příčiny poslali truhlu Boží do Akaron. A když přišla truhla Boží do Akaron, zkřikli Akaronští, řkouce: Zprovodili k nám truhlu Boha Izraelského, aby nás pomořili i náš lid.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 5, 11, 'Protož poslavše, shromáždili všecka knížata Filistinská, a řekli: Odešlete truhlu Boha Izraelského, ať se navrátí na místo své, a nezmoří nás i lidu našeho. Nebo bylo trápení smrtelné po všem tom městě, a velmi těžká byla ruka Boží tam.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 5, 12, 'Muži pak, kteříž nezemřeli, raněni byli neduhy na zadku, tak že křik města vstupoval až k nebi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 1, 'Byla pak truhla Hospodinova v krajině Filistinské za sedm měsíců.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 2, 'Tedy Filistinští povolavše kněží a hadačů, řekli: Co učiníme s truhlou Hospodinovou? Oznamte nám, kterak bychom ji odeslali na místo její?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 3, 'Kteříž odpověděli: Jestliže odešlete truhlu Boha Izraelského, neodsílejte jí prázdné, ale všelijak dejte jí obět za provinění; tehdy uzdraveni budete, a poznáte, proč ruka jeho neodešla od vás.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 4, 'I řekli: Jakáž jest to obět za hřích, kterouž jí dáti máme? Odpověděli: Vedlé počtu knížat Filistinských pět zadků zlatých a pět myší zlatých; nebo rána jednostejná jest na všechněch, i na knížatech vašich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 5, 'Uděláte tedy podobenství zadků svých a podobenství myší svých, kteréž pokazily zemi, i dáte slávu Bohu Izraelskému; snad pozlehčí ruky své nad vámi, i nad bohy vašimi a nad zemí vaší.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 6, 'A proč obtěžujete srdce svá, jako jsou obtížili Egyptští a Farao srdce své? Zdaliž, když divné věci prokázal při nich, nepropustili jich, a oni odešli?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 7, 'A protož udělejte vůz nový jeden a vezměte dvě krávy otelené, na kteréž jha nebylo vzkládáno, a zapřáhněte ty krávy do vozu, a zavřete telata jejich doma, aby za nimi nešla.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 8, 'A vezmouce truhlu Hospodinovu, vstavte ji na vůz; nádoby pak zlaté, kteréž jste dali jí za provinění, položte v škřiňce po boku jejím, a propusťte ji, ať odejde.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 9, 'A šetřte: Jestližeť cestou k cíli svému půjde do Betsemes, onť jest nám způsobil všecko toto zlé přenáramné; pakli nic, poznáme, že ne ruka jeho dotkla se nás, ale náhodou nám to přišlo.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 10, 'Učinili tedy ti muži tak, a vzavše dvě krávy otelené, zapřáhli je do toho vozu, a telata jejich zavřeli doma.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 11, 'A vstavili truhlu Hospodinovu na vůz, i škřiňku i myši zlaté, a podobizny zadků svých.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 12, 'I šly upřímo krávy cestou, kteráž vede do Betsemes, silnicí jednou předce jdouce a řičíce, aniž se uchýlily na pravo aneb na levo. Knížata také Filistinská šla za nimi až ku pomezí Betsemes.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 13, 'Betsemští pak žali tehdáž pšenici v údolí, a pozdvihše očí svých, uzřeli truhlu; i veselili se, vidouce ji.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 14, 'A když přijel vůz na pole Jozue Betsemského, tu se zastavil. I byl tu kámen veliký. Tedy zsekavše dříví vozu toho i ty krávy, obětovali je v obět zápalnou Hospodinu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 15, 'Levítové pak složili truhlu Hospodinovu i škřiňku, kteráž byla při ní, v níž byly nádoby zlaté, a postavili na ten kámen veliký. Muži pak Betsemští dodávali obětí zápalných, a obětovali oběti v ten den Hospodinu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 16, 'Což viděvše knížata Filistinská, navrátili se do Akaron téhož dne.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 17, 'Tito jsou pak zadkové zlatí, kteréž dali Filistinští za své provinění Hospodinu, za Azot jeden, za Gázu jeden, za Aškalon jeden, za Gát jeden, za Akaron jeden.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 18, 'Myši také zlaté, vedlé počtu všech měst Filistinských, za patero knížetství, od města hrazeného až do vsi nehrazené, a až k kameni tomu velikému, na němž postavili truhlu Hospodinovu, kterýž jest až do tohoto dne na poli Jozue Betsemského.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 19, 'Pobil pak Hospodin z mužů Betsemských, kteříž hleděli do truhly Hospodinovy, pobil, pravím, z lidu padesát tisíců a sedmdesáte mužů. I kvílil lid, proto že učinil Hospodin v lidu porážku velikou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 20, 'Protož řekli muži Betsemští: Kdož bude moci ostáti před Hospodinem Bohem svatým tímto? A k komu odejde od nás?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 21, 'I poslali posly k obyvatelům Kariatjeharim, řkouce: Vrátili zase Filistinští truhlu Hospodinovu; přiďte, vezměte ji k sobě.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 1, 'Tedy přišli muži Kariatjeharim a vzali odtud truhlu Hospodinovu, a vnesli ji do domu Abinadabova na pahrbek, a Eleazara syna jeho posvětili, aby ostříhal truhly Hospodinovy.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 2, 'Stalo se pak, že od toho času, jakž zůstala truhla v Kariatjeharim, když bylo přeběhlo mnoho dní, a byl již rok dvadcátý, teprv se roztoužil všecken dům Izraelský po Hospodinu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 3, 'Nebo byl mluvil Samuel ke všemu domu Izraelskému, řka: Jestliže celým srdcem svým obracíte se k Hospodinu, odejměte bohy cizí z prostředku sebe i Astarota, a ustavte srdce své při Hospodinu, a služte jemu samému, a vysvobodí vás z ruky Filistinských.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 4, 'A tak zavrhli synové Izraelští Bálim i Astarota, a sloužili Hospodinu samému.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 5, 'Byl také řekl Samuel: Shromažďte všecken lid Izraelský do Masfa, a modliti se budu za vás Hospodinu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 6, 'I shromáždili se do Masfa, a vážíce vodu, vylévali před Hospodinem, a postíce se v ten den, řekli tam: Zhřešili jsme proti Hospodinu. A soudil Samuel syny Izraelské v Masfa.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 7, 'Uslyšavše pak Filistinští, že synové Izraelští shromáždili se do Masfa, vytáhla knížata Filistinská proti Izraelovi. Což když uslyšeli synové Izraelští, báli se příchodu Filistinských.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 8, 'Pročež řekli synové Izraelští Samuelovi: Nepřestávej volati za nás k Hospodinu Bohu našemu, aby nás vysvobodil z ruky Filistinských.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 9, 'Vzav tedy Samuel beránka jednoho, kterýž ještě ssal, obětoval ho celého v obět zápalnou Hospodinu. I modlil se Samuel Hospodinu za Izraele, a uslyšel jej Hospodin.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 10, 'I bylo, že když Samuel obětoval obět zápalnou, Filistinští přiblížili se, aby bojovali proti Izraelovi, ale zahřměl Hospodin hřímáním náramným v ten den nad Filistinskými, a potřel je, i poraženi jsou před tváří Izraele.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 11, 'Vytáhše pak muži Izraelští z Masfa, stihali Filistinské, a bili je až pod Betchar.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 12, 'Tehdy vzav Samuel kámen jeden, položil jej mezi Masfa a mezi Sen, a nazval jméno jeho Eben-Ezer; nebo řekl: Až potud pomáhal nám Hospodin.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 13, 'A tak sníženi jsou Filistinští, a netáhli více na pomezí Izraelské; a byla ruka Hospodinova proti Filistinským po všecky dny Samuelovy.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 14, 'Navrácena jsou také města Izraelovi, kteráž byli Filistinští odtrhli od Izraele, počna od Akaron až do Gát; i pomezí jejich vysvobodil Izrael z ruky Filistinských. A byl pokoj mezi Izraelem a Amorejskými.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 15, 'I soudil Samuel Izraele po všecky dny života svého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 16, 'A chodě každého roku, obcházel Bethel a Galgala i Masfa, a soudil Izraele na všech těch místech.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 17, '(Potom navracoval se do Ramata, nebo tam byl dům jeho, a tam soudil Izraele.) Tam také vzdělal oltář Hospodinu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 1, 'Když se pak zstaral Samuel, ustanovil syny své za soudce v Izraeli.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 2, 'A bylo jméno syna jeho prvorozeného Joel, a jméno druhého Abia; ti byli soudcové v Bersabé.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 3, 'Nechodili pak synové jeho po cestách jeho, ale uchýlili se po lakomství, a berouce dary, převraceli soud.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 4, 'Shromáždili se tedy všickni starší Izraelští, a přišli k Samuelovi do Ramata.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 5, 'A řekli jemu: Aj, tys se již zstaral, a synové tvoji nechodí po cestách tvých; protož nyní ustanov nám krále, aby soudil nás, jakož jest u všech národů.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 6, 'I nelíbila se ta řeč Samuelovi, že řekli: Dej nám krále, aby nás soudil. Protož modlil se Samuel Hospodinu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 7, 'Tedy řekl Hospodin Samuelovi: Uposlechni hlasu lidu ve všem, což mluví tobě; nebo ne tebouť jsou pohrdli, ale mnou pohrdli, abych nekraloval nad nimi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 8, 'Podlé všech skutků těch, kteréž činili od onoho dne, v němž jsem je vyvedl z Egypta až do tohoto dne, kdyžto opustili mne, a sloužili bohům cizím, takť oni činí i tobě.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 9, 'Protož nyní uposlechni hlasu jejich, a však nejprv osvědč pilně před nimi, a oznam jim obyčej krále, kterýž nad nimi kralovati bude.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 10, 'I mluvil Samuel všecky řeči Hospodinovy k lidu, kteříž krále žádali od něho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 11, 'A řekl: Tento bude obyčej krále, kterýž kralovati bude nad vámi: Bráti bude syny vaše, a dá je k vozům svým, a zdělá sobě z nich jezdce, a běhati budou před vozem jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 12, 'Také ustanoví je sobě za hejtmany nad tisíci a za padesátníky, a aby jemu orali rolí jeho, a žali obilé jeho, též aby jemu dělali nástroje válečné a přípravy k vozům jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 13, 'Dcery také vaše bráti bude, aby dělaly masti, a byly kuchařky a pekařky.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 14, 'Nadto pole vaše a vinice vaše, i olivoví vaše nejvýbornější pobéře a rozdá služebníkům svým.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 15, 'Také z toho, což vsejete, a z vinic vašich desátky bráti bude, a dá komorníkům a služebníkům svým.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 16, 'Též služebníky vaše a děvky vaše, a mládence vaše nejzpůsobnější, i osly vaše vezme, aby jimi dělal dílo své.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 17, 'Z stád vašich desátky bráti bude, a vy budete jemu za služebníky.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 18, 'I budete volati v ten den příčinou krále vašeho, kteréhož byste sobě vyvolili, a nevyslyší vás Hospodin dne toho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 19, 'Nechtěl však lid uposlechnouti řeči Samuelovy, a řekli: Nikoli, ale král bude nad námi,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 20, 'Abychom i my také byli, jako všickni jiní národové, a souditi nás bude král náš, a vycházeje před námi, bojovati bude za nás.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 21, 'Vyslyšev tedy Samuel všecka slova lidu, oznámil je Hospodinu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 22, 'I řekl Hospodin Samuelovi: Uposlechni hlasu jejich, a ustanov jim krále. Protož řekl Samuel mužům Izraelským: Jdětež jeden každý do města svého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 1, 'Byl pak muž z pokolení Beniamin, jménem Cis, syn Abiele syna Seror, syna Bechorat, syna Afia, syna muže Jemini, muž udatný.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 2, 'Ten měl syna jménem Saule, mládence krásného, tak že žádného z synů Izraelských nebylo pěknějšího nad něj; od ramene svého vzhůru převyšoval všecken lid.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 3, 'Byly se pak ztratily oslice Cis, otce Saulova. I řekl Cis Saulovi synu svému: Vezmi i hned s sebou jednoho z služebníků, a vstana, jdi, hledej oslic.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 4, 'A tak šel přes horu Efraim, a prošel až do země Salisa, a nic nenalezli; prošli také zemi Sálim, a nic nenalezli. Ještě přešli i zemi Jemini, a nenalezli.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 5, 'Když pak přišli do země Zuf, řekl Saul služebníku svému, kterýž byl s ním: Poď, a navraťme se, aby otec můj nechaje těch oslic, neměl starosti o nás.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 6, 'Kterýž řekl jemu: Aj, nyní muž Boží jest v městě tomto, a muž ten jest znamenitý; cožkoli praví, všecko se tak stává. Medle, jděme tam, zdali by oznámil nám cestu naši, kterouž bychom jíti měli.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 7, 'Odpověděl Saul služebníku svému: Aj, půjdeme. Co pak přineseme muži tomu? Nebo jsme chléb vytrávili z pytlíků našich, ani daru nemáme, kterýž bychom přinesli muži Božímu. Což máme?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 8, 'I doložil služebník, odpovídaje Saulovi, a řekl: Hle, nalezl jsem u sebe čtvrt lotu stříbra; to dám muži Božímu, aby nám oznámil cestu naši.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 9, '(Za starodávna v Izraeli tak říkával každý, kdož jíti měl raditi se s Bohem: Poďte, a půjdeme až k vidoucímu. Nebo ten, kterýž nyní slove prorok, za starodávna sloul vidoucí.)');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 10, 'Řekl tedy Saul služebníku svému: Dobrá jest řeč tvá, nu, jděmež. I šli do města, v kterémž byl muž Boží.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 11, 'A když vcházeli na horu města, potkali se s děvečkami, vycházejícími vážit vody. I řekli jim: Jest-li zde vidoucí?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 12, 'Kteréž odpověděly jim a řekly: Jest. Hle, a on před tebou, pospěš tedy; nebo dnes přišel do města, proto že obětuje dnes lid na té hoře.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 13, 'Hned jakž vejdete do města, tedy naleznete ho, prvé než vstoupí na horu k jídlu. Lid zajisté nebude jísti, dokudž on nepřijde, nebo on požehná obětí, a potom pozvaní jísti budou. A protož jděte, nebo v tuto chvíli naleznete ho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 14, 'I šli do města. A když vcházeli do prostřed města, aj, Samuel vycházel proti nim, aby vstoupil na tu horu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 15, 'Hospodin pak zjevil Samuelovi o jeden den prvé, nežli přišel Saul, řka:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 16, 'V tuto chvíli zítra pošli k tobě muže z země Beniamin, kteréhož pomažeš, aby byl vůdce lidu mého Izraelského, a vysvobodíť lid můj z ruky Filistinských; vzhlédlť jsem zajisté na lid svůj, nebo přišlo volání jeho ke mně.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 17, 'A když Samuel uzřel Saule, řekl jemu Hospodin: Aj, teď ten muž, o kterémž pravil jsem tobě: tenť spravovati bude lid můj.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 18, 'Tedy přistoupil Saul k Samuelovi v bráně, a řekl: Ukaž mi, prosím, kde jest tuto dům vidoucího?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 19, 'I odpověděl Samuel Saulovi: Já jsem vidoucí. Vstupiž přede mnou na horu, a budete dnes jísti se mnou; potom ráno propustím tě, a cožkoli jest v srdci tvém, oznámím tobě.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 20, 'O oslice pak, kteréžť se ztratily dnes třetí den, nic se nestarej, nebo nalezeny jsou. Ale na koho žádost všeho Izraele? Zdali ne na tebe a na všecken dům otce tvého?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 21, 'I odpověděl Saul a řekl: Zdaliž já nejsem syn Jemini, z nejmenšího pokolení Izraelského? Ano i čeled má jest nejchaternější ze všech čeledí pokolení Beniaminova. Pročež jsi tedy ke mně mluvil taková slova?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 22, 'A pojav Samuel Saule i služebníka jeho, uvedl je do pokoje, a dal jim místo nejpřednější mezi pozvanými, jichž bylo okolo třidcíti mužů.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 23, 'I řekl Samuel kuchaři: Dej sem ten díl, kterýž jsem dal tobě, o kterémžť jsem řekl: Schovej jej obzvláštně.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 24, 'Když tedy přinesl kuchař plece i s tím, což se ho přídrželo, položil Samuel před Saule, a řekl: Teď, což pozůstalo, vezmi sobě, jez; až k této chvíli zajisté zachováno jest to pro tebe, jakž jsem řekl: Lidu jsem pozval. I jedl Saul s Samuelem v ten den.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 25, 'A když sešli s hory do města, mluvil s Saulem na vrchní podlaze.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 26, 'Potom vstali velmi ráno. I stalo se, když záře vzcházela, že zavolal Samuel Saule na hůru, řka: Vstaň, a propustím tě. Vstal tedy Saul, a vyšli oba ven, on i Samuel.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 27, 'A když přicházeli na konec města, řekl Samuel Saulovi: Rci služebníku, ať jde napřed, (i šel;) ty pak pozastav se málo, ažť oznámím řeč Boží.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 1, 'Tedy vzal Samuel nádobku oleje, a vylil na hlavu jeho, a políbil ho, i řekl: Aj, teď pomazal tě Hospodin nad dědictvím svým za vůdce.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 2, 'Když půjdeš dnes ode mne, nalezneš dva muže u hrobu Ráchel v končinách Beniamin v Zelzachu. Kteříž řeknou tobě: Nalezeny jsou oslice, jichž jsi chodil hledati. A aj, otec tvůj nechav péče o oslice, stará se o vás, pravě: Kterak udělám o syna svého?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 3, 'A odejda odtud dále, přijdeš až k rovině Tábor. I potkají se s tebou tam tři muži vstupující k Bohu do Bethel, jeden nesa tři kozelce, druhý nesa tři pecníky chleba, a třetí nesa láhvici vína.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 4, 'Kteřížto když tě pozdraví, dadíť dva chleby, kteréž přijmeš z rukou jejich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 5, 'Potom přijdeš na pahrbek Boží, na kterémž jest stráž Filistinská. A když tam vejdeš do města, potká se s tebou zástup proroků sstupujících s hory, a před nimi loutna, buben i píšťalka a harfa, a oni prorokovati budou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 6, 'I sstoupí na tě Duch Hospodinův, a prorokovati budeš s nimi, a proměněn budeš v muže jiného.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 7, 'Když tedy zběhnou se tato znamení při tobě, učiň, cožkoli najde ruka tvá, nebo Bůh s tebou jest.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 8, 'Potom sstoupíš přede mnou do Galgala, a aj, já sstoupím k tobě, abych obětoval oběti zápalné, též abych obětoval oběti pokojné. Za sedm dní čekati budeš, až přijdu k tobě, a ukážiť, co bys měl činiti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 9, 'A bylo, když se obrátil, aby šel od Samuele, že Bůh proměnil srdce jeho v jiné, a zběhla se všecka ta znamení dne toho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 10, 'I přišli tam ku pahrbku, a aj, zástup proroků proti němu, i sstoupil na něj Duch Boží, a prorokoval u prostřed nich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 11, 'Stalo se tedy, že všickni, kdož ho znali prvé, viděli, an prorokuje s proroky. Pročež mluvil každý, jeden k druhému: Což se to stalo synu Cis? Zdali také Saul mezi proroky?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 12, 'I odpověděl jeden odtud a řekl: A kdo jest otec jejich? Protož přišlo to v přísloví: Zdali také Saul mezi proroky?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 13, 'A přestav prorokovati, přišel na horu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 14, 'Řekl pak strýc Saulův jemu a k služebníku jeho: Kam jste chodili? Odpověděl: Hledati oslic; když jsme pak poznali, že jich není, přišli jsme k Samuelovi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 15, 'I řekl strýc Saulův: Pověz mi medle, co vám řekl Samuel?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 16, 'Odpověděl Saul strýci svému: Oznámil nám místně, že by nalezeny byly oslice. Ale s strany království nic mu neoznámil, co mluvil Samuel.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 17, 'Svolal pak Samuel lid k Hospodinu do Masfa,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 18, 'A řekl synům Izraelským: Takto praví Hospodin Bůh Izraelský: Já jsem vyvedl Izraele z Egypta, a vysvobodil jsem vás z ruky Egyptských, nýbrž z ruky všech království ssužujících vás.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 19, 'Ale vy dnes zavrhli jste Boha svého, kterýž sám vyprošťuje vás ze všech zlých věcí vašich a z úzkostí vašich, a řekli jste jemu: Krále ustanov nad námi. Protož nyní postavtež se před Hospodinem po pokoleních svých a po tisících svých.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 20, 'A když Samuel kázal přistupovati všechněm pokolením Izraelským, přišlo na pokolení Beniamin.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 21, 'Potom kázal přistupovati pokolení Beniamin po čeledech jich, i přišlo na čeled Matri, a přišlo na Saule, syna Cis. I hledali ho, a není nalezen.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 22, 'Protož ptali se opět Hospodina: Přijde-li ještě sem ten muž? I odpověděl Hospodin: Aj, skryl se mezi nádobím.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 23, 'Tedy běželi a vzali ho odtud. I postavil se u prostřed lidu, a převyšoval všecken lid od ramene svého vzhůru.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 24, 'I řekl Samuel všemu lidu: Vidíte-li, koho vyvolil Hospodin, žeť mu není podobného ve všem lidu? Protož zkřikl všecken lid, a řekli: Živ buď král!');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 25, 'I oznamoval Samuel lidu o správě království, a vepsal to do knihy, kterouž položil před Hospodinem. Potom propustil Samuel všecken lid, jednoho každého do domu jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 26, 'Také i Saul odšel do domu svého do Gabaa; a odešla s ním vojska, jichžto srdcí Bůh se dotekl.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 27, 'Ale lidé nešlechetní řekli: Tento-liž nás vysvobodí? I pohrdali jím, ani mu pocty nepřinesli. On pak činil se neslyše.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 11, 1, 'Tedy přitáhl Náhas Ammonitský, a položil se proti Jábes v Gálad. I řekli všickni muži Jábes k Náhasovi: Učiň s námi smlouvu, a budemeť sloužiti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 11, 2, 'Jimž odpověděl Náhas Ammonitský: Na ten způsob učiním s vámi smlouvu, jestliže každému z vás vyloupím oko pravé, a uvedu to pohanění na všecken Izrael.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 11, 3, 'I řekli jemu starší Jábes: Propůjč nám sedm dní, ať rozešleme posly po všech končinách Izraelských, a nebude-li žádného, kdo by nás vysvobodil, tedy vyjdeme k tobě.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 11, 4, 'Když pak přišli ti poslové do Gabaa Saulova, a mluvili ta slova v uši lidu, pozdvihli všickni hlasu svého a plakali.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 11, 5, 'A aj, Saul šel za voly s pole. I řekl Saul: Co je lidu, že pláče? I vypravovali jemu slova mužů Jábes.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 11, 6, 'Tedy sstoupil Duch Boží na Saule, když uslyšel slova ta, a rozhněvala se prchlivost jeho náramně.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 11, 7, 'A vzav pár volů, rozsekal je na kusy, a rozeslal po všech krajinách Izraelských po týchž poslích, řka: Kdo by koli nešel za Saulem a za Samuelem, tak se stane s voly jeho. I připadl strach Hospodinův na lid, a vyšli jako muž jeden.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 11, 8, 'I sečtl je v Bezeku; a bylo synů Izraelských třikrát sto tisíc, a mužů Juda třidceti tisíců.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 11, 9, 'I řekli těm poslům, kteříž byli přišli: Takto povíte mužům Jábes v Galád: Zítra budete vysvobozeni, když slunce obejde. I přišli poslové, a oznámili mužům Jábes, kteřížto zradovali se.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 11, 10, 'Tedy řekli muži Jábes Ammonitským: Ráno vyjdeme k vám, abyste nám učinili, cožkoli se vám za dobré viděti bude.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 11, 11, 'Nazejtří pak rozdělil Saul lid na tři houfy; i vskočili do prostřed vojska v čas jitřního bdění, a bili Ammonitské, až slunce dobře vzešlo; kteříž pak byli pozůstali, rozprchli se, tak že nezůstalo z nich ani dvou pospolu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 11, 12, 'I řekl lid Samuelovi: Kdo jest ten, jenž pravil: Zdali Saul kralovati bude nad námi? Vydejte ty muže, ať je zbijeme.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 11, 13, 'Ale Saul řekl: Nebudeť dnes žádný zabit, poněvadž dnes učinil Hospodin vysvobození v Izraeli.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 11, 14, 'I řekl Samuel lidu: Přiďte, a poďme do Galgala, obnovíme tam království.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 11, 15, 'Šel tedy všecken lid do Galgala, a ustanovili tam Saule za krále před Hospodinem v Galgala, a obětovali také tam oběti pokojné před Hospodinem. I veselil se tam Saul a všickni muži Izraelští velmi velice.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 1, 'Mluvil pak Samuel ke všemu Izraelovi: Aj, uposlechl jsem hlasu vašeho ve všem, což jste mluvili ke mně, a ustanovil jsem nad vámi krále.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 2, 'A nyní aj, král jde před vámi, já pak zstaral jsem se a ošedivěl, a synové moji, aj, mezi vámi jsou. Já také chodil jsem před vámi od své mladosti až do dnešního dne.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 3, 'A však aj, teď jsem. Vydejte svědectví proti mně před Hospodinem a před pomazaným jeho, vzal-li jsem čího vola, aneb vzal-li jsem čího osla, utiskl-li jsem koho, ublížil-li jsem komu, aneb vzal-li jsem od koho úplatek, abych na něm přehlédl něco, a navrátím vám.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 4, 'Odpověděli: Neutiskl jsi nás, aniž jsi ublížil nám, aniž jsi co vzal z ruky kterého člověka.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 5, 'Řekl ještě jim: Svědek jest Hospodin proti vám, svědek jest i pomazaný jeho v tento den, že jste nenalezli při mně ničehož. I řekl lid: Svědek jest.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 6, 'Tedy řekl Samuel lidu: Hospodin jest svědek, kterýž učinil Mojžíše a Arona, a kterýž vyvedl otce vaše z země Egyptské.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 7, 'Protož nyní postavte se, ať s vámi v soud vejdu před Hospodinem o všecky spravedlivé skutky Hospodinovy, kteréž učinil s vámi i s otci vašimi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 8, 'Když byl všel Jákob do Egypta, volali otcové vaši k Hospodinu; i poslal Hospodin Mojžíše a Arona, kteříž vyvedli otce vaše z Egypta, a osadili je na tomto místě.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 9, 'A když se zapomenuli na Hospodina Boha svého, vydal je v ruku Zizary, knížete vojska Azor, a v ruku Filistinských, též v ruku krále Moábského, kteříž bojovali proti nim.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 10, 'Ale když volali k Hospodinu a řekli: Zhřešili jsme, nebo jsme opustili Hospodina, a sloužili jsme Bálim a Astarot, protož nyní vysvoboď nás z ruky nepřátel našich, a sloužiti budeme tobě:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 11, 'I poslal Hospodin Jerobále a Bedana a Jefte a Samuele, a vytrhl vás z ruky nepřátel vašich okolních, a bydlili jste bezpečně.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 12, 'Potom vidouce, že Náhas král synů Ammon přitáhl proti vám, řekli jste mi: Nikoli, ale král bude kralovati nad námi; ješto Hospodin Bůh váš jest králem vaším.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 13, 'Nyní tedy, aj, král, kteréhož jste zvolili, za něhož jste žádali, a aj, Hospodin ustanovil ho nad vámi králem.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 14, 'Budete-li se báti Hospodina, a jemu sloužiti a poslouchati hlasu jeho, a nebudete-li se zpěčovati řeči Hospodinově, tak i vy i král, kterýž kraluje nad vámi, ostojíte, jdouce za Hospodinem Bohem vaším.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 15, 'Pakli nebudete poslouchati hlasu Hospodinova, ale odporni budete řeči jeho, bude ruka Hospodinova proti vám, jako i proti otcům vašim.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 16, 'Ještě se teď pozastavte, a vizte věc tuto velikou, kterouž učiní Hospodin před očima vašima.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 17, 'Zdaliž není dnes žeň pšeničná? Volati budu k Hospodinu, i vydá hřímání a déšť, tak že poznati a viděti musíte, jak jest to velmi zlá věc, kteréž jste se dopustili před očima Hospodinovýma, žádavše sobě krále.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 18, 'Protož volal Samuel k Hospodinu, a vydal Hospodin hřímání a déšť v ten den. I bál se všecken lid Hospodina velmi i Samuele.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 19, 'A řekl všecken lid Samuelovi: Modl se za služebníky své Hospodinu Bohu svému, abychom nezemřeli; nebo jsme přidali ke všem hříchům našim i toto zlé, že jsme sobě žádali krále.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 20, 'I řekl Samuel lidu: Nebojte se. Učiniliť jste sic všecko to zlé, však proto neodstupujte zpět od Hospodina, ale služte Hospodinu celým srdcem svým.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 21, 'Neodstupujte, pravím, následujíce marnosti, totiž cizích bohů, kteříž nic neprospívají, aniž vysvobozují, nebo jsou marnost.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 22, 'Neopustíť zajisté Hospodin lidu svého pro jméno své veliké; nebo zalíbilo se Hospodinu, aby vás sobě vzdělal v lid.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 23, 'Ode mne také odstup to, abych měl hřešiti proti Hospodinu, a přestávati modliti se za vás, nýbrž navoditi vás budu na cestu dobrou a přímou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 24, 'A však bojte se Hospodina a služte jemu v pravdě celým srdcem svým; nebo vidíte, jak veliké věci učinil s vámi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 25, 'Jestliže pak předce zle činiti budete, i vy i král váš zahynete.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 1, 'Saul tedy prvního léta kralování svého, (kraloval pak dvě létě nad Izraelem,)');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 2, 'Vybral sobě tři tisíce z Izraele. I bylo jich s Saulem dva tisíce v Michmas a na hoře Bethel, a tisíc bylo s Jonatou v Gabaa Beniaminově; ostatek pak lidu rozpustil jednoho každého do příbytku jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 3, 'I pobil Jonata stráž Filistinských, kterouž měli na pahrbku, a uslyšeli to Filistinští. Tedy Saul troubil v troubu po vší zemi, řka: Ať to slyší Hebrejští.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 4, 'A tak slyšel všecken Izrael, že bylo praveno: Pobil Saul stráž Filistinských, pročež také zoškliven byl Izrael mezi Filistinskými. I svolán jest lid za Saulem do Galgala.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 5, 'Filistinští pak sebrali se k boji proti Izraelovi, třidceti tisíc vozů, a šest tisíc jezdců, a lidu ve množství, jako jest písku na břehu mořském. I vytáhli a položili se v Michmas na východ Betaven.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 6, 'A protož muži Izraelští vidouce, že jim úzko, (nebo byl ssoužen lid,) skryl se lid v jeskyních a v ohradách, a v skalách a v horách, i v jamách.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 7, 'Hebrejští také přepravili se přes Jordán do země Gád a Galád. Saul pak ještě byl v Galgala, a všecken lid zastrašil se, jda za ním.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 8, 'I očekával tu za sedm dní vedlé času uloženého od Samuele; a když nepřicházel Samuel do Galgala, rozešel se lid od něho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 9, 'Tedy řekl Saul: Přineste ke mně obět zápalnou a oběti pokojné. I obětoval oběti zápalné.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 10, 'Když pak již dokonal obětování oběti zápalné, aj, Samuel přicházel, a Saul vyšel proti němu, aby ho přivítal.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 11, 'I řekl Samuel: Co jsi učinil? Odpověděl Saul: Když jsem viděl, že se lid rozchází ode mne, a ty nepřicházíš k uloženému dni, a Filistinští byli shromážděni v Michmas:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 12, 'I řekl jsem: Nyní připadnou Filistinští na mne v Galgala, a tváři Hospodinově nemodlil jsem se. Takž jsem se opovážil a obětoval jsem oběti zápalné.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 13, 'Tedy řekl Samuel Saulovi: Bláznivě jsi učinil, nezachovals přikázaní Hospodina Boha svého, kteréž přikázal tobě; nebo nyní byl by utvrdil Hospodin království tvé nad Izraelem až na věky.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 14, 'Ale již nyní království tvé neostojí. Vyhledalť jest Hospodin sobě muže vedlé srdce svého, jemuž rozkázal Hospodin, aby byl vůdce nad lidem jeho; nebo jsi nezachoval, cožť přikázal Hospodin.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 15, 'Vstav pak Samuel, vstoupil z Galgala do Gabaa Beniaminova. A Saul načetl lidu, kterýž zůstával při něm, okolo šesti set mužů.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 16, 'Saul tedy a Jonata syn jeho, i lid, kterýž zůstával s nimi, byli v Gabaa Beniaminově, Filistinští pak leželi v Michmas.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 17, 'I vyšli zhoubcové z vojska Filistinského na tré rozdělení. Houf jeden obrátil se k cestě Ofra, k zemi Sual;');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 18, 'A houf druhý obrátil se na cestu Betoron; houf pak třetí pustil se cestou krajiny, kteráž patří k údolí Seboim na poušť.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 19, 'Kováře pak žádného nenalézalo se ve vší zemi Izraelské; nebo byli řekli Filistinští: Aby sobě Hebrejští nenadělali mečů a kopí.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 20, 'Protož chodívali všickni Izraelští k Filistinským, aby ostřil sobě jeden každý radlici svou, a motyku svou, sekeru svou i vidly své,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 21, 'Sic jinak byly štěrbiny na radlicích, motykách, vidlách třírohých a sekerách; také i o zaostření ostnu bývalo těžko.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 22, 'I bylo, že v čas boje nenalézalo se meče ani kopí u žádného z lidu toho, kterýž byl s Saulem a s Jonatou, toliko u Saule a u Jonaty syna jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 23, 'Vyšla pak stráž Filistinských k cestám Michmas.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 1, 'Stalo se pak jednoho dne, že řekl Jonata syn Saulův služebníku, kterýž nosil zbroj jeho: Poď, půjdeme k stráži Filistinských, kteráž jest na oné straně. Ale otci svému toho nepověděl.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 2, 'Saul však zůstával na kraji pahrbku pod jabloní zrnatou, kteráž byla v Migron; a lidu, kterýž byl s ním, bylo okolo šesti set mužů,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 3, 'Tolikéž Achiáš syn Achitobův, bratra Ichabodova, syna Fínesova, syna Elí, kněze Hospodinova v Sílo, kterýž nosil efod. Ale lid nevěděl, že by odšel Jonata.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 4, 'Mezi těmi pak průchody, jimiž pokoušel se Jonata přejíti k stráži Filistinských, byla skála příkrá k přecházení s této strany, též skála příkrá k přecházení s oné strany; jméno jedné Bóses, a jméno druhé Seneh.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 5, 'Jedna skála byla na půlnoci proti Michmas, a druhá na poledne proti Gabaa.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 6, 'I řekl Jonata služebníku, kterýž nosil zbroj jeho: Poď, přejděme k stráži těch neobřezaných, snad bude Hospodin s námi; neboť není nesnadné Hospodinu zachovati ve mnoze aneb v mále.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 7, 'Odpověděl oděnec jeho: Učiň, cožkoli jest v srdci tvém, obrať se, kam chceš; aj, budu s tebou podlé vůle tvé.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 8, 'I řekl Jonata: Aj, my jdeme k mužům těm, a ukážeme se jim.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 9, 'Jestliže řeknou nám takto: Počkejte, až přijdeme k vám, stůjme na místě svém, a nechoďme k nim.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 10, 'Pakli by řekli takto: Vstupte k nám, jděme, nebo vydal je Hospodin v ruku naši. To zajisté nám bude za znamení.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 11, 'Ukázali se tedy oba dva stráži Filistinských. I řekli Filistinští: Hle, Hebrejští lezou z děr, v nichž se byli skryli.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 12, 'I mluvili někteří z stráže té k Jonatovi a k oděnci jeho, a řekli: Vstupte k nám, a povíme vám něco. Pročež řekl Jonata k oděnci svému: Podiž za mnou, nebo je vydal Hospodin v ruku Izraele.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 13, 'A tak lezl čtvermo Jonata a oděnec jeho za ním. I padali před Jonatou, a oděnec jeho mordoval je, jda za ním.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 14, 'A to byla porážka první, v níž zbil Jonata a oděnec jeho okolo dvadcíti mužů, jako v půl honech rolí dvěma volům s zápřež.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 15, 'Protož byl strach v tom ležení a na tom poli, i na všem tom lidu; strážní i oni loupežníci děsili se též, až se země třásla, nebo byla v strachu Božím.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 16, 'A vidouce strážní Saulovi v Gabaa Beniaminově, oznámili, jak množství to narůzno prchá, a vždy více se potírá.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 17, 'Saul pak řekl lidu, kterýž s ním byl: Vyhledejte i hned a zvězte, kdo jest z našich odšel. A když vyhledávali, hle, Jonaty nebylo a oděnce jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 18, 'I řekl Saul Achiášovi: Postav sem truhlu Boží. (Truhla pak Boží toho času byla s syny Izraelskými.)');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 19, 'I stalo se, když ještě mluvil Saul k knězi, že hřmot, kterýž byl v vojště Filistinských, více se rozcházel a rozmáhal. Protož řekl Saul knězi: Spusť ruku svou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 20, 'Shromáždili se tedy Saul i všecken lid, kterýž s ním byl, a přišli až k té bitvě; a aj, byl meč jednoho proti druhému s hřmotem velmi velikým.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 21, 'Hebrejští pak někteří byli s Filistinskými prvé, kteříž táhli s nimi polem sem i tam; i ti také obrátili se a stáli při lidu Izraelském, kterýž byl s Saulem a s Jonatou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 22, 'Všickni také muži Izraelští, kteříž se skryli na hoře Efraim, když uslyšeli, že by utíkali Filistinští, honili je i oni v té bitvě.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 23, 'I vysvobodil Hospodin toho dne Izraele. Boj pak protáhl se až do Betaven.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 24, 'A ačkoli muži Izraelští utrápili se toho dne, však Saul zavázal lid s přísahou, řka: Zlořečený muž, kterýž by jedl chléb prvé, než bude večer, a než se pomstím nad nepřátely svými. A tak neokusil všecken lid chleba.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 25, 'Všecken pak lid té krajiny šli do lesa, kdež bylo hojnost medu po zemi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 26, 'A když všel lid do lesa, viděl tekoucí med; žádný však nepřičinil k ústům svým ruky své, nebo se bál lid té přísahy.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 27, 'Ale Jonata neslyšev, že otec jeho zavazoval lid přísahou, vztáhl hůl, kterouž měl v ruce své, a omočil konec její v plástu medu, a obrátil ruku svou k ústům svým; i osvítily se oči jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 28, 'Odpovídaje pak jeden z lidu, řekl: Velikou přísahou zavázal otec tvůj lid, řka: Zlořečený muž, kterýž by jedl chléb dnes, ačkoli zemdlel lid.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 29, 'Tedy řekl Jonata: Zkormoutil otec můj lid země. Pohleďte, prosím, jak se osvítily oči mé, hned jakž jsem okusil maličko medu toho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 30, 'Čím více kdyby se byl směle najedl dnes lid z loupeží nepřátel svých, kterýchž dosáhl? Nebyla-liž by se nyní stala větší porážka Filistinských?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 31, 'A tak bili toho dne Filistinské od Michmas až do Aialon; i ustal lid náramně.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 32, 'Protož obrátil se lid k loupeži, a nabravše ovcí a volů i telat, zbili je na zemi; i jedl lid se krví.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 33, 'I pověděli Saulovi, řkouce: Aj, lid hřeší proti Hospodinu, jeda se krví. Kterýž řekl: Přestoupili jste přikázaní. Přivaltež i hned ke mně kámen veliký.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 34, 'Opět řekl Saul: Rozejděte se mezi lid a rcete jim: Přiveďte ke mně jeden každý vola svého a jeden každý dobytče své, a bíte tuto a jezte, i nebudete hřešiti proti Hospodinu, jedouce se krví. Přivedli tedy všecken lid jeden každý vola svého rukou svou té noci a zabíjeli tu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 35, 'Vzdělal také Saul oltář Hospodinu; to nejprvnější oltář udělal Hospodinu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 36, 'Potom řekl Saul: Pusťme se po Filistinských v noci, a budeme je loupiti až do jitra, aniž zůstavujme z nich koho. Kteříž řekli: Cožť se koli vidí za dobré, učiň. Ale kněz řekl: Přistupme sem k Bohu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 37, 'I tázal se Saul Boha: Pustím-li se za Filistinskými? Dáš-li je v ruku Izraelovu? I neodpověděl mu v ten den.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 38, 'Protož řekl Saul: Přistupujte sem všecka knížata lidu, a vyzvězte a vyhledejte, kdo se jest dopustil dnes hříchu nějakého?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 39, 'Nebo živť jest Hospodin, kterýž vysvobozuje Izraele, že byť pak i na Jonatovi synu mém to bylo, smrtí umře. I neodpověděl jemu žádný ze všeho lidu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 40, 'Řekl také všemu Izraelovi: Buďte vy na jedné straně, já pak a Jonata syn můj budeme na druhé straně. Odpověděl lid Saulovi: Učiň, cožť se za dobré vidí.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 41, 'Protož řekl Saul Hospodinu Bohu Izraelskému: Ukaž spravedlivě. I přišlo na Jonatu a Saule, lid pak z toho vyšel.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 42, 'I řekl Saul: Vrzte los mezi mnou a mezi Jonatou synem mým. A postižen jest Jonata.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 43, 'Řekl tedy Saul Jonatovi: Pověz mi, co jsi učinil? I pověděl mu Jonata a řekl: Toliko jsem okusil maličko medu koncem holi, kterouž jsem měl v ruce své, a aj, proto-liž mám umříti?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 44, 'Odpověděl Saul: Toto učiň mi Bůh a toto přidej, že smrtí umřeš, Jonato.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 45, 'I řekl lid Saulovi: Což tedy umříti má Jonata, kterýž učinil vysvobození toto veliké v Izraeli? Odstup to, živť jest Hospodin, že nespadne vlas s hlavy jeho na zemi, poněvadž s pomocí Boží učinil to dnes. I vyprostil lid Jonatu, tak aby nebyl usmrcen.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 46, 'Tedy odtáhl Saul od Filistinských; Filistinští také navrátili se k místu svému.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 47, 'Saul pak uvázav se v království nad Izraelem, bojoval vůkol se všemi nepřátely svými, s Moábskými a s syny Ammon, a s Edomem, i s králi Soba, a s Filistinskými; a kamž se koli obracel, ukrutnost provodil.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 48, 'Sebrav také vojska, porazil Amalecha, a vysvobodil Izraele z ruky zhoubců jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 49, 'Byli pak synové Saulovi: Jonata a Jesui a Melchisua; a jména dvou dcer jeho, jméno prvorozené Merob, jméno pak mladší Míkol.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 50, 'A jméno manželky Saulovy Achinoam, dcera Achimaasova; jméno pak hejtmana vojska jeho Abner, syn Ner, strýce Saulova.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 51, 'Nebo Cis byl otec Saulův, a Ner otec Abnerův, syn Abielův.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 52, 'Byla pak válka veliká s Filistinskými po všecky dny Saulovy, protož kohožkoli Saul viděl muže silného, a kohokoli udatného, bral ho k sobě.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 1, 'Řekl pak Samuel Saulovi: Hospodin poslal mne, abych tě pomazal za krále nad lidem jeho, nad Izraelem, pozorujž tedy nyní hlasu slov Hospodinových.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 2, 'Takto praví Hospodin zástupů: Rozpomenul jsem se na to, co jest činil Amalech Izraelovi, že se položil proti němu na cestě, když se bral z Egypta.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 3, 'Protož i hned táhni a zkaz Amalecha, a zahlaďte jako proklaté všecko, což má. Neslitovávejž se nad ním, ale zahub od muže až do ženy, od malého až do toho, kterýž prsí požívá, od vola také až do ovce, a od velblouda až do osla.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 4, 'Sebral tedy Saul lid, a sečtl je v Telaim, dvakrát sto tisíc pěších, a deset tisíc mužů Judských.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 5, 'A přitáhl Saul až k městu Amalechovu, aby bojoval v údolí jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 6, 'I řekl Saul Cinejským: Jděte, oddělte se, vyjděte z prostředku Amalechitských, abych vás s nimi nezahladil; nebo vy jste učinili milosrdenství se všemi syny Izraelskými, když šli z Egypta. A tak odšel Cinejský z prostředku Amalecha.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 7, 'I porazil Saul Amalecha od Hevilah, kudy se chodí do Sur, kteréž jest naproti Egyptu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 8, 'Jal také Agaga krále Amalechitského živého, lid pak všecken vyhladil ostrostí meče.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 9, 'I zachoval Saul a lid jeho Agaga, a nejlepší bravy a skoty a krmný dobytek, a berany i všecko, což lepšího bylo, a nechtěli vyhubiti jich; což pak bylo ničemného a churavého, to zahubili.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 10, 'A protož stalo se slovo Hospodinovo k Samuelovi, řkoucí:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 11, 'Žel mi, že jsem Saule ustanovil za krále, nebo odvrátil se ode mne, a slov mých nevyplnil. I rozhorlil se Samuel náramně a volal k Hospodinu celou noc.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 12, 'Vstav pak Samuel, šel vstříc Saulovi ráno. I oznámili Samuelovi, řkouce: Saul přišel na Karmel, a aj, připravil sobě místo, a odtud hnuv se, táhl a sstoupil do Galgala.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 13, 'A když přišel Samuel k Saulovi, řekl jemu Saul: Požehnaný ty od Hospodina, vyplnil jsem slovo Hospodinovo.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 14, 'Samuel pak řekl: Jaké pak jest to bečení ovcí těch v uších mých, a řvání volů, kteréž já slyším?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 15, 'Odpověděl Saul: Od Amalechitských přihnali je; nebo zachoval lid, což nejlepšího bylo z bravů a skotů, aby to obětoval Hospodinu Bohu tvému, ostatek pak jsme zahladili jako proklaté.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 16, 'I řekl Samuel Saulovi: Dopusť, ať oznámím tobě, co jest mi mluvil Hospodin noci této. Dí jemu: Oznam.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 17, 'Tedy řekl Samuel: Zdali jsi nebyl maličký sám u sebe? A předce učiněn jsi hlavou pokolení Izraelských, a pomazal tě Hospodin za krále nad Izraelem.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 18, 'A poslal tě Hospodin na cestu a řekl tobě: Jdi, zahub jako proklaté hříšníky ty Amalechitské, a bojuj proti nim, dokudž byste nevyhladili jich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 19, 'Pročež jsi tedy neuposlechl hlasu Hospodinova, ale obrátil jsi se k loupeži, a učinils zlou věc před očima Hospodinovýma?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 20, 'Odpověděl Saul Samuelovi: Však jsem uposlechl hlasu Hospodinova, a šel jsem cestou, kterouž poslal mne Hospodin, a přivedl jsem Agaga krále Amalechitského, i Amalechitské jako proklaté vyhubil jsem.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 21, 'Ale lid vzal z loupeží bravy a skoty přední z věcí proklatých, k obětování Hospodinu Bohu tvému v Galgala.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 22, 'I řekl Samuel: Zdaliž líbost takovou má Hospodin v zápalích a v obětech, jako když se poslušenství koná hlasu Hospodinova? Aj, poslouchati lépe jest, nežli obětovati, a ku poslušenství státi, nežli tuk skopců přinášeti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 23, 'Nebo zpoura jest takový hřích jako čarodějnictví, a přestoupiti přikázaní jako modlářství a obrazové. Poněvadž jsi pak zavrhl řeč Hospodinovu, i on také zavrhl tě, abys nebyl králem.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 24, 'Tedy řekl Saul Samuelovi: Zhřešil jsem, že jsem přestoupil rozkaz Hospodinův a slova tvá, nebo jsem se bál lidu, a povolil jsem hlasu jejich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 25, 'Protož nyní odpusť, prosím, hřích můj, a navrať se se mnou, ať se pomodlím Hospodinu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 26, 'I řekl Samuel Saulovi: Nenavrátím se s tebou; nebo jsi zavrhl řeč Hospodinovu, tebe také zavrhl Hospodin, abys nebyl králem nad Izraelem.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 27, 'A když se obrátil Samuel, aby odšel, Saul uchytil křídlo pláště jeho, i odtrhlo se.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 28, 'Tedy řekl jemu Samuel: Odtrhlť jest Hospodin království Izraelské dnes od tebe, a dal je bližnímu tvému, lepšímu, než jsi ty.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 29, 'Však proto vítěz Izraelský klamati nebude, ani želeti; nebo není člověkem, aby měl čeho želeti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 30, 'On pak řekl: Zhřešilť jsem, ale vždy mne cti, prosím, před staršími lidu mého a před Izraelem, a navrať se se mnou, abych se pomodlil Hospodinu Bohu tvému.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 31, 'I navrátiv se Samuel, šel za Saulem, a pomodlil se Saul Hospodinu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 32, 'Řekl pak Samuel: Přiveďte ke mně Agaga, krále Amalechitského. I šel k němu Agag nádherně; nebo řekl Agag: Jistě odešla hořkost smrti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 33, 'Ale Samuel řekl: Jakož uvedl sirobu na ženy meč tvůj, takť osiří matka tvá nad jiné ženy. I rozsekal Samuel Agaga na kusy před Hospodinem v Galgala.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 34, 'Potom odšel Samuel do Ráma, Saul pak vstoupil do domu svého, do Gabaa Saulova.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 35, 'A již potom více Samuel neviděl Saule až do dne smrti své; však plakal Samuel Saule. Hospodin pak želel toho, že učinil Saule králem nad Izraelem.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 1, 'Řekl pak Hospodin Samuelovi: I dokudž ty budeš plakati Saule, poněvadž jsem já ho zavrhl, aby nekraloval nad Izraelem? Naplň roh svůj olejem a poď, pošli tě k Izai Betlémskému; nebo jsem vybral sobě z synů jeho krále.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 2, 'I řekl jemu Samuel: Kterak mám jíti? Nebo Saul uslyše, zabije mne. Odpověděl Hospodin: Jalovici z stáda vezmeš s sebou, a díš: Přišel jsem, abych obětoval Hospodinu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 3, 'A pozveš Izai k oběti, jáť pak ukáži, co bys měl činiti; i pomažeš mi toho, o kterémž já tobě povím.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 4, 'A tak učinil Samuel, jakž mu byl mluvil Hospodin, a přišel do Betléma. A ulekše se starší města, vyšli proti němu a řekli: Pokojný-li jest příchod tvůj?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 5, 'Odpověděl: Pokojný. Abych obětoval Hospodinu, přišel jsem. Posvěťte se, a poďte k oběti se mnou. Posvětil také Izai a synů jeho, a pozval jich k oběti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 6, 'Když pak přišli, vida Eliába, řekl: Jistě před Hospodinem jest pomazaný jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 7, 'Ale Hospodin řekl Samuelovi: Nehleď na tvárnost jeho a na zrůst postavy jeho, nebo jsem ho zavrhl; neboť ne patřím, nač patří člověk. Člověk zajisté hledí na to, což jest před očima, ale Hospodin hledí k srdci.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 8, 'I povolal Izai Abinadaba, a kázal mu jíti před Samuele. Kterýž řekl: Také ani toho nevyvolil Hospodin.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 9, 'Rozkázal též Izai jíti Sammovi. I řekl: Ani toho nevyvolil Hospodin.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 10, 'Takž rozkázal Izai jíti sedmi synům svým před Samuele. Ale Samuel řekl Izai: Ani těch nevyvolil Hospodin.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 11, 'Potom řekl Samuel Izai: Jsou-li to již všickni synové? Odpověděl: Ještěť zůstává nejmladší, a aj, pase ovce. Tedy řekl Samuel Izai: Pošli a vezmi jej; nebo aniž sedneme za stůl, dokudž on sem nepřijde.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 12, 'I poslal a přivedl ho. (Byl pak on ryšavý, krásných očí a libého vzezření.) I řekl Hospodin: Vstana, pomaž ho, nebo to jest ten.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 13, 'Protož vzal Samuel roh s olejem, a pomazal ho u prostřed bratří jeho. I odpočinul Duch Hospodinův na Davidovi od toho dne i potom. A Samuel vstav, odšel do Ráma.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 14, 'Takž Duch Hospodinův odšel od Saule, a nepokojil ho duch zlý od Hospodina.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 15, 'Služebníci pak Saulovi řekli jemu: Aj, teď duch Boží zlý nepokojí tě.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 16, 'Nechť, medle, rozkáže pán náš služebníkům svým, kteříž stojí před tebou, ať hledají muže, kterýž by uměl hráti na harfu, aby, když by přišel na tě duch Boží zlý, hral rukou svou, a tobě aby lehčeji bylo.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 17, 'Tedy řekl Saul služebníkům svým: Medle, vyhledejte mi muže, kterýž by uměl dobře hráti, a přiveďte ke mně.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 18, 'I odpověděl jeden z služebníků a řekl: Aj, viděl jsem syna Izai Betlémského, kterýž umí hráti, muže udatného a bojovného, též správného a krásného, a jest s ním Hospodin.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 19, 'Protož poslal Saul posly k Izai, řka: Pošli mi Davida syna svého, kterýž jest při stádu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 20, 'Tedy Izai vzal osla, chléb a nádobu vína a kozelce jednoho, a poslal po Davidovi synu svém Saulovi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 21, 'Když pak přišel David k Saulovi, stál před ním; i zamiloval ho velmi, a učiněn jest jeho oděncem.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 22, 'Potom poslal opět Saul k Izai, řka: Medle, nechť David stojí přede mnou, neboť jest našel milost před očima mýma.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 23, 'I bývalo, že kdyžkoli napadal duch Boží Saule, David, bera harfu, hrával rukou svou; i míval Saul polehčení, a lépe mu bývalo, nebo ten duch zlý odstupoval od něho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 1, 'I sebrali Filistinští vojska svá k boji, a shromáždili se u Socho, kteréž jest Judovo, a položili se mezi Socho a Azeka na pomezí Dammim.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 2, 'Ale Saul a muži Izraelští sebravše se, položili se v údolí Elah, a sšikovali se k bitvě proti Filistinským.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 3, 'I stáli Filistinští na hoře s strany jedné, a Izraelští stáli na hoře s strany druhé, a údolí bylo mezi nimi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 4, 'I vyšel muž bojovník z vojska Filistinského, Goliáš jménem, z Gát, zvýší šesti loket a dlani.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 5, 'Lebka pak ocelivá na hlavě jeho, a v pancíř brněný byl oblečen, kterýžto pancíř vážil pět tisíc lotů oceli.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 6, 'Též plechovice ocelivé byly na nohách jeho, a pavéza ocelivá mezi rameny jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 7, 'A dřevo u kopí jeho jako vratidlo tkadlcovské, železo pak ostré kopí jeho vážilo šest set lotů železa; a ten, kterýž nosil braň jeho, šel před ním.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 8, 'I postavil se, a volal na vojska Izraelská, řka k nim: Nač jste to vyšli, vojensky se sšikovavše? Zdaliž já nejsem Filistinský, a vy služebníci Saulovi? Vybeřte z sebe muže, kterýž by sstoupil ke mně.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 9, 'Jestližeť mi bude moci odolati a zabije mne, tedy budeme služebníci vaši; pakliť já přemohu jej a zabiji ho, budete vy služebníci naši, a sloužiti budete nám.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 10, 'Pravil také ten Filistinský: Já jsem dnes zhaněl vojska Izraelská. Vydejtež mi muže, abychom se bili spolu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 11, 'A když uslyšel Saul i všecken Izrael slova Filistinského taková, ulekli se a báli se velmi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 12, 'David pak ten syn muže Efratejského z Betléma Judova, (jehož jméno Izai, kterýž měl osm synů, a již se byl sstaral za dnů Saule, přiblíživ se k lidem sešlým.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 13, 'Tři také synové Izai starší šedše, táhli na vojnu s Saulem. Jména těch tří synů jeho, kteříž byli šli k boji: Eliáb prvorozený, a druhý po něm Abinadab, třetí pak Samma.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 14, 'Ale David byl nejmladší. A tak ti tři synové starší odešli s Saulem.)');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 15, 'David tedy odšel od Saule a navrátil se, aby pásl stádo otce svého v Betlémě.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 16, 'I přicházel ten Filistinský ráno a večer, a stavěl se po čtyřidceti dní.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 17, 'Tedy řekl Izai Davidovi synu svému: Vezmi i hned pro bratří své efi pražmy této a deset chlebů těchto, a běž do vojska k bratřím svým.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 18, 'A deset syřečků mladých těchto doneseš hejtmanu, a navštívě bratří své, pozdravíš jich, a základ jejich vyzdvihneš.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 19, 'Saul pak i oni, i všickni muži Izraelští byli v údolí Elah, bojujíce proti Filistinským.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 20, 'A tak vstav David tím raněji a zanechav stáda při strážném, vzal to a šel, jakž mu byl přikázal Izai. I přišel až k šancům, a aj, vojsko vycházelo do šiku a křičelo k bitvě.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 21, 'I sšikovali se Izraelští, ano i Filistinští, vojsko proti vojsku.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 22, 'Protož David zanechav břemene, kteréž s sebe složil u strážného při břemeních, běžel do vojska; a když přišel, tázal se bratří svých, jak se mají.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 23, 'A když on s nimi mluvil, aj, muž bojovník jménem Goliáš, Filistinský z Gát, vycházel z vojska Filistinských a mluvil jako i prvé; což slyšel i David.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 24, 'Všickni pak muži Izraelští, jakž uzřeli toho muže, utíkali před tváří jeho, a báli se náramně.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 25, 'I mluvili Izraelští mezi sebou: Viděli-li jste toho muže, kterýž vyšel? Nebo aby pohanění uvedl na Izraele, vyšel. Kdož by ho zabil, zbohatí ho král bohatstvím velikým, a dceru svou dá jemu, i dům otce jeho osvobodí v Izraeli.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 26, 'I mluvil David mužům, kteříž stáli u něho, a řekl: Co bude dáno muži tomu, kterýž by zabil toho Filistinského a odjal pohanění od Izraele? Nebo kdo jest Filistinský neobřezaný ten, že pohanění uvodí na vojsko Boha živého?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 27, 'Odpověděl jemu lid v táž slova, řka: To bude dáno muži, kterýž by ho zabil.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 28, 'A uslyšev Eliáb, bratr jeho nejstarší, že mluví s těmi muži, rozhněval se Eliáb velmi na Davida, a řekl: Proč jsi sem přišel? A komus nechal kolikasi těch ovec na poušti? Známť já pýchu tvou a zlost srdce tvého, žes přišel dívati se bitvě.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 29, 'I řekl David: Což jsem pak učinil? Zdaž mi nebylo poručeno?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 30, 'Tedy šel od něho k jinému, jehož se tázal jako i prvé. I odpověděl jemu lid tak jako i prvé.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 31, 'A tak roznesla se slova, kteráž mluvil David, a oznámili je Saulovi. Kterýžto povolal ho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 32, 'I řekl David Saulovi: Nechť se neleká srdce člověka pro něho; služebník tvůj půjde a bude se bíti s Filistinským tímto.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 33, 'Ale Saul řekl Davidovi: Nebudeš moci jíti proti Filistinskému tomu, abys se potýkal s ním; nebo mládenček jsi, on pak jest muž bojovný od mladosti své.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 34, 'Odpověděl David Saulovi: Služebník tvůj pastýřem byl stáda otce svého, a když přicházel lev aneb nedvěd, a bral dobytče z stáda,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 35, 'Já dostihal jsem ho a bil jsem jej, a vydíral jsem je z hrdla jeho. Pakli se na mne obořil, tedy ujma ho za čelist, bil jsem jej, až jsem ho i zabil.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 36, 'I lva i nedvěda zabil služebník tvůj; budeť tedy Filistinský neobřezanec ten jako který z nich, nebo zhaněl vojska Boha živého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 37, 'Řekl také David: Hospodin, kterýž vytrhl mne z moci lva a z moci nedvěda, onť mne vytrhne z ruky Filistinského tohoto. Tedy řekl Saul Davidovi: Jdi, a Hospodin budiž s tebou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 38, 'I dal Saul obléci Davida v šaty své, a vstavil lebku ocelivou na hlavu jeho, a oblékl ho v pancíř.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 39, 'Připásal také David meč jeho na ty šaty jeho, a chtěl jíti, ale že tomu nezvykl, protož řekl David Saulovi: Nemohuť v tom jíti, nebo jsem nepřivykl. I složil to David s sebe.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 40, 'A vzav hůl svou do ruky své, vybral sobě pět kamenů hladkých z potoku, a vložil je do mošničky pastýřské, kterouž měl, totiž do pytlíku, a prak svůj v ruce nesl, a přiblížil se k Filistinskému.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 41, 'Bral se také i Filistinský, jda a přibližuje se k Davidovi, a muž ten, kterýž nesl braň jeho, šel před ním.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 42, 'A když pohleděl Filistinský a uzřel Davida, pohrdal jím, proto že byl mládenček, a ryšavý, a krásného vzezření.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 43, 'I řekl Filistinský Davidovi: Což jsem pes, že jdeš proti mně s holí? A zlořečil Filistinský Davidovi skrze bohy své.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 44, 'Řekl také Filistinský Davidovi: Poď ke mně, a dámť tělo tvé ptákům nebeským a šelmám zemským.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 45, 'Odpověděl David Filistinskému: Ty jdeš ke mně s mečem a s kopím a s pavézou, ale já k tobě jdu ve jménu Hospodina zástupů, Boha vojsk Izraelských, kterémuž jsi ty utrhal.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 46, 'Dnešního dne zavře tě Hospodin v ruku mou, a zabiji tě, a setnu hlavu tvou s tebe, a vydám těla vojska Filistinského dnes ptákům nebeským a šelmám zemským, a pozná všecka země, žeť jest Bůh v Izraeli.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 47, 'A zvíť všecko shromáždění toto, že ne mečem ani kopím vysvobozuje Hospodin; (nebo Hospodinův jest boj,) protož vydáť vás v ruce naše.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 48, 'Stalo se pak, že když vstal ten Filistinský, a šel, přibližuje se proti Davidovi, pospíšil i David a běžel proti Filistinskému, aby se s ním potýkal.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 49, 'V tom David vztáh ruku svou k mošničce, vyňal z ní kámen, kterýmž hodil z praku, a udeřil Filistinského v čelo jeho tak, že kámen uvázl v čele jeho. I padl tváří svou na zem.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 50, 'A tak přemohl David Filistinského prakem a kamenem, a udeřiv Filistinského, zabil jej, ačkoli David žádného meče v ruce neměl.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 51, 'A přiběh David, stál nad Filistinským. Potom pochytiv meč jeho, dobyl ho z pošvy a zabil jej, a sťal jím hlavu jeho. To vidouce Filistinští, že umřel nejsilnější jejich, utíkali.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 52, 'A protož vstavše muži Izraelští a Judští, zkřikli a honili Filistinské, až kde se vchází do údolí, a až k branám Akaron. I padali, raněni jsouce, Filistinští po cestě k Saraim, až do Gát a až do Akaron.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 53, 'A navrátivše se synové Izraelští od honění Filistinských, vzebrali tábor jejich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 54, 'Potom David vzav hlavu toho Filistinského, přinesl ji do Jeruzaléma, a odění jeho složil v stanu svém.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 55, 'Tehdáž pak, když viděl Saul Davida jdoucího proti tomu Filistinskému, řekl Abnerovi hejtmanu vojska: Abner, čí jest syn ten mládenček? Odpověděl Abner: Jako jest živa duše tvá, králi, že nevím.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 56, 'Ale král řekl: Zeptej ty se, čí jest syn mládenec ten.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 57, 'Když se pak vracoval David od zabití Filistinského toho, pojav ho Abner, přivedl jej před Saule, an drží hlavu Filistinského v ruce své.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 58, 'I řekl jemu Saul: Čí jsi syn, mládenče? Odpověděl David: Syn služebníka tvého Izai Betlémského.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 1, 'I stalo se, že když přestal mluviti k Saulovi, duše Jonatova spojila se s duší Davidovou, tak že ho zamiloval Jonata jako sebe samého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 2, 'A tak Saul vzal jej k sobě toho dne, a nedopustil mu navrátiti se do domu otce jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 3, 'I učinil Jonata s Davidem smlouvu, proto že ho miloval jako duši svou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 4, 'A složiv Jonata s sebe plášť, kterýmž byl odín, dal jej Davidovi, i roucho své, až do meče svého, a až do lučiště svého, i do pasu svého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 5, 'Vycházel pak David, k čemuž ho koli posílal Saul, opatrně sobě počínaje. I ustanovil ho Saul nad vojáky, a líbil se všemu lidu, též i služebníkům Saulovým.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 6, 'Stalo se pak, když se oni domů brali, a David též se navracoval od zabití Filistinského, že vyšly ženy z každého města Izraelského, zpívajíce a plésajíce, vstříc Saulovi králi s bubny, s veselím a s husličkami.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 7, 'A prozpěvovaly jedny po druhých ženy ty, hrajíce, a řekly: Porazilť jest Saul svůj tisíc, ale David svých deset tisíců.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 8, 'I rozhněval se Saul náramně, nebo nelíbila se mu ta řeč. Pročež řekl: Dali Davidovi deset tisíc, a mně dali toliko tisíc. Co mu ještě přes to přivlastní, leč království?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 9, 'Protož Saul zlobivě hleděl na Davida od toho dne i vždycky.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 10, 'Stalo se pak druhého dne, že duch Boží zlý napadl Saule, a prorokoval u prostřed domu svého, a David hral rukou svou jako i jindy vždycky. Saul pak měl kopí v ruce své.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 11, 'I vyhodil Saul kopí, řka: Prohodím Davida až do stěny. Ale David uhnul se jemu po dvakrát.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 12, 'A bál se Saul Davida, proto že Hospodin byl s ním, a od Saule odstoupil.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 13, 'Protož vybyl ho Saul od sebe, a učinil jej sobě hejtmanem nad tisíci; kterýžto vycházel i vcházel před lidem.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 14, 'David pak ve všech cestách svých opatrně sobě počínal, nebo Hospodin byl s ním.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 15, 'A když to viděl Saul, že sobě velmi opatrně počíná, bál se ho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 16, 'Ale všecken Izrael i Juda miloval Davida, nebo vycházel i vcházel před nimi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 17, 'Tedy řekl Saul Davidovi: Aj, dceru svou starší Merob dámť za manželku, toliko mi buď muž silný, a veď boje Hospodinovy. (Saul pak myslil: Nechť neschází od mé ruky, ale od ruky Filistinských.)');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 18, 'I řekl David Saulovi: Kdo jsem já, a jakýž jest rod můj a čeled otce mého v Izraeli, abych byl zetěm královým?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 19, 'I stalo se, že když již Merob dcera Saulova měla dána býti Davidovi, dána jest Adrielovi Molatitskému za manželku.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 20, 'Milovala pak Míkol dcera Saulova Davida; což když oznámili Saulovi, líbilo se to jemu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 21, '(Nebo řekl Saul: Dámť mu ji, aby mu byla osídlem, a aby proti němu byla ruka Filistinských.) A tak řekl Saul Davidovi: Po této druhé budeš mi již zetěm.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 22, 'I rozkázal Saul služebníkům svým: Mluvte k Davidovi tajně, řkouce: Aj, libuje tě sobě král, a všickni služebníci jeho laskavi jsou na tebe; nyní tedy budiž zetěm královým.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 23, 'A když mluvili služebníci Saulovi v uši Davidovy slova ta, odpověděl David: Zdaliž se vám malá věc zdá, býti zetěm královým? A já jsem člověk chudý a opovržený.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 24, 'Tedy služebníci Saulovi oznámili jemu, řkouce: Taková slova mluvil David.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 25, 'I řekl Saul: Takto rcete Davidovi: Není žádostiv král věna, toliko sto obřízek Filistinských, aby byla pomsta nad nepřátely královskými. (Saul pak to obmýšlel, aby David upadl v ruku Filistinských.)');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 26, 'Protož oznámili služebníci jeho Davidovi slova ta, a líbilo se to Davidovi, aby byl zetěm královým. Ještě se pak nebyli vyplnili dnové ti,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 27, 'Když vstav David, odšel, on i muži jeho, a zbil z Filistinských dvě stě mužů, jejichž obřízky přinesl David, a z úplna je dali králi, aby byl zetěm královým. I dal jemu Saul Míkol dceru svou za manželku.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 28, 'A vida Saul, nýbrž zkušené maje, že jest Hospodin s Davidem, a že Míkol dcera jeho miluje ho,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 29, 'Ještě tím více Saul obával se Davida. I byl Saul nepřítelem Davidovým po všecky dny.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 30, 'Vtrhovali pak do země knížata Filistinská; i bývalo, že kdyžkoli vycházeli, opatrněji sobě počínal David proti nim nade všecky služebníky Saulovy, pročež i jméno jeho bylo velmi slavné.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 1, 'Mluvil pak Saul k Jonatovi synu svému a ke všechněm služebníkům svým, aby zamordovali Davida, ale Jonata syn Saulův liboval sobě Davida velmi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 2, 'I oznámil to Jonata Davidovi, řka: Usiluje Saul otec můj, aby tě zabil; protož nyní šetř se, prosím, až do jitra, a usadě se v skrytě, schovej se.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 3, 'Ale jáť vyjdu a státi budu při boku otci svému na poli, kdež ty budeš, a budu mluviti o tobě s otcem svým, a čemuž vyrozumím, oznámím tobě.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 4, 'I mluvil Jonata o Davidovi dobře Saulovi otci svému, a řekl: Nechť nehřeší král proti služebníku svému Davidovi, nebť jest nic tobě neprovinil, nýbrž správa jeho jest tobě velmi užitečná.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 5, 'Nebo se opovážil života svého a zabil Filistinského, a učinil Hospodin vysvobození veliké všemu Izraeli. Viděls to a radoval jsi se. Pročež bys tedy hřešil proti krvi nevinné, chtěje zabiti Davida bez příčiny?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 6, 'I uposlechl Saul řeči Jonatovy a přisáhl Saul, řka: Živť jest Hospodin, žeť nebude zabit.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 7, 'Tedy Jonata povolal Davida, a oznámil jemu Jonata všecka slova tato. A přivedl Jonata Davida k Saulovi, i byl před ním jako i prvé.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 8, 'Vznikla pak opět válka; a vytáh David, bojoval proti Filistinským, a porazil je porážkou velikou, a utekli před ním.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 9, 'V tom duch Hospodinův zlý napadl Saule, kterýž v domě svém seděl, maje kopí své v ruce své, a David hrál rukou před ním.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 10, 'Ale Saul chtěl prohoditi Davida kopím až do stěny; kterýž uhnul se mu, a udeřilo kopí v stěnu. A tak David utekl a vynikl z nebezpečenství té noci.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 11, 'Potom poslal Saul posly k domu Davidovu, aby ho střáhli a zabili jej ráno. I oznámila to Davidovi Míkol manželka jeho, řkuci: Jestliže se neopatříš noci této, zítra zabit budeš.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 12, 'A protož spustila Míkol Davida oknem, kterýž odšed, utekl a vynikl z nebezpečenství.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 13, 'Vzala pak Míkol obraz a vložila na lůže, a polštář kozí položila v hlavách jeho a přikryla šaty.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 14, 'Tedy Saul poslal posly, aby vzali Davida. I řekla: Jest nemocen.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 15, 'Opět poslal Saul posly, aby pohleděli na Davida, řka: Přineste ho na lůži ke mně, ať ho zabiji.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 16, 'A když přišli poslové, a aj, obraz ležel na lůži a polštář kozí v hlavách jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 17, 'I řekl Saul k Míkol: Proč jsi mne tak podvedla a pustilas nepřítele mého, aby ušel? Odpověděla Míkol Saulovi: On mi řekl: Propusť mne, sic jinak zabiji tě.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 18, 'David tedy utíkaje, vynikl z nebezpečenství, a přišed k Samuelovi do Ráma, oznámil jemu všecko, co mu Saul učinil. I odšel on i Samuel, a bydlili v Náiot.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 19, 'Oznámeno pak bylo Saulovi, řka: Aj, David jest v Náiot v Ráma.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 20, 'I poslal Saul posly, aby jali Davida. Kteříž když viděli zástup proroků prorokujících, a Samuele jim představeného, an stojí, sstoupil také na posly Saulovy Duch Boží, a prorokovali i oni.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 21, 'To když oznámili Saulovi, poslal jiné posly, a prorokovali také i oni; a opět poslal Saul třetí posly, a i ti prorokovali.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 22, 'Šel tedy již sám do Ráma a přišel až k čisterni veliké, kteráž jest v Socho, a zeptal se, řka: Kde jest Samuel a David? I řekl někdo: Aj, jsou v Náiot v Ráma.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 23, 'I šel tam do Náiot v Ráma; a sstoupil i na něj Duch Boží, a jda dále, prorokoval, až i přišel do Náiot v Ráma.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 24, 'Kdežto svlékl také sám roucho své a prorokoval i on před Samuelem, a padna, ležel svlečený celý ten den a noc. Odkudž se říká: Zdali také Saul mezi proroky?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 1, 'V tom utíkaje David z Náiot, kteréž jest v Ráma, přišel a mluvil před Jonatou: Což jsem učinil? Jaká jest nepravost má? A jaký jest hřích můj před otcem tvým, že hledá bezživotí mého?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 2, 'Kterýž řekl jemu: Odstup to, neumřeš. Aj, nečiníť otec můj ničeho ani velikého ani malého, čehož by se mi nesvěřil. Jak by tedy otec můj tajil to přede mnou! Neníť toho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 3, 'Nadto přisáhl také David, (to promluviv: Dobřeť ví otec tvůj, že jsi laskav na mne, protož myslí: Nechť neví o tom Jonata, aby neměl zámutku.) Nýbrž jistě, živť jest Hospodin, a živať jest duše tvá, že sotva jest kročej mezi mnou a mezi smrtí.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 4, 'Odpověděl Jonata Davidovi: Pověz, čehokoli žádáš, a učiním tobě.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 5, 'I řekl David Jonatovi: Aj, zítra bude novměsíce, kdyžto já mám obyčej sedati s králem k jídlu; protož propusť mne, a skryji se na poli až do třetího večera.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 6, 'Jestliže by se zvláštně na mne ptal otec tvůj, řekneš: Prosil mne velice David, aby sběhl do Betléma města svého; nebo obět výroční tam míti má všecka jeho rodina.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 7, 'Řekne-liť: Dobře, pokoj služebníku tvému; pakliť se rozzlobí, věz, žeť se doplnila zlost jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 8, 'A tak učiníš milosrdenství s služebníkem svým, poněvadž jsi v smlouvu Hospodinovu uvedl služebníka svého s sebou. Pakliť jest na mně nepravost, zabí mne sám; nebo k otci svému proč bys mne vodil?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 9, 'I řekl Jonata: Odstup to od tebe; nebo zvím-liť to jistotně, že by se doplnila zlost otce mého, aby přišla na tě, zdaliž neoznámím tobě toho?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 10, 'Řekl také David Jonatovi: Kdož mi oznámí, jestliže odpoví tobě otec tvůj něco tvrdě?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 11, 'Odpověděl Jonata Davidovi: Poď, vyjděme na pole. I vyšli oba na pole.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 12, 'Opět řekl Jonata Davidovi: Hospodin Bůh Izraelský, (hned jakž porozumím na otci svém, okolo tohoto času zítra neb pozejtří, an bude dobře s Davidem, jestliže nepošli tehdáž k tobě, a neoznámím-liť,)');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 13, 'Toto učiň Hospodin Jonatovi a toto přidej. Pakliť se bude líbiti otci mému uvésti zlé na tebe, takéť i to zjevím tobě a propustím tě; i půjdeš v pokoji, a Hospodin budiž s tebou, jakož byl s otcem mým.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 14, 'A zdaliž i ty, dokud jsem živ, neučiníš se mnou milosrdenství Hospodinova, ano bychť i umřel,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 15, 'Tak že neodvrátíš milosrdenství svého od domu mého až na věky, zvláště tehdáž, když Hospodin vypléní nepřátely Davidovy, jednoho každého se svrchku země.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 16, 'A tak učinil Jonata smlouvu s domem Davidovým, řka: Vyhledávejž Hospodin toho z ruky nepřátel Davidových.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 17, 'Ještě i přísahou zavázal Jonata v lásce odměnné k sobě Davida; nebo jakož miloval duši svou, tak jej miloval.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 18, 'I řekl mu Jonata: Zítra bude novměsíce, a bude se ptáti na tebe, když prázdné bude místo tvé.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 19, 'Do třetího tedy dne skrývaje se, sstoupíš rychle a přijdeš k tomu místu, na kterémžs se byl skryl, když se to jednalo, a pobudeš u kamene pocestných.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 20, 'A já tři střely vystřelím po straně k němu, směřuje sobě k cíli.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 21, 'Potom hned pošli pachole a dím: Jdi, shledej střely. Jestliže prostě řeknu služebníku: Hle, střely za tebou blíže sem, přines je, tedy přiď, nebo jest pokoj tobě, a neníť žádného nebezpečenství, živť jest Hospodin.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 22, 'Pakli takto řeknu pacholeti: Hle, střely jsou před tebou dále, tedy odejdi, nebo propustil tě Hospodin.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 23, 'Řeči pak této, kterouž jsme mluvili já a ty, aj, Hospodin svědek bude mezi mnou a mezi tebou až na věky.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 24, 'A tak skryl se David na poli. Byl pak novměsíce, i sedl král za stůl k jídlu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 25, 'A seděl král na stolici své, jakž obyčej měl, na stolici u stěny, ale Jonata povstal. Sedl také Abner podlé Saule, a místo Davidovo zůstalo prázdné.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 26, 'A však toho dne Saul nic neříkal, nebo myslil: Něco se mu přihodilo, buď že čistý jest neb nečistý.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 27, 'Stalo se pak nazejtří, druhého dne novměsíce, že opět prázdné bylo místo Davidovo. I řekl Saul Jonatovi synu svému: Proč nepřišel syn Izai ani včera ani dnes k jídlu?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 28, 'Odpověděl Jonata Saulovi: Velice mne prosil David, aby šel do Betléma.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 29, 'A řekl: Odpusť mne, prosím, nebo obět má míti rodina naše v městě, a bratr můj sám rozkázal mi přijíti; nyní tedy, nalezl-li jsem milost před očima tvýma, nechť se odtrhnu, prosím, abych navštívil bratří své. Tou příčinou nepřišel k stolu královskému.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 30, 'I rozhněval se Saul náramně na Jonatu, a řekl jemu: Synu převrácený a urputný, zdaliž nevím, že jsi zvolil sobě syna Izai k hanbě své, i k hanbě a lehkosti matky své?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 31, 'Nebo po všecky dny, v nichž bude živ syn Izai na zemi, nebudeš upevněn ty, ani království tvé. Protož hned pošli a přiveď jej ke mně, nebť jest hoden smrti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 32, 'Odpověděl Jonata Saulovi otci svému, a řekl jemu: Proč má umříti? Což jest učinil?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 33, 'I hodil Saul kopím na něj, aby ho zabil. Tedy seznav Jonata, že uložil otec jeho zabiti Davida,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 34, 'Vstal od stolu Jonata, rozpálen jsa hněvem, a nejedl toho druhého dne novuměsíce pokrmu, nebo bolestil pro Davida, a že ho tak zlehčil otec jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 35, 'Protož stalo se ráno, že vyšel Jonata na pole k času uloženému Davidovi, a pachole malé s ním.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 36, 'Tedy řekl pacholeti svému: Běž a shledej střely, kteréž já vystřelím. I běželo pachole, a on střílel daleko před něj.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 37, 'Když pak přišlo pachole až k cíli, k němuž střílel Jonata, volal Jonata za pacholetem a řekl: Zdaliž není střely před tebou tam dále?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 38, 'Opět volal Jonata za pacholetem: Rychle pospěš, nestůj. A tak sebravši pachole Jonatovo střely, vrátilo se k svému pánu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 39, '(Pachole pak nic nevědělo, toliko Jonata a David věděli, co se jedná.)');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 40, 'I dal Jonata braň svou pacholeti, kteréž s ním bylo, a řekl jemu: Jdi, dones do města.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 41, 'A když odešlo pachole, vstal David s strany polední, a padna na tvář svou k zemi, poklonil se třikrát; a políbivše jeden druhého plakali oba, až Jonata Davida pozdvihl.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 42, 'I řekl Jonata Davidovi: Jdiž u pokoji, a což jsme sobě oba přisáhli ve jménu Hospodinovu, řkouce: Hospodin budiž svědkem mezi mnou a tebou, i mezi semenem mým a mezi semenem tvým, nechť trvá až na věky. A tak vstav David, odšel, Jonata pak navrátil se do města.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 21, 1, 'Tedy přišel David do Nobe k Achimelechovi knězi. I ulek se Achimelech, vyšel vstříc Davidovi a řekl jemu: Cože to, že jsi sám, a není žádného s tebou?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 21, 2, 'Odpověděl David Achimelechovi knězi: Král mi poručil nějakou věc, a řekl mi: Ať žádný nezvídá toho, proč tě posílám, a coť jsem poručil. Služebníkům pak uložil jsem jisté místo.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 21, 3, 'Protož nyní, co máš tu před rukama, dej v ruku mou, asi pět chlebů, aneb což na hotově máš.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 21, 4, 'Odpověděl kněz Davidovi a řekl: Nemámť chleba obecného před rukama, než toliko chléb svatý, však jestliže se toliko od žen zdrželi služebníci.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 21, 5, 'Odpověděl David knězi a řekl: Jistě ženy vzdáleny byly od nás, jakož včera tak i před včerejškem, když jsem vyšel; protož těla služebníků svatá jsou. Ač pak toto předsevzetí jest proti slušnosti, však i to dnes posvěceno bude pro tělo.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 21, 6, 'A tak dal jemu kněz chleby svaté; nebo nebylo tam chleba, jediné chlebové předložení, kteříž odloženi byli od tváři Hospodinovy, aby položeni byli chlebové teplí toho dne, když ti vzati byli.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 21, 7, '(Byl pak tu jeden z služebníků Saulových v týž den, kterýž se tam pozadržel před Hospodinem, jehož jméno bylo Doeg Idumejský, nejpřednější mezi pastýři Saulovými.)');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 21, 8, 'I řekl David Achimelechovi: Nemáš-liž zde kopí aneb meče? Nebo ani meče svého ani braně své nevzal jsem v ruku svou, proto že rozkaz královský dotíral.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 21, 9, 'Jemuž řekl kněz: Meč Goliáše Filistinského, kteréhož jsi zabil v údolí Elah, aj, ten jest zde obvinutý v roucho za efodem. Jestliže jej chceš sobě vzíti, vezmi, nebo zde jiného není kromě toho. I řekl David: Neníť přes ten, dejž mi jej.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 21, 10, 'Tedy vstal David, a utekl toho dne před Saulem, a přišel k Achisovi králi Gát.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 21, 11, 'Služebníci pak Achisovi řekli jemu: Zdaliž tento není David, král země? Zdaliž neprozpěvovali tomuto po houfích, řkouce: Porazil Saul svůj tisíc, David pak svých deset tisíců.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 21, 12, 'I složil David ta slova v srdci svém, a bál se velmi Achisa krále Gát.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 21, 13, 'Protož změnil způsob svůj před očima jejich, a bláznem se dělal, jsa v rukou jejich; psal také po vratech u brány, a pouštěl sliny po bradě své.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 21, 14, 'Tedy řekl Achis služebníkům svým: Hle, viděvše člověka blázna, pročež jste ho ke mně přivedli?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 21, 15, 'Nedostává-liž se mi bláznů, že jste uvedli tohoto, aby bláznil přede mnou? Ten-liž má vjíti do mého domu?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 1, 'A tak odšel odtud David, skryl se v jeskyni Adulam. To když uslyšeli bratří jeho i všecken dům otce jeho, sešli se tam k němu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 2, 'A shromáždili se k němu, kteřížkoli byli v ssoužení, a kteřížkoli byli zadlužilí, a kteřížkoli byli v hořkosti ducha, a byl nad nimi knížetem, tak že jich bylo s ním okolo čtyř set mužů.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 3, 'Potom odšel odtud David do Masfa Moábského a řekl králi Moábskému: Prosím, nechť vcházejí k vám i vycházejí otec můj a matka má, dokudž nezvím, co se mnou učiní Bůh.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 4, 'I přivedl je před krále Moábského, a bydlili s ním po všecky dny, v nichž zůstával David na tom hradě.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 5, 'Ale prorok Gád řekl Davidovi: Nebývejž déle na tom hradě, jdi, navrať se do země Judské. I odšel David, a přišel do lesa Haret.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 6, 'V tom uslyšel Saul, že by se zjevil David i muži, kteříž byli s ním. Saul pak bydlil v Gabaa pod hájem v Ráma, maje kopí své v rukou svých, a všickni služebníci jeho stáli před ním.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 7, 'I řekl Saul služebníkům svým, kteříž stáli před ním: Slyšte medle, synové Jemini: Všechněm-li vám dá syn Izai pole a vinice? Všecky-li vás postaví za správce nad tisíci a sty,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 8, 'Že jste se všickni spikli proti mně, aniž jest, kdo by mi oznámil? Již i syn můj učinil smlouvu s synem Izai, a však žádný z vás nelituje mne, aniž mi kdo oznámí, že pozdvihl syn můj služebníka mého proti mně, aby mi zálohy strojil, jakož se to již děje.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 9, 'Odpověděl pak Doeg Idumejský, kterýž též stál s služebníky Saulovými, a řekl: Viděl jsem syna Izai, an přišel do Nobe k Achimelechovi synu Achitobovu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 10, 'Kterýž radil se o něho s Hospodinem a dal jemu potravy, také i meč Goliáše Filistinského dal jemu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 11, 'I poslal král, aby zavolali Achimelecha syna Achitobova, kněze, i vší čeledi otce jeho, totiž kněží, kteříž byli v Nobe. I přišli všickni před krále.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 12, 'Tedy řekl Saul: Slyš nyní, synu Achitobův. Kterýž odpověděl: Ej, pane můj.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 13, 'I dí k němu Saul: Proč jste se spikli proti mně, ty a syn Izai, když jsi jemu dal chléb a meč, a radils se s Bohem o něj, aby povstal proti mně k strojení mi záloh, jakož se to již děje?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 14, 'Odpovídaje Achimelech králi, řekl: A kdo jest tak věrný ze všech služebníků tvých jako David, kterýž i zetěm královým jest, kterýž kráčí v poslušenství tvém, a vzácný jest v domě tvém?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 15, 'Zdaliž jsem se nyní počal tázati Boha o něj? Odstup to ode mne. Nesčítejž král takové věci na služebníka svého, ani na koho z čeledi otce mého, neboť neví služebník tvůj o ničemž o tom ani nejmenší věci.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 16, 'Ale král řekl: Smrtí umřeš Achimelechu, ty i všecken dům otce tvého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 17, 'I řekl král drabantům, kteříž stáli před ním: Obraťte se a zbíte kněží Hospodinovy, nebo i jejich ruka jest s Davidem; přes to vědouce, že utíká, nedali mi znáti. Služebníci však královští nechtěli vztáhnouti rukou svých, ani se obořiti na kněží Hospodinovy.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 18, 'A protož řekl král Doegovi: Obrať ty se, a pobí ty kněží. Takž Doeg Idumejský obrátiv se, obořil se na kněží, a zbil toho dne osmdesáte a pět mužů, kteříž nosili efod lněný.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 19, 'Nobe také město kněžské vyhubil ostrostí meče, od muže až do ženy, od malého až do požívajícího prsí, voly i osly, i dobytky pobil ostrostí meče.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 20, 'Jediný toliko syn Achimelechův, syna Achitobova, jehož jméno bylo Abiatar, ušel a utekl k Davidovi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 21, 'Tedy oznámil Abiatar Davidovi, že Saul zmordoval kněží Hospodinovy.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 22, 'I řekl David Abiatarovi: Vědělť jsem toho dne, když tam byl Doeg Idumejský, že jistotně oznámí Saulovi; jáť jsem příčinu dal k zhubení všech duší domu otce tvého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 23, 'Zůstaň u mne, neboj se; nebo kdož hledati bude bezživotí mého, hledati bude bezživotí tvého, ale ochráněn budeš u mne.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 1, 'Tedy oznámili Davidovi, řkouce: Aj, Filistinští dobývají Cejly a loupí dvory.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 2, 'Protož tázal se David Hospodina, řka: Mám-li jíti a udeřiti na ty Filistinské? I odpověděl Hospodin Davidovi: Jdi a porazíš Filistinské, i Cejlu vysvobodíš.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 3, 'Muži pak Davidovi řekli jemu: Aj, my zde v Judstvu bojíme se, čím více, když půjdeme k Cejle proti vojskům Filistinských.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 4, 'A tak opět David tázal se Hospodina. Jemuž odpověděl Hospodin a řekl: Vstana, vytáhni k Cejle, neboť dám Filistinské v ruce tvé.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 5, 'I táhl David a muži jeho k Cejle, a bojoval s Filistinskými, a zajal dobytky jejich. I porazil je ranou velikou, a tak vysvobodil David obyvatele Cejly.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 6, 'Stalo se pak, že když utíkal Abiatar syn Achimelechův k Davidovi do Cejly, dostal se efod v ruce jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 7, 'Potom oznámeno bylo Saulovi, že přitáhl David do Cejly. I řekl Saul: Dalť ho Bůh v ruku mou, nebo zavřel se, všed do města hrazeného a zavřitého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 8, 'I svolal Saul všecken lid k boji, aby táhl k Cejle, a oblehl Davida i muže jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 9, 'A zvěděv David, že Saul tajně ukládá o něm zle, řekl Abiatarovi knězi: Vezmi na se efod.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 10, 'I řekl David: Hospodine, Bože Izraelský, za jistou věc slyšel služebník tvůj, že strojí Saul přitáhnouti k Cejle, aby zkazil město pro mne.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 11, 'Vydali-li by mne muži Cejly v ruce jeho? A přitáhl-li by Saul, jakž slyšel služebník tvůj? Hospodine, Bože Izraelský, oznam, prosím, služebníku svému. Odpověděl Hospodin: Přitáhl by.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 12, 'Řekl ještě David: Vydali-li by mne obyvatelé Cejly i muže mé v ruce Saulovy? Odpověděl Hospodin: Vydali by.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 13, 'Vstav tedy David a muži jeho, téměř šest set mužů, vytáhli z Cejly a šli ustavičně, kamž jíti mohli. Saulovi pak povědíno, že ušel David z Cejly; i nechal tažení.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 14, 'Byl pak David na poušti v místech bezpečných, a bydlil na hoře, na poušti Zif. A ačkoli hledal ho Saul po všecky ty dny, však nevydal ho Bůh v ruku jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 15, 'Vida tedy David, že Saul vytáhl hledati bezživotí jeho, byl na poušti Zif v lese.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 16, 'Vstav pak Jonata syn Saulův, přišel k Davidovi do lesa, a posilnil ruky jeho v Bohu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 17, 'A řekl jemu: Neboj se, neboť nenalezne tebe ruka Saule otce mého, ale ty kralovati budeš nad Izraelem, a já budu druhý po tobě. Však i Saul otec můj zná to.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 18, 'I učinili smlouvu oba před Hospodinem; a David zůstal v lese, Jonata pak navrátil se do domu svého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 19, 'Tedy přišli Zifejští k Saulovi do Gabaa, řkouce: Zdaliž David nepokrývá se u nás v horách, v lese, na pahrbku Hachile, kterýž jest na pravé straně pouště.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 20, 'Protož nyní podlé vší žádosti duše své, ó králi, přitáhni stěží, my se pak přičiníme, abychom jej vydali v ruce královy.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 21, 'I řekl Saul: Požehnaní vy od Hospodina, že mne litujete.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 22, 'Jdětež medle, ujisťte se tím ještě lépe, přezvězte a shlédněte místo jeho, kam se obrátí, kdo ho tam viděl; nebo mi praveno, že divných chytrostí užívá.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 23, 'Vyšpehujtež tedy a vyzvězte všecky skrejše, v nichž se kryje, a navraťte se ke mně s věcí jistou, i potáhnu s vámi, a jestliže v zemi jest, hledati ho budu ve všech tisících Judských.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 24, 'Kteřížto vstavše, navrátili se do Zif před Saulem; David pak a muži jeho byli na poušti Maon, na rovinách po pravé straně pouště.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 25, 'Nebo jakž vytáhl Saul s lidem svým hledati ho, oznámeno bylo to Davidovi, kterýž sstoupil s skály a bydlil na poušti Maon. O čemž Saul uslyšav, honil Davida po poušti Maon.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 26, 'A tak Saul táhl s jedné strany hory, David pak a muži jeho po druhé straně hory. A pospíšil David, aby mohl utéci od tváři Saulovy; nebo Saul s lidem svým obkličovali Davida i muže jeho, aby je zjímali.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 27, 'V tom přišel posel k Saulovi, řka: Pospěš a přiď, nebo Filistinští vtrhli do země.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 28, 'A protož navrátil se Saul od honění Davida, táhl proti Filistinským. Pročež nazvali to místo: Skála rozdělující.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 29, 'Odšed pak David odtud, bydlil v místech bezpečných Engadi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 1, 'I stalo se, že když se navrátil Saul od honění Filistinských, oznámili jemu, řkouce: Hle, David jest na poušti Engadi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 2, 'Tedy vzav Saul tři tisíce mužů vybraných ze všeho Izraele, odšel hledati Davida a mužů jeho na skalách kamsíků.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 3, 'I přišel k stájím ovcí blízko cesty, kdež byla jeskyně, do níž všel Saul na potřebu; David pak a muži jeho seděli po stranách v té jeskyni.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 4, 'Protož řekli muži Davidovi jemu: Aj, tento jest den, o němž tobě mluvil Hospodin, řka: Aj, já dám nepřítele tvého v ruku tvou, abys mu učinil, jakť se koli líbiti bude. Tedy vstav David, uřezal tiše kus pláště Saulova.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 5, 'Potom pak padlo to těžce na srdce Davidovi, že uřezal křídlo pláště Saulova.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 6, 'Pročež řekl mužům svým: Uchovejž mne Hospodin, abych to učiniti měl pánu mému, pomazanému Hospodinovu, abych vztáhnouti měl ruku svou na něj, poněvadž jest pomazaný Hospodinův.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 7, 'A tak zabránil David mužům svým těmi slovy, a nedal jim povstati proti Saulovi. Saul také vyšed z té jeskyně, bral se cestou svou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 8, 'Potom vstal i David, a vyšed z jeskyně, volal za Saulem, řka: Pane můj králi! I ohlédl se Saul zpět, David pak sehnuv se tváří k zemi, poklonil se jemu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 9, 'A řekl David Saulovi: I proč posloucháš řečí lidských, kteříž praví: Hle, David hledá tvého zlého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 10, 'Aj, dnešního dne viděti mohly oči tvé, že tě byl vydal Hospodin dnes v ruku mou v jeskyni. A byloť mi řečeno, abych tě zabil, ale šanoval jsem tě; nebo řekl jsem: Nevztáhnuť ruky své na pána svého, poněvadž jest pomazaný Hospodinův.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 11, 'Nýbrž, otče můj, pohleď a viz kus pláště svého v ruce mé, a žeť jsem nechtěl, odřezuje křídlo pláště tvého, zabiti tebe. Poznejž tedy a viz, žeť není v úmysle mém nic zlého, ani jaké převrácenosti, a žeť jsem nezhřešil proti tobě; ty pak číháš na duši mou, abys mi ji odjal.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 12, 'Sudiž Hospodin mezi mnou a mezi tebou, a pomstiž mne Hospodin nad tebou, ale ruka má nebude proti tobě.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 13, 'Jakož vzní ono přísloví starých: Od bezbožných vychází bezbožnost; protož nebudeť ruka má proti tobě.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 14, 'Na koho to jen vytáhl král Izraelský? Koho to honíš? Psa mrtvého, blechu jednu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 15, 'Ale budeť Hospodin soudce; on nechť rozsoudí mezi mnou a tebou, a nechť pohledí a vyvede při mou, a vysvobodí mne z ruky tvé.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 16, 'Když pak přestal David mluviti slov těch Saulovi, odpověděl Saul: Není-liž to hlas tvůj, synu můj Davide? A pozdvih Saul hlasu svého, plakal.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 17, 'A řekl Davidovi: Spravedlivější jsi nežli já; nebo ty jsi mi odplatil se dobrým, já pak zlým tobě jsem se odplatil.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 18, 'Ty zajisté ukázal jsi dnes, že mi činíš dobře; nebo ačkoli mne byl Hospodin zavřel v ruce tvé, však jsi mne nezabil.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 19, 'Zdali kdo nalezna nepřítele svého, propustí ho po cestě dobré? Ale Hospodin odplatiž tobě dobrým za to, co jsi mi dnešního dne učinil.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 20, 'Protož nyní, (vím, že jistotně kralovati budeš, a že stálé bude v ruce tvé království Izraelské,)');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 21, 'Nyní, pravím, přisáhni mi skrze Hospodina, že nevypléníš semene mého po mně, a nevyhladíš jména mého z domu otce mého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 22, 'A tak přisáhl David Saulovi. I odšel Saul do domu svého, David pak a muži jeho vstoupili na bezpečné místo.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 1, 'Mezi tím umřel Samuel. A shromáždil se všecken Izrael, i plakali ho, a pochovali jej v domě jeho v Ráma. Ale David vstav, šel na poušť Fáran.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 2, 'Člověk pak nějaký byl v Maon, kterýž statek svůj měl na Karmeli. A byl člověk ten možný velmi, nebo měl tři tisíce ovec a tisíc koz, a tehdáž rovně střihl ovce své na Karmeli.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 3, 'Muže pak toho jméno Nábal, a jméno ženy jeho Abigail. A byla žena ta opatrná a krásné tváři, ale muž její byl tvrdý a zlých povah, a byl z rodu Kálefova.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 4, 'Protož uslyšav David na poušti, že by Nábal střihl ovce své,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 5, 'Poslal deset služebníků, a řekl David těm služebníkům: Vstupte na Karmel, a jděte k Nábalovi, a pozdravte ho slovem mým přátelsky.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 6, 'A rcete jemu takto: Zdráv buď, a pokoj tobě, pokoj domu tvému, i všemu, což máš, pokoj.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 7, 'Slyšel jsem, že máš střižce, a pastýři tvoji bývali s námi; neučinili jsme jim žádné křivdy, aniž jim co zhynulo po všecky dny, v nichž byli na Karmeli.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 8, 'Ptej se služebníků svých, a povědí tobě. Nyní tedy nechť naleznou mládenci milost před očima tvýma, nebo v den veselý přišli jsme; dej, prosím, což máš před rukama, služebníkům svým a synu svému Davidovi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 9, 'Přišedše tedy mládenci ti Davidovi, mluvili Nábalovi podlé všech slov těchto jménem Davidovým, a umlkli.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 10, 'Odpověděl pak Nábal služebníkům Davidovým a řekl: Kdo jest David? A kdo syn Izai? Mnohotě nyní služebníků, kteříž se odtrhují jeden každý od pána svého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 11, 'Ano, vezmu já chléb svůj, a vodu svou a pokrmy své, kteréž jsem připravil střižcům svým, a dám je těm lidem, kterýchž neznám, ani vím, odkud jsou?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 12, 'A obrátivše se služebníci Davidovi na cestu svou, navrátili se, a přišedše, oznámili jemu všecka slova ta.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 13, 'I řekl David mužům svým: Připaš každý meč svůj. Kteříž když připásali jeden každý meč svůj, připásal také David meč svůj, a šlo za Davidem okolo čtyř set mužů, dvě stě pak pozůstalo u břemen.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 14, 'A v tom Abigail, ženě Nábalově, oznámil mládenec jeden z služebníků, řka: Aj, poslal David posly s pouště, aby pozdravili pána našeho, ale on je ukřikal;');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 15, 'Ješto muži ti prospěšní nám byli velice, ani nám neučinili křivdy, aniž nám co zhynulo, když jsme bývali s nimi na poli.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 16, 'Místo zdi byli nám v noci i ve dne po všecky dny, dokudž jsme s nimi byli, pasouce stáda.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 17, 'Protož nyní pomysl a viz, co bys měla činiti, neboť již zlé věci hotové jsou na pána našeho i na všecken dům jeho; on pak jest tak zlobivý, že s ním nelze ani mluviti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 18, 'Tedy pospíšila Abigail, a vzala dvě stě chlebů, a dvě kožené láhvice vína, a pět ovcí připravených, a pět měr pražmy, a sto sušených hroznů, a dvě stě hrud fíků sušených, a vložila to na osly.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 19, 'I řekla služebníkům svým: Jdětež napřed, a já za vámi půjdu. Ale muži svému Nábalovi neoznámila.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 20, 'I stalo se, že vsedši na osla, sjížděla po stráni s hory, a aj, David a muži jeho sstupovali proti ní, a potkala se s nimi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 21, '(David pak byl řekl: Jistě nadarmo jsem ostříhal všeho, což on měl na poušti, tak že nic nezahynulo ze všeho, což má; nebo mi se odplatil zlým za dobré.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 22, 'Toto učiň Bůh nepřátelům Davidovým a toto přidej, jestliže zanechám do jitra ze všeho, což má, až do toho, kterýž močí na stěnu.)');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 23, 'Tedy uzřevši Abigail Davida, rychle ssedla s osla, a padla před Davidem na tvář svou, a poklonila se až k zemi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 24, 'A padši k nohám jeho, řekla: Na mně, pane můj, ta nepravost. Protož nechť mluví, prosím, služebnice tvá v uši tvé, a vyslyš slova děvky své.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 25, 'Nechť se neobrací, prosím, pán můj myslí svou za mužem tím bezbožným Nábalem; nebo jakéž jest jméno jeho, takovýž jest. Nábal jméno jeho jest, a bláznovství jest při něm. Já pak služebnice tvá neviděla jsem služebníků pána mého, kteréž jsi byl poslal.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 26, 'Protož nyní, pane můj, živť jest Hospodin, a živať jest duše tvá, že tě tobě zbránil Hospodin vylíti krve, a abys nemstil sám sebe. A protož nyní buďtež jako Nábal nepřátelé tvoji, a ti, kteříž hledají zlého pánu mému.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 27, 'Teď pak dar tento, kterýž přinesla děvka tvá pánu svému, nechť jest dán služebníkům, kteříž chodí za pánem mým.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 28, 'Odpusť, prosím, provinění děvce své, neboť jistě vzdělá Hospodin pánu mému dům stálý, poněvadž boje Hospodinovy pán můj vede, a nic zlého se nenalézá při tobě až posavad.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 29, 'A byť i povstal člověk, aby tě stihal a hledal bezhrdlí tvého, budeť však duše pána mého svázána v svazku živých u Hospodina Boha tvého, duši pak nepřátel tvých jako z praku pryč zahodí.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 30, 'A když učiní Hospodin pánu mému dobře podlé toho všeho, jakž zaslíbil tobě, a přikážeť, abys byl vůdcím nad Izraelem:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 31, 'Tedy nebude to k zviklání ani k urážce srdce pánu mému, jako když by vylil krev bez příčiny, aneb když by se mstil pán můj. Když tedy učiní dobře Hospodin pánu mému, rozpomeň se na děvku svou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 32, 'I řekl David k Abigail: Požehnaný Hospodin Bůh Izraelský, že tě poslal dne tohoto mně v cestu;');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 33, 'A požehnaná řeč tvá, i ty požehnaná, že jsi zdržela mne dnes, abych nevylil krve a nemstil sám sebe.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 34, 'A jistě, jako živ jest Hospodin Bůh Izraelský, kterýž mi zbránil, ať bych zle nečinil, že kdybys nebyla pospíšila a nevyšla mi v cestu, nebyl by zůstal Nábalovi do jitra ani močící na stěnu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 35, 'I přijal David z ruky její, což byla přinesla jemu, a řekl jí: Jdiž v pokoji do domu svého. Pohleď, uslyšel jsem prosbu tvou, a vážil jsem sobě osoby tvé.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 36, 'A tak navrátila se Abigail k Nábalovi, an měl hody v domě svém jako hody královské; a srdce Nábalovo rozveselilo se bylo v něm, a byl opilý velmi. Pročež ona neoznámila jemu nejmenšího slova až do jitra.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 37, 'Nazejtří pak, když z vína vystřízlivěl Nábal, tedy oznámila jemu žena jeho ty věci. I zmrtvělo v něm srdce jeho, a učiněn jest jako kámen.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 38, 'A když pominulo takměř deset dní, porazil Hospodin Nábale, i umřel.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 39, 'Uslyšev pak David, že by Nábal umřel, řekl: Požehnaný Hospodin, kterýž hodně pomstil pohanění mého nad Nábalem, a služebníka svého zdržel ode zlého, zlost pak Nábalovu shrnul Hospodin na hlavu jeho. Tedy poslal David a mluvil k Abigail, aby ji sobě vzal za manželku.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 40, 'I přišli služebníci Davidovi k Abigail na Karmel, a mluvili s ní, řkouce: David poslal nás k tobě, aby tě vzal sobě za manželku.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 41, 'Kterážto vstavši, poklonila se na tvář až k zemi, řkuci: Aj, služebnice tvá za děvku bude, aby umývala nohy služebníkům pána svého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 42, 'Protož rychle vstavši Abigail a vsedši na osla svého, (pět pak děveček jejích šlo za ní,) jela za posly Davidovými, a byla manželkou jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 43, 'Též i Achinoam pojal David z Jezreel, a byly i tyto dvě manželky jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 44, 'Nebo Saul Míkol dceru svou, manželku Davidovu, dal byl Faltiovi, synu Lais, kterýž byl z Gallim.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 1, 'Opět přišli Zifejští k Saulovi do Gabaa, řkouce: Nevíš-liž, že se David kryje na pahrbku Hachila proti poušti?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 2, 'Protož povstal Saul a táhl na poušť Zif, a s ním tři tisíce mužů vybraných z Izraele, aby hledal Davida na poušti Zif.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 3, 'I položil se Saul na pahrbku Hachila, kterýž jest proti Jesimon při cestě. David pak trvaje na poušti, srozuměl, že Saul za ním přitáhl na poušť.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 4, 'Nebo poslav David špehéře, vyzvěděl jistotně, že Saul přitáhl.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 5, 'Tedy vstav David, šel k místu, na němž se položil Saul s vojskem. I spatřil David místo, na kterémž ležel Saul a Abner syn Nerův, hejtman vojska jeho. Saul pak spal, jsa vozy otočen, lid také ležení svá měl vůkol něho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 6, 'I mluvil David a řekl Achimelechovi Hetejskému a Abizai synu Sarvie, bratru Joábovu, řka: Kdo sstoupí se mnou k Saulovi do ležení? Odpověděl Abizai: Já sstoupím s tebou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 7, 'A tak přišel David a Abizai k lidu v noci, a aj, Saul leže, spal, jsa vozy otočen, a kopí jeho vetknuté bylo v zemi u hlavy jeho, Abner pak i lid spali vůkol něho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 8, 'Tedy řekl Abizai Davidovi: Dalť Bůh dnes nepřítele tvého v ruku tvou. Protož nyní, medle nechť jej probodnu pojednou kopím až do země, tak že nebude potřebí podruhé.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 9, 'Ale David řekl k Abizai: Nezabíjej ho; nebo kdo vztáhna ruku svou na pomazaného Hospodinova, byl by bez viny?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 10, 'Řekl také David: Živť jest Hospodin, leč Hospodin raní jej, aneb den jeho přijde, aby umřel, aneb na vojnu vytáhna, zahyne:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 11, 'Mně nedej Hospodin, abych vztáhnouti měl ruku svou na pomazaného Hospodinova. Ale nyní vezmi medle to kopí, kteréž jest u hlavy jeho, a tu číši vodnou, a odejděme.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 12, 'I vzal David kopí a číši vodnou u hlavy Saulovy, a odešli, tak že žádný neviděl, ani nezvěděl, ani neprocítil, ale všickni spali; nebo sen tvrdý Hospodinův připadl byl na ně.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 13, 'A přešed David na druhou stranu, postavil se na vrchu hory zdaleka; nebo bylo mezi nimi nemalé místo.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 14, 'I zavolal David na lid a na Abnera syna Ner, řka: Což se neozveš, Abner? Odpovídaje pak Abner, řekl: Kdo jsi ty, kterýž voláš na krále?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 15, 'I řekl David Abnerovi: Zdaliž ty nejsi muž? A kdo jest tobě rovný v Izraeli? Proč jsi tedy neostříhal krále, pána svého? Nebo přišel jeden z lidu, aby zabil krále, pána tvého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 16, 'Neníť to dobře, co jsi učinil. Živť jest Hospodin, že jste hodni smrti, proto že neostříháte pána svého, pomazaného Hospodinova. Ale nyní pohleď, kde jest kopí královo a číše vodná, kteráž byla u hlavy jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 17, 'Tedy poznal Saul hlas Davidův a řekl: Není-liž to hlas tvůj, synu můj Davide? Odpověděl David: Jest můj hlas, pane můj králi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 18, 'Řekl také: Proč je to, že pán můj honí služebníka svého? Nebo co jsem učinil? A co jest zlého v ruce mé?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 19, 'Protož nyní poslyš, prosím, pane můj králi, slov služebníka svého: Jestliže tě Hospodin vzbudil proti mně, nechť zachutná obět, pakli lidé, zlořečení jsou před Hospodinem; nebo mne vyhnali dnes, abych nemohl obcovati dědictví Hospodinovu, jako by řekli: Jdi, služ bohům cizím.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 20, 'Ale již aspoň nechť není vylita krev má na zemi bez rozsouzení Hospodinova; nebo vytáhl král Izraelský hledati blechy jedné, rovně jako by honil koroptvu na horách.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 21, 'I řekl Saul: Zhřešilť jsem, navratiž se, synu můj Davide. Neboť nebudu více zle činiti tobě, proto že jsi draze sobě vážil života mého dnešní den. Aj, bláznivě jsem dělal a bloudil přenáramně.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 22, 'A odpovídaje David, řekl: Teď hle kopí královo. Nechť přijde někdo z služebníků, a vezme je.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 23, 'Hospodin pak navratiž jednomu každému za spravedlnost jeho a věrnost jeho. Daltě byl zajisté Hospodin tebe dnes v ruku mou, ale nechtělť jsem vztáhnouti ruky své na pomazaného Hospodinova.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 24, 'A protož jakož jsem já dnes sobě draze vážil života tvého, tak budiž draze vážen život můj před Hospodinem, aby mne vysvobodil ze vší úzkosti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 25, 'Tedy řekl Saul Davidovi: Požehnaný jsi, synu můj Davide. Tak čině, dokážeš ctnosti, a v tom se zmocňuje, zkvetneš. V tom odšel David cestou svou, Saul také navrátil se k místu svému.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 27, 1, 'Řekl pak David v srdci svém: Když tedyž sejdu od ruky Saulovy, nic mi lepšího není, než abych naprosto utekl do země Filistinské. I pustí o mně Saul, a nebude mne více hledati v žádných končinách Izraelských, a tak ujdu ruky jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 27, 2, 'Tedy vstav David, odebral se sám i těch šest set mužů, kteříž byli s ním, k Achisovi synu Maoch, králi Gát.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 27, 3, 'I bydlil David s Achisem v Gát, on i muži jeho, jeden každý s čeledí svou, David i dvě ženy jeho, Achinoam Jezreelská, a Abigail Karmelská někdy žena Nábalova.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 27, 4, 'A když bylo oznámeno Saulovi, že utekl David do Gát, přestal ho hledati více.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 27, 5, 'Řekl pak David Achisovi: Prosím, jestliže jsem nalezl milost před očima tvýma, ať mi dají místo v některém městě krajiny této, abych tam bydlil; nebo proč má bydliti služebník tvůj s tebou v městě královském?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 27, 6, 'I dal mu Achis v ten den Sicelech, odkudž Sicelech bylo králů Judských až do dne tohoto.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 27, 7, 'Byl pak počet dnů, v nichž bydlil David v krajině Filistinské, den a čtyři měsíce.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 27, 8, 'I vycházel David s muži svými, vpády činíce na Gessurské a Gerzitské a Amalechitské, (nebo ti bydlili v zemi té od starodávna,) kudy se chodí přes Sur až do země Egyptské.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 27, 9, 'A hubil David krajinu tu, nenechávaje živého muže ani ženy; bral také ovce i voly, i osly i velbloudy, i šaty, a navracoval se a přicházel k Achisovi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 27, 10, 'A když se ptal Achis: Kam jste dnes vpadli? odpověděl David: K straně polední Judově, a k straně polední Jerachmeelově, a k straně polední Cinejského.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 27, 11, 'Neživil pak David ani muže ani ženy, aby koho přivoditi měl do Gát; nebo myslil: Aby na nás nežalovali, řkouce: Tak učinil David. A ten obyčej jeho byl po všecky dny, dokudž zůstával v krajině Filistinské.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 27, 12, 'I věřil Achis Davidovi, řka: Jižtě se velice zošklivil lidu svému Izraelskému, protož budeť mi za služebníka na věky.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 1, 'I stalo se za dnů těch, že Filistinští sebrali vojska svá k boji, aby bojovali s Izraelem. I řekl Achis Davidovi: Věz nepochybně, že potáhneš se mnou na vojnu, ty i muži tvoji.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 2, 'Odpověděl David Achisovi: Teprv ty poznáš, co učiní služebník tvůj. I řekl Achis Davidovi: Touť příčinou strážným života svého tě ustanovím po všecky dny.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 3, '(Samuel pak již byl umřel; pročež plakal ho všecken Izrael, a pochovali jej v Ráma, totiž v městě jeho. A Saul byl vyplénil věšťce a hadače z země.)');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 4, 'Tedy shromáždivše se Filistinští, přitáhli a položili se u Sunem. Shromáždil i Saul všeho Izraele, a položili se v Gelboe.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 5, 'Vida pak Saul vojsko Filistinské, bál se, a uleklo se srdce jeho velmi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 6, 'I dotazoval se Saul Hospodina, ale Hospodin neodpovídal jemu ani skrze sny, ani skrze urim, ani skrze proroky.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 7, 'Protož řekl Saul služebníkům svým: Pohledejte mi ženy mající ducha věštího, i půjdu k ní a poradím se skrze ni. Jemuž odpověděli služebníci jeho: Aj, žena mající ducha věštího v Endor.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 8, 'Tedy změniv Saul oděv, oblékl se v roucho jiné, a šel sám a dva muži s ním, a přišli k ženě té v noci. I řekl: Medle hádej mi skrze ducha věštího, a způsob to, ať ke mně vyjde ten, kohož bych jmenoval tobě.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 9, 'Ale žena řekla jemu: Aj, ty víš, co učinil Saul, kterak vyhladil věšťce a hadače z země. Pročež tedy ty pokládáš osídlo duši mé, abys mne o hrdlo připravil?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 10, 'I přisáhl jí Saul skrze Hospodina, řka: Živť jest Hospodin, že nepřijde na tě trestání pro tu věc.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 11, 'Tedy řekla žena: Kohožť mám vyvésti? Kterýž řekl: Samuele mi vyveď.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 12, 'A když uzřela žena Samuele, zkřikla hlasem velikým, a řekla žena Saulovi takto: Pročež jsi mne oklamal! Nebo ty jsi Saul.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 13, 'I řekl jí král: Neboj se. Což jsi pak viděla? Odpověděla žena Saulovi: Bohy jsem viděla vystupující z země.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 14, 'Řekl jí opět: Jaký jest způsob jeho? Odpověděla jemu: Muž starý vystupuje a jest oděný pláštěm. Tedy srozuměl Saul, že by Samuel byl, a sehnuv se tváří k zemi, poklonil se jemu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 15, 'I řekl Samuel Saulovi: Proč mne nepokojíš, že jsi mne zavolati rozkázal? Odpověděl Saul: Úzkostmi sevřín jsem velice; nebo Filistinští bojují proti mně, a Bůh odstoupil ode mne, a neodpovídá mi více, ani skrze proroky, ani skrze sny. Protož povolal jsem tě, abys mi oznámil, co bych měl činiti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 16, 'I řekl Samuel: Proč tedy se mne dotazuješ, poněvadž Hospodin odstoupil od tebe, a jest s nepřítelem tvým?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 17, 'Učiniltě zajisté jemu Hospodin, jakož mluvil skrze mne, a odtrhl Hospodin království od ruky tvé, a dal je bližnímu tvému, Davidovi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 18, 'Nebo že jsi neuposlechl hlasu Hospodinova, a nevykonals hněvu prchlivosti jeho nad Amalechem, protož učinil tobě to dnes Hospodin.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 19, 'Nadto vydá Hospodin i Izraele s tebou v ruku Filistinských, a zítra budeš ty i synové tvoji se mnou. I vojska Izraelská vydá Hospodin v ruku Filistinských.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 20, 'I padl Saul náhle tak, jak dlouhý byl, na zem, nebo se byl ulekl náramně slov Samuelových. K tomu ani síly v něm nebylo, nebo nic nejedl celý ten den a celou tu noc.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 21, 'Přistoupivši pak ta žena k Saulovi a uzřevši, že jest předěšen náramně, řekla jemu: Aj, uposlechla děvka tvá hlasu tvého, a opovážila jsem se života svého, že jsem uposlechla slov tvých, kteráž jsi mluvil ke mně.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 22, 'Nyní tedy uposlechni i ty, prosím, hlasu děvky své, a položím před tebe kousek chleba, abys jedl a posilil se, a tak jíti mohl cestou svou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 23, 'Kterýž odepřel a řekl: Nebuduť jísti. I přinutili ho služebníci jeho, ano i ta žena, tak že uposlechl hlasu jejich, a vstav s země, sedl na lůžko.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 24, 'Měla pak ta žena tele tučné v domě, kteréž spěšně zabila, a vzavši mouky, zadělala, a napekla z ní chlebů přesných.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 25, 'Potom přinesla před Saule a služebníky jeho, kteříž jedli, a vstavše v touž noc, odešli.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 29, 1, 'A tak shromáždili Filistinští všecka vojska svá u Afeku, Izrael pak položil se u studnice, kteráž byla v Jezreel.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 29, 2, 'I táhla knížata Filistinská po stu a po tisících, David pak a muži jeho táhli nazad s Achisem.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 29, 3, 'Tedy řekla knížata Filistinská: K čemu jsou Židé tito? Odpověděl Achis knížatům Filistinským: Zdaliž toto není David služebník Saule, krále Izraelského, kterýž byl při mně dnů těchto, nýbrž těchto let, a neshledal jsem na něm ničeho ode dne, jakž odpadl od Saule, až do tohoto dne?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 29, 4, 'I rozhněvala se na něj knížata Filistinská, a řekli jemu ta knížata Filistinská: Odešli zase muže toho, ať se navrátí k místu svému, kteréž jsi mu ukázal, a nechť netáhne s námi k boji, aby se nám nepostavil za nepřítele v bitvě. Nebo čím se zalíbiti může pánu svému tento? Zdali ne hlavami mužů těchto?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 29, 5, 'Zdaliž tento není ten David, o kterémž zpívali v houfích plésajících, říkajíce: Porazil Saul svůj tisíc, ale David svých deset tisíců?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 29, 6, 'I povolal Achis Davida, a řekl jemu: Živť jest Hospodin, že jsi upřímý, a líbí mi se vycházení tvé i vcházení tvé se mnou do vojska. Nebo neshledal jsem na tobě nic zlého ode dne, v kterýž jsi přišel ke mně, až do dne tohoto, ale před očima knížat nejsi vzácný.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 29, 7, 'Protož nyní navrať se a jdi v pokoji, a nebudeš těžký v očích knížat Filistinských.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 29, 8, 'I řekl David Achisovi: Co jsem pak učinil, a co jsi shledal na služebníku svém ode dne, v kterýž jsem počal býti u tebe, až do tohoto dne, abych nešel a nebojoval proti nepřátelům pána svého krále?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 29, 9, 'A odpovídaje Achis, řekl Davidovi: Vímť, že jsi vzácný před očima mýma jako anděl Boží, ale knížata Filistinská řekla: Nechť netáhne s námi k boji.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 29, 10, 'Nyní tedy vstaň tím raněji a služebníci pána tvého, kteříž přišli s tebou, a vstanouce tím spíše ráno, hned jakž by zasvitávalo, odejděte.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 29, 11, 'I vstal David, on i muži jeho, aby odšel tím raněji, a navrátil se do země Filistinské. Filistinští pak táhli do Jezreel.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 1, 'Byl pak, když se navrátil David a muži jeho do Sicelechu, den třetí, jakž Amalechitští byli vpád učinili k straně polední i k Sicelechu, a vyhubili Sicelech, a vypálili jej.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 2, 'A zajali ženy, kteréž byly v něm. Nezabili žádného, ani malého ani velikého, ale szajímali a odešli cestou svou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 3, 'A když přišel David a muži jeho k městu, aj, vypáleno bylo ohněm, a ženy jejich, též synové a dcery jejich zajati byli.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 4, 'Tedy David i lid jeho, kterýž s ním byl, pozdvihše hlasu svého, plakali, až již více plakati nemohli.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 5, 'Obě také manželky Davidovy zajaty jsou, Achinoam Jezreelitská, a Abigail žena někdy Nábale Karmelského.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 6, 'I ssoužen jest David náramně, nebo se smlouval lid, aby ho ukamenovali, (hořkostí zajisté naplněna byla duše všeho lidu, jednoho každého pro syny jeho a pro dcery jeho). Však posilnil se David v Hospodinu Bohu svém.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 7, 'I řekl David Abiatarovi knězi, synu Achimelechovu: Medle, vezmi na sebe efod. I vzal Abiatar efod pro Davida.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 8, 'Tázal se pak David Hospodina, řka: Mám-li honiti lotříky ty? A dohoním-li se jich? I řekl jemu: Hoň, nebo se jich jistě dohoníš, a své mocně vysvobodíš.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 9, 'A tak odšed David sám i těch šest set mužů, kteříž byli s ním, přišli až ku potoku Bezor; někteří pak tu pozůstali.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 10, 'I honil je David se čtyřmi sty mužů; nebo bylo pozůstalo dvě stě mužů, kteříž ustavše, nemohli přejíti potoka Bezor.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 11, 'A nalezše muže Egyptského v poli, přivedli jej k Davidovi. I dali jemu chleba, aby pojedl; dali jemu také i vody píti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 12, 'Dali jemu též kus hrudy fíků a dva hrozny suché. A tak pojedl a okřál zase, (nebo byl nic nejedl ani nepil tři dni a tři noci).');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 13, 'Zatím řekl jemu David: Čí jsi ty? A odkud jsi? Kterýž odpověděl: Rodem jsem z Egypta, služebník muže Amalechitského, a opustil mne pán můj, proto že jsem stonal, dnes třetí den.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 14, 'Byli jsme zajisté vpád učinili k straně polední Ceretejského, a v tu stranu, kteráž jest Judova, a ku poledni, kteráž jest Kálefova, a Sicelech jsme vypálili ohněm.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 15, 'Tedy řekl jemu David: Mohl-li bys dovésti mne k těm lotříkům? Kterýž řekl: Přisáhni mi skrze Boha, že mne nezabiješ, a že mne nevydáš v ruku pána mého, a přivedu tě na ty lotříky.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 16, 'I přivedl ho. (A aj, byli se rozprostřeli po vší té zemi, jedouce a pijíce a provyskujíce nade všemi kořistmi tak velikými, kteréž pobrali z země Filistinské a z země Judovy.)');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 17, 'Protož bil je David od večera až do večera druhého dne, aniž kdo z nich ušel, kromě čtyř set mládenců, kteříž vsedše na velbloudy, utekli.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 18, 'A tak odjal David všecko, což byli pobrali Amalechitští; také obě ženy své vysvobodil David.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 19, 'A nezhynulo jim nic, ani malého ani velikého, i z synů i ze dcer, i z loupeže a ze všeho, což jim vzato bylo; všecko zase David přivedl.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 20, 'Nadto szajímal David všecka stáda bravů i skotů, kteráž hnali před dobytkem svým, a pravili: Totoť jsou kořisti Davidovy.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 21, 'Přišel pak David k těm dvěma stům mužů, kteříž byli ustali, tak že nemohli jíti za Davidem, jimž byli kázali zůstati při potoku Bezor; tedy vyšli vstříc Davidovi a lidu, kterýž byl s ním. A přistoupiv David k tomu lidu, pozdravil jich přátelsky.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 22, 'Ale všickni, což jich koli bylo zlých a bezbožných mezi těmi muži, kteříž chodili s Davidem, mluvili, řkouce: Poněvadž nešli s námi, nedáme jim z kořistí, kteréž jsme odjali, toliko každému manželku jeho a syny jeho, aby vezmouce je, odešli.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 23, 'David pak řekl: Nečiňte tak, bratří moji, s tím, což nám dal Hospodin, kterýž nás ostříhal a dal vojsko, jenž vytáhlo proti nám, v ruku naši.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 24, 'A kdož vás uposlechne v té věci? Nebo jakýž bude díl toho, kterýž vyšel k bitvě, takovýž bude díl i toho, kterýž hlídal břemen; rovně se děliti budou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 25, 'A tak bývalo od toho dne i potom, nebo to za právo a obyčej uložil v Izraeli až do tohoto dne.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 26, 'A když přišel David do Sicelechu, poslal z těch kořistí starším Juda, přátelům svým, řka: Teď máte dar z loupeží nepřátel Hospodinových.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 27, 'Těm, kteříž byli v Bethel, a kteříž v Rámat ku poledni, a kteříž byli v Jeter;');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 28, 'Též kteříž v Aroer, a kteříž v Sefama, a kteříž v Estemo;');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 29, 'A kteříž v Rachal, a kteříž v městech Jerachmeelových, a kteříž v městech Cinejského;');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 30, 'I těm, kteříž v Horma, a kteříž v Korasan, a kteříž v Atach;');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 31, 'A kteříž byli v Hebronu, i po všech místech, na nichž býval David s lidem svým.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 31, 1, 'A tak potýkali se Filistinští s Izraelem. Muži pak Izraelští utíkali před Filistinskými a padli, zbiti jsouce na hoře Gelboe.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 31, 2, 'I stihali Filistinští Saule a syny jeho, a zabili Filistinští Jonatu a Abinadaba a Melchisua, syny Saulovy.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 31, 3, 'Když se pak zsilila bitva proti Saulovi, trefili na něj střelci, muži s luky; i postřelen jest velmi od těch střelců.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 31, 4, 'I řekl Saul oděnci svému: Vytrhni meč svůj a probodni mne jím, aby přijdouce ti neobřezanci, neprobodli mne, a neučinili sobě ze mne posměchu. Ale nechtěl oděnec jeho, nebo se bál velmi. A pochytiv Saul meč, nalehl na něj.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 31, 5, 'Tedy vida oděnec jeho, že umřel Saul, nalehl i on na meč svůj a umřel s ním.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 31, 6, 'A tak umřel Saul a tři synové jeho, a oděnec jeho, ano i všickni muži jeho v ten den spolu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 31, 7, 'Když pak uzřeli synové Izraelští, kteříž bydlili za tím údolím, a kteříž bydlili za Jordánem, že zutíkali muži Izraelští, nadto že Saul i synové jeho zahynuli, opustivše města, také utíkali. I přišli Filistinští a bydlili v nich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 31, 8, 'A když bylo nazejtří, přišli Filistinští, aby zloupili pobité; i nalezli Saule a tři syny jeho ležící na hoře Gelboe.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 31, 9, 'I sťali hlavu jeho a svlékli odění jeho, a poslali po zemi Filistinské vůkol, aby to ohlášeno bylo v chrámě modl jejich i lidu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 31, 10, 'I složili odění jeho v chrámě Astarot, tělo pak jeho přibili na zdi Betsan.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 31, 11, 'Tedy uslyšavše o tom obyvatelé Jábes Galád, co učinili Filistinští Saulovi,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 31, 12, 'Zdvihli se všickni muži silní, a jdouce celou noc, sňali tělo Saulovo i těla synů jeho se zdi Betsanské; a když se navrátili do Jábes, spálili je tam.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 31, 13, 'A vzavše kosti jejich, pochovali je pod stromem v Jábes, a postili se sedm dní.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 1, 'Stalo se pak po smrti Saulově, když se navrátil David od porážky Amalechitských, že pobyl v Sicelechu za dva dni.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 2, 'A aj, dne třetího přišel jeden z vojska Saulova, maje roucho roztržené a prach na hlavě své. Kterýž když přišel k Davidovi, padl na zemi a poklonil se.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 3, 'I řekl jemu David: Odkud jdeš? Jemuž odpověděl: Z vojska Izraelského utekl jsem.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 4, 'Opět řekl jemu David: Cože se stalo? Medle, pověz mi. Kterýž odpověděl: To, že utekl lid z boje, a množství lidu padlo a zbito jest; též i Saul i Jonata syn jeho zbiti jsou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 5, 'Řekl ještě David mládenci, kterýž mu to oznámil: Kterak ty víš, že umřel Saul i Jonata syn jeho?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 6, 'Odpověděl mládenec, kterýž to oznamoval jemu: Náhodou přišel jsem na horu Gelboe, a aj, Saul nalehl byl na kopí své, a vozové i jezdci postihali ho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 7, 'Kterýžto ohlédna se zpátkem, uzřel mne a zavolal na mne. I řekl jsem: Aj, teď jsem.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 8, 'Tedy řekl mi: Kdo jsi ty? Odpověděl jsem jemu: Amalechitský jsem.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 9, 'I řekl mi: Přistup medle sem a zabí mne, nebo mne obklíčila úzkost, a ještě všecka duše má jest ve mně.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 10, 'Protož stoje nad ním, zabil jsem ho, nebo jsem věděl, že nebude živ po svém pádu. A vzal jsem korunu, kteráž byla na hlavě jeho, i záponu, kteráž byla na rameni jeho, a teď jsem to přinesl ku pánu svému.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 11, 'Tedy David uchytiv roucho své, roztrhl je; tolikéž i všickni muži, kteříž s ním byli.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 12, 'A nesouce smutek, plakali a postili se až do večera pro Saule a pro Jonatu syna jeho, i pro lid Hospodinův a pro dům Izraelský, že padli od meče.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 13, 'Řekl pak David mládenci, kterýž mu to oznámil: Odkud jsi ty? Odpověděl: Syn muže příchozího Amalechitského jsem.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 14, 'Opět mu řekl David: Kterak jsi směl vztáhnouti ruku svou, abys zahubil pomazaného Hospodinova?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 15, 'A zavolav David jednoho z mládenců, řekl jemu: Přistoupě, oboř se na něj. Kterýžto udeřil ho, tak že umřel.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 16, 'I řekl jemu David: Krev tvá budiž na hlavu tvou, neboť jsou ústa tvá svědčila na tebe, řkouce: Já jsem zabil pomazaného Hospodinova.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 17, 'Tedy naříkal David naříkáním tímto nad Saulem a nad Jonatou synem jeho,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 18, '(Přikázav však, aby synové Judovi učeni byli stříleti z luku, jakož psáno v knize Upřímého.):');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 19, 'Ó kráso Izraelská, na výsostech tvých zraněni, jakť jsou padli udatní!');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 20, 'Neoznamujtež v Gát, ani toho ohlašujte na ulicích Aškalon, aby se neveselily dcery Filistinských, a neplésaly dcery neobřezaných.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 21, 'Ó hory Gelboe, ani rosa, ani déšť nespadej na vás, ani tu buď pole úrodné; nebo tam jest povržen štít udatných, štít Saulův, jako by nebyl pomazán olejem.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 22, 'Od krve raněných a od tuku udatných lučiště Jonatovo nikdy zpět neodskočilo, a meč Saulův nenavracoval se prázdný.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 23, 'Saul a Jonata milí a utěšení v životě svém, také při smrti své nejsou rozloučeni. Nad orlice bystřejší, nad lvy silnější byli.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 24, 'Dcery Izraelské, plačte Saule, kterýž vás odíval červcem dvakrát barveným rozkošně, kterýž dával ozdoby zlaté na roucha vaše.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 25, 'Ach, jakť jsou padli udatní u prostřed boje? Jonata na výsostech tvých zabit jest.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 26, 'Velice jsem po tobě teskliv, bratře můj Jonato. Byl jsi mi příjemný náramně; vzácnější u mne byla milost tvá nežli milost žen.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 27, 'Ach, jakť jsou padli udatní, a zahynula odění válečná.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 1, 'I stalo se potom, že se David tázal Hospodina, řka: Mám-li jíti do některého města Judského? Jemuž odpověděl Hospodin: Jdi. I řekl David: Kam mám jíti? Odpověděl: Do Hebronu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 2, 'A protož bral se tam David, ano i obě manželky jeho, Achinoam Jezreelská, a Abigail žena někdy Nábale Karmelského.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 3, 'Muže také své, kteříž s ním byli, pojal David, jednoho každého s čeledí jeho, a bydlili v městech Hebronských.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 4, 'I přišli muži Judští, a pomazali tam Davida za krále nad domem Judským. Oznámili také Davidovi, řkouce: Muži Jábes Galád, oni pochovali Saule.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 5, 'Tedy poslav David posly k mužům Jábes Galád, řekl jim: Požehnaní jste vy před Hospodinem, že jste učinili to milosrdenství pánu svému Saulovi, pochovavše ho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 6, 'Protož nyní učiniž s vámi Hospodin milosrdenství a pravdu; ano i jáť s vámi učiním milost, kteříž jste to učinili.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 7, 'A tak tedy posilňtež rukou svých a buďtež stateční; nebo ač umřel pán váš Saul, však již mne pomazali dům Judův za krále nad sebou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 8, 'Abner pak syn Nerův, hejtman vojska Saulova, vzal Izbozeta syna Saulova a uvedl ho do Mahanaim.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 9, 'A ustavil ho králem nad Galád a nad Assur, a nad Jezreel, a nad Efraimem, a nad Beniaminem, i nade vším Izraelem.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 10, 'Ve čtyřidcíti letech byl Izbozet syn Saulův, když počal kralovati nad Izraelem, a kraloval dvě létě. (Toliko dům Judův přídržel se Davida.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 11, 'A byl počet dnů, v nichž byl David králem v Hebronu nad domem Judovým, sedm let a šest měsíců.)');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 12, 'Potom vytáhl Abner syn Nerův, a služebníci Izbozeta syna Saulova z Mahanaim do Gabaon.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 13, 'Joáb také syn Sarvie a služebníci Davidovi vytáhše, potkali se s nimi právě u rybníka Gabaon. I pozůstali tito u rybníka s strany jedné, oni pak u rybníka s druhé strany.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 14, 'Tedy řekl Abner Joábovi: Nechť vystoupí nyní mládenci a pohrají před námi. I řekl Joáb: Nechť vystoupí.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 15, 'A tak vystoupili a vyšli v rovném počtu, dvanácte z Beniamina, z strany Izbozeta syna Saulova, a dvanácte z služebníků Davidových.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 16, 'Kteřížto ujavše jeden každý za hlavu bližního svého, vrazil meč svůj v bok tovaryše svého, i padli spolu. Protož nazváno jest místo to Helkat Hassurim, a jest v Gabaon.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 17, 'I byla bitva velmi veliká v ten den, a poražen jest Abner i muži Izraelští od služebníků Davidových.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 18, 'Byli tu také tři synové Sarvie: Joáb, Abizai a Azael. Azael pak byl čerstvý na nohy své jako srna v poli.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 19, 'I honil Azael Abnera, a neuhnul se na pravo ani na levo, běže za Abnerem.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 20, 'Ohlédl se pak Abner zpátkem a řekl: Ty-li jsi Azael? Odpověděl: Jsem.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 21, 'Tedy řekl mu Abner: Uchyl se na pravo aneb na levo, a jmi sobě jednoho z mládenců těch, a vezmi sobě kořisti jeho. Ale nechtěl Azael uchýliti se od něho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 22, 'Ještě znovu Abner řekl Azaelovi: Uchyl se ode mne, sic jináč přirazím tě až k zemi, a jak bych směl pohleděti na Joába bratra tvého?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 23, 'Když pak nechtěl ustoupiti, uhodil ho Abner kopím pod páté žebro, tak že vyniklo kopí hřbetem jeho; a padl tu na tom místě, na kterémž i umřel. A kdožkoli přicházeli k místu, na němž padl Azael a umřel, zastavovali se.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 24, 'Ale Joáb a Abizai honili Abnera. Slunce pak již bylo zapadlo, když oni přišli ku pahrbku Amma, jenž jest naproti Giach, cestou k poušti Gabaon.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 25, 'Tedy sešli se synové Beniamin za Abnerem, a jsouce spolu v houfu, postavili se na vrchu pahrbku jednoho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 26, 'Odkudž zavolal Abner na Joába, řka: Zdaliž bez přestání sžírati bude meč tvůj? Nevíš-liž, že hořkost bývá naposledy? Dokudž tedy nerozkážeš lidu navrátiti se od honění bratří svých?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 27, 'I řekl Joáb: Živť jest Bůh, že kdybys byl nemluvil, hned ráno byl by odšel lid, jeden každý nechaje honění bratra svého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 28, 'Tedy zatroubil Joáb v troubu, a zastavil se všecken lid, a nehonili více Izraele, aniž více bojovali.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 29, 'A tak Abner i lid jeho šli přes pole celou tu noc, a přepravili se přes Jordán, a prošedše všecku Betoron, přišli do Mahanaim.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 30, 'Ale Joáb navrátiv se od honění Abnera, shromáždil všecken lid, a nedostávalo se z služebníků Davidových devatenácti mužů a Azaele.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 31, 'Služebníci pak Davidovi zbili z Beniaminských a z mužů Abnerových tři sta a šedesáte mužů, kteříž tu zahynuli.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 32, 'A vzavše Azaele, pohřbili jej v hrobě otce jeho, kterýž byl v Betlémě. Potom šli celou tu noc Joáb a muži jeho; i rozednilo se, když přicházeli do Hebronu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 1, 'I trvala dlouho válka mezi domem Saulovým a domem Davidovým. David pak čím dále tím více se silil, ale dům Saulův čím dále tím se více umenšoval.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 2, 'I zrodili se Davidovi synové v Hebronu, z nichž prvorozený jeho byl Amnon z Achinoam Jezreelské;');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 3, 'A druhý po něm Cheleab z Abigail, ženy někdy Nábale Karmelského; třetí pak Absolon, syn z Maachy dcery Tolmai krále Gessur;');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 4, 'A čtvrtý Adoniáš syn Haggit, a pátý Sefatiáš syn Abitál;');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 5, 'Šestý pak Jetram z Egly manželky Davidovy. Ti se zrodili Davidovi v Hebronu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 6, 'I stalo se, když byla válka mezi domem Saulovým a mezi domem Davidovým, a Abner statečně zastával domu Saulova,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 7, '(Měl pak byl Saul ženinu, jejíž jméno bylo Rizpa, dcera Aja,) že řekl Izbozet Abnerovi: I proč jsi všel k ženině otce mého?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 8, 'Tedy rozhněvav se Abner velmi pro slova Izbozetova, řekl: I zdali já jsem psí hlava, kterýž jsem proti Judovi dnes učinil milosrdenství s domem Saule otce tvého, s bratřími jeho i příbuznými jeho, a nevydal jsem tě v ruku Davidovu, a však vyhledáváš na mně dnes nepravosti té ženy.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 9, 'Toto učiň Bůh Abnerovi a toto mu přidej, jestliže nedopomohu k tomu Davidovi, jakož jemu přisáhl Hospodin,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 10, 'Aby přeneseno bylo království od domu Saulova, a upevněn byl trůn Davidův nad Izraelem i nad Judou, od Dan až do Bersabé.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 11, 'A nemohl k tomu nic více odpovědíti Abnerovi, proto že se ho bál.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 12, 'A tak poslal Abner posly k Davidovi na místě svém, řka: Čí jest země? A aby řekli: Učiň smlouvu se mnou, a aj, ruka má bude s tebou, abych obrátil k tobě všecken Izrael.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 13, 'Jemuž odpověděl: Dobře. Jáť učiním s tebou smlouvu, a však jedné věci od tebe žádám, totiž, abys neviděl tváři mé, leč prvé dáš přivésti Míkol dceru Saulovu, když bys chtěl přijíti, abys viděl tvář mou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 14, 'I poslal David posly k Izbozetovi synu Saulovu, aby řekli: Dej mi ženu mou Míkol, kterouž jsem sobě zasnoubil ve stu obřízek Filistinských.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 15, 'Poslav tedy Izbozet, vzal ji od muže Faltiele syna Lais.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 16, 'Šel pak s ní muž její, a jda za ní až do Bahurim, plakal. Tedy řekl jemu Abner: Jdi, navrať se zase. I navrátil se.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 17, 'Potom Abner učinil řeč k starším Izraelským, řka: Předešle stáli jste o to, aby David byl králem nad vámi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 18, 'Protož nyní vykonejtež to; neboť jest Hospodin mluvil o Davidovi, řka: Skrze ruku Davida služebníka svého vysvobodím lid svůj Izraelský z ruky Filistinských, a z ruky všech nepřátel jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 19, 'To též mluvil Abner i k Beniaminským. Potom odšel Abner, aby mluvil k Davidovi v Hebronu všecko, což se za dobré vidělo Izraelovi a všemu domu Beniamin.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 20, 'Když tedy přišel Abner k Davidovi do Hebronu a s ním dvadceti mužů, učinil David Abnerovi i mužům, kteříž s ním byli, hody.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 21, 'I řekl Abner Davidovi: Vstanu a půjdu, abych shromáždil ku pánu svému králi všecken lid Izraelský, kteříž vejdou s tebou v smlouvu, a budeš kralovati nade všemi, jakož toho žádá duše tvá. I propustil David Abnera, kterýž odšel v pokoji.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 22, 'A aj, služebníci Davidovi a Joáb vraceli se z vojny, kořisti veliké s sebou nesouce. Ale Abnera již nebylo s Davidem v Hebronu, nebo byl ho propustil, a již odšel v pokoji.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 23, 'Joáb tedy i všecko vojsko, kteréž bylo s ním, přišli tam. I oznámili Joábovi, řkouce: Byl zde Abner syn Nerův u krále, ale propustil jej, a odšel v pokoji.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 24, 'Protož všed Joáb k králi, řekl: Co jsi učinil? Aj, přišel byl Abner k tobě; proč jsi ho pustil, aby zase odšel?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 25, 'Znáš Abnera syna Nerova. Proto, aby podvedl tebe, přišel, a aby vyšpehoval vycházení tvé i vcházení tvé, a zvěděl všecko, co ty činíš.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 26, 'Tedy vyšed Joáb od Davida, poslal posly za Abnerem, kteříž ho přivedli zase od čisterny Sírach, o čemž David nic nevěděl.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 27, 'A když se navrátil Abner do Hebronu, uvedl ho Joáb do prostřed brány, aby s ním mluvil tiše. I udeřil ho v páté žebro, a umřel pro krev Azaele bratra jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 28, 'To když potom David uslyšel, řekl: Čist jsem já i království mé před Hospodinem až na věky od krve Abnera syna Nerova.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 29, 'Nechať přijde na hlavu Joábovu i na všecken dům otce jeho, a nechť není prázden dům Joábův toho, jenž by trpěl tok, aneb malomocného a na hůl se podpírajícího, aneb padajícího od meče a nemajícího chleba.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 30, 'A tak Joáb a Abizai bratr jeho zamordovali Abnera, proto že byl zabil Azaele bratra jejich v Gabaon v bitvě.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 31, 'I řekl David Joábovi a ke všemu lidu, kterýž byl s ním: Roztrhněte roucha svá, a přepašte se pytli, a plačte před Abnerem. Král pak David šel za márami.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 32, 'A když pochovávali Abnera v Hebronu, pozdvih král hlasu svého, plakal nad hrobem Abnerovým, plakal také všecken lid.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 33, 'V tom naříkaje král pro Abnera, řekl: Tak-liž jest měl umříti Abner, jako umírá nějaký ničemný člověk?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 34, 'Ruce tvé nebyly svázány a nohy tvé měděnými poutami nebyly sevříny, ale padl jsi jako ten, kdož padá od lidí nešlechetných. Tedy ještě více všecken lid plakal nad ním.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 35, 'Potom přišel všecken lid, a měli k tomu Davida, aby jedl chléb ještě záhý. Ale David přisáhl, řka: Toto ať mi učiní Bůh a toto přidá, jestliže prvé, než slunce zapadne, okusím chleba aneb čehokoli jiného.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 36, 'Což když poznal všecken lid, líbilo se jim to; a všecko, což činil král, líbilo se všemu lidu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 37, 'I poznal všecken lid a všecken Izrael v ten den, že nepošlo to od krále, aby zabili Abnera syna Nerova.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 38, 'Řekl pak král služebníkům svým: Nevíte-liž, že kníže, a veliké, padlo dnes v Izraeli?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 39, 'A já ještě nyní mdlý jsem, jakožto pomazaný král, muži pak tito, synové Sarvie, jsou mi nepovolní. Odplatiž Hospodin tomu, kdož zle činí, vedlé zlosti jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 4, 1, 'A když uslyšel Izbozet syn Saulův, že umřel Abner v Hebronu, zemdlely ruce jeho, a všecken lid Izrael byl předěšen.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 4, 2, 'Měl pak syn Saulův dva muže hejtmany nad dráby, jméno jednoho Baana, a jméno druhého Rechab, synové Remmona Berotského z synů Beniamin; nebo i Berot počítá se v Beniaminovi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 4, 3, 'Utekli pak byli Berotští do Gittaim, a byli tam pohostinu až do toho dne.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 4, 4, 'Měl také byl Jonata syn Saulův syna chromého na nohy, (nebo když byl v pěti letech a přišla pověst o Saulovi a Jonatovi z Jezreel, vzavši ho chůva jeho, utíkala, a když pospíchala utíkajici, on upadl a okulhavěl), jehož jméno Mifibozet.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 4, 5, 'A odšedše synové Remmona Berotského, Rechab a Baana, vešli o poledni do domu Izbozetova. On pak spal na lůžku poledním.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 4, 6, 'A aj, když vešli až do domu, jako by bráti měli obilé, ranili ho v páté žebro, Rechab a Baana bratr jeho, a utekli.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 4, 7, 'Nebo když byli vešli do domu, a on spal na lůžku svém v pokojíku svém, kdež léhal, probodli jej a zabili, a sťavše hlavu jeho, vzali ji, a šli cestou po pustinách celou tu noc.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 4, 8, 'I přinesli hlavu Izbozetovu k Davidovi do Hebronu a řekli králi: Aj, hlava Izbozeta syna Saulova, nepřítele tvého, kterýž hledal bezživotí tvého. Hle, pomstil dnes Hospodin pána mého krále nad Saulem i semenem jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 4, 9, 'Tedy odpovídaje David Rechabovi a Baanovi bratru jeho, synům Remmona Berotského, řekl jim: Živť jest Hospodin, kterýž vysvobodil duši mou ze všech úzkostí,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 4, 10, 'Kdyžť jsem toho, kterýž mi oznámil, řka: Aj, Saul zahynul, (ješto se jemu zdálo, že veselé noviny zvěstuje,) vzal a zabil jsem ho v Sicelechu, jemuž se zdálo, že ho budu darovati za poselství:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 4, 11, 'Čím pak více lidi bezbožné, kteříž zamordovali muže spravedlivého v domě jeho na ložci jeho? A nyní, zdaliž nebudu vyhledávati krve jeho z ruky vaší, a nevyhladím vás z země?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 4, 12, 'I rozkázal David služebníkům, aby je zbili. I zutínali jim ruce i nohy jejich, a pověsili u rybníka při Hebronu. Hlavu pak Izbozetovu vzavše, pochovali v hrobě Abnerově v Hebronu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 1, 'Tehdy přišla všecka pokolení Izraelská k Davidovi do Hebronu, a mluvili, řkouce: Aj, my kost tvá a tělo tvé jsme.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 2, 'A předešlých časů, když byl Saul králem nad námi, ty jsi vyvodil i zase přivodil lid Izraelský. A nadto řekl Hospodin tobě: Ty pásti budeš lid můj Izraelský, a ty budeš vývoda nad Izraelem.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 3, 'Přišli také všickni starší Izraelští k králi do Hebronu, a učinil s nimi král David smlouvu v Hebronu před Hospodinem. I pomazali Davida za krále nad Izraelem.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 4, 'Ve třidcíti letech byl David, když počal kralovati, a kraloval čtyřidceti let.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 5, 'V Hebronu kraloval nad Judou sedm let a šest měsíců, a v Jeruzalémě kraloval třidceti a tři léta nade vším Izraelem a Judou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 6, 'Táhl pak král s lidem svým k Jeruzalému proti Jebuzejskému, obyvateli té země; kterýž mluvil Davidovi, řka: Nevejdeš sem, leč odejmeš slepé a kulhavé, pravíce: Nevejdeť sem David.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 7, 'A však vzal David hrad Sion, toť jest město Davidovo.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 8, 'Nebo řekl David v ten den: Kdož by koli porazil Jebuzea, a zlezl by žlaby jeho, a pobil by ty slepé i chromé, kteréž má v nenávisti duše Davidova, knížetem bude. Protož pravili: Slepý a kulhavý nevejde do toho domu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 9, 'I bydlil David na tom hradě, a nazval jej městem Davidovým; nebo vystavěl je David vůkol od Mello až do vnitřku.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 10, 'A tak David čím dále tím více prospíval a rostl, Hospodin zajisté, Bůh zástupů, byl s ním.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 11, 'Poslal také Chíram král Tyrský posly k Davidovi a dříví cedrového, i tesaře, kameníky a zedníky umělé, kteříž vystavěli dům Davidovi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 12, 'I poznal David, že ho potvrdil Hospodin za krále nad Izraelem, a že zvýšil království jeho pro lid svůj Izraelský.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 13, 'Nabral pak sobě David ještě více ženin i žen z Jeruzaléma, když byl přišel z Hebronu, a naplodilo se Davidovi ještě více synů a dcer.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 14, 'A tato jsou jména těch, kteříž se jemu zrodili v Jeruzalémě: Sammua, Sobab, Nátan a Šalomoun;');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 15, 'Též Ibchar a Elisua, a Nefeg a Jafia;');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 16, 'A Elisama a Eliada a Elifelet.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 17, 'Uslyšavše pak Filistinští, že pomazali Davida za krále nad Izraelem, vytáhli všickni Filistinští hledati ho. Což když zvěděl David, sstoupil na místo hrazené.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 18, 'Protož Filistinští přitáhše, položili se v údolí Refaim.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 19, 'Tedy tázal se David Hospodina, řka: Potáhnu-li proti Filistinským? Vydáš-li je v ruku mou? Odpověděl Hospodin Davidovi: Táhni, neboť vydám jistotně Filistinské v ruku tvou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 20, 'I přitáhl David do Balperazim, a porazil je tam, a řekl: Protrhlť jest Hospodin nepřátely mé přede mnou, jako vody protrhují břehy. Protož nazval jméno místa toho Balperazim.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 21, 'Nebo zanechali tu rytin svých, kteréž pobral David i muži jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 22, 'Opět znovu vytáhli Filistinští, a rozprostřeli se v údolí Refaim.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 23, 'I tázal se David Hospodina. Kterýž odpověděl: Netáhni, ale obejda je po zadu, teprv dotřeš na ně naproti moruším.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 24, 'A když uslyšíš, že šustí vrchové moruší, hneš se také; nebo tehdáž vyjde Hospodin před tebou, aby zbil vojska Filistinských.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 25, 'I učinil David tak, jakž mu přikázal Hospodin, a porazil Filistinské od Gabaa, až kudy se jde do Gázer.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 1, 'Tedy sebral opět David výborného lidu z Izraele třidceti tisíc.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 2, 'A vstav, šel David i všecken lid, kterýž byl s ním, z Bála Judova, aby přinesli odtud truhlu Boží, při kteréž se vzývá jméno, jméno Hospodina zástupů, sedícího nad cherubíny.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 3, 'I vstavili truhlu Boží na nový vůz, vzavše ji z domu Abinadabova, kterýž byl na pahrbku. Uza pak a Achio, synové Abinadabovi, spravovali ten vůz nový.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 4, 'A tak vzali ji z domu Abinadabova, kterýž byl na pahrbku, jdouce s truhlou Boží; Achio pak šel před truhlou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 5, 'Ale David i všecken dům Izraelský hrali před Hospodinem na všelijaké nástroje z dříví cedrového, totiž na harfy, loutny, bubny, husličky, a na cymbály.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 6, 'A když přišli k humnu Náchonovu, vztáhl ruku svou Uza k truhle Boží a pozdržel jí, nebo uchýlili se volové.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 7, 'Protož rozhněval se Hospodin na Uzu, a zabil ho Bůh pro neprozřetelnost; i umřel tu u truhly Boží.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 8, 'Tedy zkormoutil se David, proto že se Hospodin tak přísně obořil na Uzu. I nazváno to místo Peres Uza až do tohoto dne.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 9, 'A boje se David Hospodina v ten den, řekl: Kterakž má vjíti ke mně truhla Hospodinova?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 10, 'Pročež David nechtěl přenésti k sobě truhly Hospodinovy do města svého, ale způsobil to, aby se obrátila do domu Obededoma Gittejského.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 11, 'I pobyla truhla Hospodinova v domě Obededoma Gittejského za tři měsíce, a požehnal Hospodin Obededomovi i všemu domu jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 12, 'V tom povědíno jest králi Davidovi, že požehnal Hospodin domu Obededomovu i všemu, což má, pro truhlu Boží. Tedy odšed David, přenesl truhlu Boží z domu Obededomova do města Davidova s veselím.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 13, 'A když poodešli ti, kteříž nesli truhlu Hospodinovu, na šest kroků, obětoval voly a tučný dobytek.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 14, 'David pak poskakoval ze vší síly před Hospodinem, a byl oblečen David v efod lněný.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 15, 'A tak David i všecken dům Izraelský provázeli truhlu Hospodinovu s plésáním a zvukem trouby.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 16, 'Stalo se pak, když truhla Hospodinova vcházela do města Davidova, že Míkol dcera Saulova vyhlídala z okna, a viduci krále Davida plésajícího a poskakujícího před Hospodinem, pohrdla jím v srdci svém.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 17, 'A když přinesli truhlu Hospodinovu, postavili ji na místě jejím u prostřed stanu, kterýž jí byl David rozbil; a obětoval David před Hospodinem oběti zápalné i pokojné.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 18, 'Zatím když přestal David obětovati obětí zápalných a pokojných, dal požehnání lidu ve jménu Hospodina zástupů.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 19, 'Dal také všemu lidu a všemu množství Izraelskému, od muže až do ženy, jednomu každému jeden pecník chleba a kus masa, a vína láhvici jednu. I odšel všecken lid, jeden každý do domu svého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 20, 'Potom navracoval se David, aby dal požehnání domu svému. I vyšla Míkol dcera Saulova vstříc Davidovi, a řekla: Jak slavný byl dnes král Izraelský, kterýž se odkrýval dnes před děvkami služebníků svých, tak jako se odkrývá jeden z lehkomyslných!');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 21, 'I řekl David k Míkol: Před Hospodinem, (kterýž mne vyvolil nad otce tvého a nad všecken dům jeho, přikázav mi, abych byl vývodou lidu Hospodinova, totiž Izraele,) plésal jsem a plésati budu před Hospodinem.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 22, 'Anobrž čím se ještě více opovrhu nežli tuto, a ponížím se u sebe sám, tím i u těch děvek, o nichž jsi mluvila, i u těch, pravím, slavnější budu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 23, 'Protož Míkol dcera Saulova neměla žádného plodu až do dne smrti své.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 1, 'I stalo se, že když král seděl v domě svém, a Hospodin jemu dal odpočinutí vůkol přede všemi nepřátely jeho,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 2, 'Řekl král Nátanovi proroku: Pohleď medle, já bydlím v domě cedrovém, truhla pak Boží přebývá mezi kortýnami.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 3, 'I dí Nátan králi: Cožkoli jest v srdci tvém, jdi, učiň, nebo Hospodin s tebou jest.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 4, 'Potom té noci stalo se slovo Hospodinovo k Nátanovi, řkoucí:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 5, 'Jdi a pověz služebníku mému Davidovi: Takto praví Hospodin: Zdaliž ty mi stavěti budeš dům, v kterémž bych přebýval?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 6, 'Poněvadž jsem nebydlil v domě od toho dne, jakž jsem vyvedl syny Izraelské z Egypta, až do dne tohoto, ale přecházel jsem s stánkem a příbytkem sem i tam.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 7, 'Nadto kudyž jsem koli chodil se všechněmi syny Izraelskými, zdali jsem jedno slovo řekl kterému z soudců Izraelských, kterémuž jsem přikázal pásti lid svůj Izraelský, řka: Proč jste mi neustavěli domu cedrového?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 8, 'Protož nyní toto díš služebníku mému Davidovi: Takto praví Hospodin zástupů: Jáť jsem tě vzal z ovčince od stáda, abys byl vývodou lidu mého Izraelského.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 9, 'A býval jsem s tebou všudy, kamž jsi koli se obracel; všecky také nepřátely tvé vyhladil jsem před tváří tvou, a učinil jsem tobě jméno veliké, jako jméno vyvýšených na zemi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 10, 'Způsobím tolikéž místo lidu svému Izraelskému, a vštípím jej, a bydliti bude v místě svém a nepohne se více, aniž ho budou více trápiti lidé nešlechetní jako prvé,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 11, 'Hned od toho dne, jakž jsem ustanovil soudce nad lidem svým Izraelským, až jsem teď dal odpočinutí tobě přede všemi nepřátely tvými. Přesto oznamujeť Hospodin, že on sám tobě dům vzdělá.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 12, 'Když se vyplní dnové tvoji, a usneš s otci svými, vzbudím símě tvé po tobě, kteréž vyjde z života tvého, a utvrdím království jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 13, 'Onť ustaví dům jménu mému, a já utvrdím trůn království jeho až na věky.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 14, 'Já budu jemu otcem, a on mi bude synem. Kterýž když zhřeší, trestati ho budu metlou lidskou a ranami synů lidských.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 15, 'Ale milosrdenství mé nebude odjato od něho, tak jako jsem je odjal od Saule, kteréhož jsem zahnal od tváři tvé.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 16, 'A tak utvrzen bude dům tvůj a království tvé až na věky před tebou, a trůn tvůj bude stálý až na věky.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 17, 'Vedlé všech slov těchto, a podlé všeho vidění tohoto, tak mluvil Nátan Davidovi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 18, 'Tedy všed král David, posadil se před Hospodinem a řekl: Kdo jsem já, Panovníče Hospodine, a jaký jest dům můj, že jsi mne přivedl v ta místa.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 19, 'Nýbrž ještěť se to málo vidělo, Panovníče Hospodine, že jsi také mluvil i o domu služebníka svého na dlouhé časy, ješto jest to povaha lidská, Panovníče Hospodine.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 20, 'Ale což již více má mluviti David před tebou? Však ty znáš služebníka svého, Panovníče Hospodine.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 21, 'Pro slovo své a podlé srdce svého činíš všecky tyto věci veliké, v známost je uvodě služebníku svému.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 22, '(Protož zveleben jsi Hospodine Bože, nebo není tobě rovného, anobrž není žádného Boha kromě tebe,) podlé toho všeho, jakž jsme slýchali ušima svýma.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 23, 'Kdo tedy jest jako lid tvůj, jako Izrael, který národ na zemi, jehož by Bůh šel, aby jej sobě vykoupil za lid, a dobyl sobě jména, a učinil tobě, ó Izraeli, tyto veliké věci a hrozné v zemi tvé, před oblíčejem lidu svého, kterýž jsi sobě vysvobodil z Egypta, z pohanstva bohů jejich?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 24, 'A vzdělal jsi sobě lid svůj Izraelský, sobě v lid až na věky, a protož, Hospodine, jsi jejich Bohem.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 25, 'Nyní tedy, Hospodine Bože, slovo to, jímž jsi se zamluvil služebníku svému a domu jeho, naplniž je až na věky, a učiň tak, jakž jsi mluvil,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 26, 'Tak aby zvelebováno bylo jméno tvé až na věky, když se říkati bude: Hospodin zástupů jest Bůh nad Izraelem, a dům služebníka tvého Davida aby byl stálý před oblíčejem tvým.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 27, 'Nebo ty, Hospodine zástupů, Bože Izraelský, zjevil jsi mně služebníku svému, řka: Dům ustavím tobě. Protož usoudil služebník tvůj v srdci svém, aby se modlil tobě modlitbou touto.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 28, 'A tak již, Panovníče Hospodine, ty sám jsi Bůh, a slova tvá jsou pravda, jimiž jsi zaslíbil služebníku svému dobré věci tyto.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 29, 'Již tedy rač požehnati domu služebníka svého, aby trval na věky před oblíčejem tvým. Nebo ty jsi, Hospodine Bože, mluvil, že požehnáním tvým požehnán bude dům služebníka tvého na věky.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 1, 'Stalo se potom, že porazil David Filistinské, a zemdlil je; i vzal David Meteg Amma z ruky Filistinských.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 2, 'Porazil také Moábské a změřil je provazcem, na zemi je rozprostíraje; a odměřil jich dva provazce k zbití a celý provazec k živení. I učiněni jsou Moábští Davidovi služebníci, a dávali jemu plat.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 3, 'Porazil též David Hadadezera syna Rohobova, krále Soba, když byl vytáhl, aby rozšířil končiny své až k řece Eufraten.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 4, 'A pobral mu David tisíc vozů a sedm set jezdců, a dvadceti tisíc mužů pěších, a zpodřezoval David žily všechněm koňům vozníkům; toliko zanechal z nich ke stu vozům.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 5, 'Přitáhli pak byli Syrští od Damašku na pomoc Hadadezerovi králi Soba, ale David porazil z Syrských dvamecítma tisíc mužů.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 6, 'Tedy osadil David stráží Syrii Damašskou, a byli Syrští služebníci Davidovi, dávajíce plat; nebo zachovával Hospodin Davida, kamžkoli se obrátil.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 7, 'Pobral také David štíty zlaté, kteréž měli služebníci Hadadezerovi, a přinesl je do Jeruzaléma.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 8, 'Z Betach též a z Berot, měst Hadadezerových, nabral král David velmi mnoho mědi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 9, 'A když uslyšel Tohi král Emat, že porazil David všecko vojsko Hadadezerovo,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 10, 'Poslal Tohi Jorama syna svého k králi Davidovi, aby ho pozdravil přátelsky, a spolu s ním se radoval z toho, že šťastně bojoval s Hadadezerem, a porazil ho; (nebo Hadadezer vedl válku proti Tohi). Kterýžto přinesl s sebou nádoby stříbrné, též nádoby zlaté a nádoby měděné.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 11, 'Ty také obětoval král David Hospodinu s stříbrem a zlatem posvěceným ze všech národů, kteréž podmanil,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 12, 'Totiž z Syrských a Moábských, též z synů Ammon a z Filistinských, i z Amalechitských a z kořistí Hadadezera syna Rohobova, krále Soba.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 13, 'Zvelebil také David své jméno, když se navracoval od pobití osmnácti tisíců Syrských v údolí solnatém.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 14, 'Protož i nad Idumejskými stráž postavil, všecku krajinu Idumejskou stráží osadiv. I učiněni jsou všickni Idumejští služebníci Davidovi; nebo zachovával Hospodin Davida, kamž se koli obrátil.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 15, 'I kraloval David nade vším Izraelem, a činil David soud a spravedlnost všemu lidu svému.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 16, 'Joáb pak syn Sarvie byl nad vojskem, a Jozafat syn Achiludův kancléřem;');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 17, 'Sádoch také syn Achitobův a Achimelech syn Abiatarův kněžími, a Saraiáš písařem.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 18, 'Benaiáš pak syn Joiadův byl nad Cheretejskými a Peletejskými, a synové Davidovi knížaty.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 9, 1, 'Tedy řekl David: Jest-li ještě kdo pozůstalý z domu Saulova, abych jemu učinil milosrdenství pro Jonatu?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 9, 2, 'Byl pak služebník domu Saulova, jehož jméno bylo Síba. I zavolali ho k Davidovi. I řekl král jemu: Ty-li jsi Síba? Odpověděl: Jsem služebník tvůj.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 9, 3, 'Řekl jemu král: Jest-liž ještě kdo z domu Saulova, abych jemu učinil milosrdenství Boží? Odpověděl Síba králi: Ještě jest syn Jonatův chromý na nohy.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 9, 4, 'I řekl jemu král: Kdež jest? Odpověděl Síba králi: Tam jest v domě Machiry, syna Amielova v Lodebar.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 9, 5, 'Protož poslav král David, vzal ho z domu Machiry, syna Amielova z Lodebar.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 9, 6, 'A když přišel Mifibozet syn Jonaty, syna Saulova, k Davidovi, padl na tvář svou a poklonil se. I řekl David: Mifibozete. Kterýž odpověděl: Aj, služebník tvůj.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 9, 7, 'Řekl jemu David: Neboj se, nebo jistě učiním s tebou milosrdenství pro Jonatu otce tvého, a navrátím tobě všecka pole Saule otce tvého, a ty jídati budeš za stolem mým vždycky.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 9, 8, 'Kterýž pokloniv se, řekl: Co jest služebník tvůj, že jsi se ohlédl na psa mrtvého, jakýž jsem já?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 9, 9, 'Zatím povolal král Síby, služebníka Saulova a řekl jemu: Cožkoli měl Saul i všecka čeled jeho, to jsem dal synu pána tvého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 9, 10, 'Budeš tedy jemu spravovati rolí, ty i synové tvoji i služebníci tvoji, a snášeti budeš, aby měl syn pána tvého pokrm, kterýž by jedl, ale Mifibozet syn pána tvého jídati bude vždycky za stolem mým. (Měl pak Síba patnácte synů a dvadceti služebníků.)');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 9, 11, 'Odpověděl Síba králi: Vedlé všeho, jakž přikázal pán můj král služebníku svému, tak učiní služebník tvůj, ačkoli i Mifibozet mohl by jídati za stolem mým jako jeden z synů královských.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 9, 12, 'Měl také Mifibozet syna malého, jemuž jméno bylo Mícha; a všickni, kteříž bydlili v domě Síbově, byli za služebníky Mifibozetovi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 9, 13, 'A tak Mifibozet zůstával v Jeruzalémě, proto že vždycky za stolem královským jídal; a byl kulhavý na obě noze.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 1, 'Stalo se také potom, že umřel král Ammonitský, a kraloval Chanun syn jeho po něm.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 2, 'I řekl David: Učiním milosrdenství s Chanunem synem Náhasovým, jakož otec jeho učinil milosrdenství nade mnou. Tedy poslal David, aby ho potěšil skrze služebníky své pro otce jeho. I přišli služebníci Davidovi do země Ammonitských.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 3, 'I řekla knížata Ammonitská k Chanunovi, pánu svému: Cožť se zdá, že David činí poctivost otci tvému, že poslal k tobě, kteříž by tě potěšili? Zdaliž ne proto, aby shlédl město a vyšpehoval je, a potom je podvrátil, poslal David služebníky své k tobě?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 4, 'A tak Chanun vzav služebníky Davidovy, oholil každému půl brady, a zustřihoval roucha jejich až do polovice, totiž až do zadků jejich, a propustil je.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 5, 'To když oznámili Davidovi, poslal proti nim, (nebo muži ti zohaveni byli velice,) a řekl jim král: Pobuďte v Jerichu, dokudž neobrostou brady vaše, potom se navrátíte.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 6, 'Vidouce pak Ammonitští, že se zošklivili Davidovi, poslavše, najali ze mzdy z Syrie z domu Rohob, a z Syrie Soba dvadcet tisíců pěších, a od krále Maacha tisíc mužů, a od Istoba dvanácte tisíc mužů.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 7, 'Což uslyšev David, poslal Joába se vším vojskem udatných.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 8, 'A tak vytáhše Ammonitští, šikovali se k boji u brány, Syrští také, Soba a Rohob, a Istob i Maacha zvláště byli na poli.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 9, 'A protož vida Joáb proti sobě sšikovaný boj s předu i s zadu, vybrav některé ze všech výborných Izraelských, sšikoval je také proti Syrským.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 10, 'Ostatek pak lidu dal pod správu Abizai bratra svého, a sšikoval jej proti Ammonitským.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 11, 'A řekl: Jestliže Syrští budou silnější mne, přispěješ mi na pomoc; jestliže pak Ammonitští silnější budou tebe, také přispěji, abych pomohl tobě.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 12, 'Posiliž se, a buďme udatní, bojujíce za lid náš a za města Boha našeho, Hospodin pak učiní, což se jemu dobře líbiti bude.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 13, 'I přistoupil Joáb s lidem svým k bitvě proti Syrským, a oni utekli před ním.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 14, 'Tedy Ammonitští vidouce, že utíkají Syrští, utekli i oni před Abizai a vešli do města. I navrátil se Joáb od Ammonitských a přišel do Jeruzaléma.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 15, 'Ale Syrští vidouce, že by poraženi byli od Izraele, sebrali se vespolek.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 16, 'Poslal také Hadarezer a vyvedl Syrské, kteříž bydlejí za řekou, a přišli k Helam; Sobach pak, hejtman vojska Hadarezerova, vedl je.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 17, 'I oznámeno to Davidovi. Kterýžto shromáždiv všecken lid Izraelský, přepravil se přes Jordán, a přitáhli k Helam. I sšikovali se Syrští proti Davidovi, a bojovali proti němu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 18, 'Tedy utekli Syrští před Izraelem, a porazil David z Syrských sedm set vozů a čtyřidceti tisíc jezdců. Sobacha také hejtmana vojska toho ranil, i umřel tu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 19, 'Když pak viděli všickni králové, kteříž byli při Hadarezerovi, že jsou poraženi od Izraele, vešli v pokoj s Izraelem a sloužili jemu. A nesměli již více Syrští táhnouti na pomoc Ammonitským.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 1, 'I stalo se po roce, když králové vyjíždívají na vojnu, že poslal David Joába a služebníky své s ním, též i všecken Izrael, aby hubili Ammonitské; i oblehli Rabba. David pak zůstal v Jeruzalémě.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 2, 'Tedy stalo se k večerou, když vstal David s ložce svého, procházeje se po paláci domu královského, že uzřel s paláce ženu, ana se myje; kterážto žena byla vzezření velmi krásného.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 3, 'A poslav David, vyptal se o té ženě a řekl: Není-liž to Betsabé dcera Eliamova, manželka Uriáše Hetejského?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 4, 'Opět poslal David posly a vzal ji. Kterážto když vešla k němu, obýval s ní; (nebo se byla očistila od nečistoty své). Potom navrátila se do domu svého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 5, 'I počala žena ta. Protož poslavši, oznámila Davidovi, řkuci: Těhotná jsem.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 6, 'Poslav pak David, vzkázal Joábovi: Pošli ke mně Uriáše Hetejského. I poslal Joáb Uriáše k Davidovi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 7, 'A když přišel Uriáš k němu, otázal se ho, jak se má Joáb, a jak se má lid, a kterak se vede v vojště?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 8, 'Řekl také David Uriášovi: Jdiž do domu svého, a umyj sobě nohy. I vyšel Uriáš z domu králova, a poslán za ním dar královský.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 9, 'Ale Uriáš spal u vrat domu královského se všemi služebníky pána svého, a nešel do domu svého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 10, 'Což když oznámili Davidovi, řkouce: Nešel Uriáš do domu svého, řekl David Uriášovi: Však jsi z cesty přišel. Pročež jsi nešel do domu svého?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 11, 'Odpověděl Uriáš Davidovi: Truhla Boží a Izrael i Juda zůstávají v staních, a pán můj Joáb i služebníci pána mého na poli zůstávají, já pak mám vjíti do domu svého, abych jedl a pil, a spal s manželkou svou? Jakož jsi živ ty, a jako jest živa duše tvá, žeť toho neučiním.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 12, 'Tedy řekl David Uriášovi: Pobuď zde ještě dnes, a zítra propustím tebe. I zůstal Uriáš v Jeruzalémě toho dne i nazejtří.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 13, 'V tom pozval ho David, aby jedl před ním a pil, a opojil ho. A však on šel večer spáti na ložce své s služebníky pána svého, a nešel do domu svého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 14, 'A když bylo ráno, napsal David list Joábovi, kterýž poslal po Uriášovi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 15, 'Psal pak v listu těmi slovy: Postavte Uriáše proti bojovníkům nejsilnějším; mezi tím odstupte nazpět od něho, aby raněn jsa, umřel.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 16, 'I stalo se, když oblehl Joáb město, že postavil Uriáše proti místu, kdež věděl, že jsou nejsilnější muži.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 17, 'A vyskočivše muži z města, bojovali proti Joábovi. I padli někteří z lidu, z služebníků Davidových, také i Uriáš Hetejský zabit.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 18, 'Tedy poslav Joáb, oznámil Davidovi všecko, což se zběhlo v bitvě.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 19, 'A přikázal tomu poslu, řka: Když vypravíš králi všecky věci, které se zběhly v bitvě,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 20, 'Při čemž jestliže se popudí prchlivost královská a řekne-liť: Proč jste přistoupili k městu, bojujíce? Zdaliž jste nevěděli, že házejí se zdi?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 21, 'Kdo zabil Abimelecha syna Jerobosetova? Zdali ne žena, svrhši na něj kus žernovu se zdi, tak že umřel v Tébes? Proč jste přistupovali ke zdi? tedy díš: Také služebník tvůj Uriáš Hetejský umřel.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 22, 'A tak šel posel, a přišed, oznámil Davidovi všecko to, pročež ho byl poslal Joáb.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 23, 'A řekl posel ten Davidovi: Zmocnili se nás muži ti, a vytrhli proti nám do pole, a honili jsem je až k bráně.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 24, 'V tom stříleli střelci na služebníky tvé se zdi, a zbiti jsou někteří z služebníků králových, také i služebník tvůj Uriáš Hetejský zabit.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 25, 'Tedy řekl David poslu: Tak pověz Joábovi: Nic tě to nerozpakuj, že tak i jinak sehlcuje meč. Ztuž boj svůj proti městu a zkaz je, a potěš drábů.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 26, 'Uslyševši pak manželka Uriášova, že umřel Uriáš muž její, plakala manžela svého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 27, 'A když pominul pláč, poslav David, vzal ji do domu svého, a měl ji za manželku; i porodila mu syna. Ale nelíbilo se to Hospodinu, co učinil David.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 1, 'Protož poslal Hospodin Nátana k Davidovi. Kterýž přišed k němu, řekl jemu: Dva muži byli v městě jednom, jeden bohatý a druhý chudý.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 2, 'Bohatý měl ovec i volů velmi mnoho,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 3, 'Chudý pak neměl nic, kromě jednu ovečku malou, kterouž byl koupil a choval, až i odrostla při něm a při dětech jeho tolikéž. Chléb jeho jedla a z číše jeho pila, a v lůnu jeho spávala, a tak byla mu jako za dceru.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 4, 'Když pak přišel pocestný k tomu bohatému člověku, líto mu bylo vzíti z ovcí aneb z volů svých, což by připravil pocestnému, kterýž k němu přišel, ale vzav ovečku toho chudého člověka, připravil ji muži, kterýž byl přišel k němu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 5, 'Tedy rozhněval se David na muže toho náramně a řekl Nátanovi: Živť jest Hospodin, že hoden jest smrti muž, kterýž to učinil.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 6, 'Ovečku také tu zaplatí čtvernásobně, proto že učinil věc tu, a nelitoval ho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 7, 'I řekl Nátan Davidovi: Ty jsi ten muž! Takto praví Hospodin Bůh Izraelský: Já jsem tě pomazal, abys králem byl nad Izraelem, a vytrhl jsem tebe z ruky Saulovy.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 8, 'A dal jsem tobě dům pána tvého, i ženy pána tvého v lůno tvé, dalť jsem také dům Izraelský a Judský, a bylo-liť by to málo, byl bych přidal mnohem více.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 9, 'Pročež jsi sobě zlehčil slovo Hospodinovo, čině to, což se nelíbí jemu? Uriáše Hetejského zabil jsi mečem, a manželku jeho pojals sobě za ženu, samého pak zamordoval jsi mečem Ammonitských.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 10, 'Protož nyní neodejdeť meč z domu tvého až na věky, proto že jsi pohrdl mnou, a vzal jsi manželku Uriáše Hetejského, aby byla žena tvá.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 11, 'Takto praví Hospodin: Aj, já vzbudím proti tobě zlé z domu tvého, a vezma ženy tvé před očima tvýma, dám je bližnímu tvému, kterýž spáti bude s ženami tvými, an na to každý hledí.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 12, 'A ačkoli ty učinil jsi to tajně, já však učiním to zjevně přede vším Izraelem a všechněm známě.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 13, 'Tedy řekl David Nátanovi: Zhřešilť jsem Hospodinu. Zase řekl Nátan Davidovi: Tentýž Hospodin přenesl hřích tvůj, neumřeš.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 14, 'Ale však, poněvadž jsi tou věcí dal příčinu nepřátelům Hospodinovým, aby se rouhali, protož ten syn, kterýž se narodil tobě, jistotně umře.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 15, 'Potom odšel Nátan do domu svého. V tom Hospodin ranil dítě, kteréž byla porodila manželka Uriášova Davidovi, tak že pochybili o něm.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 16, 'I modlil se David Bohu za to dítě a postil se, a všed, ležel přes noc na zemi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 17, 'A ačkoli starší domu jeho přišli k němu, aby ho zdvihli z země, on však nechtěl, aniž s nimi co jedl.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 18, 'Stalo se pak dne sedmého, že umřelo dítě. I nesměli služebníci Davidovi toho oznámiti jemu, že by umřelo dítě; nebo pravili: Aj, když ještě bylo dítě živo, mluvili jsme jemu, a nechtěl slyšeti hlasu našeho, což pak když jemu díme: Umřelo dítě. Ovšem to tíže ponese.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 19, 'Ale vida David, an služebníci jeho k sobě šepcí, srozuměl, že by umřelo dítě. I řekl David služebníkům svým: Co již umřelo dítě? Kteříž řekli: Umřelo.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 20, 'Tedy vstav David s země, umyl se a pomazal se, a změnil roucho své, a všed do domu Hospodinova, pomodlil se. Potom vrátiv se do domu svého, rozkázal sobě dáti jísti a jedl.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 21, 'Služebníci pak jeho řekli jemu: Co jsi to učinil? Pro dítě, když živo bylo, postils se a plakal, ale jakž dítě umřelo, vstal jsi a přijal jsi pokrm.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 22, 'Kterýžto řekl: Pokudž ještě dítě živo bylo, postil jsem se a plakal, nebo jsem řekl: Kdo ví? Můžeť se smilovati nade mnou Hospodin, aby živo bylo dítě.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 23, 'Nyní pak, poněvadž umřelo, proč se mám postiti? Zdaliž budu moci zase je vzkřísiti? Jáť půjdu k němu, ale ono se nenavrátí ke mně.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 24, 'Potom David potěšiv Betsabé manželky své, všel k ní a spal s ní. I porodila syna, a nazval jméno jeho Šalamoun, a Hospodin miloval jej.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 25, 'Protož poslal byl Nátana proroka, a nazval jméno jeho Jedidiah pro Hospodina.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 26, 'Bojoval pak Joáb proti Rabba Ammonitských, a vzal město královské.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 27, 'A poslav posly k Davidovi, řekl: Dobýval jsem Rabba a vzal jsem město vod.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 28, 'Protož nyní sebera ostatek lidu, polož se proti městu a vezmi je, abych já nevzal města toho, a bylo by mně připisováno vítězství nad ním.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 29, 'Tedy sebrav David všecken lid, vytáhl proti Rabba, kteréhož dobýval a vzal je.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 30, 'A sňal korunu krále jejich s hlavy jeho, kteráž vážila centnéř zlata, a bylo v ní kamení drahé, a vstavena byla na hlavu Davidovu. Vyvezl též kořisti města velmi veliké.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 31, 'Lid pak, kterýž v něm byl, vyvedl a dal jej pod pily a pod brány železné a pod sekery železné, a vehnal je do peci cihelné. A tak činil všechněm městům Ammonitským. Potom navrátil se David se vším lidem do Jeruzaléma.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 1, 'I stalo se potom, že Absolon syn Davidův měl sestru krásnou, jménem Támar; i zamiloval ji Amnon syn Davidův.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 2, 'A tak se o to trápil Amnon, že i v nemoc upadl pro Támar sestru svou; nebo panna byla, a viděl Amnon, že nesnadně bude jí moci co učiniti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 3, 'Měl pak Amnon přítele, jehož jméno bylo Jonadab, syn Semmaa bratra Davidova, kterýžto Jonadab byl muž velmi chytrý.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 4, 'I řekl jemu: Proč tak chřadneš, synu králův, den ode dne? Neoznámíš-liž mi? I řekl mu Amnon: Támar sestru Absolona bratra svého miluji.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 5, 'Tedy řekl jemu Jonadab: Polož se na lůže své a udělej se nemocným, a když přijde otec tvůj, aby tě navštívil, díš jemu: Nechť přijde, prosím, Támar sestra má a dá mi jísti, připravíc před očima mýma pokrm, abych viděl a jedl z ruky její.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 6, 'A tak složil se Amnon, dělaje se nemocným. A když přišel král, aby ho navštívil, řekl Amnon králi: Nechť přijde, prosím, Támar sestra má a připraví před očima mýma asi dvě krmičky, abych pojedl z ruky její.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 7, 'Protož poslal David k Támar do domu, řka: Jdi hned do domu Amnona bratra svého a připrav mu krmičku.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 8, 'I šla Támar do domu Amnona bratra svého; on pak ležel. A vzavši mouky, zadělala ji, a připravivši krmičku před očima jeho, uvařila ji.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 9, 'Potom vzavši pánvici, vyložila před něj, a on nechtěl jísti. (I řekl Amnon: Spravte to, ať vyjdou všickni ven. I vyšli od něho všickni.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 10, 'Řekl pak Amnon k Támar: Přines tu krmičku do pokojíka, abych pojedl z ruky tvé. A vzavši Támar krmičku, kterouž připravila, přinesla ji před Amnona bratra svého do pokojíka.)');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 11, 'Ale když mu podávala, aby jedl, uchopil ji a řekl jí: Poď, lež se mnou, sestro má.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 12, 'Kterážto řekla jemu: Nikoli, bratře můj, nečiň mi násilí, nebo ne tak se má díti v Izraeli. Neprovoď nešlechetnosti této.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 13, 'Nebo já na koho svedu pohanění své? Ty pak budeš jako jeden z nejnešlechetnějších v Izraeli. Raději tedy mluv medle s králem, nebo neodepřeť mne tobě.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 14, 'Ale nechtěl uposlechnouti hlasu jejího, nýbrž zmocniv se jí, učinil jí násilí a ležel s ní.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 15, 'Potom vzal ji Amnon v nenávist velikou velmi, tak že větší byla nenávist, kterouž nenáviděl jí, než milost, kterouž ji miloval. I řekl jí Amnon: Vstaň a jdi pryč.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 16, 'Kterážto odpověděla jemu: Za příčinou převelmi zlé věci té, kterouž jsi při mně spáchal, druhé horší se dopouštíš, že mne vyháníš. On pak nechtěl jí slyšeti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 17, 'Ale zavolav mládence, kterýž mu přisluhoval, řekl: Vyveď hned tuto ode mne ven, a zamkni dvéře po ní.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 18, '(Měla pak na sobě sukni proměnných barev, nebo v takových sukních chodívaly dcery královské panny.) A tak vyvedl ji ven služebník jeho a zamkl dvéře po ní.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 19, 'Tedy posypala Támar hlavu svou popelem, a sukni proměnných barev, kterouž měla na sobě, roztrhla; a vložila ruku na hlavu svou, a jduc, křičela s naříkáním.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 20, 'I řekl jí Absolon bratr její: Nebyl-liž Amnon bratr tvůj s tebou? Ale nyní, sestro má mlč; bratr tvůj jest, nepřipouštěj toho k srdci. A tak zůstala Támar, jsuc opuštěná, v domě Absolona bratra svého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 21, 'A uslyšev král David o těch všech věcech, rozhněval se náramně.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 22, 'Absolon pak nic nemluvil s Amnonem, ani dobrého ani zlého; nebo nenáviděl Absolon Amnona, proto že učinil násilí Támar sestře jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 23, 'I stalo se po celých dvou letech, když střihli ovce Absolonovi v Balazor, jenž jest podlé Efraim, že pozval Absolon všech synů královských.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 24, 'Nebo přišel Absolon k králi a řekl: Aj, nyní služebník tvůj má střižce; nechť, prosím, jde král a služebníci jeho s služebníkem tvým.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 25, 'I řekl král Absolonovi: Nechť, synu můj, nechť nyní nechodíme všickni, abychom tě neobtěžovali. A ačkoli nutkal ho, však nechtěl jíti, ale požehnal mu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 26, 'Řekl ještě Absolon: Nechť aspoň s námi jde, prosím, Amnon bratr můj. Odpověděl jemu král: Proč by s tebou šel?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 27, 'A když vždy dotíral Absolon, poslal s ním Amnona i všecky syny královské.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 28, 'Přikázal pak byl Absolon služebníkům svým, řka: Šetřte medle, když se rozveselí srdce Amnonovo vínem, a řeknu vám: Bíte Amnona, tedy zabíte jej. Nebojte se nic, nebo zdaliž jsem já nerozkázal vám? Posilňte se a mějte se zmužile.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 29, 'I učinili Amnonovi služebníci Absolonovi, jakž jim byl přikázal Absolon. Pročež vstavše všickni synové královi, vsedli jeden každý na mezka svého a utekli.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 30, 'V tom když ještě byli na cestě, přišla taková pověst k Davidovi: Pobil Absolon všecky syny královské, tak že z nich ani jednoho nezůstalo.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 31, 'Tedy vstav král, roztrhl roucha svá a ležel na zemi; všickni také služebníci jeho stáli, roztrhše roucha.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 32, 'Ozval se pak Jonadab, syn Semmaa bratra Davidova, a řekl: Nepraviž toho, pane můj, jako by všecky mládence syny královy zbili, ale Amnon toliko zabit; nebo tak v úmysle Absolonově složeno bylo od toho dne, jakž on byl učinil násilí Támar sestře jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 33, 'Protož nechať nepřipouští toho nyní pán můj král k srdci svému, mysle, že by všickni synové královi zbiti byli; nebo Amnon toliko umřel.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 34, 'Absolon pak utekl. Tedy pozdvih služebník hlásný očí svých, uzřel, an mnoho lidu jde odtud, kudyž se chodilo k němu cestou pod horami.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 35, 'I řekl Jonadab králi: Aj, synové královští přijíždějí. Vedlé řeči služebníka tvého tak se stalo.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 36, 'A když přestal mluviti, aj, synové královští přišli, a pozdvihše hlasu svého, plakali; též také král i všickni služebníci jeho plakali pláčem velmi velikým.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 37, 'Absolon pak utekl a ušel k Tolmai synu Amiudovu, králi Gessur. I plakal David syna svého po všecky ty dny.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 38, 'Absolon tedy utíkaje, přišel do Gessur, a byl tam tři léta.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 39, 'Potom žádal David vyjíti k Absolonovi, nebo již byl oželel smrti Amnonovy.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 1, 'Srozuměv pak Joáb syn Sarvie, že by naklonilo se srdce královo k Absolonovi,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 2, 'Poslav do Tekoa, a povolav odtud ženy moudré, řekl jí: Medle, udělej se, jako bys zámutek měla, a oblec se, prosím, v roucho smutku, a nepomazuj se olejem, ale buď jako žena již za mnoho dní zámutek mající nad mrtvým.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 3, 'I půjdeš k králi a mluviti mu budeš vedlé řeči této. A naučil ji Joáb, co by měla mluviti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 4, 'Protož mluvila žena ta Tekoitská králi, padši na tvář svou k zemi, a poklonu učinivši, řekla: Spomoz, ó králi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 5, 'I řekl jí král: Což jest tobě? Odpověděla ona: Zajisté žena vdova jsem, a umřel mi muž můj.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 6, 'Měla pak služebnice tvá dva syny, kteříž svadili se spolu na poli, a když nebyl, kdo by je rozvadil, udeřil jeden druhého a zabil ho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 7, 'Aj, teď povstala všecka rodina proti služebnici tvé, a řekli: Vydej toho, jenž zabil bratra svého, ať ho zabijeme za život bratra jeho, kteréhož zamordoval, nýbrž zahubíme i dědice. A tak uhasí jiskru mou, kteráž pozůstala, aby nezanechali muži mému jména a ostatku na zemi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 8, 'Tedy řekl král ženě: Navrať se do domu svého, a jáť poručím o tobě.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 9, 'I odpověděla žena Tekoitská králi: Nechť jest, pane můj králi, na mne ta nepravost, a na dům otce mého, král pak a stolice jeho ať jest bez viny.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 10, 'Řekl také král: Bude-li kdo mluviti co proti tobě, přiveď ho ke mně, a nedotkneť se tebe více.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 11, 'Tedy ona řekla: Rozpomeň se, prosím, králi, na Hospodina Boha svého, aby se nerozmnožili mstitelé krve k zhoubě a nezahladili syna mého. I odpověděl: Živť jest Hospodin, žeť nespadne vlas syna tvého na zemi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 12, 'K tomu řekla žena: Nechť promluví, prosím, služebnice tvá pánu svému králi slovo. Kterýžto odpověděl: Mluv.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 13, 'I řekla žena: Proč jsi tedy myslil podobnou věc proti lidu Božímu? Nebo mluví král řeč tuto jako ten, kterýž sebe vinného činí, poněvadž nechce zase povolati vyhnaného svého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 14, 'Všickniť jsme zajisté nepochybně smrtelní a jako vody, kteréž rozlity jsouce po zemi, zase sebrány býti nemohou, aniž se Bůh na něčí osobu ohlédá; ovšemť i myšlení svá vynesl, aby vyhnaného nevyháněl od sebe.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 15, 'Nyní pak, že jsem přišla ku pánu svému králi mluviti řeči tyto, příčina jest, že mne strašil lid. Protož řekla služebnice tvá: Budu nyní mluviti králi, snad naplní král žádost služebnice své.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 16, 'Neboť vyslyší král a vysvobodí služebnici svou z ruky muže, chtějícího vyhladiti mne i syna mého spolu z dědictví Božího.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 17, 'Řekla také služebnice tvá: Vždyť mi bude slovo pána mého krále k odtušení; (nebo jako anděl Boží, tak jest pán můj král, když slyší dobré aneb zlé,) a Hospodin Bůh tvůj bude s tebou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 18, 'A odpovídaje král, řekl ženě: Medle, netaj přede mnou toho, nač se já tebe vzeptám. I řekla žena: Mluv, prosím, pane můj králi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 19, 'Tedy řekl král: Není-liž Joáb jednatel všeho tohoto? I odpověděla žena a řekla: Jako jest živa duše tvá, pane můj králi, žeť se nelze uchýliti na pravo aneb na levo ode všeho toho, což mluvil pán můj král; nebo služebník tvůj Joáb, onť jest mi rozkázal, a on naučil služebnici tvou všechněm slovům těmto,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 20, 'A abych tak příkladně vedla řeč tuto, způsobil to služebník tvůj Joáb. Ale pán můj moudrý jest jako anděl Boží, věda, což se koli děje na zemi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 21, 'A protož řekl král Joábovi: Aj, již jsem to učinil. Jdiž tedy, přiveď mládence Absolona.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 22, 'I padl Joáb na tvář svou k zemi, a pokloniv se, poděkoval králi, a řekl Joáb: Dnes jest poznal služebník tvůj, že jsem nalezl milost před očima tvýma, pane můj králi, poněvadž jest král naplnil žádost služebníka svého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 23, 'Tedy vstav Joáb, odšel do Gessur, a přivedl Absolona do Jeruzaléma.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 24, 'I řekl král: Nechť se navrátí do domu svého, ale tváři mé ať nevidí. A tak navrátil se Absolon do domu svého, ale tváři královské neviděl.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 25, 'Nebylo pak žádného muže tak krásného jako Absolon ve všem Izraeli, aby takovou chválu měl. Od paty nohy jeho až do vrchu hlavy jeho nebylo na něm poškvrny.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 26, 'A když střihával vlasy hlavy své, (měl pak obyčej každého roku je střihati, protože jej obtěžovaly, i střihával je), tedy vážíval vlasy hlavy své, a bývalo jich dvě stě lotů váhy obecné.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 27, 'Zrodili se pak Absolonovi tři synové a jedna dcera, jejíž jméno bylo Támar, kteráž byla žena vzezření krásného.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 28, 'I byl Absolon v Jeruzalémě dvě létě, a tváři královské neviděl.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 29, 'A protož poslal Absolon k Joábovi, chtěje ho poslati k králi. Kterýžto nechtěl přijíti k němu. I poslal ještě podruhé, a nechtěl přijíti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 30, 'Tedy řekl služebníkům svým: Shlédněte dědinu Joábovu vedlé pole mého, kdežto má ječmen; jděte a spalte jej. I zapálili služebníci Absolonovi dědinu tu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 31, 'A vstav Joáb, přišel k Absolonovi do domu jeho, a řekl jemu: Proč jsou služebníci tvoji zapálili dědinu mou?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 32, 'Odpověděl Absolon Joábovi: Aj, poslal jsem k tobě, řka: Přiď sem, a pošli tě k králi, abys řekl jemu: I proč jsem přišel z Gessur? Lépe mi bylo ještě tam zůstati. Protož nyní nechať uzřím tvář královu. Pakliť jest na mně nepravost, nechť mne rozkáže zabiti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 33, 'Tedy přišel Joáb k králi a oznámil to jemu. I povolal Absolona. Kterýž přišed k králi, poklonil se na tvář svou až k zemi před ním. I políbil král Absolona.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 1, 'I stalo se potom, že sobě najednal Absolon vozů a koní a padesáte mužů, kteříž by běhali před ním.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 2, 'A vstávaje ráno Absolon, stával u cesty při bráně, a každého muže, kterýž, maje při, šel k králi pro rozsouzení, povolával Absolon, říkaje: Z kterého jsi ty města? A když mu odpověděl: Z toho a z toho pokolení Izraelského jest služebník tvůj,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 3, 'Řekl jemu Absolon: Hle, tvá pře výborná jest a pravá, ale kdo by tě vyslyšel, není žádného u krále.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 4, 'Říkal také Absolon: Ó kdyby mne kdo ustanovil soudcím v zemi této, aby ke mně chodil každý, kdož by měl nesnáz a při, a dopomáhal bych jemu k spravedlnosti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 5, 'Ano i když někdo přicházel, klaněje se jemu, vztáhl ruku svou, a uchopě ho, políbil jej.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 6, 'Činíval pak Absolon tím způsobem všemu Izraelovi, kterýž pro rozsudek přicházel k králi; a tak obracel k sobě Absolon srdce mužů Izraelských.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 7, 'Stalo se také po čtyřidcíti letech, že řekl Absolon k králi: Nechť jdu, prosím, a splním slib svůj v Hebronu, který jsem učinil Hospodinu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 8, 'Nebo byl učinil slib služebník tvůj, když jsem bydlil v Gessur v Syrii, řka: Jestliže mne zase kdy přivede Hospodin do Jeruzaléma, tedy službu jemu učiním.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 9, 'Jemuž řekl král: Jdi u pokoji. Kterýžto vstav, odšel do Hebronu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 10, 'I poslal Absolon špehéře do všech pokolení Izraelských, aby řekli: Když uslyšíte zvuk trouby, rcete: Kralujeť Absolon v Hebronu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 11, 'S Absolonem pak šlo dvě stě mužů z Jeruzaléma pozvaných, ale šli v upřímnosti své, aniž co o tom věděli.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 12, 'Poslal také Absolon pro Achitofele Gilonského, rádce Davidova, aby přišel z města svého Gilo, když měl obětovati oběti. I stalo se spiknutí veliké, nebo lidu ustavičně přibývalo Absolonovi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 13, 'V tom přišel posel k Davidovi, řka: Srdce Izraelských obrátilo se po Absolonovi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 14, 'Tedy řekl David všechněm služebníkům svým, kteříž byli s ním v Jeruzalémě: Vstaňte a utecme, sic jinak nemohli bychom ujíti tváři Absolonovy. Pospěšte, ať odejdeme, aby se neuspíšil, a nezastihl nás, a neuvalil na nás zlého a nepohubil města ostrostí meče.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 15, 'I řekli služebníci královští králi: Což by koli zvolil pán náš král, teď jsme služebníci tvoji.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 16, 'A tak vyšel král se vší svou čeledí pěšky; toliko zanechal král desíti ženin, aby doma hlídaly.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 17, 'Když pak vyšel král a všecken lid pěšky, postavili se na jednom místě zdaleka.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 18, 'I šli všickni služebníci při něm; též všickni Cheretejští a všickni Peletejští, i všickni Gittejští, šest set mužů, kteříž přišli pěšky z Gát, šli před králem.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 19, 'Tedy řekl král k Ittai Gittejskému: Proč ty také jdeš s námi? Navrať se a zůstaň při králi; nebo cizozemec jsi, kterýž se tudíž zase odbéřeš k místu svému.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 20, 'Nedávnos přišel, a již bych dnes tebou pohnouti měl, abys s námi chodil? Jáť zajisté půjdu, kdež mi se nahodí. Navratiž se a zprovoď zase bratří své, a budiž s tebou milosrdenství a pravda.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 21, 'Odpovídaje pak Ittai králi, řekl: Živť jest Hospodin a živť jest pán můj král, že na kterémkoli místě bude pán můj král, buď mrtev aneb živ, tuť bude i služebník tvůj.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 22, 'I řekl David k Ittai: Podiž a přejdi. I přešel Ittai Gittejský a všickni muži jeho, i všecky dítky, kteréž byly s ním.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 23, 'Tedy plakala všecka země hlasem velikým, i všecken lid přecházející. A tak přešel král potok Cedron; i všecken lid přešel proti cestě vedoucí na poušť.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 24, 'A aj, byl také Sádoch a všickni Levítové s ním, nesouce truhlu smlouvy Boží; i postavili truhlu Boží. Šel pak i Abiatar, a stál, dokudž všecken ten lid nepřešel z města.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 25, 'I řekl král Sádochovi: Dones zase truhlu Boží do města. Jestližeť najdu milost před očima Hospodinovýma, přivedeť mne zase, a ukážeť mi ji i příbytek svůj.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 26, 'Pakliť řekne takto: Nelíbíš mi se, aj, teď jsem, nechť mi učiní, což se mu dobrého vidí.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 27, 'Řekl ještě král Sádochovi knězi: Zdaliž ty nejsi vidoucí? Navratiž se do města u pokoji, Achimaas pak syn tvůj, a Jonata syn Abiatarův, dva synové vaši, budou s vámi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 28, 'Hle, já pobudu na rovinách pouště, dokudž nepřijde poselství od vás, skrze něž by mi oznámeno bylo.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 29, 'A tak donesl zase Sádoch a Abiatar truhlu Boží do Jeruzaléma, a zůstali tam.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 30, 'Ale David šel vzhůru k vrchu hory Olivetské, vstupuje a pláče, maje přikrytou hlavu svou; šel pak bos. Všecken také lid, kterýž byl s ním, přikryl jeden každý hlavu svou, a šli, ustavičně plačíce.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 31, 'Tedy povědíno Davidovi, že Achitofel jest s těmi, kteříž se spikli s Absolonem. I řekl David: Zruš, prosím, ó Hospodine, radu Achitofelovu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 32, 'I stalo se, jakž přišel David na vrch hory, aby se tam pomodlil Bohu, aj, potkal se s ním Chusai Architský, maje roztržené roucho své a hlavu prstí posypanou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 33, 'I řekl jemu David: Půjdeš-li se mnou, budeš mi břemenem.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 34, 'Pakli se navrátíš do města a díš k Absolonovi: Služebníkem tvým budu, ó králi, služebníkem zajisté otce tvého byl jsem již zdávna, již pak budu služebníkem tvým, tedy zrušíš radu Achitofelovu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 35, 'Však tam budou s tebou Sádoch a Abiatar kněží. Protož cožkoli uslyšíš z domu králova, oznámíš Sádochovi a Abaitarovi kněžím.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 36, 'Aj, tam s nimi jsou dva synové jejich, Achimaas Sádochův a Jonata Abiatarův, po nichž mi vzkážete, což byste koli uslyšeli.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 37, 'Šel tedy Chusai, přítel Davidův do města; Absolon také přijel do Jeruzaléma.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 1, 'A když David sešel maličko s vrchu, aj Síba služebník Mifibozetův vyšel proti němu se dvěma osly osedlanými, na nichž nesl dvě stě chlebů, a sto hroznů suchých, a sto hrud fíků, a nádobu vína.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 2, 'I řekl král Síbovi: K čemu jsou tyto věci? Odpověděl Síba: Oslové pro čeled královskou k jízdě, chléb pak a fíky, aby jedli služebníci, a víno, aby se napil, kdož by ustal na poušti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 3, 'Opět král řekl: Kdež jest pak syn pána tvého? Odpověděl Síba králi: Aj, zůstal v Jeruzalémě, nebo řekl: Dnes navrátí mi dům Izraelský království otce mého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 4, 'Řekl ještě král Síbovi: Aj, tvéť jsou všecky věci, kteréž má Mifibozet. Jemuž řekl Síba s poklonou: Nechať vždycky tak nalézám milost před očima tvýma, pane můj králi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 5, 'Tedy bral se král David do Bahurim, a aj, vyšel odtud muž z čeledi domu Saulova, jehož jméno bylo Semei, syn Gerův, kterýžto vždy jda, zlořečil.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 6, 'Ano i kamením házel na Davida, a na všecky služebníky krále Davida, ačkoli všecken lid a všickni udatní byli po pravici jeho i po levici jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 7, 'A takto mluvil Semei, když mu zlořečil: Vyjdi, vyjdi, vražedlníče a nešlechetníče.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 8, 'Obrátilť jest na tebe Hospodin všelikou krev domu Saulova, na jehož jsi místě kraloval, a dal Hospodin království v ruku Absolona syna tvého. A aj, již se vidíš v svém neštěstí, nebo jsi vražedlník.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 9, 'I řekl Abizai syn Sarvie králi: I proč zlořečí tento mrtvý pes pánu mému králi? Nechť jdu medle a setnu mu hlavu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 10, 'Ale král řekl: Co vám do toho, synové Sarvie, že zlořečí? Poněvadž Hospodin jemu rozkázal: Zlořeč Davidovi, i kdož by směl říci: Proč tak činíš?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 11, 'Řekl ještě David k Abizai i ke všechněm služebníkům svým: Aj, syn můj, kterýž pošel z života mého, hledá bezživotí mého, čím více nyní tento syn Jemini? Nechte ho, ať zlořečí, nebo jemu rozkázal Hospodin.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 12, 'Snad popatří Hospodin na ssoužení mé, a odplatí mi Hospodin dobrým za zlořečenství jeho dnes.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 13, 'A tak šel David a muži jeho cestou. Semei také šel po stráni hory naproti němu, a jda, zlořečil a házel kamením proti němu a zmítal prachem.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 14, 'I přišel král a všecken lid, kterýž byl s ním, ustalý, a odpočinul tu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 15, 'Absolon pak i všecken lid Izraelský přišli do Jeruzaléma, a Achitofel s ním.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 16, 'A když přišel Chusai Architský, přítel Davidův k Absolonovi, řekl Chusai Absolonovi: Živ buď král, živ buď král.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 17, 'Tedy řekl Absolon k Chusai: Toliž jest vděčnost tvá k příteli tvému? Pročež jsi nešel s přítelem svým?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 18, 'Odpověděl Chusai Absolonovi: Nikoli, ale kohož vyvolil Hospodin a lid tento i všickni muži Izraelští, toho budu a s tím zůstanu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 19, 'Přesto komuž bych já sloužiti měl? Zdali ne synu jeho? Jakož jsem sloužil otci tvému, tak sloužiti budu tobě.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 20, 'Řekl pak Absolon Achitofelovi: Raďtež, co máme činiti?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 21, 'Odpověděl Achitofel Absolonovi: Vejdi k ženinám otce svého, kterýchž zanechal, aby hlídaly doma. I uslyší všecken Izrael, žes se zošklivil otci svému, a zsilí se ruce všech, kteříž jsou s tebou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 22, 'A protož rozbili Absolonovi stan na paláci. I všel Absolon k ženinám otce svého před očima všeho Izraele.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 23, 'Rada pak Achitofelova, kterouž dával toho času, byla, jako by se kdo doptával na řeč Boží. Taková byla každá rada Achitofelova, jakož u Davida tak u Absolona.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 1, 'Řekl ještě Achitofel Absolonovi: Nechť medle vyberu dvanácte tisíc mužů, abych vstana, honil Davida noci této.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 2, 'A dostihna ho, dokudž jest ustalý a zemdlené má ruce, předěsím jej, a uteče všecken lid, kterýž jest s ním, i zamorduji krále samého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 3, 'A tak obrátím všecken lid k tobě; nebo jako bych je všecky obrátil, když zhyne ten muž, kteréhož ty hledáš. O lid ty se nic nestarej.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 4, 'I líbila se ta řeč Absolonovi i všechněm starším Izraelským.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 5, 'A však řekl Absolon: Zavolej sem hned Chusai Architského, abychom slyšeli, co i on mluviti bude.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 6, 'Když pak přišel Chusai k Absolonovi, mluvil k němu Absolon, řka: Takto mluvil Achitofel. Máme-li učiniti vedlé řeči jeho, čili nic? Pověz ty.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 7, 'Tedy řekl Chusai Absolonovi: Neníť dobrá rada, kterouž dal Achitofel nyní.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 8, 'Dále mluvil Chusai: Ty víš o otci svém i mužích jeho, že jsou udatní, k tomu zjitření na mysli, jako nedvědice osiřelá v poli. Nadto otec tvůj jest muž válečný, kterýž nebude nocovati s lidem.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 9, 'Nýbrž nyní spíše v záloze stojí v nějaké jeskyni, aneb v některém jiném místě. I stalo by se, jestliže by kteří padli z těch tvých při začátku, že každý, kdož by o tom uslyšel, řekl by: Stala se porážka v lidu, kterýž postoupil po Absolonovi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 10, 'A tak by i silných reků srdce, kteréž jest jako srdce lva, škodlivě osláblo; nebo ví všecken Izrael, že jest zmužilý otec tvůj, a silní ti, kteříž jsou s ním.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 11, 'Ale radím, abys, shromáždě k sobě všecken Izrael od Dan až do Bersabé, kterýž v množství jest jako písek při moři, ty sám životně vytáhl k boji.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 12, 'A tak potáhneme proti němu, na kterém by koli místě nalezen býti mohl, a připadneme na něj, jako padá rosa na zemi; i nepozůstaneť z něho, totiž ze všech mužů, kteříž jsou při něm, ani jednoho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 13, 'Jestliže by se pak shrnul do města, snesou všecken lid Izraelský k tomu městu provazy, a vtrhneme je až do potoka, tak aby tam ani kaménka nebylo lze najíti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 14, 'I řekl Absolon a všickni muži Izraelští: Lepšíť jest rada Chusai Architského, než rada Achitofelova. Hospodin zajisté to způsobil, aby zrušena byla rada Achitofelova, kteráž sic dobrá byla, aby tak uvedl Hospodin na Absolona zlé věci.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 15, 'Oznámil pak to Chusai Sádochovi a Abiatarovi kněžím: Tak a tak radil Achitofel Absolonovi a starším Izraelským, ale já takto a takto jsem radil.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 16, 'Nyní tedy pošlete rychle a oznamte Davidovi, řkouce: Nezůstavej přes noc na rovinách pouště, ale přeprav se bez meškání, aby snad nebyl sehlcen král i všecken lid, kterýž jest s ním.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 17, 'Jonata pak a Achimaas stáli u studnice Rogel. I šla tam děvečka a pověděla jim, aby oni jdouce, oznámili to králi Davidovi; nebo nesměli se ukázati aneb vjíti do města.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 18, 'A však uzřel je služebník, a oznámil Absolonovi. Pročež odšedše oba rychle, vešli do domu muže v Bahurim, kterýž měl studnici na dvoře svém. I spustili se do ní.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 19, 'A žena vzavši plachtu, rozestřela ji na vrch studnice, a nasypala na ni krup. A tak nebyla ta věc spatřína.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 20, 'Nebo když přišli služebníci Absolonovi k ženě do domu a řekli: Kde jest Achimaas a Jonata? odpověděla jim žena: Přešliť jsou ten potok. Hledavše tedy a nic nenalezše, navrátili se do Jeruzaléma.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 21, 'A když oni odešli, tito vystoupivše z studnice, šli a oznámili králi Davidovi a řekli jemu: Vstaňte a přepravte se rychle přes vodu, nebo toto radil proti vám Achitofel.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 22, 'Protož vstav David a všecken lid, kterýž byl s ním, přepravili se přes Jordán, prvé než se rozednilo; a nezůstal ani jeden, ješto by se nepřepravil přes Jordán.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 23, 'Tedy Achitofel vida, že se nestalo vedlé rady jeho, osedlal osla, a vstav, odjel do domu svého, do města svého. A učiniv pořízení v čeledi své, oběsil se a umřel; i pochován jest v hrobě otce svého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 24, 'David pak byl již přišel do Mahanaim, když se Absolon přepravil přes Jordán, on i všecken lid Izraelský s ním.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 25, 'A tu ustanovil Absolon Amazu místo Joába nad vojskem. (Byl pak Amaza syn muže, jehož jméno bylo Jetra Izraelský, kterýž všel k Abigail dceři Náchas, sestře Sarvie matky Joábovy.)');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 26, 'I položil se Izrael a Absolon v zemi Galád.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 27, 'Stalo se pak, když přišel David do Mahanaim, že Sobi syn Náchas z Rabbat synů Ammon, a Machir syn Amielův z Lodebar, a Barzillai Galádský z Rogelim,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 28, 'Lůže, číše a nádoby hliněné, též pšenice, ječmene, mouky, krup, bobu, šocovice a pražmy,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 29, 'Ano i medu, másla a ovcí i syrů kravských přinesli Davidovi a lidu, kterýž s ním byl, aby jedli. Nebo řekli: Lid ten jest hladovitý a ustalý, i žíznivý na té poušti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 1, 'Sečtl pak David lid, kterýž měl s sebou, a ustanovil nad nimi hejtmany a setníky.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 2, 'I uvedl David třetinu lidu v správu Joábovu, a třetinu v správu Abizai syna Sarvie, bratra Joábova, a třetinu v správu Ittai Gittejského. A řekl král lidu: I jáť také potáhnu s vámi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 3, 'Ale lid řekl: Nikoli nepotáhneš; nebo jestliže bychom i utíkali, nebudouť na to velmi dbáti, aniž, by nás i polovici zbili, budou toho velmi vážiti. Ty sám zajisté jsi jako z nás deset tisíců, protož lépe bude, abys nám byl v městě ku pomoci.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 4, 'I řekl jim král: Což se vám za dobré vidí, učiním. Tedy stál král u brány, a všecken lid vycházel po stu a po tisíci.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 5, 'Přikázal pak král Joábovi a Abizai a Ittai, řka: Zacházejtež mi pěkně s synem Absolonem. A všecken lid slyšel, když přikazoval král všechněm hejtmanům o Absolonovi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 6, 'A tak vytáhl lid do pole proti lidu Izraelskému, a byla bitva v lese Efraim.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 7, 'I poražen jest tu lid Izraelský od služebníků Davidových, a stala se tu porážka veliká v ten den až do dvadceti tisíců.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 8, 'Nebo když ta bitva rozšířila se po vší krajině, více pohubil lidu les, nežli jich požral meč toho dne.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 9, 'Potkal se pak Absolon s služebníky Davidovými. Kterýžto Absolon jel na mezku, (i podšel mezek pod hustý dub veliký,) a uvázl za hlavu v stromu tom, tak že visel mezi nebem a zemí. Ale mezek, kterýž pod ním byl, odběhl pryč.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 10, 'To uzřev jeden, oznámil Joábovi, řka: Hle, viděl jsem Absolona, an visí na dubě.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 11, 'I řekl Joáb muži, kterýž mu to oznámil: Aj, viděls. Pročež jsi ho tam nesrazil na zem? A já bylť bych povinen dáti deset lotů stříbra a pás rytířský jeden.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 12, 'Odpověděl muž ten Joábovi: A já, bych i odečtených měl na ruce své tisíc lotů stříbra, nevztáhl bych ruky své na syna králova; nebo jsme slyšeli, kterak přikazoval král tobě a Abizai a Ittai, řka: Šetřte všickni syna mého Absolona;');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 13, 'Leč bych se dopustiti chtěl sám proti duši své nepravosti. Ale nebýváť nic tajno před králem, a ty bys sám proti mně stál.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 14, 'I řekl Joáb: Nebuduť se tu meškati s tebou. Protož vzav tři kopí do ruky své, vrazil je do Absolona, an ještě živ byl na dubě.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 15, 'A obskočivše Absolona deset služebníků, oděnců Joábových, bili jej a zabili.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 16, 'V tom zatroubil Joáb v troubu. I vrátil se lid od honění Izraele; nebo zdržel Joáb lid.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 17, 'A vzavše Absolona, uvrhli jej v tom lese do jámy veliké, a nametali na něj hromadu kamení velmi velikou. Ale všecken Izrael zutíkali jeden každý do stanů svých.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 18, '(Absolon pak vzal byl a vyzdvihl sobě za života svého sloup v údolí královském; nebo byl řekl: Nemám syna, aby zůstala pamět jména mého. Protož nazval ten sloup jménem svým, kterýž slove místo Absolonovo až do dnešního dne.)');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 19, 'Tedy Achimaas syn Sádochův řekl: Medle, nechť běžím, abych zvěstoval králi, že ho vysvobodil Hospodin z ruky nepřátel jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 20, 'I řekl jemu Joáb: Nebyl bys dnes dobrým poslem, ale oznámíš to jiného dne; dnes však neoznamuj, proto že syn králův umřel.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 21, 'Potom řekl Joáb k Chuzi: Jdiž, zvěstuj králi, co jsi viděl. A pokloniv se Chuzi Joábovi, běžel.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 22, 'Mluvil pak ještě Achimaas syn Sádochův, a řekl Joábovi: Buď, jak buď, medle, nechť já také běžím za Chuzi. Odpověděl Joáb: Proč bys ty běžel, synu můj, když nemáš, co bys dobrého zvěstoval?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 23, 'I řekl: Buď, jak buď, poběhnu. Odpověděl mu: Běž. A tak běžel Achimaas cestou přímější a předběhl Chuzi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 24, 'David pak seděl mezi dvěma branami. I vyšel strážný na vrch brány na zed, kterýž pozdvih očí svých, uzřel, a hle, muž běžel sám.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 25, 'Tedy volaje strážný, oznámil králi. I řekl král: Jest-liť sám, dobré poselství nese. A když ten šel předce a přibližoval se,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 26, 'Uzřel ještě strážný muže druhého běžícího. I zavolal strážný na branného a řekl: Hle, opět muž běží sám. Tedy řekl král: I tenť v poselství běží.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 27, 'Řekl ještě strážný: Vidím běh prvního, jako běh Achimaasa syna Sádochova. I řekl král: Dobrýtě to muž, protož s dobrým poselstvím jde.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 28, 'Tedy volaje Achimaas, řekl králi: Pokoj tobě. A pokloniv se králi tváří svou k zemi, řekl: Požehnaný Hospodin Bůh tvůj, kterýž podmanil muže ty, kteříž pozdvihli rukou svých proti pánu mému králi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 29, 'I řekl král: Dobře-li se má syn můj Absolon? Odpověděl Achimaas: Viděl jsem hluk veliký, když posílal služebníka králova Joáb, a mne služebníka tvého, ale nevím nic, co bylo.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 30, 'Jemuž řekl král: Odstup a stůj tamto. I odstoupil a stál.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 31, 'A v tom Chuzi přišed, řekl: Zvěstuje se pánu mému králi, že vysvobodil tě dnes Hospodin z ruky všech povstávajících proti tobě.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 32, 'Ale král řekl k Chuzi: Jest-liž živ syn můj Absolon? Odpověděl Chuzi: Nechť jsou tak, jako syn králův, nepřátelé pána mého krále, i všickni, kteříž povstávají proti tobě ke zlému.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 33, 'I zarmoutil se král, a vstoupiv do horního pokoje na bráně, plakal a jda, mluvil takto: Synu můj Absolone, synu můj, synu můj Absolone! Ó kdybych byl umřel za tebe, Absolone synu můj, synu můj!');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 1, 'I oznámeno jest Joábovi: Aj, král pláče a naříká pro Absolona.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 2, 'Pročež obrátilo se to vysvobození toho dne v kvílení všemu lidu; nebo slyšel lid v ten den, že bylo praveno: Zámutek má král pro syna svého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 3, 'A tak kradl se lid toho dne, vcházeje do města, jako se krade lid, když se stydí, utíkaje z boje.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 4, 'Král pak zakryl tvář svou, a křičel král hlasem velikým: Synu můj Absolone, Absolone synu můj, synu můj!');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 5, 'Tedy všed Joáb k králi do domu, řekl: Zahanbil jsi dnes tváři všech služebníků svých, kteříž vysvobodili život tvůj dnes, a život synů tvých i dcer tvých, a život žen tvých i život ženin tvých,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 6, 'Miluje ty, kteříž tě mají v nenávisti, a v nenávisti maje ty, kteříž tě milují; nebos dokázal dnes, že sobě nevážíš hejtmanů a služebníků. Shledalť jsem to zajisté dnes, že kdyby byl Absolon živ zůstal, bychom pak všickni dnes byli pobiti, tedy dobře by se tobě to líbilo.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 7, 'Protož nyní vstana, vyjdi, a mluv ochotně k služebníkům svým; nebo přisahámť skrze Hospodina, jestliže nevyjdeš, žeť nezůstane žádný s tebou této noci, a toť bude tobě horší, nežli všecky zlé věci, kteréž na tebe přišly od mladosti tvé až dosavad.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 8, 'A tak vstav král, posadil se v bráně. I povědíno bylo všemu lidu těmito slovy: Aj, král sedí v bráně. I přišel všecken lid před oblíčej krále, ale lid Izraelský byl zutíkal jeden každý do svých stanů.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 9, 'Tedy všecken lid hádal se vespolek ve všech pokoleních Izraelských, a pravili: Král vytrhl nás z ruky nepřátel našich, a tentýž vytrhl nás z ruky Filistinských, a teď nyní utekl z země před Absolonem.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 10, 'Absolon pak, kteréhož jsme pomazali sobě, zahynul v boji. Nyní tedy, proč zanedbáváte přivésti zase krále?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 11, 'Protož král David poslal k Sádochovi a Abiatarovi kněžím, s těmito slovy: Mluvte k starším Judským, řkouce: Proč máte býti poslední v uvedení zase krále do domu jeho? (Nebo řeč všeho lidu Izraelského donesla se krále o uvedení jeho do domu jeho.)');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 12, 'Bratří moji jste, kost má a tělo mé jste; proč tedy máte býti poslední v uvedení zase krále?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 13, 'A Amazovi také rcete: Zdaliž ty nejsi kost má a tělo mé? Toto ať mi učiní Bůh a toto přidá, jestliže nebudeš hejtmanem vojska přede mnou po všecky dny na místo Joába.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 14, 'I naklonil srdce všech mužů Judských, jako muže jednoho, aby poslali k králi, řkouce: Navratiž se ty i všickni služebníci tvoji.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 15, 'Tedy navrátil se král, a přišel až k Jordánu. Lid pak Judský byl přišel do Galgala, aby se bral vstříc králi, a převedl jej přes Jordán.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 16, 'Pospíšil také Semei syn Gery, syna Jemini, kterýž byl z Bahurim, a vyšel s lidem Judským vstříc králi Davidovi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 17, 'A tisíc mužů bylo s ním z Beniamin. Síba také služebník domu Saulova, s patnácti syny svými, a dvadceti služebníků jeho s ním, přepravili se přes Jordán před krále.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 18, 'I přeplavili lodí, aby převezli čeled královskou a učinili, což by se jemu líbilo. Semei pak syn Gerův padl před králem, když se přepraviti měl přes Jordán.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 19, 'A řekl králi: Nepočítej mi pán můj nepravosti, a nezpomínej, co neprávě učinil služebník tvůj toho dne, když vyšel pán můj král z Jeruzaléma, aby to měl skládati král v srdci svém.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 20, 'Neboť zná služebník tvůj, že zhřešil, a aj, přišel jsem dnes prvé, než kdo ze vší čeledi Jozefovy, abych vyšel vstříc pánu svému králi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 21, 'I odpověděl Abizai syn Sarvie a řekl: A což nebude zabit Semei, proto že zlořečil pomazanému Hospodinovu?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 22, 'Ale David řekl: Co vám do toho, synové Sarvie, že jste mi dnes odporní? Dnes-liž má zabit býti někdo v Izraeli? Nebo zdaliž nevím, že dnes jsem králem nad Izraelem.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 23, 'Tedy řekl král k Semei: Neumřeš. I přisáhl mu král.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 24, 'Mifibozet také vnuk Saulův vyjel vstříc králi. (Neošetřoval pak byl noh svých, ani brady nespravoval, ani šatů svých nepral od toho dne, jakž byl odšel král, až do dne, když se navrátil v pokoji.)');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 25, 'A když přišel do Jeruzaléma, vyšel vstříc králi. I řekl jemu král: Proč jsi neodšel se mnou, Mifibozete?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 26, 'Kterýž odpověděl: Pane můj králi, služebník můj oklamal mne. Řekltě byl zajisté služebník tvůj: Osedlám sobě osla, abych vsedna na něj, bral se s králem, proto že jest kulhavý služebník tvůj.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 27, 'I osočil služebníka tvého u pána mého krále, ale pán můj král jest jako anděl Boží, učiniž tedy, cožť se dobrého vidí.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 28, 'Nebo všickni z domu otce mého byli jsme hodni smrti před pánem mým králem, a však jsi zasadil služebníka svého mezi ty, kteříž jedí chléb stolu tvého. K čemuž bych více právo měl, a oč se více na krále domlouval?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 29, 'Jemuž řekl král: Proč šíříš řeč svou? Vyřklť jsem. Ty a Síba rozdělte se statkem.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 30, 'Ještě řekl Mifibozet králi: Třebas nechť všecko vezme, když se jen navrátil pán můj král v pokoji do domu svého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 31, 'Ano i Barzillai Galádský vyšel z Rogelim, a přepravil se s králem přes Jordán, aby ho zprovodil za Jordán.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 32, 'Byl pak Barzillai velmi starý, maje osmdesáte let, kterýž opatroval krále stravou, když obýval v Mahanaim; nebo byl člověk bohatý velmi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 33, 'I řekl král k Barzillai: Poď se mnou, a chovati tě budu při sobě v Jeruzalémě.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 34, 'Ale Barzillai odpověděl králi: Jacíž jsou dnové věku mého, abych šel s králem do Jeruzaléma?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 35, 'V osmdesáti letech jsem dnes. Zdaliž mohu rozeznati mezi dobrým a zlým? Zdaliž okušením rozezná služebník tvůj, co bych jedl a co bych pil? Zdaliž poslouchati mohu již hlasu zpěváků a zpěvakyní? Proč by tedy služebník tvůj déle býti měl břemenem pánu svému králi?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 36, 'Maličko ještě půjde služebník tvůj za Jordán s králem; nebo proč by mi se takovou odplatou král odplacovati měl?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 37, 'Nechť se navrátí, prosím, služebník tvůj, ať umru v městě svém, kdež jest hrob otce mého a matky mé. Aj, služebník tvůj Chimham půjde se pánem mým králem, jemuž učiníš, cožť se dobrého viděti bude.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 38, 'I řekl král: Dobře, nechť jde se mnou Chimham, a učiním jemu, což se tobě za dobré viděti bude; nadto čehožkoli požádáš ode mne, toť učiním.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 39, 'A když se přepravil všecken lid přes Jordán, král také přepravil se. I políbil král Barzillai a požehnal ho, kterýžto navrátil se na místo své.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 40, 'A tak bral se král do Galgala a Chimham s ním; všecken také lid Judský provázeli krále, též i polovice lidu Izraelského.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 41, 'A aj, všickni muži Izraelští přišedše k králi, řekli jemu: Proč jsou tě ukradli bratří naši, muži Juda, a převedli krále a čeled jeho přes Jordán, i všecky muže Davidovy s ním?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 42, 'I odpověděli všickni muži Judští mužům Izraelským: Proto že král jest příbuzný náš. A proč se hněváte o to? Zdaliž nás za to král pokrmy opatroval? Zdaliž nám jaké dary dal?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 43, 'Odpovídajíce pak muži Izraelští mužům Judským, řekli: Deset dílů máme v králi, a protož i v Davidovi máme více nežli vy. Pročež tedy málo jste nás sobě vážili? Zdaliž jsme my prvé o to nemluvili, abychom zase přivedli krále svého? Ale tvrdší byla řeč mužů Judských nad řeč mužů Izraelských.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 1, 'Přišel pak tu náhodou člověk nešlechetný, jehož jméno bylo Seba, syn Bichri, muž Jemini. Ten zatroubil v troubu a řekl: Nemámeť my dílu v Davidovi, ani dědictví v synu Izai; obrať se jeden každý k stanům svým, ó Izraeli.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 2, 'A tak všickni muži Izraelští odstoupili od Davida za Sebou synem Bichri, ale muži Judští přídrželi se krále svého od Jordánu až do Jeruzaléma.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 3, 'David pak přišel do domu svého do Jeruzaléma. A vzal král deset ženin, kterýchž byl nechal, aby hlídaly doma, a dal je pod stráž, a choval je, ale nevcházel k nim. A zůstaly zavřené až do dne smrti své v vdovství.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 4, 'Potom řekl král Amazovi: Svolej mi muže Judské do třetího dne, ty také se tu postav.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 5, 'A tak odšel Amaza, aby svolal lid Judský, ale prodlil mimo určitý čas, kterýž mu byl uložil.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 6, 'Protož řekl David Abizai: Již nyní hůře nám činiti bude Seba syn Bichri, nežli Absolon. Vezmi služebníky pána svého, a hoň jej, aby sobě nenalezl měst hrazených, a tak ušel by nám s očí.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 7, 'Tedy táhli za ním muži Joábovi, i Cheretejští, i Peletejští, a všickni udatní vytáhli z Jeruzaléma, aby honili Sebu syna Bichri.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 8, 'A když byli u kamene toho velikého, kterýž jest v Gabaon, Amaza potkal se s nimi. Joáb pak byl opásán po sukni, v kterouž byl oblečen, na níž také měl připásaný meč k bedrám v pošvě své, kterýž snadně vytrhnouti i zase vstrčiti mohl.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 9, 'I řekl Joáb Amazovi: Dobře-li se máš, bratře můj? A ujal Joáb pravou rukou Amazu za bradu, aby ho políbil.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 10, 'Ale Amaza nešetřil se meče, kterýž byl v ruce Joábově. I ranil ho jím pod páté žebro, a vykydl střeva jeho na zem jednou ranou, a umřel. I honili Joáb a Abizai, bratr jeho, Sebu syna Bichri.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 11, 'Tedy stoje tu jeden podlé něho z služebníků Joábových, řekl: Kdokoli přeje Joábovi, a kdokoli drží s Davidem, jdi za Joábem.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 12, 'Amaza pak válel se ve krvi prostřed cesty. A vida onen, že se zastavoval všecken lid, odvlékl Amazu s cesty do pole, a uvrhl na něj roucho, vida, že každý, kdož šel mimo něj, zastavoval se.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 13, 'A když byl odvlečen z cesty, šel jeden každý za Joábem, aby honili Sebu syna Bichri.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 14, '(Kterýžto prošel všecka pokolení Izraelská do Abel Betmaacha se všechněmi Berejskými, kteříž se byli shromáždili a šli za ním.)');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 15, 'A přitáhše, oblehli jej v Abel Betmaacha, a udělali násyp proti městu, kteréž se bránilo z bašt; všecken pak lid, kterýž byl s Joábem, usiloval podvrátiti zed.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 16, 'V tom zvolala jedna rozumná žena z města: Slyšte, slyšte! Rcete medle Joábovi: Přistup sem, a budu s tebou mluviti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 17, 'Kterýž když k ní přistoupil, řekla žena: Ty-li jsi Joáb? Odpověděl: Jsem. I řekla jemu: Poslyš slov služebnice své. Odpověděl: Slyším.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 18, 'Protož mluvila, řkuci: Takť jsou rozmlouvali hned s počátku, řkouce: Bez pochyby žeť se ptáti budou Abelských, a tak se spraví.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 19, 'Jáť jsem jedno z pokojných a věrných Izraelských, ty pak usiluješ zkaziti město, a to ještě hlavní město v Izraeli. I pročež usiluješ sehltiti dědictví Hospodinovo?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 20, 'Tedy odpověděl Joáb a řekl: Odstup, odstup to ode mne, abych sehltiti a zkaziti chtěl.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 21, 'Neníť toho, ale muž z hory Efraim, jménem Seba, syn Bichri, pozdvihl ruky své proti králi Davidovi. Vydejte ho samého, a odtrhnemť od města. I řekla žena Joábovi: Hle, hlava jeho vyvržena bude tobě přes zed.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 22, 'A tak zjednala to žena ta u všeho lidu moudrostí svou, že sťavše hlavu Seby syna Bichri, vyhodili ji Joábovi. Kterýžto když zatroubil v troubu, rozešli se od města jeden každý do stanů svých. Joáb také vrátil se do Jeruzaléma k králi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 23, 'Byl pak Joáb představen všemu vojsku Izraelskému, a Banaiáš syn Joiadův nad Cheretejskými a Peletejskými.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 24, 'Též Aduram byl nad platy, a Jozafat syn Achiludův byl kanclířem,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 25, 'A Seiáš písařem, Sádoch pak a Abiatar byli kněžími.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 26, 'Híra také Jairský byl knížetem Davidovým.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 1, 'Byl pak hlad za dnů Davidových tři léta pořád. I hledal David tváři Hospodinovy. Jemuž řekl Hospodin: Pro Saule a pro dům jeho vražedlný, nebo zmordoval Gabaonitské.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 2, 'Tedy povolav král Gabaonitských, mluvil k nim. (Gabaonitští pak nebyli z synů Izraelských, ale z ostatků Amorejských, jimž ačkoli byli synové Izraelští přísahou se zavázali, však Saul usiloval je vypléniti, v horlivosti své pro syny Izraelské a Judské.)');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 3, 'A řekl David Gabaonitským: Což vám učiním a čím vás spokojím, abyste dobrořečili dědictví Hospodinovu?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 4, 'Odpověděli jemu Gabaonitští: Není nám o stříbro ani o zlato činiti s Saulem a domem jeho, ani o bezživotí někoho z Izraele. I řekl: Cožkoli díte, učiním vám.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 5, 'Kteříž řekli králi: Muže toho, kterýž vyhubil nás, a kterýž ukládal o nás, vyhladíme, aby nezůstal v žádných končinách Izraelských.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 6, 'Nechť jest nám dáno sedm mužů z jeho synů, a zvěsíme je Hospodinu u Gabaa Saulova, kteréhož byl vyvolil Hospodin. I řekl král: Já dám.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 7, 'Odpustil pak král Mifibozetovi synu Jonaty, syna Saulova, pro přísahu Hospodinovu, kteráž byla mezi nimi, mezi Davidem a Jonatou synem Saulovým.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 8, 'Ale vzal král dva syny Rizpy dcery Aja, kteréž porodila Saulovi, Armona a Mifibozeta, a pět synů sestry Míkol dcery Saulovy, kteréž byla porodila Adrielovi synu Barzillai Molatitského.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 9, 'I vydal je v ruku Gabaonitských, kteréž zvěšeli na hoře před Hospodinem. A tak kleslo těch sedm spolu, a zbiti jsou při začátku žně, když počínali žíti ječmene.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 10, 'Rizpa pak, dcera Aja, vzavši žíni, prostřela ji sobě na skále při začátku žně, dokudž nepršel na ně déšť s nebe, a nedala ptákům nebeským sedati na ně ve dne, ani přicházeti zvěři polní v noci.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 11, 'Tedy oznámeno jest Davidovi, co učinila Rizpa dcera Aja, ženina Saulova.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 12, 'Protož odšed David, vzal kosti Saulovy a kosti Jonaty syna jeho od starších Jábes Galád, kteříž byli je ukradli na ulici Betsan, kdežto byli je zvěšeli Filistinští v ten den, když porazili Filistinští Saule v Gelboe.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 13, 'Vzal, pravím, odtud kosti Saulovy a kosti Jonaty syna jeho; i kosti těch, kteříž zvěšeni byli, sebrali.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 14, 'A pochovali je s kostmi Saulovými a Jonaty syna jeho, v zemi Beniamin, v Sela, v hrobě Cis otce jeho; a učinili všecko, což byl přikázal král, a potom slitoval se Bůh nad zemí.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 15, 'Vznikla pak opět válka Filistinských proti Izraelovi. I vytáhl David a služebníci jeho s ním, a bili se s Filistinskými, tak že ustal David.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 16, 'Tedy Izbibenob, kterýž byl z synů jednoho obra, (jehož kopí hrot vážil tři sta lotů oceli, a měl připásaný k sobě meč nový,) myslil zabiti Davida.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 17, 'Ale retoval ho Abizai syn Sarvie, a raniv toho Filistinského, zabil jej. Protož muži Davidovi přisáhli, řkouce jemu: Nepůjdeš více s námi do boje, abys nezhasil svíce Izraelské.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 18, 'Opět byla válka v Gob s Filistinskými. Tehdáž Sibbechai Chusatský zabil Sáfu, kterýž byl z synů téhož obra.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 19, 'Byla ještě i jiná válka s Filistinskými v Gob, kdež Elchánan syn Járe Oregim Betlémský zabil bratra Goliáše Gittejského, u jehož kopí bylo dřevo jako vratidlo tkadlcovské.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 20, 'Potom byla také válka v Gát. A byl tam muž veliké postavy, kterýž měl u rukou a u noh po šesti prstech, všech čtyřmecítma, a byl také syn toho obra.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 21, 'Ten když haněl Izraele, zabil ho Jonata, syn Semmaa bratra Davidova.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 22, 'Ti čtyři byli synové jednoho obra v Gát, kteříž padli od ruky Davidovy a od ruky služebníků jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 1, 'Mluvil pak David Hospodinu slova písně této v ten den, když ho vysvobodil Hospodin z ruky všech nepřátel jeho, i z ruky Saulovy.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 2, 'A řekl: Hospodin skála má a hrad můj, i vysvoboditel můj se mnou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 3, 'Bůh skála má, doufati budu v něho; štít můj a roh spasení mého, vyvýšení mé a útočiště mé, spasitel můj, kterýž od násilí vysvobozuje mne.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 4, 'Chvály hodného vzýval jsem Hospodina, a od nepřátel svých vysvobozen jsem.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 5, 'Nebo obklíčily mne byly úzkosti smrti, a proudové bezbožných předěsili mne.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 6, 'Bolesti smrtelné obstoupily mne, a osídla smrti zachvátila mne.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 7, 'V úzkosti své vzýval jsem Hospodina, a k Bohu svému volal jsem, i vyslyšel z chrámu svého hlas můj, a křik můj přišel v uši jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 8, 'Tedy pohnula se a zatřásla země, základové nebes pohnuli se, a třásli se pro rozhněvání jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 9, 'Dým vycházel z chřípí jeho, a oheň zžírající z úst jeho, od něhož se uhlí roznítilo.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 10, 'Nakloniv nebes, sstoupil, a mrákota byla pod nohami jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 11, 'I vsedl na cherubín a letěl, a spatřín jest na peří větrovém.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 12, 'Položil temnosti vůkol sebe jako stany, shrnutí vod, oblaky husté.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 13, 'Od blesku oblíčeje jeho rozpálilo se uhlí řeřavé.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 14, 'Hřímal s nebes Hospodin, a Nejvyšší vydal zvuk svůj.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 15, 'Vystřelil i střely, kterýmiž je rozptýlil, a blýskání, jímž je porazil.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 16, 'I ukázaly se hlubiny mořské, a odkryti jsou základové okršlku, pro zůřivé kárání Hospodinovo, pro dmýchání větru chřípí jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 17, 'Poslav s výsosti, přijal mne, vytáhl mne z vod velikých.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 18, 'Vysvobodil mne od nepřítele mého silného, od těch, kteříž mne nenáviděli, ačkoli silnější mne byli.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 19, 'Předstihli mne v den trápení mého, ale Hospodin byl mi podpora.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 20, 'Kterýž vyvedl mne na prostranství, vysvobodil mne, nebo sobě oblíbil mne.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 21, 'Odplatil mi Hospodin podlé spravedlnosti mé, podlé čistoty rukou mých odplatil mi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 22, 'Nebo jsem ostříhal cest Hospodinových, aniž jsem se bezbožně strhl Boha svého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 23, 'Všickni zajisté soudové jeho jsou před oblíčejem mým, aniž jsem od kterých ustanovení jeho odstoupil.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 24, 'A tak byv dokonalý před ním, šetřil jsem, abych se nedopustil nepravosti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 25, 'Protož odplatil mi Hospodin podlé spravedlnosti mé, vedlé čistoty mé před očima jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 26, 'Ty, Pane, s milosrdným milosrdně nakládáš, a k upřímému upřímě se máš.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 27, 'K sprostnému sprostně se ukazuješ, a s převráceným převráceně zacházíš.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 28, 'Lid pak ssoužený vysvobozuješ, ale před vysokomyslnými oči své sklopuješ.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 29, 'Ty zajisté jsi svíce má, ó Hospodine. Hospodin jistě osvěcuje temnosti mé.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 30, 'Nebo v tobě proběhl jsem vojska, v Bohu svém přeskočil jsem zed.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 31, 'Toho Boha silného cesta jest dokonalá, výmluvnosti Hospodinovy přečištěné; onť jest štít všech, kteříž doufají v něho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 32, 'Nebo kdo jest Bohem kromě Hospodina? A kdo jest skalou kromě Boha našeho?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 33, 'Bůh jest síla má i vojska mého, onť působí volnou cestu mou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 34, 'Činí nohy mé jako laní, a na vysokých místech mých postavuje mne.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 35, 'Cvičí ruce mé k boji, tak že lámi lučiště ocelivá rukama svýma.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 36, 'Nebo dal mi štít spasení svého, a dobrotivost jeho zvelebila mne.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 37, 'Rozšířil kroky mé pode mnou, aby se nepodvrtly nohy mé.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 38, 'Honil jsem nepřátely své a zahladil jsem je, aniž jsem se navrátil, dokudž jsem jich nevyplénil.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 39, 'Docela jsem je vyhubil a sprobodal jsem je, tak že nepovstanou; i padli pod nohy mé.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 40, 'Ty zajisté, Bože, přepásals mne udatností k boji, porazils pode mne ty, kteříž povstávají proti mně.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 41, 'Nýbrž dals mi šíji nepřátel mých, těch, kteříž v nenávisti měli mne, a vyplénil jsem je.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 42, 'Ohlédali se, ale nebyl, kdo by vysvobodil, k Hospodinu, ale nevyslyšel jich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 43, 'I potřel jsem je jako prach země, jako bláto na ulicích potlačil a rozptýlil jsem je.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 44, 'Ty jsi mne vytrhl z různic lidu mého, zachovals mne, abych byl za hlavu národům; lid neznámý mně sloužil.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 45, 'Cizozemci lhali mi, a jakž zaslechli, uposlechli mne.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 46, 'Cizozemci svadli, a třásli se i v ohradách svých.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 47, 'Živť jest Hospodin, a požehnaná skála má; protož ať jest vyvyšován Bůh, skála spasení mého,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 48, 'Bůh silný, kterýž dává mi pomsty a podmaňuje mi lidi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 49, 'Vyvodíš mne z prostřed nepřátel mých, a nad povstávajícími proti mně vyvyšuješ mne, člověka nepravého mne zbavuješ.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 50, 'Protož chváliti tě budu, Hospodine, mezi národy, a jménu tvému žalmy zpívati budu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 51, 'Onť jest hrad jistého spasení krále svého, a ten, kterýž činí milosrdenství pomazanému svému Davidovi, i semeni jeho až na věky.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 1, 'Tato jsou pak poslední slova Davidova: Řekl David syn Izai, řekl, pravím, muž, kterýž jest velice zvýšený, pomazaný Boha Jákobova, a libý v zpěvích Izraelských:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 2, 'Duch Hospodinův mluvil skrze mne, a řeč jeho jazykem mým vynesena.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 3, 'Řekl mi Bůh Izraelský, mluvila skála Izraelská: Kdo panovati bude nad lidem, budeť spravedlivý, panující v bázni Boží.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 4, 'Rovně jako bývá světlo jitřní, když slunce vychází ráno bez oblaků, a jako mocí tepla a deště roste bylina z země:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 5, 'Tak zajisté dům můj před Bohem; nebo smlouvu věčnou učinil se mnou, kteráž všelijak upevněna a ostříhána bude. A toť jest všecko mé spasení a všeliká útěcha, že nic tak vzdělávati se nebude.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 6, 'Bezbožní pak všickni vypléněni budou jako trní, kteréž rukou bráno nebývá.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 7, 'Ale kdož by se ho chtěl dotknouti, vezme železo a žerď, aneb ohněm docela spalí je tu, kdež zrostlo.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 8, 'Tato jsou jména nejudatnějších Davidových: Jošeb Bašebet Tachmonský, přední z vůdců, jehož rozkoš byla s kopím pojednou udeřiti na osm set ku pobití jich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 9, 'A po něm Eleazar syn Dodi, syna Achochi, mezi třmi silnými, kteříž byli s Davidem, když se opovážili proti Filistinským shromážděným tam k boji, když již byli odtáhli muži Izraelští.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 10, 'Ten vstav, bil Filistinské, až ustala ruka jeho a ostála se při meči. V ten den zajisté učinil Hospodin vysvobození veliké, tak že se lid za ním navrátil, toliko aby kořisti vzebral.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 11, 'Po něm pak byl Samma syn Age Hararský. Nebo když se byli shromáždili Filistinští v hromadu tu, kdež bylo díl rolí poseté šocovicí, a lid utekl před Filistinskými:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 12, 'Tedy postavil se u prostřed dílu toho, a vysvobodil jej, a porazil Filistinské. I učinil Hospodin vysvobození veliké.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 13, 'Sstoupili také ti tři z třidcíti předních, a přišli ve žni k Davidovi do jeskyně Adulam, když vojsko Filistinské leželo v údolí Refaim.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 14, '(Nebo David tehdáž byl v pevnosti své, a osazený lid Filistinských byl u Betléma.)');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 15, 'Zechtělo se pak Davidovi vody, a řekl: Ó by mi někdo dal píti vody z čisterny Betlémské, kteráž jest u brány!');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 16, 'A protož probivše se ti tři udatní skrze vojsko Filistinských, navážili vody z čisterny Betlémské, kteráž byla u brány, kterouž nesli a donesli k Davidovi. On pak nechtěl jí píti, ale obětoval ji Hospodinu,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 17, 'A řekl: Nedejž mi toho, ó Hospodine, abych to učiniti měl. Zdaliž to není krev mužů těch, kteříž šli, opováživše se života svého? I nechtěl jí píti. To učinili ti tři silní.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 18, 'Potom Abizai bratr Joábův, syn Sarvie, byl přední mezi třmi, kterýž pozdvihl kopí svého proti třem stům, kteréž i pobil, a byl z těch tří nejslovoutnější.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 19, 'Z těch tří on jsa nejslavnější, byl knížetem jejich, a však oněm třem nebyl rovný.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 20, 'Banaiáš také syn Joiadův, syn muže udatného, velikých činů, z Kabsael, ten porazil dva reky Moábské. Tentýž sstoupiv, zabil lva v jámě, když byl sníh.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 21, 'Ten také zabil muže Egyptského, muže ku podivení, a měl Egyptský v rukou kopí. I šel k němu s holí, a vytrh kopí z ruky toho Egyptského, zabil ho kopím jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 22, 'To učinil Banaiáš syn Joiadův, kterýž také slovoutný byl mezi těmi třmi silnými.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 23, 'A ač byl mezi třidcíti nejslavnější, však oněm třem se nevrovnal. I ustanovil ho David nad drabanty svými.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 24, 'Azael také bratr Joábův byl mezi třidcíti těmito: Elchanan syn Dodův Betlémský,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 25, 'Samma Charodský, Elika Charodský,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 26, 'Chelez Faltický, Híra syn Ikeš Tekoitský,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 27, 'Abiezer Anatotský, Mebunnai Chusatský,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 28, 'Salmon Achochský, Maharai Netofatský,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 29, 'Cheleb syn Baany Netofatský, Ittai syn Ribai z Gabaa synů Beniamin,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 30, 'Banaiáš Faratonský, Haddai od potoku Gás,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 31, 'Abialbon Arbatský, Azmavet Barechumský,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 32, 'Eliachba Salbonský, z synů Jasen Jonata,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 33, 'Samma Hararský, Achiam syn Sárar Ararský,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 34, 'Elifelet syn Achasbai Machatského, Eliam syn Achitofelův Gilonský,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 35, 'Chezrai Karmelský, Farai Arbitský,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 36, 'Igal syn Nátanův z Soba, Báni Gádský,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 37, 'Zelek Ammonský, Nacharai Berotský, oděnec Joába syna Sarvie,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 38, 'Híra Itrejský, Gareb Itrejský,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 39, 'Uriáš Hetejský. Všech třidceti a sedm.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 1, 'Tedy opět prchlivost Hospodinova popudila se proti Izraelovi; nebo byl ponukl satan Davida na ně, řka: Jdi, sečti lid Izraelský a Judský.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 2, 'Protož řekl král Joábovi, hejtmanu vojska svého: Projdi i hned všecka pokolení Izraelská od Dan až k Bersabé, a sečtěte lid, abych věděl počet jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 3, 'Ale Joáb řekl králi: Přidejž Hospodin Bůh tvůj k lidu, jakž ho koli mnoho, stokrát více, a to aby oči pána mého krále viděly. Ale proč pán můj král jest toho tak žádostiv?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 4, 'A však přemohla řeč králova Joába i knížata vojska. Protož vyšel Joáb a knížata vojska od tváři královy, aby sečtli lid Izraelský.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 5, 'A přepravivše se přes Jordán, položili se při Aroer po pravé straně města, kteréž jest u prostřed potoka Gád, a při Jazer.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 6, 'Potom přišli do Galád a do země dolejší nové, odkudž šli do Dan Jáhan a do okolí Sidonského.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 7, 'Přišli také ku pevnosti Týru, a ke všem městům Hevejských a Kananejských; odkudž šli na poledne země Judské do Bersabé.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 8, 'A když schodili všecku zemi, přišli po přeběhnutí devíti měsíců a dvadcíti dní do Jeruzaléma.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 9, 'I dal Joáb počet sečteného lidu králi. Bylo pak lidu Izraelského osmkrát sto tisíc mužů silných, kteříž mohli vytrhnouti meč k bitvě. Mužů také Judských pětkrát sto tisíc.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 10, 'Potom padlo to těžce na srdce Davidovi, když již sečtl lid. I řekl David Hospodinu: Zhřešilť jsem těžce, že jsem to učinil, ale nyní, ó Hospodine, odejmi, prosím, nepravost služebníka svého, nebť jsem velmi bláznivě učinil.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 11, 'Když pak vstal David ráno, stalo se slovo Hospodinovo k Gádovi proroku, vidoucímu Davidovu, řkoucí:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 12, 'Jdi a rci Davidovi: Toto praví Hospodin: Trojíť věci podávám, vyvol sobě jednu z nich, kteroužť bych učinil.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 13, 'Protož přišed Gád k Davidovi, oznámil mu to, a řekl jemu: Chceš-li, aby přišel na tebe hlad za sedm let v zemi tvé? čili abys za tři měsíce utíkal před nepřátely svými, a oni aby tě honili? čili aby za tři dni byl mor v zemi tvé? Pomysliž spěšně, a viz, jakou mám odpověd dáti tomu, kterýž mne poslal.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 14, 'I řekl David k Gádovi: Úzkostmi sevřín jsem náramně; nechať, prosím, upadneme v ruku Hospodinovu, neboť jsou mnohá slitování jeho, jediné ať v ruce lidské neupadám.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 15, 'A tak uvedl Hospodin mor na Izraele od jitra až do času uloženého, a zemřelo jich z lidu od Dan až do Bersabé sedmdesáte tisíc mužů.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 16, 'A když vztáhl anděl ruku svou na Jeruzalém, aby hubil jej, litoval Hospodin toho zlého, a řekl andělu, kterýž hubil lid: Dostiť jest, již přestaň. Anděl pak Hospodinův byl u humna Aravny Jebuzejského.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 17, 'I mluvil David Hospodinu, když uzřel anděla, an bije lid, a řekl: Aj, já jsem zhřešil, a já jsem neprávě učinil, ale tito, jsouce jako ovce, co učinili? Nechť jest, prosím, ruka tvá proti mně a proti domu otce mého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 18, 'Potom navrátiv se Gád k Davidovi v ten den, řekl jemu: Vstup a vzdělej Hospodinu oltář na humně Aravny Jebuzejského.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 19, 'I šel David vedlé řeči Gádovy, jakož byl přikázal Hospodin.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 20, 'A vyhlédaje Aravna, uzřel krále s služebníky jeho, an jdou k němu; protož vyšed Aravna, poklonil se králi tváří svou až k zemi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 21, 'I řekl Aravna: Proč přišel pán můj král k služebníku svému? Odpověděl David: Abych koupil od tebe humno toto, na němž bych vzdělal oltář Hospodinu, aby přestala rána tato v lidu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 22, 'Opět řekl Aravna Davidovi: Nechť vezme a obětuje pán můj král, což se mu za dobré vidí. Aj, teď volové k oběti zápalné, a smyky vozové i přípravy volů na drva.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 23, 'Všecky ty věci dával králík Aravna králi. Řekl ještě Aravna králi: Hospodin Bůh tvůj zalibiž tě sobě.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 24, 'Řekl pak král Aravnovi: Nikoli, ale raději koupím od tebe, a zaplatím, aniž budu obětovati Hospodinu Bohu svému oběti zápalné darem dané. A tak koupil David humno a voly za padesáte lotů stříbra.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 25, 'A vzdělav tu David oltář Hospodinu, obětoval oběti zápalné a pokojné. I byl milostiv Hospodin zemi, a přestala zhouba v Izraeli.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 1, 'Král pak David sstaral se a sešel věkem, a ačkoli jej šaty přikrývali, však nemohl se zahřívati.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 2, 'I řekli jemu služebníci jeho: Nechť pohledají pánu našemu králi děvečky panny, kteráž by byla při králi a opatrovala jej, a aby spala v lůnu jeho, a zahřívala pána našeho krále.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 3, 'A protož hledajíce děvečky krásné ve všech končinách Izraelských, nalezli Abizag Sunamitskou, a přivedli ji k králi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 4, 'Kterážto děvečka byla velmi krásná. I opatrovala krále a přisluhovala jemu, ale král jí nepoznal.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 5, 'Adoniáš pak syn Haggity pozdvihoval se, říkaje: Jáť budu kralovati. I najednal sobě vozů a jezdců, a padesáte mužů, kteříž by běhali před ním.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 6, 'A nikdy ho nezarmoutil otec jeho, aby řekl: Proč jsi to učinil? Nebo byl i on velmi krásné postavy, kteréhož porodila po Absolonovi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 7, 'I mluvíval s Joábem synem Sarvie a s Abiatarem knězem, kteříž napomáhali Adoniášovi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 8, 'Ale Sádoch kněz a Banaiáš syn Joiadův, též Nátan prorok a Simei i Rehi, a jiní přednější, kteréž měl David, nebyli s Adoniášem.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 9, 'Tedy nabil Adoniáš ovcí a volů a krmného dobytka u kamene Zohelet, kterýž byl u studnice Rogel, a pozval všech bratří svých synů královských, i všech mužů Judských, služebníků králových.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 10, 'Nátana však proroka a Banaiáše a jiných přednějších mužů, ani Šalomouna bratra svého nepozval.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 11, 'I mluvil Nátan k Betsabé matce Šalomounově, řka: Neslyšela-lis, že kraluje Adoniáš syn Haggity, a pán náš David nic neví o tom?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 12, 'Protož nyní poď, prosím, a dámť radu, kterouž vysvobodíš život svůj, i život syna svého Šalomouna.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 13, 'Jdiž, a vejda k králi Davidovi, rci jemu: Zdaliž jsi ty, pane můj králi, nepřisáhl služebnici své, řka: Šalomoun syn tvůj kralovati bude po mně, a onť seděti bude na stolici mé? Pročež tedy kraluje Adoniáš?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 14, 'A aj, když ty ještě tam mluviti budeš s králem, přijduť za tebou a doplním řeč tvou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 15, 'A tak vešla Betsabé k králi do pokoje. Král pak již byl velmi starý, a Abizag Sunamitská přisluhovala králi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 16, 'Tedy Betsabé naklonivši hlavy, poklonila se králi. Jížto řekl král: Což chceš?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 17, 'I odpověděla jemu: Pane můj, ty jsi přisáhl skrze Hospodina Boha svého služebnici své, řka: Šalomoun syn tvůj kralovati bude po mně, a on seděti bude na stolici mé.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 18, 'A nyní, hle, Adoniáš kraluje, ty pak nyní, pane můj králi, nic nevíš o tom.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 19, 'Nebo nabiv volů a krmného dobytka a ovec množství, pozval všech synů královských, i Abiatara kněze a Joába hejtmana vojska, Šalomouna pak služebníka tvého nepozval.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 20, 'Ješto ty, pane můj králi, víš, že oči všeho Izraele na tebe jsou obráceny, abys jim oznámil, kdo by seděti měl na stolici pána mého krále po tobě.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 21, 'Sic jinak bude to, když usne pán můj král s otci svými, že já a syn můj Šalomoun budeme jako hříšníci.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 22, 'A aj, když ještě ona mluvila s králem, přišel Nátan prorok.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 23, 'I oznámili králi, řkouce: Aj, teď Nátan prorok. A tak všel před krále, a poklonil se jemu tváří svou až k zemi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 24, 'Zatím řekl Nátan: Pane můj králi, ty-lis pověděl: Adoniáš kralovati bude po mně, a on seděti bude na stolici mé?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 25, 'Nebo odšed dnes, nabil volů a krmného dobytka, i ovec množství, a sezval všecky syny královy a hejtmany vojska, i Abiatara kněze. A hle, oni jedí a pijí před ním, a praví: Živ buď král Adoniáš.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 26, 'Mne pak služebníka tvého, a Sádocha kněze, a Banaiáše syna Joiadova, a Šalomouna služebníka tvého nepozval.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 27, 'Tak-liž jest ode pána mého krále nařízeno? Mně jsi zajisté neoznámil služebníku svému, kdo bude seděti na stolici pána mého krále po tobě?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 28, 'A odpovídaje král David, řekl: Zavolejte mi Betsabé. Kteráž všedši před krále, stála před ním.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 29, 'I přisáhl král, řka: Živť jest Hospodin, kterýž vysvobodil duši mou ze všelikých úzkostí,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 30, 'Že jakož jsem přisáhl tobě skrze Hospodina Boha Izraelského, řka, že syn tvůj Šalomoun kralovati bude po mně, a on seděti bude na stolici mé místo mně, takť učiním dnes.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 31, 'A naklonivši hlavy Betsabé tváří k zemi, poklonu učinila králi a řekla: Živ buď pán můj král David na věky.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 32, 'Řekl ještě král David: Zavolejte ke mně Sádocha kněze a Nátana proroka, a Banaiáše syna Joiadova. Kteřížto vešli před krále.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 33, 'I řekl jim král: Vezměte s sebou služebníky pána svého, a vsaďte Šalomouna syna mého na mezkyni mou, a veďte ji k Gihonu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 34, 'I pomaže ho tam Sádoch kněz a Nátan prorok za krále nad Izraelem, a troubiti budete troubou, a díte: Živ buď král Šalomoun.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 35, 'Potom vstoupíte zase, jdouce za ním. Kterýž přijda, seděti bude na stolici mé, a on kralovati bude místo mne; nebť jsem jemu přikázal, aby byl vůdcí nad Izraelem i nad Judou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 36, 'A odpovídaje Banaiáš syn Joiadův králi, řekl: Amen. Způsobiž to Hospodin, Bůh pána mého krále.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 37, 'A jakož byl Hospodin se pánem mým králem, tak budiž i s Šalomounem, a zvelebiž stolici jeho více, než stolici pána mého krále Davida.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 38, 'A tak šli dolů Sádoch kněz a Nátan prorok, a Banaiáš syn Joiadův, Cheretejští také i Peletejští, a vsadili Šalomouna na mezkyni krále Davida, a dovedli jej k Gihonu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 39, 'Vzal také Sádoch kněz roh oleje z stánku, a pomazal Šalomouna. Potom troubili trubou, a řekl všecken lid: Živ buď král Šalomoun.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 40, 'I vstoupil všecken lid za ním; kterýžto lid prozpěvoval s plésáním, a veselil se radostí velikou, tak až se všudy rozléhalo od zvuku jejich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 41, 'Což slyše Adoniáš i všickni pozvaní, kteříž byli s ním, (byli pak již pojedli,) slyše také i Joáb zvuk trouby, řekl: Jaký to zvuk v městě hlučících?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 42, 'A když on ještě mluvil, aj, Jonata syn Abiatara kněze přišel, jemuž řekl Adoniáš: Přistup sem, nebo jsi muž udatný a dobré poselství neseš.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 43, 'Tedy odpovídaje Jonata, řekl Adoniášovi: Právě jižtě pán náš král David ustanovil Šalomouna za krále.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 44, 'Nebo poslal s ním král Sádocha kněze a Nátana proroka a Banaiáše syna Joiadova, ano i Cheretejské a Peletejské, a vsadili jej na mezkyni královskou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 45, 'I pomazali jej Sádoch kněz a Nátan prorok za krále u Gihonu, a vstupovali odtud s radostí, tak že hlučelo město. Toť jest zvuk ten, kterýž jste slyšeli.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 46, 'Ano již i dosedl Šalomoun na stolici královskou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 47, 'Nýbrž i služebníci královští přišli, aby dobrořečili pánu našemu, králi Davidovi, řkouce: Učiniž slavné Bůh tvůj jméno Šalomounovo nad jméno tvé, a zvelebiž stolici jeho nad stolici tvou. I poklonil se král na ložci svém.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 48, 'Ano i král takto řekl: Požehnaný Hospodin Bůh Izraelský, kterýž dal dnes sedícího na trůnu mém, a abych na to očima svýma hleděl.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 49, 'I předěšeni jsou, a vstavše všickni ti pozvaní, kteříž byli při Adoniášovi, odešli jeden každý cestou svou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 50, 'Adoniáš také boje se Šalomouna, vstav, odšel a chytil se rohů oltáře.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 51, 'I pověděli Šalomounovi, řkouce: Aj, Adoniáš bojí se krále Šalomouna, a hle, drží se rohů oltáře a praví: Nechť mi přisáhne dnes král Šalomoun, že nezabije mne služebníka svého mečem.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 52, 'I řekl Šalomoun: Bude-li muž statečný, nespadneť vlas s něho na zem; pakliť co zlého na něm nalezeno bude, umřeť.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 53, 'Poslal tedy král Šalomoun, aby jej odvedli od oltáře. Kterýž přišed, poklonil se králi Šalomounovi. Jemuž řekl Šalomoun: Jdiž do domu svého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 1, 'Když se pak čas smrti Davidovy přiblížil, dával přikázaní Šalomounovi synu svému, řka:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 2, 'Jáť již odcházím podlé způsobu všech lidí. Proto posilniž se a měj se zmužile,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 3, 'A ostříhej přikázaní Hospodina Boha svého, chodě po cestách jeho, a zachovávaje ustanovení jeho, rozkázaní jeho, i soudy jeho i svědectví jeho, jakož psáno jest v zákoně Mojžíšově, ať by se šťastně vedlo, což bys koli činil, i všecko, k čemuž bys se obrátil,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 4, 'A aby naplnil Hospodin slovo své, kteréž mi zaslíbil, mluvě: Budou-li ostříhati synové tvoji cesty své, chodíce přede mnou v pravdě z celého srdce svého a z celé duše své, tak mluvě: Že nebude vypléněn po tobě muž z stolice Izraelské.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 5, 'Také i tom víš, co jest mi učinil Joáb syn Sarvie, totiž, co učinil dvěma hejtmanům vojsk Izraelských, Abnerovi synu Ner, a Amazovi synu Jeter, že je zamordoval, dopustiv se vraždy lstivé v čas pokoje, a zmazal krví zrádně vylitou pás svůj rytířský, kterýž měl na bedrách svých, a obuv svou, kterouž měl na nohách svých.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 6, 'Protož zachováš se podlé moudrosti své, a nedáš sstoupiti šedinám jeho v pokoji do hrobu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 7, 'S syny pak Barzillai Galádského učiníš milosrdenství, tak aby jídali spolu s jinými při stole tvém; nebo tak podobně ke mně přišli, když jsem utíkal před Absolonem bratrem tvým.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 8, 'Hle, máš také v moci své Semei syna Gery Beniaminského z Bahurim, kterýž mi zlořečil zlořečením velikým v ten den, když jsem šel do Mahanaim, ačkoli potom vyšel mi vstříc k Jordánu, jemuž jsem přisáhl skrze Hospodina, řka: Nezabiji tě mečem.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 9, 'Nyní však neodpouštěj jemu. A poněvadž jsi muž opatrný, víš, jak bys k němu přistoupiti měl, abys uvedl šediny jeho se krví do hrobu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 10, 'A tak usnul David s otci svými, a pohřben jest v městě Davidově.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 11, 'Dnů pak, v nichž kraloval David nad Izraelem, bylo čtyřidceti let. V Hebronu kraloval sedm let, a v Jeruzalémě kraloval třidceti a tři léta.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 12, 'I dosedl Šalomoun na stolici Davida otce svého, a utvrzeno jest království jeho velmi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 13, 'Tedy přišel Adoniáš syn Haggity k Betsabé matce Šalomounově. Kterážto řekla: Pokojný-li jest příchod tvůj? I odpověděl: Pokojný.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 14, 'Řekl dále: Mám k tobě řeč. I řekla: Mluv.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 15, 'Tedy řekl: Ty víš, že mé bylo království, a na mne obrátili všickni Izraelští tvář svou, abych kraloval, ale přeneseno jest království na bratra mého, nebo od Hospodina usouzeno mu bylo.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 16, 'Nyní pak jediné věci žádám od tebe, nechť nejsem oslyšán. Kteráž řekla jemu: Mluv.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 17, 'A on řekl: Rci, prosím, Šalomounovi králi, (neboť neoslyší tebe,) ať mi dá Abizag Sunamitskou za manželku.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 18, 'Odpověděla Betsabé: Dobře, jáť budu mluviti o tebe s králem.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 19, 'Protož vešla Betsabé k králi Šalomounovi, aby mluvila s ním o Adoniáše. I povstal král proti ní, a pokloniv se jí, posadil se na stolici své; rozkázal také postaviti stolici matce své. I posadila se po pravici jeho,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 20, 'A řekla: Jediné věci neveliké já žádám od tebe, nechť nejsem oslyšána. I řekl jí král: Žádej, matko má, neboť neoslyším tebe.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 21, 'Kteráž řekla: Nechť jest dána Abizag Sunamitská Adoniášovi bratru tvému za manželku.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 22, 'A odpovídaje král Šalomoun, řekl matce své: Proč ty jen žádáš za Abizag Sunamitskou Adoniášovi? Žádej jemu království, poněvadž on jest bratr můj starší nežli já, a má po sobě Abiatara kněze a Joába syna Sarvie.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 23, 'I přisáhl král Šalomoun skrze Hospodina, řka: Toto ať mi učiní Bůh a toto přidá, že sám proti sobě mluvil Adoniáš řeč tuto.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 24, 'Protož nyní, živť jest Hospodin, kterýž mne utvrdil, a posadil na stolici Davida otce mého, a kterýž mi vzdělal dům, jakož byl mluvil, že dnes umříti musí Adoniáš.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 25, 'A tak poslal král Šalomoun Banaiáše syna Joiadova, kterýž udeřil na něj, tak že umřel.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 26, 'Abiatarovi knězi také řekl král: Jdi do Anatot k rolí své, nebo jsi hoden smrti. Ale nyní nezabiji tebe, poněvadž jsi nosil truhlu Hospodinovu před Davidem otcem mým, a snášel jsi všecka ta ssoužení, kteráž snášel otec můj.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 27, 'I svrhl Šalomoun Abiatara s kněžství Hospodinova, aby naplnil řeč Hospodinovu, kterouž byl mluvil proti domu Elí v Sílo.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 28, 'Donesla se pak pověst ta Joába, (nebo Joáb postoupil po Adoniášovi, ačkoli po Absolonovi byl nepostoupil). Protož utekl Joáb k stánku Hospodinovu, a chytil se rohů oltáře.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 29, 'I oznámeno králi Šalomounovi, že utekl Joáb k stánku Hospodinovu, a že jest u oltáře. Tedy poslal Šalomoun Banaiáše syna Joiadova, řka: Jdi, oboř se na něj.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 30, 'A když přišel Banaiáš k stánku Hospodinovu a řekl jemu: Takto praví král: Vyjdi, odpověděl jemu: Nikoli, ale tuto umru. V tom oznámil zase Banaiáš králi řeč tu, řka: Takto mluvil Joáb, a tak mi odpověděl.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 31, 'Na to řekl jemu král: Učiň, jakž mluvil, a udeř na něj, a pochovej jej, a odejmeš krev nevinnou, kterouž vylil Joáb, ode mne i od domu otce mého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 32, 'A navrátí Hospodin krev jeho na hlavu jeho; nebo obořiv se na dva muže spravedlivější a lepší, než jest sám, zamordoval je mečem bez vědomí otce mého Davida, Abnera syna Ner, hejtmana vojska Izraelského, a Amazu syna Jeter, hejtmana vojska Judského.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 33, 'A tak navrátí se krev jejich na hlavu Joábovu, a na hlavu semene jeho na věky, Davidovi pak a semeni jeho, domu jeho a stolici jeho buď pokoj až na věky od Hospodina.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 34, 'A protož vyšed Banaiáš syn Joiadův, obořil se na něj, a zabil jej. A pochován jest v domě svém na poušti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 35, 'I ustanovil král Banaiáše syna Joiadova místo něho nad vojskem, a Sádocha kněze ustanovil král místo Abiatara.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 36, 'Zatím poslav král, povolal Semei, a řekl jemu: Ustavěj sobě dům v Jeruzalémě, a tu zůstávej a nevycházej odtud ani sem ani tam.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 37, 'Nebo v kterýkoli den vyjdeš, a přejdeš přes potok Cedron, věz jistotně, že umřeš; krev tvá bude na hlavu tvou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 38, 'I dí Semei k králi: Dobráť jest ta řeč. Jakož mluvil pán můj král, takť učiní služebník tvůj. A tak bydlil Semei v Jeruzalémě po mnohé dny.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 39, 'Stalo se pak po třech letech, že utekli dva služebníci Semei k Achisovi synu Maachy, králi Gát. I pověděli to Semei, řkouce: Hle, služebníci tvoji jsou v Gát.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 40, 'Pročež vstav Semei, osedlal osla svého, a jel do Gát k Achisovi, aby hledal služebníků svých. I navrátil se Semei, a přivedl zase služebníky své z Gát.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 41, 'Povědíno pak Šalomounovi, že odšel Semei z Jeruzaléma do Gát, a že se navrátil.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 42, 'Tedy poslav král, povolal Semei a řekl jemu: Zdaliž jsem tě přísahou nezavázal skrze Hospodina, a osvědčil jsem proti tobě, řka: V kterýkoli den vyjdeš, a sem i tam choditi budeš, věz jistotně, že smrtí umřeš? A řekl jsi mi: Dobrá jest ta řeč, kterouž jsem slyšel.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 43, 'Pročež jsi tedy neostříhal přísahy Hospodinovy a přikázaní, kteréž jsem přikázal tobě?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 44, 'Řekl také král k Semei: Ty víš všecko zlé, kteréhož povědomo jest srdce tvé, co jsi učinil Davidovi otci mému, ale Hospodin uvedl zase to tvé zlé na hlavu tvou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 45, 'Král pak Šalomoun bude požehnaný, a stolice Davidova stálá před Hospodinem až na věky.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 46, 'I přikázal král Banaiášovi synu Joiadovu, kterýž vyšed, obořil se na něj, tak že umřel. A tak utvrzeno jest království v ruce Šalomounově.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 1, 'Spříznil se pak Šalomoun s Faraonem králem Egyptským, nebo pojal dceru Faraonovu a uvedl ji do města Davidova, dokudž nedostavěl domu svého, a domu Hospodinova i zdi Jeruzalémské vůkol.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 2, 'Toliko lid obětoval na výsostech, proto že nebyl vystaven dům jménu Hospodinovu až do těch dnů.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 3, 'Nebo miloval Šalomoun Hospodina, chodě v přikázaních Davida otce svého, a toliko na těch výsostech obětoval a kadil.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 4, 'Protož šel král do Gabaon, aby tam obětoval; ta výsost zajisté byla největší. Tisíc obětí zápalných obětoval Šalomoun na tom oltáři.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 5, 'Ukázal se pak Hospodin v Gabaon Šalomounovi ve snách noci té, a řekl Bůh: Žádej začkoli, a dám tobě.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 6, 'I řekl Šalomoun: Ty jsi učinil s služebníkem svým Davidem, otcem mým, milosrdenství veliké, když chodil před tebou v pravdě a v spravedlnosti, a v upřímnosti srdce stál při tobě. Ovšem zachoval jsi jemu zvláštní toto milosrdenství, že jsi dal jemu syna, kterýž by seděl na stolici jeho, jakž se to dnes vidí.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 7, 'Ačkoli pak nyní, ó Hospodine Bože můj, ty jsi ustanovil služebníka svého králem místo Davida otce mého, já však jsa velmi mladý, neumím vycházeti ani vcházeti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 8, 'Služebník, pravím, tvůj jest u prostřed lidu tvého, kterýž jsi vyvolil, lidu velikého, kterýž nemůže ani sečten ani sepsán býti pro množství.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 9, 'Dejž tedy služebníku svému srdce rozumné, aby soudil lid tvůj, a aby rozeznal mezi dobrým a zlým; nebo kdo bude moci souditi tento lid tvůj tak mnohý?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 10, 'I líbilo se to Hospodinu, že žádal Šalomoun za tu věc.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 11, 'A řekl jemu Bůh: Proto že jsi žádal věci takové, a neprosils sobě za dlouhý věk, aniž jsi žádal sobě bohatství, aniž jsi žádal bezživotí nepřátel svých, ale žádal jsi sobě rozumnosti, abys slýchati uměl rozepře,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 12, 'Aj, učinil jsem vedlé řeči tvé, aj, dalť jsem srdce moudré a rozumné, tak že rovného tobě nebylo před tebou, ani po tobě aby nepovstal rovný tobě.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 13, 'K tomu i to, začež jsi nežádal, dal jsem tobě, totiž bohatství a slávu, tak aby nebylo rovného tobě žádného mezi králi po všecky dny tvé.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 14, 'Přes to jestliže choditi budeš po cestách mých, ostříhaje ustanovení mých a přikázaní mých, jako chodil David otec tvůj, prodlím i dnů tvých.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 15, 'A když procítil Šalomoun, a aj, byl sen. I přišel do Jeruzaléma a stál před truhlou smlouvy Hospodinovy, a obětoval oběti zápalné a oběti pokojné; udělal také hody všechněm služebníkům svým.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 16, 'Tedy přišly dvě ženy hokyně k králi, a stály před ním.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 17, 'I řekla jedna z těch žen: Prosím, pane můj, já a žena tato bydlíme v jednom domě. I porodila jsem u ní v témž domě.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 18, 'Potom stalo se dne třetího po porodu mém, že porodila také žena tato, a byly jsme spolu. Nebylo žádného cizího s námi v domě, kromě nás dvou v témž domě.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 19, 'Umřel pak syn ženy této v noci, nebo spěci, udávila ho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 20, 'A vstavši o půl noci, vzala syna mého ode mne, když spala služebnice tvá, a položila jej v lůnu svém, a syna svého mrtvého položila do lůna mého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 21, 'Ale když jsem vstala ráno, abych přikojila syna svého, a aj, mrtvý. Na kteréhož když jsem ráno pilněji pohleděla, a aj, nebyl syn můj, kteréhož jsem porodila.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 22, 'I řekla žena druhá: Není tak, ale syn můj jest ten živý, a ten mrtvý jest syn tvůj. Ona pak řekla: Nikoli, ale syn tvůj jest ten mrtvý, a syn můj jest ten živý. A tak se hádaly před králem.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 23, 'I řekl král: Tato praví: Ten živý jest syn můj, a syn tvůj jest ten mrtvý. Tato zase praví: Neníť tak, ale syn tvůj jest ten mrtvý, a syn můj jest ten živý.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 24, 'Protož řekl král: Přineste mi meč. I přinesli meč před krále.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 25, 'Tedy řekl král: Rozetněte to dítě živé na dvé, a dejte jednu polovici jedné, a polovici druhou druhé.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 26, 'Ale žena, jejíž syn byl ten, kterýž živ zůstal, mluvila králi, (nebo pohnula se střeva její nad synem jejím,) a řekla: Prosím, pane můj, dejte jí nemluvňátko to živé, a nikoli nezabijejte ho. Druhá pak řekla: Nechť není ani mně ani tobě, rozetněte.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 27, 'K čemuž odpovídaje král, řekl: Dejtež této dítě to živé, a nikoli nezabijejte ho, onať jest matka jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 28, 'Tedy uslyšavše všickni Izraelští soud tento, kterýž vynesl král, báli se krále; nebo viděli, že moudrost Boží jest v srdci jeho k vykonávání soudu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 1, 'A tak král Šalomoun byl králem nade vším Izraelem.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 2, 'Tato pak byla knížata jeho: Azariáš syn Sádochův knížetem,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 3, 'Elichoref a Achiáš synové Sísovi byli písaři, Jozafat syn Achiludův kancléřem,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 4, 'A Banaiáš syn Joiadův nad vojskem, Sádoch pak a Abiatar kněžími,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 5, 'A Azariáš syn Nátanův nad úředníky, a Zábud syn Nátanův nejvyšší rada královská,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 6, 'A Achisar vládař domu, Adoniram pak syn Abdy nad vybraným lidem.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 7, 'Měl také Šalomoun dvanácte vládařů nade vším Izraelem, kteříž opatrovali potravou krále i dům jeho. Každého roku za měsíc jeden každý měl opatrovati krále.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 8, 'A tato jsou jména jejich: Syn Chur na hoře Efraim;');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 9, 'Syn Deker v Makaz a v Salbim, a v Betsemes a v Elon Betchanan;');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 10, 'Syn Chesed v Arubot, jehož bylo Socho i všecka země Chefer;');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 11, 'Syn Abinadabův, jehož byly všecky končiny Dor, a měl Tafat dceru Šalomounovu za manželku;');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 12, 'Baana syn Achiludův, jehož byl Tanach a Mageddo, i všecken Betsan, kterýž jest vedlé Sartan pod Jezreelem, od Betsan až do Abelmehula a až za Jekmaam;');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 13, 'Syn Geber v Rámot Galád, jehož byly vsi Jair, syna Manassesova, kteréž jsou v Galád, jehož byla krajina Argob, kteráž jest v Bázan, šedesáte měst velikých hrazených a závřitých;');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 14, 'Achinadab syn Iddo v Mahanaim;');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 15, 'Achimaas v Neftalím, on také pojal Basemat dceru Šalomounovu za manželku;');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 16, 'Baana syn Chusai v Asser a v Alot;');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 17, 'Jozafat syn Paruach v Izachar;');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 18, 'Semei syn Ela v Beniamin;');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 19, 'Geber syn Uri v zemi Galád, v zemi Seona, krále Amorejského, a Oga krále Bázan; ten sám vládařem jedním představen byl té zemi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 20, 'Tehdáž Juda a Izrael rozmnoženi jsouce jako písek při moři v množství, jedli a pili, a veselili se.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 21, 'Nebo Šalomoun panoval nade všemi královstvími od řeky až k zemi Filistinské, a až k končinám Egyptským. I přinášeli dary a sloužili Šalomounovi po všecky dny života jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 22, 'Vycházelo pak ku potravě Šalomounovi na každý den třidceti měr běli, a šedesáte měr mouky obecné,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 23, 'Deset volů krmných a dvadceti volů pastevných, a sto ovec, kromě jelenů, srn, bůvolů a ptactva vykrmeného.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 24, 'On zajisté panoval všudy s této strany řeky od Tipsach až do Gázy nade všemi králi, kteříž byli před řekou, a měl pokoj se všech stran vůkol.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 25, 'I bydlil Juda a Izrael bezpečně, jeden každý pod svým vinným kmenem a pod svým fíkem, od Dan až do Bersabé, po všecky dny Šalomounovy.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 26, 'Měl také Šalomoun čtyřidceti tisíc koní na stání k vozům svým, a dvanácte tisíc jízdných.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 27, 'A tak opatrovali ti úředníci krále Šalomouna i všecky, kteříž přicházeli k stolu krále Šalomouna, jeden každý za měsíc svůj, nedopouštějíce, aby v čem nedostatek býti měl.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 28, 'Ječmene také a slámy pro koně a pro mezky dodávali k tomu místu, kdež byl král, jeden každý, jakž mu uloženo bylo.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 29, 'Nadto dal Bůh moudrost Šalomounovi a prozřetelnost velikou náramně, a širokost mysli, jako jest písku na břehu mořském.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 30, 'Nebo větší byla moudrost Šalomounova, než moudrost všech národů východních, a než všeliká moudrost Egyptských.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 31, 'Nýbrž moudřejší byl nad všecky lidi, až i nad Etana Ezrachitského, též nad Hémana, a Kalkole i Darda, syny Máchol, a rozneslo se jméno jeho po všech národech vůkol.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 32, 'Složil také tři tisíce přísloví, a písniček jeho bylo tisíc a pět.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 33, 'Vypsal též i o stromích, počna od cedru, kterýž jest na Libánu, až do mchu, kterýž roste na zdi; psal i o hovadech a o ptácích, a zeměplazích a o rybách.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 34, 'Protož přicházeli ze všech národů poslouchati moudrosti Šalomounovy, i ode všech králů země, kteříž slyšeli o moudrosti jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 1, 'Poslal pak Chíram král Tyrský služebníky své k Šalomounovi, uslyšav, že ho pomazali za krále na místo otce jeho; nebo miloval Chíram Davida po všecky dny.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 2, 'Zase poslal Šalomoun k Chíramovi, řka:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 3, 'Ty víš, že David otec můj nemohl vystavěti domu jménu Hospodina Boha svého pro války, kteréž jej obkličovaly, dokudž Hospodin nepodložil nepřátel pod nohy jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 4, 'Ale nyní Hospodin Bůh můj dal mi odpočinutí všudy vůkol, není žádného protivníka, ani outoku nebezpečného.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 5, 'Z té příčiny, aj, úmysl mám stavěti dům jménu Hospodina Boha svého, jakož mluvil Hospodin Davidovi otci mému, řka: Syn tvůj, kteréhož posadím místo tebe na stolici tvé, onť vystaví dům ten jménu mému.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 6, 'A protož nyní rozkaž, ať mi nasekají cedrů na Libánu. Budou pak služebníci moji s služebníky tvými, a mzdu služebníků tvých dám tobě, tak jakž díš. Nebo sám víš, že mezi námi není žádného, kdož by uměl sekati dříví, jako jsou Sidonští.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 7, 'Stalo se tedy, když uslyšel Chíram ta slova Šalomounova, že se zradoval náramně, a řekl: Požehnaný Hospodin budiž nyní, kterýž dal Davidovi syna moudrého nad tím lidem tak mnohým.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 8, 'I poslal Chíram k Šalomounovi, řka: Vyrozuměl jsem, oč jsi poslal ke mně; jáť učiním všecku vůli tvou z strany dříví cedrového i jedlového.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 9, 'Služebníci moji svezou je s Libánu až k moři, a dám je v vořích splaviti po moři až k místu tomu, kteréž mi ukážeš, a tu je složím; ty pak pobéřeš je a naplníš také vůli mou, dodávaje potravy čeledi mé.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 10, 'A tak dával Chíram Šalomounovi dříví cedrového a dříví jedlového, jakkoli mnoho chtěl.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 11, 'Šalomoun také dával Chíramovi dvadceti tisíc měr pšenice ku pokrmu čeledi jeho, a dvadceti tisíc měr oleje vytlačeného. To dával Šalomoun Chíramovi každého roku.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 12, 'Když tedy dal Hospodin moudrost Šalomounovi, jakož mu byl zaslíbil, a byl pokoj mezi Chíramem a mezi Šalomounem, tak že mezi sebou učinili smlouvu:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 13, 'Rozkázal král Šalomoun vybírati osoby ze všeho Izraele, a bylo vybraných třidceti tisíc mužů.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 14, 'Z nichž posílal na Libán deset tisíců na každý měsíc, jedny po druhých. Jeden měsíc bývali na Libánu, a dva měsíce doma, Adoniram pak byl ustaven nad těmi vybranými.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 15, 'Měl také Šalomoun sedmdesáte tisíc nosičů, a osmdesáte tisíc těch, kteříž tesali na hoře,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 16, 'Kromě předních vládařů Šalomounových, kterýchž bylo nad dílem tři tisíce a tři sta. Ti představeni byli lidem, kteříž dělali.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 17, 'I přikázal král, aby navozili kamení velikého, kamení nákladného k založení toho domu, a kamení tesaného,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 18, 'Kteréž tesali kameníci Šalomounovi a kameníci Chíramovi a Gibličtí. A tak připravovali dříví i kamení k stavení domu toho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 1, 'I stalo se léta čtyřstého osmdesátého po vyjití synů Izraelských z země Egyptské, že Šalomoun měsíce Ziv, (jenž jest měsíc druhý,) čtvrtého léta kralování svého nad Izraelem, počal stavěti domu Hospodinova.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 2, 'Dům pak, kterýž stavěl král Šalomoun Hospodinu, byl zdélí šedesáti loktů, a zšíří dvadcíti, a zvýší třidcíti loktů.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 3, 'Síňce také byla před chrámem dvadcíti loktů zdélí vedlé širokosti domu, a desíti loktů zšíří před domem.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 4, 'Udělal také v domě okna porozšířená vnitř, ale possoužená zevnitř.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 5, 'Vzdělal též při zdi domu pavlače všudy vůkol vedlé zdi domu, okolo chrámu a svatyně svatých, a nadělal pokojíků všudy vůkol.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 6, 'Pavlače spodní širokost byla pěti loket, prostřední širokost šesti loket, a třetí širokost sedmi loket; nebo byl zdělal ústupky ve zdi domu zevnitř všudy vůkol, aby trámové nebyli vpouštíni do zdi domu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 7, 'Když pak ten dům staven byl, z kamení hotového, tak přivezeného stavěli. Ani kladiva ani sekery, ani jakého nástroje železného nebylo slyšeti v domě, když byl staven.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 8, 'Dvéře k prostředním pokojům byly po pravé straně domu, jimiž po šneku se chodilo k těm prostředním, a z prostředních k třetím.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 9, 'A tak vystavěl dům ten, a dokonal jej, a přikryl jej krokvemi ohnutými a na to prkny cedrovými.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 10, 'Vystavěl i pavlače ty vůkol všeho domu. Pěti loket zvýši byla každá z nich, a připojeny byly k domu trámy cedrovými.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 11, 'Stala se pak řeč Hospodinova k Šalomounovi, řkoucí:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 12, 'Toť jest ten dům, kterýž ty stavíš. Jestliže budeš choditi v ustanoveních mých, a soudy mé vykonávati, a ostříhati všech přikázaní mých, chodě v nich, tedy upevním slovo své s tebou, kteréž jsem mluvil Davidovi otci tvému.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 13, 'A budu bydliti u prostřed synů Izraelských, a neopustím lidu svého Izraelského.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 14, 'A tak vystavěl Šalomoun ten dům, a dokonal jej.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 15, 'A otafloval zdi domu vnitř prkny cedrovými, od podlahy domu až k stropu obložil dřívím vnitř; položil také podlahu domu prkny jedlovými.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 16, 'Udělal také přehražení na dvadceti loket od jedné strany domu k druhé, z prken cedrových, od podlahy až do stropu. A tak udělal u vnitřku příbytek, aby byl svatyně svatých.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 17, 'Pročež čtyřidcíti loktů byl dům, jenž jest chrám přední.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 18, 'A na tom cedrovém domu vnitř o taflování byly řezby, nápodobné tykvím planým a květům otevřeným. Všecko z cedru bylo, tak že ani kamene nebylo viděti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 19, 'Svatyni pak svatých v domě vnitř připravil, aby tam postavena byla truhla smlouvy Hospodinovy.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 20, 'Kterážto svatyně svatých vnitř byla dvadcíti loktů zdélí, a dvadcíti loktů zšíří, též dvadcíti loktů zvýší, a obložil ji zlatem nejčistším. Oltář také cedrový obložil.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 21, 'Tak obložil Šalomoun příbytek ten zlatem nejčistším, a učinil rozdělující stěnu a provazy zlaté před svatyní svatých, kterouž také obložil zlatem.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 22, 'Anobrž všecken dům obložil zlatem, žádné strany nepomíjeje; též všecken oltář, kterýž byl před svatyní svatých, obložil zlatem.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 23, 'Udělal také v svatyni svatých dva cherubíny z dříví olivového desíti loket zvýší.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 24, 'A bylo na pět loket křídlo cherubína jedno, a na pět loket křídlo cherubína druhé; deset loket bylo od konce křídla jednoho až k konci křídla druhého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 25, 'Tak na deset loket byl i cherubín druhý; míru jednostejnou a řezbu jednostejnou měli oba cherubínové.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 26, 'Vysokost cherubína jednoho byla desíti loket, a tolikéž cherubína druhého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 27, 'I postavil ty cherubíny u prostřed domu vnitřního, tak že roztáhli křídla svá, a dotýkalo se křídlo jednoho jedné stěny, též křídlo cherubína druhého dotýkalo se druhé stěny; křídla pak jejich u prostřed domu spolu se dotýkala.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 28, 'Obložil také ty cherubíny zlatem.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 29, 'Přesto i všecky stěny domu vůkol ozdobil řezbami cherubínů a palm a rozvitých květů, vnitř i zevnitř.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 30, 'I podlahu domu položil zlatem vnitř i zevnitř.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 31, 'Udělal též, kudy vcházeli do svatyně svatých, dvéře z dříví olivového, a podvoje i s veřejemi byly pětihrané.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 32, 'Oboje pak ty dvéře byly z dříví olivového, kteréž ozdobil řezbami cherubínů a palm a rozvitých květů, a obložil zlatem; potáhl také i cherubíny a palmy zlatem.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 33, 'Podobně udělal i u vrat chrámových dvéře z dříví olivového čtverhrané.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 34, 'A oboje dvéře byly z dříví jedlového. Na dvě strany jedny dvéře otvíraly se, též na dvě strany druhé dvéře se otvíraly.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 35, 'I vyřezal na nich cherubíny a palmy a rozvité květy, a obložil zlatem taženým to, což bylo vyřezáno.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 36, 'Potom vystavěl síň prostřední ze tří řadů kamení tesaného, a jednoho řadu dříví cedrového hoblovaného.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 37, 'Léta čtvrtého založen byl dům Hospodinův, měsíce Ziv,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 38, 'A léta jedenáctého, měsíce Bul, (jenž jest měsíc osmý), dokonán jest dům se všemi přípravami svými, a se vším tím, což k němu přináleželo; kterýž stavěl sedm let.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 1, 'Potom stavěl Šalomoun dům svůj za třinácte let, až jej všelijak dostavěl.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 2, 'Vystavěl též dům z lesu Libánského, sto loket zdélí a padesáte loket zšíří a třidceti loket zvýší na čtyřech řadích sloupů cedrových, a trámové cedroví byli na těch sloupích.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 3, 'A přikryt byl cedrovím na hoře na těch trámích, kteříž byli na čtyřidcíti pěti sloupích, po patnácti v každém řadu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 4, 'Oken také byly tři řady, okno proti oknu třmi řady.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 5, 'A všecky dvéře i veřeje čtverhrané byly, i okna, a zpořádaná byla okna proti oknům třmi řady.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 6, 'Udělal i síňci na sloupích. Padesáti loket byla dlouhost její a třidcíti loket širokost její, a byla ta síňce napřed, i sloupové i trámové její před tím domem.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 7, 'Opět vzdělal jinou síňci, v níž byl trůn, kdež soudil, totiž síňci soudnou, kteráž přikryta byla cedrovím od jedné podlahy až do druhé.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 8, 'Potom při domu svém, v kterémž bydlil, udělal síň druhou za tou síní; dílo podobné onomu bylo. Udělal také dům dceři Faraonově, kterouž byl pojal Šalomoun, podobný té síňci.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 9, 'Všecko to bylo z kamení nákladného, vedlé míry tesaného a pilou řezaného, vnitř i zevnitř, a to od gruntu až k stropu, i zevnitř až k síni veliké.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 10, 'Základ také byl z kamení nákladného, z kamení velikého, z kamení na deset loket, a z kamení na osm loket.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 11, 'Tak i výš bylo kamení nákladné, příslušně vedlé míry tesané, a cedrové dsky.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 12, 'Síň také veliká měla všudy vůkol třmi řady kamení tesané, a jedním řadem dříví cedrové, podobně jako síň vnitřní domu Hospodinova, i síňce téhož domu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 13, 'Poslav pak král Šalomoun, povolal Chírama z Týru,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 14, '(Ten byl syn ženy vdovy z pokolení Neftalímova, jehož otec byl obyvatel Tyrský, řemeslník díla z mědi,) proto že byl plný moudrosti a rozumnosti i umění k dělání všelikého díla z mědi. Kterýžto když přišel k králi Šalomounovi, dělal všeliké dílo jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 15, 'Nejprv sformoval dva sloupy měděné. Osmnácti loket byla výsost sloupu jednoho, kterýž okolek měl dvanácti loktů. Tak i sloup druhý.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 16, 'Potom udělal dvě makovice, kteréž by vstaveny byly na vrch těch sloupů, slité z mědi. Pěti loktů byla zvýší makovice jedna, a pěti loktů zvýší makovice druhá.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 17, 'Mřežování také dílem pleteným, a šňůry jako řetízky udělal k těm makovicím, kteréž byly na vrchu sloupů, sedm na makovici jednu a sedm na makovici druhou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 18, 'A udělav sloupy, přidal k mřežování jednomu dva řady jablek zrnatých vůkol, aby makovice, kteréž byly na vrchu, přikrývaly. A tak učinil makovici druhé.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 19, 'Na těch pak makovicích na vrchu sloupů, kteříž v síňci státi měli, bylo dílo květem liliovým na čtyři lokty.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 20, 'I měly makovice ty na dvou těch sloupích, jakož svrchu tak i proti vydutí pod zamřežováním jablka zrnatá, kterýchž bylo dvě stě, dvěma řady vůkol, na jedné i na druhé makovici.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 21, 'A tak postavil ty sloupy v síňci chrámové. A postaviv sloup na pravé straně, nazval jméno jeho Jachin; a když postavil sloup na levé straně, nazval jméno jeho Boaz.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 22, 'A na vrchu sloupů těch bylo dílo liliové. I dokonáno jest dílo sloupů.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 23, 'Udělal také moře slité, desíti loket od jednoho kraje k druhému, okrouhlé vůkol, a pět loket byla vysokost jeho, a okolek jeho třidcíti loket vůkol.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 24, 'Pod jehožto krajem pukly tykvím polním podobné všudy vůkol, po desíti do lokte, obkličovaly moře vůkol; dva řady tykví litých bylo s ním slito.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 25, 'A stálo na dvanácti volích. Tři obráceni byli na půlnoci, a tři patřili k západu, tři zase postaveni byli ku poledni, a tři obráceni byli k východu, a moře svrchu na nich stálo, ale všech jich zadkové byli pod mořem.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 26, 'A bylo ztlouští na dlaň. Kraj jeho byl, jakýž bývá u koflíku aneb květu liliového; dva tisíce tun v se bralo.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 27, 'Udělal také deset podstavků měděných. Čtyř loket zdélí byl podstavek jeden každý, a čtyř loket zšíří, a tří loket zvýší.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 28, 'Bylo pak takové dílo každého podstavku; lištování bylo vůkol na nich, kteréžto lištování bylo po krajích jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 29, 'A na tom lištování, kteréž bylo po krajích, lvové, volové a cherubínové byli, a nad těmi kraji byl sloupec svrchu, a pod lvy a voly obruba dílem taženým.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 30, 'Bylo také po čtyřech kolách měděných pod každým podstavkem, a dsky měděné, a na čtyřech úhlech svých měli raménka; tolikéž i pod každou medenicí byla ta raménka slitá při každé obrubě.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 31, 'Zřídlo pak jeho mezi obrubou po vrchu bylo zhloubí lokte, a však okrouhlé, řemeslně jako i podstavek udělané, zšíří půl druhého lokte. Na kterémžto zřídle byly řezby, ale lištování jejich bylo čtverhrané, neokrouhlé.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 32, 'A tak po čtyřech kolách bylo pod tím lištováním, a osy kol vycházely z podstavků; vysokost kola každého byla půl druhého lokte.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 33, 'Dílo těch kol bylo jako dílo kol u vozu; osy jejich i písty jejich, loukoti jejich i špice jejich, všecko bylo slité.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 34, 'Tolikéž čtyři raménka na čtyřech úhlech podstavku každého, z něhož ta raménka vynikala.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 35, 'Na vrchu pak podstavku byl sloupek na půl lokte zvýší, okrouhlý vůkol, a na vrchu sloupku toho byli krajové vypuštění, a lištování na nich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 36, 'I zdělal řezby na dskách po krajích jejich, a po lištování jejich, cherubíny, lvy a palmoví, jedno podlé druhého po obrubě všudy vůkol.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 37, 'Na ten způsob udělal deset podstavků jednostejným slitím, na jednostejnou míru, a jednostejná řezba na všech byla.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 38, 'Udělal také deset umyvadel měděných. Čtyřidceti měr bralo v se jedno umyvadlo; čtyř loket bylo to každé umyvadlo, jedno umyvadlo na jednom podstavku, a tak na desíti podstavcích.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 39, 'I postavil podstavků pět po pravé straně domu, a pět po levé straně domu, moře pak postavil na pravé straně domu, k východu na poledne.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 40, 'Nadělav tedy Chíram umyvadel, a lopat a kotlíků, dokonal všecko dílo, kteréž dělal králi Šalomounovi k domu Hospodinovu:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 41, 'Dva sloupy a makovice okrouhlé, kteréž byly na vrchu dvou sloupů, a mřežování dvoje, aby přikrývalo ty dvě makovice okrouhlé, kteréž byly na vrchu sloupů;');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 42, 'A jablek zrnatých čtyři sta na dvojím mřežování; dva řady jablek zrnatých byly na mřežování jednom, aby přikrývaly dvě makovice okrouhlé, kteréž byly na vrchu sloupů;');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 43, 'Tolikéž podstavků deset, a umyvadel deset na podstavcích;');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 44, 'A moře jedno a volů dvanácte pod mořem;');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 45, 'Též hrnce a lopaty, a kotlíky. A všecko nádobí, kteréhož nadělal Chíram králi Šalomounovi do domu Hospodinova, bylo z mědi pulerované.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 46, 'Ty věci na rovinách Jordánských slíval král v jilovaté zemi, mezi Sochot a Sartan.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 47, 'Zanechal pak Šalomoun vážení všeho nádobí, pro množství veliké není vyhledáváno váhy mědi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 48, 'Nadělal také Šalomoun všeho jiného nádobí do domu Hospodinova: Oltář zlatý a stůl zlatý, na němž byli chlebové předložení,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 49, 'A svícnů pět na pravé a pět na levé straně před svatyní svatých z zlata nejčistšího, též květy a lampy i utěradla z zlata,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 50, 'I báně a žaltáře, kotlíky, kadidlnice a nádoby k oharkům z zlata čistého, i panty zlaté ke dveřím domu vnitřního, totiž svatyně svatých, a ke dveřím chrámovým.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 51, 'A tak dokonáno jest všecko dílo, kteréž dělal král Šalomoun k domu Hospodinovu, a vnesl tam Šalomoun věci posvěcené od Davida otce svého, stříbro a zlato i nádobí, složiv je mezi poklady domu Hospodinova.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 1, 'Tedy shromáždil Šalomoun k sobě do Jeruzaléma starší lidu Izraelského, a všecky přední z pokolení, totiž knížata čeledí otcovských s syny Izraelskými, aby přenesli truhlu smlouvy Hospodinovy z města Davidova, jenž jest Sion.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 2, 'I sešli se k králi Šalomounovi všickni muži Izraelští měsíce Etanim, v čas slavnosti; a ten měsíc jest sedmý.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 3, 'A když přišli všickni starší Izraelští, vzali kněží truhlu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 4, 'I přenesli truhlu Hospodinovu a stánek úmluvy, i všecka nádobí posvátná, kteráž byla v stánku; a tak přenesli to kněží a Levítové.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 5, 'Král pak Šalomoun i všecko shromáždění Izraelské, kteréž se k němu sešlo, obětovali s ním před truhlou ovce i voly, kteříž ani popisováni ani počítáni nebyli pro množství.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 6, 'I vnesli kněží truhlu smlouvy Hospodinovy na místo její, do vnitřního domu, totiž do svatyně svatých pod křídla cherubínů.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 7, 'Nebo cherubínové měli roztažená křídla nad místem truhly, a přikrývali cherubínové truhlu i sochory její svrchu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 8, 'A povytáhli sochorů, tak že vidíni byli koncové jejich v svatyni k předku svatyně svatých, avšak vně nebylo jich viděti; a byli tam až do tohoto dne.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 9, 'Nic nebylo v truhle kromě dvou tabulí kamenných, kteréž tam složil Mojžíš na Orébě, když všel Hospodin v smlouvu s syny Izraelskými, a oni šli z země Egyptské.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 10, 'I stalo se, když vycházeli kněží z svatyně, že oblak naplnil dům Hospodinův,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 11, 'Tak že nemohli kněží ostáti a sloužiti pro ten oblak; nebo sláva Hospodinova naplnila dům Hospodinův.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 12, 'Tedy řekl Šalomoun: Hospodin řekl, že bude přebývati v mrákotě.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 13, 'Jižť jsem vystavěl dům k přebývání tvému, místo, v němž bys přebýval na věky.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 14, 'A obrátiv král tvář svou, požehnání dával všemu shromáždění Izraelskému, všecko pak shromáždění Izraelské stálo.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 15, 'A řekl: Požehnaný Hospodin Bůh Izraelský, kterýž mluvil ústy svými Davidovi otci mému, a skutečně naplnil to, řka:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 16, 'Od toho dne, kteréhož jsem vyvedl lid svůj Izraelský z Egypta, nevyvolil jsem města z žádného pokolení Izraelského k vystavení v něm domu, kdež by přebývalo jméno mé, ale Davida jsem vyvolil, aby spravoval lid můj Izraelský.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 17, 'Uložil tě byl zajisté v srdci svém David otec můj stavěti dům jménu Hospodina Boha Izraelského,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 18, 'Ale Hospodin řekl Davidovi otci mému: Ačkoli jsi uložil v srdci svém stavěti dům jménu mému, a dobře jsi učinil, žes to myslil v srdci svém:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 19, 'A však ty nebudeš stavěti toho domu, ale syn tvůj, kterýž vyjde z bedr tvých, on vystaví dům ten jménu mému.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 20, 'A tak splnil Hospodin slovo své, kteréž byl mluvil. Nebo jsem povstal na místo Davida otce svého, a dosedl jsem na stolici Izraelskou, jakož byl mluvil Hospodin, a ustavěl jsem dům tento jménu Hospodina Boha Izraelského,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 21, 'A připravil jsem tu místo truhle, v níž jest smlouva Hospodinova, kterouž učinil s otci našimi, když je vyvedl z země Egyptské.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 22, 'Postavil se pak Šalomoun před oltářem Hospodinovým, přede vším shromážděním Izraelským, a pozdvihl rukou svých k nebi,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 23, 'A řekl: Hospodine, Bože Izraelský, neníť podobného tobě Boha na nebi svrchu, ani na zemi dole, kterýž ostříháš smlouvy a milosrdenství služebníkům svým, chodícím před tebou v celém srdci svém,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 24, 'Kterýž jsi splnil služebníku svému, Davidovi otci mému, to, co jsi mluvil jemu; nebo jsi mluvil ústy svými, a skutečně jsi to naplnil, jakož se dnes vidí.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 25, 'Nyní tedy, ó Hospodine, Bože Izraelský, naplniž služebníku svému, Davidovi otci mému, což jsi mluvil jemu, řka: Nebudeť vyhlazen muž z rodu tvého od tváři mé, kterýž by seděl na stolici Izraelské, jestliže toliko ostříhati budou synové tvoji cesty své, aby chodili přede mnou, jakž jsi ty chodil přede mnou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 26, 'Protož nyní, ó Bože Izraelský, prosím, nechť jest upevněno slovo tvé, kteréž jsi mluvil služebníku svému, Davidovi otci mému.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 27, '(Ač zdali v pravdě bydliti bude Bůh na zemi? Aj, nebesa, nýbrž nebesa nebes tě neobsahují, mnohem méně dům tento, kterýž jsem vystavěl.)');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 28, 'A popatř k modlitbě služebníka svého a k úpění jeho, Hospodine, Bože můj, slyše volání a modlitbu, kterouž služebník tvůj modlí se dnes před tebou,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 29, 'Aby oči tvé byly otevřené na dům tento v noci i ve dne, na místo toto, o němž jsi řekl: Tuť bude jméno mé, abys vyslýchal modlitbu, kterouž se modlívati bude služebník tvůj na místě tomto.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 30, 'Vyslýchejž tedy modlitbu služebníka svého i lidu svého Izraelského, kterouž se modlívati budou na místě tomto; ty vždy vyslýchej v místě přebývání svého na nebesích, a vyslýchaje, buď milostiv.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 31, 'Když by zhřešil člověk proti bližnímu svému, a nutil by ho k přísaze, tak že by přisahati musil, a přišla by ta přísaha před oltář tvůj do domu tohoto:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 32, 'Ty vyslýchej na nebi a rozeznej, i rozsuď služebníky své, mstě nad bezbožným a obraceje skutky jeho na hlavu jeho, a ospravedlňuje spravedlivého, odplacuje mu vedlé spravedlnosti jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 33, 'Když by poražen byl lid tvůj Izraelský od nepřátel, proto že zhřešili proti tobě, jestliže by obrátíce se k tobě, vyznávali jméno tvé, a modléce se, poníženě prosili by tebe v domě tomto:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 34, 'Ty vyslýchej na nebi a odpusť hřích lidu svému Izraelskému, a uveď je zase do země, kterouž jsi dal otcům jejich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 35, 'Když by zavříno bylo nebe, a nepršel déšť, proto že zhřešili proti tobě, a modléce se na místě tomto, vyznávali by se jménu tvému, a od hříchů svých odvrátili by se po tvém trestání:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 36, 'Ty vyslýchej na nebi, a odpusť hřích služebníků svých a lidu svého Izraelského, vyuče je cestě výborné, po níž by chodili, a dej déšť na zemi svou, kterouž jsi dal lidu svému za dědictví.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 37, 'Byl-li by hlad na zemi, byl-li by mor, sucho, rez, kobylky, a brouci byli-li by; ssoužil-li by jej nepřítel jeho v zemi obývání jeho, aneb jakákoli rána, jakákoli nemoc:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 38, 'Všelikou modlitbu a každé úpění, kteréž by činěno bylo od kteréhokoli člověka, aneb ode všeho lidu tvého Izraelského, kdož by jen poznal ránu srdce svého, a pozdvihl by rukou svých v domě tomto,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 39, 'Ty vyslýchej na nebesích v místě přebývání svého, a slituj se i učiň a odplať jednomu každému vedlé všech cest jeho, kteréž ty znáš v srdci jeho, (nebo ty sám znáš srdce všech lidí,)');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 40, 'Aby se báli tebe po všecky dny, v nichž by živi byli na zemi, kterouž jsi dal otcům našim.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 41, 'Nýbrž také cizozemec, kterýž není z lidu tvého Izraelského, přišel-li by z země daleké pro jméno tvé,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 42, '(Neboť uslyší o jménu tvém velikém a ruce tvé přesilné, a rameni tvém vztaženém,) přišel-li by tedy, a modlil by se v domě tomto:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 43, 'Ty vyslýchej na nebi v místě přebývání svého, a učiň všecko to, o čež volati bude k tobě cizozemec ten, aťby poznali všickni národové země jméno tvé, a báli se tebe jako lid tvůj Izraelský, a aby věděli, že jméno tvé vzýváno jest nad domem tímto, kterýž jsem vystavěl.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 44, 'Když by vytáhl lid tvůj k boji proti nepříteli svému, cestou, kterouž bys poslal je, jestliže by se modlili Hospodinu naproti městu tomuto, kteréž jsi vyvolil, a naproti domu, kterýž jsem vystavěl jménu tvému:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 45, 'Tolikéž vyslýchej na nebi modlitbu jejich a úpění jejich, a vyveď při jejich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 46, 'Když by zhřešili proti tobě, (jakož není člověka, kterýž by nehřešil,) a rozhněvaje se na ně, vydal bys je v moc nepříteli, tak že by je jaté vedli ti, kteříž by je zjímali, do země nepřátelské, daleké neb blízké,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 47, 'A usmyslili by sobě v zemi té, do kteréž by zajati byli, a obrátíce se, modlili by se tobě v zemi těch, kteříž je zzajímali, řkouce: Zhřešiliť jsme a neprávě jsme činili, bezbožně jsme činili,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 48, 'A tak navrátili by se k tobě celým srdcem svým a celou duší svou v zemi nepřátel svých, kteříž je zzajímali, a modlili by se tobě naproti zemi své, kterouž jsi dal otcům jejich, naproti městu tomu, kteréž jsi vyvolil, a domu, kterýž jsem vzdělal jménu tvému:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 49, 'Vyslýchejž tedy na nebesích, v místě přebývání svého, modlitbu jejich a úpění jejich, a vyveď při jejich,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 50, 'A odpusť lidu svému, cožkoli zhřešil proti tobě, i všecka přestoupení jejich, jimiž přestoupili proti tobě, a nakloň k nim lítostí ty, kteříž je zjímali, aby se smilovali nad nimi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 51, 'Neboť jsou lid tvůj a dědictví tvé, kteréž jsi vyvedl z Egypta, z prostřed peci železné.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 52, 'Nechať jsou tedy oči tvé otevřené k modlitbě služebníka tvého a k modlitbě lidu tvého Izraelského, abys je vyslýchal vždycky, když by tě koli vzývali.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 53, 'Nebo jsi ty oddělil je sobě za dědictví ode všech národů země, jakož jsi mluvil skrze Mojžíše služebníka svého, když jsi vyvedl otce naše z Egypta, Panovníče Hospodine.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 54, 'Stalo se pak, když se přestal Šalomoun modliti Hospodinu vší modlitbou a prosbou touto, že vstal od oltáře Hospodinova, a přestal klečeti a pozdvihovati rukou svých k nebi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 55, 'A stoje, dobrořečil všemu shromáždění Izraelskému hlasem velikým, řka:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 56, 'Požehnaný Hospodin, kterýž dal odpočinutí lidu svému Izraelskému vedlé všeho, což mluvil. Nepochybilo ani jedno slovo ze všelikého slova jeho dobrého, kteréž mluvil skrze služebníka svého Mojžíše.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 57, 'Budiž Hospodin Bůh náš s námi, jako byl s otci našimi; nezamítejž nás, ani opouštěj.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 58, 'Ale nakloniž srdce naše k sobě, abychom chodili po všech cestách jeho, a ostříhali přikázaní jeho, i ustanovení jeho, a soudů jeho, kteréž přikázal otcům našim.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 59, 'A ať jsou má tato slova, kterýmiž jsem se modlil před Hospodinem, blízko Hospodina Boha našeho dnem i nocí, tak aby vyvodil při služebníka svého, a při lidu svého Izraelského každého času a dne,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 60, 'Aťby poznali všickni národové země, že Hospodin sám jest Bůh, a že není kromě něho žádný.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 61, 'Budiž tedy srdce vaše celé k Hospodinu Bohu našemu, tak abyste chodili v ustanoveních jeho, ostříhajíce přikázaní jeho, tak jako dnešního dne.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 62, 'Král pak a s ním všecken Izrael obětovali oběti před Hospodinem.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 63, 'A obětoval Šalomoun v obět pokojnou, kterouž obětoval Hospodinu, volů dvamecítma tisíců, a ovec sto dvadceti tisíců, a posvěcovali domu Hospodinova král i všickni synové Izraelští.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 64, 'Téhož dne posvětil král prostředku síně, kteráž byla před domem Hospodinovým; nebo obětoval tu oběti zápalné a oběti suché, a tuky pokojných obětí, proto že oltář měděný, kterýž byl před Hospodinem, byl malý, aniž mohly se na něm směstknati oběti zápalné a oběti suché, a tukové pokojných obětí.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 65, 'A tak držel Šalomoun toho času slavnost, a všecken Izrael s ním, shromáždění veliké odtud, kudyž se chodí do Emat, až ku potoku Egyptskému, před Hospodinem Bohem naším, za sedm dní a opět za sedm dní, to jest za čtrnácte dní.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 66, 'Dne pak osmého propustil lid. Kteříž požehnavše krále, odešli do obydlí svých, radujíce se a veselíce se v srdci ze všech dobrých věcí, kteréž učinil Hospodin Davidovi služebníku svému a Izraelovi lidu svému.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 1, 'Stalo se pak, když dokonal Šalomoun stavení domu Hospodinova a domu královského, podlé vší líbosti své, jakž vykonati umínil,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 2, 'Že se ukázal Hospodin Šalomounovi podruhé, jakož se mu byl ukázal v Gabaon.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 3, 'I řekl jemu Hospodin: Vyslyšelť jsem modlitbu tvou a prosbu tvou, kteroužs se modlil přede mnou; posvětil jsem domu toho, kterýž jsi vystavěl, aby přebývalo tam jméno mé až na věky, a byly tu oči mé i srdce mé po všecky dny.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 4, 'A ty jestliže choditi budeš přede mnou, jako chodil David otec tvůj, v dokonalosti srdce a v upřímnosti, čině všecko to, což jsem přikázal tobě, ustanovení mých i soudů mých ostříhaje:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 5, 'Utvrdím zajisté stolici království tvého nad Izraelem na věky, jakož jsem mluvil Davidovi otci tvému, řka: Nebudeť odjat muž z rodu tvého od trůnu Izraelského.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 6, 'Pakli se nazpět odvrátíte vy i synové vaši ode mne, a nebudete ostříhati přikázaní mých a ustanovení mých, kteráž jsem vydal vám, ale odejdouce, sloužiti budete bohům cizím a klaněti se jim:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 7, 'Vypléním docela Izraele se svrchku země, kterouž jsem jim dal, a dům tento, kteréhož jsem posvětil jménu svému, zavrhu od tváři své, i budeť Izrael za přísloví a za rozprávku mezi všemi národy.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 8, 'Ano i dům tento, jakkoli bude slavný, kdokoli mimo něj půjde, užasne se a ckáti bude, i řekne: Proč tak učinil Hospodin zemi této a domu tomuto?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 9, 'Tedy odpovědí: Proto že opustili Hospodina Boha svého, kterýž vyvedl otce jejich z země Egyptské, a chytili se bohů cizích, a klaněli se jim i sloužili jim, protož uvedl na ně Hospodin všecky tyto zlé věci.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 10, 'Stalo se také po přeběhnutí dvadcíti let, v nichž vzdělal Šalomoun oba dva ty domy, dům Hospodinův a dům královský,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 11, 'K čemuž byl Chíram král Tyrský daroval Šalomounovi hojně dříví cedrového a jedlového, i zlata vedlé vší vůle jeho, že dal také král Šalomoun Chíramovi dvadceti měst v zemi Galilejské.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 12, 'I vyjel Chíram z Týru, aby viděl ta města, kteráž mu daroval Šalomoun, ale nelíbila se jemu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 13, 'Protož řekl: Jakáž jsou ta města, kteráž mi dáváš, bratře můj? I nazval je zemí Kabul až do tohoto dne.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 14, 'Nebo byl poslal Chíram králi sto a dvadceti centnéřů zlata.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 15, 'Příčina pak platu, kterýž byl uložil král Šalomoun, byla, aby stavěl dům Hospodinův a dům svůj, a Mello i zdi Jeruzalémské, též Azor a Mageddo i Gázer.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 16, '(Farao zajisté král Egyptský vytáh, dobyl Gázeru a vypálil je, Kananejské pak, kteříž byli v tom městě, pobil a dal město za věno dceři své, manželce Šalomounově.)');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 17, 'A tak vystavěl zase Šalomoun Gázer a Betoron dolní,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 18, 'Též Baalat a Tadmor na poušti v též zemi,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 19, 'I všecka města, v nichž Šalomoun měl své sklady, i města vozů, i města jezdců, vše vedlé žádosti své, cožkoli chtěl stavěti v Jeruzalémě, a na Libánu i po vší zemi panování svého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 20, 'Všecken také lid, kterýž byl pozůstal z Amorejských, Hetejských, Ferezejských, Hevejských a Jebuzejských, kteříž nebyli z synů Izraelských,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 21, 'Totiž syny jejich, kteříž byli pozůstali po nich v zemi, jichž nemohli synové Izraelští vyhladiti, uvedl Šalomoun pod plat a v službu až do tohoto dne.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 22, 'Z synů pak Izraelských žádného nepodrobil v službu Šalomoun, ale byli muži váleční, a služebníci jeho, a knížata jeho, vůdcové jeho a úředníci nad vozy a jezdci jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 23, 'Bylo těch předních vládařů, kteříž byli nad dílem Šalomounovým, pět set a padesát. Ti spravovali lidi, kteříž dělali.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 24, 'Dcera pak Faraonova přestěhovala se z města Davidova do domu svého, kterýž jí byl vystavěl Šalomoun. Tehdáž také vystavěl Mello.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 25, 'I obětoval Šalomoun každého roku třikrát oběti zápalné a pokojné na oltáři, kterýž byl vzdělal Hospodinu, ale kadíval na tom, kterýž byl před Hospodinem, když dokonal dům.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 26, 'Nadělal také král Šalomoun lodí velikých v Aziongaber, kteréž jest podlé Elat, na břehu moře Rudého v zemi Idumejské.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 27, 'A poslal Chíram na těch lodech služebníky své, plavce umělé na moři, s služebníky Šalomounovými.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 28, 'Kteříž přeplavivše se do Ofir, nabrali tam zlata čtyři sta a dvadceti centnéřů, a přivezli králi Šalomounovi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 1, 'Uslyševši pak královna z Sáby pověst o Šalomounovi a jménu Hospodinovu, přijela, aby zkusila jeho v pohádkách.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 2, 'A přijevši do Jeruzaléma s počtem velmi velikým, s velbloudy nesoucími vonné věci a zlata velmi mnoho i kamení drahého, přišla k Šalomounovi, a mluvila s ním o všecko, což měla v srdci svém.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 3, 'Jížto odpověděl Šalomoun na všecka slova její. Nebylo nic skrytého před králem, nač by jí neodpověděl.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 4, 'Protož uzřevši královna z Sáby všecku moudrost Šalomounovu i dům, kterýž byl ustavěl,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 5, 'Též pokrmy stolu jeho, i sedání a stávání služebníků přisluhujících jemu, i roucha jejich, šeňkýře také jeho, i stupně, kterýmiž vstupoval k domu Hospodinovu, zděsila se náramně.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 6, 'A řekla králi: Praváť jest řeč, kterouž jsem slyšela v zemi své, o věcech tvých a o moudrosti tvé,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 7, 'Ješto jsem nechtěla věřiti řečem, až jsem přijela a uzřela očima svýma. Ale aj, není mi praveno ani polovice; převýšil jsi moudrostí a dobrotou pověst tu, kterouž jsem slyšela.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 8, 'Blahoslavení muži tvoji, a blahoslavení služebníci tvoji, kteříž stojí před tebou vždycky, a slyší moudrost tvou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 9, 'Budiž Hospodin Bůh tvůj požehnaný, kterýž tě sobě oblíbil, aby tě posadil na stolici Izraelské, proto že miluje Hospodin Izraele na věky, a ustanovil tě králem, abys činil soud a spravedlnost.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 10, 'I dala králi sto a dvadceti centnéřů zlata, a vonných věcí velmi mnoho, i kamení drahého, aniž bylo kdy více přivezeno takových vonných věcí tak mnoho, jako darovala královna z Sáby králi Šalomounovi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 11, '(Lodí také Chíramova, kteráž přinášela zlato z Ofir, přivezla z Ofir dříví almugim velmi mnoho i kamení drahého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 12, 'I nadělal král z toho dříví almugim zábradel k domu Hospodinovu, i k domu královu, též harf a louten zpěvákům, aniž jest kdy přivezeno takového dříví almugim, ani vidíno do dnešního dne.)');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 13, 'Král také Šalomoun dal královně z Sáby vedlé vší vůle její, čehož požádala, nad to, což jí Šalomoun daroval darem královským. Potom se navrátila do země své ona i služebníci její.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 14, 'Byla pak váha toho zlata, kteréž přicházelo Šalomounovi na každý rok, šest set šedesáte šest centnéřů zlata,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 15, 'Kromě toho, co přicházelo od kupců a prodavačů vonných věcí, a ode všech králů Arabských i vývod země.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 16, 'A protož nadělal král Šalomoun dvě stě štítů z zlata taženého, šest set zlatých dával na každý štít,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 17, 'A tři sta pavéz z taženého zlata, tři libry zlata dal na každou pavézu. I složil je král v domě lesu Libánského.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 18, 'Udělal také král stolici z kostí slonových velikou, a obložil ji zlatem ryzím.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 19, 'Šest stupňů bylo k té stolici, a vrch okrouhlý byl na stolici od zadní strany její, a zpolehadla rukám s obou stran té stolice, a dva lvové stáli u zpolehadel.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 20, 'A dvanácte lvů stálo tu na šesti stupních s obou stran. Nebylo nic takového učiněno v žádných královstvích.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 21, 'Nadto všecky nádoby krále Šalomouna, jichž ku pití užívali, byly zlaté, a všecky nádoby v domě lesu Libánského byly z zlata nejčistšího. Nic nebylo od stříbra, aniž ho sobě co vážili ve dnech Šalomounových.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 22, 'Nebo měl král lodí mořské s lodími krále Chírama. Jednou ve třech letech vracely se ty lodí mořské, přinášející zlato a stříbro, kosti slonové, a opice a pávy.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 23, 'I zveleben jest král Šalomoun nad všecky krále zemské v bohatství a v moudrosti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 24, 'Pročež všickni obyvatelé země žádostivi byli viděti tvář Šalomounovu, aby slyšeli moudrost jeho, kterouž složil Bůh v srdci jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 25, 'A přinášeli jeden každý dary své, nádoby stříbrné a nádoby zlaté, roucha a zbroj, i vonné věci, koně a mezky, a to každého roku,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 26, 'Tak že nashromáždil Šalomoun vozů a jezdců, a měl tisíc a čtyři sta vozů a dvanácte tisíc jezdců, kteréž rozsadil v městech vozů, a při králi v Jeruzalémě.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 27, 'I složil král stříbra v Jeruzalémě jako kamení, a cedrového dříví jako planého fíkoví, kteréž roste v údolí u velikém množství.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 28, 'Přivodili také Šalomounovi koně z Egypta a koupě rozličné; nebo kupci královští brávali koupě rozličné za slušnou mzdu,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 29, 'A vodívali spřež vozníků z Egypta za šest set lotů stříbra, koně pak jednoho za sto a padesáte, a tak všechněm králům Hetejským a králům Syrským oni dodávali.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 1, 'V tom král Šalomoun zamiloval ženy cizozemky mnohé, i dceru Faraonovu, i Moábské, Ammonitské, Idumejské, Sidonské a Hetejské,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 2, 'Z národů těch, kteréž zapověděl Hospodin synům Izraelským, řka: Nebudete se směšovati s nimi, aniž se oni budou směšovati s vámi, neboť by naklonili srdce vaše k bohům svým. K těm přilnul Šalomoun milostí,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 3, 'Tak že měl žen královen sedm set a ženin tři sta. I odvrátily ženy jeho srdce jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 4, 'Stalo se tedy, že když se zstaral Šalomoun, ženy jeho naklonily srdce jeho k bohům cizím, tak že nebylo srdce jeho celé při Hospodinu Bohu jeho, jako bylo srdce Davida otce jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 5, 'Ale obrátil se Šalomoun k Astarot, bohyni Sidonské, a k Moloch, ohavnosti Ammonské.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 6, 'I činil Šalomoun to, což se nelíbilo Hospodinu, a nenásledoval cele Hospodina, jako David otec jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 7, 'Tedy vystavěl Šalomoun výsost Chámosovi, ohavnosti Moábské, na hoře, kteráž jest naproti Jeruzalému, a Molochovi, ohavnosti synů Ammon.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 8, 'A tak vzdělal všechněm ženám svým z cizího národu, kteréž kadily a obětovaly bohům svým.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 9, 'I rozhněval se Hospodin na Šalamouna, proto že se uchýlilo srdce jeho od Hospodina Boha Izraelského, kterýž se jemu byl ukázal po dvakrát,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 10, 'A zapověděl jemu tu věc, aby nechodil po bozích cizích. Ale neostříhal toho, což byl přikázal Hospodin.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 11, 'Protož řekl Hospodin Šalomounovi: Poněvadž se to nalezlo při tobě, a neostříhal jsi smlouvy mé ani ustanovení mých, kterážť jsem přikázal, věz, že odtrhnu království toto od tebe, a dám je služebníku tvému.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 12, 'A však za dnů tvých neučiním toho pro Davida otce tvého, než z ruky syna tvého odtrhnu je.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 13, 'Všeho pak království neodtrhnu, ale pokolení jednoho zanechám synu tvému pro Davida služebníka svého a pro Jeruzalém, kterýž jsem vyvolil.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 14, 'A tak vzbudil Hospodin protivníka Šalomounovi, Adada Idumejského z semene královského, kterýž byl v zemi Idumejské.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 15, 'Nebo stalo se, když bojoval David proti Idumejským, a Joáb kníže vojska vytáhl, aby pochoval zmordované, a pobil všecky pohlaví mužského v zemi Idumejské,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 16, '(Za šest zajisté měsíců byl tam Joáb se vším lidem Izraelským, dokudž nevyplénil všech pohlaví mužského v zemi Idumejské,)');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 17, 'Že tehdáž utekl Adad sám, a někteří muži Idumejští z služebníků otce jeho s ním, aby šli do Egypta. Adad pak byl pachole neveliké.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 18, 'Kteříž jdouce z Madian, přišli do Fáran, a vzavše s sebou některé muže z Fáran, přišli do Egypta k Faraonovi, králi Egyptskému, kterýž dal jemu dům, i stravou opatřil ho, dal jemu také i zemi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 19, 'A tak nalezl Adad milost velikou před Faraonem, tak že jemu dal za manželku sestru ženy své, sestru Tafnes královny.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 20, 'I porodila jemu sestra Tafnes syna Genubata, a odchovala ho Tafnes v domu Faraonovu. I byl Genubat v domě Faraonově mezi syny Faraonovými.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 21, 'Když pak uslyšel Adad v Egyptě, že by usnul David s otci svými, a že umřel i Joáb kníže vojska, tedy řekl Adad Faraonovi: Propusť mne, ať jdu do země své.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 22, 'Jemuž řekl Farao: Čehožť se nedostává u mne, že chceš odjíti do země své? I řekl: Ničeho, a však vždy mne propusť.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 23, 'Vzbudil ještě Bůh proti němu protivníka, Rázona syna Eliadova, kterýž byl utekl od Hadarezera krále Soby, pána svého,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 24, 'A shromáždiv k sobě muže, byl knížetem roty, když je David hubil. Protož odšedše do Damašku, bydlili v něm a kralovali v Damašku.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 25, 'I byl protivníkem Izraelovým po všecky dny Šalomounovy; a to bylo nad to zlé, kteréž mu činil Adad. I měl v ošklivosti Izraele, když kraloval v Syrii.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 26, 'Jeroboám také syn Nebatův Efratejský z Sareda, (a jméno matky jeho ženy vdovy bylo Serua,) služebník Šalomounův, pozdvihl ruky proti králi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 27, 'A tato byla příčina, pro kterouž pozdvihl ruky proti králi Šalomounovi: Že vystavěv Šalomoun Mello, zavřel mezeru města Davidova otce svého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 28, 'Jeroboám pak byl muž silný a udatný. Protož vida Šalomoun mládence, že by pracovitý byl, ustanovil ho nade všemi platy z domu Jozefa.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 29, 'I stalo se téhož času, že když vyšel Jeroboám z Jeruzaléma, našel jej prorok Achiáš Silonský na cestě, jsa odín rouchem novým. A byli sami dva na poli.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 30, 'Tedy ujav Achiáš roucho nové, kteréž měl na sobě, roztrhal je na dvanácte kusů.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 31, 'A řekl Jeroboámovi: Vezmi sobě deset kusů; nebo takto praví Hospodin Bůh Izraelský: Aj, já roztrhnu království z ruky Šalomounovy, a dám tobě desatero pokolení.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 32, 'Jedno toliko pokolení zůstane jemu pro služebníka mého Davida, a pro město Jeruzalém, kteréž jsem vyvolil ze všech pokolení Izraelských,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 33, 'Proto že opustili mne, a klaněli se Astarot bohyni Sidonské, a Chámos bohu Moábskému, i Moloch bohu Ammonskému, a nechodili po cestách mých, aby činili to, což mi se líbí, totiž ustanovení má a soudy mé, jako David otec jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 34, 'A však neodejmu ničeho z království z rukou jemu; nebo vůdcím zanechám ho po všecky dny života jeho pro Davida služebníka svého, kteréhož jsem vyvolil, kterýž ostříhal přikázaní mých a ustanovení mých.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 35, 'Ale potom vezma království z ruky syna jeho, dám tobě z něho desatero pokolení,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 36, 'Synu pak jeho dám jedno pokolení, aby zůstala svíce Davidovi služebníku mému po všecky dny přede mnou v městě Jeruzalémě, kteréž jsem sobě vyvolil, aby tam jméno mé přebývalo.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 37, 'A tak tebe vezmu, abys kraloval ve všech věcech, kterýchž by žádala duše tvá, a budeš králem nad Izraelem.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 38, 'Protož jestliže uposlechneš všeho toho, což přikáži tobě, a choditi budeš po cestách mých, a činiti to, což mi se líbí, ostříhaje ustanovení mých a přikázaní mých, jako činil David služebník můj: budu s tebou a vzdělám tobě dům stálý, jako jsem vzdělal Davidovi, a dám tobě lid Izraelský.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 39, 'Potrápímť zajisté semene Davidova pro tu věc, a však ne po všecky dny.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 40, 'Pro tu příčinu chtěl Šalomoun zabiti Jeroboáma. Kterýž vstav, utekl do Egypta k Sesákovi králi Egyptskému, a byl v Egyptě, dokudž neumřel Šalomoun.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 41, 'Jiné pak věci Šalomounovy, kteréž činil, i moudrost jeho vypsány jsou v knize činů Šalomounových.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 42, 'Dnů pak, v nichž kraloval Šalomoun v Jeruzalémě nade vším Izraelem, bylo čtyřidceti let.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 43, 'I usnul Šalomoun s otci svými, a pochován jest v městě Davida otce svého. Kraloval pak Roboám syn jeho místo něho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 1, 'Tedy přibral se Roboám do Sichem; nebo tam sešel se byl všecken Izrael, aby ho ustanovili za krále.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 2, 'Stalo se pak, když uslyšel Jeroboám syn Nebatův, jsa ještě v Egyptě, kamž byl utekl před Šalomounem králem, (bydlel zajisté Jeroboám v Egyptě,)');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 3, 'Že poslali a povolali ho; protož přišed Jeroboám i všecko shromáždění Izraelské, mluvili k Roboámovi, řkouce:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 4, 'Otec tvůj ztížil jho naše; protož nyní polehč služby otce svého tvrdé a břemena jeho těžkého, kteréž vzložil na nás, a budeme tobě sloužiti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 5, 'Kterýž řekl jim: Odejděte, a třetího dne navraťte se ke mně. I odšel lid.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 6, 'Tedy radil se král Roboám s starci, kteříž stávali před Šalomounem otcem jeho ještě za života jeho, řka: Kterak vy radíte, jakou odpověd mám dáti lidu tomuto?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 7, 'I odpověděli jemu, řkouce: Jestliže dnes povolný budeš lidu tomuto a ochotně se jim ukážeš, a odpověd dávaje, mluviti budeš přívětivě, budouť služebníci tvoji po všecky dny.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 8, 'Ale on opustil radu starců, kterouž dali jemu, a radil se s mládenci, kteříž s ním zrostli a stávali před ním.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 9, 'A řekl k nim: Co vy radíte, jakou bychom dali odpověd lidu tomuto, kteříž mluvili ke mně, řkouce: Polehč břemene, kteréž vzložil otec tvůj na nás?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 10, 'I odpověděli jemu mládenci, kteříž zrostli s ním, řkouce: Takto odpovíš lidu tomu, kteříž mluvili k tobě a řekli: Otec tvůj ztížil jho naše, ty pak polehč nám. Takto díš jim: Nejmenší prst můj tlustší jest nežli bedra otce mého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 11, 'Nyní tedy otec můj těžké břímě vložil na vás, já pak přidám břemene vašeho; otec můj trestal vás bičíky, ale já trestati vás budu biči uzlovatými.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 12, 'Přišel tedy Jeroboám i všecken lid k Roboámovi dne třetího, jakž byl rozkázal král, řka: Navraťte se ke mně dne třetího.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 13, 'I odpověděl král lidu tvrdě, opustiv radu starců, kterouž dali jemu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 14, 'A mluvil k nim vedlé rady mládenců, řka: Otec můj ztížil jho vaše, já pak přidám břemene vašeho; otec můj trestal vás bičíky, ale já trestati vás budu biči uzlovatými.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 15, 'I neuposlechl král lidu. Nebo byla příčina od Hospodina, aby se naplnila řeč jeho, kterouž mluvil Hospodin skrze Achiáše Silonského k Jeroboámovi synu Nebatovu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 16, 'Protož vida všecken Izrael, že by je král oslyšel, odpověděl lid králi v tato slova: Jakýž máme díl v Davidovi? Ani dědictví nemáme v synu Izai. K stanům svým, ó Izraeli! Nyní opatř dům svůj, Davide. Odšel tedy Izrael k stanům svým,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 17, 'Tak že nad syny Izraelskými toliko, kteříž bydlili v městech Judských, kraloval Roboám.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 18, 'I poslal král Roboám Adurama, kterýž byl nad platy, a uházel ho všecken Izrael kamením až do smrti, čímž král Roboám přinucen byl, aby vsedna na vůz, utekl do Jeruzaléma.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 19, 'A tak odstoupili synové Izraelští od domu Davidova až do dnešního dne.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 20, 'I stalo se, když uslyšeli všickni Izraelští, že by se navrátil Jeroboám, poslavše, povolali ho do shromáždění, a ustanovili ho králem nade vším Izraelem. Nezůstávalo při domu Davidovu než samo pokolení Judovo.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 21, 'Když pak přijel Roboám do Jeruzaléma, shromáždil všecken dům Judský a pokolení Beniamin, totiž sto a osmdesáte tisíců výborných bojovníků, aby bojovali proti domu Izraelskému, a aby zase přivedeno bylo království k Roboámovi synu Šalomounovu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 22, 'Tedy stala se řeč Boží k Semaiášovi muži Božímu, řkoucí:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 23, 'Pověz Roboámovi synu Šalomounovu, králi Judskému a všemu domu Judovu i Beniaminovu, a ostatku lidu těmito slovy:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 24, 'Takto praví Hospodin: Netáhněte a nebojujte proti bratřím svým synům Izraelským. Navraťte se jeden každý do domu svého, nebo ode mne stala se věc tato. I uposlechli rozkazu Hospodinova a navrátili se, aby odešli vedlé řeči Hospodinovy.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 25, 'Potom vystavěl Jeroboám Sichem na hoře Efraim, a bydlil v něm, a vyšed odtud, vystavěl Fanuel.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 26, 'Řekl pak Jeroboám v srdci svém: Tudíž by se navrátilo království toto k domu Davidovu,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 27, 'Když by chodíval lid tento k obětování obětí v domě Hospodinově do Jeruzaléma; i obrátilo by se srdce lidu tohoto ku pánu jeho Roboámovi králi Judskému, a tak zabijíce mne, navrátili by se k Roboámovi králi Judskému.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 28, 'Protož poradiv se král, udělal dvé telat zlatých a řekl lidu: Dosti jste již chodili do Jeruzaléma. Aj, teď bohové tvoji, ó Izraeli, kteříž tě vyvedli z země Egyptské.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 29, 'I postavil jedno v Bethel, a druhé postavil v Dan.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 30, 'Kterážto věc byla příčinou k hřešení, nebo chodíval lid k jednomu z těch až do Dan.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 31, 'Vzdělal zajisté dům výsostí, a ustanovil kněží z lidu obecného, kteříž nebyli z synů Léví.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 32, 'Ustanovil také Jeroboám svátek měsíce osmého, v patnáctý den téhož měsíce, ku podobenství svátku, kterýž byl v Judstvu, a obětoval na oltáři. Takž učinil i v Bethel, obětuje telatům, kteréž byl udělal; také i v Bethel ustanovil kněží výsostí, kteréž byl zdělal.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 33, 'A obětoval na oltáři, kterýž byl udělal v Bethel, v patnáctý den měsíce osmého, toho měsíce, kterýž byl sobě smyslil v srdci svém, a slavil svátek s syny Izraelskými, a přistoupil k oltáři, aby kadil.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 1, 'A aj, muž Boží přišel z Judstva s slovem Hospodinovým do Bethel, tehdáž když Jeroboám, stoje u oltáře, kadil.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 2, 'I zvolal proti oltáři slovem Hospodinovým, řka: Oltáři, oltáři, toto praví Hospodin: Hle, syn narodí se domu Davidovu, jménem Joziáš, kterýž obětovati bude na tobě kněží výsostí, jenž zapalují kadidlo na tobě; i kosti lidské páliti budou na tobě.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 3, 'I dal téhož dne znamení, řka: Totoť jest znamení, že mluvil Hospodin: Aj, oltář roztrhne se a vysype se popel, kterýž jest na něm.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 4, 'V tom uslyšev král Jeroboám slovo muže Božího, že zvolal proti oltáři v Bethel, vztáhl ruku svou od oltáře a řekl: Jměte ho. I uschla ruka jeho, kterouž vztáhl proti němu, a nemohl ji zase přitáhnouti k sobě.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 5, 'Oltář také se roztrhl, a vysypal se popel z oltáře podlé znamení, kteréž byl předpověděl muž Boží slovem Hospodinovým.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 6, 'Protož mluvil král a řekl tomu muži Božímu: Pomodl se medle Hospodinu Bohu svému a pros za mne, abych mohl přitáhnouti ruku svou k sobě. I modlil se muž Boží Hospodinu, a přitáhl král ruku zase k sobě, a byla jako prvé.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 7, 'Tedy řekl král muži Božímu: Poď se mnou domů a posilň se, a dámť dar.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 8, 'I řekl muž Boží králi: Bys mi dal polovici domu svého, nešel bych s tebou, aniž bych jedl chleba, aniž bych pil vody na místě tomto.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 9, 'Nebo tak mi přikázal slovem svým Hospodin, řka: Nebudeš jísti chleba, ani píti vody, aniž se navrátíš tou cestou, kterouž jsi přišel.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 10, 'A tak odšel jinou cestou, a nenavrátil se tou cestou, kterouž byl přišel do Bethel.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 11, 'Prorok pak jeden starý bydlil v Bethel, jehož syn přišed, vypravoval mu všecky věci, kteréž učinil muž Boží toho dne v Bethel; i slova, kteráž mluvil králi, vypravovali otci svému.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 12, 'Tedy řekl jim otec jejich: Kterou cestou šel? I ukázali mu synové jeho cestu, kterouž šel ten muž Boží, kterýž byl z Judstva přišel.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 13, 'Zatím řekl synům svým: Osedlejte mi osla. Kteříž osedlali mu osla, a on vsedl na něj.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 14, 'A jel za mužem Božím a nalezl jej, an sedí pod dubem. I řekl jemu: Ty-li jsi ten muž Boží, kterýž jsi přišel z Judstva? A on odpověděl: Jsem.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 15, 'Kterýž řekl jemu: Poď se mnou domů, a pojíš chleba.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 16, 'Ale on odpověděl: Nemohuť se navrátiti, ani jíti s tebou, aniž budu jísti chleba, ani píti vody s tebou na místě tomto.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 17, 'Nebo stala se ke mně řeč slovem Hospodinovým: Nebudeš tam jísti chleba, ani píti vody; nenavrátíš se, jda touž cestou, kterouž jsi šel.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 18, 'Jemuž odpověděl: Takéť já prorok jsem jako i ty, a mluvil ke mně anděl slovem Hospodinovým, řka: Navrať ho s sebou do domu svého, ať pojí chleba a napije se vody. To pak sklamal jemu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 19, 'Takž se navrátil s ním, a jedl chléb v domě jeho a pil vodu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 20, 'Když pak oni seděli za stolem, stalo se slovo Hospodinovo k proroku tomu, kterýž onoho byl zase navrátil.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 21, 'A zvolal na muže Božího, kterýž byl přišel z Judstva, řka: Toto praví Hospodin: Proto že jsi na odpor učinil řeči Hospodinově, a neostříhal jsi přikázaní, kteréžť vydal Hospodin Bůh tvůj,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 22, 'Ale navrátils se a jedls chléb, a pils vodu na místě, o kterémžť řekl: Nebudeš jísti chleba, ani píti vody: nebudeť pochováno tělo tvé v hrobě otců tvých.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 23, 'Tedy když pojedl chleba a napil se, osedlal mu osla, totiž tomu proroku, kteréhož byl navrátil.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 24, 'A když odšel, trefil na něj lev na cestě a udávil jej. I leželo tělo jeho na cestě, a osel stál podlé něho; lev také stál vedlé těla mrtvého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 25, 'A aj, muži někteří jdouce tudy, uzřeli tělo mrtvé ležící na cestě, a lva, an stojí vedlé něho. Kteříž přišedše, pověděli v městě, v kterémž ten starý prorok bydlil.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 26, 'Což když uslyšel ten prorok, kterýž ho byl navrátil s cesty, řekl: Muž Boží jest, kterýž na odpor učinil řeči Hospodinově; protož vydal jej Hospodin lvu, kterýž potřev ho, udávil jej vedlé řeči Hospodinovy, kterouž mluvil jemu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 27, 'Zatím mluvě k synům svým, řekl: Osedlejte mi osla. I osedlali.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 28, 'A odjev, nalezl mrtvé tělo jeho ležící na cestě, a osla i lva, an stojí u toho těla; a nejedl lev těla toho, aniž co uškodil oslu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 29, 'Protož vzav prorok tělo muže Božího, vložil je na osla, a přinesl je. I přišel do města svého, aby ho plakal a pochoval.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 30, 'Položil pak tělo jeho v hrobě svém, a plakali ho: Ach, bratře můj.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 31, 'A pochovav ho, mluvil k synům svým, řka: Když já umru, pochovejte mne v témž hrobě, v němž muž Boží jest pochován, vedlé kostí jeho položte kosti mé.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 32, 'Neboť se jistě stane to, což ohlásil slovem Hospodinovým proti oltáři, kterýž jest v Bethel, a proti všechněm domům výsostí, kteréž jsou v městech Samařských.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 33, 'Po těchto příbězích neodvrátil se Jeroboám od cesty své zlé, ale opět nadělal z lidu obecného kněží výsostí. Kdo jen chtěl, posvětil ruky jeho, a ten byl knězem výsostí.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 34, 'I byla ta věc domu Jeroboámovu příčinou k hřešení, aby vypléněn a vyhlazen byl se svrchku země.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 1, 'Toho času roznemohl se Abiáš, syn Jeroboámův.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 2, 'I řekl Jeroboám ženě své: Vstaň medle a změň se, aby nepoznali, že jsi žena Jeroboámova, a jdi do Sílo. Hle, tam jest Achiáš prorok, kterýž mi byl předpověděl, že mám býti králem nad lidem tímto.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 3, 'A vezma v ruce své deset chlebů a koláčů, a láhvici medu, jdi k němu; onť oznámí tobě, co se stane pacholeti tomuto.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 4, 'I učinila tak žena Jeroboámova; nebo vstavši, šla do Sílo, a přišla do domu Achiášova. Ale Achiáš nemohl již hleděti, nebo pošly mu byly oči pro starost jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 5, 'Hospodin pak řekl Achiášovi: Aj, žena Jeroboámova jde, aby se tebe něco zeptala o synu svém, proto že jest nemocen. Toto a toto budeš jí mluviti. Budeť pak, že když přijde, činiti se bude jinou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 6, 'Protož uslyšev Achiáš šust noh jejích, když vcházela do dveří, řekl: Poď, ženo Jeroboámova, proč se jinou činíš? Já zajisté poslán jsem k tobě s řečí tvrdou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 7, 'Jdi, pověz Jeroboámovi: Toto praví Hospodin Bůh Izraelský: Poněvadž jsem tě vyvýšil z prostředku lidu, a postavil jsem tě za vůdce nad lidem svým Izraelským,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 8, 'A odtrhl jsem království od domu Davidova, a dal jsem je tobě, ty však nebyl jsi jako služebník můj David, kterýž ostříhal přikázaní mých, a následoval mne v celém srdci svém, čině toliko to, což jest pravého přede mnou,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 9, 'Ale zlost jsi páchal hojněji nade všecky, kteříž byli před tebou; nebo odšed, učinils sobě bohy cizí a slité, abys mne dráždil, mne pak zavrhl jsi za hřbet svůj:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 10, 'Protož aj, já uvedu zlé věci na dům Jeroboámův, a vyhladím z Jeroboáma, i toho, jenž močí na stěnu, i zajatého i zanechaného v Izraeli, a vyvrhu ostatky domu Jeroboámova, jako hnůj vymítán bývá až dočista.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 11, 'Toho, kdož z domu Jeroboámova umře v městě, psi žráti budou, a toho, kdož umře na poli, ptáci nebeští jísti budou; neboť jest mluvil Hospodin.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 12, 'Ty pak vstana, jdi do domu svého, a když vcházeti budeš do města, tehdy umře pachole.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 13, 'I budou ho plakati všecken lid Izraelský, a pochovají jej; nebo ten sám z domu Jeroboámova dostane se do hrobu, proto že o něm z domu Jeroboámova jest slovo dobré u Hospodina Boha Izraelského.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 14, 'Vyzdvihneť však sobě Hospodin krále nad Izraelem, kterýž vyhladí dům Jeroboámův toho dne. Ale co? Nýbrž již vyzdvihl.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 15, 'A zaklátí Hospodin Izraelem tak, jako se klátí třtina u vodách, a vykoření Izraele z země výborné této, kterouž dal otcům jejich, a rozptýlí je daleko za řeku, proto že sobě zdělali háje, popouzejíce Hospodina.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 16, 'A tak vydá Izraele pro hříchy Jeroboámovy, kterýž i sám hřešil, i v hřích uvodil Izraele.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 17, 'Tedy vstavši žena Jeroboámova, odešla a přišla do Tersa, a když vstupovala na prah domu, umřelo pachole.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 18, 'I pochovali je, a plakal ho všecken lid Izraelský vedlé řeči Hospodinovy, kterouž mluvil skrze služebníka svého, Achiáše proroka.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 19, 'Jiné pak věci Jeroboámovy, jaké boje vedl a kterak kraloval, aj, sepsány jsou v knize o králích Izraelských.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 20, 'Všech dnů, v nichž kraloval Jeroboám, bylo dvamecítma let. I usnul s otci svými, a kraloval Nádab syn jeho místo něho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 21, 'Roboám také syn Šalomounův kraloval nad Judou. V jednom a ve čtyřidcíti letech byl Roboám, když počal kralovati, a sedmnácte let kraloval v Jeruzalémě městě, kteréž vyvolil Hospodin ze všech pokolení Izraelských, aby tam přebývalo jméno jeho. Bylo pak jméno matky jeho Naama Ammonitská.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 22, 'Činil také lid Judský to, což zlého jest před Hospodinem, a k zůřivosti ho popudili hříchy svými, kterýmiž hřešili, více nežli otcové jejich všemi věcmi, kteréž činili.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 23, 'Nebo i oni vystavěli sobě výsosti a sloupy, i háje na každém pahrbku vysokém a pod každým stromem zeleným.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 24, 'Přesto byli ohyzdní sodomáři v zemi té, činíce vedlé všech ohavností pohanských, kteréž byl vyplénil Hospodin před tváří synů Izraelských.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 25, 'I stalo se léta pátého království Roboámova, že vytáhl Sesák král Egyptský proti Jeruzalému,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 26, 'A pobral poklady domu Hospodinova a poklady domu královského, všecko to pobral. Vzal také všecky pavézy zlaté, kterýchž byl nadělal Šalomoun.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 27, 'Místo kterýchž nadělal král Roboám pavéz měděných, a poručil je úředníkům nad drabanty, kteříž ostříhali brány domu královského.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 28, 'A když král chodíval do domu Hospodinova, nosili je drabanti, a zase je přinášeli do pokoje drabantů.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 29, 'Jiné pak věci Roboámovy, a všecko, což činil, zdaliž není zapsáno v knize o králích Judských.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 30, 'Ano i válka, kteráž byla mezi Roboámem a Jeroboámem po všecky dny.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 31, 'I usnul Roboám s otci svými, a pochován jest s nimi v městě Davidově. A jméno matky jeho bylo Naama Ammonitská. I kraloval Abiam syn jeho místo něho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 1, 'Léta pak osmnáctého království Jeroboáma syna Nebatova, kraloval Abiam nad Judou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 2, 'Tři léta kraloval v Jeruzalémě. A jméno matky jeho bylo Maacha, dcera Abissalomova.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 3, 'Ten chodil ve všech hříších otce svého, kteréž páchal před oblíčejem jeho; a nebylo srdce jeho celé při Hospodinu Bohu jeho, jako srdce Davida otce jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 4, 'A však pro Davida dal jemu Hospodin Bůh jeho svíci v Jeruzalémě, vzbudiv syna jeho po něm, a utvrdiv Jeruzalém,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 5, 'Proto že David činil to, což bylo dobrého před Hospodinem, a neuchýlil se od žádné věci z těch, kteréž jemu byl přikázal, po všecky dny života svého, kromě skutku při Uriášovi Hetejském.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 6, 'A byl boj mezi Roboámem a Jeroboámem po všecky dny života jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 7, 'Jiné pak věci Abiamovy, a všecko což činil, popsáno jest v knize o králích Judských, ano i o boji mezi Abiamem a Jeroboámem.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 8, 'A když usnul Abiam s otci svými, pochovali ho v městě Davidově. I kraloval Aza syn jeho místo něho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 9, 'A tak léta dvadcátého Jeroboáma, krále Izraelského, kraloval Aza nad Judou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 10, 'Jedno a čtyřidceti let kraloval v Jeruzalémě. A jméno matky jeho bylo Maacha, dcera Abissalomova.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 11, 'I činil Aza, což dobrého bylo před Hospodinem, jako David otec jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 12, 'Nebo ohyzdné sodomáře vyplénil z země, a odjal všecky modly, kterýchž nadělali otcové jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 13, 'Nadto i Maachu matku svou ssadil, aby nebyla královnou; nebo byla udělala hroznou modlu v háji. Protož podťal Aza modlu tu ohyzdnou, a spálil při potoku Cedron.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 14, 'A ačkoli výsosti nebyly zkaženy, a však srdce Azovo bylo celé při Bohu po všecky dny jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 15, 'Vnesl také ty věci, kteréž posvěceny byly od otce jeho, i ty věci, kterýchž sám posvětil, do domu Hospodinova, stříbro a zlato i nádoby.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 16, 'Pročež byla válka mezi Azou a Bázou, králem Izraelským, po všecky dny jejich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 17, 'Nebo Báza král Izraelský vytáhl proti Judovi, a stavěl Ráma, aby nedal žádnému vyjíti ani jíti k Azovi králi Judskému.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 18, 'Ale vzav Aza všecko stříbro i zlato, kteréž pozůstalo v pokladích domu Hospodinova, a v pokladích domu královského, dal je v ruce služebníků svých, a poslal je král Aza k Benadadovi synu Tabremmon, syna Hezion, králi Syrskému, kterýž bydlil v Damašku, řka:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 19, 'Smlouva jest mezi mnou a mezi tebou, mezi otcem mým a mezi otcem tvým. Aj, teď posílám tobě dar, stříbro a zlato; jdi, zruš smlouvu svou s Bázou králem Izraelským, ať odtrhne ode mne.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 20, 'I uposlechl Benadad krále Azy, a poslav knížata s vojsky svými proti městům Izraelským, dobyl Jon a Dan, též Abelbetmaachy, i všeho Ceneretu, a vší země Neftalím.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 21, 'To když uslyšel Báza, přestal stavěti Ráma, a zůstal v Tersa.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 22, 'Tedy král Aza provolal po všem Judstvu, žádného nevyměňuje. I pobrali to kamení z Ráma, i dříví jeho, z něhož stavěl Báza, a vystavěl z toho král Aza Gabaa Beniaminovo a Masfa.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 23, 'Jiné pak všecky věci Azovy, i všecka síla jeho a cokoli dělal, i jaká města vystavěl, zapsáno jest v knize o králích Judských. Jen že v věku starosti své byl nemocný na nohy.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 24, 'I usnul Aza s otci svými, a pochován jest s nimi v městě Davida otce svého. A kraloval místo něho Jozafat syn jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 25, 'Nádab pak syn Jeroboámův, počal kralovati nad Izraelem léta druhého Azy, krále Judského, a kraloval nad Izraelem dvě létě.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 26, 'A činil to, což zlého jest před očima Hospodinovýma, chodě po cestě otce svého, v hříších jeho, jimiž k hřešení přivodil lid Izraelský.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 27, 'I činil mu úklady Báza syn Achiášův z domu Izachar, a porazil ho Báza u Gebbeton, kteréž bylo Filistinských. Nádab zajisté a všickni Izraelští oblehli byli Gebbeton.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 28, 'A tak zabil ho Báza léta třetího Azy, krále Judského, a kraloval místo něho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 29, 'I stalo se, když počal kralovati, že zahubil všecken dům Jeroboámův, a nepozůstavil žádné duše z Jeroboáma, až je i vyhladil vedlé řeči Hospodinovy, kterouž byl mluvil skrze služebníka svého Achiáše Silonského,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 30, 'Pro hříchy Jeroboámovy, jimiž hřešil, a jimiž k hřešení přivodil lid Izraelský, pro dráždění jeho, kterýmž dráždil Hospodina Boha Izraelského.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 31, 'Jiné pak věci Nádabovy a všecko, což činil, zapsáno jest v knize o králích Izraelských.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 32, 'Byla tedy válka mezi Azou, a mezi Bázou králem Izraelským, po všecky dny jejich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 33, 'Léta třetího Azy, krále Judského, kraloval Báza syn Achiášův nade vším Izraelem v Tersa za čtyřmecítma let.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 34, 'A činil to, což zlého jest před Hospodinem, chodě po cestě Jeroboámově a v hříších jeho, jimiž k hřešení přivodil Izraele.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 1, 'Stala se pak řeč Hospodinova k Jéhu, synu Chanani, proti Bázovi, řkoucí:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 2, 'Proto že jsem tě vyzdvihl z prachu, a postavil za vůdci lidu mého Izraelského, ty jsi pak chodil po cestě Jeroboámově, a přivedls k hřešení lid můj Izraelský, aby mne popouzeli hříchy svými:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 3, 'Aj, já vyhladím potomky Bázovy a potomky domu jeho, a učiním domu tvému, jako domu Jeroboáma, syna Nebatova.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 4, 'Toho, kdož z rodiny Bázovy umře v městě, psi žráti budou, a kdož z nich umře na poli, ptáci nebeští jísti budou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 5, 'Jiné pak věci Bázovy a všecko, což činil, i síla jeho, o tom zapsáno jest v knize o králích Izraelských.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 6, 'Když pak usnul Báza s otci svými, pochován jest v Tersa, a Ela syn jeho kraloval místo něho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 7, 'A tak skrze Jéhu syna Chanani, proroka, stala se řeč Hospodinova proti Bázovi a proti domu jeho, i proti všemu zlému, kteréž činil před oblíčejem Hospodinovým, popouzeje ho dílem rukou svých, že má býti podobný domu Jeroboámovu, a proto že jej zabil.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 8, 'Léta dvadcátého šestého Azy, krále Judského, kraloval Ela syn Bázův nad Izraelem v Tersa dvě létě.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 9, 'I zprotivil se jemu služebník jeho Zamri, hejtman nad polovicí vozů, když on v Tersa kvasil a opilý byl v domě Arsy, vládaře města Tersa.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 10, 'V tom Zamri přišed, ranil ho, a zabil jej léta dvadcátého sedmého Azy krále Judského, a kraloval místo něho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 11, 'Když pak kraloval a seděl na stolici jeho, pobil všecken dům Bázův, i příbuzné jeho, i přátely jeho, nepozůstaviv z něho ani močícího na stěnu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 12, 'A tak vyhladil Zamri všecken dům Bázův vedlé řeči Hospodinovy, kterouž byl mluvil proti Bázovi skrze Jéhu proroka,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 13, 'Pro všecky hříchy Bázovy, i hříchy Ela syna jeho, kteříž hřešili, i v hříchy uvodili Izraele, popouzejíce Hospodina Boha Izraelského marnostmi svými.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 14, 'Jiné pak věci Ela a všecko, což činil, vypsáno jest v knize o králích Izraelských.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 15, 'Léta dvadcátého sedmého Azy, krále Judského, kraloval Zamri v Tersa sedm dní, když lid vojenský ležel proti Gebbeton Filistinských.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 16, 'Nebo uslyšev lid, kterýž byl v ležení, takové věci, že by se Zamri zprotivil a že krále zabil, tedy všecken Izrael ustanovili sobě krále Amri, hejtmana nad vojskem Izraelským toho času v vojště.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 17, 'Protož táhl Amri a s ním všecken Izrael od Gebbeton, a oblehli Tersu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 18, 'A když viděl Zamri, že již město jest vzato, všed na palác domu královského, zapálil nad sebou dům královský, i umřel,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 19, 'Pro hříchy své, kterýmiž hřešil, čině, což zlého jest před oblíčejem Hospodinovým, a chodě po cestě Jeroboámově a v hříších jeho, kteréž páchal, přivozuje k hřešení lid Izraelský.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 20, 'Jiné pak věci Zamri i jeho úkladové, kteréž činil, zapsáni jsou v knize o králích Izraelských.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 21, 'Tedy rozdělil se lid Izraelský na dvé. Polovice lidu postoupilo po Tebni synu Ginet, aby ho učinili králem, a druhá polovice postoupila po Amri.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 22, 'Ale přemohl lid, kterýž postoupil po Amri, lid ten, kterýž postoupil po Tebni synu Ginet. I umřel Tebni, a kraloval Amri.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 23, 'Léta třidcátého prvního Azy, krále Judského, kraloval Amri nad Izraelem dvanácte let. V Tersa kraloval šest let.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 24, 'I koupil horu Someron od Semera za dvě hřivny stříbra, a když vystavěl tu horu, nazval jméno města toho, kteréž vzdělal, od jména Semery, pána té hory, totiž Samaří.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 25, 'Činil pak Amri to, což jest zlého před oblíčejem Hospodinovým; nýbrž horší věci činil, než kdo ze všech, kteříž před ním byli.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 26, 'Nebo chodil po všeliké cestě Jeroboáma syna Nebatova, a ve všech hříších jeho, kterýmiž přivodil k hřešení Izraele, popouzeje Hospodina Boha Izraelského marnostmi svými.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 27, 'Jiné pak věci Amri i všecko, což činil, i síla jeho, kterouž prokazoval, o tom zapsáno jest v knize o králích Izraelských.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 28, 'I usnul Amri s otci svými, a pochován jest v Samaří, a kraloval místo něho Achab syn jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 29, 'Achab tedy syn Amri kraloval nad Izraelem léta třidcátého osmého Azy, krále Judského, a kraloval Achab syn Amri nad Izraelem v Samaří dvamecítma let.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 30, 'I činil Achab syn Amri před oblíčejem Hospodinovým horší věci než kdo ze všech, kteříž před ním byli.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 31, 'V tom stalo se, (nebo málo mu to bylo, že chodil v hříších Jeroboáma syna Nebatova), že sobě pojal ženu Jezábel dceru Etbál, krále Sidonského, a odšed, sloužil Bálovi a klaněl se jemu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 32, 'A vzdělal oltář Bálovi v chrámě Bálově, kterýž byl ustavěl v Samaří.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 33, 'Udělal také Achab i háj, a tak přičinil toho, čím by popouzel Hospodina Boha Izraelského, nade všecky jiné krále Izraelské, kteříž byli před ním.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 34, 'Za dnů jeho Hiel Bethelský vystavěl Jericho. V Abiramovi prvorozeném svém založil je, a v Segubovi nejmladším svém postavil brány jeho, vedlé řeči Hospodinovy, kterouž byl mluvil skrze Jozue syna Nun.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 1, 'Tedy Eliáš Tesbitský, obyvatel Galádský, mluvil k Achabovi: Živť jest Hospodin Bůh Izraelský, před jehož oblíčejem stojím, že nebude těchto let rosy ani deště, jediné vedlé řeči mé.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 2, 'I stalo se slovo Hospodinovo k němu, řkoucí:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 3, 'Odejdi odsud a obrať se k východu, a skrej se u potoka Karit, kterýž jest naproti Jordánu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 4, 'A budeš z toho potoka píti, krkavcům pak jsem přikázal, aby tě tam krmili.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 5, 'Kterýž odšed, učinil, jakž mu přikázal Hospodin. Nebo odšed, usadil se při potoku Karit, kterýž byl proti Jordánu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 6, 'A krkavci přinášeli jemu chléb a maso každého jitra, též chléb a maso každého večera, a z potoka pil.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 7, 'Tedy po přeběhnutí dnů některých vysechl ten potok, nebo nebylo žádného deště v té zemi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 8, 'I stalo se slovo Hospodinovo k němu, řkoucí:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 9, 'Vstaň a jdi do Sarepty Sidonské, a buď tam. Aj, přikázal jsem ženě vdově, aby tě živila.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 10, 'Kterýž vstav, šel do Sarepty, a přišel k bráně města, a aj, žena vdova sbírala tu dříví. A zavolav jí, řekl: Medle, přines mi trochu vody v nádobě, abych se napil.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 11, 'A když šla, aby přinesla, zavolal jí zase a řekl: Medle, přines mi také kousek chleba v ruce své.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 12, 'I odpověděla: Živť jest Hospodin Bůh tvůj, žeť nemám žádného chleba, ani podpopelného, kromě hrsti mouky v kbelíku a maličko oleje v nádobce, a aj, sbírám dvě dřevě, abych šla a připravila to sobě a synu svému, abychom snědouce to, za tím zemříti musili.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 13, 'I řekl jí Eliáš: Neboj se. Jdi a učiň, jakž jsi řekla, a však udělej mi prvé z toho malý chléb podpopelný a přines mi; potom sobě a synu svému uděláš.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 14, 'Neboť toto praví Hospodin Bůh Izraelský: Mouka z kbelíka toho nebude strávena, aniž oleje v nádobce té ubude až do toho dne, když dá Hospodin déšť na zemi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 15, 'I šla a učinila vedlé řeči Eliášovy, a jedla ona i on i čeled její až do těch dní.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 16, 'Z kbelíka toho mouka nebyla strávena, aniž oleje v nádobce ubylo, vedlé řeči Hospodinovy, kterouž mluvil skrze Eliáše.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 17, 'A když to přeběhlo, stalo se, že se roznemohl syn ženy, paní toho domu, a byla nemoc jeho velmi těžká, tak že nezůstalo v něm dýchání.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 18, 'Protož řekla Eliášovi: Co mně a tobě, muži Boží? Přišel jsi ke mně, abys mi připomenul nepravost mou, a umořil syna mého?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 19, 'Kterýž odpověděl jí: Dej sem syna svého. A vzav ho z lůna jejího, vnesl jej na síň, kdež sám přebýval, a položil ho na lůžko své.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 20, 'Tedy volal k Hospodinu a řekl: Hospodine Bože můj, také-liž s tou vdovou, u kteréž pohostinu jsem, tak zle nakládáš, že jsi umořil syna jejího?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 21, 'A roztáh se nad dítětem po třikrát, zvolal k Hospodinu a řekl: Hospodine Bože můj, prosím, nechť se navrátí duše dítěte tohoto do vnitřností jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 22, 'I vyslyšel Hospodin hlas Eliášův, a navrátila se duše dítěte do vnitřností jeho, i ožilo.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 23, 'A vzav Eliáš dítě, snesl je z síně do domu, a dal je matce jeho. I řekl Eliáš: Pohleď, syn tvůj živ jest.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 24, 'Tedy řekla žena Eliášovi: Jižť jsem nyní poznala, že jsi muž Boží, a že řeč Hospodinova v ústech tvých jest pravá.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 1, 'Potom po mnohých dnech, po třetím tom létě, stalo se slovo Hospodinovo k Eliášovi, řkoucí: Jdi, ukaž se Achabovi, neboť dám déšť na zemi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 2, 'Odšel tedy Eliáš, aby se ukázal Achabovi. Byl pak hlad veliký v Samaří.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 3, 'I povolal Achab Abdiáše, kterýž byl představen domu jeho. (Abdiáš pak bál se Hospodina velmi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 4, 'Nebo když Jezábel mordovala proroky Hospodinovy, vzal Abdiáš sto proroků a skryl je po padesáti v jeskyni, a krmil je chlebem a vodou.)');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 5, 'A řekl Achab Abdiášovi: Jdi skrze tu zemi ke všechněm studnicím vod, a ke všechněm potokům, zdali bychom kde nalezli trávu, abychom živé zachovali koně a mezky, a nezmořili dobytka.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 6, 'I rozdělili sobě zemi, kterouž by prošli. Achab šel jednou cestou sám, Abdiáš také šel cestou druhou sám.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 7, 'A když Abdiáš byl na cestě, aj, Eliáš potkal se s ním. Kterýž když ho poznal, padl na tvář svou a řekl: Nejsi-liž ty, pane můj, Eliáš?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 8, 'Odpověděl jemu: Jsem. Jdi, pověz pánu svému: Aj, Eliáš přišel.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 9, 'Jemuž řekl: Což jsem zhřešil, že služebníka svého vydati chceš v ruku Achabovu, aby mne zamordoval?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 10, 'Živť jest Hospodin Bůh tvůj, žeť není národu ani království, kamž by neposlal pán můj hledati tě, a když řekli, že tebe není, přísahy požádal od království a národu, že tě nemohou nalezti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 11, 'A ty nyní pravíš: Jdi, pověz pánu svému: Aj, Eliáš přišel.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 12, 'I stalo by se, že jakž bych odšel od tebe, tedy duch Hospodinův zanesl by tě nevím kam, já pak jda, oznámil bych Achabovi, a když by tě nenalezl, zabil by mne. Služebník zajisté tvůj bojí se Hospodina od mladosti své.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 13, 'Zdaliž není oznámeno pánu mému, co jsem učinil, když Jezábel mordovala proroky Hospodinovy, že jsem skryl z proroků Hospodinových sto mužů, po padesáti mužích v jeskyni, a krmil jsem je chlebem a vodou?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 14, 'Ty pak nyní pravíš: Jdi, pověz pánu svému: Aj, Eliáš přišel. A zamordujeť mne.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 15, 'Odpověděl Eliáš: Živť jest Hospodin zástupů, před jehož oblíčejem stojím, žeť se jemu dnes ukáži.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 16, 'A tak šel Abdiáš vstříc Achabovi, a oznámil jemu. Pročež šel i Achab v cestu Eliášovi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 17, 'A když uzřel Achab Eliáše, řekl Achab k němu: Zdaliž ty nejsi ten, kterýž kormoutíš lid Izraelský?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 18, 'Kterýž odpověděl: Jáť nekormoutím lidu Izraelského, ale ty a dům otce tvého, když opouštíte přikázaní Hospodinova a následujete Bálů.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 19, 'Protož nyní pošli a shromažď ke mně všecken lid Izraelský na horu Karmel, a proroků Bálových čtyři sta a padesáte, i proroků toho háje čtyři sta, kteříž jedí z stolu Jezábel.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 20, 'Obeslal tedy Achab všecky syny Izraelské, a shromáždil ty proroky na horu Karmel.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 21, 'A přistoupiv Eliáš ke všemu lidu, řekl: I dokudž kulhati budete na obě straně? Jestližeť jest Hospodin Bohem, následujtež ho; pakli jest Bál, jdětež za ním. A neodpověděl jemu lid žádného slova.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 22, 'Opět řekl Eliáš lidu: Já sám toliko pozůstal jsem prorok Hospodinův, proroků pak Bálových jest čtyři sta a padesáte mužů.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 23, 'Nechť jsou nám dáni dva volkové, a ať vyberou sobě volka jednoho, kteréhož nechť rozsekají na kusy a vkladou na dříví, ale ohně ať nepodkládají. Jáť také připravím volka druhého, kteréhož vložím na dříví, a ohně nepodložím.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 24, 'Tedy vzývejte jméno bohů vašich, já pak vzývati budu jméno Hospodinovo, a budeť to, že Bůh, kterýž se ohlásí skrze oheň, ten jest Bůh. A odpověděl všecken lid, řka: Dobráť jest řeč tato.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 25, 'I řekl Eliáš prorokům Bálovým: Vybeřte sobě volka jednoho a připravte ho nejprvé, poněvadž jest vás více, a vzývejte jméno bohů vašich, ale ohně nepodkládejte.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 26, 'A tak vzali volka, kteréhož jim dal, a připravili a vzývali jméno Bálovo od jitra až do poledne, říkajíce: Ó Báli, uslyš nás. Ale nebylo hlasu, ani kdo by odpověděl. I skákali u oltáře, kterýž byli udělali.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 27, 'Když pak bylo poledne, posmíval se jim Eliáš a řekl: Křičte vysokým hlasem, poněvadž bůh jest. Neb snad rozmlouvání má, neb jinou práci, neb jest na cestě, anebť spí, ať procítí.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 28, 'Takž křičeli hlasem velikým, a bodli se vedlé obyčeje svého nožíky a špicemi, tak až se krví polívali.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 29, 'I stalo se, když již bylo s poledne, že prorokovali až dotud, když se obětuje obět suchá, ale nebylo žádného se ohlášení, ani kdo by odpověděl, ani kdo by vyslyšel.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 30, 'Zatím řekl Eliáš všemu lidu: Přistuptež ke mně. I přistoupil všecken lid k němu. Tedy opravil oltář Hospodinův, kterýž byl zbořený.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 31, 'Nebo vzal Eliáš dvanácte kamenů, (vedlé počtu pokolení synů Jákobových, k němuž se byla stala řeč Hospodinova, že Izrael bude jméno jeho,)');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 32, 'A vzdělal z těch kamenů oltář ve jménu Hospodinovu; udělal také struhu vůkol oltáře zšíří, co by mohl dvě míry obilé vsíti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 33, 'Narovnal i dříví, a rozsekav volka na kusy, vkladl na dříví.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 34, 'A řekl: Naplňte čtyři stoudve vodou, a vylíte na obět zápalnou i na dříví. Řekl opět: Učiňtež to po druhé. I učinili po druhé. Řekl ještě: Po třetí učiňte. I učinili po třetí,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 35, 'Tak že tekly vody okolo oltáře; také i struhu naplnila voda.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 36, 'Stalo se pak, když se obětuje obět suchá, přistoupil Eliáš prorok a řekl: Hospodine Bože Abrahamův, Izákův a Izraelův, nechť dnes poznají, že jsi ty Bůh v Izraeli, a já služebník tvůj, a že jsem vedlé slova tvého činil všecky věci tyto.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 37, 'Vyslyš mne, Hospodine, vyslyš mne, aťby poznal lid tento, že jsi ty, Hospodine, Bohem, když bys obrátil srdce jejich zase.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 38, 'V tom spadl oheň Hospodinův, a spálil obět zápalnou, dříví i kamení i prsť; též vodu, kteráž byla v struze, vypil.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 39, 'Což když uzřel všecken ten lid, padli na tváři své a řekli: Hospodinť jest Bohem, Hospodin jest Bohem.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 40, 'I řekl jim Eliáš: Zjímejte ty proroky Bálovy, žádný ať z nich neujde. I zjímali je. Kteréž svedl Eliáš ku potoku Císon, a tam je zmordoval.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 41, 'Tedy řekl Eliáš Achabovi: Jdi, pojez a napí se, nebo aj, zvuk velikého deště.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 42, 'I jel Achab, aby pojedl a napil se. Eliáš pak vstoupil na vrch Karmele, a rozprostřel se na zemi a sklonil tvář svou k kolenům svým.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 43, 'Potom řekl mládenci svému: Vystup nyní, a pohleď tam k moři. Kterýž vystoupiv, pohleděl a řekl: Nic není. Řekl opět: Vrať se po sedmkrát.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 44, 'I stalo se po sedmé, řekl: Aj, oblak maličký jako dlaň člověčí vystupuje z moře. Ještě řekl: Jdi, rci Achabovi: Zapřáhej a jeď, aby tě nezastihl déšť.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 45, 'Stalo se mezi tím, když se nebesa zamračila oblakem a větrem, odkudž byl déšť veliký, že jel Achab a přišel do Jezreel.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 46, 'Ruka pak Hospodinova byla s Eliášem, tak že přepásav bedra svá, běžel před Achabem, až přišel do Jezreel.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 1, 'Tedy oznámil Achab Jezábel všecko to, což učinil Eliáš, a že naprosto všecky proroky její pobil mečem.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 2, 'A protož poslala Jezábel posla k Eliášovi, řkuci: Toto ať mi učiní bohové a toto přidadí, jestliže v tuto hodinu zítra neučiním tobě, jako ty kterému z nich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 3, 'Což když zvěděl, vstana, odšel pro zachování života svého, a přišel do Bersabé, jenž jest v Judstvu, kdež nechal mládence svého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 4, 'Sám pak šel předce po poušti cestou dne jednoho, a přišed, usadil se pod jedním jalovcem, a žádal sobě smrti a řekl: Jižť jest dosti, ó Hospodine, vezmi duši mou, nebť nejsem lepší otců svých.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 5, 'I lehl a usnul pod tím jalovcem. A aj, v touž chvíli anděl dotekl se ho a řekl jemu: Vstaň, pojez.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 6, 'A když pohleděl vůkol, a aj, u hlavy jeho chléb na uhlí pečený a číše vody. I pojedl a napil se, a lehl zase.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 7, 'Opět vrátiv se anděl Hospodinův po druhé, dotekl se ho a řekl: Vstaň, pojez, nebo velmi dlouhou máš cestu před sebou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 8, 'A vstav, jedl a pil, a šel v síle pokrmu toho čtyřidceti dní a čtyřidceti nocí, až na horu Boží Oréb.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 9, 'Kdežto všed do jakési jeskyně, nocoval tam. A aj, řeč Hospodinova k němu, a řekl jemu: Co tu děláš, Eliáši?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 10, 'Kterýž odpověděl: Velice jsem horlil pro Hospodina Boha zástupů; nebo opustili smlouvu tvou synové Izraelští, oltáře tvé zbořili a proroky tvé zmordovali mečem. I zůstal jsem já sám, teď pak hledají života mého, aby mi jej odjali.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 11, 'Řekl Bůh: Vyjdi a stůj na hoře před Hospodinem. A aj, Hospodin šel tudy, a vítr veliký a silný, podvracující hory a rozrážející skály před Hospodinem, ale nebyl v tom větru Hospodin. Za tím pak větrem země třesení, ale nebyl v tom třesení Hospodin.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 12, 'A za třesením oheň, ale nebyl v ohni Hospodin. A za ohněm hlas tichý a temný.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 13, 'Což když uslyšel Eliáš, zavinul tvář svou pláštěm svým, a vyšed, stál u dveří jeskyně, a aj, hlas k němu, řkoucí: Co tu děláš, Eliáši?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 14, 'Kterýž odpověděl: Náramně horlil jsem pro Hospodina Boha zástupů; nebo opustili smlouvu tvou synové Izraelští, oltáře tvé zbořili, a proroky tvé pomordovali mečem. I zůstal jsem já sám, teď pak hledají života mého, aby mi jej odjali.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 15, 'Ale Hospodin řekl jemu: Jdi, navrať se cestou svou k Damašské poušti, kdežto přijda, pomažeš Hazaele za krále nad Syrií.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 16, 'Jéhu také syna Namsi pomažeš za krále nad Izraelem, a Elizea syna Safatova z Abelmehula pomažeš za proroka místo sebe.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 17, 'I stane se, že toho, kdož by ušel meče Hazaelova, zamorduje Jéhu, a toho, kdož by ušel meče Jéhu, zamorduje Elizeus.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 18, 'Zachovalť jsem pak v Izraeli sedm tisíců, jichžto všech kolena neskláněla se Bálovi, a jichžto všech ústa nelíbala ho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 19, 'A tak odšed odtud, nalezl Elizea syna Safatova, an oře, a dvanáctero spřežení před ním, sám také byl při dvanáctém. A jda mimo něj Eliáš, uvrhl plášť svůj na něj.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 20, 'Kterýž zanechav volů, běžel za Eliášem a řekl: Prosím, nechť políbím otce svého a matky své, i půjdu za tebou. Jemuž řekl: Jdi, vrať se zase, nebo vidíš, coť jsem učinil.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 21, 'Navrátil se tedy od něho, a vzav pár volů, zabil je a dřívím z pluhu uvařil maso jejich, kteréž dal lidu, i jedli. A vstav, šel za Eliášem a přisluhoval jemu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 1, 'Tedy Benadad král Syrský, shromáždiv všecka vojska svá, a maje s sebou třidceti a dva krále, též koně i vozy, vytáhl a oblehl Samaří a dobýval ho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 2, 'I poslal posly k Achabovi králi Izraelskému do města,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 3, 'A vzkázal jemu: Takto praví Benadad: Stříbro tvé a zlato tvé mé jest, též ženy tvé i synové tvoji nejzdárnější moji jsou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 4, 'I odpověděl král Izraelský a řekl: Vedlé řeči tvé, pane můj králi, tvůj jsem i všecko, což mám.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 5, 'Opět navrátivše se poslové, řekli: Takto praví Benadad: Poslal jsem k tobě, aťby řekli: Stříbro své a zlato své, ženy své i syny své dáš mi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 6, 'Ale však o tomto čase zítra pošli služebníky své k tobě, aby přehledali dům tvůj i domy služebníků tvých, a oniť všecko, cožkoli máš nejlepšího, vezmouce v ruce své, poberou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 7, 'A tak povolav král Izraelský všech starších země té, řekl: Posuďte medle, a vizte, jakť ten zlého hledá; nebo poslal ke mně pro ženy mé a pro syny mé, též pro stříbro mé i pro zlato mé, a neodepřel jsem jemu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 8, 'I řekli jemu všickni starší a všecken lid: Neposlouchejž ho, ani mu povoluj.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 9, 'Protož odpověděl poslům Benadadovým: Povězte pánu mému králi: Všecko to, o čež jsi poslal k služebníku svému prvé, učiním, ale této věci učiniti nemohu. Takž odešli poslové, a donesli mu tu odpověd.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 10, 'Ještě poslal k němu Benadad a řekl: Toto ať mi učiní bohové a toto ať přidadí, dostane-li se prachu Samařského do hrstí všeho lidu, kterýž jest se mnou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 11, 'Zase odpověděl král Izraelský a řekl: Povězte, ať se nechlubí ten, kterýž se strojí do zbroje, jako ten, kterýž svláčí zbroj.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 12, 'I stalo se, když uslyšel tu řeč, (nebo pil on i králové v staních), že řekl služebníkům svým: Přitrhněte. I přitrhli k městu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 13, 'A hle, prorok nějaký přišed k Achabovi králi Izraelskému, řekl: Toto praví Hospodin: Zdaliž jsi neviděl všeho množství tohoto velikého? Hle, já dám je dnes v ruku tvou, abys poznal, že já jsem Hospodin.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 14, 'A když řekl Achab: Skrze koho? odpověděl on: Tak praví Hospodin: Skrze služebníky knížat krajů. Řekl ještě: Kdo svede tu bitvu? Odpověděl: Ty.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 15, 'A protož sečtl služebníky knížat krajů, jichž bylo dvě stě třidceti a dva; po nich sečtl i všecken lid všech synů Izraelských, sedm tisíců.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 16, 'I vytáhli o poledni. Benadad pak pil a ožral se v staních, on i třidceti a dva králové pomocníci jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 17, 'A tak vytáhli služebníci knížat krajů nejprvé. I poslal Benadad, (když mu pověděli, řkouce: Muži vytáhli z Samaří,)');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 18, 'A řekl: Buď že vytáhli o pokoj, zjímejte je živé, buď že k bitvě vytáhli, zjímejte je živé.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 19, 'Tak, pravím, vytáhli z města ti služebníci knížat krajů, a vojsko za nimi táhlo.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 20, 'A porazili jeden každý muže svého, tak že utíkali Syrští, Izraelští pak honili je. Ale Benadad král Syrský utekl na koni s jízdnými.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 21, 'Potom vytáhl král Izraelský, a pobil koně i vozy zkazil, a tak porazil Syrské ranou velikou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 22, 'Opět přišel prorok ten k králi Izraelskému, a řekl jemu: Jdiž, zmužile se měj a věz i viz, co bys měl činiti; nebo zase po roce král Syrský vytáhne proti tobě.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 23, 'Tedy služebníci krále Syrského řekli jemu: Bohové hor jsouť bohové jejich, protož nás přemohli; ale bojujme proti nim na rovinách, zvíš, nepřemůžeme-li jich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 24, 'Protož učiň toto: Odbuď těch králů, jednoho každého z místa jeho, a postav vývody místo nich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 25, 'Ty pak sečti sobě vojsko z svých jako vojsko oněch, kteříž padli, a koně jako ony koně, a vozy jako ony vozy; i budeme bojovati proti nim na rovinách, a zvíš, nepřemůžeme-liť jich. I uposlechl hlasu jejich a učinil tak.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 26, 'I stalo se po roce, že sečtl Benadad Syrské a vytáhl do Afeku, aby bojoval proti Izraelovi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 27, 'Izraelští také sečteni jsou, a opatřivše se stravou, vytáhli jim v cestu. I položili se Izraelští proti nim jako dvě malá stáda koz, Syrští pak přikryli tu zemi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 28, 'V tom přišel týž muž Boží, a mluvil králi Izraelskému a řekl: Takto praví Hospodin: Proto že pravili Syrští: Bohem hor jest Hospodin a ne Bohem rovin, dám všecko množství toto veliké v ruce tvé, abyste věděli, že já jsem Hospodin.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 29, 'A tak leželi oni proti nim za sedm dní; i stalo se dne sedmého, že svedli bitvu. I porazili synové Izraelští z Syrských sto tisíc pěších dne jednoho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 30, 'Jiní pak zutíkali do města Afeku, kdež padla zed na dvadceti a sedm tisíc mužů, kteříž byli pozůstali. Ale Benadad utíkaje, přišel do města, do nejtajnějšího pokoje.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 31, 'I řekli jemu služebníci jeho: Aj, toto jsme slýchali, že králové domu Izraelského jsou králové milosrdní. Medle, nechť vezmeme pytle na bedra svá a provazy na hlavy své, a vejdeme k králi Izraelskému; snad při životu zachová tebe.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 32, 'A protož přepásali pytli bedra svá, a provazy vzali na hlavy své, a přišli k králi Izraelskému a řekli: Služebník tvůj Benadad praví: Prosím, nechť jsem zachován při životu. Kterýž řekl: Což jest ještě živ? Bratr tě můj.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 33, 'Muži pak ti soudíc to za dobré znamení, rychle chytili ta slova od něho a řekli: Bratrť jest tvůj Benadad. I řekl: Jděte, přiveďte ho sem. Takž vyšel k němu Benadad, i kázal mu vstoupiti na svůj vůz.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 34, 'Tedy řekl jemu Benadad: Města, kteráž otec můj pobral otci tvému, navrátímť, a ulice zděláš sobě v Damašku, jako byl udělal otec můj v Samaří. I odpověděl: Já vedlé smlouvy této propustím tě. A tak učinil s ním smlouvu a propustil ho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 35, 'Muž pak nějaký z synů prorockých řekl bližnímu svému z rozkazu Božího: Ubí mne medle. Ale muž ten nechtěl ho bíti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 36, 'Kterýž řekl jemu: Proto že jsi neuposlechl hlasu Hospodinova, aj teď, když půjdeš ode mne, udáví tě lev. A když šel od něho, trefil na něj lev a udávil ho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 37, 'Opět nalezl muže druhého, jemuž řekl: Medle, ubí mne. Kterýž ubil ho velice a ranil.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 38, 'I odšed prorok ten, postavil se králi v cestě, a změnil se, zavěsiv sobě oči.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 39, 'A když král pomíjel, zvolal na něj a řekl: Služebník tvůj vyšel do bitvy, a hle, jeden odšed, přivedl ke mně muže a řekl: Ostříhej toho muže, jestliže se pak ztratí, budeť život tvůj za život jeho, aneb centnéř stříbra položíš.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 40, 'V tom když služebník tvůj toho i onoho hleděl, tožť se ztratil. Pročež řekl jemu král Izraelský: Takový buď soud tvůj, jakýž jsi sám vypověděl.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 41, 'Tedy rychle odhradil tvář svou, a poznal ho král Izraelský, že by z proroků byl.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 42, 'I řekl jemu: Takto praví Hospodin: Poněvadž jsi z ruky pustil muže k smrti odsouzeného, budeť život tvůj za život jeho, a lid tvůj za lid jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 43, 'Protož odjel král Izraelský do domu svého, smutný jsa a hněvaje se, a přišel do Samaří.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 1, 'Stalo se pak po těch věcech, měl Nábot Jezreelský vinici, kteráž byla v Jezreel podlé paláce Achaba krále Samařského.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 2, 'I mluvil Achab k Nábotovi, řka: Dej mi vinici svou, ať ji mám místo zahrady k zelinám, poněvadž jest blízko podlé domu mého, a dámť za ni vinici lepší, než ta jest, aneb jestližeť se vidí, dámť stříbra cenu její.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 3, 'Odpověděl Nábot Achabovi: Nedejž mi toho Hospodin, abych měl dáti dědictví otců mých tobě.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 4, 'Tedy přišel Achab do domu svého, smutný jsa a hněvaje se pro řeč, kterouž mluvil jemu Nábot Jezreelský, řka: Nedám tobě dědictví otců svých. I lehl na lůžko své, a odvrátiv tvář svou, ani chleba nejedl.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 5, 'V tom přišedši k němu Jezábel žena jeho, řekla jemu: Proč tak smutný jest duch tvůj, že ani nejíš chleba?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 6, 'Kterýž odpověděl jí: Proto že jsem mluvil s Nábotem Jezreelským, a řekl jsem jemu: Dej mi vinici svou za peníze, aneb jestliže raději chceš, dámť jinou vinici za ni. On pak odpověděl: Nedám tobě své vinice.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 7, 'I řekla mu Jezábel žena jeho: Takliž bys ty nyní spravoval království Izraelské? Vstaň, pojez chleba a buď dobré mysli, já tobě dám vinici Nábota Jezreelského.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 8, 'Zatím napsala list jménem Achabovým, kterýž zapečetila jeho pečetí, a poslala ten list k starším a předním města jeho, spoluobyvatelům Nábotovým.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 9, 'Napsala pak v tom listu takto: Vyhlaste půst, a posaďte Nábota mezi předními z lidu,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 10, 'A postavte dva muže nešlechetné proti němu, kteříž by svědčili na něj, řkouce: Zlořečil jsi Bohu a králi. Potom vyveďte ho a ukamenujte jej, ať umře.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 11, 'Učinili tedy muži města toho, starší a přední, kteříž bydlili v městě jeho, jakž rozkázala jim Jezábel, tak jakž psáno bylo v listu, kterýž jim byla poslala.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 12, 'Vyhlásili půst, a posadili Nábota mezi předními z lidu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 13, 'Potom přišli ti dva muži nešlechetní, a posadivše se naproti němu, svědčili proti němu muži ti nešlechetní, proti Nábotovi před lidem, řkouce: Zlořečil Nábot Bohu a králi. I vyvedli ho za město a kamenovali jej, až umřel.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 14, 'A poslali k Jezábel, řkouce: Ukamenovánť jest Nábot a umřel.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 15, 'I stalo se, jakž uslyšela Jezábel, že by ukamenován byl Nábot, a že by umřel, řekla Achabovi: Vstaň, vládni vinicí Nábota Jezreelského, kteréžť nechtěl dáti za peníze; neboť není živ Nábot, ale umřel.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 16, 'A tak uslyšev Achab, že by umřel Nábot, vstal, aby šel do vinice Nábota Jezreelského, a aby ji ujal.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 17, 'Tedy stala se řeč Hospodinova k Eliášovi Tesbitskému, řkoucí:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 18, 'Vstana, vyjdi vstříc Achabovi králi Izraelskému, kterýž bydlí v Samaří, a hle, jest na vinici Nábotově, do níž všel, aby ji ujal.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 19, 'A mluviti budeš k němu těmito slovy: Takto praví Hospodin: Zdaliž jsi nezabil, ano sobě i nepřivlastnil? Mluv tedy k němu, řka: Takto praví Hospodin: Proto že lízali psi krev Nábotovu, i tvou krev také lízati budou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 20, 'I řekl Achab Eliášovi: Což jsi mne našel, nepříteli můj? Kterýž odpověděl: Našel, nebo jsi prodal se, abys činil to, což zlého jest před oblíčejem Hospodinovým.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 21, 'Aj, já uvedu na tebe zlé, a odejmu potomky tvé, a vypléním z domu Achabova močícího na stěnu, i zajatého i zanechaného v Izraeli.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 22, 'A učiním s domem tvým jako s domem Jeroboáma syna Nebatova, a jako s domem Bázy syna Achiášova, pro zdráždění, kterýmž jsi mne popudil, a že jsi k hřešení přivodil Izraele.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 23, 'Ano i proti Jezábel mluvil Hospodin, řka: Psi žráti budou Jezábel mezi zdmi Jezreelskými.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 24, 'Toho, kdož umře z domu Achabova v městě, psi žráti budou, a kdož umře na poli, ptáci nebeští jísti budou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 25, 'Nebo nebylo podobného Achabovi, kterýž by se prodal, aby činil to, což zlého jest před oblíčejem Hospodinovým, proto že ho ponoukala Jezábel žena jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 26, 'Dopouštěl se zajisté věcí velmi ohavných, následuje modl vedlé všeho toho, čehož se dopouštěli Amorejští, kteréž vyplénil Hospodin od tváři synů Izraelských.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 27, 'I stalo se, když uslyšel Achab slova tato, že roztrhl roucho své, a vzav žíni na tělo své, postil se a léhal na pytli, a chodil krotce.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 28, 'Tedy stala se řeč Hospodinova k Eliášovi Tesbitskému, řkoucí:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 29, 'Viděl-lis, jak se ponížil Achab před tváří mou? Poněvadž se tak ponížil před tváří mou, neuvedu toho zlého za dnů jeho, ale za dnů syna jeho uvedu to zlé na dům jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 1, 'Nebylo pak za tři léta války mezi Syrskými a Izraelskými.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 2, 'I stalo se léta třetího, přijel Jozafat král Judský k králi Izraelskému.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 3, 'Mluvil pak byl král Izraelský služebníkům svým: Víte-li, že naše bylo Rámot Galád, a my zanedbáváme vzíti ho zase z moci krále Syrského?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 4, 'Pročež řekl Jozafatovi: Potáhneš-li se mnou na vojnu proti Rámot Galád? Odpověděl Jozafat králi Izraelskému: Jako jsem já, tak jsi ty, jako lid můj, tak lid tvůj, jako koni moji, tak koni tvoji.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 5, 'Řekl také Jozafat králi Izraelskému: Vzeptej se dnes medle na slovo Hospodinovo.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 6, 'I shromáždil král Izraelský proroků okolo čtyř set mužů a řekl jim: Mám-li táhnouti na vojnu proti Rámot Galád, či tak nechati? I řekli: Táhni, nebo dá je Pán v ruku krále.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 7, 'Tedy řekl Jozafat: Což není zde již žádného proroka Hospodinova, abychom se ho zeptali?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 8, 'Na to řekl král Izraelský Jozafatovi: Ještěť jest muž jeden, skrze něhož bychom se mohli poraditi s Hospodinem, ale já ho nenávidím, proto že mi dobrého neprorokuje, než zlé, Micheáš syn Jemlův. Ale Jozafat řekl: Nechť tak nemluví král.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 9, 'Protož povolav král Izraelský komorníka jednoho, řekl: Přiveď sem rychle Micheáše syna Jemlova.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 10, '(Mezi tím král Izraelský a Jozafat král Judský, jeden každý na stolici své, odění jsouce rouchem, seděli v placu u vrat brány Samařské, a všickni proroci prorokovali před nimi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 11, 'Sedechiáš pak syn Kenanův udělal sobě byl rohy železné a řekl: Takto praví Hospodin: Těmito trkati budeš Syrské, dokudž nepohubíš jich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 12, 'Takž podobně i jiní všickni proroci prorokovali, řkouce: Jeď do Rámot Galád, a šťastněť se povede; nebo dá je Hospodin v ruku královu.)');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 13, 'V tom posel ten, kterýž šel, aby zavolal Micheáše, mluvil jemu, řka: Aj, nyní slova proroků jedněmi ústy předpovídají dobré věci králi. Medle, buď řeč tvá jako řeč kterého z nich, a mluv dobré věci.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 14, 'Tedy řekl Micheáš: Živť jest Hospodin, že což mi koli řekne Hospodin, to mluviti budu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 15, 'A když přišel k králi, řekl jemu král: Micheáši, máme-li jeti na vojnu proti Rámot Galád, či tak nechati? Kterýž řekl jemu: Jeď a šťastněť se povede, nebo dá je Hospodin v ruku krále.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 16, 'I řekl jemu král: I kolikrátž tě mám přísahou zavazovati, abys mi nemluvil než pravdu ve jménu Hospodinovu?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 17, 'Protož řekl: Viděl jsem všecken lid Izraelský rozptýlený po horách jako ovce, kteréž nemají pastýře; nebo řekl Hospodin: Nemají pána tito, navrať se jeden každý do domu svého v pokoji.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 18, 'I řekl král Izraelský Jozafatovi: Zdaližť jsem neřekl, že mi nebude prorokovati dobrého, ale zlé?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 19, 'Řekl dále: Z té příčiny slyš slovo Hospodinovo: Viděl jsem Hospodina sedícího na stolici své, a všecko vojsko nebeské stojící po pravici jeho i po levici jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 20, 'I řekl Hospodin: Kdo oklamá Achaba, aby vytáhl a padl u Rámot Galád? A když pravil ten toto, a jiný pravil jiné,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 21, 'Tožť vyšel jakýsi duch, a postaviv se před Hospodinem, řekl: Já ho oklamám. Hospodin pak řekl jemu: Jakým způsobem?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 22, 'Odpověděl: Vyjdu a budu duchem lživým v ústech všech proroků jeho. Kterýžto řekl: Oklamáš a dovedeš toho; vyjdiž a učiň tak.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 23, 'Protož, aj, jižtě dal Hospodin ducha lživého v ústa všech proroků tvých těchto, ješto však Hospodin mluvil zlé proti tobě.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 24, 'Tedy přistoupiv Sedechiáš syn Kenanův, dal Micheášovi poliček a řekl: Kudyže odšel duch Hospodinův ode mne, aby mluvil tobě?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 25, 'Odpověděl Micheáš: Aj, uzříš v ten den, když vejdeš do nejtajnějšího pokoje, abys se skryl.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 26, 'I řekl král Izraelský: Jmi Micheáše, a doveď ho k Amonovi knížeti města, a k Joasovi synu královu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 27, 'A řekneš: Takto praví král: Dejte tohoto do žaláře, a dávejte mu jísti maličko chleba a maličko vody, dokudž se nenavrátím v pokoji.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 28, 'Ale Micheáš řekl: Jestliže ty se navrátíš v pokoji, tedyť nemluvil skrze mne Hospodin. Přes to řekl: Slyštež to všickni lidé!');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 29, 'A tak táhl král Izraelský, a Jozafat král Judský proti Rámot Galád.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 30, 'I řekl král Izraelský Jozafatovi: Změním já se, když půjdu k bitvě, ale ty oblec se v roucho své. I změnil se král Izraelský a jel k bitvě.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 31, 'Král pak Syrský přikázal třidcíti dvěma svým hejtmanům nad vozy, a řekl: Nebojujte proti malému ani proti velikému, než proti samému králi Izraelskému.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 32, 'I stalo se, když uzřeli hejtmané nad vozy Jozafata, řekli: Jistě král Izraelský jest. I obrátili se proti němu, aby bojovali. Tedy zkřikl Jozafat.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 33, 'V tom když uzřeli hejtmané nad vozy, že on není král Izraelský, obrátili se od něho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 34, 'Muž pak jeden střelil z lučiště náhodou, a postřelil krále Izraelského, kdež se pancíř spojuje. Pročež řekl vozkovi svému: Obrať se a vyvez mne z vojska, nebo jsem nemocen.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 35, 'I rozmohla se bitva v ten den. Král pak stál na voze proti Syrským; potom umřel u večer, a tekla krev z rány do vozu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 36, 'I volal biřic po vojště, když již slunce zapadlo, řka: Jeden každý do města svého, a jeden každý do země své navrať se.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 37, 'Umřel tedy král a dovezen jest do Samaří, i pochovali ho v Samaří.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 38, 'A když pohřížen byl vůz v rybníku Samařském, střebali psi krev jeho, též když umývali zbroj jeho, vedlé řeči Hospodinovy, kterouž byl mluvil.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 39, 'Jiné pak věci Achabovy, a cožkoli činil, i jaký dům z kostí slonových vystavěl, i všecka města, kteráž vzdělal, o tom zapsáno jest v knize o králích Izraelských.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 40, 'A tak usnul Achab s otci svými, a kraloval Ochoziáš syn jeho místo něho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 41, 'Jozafat pak syn Azy počal kralovati nad Judou léta čtvrtého Achaba, krále Izraelského.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 42, 'A byl Jozafat ve třidcíti pěti letech, když počal kralovati, a dvadceti pět let kraloval nad Jeruzalémem, jehož matky jméno bylo Azuba, dcera Silchi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 43, 'I chodil po vší cestě Azy otce svého, aniž se od ní uchýlil, čině, což dobrého bylo před oblíčejem Hospodinovým. Toliko poněvadž výsostí nezkazili, ještě lid obětoval a kadil na těch výsostech.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 44, 'Všel také v pokoj král Jozafat s králem Izraelským.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 45, 'Jiné pak věci Jozafatovy, i síla jeho, kterouž prokazoval a kterouž bojoval, zapsány jsou v knize o králích Judských.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 46, 'Ten ostatky ohyzdných sodomářů, kteříž ještě pozůstali za dnů Azy otce jeho, vyplénil z země.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 47, 'Tehdáž nebylo žádného krále v zemi Idumejské, hejtmana měli místo krále.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 48, 'I nadělal Jozafat lodí mořských, aby jeli do Ofir pro zlato. Ale nejeli, nebo polámaly se lodí v Aziongaber.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 49, 'Řekl byl také Ochoziáš syn Achabův Jozafatovi: Nechť jedou služebníci moji s služebníky tvými na lodech. Ale Jozafat nechtěl.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 50, 'I usnul Jozafat s otci svými, a pochován jest s otci svými v městě Davida otce svého; kraloval pak Joram syn jeho místo něho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 51, 'Ochoziáš syn Achabův počal kralovati nad Izraelem v Samaří, léta sedmnáctého Jozafata krále Judského, a kraloval nad Izraelem dvě létě.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 52, 'Nebo činil zlé věci před oblíčejem Hospodinovým, a chodil po cestě otce svého a po cestě matky své, i po cestě Jeroboáma syna Nebatova, kterýž přivodil k hřešení lid Izraelský.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 53, 'Sloužil také Bálovi a klaněl se jemu, čímž popudil k hněvu Hospodina Boha Izraelského vedlé toho všeho, což činil otec jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 1, 'V tom zprotivil se Moáb Izraelovi po smrti Achabově.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 2, 'A Ochoziáš spadl skrze mříži paláce svého letního, kterýž byl v Samaří, a stonal. I poslal posly, řka jim: Jděte, pilně se ptejte Belzebuba, boha Akaron, povstanu-li z nemoci této?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 3, 'Ale anděl Hospodinův řekl Eliášovi Tesbitskému: Vstana, jdi vstříc poslům krále Samařského a mluv k nim: Zdali není Boha v Izraeli, že jdete dotazovati se Belzebuba, boha Akaron?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 4, 'Protož takto praví Hospodin: S ložce, na kterémžs se složil, nesejdeš, ale jistotně umřeš. I odšel Eliáš.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 5, 'A když se navrátili poslové k němu, řekl jim: Pročež jste se zase vrátili?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 6, 'Odpověděli jemu: Muž nějaký vyšel nám v cestu a řekl nám: Jděte, navraťte se k králi, kterýž vás poslal, a rcete jemu: Takto praví Hospodin: Zdali není Boha v Izraeli, že ty posíláš tázati se Belzebuba, boha Akaron? Protož s ložce, na kterémžs se složil, nesejdeš, ale jistotně umřeš.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 7, 'I řekl jim: Jaký jest způsob muže toho, kterýž vám vstříc vyšel a mluvil vám ty řeči?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 8, 'Kteříž odpověděli jemu: Jest člověk chlupatý, a pasem koženým přepásán na bedrách svých. Tedy řekl: Eliáš Tesbitský jest.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 9, 'Protož poslal pro něj padesátníka s padesáti jeho. Kterýž šel k němu, a aj, seděl na vrchu hory. I řekl jemu: Muži Boží, král rozkázal, abys sstoupil dolů.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 10, 'Odpovídaje Eliáš, řekl padesátníku: Jestliže jsem muž Boží, nechť sstoupí oheň s nebe, a sžíře tě i tvých padesát. A tak sstoupil oheň s nebe, a sežral jej i padesát jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 11, 'Opět poslal k němu král padesátníka jiného s padesáti jeho. Kterýž mluvil a řekl jemu: Muži Boží, takto rozkázal král: Rychle sstup dolů.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 12, 'I odpověděl Eliáš a řekl jim: Jestliže jsem muž Boží, nechť sstoupí oheň s nebe, a sžíře tě i tvých padesát. A tak sstoupil oheň Boží s nebe, a sežral jej i padesát jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 13, 'Ještě poslal padesátníka třetího s padesáti jeho. Pročež vstoupiv, přišel ten třetí padesátník, a klekl na kolena svá před Eliášem, a prose ho pokorně, řekl jemu: Muži Boží, prosím, nechť jest drahá duše má i duše služebníků tvých padesáti těchto před očima tvýma.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 14, 'Aj, oheň sstoupiv s nebe, sežral dva první padesátníky s padesáti jejich, ale nyní nechť jest drahá duše má před očima tvýma.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 15, 'Řekl pak anděl Hospodinův Eliášovi: Sstup s ním, neboj se nic tváři jeho. Tedy vstav, šel s ním k králi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 16, 'A mluvil jemu: Takto praví Hospodin: Proto že jsi poslal posly tázati se Belzebuba, boha Akaron, (jako by nebylo Boha v Izraeli, abys se tázal slova jeho), protož s ložce, na kterémžs se složil, nesejdeš, ale jistotně umřeš.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 17, 'I umřel podlé řeči Hospodinovy, kterouž mluvil Eliáš, a kraloval Joram místo něho léta druhého Jehorama syna Jozafatova, krále Judského; nebo on neměl syna.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 18, 'O jiných pak věcech Ochoziášových, kteréž činil, zapsáno jest v knize o králích Izraelských.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 1, 'Stalo se potom, když měl již vzíti Hospodin Eliáše u vichru do nebe, že vyšel Eliáš s Elizeem z Galgala.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 2, 'I řekl Eliáš Elizeovi: Medle, poseď tuto, nebo Hospodin poslal mne až do Bethel. Jemuž řekl Elizeus: Živť jest Hospodin, a živať jest duše tvá, žeť se tebe nespustím. I přišli do Bethel.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 3, 'Tedy vyšli synové proročtí, kteříž byli v Bethel, k Elizeovi a řekli jemu: Víš-liž, že dnes Hospodin vezme pána tvého od tebe? Kterýž odpověděl: A já vím, mlčte.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 4, 'Opět řekl jemu Eliáš: Elizee, medle poseď tuto, nebo Hospodin poslal mne do Jericha. Kterýž odpověděl: Živť jest Hospodin, a živať jest duše tvá, žeť se tebe nespustím. I přišli do Jericha.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 5, 'Přistoupivše pak synové proročtí, kteříž byli v Jerichu, k Elizeovi, řekli jemu: Víš-liž, že dnes vezme Hospodin pána tvého od tebe? I řekl: A já vím, mlčte.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 6, 'Řekl mu ještě Eliáš: Poseď medle tuto, nebo Hospodin poslal mne k Jordánu. Kterýž odpověděl: Živť jest Hospodin, a živať jest duše tvá, žeť se tebe nespustím. Šli tedy oba.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 7, 'Padesáte pak mužů z synů prorockých šli, a postavili se naproti zdaleka, ale oni oba zastavili se u Jordánu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 8, 'A vzav Eliáš plášť svůj, svinul jej a udeřil na vodu. I rozdělila se sem i tam, tak že přešli oba po suše.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 9, 'V tom když přešli, řekl Eliáš Elizeovi: Žádej sobě, co chceš, prvé než vzat budu od tebe. I řekl Elizeus: Nechť jest, prosím, dvojnásobní díl ducha tvého na mně.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 10, 'Jemuž řekl: Nesnadnés věci požádal, a však jestliže uzříš mne, když budu vzat od tebe, staneť se tak; pakli nic, nestane se.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 11, 'Takž stalo se, že když předce jdouce, rozmlouvali, aj, vůz ohnivý a koni ohniví rozdělili je na různo. I vstoupil Eliáš u vichru do nebe.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 12, 'To vida Elizeus, volal: Otče můj, otče můj! Vozové Izraelští i jezdci jeho! A neviděl ho více. Potom uchopiv roucho své, roztrhl je na dva kusy.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 13, 'A zdvih plášť Eliášův, kterýž byl spadl s něho, navrátil se a stál na břehu Jordánském.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 14, 'Tedy vzav plášť Eliášův, kterýž byl spadl s něho, udeřil na vodu a řekl: Kdež jest Hospodin Bůh Eliášův i on sám? A udeřil, pravím, na vodu, kteráž rozstoupila se sem i tam. I přešel Elizeus.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 15, 'Což vidouce synové proročtí z Jericha, naproti stojíce, řekli: Odpočinul duch Eliášův na Elizeovi. I šli proti němu a poklonili se mu až k zemi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 16, 'A řekli jemu: Aj, nyní jest s služebníky tvými padesáte mužů silných, medle nechť jdou a hledají pána tvého. Snad ho zanesl duch Hospodinův, a povrhl jej na některé hoře aneb v některém údolí. Kterýž řekl: Neposílejte.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 17, 'Ale když na něj vždy dotírali, tak že mu to obtížné bylo, řekl: Pošlete. I poslali padesáte mužů, a hledajíce za tři dni, nenalezli ho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 18, 'A když se k němu navrátili, (on pak bydlil v Jerichu,) řekl jim: Zdaliž jsem vám neřekl: Nechoďte?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 19, 'Muži pak města toho řekli Elizeovi: Hle, nyní byt v městě tomto jest výborný, jakož, pane můj, vidíš, ale vody jsou zlé a země neúrodná.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 20, 'Tedy řekl: Přineste mi nádobu novou, a dejte do ní soli. I přinesli mu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 21, 'A vyšed k pramenu těch vod, vsypal tam sůl a řekl: Takto praví Hospodin: Uzdravuji vody tyto; nebudeť více odtud smrti, ani nedochůdčete.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 22, 'A tak uzdraveny jsou ty vody až do dnešního dne, vedlé řeči Elizeovy, kterouž byl mluvil.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 23, 'Potom šel odtud do Bethel. A když šel cestou, pacholata malá vyšedše z města, posmívali se jemu, říkajíce: Jdi lysý, jdi lysý!');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 24, 'Kterýž ohlédna se, uzřel je a zlořečil jim ve jménu Hospodinovu. Protož vyskočivše dvě nedvědice z lesa, roztrhaly z nich čtyřidcatero a dvé dětí.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 25, 'I šel odtud na horu Karmel, odkudž navrátil se do Samaří.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 1, 'Joram pak syn Achabův počal kralovati nad Izraelem v Samaří léta osmnáctého Jozafata krále Judského, a kraloval dvanácte let.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 2, 'A činil to, což jest zlého před očima Hospodinovýma, ač ne tak jako otec jeho a jako matka jeho; nebo odjal modly Bál, kterýchž byl nadělal otec jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 3, 'A však v hříších Jeroboáma syna Nebatova, kterýž k hřešení přivodil Izraele, vždy vězel, a neodstoupil od nich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 4, 'Mésa pak král Moábský měl hojnost dobytka, a dával králi Izraelskému sto tisíc beranů, a sto tisíc skopců i s vlnou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 5, 'I stalo se, když umřel Achab, že se zprotivil král Moábský králi Izraelskému.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 6, 'Tedy vytáhl v ten čas král Joram z Samaří, a sečtl všecken Izrael.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 7, 'A když táhl, poslal k Jozafatovi králi Judskému, aby mu řekli: Král Moábský zprotivil mi se. Potáhneš-li se mnou proti Moábovi na vojnu? Odpověděl: Potáhnu. Jako jsem já, tak jsi ty, jako lid můj, tak lid tvůj, jakž koni moji, tak koni tvoji.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 8, 'Zatím řekl: Kterouž pak cestou potáhneme? Odpověděl: Cestou pouště Idumejské.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 9, 'A tak vytáhl král Izraelský a král Judský i král Idumejský. A když objížděli cestou za sedm dní, nedostávalo se vody vojsku a hovadům jejich, kteráž měli s sebou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 10, 'I řekl král Izraelský: Ach, běda! Nebo povolal Hospodin tří králů těchto, aby je vydal v ruku Moábovu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 11, 'Ale Jozafat řekl: Není-liž zde proroka Hospodinova, abychom se otázali Hospodina skrze něho? Odpovídaje pak jeden z služebníků krále Izraelského, řekl: Jestiť zde Elizeus syn Safatův, kterýž líval vodu na ruce Eliášovy.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 12, 'Tedy řekl Jozafat: U tohoť jest slovo Hospodinovo. I šli k němu, král Izraelský a Jozafat, i král Idumejský.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 13, 'I řekl Elizeus králi Izraelskému: Co mně do tebe? Jdi k prorokům otce svého a k prorokům matky své. Řekl jemu král Izraelský: Nikoli, nebo povolal Hospodin tří králů těchto, aby je vydal v ruku Moábovu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 14, 'K tomu řekl Elizeus: Živť jest Hospodin zástupů, před jehož oblíčejem stojím, bychť sobě nevážil Jozafata krále Judského, nepohleděl bych na tě, ani popatřil.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 15, 'Ale nyní přiveďte mi toho, kterýž by uměl hráti na harfu. A když on hral, byla nad ním ruka Hospodinova.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 16, 'I řekl: Takto praví Hospodin: Nadělej v tomto potoku množství dolů.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 17, 'Nebo toto dí Hospodin: Neuzříte větru, aniž uzříte přívalu, však potok tento naplněn bude vodou, tak že píti budete i vy i množství vaše, i hovada vaše.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 18, 'A i to málo jest před oblíčejem Hospodinovým, nebo i Moábské dá v ruku vaši.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 19, 'A zkazíte všeliké město hrazené, i všeliké město výborné, též všecko stromoví dobré zporážíte, a všecky studnice vod zasypete, a všeliké pole dobré kamením přiházíte.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 20, 'I stalo se ráno, když obětována bývá obět suchá, a aj, vody přicházely cestou od strany Idumejské, a naplněna jest země vodami.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 21, 'Všecken pak Moáb uslyšev, že by vytáhli králové, aby bojovali proti nim, svolali se všickni, od toho, kterýž se pasem opásati může, a výše, a postavili se na pomezí.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 22, 'Potom ráno vstavše, když slunce vzešlo nad těmi vodami, uzřeli Moábští naproti ty vody rdějící se jako krev.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 23, 'A řekli: Krev jest. Jistě žeť jsou se pohubili ti králové, a zabil jeden každý bližního svého; protož nyní k loupežem, ó Moábští! A přišli až k ležení Izraelskému.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 24, 'Tedy povstavše Izraelští, porazili Moábské, kteříž utíkali před nimi, a oni porazili je porážkou velikou, také i v jejich krajině.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 25, 'Nebo města jejich zbořili, a na všeliké pole výborné házejíce jeden každý kamením svým, naplnili je, i všecky studnice vod zasypali, a všecko stromoví dobré zporáželi, tak že toliko nechali u Kirchareset zdi jeho. Protož shlukše se prakovníci, dobývali ho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 26, 'A vida král Moábský, že jsou mu silní bojovníci ti, vzal s sebou sedm set mužů bojovných, chtě se probiti skrze vojska krále Idumejského. Ale nemohli.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 27, 'Pročež jav syna jeho prvorozeného, kterýž měl kralovati místo něho, obětoval jej v obět zápalnou na zdi. I stalo se rozhněvání veliké proti Izraelovi; protož odtrhše od něho, navrátili se do země své.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 1, 'Tedy žena jedna z manželek synů prorockých volala k Elizeovi, řkuci: Služebník tvůj, muž můj, umřel, ty pak víš, že služebník tvůj bál se Hospodina. A teď věřitel přišel, aby vzal dva syny mé sobě za služebníky.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 2, 'Řekl jí Elizeus: Což chceš, ať učiním? Oznam mi, co máš v domě? Ona řekla: Nemáť služebnice tvá nic v domě, jediné báni oleje.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 3, 'I řekl: Jdi, vyžádej sobě nádob vně ode všech sousedů svých, nádob prázdných tím více.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 4, 'A vejda, zavři za sebou dvéře i za syny svými, a nalévej do všech těch nádob, a kteráž bude plná, rozkážeš ji odstaviti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 5, 'A tak odešla od něho a zavřela dvéře za sebou a za syny svými. Oni podávali jí, a ona nalévala.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 6, 'I stalo se, že když naplnila ty nádoby, řekla synu svému: Podej mi ještě nádoby. Kterýž odpověděl: Již není více nádob. I přestal olej.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 7, 'Tedy ona přišedši, oznámila to muži Božímu. On pak řekl: Jdi, prodej ten olej, a spokoj věřitele svého, ty pak s syny svými budeš se živiti z ostatku.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 8, 'Potom stalo se některého času, že šel Elizeus skrze Sunem, kdež byla jedna žena vzácná, kteráž ho pozdržela, aby jedl u ní. A od toho času chodívaje tudy, stavoval se tam, a jídal chléb.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 9, 'Nebo řekla byla muži svému: Aj, nyní vím, že ten muž Boží svatý jest, kterýž často tudyto chodívá.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 10, 'Medle, udělejme pokojík malý, a postavme tam jemu ložce, stůl, stolici a svícen, aby, když by koli k nám přišel, obrátil se tam.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 11, 'Některého tedy času přišel tam, a všed do toho pokojíku, odpočinul tu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 12, 'I řekl Gézi služebníku svému: Zavolej té Sunamitské. Kterýž zavolal jí. I postavila se před ním.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 13, 'Přitom řekl jemu: Rci jí nyní: Hle, pečuješ a staráš se o nás všelijak. Co chceš, ať učiním? Máš-li jakou potřebu před králem aneb před hejtmanem vojska? Kteráž řekla: U prostřed lidu svého bydlím.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 14, 'Řekl on: Což tedy mám pro ni učiniti? Odpověděl Gézi: Hle, syna nemá, a muž její starý jest.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 15, 'Protož řekl: Zavolej jí. Takž jí zavolal, a ona stála u dveří.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 16, 'I řekl: V času jistém vedlé času života chovati budeš syna. Řekla ona: Nechtěj, pane můj, muži Boží, nechtěj se posmívati služebnici své.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 17, 'Zatím počala žena a porodila syna v času jistém vedlé času života, kterýž předpověděl jí Elizeus.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 18, 'I rostlo dítě. Stalo se pak některého času, že vyšedši k otci svému k žencům,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 19, 'Řeklo otci svému: Hlava má, hlava má! I řekl služebníku: Dones jej k matce jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 20, 'Kterýž když ho vzal a přinesl k matce jeho, seděl na klíně jejím až do poledne a umřel.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 21, 'Tedy ona vstoupivši, položila jej na ložce muže Božího, a zavřevši ho, vyšla.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 22, 'Potom zavolala muže svého a řekla: Medle, pošli mi jednoho z služebníků a jednu oslici, ať doběhnu až k muži Božímu, a zase se navrátím.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 23, 'Kterýž řekl: Proč chceš jíti k němu? Dnes není novměsíce, ani sobota. Odpověděla ona: Měj o to pokoj.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 24, 'Osedlavši tedy oslici, řekla služebníku svému: Pobádej a běž, a nemeškej se pro mne v jízdě, leč bych rozkázala tobě.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 25, 'A tak jela, až přijela k muži Božímu na horu Karmel. A když ji uzřel muž Boží zdaleka, řekl Gézi služebníku svému: Hle, Sunamitská tamto.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 26, 'Protož nyní běž jí v cestu a rci jí: Dobře-li se máš? Dobře-li se má muž tvůj? Dobře-li se má syn? Ona řekla: Dobře.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 27, 'V tom přišla k muži Božímu na horu, a chopila se noh jeho. I přistoupil Gézi, aby ji odehnal. Ale muž Boží řekl: Nechej jí; nebo v hořkosti jest duše její, a Hospodin zatajil to přede mnou, aniž mi oznámil.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 28, 'Ona pak řekla: Zdaliž jsem žádala syna od pána mého? Zdaliž jsem neřekla, abys mne nešálil?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 29, 'Tedy řekl k Gézi: Přepaš bedra svá, a vezmi hůl mou v ruku svou a jdi. Jestliže potkáš koho, nepozdravuj ho, a jestliže tě kdo pozdraví, neodpovídej jemu, a přijda, polož hůl mou na tvář dítěte.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 30, 'I řekla matka dítěte: Živť jest Hospodin a živať jest duše tvá, žeť se tebe nespustím. Protož vstav, bral se za ní.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 31, 'Gézi pak byl předšel je, a položil hůl na tvář dítěte, ale nebylo hlasu, ani čitelnosti. Pročež vracuje se jemu vstříc, pověděl mu, řka: Neprobudilo se dítě.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 32, 'Všel tedy Elizeus do domu, a aj, dítě mrtvé leželo na ložci jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 33, 'A když všel tam, zavřel dvéře před oběma, a modlil se Hospodinu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 34, 'Zatím vstoupiv na lože, zpolehl na dítě, vloživ ústa svá na ústa jeho, a oči své na oči jeho, a ruce své na ruce jeho, a rozprostřel se nad ním. I zahřelo se tělo dítěte.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 35, 'A odvrátiv se, procházel se po domě jednak sem jednak tam; potom vstoupiv, rozprostřel se opět nad ním. I kýchalo dítě až do sedmikrát, a otevřelo to dítě oči své.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 36, 'Tedy zavolav Gézi, řekl: Zavolej Sunamitské. I zavolal jí. A když přišla k němu, řekl jí: Vezmiž syna svého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 37, 'Kteráž jakž vešla, padla k nohám jeho a poklonila se k zemi. I vzala syna svého a vyšla.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 38, 'Potom Elizeus navrátil se do Galgala. Byl pak hlad v té zemi, a synové proročtí seděli před ním. I řekl mládenci svému: Přistav hrnec veliký, a navař kaše synům prorockým.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 39, 'Protož vyšel jeden na pole, aby nasbíral zelin, a nalezl rév polní, a nasbíral z něho tykví polních plnou sukni svou, a přišed, skrájel to do hrnce, aby navařil kaše; nebo neznali toho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 40, 'I vylili mužům těm, aby jedli. Stalo se pak, když jedli tu kaši, že zkřikli a řekli: Smrt v hrnci, muži Boží! A nemohli jísti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 41, 'Kterýžto řekl: Vezměte mouky. Kteréž nasypav do hrnce, rozkázal vyliti lidu. I jedli, aniž co zlého bylo v hrnci.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 42, 'V tom muž přišel z Balsalisa, kterýž přinesl muži Božímu chleby z prvotin, totiž dvadceti chlebů ječných, a klasů nových nevymnutých. I řekl: Dej lidu, ať jedí.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 43, 'Odpověděl služebník jeho: Což to mám předložiti sto mužům? Opět řekl: Dej lidu, ať pojedí. Nebo tak praví Hospodin: Jísti budou, a ještě zůstane.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 44, 'A tak předložil jim, i jedli, a zůstalo ještě vedlé řeči Hospodinovy.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 1, 'Náman hejtman vojska krále Syrského, jsa muž veliký u pána svého, a osoba vzácná, skrze něho zajisté dal Hospodin vysvobození zemi Syrské, ten, pravím, muž tak udatný byl malomocný.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 2, 'Byli pak vyšli z země Syrské lotříkové, kteříž zajali z země Izraelské děvečku malou, a ta sloužila manželce Námanově.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 3, 'Kteráž řekla paní své: Ó by pán můj dostal se k proroku, kterýž jest v Samaří, tedy on by ho uzdravil od malomocenství jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 4, 'A on všed, oznámil pánu svému, řka: Takto a takto pravila děvečka, kteráž jest z země Izraelské.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 5, 'Tedy řekl král Syrský: Jdi, vyprav se, a já pošli list králi Izraelskému. A odcházeje, vzal s sebou deset centnéřů stříbra a šest tisíců zlatých, nad to desatero roucho proměnné.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 6, 'I přinesl list králi Izraelskému v tato slova: Hned, jakž tě dojde list tento, aj, poslal jsem k tobě Námana služebníka svého, abys ho uzdravil od malomocenství jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 7, 'I stalo se, že když přečetl král Izraelský ten list, roztrhl roucho své a řekl: Zdali jsem já Bohem, abych mohl umrtviti a obživiti, že tento poslal ke mně, abych uzdravil muže od malomocenství jeho? Nýbrž posuďte, prosím, a pohleďte, že příčiny hledá proti mně.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 8, 'A když uslyšel Elizeus muž Boží, že roztrhl král Izraelský roucho své, poslal k králi, řka: Proč jsi roztrhl roucho své? Nechť nyní přijde ke mně a zvíť, že jest prorok v Izraeli.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 9, 'A tak přibral se Náman s jízdou svou a s vozy svými, a stál u dveří domu Elizeova.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 10, 'Poslal pak k němu Elizeus posla, řka: Jdi a umej se sedmkrát v Jordáně, a uzdraveno bude tělo tvé, a čist budeš.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 11, 'Tedy rozhněvav se Náman, bral se odtud a mluvil: Hle, řekl jsem u sebe, že jistotně vyjde, a stoje, vzývati bude jméno Hospodina Boha svého, a vznášeje ruku svou nad místem neduživým, tak uzdraví malomocenství mé.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 12, 'Zdali nejsou lepší Abana a Farfar, řeky Damašské, nad všecky vody Izraelské? Zdaliž bych se nemohl v nich zmýti, abych čist byl? A obrátiv se, jel s hněvem.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 13, 'Ale přistoupivše služebníci jeho, mluvili k němu a řekli: Otče můj, jakkoli velikou věc prorok ten rozkázal by tobě, což bys neměl učiniti toho? Čím tedy více, kdyžť řekl: Umej se, a budeš čist.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 14, 'A protož sstoupiv, pohřížil se v Jordáně sedmkrát vedlé řeči muže Božího. I učiněno jest tělo jeho jako tělo dítěte malého, a očištěn jest.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 15, 'A hned navrátil se k muži Božímu se vším komonstvem svým, a přišed, stál před ním a řekl: Aj, již jsem poznal, žeť není Boha na vší zemi, jediné v Izraeli. Protož nyní vezmi, prosím, dary tyto od služebníka svého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 16, 'On pak řekl: Živť jest Hospodin, před jehož oblíčejem stojím, žeť nic nevezmu. A ač ho nutil, aby vzal, však nikoli nechtěl.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 17, 'I řekl Náman: Tedy nic? Ale nechť jest dáno, prosím, mně služebníku tvému břímě země na dva mezky; neboť nebude více obětovati služebník tvůj zápalů aneb obětí bohům cizím, ale Hospodinu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 18, 'V této však věci odpusť Hospodin služebníku tvému: Když vchází pán můj do chrámu Remmon, aby se tam modlil, a on podpírá se na mou ruku, že i já skláním se v chrámě Remmon. Toho sklánění mého v chrámě Remmon nechť neváží, prosím, Hospodin služebníku tvému při té věci.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 19, 'I řekl jemu: Jdi v pokoji. A když odjel od něho nedaleko,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 20, 'V tom řekl Gézi služebník Elizea muže Božího: Hle, nedopustil pán můj Námanovi Syrskému tomuto, aby dáti měl z ruky své to, což přivezl. Živť jest Hospodin, žeť poběhnu za ním, a vezmu něco od něho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 21, 'Protož běžel Gézi za Námanem. A vida Náman běžícího za sebou, rychle skočil s vozu vstříc jemu a řekl: Dobře-li se děje?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 22, 'A on odpověděl: Dobře. Pán můj poslal mne, aťbych řekl: Aj, teď nyní přišli ke mně dva mládenci s hory Efraim z synů prorockých; dej jim medle centnéř stříbra a dvoje roucho proměnné.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 23, 'I řekl Náman: Raději vezmi dva centnéře. I přinutil ho. A svázav dva centnéře stříbra do dvou pytlů, a dvoje roucho proměnné, vložil to na dva pacholky své, kteříž nesli před ním.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 24, 'A když přišel na vrch, vzal to z rukou jejich, a složil v jednom domě, propustiv muže ty, kteřížto odešli.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 25, 'Sám pak všed, stál před pánem svým. I řekl mu Elizeus: Odkudžto, Gézi? Odpověděl: Nechodil služebník tvůj nikam.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 26, 'Kterýž řekl jemu: Zdaliž srdce mé nebylo při tom, když obrátil se muž s vozu svého vstříc tobě? Zdaliž čas byl bráti stříbro aneb roucho, aneb olivoví a vinice, aneb stáda a voly, neb služebníky aneb děvky?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 27, 'Protož malomocenství Námanovo přichytí se tebe i semene tvého na věky. I vyšel od tváři jeho malomocný jako sníh.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 1, 'Řekli pak synové proročtí Elizeovi: Ej, teď místo toto, v němž bydlíme s tebou, jest nám těsné.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 2, 'Medle, nechť jdeme až k Jordánu, abychom vzali odtud jeden každý jedno dřevo, a uděláme sobě tu místo, v němž bychom bydlili. Jimž řekl: Jděte.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 3, 'I řekl jeden: Prosím, poď také s služebníky svými. Kterýž odpověděl: A já půjdu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 4, 'Takž šel s nimi. A když přišli k Jordánu, sekali dříví.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 5, 'I stalo se, když jeden z nich podtínal dřevo, že sekera spadla mu do vody. Tedy zkřikl a řekl: Ach, pane můj, a ta ještě byla vypůjčená.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 6, 'Jemuž řekl muž Boží: Kamž jest upadla? I ukázal mu to místo. Kterýž uťav dřevo, uvrhl je tam, a učinil, aby zplynula sekera.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 7, 'A řekl: Vezmi ji sobě. Kterýž vztáh ruku svou, vzal ji.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 8, 'Když pak král Syrský bojoval proti Izraelovi, a vešel v radu s služebníky svými, řka: Na tom a na tom místě položí se vojsko mé:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 9, 'Tedy poslal muž Boží k králi Izraelskému, řka: Viz, abys netáhl přes to místo, nebo tam Syrští jsou v zálohách.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 10, 'Protož posílal král Izraelský na to místo, o kterémž mu byl řekl muž Boží, a vystříhal ho, aby se ho šetřil a to nejednou ani dvakrát.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 11, 'A tak zkormoutil se v srdci svém král Syrský pro tu věc, a svolav služebníky své, řekl jim: Proč mi neoznámíte, kdo z našich králi Izraelskému donáší?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 12, 'Jemuž řekl jeden z služebníků jeho: Nikoli, pane můj králi, ale Elizeus prorok, kterýž jest v Izraeli, oznamuje králi Izraelskému slova, kteráž ty mluvíš v nejtajnějším pokoji svém.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 13, 'Kterýž řekl: Jděte a vizte, kde jest, abych poslal a jal jej. I oznámeno jemu těmito slovy: Hle, jest v Dotain.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 14, 'Protož poslal tam koně a vozy a vojsko veliké. Kteříž přitáhše v noci, oblehli město.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 15, 'Vstav pak ráno služebník muže Božího, vyšel, a aj, vojsko obklíčilo město, koni i vozové. I řekl služebník ten jeho k němu: Ach, pane můj, což budeme dělati?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 16, 'Kterýž odpověděl: Neboj se, nebo mnohem více jich s námi jest, než s nimi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 17, 'I modlil se Elizeus a řekl: Ó Hospodine, otevři, prosím, oči jeho, aby viděl. A tak otevřel Hospodin oči služebníka toho, a viděl, a aj, hora ta plná koňů, a vozové ohniví okolo Elizea.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 18, 'A když nepřátelé táhli k němu, modlil se Elizeus Hospodinu a řekl: Poraz, prosím, národ tento slepotou. I porazil je slepotou vedlé řeči Elizeovy.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 19, 'V tom řekl jim Elizeus: Neníť to ta cesta, ani to město. Poďte za mnou, a dovedu vás k muži, kteréhož hledáte. Takž je vedl do Samaří.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 20, 'I stalo se, když vešli do Samaří, že řekl Elizeus: Ó Hospodine, otevři oči těchto, ať vidí. Tedy otevřel Hospodin oči jejich, a viděli, že jsou u prostřed Samaří.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 21, 'Řekl pak král Izraelský Elizeovi, když je uzřel: Mám-liž je zmordovati, otče můj?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 22, 'Odpověděl on: Nemorduj. Zdaliž jsi je zjímal mečem svým a lučištěm svým, abys je zmordoval? Dej jim chleba a vody, ať jedí a pijí, a navrátí se ku pánu svému.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 23, 'A tak připravil jim hojnost velikou, a když pojedli a napili se, propustil je. Oni pak navrátili se ku pánu svému, aniž kdy více potom lotříkové Syrští vskakovali do země Izraelské.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 24, 'Stalo se potom, že shromáždil Benadad král Syrský všecka vojska svá, a přitáh, oblehl Samaří.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 25, 'Pročež byl hlad veliký v Samaří; nebo aj, tak dlouho obleženo bylo, až hlava oslová byla za osmdesáte stříbrných, a čtvrtý díl míry káb trusů holubích za pět stříbrných.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 26, 'I přihodilo se, když král Izraelský šel po zdi, žena jedna zvolala k němu, řkuci: Spomoz mi, pane můj králi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 27, 'Kterýž řekl: Jestliť nespomůže Hospodin, odkud já mám pomoci tobě? Zdali z humna aneb z presu?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 28, 'Řekl jí ještě král: Cožtě pak? Kteráž odpověděla: Žena tato řekla mi: Dej syna svého, abychom ho dnes snědly, zítra také sníme syna mého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 29, 'I uvařily jsme syna mého, a snědly jsme jej. Potom druhého dne řekla jsem jí: Dej syna svého, abychom ho snědly. Ale ona skryla syna svého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 30, 'A když uslyšel král slova ženy té, roztrhl roucha svá. (Když pak on šel po zdi, viděl lid, an pytel byl na těle jeho zespod.)');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 31, 'Protož řekl král: Toto mi učiň Bůh a toto přidej, jestliže zůstane hlava Elizea syna Safatova na něm dnes.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 32, '(Elizeus pak seděl v domě svém, a starší s ním seděli.) I poslal jednoho z přístojících svých, a prvé než přišel posel ten k němu, již byl řekl starším: Nevíte-liž, že poslal ten syn vražedlníkův, aby sťal hlavu mou? Šetřtež, když by vcházel ten posel, zavřete dvéře a odstrčte jej ode dveří. Zdaliž i dusání noh pána jeho není za ním?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 33, 'A když on ještě mluvil s nimi, hle, posel přicházel k němu, a řekl: Aj, toto zlé jest od Hospodina, což mám déle čekati na něj?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 1, 'Řekl pak Elizeus: Slyšte slovo Hospodinovo. Toto praví Hospodin: O tomto času zítra míra mouky bělné bude za lot stříbra, a dvě míry ječmene za lot stříbra v bráně Samařské.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 2, 'I odpověděl muži Božímu jeden z knížat, na jehož ruku král zpoléhal, a řekl: Kdyby otevřel Hospodin průduchy nebeské, zdali by to býti mohlo? Kterýž řekl: Aj, uzříš očima svýma, ale nebudeš jísti z toho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 3, 'Byli pak u vrat brány čtyři muži malomocní, kteříž řekli jeden druhému: Co tu sedíme, až bychom zemříti musili?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 4, 'Díme-li: Poďme do města, hlad jest v městě, i zemřeme tam; pakli zde zůstaneme, také zemřeme. Protož nyní poďte, a utecme do vojska Syrských. Budou-li nás živiti, zůstaneme živi; pakli nás zbijí, též zemřeme.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 5, 'Vstavše tedy v soumrak, aby šli k vojsku Syrských, přišli až k kraji ležení Syrského, a hle, nebylo tu žádného.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 6, 'Nebo Pán učinil to, aby slyšelo vojsko Syrské hřmot vozů a zvuk koňů, a tak hluk vojska velikého. I řekli jeden druhému: Hle, ze mzdy najal proti nám král Izraelský krále Hetejské a krále Egyptské, aby připadli na nás.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 7, 'A vstavše, utekli v soumrak a nechali tu stanů svých, a koňů svých i oslů svých, a ležení, tak jakž bylo, a utekli pro zachování života svého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 8, 'Když tedy přišli malomocní ti na kraj ležení, všedše do jednoho stanu, jedli a pili, a pobravše v něm stříbro a zlato i roucha, odešli a schovali. Opět navrátivše se, vešli do jiného stanu a pobrali v něm, a odšedše, schovali.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 9, 'I řekli vespolek: Nedobře děláme. Den tento jest den dobrých novin, a my mlčíme. Budeme-li čekati až do svitání, postihne nás nepravost; protož nyní poďte, vejdouce, oznamme to domu královskému.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 10, 'A přišedše, volali na branné města, a pověděli jim, řkouce: Přišli jsme do ležení Syrského, a aj, nebylo tam žádného, ani hlasu lidského, kromě koní přivázaných a oslů přivázaných, a stanů, jakž prvé byli.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 11, 'I volal ten na jiné branné, a ti ohlásili to po všem domě královském.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 12, 'Vstav tedy král v noci, řekl služebníkům svým: Povím vám nyní, co jsou nám udělali Syrští. Vědí, že jsme hladovití, protož vyšli z ležení, aby se skryli v poli, řkouce: Když vyjdou z města, zjímáme je živé a vejdeme do města.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 13, 'K tomu odpovídaje jeden z služebníků jeho, řekl: Nechť, prosím, vezmou pět koní z těch, kteříž pozůstali v městě. (Hle, oniť jsou jako i všecko množství Izraelské, jenž zůstali v něm, hle, jsou jako všecko množství Izraelské, kteréž již hyne.) Ty pošleme a přezvíme.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 14, 'A tak vzali dva koně vozní, kteréž poslal král za vojskem Syrským, řka: Jděte a vizte.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 15, 'I jeli za nimi až k Jordánu, a aj, po vší té cestě plno bylo šatů a nádob, kteréž metali od sebe Syrští, splašeni jsouce. Tedy navrátivše se poslové, oznámili to králi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 16, 'Protož vyšed lid, vzebral ležení Syrské. A byla míra mouky bělné za lot, a dvě míry ječmene za lot vedlé řeči Hospodinovy.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 17, 'Král pak byl ustanovil to kníže, na jehož ruku zpoléhal, u brány. Kteréhož pošlapal lid v bráně, tak že umřel, vedlé řeči muže Božího, kterouž mluvil, když král k němu byl sešel.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 18, 'A stalo se tak, jakž mluvil muž Boží králi, řka: Dvě míry ječmene budou za lot stříbra, a míra mouky bělné za lot stříbra zítra o tomto času v bráně Samařské.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 19, 'K čemuž bylo odpovědělo kníže muži Božímu, a řeklo: Kdyby otevřel Hospodin průduchy nebeské, zdali by to podlé řeči této býti mohlo? Jemuž on řekl: Aj, ty uzříš očima svýma, ale z toho jísti nebudeš.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 20, 'A tak se stalo jemu; nebo pošlapal ho lid v bráně, tak že umřel.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 1, 'Mluvil pak Elizeus k ženě té, jejíhož byl syna vzkřísil, řka: Vstaň a jdi, ty i čeled tvá, a buď pohostinu, kdežkoli budeš moci byt míti; nebo zavolal Hospodin hladu, a přijdeť na zemi za sedm let.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 2, 'Vstavši tedy žena, učinila vedlé řeči muže Božího, a odešla s čeledí svou, a bydlila pohostinu v zemi Filistinských sedm let.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 3, 'I stalo se, že když pominulo těch sedm let, navrátila se ta žena z země Filistinské, a šla, aby prosila krále za dům svůj a za pole své.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 4, 'Mezi tím král mluvil s Gézi, služebníkem muže Božího, řka: Vypravuj mi medle o všech věcech velikých, kteréž činil Elizeus.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 5, 'A když on vypravoval králi, kterak obživil mrtvého, aj žena, jejíhož syna vzkřísil, prosila krále za dům svůj a za pole své. I řekl Gézi: Pane můj králi, to jest ta žena, a tento syn její, kteréhož vzkřísil Elizeus.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 6, 'Tedy tázal se král ženy, kteráž vypravovala jemu. I poručil král komorníku jednomu, řka: Ať jsou navráceny všecky věci, kteréž byly její, i všecky užitky pole, ode dne, v němž opustila zemi, až po dnes.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 7, 'Potom přišel Elizeus do Damašku, král pak Syrský Benadad stonal. I oznámeno jemu těmito slovy: Přišel muž Boží sem.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 8, 'I řekl král Hazaelovi: Vezmi v ruce své dar, a jdi vstříc muži Božímu, a zeptej se Hospodina skrze něho, řka: Povstanu-li z nemoci této?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 9, 'A tak šel Hazael vstříc jemu, vzav s sebou dar, a všeliké věci výborné Damašské, břemena na čtyřidcíti velbloudích, a přišed, stál před ním a řekl: Syn tvůj Benadad, král Syrský, poslal mne k tobě, řka: Povstanu-li z nemoci této?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 10, 'Odpověděl mu Elizeus: Jdi, pověz jemu: Zajisté mohl bys živ zůstati. Ale Hospodin mi ukázal, že jistotně umře.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 11, 'V tom proměniv muž Boží tvář svou, ukázal se k němu neochotně a plakal.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 12, 'Jemuž řekl Hazael: Proč pán můj pláče? Odpověděl: Proto že vím, co zlého ty učiníš synům Izraelským. Pevnosti jejich spálíš a mládence jejich zmorduješ mečem, a nemluvňátka jejich rozrážeti budeš, a těhotné jejich zroztínáš.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 13, 'I řekl Hazael: I což jest služebník tvůj pes, aby učiniti mohl věc tak velikou? Odpověděl Elizeus: Ukázal tě mi Hospodin, že budeš králem Syrským.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 14, 'A odšed od Elizea, přišel ku pánu svému. Kterýž řekl jemu: Cožť řekl Elizeus? Odpověděl: Pravil mi, že bys mohl živ zůstati.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 15, 'I stalo se nazejtří, že vzal koberec, a namočiv jej v vodě, prostřel jej na tvář jeho. I umřel, a kraloval Hazael místo něho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 16, 'Léta pak pátého Jorama, syna Achabova krále Izraelského, a Jozafata krále Judského, počal kralovati Jehoram, syn Jozafatův král Judský.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 17, 'Ve dvou a třidcíti letech byl, když počal kralovati, a kraloval osm let v Jeruzalémě.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 18, 'A chodil po cestě králů Izraelských, tak jako činil dům Achabův; nebo měl dceru Achabovu za manželku. Takž činil zlé věci před očima Hospodinovýma.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 19, 'Hospodin však nechtěl zahladiti Judy pro Davida služebníka svého, jakž mu byl zaslíbil, že dá jemu svíci i synům jeho po všecky dny.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 20, 'Ve dnech jeho odstoupil Edom od království Judského, a ustanovili nad sebou krále.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 21, 'Tou příčinou táhl Jehoram do Seir, i všickni vozové s ním. A vstav v noci, porazil Idumejské, kteříž jej byli obklíčili, i hejtmany vozů, a lid utekl do stanů svých.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 22, 'Však předce odstoupil Edom od království Judského až do tohoto dne. Takž odstoupilo i Lebno téhož času.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 23, 'O jiných pak věcech Jehoramových, a o všem, cožkoli činil, psáno jest v knize o králích Judských.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 24, 'I usnul Jehoram s otci svými, a pochován jest s otci svými v městě Davidově, kraloval pak Ochoziáš syn jeho místo něho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 25, 'Léta dvanáctého Jorama syna Achabova, krále Izraelského, počal kralovati Ochoziáš syn Jehorama, krále Judského.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 26, 'Ve dvamecítma letech byl Ochoziáš, když počal kralovati, a kraloval jeden rok v Jeruzalémě. Jméno matky jeho bylo Atalia, dcera Amri krále Izraelského.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 27, 'A chodil cestou domu Achabova, čině, což jest zlého před očima Hospodinovýma, jako i dům Achabův, nebo byl zetěm domu Achabova.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 28, 'Pročež vycházel s Joramem synem Achabovým, na vojnu proti Hazaelovi králi Syrskému, do Rámot Galád; ale porazili Syrští Jorama.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 29, 'A tak navrátil se král Joram, aby se hojil v Jezreel na rány, kterýmiž ho ranili Syrští v Ráma, když bojoval s Hazaelem králem Syrským. Ochoziáš pak syn Jehorama, krále Judského, přijel, aby navštívil Jorama syna Achabova v Jezreel; nebo tam nemocen byl.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 1, 'Prorok pak Elizeus povolal jednoho z synů prorockých, a řekl jemu: Přepaš bedra svá, a vezmi tuto nádobku oleje do ruky své, a jdi do Rámot Galád.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 2, 'A když tam přijdeš, uzříš tam Jéhu, syna Jozafata syna Namsi. K němuž když přijdeš, vyvoláš ho z prostředku bratří jeho, a uvedeš ho do nejtajnějšího pokojíku.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 3, 'A vezma nádobku oleje, vyleješ na hlavu jeho a díš: Toto praví Hospodin: Pomazuji tebe za krále nad Izraelem. A hned otevra dvéře, utec a nemeškej se.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 4, 'I odšel mládenec ten služebník prorokův do Rámot Galád.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 5, 'A když přišel, aj, knížata vojska seděli. I řekl: Mámť něco povědíti, ó kníže. I řekl Jéhu: Komu ze všech nás? Odpověděl: Tobě, ó kníže.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 6, 'Vyvstav tedy, všel do vnitřku. I vylil olej na hlavu jeho a řekl jemu: Toto praví Hospodin, Bůh Izraelský: Pomazuji tebe za krále nad lidem Hospodinovým, nad Izraelem.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 7, 'A zmorduješ dům Achaba pána svého; neboť pomstím krve služebníků svých proroků, a krve všech služebníků Hospodinových z ruky Jezábel.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 8, 'A tak zahyne všecken dům Achabův, a vypléním z domu Achabova močícího na stěnu, a zajatého i zanechaného v Izraeli.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 9, 'Učiním zajisté domu Achabovu, jako domu Jeroboámovu syna Nebatova, a jako domu Bázy syna Achiášova.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 10, 'Jezábel pak sežerou psi na poli Jezreel, a nebude, kdo by ji pochoval. A rychle otevřev dvéře, utekl.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 11, 'A když Jéhu vyšel k služebníkům pána svého, řekl mu jeden: Dobře-li se děje? Proč přišel ten blázen k tobě? Odpověděl jim: Vy znáte člověka i řeč jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 12, 'I řekli: Klamť jest, pověz nám medle. Kterýž řekl: Takto a takto mluvil mi, řka: Toto praví Hospodin: Pomazuji tě za krále nad Izraelem.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 13, 'Tedy rychle vzali jeden každý roucho své, a prostřeli pod něj na nejvyšším stupni, a troubíce v troubu, pravili: Kralujeť Jéhu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 14, 'Zatím spuntoval se Jéhu syn Jozafata, syna Namsi, proti Joramovi, (když Joram ostříhaje Rámot Galád spolu se vším Izraelem, před Hazaelem králem Syrským,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 15, 'Navrátil se byl Joram král, aby se hojil v Jezreel na rány, kterýmiž ho ranili Syrští, když bojoval proti Hazaelovi králi Syrskému). A řekl Jéhu: Vidí-li se vám, nechť nevychází žádný z města, kterýž by šel a oznámil to v Jezreel.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 16, 'I vsedl na vůz Jéhu a jel do Jezreel, nebo Joram ležel tam. Ochoziáš také král Judský přijel byl, aby navštívil Jorama.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 17, 'V tom strážný, kterýž stál na věži v Jezreel, když viděl houf Jéhu přicházející, řekl: Vidím jakýsi houf. I řekl Joram: Povolej jízdného, a pošli vstříc jim, aby se otázal: Jest-li pokoj?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 18, 'I vyjel jízdný proti nim a řekl: Takto praví král: Jest-li pokoj? Odpověděl Jéhu: Co tobě do pokoje? Jeď za mnou. Protož oznámil to strážný, řka: Přijel posel až k nim, ale nevracuje se.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 19, 'Ještě poslal druhého jízdného. Kterýž přijel k nim a řekl: Takto praví král: Jest-li pokoj? Odpověděl Jéhu: Co tobě do pokoje? Jeď za mnou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 20, 'Opět oznámil to strážný, řka: Přijel až k nim, ale nevrací se. Příjezd pak jest jako příjezd Jéhu syna Namsi; nebo vztekle jede.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 21, 'Tedy řekl Joram: Zapřáhni. I zapřáhl k vozu jeho. Takž vyjel Joram král Izraelský a Ochoziáš král Judský, každý na voze svém, a vyjevše proti Jéhu, potkali se s ním na poli Nábota Jezreelského.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 22, 'I stalo se, když uzřel Joram Jéhu, že řekl: Jest-liž pokoj, Jéhu? Odpověděl: Jaký pokoj, poněvadž ještě smilství Jezábel matky tvé a kouzelnictví její velmi mnohá trvají?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 23, 'Pročež obrátiv se Joram, utíkal a řekl Ochoziášovi: Zrada, Ochoziáši!');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 24, 'Ale Jéhu pochytiv lučiště, postřelil Jorama mezi ramenem jeho, tak že střela pronikla srdce jeho. I padl na voze svém.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 25, 'Zatím řekl Jéhu Badakerovi, hejtmanu svému: Vezma, povrz jej na pole Nábota Jezreelského; nebo pamatuješ, když jsme já a ty jeli spolu za Achabem otcem jeho, že Hospodin vynesl proti němu pohrůžku tuto, řka:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 26, 'Zajisté krve Nábotovy a krve synů jeho, kterouž jsem viděl včera, řekl Hospodin, pomstím na tobě na poli tomto. Hospodin to řekl, nyní tedy vezma, povrz jej na pole, vedlé řeči Hospodinovy.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 27, 'Ochoziáš pak král Judský uzřev to, utíkal cestou k domu zahradnímu. Ale honil ho Jéhu a řekl: I toho zabíte na voze jeho. Takž ho ranili, když vyjížděl k Guru, kteréž jest podlé Jibleam. I utekl do Mageddo a tam umřel.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 28, 'Kteréhož vloživše na vůz služebníci jeho, vezli jej do Jeruzaléma, a pochovali jej v hrobě jeho s otci jeho v městě Davidově.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 29, 'Léta jedenáctého Jorama syna Achabova počal kralovati Ochoziáš nad Judou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 30, 'Potom Jéhu přijel do Jezreel. O čemž když uslyšela Jezábel, ulíčila tvář svou, a ozdobila hlavu svou, a vyhlédala z okna.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 31, 'A když Jéhu jel skrze bránu, řekla: Jest-li pokoj, ó Zamri, mordéři pána svého?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 32, 'On pak pozdvih tváři své k oknu, řekl: Kdo drží se mnou, kdo? I vyhlédli na něj dva či tři komorníci její.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 33, 'Jimž řekl: Svrzte ji. Kteřížto svrhli ji. I pokropena jest krví její stěna i koni; a tak pošlapal ji.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 34, 'A když přijel, jedl a pil, a řekl: Pohleďte již na tu zlořečenou a pochovejte ji, nebť jest dcera královská.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 35, 'Protož odšedše, aby ji pochovali, nenalezli z ní než leb a nohy a dlaně rukou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 36, 'A navrátivše se, pověděli jemu. Kterýž řekl: Slovo Hospodinovo jest, kteréž mluvil skrze služebníka svého, Eliáše Tesbitského, řka: Na poli Jezreel žráti budou psi tělo Jezábel.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 37, 'Budiž tedy tělo Jezábel na poli Jezreel, jako hnůj na svrchku pole, tak aby žádný neřekl: Tato jest Jezábel.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 1, 'Měl pak Achab sedmdesáte synů v Samaří. I napsal Jéhu list, a poslal jej do Samaří k knížatům Jezreelským, starším, a kteříž chovali syny Achabovy, s tímto poručením:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 2, 'Hned jakž vás dojde list tento, poněvadž u vás jsou synové pána vašeho, jsou i vozové u vás, i koni, i město hrazené a zbroj,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 3, 'Vybeřte nejlepšího a nejzpůsobnějšího z synů pána svého, a posaďte na stolici otce jeho, a bojujte za dům pána svého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 4, 'Kteříž bojíce se náramně, pravili: Aj, dva králové neostáli před ním, a kterak my ostojíme?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 5, 'A tak poslal ten, kterýž byl ustanoven nad domem, a kterýž ustanoven byl nad městem, i starší, a kteříž chovali syny Achabovy, k Jéhu, řkouce: Služebníci tvoji jsme, a všecko, což nám rozkážeš, učiníme. Neustanovíme žádného krále; což se tobě dobře líbí, učiň.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 6, 'I napsal k nim list po druhé, řka: Jste-li moji a hlasu mého posloucháte-li, vezmouce hlavy všech synů pána svého, přiďte ke mně zítra o tomto času do Jezreel. (Synů pak králových bylo sedmdesáte mužů u nejpřednějších v městě, kteříž chovali je.)');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 7, 'Tedy stalo se, jakž jich došel list ten, že zjímali syny královské, a zbili sedmdesáte mužů, a vkladše hlavy jejich do košů, poslali je k němu do Jezreel.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 8, 'A přišed posel, oznámil jemu, řka: Přinesli hlavy synů královských. A on řekl: Sklaďte je na dvě hromady u vrat brány až do jitra.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 9, 'Potom ráno vyšed, postavil se a řekl všemu lidu: Spravedliví jste vy. Aj, já spuntoval jsem se proti pánu svému a zabil jsem jej; kdo by pobil tyto všecky?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 10, 'Věztež nyní, žeť nepochybilo nižádné slovo Hospodinovo, kteréž mluvil Hospodin proti domu Achabovu, ale vykonal Hospodin to, což byl mluvil skrze služebníka svého Eliáše.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 11, 'A tak pobil Jéhu všecky, kteříž pozůstali z domu Achabova v Jezreel, i všecky nejpřednější jeho, i známé jeho, i kněží jeho, tak že nezůstalo z nich žádného živého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 12, 'Potom vstav, odebral se a jel do Samaří, a již byl v Betekedu pastýřů na cestě.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 13, 'I nalezl tam Jéhu bratří Ochoziáše, krále Judského, a řekl: Kdo jste vy? Odpověděli: Jsme bratří Ochoziášovi a jdeme, abychom pozdravili synů králových a synů královny.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 14, 'Tedy řekl: Zjímejte je živé. I zjímali je živé, a pobili je u čisterny v Betekedu, čtyřidceti a dva muže, a nezůstal z nich žádný.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 15, 'Potom bera se odtud, nalezl Jonadaba syna Rechabova, kterýž se s ním potkal, a pozdravil ho. I řekl jemu: Jest-liž srdce tvé přímé, jako jest srdce mé s srdcem tvým? Odpověděl Jonadab: Jest, arci jest. Řekl Jéhu: Podejž mi ruky své. I podal mu ruky své. A on kázal mu vsednouti k sobě na vůz,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 16, 'A řekl: Pojeď se mnou, a viz horlivost mou pro Hospodina. A tak vezli jej na voze jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 17, 'Když pak přijel do Samaří, pobil všecky, kteříž byli pozůstali z domu Achabova v Samaří, a vyhladil jej vedlé řeči Hospodinovy, kterouž byl mluvil k Eliášovi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 18, 'Zatím shromáždiv Jéhu všecken lid, řekl jim: Achab málo sloužil Bálovi, Jéhu bude mu více sloužiti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 19, 'Protož nyní všecky proroky Bálovy, všecky služebníky jeho, a všecky kněží jeho svolejte ke mně, ať žádný tam nezůstává; nebo velikou obět budu obětovati Bálovi. Kdož by koli nebyl přítomen, nezůstane živ. Ale Jéhu činil to chytře, aby vyhladil ctitele Bálovy.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 20, 'Řekl také Jéhu: Zasvěťte svátek Bálovi. I prohlásili jej.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 21, 'Rozeslal zajisté Jéhu po vší zemi Izraelské. I sešli se všickni ctitelé Bálovi, tak že nezůstalo ani jednoho, ješto by nepřišel. A když vešli do domu Bálova, naplněn jest dům Bálův, od jednoho konce až do druhého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 22, 'Tedy řekl tomu, kterýž vládl rouchem: Vynes roucha všechněm ctitelům Bálovým. I přinesl jim roucha.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 23, 'Potom všel i Jéhu a Jonadab syn Rechabův do domu Bálova, a řekl ctitelům Bálovým: Vyhledejte a vizte, ať není zde s vámi někdo z ctitelů Hospodinových, kromě samých ctitelů Bálových.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 24, 'A tak vešli, aby obětovali oběti a zápaly. Jéhu pak postavil sobě vně osmdesáte mužů, jimž byl řekl: Jestliže kdo uteče z lidí těch, kteréž já uvozuji vám v ruce vaše, život váš za život jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 25, 'I stalo se, když kněz dokonal obětování zápalu, řekl Jéhu drabantům a hejtmanům: Vejdětež a zbíte je, ať žádný neuchází. Kteřížto pobili je ostrostí meče, a rozmetali těla jejich drabanti a hejtmané. Potom šli dále do každého města, kdež byl dům Bálův,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 26, 'A vymítajíce modly z domu Bálova, pálili je.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 27, 'Zkazili také modlu Bálovu, a zbořivše dům jeho, nadělali z něho záchodů až do dnešního dne.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 28, 'A tak vyplénil Jéhu Bále z lidu Izraelského.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 29, 'A však proto od hříchů Jeroboáma syna Nebatova, kterýž přivedl k hřešení Izraele, neodstoupil Jéhu, totiž od těch telat zlatých, kteráž byla v Bethel a v Dan.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 30, 'Tedy řekl Hospodin Jéhu: Poněvadž jsi snažně vykonal to, což dobrého jest před očima mýma, a všecky věci, kteréž jsem měl v srdci svém, učinil jsi domu Achabovu, synové tvoji až do čtvrtého pokolení seděti budou na stolici Izraelské.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 31, 'Ale Jéhu nebyl toho pilen, aby chodil v zákoně Hospodina, Boha Izraelského, celým srdcem svým, aniž odstoupil od hříchů Jeroboáma, kterýž byl uvedl v hříchy lid Izraelský.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 32, 'Za těch dnů počal Hospodin zmenšovati Izraele; nebo je porazil Hazael po všech končinách Izraelských,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 33, 'Od Jordánu, proti východu slunce, všecku zemi Galád, Gádovu a Rubenovu i Manassesovu, od Aroer, kteréž jest při potoku Arnon, tak Galád jako Bázan.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 34, 'O jiných věcech Jéhu, a cožkoli činil, i o vší síle jeho, sepsáno jest v knize o králích Izraelských.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 35, 'I usnul Jéhu s otci svými, a pochovali jej v Samaří, a kraloval Joachaz syn jeho místo něho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 36, 'Dnů pak, v nichž kraloval Jéhu nad lidem Izraelským v Samaří, bylo let osmmecítma.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 1, 'Atalia pak matka Ochoziášova viduci, že umřel syn její, vstavši, pomordovala všecko símě královské.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 2, 'Ale Jozaba dcera krále Jehorama, sestra Ochoziášova, vzala Joasa syna Ochoziášova, a ukradši ho z prostředku synů královských, kteříž mordováni byli, skryla jej i s chůvou jeho v pokoji, kdež lůže byla. A tak skryli ho před Atalií, a není zamordován.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 3, 'I byl s ní v domě Hospodinově tajně za šest let, v nichž Atalia kralovala nad zemí.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 4, 'Léta sedmého poslav Joiada, povolal setníků, hejtmanů a drabantů. I uvedl je k sobě do domu Hospodinova, a učinil s nimi smlouvu, a zavázav je přísahou v domě Hospodinově, ukázal jim syna králova.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 5, 'A přikázal jim, řka: Tato jest věc, kterouž učiníte: Třetí díl vás, kteříž přicházíte v sobotu, a držíte stráž, bude při domě králově,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 6, 'A díl třetí bude u brány Sur, a třetí díl bude u brány za drabanty, a budete stráž držeti, ostříhajíce domu tohoto před outokem.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 7, 'Vy pak všickni, kteříž byste odjíti měli v sobotu, po vykonání povinnosti při domě Hospodinově, ve dvě poboční stráže rozdělení, buďte při králi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 8, 'A tak obstoupíte krále vůkol, jeden každý majíce braň svou v rukou svých. Kdož by pak šel do šiku vašeho, ať umře; a budete při králi, když bude vycházeti i když bude vcházeti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 9, 'Protož učinili setníci ti všecky věci tak, jakž byl rozkázal Joiada kněz, a vzavše jeden každý muže své, kteříž přicházeli v sobotu a kteříž odcházeli v sobotu, přišli k Joiadovi knězi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 10, 'I dal kněz setníkům kopí a pavézy, kteréž byly Davida krále, a kteréž byly v domě Hospodinově.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 11, 'Stáli pak ti drabanti, jeden každý držíce braň svou v ruce své, od pravé strany domu až do levé strany domu, proti oltáři a proti domu při králi vůkol.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 12, 'Tedy vyvedl syna králova, a vstavil na něj korunu a ozdobu. I ustanovili jej králem a pomazali ho, a plésajíce rukama, říkali: Živ buď král!');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 13, 'V tom uslyševši Atalia hluk plésajícího lidu, vešla k lidu do domu Hospodinova.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 14, 'A když pohleděla, a aj, král stál na místě vyšším, vedlé obyčeje s knížaty, a trouby byly před králem, a všecken lid země byl vesel, i troubili v trouby. Tedy roztrhla Atalia roucho své a zkřikla: Spiknutí, spiknutí!');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 15, 'Protož rozkázal Joiada kněz těm setníkům ustaveným nad vojskem, řka jim: Pusťte ji prostředkem řadu, a i toho, kdož by za ní šel, zabíte mečem. Nebo byl řekl kněz: Ať není zabita v domě Hospodinově.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 16, 'I pustili ji. Ale když přišla na cestu, kudy koni vcházejí do domu královského, tu jest zabita.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 17, 'Tedy učinil Joiada smlouvu mezi Hospodinem a mezi králem, i mezi lidem, aby byli lid Hospodinův; též mezi králem a mezi lidem.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 18, 'Potom šel všecken lid země do domu Bálova, a zbořili jej, i oltáře jeho a obrazy jeho v kusy stroskotali; Matana také kněze Bálova zabili před oltáři. Kněz pak znovu nařídil přisluhující v domě Hospodinově.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 19, 'A pojav ty setníky a hejtmany, i drabanty se vším lidem země, provázeli krále z domu Hospodinova, a přišli cestou k bráně drabantů do domu královského. Kdežto posadil se na stolici královské.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 20, 'I veselil se všecken lid země, a město se upokojilo. Atalii pak zabili mečem u domu královského.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 21, 'A byl Joas v sedmi letech, když počal kralovati.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 1, 'Léta sedmého Jéhu počal kralovati Joas, a kraloval čtyřidceti let v Jeruzalémě. Jméno matky jeho bylo Sebia z Bersabé.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 2, 'I činil Joas, což dobrého jest před očima Hospodinovýma po všecky dny své, pokudž ho vyučoval Joiada kněz.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 3, 'A však výsosti nebyly zkaženy, ještě lid obětoval a kadil na těch výsostech.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 4, 'Řekl pak Joas kněžím: Všecky peníze svaté, kteréž se vnášejí do domu Hospodinova, totiž peníze těch, kteříž jdou v počet, a peníze ceny za osobu jednoho každého, a všecky peníze, kteréž by kdo dobrovolně uložil dáti do domu Hospodinova,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 5, 'Vezmou kněží k sobě, jeden každý od známého svého, a oni opraví zbořeniny domu všudy, kdež by bylo zboření.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 6, 'Stalo se potom léta dvadcátého třetího krále Joasa, když ještě neopravili kněží zbořenin chrámových,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 7, 'Že povolal král Joas Joiady kněze i jiných kněží, a řekl jim: Proč neopravujete zbořenin chrámových? Protož nyní nepřijímejte peněz od známých svých, ale na zbořeniny domu dávejte je.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 8, 'Jemuž povolivše kněží, nebrali peněz od lidu, ani neopravovali domu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 9, 'Protož Joiada kněz vzav jednu truhlici, udělal díru v víku jejím, a postavil ji vedlé oltáře po pravé straně, kudy se vchází do domu Hospodinova. I postavili tu kněží ostříhající prahu i všech peněz, kteréž vnášíny byly do domu Hospodinova.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 10, 'A když rozuměli, že by mnoho peněz bylo v truhlici, tedy přicházel kancléř královský a kněz nejvyšší, a sčetše, schovávali ty peníze, kteréž se nalézaly v domě Hospodinově.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 11, 'Odkudž vydávali peníze hotové v ruce řemeslníků postavených nad dílem domu Hospodinova, a ti obraceli je na tesaře a dělníky, kteříž opravovali dům Hospodinův,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 12, 'Totiž na zedníky a kameníky, a k jednání dříví i tesaného kamení, aby opraveny byly zbořeniny domu Hospodinova, i na všecko to, což obráceno mělo býti na dům k opravě jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 13, 'A však nebylo děláno do domu Hospodinova číší stříbrných, žaltářů, kotlíků, trub a žádné nádoby zlaté, ani nádoby stříbrné z peněz, kteréž přinášíny byly do domu Hospodinova,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 14, 'Ale těm, kteříž představeni byli nad dílem, dávali je, a opravovali na ně dům Hospodinův.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 15, 'Aniž žádali počtu od mužů těch, jimž v ruce peníze dávali, aby platili dělníkům; nebo věrně dělali.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 16, 'Peněz za vinu, a peněz za hříchy nebylo vnášíno do domu Hospodinova; kněžím se dostávaly.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 17, 'Tedy vytáhl Hazael král Syrský, a bojoval proti Gát a dobyl ho. Potom obrátil Hazael tvář svou, aby táhl proti Jeruzalému.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 18, 'Protož pobral Joas král Judský všecky věci svaté, kterýchž byli nadali Jozafat a Jehoram a Ochoziáš, otcové jeho, králové Judští, i to, čehož sám posvětil, i všecko zlato, kteréž se nalezlo v pokladích domu Hospodinova a domu královského, a poslal k Hazaelovi králi Syrskému. I odtáhl od Jeruzaléma.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 19, 'O jiných pak činech Joasových, a cožkoli činil, psáno jest v knize o králích Judských.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 20, 'Potom povstavše služebníci jeho, spikli se spolu, a zabili Joasa v Betmillo, kudy se chodí do Silla,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 21, 'Totiž Jozachar syn Simatův, a Jozabad syn Somerův. Ti služebníci jeho zabili ho, a umřel. I pochovali jej s otci jeho v městě Davidově, a kraloval Amaziáš syn jeho místo něho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 1, 'Léta třimecítmého Joasa syna Ochoziáše, krále Judského, kraloval Joachaz syn Jéhu nad Izraelem v Samaří sedmnácte let.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 2, 'A činil to, což jest zlého před očima Hospodinovýma; nebo následoval hříchů Jeroboáma syna Nebatova, kterýž přivedl k hřešení Izraele, a neuchýlil se od nich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 3, 'I rozhněvala se prchlivost Hospodinova na Izraele, a vydal je v ruku Hazaele krále Syrského, a v ruku Benadada syna Hazaelova po všecky ty dny.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 4, 'Ale když se modlil Joachaz Hospodinu, vyslyšel jej Hospodin. Viděl zajisté trápení Izraelské, že je ssužoval král Syrský.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 5, 'Protož dal Hospodin Izraelovi vysvoboditele, a vyšli z ruky Syrských, i bydlili synové Izraelští v příbytcích svých jako kdy prvé.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 6, 'Však proto neodstoupili od hříchů domu Jeroboámova, kterýž přivedl k hřešení Izraele, nýbrž v nich chodili, ano i háj ještě zůstával v Samaří,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 7, 'Ačkoli nezanechal Joachazovi lidu, kromě padesáti jízdných a desíti vozů a desíti tisíců pěších; nebo je pohubil král Syrský, a setřel je jako prach při mlácení.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 8, 'O jiných pak činech Joachazových, a cožkoli činil, i o síle jeho zapsáno jest v knize o králích Izraelských.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 9, 'I usnul Joachaz s otci svými, a pochovali ho v Samaří. Kraloval pak Joas syn jeho místo něho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 10, 'Léta třidcátého sedmého Joasa krále Judského kraloval Joas syn Joachazův nad Izraelem v Samaří šestnácte let.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 11, 'A činil to, což jest zlého před očima Hospodinovýma, neuchýliv se od žádných hříchů Jeroboáma syna Nebatova, kterýž přivedl k hřešení Izraele, ale chodil v nich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 12, 'O jiných pak činech Joasových, i cožkoli činil, i o síle jeho, kterouž bojoval proti Amaziášovi králi Judskému, zapsáno jest v knize o králích Izraelských.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 13, 'I usnul Joas s otci svými, a sedl Jeroboám na stolici jeho. I pochován jest Joas v Samaří s králi Izraelskými.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 14, 'Elizeus pak roznemohl se nemocí těžkou, v kteréž i umřel. A přišel byl k němu Joas král Izraelský, a pláče nad ním, řekl: Otče můj, otče můj, vozové Izraelští a jízdo jeho!');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 15, 'Ale Elizeus řekl jemu: Vezmi lučiště a střely. I vzav, přinesl k němu lučiště a střely.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 16, 'Řekl dále králi Izraelskému: Vezmi v ruku svou lučiště. I vzal je v ruku svou. Vložil také Elizeus ruce své na ruce královy.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 17, 'A řekl: Otevři to okno k východu. A když otevřel, řekl Elizeus: Střeliž. I střelil. Tedy řekl: Střela spasení Hospodinova a střela vysvobození proti Syrským; nebo porazíš Syrské v Afeku, až i do konce vyhladíš je.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 18, 'Opět řekl: Vezmi střely. I vzal. Tedy řekl králi Izraelskému: Střílej k zemi. I střelil po třikrát, potom tak nechal.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 19, 'Pročež rozhněvav se na něj muž Boží, řekl: Měls pětkrát neb šestkrát střeliti, ješto bys byl porazil Syrské, ažbys je i do konce byl vyhladil; nyní pak jen po třikrát porazíš Syrské.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 20, 'Potom umřel Elizeus, a pochovali ho. Lotříkové pak Moábští vtrhli do země nastávajícího roku.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 21, 'I stalo se, když pochovávali jednoho, že uzřevše ty lotříky, uvrhli muže toho do hrobu Elizeova. Kterýžto muž, jakž tam padl, a dotekl se kostí Elizeových, ožil a vstal na nohy své.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 22, 'Hazael pak král Syrský, ssužoval Izraele po všecky dny Joachaza.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 23, 'A milostiv jsa jim Hospodin, slitoval se nad nimi, a popatřil na ně, pro smlouvu svou s Abrahamem, s Izákem a s Jákobem, a nechtěl jich zahladiti, aniž zavrhl jich od tváři své až do tohoto času.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 24, 'I umřel Hazael král Syrský, a kraloval Benadad syn jeho místo něho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 25, 'Protož Joas syn Joachazův pobral zase města z ruky Benadada syna Hazaelova, kteráž byl vzal z ruky Joachaza otce jeho válečně; nebo po třikrát porazil ho Joas, a navrátil města Izraelská.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 1, 'Léta druhého Joasa syna Joachaza, krále Izraelského, kraloval Amaziáš syn Joasa, krále Judského.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 2, 'V pětmecítma letech byl, když počal kralovati, a kraloval dvadceti devět let v Jeruzalémě. Jméno matky jeho Joadan z Jeruzaléma.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 3, 'Ten činil to, což dobrého jest před očima Hospodinovýma, ačkoli ne tak jako David otec jeho. Všecko, což činil Joas otec jeho, tak činil.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 4, 'A však výsostí nezkazili, ještě lid obětoval a kadil na výsostech.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 5, 'I stalo se, když upevněno bylo království v ruce jeho, že pobil služebníky své, kteříž byli zabili krále otce jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 6, 'Synů pak těch vražedlníků nepobil, jakož jest psáno v knize zákona Mojžíšova, kdež přikázal Hospodin, řka: Nebudouť na hrdle trestáni otcové za syny, aniž synové trestáni budou na hrdle za otce, ale jeden každý za svůj hřích umře.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 7, 'On také porazil Idumejských v údolí solnatém deset tisíců, a dobyl Sela bojem. I nazval jméno jeho Jektehel až do tohoto dne.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 8, 'Tedy poslal Amaziáš posly k Joasovi synu Joachaza, syna Jéhu krále Izraelského, řka: Nuže, pohleďme sobě v oči.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 9, 'Zase poslal Joas král Izraelský k Amaziášovi králi Judskému a řekl: Bodlák, kterýž byl na Libánu, poslal k cedru Libánskému, řka: Dej dceru svou synu mému za manželku. V tom šlo tudy zvíře polní, kteréž bylo na Libánu, a pošlapalo ten bodlák.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 10, 'Že jsi mocně porazil Idumejské, protož pozdvihlo tě srdce tvé. Chlub se a seď v domě svém. I proč se máš plésti v neštěstí, abys padl ty i Juda s tebou?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 11, 'Ale Amaziáš neuposlechl. Protož vytáhl Joas král Izraelský, a pohleděli sobě v oči, on s Amaziášem králem Judským u Betsemes Judova.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 12, 'I poražen jest Juda od Izraele, a utíkali jeden každý do příbytků svých.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 13, 'Amaziáše pak krále Judského, syna Joasa syna Ochoziášova, jal Joas král Izraelský u Betsemes, a přitáh do Jeruzaléma, zbořil zed Jeruzalémskou, od brány Efraim až k bráně úhlu, na čtyři sta loktů.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 14, 'A pobral všecko zlato i stříbro, a všecky nádoby, kteréž se nalézaly v domě Hospodinově a v pokladích domu královského, také i mládence zastavené, a navrátil se do Samaří.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 15, 'O jiných pak činech Joasa, kteréž činil, i síle jeho, a kterak bojoval proti Amaziášovi králi Judskému, psáno jest v knize o králích Izraelských.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 16, 'I usnul Joas s otci svými, a pochován jest v Samaří s králi Izraelskými, i kraloval Jeroboám syn jeho místo něho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 17, 'Živ pak byl Amaziáš syn Joasův, král Judský, po smrti Joasa syna Joachaza, krále Izraelského, patnácte let.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 18, 'O jiných pak věcech Amaziášových psáno jest v knize o králích Judských.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 19, 'Potom spuntovali se proti němu v Jeruzalémě, a on utekl do Lachis. Protož poslali za ním do Lachis, a zamordovali ho tam.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 20, 'Odkudž odnesli jej na koních, a pochován jest v Jeruzalémě s otci svými v městě Davidově.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 21, 'Tedy všecken lid Judský vzali Azariáše, kterýž byl v šestnácti letech, a ustanovili ho za krále na místě otce jeho Amaziáše.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 22, 'Onť jest vzdělal Elat a dobyl ho Judovi, když byl již usnul král s otci svými.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 23, 'Léta patnáctého Amaziáše syna Joasa, krále Judského, kraloval Jeroboám syn Joasa, krále Izraelského, v Samaří čtyřidceti a jedno léto.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 24, 'A činil to, což jest zlého před očima Hospodinovýma, neuchýliv se od žádných hříchů Jeroboáma syna Nebatova, kterýž k hřešení přivedl Izraele.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 25, 'On zase dobyl končin Izraelských od toho místa, kudy se jde do Emat, až k moři pustému, vedlé řeči Hospodina Boha Izraelského, kterouž byl mluvil skrze služebníka svého Jonáše syna Amaty proroka, kterýž byl z Gethefer.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 26, 'Nebo viděl Hospodin trápení Izraele těžké náramně, a že jakož zajatý, tak i zanechaný s nic býti nemůže, aniž jest, kdo by spomohl Izraelovi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 27, 'A nemluvil Hospodin, že by chtěl zahladiti jméno Izraele, aby ho nebylo pod nebem; protož vysvobodil je skrze Jeroboáma syna Joasova.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 28, 'O jiných pak věcech Jeroboámových, a cožkoli činil, i o síle jeho, a kterak bojoval, jak zase dobyl Damašku a Emat Judova Izraelovi, psáno jest v knize o králích Izraelských.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 29, 'I usnul Jeroboám s otci svými, s králi Izraelskými, a kraloval Zachariáš syn jeho místo něho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 1, 'Léta sedmmecítmého Jeroboáma krále Izraelského kraloval Azariáš syn Amaziáše, krále Judského.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 2, 'V šestnácti letech byl, když počal kralovati, a kraloval padesáte dvě létě v Jeruzalémě. Jméno matky jeho bylo Jecholia z Jeruzaléma.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 3, 'Ten činil, což dobrého jest před očima Hospodinovýma vedlé všech věcí, kteréž činil Amaziáš otec jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 4, 'A však výsostí nezkazili, ještě lid obětoval a kadil na výsostech.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 5, 'Ranil pak Hospodin krále, tak že byl malomocný až do dne smrti své, a bydlil v domě obzvláštním. Pročež Jotam syn královský držel správu nad domem, soudě lid země.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 6, 'O jiných pak činech Azariášových, i cožkoli činil, psáno jest v knize o králích Judských.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 7, 'I usnul Azariáš s otci svými, a pochovali jej s otci jeho v městě Davidově, a kraloval Jotam syn jeho místo něho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 8, 'Léta třidcátého osmého Azariáše krále Judského kraloval Zachariáš syn Jeroboamův nad Izraelem v Samaří šest měsíců.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 9, 'A činil to, což jest zlého před očima Hospodinovýma, jakž činívali otcové jeho, neuchýliv se od hříchů Jeroboáma syna Nebatova, kterýž přivedl k hřešení Izraele.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 10, 'I spikl se proti němu Sallum syn Jábes a bil ho před lidem, i zabil jej a kraloval místo něho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 11, 'O jiných pak věcech Zachariášových zapsáno jest v knize o králích Izraelských.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 12, 'Toť jest slovo Hospodinovo, kteréž mluvil k Jéhu, řka: Synové tvoji do čtvrtého kolena seděti budou na stolici Izraelské. A tak se stalo.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 13, 'Sallum syn Jábesův kraloval léta třidcátého devátého Uziáše krále Judského, a kraloval jeden měsíc v Samaří.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 14, 'Nebo přitáhl Manahem syn Gádi z Tersa, a přišed do Samaří, porazil Sallum syna Jábes v Samaří, a zabiv jej, kraloval na místě jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 15, 'O jiných pak činech Sallum i spiknutí jeho, kteréž učinil, zapsáno jest v knize o králích Izraelských.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 16, 'Tehdy pohubil Manahem město Tipsach, a všecky, kteříž byli v něm, i všecky končiny jeho od Tersa, proto že mu ho neotevřeli. I pomordoval je, a všecky těhotné jejich zroztínal.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 17, 'Léta třidcátého devátého Azariáše krále Judského kraloval Manahem syn Gádi nad Izraelem v Samaří za deset let.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 18, 'A činil to, což jest zlého před očima Hospodinovýma, neodvrátiv se od hříchů Jeroboáma syna Nebatova, (kterýž přivedl Izraele k hřešení,) po všecky dny své.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 19, 'Když pak vytáhl Ful král Assyrský proti zemi té, dal Manahem Fulovi deset tisíc centnéřů stříbra, aby mu byl nápomocen k utvrzení království v rukou jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 20, 'I uložil Manahem daň na Izraele, na všecky bohaté, aby dávali králi Assyrskému jeden každý po padesáti lotech stříbra. Takž obrátiv se král Assyrský, nemeškal se více tu v zemi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 21, 'O jiných pak činech Manahemových, a cožkoli činil, zapsáno jest v knize o králích Izraelských.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 22, 'I usnul Manahem s otci svými, a kraloval Pekachia syn jeho místo něho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 23, 'Léta padesátého Azariáše, krále Judského, kraloval Pekachia syn Manahemův nad Izraelem v Samaří dvě létě.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 24, 'A činil to, což jest zlého před očima Hospodinovýma, neuchýliv se od hříchů Jeroboáma syna Nebatova, kterýž k hřešení přivedl Izraele.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 25, 'Tedy spuntoval se proti němu Pekach syn Romeliův, hejtman jeho, s Argobem i s Ariášem, a zabil jej v Samaří na paláci domu královského, maje s sebou padesáte mužů Galádských. A zabiv jej, kraloval místo něho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 26, 'Jiní pak skutkové Pekachia a všecko, což činil, zapsáno jest v knize o králích Izraelských.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 27, 'Léta padesátého druhého Azariáše krále Judského kraloval Pekach syn Romeliův nad Izraelem v Samaří dvadceti let.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 28, 'A činil to, což jest zlého před očima Hospodinovýma, aniž odstoupil od hříchů Jeroboáma syna Nebatova, kterýž k hřešení přivedl Izraele.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 29, 'Za dnů Pekacha krále Izraelského přitáhl Tiglatfalazar král Assyrský, a vzal Jon a Abel, dům Maacha a Janoe, Kedes a Azor, i Galád a Galilei, i všecku zemi Neftalím, a přenesl obyvatele jejich do Assyrie.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 30, 'Tedy spuntoval se Ozee syn Ela, proti Pekachovi synu Romeliovu, a raniv ho, zabil jej, a kraloval na místě jeho léta dvadcátého Jotama syna Uziášova.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 31, 'O jiných pak činech Pekachových, a cožkoli činil, zapsáno jest v knize o králích Izraelských.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 32, 'Léta druhého Pekacha syna Romelia, krále Izraelského, kraloval Jotam syn Uziáše, krále Judského.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 33, 'V pětmecítma letech byl, když počal kralovati, a šestnácte let kraloval v Jeruzalémě. Jméno matky jeho Jerusa, dcera Sádochova.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 34, 'A činil to, což pravého jest před očima Hospodinovýma. Všecko, jakž činil Uziáš otec jeho, tak činil.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 35, 'A však výsosti nebyly zkaženy, ještě lid obětoval a kadil na výsostech. On vystavěl bránu hořejší domu Hospodinova.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 36, 'O jiných pak činech Jotamových, a cožkoli činil, zapsáno jest v knize o králích Judských.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 37, 'Za dnů těch počal Hospodin posílati na Judu Rezina krále Syrského a Pekacha syna Romeliova.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 38, 'I usnul Jotam s otci svými, a pochován jest s otci svými v městě Davida otce svého. I kraloval Achas syn jeho místo něho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 1, 'Sedmnáctého léta Pekacha syna Romeliova kraloval Achas syn Jotama, krále Judského.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 2, 'Ve dvadcíti letech byl Achas, když kralovati počal, a šestnácte let kraloval v Jeruzalémě, ale nečinil toho, což pravého jest, před Hospodinem Bohem svým, jako David otec jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 3, 'Nýbrž chodil po cestě králů Izraelských; nadto i syna svého dal provésti skrze oheň vedlé ohavností pohanských, kteréž byl Hospodin vyplénil před oblíčejem synů Izraelských.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 4, 'Obětoval také a kadil na výsostech a na pahrbcích, i pod každým stromem zeleným.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 5, 'Tedy vytáhl Rezin král Syrský a Pekach syn Romeliášův, král Izraelský, proti Jeruzalému k boji, a oblehli Achasa. Ale nemohli ho dobyti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 6, '(Toho času Rezin král Syrský odtrhl zase město Elat k Syrii, a vyplénil Židy z Elot; Syrští pak přišedše do Elat, bydlili tam až do dnešního dne.)');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 7, 'I poslal Achas posly k Tiglatfalazarovi králi Assyrskému, řka: Služebník tvůj a syn tvůj jsem, přitáhni a vysvoboď mne z ruky krále Syrského, a z ruky krále Izraelského, kteříž povstali proti mně.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 8, 'A pobrav Achas stříbro a zlato, kteréž se nalézti mohlo v domě Hospodinově a v pokladích domu královského, poslal králi Assyrskému dar.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 9, 'Tedy povolil jemu král Assyrský, a přitáhl k Damašku a dobyl ho, a přenesl obyvatele jeho do Kir, Rezina pak zabil.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 10, 'I vypravil se král Achas vstříc Tiglatfalazarovi králi Assyrskému do Damašku. A uzřev král Achas oltář v Damašku, poslal k Uriášovi knězi podobenství toho oltáře, a formu jeho vedlé všelikého díla jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 11, 'I vzdělal Uriáš kněz oltář vedlé všeho toho, což byl poslal král Achas z Damašku. Tak učinil kněz Uriáš, prvé než se vrátil král Achas z Damašku.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 12, 'Když se pak navrátil král z Damašku, uzřev ten oltář přistoupil k němu a obětoval na něm.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 13, 'A tak zapálil zápal svůj i suchou obět svou, a obětoval obět mokrou svou, a pokropil krví oltáře z pokojných obětí svých.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 14, 'Oltář pak měděný, kterýž byl před Hospodinem, přenesl z přední strany domu, aby nestál mezi oltářem jeho a mezi domem Hospodinovým, a postavil jej po boku oltáře svého k půlnoci.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 15, 'I přikázal král Achas knězi Uriášovi, řka: Na větším oltáři obětuj zápaly jitřní, a obět suchou večerní, a obět zápalnou královskou s obětí suchou její, i obět zápalnou všeho lidu země, a oběti suché jejich, i oběti mokré jejich, a všelikou krví zápalu a všelikou krví oběti kropiti budeš na něj, oltář pak měděný bude mi k doptávání se Boha.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 16, 'Tedy učinil Uriáš kněz všecko, jakž mu přikázal Achas.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 17, 'Osekal také král Achas přepásaní podstavků, a odjal od nich pánve, a moře složil s volů měděných, kteříž byli pod ním, a položil je na dlážení kamenné.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 18, 'Zastření také sobotní, kteréž byli udělali v domě, a vcházení královské z zevnitř odjal od domu Hospodinova, boje se krále Assyrského.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 19, 'Jiní pak skutkové krále Achasa, kteréž činil, zapsáni jsou v knize o králích Judských.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 20, 'I usnul Achas s otci svými, a pochován jest s nimi v městě Davidově, a kraloval Ezechiáš syn jeho místo něho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 1, 'Léta dvanáctého Achasa krále Judského kraloval Ozee syn Ela v Samaří nad Izraelem devět let.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 2, 'A činil to, což jest zlého před očima Hospodinovýma, ač ne tak jako jiní králové Izraelští, kteříž byli před ním.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 3, 'Proti němuž přitáhl Salmanazar král Assyrský. I učiněn jest Ozee služebníkem jeho, a dával mu plat.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 4, 'Shledal pak král Assyrský při Ozee puntování; nebo poslal posly k Sua králi Egyptskému, a neposílal králi Assyrskému ročního platu. Protož oblehl ho král Assyrský, a svázaného dal do žaláře.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 5, 'I táhl král Assyrský po vší zemi; přitáhl také do Samaří, a ležel u ní tři léta.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 6, 'Léta pak devátého Ozee vzal král Assyrský Samaří, a přenesl Izraele do Assyrie, a osadil je v Chelach a v Chabor při řece Gozan, a v městech Médských.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 7, 'To se stalo, proto že hřešili synové Izraelští proti Hospodinu Bohu svému, kterýž je vyvedl z země Egyptské, aby nebyli pod mocí Faraona krále Egyptského, a ctili bohy cizí,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 8, 'Chodíce v ustanoveních pohanů, (kteréž byl vyvrhl Hospodin od tváři synů Izraelských,) a králů Izraelských, kteráž nařídili.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 9, 'Přesto pokrytě se měli synové Izraelští, činíce to, což není dobrého před Hospodinem Bohem svým, a vzdělali sobě výsosti ve všech městech svých, od věže strážných až do města hrazeného.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 10, 'A nastavěli sobě obrazů i hájů na všelikém pahrbku vysokém, a pod každým stromem zeleným,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 11, 'Zapalujíce tam vonné věci na všech výsostech, rovně jako pohané, kteréž vyhnal Hospodin od tváři jejich. A činili věci nejhorší, popouzejíce Hospodina.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 12, 'A sloužili bohům nečistým, o nichž byl Hospodin řekl jim, aby nečinili toho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 13, 'I osvědčoval Hospodin proti Izraelovi a proti Judovi skrze všecky proroky i všecky vidoucí, řka: Odvraťte se od cest svých zlých, a ostříhejte přikázaní mých a ustanovení mých vedlé všeho zákona, kterýž jsem vydal otcům vašim, a kterýž jsem poslal k vám skrze služebníky své proroky.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 14, 'Však neposlechli, ale zatvrdili šíji svou, jako i otcové jejich šíje své, kteříž nevěřili v Hospodina Boha svého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 15, 'A opovrhli ustanovení jeho i smlouvu jeho, kterouž učinil s otci jejich, i osvědčování jeho, kterýmiž se jim osvědčoval, a odešli po marnosti, a marní učiněni jsou, následujíce pohanů, kteříž byli vůkol nich, o nichž jim byl přikázal Hospodin, aby nečinili jako oni.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 16, 'A opustivše všecka přikázaní Hospodina Boha svého, udělali sobě slitinu, dvé telat a háj, a klaněli se všemu vojsku nebeskému; sloužili také Bálovi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 17, 'A vodili syny své a dcery své skrze oheň, a obírali se s hádáním a kouzly, a tak vydali se v činění toho, což jest zlé před očima Hospodinovýma, popouzejíce ho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 18, 'Protož rozhněval se Hospodin náramně na Izraele, a zahnal je od tváři své, nezanechav z nich nic, kromě samého pokolení Judova.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 19, 'Ano i Juda neostříhal přikázaní Hospodina Boha svého, ale chodili v ustanoveních Izraelských, kteráž byli nařídili.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 20, 'A protož opovrhl Hospodin všecko símě Izraelské a ssužoval je, a vydal je v ruku loupežníků, až je i zavrhl od tváři své.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 21, 'Nebo odtrhl Izraele od domu Davidova, a krále ustanovili Jeroboáma syna Nebatova, Jeroboám pak odvrátil Izraele od následování Hospodina, a přivedl je k hřešení hříchem velikým.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 22, 'A chodili synové Izraelští ve všech hříších Jeroboámových, kteréž on činil, a neodstoupili od nich,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 23, 'Až zavrhl Hospodin Izraele od tváři své, jakož byl mluvil skrze všecky služebníky své proroky. I vyhnán jest Izrael z země své do Assyrie až do tohoto dne.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 24, 'Potom král Assyrský přivedl lidi z Babylona, a z Kut a z Ava, a z Emat a z Sefarvaim, a osadil je v městech Samařských místo synů Izraelských, kteříž opanovavše Samaří, bydlili v městech jejich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 25, 'I stalo se, když tam bydliti počali, a nesloužili Hospodinu, že poslal na ně Hospodin lvy, kteříž je dávili.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 26, 'Protož mluvili králi Assyrskému, řkouce: Národové ti, kteréž jsi přenesl a osadil v městech Samařských, neznají obyčeje Boha země té; protož poslal na ně lvy, kteříž je hubí, proto že neznají obyčeje Boha země té.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 27, 'I přikázal král Assyrský, řka: Doveďte tam jednoho z těch kněží, kteréž jste odtud přivedli, a odejdouce, nechť tam bydlí, a učí je obyčeji Boha země té.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 28, 'Přišel tedy jeden z kněží, kteréž byli přivedli z Samaří, a bydlil v Bethel, a učil je, jak by měli sloužiti Hospodinu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 29, 'A však nadělali sobě jeden každý národ bohů svých, kteréž stavěli v domě výsostí, jichž byli nadělali Samařští, jeden každý národ v městech svých, v nichž bydlili.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 30, 'Muži zajisté Babylonští udělali Sukkot Benot, muži pak Kutští udělali Nergale, a muži Ematští udělali Asima.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 31, 'Hevejští tolikéž udělali Nibchaz a Tartak, a Sefarvaimští pálili syny své ohněm Adramelechovi a Anamelechovi, bohům Sefarvaimským.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 32, 'A tak sloužili Hospodinu, nadělavše sobě z počtu svého kněží výsostí, kteříž přisluhovali jim v domích výsostí.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 33, 'Hospodina ctili, však předce bohům svým sloužili vedlé obyčeje těch národů, odkudž převedeni byli.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 34, 'A do dnes činí vedlé obyčejů starých; nebojí se Hospodina, a nečiní vedlé ustanovení a úsudků jeho, ani vedlé zákona a přikázaní, kteráž vydal Hospodin synům Jákobovým, jehož nazval Izraelem.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 35, 'Učinil také byl Hospodin s nimi smlouvu, a přikázal jim, řka: Nebudete ctíti bohů cizích, ani se jim klaněti, ani jim sloužiti, ani jim obětovati.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 36, 'Ale Hospodina, kterýž vás vyvedl z země Egyptské v síle veliké a v rameni vztaženém, toho ctíti budete, a jemu se klaněti, a jemu obětovati.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 37, 'Také ustanovení a úsudků, i zákona a přikázaní, kteráž napsal vám, ostříhati budete, plníce je po všecky dny, a nebudete ctíti bohů cizích.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 38, 'Nadto na smlouvu, kterouž jsem učinil s vámi, nezapomínejte, aniž ctěte bohů cizích.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 39, 'Ale Hospodina Boha vašeho se bojte; onť vás vysvobodí z ruky všech nepřátel vašich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 40, 'A však neposlechli, ale vedlé obyčeje svého starého činili.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 41, 'A tak ti národové ctili Hospodina, a však proto rytinám svým sloužili. Takž i synové jejich a synové synů jejich vedlé toho, což činili otcové jejich, také činí až do dnešního dne.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 1, 'Stalo se pak léta třetího Ozee syna Ela, krále Izraelského, kraloval Ezechiáš syn Achasa, krále Judského.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 2, 'V pětmecítma letech byl, když počal kralovati, a dvadceti devět let kraloval v Jeruzalémě. Jméno matky jeho bylo Abi, dcera Zachariášova.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 3, 'Ten činil, což jest dobrého před očima Hospodinovýma, všecko tak, jakž činil David otec jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 4, 'On zkazil výsosti a stroskotal obrazy, a háje posekal, a ztloukl hada měděného, jehož byl udělal Mojžíš; nebo až do těch dnů synové Izraelští kadívali jemu, a nazval jej Nechustam.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 5, 'V Hospodinu Bohu Izraelském doufal, a nebylo po něm jemu rovného mezi všemi králi Judskými, i z těch, kteříž byli před ním.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 6, 'Nebo se přídržel Hospodina, aniž se uchýlil od něho, a ostříhal přikázaní jeho, kteráž byl přikázal Hospodin Mojžíšovi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 7, 'A byl Hospodin s ním; k čemuž se koli obrátil, šťastně se mu vedlo. Zprotivil se pak králi Assyrskému, a nesloužil jemu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 8, 'On porazil Filistinské až do Gázy a končin jeho, od věže strážných až do města hrazeného.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 9, 'Stalo se pak léta čtvrtého krále Ezechiáše, (jenž byl sedmý rok Ozee syna Ela, krále Izraelského,) vytáhl Salmanazar král Assyrský proti Samaří a oblehl ji.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 10, 'I vzali ji při konci léta třetího; léta šestého Ezechiášova, (jenž byl rok devátý Ozee krále Izraelského,) vzata jest Samaří.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 11, 'I zavedl král Assyrský Izraele do Assyrie, a osadil jej v Chelach a v Chabor při potoku Gozan, a v městech Médských,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 12, 'Proto že neposlouchali hlasu Hospodina Boha svého, ale přestupovali smlouvu jeho, i všecko to, což přikázal Mojžíš služebník Hospodinův, tak že ani poslechnouti ani činiti nechtěli.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 13, 'Potom čtrnáctého léta krále Ezechiáše přitáhl Senacherib král Assyrský proti všechněm městům Judským hrazeným, a zdobýval jich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 14, 'Tedy poslal Ezechiáš král Judský k králi Assyrskému do Lachis, řka: Zhřešilť jsem, odtáhni ode mne; cožkoli na mne vzložíš, ponesu. I uložil král Assyrský Ezechiášovi králi Judskému tři sta centnéřů stříbra a třidceti centnéřů zlata.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 15, 'I dal Ezechiáš všecky peníze, kteréž jsou nalezeny v domě Hospodinově a v pokladích domu královského.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 16, 'Toho času obloupal Ezechiáš dvéře chrámu Hospodinova, i sloupy, kteréž byl obložil Ezechiáš král Judský, a dal je králi Assyrskému.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 17, 'A však poslal král Assyrský Tartana a Rabsara a Rabsace z Lachis k králi Ezechiášovi s vojskem velikým k Jeruzalému. Kteříž vytáhše, přijeli k Jeruzalému, a přitáhše, přitrhli a položili se u struhy rybníka hořejšího, kteráž jest podlé cesty dlážené při poli valchářovu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 18, 'A když volali na krále, vyšel k nim Eliakim syn Helkiášův, kterýž byl správce domu, a Sobna písař, a Joach syn Azafův kancléř.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 19, 'I mluvil k nim Rabsace: Povězte medle Ezechiášovi: Toto praví král veliký, král Assyrský: Jakéž jest to doufání, na kterémž se zakládáš?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 20, 'Mluvils, (ale slova rtů svých), že jest rady i síly k válce dosti. V kohož tedy nyní doufáš, že mi se protivíš?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 21, 'Aj, nyní zpolehl jsi na hůl třtinovou, a to ještě nalomenou, na Egypt, na niž zpodepřel-li by se kdo, pronikne ruku jeho a probodne ji. Takovýť jest Farao král Egyptský všechněm, kteříž doufají v něho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 22, 'Pakli mi díte: V Hospodina Boha svého doufáme: zdaliž on není ten, jehož Ezechiáš pobořil výsosti i oltáře, a přikázal Judovi i Jeruzalému, řka: Před tímto oltářem klaněti se budete v Jeruzalémě.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 23, 'Nyní tedy, založ se medle se pánem mým, králem Assyrským, a dámť dva tisíce koní, budeš-li moci míti, kdo by na nich jeli?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 24, 'I jakž bys tedy odolati mohl jednomu knížeti z nejmenších služebníků pána mého, ačkoli máš doufání v Egyptu pro vozy a jezdce?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 25, 'Přesto, zdali bez Hospodina přitáhl jsem proti místu tomuto, abych je zkazil? Hospodin řekl mi: Táhni proti zemi té a zkaz ji.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 26, 'I řekl Eliakim syn Helkiášův a Sobna a Joach Rabsacovi: Mluv medle k služebníkům svým Syrsky, však rozumíme, a nemluv k nám Židovsky před lidem tímto, kterýž jest na zdech.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 27, 'I odpověděl jim Rabsace: Zdaliž ku pánu tvému a k tobě poslal mne pán můj, abych mluvil slova tato? Však k mužům těm, kteříž jsou na zdech, aby lejna svá jedli, a moč svůj spolu s vámi pili.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 28, 'A tak stoje Rabsace, volal hlasem velikým, Židovsky mluvě a řka: Slyšte slovo krále velikého, krále Assyrského.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 29, 'Toto praví král: Nechť vás nesvodí Ezechiáš, neboť nebude moci vás vysvoboditi z ruky mé.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 30, 'A nechť vám nevelí Ezechiáš doufati v Hospodina, řka: Zajisté vysvobodí nás Hospodin, a nebudeť dáno město toto v ruku krále Assyrského.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 31, 'Neposlouchejtež Ezechiáše, nebo takto praví král Assyrský: Učiňte se mnou smlouvu, a vyjděte ke mně, a jezte jeden každý z vinice své a z fíku svého, a píte jeden každý vodu z čisterny své,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 32, 'Dokudž nepřijdu a nepřenesu vás do země podobné zemi vaší, do země úrodné, země chleba a vinic, země olivoví, oleje a medu, a budete živi a nezemřete. Neposlouchejtež Ezechiáše, neboť vás svodí, řka: Hospodin vysvobodí nás.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 33, 'Zdaliž mohli vysvoboditi bohové národů jeden každý zemi svou z ruky krále Assyrského?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 34, 'Kdež jsou bohové Emat a Arfad? Kde jsou bohové Sefarvaim, Ana a Ava? Zdaliž jsou vysvobodili Samaří z ruky mé?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 35, 'Kteří jsou mezi všemi bohy těch zemí, ješto by vysvobodili zemi svou z ruky mé? Aby pak Hospodin vysvoboditi mohl Jeruzalém z ruky mé?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 36, 'Lid pak mlčel, a neodpověděl mu žádného slova; nebo takové bylo rozkázaní královo, řkoucí: Neodpovídejte jemu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 37, 'Přišli tedy Eliakim syn Helkie, kterýž byl správcím domu, a Sobna písař, a Joach syn Azafův kancléř k Ezechiášovi, majíce roucho roztržené, a oznámili jemu slova Rabsacova.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 1, 'To když uslyšel král Ezechiáš, roztrhl roucho své, a oděv se žíní, všel do domu Hospodinova.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 2, 'I poslal Eliakima správce domu, a Sobnu písaře, i starší z kněží, oblečené v žíně, k Izaiášovi proroku, synu Amosovu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 3, 'Kteříž řekli jemu: Toto praví Ezechiáš: Den úzkosti a útržek i rouhání jest den tento; přiblížilť se plod k vyjití, ale není síly při rodičce.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 4, 'Ó by slyšel Hospodin Bůh tvůj všecka slova Rabsacova, jehož poslal král Assyrský pán jeho, aby utrhal Bohu živému, aby pomstil Hospodin Bůh tvůj těch slov, kteráž by slyšel. Protož pozdvihni modlitby své za tento ostatek, kterýž se nalézá.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 5, 'A tak přišli služebníci krále Ezechiáše k Izaiášovi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 6, 'Jimž odpověděl Izaiáš: Toto povíte pánu svému: Takto praví Hospodin: Nestrachuj se slov těch, kteráž jsi slyšel, jimiž se mi rouhali služebníci krále Assyrského.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 7, 'Aj, já pustím naň vítr, aby uslyše pověst, navrátil se do země své, a učiním to, že padne od meče v zemi své.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 8, 'Rabsace pak navrátiv se, nalezl krále Assyrského, an dobývá Lebna; nebo uslyšel, (pročež odtrhl od Lachis,)');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 9, 'Uslyšel, pravím, o Tirhákovi králi Mouřenínském, ano pravili: Aj, teď táhne, aby bojoval s tebou. I navrátil se, a však poslal jiné posly k Ezechiášovi s těmito slovy:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 10, 'Takto povíte Ezechiášovi králi Judskému, řkouce: Nechť tebe nesvodí Bůh tvůj, v němž ty doufáš, říkaje: Nebudeť dán Jeruzalém v ruku krále Assyrského.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 11, 'Aj, slyšels, co jsou činili králové Assyrští všechněm zemím, pohubivše je, a ty bys měl býti vysvobozen?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 12, 'Zdaliž jsou je vysvobodili bohové těch národů, kteréž zahladili otcové moji, totiž Gozana, Charana, Resefa a syny Eden, kteříž byli v Telasar?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 13, 'Kde jest král Emat, a král Arfad, a král města Sefarvaim, Ana i Ava?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 14, 'Protož vzav Ezechiáš list z ruky poslů, přečetl jej, a vstoupiv do domu Hospodinova, rozvinul jej Ezechiáš před Hospodinem.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 15, 'A modlil se Ezechiáš před Hospodinem, řka: Hospodine Bože Izraelský, kterýž sedíš nad cherubíny, ty jsi sám Bůh všech království země, ty jsi učinil nebe i zemi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 16, 'Nakloniž, Hospodine, ucha svého a uslyš; otevři, Hospodine, oči své a pohleď; slyš slova Senacheribova, kterýž poslal k činění útržek Bohu živému.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 17, 'Takť jest, Hospodine, žeť jsou zkazili králové Assyrští národy ty i země jejich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 18, 'A uvrhli bohy jejich do ohně. Nebo nebyli bohové, ale dílo rukou lidských, dřevo a kámen, protož zahladili je.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 19, 'A nyní, Hospodine Bože náš, vysvoboď nás, prosím, z ruky jeho, ať by poznala všecka království země, že jsi ty sám, Hospodine, Bohem.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 20, 'Tedy poslal Izaiáš syn Amosův k Ezechiášovi, řka: Toto praví Hospodin Bůh Izraelský: Zač jsi mi se modlil strany Senacheriba krále Assyrského, vyslyšel jsem tě.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 21, 'Totoť jest slovo, kteréž mluvil Hospodin o něm: Pohrdá tebou, a posmívá se tobě, králi, panna dcera Sionská, potřásá za tebou hlavou dcera Jeruzalémská.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 22, 'Kohož jsi zhaněl? A komus se rouhal? Proti komu jsi povýšil hlasu a pozdvihls vzhůru očí svých? Však proti svatému Izraelskému.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 23, 'Skrze posly své utrhal jsi Pánu, a řekl jsi: Ve množství vozů svých vytáhl jsem na hory vysoké, na stráně Libánské, a zpodtínám vysoké cedry jeho, i spanilé jedle jeho, a vejdu do nejdalších příbytků jeho, do lesů a výborných rolí jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 24, 'Já jsem vykopal a pil jsem vody cizí, a vysušil jsem nohama svýma všecky potoky podmaněných.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 25, 'Zdaliž jsi neslyšel, že již dávno jsem jej učinil, a ode dnů starých jej sformoval? Což tedy nyní přivedl bych jej k zkažení a v hromady rumu, jako jiná města hrazená?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 26, 'Jejichž obyvatelé mdlí byli, předěšení a zahanbení, byvše jako bylina polní a zelina vzcházející, jako tráva na střechách, a jako osení rzí zkažené, prvé než by dorostlo obilí.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 27, 'Sedání pak tvé, vycházení tvé i vcházení tvé znám, i vzteklost tvou proti mně.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 28, 'Poněvadž jsi se rozzlobil proti mně, a tvé zpouzení přišlo v uši mé, protož vpustím udici svou v chřípě tvé, a udidla svá do úst tvých, a odvedu tě zase tou cestou, kterouž jsi přišel.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 29, 'Toto pak měj, Ezechiáši, za znamení: Že jíte roku prvního to, což se samo rodí, též druhého roku, což samo vzchází, třetího teprv roku sejte a žněte, a štěpujte vinice, a jezte ovoce z nich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 30, 'Ostatek zajisté domu Judova, kterýž pozůstal, vpustí zase kořeny své hluboce, a vydá užitek nahoru.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 31, 'Nebo z Jeruzaléma vyjdou ostatkové, a ti, kteříž jsou zachováni, z hory Siona. Horlivost Hospodina zástupů učiní to.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 32, 'A protož toto praví Hospodin o králi Assyrském: Nevejdeť do města tohoto, aniž sem střely vstřelí, aniž se ho zmocní pavézníci, aniž udělají u něho náspu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 33, 'Cestou, kterouž přitáhl, zase navrátí se, a do města tohoto nevejde, praví Hospodin.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 34, 'Nebo chrániti budu města tohoto, abych je zachoval pro sebe a pro Davida služebníka svého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 35, 'Tedy stalo se té noci, že vyšel anděl Hospodinův, a zbil v vojště Assyrském sto osmdesáte pět tisíců. I vstali ráno, a aj, všickni mrtví.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 36, 'Pročež odjel a utekl Senacherib král Assyrský, a navrátiv se, bydlil v Ninive.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 37, 'I stalo se, když se klaněl v chrámě Nizrocha boha svého, že Adramelech a Sarasar, synové jeho, zabili jej mečem, a sami utekli do země Ararat. I kraloval Esarchaddon syn jeho místo něho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 1, 'V těch dnech roznemohl se Ezechiáš až k smrti. I přišel k němu Izaiáš syn Amosův prorok, a řekl jemu: Toto praví Hospodin: Zřeď dům svůj, nebo umřeš, a nebudeš živ.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 2, 'I obrátil tvář svou k stěně, a modlil se Hospodinu, řka:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 3, 'Prosím, ó Hospodine, rozpomeň se nyní, že jsem stále chodil před tebou v pravdě a v srdci upřímém, a že jsem to činil, což dobrého jest před očima tvýma. I plakal Ezechiáš pláčem velikým.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 4, 'Ještě pak Izaiáš nebyl vyšel do půl síně, když se k němu stalo slovo Hospodinovo, řkoucí:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 5, 'Navrať se a rci Ezechiášovi vůdci lidu mého: Toto praví Hospodin Bůh Davida otce tvého: Slyšelť jsem modlitbu tvou, a viděl jsem slzy tvé; aj, já uzdravím tě, třetího dne vstoupíš do domu Hospodinova.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 6, 'A přidám ke dnům tvým patnácte let, a z ruky krále Assyrského vysvobodím tě, i město toto, a chrániti budu města tohoto, pro sebe a pro Davida služebníka svého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 7, 'I řekl Izaiáš: Vezměte hrudu suchých fíků. Kterouž vzavše, přiložili na vřed, i uzdraven jest.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 8, 'Řekl pak Ezechiáš Izaiášovi: Jaké bude znamení toho, že mne uzdraví Hospodin, a že půjdu třetího dne do domu Hospodinova?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 9, 'Odpověděl Izaiáš: Toto bude tobě znamení od Hospodina, že Hospodin učiní věc tuto, kterouž mluvil: Chceš-li, aby postoupil dále stín o deset stupňů, aneb navrátil se zpátkem o deset stupňů?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 10, 'Odpověděl Ezechiáš: Snázeť může stín postoupiti dolů o deset stupňů. Nechci, ale nechť zase postoupí stín zpátkem o deset stupňů.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 11, 'Volal tedy Izaiáš prorok k Hospodinu, a navrátil stín po stupních, po nichž sešel na hodinách slunečných Achasových, zpátkem o deset stupňů.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 12, 'Toho času poslal Berodach Baladan syn Baladanův, král Babylonský, list a dary Ezechiášovi; nebo slyšel, že nemocen byl Ezechiáš.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 13, 'I vyslyšel je Ezechiáš a ukázal jim všecky schrany klénotů svých, stříbra a zlata i vonných věcí, a olej nejvýbornější, tolikéž dům zbroje své, a cožkoli mohlo nalezeno býti v pokladích jeho. Ničeho nebylo, čehož by jim neukázal Ezechiáš v domě svém i ve všem panství svém.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 14, 'Protož přišel prorok Izaiáš k králi Ezechiášovi, a řekl jemu: Co pravili ti muži? A odkud přišli k tobě? Odpověděl Ezechiáš: Z země daleké přišli, z Babylona.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 15, 'I řekl: Co viděli v domě tvém? Odpověděl Ezechiáš: Všecko, což jest v domě mém, viděli. Ničeho není v pokladích mých, čehož bych jim neukázal.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 16, 'Ale Izaiáš řekl Ezechiášovi: Slyšiž slovo Hospodinovo.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 17, 'Aj, dnové přijdou, v nichž odneseno bude do Babylona, cožkoli jest v domě tvém, a cožkoli nachovali otcové tvoji až do tohoto dne; nezůstaneť ničeho, praví Hospodin.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 18, 'Syny také tvé, kteříž pojdou z tebe, kteréž ty zplodíš, poberou a budou komorníci při dvoru krále Babylonského.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 19, 'Tedy řekl Ezechiáš Izaiášovi: Dobréť jest slovo Hospodinovo, kteréž jsi mluvil. Řekl ještě: Ovšem, žeť jest dobré, jestliže pokoj a pravda bude za dnů mých.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 20, 'O jiných pak činech Ezechiášových, i vší síle jeho, a kterak udělal rybník, a vodu po trubách uvedl do města, zapsáno jest v knize o králích Judských.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 21, 'I usnul Ezechiáš s otci svými, a kraloval Manasses syn jeho místo něho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 1, 'Ve dvanácti letech byl Manasses, když počal kralovati, a kraloval padesáte a pět let v Jeruzalémě. Jméno matky jeho bylo Chefziba.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 2, 'I činil to, což jest zlého před očima Hospodinovýma, vedlé ohavností těch národů, kteréž Hospodin vyplénil před syny Izraelskými.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 3, 'Nebo převrátiv se, vzdělal zase výsosti, kteréž byl zkazil Ezechiáš otec jeho, a vystavěl oltáře Bálovi, a vysadil háj, tak jako byl učinil Achab král Izraelský. A klaněje se všemu vojsku nebeskému, ctil je.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 4, 'Vzdělal také oltáře v domě Hospodinově, o němž byl řekl Hospodin: V Jeruzalémě položím jméno své.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 5, 'Nadto nadělal oltářů všemu vojsku nebeskému, v obou síních domu Hospodinova.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 6, 'Syna také svého provedl skrze oheň, a šetřil časů, s hadačstvím zacházel, zaklinače a čarodějníky zřídil, a velmi mnoho zlého činil před očima Hospodinovýma, popouzeje ho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 7, 'Postavil také rytinu háje, kterouž byl udělal v domě, o kterémž byl řekl Hospodin k Davidovi a Šalomounovi synu jeho: V domě tomto a v Jeruzalémě, kterýž jsem vyvolil ze všech pokolení Izraelských, položím jméno své na věky,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 8, 'Aniž více dopustím, aby se pohnula noha Izraele z země, kterouž jsem dal otcům jejich, jen toliko budou-li skutečně ostříhati všeho, což jsem jim přikázal, a všeho zákona, kterýž jim vydal Mojžíš služebník můj.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 9, 'Ale neuposlechli; nebo je svedl Manasses, tak že činili horší věci, nežli ti národové, kteréž vyplénil Hospodin od tváři synů Izraelských,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 10, 'Ačkoli mluvíval Hospodin skrze služebníky své proroky, řka:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 11, 'Proto že činil Manasses král Judský ohavnosti tyto, a páchal horší věci nad všecko, což činili Amorejští, kteříž byli před ním, a že přivedl i Judu k hřešení skrze ukydané bohy své,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 12, 'Protož řekl Hospodin Bůh Izraelský: Aj, já uvedu zlé věci na Jeruzalém a na Judu, aby každému slyšícímu o tom znělo v obou uších jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 13, 'Nebo vztáhnu na Jeruzalém šňůru Samařskou, a závaží domu Achabova, a vytru Jeruzalém, jako vytírá někdo misku, a vytra, poklopí ji.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 14, 'A opustím ostatky dědictví svého, a vydám je v ruku nepřátel jejich, i budou v loupež a v rozchvátání všechněm nepřátelům svým,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 15, 'Proto že činili to, což jest zlého před očima mýma, a popouzeli mne od toho dne, jakž vyšli otcové jejich z Egypta, až do dnešního dne.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 16, 'Ano i krve nevinné vylil Manasses velmi mnoho, tak že naplnil Jeruzalém od jednoho konce k druhému, kromě hříchu svého, kterýmž přivedl k hřešení Judu, aby činili, což zlého jest před očima Hospodinovýma.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 17, 'O jiných pak činech Manassesových, a cožkoli činil, i hřích jeho, kterýmž zhřešil, zapsáno jest v knize o králích Judských.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 18, 'I usnul Manasses s otci svými, a pohřben jest v zahradě domu svého, v zahradě Uzy, a kraloval Amon syn jeho místo něho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 19, 'Ve dvamecítma letech byl Amon, když počal kralovati, a kraloval dvě létě v Jeruzalémě. Jméno matky jeho bylo Mesullemet, dcera Charus z Jateba.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 20, 'I ten činil to, což jest zlého před očima Hospodinovýma, jako činil Manasses otec jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 21, 'A chodil po vší cestě, po níž chodil otec jeho. Sloužil také ukydaným bohům, jimž sloužíval otec jeho, a klaněl se jim,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 22, 'Opustiv Hospodina Boha otců svých, aniž chodil po cestě Hospodinově.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 23, 'Spuntovali se pak služebníci Amonovi proti němu, a zamordovali jej v domě jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 24, 'Tedy pobil lid země všecky ty, kteříž se byli spuntovali proti králi Amonovi, a ustanovil lid země krále Joziáše syna jeho místo něho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 25, 'O jiných pak činech Amonových, kteréž činil, zapsáno jest v knize o králích Judských.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 26, 'I pochoval ho lid v hrobě jeho v zahradě Uzy, a kraloval Joziáš syn jeho místo něho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 1, 'V osmi letech byl Joziáš, když počal kralovati, a kraloval jedno a třidceti let v Jeruzalémě. Jméno matky jeho bylo Jedida, dcera Adaiášova z Baskat.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 2, 'Ten činil to, což pravého jest před očima Hospodinovýma, chodě po vší cestě Davida otce svého, a neuchyluje se na pravo ani na levo.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 3, 'Stalo se pak osmnáctého léta krále Joziáše, že poslal král Safana syna Azaliášova, syna Mesullamova, písaře, do domu Hospodinova, řka:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 4, 'Jdi k Helkiášovi knězi nejvyššímu, ať sečtou peníze, kteréž jsou vneseny do domu Hospodinova, kteréž sebrali strážní prahu od lidu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 5, 'A ať je dadí v ruce řemeslníků představených nad dílem domu Hospodinova, aby je obraceli na dělníky, kteříž dělají dílo v domě Hospodinově, k opravení zbořenin domu,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 6, 'Totiž na tesaře a stavitele a zedníky, též aby jednali dříví a tesané kamení k opravování domu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 7, 'A však ať počtu nečiní z peněz, kteréž se dávají v ruce jejich; nebo věrně dělati budou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 8, 'I řekl Helkiáš kněz nejvyšší Safanovi písaři: Knihu zákona nalezl jsem v domě Hospodinově. I dal Helkiáš knihu tu Safanovi, kterýž četl v ní.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 9, 'Přišel pak Safan písař k králi, a oznamuje králi tu věc, řekl: Sebrali služebníci tvoji peníze, kteréž se nalezly v domě Páně, a dali je v ruce řemeslníků představených nad dílem domu Hospodinova.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 10, 'Oznámil také Safan písař králi, řka: Knihu mi dal Helkiáš kněz. I četl ji Safan před králem.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 11, 'A když slyšel král slova knihy zákona, roztrhl roucho své.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 12, 'A rozkázal král Helkiášovi knězi, a Achikamovi synu Safanovu, a Achborovi synu Michaia, a Safanovi písaři, a Asaiášovi služebníku královskému, řka:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 13, 'Jděte, poraďte se s Hospodinem o mne i o lid, a o všeho Judu z strany slov knihy této, kteráž jest nalezena; nebo veliký jest hněv Hospodinův, kterýž rozpálen jest proti nám, proto že otcové naši neposlouchali slov knihy této, aby činili všecko tak, jakž jest nám zapsáno.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 14, 'Tedy šli Helkiáš kněz a Achikam, a Achbor, a Safan a Asaia k Chuldě prorokyni, manželce Salluma, syna Tekue, syna Charchas, strážného nad rouchem; nebo bydlila v Jeruzalémě na druhé straně. A mluvili s ní.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 15, 'Kteráž řekla jim: Toto praví Hospodin Bůh Izraelský: Povězte muži, kterýž vás poslal ke mně:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 16, 'Takto praví Hospodin: Aj, já uvedu zlé věci na místo toto a na obyvatele jeho, všecka slova knihy té, kterouž četl král Judský,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 17, 'Proto že mne opustili a kadili bohům cizím, aby mne popouzeli všelikým dílem rukou svých. Z té příčiny rozpálila se prchlivost má na místo toto, aniž bude uhašena.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 18, 'Králi pak Judskému, kterýž vás poslal, abyste se tázali Hospodina, takto povíte: Toto praví Hospodin Bůh Izraelský o slovích těch, kteráž jsi slyšel:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 19, 'Poněvadž obměkčeno jest srdce tvé, a ponížils se před tváří Hospodinovou, když jsi slyšel, které věci jsem mluvil proti místu tomuto, a proti obyvatelům jeho, že má přijíti v zpuštění a v zlořečení, a roztrhl jsi roucho své, a plakals přede mnou, i já také uslyšel jsem tě, praví Hospodin.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 20, 'Protož, aj, já připojím tě k otcům tvým, a pochován budeš v hrobích svých v pokoji, aby neviděly oči tvé ničeho z toho zlého, kteréž přivedu na místo toto. I oznámili králi tu řeč.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 1, 'Tedy poslav král, aby se shromáždili k němu všickni starší Judští a Jeruzalémští,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 2, 'Vstoupil král do domu Hospodinova a všickni muži Judští, i všickni obyvatelé Jeruzalémští s ním, i kněží a proroci, a všecken lid od malého až do velikého, i četl, aby všickni slyšeli všecka slova knihy smlouvy, kteráž byla nalezena v domě Hospodinově.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 3, 'Potom stoje král na místě vyšším, učinil smlouvu před Hospodinem, že bude následovati Hospodina, a ostříhati přikázaní jeho, i svědectví jeho a ustanovení jeho, vším srdcem svým a vší duší svou, a plniti slova smlouvy té, kteráž jsou zapsána v knize té. K kteréžto smlouvě i všecken lid přistoupil.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 4, 'A přikázal král Helkiášovi knězi nejvyššímu a kněžím nižším i strážným prahu, aby vymetali z chrámu Hospodinova všecky nádoby, kteréž udělány byly Bálovi a háji, i všemu vojsku nebeskému. Kterýž popáliv je vně za Jeruzalémem na poli Cedron, vnesl prach jejich do Bethel.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 5, 'Složil také kněží, kteréž byli ustanovili králové Judští, aby kadívali na výsostech v městech Judských a vůkol Jeruzaléma; takž podobně i ty, kteříž kadívali Bálovi, slunci, měsíci a planétám, i všemu vojsku nebeskému.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 6, 'Vyvezl také háj z domu Hospodinova ven z Jeruzaléma ku potoku Cedron, a spálil jej u potoka Cedron a setřel na prach; ten pak prach vysypal na hroby synů toho lidu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 7, 'Domky také sodomářů hanebných zkazil, kteříž byli při domě Hospodinově, v nichž ženy tkaly kortýny k háji.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 8, 'A kázal přivésti všecky kněží z měst Judských, a poškvrnil výsostí, na nichž kadívali kněží, od Gabaa až do Bersabé. Zkazil také výsostí u bran, kteréž byly u vrat brány Jozue, knížete města, a byly po levé straně vcházejícímu do brány městské.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 9, 'A však nepřistupovali ti kněží výsostí k oltáři Hospodinovu v Jeruzalémě, ale jídali chleby přesné mezi bratřími svými.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 10, 'Poškvrnil také i Tofet, jenž jest v údolí syna Hinnom, aby více žádný nevodil syna svého aneb dcery své skrze oheň Molochovi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 11, 'Zahladil také ty koně, kteréž byli postavili králové Judští slunci, kdež se vchází do domu Hospodinova, k domu Netanmelecha komorníka, kterýž byl v Parvarim; a vozy slunce spálil ohněm.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 12, 'Ano i oltáře, kteříž byli na vrchním paláci Achasovu, jichž byli nadělali králové Judští, a oltáře, jichž nadělal Manasses v obou síních domu Hospodinova, pobořil král, a pospíšiv s nimi odtud, dal vysypati prach jejich do potoka Cedron.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 13, 'Výsosti také, kteréž byly před Jeruzalémem, a kteréž byly po pravé straně hory Olivetské, jichž byl nadělal Šalomoun král Izraelský Astarotovi, ohavnosti Sidonských, a Chámosovi, ohavnosti Moábských, a Melchomovi, ohavnosti synů Ammon, poškvrnil král,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 14, 'A potřískal obrazy, háje posekal, a místa jejich naplnil kostmi lidskými.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 15, 'Nadto i oltář, jenž byl v Bethel, a výsost, kterouž udělal Jeroboám syn Nebatův, kterýž přivedl k hřešení Izraele, i ten oltář i výsost zkazil, a spáliv výsost, setřel ji na prach; spálil i háj.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 16, 'A obrátiv se Joziáš, uzřel hroby, kteříž tu na hoře byli, a poslav, pobral kosti z těch hrobů a spálil je na tom oltáři. A tak poškvrnil ho vedlé řeči Hospodinovy, kterouž mluvil muž Boží ten, kterýž to předpověděl.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 17, 'I řekl: Jaký jest onenno nápis, kterýž vidím? Odpověděli jemu muži města: Hrob muže Božího jest, kterýž přišed z Judstva, předpověděl tyto věci, kteréž jsi učinil při oltáři v Bethel.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 18, 'Tedy řekl: Nechtež ho, aniž kdo hýbej kostmi jeho. I vysvobodili kosti jeho s kostmi proroka toho, kterýž byl přišel z Samaří.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 19, 'Též všecky domy výsostí, kteříž byli v městech Samařských, jichž byli nadělali králové Izraelští, aby popouzeli Hospodina, zkazil Joziáš, a učinil jim rovně tak, jakž byl učinil v Bethel.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 20, 'Zbil také všecky kněží výsostí, kteříž tu byli, na oltářích, a pálil kosti lidské na nich. Potom navrátil se do Jeruzaléma.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 21, 'Přikázal pak král všemu lidu, řka: Slavte velikunoc Hospodinu Bohu svému, jakož psáno jest v knize smlouvy této.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 22, 'Nebo nebyla slavena taková velikanoc od času soudců, kteříž soudili Izraele, a po všecky dny králů Izraelských a králů Judských.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 23, 'Osmnáctého léta krále Joziáše slavena jest ta velikanoc Hospodinu v Jeruzalémě.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 24, 'Ano i věšťce a hadače, obrazy i ukydané bohy, a všecky ty ohavnosti, což jich bylo viděti v zemi Judské a v Jeruzalémě, vyplénil Joziáš, aby naplnil slova zákona zapsaná v knize, kterouž nalezl Helkiáš kněz v domě Hospodinově.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 25, 'A nebylo jemu podobného krále před ním, kterýž by obrátil se k Hospodinu celým srdcem svým, a celou duší svou, i všemi mocmi svými vedlé všeho zákona Mojžíšova, ani po něm nepovstal podobný jemu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 26, 'A však neodvrátil se Hospodin od prchlivosti hněvu svého velikého, kterouž vzbuzen byl hněv jeho proti Judovi, pro všecka popouzení, kterýmiž popouzel ho Manasses.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 27, 'Protož řekl Hospodin: Také i Judu zavrhu od tváři své, jako jsem zavrhl Izraele, a opovrhu to město, kteréž jsem vyvolil, Jeruzalém, i ten dům, o němž jsem byl řekl: Jméno mé tam bude.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 28, 'O jiných pak činech Joziášových, a cožkoli činil, zapsáno jest v knize o králích Judských.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 29, 'Za dnů jeho přitáhl Farao Nécho král Egyptský proti králi Assyrskému k řece Eufraten. I vytáhl král Joziáš proti němu, a on zabil jej v Mageddo, když ho uzřel.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 30, 'Tedy služebníci jeho vloživše jej mrtvého na vůz, přivezli ho z Mageddo do Jeruzaléma, a pochovali jej v hrobě jeho. I vzal lid země Joachaza syna Joziášova, a pomazali ho, i ustanovili králem na místě otce jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 31, 'Ve třimecítma letech byl Joachaz, když počal kralovati, a kraloval tři měsíce v Jeruzalémě. Jméno matky jeho bylo Chamutal, dcera Jeremiášova z Lebna.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 32, 'A činil to, což jest zlého před očima Hospodinovýma, všecko tak, jakž činili otcové jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 33, 'I svázal ho Farao Nécho v Ribla, v zemi Emat, když kraloval v Jeruzalémě, a uložil daň na tu zemi, sto centnéřů stříbra a centnéř zlata.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 34, 'A ustanovil Farao Nécho za krále Eliakima syna Joziášova, na místo Joziáše otce jeho, a proměnil jméno jeho, aby sloul Joakim. Ale Joachaza vzal, kterýž, když se dostal do Egypta, umřel tam.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 35, 'To pak zlato i stříbro dával Joakim Faraonovi; pročež šacoval obyvatele země, aby mohl dáti stříbro k rozkázaní Faraonovu. Od jednoho každého vedlé toho, jakž byl šacován, bral stříbro i zlato od lidu země, aby dal Faraonovi Néchovi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 36, 'V pětmecítma letech byl Joakim, když počal kralovati, a jedenácte let kraloval v Jeruzalémě. Jméno matky jeho bylo Zebuda, dcera Pedaiova z Ruma.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 37, 'I činil to, což jest zlého před očima Hospodinovýma, podlé všeho, což činili otcové jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 1, 'Za dnů jeho přitáhl Nabuchodonozor král Babylonský, i učiněn jest Joakim služebníkem jeho za tři léta. Potom odvrátiv se, zprotivil se jemu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 2, 'Protož poslal Hospodin na něj lotříky Kaldejské a lotříky Syrské, i lotříky Moábské a lotříky synů Ammon, poslal je, pravím, na Judu, aby ho zkazili vedlé řeči Hospodinovy, kterouž byl mluvil skrze služebníky své proroky.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 3, 'A jistě podlé řeči Hospodinovy to se dálo proti Judovi, aby jej zavrhl od tváři své pro hříchy Manassesovy, vedlé toho všeho, což byl činil,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 4, 'Ano i pro krev nevinnou, kterouž vylil, naplniv Jeruzalém krví nevinnou, čehož nechtěl Hospodin prominouti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 5, 'O jiných pak věcech Joakimových, a cožkoli činil, psáno jest v knize o králích Judských.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 6, 'A tak usnul Joakim s otci svými, a kraloval Joachin syn jeho místo něho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 7, 'Král pak Egyptský nikdy více nevytáhl z země své; nebo král Babylonský pobral od řeky Egyptské až k řece Eufraten všecko, cožkoli měl král Egyptský.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 8, 'V osmnácti letech byl Joachin, když počal kralovati, a tři měsíce kraloval v Jeruzalémě. Jméno matky jeho Nechusta, dcera Elnatanova z Jeruzaléma.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 9, 'I činil to, což jest zlého před očima Hospodinovýma, všecko tak, jakž byl činil otec jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 10, 'Toho času vytáhli služebníci Nabuchodonozora krále Babylonského proti Jeruzalému, a obleženo jest město.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 11, 'Ano i Nabuchodonozor král Babylonský přitáhl proti městu, když služebníci jeho leželi vůkol něho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 12, 'Tedy vyšel Joachin král Judský k králi Babylonskému, i s matkou svou i s služebníky, knížaty i komorníky svými, kteréhož vzal král Babylonský léta osmého kralování svého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 13, 'A vynesl odtud všecky poklady domu Hospodinova, a poklady domu královského, a ztloukl všecky nádoby zlaté, jichž byl nadělal Šalomoun král Izraelský do domu Hospodinova, jakož byl mluvil Hospodin.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 14, 'Při tom přenesl všecken Jeruzalém a všecka knížata i všecky muže udatné, deset tisíců zajatých, i všecky tesaře a kováře. Žádného nezanechal, kromě chaterných lidí země.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 15, 'Zavedl také i Joachina do Babylona, a matku jeho i ženy královské i komorníky jeho; silné také země zavedl do vězení z Jeruzaléma do Babylona.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 16, 'Všech také mužů udatných sedm tisíců, tesařů také a kovářů tisíc, všecky též zmužilé bojovníky zavedl jaté král Babylonský do Babylona.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 17, 'Ustanovil pak král Babylonský Mataniáše, strýce jeho, králem místo něho, a změnil mu jméno, aby sloul Sedechiáš.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 18, 'V jedenmecítma letech byl Sedechiáš, když počal kralovati a jedenácte let kraloval v Jeruzalémě. Jméno matky jeho bylo Chamutal, dcera Jeremiášova z Lebna.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 19, 'I činil to, což jest zlého před očima Hospodinovýma, všecko tak, jakž byl dělal Joakim.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 20, 'Nebo se to dálo pro rozhněvání Hospodinovo proti Jeruzalému a Judovi, až je i zavrhl od tváři své. V tom opět zprotivil se Sedechiáš králi Babylonskému.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 1, 'Stalo se pak léta devátého kralování jeho, měsíce desátého, v desátý den téhož měsíce, že přitáhl Nabuchodonozor král Babylonský se vším vojskem svým k Jeruzalému, a položil se u něho, a vzdělali proti němu hradbu vůkol.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 2, 'A bylo město obleženo, až do jedenáctého léta krále Sedechiáše.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 3, 'V kterémžto, devátého dne čtvrtého měsíce, rozmohl se hlad v městě, a neměl chleba lid země.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 4, 'I protrženo jest město, a všickni muži bojovní utekli noci té skrze bránu mezi dvěma zdmi u zahrady královské; Kaldejští pak leželi okolo města. Ušel také král cestou pouště.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 5, 'I honilo vojsko Kaldejské krále, a postihli ho na rovinách Jerišských, a všecko vojsko jeho rozprchlo se od něho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 6, 'A tak javše krále, přivedli jej k králi Babylonskému do Ribla, kdež učinili o něm soud.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 7, 'Syny pak Sedechiášovy zmordovali před očima jeho. Potom Sedechiáše oslepili, a svázavše ho řetězy ocelivými, zavedli jej do Babylona.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 8, 'Potom měsíce pátého, sedmý den téhož měsíce, léta devatenáctého kralování Nabuchodonozora krále Babylonského, přitáhl Nebuzardan hejtman nad žoldnéři, služebník krále Babylonského, do Jeruzaléma.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 9, 'A zapálil dům Hospodinův i dům královský, i všecky domy v Jeruzalémě, a tak všecky domy veliké vypálil.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 10, 'Zdi také Jeruzalémské vůkol pobořilo všecko vojsko Kaldejské, kteréž bylo s tím hejtmanem nad žoldnéři.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 11, 'Ostatek pak lidu, kterýž byl zůstal v městě, i poběhlce, kteříž se byli obrátili k králi Babylonskému, a jiný obecný lid, zavedl Nebuzardan hejtman nad žoldnéři.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 12, 'Toliko něco chaterného lidu země zanechal hejtman nad žoldnéři, aby byli vinaři a oráči.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 13, 'Nadto sloupy měděné, kteříž byli v domě Hospodinově, i podstavky, i moře měděné, kteréž bylo v domě Hospodinově, ztloukli Kaldejští, a měď z nich odvezli do Babylona.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 14, 'Též hrnce, lopaty a nástroje hudebné, a kadidlnice i všecky nádoby měděné, jimiž sloužili, pobrali.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 15, 'I nádoby k oharkům a kotlíky, a cokoli zlatého a stříbrného bylo, pobral hejtman nad žoldnéři,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 16, 'Sloupy dva, moře jedno a podstavky, jichž byl nadělal Šalomoun do domu Hospodinova. Nebylo váhy mědi všech těch nádob.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 17, 'Osmnácti loket byla výška sloupu jednoho, a makovice na něm měděná, kterážto makovice tří loket zvýší byla, a mřežování i jablka zrnatá na té makovici vůkol; všecko bylo měděné. Takovýž byl i druhý sloup s mřežováním.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 18, 'Vzal také týž hejtman nad žoldnéři Saraiáše kněze předního, a Sofoniáše kněze nižšího, a tři strážné prahu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 19, 'A z města vzal komorníka jednoho, kterýž byl hejtmanem nad muži bojovnými, a pět mužů z těch, jenž bývali při králi, kteříž nalezeni byli v městě, a předního spisovatele vojska, kterýž popisoval vojsko z lidu země, a šedesáte mužů z lidu země, kteříž se nalezli v městě.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 20, 'Zjímav tedy je Nebuzardan hejtman nad žoldnéři, přivedl je k králi Babylonskému do Ribla.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 21, 'I pobil je král Babylonský, a zmordoval je v Ribla, v zemi Emat, a tak zaveden jest Juda z země své.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 22, 'Lidu pak, kterýž zůstal v zemi Judské, jehož byl zanechal Nabuchodonozor král Babylonský, představil Godoliáše syna Achikama, syna Safanova.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 23, 'I uslyšeli všickni hejtmané vojska, oni i lid jejich, že postavil za správce král Babylonský Godoliáše, a přišli k Godoliášovi do Masfa, totiž Izmael syn Netaniášův, a Jochanan syn Kareachův, a Saraiáš syn Tanchumeta Netofatského, a Jazaniáš syn Machatův, oni i lid jejich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 24, 'Tedy přisáhl jim Godoliáš i lidu jejich, a řekl jim: Nebojte se služby Kaldejských, zůstaňte v zemi, a služte králi Babylonskému, a dobře vám bude.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 25, 'I stalo se měsíce sedmého, přišel Izmael syn Netaniáše, syna Elisamova, z semene královského, a deset mužů s ním. I zabili Godoliáše, a umřel; takž i Židy i Kaldejské, kteříž s ním byli v Masfa.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 26, 'Pročež zdvih se všecken lid, od malého až do velikého, i hejtmané vojsk, ušli do Egypta; nebo se báli Kaldejských.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 27, 'Stalo se také léta třidcátého sedmého po zajetí Joachina krále Judského, dvanáctého měsíce, dvadcátého sedmého dne téhož měsíce, povýšil Evilmerodach král Babylonský toho léta, když počal kralovati, Joachina krále Judského, pustiv ho z žaláře.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 28, 'A mluvil s ním dobrotivě, i stolici jeho postavil nad stolice jiných králů, kteříž s ním byli v Babyloně.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 29, 'Změnil též roucho jeho, kteréž měl v žaláři. I jídal vždycky před ním po všecky dny života svého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 30, 'Nebo vyměřený pokrm ustavičně dáván byl jemu od krále, a to na každý den po všecky dny života jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 1, 'Adam, Set, Enos,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 2, 'Kainan, Mahalaleel, Járed,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 3, 'Enoch, Matuzalém, Lámech,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 4, 'Noé, Sem, Cham a Jáfet.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 5, 'Synové Jáfetovi: Gomer, Magog, Madai, Javan, Tubal, Mešech a Tiras.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 6, 'Synové pak Gomerovi: Ascenez, Difat a Togorma.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 7, 'Synové pak Javanovi: Elisa, Tarsis, Cetim a Rodanim.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 8, 'Synové Chamovi: Chus, Mizraim, Put a Kanán.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 9, 'A synové Chusovi: Sába, Evila, Sabata, Regma, Sabatacha. Synové pak Regmovi: Sába a Dedan.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 10, 'Zplodil také Chus Nimroda; ten počal mocným býti na zemi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 11, 'Mizraim pak zplodil Ludim, Anamim, Laabim a Neftuim,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 12, 'Fetruzim také a Chasluim, (odkudž pošli Filistinští), a Kafturim.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 13, 'Kanán pak zplodil Sidona, prvorozeného svého, a Het,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 14, 'A Jebuzea, Amorea a Gergezea,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 15, 'A Hevea, Aracea a Sinea,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 16, 'A Aradia, Samarea a Amatea.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 17, 'Synové Semovi: Elam, Assur, Arfaxad, Lud, Aram, Hus a Hul, Geter a Mas.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 18, 'A Arfaxad zplodil Sále, Sále pak zplodil Hebera.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 19, 'Heberovi pak narodili se dva synové, z nichž jednoho jméno Peleg, proto že za dnů jeho rozdělena byla země, jméno pak bratra jeho Jektan.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 20, 'Kterýžto Jektan zplodil Elmodada, Salefa, Azarmota a Járe,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 21, 'A Adoráma, Uzala a Dikla,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 22, 'A Ebale, Abimahele a Sebai,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 23, 'A Ofira, Evila a Jobaba. Všickni ti byli synové Jektanovi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 24, 'Sem, Arfaxad, Sále,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 25, 'Heber, Peleg, Réhu,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 26, 'Sárug, Náchor, Táre,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 27, 'Abram, ten jest Abraham.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 28, 'Synové Abrahamovi: Izák a Izmael.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 29, 'Tito jsou rodové jejich: Prvorozený Izmaelův Nabajot, Cedar, Adbeel a Mabsan,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 30, 'Masma, Dumah, Massa, Hadad a Tema,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 31, 'Jetur, Nafis a Cedma. Ti jsou synové Izmaelovi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 32, 'Synové pak Cetury, ženiny Abrahamovy: Ta porodila Zamrana, Jeksana, Madana, Madiana, Jezbocha a Suecha. Synové pak Jeksanovi: Sába a Dedan.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 33, 'Synové pak Madianovi: Efa, Efer, Enoch, Abida a Helda. Všickni ti synové Cetury.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 34, 'Zplodil tedy Abraham Izáka. Synové pak Izákovi: Ezau a Izrael.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 35, 'Synové Ezau: Elifaz, Rahuel, Jehus, Jhelom a Kore.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 36, 'Synové Elifazovi: Teman, Omar, Sefi, Gatam, Kenaz a syn Tamny, totiž Amalech.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 37, 'Synové Rahuelovi: Nahat, Zára, Samma a Méza.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 38, 'Synové pak Seir: Lotan, Sobal, Sebeon, Ana, Dison, Eser a Dízan.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 39, 'Synové pak Lotanovi: Hori a Homam. Sestra pak Lotanova: Tamna.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 40, 'Synové Sobalovi: Alian, Manáhat, Ebal, Sefi a Onam. Synové pak Sebeonovi: Aia a Ana.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 41, 'Synové Anovi: Dison. A synové Disonovi: Hamran, Eseban, Jetran a Charan.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 42, 'Synové Eser: Balaan, Závan a Jakan. Synové Dízonovi: Hus a Aran.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 43, 'Tito pak jsou králové, kteříž kralovali v zemi Idumejské, prvé než kraloval který král z synů Izraelských: Béla syn Beorův, jehožto město jméno mělo Denaba.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 44, 'A když umřel Béla, kraloval na místě jeho Jobab, syn Záre z Bozra.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 45, 'A když umřel Jobab, kraloval místo něho Husam z země Temanské.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 46, 'A když umřel Husam, kraloval místo něho Adad syn Badadův, kterýž porazil Madianské v krajině Moábské; jehož město jméno mělo Avith.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 47, 'A když umřel Adad, kraloval na místě jeho Semla z Masreka.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 48, 'A když umřel Semla, kraloval místo něho Saul z Rohobot řeky.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 49, 'A když umřel Saul, kraloval místo něho Bálanan, syn Achoborův.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 50, 'A když umřel Bálanan, kraloval místo něho Adad, jehož město řečené Pahu; jméno pak ženy jeho Mehetabel, dcera Matredy, dcery Mezábovy.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 51, 'A když umřel Adad, byli vývodové Idumejští: Vývoda Tamna, vývoda Alja, vývoda Jetet,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 52, 'Vývoda Olibama, vývoda Ela, vývoda Finon,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 53, 'Vývoda Kenaz, vývoda Teman, vývoda Mabsar,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 54, 'Vývoda Magdiel, vývoda Híram. Ti byli vývodové Idumejští.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 1, 'Tito jsou synové Izraelovi: Ruben, Simeon, Léví, Juda, Izachar a Zabulon,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 2, 'Dan, Jozef, Beniamin, Neftalím, Gád a Asser.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 3, 'Synové Judovi: Her, Onan a Séla. Ti tři narodili se jemu z dcery Suovy Kananejské. Ale Her, prvorozený Judův, byl zlý před očima Hospodinovýma, protož zabil ho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 4, 'Támar pak nevěsta jeho porodila mu Fáresa a Záru. Všech synů Judových pět.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 5, 'Synové Fáresovi: Ezron a Hamul.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 6, 'Synové pak Záre: Zamri, Etan, Héman, Kalkol a Dára, všech těch pět.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 7, 'A synové Zamri: Charmi, vnuk Achar, kterýž zkormoutil Izraele, zhřešiv při věci proklaté.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 8, 'Synové pak Etanovi: Azariáš.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 9, 'Synové pak Ezronovi, kteříž se mu zrodili: Jerachmeel, Ram a Chelubai.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 10, 'Ram pak zplodil Aminadaba, a Aminadab zplodil Názona, kníže synů Juda.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 11, 'Názon pak zplodil Salmona, a Salmon zplodil Bóza.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 12, 'A Bóz zplodil Obéda, a Obéd zplodil Izai.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 13, 'Izai pak zplodil prvorozeného svého Eliaba, a Abinadaba druhého, a Sammu třetího,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 14, 'Natanaele čtvrtého, Raddaia pátého,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 15, 'Ozema šestého, Davida sedmého,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 16, 'A sestry jejich: Sarvii a Abigail. Synové pak Sarvie byli: Abizai, Joáb, Azael, tři.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 17, 'Abigail pak porodila Amazu, otec pak Amazův byl Jeter Izmaelitský.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 18, 'Kálef pak syn Ezronův zplodil s Azubou manželkou a s Jeriotou syny. Jehož tito synové byli: Jeser, Sobab a Ardon.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 19, 'Když pak umřela Azuba, pojal sobě Kálef Efratu, kteráž mu porodila Hura.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 20, 'A Hur zplodil Uri, a Uri zplodil Bezeleele.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 21, 'Potom všel Ezron k dceři Machira otce Galádova, kterouž on pojal, když byl v šedesáti letech. I porodila jemu Seguba.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 22, 'Segub pak zplodil Jaira, kterýž měl třimecítma měst v zemi Galád.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 23, 'Nebo vzal Gessurejským a Assyrským vsi Jairovy, i Kanat s městečky jeho, šedesáte měst. To všecko pobrali synové Machirovi, otce Galádova.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 24, 'Též i po smrti Ezronově, když již pojal byl Kálef Efratu, manželka Ezronova Abia porodila jemu také Ashura, otce Tekoa.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 25, 'Byli pak synové Jerachmeele prvorozeného Ezronova: Prvorozený Ram, po něm Buna a Oren, a Ozem s Achia.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 26, 'Měl také manželku druhou Jerachmeel, jménem Atara. Ta jest matka Onamova.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 27, 'Byli pak synové Ramovi prvorozeného Jerachmeele: Maaz a Jamin a Eker.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 28, 'Též synové Onamovi byli: Sammai a Jáda. A synové Sammai: Nádab a Abisur.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 29, 'Jméno pak manželky Abisurovy Abichail; kteráž porodila jemu Achbana a Molida.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 30, 'A synové Nádabovi: Seled a Appaim. Ale umřel Seled bez dětí.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 31, 'Synové pak Appaimovi: Jesi; a synové Jesi: Sesan; a dcera Sesanova: Achlai.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 32, 'Synové pak Jády, bratra Sammaiova: Jeter a Jonatan. Ale umřel Jeter bez dětí.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 33, 'Synové pak Jonatanovi: Felet a Záza. Ti byli synové Jerachmeelovi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 34, 'Neměl pak Sesan synů, ale dceru. A měl Sesan služebníka Egyptského jménem Jarchu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 35, 'Protož dal Sesan dceru svou Jarchovi služebníku svému za manželku, kteráž porodila mu Attaie.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 36, 'Attai pak zplodil Nátana, a Nátan zplodil Zabada.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 37, 'Zabad pak zplodil Eflale, a Eflal zplodil Obéda.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 38, 'Obéd pak zplodil Jéhu, a Jéhu zplodil Azariáše.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 39, 'Azariáš pak zplodil Cheleza, a Chelez zplodil Elasu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 40, 'Elasa pak zplodil Sismaie, a Sismai zplodil Salluma.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 41, 'Sallum pak zplodil Jekamiáše, a Jekamiáš zplodil Elisama.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 42, 'Synové pak Kálefa, bratra Jerachmeelova: Mésa prvorozený jeho. On byl otec Zifejských i synů Marese, otce Hebronova.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 43, 'Synové pak Hebronovi: Chóre a Tapuach, a Rekem a Sema.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 44, 'Sema pak zplodil Rachama otce Jorkeamova, a Rekem zplodil Sammaie.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 45, 'Syn pak Sammai byl Maon; kterýžto Maon byl otec Betsurských.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 46, 'Efa také, ženina Kálefova, porodila Chárana a Mozu a Gazeza. A Cháran zplodil Gazeza.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 47, 'Synové pak Johedai: Regem, Jotam, Gesan, Felet, Efa a Saaf.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 48, 'S ženinou Maachou Kálef zplodil Sebera a Tirchana.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 49, 'Porodila pak Saafa otce Madmanejských, Sévu otce Makbenejských a otce Gibejských. Též dcera Kálefova Axa.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 50, 'Ti byli synové Kálefovi, syna Hur prvorozeného Efraty: Sobal otec Kariatjeharimských,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 51, 'Salma otec Betlémských, Charef otec čeledi Betgaderských.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 52, 'Měl pak syny Sobal otec Kariatjeharimských: Haroe otce obyvatelů dílu Menuchotských.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 53, 'A čeledi Kariatjeharimských, Jeterských, Putských, Sumatských a Misraiských. Z těch pošli Zaratští a Estaolští.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 54, 'Synové Salmy: Betlémští, Netofatští, Atarotští z čeledi Joábovy, a Zarští, kteříž užívali dílu Menuchotských,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 55, 'A čeledi písařů obývajících v Jábezu, Tiratských, Simatských, Suchatských. Ti jsou Cinejští příchozí z Amata, otce čeledi Rechabovy.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 1, 'Tito jsou pak synové Davidovi, kteříž se jemu zrodili v Hebronu: Prvorozený Amnon z Achinoam Jezreelské, druhý Daniel z Abigail Karmelské;');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 2, 'Třetí Absolon syn Maachy, dcery Tolmai, krále Gessur, čtvrtý Adoniáš, syn Haggit;');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 3, 'Pátý Sefatiáš z Abitál, šestý Jetram, z Egly manželky jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 4, 'Šest se mu jich zrodilo v Hebronu, kdež kraloval sedm let a šest měsíců; třidceti pak a tři kraloval v Jeruzalémě.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 5, 'Potom tito se jemu zrodili v Jeruzalémě: Sammua, Sobab, Nátan a Šalomoun, čtyři, z Betsabé, dcery Amielovy;');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 6, 'Též Ibchar, Elisama a Elifelet;');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 7, 'A Noga, Nefeg a Jafia;');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 8, 'A Elisama, Eliada a Elifelet, těch devět.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 9, 'Všickni ti synové Davidovi krom synů ženin, a Támar sestra jejich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 10, 'Syn pak Šalomounův Roboám, Abiam syn jeho, Aza syn jeho, Jozafat syn jeho,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 11, 'Joram syn jeho, Ochoziáš syn jeho, Joas syn jeho,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 12, 'Amaziáš syn jeho, Azariáš syn jeho, Jotam syn jeho,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 13, 'Achas syn jeho, Ezechiáš syn jeho, Manasses syn jeho,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 14, 'Amon syn jeho, Joziáš syn jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 15, 'Synové pak Joziášovi: Prvorozený Jochanan, druhý Joakim, třetí Sedechiáš, čtvrtý Sallum.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 16, 'Synové pak Joakimovi: Jekoniáš syn jeho, Sedechiáš syn jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 17, 'Synové pak Jekoniáše vězně: Salatiel syn jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 18, 'Toho pak Malkiram, Pedai, Senazar, Jekamia, Hosama a Nedabia.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 19, 'Synové pak Pedaiovi: Zorobábel a Semei. A syn Zorobábelův: Mesullam, Chananiáš, a Selomit sestra jejich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 20, 'Toho pak Chasuba, Ohel, Berechiáš, Chasadiáš a Jusabchesed, těch pět.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 21, 'Syn pak Chananiášův: Pelatia a Izaiáš. Synové Refaie, synové Arnanovi, synové Abdiášovi, synové Sechaniovi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 22, 'A synové Sechaniovi: Semaiáš. A synové Semaiášovi: Chattus, Igal, Bariach, Neariáš a Safat, šest.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 23, 'A syn Neariáše: Elioenai, Ezechiáš a Azrikam, ti tři.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 24, 'Též synové Elioenai: Hodaviáš, Eliasib, Pelaiáš, Akkub, Jochanan, Delaiáš a Anani, těch sedm.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 1, 'Synové Judovi: Fáres, Ezron, Charmi, Hur a Sobal.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 2, 'Reaiáš pak syn Sobalův zplodil Jachata, Jachat pak zplodil Ahumai a Laad. Ti jsou rodové Zarati.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 3, 'A tito z otce Etama: Jezreel, Isma a Idbas; a jméno sestry jejich Zelelfoni.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 4, 'Fanuel pak otec Gedor, a Ezer otec Chusův. Ti jsou synové Hur prvorozeného Efraty, otce Betlémských.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 5, 'Ashur pak otec Tekoe měl dvě manželky, Chélu a Naaru.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 6, 'I porodila jemu Naara Achuzama, Hefera, Temana a Achastara. Ti jsou synové Naary.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 7, 'Synové pak Chéle: Zeret, Jezochar a Etnan.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 8, 'Kóz pak zplodil Anuba, Hazobeba, a rodiny Acharchele syna Harumova.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 9, 'Byl pak Jábez slavnější nad bratří své, a matka jeho nazvala jméno jeho Jábez, řkuci: Nebo jsem ho porodila s bolestí.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 10, 'Kterýžto Jábez vzýval Boha Izraelského, řka: Jestliže štědře požehnáš mi, a rozšíříš meze mé, a bude ruka tvá se mnou, a vysvobodíš mne od zlého, abych bolesti netrpěl. I učinil Bůh, začež žádal.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 11, 'Chelub pak, bratr Sucha, zplodil Mechiru. Onť jest otec Estonův.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 12, 'Eston pak zplodil Betrafa, Paseacha a Techinna, otce města Náchas. Ti jsou muži Rechy.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 13, 'Synové pak Cenezovi: Otoniel a Saraiáš. Synové pak Otonielovi: Chatat.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 14, 'Meonatai pak zplodil Ofru, Saraiáš pak zplodil Joába, otce bydlících v údolí řemeslníků; nebo tam řemeslníci byli.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 15, 'Synové pak Kálefa, syna Jefonova: Iru, Ela a Naam. Syn pak Ela: Cenez.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 16, 'Synové pak Jehalleleelovi: Zif, Zifa, Tiriáš a Asarel.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 17, 'A synové Ezry: Jeter, Mered, Efer a Jalon. Porodila také Miriama, Sammai a Jezba otce Estemo.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 18, 'Manželka pak jeho Jehudia porodila Jereda otce Gedor, a Hebera otce Socho, a Jekutiele otce Zanoe. A ti jsou synové Betie dcery Faraonovy, kterouž pojal Mered.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 19, 'Synové pak manželky Hodia sestry Nachamovy, otce Cejly: Garmi a Estemo Maachatský.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 20, 'Synové pak Simonovi: Amnon, Rinna, Benchanan a Tilon. A synové Jesi: Zochet a Benzochet.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 21, 'Synové Séla syna Judova: Her otec Lechův, a Lada otec Maresův, a čeledi domu těch, jenž dělali díla kmentová v domě Asbea,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 22, 'A Jokim a muži Chozeby, Joas a Saraf, kteříž panovali v Moáb, a Jasubi Lechem. Ale ty věci jsou starodávní.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 23, 'Toť jsou ti hrnčíři obyvatelé v štěpnicích a ohradách u krále, příčinou díla jeho tam bydlíce.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 24, 'Synové Simeonovi: Namuel, Jamin, Jarib, Zára a Saul.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 25, 'Sallum syn jeho, Mabsam syn jeho, Masma syn jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 26, 'Synové pak Masmovi: Hamuel syn jeho, Zakur syn jeho, Semei syn jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 27, 'Ten Semei měl synů šestnácte a dcer šest. Bratří pak jejich neměli mnoho synů, tak že vší rodiny jejich nebylo tak mnoho, jako synů Judových.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 28, 'Bydlili pak v Bersabé a Molada a v Azarsual,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 29, 'A v Bála, v Esem a v Tolad,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 30, 'A v Betueli, v Horma a v Sicelechu,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 31, 'A v Betmarchabot, a v Azarsusim, v Betberi a v Saraim. Ta byla města jejich, dokudž kraloval David.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 32, 'Vsi také jejich při Etam, Ain, Remmon, Tochen, Asan, pěti městech.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 33, 'A tak všecky vesnice jejich, kteréž byly vůkol těch měst až do Baal, ta byla obydlé jejich vedlé rodu jejich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 34, 'A Mesobab, Jamlech a Josa syn Amazův;');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 35, 'A Joel, a Jéhu syn Jozabiáše, syna Saraiášova, syna Azielova;');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 36, 'A Elioenai, Jákoba, Jesochaiáš, Asaiáš, Adiel a Jesimeel a Benaiáš;');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 37, 'A Ziza syn Sifi, syna Allonova, syna Jedaiášova, syna Simri, syna Semaiášova.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 38, 'Tito ze jména vyčtení ustaveni jsou za knížata v čeledech svých, a čeledi otcovské jejich rozmnožily se náramně.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 39, 'A protož brali se, kudyž se vchází k Gedor, až k východu po údolí tom, aby hledali pastev dobytku svému.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 40, 'I nalezli pastvu hojnou a výbornou, zemi pak prostrannou, bezpečnou a pokojnou, a že z Chama byli ti, kteříž bydlili tam před tím.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 41, 'Protož přišedše ti napsaní ze jména ve dnech Ezechiáše krále Judského, pobořili stany jejich a příbytky, kteříž tam nalezeni byli, a zmordovali je, tak že jich do tohoto dne není, a sami osedli místo nich; nebo měli tu pastvu dobytku svému.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 42, 'Někteří pak z těch synů Simeonových odebrali se na horu Seir, mužů pět set, jichž Pelatia, Neariáš, Refaiáš a Uziel, synové Jesi, byli vůdcové.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 43, 'I vyplénili ostatek těch, kteříž ušli z Amalechitských, a bydlili tam až do tohoto dne.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 1, 'Synové pak Rubenovi prvorozeného Izraelova: (nebo on byl prvorozený, ale když poškvrnil lože otce svého, dáno jest prvorozenství jeho synům Jozefovým, syna Izraelova, však jemu není přičteno prvorozenství.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 2, 'Nebo Judas byl nejsilnější z bratří svých, a kníže mezi nimi, ale prvorozenství Jozefovi náleželo).');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 3, 'Synové, pravím, Rubenovi, prvorozeného Izraelova: Enoch, Fallu, Ezron a Charmi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 4, 'Synové Joelovi: Semaiáš syn jeho, Gog syn jeho, Semei syn jeho;');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 5, 'Mícha syn jeho, Reaiáš syn jeho, Bál syn jeho;');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 6, 'Béra syn jeho, jehož zavedl Tiglatfalazar král Assyrský. Ten byl knížetem pokolení Rubenova.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 7, 'Bratří pak jeho po čeledech jejich, když vyčteni byli po rodinách svých, knížetem byl Jehiel a Zachariáš.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 8, 'A Béla syn Azaza, syna Semy, syna Joelova. Ten bydlil v Aroer až do Nébo a Balmeon.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 9, 'Potom i na východ bydlil, až kudy se vchází na poušť od řeky Eufrates; nebo stáda jejich rozmnožila se v zemi Galádské.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 10, 'Pročež ve dnech Saulových bojovali s Agarenskými, kteříž poraženi jsou od ruky jejich. A tak bydlili v staních jejich po vší krajině východní země Galádské.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 11, 'Synové pak Gádovi naproti nim bydlili v zemi Bázan, až do Sálechy.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 12, 'Joel byl kníže jejich, a Safan druhý. Ale Janai a Safat v Bázan zůstali.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 13, 'Bratří pak jejich po domích otců svých: Michael, Mesullam, Seba, Jorai, Jachan, Zia, Heber, těch sedm.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 14, '(Ti byli synové Abichailovi, synové Hurovi, synové Jaroachovi, synové Galádovi, synové Michaelovi, synové Jesisovi, synové Jachdovi, synové Buzovi.)');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 15, 'Též Ahi syn Abdiele, syna Gunova, kníže v domě otců jich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 16, 'I bydlili v Galád, v Bázan a v vesnicech jeho, a ve všech předměstích Sáron, až do hranic jejich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 17, 'Všickni tito vyčteni byli ve dnech Jotama krále Judského, a ve dnech Jeroboáma krále Izraelského.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 18, 'Synů Rubenových a Gádových a polovice pokolení Manassesova, mužů silných, nosících štít a meč, a natahujících lučiště, a umělých v bitvě, čtyřidceti a čtyři tisíce, sedm set a šedesát vycházejících k boji.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 19, 'I bojovali s Agarenskými, Iturejskými, Nafejskými a Nodabskými.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 20, 'A měli pomoc proti nim. I dáni jsou v ruku jich Agarenové i všecko, což měli. Nebo k Bohu volali v boji, a vyslyšel je, nebo doufali v něho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 21, 'I zajali stáda jejich, velbloudů jejich padesáte tisíců, a dobytka dvě stě a padesáte tisíců, a oslů dva tisíce, a lidí sto tisíc osob.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 22, 'Zraněných také množství padlo, nebo od Boha byla porážka ta. I bydlili na místě jejich až do přestěhování svého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 23, 'Synové pak polovice pokolení Manassesova bydlili v té zemi od Bázanu až do Balhermon i Sanir, totiž hory Hermon; nebo i oni rozmnoženi byli.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 24, 'Tato pak byla knížata v domě otců jejich: Efer, Jesi, Eliel, Azriel, Jeremiáš, Hodaviáš a Jachdiel, muži udatní a silní, muži slovoutní, knížata domu otců svých.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 25, 'Ale když přestoupili proti Bohu otců svých, a smilnili, následujíce bohů národů země té, kteréž shladil Bůh od tváři jejich:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 26, 'Vzbudil Bůh Izraelský ducha Fule krále Assyrského, a ducha Tiglatfalazara krále Assyrského, kterýž přenesl pokolení Rubenovo a Gádovo a polovici pokolení Manassesova, a dovedl je do Chelach a do Chabor, až do Hara a k řece Gozan až do dnešního dne.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 1, 'Synové Léví: Gerson, Kahat a Merari.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 2, 'Synové pak Kahat: Amram, Izar, Hebron a Uziel.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 3, 'Synové pak Amramovi: Aron, Mojžíš, a Maria. Synové pak Aronovi: Nádab, Abiu, Eleazar a Itamar.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 4, 'Eleazar zplodil Fínesa, Fínes zplodil Abisua.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 5, 'Abisua pak zplodil Bukki, Bukki pak zplodil Uzi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 6, 'Uzi pak zplodil Zerachiáše, Zerachiáš pak zplodil Meraiota.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 7, 'Meraiot zplodil Amariáše, Amariáš pak zplodil Achitoba.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 8, 'Achitob pak zplodil Sádocha, Sádoch pak zplodil Achimaasa.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 9, 'Achimaas pak zplodil Azariáše, Azariáš pak zplodil Jochanana.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 10, 'Jochanan pak zplodil Azariáše. Onť jest užíval kněžství v domě, jejž ustavěl Šalomoun v Jeruzalémě.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 11, 'Zplodil pak Azariáš Amariáše, Amariáš pak zplodil Achitoba.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 12, 'Achitob zplodil Sádocha, Sádoch pak zplodil Salluma.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 13, 'Sallum pak zplodil Helkiáše, Helkiáš pak zplodil Azariáše.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 14, 'Azariáš pak zplodil Saraiáše, Saraiáš pak zplodil Jozadaka.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 15, 'Jozadak pak odšel, když převedl Hospodin Judu a Jeruzalém skrze Nabuchodonozora.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 16, 'Synové Léví: Gersom, Kahat a Merari.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 17, 'Tato pak jsou jména synů Gersomových: Lebni a Semei.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 18, 'Synové pak Kahat: Amram, Izar, Hebron a Uziel.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 19, 'Synové Merari: Moholi a Musi. A tak ty jsou čeledi Levítů po otcích jejich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 20, 'Gersomovi: Lebni syn jeho, Jachat syn jeho, Zimma syn jeho,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 21, 'Joach syn jeho, Iddo syn jeho, Zára syn jeho, Jetrai syn jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 22, 'Synové Kahat: Aminadab syn jeho, Chóre syn jeho, Assir syn jeho,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 23, 'Elkána syn jeho, a Abiazaf syn jeho, Assir syn jeho,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 24, 'Tachat syn jeho, Uriel syn jeho, Uziáš syn jeho, Saul syn jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 25, 'Synové pak Elkánovi: Amasai a Achimot.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 26, 'Elkána: Synové Elkánovi: Zofai syn jeho, a Nachat syn jeho,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 27, 'Eliab syn jeho, Jerocham syn jeho, Elkána syn jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 28, 'Synové pak Samuelovi: Prvorozený Vasni a Abia.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 29, 'Synové Merari: Moholi, Lebni syn jeho, Semei syn jeho, Uza syn jeho,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 30, 'Sima syn jeho, Aggia syn jeho, Azaiáš syn jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 31, 'Tito jsou pak, kteréž ustanovil David k zpívání v domě Hospodinově, když tam postavena truhla,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 32, 'Kteříž přisluhovali před příbytkem stánku úmluvy zpíváním, dokudž neustavěl Šalomoun domu Hospodinova v Jeruzalémě, a stáli podlé pořádku svého v přisluhování svém.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 33, 'Tito jsou pak, kteříž stáli, i synové jejich, z synů Kahat: Héman kantor, syn Joele, syna Samuelova,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 34, 'Syna Elkánova, syna Jerochamova, syna Elielova, syna Tohu,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 35, 'Syna Sufova, syna Elkánova, syna Machatova, syna Amasai,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 36, 'Syna Elkánova, syna Joelova, syna Azariášova, syna Sofoniášova,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 37, 'Syna Tachatova, syna Assirova, syna Abiazafova, syna Chóre,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 38, 'Syna Izarova, syna Kahatova, syna Léví, syna Izraelova.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 39, 'A bratr jeho Azaf, kterýž stával po pravici jeho. Azaf pak byl syn Berechiáše, syna Simova,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 40, 'Syna Michaelova, syna Baaseiášova, syna Malkiášova,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 41, 'Syna Etni, syna Záry, syna Adaiova,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 42, 'Syna Etanova, syna Zimmova, syna Semeiova,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 43, 'Syna Jachatova, syna Gersomova, syna Léví.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 44, 'Synové pak Merari, bratří jejich, stávali po levici: Etan, syn Kísi, syna Abdova, syna Malluchova,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 45, 'Syna Chasabiášova, syna Amaziášova, syna Helkiášova,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 46, 'Syna Amzova, syna Bánova, syna Semerova,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 47, 'Syna Moholi, syna Musi, syna Merari, syna Léví.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 48, 'Bratří pak jejich Levítové jiní oddáni jsou ke všelikému přisluhování příbytku domu Božího.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 49, 'Ale Aron a synové jeho pálili na oltáři zápalu a na oltáři kadění, při všelikém přisluhování svatyně svatých, a k očišťování Izraele podlé všeho toho, jakož přikázal Mojžíš služebník Boží.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 50, 'Tito pak jsou synové Aronovi: Eleazar syn jeho, Fínes syn jeho, Abisua syn jeho,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 51, 'Bukki syn jeho, Uzi syn jeho, Zerachiáš syn jeho,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 52, 'Meraiot syn jeho, Amariáš syn jeho, Achitob syn jeho,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 53, 'Sádoch syn jeho, Achimaas syn jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 54, 'A tato obydlé jejich, po příbytcích jejich, v mezech jejich, synů Aronových po čeledi Kahatských; nebo jejich byl los.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 55, 'A protož dali jim Hebron v zemi Judské, a předměstí jeho vůkol něho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 56, 'Pole však městská a vsi jejich dali Kálefovi synu Jefonovu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 57, 'Synům pak Aronovým dali z měst Judských města útočišťná: Hebron a Lebno a předměstí jeho, a Jeter i Estemo a předměstí jeho,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 58, 'A Holon i předměstí jeho, a Dabir i předměstí jeho,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 59, 'Též Asan a předměstí jeho, a Betsemes a předměstí jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 60, 'Z pokolení pak Beniamin: Gaba a předměstí jeho, a Allemet i předměstí jeho, i Anatot a předměstí jeho, všech měst jejich třinácte měst po čeledech jejich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 61, 'Synům též Kahatovým ostatním z čeledi toho pokolení dáno v polovici pokolení Manassesova losem měst deset.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 62, 'Synům pak Gersonovým po čeledech jejich v pokolení Izachar a v pokolení Asser, a v pokolení Neftalím, a v pokolení Manassesovu v Bázan měst třináct.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 63, 'Synům Merari po čeledech jejich v pokolení Ruben, a v pokolení Gád, a v pokolení Zabulon losem měst dvanáct.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 64, 'Dali synové Izraelští Levítům ta města a předměstí jejich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 65, 'A dali je losem v pokolení synů Judových, a v pokolení synů Simeonových, a v pokolení synů Beniaminových, města ta, kteráž jmenovali ze jména.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 66, 'A kteříž byli z čeledi synů Kahat, (byla pak města a hranice jejich v pokolení Efraimovu),');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 67, 'Těm dali města útočišťná: Sichem a předměstí jeho na hoře Efraim, a Gázer a předměstí jeho,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 68, 'A Jekmaam i předměstí jeho, a Betoron i předměstí jeho,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 69, 'Též i Aialon a předměstí jeho, a Getremmon s předměstím jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 70, 'A v polovici pokolení Manassesova: Aner a předměstí jeho, Balám a předměstí jeho, čeledem synů Kahat ostatním.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 71, 'Synům pak Gersonovým v čeledi polovice pokolení Manassesova dali Golan v Bázan s předměstím jeho, a Astarot i předměstí jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 72, 'V pokolení pak Izachar: Kádes s předměstím jeho, Daberet a předměstí jeho,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 73, 'Rámot také s předměstím jeho, a Anem i předměstí jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 74, 'V pokolení pak Asser: Masal s předměstím jeho, a Abdon i předměstí jeho,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 75, 'Též Hukok s předměstím jeho, Rohob také i předměstí jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 76, 'V pokolení pak Neftalímovu: Kádes v Galilei a předměstí jeho, Hamon a předměstí jeho, a Kariataim i předměstí jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 77, 'Synům Merari ostatním v pokolení Zabulonovu dali Remmon s předměstím jeho, Tábor a předměstí jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 78, 'A za Jordánem u Jericha, k východní straně Jordánu, v pokolení Rubenovu: Bozor na poušti s předměstím jeho, a Jasa i předměstí jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 79, 'Kedemot také s předměstím jeho, a Mefat i předměstí jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 80, 'V pokolení pak Gád: Rámot v Galád s předměstím jeho, a Mahanaim i předměstí jeho,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 81, 'I Ezebon s předměstím jeho, a Jazer i předměstí jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 1, 'Synové pak Izacharovi: Tola, Fua, Jasub a Simron, čtyři.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 2, 'Synové pak Tolovi: Uzi, Refaia, Jeriel, Jachmai, Jipsam, Samuel, knížata po domích otců jejich, pošlí od Toly, muži udatní v pokoleních svých. Počet jejich ve dnech Davidových byl dvamecítma tisíců a šest set.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 3, 'Synové Uzovi: Izrachiáš. Synové pak Izrachiášovi: Michael, Abdiáš, Joel a Isia, všech pět knížat.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 4, 'A s nimi v pokoleních jejich, po čeledech jejich otcovských, mužů válečných třidceti šest tisíců; nebo mnoho měli žen a synů.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 5, 'Bratří také jejich po všech čeledech Izachar, mužů udatných osmdesáte sedm tisíců, všech vyčtených.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 6, 'Synové Beniaminovi: Béla, Becher, Jediael, tři.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 7, 'Synové pak Bélovi: Ezbon, Uzi, Uziel, Jerimot a Iri, pět knížat čeledí otcovských, muži udatní; načteno jich dvamecítma tisíců, třidceti a čtyři.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 8, 'Potom synové Becherovi: Zemira, Joas, Eliezer, Elioenai, Amri, Jeremot, Abiáš, Anatot a Alemet, všickni synové Becherovi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 9, 'Kterýchž počet po pokoleních jejich, a po knížatech v domě čeledí otcovských, mužů udatných, dvadceti tisíců a dvě stě.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 10, 'Synové také Jediaelovi: Bilan. Synové pak Bilanovi: Jeus, Beniamin, Ahod, Kenan, Zetan, Tarsis a Achisachar.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 11, 'Všech těch synů Jediaelových po knížatech čeledí, mužů udatných, sedmnáct tisíc a dvě stě, vycházejících na vojnu k bitvě,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 12, 'Kromě Suppim a Chuppim, synů doma zrozených, a Chusim, synů vně zplozených.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 13, 'Synové Neftalímovi: Jasiel, Guni, Jezer a Sallum, synové Bály.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 14, 'Synové Manassesovi: Asriel, kteréhož mu manželka porodila. (Ženina též jeho Syrská porodila Machira, otce Galád.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 15, 'Machir pak vzal manželku Chuppimovu a Suppimovu, a jméno sestry jeho Maacha.) Jméno pak druhého Salfad, a měl Salfad dcery.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 16, 'Porodila pak Maacha manželka Machirova syna, kteréhož nazvala Fáres, a jméno bratra jeho Sáres, synové pak jeho Ulam a Rekem.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 17, 'Synové pak Ulamovi: Bedan. Tiť jsou synové Galád syna Machirova, syna Manassesova.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 18, 'Sestra pak jeho Molechet porodila Ishoda a Abiezera a Machla.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 19, 'Byli pak synové Semidovi: Achian, Sechem, Likchi a Aniam.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 20, 'Synové pak Efraimovi: Sutelach, a Bered syn jeho, Tachat syn jeho, Elada syn jeho, Tachat syn jeho,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 21, 'Též Zabad syn jeho, Sutelach syn jeho, Ezer a Elad. I zbili je muži Gát, kteříž zrozeni byli v zemi té; nebo sstoupili byli, aby zajali dobytky jejich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 22, 'Protož kvílil Efraim otec jejich za mnohé dny, a přišli bratří jeho, aby ho těšili.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 23, 'Potom všel k manželce své, kteráž počala a porodila syna, a nazval jméno jeho Beria, že byl v zámutku pro rodinu svou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 24, 'Dceru také Seeru, kteráž vystavěla Betoron dolní i horní, a Uzen Seera.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 25, 'A Refacha syna jeho, Resefa, Telecha, a Tachana syna jeho,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 26, 'Ladana syna jeho, Amiuda syna jeho, Elisama syna jeho,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 27, 'Non syna jeho, Jozue syna jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 28, 'Vládařství pak jejich a bydlení jejich Bethel s vesnicemi svými, a k východu Náran, a k západu Gázer a vesnice jeho, Sichem s vesnicemi svými, až do Gázy a vesnic jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 29, 'A v místech naproti synům Manassesovým: Betsan s vesnicemi svými, Tanach s vesnicemi svými, Mageddo s vesnicemi svými, Dor s vesnicemi svými. V těch bydlili synové Jozefa syna Izraelova.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 30, 'Synové Asser: Jemna, Jesua, Jesui, Beria, a Serach sestra jejich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 31, 'Synové pak Beriovi: Heber, Melchiel. Onť jest otec Birzavitův.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 32, 'Heber pak zplodil Jafleta, Somera, Chotama, a Suu sestru jejich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 33, 'Synové pak Jafletovi: Pasach, Bimhal, a Asvat. Ti jsou synové Jafletovi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 34, 'Synové pak Somerovi: Achi, Rohaga, Jehubba a Aram.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 35, 'Synové pak Helema, bratra jeho: Zofach, Jimna, Seles a Amal.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 36, 'Synové Zofachovi: Suach, Charnefer, Sual, Beri a Jimra,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 37, 'Bezer, Hod, Samma, Silsa, Jitran a Béra.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 38, 'Synové Jeterovi: Jefunne, Fispa a Ara.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 39, 'Synové pak Ulla: Arach, Haniel a Riziáš.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 40, 'Všickni ti synové Asser, knížata domů otcovských, vybraní, udatní, přední z knížat, kteříž vyčteni do vojska k bitvě, v počtu šest a dvadceti tisíc mužů.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 1, 'Beniamin pak zplodil Bélu, prvorozeného svého, Asbele druhého, Achracha třetího,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 2, 'Nocha čtvrtého, Rafa pátého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 3, 'Béla pak měl syny: Addara, Geru, Abiuda,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 4, 'Abisua, Námana, Achoacha,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 5, 'A Geru, Sefufana a Churama.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 6, 'Ti jsou synové Echudovi, ti jsou knížata čeledí otcovských, bydlících v Gabaa, kteříž je uvedli do Manáhat,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 7, 'Totiž: Náman, a Achia a Gera. On přestěhoval je; zplodil pak Uza a Achichuda.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 8, 'Sacharaim pak zplodil v krajině Moábské, když onen byl propustil je, s Chusimou a Bárou manželkami svými.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 9, 'Zplodil s Chodes manželkou svou Jobaba, Sebia, Mésa a Malkama,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 10, 'Jehuza, Sachia a Mirma. Ti jsou synové jeho, knížata čeledí otcovských.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 11, 'S Chusimou pak byl zplodil Abitoba a Elpále.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 12, 'Synové pak Elpálovi: Heber, Misam a Semer. Ten vystavěl Ono a Lod, i vsi jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 13, 'A Beria a Sema. Ti jsou knížata čeledí otcovských, bydlících v Aialon; ti zahnali obyvatele Gát.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 14, 'Achio pak, Sasák a Jeremot,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 15, 'Zebadiáš, Arad a Ader,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 16, 'Michael, Ispa a Jocha synové Beria.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 17, 'A Zebadiáš, Mesullam, Chiski, Heber,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 18, 'Ismerai, Izliáš a Jobab synové Elpálovi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 19, 'A Jakim, Zichri a Zabdi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 20, 'Elienai, Ziletai a Eliel,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 21, 'Adaiáš, Baraiáš a Simrat synové Simei.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 22, 'Ispan a Heber a Eliel,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 23, 'Abdon, Zichri a Chanan,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 24, 'Chananiáš, Elam a Anatotiáš,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 25, 'Ifdaiáš a Fanuel synové Sasákovi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 26, 'Samserai, Sechariáš a Ataliáš,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 27, 'Jaresiáš, Eliáš a Zichri synové Jerochamovi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 28, 'Ta jsou knížata otcovských čeledí po rodinách svých, kterážto knížata bydlila v Jeruzalémě.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 29, 'V Gabaon pak bydlilo kníže Gabaon, a jméno manželky jeho Maacha.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 30, 'A syn jeho prvorozený Abdon, Zur, Cis, Bál a Nádab,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 31, 'Ale Gedor, Achio, Zecher.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 32, 'A Miklot zplodil Simea. I ti také naproti bratřím svým bydlili v Jeruzalémě s bratřími svými.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 33, 'Ner pak zplodil Cisa, a Cis zplodil Saule. Saul pak zplodil Jonatu, Melchisua, Abinadaba a Ezbále.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 34, 'Syn pak Jonatův Meribbál, Meribbál pak zplodil Mícha.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 35, 'Synové pak Míchovi: Piton, Melech, Tarea a Achaz.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 36, 'Achaz pak zplodil Jehoadu, Jehoada pak zplodil Alemeta, Azmaveta a Zimru. Zimri pak zplodil Mozu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 37, 'Moza pak zplodil Bina. Ráfa syn jeho, Elasa syn jeho, Azel syn jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 38, 'Azel pak měl šest synů, jichž tato jsou jména: Azrikam, Bochru, Izmael, Seariáš a Abdiáš a Chanan. Všickni ti synové Azelovi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 39, 'Synové pak Ezeka, bratra jeho: Ulam prvorozený jeho, Jehus druhý, a Elifelet třetí.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 40, 'A byli synové Ulamovi muži udatní a střelci umělí, kteříž měli mnoho synů a vnuků až do sta a padesáti. Všickni ti byli z synů Beniaminových.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 1, 'A tak všickni Izraelští sečteni byli, a aj, zapsáni jsou v knize králů Izraelských a Judských, a přeneseni jsou do Babylona pro přestoupení své.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 2, 'Ti pak, kteříž bydlili prvé v vládařství svém v městech svých, totiž Izraelští, kněží, Levítové a Netinejští,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 3, 'Bydlili v Jeruzalémě, z synů Judových, z synů Beniaminových, ano i z synů Efraimových a Manassesových:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 4, 'Uttai syn Amiuda, syna Amri, syna Imri, syna Bani, z synů Fáresových, syna Judova.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 5, 'A z čeledi Silonovy: Azaiáš prvorozený a synové jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 6, 'A z synů Zerachových: Jehuel, a příbuzných jejich šest set a devadesát.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 7, 'Z synů pak Beniaminových: Sallu syn Mesullama, syna Hodavia, syna Hasenuova,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 8, 'A Ibneiáš syn Jerochamův, Ela syn Uzi, syna Michri, a Mesullam syn Sefatiáše, syna Rehuelova, syna Ibniášova.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 9, 'Bratří také jejich po pokoleních jejich, devět set padesáte a šest; všickni ti muži knížata čeledí po domích otců svých.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 10, 'Z kněží také Jedaiáš, Jehoiarib a Jachin,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 11, 'Azariáš syn Helkiáše, syna Mesullamova, syna Sádochova, syna Meraiotova, syna Achitobova, kníže v domě Božím.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 12, 'A Adaiáš syn Jerochama, syna Paschurova, syna Malchiášova, a Masai syn Adiele, syna Jachzery, syna Mesullamova, syna Mesillemitova, syna Immerova.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 13, 'A bratří jejich knížata po domích otců svých, tisíc sedm set a šedesát mužů udatných v práci přisluhování domu Božího.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 14, 'A z Levítů: Semaiáš syn Chasuba, syna Azrikamova, syna Chasabiášova, z synů Merari.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 15, 'A Bakbakar Cheres, a Galal, a Mataniáš syn Míchy, syna Zichri, syna Azafova.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 16, 'A Abdiáš syn Semaiáše, syna Galalova, syna Jedutunova, a Berechiáš syn Asy, syna Elkánova, kterýž přebýval ve vsech Netofatských.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 17, 'Též vrátní: Sallum a Akkub, a Talmon, Achiman, i bratří jejich, z nichž byl Sallum kníže.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 18, 'Kterýž až po dnes v bráně královské stával k východu, onino pak vrátnými byli po houfích synů Léví.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 19, 'Ale Sallum syn Chóre, syna Abiazafova, syna Chóre, a bratří jeho z domu otce jeho, Chorejští, nad pracemi přisluhování, ostříhali prahů při stánku, tak jako otcové jejich nad vojskem Hospodinovým, kteříž ostříhali vcházení.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 20, 'Nad kterýmiž Fínes syn Eleazarův byl někdy knížetem, a Hospodin byl s ním.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 21, 'Zachariáš pak syn Meselemiášův vrátným byl u dveří stánku úmluvy.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 22, 'Všickni ti voleni za vrátné k veřejím, osob dvě stě a dvanáct. Ti ve vsech svých vyčteni jsou, kteréž nařídil David a Samuel vidoucí, pro jejich věrnost,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 23, 'Aby oni i synové jejich byli při branách domu Hospodinova, v domě stánku po strážích.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 24, 'Po čtyřech stranách byli vrátní, k východu, k západu, k půlnoci a ku poledni.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 25, 'A bratří jejich, po vsech svých bydlící, aby každého sedmého dne časy svými přicházeli s nimi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 26, 'Nebo Levítové byli pod spravou těch čtyř předních vrátných, a byli nad komorami a nad poklady domu Božího,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 27, 'A aby vůkol domu Božího ponocovali; nebo jim poručena stráž, a otvírati každý den ráno.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 28, 'Z těch také ustaveni nad nádobami přisluhování; nebo v počtu vnášeli je, a v jistém počtu též vynášeli.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 29, 'Z nichž opět někteří postaveni byli nad nádobami jinými a nade všemi nádobami posvátnými, a nad bělí, vínem, olejem, kadidlem a vonnými věcmi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 30, 'Někteří také synové kněžští strojili masti z těch vonných věcí.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 31, 'Matatiáš pak z Levítů, prvorozený Salluma Choritského, správcí byl těch věcí, kteréž se na pánvi smažily.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 32, 'A z synů Kahat, z bratří jejich, byli ustanoveni nad chlebem předložení, aby jej připravovali na každou sobotu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 33, 'Z těch také byli zpěváci, přednější z čeledí otcovských mezi Levíty bydlíce, nejsouce zaměstknaní něčím jiným; nebo ve dne i v noci k své povinnosti státi musili.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 34, 'Ti jsou přední z čeledí otcovských mezi Levíty v čeledech svých, a ti přední jsouce, bydlili v Jeruzalémě.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 35, 'V Gabaon pak bydlili, otec Gabaonitských Jehiel, a jméno manželky jeho Maacha.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 36, 'Syn pak jeho prvorozený Abdon, Zur, Cis, Bál, Ner a Nádab.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 37, 'Ale Gedor, Achio, Zachariáš a Miklot,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 38, '(Miklot pak zplodil Simam), ti také naproti bratřím svým bydlili v Jeruzalémě s bratřími svými.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 39, 'Ner pak zplodil Cisa, a Cis zplodil Saule, Saul pak zplodil Jonatu, Melchisua, Abinadaba a Ezbále.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 40, 'Syn pak Jonatův Meribbál, a Meribbál zplodil Mícha.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 41, 'Synové pak Míchovi: Piton, Melech, Tarea.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 42, 'Achaz pak zplodil Járu, Jára pak zplodil Alemeta, Azmaveta a Zimri. Zimri pak zplodil Mozu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 43, 'Moza pak zplodil Bina. Refaiáš syn jeho, Elasa syn jeho, Azel syn jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 44, 'Azel pak měl šest synů, jichžto tato jsou jména: Azrikam, Bochru, Izmael, Seariáš, Abdiáš a Chanan. Ti jsou synové Azelovi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 10, 1, 'Když pak bojovali Filistinští s Izraelem, utíkali muži Izraelští před Filistinskými, a padli, zbiti jsouce na hoře Gelboe.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 10, 2, 'I stihali Filistinští Saule a syny jeho, a zabili Filistinští Jonatu, Abinadaba a Melchisua, syny Saulovy.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 10, 3, 'A když se zsilila bitva proti Saulovi, trefili na něj střelci s luky, a postřelen jest od střelců.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 10, 4, 'Protož řekl Saul oděnci svému: Vytrhni meč svůj a probodni mne jím, aby přijdouce ti neobřezanci, nečinili sobě ze mne posměchu. Ale nechtěl oděnec jeho, nebo se bál velmi. A pochytiv Saul meč, nalehl na něj.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 10, 5, 'Tedy vida oděnec jeho, že umřel Saul, nalehl i on na meč a umřel.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 10, 6, 'A tak umřel Saul i tři synové jeho, a všecka čeled jeho spolu zemřeli.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 10, 7, 'Když pak uzřeli všickni muži Izraelští, kteříž bydlili za tím údolím, že utekli Izraelští, a že zemřeli Saul i synové jeho, opustivše města svá, též utíkali. I přišli Filistinští a bydlili v nich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 10, 8, 'Potom nazejtří přišli Filistinští, aby zloupili pobité. I nalezli Saule a syny jeho, ležící na hoře Gelboe.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 10, 9, 'A svlékše ho, vzali hlavu jeho i odění jeho, a poslali po zemi Filistinské vůkol, aby to ohlášeno bylo modlám jejich i lidu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 10, 10, 'Složili také i odění jeho v chrámě boha svého, hlavu pak jeho přibili v chrámě Dágon.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 10, 11, 'Tedy uslyšavše všickni v Jábes Galád všecko, což učinili Filistinští Saulovi,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 10, 12, 'Zdvihli se všickni muži silní a vzali tělo Saulovo, a těla synů jeho, a přinesli je do Jábes. A pochovavše kosti jejich pod jedním dubem v Jábes, postili se sedm dní.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 10, 13, 'A tak umřel Saul pro přestoupení své, jímž byl přestoupil proti Hospodinu, totiž proti slovu Hospodinovu, jehož neostříhal, a že se také radil s duchem věštím, doptávaje se ho,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 10, 14, 'A nedoptával se Hospodina. Protož zabil jej, a přenesl království na Davida syna Izai.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 1, 'Nebo shromáždivše se všickni Izraelští k Davidovi do Hebronu, řekli: Aj, my kost tvá a tělo tvé jsme.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 2, 'Ano předešlých časů, když byl Saul králem, ty jsi vyvodil i přivodil Izraele, a nadto řekl Hospodin Bůh tvůj tobě: Ty pásti budeš lid můj Izraelský, a ty budeš vývoda nad lidem mým Izraelským.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 3, 'Přišli také všickni starší Izraelští k králi do Hebronu, a učinil s nimi David smlouvu v Hebronu před Hospodinem. I pomazali Davida za krále nad Izraelem, podlé slova Hospodinova skrze Samuele.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 4, 'Táhl pak David a všecken lid Izraelský k Jeruzalému, (jenž bylo Jebus, nebo tam byli Jebuzejští obyvatelé té země).');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 5, 'I mluvili obyvatelé Jebus Davidovi: Nevejdeš sem. Ale David vzal hrad Sion, to jest město Davidovo.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 6, 'Nebo byl řekl David: Kdož by koli nejprvé porazil Jebuzea, bude předním a knížetem. Protož vstoupil nejprvé Joáb syn Sarvie, a učiněn předním.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 7, 'Potom bydlil David na tom hradě, pročež nazvali jej městem Davidovým.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 8, 'I vystavěl město vůkol a vůkol, od Mello až do okolku, Joáb pak opravil ostatek města.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 9, 'A tak David čím dále tím více prospíval a rostl; nebo Hospodin zástupů byl s ním.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 10, 'Tito pak jsou přední z udatných, kteréž měl David, ježto se zmužile přičinili s ním o království jeho se vším Izraelem, aby ho za krále vyzdvihli podlé slova Hospodinova nad Izraelem.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 11, 'Tento jest počet silných, kteréž měl David: Jasobam syn Chachmonův, přední z vůdců. Ten pozdvihl kopí svého proti třem stům, a zbil je pojednou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 12, 'Po něm též Eleazar syn Dodi Achochitského. On byl jeden z těch tří udatných.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 13, 'Ten byl s Davidem v Pasdammim, když se Filistinští sebrali k boji. A byl tu díl rolí poseté ječmenem, a lid byl utekl před Filistinskými.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 14, 'I zastavili se u prostřed toho dílu, a obdrželi jej, porazivše Filistinské. A vysvobodil Hospodin lid vysvobozením velikým.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 15, 'Ti také tři ze třidcíti předních sstoupili k skále k Davidovi do jeskyně Adulam, když vojsko Filistinských leželo v údolí Refaim.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 16, '(Nebo David tehdáž bydlil v pevnosti své, a osazený lid Filistinských byl tehdáž u Betléma.)');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 17, 'Pohnul se pak David žádostí, a řekl: Ó by mi někdo dal píti vody z čisterny Betlémské, kteráž jest u brány.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 18, 'A protož probivše se ti tři skrze vojsko Filistinských, navážili vody z čisterny Betlémské, kteráž jest u brány, a nabravše, přinesli k Davidovi. David pak nechtěl jí píti, ale vylil ji v obět Hospodinu,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 19, 'A řekl: Nedejž mi toho, Bože můj, abych to učiniti měl. Zdali krev mužů těch píti budu, kteříž se opovážili života svého? Nebo s opovážením života svého přinesli ji. I nechtěl jí píti. To učinili ti tři silní.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 20, 'Potom Abizai bratr Joábův byl přední mezi třmi, a ten také pozdvihl kopí svého proti třem stům, i pobil je, a byl z těch tří nejslovoutnější.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 21, 'Z těch tří nad druhé dva jsa nejvzácnější, byl knížetem jejich, a však oněm prvním nebyl rovný.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 22, 'Banaiáš také syn Joiadův, syn muže udatného, velikých činů, z Kabsael, ten zabil dva reky Moábské. Tentýž sstoupiv, zabil lva v jámě, když byl sníh.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 23, 'Ten také zabil muže Egyptského zvýší pěti loket. A ačkoli měl Egyptský ten v ruce kopí, jako vratidlo tkadlcovské, však šel k němu s holí, a vytrh kopí z ruky Egyptského, zabil jej kopím jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 24, 'To učinil Banaiáš syn Joiadův, kterýž také slovoutný byl mezi těmi třmi silnými.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 25, 'A ač byl mezi třidcíti slavný, však oněm třem se nevrovnal. I ustanovil ho David nad drabanty svými.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 26, 'Udatní rytíři také i tito: Azael bratr Joábův, Elchanan syn Dodův Betlémský,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 27, 'Sammot Charodský, Chelez Pelonský,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 28, 'Híra syn Ikeš Tekoitský, Abiezer Anatotský,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 29, 'Sibbechai Chusatský, Ilai Achochský,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 30, 'Maharai Netofatský, Cheleb syn Baany Netofatský,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 31, 'Ittai syn Ribai z Gabaa synů Beniaminových, Banaiáš Faratonský,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 32, 'Churai od potoku Gás, Abiel Arbatský,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 33, 'Azmavet Bacharomský, Eliachba Salbonský,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 34, 'Synové Chasem Gizonského, Jonatan syn Sage Hararského,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 35, 'Achiam syn Sacharův Hararský, Elifal syn Urův,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 36, 'Hefer Mecheratský, Achiáš Pelonský,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 37, 'Chezro Karmelský, Narai syn Ezbai,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 38, 'Joel bratr Nátanův, Mibchar syn Geri,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 39, 'Zelek Ammonský, Nacharai Berotský, oděnec Joába syna Sarvie,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 40, 'Híra Itrejský, Gareb Itrejský,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 41, 'Uriáš Hetejský, Zabad syn Achlai,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 42, 'Adina syn Sizův Rubenský, kníže nad Rubenskými, a s ním jiných třidceti,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 43, 'Chanan syn Maachův, a Jozafat Mitnejský,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 44, 'Uziáš Asteratský, Sama a Johiel, synové Chotama Aroerského,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 45, 'Jediael, syn Simri, a Jocha bratr jeho Tizejský,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 46, 'Eliel Machavimský, a Jeribai a Josaviáš synové Elnámovi, a Itma Moábský,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 47, 'Eliel, a Obéd, a Jaasiel z Mezobaia.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 1, 'Tito pak jsou, kteříž přišli k Davidovi do Sicelechu, když se ještě kryl před Saulem synem Cis, a ti byli mezi udatnými, pomocníci boje,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 2, 'Nosíce lučiště, a bojujíce pravicí i levicí kamením i střelami z lučiště, a byli z bratří Saulových, z pokolení Beniaminova:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 3, 'Kníže Achiezer a Joas, synové Semmaa Gabatského, a Jeziel a Felet, synové Azmavetovi, Beracha, a Jéhu Anatotský,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 4, 'A Ismaiáš Gabaonitský, silný mezi třidcíti, kterýž byl nad třidcíti, Jeremiáš, Jachaziel, Jochanan a Jozabad Gederatský,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 5, 'A Eluzai, Jerimot, Bealiáš, Semariáš, a Sefatiáš Charufský,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 6, 'Elkána, Isiáš, Azareel, Joezer a Jasobam, Chorejští,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 7, 'A Joela a Zebadiáš synové Jerochamovi z Gedor.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 8, 'Též i z pokolení Gádova utekli k Davidovi k pevnosti na poušť, muži udatní, muži způsobní k boji, užívajíce štítu a pavézy, jichžto tváři jako tváři lvové, a podobní srnám na horách v rychlosti:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 9, 'Ezer první, Abdiáš druhý, Eliab třetí,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 10, 'Mismanna čtvrtý, Jeremiáš pátý,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 11, 'Attai šestý, Eliel sedmý,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 12, 'Jochanan osmý, Elzabad devátý,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 13, 'Jeremiáš desátý, Machbannai jedenáctý.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 14, 'Ti byli z synů Gádových, knížata vojska, jeden nad stem menší, a větší nad tisícem.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 15, 'Ti jsou, kteříž přepravili se přes Jordán měsíce prvního, ačkoli se byl vylil ze všech břehů svých, a zahnali všecky z údolí na východ i na západ.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 16, 'Přišli také někteří z synů Beniaminových a Judových k pevnosti Davidově.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 17, 'I vyšel jim David vstříc, a mluvě, řekl jim: Jestliže z příčiny pokoje jdete ke mně, abyste mi pomáhali, i mé srdce také s vámi se sjednotí; pakli k vyzrazení mne nepřátelům mým, (ješto není nepravosti při mně), popatřiž Bůh otců našich a tresci.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 18, 'Duch pak posilnil Amazu předního mezi hejtmany, i řekl: Tobě, ó Davide, a těm, jenž s tebou jsou, synu Izai, pokoj; pokoj tobě, pokoj i pomocníkům tvým. Toběť zajisté pomáhá Bůh tvůj. A tak přijal je David, a postavil je mezi knížaty houfů.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 19, 'Nadto i z pokolení Manassesova odstoupili k Davidovi, když táhl s Filistinskými k boji proti Saulovi, ale nepomáhali jim. Nebo uradivše se, propustili ho zase knížata Filistinská, řkouce: S nebezpečenstvím hrdel našich odstoupil by ku pánu svému Saulovi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 20, 'Takž když táhl do Sicelechu, odstoupili k němu někteří z pokolení Manassesova: Adnach, Jozabad, Jediael, Michael, Jozabad, Elihu, a Zilletai, hejtmané nad tisíci v pokolení Manassesovu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 21, 'Ti také pomáhali Davidovi s houfy jeho; nebo udatní byli všickni, pročež byli knížaty v jeho vojště.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 22, 'Anobrž každého dne přibývalo jich Davidovi ku pomoci, až bylo vojsko veliké, jako vojsko Boží.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 23, 'Tento pak jest počet vývod způsobných k boji, kteříž přišli k Davidovi do Hebronu, aby obrátili království Saulovo k němu podlé slova Hospodinova.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 24, 'Z synů Judových, nosících pavézy a kopí, šest tisíc a osm set způsobných k boji.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 25, 'Z synů Simeonových, udatných mužů k boji, sedm tisíc a sto.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 26, 'Z synů Léví čtyři tisíce a šest set.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 27, 'Joiada také vývoda synů Aronových, a s ním tři tisíce a sedm set.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 28, 'A Sádoch mládenec rek udatný, a z domu otce jeho knížat dvamecítma.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 29, 'A z synů Beniaminových, bratří Saulových tři tisíce; nebo ještě množství jiných drželi stráž domu Saulova.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 30, 'Z synů též Efraimových dvadceti tisíc a osm set. Ti byli rekové udatní, muži slovoutní v čeledech otců svých.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 31, 'Z polovice pak pokolení Manassesova osmnáct tisíc, kteříž vyčteni byli ze jména, aby přišli a ustanovili Davida za krále.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 32, 'Z synů také Izacharových, znajících a rozumějících časům, tak že věděli, co by měl činiti lid Izraelský, knížat jejich dvě stě, a všickni bratří jejich činili podlé rčení jejich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 33, 'Z synů Zabulon vycházejících na vojnu, vycvičených v bitvě všelijakými nástroji válečnými, padesáte tisíc, a ku potýkání se v šiku bez choulostivosti srdce.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 34, 'Z Neftalímova pak pokolení knížat tisíc, a s nimi pavézníků a kopidlníků třidceti a sedm tisíc.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 35, 'Z pokolení Dan, způsobných k boji, osm a dvadceti tisíc a šest set.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 36, 'A z pokolení Asserova, kteříž způsobní byli k boji, a umělí v šikování se k bitvě, čtyřidceti tisíc.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 37, 'A z Zajordání, totiž z Rubenských a Gádských, a z polovice pokolení Manassesova, přišli se všemi nástroji válečnými sto a dvadceti tisíc.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 38, 'Všickni ti muži bojovní, umělí v šiku, úmyslem upřímým přišli do Hebronu, aby ustanovili Davida za krále nade vším lidem Izraelským. Nýbrž i všickni ostatní Izraelští srdce jednoho byli, aby za krále ustanovili Davida.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 39, 'I byli tu s Davidem tři dni, jedouce a pijíce, nebo jim byli připravili bratří jejich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 40, 'Ano i ti, kteříž jim blízcí byli až k Izachar a Zabulon a Neftalím, přinášeli chleba na oslích a na velbloudích, i na mezcích a na volích, potravy, mouky, fíků a hroznů sušených, vína, oleje, volů, a ovcí v hojnosti. Nebo radost byla v lidu Izraelském.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 13, 1, 'David pak poradil se s hejtmany nad tisíci, s setníky a se všemi vývodami.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 13, 2, 'A řekl David všemu shromáždění Izraelskému: Jestliže se vám líbí, a jestli to od Hospodina Boha našeho, rozešleme posly k bratřím našim pozůstalým do všech zemí Izraelských, a též kněžím a Levítům do měst a předměstí jejich, a nechť se shromáždí k nám,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 13, 3, 'Abychom zase k nám přivezli truhlu Boha našeho; nebo jsme jí nehledali ve dnech Saulových.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 13, 4, 'I řeklo všecko množství, aby se tak stalo; nebo líbila se ta věc všemu lidu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 13, 5, 'Protož shromáždil David všecken lid Izraelský od Nílu Egyptského, až kudy se vchází do Emat, aby přivezli truhlu Hospodinovu z Kariatjeharim.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 13, 6, 'A tak vstoupil David a všecken lid Izraelský do Bála, v Kariatjeharim, kteréž jest v Judstvu, aby přenesli odtud truhlu Boha Hospodina, sedícího nad cherubíny, jehož se jméno vzývá.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 13, 7, 'I vstavili truhlu Boží na nový vůz, vzavše ji z domu Abinadabova, Uza pak a Achio spravovali vůz.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 13, 8, 'Ale David a všecken lid Izraelský hrali před Bohem ze vší síly, v zpěvích na harfy, na loutny, na bubny, na cymbály a na trouby.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 13, 9, 'A když přišli až k humnu Kídon, vztáhl Uza ruku svou, aby pozdržel truhly; nebo uchýlili se volové.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 13, 10, 'Protož rozhněval se Hospodin na Uzu a zabil jej, proto že vztáhl ruku svou k truhle; a umřel tu před Bohem.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 13, 11, 'Tedy zkormoutil se David, proto že se Hospodin tak přísně obořil na Uzu. I nazval to místo Perez Uza až do tohoto dne.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 13, 12, 'A boje se David Boha v ten den, řekl: Kterakž mám k sobě přivezti truhlu Boží?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 13, 13, 'Pročež nepřenesl David truhly k sobě do města Davidova, ale obrátil ji do domu Obededoma Gittejského.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 13, 14, 'I pozůstala truhla Boží mezi čeledí Obededomovou, v domě jeho za tři měsíce, a požehnal Hospodin domu Obededomovu a všem věcem jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 1, 'Potom poslal Chíram král Tyrský posly k Davidovi, a dříví cedrového a zedníky i tesaře, aby stavěli jemu dům.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 2, 'I poznal David, že ho potvrdil Hospodin za krále nad Izraelem, a že zvýšil království jeho pro lid svůj Izraelský.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 3, 'Pojal pak David ještě ženy v Jeruzalémě, a zplodil David více synů a dcer.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 4, 'A tato jsou jména těch, kteříž se jemu zrodili v Jeruzalémě: Sammua, Sobab, Nátan a Šalomoun,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 5, 'Též Ibchar, Elisua, Elfelet,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 6, 'Za tím Noga, Nefeg, Jafia,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 7, 'Elisama, Beeliada a Elifelet.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 8, 'V tom uslyšavše Filistinští, že by pomazán byl David za krále nade vším Izraelem, vytáhli všickni Filistinští hledati Davida. O čemž uslyšav David, vytáhl proti nim.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 9, 'Nebo když Filistinští přišli, a rozprostřeli se v údolí Refaim,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 10, 'Radil se David s Bohem, řka: Potáhnu-li proti Filistinským, a dáš-li je v ruku mou? Odpověděl jemu Hospodin: Táhni, a dám je v ruku tvou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 11, 'Tedy vtrhli do Balperazim. I porazil je tam David a řekl: Protrhlť jest Bůh nepřátely mé rukou mou, jako vody protrhují břehy. A protož nazváno jméno místa toho Balperazim.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 12, 'Nebo nechali tam bohů svých. I přikázal David, aby je spálili.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 13, 'Ale Filistinští sebravše se znovu, rozprostřeli se v tom údolí.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 14, 'Pročež David radil se opět s Bohem. I řekl jemu Bůh: Nepřistupuj k nim po zadu; odvrať se od nich, abys na ně trefil naproti moruším.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 15, 'A když uslyšíš, že šustí vrchové moruší, tedy vytáhneš k bitvě; nebo vyšel Bůh před tebou, aby porazil vojska Filistinská.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 16, 'I učinil David tak, jakž mu byl přikázal Bůh, a porazili vojska Filistinská od Gabaon až do Gázera.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 17, 'A tak rozešla se pověst o Davidovi do všech zemí, a způsobil Hospodin to, že se ho báli všickni národové.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 1, 'Když pak sobě nastavěl domů v městě Davidově, a připravil místo pro truhlu Boží, a roztáhl jí stánek,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 2, 'Tehdy řekl David: Nemáť nositi žádný truhly Boží kromě Levítů, ty zajisté vyvolil Hospodin, aby nosili truhlu Boží, a aby přisluhovali jemu až na věky.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 3, 'Protož shromáždil David všecken lid Izraelský do Jeruzaléma, aby přenesl truhlu Hospodinovu na místo její, kteréž jí byl připravil.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 4, 'Shromáždil také David syny Aronovy a Levíty.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 5, 'Z synů Kahat byli Uriel kníže, a bratří jeho sto a dvadceti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 6, 'Z synů Merari Asaiáš kníže, a bratří jeho dvě stě a dvadceti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 7, 'Z synů Gersomových Joel kníže, a bratří jeho sto a třidceti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 8, 'Z synů Elizafanových Semaiáš kníže, a bratří jeho dvě stě.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 9, 'Z synů Hebronových Eliel kníže, a bratří jeho osmdesát.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 10, 'Z synů Uzielových Aminadab kníže, a bratří jeho sto a dvanáct.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 11, 'Tedy povolal David Sádocha a Abiatara, kněží, též i Levítů: Uriele, Asaiáše, Joele, Semaiáše, Eliele a Aminadaba,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 12, 'A řekl jim: Vy jste přední z otcovských čeledí mezi Levíty, posvěťte sebe i bratří svých, abyste vnesli truhlu Hospodina Boha Izraelského tu, kdež jsem jí připravil.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 13, 'Nebo že spočátku ne vy jste spravovali toho, obořil se Hospodin Bůh náš na nás; nebo jsme ho nehledali náležitě.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 14, 'I posvětili se kněží i Levítové, aby přenesli truhlu Hospodina Boha Izraelského.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 15, 'A nesli synové Levítů truhlu Boží, jakož byl přikázal Mojžíš, podlé slova Hospodinova, na ramenou svých na sochořích.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 16, 'Řekl také David předním z Levítů, aby ustanovili z bratří svých zpěváky s nástroji muzickými, loutnami, harfami a cymbály, aby zvučeli, povyšujíce hlasu s radostí.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 17, 'Takž ustanovili Levítové Hémana syna Joelova, a z bratří jeho Azafa syna Berechiášova, a z synů Merari bratří jejich Etana syna Kusaiova.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 18, 'A s nimi bratří jejich z druhého pořádku: Zachariáše, Béna, Jaaziele, Semiramota, Jechiele, Unni, Eliaba, Benaiáše, Maaseiáše, Mattitiáše, Elifele, Mikneiáše, Obededoma a Jehiele, vrátné.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 19, 'Nebo zpěváci Héman, Azaf a Etan hrali hlasitě na cymbálích měděných,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 20, 'A Zachariáš, Aziel, Semiramot, Jechiel, Unni, Eliab, Maaseiáš a Benaiáš na loutnách, při zpěvu vysokém.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 21, 'A Mattitiáš, Elifele, Mikneiáš, Obededom, Jehiel a Azaziáš hrali na harfách při zpěvu nízkém.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 22, 'Chenaniáš pak, přední z Levítů nesoucích truhlu, spravoval, jak by nésti měli; nebo byl umělý.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 23, 'Berechiáš pak a Elkána byli vrátní u truhly.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 24, 'Sebaniáš také a Jozafat, Natanael, Amazai, Zachariáš, Benaiáš a Eliezer kněží, troubili na trouby před truhlou Boží; ale Obededom a Jechiáš byli též vrátní u truhly.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 25, 'A tak vypravil se David a starší Izraelští a hejtmané, aby přenesli truhlu smlouvy Hospodinovy z domu Obededomova s veselím.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 26, 'I stalo se, poněvadž Bůh pomáhal Levítům nesoucím truhlu smlouvy Hospodinovy, že obětovali sedm volů a sedm beranů.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 27, 'David pak odín byl pláštěm kmentovým, tolikéž všickni Levítové, kteříž nesli truhlu, i zpěváci, i Chenaniáš, správce nesoucích, mezi zpěváky. Měl také David na sobě efod lněný.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 28, 'Takž všecken lid Izraelský provázeli truhlu smlouvy Hospodinovy s plésáním a zvukem trouby, a pozaunů a cymbálů, a hrali na loutny a na harfy.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 29, 'Když pak truhla smlouvy Hospodinovy vcházela do města Davidova, Míkol dcera Saulova vyhlédla z okna, a viduci krále Davida poskakujícího a plésajícího, pohrdla jím v srdci svém.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 1, 'A když přinesli truhlu Boží a postavili ji u prostřed stánku, kterýž jí byl rozbil David, tedy obětovali oběti zápalné a oběti pokojné před Bohem.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 2, 'Zatím dokonav David obětování obětí zápalných a pokojných, dal požehnání lidu ve jménu Hospodinovu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 3, 'Rozdělil také všechněm mužům Izraelským, od muže až do ženy, jednomu každému po pecnu chleba a kusu masa, a vína láhvici.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 4, 'Potom postavil před truhlou Hospodinovou služebníky z Levítů k připomínání, k vyznávání a k chválení Hospodina Boha Izraelského.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 5, 'Azaf byl přední, a druhý po něm Zachariáš, Jehiel, Semiramot, Jechiel, Mattitiáš, Eliab, Benaiáš, Obededom a Jehiel. Ti na nástrojích, na loutnách a harfách, ale Azaf na cymbálích hral.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 6, 'Benaiáš pak a Jachaziel kněží s trubami byli ustavičně před truhlou smlouvy Boží.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 7, 'Teprv toho dne ponejprvé nařídil David, aby slaven byl Hospodin zpěvem tímto od Azafa a bratří jeho:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 8, 'Slavte Hospodina, zvěstujte jméno jeho, a oznamujte mezi národy skutky jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 9, 'Zpívejte a žalmy prozpěvujte jemu, rozmlouvejte o všech divných skutcích jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 10, 'Chlubte se v svatém jménu jeho, vesel se srdce těch, jenž hledají Hospodina.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 11, 'Hledejte Hospodina i síly jeho, hledejte tváři jeho ustavičně.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 12, 'Rozpomínejte se na divné skutky jeho, kteréž činil, na zázraky jeho, i na soudy úst jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 13, 'Ó símě Izraele, služebníka jeho, ó synové Jákobovi, vyvolení jeho,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 14, 'Onť jest Hospodin Bůh náš, na vší zemi soudové jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 15, 'Rozpomínejte se ustavičně na smlouvu jeho, na slovo, kteréž přikázal až do tisíce pokolení,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 16, 'Kterouž učinil s Abrahamem, a na přísahu jeho Izákovi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 17, 'A vystavil ji Jákobovi za ustanovení, Izraelovi za smlouvu věčnou,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 18, 'Pravě: Tobě dám zemi Kananejskou za provazec vládařství vašeho,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 19, 'Ačkoli vás byl malý počet, a maličko byli jste v ní pohostinu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 20, 'A přecházeli od národu do národu, a z království k jinému lidu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 21, 'Nedopustil žádnému ublížiti jim, ano i krále pro ně trestal, řka:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 22, 'Nedotýkejte se pomazaných mých, a prorokům mým nečiňte nic zlého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 23, 'Zpívejte Hospodinu všecka země, zvěstujte den po dni spasení jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 24, 'Vypravujte mezi pohany slávu jeho, a mezi všemi národy divy jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 25, 'Nebo veliký jest Hospodin, a chvalitebný náramně, hroznější nade všecky bohy.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 26, 'Všickni zajisté bohové národů jsou modly, Hospodin pak nebesa učinil.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 27, 'Sláva a jasnost před ním, síla a veselé na místě jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 28, 'Vzdejte Hospodinu čeledi národů, vzdejte Hospodinu slávu i moc.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 29, 'Vzdejte Hospodinu čest jména jeho, přineste dary a přiďte před oblíčej jeho, a sklánějte se před Hospodinem v okrase svatosti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 30, 'Bojte se oblíčeje jeho všickni obyvatelé země, a budeť upevněn okršlek země, aby se nepohnul.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 31, 'Veseliti se budou nebesa, a plésati bude země, a řeknou mezi pohany: Hospodin kraluje.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 32, 'Zvuk vydá moře, i což v něm jest, veseliti se bude pole i vše, což jest na něm.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 33, 'Tedy prozpěvovati bude dříví lesní před Hospodinem, neboť se béře, aby soudil zemi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 34, 'Oslavujte Hospodina, neb dobrý jest, nebo na věky milosrdenství jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 35, 'A rcete: Zachovej nás, Bože spasení našeho, a shromažď nás, a vytrhni nás z pohanů, abychom slavili svaté jméno tvé, a chlubili se v chvále tvé.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 36, 'Požehnaný Hospodin Bůh Izraelský od věků a až na věky. I řekl všecken lid: Amen, i Halelujah.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 37, 'I nechal tu David před truhlou smlouvy Hospodinovy Azafa a bratří jeho, aby přisluhovali před truhlou ustavičně podlé povinnosti dne každého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 38, 'Též i Obededoma s bratřími jejich, osob šedesáte osm, Obededoma, pravím, syna Jedutunova, a Chosi, aby vrátní byli.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 39, 'Sádocha také kněze a bratří jeho za kněží nechal před příbytkem Hospodinovým na výsosti, kteráž byla v Gabaon,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 40, 'Aby obětovali zápaly Hospodinu na oltáři zápalu ustavičně, ráno i večer, podlé všeho, což psáno jest v zákoně Hospodinově, jejž vydal Izraelovi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 41, 'A s nimi nechal Hémana a Jedutuna a jiných vybraných, kteříž vyčteni byli zejména, aby vzdávali chválu Hospodinu, proto že na věky trvá milosrdenství jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 42, 'Těm také, totiž Hémanovi a Jedutunovi, nechal trub a cymbálů, aby zvučeli, i jiných nástrojů muziky Boží, syny pak Jedutunovy postavil u vrat.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 43, 'A tak rozešel se všecken lid, jeden každý do domu svého; David též navrátil se, aby požehnání dal domu svému.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 1, 'I stalo se, když bydlil David v domě svém, že řekl Nátanovi proroku: Aj, já přebývám v domě cedrovém, truhla pak smlouvy Hospodinovy jest pod kortýnami.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 2, 'I řekl Nátan Davidovi: Cožkoli jest v srdci tvém, učiň; nebo Bůh s tebou jest.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 3, 'Potom té noci stalo se slovo Boží k Nátanovi, řkoucí:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 4, 'Jdi a rci Davidovi služebníku mému: Toto dí Hospodin: Ne ty stavěti mi budeš dům k bydlení,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 5, 'Poněvadž jsem nebydlil v žádném domě od toho dne, jakž jsem vyvedl syny Izraelské, až do dne tohoto, ale procházel jsem se z stánku do stánku, také i vně kromě příbytku.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 6, 'Nadto kudyž jsem koli chodil se vším Izraelem, zdali jsem slovo řekl kterému z soudců Izraelských, (jimž jsem přikázal, aby pásli lid můj), řka: Proč jste mi neustavěli domu cedrového?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 7, 'Protož nyní toto díš služebníku mému Davidovi: Takto praví Hospodin zástupů: Já jsem tě vzal z ovčince, když jsi chodil za stádem, abys byl vývodou lidu mého Izraelského.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 8, 'A býval jsem s tebou všudy, kamž jsi koli se obrátil, všecky také nepřátely tvé vyhladil jsem před tváří tvou, a učinilť jsem jméno veliké, jako jméno vznešených na zemi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 9, 'Ano i lidu svému Izraelskému způsobil jsem místo, a vštípil jej tu. I bude bydliti na místě svém, a nepohne se více, aniž na něj dotírati budou lidé nešlechetní, jako prvé,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 10, 'Hned od toho času, jakž jsem ustanovil soudce nad lidem svým Izraelským, až jsem ponížil všech nepřátel tvých; nýbrž oznamujiť, že Hospodin sám vystaví tobě dům.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 11, 'Nebo když se vyplní dnové tvoji, abys šel za otci svými, vzbudím símě tvé po tobě, kteréž bude z synů tvých, a utvrdím království jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 12, 'Onť mi ustaví dům, a já utvrdím trůn jeho až na věky.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 13, 'Já budu jemu otcem, a on mi bude synem, a milosrdenství svého neodejmu od něho, jako jsem je odjal od toho, kterýž byl před tebou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 14, 'Ale postavím jej v domě svém a v království svém až na věky, a trůn jeho bude nepohnutelný až na věky.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 15, 'Podlé všech slov těchto, a podlé všeho vidění tohoto, tak mluvil Nátan Davidovi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 16, 'Tedy všed král David, posadil se před Hospodinem, a řekl: Kdož jsem já, ó Hospodine Bože, a jaký jest dům můj, že jsi mne tak zvýšil?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 17, 'Anobrž i to jsi za málo u sebe položil, ó Bože, pročež jsi zamluvil se o domu služebníka svého i na dlouhé časy, a popatřil jsi na mne, jako na osobu člověka vzácného, Hospodine Bože.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 18, 'Což ještě více mluviti má David před tebou o zvelebení služebníka tvého? Ty zajisté znáš služebníka svého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 19, 'Hospodine, pro služebníka svého a podlé srdce svého činíš velikou věc tuto, abys v známost uvedl všecky převeliké věci.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 20, 'Hospodine, neníť tobě rovného, anobrž není žádného Boha kromě tebe, podlé toho všeho, jakž jsme slýchali ušima svýma.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 21, 'Nebo kde jest který národ na zemi, jako lid tvůj Izraelský, jehož by Bůh šel, aby vykoupil sobě lid a dobyl sobě jména, čině veliké a hrozné věci, vyháněje před tváří lidu svého, kterýž jsi vykoupil z Egypta, pohany?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 22, 'Zvolil jsi zajisté lid svůj Izraelský sobě za lid až na věky, a ty, Hospodine, sám jsi jejich Bohem.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 23, 'Nyní tedy, Hospodine, slovo to, jímž jsi zamluvil se služebníku svému a domu jeho, budiž jisté až na věky, a učiň tak, jakž jsi mluvil.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 24, 'Budiž, pravím, jisté, tak aby velebeno bylo jméno tvé až na věky, a říkáno: Hospodin zástupů, Bůh Izraelský, jest Bůh nad Izraelem, a dům Davida služebníka tvého ať jest nepohnutelný před oblíčejem tvým.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 25, 'Nebo ty, Bože můj, zjevil jsi služebníku svému, že mu ustavíš dům, a protož směl služebník tvůj modliti se před tebou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 26, 'A tak, ó Hospodine, ty jsi sám Bůh, a mluvil jsi o služebníku svém dobré věci tyto.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 27, 'Nyní tedy ráčil jsi požehnati domu služebníka svého, aby trval na věky před oblíčejem tvým; nebo jsi ty, Hospodine, požehnal, i budeť požehnaný na věky.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 1, 'Stalo se potom, že porazil David Filistinské, a zemdlil je, a vzal Gát i vesnice jeho z ruky Filistinských.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 2, 'Porazil také i Moábské, a učiněni jsou Moábští služebníci Davidovi, a dávali jemu plat.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 3, 'Porazil též David Hadarezera krále Soba v Emat, když byl vytáhl, aby opanoval řeku Eufrates.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 4, 'A pobral mu David tisíc vozů, a sedm tisíc jízdných, a dvadceti tisíc mužů pěších, a zpodřezoval David žily všechněm koňům vozníkům. Toliko zanechal z nich ke stu vozům.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 5, 'Přitáhli pak byli Syrští od Damašku na pomoc Hadarezerovi králi Soba, ale David porazil z Syrských dvamecítma tisíc mužů.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 6, 'Tedy osadil David Syrii Damašskou. I učiněni jsou Syrští služebníci Davidovi, dávajíce plat; nebo zachovával Hospodin Davida, kamž se koli obrátil.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 7, 'Pobral také David štíty zlaté, kteréž měli služebníci Hadarezerovi, a přinesl je do Jeruzaléma.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 8, 'Z Tibchat též a z Chun, měst Hadarezerových, nabral David mědi velmi mnoho, z kteréž potom slil Šalomoun moře měděné, a sloupy i nádobí měděné.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 9, 'A když uslyšel Tohu král Emat, že porazil David všecko vojsko Hadarezera krále Soba,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 10, 'Poslal Adorama syna svého k králi Davidovi, aby ho pozdravil přátelsky, a spolu se s ním radoval z toho, že bojoval s Hadarezerem, a porazil ho; (nebo válčil Tohu s Hadarezerem). Kterýžto přinesl všelijaké nádoby zlaté a stříbrné i měděné.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 11, 'Ty také obětoval král David Hospodinu s stříbrem a zlatem, kteréhož byl nabral ze všech národů, z Idumejských, z Moábských, z synů Ammon, z Filistinských, i z Amalechitských.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 12, 'Abizai také syn Sarvie porazil Idumejských v údolí solnatém osmnácte tisíc.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 13, 'Protož i nad Idumejskými postavil stráž, a učiněni jsou všickni Idumejští služebníci Davidovi; nebo zachovával Hospodin Davida, kamž se koli obrátil.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 14, 'A tak kraloval David nade vším Izraelem, a činil soud a spravedlnost všemu lidu svému.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 15, 'Joáb pak syn Sarvie byl nad vojskem, a Jozafat syn Achiludův byl kancléřem.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 16, 'Sádoch také syn Achitobův a Abimelech syn Abiatarův byli kněžími, a Susa byl písařem.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 17, 'Banaiáš pak syn Joiadův byl nad Cheretejskými a Peletejskými, a synové Davidovi knížaty při králi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 1, 'Stalo se zatím, že umřel Náhas král Ammonitský, a kraloval syn jeho místo něho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 2, 'I řekl David: Učiním milosrdenství s Chanunem synem Náhasovým, nebo učinil otec jeho milosrdenství nade mnou. Tedy poslal David posly, aby ho potěšili pro otce jeho. I přišli služebníci Davidovi do země synů Ammon k Chanunovi, aby ho těšili.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 3, 'Tedy řekla knížata Ammonitská Chanunovi: Cožť se zdá, že David činí poctivost otci tvému, že poslal k tobě, kteříž by tě potěšili? Zdali ne proto, aby shlédli a vyšpehovali, i podvrátili zemi tuto, přišli služebníci jeho k tobě?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 4, 'Pročež Chanun vzav služebníky Davidovy, oholil je a zustřihoval roucha jejich polovici až do rozkroků, a propustil je.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 5, 'Tedy odešli někteří, a oznámili Davidovi o těch mužích. I poslal proti nim, (nebo byli muži ti zlehčeni velice), a rozkázal jim král: Pobuďte v Jerichu, dokudž neobrostou brady vaše; potom se navrátíte.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 6, 'Vidouce pak Ammonitští, že se zošklivili Davidovi, poslal Chanun a synové Ammon tisíc hřiven stříbra, aby sobě najali ze mzdy z Mezopotamie a z Syrie Maacha a z Soba vozů a jezdců.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 7, 'A najali sobě ze mzdy třidceti a dva tisíce vozů, a krále Maachu i lid jeho. Kteřížto přitáhše, položili se s vojskem naproti Medaba. Ammonitští také shromáždivše se z měst svých, přitáhli k té bitvě.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 8, 'Což uslyšav David, poslal Joába se vším vojskem udatných.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 9, 'A tak vytáhše Ammonitští, sšikovali se k boji u brány města toho. Králové pak, kteříž byli přitáhli, byli zvláště na poli.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 10, 'A protož vida Joáb proti sobě sšikovaný lid z předu i z zadu, vybrav některé ze všech výborných Izraelských, sšikoval je také proti Syrským.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 11, 'Ostatek pak lidu dal pod správu Abizaie bratra svého, a sšikovali se proti Ammonitským.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 12, 'I řekl Joáb: Jestliže Syrští budou mne silnější, přispěješ mi na pomoc; pakli Ammonitští silnější budou tebe, já pomohu tobě.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 13, 'Posiliž se, a zmužile se mějme, bojujíce za lid náš a za města Boha našeho, Hospodin však, což mu se dobře líbí, nechť učiní.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 14, 'Takž přistoupil Joáb i lid, kterýž při něm byl, k bitvě proti Syrským. Ale oni utekli před ním.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 15, 'V tom Ammonitští vidouce, že utíkají Syrští, utekli také i oni před Abizaiem bratrem jeho, a ušli do města. Joáb též navrátil se do Jeruzaléma.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 16, 'A tak vidouce Syrští, že jsou poraženi od Izraelských, poslali posly, a vyvedli Syrské, kteříž bydlejí za řekou, a Sofach kníže vojska Hadarezerova vedl je.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 17, 'I oznámeno to Davidovi. Kterýžto shromáždiv všecken lid Izraelský, přepravil se přes Jordán, a přitáhl k nim, a sšikoval vojsko proti nim. A když sšikoval David vojsko proti Syrským k bitvě, bojovali s ním.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 18, 'Tedy utekli Syrští před Izraelem. I porazil David z Syrských sedm tisíc vozů, a čtyřidceti tisíc lidu pěšího, až i Sofacha hejtmana vojska toho zabil.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 19, 'Pročež když viděli služebníci Hadarezerovi, že jsou poraženi od Izraele, vešli v pokoj s Davidem, a sloužili jemu. A nechtěli více Syrští táhnouti na pomoc Ammonitským.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 20, 1, 'I stalo se po roce, když králové vyjíždívají na vojnu, že vedl Joáb lid válečný, a hubil zemi synů Ammon. A když přitáhl, oblehl Rabbu; (ale David zůstal v Jeruzalémě). I dobyl Joáb Rabby, a rozbořil ji.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 20, 2, 'Tedy sňal David korunu krále jejich s hlavy jeho, a našel, že vážila hřivnu zlata. A bylo v ní kamení drahé, i vstavena byla na hlavu Davidovu. Vyvezl též kořisti města velmi veliké.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 20, 3, 'Lid pak, kterýž v něm byl, vyvedl, a dal je pod pily a brány železné i sekery. A tak učinil David všechněm městům Ammonitským. I navrátil se David se vším lidem do Jeruzaléma.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 20, 4, 'Potom pak když trvala válka v Gázer s Filistinskými, tehdy zabil Sibbechai Chusatský Sippaje, kterýž byl zplozený z obrů, i sníženi jsou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 20, 5, 'Byla ještě i jiná válka s Filistinskými, kdežto zabil Elchanan, syn Jairův, Lachmi bratra Goliáše Gittejského, u jehož kopí bylo dřevo jako vratidlo tkadlcovské.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 20, 6, 'Opět byla jiná válka v Gát, a byl tam muž veliké postavy, kterýž měl po šesti prstech, všech čtyřmecítma, a byl i on zplozený z téhož obra.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 20, 7, 'Ten když haněl Izraele, zabil ho Jonata syn Semmaa, bratra Davidova.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 20, 8, 'Ti byli synové jednoho obra v Gát, kteříž padli od ruky Davidovy a od ruky služebníků jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 1, 'Satan pak povstal proti Izraelovi, a ponukl Davida, aby sečtl lid Izraelský.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 2, 'Protož řekl David Joábovi a knížatům lidu: Jděte, sečtěte lid Izraelský od Bersabé až do Dan, a oznamte mi, abych věděl počet jich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 3, 'Ale Joáb řekl: Přidejž Hospodin lidu svého, což ho koli, stokrát více. I zdaliž, pane můj králi, nejsou všickni oni pána mého služebníci? Proč toho vyhledává pán můj? Proč má býti uvedena pokléska na Izraele?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 4, 'Ale řeč královská přemohla Joába. A tak vyšed Joáb, prošel všecken lid Izraelský; potom navrátil se do Jeruzaléma.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 5, 'I dal Joáb počet lidu sečteného Davidovi. A bylo všeho lidu Izraelského jedenáctekrát sto tisíc mužů bojovných, lidu pak Judského čtyřikrát sto tisíc, a sedmdesáte tisíc mužů bojovných.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 6, 'Pokolení pak Léví a Beniaminova nepočítal mezi ně; nebo v ošklivosti měl Joáb rozkázaní královo.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 7, 'Ovšem nelíbila se Bohu ta věc, protož ranil Izraele.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 8, 'I řekl David Bohu: Zhřešil jsem těžce, že jsem to učinil, ale nyní odejmi, prosím, nepravost služebníka svého, nebo jsem velmi bláznivě učinil.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 9, 'V tom mluvil Hospodin k Gádovi, proroku Davidovu, řka:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 10, 'Jdi a rci Davidovi: Toto praví Hospodin: Trojíť věci podávám, vyvol sobě jednu z nich, kteroužť bych učinil.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 11, 'Tedy přišel Gád k Davidovi a řekl jemu: Toto praví Hospodin: Vol sobě,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 12, 'Buďto hlad za tři léta, buď abys za tři měsíce kažen byl od protivníků svých, když by meč nepřátel tvých dotekl se tebe, aneb aby za tři dni meč Hospodinův a mor byl v zemi, a anděl Hospodinův aby hubil po všech končinách Izraelských. Již tedy viz, co mám odpovědíti tomu, kterýž mne poslal.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 13, 'I řekl David Gádovi: Úzko mi náramně; nechť prosím, upadnu v ruce Hospodinovy, neboť jsou mnohá slitování jeho, jediné ať v ruce lidské neupadám.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 14, 'A tak uvedl Hospodin mor na lid Izraelský, a padlo jich z Izraele sedmdesáte tisíc mužů.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 15, 'Poslal také Bůh anděla i na Jeruzalém, aby hubil jej. A když hubil, popatřil Hospodin, a zželelo mu se toho zlého. I řekl andělu, kterýž hubil: Dostiť jest, zdrž ruku svou. Anděl pak stál podlé humna Ornana Jebuzejského.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 16, 'Mezi tím pozdvih David očí svých, uzřel anděla Hospodinova, stojícího mezi zemí a nebem, a meč dobytý v ruce jeho, vztažený proti Jeruzalému. I padl David, ano i starší, odíni jsouce žíněmi, na tváři své.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 17, 'A řekl David Bohu: Zdaliž jsem já nerozkázal čísti lidu? A jáť jsem sám ten, kterýž jsem zhřešil, a převelmi jsem zle učinil, tyto pak ovce co učinily? Hospodine, Bože můj, nechť jest, prosím, ruka tvá proti mně, a proti domu otce mého, ale proti lidu tvému nechť není rána.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 18, 'Zatím anděl Hospodinův mluvil k Gádovi, aby řekl Davidovi, aby vstoupě, vzdělal oltář Hospodinu na humně Ornana Jebuzejského.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 19, 'I vstoupil David podlé řeči Gádovy, kterouž byl mluvil ve jménu Hospodinovu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 20, 'A obrátiv se Ornan, uzřel toho anděla, a čtyři synové jeho s ním skryli se. Ornan pak mlátil pšenici.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 21, 'V tom přišel David k Ornanovi. A pohleděv Ornan, uzřel Davida, a vyšed z humna toho, klaněl se Davidovi až k zemi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 22, 'Tedy řekl David Ornanovi: Dej mi to místo humna, ať vzdělám na něm oltář Hospodinu; za slušné peníze dej mi je, i přestane rána v lidu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 23, 'I řekl Ornan Davidovi: Nechť sobě vezme, a učiní pán můj král, což se mu za dobré vidí. Hle, přidám i voly tyto k oběti zápalné, a smyky na drva, i pšenici k oběti suché, to všecko dávám.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 24, 'Král pak David řekl Ornanovi: Nikoli, ale raději koupím je od tebe za slušné peníze; neboť nevezmu, což tvého jest, Hospodinu, aniž budu obětovati oběti zápalné darem dané.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 25, 'I dal David Ornanovi za to místo zlata ztíží šesti set lotů.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 26, 'A vzdělal tu David oltář Hospodinu, a obětoval zápaly a oběti pokojné, a vzýval Hospodina. Kterýžto vyslyšel ho, spustiv oheň s nebe na oltář zápalu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 27, 'I řekl Hospodin andělu, aby obrátil meč svůj do pošvy jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 28, 'Toho času když uzřel David, že jej vyslyšel Hospodin na humně Ornana Jebuzejského, obětovával tu oběti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 29, 'Nebo stánek Hospodinův, kterýž byl učinil Mojžíš na poušti, a oltář k zápalu toho času byl na výsosti v Gabaon.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 30, 'David pak nemohl tam choditi k němu, aby hledal Boha, proto že se zhrozil meče anděla Hospodinova.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 1, 'I řekl David: Totoť jest místo domu Hospodina Boha, a toto jest místo oltáři k zápalu Izraelovi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 2, 'Protož přikázal David, aby shromáždili cizozemce přebývající v zemi Izraelské, a ustanovil z nich kameníky, aby tesali kamení k stavení domu Božího.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 3, 'Železa také mnoho na hřeby, a na dvéře k branám i k spojováním, připravil David, i mědi mnoho bez váhy.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 4, 'Též i dříví cedrového bez počtu; nebo přiváželi Sidonští a Tyrští dříví cedrového množství Davidovi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 5, 'Nebo řekl byl David: Šalomoun syn můj mládenček jest malý, dům pak vystaven býti má Hospodinu veliký, znamenitý a slovoutný po všech zemích, a protož připravím mu nyní potřeb. A tak připravil David množství toho před smrtí svou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 6, 'Potom povolav Šalomouna syna svého, přikázal mu, aby vystavěl dům Hospodinu Bohu Izraelskému.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 7, 'A řekl David Šalomounovi: Synu můj, uložil jsem byl v srdci svém vystavěti dům jménu Hospodina Boha svého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 8, 'Ale stala se ke mně řeč Hospodinova, řkoucí: Mnohou jsi krev vylil, a boje veliké jsi vedl; nebudeš stavěti domu jménu mému, proto že jsi mnoho krve vylil na zem přede mnou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 9, 'Aj, syn narodí se tobě, tenť bude muž pokojný. Odpočinutí zajisté dám jemu vůkol přede všemi nepřátely jeho, pročež Šalomoun slouti bude; nebo pokoj a odpočinutí dám Izraelovi za dnů jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 10, 'Onť ustaví dům jménu mému, a on bude mi za syna, a já jemu za otce, a upevním trůn království jeho nad Izraelem až na věky.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 11, 'Protož, synu můj, Hospodin bude s tebou, a šťastněť se povede, a vystavíš dům Hospodina Boha svého, jakož mluvil o tobě.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 12, 'A však dejž tobě Hospodin rozum a moudrost, a ustanoviž tě nad Izraelem, abys ostříhal zákona Hospodina Boha svého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 13, 'A tehdyť se šťastně povede, když ostříhati a činiti budeš ustanovení a soudy, kteréž přikázal Hospodin skrze Mojžíše lidu Izraelskému. Posilniž se a zmocni, neboj se, ani lekej.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 14, 'A aj, já v nevolech svých připravil jsem k domu Hospodinovu sto tisíců centnéřů zlata, a stříbra tisíc tisíců centnéřů, mědi pak a železa bez váhy; nebo toho mnoho jest. Dříví také i kamení připravil jsem, a k tomu ostatek přidáš.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 15, 'Přes to máš u sebe hojně dělníků, kameníků a zedníků, i tesařů i jiných zběhlých ve všelijakém díle.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 16, 'Zlata, stříbra, mědi a železa není počtu; snažiž se a dělej, a Hospodin budiž s tebou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 17, 'Přikázal také David všechněm knížatům Izraelským, aby pomáhali Šalomounovi synu jeho, řka:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 18, 'Zdaliž Hospodin Bůh váš není s vámi, kterýž vám způsobil vůkol a vůkol odpočinutí? Nebo dal v ruku mou obyvatele země této, a podmaněna jest země Hospodinu a lidu jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 19, 'Nyní tedy vydejte se srdcem svým a duší svou k hledání Hospodina Boha svého, a přičiníce se, vystavějte svatyni Hospodinu Bohu, abyste tam vnesli truhlu smlouvy Hospodinovy, a nádobí Bohu posvěcená do domu vystaveného jménu Hospodinovu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 1, 'Sstarav se pak David, a jsa pln dnů, ustanovil králem Šalomouna syna svého nad Izraelem,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 2, 'A shromáždil všecka knížata Izraelská, i kněží a Levíty.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 3, 'I sečteni jsou Levítové od třidcítiletých a výše, a byl počet jich, vedlé jmen a osob jejich, třidceti a osm tisíců.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 4, 'Z kterýchž postaveno bylo nad dílem domu Hospodinova čtyřmecítma tisíců, vladařů pak a soudců šest tisíců,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 5, 'A vrátných čtyři tisíce, a čtyři tisíce chválících Hospodina na nástrojích, kterýchž nadělal k chválení Boha.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 6, 'I nařídil David pořádku mezi syny Léví, totiž mezi syny Gerson, Kahat a Merari.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 7, 'Z Gersona byli Ladan a Semei.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 8, 'Synové Ladan: Kníže Jehiel, Zetam a Joel, ti tři.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 9, 'Synové Semei: Selomit, Oziel a Háran, ti tři. Ta jsou knížata otcovských čeledí Ladanských.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 10, 'Synové pak Semei: Jachat, Zina, Jehus a Beria. Ti čtyři jsou synové Semei.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 11, 'Byl pak Jachat kníže, a Ziza druhý, ale Jehus a Beria ne mnoho měli synů, a protož v čeledi otcovské za jedny byli počítáni.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 12, 'Synové Kahat: Amram, Izar, Hebron a Uziel, ti čtyři.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 13, 'Synové Amramovi: Aron a Mojžíš. Byl pak oddělen Aron, aby sloužil v svatyni svatých, on i synové jeho na věky, a aby kadili před Hospodinem, a sloužili jemu, i dobrořečili ve jménu jeho až na věky.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 14, 'Ale synové Mojžíše, muže Božího, počteni jsou v pokolení Léví.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 15, 'Synové Mojžíšovi: Gersom a Eliezer.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 16, 'Synové Gersomovi: Sebuel kníže.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 17, 'A synové Eliezerovi: Rechabiáš kníže. Neměl pak Eliezer více synů, ale synové Rechabiášovi rozmnožili se velmi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 18, 'Synové Izarovi: Selomit kníže.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 19, 'Synové Hebronovi: Jeriáš kníže, Amariáš druhé, Jachaziel třetí, a Jekmaam čtvrté.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 20, 'Synové Uzielovi: Mícha kníže, a Jezia druhý.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 21, 'Synové Merari: Moholi a Musi. Synové Moholi: Eleazar a Cis.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 22, 'Umřel pak Eleazar, a neměl synů, než toliko dcery, kteréž pojali synové Cis, bratří jejich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 23, 'Synové Musi: Moholi a Eder a Jerimot, ti tři.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 24, 'Ti jsou synové Léví po čeledech svých, knížata čeledí, kteříž vyčteni byli vedlé počtu jmen a osob, konající dílo v přisluhování domu Hospodinova od dvadcítiletých a výše.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 25, 'Nebo řekl David: Odpočinutí dal Hospodin Bůh Izraelský lidu svému, a bydliti bude v Jeruzalémě až na věky.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 26, 'Ano i Levítové nebudou více nositi stánku, ani kterých nádob jeho k přisluhování jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 27, 'A tak podlé nařízení Davidova nejposlednějšího byvše sečteni synové Léví, počna od dvadcítiletých a výše,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 28, 'Postaveni byli, aby byli ku pomoci synů Aronových, v přisluhování domu Hospodinova v síňcích, v pokojích a při očišťování všeliké věci svaté, i při práci služebnosti domu Božího,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 29, 'Též při chlebích posvátných, a při běli k obětem suchým, při koláčích přesných, a při pánvicích a rendlících, i při všeliké míře a měření,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 30, 'A aby stáli každého jitra k slavení a chválení Hospodina, tolikéž i u večer,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 31, 'A při všeliké oběti zápalů Hospodinových ve dny sobotní, a na novměsíce a v svátky výroční v jistém počtu, vedlé řádu jejich ustavičně před Hospodinem,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 32, 'A tak aby drželi stráž stánku úmluvy, a stráž svatyně, i stráž synů Aronových, bratří svých v službě domu Hospodinova.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 1, 'Synů pak Aronových tato jsou zpořádaní: Synové Aronovi: Nádab, Abiu, Eleazar a Itamar.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 2, 'Ale že umřel Nádab a Abiu před otcem svým, a neměli synů, protož konali úřad kněžský Eleazar a Itamar.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 3, 'Kteréž zpořádal David, totiž Sádocha z synů Eleazarových, a Achimelecha z synů Itamarových, vedlé počtu a řádu jejich v přisluhováních jejich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 4, 'Nalezeno pak synů Eleazarových více předních mužů, než synů Itamarových, a rozdělili je. Z synů Eleazarových bylo předních po domích otcovských šestnáct, a z synů Itamarových po čeledech otcovských osm.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 5, 'I rozděleni jsou losem jedni od druhých, ačkoli byli knížata nad věcmi svatými, a knížata Boží z synů Eleazarových a z synů Itamarových.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 6, 'I popsal je Semaiáš syn Natanaelův, písař z pokolení Léví před králem a knížaty, a Sádochem knězem a Achimelechem synem Abiatarovým i knížaty čeledí otcovských mezi kněžími a Levíty, tak že dům otcovský jeden zaznamenán Eleazarovi, tolikéž druhý zaznamenán Itamarovi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 7, 'Padl pak los první na Jehoiariba, na Jedaiáše druhý,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 8, 'Na Charima třetí, na Seorima čtvrtý,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 9, 'Na Malkiáše pátý, na Miamin šestý,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 10, 'Na Hakkoza sedmý, na Abiáše osmý,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 11, 'Na Jesua devátý, na Sechaniáše desátý,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 12, 'Na Eliasiba jedenáctý, na Jakima dvanáctý,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 13, 'Na Chuppa třináctý, na Jesebaba čtrnáctý,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 14, 'Na Bilgu patnáctý, na Immera šestnáctý,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 15, 'Na Chezira sedmnáctý, na Happizeza osmnáctý,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 16, 'Na Petachiáše devatenáctý, na Ezechiele dvadcátý,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 17, 'Na Jachina jedenmecítmý, na Gamule dvamecítmý,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 18, 'Na Delaiáše třimecítmý, na Maaseiáše čtyřmecítmý.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 19, 'Ti jsou, jenž zřízeni byli v přisluhováních svých, aby vcházeli do domu Hospodinova podlé řádu svého, pod spravou Arona otce jejich, jakož mu byl přikázal Hospodin Bůh Izraelský.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 20, 'Z synů Léví ostatních, z synů Amramových Subael, z synů Subael Jechdeiáš.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 21, 'Z Rechabiáše, z synů Rechabiášových kníže Iziáš.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 22, 'Z Izara Selomot, z synů Selomotových Jachat.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 23, 'Synové pak Jeriášovi: Amariáš druhý, Jachaziel třetí, Jekamam čtvrtý.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 24, 'Syn Uzielův Mícha, z synů Míchy Samir.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 25, 'Bratr Míchův Iziáš, a syn Iziášův Zachariáš.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 26, 'Synové Merari: Moholi a Musi, synové Jaaziášovi: Beno.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 27, 'Synové Merari z Jaaziáše: Beno, Soham, Zakur a Ibri.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 28, 'Z Moholi Eleazar, kterýž neměl synů.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 29, 'Z Cisa synové Cisovi: Jerachmeel.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 30, 'Synové pak Musi: Moholi, Eder a Jerimot. Ti jsou synové Levítů po domích otců svých.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 31, 'I ti také metali losy naproti bratřím svým, synům Aronovým, před Davidem králem, Sádochem a Achimelechem, i knížaty otcovských čeledí z kněží a Levítů, z čeledí otcovských, každý přednější naproti bratru svému mladšímu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 1, 'I oddělil David a knížata vojska k službě syny Azafovy a Hémanovy a Jedutunovy, kteříž by prorokovali při harfách, při loutnách a při cymbálích. Byl pak počet jejich, totiž mužů těch, jenž práci vedli v přisluhování svém,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 2, 'Z synů Azafových: Zakur, Jozef, Netaniáš a Asarela, synové Azafovi, pod spravou Azafovou byli, kterýž prorokoval k rozkazu královu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 3, 'Z Jedutuna synů Jedutunových bylo šest: Godoliáš, Zeri, Izaiáš, Chasabiáš, Mattitiáš a Simei, pod spravou otce jejich Jedutuna, kterýž prorokoval při harfě k slavení a chválení Hospodina.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 4, 'Z Hémana synové Hémanovi: Bukkiáš, Mataniáš, Uziel, Sebuel, Jerimot, Chananiáš, Chanani, Eliata, Giddalti, Romantiezer, Jazbekasa, Malloti, Hotir a Machaziot.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 5, 'Všickni ti synové Hémanovi, proroka králova v slovích Božských, k vyvyšování moci. A dal Bůh Hémanovi synů čtrnácte a dcery tři.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 6, 'Všickni ti byli pod spravou otce svého, při zpívání v domě Hospodinově na cymbálích, loutnách a harfách, k službě v domě Božím vedlé poručení králova Azafovi, Jedutunovi a Hémanovi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 7, 'Byl pak počet jich s bratřími jejich, těmi, kteříž byli vycvičení v zpěvích Hospodinových, všech mistrů dvě stě osmdesát osm.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 8, 'Tedy metali losy, houf držících stráž naproti druhému, jakž malý, tak veliký, mistr i učedlník.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 9, 'I padl první los v čeledi Azaf na Jozefa, na Godoliáše s bratřími a syny jeho druhý, jichž bylo dvanáct.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 10, 'Třetí na Zakura, synům jeho a bratřím jeho dvanácti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 11, 'Čtvrtý na Izara, synům jeho a bratřím jeho dvanácti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 12, 'Pátý na Netaniáše, synům jeho a bratřím jeho dvanácti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 13, 'Šestý na Bukkiáše, synům jeho a bratřím jeho dvanácti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 14, 'Sedmý na Jesarele, synům jeho a bratřím jeho dvanácti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 15, 'Osmý na Izaiáše, synům jeho a bratřím jeho dvanácti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 16, 'Devátý na Mataniáše, synům a bratřím jeho dvanácti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 17, 'Desátý na Simei, synům a bratřím jeho dvanácti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 18, 'Jedenáctý na Azarele, synům a bratřím jeho dvanácti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 19, 'Dvanáctý na Chasabiáše, synům a bratřím jeho dvanácti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 20, 'Třináctý na Subaele, synům a bratřím jeho dvanácti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 21, 'Čtrnáctý na Mattitiáše, synům a bratřím jeho dvanácti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 22, 'Patnáctý na Jerimota, synům a bratřím jeho dvanácti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 23, 'Šestnáctý na Chananiáše, synům a bratřím jeho dvanácti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 24, 'Sedmnáctý na Jazbekasa, synům a bratřím jeho dvanácti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 25, 'Osmnáctý na Chanani, synům a bratřím jeho dvanácti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 26, 'Devatenáctý na Malloti, synům a bratřím jeho dvanácti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 27, 'Dvadcátý na Eliatu, synům a bratřím jeho dvanácti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 28, 'Jedenmecítmý na Hotira, synům a bratřím jeho dvanácti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 29, 'Dvamecítmý na Giddalta, synům a bratřím jeho dvanácti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 30, 'Třimecítmý na Machaziota, synům a bratřím jeho dvanácti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 31, 'Čtyřmecítmý na Romantiezera, synům a bratřím jeho dvanácti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 1, 'Zpořádání pak vrátných takové bylo: Z Chorejských Meselemiáš syn Chóre, z synů Azafových.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 2, 'A z Meselemiášových synů: Zachariáš prvorozený, Jediael druhý, Zebadiáš třetí, Jatniel čtvrtý,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 3, 'Elam pátý, Jochanan šestý, Elioenai sedmý.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 4, 'A z Obededomových synů: Semaiáš prvorozený, Jozabad druhý, Joach třetí, Sachar čtvrtý a Natanael pátý,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 5, 'Amiel šestý, Izachar sedmý, Pehulletai osmý; nebo požehnal mu Bůh.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 6, 'Semaiášovi pak synu jeho zrodili se synové, kteříž panovali v domě otce svého; nebo muži udatní byli.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 7, 'Synové Semaiášovi: Otni a Refael, Obéd a Elzabad, jehož bratří byli muži udatní; též Elihu a Semachiáš.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 8, 'Všickni ti z potomků Obededomových, oni sami i synové jejich a bratří jejich, jeden každý muž udatný a způsobný k službě, šedesáte a dva všech z Obededoma.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 9, 'Též synů a bratří Meselemiášových, mužů silných, osmnáct.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 10, 'Z Chosových pak, kterýž byl z synů Merari, synové byli: Simri kníže. Ačkoli nebyl prvorozený, však postavil ho otec jeho za předního.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 11, 'Helkiáš druhý, Tebaliáš třetí, Zachariáš čtvrtý. Všech synů a bratří Chosových třinácte.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 12, 'Těm rozděleny jsou povinnosti, aby byli vrátnými po mužích předních, držíce stráž naproti bratřím svým při službě v domě Hospodinově.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 13, 'Nebo metali losy, jakož malý, tak veliký, po domích svých otcovských, k jedné každé bráně.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 14, 'I padl los k východu Selemiášovi. Zachariášovi také synu jeho, rádci opatrnému, uvrhli losy, i padl los jeho na půlnoci.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 15, 'Obededomovi pak na poledne, ale synům jeho na dům pokladů.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 16, 'Suppimovi a Chosovi na západ s branou Salléchet, na cestě podlážené vzhůru jdoucí. Stráž byla naproti stráži.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 17, 'K východu Levítů šest, k půlnoci na den čtyři, ku poledni na den čtyři, a při domě pokladů dva a dva,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 18, 'V straně zevnitřní k západu, po čtyřech k příkopu, po dvou k straně zevnitřní.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 19, 'Ta jsou zpořádání vrátných synů Chóre a synů Merari.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 20, 'Tito také Levítové: Achiáš byl nad poklady domu Božího, totiž nad poklady věcí posvátných.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 21, 'Z synů Ladanových synové Gersunských, z Ladana knížata otcovských čeledí, z Ladana totiž Gersunského Jechiel.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 22, 'Synové Jechielovi, Zetam a Joel bratr jeho, byli nad poklady domu Hospodinova.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 23, 'Z Amramských, z Izarských z Hebronských a z Ozielských.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 24, 'Sebuel pak syn Gersoma, syna Mojžíšova, přední nad poklady.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 25, 'Ale bratří jeho z Eliezera: Rechabiáš syn jeho, a Izaiáš syn jeho, a Joram syn jeho, a Zichri syn jeho, a Selomit syn jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 26, 'Ten Selomit a bratří jeho byli nade všemi poklady věcí posvátných, kterýchž byl posvětil David král a knížata čeledí otcovských, i hejtmané a setníci s vývodami vojska.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 27, 'Nebo z bojů a z kořistí obětovávali k opravě domu Hospodinova,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 28, 'A čehožkoli byl posvětil Samuel prorok, a Saul syn Cis, a Abner syn Nerův, a Joáb syn Sarvie. Kdokoli posvěcoval čeho, dával do rukou Selomita a bratří jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 29, 'Z Izarských Chenaniáš a synové jeho, nad dílem, kteréž vně děláno, byli v Izraeli za úředníky a soudce.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 30, 'Z Hebronských Chasabiáš a bratří jeho, mužů silných tisíc a sedm set bylo v přednosti nad Izraelem, za Jordánem k západu, ve všelikém díle Hospodinově a v službě královské.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 31, 'Mezi kterýmiž Hebronskými Jeriáš kníže byl nad Hebronskými v pokolení jejich, po čeledech otcovských; nebo léta čtyřidcátého kralování Davidova vyhledáváni byli, a nalezeni jsou mezi nimi muži udatní v Jazer Galádské,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 32, 'A bratří jeho, mužů silných, dva tisíce a sedm set, knížat otcovských čeledí. Kteréž ustanovil David král nad Rubenskými a Gádskými, a nad polovicí pokolení Manassesova, ve všech věcech Božských i věcech královských.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 1, 'Synové pak Izraelští podlé počtu svého, knížata čeledí otcovských a hejtmané a setníci a úředníci nad těmi, kteříž přisluhovali králi ve všech věcech jedni po druhých, vcházejíce a vycházejíce na každý měsíc, přes všecky měsíce roku: V jednom každém houfě bylo jich čtyřmecítma tisíců.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 2, 'Nad houfem prvním první měsíc byl Jasobam, syn Zabdielův, a v houfě jeho bylo čtyřmecítma tisíců.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 3, 'Z synů Fáresových bylo to kníže všech knížat nad vojsky, měsíce prvního.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 4, 'Zatím nad houfem na měsíc druhý byl Dodai Achochitský i s houfem svým, potom Miklot vývoda, a v houfě jeho čtyřmecítma tisíců.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 5, 'Kníže vojska třetího na třetí měsíc Banaiáš syn Joiady, nejvyššího kněze, a v houfě jeho čtyřmecítma tisíců.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 6, 'Ten Banaiáš byl silný mezi třidcíti a nad třidcíti, a v houfě jeho Amizabad syn jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 7, 'Čtvrtého houfu kníže na čtvrtý měsíc Azael, bratr Joábův, a Zebadiáš syn jeho po něm, a v houfě jeho čtyřmecítma tisíců.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 8, 'Pátého na pátý měsíc kníže Samhut Izrachitský, a v houfě jeho čtyřmecítma tisíců.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 9, 'Šestého na šestý měsíc Híra, syn Ikeše Tekoitského, a v houfě jeho čtyřmecítma tisíců.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 10, 'Sedmého na sedmý měsíc Chelez Pelonský z synů Efraimových, a v houfě jeho čtyřmecítma tisíců.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 11, 'Osmého na osmý měsíc Sibbechai Chusatský z Zarchejských, a v houfě jeho čtyřmecítma tisíců.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 12, 'Devátého na devátý měsíc Abiezer Anatotský z Beniaminských, a v houfě jeho čtyřmecítma tisíců.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 13, 'Desátého na měsíc desátý Maharai Netofatský z Zarchejských, a v houfě jeho čtyřmecítma tisíců.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 14, 'Jedenáctého na jedenáctý měsíc Banaiáš Faratonský z synů Efraimových, a v houfě jeho čtyřmecítma tisíců.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 15, 'Dvanáctého na dvanáctý měsíc Cheldai Netofatský z Otoniele, a v houfě jeho čtyřmecítma tisíců.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 16, 'Mimo to byli nad pokoleními Izraelskými, nad Rubenskými vývoda Eliezer syn Zichrův, nad Simeonskými Sefatiáš syn Maachův,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 17, 'Nad pokolením Léví Chasabiáš syn Kemuelův, nad Aronovým Sádoch,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 18, 'Nad Judovým Elihu z bratří Davidových, nad Izacharovým Amri syn Michaelův,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 19, 'Nad Zabulonovým Izmaiáš syn Abdiášův, nad Neftalímovým Jerimot syn Azrielův,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 20, 'Nad syny Efraimovými Ozeáš syn Azaziášův, nad polovicí pokolení Manasse Joel syn Pedaiášův,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 21, 'Nad druhou pak polovicí Manasse v Gálad Iddo syn Zachariášův, nad Beniaminovým Jaasiel syn Abnerův,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 22, 'Nad Danovým Azarel syn Jerochamův. Ta jsou knížata pokolení Izraelských.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 23, 'Nesečtl jich pak David všech od dvadcítiletých a níže; nebo byl řekl Hospodin, že rozmnoží Izraele jako hvězdy nebeské.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 24, 'A ačkoli Joáb syn Sarvie počal jich počítati, však nedokonal; nebo proto přišel hněv Boží na Izraele, aniž jest vložen počet ten v knihu o králi Davidovi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 25, 'Nad poklady pak královskými byl Azmavet syn Adielův, a nad důchody z polí, z měst a ze vsí i z zámků byl Jonatan syn Uziášův.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 26, 'A nad dělníky na poli, při dělání rolí, Ezri syn Chelubův.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 27, 'A nad vinicemi Semeiáš Ramatský, a nad úrodami z vinic i nad sklepy vinnými Zabdi Sifmejský.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 28, 'A nad olivovím a planým fíkovím, kteréž jest na polích, Baalchanan Gederský, a nad špižírnami olejnými Joas.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 29, 'A nad skoty, kteříž se pásli v Sáron, Sitrai Sáronský, a nad skoty v údolích Safat syn Adlai.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 30, 'A nad velbloudy Obil Izmaelský, nad oslicemi Jechdeiáš Meronotský,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 31, 'Nad bravy pak Jazim Agarejský. Všickni ti úředníci byli nad statkem krále Davida.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 32, 'Ale Jonatan strýc Davidův byl rada, muž rozumný a kancléř. On a Jechiel syn Chachmonův býval s syny královskými.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 33, 'Achitofel též rada králova, a Chusai Architský přítel králův.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 34, 'Po Achitofelovi potom byl Joiada syn Banaiášův, a Abiatar, a kníže vojska králova Joáb.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 1, 'Shromáždil pak David všecka knížata Izraelská, knížata jednoho každého pokolení, a knížata houfů sloužících králi, i hejtmany a setníky, i úředníky nade vším statkem a jměním královým i synů jeho s komorníky, i se všemi vzácnými a udatnými lidmi, do Jeruzaléma.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 2, 'A povstav David král na nohy své, řekl: Slyšte mne, bratří moji a lide můj. Já jsem uložil v srdci svém vystavěti dům k odpočinutí truhle úmluvy Hospodinovy, a ku podnoži noh Boha našeho, a připravil jsem byl potřeby k stavení.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 3, 'Ale Bůh mi řekl: Nebudeš stavěti domu jménu mému, proto že jsi muž válkami zaměstknaný a krev jsi vyléval.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 4, 'Vyvolil pak Hospodin Bůh Izraelský mne ze vší čeledi otce mého, abych byl králem nad Izraelem na věky; nebo z Judy vybral vývodu a z domu Judova čeled otce mého, a z synů otce mého mne ráčil za krále ustanoviti nade vším Izraelem.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 5, 'Tolikéž ze všech synů mých, (nebo mnoho synů dal mi Hospodin), vybral Šalomouna syna mého, aby seděl na stolici království Hospodinova nad Izraelem,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 6, 'A řekl mi: Šalomoun syn tvůj, ten mi vzdělá dům můj a síně mé; nebo jsem jej sobě zvolil za syna, a já budu jemu za otce.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 7, 'I utvrdím království jeho až na věky, bude-li stálý v ostříhání přikázaní mých a soudů mých, jako i nynějšího času.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 8, 'Nyní tedy při přítomnosti všeho Izraele, shromáždění Hospodinova, an slyší Bůh náš, napomínám vás: Zachovávejte a dotazujte se na všecka přikázaní Hospodina Boha svého, abyste vládli zemí dobrou, a v dědictví její uvedli i syny své po sobě až na věky.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 9, 'Ty také, Šalomoune, synu můj, znej Boha otce svého, a služ jemu celým srdcem a myslí ochotnou. Nebo všecka srdce zpytuje Hospodin a všeliká mysli tanutí zná. Budeš-li ho hledati, nalezneš jej; pakli ho opustíš, zavrže tě na věky.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 10, 'A tak viziž, že tě Hospodin zvolil, abys vystavěl dům svatyně; posilniž se a dělej.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 11, 'Dal pak David Šalomounovi synu svému formu síňce i pokojů jejích, a sklepů i paláců a komor jejích vnitřních, i domu pro slitovnici,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 12, 'A formu všeho toho, což byl složil v mysli své o síních domu Hospodinova, i o všech komorách vůkol chrámu pro poklady domu Božího, i pro poklady věcí posvátných,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 13, 'I pro houfy kněží a Levítů, a pro všecko dílo služby domu Hospodinova, a pro všecko nádobí k přisluhování v domě Hospodinově.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 14, 'Dal též zlata v jisté váze na nádobí zlaté, na všelijaké nádobí k jedné každé službě, též stříbra na všecky nádoby stříbrné v jisté váze na všelijaké nádobí k jedné každé službě,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 15, 'Totiž váhu na svícny zlaté, a lampy jejich zlaté podlé váhy jednoho každého svícnu i lamp jeho, na svícny pak stříbrné podlé váhy svícnu každého a lamp jeho, jakž potřebí bylo každému svícnu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 16, 'Zlata též váhu na stoly předložení na jeden každý stůl, i stříbra na stoly stříbrné,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 17, 'I na vidličky a na kotlíky, i na přikryvadla zlata ryzího, a na medenice zlaté váhu na jednu každou medenici, tolikéž na medenice stříbrné jistou váhu na jednu každou medenici.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 18, 'Také na oltář k kadění zlata ryzího váhu, zlata i k udělání vozů cherubínů, kteříž by roztaženými křídly zastírali truhlu úmluvy Hospodinovy.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 19, 'Všecko to skrze vypsání z ruky Hospodinovy mne došlo, kterýž mi to dal, abych vyrozuměl všemu dílu formy té.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 20, 'A tak řekl David Šalomounovi synu svému: Posilniž se a zmocni a dělej; neboj se, ani lekej. Nebo Hospodin Bůh, Bůh můj s tebou bude, nenecháť tebe samého, aniž tě opustí, až i dokonáno bude všecko dílo služby domu Hospodinova.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 21, 'Hle, i houfové kněží a Levítů ke všeliké službě domu Božího s tebou také budou při všelikém díle, jsouce všickni ochotní a prozřetelní v moudrosti při všeliké práci, knížata také i všecken lid ke všechněm slovům tvým.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 1, 'Potom řekl David král všemu shromáždění: Šalomouna syna mého jediného vyvolil Bůh ještě maličkého a mladého, dílo pak toto veliké jest; nebo ne člověku palác ten, ale Hospodinu Bohu býti má.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 2, 'Já zajisté podlé své nejvyšší možnosti nachystal jsem potřeb k domu Boha svého, zlata k nádobám zlatým, a stříbra k stříbrným, mědi k měděným, železa k železným a dříví k dřevěným, kamení onychinového i kamení k vsazování, i karbunkulového, a rozličných barev, a všelijakého kamení drahého, i kamení mramorového hojně.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 3, 'Nadto z veliké lásky k domu Boha svého, maje zvláštní poklad zlata a stříbra, i ten dávám k domu Boha svého mimo všecko to, což jsem připravil k domu svatyně,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 4, 'Totiž tři tisíce centnéřů zlata, zlata z Ofir, a sedm tisíc centnéřů stříbra přečištěného k potažení stěn domů svatých,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 5, 'Zlata k nádobám zlatým a stříbra k stříbrným i ke všelikému dílu řemeslnému. A jestliže jest kdo více, ješto by co chtěl dobrovolně obětovati dnes Hospodinu?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 6, 'Tedy knížata čeledí otcovských a knížata pokolení Izraelských, i hejtmané a setníci i úředníci nad dílem královským dobrovolně obětovali.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 7, 'A dali k službě domu Božího zlata pět tisíc centnéřů, a deset tisíc zlatých, stříbra pak deset tisíc centnéřů, a mědi osmnácte tisíc centnéřů, a železa sto tisíc centnéřů.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 8, 'Kdožkoli měli kamení drahé, dávali do pokladu domu Hospodinova do rukou Jechiele Gersunského.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 9, 'I veselil se lid, že tak ochotně obětovali; nebo celým srdcem dobrovolně obětovali Hospodinu. Nýbrž i král David radoval se radostí velikou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 10, 'A protož dobrořečil David Hospodinu před oblíčejem všeho shromáždění, a řekl David: Požehnaný jsi ty Hospodine, Bože Izraele otce našeho, od věků až na věky.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 11, 'Tváť jest, ó Hospodine, velebnost i moc i sláva, i vítězství i čest, ano i všecko, což jest v nebi i v zemi. Tvé jest, ó Hospodine, království, a ty jsi vyšší nad všelikou vrchnost.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 12, 'I bohatství i sláva od tebe jest, a ty panuješ nade vším, a v ruce tvé jest moc a síla, a v ruce tvé také jest i to, kohož chceš zvelebiti a upevniti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 13, 'Nyní tedy, Bože náš, děkujeme tobě, a chválíme jméno slávy tvé.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 14, 'Nebo kdo jsem já, a co jest lid můj, abychom mohli míti moc k tak dobrovolnému obětování tobě? Od tebeť jest zajisté všecko, a i to z ruky tvé dali jsme tobě.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 15, 'Nebo my příchozí jsme před tebou a hosté, jako i všickni otcové naši; dnové naši jsou jako stín běžící po zemi beze vší zástavy.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 16, 'Hospodine, Bože náš, všecka ta hojnost, kterouž jsme připravili k stavení domu tvého, jménu svatému tvému, z ruky tvé jest, a tvé jsou všecky věci.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 17, 'Známť pak, Bože můj, že ty zpytuješ srdce, a upřímnost oblibuješ; protož já z upřímnosti srdce svého ochotně obětoval jsem toto všecko. Ano i lid tvůj, kterýž se teď shledal, viděl jsem, jak s radostí chtivě obětuje tobě.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 18, 'Hospodine, Bože Abrahama, Izáka a Izraele, otců našich, zachovejž to na věky, totiž snažnost takovou srdce lidu svého, a nastrojuj srdce jejich sobě.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 19, 'Šalomounovi také synu mému dej srdce upřímé, aby ostříhal přikázaní tvých, svědectví tvých a ustanovení tvých, a aby činil všecko, a vystavěl dům ten, k němuž jsem potřeby připravil.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 20, 'Potom řekl David všemu shromáždění: Dobrořečte nyní Hospodinu Bohu svému. I dobrořečilo všecko shromáždění Hospodinu Bohu otců svých, a přisehnuvše hlavy, poklonili se Hospodinu i králi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 21, 'Zatím obětovali Hospodinu oběti, obětovali také zápaly Hospodinu nazejtří, volů tisíc, skopců tisíc, beranů tisíc, s mokrými obětmi jejich, a jiných obětí množství za všecken lid Izraelský.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 22, 'I jedli a pili před Hospodinem v ten den s radostí velikou. Potom za krále ustanovili po druhé Šalomouna syna Davidova, a pomazali jej Hospodinu za vývodu, a Sádocha za kněze.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 23, 'A tak dosedl Šalomoun na stolici Hospodinovu, aby byl králem místo Davida otce svého. I vedlo se mu šťastně, a poslouchal ho všecken Izrael.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 24, 'Tolikéž i všecka knížata a znamenití, i všickni synové krále Davida poddali se Šalomounovi králi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 25, 'I zvelebil Hospodin Šalomouna náramně před očima všeho Izraele, a dal mu slávu královskou, jakéž neměl před ním žádný král v Izraeli.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 26, 'Kraloval pak byl David syn Izai nade vším Izraelem.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 27, 'A dnů, v nichž kraloval David nad Izraelem, bylo čtyřidceti let. V Hebronu kraloval sedm let, a v Jeruzalémě kraloval třidceti a tři léta.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 28, 'I umřel v starosti dobré, pln jsa dnů, bohatství a slávy, a kraloval Šalomoun syn jeho místo něho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 29, 'Činové pak Davida krále první i poslední popsáni jsou v knize Samuele proroka, a v knize Nátana proroka, též v knize Gáda proroka,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 30, 'Se vším kralováním i silou jeho, i se všemi příběhy časů při něm i při lidu Izraelském, i při všech královstvích zemských.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 1, 'Když se pak zmocnil Šalomoun syn Davidův v království svém, a Hospodin Bůh jeho byl s ním, a zvelebil ho náramně:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 2, 'Tedy rozkázal Šalomoun všemu Izraelovi i hejtmanům, setníkům i soudcům, i všechněm knížatům nade vším Izraelem, i přednějším v čeledech otcovských.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 3, 'I bral se Šalomoun a všecko to shromáždění s ním na výsost, kteráž byla v Gabaon; nebo tam byl stánek shromáždění Božího, kterýž byl udělal Mojžíš služebník Hospodinův na poušti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 4, '(Truhlu pak Boží přivezl byl David z Kariatjeharim, připraviv jí místo; nebo byl rozbil jí stan v Jeruzalémě.)');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 5, 'A oltář měděný, kterýž byl udělal Bezeleel syn Uri, syna Hur, byl tam před stánkem Hospodinovým, kdež hledal ho Šalomoun i všecko to shromáždění.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 6, 'I obětoval tam Šalomoun před Hospodinem na oltáři měděném, kterýž byl před stánkem úmluvy, a obětoval na něm tisíc zápalů.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 7, 'Té noci ukázal se Bůh Šalomounovi, a řekl jemu: Žádej, zač chceš, a dám tobě.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 8, 'I řekl Šalomoun Bohu: Ty jsi učinil otci mému Davidovi milosrdenství veliké, mne jsi též ustanovil králem místo něho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 9, 'Již tedy, Hospodine Bože, budiž stálé slovo tvé mluvené s Davidem otcem mým; nebo ty jsi mne ustanovil za krále nad lidem tak mnohým, jako jest prachu zemského.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 10, 'Protož dej mi moudrost a umění, aťbych vycházeti mohl před lidem tímto i vcházeti. Nebo kdož by mohl souditi tento lid tvůj tak mnohý?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 11, 'Tedy odpověděl Bůh Šalomounovi: Proto že bylo to v srdci tvém, a nežádal jsi bohatství, ani zboží, ani slávy, ani bezživotí těch, jenž tebe nenávidí, aniž jsi také za dlouhý věk žádal, ale žádal jsi sobě moudrosti a umění, abys soudil lid můj, nad nímž jsem tě ustanovil za krále:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 12, 'Moudrost a umění dáno jest tobě, k čemužť přidám i bohatství a zboží, i slávy, tak že žádný z králů, kteříž byli před tebou, nebyl tobě rovný, aniž bude po tobě takového.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 13, 'I navrátil se Šalomoun s výsosti, kteráž byla v Gabaon, do Jeruzaléma, od stánku úmluvy, a tak kraloval nad Izraelem.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 14, 'Nashromáždil pak Šalomoun vozů a jezdců, a měl tisíc a čtyři sta vozů, a dvanácte tisíc jezdců, kteréž rozsadil do měst vozů, a při králi v Jeruzalémě.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 15, 'I složil král stříbra a zlata v Jeruzalémě jako kamení, a dříví cedrového jako planého fíkoví, kteréž roste v údolí u velikém množství.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 16, 'Přivodili také Šalomounovi koně z Egypta a koupě rozličné; nebo kupci královští brávali koupě rozličné za slušnou mzdu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 17, 'A vycházejíce, vodívali spřež vozníků z Egypta za šest set lotů stříbra, koně pak za půl druhého sta. A tak všechněm králům Hetejským i králům Syrským oni dodávali.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 1, 'A umíniv Šalomoun stavěti dům jménu Hospodinovu, a dům svůj královský,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 2, 'Odečtl Šalomoun sedmdesát tisíc nosičů a osmdesát tisíc těch, kteříž tesali na hoře, a úředníků nad nimi tři tisíce a šest set.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 3, 'Poslal také Šalomoun k Chíramovi králi Tyrskému, řka: Jakž jsi se choval k Davidovi otci mému, posílaje mu dříví cedrové, aby sobě stavěl dům k bydlení, tak čiň i mně.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 4, 'Nebo aj, já stavěti chci dům jménu Hospodina Boha svého, aby posvěcen byl jemu k tomu, aby se před ním kadilo vonnými věcmi, a k ustavičnému předkládání chlebů, i k zápalným obětem, ranním i večerním, ve dny sobotní a novoměsíčné, i na slavnosti Hospodina Boha našeho, což v Izraeli na věky trvati má.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 5, 'Dům pak, kterýž stavěti chci, veliký býti má; nebo Bůh náš větší jest nade všecky bohy.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 6, 'Ač kdo jest, ješto by mohl dům jemu vystavěti, poněvadž ho nebe i nebesa nebes obsáhnouti nemohou? Ano i já kdo jsem, abych jemu dům vystavěti měl, než toliko k tomu, aby se kadilo před ním?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 7, 'Protož nyní pošli mi muže umělého, kterýž by uměl dělati na zlatě, na stříbře, na mědi, na železe, i z zlatohlavu a z červce, a z postavce modrého, a kterýž by uměl řezati řezby s jinými umělými, kteříž jsou u mne v Judstvu a v Jeruzalémě, kteréž zjednal David otec můj.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 8, 'Přes to pošli mi také dříví cedrového a jedlového, a algumim z Libánu; nebo vím, že služebníci tvoji umějí sekati dříví Libánské. A hle, služebníci moji budou s služebníky tvými,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 9, 'Aby mi připravili dostatek dříví; nebo dům, kterýž já stavěti chci, veliký býti má a slavný.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 10, 'A aj, dám na dělníky, kteříž sekati mají dříví, pšenice semlené služebníkům tvým dvadcet tisíc měr, a dvadcet tisíc měr ječmene, a dvadcet tisíc lák vína, a dvadcet tisíc tun oleje.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 11, 'I odpověděl Chíram král Tyrský psáním, kteréž poslal k Šalomounovi: Jistě, žeť miluje Hospodin lid svůj, protož tě ustanovil nad nimi za krále.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 12, 'Řekl dále Chíram: Požehnaný Hospodin Bůh Izraelský, kterýž učinil nebe i zemi, a kterýž dal králi Davidovi syna moudrého, umělého, rozumného a opatrného, aby vystavěl dům Hospodinu a dům svůj královský.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 13, 'Protož posílámť teď muže moudrého, umělého a opatrného, kterýž byl u Chírama otce mého,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 14, 'Syna jedné ženy ze dcer Dan, otce pak měl Tyrského, kterýž umí dělati na zlatě, na stříbře, na mědi, železe, kamení a na dříví, i z šarlatu, z postavce modrého, z kmentu a z červce, tolikéž řezati všelijaké řezby, a vymysliti všelijaké dílo, kteréž dáno mu bude s moudrými tvými, a s moudrými pána mého Davida otce tvého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 15, 'Pšenice však toliko a ječmene, oleje a vína, což řekl pán můj, nechť pošle služebníkům svým.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 16, 'My pak nasekáme dříví z Libánu, což ho koli bude potřebí tobě, a připlavíme je tobě v vořích po moři k Joppe, a ty dáš je voziti do Jeruzaléma.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 17, 'A tak sečtl Šalomoun všecky cizozemce, kteříž byli v zemi Izraelské po sečtení tom, kterýmž sečtl je David otec jeho, a nalezeno jich sto a padesát tisíc, tři tisíce a šest set.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 18, 'I vybral z nich sedmdesát tisíc nosičů, a osmdesát tisíc těch, kteříž sekali na hoře, tři pak tisíce a šest set úředníků, kteříž lid k dílu přídrželi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 1, 'I začal stavěti Šalomoun domu Hospodinova v Jeruzalémě na hoře Moria, kteráž byla ukázána Davidovi otci jeho, na místě, kteréž byl připravil David, na humně Ornana Jebuzejského.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 2, 'A počal stavěti druhého měsíce, dne druhého, království svého léta čtvrtého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 3, 'A toto jest vyměření Šalomounovo při stavení domu Božího: Dlouhost loktů podlé první míry bylo šedesáti loket, a šíř dvadcíti loket.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 4, 'A síň, kteráž byla v čele, jakž široký dům, byla na dvadceti loktů, vysokost pak sto a dvadcíti, a obložil ji vnitř zlatem čistým.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 5, 'Dům pak veliký opažil dřívím jedlovým, kteréž obložil zlatem nejčistším, na němž po vrchu dal nadělati palm a řetízků.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 6, 'Přikryl také dům ten kamenem drahým ozdobně; zlato pak to bylo zlato Parvaimské.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 7, 'Obložil, pravím, dům, trámy, veřeje i stěny jeho, i dvéře jeho zlatem, a vyryl cherubíny na stěnách.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 8, 'Udělal i dům svatyně svatých, jehož dýlka byla jako šířka domu, dvadcíti loktů, a šířka loktů dvadcíti, a obložil ji zlatem výborným šesti sty centnéři.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 9, 'Hřebíkové též vážili padesát lotů zlata, ano i síňce obložil zlatem.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 10, 'Udělal také v domě svatyně svatých dva cherubíny dílem řemeslným, a obložil je zlatem.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 11, 'Dlouhost křídel těch cherubínů byla na dvadceti loket. Křídlo jedno na pět loket, a dotýkalo se stěny domu, a druhé křídlo na pět loket dotýkalo se křídla cherubína druhého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 12, 'A tak křídlo cherubína jednoho na pět loket dotýkalo se stěny domu, a křídlo druhé na pět loket dosahovalo křídla cherubína druhého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 13, 'A tak křídla cherubínů těch roztažená byla na dvadceti loktů, a stáli na nohách svých, tváří svou obráceni do domu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 14, 'Udělal také i oponu z postavce modrého, z šarlatu, z červce a z kmentu, a udělal na ní cherubíny.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 15, 'Udělal též před domem sloupy dva na třidceti a pět loktů zvýší, a makovice, kteréž byly na každém svrchu, na pět loket.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 16, 'Zdělal též i řetízky jako v svatyni svatých, a otočil je okolo makovic těch sloupů, a udělav jablek zrnatých sto, dal mezi řetízky.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 17, 'A tak postavil ty sloupy před chrámem, jeden po pravé a druhý po levé straně, a dal jméno tomu, kterýž byl po pravici Jachin, a jméno tomu, kterýž byl po levici, Boaz.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 1, 'Udělal také i oltář měděný, zdélí dvadcíti loktů, a dvadcíti loktů zšíří, desíti pak loktů zvýší.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 2, 'Udělal též moře slité, desíti loket od jednoho kraje k druhému, okrouhlé vůkol, zvýší na pět loktů, a okolek jeho třidcíti loket vůkol.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 3, 'Podobenství také volů pod ním, kterýchž všudy vůkol bylo deset do lokte, obkličujících moře vůkol; a tak byly dva řady volů slitých, spolu s mořem.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 4, 'A stálo na dvanácti volích. Tři obráceni byli na půlnoci, a tři patřili k západu, tři zase postaveni byli ku poledni, a tři obráceni byli k východu, a moře svrchu na nich stálo, ale všech jich zadkové byli pod mořem.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 5, 'A bylo ztlouští na dlaň. Kraj jeho byl, jakýž bývá u koflíku aneb květu liliového, tři tisíce tun v se beroucí.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 6, 'Udělal také deset umyvadel, a postavil jich pět po pravé straně, a pět po levé, k obmývání z nich. Všecko, což se strojilo k zápalům, obmývali z nich, ale moře, aby se z něho kněží umývali.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 7, 'Nadto udělal i svícnů zlatých deset vedlé slušnosti jejich, a postavil v chrámě, pět po pravé straně a pět po levé.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 8, 'Udělal i stolů deset, kteréž postavil v chrámě, pět po pravé a pět po levé straně. K tomu udělal číší zlatých sto.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 9, 'Udělal potom síň kněžskou, též síň velikou, a dvéře u též síně okoval mědí.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 10, 'Moře pak postavil na pravé straně k východu, naproti polední straně.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 11, 'Nadělal také Chíram hrnců, lopat a kotlíků, a dokonal Chíram dílo, kteréž byl dělal králi Šalomounovi k domu Božímu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 12, 'Dva sloupy a kruhy, makovice také na vrchu těch dvou sloupů, a mřežování dvoje, aby přikrývalo ty dvě makovice okrouhlé, kteréž byly na vrchu sloupů,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 13, 'A jablek zrnatých čtyři sta na dvojím mřežování. Dvěma řady jablka zrnatá byla na mřežování jednom, aby přikrývala ty dvě makovice okrouhlé, kteréž byly na vrchu sloupů.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 14, 'Podstavky také zdělal, a umyvadla na těch podstavcích.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 15, 'Moře jedno, a volů dvanácte pod ním.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 16, 'Též hrnce a lopaty a vidličky třírohé, a všecko nádobí jejich zdělal Chíram s otcem svým králi Šalomounovi k domu Hospodinovu z mědi přečisté.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 17, 'Na rovinách Jordánských sléval to král v zemi jilovaté, mezi Sochot a Saredata.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 18, 'A tak nadělal Šalomoun všech těch nádob velmi mnoho, tak že váhy té mědi vyhledáváno nebylo.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 19, 'Zdělal také Šalomoun i jiná všelijaká nádobí k domu Božímu, jako oltář zlatý a stoly, na nichž kladeni byli chlebové předložení,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 20, 'Tolikéž svícny i lampy jejich z zlata nejčistšího, aby je rozsvěcovali příslušně před svatyní svatých,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 21, 'Květy také a lampy i utěradla z zlata, a to bylo zlato nejvýbornější.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 22, 'I žaltáře a kotlíky, kadidlnice a nádoby k oharkům z zlata čistého, k tomu i bránu domu, dvéře vnitřní svatyně svatých, i dvéře domu, totiž v chrámě, byly z zlata.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 5, 1, 'A tak dokonáno jest všecko dílo, kteréž dělal Šalomoun k domu Hospodinovu, a vnesl tam Šalomoun věci posvěcené od Davida otce svého, též stříbro a zlato, a všecko nádobí, složiv je mezi poklady domu Božího.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 5, 2, 'Tedy shromáždil Šalomoun starší Izraelské, a všecky přední z pokolení, totiž knížata čeledí otcovských s syny Izraelskými do Jeruzaléma, aby přenesli truhlu smlouvy Hospodinovy z města Davidova, jenž jest Sion.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 5, 3, 'I shromáždili se k králi všickni muži Izraelští na slavnost, kteráž bývá měsíce sedmého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 5, 4, 'Když pak přišli všickni starší Izraelští, vzali Levítové truhlu,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 5, 5, 'A nesli ji zhůru, též stánek úmluvy, i všecka nádobí posvátná, kteráž byla v stánku, přenesli to kněží a Levítové.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 5, 6, 'Zatím král Šalomoun i všecko shromáždění Izraelské, kteréž se k němu sešlo, obětovali před truhlou ovce a voly, kteříž ani popisováni, ani vyčítáni nebyli pro množství.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 5, 7, 'A tak vnesli kněží truhlu smlouvy Hospodinovy na místo její, do vnitřního domu, do svatyně svatých, pod křídla cherubínů.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 5, 8, 'Nebo cherubínové měli roztažená křídla nad místem truhly, a přikrývali cherubínové truhlu i sochory její svrchu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 5, 9, 'A povytáhli sochorů, tak že vidíni byli koncové jejich z truhly, k předku svatyně svatých, vně však nebylo jich viděti. A byla tam až do tohoto dne.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 5, 10, 'Nic nebylo v truhle, kromě dvou tabulí, kteréž tam složil Mojžíš na Orébě tehdáž, když učinil Hospodin smlouvu s syny Izraelskými, a oni vyšli z Egypta.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 5, 11, 'I stalo se, když vycházeli kněží z svatyně, (nebo všickni kněží, kteříž se koli našli, byli se posvětili, aniž šetřili pořádku.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 5, 12, 'Tak i Levítové zpěváci všickni, kteříž byli při Azafovi, Hémanovi a Jedutunovi, i synové jejich i bratří jejich, odíni jsouce kmentem, stáli s cymbály a loutnami a harfami k východní straně oltáře, a s nimi kněží sto a dvadceti, troubících v trouby.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 5, 13, 'Nebo měli ti, kteříž spolu troubili v trouby, a zpěváci vydávati jeden zvuk k chválení a oslavování Hospodina); a když povyšovali hlasu na trouby a cymbály i jiné nástroje hudebné, chválíce Hospodina a řkouce, že dobrý jest, a že na věky trvá milosrdenství jeho: tedy oblak naplnil dům ten, dům totiž Hospodinův,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 5, 14, 'Tak že nemohli kněží ostáti a sloužiti pro ten oblak; nebo sláva Hospodinova byla naplnila dům Boží.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 1, 'Tehdy řekl Šalomoun: Hospodin řekl, že bude přebývati v mrákotě.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 2, 'Aj, jižť jsem vystavěl tobě, Pane, dům k přebývání, a místo, v němž bys přebýval na věky.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 3, 'A obrátiv král tvář svou, dával požehnání všemu shromáždění Izraelskému. (Všecko pak shromáždění Izraelské stálo.)');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 4, 'A řekl: Požehnaný Hospodin Bůh Izraelský, kterýž mluvil ústy svými Davidovi otci mému, a to teď skutečně naplnil, řka:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 5, 'Od toho dne, jakž jsem vyvedl lid svůj z země Egyptské, nevyvolil jsem města z žádného pokolení Izraelského k vystavení domu, kdež by přebývalo jméno mé, aniž jsem vyvolil kterého muže, aby byl vývodou nad lidem mým Izraelským.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 6, 'Ale vyvolil jsem Jeruzalém, aby tu přebývalo jméno mé, a vyvolil jsem Davida, aby byl nad lidem mým Izraelským.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 7, 'Uložil tě byl zajisté David otec můj stavěti dům jménu Hospodina Boha Izraelského.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 8, 'Ale Hospodin řekl Davidovi otci mému: Ačkoli jsi uložil v srdci svém stavěti dům jménu mému, a dobřes učinil, žes to myslil v srdci svém,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 9, 'A však ty nebudeš stavěti toho domu, ale syn tvůj, kterýž vyjde z bedr tvých, on vystaví dům ten jménu mému.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 10, 'A tak splnil Hospodin slovo své, kteréž byl mluvil. Nebo jsem povstal na místo Davida otce svého, a dosedl jsem na stolici Izraelskou, jakož byl mluvil Hospodin, a ustavěl jsem dům tento jménu Hospodina Boha Izraelského.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 11, 'A postavil jsem tam truhlu, v níž jest smlouva Hospodinova, kterouž učinil s syny Izraelskými.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 12, 'I postavil se před oltářem Hospodinovým, přede vším shromážděním Izraelským, a pozdvihl rukou svých.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 13, 'Udělal pak byl Šalomoun výstupek měděný ku podobenství pánve, a postavil jej u prostřed síně, pěti loktů zdélí, a pěti loket zšíří, a tří loket zvýší, i vstoupil na něj, a poklekl na kolena svá přede vším shromážděním Izraelským, a pozdvihl rukou svých k nebi,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 14, 'A řekl: Hospodine Bože Izraelský, neníť podobného tobě Boha na nebi ani na zemi, kterýž by ostříhal smlouvy a milosrdenství služebníkům svým, chodícím před tebou v celém srdci svém,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 15, 'Kterýž jsi splnil služebníku svému, Davidovi otci mému, to, což jsi mluvil jemu. Jakž jsi mluvil ústy svými, tak jsi to skutečně naplnil, jakž se to dnes vidí.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 16, 'Nyní tedy, ó Hospodine Bože Izraelský, naplniž služebníku svému, Davidovi otci mému, což jsi mluvil jemu, řka: Nebudeť vyhlazen muž z rodu tvého od tváři mé, aby neměl seděti na stolici Izraelské, jestliže toliko ostříhati budou synové tvoji cesty své, chodíce v zákoně mém, tak jakož jsi ty chodil přede mnou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 17, 'Protož nyní, ó Hospodine Bože Izraelský, nechť jest upevněno slovo tvé, kteréž jsi mluvil služebníku svému Davidovi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 18, '(Ač zdali v pravdě bydliti bude Bůh s člověkem na zemi? Aj, nebesa, nýbrž nebesa nebes neobsahují tě, mnohem méně dům tento, kterýž jsem vystavěl.)');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 19, 'A popatř k modlitbě služebníka svého a k úpění jeho, Hospodine Bože můj, slyše volání a modlitbu, kterouž služebník tvůj modlí se před tebou,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 20, 'Aby oči tvé byly otevřené na dům tento dnem i nocí, na místo toto, o němž jsi mluvil, že tu přebývati bude jméno tvé, abys vyslýchal modlitbu, kterouž se modlívati bude služebník tvůj na místě tomto.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 21, 'Vyslýchejž tedy modlitbu služebníka svého, i lidu svého Izraelského, kterouž se modlívati budou na místě tomto, ty vždy vyslýchej z místa přebývání svého, s nebe, a vyslýchaje, buď milostiv.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 22, 'Když by zhřešil člověk proti bližnímu svému, a nutil by ho k přísaze, tak že by přisahati musil, a přišla by ta přísaha před oltář do domu tohoto:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 23, 'Ty vyslýchej s nebe, a rozeznej i rozsuď služebníky své, mstě nad bezbožným, obraceje usilování jeho na hlavu jeho, a ospravedlňuje spravedlivého, odplacuje mu podlé spravedlnosti jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 24, 'Tolikéž když by poražen byl lid tvůj Izraelský od nepřátel, proto že zhřešili proti tobě, jestliže by obrátíce se, vyznávali jméno tvé, a modléce se, poníženě by prosili tebe v domě tomto:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 25, 'Ty vyslýchej s nebe, a odpusť hřích lidu svému Izraelskému, a přiveď je zase do země, kterouž jsi jim dal i otcům jejich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 26, 'Podobně když by zavříno bylo nebe, a nepršel by déšť, proto že zhřešili proti tobě, a modléce se na místě tomto, vyznávali by jméno tvé, a od hříchu svého by se odvrátili po tvém trestání:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 27, 'Ty vyslýchej na nebi, a odpusť hřích služebníků svých a lidu svého Izraelského, vyučuje je cestě výborné, po níž by chodili, a dej déšť na zemi svou, kterouž jsi dal lidu svému za dědictví.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 28, 'Byl-li by hlad na zemi, byl-li by mor, sucho neb rez, kobylky neb brouci jestliže by byli, ssoužil-li by jej nepřítel jeho v zemi obývání jeho, aneb jakákoli rána a jakákoli nemoc:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 29, 'Všelikou modlitbu a každé úpění, kteréž by pocházelo od kteréhokoli člověka, aneb ode všeho lidu tvého Izraelského, když by jen poznajíce jeden každý ránu svou a bolest svou, pozdvihl by rukou svých v domě tomto,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 30, 'Ty vyslýchej s nebe, z místa přebývání svého, a slituj se, a odplať jednomu každému podlé skutků jeho, vedlé toho, jakž znáš srdce jeho, (ty zajisté sám znáš srdce lidská),');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 31, 'Aby se báli tebe, a chodili po všech cestách tvých, po všecky dny, v nichž by živi byli na zemi, kterouž jsi dal otcům našim.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 32, 'Nýbrž také i cizozemec, kterýž není z lidu tvého Izraelského, přišel-li by z země daleké pro jméno tvé veliké a ruku tvou silnou, a rámě tvé vztažené, když by přišli a modlili se v domě tomto:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 33, 'Ty vyslýchej s nebe, z místa přebývání svého, a učiň všecko to, o čež volati bude k tobě cizozemec ten, aby poznali všickni národové země jméno tvé, a báli se tebe jako lid tvůj Izraelský, a aby poznali, že jméno tvé vzýváno jest nad domem tímto, kterýž jsem vystavěl.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 34, 'Když by vytáhl lid tvůj k boji proti nepřátelům svým cestou, kterouž bys je poslal, a modlili by se tobě naproti městu tomuto, kteréž jsi vyvolil, a domu tomuto, kterýž jsem ustavěl jménu tvému:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 35, 'Ty vyslýchej s nebe modlitbu a úpění jejich, a vyvoď při jejich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 36, 'Když by zhřešili proti tobě, (jakož není člověka, ješto by nehřešil), a rozhněvaje se na ně, vydal bys je v moc nepříteli, tak že by je jaté vedli ti, kteříž by je zjímali, do země daleké neb blízké;');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 37, 'A usmyslili by sobě v zemi, do níž by zajati byli, a obrátíce se, modlili by se tobě v zemi zajetí svého, řkouce: Zhřešili jsme, převráceně jsme činili, a bezbožně jsme se chovali;');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 38, 'A tak navrátili by se k tobě celým srdcem svým a celou duší svou v zemi zajetí svého, do kteréž by zajati byli, a modlili by se naproti zemi své, kterouž jsi dal otcům jejich, a naproti městu, kteréž jsi vyvolil, a domu, kterýž jsem vzdělal jménu tvému:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 39, 'Vyslýchej s nebe, z místa příbytku svého, modlitbu jejich a úpění jejich, a vyvoď při jejich, a odpusť lidu svému, kterýž by zhřešil proti tobě.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 40, 'Nyní tedy, Bože můj, nechť jsou, prosím, oči tvé otevřené, a uši tvé nakloněné k modlitbě na místě tomto.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 41, 'Aj, nyní povstaň, ó Hospodine Bože, k odpočinutí svému, ty i truhla síly tvé; kněží tvoji, Hospodine Bože, nechť jsou oblečeni v spasení, a svatí tvoji ať se veselí v dobrých věcech.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 42, 'Hospodine Bože, neodvracejž tváři od pomazaného svého, pamatuj na milosrdenství zaslíbená Davidovi služebníku svému.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 1, 'A když přestal Šalomoun modliti se, rychle oheň sstoupil s nebe, a sehltil zápal i jiné oběti, a sláva Hospodinova naplnila dům ten,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 2, 'Tak že nemohli kněží vjíti do domu Hospodinova, proto že naplnila sláva Hospodinova dům Hospodinův.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 3, 'Všickni pak synové Izraelští viděli, když sstupoval oheň a sláva Hospodinova na dům, a padše tváří k zemi na dlážení, klaněli se a chválili Hospodina, že dobrý jest, a že na věky trvá milosrdenství jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 4, 'Při tom král a všecken lid obětovali oběti před Hospodinem.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 5, 'Obětoval zajisté král Šalomoun obět dvamecítma tisíc volů, a ovec sto a dvadceti tisíců, když posvěcovali domu Božího král i všecken lid.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 6, 'Ale kněží stáli při svých úřadích, též i Levítové s nástroji hudebnými Hospodinovými, kterýchž byl nadělal David král k oslavování Hospodina, (nebo na věky milosrdenství jeho), žalmem Davidovým, kterýž jim vydal. Jiní pak kněží troubili v trouby naproti nim, a všecken lid Izraelský stál.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 7, 'Posvětil také Šalomoun prostředku té síně, kteráž byla před domem Hospodinovým; nebo obětoval tu oběti zápalné a tuky obětí, pokojných, proto že na oltáři měděném, kterýž byl udělal Šalomoun, nemohli se směstknati zápalové a oběti suché i tukové jejich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 8, 'I držel Šalomoun slavnost toho času za sedm dní, a všecken Izrael s ním, shromáždění velmi veliké odtud, kudyž se vchází do Emat, až ku potoku Egyptskému.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 9, 'I světili dne osmého svátek; nebo posvěcení oltáře slavili za sedm dní, tolikéž slavnost tu za sedm dní.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 10, 'Třimecítmého pak dne měsíce sedmého propustil lid k příbytkům jejich s radostí a veselím srdce z toho, což dobrého učinil Hospodin Davidovi a Šalomounovi a Izraelovi lidu svému.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 11, 'I dokonal Šalomoun dům Hospodinův a dům královský, a všecko, cožkoli byl uložil v srdci svém, aby učinil v domě Hospodinově a v domě svém, šťastně se mu vedlo.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 12, 'V tom ukázal se Hospodin Šalomounovi v noci, a řekl jemu: Uslyšel jsem modlitbu tvou, a vyvolil jsem sobě to místo za dům obětí.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 13, 'Jestliže zavru nebe, tak že by nebylo deště, a jestliže přikáži kobylkám, aby pohubily zemi, též jestliže pošli morovou ránu na lid svůj,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 14, 'A ponižujíce se lid můj, nad nímž jest vzýváno jméno mé, modlili by se, a hledali by tváři mé, a odvrátili by se od cest svých zlých: i já také vyslyším je s nebe, a odpustím hřích jejich, a uzdravím zemi jejich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 15, 'Budouť již i oči mé otevřené, a uši mé nakloněné k modlitbě z místa tohoto.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 16, 'Nebo nyní vyvolil jsem a posvětil domu tohoto, aby tu přebývalo jméno mé až na věky, a aby tu byly oči mé a srdce mé po všecky dny.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 17, 'A ty budeš-li choditi přede mnou, jako chodil David otec tvůj, tak abys činil všecko to, což jsem přikázal tobě, ustanovení i soudů mých ostříhaje:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 18, 'Utvrdím zajisté stolici království tvého, jakož jsem učinil smlouvu s Davidem otcem tvým, řka: Nebude vyhlazen muž z rodu tvého, aby nepanoval nad Izraelem.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 19, 'Jestliže pak se odvrátíte a opustíte ustanovení má a přikázání má, kteráž jsem vám vydal, a odejdouce, sloužiti budete bohům cizím a klaněti se jim:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 20, 'Vypléním takové z země své, kterouž jsem jim dal, a dům tento, kteréhož jsem posvětil jménu svému, zavrhu od tváři své, a vydám jej v přísloví a v rozprávku mezi všemi národy.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 21, 'A tak dům ten, kterýž byl zvýšený každému jdoucímu mimo něj, bude k užasnutí, a dí: Proč tak učinil Hospodin zemi této a domu tomuto?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 22, 'Tedy odpovědí: Proto že opustili Hospodina Boha otců svých, kterýž je vyvedl z země Egyptské, a chopili se bohů cizích, a klanějíce se jim, sloužili jim, protož uvedl na ně všecky tyto zlé věci.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 1, 'Stalo se potom po přeběhnutí dvadcíti let, v nichž stavěl Šalomoun dům Hospodinův a dům svůj,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 2, 'Že vystavěl Šalomoun města, kteráž byl dal Chíram Šalomounovi, a osadil tam syny Izraelské.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 3, 'Zatím táhl Šalomoun do Emat Soby, a zmocnil se jí.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 4, 'I ustavěl Tadmor na poušti, a všecka města skladů vystavěl v Emat.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 5, 'Vystavěl i Betoron hořejší, též i Betoron dolejší, města ohrazená zdmi, branami i závorami.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 6, 'Ano i Baalat a všecka města, v nichž měl sklady Šalomoun, a všecka města vozů, i města jízdných, všecko vedlé žádosti své, cožkoli chtěl stavěti v Jeruzalémě a na Libánu, i po vší zemi panování svého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 7, 'Všecken také lid, kterýž byl pozůstal z Hetejských, a Amorejských a Ferezejských, a Hevejských a Jebuzejských, kteříž nebyli z Izraele,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 8, 'Z synů jejich, kteříž byli pozůstali po nich v zemi té, jichž byli nevyhubili synové Izraelští, uvedl Šalomoun pod plat až do tohoto dne.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 9, 'Ale z synů Izraelských, jichž nepodrobil Šalomoun v službu při díle svém, (nebo oni byli muži bojovní a přední knížata jeho, úředníci nad vozy a jezdci jeho),');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 10, 'Z těch, pravím, bylo předních vládařů, kteréž měl král Šalomoun, dvě stě a padesáte, kteříž panovali nad lidem.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 11, 'Dceru pak Faraonovu přestěhoval Šalomoun z města Davidova do domu, kterýž jí byl vystavěl. Nebo řekl: Nemohlať by bydliti manželka má v domě Davida krále Izraelského, nebo svatý jest, proto že vešla do něho truhla Hospodinova.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 12, 'Tedy obětoval Šalomoun zápaly Hospodinu na oltáři Hospodinovu, kterýž byl vzdělal před síní,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 13, 'Cokoli náležitě každého dne obětováno býti mělo podlé přikázaní Mojžíšova, ve dny sobotní, na novměsíce a na slavnosti, po třikrát do roka, na slavnost přesnic, na slavnost téhodnů, a na slavnost stánků.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 14, 'Ustanovil také podlé nařízení Davida otce svého pořádky kněžské k úřadům jejich, a Levíty ku povinnostem jejich, aby chválili Boha, a přisluhovali při kněžích náležitě každého dne, a vrátné v pořádcích jejich u jedné každé brány; nebo tak byl rozkaz Davida muže Božího.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 15, 'Aniž se uchýlili od rozkázaní králova kněžím a Levítům při všeliké věci i při pokladích.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 16, 'A když dostrojeno bylo všecko dílo Šalomounovo od toho dne, v němž založen byl dům Hospodinův, až do vystavení jeho, a tak dokonán byl dům Hospodinův,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 17, 'Tedy jel Šalomoun do Aziongaber a do Elat při břehu mořském v zemi Idumejské.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 18, 'I poslal jemu Chíram po služebnících svých lodí, a služebníky umělé na moři, kteříž plavivše se s služebníky Šalomounovými do Ofir, nabrali odtud čtyři sta a padesáte centnéřů zlata, a přinesli je králi Šalomounovi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 1, 'Královna pak z Sáby uslyševši pověst o Šalomounovi, přijela do Jeruzaléma, aby zkusila Šalomouna v pohádkách, s vojskem velmi velikým a s velbloudy, na nichž přinesla vonných věcí, a zlata velmi mnoho i kamení drahého. Přišla tedy k Šalomounovi, a mluvila s ním o všecko, což měla v srdci svém.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 2, 'Jížto odpověděl Šalomoun na všecka slova její. Nebylo nic skrytého před Šalomounem, nač by jí neodpověděl.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 3, 'Protož uzřevši královna z Sáby moudrost Šalomounovu, a dům, kterýž byl ustavěl,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 4, 'I pokrmy stolu jeho, též sedání a stávání služebníků jeho přisluhujících jemu, i roucha jejich, šeňkýře také jeho a oděv jejich, i stupně, kterýmiž vstupoval k domu Hospodinovu: zděsila se náramně,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 5, 'A řekla králi: Praváť jest řeč, kterouž jsem slyšela v zemi své o věcech tvých a o moudrosti tvé.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 6, 'Však jsem nechtěla věřiti řečem jejich, až jsem přijela a uzřela očima svýma, a aj, není mi praveno ani polovice o velikosti moudrosti tvé. Převýšil jsi pověst tu, kterouž jsem slyšela.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 7, 'Blahoslavení muži tvoji, a blahoslavení služebníci tvoji tito, kteříž stojí před tebou vždycky, a slyší moudrost tvou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 8, 'Budiž Hospodin Bůh tvůj požehnaný, kterýž tě sobě oblíbil, aby tě posadil na stolici své, abys byl králem na místě Hospodina Boha tvého. Proto že miluje Bůh tvůj Izraele, aby jej utvrdil na věky, ustanovil tě nad nimi králem, abys činil soud a spravedlnost.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 9, 'I dala králi sto a dvadceti centnéřů zlata, a vonných věcí velmi mnoho, i kamení drahého, aniž bylo kdy přivezeno takových vonných věcí, jakéž darovala královna z Sáby Šalomounovi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 10, 'K tomu také i služebníci Chíramovi, a služebníci Šalomounovi, kteříž byli přivezli zlata z Ofir, přivezli dříví algumim a kamení drahého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 11, 'I nadělal král z toho dříví algumim stupňů k domu Hospodinovu i k domu královu, též harf a louten zpěvákům, aniž kdy prvé vídány takové věci v zemi Judské.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 12, 'Král také Šalomoun dal královně z Sáby vedlé vší vůle její, čehož požádala, kromě toho, což byla přinesla k králi. Potom se navrátila a odjela do země své, ona i služebníci její.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 13, 'Byla pak váha toho zlata, kteréž přicházelo Šalomounovi na každý rok, šest set šedesáte a šest centnéřů zlata,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 14, 'Kromě toho, což kupci a prodavači přinášeli, a všickni králové Arabští. A vývodové té země přiváželi zlato a stříbro Šalomounovi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 15, 'A protož nadělal král Šalomoun dvě stě štítů z zlata taženého; šest set lotů zlata taženého dával na každý štít.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 16, 'A tři sta pavéz z zlata taženého; tři sta lotů zlata dal na každou pavézu. I složil je král v domě lesu Libánského.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 17, 'Udělal také král stolici z kostí slonových velikou, a obložil ji zlatem čistým.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 18, 'A bylo šest stupňů k té stolici, a podnože té stolice také byly z zlata, držící se stolice, ano i spolehadla rukám s obou stran, tu kdež se sedalo, a dva lvové stáli u spolehadel.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 19, 'Dvanácte též lvů stálo tu na šesti stupních s obou stran. Nebylo nic uděláno takového v žádném království.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 20, 'Nadto všecky nádoby krále Šalomouna, jichž ku pití užívali, byly zlaté, a všecky nádoby v domě lesu Libánského byly z zlata nejčistšího. Nic nebylo z stříbra, aniž ho sobě co vážili za dnů Šalomounových.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 21, 'Nebo měl král lodí, kteréž přecházely přes moře s služebníky Chíramovými. Jednou ve třech letech vracovaly se ty lodí mořské, přinášející zlato a stříbro, kosti slonové a opice a pávy.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 22, 'I zveleben jest král Šalomoun nad všecky krále zemské v bohatství a v moudrosti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 23, 'Pročež všickni králové země žádostivi byli viděti tvář Šalomounovu, aby slyšeli moudrost jeho, kterouž složil Bůh v srdci jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 24, 'Z nichž jeden každý přinášeli také dar svůj, nádoby stříbrné a nádoby zlaté, roucha a zbroj, i vonné věci, koně a mezky, každého roku,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 25, 'Tak že měl Šalomoun čtyři tisíce stájí koní a vozů, a dvanácte tisíc jezdců, kteréž rozsadil v městech vozů a při králi v Jeruzalémě.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 26, 'I panoval nade všemi králi od řeky Eufrates až k zemi Filistinské, a až k končinám Egyptským.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 27, 'A složil král stříbra v Jeruzalémě jako kamení, a cedrového dříví jako planého fíkoví, kteréž roste v údolí u velikém množství.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 28, 'Přivodili také Šalomounovi koně z Egypta i ze všech zemí.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 29, 'Jiné pak věci Šalomounovy, první i poslední, vypsány jsou v knize Nátana proroka, a v proroctví Achiáše Silonského, a u viděních Jaaddy proroka o Jeroboámovi synu Nebatovu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 30, 'A kraloval Šalomoun v Jeruzalémě nade vším Izraelem čtyřidceti let.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 31, 'I usnul Šalomoun s otci svými, a pochovali jej v městě Davida otce jeho. Kraloval pak Roboám syn jeho místo něho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 1, 'Tedy odšel Roboám do Sichem; nebo tam sešel se byl všecken Izrael, aby ho ustanovili za krále.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 2, 'Stalo se pak, když o tom uslyšel Jeroboám syn Nebatův, jsa v Egyptě, kamž byl utekl před králem Šalomounem, navrátil se Jeroboám z Egypta.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 3, 'Nebo poslali a povolali ho. Tedy přišed Jeroboám i všecken Izrael, mluvili k Roboámovi, řkouce:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 4, 'Otec tvůj stížil jho naše, protož nyní polehč služby otce svého tvrdé a břemene jeho těžkého, kteréž vložil na nás, a budeme tobě sloužiti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 5, 'Kterýž řekl jim: Po třech dnech navraťte se ke mně. I odšel lid.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 6, 'V tom radil se král Roboám s starci, kteříž stávali před Šalomounem otcem jeho, ještě za života jeho, řka: Kterak vy radíte, jakou odpověd mám dáti lidu tomu?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 7, 'I odpověděli jemu, řkouce: Jestliže se dobrotivě ukážeš lidu tomuto a povolíš jim, a mluviti budeš přívětivě, budou služebníci tvoji po všecky dny.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 8, 'Ale on opustil radu starců, kterouž dali jemu, a radil se s mládenci, kteříž odrostli s ním, a stávali před ním.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 9, 'A řekl jim: Co vy radíte, jakou máme dáti odpověd lidu tomuto, kteříž mluvili ke mně, řkouce: Polehč břemene, kteréž vložil otec tvůj na nás?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 10, 'Jemuž odpověděli mládenci, kteříž zrostli s ním, řkouce: Takto odpovíš lidu tomu, kteříž mluvili k tobě a řekli: Otec tvůj stížil jho naše, ty pak polehč nám, takto díš jim: Nejmenší prst můj tlustší jest, nežli bedra otce mého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 11, 'Nyní tedy, otec můj těžké břímě vzložil na vás, já pak přidám břemene vašeho; otec můj trestal vás bičíky, ale já biči uzlovatými.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 12, 'Potom přišel Jeroboám i všecken lid k Roboámovi dne třetího, jakž byl vyřkl král, řka: Navraťte se ke mně dne třetího.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 13, 'I odpověděl jim král tvrdě. Nebo opustil král Roboám radu starců,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 14, 'A mluvil k nim vedlé rady mládenců, řka: Otec můj stížil jho vaše, já pak k němu přidám; otec můj trestal vás bičíky, ale já biči uzlovatými.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 15, 'A tak neuposlechl král lidu. (Příčina zajisté byla od Boha, aby naplnil Hospodin řeč svou, kterouž mluvil skrze Achiáše Silonského k Jeroboámovi synu Nebatovu.)');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 16, 'Protož vida všecken Izrael, že by je král oslyšel, odpověděl lid králi, řkouce: Jakýž máme díl v Davidovi? Ani dědictví nemáme v synu Izai. Jeden každý k stanům svým, ó Izraeli! Nyní opatř dům svůj, Davide. Odšel tedy všecken Izrael k stanům svým,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 17, 'Tak že nad syny Izraelskými toliko, kteříž bydlili v městech Judských, kraloval Roboám.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 18, 'A když poslal král Roboám Adurama, kterýž byl nad platy, uházeli ho synové Izraelští kamením až do smrti, čímž král Roboám přinucen byl, aby vsedna na vůz, utekl do Jeruzaléma.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 19, 'A tak odstoupili synové Izraelští od domu Davidova až do dnešního dne.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 1, 'Když pak přijel Roboám do Jeruzaléma, shromáždil dům Judův a Beniaminův, sto a osmdesáte tisíc výborných bojovníků, aby bojovali proti Izraelovi, a aby zase obráceno bylo království k Roboámovi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 2, 'Tedy stala se řeč Hospodinova k Semaiášovi, muži Božímu, řkoucí:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 3, 'Pověz Roboámovi synu Šalomounovu, králi Judskému, a všemu lidu Izraelskému, kterýž jest v pokolení Judově a Beniaminově, řka:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 4, 'Takto praví Hospodin: Netáhněte a nebojujte proti bratřím svým, navraťte se jeden každý do domu svého; nebo ode mne stala se věc tato. I uposlechli rozkazu Hospodinova, a navrátili se, aby netáhli proti Jeroboámovi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 5, 'I bydlil Roboám v Jeruzalémě, a vzdělal města hrazená v Judstvu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 6, 'A vzdělal Betlém, Etam. a Tekoe,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 7, 'Betsur, Socho a Adulam,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 8, 'Gát, Maresa a Zif,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 9, 'Adoraim, Lachis a Azeka,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 10, 'Zaraha, Aialon a Hebron, kteráž byla v pokolení Judově a Beniaminově města hrazená.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 11, 'A když upevnil města hrazená, osadil v nich knížata, a zdělal špižírny k potravám, k oleji a vínu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 12, 'A v jednom každém městě složil štíty a kopí, a opatřil ta města velmi dobře, a tak kraloval nad Judou a Beniaminem.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 13, 'Kněží také a Levítové, kteříž byli ve všem Izraeli, postavili se k němu ze všech končin svých.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 14, 'Opustili byli zajisté Levítové předměstí svá i vládařství svá, a odebrali se do Judstva a do Jeruzaléma, (proto, že je zavrhl Jeroboám a synové jeho, aby v úřadu kněžském nesloužili Hospodinu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 15, 'A nařídil sobě kněží k sloužení po výsostech ďáblům a telatům, kterýchž byl nadělal).');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 16, 'A za nimi ze všech pokolení Izraelských ti, kteříž oddali srdce své k hledání Hospodina Boha Izraelského, přišli do Jeruzaléma, aby obětovali Hospodinu Bohu otců svých.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 17, 'A tak utvrdili království Judské, a zsilili Roboáma syna Šalomounova za tři léta, a po ta tři léta chodili po cestě Davidově a Šalomounově.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 18, 'Potom pojal sobě Roboám ženu, Mahalat, dceru Jerimota syna Davidova, a Abichail, dceru Eliaba syna Izai.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 19, 'Kteráž mu zplodila syny: Jeusa a Semariáše a Zahama.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 20, 'A po té pojal Maachu dceru Absolonovu, kteráž mu porodila Abiáše, Attaie, Zizu a Selomita.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 21, 'Ale miloval Roboám Maachu dceru Absolonovu, nade všecky ženy i ženiny své; nebo byl pojal žen osmnáct, a ženin šedesát, a zplodil dvadceti a osm synů a šedesáte dcer.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 22, 'Ustanovil pak Roboám Abiáše syna Maachy za kníže a vývodu mezi bratřími jeho; nebo myslil ho ustanoviti králem.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 23, 'A opatrnosti užívaje, rozsadil všecky jiné syny své po všech krajích Judových a Beniaminových, ve všech městech ohrazených, i dal jim potravy hojně, a nabral jim mnoho žen.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 1, 'I stalo se, když utvrdil království Roboám a zmocnil je, opustil zákon Hospodinův, i všecken Izrael s ním.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 2, 'Stalo se, pravím, léta pátého království Roboámova, že vytáhl Sesák král Egyptský proti Jeruzalému, (nebo byli zhřešili proti Hospodinu),');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 3, 'S tisícem a dvěma sty vozů, a s šedesáti tisíci jízdných, a nebylo počtu lidu, kterýž přitáhl s ním z Egypta, Lubimských, Sukkimských a Chussimských.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 4, 'A pobral města hrazená, kteráž byla v Judstvu, a přitáhl až k Jeruzalému.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 5, 'Tedy Semaiáš prorok přišel k Roboámovi a k knížatům Judským, kteříž se byli sebrali do Jeruzaléma, bojíce se Sesáka, a řekl jim: Toto praví Hospodin: Vy jste mne opustili, i já také opouštím vás v rukou Sesákových.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 6, 'I ponížili se knížata Izraelská i král, a řekli: Spravedlivýť jest Hospodin.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 7, 'A když viděl Hospodin, že se ponížili, stalo se slovo Hospodinovo k Semaiášovi, řkoucí: Ponížiliť jsou se, neshladím jich, ale dám jim tudíž vysvobození, aniž se vyleje prchlivost má na Jeruzalém skrze Sesáka.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 8, 'A však sloužiti jemu budou, aby zkusili, co jest to mně sloužiti, a sloužiti králům zemským.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 9, 'A tak vstoupiv Sesák král Egytský do Jeruzaléma, pobral poklady domu Hospodinova, i poklady domu královského, všecko to pobral. Vzal i pavézy zlaté, kterýchž byl nadělal Šalomoun.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 10, 'I nadělal král Roboám místo nich pavéz měděných, a poručil je úředníkům nad drabanty, kteříž ostříhali brány domu královského.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 11, 'A když král chodíval do domu Hospodinova, přicházívali drabanti a nosili je; potom též zase přinášeli je do pokoje drabantů.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 12, 'Když se pak ponížil, odvrátila se od něho prchlivost Hospodinova, a neshladil ho do cela, tak jakož se k Judovi v dobrých věcech ohlašoval.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 13, 'Tedy zmocnil se král Roboám v Jeruzalémě a kraloval; nebo ve čtyřidcíti a v jednom létě byl Roboám, když počal kralovati, a sedmnácte let kraloval v Jeruzalémě, městě, kteréž vyvolil Hospodin ze všech pokolení Izraelských, aby tam přebývalo jméno jeho. Jméno matky jeho bylo Naama Ammonitská.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 14, 'Kterýž činil zlé věci; nebo neustavil srdce svého, aby hledal Hospodina.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 15, 'Věci pak Roboámovy, první i poslední, zdaž zapsány nejsou v knihách Semaiáše proroka, a Iddo proroka, kdež se vyčítá pořádek rodů, ano i války mezi Roboámem a Jeroboámem, po všecky dny?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 16, 'I usnul Roboám s otci svými, a pochován jest v městě Davidově, a kraloval Abiáš syn jeho místo něho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 1, 'Léta osmnáctého krále Jeroboáma kraloval Abiáš nad Judou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 2, 'Tři léta kraloval v Jeruzalémě, (a jméno matky jeho Michaia, dcera Urielova z Gabaa), a byla válka mezi Abiášem a Jeroboámem.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 3, 'Pročež sšikoval Abiáš vojsko udatných bojovníků, čtyřikrát sto tisíc mužů výborných, Jeroboám pak sšikoval se proti němu, maje osmkrát sto tisíc mužů výborných, velmi udatných.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 4, 'I postavil se Abiáš na vrchu hory Semaraim, kteráž byla mezi horami Efraimskými, a řekl: Slyšte mne, Jeroboáme i všecken Izraeli.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 5, 'Zdaliž jste neměli věděti, že Hospodin Bůh Izraelský dal království Davidovi nad Izraelem na věky, jemu i synům jeho smlouvou trvánlivou?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 6, 'Ale povstal Jeroboám syn Nebatův, služebník Šalomouna syna Davidova, a zprotivil se pánu svému.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 7, 'A sebrali se k němu lidé nevážní a bezbožní a zsilili se proti Roboámovi synu Šalomounovu, Roboám pak byv dítě a srdce choulostivého, neodepřel jim zmužile.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 8, 'Tak vy nyní myslíte zsiliti se proti království Hospodinovu, kteréž jest v ruce synů Davidových, a jest vás veliké množství; máte také při sobě telata zlatá, kterýchž vám nadělal Jeroboám, za bohy.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 9, 'Zdaliž jste nezavrhli kněží Hospodinových, synů Aronových a Levítů, a nadělali jste sobě kněží, tak jako národové jiných zemí? Kdožkoli přichází, aby posvěceny byly ruce jeho volčetem mladým a sedmi skopci, hned je knězem těch, jenž nejsou bohové.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 10, 'Ale my jsme Hospodina Boha našeho, aniž jsme se ho spustili, kněží pak přisluhující Hospodinu jsou synové Aronovi a Levítové, kteříž konají práci svou,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 11, 'A pálí Hospodinu zápaly každého jitra a každého večera, kadí také vonnými věcmi, zpořádaní také chlebů na stole čistém, a svícen zlatý s lampami jeho spravují, aby hořely každého večera. A tak my ostříháme nařízení Hospodina Boha svého, ale vy strhli jste se jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 12, 'Protož aj, s námi jest Bůh vůdce náš, a kněží jeho a trouby zvučné, aby zněly proti vám. Synové Izraelští, nebojujte s Hospodinem Bohem otců svých, nebo nepovede se vám šťastně.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 13, 'Mezi tím Jeroboám obvedl zálohy, aby po zadu na ně připadli, a tak byli Izraelští před Judskými, a zálohy ty byly jim pozadu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 14, 'Tedy spatřiv Juda, an válka jim s předu i s zadu, zvolali k Hospodinu, a kněží troubili v trouby.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 15, 'Učinili také pokřik muži Judští. I stalo se v tom pokřiku mužů Judských, ranil Bůh Jeroboáma i všecken Izrael před Abiášem a Judou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 16, 'A tak utíkali synové Izraelští před Judou, ale dal je Bůh v ruku jejich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 17, 'Nebo porazili je Abiáš a lid jeho ranou velikou, tak že padlo zbitých z Izraele pětkrát sto tisíc mužů výborných.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 18, 'Protož sníženi jsou synové Izraelští v ten čas, a zmocnili se synové Judovi, nebo zpolehli na Hospodina Boha otců svých.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 19, 'I honil Abiáš Jeroboáma, a vzal mu města, Bethel i vsi jeho, Jesana i vsi jeho, a Efron i vsi jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 20, 'Aniž se mohl zase zsiliti více Jeroboám po všecky dny Abiášovy. I ranil jej Hospodin, tak že umřel.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 21, 'Ale Abiáš zmocnil se, kterýž byl sobě pojal žen čtrnáct, a zplodil dvamecítma synů a šestnácte dcer.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 22, 'Ostatek pak činů Abiášových, a života jeho i řečí jeho, sepsáno jest v knize proroka Iddo.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 14, 1, 'Když pak usnul Abiáš s otci svými, a pochovali jej v městě Davidově, kraloval Aza syn jeho místo něho. Za jeho dnů v pokoji byla země deset let.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 14, 2, 'I činil Aza to, což se dobře líbilo Hospodinu Bohu jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 14, 3, 'Nebo zbořil oltáře cizí i výsosti, a stroskotal obrazy jejich, a posekal háje jejich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 14, 4, 'A přikázal Judovi, aby hledali Hospodina Boha otců svých, a ostříhali zákona a přikázaní jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 14, 5, 'Zkazil, pravím, po všech městech Judských výsosti a slunečné obrazy, a bylo v pokoji království za času jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 14, 6, 'Zatím vzdělal města hrazená v Judstvu, proto že v pokoji byla země, aniž jaká proti němu válka povstala těch let; nebo Hospodin dal jemu odpočinutí.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 14, 7, 'I řekl lidu Judskému: Vzdělejme ta města, a ohraďme je zdmi a věžemi, branami i závorami, dokudž země jest v moci naší. Aj, že jsme hledali Hospodina Boha svého, hledali jsme ho, a dal nám odpočinutí odevšad. A tak stavěli a šťastně se jim zvedlo.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 14, 8, 'Měl pak Aza vojsko těch, kteříž nosili štíty a kopí, z pokolení Judova třikrát sto tisíců, a z Beniaminova pavézníků a střelců dvě stě a osmdesáte tisíců. Všickni ti byli muži udatní.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 14, 9, 'I vytáhl proti nim Zerach Mouřenín, maje v vojště desetkrát sto tisíců, a vozů tři sta, a přitáhl až k Maresa.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 14, 10, 'Vytáhl též i Aza proti němu. I sšikovali vojska v údolí Sefata u Maresa.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 14, 11, 'Tedy volal Aza k Hospodinu Bohu svému, a řekl: Hospodine, neníť potřebí tobě velikého množství, když ty chceš pomoci mdlejším. Pomoziž nám, Hospodine Bože náš, neboť v tebe doufáme, a ve jménu tvém jdeme proti množství tomuto. Hospodine, ty jsi Bůh náš; nechť nemá moci proti tobě bídný člověk.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 14, 12, 'I ranil Hospodin Mouřeníny před Azou a před lidem Judským, tak že utíkali Mouřenínové.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 14, 13, 'A honil je Aza i lid, kterýž byl s ním, až do Gerar. I padli Mouřenínové, že se nijakž otaviti nemohli; nebo potříni jsou před Hospodinem a před vojskem jeho. I odnesli onino kořistí velmi mnoho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 14, 14, 'Pohubili také všecka města vůkol Gerar; strach zajisté Hospodinův připadl na ně. I vzebrali všecka města; nebo mnoho kořistí v nich bylo.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 14, 15, 'Též i obyvatele v staních při dobytcích zbili, a zajavše ovec velmi mnoho a velbloudů, navrátili se do Jeruzaléma.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 1, 'Tehdy na Azariáše syna Odedova sstoupil duch Boží.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 2, 'Pročež vyšed vstříc Azovi, řekl jemu: Slyšte mne, Azo i všecko pokolení Judovo a Beniaminovo. Hospodin byl s vámi, dokudž jste byli s ním, a budete-li ho hledati, najdete ho; pakli ho opustíte, opustíť vás.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 3, 'Po mnohé zajisté dny Izrael jest bez pravého Boha a bez kněží, učitelů i bez zákona,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 4, 'Ješto, kdyby se v úzkosti své k Hospodinu Bohu Izraelskému byli obrátili a hledali ho, byliť by ho nalezli.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 5, 'Ale časů těchto není bezpečno vycházeti ani vcházeti; nebo nepokoj veliký jest mezi všemi obyvateli země,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 6, 'Tak že šlapá národ po národu, a město po městu, proto že Bůh kormoutí je všelijakými úzkostmi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 7, 'Protož vy posilňte se, a neopouštějte rukou svých; nebo má mzdu práce vaše.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 8, 'A když slyšel Aza slova ta a proroctví Odeda proroka, posilil se, a vyplénil ohavnosti ze vší země Judské a Beniaminské, i z měst, kteráž byl vzal na hoře Efraim, a obnovil oltář Hospodinův, kterýž byl před síní Hospodinovou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 9, 'Potom shromáždil všecko pokolení Judovo i Beniaminovo, a příchozí s nimi z Efraima, Manassesa a Simeona; nebo jich bylo uteklo k němu z lidu Izraelského velmi mnoho, vidouce, že Hospodin Bůh jeho jest s ním.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 10, 'I sebrali se do Jeruzaléma třetího měsíce, patnáctého léta kralování Azova,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 11, 'A obětovali Hospodinu v ten den z kořistí přihnaných, volů sedm set a ovcí sedm tisíc.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 12, 'A vešli v smlouvu, aby hledali Hospodina Boha otců svých, z celého srdce svého a ze vší duše své,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 13, 'A kdož by koli nehledal Hospodina Boha Izraelského, aby byl usmrcen, buď malý neb veliký, buď muž neb žena.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 14, 'I přisáhli Hospodinu hlasem velikým, s zvukem na trouby i na pozouny.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 15, 'Všecken zajisté lid Judský radoval se z přísahy té; nebo celým srdcem svým přisáhli, a se vší ochotností hledali ho, a nalezli jej. I dal jim odpočinutí Hospodin se všech stran.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 16, 'Nadto i Maachu matku ssadil Aza král, aby nebyla královnou, proto že byla vzdělala v háji hroznou modlu. I podťal Aza modlu tu hroznou, a zdrobil i spálil ji při potoku Cedron.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 17, 'Ačkoli výsosti nebyly zkaženy v lidu Izraelském, srdce však Azovo bylo celé po všecky dny jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 18, 'Vnesl také ty věci, kteréž posvěceny byly od otce jeho, i to, čehož sám posvětil, do domu Božího, stříbro, zlato i nádoby.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 19, 'A nebylo války až do léta třidcátého pátého kralování Azova.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 16, 1, 'Léta třidcátého šestého kralování Azova vytáhl Báza král Izraelský proti Judovi, a stavěl Ráma, aby nedal vyjíti ani jíti k Azovi králi Judskému.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 16, 2, 'Tedy vzav Aza stříbro i zlato z pokladů domu Hospodinova i domu královského, poslal k Benadadovi králi Syrskému, kterýž bydlil v Damašku, řka:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 16, 3, 'Smlouva jest mezi mnou a mezi tebou, mezi otcem mým a mezi otcem tvým. Aj, posílámť teď stříbro a zlato, jdi, zruš smlouvu svou s Bázou králem Izraelským, ať odtrhne ode mne.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 16, 4, 'I uposlechl Benadad krále Azy, a poslal knížata s vojsky svými proti městům Izraelským. I dobyli Jon a Dan, též Abelmaim i všech měst Neftalímových, v nichž měli sklady.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 16, 5, 'To když uslyšel Báza, přestal stavěti Ráma, a zanechal díla svého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 16, 6, 'V tom Aza král pojal všecken lid Judský, a pobrali kamení z Ráma i dříví, z něhož stavěl Báza, a vystavěl z něho Gabaa a Masfa.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 16, 7, 'V ten pak čas přišel Chanani prorok k Azovi králi Judskému, a řekl jemu: Že jsi zpolehl na krále Syrského, a nezpolehl jsi na Hospodina Boha svého, proto ušlo vojsko krále Syrského z ruky tvé.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 16, 8, 'Zdaliž jsou Chussimští a Lubimští neměli vojsk velmi velikých, s vozy a jezdci náramně mnohými? A když jsi zpolehl na Hospodina, vydal je v ruku tvou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 16, 9, 'Oči zajisté Hospodinovy spatřují všecku zemi, aby dokazoval síly své při těch, kteříž jsou k němu srdce upřímého. Bláznivě jsi učinil v té věci, protož od toho času budou proti tobě války.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 16, 10, 'Tedy rozhněvav se Aza na proroka, dal ho do vězení; nebo se byl rozhněval na něj pro tu věc. A utiskal Aza některé z lidu toho času.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 16, 11, 'O jiných pak věcech Azových, prvních i posledních, zapsáno jest v knize o králích Judských a Izraelských.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 16, 12, 'Potom léta třidcátého devátého kralování svého nemocen byl Aza na nohy své těžkou nemocí, a však v nemoci své nehledal Boha, ale lékařů.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 16, 13, 'A tak usnul Aza s otci svými, a umřel léta čtyřidcátého prvního kralování svého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 16, 14, 'A pochovali jej v hrobě jeho, kterýž byl vytesal sobě v městě Davidově, a položili ho na lůžku, kteréž byl naplnil vonnými věcmi a mastmi dílem apatykářským připravenými. I pálili to jemu ohněm velmi velikým.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 1, 'I kraloval Jozafat syn jeho místo něho, a zmocnil se Izraele.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 2, 'I osadil lidem válečným všecka města hrazená v Judstvu, a postavil stráž v zemi Judské a v městech Efraim, kteráž byl zdobýval Aza otec jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 3, 'A byl Hospodin s Jozafatem; nebo chodil po cestách Davida otce svého prvních, aniž hledal modl.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 4, 'Ale Boha otce svého hledal, a v přikázaních jeho chodil, aniž následoval skutků lidu Izraelského.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 5, 'I utvrdil Hospodin království v ruce jeho, a dal všecken lid Judský dary Jozafatovi, tak že měl bohatství a slávy hojně.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 6, 'A nabyv udatného srdce k cestám Hospodinovým, zkazil přesto také i výsosti a háje v Judstvu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 7, 'Léta pak třetího království svého poslal knížata svá: Benchaile, Abdiáše, Zachariáše, Natanaele a Micheáše, aby učili v městech Judských.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 8, 'A s nimi Levíty: Semaiáše, Netaniáše, Zebadiáše, Azaele, Semiramota, Jonatana, Adoniáše, Tobiáše a Tobadoniáše, Levíty, a s nimi Elisama a Jehorama, kněží,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 9, 'Kteříž učili v Judstvu, majíce s sebou knihu zákona Hospodinova. Chodili pak vůkol po všech městech Judských, vyučujíce lid.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 10, 'I byl strach Hospodinův na všech královstvích zemí, kteréž byly vůkol Judstva, tak že nebojovali proti Jozafatovi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 11, 'Nýbrž i Filistinští přinášeli Jozafatovi dary a berni uloženou. Arabští také přiháněli jemu dobytky, skopců po sedmi tisících a sedmi stech, též kozlů po sedmi tisících a sedmi stech.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 12, 'I prospíval Jozafat, a rostl až na nejvyšší, a vystavěl v Judstvu zámky a města k skladům.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 13, 'A práci mnohou vedl při městech Judských, muže pak válečné a slovoutné měl v Jeruzalémě.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 14, 'A tento jest počet jich po domích otců jejich: Z Judy knížata nad tisíci: Adna kníže, a s ním udatných rytířů třikrát sto tisíc.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 15, 'A po něm Jochanan kníže, a s ním dvě stě a osmdesát tisíc.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 16, 'Po něm Amaziáš syn Zichrův, kterýž se dobrovolně byl oddal Hospodinu, a při něm dvakrát sto tisíc mužů udatných.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 17, 'Z Beniamina pak muž udatný Eliada, a s ním lidu zbrojného s lučišti a pavézami dvakrát sto tisíc.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 18, 'A po něm Jozabad, a s ním sto a osmdesát tisíc způsobných k boji.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 19, 'Ti sloužili králi, kromě těch, kteréž byl osadil král po městech hrazených po všem Judstvu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 1, 'I měl Jozafat bohatství a slávu velmi velikou, a spříznil se s Achabem.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 2, 'Přijel pak po letech k Achabovi do Samaří, a nabil Achab ovcí a volů hojně pro něj a pro lid, kterýž byl s ním, a namlouval ho, aby táhl do Rámot Galád.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 3, 'Nebo řekl Achab král Izraelský Jozafatovi králi Judskému: Potáhneš-li se mnou do Rámot Galád? Odpověděl jemu: Jakž jsem já, tak jsi ty, jako lid tvůj, tak lid můj, a s tebouť budu v tom boji.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 4, 'Řekl také Jozafat králi Izraelskému: Vzeptej se medle dnes na slovo Hospodinovo.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 5, 'I shromáždil král Izraelský proroků svých čtyři sta mužů, a řekl jim: Máme-li jeti do Rámot Galád na vojnu, čili tak nechati? I řekli: Táhni, nebo dá je Bůh v ruku královu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 6, 'Tedy řekl Jozafat: Což již není zde proroka Hospodinova žádného, abychom se ho zeptali?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 7, 'Odpověděl král Izraelský Jozafatovi: Ještěť jest muž jeden, skrze něhož bys se mohl poraditi s Hospodinem, ale já ho nenávidím, proto že mi nikdy nic dobrého neprorokuje, ale vždycky zlé. Ten jest Micheáš syn Jemlův. Ale Jozafat řekl: Nechť tak nemluví král.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 8, 'Protož povolav král Izraelský komorníka jednoho, řekl: Přiveď sem rychle Micheáše syna Jemlova.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 9, '(Mezi tím král Izraelský a Jozafat král Judský seděli jeden každý na stolici své, odíni jsouce rouchem. Seděli pak v placu u vrat brány Samařské, a všickni proroci prorokovali před nimi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 10, 'Kdežto Sedechiáš syn Kenanův udělal sobě byl i rohy železné, a řekl: Takto praví Hospodin: Těmito trkati budeš Syrské, dokudž jich nepohubíš.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 11, 'Tak podobně všickni proroci prorokovali, řkouce: Jeď do Rámot Galád, a šťastněť se povede; nebo dá je Hospodin v ruku královu.)');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 12, 'V tom posel ten, kterýž šel, aby zavolal Micheáše, mluvil jemu, řka: Aj, řeči proroků těch jednostejné jsou a dobré před králem. Medle, buď řeč tvá, jako řeč kterého z nich, a mluv dobré věci.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 13, 'Jemuž řekl Micheáš: Živť jest Hospodin, že cožkoli vyřkne Bůh můj, to mluviti budu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 14, 'A když přišel k králi, řekl jemu král: Micheáši, máme-li jeti proti Rámot Galád na vojnu, čili tak nechati? Kterýž řekl: Táhněte a šťastněť se vám povede, i budou dáni v ruku vaši.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 15, 'Ještě řekl jemu král: I kolikrátž tě mám přísahou zavazovati, abys mi nemluvil než pravdu ve jménu Hospodinovu?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 16, 'Protož řekl: Viděl jsem všecken lid Izraelský rozptýlený po horách jako ovce, kteréž nemají pastýře; nebo řekl Hospodin: Nemají pána tito, navrať se jeden každý do domu svého v pokoji.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 17, 'I řekl král Izraelský Jozafatovi: Zdaližť jsem neřekl, že mi nebude prorokovati nic dobrého, ale zlé?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 18, 'Řekl dále: Protož slyšte slovo Hospodinovo: Viděl jsem Hospodina sedícího na trůnu svém, a všecko vojsko nebeské stojící po pravici jeho i po levici jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 19, 'I řekl Hospodin: Kdo oklamá Achaba krále Izraelského, aby vytáhl a padl u Rámot Galád? A když pravil ten toto, a jiný pravil jiné,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 20, 'Tožť vyšel duch, a postaviv se před Hospodinem, řekl: Já ho oklamám. Hospodin pak řekl jemu: Jakým způsobem?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 21, 'Odpověděl: Vyjdu a budu duchem lživým v ústech všech proroků jeho. Kterýžto řekl: Oklamáš a dovedeš toho; jdiž a učiň tak.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 22, 'Protož aj, jižtě dal Hospodin ducha lživého v ústa proroků tvých těchto, ješto však Hospodin mluvil zlé proti tobě.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 23, 'Tedy přistoupiv Sedechiáš syn Kenanův, dal políček Micheášovi a řekl: Kterouž jest cestou odšel duch Hospodinův ode mne, aby mluvil tobě?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 24, 'Odpověděl Micheáš: Aj, uzříš v ten den, když vejdeš do nejtajnějšího pokoje, abys se skryl.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 25, 'I řekl král Izraelský: Jměte Micheáše, a doveďte ho k Amonovi hejtmanu města, a k Joasovi synu královu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 26, 'A díte: Takto praví král: Dejte tohoto do žaláře a dávejte mu jísti maličko chleba a maličko vody, dokudž se nenavrátím v pokoji.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 27, 'Ale Micheáš řekl: Jestliže se ty navrátíš v pokoji, tedyť nemluvil Hospodin skrze mne. Přesto řekl: Slyštež to všickni lidé.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 28, 'A tak táhl král Izraelský a Jozafat král Judský proti Rámot Galád.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 29, 'I řekl král Izraelský Jozafatovi: Změním já se, když půjdu k bitvě, ale ty oblec se v roucho své. I změnil se král Izraelský, a jeli k bitvě.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 30, 'Král pak Syrský přikázal byl hejtmanům nad vozy svými, řka: Nebojujte proti malému ani proti velikému, než proti samému králi Izraelskému.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 31, 'I stalo se, když hejtmané nad vozy uzřeli Jozafata, řekli: Král Izraelský jest. Takž se obrátili proti němu, aby bojovali. Tedy zkřikl Jozafat, a Hospodin spomohl jemu, a odvrátil je Bůh od něho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 32, 'Nebo uzřevše hejtmané nad vozy, že on není král Izraelský, obrátili se od něho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 33, 'Muž pak střelil z lučiště náhodou, a postřelil krále Izraelského, kdež se pancíř spojuje. Pročež řekl vozkovi: Obrať se, a vyvez mne z vojska; nebo jsem nemocen.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 34, 'I rozmohla se bitva v ten den. Král pak Izraelský stál na voze proti Syrským až do večera, i umřel v západ slunce.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 19, 1, 'Když se pak navracoval Jozafat král Judský do domu svého v pokoji do Jeruzaléma,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 19, 2, 'Vyšel jemu vstříc Jéhu syn Chananův, prorok, a řekl králi Jozafatovi: Zdaliž jsi bezbožnému měl pomáhati, a ty, jenž nenávidí Hospodina, milovati? Z té příčiny proti tobě jest hněv Hospodinův.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 19, 3, 'Ale však nalezly se věci dobré při tobě, že jsi vysekal háje z země, a nastrojil srdce své, abys hledal Boha.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 19, 4, 'I bydlil Jozafat v Jeruzalémě, a zase projel lid od Bersabé až k hoře Efraim, a navrátil je k Hospodinu Bohu otců jejich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 19, 5, 'A ustanovil soudce v zemi po všech městech Judských hrazených, v jednom každém městě.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 19, 6, 'Tedy řekl soudcům: Vizte, jak co činíte; nebo nevedete soudu za člověka, ale za Hospodina, kterýž vám přítomen jest při vykonávání soudu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 19, 7, 'A protož budiž bázeň Hospodinova při vás. Ostříhejte toho a čiňte tak, neboť není u Hospodina Boha našeho nepravosti, tak aby šetřiti měl osob, aneb přijímati dary.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 19, 8, 'Tak i v Jeruzalémě ustanovil Jozafat některé z Levítů a z kněží, a z knížat otcovských, čeledí Izraelských, k soudu Hospodinovu a k rozepřem těch, kteříž by se obraceli o to do Jeruzaléma.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 19, 9, 'A přikázal jim, řka: Takž dělejte v bázni Hospodinově, u víře a v srdci upřímém.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 19, 10, 'A při všeliké rozepři, kteráž by přišla před vás od bratří vašich, kteříž bydlí v městech svých, buď mezi krví a krví, mezi zákonem a přikázaním, ustanoveními a soudy, napomenete jich, aby nehřešili proti Hospodinu, tak aby nepřišla prchlivost na vás, ani na bratří vaše. Tak čiňte, a neuběhnete v hřích.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 19, 11, 'A aj, Amariáš, kněz nejvyšší, mezi vámi bude ve všech věcech Hospodinových, a Zebadiáš syn Izmaelův, vývoda domu Judova, ve všeliké věci královské. Máte také Levíty správce mezi sebou; posilňtež se a zmužile sobě počínejte, a budeť Hospodin s tím, kdož bude dobrý.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 1, 'I stalo se potom, že přitáhli synové Moáb a synové Ammon, a s nimi někteří od Ammonitských, proti Jozafatovi na vojnu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 2, 'A přišedše, oznámili Jozafatovi, řkouce: Přitáhlo proti tobě množství veliké z zámoří, z země Syrské, a aj, jsou v Hasesontamar, jenž jest Engadi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 3, 'I ulekl se, a obrátil Jozafat tvář svou k hledání Hospodina, a vyhlásil půst všemu lidu Judskému.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 4, 'A tak shromáždil se lid Judský, aby hledali Hospodina. Také i ze všech měst Judských sešli se hledati Hospodina.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 5, 'Tedy stál Jozafat v shromáždění Judském a Jeruzalémském, v domě Hospodinově před síní novou,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 6, 'A řekl: Hospodine, Bože otců našich, zdaliž ty sám nejsi Bohem na nebi? Zdaliž ty nepanuješ nade všemi královstvími národů? Zdaliž v ruce tvé není síly a moci, tak že není, kdo by se mohl postaviti proti tobě?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 7, 'Zdaliž jsi ty, Bože náš, nevyhnal obyvatelů země této před tváří lidu svého Izraelského, a dal jsi ji semeni Abrahama, milovníka svého na věky?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 8, 'Kteřížto bydlili v ní, a vzdělali tobě v ní svatyni, jménu tvému, řkouce:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 9, 'Jestliže by na nás přišly zlé věci, meč pomsty, buď morová rána, buď hlad, postavíme se před tímto domem a před tebou, (poněvadž jméno tvé jest v domě tomto), a budeme volati k tobě v úzkostech svých, i vyslyšíš a vysvobodíš.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 10, 'A nyní, aj, synové Ammon a Moáb, a hora Seir, skrze něž jsi nedopustil jíti Izraelovi, když se brali z země Egyptské, ale uhnuli se od nich, a nepohubili jich,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 11, 'Aj hle, oni odplacejí se nám, přitáhše, aby nás vyhnali z dědictví tvého, kteréž jsi právem dědičným dal nám.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 12, 'Bože náš, zdali jich souditi nebudeš? V násť zajisté není žádné síly proti množství tomuto velikému, kteréž táhne proti nám, aniž my víme, co bychom činiti měli, toliko na tě patří oči naše.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 13, 'Všecken také lid Judský stáli před Hospodinem, též i dítky jich, ženy i synové jejich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 14, 'Jachaziel pak syn Zachariáše syna Benaiášova, syna Jehielova, syna Mataniášova, Levíta z synů Azafových, nadšen jsa duchem Hospodinovým, u prostřed toho shromáždění,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 15, 'Řekl: Pozorujte všecken Judo a obyvatelé Jeruzalémští, i ty králi Jozafate. Takto vám praví Hospodin: Nebojte se vy, ani se lekejte množství tohoto velikého; nebo ne váš bude boj, ale Boží.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 16, 'Zítra vytáhněte proti nim, aj, oni potáhnou po stráni Ziz, a naleznete je při konci údolí naproti poušti Jeruel.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 17, 'Nebudete vy bojovati tuto. Postavte se, stůjte a vizte vysvobození Hospodinovo při sobě, ó Judo a Jeruzaléme. Nebojte se, aniž se strachujte; zítra vyjděte proti nim, a Hospodin bude s vámi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 18, 'I sklonil se Jozafat tváří k zemi, a všecken lid Judský i obyvatelé Jeruzalémští padli před Hospodinem, klanějíce se Hospodinu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 19, 'Vstali pak Levítové z synů Kahat a z synů Chóre, aby chválili Hospodina Boha Izraelského hlasem velikým a vysokým.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 20, 'Potom vstavše ráno, vytáhli na poušť Tekoe. A když vycházeli, stál Jozafat a řekl: Slyšte mne, Judo a obyvatelé Jeruzalémští. Věřte v Hospodina Boha svého, a stane se vám věrně; věřte prorokům jeho, a šťastně se vám povede.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 21, 'A tak poradiv se s lidem, postavil zpěváky Hospodinu, aby chválili okrasu svatosti, a když by vycházeli sšikovaní k boji, aby oni napřed šli a říkali: Oslavujte Hospodina, nebo na věky milosrdenství jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 22, 'Tu chvíli pak, když oni začali zpěv a chválení, obrátil Hospodin ty, kteříž byli v zálohách, na syny Ammon, Moáb a obyvatele hory Seir, ješto však byli přitáhli proti Judovi, a tak sami se bili.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 23, 'Nebo povstali synové Ammon a Moábští proti obyvatelům hory Seir, aby zmordovali a shladili je. A když dokonali boj proti obyvatelům hory Seir, pomáhali sobě a hubili jedni druhé.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 24, 'Mezi tím lid Judský přitáhl k stráži, kteráž jest na poušti, a uzřeli to množství, a aj, mrtví leží na zemi, aniž kdo ušel.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 25, 'Pročež přistoupil Jozafat s lidem svým, aby rozebrali loupeže jejich, a nalezli u nich hojnost zboží i klénotů na tělích zbitých. I rozbitovali toho mezi sebou, tak že unesti nemohli; za tři dni dělili ty loupeže, proto že jich mnoho bylo.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 26, 'V den pak čtvrtý shromáždili se do údolí Beracha, a že tu dobrořečili Hospodinu, protož nazvali jméno místa toho údolí Beracha až do dnešního dne.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 27, 'Zatím obrátili se všickni muži Judští a Jeruzalémští, a Jozafat před nimi, aby se navrátili do Jeruzaléma s veselím; nebo byl obveselil je Hospodin nad nepřátely jejich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 28, 'I vešli do Jeruzaléma s loutnami a harfami a s trubami do domu Hospodinova.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 29, 'Tedy připadl strach Boží na všecka království zemská, když uslyšeli, že Hospodin bojoval proti nepřátelům lidu Izraelského.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 30, 'A tak v pokoji bylo království Jozafatovo; nebo odpočinutí dal jemu Bůh jeho odevšad.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 31, 'Kraloval pak Jozafat nad Judou. Ve třidcíti pěti letech byl, když kralovati začal, a pětmecítma let kraloval v Jeruzalémě. Jméno matky jeho Azuba, dcera Silchi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 32, 'A chodil po cestě Azy otce svého, aniž se uchýlil od ní, čině to, což pravého jest před očima Hospodinovýma.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 33, 'A však výsosti nebyly zkaženy, nebo ještě lid byl nenastrojil srdce svého k Bohu otců svých.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 34, 'O jiných pak věcech Jozafatových, prvních i posledních, sepsáno jest v knihách Jéhu syna Chanani, kterémuž bylo poručeno, aby to vložil do knihy o králích Izraelských.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 35, 'Potom stovaryšil se Jozafat král Judský s Ochoziášem králem Izraelským, kterýž sobě bezbožně počínal.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 36, 'Stovaryšil se pak s ním proto, aby nadělal lodí, kteréž by přecházely přes moře. I nadělali lodí v Aziongaber.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 37, 'Protož prorokoval Eliezer syn Dodavahův z Maresa proti Jozafatovi, řka: Jakž jsi se stovaryšil s Ochoziášem, roztrhl Hospodin skutky tvé. I stroskotány jsou lodí, a tak nemohly se doplaviti přes moře.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 1, 'Potom usnul Jozafat s otci svými, a pochován jest s nimi v městě Davidově. I kraloval Jehoram syn jeho místo něho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 2, 'Měl pak bratří, syny Jozafatovy, Azariáše, Jechiele, Zachariáše, Azariáše, Michaele a Sefatiáše. Všickni ti byli synové Jozafata krále Izraelského.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 3, 'Kterýmž byl dal otec jejich darů mnoho, stříbra a zlata, a věcí drahých, s městy hrazenými v Judstvu, království pak dal Jehoramovi, proto že on byl prvorozený.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 4, 'I uvázal se Jehoram v království otce svého, a zmocniv se, zmordoval všecky bratří své mečem, ano i některé z knížat Izraelských.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 5, 'Ve dvou a třidcíti letech byl Jehoram, když počal kralovati, a osm let kraloval v Jeruzalémě.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 6, 'A chodil po cestě králů Izraelských, tak jako činil dům Achabův; nebo dceru Achabovu měl za manželku, a činil zlé věci před očima Hospodinovýma.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 7, 'Hospodin však nechtěl zahladiti domu Davidova, pro smlouvu, kterouž byl učinil s Davidem, a poněvadž byl řekl, že dá jemu svíci i synům jeho po všecky dny.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 8, 'Ve dnech jeho odstoupili Idumejští, aby nebyli poddáni Judovi, a ustanovili nad sebou krále.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 9, 'Pročež přitáhl Jehoram s knížaty svými, i se všemi vozy svými, a vstav v noci porazil Idumejské, kteříž jej byli obklíčili, i hejtmany vozů jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 10, 'Však předce vytáhli se Idumejští z manství Judova až do tohoto dne. Téhož času zprotivilo se i Lebno, aby nebylo pod jeho mocí, proto že opustil Hospodina Boha otců svých.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 11, 'Přesto nadělal výsostí po horách Judských, a uvedl v smilství obyvatele Jeruzalémské, nýbrž dostrčil, jako i Judské.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 12, 'I přišlo k němu psání od Eliáše proroka, řkoucího: Toto praví Hospodin Bůh Davida otce tvého: Proto že jsi nechodil po cestách Jozafata otce svého, a po cestách Azy krále Judského,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 13, 'Ale chodil jsi po cestě králů Izraelských, a uvedl jsi v smilství Judu i obyvatele Jeruzalémské, tak jako jest v smilství uvedl dům Achabův Izraele, nadto i bratří své, rodinu otce svého, lepší než jsi sám, zmordoval jsi:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 14, 'Aj, Hospodin uvede ránu velikou na lid tvůj a na syny tvé, na ženy tvé a na všecko jmění tvé,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 15, 'Ty pak nemocen budeš těžce nemocí střev svých, až z tebe vyjdou střeva tvá pro nemoc rozmáhající se den ode dne.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 16, 'A tak vzbudil Hospodin proti Jehoramovi ducha Filistinských a Arabských, kteříž jsou při končinách Chussimských.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 17, 'Kteříž vytáhše proti zemi Judské, vtrhli do ní, a rozchvátali všecko jmění, kteréž se nalezlo v domě královském, ano i syny jeho a ženy jeho, tak že mu nezůstalo žádného syna kromě Joachaza, nejmladšího z synů jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 18, 'Potom pak po všem ranil jej Hospodin na střevách jeho nemocí nezhojitelnou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 19, 'A když se to den po dni rozmáhalo, a již čas vycházel přeběhnutí dvou let, vyšla střeva jeho pro nemoc jeho, i umřel na hrozné bolesti. A nepálil mu lid jeho vonných věcí, jako pálívali otcům jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 20, 'Ve třidcíti a ve dvou letech byl, když kralovati počal, a osm let kraloval v Jeruzalémě, a sešel tak, že po něm netoužili. A však jej pochovali v městě Davidově, ale ne v hrobích královských.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 22, 1, 'Tedy ustanovili krále obyvatelé Jeruzalémští Ochoziáše, syna jeho nejmladšího, místo něho; nebo všecky starší byl pobil houf lotříků, kteříž přitáhli s Arabskými do ležení. A tak kraloval Ochoziáš syn Jehorama krále Judského.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 22, 2, 'Ve čtyřidcíti a dvou letech byl Ochoziáš, když kralovati počal, a jediný rok kraloval v Jeruzalémě. Jméno pak matky jeho Atalia dcera Amri.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 22, 3, 'I on také chodil po cestách domu Achabova, nebo matka jeho nabádala jej k nepobožnosti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 22, 4, 'Protož činil zlé věci před očima Hospodinovýma, jako dům Achabův; ty on měl zajisté rádce po smrti otce svého, k zahynutí svému.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 22, 5, 'Nebo radou jejich se spravoval, a táhl s Joramem synem Achabovým, králem Izraelským, na vojnu proti Hazaelovi králi Syrskému do Rámot Galád, kdežto ranili Syrští Jorama.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 22, 6, 'Kterýž navrátil se, aby se hojil v Jezreel; nebo měl rány, kteréž mu učinili v Ráma, když bojoval s Hazaelem králem Syrským. V tom Azariáš syn Jehorama krále Judského sstoupil, aby navštívil Jorama syna Achabova v Jezreel, kterýž tam nemocen byl.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 22, 7, 'Bylo pak to ku pádu od Boha Ochoziášovi, že přišel k Joramovi. Nebo jakž přišel, vyjel s Joramem proti Jéhu synu Namsi, kteréhož byl pomazal Hospodin, aby vyplénil dům Achabův.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 22, 8, 'Tedy stalo se, když mstil Jéhu nad domem Achabovým, že našel knížata Judská, a syny bratří Ochoziášových, kteříž sloužili Ochoziášovi, i zmordoval je.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 22, 9, 'Potom hledajíce i Ochoziáše, jali jej, an se pokrýval v Samaří, a přivedše ho k Jéhu, zabili jej a pochovali; nebo řekli: Synť jest Jozafatův, kterýž hledal Hospodina celým srdcem svým. A tak nebylo žádného více z domu Ochoziášova, kterýž by měl moc k obdržení království.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 22, 10, 'Pročež Atalia matka Ochoziášova viduci, že umřel syn její, vstavši, pomordovala všecko símě královské domu Judského.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 22, 11, 'Ale Jozabat dcera králova vzala Joasa syna Ochoziášova, a tajně ho uchvátivši z prostředku synů královských, kteříž mordováni byli, schovala jej s chůvou jeho v pokoji, kdež lůže byla. I skryla ho Jozabat dcera krále Jorama, manželka Joiady kněze, (nebo ona byla sestra Ochoziášova), před Atalií, aby ho nezamordovala.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 22, 12, 'I byl s nimi v domě Božím, skryt jsa za šest let, v nichž Atalia kralovala v té zemi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 1, 'Léta pak sedmého posilnil se Joiada, a pojal s sebou v smlouvu setníky, Azariáše syna Jerochamova, a Izmaele syna Jochananova, a Azariáše syna Obédova, a Maaseiáše syna Adaiášova, a Elizafata syna Zichri,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 2, 'Kteříž obcházejíce zemi Judskou, shromáždili Levíty ze všech měst Judských, a přední z otcovských čeledí Izraelských, a přišli do Jeruzaléma.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 3, 'I učinilo všecko to shromáždění smlouvu v domě Božím s králem. Byl pak jim řekl Joiada: Aj, syn králův kralovati bude, jakož mluvil Hospodin o synech Davidových.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 4, 'Tatoť jest věc, kterouž učiníte: Třetí díl vás, kteříž přicházíte v sobotu z kněží a z Levítů, budou vrátnými.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 5, 'Třetí pak díl bude při domě královu, a třetí díl u brány přední, ale všecken lid bude v síních domu Hospodinova.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 6, 'Aniž kdo vcházej do domu Hospodinova kromě kněží a těch Levítů, kteříž konají služby. Ti ať vcházejí, nebo svatí jsou, všecken pak lid ať drží stráž Hospodinovu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 7, 'I obstoupí Levítové krále vůkol, jeden každý maje braň svou v rukou svých, a kdož by koli všel do domu, ať umře. A buďte při králi, když bude vcházeti, i když bude vycházeti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 8, 'Tedy učinili Levítové a všecken Juda všecko, cožkoli přikázal Joiada kněz, a vzali jeden každý muže své, kteříž přicházeli v sobotu, a kteříž odcházeli v sobotu; nebo byl nepropustil Joiada kněz žádné střídy.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 9, 'I dal Joiada kněz setníkům kopí a pavézy i štíty, kteříž byli krále Davida, jenž byli v domě Božím.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 10, 'A postavil všecken lid, (a jeden každý měl braň v ruce své), od pravé strany domu až do levé strany domu, proti oltáři a proti domu, při králi všudy vůkol.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 11, 'A tak vyvedli syna králova, a vstavili na něj korunu královskou a ozdobu. I ustanovili jej králem, a pomazali ho Joiada a synové jeho, a říkali: Živ buď král!');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 12, 'V tom uslyševši Atalia hřmot sbíhajícího se lidu, a chválícího krále, vešla k lidu do domu Hospodinova.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 13, 'A když pohleděla, a aj, král stál na místě vyšším, kudyž se vchází, a knížata i trubači podlé krále, a všecken lid země veselící se, a zvučící na trouby, a zpěváci s nástroji hudebnými, a ti, kteříž předčili v zpívání. Tedy roztrhla Atalia roucho své, a řekla: Spiknutí, spiknutí!');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 14, 'Ale Joiada kněz rozkázal vyjíti setníkům, hejtmanům vojska, řka jim: Vyveďte ji prostředkem řadů, a kdož by za ní šel, ať jest zabit mečem. Nebo byl řekl kněz: Nezabijejte jí v domě Hospodinově.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 15, 'A když se jí rozstoupili s obou stran, šla, kudy se chodí k bráně koňské k domu královskému, a tu ji zabili.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 16, 'Tedy Joiada učinil smlouvu mezi Hospodinem a mezi vším lidem, i mezi králem, aby byli lid Hospodinův.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 17, 'Potom šel všecken lid do domu Bálova a zbořili jej i oltáře jeho, a obrazy stroskotali. Matana pak kněze Bálova zabili před oltáři.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 18, 'I uvedl zase Joiada úředníky domu Hospodinova pod moc kněží a Levítů, kteréž byl rozdělil David v domě Hospodinově, aby obětovali zápaly Hospodinu, (jakož psáno jest v zákoně Mojžíšově), s veselím a zpíváním podlé nařízení Davidova.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 19, 'Postavil také vrátné u vrat domu Hospodinova, aby tam nevcházel poškvrněný jakoužkoli věcí.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 20, 'A pojav setníky a znamenitější, a ty, kteříž správu drželi nad lidem, i všecken lid země, provázel krále z domu Hospodinova. I šli branou hořejší do domu královského, a posadili krále na stolici královské.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 21, 'I veselil se všecken lid země, a město se upokojilo, jakž Atalii zabili mečem.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 1, 'V sedmi letech byl Joas, když počal kralovati, a čtyřidceti let kraloval v Jeruzalémě. Jméno pak matky jeho Sebia z Bersabé.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 2, 'A činil Joas to, což pravého bylo před očima Hospodinovýma po všecky dny kněze Joiady.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 3, 'Mezi tím vzal mu Joiada dvě ženě, i plodil syny i dcery.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 4, 'Potom pak uložil v srdci Joas, aby opravil dům Hospodinův.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 5, 'I shromáždil kněží a Levíty, a řekl jim: Vyjděte do měst Judských, a vybírejte ode všeho Izraele peníze, na opravu domu Boha vašeho na každý rok, vy pak pospěšte s tou věcí. Ale nepospíchali Levítové.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 6, 'Protož povolav král Joiady, předního kněze, řekl jemu: Proč nepřídržíš Levítů, aby snesli z Judstva a z Jeruzaléma sbírku Mojžíše služebníka Hospodinova a shromáždění všeho Izraele k stánku svědectví?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 7, 'Nebo Atalia bezbožná a synové její vlámali se do domu Božího, a všecky věci posvěcené domu Hospodinova obrátili na modly.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 8, 'A tak poručil král, aby udělali jednu truhlu, a postavili ji u brány domu Hospodinova vně.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 9, 'I dali provolati v Judstvu a v Jeruzalémě, aby snesli Hospodinu sbírku Mojžíše služebníka Božího, uloženou na Izraele na poušti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 10, 'Tedy veselila se všecka knížata i všecken lid, a přinášejíce, metali do truhly, až se zpořádali.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 11, 'Bývalo pak to, že když přinášeli truhlu k úředníkům královským skrze ruce Levítů, (nebo když viděli, že mnoho jest peněz, tedy přicházel kanclíř královský a úředník nejvyššího kněze), aby vyprázdnili truhlu, potom ji zase donášeli a postavovali na místo její. A tak činívali den po dni, a sebrali peněz velmi mnoho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 12, 'Kteréž vydával král a Joiada správcům nad dílem domu Hospodinova, a oni najímali kameníky a řemeslníky k opravování domu Hospodinova, ano i kováře a kotláře k utvrzení domu Hospodinova.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 13, 'Takž dělali dělníci, a spraveno jest dílo to skrze ruce jejich, tak že přivedli zase dům Boží k způsobu jeho, a upevnili jej.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 14, 'A když dokonali, přinesli před krále a Joiadu ostatek peněz. I dal nadělati z nich nádob do domu Hospodinova, nádob k službě a obětování, a kadidlnic, i jiných nádob zlatých a stříbrných. A tak obětovávali oběti zápalné v domě Hospodinově ustavičně, po všecky dny Joiadovy.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 15, 'Potom sstaral se Joiada, pln jsa dnů, a umřel. Ve stu a ve třidcíti letech byl, když umřel.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 16, 'I pochovali ho v městě Davidově s králi, proto že činil, což dobrého jest Izraelovi, Bohu i domu jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 17, 'Po smrti pak Joiadově přišla knížata Judská, a padše, klaněli se králi. Tedy uposlechl jich král.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 18, 'Pročež opustivše dům Hospodina Boha otců svých, sloužili hájům a modlám. I rozhněval se Bůh na lid Judský a na Jeruzalém pro ten hřích jejich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 19, 'I posílal k nim proroky, aby je zase obrátili k Hospodinu. Kteřížto svědčili jim, oni však neuposlechli.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 20, 'Nýbrž, když Duch Boží vzbudil Zachariáše syna Joiady kněze, (kterýž vystoupiv před lid, mluvil jim: Takto praví Bůh: Proč přestupujete přikázaní Hospodinova? Nepovedeť se vám šťastně. Proto že jste opustili Hospodina, i on také opustí vás);');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 21, 'Oni spikše se proti němu, ukamenovali jej z rozkazu králova v síni domu Hospodinova.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 22, '(Aniž se rozpomenul Joas král na milosrdenství, kteréž byl učinil jemu Joiada otec jeho, ale zamordoval syna jeho.) Kterýž když umíral, řekl: Nechť popatří Hospodin, a vyhledá to.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 23, 'I stalo se po roce, vytáhlo proti němu vojsko Syrské a přitáhlo proti Judovi a Jeruzalému, a vyhladili z lidu všecka knížata jejich, a všecky loupeže jich poslali králi Damašskému.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 24, 'Nebo ač v malém počtu lidu bylo přitáhlo vojsko Syrské, však Hospodin dal v ruku jejich vojsko velmi veliké, proto že opustili Hospodina Boha otců svých. Ano i samého Joasa trápili.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 25, 'A jakž ti odešli od něho, (opustivše jej v těžkých nemocech), spikli se proti němu služebníci jeho pro krev synů Joiady kněze, a zamordovali jej na loži jeho. I umřel. Tedy pochovali jej v městě Davidově, ale nepochovali ho v hrobích královských.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 26, 'A tito jsou, kteříž se spikli proti němu: Zabad syn Simaty Ammonitského, a Jozabad syn Simrity Moábského.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 27, 'O synech pak jeho, a o veliké dani od něho uložené, i o stavení domu Božího, to vše sepsáno jest v knize královské. Kraloval pak Amaziáš syn jeho místo něho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 1, 'V pětmecítma letech kralovati počal Amaziáš, a kraloval dvadceti devět let v Jeruzalémě. Jméno matky jeho Joadan z Jeruzaléma.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 2, 'A činil to, což pravého bylo před očima Hospodinovýma, ale však ne srdcem upřímým.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 3, 'I stalo se, když bylo upevněno království jeho, že zmordoval služebníky své, kteříž zabili krále otce jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 4, 'A však synů jejich nekázal mordovati, ale učinil tak, jakž psáno jest v zákoně, v knize Mojžíšově, kdež přikázal Hospodin, řka: Nebudou na hrdle trestáni otcové za syny, aniž synové trestáni budou na hrdle za otce, ale jeden každý za svůj hřích umře.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 5, 'Zatím shromáždil Amaziáš lid Judský, a ustanovil po domích otcovských čeledí jejich hejtmany a setníky, po všem Judstvu a pokolení Beniaminovu, a sečtl je od dvadcítiletých a výše, a našel jich třikrát sto tisíc vybraných mužů bojovných, kopidlníků a pavézníků.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 6, 'Najal také ze mzdy z Izraele sto tisíc mužů udatných ze sta hřiven stříbra.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 7, 'Muž pak Boží přišel k němu, řka: Ó králi, nechť netáhne s tebou vojsko Izraelské; nebo Hospodin není s Izraelem, a všechněmi syny Efraimovými.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 8, 'Ale táhni ty. Učiniž tak, a posilň se k boji; jinak porazí tě Bůh před nepřátely, neboť může Bůh i pomoci i poraziti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 9, 'Tedy řekl Amaziáš muži Božímu: Jakž pak udělám s stem hřiven stříbra, kteréž jsem dal vojsku Izraelskému? Odpověděl muž Boží: Máť Hospodin mnohem více nad to, což by dal tobě.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 10, 'A tak oddělil Amaziáš vojsko to, kteréž bylo přitáhlo k němu z Efraim, aby odešli na místo své. Pročež rozhněvali se náramně na Judské a navrátili se k místu svému s velikým hněvem.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 11, 'Mezi tím Amaziáš posiliv se, vedl lid svůj, a táhl do údolí solnatého, a porazil synů Seir deset tisíců.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 12, 'Deset také tisíců živých jali synové Judští, a vedli na vrch skály, a sházeli je s vrchu té skály, tak že se všickni zrozráželi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 13, 'Vojsko pak to, kteréž zase odeslal Amaziáš, aby netáhlo s ním na vojnu, vtrhlo do měst Judských od Samaří až do Betoron, a pobivše z nich tři tisíce, nabrali loupeží mnoho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 14, 'I stalo se, když se vracel Amaziáš od porážky Idumejských, že přivezl s sebou bohy synů Seir, a vyzdvihl je sobě za bohy, a skláněl se před nimi, a kadil jim.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 15, 'A protož rozhněval se náramně Hospodin na Amaziáše, a poslal k němu proroka, kterýž jemu řekl: Proč hledáš bohů lidu toho, kteříž nevytrhli lidu svého z ruky tvé?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 16, 'Stalo se pak, když on k němu mluvil, řekl mu král: Co tě postavili, abys byl rádcím královským? Přestaniž, nechceš-li bit býti. A tak přestal prorok, však řekl: Seznávám, že tě usoudil Bůh zahladiti, poněvadž učiniv to, neuposlechl jsi rady mé.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 17, 'Tedy poradiv se Amaziáš král Judský, poslal k Joasovi synu Joachaza syna Jéhu, králi Izraelskému, řka: Nuže, pohleďme sobě v oči.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 18, 'I poslal Joas král Izraelský k Amaziášovi králi Judskému, a řekl: Bodlák, kterýž byl na Libánu, poslal k cedru Libánskému, řka: Dej dceru svou synu mému za manželku. V tom šlo tudy zvíře polní, kteréž bylo na Libánu, a pošlapalo ten bodlák.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 19, 'Myslil jsi: Aj, porazil jsem Idumejské, protož pozdvihlo tě srdce tvé, tak že se tím honosíš. Medle, zůstaň v domě svém. Proč se máš zapletati v takové zlé, až bys padl i ty i Juda s tebou?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 20, 'Ale neuposlechl Amaziáš; nebo od Boha to bylo, aby je vydal v ruku oněchno, proto že hledali bohů Idumejských.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 21, 'Takž vytáhl Joas král Izraelský, a pohleděli sobě v oči s Amaziášem králem Judským v Betsemes, kteréž jest Judovo.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 22, 'I poražen jest Juda před Izraelem, a utíkali jeden každý do příbytků svých.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 23, 'Amaziáše pak krále Judského, syna Joasova, jenž byl syn Joachazův, jal Joas král Izraelský u Betsemes, a přivedl jej do Jeruzaléma, a zbořil zdi Jeruzalémské od brány Efraim až k bráně úhlu na čtyři sta loktů.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 24, 'A pobrav všecko zlato a stříbro i všecko nádobí, kteréž se nalezlo v domě Božím u Obededoma, a v pokladích domu královského, také i ty, kteříž byli v zástavě, navrátil se do Samaří.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 25, 'Byl pak živ Amaziáš syn Joasův, král Judský, po smrti Joasa syna Joachaza, krále Izraelského, patnácte let.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 26, 'Ale o jiných činech Amaziášových, prvních i posledních, vypsáno jest v knize o králích Judských a Izraelských.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 27, 'Od toho zajisté času, jakž se spustil Amaziáš Hospodina, spikli se jedovatě proti němu v Jeruzalémě. A když utekl do Lachis, poslali za ním do Lachis, a zabili jej tam.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 28, 'A přinesše ho na koních, pochovali jej s otci jeho v městě Judově.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 1, 'Tedy všecken lid Judský vzali Uziáše, kterýž byl v šestnácti letech, a ustanovili jej za krále na místě otce jeho Amaziáše.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 2, 'Onť jest vzdělal Elot, a dobyl ho zase Judovi, když již umřel král s otci svými.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 3, 'V šestnácti letech byl Uziáš, když kralovati počal, a kraloval padesáte a dvě létě v Jeruzalémě. Jméno pak matky jeho Jecholia z Jeruzaléma.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 4, 'Ten činil to, což pravého bylo před očima Hospodinovýma, podlé všeho, což byl činil Amaziáš otec jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 5, 'A hledal s pilností Boha ve dnech Zachariáše, rozumějícího vidění Božímu, a po ty dny, v nichž hledal Hospodina, šťastný prospěch dal jemu Bůh.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 6, 'Nebo vytáh, bojoval proti Filistinským, a probořil zed města Gát, a zed města Jabne, i zed města Azotu, a vystavěl města okolo Azotu, i v zemi Filistinské.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 7, 'Bůh zajisté pomáhal jemu proti Filistinským a proti Arabským, kteříž bydlili v Gurbal, i proti Maonitským.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 8, 'I dávali Ammonitští dary Uziášovi, a rozneslo se jméno jeho až do Egypta; nebo zsilil se na nejvyšší.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 9, 'A vzdělal Uziáš věže v Jeruzalémě u brány úhlové, a u brány údolí, a u Mikzoa, i upevnil je.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 10, 'Vystavěl také věže na poušti, a vykopal studnic mnoho, proto že měl stád mnoho, jakož při údolí tak i na rovinách, oráče tolikéž a vinaře po horách i na místech úrodných; nebo laskav byl na rolí.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 11, 'Měl také Uziáš vojsko bojovníků, vycházejících k boji po houfích v jistém počtu, jakž vyčteni byli od Jehiele kanclíře, a Maaseiáše úředníka, uvedené pod správu Chananiášovi knížeti královskému.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 12, 'Všecken počet knížat čeledí otcovských, mužů udatných, dva tisíce a šest set.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 13, 'A pod spravou jejich lidu válečného třikrát sto tisíc, sedm tisíc a pět set bojovníků udatných, aby pomáhali králi proti nepříteli.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 14, 'Připravil pak Uziáš všemu tomu vojsku pavézy, kopí, lebky, pancíře, lučiště i kamení prakové.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 15, 'Nadělal také v Jeruzalémě vtipně vymyšlených nástrojů válečných, aby byli na věžech a na úhlech k střílení střelami a kamením velikým. I rozneslo se jméno jeho daleko, proto že divné pomoci měl, až se i zmocnil.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 16, 'Ale když se zmocnil, pozdvihlo se srdce jeho k zahynutí jeho, a zhřešil proti Hospodinu Bohu svému; nebo všel do chrámu Hospodinova, aby kadil na oltáři, na němž se kadívalo.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 17, 'I všel za ním Azariáš kněz, a s ním jiných kněží Hospodinových osmdesáte, mužů udatných.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 18, 'Kteříž postavili se proti Uziášovi králi, a mluvili jemu: Ne tobě, Uziáši, náleží kaditi Hospodinu, ale kněžím, synům Aronovým, kteříž posvěceni jsou, aby kadili. Vyjdiž z svatyně, nebo jsi zhřešil, aniž to bude tobě ke cti před Hospodinem Bohem.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 19, 'Pročež rozhněval se Uziáš, (v ruce pak své měl kadidlnici, aby kadil). A když se spouzel na kněží, ukázalo se malomocenství na čele jeho před kněžími v domě Hospodinově u oltáře, na němž se kadilo.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 20, 'A pohleděv na něj Azariáš, nejvyšší kněz, a všickni kněží, a aj, byl malomocný na čele svém. Protož rychle jej vyvedli ven, nýbrž i sám se nutil vyjíti, proto že ho ranil Hospodin.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 21, 'A tak byl Uziáš král malomocný až do dne smrti své, a bydlil v domě obzvláštním, jsa malomocný; nebo byl vyobcován z domu Hospodinova. Mezi tím Jotam syn jeho byl nad domem královským, soudě lid země.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 22, 'O jiných pak věcech Uziášových, prvních i posledních, psal Izaiáš prorok, syn Amosův.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 23, 'I usnul Uziáš s otci svými, a pochovali jej s otci jeho na poli hrobů královských; nebo řekli: Malomocný jest. I kraloval Jotam syn jeho místo něho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 27, 1, 'V pětmecítma letech byl Jotam, když počal kralovati, a šestnáct let kraloval v Jeruzalémě. Jméno matky jeho Jerusa dcera Sádochova.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 27, 2, 'Kterýž činil to, což pravého bylo před očima Hospodinovýma, podlé všeho, což činil Uziáš otec jeho, kromě že nevšel do chrámu Hospodinova, a lid ještě porušený byl.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 27, 3, 'On ustavěl bránu domu Hospodinova hořejší, a na zdi Ofel mnoho stavěl.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 27, 4, 'Nadto vystavěl i města na horách Judských, a v lesích zdělal zámky a věže.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 27, 5, 'On také bojoval s králem synů Ammon, a zmocnil se jich. I dali mu synové Ammon toho roku sto centnéřů stříbra, a deset tisíc měr pšenice, a ječmene deset tisíců. Tolikéž dali mu synové Ammon i léta druhého i třetího.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 27, 6, 'A tak zsilil se Jotam; nebo nastrojil cesty své před Hospodinem Bohem svým.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 27, 7, 'O jiných pak věcech Jotamových, a o všech válkách i cestách jeho, zapsáno jest v knize o králích Izraelských a Judských.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 27, 8, 'V pětmecítma letech byl, když kralovati začal, a šestnáct let kraloval v Jeruzalémě.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 27, 9, 'I usnul Jotam s otci svými, a pochovali jej v městě Davidově, a kraloval Achas syn jeho místo něho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 1, 'Ve dvadcíti letech byl Achas, když počal kralovati, a šestnácte let kraloval v Jeruzalémě, a nečinil toho, což pravého bylo před očima Hospodinovýma, jako David otec jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 2, 'Ale chodil po cestách králů Izraelských, nýbrž nadělal také slitin modlářských.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 3, 'Přesto i sám kadíval v údolí Benhinnom, a pálil syny své ohněm podlé ohavností pohanů, kteréž vyhnal Hospodin před syny Izraelskými.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 4, 'A obětoval i kadíval na výsostech a na pahrbcích, i pod každým stromem zeleným.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 5, 'Protož dal jej Hospodin Bůh jeho v ruku krále Syrského. Kteříž porazivše jej, zajali odtud množství veliké, a přivedli je do Damašku. Nad to i v ruku krále Izraelského dán jest, kterýž porazil jej porážkou velikou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 6, 'Nebo pomordoval Pekach syn Romeliášův v Judstvu sto a dvadcet tisíců dne jednoho, vše mužů udatných, proto že opustili Hospodina Boha otců svých.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 7, 'Zabil také Zichri, rytíř Efraimský Maaseiáše syna králova, a Azrikama, správce domu jeho, a Elkána, druhého po králi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 8, 'Nadto zajali též synové Izraelští z bratří svých dvakrát sto tisíc žen, synů a dcer, ano i kořistí mnoho nabrali od nich, a vezli loupež do Samaří.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 9, 'Byl pak tu prorok Hospodinův, jménem Oded, kterýž vyšed proti vojsku přicházejícímu do Samaří, řekl jim: Hle, rozhněvav se Hospodin Bůh otců vašich na Judské, vydal je v ruku vaši, a vy jste je pomordovali v prchlivosti, kteráž až k nebi dosáhla.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 10, 'A ještě Judské a Jeruzalémské myslíte sobě podrobiti za pacholky a děvky. Zdaliž i vy, i vy, jste bez hříchů proti Hospodinu Bohu vašemu?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 11, 'A protož nyní poslechněte mne, a doveďte zase zajaté, kteréž jste zajali z bratří svých; nebo jinak hněv prchlivosti Hospodinovy bude proti vám.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 12, 'Tedy povstali někteří z předních synů Efraimových: Azariáš syn Jochananův, Berechiáš syn Mesillemotův, Ezechiáš syn Sallumův, a Amaza syn Chadlaiův proti těm, kteříž se vracovali z té vojny.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 13, 'A řekli jim: Nepřivedete sem těch zajatých; nebo vinu proti Hospodinu myslíte na nás uvesti, přivětšujíce hříchů našich a provinění našich. Veliký tě zajisté hřích náš a prchlivost hněvu proti Izraelovi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 14, 'Takž nechali vojáci těch zajatých i kořistí svých před knížaty a vším shromážděním.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 15, 'A přičinivše se muži někteří ze jména znamenaní, vzali ty zajaté, a všecky, kteřížkoli z nich nebyli odění, přiodíli je z těch kořistí. A když je zobláčeli a zobouvali, nakrmili i napojili, ano i pomazali, a zprovodili na oslích, každého nemocného z nich, a dovedli ho do Jericha města palmového k bratřím jejich, potom navrátili se do Samaří.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 16, 'Toho času poslal král Achas k králům Assyrským, aby mu pomoc dali.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 17, 'Nebo ještě přitáhli i Idumejští, a zbili některé z Judských, a jiné zajali.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 18, 'Nadto i Filistinští učinili vpád do měst, na rovinách k straně polední Judstva, a vzali Betsemes a Aialon, a Gederot a Socho i vsi jeho, a Tamna i vsi jeho, a Gimzo i vsi jeho, a bydlili v nich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 19, 'Tak zajisté ponižoval Hospodin Judy pro Achasa krále Izraelského, proto že odvrátil Judu, aby naprosto převráceně činil proti Hospodinu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 20, 'A tak přitáhl k němu Tiglatfalazar král Assyrský, a více ho ssužoval, nežli mu pomáhal.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 21, 'A ačkoli Achas vzal z domu Hospodinova a domu královského, i od knížat, a dal králi Assyrskému, však nedal jemu pomoci.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 22, 'V který pak koli čas byl ssužován, tím větší převrácenost páchal proti Hospodinu. Takový byl král Achas.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 23, 'Nebo obětoval bohům Damašským, kteříž ho porazili, a řekl: Poněvadž bohové králů Syrských pomáhají jim, těm obětovati budu, aby mně pomáhali. Ale oni byli ku pádu jemu, ano i všemu Izraeli.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 24, 'Pročež shromáždiv Achas nádoby domu Božího, osekal je, a zamkl dvéře domu Hospodinova, a nadělal sobě oltářů při každém úhlu v Jeruzalémě.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 25, 'Ano i v každém městě Judském zdělal výsosti, aby kadil bohům cizím, a tak popouzel k hněvu Hospodina Boha otců svých.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 26, 'O jiných pak věcech jeho, a o všech cestách jeho, prvních i posledních zapsáno jest v knize králů Judských a Izraelských.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 27, 'I usnul Achas s otci svými, a pochovali jej v městě Jeruzalémě; nebo nevložili ho do hrobů králů Izraelských. I kraloval Ezechiáš syn jeho místo něho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 1, 'Ezechiáš kralovati počal, když byl v pětmecítma letech, a dvadceti devět let kraloval v Jeruzalémě. Jméno matky jeho bylo Abia dcera Zachariášova.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 2, 'A činil to, což pravého bylo před očima Hospodinovýma, podlé všech věcí, kteréž činil David otec jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 3, 'On prvního léta kralování svého měsíce prvního otevřel dvéře domu Hospodinova, a opravil je.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 4, 'Uvedl také kněží a Levíty, shromáždiv je do ulice východní,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 5, 'A řekl jim: Slyšte mne, Levítové. Nyní posvěťte se, posvěťte také i domu Hospodina Boha otců vašich, a vyneste nečistotu z svatyně.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 6, 'Neboť zhřešili otcové naši, a činili zlé věci před očima Hospodina Boha našeho, opouštějíce jej, a odvracujíce tvář svou od stánku Hospodinova, obracejíce se hřbetem k němu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 7, 'Zavřeli také dvéře síně, a zhasili lampy, a kadidlem nekadili, aniž zápalu obětovali v svatyni Bohu Izraelskému.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 8, 'Protož rozhněval se Hospodin na Judu a na Jeruzalém, a vydal je v posmýkání, zpuštění a ku podivení, jakož sami očima svýma vidíte.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 9, 'A aj, padli otcové naši od meče, a synové naši i dcery naše a manželky naše zajaty jsou pro tu příčinu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 10, 'Nyní tedy umínil jsem učiniti smlouvu s Hospodinem Bohem Izraelským, aby odvrátil od nás hněv prchlivosti své.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 11, 'Synové moji, nebluďtež již. Vásť jest zajisté vyvolil Hospodin, abyste stojíce před ním, sloužili jemu, a byli služebníci jeho, a kadili.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 12, 'Tedy povstali Levítové tito: Machat syn Amazai, a Joel syn Azariášův z synů Kahat; z synů pak Merari: Cis syn Abdi, a Azariáš syn Jehalleelův; a z Gersonitských: Joach syn Zimma, a Eden syn Joachův;');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 13, 'Též z synů Elizafanových: Simri a Jehiel; z synů pak Azafových: Zachariáš a Mataniáš;');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 14, 'A z synů Hémanových: Jechiel a Simei; z synů pak Jedutunových: Semaiáš a Uziel.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 15, 'I shromáždili bratří své, kteříž posvětivše se, přišli podlé rozkázaní králova a slov Hospodinových, aby vyčistili dům Hospodinův.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 16, 'A všedše kněží do domu Hospodinova, aby jej vyčistili, vynesli všelikou nečistotu, kterouž našli v chrámě Hospodinově, do síně domu Hospodinova. Levítové pak probravše to, vynesli ven ku potoku Cedron.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 17, 'Začali pak prvního dne měsíce prvního posvěcovati, a dne osmého téhož měsíce vešli do síně Hospodinovy, a posvěcovali domu Hospodinova za osm dní, a dne šestnáctého měsíce prvního dokonali.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 18, 'Tedy vešli k Ezechiášovi králi, a řekli: Vyčistili jsme všecken dům Hospodinův, i oltář zápalu, i všecky nádoby jeho, i stůl předložení a všecky nádoby jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 19, 'Všecky také nádoby, kteréž byl zavrhl král Achas za kralování svého, když převráceně činil, připravili jsme a posvětili, a aj, jsou před oltářem Hospodinovým.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 20, 'Potom vstav ráno Ezechiáš král, shromáždil úředníky města, a vstoupil do domu Hospodinova.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 21, 'A přivedli volků sedm, a skopců sedm, a beránků sedm, a kozlů sedm za hřích, za království, a za svatyni, a za Judu; a rozkázal synům Aronovým kněžím, aby obětovali na oltáři Hospodinovu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 22, 'Takž zbili voly ty, a kněží berouce krev jejich, kropili na oltář. Zbili též i skopce a pokropovali krví jejich oltáře; zbili také i beránky, a krví jejich kropili na oltář.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 23, 'Přivedli i kozly k oběti za hřích před krále i shromáždění, kteřížto vložili ruce své na ně.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 24, 'I zbili je kněží a vyčistili krví jejich oltář k očištění všeho Izraele; nebo za všecken lid Izraelský rozkázal král obětovati zápal a oběti za hřích.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 25, 'Postavil zase i Levíty v domě Hospodinově s cymbály, loutnami a harfami podlé rozkázaní Davidova, a Gáda proroka královského, a Nátana proroka; nebo od Hospodina bylo to přikázáno skrze proroky jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 26, 'A tak stáli Levítové s nástroji Davidovými a kněží s trubami.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 27, 'I rozkázal Ezechiáš, aby obětovali zápal na oltáři. A když se začala obět zápalná, začal se zpěv Hospodinův a troubení i zpěvové na nástroje Davida, krále Izraelského.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 28, 'Všecko pak shromáždění klanělo se, když zpěváci zpívali, a trubači troubili, a to vše, až se dokonal zápal.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 29, 'A když dokonali obětování zápalu, sklonili se král a všickni, kteříž byli s ním, a poklonu učinili.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 30, 'Tedy přikázal Ezechiáš král i knížata Levítům, aby chválili Hospodina slovy Davidovými a Azafa proroka. I chválili s velikým veselím, a sklánějíce se, poklonu činili.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 31, 'Potom mluvil Ezechiáš, řka: Nyní jste posvětili rukou svých Hospodinu. Přistupte, a přiveďte oběti vítězné a oběti chvály do domu Hospodinova. Protož přivodilo shromáždění to oběti vítězné a oběti chvály, ano i každý z srdce ochotného k zápalným obětem,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 32, 'Tak že počet obětí zápalných, kteréž přivedlo shromáždění to, byl volů sedmdesáte, skopců sto, beránků dvě stě, všecko to na obět zápalnou Hospodinu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 33, 'Jiných pak věcí posvěcených bylo volů šest set, a ovec tři tisíce.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 34, 'Kněží však bylo málo, tak že nemohli postačiti vytahovati z koží všech obětí zápalných. Pročež pomáhali jim bratří jejich Levítové, až i dokonali dílo to, a dokudž se neposvětili jiní kněží; nebo Levítové byli hotovější ku posvěcení se, nežli kněží.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 35, 'K tomu k zápalům bylo množství veliké tuků z obětí pokojných a obětí mokrých, kromě jiných zápalů. A tak vykonána byla služba domu Hospodinova.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 36, 'A veselil se Ezechiáš i všecken lid, že Bůh byl nastrojil lid, tak aby se ta věc rychle spravila.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 1, 'Potom poslal Ezechiáš ke všemu lidu Izraelskému a Judskému, psal také listy k Efraimovi a Manassesovi, aby přišli do domu Hospodinova do Jeruzaléma, a slavili velikunoc Hospodinu Bohu Izraelskému.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 2, 'Snesli se pak byli na tom král i knížata jeho, i všecko shromáždění v Jeruzalémě, aby slavili velikunoc měsíce druhého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 3, 'Nebo nemohli slaviti toho času, proto že kněží posvěcených se nedostávalo, aniž se lid byl shromáždil do Jeruzaléma.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 4, 'I vidělo se to za dobré králi i všemu množství,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 5, 'A usoudili, aby provolati dali po všem Izraeli, od Bersabé až do Dan, aby přišli k slavení velikonoci Hospodinu Bohu Izraelskému do Jeruzaléma; nebo již byli dávno neslavili tak, jakž psáno jest.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 6, 'Protož šli poslové s listy od krále a od knížat jeho po vší zemi Izraelské a Judské s rozkazem královským tímto: Synové Izraelští, obraťte se k Hospodinu Bohu Abrahamovu, Izákovu a Izraelovu, i obrátí se k ostatkům, kteříž jste koli znikli ruky králů Assyrských.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 7, 'A nebývejte jako otcové vaši a bratří vaši, kteříž převráceně činili proti Hospodinu Bohu otců svých, pročež dal je v zpuštění, jakž sami vidíte.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 8, 'Nyní tedy nezatvrzujte šijí svých tak, jako otcové vaši. Podejte ruky Hospodinu, a poďte do svatyně jeho, kteréž posvětil na věky, a služte Hospodinu Bohu svému, a odvrátí se od vás hněv prchlivosti jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 9, 'Nebo obrátíte-li se k Hospodinu, bratří vaši i synové vaši milosrdenství obdrží u těch, kteříž je zjímali, tak že se navrátí do země této. Milosrdný zajisté a dobrotivý jest Hospodin Bůh váš, aniž odvrátí tváři od vás, jestliže se obrátíte k němu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 10, 'Když pak ti poslové chodili z města do města po kraji Efraim a Manasse až do Zabulon, posmívali se a utrhali jim.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 11, 'Ale však někteří z Asser, Manasses a Zabulon, poníživše se, přišli do Jeruzaléma.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 12, 'V Judstvu tolikéž byla ruka Boží, tak že jim dal srdce jedno k vykonání rozkazu králova a knížat, podlé slova Hospodinova.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 13, 'I sešlo se do Jeruzaléma lidu mnoho, aby drželi slavnost přesnic měsíce druhého, shromáždění velmi veliké.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 14, 'Tedy povstavše, pobořili oltáře, kteříž byli v Jeruzalémě; též i všecky oltáře, na kterýchž se kadívalo, rozbořili a vmetali do potoka Cedron.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 15, 'Potom pak obětovali beránka velikonočního, čtrnáctého dne měsíce druhého. Kněží pak a Levítové zastyděvše se, posvětili se, a přivedli oběti do domu Hospodinova.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 16, 'A stáli v řadu svém vedlé povinnosti své podlé zákona Mojžíše muže Božího, a kněží kropili krví, berouce ji z rukou Levítů.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 17, 'Nebo mnozí byli v shromáždění, kteříž se neposvětili. Protož Levítové zabijeli beránky velikonoční za každého nečistého, k tomu, aby jich posvětili Hospodinu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 18, 'Veliký zajisté díl toho lidu, množství z Efraima, Manassesa, Izachara a Zabulona, neočistili se, a však jedli beránka velikonočního jinak než psáno jest. Ale modlil se Ezechiáš za ně, řka: Dobrotivý Hospodin očistiž toho,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 19, 'Kdožkoli celým srdcem svým se ustavil, aby hledal Boha, Hospodina Boha otců svých, byť pak i očištěn nebyl vedlé očišťování svatého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 20, 'I vyslyšel Hospodin Ezechiáše, a uzdravil lid.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 21, 'A tak drželi synové Izraelští, kteříž byli v Jeruzalémě, slavnost přesnic za sedm dní s veselím velikým, a chválili Hospodina každého dne Levítové a kněží na nástrojích sílu Hospodinovu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 22, 'Mluvil pak byl Ezechiáš přívětivě ke všechněm Levítům vyučujícím známosti pravé Hospodina. I jedli oběti slavnosti té za sedm dní, obětujíce oběti pokojné, a oslavujíce Hospodina Boha otců svých.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 23, 'Tedy sneslo se na tom všecko shromáždění, aby učinili tolikéž za druhých sedm dní. Takž slavili jiných sedm dní s radostí.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 24, 'Nebo Ezechiáš král Judský dal shromáždění tomu tisíc volků, a sedm tisíc ovec. Knížata také dala shromáždění volků tisíc, a ovec deset tisíců. A posvětilo se kněží velmi mnoho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 25, 'A tak veselilo se všecko shromáždění Judské, i kněží a Levítové a všecko shromáždění, kteréž přišlo z Izraele, i příchozí, kteříž byli přišli z země Izraelské, i obyvatelé Judští.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 26, 'A bylo veselí veliké v Jeruzalémě; nebo ode dnů Šalomouna syna Davida, krále Izraelského, nic takového nebylo v Jeruzalémě.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 27, 'Potom pak vstali kněží i Levítové, a dali požehnání lidu. I vyslyšán jest hlas jejich, a přišla modlitba jejich k příbytku svatosti Hospodinovy v nebe.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 1, 'A když se to všecko dokonalo, vyšed všecken lid Izraelský, což ho koli bylo v městech Judských, stroskotali modly a posekali háje, a pobořili výsosti a oltáře po vší zemi Judské a Beniamin, i v Efraim a Manasses, až vše dokonali. Potom navrátili se všickni synové Izraelští, jeden každý k vládařství svému do města svého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 2, 'Ezechiáš pak zase zřídil třídy kněží a Levítů podlé tříd jejich, jednoho každého podlé povinnosti přisluhování jeho, kněží a Levíty k obětem zápalným a pokojným, aby přisluhovali, a oslavovali i chválili Hospodina v branách vojska jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 3, 'Též i částka z statku královského dávána k obětování zápalů, k zápalům jitřním i večerním, též k zápalům sobotním, a na novměsíce i na slavnosti výroční, jakož psáno jest v zákoně Hospodinově.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 4, 'Přikázal také lidu přebývajícímu v Jeruzalémě, dávati díl kněžím a Levítům, aby tím ochotnější byli v zákoně Hospodinově.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 5, 'A jakž vyšel tento rozkaz, snesli synové Izraelští mnoho prvotin obilé, mstu, oleje, ovoce palmového i všech úrod polních, a desátek ze všech věcí hojný přinesli.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 6, 'Synové také Izraelští a Judští, kteříž bydlili v městech Judských, i oni desátky z skotů a bravů, a desátky svaté, posvěcené Hospodinu Bohu svému, snášeli a skládali po hromadách.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 7, 'Třetího měsíce počali zakládati těch hromad, a měsíce sedmého dokonali.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 8, 'Přišed pak Ezechiáš s knížaty, a vidouce hromady ty, dobrořečili Hospodinu a lidu jeho Izraelskému.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 9, 'I tázal se Ezechiáš kněží a Levítů o těch hromadách.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 10, 'Jemuž odpověděl Azariáš kněz nejvyšší z domu Sádochova, řka: Jakž počali těch obětí přinášeti do domu Hospodinova, jedli jsme a nasyceni jsme, a ještě zůstává hojně; nebo Hospodin požehnal lidu svému, že toho tak mnoho pozůstalo.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 11, 'Tedy rozkázal Ezechiáš nadělati špižírní při domu Hospodinovu. I nadělali,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 12, 'A snášeli tam věrně oběti a desátky, i věci posvěcené, a nad tím byl za správce Konaniáš Levíta, a Simei bratr jeho, druhý.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 13, 'Jechiel pak a Azaziáš, Nachat a Azael, a Jerimot a Jozabad, Eliel, Izmachiáš, Machat a Benaiáš, přivzati za úředníky od Konaniáše a Simei bratra jeho, podlé poručení Ezechiáše krále, a Azariáše knížete domu Božího.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 14, 'Chóre pak syn Imny, Levíta, vrátný brány východní, byl nad tím, což dobrovolně obětovali Bohu, aby rozděloval oběti Hospodinovy a věci svatosvaté.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 15, 'Jemuž ku pomoci byli Eden, Miniamin, Jesua, Semaiáš, Amariáš a Sechaniáš po městech kněžských, muži hodnověrní, aby rozdělovali bratřím svým díly, jakž velikému, tak malému,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 16, '(Mimo ty, kteříž z pokolení jejich byli pohlaví mužského, od tříletých a výše), každému vcházejícímu do domu Hospodinova ku povinnostem denním, podlé úřadů jejich, a podlé služby jich i podlé třídy jejich,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 17, 'A těm, kteříž počteni byli v rodině kněžské po čeledech otců jejich, i Levítům, ode dvadcítiletého a výše, podlé služby jich v třídách jejich,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 18, 'Též i rodině jejich, na všecky maličké jich, ženy jejich, syny jejich i dcery jejich, a všemu množství; nebo dověrně posvětili se v svatosti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 19, 'Synům také Aronovým kněžím v předměstích měst jejich po všech městech ti muži, kteříž zejména zaznamenáni jsou, dávali díly každému pohlaví mužského z kněží i každému z rodiny Levítů.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 20, 'A tak učinil Ezechiáš ve všem Judstvu, a činil, což dobrého, přímého a pravého jest před Hospodinem Bohem svým.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 21, 'A ve všelikém díle, kteréžkoli začal při službě domu Božího, a v zákoně i v přikázaní, hledaje Boha svého, celým srdcem svým to činil, a šťastně se mu vedlo.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 1, 'Po těch věcech a stálém nařízení jejich, přitáh Senacherib král Assyrský, vtrhl do Judstva, a položil se proti městům hrazeným, a uložil jich zdobývati sobě.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 2, 'Vida pak Ezechiáš, že přitáhl Senacherib, a že tvář jeho obrácena jest k boji proti Jeruzalému,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 3, 'Uradil se s knížaty a rytíři svými, aby zasypali vody studnic, kteréž byly vně za městem. I pomáhali jemu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 4, 'Nebo shromáždilo se lidu množství, a zasypali všecky studnice i potok rozvodňující se u prostřed země, řkouce: Proč přijdouce králové Assyrští, mají najíti vody tak mnoho?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 5, 'A posiliv se, vystavěl všecku zed zbořenou, a zopravoval věže, a vně zed druhou. Upevnil i Mello města Davidova, k tomu také nadělal braně velmi mnoho i pavéz.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 6, 'Zřídil též hejtmany válečné nad lidem, a shromáždil je k sobě do ulice u brány městské, a mluvil jim přívětivě, řka:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 7, 'Posilňte se a zmužile sobě počínejte, nebojte se, ani strachujte tváři krále Assyrského, ani všeho množství, kteréž jest s ním; nebo větší jest s námi, než s ním.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 8, 'S nímť jest rámě člověka, s námi pak jest Hospodin Bůh náš, ku pomoci naší a k bojování za nás. I zpolehl lid na slova Ezechiáše krále Judského.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 9, 'Potom poslal Senacherib král Assyrský služebníky své do Jeruzaléma, (sám pak ležel u Lachis, a všecko království jeho bylo s ním), k Ezechiášovi králi Judskému, i ke všemu lidu Judskému, kterýž byl v Jeruzalémě, řka:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 10, 'Takto praví Senacherib král Assyrský: V čem vy doufáte, že zůstáváte v ohradě v Jeruzalémě?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 11, 'Zdaliž Ezechiáš nenavodí vás, aby vás zmořil hladem a žízní, pravě: Hospodin Bůh náš vytrhne nás z ruky krále Assyrského?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 12, 'Zdaliž jest sám Ezechiáš nepobořil výsostí jeho a oltářů jeho, a přikázal Judovi a obyvatelům Jeruzalémským, řka: Před jedním oltářem klaněti se budete, a na něm kaditi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 13, 'Nevíte-liž, co jsem učinil já i otcové moji všechněm národům zemí? Zdaliž jak mohli bohové národů a zemí vytrhnouti země své z ruky mé?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 14, 'Kdo byl mezi všemi bohy národů těch, kteréž jsou vyplénili otcové moji, kterýž by mohl vytrhnouti lid svůj z ruky mé? Aby pak mohl Bůh váš vytrhnouti vás z ruky mé?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 15, 'Protož tedy nechť vás nesvodí Ezechiáš, ani vás namlouvá, aniž mu věřte. Kdyžtě nemohl žádný bůh všech národů a království vytrhnouti lidu svého z ruky mé, jako i z ruky otců mých, nadtoť ovšem bohové vaši nevytrhnou vás z ruky mé.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 16, 'Přes to ještě mluvili služebníci jeho i proti Hospodinu Bohu, i proti Ezechiášovi služebníku jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 17, 'Psal také listy, rouhaje se Hospodinu Bohu Izraelskému, a mluvě proti němu, řka: Jakož bohové národů zemských nevytrhli lidu svého z ruky mé, tak nevytrhne Bůh Ezechiášův lidu svého z ruky mé.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 18, 'Křičeli pak hlasem velikým Židovsky proti lidu Jeruzalémskému, kterýž byl na zdi, aby strach na ně pustili a předěsili je, aby tak vzali město.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 19, 'A tak mluvili o Bohu Jeruzalémském, jako o jiných bozích národů země, dílu rukou lidských.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 20, 'Tedy modlil se Ezechiáš král, a Izaiáš prorok syn Amosův z příčiny té, a volali k nebi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 21, 'I poslal Hospodin anděla, kterýž vyhladil každého udatného i vývodu i kníže v vojště krále Assyrského, tak že se s hanbou velikou navrátil do země své. A když všel do chrámu boha svého, ti, kteříž vyšli z života jeho, zamordovali ho tam mečem.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 22, 'A tak vysvobodil Hospodin Ezechiáše a obyvatele Jeruzalémské z ruky Senacheriba krále Assyrského, a z ruky všech, a provázel je všudy vůkol.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 23, 'Tedy mnozí přinášeli oběti Hospodinu do Jeruzaléma, ano i dary drahé Ezechiášovi králi Judskému, tak že potom vznešen jest u všech národů.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 24, 'V těch dnech roznemohl se Ezechiáš až k smrti, i modlil se Hospodinu. Kterýž promluvil k němu, a ukázal mu zázrak.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 25, 'Ale Ezechiáš nebyl vděčen dobrodiní sobě učiněného, nebo pozdvihlo se srdce jeho. Pročež povstala proti němu prchlivost, i proti Judovi a Jeruzalému.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 26, 'Ale když se pokořil Ezechiáš pro to pozdvižení srdce svého i s obyvateli Jeruzalémskými, nepřišla na ně prchlivost Hospodinova za dnů Ezechiášových.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 27, 'Měl pak Ezechiáš bohatství a slávu velmi velikou; nebo nashromáždil sobě pokladů stříbra a zlata i kamení drahého a vonných věcí, i pavéz i všelijakých klénotů.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 28, 'A měl špižírny pro úrody obilí, mstu, oleje, i stáje pro všeliká hovada a chlévy pro dobytek.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 29, 'Města také zdělal sobě, a měl bravů a skotů množství; nebo Bůh dal jemu zboží náramně veliké.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 30, 'Tentýž Ezechiáš zasypal tok vody Gihonu hořejší, a přímo vedl jej dolů k západní straně města Davidova, a šťastně se vedlo Ezechiášovi ve všech skutcích jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 31, 'Toliko při poselství knížat Babylonských poslaných k němu, aby se vyptali na zázrak, kterýž se byl stal v zemi, opustil ho Bůh, aby ho zkusil, aby známé bylo všecko, co bylo v srdci jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 32, 'Jiné pak věci Ezechiášovy i pobožnost jeho zapsány jsou v proroctví Izaiáše proroka syna Amosova, a v knize o králích Judských a Izraelských.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 33, 'I usnul Ezechiáš s otci svými, a pochovali jej výše nad hroby potomků Davidových, a učinili jemu poctivost při smrti jeho všecken Juda i obyvatelé Jeruzalémští. A kraloval Manasses syn jeho místo něho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 1, 'Ve dvanácti letech byl Manasses, když počal kralovati, a padesáte pět let kraloval v Jeruzalémě.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 2, 'Činil pak to, což jest zlého před očima Hospodinovýma, vedlé ohavností těch národů, kteréž Hospodin vyhnal před syny Izraelskými.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 3, 'Nebo vzdělal zase výsosti, kteréž byl rozbořil Ezechiáš otec jeho, a vystavěl oltáře Bálům, a vysadil háje, a klaněje se všemu vojsku nebeskému, sloužil jim.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 4, 'Vzdělal také oltáře v domě Hospodinově, o němž byl řekl Hospodin: V Jeruzalémě bude jméno mé na věky.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 5, 'Vzdělal, pravím, oltáře všemu vojsku nebeskému ve dvou síních domu Hospodinova.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 6, 'Přesto dal provoditi syny své skrze oheň v údolí Benhinnom, a šetřil času, s hadačstvím a s kouzly se obíral, a nařídil zaklinače a čarodějníky, a mnoho zlého páchal před očima Hospodinovýma, popouzeje ho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 7, 'Postavil také obraz rytý, kterýž byl udělal, v domě Božím, o kterémž byl řekl Bůh Davidovi a Šalomounovi synu jeho: V domě tomto a v Jeruzalémě, kterýž jsem vyvolil ze všech pokolení Izraelských, oslavím jméno své na věky.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 8, 'Aniž více pohnu nohou lidu Izraelského z země, kterouž jsem oddělil otcům vašim, jen toliko budou-li šetřiti, aby plnili všecko to, což jsem jim přikázal, všecken zákon, ustanovení a soudy skrze Mojžíše vydané.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 9, 'Ale Manasses uvedl v blud Judské i obyvatele Jeruzalémské, tak že činili horší věci nežli ti národové, kteréž vyplénil Hospodin před tváří synů Izraelských.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 10, 'A ačkoli mluvil Hospodin k Manassesovi a k lidu jeho, oni však nepozorovali.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 11, 'Pročež přivedl na ně Hospodin hejtmany vojska krále Assyrského, kteříž jali Manassesa v trní, a svázavše ho dvěma řetězy ocelivými, dovedli jej do Babylona.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 12, 'Tam pak jsa sevřín, modlil se Hospodinu Bohu svému, a ponižoval se velmi před oblíčejem Boha otců svých,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 13, 'A modlil se jemu. I naklonil se k němu, a vyslyšel modlitbu jeho, a uvedl jej zase do Jeruzaléma do království jeho. Tehdy poznal Manasses, že sám Hospodin jest Bohem.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 14, 'A potom vystavěl zed zevnitřní města Davidova k západní straně Gihonu potoku, až kudy se chodí k bráně rybné, a obehnal Ofel, a vyhnal ji velmi vysoko. Rozsadil také hejtmany vojska po všech městech hrazených v Judstvu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 15, 'Vymetal také bohy cizí a rytinu z domu Hospodinova, a všecky oltáře, kterýchž byl nadělal na hoře domu Hospodinova i v Jeruzalémě, a vyházel za město.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 16, 'Opravil zase i oltář Hospodinův, a obětoval na něm oběti pokojné a díkčinění, a přikázal Judským, aby sloužili Hospodinu Bohu Izraelskému.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 17, 'A však vždy ještě lid obětoval na výsostech, ale toliko Hospodinu Bohu svému.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 18, 'Jiné pak věci Manassesovy, i modlitba jeho k Bohu jeho, a slova proroků, kteříž mluvívali k němu ve jménu Hospodina Boha Izraelského, to vše zapsáno v knize o králích Izraelských.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 19, 'Modlitba pak jeho i to, že vyslyšán jest, a každý hřích jeho, i přestoupení jeho, i místa, na kterýchž byl postavil výsosti, a zdělal háje a rytiny, ještě prvé než se pokořil, to vše zapsáno jest v knihách Chozai.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 20, 'I usnul Manasses s otci svými, a pochovali jej v domě jeho, a kraloval Amon syn jeho místo něho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 21, 'Ve dvamecítma letech byl Amon, když počal kralovati, a dvě létě kraloval v Jeruzalémě.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 22, 'I činil to, což jest zlého před očima Hospodinovýma, tak jako byl činil Manasses otec jeho; nebo všechněm rytinám, kterýchž byl nadělal Manasses otec jeho, obětoval Amon a sloužil jim.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 23, 'Aniž se ponížil před Hospodinem, jako se ponížil Manasses otec jeho, nýbrž on Amon mnohem více hřešil.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 24, 'Spuntovali se pak proti němu služebníci jeho, a zamordovali jej v domě jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 25, 'Tedy pobil lid země všecky ty, kteříž se byli spuntovali proti králi Amonovi, a ustanovil lid země krále Joziáše syna jeho místo něho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 1, 'V osmi letech byl Joziáš, když kralovati počal, a kraloval jedno a třidceti let v Jeruzalémě.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 2, 'Ten činil to, což jest pravého před očima Hospodinovýma, chodě po cestách Davida otce svého, a neuchýlil se na pravo ani na levo.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 3, 'Léta zajisté osmého kralování svého, když ještě mládenček byl, počal hledati Boha Davida otce svého, dvanáctého pak léta počal vyčišťovati Judy a Jeruzaléma od výsostí, hájů, rytin a slitin.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 4, 'Nebo u přítomnosti jeho rozbořili oltáře Bálů, i obrazy slunečné, kteříž byli na nich, zpodtínal. Též i háje a rytiny, i slitiny zdrobil a setřel, a rozsypal po hrobích těch, kteříž jim obětovávali.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 5, 'Kosti pak kněží popálil na oltářích jejich, a vyčistil Judu a Jeruzalém,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 6, 'Též i města v pokolení Manasses, Efraim a Simeon, až i Neftalím i pustiny jejich vůkol.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 7, 'A tak zkazil oltáře a háje, a rytiny stroskotal na kusy, a všecky obrazy slunečné vysekal po vší zemi Izraelské. Potom navrátil se do Jeruzaléma.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 8, 'Léta pak osmnáctého kralování svého, když vyčistil zemi a dům Boží, poslal Safana syna Azaliášova, a Maaseiáše úředníka města, a Joacha syna Joachazova kanclíře, aby opraven byl dům Hospodina Boha jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 9, 'Kteříž přišedše k Helkiášovi knězi nejvyššímu, dali peníze snesené do domu Božího, kteréž byli Levítové vrátní vybrali od Manassesa a Efraima, i ode všech ostatků Izraelských, i od všeho Judy a Beniamina, a navrátili se do Jeruzaléma.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 10, 'Dali je pak v ruce správců toho díla, kteříž představeni byli nad domem Hospodinovým, a ti vydávali je dělníkům, jenž dělali v domě Hospodinově, opravujíce a utvrzujíce jej.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 11, 'I dali tesařům a stavitelům, aby najednali kamení tesaného, a dříví k vazbám i k trámům domů, kteréž byli zbořili králové Judští.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 12, 'Muži pak ti věrně se měli při té práci, nad nimiž ustanoveni Jachat a Abdiáš Levítové z synů Merari, Zachariáš a Mesullam z synů Kahat, aby s pilností přídrželi k práci. A z těch Levítů každý uměl hráti na nástroje muzické.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 13, 'Ale nad nosiči, i kteříž přídrželi dělníky ke všeliké práci, byli z Levítů písaři, úředníci a vrátní.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 14, 'A když vynášeli peníze, kteréž byli sneseny do domu Hospodinova, našel Helkiáš kněz knihu zákona Hospodinova vydaného skrze Mojžíše.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 15, 'I řekl Helkiáš k Safanovi písaři: Knihu zákona nalezl jsem v domě Hospodinově. I dal Helkiáš tu knihu Safanovi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 16, 'Safan pak přinesl tu knihu králi, a při tom jemu oznámil, řka: Všecko, cožkoli bylo poručeno služebníkům tvým, dělají.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 17, 'Nebo sebravše peníze, což se jich koli nalezlo v domě Hospodinově, vydali je v ruce úředníkům a dělníkům.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 18, 'Oznámil také Safan písař králi, řka: Knihu mi dal Helkiáš kněz. I četl v ní Safan před králem.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 19, 'Pročež když slyšel král slova zákona, roztrhl roucho své.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 20, 'A rozkázal král Helkiášovi, též Achikamovi synu Safanovu, a Abdonovi synu Míchovu, a Safanovi písaři, a Asaiášovi služebníku královskému, řka:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 21, 'Jděte, poraďte se s Hospodinem o mne i o pozůstalý lid Izraelský a Judský, z strany slov knihy této, kteráž jest nalezena; nebo veliký jest hněv Hospodinův, kterýž jest vylit na nás, proto že neostříhali otcové naši slova Hospodinova, aby činili všecko, což psáno jest v knize této.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 22, 'Tedy šli, Helkiáš a kteříž byli při králi, k Chuldě prorokyni, manželce Salluma syna Tekue, syna Chasrova, strážného nad rouchem, nebo bydlila v Jeruzalémě na druhé straně, a mluvili k ní ty věci.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 23, 'Kteráž řekla jim: Toto praví Hospodin Bůh Izraelský: Povězte muži tomu, kterýž poslal vás ke mně,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 24, 'Takto praví Hospodin: Aj, já uvedu zlé věci na toto místo a na obyvatele jeho, všecka zlořečení napsaná v knize té, kterouž čtli před králem Judským,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 25, 'Proto že opustili mne a kadili bohům cizím, aby mne popouzeli všemi skutky rukou svých. Z té příčiny vylita bude prchlivost má na toto místo, aniž bude uhašena.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 26, 'Králi pak Judskému, kterýž poslal vás, abyste se tázali Hospodina, takto povíte: Toto praví Hospodin Bůh Izraelský o slovích těch, kteráž jsi slyšel:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 27, 'Poněvadž obměkčeno jest srdce tvé, a ponížil jsi se před tváří Boží, kdyžs slyšel slova jeho proti místu tomuto a proti obyvatelům jeho, a ponižuje se přede mnou, roztrhl jsi roucho své, a plakals přede mnou, i já vyslyšel jsem tě, praví Hospodin.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 28, 'Aj, já připojím tě k otcům tvým, a pochován budeš v hrobích svých v pokoji, aby neviděly oči tvé ničeho z toho zlého, kteréž já uvedu na místo toto a na obyvatele jeho. I oznámili králi tu řeč.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 29, 'Tedy poslav král, shromáždil všecky starší Judské a Jeruzalémské.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 30, 'A vstoupil král do domu Hospodinova, a všickni muži Judští i obyvatelé Jeruzalémští, kněží, Levítové a všecken lid od velikého až do malého, i četl, aby všickni slyšeli všecka slova knihy smlouvy, kteráž byla nalezena v domě Hospodinově.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 31, 'Potom stoje král na místě svém, učinil smlouvu před Hospodinem, že bude následovati Hospodina, a ostříhati přikázaní jeho i svědectví jeho a ustanovení jeho z celého srdce svého a ze vší duše své, a plniti slova smlouvy té, kteráž jsou v té knize zapsána.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 32, 'I rozkázal, aby k témuž každý stál, kdož by koli nalezen byl v Jeruzalémě a v Beniaminovi. I činili obyvatelé Jeruzalémští podlé smlouvy Boží, Boha otců svých.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 33, 'Tehdáž také vyprázdnil Joziáš všecky ohavnosti ze všech zemí synů Izraelských, a přídržel všecky, kteřížkoli byli v Izraeli, k tomu, aby sloužili Hospodinu Bohu svému. Po všecky dny jeho neodstoupili od následování Hospodina Boha otců svých.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 1, 'Slavil také Joziáš v Jeruzalémě velikunoc Hospodinu, a zabili beránka velikonočního čtrnáctého dne měsíce prvního.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 2, 'A postaviv kněží v strážech jejich, utvrdil je v přisluhování domu Hospodinova.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 3, 'I řekl Levítům, kteříž připravovali za všecken lid Izraelský věci svaté Hospodinu: Vneste truhlu svatosti do domu, kterýž ustavěl Šalomoun syn Davidův, král Izraelský. Nebudeť vám břemenem na ramenou. A tak nyní služte Hospodinu Bohu svému a lidu jeho Izraelskému.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 4, 'A připravte se po čeledech otců svých, po třídách svých, tak jakž nařídil David král Izraelský, a podlé nařízení Šalomouna syna jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 5, 'A stůjte v svatyni podlé rozdílu čeledí otcovských, bratří národu svého, a podlé rozdělení každé čeledi otcovské Levítů.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 6, 'A tak zabíte beránka, a posvěťte se, a připravte bratřím svým, chovajíce se vedlé slova Hospodinova vydaného skrze Mojžíše.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 7, 'Daroval pak Joziáš všemu množství z stáda beránků a kozelců, vše k obětem velikonočním, podlé toho všeho, jakž postačovalo, v počtu třidcet tisíců, a skotů tři tisíce, to vše z statku královského.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 8, 'Knížata jeho také k lidu, kněžím i Levítům štědře se ukázali: Helkiáš, Zachariáš a Jechiel, přední v domě Božím, dali kněžím k obětem velikonočním dva tisíce a šest set bravů a skotů tři sta.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 9, 'Konaniáš pak s Semaiášem a Natanaelem bratřími svými, též Chasabiáš, Jehiel, Jozabad, přední z Levítů, darovali jiným Levítům k obětem velikonočním pět tisíc bravů a skotů pět set.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 10, 'A když připraveno bylo všecko k službě, stáli kněží na místě svém, a Levítové v třídách svých, podlé rozkazu královského.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 11, 'I zabijeli beránky velikonoční, kněží pak kropili krví, berouce z rukou jejich, a Levítové vytahovali z koží.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 12, 'Tedy oddělili zápal, aby dali lidu podlé rozdělení domů čeledí otcovských, tak aby obětováno bylo Hospodinu, jakž psáno jest v knize Mojžíšově. Tolikéž i s voly učinili.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 13, 'I pekli beránky velikonoční ohněm podlé obyčeje, ale jiné věci posvěcené vařili v hrncích, v kotlících a v pánvicích, a rozdávali rychle všemu lidu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 14, 'Potom pak připravili sobě a kněžím. Nebo kněží, synové Aronovi, zápaly a tuky až do noci obětovali, protož Levítové připravili sobě i kněžím, synům Aronovým.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 15, 'Též i zpěváci, synové Azafovi, stáli na místě svém podlé rozkázaní Davidova Azafovi, Hémanovi i Jedutunovi, proroku královskému, vydaného. Vrátní také při jedné každé bráně neměli odcházeti od své povinnosti, pročež bratří jejich Levítové jiní strojili jim.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 16, 'A tak nastrojena byla všecka služba Hospodinova v ten den, v slavení hodu beránka a obětování oběti zápalné na oltáři Hospodinovu, podlé rozkázaní krále Joziáše.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 17, 'I slavili synové Izraelští, což se jich našlo, hod beránka v ten čas a slavnost přesnic za sedm dní.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 18, 'Nebyla pak slavena velikanoc té podobná v Izraeli ode dnů Samuele proroka, aniž který z králů Izraelských slavil hodu beránka podobného tomu, kterýž slavil Joziáš s kněžími a Levíty, i se vším lidem Judským a Izraelským, což se ho našlo, i s obyvateli Jeruzalémskými.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 19, 'Osmnáctého léta kralování Joziášova slaven byl ten hod beránka.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 20, 'Potom po všem, když již spravil Joziáš dům Boží, přitáhl Nécho král Egyptský, aby bojoval proti Charkemis podlé Eufraten, Joziáš pak vytáhl proti němu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 21, 'Kterýž ač poslal k němu posly, řka: Já nic nemám s tebou činiti, králi Judský. Ne proti tobě, slyš ty, dnes táhnu, ale proti domu, kterýž se mnou bojuje, kamž mi rozkázal Bůh, abych pospíšil. Nebojuj s Bohem, kterýž se mnou jest, ať tě neshladí:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 22, 'Joziáš však neodvrátil tváři své od něho, ale aby bojoval s ním, změnil oděv svůj, aniž uposlechl slov Néchových, pošlých z úst Božích. A tak přitáhl, aby se s ním potýkal na poli Mageddo.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 23, 'I postřelili střelci krále Joziáše. Tedy řekl král služebníkům svým: Odvezte mne, neboť jsem velmi nemocen.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 24, 'Takž přenesli jej služebníci jeho z toho vozu, a vložili ho na druhý vůz, kterýž měl, a dovezli jej do Jeruzaléma. I umřel a pochován jest v hrobích otců svých. I plakal všecken Juda a Jeruzalém nad Joziášem.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 25, 'Naříkal také i Jeremiáš nad Joziášem, a zpívávali všickni zpěváci a zpěvakyně v naříkáních svých o Joziášovi až do dnešního dne, kteráž uvedli v obyčej Izraeli. A ta jsou zapsána v pláči Jeremiášovu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 26, 'Jiné pak věci Joziášovy, i pobožnost jeho, jakž napsáno jest v zákoně Hospodinově,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 27, 'I skutkové jeho první i poslední, to vše zapsáno jest v knize o králích Izraelských a Judských.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 1, 'Tedy vzal lid země Joachaza syna Joziášova, a ustanovili ho králem na místě otce jeho v Jeruzalémě.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 2, 'Ve třimecítma letech byl Joachaz, když počal kralovati, a tři měsíce kraloval v Jeruzalémě.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 3, 'Nebo vzal jej král Egyptský z Jeruzaléma, a uložil na zemi pokutu sto centnéřů stříbra a centnéř zlata.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 4, 'A ustanovil král Egyptský Eliakima bratra jeho nad Judou a Jeruzalémem za krále, a proměnil mu jméno jeho, aby sloul Joakim. Joachaza pak bratra jeho vzal Nécho, a zavedl ho do Egypta.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 5, 'V pětmecítma letech byl Joakim, když počal kralovati, a jedenáct let kraloval v Jeruzalémě. A když činil to, což jest zlého před očima Hospodina Boha svého,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 6, 'Přitáhl proti němu Nabuchodonozor král Babylonský, a svázal jej řetězy ocelivými, aby jej zavedl do Babylona.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 7, 'Nádoby také domu Hospodinova zavezl Nabuchodonozor do Babylona, a dal je do chrámu svého v Babyloně.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 8, 'Jiné pak věci Joakimovy i ohavnosti jeho, kteréž páchal, i což se nalézalo při něm, to vše zapsáno jest v knize o králích Izraelských a Judských. I kraloval Joachin syn jeho místo něho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 9, 'V osmi letech byl Joachin, když kralovati počal, a kraloval tři měsíce a deset dní v Jeruzalémě, a činil to, což bylo zlého před očima Hospodinovýma.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 10, 'Potom pak po roce poslal král Nabuchodonozor, a dal ho zavésti do Babylona s klénoty domu Hospodinova, a ustanovil králem Sedechiáše, příbuzného jeho, nad Judou a Jeruzalémem.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 11, 'V jedenmecítma letech byl Sedechiáš, když počal kralovati, a jedenáct let kraloval v Jeruzalémě.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 12, 'I činil to, což jest zlého před očima Hospodina Boha svého, aniž se pokořil před Jeremiášem prorokem mluvícím řeč Hospodinovu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 13, 'Nýbrž i Nabuchodonozorovi králi se zprotivil, jenž ho byl přísahou zavázal skrze Boha, a zatvrdiv šíji svou, urputně uložil v srdci svém, aby se nenavracoval k Hospodinu Bohu Izraelskému.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 14, 'Ano i všecka knížata, kněží i lid v mnohá přestoupení se vydali, podlé všech ohavností pohanských, a poškvrnili domu Hospodinova, jehož byl posvětil v Jeruzalémě.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 15, 'A když posílal Hospodin Bůh otců jejich k nim posly své, ráno vstávaje a posílaje, proto že se přívětivě měl k lidu svému a k příbytku svému:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 16, 'Posmívali se poslům Božím, a pohrdali slovy jeho, a za svůdce měli proroky jeho, až se rozpálila prchlivost Hospodinova na lid jeho, tak aby nebylo žádného uléčení.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 17, 'I přivedl na ně krále Kaldejského, kterýž zmordoval mládence jejich mečem v domě svatyně jejich, a neodpustil mládenci ani panně, starci ani kmeti. Všecky dal v ruku jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 18, 'K tomu i všecky nádoby domu Božího, veliké i malé, i poklady domu Hospodinova, i poklady královské i knížat jeho, všecko zavezl do Babylona.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 19, 'A vypálili dům Boží, a zbořili zed Jeruzalémskou, též i všecky paláce v něm popálili, ano i všelijaké klénoty drahé v něm zkazili.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 20, 'A což jich pozůstalo po meči, to převedl do Babylona, a byli služebníci jeho i synů jeho, dokudž nekraloval král Perský,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 21, 'Aby se naplnila řeč Hospodinova skrze ústa Jeremiášova, dokudž země nevykonala sobot svých; po všecky dny, pokudž byla pustá, odpočívala, až se vyplnilo sedmdesáte let.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 22, 'Potom léta prvního Cýra krále Perského, aby se naplnila řeč Hospodinova skrze ústa Jeremiášova, vzbudil Hospodin ducha Cýrova krále Perského. Kterýž dal provolati po všem království svém, ano také i rozepsal, řka:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 23, 'Toto praví Cýrus král Perský: Všecka království země dal mi Hospodin Bůh nebeský, a ten mi poručil, abych mu vystavěl dům v Jeruzalémě, kterýž jest v Judstvu. Kdo jest mezi vámi ze všeho lidu jeho, Hospodin Bůh jeho budiž s ním, a ať jde.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 1, 1, 'Léta prvního Cýra krále Perského, aby se naplnila řeč Hospodinova skrze ústa Jeremiášova, vzbudil Hospodin ducha Cýrova krále Perského, aby dal provolati po všem království svém, ano také i rozepsal, řka:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 1, 2, 'Toto praví Cýrus král Perský: Všecka království země dal mi Hospodin Bůh nebeský, a on mi poručil, abych mu vystavěl dům v Jeruzalémě, kterýž jest v Judstvu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 1, 3, 'Kdo jest mezi vámi ze všeho lidu jeho, budiž Bůh jeho s ním, a nechať jde do Jeruzaléma, kterýž jest v Judstvu, a staví dům Hospodina Boha Izraelského, toho Boha, kterýž jest v Jeruzalémě.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 1, 4, 'Kdož by pak zůstal na kterémkoli místě, kdež jest pohostinu, lidé místa toho ať mu pomohou stříbrem a zlatem, statkem i hovady, mimo oběti dobrovolné k domu Božímu, kterýž jest v Jeruzalémě.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 1, 5, 'I povstali přední z čeledí otců z pokolení Judova a Beniaminova, kněží také a Levítové i každý, číhož ducha vzbudil Bůh, aby šli k stavení domu Hospodinova, kterýž jest v Jeruzalémě.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 1, 6, 'Jimž všickni ti, kteříž bydlili okolo nich, pomáhali nádobami stříbrnými a zlatými, statkem i hovady, a věcmi drahými, mimo všecko, což dobrovolně obětováno bylo.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 1, 7, 'Král také Cýrus vydal nádoby domu Hospodinova, kteréž byl pobral Nabuchodonozor z Jeruzaléma, a dal je byl do domu Boha svého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 1, 8, 'Vydal je pak Cýrus král Perský skrze Mitridata správce nad poklady, kterýž je vyčtl Sesbazarovi knížeti Judskému.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 1, 9, 'A tento jest počet jejich: Medenic zlatých třidceti, medenic stříbrných tisíc, nožů devětmecítma.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 1, 10, 'Koflíků zlatých třidceti, koflíků stříbrných prostějších čtyři sta a deset, nádob jiných na tisíce.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 1, 11, 'Všech nádob zlatých i stříbrných pět tisíc a čtyři sta. Všecko to odnesl Sesbazar, když se stěhoval lid zajatý z Babylona do Jeruzaléma.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 1, 'Tito pak jsou lidé té krajiny, kteříž se z zajetí a přestěhování toho brali, jakž je byl přestěhoval Nabuchodonozor král Babylonský do Babylona, a navrátili se do Jeruzaléma a do Judstva, jeden každý do města svého,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 2, 'Kteříž přišli s Zorobábelem, s Jesua, s Nehemiášem, Saraiášem, Reelaiášem, Mardocheem, Bilsanem, Misparem, Bigvajem, Rechumem a Baanou. Počet mužů z lidu Izraelského:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 3, 'Synů Farosových dva tisíce, sto sedmdesáte dva.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 4, 'Synů Sefatiášových tři sta sedmdesáte dva.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 5, 'Synů Arachových sedm set sedmdesát pět.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 6, 'Synů Pachat Moábových, synů Jesue a Joábových dva tisíce, osm set a dvanácte.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 7, 'Synů Elamových tisíc, dvě stě padesáte čtyři.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 8, 'Synů Zattuových devět set čtyřidceti pět.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 9, 'Synů Zakkai sedm set a šedesát.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 10, 'Synů Báni šest set čtyřidceti dva.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 11, 'Synů Bebai šest set třimecítma.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 12, 'Synů Azgadových tisíc, dvě stě dvamecítma.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 13, 'Synů Adonikamových šest set šedesáte šest.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 14, 'Synů Bigvai dva tisíce, padesáte šest.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 15, 'Synů Adinových čtyři sta padesáte čtyři.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 16, 'Synů Aterových z Ezechiáše devadesát osm.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 17, 'Synů Bezai tři sta třimecítma.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 18, 'Synů Jorahových sto a dvanácte.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 19, 'Synů Chasumových dvě stě třimecítma.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 20, 'Synů Gibbarových devadesáte pět.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 21, 'Synů Betlémských sto třimecítma.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 22, 'Mužů Netofatských padesáte šest.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 23, 'Mužů Anatotských sto osmmecítma.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 24, 'Synů Azmavetských čtyřidceti dva.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 25, 'Synů Kariatarimských, Kafirských a Berotských sedm set čtyřidceti a tři.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 26, 'Synů Ráma a Gabaa šest set jedenmecítma.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 27, 'Mužů Michmas sto dvamecítma.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 28, 'Mužů z Bethel a Hai dvě stě třimecítma.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 29, 'Synů z Nébo padesáte dva.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 30, 'Synů Magbisových sto padesáte šest.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 31, 'Synů Elama druhého tisíc, dvě stě padesáte čtyři.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 32, 'Synů Charimových tři sta dvadceti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 33, 'Synů Lodových, Chadidových a Onových sedm set dvadceti pět.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 34, 'Synů Jerecho tři sta čtyřidceti pět.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 35, 'Synů Senaa tři tisíce, šest set a třidceti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 36, 'Kněží, synů Jedaiášových z domu Jesua, devět set sedmdesáte tři.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 37, 'Synů Immerových tisíc, padesáte dva.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 38, 'Synů Paschurových tisíc, dvě stě čtyřidceti sedm.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 39, 'Synů Charimových tisíc a sedmnácte.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 40, 'Levítů, synů Jesua a Kadmiele, synů Hodaviášových, sedmdesáte čtyři.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 41, 'Zpěváků, synů Azafových, sto dvadceti osm.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 42, 'Synů vrátných, synů Sallumových, synů Aterových, synů Talmonových, synů Akkubových, synů Chatita, synů Sobai, všech sto třidceti devět.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 43, 'Netinejských, synů Zicha, synů Chasufa, synů Tabbaot,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 44, 'Synů Keros, synů Siaha, synů Fádon,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 45, 'Synů Lebana, synů Chagaba, synů Akkub,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 46, 'Synů Chagab, synů Samlai, synů Chanan,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 47, 'Synů Giddel, synů Gachar, synů Reaia,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 48, 'Synů Rezin, synů Nekoda, synů Gazam,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 49, 'Synů Uza, synů Paseach, synů Besai,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 50, 'Synů Asna, synů Meunim, synů Nefusim,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 51, 'Synů Bakbuk, synů Chakufa, synů Charchur,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 52, 'Synů Bazlut, synů Mechida, synů Charsa,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 53, 'Synů Barkos, synů Sisera, synů Tamach,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 54, 'Synů Neziach, synů Chatifa,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 55, 'Synů služebníků Šalomounových, synů Sotai, synů Soferet, synů Feruda,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 56, 'Synů Jaala, synů Darkon, synů Giddel,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 57, 'Synů Sefatiášových, synů Chattil, synů Pocheret Hazebaim, synů Ami,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 58, 'Všech Netinejských a synů služebníků Šalomounových tři sta devadesáte dva.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 59, 'Tito také byli, kteříž šli z Telmelach, Telcharsa, Cherub, Addan a Immer, ale nemohli ukázati domu otců svých a semene svého, že by z Izraele byli:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 60, 'Synů Delaiášových, synů Tobiášových, synů Nekodových šest set padesáte dva.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 61, 'A z synů kněžských synové Chabaiášovi, synové Kózovi, synové Barzillai, kterýž pojav sobě ze dcer Barzillai Galádského manželku, nazván jest jménem jejich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 62, 'Ti vyhledávali zapsání o sobě, chtíce prokázati rod svůj, ale nenašlo se. Protož zbaveni jsou kněžství.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 63, 'A zapověděl jim Tirsata, aby nejedli z věcí svatosvatých, dokudž by nestál kněz s urim a thumim.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 64, 'Všeho toho shromáždění pospolu čtyřidceti a dva tisíce, tři sta šedesáte,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 65, 'Kromě služebníků jejich, a děvek jejich, jichž bylo sedm tisíc, tři sta třidceti sedm. A mezi nimi bylo zpěváků a zpěvakyní dvě stě.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 66, 'Koní jejich sedm set třidceti šest, mezků jejich dvě stě čtyřidceti pět.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 67, 'Velbloudů jejich čtyři sta třidceti pět, oslů šest tisíc, sedm set a dvadceti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 68, 'Z knížat pak čeledí otcovských, někteří, když přišli k domu Hospodinovu, kterýž byl v Jeruzalémě, dobrovolně se oddavše, aby stavěli dům Boží na gruntech jeho,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 69, 'Vedlé možnosti své dali náklad k dílu: Zlata jeden a šedesáte tisíc drachem, stříbra pak pět tisíc liber, a sukní kněžských sto.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 70, 'A tak osadili se kněží i Levítové a někteří z lidu, i zpěváci i vrátní a Netinejští v městech svých, i všecken Izrael v městech svých.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 3, 1, 'Když pak nastal měsíc sedmý, a byli synové Izraelští v městech, shromáždil se lid jednomyslně do Jeruzaléma.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 3, 2, 'Tedy vstav Jesua syn Jozadakův s bratřími svými kněžími, a Zorobábel syn Salatielův s bratřími svými, vzdělali oltář Boha Izraelského, aby obětovali na něm oběti zápalné, jakož psáno jest v zákoně Mojžíše muže Božího.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 3, 3, 'A když postavili oltář ten na základích jeho, ačkoli se obávali národů jiných zemí, však obětovali na něm oběti zápalné Hospodinu, oběti zápalné ráno i večer.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 3, 4, 'Drželi také slavnost stánků, jakož psáno jest, obětujíce zápal na každý den, vedlé počtu a vedlé obyčeje každého dne,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 3, 5, 'A potom obět zápalnou ustavičnou, i na novměsíce i na každou slavnost Hospodinu posvěcenou, i od každého dobrovolně obětujícího dobrovolnou obět Hospodinu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 3, 6, 'Od prvního dne toho měsíce sedmého počali obětovati zápalů Hospodinu, ačkoli chrám Hospodinův ještě nebyl založen.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 3, 7, 'I dali peníze kameníkům a řemeslníkům, též potravy a nápoje i oleje Sidonským a Tyrským, aby vezli dříví cedrové z Libánu k moři Joppen, podlé povolení jim Cýra krále Perského.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 3, 8, 'Léta pak druhého po jejich se navrácení k domu Božímu do Jeruzaléma, měsíce druhého, začali Zorobábel syn Salatielův, a Jesua syn Jozadakův, i jiní bratří jejich kněží a Levítové a všickni, kteříž byli přišli z toho zajetí do Jeruzaléma, a ustanovili Levíty od dvadcítiletých a výše, aby přihlédali k dílu domu Hospodinova.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 3, 9, 'A tak postaven jest Jesua, synové jeho i bratří jeho, Kadmiel i synové jeho, synové Judovi spolu, aby přihlédali k dílu při domě Božím, potomci Chenadadovi, synové jejich i bratří jejich Levítové.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 3, 10, 'A když zakládali grunty stavitelé chrámu Hospodinova, postavili kněží zobláčené s trubami, a Levíty, syny Azafovy s cymbály, aby chválili Hospodina vedlé nařízení Davida krále Izraelského.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 3, 11, 'I prozpěvovali jedni po druhých, chválíce a oslavujíce Hospodina, nebo dobrý jest, a že na věky trvá milosrdenství jeho nad Izraelem. Všecken také lid prokřikoval hlasem velikým, chválíce Hospodina, proto že založen byl dům Hospodinův.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 3, 12, 'Mnozí pak z kněží a z Levítů i z knížat čeledí otcovských, starci, kteříž byli viděli prvnější dům, když zakládali tento dům před očima jejich, plakali hlasem velikým. Mnozí nazpět prokřikovali s radostí hlasem velikým,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 3, 13, 'Tak že lid nemohl rozeznati hlasu prokřikování radostného od hlasu plačícího lidu; nebo lid ten prokřikoval hlasem velikým, a hlas ten slyšán byl daleko.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 1, 'Uslyšavše pak nepřátelé Judovi a Beniaminovi, že by ti, kteříž přestěhováni byli, stavěli chrám Hospodinu Bohu Izraelskému,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 2, 'Přistoupili k Zorobábelovi a k knížatům čeledí otcovských, a řekli jim: Budeme s vámi stavěti; nebo jako i vy hledati budeme Boha vašeho, jemuž i oběti obětujeme ode dnů Esarchaddona krále Assyrského, kterýž nás sem uvedl.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 3, 'Tedy řekl jim Zorobábel a Jesua i jiná knížata čeledí otcovských z Izraele: Ne vám, ale nám náleží stavěti dům Bohu našemu; nebo my sami stavěti budeme Hospodinu Bohu Izraelskému, jakž přikázal nám král Cýrus, král Perský.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 4, 'A však lid té krajiny zemdléval ruce lidu Judského, a odhrožovali je, aby nestavěli.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 5, 'Anobrž i najímali proti nim rádce, aby rušili rady jejich, po všecky dny Cýra krále Perského, až do kralování Daria krále Perského.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 6, 'Nebo když kraloval Asverus, při začátku kralování jeho sepsali žalobu proti obyvatelům Judským a Jeruzalémským.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 7, '(Tak jako za dnů Artaxerxa psal Bislam, Mitridates, Tabel a jiní tovaryši jeho k Artaxerxovi králi Perskému.) Písmo pak listu toho psáno bylo Syrsky, i vykládáno Syrsky.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 8, 'Rechum totiž kancléř a Simsai písař napsali jeden list proti Jeruzalému Artaxerxovi králi, takový:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 9, 'Rechum kancléř a Simsai písař i jiní tovaryši jejich, Dinaiští a Afarsatchaiští, Tarpelaiští, Afarzaiští, Arkevaiští, Babylonští, Susanechaiští, Dehavejští a Elmaiští,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 10, 'I jiní národové, kteréž byl převedl Asnapar veliký a slavný, a rozsadil v městech Samařských, a jiní za řekou, i Cheenetští,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 11, '(Tento jest přípis listu, kterýž poslali k Artaxerxovi králi), služebníci tvoji, lidé za řekou a Cheenetští.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 12, 'Známo buď králi, že Židé, kteříž se vrátili od tebe, přišedše k nám do Jeruzaléma, město odporné a škodlivé stavějí, i zdi dělají, a základy spojují.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 13, 'Protož nyní buď vědomo králi, bude-li to město vystaveno, a zdi dodělány, platuť, cla a úroku dávati nebudou, a tak komoře královské újma bude.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 14, 'Nyní tedy poněvadž dobrodiní paláce užíváme, na obnažování krále neslušelo se nám dívati. Tou příčinou poslali jsme a oznámili to králi,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 15, 'Aby dal hledati v knihách kronik otců svých, a najdeš v nich, i zvíš, že město to jest město odporné a škodlivé králům i krajinám, a že se v něm puntovávají od starodávna, pročež to město prvé zkaženo bylo.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 16, 'Nadto známoť činíme králi, že bude-li to město vystaveno, a zdi dodělány, tedy vládařství za řekou míti nebudeš.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 17, 'Tedy odeslal odpověd král Rechumovi kancléři a Simsaiovi písaři i jiným tovaryšům jejich, kteříž bydlili v Samaří, a jiným za řekou v Selam i v Cheet:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 18, 'Psání, kteréž jste k nám poslali, zjevně čteno jest přede mnou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 19, 'Protož rozkázal jsem, aby hledali. I nalezli, že to město zdávna povstává proti králům, a zprotivování i puntování bývají v něm.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 20, 'Nadto i králové mocní že bývali v Jeruzalémě, a panovali nade vším, co jest za řekou, jimž platové, cla a úrok dáván býval.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 21, 'Protož nyní přikažte, ať jest zastaveno mužům těm, aby to město nebylo staveno, dokudž by ode mne poručeno nebylo.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 22, 'Hleďtež pak, abyste se v té věci nemýlili, a ať skrze to nezroste něco zlého na škodu králům.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 23, 'Když pak ten přípis listu Artaxerxa krále čten byl před Rechumem a Simsaiem písařem a tovaryši jejich, odešli rychle do Jeruzaléma k Židům, a zastavili jim mocí a silou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 24, 'A tak přetrženo jest dílo domu Božího, kterýž byl v Jeruzalémě, a stálo tak až do druhého léta kralování Daria krále Perského.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 1, 'Toho času prorokoval Aggeus prorok a Zachariáš syn Iddo, proroci, Židům, kteříž byli v Judstvu a v Jeruzalémě, ve jménu Boha Izraelského mluvíce k nim.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 2, 'Tedy povstavše Zorobábel syn Salatielův, a Jesua syn Jozadakův, počali zase stavěti domu Božího, kterýž jest v Jeruzalémě, a byli s nimi proroci Boží, pomáhajíce jim.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 3, 'Téhož času přišel k nim Tattenai, vývoda za řekou, a Setarbozenai, i tovaryši jejich, kteříž takto k nim řekli: Kdo vám poručil dům tento stavěti a zdi tyto dělati?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 4, 'Tedy jsme jim řekli takto, ano i ty muže, kteří to stavení dělali, jmenovali.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 5, 'Nad staršími pak Židovskými byla ochrana Boha jejich, tak že nepřekazili jim, dokudž ta věc nepřišla před Daria, jehož tehdáž odpověd přinesli o té věci.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 6, 'Přípis listu, kterýž poslal Tattenai vývoda za řekou, a Setarbozenai s tovaryši svými, i Afarsechaiští, kteříž byli za řekou, k Dariovi králi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 7, 'List poslali jemu, a takto bylo psáno v něm: Dariovi králi pokoj všeliký.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 8, 'Známo buď králi, že jsme přišli do Judské krajiny k domu Boha velikého. Kterýžto stavějí kamením velikým, a dříví kladou do stěn, a dílo to spěšně se staví, a daří se v rukou jejich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 9, 'Tedy otázali jsme se těch starších, a takto jsme jim řekli: Kdo vám poručil stavěti dům tento, a zdi tyto dělati?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 10, 'Ano i na jména jejich ptali jsme se jich, abychom oznámili tobě, a napsali jména mužů těch, kteříž jsou přední mezi nimi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 11, 'Těmito pak slovy nám odpověděli, řkouce: My jsme služebníci Boha nebe a země, a stavíme dům, kterýž byl ustaven prvé před mnohými lety, jejž byl veliký král Izraelský stavěl i dokonal.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 12, 'Ale potom, když popudili otcové naši Boha nebeského, vydal je v ruku Nabuchodonozora krále v Babyloně, Kaldejského, kterýž dům tento zbořil, a lid převedl do Babylona.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 13, 'A však léta prvního Cýra krále Babylonského, Cýrus král rozkázal, aby tento Boží dům byl staven.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 14, 'Nadto i nádoby domu Božího zlaté a stříbrné, kteréž byl Nabuchodonozor vynesl z chrámu, jenž byl v Jeruzalémě, a vnesl je do chrámu Babylonského, i ty vynesl Cýrus král z chrámu Babylonského, a dány jsou Sesbazarovi, jehož byl vývodou ustanovil.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 15, 'A poručil mu, řka: Nádoby tyto vezma, odejdi a slož je v chrámě, kterýž jest v Jeruzalémě, a dům Boží ať stavějí na místě jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 16, 'Tedy Sesbazar ten přišed, založil grunty domu Božího, kterýž jest v Jeruzalémě, a od toho času až po dnes staví se, a ještě není dokonán.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 17, 'Nyní tedy jestli se za dobré králi vidí, nechť se pohledá mezi poklady královskými, kteříž jsou tam v Babyloně, jest-li tak, že by Cýrus král poručil, aby staven byl dům Boží tento, kterýž jest v Jeruzalémě. Potom vůli královskou nechť nám pošle o té věci.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 1, 'Tedy král Darius rozkázal, aby hledali v bibliotéce, mezi poklady složenými v Babyloně.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 2, 'I nalezena jest v Achmeta na hradě, kterýž jest v Médské krajině, jedna kniha, a takto zapsána byla v ní pamět:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 3, 'Léta prvního Cýra krále Cýrus král rozkázal: Dům Boží, kterýž byl v Jeruzalémě, ať jest v městě staven na místě, kdež se obětují oběti, a grunty jeho ať vzhůru ženou, zvýší loktů šedesáti, a zšíří loktů šedesáti,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 4, 'Třmi řady z kamení velikého, a řad z dříví nového, náklad pak z domu královského bude dáván.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 5, 'Nadto nádobí domu Božího zlaté i stříbrné, kteréž Nabuchodonozor byl pobral z chrámu, jenž byl v Jeruzalémě, a byl je přenesl do Babylona, ať zase navrátí, aby se dostalo do chrámu Jeruzalémského na místo své, a složeno bylo v domě Božím.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 6, 'Protož nyní, ty Tattenai, vývodo za řekou, Setarbozenai s tovaryši svými, i Afarsechaiští, kteříž jste za řekou, ustupte odtud.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 7, 'Nechte jich při díle toho domu Božího. Vůdce Židovský a starší jejich nechať ten dům Boží stavějí na místě jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 8, 'Ode mne také poručeno jest o tom, co byste měli činiti s staršími Židovskými při stavení toho domu Božího, totiž, aby z zboží královského, z důchodů, jenž jsou za řekou, bez meškání náklad dáván byl mužům těm, aby dílo nemělo překážky.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 9, 'A to, čehož by bylo potřebí, buď volků aneb skopců i beránků k zápalným obětem Boha nebeského, obilé, soli, vína i oleje, jakž by rozkázali kněží Jeruzalémští, nechť se jim dává na každý den, a to beze všeho podvodu,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 10, 'Aby měli z čeho obětovati vůni příjemnou Bohu nebeskému, a aby se modlili za život krále i za syny jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 11, 'Nadto ode mne jest rozkázáno: Kdož by koli zrušil přikázaní toto, aby vybořeno bylo z domu jeho dřevo, a zdviženo bylo, na němž by oběšen byl, a dům jeho ať jest hnojištěm pro takovou věc.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 12, 'Bůh pak, jehož jméno tam přebývá, zkaziž všelikého krále i lid, kterýž by vztáhl ruku svou k změnění toho, a zkáze toho domu Božího, jenž jest v Jeruzalémě. Já Darius přikazuji sám, bez meškání ať se stane.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 13, 'Tedy Tattenai, vývoda za řekou, a Setarbozenai s tovaryši svými vedlé toho, jakž rozkázal Darius král, tak učinili bez meškání.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 14, 'I stavěli starší Židovští, a šťastně se jim vedlo vedlé proroctví Aggea proroka, a Zachariáše syna Iddova. Stavěli tedy a dokonali z rozkázaní Boha Izraelského, a z rozkázaní Cýra a Daria, a Artaxerxa krále Perského.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 15, 'A dokonán jest ten dům k třetímu dni měsíce Adar, a ten byl rok šestý kralování Daria krále.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 16, 'Tedy synové Izraelští, kněží a Levítové, i jiní, kteříž byli přišli z převedení, posvětili toho domu Božího s radostí.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 17, 'A obětovali při posvěcení toho Božího domu sto telat, skopců dvě stě, beránků čtyři sta, a kozlů k oběti za hřích za všecken Izrael dvanáct, vedlé počtu pokolení Izraelského.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 18, 'I postavili kněží v třídách jejich, a Levíty v pořádcích jejich při službě Boží v Jeruzalémě, jakož psáno jest v knize Mojžíšově.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 19, 'Slavili také ti, kteříž se vrátili z přestěhování, velikunoc čtrnáctého dne měsíce prvního.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 20, 'Nebo očistili se byli kněží a Levítové jednomyslně. Všickni čistí byli, a obětovali beránka velikonočního za všecky, jenž zajati byli, i za bratří své kněží, i sami za sebe.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 21, 'A jedli synové Izraelští, kteříž se byli navrátili z přestěhování, i každý, kdož odděliv se od poškvrnění pohanů země, připojil se k nim, aby hledal Hospodina Boha Izraelského.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 22, 'Drželi také slavnost přesnic za sedm dní s veselím, proto že je rozveselil Hospodin, a obrátil srdce krále Assyrského k nim, aby jich posilnil v díle domu Božího, Boha Izraelského.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 1, 'Po těch pak věcech, za kralování Artaxerxa krále Perského, Ezdráš syn Saraiáše, syna Azariášova, syna Helkiášova,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 2, 'Syna Sallumova, syna Sádochova, syna Achitobova,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 3, 'Syna Amariášova, syna Azariášova, syna Meraiotova,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 4, 'Syna Zerachiášova, syna Uzi, syna Bukki,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 5, 'Syna Abisuova, syna Fínesova, syna Eleazarova, syna Aronova, kněze nejvyššího,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 6, 'Tento Ezdráš vyšel z Babylona, a byl člověk zběhlý v zákoně Mojžíšově, kterýž dal Hospodin Bůh Izraelský, a dal mu král podlé toho, jakž ruka Hospodina Boha jeho byla s ním, všecko, zač ho koli žádal.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 7, 'Vyšli také synové Izraelští a kněží, i Levítové a zpěváci, vrátní a Netinejští do Jeruzaléma, léta sedmého Artaxerxa krále.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 8, 'A přišel do Jeruzaléma pátého měsíce. Tenť jest rok sedmý krále Daria.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 9, 'Prvního zajisté dne měsíce prvního vyšel z Babylona, a prvního dne měsíce pátého přišel do Jeruzaléma s pomocí Boha svého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 10, 'Nebo Ezdráš byl uložil v srdci svém, aby zpytoval zákon Hospodinův i plnil jej, a aby učil lid Izraelský ustanovením a soudům.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 11, 'Tento pak jest přípis listu, kterýž dal král Artaxerxes Ezdrášovi knězi umělému v zákoně, zběhlému v těch věcech, kteréž přikázal Hospodin, a v ustanoveních jeho v Izraeli:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 12, 'Artaxerxes, král nad králi, Ezdrášovi knězi umělému v zákoně Boha nebeského, muži zachovalému i Cheenetským.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 13, 'Ode mne jest přikázáno, kdož by koli v království mém z lidu Izraelského, a z kněží jeho i z Levítů, dobrovolně jíti chtěl s tebou do Jeruzaléma, aby šel.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 14, 'Poněvadž jsi od krále a sedmi rad jeho poslán, abys dohlédal k Judstvu a k Jeruzalému podlé zákona Boha svého, kterýž máš v ruce své,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 15, 'A abys donesl stříbro a zlato, kteréž král a rady jeho dobrovolně obětovali Bohu Izraelskému, jehož příbytek jest v Jeruzalémě,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 16, 'A všecko stříbro a zlato, kteréhož bys dostal ve vší krajině Babylonské u těch, kteříž by z lidu dobrovolně co obětovati chtěli, i s kněžími, kteříž by dobrovolně obětovali k domu Boha svého, kterýž jest v Jeruzalémě,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 17, 'Abys rychle nakoupil za to stříbro telat, skopců, beránků s suchými i mokrými obětmi jejich, a obětoval je na oltáři domu Boha vašeho v Jeruzalémě.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 18, 'A což se koli tobě a bratřím tvým za dobré viděti bude, s ostatkem stříbra a zlata učiniti, vedlé vůle Boha vašeho učiňte.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 19, 'Nádoby pak, kteréžť jsou dány k službě domu Boha tvého, navrať před Bohem v Jeruzalémě,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 20, 'I jiné věci přináležející k domu Boha tvého. A což by bylo potřebí dáti, dáš z komory královské.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 21, 'A já, já Artaxerxes král poručil jsem všechněm výběrčím, kteříž jste za řekou, aby všecko, čehož by koli žádal od vás Ezdráš kněz, učitel zákona Boha nebeského, rychle se stalo,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 22, 'Až do sta centnéřů stříbra, a až do sta měr pšenice, a až do sta sudů vína, a až do sta tun oleje, a soli bez míry.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 23, 'Což by koli bylo z rozkazu Boha nebeského, nechť rychle spraví k domu Boha nebeského. Nebo proč má býti prchlivost jeho proti království královu i synům jeho?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 24, 'Také vám oznamujeme, aby na žádného z kněží a Levítů, zpěváků, vrátných, Netinejských a služebníků v domě Boha toho, platu, cla a úroku žádný úředník nevzkládal.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 25, 'Přesto, ty Ezdráši, podlé moudrosti Boha svého, kterouž jsi obdařen, nařídíš soudce a rádce, kteříž by soudili všecken lid, jenž jest za řekou, ze všech, kteříž povědomi jsou zákona Boha tvého. A kdo by neuměl, budete učiti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 26, 'Kdož by pak koli neplnil zákona Boha tvého a zákona králova, ať se i hned soud vynese o něm, buď k smrti, buďto k vypovědění jeho, neb aby na statku pokutován byl, aneb vězením trestán.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 27, 'Požehnaný Hospodin Bůh otců našich, kterýž dal to srdce královo, aby zvelebil dům Hospodinův, kterýž jest v Jeruzalémě,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 28, 'A naklonil ke mně milosrdenstvím krále i rad jeho, i všech mocných knížat královských. Protož já posilněn jsa rukou Hospodina Boha svého nade mnou, shromáždil jsem z lidu Izraelského přednější, kteříž by šli se mnou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 1, 'Tito jsou pak přednější po čeledech svých otcovských, a rod těch, kteříž vyšli se mnou za kralování Artaxerxa krále z Babylona:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 2, 'Z synů Fínesových Gersom, z synů Itamarových Daniel, z synů Davidových Chattus.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 3, 'Z synů Sechaniášových, jenž byl z synů Farosových, Zachariáš, a s ním počet mužů sto a padesáte.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 4, 'Z synů Pachat Moábových Eliehoenai syn Zerachiášův, a s ním dvě stě mužů.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 5, 'Z synů Sechaniášových syn Jachazielův, a s ním tři sta mužů.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 6, 'Z synů Adinových Ebed syn Jonatanův, a s ním padesát mužů.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 7, 'Z synů pak Elamových Izaiáš syn Ataliášův, a s ním sedmdesát mužů.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 8, 'Z synů Sefatiášových Zebadiáš syn Michaelův, a s ním osmdesáte mužů.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 9, 'Z synů Joábových Abdiáš syn Jechielův, a s ním dvě stě a osmnácte mužů.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 10, 'Z synů Selomitových syn Josifiášův, a s ním sto a šedesáte mužů.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 11, 'Z synů Bebai Zachariáš syn Bebai, a s ním osmmecítma mužů.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 12, 'Z synů Azgadových Jochanan syn Hakatanův, a s ním sto a deset mužů.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 13, 'Z synů Adonikamových poslednějších, jichž jména jsou tato: Elifelet, Jehiel, Semaiáš, a s ním šedesáte mužů.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 14, 'Z synů Bigvai Utai a Zabbud, a s nimi sedmdesáte mužů.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 15, 'Shromáždil jsem je pak u potoku, kterýž vpadá do Ahavy, a leželi jsme tu tři dni. Potom přehlédal jsem lid a kněží, a z synů Léví nenašel jsem tu žádného.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 16, 'Protož poslal jsem Eliezera, Ariele, Semaiáše, Elnatana, Jariba, Elnatana, Nátana, Zachariáše a Mesullama, přednější, a Joiariba a Elnatana, muže učené,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 17, 'A rozkázal jsem jim k Iddovi, knížeti v Chasifia místě, a naučil sem je, jak by měli mluviti k Iddovi, Achivovi a Netinejským v Chasifia místě, aby nám přivedli služebníky domu Boha našeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 18, 'I přivedli nám s pomocí Boží muže rozumného z synů Moholi, syna Léví, syna Izraelova, a Serebiáše s syny jeho, a bratří jeho osmnácte,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 19, 'A Chasabiáše, a s ním Izaiáše z synů Merari, bratří jeho a synů jejich dvadceti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 20, 'Z Netinejských pak, kteréž byl zřídil David a knížata k službě Levítům, dvě stě a dvadceti Netinejských. A ti všickni ze jména vyčteni byli.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 21, 'Tedy vyhlásil jsem tu půst u řeky Ahava, abychom se ponižovali před Bohem svým, a hledali od něho cesty přímé sobě a dítkám svým, i všemu jmění našemu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 22, 'Nebo styděl jsem se žádati od krále vojska a jízdných, aby nás bránili před nepřátely na cestě; nebo jsme byli pravili králi, řkouce: Ruka Boha našeho jest nade všemi, kteříž ho hledají upřímě, ale moc a prchlivost jeho proti všechněm, kteříž ho opouštějí.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 23, 'A když jsme se postili a hledali v tom Boha svého, tedy vyslyšel nás.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 24, 'Oddělil jsem pak přednějších kněží dvanácte: Serebiáše, Chasabiáše, a s nimi z bratří jejich deset.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 25, 'I odvážil jsem jim stříbro a zlato, a to nádobí, obět domu Boha našeho, kterouž obětovali král i rady jeho, i knížata jeho a všecken lid Izraelský, což se ho našlo.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 26, 'Odvážil jsem, pravím, do rukou jejich stříbra šest set centnéřů a padesát, a nádobí stříbrného sto centnéřů, a zlata sto centnéřů,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 27, 'A koflíků zlatých dvadceti, každý v tisíc drachem, a dvě nádoby z mosazi nejlepší, tak vzácné jako zlato.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 28, 'Potom jsem jim řekl: Vy jste posvěceni Hospodinu, i tyto nádoby posvěceny jsou, a to stříbro i zlato jest obět dobrovolná Hospodinu Bohu otců vašich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 29, 'Pilni toho buďte a ostříhejte, až to i odvážíte před kněžími přednějšími a Levíty, i předními z čeledí otcovských z Izraele v Jeruzalémě v pokojích domu Hospodinova.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 30, 'A tak přijali kněží a Levítové váhu stříbra, zlata a nádobí, aby donesli do Jeruzaléma, do domu Boha našeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 31, 'Zatím hnuli jsme se od řeky Ahava, dvanáctého dne měsíce prvního, abychom se brali do Jeruzaléma, a ruka Boha našeho byla s námi, a vytrhla nás z ruky nepřátel a úkladníků na cestě.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 32, 'I přišli jsme do Jeruzaléma, a pobyli jsme tu tři dni.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 33, 'Čtvrtého pak dne odváženo jest stříbro a zlato, a nádobí to v domě Boha našeho k ruce Meremota syna Uriáše kněze, s nímž byl Eleazar syn Fínesův, a pomocníci jejich Jozabad syn Jesua, a Noadiáš syn Binnui, Levítové,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 34, 'Vše v počtu a váze, a zapsána jest všecka ta váha toho času.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 35, 'Vrátivše se pak z zajetí ti, kteříž byli přestěhováni, obětovali zápaly Bohu Izraelskému, volků dvanáct za všecken lid Izraelský, skopců devadesát a šest, beránků sedmdesát a sedm, kozlů za hřích dvanáct, vše v obět zápalnou Hospodinu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 36, 'I dali výpovědi královy vládařům královským i vývodám za řekou. Kteříž pomocni byli lidu i domu Božímu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 1, 'A když se to vykonalo, přistoupili ke mně knížata, řkouce: Neoddělil se lid Izraelský, ani kněží a Levítové od národů zemí, ale činí podlé ohavností Kananejských, Hetejských, Ferezejských, Jebuzejských, Ammonitských, Moábských, Egyptských a Amorejských.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 2, 'Nebo nabrali sobě a synům svým dcer jejich, a smísili se símě svaté s národy zemí, a knížata a vrchnost první byla v tom přestoupení.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 3, 'Kteroužto věc když jsem uslyšel, roztrhl jsem roucho své i plášť, a trhal jsem vlasy s hlavy své i z brady, a seděl jsem zděšený.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 4, 'I shromáždili se ke mně všickni, třesoucí se před řečmi Boha Izraelského pro přestoupení lidu přestěhovaného, já pak seděl jsem zděšený, až do oběti večerní.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 5, 'Ale v čas oběti večerní vstal jsem od trápení svého, maje na sobě roucho roztržené i plášť svůj, a klekl jsem na kolena svá, rozprostíraje ruce své k Hospodinu Bohu svému.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 6, 'A řekl jsem: Bože můj, stydím se a hanbím pozdvihnouti, Bože můj, tváři své k tobě; nebo nepravosti naše rozmnožily se nad hlavou, a provinění naše vzrostlo až k nebi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 7, 'Ode dnů otců našich u veliké jsme vině až do tohoto dne, a pro nepravosti naše vydáni jsme my, králové naši i kněží naši v ruku králů zemí pod meč, v zajetí a v loupež, a v zahanbení tváři, tak jakž se to nyní děje.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 8, 'Teď pak rychle stala se nám milost od Hospodina Boha našeho, že zanechal nám ostatků, a dal nám obydlí na místě svatém, aby osvítil oči naše Bůh náš, a dal nám maličké povydchnutí od služby naší.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 9, 'Nebo ač jsme byli služebníci, však nenechal nás Bůh náš v porobě naší, ale naklonil k nám milostí krále Perské, dav nám život, abychom vyzdvihli dům Boha našeho, a zase obnovili pustiny jeho, nýbrž ohradil nás v Judstvu a v Jeruzalémě.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 10, 'Nyní tedy což díme, ó Bože náš, po těch věcech, poněvadž jsme opustili přikázaní tvá,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 11, 'Kteráž jsi vydal skrze služebníky své proroky, řka: Země ta, do kteréž jdete, abyste jí dědičně vládli, jest země nečistá, pro nečistotu národů těch zemí, pro ohavnosti jejich, kterýmiž ji naplnili všudy naskrze v nečistotě své.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 12, 'Protož nyní dcer vašich nedávejte synům jejich, a dcer jejich nebeřte synům vašim, a nehledejte pokoje jejich a dobrého jejich, až na věky, abyste se zmocnili, a jedli dobré věci země, a k dědičnému vládařství zanechali ji synům svým až na věky.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 13, 'Po všech pak těch věcech, kteréž na nás přišly pro zlé skutky naše, a pro veliké naše provinění, poněvadž ty, Bože náš, netrestal jsi nás podlé nepravostí našich, a dal jsi nám vysvobození takové,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 14, 'Opět-liž bychom rušiti měli tvá přikázaní, a přízniti se s národy těmito ohavnými? Zdaliž bys se zůřivě nehněval na nás, až bys nás do konce vyhladil, tak že by žádný nezůstal a neušel?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 15, 'Hospodine Bože Izraelský, ty jsi spravedlivý; nebo jsme pozůstali ostatkové, jakž se to vidí dnešního dne. Aj, my jsme před tebou s proviněním svým, ač bychom neměli postavovati se před tváří tvou pro věci takové.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 1, 'Když se pak Ezdráš, padna před domem Božím, tak modlil a vyznával s pláčem, sešel se k němu z lidu Izraelského zástup velmi veliký mužů i žen i dětí. A když plakal lid pláčem velikým,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 2, 'Tedy mluvil Sechaniáš syn Jechielův z synů Elamových, a řekl Ezdrášovi: Myť jsme zhřešili proti Bohu svému, že jsme pojímali ženy cizozemky z národů zemí, a však vždy Izrael může míti naději při té věci.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 3, 'Nyní tedy vejděme v smlouvu s Bohem svým, zapudíce všecky ženy i syny jejich podlé rady Páně a těch, jenž se třesou před přikázaním Boha našeho, a tak podlé zákona ať se stane.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 4, 'Vstaň, nebo na tobě jest ta věc, a my budeme při tobě. Posilň se a učiň tak.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 5, 'I vstal Ezdráš a zavázal přísahou přednější kněží a Levíty a všecken lid Izraelský, aby tak učinili. I přisáhli.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 6, 'A vstav Ezdráš od domu Božího, odšel do pokojíka Jochananova, syna Eliasibova, i všel tam, a nejedl chleba, ani vody nepil; nebo zámutek měl pro přestoupení těch, jenž se přestěhovali.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 7, 'Zatím dali provolati v Judstvu a v Jeruzalémě všechněm přestěhovaným, aby se shromáždili do Jeruzaléma,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 8, 'Kdo by pak koli nepřišel ve třech dnech, podlé rady knížat a starších, aby všecken statek svůj propadl, a sám odloučen byl od shromáždění přestěhovaných.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 9, 'A protož shromáždili se všickni muži Judští i Beniamin do Jeruzaléma ke dni třetímu, dvadcátého dne měsíce, (a ten měsíc byl devátý). I seděl všecken lid na ulici domu Božího, třesouce se pro tu věc i pro déšť.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 10, 'Tedy vyvstal Ezdráš kněz a řekl k nim: Vy jste zhřešili, že jste pojímali ženy cizozemky, abyste přidali k provinění lidu Izraelského.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 11, 'Protož již vyznejte se Hospodinu Bohu otců svých, a čiňte vůli jeho, a oddělte se od národů cizích, i od žen cizozemek.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 12, 'I odpovědělo všecko to shromáždění, a řekli hlasem velikým: Podlé slova tvého povinni jsme tak učiniti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 13, 'Ale lidu mnoho jest, a prška, a nemůžeme vně státi. K tomu není ta práce jednoho dne ani dvou, nebo mnoho jest nás, kteříž jsme v tom přestoupili.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 14, 'Nechť jsou postavena, prosíme, knížata naše ze všeho shromáždění, a kdož koli jest v městech našich, kterýž pojal ženy cizozemky, ať přijde v čas uložený, a s nimi starší z jednoho každého města i soudcové jejich, až bychom tak odvrátili hněv prchlivosti Boha našeho od sebe pro tu věc.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 15, 'Takž Jonatan syn Azahelův, a Jachziáš syn Tekue, postaveni byli nad tím, Mesullam pak a Sabbetai, Levítové, pomáhali jim.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 16, 'Tedy učinili tak při těch, jenž přestěhováni byli. I odděleni jsou Ezdráš kněz a muži přední čeledí otcovských po domích otců svých, všickni ti ze jména, a zasedli prvního dne měsíce desátého, aby to vyhledali.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 17, 'Což i konali při všech mužích, kteříž byli pojali ženy cizozemky, až do prvního dne prvního měsíce.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 18, 'Našli se pak z synů kněžských, jenž zpojímali ženy cizozemky tito: Z synů Jesua syna Jozadakova, a z bratří jeho: Maaseiáš, Eliezer, Jarib a Gedaliáš.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 19, 'Ale povolili, aby zapudili ženy své. A ti, kteříž provinili, obětovali skopce z stáda za vinu svou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 20, 'A z synů Immer: Chanani a Zebadiáš.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 21, 'Z synů Charim: Maaseiáš, Eliah, Semaiáš, Jechiel a Uziáš.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 22, 'Z synů Paschur: Elioenai, Maaseiáš, Izmael, Natanael, Jozabad a Elasa.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 23, 'A z Levítů: Jozabad, Simei, Kelaiáš, (jenž jest Kelita), Petachiáš, Juda a Eliezer.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 24, 'Z zpěváků pak Eliasib, a z vrátných Sallum, Telem a Uri.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 25, 'A z lidu Izraelského, z synů Faresových: Ramiáš, Jeziáš, Malkiáš, Miamin, Eleazar, Malkiáš a Benaiáš.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 26, 'Z synů Elamových: Mataniáš, Zachariáš, Jechiel, Abdi, Jeremot a Eliah.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 27, 'Z synů Zattu: Elioenai, Eliasib, Mataniáš, Jeremot, Zabad, a Aziza.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 28, 'Též z synů Bebai: Jochanan, Chananiáš, Zabbai, Atlai.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 29, 'Z synů Báni: Mesullam, Malluch, Adaiáš, Jasub, Seal, Jeramot.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 30, 'Z synů Pachat Moábových: Adna a Chélal, Benaiáš, Maaseiáš, Mataniáš, Bezaleel, Binnui a Manasse.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 31, 'Z synů Charimových: Eliezer, Isiáš, Malkiáš, Semaiáš, Simeon,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 32, 'Beniamin, Malluch, Semariáš.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 33, 'Z synů Chasumových: Mattenai, Mattata, Zabad, Elifelet, Jeremai, Manasses, Simei.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 34, 'Z synů Báni: Maadai, Amram, Uel,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 35, 'Benaiáš, Bediáš, Keluhu,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 36, 'Vaniáš, Meremot, Eliasib,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 37, 'Mattaniáš, Mattenai, Jaasav,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 38, 'Báni, Binnui, Simei,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 39, 'Selemiáš, Nátan a Adaiáš,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 40, 'Machnadbai, Sasai, Sarai,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 41, 'Azarel, Selemiáš, Semariáš,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 42, 'Sallum, Amariáš a Jozef.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 43, 'Z synů Nébových: Jehiel, Mattitiáš, Zabad, Zebina, Jaddav, Joel a Benaiáš.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 44, 'Ti všickni pojali byli ženy cizozemky, a byly z těch žen některé, že i děti zplodily.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 1, 1, 'Slova Nehemiáše syna Chachaliášova. I stalo se měsíce Kislev léta dvadcátého, když jsem byl na hradě Susan,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 1, 2, 'Že přišel Chanani, jeden z bratří mých, s některými muži z Judstva. Kterýchžto vzeptal jsem se na Židy, na ostatky pozůstalé z zajetí a na Jeruzalém.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 1, 3, 'I řekli mi: Ostatkové ti, kteříž pozůstali z zajetí tam v té krajině, jsou u velikém nátisku a v pohanění, nadto i zed Jeruzalémská rozbořena jest, a brány jeho ohněm zkaženy.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 1, 4, 'Kterážto slova když jsem uslyšel, sedna plakal jsem a kvílil za několik dní, a postil jsem se, i modlil před Bohem nebeským.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 1, 5, 'A řekl jsem: Prosím, Hospodine Bože nebeský, silný, veliký a hrozný, ostříhající smlouvy a milosrdenství těm, jenž tě milují, a ostříhají přikázaní tvých,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 1, 6, 'Budiž, prosím, ucho tvé nakloněné, a oči tvé otevřené, abys slyšel modlitbu služebníka svého, kterouž já se modlím před tebou nyní dnem i nocí za syny Izraelské, služebníky tvé, a vyznávám hříchy synů Izraelských, jimiž jsme hřešili proti tobě. Já také i dům otce mého hřešili jsme.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 1, 7, 'Zpronevěřili jsme se tobě, a neostříhali jsme přikázaní a ustanovení a soudů, kteréž jsi vydal skrze Mojžíše služebníka svého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 1, 8, 'Budiž pamětliv, prosím, na slovo, kteréž jsi přikázal Mojžíšovi služebníku svému, řka: Vy přestoupíte, já pak rozptýlím vás mezi národy.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 1, 9, 'Ale když se obrátíte ke mně, a budete ostříhati přikázaní mých, a plniti je, by pak někteří z vás až na kraj světa zahnáni byli, i odtud shromáždím je, a přivedu je zase na místo, kteréž jsem vyvolil, aby tam přebývalo jméno mé.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 1, 10, 'Však tito jsou služebníci tvoji a lid tvůj, kteréž jsi vykoupil mocí svou převelikou, a rukou svou přesilnou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 1, 11, 'Prosím, ó Hospodine, nechť jest nakloněné ucho tvé k modlitbě služebníka tvého, a k modlitbě služebníků tvých, kteříž žádají báti se jména tvého, a dej šťastný prospěch, prosím, služebníku svému dnes, nakloně k němu lítostí člověka toho. Já pak byl jsem šeňkéřem královským.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 1, 'Tedy stalo se měsíce Nísan léta dvadcátého Artaxerxa krále, když víno stálo před ním, že vzav víno, podal jsem ho králi. Nebýval jsem pak smuten před ním.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 2, 'Pročež mi řekl král: Proč oblíčej tvůj smutný jest, poněvadž nestůněš? Jiného není, než sevření srdce. Pročež ulekl jsem se velmi velice.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 3, 'A řekl jsem králi: Král na věky buď živ. Kterak nemá býti smutný oblíčej můj, když město to, kdež jsou hrobové otců mých, zpuštěno jest, a brány jeho ohněm zkaženy?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 4, 'Opět mi řekl král: Čeho žádáš? Mezi tím modlil jsem se Bohu nebeskému.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 5, 'Potom řekl jsem králi: Zdá-liť se za dobré králi, a jestliže má lásku služebník tvůj u tebe, žádám, abys mne poslal do Judstva, do města, kdež jsou hrobové otců mých, abych je zase vystavěl.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 6, 'Ještě mi řekl král (královna pak seděla podlé něho): Dlouho-li budeš na té cestě, a kdy se zas navrátíš? I líbilo se to králi, a propustil mne, hned jakž jsem mu oznámil jistý čas.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 7, 'Zatím řekl jsem králi: Vidí-li se za dobré králi, nechť mi dadí listy k vývodám za řekou, aby mne provedli, až bych přišel do Judstva,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 8, 'Tolikéž psání k Azafovi, vládaři lesu královského, aby mi dal dříví na trámy, k branám paláce, při domě Božím, a ke zdem městským, a k domu, do něhož bych vjíti mohl. I dal mi král vedlé štědré ruky Boha mého ke mně.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 9, 'Tedy přišed k vývodám za řekou, dal jsem jim psání královské. Poslal pak byl se mnou král hejtmany vojska a jezdce.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 10, 'To když uslyšel Sanballat Choronský, a Tobiáš služebník Ammonitský, velmi je to mrzelo, že přišel člověk, kterýž by obmýšlel dobré synů Izraelských.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 11, 'A tak přišed do Jeruzaléma, pobyl jsem tam za tři dni.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 12, 'V noci pak vstal jsem, a kolikosi mužů se mnou, a neoznámil jsem žádnému, co mi dal Bůh můj v srdce, abych činil v Jeruzalémě, aniž jsem měl hovada jakého s sebou, kromě hovádka, na němž jsem jel.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 13, 'I vyjel jsem branou při údolí v noci k studnici drakové a k bráně hnojné, a ohledoval jsem zdí Jeruzalémských, kteréž byly pobořené, a bran jeho zkažených ohněm.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 14, 'Odtud jsem jel k bráně studničné, a k rybníku královskému, kdež nebylo brodu hovádku, na němž jsem jel, aby přejíti mohlo.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 15, 'Pročež bral jsem se zhůru podlé potoka v noci, a ohledoval jsem zdi. Odkudž vraceje se, vjel jsem branou při údolí, a tak jsem se navrátil.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 16, 'Ale knížata nic nevěděli, kam jsem jezdil, a co jsem činil; nebo jsem Židům, ani kněžím, ani přednějším, ani knížatům, ani jiným úředníkům až do té chvíle neoznámil.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 17, 'Protož řekl jsem jim: Vy vidíte, v jakém jsme zlém, a Jeruzalém zpuštěný, a brány jeho ohněm zkaženy. Poďtež, a stavějme zed Jeruzalémskou, abychom nebyli více v pohanění.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 18, 'A když jsem jim oznámil, že pomoc Boha mého jest se mnou, ano i slova králova, kteráž ke mně mluvil, teprv řekli: Přičiňmež se a stavějme. I posilnili rukou svých k dobrému.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 19, 'Což když uslyšel Sanballat Choronský, a Tobiáš služebník Ammonitský, a Gesem Arabský, posmívali se, a utrhali nám, pravíce: Což to děláte? Co se králi protivíte?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 20, 'Jimž odpovídaje, řekl jsem: Bůh nebeský, tenť nám dá prospěch, a my služebníci jeho přičiníce se, stavěti budeme, vy pak nemáte žádného dílu, ani práva, ani památky v Jeruzalémě.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 1, 'Tedy povstal Eliasib, kněz nejvyšší, a příbuzní jeho kněží, a stavěli bránu bravnou, (tiť jsou ji vystavěli, a zavěsili vrata její, až k věži Mea vystavěli ji), až k věži Chananeel.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 2, 'A podlé něho stavěli muži Jerecha, též podlé něho stavěl Zakur syn Imrův.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 3, 'Bránu pak rybnou stavěli synové Senaa. Ti položili trámy její, a vstavili vrata její s zámky i závorami jejími.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 4, 'Podlé těch také opravoval Meremot syn Uriáše, syna Kózova, a podlé nich opravoval Mesullam syn Berechiáše, syna Mesezabelova, a podlé těch opravoval Sádoch syn Baanův.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 5, 'A podlé nich opravovali Tekoitští. Ale ti, kteříž byli znamenitější z nich, nepodklonili šíje své k dílu pána svého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 6, 'Bránu pak starou opravovali Joiada syn Paseachův, a Mesullam syn Besodiášův. Ti položili trámy její a vstavili vrata její s zámky a závorami jejími.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 7, 'Podlé nich opravoval Melatiáš Gabaonitský, a Jádon Meronotský, muži z Gabaon a z Masfa, až k stolici knížecí z této strany řeky.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 8, 'Podlé nich pak opravoval Uziel syn Charhaiášův s zlatníky, a podlé něho opravoval Chananiáš, syn apatekářův. A nechali Jeruzaléma až do zdi široké.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 9, 'Dále podlé nich opravoval Refaiáš syn Churův, hejtman nad polovicí kraje Jeruzalémského.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 10, 'A podlé nich opravoval Jedaiáš Charumafův proti domu svému. Podlé něhož opravoval Chattus syn Chasabneiášův.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 11, 'Druhý pak díl opravoval Malkiáš syn Charimův, a Chasub syn Pachat Moábův, a věži Tannurim.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 12, 'Podlé něhož opravoval Sallum syn Lochesův, hejtman nad polovicí kraje Jeruzalémského, se dcerami svými.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 13, 'Bránu při údolí opravil Chanun s obyvateli Zanoe. Oni ji stavěli, a vstavili vrata její s zámky i závorami jejími, a zdi na tisíc loket až do brány hnojné.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 14, 'Bránu pak hnojnou opravil Malkiáš syn Rechabův, hejtman kraje Betkarem. On ji ustavěl, a vstavil vrata s zámky i závorami jejími.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 15, 'Bránu pak studnice opravoval Sallun syn Kolchozův, hejtman kraje Masfa. On ji vystavěl a přikryl ji, a vstavil vrata její s zámky i závorami jejími, a zed rybníka Selach, od zahrady královské až k stupňům sstupujícím z města Davidova.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 16, 'Za ním opravoval Nehemiáš syn Azbukův, hejtman nad polovici kraje Betsur, až naproti hrobům Davidovým, a až k rybníku udělanému, až k domu silných.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 17, 'Za ním opravovali Levítové, Rechum syn Báni, podlé něhož opravoval Chasabiáš, hejtman nad polovicí kraje Ceily s krajem svým.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 18, 'Za ním opravovali bratří jejich, Bavai syn Chenadadův, hejtman nad polovicí kraje Ceily.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 19, 'Podlé něho pak opravoval Ezer syn Jesua, hejtman Masfa, díl druhý naproti, kudyž se chodí k skladu zbroje Mikzoa.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 20, 'Za ním rozhorliv se, opravoval Báruch syn Zabbai, díl druhý od Mikzoa až ke dveřům domu Eliasiba, kněze nejvyššího.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 21, 'Za ním opravoval Meremot syn Uriáše, syna Kózi, díl druhý ode dveří domu Eliasibova až do konce domu jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 22, 'Za ním opravovali kněží, kteříž bydlili v rovině.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 23, 'Za ním opravoval Beniamin a Chasub proti domům svým. Za ním opravoval Azariáš syn Maaseiáše, syna Ananiášova vedlé domu svého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 24, 'Za ním opravoval Binnui syn Chenadadův díl druhý, od domu Azariášova až do Mikzoa a až k úhlu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 25, 'Pálal syn Uzai proti Mikzoa a věži vysoké, kteráž vyhlédala z domu králova, jenž byla v placu u žaláře. Za ním Pedaiáš syn Farosův.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 26, 'Netinejští pak, jenž bydlili v Ofel, až naproti bráně vodné k východu, a věži vysoké.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 27, 'Za ním opravovali Tekoitští díl druhý, naproti věži veliké a vysoké, až ke zdi při Ofel.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 28, 'Od brány koňské opravovali kněží, jeden každý naproti domu svému.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 29, 'Za tím opravoval Sádoch syn Immerův naproti domu svému. Za ním pak opravoval Semaiáš syn Sechaniášův, strážný brány východní.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 30, 'Za ním opravoval Chananiáš syn Selemiášův, a Chanun syn Zalafův šestý, díl druhý. Za ním opravoval Mesullam syn Berechiášův proti pokoji svému.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 31, 'Za ním opravoval Malkiáš syn zlatníkův až k domu Netinejských a kupců, naproti bráně Mifkad, až do paláce úhlového.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 32, 'A mezi palácem úhlovým až do brány bravné opravovali zlatníci a kupci.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 1, 'I stalo se, když uslyšel Sanballat, že stavíme zed, rozpálil se hněvem, a rozzlobiv se velmi, posmíval se Židům.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 2, 'Nebo mluvil před bratřími svými a před vojskem Samařským, řka: Co ti bídní Židé berou před sebe? Tak-liž mají býti zanecháni? Což budou obětovati? Za jeden-liž den to dodělati mají? Také-liž i kamení z hromad rumu křísiti budou, kteréž spáleno jest?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 3, 'Tobiáš pak Ammonitský podlé něho řekl: Nechať stavějí, však liška přiběhna, prorazí zed jejich kamennou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 4, 'Slyš, ó Bože náš, že jsme v pohrdání, a obrať pohanění jejich na hlavu jejich, a dej je v loupež v zemi, do níž by zajati byli.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 5, 'A nepřikrývej nepravosti jejich, a hřích jejich od tváři tvé ať není shlazen, proto že jsou tě popouzeli v stavitelích.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 6, 'A tak stavěli jsme tu zed, a spojili všecku až do polu, a měl lid srdce k tomu dílu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 7, 'Což když uslyšel Sanballat, a Tobiáš a Arabští, Ammonitští i Azotští, že by na dýl přibývalo zdi Jeruzalémské, a že se již byly počaly mezery zavírati, rozpálili se hněvem velice.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 8, 'Protož spuntovali se všickni společně, aby táhli k boji proti Jeruzalému a aby jemu překážku učinili.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 9, '(My pak modlili jsem se Bohu svému, a postavili jsme stráž proti nim ve dne i v noci, bojíce se jich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 10, 'Nebo řekli Judští: Zemdlelať jest síla nosičů, a rumu ještě mnoho jest, neodolaliť bychom jim, stavějíce zed.)');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 11, 'Anobrž i řekli nepřátelé naši: Nezvědíť, ani spatří, až vpadneme mezi ně, a pomordujeme je, aneb zastavíme to dílo.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 12, 'Když pak přišli Židé, kteříž s nimi bydlili, a pravili nám na desetkrát: Mějte pozor na všecka místa, kudyž se chodí k nám:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 13, 'Tedy postavil jsem na dolních místech za zdí, i na místech příkrých, a osadil jsem lidem po čeledech s meči, s kopími a lučišti jejich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 14, 'A když jsem to spatřil, vstana, řekl jsem k přednějším a knížatům i k jinému lidu: Nebojte se jich, ale na Pána velikého a hrozného pamatujte, a bojujte za bratří své, za syny své a dcery své, za manželky své a domy své.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 15, 'I stalo se, když uslyšeli nepřátelé naši, že jest nám to oznámeno, tožť Bůh rozptýlil radu jejich, a my navrátili jsme se všickni ke zdem, každý k dílu svému.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 16, 'Ale však od toho dne polovice služebníků mých dělali, a polovice jich držela kopí, pavézy a lučiště, a pancíře, a knížata stála za vší čeledí Judskou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 17, 'Ti také, kteříž dělali na zdi, i nosiči břemen, i nakladači, každý jednou rukou dělal, a v druhé držel braň.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 18, 'Z těch pak, kteříž stavěli, měl jeden každý meč svůj připásaný na bedrách svých, a tak stavěli, a trubač stál podlé mne.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 19, 'Nebo jsem řekl k přednějším a knížatům i k jinému lidu: Dílo veliké a široké jest, a my porůznu jsme na zdi, podál jeden od druhého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 20, 'Na kterém byste koli místě uslyšeli hlas trouby, tu se shromažďte k nám. Bůh náš bude bojovati za nás.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 21, 'A tak my dělali jsme dílo, a polovice jich držela kopí od svitání až do soumraku.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 22, 'Tehdáž také řekl jsem lidu: Každý s služebníkem svým nocuj u prostřed Jeruzaléma, ať je máme k stráži v noci, a ve dne k dílu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 23, 'Pročež i já, i bratří moji, i služebníci moji, i strážní, kteříž chodí za mnou, nebudeme svláčeti oděvu svého. Žádný ho nesloží, leč u vody.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 1, 'Byl pak pokřik veliký lidu i žen jejich na bratří jich Židy.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 2, 'Nebo někteří pravili: Synů a dcer máme tak mnoho, že za ně obilé jednáme, abychom jísti a živi býti mohli.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 3, 'Jiní opět pravili: Pole svá i vinice své, a domy své zzastavovati musíme, abychom obilé jednati mohli v hladu tomto.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 4, 'Jiní ještě pravili: Musíme vypůjčiti peněz, abychom dali plat králi, na svá pole i vinice své,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 5, 'Ješto aj, jakož tělo bratří našich, tak těla naše, jakož synové jejich, tak i synové naši. A však my musíme podrobovati syny své a dcery své v službu, a některé již ze dcer našich podrobeny jsou, a nemůžeme s nic býti, poněvadž pole naše a vinice naše drží jiní.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 6, 'Protož rozhněval jsem se velmi, když jsem slyšel křik jejich a slova taková.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 7, 'I uložil jsem v srdci svém, abych domlouval přednějším a knížatům, řka jim: Vy jste ti, jenž obtěžujete jeden každý bratra svého. I svolal jsem proti nim shromáždění veliké.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 8, 'A řekl jsem jim: My vyplacujeme bratří své Židy, kteříž prodáni byli pohanům, podlé možnosti naší. Což vy zase prodávati máte bratří vaše, anobrž což je sobě prodávati budete? Kteřížto umlkli a nenalezli odpovědi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 9, 'Řekl jsem dále: Není to dobře, což děláte. Zdali v bázni Boha našeho nemáte choditi raději než v pohanění pohanů, nepřátel našich?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 10, 'I já také s bratřími svými a s služebníky svými mohl bych bráti od nich peníze aneb obilé, a však odpusťme jim medle ten dluh.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 11, 'Navraťte jim, prosím, ještě dnes pole jejich, vinice jejich, zahrady olivové jejich i domy jejich, i ten stý díl peněz, obilé, vína i oleje, kterýž od nich béřete.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 12, 'Odpověděli: Navrátíme, aniž čeho od nich vyhledávati budeme; tak učiníme, jakž ty pravíš. Tedy svolav kněží, zavázal jsem je přísahou, aby tak učinili.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 13, 'Vytřásl jsem také podolek svůj, a řekl jsem: Tak vytřes Bůh každého muže, kdož by nenaplnil slova tohoto, z domu jeho, z úsilí jeho, a tak buď vytřesený a prázdný. I řeklo všecko shromáždění: Amen, a chválili Hospodina. I učinil lid tak.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 14, 'Anobrž také ode dne, v němž jsem postaven, abych byl vývodou jejich v zemi Judské, od léta dvadcátého až do léta třidcátého druhého Artaxerxa krále, za dvanácte let, ani já ani bratří moji pokrmu knížecího jsme nejedli,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 15, 'Ješto vývodové prvnější, kteříž byli přede mnou, obtěžovali lid, berouce od nich chléb a víno mimo čtyřidceti lotů stříbra. Nadto i služebníci jejich ssužovali lid, čehož jsem já nečinil, boje se Boha.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 16, 'Alebrž také i při opravování zdi pracoval jsem, aniž jsme skupovali rolí, ano i všickni služebníci moji byli tu shromážděni k dílu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 17, 'Přesto Židé a knížat půl druhého sta osob, a kteříž přicházeli k nám z národů okolních, jídali u stolu mého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 18, 'Pročež strojívalo se toho na každý den jeden vůl, šest ovec výborných, též i ptáci byli mi strojeni, a v jednom z desíti dnů všelijakého vína dávalo se dosti. Však s tím se vším pokrmu knížecího nežádal jsem, nebo těžká poroba vzložena byla na lid ten.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 19, 'Budiž pamětliv na mne, Bože můj, k dobrému, což jsem pak koli činil při lidu tomto.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 1, 'I stalo se, když uslyšel Sanballat a Tobiáš, a Gesem Arabský i jiní nepřátelé naši, že bych vystavěl zed, a že nezůstalo v ní mezery, ačkoli jsem ještě až do toho času nevstavil vrat do bran,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 2, 'Že poslal Sanballat a Gesem ke mně, řka: Přiď, a rozmluvíme spolu ve vsi na rovinách Ono. Ale oni mé zlé obmýšleli.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 3, 'Takž jsem poslal k nim posly, řka: Dílo veliké dělám, protož nemohu odjíti. Což se má meškati dílo, když bych je opustě, k vám sjíti měl?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 4, 'I posílali ke mně na týž způsob čtyřikrát, a odpověděl jsem jim týmiž slovy.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 5, 'Potom poslal ke mně Sanballat na tentýž způsob po páté služebníka svého s listem otevřeným.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 6, 'V kterémž bylo psáno: Slyší se mezi národy, jakž Gasmu praví, že ty a Židé myslíte se zprotiviti, a že ty proto stavíš zed, abys králem jejich byl, jakž se to dokoná.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 7, 'Také žes i proroky postavil, aby hlásali o tobě v Jeruzalémě, řkouce: Král v Judstvu. Nyní tedy uslyší král ty věci. Protož přiď, a poradíme se spolu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 8, 'Tedy poslal jsem k němu, řka: Neníť toho nic, což ty pravíš, ale sám sobě to vymýšlíš.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 9, 'Nebo všickni ti nás ustrašiti se snažovali, myslíce: Oslábnou ruce jejich při díle, a nedokoná se to. Ale však ty, ó Bože, posilň rukou mých.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 10, 'A když jsem všel do domu Semaiáše syna Delaiášova, syna Mehetabelova, kterýž se byl zavřel, řekl mi: Sejděme se do domu Božího, do vnitřku chrámu, a zavřeme dvéře chrámové; nebo přijdou, chtíc tě zamordovati. A to v noci přijdou, aby tě zamordovali.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 11, 'Jemuž jsem řekl: Takový-liž by muž, jako jsem já, utíkati měl? Aneb kdo jest tak, jako jsem já, ješto by vejda do chrámu, živ byl? Nevejduť.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 12, 'I poznal jsem, a aj, Bůh neposlal ho, ale proroctví to mluvil proti mně, že ho Tobiáš a Sanballat byli ze mzdy najali.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 13, 'Proto pak ze mzdy byl najat, abych já ustrašen jsa, učinil to a zhřešil, aby mi to bylo u nich k zlé pověsti, čímž by mi utrhali.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 14, 'Budiž pamětliv, můj Bože, na Tobiáše a Sanballata, podlé těch skutků jejich, i na Noadii prorokyni, a na jiné proroky, kteříž strašili mne.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 15, 'A tak dodělána jest zed ta pětmecítmého dne měsíce Elul v padesáti a dvou dnech.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 16, 'To když uslyšeli všickni nepřátelé naši, a viděli všickni národové, kteříž byli vůkol nás, ulekli se velmi; nebo poznali, že od Boha našeho působeno bylo dílo to.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 17, 'Také v těch dnech i listy často posílali přednější Judští k Tobiášovi, tolikéž od Tobiáše docházely k nim.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 18, 'Nebo mnozí v Judstvu měli s ním přísahu, proto že byl zetěm Sechaniáše syna Arachova, a Jochanan syn jeho pojal byl dceru Mesullama syna Berechiášova.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 19, 'K tomu i dobré činy jeho vypravovali přede mnou, a řeči mé vynášeli k němu. Listy pak posílal Tobiáš, aby mne ustrašil.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 1, 'A když byla dostavena zed, a zavěsil jsem vrata, a ustanoveni byli vrátní i zpěváci i Levítové,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 2, 'Poručil jsem Chananovi bratru svému, a Chananiášovi hejtmanu hradu Jeruzalémského, (proto že on byl muž věrný a bohabojný nad mnohé),');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 3, 'A řekl jsem jim: Nechť nebývají otvírány brány Jeruzalémské, až obejde slunce, a když ti, jenž tu stávají, zavrou brány, vy ohledejte. A tak postavil jsem stráž z obyvatelů Jeruzalémských, každého v stráži jeho, a každého naproti domu jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 4, 'Město pak to bylo široké a veliké, ale lidu málo v ohradě jeho, a domové nebyli vystaveni.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 5, 'Protož dal mi to Bůh můj v srdce mé, že jsem shromáždil přednější, a knížata i lid, aby byli vyčteni podlé pořádku rodů. I nalezl jsem knihu o rodu těch, kteříž se byli prvé přestěhovali, a našel jsem v ní napsáno:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 6, 'Tito jsou lidé té krajiny, kteříž šli z zajetí a přestěhování toho, jakž je byl přestěhoval Nabuchodonozor král Babylonský, a navrátili se do Jeruzaléma a do Judstva, jeden každý do města svého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 7, 'Kteříž přišli s Zorobábelem, s Jesua, s Nehemiášem, Azariášem, Raamiášem, Nachamanem, Mardocheem, Bilsanem, Misperetem, Bigvajem, Nechumem, Baanou, počet mužů z lidu Izraelského:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 8, 'Synů Farosových dva tisíce, sto sedmdesát dva;');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 9, 'Synů Sefatiášových tři sta sedmdesát dva;');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 10, 'Synů Arachových šest set padesát dva;');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 11, 'Synů Pachat Moábových, synů Jesua a Joábových, dva tisíce, osm set a osmnáct;');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 12, 'Synů Elamových tisíc, dvě stě padesát čtyři;');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 13, 'Synů Zattuových osm set čtyřidceti pět;');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 14, 'Synů Zakkai sedm set a šedesát;');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 15, 'Synů Binnui šest set čtyřidceti osm;');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 16, 'Synů Bebai šest set dvadceti osm;');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 17, 'Synů Azgadových dva tisíce, tři sta dvamecítma;');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 18, 'Synů Adonikamových šest set šedesáte sedm;');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 19, 'Synů Bigvai dva tisíce, šedesáte sedm;');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 20, 'Synů Adinových šest set padesát pět;');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 21, 'Synů Aterových z Ezechiáše devadesát osm;');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 22, 'Synů Chasumových tři sta dvadceti osm;');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 23, 'Synů Bezai tři sta dvadceti čtyři;');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 24, 'Synů Charifových sto a dvanáct;');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 25, 'Synů Gabaonitských devadesát pět;');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 26, 'Mužů Betlémských a Netofatských sto osmdesát osm;');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 27, 'Mužů Anatotských sto dvadceti osm;');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 28, 'Mužů Betazmavetských čtyřidceti dva;');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 29, 'Mužů Kariatjeharimských, Kafirských a Berotských sedm set čtyřidceti a tři;');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 30, 'Mužů Ráma a Gabaa šest set dvadceti jeden;');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 31, 'Mužů Michmas sto dvadceti dva;');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 32, 'Mužů z Bethel a Hai sto dvadceti tři;');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 33, 'Mužů z Nébo druhého padesáte dva;');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 34, 'Synů Elama druhého tisíc, dvě stě padesát čtyři;');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 35, 'Synů Charimových tři sta dvadceti;');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 36, 'Synů Jerecho tři sta čtyřidceti pět;');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 37, 'Synů Lodových, Chadidových a Onových sedm set dvadceti jeden;');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 38, 'Synů Senaa tři tisíce, devět set a třidceti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 39, 'Kněží: Synů Jedaiášových z domu Jesua devět set sedmdesát tři;');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 40, 'Synů Immerových tisíc, padesát dva;');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 41, 'Synů Paschurových tisíc, dvě stě čtyřidceti sedm;');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 42, 'Synů Charimových tisíc a sedmnáct.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 43, 'Levítů: Synů Jesua a Kadmiele, synů Hodevášových sedmdesát čtyři.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 44, 'Zpěváků: Synů Azafových sto čtyřidceti osm.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 45, 'Vrátných: Synů Sallumových, synů Aterových, synů Talmonových, synů Akkubových, synů Chatita, synů Sobai, sto třidceti osm.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 46, 'Netinejských: Synů Zicha, synů Chasufa, synů Tabbaot,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 47, 'Synů Keros, synů Sia, synů Fadon,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 48, 'Synů Lebana, synů Chagaba, synů Salmai,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 49, 'Synů Chanan, synů Giddel, synů Gachar,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 50, 'Synů Reaia, synů Rezin, synů Nekoda,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 51, 'Synů Gazam, synů Uza, synů Paseach,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 52, 'Synů Besai, synů Meunim, synů Nefisesim,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 53, 'Synů Bakbuk, synů Chakufa, synů Charchur,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 54, 'Synů Bazlit, synů Mechida, synů Charsa,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 55, 'Synů Barkos, synů Sisera, synů Tamach,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 56, 'Synů Neziach, synů Chatifa,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 57, 'Synů služebníků Šalomounových, synů Sotai, synů Soferet, synů Ferida,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 58, 'Synů Jaala, synů Darkon, synů Giddel,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 59, 'Synů Sefatiášových, synů Chattil, synů Pocheret Hazebaim, synů Amon,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 60, 'Všech Netinejských a synů služebníků Šalomounových tři sta devadesát dva.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 61, 'Tito také byli, kteříž vyšli z Telmelach a Telcharsa: Cherub, Addon a Immer. Ale nemohli prokázati rodu otců svých a semene svého, že by z Izraele byli.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 62, 'Synů Delaiášových, synů Tobiášových, synů Nekodových šest set čtyřidceti dva.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 63, 'A z kněží: Synové Chabaiášovi, synové Kózovi, synové Barzillai toho, kterýž pojav sobě z dcer Barzillai Galádského manželku, nazván jest jménem jejich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 64, 'Ti vyhledávali jeden každý zapsání o sobě, chtíce prokázati rod svůj, ale nenašlo se. A protož zbaveni jsou kněžství.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 65, 'A zapověděl jim Tirsata, aby nejedli z věcí svatosvatých, dokudž by nestál kněz s urim a tumim.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 66, 'Všeho toho shromáždění pospolu čtyřidceti a dva tisíce, tři sta a šedesát,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 67, 'Kromě služebníků jejich a děvek jejich, jichž bylo sedm tisíc, tři sta třidceti sedm. A mezi nimi bylo zpěváků a zpěvakyní dvě stě čtyřidceti pět.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 68, 'Koní jejich sedm set třidceti šest, mezků jejich dvě stě čtyřidceti pět,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 69, 'Velbloudů čtyři sta třidceti pět, oslů šest tisíc, sedm set a dvadceti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 70, 'Tehdy někteří z knížat čeledí otcovských dávali ku potřebám. Tirsata dal na poklad tisíc drachem zlata, bání padesát, sukní kněžských pět set a třidceti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 71, 'Knížata také čeledí otcovských dali na poklad ku potřebám dvadceti tisíc drachem zlata, a stříbra liber dva tisíce a dvě stě.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 72, 'Což pak dali jiní z lidu, bylo zlata dvadcet tisíc drachem, a stříbra dva tisíce liber, a sukní kněžských šedesát sedm.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 73, 'A tak osadili se kněží a Levítové, a vrátní i zpěváci, lid a Netinejští, i všecken Izrael v městech svých. I nastal měsíc sedmý, a synové Izraelští byli v městech svých.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 1, 'I shromáždil se všecken lid jednomyslně do ulice, kteráž jest proti bráně vodné, a řekli Ezdrášovi učiteli, aby přinesl knihu zákona Mojžíšova, kterýž vydal Hospodin lidu Izraelskému.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 2, 'Tedy přinesl Ezdráš kněz zákon před to shromáždění mužů i žen i všech, kteříž by rozumně poslouchati mohli, prvního dne měsíce sedmého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 3, 'I četl v něm na té ulici, kteráž jest proti bráně vodné, od jitra až do poledne, při přítomnosti mužů i žen, i kteřížkoli rozuměti mohli. A uši všeho lidu obráceny byly k knize zákona.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 4, 'Stál pak Ezdráš učitel na kazatelnici dřevěné, kterouž byli udělali k té věci, a stál podlé něho Mattitiáš, Sema, Anaiáš, Uriáš, Helkiáš a Maaseiáš, po pravé ruce jeho, po levé pak Pedaiáš, Misael, Malkiáš, Chasum, Chasbaddana, Zachariáš a Mesullam.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 5, 'Otevřel tedy Ezdráš knihu před očima všeho lidu, (nebo výše stál než všecken lid). Kterouž jakž otevřel, povstal všecken lid.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 6, 'I dobrořečil Ezdráš Hospodinu Bohu velikému, a všecken lid odpovídal: Amen, amen, pozdvihujíce rukou svých, a skloňujíce hlavy, poklonu učinili Hospodinu tváří k zemi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 7, 'Tak i Jesua, Báni, Serebiáš, Jamin, Akkub, Sabbetai, Hodiáš, Maaseiáš, Kelita, Azariáš, Jozabad, Chanan, Pelaiáš, a Levítové vyučovali lid zákonu. Lid pak byl na místě svém.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 8, 'Nebo čtli v té knize v zákoně Božím srozumitelně, a vykládajíce smysl, vysvětlovali to, což čtli.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 9, 'Potom řekl Nehemiáš, jinak Tirsata, a Ezdráš kněz, učitel, a Levítové, kteříž lid vyučovali, všemu lidu: Den tento posvěcený jest Hospodinu Bohu vašemu, nekvěltež, ani plačte. (Nebo plakal všecken lid, když slyšeli slova zákona.)');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 10, 'Ale jděte, řekl jim, a jezte tučné věci, a píte sladké, sdílejíce se s těmi, kteříž nemají nic připraveno. Den zajisté tento svatý jest Pánu našemu, protož nermuťtež se, nýbrž radost Hospodinova budiž síla vaše.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 11, 'A když tak Levítové pospokojili všeho lidu, mluvíce: Mlčte, nebo den svatý jest, a nermuťte se,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 12, 'Odšel všecken lid, aby jedli a pili, a aby se sdíleli. I veselili se velmi, proto že srozuměli slovům těm, kteráž jim v známost uvedli.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 13, 'Potom nazejtří sešla se knížata čeledí otcovských ze všeho lidu, kněží i Levítové k Ezdrášovi učiteli, aby vyrozuměli slovům zákona.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 14, 'Našli pak napsáno v zákoně, že přikázal Hospodin skrze Mojžíše, aby bydlili synové Izraelští v stáncích na slavnost měsíce sedmého,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 15, 'A aby dali prohlásiti a provolati po všech městech svých i v Jeruzalémě, řkouce: Vyjděte na hory, a přineste ratolestí olivových a ratolestí dříví borového, a ratolestí myrtových, i ratolestí palmových, a ratolestí dříví hustého, abyste nadělali stánků, tak jakž psáno jest.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 16, 'Protož vyšed lid, přinesli a nadělali sobě stánků, jeden každý na střeše své, i v síních svých, i v síních domu Božího, i v ulici brány vodné, i v ulici brány Efraim.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 17, 'A tak nadělali stánků všecko shromáždění těch, jenž se vrátili z zajetí, a bydlili v nich, (ačkoli nečinili tak synové Izraelští ode dnů Jozue syna Nun, až do dne toho). I byla radost velmi veliká.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 18, 'Četl pak v knize zákona Božího na každý den, od prvního dne až do posledního, a drželi slavnost za sedm dní. Osmého pak dne byl svátek podlé obyčeje.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 1, 'Potom dvadcátého čtvrtého dne téhož měsíce shromáždili se synové Izraelští, a postíce se v žíních, posypali se prstí,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 2, '(Oddělilo se pak bylo símě Izraelské ode všech cizozemců), a stojíce, vyznávali hříchy své i nepravosti otců svých.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 3, 'I stáli na místech svých, a čtli v knize zákona Hospodina Boha svého čtyřikrát za den, a čtyřikrát vyznávali a klaněli se Hospodinu Bohu svému.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 4, 'Za tím vystoupivše na výstupek Levítský Jesua a Báni, Kadmiel, Sebaniáš, Bunni, Serebiáš, Báni a Chenani, volali hlasem velikým k Hospodinu Bohu svému.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 5, 'A řekli Levítové ti, Jesua, Kadmiel, Báni, Chasabniáš, Serebiáš, Hodiáš, Sebaniáš a Petachiáš: Vstaňte, dobrořečte Hospodinu Bohu svému, od věků až na věky, a ať dobrořečí slavnému jménu jeho, a vyššímu nad každé dobrořečení i chválu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 6, 'Ty jsi, Hospodine, sám ten jediný, ty jsi učinil nebesa, nebesa nebes i všecko vojsko jejich, zemi i všecko, což jest na ní, moře i všecko, což jest v nich, obživuješ také všecko, ano i vojska nebeská před tebou se sklánějí.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 7, 'Ty jsi, Hospodine, Bůh ten, kterýž jsi vyvolil Abrama, a vyvedl jej z Ur Kaldejských, a dal jsi jemu jméno Abraham.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 8, 'A nalezl jsi srdce jeho věrné před sebou, a učinil jsi s ním smlouvu, že dáš zemi Kananejského, Hetejského, Amorejského, Ferezejského, Jebuzejského a Gergezejského, že dáš ji semeni jeho, a naplnils slova svá, nebo spravedlivý jsi ty.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 9, 'Popatřil jsi zajisté na trápení otců našich v Egyptě, a křik jejich vyslyšel jsi při moři Rudém.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 10, 'A ukazovals znamení a zázraky na Faraonovi i na všech služebnících jeho, i na všem lidu země jeho; nebo věděl jsi, že jsou pýchu provodili nad nimi. Čímž jsi dobyl sobě jména, jakž se to podnes vidí.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 11, 'Nadto i moře jsi před nimi rozdělil, tak že přešli prostředkem moře po suše, a ty, jenž je stihali, uvrhl jsi do hlubin, jako kámen do vody veliké.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 12, 'A sloupem oblakovým vodils je ve dne, a sloupem ohnivým v noci, osvěcuje jim cestu, kudy by jíti měli.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 13, 'Potom jsi sstoupil na horu Sinai, a mluvil jsi s nimi s nebe, a vydal jsi jim soudy přímé a zákony pravé, ustanovení a přikázaní dobrá.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 14, 'Též i sobotu svou svatou známu jsi jim učinil, a přikázaní, ustanovení i zákon vydals jim skrze Mojžíše, služebníka svého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 15, 'Také i chléb s nebe dal jsi jim v hladu jejich, a vodu z skály vyvedl jsi jim v žízni jejich, a rozkázal jsi jim, aby šli a dědičně vládli zemí, kterouž jsi zdvihna ruku svou, přisáhl dáti jim.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 16, 'Oni pak a otcové naši pyšně sobě počínali, a zatvrdivše šíji svou, neposlouchali přikázaní tvých.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 17, 'Nýbrž hned nechtěli slyšeti, aniž se rozpomenuli na divné činy tvé, kteréž jsi působil při nich, a zatvrdivše šíji svou, ustavovali sobě vůdce, chtíce se navrátiti k porobení svému z zarputilosti své. Ty však, Bože, snadný k odpuštění, milostivý a lítostivý, dlouho shovívající a hojný v milosrdenství, neopustils jich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 18, 'Ano i tehdáž, když sobě udělali tele slité a řekli: Tito jsou bohové tvoji, kteříž tě vyvedli z Egypta, a dopustili se velikého rouhání.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 19, 'Ty však pro svá mnohá slitování neopustil jsi jich na poušti. Sloup oblakový neodcházel od nich ve dne, veda je po cestě, ani sloup ohnivý v noci, osvěcuje je a cestu, po níž jíti měli.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 20, 'Nadto Ducha svého dobrého dal jsi k vyučování jich, manny své také neodjals od úst jejich, a vodu dal jsi jim v žízni jejich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 21, 'A tak za čtyřidceti let krmil jsi je na poušti. V ničemž nedostatku neměli, oděv jejich nezvetšel, a nohy jejich se neodhnetly.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 22, 'Potom dal jsi jim království a národy, kteréž jsi rozehnal do koutů, tak že dědičně obdrželi zemi Seonovu, a zemi krále Ezebon, i zemi Oga krále Bázan.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 23, 'Syny pak jejich rozmnožil jsi jako hvězdy nebeské, a uvedl jsi je do země, o kteréž jsi byl řekl otcům jejich, že do ní vejdou, aby jí vládli.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 24, 'Nebo všedše synové, dědičně obdrželi zemi tu, když jsi snížil před nimi obyvatele té země Kananejské, a dals je v ruku jejich, i krále jejich, i národy té země, aby s nimi nakládali podlé vůle své.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 25, 'A tak vzali města hrazená i pole úrodná, a dědičně ujali domy plné všeho dobrého, studnice vykopané, vinice a olivoví, i stromoví ovoce nesoucí velmi mnohé. I jedli, a nasyceni jsouce, vytyli, a v dobrodiní tvém hojném rozkoší oplývali.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 26, 'Když pak popouzejíce tě, zprotivili se tobě, zavrhše zákon tvůj za hřbet svůj, a proroky tvé zmordovali, kteříž jim osvědčovali, aby je obrátili k tobě, a dopouštěli se velikého rouhání,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 27, 'Dával jsi je v ruku nepřátel jejich, kteříž je ssužovali. A když v čas ssoužení svého volali k tobě, tys je s nebe vyslýchal, a podlé mnohých slitování svých dával jsi jim vysvoboditele, kteříž je vysvobozovali z ruky nepřátel jejich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 28, 'Mezitím, jakž jen oddechnutí měli, zase znovu činili zlé před tebou, a protož pouštěl jsi je v ruku nepřátel jejich, aby panovali nad nimi. Když se pak opět obrátili, a křičeli k tobě, tys je s nebe vyslýchal a vysvobozoval podlé slitování svých po mnohé časy.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 29, 'A napomínals jich, abys je obrátil k zákonu svému, ale oni pyšně sobě počínali, a neposlouchali přikázaní tvých, a proti soudům tvým hřešili, v nichžto, činil-li by je člověk, byl by živ. Nýbrž plece svého uchylujíce, šíji svou zatvrzovali, a neposlouchali.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 30, 'A však shovíval jsi jim po mnohá léta, osvědčuje jim duchem svým skrze proroky své, a když neposlouchali, dal jsi je v ruku národům zemí.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 31, 'Ale pro slitování svá mnohá nedals jim do konce zahynouti, aniž jsi jich opustil, proto že jsi Bůh milostivý a lítostivý.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 32, 'Nyní tedy, ó Bože náš, silný, veliký, mocný a hrozný, kterýž ostříháš smlouvy a milosrdenství, nechť to není u tebe za málo, že ty všecky těžkosti na nás přišly, na krále naše, knížata naše, kněží naše, proroky naše i na otce naše, a na všecken lid tvůj, hned ode dnů králů Assyrských, až do tohoto dne,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 33, 'Ačkoli ty jsi spravedlivý ve všech těch věcech, kteréž přišly na nás. Nebo jsi spravedlivě to učinil, ale my jsme bezbožně činili.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 34, 'I králové naši, knížata naše, kněží naši i otcové naši neplnili zákona tvého, aniž šetřili přikázaní tvých a svědectví tvých, jimiž se jim osvědčoval.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 35, 'Nebo oni v království svém a v dobrodiní tvém hojném, kteréž jsi jim ukazoval, a v zemi široké a úrodné, kterouž jsi jim dal, nesloužili tobě, aniž se odvrátili od činů svých zlých.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 36, 'Aj, my jsme dnes manové, a to v zemi, kterouž jsi dal otcům našim, aby jedli ovoce její a dobré věci její, aj, jsme v ní manové.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 37, 'Jižť úrody své vydává v hojnosti králům, kteréž jsi postavil nad námi pro hříchy naše, a oniť i nad těly našimi se potřásají, i nad hovady našimi podlé vůle své, tak že jsme u veliké úzkosti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 38, 'Se vším však tím činíme smlouvu nepohnutelnou, i zapisujeme, kteréž potvrzují knížata naše, Levítové naši, i kněží naši.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 1, 'Kteříž pak potvrzovali, byli tito: Nehemiáš Tirsata, syn Chachaliášův, a Sedechiáš,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 2, 'Saraiáš, Azariáš, Jeremiáš,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 3, 'Paschur, Amariáš, Malkiáš,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 4, 'Chattus, Sebaniáš, Malluch,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 5, 'Charim, Meremot, Abdiáš,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 6, 'Daniel, Ginneton, Báruch,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 7, 'Mesullam, Abiáš, Miamin,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 8, 'Maaseiáš, Bilkai, Semaiáš. To kněží.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 9, 'Levítové pak: Jesua syn Azaniášův, Binnui z synů Chenadad, Kadmiel.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 10, 'Bratří pak jejich: Sebaniáš, Hodiáš, Kelita, Pelaiáš, Chanan,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 11, 'Mícha, Rechob, Chasabiáš,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 12, 'Zakur, Serebiáš, Sebaniáš,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 13, 'Hodiáš, Báni, Beninu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 14, 'Přední z lidu: Paros, Pachat Moáb, Elam, Zattu, Báni,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 15, 'Bunni, Azgad, Bebai,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 16, 'Adoniáš, Bigvai, Adin,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 17, 'Ater, Ezechiáš, Azur,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 18, 'Hodiáš, Chasum, Bezai,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 19, 'Charif, Anatot, Nebai,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 20, 'Magpias, Mesullam, Chezir,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 21, 'Mesezabel, Sádoch, Jaddua,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 22, 'Pelatiáš, Chanan, Anaiáš,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 23, 'Ozeáš, Chananiáš, Chasub,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 24, 'Loches, Pilcha, Sobek,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 25, 'Rechum, Chasabna, Maaseiáš,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 26, 'Achiáš, Chanan, Anan,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 27, 'Malluch, Charim, Baana.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 28, 'Tak i jiní z lidu, kněží, Levítů, vrátných, zpěváků, Netinejských i všickni, kteříž se oddělili od národů zemí k zákonu Božímu, ženy jejich, synové jejich i dcery jejich, každý umělý a rozumný,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 29, 'Chopivše se téhož s bratřími svými a těmi, kteříž byli přednější, přistupovali, prokletím a přísahou se zavazujíce: Že budeme choditi v zákoně Božím, kterýž vydán jest skrze Mojžíše služebníka Božího, a ostříhati i plniti všecka přikázaní Hospodina Pána našeho, i soudy jeho, i ustanovení jeho;');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 30, 'Také že nebudeme dávati dcer svých národům zemí, ani dcer jejich bráti synům svým,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 31, 'Ani od cizozemců, kteříž by nám přinášeli jaké koupě a jakékoli potravy v den sobotní na prodaj, přijímati v sobotu aneb v sváteční den, a že necháme rolí sedmého léta, i všelikého dobývání dluhu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 32, 'I to nařídili jsme mezi sebou, abychom dávali třetí díl lotu na každý rok k službě domu Boha našeho,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 33, 'Na chleby zpořádaní, i obět ustavičnou, i na zápal ustavičný k sobotám, novměsícům a slavnostem, i na věci svaté, i oběti za hříchy k očištění Izraele, i na všecko přisluhování domu Boha našeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 34, 'Metali jsme i losy s strany kněží, Levítů i lidu, příčinou dříví nošení, aby ho dodávali do domu Boha našeho, čeledem otců našich časy vyměřenými, rok po roku, aby hořelo na oltáři Hospodina Boha našeho, jakž psáno jest v zákoně.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 35, 'Také, že chceme přinášeti prvotiny země své, i prvotiny všelikého ovoce každého stromu, rok po roku do domu Hospodinova.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 36, 'K tomu i prvorozené syny své, i hovádka svá, (jakož psáno jest v zákoně), i prvorozené z skotů i bravů svých, že přinášeti budeme do domu Boha svého, kněžím přisluhujícím v domě Boha našeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 37, 'A prvotiny těsta svého i obětí svých, i ovoce všelijakého stromu, mstu i oleje nového, aby přinášeli kněžím do pokojů domu Boha našeho, a desátky země naší Levítům. A Levítové desátky ty vybírati budou po všech městech, v nichž pracovati budeme.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 38, 'Bude pak při tom kněz, syn Aronův, s Levíty, když Levítové ty desátky vyberou, a Levítové sami vnesou desátek z desátků do domu Boha našeho, do pokojů v domě skladu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 39, 'Nebo do těch pokojů donášeti budou synové Izraelští i synové Léví oběti obilé, mstu a oleje nového, (kdež jsou nádoby svatyně), i kněží přisluhující, vrátní i zpěváci, abychom neopouštěli domu Boha svého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 1, 'I přebývala knížata lidu v Jeruzalémě. Jiný pak lid metali losy, aby vzali desátého člověka k bydlení v Jeruzalémě městě svatém, ale devět dílů v jiných městech,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 2, 'Ačkoli dobrořečil lid všechněm mužům těm, kteříž se sami dobrovolně podali k bydlení v Jeruzalémě.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 3, 'A tito jsou přednější té krajiny, kteříž se osadili v Jeruzalémě. (V jiných pak městech Judských bydlili jeden každý v vládařství svém, po městech svých, lid Izraelský, kněží a Levítové, i Netinejští, též i synové služebníků Šalomounových.)');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 4, 'A tak v Jeruzalémě bydlili někteří z synů Judových i z synů Beniaminových. Z Judových: Ataiáš syn Uziáše, syna Zachariášova, syna Amariášova, syna Sefatiášova, syna Mahalaleelova z synů Fáresových.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 5, 'Též Maaseiáš syn Bárucha, syna Kolchozy, syna Chazaiášova, syna Adaiášova, syna Joiaribova, syna Zachariášova, syna Silonského.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 6, 'Všech synů Fáresových, bydlících v Jeruzalémě, čtyři sta šedesáte osm, mužů udatných.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 7, 'Synové Beniaminovi tito: Sallu syn Mesullama, syna Joedova, syna Pedaiášova, syna Kolaiášova, syna Maaseiášova, syna Itielova, syna Izaiášova.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 8, 'A po něm Gabai, Sallai. Všech devět set dvadceti osm.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 9, 'Joel pak syn Zichri byl jim představen, a Juda syn Senua nad městem druhý po něm.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 10, 'Z kněží: Jedaiáš syn Joiaribův a Jachin.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 11, 'Saraiáš syn Helkiáše, syna Mesullamova, syna Sádochova, syna Meraiotova, syna Achitobova, přední v domě Božím.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 12, 'Bratří pak jejich, přisluhujících v tom domě, osm set dvadceti dva. A Adaiáš syn Jerochama, syna Pelaliášova, syna Amzi, syna Zachariášova, syna Paschurova, syna Malkiášova,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 13, 'A bratří jeho, knížat čeledí otcovských, dvě stě čtyřidceti dva. A Amassai syn Azarele, syna Achzai, syna Mesillemotova, syna Immerova.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 14, 'Bratří pak jejich, mužů udatných, sto dvadceti osm, jimž představen byl Zabdiel syn Gedolimův.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 15, 'Z Levítů tito: Semaiáš syn Chasuby, syna Azrikamova, syna Chasabiášova, syna Bunni.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 16, 'A Sabbetai s Jozabadem byli nad dílem při domě Božím vně, z předních Levítů.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 17, 'A Mataniáš syn Míchy, syna Zabdi, syna Azafova, přední, začínal chvály a modlitbu. A Bakbukiáš druhý z bratří jeho, a Abda syn Sammua, syna Galalova, syna Jedutunova.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 18, 'Všech Levítů v městě svatém dvě stě osmdesát a čtyři.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 19, 'Z vrátných: Akkub, Talmon a bratří jejich, strážní u bran, sto sedmdesát a dva.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 20, 'Ostatek pak lidu Izraelského, kněží a Levítů, bydlili ve všech městech Judských, jeden každý v dědictví svém.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 21, 'Ale Netinejští bydlili v Ofel, Zicha pak a Gispa byli představeni Netinejským.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 22, 'Představený pak Levítům v Jeruzalémě byl Uzi syn Báni, syna Chasabiášova, syna Mataniášova, syna Míchova z synů Azafových, jenž byli zpěváci při službě domu Božího.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 23, 'Nebo poručení královské bylo o nich, a stálé odměření pro zpěváky na každý den.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 24, 'A Petachiáš syn Mesezabelův, z synů Záry syna Judova, místo královské držící v každém jednání k lidu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 25, 'Ve vsech pak s poli jejich, z synů Judových bydlili v Kariatarbe a v vesnicích jeho, v Dibon a vesnicích jeho, v Jekabsael i ve vsech jeho,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 26, 'A v Jesua, v Molada, v Betfelet,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 27, 'A v Azarsual, v Bersabé i v vesnicích jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 28, 'A v Sicelechu, v Mechona, i v vesnicích jeho,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 29, 'V Enremmon, v Zaraha, v Jarmut,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 30, 'V Zanoe, v Adulam i ve vsech jeho, v Lachis s poli jeho, v Azeka a vesnicích jeho. A tak bydlili od Bersabé až do Gehinnom.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 31, 'Synové pak Beniaminovi z Gabaa v Michmas, v Aia, v Bethel i v vesnicích jeho,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 32, 'V Anatot, v Nobe, v Anania,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 33, 'V Azor, v Ráma, v Gittaim,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 34, 'V Chadid, v Seboim, v Neballat,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 35, 'V Lod, v Ono a v údolí řemeslníků.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 36, 'Z Levítů pak někteří bydlili v dílích Judských a Beniaminských.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 1, 'Tito pak jsou kněží a Levítové, kteříž se byli navrátili s Zorobábelem synem Salatielovým, a s Jesua: Saraiáš, Jeremiáš, Ezdráš,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 2, 'Amariáš, Malluch, Chattus,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 3, 'Sechaniáš, Rechum, Meremot,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 4, 'Iddo, Ginnetoi, Abiáš,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 5, 'Miamin, Maadiáš, Bilga,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 6, 'Semaiáš, Joiarib, Jedaiáš,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 7, 'Sallu, Amok, Helkiáš, Jedaiáš. Ti byli přednější z kněží a bratří svých za času Jesua.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 8, 'Levítové pak: Jesua, Binnui, Kadmiel, Serebiáš, Juda; Mattaniáš, postavený nad zpěvy chvalitebnými s bratřími svými.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 9, 'A Bakbukiáš a Unni, bratří jejich, byli naproti nim v pořádcích svých.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 10, 'Jesua pak zplodil Joiakima, a Joiakim zplodil Eliasiba, Eliasib pak zplodil Joiadu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 11, 'A Joiada zplodil Jonatana, Jonatan pak zplodil Jaddua.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 12, 'Za času pak Joiakima byli přední kněží z čeledí otcovských: Z Saraiášovy Meraiáš, z Jeremiášovy Chananiáš,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 13, 'Z Ezdrášovy Mesullam, z Amariášovy Jochanan,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 14, 'Z Melichovy Jonatan, z Sebaniášovy Jozef,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 15, 'Z Charimovy Adna, z Meraiotovy Chelkai,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 16, 'Z Iddovy Zachariáš, z Ginnetonovy Mesullam,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 17, 'Z Abiášovy Zichri, z Miniaminovy a z Moadiášovy Piltai,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 18, 'Z Bilgovy Sammua, z Semaiášovy Jonatan,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 19, 'Z Joiaribovy Mattenai, z Jedaiášovy Uzi,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 20, 'Z Sallaiovy Kallai, z Amokovy Heber,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 21, 'Z Helkiášovy Chasabiáš, z Jedaiášovy Natanael.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 22, 'Levítové pak přednější z čeledí otcovských za dnů Eliasiba, Joiady, Jochanana a Jaddua, zapsáni jsou až do kralování Daria Perského.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 23, 'Synové, pravím, Léví, přední v čeledech otcovských, zapsáni jsou v knize Paralipomenon, až do času Jochanana syna Eliasibova.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 24, 'Potom přední Levítové: Chasabiáš, Serebiáš, a Jesua syn Kadmielův, a bratří jejich naproti nim k chválení a oslavování Boha, podlé nařízení Davida muže Božího, třída proti třídě.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 25, 'Mataniáš, Bakbukiáš, Abdiáš, Mesullam, Talmon, Akkub, držící stráž vrátných při domu pokladů u bran.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 26, 'Ti byli za času Joiakima, syna Jesua, syna Jozadakova, a za času Nehemiáše vůdce, a Ezdráše kněze a učitele.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 27, 'Ku posvěcování pak zdí Jeruzalémských shlédávali Levíty ze všech míst jejich, aby je přivedli do Jeruzaléma, aby vykonali posvěcení a veselí, a to s oslavováním a zpěvy, cymbály, loutnami a harfami.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 28, 'Protož shromážděni jsou synové zpěváků, i z rovin okolo Jeruzaléma, i ze vsí Netofatských,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 29, 'Též z domu Galgal, a z polí Gaba i Azmavet; nebo vsi stavěli sobě zpěváci okolo Jeruzaléma.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 30, 'A očistivše se kněží a Levítové, očistili také lid, brány i zed.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 31, 'Za tím rozkázal jsem vstoupiti knížatům Judským na zed, a postavil jsem dva houfy veliké oslavujících, z nichž jedni šli na pravo, od horní strany zdi k bráně hnojné.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 32, 'A za těmi šel Hosaiáš a polovice knížat Judských,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 33, 'Též Azariáš, Ezdráš, a Mesullam,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 34, 'Juda, Beniamin, Semaiáš a Jeremiáš.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 35, 'Potom za syny kněžskými s trubami Zachariáš syn Jonatana, syna Semaiášova, syna Mattaniášova, syna Michaiášova, syna Zakurova, syna Azafova.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 36, 'A bratří jeho: Semaiáš, Azarel, Milalai, Gilalai, Maai, Natanael a Juda, Chanani s nástroji hudebnými Davida muže Božího, Ezdráš pak učitel před nimi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 37, 'Potom k bráně u studnice, kteráž naproti nim byla, vstupovali po stupních města Davidova, kudy se chodí na zed, a ode zdi při domě Davidově, až k bráně vodné k východu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 38, 'Houf pak druhý oslavujících bral se naproti oněmno, a já za nimi, a polovice lidu po zdi od věže Tannurim až ke zdi široké,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 39, 'A od brány Efraim k bráně staré, a k bráně rybné, a věži Chananeel, a věži Mea, až k bráně bravné. I zastavili se v bráně stráže.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 40, 'Potom zastavili se oba houfové oslavujících v domě Božím, i já, a polovice knížat se mnou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 41, 'Ano i kněží: Eliakim, Maaseiáš, Miniamin, Michaiáš, Elioenai, Zachariáš, Chananiáš, s trubami,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 42, 'A Maaseiáš, Semaiáš, Eleazar, Uzi, Jochanan, Malkiáš, Elam a Ezer. Zpěváci pak zvučně zpívali s Izrachiášem představeným svým.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 43, 'Obětovali také v ten den oběti veliké, a veselili se; nebo Bůh obveselil je veselím velikým. Ano i ženy a děti veselily se, tak že bylo slyšáno veselí Jeruzaléma opodál.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 44, 'Mezi tím zřízeni jsou v ten den muži nad komorami k pokladům a k obětem, i k prvotinám a k desátkům, aby shromažďovali do nich s polí městských díly, zákonem vyměřené kněžím a Levítům; nebo veselil se Juda z kněží a Levítů přístojících,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 45, 'Kteříž držeti měli stráž Boha svého, a stráž očišťování, a zpěváků i vrátných, podlé nařízení Davidova a Šalomouna syna jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 46, 'Nebo za času Davidova a Azafova od starodávna přední zpěváci k zpívání, chválení a oslavování Boha stáli před ním.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 47, 'Pročež všecken Izrael za dnů Zorobábele a za času Nehemiáše dávali díly pro zpěváky a vrátné, na každý den stálé odměření, a odvodili je Levítům, Levítové pak dávali synům Aronovým.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 1, 'V ten den čteno jest v knize Mojžíšově, tak že lid slyšeti mohl. I nalezeno v ní napsáno, že nemá vjíti Ammonitský a Moábský do shromáždění Božího až na věky,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 2, 'Proto že nevyšli proti synům Izraelským s chlebem a s vodou, ale najali ze mzdy proti nim Baláma, aby jim zlořečil, ačkoli obrátil Bůh náš to zlořečení v požehnání.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 3, 'Stalo se pak, když slyšeli zákon, že odmísili všecky přimíšené od Izraele.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 4, 'Ale před tím Eliasib kněz, správce komory domu Boha našeho, spříznil se s Tobiášem.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 5, 'Kterémuž udělal pokoj veliký, kdež prvé skládali dary, kadidlo a nádoby, a desátky z obilé, mstu a oleje nového, nařízené Levítům a zpěvákům i vrátným, též i obět kněžím.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 6, 'Ale když se to vše dálo, nebyl jsem v Jeruzalémě. Nebo léta třidcátého druhého Artaxerxa krále Babylonského přišel jsem k králi, a po přeběhnutí let, vyžádán jsem na králi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 7, 'Když jsem pak přišel do Jeruzaléma, srozuměl jsem tomu zlému, co učinil Eliasib pro Tobiáše, udělav mu pokoj v síních domu Božího.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 8, 'Což mi se velmi nelíbilo. Protož vyházel jsem všecko nádobí domu Tobiášova ven z toho pokoje.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 9, 'A rozkázal jsem očistiti ty pokoje. I vnesl jsem tam zase nádoby domu Božího, dary a kadidlo.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 10, 'Potom dověděv se, že dílové Levítům nebyli dáváni, a že rozběhli se jeden každý na svou rolí, Levítové i zpěváci vedoucí práci,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 11, 'Protož domlouval jsem se na starší, řka: Proč jest opuštěn dům Boží? A shromáždiv je, postavil jsem je na místě jejich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 12, 'A všecken Juda přinášeli desátky obilé, mstu a oleje nového do skladů.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 13, 'A ustanovil jsem úředníky nad sklady: Selemiáše kněze, a Sádocha učitele, a Pedaiáše z Levítů, přidav k nim Chanana syna Zakurova, syna Mattaniášova; nebo za věrné jmíni byli. A ti měli rozdělovati bratřím svým.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 14, 'Budiž pamětliv na mne, Bože můj, pro to, a nevyhlazuj dobrodiní mých, kteráž jsem prokázal k domu Boha svého i k službám jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 15, 'V těch dnech viděl jsem v Judstvu, ani tlačí presem v sobotu, a přinášejí snopy, kteréž nakládali na osly, též víno, hrozny, fíky i všeliká břemena, a snášejí v den sobotní do Jeruzaléma. I domlouval jsem jim v ten den, když prodávali potravu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 16, 'Tyrští také, kteříž bydlili v něm, nosili ryby i všelijaké koupě, a prodávali v sobotu synům Juda, a to v Jeruzalémě.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 17, 'Protož jsem domlouval starším Judským, a řekl jsem jim: Jaká jest to nepravost, kterouž činíte, poškvrňujíce dne sobotního?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 18, 'Zdaliž jsou tak nečinili otcové vaši? Pročež Bůh náš přivedl na nás všecko toto zlé, i na toto město, a vy přidáváte hněvivosti na Izraele, poškvrňujíce soboty.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 19, 'Když tedy byly v stínu brány Jeruzalémské před sobotou, rozkázal jsem zavříti brány, a rozkázal jsem, aby jich neotvírali až po sobotě. K tomu i z služebníků svých některé postavil jsem v bráně, aby náklad nebyl vezen do města v sobotu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 20, 'Protož zůstali kupci a prodavači všelijakých věcí prodajných vně před Jeruzalémem, jednou i podruhé.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 21, 'I osvědčil jsem se jim, řka jim: Proč zůstáváte přes noc naproti zdi? Učiníte-li to více, vztáhnu ruku na vás. Od té chvíle nepřicházeli v sobotu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 22, 'Rozkázal jsem pak Levítům, aby se očistili, a přijdouce, ostříhali bran, a světili den sobotní. Také i v tom pamatuj na mne, Bože můj, a buď mi milostiv podlé množství milosrdenství svého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 23, 'V těch dnech spatřil jsem také Židy, kteříž byli pojali ženy Azotské, Ammonitské a Moábské,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 24, 'An synové jejich mluvili od polu Azotsky, a neuměli mluviti Židovsky, ale podlé jazyku každého toho lidu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 25, 'Protož domlouval jsem jim, a zlořečil jsem jim, a některé z nich bil jsem a rval, přísahou je zavazuje skrze Boha, řka: Budete-li dávati dcery své synům jejich, aneb bráti dcery jejich synům svým neb sobě, zlořečení budete.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 26, 'Zdaliž tím nezhřešil Šalomoun král Izraelský? Ješto ve mnohých národech nebylo krále jemu podobného, kterýž byl milý Bohu svému, tak že ustanovil jej Bůh králem nade vším Izraelem, však i toho k hříchu přivedly ženy cizozemky.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 27, 'A vám zdali povolíme, abyste se dopouštěli všeho toho zlého velikého, a přestupovali proti Bohu svému, pojímajíce ženy cizozemky?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 28, 'Z synů pak Joiady syna Eliasiba, kněze nejvyššího, jeden byl zeť Sanballata Choronského, kteréhož jsem zahnal od sebe.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 29, 'Budiž pamětliv na to, Bože můj, proti těm, kteříž poškvrňují kněžství, a smlouvy kněžské i Levítské.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 30, 'Protož jsem je vyčistil od všelikého cizozemce, a ustanovil jsem zase třídy kněžím a Levítům, jednomu každému v práci jeho,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 31, 'I nošení dříví k obětem časy uloženými, též i prvotin. Budiž pamětliv na mne, Bože můj, k mému dobrému.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 1, 'Stalo se pak za času krále Asvera, (to jest ten Asverus, jenž kraloval od Indie až k Mouřenínské zemi nad sto dvadcíti a sedmi krajinami),');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 2, 'Že toho času, když seděl král Asverus na stolici království svého, jenž byla v Susan, městě královském,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 3, 'Léta třetího kralování svého, učinil u sebe hody všechněm knížatům svým a služebníkům svým, nejznamenitějším Perským a Médským, hejtmanům a vládařům nad krajinami,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 4, 'Ukazuje bohatství, slávu království svého a čest, i ozdobu důstojnosti své za mnoho dnů, totiž za sto a osmdesáte dnů.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 5, '(A když se vyplnili dnové ti, učinil král všemu lidu, což ho koli bylo v Susan městě královském, od největšího až do nejmenšího, hody za sedm dní na paláci v zahradě při domě královském.)');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 6, 'Též čalouny bílé, zelené a z postavce modrého, zavěšené na provázcích kmentových a šarlatových u kroužků stříbrných, na sloupích mramorových, lůžka zlatá a stříbrná na podlaze porfyretové a mramorové, pariové a socharetové.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 7, 'Nápoj pak dávali v nádobách zlatých, a to v nádobách jiných a jiných, i vína královského v hojnosti, jakž slušelo na krále.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 8, 'Ale ku pití, podlé nařízení, žádný nenutil. Nebo tak poručil král všechněm správcům domu svého, aby činili podlé vůle jednoho každého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 9, 'Také i královna Vasti učinila hody ženám v domě královském krále Asvera.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 10, 'Dne pak sedmého, když se podveselil král vínem, rozkázal Mehumanovi, Biztovi, Charbonovi, Bigtovi a Abagtovi, Zetarovi a Karkasovi, sedmi komorníkům, kteříž sloužili před oblíčejem krále Asvera,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 11, 'Aby přivedli Vasti královnu před oblíčej krále v koruně královské, aby okázal národům i knížatům krásu její; nebo velmi krásná byla.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 12, 'Ale odepřela královna Vasti přijíti k rozkazu královskému, skrze ty komorníky vzkázanému. Pročež král rozhněval se velmi a rozpálil se hněvem sám v sobě.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 13, 'I řekl král mudrcům znajícím časy, (nebo tak každé věci podával král na všecky zběhlé v právích a soudech),');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 14, 'A nejbližšímu sebe Charsenovi, Setarovi, Admatovi, Tarsisovi, Meresovi, Marsenovi, Memuchanovi, sedmi vývodám Perským a Médským, jenž vídali tvář královskou, a sedali první po králi:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 15, 'Co se má podlé práva státi s královnou Vasti, proto že nevyplnila rozkazu krále Asvera, stalého skrze komorníky?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 16, 'Tedy řekl Memuchan před králem i knížaty: Ne proti samému králi zavinila královna Vasti, ale proti všechněm knížatům, a proti všechněm národům všech krajin Asvera krále.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 17, 'Nebo když se donese to, co učinila královna, všech žen, zlehčí sobě muže své a řeknou: An král Asverus rozkázal přivésti královnu Vasti před oblíčej svůj, a však nepřišla.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 18, 'Nýbrž ještě tohoto dne budou to mluviti kněžny Perské a Médské, (kteréž slyšely, co učinila královna), všechněm knížatům královským, i naplodí se hojně pýchy a zpoury.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 19, 'Jestliže se tedy králi za dobré vidí, nechť se stane výpověď královská od oblíčeje jeho, a nechť jest vepsána mezi práva Perská a Médská, kteráž by nemohla změněna býti, že nechtěla přijíti Vasti před oblíčej krále Asvera, pročež království její dá král jiné, lepší nežli ona.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 20, 'Tak když uslyší výpověd královskou, kterouž vyhlásiti dá po všem království svém, jakkoli veliké jest, všecky ženy v poctivosti míti budou manžely své, od největšího až do nejmenšího.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 21, 'I líbila se ta rada králi i knížatům, a učinil král podlé rady Memuchanovy.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 22, 'A rozeslal listy do všech krajin královských, do jedné každé krajiny písmem jejím, a do každého národu jazykem jeho, aby každý muž byl pánem domu svého. Což oznámil každý hejtman lidu jazykem jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 1, 'Ty věci když se zběhly, a když se upokojila prchlivost krále Asvera, zpomenul na Vasti a na to, což byla učinila, též i na to, jaká se výpověd stala proti ní.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 2, 'I řekli mládenci královští, služebníci jeho: Nechť hledají králi mladic, panen krásných.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 3, 'A nechť zřídí král úředníky ve všech krajinách království svého, kteříž by shromáždili všecky mladice, panny krásné, do Susan města královského, do domu ženského, pod stráž Hegai komorníka královského, strážce žen, a ať jim vydává okrasy jejich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 4, 'A mladice, kteráž by se zalíbila králi, aby kralovala místo Vasti. I líbila se ta věc králi, a učinil tak.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 5, 'Byl pak jeden Žid v Susan, městě královském, jménem Mardocheus syn Jairův, syna Simei, syna Cis, z pokolení Beniamin.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 6, 'A ten byl přestěhován z Jeruzaléma s přestěhovanými, kteříž přestěhováni byli s Jekoniášem králem Judským, kteréhož přestěhoval Nabuchodonozor král Babylonský.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 7, 'Ten choval Hadassu, jinak Esteru, dceru strýce svého, proto že neměla otce ani matky. A děvečka ta byla pěkné postavy a krásné tváři, kterouž po smrti otce a matky její vzal sobě Mardocheus za dceru.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 8, 'Stalo se tedy, když vyšlo slovo královské a rozkaz jeho, a když shromážďováno bylo panen mnoho do Susan, města královského, pod stráž Hegai, že i Ester vzata byla do domu královského pod stráž Hegai, strážného nad ženami.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 9, 'I líbila se jemu ta mladice, a našla milost u něho. Pročež i hned dal jí okrasu její a díl její, a sedm panen způsobných z domu královského; k tomu opatření její i jejích panen proměnil v lepší v domě ženském.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 10, 'Neoznámila pak Ester lidu svého, ani rodiny své; nebo přikázal jí byl Mardocheus, aby nepravila.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 11, 'Ale Mardocheus každého dne chodíval před síní domu ženského, aby zvěděl, jak se má Ester, a co se s ní děje.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 12, 'Když pak přišel jistý čas jedné každé panny, aby vešla před krále Asvera, když se vyplnilo při ní podlé práva žen, za dvanácte měsíců, (nebo za tolik dnů ozdobovaly se, šest měsíců olejem mirrovým, a šest měsíců věcmi vonnými a ozdobami ženskými),');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 13, 'A tak přicházela panna před krále. Cožkoli řekla, dávalo se jí, aby s tím šla z domu žen až k domu královskému.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 14, 'U večer vcházela k králi, a ráno zase odcházela do druhého domu ženského, pod stráž Saasgazy, komorníka královského, strážce ženin. Nepřicházela více k králi, ale jestliže se líbila králi, povolána bývala ze jména.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 15, 'Tedy když přišel čas jistý Estery, dcery Abichaile, strýce Mardocheova, kterouž byl vzal sobě za dceru, aby vešla k králi, nežádala ničeho, než což řekl Hegai komorník královský, strážce žen. I líbila se Ester všechněm, kteříž ji viděli.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 16, 'A tak vzata jest Ester k králi Asverovi do domu jeho královského, měsíce desátého, (jenž jest měsíc Tebet), léta sedmého kralování jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 17, 'I zamiloval král Ester nade všecky jiné ženy, a nalezla milost a lásku u něho nade všecky panny, tak že vstavil korunu královskou na hlavu její, a učinil ji královnou místo Vasti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 18, 'K tomu také učinil král hody veliké všechněm knížatům svým a služebníkům svým, totiž hody Estery, a dal odpočinutí krajinám, a daroval je tak, jakž slušelo na krále.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 19, 'A když podruhé shromažďovány byly panny, a Mardocheus seděl u brány královské,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 20, 'Ester pak neoznámila byla rodiny své a národu svého, jakž jí byl přikázal Mardocheus; nebo rozkázaní Mardocheovo Ester činila, jako i když chována byla u něho:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 21, 'V těch dnech, (když Mardocheus sedal u brány královské), rozhněval se Bigtan a Teres, dva komorníci královští z strážných prahu, a smýšleli o to, aby vztáhli ruce na krále Asvera.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 22, 'Čehož dověděv se Mardocheus, oznámil to Ester královně, Ester pak oznámila králi jménem Mardocheovým.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 23, 'A když bylo toho vyhledáváno, našlo se tak. I oběšeni jsou ti oba na šibenici, a zapsáno jest to do kronik před králem.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 1, 'Po těch věcech zvelebil král Asverus Amana syna Hammedatova Agagského, a vyvýšil ho, tak že vyzdvihl stolici jeho nade všecka jiná knížata, kteříž byli při něm.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 2, 'A všickni služebníci královští, kteříž vcházeli do brány královské, klaněli se a padali před Amanem; nebo tak přikázal o něm král. Ale Mardocheus se neklaněl, ani padal.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 3, 'Protož řekli služebníci královští, kteříž byli v bráně královské, Mardocheovi: Proč přestupuješ přikázaní královské?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 4, 'I stalo se, když o to s ním mluvívali každého dne, a neposlechl jich, že to oznámili Amanovi, aby viděli, bude-li stálý v svých slovích Mardocheus; nebo oznámil jim, že jest Žid.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 5, 'Vida pak Aman, že se Mardocheus neklaní, ani padá před ním, naplněn jest Aman prchlivostí.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 6, 'Ale za malou věc sobě položil, vztáhnouti ruku na Mardochea samého, (nebo byli oznámili jemu, z kterého by lidu byl Mardocheus). Protož smýšlel Aman, aby zahubil národ Mardocheův, totiž všecky Židy, kteříž byli ve všem království Asverovu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 7, 'Takž měsíce prvního, totiž měsíce Nísan, léta dvanáctého kralování Asverova, rozkázal uvrci pur, totiž los, před sebou ode dne ke dni, a od měsíce až do měsíce dvanáctého, jenž jest měsíc Adar.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 8, 'Nebo byl řekl Aman králi Asverovi: Jest lid jakýsi rozptýlený a roztroušený mezi lidem ve všech krajinách království tvého, jejichž práva rozdílná jsou ode všech národů, práv pak královských neostříhají. Protož králi není užitečné, nechati jich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 9, 'Jestliže se králi za dobré vidí, nechť se napíše, aby je zahladili, a já deset tisíc centnéřů stříbra odvážím do rukou představeným té práci, aby je vnesli do komory královské.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 10, 'Tedy král sňav prsten svůj s ruky své, dal jej Amanovi synu Hammedatovu Agagskému, nepříteli Židovskému.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 11, 'A řekl král Amanovi: Stříbro to daruji tobě i lid ten, abys naložil s ním, jakť se koli líbí.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 12, 'Protož povoláni jsou písaři královští téhož měsíce prvního třináctého dne, a psáno jest všecko tak, jakž přikázal Aman, k knížatům královským i vývodám, kteříž byli v jedné každé krajině, i hejtmanům jednoho každého národu, každé krajině vedlé písma jejího, a každému národu vedlé jazyku jeho; jménem krále Asvera psáno, a zapečetěno prstenem královským.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 13, 'I jsou posláni listové po poslích do všech krajin královských, aby hubili, mordovali a vyhladili všecky Židy, od mladého až do starce, děti i ženy, jednoho dne, totiž třináctého, měsíce dvanáctého, (jenž jest měsíc Adar), a loupeže jejich aby rozbitovali.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 14, 'Summa toho psání byla: Aby vyhlášeno bylo v jedné každé krajině a oznámeno všechněm národům, aby hotovi byli ke dni tomu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 15, 'Tedy vyjeli poslové stěží s poručením královským, a vyhlášeno jest to v Susan, městě královském. Král pak a Aman seděli, kvasíce, ale měšťané Susan zkormouceni byli.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 1, 'Mardocheus pak zvěděv všecko to, což se bylo stalo, roztrhl roucho své, a vzal na sebe žíni a popel, a jda po městě, křičel křikem velikým a žalostným.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 2, 'A přišel až před bránu královskou; nebo žádný neměl vcházeti do brány královské v oděvu žíněném.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 3, 'V každé také krajině i místě, kamžkoli slovo královské a výpověd jeho došla, kvílení veliké bylo od Židů, a půst, pláč i úpění, a žíni s popelem podestřeli sobě mnozí.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 4, 'Pročež přišedše děvečky Estery a komorníci její, oznámili jí to. I zarmoutila se královna velmi, a poslala šaty, aby oblékli Mardochea, a aby vzali žíni jeho od něho. Ale on jich nepřijal.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 5, 'Tedy zavolavši Ester Hatacha, jednoho z komorníků královských, kteréhož jí byl dal za služebníka, poručila mu o Mardocheovi, aby přezvěděl, co a proč by to bylo.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 6, 'Takž vyšel Hatach k Mardocheovi na ulici města, kteráž jest před branou královskou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 7, 'I oznámil jemu Mardocheus všecko, co se mu přihodilo, i o té summě peněz, kterouž připověděl Aman dáti do komory královské proti Židům, k vyhlazení jich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 8, 'K tomu i přípis psané výpovědi, kteráž vyhlášena byla v Susan, aby zhubeni byli, dal jemu, aby ukázal Ester a oznámil jí, a aby jí rozkázal jíti k králi, a milosti hledati u něho, a prositi před tváří jeho za lid svůj.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 9, 'Tedy přišel Hatach, a oznámil Ester slova Mardocheova.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 10, 'I řekla Ester Hatachovi, a poručila mu oznámiti Mardocheovi:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 11, 'Všickni služebníci královští i lid krajin královských vědí, že kterýž by koli muž neb žena všel před krále do síně vnitřní, nejsa povolán, jedno právo o něm jest, aby hrdlo propadl, kromě toho, k komuž by král vztáhl berlu zlatou, že živ zůstane. Já pak nebyla jsem povolána, abych vešla k králi již třidceti dnů.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 12, 'Ale když oznámili Mardocheovi slova Estery,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 13, 'Řekl Mardocheus, aby zase oznámeno bylo Esteře: Nemysl sobě, abys zachována býti mohla v domě královském ze všech Židů.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 14, 'Nebo jestliže se umlčíš v tento čas, oddechnutí a vysvobození Židům přijde odjinud, ty pak a dům otce tvého zahynete. A kdo ví, ne pro tento-lis čas přišla k tomu království?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 15, 'I řekla Ester, aby zase oznámili Mardocheovi:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 16, 'Jdi a shromažď všecky Židy, což jest jich v Susan, a posťte se za mne, a nejezte ani píte za tři dni, v noci ani ve dne. Já podobně, i panny mé postiti se budou, a teprv vejdu k králi, což však neobyčejné jest, a jestližeť zahynu, nechť zahynu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 17, 'Tedy šel Mardocheus, a učinil všecko tak, jakž mu poručila Ester.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 1, 'Stalo se potom dne třetího, oblékši se Ester v roucho královské, postavila se v síni vnitřní domu královského, naproti pokoji královskému. Král pak seděl na stolici své královské, v pokoji královském naproti dveřím domu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 2, 'Stalo se, pravím, když uzřel král Ester královnu, ana stojí v síni, že milostí jsa k ní nakloněn, vztáhl král k Ester berlu zlatou, kterouž držel v ruce své. Tedy přistoupivši Ester, dotkla se konce berly.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 3, 'I řekl jí král: Co jest tobě, královno Ester? A jaká jest prosba tvá? Až do polovice království dáno bude tobě.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 4, 'Odpověděla Ester: Jestliže se králi za dobré vidí, nechať přijde král s Amanem dnes na hody, kteréž jsem jemu připravila.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 5, 'I řekl král: Zavolejte rychle Amana, ať naplní žádost Estery. A tak přišel král s Amanem na hody, kteréž byla připravila Ester.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 6, 'Potom řekl král k Ester, napiv se vína. Jaká jest žádost tvá? A budeť dáno. Aneb jaká jest prosba tvá? Bys pak žádala až do polovice království, staneť se.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 7, 'I odpověděla Ester: Žádost má a prosba má jest:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 8, 'Nalezla-li jsem milost u krále, a jestliže se králi za dobré vidí povoliti žádosti mé, a naplniti prosbu mou, aby ještě přišel král i Aman na hody, kteréž jim připravím, a zítra učiním podlé slova královského.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 9, 'A tak vyšel Aman dne toho, vesel jsa a dobré mysli. Ale když viděl Aman Mardochea v bráně královské, že ani nepovstal, ani se nehnul před ním, naplněn jest Aman hněvem proti Mardocheovi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 10, 'A však zdržel se Aman, až přišel do domu svého, a poslav, povolal přátel svých a Zeres ženy své.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 11, 'I vypravoval jim Aman o slávě bohatství svého, i o množství synů svých, i o všem, čímž ho zvelebil král, a jak ho vyvýšil nad knížata i služebníky královské.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 12, 'A doložil Aman: Nadto nepozvala Ester královna s králem na hody, kteréž byla připravila jen mne, a ještě i k zejtří pozván jsem od ní s králem.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 13, 'Ale všecko to nic mi neprospívá, pokudžkoli vídám Mardochea, toho Žida, sedati u brány královské.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 14, 'Řekla jemu Zeres žena jeho, i všickni přátelé jeho: Nechť udělají šibenici zvýši padesáti loket, a ráno rci králi, aby na ní oběsili Mardochea, a vejdi s králem na hody vesele. I líbila se ta rada Amanovi, a rozkázal postaviti šibenici.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 6, 1, 'Té noci král nemoha spáti, rozkázal přinésti knihy pamětné, kroniky, kteréž čteny byly před králem.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 6, 2, 'I našli zapsáno, že pověděl Mardocheus na Bigtana a Teresa, dva komorníky královské z těch, jenž ostříhali prahu, že ukládali vztáhnouti ruku na krále Asvera.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 6, 3, 'Tedy řekl král: Čím jest poctěn, neb jak zveleben Mardocheus za to? Odpověděli služebníci královští, dvořané jeho: Není jemu nic dáno.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 6, 4, 'I řekl král: Kdo jest v síni? (Aman pak byl přišel do síně domu královského zevnitřní, mluviti s králem, aby oběšen byl Mardocheus na šibenici, kterouž jemu připravil.)');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 6, 5, 'Odpověděli králi služebníci jeho: Aj, Aman stojí v síni. Řekl král: Nechť vejde sem.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 6, 6, 'Takž všel Aman. Jemuž řekl král: Co sluší učiniti muži tomu, kteréhož by chtěl král ctíti? (Aman řekl sám v sobě: Kohož by jiného chtěl král více ctíti, nežli mne?)');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 6, 7, 'Odpověděl Aman králi: Muži tomu, jehož král ctíti chce,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 6, 8, 'Ať přinesou roucho královské, do kteréhož se král obláčí, a přivedou koně, na kterémž jezdí král, a vstaví korunu královskou na hlavu jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 6, 9, 'A dadouce roucho to i koně toho v ruku některého z nejznamenitějších knížat královských, ať oblekou muže toho, jehož král chce ctíti, a ať jej vodí na koni po ulici města, a volají před ním: Tak se má státi muži tomu, jehož král ctíti chce.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 6, 10, 'Tedy řekl král Amanovi: Pospěš, vezmi to roucho a koně, jakž jsi řekl, a učiň to Mardocheovi Židu, kterýž sedí v bráně královské. Nepomíjejž ničeho ze všeho toho, což jsi mluvil.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 6, 11, 'Protož vzav Aman roucho i koně, oblékl Mardochea, a vedl jej na koni po ulici města, volaje před ním: Tak se má státi muži tomu, jehož král ctíti chce.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 6, 12, 'Potom navrátil se Mardocheus k bráně královské. Aman pak rychle pospíšil do domu svého, smuten jsa, s zakrytou hlavou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 6, 13, 'I vypravoval Aman Zeres ženě své a všechněm přátelům svým všecko, což se mu přihodilo. I řekli jemu mudrci jeho i Zeres žena jeho: Poněvadž z národu Židovského jest Mardocheus, před jehož oblíčejem počal jsi klesati, neodoláš jemu, ale jistě padneš před oblíčejem jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 6, 14, 'A když oni ještě mluvili s ním, komorníci královští přišli, a rychle vzali Amana na hody, kteréž připravila Ester.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 1, 'A tak přišel král i Aman, aby hodovali s Ester královnou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 2, 'I řekl král k Ester opět druhého dne, napiv se vína: Jaká jest žádost tvá, Ester královno? A budeť dáno. Aneb jaká jest prosba tvá? Až do polovice království staneť se.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 3, 'Tedy odpověděla Ester královna a řekla: Jestliže jsem nalezla milost před očima tvýma, ó králi, a jestliže se králi za dobré vidí, nechť mi jest darován život můj k mé žádosti, a národu mému k prosbě mé.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 4, 'Nebo prodáni jsme, já i národ můj, abychom zbiti, pomordováni a vyhlazeni byli, ješto kdybychom za služebníky a děvky prodáni byli, mlčela bych, ač by i tak ten nepřítel nijakž nemohl nahraditi králi té škody.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 5, 'Opět odpovídaje král Asverus, řekl Ester královně: I kdož jest to ten, a kde jest ten, jehož srdce tak jest naduté, aby to činil?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 6, 'I řekla Ester: Muž protivník a nepřítel nejhorší jest Aman tento. Takž Aman zhrozil se před oblíčejem krále a královny.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 7, 'Tedy král vstal v prchlivosti své od pití vína, a vyšel na zahradu při paláci. Aman pak pozůstal tu, aby prosil za život svůj Estery královny; nebo viděl, že jest o něm zle uloženo od krále.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 8, 'Potom král navrátil se z zahrady palácu do domu, kdež pil víno, a Aman padl na lůžko, na kterémž seděla Ester. I řekl král: Což ještě násilé učiniti chce královně u mne v domě? A hned jakž slovo to vyšlo z úst krále, tvář Amanovu zakryli.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 9, 'Mezi tím řekl Charbona, jeden z komorníků, před králem: Aj, ještě šibenice, kterouž připravil Aman Mardocheovi, kterýž mluvil králi k dobrému, stojí při domě Amanově, zvýší padesáti loket. I řekl král: Oběstež ho na ní.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 10, 'Tedy oběsili Amana na té šibenici, kterouž byl připravil Mardocheovi. A tak prchlivost královská ukojila se.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 1, 'Téhož dne dal král Asverus Ester královně dům Amana nepřítele Židovského, a Mardocheus přišel před krále, (nebo oznámila Ester, co by jí on byl).');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 2, 'Kdežto král sňav prsten svůj, kterýž vzal od Amana, dal jej Mardocheovi. Ester pak ustanovila Mardochea nad domem Amanovým.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 3, 'Potom ještě Ester mluvila před králem, padši k nohám jeho, a s pláčem pokorně ho prosila, aby zrušil nešlechetnost Amana Agagského a jeho úklady, kteréž smyslil proti Židům.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 4, '(Tedy vztáhl král k Esteře berlu zlatou, a Ester vstavši, postavila se před králem.)');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 5, 'A řekla: Jestliže se králi za dobré vidí, a nalezla-li jsem milost před tváří jeho, a jestliže se ta věc králi slušná býti vidí, a já jsem-li příjemná před očima jeho: nechť jest psáno, aby byli zrušeni listové ti, a tak úkladové Amana syna Hammedatova Agagského, kteréž rozepsal, aby vyhladili Židy, což jest jich ve všech krajinách královských.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 6, 'Nebo jak bych se mohla dívati na to zlé, kteréž by potkalo lid můj? A jak bych mohla hleděti na zhoubu rodiny své?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 7, 'I řekl král Asverus Ester královně a Mardocheovi Židu: Ej, dům Amanův dal jsem Esteře, jeho pak oběsili na šibenici, proto že vztáhnouti chtěl ruku svou na Židy.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 8, 'Vy tedy pište Židům, jakž se vám za dobré zdá, jménem královským, a zapečeťte prstenem královským. (Nebo což se píše jménem krále, a zapečetí prstenem královským, nemůže zpátkem jíti.)');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 9, 'Takž svolali písaře královské v ten čas měsíce třetího, jenž jest měsíc Siban, dvadcátého třetího dne téhož měsíce, a psáno jest všecko tak, jakž přikázal Mardocheus, k Židům a knížatům, i vývodám a hejtmanům krajin, kteréž jsou od Indie až do země Mouřenínské, sto dvadceti sedm krajin, do každé krajiny písmem jejím, každému národu jazykem jeho, též i Židům písmem jejich a jazykem jejich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 10, 'A když napsal jménem krále Asvera a zapečetil prstenem královským, rozeslal listy po poslích, kteříž jezdívali na koních rychlých a mezcích mladých:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 11, 'Že jest povolil král Židům, kteříž by v kterémkoli městě byli, aby shromáždíce se, zastávali života svého, a aby hubili, mordovali a plénili všecka vojska národu i krajiny, útok činících na ně, na děti jejich i ženy jejich, a kořisti jejich aby rozbitovali.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 12, 'Jednoho a téhož dne ve všech krajinách krále Asvera, totiž třináctého, měsíce dvanáctého, jenž jest měsíc Adar.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 13, 'Summa toho psání: Aby vyhlášeno bylo v jedné každé krajině, a oznámeno všechněm národům, aby Židé byli hotovi ke dni tomu ku pomstě nad nepřátely svými.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 14, 'Tedy poslové, kteříž jezdívali na koních prudkých a na mezcích, vyjeli snažným a rychlým během s poručením královským, a vyhlášeno jest to v Susan, městě královském.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 15, 'Mardocheus pak vycházel od oblíčeje královského v rouše královském z postavce modrého a bílého, v koruně zlaté veliké a v plášti kmentovém a šarlatovém, a město Susan plésalo a veselilo se.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 16, 'Nebo Židům vzešlo světlo a radost, i veselé a sláva.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 17, 'Ano i v každé krajině i v každém městě, na kteréžkoli místo poručení královské a výpověd jeho došla, veselé a radost měli Židé, hody a dobrou vůli, a mnozí z národů jiných přistupovali k Židům; nebo připadl na ně strach Židovský.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 1, 'Potom dvanáctého měsíce, (jenž jest měsíc Adar), třináctého dne téhož měsíce, když přišel čas poručení královského a výpovědi jeho, aby se vyplnila, v ten den, v kterýž se nadáli nepřátelé Židovští, že budou panovati nad nimi, stalo se na odpor, že panovali Židé nad těmi, kteříž je v nenávisti měli.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 2, 'Nebo se byli shromáždili Židé v městech svých, po všech krajinách krále Asvera, aby vztáhli ruku na ty, kteříž hledali jejich zlého. A žádný před nimi neostál, nebo připadl strach jejich na všecky národy.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 3, 'A všickni hejtmané krajin, i knížata a vývodové, i správcové díla královského v poctivosti měli Židy; nebo strach Mardocheův na ně připadl.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 4, 'Byl zajisté Mardocheus veliký v domě královském, a rozcházela se pověst o něm po všech krajinách; nebo muž ten Mardocheus vždy více rostl.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 5, 'A tak zbili Židé všecky nepřátely své, mečem hubíce, mordujíce a vyhlazujíce je, a nakládajíce s těmi, kteříž je v nenávisti měli, podlé líbosti své.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 6, 'Ano i v Susan městě královském zmordovali Židé a vyhladili pět set mužů.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 7, 'A Parsandata, Dalfona i Aspata,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 8, 'A Porata, Adalia i Aridata,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 9, 'I Parimasta, Arisai i Aridai a Vajezata,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 10, 'Deset synů Amana syna Hammedatova, nepřítele Židovského, zmordovali. Ale k loupeži nevztáhli ruky své.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 11, 'Dne toho, když se donesl krále počet zmordovaných v Susan městě královském,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 12, 'Řekl král Esteře královně: V Susan městě královském zmordovali Židé a vyhladili pět set mužů, a deset synů Amanových. Co pak učinili v jiných krajinách královských? Již tedy jaká jest žádost tvá? A dánoť bude. Aneb která prosba tvá ještě? A staneť se.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 13, 'Odpověděla Ester: jestliže se králi za dobré vidí, nechť jest dopuštěno ještě zítra Židům, kteříž jsou v Susan, učiniti podlé výpovědi dnešní, a deset synů Amanových zvěšeti na šibenici.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 14, 'I přikázal král, aby se tak stalo. Tedy vyhlášena jest výpověd v Susan, a tak deset synů Amanových zvěšeli.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 15, 'A shromáždivše se Židé, kteříž byli v Susan, také i čtrnáctého dne měsíce Adar, zmordovali v Susan tři sta mužů. Ale k loupeži nevztáhli ruky své.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 16, 'Jiní také Židé, kteříž byli v krajinách královských, shromáždivše se, a zastávajíce života svého, tak odpočinuli od nepřátel svých. Zmordovali pak těch, jenž je v nenávisti měli, sedmdesáte pět tisíc. Ale k loupeži nevztáhli ruky své.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 17, 'Stalo se to dne třináctého měsíce Adar. I odpočinuli čtrnáctého dne téhož měsíce, a učinili sobě v ten den hody a veselé.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 18, 'Ale Židé, kteříž byli v Susan, shromáždili se třináctého dne téhož měsíce a též čtrnáctého, a odpočinuli patnáctého, a učinili sobě na ten den hody a veselé.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 19, 'Protož Židé, kteříž bydlí ve vsech a v městečkách nehrazených, světí den čtrnáctý měsíce Adar, majíce veselé, hody a dobrou vůli, a posílajíce částky pokrmů jedni druhým.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 20, 'Nebo rozepsal Mardocheus ty věci, a rozeslal listy ke všem Židům, kteříž byli ve všech krajinách krále Asvera, blízkým i dalekým,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 21, 'Ustavuje jim, aby slavili den čtrnáctý měsíce Adar, a den patnáctý téhož měsíce každého roku,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 22, 'Podlé dnů těch, v nichž odpočinuli Židé od nepřátel svých, a měsíce toho, kterýž se jim obrátil z zámutku v radost, a z kvílení v dobrou vůli, aby ty dni slavili, hodujíce a veselíce se, a posílajíce částky pokrmů jeden druhému, i dary chudým.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 23, 'I přijali to všickni Židé, že budou činiti to, což začali, a což jim psal Mardocheus:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 24, 'Jak Aman syn Hammedatův Agagský, protivník všech Židů, ukládal o Židech, aby je vyhubil a uvrhl pur, totiž los, k setření a zahlazení jejich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 25, 'Ale jak ona vešla před oblíčej krále, poručil král v listech, aby obráceni byli úkladové jeho nešlechetní, kteréž vymyslil proti Židům, na hlavu jeho, a aby ho oběsili i syny jeho na šibenici.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 26, 'I nazvali ty dny Purim, totiž losů, od jména toho pur. A tak z příčiny všech slov listu toho, a což viděli při tom, i což přišlo k nim,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 27, 'Ustavili a přijali Židé na sebe i na símě své, i na všecky připojené k sobě, aby to nepominulo, že budou slaviti ty dva dni podlé vypsání jejich, a podlé určitého času jejich každého roku.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 28, 'A že ti dnové budou pamětní a slavní v každém věku, rodině, krajině a městě; k tomu, že ti dnové Purim nepominou z prostředku Židů, a památka jejich nepřestane u potomků jejich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 29, 'Psala také Ester královna, dcera Abichailova, i Mardocheus Žid pro větší upevnění psání z strany dnů Purim po druhé.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 30, 'A on rozeslal to psání ke všem Židům, do sta dvadcíti sedmi krajin království Asverova, vzkazuje jim pozdravení,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 31, 'Aby tuze drželi dny ty Purim v určité časy jich, jakž je nařídil jim Mardocheus Žid a Ester královna, a jakž to přijali na sebe a na símě své, na pamět postů a křiku jejich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 32, 'A tak výpověd Estery potvrdila ustanovení dnů Purim, což zapsáno jest v knize této.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 10, 1, 'Potom uložil král Asverus daň na zemi i na ostrovy mořské.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 10, 2, 'Všickni pak činové síly jeho a moci jeho, i vypsání důstojnosti Mardocheovy, kterouž ho zvelebil král, to vše zapsáno jest v knize o králích Médských a Perských.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 10, 3, 'Nebo Mardocheus Žid byl druhý po králi Asverovi, a veliký u Židů, i vzácný u všeho množství bratří svých, pečuje o dobré lidu svého, a způsobuje pokoj všemu semeni svému.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 1, 'Byl muž v zemi Uz, jménem Job, a muž ten byl sprostný a upřímý, boje se Boha, a vystříhaje se zlého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 2, 'Kterémuž se narodilo sedm synů a tři dcery.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 3, 'A měl dobytka sedm tisíc ovec, tři tisíce velbloudů, pět set spřežení volů, a pět set oslic, a čeledi služebné velmi mnoho, a byl muž ten vznešenější nade všecky lidi východní.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 4, 'I scházívali se synové jeho, a strojívali hody po domích, každý ve dni svém. Posílávali také, a zvávali své tři sestry, aby jedly a pily s nimi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 5, 'A když vypořádali dny hodů, posílával Job, a posvěcoval jich, a vstávaje ráno, obětoval zápaly podlé počtu všech jich. Nebo říkával Job: Snad zhřešili synové moji, aneb zlořečili Bohu v srdci svém. Tak činíval Job po všecky ty dny.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 6, 'Jednoho pak dne, když přišli synové Boží, aby se postavili před Hospodinem, přišel také i Satan mezi ně.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 7, 'Tedy řekl Hospodin Satanovi: Odkud jdeš? I odpověděl Satan Hospodinu, řka: Procházel jsem zemi, a obcházel jsem ji.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 8, 'I řekl Hospodin Satanovi: Spatřil-lis služebníka mého Joba, že není jemu rovného na zemi, a že jest muž sprostný a upřímý, bojící se Boha a varující se zlého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 9, 'A odpovídaje Satan Hospodinu, řekl: Zdaliž se Job darmo bojí Boha?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 10, 'Zdaž jsi ty ho neohradil i domu jeho a všeho, což má, se všech stran? Dílu rukou jeho požehnal jsi, a dobytek jeho rozmnožil se na zemi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 11, 'Ale vztáhni nyní ruku svou, a dotkni se všeho, což má, nebude-liť zlořečiti v oči.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 12, 'Tedy řekl Hospodin Satanovi: Aj, cožkoli má, v moci tvé buď, toliko na něj nevztahuj ruky své. I vyšel Satan od tváři Hospodinovy.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 13, 'Jednoho pak dne synové a dcery jeho jedli, a pili víno v domě bratra svého prvorozeného.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 14, 'I přišel posel k Jobovi, a řekl: Když volové orali, a oslice se pásly podlé nich,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 15, 'Vpád učinivše Sabejští, zajali je, a služebníky zbili ostrostí meče, a utekl jsem toliko já sám, abych oznámil tobě.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 16, 'A když on ještě mluvil, přišed druhý, řekl: Oheň Boží spadl s nebe, a rozpáliv se na dobytek i na služebníky, sehltil je, já pak utekl jsem toliko sám, abych oznámil tobě.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 17, 'A když ten ještě mluvil, jiný přišed, řekl: Kaldejští sšikovavše tři houfy, připadli na velbloudy, a zajali je, a služebníky zbili ostrostí meče, a utekl jsem toliko já sám, abych oznámil tobě.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 18, 'A když ten ještě mluvil, jiný přišel a řekl: Synové tvoji a dcery tvé jedli, a pili víno v domě bratra svého prvorozeného.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 19, 'A aj, vítr veliký strhl se z té strany od pouště, a udeřil na čtyři úhly domu, tak že se obořil na děti, i zemřeli, a utekl jsem toliko já sám, abych oznámil tobě.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 20, 'Tedy Job vstav, roztrhl roucho své, a oholil hlavu svou, a padna na zem, poklonu učinil.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 21, 'A řekl: Nahý jsem vyšel z života matky své, nahý se také zase tam navrátím. Hospodin dal, Hospodin též odjal. Buď požehnáno jméno Hospodinovo.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 22, 'V tom ve všem nezhřešil Job, a nepřivlastnil Bohu nic nemoudrého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 2, 1, 'I stalo se opět jednoho dne, že když přišli synové Boží, aby se postavili před Hospodinem, přišel také i Satan mezi ně, aby se postavil před Hospodinem.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 2, 2, 'Tedy řekl Hospodin Satanovi: Odkud jdeš? I odpověděl Satan Hospodinu, řka: Procházel jsem zemi, a obcházel jsem ji.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 2, 3, 'I řekl Hospodin Satanovi: Spatřil-lis služebníka mého Joba, že není jemu rovného na zemi, že jest muž sprostný a upřímý, bojící se Boha, a varující se zlého, a že po dnes trvá v upřímnosti své, ačkoli jsi ty mne popudil proti němu, abych jej hubil bez příčiny.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 2, 4, 'A odpovídaje Satan Hospodinu, řekl: Kůži za kůži, a všecko, což má člověk, dá za sebe samého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 2, 5, 'Ale vztáhni nyní ruku svou, a dotkni se kostí jeho, a masa jeho, nebude-liť v oči zlořečiti tobě.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 2, 6, 'Tedy řekl Hospodin Satanovi: Aj, v moci tvé buď, a však zachovej ho při životu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 2, 7, 'Protož vyšed Satan od tváři Hospodinovy, ranil Joba nežitem nejhorším, od zpodku nohy jeho až do vrchu hlavy jeho,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 2, 8, 'Tak že vzal střepinu, aby se jí drbal, usadiv se v popele.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 2, 9, 'I řekla jemu žena jeho: Ještě vždy trváš v své upřímnosti? Zlořeč Bohu a umři.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 2, 10, 'Jížto řekl: Mluvíš, jako jedna z bláznivých mluvívá. Dobré-liž jen věci bráti budeme od Boha, zlých pak nebudeme přijímati? V tom ve všem nezhřešil Job rty svými.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 2, 11, 'Když pak uslyšeli tři přátelé Jobovi o všem tom zlém, kteréž přišlo na něj, přišli jeden každý z místa svého: Elifaz Temanský, a Bildad Suchský a Zofar Naamatský, na tom zůstavše spolu, aby přijdouce k němu, politovali ho a těšili jej.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 2, 12, 'Kteříž pozdvihše očí svých zdaleka, nepoznali ho. Potom pozdvihše hlasu svého, plakali, a roztrhše jeden každý roucho své, házeli prachem nad hlavy své zhůru.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 2, 13, 'A seděli s ním na zemi sedm dní a sedm nocí, a žádný k němu nepromluvil slova; nebo viděli, že se velmi rozmohla bolest jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 1, 'Potom otevřev Job ústa svá, zlořečil dni svému.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 2, 'Nebo mluvě Job, řekl:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 3, 'Ó by byl zahynul ten den, v němž jsem se naroditi měl, i noc, v níž bylo řečeno: Počat jest pacholík.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 4, 'Ten den ó by byl obrácen v temnost, aby ho byl nevyhledával Bůh shůry, a nebyl osvícen světlem.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 5, 'Ó by jej byly zachvátily tmy a stín smrti, a aby jej byla přikvačila mračna, a předěsila horkost denní.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 6, 'Ó by noc tu mrákota byla opanovala, aby nebyla připojena ke dnům roku, a v počet měsíců nepřišla.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 7, 'Ó by noc ta byla osaměla, a zpěvu aby nebylo v ní.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 8, 'Ó by jí byli zlořečili ti, kteříž proklínají den, hotovi jsouce vzbuditi velryba.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 9, 'Ó by se byly hvězdy zatměly v soumraku jejím, a očekávajíc světla, aby ho nebyla dočekala, ani spatřila záře jitřní.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 10, 'Nebo nezavřela dveří života mého, ani skryla trápení od očí mých.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 11, 'Proč jsem neumřel v matce, aneb vyšed z života, proč jsem nezahynul?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 12, 'Proč jsem vzat byl na klín, a proč jsem prsí požíval?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 13, 'Nebo bych nyní ležel a odpočíval, spal bych a měl bych pokoj,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 14, 'S králi a radami země, kteříž sobě vzdělávali místa pustá,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 15, 'Aneb s knížaty, kteříž měli zlato, a domy své naplňovali stříbrem.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 16, 'Aneb jako nedochůdče nezřetelné proč jsem nebyl, a jako nemluvňátka, kteráž světla neviděla?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 17, 'Tamť bezbožní přestávají bouřiti, a tamť odpočívají ti, jenž v práci ustali.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 18, 'Také i vězňové pokoj mají, a neslyší více hlasu násilníka.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 19, 'Malý i veliký tam jsou rovni sobě, a služebník jest prost pána svého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 20, 'Proč Bůh dává světlo zbědovanému a život těm, kteříž jsou ducha truchlivého?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 21, 'Kteříž očekávají smrti, a není jí, ačkoli jí hledají pilněji než skrytých pokladů?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 22, 'Kteříž by se veselili s plésáním a radovali, když by nalezli hrob?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 23, 'Člověku, jehož cesta skryta jest, a jehož Bůh přistřel?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 24, 'Nebo před pokrmem mým vzdychání mé přichází, a rozchází se jako voda řvání mé.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 25, 'To zajisté, čehož jsem se lekal, stalo se mi, a čehož jsem se obával, přišlo na mne.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 26, 'Neměl jsem pokoje, aniž jsem se ubezpečil, ani odpočíval, až i přišlo pokušení toto.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 1, 'Jemuž odpovídaje Elifaz Temanský, řekl:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 2, 'Počneme-li mluviti s tebou, neponeseš-liž toho těžce? Ale kdož by se zdržeti mohl, aby neměl mluviti?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 3, 'Aj, učívals mnohé, a rukou opuštěných jsi posiloval.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 4, 'Padajícího pozdvihovals řečmi svými, a kolena zemdlená jsi zmocňoval.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 5, 'Nyní pak, jakž toto přišlo na tebe, těžce to neseš, a jakž tě dotklo, předěšen jsi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 6, 'Nebylo-liž náboženství tvé nadějí tvou, a upřímost cest tvých očekáváním tvým?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 7, 'Rozpomeň se, prosím, kdo jest kdy nevinný zahynul? Aneb kde upřímí vyhlazeni jsou?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 8, 'Jakož jsem já vídal ty, kteříž orali nepravost, a rozsívali převrácenost, že ji i žali.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 9, 'Od dchnutí Božího hynou, a duchem prchlivosti jeho v nic obracíni bývají.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 10, 'Řvání lva a hlas lvice a zubové mladých lvíčat setříni bývají.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 11, 'Hyne lev, že nemá loupeže, a lvíčata mladá rozptýlena bývají.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 12, 'Nebo i tajně doneslo se mne slovo, a pochopilo ucho mé něco maličko toho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 13, 'V přemyšlováních z vidění nočních, když připadá tvrdý sen na lidi,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 14, 'Strach připadl na mne a lekání, kteréž předěsilo všecky kosti mé.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 15, 'Duch zajisté před tváří mou šel, tak že vlasové vstávali na těle mém.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 16, 'Zastavil se, ale neznal jsem tváři jeho; tvárnost jen byla před očima mýma. Mezi tím mlče, slyšel jsem hlas:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 17, 'Zdaliž může člověk spravedlivějším býti než Bůh, aneb muž čistším nad toho, kterýž ho učinil?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 18, 'Ano mezi služebníky jeho není dokonalosti, a při andělích svých zanechal nedostatku.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 19, 'Čím více při těch, kteříž bydlejí v domích hliněných, jejichž základ jest na prachu, a setříni bývají snáze než mol.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 20, 'Od jitra až do večera stíráni bývají, a kdož toho nerozvažují, na věky zahynou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 21, 'Zdaliž nepomíjí sláva jejich s nimi? Umírají, ale ne v moudrosti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 1, 'Zavolejž tedy, dá-liť kdo odpověd? A k kterému se z svatých obrátíš?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 2, 'Pakli k bláznu, zahubí ho rozhněvání, a nesmyslného zabije prchlivost.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 3, 'Jáť jsem viděl blázna, an se vkořenil, ale hned jsem zle tušil příbytku jeho, řka:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 4, 'Vzdáleniť jsou synové jeho od spasení; nebo potříni budou v bráně, aniž bude, kdo by je vytrhl.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 5, 'Obilé jeho zžíře hladovitý, a i z prostřed trní je vychvátí; nadto sehltí násilník statek takových.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 6, 'Neboť nepochází z prachu trápení, aniž se z země pučí bída.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 7, 'Ale člověk rodí se k bídě, tak jako jiskry z uhlí zhůru létají.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 8, 'Jistě žeť bych já hledal Boha silného, a jemu bych předložil při svou,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 9, 'Kterýž činí věci veliké, nezpytatelné, divné, a jimž počtu není,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 10, 'Kterýž dává déšť na zemi, a spouští vody na pole,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 11, 'Kterýž sází opovržené na místě vysokém, a žalostící vyvyšuje spasením,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 12, 'Kterýž v nic obrací myšlení chytráků, tak aby nemohli k skutku přivésti ruce jejich ničeho,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 13, 'Kterýž lapá moudré v chytrosti jejich; nebo rada převrácených bláznová bývá.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 14, 'Ve dne motají se jako ve tmách, a jako v noci šámají o poledni.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 15, 'Kterýž zachovává od meče a od úst jejich, a chudého od ruky násilníka.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 16, 'Máť zajisté nuzný naději, ale nepravost musí zacpati ústa svá.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 17, 'Aj, jak blahoslavený jest člověk, kteréhož tresce Bůh! A protož káráním Všemohoucího nepohrdej.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 18, 'Onť zajisté uráží, on i obvazuje; raní, ruka jeho také léčí.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 19, 'Z šesti úzkostí vysvobodil by tebe, ano i v sedmi nedotklo by se tebe zlé.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 20, 'V hladu vykoupil by tě od smrti, a v boji od moci meče.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 21, 'Když utrhá jazyk, byl bys skryt, aniž bys se bál zhouby, když by přišla.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 22, 'Zhouba a hlad buď tobě za smích, a nestrachuj se ani líté zvěři zemské.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 23, 'Nebo s kamením polním příměří tvé, a zvěř lítá polní pokoj zachová k tobě.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 24, 'A shledáš, žeť stánek tvůj bude bezpečný, a navrátíš se zase k příbytku svému, a nezhřešíš.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 25, 'Shledáš také, žeť se rozmnoží símě tvé, a potomci tvoji jako bylina zemská.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 26, 'Vejdeš v šedinách do hrobu, tak jako odnášíno bývá zralé obilí časem svým.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 27, 'Aj, toť jsme vyhledali, a takť jest; poslechniž toho, a schovej sobě to.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 1, 'Odpovídaje pak Job, řekl:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 2, 'Ó kdyby pilně zváženo bylo hořekování mé, a bída má na váze aby spolu vyzdvižena byla.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 3, 'Jistě že by se nad písek mořský těžší ukázala, pročež mi se i slov nedostává.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 4, 'Nebo střely Všemohoucího vězí ve mně, jejichž jed vysušil ducha mého, a hrůzy Boží bojují proti mně.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 5, 'Zdaliž řve divoký osel nad mladistvou travou? Řve-liž vůl nad picí svou?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 6, 'Zdaliž jedí to, což neslaného jest, bez soli? Jest-liž chut v věci slzké?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 7, 'Ach, kterýchž se ostýchala dotknouti duše má, ty jsou již bolesti těla mého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 8, 'Ó by se naplnila žádost má, a aby to, čehož očekávám, dal Bůh,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 9, 'Totiž, aby se líbilo Bohu setříti mne, vztáhnouti ruku svou, a zahladiti mne.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 10, 'Neboť mám ještě, čím bych se potěšoval, (ačkoli hořím bolestí, aniž mne Bůh co lituje), že jsem netajil řečí Nejsvětějšího.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 11, 'Nebo jaká jest síla má, abych potrvati mohl? Aneb jaký konec můj, abych prodlel života svého?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 12, 'Zdali síla má jest síla kamenná? Zdali tělo mé ocelivé?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 13, 'Zdaliž pak obrany mé není při mně? Aneb zdravý soud vzdálen jest ode mne,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 14, 'Proti tomu, jehož lítostivost k bližnímu mizí, a kterýž bázeň Všemohoucího opustil?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 15, 'Bratří moji zmýlili mne jako potok, pominuli jako prudcí potokové,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 16, 'Kteříž kalní bývají od ledu, a v nichž se kryje sníh.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 17, 'V čas horka vysychají; když sucho bývá, mizejí z místa svého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 18, 'Sem i tam roztěkají se od toku svého obecného, v nic se obracejí a hynou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 19, 'To vidouce houfové jdoucích z Tema, zástupové Sabejských, jenž naději měli v nich,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 20, 'Zastyděli se, že v nich doufali; nebo přišedše až k nim, oklamáni jsou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 21, 'Tak zajisté i vy byvše, ne jste; vidouce potření mé, děsíte se.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 22, 'Zdali jsem řekl: Přineste mi, aneb z zboží svého udělte darů pro mne?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 23, 'Aneb: Vysvoboďte mne z ruky nepřítele, a z ruky násilníků vykupte mne?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 24, 'Poučte mne, a budu mlčeti, a v čem bych bloudil, poslužte mi k srozumění.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 25, 'Ó jak jsou pronikavé řeči upřímé! Ale co vzdělá obviňování vaše?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 26, 'Zdali jen z slov mne viniti myslíte, a převívati řeči choulostivého?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 27, 'Také i na sirotka se obořujete, anobrž jámu kopáte příteli svému.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 28, 'A protož nyní chtějtež popatřiti na mne, a suďte, klamám-liť před oblíčejem vaším.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 29, 'Napravte se, prosím, nechť není nepravostí; napravte se, pravím, a tak poznáte, žeť jest spravedlnost v té řeči mé.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 30, 'A jest-li na jazyku mém nepravost, neměl-liž bych, čitedlen býti bíd?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 1, 'Zdaliž nemá vyměřeného času člověk na zemi? A dnové jeho jako dnové nájemníka.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 2, 'Jako služebník, kterýž touží po stínu, a jako nájemník, jenž očekává skonání díla svého:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 3, 'Tak jsou mi dědičně přivlastněni měsícové marní, a noci plné trápení jsou mi odečteny.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 4, 'Jestliže ležím, říkám: Kdy vstanu? A brzo-li pomine noc? Tak pln bývám myšlení až do svitání.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 5, 'Tělo mé odíno jest červy a strupem i prachem, kůže má puká se a rozpouští.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 6, 'Dnové moji rychlejší byli nežli člunek tkadlce, nebo stráveni jsou bez prodlení.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 7, 'Rozpomeň se, ó Pane, že jako vítr jest život můj, a oko mé že více neuzří dobrých věcí,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 8, 'Aniž mne spatří oko, jenž mne vídalo. Oči tvé budou ke mně, a mne již nebude.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 9, 'Jakož oblak hyne a mizí, tak ten, kterýž sstupuje do hrobu, nevystoupí zase,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 10, 'Aniž se opět navrátí do domu svého, aniž ho již více pozná místo jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 11, 'Protož nemohuť já zdržeti úst svých, mluvím v ssoužení ducha svého, naříkám v hořkosti duše své.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 12, 'Zdali jsem já mořem čili velrybem, že jsi mne stráží osadil?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 13, 'Když myslím: Potěší mne lůže mé, poodejme naříkání mého postel má:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 14, 'Tedy mne strašíš sny, a viděními děsíš mne,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 15, 'Tak že sobě zvoluje zaškrcení duše má, a smrt nad život.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 16, 'Mrzí mne, nebuduť déle živ. Poodstupiž ode mne, nebo marní jsou dnové moji.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 17, 'Co jest člověk, že ho sobě tak vážíš, a že tak o něj pečuješ?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 18, 'A že ho navštěvuješ každého jitra, a každé chvíle jej zkušuješ?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 19, 'Dokudž se neodvrátíš ode mne, a nedáš mi aspoň polknouti mé sliny?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 20, 'Zhřešil jsem, což mám učiniti, ó strážce lidský? Proč jsi mne položil za cíl sobě, tak abych sám sobě byl břemenem?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 21, 'Nýbrž proč neodejmeš přestoupení mého, a neodpustíš nepravosti mé? Nebo již v zemi lehnu. Potom bys mne i pilně hledal, nebude mne.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 1, 'Tedy odpovídaje Bildad Suchský, řekl:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 2, 'Dokudž mluviti budeš takové věci, a slova úst tvých budou jako vítr násilný?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 3, 'Což by Bůh silný neprávě soudil, a Všemohoucí což by převracel spravedlnost?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 4, 'Synové zajisté tvoji že zhřešili proti němu, proto pustil je po nepravosti jejich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 5, 'Kdybys ty opravdově hledal Boha silného, a Všemohoucímu se modlil,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 6, 'A byl čistý a upřímý: jistě žeť by se hned probudil k tobě, a napravil by příbytek spravedlnosti tvé.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 7, 'A byly by první věci tvé špatné, poslední pak rozmnožily by se náramně.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 8, 'Nebo vzeptej se, prosím, věku starého, a nastroj se k zpytování otců jejich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 9, '(Myť zajisté včerejší jsme, aniž jsme čeho povědomi; k tomu dnové naši jsou jako stín na zemi.)');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 10, 'Zdaliž tě oni nenaučí, a nepovědí tobě, a z srdce svého nevynesou-liž slov?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 11, 'Zdali roste třtí bez bahna? Roste-liž rákosí bez vody?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 12, 'Nýbrž ještě za zelena, dříve než vytrháno bývá, ano prvé než jaká jiná tráva, usychá.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 13, 'Tak stezky všech zapomínajících se na Boha silného, tak, pravím, naděje pokrytce zahyne.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 14, 'Klesne naděje jeho, a doufání jeho jako dům pavouka.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 15, 'Spolehne-li na dům svůj, neostojí; chytí-li se ho, nezdrží.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 16, 'Vláhu má před sluncem, tak že z zahrady jeho výstřelkové jeho vynikají.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 17, 'Při vrchovišti kořenové jeho hustě rostou, i na místech skalnatých rozkládá se.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 18, 'A však bývá-li zachvácen z místa svého, až by se ho i odečtlo, řka: Nevidělo jsem tě:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 19, 'Tožť ta radost života jeho, a z země jiný vykvetá.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 20, 'Aj, Bůh silný nepohrdá upřímým, ale nešlechetným ruky nepodává:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 21, 'Až i naplní smíchem ústa tvá, a rty tvé plésáním,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 22, 'Když nenávidící tebe v hanbu oblečeni budou, a stánku lidí bezbožných nikdež nebude.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 1, 'Odpověděv pak Job, řekl:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 2, 'I ovšem vím, žeť tak jest; nebo jak by mohl člověk spravedliv býti před Bohem silným?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 3, 'A chtěl-li by se hádati s ním, nemohl by jemu odpovědíti ani na jedno z tisíce slov.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 4, 'Moudrého jest srdce a silný v moci. Kdo zatvrdiv se proti němu, pokoje užil?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 5, 'On přenáší hory, než kdo shlédne, a podvrací je v prchlivosti své.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 6, 'On pohybuje zemí z místa jejího, tak že se třesou sloupové její.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 7, 'On když zapovídá slunci, nevychází, a hvězdy zapečeťuje.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 8, 'On roztahuje nebe sám, a šlapá po vlnách mořských.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 9, 'On učinil Arktura, Oriona, Kuřátka a hvězdy skryté na poledne.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 10, 'On činí věci veliké, a to nevystižitelné a divné, jimž není počtu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 11, 'Ano jde-li mimo mne, tedy nevidím; ovšem když pomíjí, neznamenám ho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 12, 'Tolikéž jestliže co uchvátí, kdo mu to rozkáže navrátiti? Kdo dí jemu: Co činíš?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 13, 'Nezdržel-li by Bůh hněvu svého, klesli by před ním spolu spuntovaní, jakkoli mocní.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 14, 'Jakž bych já tedy jemu odpovídati, a jaká slova svá proti němu vyhledati mohl?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 15, 'Kterémuž, bych i spravedliv byl, nebudu odpovídati, ale před soudcím svým pokořiti se budu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 16, 'Ač bych pak i volal, a on mi se ozval, neuvěřím, aby vyslyšel hlas můj,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 17, 'Poněvadž vichřicí setřel mne, rozmnožil rány mé bez příčiny.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 18, 'Aniž mi dá oddechnouti, ale sytí mne hořkostmi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 19, 'Obrátil-li bych se k moci, aj, onť jest nejsilnější; pakli k soudu, kdo mi rok složí?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 20, 'Jestliže se za spravedlivého stavěti budu, ústa má potupí mne; pakli za upřímého, převráceného mne býti ukáží.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 21, 'Jsem-li upřímý, nebudu věděti toho; nenáviděti budu života svého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 22, 'Jediná jest věc, pročež jsem to mluvil, že upřímého jako bezbožného on zahlazuje.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 23, 'Jestliže bičem náhle usmrcuje, zkušování nevinných se posmívá;');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 24, 'Země dána bývá v ruku bezbožného, tvář soudců jejich zakrývá: jestliže ne on, kdož jiný jest?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 25, 'Dnové pak moji rychlejší byli nežli posel; utekli, aniž viděli dobrých věcí.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 26, 'Pominuli jako prudké lodí, jako orlice letící na pastvu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 27, 'Dím-li: Zapomenu se na své naříkání, zanechám horlení svého, a posilím se:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 28, 'Lekám se všech bolestí svých, vida, že mne jich nezprostíš.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 29, 'Jestli jsem bezbožný, pročež bych nadarmo pracoval?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 30, 'Ano bych se i umyl vodou sněžnou, a očistil mýdlem ruce své,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 31, 'Tedy v jámě pohřížíš mne, tak že se ode mne zprzní i to roucho mé.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 32, 'Nebo Bůh není člověkem jako já, jemuž bych odpovídati mohl, a abychom vešli spolu v soud.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 33, 'Aniž máme prostředníka mezi sebou, kterýž by rozhodl nás oba.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 34, 'Kdyby odjal ode mne prut svůj, a strach jeho aby mne nekormoutil,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 35, 'Tehdáž bych mluvil, a nebál bych se, poněvadž není toho tak při mně.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 1, 'Stýště se duši mé v životě mém, vypustím nad sebou naříkání své, mluviti budu v hořkosti duše své.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 2, 'Dím Bohu: Neodsuzuj mne, oznam mi, proč se nesnadníš se mnou?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 3, 'Jaký máš na tom užitek, že mne ssužuješ, že pohrdáš dílem rukou svých, a radu bezbožných osvěcuješ?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 4, 'Zdali oči tělesné máš? Zdali tak, jako hledí člověk, ty hledíš?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 5, 'Zdaž jsou jako dnové člověka dnové tvoji, a léta tvá podobná dnům lidským,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 6, 'Že vyhledáváš nepravosti mé, a na hřích můj se vyptáváš?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 7, 'Ty víš, žeť nejsem bezbožný, ačkoli není žádného, kdo by mne vytrhl z ruky tvé.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 8, 'Ruce tvé sformovaly mne, a učinily mne, a teď pojednou všudy vůkol hubíš mne.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 9, 'Pamětliv buď, prosím, že jsi mne jako hlinu učinil, a že v prach zase obrátíš mne.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 10, 'Zdalis mne jako mléka neslil, a jako syření neshustil?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 11, 'Kůží a masem přioděl jsi mne, a kostmi i žilami spojils mne.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 12, 'Života z milosrdenství udělil jsi mi, přesto navštěvování tvé ostříhalo dýchání mého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 13, 'Ale toto skryl jsi v srdci svém; vím, žeť jest to při tobě.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 14, 'Jakž zhřeším, hned mne šetříš, a od nepravosti mé neočišťuješ mne.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 15, 'Jestliže jsem bezbožný, běda mně; pakliť jsem spravedlivý, ani tak nepozdvihnu hlavy, nasycen jsa hanbou, a vida trápení své,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 16, 'Kteréhož vždy více přibývá. Honíš mne jako lev, a jedno po druhém divně se mnou zacházíš.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 17, 'Obnovuješ svědky své proti mně, a rozmnožuješ rozhněvání své na mne; vojska jedna po druhých jsou proti mně.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 18, 'Proč jsi jen z života vyvedl mne? Ó bych byl zahynul, aby mne bylo ani oko nevidělo,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 19, 'A abych byl, jako by mne nikdy nebylo, z života do hrobu abych byl vnesen.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 20, 'Zdaliž jest mnoho dnů mých? Ponechejž tedy a popusť mne, abych maličko pookřál,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 21, 'Prvé než odejdu tam, odkudž se zase nenavrátím, do krajiny tmavé, anobrž stínu smrti,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 22, 'Do krajiny, pravím, tmavé, kdež jest sama mrákota stínu smrti, a kdež není žádných proměn, ale sama pouhá mrákota.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 1, 'A odpovídaje Zofar Naamatský, řekl:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 2, 'Zdaliž k mnohým slovům nemá odpovědíno býti? Aneb zdali člověk mnohomluvný práv zůstane?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 3, 'Žváním svým lidi zaměstknáváš, a posmíváš se, aniž jest, kdo by tě zahanbil.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 4, 'Nebo jsi řekl: Čisté jest učení mé, a čist jsem, ó Bože, před očima tvýma.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 5, 'Ješto, ó kdyby Bůh mluvil, a otevřel rty své proti tobě,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 6, 'Aťby oznámil tajemství moudrosti, že dvakrát většího trestání zasloužil jsi. A věz, že se Bůh zapomněl na tebe pro nepravost tvou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 7, 'Zdaliž ty stižitelnosti Boží dosáhneš, aneb dokonalost Všemohoucího vystihneš?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 8, 'Vyšší jest nebes, což učiníš? Hlubší než peklo, jakž porozumíš?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 9, 'Delší jest míra její než země, a širší než moře.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 10, 'Bude-li pléniti neb zavírati aneb ssužovati, kdo se na něj bude domlouvati?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 11, 'Poněvadž zná lidskou marnost, a vidí nepravost, což by tomu rozuměti neměl?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 12, 'Tak aby muž nesmyslný nabyl rozumu, ačkoli člověk jest jako hřebec z divokého osla zplozený.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 13, 'Jestliže ty nastrojíš srdce své, a ruce své k němu vztáhneš;');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 14, 'Byla-li by nepravost v ruce tvé, vzdal ji od sebe, aniž dopouštěj bydliti v staních svých nešlechetnosti:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 15, 'Tedy jistě pozdvihneš tváři své z poškvrny, a budeš nepohnutý, aniž se báti budeš.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 16, 'Nebo se na těžkost zapomeneš, na niž jako na vody, kteréž pominuly, zpomínati budeš.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 17, 'K tomu nad poledne jasný nastaneť čas; zatmíš-li se pak, jitru podobný budeš.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 18, 'Budeš i mysli doufanlivé, maje naději; stánek roztáhneš, i bezpečně spáti budeš.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 19, 'A tak v pokoji budeš, aniž tě kdo předěsí, a mnozí tváři tvé kořiti se budou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 20, 'Oči pak bezbožných zkaženy budou, a utíkání jim zhyne; nadto naděje jejich bude jako dchnutí člověka.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 1, 'Odpověděv pak Job, řekl:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 2, 'V pravdě, že jste vy lidé, a že s vámi umře moudrost.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 3, 'I jáť mám srdce jako vy, aniž jsem zpozdilejší než vy, anobrž při komž toho není?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 4, 'Za posměch příteli svému jsem, kteréhož, když volá, vyslýchá Bůh; v posměchuť jest spravedlivý a upřímý.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 5, 'Pochodně zavržená jest (podlé smýšlení člověka pokoje užívajícího) ten, kterýž jest blízký pádu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 6, 'Pokojné a bezpečné příbytky mají loupežníci ti, kteříž popouzejí Boha silného, jimž on uvodí dobré věci v ruku jejich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 7, 'Ano zeptej se třebas hovad, a naučí tě, aneb ptactva nebeského, a oznámí tobě.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 8, 'Aneb rozmluv s zemí, a poučí tě, ano i ryby mořské vypravovati budou tobě.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 9, 'Kdo nezná ze všeho toho, že ruka Hospodinova to učinila?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 10, 'V jehož ruce jest duše všelikého živočicha, a duch každého těla lidského.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 11, 'Zdaliž ucho slov rozeznávati nebude, tak jako dásně pokrmu okoušejí?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 12, 'Při starcích jest moudrost, a při dlouhověkých rozumnost.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 13, 'Nadto pak u Boha moudrost a síla, jehoť jest rada a rozumnost.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 14, 'Jestliže on boří, nemůže zase stavíno býti; zavírá-li člověka, nemůže býti otevříno.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 15, 'Hle, tak zastavuje vody, až i vysychají, a tak je vypouští, že podvracejí zemi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 16, 'U něho jest síla a bytnost, jeho jest ten, kterýž bloudí, i kterýž v blud uvodí.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 17, 'On uvodí rádce v nemoudrost, a z soudců blázny činí.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 18, 'Svazek králů rozvazuje, a pasem přepasuje bedra jejich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 19, 'On uvodí knížata v nemoudrost, a mocné vyvrací.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 20, 'On odjímá řeč výmluvným, a soud starcům béře.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 21, 'On vylévá potupu na urozené, a sílu mocných zemdlívá.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 22, 'On zjevuje hluboké věci z temností, a vyvodí na světlo stín smrti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 23, 'On rozmnožuje národy i hubí je, rozšiřuje národy i zavodí je.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 24, 'On odjímá srdce předním z lidu země, a v blud je uvodí na poušti bezcestné,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 25, 'Aby šámali ve tmě bez světla. Summou, činí, aby bloudili jako opilý.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 1, 'Aj, všecko to vidělo oko mé, slyšelo ucho mé, a srozumělo tomu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 2, 'Jakož vy znáte to, znám i já, nejsem zpozdilejší než vy.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 3, 'Jistě žeť já s Všemohoucím mluviti, a s Bohem silným o svou při jednati budu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 4, 'Nebo vy jste skladatelé lži, a lékaři marní všickni vy.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 5, 'Ó kdybyste aspoň mlčeli, a bylo by vám to za moudrost.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 6, 'Slyštež medle odpory mé, a důvodů rtů mých pozorujte.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 7, 'Zdali zastávajíce Boha silného, mluviti máte nepravost? Aneb za něho mluviti máte lest?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 8, 'Zdaliž osobu jeho přijímati budete, a o Boha silného se zasazovati?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 9, 'Zdaž vám to k dobrému bude, když na průbu vezme vás, že jakož člověk oklamán bývá, oklamati jej chcete?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 10, 'V pravdě žeť vám přísně domlouvati bude, budete-li povrchně osoby jeho šetřiti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 11, 'Což ani důstojnost jeho vás nepředěšuje, ani strach jeho nepřikvačuje vás?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 12, 'Všecka vzácnost vaše podobná jest popelu, a hromadám bláta vyvýšení vaše.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 13, 'Postrptež mne, nechať já mluvím, přiď na mne cokoli.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 14, 'Pročež bych trhati měl maso své zuby svými, a duši svou klásti v ruku svou?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 15, 'By mne i zabil, což bych v něho nedoufal? A však cesty své před oblíčej jeho předložím.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 16, 'Onť sám jest spasení mé; nebo před oblíčej jeho pokrytec nepřijde.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 17, 'Poslouchejte pilně řeči mé, a zprávu mou pusťte v uši své.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 18, 'Aj, jižť začínám pře své vésti, vím, že zůstanu spravedliv.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 19, 'Kdo jest, ješto by mi odpíral, tak abych nyní umlknouti a umříti musil?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 20, 'Toliko té dvoji věci, ó Bože, nečiň mi, a tehdy před tváří tvou nebudu se skrývati:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 21, 'Ruku svou vzdal ode mne, a hrůza tvá nechť mne neděsí.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 22, 'Zatím povolej mne, a buduť odpovídati; aneb nechať já mluvím, a odpovídej mi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 23, 'Jak mnoho jest mých nepravostí a hříchů? Přestoupení mé a hřích můj ukaž mi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 24, 'Proč tvář svou skrýváš, a pokládáš mne sobě za nepřítele?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 25, 'Zdaliž list větrem se zmítající potříti chceš, a stéblo suché stihati budeš?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 26, 'Že zapisuješ proti mně hořkosti, a dáváš mi v dědictví nepravosti mladosti mé,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 27, 'A dáváš do klady nohy mé, a šetříš všech stezek mých, na paty noh mých našlapuješ;');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 28, 'Ješto člověk jako hnis kazí se, a jako roucho, kteréž jí mol.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 1, 'Člověk narozený z ženy jest krátkého věku a plný lopotování.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 2, 'Jako květ vychází a podťat bývá, a utíká jako stín, a netrvá.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 3, 'A však i na takového otvíráš oko své, a mne uvodíš k soudu s sebou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 4, 'Kdo toho dokáže, aby čistý z nečistého pošel? Ani jeden.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 5, 'Poněvadž vyměřeni jsou dnové jeho, počet měsíců jeho u tebe, a cíles jemu položil, kterýchž by nepřekračoval:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 6, 'Odvrať se od něho, ať oddechne sobě, a zatím aby přečekal jako nájemník den svůj.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 7, 'O stromu zajisté jest naděje, by i podťat byl, že se zase zotaví, a výstřelek jeho nevyhyne,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 8, 'By se pak i sstaral v zemi kořen jeho, a v prachu již jako umřel peň jeho:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 9, 'Avšak jakž počije vláhy, zase se pučí, a zahustí jako keř.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 10, 'Ale člověk umírá, mdlobou přemožen jsa, a když vypustí duši člověk, kam se poděl?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 11, 'Jakož ucházejí vody z jezera, a řeka opadá a vysychá:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 12, 'Tak člověk, když lehne, nevstává zase dotud, dokudž nebes stává. Nebývajíť vzbuzeni lidé, aniž se probuzují ze sna svého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 13, 'Ó kdybys mne v hrobě schoval, a skryl mne, dokudž by nebyl odvrácen hněv tvůj, ulože mi cíl, abys se rozpomenul na mne.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 14, 'Když umře člověk, zdaliž zase ožive? Po všecky tedy dny vyměřeného času svého očekávati budu, až přijde proměna při mně.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 15, 'Zavoláš, a já se ohlásím tobě, díla rukou svých budeš žádostiv,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 16, 'Ačkoli nyní kroky mé počítáš, aniž shovíváš hříchům mým,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 17, 'Ale zapečetěné maje jako v pytlíku přestoupení mé, ještě přikládáš k nepravosti mé.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 18, 'Jistě že jako hora padnuc, rozdrobuje se, a skála odsedá z místa svého,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 19, 'Jako kamení stírá voda, a povodní zachvacuje, což z prachu zemského samo od sebe roste: tak i ty naději člověka v nic obracíš.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 20, 'Přemáháš jej ustavičně, tak aby odjíti musil; proměňuješ tvář jeho, a propouštíš jej.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 21, 'Budou-li slavní synové jeho, nic neví; pakli v potupě, nic o ně nepečuje.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 22, 'Toliko tělo jeho, dokudž živ jest, bolestí okouší, a duše jeho v něm kvílí.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 1, 'Tedy odpovídaje Elifaz Temanský, řekl:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 2, 'Zdali moudrý vynášeti má umění povětrné, aneb naplňovati východním větrem břicho své,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 3, 'Hádaje se slovy neprospěšnými, aneb řečmi neužitečnými?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 4, 'Anobrž vyprazdňuješ i bázeň Boží, a modliteb k Bohu činiti se zbraňuješ.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 5, 'Osvědčujíť zajisté nepravost tvou ústa tvá, ač jsi koli sobě zvolil jazyk chytrých.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 6, 'Potupují tě ústa tvá, a ne já, a rtové tvoji svědčí proti tobě.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 7, 'Zdaliž ty nejprv z lidí zplozen jsi, aneb prvé než pahrbkové sformován?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 8, 'Zdaliž jsi tajemství Boží slyšel, že u sebe zavíráš moudrost?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 9, 'Co víš, čehož bychom nevěděli? Čemu rozumíš, aby toho při nás nebylo?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 10, 'I šedivýť i stařec mezi námi jest, ano i starší věkem než otec tvůj.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 11, 'Zdali malá jsou tobě potěšování Boha silného, čili něco je zastěňuje tobě?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 12, 'Tak-liž tě jalo srdce tvé, a tak-liž blíkají oči tvé,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 13, 'Že smíš odpovídati Bohu silnému tak pyšně, a vypouštěti z úst svých ty řeči?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 14, 'Nebo což jest člověk, aby se mohl očistiti, aneb spravedliv býti narozený z ženy?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 15, 'An při svatých jeho není dokonalosti, a nebesa nejsou čistá před očima jeho,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 16, 'Nadto ohavný a neužitečný člověk, kterýž pije nepravost jako vodu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 17, 'Já oznámím tobě, poslyš mne; to zajisté, což jsem viděl, vypravovati budu,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 18, 'Což moudří vynesli a nezatajili, slýchavše od předků svých.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 19, 'Jimž samým dána byla země, aniž přejíti mohl cizí prostředkem jejich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 20, 'Po všecky své dny bezbožný sám se bolestí trápí, po všecka, pravím léta, skrytá před ukrutníkem.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 21, 'Zvuk strachu jest v uších jeho, že i v čas pokoje zhoubce připadne na něj.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 22, 'Nevěří, by se měl navrátiti z temností, ustavičně očekávaje na sebe meče.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 23, 'Bývá i tulákem, chleba hledaje, kde by byl, cítě, že pro něj nastrojen jest den temností.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 24, 'Děsí jej nátisk a ssoužení, kteréž se silí proti němu, jako král s vojskem sšikovaným.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 25, 'Nebo vztáhl proti Bohu silnému ruku svou, a proti Všemohoucímu postavil se.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 26, 'Útok učinil na něj, na šíji jeho s množstvím zdvižených štítů svých.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 27, 'Nebo přiodíl tvář svou tukem svým, tak že se mu nadělalo faldů na slabinách.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 28, 'A bydlil v městech zkažených, a v domích, v nichž žádný nebydlil, kteráž v hromady rumu obrácena byla.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 29, 'Avšak nezbohatneť, aniž stane moc jeho, aniž se rozšíří na zemi dokonalost takových.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 30, 'Nevyjde z temností, mladistvou ratolest jeho usuší plamen, a tak zahyne od ducha úst svých.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 31, 'Ale nevěří, že v marnosti jest ten, jenž bloudí, a že marnost bude směna jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 32, 'Před časem svým vyťat bude, a ratolest jeho nebude se zelenati.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 33, 'Zmaří, jako vinný kmen nezralý hrozen svůj, a svrže květ svůj jako oliva.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 34, 'Nebo shromáždění pokrytce spustne, a oheň spálí stany oslepených dary.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 35, 'Kteřížto když počali ssužování, a porodili nepravost, hned břicho jejich strojí jinou lest.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 1, 'A odpovídaje Job, řekl:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 2, 'Slyšel jsem již podobných věcí mnoho; všickni vy nepříjemní jste těšitelé.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 3, 'Bude-liž kdy konec slovům povětrným? Aneb co tě popouzí, že tak mluvíš?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 4, 'Zdaliž bych já tak mluviti mohl, jako vy, kdybyste byli na místě mém? Shromažďoval-li bych proti vám slova, aneb potřásal na vás hlavou svou?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 5, 'Nýbrž posiloval bych vás ústy svými, a otvírání rtů mých krotilo by bolest.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 6, 'Buď že mluvím, neumenšuje se bolesti mé, buď že tak nechám, neodchází ode mne.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 7, 'Ale ustavičně zemdlívá mne; nebo jsi mne, ó Bože, zbavil všeho shromáždění mého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 8, 'A vrásky jsi mi zdělal; což mám za svědka, ano patrná na mně hubenost má na tváři mé to osvědčuje.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 9, 'Prchlivost jeho zachvátila mne, a vzal mne v nenávist, škřipě na mne zuby svými; jako nepřítel můj zaostřil oči své na mne.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 10, 'Rozedřeli na mne ústa svá, potupně mne poličkujíce, proti mně se shromáždivše.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 11, 'Vydal mne Bůh silný nešlechetníku, a v ruce bezbožných uvedl mne.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 12, 'Pokoje jsem užíval, však potřel mne, a uchopiv mne za šíji mou, roztříštil mne, a vystavil mne sobě za cíl.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 13, 'Obklíčili mne střelci jeho, rozťal ledví má beze vší lítosti, a vylil na zem žluč mou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 14, 'Ranil mne ranou na ránu, outok učinil na mne jako silný.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 15, 'Žíni jsem ušil na zjízvenou kůži svou, a zohavil jsem v prachu sílu svou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 16, 'Tvář má oduřavěla od pláče, a na víčkách mých stín smrti jest.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 17, 'Ne pro nějaké bezpraví v rukou mých; nebo i modlitba má čistá jest.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 18, 'Ó země, nepřikrývej krve mé, a nechť nemá místa volání mé.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 19, 'Aj, nyní jestiť i v nebesích svědek můj, svědek můj, pravím, jest na výsostech.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 20, 'Ó mudráci moji, přátelé moji, k Bohuť slzí oko mé.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 21, 'Ó by lze bylo muži v hádku s ním se vydati, jako synu člověka s přítelem svým.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 22, 'Nebo léta mně odečtená přicházejí, a cestou, kterouž se zase nenavrátím, již se beru.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 17, 1, 'Dýchání mé ruší se, dnové moji hynou, hrobu blízký jsem.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 17, 2, 'Jistě posměvači jsou u mne, a pro jejich mne kormoucení nepřichází ani sen na oči mé.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 17, 3, 'Postav mi, prosím, rukojmě za sebe; kdo jest ten, nechť mi na to ruky podá.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 17, 4, 'Nebo srdce jejich přikryl jsi, aby nerozuměli, a protož jich nepovýšíš.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 17, 5, 'Kdož pochlebuje bližním, oči synů jeho zhynou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 17, 6, 'Jistě vystavil mne za přísloví lidem, a za divadlo všechněm,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 17, 7, 'Tak že pro žalost pošly oči mé, a oudové moji všickni stínu jsou podobni.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 17, 8, 'Užasnouť se nad tím upřímí, a však nevinný proti pokrytci vždy se zsilovati bude.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 17, 9, 'Přídržeti se bude, pravím, spravedlivý cesty své, a ten, jenž jest čistých rukou, posilní se více.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 17, 10, 'Tolikéž i vy všickni obraťte se, a poďte, prosím; neboť nenacházím mezi vámi moudrého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 17, 11, 'Dnové moji pomíjejí, myšlení má mizejí, přemyšlování, pravím, srdce mého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 17, 12, 'Noc mi obracejí v den, a světla denního ukracují pro přítomnost temností.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 17, 13, 'Abych pak čeho i očekával, hrob bude dům můj, ve tmě usteli ložce své.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 17, 14, 'Jámu nazovu otcem svým, matkou pak a sestrou svou červy.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 17, 15, 'Kdež jest tedy očekávání mé? A kdo to, čím bych se troštoval, spatří?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 17, 16, 'Do skrýší hrobu sstoupí, poněvadž jest všechněm v prachu země odpočívati.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 1, 'Odpovídaje pak Bildad Suchský, řekl:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 2, 'Dokudž neučiníte konce řečem? Pomyslte na to, a potom mluviti budeme.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 3, 'Proč jsme počteni za hovada? Oškliví jsme jemu, jakž sami vidíte.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 4, 'Ó ty, jenž hubíš život svůj zůřením svým, zdaliž pro tebe opuštěna bude země, a odsedne skála z místa svého?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 5, 'Anobrž světlo bezbožných uhašeno bude, aniž se blyštěti bude jiskra ohně jejich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 6, 'Světlo se zatmí v stánku jeho, a lucerna jeho v něm zhasne.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 7, 'Ssouženi budou krokové síly jeho, a porazí jej rada jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 8, 'Nebo zapleten jest do síti nohami svými, a v zamotání chodí.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 9, 'Chytí ho za patu osídlo, a zmocní se ho násilník.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 10, 'Skrytať jest při zemi smečka jeho, a léčka jeho na stezce.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 11, 'Odevšad hrůzy jej děsiti budou a dotírati na nohy jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 12, 'Hladovitá bude síla jeho, a bída pohotově při boku jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 13, 'Zžíře žily kůže jeho, zžíře oudy jeho kníže smrti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 14, 'Uchváceno bude z stánku jeho doufání jeho, a to jej přivede k králi strachů.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 15, 'V stánku jeho hrůza bydleti bude, ač nebyl jeho; posypáno bude obydlí jeho sirou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 16, 'Od zpodku kořenové jeho uschnou, a svrchu osekány budou ratolesti jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 17, 'Památka jeho zahyne z země, aniž jméno jeho slýcháno bude na ulicích.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 18, 'Vyženou ho z světla do tmy, anobrž z okršlku zemského vypudí jej.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 19, 'Ne pozůstaví ani syna ani vnuka v lidu svém, ani jakého ostatku v příbytcích svých.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 20, 'Nade dnem jeho zděsí se potomci, a přítomní strachem podjati budou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 21, 'Takovýť jest zajisté způsob nešlechetného, a takový cíl toho, kterýž nezná Boha silného.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 1, 'Tedy odpověděv Job, řekl:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 2, 'Dokudž trápiti budete duši mou, a dotírati na mne řečmi svými?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 3, 'Již na desetkrát zhaněli jste mne, aniž se stydíte, že se zatvrzujete proti mně.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 4, 'Ale nechť jest tak, že jsem zbloudil, při mně zůstane blud můj.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 5, 'Jestliže se pak vždy proti mně siliti chcete, a obviňujíc mne, za pomoc sobě bráti proti mně potupu mou:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 6, 'Tedy vězte, že Bůh podvrátil mne, a sítí svou otáhl mne.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 7, 'Nebo aj, volám-li pro nátisk, nemám vyslyšení; křičím-li, není rozsouzení.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 8, 'Cestu mou zapletl tak, abych nikoli projíti nemohl, a stezky mé temnostmi zastřel.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 9, 'Slávu mou se mne strhl, a sňal korunu s hlavy mé.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 10, 'Zpodvracel mne všudy vůkol, abych zahynul, a vyvrátil jako strom naději mou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 11, 'Nadto zažžel proti mně prchlivost svou, a přičtl mne mezi nepřátely své.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 12, 'Pročež přitáhše houfové jeho, učinili sobě ke mně cestu, a vojensky se položili okolo stanu mého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 13, 'Bratří mé ode mne vzdálil, a známí moji všelijak se mne cizí.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 14, 'Opustili mne příbuzní moji, a známí moji zapomenuli se na mne.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 15, 'Podruhové domu mého a děvky mé za cizího mne mají, cizozemec jsem před očima jejich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 16, 'Na služebníka svého volám, ale neozývá se, i když ho ústy svými pěkně prosím.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 17, 'Dýchání mého štítí se manželka má, ačkoli pokorně jí prosím, pro dítky života mého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 18, 'Nadto i ti nejšpatnější pohrdají mnou; i když povstanu, utrhají mi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 19, 'V ošklivost mne sobě vzali všickni rádcové moji, a ti, kteréž miluji, obrátili se proti mně.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 20, 'K kůži mé jako k masu mému přilnuly kosti mé, kůže při zubích mých toliko v cele zůstala.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 21, 'Slitujte se nade mnou, slitujte se nade mnou, vy přátelé moji; nebo ruka Boží se mne dotkla.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 22, 'Proč mi se protivíte tak jako Bůh silný, a masem mým nemůžte se nasytiti?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 23, 'Ó kdyby nyní sepsány byly řeči mé, ó kdyby v knihu vepsány byly,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 24, 'Anobrž rafijí železnou a olovem na věčnost na skále aby vyryty byly.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 25, 'Ačkoli já vím, že vykupitel můj živ jest, a že v den nejposlednější nad prachem se postaví.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 26, 'A ač by kůži mou i tělo červi zvrtali, však vždy v těle svém uzřím Boha.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 27, 'Kteréhož já uzřím sobě, a oči mé spatří jej, a ne jiný, jakkoli zhynula ledví má u vnitřnosti mé.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 28, 'Ješto byste říci měli: I pročež ho trápíme? poněvadž základ dobré pře při mně se nalézá.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 29, 'Bojte se meče, nebo pomsta za nepravosti jest meč, a vězte, žeť bude soud.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 1, 'Odpovídaje pak Zofar Naamatský, řekl:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 2, 'Z příčiny té myšlení má k odpovídání tobě nutí mne, a to abych rychle učinil,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 3, 'Že kárání k zahanbení svému slyším, pročež duch můj osvícený nutí mne, aťbych odpovídal.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 4, 'Zdaž nevíš o tom, že od věků, a jakž postavil Bůh člověka na zemi,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 5, 'Plésání bezbožných krátké jest, a veselí pokrytce jen na chvílku?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 6, 'Byť pak vstoupila až k nebi pýcha jeho, a hlava jeho oblaku by se dotkla,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 7, 'Však jako lejno jeho na věky zahyne. Ti, kteříž jej vídali, řeknou: Kam se poděl?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 8, 'Jako sen pomine, aniž ho naleznou; nebo uteče jako vidění noční.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 9, 'Oko, kteréž ho vídalo, již ho nikdy neuzří, aniž více patřiti bude na něj místo jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 10, 'Synové jeho budou přízně u nuzných hledati, a ruce jeho musejí zase vraceti loupež svou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 11, 'Kosti jeho naplněny jsou hříchy mladosti jeho, a s ním v prachu lehnou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 12, 'A ačkoli zlost sladne v ústech jeho, a chová ji pod jazykem svým;');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 13, 'Kochá se v ní, a nepouští jí, ale zdržuje ji u prostřed dásní svých:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 14, 'Však pokrm ten ve střevách jeho promění se; bude jako žluč hadů nejlítějších u vnitřnostech jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 15, 'Zboží nahltané vyvrátí, z břicha jeho Bůh silný je vyžene.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 16, 'Jed hadů lítých ssáti bude, zabije ho jazyk ještěrčí.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 17, 'Neuzří pramenů potoků a řek medu a másla.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 18, 'Navrátí úsilé cizí, a nezažive ho, vedlé nátisku svého rozličného; nebude na ně vesel.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 19, 'Nebo utiskal a opouštěl nuzné, dům zloupil a nestavěl ho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 20, 'Pročež nesezná nic pokojného v životě svém, aniž které nejrozkošnější své věci bude moci zachovati.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 21, 'Nic mu nepozůstane z pokrmu jeho, tak že nebude míti, čím by se troštoval.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 22, 'Byť pak i dovršena byla hojnost jeho, ssoužení míti bude; každá ruka trapiče oboří se na něj.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 23, 'By měl čím naplniti břicho své, dopustí na něj Bůh prchlivost hněvu svého, kterouž na něj dštíti bude i na pokrm jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 24, 'Když utíkati bude před zbrojí železnou, prostřelí ho lučiště ocelivé.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 25, 'Střela vyňata bude z toulu a vystřelena, nadto meč pronikne žluč jeho; a když odcházeti bude, přikvačí jej hrůzy.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 26, 'Všeliká neštěstí jsou polečena v skrýších jeho, zžíře jej oheň nerozdmýchaný, zle se povede i pozůstalému v stanu jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 27, 'Odkryjí nebesa nepravost jeho, a země povstane proti němu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 28, 'Rozptýlena bude úroda domu jeho, rozplyne se v den hněvu jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 29, 'Tenť jest podíl člověka bezbožného od Boha, to, pravím, dědictví vyrčené jemu od Boha silného.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 1, 'A odpovídaje Job, řekl:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 2, 'Poslouchejte pilně řeči mé, a bude mi to za potěšení od vás.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 3, 'Postrpte mne, abych i já mluvil, a když odmluvím, posmívejž se.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 4, 'Zdaliž já před člověkem naříkám? A poněvadž jest proč, jakž nemá býti ssoužen duch můj?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 5, 'Pohleďte na mne, a užasněte se, a položte prst na ústa.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 6, 'Ano já sám, když rozvažuji své bídy, tedy se děsím, a spopadá tělo mé hrůza.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 7, 'Proč bezbožní živi jsou, k věku starému přicházejí, též i bohatnou?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 8, 'Símě jejich stálé jest před oblíčejem jejich s nimi, a rodina jejich před očima jejich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 9, 'Domové jejich bezpečni jsou před strachem, aniž metla Boží na nich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 10, 'Býk jejich připouštín bývá, ale ne na prázdno; kráva jejich rodí, a nepotracuje plodu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 11, 'Vypouštějí jako stádo maličké své, a synové jejich poskakují.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 12, 'Povyšují hlasu při bubnu a harfě, a veselí se k zvuku muziky.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 13, 'Tráví v štěstí dny své, a v okamžení do hrobu sstupují.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 14, 'Kteříž říkají Bohu silnému: Odejdi od nás, nebo známosti cest tvých neoblibujeme.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 15, 'Kdo jest Všemohoucí, abychom sloužili jemu? A jaký toho zisk, že bychom se modlili jemu?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 16, 'Ale pohleď, že není v moci jejich štěstí jejich, pročež rada bezbožných vzdálena jest ode mne.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 17, 'Často-liž svíce bezbožných hasne? Přichází-liž na ně bída jejich? Poděluje-liž je bolestmi Bůh v hněvě svém?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 18, 'Bývají-liž jako plevy před větrem, a jako drtiny, kteréž zachvacuje vicher?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 19, 'Odkládá-liž Bůh synům bezbožníka nepravost jeho? Odplacuje-liž jemu tak, aby to znáti mohl,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 20, 'A aby viděly oči jeho neštěstí jeho, a prchlivost Všemohoucího že by pil?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 21, 'O dům pak jeho po něm jaká jest péče jeho, když počet měsíců jeho bude umenšen?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 22, 'Zdali Boha silného kdo učiti bude umění, kterýž sám vysokosti soudí?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 23, 'Tento umírá v síle dokonalosti své, všelijak bezpečný a pokojný.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 24, 'Prsy jeho plné jsou mléka, a mozk kostí jeho svlažován bývá.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 25, 'Jiný pak umírá v hořkosti ducha, kterýž nikdy nejídal s potěšením.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 26, 'Jednostejně v prachu lehnou, a červy se rozlezou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 27, 'Aj, známť myšlení vaše, a chytrosti, kteréž proti mně neprávě vymýšlíte.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 28, 'Nebo pravíte: Kde jest dům urozeného? A kde stánek příbytků bezbožných?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 29, 'Což jste se netázali jdoucích cestou? Zkušení-liž aspoň jejich nepovolíte,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 30, 'Že v den neštěstí ochranu mívá bezbožný, v den, pravím, rozhněvání přistřín bývá?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 31, 'Kdo jemu oznámí zjevně cestu jeho? Aneb za to, co činil, kdo jemu odplatí?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 32, 'A však i on k hrobu vyprovozen bude, a tam zůstane.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 33, 'Sladnou jemu hrudy údolí, nadto za sebou všecky lidi táhne, těch pak, kteříž ho předešli, není počtu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 34, 'Hle, jak vy mne marně troštujete, nebo v odpovědech vašich ne zůstává než faleš.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 1, 'A odpovídaje Elifaz Temanský, řekl:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 2, 'Zdaliž Bohu silnému co prospěšný býti může člověk, když sobě nejmoudřeji počíná?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 3, 'Zdaliž se kochá Všemohoucí v tom, že ty se ospravedlňuješ? Aneb má-liž zisk, když bys dokonalé ukázal býti cesty své?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 4, 'Zdali, že by se tebe bál, tresce tě, mstě nad tebou?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 5, 'Zdali zlost tvá není mnohá? Anobrž není konce nepravostem tvým.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 6, 'Nebo jsi brával základ od bratří svých bez příčiny, a roucha z nahých jsi svláčel.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 7, 'Vody ustalému jsi nepodal, a hladovitému zbraňovals chleba.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 8, 'Ale muži boháči přál jsi země, tak aby ten, jehož osoba vzácná, v ní seděl.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 9, 'Vdovy pak pouštěl jsi prázdné, ačkoli ramena sirotků potřína byla.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 10, 'A protož obkličuji tě osídla, a děsí tě strach nenadálý,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 11, 'Aneb tma, abys neviděl, anobrž rozvodnění přikrývá tě.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 12, 'Říkáš: Zdaž Bůh není na výsosti nebeské? Ano shlédni vrch hvězd, jak jsou vysoké.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 13, 'Protož pravíš: Jak by věděl Bůh silný? Skrze mrákotu-liž by soudil?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 14, 'Oblakové jsou skrýše jeho, tak že nevidí; nebo okršlek nebeský obchází.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 15, 'Šetříš-liž stezky věku předešlého, kterouž kráčeli lidé marní?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 16, 'Kteříž vypléněni jsou před časem, potok vylit jest na základ jejich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 17, 'Kteříž říkali Bohu silnému: Odejdi od nás. Což by tedy jim učiniti měl Všemohoucí?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 18, 'On zajisté domy jejich naplnil dobrými věcmi, (ale rada bezbožných vzdálena jest ode mne).');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 19, 'Což vidouce spravedliví, veselí se, a nevinný posmívá se jim,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 20, 'Zvlášť když není vypléněno jmění naše, ostatky pak jejich sežral oheň.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 21, 'Přivykejž medle s ním choditi, a pokojněji se míti, skrze to přijde tobě všecko dobré.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 22, 'Přijmi, prosím, z úst jeho zákon, a slož řeči jeho v srdci svém.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 23, 'Navrátíš-li se k Všemohoucímu, vzdělán budeš, a vzdálíš-li nepravost od stanů svých,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 24, 'Tedy nakladeš na zemi zlata, a místo kamení potočního zlata z Ofir.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 25, 'Nebo bude Všemohoucí nejčistším zlatem tvým, a stříbrem i silou tvou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 26, 'A tehdáž v Všemohoucím kochati se budeš, a pozdvihna k Bohu tváři své,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 27, 'Pokorně modliti se budeš jemu, a vyslyší tě; pročež sliby své plniti budeš.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 28, 'Nebo cožkoli začneš, budeť se dařiti, anobrž na cestách tvých svítiti bude světlo.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 29, 'Když jiní sníženi budou, tedy díš: Jáť jsem povýšen. Nebo toho, kdož jest očí ponížených, Bůh spasena učiní.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 30, 'Vysvobodí i toho, kterýž není bez viny, vysvobodí, pravím, čistotou rukou tvých.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 23, 1, 'Tedy odpověděl Job a řekl:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 23, 2, 'Což vždy předce naříkání mé za zpouru jmíno bude, ješto bída má těžší jest nežli lkání mé?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 23, 3, 'Ó bych věděl, kde ho najíti, šel bych až k trůnu jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 23, 4, 'Pořádně bych před ním vedl při, a ústa svá naplnil bych důvody.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 23, 5, 'Zvěděl bych, jakými slovy by mně odpověděl, a porozuměl bych, co by mi řekl.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 23, 6, 'Zdaliž by podlé veliké síly své rozepři vedl se mnou? Nikoli, nýbrž on sám dal by mi sílu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 23, 7, 'Tuť by upřímý hádati se mohl s ním, a byl bych osvobozen všelijak od soudce svého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 23, 8, 'Ale aj, půjdu-li upřímo dále, tam ho není; pakli nazpět, nepostihnu ho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 23, 9, 'By i čím zaměstknán byl na levo, předce ho nespatřím; zastře-li se na pravo, ovšem ho neuzřím.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 23, 10, 'Nebo on zná cestu, kteráž jest při mně; bude-li mne zkušovati, jako zlato se ukáži.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 23, 11, 'Šlepějí zajisté jeho přídržela se noha má, cesty jeho šetřil jsem, abych se s ní neuchyloval.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 23, 12, 'Aniž od přikázaní rtů jeho uchýlil jsem se, nýbrž ustaviv se na tom, schované jsem měl řeči úst jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 23, 13, 'On pak jestliže při čem stojí, kdo jej odvrátí? Ano duše jeho čehož jen žádá, toho hned dovodí.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 23, 14, 'A vykoná uložení své o mně; nebo takových příkladů mnoho jest při něm.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 23, 15, 'Pročež před tváří jeho děsím se; když to rozvažuji, lekám se ho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 23, 16, 'Bůh zajisté zemdlil srdce mé, a Všemohoucí předěsil mne,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 23, 17, 'Tak že sotva jsem nezahynul v těch temnostech; nebo před tváří mou ne zakryl mrákoty.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 1, 'Proč by od Všemohoucího neměli býti skryti časové, a ti, kteříž jej znají, neměli neviděti dnů jeho?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 2, 'Bezbožníť nyní mezníky přenášejí, a stádo, kteréž mocí zajali, pasou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 3, 'Osla sirotků zajímají, v zástavě berou vola od vdovy.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 4, 'Strkají nuznými s cesty, musejí se vůbec skrývati chudí na světě.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 5, 'Aj, oni jako divocí oslové na poušti, vycházejí jako ku práci své, ráno přivstávajíce k loupeži; poušť jest chléb jejich i dětí jejich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 6, 'Na cizím poli žnou, a z vinic bezbožníci sbírají.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 7, 'Nahé přivodí k tomu, aby nocovati musili bez roucha, nemajíce se čím přiodíti na zimě.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 8, 'A přívalem v horách moknouce, nemajíce obydlí, k skále se přivinouti musejí.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 9, 'Loupí sirotky, kteříž jsou při prsích, a od chudého základ berou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 10, 'Nahého opouštějí, že musí choditi bez oděvu, a ti, kteříž snášejí snopy, v hladu zůstávati.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 11, 'Ti, jenž mezi zdmi jejich olej vytlačují, a presy tlačí, žíznějí.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 12, 'Lidé v městech lkají, a duše zraněných volají, Bůh pak přítrže tomu nečiní.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 13, 'Oniť jsou ti, kteříž odporují světlu, a neznají cest jeho, aniž chodí po stezkách jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 14, 'Na úsvitě povstávaje vražedlník, morduje chudého a nuzného, a v noci jest jako zloděj.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 15, 'Tolikéž oko cizoložníka šetří soumraku, říkaje: Nespatříť mne žádný, a tvář zakrývá.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 16, 'Podkopávají potmě i domy, kteréž sobě ve dne znamenali; nebo nenávidí světla.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 17, 'Ale hned v jitře přichází na ně stín smrti; když jeden druhého poznati může, strachu stínu smrti okoušejí.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 18, 'Lehcí jsou na svrchku vody, zlořečené jest jmění jejich na zemi, aniž odcházejí cestou svobodnou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 19, 'Jako sucho a horko uchvacuje vody sněžné, tak hrob ty, jenž hřešili.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 20, 'Zapomíná se na něj život matky, sladne červům, nebývá více připomínán, a tak polámána bývá nepravost jako strom.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 21, 'Připojuje mu neplodnou, kteráž nerodí, a vdově dobře nečiní.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 22, 'Zachvacuje silné mocí svou; ostojí-li kdo z nich, bojí se o život svůj.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 23, 'Dává jemu, na čemž by bezpečně spolehnouti mohl, však oči jeho šetří cest jejich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 24, 'Bývají zvýšeni poněkud, ale hned jich není; tak jako jiní všickni sníženi, vypléněni, a jako vrškové klasů stínáni bývají.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 25, 'Zdaliž není tak? Kdo na mne dokáže klamu, a v nic obrátí řeč mou?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 25, 1, 'Tedy odpovídaje Bildad Suchský, řekl:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 25, 2, 'Panování a hrůza Boží působí pokoj na výsostech jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 25, 3, 'Zdaliž jest počet vojskům jeho? A nad kým nevzchází světlo jeho?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 25, 4, 'Jakž by tedy spravedliv býti mohl bídný člověk před Bohem silným, aneb jak čist býti narozený z ženy?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 25, 5, 'Hle, ani měsíc nesvítil by, ani hvězdy nebyly by čisté před očima jeho,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 25, 6, 'Nadto pak smrtelný člověk, jsa jako červ, a syn člověka, jako hmyz.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 26, 1, 'A odpovídaje Job, řekl:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 26, 2, 'Komu jsi napomohl? Tomu-li, kterýž nemá síly? Toho-lis retoval, kterýž jest bez moci?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 26, 3, 'Komu jsi rady udělil? Nemoudrému-li? Hned jsi základu dostatečně poučil?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 26, 4, 'Komužs ty řeči zvěstoval? A čí duch vyšel z tebe?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 26, 5, 'Však i mrtvé věci pod vodami a obyvateli jejich sformovány bývají.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 26, 6, 'Odkryta jest propast před ním, i zahynutí není zakryto.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 26, 7, 'Ontě roztáhl půlnoční stranu nad prázdnem, zavěsil zemi na ničemž.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 26, 8, 'Zavazuje vody v oblacích svých, aniž se trhá oblak pod nimi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 26, 9, 'On sám zdržuje stále trůn svůj, a roztahuje na něm oblaky své.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 26, 10, 'Cíl vyměřil rozlévání se vodám, až do skonání světla a tmy.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 26, 11, 'Sloupové nebeští třesou se a pohybují od žehrání jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 26, 12, 'Mocí svou rozdělil moře, a rozumností svou dutí jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 26, 13, 'Duchem svým nebesa ozdobil, a ruka jeho sformovala hada dlouhého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 26, 14, 'Aj, toť jsou jen částky cest jeho, a jak nestižitelné jest i to maličko, což jsme slyšeli o něm. Hřímání pak moci jeho kdo srozumí?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 1, 'Potom dále Job vedl řeč svou a řekl:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 2, 'Živť jest Bůh silný, kterýž zavrhl při mou, a Všemohoucí, kterýž hořkostí naplnil duši mou,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 3, 'Že nikoli, dokudž duše má ve mně bude a duch Boží v chřípích mých,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 4, 'Nebudou mluviti rtové moji nepravosti, a jazyk můj vynášeti lsti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 5, 'Odstup ode mne, abych vás za spravedlivé vysvědčil; dokudž dýchati budu, neodložím upřímosti své od sebe.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 6, 'Spravedlnosti své držím se, aniž se jí pustím; nezahanbíť mne srdce mé nikdy.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 7, 'Bude jako bezbožník nepřítel můj, a povstávající proti mně jako nešlechetník.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 8, 'Nebo jaká jest naděje pokrytce, by pak lakoměl, když Bůh vytrhne duši jeho?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 9, 'Zdaliž volání jeho vyslyší Bůh silný, když na něj přijde ssoužení?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 10, 'Zdaliž v Všemohoucím kochati se bude? Bude-liž vzývati Boha každého času?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 11, 'Ale já učím vás, v kázni Boha silného jsa, a jak se mám k Všemohoucímu, netajím.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 12, 'Aj, vy všickni to vidíte, pročež vždy tedy takovou marnost vynášíte?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 13, 'Ten má podíl člověk bezbožný u Boha silného, a to dědictví ukrutníci od Všemohoucího přijímají:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 14, 'Rozmnoží-li se synové jeho, rozmnoží se pod meč, a rodina jeho nenasytí se chlebem.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 15, 'Pozůstalí po něm v smrti pohřbeni budou, a vdovy jeho nebudou ho plakati.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 16, 'Nashromáždí-li jako prachu stříbra, a jako bláta najedná-li šatů:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 17, 'Co najedná, to spravedlivý obleče, a stříbro nevinný rozdělí.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 18, 'Vystaví-li jako Arktura dům svůj, bude však jako bouda, kterouž udělal strážný.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 19, 'Bohatý když umře, nebude pochován; pohledí někdo, anť ho není.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 20, 'Postihnou jej hrůzy jako vody, v noci kradmo zachvátí ho vicher.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 21, 'Pochytí jej východní vítr, a odejde, nebo vichřicí uchvátí jej z místa jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 22, 'Takové věci na něj dopustí Bůh bez lítosti, ačkoli před rukou jeho prudce utíkati bude.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 23, 'Tleskne nad ním každý rukama svýma, a ckáti bude z místa svého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 1, 'Máť zajisté stříbro prameny své, a zlato místo k přehánění.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 2, 'Železo z země vzato bývá, a kámen rozpuštěný dává měď.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 3, 'Cíl ukládá temnostem, a všelikou dokonalost člověk vystihá, kámen mrákoty a stínu smrti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 4, 'Protrhuje se řeka na obyvatele, tak že ji nemůže žádný přebřesti, a svozována bývá uměním smrtelného člověka, i odchází.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 5, 'Z země vychází chléb, ačkoli pod ní jest něco rozdílného, podobného k ohni.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 6, 'V některé zemi jest kamení zafirové a prach zlatý,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 7, 'K čemuž stezky nezná žádný pták, aniž ji spatřilo oko luňáka,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 8, 'Kteréž nešlapala mladá zvěř, aniž šel po ní lev.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 9, 'K škřemeni vztahuje ruku svou, a z kořene převrací hory.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 10, 'Z skálí vyvodí potůčky, a všecko, což jest drahého, spatřuje oko jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 11, 'Vylévati se řekám zbraňuje, a tak cožkoli skrytého jest, na světlo vynáší.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 12, 'Ale moudrost kde nalezena bývá? A kde jest místo rozumnosti?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 13, 'Neví smrtelný člověk ceny její, aniž bývá nalezena v zemi živých.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 14, 'Propast praví: Není ve mně, moře také dí: Není u mne.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 15, 'Nedává se zlata čistého za ni, aniž odváženo bývá stříbro za směnu její.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 16, 'Nemůže býti ceněna za zlato z Ofir, ani za onychin drahý a zafir.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 17, 'Nevrovná se jí zlato ani drahý kámen, aniž směněna býti může za nádobu z ryzího zlata.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 18, 'Korálů pak a perel se nepřipomíná; nebo nabytí moudrosti dražší jest nad klénoty.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 19, 'Není jí rovný v ceně smaragd z Mouřenínské země, aniž za čisté zlato může ceněna býti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 20, 'Odkudž tedy moudrost přichází? A kde jest místo rozumnosti?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 21, 'Poněvadž skryta jest před očima všelikého živého, i před nebeským ptactvem ukryta jest.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 22, 'Zahynutí i smrt praví: Ušima svýma slyšely jsme pověst o ní.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 23, 'Sám Bůh rozumí cestě její, a on ví místo její.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 24, 'Nebo on končiny země spatřuje, a všecko, což jest pod nebem, vidí,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 25, 'Tak že větru váhu dává, a vody v míru odvažuje.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 26, 'On též vyměřuje dešti právo, i cestu blýskání hromů.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 27, 'Hned tehdáž viděl ji, a rozhlásil ji, připravil ji, a vystihl ji.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 28, 'Člověku pak řekl: Aj, bázeň Páně jest moudrost, a odstoupiti od zlého rozumnost.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 1, 'Ještě dále Job vedl řeč svou, a řekl:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 2, 'Ó bych byl jako za časů předešlých, za dnů, v nichž mne Bůh zachovával,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 3, 'Dokudž svítil svící svou nad hlavou mou, při jehož světle chodíval jsem v temnostech,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 4, 'Tak jako jsem byl za dnů mladosti své, dokudž přívětivost Boží byla v stanu mém,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 5, 'Dokudž ještě Všemohoucí byl se mnou, a všudy vůkol mne dítky mé,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 6, 'Když šlepěje mé máslem oplývaly, a skála vylévala mi prameny oleje,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 7, 'Když jsem vycházel k bráně skrze město, a na ulici strojíval sobě stolici svou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 8, 'Jakž mne spatřovali mládenci, skrývali se, starci pak povstávali a stáli.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 9, 'Knížata choulili se v řečech, anobrž ruku kladli na ústa svá.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 10, 'Hlas vývod se tratil, a jazyk jejich lnul k dásním jejich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 11, 'Nebo ucho slyše, blahoslavilo mne, a oko vida, posvědčovalo mi,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 12, 'Že vysvobozuji chudého volajícího, a sirotka, i toho, kterýž nemá spomocníka.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 13, 'Požehnání hynoucího přicházelo na mne, a srdce vdovy k plésání jsem vzbuzoval.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 14, 'V spravedlnost jsem se obláčel, a ona ozdobovala mne; jako plášť a koruna byl soud můj.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 15, 'Místo očí býval jsem slepému, a místo noh kulhavému.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 16, 'Byl jsem otcem nuzných, a na při, jíž jsem nebyl povědom, vyptával jsem se.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 17, 'A tak vylamoval jsem třenovní zuby nešlechetníka, a z zubů jeho vyrážel jsem loupež.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 18, 'A protož jsem říkal: V hnízdě svém umru, a jako písek rozmnožím dny.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 19, 'Kořen můj rozloží se při vodách, a rosa nocovati bude na ratolestech mých.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 20, 'Sláva má mladnouti bude při mně, a lučiště mé v ruce mé obnovovati se.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 21, 'Poslouchajíce, čekali na mne, a přestávali na radě mé.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 22, 'Po slovu mém nic neměnili, tak na ně dštila řeč má.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 23, 'Nebo očekávali mne jako deště, a ústa svá otvírali jako k přívalu žádostivému.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 24, 'Žertoval-li jsem s nimi, nevěřili; pročež u vážnosti mne míti neoblevovali.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 25, 'Přišel-li jsem kdy k nim, sedal jsem na předním místě, a tak bydlil jsem jako král v vojště, když smutných potěšuje.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 1, 'Nyní pak posmívají se mi mladší mne, jejichž bych otců nechtěl byl postaviti se psy stáda svého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 2, 'Ač síla rukou jejich k čemu by mi byla? Zmařena jest při nich starost jejich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 3, 'Nebo chudobou a hladem znuzeni, utíkali na planá, tmavá, soukromná a pustá místa.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 4, 'Kteříž trhali zeliny po chrastinách, ano i koření, a jalovec za pokrm byl jim.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 5, 'Z prostřed lidí vyháníni byli; povolávali za nimi, jako za zlodějem,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 6, 'Tak že musili bydliti v výmolích potoků, v děrách země a skálí.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 7, 'V chrastinách řvali, pod trní se shromažďovali,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 8, 'Lidé nejnešlechetnější, nýbrž lidé bez poctivosti, menší váhy i než ta země.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 9, 'Nyní, pravím, jsem jejich písničkou, jsa jim učiněn za přísloví.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 10, 'V ošklivosti mne mají, vzdalují se mne, a na tvář mou nestydí se plvati.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 11, 'Nebo Bůh mou vážnost odjal, a ssoužil mne; pročež uzdu před přítomností mou svrhli.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 12, 'Po pravici mládež povstává, nohy mi podrážejí, tak že šlapáním protřeli ke mně stezky nešlechetnosti své.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 13, 'Mou pak stezku zkazili, k bídě mé přidali, ač jim to nic nepomůže.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 14, 'Jako širokou mezerou vskakují, a k vyplénění mému valí se.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 15, 'Obrátily se na mne hrůzy, stihají jako vítr ochotnost mou, nebo jako oblak pomíjí zdraví mé.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 16, 'A již ve mně rozlila se duše má, pochytili mne dnové trápení mého,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 17, 'Kteréž v noci vrtá kosti mé ve mně; pročež ani nervové moji neodpočívají.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 18, 'Oděv můj mění se pro násilnou moc bolesti, kteráž mne tak jako obojek sukně mé svírá.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 19, 'Uvrhl mne do bláta, tak že jsem již podobný prachu a popelu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 20, 'Volám k tobě, ó Bože, a neslyšíš mne; postavuji se, ale nehledíš na mne.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 21, 'Obrátils mi se v ukrutného nepřítele, silou ruky své mi odporuješ.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 22, 'Vznášíš mne u vítr, sázíš mne na něj, a k rozplynutí mi přivodíš zdravý soud.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 23, 'Nebo vím, že mne k smrti odkážeš, a do domu, do něhož se shromažďuje všeliký živý.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 24, 'Jistě žeť nevztáhne Bůh do hrobu ruky, by pak, když je stírá, i volali.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 25, 'Zdaliž jsem neplakal nad tím, kdož okoušel zlých dnů? Duše má kormoutila se nad nuzným.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 26, 'Když jsem dobrého čekal, přišlo mi zlé; nadál jsem se světla, ale přišla mrákota.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 27, 'Vnitřností mé zevřely, tak že se ještě neupokojily; předstihli mne dnové trápení.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 28, 'Chodím osmahlý, ne od slunce, povstávaje, i mezi mnohými křičím.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 29, 'Bratrem učiněn jsem draků, a tovaryšem mladých pstrosů.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 30, 'Kůže má zčernala na mně, a kosti mé vyprahly od horkosti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 31, 'A protož v kvílení obrátila se harfa má, a píšťalka má v hlas plačících.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 1, 'Smlouvu jsem učinil s očima svýma, a proč bych hleděl na pannu?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 2, 'Nebo jaký jest díl od Boha s hůry, aneb dědictví od Všemohoucího s výsosti?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 3, 'Zdaliž zahynutí nešlechetnému a pomsta zázračná činitelům nepravosti připravena není?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 4, 'Zdaliž on nevidí cest mých, a všech kroků mých nepočítá?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 5, 'Obíral-li jsem se s neupřímostí, a chvátala-li ke lsti noha má:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 6, 'Nechť mne zváží na váze spravedlnosti, a přezví Bůh upřímost mou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 7, 'Uchýlil-li se krok můj s cesty, a za očima mýma odešlo-li srdce mé, a rukou mých chytila-li se jaká poškvrna:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 8, 'Tedy co naseji, nechť jiný sní, a výstřelkové moji ať jsou vykořeněni.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 9, 'Jestliže se dalo přivábiti srdce mé k ženě, a u dveří bližního svého činil-li jsem úklady:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 10, 'Nechť mele jinému žena má, a nad ní ať se schylují jiní.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 11, 'Neboť jest to nešlechetnost, a nepravost odsudku hodná.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 12, 'Oheň ten zajisté by až do zahynutí žral, a všecku úrodu mou vykořenil.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 13, 'Nechtěl-li jsem státi k soudu s služebníkem svým aneb děvkou svou v rozepři jejich se mnou?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 14, 'Nebo co bych činil, kdyby povstal Bůh silný? A kdyby vyhledával, co bych odpověděl jemu?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 15, 'Zdali ten, kterýž mne v břiše učinil, neučinil i jeho? A ne sformoval nás hned v životě jeden a týž?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 16, 'Odepřel-li jsem žádosti nuzných, a oči vdovy jestliže jsem kormoutil?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 17, 'A jedl-li jsem skyvu svou sám, a nejedl-li i sirotek z ní?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 18, 'Poněvadž od mladosti mé rostl se mnou jako u otce, a od života matky své býval jsem vdově za vůdce.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 19, 'Díval-li jsem se na koho, že by hynul, nemaje šatů, a nuzný že by neměl oděvu?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 20, 'Nedobrořečila-li mi bedra jeho, že rounem beranů mých se zahřel?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 21, 'Opřáhl-li jsem na sirotka rukou svou, když jsem v bráně viděl pomoc svou:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 22, 'Lopatka má od svých plecí nechť odpadne, a ruka má z kloubu svého ať se vylomí.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 23, 'Nebo jsem se bál, aby mne Bůh nesetřel, jehož bych velebnosti nikoli neznikl.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 24, 'Skládal-li jsem v zlatě naději svou, aneb hrudě zlata říkal-li jsem: Doufání mé?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 25, 'Veselil-li jsem se z toho, že bylo rozmnoženo zboží mé, a že ho množství nabyla ruka má?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 26, 'Hleděl-li jsem na světlost slunce svítícího, a na měsíc spanile chodící,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 27, 'Tak že by se tajně dalo svésti srdce mé, a že by líbala ústa má ruku mou?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 28, 'I toť by byla nepravost odsudku hodná; neboť bych tím zapíral Boha silného nejvyššího.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 29, 'Radoval-li jsem se z neštěstí toho, kterýž mne nenáviděl, a plésal-li jsem, když se mu zle vedlo?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 30, 'Nedopustilť jsem zajisté hřešiti ani ústům svým, abych zlořečení žádal duši jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 31, 'Jestliže neříkala čeládka má: Ó by nám dal někdo masa toho; nemůžeme se ani najísti?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 32, 'Nebo vně nenocoval host, dvéře své pocestnému otvíral jsem.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 33, 'Přikrýval-li jsem jako jiní lidé přestoupení svá, skrývaje v skrýši své nepravost svou?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 34, 'A ač bych byl mohl škoditi množství velikému, ale pohanění rodů děsilo mne; protož jsem mlčel, nevycházeje ani ze dveří.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 35, 'Ó bych měl toho, kterýž by mne vyslyšel. Ale aj, totoť jest znamení mé: Všemohoucí sám bude odpovídati za mne, a kniha, kterouž sepsal odpůrce můj.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 36, 'Víť Bůh, nenosil-li bych ji na rameni svém, neotočil-li bych ji sobě místo koruny.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 37, 'Počet kroků svých oznámil bych jemu, jako kníže přiblížil bych se k němu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 38, 'Jestliže proti mně země má volala, tolikéž i záhonové její plakali,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 39, 'Jídal-li jsem úrody její bez peněz, a duši držitelů jejich přivodil-li jsem k vzdychání:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 40, 'Místo pšenice nechť vzejde trní, a místo ječmene koukol. Skonávají se slova Jobova.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 1, 'A když přestali ti tři muži odpovídati Jobovi, proto že se spravedlivý sobě zdál,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 2, 'Tedy rozpáliv se hněvem Elihu, syn Barachele Buzitského z rodu Syrského, na Joba, rozhněval se, proto že spravedlivější pravil býti duši svou nad Boha.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 3, 'Ano i na ty tři z přátel jeho roznítil se hněv jeho, proto že nenalézajíce odpovědi, však potupovali Joba.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 4, 'Nebo Elihu očekával na Joba a na ně s řečí, proto že starší byli věkem než on.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 5, 'Ale vida Elihu, že nebylo žádné odpovědi v ústech těch tří mužů, zažhl se v hněvě svém.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 6, 'I mluvil Elihu syn Barachele Buzitského, řka: Já jsem nejmladší, vy pak jste starci, pročež ostýchaje se, nesměl jsem vám oznámiti zdání svého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 7, 'Myslil jsem: Staří mluviti budou, a mnoho let mající v známost uvedou moudrost.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 8, 'Ale vidím, že Duch Boží v člověku a nadšení Všemohoucího činí lidi rozumné.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 9, 'Slavní ne vždycky jsou moudří, aniž starci vždycky rozumějí soudu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 10, 'A protož pravím: Poslouchejte mne, oznámím i já také zdání své.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 11, 'Aj, očekával jsem na slova vaše, poslouchal jsem důvodů vašich dotud, dokudž jste vyhledávali řeči,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 12, 'A bedlivě vás soudě, spatřil jsem, že žádného není, kdo by Joba přemohl, není z vás žádného, ješto by odpovídal řečem jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 13, 'Ale díte snad: Nalezli jsme moudrost, Bůh silný stihá jej, ne člověk.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 14, 'Odpovím: Ač Job neobracel proti mně řeči, a však slovy vašimi nebudu jemu odpovídati.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 15, 'Bojí se, neodpovídají více, zavrhli od sebe slova.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 16, 'Čekal jsem zajisté, však poněvadž nemluví, ale mlčí, a neodpovídají více,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 17, 'Odpovím i já také za sebe, oznámím zdání své i já.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 18, 'Nebo pln jsem řečí, těsno ve mně duchu života mého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 19, 'Aj, břicho mé jest jako mest nemající průduchu, jako sudové noví rozpuklo by se.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 20, 'Mluviti budu, a vydchnu sobě, otevru rty své, a odpovídati budu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 21, 'Nebuduť pak šetřiti osoby žádného, a k člověku bez proměňování jména mluviti budu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 22, 'Nebo neumím jmen proměňovati, nebo tudíž by mne zachvátil stvořitel můj.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 1, 'Slyšiž tedy, prosím, Jobe, řeči mé, a všech slov mých ušima svýma pozoruj.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 2, 'Aj, jižť otvírám ústa svá, mluví jazyk můj v ústech mých.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 3, 'Upřímost srdce mého a umění vynesou rtové moji.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 4, 'Duch Boha silného učinil mne, a dchnutí Všemohoucího dalo mi život.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 5, 'Můžeš-li, odpovídej mi, připrav se proti mně, a postav se.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 6, 'Aj, já podlé žádosti tvé buduť místo Boha silného; z bláta sformován jsem i já.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 7, 'Pročež strach ze mne nepředěsí tě, a ruka má nebudeť k obtížení.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 8, 'Řekl jsi pak přede mnou, a hlas ten řečí tvých slyšel jsem:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 9, 'Čist jsem, bez přestoupení, nevinný jsem, a nepravosti při mně není.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 10, 'Aj, příčiny ku potření mne shledal Bůh, klade mne sobě za nepřítele,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 11, 'Svírá poutami nohy mé, střeže všech stezek mých.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 12, 'Aj, tím nejsi spravedliv, odpovídám tobě, nebo větší jest Bůh nežli člověk.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 13, 'Oč se s ním nesnadníš? Žeť všech svých věcí nezjevuje?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 14, 'Ano jednou mluví Bůh silný, i dvakrát, a nešetří toho člověk.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 15, 'Skrze sny u vidění nočním, když připadá hluboký sen na lidi ve spaní na ložci,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 16, 'Tehdáž odkrývá ucho lidem, a čemu je učí, to zpečeťuje,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 17, 'Aby odtrhl člověka od skutku zlého, a pýchu od muže vzdálil,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 18, 'A zachoval duši jeho od jámy, a život jeho aby netrefil na meč.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 19, 'Tresce i bolestí na lůži jeho, a všecky kosti jeho násilnou nemocí,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 20, 'Tak že sobě život jeho oškliví pokrm, a duše jeho krmi nejlahodnější.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 21, 'Hyne tělo jeho patrně, a vyhlédají kosti jeho, jichž prvé nebylo vídati.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 22, 'A tak bývá blízká hrobu duše jeho, a život jeho smrtelných ran.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 23, 'Však bude-li míti anděla vykladače jednoho z tisíce, kterýž by za člověka oznámil pokání jeho:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 24, 'Tedy smiluje se nad ním, a dí: Vyprosť jej, ať nesstoupí do porušení, oblíbilť jsem mzdu vyplacení.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 25, 'I odmladne tělo jeho nad dítěcí, a navrátí se ke dnům mladosti své.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 26, 'Kořiti se bude Bohu, a zamiluje jej, a patřiti bude na něj tváří ochotnou; nadto navrátí člověku spravedlnost jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 27, 'Kterýž hledě na lidi, řekne: Zhřešilť jsem byl, a to, což pravého bylo, převrátil jsem, ale nebylo mi to prospěšné.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 28, 'Bůh však vykoupil duši mou, aby nešla do jámy, a život můj, aby světlo spatřoval.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 29, 'Aj, všeckoť to dělá Bůh silný dvakrát i třikrát při člověku,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 30, 'Aby odvrátil duši jeho od jámy, a aby osvícen byl světlem živých.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 31, 'Pozoruj, Jobe, poslouchej mne, mlč, ať já mluvím.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 32, 'Jestliže máš slova, odpovídej mi, nebo bych chtěl ospravedlniti tebe.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 33, 'Pakli nic, ty mne poslouchej; mlč, a poučím tě moudrosti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 1, 'Ještě mluvil Elihu, a řekl:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 2, 'Poslouchejte, moudří, řečí mých, a rozumní, ušima pozorujte.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 3, 'Nebo ucho řečí zkušuje, tak jako dásně okoušejí pokrmu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 4, 'Soud sobě zvolme, a vyhledejme mezi sebou, co by bylo dobrého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 5, 'Nebo řekl Job: Spravedliv jsem, a Bůh silný zavrhl při mou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 6, 'Své-liž bych pře ukrývati měl? Přeplněna jest bolestí rána má bez provinění.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 7, 'Který muž jest podobný Jobovi, ješto by pil posměch jako vodu?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 8, 'A že by všel v tovaryšství s činiteli nepravosti, a chodil by s lidmi nešlechetnými?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 9, 'Nebo řekl: Neprospívá to člověku líbiti se Bohu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 10, 'A protož, muži rozumní, poslouchejte mne. Odstup od Boha silného nešlechetnost a od Všemohoucího nepravost.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 11, 'Nebo on podlé skutků člověka odplací, a podlé toho, jaká jest čí cesta, působí, aby to nalézal.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 12, 'A naprosto Bůh silný nečiní nic nešlechetně, a Všemohoucí nepřevrací soudu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 13, 'Kdo svěřil jemu zemi? A kdo zpořádal všecken okršlek?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 14, 'Kdyby se na něj obrátil, a ducha jeho i duši jeho k sobě vzal,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 15, 'Umřelo by všeliké tělo pojednou, a tak by člověk do prachu se navrátil.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 16, 'Máš-li tedy rozum, poslyš toho, pusť v uši své hlas řečí mých.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 17, 'Ješto ten, kterýž by v nenávisti měl soud, zdaliž by panovati mohl? Čili toho, jenž jest svrchovaně spravedlivý, za nešlechetného vyhlásíš?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 18, 'Zdaliž sluší králi říci: Ó nešlechetný, a šlechticům: Ó bezbožní?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 19, 'Mnohem méně tomu, kterýž nepřijímá osob knížat, aniž u něho má přednost urozený před nuzným; nebo dílo rukou jeho jsou všickni.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 20, 'V okamžení umírají, třebas o půl noci postrčeni bývají lidé, a pomíjejí, a zachvácen bývá silný ne rukou lidskou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 21, 'Nebo oči jeho hledí na cesty člověka, a všecky kroky jeho on spatřuje.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 22, 'Neníť žádných temností, ani stínu smrti, kdež by se skryli činitelé nepravosti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 23, 'Aniž zajisté vzkládá na koho více, tak aby se s Bohem silným souditi mohl.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 24, 'Pyšné stírá bez počtu, a postavuje jiné na místa jejich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 25, 'Nebo zná skutky jejich; pročež na ně obrací noc, a potříni bývají.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 26, 'Jakožto bezbožné rozráží je na místě patrném,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 27, 'Proto že odstoupili od něho, a žádných cest jeho nešetřili,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 28, 'Aby dokázal, že připouští k sobě křik nuzného, a volání chudých že vyslýchá.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 29, '(Nebo když on spokojí, kdo znepokojí? A když skryje tvář svou, kdo jej spatří?) Tak celý národ, jako i každého člověka jednostejně,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 30, 'Aby nekraloval člověk pokrytý, aby nebylo lidem ourazu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 31, 'Jistě žeť k Bohu silnému raději toto mluveno býti má: Ponesuť, nezruším.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 32, 'Mimo to, ne vidím-li čeho, ty vyuč mne; jestliže jsem nepravost páchal, neučiním toho víc.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 33, 'Nebo zdali vedlé tvého zdání odplacovati má, že bys ty toho neliboval, že bys ono zvoloval, a ne on? Pakli co víš jiného, mluv.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 34, 'Muži rozumní se mnou řeknou, i každý moudrý poslouchaje mne,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 35, 'Že Job hloupě mluví, a slova jeho nejsou rozumná.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 36, 'Ó by zkušen byl Job dokonale, pro odmlouvání nám jako lidem nepravým,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 37, 'Poněvadž k hříchu svému přidává i nešlechetnost, mezi námi také jen chloubu svou vynáší, a rozmnožuje řeči své proti Bohu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 35, 1, 'Ještě mluvil Elihu, a řekl:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 35, 2, 'Domníváš-liž se, že jsi to s soudem řekl: Spravedlnost má převyšuje Boží?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 35, 3, 'Nebo jsi řekl: Co mi prospěje, jaký užitek budu míti, bych i nehřešil?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 35, 4, 'Já odpovím tobě místně, i tovaryšům tvým s tebou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 35, 5, 'Pohleď na nebe a viz, anobrž spatř oblaky, vyšší, než-lis ty.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 35, 6, 'Jestliže bys hřešil, co svedeš proti němu? A byť se i rozmnožily nešlechetnosti tvé, co mu uškodíš?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 35, 7, 'Budeš-li spravedlivý, čeho mu udělíš? Aneb co z ruky tvé vezme?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 35, 8, 'Každémuť člověku bezbožnost jeho uškodí, a synu člověka spravedlnost jeho prospěje.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 35, 9, 'Z množství nátisk trpících, kteréž k tomu přivodí, aby úpěli a křičeli pro ukrutnost povýšených,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 35, 10, 'Žádný neříká: Kde jest Bůh stvořitel můj? Ješto on dává zpěv i v noci.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 35, 11, 'On vyučuje nás nad hovada zemská, a nad ptactvo nebeské moudřejší nás činí.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 35, 12, 'Tehdáž volají-li pro pýchu zlých, nebývají vyslyšáni.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 35, 13, 'A jistě žeť ošemetnosti nevyslýchá Bůh silný, a Všemohoucí nepatří na ni.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 35, 14, 'Mnohem méně, jestliže díš: Nepatříš na to. Sám s sebou vejdi v soud před ním, a doufej v něho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 35, 15, 'Ale nyní poněvadž nic není těch věcí, navštívil jej hněv jeho; nebo nechce znáti hojnosti této veliké.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 35, 16, 'A protož marně Job otvírá ústa svá, hloupě rozmnožuje řeči své.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 1, 'Zatím přidal Elihu, a řekl:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 2, 'Postrp mne maličko, a oznámímť šíře; neboť mám ještě, co bych za Boha mluvil.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 3, 'Vynesu smysl svůj zdaleka, a stvořiteli svému přivlastním spravedlnost.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 4, 'V pravdě, žeť ne budou lživé řeči mé; zdravě smýšlejícího máš mne s sebou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 5, 'Aj, Bůh silný mocný jest, aniž svých zamítá; silný jest, a srdce udatného.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 6, 'Neobživuje bezbožného, chudým pak k soudu dopomáhá.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 7, 'Neodvrací od spravedlivého očí svých, nýbrž s králi na stolici sází je na věky, i bývají zvýšeni.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 8, 'Pakli by poutami sevříni byli, zapleteni jsouce provazy ssoužení:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 9, 'Tudy jim v známost uvodí hřích jejich, a že přestoupení jejich se ssilila.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 10, 'A tak otvírá sluch jejich, aby se napravili, anobrž mluví jim, aby se navrátili od nepravosti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 11, 'Uposlechnou-li a budou-li jemu sloužiti, stráví dny své v dobrém, a léta svá v potěšení.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 12, 'Pakli neuposlechnou, od meče sejdou, a pozdychají bez umění.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 13, 'Nebo kteříž jsou nečistého srdce, přivětšují hněvu, aniž k němu volají, když by je ssoužil.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 14, 'Protož umírá v mladosti duše jejich, a život jejich s smilníky.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 15, 'Vytrhuje, pravím, ssouženého z jeho ssoužení, a ty, jejichž sluch otvírá, v trápení.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 16, 'A tak by i tebe přenesl z prostředku úzkosti na širokost, kdež není stěsnění, a byl by pokojný stůl tvůj tukem oplývající.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 17, 'Ale ty zasloužils, abys jako bezbožný souzen byl; soud a právo na tě dochází.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 18, 'Jistě strach, aby tě neuvrhl Bůh u větší ránu, tak že by jakkoli veliká výplaty mzda, tebe nevyprostila.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 19, 'Zdaliž by sobě co vážil bohatství tvého? Jistě ani nejvýbornějšího zlata, ani jakékoli síly neb moci tvé.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 20, 'Nechvátejž tedy k noci, v kterouž odcházejí lidé na místo své.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 21, 'Hleď, abys se neohlédal na marnost, zvoluje ji raději, nežli ssoužení.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 22, 'Aj, Bůh silný nejvyšší jest mocí svou. Kdo jemu podobný učitel?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 23, 'Kdo jemu vyměřil cestu jeho? Kdo jemu smí říci: Činíš nepravost?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 24, 'Pamětliv buď raději, abys vyvyšoval dílo jeho, kteréž spatřují lidé,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 25, 'Kteréž, pravím, všickni lidé vidí, na něž člověk patří zdaleka.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 26, 'Nebo Bůh silný tak jest veliký, že ho nemůžeme poznati, počet let jeho jest nevystižitelný.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 27, 'On zajisté vyvodí krůpěje vod, kteréž vylévají déšť z oblaků jeho,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 28, 'Když se rozpouštějí oblakové, a kropí na mnohé lidi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 29, '(Anobrž vyrozumí-li kdo roztažení oblaků, a zvuku stánku jeho,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 30, 'Jak rozprostírá nad ním světlo své, aneb všecko moře přikrývá?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 31, 'Skrze ty věci zajisté tresce lidi, a též dává pokrmu hojnost.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 32, 'Oblaky zakrývá světlo, a přikazuje mu ukrývati se za to, co je potkává.)');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 33, 'Ohlašuje o něm zvuk jeho, též dobytek, a to hned, když pára zhůru vstupuje.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 1, 'Takéť se i nad tím děsí srdce mé, až se pohybuje z místa svého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 2, 'Poslouchejte pilně hřmotného hlasu jeho, a zvuku z úst jeho pocházejícího.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 3, 'Pode všecka nebesa jej rozprostírá, a světlo své k krajům země.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 4, 'Za nímž zvučí hlukem, a hřímá hlasem důstojnosti své, aniž mešká s jinými věcmi, když se slýchá hlas jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 5, 'Bůh silný hřímá hlasem svým předivně, činí veliké věci, a však nemůžeme rozuměti, jak.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 6, 'Sněhu zajisté říká: Buď na zemi, tolikéž pršce dešťové, ano i přívalu násilnému.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 7, 'Zavírá ruku všelikého člověka, aby žádný z lidí nemohl konati díla svého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 8, 'Tehdáž i zvěř vchází do skrýše, a v peleších svých obývá.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 9, 'Z skrýše vychází vichřice, a od půlnoční strany zima.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 10, 'Dchnutím Bůh silný dává mráz, až se široké vody zavírají.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 11, 'Také i při svlažování země pohybuje oblakem, a rozhání mračno světlem svým.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 12, 'A tentýž sem i tam obrací se moudrostí jeho, aby činil, což by mu koli přikázal na tváři okršlku zemského.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 13, 'Buď k trestání, neb pro zemi svou, buď k prokazování dobrotivosti, spraví to, že se postaví.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 14, 'Pozorujž toho, Jobe, zastav se a podívej se divům Boha silného.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 15, 'Víš-li, kdy Bůh ukládá co o těch věcech, aneb kdy chce osvěcovati světlem oblaky své?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 16, 'Znáš-li, jak se vznášejí oblakové, a jiné divy dokonalého v uměních?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 17, 'A že tě roucho tvé zahřívati bude, když Bůh zemi pokojnou činí větry poledními?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 18, 'Roztahoval-li jsi s ním nebesa trvánlivá, k zrcadlu slitému podobná?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 19, 'Poukaž nám, co bychom řekli jemu; nebo nemůžeme ani řeči zpořádati pro temnost.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 20, 'Zdaž jemu kdo oznámí, co bych já mluvil? Pakli by kdo za mne mluvil, jistě že by byl sehlcen.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 21, 'Ano nyní nemohou patřiti lidé na světlo, když jest jasné na oblacích, když je vítr prochází a vyčišťuje,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 22, 'Od půlnoční strany s jasnem jako zlato přicházeje, ale v Bohu hroznější jest sláva.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 23, 'Všemohoucí, jehož vystihnouti nemůžeme, ač jest veliký v moci, však soudem a přísnou spravedlností netrápí.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 24, 'Protož bojí se ho lidé; neohlédá se na žádného z těch, kdož jsou moudrého srdce.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 1, 'Tedy odpověděl Hospodin Jobovi z vichru, a řekl:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 2, 'Kdož jest to, jenž zatemňuje radu řečmi neumělými?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 3, 'Přepaš nyní jako muž bedra svá, a nač se tebe tázati budu, oznam mi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 4, 'Kdes byl, když jsem zakládal zemi? Pověz, jestliže máš rozum.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 5, 'Kdo rozměřil ji, víš-li? Aneb kdo vztáhl pravidlo na ni?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 6, 'Na čem podstavkové její upevněni jsou? Aneb kdo založil úhelný kámen její,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 7, 'Když prozpěvovaly spolu hvězdy jitřní, a plésali všickni synové Boží?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 8, 'Aneb kdo zavřel jako dveřmi moře, když vyšlo z života, a zjevilo se?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 9, 'Když jsem mu položil oblak za oděv, a mrákotu místo plének jeho,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 10, 'Když jsem jemu uložil úsudek svůj, přistaviv závory a dvéře,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 11, 'I řekl jsem: Až potud vycházeti budeš, a dále nic, tu, pravím, skládati budeš dutí vlnobití svého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 12, 'Zdaž jsi kdy za dnů svých rozkázal jitru? Ukázal-lis záři jitřní místo její,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 13, 'Aby uchvacovala kraje země, a bezbožní aby z ní vymítáni byli?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 14, 'Tak aby proměnu přijímala jako vosk pečetní, oni pak aby nedlouho stáli jako roucho,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 15, 'A aby bezbožným zbraňováno bylo světla jejich, a rámě vyvýšené zlámáno bylo?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 16, 'Přišel-lis až k hlubinám mořským? A u vnitřnosti propasti chodil-lis?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 17, 'Jsou-li tobě zjeveny brány smrti? A brány stínu smrti viděl-lis?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 18, 'Shlédl-lis širokosti země? Oznam, jestliže ji znáš všecku.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 19, 'Která jest cesta k obydlí světla, a které místo temností,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 20, 'Že bys je pojal v meze jeho, poněvadž bys srozumíval stezkám domu jeho?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 21, 'Věděl-lis tehdáž, že jsi měl se naroditi, a počet dnů tvých jak veliký býti má?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 22, 'Přišel-lis až ku pokladům sněhu? A poklady krupobití viděl-lis,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 23, 'Kteréž chovám k času ssoužení, ke dni bitvy a boje?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 24, 'Kterými se cestami rozděluje světlo, kteréž rozhání východní vítr po zemi?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 25, 'Kdo rozdělil povodní tok, a cestu blýskání hromovému,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 26, 'Tak aby pršel déšť i na tu zemi, kdež není lidí, na poušť, kdež není člověka,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 27, 'Aby zapájel místa planá a pustá, a k zrůstu přivodil trávu mladistvou?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 28, 'Má-liž déšť otce? A kdo plodí krůpěje rosy?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 29, 'Z čího života vychází mráz? A jíní nebeské kdo plodí?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 30, 'Až i vody jako v kámen se proměňují, a svrchek propasti zamrzá.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 31, 'Zdali zavázati můžeš rozkoše Kuřátek, aneb stahování Orionovo rozvázati?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 32, 'Můžeš-li vyvoditi hvězdy polední v čas jistý, aneb Arktura s syny jeho povedeš-li?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 33, 'Znáš-li řád nebes? Můžeš-li spravovati panování jejich na zemi?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 34, 'Můžeš-li pozdvihnouti k oblaku hlasu svého, aby hojnost vod přikryla tebe?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 35, 'Ty-liž vypustíš blýskání, aby vycházela? Zdaliž řeknou tobě: Aj teď jsme?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 36, 'Kdo složil u vnitřnostech lidských moudrost? Aneb kdo dal rozumu stižitelnost?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 37, 'Kdo vypravovati bude o nebesích moudře? A láhvice nebeské kdo nastrojuje,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 38, 'Aby svlažená země zase stuhnouti mohla, a hrudy se v hromadě držely?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 39, 'Honíš-liž ty lvu loupež? A hltavost lvíčat naplňuješ-liž,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 40, 'Když se stulují v peleších svých, ustavičně z skrýší číhajíce?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 41, 'Kdo připravuje krkavci pokrm jeho, když mladí jeho k Bohu silnému volají, a toulají se sem i tam pro nedostatek pokrmu?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 1, 'Víš-li, kterého času rodí kamsíkové, a laň ku porodu pracující spatřil-lis?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 2, 'Máš-li v počtu měsíce, kteréž vyplňují? Znáš-li, pravím, čas porodu jejich?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 3, 'Jak se kladou, plod svůj utiskají, a s bolestí ho pozbývají?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 4, 'Jak se zmocňují mladí jejich, i odchovávají picí polní, a vycházejíce, nenavracují se k nim?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 5, 'Kdo propustil zvěř, aby byla svobodná? A řemení divokého osla kdo rozvázal?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 6, 'Jemuž jsem dal pustinu místo domu jeho, a místo příbytku jeho zemi slatinnou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 7, 'Posmívá se hluku městskému, a na křikání toho, kdož by jej honil, nic nedbá.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 8, 'To, což nachází v horách, jest pastva jeho; nebo toliko zeliny hledá.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 9, 'Svolí-liž jednorožec, aby tobě sloužil, a u jeslí tvých aby nocoval?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 10, 'Připřáhneš-liž provazem jednorožce k orání? Bude-liž vláčeti brázdy za tebou?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 11, 'Zdaž se na něj ubezpečíš, proto že jest veliká síla jeho, a poručíš jemu svou práci?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 12, 'Zdaž se jemu dověříš, že sveze semeno tvé, a na humno tvé shromáždí?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 13, 'Ty-lis dal pávům křídlo pěkné, aneb péro čápu neb pstrosu?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 14, 'A že opouští na zemi vejce svá, ačkoli je v prachu osedí,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 15, 'Nic nemysle, že by je noha potlačiti, aneb zvěř polní pošlapati mohla?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 16, 'Tak se zatvrzuje k mladým svým, jako by jich neměl; jako by neužitečná byla práce jeho, tak jest bez starosti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 17, 'Nebo nedal jemu Bůh moudrosti, aniž mu udělil rozumnosti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 18, 'Časem svým zhůru se vznášeje, posmívá se koni i jezdci jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 19, 'Zdaž ty dáti můžeš koni sílu? Ty-li ozdobíš šíji jeho řehtáním?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 20, 'Zdali jej zastrašíš jako kobylku? Anobrž frkání chřípí jeho strašlivé jest.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 21, 'Kopá důl, a pléše v síle své, vycházeje vstříc i zbroji.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 22, 'Směje se strachu, aniž se leká, aniž ustupuje zpátkem před ostrostí meče,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 23, 'Ač i toul na něm chřestí, a blyští se dřevce a kopí.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 24, 'S hřmotem a s hněvem kopá zemi, aniž pokojně stojí k zvuku trouby.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 25, 'Anobrž k zvuku trouby řehce, a zdaleka cítí boj, hluk knížat a prokřikování.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 26, 'Zdali podlé rozumu tvého létá jestřáb, roztahuje křídla svá na poledne?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 27, 'Zdali k rozkazu tvému zhůru se vznáší orlice, a vysoko se hnízdí?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 28, 'Na skále přebývá, přebývá na špičaté skále jako na hradě,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 29, 'Odkudž hledá pokrmu, kterýž z daleka očima svýma spatřuje.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 30, 'Ano i mladí její střebí krev, a kde těla mrtvá, tu i ona jest.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 1, 'A tak odpovídaje Hospodin Jobovi, řekl:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 2, 'Zdali hádající se s Všemohoucím obviní jej? Kdo chce viniti Boha, nechť odpoví na to.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 3, 'Tehdy odpověděl Job Hospodinu a řekl:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 4, 'Aj, chaternýť jsem, což bych odpovídal tobě? Ruku svou kladu na ústa svá.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 5, 'Jednou jsem mluvil, ale nebudu již odmlouvati, nýbrž i podruhé, ale nebudu více přidávati.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 6, 'Ještě odpovídaje Hospodin z vichru Jobovi, i řekl:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 7, 'Přepaš nyní jako muž bedra svá, a nač se tebe tázati budu, oznam mi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 8, 'Zdaliž pak i soud můj zrušiti chceš? Což mne odsoudíš, jen abys se sám ospravedlnil?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 9, 'Čili máš rámě jako Bůh silný, a hlasem jako on hřímáš?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 10, 'Ozdobiž se nyní vyvýšeností a důstojností, v slávu a okrasu oblec se.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 11, 'Rozprostři prchlivost hněvu svého, a pohleď na všelikého pyšného, a sniž ho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 12, 'Pohleď, pravím, na všelikého pyšného, a sehni jej, anobrž setři bezbožné na místě jejich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 13, 'Skrej je v prachu spolu, tvář jejich zavěž v skrytě.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 14, 'A tak i já budu tě oslavovati, že tě zachovává pravice tvá.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 15, 'Aj, hle slon, jejž jsem jako i tebe učinil, trávu jí jako vůl.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 16, 'Aj, hle moc jeho v bedrách jeho, a síla jeho v pupku břicha jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 17, 'Jak chce, ohání ocasem svým, ačkoli jest jako cedr; žily lůna jeho jako ratolesti jsou spletené.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 18, 'Kosti jeho jako trouby měděné, hnátové jeho jako sochor železný.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 19, 'Onť jest přední z účinků Boha silného, učinitel jeho sám na něj doložiti může meč svůj.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 20, 'Hory zajisté přinášejí mu pastvu, a všecka zvěř polní hrá tam.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 21, 'V stínu léhá, v soukromí mezi třtím a bahnem.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 22, 'Dříví stín dávající stínem svým jej přikrývá, a vrbí potoční obkličuje jej.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 23, 'Aj, zadržuje řeku tak, že nemůže pospíchati; tuší sobě, že požře Jordán v ústa svá.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 24, 'Zdaž kdo před očima jeho polapí jej, aneb provazy protáhne chřípě jeho?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 1, 'Vytáhneš-liž velryba udicí, aneb provazem pohříženým až k jazyku jeho?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 2, 'Zdali dáš kroužek na chřípě jeho, aneb hákem probodneš čelist jeho?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 3, 'Zdaž se obrátí k tobě s prosbami, aneb mluviti bude tobě lahodně?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 4, 'Učiní-liž smlouvu s tebou? Přijmeš-liž jej za služebníka věčného?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 5, 'Zdaž budeš s ním hráti jako s ptáčkem, aneb přivážeš jej dětem svým?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 6, 'Přistrojí-liž sobě hody z něho společníci, a rozdělí-liž jej mezi kupce?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 7, 'Zdaž naplníš háky kůži jeho, a vidlicemi rybářskými hlavu jeho?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 8, 'Vztáhni jen na něj ruku svou, a neučiníš zmínky o boji.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 9, 'Aj, naděje o polapení jeho mylná jest. Zdaž i k spatření jeho člověk nebývá poražen?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 10, 'Není žádného tak smělého, kdo by jej zbudil, kdož tedy postaví se přede mnou?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 11, 'Kdo mne čím předšel, abych se jemu odplacel? Cožkoli jest pode vším nebem, mé jest.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 12, 'Nebudu mlčeti o údech jeho, a o síle výborného sformování jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 13, 'Kdo odkryl svrchek oděvu jeho? S dvojitými udidly svými kdo k němu přistoupí?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 14, 'Vrata úst jeho kdo otevře? Okolo zubů jeho jest hrůza.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 15, 'Šupiny jeho pevné jako štítové sevřené velmi tuze.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 16, 'Jedna druhé tak blízko jest, že ani vítr nevchází mezi ně.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 17, 'Jedna druhé se přídrží, a nedělí se.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 18, 'Od kýchání jeho zažžehá se světlo, a oči jeho jsou jako záře svitání.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 19, 'Z úst jeho jako pochodně vycházejí, a jiskry ohnivé vyskakují.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 20, 'Z chřípí jeho vychází dým, jako z kotla vroucího aneb hrnce.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 21, 'Dýchání jeho uhlí rozpaluje, a plamen z úst jeho vychází.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 22, 'V šíji jeho přebývá síla, a před ním utíká žalost.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 23, 'Kusové masa jeho drží se spolu; celistvé jest v něm, aniž se rozdrobuje.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 24, 'Srdce jeho tuhé jest jako kámen, tak tuhé, jako úlomek zpodního žernovu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 25, 'Vyskýtání jeho bojí se nejsilnější, až se strachem i vyčišťují.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 26, 'Meč stihající jej neostojí, ani kopí, šíp neb i pancíř.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 27, 'Pokládá železo za plevy, ocel za dřevo shnilé.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 28, 'Nezahání ho střela, v stéblo obrací se jemu kamení prakové.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 29, 'Za stéblo počítá střelbu, a posmívá se šermování kopím.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 30, 'Pod ním ostré střepiny, stele sobě na věci špičaté jako na blátě.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 31, 'Působí, aby vřelo v hlubině jako v kotle, a kormoutilo se moře jako v moždíři.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 32, 'Za sebou patrnou činí stezku, až sezdá, že propast má šediny.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 33, 'Žádného není na zemi jemu podobného, aby tak učiněn byl bez strachu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 34, 'Cokoli vysokého jest, za nic pokládá, jest králem nade všemi šelmami.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 42, 1, 'Tedy odpovídaje Job Hospodinu, řekl:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 42, 2, 'Vím, že všecko můžeš, a že nemůže překaženo býti tvému myšlení.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 42, 3, 'Kdo jest to ten, ptáš se, ješto zatemňuje radu Boží tak hloupě? Protož přiznávám se, že jsem tomu nerozuměl. Divnějšíť jsou ty věci nad mou stižitelnost, anižť jich mohu poznati.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 42, 4, 'Vyslýchejž, prosím, když bych koli mluvil; když bych se tebe tázal, oznamuj mi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 42, 5, 'Tolikoť jsem slýchal o tobě, nyní pak i oko mé tě vidí.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 42, 6, 'Pročež mrzí mne to, a želím toho v prachu a v popele.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 42, 7, 'Stalo se pak, když odmluvil Hospodin slova ta k Jobovi, že řekl Hospodin Elifazovi Temanskému: Rozpálil se hněv můj proti tobě, a proti dvěma přátelům tvým, proto že jste nemluvili o mně toho, což pravého jest, tak jako služebník můj Job.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 42, 8, 'Protož nyní vezměte sobě sedm volků, a sedm skopců, a jděte k služebníku mému Jobovi, abyste dali obětovati obět za sebe, a služebník můj Job, aby se modlil za vás. Nebo jistě oblíčej jeho přijmu, abych neučinil s vámi podlé bláznovství vašeho; nebo nemluvili jste toho, což pravého jest, o mně, tak jako služebník můj Job.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 42, 9, 'A tak odšedše Elifaz Temanský a Bildad Suchský a Zofar Naamatský, učinili, jakž jim byl přikázal Hospodin, a přijal Hospodin oblíčej Jobův.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 42, 10, 'Navrátil také Hospodin to, což odjato bylo Jobovi, když se modlil za přátely své, tak že což měl Job, rozmnožil to Hospodin dvénásobně.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 42, 11, 'A sšedše se k němu všickni příbuzní, a všecky příbuzné jeho, a všickni známí jeho prvnější, jedli s ním chléb v domě jeho, a lítost majíce nad ním, potěšovali ho nade vším tím zlým, kteréž byl uvedl Hospodin na něj. A dali jemu jeden každý peníz jeden, a jeden každý náušnici zlatou jednu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 42, 12, 'A tak požehnal Hospodin Jobovi k posledku více nežli v počátku jeho. Nebo měl čtrnácte tisíc ovcí, a šest tisíc velbloudů, a tisíc spřežení volů, a tisíc oslic.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 42, 13, 'Měl také sedm synů a tři dcery,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 42, 14, 'Z nichž první dal jméno Jemima, jméno pak druhé Keciha, a jméno třetí Kerenhappuch.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 42, 15, 'Aniž se nacházely ženy tak krásné, jako dcery Jobovy, ve vší té krajině; kterýmž dal otec jejich dědictví mezi bratřími jejich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 42, 16, 'Byl pak živ Job potom sto a čtyřidceti let, a viděl syny své, a syny synů svých, až do čtvrtého pokolení.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 42, 17, 'I umřel Job, stár jsa a pln dnů.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 1, 1, 'Blahoslavený ten muž, kterýž nechodí po radě bezbožných, a na cestě hříšníků nestojí, a na stolici posměvačů nesedá.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 1, 2, 'Ale v zákoně Hospodinově jest líbost jeho, a v zákoně jeho přemýšlí dnem i nocí.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 1, 3, 'Nebo bude jako strom štípený při tekutých vodách, kterýž ovoce své vydává časem svým, jehožto list nevadne, a cožkoli činiti bude, šťastně mu se povede.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 1, 4, 'Ne takť budou bezbožní, ale jako plevy, kteréž rozmítá vítr.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 1, 5, 'A protož neostojí bezbožní na soudu, ani hříšníci v shromáždění spravedlivých.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 1, 6, 'Neboť zná Hospodin cestu spravedlivých, ale cesta bezbožných zahyne.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 2, 1, 'Proč se bouří národové, a lidé daremné věci přemyšlují?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 2, 2, 'Sstupují se králové zemští, a knížata se spolu radí proti Hospodinu, a proti pomazanému jeho,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 2, 3, 'Říkajíce: Roztrhejme svazky jejich, a zavrzme od sebe provazy jejich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 2, 4, 'Ale ten, jenž přebývá v nebesích, směje se, Pán posmívá se jim.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 2, 5, 'Tehdáž mluviti bude k nim v hněvě svém, a v prchlivosti své předěsí je, řka:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 2, 6, 'Jáť jsem ustanovil krále svého nad Sionem, horou svatou mou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 2, 7, 'Vypravovati budu úsudek. Hospodin řekl ke mně: Syn můj ty jsi, já dnes zplodil jsem tě.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 2, 8, 'Požádej mne, a dámť národy, dědictví tvé, a končiny země, vládařství tvé.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 2, 9, 'Roztlučeš je prutem železným, a jako nádobu hrnčířskou roztříštíš je.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 2, 10, 'A protož, králové, nyní srozumějte, vyučujte se, soudcové zemští.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 2, 11, 'Služte Hospodinu v bázni, a veselte se s třesením.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 2, 12, 'Líbejte syna, aby se nerozhněval, a zhynuli byste na cestě, jakž by se jen málo zapálil hněv jeho. Blahoslavení jsou všickni, kteříž doufají v něho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 3, 1, 'Žalm Davidův, když utíkal před Absolonem synem svým. Hospodine, jakť jsou mnozí nepřátelé moji! Mnozí povstávají proti mně.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 3, 2, 'Mnozí mluví o duši mé: Nemáť tento žádné pomoci v Bohu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 3, 3, 'Ale ty, Hospodine, jsi štítem vůkol mne, slávou mou, a kterýž povyšuješ hlavy mé.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 3, 4, 'Hlasem svým volal jsem k Hospodinu, a vyslyšel mne s hory svaté své. Sélah.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 3, 5, 'Já jsem lehl, a spal jsem, i zas procítil; nebo mne zdržoval Hospodin.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 3, 6, 'Nebuduť se báti mnoha tisíců lidí, kteříž se vůkol kladou proti mně.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 3, 7, 'Povstaniž, Hospodine, zachovej mne, Bože můj, kterýž jsi zbil všech nepřátel mých líce, a zuby bezbožníků zvyrážel.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 3, 8, 'Tvéť, ó Hospodine, jest spasení, a nad lidem tvým požehnání tvé. Sélah.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 4, 1, 'Přednímu zpěváku na neginot, žalm Davidův. Když volám, vyslyš mne, Bože spravedlnosti mé. Ty jsi mi v úzkosti prostranství způsoboval, smiluj se nade mnou, a vyslyš modlitbu mou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 4, 2, 'Synové lidští, dokudž sláva má v potupě bude? Dlouho-liž marnost milovati a lži hledati budete? Sélah.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 4, 3, 'Vězte, žeť jest oddělil Hospodin sobě milého. Vyslyšíť mne Hospodin, když k němu volati budu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 4, 4, 'Uleknětež se a nehřešte, přemyšlujte o tom v srdci svém, na ložci svém, a umlkněte. Sélah.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 4, 5, 'Obětujte oběti spravedlnosti, a doufejte v Hospodina.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 4, 6, 'Mnozí říkají: Ó bychom viděti mohli dobré věci. Hospodine, pozdvihni nad námi jasného oblíčeje svého,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 4, 7, 'I způsobíš radost v srdci mém větší, než oni mívají, když obilé a víno jejich se obrodí.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 4, 8, 'Jáť u pokoji i lehnu i spáti budu; nebo ty, Hospodine, sám způsobíš mi bydlení bezpečné.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 5, 1, 'Přednímu zpěváku na nechilot, žalm Davidův. Slova má slyš, Hospodine, porozuměj tužebnému úpění mému.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 5, 2, 'Pozoruj hlasu volání mého, králi můj a Bože můj; nebo se tobě modlím.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 5, 3, 'Hospodine, v jitře vyslyšíš hlas můj, v jitře předložím tobě žádost, a šetřiti budu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 5, 4, 'Nebo ty, ó Bože silný, neoblibuješ bezbožnosti, nemá místa u tebe nešlechetník.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 5, 5, 'Neostojí blázniví před očima tvýma, v nenávisti máš všecky činitele nepravosti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 5, 6, 'Zatratíš mluvící lež. Člověka ukrutného a lstivého v ohavnosti má Hospodin.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 5, 7, 'Já pak ve množství milosrdenství tvého vejdu do domu tvého, klaněti se budu k svatému chrámu tvému v bázni tvé.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 5, 8, 'Hospodine, proveď mne v spravedlnosti své, pro ty, jenž mne střehou; spravuj přede mnou cestu svou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 5, 9, 'Neboť není v ústech jejich žádné upřímnosti, vnitřnosti jejich plné nešlechetnosti, hrob otevřený hrdlo jejich, jazykem svým lahodně mluví.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 5, 10, 'Zkaz je, ó Bože, nechať padnou od rad svých; pro množství nešlechetností jejich rozptyl je, poněvadž odporní jsou tobě.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 5, 11, 'A ať se všickni v tě doufající radují, na věky ať plésají, když je zastírati budeš; ať se v tobě veselí, kteřížkoli milují jméno tvé.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 5, 12, 'Nebo ty, Hospodine, požehnáš spravedlivému, a jako štítem přívětivostí svou vůkol zastřeš jej.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 6, 1, 'Přednímu kantoru na neginot, k nízkému zpěvu, žalm Davidův. Hospodine, netresci mne v hněvě svém, ani v prchlivosti své kárej mne.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 6, 2, 'Smiluj se nade mnou, Hospodine, neboť jsem zemdlený; uzdrav mne, Hospodine, nebo ztrnuly kosti mé.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 6, 3, 'Ano i duše má předěšena jest náramně, ty pak, Hospodine, až dokavad?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 6, 4, 'Navratiž se, Hospodine, a vytrhni duši mou; spomoz mi pro milosrdenství své.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 6, 5, 'Nebo mrtví nezpomínají na tebe, a v hrobě kdo tě bude oslavovati?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 6, 6, 'Ustávám v úpění svém, ložce své každé noci svlažuji, slzami svými postel svou smáčím.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 6, 7, 'Sškvrkla se zámutkem tvář má, sstarala se příčinou všech nepřátel mých.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 6, 8, 'Odstuptež ode mne všickni činitelé nepravosti; neboť jest vyslyšel Hospodin hlas pláče mého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 6, 9, 'Vyslyšel Hospodin pokornou modlitbu mou, Hospodin modlitbu mou přijal.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 6, 10, 'Nechažť se zastydí a předěsí zřejmě všickni nepřátelé moji, nechažť jsou zpět obráceni a rychle zahanbeni.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 1, 'Osvědčení neviny Davidovy, o čemž zpíval Hospodinu z příčiny slov Chusi syna Jeminova. Hospodine Bože můj, v toběť doufám, vysvoboď mne ode všech protivníků mých, a vytrhni mne,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 2, 'Aby neuchvátil jako lev duše mé, a neroztrhal, když by nebyl, kdo by vysvobodil.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 3, 'Hospodine Bože můj, učinil-li jsem to, jest-li nepravost při mně,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 4, 'Činil-li jsem zle tomu, kdož se ke mně pokojně choval, (nýbrž spomáhal jsem protivícímu se mi bez příčiny),');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 5, 'Nechať stihá nepřítel duši mou, i popadne, a pošlapá na zemi život můj, a slávu mou v prach uvede. Sélah.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 6, 'Povstaň, Hospodine, v hněvě svém, vyvyš se proti vzteklostem mých nepřátel, a prociť ke mně, nebo jsi soud nařídil.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 7, 'I shrne se k tobě shromáždění lidí; pro ně tedy u výsost navrať se zase.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 8, 'Hospodin souditi bude lidi. Sudiž mne, Hospodine, podlé spravedlnosti mé, a podlé nevinnosti mé, kteráž při mně jest.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 9, 'Ó by již k skončení přišla nešlechetnost bezbožných, spravedlivého pak abys utvrdil ty, kterýž zkušuješ srdce a ledví, Bože spravedlivý.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 10, 'Bůh jest štít můj, kterýž spaseny činí upřímé srdcem.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 11, 'Bůh jest soudce spravedlivý, Bůh silný hněvá se na bezbožného každý den.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 12, 'Neobrátí-li se, naostříť meč svůj; lučiště své natáhl, a naměřil je.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 13, 'Připravil sobě i zbroj smrtelnou, střely své proti škůdcím přistrojil.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 14, 'Aj, rodí nepravost; nebo počav těžkou bolest, urodí lež.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 15, 'Jámu kopal, i vykopal ji, ale padne do dolu, kterýž přistrojil.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 16, 'Obrátíť se usilování jeho na hlavu jeho, a na vrch hlavy jeho nepravost jeho sstoupí.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 17, 'Slaviti budu Hospodina podlé spravedlnosti jeho, a žalmy zpívati jménu Hospodina nejvyššího.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 8, 1, 'Přednímu zpěváku na gittejský nástroj, žalm Davidův. Hospodine Pane náš, jak důstojné jest jméno tvé na vší zemi! Nebo jsi vyvýšil slávu svou nad nebesa.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 8, 2, 'Z úst nemluvňátek a těch, jenž prsí požívají, mocně dokazuješ síly z příčiny svých nepřátel, abys přítrž učinil protivníku a vymstívajícímu se.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 8, 3, 'Když spatřuji nebesa tvá, dílo prstů tvých, měsíc a hvězdy, kteréž jsi tak upevnil, říkám:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 8, 4, 'Co jest člověk, že jsi naň pamětliv, a syn člověka, že jej navštěvuješ?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 8, 5, 'Nebo učinil jsi ho málo menšího andělů, slávou a ctí korunoval jsi jej.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 8, 6, 'Pánem jsi ho učinil nad dílem rukou svých, všecko jsi podložil pod nohy jeho:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 8, 7, 'Ovce i voly všecky, také i zvěř polní,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 8, 8, 'Ptactvo nebeské, i ryby mořské, a cožkoli chodí stezkami mořskými.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 8, 9, 'Hospodine Pane náš, jak důstojné jest jméno tvé na vší zemi!');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 1, 'Přednímu zpěváku na al mutlabben, žalm Davidův. Oslavovati tě budu, Hospodine, celým srdcem svým, vypravovati budu všecky divné skutky tvé.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 2, 'Radovati a veseliti se budu v tobě, žalmy zpívati budu jménu tvému, ó Nejvyšší,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 3, 'Proto že nepřátelé moji jsou nazpět obráceni, že klesli, a zahynuli od tváři tvé.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 4, 'Nebo jsi vyvedl soud můj a při mou, posadils se na stolici soudce spravedlivý.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 5, 'Ohromil jsi národy, zatratils bezbožníka, jméno jejich vyhladil jsi na věčné věky.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 6, 'Ó nepříteli, již-li jsou dokonány zhouby tvé na věky? Již-li jsi města podvrátil? Zahynula památka jejich s nimi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 7, 'Ale Hospodin na věky kraluje, připravil k soudu trůn svůj.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 8, 'Onť soudí sám okršlek v spravedlnosti, a výpověd činí národům v pravosti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 9, 'Hospodin zajisté jest útočiště chudého, útočiště v čas ssoužení.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 10, 'I budou v tebe doufati, kteříž znají jméno tvé; nebo neopouštíš hledajících tě, Hospodine.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 11, 'Žalmy zpívejte Hospodinu, přebývajícímu na Sionu, zvěstujte mezi národy skutky jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 12, 'Nebo on vyhledává krve, rozpomíná se na ni, aniž se zapomíná na křik utištěných.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 13, 'Smiluj se nade mnou, Hospodine, viz ssoužení mé od těch, kteříž mne nenávidí, ty, kterýž mne vyzdvihuješ z bran smrti,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 14, 'Abych vypravoval všecky chvály tvé v branách dcery Sionské, a veselil se v spasení tvém.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 15, 'Pohříženiť jsou národové v jámě, kterouž udělali; v osídle, kteréž polékli, uvázla noha jejich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 16, 'Přišelť jest v známost Hospodin, pomstu učiniv; v díle rukou svých zapletl se bezbožník. Higgaion Sélah.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 17, 'Obráceni buďte bezbožníci do pekla, všickni národové, kteříž se zapomínají nad Bohem.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 18, 'Neboť nebude dán chudý u věčné zapomenutí; očekávání ssoužených nezahyneť na věky.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 19, 'Povstaniž, Hospodine, ať se nesilí člověk; národové buďte souzeni před tebou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 20, 'Pusť na ně strach, ó Hospodine, ať tomu porozumějí národové, že smrtelní jsou. Sélah.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 1, 'Proč, ó Hospodine, stojíš zdaleka, a skrýváš se v čas ssoužení?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 2, 'Z pychu bezbožník protivenství činí chudému. Ó by jati byli v zlých radách, kteréž vymýšlejí.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 3, 'Neboť se honosí bezbožník v líbostech života svého, a lakomý sobě pochlebuje, a Hospodina popouzí.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 4, 'Bezbožník pro pýchu, kterouž na sobě prokazuje, nedbá na nic; všecka myšlení jeho jsou, že není Boha.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 5, 'Dobře mu se daří na cestách jeho všelikého času, soudové tvoji vzdáleni jsou od něho, i na všecky nepřátely své fouká,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 6, 'Říkaje v srdci svém: Nepohnuť se od národu až do pronárodu, nebo ne bojím se zlého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 7, 'Ústa jeho plná jsou zlořečenství, i chytrosti a lsti; pod jazykem jeho trápení a starost.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 8, 'Sedí v zálohách ve vsech a v skrýších, aby zamordoval nevinného; očima svýma po chudém špehuje.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 9, 'Číhá v skrytě jako lev v jeskyni své, číhá, aby pochytil chudého, uchvacujeť jej, a táhne pod sítku svou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 10, 'Připadá a stuluje se, dokudž by nevpadlo v silné pazoury jeho shromáždění chudých.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 11, 'Říká v srdci svém: Zapomenulť jest Bůh silný, skryl tvář svou, nepohledíť na věky.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 12, 'Povstaniž, Hospodine Bože silný, vznes ruku svou, nezapomínejž se nad chudými.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 13, 'Proč má bezbožník Boha popouzeti, říkaje v srdci svém, že toho vyhledávati nebudeš?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 14, 'Díváš se do času, nebo ty nátisk a bolest spatřuješ, abys jim odplatil rukou svou; na tebeť se spouští chudý, sirotku ty jsi spomocník.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 15, 'Potři rámě bezbožného, a vyhledej nepravosti zlostného, tak aby neostál.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 16, 'Hospodin jest králem věčných věků, národové z země své hynou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 17, 'Žádost ponížených vyslýcháš, Hospodine, utvrzuješ srdce jejich, ucha svého k nim nakloňuješ,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 18, 'Abys soud činil sirotku a ssouženému, tak aby jich nessužoval více člověk bídný a zemský.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 11, 1, 'Přednímu zpěváku, žalm Davidův. V Hospodina doufám, kterakž tedy říkáte duši mé: Uleť s hory své jako ptáče?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 11, 2, 'Nebo aj, bezbožníci napínají lučiště, přikládají šípy své na tětivo, aby stříleli skrytě na upřímé srdcem.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 11, 3, 'Ale těmi usilováními zkaženi budou; nebo spravedlivý co učinil?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 11, 4, 'Hospodin jest v chrámě svatém svém, trůn Hospodinův v nebi jest; oči jeho hledí, víčka jeho zkušují synů lidských.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 11, 5, 'Hospodin zkušuje spravedlivého, bezbožníka pak a milujícího nepravost nenávidí duše jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 11, 6, 'Dštíti bude na bezbožníky uhlím řeřavým, ohněm a sirou, a duch vichřice bude částka kalicha jejich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 11, 7, 'Nebo Hospodin spravedlivý jest, spravedlnost miluje, na upřímého oči jeho patří.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 12, 1, 'Přednímu kantoru k nízkému zpěvu, žalm Davidův. Spomoz, ó Hospodine; nebo se již nenalézá milosrdného, a vyhynuli věrní z synů lidských.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 12, 2, 'Lež mluví jeden každý s bližním svým, rty úlisnými z srdce dvojitého řeči vynášejí.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 12, 3, 'Ó by vyplénil Hospodin všeliké rty úlisné, a jazyk velikomluvný,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 12, 4, 'Kteříž říkají: Jazykem svým přemůžeme, mámeť ústa svá s sebou, kdo jest pánem naším?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 12, 5, 'Pro zhoubu chudých, pro úpění nuzných jižť povstanu, praví Hospodin, v bezpečnosti postavím toho, na nějž polečeno bylo.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 12, 6, 'Výmluvnosti Hospodinovy jsou výmluvnosti čisté, jako stříbro v hliněné peci přehnané a sedmkrát zprubované.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 12, 7, 'Ty, Hospodine, jim spomáhati budeš, a ostříhati každého od národu tohoto až na věky.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 12, 8, 'Vůkol a vůkol bezbožní se protulují, když takoví ničemní vyvýšeni bývají mezi syny lidskými.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 13, 1, 'Přednímu zpěváku, žalm Davidův. Až dokud, Hospodine? Což se na věky zapomeneš na mne? Dokudž tvář svou skrývati budeš přede mnou?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 13, 2, 'Dokud rady vyhledávati budu v mysli své, a den ode dne svírati se v srdci svém? Až dokud se zpínati bude nepřítel můj nade mnou?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 13, 3, 'Vzhlédni, vyslyš mne, Hospodine Bože můj, osvěť oči mé, abych neusnul snem smrti,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 13, 4, 'A aby neřekl nepřítel můj: Svítězil jsem nad ním, a nepřátelé moji aby neplésali, jestliže bych se poklesl.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 13, 5, 'Jáť zajisté v milosrdenství tvém doufám, plésati bude srdce mé v spasení tvém;');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 13, 6, 'zpívati budu Hospodinu, že jest mi tak dobře učinil.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 14, 1, 'Přednímu zpěváku, píseň Davidova. Říká blázen v srdci svém: Není Boha. Porušeni jsou, a ohavní v snažnostech; není, kdo by činil dobré.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 14, 2, 'Hospodin s nebe popatřil na syny lidské, aby viděl, byl-li by kdo rozumný a hledající Boha.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 14, 3, 'Všickni se odvrátili, napořád neužiteční učiněni jsou; není, kdo by činil dobré, není ani jednoho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 14, 4, 'Zdaliž nevědí všickni činitelé nepravosti, že zžírají lid můj, jako by chléb jedli? Hospodina pak nevzývají.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 14, 5, 'Tehdáž se náramně strašiti budou; nebo Bůh jest v rodině spravedlivého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 14, 6, 'Radu chudého potupujete, ale Hospodin jest naděje jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 14, 7, 'Ó by z Siona dáno bylo spasení Izraelovi. Když Hospodin zase přivede zajaté lidu svého, plésati bude Jákob, a veseliti se Izrael.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 15, 1, 'Žalm Davidův. Hospodine, kdo bude přebývati v stánku tvém? Kdo bydliti bude na hoře svaté tvé?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 15, 2, 'Ten, kdož chodí v upřímnosti, a činí spravedlnost, a mluví pravdu z srdce svého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 15, 3, 'Kdož neutrhá jazykem svým, bližnímu svému nečiní zlého, a potupy neuvodí na bližního svého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 15, 4, 'Ten, před jehož očima v nevážnosti jest zavržený, v poctivosti pak bojící se Hospodina; a přisáhl-li by i se škodou, však toho nemění.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 15, 5, 'Kdož peněz svých nedává na lichvu, a daru proti nevinnému nebéře. Kdož tyto věci činí, nepohneť se na věky.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 16, 1, 'Zlatý zpěv Davidův. Ostříhej mne, Bože silný, neboť v tebe doufám.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 16, 2, 'Rciž, duše má, Hospodinu: Ty jsi Pán můj, dobrota má nic tobě neprospěje.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 16, 3, 'Ale svatým, kteříž jsou na zemi, a znamenitým, v nichž všecka líbost má.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 16, 4, 'Rozmnožují bolesti své ti, kteříž k cizímu bohu chvátají; neokusím obětí jejich ze krve, aniž vezmu jména jejich ve rty své.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 16, 5, 'Hospodin jest částka dílu mého a kalicha mého; ty zdržuješ los můj.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 16, 6, 'Provazcové padli mi na místech veselých, a dědictví rozkošné dostalo se mi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 16, 7, 'Dobrořečiti budu Hospodinu, kterýž mi radí; nebo i v noci vyučují mne ledví má.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 16, 8, 'Představuji Hospodina před oblíčej svůj vždycky, a kdyžť jest mi po pravici, nikoli se nepohnu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 16, 9, 'Z té příčiny rozveselilo se srdce mé, a zplésala sláva má, ano i tělo mé v bezpečnosti přebývati bude.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 16, 10, 'Nebo nenecháš duše mé v pekle, aniž dopustíš svatému svému viděti porušení.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 16, 11, 'Známou učiníš mi cestu života; sytost hojného veselí jest před oblíčejem tvým, a dokonalé utěšení po pravici tvé až na věky.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 17, 1, 'Modlitba Davidova. Vyslyš, Hospodine, spravedlnost, a pozoruj volání mého; nakloň uší k modlitbě mé, kteráž jest beze vší rtů ošemetnosti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 17, 2, 'Od tváři tvé vyjdiž soud můj, oči tvé nechať patří na upřímnost.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 17, 3, 'Zkusils srdce mého, navštívils je v noci; ohněm jsi mne zpruboval, aniž jsi co shledal; to, což myslím, nepředstihá úst mých.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 17, 4, 'Z strany pak skutků lidských, já podlé slova rtů tvých vystříhal jsem se stezky zhoubce.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 17, 5, 'Zdržuj kroky mé na cestách svých, aby se neuchylovaly nohy mé.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 17, 6, 'Já volám k tobě, nebo vyslýcháš mne, ó Bože silný; nakloň ke mně ucha svého, a slyš řeč mou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 17, 7, 'Prokaž milosrdenství svá, naději majících ochránce před těmi, kteříž povstávají proti pravici tvé.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 17, 8, 'Ostříhej mne jako zřítelnice oka, v stínu křídel svých skrej mne,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 17, 9, 'Od tváři bezbožných těch, kteříž mne hubí, od nepřátel mých úhlavních obkličujících mne,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 17, 10, 'Kteříž tukem svým zarostli, mluví pyšně ústy svými.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 17, 11, 'Jižť i kroky naše předstihají, oči své obrácené mají, aby nás porazili na zem.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 17, 12, 'Každý z nich podoben jest lvu žádostivému loupeže, a lvíčeti sedícímu v skrýši.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 17, 13, 'Povstaniž, Hospodine, předejdi tváři jeho, sehni jej, a vytrhni duši mou od bezbožníka mečem svým,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 17, 14, 'Rukou svou od lidí, ó Hospodine, od lidí světských, jichžto oddíl jest v tomto životě, a jejichž břicho ty z špižírny své naplňuješ. Čímž i synové jejich nasyceni bývají, a ostatků zanechávají maličkým svým.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 17, 15, 'Já pak v spravedlnosti spatřovati budu tvář tvou; nasycen budu obrazem tvým, když procítím.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 1, 'Přednímu zpěváku, služebníka Hospodinova Davida, kterýž mluvil Hospodinu slova písně této v ten den, v němž ho vysvobodil Hospodin z ruky všech nepřátel jeho i z ruky Saulovy, a řekl: Z vnitřnosti srdce miluji tě, Hospodine, sílo má.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 2, 'Hospodin skála má a hrad můj, i vysvoboditel můj, Bůh silný můj, skála má, v němž naději skládám, štít můj a roh spasení mého, mé útočiště.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 3, 'Chvály hodného vzýval jsem Hospodina, a od nepřátel svých byl jsem vyproštěn.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 4, 'Obklíčilyť mne byly bolesti smrti, a proudové nešlechetných předěsili mne.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 5, 'Bylyť jsou mne obklíčily bolesti hrobu, osídla smrti zachvátila mne.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 6, 'V úzkosti své vzýval jsem Hospodina, a k Bohu svému volal jsem, i vyslyšel z chrámu svého hlas můj, a volání mé před oblíčejem jeho přišlo v uši jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 7, 'Tehdy pohnula se a zatřásla země, základové hor pohnuli se, a třásli se pro rozhněvání jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 8, 'Dým vystupoval z chřípí jeho, a oheň zžírající z úst jeho, od něhož se uhlí rozpálilo.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 9, 'Nakloniv nebes, sstoupil, a mrákota byla pod nohami jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 10, 'A sedě na cherubínu, letěl, letěl na peří větrovém.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 11, 'Udělal sobě z temností skrýši, vůkol sebe stánek svůj z temných vod a hustých oblaků.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 12, 'Od blesku před ním oblakové jeho rozehnáni jsou, krupobití i uhlí řeřavé.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 13, 'I hřímal na nebi Hospodin, a Nejvyšší vydal zvuk svůj, i krupobití a uhlí řeřavé.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 14, 'Vystřelil i střely své, a rozptýlil je, a blýskáním častým porazil je.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 15, 'I ukázaly se hlubiny vod, a odkryti jsou základové okršlku pro žehrání tvé, Hospodine, pro dchnutí větru chřípí tvých.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 16, 'Poslav s výsosti, uchopil mne, vytáhl mne z velikých vod.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 17, 'Vytrhl mne od nepřítele mého silného, a od těch, kteříž mne nenáviděli, ačkoli silnější mne byli.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 18, 'Předstihliť jsou mne byli v den trápení mého, ale Hospodin byl mi podpora.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 19, 'Kterýž vyvedl mne na prostranno, vytrhl mne, nebo mne sobě oblíbil.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 20, 'Odplatil mi Hospodin podlé spravedlnosti mé, podlé čistoty rukou mých nahradil mi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 21, 'Nebo jsem ostříhal cest Hospodinových, aniž jsem se bezbožně strhl Boha svého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 22, 'Všickni zajisté soudové jeho jsou přede mnou, a ustanovení jeho neodložil jsem od sebe.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 23, 'Nýbrž upřímě choval jsem se k němu, a vystříhal jsem se nepravosti své.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 24, 'Protož odplatil mi Hospodin podlé spravedlnosti mé, podlé čistoty rukou mých, kteráž jest před očima jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 25, 'Ty, Pane, s milosrdným milosrdně nakládáš, a k člověku upřímému upřímě se máš.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 26, 'K sprostnému sprostně se ukazuješ, a s převráceným převráceně zacházíš.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 27, 'Lid pak ssoužený vysvobozuješ, a oči vysoké snižuješ.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 28, 'Ty zajisté rozsvěcuješ svíci mou; Hospodin Bůh můj osvěcuje temnosti mé.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 29, 'Nebo v tobě proběhl jsem vojsko, a v Bohu svém přeskočil jsem i zed.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 30, 'Boha tohoto silného cesta jest dokonalá, výmluvnosti Hospodinovy jsou přečištěné, onť jest štít všech, kteříž v něho doufají.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 31, 'Nebo kdo jest Bohem kromě Hospodina, a kdo skalou kromě Boha našeho?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 32, 'Ten Bůh silný přepasuje mne udatností, a činí dokonalou cestu mou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 33, 'Činí nohy mé jako laní, a na vysokostech mých postavuje mne.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 34, 'Učí ruce mé boji, tak že lámi i lučiště ocelivé rukama svýma.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 35, 'Tys mi také dodal štítu spasení svého, a pravice tvá podpírala mne, a dobrotivost tvá mne zvelebila.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 36, 'Rozšířil jsi krokům mým místo pode mnou, a nepodvrtly se nohy mé.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 37, 'Honil jsem nepřátely své, a postihl jsem je, aniž jsem se navrátil, až jsem je vyhubil.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 38, 'Tak jsem je zranil, že nemohli povstati, padše pod nohy mé.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 39, 'Ty jsi zajisté mne přepásal udatností k boji, povstávající proti mně sehnul jsi pode mne.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 40, 'Nýbrž dals mi šíji nepřátel mých, abych ty, kteříž mne nenáviděli, vyplénil.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 41, 'Volaliť jsou, ale nebylo spomocníka k Hospodinu, ale nevyslyšel jich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 42, 'I potřel jsem je jako prach u povětří, jako bláto na ulicích rozšlapal jsem je.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 43, 'Ty jsi mne vyprostil z různic lidu, a postavils mne v hlavu národům; lid, kteréhož jsem neznal, sloužil mi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 44, 'Jakž jen zaslechli, uposlechli mne, cizozemci lhali mi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 45, 'Cizozemci svadli a třásli se v ohradách svých.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 46, 'Živť jest Hospodin, a požehnaná skála má; protož buď vyvyšován Bůh spasení mého,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 47, 'Bůh silný, kterýž mi pomsty poroučí, a podmaňuje mi lidi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 48, 'Ty jsi vysvoboditel můj z moci nepřátel mých, také i nad povstávající proti mně vyvýšils mne, a od člověka ukrutného vyprostils mne.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 49, 'A protož chváliti tě budu mezi národy, ó Hospodine, a jménu tvému žalmy prozpěvovati,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 50, 'Kterýž tak důstojně vysvobozuješ krále svého, a činíš milosrdenství pomazanému svému Davidovi, i semeni jeho až na věky.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 19, 1, 'Přednímu z kantorů, žalm Davidův. Nebesa vypravují slávu Boha silného, a dílo rukou jeho obloha zvěstuje.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 19, 2, 'Den po dni vynáší řeč, a noc po noci ukazuje umění.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 19, 3, 'Neníť řeči ani slov, kdež by nemohl slyšán býti hlas jejich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 19, 4, 'Po vší zemi rozchází se zpráva jejich, a až do končin okršlku slova jich, slunci pak rozbil stánek na nich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 19, 5, 'Kteréž jako ženich vychází z pokoje svého, veselí se jako udatný rek, cestou běžeti maje.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 19, 6, 'Od končin nebes východ jeho, a obcházení jeho až zase do končin jejich, a ničeho není, což by se ukryti mohlo před horkostí jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 19, 7, 'Zákon Hospodinův jest dokonalý, očerstvující duši, Hospodinovo svědectví pravé, moudrost dávající neumělým.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 19, 8, 'Rozkazové Hospodinovi přímí, obveselující srdce, přikázaní Hospodinovo čisté, osvěcující oči.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 19, 9, 'Bázeň Hospodinova čistá, zůstávající na věky, soudové Hospodinovi praví, a k tomu i spravedliví.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 19, 10, 'Mnohem žádostivější jsou než zlato, a než mnoho ryzího zlata, sladší než med a stred z plástů.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 19, 11, 'Služebník tvůj zajisté jimi osvěcován bývá, a kdož jich ostříhá, užitek hojný má.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 19, 12, 'Ale poblouzením kdo vyrozumí? Protož i od tajných očisť mne.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 19, 13, 'I od zúmyslných zdržuj služebníka svého, aby nade mnou nepanovali, a tehdyť dokonalý budu, a očištěný od přestoupení velikého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 19, 14, 'Ó ať jsou slova úst mých tobě příjemná, i přemyšlování srdce mého před tebou, Hospodine skálo má, a vykupiteli můj.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 20, 1, 'Přednímu zpěváku, žalm Davidův. Vyslyšiž tě Hospodin v den ssoužení, k zvýšení tě přiveď jméno Boha Jákobova.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 20, 2, 'Sešliž tobě pomoc z svatyně, a z Siona utvrzuj tě.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 20, 3, 'Rozpomeniž se na všecky oběti tvé, a zápaly tvé v popel obrať. Sélah.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 20, 4, 'Dejž tobě vše podlé srdce tvého, a všelikou radu tvou vyplň.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 20, 5, 'I budeme prozpěvovati o spasení tvém, a ve jménu Boha našeho korouhve vyzdvihneme; naplniž Hospodin všecky prosby tvé.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 20, 6, 'Nyníť jsme poznali, že Hospodin zachoval svého pomazaného, a že jej vyslyšel s nebe svatého svého; nebo v jeho přesilné pravici jest spasení.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 20, 7, 'Tito v vozích, jiní v koních doufají, ale my jméno Hospodina Boha našeho sobě připomínáme.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 20, 8, 'A protož oni sehnuti jsou, a padli, ale my povstali jsme, a zmužile stojíme.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 20, 9, 'Hospodine, zachovávejž nás, i král ať slyší nás, když k němu volati budeme.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 21, 1, 'Přednímu z kantorů, žalm Davidův. Hospodine, v síle tvé raduje se král, a v spasení tvém veselí se přenáramně.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 21, 2, 'Žádost srdce jeho dal jsi jemu, a prosbě rtů jeho neodepřel jsi. Sélah.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 21, 3, 'Předšel jsi jej zajisté hojným požehnáním, vstavil jsi na hlavu jeho korunu z ryzího zlata.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 21, 4, 'Života požádal od tebe, a dal jsi mu prodlení dnů na věky věků.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 21, 5, 'Veliká jest sláva jeho v spasení tvém, důstojností a krásou přioděl jsi jej.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 21, 6, 'Nebo jsi jej vystavil za příklad hojného požehnání až na věky, rozveselil jsi jej radostí oblíčeje svého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 21, 7, 'A poněvadž král doufá v Hospodina, a v milosrdenství Nejvyššího, nepohneť se.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 21, 8, 'Najdeť ruka tvá všecky nepřátely své, dosáhne pravice tvá těch, kteříž tě nenávidí.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 21, 9, 'Uvržeš je jako do peci ohnivé v čas rozhněvání svého; Hospodin v prchlivosti své sehltí je, a oheň sžíře je.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 21, 10, 'Plémě jejich z země vyhladíš, a símě jejich z synů lidských,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 21, 11, 'Nebo jsou proti tobě ukládali zlost, myslili na nešlechetnost, ač ji dovesti nemohli.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 21, 12, 'Protož je vystavíš za cíl, na tětiva svá přikládati budeš proti tváři jejich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 21, 13, 'Zjeviž se, ó Hospodine, v síle své, a budemeť zpívati a oslavovati udatnost tvou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 1, 'Přednímu zpěváku k času jitřnímu, žalm Davidův.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 2, 'Bože můj, Bože můj, pročež jsi mne opustil? Vzdálils se od spasení mého a od slov naříkání mého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 3, 'Bože můj, přes celý den volám, a neslyšíš, i v noci, a nemohu se utajiti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 4, 'Ty zajisté jsi svatý, zůstávající vždycky k veliké chvále Izraelovi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 5, 'V toběť doufali otcové naši, doufali, a vysvobozovals je.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 6, 'K tobě volávali, a spomáhals jim; v tobě doufali, a nebývali zahanbeni.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 7, 'Já pak červ jsem, a ne člověk, útržka lidská a povrhel vůbec.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 8, 'Všickni, kteříž mne vidí, posmívají se mi, ošklebují se, a hlavami potřásají, říkajíce:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 9, 'Spustiltě se na Hospodina, nechť ho vysvobodí; nechať jej vytrhne, poněvadž se mu v něm zalíbilo.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 10, 'Ješto ty jsi, kterýž jsi mne vyvedl z života, ustaviv mne v doufání při prsích matky mé.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 11, 'Na tebeť jsem uvržen od narození svého, od života matky mé Bůh můj ty jsi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 12, 'Nevzdalujž se ode mne, nebo ssoužení blízké jest, a nemám spomocníka.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 13, 'Obkličujíť mne býkové mnozí, silní volové z Bázan obstupují mne.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 14, 'Otvírají na mne ústa svá, jako lev rozsapávající a řvoucí.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 15, 'Jako voda rozplynul jsem se, a rozstoupily se všecky kosti mé, a srdce mé jako vosk rozpustilo se u prostřed vnitřností mých.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 16, 'Vyprahla jako střepina síla má, a jazyk můj přilnul k dásním mým, anobrž v prachu smrti položils mne.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 17, 'Nebo psi obskočili mne, rota zlostníků oblehla mne, zprobijeli ruce mé i nohy mé.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 18, 'Mohl bych sčísti všecky kosti své, oni pak hledí na mne, a dívají se mi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 19, 'Dělí mezi sebou roucha má, a o můj oděv mecí los.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 20, 'Ale ty, Hospodine, nevzdalujž se, sílo má, přispěj k spomožení mému.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 21, 'Vychvať od meče duši mou, a z moci psů jedinkou mou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 22, 'Zachovej mne od úst lva, a od rohů jednorožcových vyprosť mne.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 23, 'I budu vypravovati bratřím svým o jménu tvém, u prostřed shromáždění chváliti tě budu, řka:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 24, 'Kteříž se bojíte Hospodina, chvalte jej, všecko símě Jákobovo ctěte jej, a boj se ho všecka rodino Izraelova.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 25, 'Nebo nepohrdá, ani se odvrací od trápení ztrápeného, aniž skrývá tváři své od něho, nýbrž když k němu volá, vyslýchá jej.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 26, 'O tobě chvála má v shromáždění velikém, sliby své plniti budu před těmi, kteříž se bojí tebe.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 27, 'Jísti budou tiší a nasyceni budou, chváliti budou Hospodina ti, kteříž ho hledají, živo bude srdce vaše na věky.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 28, 'Rozpomenou a obrátí se k Hospodinu všecky končiny země, a skláněti se budou před ním všecky čeledi národů.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 29, 'Nebo Hospodinovo jest království, a onť panuje nad národy.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 30, 'Jísti budou a skláněti se před ním všickni tuční země, jemu se klaněti budou všickni sstupující do prachu, a kteříž duše své nemohou při životu zachovati.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 31, 'Símě jejich sloužiti mu bude, a přičteno bude ku Pánu v každém věku. Přijdouť, a lidu, kterýž z nich vyjde, vypravovati budou spravedlnost jeho; nebo ji skutkem vykonal.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 23, 1, 'Žalm Davidův. Hospodin jest můj pastýř, nebudu míti nedostatku.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 23, 2, 'Na pastvách zelených pase mne, k vodám tichým mne přivodí.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 23, 3, 'Duši mou očerstvuje, vodí mne po stezkách spravedlnosti pro jméno své.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 23, 4, 'Byť mi se dostalo jíti přes údolí stínu smrti, nebuduť se báti zlého, nebo ty se mnou jsi; prut tvůj a hůl tvá, toť mne potěšuje.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 23, 5, 'Strojíš stůl před oblíčejem mým naproti mým nepřátelům, pomazuješ olejem hlavy mé, kalich můj naléváš, až oplývá.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 23, 6, 'Nadto i dobrota a milosrdenství následovati mne budou po všecky dny života mého, a přebývati budu v domě Hospodinově za dlouhé časy.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 24, 1, 'Žalm Davidův. Hospodinova jest země, a plnost její, okršlek země, i ti, kteříž obývají na něm.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 24, 2, 'Nebo on ji na moři založil, a na řekách upevnil ji.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 24, 3, 'Kdo vstoupí na horu Hospodinovu? A kdo stane na místě svatém jeho?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 24, 4, 'Ten, kdož jest rukou nevinných, a srdce čistého, kdož neobrací duše své k marnosti, a nepřisahá lstivě.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 24, 5, 'Ten přijme požehnání od Hospodina, a spravedlnost od Boha spasitele svého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 24, 6, 'Toť jest národ hledajících jeho, hledajících tváři tvé, ó Bože Jákobův. Sélah.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 24, 7, 'Pozdvihnětež, ó brány, svrchků svých, pozdvihnětež se vrata věčná, aby vjíti mohl král slávy.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 24, 8, 'Kdož jest to ten král slávy? Hospodin silný a mocný, Hospodin udatný válečník.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 24, 9, 'Pozdvihnětež, ó brány, svrchků svých, pozdvihněte se vrata věčná, aby vjíti mohl král slávy.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 24, 10, 'Kdož jest to ten král slávy? Hospodin zástupů, onť jest král slávy. Sélah.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 1, 'Žalm Davidův. K toběť, Hospodine, duše své pozdvihuji.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 2, 'Bože můj, v toběť naději skládám, nechť nejsem zahanben, aby se neradovali nepřátelé moji nade mnou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 3, 'A takť i všickni, kteříž na tě očekávají, zahanbeni nebudou; zahanbeni budou, kteříž se převráceně mají bez příčiny.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 4, 'Cesty své, Hospodine, uveď mi v známost, a stezkám svým vyuč mne.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 5, 'Dejž, ať chodím v pravdě tvé, a poučuj mne; nebo ty jsi Bůh spasitel můj, na tebeť očekávám dne každého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 6, 'Rozpomeň se na slitování svá, Hospodine, a na milosrdenství svá, kteráž jsou od věků.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 7, 'Hříchů mladosti mé a přestoupení mých nezpomínej, ale podlé milosrdenství svého pamětliv buď na mne pro dobrotu svou, Hospodine.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 8, 'Dobrý a přímý jest Hospodin, a protož vyučuje hříšníky cestě své.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 9, 'Působí to, aby tiší chodili v soudu, a vyučuje tiché cestě své.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 10, 'Všecky stezky Hospodinovy jsou milosrdenství a pravda těm, kteříž ostříhají smlouvy jeho a svědectví jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 11, 'Pro jméno své, Hospodine, odpusť nepravost mou, neboť jest veliká.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 12, 'Který jest člověk, ješto se bojí Hospodina, jehož vyučuje, kterou by cestu vyvoliti měl?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 13, 'Duše jeho v dobrém přebývati bude, a símě jeho dědičně obdrží zemi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 14, 'Tajemství Hospodinovo zjevné jest těm, kteříž se jeho bojí, a v známost jim uvodí smlouvu svou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 15, 'Oči mé vždycky patří k Hospodinu, on zajisté z leči vyvodí nohy mé.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 16, 'Popatřiž na mne, a smiluj se nade mnou, neboť jsem opuštěný a strápený.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 17, 'Ssoužení srdce mého rozmnožují se, z úzkostí mých vyveď mne.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 18, 'Viz trápení mé a bídu mou, a odpusť všecky hříchy mé.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 19, 'Viz nepřátely mé, jak mnozí jsou, a nenávistí nešlechetnou nenávidí mne.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 20, 'Ostříhej duše mé, a vytrhni mne, ať nejsem zahanben, neboť v tebe doufám.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 21, 'Sprostnost a upřímnost nechať mne ostříhají, nebo na tě očekávám.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 22, 'Vykup, ó Bože, Izraele ze všelijakých úzkostí jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 26, 1, 'Žalm Davidův. Suď mne, Hospodine, nebo já v upřímnosti své chodím, a v tě Hospodina doufám, nepohnuť se.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 26, 2, 'Zprubujž mne, Hospodine, a zkus mne, přepal ledví má i srdce mé.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 26, 3, 'Milosrdenství tvé zajisté před očima mýma jest, a chodím stále v pravdě tvé.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 26, 4, 'S lidmi marnými nesedám, a s pokrytci v spolek nevcházím.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 26, 5, 'V nenávisti mám shromáždění zlostníků, a s bezbožnými se neusazuji.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 26, 6, 'Umývám v nevinnosti ruce své, postavuji se při oltáři tvém, Hospodine,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 26, 7, 'Abych tě hlasitě chválil, a vypravoval všecky divné skutky tvé.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 26, 8, 'Hospodine, jáť miluji obydlí domu tvého, a místo příbytku slávy tvé.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 26, 9, 'Nezahrnujž s hříšnými duše mé, a s lidmi vražedlnými života mého,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 26, 10, 'V jejichž rukou jest nešlechetnost, a pravice jejich vzátků plná.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 26, 11, 'Já pak v upřímnosti své chodím, vykupiž mne, a smiluj se nade mnou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 26, 12, 'Noha má stojí na rovině, v shromážděních svatých dobrořečiti budu Hospodinu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 27, 1, 'Davidův. Hospodin světlo mé a spasení mé, kohož se budu báti? Hospodin síla života mého, kohož se budu strašiti?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 27, 2, 'Útok učinivše na mne zlostníci, k sežrání těla mého, protivníci moji a nepřátelé moji, sami se potkli a padli.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 27, 3, 'Protož byť i stany své proti mně rozbili, nebude se lekati srdce mé; byť se pozdvihla proti mně i válka, na toť se já spouštím.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 27, 4, 'Jedné věci žádal jsem od Hospodina, téť vždy hledati budu: Abych přebýval v domě Hospodinově po všecky dny života svého, a spatřoval okrasu Hospodinovu, a zpytoval v chrámě jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 27, 5, 'Nebo tu mne ukryje v stánku svém, v den zlý schová mne v skrýši stanu svého, a na skálu vyzdvihne mne.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 27, 6, 'A tak vyvýšena bude hlava má nad nepřátely mými, kteříž mne obklíčili; i budu obětovati v stánku jeho oběti plésání, prozpěvovati a chvály vzdávati budu Hospodinu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 27, 7, 'Slyš mne, Hospodine, hlasem volajícího, a smiluj se nade mnou, i vyslyš mne.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 27, 8, 'O tobě přemýšlí srdce mé, že velíš, řka: Hledejte tváři mé, a protož tváři tvé, Hospodine, hledati budu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 27, 9, 'Neskrývejž tváři své přede mnou, aniž zamítej v hněvě služebníka svého; spomožení mé býval jsi, neopouštěj mne, aniž se mne zhošťuj, Bože spasení mého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 27, 10, 'Ačkoli otec můj a matka má mne opustili, Hospodin však mne k sobě přivine.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 27, 11, 'Vyuč mne, Hospodine, cestě své, a veď mne po stezce přímé pro ty, jenž mne střehou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 27, 12, 'Nevydávejž mne líbosti protivníků mých, neboť by ostáli proti mně svědkové lživí, i ten, jenž dýše ukrutností.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 27, 13, 'Bychť nevěřil, že užívati budu dobroty Hospodinovy v zemi živých, nikoli bych neostál.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 27, 14, 'Očekávejž na Hospodina, posilň se, a onť posilní srdce tvého; protož očekávej na Hospodina.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 28, 1, 'Davidův. K toběť, Hospodine, volám, skálo má, neodmlčujž mi se, abych, neozval-li bys mi se, nebyl podobný učiněn těm, kteříž sstupují do hrobu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 28, 2, 'Vyslýchej hlas pokorných modliteb mých, kdyžkoli k tobě volám, když pozdvihuji rukou svých k svatyni svatosti tvé.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 28, 3, 'Nezahrnuj mne s bezbožníky, a s těmi, kteříž páší nepravost, kteříž mluvívají pokoj s bližními svými, ale převrácenost jest v srdcích jejich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 28, 4, 'Dejž jim podlé skutků jejich, a podlé zlosti nešlechetností jejich; podlé práce rukou jejich dej jim, zaplať jim zaslouženou mzdu jejich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 28, 5, 'Nebo nechtí mysli přiložiti k skutkům Hospodinovým, a k dílu rukou jeho; protož podvrátí je, a nebude jich vzdělávati.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 28, 6, 'Požehnaný Hospodin, nebo vyslyšel hlas pokorných modliteb mých.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 28, 7, 'Hospodin jest síla má a štít můj, v němť jest složilo naději srdce mé, a dána mi pomoc; protož se veselí srdce mé, a písničkou svou oslavovati jej budu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 28, 8, 'Hospodin jest síla svých, a síla hojného spasení pomazaného svého on jest.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 28, 9, 'Spas lid svůj, Hospodine, a požehnej dědictví svému, a pas je, i vyvyš je až na věky.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 29, 1, 'Žalm Davidův. Vzdejte Hospodinu, velikomocní, vzdejte Hospodinu čest a sílu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 29, 2, 'Vzdejte Hospodinu slávu jména jeho, sklánějte se Hospodinu v ozdobě svatosti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 29, 3, 'Hlas Hospodinův nad vodami, Bůh silný slávy hřímání vzbuzuje, Hospodin to činí nad vodami mnohými.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 29, 4, 'Hlas Hospodinův přichází s mocí, hlas Hospodinův s velebností.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 29, 5, 'Hlas Hospodinův láme cedry, rozrážíť Hospodin cedry Libánské.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 29, 6, 'A činí, aby skákali jako telata, Libán a Sirion, jako mladý jednorožec.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 29, 7, 'Hlas Hospodinův rozkřesává plamen ohně.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 29, 8, 'Hlas Hospodinův k bolesti přivodí poušť, k bolesti přivodí Hospodin poušť Kádes.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 29, 9, 'Hlas Hospodinův to činí, že laně plodu pozbývají, obnažuje i lesy, ale v chrámě svém všecku svou slávu vypravuje.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 29, 10, 'Hospodin nad potopou seděl, a budeť seděti Hospodin, jsa králem i na věky.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 29, 11, 'Hospodin silou lid svůj daří, Hospodin požehná lidu svému v pokoji.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 30, 1, 'Žalm písně, při posvěcení domu Davidova. Vyvyšovati tě budu, Hospodine, nebo jsi vyvýšil mne, aniž jsi obradoval nepřátel mých nade mnou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 30, 2, 'Hospodine Bože můj, k toběť jsem volal, a uzdravil jsi mne.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 30, 3, 'Hospodine, vyvedl jsi z pekla duši mou, obživil jsi mne, abych s jinými nesstoupil do hrobu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 30, 4, 'Žalmy zpívejte Hospodinu svatí jeho, a oslavujte památku svatosti jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 30, 5, 'Nebo na kratičko trvá v hněvě svém, všecken pak život v dobré líbeznosti své; z večera potrvá pláč, ale z jitra navrátí se prozpěvování.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 30, 6, 'I jáť jsem řekl, když mi se šťastně vedlo: Nepohnu se na věky.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 30, 7, 'Nebo ty, Hospodine, podlé dobře líbezné vůle své silou upevnil jsi horu mou, ale jakž jsi skryl tvář svou, byl jsem přestrašen.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 30, 8, 'I volal jsem k tobě, Hospodine, Pánu pokorně jsem se modlil, řka:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 30, 9, 'Jaký bude užitek z mé krve, jestliže sstoupím do jámy? Zdaliž tě prach oslavovati bude? Zdaliž zvěstovati bude pravdu tvou?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 30, 10, 'Vyslyšiž, Hospodine, a smiluj se nade mnou, Hospodine, budiž můj spomocník.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 30, 11, 'I obrátil jsi mi pláč můj v plésání, odvázal jsi pytel můj, a přepásals mne veselím.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 30, 12, 'Protož tobě žalmy zpívati bude jazyk můj, a nebude mlčeti. Hospodine Bože můj, na věky tě oslavovati budu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 1, 'Přednímu zpěváku, žalm Davidův. V tebe, Hospodine, doufám, nedejž mi zahanbenu býti na věky, pro spravedlnost svou vysvoboď mne.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 2, 'Nakloň ke mně ucha svého, rychle vytrhni mne; budiž mi pevnou skalou a domem ohraženým, abys mne zachoval.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 3, 'Nebo skála má a hrad můj ty jsi, protož pro jméno své veď i doveď mne.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 4, 'Vyveď mne z leči, kterouž polékli na mne; nebo síla má ty jsi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 5, 'V ruce tvé poroučím ducha svého, nebo jsi mne vykoupil, Hospodine, Bože silný a věrný.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 6, 'Nenávidím těch, kteříž následují pouhých marností, nebo já v Hospodinu naději skládám.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 7, 'Plésati a radovati se budu v milosrdenství tvém, že jsi vzezřel na mé trápení, a poznal jsi v ssoužení duši mou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 8, 'Aniž jsi mne zavřel v ruce nepřítele, ale postavil jsi na širokosti nohy mé.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 9, 'Smiluj se nade mnou, Hospodine, nebo jsem ssoužen, tak že usvadla zámutkem tvář má, duše má, i život můj.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 10, 'Žalostí zajisté zhynulo zdraví mé, a léta má od úpění, zemdlena bídou mou síla má, a kosti mé vyprahly.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 11, 'U všech nepřátel svých jsem v pohanění, a nejvíce u sousedů, známým pak svým jsem strašidlem; kteříž mne vídají vně, utíkají přede mnou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 12, 'Vyšel jsem z paměti tak, jako mrtvý, učiněn jsem jako nádoba rozražená.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 13, 'Nebo slýchám utrhání mnohých, strach odevšad, když se proti mně spolu puntují, lstivě přemýšlejíce, jak by odjali duši mou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 14, 'Ale já v tobě naději skládám, Hospodine; řekl jsem: Bůh můj jsi ty.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 15, 'V rukou tvých jsou časové moji, vytrhni mne z ruky nepřátel mých a těch, kteříž mne stihají.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 16, 'Osvěť tvář svou nad služebníkem svým, zachovej mne pro milosrdenství své.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 17, 'Hospodine, ať nejsem zahanben, nebo jsem tě vzýval; nechať jsou zahanbeni bezbožníci, a skroceni v pekle.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 18, 'Oněmějte rtové lživí, kteříž mluví proti spravedlivému tvrdě, pyšně a s potupou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 19, 'Ó jak veliká jest dobrotivost tvá, kterouž jsi odložil těm, jenž se bojí tebe, a kterouž jsi činíval doufajícím v tebe před syny lidskými.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 20, 'Ty je skrýváš v skrýši oblíčeje svého před vysokomyslností člověka, skrýváš je jako v stanu před jazyky svárlivými.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 21, 'Požehnaný buď Hospodin, nebo prokázal ke mně divné milosrdenství své jako v městě ohraženém.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 22, 'Já zajisté když jsem pospíchal, řekl jsem: Zavrženť jsem od očí tvých, ale ty jsi vyslyšel hlas pokorných modliteb mých, když jsem k tobě volal.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 23, 'Milujtež Hospodina všickni svatí jeho, neboť ostříhá věřících Hospodin, a též odplací vrchovatě tomu, kdož pýchu provodí.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 24, 'Zmužile sobě čiňte, (a posilní Bůh srdce vašeho), všickni, kteříž naději máte v Hospodinu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 32, 1, 'Žalm Davidův vyučující. Blahoslavený jest ten, jemuž odpuštěno přestoupení, a jehož hřích přikryt jest.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 32, 2, 'Blahoslavený člověk, jemuž nepočítá Hospodin nepravosti, a v jehož duchu lsti není.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 32, 3, 'Já když jsem mlčel, prahly kosti mé v úpění mém každého dne.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 32, 4, 'Nebo dnem i nocí obtížena byla nade mnou ruka tvá, tak že přirozená vlhkost má obrátila se v sucho letní. Sélah.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 32, 5, 'Protož hřích svůj oznámil jsem tobě, a nepravosti své jsem neukryl. Řekl jsem: Vyznám na sebe Hospodinu přestoupení svá, a ty jsi odpustil nepravost hříchu mého. Sélah.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 32, 6, 'Za to se tobě bude modliti každý svatý, v času příhodném k nalezení tebe; pročež vody mnohé v rozvodnění k němu nedosáhnou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 32, 7, 'Ty jsi skrýše má, od ssoužení zachováš mne, a plésáním vítězným obdaříš. Sélah.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 32, 8, 'Já tobě k srozumění posloužím, a vyučím tě cestě, po níž bys choditi měl; dámť radu, oči své na tě obrátě.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 32, 9, 'Nebývejte jako kůň a jako mezek, kteříž rozumu nemají, jejichž ústa uzdou a udidly sevříti musíš, aby tobě neškodili.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 32, 10, 'Mnohé bolesti jsou bezbožníka, ale toho, jenž naději skládá v Hospodinu, milosrdenství obklíčí.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 32, 11, 'Radujte se v Hospodinu, a plésejte spravedliví, a prozpěvujte všickni srdce upřímého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 1, 'Veselte se spravedliví v Hospodinu, na upříméť přísluší chválení.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 2, 'Oslavujte Hospodina na harfě, na loutně, a na nástroji o desíti strunách, žalmy zpívejte jemu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 3, 'Zpívejte jemu píseň novou, a huďte dobře a zvučně.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 4, 'Nebo pravé jest slovo Hospodinovo, a všeliké dílo jeho stálé.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 5, 'Milujeť spravedlnost a soud, milosrdenství Hospodinova plná jest země.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 6, 'Slovem Hospodinovým nebesa učiněna jsou, a duchem úst jeho všecko vojsko jejich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 7, 'Onť shrnul jako na hromadu vody mořské, a složil na poklad propasti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 8, 'Boj se Hospodina všecka země, děstež se před ním všickni obyvatelé okršlku zemského.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 9, 'Nebo on řekl, a stalo se, on rozkázal, a postavilo se.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 10, 'Hospodin ruší rady národů, a v nic obrací přemyšlování lidská.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 11, 'Rada pak Hospodinova na věky trvá, myšlení srdce jeho od národu do pronárodu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 12, 'Blahoslavený národ, kteréhož Hospodin jest Bohem jeho, lid ten, kterýž sobě on vyvolil za dědictví.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 13, 'Hospodin patře s nebe, vidí všecky syny lidské,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 14, 'Z příbytku trůnu svého dohlédá ke všechněm obyvatelům země.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 15, 'Ten, kterýž stvořil srdce jednoho každého z nich, spatřuje všecky skutky jejich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 16, 'Nebývá král zachován skrze mnohý zástup, ani udatný rek vysvobozen skrze velikou moc svou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 17, 'Oklamavatelný jest kůň k spomožení, aniž ve množství síly své vytrhuje.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 18, 'Aj, oči Hospodinovy patří na ty, kteříž se ho bojí, a na ty, kteříž očekávají milosrdenství jeho,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 19, 'Aby vyprostil od smrti duše jejich, a živil je v čas hladu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 20, 'Duše naše očekává na Hospodina, on jest spomožení naše, a pavéza naše.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 21, 'V něm zajisté rozveselí se srdce naše, nebo ve jménu jeho svatém naději skládáme.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 22, 'Budiž milosrdenství tvé nad námi, Hospodine, jakož naději máme v tobě.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 1, 'Davidův, když proměnil oblíčej svůj před Abimelechem; pročež jsa od něho vyhnán, odšel. Dobrořečiti budu Hospodinu každého času, vždycky chvála jeho v ústech mých.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 2, 'V Hospodinu chlubiti se bude duše má, což uslyšíc tiší, budou se veseliti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 3, 'Zvelebujtež se mnou Hospodina, a jméno jeho společně vyvyšujme.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 4, 'Hledal jsem Hospodina, a vyslyšel mne, a ze všech přístrachů mých vytrhl mne.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 5, 'Pročež k němu patřiti budou, a sbíhati se, a nebudou zahanbeny tváři jejich, ale řkou:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 6, 'Tento chudý volal a Hospodin vyslyšel, i ze všech úzkostí jeho vysvobodil jej.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 7, 'Vojensky se klade anděl Hospodinův okolo těch, kteříž se ho bojí, a zastává jich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 8, 'Okuste a vizte, jak dobrý jest Hospodin. Blahoslavený člověk, kterýž doufá v něho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 9, 'Bojtež se Hospodina svatí jeho; neboť nemívají nedostatku ti, kdož se ho bojí.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 10, 'Lvíčátka nedostatek a hlad trpívají, ale ti, kteříž hledají Hospodina, nemívají nedostatku ve všem dobrém.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 11, 'Poďtež, dítky, poslouchejte mne, bázni Hospodinově vyučovati vás budu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 12, 'Který člověk žádostiv jest života, a miluje dny, aby užíval dobrých věcí?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 13, 'Zdržuj jazyk svůj od zlého, a rty své od mluvení lsti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 14, 'Odstup od zlého, a čiň dobré, hledej pokoje, a stíhej jej.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 15, 'Oči Hospodinovy obrácené jsou k spravedlivým, a uši jeho k volání jejich:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 16, 'Ale zůřivý oblíčej Hospodinův proti těm, kteříž páší zlé věci, aby vyplénil z země památku jejich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 17, 'Volají-li spravedliví, Hospodin vyslýchá, a ze všech jejich úzkostí je vytrhuje.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 18, 'Nebo blízko jest Hospodin těm, kteříž jsou srdce skroušeného, a potřeným v duchu spomáhá.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 19, 'Mnohé úzkosti jsou spravedlivého, ale Hospodin ze všech jej vytrhuje.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 20, 'Onť ostříhá všech kostí jeho, žádná z nich nebývá zlámána.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 21, 'Bezbožníka zahubí zlost, a ti, kteříž nenávidí spravedlivého, zkaženi budou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 22, 'Služebníků pak svých duše vykoupí Hospodin, a nebudou zkaženi, kteříž doufají v něho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 1, 'Žalm Davidův. Suď se, Hospodine, s těmi, kteříž se se mnou soudí; bojuj proti těm, kteříž proti mně bojují.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 2, 'Pochyť štít a pavézu, a povstaň mi ku pomoci.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 3, 'Vezmi i kopí, a vyjdi vstříc těm, kteříž táhnou proti mně. Rciž duši mé: Spasení tvé jáť jsem.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 4, 'Nechať se zahanbí a zapýří ti, kteříž hledají duše mé; zpět ať jsou obráceni a zahanbeni ti, kteříž mi zlé obmýšlejí.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 5, 'Ať jsou jako plevy před větrem, a anděl Hospodinův rozptylujž je.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 6, 'Cesta jejich budiž temná a plzká, a anděl Hospodinův stihej je.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 7, 'Nebo jsou bez příčiny polékli v jámě osídlo své, bez příčiny vykopali jámu duši mé.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 8, 'Připadniž na ně setření, jehož se nenadáli, a sít jejich, kterouž ukryli, ať je uloví; s hřmotem ať do ní vpadnou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 9, 'Duše má pak ať se veselí v Hospodinu, a ať raduje se v spasení jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 10, 'A tuť všecky kosti mé řeknou: Hospodine, kdo jest podobný tobě, ješto vytrhuješ ztrápeného z moci toho, kterýž nad něj silnější jest, tolikéž chudého a nuzného od toho, kterýž ho násilně loupí?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 11, 'Povstávají svědkové lživí, a na to, o čemž nevím, dotazují se mne.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 12, 'Zlým za dobré mi se odplacují, duše mé zbaviti mne chtíce,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 13, 'Ježto já v nemoci jejich pytlem jsem se přiodíval, duši svou postem trápil, a sám u sebe za ně často se modlil.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 14, 'Jako k příteli, jako k bratru vlastnímu jsem chodíval; jakožto ten, kterýž po matce kvílí, smutek nesa, tak jsem se ponižoval.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 15, 'Ale oni z mého zlého radovali se, a rotili se; shromažďovali se proti mně i ti nejnevážnější, o čemž jsem nevěděl; utrhali mi, a nemlčeli.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 16, 'S pokrytci, posměvači, fatkáři škřipěli na mne zuby svými.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 17, 'Pane, dlouho-liž se dívati budeš? Vytrhni duši mou od zhouby jejich, od lvů jedinkou mou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 18, 'I budu tě oslavovati v shromáždění velikém, ve množství lidu tebe chváliti budu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 19, 'Nechažť se nade mnou neradují ti, kteříž bezprávně ke mně se nepřátelsky mají; ti, kteříž mne nenávidí bez příčiny, ať nemhourají očima.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 20, 'Neboť nemluví ku pokoji, ale proti pokojným na zemi slova lstivá vymýšlejí.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 21, 'Anobrž rozdírají proti mně ústa svá, a říkají: Hahá, hahá, jižť vidí oko naše.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 22, 'Vidíš ty to, Hospodine, neodmlčujž se, Pane, nevzdalujž se ode mne.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 23, 'Probudiž se a prociť k soudu mému, Bože můj a Pane můj, k obhájení pře mé.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 24, 'Suď mne podlé spravedlnosti své, Hospodine Bože můj, ať se neradují nade mnou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 25, 'Ať neříkají v srdci svém: Měhoděk duši naší; ať neříkají: Sehltili jsme jej.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 26, 'Ale ať se zahanbí a zapýří všickni radující se mému zlému, v stud a hanbu ať jsou oblečeni ti, kteříž se zpínají proti mně.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 27, 'Ti pak, kteříž mi přejí mé spravedlnosti, ať plésají, a radují se, a ať říkají vždycky: Veleslaven budiž Hospodin, kterýž přeje pokoje služebníku svému.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 28, 'I můj jazyk ohlašovati bude spravedlnost tvou, a na každý den chválu tvou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 36, 1, 'Přednímu z kantorů, služebníka Hospodinova Davida. Převrácenost bezbožníka pojišťuje u vnitřnosti srdce mého, že není žádné bázně Boží před očima jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 36, 2, 'Nebo mu ona pochlebuje před očima jeho, aby vykonal nepravost svou až do zošklivení.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 36, 3, 'Slova úst jeho jsou nepravá a lstivá, přestal srozumívati, aby dobře činil.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 36, 4, 'Nepravost smýšlí i na ložci svém, ustavuje se na cestě nedobré, zlého se nevaruje.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 36, 5, 'Hospodine, až do nebes milosrdenství tvé, pravda tvá až do nejvyšších oblaků.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 36, 6, 'Spravedlnost tvá jako nejvyšší hory, soudové tvoji jako hlubokost nesmírná; lidi i hovada sám zachováváš, Hospodine.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 36, 7, 'Jak převelmi drahé jest milosrdenství tvé, Bože, a protož synové lidští v stínu křídel tvých doufají.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 36, 8, 'Tučností domu tvého rozvlažováni bývají, a potokem rozkoší svých napájíš je.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 36, 9, 'Nebo u tebe jest studnice života, a v světle tvém světlo vidíme.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 36, 10, 'Rozprostři milosrdenství své na ty, kteříž tebe znají, a spravedlnost tvou na upřímé srdcem.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 36, 11, 'Nechažť nedotírá na mne noha pyšných, a ruka bezbožníků ať mne nezavozuje.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 36, 12, 'Tam, kdež padají činitelé nepravosti, poraženi bývají, a nemohou povstati.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 1, 'Žalm Davidův. Nehněvej se příčinou zlostníků, nechtěj záviděti těm, kteříž páší nepravost.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 2, 'Nebo jako tráva v náhle podťati budou, a jako zelená bylina uvadnou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 3, 'Doufej v Hospodina, a čiň dobré, přebývej na zemi a živ se spravedlivě.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 4, 'Těš se v Hospodinu, a dá tobě žádosti srdce tvého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 5, 'Uval na Hospodina cestu svou, a slož v něm naději, onť zajisté všecko spraví.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 6, 'A vyvedeť spravedlnost tvou jako světlo, a nevinu tvou jako poledne.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 7, 'Mlčelivě se měj k Hospodinu, a očekávej na něj pečlivě. Nekormuť se příčinou toho, jemuž se daří na cestě jeho, příčinou člověka, kterýž provodí, cožkoli umyslil.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 8, 'Pusť mimo sebe hněv, a zanech prchlivosti; nezpouzej se tak, abys zle činiti chtěl.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 9, 'Nebo zlostníci vypléněni budou, ale ti, kteříž očekávají na Hospodina, dědičně zemí vládnouti budou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 10, 'Po malé chvíli zajisté, anť bezbožníka nebude, a pohledíš na místo jeho, anť ho již není.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 11, 'Ale tiší dědičně obdrží zemi, a rozkoš míti budou ve množství pokoje.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 12, 'Zle myslí bezbožník o spravedlivém, a škřipí na něj zuby svými,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 13, 'Ale Hospodin směje se jemu; nebo vidí, že se přibližuje den jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 14, 'Vytrhujíť bezbožníci meč, a natahují lučiště své, aby porazili chudého a nuzného, aby hubili ty, kteříž jsou ctného obcování;');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 15, 'Ale meč jejich vejde v jejich srdce, a lučiště jejich budou polámána.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 16, 'Lepší jest málo, což má spravedlivý, než veliká bohatství bezbožníků mnohých.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 17, 'Nebo ramena bezbožných polámána budou, spravedlivé pak zdržuje Hospodin.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 18, 'Znáť Hospodin dny upřímých, protož dědictví jejich na věky zůstane.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 19, 'Nebudouť zahanbeni v čas zlý, a ve dnech hladu nasyceni budou;');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 20, 'Ale bezbožníci zahynou, a nepřátelé Hospodinovi, jak tuk beranů s dymem mizí, tak zmizejí.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 21, 'Vypůjčuje bezbožník, a nemá co oplatiti, ale spravedlivý milost činí, a rozdává.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 22, 'Nebo požehnaní ode Pána zemí vládnouti budou, ale zlořečení od něho budou vypléněni.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 23, 'Krokové člověka spravedlivého od Hospodina spravováni bývají, a cestu jeho libuje.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 24, 'Jestliže by upadl, neurazí se; nebo Hospodin drží jej za ruku jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 25, 'Mlad jsem byl, a sstaral jsem se, a neviděl jsem spravedlivého opuštěného, ani semene jeho žebrati chleba.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 26, 'Každého dne milost činí, i půjčuje, a však símě jeho jest v požehnání.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 27, 'Odstup od zlého, a čiň dobré, a bydliti budeš na věky.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 28, 'Nebo Hospodin miluje soud, a neopouští svatých svých, na věky v stráži jeho budou; símě pak bezbožníků bude vypléněno.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 29, 'Ale spravedliví ujmou zemi dědičně, a na věky v ní přebývati budou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 30, 'Ústa spravedlivého mluví moudrost, a jazyk jeho vynáší soud.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 31, 'Zákon Boha jeho jest v srdci jeho, pročež nepodvrtnou se nohy jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 32, 'Špehujeť bezbožník po spravedlivém, a hledá ho zahubiti;');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 33, 'Ale Hospodin ho nenechá v ruce jeho, aniž ho dopustí potupiti, když by souzen byl.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 34, 'Očekávejž tedy na Hospodina, a ostříhej cesty jeho, a on tě povýší, abys dědičně obdržel zemi, z níž že vykořeněni budou bezbožníci, uhlédáš.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 35, 'Viděl jsem bezbožníka hrozné síly, an se rozložil jako zelený samorostlý strom.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 36, 'Ale tudíž pominul, a aj nebylo ho; nebo hledal jsem ho, a není nalezen.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 37, 'Pozor měj na pobožného, a viz upřímého, žeť takového člověka poslední věci jsou potěšené,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 38, 'Přestupníci pak že tolikéž vyhlazeni budou, a bezbožníci naposledy vyťati.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 39, 'Ale spasení spravedlivých jest od Hospodina, onť jest síla jejich v času ssoužení.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 40, 'Spomáháť jim Hospodin, a je vytrhuje, vytrhuje je od bezbožníků, a zachovává je; nebo doufají v něho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 1, 'Žalm Davidův k připomínání. Hospodine, v prchlivosti své netresci mne, ani v hněvě svém kárej mne.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 2, 'Nebo střely tvé uvázly ve mně, a ruka tvá na mne těžce dolehla.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 3, 'Nic není celého v těle mém pro tvou hněvivost, nemají pokoje kosti mé pro hřích můj.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 4, 'Nebo nepravosti mé vzešly nad hlavu mou, jako břímě těžké nemožné jsou mi k unesení.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 5, 'Zahnojily se, a kyší rány mé pro bláznovství mé.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 6, 'Pohrbený a sklíčený jsem náramně, každého dne v smutku chodím.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 7, 'Nebo ledví má plná jsou mrzkosti, a nic není celého v těle mém.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 8, 'Zemdlen jsem a potřín převelice, řvu pro úzkost srdce svého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 9, 'Pane, před tebou jest všecka žádost má, a vzdychání mé není před tebou skryto.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 10, 'Srdce mé zmítá se, opustila mne síla má, i to světlo očí mých není se mnou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 11, 'Ti, kteříž mne milovali, a tovaryši moji, štítí se ran mých, a příbuzní moji zdaleka stojí.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 12, 'Ti pak, kteříž stojí o bezživotí mé, osídla lécejí, a kteříž mého zlého hledají, mluví převráceně, a přes celý den lest a chytrost smýšlejí.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 13, 'Ale já jako hluchý neslyším, a jako němý, kterýž neotvírá úst svých;');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 14, 'Tak jsem, jako člověk, kterýž neslyší, a v jehož ústech není žádného odporu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 15, 'Nebo na tě, Hospodine, očekávám, ty za mne odpovíš, Pane Bože můj.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 16, 'Nebo jsem řekl: Ať se neradují ze mne, poklesla-li by se noha má, ať se pyšně nepozdvihují nade mnou,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 17, 'Poněvadž k snášení bíd hotov jsem, anobrž bolest má vždycky jest přede mnou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 18, 'A že nepravosti své vyznávám, a pro hřích svůj tesklím.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 19, 'Pročež nepřátelé moji veseli jsouce, silí se, a rozmnožují se ti, kteříž mne bez příčiny nenávidí.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 20, 'A zlým za dobré mi se odplacujíce, činí mi protivenství, proto že dobrého následuji.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 21, 'Neopouštějž mne, Hospodine Bože můj, nevzdalujž se ode mne.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 22, 'Přispěj k spomožení mému, Pane spasení mého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 39, 1, 'Přednímu zpěváku Jedutunovi, žalm Davidův. Řekl jsem: Ostříhati budu cest svých, abych nezhřešil jazykem svým; pojmu v uzdu ústa svá, dokudž bude bezbožník přede mnou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 39, 2, 'Mlčením byl jsem k němému podobný, umlčel jsem se i spravedlivého odporu, ale bolest má více zbouřena jest.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 39, 3, 'Hořelo ve mně srdce mé, roznícen jest oheň v přemyšlování mém, tak že jsem mluvil jazykem svým, řka:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 39, 4, 'Dej mi znáti, Hospodine, konec života mého, a odměření dnů mých jaké jest, abych věděl, jak dlouho trvati mám.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 39, 5, 'Aj, na dlaň odměřil jsi mi dnů, a věk můj jest jako nic před tebou, a jistě žeť není než pouhá marnost každý člověk, jakkoli pevně stojící. Sélah.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 39, 6, 'Jistě tak pomíjí člověk jako stín, nadarmo zajisté kvaltuje se; shromažďuje, a neví, kdo to pobéře.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 39, 7, 'Načež bych tedy nyní očekával, Pane? Očekávání mé jest na tebe.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 39, 8, 'A protož ode všech přestoupení mých vysvoboď mne, za posměch bláznu nevystavuj mne.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 39, 9, 'Oněměl jsem, a neotevřel úst svých, proto že jsi ty učinil to.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 39, 10, 'Odejmi ode mne metlu svou, nebo od švihání ruky tvé docela zhynul jsem.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 39, 11, 'Ty, když žehráním pro nepravost tresceš člověka, hned jako mol k zetlení přivodíš zdárnost jeho; marnost zajisté jest všeliký člověk. Sélah.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 39, 12, 'Vyslyšiž modlitbu mou, Hospodine, a volání mé přijmi v uši své; neodmlčujž se kvílení mému, nebo jsem příchozí a podruh u tebe, jako i všickni otcové moji.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 39, 13, 'Ponechej mne, ať se posilím, prvé než bych se odebral, a již zde více nebyl.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 1, 'Přednímu zpěváku, Davidův žalm. Žádostivě očekával jsem na Hospodina, i naklonil se ke mně, a vyslyšel mé volání.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 2, 'A vytáhl mne z čisterny hlučící, i z bláta bahnivého, a postavil na skále nohy mé, a kroky mé utvrdil.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 3, 'A tak vložil v ústa má píseň novou, chválu Bohu našemu, což když uhlédají mnozí, i báti se, i doufání skládati budou v Hospodinu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 4, 'Blahoslavený ten člověk, kterýž skládá v Hospodinu svou naději, a neohlédá se na pyšné, ani na ty, kteříž se ke lži uchylují.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 5, 'Mnohé věci činíš ty, Hospodine Bože můj, a divní jsou skutkové tvoji i myšlení tvá o nás; není, kdo by je pořád vyčísti mohl před tebou. Já chtěl-li bych je vymluviti a vypraviti, mnohem více jich jest, nežli vypraveno býti může.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 6, 'Oběti a daru neoblíbils, ale uši jsi mi otevřel; zápalu a oběti za hřích nežádal jsi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 7, 'Tehdy řekl jsem: Aj, jduť, jakož v knihách psáno jest o mně.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 8, 'Abych činil vůli tvou, Bože můj, líbost mám; nebo zákon tvůj jest u prostřed vnitřností mých.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 9, 'Ohlašoval jsem spravedlnost v shromáždění velikém; aj, rtů svých že jsem nezdržoval, ty znáš, Hospodine.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 10, 'Spravedlnosti tvé neukryl jsem u prostřed srdce svého, pravdu tvou a spasení tvé vypravoval jsem, nezatajil jsem milosrdenství tvého a pravdy tvé v shromáždění velikém.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 11, 'Ty pak, Hospodine, nevzdaluj slitování svých ode mne; milosrdenství tvé a pravda tvá vždycky ať mne ostříhají.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 12, 'Neboť jsou mne obklíčily zlé věci, jimž počtu není; dostihly mne mé nepravosti, tak že prohlédnouti nemohu; rozmnožily se nad počet vlasů hlavy mé, a srdce mé opustilo mne.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 13, 'Račiž ty mne, Hospodine, vysvoboditi; Hospodine, pospěšiž ku pomoci mé.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 14, 'Zahanbeni buďte, a zapyřte se všickni, kteříž hledají duše mé, aby ji zahladili; zpět obráceni a v potupu dáni buďte, kteříž líbost mají v neštěstí mém.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 15, 'Přijdiž na ně spuštění za to, že mne k hanbě přivésti usilují, říkajíce: Hahá, hahá.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 16, 'Ale ať radují a veselí se v tobě všickni hledající tebe, a milující spasení tvé ať říkají vždycky: Veleslaven budiž Hospodin.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 17, 'Já pak ačkoli chudý a nuzný jsem, Pán však pečuje o mne. Pomoc má a vysvoboditel můj ty jsi. Bože můj, neprodlévejž.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 41, 1, 'Přednímu zpěváku, žalm Davidův. Blahoslavený, kdož prozřetelný soud činí o chudém; v den zlý vysvobodí jej Hospodin.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 41, 2, 'Hospodin ho ostřeže, a obživí jej; blažený bude na zemi, aniž ho vydá líbosti nepřátel jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 41, 3, 'Hospodin ho na ložci ve mdlobě posilí, všecko ležení jeho v nemoci jeho promění.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 41, 4, 'Já řekl jsem: Hospodine, smiluj se nade mnou, uzdrav duši mou, nebo jsem tobě zhřešil.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 41, 5, 'Nepřátelé moji mluvili zle o mně, řkouce: Skoro-liž umřel, a zahyne jméno jeho?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 41, 6, 'A jestliže kdo z nich přichází, aby mne navštívil, pochlebenství mluví; srdce jeho sbírá sobě nepravost, a vyjda ven, roznáší ji.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 41, 7, 'Sšeptávají se spolu proti mně všickni, kteříž mne nenávidí, a přičítají mi zlé věci, říkajíce:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 41, 8, 'Pomsta pro nešlechetnost přichytila se ho, a kdyžtě se složil nepovstaneť zase.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 41, 9, 'Také i ten, s nímž jsem byl v přátelství, jemuž jsem se dověřoval, a kterýž jídal chléb můj, pozdvihl paty proti mně.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 41, 10, 'Ale ty, Hospodine, smiluj se nade mnou, a pozdvihni mne, a odplatím jim;');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 41, 11, 'Abych odtud poznal, že mne sobě libuješ, když by se neradoval nade mnou nepřítel můj.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 41, 12, 'Mne pak v upřímnosti mé zachováš, a postavíš před oblíčejem svým na věky.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 41, 13, 'Požehnaný Hospodin Bůh Izraelský, od věků až na věky, Amen i Amen.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 42, 1, 'Přednímu zpěváku z synů Chóre, žalm vyučující. Jakož jelen řve, dychtě po tekutých vodách, tak duše má řve k tobě, ó Bože.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 42, 2, 'Žízní duše má Boha, Boha živého, a říká: Skoro-liž půjdu, a ukáži se před oblíčejem Božím?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 42, 3, 'Slzy mé jsou mi místo chleba dnem i nocí, když mi říkají každého dne: Kdež jest Bůh tvůj?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 42, 4, 'Na to když se rozpomínám, téměř duši svou sám v sobě vylévám, že jsem chodíval s mnohými, a ubírával jsem se s nimi do domu Božího s hlasitým zpíváním, a díkčiněním v zástupu plésajících.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 42, 5, 'Proč jsi smutná, duše má, a proč se kormoutíš? Posečkej na Boha, neboť ještě vyznávati jej budu, i hojné spasení tváři jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 42, 6, 'Můj Bože, jak tesklí duše má! Protož se na tě rozpomínám v krajině Jordánské a Hermonské, na hoře Mitsar.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 42, 7, 'Propast propasti se ozývá k hlučení trub tvých, všecka vlnobití tvá a rozvodnění tvá na mne se svalila.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 42, 8, 'Věřím však, žeť mi udělí ve dne Hospodin milosrdenství svého, a v noci písnička jeho se mnou, a modlitba má k Bohu života mého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 42, 9, 'Dím k Bohu silnému, skále své: Pročež jsi zapomenul se nade mnou? Proč pro ssoužení od nepřítele v smutku mám choditi?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 42, 10, 'Jako rána v kostech mých jest to, když mi utrhají nepřátelé moji, říkajíce mi každého dne: Kdež jest Bůh tvůj?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 42, 11, 'Proč jsi smutná, duše má, a proč se kormoutíš ve mně? Posečkej na Boha, neboť ještě vyznávati jej budu; onť jest hojné spasení tváři mé a Bůh můj.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 43, 1, 'Suď mne, ó Bože, a zasaď se o mou při; od národu nemilosrdného, a od člověka lstivého a nepravého vytrhni mne.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 43, 2, 'Nebo ty jsi Bůh mé síly. Proč jsi mne zapudil? Proč pro ssoužení od nepřítele v smutku mám ustavičně choditi?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 43, 3, 'Sešliž světlo své a pravdu svou, to ať mne vodí a zprovodí na horu svatosti tvé a do příbytků tvých,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 43, 4, 'Abych přistoupil k oltáři Božímu, k Bohu radostného plésání mého, a budu tě oslavovati na harfě, ó Bože, Bože můj.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 43, 5, 'Proč jsi smutná, duše má, a proč se kormoutíš ve mně? Posečkej na Boha, neboť ještě vyznávati jej budu; onť jest hojné spasení tváři mé a Bůh můj.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 1, 'Přednímu zpěváku z synů Chóre, vyučující. Bože, ušima svýma slýchali jsme, a otcové naši vypravovali nám o skutcích, kteréž jsi činíval za dnů jejich, za dnů starodávních.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 2, 'Tys sám rukou svou vyhnal pohany, a vštípil jsi je; potřel jsi lidi, a je jsi rozplodil.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 3, 'Neboť jsou neopanovali země mečem svým, aniž jim rámě jejich spomohlo, ale pravice tvá a rámě tvé, a světlost oblíčeje tvého, proto že jsi je zamiloval.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 4, 'Ty jsi sám král můj, ó Bože, udílejž hojného spasení Jákobova.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 5, 'V toběť jsme protivníky naše potírali, a ve jménu tvém pošlapávali jsme povstávající proti nám.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 6, 'Neboť jsem v lučišti svém naděje neskládal, aniž mne kdy obránil meč můj.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 7, 'Ale ty jsi nás vysvobozoval od nepřátel našich, a kteříž nás nenávidí, ty jsi zahanboval.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 8, 'A protož chválíme tě Boha na každý den, a jméno tvé ustavičně oslavujeme. Sélah.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 9, 'Ale nyní jsi nás zahnal i zahanbil, a nevycházíš s vojsky našimi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 10, 'Obrátil jsi nás nazpět, a ti, kteříž nás nenávidí, rozchvátali mezi sebou jmění naše.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 11, 'Oddal jsi nás, jako ovce k snědení, i mezi pohany rozptýlil jsi nás.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 12, 'Prodal jsi lid svůj bez peněz, a nenadsadils mzdy jejich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 13, 'Vydal jsi nás k utrhání sousedům našim, ku posměchu a ku potupě těm, kteříž jsou vůkol nás.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 14, 'Uvedl jsi nás v přísloví mezi národy, a mezi lidmi, aby nad námi hlavou zmítáno bylo.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 15, 'Na každý den styděti se musím, a hanba tváři mé přikrývá mne,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 16, 'A to z příčiny řeči utrhajícího a hanějícího, z příčiny nepřítele a vymstívajícího se.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 17, 'Všecko to přišlo na nás, a však jsme se nezapomenuli na tě, aniž jsme zrušili smlouvy tvé.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 18, 'Neobrátilo se nazpět srdce naše, aniž se uchýlil krok náš od stezky tvé,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 19, 'Ačkoli jsi nás byl potřel na místě draků, a přikryl jsi nás stínem smrti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 20, 'Kdybychom se byli zapomenuli na jméno Boha svého, a pozdvihli rukou svých k bohu cizímu,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 21, 'Zdaliž by toho Bůh byl nevyhledával? Nebo on zná skrytosti srdce.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 22, 'Anobrž pro tebe mordováni býváme každého dne, jmíni jsme jako ovce k zabití oddané.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 23, 'Procitiž, proč spíš, ó Pane? Probudiž se, a nezaháněj nás na věky.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 24, 'I pročež tvář svou skrýváš, a zapomínáš se na trápení a ssoužení naše?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 25, 'Nebotě se již sklonila až k prachu duše naše, přilnul k zemi život náš.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 26, 'Povstaniž k našemu spomožení, a vykup nás pro své milosrdenství.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 1, 'Přednímu kantoru z synů Chóre, na šošannim, vyučující. Píseň o lásce. Vyneslo srdce mé slovo dobré, vypravovati budu písně své o králi, jazyk můj jako péro hbitého písaře.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 2, 'Krásnější jsi nad všecky syny lidské, rozlita jest i milost ve rtech tvých, proto že jest tobě požehnal Bůh až na věky.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 3, 'Připaš meč svůj na bedra, ó reku udatný, prokaž důstojnost a slávu svou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 4, 'A v té slávě své šťastně vyjížděj s slovem pravdy, tichosti a spravedlnosti, a dokáže pravice tvá hrozných věcí.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 5, 'Střely tvé jsou ostré, padati budou od nich před tebou národové, proniknou až k srdci nepřátel královských.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 6, 'Trůn tvůj, ó Bože, jest věčný a stálý, berla království tvého jestiť berla nejupřímější.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 7, 'Miluješ spravedlnost, a nenávidíš bezbožnosti, protož pomazal tě, Bože, Bůh tvůj olejem veselé nad účastníky tvé.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 8, 'Mirra, aloe a kassia, všecka roucha tvá voní z paláců, z kostí slonových vzdělaných, nad ty, jenž tě obveselují.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 9, 'Dcery králů jsou mezi vzácnými tvými, přístojíť i manželka tobě po pravici v ryzím zlatě.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 10, 'Slyšiž, dcerko, a viz, a nakloň ucha svého, a zapomeň na lid svůj a na dům otce svého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 11, 'I zalíbí se králi tvá krása; onť jest zajisté Pán tvůj, protož skláněj se před ním.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 12, 'Tuť i Tyrští s dary, před oblíčejem tvým kořiti se budou bohatí národové.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 13, 'Všecka slavná jest dcera královská u vnitřku, roucho zlatem vytkávané jest oděv její.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 14, 'V rouše krumpovaném přivedena bude králi, i panny za ní, družičky její, přivedeny budou k tobě.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 15, 'Přivedeny budou s radostí velikou a plésáním, a vejdou na palác královský.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 16, 'Místo otců svých budeš míti syny své, kteréž postavíš za knížata po vší zemi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 17, 'V pamět uvoditi budu jméno tvé po všecky věky, pročež oslavovati tě budou národové na věky věků.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 46, 1, 'Přednímu kantoru z synů Chóre, píseň na alamot. Bůh jest naše útočiště i síla, ve všelikém ssoužení pomoc vždycky hotová.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 46, 2, 'A protož nebudeme se báti, byť se pak i země podvrátila, a zpřevracely se hory do prostřed moře.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 46, 3, 'Byť i ječely, a kormoutily se vody jeho, a hory se rozrážely od dutí jeho. Sélah.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 46, 4, 'Potok a pramenové jeho obveselují město Boží, nejsvětější z příbytků Nejvyššího.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 46, 5, 'Bůh jest u prostřed něho, nepohneť se; přispějeť jemu Bůh na pomoc hned v jitře.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 46, 6, 'Když hlučeli národové, a pohnula se království, vydal hlas svůj, a rozplynula se země.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 46, 7, 'Hospodin zástupů jest s námi, hradem vysokým jest nám Bůh Jákobův. Sélah.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 46, 8, 'Poďte, vizte skutky Hospodinovy, jakýchť jest pustin nadělal na zemi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 46, 9, 'Přítrž činí bojům až do končin země, lučiště láme, kopí posekává, a vozy spaluje ohněm,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 46, 10, 'Mluvě: Upokojtež se, a vězte, žeť jsem já Bůh, kterýž vyvýšen budu mezi národy, vyvýšen budu na zemi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 46, 11, 'Hospodin zástupů jest s námi, hradem vysokým jest nám Bůh Jákobův. Sélah.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 47, 1, 'Přednímu zpěváku z synů Chóre, žalm. Všickni národové plésejte rukama, trubte Bohu s hlasitým prozpěvováním.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 47, 2, 'Nebo Hospodin nejvyšší, hrozný, jest král veliký nade vší zemi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 47, 3, 'Uvozuje lidi v moc naši, a národy pod nohy naše.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 47, 4, 'Oddělil nám za dědictví naše slávu Jákobovu, kteréhož miloval. Sélah.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 47, 5, 'Vstoupil Bůh s troubením, Hospodin s zvukem trouby.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 47, 6, 'Žalmy zpívejte Bohu, zpívejte; zpívejte žalmy králi našemu, zpívejte.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 47, 7, 'Nebo král vší země Bůh jest, zpívejte žalmy rozumně.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 47, 8, 'Kralujeť Bůh nad národy, Bůh sedí na trůnu svém svatém.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 47, 9, 'Knížata národů připojili se k lidu Boha Abrahamova; nebo pavézy země Boží jsou, pročež on náramně vyvýšen jest.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 48, 1, 'Píseň žalmu synů Chóre. Veliký jest Hospodin, a převelmi chvalitebný v městě Boha našeho, na hoře svatosti své.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 48, 2, 'Ozdoba krajiny, útěcha vší země jestiť hora Sion, k straně půlnoční, město krále velikého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 48, 3, 'Bůh na palácích jeho, a znají ho býti vysokým hradem.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 48, 4, 'Nebo aj, králové když se shromáždili a spolu táhli,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 48, 5, 'Sami to uzřevše, velmi se divili, a předěšeni byvše, náhle utíkali.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 48, 6, 'Tuť jest je strach popadl, a bolest jako ženu rodící.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 48, 7, 'Větrem východním rozrážíš lodí Tarské.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 48, 8, 'Jakž jsme slýchali, tak jsme spatřili, v městě Hospodina zástupů, v městě Boha našeho. Bůh upevní je až na věky.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 48, 9, 'Rozjímáme, ó Bože, milosrdenství tvé u prostřed chrámu tvého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 48, 10, 'Jakož jméno tvé, Bože, tak i chvála tvá až do končin země; pravice tvá zajisté plná jest spravedlnosti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 48, 11, 'Raduj se, horo Sione, plésejte, dcery Judské, z příčiny soudů Božích.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 48, 12, 'Obejděte Sion, a obstupte jej, sečtěte věže jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 48, 13, 'Přiložte mysl svou k ohradě, popatřte na paláce jeho, abyste uměli vypravovati věku potomnímu,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 48, 14, 'Že tento Bůh jest Bůh náš na věčné věky, a že on vůdce náš bude až do smrti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 1, 'Přednímu kantoru z synů Chóre, žalm. Slyšte to všickni národové, pozorujte všickni obyvatelé zemští.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 2, 'Tak z lidu obecného, jako z povýšených, tak bohatý, jako chudý.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 3, 'Ústa má mluviti budou moudrost, a přemyšlování srdce mého rozumnost.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 4, 'Nakloním k přísloví ucha svého, a při harfě vykládati budu přípovídku svou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 5, 'I proč se báti mám ve dnech zlých, aby nepravost těch, kteříž mi na paty šlapají, mne obklíčiti měla?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 6, 'Kteříž doufají v svá zboží, a množstvím bohatství svého se chlubí.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 7, 'Žádný bratra svého nijakž vykoupiti nemůže, ani Bohu za něj dáti mzdy vyplacení,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 8, '(Neboť by velmi drahé musilo býti vyplacení duše jejich, protož nedovedeť toho na věky),');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 9, 'Aby živ byl věčně, a neviděl porušení.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 10, 'Nebo se vídá, že i moudří umírají, blázen a hovadný člověk zaroveň hynou, zboží svého i cizím zanechávajíce.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 11, 'Myšlení jejich jest, že domové jejich věční jsou, a příbytkové jejich od národu do pronárodu; pročež je po krajinách nazývají jmény svými.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 12, 'Ale člověk v slávě netrvá, jsa podobný hovadům, kteráž hynou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 13, 'Taková snažnost jejich jest bláznovstvím při nich, však potomci jejich ústy svými to schvalují. Sélah.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 14, 'Jako hovada v pekle skladeni budou, smrt je žráti bude, ale upřímí panovati budou nad nimi v jitře; způsob pak oněchno aby zvetšel, z příbytku svého octnou se v hrobě.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 15, 'Ale Bůh vykoupí duši mou z moci pekla, když mne přijme. Sélah.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 16, 'Neboj se, když by někdo zbohatl, a když by se rozmnožila sláva domu jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 17, 'Při smrti zajisté ničeho nevezme, aniž sstoupí za ním sláva jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 18, 'Ačťkoli duši své, pokudž jest živ, lahodí; k tomu chválí jej i jiní, když sobě čistě povoluje:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 19, 'A však musí se odebrati za věkem otců svých, a na věky světla neuzří.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 20, 'Summou: Člověk jsa ve cti, neusrozumí-li sobě, bývá učiněn podobný hovadům, kteráž hynou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 1, 'Žalm Azafovi. Bůh silný, Bůh Hospodin mluvil, a přivolal zemi od východu slunce i od západu jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 2, 'Z Siona v dokonalé kráse Bůh zastkvěl se.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 3, 'Béřeť se Bůh náš, a nebude mlčeti; oheň před ním vše zžírati bude, a vůkol něho vichřice náramná.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 4, 'Zavolal nebes s hůry i země, aby soudil lid svůj, řka:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 5, 'Shromažďte mi svaté mé, kteříž smlouvu se mnou učinili při obětech.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 6, 'I budou vypravovati nebesa spravedlnost jeho; nebo sám Bůh soudce jest. Sélah.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 7, 'Slyš, lide můj, a buduť mluviti, Izraeli, a buduť tebou osvědčovati. Já zajisté Bůh, Bůh tvůj jsem.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 8, 'Nechci tě obviňovati z příčiny obětí tvých, ani zápalů tvých, že by vždycky přede mnou nebyli.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 9, 'Nevezmuť z domu tvého volka, ani z chlévů tvých kozlů.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 10, 'Nebo má jest všecka zvěř lesní, i hovada na tisíci horách.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 11, 'Já znám všecko ptactvo po horách, a zvěř polní před sebou mám.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 12, 'Zlačním-li, nic tobě o to nedím; nebo můj jest okršlek zemský i plnost jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 13, 'Zdaliž jídám maso z volů, a pijím krev kozlovou?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 14, 'Obětuj Bohu obět chvály, a plň Nejvyššímu své sliby;');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 15, 'A vzývej mne v den ssoužení, vytrhnu tě, a ty mne budeš slaviti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 16, 'Sic jinak bezbožníku praví Bůh: Což tobě do toho, že ty vypravuješ ustanovení má, a béřeš smlouvu mou v ústa svá,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 17, 'Poněvadž jsi vzal v nenávist kázeň, a zavrhl jsi za sebe slova má.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 18, 'Vidíš-li zloděje, hned s ním běžíš, a s cizoložníky díl svůj máš.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 19, 'Ústa svá pouštíš ke zlému, a jazyk tvůj skládá lest.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 20, 'Usazuješ se, a mluvíš proti bratru svému, a na syna matky své lehkost uvodíš.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 21, 'To jsi činil, a já mlčel jsem. Měl-liž jsi ty se domnívati, že já tobě podobný budu? Nýbrž trestati tě budu, a představímť to před oči tvé.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 22, 'Srozumějtež tomu již aspoň vy, kteříž se zapomínáte na Boha, abych snad nepochytil, a nebyl by, kdo by vytrhl.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 23, 'Kdož obětuje obět chvály, tenť mne uctí, a tomu, kdož napravuje cestu svou, ukáži spasení Boží.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 1, 'Přednímu z kantorů, žalm Davidův, Když k němu přišel Nátan prorok, po jeho vjití k Betsabé. Smiluj se nade mnou, Bože, podlé milosrdenství svého, podlé množství slitování svých shlaď přestoupení má.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 2, 'Dokonale obmej mne od nepravosti mé, a od hříchu mého očisť mne.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 3, 'Nebo já znám přestoupení svá, a hřích můj přede mnou jest ustavičně.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 4, 'Tobě, tobě samému, zhřešil jsem, a zlého se před očima tvýma dopustil, abys spravedlivý zůstal v řečech svých, a bez úhony v soudech svých.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 5, 'Aj, v nepravosti zplozen jsem, a v hříchu počala mne matka má.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 6, 'Aj, ty libuješ pravdu u vnitřnostech, nadto skrytou moudrost zjevil jsi mi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 7, 'Vyčisť mne yzopem, a očištěn budu, umej mne, a nad sníh bělejší budu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 8, 'Dej mi slyšeti radost a potěšení, tak ať zpléší kosti mé, kteréž jsi potřel.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 9, 'Odvrať tvář svou přísnou od hříšností mých, a vymaž všecky nepravosti mé.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 10, 'Srdce čisté stvoř mi, ó Bože, a ducha přímého obnov u vnitřnostech mých.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 11, 'Nezamítej mne od tváři své, a Ducha svatého svého neodjímej ode mne.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 12, 'Navrať mi radost spasení svého, a duchem dobrovolným utvrď mne.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 13, 'I budu vyučovati přestupníky cestám tvým, aby hříšníci k tobě se obraceli.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 14, 'Vytrhni mne z pomsty pro vylití krve, ó Bože, Bože spasiteli můj, a budeť s veselím prozpěvovati jazyk můj o spravedlnosti tvé.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 15, 'Pane, rty mé otevři, i budou ústa má zvěstovati chválu tvou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 16, 'Nebo neoblíbil bys oběti, bychť ji i dal, aniž bys zápalu přijal.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 17, 'Oběti Boží duch skroušený; srdcem skroušeným a potřebným, Bože, nezhrzíš.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 18, 'Dobrotivě nakládej z milosti své s Sionem, vzdělej zdi Jeruzalémské.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 19, 'A tehdáž sobě zalíbíš oběti spravedlnosti, zápaly a pálení celých obětí, tehdážť voly na oltáři tvém obětovati budou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 52, 1, 'Přednímu z kantorů, vyučující žalm Davidův. Když přišel Doeg Idumejský, a zvěstoval Saulovi, a pověděl mu, že David všel do domu Achimelechova. Proč se chlubíš nešlechetností, ty mocný? Milosrdenstvíť Boha silného trvá každého dne.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 52, 2, 'Těžkosti obmýšlí jazyk tvůj, tak jako břitva nabroušená lest provodí.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 52, 3, 'Miluješ zlé více než dobré, raději lež mluvíš než spravedlnost. Sélah.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 52, 4, 'Miluješ všelijaké řeči k sehlcení, a jazyk ošemetný.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 52, 5, 'I tebeť Bůh silný zkazí na věky, pochytí tě, a vytrhne tě z stánku, a vykoření z země živých. Sélah.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 52, 6, 'Což spravedliví vidouce, budou se báti a jemu posmívati:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 52, 7, 'Aj, toť jest ten člověk, kterýž neskládal v Bohu síly své, ale doufaje ve množství bohatství svých, zmocňoval se v zlosti své.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 52, 8, 'Já pak budu jako oliva zelenající se v domě Božím; neboť jsem naději složil v milosrdenství Božím na věky věků.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 52, 9, 'Oslavovati tě budu, Pane, na věky, že jsi to učinil, a poshovím na jméno tvé, neboť jest vzácné před oblíčejem svatých tvých.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 53, 1, 'Přednímu z kantorů na machalat, vyučující žalm Davidův. Říká blázen v srdci svém: Není Boha. Porušeni jsou, a ohavnou páší nepravost; není, kdo by činil dobré.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 53, 2, 'Bůh s nebe popatřil na syny lidské, aby viděl, byl-li by kdo rozumný a hledající Boha.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 53, 3, 'Aj, každý z nich nazpět odšel, napořád neužiteční učiněni jsou; není, kdo by činil dobré, není ani jednoho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 53, 4, 'Zdaliž nevědí všickni činitelé nepravosti, lid můj sžírajíce, jako by chléb jedli? Boha pak nevzývají.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 53, 5, 'Tuť se náramně strašiti budou, kdež není strachu. Bůh zajisté rozptýlí kosti těch, kteříž tě vojensky oblehli; zahanbíš je, nebo Bůh pohrdl jimi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 53, 6, 'Ó by z Siona dáno bylo spasení Izraelovi. Když Bůh zase přivede zajaté lidu svého, plésati bude Jákob, a veseliti se Izrael.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 54, 1, 'Přednímu z kantorů na neginot, vyučující žalm Davidův, Když přišli Zifejští, a řekli Saulovi: Nevíš-liž, že se David pokrývá u nás? Bože, spasena mne učiň pro jméno své, a v moci své veď při mou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 54, 2, 'Bože, slyš modlitbu mou, pozoruj řeči úst mých.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 54, 3, 'Neboť jsou cizí povstali proti mně, a ukrutníci hledají duše mé, nepředstavujíce sobě Boha před oblíčej svůj. Sélah.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 54, 4, 'Aj, Bůhť jest spomocník můj; Pán s těmi jest, kteříž jsou podpůrcové života mého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 54, 5, 'Odplať zlým nepřátelům mým, v pravdě své vypleň je, ó Pane.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 54, 6, 'I buduť dobrovolně oběti obětovati, slaviti budu jméno tvé, Hospodine, proto že jest dobré.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 54, 7, 'Nebo z ssoužení všelikého vytrhl mne Bůh, nýbrž i pomstu nad nepřátely mými vidělo oko mé.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 1, 'Přednímu kantoru na neginot, vyučující žalm Davidův. Slyš, ó Bože, modlitbu mou, a neskrývej se před prosbou mou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 2, 'Pozoruj a vyslyš mne, neboť naříkám v úpění svém, a kormoutím se,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 3, 'A to pro křik nepřítele, pro nátisk bezbožníka; neboť sčítají na mne lživé věci, a s vzteklostí se proti mně postavují.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 4, 'Srdce mé bolestí ve mně, a strachové smrti připadli na mne.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 5, 'Bázeň a strach přišel na mne, a hrůza přikvačila mne.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 6, 'I řekl jsem: Ó bych měl křídla jako holubice, zaletěl bych a poodpočinul.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 7, 'Aj, daleko bych se vzdálil, a přebýval bych na poušti. Sélah.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 8, 'Pospíšil bych ujíti větru prudkému a vichřici.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 9, 'Zkaz je, ó Pane, změť jazyk jejich, neboť jsem spatřil bezpráví a rozbroj v městě.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 10, 'Dnem i nocí ty věci je obkličují po zdech jeho, a v prostředku jeho jest nepravost a převrácenost.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 11, 'Těžkosti jsou u prostřed něho, aniž vychází chytrost a lest z ulic jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 12, 'Nebo ne nějaký nepřítel útržky mi činil, sic jinak snesl bych to; ani ten, kdož mne nenávidí, pozdvihl se proti mně, nebo skryl bych se před ním:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 13, 'Ale ty, člověče mně rovný, vůdce můj a domácí můj;');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 14, 'Ješto jsme spolu mile tajné rady držívali, a do domu Božího společně chodívali.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 15, 'Ó by je smrt náhle přikvačila, tak aby za živa sstoupiti musili do pekla; nebo jest nešlechetnost v příbytcích jejich a u prostřed nich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 16, 'Já pak k Bohu volati budu, a Hospodin vysvobodí mne.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 17, 'U večer, i ráno, též o poledni modliti se, a nezbedně volati budu, až i vyslyší hlas můj.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 18, 'Vykoupíť duši mou, tak aby v pokoji byla před válkou proti mně; nebo veliké množství bylo jich při mně.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 19, 'Vyslyšíť Bůh silný, a je ssouží, (neboť sedí od věčnosti, Sélah), proto že nenapravují, aniž se bojí Boha.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 20, 'Vztáhl ruce své na ty, kteříž s ním pokoj měli, a zrušil smlouvu svou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 21, 'Libější než máslo byla slova úst jeho, ale v srdci boj; měkčejší nad olej řeči jeho, a však byly jako mečové.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 22, 'Uvrz na Hospodina břímě své, a onť opatrovati tě bude, aniž dopustí, aby na věky pohnut byl spravedlivý.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 23, 'Ale onyno, ty Bože, svedeš do jámy zatracení; lidé zajisté vražedlní a lstiví nedojdou polovice dnů svých, já pak v tebe doufati budu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 56, 1, 'Přednímu z kantorů, o němé holubici v místech vzdálených, zlatý žalm Davidův, když ho jali Filistinští v Gát. Smiluj se nade mnou, ó Bože, nebo mne sehltiti chce člověk; každého dne boj veda, ssužuje mne.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 56, 2, 'Sehltiti mne usilují na každý den moji nepřátelé; jistě žeť jest mnoho válčících proti mně, ó Nejvyšší.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 56, 3, 'Kteréhokoli dne strach mne obkličuje, v tebe doufám.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 56, 4, 'Boha chváliti budu z slova jeho, v Boha doufati budu, aniž se budu báti, aby mi co mohlo učiniti tělo.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 56, 5, 'Na každý den slova má převracejí, proti mně jsou všecka myšlení jejich ke zlému.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 56, 6, 'Spolu se scházejí, skrývají se, a šlepějí mých šetří, číhajíce na duši mou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 56, 7, 'Za nešlechetnost-liž zniknou pomsty? V prchlivosti, ó Bože, smeceš lidi ty.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 56, 8, 'Ty má utíkání v počtu máš, schovej slzy mé do láhvice své, a což bys jich v počtu neměl?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 56, 9, 'A tehdyť obráceni budou zpět nepřátelé moji v ten den, když volati budu; toť vím, že Bůh při mně stojí.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 56, 10, 'Jáť budu Boha chváliti z slova, Hospodina oslavovati budu z slova jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 56, 11, 'V Boha doufám, nebudu se báti, aby mi co učiniti mohl člověk.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 56, 12, 'Tobě jsem, Bože, učinil sliby, a protož tobě vzdám chvály.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 56, 13, 'Nebo jsi vytrhl z smrti duši mou, a nohy mé od poklesnutí, tak abych stále chodil před Bohem v světle živých.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 57, 1, 'Přednímu kantoru, jako: Nevyhlazuj, zlatý žalm Davidův, když utekl před Saulem do jeskyně. Smiluj se nade mnou, ó Bože, smiluj se nade mnou; neboť v tebe doufá duše má, a v stínu křídel tvých schráním se, až přejde ssoužení.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 57, 2, 'Volati budu k Bohu nejvyššímu, k Bohu silnému, kterýž dokonává za mne.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 57, 3, 'Onť pošle s nebe, a zachová mne od potupy usilujícího mne sehltiti. Sélah. Pošle Bůh milosrdenství své a pravdu svou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 57, 4, 'Duše má jest u prostřed lvů, bydlím mezi paliči, mezi lidmi, jejichž zubové kopí a střely, a jazyk jejich jako ostrý meč.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 57, 5, 'Vyvyšiž se nad nebesa, ó Bože, a nade všecku zemi sláva tvá.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 57, 6, 'Tenata roztáhli nohám mým, sklíčili duši mou, vykopali přede mnou jámu, ale sami upadli do ní. Sélah.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 57, 7, 'Hotovo jest srdce mé, Bože, hotovo jest srdce mé, zpívati a oslavovati tě budu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 57, 8, 'Probuď se, slávo má, probuď se, loutno a harfo, když v svitání povstávám.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 57, 9, 'Slaviti tě budu mezi lidmi, Pane, žalmy prozpěvovati tobě budu mezi národy.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 57, 10, 'Nebo veliké jest až k nebi milosrdenství tvé, a až k nejvyšším oblakům pravda tvá.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 57, 11, 'Vyvyšiž se nad nebesa, ó Bože, a nade všecku zemi sláva tvá.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 58, 1, 'Přednímu z kantorů, jako: Nevyhlazuj, Davidův žalm zlatý. Právě-liž vy, ó shromáždění, spravedlnost vypovídáte? Upřímě-liž soudy činíte, vy synové lidští?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 58, 2, 'Anobrž raději nepravosti v srdci ukládáte, a násilí rukou svých v zemi této odvažujete.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 58, 3, 'Uchýlili se bezbožníci hned od narození, pobloudili hned od života matky, mluvíce lež.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 58, 4, 'Jed v sobě mají jako jedovatý had, jako lítý had hluchý, kterýž zacpává ucho své,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 58, 5, 'Aby neslyšel hlasu zaklinačů, a čarodějníka v čářích vycvičeného.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 58, 6, 'Ó Bože, potři jim zuby v ústech jejich, střenovní zuby lvíčat těch polámej, Hospodine.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 58, 7, 'Nechť se rozplynou jako voda, a zmizejí; ať jsou jako ten, kterýž napíná luk, jehož však střely se lámí,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 58, 8, 'Jako hlemejžď, kterýž tratí se a mizí, jako nedochůdče ženy, ješto nespatřilo slunce.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 58, 9, 'Prvé než lidé pocítí trní jejich a bodláku, hned za živa zapálením jako vichřicí zachváceni budou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 58, 10, 'I bude se veseliti spravedlivý, když uzří pomstu, nohy své umyje ve krvi bezbožníka.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 58, 11, 'Ano dí každý: V pravdě, žeť má užitek spravedlivý, jistě, žeť jest Bůh soudce na zemi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 1, 'Přednímu z kantorů, jako: Nevyhlazujž, Davidův žalm zlatý, když poslal Saul, aby střehouc domu, zabili ho. Vytrhni mne od nepřátel mých, Bože můj; před těmi, kteříž povstávají proti mně, bezpečna mne učiň.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 2, 'Vytrhni mne od těch, kteříž páší nepravost, a od mužů vražedlných zachovej mne.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 3, 'Neb aj, zálohy činí duši mé, sbírají se proti mně mocní, bez mého provinění a bez hříchu mého, ó Hospodine.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 4, 'Beze vší mé nepravosti sbíhají se, a strojí; povstaniž mně vstříc, a popatř.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 5, 'Sám ty, Hospodine Bože zástupů, Bože Izraelský, prociť, abys navštívil všecky národy, aniž se smilovávej nad kterým z těch převrácenců nešlechetných. Sélah.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 6, 'Navracejí se k večerou, štěkají jako psi, a běhají okolo města.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 7, 'Aj, coť vynášejí ústy svými! Mečové jsou ve rtech jejich, nebo říkají: Zdaliž kdo slyší?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 8, 'Ale ty, Hospodine, směješ se jim, posmíváš se všechněm národům.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 9, 'Když on moc provozuje, na tebe pozor míti budu, nebo ty, Bože, jsi hrad můj vysoký.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 10, 'Bůh mně milosrdný předejdeť mne, Bůh dá mi viděti pomstu nad nepřátely mými.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 11, 'Nezbijej jich, aby nezapomněl lid můj, ale zmítej jimi mocí svou, a sházej je, pavézo naše, ó Pane.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 12, 'Hřích úst svých, slova rtů svých, (postiženi jsouce v pýše své, pro prokletí a chřadnutí), ať vypravují.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 13, 'Zahlaď v prchlivosti, zahlaď je, ať jich není, ať poznají, že Bůh panuje v Jákobovi i do končin země. Sélah.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 14, 'I nechažť se pak zase navracejí k večerou, štěkají jako psi, a běhají okolo města.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 15, 'Nechať těkají, a potravy hledají, však hladovití jsouce, uložiti se musejí.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 16, 'Já pak zpívati budu o síle tvé, hned z jitra hlasitě slaviti budu milosrdenství tvé, nebo jsi byl hrad můj vysoký, a útočiště v den ssoužení mého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 17, 'A posilen jsa, žalmy tobě zpívati budu; nebo jsi Bůh, vysoký hrad můj, Bůh mně milosrdný.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 60, 1, 'Přednímu z kantorů na šušan eduth, zlatý žalm Davidův, k vyučování, Když válku vedl proti Syrii Naharaim, a proti Syrii Soba, kdyžto navrátil se Joáb, pobiv Idumejských v údolí slaném dvanácte tisíců. Bože, zavrhl jsi byl nás, roztrhls nás a hněvals se, navratiž se zase k nám.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 60, 2, 'Zatřásl jsi byl zemí a roztrhls ji, uzdraviž rozsedliny její, neboť se chvěje.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 60, 3, 'Ukazoval jsi lidu svému tvrdé věci, napájels nás vínem zkormoucení.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 60, 4, 'Ale nyní dal jsi těm, kteříž se tebe bojí, korouhev, aby ji vyzdvihli pro pravdu tvou. Sélah.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 60, 5, 'Ať jsou vysvobozeni milí tvoji, zachovávejž jich pravicí svou, a vyslyš mne.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 60, 6, 'Bůh mluvil skrze svatost svou, veseliti se budu, budu děliti Sichem, a údolí Sochot rozměřím.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 60, 7, 'Můjť jest Galád, můj i Manasses, a Efraim síla hlavy mé, Juda učitel můj.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 60, 8, 'Moáb medenice k umývání mému, na Edoma uvrhu obuv svou, proti mně, Palestino, trub.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 60, 9, 'Kdo mne uvede do města ohraženého? Kdo mne zprovodí až do Idumee?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 60, 10, 'Zdali ne ty, ó Bože, kterýž jsi nás byl zavrhl, a nevycházels, Bože, s vojsky našimi?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 60, 11, 'Uděliž nám pomoci před nepřítelem, nebo marná jest pomoc lidská.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 60, 12, 'V Bohu udatně sobě počínati budeme, a onť pošlapá nepřátely naše.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 61, 1, 'Přednímu z kantorů na neginot, Davidův. Slyš, ó Bože, volání mé, pozoruj modlitby mé.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 61, 2, 'Od konce země v sevření srdce svého k tobě volám, na skálu nade mne vyšší uvediž mne.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 61, 3, 'Nebo jsi býval mé útočiště, a pevná věže před tváří nepřítele.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 61, 4, 'Buduť bydliti v stánku tvém na věky, schráním se v skrýši křídel tvých. Sélah.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 61, 5, 'Ty jsi zajisté, Bože, vyslyšel žádosti mé, dal jsi dědictví bojícím se jména tvého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 61, 6, 'Ke dnům krále více dnů přidej, ať jsou léta jeho od národu do pronárodu,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 61, 7, 'Ať bydlí na věky před tváří Boží; milosrdenství a pravdu nastroj, ať ho ostříhají.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 61, 8, 'A tak žalmy zpívati budu jménu tvému na věky, a sliby své plniti budu den po dni.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 62, 1, 'Přednímu z kantorů Jedutunovi, žalm Davidův. Vždy předce k Bohu má se mlčelivě duše má, od něhoť jest spasení mé.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 62, 2, 'Vždyť předce on jest skála má, mé spasení, vysoký hrad můj, nepohnuť se škodlivě.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 62, 3, 'Až dokud zlé obmýšleti budete proti člověku? Všickni vy zahubeni budete, jako zed navážená a stěna nachýlená jste.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 62, 4, 'Však nic méně radí se o to, jak by jej odstrčili, aby nebyl vyvýšen; lež oblibují, ústy svými dobrořečí, ale u vnitřnosti své proklínají. Sélah.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 62, 5, 'Vždy předce měj se k Bohu mlčelivě, duše má, nebo od něho jest očekávání mé.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 62, 6, 'Onť jest zajisté skála má, mé spasení, vysoký hrad můj, nepohnuť se.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 62, 7, 'V Bohu jest spasení mé a sláva má; skála síly mé, doufání mé v Bohu jest.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 62, 8, 'Naději v něm skládejte všelikého času, ó lidé, vylévejte před oblíčejem jeho srdce vaše, Bůh útočiště naše. Sélah.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 62, 9, 'Jistě žeť jsou marnost synové lidští, a synové mocných lživí. Budou-li spolu na váhu vloženi, lehčejší budou nežli marnost.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 62, 10, 'Nedoufejtež v utiskování, ani v loupeži, a nebývejte marní; statku přibývalo-li by, nepřikládejte srdce.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 62, 11, 'Jednou mluvil Bůh, dvakrát jsem to slyšel, že Boží jest moc,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 62, 12, 'A že tvé, Pane, jest milosrdenství, a že ty odplatíš jednomu každému podlé skutků jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 63, 1, 'Žalm Davidův, když byl na poušti Judské. Bože, Bůh silný můj ty jsi, tebeť hned v jitře hledám, tebe žízní duše má, po tobě touží tělo mé, v zemi žíznivé a vyprahlé, v níž není vody,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 63, 2, 'Abych tě v svatyni tvé spatřoval, a viděl sílu tvou a slávu tvou,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 63, 3, '(Neboť jest lepší milosrdenství tvé, nežli život), aby tě chválili rtové moji,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 63, 4, 'A tak abych tobě dobrořečil, pokudž jsem živ, a ve jménu tvém pozdvihoval rukou svých.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 63, 5, 'Jako tukem a sádlem sytila by se tu duše má, a s radostným rtů prozpěvováním chválila by tě ústa má.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 63, 6, 'Jistě žeť na tě pamětliv jsem i na ložci svém, každého bdění nočního přemýšlím o tobě.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 63, 7, 'Nebo jsi mi býval ku pomoci, protož v stínu křídel tvých prozpěvovati budu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 63, 8, 'Přilnula duše má k tobě, pravice tvá zdržuje mne.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 63, 9, 'Pročež ti, kteříž hledají pádu duše mé, sami vejdou do největší hlubokosti země.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 63, 10, 'Zabijí každého z nich ostrostí meče, i budou liškám za podíl.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 63, 11, 'Král pak veseliti se bude v Bohu, i každý, kdož skrze něho přisahá, chlubiti se bude; nebo ústa mluvících lež zacpána budou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 64, 1, 'Přednímu z kantorů, žalm Davidův. Slyš, ó Bože, hlas můj, když naříkám, před hrůzou nepřítele ostříhej života mého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 64, 2, 'Skrej mne před úklady zlostníků, před zbouřením těch, kteříž páší nepravost,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 64, 3, 'Kteříž naostřili jako meč jazyk svůj, naměřili střelu svou, řeč přehořkou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 64, 4, 'Aby stříleli z skrýší na upřímého; nenadále naň vystřelují, aniž se koho bojí.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 64, 5, 'Zatvrzují se ve zlém, smlouvají se, jak by poléci mohli osídla, a říkají: Kdo je spatří?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 64, 6, 'Vyhledávají snažně nešlechetnosti, hyneme od ran přelstivých; takť vnitřnost a srdce člověka hluboké jest.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 64, 7, 'Ale jakž Bůh vystřelí na ně prudkou střelu, poraženi budou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 64, 8, 'A ku pádu je přivede vlastní jazyk jejich; vzdálí se jich každý, kdož by je viděl.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 64, 9, 'I budou se báti všickni lidé, a ohlašovati skutek Boží, a k srozumívání dílu jeho příčinu dadí.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 64, 10, 'Spravedlivý pak veseliti se bude v Hospodinu, a v něm doufati, anobrž chlubiti se budou všickni, kteříž jsou upřímého srdce.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 65, 1, 'Přednímu z kantorů žalm, Davidova píseň. Na tobě přestávati sluší, ó Bože, tebe na Sionu chváliti, a tu tobě slib vyplňovati.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 65, 2, 'Tu k tobě modlitbu vyslýchajícímu všeliké tělo přicházeti bude.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 65, 3, 'Mnohé nepravosti, kteréž se zmocnily nás, a přestoupení naše ty očistíš.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 65, 4, 'Blahoslavený, kohož vyvoluješ, a přivodíš, aby obýval v síňcích tvých. Tuť nasyceni budeme dobrým domu tvého, v svatyni chrámu tvého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 65, 5, 'Předivné věci podlé spravedlnosti nám mluvíš, Bože spasení našeho, naděje všech končin země i moře dalekého,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 65, 6, 'Kterýž upevňuješ hory mocí svou, silou jsa přepásán,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 65, 7, 'Kterýž skrocuješ zvuk moře, ječení vlnobití jeho, i bouření se národů,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 65, 8, 'Tak že se báti musejí obyvatelé končin zázraků tvých, kteréž nastáváním jitra a večera k plésání přivodíš.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 65, 9, 'Navštěvuješ zemi a svlažuješ ji, hojně ji obohacuješ. Potok Boží naplňován bývá vodami, i nastrojuješ obilé jejich, když ji tak spravuješ.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 65, 10, 'Záhony její svlažuješ, brázdy její snižuješ, dešti ji obměkčuješ, a zrostlinám jejím požehnání dáváš.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 65, 11, 'Korunuješ rok dobrotivostí svou, a šlepěje tvé kropí tučností;');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 65, 12, 'Skropují pastviště po pustinách, tak že i pahrbkové plésáním přepasováni bývají.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 65, 13, 'Přiodíny bývají roviny dobytkem, a údolí přistřína obilím, tak že radostí prokřikují, a prozpěvují.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 1, 'Přednímu z kantorů, píseň žalmu. Plésej Bohu všecka země.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 2, 'Zpívejte žalmy k slávě jména jeho, ohlašujte slávu a chválu jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 3, 'Rcete Bohu: Jak hrozný jsi v skutcích svých! Pro velikost síly tvé lháti budou tobě nepřátelé tvoji.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 4, 'Všecka země skláněti se tobě a prozpěvovati bude, žalmy zpívati bude jménu tvému. Sélah.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 5, 'Poďte a vizte skutky Boží, jak hrozný jest v správě při synech lidských.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 6, 'Obrátil moře v suchost, řeku přešli nohou po suše, tuť jsme se veselili v něm.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 7, 'Panuje v síle své nade vším světem, oči jeho spatřují národy, zpurní nebudou míti zniku. Sélah.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 8, 'Dobrořečte národové Bohu našemu, a ohlašujte hlas chvály jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 9, 'Zachoval při životu duši naši, aniž dopustil, aby se poklesla noha naše.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 10, 'Nebo jsi nás zpruboval, ó Bože, přečistil jsi nás, tak jako přečištěno bývá stříbro.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 11, 'Uvedl jsi nás byl do leči, krutě jsi bedra naše ssoužil,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 12, 'Vsadils člověka na hlavu naši, vešli jsme byli do ohně i do vody, a však jsi nás vyvedl do rozvlažení.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 13, 'A protož vejdu do domu tvého s zápalnými obětmi, a plniti tobě budu sliby své,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 14, 'Kteréž vyřkli rtové moji, a vynesla ústa má, když jsem byl v ssoužení.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 15, 'Zápaly tučných beranů obětovati budu tobě s kaděním, volů i kozlů nastrojím tobě. Sélah.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 16, 'Poďte, slyšte, a vypravovati budu, kteříž se koli bojíte Boha, co jest učinil duši mé.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 17, 'Ústy svými k němu jsem volal, a vyvyšoval jsem ho jazykem svým.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 18, 'Bychť byl patřil k nepravosti srdcem svým, nebyl by vyslyšel Pán.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 19, 'Ale vyslyšelť Bůh, a pozoroval hlasu modlitby mé.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 20, 'Požehnaný Bůh, kterýž neodstrčil modlitby mé, a milosrdenství svého ode mne neodjal.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 67, 1, 'Přednějšímu z kantorů na neginot, žalm k zpívání. Bože, smiluj se nad námi, a požehnej nám, zasvěť oblíčej svůj nad námi, Sélah,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 67, 2, 'Tak aby poznali na zemi cestu tvou, mezi všemi národy spasení tvé.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 67, 3, 'I budou tě oslavovati národové, ó Bože, oslavovati tě budou všickni lidé.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 67, 4, 'Veseliti se a prozpěvovati budou národové; nebo ty souditi budeš lidi v pravosti, a národy spravovati budeš na zemi. Sélah.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 67, 5, 'I budou tě oslavovati národové, ó Bože, oslavovati tě budou všickni lidé.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 67, 6, 'Země také vydá úrodu svou. Požehnání svého uděliž nám Bůh, Bůh náš;');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 67, 7, 'Požehnej nás Bůh, a bojtež se jeho všecky končiny země.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 1, 'Přednímu z kantorů, Davidův žalm k zpívání. Povstane Bůh, a rozprchnou se nepřátelé jeho, a utekou od tváři jeho ti, kteříž ho mají v nenávisti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 2, 'Jakož rozehnán bývá dým, tak je rozženeš; jakož se rozplývá vosk před ohněm, tak bezbožní zahynou před tváří Boží.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 3, 'Spravedliví pak veselíce se, poskakovati budou před Bohem, a plésati budou radostí.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 4, 'Prozpěvujte Bohu, žalmy zpívejte jménu jeho, vyrovnejte cestu tomu, kterýž se vznáší na oblacích. Hospodin jest jméno jeho, plésejtež před ním.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 5, 'Otec jest sirotků a ochránce vdov, Bůh v příbytku svatém svém.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 6, 'Bůh samotné rozmnožuje v domy, vyvodí vězně z okovů, zpurní pak bydliti musejí v zemi vyprahlé.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 7, 'Bože, když jsi předcházel lid svůj, když jsi kráčel po poušti, Sélah,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 8, 'Země se třásla, též i nebesa rozplývala se před tváří Boží, i ta hora Sinai před přítomností Boží, Boha Izraelského.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 9, 'Deštěm štědrosti hojné skropoval jsi, Bože, dědictví své, a když zemdlívalo, ty jsi je zase očerstvoval.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 10, 'Zástupové tvoji přebývají v něm, kteréžs ty nastrojil dobrotivostí svou pro chudého, ó Bože.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 11, 'Pán dal slovo své, i těch, kteréž potěšeně zvěstovaly, zástup veliký, řkoucích:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 12, 'Králové s vojsky utíkali, utíkali, a doma hlídající dělily kořisti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 13, 'Ačkoli jste mezi kotly ležeti musili, však jste jako holubice, mající křídla postříbřená, a brky z ryzího zlata.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 14, 'Když Všemohoucí rozptýlí krále v této zemi, zbělíš jako sníh na hoře Salmon.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 15, 'Hoře veliké, hoře v Bázan, hoře pahrbkovaté, hoře v Bázan.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 16, 'Pročež vyskakujete, hory pahrbkovaté? Na tétoť hoře zalíbilo se Bohu přebývati, jistě žeť na ní Hospodin na věky přebývati bude.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 17, 'Vozů Božích jest dvadceti tisíců, mnoho tisíců andělů, Pán pak mezi nimi jako na Sinai v svatyni přebývá.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 18, 'Vstoupil jsi na výsost, jaté jsi vedl vězně, vzal jsi dary pro lidi. I nejzpurnější k přebývání s námi, Hospodine Bože, přivozuješ.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 19, 'Požehnaný Pán, každého dne nás osýpá dary svými, Bůh silný spasení našeho. Sélah.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 20, 'Onť jest Bůh silný náš, Bůh silný k hojnému spasení. Hospodin Pán z smrti vyvodí.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 21, 'Raní zajisté Bůh hlavu nepřátel svých, a vrch hlavy vlasatý chodícího v hříších svých.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 22, 'Řekltě Pán: Zaseť vyvedu své, jako z Bázan, zase vyvedu z hlubokosti mořské.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 23, 'A protož noha tvá zbrocena bude ve krvi, i jazyk psů tvých krví nepřátelskou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 24, 'Spatřili slavné jití tvé, Bože, jití silného Boha mého a krále mého v svatyni.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 25, 'Napřed šli zpěváci, z zadu hrající na nástroje hudebné, u prostřed pak děvečky bubnující.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 26, 'V shromážděních dobrořečte Bohu Pánu, kteříž jste z národu Izraelského.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 27, 'Tu ať jest Beniamin maličký, kterýž je opanoval, tu knížata z Judy a houfové jejich, knížata z Zabulona, i knížata z Neftalíma.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 28, 'Obdařil tě Bůh tvůj silou. Potvrdiž, Bože, což jsi mezi námi vzdělal,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 29, 'Z chrámu svého nad Jeruzalémem, do něhož tobě přinášeti budou králové dary.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 30, 'Zahub zástup kopidlníků, sebrání mocných vůdců i lidu bujného, pyšně vykračující s kusy stříbra; rozptyl lidi žádostivé válek.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 31, 'Přijdouť nejvzácnější z Egypta, Mouřenínská země rychle vztáhne ruku svou k Bohu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 32, 'Království země zpívejte Bohu, žalmy zpívejte Pánu, Sélah,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 33, 'Tomu, kterýž se vznáší nad nebem nebes starodávních; aj, vydává hlas svůj, hlas přemocný.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 34, 'Dejte čest síly Bohu, jehož důstojnost nad Izraelem, a velikomocnost jeho na oblacích.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 35, 'Přehrozný jsi, ó Bože, z svatých příbytků svých. Bůh silný Izraelský, onť dává moc a sílu lidu svému, Bůh požehnaný.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 1, 'Přednímu z kantorů na šošannim, žalm Davidův. Vysvoboď mne, ó Bože, neboť jsou dosáhly vody až k duši mé.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 2, 'Pohřížen jsem v hlubokém bahně, v němž dna není; všel jsem do hlubokosti vod, jejichž proud zachvátil mne.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 3, 'Ustal jsem, volaje, vyschlo hrdlo mé, zemdlely oči mé od ohlídání se na tě Boha svého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 4, 'Více jest těch, kteříž mne nenávidí bez příčiny, než vlasů hlavy mé; zmocnili se ti, kteříž mne vyhladiti usilují, a jsou nepřátelé moji bez mého provinění; to, čehož jsem nevydřel, nahražovati jsem musil.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 5, 'Bože, ty znáš sám nemoudrost mou, a výstupkové moji nejsou skryti před tebou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 6, 'Nechť nebývají zahanbeni příčinou mou ti, kteříž na tě očekávají, Pane, Hospodine zástupů; nechť nepřicházejí skrze mne k hanbě ti, kteříž tě hledají, ó Bože Izraelský.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 7, 'Neboť pro tebe snáším pohanění, a stud přikryl tvář mou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 8, 'Cizí učiněn jsem bratřím svým, a cizozemec synům matky své,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 9, 'Proto že horlivost domu tvého snědla mne, a hanění hanějících tě na mne připadla.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 10, 'Když jsem plakal, postem trápiv duši svou, bylo mi to ku potupě obráceno.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 11, 'Když jsem bral na se pytel místo roucha, tehdy jsem jim byl za přísloví.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 12, 'Pomlouvali mne, sedíce v bráně, a písničkou byl jsem těm, kteříž pili víno.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 13, 'Já pak modlitbu svou k tobě odsílám, Hospodine, časť jest dobré líbeznosti tvé. Ó Bože, vedlé množství milosrdenství svého vyslyš mne, pro pravdu svou spasitelnou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 14, 'Vytrhni mne z bláta, abych nebyl pohřížen; nechť jsem vytržen od těch, kteříž mne nenávidí, jako z hlubokostí vod,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 15, 'Aby mne nezachvátili proudové vod, a nesehltila hlubina, ani se nade mnou zavřela prohlubně.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 16, 'Vyslyšiž mne, Hospodine, neboť jest dobré milosrdenství tvé; vedlé množství slitování svých vzhlédniž na mne.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 17, 'A neskrývej tváři své od služebníka svého, neboť mám úzkost; rychle vyslyš mne.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 18, 'Přibliž se k duši mé, a vyprosť ji; pro nepřátely mé vykup mne.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 19, 'Ty znáš pohanění mé, a zahanbení mé, i potupu mou, před tebouť jsou všickni nepřátelé moji.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 20, 'Pohanění potřelo srdce mé, pročež jsem byl v žalosti. Očekával jsem, zdali by mne kdo politoval, ale žádného nebylo, zdali by kdo potěšiti chtěli, ale nedočkal jsem.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 21, 'Nýbrž místo pokrmu poskytli mi žluči, a v žízni mé napájeli mne octem.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 22, 'Budiž jim stůl jejich před nimi za osídlo, a pokojný způsob jejich místo síti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 23, 'Ať se zatmí oči jejich, aby viděti nemohli, a bedra jejich k stálému přiveď zemdlení.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 24, 'Vylí na ně rozhněvání své, a prchlivost hněvu tvého ať je zachvátí.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 25, 'Budiž příbytek jejich pustý, v staních jejich kdo by obýval, ať není žádného.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 26, 'Nebo se tomu, jehož jsi ty zbil, protiví, a o bolesti zraněných tvých rozmlouvají.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 27, 'Přilož nepravost k nepravosti jejich, a ať nepřicházejí k spravedlnosti tvé.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 28, 'Nechť jsou vymazáni z knihy živých, a s spravedlivými ať nejsou zapsáni.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 29, 'Já pak ztrápený jsem, a bolestí sevřený, ale spasení tvé, ó Bože, na místě bezpečném postaví mne.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 30, 'I buduť chváliti jméno Boží s prozpěvováním, a velebiti je s děkováním.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 31, 'A bude to příjemnější Hospodinu nežli vůl, neb volek rohatý s rozdělenými kopyty.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 32, 'To když uhlédají tiší, radovati se budou, hledajíce Boha, a ožive srdce jejich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 33, 'Neboť vyslýchá chudé Hospodin, a vězni svými nezhrzí.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 34, 'Chvaltež ho nebesa a země, moře i všeliký hmyz jejich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 35, 'Bůhť zajisté zachová Sion, a vzdělá města Judská, i budou tu bydliti, a zemi tu dědičně obdrží.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 36, 'Tolikéž i símě služebníků jeho dědičně jí vládnouti budou, a milující jméno jeho v ní přebývati.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 70, 1, 'Přednímu z kantorů, žalm Davidův, k připomínání. Bože, abys mne vytrhl, Hospodine, abys mi spomohl, pospěš.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 70, 2, 'Zahanbeni buďte, a zapyřte se, kteříž hledají duše mé; zpět obráceni a v potupu dáni buďte, kteříž se kochají v neštěstí mém.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 70, 3, 'Zpět obráceni buďte za to, že mne k hanbě přivesti usilují ti, kteříž na mne povolávají: Hahá, hahá.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 70, 4, 'Ale ať se radují a veselí v tobě všickni ti, kteříž tě hledají, a ti, kteříž milují spasení tvé, ať říkají vždycky: Veleslaven budiž Bůh náš.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 70, 5, 'Já pak chudý a nuzný jsem, ó Bože, pospěšiž ke mně; pomoc má, a vysvoboditel můj ty jsi, neprodlévejž, Hospodine.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 1, 'V tebeť, Hospodine, doufám, nechť nejsem zahanben na věky.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 2, 'Vedlé spravedlnosti své vytrhni mne, a vyprosť mne; nakloň ke mně ucha svého, a spas mne.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 3, 'Budiž mi skalou obydlí, na niž bych ustavičně utíkal; přikázal jsi ostříhati mne, nebo skála má i pevnost má ty jsi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 4, 'Bože můj, vytrhni mne z ruky bezbožníka, z ruky převráceného a násilníka.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 5, 'Nebo ty jsi má naděje, Pane; Hospodine, v tebeť doufám od své mladosti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 6, 'Na tebe jsem zpolehl hned od života, z břicha matky mé ty jsi mne vyvedl, v tobě jest chvála má vždycky.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 7, 'Jako zázrak byl jsem mnohým, a však ty jsi mé silné doufání.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 8, 'Ó ať jsou naplněna ústa má chválením tebe, přes celý den slavením tebe.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 9, 'Nezamítejž mne v věku starosti; když zhyne síla má, neopouštějž mne.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 10, 'Nebo mluvili nepřátelé moji proti mně, a ti, jenž střehou duše mé, radili se spolu,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 11, 'Pravíce: Bůh jej opustil, hoňte a popadněte jej, nebo kdo by ho vytrhl, není žádného.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 12, 'Bože, nevzdalujž se ode mne, Bože můj, přispějž mi na pomoc.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 13, 'Nechť jsou zahanbeni, a zhynou protivníci duše mé; přikryti buďte lehkostí a hanbou, kteříž hledají pádu mého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 14, 'Já pak ustavičně čekati, a vždy víc a víc tě chváliti budu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 15, 'Ústa má budou vypravovati spravedlnost tvou, každého dne spasení tvé, ačkoli mu počtu nevím.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 16, 'Přistoupě k všelijaké moci Panovníka Hospodina, připomínati budu tvou vlastní spravedlnost.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 17, 'Bože, učinil jsi mne od mladosti mé, a až po dnes vypravuji o divných činech tvých.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 18, 'Protož také i do starosti a šedin, Bože, neopouštěj mne, až v známost uvedu rámě tvé tomuto věku, a všechněm potomkům sílu tvou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 19, 'Nebo spravedlnost tvá, Bože, vyvýšená jest, provodíš zajisté věci veliké. Bože, kdo jest podobný tobě?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 20, 'Kterýž ač jsi mi dal okusiti úzkostí velikých a hrozných, však zase k životu navrátíš mne, a z propastí země zase mne vyzdvihneš.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 21, 'Rozmnožíš důstojnost mou, a zase utěšíš mne.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 22, 'I jáť také budu tě slaviti na nástroji hudebném, i pravdu tvou, Bože můj; žalmy tobě zpívati budu na harfě, ó svatý Izraelský.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 23, 'Plésati budou rtové moji, když žalmy zpívati budu tobě, i duše má, kterouž jsi vykoupil.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 24, 'Nadto i jazyk můj každý den vypravovati bude spravedlnost tvou; nebo se zastyděti a zahanbiti musili ti, jenž mého pádu hledali.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 1, 'Šalomounovi. Bože, soudy své králi dej, a spravedlnost svou synu královu,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 2, 'Aby soudil lid tvůj v spravedlnosti a chudé tvé v pravosti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 3, 'Hory přinesou pokoj lidu i pahrbkové v spravedlnosti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 4, 'Souditi bude chudé z lidu, a vysvobodí syny nuzného, násilníka pak potře.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 5, 'Báti se budou tebe, dokudž slunce a měsíc trvati bude, od národu až do pronárodu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 6, 'Jako když sstupuje déšť na přisečenou trávu, a jako tiší déšťové skrápějící zemi:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 7, 'Tak zkvete ve dnech jeho spravedlivý, a bude hojnost pokoje, dokud měsíce stává.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 8, 'Panovati bude od moře až k moři, a od řeky až do končin země.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 9, 'Před ním skláněti se budou obyvatelé pustin vyprahlých, a nepřátelé jeho prach lízati budou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 10, 'Králové při moři a z ostrovů pocty mu přinesou, králové Šebejští a Sabejští dary obětovati budou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 11, 'Nadto klaněti se jemu budou všickni králové, všickni národové jemu sloužiti budou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 12, 'Nebo vytrhne nuzného, volajícího a nátisk trpícího, kterýž nemá spomocníka.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 13, 'Smiluje se nad bídným a potřebným, a duše nuzných spasí.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 14, 'Od lsti a násilí vysvobodí duši jejich; neboť jest drahá krev jejich před očima jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 15, 'Budeť dlouhověký, a dávati mu budou zlato Arabské, a ustavně za něj se modliti, na každý den jemu dobrořečiti budou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 16, 'Když se vrže hrst obilí do země na vrchu hor, klátiti se budou jako Libán klasové jeho, a kvésti budou měšťané jako byliny země.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 17, 'Jméno jeho bude na věky; dokudž slunce trvá, děditi bude jméno jeho. A požehnání sobě dávajíce v něm všickni národové, budou ho blahoslaviti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 18, 'Požehnaný Hospodin Bůh, Bůh Izraelský, kterýž sám činí divné věci,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 19, 'A požehnané jméno slávy jeho na věky. Budiž také naplněna slávou jeho všecka země, Amen i Amen.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 20, 'Skonávají se modlitby Davidovy, syna Izai.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 1, 'Žalm Azafovi. Jistě žeť jest Bůh dobrý Izraelovi, těm, kteříž jsou čistého srdce.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 2, 'Ale nohy mé téměř se byly ušinuly, o málo, že by byli sklouzli krokové moji,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 3, 'Když jsem horlil proti bláznivým, vida štěstí nešlechetných.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 4, 'Nebo nebývají vázáni až k smrti, ale zůstává v cele síla jejich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 5, 'V práci lidské nejsou, a s lidmi trestáni nebývají.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 6, 'Protož otočeni jsou pýchou jako halží, a ukrutností jako rouchem ozdobným přiodíni.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 7, 'Vysedlo tukem oko jejich; majíce hojnost nad pomyšlení srdce,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 8, 'Rozpustilí jsou, a mluví zlostně, o nátisku velmi pyšně mluví.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 9, 'Stavějí proti nebi ústa svá, a jazyk jejich po zemi se vozí.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 10, 'A protož na to přichází lid jeho, když se jim vody až do vrchu nalívá,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 11, 'Že říkají: Jakť má o tom věděti Bůh silný? Aneb zdaž jest to známé Nejvyššímu?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 12, 'Nebo aj, ti bezbožní jsouce, mají pokoj v světě, a dosahují zboží.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 13, 'Nadarmo tedy v čistotě chovám srdce své, a v nevinnosti ruce své umývám.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 14, 'Poněvadž každý den trestán bývám, a kázeň přichází na mne každého jitra.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 15, 'Řeknu-li: Vypravovati budu věci takové, hle, rodina synů tvých dí, že jsem jim křiv.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 16, 'Chtěl jsem to rozumem vystihnouti, ale vidělo mi se pracno.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 17, 'Až jsem všel do svatyní Boha silného, tu jsem srozuměl poslední věci jejich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 18, 'Jistě že jsi je na místech plzkých postavil, a uvržeš je v spustliny.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 19, 'Aj, jakť přicházejí na spuštění jako v okamžení! Mizejí a hynou hrůzami,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 20, 'Jako snové tomu, kdož procítí; Pane, když je probudíš, obraz ten jejich za nic položíš.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 21, 'Když zhořklo srdce mé, a ledví má bodena byla,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 22, 'Nesmyslný jsem byl, aniž jsem co znal, jako hovádko byl jsem před tebou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 23, 'A však vždycky jsem byl s tebou, nebo jsi mne ujal za mou pravici.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 24, 'Podlé rady své veď mne, a potom v slávu přijmeš mne.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 25, 'Kohož bych měl na nebi? A mimo tebe v žádném líbosti nemám na zemi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 26, 'Ač tělo i srdce mé hyne, skála srdce mého, a díl můj Bůh jest na věky.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 27, 'Nebo aj, ti, kteříž se vzdalují tebe, zahynou; vytínáš ty, kteříž cizoloží odcházením od tebe.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 28, 'Ale mně nejlépe jest přídržeti se Boha; pročež skládám v Panovníku Hospodinu doufání své, abych vypravoval všecky skutky jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 1, 'Vyučující, Azafův. Proč, ó Bože, nás tak do konce zamítáš? Proč roznícena jest prchlivost tvá proti stádci pastvy tvé?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 2, 'Rozpomeň se na shromáždění své, jehož jsi od starodávna dobyl a vykoupil, na proutek dědictví svého, na Sion horu tuto, na níž přebýváš.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 3, 'Přispějž k hrozným pustinám. Jak všecko pohubil nepřítel v svatyni!');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 4, 'Řvali nepřátelé tvoji u prostřed shromáždění tvých, a na znamení toho zanechali množství korouhví svých.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 5, 'Za hrdinu jmín byl ten, kterýž co nejvýše zdvihl sekeru, roubaje vazbu dříví jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 6, 'A nyní již řezby jeho napořád sekerami a palicemi otloukají.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 7, 'Uvrhli oheň do svatyně tvé, na zem zřítivše, poškvrnili příbytku jména tvého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 8, 'Řekli v srdci svém: Vyhubme je napořád. Takž vypálili všecky stánky Boha silného v zemi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 9, 'Znamení svých nevidíme, jižť není proroka, aniž jest mezi námi, kdo by věděl, dokud to stane.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 10, 'I dokudž, ó Bože, útržky činiti bude odpůrce? A nepřítel ustavičně-liž rouhati se bude jménu tvému?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 11, 'Proč zdržuješ ruku svou, a pravice své z lůna svého nevzneseš?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 12, 'Však jsi ty, Bože, král můj od starodávna, působíš hojné spasení u prostřed země.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 13, 'Ty silou svou rozdělil jsi moře, a potřels hlavy draků u vodách.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 14, 'Ty jsi potřel hlavu Leviatanovi, dal jsi jej za pokrm lidu na poušti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 15, 'Ty jsi otevřel vrchoviště a potoky, ty jsi osušil i řeky prudké.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 16, 'Tvůjť jest den, tvá jest také i noc, světlo i slunce ty jsi učinil.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 17, 'Ty jsi založil všecky končiny země, léto i zimy ty jsi sformoval.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 18, 'Rozpomeniž se na to, že útržky činil ten odpůrce Hospodinu, a lid bláznivý jak se jménu tvému rouhal.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 19, 'Nevydávejž té zběři duše hrdličky své, na stádce chudých svých nezapomínej se na věky.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 20, 'Ohlédni se na smlouvu; nebo plní jsou i nejtmavější koutové země peleší ukrutnosti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 21, 'Nechažť bídní neodcházejí s hanbou, chudý a nuzný ať chválí jméno tvé.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 22, 'Povstaniž, ó Bože, a veď při svou, rozpomeň se na pohanění, kteréžť se děje od nesmyslných na každý den.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 23, 'Nezapomínej se na vykřikování svých nepřátel, a na hluk proti tobě povstávajících, kterýž se silí ustavičně.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 75, 1, 'Přednímu z kantorů, jako: Nezahlazuj, žalm Azafův, a píseň. Oslavujeme tě, Bože, oslavujeme; nebo že jest blízké jméno tvé, vypravují to předivní skutkové tvoji.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 75, 2, 'Když přijde čas uložený, já právě souditi budu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 75, 3, 'Rozplynula se země i všickni obyvatelé její, já utvrdím sloupy její. Sélah.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 75, 4, 'Dím bláznům: Neblázněte, a bezbožným: Nevyzdvihujte rohů.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 75, 5, 'Nevyzdvihujte proti Nejvyššímu rohů svých, aniž mluvte tvrdošijně.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 75, 6, 'Nebo ne od východu, ani západu, ani od pouště přichází zvýšení;');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 75, 7, 'Ale Bůh soudce jednoho ponižuje, a druhého povyšuje.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 75, 8, 'Kalich zajisté jest v rukou Hospodinových, a to vína kalného plný nalitý, z něhož nalévati bude, tak že i kvasnice jeho vyváží, a vypijí všickni bezbožníci země.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 75, 9, 'Já pak zvěstovati budu skutky Páně na věčnost, žalmy zpívati budu Bohu Jákobovu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 75, 10, 'A všecky rohy bezbožníků srážím, rohové pak spravedlivého vyvýšeni budou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 76, 1, 'Přednímu z kantorů na neginot, žalm Azafův a píseň. Znám jest Bůh v Judstvu, a v Izraeli veliké jméno jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 76, 2, 'V Sálem jest stánek jeho, a obydlé jeho na Sionu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 76, 3, 'Tamť jest polámal ohnivé šípy lučišť, pavézu a meč, i válku. Sélah.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 76, 4, 'Slavný jsi učiněn a důstojný horami loupeže.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 76, 5, 'V loupež dáni jsou udatní srdcem, zesnuli snem svým, aniž nalezly zmužilé hrdiny síly v rukou svých.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 76, 6, 'Od žehrání tvého, ó Bože Jákobův, i vůz i kůň tvrdě zesnuli.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 76, 7, 'Ty jsi, ty velmi hrozný, a kdo jest, ješto by před tebou ostál v rozhněvání tvém?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 76, 8, 'Když s nebe dáváš slyšeti výpověd svou, země se bojí a tichne,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 76, 9, 'Když povstává k soudu Bůh, aby zachoval všecky pokorné na zemi. Sélah.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 76, 10, 'Zajisté i hněv člověka chváliti tě musí, a ostatek zůřivosti skrotíš.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 76, 11, 'Sliby čiňte a plňte Hospodinu Bohu vašemu; kteřížkoli jste vůkol něho, přinášejte dary Přehroznému.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 76, 12, 'Onť odjímá ducha knížatům, a k hrůze jest králům zemským.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 1, 'Přednímu kantoru z potomků Jedutunových, s Azafem, žalm. Hlas můj k Bohu, když volám, hlas můj k Bohu, aby ucha naklonil ke mně.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 2, 'V den ssoužení svého Pána hledal jsem, v noci ruce své rozprostíral jsem bez přestání, a nedala se potěšiti duše má.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 3, 'Na Boha zpomínal jsem a kormoutil se, přemyšloval jsem, a úzkostmi svírán byl duch můj. Sélah.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 4, 'Zdržoval jsi oči mé, aby bděly; potřín jsem byl, aniž jsem mluviti mohl.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 5, 'I přicházeli mi na pamět dnové předešlí, a léta dávní.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 6, 'Rozpomínal jsem se v noci na zpěvy své, v srdci svém přemyšloval jsem, a zpytoval to duch můj, pravě:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 7, 'Zdali na věky zažene Bůh? Nikdy-liž již více lásky neukáže?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 8, 'Zdali do konce přestane milosrdenství jeho? A konec vezme slovo od pokolení až do pokolení?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 9, 'Zdali se zapomněl smilovávati Bůh silný? Zdaž zadržel v hněvě milosrdenství svá? Sélah.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 10, 'I řekl jsem: Toť jest má smrt. Ale učiníť proměnu pravice Nejvyššího.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 11, 'Rozpomínati se budu na skutky Hospodinovy, a připomínati sobě divné činy tvé, od starodávna.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 12, 'A přemyšlovati o všelikém díle tvém, a o skutcích tvých mluviti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 13, 'Bože, svatá jest cesta tvá. Kdo jest silný, veliký, jako Bůh?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 14, 'Ty jsi ten Bůh silný, jenž činíš divné věci; uvedl jsi v známost mezi národy sílu svou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 15, 'Vysvobodil jsi ramenem lid svůj, syny Jákobovy a Jozefovy. Sélah.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 16, 'Vidělyť jsou tě vody, Bože, viděly tě vody, a zstrašily se; pohnuly se také i hlubiny.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 17, 'Vydali povodně oblakové, vydala hřmot nebesa, ano i kameníčko tvé skákalo.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 18, 'Vznělo hřímání tvé po obloze, blýskání osvěcovalo okršlek zemský, pohybovala se a třásla země.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 19, 'Skrze moře byla cesta tvá, a stezky tvé skrze vody veliké, a však šlepějí tvých nebylo znáti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 20, 'Vedl jsi jako stádo lid svůj skrze Mojžíše a Arona.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 1, 'Vyučující, Azafovi. Pozoruj, lide můj, zákona mého, nakloňte uší svých k slovům úst mých.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 2, 'Otevru v podobenství ústa svá, vypravovati budu přípovídky starobylé.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 3, 'Co jsme slýchali i poznali, a co nám otcové naši vypravovali,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 4, 'Nezatajíme toho před syny jejich, kteříž budoucím potomkům svým vypravovati budou chvály Hospodinovy, ano i moc jeho a divné skutky jeho, kteréž činil.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 5, 'Neboť jest vyzdvihl svědectví v Jákobovi, a zákon vydal v Izraeli, což přikázal otcům našim, aby v známost uvodili synům svým,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 6, 'Aby to poznal věk potomní, synové, kteříž se zroditi měli, a ti povstanouce, aby vypravovali dítkám svým,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 7, 'Aby pokládali v Bohu naději svou, a nezapomínali se na skutky Boha silného, ale ostříhali přikázaní jeho,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 8, 'Aby nebývali jako otcové jejich, pokolení zpurné a protivné, národ, kterýž nenapravil srdce svého, a nebyl věrný Bohu silnému duch jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 9, 'Jako synové Efraim zbrojní, ač uměle z lučiště stříleli, však v čas boje zpět se obrátili,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 10, 'Nebo neostříhali smlouvy Boží, a v zákoně jeho zpěčovali se choditi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 11, 'Zapomenuli se na činy jeho, a na divné skutky jeho, kteréž jim ukázal.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 12, 'Před otci jejich činil divy v zemi Egyptské, na poli Soan.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 13, 'Rozdělil moře, a převedl je; učinil, aby stály vody jako hromada.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 14, 'Vedl je ve dne v oblace, a každé noci v jasném ohni.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 15, 'Protrhl skály na poušti, a napájel je jako z propastí velikých.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 16, 'Vyvedl potoky z skály, a učinil, aby vody tekly jako řeky.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 17, 'A však vždy přičíněli hříchů proti němu, a popouzeli Nejvyššího na poušti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 18, 'A pokoušeli Boha silného v srdci svém, žádajíce pokrmu podlé líbosti své.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 19, 'A mluvili proti Bohu, řkouce: Zdaliž bude moci Bůh silný připraviti stůl na této poušti?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 20, 'Aj, udeřilť jest v skálu, a tekly vody, a řeky se rozvodnily. Zdali také bude moci dáti chleba? Zdali nastrojí masa lidu svému?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 21, 'A protož uslyšav Hospodin, rozhněval se, a oheň zažžen jest proti Jákobovi, a prchlivost vstoupila na Izraele,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 22, 'Proto že se nedověřili Bohu, a neměli naděje v spasení jeho,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 23, 'Ačkoli rozkázal oblakům shůry, a průduchy nebeské otevřel,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 24, 'A dštil na ně mannou ku pokrmu, a obilé nebeské dával jim.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 25, 'Chléb mocných jedl člověk, seslal jim pokrmů do sytosti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 26, 'Obrátil vítr východní u povětří, a přivedl mocí svou vítr polední.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 27, 'I dštil na ně masem jako prachem, a ptactvem pernatým jako pískem mořským.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 28, 'Spustil je do prostřed vojska jejich, a všudy vůkol stanů jejich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 29, 'I jedli, a nasyceni jsou hojně, a dal jim to, čehož žádali.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 30, 'Ještě nevyplnili žádosti své, ještě pokrm byl v ústech jejich,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 31, 'A v tom prchlivost Boží připadla na ně, a zbil tučné jejich, a přední Izraelské porazil.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 32, 'S tím se vším vždy ještě hřešili, a nevěřili předivným skutkům jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 33, 'A protož dopustil na ně, že marně skonali dny své, a léta svá s chvátáním.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 34, 'Když je hubil, jestliže ho hledali, a zase k Bohu silnému hned na úsvitě se navraceli,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 35, 'Rozpomínajíce se na to, že Bůh byl skála jejich, a Bůh silný nejvyšší vykupitel jejich:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 36, '(Ačkoli mu s pochlebenstvím mluvili ústy svými, a jazykem svým lhali jemu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 37, 'A srdce jejich nebylo upřímé před ním, aniž se věrně měli v smlouvě jeho),');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 38, 'On jsa milosrdný, odpouštěl nepravosti jejich, a nezahladil jich; častokrát odvracel hněv svůj, a nevzbuzoval vší zůřivosti své.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 39, 'Nebo pamatoval, že jsou tělo, vítr, kterýž odchází, a nenavracuje se zase.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 40, 'Kolikrát jsou ho dráždili na poušti, a k bolesti přivodili na pustinách.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 41, 'Týž i týž navracujíce se, pokoušeli Boha silného, a svatému Izraelskému cíle vyměřovali.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 42, 'Nepamatovali na moc jeho, a na ten den, v kterémž je vysvobodil z ssoužení,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 43, 'Když činil v Egyptě znamení svá, a zázraky své na poli Soan,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 44, 'Když obrátil v krev řeky a potoky jejich, tak že jich píti nemohli.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 45, 'Dopustil na ně směsici žížal, aby je žraly, a žáby, aby je hubily.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 46, 'A dal chroustům úrody jejich, a úsilí jejich kobylkám.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 47, 'Stloukl krupami réví jejich, a stromy fíkové jejich ledem.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 48, 'Vydal krupobití na hovada jejich, a na dobytek jejich uhlí řeřavé.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 49, 'Poslal na ně prchlivost hněvu svého, rozpálení, zůřivost i ssoužení, dopustiv na ně anděly zlé.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 50, 'Uprostrannil stezku prchlivosti své, neuchoval od smrti duše jejich, ano i na hovada jejich mor dopustil.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 51, 'A pobil všecko prvorozené v Egyptě, prvotiny síly v staních Chamových.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 52, 'Ale lid svůj vyvedl jako ovce, a vodil se s nimi jako s stádem po poušti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 53, 'Vodil je v bezpečnosti, tak že nestrašili, nepřátely pak jejich přikrylo moře,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 54, 'Až je přivedl ku pomezí svatosti své, na horu tu, kteréž dobyla pravice jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 55, 'Vyhnav před tváří jejich národy, způsobil to, aby jim na provazec dědictví jejich přišli, a aby přebývala v staních jejich pokolení Izraelská.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 56, 'Však vždy předce pokoušeli a dráždili Boha nejvyššího, a svědectví jeho neostříhali.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 57, 'Ale zpět odšedše, převráceně činili, jako i předkové jejich; uchýlili se jako mylné lučiště.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 58, 'Nebo popouzeli ho výsostmi svými, a rytinami svými k horlení přivedli jej.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 59, 'Slyšel Bůh, a rozhněval se, a u velikou ošklivost vzal Izraele,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 60, 'Tak že opustiv příbytek v Sílo, stánek, kterýž postavil mezi lidmi,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 61, 'Vydal v zajetí sílu svou, a slávu svou v ruce nepřítele.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 62, 'Dal pod meč lid svůj, a na dědictví své se rozhněval.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 63, 'Mládence jeho sežral oheň, a panny jeho nebyly chváleny.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 64, 'Kněží jejich od meče padli, a vdovy jejich neplakaly.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 65, 'Potom pak procítil Pán jako ze sna, jako silný rek, kterýž po víně sobě vykřikuje.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 66, 'A ranil nepřátely své po zadu, a u věčné pohanění je vydal.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 67, 'Ačkoli pak pohrdl stánkem Jozefovým, a pokolení Efraimova nevyvolil,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 68, 'Však vyvolil pokolení Judovo, horu Sion, kterouž zamiloval.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 69, 'A vystavěl sobě, jako hrad vysoký, svatyni svou, jako zemi, kterouž utvrdil na věky.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 70, 'A vyvolil Davida služebníka svého, vzav jej od chlévů stáda.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 71, 'Když chodil za ovcemi březími, zavedl jej, aby pásl Jákoba, lid jeho, a Izraele, dědictví jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 72, 'Kterýž pásl je v upřímnosti srdce svého, a zvláštní opatrností rukou svých vodil je.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 79, 1, 'Žalm Azafovi. Bože, vtrhli pohané do dědictví tvého, poškvrnili chrámu svatosti tvé, obrátili Jeruzalém v hromady.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 79, 2, 'Dali těla mrtvá služebníků tvých za pokrm ptákům nebeským, těla svatých tvých šelmám zemským.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 79, 3, 'Vylili krev jejich jako vodu okolo Jeruzaléma, a nebyl, kdo by je pochovával.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 79, 4, 'Vydáni jsme v pohanění sousedům našim, v posměch a žert těm, kteříž jsou vůkol nás.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 79, 5, 'Až dokud, ó Hospodine? Na věky-liž se hněvati budeš, a hořeti bude jako oheň horlení tvé?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 79, 6, 'Vylí hněv svůj na národy, kteříž tě neznají, a na království, kteráž jména tvého nevzývají.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 79, 7, 'Neboť jsou sežrali Jákoba, a obydlí jeho v poustku obrátili.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 79, 8, 'Nezpomínejž nám dřevních nepravostí našich, rychle ať předejdou nás milosrdenství tvá, neboť jsme velmi znuzeni.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 79, 9, 'Pomoz nám, ó Bože spasení našeho, pro slávu jména svého; vytrhni nás, a buď milostiv hříchům našim pro jméno své.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 79, 10, 'Proč mají říkati pohané: Kdež jest Bůh jejich? Budiž znám mezi pohany, před očima našima, skrze pomstu krve služebníků svých, kteráž jest vylita.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 79, 11, 'Vstupiž před oblíčej tvůj lkání vězňů, a podlé velikosti síly své zanechej ostatků k smrti oddaných.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 79, 12, 'A odplať sousedům našim sedmernásobně do lůna jejich za pohanění, kteréž jsou tobě činili, ó Pane.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 79, 13, 'My pak, lid tvůj a ovce pastvy tvé, slaviti tě budeme na věky; od národu do pronárodu vypravovati budeme chválu tvou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 1, 'Přednímu z kantorů na šošannim, žalm svědectví, Azafovi. Ó pastýři Izraelský, pozoruj, kterýž vodíš Jozefa jako stádo, kterýž sedíš nad cherubíny, ó zastkvějž se.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 2, 'Před Efraimem, Beniaminem a Manasse vzbuď moc svou, a přispěj k spasení našemu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 3, 'Ó Bože, navrať nás, a dejž, ať nám svítí oblíčej tvůj, a spaseni budeme.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 4, 'Hospodine Bože zástupů, dokudž se přísně stavěti budeš k modlitbám lidu svého?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 5, 'Nakrmil jsi je chlebem pláče, a dals jim vypiti slz míru velikou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 6, 'Postavils nás k sváru sousedům našim, a nepřátelé naši aby sobě posměch z nás činili.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 7, 'Ó Bože zástupů, navrať nás, a dej, ať nám svítí oblíčej tvůj, a spaseni budeme.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 8, 'Ty jsi kmen vinný z Egypta přenesl, vyhnal jsi pohany, a vsadils jej.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 9, 'Uprázdnil jsi mu, a učinils, aby se vkořenil, i zemi naplnil.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 10, 'Přikryty jsou hory stínem jeho, a réví jeho jako nejvyšší cedrové.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 11, 'Vypustil ratolesti své až k moři, a až do řeky rozvody své.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 12, 'I pročež jsi rozbořil hradbu vinice, tak aby každý, kdož by tudy šel, trhati z ní mohl?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 13, 'Vepř divoký zryl ji, a zvěř polní spásla ji.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 14, 'Ó Bože zástupů, obrať se již, popatř s nebe, viz a navštěv kmen vinný tento,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 15, 'Vinici tu, kterouž štípila pravice tvá, a mladistvé réví, kteréž jsi zmocnil sobě.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 16, 'Popálenať jest ohněm a poroubána, od žehrání oblíčeje tvého hyne.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 17, 'Budiž ruka tvá nad mužem pravice tvé, nad synem člověka, kteréhož jsi zmocnil sobě,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 18, 'A neodstoupímeť od tebe; zachovej nás při životu, ať jméno tvé vzýváme.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 19, 'Hospodine Bože zástupů, navratiž nás zase, a dej, ať nám svítí oblíčej tvůj, a spaseni budeme.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 81, 1, 'Přednímu z kantorů na gittit, Azafovi. Plésejte Bohu, síle naší, prokřikujte Bohu Jákobovu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 81, 2, 'Vezměte žaltář, přidejte buben, harfu libou a loutnu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 81, 3, 'Trubte trubou na novměsíce, v uložený čas, v den slavnosti naší.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 81, 4, 'Nebo toť jest ustavení v Izraeli, řád Boha Jákobova.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 81, 5, 'Na svědectví v Jozefovi vyzdvihl jej, když byl vyšel proti zemi Egyptské, kdež jsme jazyk neznámý slýchati musili.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 81, 6, 'Osvobodil jsem, dí Bůh, od břemene rameno jeho, a ruce jeho nádob zednických zproštěny byly.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 81, 7, 'V ssoužení tom, když jsi volal, vytrhl jsem tě, vyslyšel jsem tě z skrýše hromu, zkušoval jsem tě při vodách sváru. Sélah.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 81, 8, 'Řeklť jsem: Slyš, lide můj, a osvědčím se tobě, ó Izraeli, budeš-li mne poslouchati,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 81, 9, 'A nebude-li mezi vámi Boha jiného, a nebudeš-li se klaněti bohu cizímu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 81, 10, 'Já jsem Hospodin Bůh tvůj, kterýž jsem tě vyvedl z země Egyptské, otevři jen ústa svá, a naplnímť je.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 81, 11, 'Ale neuposlechl lid můj hlasu mého, a Izrael nepřestal na mně,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 81, 12, 'A protož pustil jsem je v žádost srdce jejich, i chodili po radách svých.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 81, 13, 'Ó byť mne byl lid můj poslouchal, a Izrael po cestách mých chodil,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 81, 14, 'Tudíž bych já byl nepřátely jejich snížil, a na protivníky jejich obrátil ruku svou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 81, 15, 'A ti, kteříž v nenávisti mají Hospodina, úlisně by se jim poddávati musili, i byl by čas jejich až na věky.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 81, 16, 'A krmil bych je byl jádrem pšenice, a medem z skály sytil bych je.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 82, 1, 'Žalm Azafův. Bůh stojí v shromáždění Božím, u prostřed bohů soud čině, a dí:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 82, 2, 'Dokudž souditi budete nespravedlivě, a osoby nešlechetných přijímati? Sélah.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 82, 3, 'Zastávejte bídného a sirotka, utištěného a chudého spravedliva vyhlašujte.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 82, 4, 'Vytrhněte bídného a nuzného, z ruky nešlechetných vytrhněte ho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 82, 5, 'Ale nevědí nic, nerozumějí nic; ve tmách ustavně chodí, až se proto všickni základové země pohybují.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 82, 6, 'Řeklť jsem já byl: Bohové jste, a synové Nejvyššího vy všickni;');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 82, 7, 'A však jako i jiní lidé zemřete, a jako jeden z knížat padnete.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 82, 8, 'Povstaniž, ó Bože, suď zemi; nebo ty dědičně vládneš všemi národy.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 1, 'Píseň a žalm Azafův. Bože, neodmlčujž se, nečiň se neslyše, aniž se upokojuj, ó Bože silný.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 2, 'Nebo aj, nepřátelé tvoji se bouří, a ti, kteříž tě v nenávisti mají, pozdvihují hlavy.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 3, 'Chytře tajné rady proti lidu tvému skládají, a radí se proti těm, kteréž ty skrýváš,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 4, 'Říkajíce: Poďte, a vyhlaďme je, ať nejsou národem, tak aby ani zpomínáno nebylo více jména Izraelova.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 5, 'Jednomyslněť se na tom spolu snesli, i smlouvou se proti tobě zavázali,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 6, 'Stánkové Idumejští a Izmaelitští, Moábští a Agarenští,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 7, 'Gebálští a Ammonitští, a Amalechitští, Filistinští s obyvateli Tyrskými.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 8, 'Ano i Assyrští spojili se s nimi, jsouce na ruku synům Lotovým. Sélah.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 9, 'Učiniž jim jako Madianským, jako Zizarovi, a jako Jabínovi při potoku Císon,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 10, 'Kteříž jsou do konce vyhlazeni v Endor, a učiněni hnůj země.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 11, 'Nalož s nimi a s vůdci jejich jako s Gorébem, jako s Zébem, jako s Zebahem, a jako s Salmunou, se všemi knížaty jejich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 12, 'Neboť jsou řekli: Uvažme se dědičně v příbytky Boží.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 13, 'Můj Bože, učiň to, ať jsou jako chumelice, a jako stéblo před větrem.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 14, 'Jakož oheň spaluje les, a jako plamen zapaluje hory,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 15, 'Tak ty je vichřicí svou stihej, a bouří svou ohrom je.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 16, 'Naplň tváře jejich zahanbením, tak aby hledali jména tvého, Hospodine.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 17, 'Nechať se hanbí a děsí na věčné časy, a ať potupu nesou a zahynou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 18, 'A tak ať poznají, že ty, kterýž sám jméno máš Hospodin, jsi nejvyšší nade vší zemí.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 84, 1, 'Přednímu z kantorů na gittit, synů Chóre, žalm. Jak jsou milí příbytkové tvoji, Hospodine zástupů!');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 84, 2, 'Žádostiva jest a velice touží duše má po síňcích Hospodinových; srdce mé, i tělo mé pléše k Bohu živému.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 84, 3, 'Ano i ten vrabec nalezl sobě místo a vlaštovice hnízdo, v němž by schránila mladé své, při oltářích tvých, Hospodine zástupů, králi můj a Bože můj.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 84, 4, 'Blahoslavení, kteříž přebývají v domě tvém, tiť tebe na věky chváliti budou. Sélah.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 84, 5, 'Blahoslavený člověk, jehož síla jest Hospodin, a v jejichž srdci jsou stezky kroků jejich,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 84, 6, 'Ti, kteříž jdouce přes údolí moruší, za studnici jej sobě pokládají, na něž i déšť požehnání přichází.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 84, 7, 'Berou se houf za houfem, a ukazují se před Bohem na Sionu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 84, 8, 'Hospodine Bože zástupů, vyslyš modlitbu mou, pozoruj, ó Bože Jákobův. Sélah.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 84, 9, 'Pavézo naše, popatř, ó Bože, a viz tvář pomazaného svého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 84, 10, 'Nebo lepší jest den v síňcích tvých, než jinde tisíc; zvolil jsem sobě raději u prahu seděti v domě Boha svého, nežli přebývati v stáncích bezbožníků.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 84, 11, 'Nebo Hospodin Bůh jest slunce a pavéza; tuť milosti i slávy udílí Hospodin, aniž odepře čeho dobrého chodícím v upřímnosti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 84, 12, 'Hospodine zástupů, blahoslavený člověk, kterýž naději skládá v tobě.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 85, 1, 'Přednímu z kantorů, synů Chóre, žalm. Laskavěs se, Hospodine, někdy ukazoval k zemi své, přivedls zase z vězení Jákoba.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 85, 2, 'Odpustil jsi nepravost lidu svého, přikryls všeliký hřích jejich. Sélah.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 85, 3, 'Zdržels všecken hněv svůj, odvrátils od zůřivosti prchlivost svou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 85, 4, 'Navratiž se zase k nám, ó Bože spasení našeho, a učiň přítrž hněvu svému proti nám.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 85, 5, 'Zdaliž na věky hněvati se budeš na nás? A protáhneš zůřivost svou od národu do pronárodu?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 85, 6, 'Zdaliž ty obrátě se, neobživíš nás, tak aby se lid tvůj veselil v tobě?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 85, 7, 'Ukaž nám, Hospodine, milosrdenství své, a spasení své dej nám.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 85, 8, 'Ale poslechnu, co říká Bůh ten silný, Hospodin. Jistě žeť mluví pokoj k lidu svému, a k svatým svým, než aby se nenavracovali zase k bláznovství.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 85, 9, 'Zajisté žeť jest blízké těm, kteříž se ho bojí, spasení jeho, a přebývati bude sláva v zemi naší.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 85, 10, 'Milosrdenství a víra potkají se spolu, spravedlnost a pokoj dadí sobě políbení.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 85, 11, 'Víra z země pučiti se bude, a spravedlnost s nebe vyhlédati.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 85, 12, 'Dáť také Hospodin i časné dobré, tak že země naše vydá úrody své.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 85, 13, 'Způsobí to, aby spravedlnost před ním šla, když obrátí k cestě nohy své.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 86, 1, 'Modlitba Davidova. Nakloň, Hospodine, ucha svého, a vyslyš mne, neboť jsem chudý a nuzný.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 86, 2, 'Ostříhejž duše mé, neboť jsem ten, jehož miluješ; zachovej služebníka svého, ty Bože můj, v tobě naději majícího.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 86, 3, 'Smiluj se nade mnou, Hospodine, k toběť zajisté každého dne volám.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 86, 4, 'Potěš duše služebníka svého, neboť k tobě, ó Pane, duše své pozdvihuji.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 86, 5, 'Nebo ty jsi, Pane, dobrotivý a lítostivý, a hojný v milosrdenství ke všechněm, kteříž tě vzývají.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 86, 6, 'Slyš, Hospodine, modlitbu mou, a pozoruj hlasu žádostí mých.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 86, 7, 'V den ssoužení svého vzývám tě, nebo mne vyslýcháš.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 86, 8, 'Neníť žádného tobě podobného mezi bohy, ó Pane, a není takových skutků, jako jsou tvoji.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 86, 9, 'Všickni národové, kteréž jsi učinil, přicházejíce, skláněti se budou před tebou, Pane, a ctíti jméno tvé.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 86, 10, 'Nebo jsi ty veliký, a činíš divné věci, ty jsi Bůh sám.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 86, 11, 'Vyuč mne, Hospodine, cestě své, abych chodil v pravdě tvé; ustav srdce mé v bázni jména svého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 86, 12, 'I budu tě oslavovati, Pane Bože můj, z celého srdce svého a ctíti jméno tvé na věky,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 86, 13, 'Poněvadž milosrdenství tvé veliké jest nade mnou, a vytrhls duši mou z jámy nejhlubší.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 86, 14, 'Ó Bože, povstaliť jsou pyšní proti mně, a rota násilníků hledají bezživotí mého, ti, kteříž tě sobě nepředstavují.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 86, 15, 'Ale ty Pane, Bože silný, lítostivý a milostivý, shovívající a hojný v milosrdenství, i pravdomluvný,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 86, 16, 'Vzhlédniž na mne, a smiluj se nade mnou, obdař silou svou služebníka svého, a zachovávej syna děvky své.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 86, 17, 'Prokaž ke mně znamení dobrotivosti, tak aby vidouce to ti, kteříž mne nenávidí, zahanbeni byli, že jsi ty mi, Hospodine, spomohl, a mne potěšil.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 87, 1, 'Synům Chóre, žalm a píseň. Základ svůj na horách svatých.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 87, 2, 'Milujeť Hospodin, totiž brány Sionské, nade všecky příbytky Jákobovy.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 87, 3, 'Přeslavnéť jsou to věci, kteréž se o tobě hlásají, ó město Boží. Sélah.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 87, 4, 'Připomínati budu Egypt a Babylon před svými známými, ano i Filistinské a Tyrské i Mouřeníny, že se tu každý z nich narodil.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 87, 5, 'An i o Sionu praveno bude: Ten i onen jest rodem z něho, sám pak Nejvyšší utvrdí jej.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 87, 6, 'Sečteť Hospodin při popisu národy, a dí, že tento se tu narodil. Sélah.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 87, 7, 'Tou příčinou zpívají s plésáním o tobě všecky moci života mého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 1, 'Píseň a žalm synů Chóre, přednímu zpěváku na machalat k zpívání, vyučující, složený od Hémana Ezrachitského. Hospodine, Bože spasení mého, ve dne i v noci k tobě volám.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 2, 'Vstupiž před oblíčej tvůj modlitba má, nakloň ucha svého k volání mému.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 3, 'Neboť jest naplněna trápeními duše má, a život můj až k hrobu se přiblížil.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 4, 'Počten jsem mezi ty, kteříž se dostávají do jámy; připodobněn jsem člověku beze vší síly.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 5, 'Mezi mrtvé jsem odložen, jako zmordovaní ležící v hrobě, na něž nezpomínáš více, kteříž od ruky tvé vyhlazeni jsou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 6, 'Spustils mne do jámy nejzpodnější, do nejtemnějšího a nejhlubšího místa.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 7, 'Dolehla na mne prchlivost tvá, a vším vlnobitím svým přikvačil jsi mne. Sélah.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 8, 'Daleko jsi vzdálil mé známé ode mne, jimž jsi mne velice zošklivil, a tak jsem sevřín, že mi nelze nijakž vyjíti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 9, 'Zrak můj hyne trápením; na každý den vzývám tě, Hospodine, ruce své před tebou rozprostíraje.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 10, 'Zdali před mrtvými učiníš zázrak? Aneb vstanou-liž mrtví, aby tě oslavovali?Sélah.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 11, 'I zdali bude ohlašováno v hrobě milosrdenství tvé, a pravda tvá v zahynutí?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 12, 'Zdaliž v známost přichází ve tmách div tvůj, a spravedlnost tvá v zemi zapomenutí?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 13, 'Já pak, Hospodine, k tobě volám, a každého jitra předchází tě modlitba má.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 14, 'Pročež, ó Hospodine, zamítáš mne, a tvář svou skrýváš přede mnou?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 15, 'Ztrápený jsem, jako hned maje umříti od násilí; snáším hrůzy tvé, a děsím se.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 16, 'Hněv tvůj přísný na mne se obořil, a hrůzy tvé krutě sevřely mne.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 17, 'Obkličují mne jako voda, na každý den obstupují mne hromadně.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 18, 'Vzdálil jsi ode mne přítele a tovaryše, a známým svým jsem ve tmě.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 1, 'Vyučující, složený od Etana Ezrachitského. O milosrdenstvích Hospodinových na věky zpívati budu, od národu do pronárodu zvěstovati budu pravdu tvou ústy svými.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 2, 'Nebo jsem řekl: Na věky milosrdenství vzdělávati se bude, na nebi utvrdíš pravdu svou, o nížs řekl:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 3, 'Učinil jsem smlouvu s vyvoleným svým, přisáhl jsem Davidovi služebníku svému,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 4, 'Že až na věky utvrdím símě tvé, a vzdělám od národu do národu trůn tvůj. Sélah.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 5, 'Protož oslavují nebesa div tvůj, Hospodine, i pravdu tvou v shromáždění svatých.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 6, 'Nebo kdo na nebi přirovnán býti může Hospodinu? Kdo jest podobný Hospodinu mezi syny silných?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 7, 'Bůh i v shromáždění svatých strašlivý jest náramně, a hrozný nade všecky vůkol něho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 8, 'Hospodine Bože zástupů, kdo jest jako ty, silný Hospodin? Nebo pravda tvá tobě přístojí všudy vůkol.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 9, 'Ty panuješ nad dutím moře; když se zdvihají vlny jeho, ty je skrocuješ.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 10, 'Ty jsi jako raněného potřel Egypt, a silným ramenem svým rozptýlil jsi nepřátely své.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 11, 'Tváť jsou nebesa, tvá také i země, okršlek i plnost jeho ty jsi založil.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 12, 'Půlnoční i polední strana, kteréž jsi ty stvořil, i Tábor a Hermon o tvém jménu zpívají.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 13, 'Tvé rámě jest přemocné, silná ruka tvá, a vyvýšená pravice tvá.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 14, 'Spravedlnost a soud jsou základem trůnu tvého, milosrdenství a pravda předcházejí tvář tvou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 15, 'Blahoslavený lid, kterýž zná zvuk tvůj; tiť, Hospodine, v světle oblíčeje tvého choditi budou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 16, 'Ve jménu tvém plésati budou každého dne, a v spravedlnosti tvé vyvýší se.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 17, 'Nebo sláva síly jejich ty jsi, a z milosti tvé k zvýšení přijde roh náš.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 18, 'Nebo štít náš jest Hospodinův, a svatého Izraelského král náš.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 19, 'Tehdy mluvě u vidění k svatému svému, řekl jsi: Složil jsem pomoc v reku udatném, zvýšil jsem vybraného z lidu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 20, 'Nalezl jsem Davida služebníka svého, olejem svým svatým pomazal jsem ho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 21, 'A protož budeť s ním stále ruka má, ano i ramenem svým posilovati ho budu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 22, 'Nebudeť ho moci nuziti nepřítel, ani člověk nešlechetný trápiti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 23, 'Nebo potru před tváří jeho protivníky jeho, a ty, kteříž ho nenávidí, porazím.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 24, 'Nadto pravda má a milosrdenství mé s ním bude, a ve jménu mém vyvýšen bude roh jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 25, 'A vložím na moře ruku jeho, a na řeky pravici jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 26, 'On volaje ke mně, dí: Ty jsi otec můj, Bůh silný můj a skála spasení mého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 27, 'Já také za prvorozeného vystavím jej, a za vyššího králů zemských.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 28, 'Na věky zachovám jemu milosrdenství své, a smlouva s ním stálá bude.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 29, 'Učiním i to, aby na věky trvalo símě jeho, a trůn jeho jako dnové nebes.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 30, 'Jestliže by pak synové jeho opustili zákon můj, a v soudech mých nechodili,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 31, 'Jestliže by ustanovení mých poškvrnili, a přikázaní mých neostříhali:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 32, 'Tedy navštívím metlou přestoupení jejich, a trestáním nepravost jejich,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 33, 'Ale milosrdenství svého neodejmu od něho, aniž klamati budu proti pravdě své.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 34, 'Nepoškvrnímť smlouvy své, a toho, což vyšlo z úst mých, nezměním.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 35, 'Jednou jsem přisáhl skrze svatost svou, nesklamámť Davidovi,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 36, 'Že símě jeho na věky bude, a trůn jeho jako slunce přede mnou,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 37, 'Jako měsíc utvrzeno bude na věky, a jako svědkové na obloze hodnověrní.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 38, 'Ale ty jsi jej zavrhl a potupil, rozhněvals se na pomazaného svého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 39, 'Zavrhl jsi smlouvu s služebníkem svým, povrhls korunu jeho na zem.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 40, 'Roztrhal jsi všecky ohrady jeho, a bašty jeho jsi rozválel.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 41, 'Derou jej všickni, kteříž tudy jdou; jest ku posměchu i sousedům svým.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 42, 'Vyvýšil jsi pravici protivníků jeho, obveselils všecky nepřátely jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 43, 'Ztupils i ostří meče jeho, aniž jsi dal jemu, aby ostáti mohl v boji.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 44, 'Učinils přítrž okrase jeho, a trůn jeho svrhl jsi na zem.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 45, 'Ukrátil jsi dnů mladosti jeho, a hanbous jej přiodíl. Sélah.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 46, 'Až dokud, Hospodine? Na věky-liž se skrývati budeš? Tak-liž hořeti bude jako oheň prchlivost tvá?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 47, 'Rozpomeniž se na mne, jak kratičký jest věk můj. Zdaliž jsi pak nadarmo stvořil všecky syny lidské?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 48, 'Kdo z lidí může tak živ býti, aby neokusil smrti? Kdo vytrhne život svůj z hrobu? Sélah.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 49, 'Kdež jsou milosrdenství tvá první, ó Pane? Přísahuť jsi učinil Davidovi, v pravdě své.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 50, 'Pamatuj, Pane, na útržky činěné služebníkům tvým, a jak jsem já nosil v lůně svém potupu ode všech nejmocnějších národů,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 51, 'Jak jsou utrhali nepřátelé tvoji, Hospodine, jak jsou utrhali šlepějím pomazaného tvého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 52, 'Budiž pochválen Hospodin na věky, Amen i Amen.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 90, 1, 'Modlitba Mojžíše, muže Božího. Pane, ty jsi býval příbytek náš od národu do pronárodu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 90, 2, 'Prvé, než hory stvořeny byly, nežlis sformoval zemi, a okršlek světa, ano hned od věků a až na věky, ty jsi Bůh silný.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 90, 3, 'Ty přivodíš člověka na to, aby setřín byl, říkaje: Navraťtež se zase, synové lidští.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 90, 4, 'Nebo by tisíc let přetrval, jest to před očima tvýma jako den včerejší, a bdění noční.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 90, 5, 'Povodní zachvacuješ je; jsou sen, a jako bylina hned v jitře pomíjející.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 90, 6, 'Toho jitra, kteréhož vykvetne, mění se, u večer pak jsuc podťata, usychá.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 90, 7, 'Ale my hyneme od hněvu tvého, a prchlivostí tvou jsme zděšeni.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 90, 8, 'Nebo jsi položil nepravosti naše před sebe, a tajnosti naše na světlo oblíčeje svého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 90, 9, 'Pročež všickni dnové naši v náhle přebíhají pro tvé rozhněvání; k skončení let svých docházíme jako řeč.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 90, 10, 'Všech dnů let našich jest let sedmdesáte, aneb jest-li kdo silnějšího přirození, osmdesát let, a i to, což nejzdárnějšího v nich, jest práce a bída, a když to pomine, tožť ihned rychle zaletíme.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 90, 11, 'Ale kdo jest, ješto by znal přísnost hněvu tvého, a ostýchal se zůřivosti tvé?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 90, 12, 'Naučiž nás počítati dnů našich, abychom uvodili moudrost v srdce.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 90, 13, 'Navrať se zase, Hospodine, až dokud prodléváš? Mějž lítost nad služebníky svými.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 90, 14, 'Nasyť nás hned v jitře svým milosrdenstvím, tak abychom prozpěvovati, a veseliti se mohli po všecky dny naše.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 90, 15, 'Obveseliž nás podlé dnů, v nichž jsi nás ssužoval, a let, v nichž jsme okoušeli zlého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 90, 16, 'Budiž zřejmé při služebnících tvých dílo tvé, a okrasa tvá při synech jejich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 90, 17, 'Budiž nám přítomná i ochotnost Hospodina Boha našeho, a díla rukou našich potvrď mezi námi, díla, pravím, rukou našich potvrď.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 91, 1, 'Ten, kdož v skrýši Nejvyššího přebývá, v stínu Všemohoucího odpočívati bude.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 91, 2, 'Dím Hospodinu: Útočiště mé a hrad můj, Bůh můj, v němž naději skládati budu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 91, 3, 'Onť zajisté vysvobodí tě z osídla lovce, a od nejjedovatějšího nakažení morního.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 91, 4, 'Brky svými přikryje tě, a pod křídly jeho bezpečen budeš; místo štítu a pavézy budeš míti pravdu jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 91, 5, 'Nebudeš se báti přístrachu nočního, ani střely létající ve dne.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 91, 6, 'Ani nakažení morního, vlekoucího se v mrákotě, ani povětří morního, v polední čas hubícího.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 91, 7, 'Padne jich po boku tvém tisíc, a deset tisíců po pravici tvé, ale k tobě se to nepřiblíží.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 91, 8, 'Očima toliko svýma to spatříš, a odplatě bezbožných se podíváš.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 91, 9, 'Poněvadž jsi Hospodina, kterýž útočiště mé jest, a Nejvyššího za svůj příbytek položil,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 91, 10, 'Nepřihodí se tobě nic zlého, aniž se přiblíží jaká rána k stánku tvému.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 91, 11, 'Nebo andělům svým přikázal o tobě, aby tě ostříhali na všech cestách tvých.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 91, 12, 'Na rukou ponesou tě, abys neurazil o kámen nohy své.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 91, 13, 'Po lvu a bazališku choditi budeš, a pošlapáš lvíče i draka.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 91, 14, 'Poněvadž mne, dí Bůh, zamiloval, vysvobodím jej, a vyvýším; nebo poznal jméno mé.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 91, 15, 'Vzývati mne bude, a vyslyším jej; já s ním budu v ssoužení, vytrhnu a oslavím jej.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 91, 16, 'Dlouhostí dnů jej nasytím, a ukáži jemu spasení své.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 92, 1, 'Žalm a píseň, ke dni sobotnímu. Dobré jest oslavovati Hospodina, a žalmy zpívati jménu tvému, ó Nejvyšší,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 92, 2, 'Zvěstovati každé jitro milosrdenství tvé, a pravdu tvou každé noci,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 92, 3, 'Při nástroji o desíti strunách, při loutně, a při harfě s písničkou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 92, 4, 'Nebo jsi mne rozveselil, Hospodine, skutky svými, o skutcích rukou tvých zpívati budu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 92, 5, 'Jak velicí jsou skutkové tvoji, Hospodine! Velmi hluboká jsou myšlení tvá.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 92, 6, 'Člověk hovadný nezná toho, aniž blázen rozumí tomu,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 92, 7, 'Že vyrostají bezbožní jako bylina, a kvetou všickni činitelé nepravosti, aby vyhlazeni byli na věky.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 92, 8, 'Ty pak, ó Nejvyšší, že na věky jsi Hospodin.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 92, 9, 'Nebo aj, nepřátelé tvoji, Hospodine, nebo aj, nepřátelé tvoji zahynou; rozptýleni budou všickni činitelé nepravosti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 92, 10, 'Můj pak roh vyzdvihneš jako jednorožcův, pokropen budu olejem novým.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 92, 11, 'I podívá se oko mé na ty, jenž mne špehují, a o těch nešlechetnících, jenž proti mně povstávají, ušima svýma uslyším.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 92, 12, 'Spravedlivý jako palma kvésti bude, a jako cedr na Libánu rozloží se.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 92, 13, 'Štípení v domě Hospodinově v síňcích Boha našeho kvésti budou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 92, 14, 'Ještě i v šedinách ovoce ponesou, spanilí a zelení budou,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 92, 15, 'Aby to zvěstováno bylo, že přímý jest Hospodin, skála má, a že nepravosti žádné při něm není.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 93, 1, 'Hospodin kraluje, v důstojnost se oblékl, oblékl se Hospodin v sílu, a přepásal se; také okršlek země upevnil, aby se nepohnul.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 93, 2, 'Utvrzenť jest trůn tvůj přede všemi časy, od věčnosti ty jsi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 93, 3, 'Pozdvihují se řeky, ó Hospodine, pozdvihují řeky zvuku svého, pozdvihují řeky vlnobití svých.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 93, 4, 'Nad zvuk mnohých vod, nad sílu vln mořských mnohem silnější jest na výsostech Hospodin.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 93, 5, 'Svědectví tvá jsou velmi jistá, domu tvému ušlechtilá svatost, Hospodine, až na věky.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 1, 'Bože silný pomst, Hospodine, Bože silný pomst, zastkvěj se.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 2, 'Zdvihni se, ó soudce vší země, a dej odplatu pyšným.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 3, 'Až dokud bezbožní, Hospodine, až dokud bezbožní budou plésati,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 4, 'Žváti a hrdě mluviti, honosíce se, všickni činitelé nepravosti?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 5, 'Lid tvůj, Hospodine, potírati a dědictví tvé bědovati?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 6, 'Vdovy a příchozí mordovati, a sirotky hubiti,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 7, 'Říkajíce: Nehledíť na to Hospodin, aniž tomu rozumí Bůh Jákobův?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 8, 'Rozumějte, ó vy hovadní v lidu, a vy blázni, kdy srozumíte?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 9, 'Zdali ten, jenž učinil ucho, neslyší? A kterýž stvořil oko, zdali nespatří?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 10, 'Zdali ten, jenž tresce národy, nebude kárati, kterýž učí lidi umění?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 11, 'Hospodinť zná myšlení lidská, že jsou pouhá marnost.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 12, 'Blahoslavený jest ten muž, kteréhož ty cvičíš, Hospodine, a z zákona svého jej vyučuješ.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 13, 'Abys mu způsobil pokoj před časy zlými, až by za tím vykopána byla bezbožníku jáma.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 14, 'Neboť neopustí Hospodin lidu svého, a dědictví svého nezanechá,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 15, 'Ale až k spravedlnosti navrátí se soud, a za ním všickni upřímého srdce.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 16, 'Kdož by se byl o mne zasadil proti zlostníkům? Kdo by se byl za mne postavil proti těm, jenž páší nepravost?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 17, 'Kdyby mi Hospodin nebyl ku pomoci, tudíž by se byla octla duše má v mlčení.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 18, 'Již jsem byl řekl: Klesla noha má, ale milosrdenství tvé, ó Hospodine, zdrželo mne.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 19, 'Ve množství přemyšlování mých u vnitřnosti mé, tvá potěšování obveselovala duši mou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 20, 'Zdaliž se k tobě přitovaryší stolice převráceností těch, jenž vynášejí nátisk mimo spravedlnost,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 21, 'Jenž se shlukují proti duši spravedlivého, a krev nevinnou odsuzují?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 22, 'Ale Hospodin jest mým hradem vysokým, a Bůh můj skalou útočiště mého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 23, 'Onť obrátí na ně nepravost jejich, a zlostí jejich zahladí je, zahladí je Hospodin Bůh náš.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 95, 1, 'Poďte, zpívejme Hospodinu, prokřikujme skále spasení našeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 95, 2, 'Předejděme oblíčej jeho s díkčiněním, žalmy prozpěvujme jemu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 95, 3, 'Nebo Hospodin jest Bůh veliký, a král veliký nade všecky bohy,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 95, 4, 'V jehož rukou základové země, a vrchové hor jeho jsou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 95, 5, 'Jehož jest i moře, nebo on je učinil, i země, kterouž ruce jeho sformovaly.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 95, 6, 'Poďte, sklánějme se, a padněme před ním, klekejme před Hospodinem stvořitelem naším.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 95, 7, 'Onť jest zajisté Bůh náš, a my jsme lid pastvy jeho, a stádo rukou jeho. Dnes uslyšíte-li hlas jeho,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 95, 8, 'Nezatvrzujte srdce svého, jako při popuzení, a v den pokušení na poušti,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 95, 9, 'Kdežto pokoušeli mne otcové vaši, zkusiliť jsou mne, a viděli skutky mé.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 95, 10, 'Za čtyřidceti let měl jsem nesnáz s národem tím, a řekl jsem: Lid tento bloudí srdcem, a nepoznali cest mých.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 95, 11, 'Jimž jsem přisáhl v hněvě svém, že nevejdou v odpočinutí mé.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 96, 1, 'Zpívejte Hospodinu píseň novou, zpívej Hospodinu všecka země.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 96, 2, 'Zpívejte Hospodinu, dobrořečte jménu jeho, zvěstujte den po dni spasení jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 96, 3, 'Vypravujte mezi národy slávu jeho, mezi všemi lidmi divy jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 96, 4, 'Nebo veliký Hospodin, a vší chvály hodný, i hrozný jest nade všecky bohy.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 96, 5, 'Všickni zajisté bohové národů jsou modly, ale Hospodin nebesa učinil.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 96, 6, 'Sláva a důstojnost před ním, síla i okrasa v svatyni jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 96, 7, 'Vzdejte Hospodinu čeledi národů, vzdejte Hospodinu čest i moc.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 96, 8, 'Vzdejte Hospodinu čest jména jeho, přineste dary, a vejděte do síňcí jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 96, 9, 'Sklánějte se Hospodinu v okrase svatosti, boj se oblíčeje jeho všecka země.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 96, 10, 'Rcete mezi pohany: Hospodin kraluje, a že i okršlek zemský upevněn bude, tak aby se nepohnul, a že souditi bude lidi spravedlivě.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 96, 11, 'Rozveseltež se nebesa, a plésej země, zvuč moře, i což v něm jest.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 96, 12, 'Plésej pole a vše, což na něm, tehdáž ať prozpěvuje všecko dříví lesní,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 96, 13, 'Před tváří Hospodina; neboť se béře, béře se zajisté, aby soudil zemi. Budeť souditi okršlek světa v spravedlnosti, a národy v pravdě své.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 97, 1, 'Hospodin kraluje, plésej země, a vesel se ostrovů všecko množství.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 97, 2, 'Oblak a mrákota jest vůkol něho, spravedlnost a soud základ trůnu jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 97, 3, 'Oheň předchází jej, a zapaluje vůkol nepřátely jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 97, 4, 'Zasvěcujíť se po okršlku světa blýskání jeho; to viduc země, děsí se.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 97, 5, 'Hory jako vosk rozplývají se před oblíčejem Hospodina, před oblíčejem Panovníka vší země.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 97, 6, 'Nebesa vypravují o jeho spravedlnosti, a slávu jeho spatřují všickni národové.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 97, 7, 'Zastyďte se všickni, kteříž sloužíte rytinám, kteříž se chlubíte modlami; sklánějte se před ním všickni bohové.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 97, 8, 'To uslyše Sion, rozveselí se, a zpléší dcery Judské z příčiny soudů tvých, Hospodine.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 97, 9, 'Nebo ty, Hospodine, jsi nejvyšší na vší zemi, a velice jsi vyvýšený nade všecky bohy.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 97, 10, 'Vy, kteříž milujete Hospodina, mějte v nenávisti to, což zlého jest; onť ostříhá duší svatých svých, a z ruky bezbožníků je vytrhuje.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 97, 11, 'Světlo vsáto jest spravedlivým, a radost těm, kteříž jsou upřímého srdce.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 97, 12, 'Veselte se, spravedliví v Hospodinu, a oslavujte památku svatosti jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 98, 1, 'Žalm. Zpívejte Hospodinu píseň novou, neboť jest divné věci učinil; spomohla mu pravice jeho, a rámě svatosti jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 98, 2, 'V známost uvedl Hospodin spasení své, před očima národů zjevil spravedlnost svou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 98, 3, 'Rozpomenul se na milosrdenství své, a na pravdu svou k domu Izraelskému; všecky končiny země vidí spasení Boha našeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 98, 4, 'Prokřikuj Hospodinu všecka země; zvuk vydejte, prozpěvujte, a žalmy zpívejte.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 98, 5, 'Žalmy zpívejte Hospodinu na citaře, k citaře i hlasem přizpěvujte.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 98, 6, 'Trubami a zvučnými pozouny hlas vydejte před králem Hospodinem.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 98, 7, 'Zvuč moře i to, což v něm jest, okršlek světa i ti, kteříž na něm bydlí.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 98, 8, 'Řeky rukama plésejte, spolu i hory prozpěvujte,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 98, 9, 'Před Hospodinem; neboť se béře, aby soudil zemi. Budeť souditi okršlek světa v spravedlnosti, a národy v pravosti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 99, 1, 'Hospodin kraluje, užasněte se národové; sedí nad cherubíny, pohniž se země.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 99, 2, 'Hospodin na Sionu veliký, a vyvýšený jest nade všecky lidi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 99, 3, 'Oslavujte jméno tvé veliké a hrozné, nebo svaté jest.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 99, 4, 'Moc zajisté králova miluje soud; ty jsi ustanovil práva, soud a spravedlnost v Jákobovi ty konáš.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 99, 5, 'Vyvyšujte Hospodina Boha našeho, a sklánějte se u podnoží noh jeho, svatýť jest.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 99, 6, 'Mojžíš a Aron mezi kněžími jeho, a Samuel mezi vzývajícími jméno jeho; volávali k Hospodinu, a on je vyslýchal.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 99, 7, 'V sloupu oblakovém mluvíval k nim; kteřížto když ostříhali svědectví jeho, i ustanovení jim vydal.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 99, 8, 'Hospodine Bože náš, tys je vyslýchal, Bože, bývals jim milostiv, i když jsi je trestal pro výstupky jejich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 99, 9, 'Vyvyšujte Hospodina Boha našeho, a sklánějte se na hoře svaté jeho; neboť jest svatý Hospodin Bůh náš.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 100, 1, 'Žalm k díků činění. Prokřikuj Hospodinu všecka země.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 100, 2, 'Služte Hospodinu s veselím, předstupte před oblíčej jeho s prozpěvováním.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 100, 3, 'Vězte, že Hospodin jest Bůh; on učinil nás, a ne my sami sebe, abychom byli lid jeho, a ovce pastvy jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 100, 4, 'Vcházejte do bran jeho s díkčiněním, a do síní jeho s chvalami; oslavujte jej, a dobrořečte jménu jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 100, 5, 'Nebo dobrý jest Hospodin, na věky milosrdenství jeho, a od národu až do pronárodu pravda jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 101, 1, 'Žalm Davidův. O milosrdenství a soudu zpívati budu, tobě, ó Hospodine, žalmy budu zpívati.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 101, 2, 'Opatrně se míti budu na cestě přímé, až přijdeš ke mně; choditi budu ustavičně v upřímnosti srdce svého i v domě svém.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 101, 3, 'Nepředstavímť sobě před oči věci nešlechetné; skutek uchylujících se v nenávisti mám, nepřichytíť se mne.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 101, 4, 'Srdce převrácené odstoupí ode mne, zlého nebudu oblibovati.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 101, 5, 'Škodícího jazykem bližnímu svému tajně, tohoť vytnu; očí vysokých a mysli naduté nikoli nebudu moci trpěti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 101, 6, 'Oči mé na pravdomluvné v zemi, aby sedali se mnou; kdož chodí po cestě upřímé, tenť mi sloužiti bude.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 101, 7, 'Nebude bydliti v domě mém činící lest, a mluvící lež nebude míti místa u mne.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 101, 8, 'Každého jitra pléniti budu všecky nešlechetné z země, abych tak vyplénil z města Hospodinova všecky, kdož páší nepravost.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 1, 'Modlitba chudého, když sevřín jsa, před Hospodinem vylévá žádosti své. Hospodine, slyš modlitbu mou, a volání mé přijdiž k tobě.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 2, 'Neskrývej tváři své přede mnou, v den ssoužení mého nakloň ke mně ucha svého; když k tobě volám, rychle vyslyš mne.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 3, 'Nebo mizejí jako dým dnové moji, a kosti mé jako ohniště vypáleny jsou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 4, 'Poraženo jest jako bylina, a usvadlo srdce mé, tak že jsem chleba svého jísti zapomenul.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 5, 'Od hlasu lkání mého přilnuly kosti mé k kůži mé.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 6, 'Podobný jsem učiněn pelikánu na poušti, jsem jako výr na pustinách.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 7, 'Bdím, a jsem jako vrabec osamělý na střeše.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 8, 'Každý den utrhají mi nepřátelé moji, a posměvači moji proklínají mnou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 9, 'Nebo jídám popel jako chléb, a k nápoji svému slz přiměšuji,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 10, 'Pro rozhněvání tvé a zažžený hněv tvůj; nebo zdvihna mne, hodils mnou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 11, 'Dnové moji jsou jako stín nachýlený, a já jako tráva usvadl jsem.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 12, 'Ale ty, Hospodine, na věky zůstáváš, a památka tvá od národu až do pronárodu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 13, 'Ty povstana, smiluješ se nad Sionem, nebo čas jest učiniti milost jemu, a čas uložený přišel.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 14, 'Nebo líbost mají služebníci tvoji v kamení jeho, a nad prachem jeho slitují se,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 15, 'Aby se báli pohané jména Hospodinova, a všickni králové země slávy tvé,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 16, 'Když by Hospodin vzdělal Sion, a ukázal se v slávě své,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 17, 'Když by popatřil k modlitbě poníženého lidu, nepohrdaje modlitbou jejich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 18, 'Budeť to zapsáno pro budoucí potomky, a lid, kterýž má stvořen býti, chváliti bude Hospodina,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 19, 'Že shlédl s výsosti svatosti své. Hospodin s nebe na zemi že popatřil,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 20, 'Aby vyslyšel vzdychání vězňů, a rozvázal ty, kteříž již k smrti oddání byli,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 21, 'Aby vypravovali na Sionu jméno Hospodinovo, a chválu jeho v Jeruzalémě,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 22, 'Když se spolu shromáždí národové a království, aby sloužili Hospodinu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 23, 'Ztrápilť jest na cestě sílu mou, ukrátil dnů mých,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 24, 'Až jsem řekl: Můj Bože, nebeř mne u prostřed dnů mých; od národu zajisté až do pronárodu jsou léta tvá,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 25, 'I prvé nežlis založil zemi, a dílo rukou svých, nebesa.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 26, 'Onať pominou, ty pak zůstáváš; všecky ty věci jako roucho zvetšejí, jako oděv změníš je, a změněny budou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 27, 'Ty pak jsi tentýž, a léta tvá nikdy nepřestanou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 28, 'Synové služebníků tvých bydliti budou, a símě jejich zmocní se před tebou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 1, 'Davidův. Dobrořeč duše má Hospodinu, a všecky vnitřnosti mé jménu svatému jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 2, 'Dobrořeč duše má Hospodinu, a nezapomínej se na všecka dobrodiní jeho,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 3, 'Kterýž odpouští tobě všecky nepravosti, kterýž uzdravuje všecky nemoci tvé,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 4, 'Kterýž vysvobozuje od zahynutí život tvůj, kterýž tě korunuje milosrdenstvím a mnohým slitováním,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 5, 'Kterýž nasycuje dobrými věcmi ústa tvá, tak že se obnovuje jako orlice mladost tvá.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 6, 'Činí, což spravedlivého jest, Hospodin, a soudy všechněm utištěným.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 7, 'Známé učinil Mojžíšovi cesty své, synům Izraelským skutky své.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 8, 'Lítostivý a milostivý jest Hospodin, dlouhoshovívající a mnohého milosrdenství.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 9, 'Nebudeť ustavičně žehrati, ani na věky hněvu držeti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 10, 'Ne podlé hříchů našich nakládá s námi, ani vedlé nepravostí našich odplacuje nám.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 11, 'Nebo jakož jsou vysoko nebesa nad zemí, tak jest vyvýšené milosrdenství jeho nad těmi, kteříž se ho bojí.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 12, 'A jak daleko jest východ od západu, tak daleko vzdálil od nás přestoupení naše.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 13, 'Jakož se slitovává otec nad dítkami, tak se slitovává Hospodin nad těmi, kteříž se ho bojí.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 14, 'Onť zajisté zná slepení naše, v paměti má, že prach jsme.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 15, 'Dnové člověka jsou jako tráva, a jako květ polní, tak kvete.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 16, 'Jakž vítr na něj povane, anť ho není, aniž ho již více pozná místo jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 17, 'Milosrdenství pak Hospodinovo od věků až na věky nad těmi, kteříž se ho bojí, a spravedlnost jeho nad syny synů,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 18, 'Kteříž ostříhají smlouvy jeho, a pamatují na přikázaní jeho, aby je činili.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 19, 'Hospodin na nebesích utvrdil trůn svůj, a kralování jeho nade vším panuje.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 20, 'Dobrořečte Hospodinu andělé jeho, kteříž jste mocní v síle, a činíte slovo jeho, poslušní jsouc hlasu slova jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 21, 'Dobrořečte Hospodinu všickni zástupové jeho, služebníci jeho, kteříž činíte vůli jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 22, 'Dobrořečte Hospodinu všickni skutkové jeho, na všech místech panování jeho. Dobrořeč duše má Hospodinu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 1, 'Dobrořeč duše má Hospodinu. Hospodine Bože můj, velmi jsi veliký, velebnost a krásu jsi oblékl.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 2, 'Přioděls se světlem jako rouchem, roztáhls nebesa jako kortýnu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 3, 'Kterýž sklenul na vodách paláce své, kterýž užívá hustých oblaků místo vozů, a vznáší se na peří větrovém.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 4, 'Kterýž činí posly své duchy, služebníky své oheň plápolající.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 5, 'Založil zemi na sloupích jejich, tak že se nepohne na věky věků.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 6, 'Propastí jako rouchem byl jsi ji přioděl, i nad horami stály vody.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 7, 'K žehrání tvému rozběhly se, před hřmotem hromu tvého pospíšily,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 8, '(Vystoupily hory, snížilo se údolí), na místo, kteréž jsi jim založil.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 9, 'Meze jsi položil, aby jich nepřestupovaly, ani se navracovaly k přikrývání země.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 10, 'Kterýž vypouštíš potoky přes údolé, aby tekli mezi horami,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 11, 'A nápoj dávali všechněm živočichům polním. Tuť uhašují oslové divocí žízeň svou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 12, 'Při nich hnízdí se ptactvo nebeské, a z prostřed ratolestí hlas svůj vydává.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 13, 'Kterýž svlažuješ hory z výsostí svých, aby ovocem činů tvých sytila se země.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 14, 'Dáváš, aby rostla tráva dobytku, a bylina ku potřebě člověku, abys tak vyvodil chléb z země,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 15, 'A víno, jenž obveseluje srdce člověka. Činí, aby se stkvěla tvář od oleje, ano i pokrmem zdržuje život lidský.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 16, 'Nasyceno bývá i dříví Hospodinovo, cedrové Libánští, kteréž štípil.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 17, 'Na nichž se ptáci hnízdí, i čáp příbytek svůj má na jedlí.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 18, 'Hory vysoké jsou kamsíků, skály útočiště králíků.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 19, 'Učinil měsíc k jistým časům, a slunce zná západ svůj.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 20, 'Uvodíš tmu, a bývá noc, v níž vybíhají všickni živočichové lesní:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 21, 'Lvíčata řvoucí po loupeži, aby hledali od Boha silného pokrmu svého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 22, 'Když slunce vychází, zase shromažďují se, a v doupatech svých se ukládají.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 23, 'Člověk vychází ku práci své, a k dílu svému až do večera.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 24, 'Jak mnozí a velicí jsou skutkové tvoji, Hospodine! Všeckys je moudře učinil, plná jest země bohatství tvého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 25, 'V moři pak velikém a přeširokém, tamť jsou hmyzové nesčíslní, a živočichové malí i velicí.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 26, 'Tuť bárky přecházejí i velryb, kteréhož jsi stvořil, aby v něm hrál.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 27, 'Všecko to na tě očekává, abys jim dával pokrm časem svým.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 28, 'Když jim dáváš, sbírají; když otvíráš ruku svou, nasyceni bývají dobrými věcmi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 29, 'Když skrýváš tvář svou, rmoutí se; když odjímáš ducha jejich, hynou, a v prach svůj se navracejí.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 30, 'Vysíláš ducha svého, a zase stvořeni bývají, a obnovuješ tvář země.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 31, 'Budiž sláva Hospodinova na věky, rozveselujž se Hospodin v skutcích svých.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 32, 'On když pohledí na zemi, anať se třese; když se dotkne hor, anť se kouří.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 33, 'Zpívati budu Hospodinu, dokudž jsem živ; žalmy Bohu svému zpívati budu, pokudž mne stává.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 34, 'Libé bude přemyšlování mé o něm, jáť rozveselím se v Hospodinu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 35, 'Ó by hříšníci vyhynuli z země, a bezbožných aby již nebylo. Dobrořeč duše má Hospodinu. Halelujah.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 1, 'Oslavujte Hospodina, ohlašujte jméno jeho, oznamujte mezi národy skutky jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 2, 'Zpívejte jemu, žalmy prozpěvujte jemu, rozmlouvejte o všech divných skutcích jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 3, 'Chlubte se jménem svatým jeho; vesel se srdce těch, kteříž hledají Hospodina.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 4, 'Hledejte Hospodina a síly jeho, hledejte tváři jeho ustavičně.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 5, 'Rozpomínejte se na divné skutky jeho, kteréž činil, na zázraky jeho a na soudy úst jeho,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 6, 'Símě Abrahamovo, služebníka jeho, synové Jákobovi, vyvolení jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 7, 'Onť jest Hospodin Bůh náš, na vší zemi soudové jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 8, 'Pamatuje věčně na smlouvu svou, na slovo, kteréž přikázal až do tisíce pokolení,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 9, 'Kteréž upevnil s Abrahamem, a na přísahu svou učiněnou Izákovi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 10, 'Nebo ji utvrdil Jákobovi za ustanovení, Izraelovi za smlouvu věčnou,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 11, 'Pravě: Tobě dám zemi Kananejskou za podíl dědictví vašeho,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 12, 'Ješto jich byl malý počet, malý počet, a ještě v ní byli pohostinu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 13, 'Přecházeli zajisté z národu do národu, a z království k jinému lidu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 14, 'Nedopustil žádnému ublížiti jim, ano i krále pro ně trestal, řka:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 15, 'Nedotýkejte se pomazaných mých, a prorokům mým nečiňte nic zlého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 16, 'Když přivolav hlad na zemi, všecku hůl chleba polámal,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 17, 'Poslal před nimi muže znamenitého, jenž za služebníka prodán byl, totiž Jozefa.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 18, 'Jehož nohy sevřeli pouty, železa podniknouti musil,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 19, 'Až do toho času, když se zmínka stala o něm; řeč Hospodinova zkusila ho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 20, 'Poslav král, propustiti ho rozkázal, panovník lidu svobodna ho učinil.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 21, 'Ustanovil ho pánem domu svého, a panovníkem všeho vládařství svého,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 22, 'Aby vládl i knížaty jeho podlé své líbosti, a starce jeho vyučoval moudrosti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 23, 'Potom všel Izrael do Egypta, a Jákob pohostinu byl v zemi Chamově.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 24, 'Kdež rozmnožil Bůh lid svůj náramně, a učinil, aby silnější byl nad nepřátely své.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 25, 'Změnil mysl těchto, aby v nenávisti měli lid jeho, a aby ukládali lest o služebnících jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 26, 'I poslal Mojžíše slouhu svého, a Arona, kteréhož vyvolil.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 27, 'Kteříž předložili jim slova znamení jeho a zázraků v zemi Chamově.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 28, 'Poslal tmu, a zatmělo se, aniž odporná byla slovu jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 29, 'Obrátil vody jejich v krev, a zmořil ryby v nich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 30, 'Vydala země jejich množství žab, i v pokoleních králů jejich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 31, 'Řekl, i přišla směsice žížal, a stěnice na všecky končiny jejich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 32, 'Dal místo deště krupobití, oheň hořící na zemi jejich,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 33, 'Tak že potloukl réví jejich i fíkoví jejich, a zpřerážel dříví v krajině jejich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 34, 'Řekl, i přišly kobylky a chroustů nesčíslné množství.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 35, 'I sežrali všelikou bylinu v krajině jejich, a pojedli úrody země jejich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 36, 'Nadto pobil všecko prvorozené v zemi jejich, počátek všeliké síly jejich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 37, 'Tedy vyvedl své s stříbrem a zlatem, aniž byl v pokoleních jejich, ješto by se poklesl.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 38, 'Veselili se Egyptští, když tito vycházeli; nebo byl připadl na ně strach Izraelských.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 39, 'Roztáhl oblak k zastírání jich, a oheň k osvěcování noci.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 40, 'K žádosti přivedl křepelky, a chlebem nebeským sytil je.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 41, 'Otevřel skálu, i tekly vody, a odcházely přes vyprahlá místa jako řeka.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 42, 'Nebo pamětliv byl na slovo svatosti své, k Abrahamovi služebníku svému mluvené.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 43, 'Protož vyvedl lid svůj s radostí, s prozpěvováním vyvolené své.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 44, 'A dal jim země pohanů, a tak úsilí národů dědičně obdrželi,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 45, 'Aby zachovávali ustanovení jeho, a práv jeho ostříhali. Halelujah.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 1, 'Halelujah. Oslavujte Hospodina, nebo dobrý jest, nebo na věky milosrdenství jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 2, 'Kdo může vymluviti nesmírnou moc Hospodinovu, a vypraviti všecku chválu jeho?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 3, 'Blahoslavení, kteříž ostříhají soudu, a činí spravedlnost každého času.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 4, 'Pamatuj na mne, Hospodine, pro milost k lidu svému, navštěv mne spasením svým,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 5, 'Abych užíval dobrých věcí s vyvolenými tvými, a veselil se veselím národu tvého, a chlubil se spolu s dědictvím tvým.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 6, 'Zhřešili jsme i s otci svými, neprávě jsme činili, a bezbožnost páchali.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 7, 'Otcové naši v Egyptě nerozuměli předivným skutkům tvým, aniž pamatovali na množství milosrdenství tvých, ale odporni byli při moři, při moři Rudém.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 8, 'A však vysvobodil je pro jméno své, aby v známost uvedl moc svou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 9, 'Nebo přimluvil moři Rudému, a vyschlo; i provedl je skrze hlubiny, jako po poušti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 10, 'A tak zachoval je od ruky toho, jenž jich nenáviděl, a vyprostil je z ruky nepřítele.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 11, 'V tom přikryly vody ty, kteříž je ssužovali, nezůstalo ani jednoho z nich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 12, 'A ačkoli věřili slovům jeho, a zpívali chválu jeho,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 13, 'Však rychle zapomenuli na skutky jeho, a nečekali na radu jeho;');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 14, 'Ale jati jsouce žádostí na poušti, pokoušeli Boha silného na pustinách.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 15, 'I dal jim, čehož se jim chtělo, a však dopustil hubenost na život jejich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 16, 'Potom, když horlili proti Mojžíšovi v vojště, a Aronovi, svatému Hospodinovu,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 17, 'Otevřevši se země, požřela Dátana, a přikryla zběř Abironovu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 18, 'A roznícen byl oheň na rotu jejich, plamen spálil bezbožníky.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 19, 'Udělali i tele na Orébě, a skláněli se slitině.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 20, 'A změnivše slávu svou v podobiznu vola, jenž jí trávu,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 21, 'Zapomněli na Boha silného, spasitele svého, kterýž činil veliké věci v Egyptě.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 22, 'A předivné v zemi Chamově, přehrozné při moři Rudém.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 23, 'Pročež řekl, že je vypléní, kdyby se byl Mojžíš, vyvolený jeho, nepostavil v té mezeře před ním, a neodvrátil prchlivosti jeho, aby nehubil.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 24, 'Za tím zošklivili sobě zemi žádanou, nevěříce slovu jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 25, 'A repcíce v staních svých, neposlouchali hlasu Hospodinova.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 26, 'A protož pozdvihl ruky své proti nim, aby je rozmetal po poušti,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 27, 'A aby rozptýlil símě jejich mezi pohany, a rozehnal je do zemí.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 28, 'Spřáhli se také byli s modlou Belfegor, a jedli oběti mrch.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 29, 'A tak dráždili Boha skutky svými, až se na ně obořila rána,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 30, 'Až se postavil Fínes, a pomstu vykonal, i přetržena jest rána ta.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 31, 'Což jest mu počteno za spravedlnost od národu do pronárodu, a až na věky.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 32, 'Opět ho byli popudili při vodách sváru, až se i Mojžíšovi zle stalo pro ně.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 33, 'Nebo k hořkosti přivedli ducha jeho, a pronesl ji rty svými.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 34, 'K tomu nevyplénili ani národů těch, o kterýchž jim byl Hospodin poručil,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 35, 'Ale směšujíce se s těmi národy, naučili se skutkům jejich,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 36, 'A sloužili modlám jejich, kteréž jim byly osídlem.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 37, 'Obětovali zajisté syny své a dcery své ďáblům.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 38, 'A vylili krev nevinnou, krev synů svých a dcer svých, kteréž obětovali trapidlům Kananejským, tak že poškvrněna jest země těmi vraždami.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 39, 'I zmazali se skutky svými, a smilnili činy svými.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 40, 'Protož rozpáliv se v prchlivosti Hospodin na lid svůj, v ošklivost vzal dědictví své.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 41, 'A vydal je v ruce pohanů. I panovali nad nimi ti, jenž je v nenávisti měli,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 42, 'A utiskali je nepřátelé jejich, tak že sníženi jsou pod ruku jejich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 43, 'Mnohokrát je vysvobozoval, oni však popouzeli ho radou svou, pročež potlačeni jsou pro nepravost svou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 44, 'A však patřil na úzkost jejich, a slyšel křik jejich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 45, 'Nebo se rozpomenul na smlouvu svou s nimi, a želel toho podlé množství milosrdenství svých,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 46, 'Tak že naklonil k nim lítostí všecky, kteříž je u vězení drželi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 47, 'Zachovej nás, Hospodine Bože náš, a shromažď nás z těch pohanů, abychom slavili jméno tvé svaté, a chlubili se v chvále tvé.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 48, 'Požehnaný Hospodin Bůh Izraelský od věků až na věky. Na to rciž všecken lid: Amen, Halelujah.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 1, 'Oslavujte Hospodina, nebo jest dobrý, nebo na věky milosrdenství jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 2, 'Nechť o tom vypravují ti, kteříž jsou vykoupeni skrze Hospodina, jak je on vykoupil z ruky těch, kteříž je ssužovali,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 3, 'A shromáždil je z zemí, od východu a od západu, od půlnoci i od moře.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 4, 'Bloudili po poušti, po cestách pustých, města k přebývání nenacházejíce.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 5, 'Hladovití a žízniví byli, až v nich svadla duše jejich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 6, 'Když volali k Hospodinu v ssoužení svém, z úzkostí jejich vytrhl je,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 7, 'A vedl je po cestě přímé, aby přišli do města k bydlení.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 8, 'Nechať oslavují před Hospodinem milosrdenství jeho, a divné skutky jeho před syny lidskými,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 9, 'Poněvadž napájí duši žíznivou, a duši hladovitou naplňuje dobrými věcmi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 10, 'Kteříž sedí ve tmě a v stínu smrti, sevříni jsouce bídou i železy,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 11, 'Protože odporni byli řečem Boha silného, a radou Nejvyššího pohrdli.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 12, 'Pročež ponížil bídou srdce jejich, padli, a nebylo pomocníka.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 13, 'Když volají k Hospodinu v ssoužení svém, z úzkostí je vysvobozuje.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 14, 'Vyvodí je z temností a stínu smrti, a svazky jejich trhá.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 15, 'Nechať oslavují před Hospodinem milosrdenství jeho, a divné skutky jeho před syny lidskými,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 16, 'Poněvadž láme brány měděné, a závory železné posekává.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 17, 'Blázni pro cestu převrácenosti své, a pro nepravosti své v trápení bývají.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 18, 'Oškliví se jim všeliký pokrm, až se i k branám smrti přibližují.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 19, 'Když volají k Hospodinu v ssoužení svém, z úzkostí jejich je vysvobozuje.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 20, 'Posílá slovo své, a uzdravuje je, a vysvobozuje je z hrobu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 21, 'Nechať oslavují před Hospodinem milosrdenství jeho, a divné skutky jeho před syny lidskými,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 22, 'A obětujíce oběti chvály, ať vypravují skutky jeho s prozpěvováním.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 23, 'Kteří se plaví po moři na lodech, pracujíce na velikých vodách,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 24, 'Tiť vídají skutky Hospodinovy, a divy jeho v hlubokosti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 25, 'Jakž jen dí, hned se strhne vítr bouřlivý, a dme vlny mořské.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 26, 'Vznášejí se k nebi, sstupují do propasti, duše jejich v nebezpečenství rozplývá se.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 27, 'Motají se a nakloňují jako opilý, a všecko umění jejich mizí.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 28, 'Když volají k Hospodinu v ssoužení svém, z úzkostí jejich je vysvobozuje.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 29, 'Proměňuje bouři v utišení, tak že umlkne vlnobití jejich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 30, 'I veselí se, že utichlo; a tak přivodí je k břehu žádostivému.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 31, 'Nechať oslavují před Hospodinem milosrdenství jeho, a divné skutky jeho před syny lidskými.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 32, 'Nechť ho vyvyšují v shromáždění lidu, a v radě starců chválí jej.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 33, 'Obrací řeky v poušť, a prameny vod v suchost,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 34, 'Zemi úrodnou v slatinnou, pro zlost obyvatelů jejích.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 35, 'Pustiny obrací v jezera, a zemi vyprahlou v prameny vod.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 36, 'I osazuje na ní hladovité, aby stavěli města k bydlení.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 37, 'Kteříž osívají pole, a dělají vinice, a shromažďují sobě užitek úrody.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 38, 'Takť on jim žehná, že se rozmnožují velmi, a dobytka jejich neumenšuje.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 39, 'A někdy pak umenšeni a sníženi bývají ukrutenstvím, bídou a truchlostí,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 40, 'Když vylévá pohrdání na knížata, dopouštěje, aby bloudili po poušti bezcestné.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 41, 'Onť vyzdvihuje nuzného z trápení, a rozmnožuje rodinu jako stádo.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 42, 'Nechť to spatřují upřímí, a rozveselí se, ale všeliká nepravost ať zacpá ústa svá.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 43, 'Ale kdo jest tak moudrý, aby toho šetřil, a vyrozumíval mnohému milosrdenství Hospodinovu?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 108, 1, 'Píseň a žalm Davidův. Hotovo jest srdce mé, Bože, zpívati a oslavovati tě budu, také i sláva má.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 108, 2, 'Probuď se loutno a harfo, když v svitání povstávám.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 108, 3, 'Slaviti tě budu mezi lidmi, Hospodine, a tobě žalmy prozpěvovati mezi národy.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 108, 4, 'Nebo nad nebesa větší jest milosrdenství tvé, a až k nejvyšším oblakům pravda tvá.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 108, 5, 'Vyvyšiž se nad nebesa, ó Bože, a nade všecku zemi sláva tvá.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 108, 6, 'Ať jsou vysvobozeni milí tvoji, zachovávejž je pravicí svou, a vyslyš mne.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 108, 7, 'Bůh mluvil skrze svatost svou; veseliti se budu, že budu děliti Sichem, a údolí Sochot že rozměřím.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 108, 8, 'Můjť jest Galád, můj i Manasses, a Efraim síla hlavy mé, Juda učitel můj.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 108, 9, 'Moáb medenice k umývání mému, na Edoma uvrhu obuv svou, proti Palestině troubiti budu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 108, 10, 'Kdo mne uvede do města hrazeného? Kdo mne zprovodí až do Idumejské země?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 108, 11, 'Zdali ne ty, ó Bože, kterýž jsi nás byl zavrhl, a nevycházels, ó Bože, s vojsky našimi?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 108, 12, 'Uděliž nám pomoci proti nepříteli, nebo marná jest pomoc lidská.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 108, 13, 'V Bohu udatně sobě počínati budeme, a on pošlapá nepřátely naše.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 1, 'Přednímu zpěváku, žalm Davidův. Ó Bože chvály mé, nečiň se neslyše.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 2, 'Nebo ústa nešlechetného a ústa lstivá proti mně se otevřela, mluvili proti mně jazykem lživým.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 3, 'A slovy jizlivými osočili mne, válčí proti mně beze vší příčiny.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 4, 'Protivili mi se za mé milování, ješto jsem se za ně modlíval.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 5, 'Odplacují se mi zlým za dobré, a nenávistí za milování mé.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 6, 'Postav nad ním bezbožníka, a protivník ať mu stojí po pravici.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 7, 'Když před soudem stane, ať zůstane za nešlechetného, a prosba jeho budiž jemu k hříchu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 8, 'Budiž dnů jeho málo, a úřad jeho vezmi jiný.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 9, 'Buďtež děti jeho sirotci, a žena jeho vdovou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 10, 'Buďtež běhouni a tuláci synové jeho, žebřete, vyhnáni jsouce z poustek svých.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 11, 'Přitáhni k sobě lichevník všecko, cožkoli má, a úsilé jeho rozchvátejte cizí.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 12, 'Nebudiž, kdo by mu chtěl milosrdenství prokázati, aniž buď, kdo by se smiloval nad sirotky jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 13, 'Potomci jeho z kořen vyťati buďte, v druhém kolenu vyhlazeno buď jméno jejich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 14, 'Přijdiž na pamět nepravost předků jeho před Hospodinem, a hřích matky jeho nebuď shlazen.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 15, 'Buďtež před Hospodinem ustavičně, až by vyhladil z země památku jejich,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 16, 'Proto že nepamatoval, aby činil milosrdenství, ale protivenství činil člověku chudému a nuznému a sevřenému bolestí srdce, aby jej zamordoval.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 17, 'Poněvadž miloval zlořečení, nechať přijde na něj; neměl líbosti v požehnání, nechať se vzdálí od něho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 18, 'A tak budiž oblečen v zlořečenství jako v svůj oděv, a ať vejde do vnitřností jeho jako voda, a jako olej do kostí jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 19, 'Budiž jemu to jako plášť k přiodívání, a jako pás k ustavičnému opasování.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 20, 'Taková mzda přijdiž mým protivníkům od Hospodina, a mluvícím zlé věci proti duši mé.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 21, 'Ty pak, Hospodine Pane, nalož se mnou laskavě pro jméno své, nebo dobré jest milosrdenství tvé; vytrhni mne.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 22, 'Jsemť zajisté chudý a nuzný, a srdce mé raněno jest u vnitřnostech mých.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 23, 'Jako stín, když se nachyluje, ucházeti musím; honí se za mnou jako za kobylkou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 24, 'Kolena má klesají postem, a tělo mé vyschlo z tučnosti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 25, 'Nadto jsem jim za posměch; když mne uhlédají, potřásají hlavami svými.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 26, 'Spomoz mi, ó Hospodine Bože můj, zachovej mne podlé milosrdenství svého,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 27, 'Tak aby poznati mohli, že jest to ruka tvá, a že jsi ty, Hospodine, učinil to.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 28, 'Nechť oni jakkoli zlořečí, ty dobrořeč; kteříž povstali, nechť se zastydí, aby se veselil služebník tvůj.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 29, 'Buďtež oblečeni protivníci moji v zahanbení, a nechť se odějí jako pláštěm hanbou svou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 30, 'Slaviti budu Hospodina velice ústy svými, a u prostřed mnohých chváliti jej budu,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 31, 'Proto že stojí po pravici nuznému, aby ho zachoval od těch, kteříž odsuzují život jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 110, 1, 'Davidův žalm. Řekl Hospodin Pánu mému: Seď na pravici mé, dokudž nepoložím nepřátel tvých za podnože noh tvých.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 110, 2, 'Berlu moci tvé vyšle Hospodin z Siona, řka: Panuj u prostřed nepřátel svých.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 110, 3, 'Lid tvůj dobrovolný v den boje tvého v ozdobě svatosti, z života hned v svitání jako rosa plod tvůj bude.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 110, 4, 'Přisáhl Hospodin, a nebude želeti toho, řka: Ty jsi kněz na věky podlé řádu Melchisedechova.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 110, 5, 'Pán po pravici tvé potře v den hněvu svého krále.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 110, 6, 'Soud činiti bude mezi národy, porážku hroznou učiní, potře i hlavu panující nad mnohými krajinami.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 110, 7, 'Z potoka na cestě píti bude, a protož povýší hlavy.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 111, 1, 'Halelujah. Slaviti budu Hospodina z celého srdce, v radě přímých i v shromáždění;');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 111, 2, 'Veliké skutky Hospodinovy, a patrné všechněm, kteříž v nich líbost mají;');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 111, 3, 'Slavné a překrásné dílo jeho, a spravedlnost jeho zůstávající na věky.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 111, 4, 'Památku způsobil předivnými skutky svými milostivý a milosrdný Hospodin.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 111, 5, 'Pokrm dal těm, kteříž se ho bojí, pamětliv jsa věčně na smlouvu svou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 111, 6, 'Mocné skutky své oznámil lidu svému, dav jim dědictví pohanů.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 111, 7, 'Skutkové rukou jeho pravda a soud, a nepohnutelní všickni rozkazové jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 111, 8, 'Upevnění na věčnou věčnost; učiněni jsou v pravdě a v pravosti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 111, 9, 'Vykoupení poslav lidu svému, přikázal na věky smlouvu svou; svaté a hrozné jest jméno jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 111, 10, 'Počátek moudrosti jest bázeň Hospodina; rozumu výborného nabývají všickni, kteříž činí ty věci; chvála jeho zůstává na věky.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 112, 1, 'Halelujah. Blahoslavený muž, kterýž se bojí Hospodina, a v přikázaních jeho má velikou líbost.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 112, 2, 'Mocné na zemi bude símě jeho, rodina upřímých požehnání dojde.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 112, 3, 'Zboží a bohatství v domě jeho, a spravedlnost jeho zůstává na věky.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 112, 4, 'Vzchází ve tmách světlo upřímým, milostivý jest, milosrdný a spravedlivý.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 112, 5, 'Dobrý člověk slitovává se i půjčuje, a řídí své věci s soudem.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 112, 6, 'Nebo nepohne se na věky, v paměti věčné bude spravedlivý.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 112, 7, 'Slyše zlé noviny, nebojí se; stálé jest srdce jeho, a doufá v Hospodina.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 112, 8, 'Utvrzené srdce jeho nebojí se, až i uzří pomstu na svých nepřátelích.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 112, 9, 'Rozděluje štědře, a dává nuzným; spravedlnost jeho zůstává na věky, roh jeho bude vyvýšen v slávě.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 112, 10, 'Bezbožný vida to, zlobiti se, zuby svými škřipěti a schnouti bude; žádost bezbožníků zahyne.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 113, 1, 'Halelujah. Chvalte služebníci Hospodinovi, chvalte jméno Hospodinovo.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 113, 2, 'Budiž jméno Hospodinovo požehnáno od tohoto času až na věky.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 113, 3, 'Od východu slunce až do západu jeho chváleno buď jméno Hospodinovo.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 113, 4, 'Vyvýšenť jest nade všecky národy Hospodin, a nad nebesa sláva jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 113, 5, 'Kdo jest rovný Hospodinu Bohu našemu, kterýž vysoko bydlí?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 113, 6, 'Kterýž snižuje se, aby všecko spatřoval, což jest na nebi i na zemi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 113, 7, 'Vyzdvihuje z prachu nuzného, a z hnoje vyvyšuje chudého,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 113, 8, 'Aby jej posadil s knížaty, s knížaty lidu svého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 113, 9, 'Kterýž vzdělává neplodnou v čeled, a matku veselící se z dítek. Halelujah.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 114, 1, 'Když vycházel Izrael z Egypta, a rodina Jákobova z národu jazyka cizího,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 114, 2, 'Byl Juda posvěcením jeho, Izrael panováním jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 114, 3, 'To když vidělo moře, uteklo, Jordán nazpět se obrátil.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 114, 4, 'Hory poskakovaly jako skopci, pahrbkové jako jehňata.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 114, 5, 'Coť bylo, ó moře, že jsi utíkalo? Jordáne, že jsi nazpět se obrátil?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 114, 6, 'Ó hory, že jste poskakovaly jako skopci, pahrbkové jako jehňata?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 114, 7, 'Pro přítomnost Panovníka třásla jsem se já země, pro přítomnost Boha Jákobova,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 114, 8, 'Kterýž obrací i tu skálu v jezero vod, a škřemen v studnici vod.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 1, 'Ne nám, Hospodine, ne nám, ale jménu svému dej čest, pro milosrdenství své a pro pravdu svou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 2, 'Proč mají říkati pohané: Kdež jest nyní Bůh jejich?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 3, 'Ješto Bůh náš jest na nebi, čině všecko, což se mu líbí.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 4, 'Modly pak jejich jsou stříbro a zlato, dílo rukou lidských.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 5, 'Ústa mají, a nemluví, oči mají, a nevidí.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 6, 'Uši mají, a neslyší, nos mají, a nečijí.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 7, 'Ruce mají, a nemakají, nohy mají, a nechodí, aniž volati mohou hrdlem svým.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 8, 'Nechať jsou jim podobni, kteříž je dělají, a kdožkoli v nich doufají.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 9, 'Izraeli, doufej v Hospodina, nebo spomocníkem a štítem takových on jest.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 10, 'Dome Aronův, doufej v Hospodina, spomocníkem a štítem takových on jest.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 11, 'Kteříž se bojíte Hospodina, doufejte v Hospodina, spomocníkem a štítem takových on jest.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 12, 'Hospodin rozpomena se na nás, požehná; požehná domu Izraelovu, požehná i domu Aronovu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 13, 'Požehná bojícím se Hospodina, malým, i velikým.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 14, 'Rozmnoží Hospodin vás, vás i syny vaše.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 15, 'Požehnaní vy od Hospodina, kterýž učinil nebesa i zemi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 16, 'Nebesa jsou nebesa Hospodinova, zemi pak dal synům lidským.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 17, 'Ne mrtví chváliti budou Hospodina, ani kdo ze všech těch, kteříž sstupují do místa mlčení,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 18, 'Ale my dobrořečiti budeme Hospodinu od tohoto času až na věky. Halelujah.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 1, 'Miluji Hospodina, proto že vyslýchá hlas můj a pokorné modlitby mé.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 2, 'Nebo naklonil ucha svého ke mně, když jsem ho vzýval ve dnech svých.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 3, 'Obklíčilyť mne byly bolesti smrti, a úzkosti hrobu potkaly mne; sevření a truchlost přišla na mne.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 4, 'I vzýval jsem jméno Hospodinovo, řka: Prosím, ó Hospodine, vysvoboď duši mou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 5, 'Milostivý Hospodin a spravedlivý, Bůh náš lítostivý.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 6, 'Ostříhá sprostných Hospodin; znuzen jsem byl, a spomohl mi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 7, 'Navratiž se, duše má, do odpočinutí svého, poněvadž Hospodin jest dobrodince tvůj.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 8, 'Nebo jsi vytrhl duši mou od smrti, oči mé od slz, nohu mou od poklesnutí.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 9, 'Ustavičně choditi budu před Hospodinem v zemi živých.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 10, 'Uvěřil jsem, protož i mluvil jsem, ačkoli jsem byl velmi ztrápený.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 11, 'Já jsem byl řekl v pospíchání: Všeliký člověk jest lhář.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 12, 'Čím se odplatím Hospodinu za všecka dobrodiní jeho mně učiněná?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 13, 'Kalich mnohého spasení vezmu, a jméno Hospodinovo vzývati budu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 14, 'Sliby své Hospodinu splním, teď přede vším lidem jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 15, 'Drahá jest před očima Hospodinovýma smrt svatých jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 16, 'Ó Hospodine, že jsem služebník tvůj, služebník, pravím, tvůj, syn děvky tvé, rozvázal jsi svazky mé.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 17, 'Tobě obětovati budu obět díků činění, a jméno Hospodinovo vzývati budu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 18, 'Sliby své Hospodinu splním, teď přede vším lidem jeho,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 19, 'V síňcích domu Hospodinova, u prostřed tebe, Jeruzaléme. Halelujah.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 117, 1, 'Chvalte Hospodina všickni národové, velebtež ho všickni lidé.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 117, 2, 'Neboť jest rozšířeno nad námi milosrdenství jeho, a pravda Hospodinova na věky. Halelujah.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 1, 'Oslavujte Hospodina, nebo jest dobrý, nebo na věky trvá milosrdenství jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 2, 'Rciž nyní, Izraeli, že na věky milosrdenství jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 3, 'Rciž nyní, dome Aronův, že na věky milosrdenství jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 4, 'Rcetež nyní bojící se Hospodina, že na věky milosrdenství jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 5, 'V úzkosti vzýval jsem Hospodina, a vyslyšev, uprostrannil mi Hospodin.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 6, 'Hospodin se mnou, nebudu se báti. Co mi může učiniti člověk?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 7, 'Hospodin se mnou jest mezi pomocníky mými, pročež já podívám se těm, kteříž mne mají v nenávisti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 8, 'Lépe jest doufati v Hospodina, než naději skládati v člověku.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 9, 'Lépe jest doufati v Hospodina, nežli naději skládati v knížatech.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 10, 'Všickni národové obklíčili mne, ale ve jménu Hospodinovu vyplénil jsem je.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 11, 'Mnohokrát obklíčili mne, ale ve jménu Hospodinovu vyplénil jsem je.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 12, 'Ssuli se na mne jako včely, však zhasli jako oheň z trní: nebo ve jménu Hospodinovu vyplénil jsem je.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 13, 'Velmi jsi ztuha na mne dotíral, abych padl, ale Hospodin spomohl mi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 14, 'Síla má a písnička má jest Hospodin, on byl můj vysvoboditel.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 15, 'Hlas prokřikování a spasení v staních spravedlivých. Pravice Hospodinova dokázala síly,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 16, 'Pravice Hospodinova vyvýšila se, pravice Hospodinova dokázala síly.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 17, 'Neumruť, ale živ budu, abych vypravoval skutky Hospodinovy.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 18, 'Trestaltě mne přísně Hospodin, ale smrti mne nevydal.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 19, 'Otevřetež mi brány spravedlnosti, a vejda do nich, oslavovati budu Hospodina.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 20, 'Tať jest brána Hospodinova, kterouž spravedliví vcházejí.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 21, 'Tuť já tě oslavovati budu, nebo jsi mne vyslyšel, a byls můj vysvoboditel.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 22, 'Kámen, kterýž zavrhli stavitelé, učiněn jest v hlavu úhelní.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 23, 'Od Hospodina stalo se to, a jest divné před očima našima.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 24, 'Tentoť jest den, kterýž učinil Hospodin, a protož radujme se a veselme se v něm.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 25, 'Prosím, Hospodine, zachovávejž již; prosím, Hospodine, dávej již šťastný prospěch.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 26, 'Požehnaný, jenž se béře ve jménu Hospodinovu; dobrořečíme vám z domu Hospodinova.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 27, 'Bůh silný Hospodin, onť se zasvítil nám, važte beránky až k rohům oltáře.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 28, 'Bůh silný můj ty jsi, protož slaviti tě budu, Bože můj, vyvyšovati tě budu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 29, 'Oslavujtež Hospodina, neboť jest dobrý, nebo na věky milosrdenství jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 1, 'Aleph. Blahoslavení ti, kteříž jsou ctného obcování, kteříž chodí v zákoně Hospodinově.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 2, 'Blahoslavení, kteříž ostříhají svědectví jeho, a kteříž ho celým srdcem hledají.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 3, 'Nečiní zajisté nepravosti, ale kráčejí po cestách jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 4, 'Ty jsi přikázal, aby pilně bylo ostříháno rozkazů tvých.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 5, 'Ó by spraveny byly cesty mé k ostříhání ustanovení tvých.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 6, 'Tehdážť nebudu zahanben, když budu patřiti na všecka přikázaní tvá.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 7, 'Oslavovati tě budu v upřímnosti srdce, když se vyučovati budu právům spravedlnosti tvé.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 8, 'Ustanovení tvých budu ostříhati s pilností, toliko neopouštěj mne.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 9, 'Beth. Jakým způsobem očistí mládenec stezku svou? Takovým, aby se choval vedlé slova tvého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 10, 'Celým srdcem svým hledám tebe, nedopouštějž mi blouditi od přikázaní tvých.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 11, 'V srdci svém skládám řeč tvou, abych nehřešil proti tobě.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 12, 'Ty chvály hodný Hospodine, vyuč mne ustanovením svým.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 13, 'Rty svými vypravuji o všech soudech úst tvých.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 14, 'Z cesty svědectví tvých raduji se více, než z největšího zboží.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 15, 'O přikázaních tvých přemyšluji, a patřím na stezky tvé.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 16, 'V ustanoveních tvých se kochám, aniž se zapomínám na slovo tvé.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 17, 'Gimel Tu milost učiň s služebníkem svým, abych, dokudž jsem živ, ostříhal slova tvého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 18, 'Otevři oči mé, abych spatřoval divné věci z zákona tvého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 19, 'Příchozí jsem na tom světě, neukrývejž přede mnou přikázaní svých.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 20, 'Umdlévá duše má pro žádost soudů tvých všelikého času.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 21, 'Vyhlazuješ pyšné, zlořečené, kteříž bloudí od přikázaní tvých.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 22, 'Odejmi ode mne útržku a potupu, neboť ostříhám svědectví tvých.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 23, 'Také i knížata se zasazují, a mluví proti mně, služebník pak tvůj přemýšlí o ustanoveních tvých.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 24, 'Svědectví tvá zajisté jsou mé rozkoše a moji rádcové.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 25, 'Daleth Přilnula k prachu duše má; obživiž mne podlé slova svého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 26, 'Cesty své předložilť jsem, a vyslýchals mne; vyuč mne ustanovením svým.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 27, 'Cestě rozkazů tvých dej ať vyrozumívám, a ať přemýšlím o divných skutcích tvých.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 28, 'Rozplývá se zámutkem duše má, očerstviž mne podlé slova svého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 29, 'Cestu lživou odvrať ode mne, a zákon svůj z milosti dej mi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 30, 'Cestu pravou jsem vyvolil, soudy tvé sobě předkládám.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 31, 'Svědectví tvých se přídržím, Hospodine, nedejž mi zahanbenu býti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 32, 'Cestou rozkazů tvých poběhnu, když ty rozšíříš srdce mé.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 33, 'He Vyuč mne, Hospodine, cestě ustanovení svých, kteréž bych ostříhal do konce.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 34, 'Dej mi ten rozum, ať šetřím zákona tvého, a ať ho ostříhám celým srdcem.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 35, 'Dej, ať chodím cestou přikázaní tvých; nebo v tom svou rozkoš skládám.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 36, 'Nakloň srdce mého k svědectvím svým, a ne k lakomství.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 37, 'Odvrať oči mé, ať nehledí marnosti; na cestě své obživ mne.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 38, 'Potvrď služebníku svému řeči své, kterýž se oddal k službě tvé.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 39, 'Odvrať ode mne pohanění, jehož se bojím; nebo soudové tvoji dobří jsou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 40, 'Aj, toužím po rozkázaních tvých; dej, ať jsem živ v spravedlnosti tvé.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 41, 'Vav Ó ať se přiblíží ke mně milosrdenství tvá, Hospodine, a spasení tvé vedlé řeči tvé,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 42, 'Tak abych odpovědíti uměl utrhači svému skutkem, že doufání skládám v slovu tvém.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 43, 'A nevynímej z úst mých slova nejpravějšího; neboť na soudy tvé očekávám.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 44, 'I budu ostříhati zákona tvého ustavičně, od věků až na věky,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 45, 'A bez přestání choditi na širokosti, neboť jsem se dotázal rozkazů tvých.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 46, 'Nýbrž mluviti budu o svědectvích tvých i před králi, a nebudu se hanbiti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 47, 'Nebo rozkoš svou skládám v přikázaních tvých, kteráž jsem zamiloval.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 48, 'Přičinímť i ruce své k přikázaním tvým, kteráž miluji, a přemýšleti budu o ustanoveních tvých.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 49, 'Zajin Rozpomeň se na slovo k služebníku svému, kterýmž jsi mne ubezpečil.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 50, 'Toť jest má útěcha v ssoužení mém, že mne slovo tvé obživuje.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 51, 'Pyšní mi se velmi posmívají, však od zákona tvého se neuchyluji.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 52, 'Neboť se rozpomínám na soudy tvé věčné, Hospodine, kterýmiž se potěšuji.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 53, 'Děsím se nad bezbožnými, kteříž opouštějí zákon tvůj.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 54, 'Ustanovení tvá jsou mé písničky na místě mého putování.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 55, 'Rozpomínám se i v noci na jméno tvé, Hospodine, a ostříhám zákona tvého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 56, 'Toť mám odtud, abych ostříhal rozkazů tvých.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 57, 'Cheth Díl můj, řekl jsem, Hospodine, ostříhati výmluvnosti tvé.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 58, 'Modlívám se milosti tvé v celém srdci: Smiluj se nade mnou podlé slova svého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 59, 'Rozvážil jsem na mysli cesty své, a obrátil jsem nohy své k tvým svědectvím.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 60, 'Pospíchámť a neodkládám ostříhati rozkazů tvých.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 61, 'Rota bezbožníků zloupila mne, na zákon tvůj se nezapomínám.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 62, 'O půlnoci vstávám, abych tě oslavoval v soudech spravedlnosti tvé.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 63, 'Účastník jsem všech, kteříž se bojí tebe, a těch, kteříž ostříhají přikázaní tvých.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 64, 'Milosrdenství tvého, Hospodine, plná jest země, ustanovením svým vyuč mne.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 65, 'Teth Dobrotivě jsi nakládal s služebníkem svým, Hospodine, podlé slova svého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 66, 'Pravému soudu a umění vyuč mne, nebo jsem přikázaním tvým uvěřil.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 67, 'Prvé než jsem snížen byl, bloudil jsem, ale nyní výmluvnosti tvé ostříhám.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 68, 'Dobrý jsi ty a dobrotivý, vyuč mne ustanovením svým.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 69, 'Složiliť jsou lež proti mně pyšní, ale já celým srdcem ostříhám přikázaní tvých.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 70, 'Zbřidlo jako tuk srdce jejich, já zákonem tvým se potěšuji.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 71, 'K dobrémuť jest mi to, že jsem pobyl v trápení, abych se naučil ustanovením tvým.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 72, 'Za lepší sobě pokládám zákon úst tvých, nežli na tisíce zlata a stříbra.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 73, 'Jod Ruce tvé učinily a sformovaly mne, dej mi ten rozum, abych se naučil přikázaním tvým,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 74, 'Tak aby bojící se tebe mne vidouce, radovali se, že na slovo tvé očekávám.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 75, 'Seznávámť, Hospodine, že jsou spravedliví soudové tvoji, a že jsi mne hodně potrestal.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 76, 'Nechať jest již zřejmé milosrdenství tvé ku potěšení mému, podlé řeči tvé mluvené služebníku tvému.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 77, 'Přiďtež na mne slitování tvá, abych živ býti mohl; nebo zákon tvůj rozkoš má jest.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 78, 'Zahanbeni buďte pyšní, proto že lstivě chtěli mne podvrátiti, já pak přemyšluji o přikázaních tvých.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 79, 'Obraťtež se ke mně, kteříž se bojí tebe, a kteříž znají svědectví tvá.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 80, 'Budiž srdce mé upřímé při ustanoveních tvých, tak abych nebyl zahanben.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 81, 'Kaph Touží duše má po spasení tvém, na slovo tvé očekávám.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 82, 'Hynou i oči mé žádostí výmluvností tvých, když říkám: Skoro-liž mne potěšíš?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 83, 'Ačkoli jsem jako nádoba kožená v dymu, na ustanovení tvá však jsem nezapomenul.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 84, 'Mnoho-liž bude dní služebníka tvého? Skoro-liž soud vykonáš nad těmi, kteříž mi protivenství činí?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 85, 'Vykopali mi pyšní jámy, kterážto věc není podlé zákona tvého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 86, 'Všecka přikázaní tvá jsou pravda; bez příčiny mi se protiví, spomoziž mi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 87, 'Téměřť jsou mne již v nic obrátili na zemi, já jsem však neopustil přikázaní tvých.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 88, 'Podlé milosrdenství svého obživ mne, abych ostříhal svědectví úst tvých.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 89, 'Lamed Na věky, ó Hospodine, slovo tvé trvánlivé jest v nebesích.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 90, 'Od národu do pronárodu pravda tvá, utvrdil jsi zemi, a tak stojí.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 91, 'Vedlé úsudků tvých stojí to vše do dnešního dne, všecko to zajisté jsou služebníci tvoji.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 92, 'Byť zákon tvůj nebyl mé potěšení, dávno bych byl zahynul v svém trápení.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 93, 'Na věky se nezapomenu na rozkazy tvé; jimi zajisté obživil jsi mne.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 94, 'Tvůjť jsem já, zachovávejž mne; nebo přikázaní tvá zpytuji.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 95, 'Očekávajíť na mne bezbožní, aby mne zahubili, já pak svědectví tvá rozvažuji.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 96, 'Každé věci dokonalé vidím skončení; rozkaz tvůj jest přeširoký náramně.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 97, 'Mem Ó jak miluji zákon tvůj, tak že každého dne on jest mé přemyšlování.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 98, 'Nad nepřátely mé moudřejšího mne činíš přikázaními svými; nebo mám je ustavičně před sebou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 99, 'Nade všecky své učitele rozumnější jsem učiněn; nebo svědectví tvá jsou má přemyšlování.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 100, 'I nad starce opatrnější jsem, nebo přikázaní tvých ostříhám.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 101, 'Od každé cesty zlé zdržuji nohy své, abych ostříhal slova tvého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 102, 'Od soudů tvých se neodvracuji, proto že ty mne vyučuješ.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 103, 'Ó jak jsou sladké dásním mým výmluvnosti tvé, nad med ústům mým.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 104, 'Z přikázaní tvých rozumnosti jsem nabyl, a protož všeliké cesty bludné nenávidím.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 105, 'Nun Svíce nohám mým jest slovo tvé, a světlo stezce mé.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 106, 'Přisáhl jsem, což i splním, že chci ostříhati soudů spravedlnosti tvé.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 107, 'Ztrápenýť jsem přenáramně, Hospodine, obživiž mne vedlé slova svého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 108, 'Dobrovolné oběti úst mých, žádám, oblib, Hospodine, a právům svým vyuč mne.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 109, 'Duše má jest v ustavičném nebezpečenství, a však na zákon tvůj se nezapomínám.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 110, 'Polékli jsou mi bezbožní osídlo, ale já od rozkazů tvých se neodvracím.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 111, 'Za dědictví věčné ujal jsem svědectví tvá, neboť jsou radost srdce mého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 112, 'Naklonil jsem srdce svého k vykonávání ustanovení tvých ustavičně, až i do konce.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 113, 'Samech Výmyslků nenávidím, zákon pak tvůj miluji.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 114, 'Skrýše má a pavéza má ty jsi, na slovo tvé očekávám.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 115, 'Odstuptež ode mne nešlechetníci, abych ostříhal přikázaní Boha svého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 116, 'Zdržujž mne podlé slova svého, tak abych živ byl, a nezahanbuj mne v mém očekávání.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 117, 'Posiluj mne, abych zachován byl, a patřil k ustanovením tvým ustavičně.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 118, 'Potlačuješ všecky ty, kteříž odstupují od ustanovení tvých; neboť jest lživá opatrnost jejich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 119, 'Jako trůsku odmítáš všecky bezbožníky země, a protož miluji svědectví tvá.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 120, 'Děsí se strachem před tebou tělo mé; nebo soudů tvých bojím se.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 121, 'Ajin Činím soud a spravedlnost, nevydávejž mne mým násilníkům.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 122, 'Zastup sám služebníka svého k dobrému, tak aby mne pyšní nepotlačili.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 123, 'Oči mé hynou čekáním na spasení tvé, a na výmluvnost spravedlnosti tvé.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 124, 'Nalož s služebníkem svým vedlé milosrdenství svého, a ustanovením svým vyuč mne.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 125, 'Služebník tvůj jsem já, dejž mi rozumnost, abych uměl svědectví tvá.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 126, 'Časť jest, abys se přičinil, Hospodine; zrušili zákon tvůj.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 127, 'Z té příčiny miluji přikázaní tvá více nežli zlato, i to, kteréž jest nejlepší.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 128, 'A proto, že všecky rozkazy tvé o všech věcech pravé býti poznávám, všeliké stezky bludné nenávidím.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 129, 'Pe Předivnáť jsou svědectví tvá, a protož jich ostříhá duše má.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 130, 'Začátek učení tvého osvěcuje, a vyučuje sprostné rozumnosti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 131, 'Ústa svá otvírám, a dychtím, nebo přikázaní tvých jsem žádostiv.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 132, 'Popatřiž na mne, a smiluj se nade mnou podlé práva těch, kteříž milují jméno tvé.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 133, 'Kroky mé utvrzuj v slovu svém, a nedej, aby nade mnou panovati měla jaká nepravost.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 134, 'Vysvoboď mne z nátisků lidských, abych ostříhal rozkazů tvých.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 135, 'Zasvěť tvář svou nad služebníkem svým, a ustanovením svým vyuč mne.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 136, 'Potůčkové vod vyplývají z očí mých příčinou těch, kteříž neostříhají zákona tvého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 137, 'Tsade Spravedlivý jsi, Hospodine, a upřímý v soudech svých.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 138, 'Ty jsi vydal spravedlivá svědectví svá, a vší víry hodná.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 139, 'Až svadnu, tak horlím, že se zapomínají na slovo tvé nepřátelé moji.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 140, 'Zprubovanáť jest řeč tvá dokonale, tou příčinou ji miluje služebník tvůj.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 141, 'Maličký a opovržený jsem já, však na rozkazy tvé se nezapomínám.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 142, 'Spravedlnost tvá jest spravedlnost věčná, a zákon tvůj pravda.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 143, 'Ssoužení a nátisk mne stihají, přikázaní tvá jsou mé rozkoše.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 144, 'Spravedlnost svědectví tvých trvá na věky; dej mi z ní rozumnosti nabýti, tak abych živ býti mohl.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 145, 'Koph Z celého srdce volám, vyslyšiž mne, ó Hospodine, abych ostříhal ustanovení tvých.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 146, 'K tobě volám, vysvoboď mne, abych šetřil svědectví tvých.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 147, 'Předstihám svitání a volám, na tvéť slovo očekávám.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 148, 'Předstihají oči mé bdění proto, abych přemýšlel o výmluvnostech tvých.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 149, 'Hlas můj slyš podlé svého milosrdenství, Hospodine, podlé soudů svých obživ mne.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 150, 'Přibližují se následovníci nešlechetnosti, ti, kteříž se od zákona tvého vzdálili.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 151, 'Ty blíže jsi, Hospodine; nebo všecka přikázaní tvá jsou pravda.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 152, 'Jižť to dávno vím o svědectvích tvých, že jsi je stvrdil až na věky.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 153, 'Reš Popatřiž na mé trápení, a vysvoboď mne; neboť se na zákon tvůj nezapomínám.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 154, 'Zasaď se o mou při, a ochraň mne; pro řeč svou obživ mne.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 155, 'Dalekoť jest od bezbožných spasení, nebo nedotazují se na ustanovení tvá.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 156, 'Slitování tvá mnohá jsou, Hospodine; podlé soudů svých obživ mne.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 157, 'Jakžkoli jsou mnozí protivníci moji a nepřátelé moji, však od svědectví tvých se neuchyluji.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 158, 'Viděl jsem ty, kteříž se převráceně měli, velmi to těžce nesa, že řeči tvé neostříhali.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 159, 'Popatřiž, žeť rozkazy tvé miluji, Hospodine; podlé milosrdenství svého obživ mne.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 160, 'Nejpřednější věc slova tvého jest pravda, a na věky trvá všeliký úsudek spravedlnosti tvé.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 161, 'Šin Knížata mi se protiví bez příčiny, však slova tvého děsí se srdce mé.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 162, 'Já raduji se z řeči tvé tak jako ten, kterýž dochází hojné kořisti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 163, 'Falše pak nenávidím, a jí v ohavnosti mám; zákon tvůj miluji.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 164, 'Sedmkrát za den chválím tě z soudů tvých spravedlivých.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 165, 'Pokoj mnohý těm, kteříž milují zákon tvůj, a nemají žádné urážky.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 166, 'Očekávám na spasení tvé, Hospodine, a přikázaní tvá vykonávám.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 167, 'Ostříhá duše má svědectví tvých, nebo je velice miluji.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 168, 'Ostříhám rozkazů tvých a svědectví tvých; nebo všecky cesty mé jsou před tebou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 169, 'Thav Předstupiž úpění mé před oblíčej tvůj, Hospodine, a podlé slova svého uděl mi rozumnosti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 170, 'Vejdiž pokorná prosba má před tvář tvou, a vedlé řeči své vytrhni mne.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 171, 'I vynesou rtové moji chválu, když ty mne vyučíš ustanovením svým.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 172, 'Zpívati bude i jazyk můj slovo tvé, a že všecka přikázaní tvá jsou spravedlnost.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 173, 'Budiž mi ku pomoci ruka tvá; neboť jsem sobě zvolil přikázaní tvá.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 174, 'Toužím po spasení tvém, Hospodine, a zákon tvůj jest rozkoš má.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 175, 'Živa bude duše má, a bude tě chváliti, a soudové tvoji budou mi na pomoc.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 176, 'Bloudím jako ovce ztracená, hledejž služebníka svého, neboť se na přikázaní tvá nezapomínám.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 120, 1, 'Píseň stupňů. K Hospodinu v ssoužení svém volal jsem, a vyslyšel mne.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 120, 2, 'Hospodine, vysvoboď duši mou od rtů lživých, a od jazyka lstivého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 120, 3, 'Coť prospěje, aneb coť přidá jazyk lstivý,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 120, 4, 'Podobný k střelám přeostrým silného, a k uhlí jalovcovému?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 120, 5, 'Běda mně, že pohostinu býti musím v Mešech, a přebývati v saláších Cedarských.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 120, 6, 'Dlouho bydlí duše má mezi těmi, kteříž nenávidí pokoje.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 120, 7, 'Já ku pokoji, ale když mluvím, oni k boji.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 121, 1, 'Píseň stupňů. Pozdvihuji očí svých k horám, odkudž by mi přišla pomoc.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 121, 2, 'Pomoc má jest od Hospodina, kterýž učinil nebe i zemi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 121, 3, 'Nedopustíť, aby se pohnouti měla noha tvá, nedřímeť strážný tvůj.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 121, 4, 'Aj, nedřímeť, ovšem nespí ten, kterýž ostříhá Izraele.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 121, 5, 'Hospodin strážce tvůj, Hospodin zastínění tvé tobě po pravici.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 121, 6, 'Nebudeť bíti na tě slunce ve dne, ani měsíc v noci.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 121, 7, 'Hospodin tě ostříhati bude ode všeho zlého, ostříhati bude duše tvé.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 121, 8, 'Hospodin ostříhati tě bude, když vycházeti i vcházeti budeš, od tohoto času až na věky.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 122, 1, 'Píseň stupňů, Davidova. Veselím se z toho, že mi říkáno bývá: Poďme do domu Hospodinova,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 122, 2, 'A že se postavují nohy naše v branách tvých, ó Jeruzaléme.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 122, 3, 'Jižtě Jeruzalém ušlechtile vystaven, a jako v město k sobě vespolek připojen.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 122, 4, 'Do něhož vstupují pokolení, pokolení Hospodinova, k svědectví Izraelovu, aby oslavovali jméno Hospodinovo.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 122, 5, 'Nebo tamť jsou postaveny stolice soudu, stolice domu Davidova.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 122, 6, 'Žádejtež pokoje Jeruzalému, řkouce: Dějž se pokojně těm, kteříž tě milují.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 122, 7, 'Budiž pokoj v předhradí tvém, a upokojení na palácích tvých.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 122, 8, 'Pro bratří své a přátely své žádati budu pokoje tobě.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 122, 9, 'Pro dům Hospodina Boha našeho budu tvého dobrého hledati.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 123, 1, 'Píseň stupňů. K toběť pozdvihuji očí svých, ó ty, kterýž na nebesích přebýváš.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 123, 2, 'Aj hle, jakož oči služebníků k rukám pánů jejich, jakož oči děvky k rukám paní její: tak oči naše k Hospodinu Bohu našemu, až by se smiloval nad námi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 123, 3, 'Smiluj se nad námi, Hospodine, smiluj se nad námi, neboť jsme již příliš potupou nasyceni.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 123, 4, 'Jižť jest příliš nasycena duše naše posmíšky bezbožných, a potupou pyšných.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 124, 1, 'Píseň stupňů, Davidova. Byť Hospodina s námi nebylo, rciž nyní, Izraeli,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 124, 2, 'Byť Hospodina s námi nebylo, když lidé povstali proti nám:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 124, 3, 'Tehdáž by nás byli za živa sehltili v rozpálení hněvu svého proti nám;');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 124, 4, 'Tehdáž by nás byly přikvačily vody, proud zachvátil by byl duši naši;');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 124, 5, 'Tehdáž zachvátily by byly duši naši ty vody zduté.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 124, 6, 'Požehnaný Hospodin, kterýž nás nevydal v loupež zubům jejich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 124, 7, 'Duše naše jako ptáče znikla osídla ptáčníků; osídlo se ztrhalo, i vynikli jsme.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 124, 8, 'Pomoc naše jest ve jménu Hospodinovu, kterýž učinil nebe i zemi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 125, 1, 'Píseň stupňů. Ti, kteříž doufají v Hospodina, podobni jsou k hoře Sionu, kteráž se nepohybuje, ale na věky zůstává.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 125, 2, 'Okolo Jeruzaléma jsou hory, Hospodin jest vůkol lidu svého, od tohoto času až na věky.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 125, 3, 'Neboť nebude státi sceptrum bezbožníků nad losem spravedlivých, aby nevztáhli spravedliví k nepravosti rukou svých.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 125, 4, 'Dobře učiň, Hospodine, dobrým, a těm, kteříž jsou upřímého srdce.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 125, 5, 'Ty pak, kteříž se uchylují k cestám svým křivým, zapudiž Hospodin s činiteli nepravosti. Pokoj přijdiž na Izraele.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 126, 1, 'Píseň stupňů. Když zase vedl Hospodin zajaté Sionské, zdálo se nám to jako ve snách.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 126, 2, 'Tehdážť byla plná radosti ústa naše, a jazyk náš plésání; tehdáž pravili mezi národy: Veliké věci s nimi učinil Hospodin.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 126, 3, 'Učinilť jest s námi veliké věci Hospodin, a protož veselili jsme se.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 126, 4, 'Uvediž zase, ó Hospodine, zajaté naše, tak jako potoky na vyprahlou krajinu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 126, 5, 'Ti, kteříž se slzami rozsívali, s prozpěvováním žíti budou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 126, 6, 'Sem i tam chodící lid s pláčem rozsívá drahé símě, ale potom přijda, s plésáním snášeti bude snopy své.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 127, 1, 'Píseň stupňů, Šalomounova. Nebude-li Hospodin stavěti domu, nadarmo usilují ti, kteříž stavějí jej; nebude-li Hospodin ostříhati města, nadarmo bdí strážný.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 127, 2, 'Daremnéť jest vám ráno vstávati, dlouho sedati, a jísti chléb bolesti, poněvadž Bůh dává milému svému i sen.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 127, 3, 'Aj, dědictví od Hospodina jsou dítky, a plod života jest mzda.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 127, 4, 'Jako střely v ruce udatného, tak jsou dítky zdárné.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 127, 5, 'Blahoslavený muž, kterýž by jimi naplnil toul svůj; nebudouť zahanbeni, když v rozepři budou s nepřátely v branách.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 128, 1, 'Píseň stupňů. Blahoslavený každý, kdo se bojí Hospodina, a chodí po cestách jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 128, 2, 'Nebo z práce rukou svých živnost míti budeš, blahoslavený budeš, a šťastněť se povede.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 128, 3, 'Manželka tvá jako vinný kmen plodný po bocích domu tvého, dítky tvé jako mladistvé olivoví vůkol stolu tvého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 128, 4, 'Aj, takovéť bude míti požehnání muž bojící se Hospodina.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 128, 5, 'Požehnání tobě uděliž Hospodin z Siona, a ty spatřuj dobré věci Jeruzaléma po všecky dny života svého;');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 128, 6, 'A viz syny synů svých, a pokoj nad Izraelem.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 129, 1, 'Píseň stupňů. Veliceť jsou mne ssužovali hned od mladosti mé, rciž nyní Izraeli,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 129, 2, 'Veliceť jsou mne ssužovali hned od mladosti mé, a však mne nepřemohli.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 129, 3, 'Po hřbetě mém orali oráči, a dlouhé proháněli brázdy své.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 129, 4, 'Ale Hospodin jsa spravedlivý, zpřetínal prostranky bezbožných.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 129, 5, 'Zahanbeni a zpět obráceni budou všickni, kteříž nenávidí Siona.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 129, 6, 'Budou jako tráva na střechách, kteráž prvé než odrostá, usychá.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 129, 7, 'Z níž nemůže hrsti své naplniti žnec, ani náručí svého ten, kterýž váže snopy.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 129, 8, 'Aniž řeknou tudy jdoucí: Požehnání Hospodinovo budiž s vámi, aneb: Dobrořečíme vám ve jménu Hospodinovu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 130, 1, 'Píseň stupňů. Z hlubokosti volám k tobě, Hospodine.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 130, 2, 'Pane, vyslyš hlas můj, nakloň uší svých k hlasu pokorných proseb mých.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 130, 3, 'Budeš-li nepravosti šetřiti, Hospodine Pane, kdo ostojí?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 130, 4, 'Ale u tebe jest odpuštění, tak aby uctivost k tobě zachována byla.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 130, 5, 'Očekávám na Hospodina, očekává duše má, a ještě očekává na slovo jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 130, 6, 'Duše má čeká Pána, víc než ponocní svitání, kteříž ponocují až do jitra.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 130, 7, 'Očekávejž, Izraeli, na Hospodina; nebo u Hospodina jest milosrdenství, a hojné u něho vykoupení.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 130, 8, 'Onť zajisté vykoupí Izraele ze všech nepravostí jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 131, 1, 'Píseň stupňů, Davidova. Hospodine, nepozdvihlotě se srdce mé, ani se povýšily oči mé, aniž jsem se vydal v věci veliké, aneb vyšší nad to, než mi náleží.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 131, 2, 'Zdali jsem nepoložil a neupokojil duše své, jako dítě ostavené od matky své? Ostavenému podobná byla ve mně duše má.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 131, 3, 'Doufej, ó Izraeli, v Hospodina, od tohoto času až na věky.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 1, 'Píseň stupňů. Pamětliv buď, Hospodine, na Davida i na všecka trápení jeho,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 2, 'Jak se přísahou zavázal Hospodinu, a slib učinil Nejmocnějšímu Jákobovu, řka:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 3, 'Jistě že nevejdu do stánku domu svého, a nevstoupím na postel ložce svého,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 4, 'Aniž dám očím svým usnouti, ani víčkám svým zdřímati,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 5, 'Dokudž nenajdu místa Hospodinu, k příbytkům Nejmocnějšímu Jákobovu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 6, 'Aj, uslyšavše o ní, že byla v kraji Efratském, našli jsme ji na polích Jaharských.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 7, 'Vejdemeť již do příbytků jeho, a skláněti se budeme u podnoží noh jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 8, 'Povstaniž, Hospodine, a vejdi do odpočinutí svého, ty i truhla velikomocnosti tvé.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 9, 'Kněží tvoji ať se zobláčejí v spravedlnost, a svatí tvoji ať vesele prozpěvují.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 10, 'Pro Davida služebníka svého neodvracejž tváři pomazaného svého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 11, 'Učinilť jest Hospodin pravdomluvnou přísahu Davidovi, aniž se od ní uchýlí, řka: Z plodu života tvého posadím na trůn tvůj.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 12, 'Budou-li ostříhati synové tvoji smlouvy mé a svědectví mých, kterýmž je vyučovati budu, také i synové jejich až na věky seděti budou na stolici tvé.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 13, 'Neboť jest vyvolil Hospodin Sion, oblíbil jej sobě za svůj příbytek, řka:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 14, 'Toť bude obydlí mé až na věky, tuť přebývati budu, nebo jsem sobě to oblíbil.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 15, 'Potravu jeho hojným požehnáním rozmnožím, chudé jeho chlebem nasytím,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 16, 'A kněží jeho v spasení zobláčím, a svatí jeho vesele prozpěvovati budou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 17, 'Tuť způsobím, aby zkvetl roh Davidův; připravím svíci pomazanému svému.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 18, 'Nepřátely jeho v hanbu zobláčím, nad ním pak kvésti bude koruna jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 133, 1, 'Píseň stupňů, Davidova. Aj, jak dobré a jak utěšené, když bratří v jednomyslnosti přebývají!');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 133, 2, 'Jako mast výborná na hlavě, sstupující na bradu, bradu Aronovu, tekoucí až i na podolek roucha jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 133, 3, 'A jako rosa Hermon, kteráž sstupuje na hory Sionské. Nebo tu udílí Hospodin požehnání i života až na věky.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 134, 1, 'Píseň stupňů. Ej nuž dobrořečte Hospodinu všickni služebníci Hospodinovi, kteříž stáváte v domě Hospodinově každé noci.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 134, 2, 'Pozdvihujte rukou svých k svatyni, a dobrořečte Hospodinu, říkajíce:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 134, 3, 'Požehnejž tobě Hospodin z Siona, kterýž učinil nebe i zemi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 1, 'Halelujah. Chvalte jméno Hospodinovo, chvalte služebníci Hospodinovi,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 2, 'Kteříž stáváte v domě Hospodinově, v síňcích domu Boha našeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 3, 'Chvalte Hospodina, nebo jest dobrý Hospodin; žalmy zpívejte jménu jeho, nebo rozkošné jest.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 4, 'Jákoba zajisté sobě vyvolil Hospodin, a Izraele za svůj lid zvláštní.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 5, 'Jáť jsem jistě seznal, že veliký jest Hospodin, a Pán náš nade všecky bohy.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 6, 'Cožkoli chce Hospodin, to činí na nebi i na zemi, v moři i ve všech propastech.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 7, 'Kterýž způsobuje to, že páry vystupují od krajů země; blýskání s deštěm přivodí, a vyvodí vítr z pokladů svých.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 8, 'Kterýž zbil prvorozené v Egyptě, od člověka až do hovada.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 9, 'Poslal znamení a zázraky u prostřed tebe, Egypte, na Faraona i na všecky služebníky jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 10, 'Kterýž pobil národy mnohé, a zbil krále mocné,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 11, 'Seona krále Amorejského, a Oga krále Bázan, i všecka království Kananejská.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 12, 'A dal zemi jejich v dědictví, v dědictví Izraelovi lidu svému.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 13, 'Hospodine, jméno tvé na věky, Hospodine, památka tvá od národu až do pronárodu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 14, 'Souditi zajisté bude Hospodin lid svůj, a služebníkům svým bude milostiv.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 15, 'Ale modly pohanské stříbro a zlato, dílo rukou lidských,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 16, 'Ústa mají a nemluví, oči mají a nevidí.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 17, 'Uši mají a neslyší, nýbrž ani ducha není v ústech jejich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 18, 'Buďtež jim podobní, kteříž je dělají, a kdožkoli naději svou v nich skládají.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 19, 'Dome Izraelský, dobrořečte Hospodinu; dome Aronův, dobrořečte Hospodinu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 20, 'Dome Léví, dobrořečte Hospodinu; kteříž se bojíte Hospodina, dobrořečte Hospodinu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 21, 'Požehnaný Hospodin z Siona, kterýž přebývá v Jeruzalémě. Halelujah.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 1, 'Oslavujte Hospodina, nebo jest dobrý, nebo věčné jest milosrdenství jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 2, 'Oslavujte Boha bohů, nebo jest věčné milosrdenství jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 3, 'Oslavujte Pána pánů, nebo jest věčné milosrdenství jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 4, 'Toho, kterýž sám činí divy veliké, nebo jest věčné milosrdenství jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 5, 'Kterýž učinil nebesa moudře, nebo jest věčné milosrdenství jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 6, 'Kterýž roztáhl zemi na vodách, nebo jest věčné milosrdenství jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 7, 'Kterýž učinil světla veliká, nebo jest věčné milosrdenství jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 8, 'Slunce, aby panovalo ve dne, nebo jest věčné milosrdenství jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 9, 'Měsíc a hvězdy, aby panovaly v noci, nebo jest věčné milosrdenství jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 10, 'Kterýž ranil Egyptské v prvorozených jejich, nebo jest věčné milosrdenství jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 11, 'A vyvedl Izraele z prostředku jejich, nebo jest věčné milosrdenství jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 12, 'V ruce silné a v rameni vztaženém, nebo jest věčné milosrdenství jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 13, 'Kterýž rozdělil moře Rudé na díly, nebo jest věčné milosrdenství jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 14, 'A převedl Izraele prostředkem jeho, nebo jest věčné milosrdenství jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 15, 'A uvrhl Faraona s vojskem jeho do moře Rudého, nebo jest věčné milosrdenství jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 16, 'Kterýž vedl lid svůj přes poušť, nebo jest věčné milosrdenství jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 17, 'Kterýž pobil krále veliké, nebo jest věčné milosrdenství jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 18, 'A zbil krále znamenité, nebo jest věčné milosrdenství jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 19, 'Seona krále Amorejského, nebo jest věčné milosrdenství jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 20, 'Též Oga krále Bázan, nebo jest věčné milosrdenství jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 21, 'A dal zemi jejich v dědictví, nebo jest věčné milosrdenství jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 22, 'V dědictví Izraelovi, služebníku svému, nebo jest věčné milosrdenství jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 23, 'Kterýž v snížení našem pamatuje na nás, nebo jest věčné milosrdenství jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 24, 'A vytrhl nás z nepřátel našich, nebo jest věčné milosrdenství jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 25, 'Kterýž dává pokrm všelikému tělu, nebo jest věčné milosrdenství jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 26, 'Oslavujte Boha silného nebes, neboť jest věčné milosrdenství jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 137, 1, 'Při řekách Babylonských tam jsme sedávali, a plakávali, rozpomínajíce se na Sion.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 137, 2, 'Na vrbí v té zemi zavěšovali jsme citary své.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 137, 3, 'A když se tam dotazovali nás ti, kteříž nás zajali, na slova písničky, (ješto jsme zavěsili byli veselí), říkajíce: Zpívejte nám některou píseň Sionskou:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 137, 4, 'Kterakž bychom měli zpívati píseň Hospodinovu v zemi cizozemců?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 137, 5, 'Jestliže se zapomenu na tebe, ó Jeruzaléme, zapomeniž i pravice má.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 137, 6, 'Přilniž i jazyk můj k dásním mým, nebudu-li se rozpomínati na tebe, jestliže v samém Jeruzalémě nebudu míti svého největšího potěšení.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 137, 7, 'Rozpomeň se, Hospodine, na Idumejské, a na den Jeruzaléma, kteříž pravili: Rozbořte, rozbořte až do základů v něm.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 137, 8, 'Ó dcero Babylonská, zkažena býti máš. Blahoslavený ten, kdož odplatí tobě za to, což jsi nám zlého učinila.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 137, 9, 'Blahoslavený, kdož pochytí dítky tvé a o skálu je rozrážeti bude.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 138, 1, 'Davidův. Oslavovati tě budu, Pane, celým srdcem svým, a před mocnými žalmy tobě zpívati.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 138, 2, 'Skláněti se budu k chrámu svatému tvému, a oslavovati jméno tvé pro milosrdenství tvé a pro pravdu tvou; nebo jsi zvelebil nade všecko jméno své a slovo své.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 138, 3, 'Kteréhokoli dne vzýval jsem tě, vyslyšels mne, a obdařils silou duši mou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 138, 4, 'Oslavovati tě budou, Hospodine, i všickni králové země, když uslyší řeč úst tvých.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 138, 5, 'A zpívati budou o cestách Hospodinových, a že veliká jest sláva Hospodinova,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 138, 6, 'A ač vyvýšený jest Hospodin, však že na poníženého patří, a vysokomyslného zdaleka zná.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 138, 7, 'Bych pak chodil u prostřed ssoužení, obživíš mne; proti vzteklosti nepřátel mých vztáhneš ruku svou, a tak vysvobodí mne pravice tvá.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 138, 8, 'Hospodin dokoná za mne; nebo milosrdenství tvé, Hospodine, na věky, aniž díla rukou svých kdy opustíš.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 1, 'Přednímu zpěváku, žalm Davidův. Hospodine, ty jsi mne zkusil a seznal.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 2, 'Ty znáš sednutí mé i povstání mé, rozumíš myšlení mému zdaleka.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 3, 'Chození mé i ležení mé ty obsahuješ, a všech mých cest svědom jsi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 4, 'Než ještě mám na jazyku slovo, aj, Hospodine, ty to všecko víš.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 5, 'Z zadu i z předu obklíčils mne, a vzložils na mne ruku svou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 6, 'Divnější jest umění tvé nad můj vtip; vysoké jest, nemohu k němu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 7, 'Kamž bych zašel od ducha tvého? Aneb kam bych před tváří tvou utekl?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 8, 'Jestliže bych vstoupil na nebe, tam jsi ty; pakli bych sobě ustlal v hrobě, aj, přítomen jsi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 9, 'Vzal-li bych křídla záře jitřní, abych bydlil při nejdalším moři:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 10, 'I tamť by mne ruka tvá provedla, a pravice tvá by mne popadla.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 11, 'Dím-li pak: Aspoň tmy, jako v soumrak, přikryjí mne, ale i noc jest světlem vůkol mne.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 12, 'Aniž ty tmy před tebou ukryti mohou, anobrž noc jako den tobě svítí, rovně tma jako světlo.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 13, 'Ty zajisté v moci máš ledví má, přioděl jsi mne v životě matky mé.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 14, 'Oslavuji tě, proto že se hrozným a divným skutkům tvým divím, a duše má zná je výborně.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 15, 'Neníť ukryta žádná kost má před tebou, jakž jsem učiněn v skrytě, a řemeslně složen, v nejhlubších místech země.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 16, 'Trupel můj viděly oči tvé, v knihu tvou všickni oudové jeho zapsáni jsou, i dnové, v nichž formováni byli, když ještě žádného z nich nebylo.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 17, 'Protož u mne ó jak drahá jsou myšlení tvá, Bože silný, a jak jest jich nesčíslná summa!');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 18, 'Chtěl-li bych je sčísti, více jest jich než písku; procítím-li, a já jsem vždy s tebou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 19, 'Zabil-li bys, ó Bože, bezbožníka, tehdážť by muži vražedlní odstoupili ode mne,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 20, 'Kteříž mluví proti tobě nešlechetně; marně vyvyšují nepřátely tvé.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 21, 'Zdaliž těch, kteříž tě v nenávisti mají, ó Hospodine, v nenávisti nemám? A ti, kteříž proti tobě povstávají, zdaž mne nemrzejí?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 22, 'Úhlavní nenávistí jich nenávidím, a mám je za nepřátely.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 23, 'Vyzpytuj mne, Bože silný, a poznej srdce mé; zkus mne, a poznej myšlení má.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 24, 'A popatř, chodím-liť já cestou odpornou tobě, a veď mne cestou věčnou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 140, 1, 'Přednímu z kantorů, žalm Davidův. Vysvoboď mne, Hospodine, od člověka zlého, a od muže ukrutného ostříhej mne,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 140, 2, 'Kteříž myslí zlé věci v srdci, a na každý den sbírají se k válce.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 140, 3, 'Naostřují jazyk svůj jako had, jed lítého hada jest ve rtech jejich. Sélah.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 140, 4, 'Ostříhej mne, Hospodine, od rukou bezbožníka, od muže ukrutného zachovej mne, kteříž myslí podraziti nohy mé.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 140, 5, 'Polékli pyšní na mne osídlo a provazy, roztáhli teneta u cesty, a léčky své mi položili. Sélah.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 140, 6, 'Řekl jsem Hospodinu: Bůh silný můj jsi, pozoruj, Hospodine, hlasu pokorných modliteb mých.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 140, 7, 'Hospodine Pane, sílo spasení mého, kterýž přikrýváš hlavu mou v čas boje,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 140, 8, 'Nedávej, Hospodine, bezbožnému, čehož žádostiv jest, ani předsevzetí zlého vykonati jemu dopouštěj, aby se nepovýšil. Sélah.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 140, 9, 'Vůdce těch, jenž obkličují mne, nepravost rtů jejich ať přikryje.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 140, 10, 'Padej na ně uhlí řeřavé, a na oheň uvrz je, do jam hlubokých, aby nemohli povstati.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 140, 11, 'Člověk utrhač nebude upevněn na zemi, a muž ukrutný, zlostí polapen jsa, padne.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 140, 12, 'Vím, žeť se Hospodin zasadí o při chudého, a pomstí nuzných.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 140, 13, 'A tak spravedliví slaviti budou jméno tvé, a upřímí přebývati před oblíčejem tvým.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 141, 1, 'Žalm Davidův. Hospodine, k toběť volám, pospěš ke mně; pozoruj hlasu mého, když tebe vzývám.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 141, 2, 'Budiž příjemná modlitba má, jako kadění před oblíčejem tvým, pozdvižení rukou mých, jako obět večerní.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 141, 3, 'Polož, Hospodine, stráž ústům mým, ostříhej dveří rtů mých.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 141, 4, 'Nedopouštěj srdci mému uchýliti se ke zlé věci, k činění skutků bezbožných, s muži činícími nepravost, a abych nebyl přelouzen líbostmi jejich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 141, 5, 'Nechť mne bije spravedlivý, přijmu to za dobrodiní, a nechť tresce mne, bude mi to olej nejčistší, kterýž neprorazí hlavy mé, ale ještěť modlitba má platná bude proti zlosti jejich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 141, 6, 'Smetáni jsou do míst skalnatých soudcové jejich, aby slyšeli slova má, nebo jsou libá.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 141, 7, 'Jako když někdo roubá a štípá dříví na zemi, tak se rozletují kosti naše až k ústům hrobovým.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 141, 8, 'Ale k toběť, Hospodine Pane, oči mé; v tebe doufám, nevylévej duše mé.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 141, 9, 'Zachovej mne od osídla, kteréž mi roztáhli, a od sítek činících nepravost.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 141, 10, 'Nechť padnou hromadně do sítek svých bezbožní, a já zatím přejdu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 142, 1, 'Vyučující Davidův, když byl v jeskyni, modlitba jeho. Hlasem svým k Hospodinu volám, hlasem svým Hospodinu pokorně se modlím.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 142, 2, 'Vylévám před oblíčejem jeho žádost svou, a ssoužení své před ním oznamuji.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 142, 3, 'Když se úzkostmi svírá ve mně duch můj, ty znáš stezku mou; na cestě, po kteréžkoli chodím, osídlo mi ukryli.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 142, 4, 'Ohlédám-li se na pravo, a patřím, není, kdo by mne znáti chtěl; zhynulo útočiště mé, není, kdo by se ujal o život můj.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 142, 5, 'K tobě volám, Hospodine, říkaje: Ty jsi doufání mé a díl můj v zemi živých.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 142, 6, 'Pozorujž volání mého, neboť jsem zemdlen přenáramně; vysvoboď mne od těch, jenž stihají mne, nebo jsou silnější nežli já.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 142, 7, 'Vyveď z žaláře duši mou, abych oslavoval jméno tvé; obstoupí mne spravedliví, když mi dobrodiní učiníš.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 143, 1, 'Žalm Davidův. Hospodine, slyš modlitbu mou, pozoruj pokorné prosby mé; pro pravdu svou vyslyš mne, i pro spravedlnost svou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 143, 2, 'A nevcházej v soud s služebníkem svým, neboť by nebyl spravedliv před tebou nižádný živý.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 143, 3, 'Nebo stihá nepřítel duši mou, potírá až k zemi život můj; na to mne přivodí, abych bydlil v mrákotě, jako ti, kteříž již dávno zemřeli,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 143, 4, 'Tak že se svírá úzkostmi duch můj ve mně, u vnitřnosti mé hyne srdce mé.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 143, 5, 'Rozpomínaje se na dny předešlé, a rozvažuje všecky skutky tvé, a dílo rukou tvých rozjímaje,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 143, 6, 'Vztahuji ruce své k tobě, duše má jako země vyprahlá žádá tebe. Sélah.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 143, 7, 'Pospěšiž a vyslyš mne, Hospodine, hyne duch můj; neukrývejž tváři své přede mnou, neboť jsem podobný těm, kteříž sstupují do hrobu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 143, 8, 'Učiň to, ať v jitře slyším milosrdenství tvé, neboť v tobě naději mám; oznam mi cestu, po kteréž bych choditi měl, neboť k tobě pozdvihuji duše své.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 143, 9, 'Vytrhni mne z nepřátel mých, Hospodine, u tebeť se skrývám.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 143, 10, 'Nauč mne činiti vůle tvé, nebo ty jsi Bůh můj; duch tvůj dobrý vediž mne jako po rovné zemi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 143, 11, 'Pro jméno své, Hospodine, obživ mne, pro spravedlnost svou vyveď z úzkosti duši mou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 143, 12, 'A pro milosrdenství své vypleň nepřátely mé, a vyhlaď všecky, kteříž trápí duši mou; nebo já jsem služebník tvůj.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 144, 1, 'Davidův. Požehnaný Hospodin skála má, kterýž učí ruce mé boji, a prsty mé bitvě.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 144, 2, 'Milosrdenství mé a hrad můj, útočiště mé, vysvoboditel můj, a štít můj, protož v něhoť já doufám; onť mi podmaňuje lidi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 144, 3, 'Hospodine, co jest člověk, že se znáš k němu, a syn člověka, že ho sobě tak vážíš?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 144, 4, 'Člověk marnosti podobný jest, dnové jeho jako stín pomíjející.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 144, 5, 'Hospodine, nakloň svých nebes a sstup, dotkni se hor, a kouřiti se budou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 144, 6, 'Sešli hromobití a rozptyl je, vypusť střely své a poraz je.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 144, 7, 'Vztáhni ruku svou s výsosti, vysvoboď mne, a vytrhni mne z vod mnohých, z ruky cizozemců.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 144, 8, 'Jejichž ústa mluví marnost, a pravice jejich jest pravice lživá.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 144, 9, 'Bože, píseň novou zpívati budu tobě na loutně, a na desíti strunách žalmy tobě prozpěvovati,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 144, 10, 'Dávajícímu vítězství králům, a vysvobozujícímu Davida, služebníka svého od meče vražedlného.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 144, 11, 'Vysvoboď mne, a vytrhni mne z ruky cizozemců, jejichž ústa mluví marnost, a pravice jejich pravice lživá.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 144, 12, 'Aby synové naši byli jako štípkové zdárně rostoucí v mladosti své, a dcery naše jako úhelní kamenové, tesaní ku podobenství chrámu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 144, 13, 'Špižírny naše plné ať vydávají všelijaké potravy; dobytek náš ať rodí na tisíce, a na deset tisíců v stájích našich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 144, 14, 'Volové naši ať jsou vytylí; ať není vpádu ani zajetí, ani naříkání na ulicích našich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 144, 15, 'Blahoslavený lid, jemuž se tak děje, blahoslavený ten lid, jehož Hospodin Bohem jest.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 1, 'Chvalitebná píseň Davidova. Vyvyšovati tě budu, Bože můj králi, a dobrořečiti jménu tvému na věky věků.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 2, 'Na každý den dobrořečiti budu tobě, a chváliti jméno tvé na věky věků.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 3, 'Hospodin veliký jest, a vší chvály hodný, a velikost jeho nemůž vystižena býti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 4, 'Rodina rodině vychvalovati bude skutky tvé, a předivnou moc tvou zvěstovati.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 5, 'O slávě a kráse velebnosti tvé, i o věcech tvých předivných mluviti budu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 6, 'A moc přehrozných skutků tvých rozhlašovati budou; i já důstojnost tvou budu vypravovati.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 7, 'Pamět mnohé dobroty tvé hlásati budou, a o spravedlnosti tvé zpívati, řkouce:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 8, 'Milostivý a lítostivý jest Hospodin, dlouhoshovívající a velikého milosrdenství.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 9, 'Dobrotivý Hospodin všechněm, a slitování jeho nade všecky skutky jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 10, 'Oslavujtež tebe, Hospodine, všickni skutkové tvoji, a svatí tvoji tobě dobrořečte.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 11, 'Slávu království tvého ať vypravují, a o síle tvé mluví,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 12, 'Aby v známost uvedli synům lidským moci jeho, a slávu i ozdobu království jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 13, 'Království tvé jest království všech věků, a panování tvé nad jedním každým pokolením.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 14, 'Zdržujeť Hospodin všecky padající, a pozdvihuje všechněch sklíčených.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 15, 'Oči všechněch v tebe doufají, a ty dáváš jim pokrm jejich v čas příhodný.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 16, 'Otvíráš ruku svou, a nasycuješ každý živočich podlé dobře líbezné vůle své.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 17, 'Spravedlivý jest Hospodin ve všech cestách svých, a milosrdný ve všech skutcích svých.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 18, 'Blízký jest Hospodin všechněm, kteříž ho vzývají, všechněm, kteříž ho vzývají v pravdě.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 19, 'Vůli těch, kteříž se ho bojí, činí, a křik jejich slyší, a spomáhá jim.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 20, 'Ostříhá Hospodin všech, kdož jej milují, ale všecky bezbožné zatratí.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 21, 'Chválu Hospodinovu vypravovati budou ústa má, a dobrořečiti bude všeliké tělo jménu svatému jeho od věků až na věky.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 146, 1, 'Halelujah. Chval, duše má, Hospodina.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 146, 2, 'Chváliti budu Hospodina, dokud jsem živ, žalmy zpívati Bohu svému, dokud mne stává.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 146, 3, 'Nedoufejtež v knížatech, v synech lidských, v nichž není vysvobození.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 146, 4, 'Vychází duch jejich, navracují se do země své, v tentýž den mizejí myšlení jejich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 146, 5, 'Blahoslavený ten, jehož spomocník jest Bůh silný Jákobův, jehož naděje jest v Hospodinu Bohu jeho,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 146, 6, 'Kterýž učinil nebe, zemi, moře, i vše, což v nich jest, kterýž ostříhá pravdy až na věky,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 146, 7, 'Kterýž činí soud utištěným, dává chléb lačným. Hospodin vysvobozuje vězně.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 146, 8, 'Hospodin otvírá oči slepých, Hospodin pozdvihuje snížených, Hospodin miluje spravedlivé.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 146, 9, 'Hospodin ostříhá příchozích, sirotku a vdově pomáhá, ale cestu bezbožných podvrací.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 146, 10, 'Kralovati bude Hospodin na věky, Bůh tvůj, ó Sione, od národu až do pronárodu. Halelujah.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 1, 'Chvalte Hospodina, nebo dobré jest zpívati žalmy Bohu našemu, nebo rozkošné jest, a ozdobná jest chvála.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 2, 'Stavitel Jeruzaléma Hospodin, rozptýlený lid Izraelský shromažďuje,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 3, 'Kterýž uzdravuje skroušené srdcem, a uvazuje bolesti jejich,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 4, 'Kterýž sčítá počet hvězd, a každé z nich ze jména povolává.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 5, 'Velikýť jest Pán náš, a nesmírný v síle; rozumnosti jeho není počtu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 6, 'Pozdvihuje pokorných Hospodin, ale bezbožné snižuje až k zemi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 7, 'Zpívejte Hospodinu s díkčiněním, zpívejte žalmy Bohu našemu na citaře,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 8, 'Kterýž zastírá nebesa hustými oblaky, nastrojuje zemi déšť, a vyvodí trávu na horách.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 9, 'Kterýž dává hovadům potravu jejich, i mladým krkavcům, kteříž volají k němu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 10, 'Nemáť v síle koně zalíbení, aniž se kochá v lejtkách muže udatného.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 11, 'Líbost má Hospodin v těch, kteříž se ho bojí, a kteříž doufají v milosrdenství jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 12, 'Chval, Jeruzaléme, Hospodina, chval Boha svého, Sione.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 13, 'Nebo on utvrzuje závory bran tvých, požehnání udílí synům tvým u prostřed tebe.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 14, 'On působí v končinách tvých pokoj, a bělí pšeničnou nasycuje tě.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 15, 'On když vysílá na zemi rozkaz svůj, velmi rychle k vykonání běží slovo jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 16, 'Onť dává sníh jako vlnu, jíním jako popelem posýpá.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 17, 'Hází ledem svým jako skyvami; před zimou jeho kdo ostojí?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 18, 'Vysílaje slovo své, rozpouští je; hned jakž povane větrem svým, anť tekou vody.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 19, 'Zvěstuje slovo své Jákobovi, ustanovení svá a soudy své Izraelovi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 20, 'Neučinilť tak žádnému národu, a protož soudů jeho nepoznali. Halelujah.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 148, 1, 'Halelujah. Chvalte Hospodina stvoření nebeská, chvaltež ho na výsostech.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 148, 2, 'Chvalte jej všickni andělé jeho, chvalte jej všickni zástupové jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 148, 3, 'Chvalte jej slunce i měsíc, chvalte jej všecky jasné hvězdy.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 148, 4, 'Chvalte jej nebesa nebes, i vody, kteréž jsou nad nebem tímto.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 148, 5, 'Chvalte jméno Hospodinovo všecky věci, kteréž, jakž on řekl, pojednou stvořeny jsou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 148, 6, 'A utvrdil je na věčné věky, uložil cíle, z nichž by nevykračovaly.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 148, 7, 'Chvalte Hospodina tvorové zemští, velrybové a všecky propasti,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 148, 8, 'Oheň a krupobití, sníh i pára, vítr bouřlivý, vykonávající rozkaz jeho,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 148, 9, 'I hory a všickni pahrbkové, stromoví ovoce nesoucí, i všickni cedrové,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 148, 10, 'Zvěř divoká i všeliká hovada, zeměplazové i ptactvo létavé,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 148, 11, 'Králové zemští i všickni národové, knížata i všickni soudcové země,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 148, 12, 'Mládenci, též i panny, starci s dítkami,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 148, 13, 'Chvalte jméno Hospodinovo; nebo vyvýšeno jest jméno jeho samého, a sláva jeho nade všecku zemi i nebe.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 148, 14, 'A vyzdvihl roh lidu svého, chválu všech svatých jeho, synů Izraelských, lidu s ním spojeného. Halelujah.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 149, 1, 'Halelujah. Zpívejte Hospodinu píseň novou, chválu jeho v shromáždění svatých.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 149, 2, 'Vesel se Izrael v tom, kterýž ho učinil, synové Sionští plésejte v králi svém.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 149, 3, 'Chvalte jméno jeho na píšťalu, na buben a na citaru prozpěvujte jemu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 149, 4, 'Nebo zalíbilo se Hospodinu v lidu jeho; onť ozdobuje pokorné spasením.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 149, 5, 'Plésati budou svatí v Boží slávě, a zpívati v pokojích svých.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 149, 6, 'Oslavování Boha silného bude ve rtech jejich, a meč na obě straně ostrý v rukou jejich,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 149, 7, 'K vykonávání pomsty nad pohany, a k strestání národů,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 149, 8, 'K svazování králů jejich řetězy, a šlechticů jejich pouty železnými,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 149, 9, 'K nakládání s nimi podlé práva zapsaného, k slávě všechněm svatým jeho. Halelujah.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 150, 1, 'Halelujah. Chvalte Boha silného pro svatost jeho, chvalte jej pro rozšíření síly jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 150, 2, 'Chvalte jej ze všelijaké moci jeho, chvalte jej podlé veliké důstojnosti jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 150, 3, 'Chvalte jej zvukem trouby, chvalte jej na loutnu a citaru.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 150, 4, 'Chvalte jej na buben a píšťalu, chvalte jej na husle a varhany.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 150, 5, 'Chvalte jej na cymbály hlasité, chvalte jej na cymbály zvučné.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 150, 6, 'Všeliký duch chval Hospodina. Halelujah.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 1, 'Přísloví Šalomouna syna Davidova, krále Izraelského,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 2, 'Ku poznání moudrosti a cvičení, k vyrozumívání řečem rozumnosti,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 3, 'K dosažení vycvičení v opatrnosti, spravedlnosti, soudu a toho, což pravého jest,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 4, 'Aby dána byla hloupým důmyslnost, mládenečku umění a prozřetelnost.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 5, 'Když poslouchati bude moudrý, přibude mu umění, a rozumný bude vtipnější,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 6, 'K srozumění podobenství, a výmluvnosti řeči moudrých a pohádkám jejich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 7, 'Bázeň Hospodinova jest počátek umění, moudrostí a cvičením pohrdají blázni.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 8, 'Poslouchej, synu můj, cvičení otce svého, a neopouštěj naučení matky své.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 9, 'Neboť to přidá příjemnosti hlavě tvé, a bude zlatým řetězem hrdlu tvému.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 10, 'Synu můj, jestliže by tě namlouvali hříšníci, nepřivoluj.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 11, 'Jestliže by řekli: Poď s námi, úklady čiňme krvi, skryjeme se proti nevinnému bez ostýchání se;');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 12, 'Sehltíme je jako hrob za živa, a v cele jako ty, jenž sstupují do jámy;');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 13, 'Všelijakého drahého zboží dosáhneme, naplníme domy své loupeží;');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 14, 'Vrz los svůj mezi nás, měšec jeden budeme míti všickni:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 15, 'Synu můj, nevycházej na cestu s nimi, zdrž nohu svou od stezky jejich;');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 16, 'Nebo nohy jejich ke zlému běží, a pospíchají k vylévání krve.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 17, 'Jistě, že jakož nadarmo roztažena bývá sít před očima jakéhokoli ptactva,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 18, 'Tak tito proti krvi své ukládají, skrývají se proti dušem svým.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 19, 'Takovéť jsou cesty každého dychtícího po zisku, duši pána svého uchvacuje.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 20, 'Moudrost vně volá, na ulicech vydává hlas svůj.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 21, 'V největším hluku volá, u vrat brány, v městě, a výmluvnosti své vypravuje, řka:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 22, 'Až dokud hloupí milovati budete hloupost, a posměvači posměch sobě libovati, a blázni nenáviděti umění?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 23, 'Obraťtež se k domlouvání mému. Hle, vynáším vám ducha svého, a v známost vám uvodím slova svá.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 24, 'Poněvadž jsem volala, a odpírali jste; vztahovala jsem ruku svou, a nebyl, kdo by pozoroval,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 25, 'Anobrž strhli jste se všeliké rady mé, a trestání mého jste neoblíbili:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 26, 'Pročež i já v bídě vaší smáti se budu, posmívati se budu, když přijde to, čehož se bojíte,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 27, 'Když přijde jako hrozné zpuštění to, čehož se bojíte, a bída vaše jako bouře nastane, když přijde na vás trápení a ssoužení.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 28, 'Tehdy volati budou ke mně, a nevyslyším; ráno hledati mne budou, a nenaleznou mne.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 29, 'Proto že nenáviděli umění, a bázně Hospodinovy nevyvolili,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 30, 'Aniž povolili radě mé, ale pohrdali všelikým domlouváním mým.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 31, 'Protož jísti budou ovoce skutků svých, a radami svými nasyceni budou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 32, 'Nebo pokoj hloupých zmorduje je, a štěstí bláznů zahubí je.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 33, 'Ale kdož mne poslouchá, bydliti bude bezpečně, pokoj maje před strachem zlých věcí.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 1, 'Synu můj, přijmeš-li slova má, a přikázaní má schováš-li u sebe;');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 2, 'Nastavíš-li moudrosti ucha svého, a nakloníš-li srdce svého k opatrnosti;');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 3, 'Ovšem, jestliže na rozumnost zavoláš, a na opatrnost zvoláš-li;');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 4, 'Budeš-li jí hledati jako stříbra, a jako pokladů pilně vyhledávati jí:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 5, 'Tehdy porozumíš bázni Hospodinově, a známosti Boží nabudeš;');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 6, 'Nebo Hospodin dává moudrost, z úst jeho umění a opatrnost.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 7, 'Chová upřímým dlouhověkosti, pavézou jest chodícím v sprostnosti,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 8, 'Ostříhaje stezek soudu; on cesty svatých svých ostříhá.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 9, 'Tehdy porozumíš spravedlnosti a soudu, a upřímosti i všeliké cestě dobré,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 10, 'Když vejde moudrost v srdce tvé, a umění duši tvé se zalíbí.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 11, 'Prozřetelnost ostříhati bude tebe, a opatrnost zachová tě,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 12, 'Vysvobozujíc tě od cesty zlé, a od lidí mluvících věci převrácené,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 13, 'Kteříž opouštějí stezky přímé, aby chodili po cestách tmavých,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 14, 'Kteříž se veselí ze zlého činění, plésají v převrácenostech nejhorších,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 15, 'Jejichž stezky křivolaké jsou, anobrž zmotaní jsou na cestách svých;');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 16, 'Vysvobozujíc tě i od ženy postranní, od cizí, kteráž řečmi svými lahodí,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 17, 'Kteráž opouští vůdce mladosti své, a na smlouvu Boha svého se zapomíná;');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 18, 'K smrti se zajisté nachyluje dům její, a k mrtvým stezky její;');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 19, 'Kteřížkoli vcházejí k ní, nenavracují se zase, aniž trefují na cestu života;');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 20, 'Abys chodil po cestě dobrých, a stezek spravedlivých abys ostříhal.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 21, 'Nebo upřímí bydliti budou v zemi, a pobožní zůstanou v ní;');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 22, 'Bezbožní pak z země vyťati budou, a přestupníci vykořeněni budou z ní.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 1, 'Synu můj, na učení mé nezapomínej, ale přikázaní mých nechať ostříhá srdce tvé.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 2, 'Dlouhosti zajisté dnů, i let života i pokoje přidadí tobě.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 3, 'Milosrdenství a pravda nechť neopouštějí tě, přivaž je k hrdlu svému, napiš je na tabuli srdce svého,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 4, 'A nalezneš milost a prospěch výborný před Bohem i lidmi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 5, 'Doufej v Hospodina celým srdcem svým, na rozumnost pak svou nezpoléhej.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 6, 'Na všech cestách svých snažuj se jej poznávati, a onť spravovati bude stezky tvé.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 7, 'Nebývej moudrý sám u sebe; boj se Hospodina, a odstup od zlého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 8, 'Toť bude zdraví životu tvému, a rozvlažení kostem tvým.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 9, 'Cti Hospodina z statku svého, a z nejpřednějších věcí všech úrod svých,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 10, 'A naplněny budou stodoly tvé hojností, a presové tvoji mstem oplývati budou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 11, 'Kázně Hospodinovy, synu můj, nezamítej, aniž sobě oškliv domlouvání jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 12, 'Nebo kohož miluje Hospodin, tresce, a to jako otec syna, jejž libuje.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 13, 'Blahoslavený člověk nalézající moudrost, a člověk vynášející opatrnost.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 14, 'Lépeť jest zajisté těžeti jí, nežli těžeti stříbrem, anobrž nad výborné zlato užitek její.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 15, 'Dražší jest než drahé kamení, a všecky nejžádostivější věci tvé nevrovnají se jí.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 16, 'Dlouhost dnů v pravici její, a v levici její bohatství a sláva.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 17, 'Cesty její cesty utěšené, a všecky stezky její pokojné.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 18, 'Stromem života jest těm, kteříž jí dosahují, a kteříž ji mají, blahoslavení jsou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 19, 'Hospodin moudrostí založil zemi, utvrdil nebesa opatrností.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 20, 'Uměním jeho propasti protrhují se, a oblakové vydávají rosu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 21, 'Synu můj, nechť neodcházejí ty věci od očí tvých, ostříhej zdravého naučení a prozřetelnosti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 22, 'I budeť to životem duši tvé, a ozdobou hrdlu tvému.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 23, 'Tehdy choditi budeš bezpečně cestou svou, a v nohu svou neurazíš se.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 24, 'Když lehneš, nebudeš se strašiti, ale odpočívati budeš, a bude libý sen tvůj.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 25, 'Nelekneš se strachu náhlého, ani zpuštění bezbožníků, když přijde.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 26, 'Nebo Hospodin bude doufání tvé, a ostříhati bude nohy tvé, abys nebyl lapen.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 27, 'Nezadržuj dobrodiní potřebujícím, když s to býti můžeš, abys je činil.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 28, 'Neříkej bližnímu svému: Odejdi, potom navrať se, a zítrať dám, maje to u sebe.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 29, 'Neukládej proti bližnímu svému zlého, kterýž s tebou dověrně bydlí.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 30, 'Nevaď se s člověkem bez příčiny, jestližeť neučinil zlého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 31, 'Nechtěj záviděti muži dráči, aniž zvoluj které cesty jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 32, 'Nebo ohavností jest Hospodinu převrácenec, ale s upřímými tajemství jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 33, 'Zlořečení Hospodinovo jest v domě bezbožníka, ale příbytku spravedlivých žehná:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 34, 'Poněvadž posměvačům on se posmívá, pokorným pak dává milost.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 35, 'Slávu moudří dědičně obdrží, ale blázny hubí pohanění.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 1, 'Poslouchejte, synové, učení otcova, a pozorujte, abyste poznali rozumnost.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 2, 'Nebo naučení dobré dávám vám, neopouštějtež zákona mého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 3, 'Když jsem byl syn u otce svého mladičký, a jediný při matce své,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 4, 'On vyučoval mne a říkal mi: Ať se chopí výmluvností mých srdce tvé, ostříhej přikázaní mých, a živ budeš.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 5, 'Nabuď moudrosti, nabuď rozumnosti; nezapomínej, ani se uchyluj od řečí úst mých.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 6, 'Neopouštějž jí, a bude tě ostříhati; miluj ji, a zachová tě.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 7, 'Předně moudrosti, moudrosti nabývej, a za všecko jmění své zjednej rozumnost.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 8, 'Vyvyšuj ji, a zvýšíť tě; poctí tě, když ji přijmeš.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 9, 'Přidá hlavě tvé příjemnosti, korunou krásnou obdaří tě.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 10, 'Slyš, synu můj, a přijmi řeči mé, a tak rozmnoží se léta života tvého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 11, 'Cestě moudrosti učím tě, vedu tě stezkami přímými.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 12, 'Když choditi budeš, nebude ssoužen krok tvůj, a poběhneš-li, neustrčíš se.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 13, 'Chopiž se učení, nepouštěj, ostříhej ho, nebo ono jest život tvůj.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 14, 'Na stezku bezbožných nevcházej, a nekráčej cestou zlostníků.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 15, 'Opusť ji, nechoď po ní, uchyl se od ní, a pomiň jí.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 16, 'Neboť nespí, leč zlost provedou; anobrž zahánín bývá sen jejich, dokudž ku pádu nepřivodí,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 17, 'Proto že jedí chléb bezbožnosti, a víno loupeží pijí.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 18, 'Ale stezka spravedlivých jako světlo jasné, kteréž rozmáhá se, a svítí až do pravého dne.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 19, 'Cesta pak bezbožných jako mrákota; nevědí, na čem se ustrčiti mohou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 20, 'Synu můj, slov mých pozoruj, k řečem mým nakloň ucha svého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 21, 'Nechať neodcházejí od očí tvých, ostříhej jich u prostřed srdce svého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 22, 'Nebo životem jsou těm, kteříž je nalézají, i všemu tělu jejich lékařstvím.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 23, 'Přede vším, čehož se stříci sluší, ostříhej srdce svého, nebo z něho pochází život.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 24, 'Odlož od sebe převrácenost úst, a zlost rtů vzdal od sebe.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 25, 'Oči tvé ať k dobrým věcem patří, a víčka tvá ať přímě hledí před tebou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 26, 'Zvaž stezku noh svých, a všecky cesty tvé ať jsou spraveny.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 27, 'Neuchyluj se na pravo ani na levo, odvrať nohu svou od zlého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 1, 'Synu můj, pozoruj moudrosti mé, k opatrnosti mé nakloň ucha svého,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 2, 'Abys ostříhal prozřetelnosti, a rtové tvoji šetřili umění.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 3, 'Nebo rtové cizí ženy strdí tekou, a měkčejší nad olej ústa její.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 4, 'Poslední pak věci její hořké jsou jako pelyněk, ostré jako meč na obě straně ostrý.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 5, 'Nohy její sstupují k smrti, krokové její hrob uchvacují.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 6, 'Stezku života snad bys zvážiti chtěl? Vrtkéť jsou cesty její, neseznáš.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 7, 'Protož, synové, poslechněte mne, a neodstupujte od řečí úst mých.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 8, 'Vzdal od ní cestu svou, a nepřibližuj se ke dveřím domu jejího,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 9, 'Abys snad nedal jiným slávy své, a let svých ukrutnému,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 10, 'Aby se nenasytili cizí úsilím tvým, a práce tvá nezůstala v domě cizím.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 11, 'I řval bys naposledy, když bys zhubil tělo své a čerstvost svou,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 12, 'A řekl bys: Jak jsem nenáviděl cvičení, a domlouváním pohrdalo srdce mé,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 13, 'A neposlouchal jsem hlasu vyučujících mne, a k učitelům svým nenaklonil jsem ucha svého!');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 14, 'O málo, že jsem nevlezl ve všecko zlé u prostřed shromáždění a zástupu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 15, 'Pí vodu z čisterny své, a prameny z prostředku vrchoviště svého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 16, 'Nechť se rozlévají studnice tvé ven, a potůčkové vod na ulice.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 17, 'Měj je sám sobě, a ne cizí s tebou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 18, 'Budiž požehnaný pramen tvůj, a vesel se z manželky mladosti své.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 19, 'Laně milostné a srny utěšené; prsy její ať tě opojují všelikého času, v milování jejím kochej se ustavičně.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 20, 'Nebo proč bys se kochal, synu můj, v cizí, a objímal život postranní,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 21, 'Poněvadž před očima Hospodinovýma jsou cesty člověka, a on všecky stezky jeho váží?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 22, 'Nepravosti vlastní jímají bezbožníka takového, a v provazích hříchu svého uvázne.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 23, 'Takovýť umře, proto že nepřijímal cvičení, a ve množství bláznovství svého blouditi bude.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 1, 'Synu můj, slíbil-lis za přítele svého, podal-lis cizímu ruky své,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 2, 'Zapleten jsi slovy úst svých, jat jsi řečmi úst svých.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 3, 'Učiniž tedy toto, synu můj, a vyprosť se, poněvadžs se dostal v ruku přítele svého. Jdi, pokoř se, a probuď přítele svého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 4, 'Nedej usnouti očím svým, a zdřímati víčkám svým.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 5, 'Vydři se jako srna z ruky, a jako pták z ruky čižebníka.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 6, 'Jdi k mravenci, lenochu, shlédni cesty jeho, a nabuď moudrosti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 7, 'Kterýž nemaje vůdce, ani správce, ani pána,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 8, 'Připravuje v létě pokrm svůj, shromažďuje ve žni potravu svou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 9, 'Dokudž lenochu ležeti budeš? Skoro-liž vstaneš ze sna svého?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 10, 'Maličko pospíš, maličko zdřímeš, maličko složíš ruce, abys poležel,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 11, 'V tom přijde jako pocestný chudoba tvá, a nouze tvá jako muž zbrojný.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 12, 'Člověk nešlechetný, muž nepravý chodí v převrácenosti úst.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 13, 'Mhourá očima svýma, mluví nohama svýma, ukazuje prsty svými.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 14, 'Převrácenost všeliká jest v srdci jeho, smýšlí zlé všelikého času, sváry rozsívá.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 15, 'A protož v náhle přijde bída jeho, rychle setřín bude, a nebudeť uléčení.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 16, 'Těchto šesti věcí nenávidí Hospodin, a sedmá ohavností jest duši jeho:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 17, 'Očí vysokých, jazyka lživého, a rukou vylévajících krev nevinnou,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 18, 'Srdce, kteréž ukládá myšlení nepravá, noh kvapných běžeti ke zlému,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 19, 'Svědka lživého, mluvícího lež, a toho, jenž rozsívá různice mezi bratřími.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 20, 'Ostříhejž, synu můj, přikázaní otce svého, a neopouštěj naučení matky své.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 21, 'Přivazuj je k srdci svému ustavičně, a k hrdlu svému je připínej.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 22, 'Kamžkoli půjdeš, ono tě zprovodí, když spáti budeš, bude tě ostříhati, a když procítíš, bude s tebou rozmlouvati,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 23, '(Nebo přikázaní jest svíce, a naučení světlo, a cesta života jsou domlouvání vyučující),');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 24, 'Aby tě ostříhalo od ženy zlé, od úlisnosti jazyka ženy cizí.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 25, 'Nežádejž krásy její v srdci svém, a nechať tě nejímá víčky svými.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 26, 'Nebo příčinou ženy cizoložné zchudl bys až do kusu chleba, anobrž žena cizoložná drahou duši ulovuje.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 27, 'Může-liž kdo skrýti oheň v klíně svém, aby roucho jeho se nepropálilo?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 28, 'Může-liž kdo choditi po uhlí řeřavém, aby nohy jeho se neopálily?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 29, 'Tak kdož vchází k ženě bližního svého, nebudeť bez viny, kdož by se jí koli dotkl.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 30, 'Neuvozují potupy na zloděje, jestliže by ukradl, aby nasytil život svůj, když lační,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 31, 'Ač postižen jsa, navracuje to sedmernásobně, vším statkem domu svého nahražuje:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 32, 'Ale cizoložící s ženou blázen jest; kdož hubí duši svou, tenť to činí;');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 33, 'Trápení a lehkosti dochází, a útržka jeho nebývá shlazena.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 34, 'Nebo zůřivý jest hněv muže, a neodpouštíť v den pomsty.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 35, 'Neohlídá se na žádnou záplatu, aniž přijímá, by i množství darů dával.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 1, 'Synu můj, ostříhej řečí mých, a přikázaní má schovej u sebe.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 2, 'Ostříhej přikázaní mých, a živ budeš, a naučení mého jako zřítelnice očí svých.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 3, 'Přivaž je na prsty své, napiš je na tabuli srdce svého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 4, 'Rci moudrosti: Sestra má jsi ty, a rozumnost přítelkyní jmenuj,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 5, 'Aby tě ostříhala od ženy cizí, od postranní, jenž řečmi svými lahodí.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 6, 'Nebo z okna domu svého okénkem vyhlédaje,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 7, 'Viděl jsem mezi hloupými, spatřil jsem mezi mládeží mládence bláznivého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 8, 'Kterýž šel po ulici vedlé úhlu jejího, a cestou k domu jejímu kráčel,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 9, 'V soumrak, u večer dne, ve tmách nočních a v mrákotě.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 10, 'A aj, žena potkala ho v ozdobě nevěstčí a chytrého srdce,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 11, 'Štěbetná a opovážlivá, v domě jejím nezůstávají nohy její,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 12, 'Jednak vně, jednak na ulici u každého úhlu úklady činící.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 13, 'I chopila jej, a políbila ho, a opovrhši stud, řekla jemu:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 14, 'Oběti pokojné jsou u mne, dnes splnila jsem slib svůj.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 15, 'Protož vyšla jsem vstříc tobě, abych pilně hledala tváři tvé, i nalezla jsem tě.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 16, 'Koberci jsem obestřela lůže své, s řezbami a prostěradly Egyptskými,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 17, 'Vykadila jsem pokojík svůj mirrou a aloe a skořicí.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 18, 'Poď, opojujme se milostí až do jitra, obveselíme se v milosti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 19, 'Nebo není muže doma, odšel na cestu dalekou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 20, 'Pytlík peněz vzal s sebou, v jistý den vrátí se do domu svého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 21, 'I naklonila ho mnohými řečmi svými, a lahodností rtů svých přinutila jej.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 22, 'Šel za ní hned, jako vůl k zabití chodívá, a jako blázen v pouta, jimiž by trestán byl.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 23, 'Dokudž nepronikla střela jater jeho, pospíchal jako pták k osídlu, nevěda, že ono bezživotí jeho jest.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 24, 'Protož nyní, synové, slyšte mne, a pozorujte řečí úst mých.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 25, 'Neuchyluj se k cestám jejím srdce tvé, aniž se toulej po stezkách jejích.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 26, 'Nebo mnohé zranivši, porazila, a silní všickni zmordováni jsou od ní.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 27, 'Cesty pekelné dům její, vedoucí do skrýší smrti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 1, 'Zdaliž moudrost nevolá, a rozumnost nevydává hlasu svého?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 2, 'Na vrchu vysokých míst, u cesty, na rozcestí stojí,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 3, 'U bran, kudy se chodí do města, a kudy se chodí dveřmi, volá, řkuci:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 4, 'Na vásť, ó muži, volám, a hlas můj jest k synům lidským.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 5, 'Poučte se hloupí opatrnosti, a blázni srozumějte srdcem.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 6, 'Poslouchejtež, nebo znamenité věci mluviti budu, a otevření rtů mých pouhou pravdu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 7, 'Jistě žeť pravdu zvěstují ústa má, a ohavností jest rtům mým bezbožnost.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 8, 'Spravedlivé jsou všecky řeči úst mých, není v nich nic křivého ani převráceného.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 9, 'Všecky pravé jsou rozumějícímu, a přímé těm, kteříž nalézají umění.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 10, 'Přijmětež cvičení mé raději než stříbro, a umění raději než zlato nejvýbornější.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 11, 'Nebo lepší jest moudrost než drahé kamení, tak že jakékoli věci žádostivé vrovnati se jí nemohou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 12, 'Já moudrost bydlím s opatrností, a umění pravé prozřetelnosti přítomné mám.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 13, 'Bázeň Hospodinova jest v nenávisti míti zlé, pýchy a vysokomyslnosti, i cesty zlé a úst převrácených nenávidím.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 14, 'Má jest rada i šťastný prospěch, jáť jsem rozumnost, a má jest síla.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 15, 'Skrze mne králové kralují, a knížata ustanovují věci spravedlivé.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 16, 'Skrze mne knížata panují, páni i všickni soudcové zemští.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 17, 'Já milující mne miluji, a kteříž mne pilně hledají, nalézají mne.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 18, 'Bohatství a sláva při mně jest, zboží trvánlivé i spravedlnost.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 19, 'Lepší jest ovoce mé než nejlepší zlato, i než ryzí, a užitek můj než stříbro výborné.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 20, 'Stezkou spravedlnosti vodím, prostředkem stezek soudu,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 21, 'Abych těm, kteříž mne milují, přidědila zboží věčné, a poklady jejich naplnila.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 22, 'Hospodin měl mne při počátku cesty své, před skutky svými, přede všemi časy.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 23, 'Před věky ustanovena jsem, před počátkem, prvé než byla země.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 24, 'Když ještě nebylo propasti, zplozena jsem, když ještě nebylo studnic oplývajících vodami.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 25, 'Prvé než hory založeny byly, než byli pahrbkové, zplozena jsem;');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 26, 'Ještě byl neučinil země a rovin, ani začátku prachu okršlku zemského.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 27, 'Když připravoval nebesa, byla jsem tu, když vyměřoval okrouhlost nad propastí;');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 28, 'Když upevňoval oblaky u výsosti, když utvrzoval studnice propasti;');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 29, 'Když ukládal moři cíl jeho, a vodám, aby nepřestupovaly rozkázaní jeho, když vyměřoval základy země:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 30, 'Tehdáž byla jsem od něho pěstována, a byla jsem jeho potěšení na každý den, anobrž hrám před ním každého času;');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 31, 'Hrám i na okršlku země jeho, a rozkoše mé s syny lidskými.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 32, 'A tak tedy, synové, poslechněte mne, nebo blahoslavení jsou ostříhající cest mých.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 33, 'Poslouchejte cvičení, a nabuďte rozumu, a nerozpakujte se.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 34, 'Blahoslavený člověk, kterýž mne slýchá, bdě u dveří mých na každý den, šetře veřejí dveří mých.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 35, 'Nebo kdož mne nalézá, nalézá život, a dosahuje lásky od Hospodina.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 36, 'Ale kdož hřeší proti mně, ukrutenství provodí nad duší svou; všickni, kteříž mne nenávidí, milují smrt.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 1, 'Moudrost vystavěla dům svůj, vytesavši sloupů svých sedm.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 2, 'Zbila dobytek svůj, smísila víno své, stůl také svůj připravila.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 3, 'A poslavši děvečky své, volá na vrchu nejvyšších míst v městě:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 4, 'Kdožkoli jest hloupý, uchyl se sem. Až i bláznivým říká:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 5, 'Poďte, jezte chléb můj, a píte víno, kteréž jsem smísila.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 6, 'Opusťte hloupost a živi buďte, a choďte cestou rozumnosti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 7, 'Kdo tresce posměvače, dochází hanby, a kdo přimlouvá bezbožnému, pohanění.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 8, 'Nedomlouvej posměvači, aby tě nevzal v nenávist; přimlouvej moudrému, a bude tě milovati.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 9, 'Učiň to moudrému, a bude moudřejší; pouč spravedlivého, a bude umělejší.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 10, 'Počátek moudrosti jest bázeň Hospodinova, a umění svatých rozumnost.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 11, 'Nebo skrze mne rozmnoží se dnové tvoji, a přidánoť bude let života.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 12, 'Budeš-li moudrý, sobě moudrý budeš; pakli posměvač, sám vytrpíš.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 13, 'Žena bláznivá štěbetná, nesmyslná, a nic neumí.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 14, 'A sedí u dveří domu svého na stolici, na místech vysokých v městě,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 15, 'Aby volala jdoucích cestou, kteříž přímo jdou stezkami svými, řkuci:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 16, 'Kdo jest hloupý, uchyl se sem. A bláznivému říká:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 17, 'Voda kradená sladší jest, a chléb pokoutní chutnější.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 18, 'Ale neví hlupec, že mrtví jsou tam, a v hlubokém hrobě ti, kterýchž pozvala.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 1, 'Syn moudrý obveseluje otce, ale syn bláznivý zámutkem jest matce své.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 2, 'Neprospívají pokladové bezbožně nabytí, ale spravedlnost vytrhuje od smrti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 3, 'Nedopustí lačněti Hospodin duši spravedlivého, statek pak bezbožných rozptýlí.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 4, 'K nouzi přivodí ruka lstivá, ruka pak pracovitých zbohacuje.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 5, 'Kdo shromažďuje v létě, jest syn rozumný; kdož vyspává ve žni, jest syn, kterýž hanbu činí.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 6, 'Požehnání jest nad hlavou spravedlivého, ale ústa bezbožných přikrývají ukrutnost.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 7, 'Památka spravedlivého požehnaná, ale jméno bezbožných smrdí.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 8, 'Moudré srdce přijímá přikázaní, ale blázen od rtů svých padne.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 9, 'Kdo chodí upřímě, chodí doufanlivě; kdož pak převrací cesty své, vyjeven bude.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 10, 'Kdo mhourá okem, uvodí nesnáz; a kdož jest bláznivých rtů, padne.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 11, 'Pramen života jsou ústa spravedlivého, ale ústa bezbožných přikrývají ukrutnost.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 12, 'Nenávist vzbuzuje sváry, ale láska přikrývá všecka přestoupení.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 13, 'Ve rtech rozumného nalézá se moudrost, ale kyj na hřbetě blázna.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 14, 'Moudří skrývají umění, úst pak blázna blízké jest setření.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 15, 'Zboží bohatého jest město pevné jeho, ale nouze jest chudých setření.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 16, 'Práce spravedlivého jest k životu, nábytek pak bezbožných jest k hříchu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 17, 'Stezkou života jde, kdož přijímá trestání; ale kdož pohrdá domlouváním, bloudí.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 18, 'Kdož přikrývá nenávist rty lživými, i kdož uvodí v lehkost, ten blázen jest.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 19, 'Mnohé mluvení nebývá bez hříchu, kdož pak zdržuje rty své, opatrný jest.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 20, 'Stříbro výborné jest jazyk spravedlivého, ale srdce bezbožných za nic nestojí.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 21, 'Rtové spravedlivého pasou mnohé, blázni pak pro bláznovství umírají.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 22, 'Požehnání Hospodinovo zbohacuje, a to beze všeho trápení.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 23, 'Za žert jest bláznu činiti nešlechetnost, ale muž rozumný moudrosti se drží.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 24, 'Čeho se bojí bezbožný, to přichází na něj; ale čehož žádají spravedliví, dává Bůh.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 25, 'Jakož pomíjí vichřice, tak nestane bezbožníka, spravedlivý pak jest základ stálý.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 26, 'Jako ocet zubům, a jako dým očima, tak jest lenivý těm, kteříž jej posílají.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 27, 'Bázeň Hospodinova přidává dnů, léta pak bezbožných ukrácena bývají.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 28, 'Očekávání spravedlivých jest potěšení, naděje pak bezbožných zahyne.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 29, 'Silou jest upřímému cesta Hospodinova, a strachem těm, kteříž činí nepravost.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 30, 'Spravedlivý na věky se nepohne, bezbožní pak nebudou bydliti v zemi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 31, 'Ústa spravedlivého vynášejí moudrost, ale jazyk převrácený vyťat bude.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 32, 'Rtové spravedlivého znají, což jest Bohu libého, ústa pak bezbožných převrácené věci.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 1, 'Váha falešná ohavností jest Hospodinu, ale závaží pravé líbí se jemu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 2, 'Za pýchou přichází zahanbení, ale při pokorných jest moudrost.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 3, 'Sprostnost upřímých vodí je, převrácenost pak přestupníků zatracuje je.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 4, 'Neprospíváť bohatství v den hněvu, ale spravedlnost vytrhuje z smrti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 5, 'Spravedlnost upřímého spravuje cestu jeho, ale pro bezbožnost svou padá bezbožný.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 6, 'Spravedlnost upřímých vytrhuje je, ale přestupníci v zlosti zjímáni bývají.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 7, 'Když umírá člověk bezbožný, hyne naděje, i očekávání rekovských činů mizí.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 8, 'Spravedlivý z úzkosti bývá vysvobozen, bezbožný pak přichází na místo jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 9, 'Pokrytec ústy kazí bližního svého, ale spravedliví uměním vytrženi bývají.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 10, 'Z štěstí spravedlivých veselí se město, když pak hynou bezbožní, bývá prozpěvování.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 11, 'Požehnáním spravedlivých zvýšeno bývá město, ústy pak bezbožných vyvráceno.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 12, 'Pohrdá bližním svým blázen, ale muž rozumný mlčí.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 13, 'Utrhač toulaje se, pronáší tajnost, věrný pak člověk tají věc.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 14, 'Kdež není dostatečné rady, padá lid, ale spomožení jest ve množství rádců.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 15, 'Velmi sobě škodí, kdož slibuje za cizího, ješto ten, kdož nenávidí rukojemství, bezpečen jest.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 16, 'Žena šlechetná má čest, a ukrutní mají zboží.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 17, 'Člověk účinný dobře činí životu svému, ale ukrutný kormoutí tělo své.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 18, 'Bezbožný dělá dílo falešné, ale kdož rozsívá spravedlnost, má mzdu jistou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 19, 'Tak spravedlivý rozsívá k životu, a kdož následuje zlého, k smrti své.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 20, 'Ohavností jsou Hospodinu převrácení srdcem, ale ctného obcování líbí se jemu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 21, 'Zlý, by sobě i na pomoc přivzal, neujde pomsty, símě pak spravedlivých uchází toho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 22, 'Zápona zlatá na pysku svině jest žena pěkná bez rozumu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 23, 'Žádost spravedlivých jest toliko dobrých věcí, ale očekávání bezbožných hněv.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 24, 'Mnohý rozdává štědře, a však přibývá mu více; jiný skoupě drží nad slušnost, ale k chudobě.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 25, 'Člověk štědrý bývá bohatší, a kdož svlažuje, také sám bude zavlažen.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 26, 'Kdo zadržuje obilí, zlořečí mu lid; ale požehnání na hlavě toho, kdož je prodává.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 27, 'Kdo pilně hledá dobrého, nalézá přízeň; kdož pak hledá zlého, potká jej.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 28, 'Kdo doufá v bohatství své, ten spadne, ale spravedliví jako ratolest zkvetnou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 29, 'Kdo kormoutí dům svůj, za dědictví bude míti vítr, a blázen sloužiti musí moudrému.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 30, 'Ovoce spravedlivého jest strom života, a kdož vyučuje duše, jest moudrý.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 31, 'Aj, spravedlivému na zemi odplacováno bývá, čím více bezbožnému a hříšníku?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 1, 'Kdo miluje cvičení, miluje umění; kdož pak nenávidí domlouvání, nemoudrý jest.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 2, 'Dobrý nalézá lásku u Hospodina, ale muže nešlechetného potupí Bůh.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 3, 'Nebývá trvánlivý člověk v bezbožnosti, kořen pak spravedlivých nepohne se.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 4, 'Žena statečná jest koruna muže svého, ale jako hnis v kostech jeho ta, kteráž k hanbě přivodí.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 5, 'Myšlení spravedlivých jsou pravá, rady pak bezbožných lstivé.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 6, 'Slova bezbožných úklady činí krvi, ústa pak spravedlivých vytrhují je.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 7, 'Vyvráceni bývají bezbožní tak, aby jich nebylo, ale dům spravedlivých ostojí.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 8, 'Podlé toho, jakž rozumný jest, chválen bývá muž, převráceného pak srdce bude v pohrdání.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 9, 'Lepší jest nevzácný, kterýž má služebníka, nežli ten, kterýž sobě slavně počíná, a nemá chleba.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 10, 'Pečuje spravedlivý o život hovádka svého, srdce pak bezbožných ukrutné jest.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 11, 'Kdo dělá zemi svou, nasycen bývá chlebem; ale kdož následuje zahalečů, blázen jest.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 12, 'Žádostiv jest bezbožný obrany proti zlému, ale kořen spravedlivých způsobuje ji.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 13, 'Do přestoupení rtů zapletá se zlostník, ale spravedlivý vychází z ssoužení.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 14, 'Z ovoce úst každý nasycen bude dobrým, a odplatu za skutky člověka dá jemu Bůh.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 15, 'Cesta blázna přímá se zdá jemu, ale kdo poslouchá rady, moudrý jest.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 16, 'Hněv blázna v tentýž den poznán bývá, ale opatrný hanbu skrývá.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 17, 'Kdož mluví pravdu, ohlašuje spravedlnost, svědek pak falešný lest.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 18, 'Někdo vynáší řeči podobné meči probodujícímu, ale jazyk moudrých jest lékařství.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 19, 'Rtové pravdomluvní utvrzeni budou na věky, ale na kratičko jazyk lživý.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 20, 'V srdci těch, kteříž zlé obmýšlejí, bývá lest, v těch pak, kteříž radí ku pokoji, veselí.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 21, 'Nepotká spravedlivého žádná těžkost, bezbožní pak naplněni budou zlým.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 22, 'Ohavností jsou Hospodinu rtové lživí, ale ti, jenž činí pravdu, líbí se jemu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 23, 'Člověk opatrný tají umění, ale srdce bláznů vyvolává bláznovství.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 24, 'Ruka pracovitých panovati bude, lstivá pak musí dávati plat.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 25, 'Starost v srdci člověka snižuje ji, ale věc dobrá obveseluje ji.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 26, 'Vzácnější jest nad bližního svého spravedlivý, cesta pak bezbožných svodí je.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 27, 'Nebude péci fortelný, což ulovil, ale člověk bedlivý statku drahého nabude.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 28, 'Na stezce spravedlnosti jest život, a cesta stezky její nesmrtelná jest.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 1, 'Syn moudrý přijímá cvičení otcovo, ale posměvač neposlouchá domlouvání.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 2, 'Z ovoce úst každý jísti bude dobré, ale duše převrácených nátisky.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 3, 'Kdo ostříhá úst svých, ostříhá duše své; kdo rozdírá rty své, setření na něj přijde.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 4, 'Žádá, a nic nemá duše lenivého, duše pak pracovitých zbohatne.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 5, 'Slova lživého nenávidí spravedlivý, bezbožníka pak v ošklivost uvodí a zahanbuje.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 6, 'Spravedlnost ostříhá přímě chodícího po cestě, bezbožnost pak vyvrací hříšníka.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 7, 'Někdo bohatým se dělaje, nemá nic: zase někdo dělaje se chudým, má však statku mnoho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 8, 'Výplata života člověku jest bohatství jeho, ale chudý neslyší domlouvání.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 9, 'Světlo spravedlivých rozsvětluje se, svíce pak bezbožných zhasne.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 10, 'Samou toliko pýchou působí člověk svár, ale při těch, jenž užívají rady, jest moudrost.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 11, 'Statek zle dobytý umenšovati se bude, kdož pak shromažďuje rukou, přivětší ho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 12, 'Očekávání dlouhé zemdlívá srdce, ale žádost splněná jest strom života.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 13, 'Kdož pohrdá slovem Božím, sám sobě škodí; ale kdož se bojí přikázaní, odplaceno mu bude.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 14, 'Naučení moudrého jest pramen života, k vyhýbání se osídlům smrti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 15, 'Rozum dobrý dává milost, cesta pak převrácených jest tvrdá.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 16, 'Každý důmyslný dělá uměle, ale blázen rozprostírá bláznovství.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 17, 'Posel bezbožný upadá v neštěstí, jednatel pak věrný jest lékařství.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 18, 'Chudoba a lehkost potká toho, jenž se vytahuje z kázně; ale kdož ostříhá naučení, zveleben bude.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 19, 'Žádost naplněná sladká jest duši, ale ohavnost jest bláznům odstoupiti od zlého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 20, 'Kdo chodí s moudrými, bude moudrý; ale kdo tovaryší s blázny, setřín bude.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 21, 'Hříšníky stihá neštěstí, ale spravedlivým odplatí Bůh dobrým.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 22, 'Dobrý zanechává dědictví vnukům, ale zboží hříšného zachováno bývá spravedlivému.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 23, 'Hojnost jest pokrmů na rolí chudých, někdo pak hyne skrze nerozšafnost.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 24, 'Kdo zdržuje metlu svou, nenávidí syna svého; ale kdož ho miluje, za času jej tresce.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 25, 'Spravedlivý jí až do nasycení duše své, břicho pak bezbožných nedostatek trpí.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 1, 'Moudrá žena vzdělává dům svůj, bláznice pak rukama svýma boří jej.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 2, 'Kdo chodí v upřímnosti své, bojí se Hospodina, ale převrácený v cestách svých pohrdá jím.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 3, 'V ústech blázna jest hůl pýchy, rtové pak moudrých ostříhají jich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 4, 'Když není volů, prázdné jsou jesle, ale hojná úroda jest v síle volů.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 5, 'Svědek věrný neklamá, ale svědek falešný mluví lež.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 6, 'Hledá posměvač moudrosti, a nenalézá, rozumnému pak umění snadné jest.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 7, 'Odejdi od muže bláznivého, když neseznáš při něm rtů umění.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 8, 'Moudrost opatrného jest, aby rozuměl cestě své, bláznovství pak bláznů ke lsti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 9, 'Blázen přikrývá hřích, ale mezi upřímými dobrá vůle.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 10, 'Srdce ví o hořkosti duše své, a k veselí jeho nepřimísí se cizí.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 11, 'Dům bezbožných vyhlazen bude, ale stánek upřímých zkvetne.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 12, 'Cesta zdá se přímá člověku, a však dokonání její jest cesta k smrti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 13, 'Také i v smíchu bolí srdce, a cíl veselí jest zámutek.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 14, 'Cestami svými nasytí se převrácený srdcem, ale muž dobrý štítí se jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 15, 'Hloupý věří každému slovu, ale opatrný šetří kroku svého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 16, 'Moudrý bojí se a odstupuje od zlého, ale blázen dotře a smělý jest.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 17, 'Náhlý se dopouští bláznovství, a muž myšlení zlých v nenávisti bývá.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 18, 'Dědičně vládnou hlupci bláznovstvím, ale opatrní bývají korunováni uměním.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 19, 'Sklánějí se zlí před dobrými, a bezbožní u bran spravedlivého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 20, 'Také i příteli svému v nenávisti bývá chudý, ale milovníci bohatého mnozí jsou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 21, 'Pohrdá bližním svým hříšník, ale kdož se slitovává nad chudými, blahoslavený jest.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 22, 'Zajisté žeť bloudí, kteříž ukládají zlé; ale milosrdenství a pravda těm, kteříž smýšlejí dobré.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 23, 'Všeliké práce bývá zisk, ale slovo rtů jest jen k nouzi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 24, 'Koruna moudrých jest bohatství jejich, bláznovství pak bláznivých bláznovstvím.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 25, 'Vysvobozuje duše svědek pravdomluvný, ale lstivý mluví lež.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 26, 'V bázni Hospodinově jestiť doufání silné, kterýž synům svým útočištěm bude.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 27, 'Bázeň Hospodinova jest pramen života, k vyhýbání se osídlům smrti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 28, 'Ve množství lidu jest sláva krále, ale v nedostatku lidu zahynutí vůdce.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 29, 'Zpozdilý k hněvu hojně má rozumu, ale náhlý pronáší bláznovství.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 30, 'Život těla jest srdce zdravé, ale hnis v kostech jest závist.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 31, 'Kdo utiská chudého, útržku činí Učiniteli jeho; ale ctí jej, kdož se slitovává nad chudým.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 32, 'Pro zlost svou odstrčen bývá bezbožný, ale naději má i při smrti své spravedlivý.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 33, 'V srdci rozumného odpočívá moudrost, co pak jest u vnitřnosti bláznů, nezatají se.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 34, 'Spravedlnost zvyšuje národ, ale hřích jest ku pohanění národům.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 35, 'Laskav bývá král na služebníka rozumného, ale hněviv na toho, kterýž hanbu činí.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 1, 'Odpověd měkká odvracuje hněv, ale řeč zpurná vzbuzuje prchlivost.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 2, 'Jazyk moudrých ozdobuje umění, ale ústa bláznů vylévají bláznovství.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 3, 'Na všelikém místě oči Hospodinovy spatřují zlé i dobré.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 4, 'Zdravý jazyk jest strom života, převrácenost pak z něho ztroskotání od větru.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 5, 'Blázen pohrdá cvičením otce svého, ale kdož ostříhá naučení, opatrnosti nabude.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 6, 'V domě spravedlivého jest hojnost veliká, ale v úrodě bezbožného zmatek.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 7, 'Rtové moudrých rozsívají umění, srdce pak bláznů ne tak.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 8, 'Obět bezbožných ohavností jest Hospodinu, ale modlitba upřímých líbí se jemu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 9, 'Ohavností jest Hospodinu cesta bezbožného, toho pak, kdož následuje spravedlnosti, miluje.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 10, 'Trestání přísné opouštějícímu cestu, a kdož nenávidí domlouvání, umře.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 11, 'Peklo i zatracení jest před Hospodinem, čím více srdce synů lidských?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 12, 'Nemiluje posměvač toho, kterýž ho tresce, aniž k moudrým přistoupí.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 13, 'Srdce veselé obveseluje tvář, ale pro žalost srdce duch zkormoucen bývá.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 14, 'Srdce rozumného hledá umění, ale ústa bláznů pasou se bláznovstvím.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 15, 'Všickni dnové chudého zlí jsou, ale dobromyslného hody ustavičné.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 16, 'Lepší jest maličko s bázní Hospodinovou než poklad veliký s nepokojem.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 17, 'Lepší jest krmě z zelí, kdež jest láska, nežli z krmného vola, kdež jest nenávist.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 18, 'Muž hněvivý vzbuzuje sváry, ale zpozdilý k hněvu upokojuje svadu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 19, 'Cesta lenivého jest jako plot z trní, ale stezka upřímých jest vydlážená.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 20, 'Syn moudrý obveseluje otce, bláznivý pak člověk pohrdá matkou svou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 21, 'Bláznovství jest veselím bláznu, ale člověk rozumný upřímo kráčeti směřuje.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 22, 'Kdež není rady, zmařena bývají usilování, ale množství rádců ostojí.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 23, 'Vesel bývá člověk z odpovědi úst svých; nebo slovo v čas příhodný ó jak jest dobré!');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 24, 'Cesta života vysoko jest rozumnému proto, aby se uchýlil od pekla dole.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 25, 'Dům pyšných vyvrací Hospodin, meze pak vdovy upevňuje.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 26, 'Ohavností jsou Hospodinu myšlení zlého, ale čistých řeči vzácné.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 27, 'Kdož dychtí po lakomství, kormoutí dům svůj; ale kdož nenávidí darů, živ bude.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 28, 'Srdce spravedlivého přemyšluje, co má mluviti, ale ústa bezbožných vylévají všelijakou zlost.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 29, 'Vzdálen jest Hospodin od bezbožných, ale modlitbu spravedlivých vyslýchá.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 30, 'To, což se zraku naskýtá, obveseluje srdce; pověst dobrá tukem naplňuje kosti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 31, 'Ucho, kteréž poslouchá trestání života, u prostřed moudrých bydliti bude.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 32, 'Kdo se vyhýbá cvičení, zanedbává duše své; ale kdož přijímá domlouvání, má rozum.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 33, 'Bázeň Hospodinova jest cvičení se moudrosti, a slávu předchází ponížení.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 1, 'Při člověku bývá spořádání myšlení, ale od Hospodina jest řeč jazyka.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 2, 'Všecky cesty člověka čisté se jemu zdají, ale kterýž zpytuje duchy, Hospodin jest.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 3, 'Uval na Hospodina činy své, a budou upevněna předsevzetí tvá.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 4, 'Hospodin všecko učinil pro sebe samého, také i bezbožného ke dni zlému.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 5, 'Ohavností jest Hospodinu každý pyšného srdce; by sobě na pomoc i jiné přivzal, neujde pomsty.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 6, 'Milosrdenstvím a pravdou očištěna bývá nepravost, a v bázni Hospodinově uchází se zlého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 7, 'Když se líbí Hospodinu cesty člověka, také i nepřátely jeho spokojuje k němu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 8, 'Lepší jest maličko s spravedlností, než množství důchodů nespravedlivých.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 9, 'Srdce člověka přemýšlí o cestě své, ale Hospodin spravuje kroky jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 10, 'Rozhodnutí jest ve rtech královských, v soudu neuchylují se ústa jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 11, 'Váha a závaží jsou úsudek Hospodinův, a všecka závaží v pytlíku jeho nařízení.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 12, 'Ohavností jest králům činiti bezbožně; nebo spravedlností upevňován bývá trůn.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 13, 'Rtové spravedliví líbezní jsou králům, a ty, kteříž upřímě mluví, milují.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 14, 'Rozhněvání královo jistý posel smrti, ale muž moudrý ukrotí je.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 15, 'V jasné tváři královské jest život, a přívětivost jeho jako oblak s deštěm jarním.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 16, 'Mnohem lépe jest nabyti moudrosti než zlata nejčistšího, a nabyti rozumnosti lépe než stříbra.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 17, 'Cesta upřímých jest odstoupiti od zlého; ostříhá duše své ten, kdož ostříhá cesty své.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 18, 'Před setřením bývá pýcha, a před pádem pozdvižení ducha.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 19, 'Lépe jest poníženého duchu býti s pokornými, než děliti kořist s pyšnými.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 20, 'Ten, kdož pozoruje slova, nalézá dobré; a kdož doufá v Hospodina, blahoslavený jest.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 21, 'Ten, kdož jest moudrého srdce, slove rozumný, a sladkost rtů přidává naučení.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 22, 'Rozumnost těm, kdož ji mají, jest pramen života, ale umění bláznů jest bláznovství.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 23, 'Srdce moudrého rozumně spravuje ústa svá, tak že rty svými přidává naučení.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 24, 'Plást medu jsou řeči utěšené, sladkost duši, a lékařství kostem.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 25, 'Cesta zdá se přímá člověku, ale dokonání její jistá cesta smrti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 26, 'Člověk pracovitý pracuje sobě, nebo ponoukají ho ústa jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 27, 'Muž nešlechetný vykopává zlé, v jehožto rtech jako oheň spalující.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 28, 'Muž převrácený rozsívá sváry, a klevetník rozlučuje přátely.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 29, 'Muž ukrutný přeluzuje bližního svého, a uvodí jej na cestu nedobrou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 30, 'Zamhuřuje oči své, smýšleje věci převrácené, a zmítaje pysky svými, vykonává zlé.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 31, 'Koruna ozdobná jsou šediny na cestě spravedlnosti se nalézající.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 32, 'Lepší jest zpozdilý k hněvu než silný rek, a kdož panuje nad myslí svou nežli ten, kterýž dobyl města.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 33, 'Do klínu umítán bývá los, ale od Hospodina všecko řízení jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 1, 'Lepší jest kus chleba suchého s pokojem, nežli dům plný nabitých hovad s svárem.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 2, 'Služebník rozumný panovati bude nad synem, kterýž jest k hanbě, a mezi bratřími děliti bude dědictví.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 3, 'Teglík stříbra a pec zlata zkušuje, ale srdcí Hospodin.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 4, 'Zlý člověk pozoruje řečí nepravých, a lhář poslouchá jazyka převráceného.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 5, 'Kdo se posmívá chudému, útržku činí Učiniteli jeho; a kdo se z bídy raduje, nebude bez pomsty.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 6, 'Koruna starců jsou vnukové, a ozdoba synů otcové jejich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 7, 'Nesluší na blázna řeči znamenité, ovšem na kníže řeč lživá.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 8, 'Jako kámen drahý, tak bývá vzácný dar před očima toho, kdož jej béře; k čemukoli směřuje, daří se jemu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 9, 'Kdo přikrývá přestoupení, hledá lásky; ale kdo obnovuje věc, rozlučuje přátely.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 10, 'Více se chápá rozumného jedno domluvení, nežli by blázna stokrát ubil.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 11, 'Zpurný toliko zlého hledá, pročež přísný posel na něj poslán bývá.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 12, 'Lépe člověku potkati se s nedvědicí osiřalou, nežli s bláznem v bláznovství jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 13, 'Kdo odplacuje zlým za dobré, neodejdeť zlé z domu jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 14, 'Začátek svady jest, jako když kdo protrhuje vodu; protož prvé než by se zsilil svár, přestaň.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 15, 'Kdož ospravedlňuje nepravého, i kdož odsuzuje spravedlivého, ohavností jsou Hospodinu oba jednostejně.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 16, 'K čemu jest zboží v ruce blázna, když k nabytí moudrosti rozumu nemá?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 17, 'Všelikého času miluje, kdož jest přítelem, a bratr v ssoužení ukáže se.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 18, 'Člověk bláznivý ruku dávaje, činí slib před přítelem svým.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 19, 'Kdož miluje svadu, miluje hřích; a kdo vyvyšuje ústa svá, hledá potření.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 20, 'Převrácené srdce nenalézá toho, což jest dobrého; a kdož má vrtký jazyk, upadá v těžkost.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 21, 'Kdo zplodil blázna, k zámutku svému zplodil jej, aniž se bude radovati otec nemoudrého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 22, 'Srdce veselé očerstvuje jako lékařství, ale duch zkormoucený vysušuje kosti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 23, 'Bezbožný tajně béře dar, aby převrátil stezky soudu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 24, 'Na oblíčeji rozumného vidí se moudrost, ale oči blázna těkají až na konec země.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 25, 'K žalosti jest otci svému syn blázen, a k hořkosti rodičce své.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 26, 'Jistě že pokutovati spravedlivého není dobré, tolikéž, aby knížata bíti měli pro upřímost.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 27, 'Zdržuje řeči své muž umělý; drahého ducha jest muž rozumný.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 28, 'Také i blázen, mlče, za moudrého jmín bývá, a zacpávaje rty své, za rozumného.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 1, 'Svémyslný hledá toho, což se jemu líbí, a ve všelijakou věc plete se.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 2, 'Nezalibuje sobě blázen v rozumnosti, ale v tom, což zjevuje srdce jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 3, 'Když přijde bezbožný, přichází také pohrdání, a s lehkomyslným útržka.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 4, 'Slova úst muže vody hluboké, potok rozvodnilý pramen moudrosti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 5, 'Přijímati osobu bezbožného není dobré, abys převrátil spravedlivého v soudu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 6, 'Rtové blázna směřují k svadě, a ústa jeho bití se domluví.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 7, 'Ústa blázna k setření jemu, a rtové jeho osídlem duši jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 8, 'Slova utrhače jsou jako ubitých, ale však sstupují do vnitřností života.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 9, 'Také ten, kdož jest nedbalý v práci své, bratr jest mrhače.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 10, 'Věže pevná jest jméno Hospodinovo; k němu se uteče spravedlivý, a bude povýšen.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 11, 'Zboží bohatého jest město pevné jeho, a jako zed vysoká v mysli jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 12, 'Před setřením vyvyšuje se srdce člověka, ale před povýšením bývá ponížení.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 13, 'Kdož odpovídá něco, prvé než vyslyší, počítá se to za bláznovství jemu a za lehkost.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 14, 'Duch muže snáší nemoc svou, ducha pak zkormouceného kdo snese?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 15, 'Srdce rozumného dosahuje umění, a ucho moudrých hledá umění.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 16, 'Dar člověka uprostranňuje jemu, a před oblíčej mocných přivodí jej.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 17, 'Spravedlivý zdá se ten, kdož jest první v své při, ale když přichází bližní jeho, tedy stihá jej.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 18, 'Los pokojí svady, a mezi silnými rozeznává.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 19, 'Bratr křivdou uražený tvrdší jest než město nedobyté, a svárové jsou jako závora u hradu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 20, 'Ovocem úst jednoho každého nasyceno bývá břicho jeho, úrodou rtů svých nasycen bude.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 21, 'Smrt i život jest v moci jazyka, a ten, kdož jej miluje, bude jísti ovoce jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 22, 'Kdo nalezl manželku, nalezl věc dobrou, a navážil lásky od Hospodina.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 23, 'Poníženě mluví chudý, ale bohatý odpovídá tvrdě.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 24, 'Ten, kdož má přátely, má se míti přátelsky, poněvadž přítel bývá vlastnější než bratr.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 1, 'Lepší jest chudý, jenž chodí v upřímnosti své, nežli převrácený ve rtech svých, kterýž jest blázen.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 2, 'Jistě že bez umění duši není dobře, a kdož jest kvapných noh, hřeší.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 3, 'Bláznovství člověka převrací cestu jeho, ačkoli proti Hospodinu zpouzí se srdce jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 4, 'Statek přidává přátel množství, ale chudý od přítele svého odloučen bývá.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 5, 'Svědek falešný nebude bez pomsty, a kdož mluví lež, neuteče.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 6, 'Mnozí pokoří se před knížetem, a každý jest přítel muži štědrému.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 7, 'Všickni bratří chudého v nenávisti jej mají; čím více přátelé jeho vzdalují se od něho! Když volá za nimi, není jich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 8, 'Ten, kdož miluje duši svou, nabývá moudrosti, a ostříhá opatrnosti, aby nalezl dobré.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 9, 'Svědek falešný nebude bez pomsty, a kdož mluví lež, zahyne.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 10, 'Nesluší na blázna rozkoš, a ovšem, aby služebník nad knížaty panoval.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 11, 'Rozum člověka zdržuje hněv jeho, a čest jeho jest prominouti provinění.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 12, 'Prchlivost královská jako řvání mladého lva jest, a ochotnost jeho jako rosa na bylinu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 13, 'Trápení otci svému jest syn bláznivý, a ustavičné kapání žena svárlivá.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 14, 'Dům a statek jest po rodičích, ale od Hospodina manželka rozumná.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 15, 'Lenost přivodí tvrdý sen, a duše váhavá lačněti bude.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 16, 'Ten, kdož ostříhá přikázaní, ostříhá duše své; ale kdož pohrdá cestami svými, zahyne.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 17, 'Kdo uděluje chudému, půjčuje Hospodinu, a onť za dobrodiní jeho odplatí jemu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 18, 'Tresci syna svého, dokudž jest o něm naděje, a k zahynutí jeho neodpouštěj jemu duše tvá.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 19, 'Veliký hněv ukazuj, odpouštěje trestání, proto že poněvadž odpouštíš, potom více trestati budeš.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 20, 'Poslouchej rady, a přijímej kázeň, abys vždy někdy moudrý byl.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 21, 'Mnozí úmyslové jsou v srdci člověka, ale uložení Hospodinovo toť ostojí.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 22, 'Žádaná věc člověku jest dobře činiti jiným, ale počestnější jest chudý než muž lživý.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 23, 'Bázeň Hospodinova k životu. Takový jsa nasycen, bydlí, aniž neštěstím navštíven bývá.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 24, 'Lenivý schovává ruku svou za ňadra, ani k ústům svým jí nevztáhne.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 25, 'Ubí posměvače, ať se hlupec dovtípí; a potresci rozumného, ať porozumí umění.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 26, 'Syn, kterýž hanbu a lehkost činí, hubí otce, a zahání matku.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 27, 'Přestaň, synu můj, poslouchati učení, kteréž od řečí rozumných odvozuje.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 28, 'Svědek nešlechetný posmívá se soudu, a ústa bezbožných přikrývají nepravost.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 29, 'Nebo na posměvače hotoví jsou nálezové, a rány na hřbet bláznů.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 1, 'Víno činí posměvače, a nápoj opojný nepokojného; pročež každý, kdož se kochá v něm, nebývá moudrý.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 2, 'Hrůza královská jako řvání mladého lva; kdož ho rozhněvá, hřeší proti životu svému.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 3, 'Přestati od sváru jest to každému ku poctivosti, ale kdožkoli se do nich zapletá, blázen jest.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 4, 'Lenoch neoře pro zimu, pročež žebrati bude ve žni, ale nadarmo.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 5, 'Rada v srdci muže voda hluboká, muž však rozumný dosáhne jí.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 6, 'Větší díl lidí honosí se účinností svou, ale v pravdě takového kdo nalezne?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 7, 'Spravedlivý ustavičně chodí v upřímnosti své; blažení synové jeho po něm.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 8, 'Král sedě na soudné stolici, rozhání očima svýma všecko zlé.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 9, 'Kdo může říci: Očistil jsem srdce své? Čist jsem od hříchu svého?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 10, 'Závaží rozdílná a míra rozdílná, obé to ohavností jest Hospodinu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 11, 'Po skutcích svých poznáno bývá také i pachole, jest-li upřímé a pravé dílo jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 12, 'Ucho, kteréž slyší, a oko, kteréž vidí, obé to učinil Hospodin.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 13, 'Nemiluj snu, abys nezchudl, otevři oči své, a nasytíš se chlebem.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 14, 'Zlé, zlé, říká ten, kdož kupuje, a odejda, tedy se chlubí.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 15, 'Zlato a množství perel, a nejdražší klínot jsou rtové umělí.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 16, 'Vezmi roucho toho, kterýž slíbil za cizího, a kdo za cizozemku, základ jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 17, 'Chutný jest někomu chléb falše, ale potom ústa jeho pískem naplněna bývají.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 18, 'Myšlení radou upevňuj, a s opatrnou radou veď boj.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 19, 'Kdo vynáší tajnost, chodí neupřímě, pročež k lahodícímu rty svými nepřiměšuj se.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 20, 'Kdo zlořečí otci svému neb matce své, zhasne svíce jeho v temných mrákotách.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 21, 'Dědictví rychle z počátku nabytému naposledy nebývá dobrořečeno,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 22, 'Neříkej: Odplatím se zlým; očekávej na Hospodina, a vysvobodí tě.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 23, 'Ohavností jsou Hospodinu závaží rozdílná, a váhy falešné neoblibuje.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 24, 'Od Hospodina jsou krokové muže, ale člověk jak vyrozumívá cestě jeho?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 25, 'Osídlo jest člověku pohltiti věc posvěcenou, a po slibu zase toho vyhledávati.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 26, 'Král moudrý rozptyluje bezbožné, a uvodí na ně pomstu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 27, 'Duše člověka jest svíce Hospodinova, kteráž zpytuje všecky vnitřnosti srdečné.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 28, 'Milosrdenství a pravda ostříhají krále, a milosrdenstvím podpírá se trůn jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 29, 'Ozdoba mládenců jest síla jejich, a okrasa starců šediny.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 30, 'Modřiny ran jsou lékařství při zlém, a bití vnitřnostem života.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 1, 'Jako potůčkové vod jest srdce královo v ruce Hospodinově; kamžkoli chce, nakloňuje ho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 2, 'Všeliká cesta člověka přímá se zdá jemu, ale kterýž zpytuje srdce, Hospodin jest.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 3, 'Vykonávati spravedlnost a soud více se líbí Hospodinu nežli obět.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 4, 'Vysokost očí, širokost srdce, a orání bezbožných jest hříchem.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 5, 'Myšlení bedlivého všelijak ku prospěchu přicházejí, ale každého toho, kdož kvapný jest, toliko k nouzi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 6, 'Pokladové jazykem lživým shromáždění jsou marnost pomíjející hledajících smrti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 7, 'Zhouba, kterouž činí bezbožníci, bydliti bude u nich; nebo se zpěčují činiti soudu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 8, 'Muž, jehož cesta převrácená jest, cizí jest, čistého pak dílo přímé jest.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 9, 'Lépe jest bydliti v koutě na střeše, nežli s ženou svárlivou v domě společném.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 10, 'Duše bezbožného žádá zlého, ani přítel jeho jemu příjemný nebývá.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 11, 'Posměvač když bývá trestán, hloupý bývá moudřejší; a když se uměle nakládá s moudrým, přijímá umění.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 12, 'Vyučuje Bůh spravedlivého na domě bezbožného, kterýž vyvrací bezbožné pro zlost.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 13, 'Kdo zacpává ucho své k volání chudého, i on sám volati bude, a nebude vyslyšán.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 14, 'Dar skrytý ukrocuje prchlivost, a pocta v klíně hněv prudký.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 15, 'Radostí jest spravedlivému činiti soud, ale hrůzou činitelům nepravosti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 16, 'Člověk bloudící z cesty rozumnosti v shromáždění mrtvých odpočívati bude.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 17, 'Muž milující veselost nuzníkem bývá, a kdož miluje víno a masti, nezbohatne.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 18, 'Výplatou za spravedlivého bude bezbožný, a za upřímé ošemetný.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 19, 'Lépe jest bydliti v zemi pusté než s ženou svárlivou a zlostnou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 20, 'Poklad žádostivý a olej jest v příbytku moudrého, bláznivý pak člověk zžírá jej.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 21, 'Kdo snažně následuje spravedlnosti a milosrdenství, nalézá život, spravedlnost i slávu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 22, 'Do města silných vchází moudrý, a boří pevnost doufání jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 23, 'Kdo ostříhá úst svých a jazyka svého, ostříhá od úzkosti duše své.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 24, 'Hrdého a pyšného jméno jest posměvač, kterýž vše s neochotností a pýchou dělá.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 25, 'Žádost lenivého zabijí jej, nebo nechtí ruce jeho dělati.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 26, 'Každého dne žádostí hoří, spravedlivý pak dává a neskoupí se.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 27, 'Obět bezbožných ohavností jest, ovšem pak jestliže by ji s nešlechetností obětovali.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 28, 'Svědek lživý zahyne, ale muž, kterýž co slyší, stále mluviti bude.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 29, 'Muž bezbožný zatvrzuje tvář svou, upřímý pak měří cestu svou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 30, 'Není žádné moudrosti, ani opatrnosti, ani rady proti Hospodinu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 31, 'Kůň strojen bývá ke dni boje, ale Hospodinovo jest vysvobození.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 1, 'Vzácnější jest jméno dobré než bohatství veliké, a přízeň lepší než stříbro a zlato.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 2, 'Bohatý a chudý potkávají se, učinitel obou jest Hospodin.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 3, 'Opatrný vida zlé, vyhne se, ale hloupí předce jdouce, těžkosti docházejí.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 4, 'Pokory a bázně Hospodinovy odplata jest bohatství a sláva i život.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 5, 'Trní a osídla jsou na cestě převráceného; kdož ostříhá duše své, vzdálí se od nich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 6, 'Vyučuj mladého podlé způsobu cesty jeho; nebo když se i zstará, neuchýlí se od ní.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 7, 'Bohatý nad chudými panuje, a vypůjčující bývá služebníkem toho, jenž půjčuje.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 8, 'Kdo rozsívá nepravost, žíti bude trápení; prut zajisté prchlivosti jeho přestane.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 9, 'Oko dobrotivé, onoť požehnáno bude; nebo udílí z chleba svého chudému.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 10, 'Vyvrz posměvače, a odejdeť svada, anobrž přestane svár a lehkost.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 11, 'Kdo miluje čistotu srdce, a v čích rtech jest příjemnost, takového král přítelem bývá.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 12, 'Oči Hospodinovy ostříhají umění, ale snažnosti ošemetného převrací.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 13, 'Říká lenoch: Lev jest vně, naprostřed ulic byl bych zabit.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 14, 'Jáma hluboká ústa postranních; ten, na kohož se hněvá Hospodin, vpadne tam.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 15, 'Bláznovství přivázáno jest k srdci mladého, ale metla kázně vzdálí je od něho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 16, 'Kdo utiská nuzného, aby rozmnožil své, a dává bohatému, jistotně bude v nouzi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 17, 'Nakloň ucha svého, a slyš slova moudrých, a mysl svou přilož k učení mému.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 18, 'Nebo to bude utěšenou věcí, jestliže je složíš v srdci svém, budou-li spolu nastrojena ve rtech tvých.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 19, 'Aby bylo v Hospodinu doufání tvé, oznamujiť to dnes. I ty také ostříhej toho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 20, 'Zdaližť jsem nenapsal znamenitých věcí z strany rad a umění,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 21, 'Aťbych v známost uvedl jistotu řečí pravých, tak abys vynášeti mohl slova pravdy těm, kteříž by k tobě poslali?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 22, 'Nelup nuzného, proto že nuzný jest, aniž potírej chudého v bráně.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 23, 'Nebo Hospodin povede při jejich, a vydře duši těm, kteříž vydírají jim.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 24, 'Nebývej přítelem hněvivého, a s mužem prchlivým neobcuj,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 25, 'Abys se nenaučil stezkám jeho, a nevložil osídla na duši svou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 26, 'Nebývej mezi rukojměmi, mezi slibujícími za dluhy.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 27, 'Nemáš-li, čím bys zaplatil, proč má kdo bráti lůže tvé pod tebou?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 28, 'Nepřenášej mezníku starodávního, kterýž učinili otcové tvoji.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 29, 'Vídáš-li, že muž snažný v díle svém před králi stává? Nestává před nepatrnými.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 1, 'Když sedneš k jídlu se pánem, pilně šetř, co jest před tebou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 2, 'Jinak vrazil bys nůž do hrdla svého, byl-li bys lakotný.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 3, 'Nežádej lahůdek jeho, nebo jsou pokrm oklamavatelný.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 4, 'Neusiluj, abys zbohatl; od opatrnosti své přestaň.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 5, 'K bohatství-liž bys obrátil oči své? Poněvadž v náhle mizí; nebo sobě zdělalo křídla podobná orličím, a zaletuje k nebi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 6, 'Nejez chleba člověka závistivého, a nežádej lahůdek jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 7, 'Nebo jak on sobě tebe váží v mysli své, tak ty pokrmu toho. Díť: Jez a pí, ale srdce jeho není s tebou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 8, 'Skyvu svou, kterouž jsi snědl, vyvrátíš, a zmaříš slova svá utěšená.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 9, 'Před bláznem nemluv, nebo pohrdne opatrností řečí tvých.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 10, 'Nepřenášej mezníku starodávního, a na pole sirotků nevcházej.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 11, 'Silnýť jest zajisté ochránce jejich; onť povede při jejich proti tobě.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 12, 'Zaveď k učení mysl svou, a uši své k řečem umění.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 13, 'Neodjímej od mladého kázně; nebo umrskáš-li jej metlou, neumřeť.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 14, 'Ty metlou jej mrskávej, a tak duši jeho z pekla vytrhneš.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 15, 'Synu můj, bude-li moudré srdce tvé, veseliti se bude srdce mé všelijak ve mně;');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 16, 'A plésati budou ledví má, když mluviti budou rtové tvoji pravé věci.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 17, 'Nechť nezávidí srdce tvé hříšníku, ale raději choď v bázni Hospodinově celý den.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 18, 'Nebo poněvadž jest odplata, naděje tvá nebude podťata.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 19, 'Slyš ty, synu můj, a buď moudrý, a naprav na cestu srdce své.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 20, 'Nebývej mezi pijány vína, ani mezi žráči masa.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 21, 'Nebo opilec a žráč zchudne, a ospánlivost v hadry obláčí.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 22, 'Poslouchej otce svého, kterýž tě zplodil, aniž pohrdej matkou svou, když se zstará.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 23, 'Pravdy nabuď, a neprodávej jí, též moudrosti, umění a rozumnosti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 24, 'Náramně bývá potěšen otec spravedlivého, a ten, kdož zplodil moudrého, veselí se z něho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 25, 'Nechať se tedy veselí otec tvůj a matka tvá, a ať pléše rodička tvá.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 26, 'Dej mi, synu můj, srdce své, a oči tvé cest mých ať ostříhají.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 27, 'Nebo nevěstka jest jáma hluboká, a studnice těsná žena cizí.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 28, 'Onať také jako loupežník úklady činí, a zoufalce na světě rozmnožuje.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 29, 'Komu běda? komu ouvech? komu svady? komu křik? komu rány darmo? komu červenost očí?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 30, 'Těm, kteříž se zdržují na víně; těm, kteříž chodí, aby vyhledali strojené víno.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 31, 'Nehleď na víno rdící se, že vydává v koflíku záři svou, a přímo vyskakuje.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 32, 'Naposledy jako had uštípne, a jako štír ušťkne.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 33, 'Oči tvé hleděti budou na cizí, a srdce tvé mluviti bude převrácené věci,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 34, 'A budeš jako ten, kterýž spí u prostřed moře, a jako ten, kterýž spí na vrchu sloupu bárky.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 35, 'Díš: Zbili mne, a nestonal jsem, tloukli mne, a nečil jsem; když procítím, dám se zase v to.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 1, 'Nenásleduj lidí zlých, aniž žádej bývati s nimi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 2, 'Nebo o zhoubě přemýšlí srdce jejich, a rtové jejich o trápení mluví.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 3, 'Moudrostí vzdělán bývá dům, a rozumností upevněn.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 4, 'Skrze umění zajisté pokojové naplněni bývají všelijakým zbožím drahým a utěšeným.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 5, 'Muž moudrý jest silný, a muž umělý přidává síly.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 6, 'Nebo skrze rady opatrné svedeš bitvu, a vysvobození skrze množství rádců.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 7, 'Vysoké jsou bláznu moudrosti; v bráně neotevře úst svých.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 8, 'Kdo myslí zle činiti, toho nešlechetným nazovou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 9, 'Zlé myšlení blázna jest hřích, a ohavnost lidská posměvač.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 10, 'Budeš-li se lenovati ve dni ssoužení, špatná bude síla tvá.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 11, 'Vytrhuj jaté k smrti; nebo od těch, ješto se chýlí k zabití, což bys se zdržel?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 12, 'Díš-li: Aj, nevěděli jsme o tom: zdaliž ten, jenž zpytuje srdce, nerozumí, a ten, kterýž jest strážce duše tvé, nezná, a neodplatí každému podlé skutků jeho?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 13, 'Synu můj, jez med, nebo dobrý jest, a plást sladký dásním tvým.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 14, 'Tak umění moudrosti duši tvé. Jestliže ji najdeš, onať bude mzda, a naděje tvá nebude vyťata.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 15, 'Nečiniž úkladů, ó bezbožníče, příbytku spravedlivého, a nekaz odpočinutí jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 16, 'Nebo ač sedmkrát padá spravedlivý, však zase povstává, bezbožníci pak padají ve zlém.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 17, 'Když by padl nepřítel tvůj, neraduj se, a když by klesl, nechať nepléše srdce tvé,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 18, 'Aby snad nepopatřil Hospodin, a nelíbilo by se to jemu, a odvrátil by od něho hněv svůj.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 19, 'Nehněvej se příčinou zlostníků, aniž následuj bezbožných.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 20, 'Nebo zlý nebude míti odplaty; svíce bezbožných zhasne.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 21, 'Boj se Hospodina, synu můj, i krále, a k neustavičným se nepřiměšuj.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 22, 'Nebo v náhle nastane bída jejich, a pomstu obou těch kdo zná?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 23, 'Také i toto moudrým náleží: Přijímati osobu v soudu není dobré.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 24, 'Toho, kdož říká bezbožnému: Spravedlivý jsi, klnouti budou lidé, a v ošklivost jej vezmou národové.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 25, 'Ale kteříž kárají, budou potěšeni, a přijde na ně požehnání dobrého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 26, 'Bude líbati rty toho, kdož mluví slova pravá.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 27, 'Nastroj vně dílo své, a sprav je sobě na poli; potom také vystavíš dům svůj.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 28, 'Nebývej svědkem všetečným proti bližnímu svému, aniž lahodně namlouvej rty svými.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 29, 'Neříkej: Jakž mi učinil, tak mu učiním; odplatím muži tomu podlé skutku jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 30, 'Přes pole muže lenivého šel jsem, a přes vinici člověka nemoudrého,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 31, 'A aj, porostlo všudy trním, přikryly všecko kopřivy, a ohrada kamenná její byla zbořená.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 32, 'A vida to, posoudil jsem toho; vida, vzal jsem to k výstraze.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 33, 'Maličko pospíš, maličko zdřímeš, maličko složíš ruce, abys poležel,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 34, 'V tom přijde jako pocestný chudoba tvá, a nouze tvá jako muž zbrojný.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 1, 'Jaké i tato jsou přísloví Šalomounova, kteráž shromáždili muži Ezechiáše, krále Judského:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 2, 'Sláva Boží jest skrývati věc, ale sláva králů zpytovati věc.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 3, 'Vysokosti nebes, a hlubokosti země, a srdce králů není žádného vystižení.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 4, 'Jako když bys odjal trůsku od stříbra, ukáže se slevači nádoba čistá:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 5, 'Tak když odejmeš bezbožného od oblíčeje králova, tedy utvrzen bude v spravedlnosti trůn jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 6, 'Nestavěj se za znamenitého před králem, a na místě velikých nestůj.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 7, 'Nebo lépe jest, aťby řečeno bylo: Vstup sem, nežli abys snížen byl před knížetem; což vídávají oči tvé.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 8, 'Nevcházej v svár kvapně, tak abys naposledy něčeho se nedopustil, kdyby tě zahanbil bližní tvůj.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 9, 'Srovnej při svou s bližním svým, a tajné věci jiného nevyjevuj,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 10, 'Aťby lehkosti neučinil ten, kdož by to slyšel, až by i zlá pověst tvá nemohla jíti nazpět.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 11, 'Jablka zlatá s řezbami stříbrnými jest slovo propověděné případně.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 12, 'Náušnice zlatá a ozdoba z ryzího zlata jest trestatel moudrý u toho, jenž poslouchá.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 13, 'Jako studenost sněžná v čas žně, tak jest posel věrný těm, kteříž jej posílají; nebo duši pánů svých očerstvuje.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 14, 'Jako oblakové a vítr bez deště, tak člověk, kterýž se chlubí darem lživým.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 15, 'Snášelivostí nakloněn bývá vývoda, a jazyk měkký láme kosti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 16, 'Nalezneš-li med, jez, pokudž by dosti bylo tobě, abys snad nasycen jsa jím, nevyvrátil ho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 17, 'Zdržuj nohu svou od domu bližního svého, aby syt jsa tebe, neměl tě v nenávisti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 18, 'Kladivo a meč a střela ostrá jest každý, kdož mluví falešné svědectví proti bližnímu svému.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 19, 'Zub vylomený a noha vytknutá jest doufání v převráceném v den úzkosti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 20, 'Jako ten, kdož svláčí oděv v čas zimy, a ocet lije k sanitru, tak kdož zpívá písničky srdci smutnému.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 21, 'Jestliže by lačněl ten, jenž tě nenávidí, nakrm jej chlebem, a žíznil-li by, napoj jej vodou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 22, 'Nebo uhlí řeřavé shromáždíš na hlavu jeho, a Hospodin odplatí tobě.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 23, 'Vítr půlnoční zplozuje déšť, a tvář hněvivá jazyk tajně utrhající.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 24, 'Lépe jest bydliti v koutě na střeše, nežli s ženou svárlivou v domě společném.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 25, 'Voda studená duši ustalé jest novina dobrá z země daleké.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 26, 'Studnice nohami zakalená a pramen zkažený jest spravedlivý z místa svého před bezbožným vystrčený.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 27, 'Jísti mnoho medu není dobře; tak zpytování slávy jejich není slavné.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 28, 'Město rozbořené beze zdi jest muž, kterýž nemá moci nad duchem svým.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 1, 'Jako sníh v létě, a jako déšť ve žni, tak nepřipadá na blázna čest.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 2, 'Jako vrabec přenáší se, a vlaštovice létá, tak zlořečení bez příčiny nedojde.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 3, 'Bič na koně, uzda na osla, a kyj na hřbet blázna.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 4, 'Neodpovídej bláznu podlé bláznovství jeho, abys i ty jemu nebyl podobný.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 5, 'Odpověz bláznu podlé bláznovství jeho, aby sám u sebe nebyl moudrý.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 6, 'Jako by nohy osekal, bezpráví se dopouští ten, kdož svěřuje poselství bláznu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 7, 'Jakož nejednostejní jsou hnátové kulhavého, tak řeč v ústech bláznů.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 8, 'Jako vložiti kámen do praku, tak jest, když kdo ctí blázna.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 9, 'Trn, kterýž se dostává do rukou opilého, jest přísloví v ústech bláznů.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 10, 'Veliký pán stvořil všecko, a dává odplatu bláznu, i odměnu přestupníkům.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 11, 'Jakož pes navracuje se k vývratku svému, tak blázen opětuje bláznovství své.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 12, 'Spatřil-li bys člověka, an jest moudrý sám u sebe, naděje o bláznu lepší jest než o takovém.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 13, 'Říká lenoch: Lev lítý jest na cestě, lev jest v ulici.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 14, 'Dvéře se obracejí na stežejích svých, a lenoch na lůži svém.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 15, 'Schovává lenivý ruku svou za ňadra; těžko mu vztáhnouti ji k ústům svým.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 16, 'Moudřejší jest lenivý u sebe sám, nežli sedm odpovídajících s soudem.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 17, 'Psa za uši lapá, kdož odcházeje, hněvá se ne v své při.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 18, 'Jako nesmyslný vypouští jiskry a šípy smrtelné,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 19, 'Tak jest každý, kdož oklamává bližního, a říká: Zdaž jsem nežertoval?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 20, 'Když není drev, hasne oheň; tak když nebude klevetníka, utichne svár.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 21, 'Uhel mrtvý k roznícení, a drva k ohni, tak člověk svárlivý k roznícení svady.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 22, 'Slova utrhače jako ubitých, ale však sstupují do vnitřností života.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 23, 'Stříbrná trůska roztažená po střepě jsou rtové protivní a srdce zlé.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 24, 'Rty svými za jiného se staví ten, jenž nenávidí, ale u vnitřnosti své skládá lest.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 25, 'Když se ochotný ukáže řečí svou, nevěř mu; nebo sedmera ohavnost jest v srdci jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 26, 'Přikrývána bývá nenávist chytře, ale zlost její zjevena bývá v shromáždění.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 27, 'Kdo jámu kopá, do ní upadá, a kdo valí kámen, na něj se obrací.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 28, 'Člověk jazyka ošemetného v nenávisti má ponížené, a ústy úlisnými způsobuje pád.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 1, 'Nechlub se dnem zítřejším, nebo nevíš, coť ten den přinese.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 2, 'Nechať tě chválí jiní, a ne ústa tvá, cizí, a ne rtové tvoji.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 3, 'Tíž má kamen, a váhu písek, ale hněv blázna těžší jest nad to obé.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 4, 'Ukrutnátě věc hněv a prudká prchlivost, ale kdo ostojí před závistí?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 5, 'Lepší jest domlouvání zjevné, než milování tajné.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 6, 'Bezpečnější rány od přítele, než lahodná líbání nenávidícího.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 7, 'Duše sytá pohrdá i medem, ale duši lačné každá hořkost sladká.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 8, 'Jako pták zaletuje od hnízda svého, tak muž odchází od místa svého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 9, 'Mast a kadění obveseluje srdce; tak sladkost přítele víc než rada vlastní.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 10, 'Přítele svého a přítele otce svého neopouštěj, a do domu bratra svého nechoď v čas bídy své; lepšíť jest soused blízký, než bratr daleký.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 11, 'Buď moudrý, synu můj, a obvesel srdce mé, ať mám co odpovědíti tomu, kdož mi utrhá.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 12, 'Opatrný vida zlé, vyhne se, ale hloupí předce jdouce, těžkosti docházejí.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 13, 'Vezmi roucho toho, kterýž slíbil za cizího, a od toho, kdo za cizozemku slíbil, základ jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 14, 'Tomu, kdož dobrořečí příteli svému hlasem velikým, ráno vstávaje, za zlořečení počteno bude.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 15, 'Kapání ustavičné v čas přívalu, a žena svárlivá rovní jsou sobě;');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 16, 'Kdož ji schovává, schovává vítr, a jako mast v pravici voněti bude.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 17, 'Železo železem se ostří; tak muž zostřuje tvář přítele svého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 18, 'Kdo ostříhá fíku, jídá ovoce jeho; tak kdo ostříhá pána svého, poctěn bude.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 19, 'Jakož u vodě tvář proti tváři se ukazuje, tak srdce člověka člověku.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 20, 'Propast a zahynutí nebývají nasyceni, tak oči člověka nasytiti se nemohou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 21, 'Teglík stříbra a pec zlata zkušuje, tak člověka pověst chvály jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 22, 'Bys blázna i v stupě mezi krupami píchem zopíchal, neodejde od něho bláznovství jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 23, 'Pilně přihlídej k dobytku svému, pečuj o stáda svá.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 24, 'Nebo ne na věky trvá bohatství, ani koruna do pronárodu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 25, 'Když zroste tráva, a ukazuje se bylina, tehdáž ať se shromažďuje seno s hor.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 26, 'Beránkové budou k oděvu tvému, a záplata pole kozelci.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 27, 'Nadto dostatek mléka kozího ku pokrmu tvému, ku pokrmu domu tvého, a živnosti děvek tvých.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 1, 'Utíkají bezbožní, ač jich žádný nehoní, ale spravedliví jako mladý lev smělí jsou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 2, 'Pro přestoupení země mnoho knížat jejích, ale pro člověka rozumného a umělého trvánlivé bývá panování.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 3, 'Muž chudý, kterýž utiská nuzné, podoben jest přívalu zachvacujícímu, za čímž nebývá chleba.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 4, 'Kteří opouštějí zákon, chválí bezbožného, ale kteříž ostříhají zákona, velmi jsou jim na odpor.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 5, 'Lidé zlí nesrozumívají soudu, ti pak, kteříž hledají Hospodina, rozumějí všemu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 6, 'Lepší jest chudý, kterýž chodí v upřímnosti své, než převrácený na kterékoli cestě, ačkoli jest bohatý.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 7, 'Kdo ostříhá zákona, jest syn rozumný; kdož pak s žráči tovaryší, hanbu činí otci svému.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 8, 'Kdo rozmnožuje statek svůj lichvou a úrokem, shromažďuje tomu, kdož by jej z milosti chudým rozděloval.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 9, 'Kdo odvrací ucho své, aby neslyšel zákona, i modlitba jeho jest ohavností.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 10, 'Kdo zavodí upřímé na cestu zlou, do jámy své sám vpadne, ale upřímí dědičně obdrží dobré.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 11, 'Moudrý jest u sebe sám muž bohatý, ale chudý rozumný vystihá jej.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 12, 'Když plésají spravedliví, velmi to pěkně sluší; ale když povstávají bezbožní, vyhledáván bývá člověk.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 13, 'Kdo přikrývá přestoupení svá, nepovede se jemu šťastně; ale kdož je vyznává a opouští, milosrdenství důjde.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 14, 'Blahoslavený člověk, kterýž se strachuje vždycky; ale kdož zatvrzuje srdce své, upadne ve zlé.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 15, 'Lev řvoucí a nedvěd hladovitý jest panovník bezbožný nad lidem nuzným.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 16, 'Kníže bez rozumu bývá veliký dráč, ale kdož v nenávisti má mrzký zisk, prodlí dnů.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 17, 'Člověka, kterýž násilí činí krvi lidské, ani nad jamou, když utíká, žádný ho nezadrží.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 18, 'Kdo chodí upřímě, zachován bude, převrácený pak na kterékoli cestě padne pojednou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 19, 'Kdo dělá zemi svou, nasycen bývá chlebem; ale kdož následuje zahalečů, nasycen bývá chudobou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 20, 'Muž věrný přispoří požehnání, ale kdož chvátá zbohatnouti, nebývá bez viny.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 21, 'Přijímati osobu není dobré; nebo mnohý pro kus chleba neprávě činí.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 22, 'Člověk závistivý chvátá k statku, nic nevěda, že nouze na něj přijde.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 23, 'Kdo domlouvá člověku, potom spíše milost nalézá nežli ten, kterýž lahodí jazykem.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 24, 'Kdo loupí otce svého a matku svou, a říká, že to není žádný hřích, tovaryš jest vražedlníka.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 25, 'Vysokomyslný vzbuzuje svár, ale kdo doufá v Hospodina, hojnost míti bude.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 26, 'Kdo doufá v srdce své, blázen jest; ale kdož chodí moudře, pomůže sobě.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 27, 'Kdo dává chudému, nebude míti žádného nedostatku; kdož pak zakrývá oči své, bude míti množství zlořečení.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 28, 'Když povstávají bezbožní, skrývá se člověk; ale když hynou, rozmnožují se spravedliví.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 1, 'Člověk, kterýž často kárán bývaje, zatvrzuje šíji, rychle potřín bude, tak že neprospěje žádné lékařství.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 2, 'Když se množí spravedliví, veselí se lid; ale když panuje bezbožník, vzdychá lid.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 3, 'Muž, kterýž miluje moudrost, obveseluje otce svého; ale kdož se přitovaryšuje k nevěstkám, mrhá statek.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 4, 'Král soudem upevňuje zemi, muž pak, kterýž béře dary, boří ji.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 5, 'Člověk, kterýž pochlebuje příteli svému, rozprostírá sít před nohama jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 6, 'Výstupek bezbožného jest jemu osídlem, spravedlivý pak prozpěvuje a veselí se.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 7, 'Spravedlivý vyrozumívá při nuzných, ale bezbožník nemá s to rozumnosti ani umění.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 8, 'Muži posměvači zavozují město, ale moudří odvracují hněv.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 9, 'Muž moudrý, kterýž se nesnadní s mužem bláznivým, buď že se pohne, buď že se směje, nemá pokoje.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 10, 'Vražedlníci v nenávisti mají upřímého, ale upřímí pečují o duši jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 11, 'Všecken duch svůj vypouští blázen, ale moudrý na potom zdržuje jej.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 12, 'Pána toho, kterýž rád poslouchá slov lživých, všickni služebníci jsou bezbožní.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 13, 'Chudý a dráč potkávají se, obou dvou však oči osvěcuje Hospodin.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 14, 'Krále toho, kterýž soudí právě nuzné, trůn na věky bývá utvrzen.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 15, 'Metla a kárání dává moudrost, ale dítě sobě volné k hanbě přivodí matku svou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 16, 'Když se rozmnožují bezbožní, rozmnožuje se převrácenost, a však spravedliví spatřují pád jejich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 17, 'Tresci syna svého, a přineseť odpočinutí, a způsobí rozkoš duši tvé.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 18, 'Když nebývá vidění, rozptýlen bývá lid; kdož pak ostříhá zákona, blahoslavený jest.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 19, 'Slovy nebývá napraven služebník; nebo rozuměje, však neodpoví.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 20, 'Spatřil-li bys člověka, an jest kvapný v věcech svých, lepší jest naděje o bláznu, než o takovém.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 21, 'Kdo rozkošně chová z dětinství služebníka svého, naposledy bude syn.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 22, 'Člověk hněvivý vzbuzuje svár, a prchlivý mnoho hřeší.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 23, 'Pýcha člověka snižuje jej, ale chudý duchem dosahuje slávy.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 24, 'Kdo má spolek s zlodějem, v nenávisti má duši svou; zlořečení slyší, však neoznámí.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 25, 'Strašlivý člověk klade sobě osídlo, ale kdo doufá v Hospodina, bývá povýšen.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 26, 'Mnozí hledají tváři pánů, ješto od Hospodina jest soud jednoho každého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 27, 'Ohavností spravedlivým jest muž nepravý, ohavností pak bezbožnému, kdož upřímě kráčí.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 1, 'Slova Agura, syna Jáke. Sepsání řečí muže toho k Itielovi, k Itielovi a Uchalovi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 2, 'Jistě žeť jsem hloupější nad jiné, tak že rozumnosti člověka obecného nemám,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 3, 'Aniž jsem se naučil moudrosti, a umění svatých neumím.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 4, 'Kdo vstoupil v nebe, i sstoupil? Kdo sebral vítr do hrstí svých? Kdo shrnul vody v roucho své? Kdo upevnil všecky končiny země? Které jméno jeho, a jaké jméno syna jeho, víš-li?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 5, 'Všeliká výmluvnost Boží přečištěná jest; onť jest štít doufajících v něho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 6, 'Nepřidávej k slovům jeho, aby tě nekáral, a byl bys ve lži postižen.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 7, 'Dvou věcí žádám od tebe, neoslýchejž mne, prvé než umru:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 8, 'Marnost a slovo lživé vzdal ode mne, chudoby neb bohatství nedávej mi, živ mne pokrmem vedlé potřeby mé,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 9, 'Abych snad nasycen jsa, tě nezapřel, a neřekl: Kdo jest Hospodin? a abych zchudna, nekradl, a nebral naprázdno jména Hospodina Boha svého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 10, 'Nesoč na služebníka před pánem jeho, aťby nezlořečil, a ty abys nehřešil.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 11, 'Jest pokolení, kteréž otci svému zlořečí, a matce své nedobrořečí.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 12, 'Jest pokolení čisté samo u sebe, ačkoli od nečistot svých není obmyto.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 13, 'Jest pokolení, jehož vysoké jsou oči, a víčka jeho jsou vyzdvižená.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 14, 'Jest pokolení, jehož zubové jsou mečové, a třenovní zubové jeho nožové, k zžírání chudých na zemi a nuzných na světě.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 15, 'Pijavice má dvě dcery říkající: Dej, dej. Tři věci nebývají nasyceny, anobrž čtyry, kteréž nikdy neřeknou: Dosti:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 16, 'Peklo a život neplodné, země též nebývá nasycena vodou, a oheň neříká: Dosti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 17, 'Oko, kteréž se posmívá otci, a pohrdá poslušenstvím matky, vyklubí krkavci potoční, aneb snědí je orličata.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 18, 'Tři tyto věci skryty jsou přede mnou, nýbrž čtyry, kterýchž neznám:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 19, 'Cesty orlice v povětří, cesty hada na skále, cesty lodí u prostřed moře, a cesty muže při panně.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 20, 'Takováž jest cesta ženy cizoložné: Jí, a utře ústa svá, a dí: Nepáchala jsem nepravosti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 21, 'Pode třmi věcmi pohybuje se země, anobrž pod čtyřmi, jichž nemůž snésti:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 22, 'Pod služebníkem, když kraluje, a bláznem, když se nasytí chleba;');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 23, 'Pod omrzalou, když se vdá, a děvkou, když dědičkou bývá paní své.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 24, 'Čtyry tyto věci jsou malé na zemi, a však jsou moudřejší nad mudrce:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 25, 'Mravenci, lid nesilný, kteříž však připravují v létě pokrm svůj;');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 26, 'Králíkové, lid nesilný, kteříž však stavějí v skále dům svůj;');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 27, 'Krále nemají kobylky, a však vycházejí po houfích všecky;');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 28, 'Pavouk rukama dělá, a bývá na palácích královských.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 29, 'Tři tyto věci udatně vykračují, anobrž čtyry, kteréž zmužile chodí:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 30, 'Lev nejsilnější mezi zvířaty, kterýž neustupuje před žádným;');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 31, 'Přepásaný na bedrách kůň neb kozel, a král, proti němuž žádný nepovstává.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 32, 'Jestliže jsi bláznil, vynášeje se, a myslil-lis zle, ruku na ústa polož.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 33, 'Kdo tluče smetanu, stlouká máslo, a stiskání nosu vyvodí krev, tak popouzení k hněvu vyvodí svár.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 1, 'Slova proroctví Lemuele krále, kterýmž vyučovala jej matka jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 2, 'Co dím, synu můj, co, synu života mého? Co, řku, dím, synu slibů mých?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 3, 'Nedávej ženám síly své, ani cest svých těm, kteréž k zahynutí přivodí krále.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 4, 'Ne králům, ó Lemueli, ne králům náleží píti víno, a ne pánům žádost nápoje opojného,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 5, 'Aby pije, nezapomněl na ustanovení, a nezměnil pře všech lidí ssoužených.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 6, 'Dejte nápoj opojný hynoucímu, a víno těm, kteříž jsou truchlivého ducha,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 7, 'Ať se napije, a zapomene na chudobu svou, a na trápení své nezpomíná více.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 8, 'Otevři ústa svá za němého, v při všech oddaných k smrti,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 9, 'Otevři, řku, ústa svá, suď spravedlivě, a veď při chudého a nuzného.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 10, 'Ženu statečnou kdo nalezne? Nebo daleko nad perly cena její.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 11, 'Dověřuje se jí srdce muže jejího; nebo tu kořistí nebude nedostatku.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 12, 'Dobře činí jemu a ne zle, po všecky dny života svého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 13, 'Hledá pilně vlny a lnu, a dělá šťastně rukama svýma.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 14, 'Jest podobná lodi kupecké, zdaleka přiváží pokrm svůj.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 15, 'Kterážto velmi ráno vstávajíc, dává pokrm čeledi své, a podíl náležitý děvkám svým.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 16, 'Rozsuzuje pole, a ujímá je; z výdělku rukou svých štěpuje i vinici.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 17, 'Přepasuje silou bedra svá, a zsiluje ramena svá.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 18, 'Zakouší, jak jest užitečné zaměstknání její; ani v noci nehasne svíce její.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 19, 'Rukama svýma sahá k kuželi, a prsty svými drží vřeteno.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 20, 'Ruku svou otvírá chudému, a ruce své vztahuje k nuznému.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 21, 'Nebojí se za čeled svou v čas sněhu; nebo všecka čeled její obláčí se v roucho dvojnásobní.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 22, 'Koberce dělá sobě z kmentu, a z zlatohlavu jest oděv její.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 23, 'Patrný jest v branách manžel její, když sedá s staršími země.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 24, 'Plátno drahé dělá, a prodává; též i pasy prodává kupci.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 25, 'Síla a krása oděv její, nestará se o časy potomní.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 26, 'Ústa svá otvírá k moudrosti, a naučení dobrotivosti v jazyku jejím.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 27, 'Spatřuje obcování čeledi své, a chleba zahálky nejí.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 28, 'Povstanouce synové její, blahoslaví ji; manžel její také chválí ji,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 29, 'Říkaje: Mnohé ženy statečně sobě počínaly, ty pak převyšuješ je všecky.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 30, 'Oklamavatelná jest příjemnost a marná krása; žena, kteráž se bojí Hospodina, tať chválena bude.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 31, 'Dejtež takové z ovoce rukou jejích, a nechať ji chválí v branách skutkové její.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 1, 'Slova kazatele syna Davidova, krále v Jeruzalémě.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 2, 'Marnost nad marnostmi, řekl kazatel, marnost nad marnostmi, a všecko marnost.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 3, 'Jaký užitek má člověk ze všelijaké práce své, kterouž vede pod sluncem?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 4, 'Věk pomíjí, a jiný věk nastává, ačkoli země na věky trvá.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 5, 'Vychází slunce, i zapadá slunce, a k místu svému chvátá, kdež vychází.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 6, 'Jde ku poledni, a obrací se na půlnoci, sem i tam se toče, chodí vítr, a okolky svými navracuje se vítr.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 7, 'Všecky řeky jdou do moře, a však se moře nepřeplňuje; do místa, do něhož tekou řeky, navracují se, aby zase odtud vycházely.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 8, 'Všecky věci jsou plné zaneprázdnění, aniž může člověk vymluviti; nenasytí se oko hleděním, aniž se naplní ucho slyšením.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 9, 'Což bylo, jest to, což býti má; a což se nyní děje, jest to, což se díti bude; aniž jest co nového pod sluncem.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 10, 'Jest-liž jaká věc, o níž by říci mohl: Pohleď, toť jest cosi nového? Ano již to bylo před věky, kteříž byli před námi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 11, 'Není paměti prvních věcí, aniž také potomních, kteréž budou, památka zůstane u těch, jenž potom nastanou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 12, 'Já kazatel byl jsem králem nad Izraelem v Jeruzalémě,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 13, 'A přiložil jsem mysl svou k tomu, jak bych vyhledati a vystihnouti mohl rozumností svou všecko to, což se děje pod nebem. (Takové bídné zaměstknání dal Bůh synům lidským, aby se jím bědovali.)');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 14, 'Viděl jsem všecky skutky, dějící se pod sluncem, a aj, všecko jest marnost a trápení ducha.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 15, 'Což křivého jest, nemůže se zpřímiti, a nedostatkové nemohou sečteni býti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 16, 'Protož tak jsem myslil v srdci svém, řka: Aj, já zvelebil jsem a rozšířil moudrost nade všecky, kteříž byli přede mnou v Jeruzalémě, a srdce mé dosáhlo množství moudrosti a umění.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 17, 'I přiložil jsem mysl svou, abych poznal moudrost a umění, nemoudrost i bláznovství, ale shledal jsem, že i to jest trápení ducha.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 18, 'Nebo kde jest mnoho moudrosti, tu mnoho hněvu; a kdož rozmnožuje umění, rozmnožuje bolest.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 1, 'Řekl jsem opět srdci svému: Nuže nyní zkusím tě v veselí, užívejž tedy dobrých věcí. A hle, i to marnost.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 2, 'Smíchu jsem řekl: Blázníš, a veselí: Co to děláš?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 3, 'Přemyšloval jsem v srdci svém, abych povoloval u víně tělu svému, srdce však své spravuje moudrostí, a přídržel se bláznovství dotud, až bych zkusil, co by lepšího bylo synům lidským, aby činili pod nebem v počtu dnů života svého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 4, 'Veliké jsem skutky činil, vystavěl jsem sobě domy, štípil jsem sobě vinice.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 5, 'Vzdělal jsem sobě zahrady a štěpnice, a štípil jsem v nich stromy všelijakého ovoce.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 6, 'Nadělal jsem sobě rybníků, abych svlažoval jimi les plodící dříví.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 7, 'Najednal jsem sobě služebníků a děvek, a měl jsem čeled v domě svém; k tomu i stáda skotů a bravů veliká měl jsem nade všecky, kteříž byli přede mnou v Jeruzalémě.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 8, 'Nahromáždil jsem sobě také stříbra a zlata a klínotů od králů a krajin; způsobil jsem sobě zpěváky a zpěvakyně i jiné rozkoše synů lidských a nástroje muzické rozličné.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 9, 'A tak velikým jsem učiněn, a zrostl jsem nade všecky, kteříž přede mnou byli v Jeruzalémě; nadto moudrost má zůstávala při mně.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 10, 'A čehožkoli žádaly oči mé, nezbránil jsem jim, aniž jsem zbraňoval srdci svému jakého veselí; srdce mé zajisté veselilo se ze vší práce mé, a to byl podíl můj ze vší práce mé.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 11, 'Ale jakž jsem se ohlédl na všecky skutky své, kteréž činily ruce mé, a na práci úsilně vedenou, a aj, všecko marnost a trápení ducha, a že nic není užitečného pod sluncem.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 12, 'Pročež obrátil jsem se, abych spatřoval moudrost a nemoudrost, i bláznovství. (Nebo co by člověk spravil, chtěje následovati krále? To, což již jiní spravili.)');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 13, 'I viděl jsem, že jest užitečnější moudrost než bláznovství, tak jako jest užitečnější světlo nežli temnost.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 14, 'Moudrý má oči v hlavě své, blázen pak ve tmách chodí; a však poznal jsem, že jednostejné příhody všechněm se přiházejí.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 15, 'Protož jsem řekl v srdci svém: Má-liť mi se tak díti, jako se děje bláznu, pročež jsem tedy moudrostí předčil? A tak řekl jsem v srdci svém: I to jest marnost.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 16, 'Nebo není památka moudrého jako i blázna na věky, proto že to, což nyní jest, ve dnech budoucích všecko v zapomenutí přichází, a že jakož umírá moudrý, tak i blázen.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 17, 'Pročež mrzí mne tento život; nebo se mi nelíbí nic, což se děje pod sluncem, poněvadž všecky věci jsou marnost a trápení ducha.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 18, 'Ano mrzí mne i všecka práce má, kterouž jsem vedl pod sluncem proto že jí zanechati musím člověku, kterýž bude po mně.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 19, 'A kdo ví, bude-li moudrý, či blázen? A však panovati bude nade vší prací mou, kterouž jsem vedl, a v níž jsem moudrý byl pod sluncem. A i to marnost.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 20, 'I přišel jsem na to, abych pochybil v srdci svém o vší práci, kterouž jsem konal, a v níž jsem moudrý byl pod sluncem.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 21, 'Mnohý zajisté člověk pracuje moudře, uměle a spravedlivě, a však jinému, kterýž nepracoval o tom, nechává toho za podíl jemu, ješto i to jest marnost a bídná věc.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 22, 'Nebo co má člověk ze vší práce své a z kvaltování srdce svého, kteréž snáší pod sluncem,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 23, 'Poněvadž všickni dnové jeho bolestní, a zaměstknání jeho hněv, tak že ani v noci neodpočívá srdce jeho? A i to marnost.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 24, 'Zdaliž není to chvalitebné při člověku, jísti a píti, a učiniti životu svému pohodlí z práce své? Ač i to také viděl jsem, že z ruky Boží pochází.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 25, 'Nebo kdož by jísti a užívati měl toho nežli já?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 26, 'Člověku zajisté, kterýž se líbí jemu, dává moudrost, umění a veselí; hříšníku pak dává trápení, aby shromažďoval a hrnul, čehož by zanechal tomu, kterýž se líbí Bohu. I to také jest marnost a trápení ducha.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 1, 'Všeliká věc má jistý čas, a každé předsevzetí pod nebem svou chvíli.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 2, 'Jest čas rození i čas umírání, čas sázení a čas vykopání, což vsazeno bývá;');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 3, 'Čas mordování a čas hojení, čas boření a čas stavení;');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 4, 'Čas pláče a čas smíchu, čas smutku a čas proskakování;');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 5, 'Čas rozmítání kamení a čas shromažďování kamení, čas objímání a čas vzdálení se od objímání;');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 6, 'Čas hledání a čas ztracení, čas chování a čas zavržení;');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 7, 'Čas roztrhování a čas sšívání, čas mlčení a čas mluvení;');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 8, 'Čas milování a čas nenávidění, čas boje a čas pokoje.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 9, 'Co tedy má ten, kdo práci vede, z toho, o čemž pracuje?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 10, 'Viděl jsem zaměstknání, kteréž dal Bůh synům lidským, aby se jím trápili.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 11, 'Sám všecko činí ušlechtile časem svým, nýbrž i žádost světa dal v srdce jejich, aby nestihal člověk díla toho, kteréž dělá Bůh, ani počátku ani konce.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 12, 'Odtud seznávám, že nic lepšího nemají, než aby se veselili, a činili dobře v životě svém,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 13, 'Ač i to, když všeliký člověk jí a pije, a užívá dobrých věcí ze všelijaké práce své, jest dar Boží.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 14, 'Znám, že cožkoli činí Bůh, to trvá na věky; nemůže se k tomu nic přidati, ani od toho co odjíti. A činí to Bůh, aby se báli oblíčeje jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 15, 'To, což bylo, i nyní jest, a což bude, již bylo; nebo Bůh obnovuje to, což pominulo.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 16, 'Přesto viděl jsem ještě pod sluncem na místě soudu bezbožnost, a na místě spravedlnosti nespravedlnost.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 17, 'I řekl jsem v srdci svém: Budeť Bůh spravedlivého i bezbožného souditi; nebo tam bude čas každému předsevzetí i každému skutku.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 18, 'Řekl jsem v srdci svém o způsobu synů lidských, že jim ukázal Bůh, aby viděli, že jsou podobni hovadům.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 19, 'Případnost synů lidských a případnost hovad jest případnost jednostejná. Jakož umírá ono, tak umírá i on, a dýchání jednostejné všickni mají, aniž co napřed má člověk před hovadem; nebo všecko jest marnost.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 20, 'Obé to jde k místu jednomu; obé jest z prachu, obé také zase navracuje se do prachu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 21, 'Kdo to zná, že duch synů lidských vstupuje zhůru, a duch hovadí že sstupuje pod zemi?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 22, 'Protož spatřil jsem, že nic není lepšího, než veseliti se člověku v skutcích svých, poněvadž to jest podíl jeho. Nebo kdo jej k tomu přivede, aby poznati mohl to, což jest budoucího po něm?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 1, 'Opět obrátiv se, i viděl jsem všeliká ssoužení, kteráž se dějí pod sluncem, a aj, slzy křivdu trpících, ješto nemají potěšitele, ani moci k vyjití z ruky těch, kteříž je ssužují, a nemají potěšitele.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 2, 'Protož já chválil jsem mrtvé, kteříž již zemřeli, více nežli živé, kteříž jsou živi až po dnes.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 3, 'Nýbrž nad oba tyto šťastnější jest ten, kterýž ještě nebyl, a neviděl skutku zlého, dějícího se pod sluncem.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 4, 'Nebo spatřil jsem všelikou práci a každé dobré dílo, že jest k závisti jedněch druhým. I to také jest marnost a trápení ducha.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 5, 'Blázen skládá ruce své, a jí maso své, říkaje:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 6, 'Lepší jest plná hrst s odpočinutím, nežli přehršlí plné s prací a trápením ducha.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 7, 'Opět obrátiv se, viděl jsem jinou marnost pod sluncem:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 8, 'Jest samotný někdo, nemaje žádného, ani syna, ani bratra, a však není konce všeliké práci jeho, ani oči jeho nemohou se nasytiti bohatství. Nepomyslí: Komu já pracuji, tak že i životu svému ujímám pohodlí? I to také jest marnost a bídné zaneprázdnění.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 9, 'Lépeť jest dvěma než jednomu; mají zajisté dobrý užitek z práce své.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 10, 'Nebo padne-li který z nich, druhý pozdvihne tovaryše svého. Běda tedy samotnému, když by padl; nebo nemá druhého, aby ho pozdvihl.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 11, 'Také budou-li dva spolu ležeti, zahřejí se, ale jeden jak se zahřeje?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 12, 'Ovšem, jestliže by se kdo jednoho zmocniti chtěl, dva postaví se proti němu; ano trojnásobní provázek nesnadně se přetrhne.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 13, 'Lepší jest dítě chudé a moudré, než král starý a blázen, kterýž neumí již ani napomenutí přijímati,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 14, 'Ačkoli z žaláře vychází, aby kraloval, nýbrž i v království svém může na chudobu přijíti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 15, 'Viděl jsem všecky živé, kteříž chodí pod sluncem, ani se přídrželi pacholete, potomka onoho, kterýž měl kralovati místo něho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 16, 'Nebývalo konce té vrtkosti všeho lidu, jakž toho, kterýž byl před nimi, takž ani potomci nebudou se těšiti z něho. Protož i to jest marnost a trápení ducha.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 1, 'Ostříhej nohy své, když jdeš do domu Božího, a buď hotovější k slyšení nežli k dávání obětí bláznů; nebo oni neznají toho, že zle činí.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 2, 'Nebývej rychlý k mluvení, ani srdce tvé kvapné k vynášení slova před oblíčejem Božím, poněvadž Bůh jest na nebi, a ty na zemi; protož nechť jsou slova tvá nemnohá.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 3, 'Nebo jakož přichází sen z velikého pracování, tak hlas blázna z množství slov.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 4, 'Když bys učinil slib Bohu, neprodlévej ho splniti, nebo nemá líbosti v blázních. Cožkoli slíbíš, splň.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 5, 'Lépe jest, abys nesliboval, než abys slibě, neplnil.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 6, 'Nedopouštěj ústům svým, aby k hříchu přivodila tělo tvé, aniž říkej před andělem, že to jest poblouzení. Proč máš hněvati Boha řečí svou, kterýž by na zkázu přivedl dílo rukou tvých?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 7, 'Nebo kdež jest mnoho snů, tu i marnosti a slova mnohá, ale ty Boha se boj.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 8, 'Jestliže bys nátisk chudého a zadržení soudu a spravedlnosti spatřil v krajině, nediv se té věci; nebo vyšší vysokého šetří, a ještě vyšší nad nimi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 9, 'Zemský pak obchod u všech přední místo má; i král rolí slouží.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 10, 'Kdo miluje peníze, nenasytí se penězi; a kdo miluje hojnost, nebude míti užitku. I to jest marnost.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 11, 'Kde jest mnoho statku, mnoho bývá i těch, kteříž jedí jej. Jakýž tedy má užitek pán jeho? Jediné, že očima svýma hledí na něj.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 12, 'Sladký jest sen pracovitému, jez on málo neb mnoho, ale sytost bohatého nedopouští mu spáti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 13, 'Jest přebídná věc, kterouž jsem viděl pod sluncem: Bohatství nachované tomu, kdož je má, k jeho zlému.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 14, 'Nebo hyne bohatství takové pro zlou správu; syn, kteréhož zplodí, nebude míti v ruce své ničeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 15, 'Jakž vyšel z života matky své nahý, tak zase odchází, jakž přišel, aniž čeho odnáší z práce své, což by vzal v ruku svou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 16, 'A toť jest také přebídná věc, že rovně, jakž přišel, tak odjíti musí. Protož jaký užitek míti bude toho, že pracoval u vítr?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 17, 'K tomu, že po všecky dny své v temnostech jídal, s mnohým zůřením, nemocí a hněvem?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 18, 'Aj, toť jsem já spatřil, že dobrá a čistá jest věc jísti a píti a užívati pohodlí ze vší práce své, kterouž kdo vede pod sluncem v počtu dnů života svého, kteréž dal jemu Bůh, nebo to jest podíl jeho;');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 19, 'A že kterémukoli člověku dal Bůh bohatství a zboží, a dopustil, aby užíval jich, a bral díl svůj, a veselil se z práce své, to jest dar Boží.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 20, 'Nebo nebude mnoho pamatovati na dny života svého, proto že Bůh jemu přeje veselí srdce jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 6, 1, 'Jest bídná věc, kterouž jsem viděl pod sluncem, a lidem obyčejná:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 6, 2, 'Kterému člověku dal Bůh bohatství a zboží i slávu, tak že nemá nedostatku duše jeho v ničemž, čehokoli žádá, a však nedopouští mu Bůh užívati těch věcí, ale jiný leckdos sžíře to, a toť jest marnost a bídná věc.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 6, 3, 'Zplodil-li by kdo sto synů, a byl by živ mnoho let, jakkoli rozmnoženi jsou dnové let jeho, nebyl-li život jeho nasycen dobrými věcmi, a neměl by ani pohřbu, pravím, že šťastnější jest nedochůdče nežli on.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 6, 4, 'Nebo ono v zmaření přicházeje, do temností odchází, a jméno jeho temnostmi přikryto bývá.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 6, 5, 'Nýbrž ani slunce nevídá, aniž čeho poznává, a tak odpočinutí má lepší nežli onen.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 6, 6, 'A byť pak byl živ dva tisíce let, a pohodlí by neužil, zdaliž k jednomu místu všickni neodcházejí?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 6, 7, 'Všecka práce člověka jest pro ústa jeho, a však duše jeho nemůže se nasytiti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 6, 8, 'Nebo co má více moudrý nežli blázen? A co chudý, kterýž se umí chovati mezi lidmi?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 6, 9, 'Lépe jest viděti nežli žádati, ale i to jest marnost a trápení ducha.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 6, 10, 'Čímžkoli jest, dávno jest tím nazván, a známé bylo, že člověk býti měl, a že se nebude moci souditi s silnějším, nežli jest sám.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 6, 11, 'A poněvadž předsevzetí mnohá rozmnožují marnost, co na tom má člověk?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 6, 12, 'Nebo kdo ví, co by bylo dobrého člověku v tomto životě, v počtu dnů marného života jeho, kteříž pomíjejí jako stín? Aneb kdo oznámí člověku, co se díti bude po něm pod sluncem?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 1, 'Lepší jest jméno dobré nežli mast výborná, a den smrti než den narození člověka.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 2, 'Lépe jest jíti do domu zámutku, nežli jíti do domu hodování, pro dokonání každého člověka, a kdož jest živ, složí to v srdci svém.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 3, 'Lepší jest horlení nežli smích; nebo zůřivá tvář polepšuje srdce.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 4, 'Srdce moudrých v domě zámutku, ale srdce bláznů v domě veselí.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 5, 'Lépe jest slyšeti žehrání moudrého, nežli aby někdo poslouchal písně bláznů.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 6, 'Nebo jako praštění trní pod hrncem, tak smích blázna. A i to jest marnost.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 7, 'Ssužování zajisté k bláznovství přivodí moudrého, a dar oslepuje srdce.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 8, 'Lepší jest skončení věci nežli počátek její; lepší jest dlouho čekající nežli vysokomyslný.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 9, 'Nebuď kvapný v duchu svém k hněvu; nebo hněv v lůnu bláznů odpočívá.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 10, 'Neříkej: Čím jest to, že dnové první lepší byli nežli tito? Nebo bys se nemoudře na to vytazoval.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 11, 'Dobrá jest moudrost s statkem, a velmi užitečná těm, kteříž vidí slunce;');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 12, 'Nebo v stínu moudrosti a v stínu stříbra odpočívají. A však přednější jest umění moudrosti, přináší život těm, kdož ji mají.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 13, 'Hleď na skutky Boží. Nebo kdo může zpřímiti to, což on zkřivil?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 14, 'V den dobrý užívej dobrých věcí, a v den zlý buď bedliv; nebo i to naproti onomu učinil Bůh z té příčiny, aby nenalezl člověk po něm ničeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 15, 'Všecko to viděl jsem za dnů marnosti své: Bývá spravedlivý, kterýž hyne s spravedlností svou; tolikéž bývá bezbožný, kterýž dlouho živ jest v zlosti své.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 16, 'Nebývej příliš spravedlivý, aniž buď příliš moudrý. Proč máš na zkázu přicházeti?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 17, 'Nebuď příliš starostlivý, aniž bývej bláznem. Proč máš umírati dříve času svého?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 18, 'Dobréť jest, abys se onoho přídržel, a tohoto se nespouštěl; nebo kdo se bojí Boha, ujde všeho toho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 19, 'Moudrost posiluje moudrého nad desatero knížat, kteříž jsou v městě.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 20, 'Není zajisté člověka spravedlivého na zemi, kterýž by činil dobře a nehřešil.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 21, 'Také ne ke všechněm slovům, kteráž mluví lidé, přikládej mysli své, poněvadž nemáš dbáti, by i služebník tvůj zlořečil tobě.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 22, 'Neboť ví srdce tvé, že jsi i ty častokrát zlořečil jiným.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 23, 'Všeho toho zkusil jsem moudrostí, a řekl jsem: Budu moudrým, ale moudrost vzdálila se ode mne.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 24, 'Což pak vzdálené a velmi hluboké jest, kdož to najíti může?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 25, 'Všecko jsem přeběhl myslí svou, abych poznal a vyhledal, i vynalezl moudrost a rozumnost, a abych poznal bezbožnost, bláznovství a nemoudrost i nesmyslnost.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 26, 'I našel jsem věc hořčejší nad smrt, ženu, jejíž srdce tenata, a ruce její okovy. Kdož se líbí Bohu, zachován bývá od ní, ale hříšník bývá od ní jat.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 27, 'Pohleď, to jsem shledal, (praví kazatel), jedno proti druhému stavěje, abych nalezl umění,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 28, 'Čeho pak přesto hledala duše má, však jsem nenalezl: Muže jednoho z tisíce našel jsem, ale ženy mezi tolika jsem nenalezl.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 29, 'Obzvláštně pohleď i na to, což jsem nalezl: Že učinil Bůh člověka dobrého, ale oni následovali smyšlínek rozličných.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 1, 'Kdo se může vrovnati moudrému, a kdo může vykládati všelikou věc? Moudrost člověka osvěcuje oblíčej jeho, a nestydatost tváři jeho proměňuje.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 2, 'Jáť radím: Výpovědi královské ostříhej, a však podlé přísahy Boží.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 3, 'Nepospíchej odjíti od tváři jeho, aniž trvej v zpouře; nebo cožť by koli chtěl, učinil by.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 4, 'Nebo kde slovo královské, tu i moc jeho, a kdo dí jemu: Co děláš?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 5, 'Kdo ostříhá přikázaní, nezví o ničem zlém. I čas i příčiny zná srdce moudrého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 6, 'Nebo všeliké předsevzetí má čas a příčiny. Ale i to neštěstí veliké člověka se přídrží,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 7, 'Že neví, co budoucího jest. Nebo jak se stane, kdo mu oznámí?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 8, 'Není člověka, kterýž by moci měl nad životem, aby zadržel duši, aniž má moc nade dnem smrti; nemá ani braně v tom boji, aniž vysvobodí bezbožnost bezbožného.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 9, 'Ve všem tom viděl jsem, přiloživ mysl svou ke všemu tomu, co se děje pod sluncem, že časem panuje člověk nad člověkem k jeho zlému.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 10, 'A tehdáž viděl jsem bezbožné pohřbené, že se zase navrátili, ale kteříž z místa svatého odešli, v zapomenutí dáni jsou v městě tom, v kterémž dobře činili. I to také jest marnost.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 11, 'Nebo že ne i hned ortel dochází pro skutek zlý, protož vroucí jest k tomu srdce synů lidských, aby činili zlé věci.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 12, 'A ačkoli hříšník činí zle na stokrát, a vždy se mu odkládá, já však vím, že dobře bude bojícím se Boha, kteříž se bojí oblíčeje jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 13, 'S bezbožným pak nedobře se díti bude, aniž se prodlí dnové jeho; minou jako stín, proto že jest bez bázně před oblíčejem Božím.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 14, 'Jest marnost, kteráž se děje na zemi: Že bývají spravedliví, jimž se však vede, jako by činili skutky bezbožných; zase bývají bezbožní, kterýmž se však vede, jako by činili skutky spravedlivých. Protož jsem řekl: I to také jest marnost.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 15, 'A tak chválil jsem veselí, proto že nic nemá lepšího člověk pod sluncem, jediné aby jedl a pil, a veselil se, a že to pozůstává jemu z práce jeho ve dnech života jeho, kteréž dal jemu Bůh pod sluncem.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 16, 'A ač jsem se vydal srdcem svým na to, abych moudrost vystihnouti mohl, a vyrozuměti bídě, kteráž bývá na zemi, pro kterouž ani ve dne ani v noci nespí,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 17, 'A však viděl jsem při každém skutku Božím, že nemůže člověk vystihnouti skutku dějícího se pod sluncem. O čež pracuje člověk, vyhledati chtěje, ale nenalézá; nýbrž byť i myslil moudrý, že se doví, nebude moci nic najíti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 1, 'Všecko to zajisté rozvažoval jsem v srdci svém, abych vysvětlil všecko to, že spravedliví a moudří, i skutkové jejich jsou v rukou Božích. Jakož milosti, tak ani nenávisti nezná člověk ze všech věcí, kteréž jsou před oblíčejem jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 2, 'Všecko se děje jednostejně při všech; jedna a táž případnost jest spravedlivého jako bezbožného, dobrého a čistého jako nečistého, obětujícího jako toho, kterýž neobětuje, tak dobrého jako hříšníka, přisahajícího jako toho, kterýž se přísahy bojí.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 3, 'A toť jest přebídná věc mezi vším tím, což se děje pod sluncem, že případnost jednostejná jest všechněch, ovšem pak že srdce synů lidských plné jest zlého, a že bláznovství přídrží se srdce jejich, pokudž živi jsou, potom pak umírají,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 4, 'Ačkoli ten, kterýž tovaryší se všechněmi živými, má naději, an psu živému lépe jest nežli lvu mrtvému.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 5, 'Nebo živí vědí, že umříti mají, mrtví pak nevědí nic, aniž více mají odplaty, proto že v zapomenutí přišla památka jejich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 6, 'Anobrž i milování jejich, i nenávist jejich, i závist jejich zahynula, a již více nemají dílu na věky v žádné věci, kteráž se děje pod sluncem.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 7, 'Nuže tedy jez s radostí chléb svůj, a pí s veselou myslí víno své, nebo již oblibuje Bůh skutky tvé.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 8, 'Každého času ať jest roucho tvé bílé, a oleje na hlavě tvé nechť není nedostatku.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 9, 'Živ buď s manželkou, kterouž jsi zamiloval, po všecky dny života marnosti své, kterýžť dán pod sluncem po všecky dny marnosti tvé; nebo to jest podíl tvůj v životě tomto a při práci tvé, kterouž vedeš pod sluncem.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 10, 'Všecko, což by před se vzala ruka tvá k činění, podlé možnosti své konej; nebo není práce ani důmyslu ani umění ani moudrosti v hrobě, do něhož se béřeš.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 11, 'A obrátiv se, spatřil jsem pod sluncem, že ne záleží běh na rychlých, ani boj na udatných, nýbrž ani živnost na moudrých, ani bohatství na opatrných, ani přízeň na umělých, ale podlé času a příhody přihází se všechněm.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 12, 'Nebo tak nezná člověk času svého jako ryby, kteréž loveny bývají sítí škodlivou, a jako ptáci polapeni bývají osídlem; tak zlapáni bývají synové lidští v čas zlý, když na ně připadá v náhle.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 13, 'Také i tuto moudrost viděl jsem pod sluncem, kteráž za velikou byla u mne:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 14, 'Bylo město malé, a v něm lidí málo, k němuž přitáhl král mocný, a obehnav je, zdělal proti němu náspy veliké.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 15, 'I nalezen jest v něm muž chudý moudrý, kterýž vysvobodil to město moudrostí svou, ačkoli žádný nevzpomenul na muže toho chudého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 16, 'Protož řekl jsem já: Lepší jest moudrost než síla, ačkoli moudrost chudého toho byla v pohrdání, a slov jeho neposlouchali.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 17, 'Slov moudrých pokojně poslouchati sluší, raději než křiku panujícího mezi blázny.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 18, 'Lepší jest moudrost než nástrojové váleční, ale nemoudrý jeden kazí mnoho dobrého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 1, 'Muchy mrtvé nasmrazují a nakažují mast apatekářskou; tak pro moudrost a slávu vzácného maličko bláznovství zohyžďuje.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 2, 'Srdce moudrého jest po pravici jeho, ale srdce blázna po levici jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 3, 'I tehdáž, když blázen cestou jde, srdce jeho nedostatek trpí; nebo všechněm znáti dává, že blázen jest.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 4, 'Jestliže by duch toho, jenž panuje, povstal proti tobě, neopouštěj místa svého; nebo krotkost přítrž činí hříchům velikým.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 5, 'Jest zlá věc, kterouž jsem viděl pod sluncem, totiž neprozřetelnost, kteráž pochází od vrchnosti,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 6, 'Že blázen postaven bývá v důstojnosti veliké, a bohatí že v nízkosti sedávají.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 7, 'Viděl jsem služebníky na koních, knížata pak, ana chodí pěšky jako služebníci.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 8, 'Kdo kopá jámu, upadá do ní; a kdo boří plot, ušťkne jej had.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 9, 'Kdo přenáší kamení, urazí se jím; a kdo štípá dříví, nebezpečenství bude míti od něho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 10, 'Jestliže se ztupí železo, a nenabrousí-li ostří jeho, tedy síly přičiniti musí; ale mnohem lépe může to spraviti moudrost.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 11, 'Ušťkne-li had, než by zaklet byl, nic neprospějí slova zaklinače.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 12, 'Slova úst moudrého jsou příjemná, ale rtové blázna sehlcují jej.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 13, 'Počátek slov úst jeho jest nemoudrost, a ostatek mluvení jeho pouhé bláznovství.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 14, 'Nebo blázen mnoho mluví, ješto neví člověk ten, co budoucího jest. To zajisté, co bude po něm, kdo mu oznámí?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 15, 'Práce bláznů k ustání je přivodí, nebo neumí ani do města trefiti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 16, 'Běda tobě, země, když král tvůj dítě jest, a knížata tvá ráno hodují.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 17, 'Blahoslavená jsi ty země, když král tvůj jest syn šlechetných, a knížata tvá, když čas jest, jídají pro posilnění, a ne pro opilství.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 18, 'Ano pro lenost schází krov, a pro opuštění rukou kapává do domu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 19, 'Pro obveselení strojívají hody, a víno obveseluje život, peníze pak ke všemu dopomáhají.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 20, 'Ani sám u sebe králi nezlořeč, ani v skrýších pokoje svého nezlořeč mocnějšímu; nebo pták nebeský donesl by hlas ten, a to, což křídla má, vyjevilo by řeč tvou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 11, 1, 'Pouštěj chléb svůj po vodě, nebo po mnohých dnech najdeš jej.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 11, 2, 'Dej částku sedmi aneb i osmi, nebo nevíš, co zlého bude na zemi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 11, 3, 'Když se naplňují oblakové, déšť na zem vydávají; a když padá dřevo na poledne aneb na půlnoci, na kteréž místo padá to dřevo, tu zůstává.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 11, 4, 'Kdo šetří větru, nebude síti; a kdo hledí na husté oblaky, nebude žíti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 11, 5, 'Jakož ty nevíš, která jest cesta větru, a jak rostou kosti v životě těhotné, tak neznáš díla Božího, kterýž činí všecko.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 11, 6, 'Hned z jitra rozsívej símě své, a u večer nedávej odpočinutí ruce své; nebo ty nevíš, co jest lepšího, to-li či ono, čili obé jednostejně dobré jest.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 11, 7, 'Příjemnéť jest zajisté světlo, a milá věc očima viděti slunce;');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 11, 8, 'A však, by mnoho let živ jsa člověk, ve všech těch veselil by se, tedy rozpomenul-li by se na dny temnosti, jak jich mnoho bude, cožkoli přeběhlo, počte za marnost.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 11, 9, 'Radujž se tedy, mládenče, v mladosti své, a nechť tě obveseluje srdce tvé ve dnech mladosti tvé, a choď po cestách srdce svého, a podlé žádosti očí svých, než věz, že tě s tím se vším přivede Bůh na soud.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 11, 10, 'Anobrž odejmi hněv od srdce svého, a odvrať zlost od těla svého; nebo dětinství a mladost jest marnost.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 12, 1, 'A pamatuj na stvořitele svého ve dnech mladosti své, prvé než nastanou dnové zlí, a přiblíží se léta, o nichž díš: Nemám v nich zalíbení;');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 12, 2, 'Prvé než se zatmí slunce a světlo, a měsíc i hvězdy, a navrátí se hustí oblakové po dešti;');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 12, 3, 'V ten den, v kterémž se třísti budou strážní domu, a nakřiví se muži silní, a ustanou melící, proto že jich málo bude, a zatmí se ti, kteříž vyhlédají z oken,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 12, 4, 'A zavříny budou dvéře od ulice s slabým zvukem mlení, a povstanou k hlasu ptačímu, a přestanou všecky slibnosti zpěvu;');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 12, 5, 'Ano i vysokosti báti se budou, a úrazu na cestě, a kvésti bude mandlový strom, tak že i kobylka těžká bude, a poruší se žádost; nebo béře se člověk do domu věčného, a choditi budou po ulici kvílící;');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 12, 6, 'Prvé než se přetrhne provaz stříbrný, a než se rozrazí číše zlatá, a roztříští se věderce nad vrchovištěm, a roztrhne se kolo nad studnicí,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 12, 7, 'A navrátí se prach do země, jakž prvé byl, duch pak navrátí se k Bohu, kterýž jej dal.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 12, 8, 'Marnost nad marnostmi, řekl kazatel, a všecko marnost.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 12, 9, 'Čím pak byl kazatel moudřejší, tím více vyučoval lid umění, a rozvažoval, zpytoval, i složil množství přísloví.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 12, 10, 'Snažovaltě se kazatel vyhledati věci nejžádostivější, a napsal, což pravého jest, a slova věrná.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 12, 11, 'Slova moudrých podobná ostnům a hřebíkům vbitým, slova skladatelů, kteráž jsou vydána od pastýře jednoho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 12, 12, 'A tak tedy jimi, synu můj, hojně dosti osvícen býti můžeš. Dělání knih mnohých žádného konce není, a čísti mnoho jest zemdlení těla.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 12, 13, 'Summa všeho, což jsi slyšel: Boha se boj, a přikázaní jeho ostříhej, nebo na tom všecko člověku záleží.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 12, 14, 'Poněvadž všeliký skutek Bůh přivede na soud, i každou věc tajnou, buďto dobrou, buďto zlou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 1, 'Píseň nejpřednější z písní Šalomounových.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 2, 'Ó by mne políbil políbením úst svých; nebo lepší jsou milosti tvé nežli víno.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 3, 'Pro vůni masti tvé jsou výborné, mast rozlitá jméno tvé; protož tě mladice milují.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 4, 'Táhniž mne, a poběhnem za tebou. Uvedltě mne král do pokojů svých, plésati a veseliti se v tobě budeme, a vychvalovati milosti tvé více než víno; upřímí milují tě.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 5, 'Jsemť černá, ale milostná, ó dcery Jeruzalémské, tak jako stanové Cedarští, jako opony Šalomounovy.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 6, 'Nehleďte na mne, žeť jsem snědá, nebo jsem obhořela od slunce. Synové matky mé rozpálivše se proti mně, postavili mne, abych ostříhala vinic, a vinice své nehlídala jsem.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 7, 'Oznam mi ty, kteréhož miluje duše má, kde paseš? Kde dáváš odpočinutí o poledni? Nebo proč mám býti tak jako poběhlá při stádích tovaryšů tvých?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 8, 'Jestliže nevíš, ó nejkrašší mezi ženami, vyjdi po šlepějích ovcí, a pas kozlátka svá podlé obydlí pastýřů.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 9, 'Jízdě v vozích Faraonových připodobňuji tě, ó milostnice má.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 10, 'Líce tvá okrášlena jsou ozdobami, a hrdlo tvé halžemi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 11, 'Ozdob zlatých naděláme tobě s proměnami stříbrnými.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 12, 'Dotud, dokudž král stolí, nardus můj vydává vůni svou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 13, 'Svazček mirry jest mi milý můj, na prsech mých odpočívaje.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 14, 'Milý můj jest mi hrozen cyprový na vinicích v Engadi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 15, 'Aj, jak jsi ty krásná, přítelkyně má, aj, jak jsi krásná! Oči tvé jako holubičí.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 16, 'Aj, jak jsi ty krásný, milý můj, jak utěšený! I to lůže naše zelená se.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 17, 'Trámové domů našich jsou z cedrů, a pavlače naše z boroví.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 1, 'Já jsem růže Sáronská, a lilium při dolinách.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 2, 'Jako lilium mezi trním, tak přítelkyně má mezi pannami.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 3, 'Jako jabloň mezi dřívím lesním, tak milý můj mezi mládenci. V stínu jeho žádostiva jsem byla seděti, a sedímť; nebo ovoce jeho sladké jest ústům mým.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 4, 'Uvedl mne na hody, maje za korouhev lásku ke mně.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 5, 'Očerstvětež mne těmi flašemi, posilňte mne těmi jablky, nebo umdlévám milostí,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 6, 'Levice jeho pod hlavou mou, a pravicí svou objímá mne.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 7, 'Zavazujiť vás přísahou, dcery Jeruzalémské, skrze srny a laně polní, abyste nebudily a nevyrážely ze sna milého mého, dokudž by nechtěl.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 8, 'Hlas milého mého, aj, onť se béře, skáče po těch horách, poskakuje na těch pahrbcích.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 9, 'Podobný jest milý můj srně aneb mladému jelenu; aj, on stojí za stěnou naší, vyhlédá z oken, patří skrze mříži.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 10, 'Ozval se milý můj, a řekl mi: Vstaň, přítelkyně má, krásná má, a poď.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 11, 'Nebo aj, zima pominula, prška přestala a odešla.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 12, 'Kvítíčko se ukazuje po zemi, čas prozpěvování přišel, a hlas hrdličky slyší se v krajině naší.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 13, 'Fík vypustil holičky své, a réví rozkvetlé vydalo vůni. Vstaniž, přítelkyně má, krásná má, a poď.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 14, 'Holubičko má, v rozsedlinách skalních, v skrýši příkré, ukaž mi oblíčej svůj, nechať slyším hlas tvůj; nebo hlas tvůj libý jest, a oblíčej tvůj žádostivý.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 15, 'Zlapejte nám lišky, lišky maličké, ješto škodu dělají na vinicích, poněvadž vinice naše kvete.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 16, 'Milý můj jest můj, a já jeho, jenž pase mezi lilium.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 17, 'Ažby zavítal ten den, a utekli by stínové ti, navratiž se, připodobni se, milý můj, srně neb mladému jelenu na horách Beter.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 3, 1, 'Na ložci svém v noci hledala jsem toho, kteréhož miluje duše má. Hledala jsem ho, ale nenašla jsem ho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 3, 2, 'Již tedy vstanu, a zchodím město; po ryncích i po ulicech hledati budu toho, kteréhož miluje duše má. Hledala jsem ho, ale nenašla jsem ho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 3, 3, 'Našli mne ponocní, kteříž chodí po městě. Viděli-liž jste toho, kteréhož miluje duše má?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 3, 4, 'A jakž jsem jich jen pominula, takž jsem našla toho, kteréhož miluje duše má. Chopila jsem ho, aniž ho pustím, až ho uvedu do domu matky své, a do pokojíka rodičky své.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 3, 5, 'Přísahou vás zavazuji, dcery Jeruzalémské, skrze srny a laně polní, abyste nebudily a nevyrážely ze sna milého mého, dokudž by sám nechtěl.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 3, 6, 'Která jest to, jenž vstupuje z pouště jako sloupové dymu, okouřena jsuc mirrou a kadidlem, dražším nad všelijaký prach apatekářský?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 3, 7, 'Aj, lože Šalomounovo, okolo něhož šedesáte udatných z nejsilnějších Izraelských,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 3, 8, 'Vše vládnoucích mečem, vycvičených v boji, z nichž jeden každý má svůj meč při boku svém z příčiny strachu nočního.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 3, 9, 'Schranu vystavěl sobě král Šalomoun z dříví Libánského,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 3, 10, 'Při níž udělal sloupy stříbrné, dno zlaté a ponebí šarlatové, vnitřek pak jeho postlaný milostí dcer Jeruzalémských.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 3, 11, 'Vyjděte a pohleďte, dcery Sionské, na krále Šalomouna v koruně, kterouž ho korunovala matka jeho v den oddávání jeho a v den veselí srdce jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 1, 'Aj, jak jsi ty krásná, přítelkyně má, aj, jak jsi krásná! Oči tvé jako holubičí mezi kadeři tvými, vlasy tvé jako stáda koz, kteréž vídati na hoře Galád.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 2, 'Zubové tvoji podobní stádu ovcí jednostejných, když vycházejí z kupadla, z nichž každá mívá po dvém, a mezi nimiž není žádné neplodné.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 3, 'Jako provázek z hedbáví červeného dvakrát barveného rtové tvoji, a řeč tvá ozdobná; jako kus jablka zrnatého židoviny tvé mezi kadeři tvými.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 4, 'Hrdlo tvé jest jako věže Davidova, vystavená k chování zbroje, v níž na tisíce pavéz visí, vše štítů mužů udatných.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 5, 'Oba tvé prsy jako dvé telátek bliženců srních, jenž se pasou v kvítí.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 6, 'Ažby zavítal ten den, a utekli by stínové, poodejdu k hoře mirrové a pahrbku kadidlovému.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 7, 'Všecka jsi krásná, přítelkyně má, a není na tobě poškvrny.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 8, 'Se mnou z Libánu, ó choti má, se mnou z Libánu půjdeš, a pohledíš s vrchu hory Amana, s vrchu Senir a Hermon, z peleší lvových a s hor pardových.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 9, 'Jala jsi srdce mé, sestro má choti, jala jsi srdce mé jedním okem svým, a jedinou točenicí hrdla svého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 10, 'Jak utěšené jsou milosti tvé, sestro má choti! Jak vzácnější jsou milosti tvé než víno, a vůně mastí tvých nade všecky vonné věci.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 11, 'Strdí tekou rtové tvoji, ó choti, med a mléko pod jazykem tvým, a vůně roucha tvého jako vůně Libánu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 12, 'Zahrada zamčená jsi, sestro má choti, vrchoviště zamčené, studnice zapečetěná.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 13, 'Výstřelkové tvoji jsou zahrada stromů jablek zrnatých s ovocem rozkošným cypru a nardu,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 14, 'Nardu s šafránem, prustvorce s skořicí, a s každým stromovím kadidlo vydávajícím, mirry a aloes, i s všelijakými zvláštními věcmi vonnými.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 15, 'Ó ty sám vrchoviště zahradní, studnice vod živých, a tekoucích z Libánu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 16, 'Věj, větříčku půlnoční, a přiď, větříčku polední, prověj zahradu mou, ať tekou vonné věci její, a ať přijde milý můj do zahrady své, a jí rozkošné ovoce své.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 1, 'Přišelť jsem do zahrady své, sestro má choti, sbírám mirru svou i vonné věci své, jím plást svůj i med svůj, pijí víno své a mléko své. Jezte, přátelé, píte a hojně se napíte, moji milí.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 2, 'Spávámť, a však srdce mé bdí. Hlas milého mého, tlukoucího: Otevři mi, sestro má, přítelkyně má, holubičko má, upřímá má; nebo hlava má plná jest rosy, a kadeře mé krůpějí nočních.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 3, 'Svlékla jsem sukni svou, kterakž ji obleku? Umyla jsem nohy své, což je mám káleti?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 4, 'Milý můj sáhl rukou svou skrze dvéře, a vnitřnosti mé pohnuly se ve mně.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 5, 'I vstala jsem, abych otevřela milému svému, a aj, z rukou mých kapala mirra, i z prstů mých, mirra tekutá na rukovětech závory.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 6, 'Otevřelať jsem byla milému svému, ale milý můj již byl ušel, a pominul. Duše má byla vyšla, když on promluvil. Hledala jsem ho, ale nenašla jsem ho; volala jsem ho, ale neozval se mi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 7, 'Nalezše mne strážní, kteříž chodí po městě, zbili mne, ranili mne, vzali i rouchu mou se mne strážní zdí městských.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 8, 'Zavazuji vás přísahou dcery Jeruzalémské, jestliže byste našly milého mého, co jemu povíte? Že jsem nemocná milostí.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 9, 'Což má milý tvůj mimo jiné milé, ó nejkrásnější z žen? Co má milý tvůj nad jiné milé, že nás tak přísahou zavazuješ?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 10, 'Milý můj jest bílý a červený, znamenitější nežli deset tisíců jiných.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 11, 'Hlava jeho jako ryzí zlato, vlasy jeho kadeřavé, černé jako havran.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 12, 'Oči jeho jako holubic nad stoky vod, jako v mléce umyté, stojící v slušnosti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 13, 'Líce jeho jako záhonkové vonných věcí, jako květové vonných věcí; rtové jeho jako lilium prýštící mirru tekutou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 14, 'Ruce jeho prstenové zlatí, vysazení kamením drahým jako postavcem modrým; břicho jeho stkvělost slonové kosti zafiry obložené.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 15, 'Hnátové jeho sloupové mramoroví, na podstavcích zlata nejčistšího založení; oblíčej jeho jako Libán, výborný jako cedrové.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 16, 'Ústa jeho přesladká, a všecken jest přežádostivý. Takovýť jest milý můj, takový jest přítel můj, ó dcery Jeruzalémské.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 6, 1, 'Kamže odšel milý tvůj, ó nejkrásnější z žen? Kam se obrátil milý tvůj? A hledati ho budeme s tebou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 6, 2, 'Milý můj sstoupil do zahrady své, k záhonkům věci vonných, aby pásl v zahradách, a aby zbíral lilium.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 6, 3, 'Já jsem milého mého, a milý můj jest můj, kterýž pase mezi lilium.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 6, 4, 'Krásná jsi, přítelkyně má, jako Tersa, pěkná jako Jeruzalém, hrozná jako vojsko s praporci.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 6, 5, 'Odvrať oči své od patření na mne, nebo ony mne posilují. Vlasy tvé jsou jako stáda koz, kteréž vídati v Galád.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 6, 6, 'Zubové tvoji jsou podobní stádu ovcí, když vycházejí z kupadla, z nichž každá mívá po dvém, a mezi nimiž není žádné neplodné.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 6, 7, 'Jako kus jablka zrnatého židoviny tvé mezi kadeři tvými.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 6, 8, 'Šedesáte jest královen, a osmdesáte ženin, a mladic bez počtu;');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 6, 9, 'Jediná jest však má holubice, má upřímá, jedinká při matce své, nepoškvrněná při své rodičce. Spatřivše ji dcery, blahoslavily ji, královny a ženiny chválily ji, řkouce:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 6, 10, 'Která jest to, kterouž viděti jako dennici, krásná jako měsíc, čistá jako slunce, hrozná jako vojsko s praporci?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 6, 11, 'Do zahrady vypravené sstoupila jsem, abych spatřila ovoce údolí, abych viděla, kvete-li vinný kmen, a pučí-li se jabloně zrnaté.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 6, 12, 'Nezvěděla jsem, a žádost má ponukla mne na vůz přednějších z lidu mého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 6, 13, 'Navrať se, navrať, ó Sulamitská, navrať se, navrať, ať na tě patříme. Co uzříte na Sulamitské? Jako zástup vojenský.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 7, 1, 'Jak jsou krásné nohy tvé v střevících, dcero knížecí! Okolek bedr tvých jako zápony, dílo ruku výborného řemeslníka.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 7, 2, 'Pupek tvůj koflík okrouhlý, ne bez nápoje; břicho tvé jako stoh pšenice obrostlý kvítím.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 7, 3, 'Oba tvé prsy jako dvé telátek bliženců srních.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 7, 4, 'Hrdlo tvé jako věže z kostí slonových, oči tvé rybníci v Ezebon podlé brány Batrabbim, nos tvůj věže Libánská patřící k Damašku.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 7, 5, 'Hlava tvá na tobě jako Karmel, a vlasy hlavy tvé jako šarlat; i král přivázán by byl na pavlačích.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 7, 6, 'Jak jsi ty krásná, a jak utěšená, ó milosti přerozkošná!');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 7, 7, 'Ta postava tvá podobna jest palmě, a prsy tvé hroznům.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 7, 8, 'Řekl jsem: Vstoupím na palmu, dosáhnu vrchů jejích. Nechažť tedy jsou prsy tvé jako hroznové vinného kmene, a vůně chřípí tvých jako jablek vonných.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 7, 9, 'Ústa tvá jako víno výborné, milá pro upřímnost, působící, aby i těch, jenž spí, rtové mluvili.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 7, 10, 'Já jsem milého svého, a ke mně jest žádost jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 7, 11, 'Poď, milý můj, vyjděme na pole, přenocujme ve vsech.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 7, 12, 'Ráno přivstaneme, na vinice pohledíme, kvete-li vinný kmen, již-li se ukázal začátek hroznů, kvetou-li jablka zrnatá, a tuť dám tobě milosti své.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 7, 13, 'Pěkná jablečka vydala vůni, a na dveřech našich všecky rozkoše nové i staré, milý můj, zachovala jsem tobě.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 8, 1, 'Ó bys byl jako bratr můj požívající prsí matky mé, abych tě naleznuc vně, políbila, a nebyla zahanbena.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 8, 2, 'Vedla bych tě, a uvedla do domu matky své, a tu bys mne vyučoval; a jáť bych dala píti vína strojeného, a mstu z jablek zrnatých.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 8, 3, 'Levice jeho pod hlavou mou, a pravicí svou objímá mne.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 8, 4, 'Přísahou vás zavazuji, dcery Jeruzalémské, abyste nebudily a nevyrážely ze sna milého mého, dokudž by sám nechtěl.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 8, 5, 'Která jest to, jenž vstupuje z pouště, zpolehši na milého svého? Pod jabloní vzbudila jsem tě; tuť tebe počala matka tvá, tuť tě počala rodička tvá.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 8, 6, 'Položiž mne jako pečet na srdce své, jako pečetní prsten na ruku svou. Nebo silné jest jako smrt milování, tvrdá jako hrob horlivost; uhlí její uhlí řeřavé, plamen nejprudší.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 8, 7, 'Vody mnohé nemohly by uhasiti tohoto milování, aniž ho řeky zatopí. Kdyby někdo dáti chtěl všecken statek domu svého za takovou milost, se vším tím pohrdnut by byl.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 8, 8, 'Sestru máme maličkou, kteráž ještě nemá prsí. Co učiníme s sestrou svou v den, v kterýž bude řeč o ní?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 8, 9, 'Jestliže jest zed, vzděláme na ní palác stříbrný; pakli jest dveřmi, obložíme je dskami cedrovými.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 8, 10, 'Já jsem zed, a prsy mé jako věže; takž jsem byla před očima jeho, jako nacházející pokoj.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 8, 11, 'Vinici měl Šalomoun v Balhamon, kteroužto pronajal strážným, aby jeden každý přinášel za ovoce její tisíc stříbrných.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 8, 12, 'Ale vinice má, kterouž mám, přede mnou jest. Mějž sobě ten tisíc, ó Šalomoune, a dvě stě ti, kteříž ostříhají ovoce jejího.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 8, 13, 'Ó ty, kteráž bydlíš v zahradách, přáteléť pozorují hlasu tvého, ohlašujž mi se.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 8, 14, 'Pospěš, milý můj, a připodobni se k srně nebo mladému jelenu, na horách vonných věcí.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 1, 'Vidění Izaiáše syna Amosova, kteréž viděl o Judovi a Jeruzalému, za dnů Uziáše, Jotama, Achasa a Ezechiáše, králů Judských.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 2, 'Slyšte nebesa, a ušima pozoruj země, nebo Hospodin mluví: Syny jsem vychoval a vyvýšil, oni pak strhli se mne.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 3, 'Vůl zná hospodáře svého, a osel jesle pánů svých; Izrael nezná, lid můj nesrozumívá.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 4, 'Ach, národe hříšný, lide obtížený nepravostí, símě zlostníků, synové nešlechetní, opustili Hospodina, pohrdli svatým Izraelským, odvrátili se zpět.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 5, 'Proč, čím více biti býváte, tím více se odvracujete? Všecka hlava jest neduživá, a všecko srdce zemdlené.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 6, 'Od zpodku nohy až do vrchu hlavy není na něm místa celého, jen rána a zsinalost, a zbití zahnojené, aniž se vytlačuje, ani uvazuje, ani olejem změkčuje.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 7, 'Země vaše spustla, města vaše vypálena ohněm; zemi vaši před vámi cizozemci zžírají, a v poušť obracejí, tak jakž vše kazí cizozemci.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 8, 'I zůstala dcera Sionská jako boudka na vinici, jako chaloupka v zahradě tykevné, a jako město zkažené.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 9, 'Byť nám byl Hospodin zástupů jakkoli malička ostatků nezanechal, byli bychom jako Sodoma, byli bychom Gomoře podobni.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 10, 'Slyšte slovo Hospodinovo, knížata Sodomská, ušima pozorujte zákona Boha našeho, lide Gomorský:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 11, 'K čemu jest mi množství obětí vašich? dí Hospodin. Syt jsem zápalných obětí skopců a tuků krmných hovad, a krve volků a beránků a kozlů nejsem žádostiv.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 12, 'Že přicházíte, abyste se ukazovali přede mnou, kdož toho z ruky vaší hledal, abyste šlapali síně mé?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 13, 'Nepřinášejte více oběti oklamání. Kadění v ohavnosti mám, novměsíců a sobot a svolávání nemohu trpěti, (nepravost jest), ani shromáždění.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 14, 'Novměsíců vašich a slavností vašich nenávidí duše má; jsou mi břemenem, ustal jsem, nesa je.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 15, 'Protož, když rozprostíráte ruce vaše, skrývám oči své před vámi, a když množíte modlitbu, neslyším; ruce vaše krve plné jsou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 16, 'Umejte se, očisťte se, odvrzte zlost skutků vašich od očí mých, přestaňte zle činiti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 17, 'Učte se dobře činiti, hledejte soudu, pozdvihněte potlačeného, dopomozte k spravedlnosti sirotku, zastaňte vdovy.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 18, 'Poďtež nu, a poukažme sobě, praví Hospodin: Budou-li hříchové vaši jako červec dvakrát barvený, jako sníh zbělejí; budou-li červení jako šarlat, jako vlna budou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 19, 'Budete-li povolní a poslušní, dobré věci země jísti budete.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 20, 'Pakli nebudete povolní, ale zpurní, od meče sežráni budete; nebo ústa Hospodinova mluvila.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 21, 'Jak tě nevěstkou učiněno to město věrné, plné soudu! Spravedlnost přebývala v něm, nyní pak vražedlníci.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 22, 'Stříbro tvé obrátilo se v trůsky, víno tvé smíšeno s vodou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 23, 'Knížata tvá zpurná a tovaryši zlodějů, jeden každý z nich miluje dary, a dychtí po úplatcích; sirotku k spravedlnosti nedopomáhají, a pře vdovy před ně nepřichází.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 24, 'Protož dí Pán, Hospodin zástupů, silný Izraelský: Aj, jáť se potěším nad protivníky svými, a vymstím se nad nepřátely svými,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 25, 'Když zase obrátím ruku svou na tě, až přepálím dočista trůsky tvé, a odejmu všecken cín tvůj,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 26, 'A obnovím soudce tvé tak jako na počátku, a rádce tvé jako s prvu. A tu potom slouti budeš městem spravedlnosti, městem věrným.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 27, 'Sion v soudu vykoupen bude, a kteříž zase uvedeni budou do něho, v spravedlnosti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 28, 'Setření pak přestupníků a nešlechetných v náhle přijde, a kteříž opouštějí Hospodina, docela zahynou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 29, 'Nebo zahanbeni budete pro háje, po nichž jste toužili, a zastydíte se pro zahrady, kteréž jste sobě zvolili.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 30, 'Budete zajisté jako dub, s něhož lístí prší, a jako zahrada, v níž vody není.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 31, 'I bude nejsilnější jako koudel, a učinitel jeho jako jiskra; i bude to obé hořeti spolu, a nebude žádného, ješto by uhasiti mohl.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 1, 'Slovo, kteréž viděl Izaiáš syn Amosův o Judovi a Jeruzalému.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 2, 'I stane se v posledních dnech, že utvrzena bude hora domu Hospodinova na vrchu hor, a vyvýšena nad pahrbky, i pohrnou se k ní všickni národové.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 3, 'A půjdou lidé mnozí, říkajíce: Poďte, a vstupme na horu Hospodinovu, do domu Boha Jákobova, a bude nás vyučovati cestám svým, i budeme choditi po stezkách jeho. Nebo z Siona vyjde zákon, a slovo Hospodinovo z Jeruzaléma.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 4, 'Onť bude souditi mezi národy, a trestati bude lidi mnohé. I zkují meče své v motyky, a oštípy své v srpy. Nepozdvihne národ proti národu meče, a nebudou se více učiti boji.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 5, 'Dome Jákobův, poďtež, a choďme v světle Hospodinově.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 6, 'Ale ty jsi opustil lid svůj, dům Jákobův, proto že jsou naplněni ohavnostmi národů východních, a jsou pověrní jako Filistinští, a smyšlínky cizozemců že sobě libují.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 7, 'K tomu naplněna jest země jejich stříbrem a zlatem, tak že není konce pokladům jejich; naplněna jest země jejich i koňmi, vozům pak jejich počtu není.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 8, 'Naplněna jest také země jejich modlami; klanějí se dílu rukou svých, kteréž učinili prstové jejich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 9, 'Klaní se obecný člověk, a ponižuje se i přední muž; protož neodpouštěj jim.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 10, 'Vejdi do skály, a skrej se v prachu před hrůzou Hospodinovou, před slávou důstojnosti jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 11, 'Tuť oči vysoké člověka sníženy budou, a skloněna bude vysokost lidská, ale Hospodin sám vyvýšen bude v ten den.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 12, 'Nebo den Hospodina zástupů se blíží na každého pyšného a zpínajícího se, i na každého vyvýšeného, i bude ponížen,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 13, 'I na všecky cedry Libánské vysoké a vyvýšené, i na všecky duby Bázanské,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 14, 'I na všecky hory vysoké, i na všecky pahrbky vyvýšené,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 15, 'I na všelikou věži vysokou, i na všelikou zed pevnou,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 16, 'I na všecky lodí mořské, i na všecka malování slibná.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 17, 'A sehnuta bude pýcha člověka, a snížena bude vysokost lidská, ale vyvýšen bude Hospodin sám v ten den,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 18, 'Modly pak docela vymizejí.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 19, 'Tehdy půjdou do jeskyní skal a do roklí země, před hrůzou Hospodinovou a slávou důstojnosti jeho, když povstane, aby potřel zemi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 20, 'V ten den zavrže člověk modly své stříbrné a modly své zlaté, kterýchž mu nadělali, aby se klaněl, totiž krtům a netopýřům.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 21, 'I vejde do slují skal a do vysedlin jejich před hrůzou Hospodinovou, a před slávou důstojnosti jeho, když povstane, aby potřel zemi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 22, 'Přestaňtež doufati v člověku, jehož dýchání v chřípích jeho jest. Nebo zač má jmín býti?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 1, 'Nebo aj, Pán, Hospodin zástupů, odejme od Jeruzaléma a Judy hůl a podporu, všelijakou hůl chleba a všelikou podporu vody,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 2, 'Silného i muže válečného, soudce i proroka, mudrce i starce,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 3, 'Padesátníka i počestného, i rádci, i vtipného řemeslníka, i výmluvného,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 4, 'A dám jim děti za knížata; děti, pravím, panovati budou nad nimi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 5, 'I bude ssužovati v lidu jeden druhého, a bližní bližního svého; zpurně se postaví dítě proti starci, a chaterný proti vzácnému.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 6, 'Pročež se chopí jeden každý bratra svého z domu otce svého, a dí: Máš oděv, knížetem naším budeš, a pád tento zdrž rukou svou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 7, 'Ale on přisáhne v ten den, řka: Nebuduť vázati těch ran, nebo v domě mém není chleba ani oděvu; neustanovujtež mne knížetem lidu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 8, 'Nebo se obořil Jeruzalém, a Juda padl, proto že jazyk jejich a skutkové jejich jsou proti Hospodinu, k dráždění očí slávy jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 9, 'Nestydatost tváři jejich svědčí proti nim; hřích zajisté svůj jako Sodomští ohlašují, a netají. Běda duši jejich, nebo sami na sebe uvodí zlé.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 10, 'Rcete spravedlivému: Dobře bude; nebo ovoce skutků svých jísti bude.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 11, 'Ale běda bezbožnému, zle bude; nebo odplata rukou jeho dána jemu bude.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 12, 'Lidu mého knížata jsou děti, a ženy panují nad ním. Lide můj, kteříž tě vodí, svodí tě, a cestu stezek tvých ukrývají.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 13, 'Stojíť Hospodin k rozsudku, stojí, pravím, k rozsudku s lidmi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 14, 'Hospodin k soudu přijde proti starším lidu svého a knížatům jejich, a dí: Vy jste pohubili vinici mou, loupež chudého jest v domích vašich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 15, 'Proč vy nuzíte lid můj, a tváře chudých zahanbujete? praví Pán, Hospodin zástupů.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 16, 'I dí Hospodin: Proto že se pozdvihují dcery Sionské, a chodí s vytaženým krkem, a pasou očima, protulujíce se, a zdrobna kráčejíce, i nohama svýma lákají,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 17, 'Protož okydne Pán prašivinou vrch hlavy dcer Sionských, a Hospodin hanbu jejich obnaží.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 18, 'V ten den odejme Pán okrasu těch nástrah, totiž poučníky a halže,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 19, 'Jablka zlatá a spinadla a čepce,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 20, 'Biréty a zápony, tkanice, punty a náušnice,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 21, 'Prsteny a náčelníky,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 22, 'Proměnná roucha, i plášťky, i roušky, i vačky,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 23, 'I zrcadla, i čechlíky, i věnce, i šlojíře.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 24, 'A budeť místo vonných věcí hnis, a místo pasů roztržení, a místo strojení kadeří lysina, a místo širokého podolku bude přepásání pytlem, obhoření pak místo krásy.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 25, 'Muži tvoji od meče padnou, a silní tvoji v boji.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 26, 'I budou plakati a kvíliti brány jeho, a spustlý na zemi seděti bude.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 4, 1, 'I chopí se sedm žen muže jednoho v ten den, a řeknou: Chléb svůj jísti budeme, a rouchem svým se odívati, toliko ať po tobě se jmenujeme; odejmi pohanění naše.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 4, 2, 'V ten den bude výstřelek Hospodinův ušlechtilý a slavný, a plod země výtečný a krásný, totiž ti, kteříž zachováni budou z Izraele.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 4, 3, 'I stane se, že kdož bude zanechán na Sionu, a pozůstaven bude v Jeruzalémě, svatý slouti bude, každý, kdož jest zapsán k životu v Jeruzalémě,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 4, 4, 'Když Pán smyje nečistotu dcer Sionských, a krev Jeruzaléma vyplákne z něho v duchu soudu a v duchu horlivosti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 4, 5, 'A stvoří Hospodin nad každým obydlím hory Sion, a nad každým shromážděním jejím oblak ve dne, a dým a blesk plápolajícího ohně v noci; nebo nad všecku slávu bude zastření.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 4, 6, 'A bude stánkem k zastěňování ve dne před horkem, a za útočiště a skrýši před přívalem a deštěm.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 1, 'Zpívati již budu milému svému píseň milého svého o vinici jeho: Vinici má milý můj na vrchu úrodném.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 2, 'Kterouž ohradil, a kamení z ní vybral, a vysadil ji vinným kmenem výborným, a ustavěl věži u prostřed ní, také i pres udělal v ní, a očekával, aby nesla hrozny, ale vydala plané víno.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 3, 'Nyní tedy, obyvatelé Jeruzalémští a muži Judští, suďte medle mezi mnou a vinicí mou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 4, 'Což ještě činěno býti mělo vinici mé, ješto bych jí neučinil? Proč, když jsem očekával, aby nesla hrozny, plodila plané víno?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 5, 'A protož oznámím vám, co já učiním vinici své: Odejmu plot její, a přijde na spuštění; rozbořím hradbu její, i přijde na pošlapání.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 6, 'Zapustím ji, nebude řezána, ani kopána, i vzroste na ní bodláčí a trní; oblakům také zapovím, aby nevydávali více na ni deště.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 7, 'Vinice zajisté Hospodina zástupů dům Izraelský jest, a muži Judští révové milí jemu. Očekával pak soudu, a aj, nátisk; spravedlnosti, a aj, křik.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 8, 'Běda vám, kteříž připojujete dům k domu, a pole s polem spojujete, tak že místa jiným není, jako byste sami rozsazeni byli k přebývání u prostřed země.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 9, 'V uši mé řekl Hospodin zástupů: Jistě žeť domové mnozí zpustnou, velicí a krásní bez obyvatele budou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 10, 'Nadto deset dílců viničných vydá láhvici jednu, a semena chomer vydá efi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 11, 'Běda těm, kteříž ráno vstávajíce, chodí po opilství, a trvají při tom do večera, až je víno i rozpaluje.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 12, 'A harfa, loutna a buben, a píšťalka, a víno bývá na hodech jejich; na skutky pak Hospodinovy nehledí, a díla rukou jeho nespatřují.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 13, 'Protož v zajetí půjde lid můj, nebo jest bez umění; a slavní jeho budou hladovití, a množství jeho žízní usvadne.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 14, 'Pročež rozšířilo i peklo hrdlo své, a rozedřelo nad míru ústa svá, i sstoupí do něho slavní její a množství její, i hluk její, i ti, kteříž se veselí v ní.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 15, 'A tak sehnut bude člověk, a ponížen muž, a oči pyšných sníženy budou,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 16, 'Hospodin pak zástupů vyvýšen bude v soudu, a Bůh silný a svatý ukáže se svatý v spravedlnosti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 17, 'I pásti se budou beránkové podlé obyčeje svého, a ostatky těch tučných, navrátíce se, jísti budou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 18, 'Běda těm, kteříž táhnou nepravost za provazy marnosti, a jako provazem u vozu hřích;');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 19, 'Kteříž říkají: Nechať pospíší, a nemešká dílem svým, abychom viděli, a nechať se přiblíží, a přijde rada toho Svatého Izraelského, abychom zvěděli.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 20, 'Běda těm, kteříž říkají zlému dobré, a dobrému zlé, kladouce tmu za světlo, a světlo za tmu, pokládajíce hořké za sladké, a sladké za hořké.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 21, 'Běda těm, kteříž jsou moudří sami u sebe, a vedlé zdání svého opatrní.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 22, 'Běda těm, kteříž jsou silní ku pití vína, a muži udatní k smíšení nápoje opojného;');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 23, 'Kteříž ospravedlňují bezbožného pro dary, spravedlnost pak spravedlivých odjímají od nich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 24, 'Z té příčiny, jakož plamen ohně zžírá strniště, a plevy plamen v nic obrací, tak kořen jejich bude jako shnilina, a květ jejich jako prach vzejde; nebo zavrhli zákon Hospodina zástupů, a řečí svatého Izraelského pohrdli.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 25, 'Pročež rozpáliv se prchlivostí Hospodin na lid svůj, a vztáh ruku svou na něj, porazil jej, tak že se hory zatřásly, a těla mrtvá jejich jako hnůj u prostřed ulic. V tom však ve všem neodvrátila se prchlivost jeho, ale předce ruka jeho jest vztažená.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 26, 'Nebo vyzdvihne korouhev národu dalekému, a zahvízdne naň od končin země, a aj, rychle a prudce přijde.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 27, 'Žádného ustalého ani klesajícího nebude mezi nimi; nebude dřímati ani spáti, aniž se rozepne pás bedr jeho, aniž se strhá řemen obuví jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 28, 'Střely jeho ostré, a všecka lučiště jeho natažená; kopyta koňů jeho jako škřemen souzena budou, a kola jeho jako vichřice.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 29, 'Řvání jeho jako řvání lva, a řváti bude jako lvíčata; a mumlati bude, a pochytí loupež a uteče, aniž bude, kdo by vydřel.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 30, 'A zvučeti bude nad ním v ten den, jako zvučí moře. Tehdy pohledíme na zemi, a aj, mrákota a úzkost; nebo se i světlo zatmí při pohubení jejím.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 6, 1, 'Léta, kteréhož umřel král Uziáš, viděl jsem Pána sedícího na trůnu vysokém a vyzdviženém, a podolek jeho naplňoval chrám.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 6, 2, 'Serafínové stáli nad ním. Šest křídel měl každý z nich: dvěma zakrýval tvář svou, a dvěma přikrýval nohy své, a dvěma létal.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 6, 3, 'A volal jeden k druhému, říkaje: Svatý, svatý, svatý Hospodin zástupů, plná jest všecka země slávy jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 6, 4, 'A pohnuly se podvoje veřejí od hlasu volajícího, a dům plný byl dymu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 6, 5, 'I řekl jsem: Běda mně, jižť zahynu, proto že jsem člověk poškvrněné rty maje, k tomu u prostřed lidu rty poškvrněné majícího bydlím, a že krále Hospodina zástupů viděly oči mé.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 6, 6, 'I přiletěl ke mně jeden z serafínů, maje v ruce své uhel řeřavý, kleštěmi vzatý z oltáře,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 6, 7, 'A dotekl se úst mých, a řekl: Aj hle, dotekl se uhel tento úst tvých; nebo odešla nepravost tvá, a hřích tvůj shlazen jest.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 6, 8, 'Potom slyšel jsem hlas Pána řkoucího: Koho pošli? A kdo nám půjde? I řekl jsem: Aj já, pošli mne.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 6, 9, 'On pak řekl: Jdi, a rci lidu tomu: Slyšte slyšíce, a nerozumějte, a hleďte hledíce, a nepoznávejte.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 6, 10, 'Zatvrď srdce lidu toho, a uši jeho zacpej, a oči jeho zavři, aby neviděl očima svýma, a ušima svýma neslyšel, a srdcem svým nerozuměl, a neobrátil se, a nebyl uzdraven.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 6, 11, 'A když jsem řekl: Až dokud, Pane? i odpověděl: Dokudž nezpustnou města, tak aby nebylo žádného obyvatele, a domové, aby nebylo v nich žádného člověka, a země docela nezpustne,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 6, 12, 'A nevzdálí Hospodin všelikého člověka, a nebude dokonalého zpuštění u prostřed země;');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 6, 13, 'Dokudž ještě v ní nebude desateré zhouby, a teprv zkažena bude. Ale jakož ono jilmoví, a jako doubí onoho náspu podporou jest, tak símě svaté jest podpora její.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 1, 'I stalo se za dnů Achasa syna Jotamova, syna Uziáše, krále Judského, že přitáhl Rezin král Syrský, a Pekach syn Romeliáše, krále Izraelského, k Jeruzalému, aby bojoval proti němu, ale nemohl ho dobyti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 2, 'I oznámeno jest domu Davidovu v tato slova: Spikla se země Syrská s Efraimem. Pročež pohnulo se srdce jeho, i srdce lidu jeho, tak jako se pohybuje dříví v lese od větru.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 3, 'Tedy řekl Hospodin Izaiášovi: Vyjdi nyní vstříc Achasovi, ty a Sear Jašub syn tvůj, až na konec struhy rybníka hořejšího, k silnici pole valchářova,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 4, 'A díš jemu: Šetř se, abys se nekormoutil. Neboj se, a srdce tvé nechať se neděsí dvou ostatků hlavní těch kouřících se, před rozpáleným hněvem Rezinovým s Syrskými, a syna Romeliášova,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 5, 'Proto že zlou radu složili proti tobě Syrský, Efraim a syn Romeliášův, řkouce:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 6, 'Táhněme proti zemi Judské, a vyležme ji, a odtrhněme ji k sobě, a ustavme krále u prostřed ní syna Tabealova.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 7, 'Toto praví Panovník Hospodin: Nestaneť se a nebude toho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 8, 'Nebo hlava Syrské země jest Damašek, a hlava Damašku Rezin, a po šedesáti pěti letech potřín bude Efraim, tak že nebude lidem.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 9, 'Mezi tím hlava Efraimova Samaří, a hlava Samaří syn Romeliášův. Jestliže nevěříte, jistě že neostojíte.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 10, 'I mluvil ještě Hospodin k Achasovi, řka:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 11, 'Požádej sobě znamení od Hospodina Boha svého, buď dole hluboko, aneb na hoře vysoko.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 12, 'I řekl Achas: Nebudu prositi, aniž budu pokoušeti Hospodina.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 13, 'Tedy řekl prorok: Slyšte nyní, dome Davidův, ještě-liž jest vám málo, lidem býti k obtížení, že i Bohu mému k obtížení jste?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 14, 'Protož sám Pán dá vám znamení: Aj, panna počne, a porodí syna, a nazůve jméno jeho Immanuel.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 15, 'Máslo a med jísti bude, až by uměl zavrci zlé, a vyvoliti dobré.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 16, 'Nýbrž prvé než bude uměti dítě to zavrci zlé a vyvoliti dobré, opuštěna bude země, kteréž nenávidíš pro dva krále její.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 17, 'Na tebe pak přivede Hospodin, a na lid tvůj, i na dům otce tvého dny, jakýchž nebylo ode dne, v němž odstoupil Efraim od Judy, a to skrze krále Assyrského.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 18, 'Nebo stane se v ten den, že pošepce Hospodin muchám, kteréž jsou při nejdalších řekách Egyptských, a včelám, kteréž jsou v zemi Assyrské.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 19, 'I přijdou, a usadí se všickni ti v údolích pustých a v děrách skalních, i na všech chrastinách i na všech stromích užitečných.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 20, 'V ten den oholí Pán tou břitvou najatou, (skrze ty, kteříž za řekou jsou, skrze krále Assyrského), hlavu a vlasy noh, ano také i bradu do čista sholí.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 21, 'I bude tehdáž, že sotva člověk zachová kravičku neb dvě ovce,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 22, 'Avšak pro množství mléka, kteréhož nadojí, jísti bude máslo. Máslo zajisté a med jísti bude, kdožkoli v zemi bude zanechán.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 23, 'Bude také v ten čas, že každé místo, na němž jest tisíc kmenů vinných za tisíc stříbrných, trním a hložím poroste.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 24, 'S střelami a lučištěm tudy jíti musí; hložím zajisté a trním zaroste všecka země.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 25, 'Všecky pak hory, kteréž motykou kopány býti mohou, nebudou se báti hloží a trní; nebo budou za pastviště volům, a bravům ku pošlapání.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 1, 'I řekl mi Hospodin: Vezmi sobě knihu velikou, a napiš na ní písmem lidským: K rychlé kořisti pospíchá loupežník.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 2, 'I vzal jsem sobě za svědky věrné Uriáše kněze, a Zachariáše syna Jeberechiášova.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 3, 'V tom přistoupil jsem k prorokyni, kteráž počala, a porodila syna. I řekl mi Hospodin: Dej mu jméno: K rychlé kořisti pospíchá loupežník.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 4, 'Nebo prvé než bude uměti dítě to volati: Otče můj, matko má, odejme zboží Damašské a loupeže Samařské lid krále Assyrského.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 5, 'I to ještě mluvil Hospodin ke mně, řka:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 6, 'Poněvadž pohrdl lid ten vodami Siloe tiše tekoucími, raduje se z Rezina a syna Romeliášova,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 7, 'Protož aj, Pán uvede na ně vody, řeky násilné a mnohé, totiž krále Assyrského, a všecku slávu jeho, tak že vystoupí ze všech toků svých, a půjde nad všecky břehy své.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 8, 'Půjde i přes Judu, rozleje se a rozejde, až k hrdlu dosáhne, a roztažená křídla jeho naplní širokost země tvé, ó Immanueli.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 9, 'Puntujtež se lidé, však potříni budete, (nýbrž pozorujte všickni v daleké zemi), přepašte se, však potříni budete, přepašte se, však potříni budete.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 10, 'Vejděte v radu, a zrušena bude, mluvte slovo, a neostojíť; nebo s námi jest Bůh silný.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 11, 'Tak zajisté mluvil Hospodin ke mně, ujav mne za ruku, a dav mi výstrahu, abych nechodil cestou lidu tohoto, řka:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 12, 'Neříkejte: Spuntování, když lid ten praví: Spuntování; aniž se jako oni strachujte, nerci-li, abyste se děsiti měli.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 13, 'Hospodina zástupů samého posvěcujte; on budiž bázeň vaše i strach váš.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 14, 'A budeť vám i svatyní, kamenem pak urážky a skalou pádu oběma domům Izraelským, osídlem a léčkou i obyvatelům Jeruzalémským.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 15, 'I urazí se o to mnozí, a padnou, a potříni budou, aneb zapletouce se, popadeni budou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 16, 'Zavaž osvědčení, zapečeť zákon mezi učedlníky mými.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 17, 'Pročež očekávati budu na Hospodina, kterýž skryl tvář svou od domu Jákobova; na něj, pravím, čekati budu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 18, 'Aj, já a dítky, kteréž mi dal Hospodin, na znamení a zázraky v Izraeli od Hospodina zástupů, kterýž přebývá na hoře Sion.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 19, 'Jestliže by vám pak řekli: Dotazujte se na hadačích a věšťcích, kteříž šepcí a šveholí, rcete: Nemá-liž se lid na Bohu svém dotazovati? K mrtvým-liž místo živých má se utíkati?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 20, 'K zákonu a svědectví! Pakli nechtí, nechať mluví vedlé slova toho, v němž není žádné záře,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 21, 'Až by každý toulati se musil, zbědovaný jsa a hladovitý. I stane se, že se bude, hladovitý jsa, sám v sobě zlobiti, a zlořečiti králi svému a Bohu svému, buď že zhůru pohledí,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 22, 'Buď že na zemi popatří, a aj, všudy ssoužení a tma, mrákota, bída i nátisk v temnostech.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 1, 'A však ne tak obklíčí mrákota té země, kteráž ssoužena bude, jako když se ponejprv nepřítel dotkl země Zabulon a země Neftalím, ani jako potom, když více obtíží, naproti moři, při Jordánu Galilei lidnou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 2, 'Nebo lid tento chodě v temnostech, uzří světlo veliké, a bydlícím v zemi stínu smrti světlo zastkví se.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 3, 'Rozmnožil jsi tento národ, ale nezveličils veselé. A však veseliti se budou před tebou, tak jako se veselí ve žni, jako se radují, když dělí kořisti,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 4, 'Když jho břemene jeho a prut ramene jeho, hůl násilníka jeho polámeš, jako za dnů Madianských,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 5, 'Kdyžto všickni bojovníci předěšeni, a roucha ve krvi zbrocena, ano což hořeti mohlo, i ohněm spáleno.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 6, 'Nebo dítě narodilo se nám, syn dán jest nám, i bude knížetství na rameni jeho, a nazváno bude jméno jeho: Předivný, Rádce, Bůh silný, Rek udatný, Otec věčnosti, Kníže pokoje.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 7, 'K rozmnožování pak toho knížetství a pokoje, jemuž nebude konce, sedne na stolici Davidově, a na království jeho, až je i v řád uvede, a utvrdí v soudu a v spravedlnosti, od tohoto času až na věky. Horlivost Hospodina zástupů to učiní.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 8, 'Slovo poslal Pán Jákobovi, a padlo v Izraeli.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 9, 'A zvíť všecken lid, Efraim, i obyvatelé Samařští, kteříž v pýše a vysokomyslnosti srdce říkají:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 10, 'Padly cihly, ale my tesaným kamenem stavěti budeme; planí fíkové podťati jsou, a my to v cedry směníme.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 11, 'Ale zvýší Hospodin protivníky Rezinovy nad něj, a nepřátely jeho svolá,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 12, 'Syrské po předu, a Filistinské po zadu. I budou žráti Izraele celými ústy, aniž ve všem tom odvrátí se prchlivost jeho, ale ruka jeho předce bude vztažená.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 13, 'Protože se lid ten nenavrací k tomu, kterýž jej bije, a Hospodina zástupů nehledají,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 14, 'Protož odetne Hospodin od Izraele hlavu i ocas, ratolest i sítí jednoho dne.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 15, '(Stařec a vzácný člověk, onť jest hlava, prorok pak, kterýž učí lži, onť jest ocas.)');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 16, 'Nebo vůdcové lidu tohoto jsou svůdcové, a kteříž se jim vésti dadí, zhynuli.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 17, 'Protož z mládenců jeho nepotěší se Pán, a nad sirotky a vdovami jeho neslituje se; nebo všickni jsou pokrytci a zločinci, a každá ústa mluví nešlechetnost. Aniž ve všem tom odvrátí se prchlivost jeho, ale předce ruka jeho bude vztažená.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 18, 'Nebo roznícena jsouc jako oheň bezbožnost, bodláčí a trní pálí, potom zapálí i houště lesu; pročež rozptýleni budou jako dým u povětří.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 19, 'Pro hněv Hospodina zástupů zatmí se země, a ten lid bude jako pokrm ohně. Žádný ani bratra svého šanovati nebude,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 20, 'Ale krájeje sobě po pravé straně, však lačněti bude, a zžíraje po levé, však nenasytí se. Jeden každý maso ramene svého žráti bude,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 21, 'Manasses Efraima a Efraim Manessesa, oba pak spolu proti Judovi budou. Ve všem tom však neodvrátí se prchlivost jeho, ale předce ruka jeho bude vztažená.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 1, 'Běda těm, kteříž ustanovují práva nepravá, a spisovatelům, kteříž těžkosti spisují,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 2, 'Aby odstrkovali nuzné od soudu, a vydírali spravedlnost chudých lidu mého, vdovy aby byly kořist jejich, a sirotky aby loupili.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 3, 'I což učiníte v den navštívení a zpuštění, kteréž zdaleka přijde? K komu se o pomoc utečete? A kde zanecháte slávy své,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 4, 'By nemusila skloniti se mezi vězni, a mezi zbitými klesnouti? Ve všem tom neodvrátí se prchlivost jeho, ale předce ruka jeho bude vztažená.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 5, 'Běda Assurovi, metle hněvu mého, ačkoli hůl rozhněvání mého jest v rukou jeho,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 6, 'A na národ ošemetný pošli jej, a o lidu hněvu mého přikáži jemu, aby směle bral kořisti, a loupil bez milosti, a položil jej v pošlapání jako bláto na ulicích.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 7, 'Ale on ne tak se bude domnívati, ani srdce jeho tak mysliti bude; nebo srdce jeho jest hubiti a pléniti národy mnohé.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 8, 'Nebo řekne: Zdaliž knížata má nejsou také i králové?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 9, 'Zdaliž jako Charkemis není Chalno? Zdali není jako Arfad Emat? Zdali není jako Damašek Samaří?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 10, 'Jakož nalezla ruka má království bohů, ješto rytiny jejich byly nad Jeruzalémských a Samařských,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 11, 'Zdaliž jako jsem učinil Samaří a modlám jeho, tak neučiním Jeruzalému a obrazům jeho?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 12, 'I staneť se, když dokoná Pán všecko dílo své na hoře Sion a v Jeruzalémě, že navštívím ovoce pyšného srdce krále Assyrského, a nádhernost vysokých očí jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 13, 'Nebo řekne: V síle ruky své to jsem vykonal, a v moudrosti své; nebo jsem rozumný byl, a odjal jsem meze národů, a poklady jejich jsem vzebral, a strhl jsem dolů, jako mocný, obyvatele.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 14, 'Anobrž jako hnízdo nalezla ruka má zboží národů, a jako zbírána bývají vejce opuštěná, tak všecku zemi já jsem sebral, aniž byl, kdo by křídlem hnul, aneb otevřel ústa a siptěl.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 15, 'Zdaliž se bude sekera velebiti nad toho, kdož ní seká? Zdaliž se honositi bude pila nad toho, kdož ní tře? Jako by se zpínala metla proti tomu, kdož by ji zdvihl; jako by se chlubila hůl, že není dřevem.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 16, 'Protož pošle Pán, Hospodin zástupů, na vytylé jeho vyzáblost, a po zpodku slávu jeho prudce zapálí, jako silný oheň.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 17, 'Nebo světlo Izraelovo bude ohněm, a Svatý jeho plamenem, i spálí a sžíře trní i bodláčí jeho jednoho dne.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 18, 'Též spanilost lesu jeho, i úrodných polí jeho, od duše až do těla, všecko vyhubí. I stane se, že předěšený jsa, bude utíkati.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 19, 'A pozůstalého dříví lesu jeho malý počet bude, tak že by je mohlo dítě popsati.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 20, 'I stane se v ten den, nebudou více ostatkové Izraelští a pozůstalí z domu Jákobova zpoléhati na toho, kdož je tepe, ale zpoléhati budou na Hospodina, Svatého Izraelského v pravdě.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 21, 'Ostatkové obrátí se, ostatkové Jákobovi k Bohu silnému, reku udatnému.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 22, 'Nebo byť bylo lidu tvého, Izraeli, jako písku mořského, ostatkové jeho obrátí se. Pohubení uložené rozhojní spravedlnost.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 23, 'Pohubení, pravím, a to jisté, Pán, Hospodin zástupů, učiní u prostřed vší této země.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 24, 'Protož takto praví Pán, Hospodin zástupů: Neboj se Assyrského, lide můj, kterýž přebýváš na Sionu. Prutem umrská tě, a holí svou opřáhne na tebe na cestě Egyptské.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 25, 'Po maličkém zajisté času dokoná se hněv a prchlivost má k vyhlazení jich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 26, 'Nebo vzbudí na něj Hospodin zástupů bič, jako porážku Madianských na skále Goréb, a jakož pozdvihl holi své na moře, tak jí pozdvihne na něj, na cestě Egyptské.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 27, 'I stane se v ten den, že složeno bude břímě jeho s ramene tvého, a jho jeho s šíje tvé, nýbrž zkaženo bude jho od přítomnosti pomazaného.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 28, 'Přitáhne do Aiat, přejde přes Migron, v Michmas složí nádobí svá.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 29, 'Projdou průchod, v Gabaa budou míti hospodu k přenocování; ulekne se Ráma, Gabaa Saulovo uteče.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 30, 'Naříkej hlasem svým, město Gallim, ať se slyší v Lais: Ach, ubohá Anatot.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 31, 'Pohne se Madmena, obyvatelé Gábim schopí se.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 32, 'Ještě téhož dne zastavě se v Nobe, pohrozí rukou svou hoře dcery Sionské, pahrbku Jeruzalémskému.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 33, 'Aj, Panovník Hospodin zástupů oklestí vší silou ratolesti, ty pak, kteříž jsou vysokého zrostu, podetne; i budou vysocí sníženi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 34, 'Vyseká též houšť lesů sekerou, i Libán od velikomocného padne.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 11, 1, 'Ale vyjdeť proutek z pařezu Izai, a výstřelek z kořenů jeho vyroste, a ovoce ponese.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 11, 2, 'Na němž odpočine Duch Hospodinův, Duch moudrosti a rozumnosti, Duch rady a síly. Duch umění a bázně Hospodinovy.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 11, 3, 'A bude stižitelný v bázni Hospodinově, a nebudeť podlé vidění očí svých souditi, ani podlé slyšení uší svých trestati.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 11, 4, 'Ale souditi bude chudé podlé spravedlnosti, a v pravosti trestati tiché v zemi. Bíti zajisté bude zemi holí úst svých, a duchem rtů svých zabije bezbožného.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 11, 5, 'Nebo spravedlnost bude pasem bedr jeho, a pravda přepásaním ledví jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 11, 6, 'I bude bydliti vlk s beránkem a pardus s kozlátkem ležeti; tolikéž tele a lvíče i krmný dobytek spolu budou, a malé pacholátko je povede.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 11, 7, 'Také i kráva a nedvědice spolu pásti se budou, a plod jejich spolu ležeti, lev pak jako vůl plevy jísti bude.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 11, 8, 'A lítý had nad děrou pohrávati bude s dítětem prsí požívajícím, a to, kteréž ostaveno jest, směle sáhne rukou svou do díry bazališkovy.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 11, 9, 'Neuškodí, aniž zahubí na vší mé hoře svaté; nebo země naplněna bude známostí Hospodina, tak jako vodami moře naplněno jest.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 11, 10, 'A budeť v ten den, že na kořen Izai, kterýž stane za korouhev národům, pohané pilně ptáti se budou; nebo odpočívání jeho bude slavné.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 11, 11, 'I bude v ten den, že přičiní Pán po druhé ruky své, aby shledal ostatky lidu svého, což jich zanecháno bude od Assura, a od Egypta, a od Patros, a od Chus, a od Elam, a od Sinear, a od Emat, a od ostrovů mořských.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 11, 12, 'A vyzdvihne korouhev mezi pohany, a sbéře zahnané Izraelské, a rozptýlené Judovy shromáždí ode čtyř stran země.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 11, 13, 'I přestane nenávist Efraimova, a nepřátelé Judovi vyhlazeni budou. Efraim nebude nenáviděti Judy, a Juda nebude ssužovati Efraima.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 11, 14, 'Ale vletí na rameno Filistinských k západu, a spolu loupiti budou národy východní. Na Idumejské a Moábské sáhnou rukou svou, a synové Ammon poslouchati jich budou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 11, 15, 'Zkazí též Hospodin zátoku moře Egyptského, a vztáhne ruku svou na řeku v prudkosti větru svého, a rozrazí ji na sedm potůčků, a učiní, aby je v obuvi přejíti mohli.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 11, 16, 'I bude silnice ostatkům lidu toho, kterýž zanechán bude od Assyrských, jako byla Izraelovi v ten den, když vycházel z země Egyptské.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 12, 1, 'I díš v ten den: Oslavovati tě budu, Hospodine, proto že byv hněviv na mne, odvrátil jsi prchlivost svou, a utěšil jsi mne.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 12, 2, 'Aj, Bůh silný spasení mé, doufati budu, a nebudu se strašiti; nebo síla má a píseň a spasení mé jest Bůh Hospodin.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 12, 3, 'I budete vážiti vody s radostí z studnic toho spasení,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 12, 4, 'A řeknete v ten den: Oslavujte Hospodina, vzývejte jméno jeho, známé čiňte mezi lidmi skutky jeho, připomínejte, že vyvýšené jest jméno jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 12, 5, 'Žalmy zpívejte Hospodinu, nebo veliké věci učinil; a to známé buď po vší zemi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 12, 6, 'Prokřikni a zpívej, obyvatelkyně Sionská, nebo veliký jest u prostřed tebe Svatý Izraelský.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 1, 'Břímě Babylona, kteréž viděl Izaiáš syn Amosův.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 2, 'Na hoře vysoké vyzdvihněte korouhev, povyšte hlasu k nim, dejte návěští rukou, ať vejdou do bran knížecích.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 3, 'Já jsem přikázal posvěceným svým, povolal jsem také i udatných reků svých k vykonání hněvu svého, veselících se z vyvýšení mého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 4, 'Hlas množství na horách, jakožto lidu mnohého, hlas a zvuk království a národů shromážděných: Hospodin zástupů sbírá vojsko k válce.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 5, 'Táhnou z země daleké od končin nebes. Hospodin a osudí prchlivosti jeho, aby poplénil všecku zemi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 6, 'Kvělte, nebo blízko jest den Hospodinův, jako zpuštění od Všemohoucího přijde.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 7, 'A protož všeliké ruce oslábnou, a všeliké srdce člověka rozplyne se.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 8, 'I budou předěšeni, svírání a bolesti je zachvátí, jako rodička stonati budou; každý nad bližním svým užasne se, tváře jejich k plameni podobné budou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 9, 'Aj, den Hospodinův přichází přísný, a zůřivost a rozpálení hněvu, aby obrátil tu zemi v poušť, a hříšníky její z ní vyhladil.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 10, 'Nebo hvězdy nebeské a planéty jejich nedopustí svítiti světlu svému; zatmí se slunce při vycházení svém, a měsíc nevydá světla svého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 11, 'A navštívím na okršlku země zlost, a na bezbožných nepravost jejich; a káži přestati pýše pyšných, a vysokomyslnost tyranů snížím.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 12, 'Způsobím to, že dražší bude člověk nad zlato čisté, člověk, pravím, nad zlato z Ofir.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 13, 'Z té příčiny zatřesu nebesy, a pohne se země z místa svého, v prchlivosti Hospodina zástupů, a ve dni rozpálení hněvu jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 14, 'I bude jako srna zplašená, a jako stádo, když není, kdo by je shromáždil; jedenkaždý k lidu svému se obrátí, a každý do země své uteče.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 15, 'Kdožkoli nalezen bude, bude proboden, a kteříž by se koli shlukli, od meče padnou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 16, 'Nadto i dítky jejich rozrážíny budou před očima jejich, domové jejich zloupeni, a ženy jejich poškvrněny.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 17, 'Aj, já vzbudím proti nim Médské, kteříž sobě stříbra nebudou vážiti, a v zlatě nebudou se kochati,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 18, 'Ale z luků dítky rozrážeti, aniž se nad plodem života slitují, aniž synům odpustí oko jejich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 19, 'I budeť Babylon, někdy ozdoba království a okrasa důstojnosti Kaldejské, podobný podvrácené Sodomě a Gomoře.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 20, 'Nebudou se v něm osazovati na věky, ani bydliti od pokolení až do pokolení; aniž rozbije tam stanu svého Arab, ani pastýři tam odpočívati budou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 21, 'Ale lítá zvěř tam odpočívati bude, a domové jejich šelmami naplněni budou; bydliti budou tam i sovy, a příšery tam skákati budou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 22, 'Ozývati se také budou sobě hrozné potvory na palácích jejich, a draci na hradích rozkošných. A blízkoť jest, že přijde čas jeho, a dnové jeho prodlévati nebudou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 1, 'Nebo slituje se Hospodin nad Jákobem, a vyvolí zase Izraele, a dá jim odpočinutí v zemi jejich; a připojí se k nim cizozemec, a přídržeti se budou domu Jákobova.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 2, 'Nebo pojmou ty národy, a přivedou je k místu svému, i uvedou je v dědictví dům Izraelský v zemi Hospodinově, za služebníky a za děvky; a jímati budou ty, kteříž je zjímali, a panovati budou nad násilníky svými.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 3, 'I staneť se v ten den, v němž tobě odpočinutí dá Hospodin od těžkosti tvé a strachu tvého, a od poroby těžké, v kterouž jsi byl podroben,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 4, 'Že uživeš přísloví tohoto o králi Babylonském, a řekneš: Aj, jak přestal násilník! Přestalo dychtění po zlatě.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 5, 'Potřískal Hospodin hůl bezbožných, prut panujících,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 6, 'Mrskajícího lidi v prchlivosti mrskáním ustavičným, panujícího v hněvě nad národy, kteříž ssužováni bývali bez lítosti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 7, 'Odpočívá, jest v pokoji všecka země, zvučně prozpěvují.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 8, 'I jedloví veselí se nad tebou, i cedroví Libánské, řkouce: Jakž jsi klesl, nepovstal, kdo by nás podtínal.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 9, 'I peklo zespod zbouřilo se pro tebe, k vyjití vstříc přicházejícímu tobě vzbudilo pro tě mrtvé, všecka knížata země; kázalo vyvstati z stolic jejich i všechněm králům národů.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 10, 'Všickni tito odpovídajíce, mluví tobě: Což ty také jsi zemdlen jako i my, a nám podobný učiněn?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 11, 'Svrženať jest do pekla pýcha tvá, i zvuk hudebných nástrojů tvých; moli tobě podestláno, a červi tě přikrývají.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 12, 'Jakž to, že jsi spadl s nebe, ó lucifeře v jitře vycházející? Poražen jsi až na zem, ještos zemdlíval národy.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 13, 'Však jsi ty říkával v srdci svém: Vstoupím do nebe, nad hvězdy Boha silného vyvýším stolici svou, a posadím se na hoře shromáždění k straně půlnoční.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 14, 'Vstoupím nad výsosti oblaku, budu rovný Nejvyššímu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 15, 'A ty pak stržen jsi až do pekla, pryč na stranu do jámy.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 16, 'Ti, kdož tě uzří, za tebou se ohlédati, a tebe spatřovati budou, říkajíce: To-liž jest ten muž, kterýž nepokojil zemi, a pohyboval královstvími,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 17, 'Obracel jako v pustinu okršlek země, a města jeho bořil, vězňů svých nepropouštěl domů?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 18, 'Všickni králové národů, což jich koli bylo, pochováni slavně doma jeden každý z nich;');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 19, 'Ty pak zavržen jsi od hrobu svého jako ratolest ohyzdná, a roucho zbitých, ukrutně zraněných, kteříž se dostávají do jámy mezi kamení, a jako mrcha pošlapaná.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 20, 'Nebudeš k oněmno v pohřbu přiúčastněn, nebo jsi poplénil zemi svou, lid svůj jsi pomordoval; nebudeť připomínáno na věky símě zlostníků.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 21, 'Připravte se k zmordování synů jeho pro nepravosti otců jejich, aby nepovstali, a dědičně neujali země, a nenaplnili svrchku okršlku zemského městy.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 22, 'Nebo povstanu proti nim, praví Hospodin zástupů, a zahladím jméno Babylona i ostatky syna i vnuka, praví Hospodin.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 23, 'A obrátím jej v dědictví bukačů, a v jezera vod, a vymetu jej pometlem zahynutí, praví Hospodin zástupů.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 24, 'Přisáhl Hospodin zástupů, řka: Jistě že jakž jsem myslil, tak bude, a jakž jsem uložil, stane se,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 25, 'Že potru Assyrského v zemi své, a na horách svých pošlapám jej, a odejde z nich jho jeho, břímě také jeho s ramene jejich sňato bude.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 26, 'Toť jest ta rada, kteráž zavřína jest o vší té zemi, a to jest ta ruka vztažená proti všechněm těm národům.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 27, 'Poněvadž pak Hospodin zástupů usoudil, kdo to tedy zruší? A ruku jeho vztaženou kdo odvrátí?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 28, 'Léta kteréhož umřel král Achas, stalo se proroctví toto:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 29, 'Neraduj se všecka ty země Filistinská, že zlámán jest prut toho, kterýž tě mrskal; nebo z plemene hadího vyjde bazališkus, jehož plod bude drak ohnivý létající.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 30, 'I budou se pásti prvorození chudých, a nuzní bezpečně odpočívati budou; kořen pak tvůj umořím hladem, a ostatky tvé zmorduje.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 31, 'Kvěl, ó bráno, křič město, již jsi rozplynula se všecka ty země Filistinská; nebo od půlnoci oheň přijde aniž bude, kdo by stranil z obcí jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 32, 'Co pak odpovědí poslové národů? To, že Hospodin upevnil Sion, v němž útočiště mají chudí z lidu jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 15, 1, 'Břímě Moábských. Když v noci Ar Moábské popléněno a zkaženo bude, když i Kir Moábské v noci popléněno a zkaženo bude,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 15, 2, 'Vstoupí do Baít, a do Dibon a do Bamot s pláčem, nad Nébo a nad Medaba Moáb kvíliti bude, na všech hlavách jeho bude lysina, a každá brada oholena bude.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 15, 3, 'Na ulicích jeho přepáší se žíní, na střechách jeho i na ryncích jeho každý kvíliti bude, s pláčem se vraceje.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 15, 4, 'A křičeti bude Ezebon a Eleale, až v Jasa slyšán bude hlas jejich, nýbrž i zbrojní Moábští křičeti budou. Duše každého z nich žalostiti bude, a řekne:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 15, 5, 'Srdce mé řve nad Moábem a pevnostmi jeho, až slyšeti v Ségor, jako jalovice tříletá; nebo cestou Luchitskou s pláčem půjde, a kudyž se chodí k Choronaim, křik hrozný vydávati budou,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 15, 6, 'Proto že vody Nimrim vymizejí, že uschne bylina, usvadne tráva, aniž co zeleného bude.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 15, 7, 'A protož zboží nachované a statky jejich odnesou ku potoku Arabim.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 15, 8, 'Nebo křik obejde vůkol meze Moábské, až do Eglaim kvílení jeho, a až do Beer Elim kvílení jeho,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 15, 9, 'Poněvadž i vody Dimon naplněny budou krví. Přidám zajisté Dimonu přídavků, a pošli na ty, kteříž ujdou z Moábských, lvy, i na pozůstalé v té zemi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 16, 1, 'Pošlete beránky panovníku země, počnouc od Sela až do pouště, k hoře dcery Sionské.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 16, 2, 'Sic jinak bude Moáb jako pták místa nemající, a s hnízda sehnaný; budou dcery Moábské při brodech Arnon.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 16, 3, 'Svolej radu, učiň soud, připrav stín svůj u prostřed poledne jako noc; skrej vyhnané, místa nemajícího nevyzrazuj.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 16, 4, 'Nechať u tebe pobudou vyhnaní moji, ó Moábe, buď skrýší jejich před zhoubcím; nebo přestane násilník, přestane zhoubce, pošlapávající vyhlazen bude z země.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 16, 5, 'A upevněn bude milosrdenstvím trůn, a seděti bude na něm stále v stánku Davidovu ten, kterýž by soudil a vyhledával soudu a pospíchal k spravedlnosti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 16, 6, 'Ale slýchaliť jsme o pýše Moábově, že velmi pyšný jest, o pýše jeho, a chloubě jeho i spouzení se jeho, ale nepřijdouť k vykonání myšlénky jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 16, 7, 'Protož kvíliti bude Moáb před Moábem, jeden každý kvíliti bude; nad grunty Kirchareset úpěti budete, a říkati: Jižť jsou zkaženi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 16, 8, 'Nýbrž i réví Ezebon usvadlo, i vinní kmenové Sibma. Páni národů potřeli výborné réví jeho, kteréž až do Jazer dosahalo, a bylo se rozšířilo při poušti; rozvodové jeho rozložili se, a dosahali až za moře.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 16, 9, 'Protož pláči pro pláč Jazerských a pro vinici Sibma; svlažuji tě slzami svými, ó Ezebon a Eleale, nebo provyskování nad ovocem tvým letním a nad žní tvou kleslo.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 16, 10, 'A přestalo veselé a plésání nad polem úrodným, na vinicích se nezpívá, ani prokřikuje, vína v presích netlačí ten, kterýž tlačívá. Takž i já provyskování přestávám.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 16, 11, 'Protože střeva má nad Moábem jako harfa znějí, a vnitřnosti mé pro Kircheres.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 16, 12, 'I stane se, když zřejmé bude, an ustává Moáb nad výsostmi, že vejde do svatyně své, aby se modlil, však nic nespraví.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 16, 13, 'Toť jest to slovo, kteréž mluvil Hospodin o Moábovi již dávno.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 16, 14, 'Nyní pak praví Hospodin, řka: Po třech letech, jakáž jsou léta nájemníka, v potupu uvedena bude sláva Moábova se vším množstvím velikým, tak že ostatkové jeho budou skrovní, přemaličcí a mdlí.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 17, 1, 'Břímě Damašku. Aj, Damašek přestane býti městem, a bude hromadou rumu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 17, 2, 'Zpuštěná města Aroer pro stáda budou, a odpočívati tam budou, a nebude žádného, kdo by je strašil.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 17, 3, 'I bude odjata pevnost od Efraima, a království od Damašku i ostatků Syrských; jako i sláva synů Izraelských na nic přijdou, praví Hospodin zástupů.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 17, 4, 'I bude v ten den, že opadne sláva Jákobova, a tuk těla jeho vymizí.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 17, 5, 'Nebo bude Assur jako ten, jenž shromažďuje ve žni obilé, a rámě jeho žne klasy, anobrž bude jako ten, jenž zbírá klasy v údolí Refaim.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 17, 6, 'Paběrkové však zanecháni v něm budou, jako po očesání olivy dvě neb tři olivky na vrchu větve, a čtyry neb pět na ratolestech jejích plodistvých, praví Hospodin Bůh Izraelský.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 17, 7, 'V ten den patřiti bude člověk k Učiniteli svému, a oči jeho k Svatému Izraelskému hleděti budou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 17, 8, 'A nebude patřiti k oltářům, dílu rukou svých; ani k tomu, což učinili prstové jeho, hleděti bude, ani k hájům, ani k obrazům slunečným.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 17, 9, 'V ten den budou města síly jeho opuštěna jako chrastinka a růžťka, kteráž opuštěna budou od synů Izraelských, i spustneš, ó země.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 17, 10, 'Nebos se zapomněla na Boha spasení svého, a na skálu síly své nezpomenulas. Protož ačkoli štěpy rozkošné štěpuješ, a kmen vinný přespolní sázíš,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 17, 11, 'V čas štěpování tvého štípí, aby rostlo, opatruješ, nýbrž téhož jitra o to, což seješ, aby se pučilo, pečuješ: v den však užitku odejde žeň, na žalost tvou přetěžkou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 17, 12, 'Běda množství lidí mnohých, kteříž jako zvuk mořský ječí, a hlučícím národům, kteříž jako zvuk vod násilných hlučí,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 17, 13, 'Národům jako zvuk vod mnohých zvučícím; nebo je Bůh okřikne. Pročež daleko utíkati budou, a honěni budou jako plevy po vrších od větru, a jako chumel od vichřice.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 17, 14, 'Nebo u večer aj, předěšení, a než jitro přijde, anť ho není. Tenť jest podíl těch, kteříž nás potlačují, a los těch, kteříž nás loupí.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 18, 1, 'Běda zemi zastěňující se křídly, kteráž jest při řekách země Mouřenínské,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 18, 2, 'Posílající po moři posly, v nástrojích z sítí po vodách, řka: Jděte, poslové rychlí, k národu rozptýlenému a zloupenému, k lidu hroznému zdávna i posavad, k národu všelijak potlačenému, jehož zemi řeky roztrhaly.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 18, 3, 'Všickni obyvatelé světa, a přebývající na zemi, když bude korouhev vyzdvižena na horách, uzříte, a když troubiti se bude trubou, uslyšíte.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 18, 4, 'Nebo takto praví Hospodin ke mně: Spokojímť se, a podívám z příbytku svého, a budu jako teplo vysušující po dešti, a jako oblak dešťový v čas horké žně.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 18, 5, 'Před vinobraním zajisté, když se vypučí pupenec, a květ vydá hrozen trpký, ještě rostoucí, tedy podřeže révíčko noži, a rozvody odejme a zpodtíná.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 18, 6, 'I budou zanecháni všickni spolu ptactvu z hor, a šelmám zemským, a bude na nich přes léto ptactvo, a všeliké šelmy zemské na nich přes zimu zůstanou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 18, 7, 'V ten čas přinesen bude dar Hospodinu zástupů (od lidu rozptýleného a zloupeného, od lidu hrozného zdávna i posavad, národu všelijak potlačeného, jehožto zemi řeky rozchvátaly), k místu jména Hospodina zástupů, hoře Sion.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 1, 'Břímě Egyptských. Aj, Hospodin béře se na oblaku lehkém, a přitáhne na Egypt. I pohnou se modly Egyptské před tváří jeho, a srdce Egyptských rozplyne se u prostřed něho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 2, 'Nebo spustím Egyptské s Egyptskými, tak že bojovati budou jeden každý proti bratru svému, a přítel proti příteli svému, město proti městu, království proti království.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 3, 'A na nic přijde duch Egyptských u prostřed něho, a radu jeho sehltím. I raditi se budou modl a kouzedlníků a zaklinačů a hadačů.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 4, 'Dám zajisté Egypt v ruku pánů ukrutných, a král přísný panovati bude nad nimi, praví Pán, Hospodin zástupů.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 5, 'A vymizejí vody z moře, i řeka osákne a vyschne.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 6, 'I vzdálí se řeky, opadnou a vyschnou potokové Egyptští, třtí i rákosí usvadne.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 7, 'Tráva okolo potoka a při pramenu potoka, i vše, což se seje při potoku, uschne, zmizí a ztratí se.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 8, 'I budou žalostiti rybáři, a kvíliti všickni, kteříž mecí do potoka udici; a kteříž rozstírají síti na vody, na nouzi přijdou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 9, 'Zahanbeni budou i ti, kteříž dělají věci lněné a hedbávné, a kteříž tkají kment.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 10, 'Nebo síti jeho budou zkaženy, i všickni dělající rybníky pro ryby.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 11, 'Jistě žeť jsou blázni knížata Soan, moudrých rádců Faraonových rada zhlupěla. Jakž říkati můžete Faraonovi: Syn moudrých já jsem, syn králů starožitných?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 12, 'Kdež jsou, kde ti moudří tvoji? Nechať oznámí nyní tobě, vědí-li, co uložil Hospodin zástupů o Egyptu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 13, 'Zbláznila se knížata Soan, podvedena jsou knížata Nof, svedli Egypt přednější v pokolení jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 14, 'Hospodin pustil mezi ně ducha závrativého, i spraví to, že zbloudí Egypt při všelikém předsevzetí svém, tak jako bloudí ožralec při vývratku svém.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 15, 'Aniž bude dílo v Egyptě, kteréž by učinila hlava neb ocas, ratolest aneb sítí.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 16, 'V ten den bude Egypt podobný ženám; nebo strašiti se a děsiti bude před zdvižením ruky Hospodina zástupů, kterouž on zdvihne proti němu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 17, 'A budeť země Judská Egyptu k hrůzi; každý, kdož zpomene na ni, strašiti se bude, pro radu Hospodina zástupů, kterouž zavřel o něm.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 18, 'V ten den bude pět měst v zemi Egyptské, mluvících jazykem Kananejským, a přisahajících skrze Hospodina zástupů, jedno pak nazváno bude město zpuštění.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 19, 'V ten den bude oltář Hospodinův u prostřed země Egyptské, a sloup při pomezí jejím Hospodinu;');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 20, 'Bude, pravím, na znamení a na svědectví Hospodinu zástupů v zemi Egyptské. A když volati budou k Hospodinu příčinou těch, kteříž by je ssužovali, tedy pošle jim spasitele a kníže, i vysvobodí je.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 21, 'I bude známý Hospodin Egyptským; nebo poznají Egyptští Hospodina v ten den, a ctíti jej budou obětmi a dary, a činiti budou sliby Hospodinu, i plniti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 22, 'A tak bíti bude Hospodin Egypt, aby zbije, uzdravil jej; nebo obrátí se k Hospodinu, a on je vyslyší a uzdraví.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 23, 'V ten den bude silnice z Egypta do Assyrie, i budou choditi Assyrští do Egypta, a Egyptští do Assyrie, a sloužiti budou Egyptští s Assyrskými Hospodinu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 24, 'V ten den bude Izrael Egyptským a Assyrským jako třetí z nich, i budou požehnaní u prostřed země.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 25, 'Nebo požehná jim Hospodin zástupů, řka: Požehnaný lid můj Egyptský, a dílo rukou mých Assur, i dědictví mé Izrael.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 20, 1, 'Léta, kteréhož přitáhl Tartan do Azotu, poslán jsa od Sargona, krále Assyrského, a když bojoval proti Azotu, a vzal jej,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 20, 2, 'Času toho mluvil Hospodin skrze Izaiáše syna Amosova, řka: Jdi a slož žíni z bedr svých, a obuv svou zzuj s noh svých. I učinil tak, a chodil nahý a bosý.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 20, 3, 'I řekl Hospodin: Jakož chodí služebník můj Izaiáš nahý a bosý, na znamení a zázrak, třetího roku Egypta a Mouřenínské země,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 20, 4, 'Tak povede král Assyrský jaté Egyptské a jaté Mouřenínské, mladé i staré, nahé a bosé, s obnaženými zadky, k hanbě Egyptských.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 20, 5, 'I užasnou se a zahanbí nad Mouřeníny, útočištěm svým, a nad Egyptskými, chloubou svou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 20, 6, 'Tedy řekne obyvatel ostrovu tohoto v ten den: Aj hle, toť naše útočiště, k němuž jsme se utíkali o pomoc, abychom vysvobozeni byli z moci krále Assyrského. Jakž bychom my tedy ušli?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 1, 'Břímě pustého moře. Jako vichřice na poledne se žene, tak přijde z pouště, z země hrozné.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 2, 'Vidění tvrdé jest mi ukázáno. Nešlechetník nešlechetnost páše, a zhoubce hubí. Přitáhniž Elame, Médský oblehni. Všelikému úpění jeho přestati rozkáži.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 3, 'Z té příčiny naplněna jsou bedra má bolestí, úzkosti postihly mne jako úzkosti rodičky; sklíčen jsem, slyše to, strnul jsem, vida to.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 4, 'Zkormoutilo se srdce mé, hrůza předěsila mne, noc mých rozkoší obrátila se mi v strach.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 5, 'Přistroj na stůl, nechť stráž drží strážný, jez, pí. Vstaňte knížata, mažte pavézy.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 6, 'Nebo tak řekl ke mně Pán: Jdi, postav strážného, kterýž by to, což uhlédá, oznámil.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 7, 'I viděl vozy, a dvěma řady jízdu, vozy, kteréž oslové, a vozy, kteréž velbloudové táhli; šetřil zajisté pilně s velikou bedlivostí.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 8, 'A volal jako lev: Jáť, Pane můj, stojím na stráži ustavičně ve dne, nýbrž na stráži své já stávám v každičkou noc.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 9, '(A aj, v tom přijeli na vozích muži a dvěma řady jízda.) Zvolal tedy a řekl: Padl, padl Babylon, a všecky rytiny bohů jeho o zem roztřískány.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 10, 'Méť jest humno, a obilé humna mého. Což jsem slyšel od Hospodina zástupů, Boha Izraelského, oznámil jsem vám.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 11, 'Břímě Dumy. Slyším hlas z Seir: Strážný, co bylo v noci? Strážný, co se stalo v noci?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 12, 'Řekl strážný: Přišlo jitro, a tolikéž noc; chcete-li hledati, hledejte. Navraťte se, přiďte.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 13, 'Břímě na Arabii. Po lesích v Arabii nocleh mívati budete, ó pocestní Dedanských.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 14, 'Obyvatelé země Tema nechať vynesou vody vstříc žíznivému; s chlebem jeho nechať vyjdou proti utíkajícímu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 15, 'Nebo před mečem utíkati budou, před mečem vytaženým, před lučištěm nataženým, před těžkostí boje.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 16, 'Tak zajisté řekl Pán ke mně: Že po roce, jakýž jest rok nájemníka, přestane všecka sláva Cedar,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 17, 'A pozůstalý počet střelců udatných synů Cedar zmenšen bude; nebo Hospodin Bůh Izraelský to mluvil.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 1, 'Břímě údolí vidění. Cožť se stalo, že jsi vystoupilo všecko na střechy,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 2, 'Město plné hřmotu a hluku, město veselící se? Zbití tvoji nejsou zbiti mečem, ani zhynuli v boji.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 3, 'Všecka knížata tvá rozprchla se napořád, od střelců svázána jsou. Což jich koli nalezeno jest v tobě, napořád svázáni jsou, zdaleka utíkají.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 4, 'Protož jsem řekl: Ponechejte mne, ať hořekuji s pláčem, a neusilujte mne těšiti nad popléněním dcerky lidu mého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 5, 'Nebo jest den ssoužení, a pošlapání, a v mysli sevření ode Pána, Hospodina zástupů, v údolí vidění, den boření zdi, a křiku k horám.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 6, 'Byltě zajisté Elam pochytil toul s vozy lidu vojenského, a Kir ukázal pavézu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 7, 'I stalo se, že nejvýbornější údolí tvá naplněna byla vozy, a vojáci silně položili se u brány,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 8, 'A odkryto bylo zastření Judovo; však obrátilo jsi zřetel v ten den k zbrojné komoře.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 9, 'I k zbořeninám města Davidova dohlédli jste, nebo mnohé byly, a shromáždili jste vody rybníka dolního.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 10, 'Domy též Jeruzalémské sečtli jste, i pobořili, abyste utvrdili zed.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 11, 'Udělali jste také stav mezi dvěma zdmi pro vody rybníka starého, aniž jste popatřili k Učiniteli jeho, a toho, kdo jej vzdělal od starodávna, neviděli jste.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 12, 'Nadto když volal Pán, Hospodin zástupů, v ten den k pláči a k kvílení, a k lysině a k přepásání se žíní.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 13, 'A aj, radost a veselí vaše zabijeti voly, a bíti ovce, jísti maso, a píti víno, a říkati: Jezme, píme, nebo zítra zemřeme.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 14, 'Ale známéť jest to v uších mých, praví Hospodin zástupů. Protož nikoli vám nebude odpuštěna ta nepravost, až i zemřete, praví Pán, Hospodin zástupů.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 15, 'Takto praví Pán, Hospodin zástupů: Jdi, vejdi k Sochitskému tomu, k Sobnovi správci domu, a řekni:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 16, 'Co ty zde máš? A koho zde máš, že jsi vytesal sobě zde hrob? Vytesals sobě na vysokém místě hrob svůj, a vystavěls na skále příbytek svůj.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 17, 'Aj, Hospodin, kterýž tě přistřel, jakž na muže znamenitého náleží, a kterýž tě výborně přioděl,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 18, 'Prudce tě zakulí jako kuli do země všelijak prostranné. Tam umřeš, tam i vozové slávy tvé, ó ohyzdo domu Pána svého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 19, 'A tak seženu tě s místa tvého, a s úřadu tvého svrhu tě.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 20, 'I stane se v ten den, že povolám služebníka svého Eliakima syna Helkiášova,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 21, 'A obleku jej v sukni tvou, a pasem tvým potvrdím ho, panování tvé také dám v ruku jeho. I bude za otce obyvatelům Jeruzalémským a domu Judovu,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 22, 'A vložím klíč domu Davidova na rameno jeho. Když otevře, žádný nezavře, a když zavře, žádný neotevře.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 23, 'A vbiji jej jako hřebík v místě pevném, a bude stolicí slávy domu otce svého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 24, 'I zavěsí na něm synové a dcery všecku slávu domu otce jeho, všecko nádobí, i to nejmenší, od nádobí, z něhož se pije, až do všech nádob vinných.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 25, 'V ten den, praví Hospodin zástupů, pohne se hřebík, kterýž vbit byl v místě pevném, a vyťat bude, a spadne, odťato bude i břímě, kteréž jest na něm; nebo Hospodin mluvil.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 1, 'Břímě Týru. Kvělte lodí mořské; nebo popléněn jest, tak že není ani domu. Aniž kdo přichází z země Citim; známé učiněno jest jim.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 2, 'Umlknětež obyvatelé ostrovu, kterýž kupci Sidonští, plavíce se přes moře, naplňovali,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 3, 'A jehož úrody na velikých vodách, símě Sichor, žeň jeho, užitek potoka, a kterýž byl skladem národů.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 4, 'Zastyď se, Sidone, nebo praví moře, pevnost mořská, řkuc: Nepracuji ku porodu, a nerodím, a nevychovávám mládenců, aniž odchovávám panen.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 5, 'Jakož nad pověstí o Egyptu, tak žalostiti budou nad pověstí o Týru.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 6, 'Přepravte se do Tarsu, kvělte obyvatelé ostrovu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 7, 'To-liž by se vždycky veselilo? Jestiť starožitnost jeho ode dnů starodávních, ale zavedouť je daleko nohy jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 8, 'Kdo že to usoudil proti Týru, korunujícímu jiné, jehož kupci jsou jako knížata, a kramáři jeho znamenití v zemi?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 9, 'Hospodin zástupů usoudil to, aby zohavil pýchu všelikého slavného, a za nic položil všecky znamenité země.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 10, 'Navrať se do země své jako řeka, ó dcero Tarská, neníť tam více ani pasu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 11, 'Vztáhl ruku svou na moře, pohnul královstvími; Hospodin přikázal o tržišti, aby zkaženy byly pevnosti jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 12, 'A řekl: Nebudeš se více veseliti, trpěc nátisk, panno, dcero Sidonská. Povstaň, beř se do Citim, ale i tam nebudeš míti odpočinutí.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 13, 'Aj, země Kaldejská, ten lid nebyl lidem. Assur vzdělal ji pro obyvatele pustin, vystavěli věže jejich, vzdělali paláce její, tak že i Assyrii vyvrátil.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 14, 'Kvělte lodí mořské, nebo zpuštěna jest pevnost vaše.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 15, 'I stane se v ten den, že v zapomenutí bude Týrus za sedmdesáte let, jako za věk krále jednoho. Do skonání sedmdesáti let bude míti Týrus jako písničku nevěstky.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 16, 'Vezmi harfu, obcházej město, ó nevěstko v zapomenutí daná, hrej dobře, zpívej dlouho, abys v pamět uvedena byla.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 17, 'I bude po dokonání sedmdesáti let, že navštíví Hospodin Týr, ale on navrátí se zase k nevěstčí mzdě své, a smilniti bude se všemi královstvími země na okršlku světa.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 18, 'Však kupectví jeho a mzda jeho svatá bude Hospodinu. Nebude na poklad skládána, ani schovávána, ale pro ty, kteříž přebývají před Hospodinem, bude kupectví jeho, aby jedli do sytosti, a měli roucho dobré.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 1, 'Aj, Hospodin vyprázdní zemi, a pustou učiní; promění zajisté způsob její, a rozptýlí obyvatele její.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 2, 'I budeť jakož lid tak kníže, jakož služebník tak pán jeho, jakož děvka tak paní její, jakož kupující tak prodávající, jakož půjčující tak vypůjčující, jakož lichevník tak ten, jenž lichvu dává.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 3, 'Náramně vyprázdněna bude země, a velice zloupena; nebo Hospodin mluvil slovo toto.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 4, 'Kvíliti bude a padne země, zemdlí a padne okršlek země, zemdlejí vysocí národové zemští,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 5, 'Proto že i ta země poškvrněna jest pod obyvateli svými; nebo přestoupili zákony, změnili ustanovení, zrušili smlouvu věčnou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 6, 'Protož prokletí zžíře zemi, a vypléněni budou obyvatelé její; protož hořeti budou obyvatelé země, a pozůstane lidí maličko.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 7, 'Žalostiti bude mest, usvadne vinný kmen, úpěti budou všickni veselého srdce.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 8, 'Odpočine radost bubnů, přestane hluk veselících se, utichne veselí harfy.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 9, 'Nebudou píti vína s prozpěvováním, zhořkne opojný nápoj pitelům jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 10, 'Potříno bude město marnosti; zavřín bude každý dům, aby do něho nechodili.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 11, 'Naříkání bude na ulicích pro víno, zatemněno bude všeliké veselí, odstěhuje se radost země.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 12, 'Zůstane v městě poušť, i brány zbořeny budou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 13, 'Nebo tak bude u prostřed země, u prostřed národů, jako očesání olivy, jako paběrkování, když se dokoná vinobraní.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 14, 'Tiť pozdvihnou hlasu svého, prozpěvovati budou v důstojnosti Hospodinově, prokřikovati budou i při moři.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 15, 'Protož v údolích oslavujte Hospodina, na ostrovích mořských jméno Hospodina Boha Izraelského.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 16, 'Od končin země slyšíme písničky o slávě spravedlivého. Ale já řekl jsem: Zchuravěl jsem, zchuravěl jsem. Ach, na mé hoře, že nešlechetní nešlechetnost provodí, nešlechetnost, pravím, že tak nestydatě páší.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 17, 'Hrůza a jáma a osídlo tě očekává, ó obyvateli země.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 18, 'I stane se, že kdož uteče před pověstí strachu, upadne do jámy, a kdož vyleze z jámy, v osídle uvázne; nebo průduchové s výsosti otevříni budou, a zatřesou se základové země.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 19, 'Velmi se rozstoupí země, velice se rozpadne země, náramně pohybovati se bude země.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 20, 'Motaje, motati se bude země jako opilý, a přenešena bude jako chaloupka; nebo těžce na ni dolehne nepravost její, i padne tak, že nepovstane více.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 21, 'I stane se v ten den, navštíví Hospodin vojsko vysoké na výsosti, též i krále zemské na zemi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 22, 'Kteřížto shromážděni budou, tak jako shromažďováni bývají vězňové do žaláře, a zavříni budou u vězení; po mnohých, pravím, dnech navštíveni budou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 23, 'I zahanbí se měsíc, a zastydí slunce, když kralovati bude Hospodin zástupů na hoře Sion, a v Jeruzalémě, a před starci svými slavně.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 25, 1, 'Hospodine, ty jsi Bůh můj, vyvyšovati tě budu, a oslavovati budu jméno tvé; nebo jsi učinil předivné věci. Rady tvé zdávna uložené jsou věrná pravda.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 25, 2, 'Nebo jsi obrátil město v hromadu, město hrazené v zříceninu, paláce cizozemců, aby nebyli městem, a na věky aby nebyli zase staveni.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 25, 3, 'Protož ctíti tě budou lid silný, města národů hrozných báti se tebe budou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 25, 4, 'Nebo jsi byl hradem chudému, hradem nuznému v úzkosti jeho, útočištěm před povodní, zastíněním před horkem; (nebo vzteklost ukrutníků podvrátila by zed).');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 25, 5, 'Hlučení cizozemců jsi přetrhl jako horkost v sucho, horkost stínem oblaku; zhouba ukrutných přetržena.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 25, 6, 'I učiní Hospodin zástupů všechněm národům na hoře této hody z věcí tučných, hody z vína vystálého, z věcí tučných, mozk v sobě majících, z vína vystálého a učištěného.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 25, 7, 'A zkazí na hoře této zastření, kteréž zastírá všecky lidi, a přikrytí, jímž přikryti jsou všickni národové.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 25, 8, 'Sehltí i smrt u vítězství, a setře Panovník Hospodin slzu s všeliké tváři, a pohanění lidu svého odejme ze vší země; (nebo Hospodin mluvil).');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 25, 9, 'Pročež řekne v ten den: Aj, Bůh náš tento jest, očekávaliť jsme na něj, a vysvobodil nás. Onť jest Hospodin, jehož jsme očekávali; plésati a veseliti se budeme v spasení jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 25, 10, 'Nebo odpočine ruka Hospodinova na hoře této, a mlácen bude Moáb na místě svém, jako vymlacována bývá pleva do hnoje.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 25, 11, 'A roztáhneť ruce své u prostřed něho, jako roztahuje ten, kterýž plyne k plování, a poníží pýchy jeho rameny rukou svých.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 25, 12, 'A tak pevnost i výsost zdí tvých sehne, poníží a srazí na zem až do prachu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 1, 'V ten den zpívána bude píseň tato v zemi Judské: Město máme pevné, sám Bůh spasením obdařil zdi a valy jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 2, 'Otevřete brány, ať vejde národ spravedlivý, ostříhající všeliké pravdy.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 3, 'Člověka spoléhajícího na tě ostříháš v pokoji; v pokoji, nebo v tebe doufá.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 4, 'Doufejtež v Hospodina až na věky; nebo v Hospodinu, v Hospodinu jest skála věčná.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 5, 'Ale obyvatele vysokých míst snižuje, města vyvýšeného ponižuje, ponižuje ho až k zemi, sráží je až do prachu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 6, 'Pošlapává je noha, nohy chudého, krokové nuzných.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 7, 'Cesta spravedlivého jest upřímá; stezku spravedlivého vyrovnáváš.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 8, 'Také na cestě soudů tvých, Hospodine, očekáváme na tě; ke jménu tvému a k rozpomínání se na tě patří žádost duše.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 9, 'Duše má touží po tobě v noci, nýbrž i duchem svým ve mně ráno tě hledám. Nebo když soudové tvoji dějí se na zemi, obyvatelé okršlku zemského učí se spravedlnosti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 10, 'Když se milost činí bezbožnému, neučí se spravedlnosti; v zemi pravosti neprávě činí, a nehledí na důstojnost Hospodinovu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 11, 'Hospodine, ačkoli vyvýšena jest ruka tvá, však toho nevidí. Uzříť a zahanbeni budou, závidíce lidu tvému; nadto i ohněm ty nepřátely své sehltíš.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 12, 'Nám, Hospodine, způsobíš pokoj; nebo i všecko, cožkoli se dálo při nás, dělal jsi pro dobré naše.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 13, 'Hospodine, Bože náš, panovaliť jsou nad námi páni jiní než ty, (my však toliko v tebe doufajíce, rozpomínali jsme se na jméno tvé).');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 14, 'Ale již zemřevše, neoživouť, mrtví jsouc, nevstanouť, proto že jsi je navštívil, a vyplénil, i zahladil všecku památku jejich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 15, 'Rozmnožil jsi národ, ó Hospodine, rozmnožil jsi národ, a oslaven jsi, ač jsi jej byl vzdálil do všech končin země.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 16, 'Hospodine, v úzkosti hledali tebe, vylévali prosby, když jsi je trestával.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 17, 'Jako těhotná, blížíc se ku porodu, svírá se, křičí v bolestech svých, tak jsme byli před tváří tvou, Hospodine.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 18, 'Počali jsme, svírali jsme se, jako bychom rodili vítr: však jsme žádného vysvobození nezpůsobili zemi, aniž padli obyvatelé okršlku zemského.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 19, 'Oživouť mrtví tvoji, těla mrtvá má vstanou. Prociťte a prozpěvujte, obyvatelé prachu. Nebo rosa tvá jako rosa na bylinách, ale bezbožné k zemi zporážíš.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 20, 'Ej lide můj, vejdi do pokojů svých, a zavři dvéře své za sebou; schovej se na maličkou chvilku, dokudž nepřejde hněv.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 21, 'Nebo aj, Hospodin béře se z místa svého, aby navštívil nepravost na obyvatelích země, a odkryje země zbité své, a nebude přikrývati více zmordovaných svých.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 27, 1, 'V ten den navštíví Hospodin mečem svým přísným, velikým a mocným Leviatana, hada dlouhého, a Leviatana, hada stočilého, a zabije draka, kterýž jest v moři.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 27, 2, 'V ten den o vinici výborné víno vydávající zpívejte.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 27, 3, 'Já Hospodin, kterýž ji ostříhám, každé chvilky budu ji svlažovati, a aby jí někdo neuškodil, v noci i ve dne ji ostříhati.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 27, 4, 'Prchlivosti při mně žádné není. Kdož mi dá bodlák a trn, abych proti ní válčil, a spálil ji docela?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 27, 5, 'Zdali sváže sílu mou, aby učinil se mnou pokoj, aby pravím, učinil se mnou pokoj?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 27, 6, 'Vždyť na to přijde, že se vkoření Jákob, zkvetne a zroste Izrael, a naplní okršlek zemský ovocem.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 27, 7, 'Nebo zdaliž jej tak ubil, jako ubil nepřítele jeho? Zdali jej zamordoval, jako jsou jiní zmordováni od něho?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 27, 8, 'Vedlé míry trestal jej i tehdáž, když jej zavesti dal, ješto nepřítele zachvátil větrem svým tuhým východním.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 27, 9, 'A protož tím způsobem očištěna bude nepravost Jákobova, a toť bude veliký užitek, že odejme hřích jeho, když rozmece všecko kamení oltáře jako kamení vápenné rozsypané, neostojí hájové, ani sluneční obrazové;');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 27, 10, 'Když město hrazené zpustne, a bude příbytkem zavrženým a opuštěným jako poušť, tam pásti se bude tele, a tam léhati, a pokazí docela výstřelky jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 27, 11, 'Když počne zráti žeň jeho, potřína bude; ženy přijdouce, zapálí ji. Nebo ten lid nemá žádného rozumu; protož neslituje se nad ním učinitel jeho, a stvořitel jeho neučiní jemu milosti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 27, 12, 'I stane se v ten den, když pomstu uvoditi bude Hospodin od toku řeky až do potoka Egyptského, že vy, synové Izraelští, po jednom sebráni budete.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 27, 13, 'Stane se také v ten den, že troubeno bude trubou velikou, i přijdou, kteříž byli zahynuli v zemi Assyrské, a zahnáni byli do země Egyptské, a klaněti se budou Hospodinu na hoře svaté v Jeruzalémě.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 1, 'Běda koruně pýchy, ožralcům Efraimským, květu nestálému v kráse a slávě své, těm, kteříž jsou při vrchu údolí velmi úrodného, a ztupeným od vína.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 2, 'Aj, silný a mocný Páně jako příval s krupobitím, jako povětří vyvracející, jako povodeň vod prudkých a rozvodnilých prudce až k zemi porazí.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 3, 'Nohami pošlapána bude koruna pýchy, ožralci Efraimští.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 4, 'Tehdáž stane se, že květ ten nestálý v kráse a slávě své těch, kteříž jsou při vrchu údolí velmi úrodného, bude jako ranní ovoce, prvé než léto bývá; kteréž vida někdo, nepustil by ho z ruky, až by je snědl.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 5, 'V ten den bude Hospodin zástupů korunou ozdoby, a korunou okrasy ostatkům lidu svého,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 6, 'A duchem soudu sedícímu na soudu, a silou těm, kteříž zapuzují válku až k bráně.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 7, 'Ale i ti od vína bloudí, a od opojného nápoje se potácejí. Kníže i prorok bloudí, přeplňujíce se nápojem opojným, pohlceni jsou od vína, potácejí se od nápoje opojného, bloudí u vidění, chybují v soudu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 8, 'Nebo všickni stolové plní jsou vývratků a lejn, tak že žádného místa čistého není.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 9, 'Kohož by vyučoval umění? A komu by posloužil, aby vyrozuměl naučení? Zdali ostaveným od mléka, odtrženým od prsí?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 10, 'Poněvadž měli naučení za naučením, naučení za naučením, správu za správou, správu za správou, trošku odtud, trošku od onud.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 11, 'A však jako by neznámou řečí a cizím jazykem mluvil lidu tomuto,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 12, 'Kdyžto jim řekl: Totoť jest odpočinutí, způsobte odpočinutí ustalému, toť jest, pravím, odpočinutí. Ale nechtěli slyšeti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 13, 'I bude jim slovo Hospodinovo naučení za naučením, naučení za naučením, správa za správou, správa za správou, troška odtud, troška od onud; k tomu aby šli a padajíce nazpět, setříni byli, a zapleteni jsouce, aby polapeni byli.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 14, 'Protož slyšte slovo Hospodinovo, muži posměvači, panující nad lidem tímto, kterýž jest v Jeruzalémě:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 15, 'Proto že říkáte: Učinili jsme smlouvu s smrtí, a s peklem máme srozumění, pomsta rozvodnilá, ač přecházeti bude, nepřijde na nás, jakžkoli jsme položili svod za útočiště své, a pod falší jsme se ukryli:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 16, 'Z té příčiny takto praví Panovník Hospodin: Aj, já zakládám na Sionu kámen, kámen zkušený, úhelný drahý, základ pevný; kdo věří, nebudeť kvapiti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 17, 'A vykonám soud podlé pravidla, a spravedlnost podlé závaží, i zamete to omylné útočiště krupobití, a skrýši povodeň zatopí.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 18, 'A tak zrušena bude smlouva vaše s smrtí, a srozumění vaše s peklem neostojí; a když přecházeti bude pomsta rozvodnilá, budete od ní pošlapáni.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 19, 'Jakž jen počne přecházeti, zachvátí vás; každého zajisté jitra přecházeti bude, ve dne i v noci. I stane se, že sám strach tomu, což jste slýchali, k srozumění poslouží,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 20, 'Zvlášť když bude tak krátké lůže, že se nebude lze stáhnouti, a přikrýti úzké, by se i skrčil.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 21, 'Nebo jako na hoře Perazim povstane Hospodin, jako v údolí Gabaon hněvati se bude, aby dělal dílo své, neobyčejné dílo své, aby vykonal skutek svůj, neobyčejný skutek svůj.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 22, 'A protož nebuďtež již posměvači, aby se nezadrhla osídla vaše; nebo o zkažení, a to jistém, vší země slyšel jsem ode Pána, Hospodina zástupů.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 23, 'Nastavte uší, a slyšte hlas můj; pozorujte, a poslechněte řeči mé.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 24, 'Zdaliž každého dne oře oráč, aby sel, prohání brázdy, a vláčí rolí svou?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 25, 'Zdali když srovná svrchek její, nerozsívá viky, a nerozmítá kmínu a neseje pšenice přední a ječmene výborného, i špaldy v místě příhodném?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 26, 'Nebo učí jej rozšafnosti, Bůh jeho vyučuje jej.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 27, 'Nebýváť pak okovaným smykem mlácena vika, aniž kolem vozním po kmínu se vůkol jezdí; nebo holí vytlouká se vika, a kmín prutem.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 28, 'Pšenice mlácena bývá; však i té ne vždycky mlátiti bude, aniž ji potře kolem vozu svého, ani o zuby jeho rozdrobí.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 29, 'I to od Hospodina zástupu vyšlo, kterýž jest divný v radě, a veleslavný v skutku.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 1, 'Běda Arieli, Arieli městu, v kterémž bydlil David. Přidejte rok po roku, nechať zařezují beránky.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 2, 'Však předce ssoužím Ariele. I nastane žalost a zámutek, nebo mi bude jako Ariel.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 3, 'Položím se zajisté vůkol proti tobě vojensky, a ssoužím tě bez lítosti, a vzdělám proti tobě šance.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 4, 'Tehdy sníženo jsuc, z země mluviti budeš, a z prachu šeptati bude řeč tvá; bude, pravím, jako hadače z země hlas tvůj, a z prachu řeč tvá siptěti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 5, 'Nebo jako prášku drobného bude množství nepřátel tvých, a jako plev létajících množství ukrutníků, a stane se to hned v okamžení.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 6, 'Od Hospodina zástupů navštíveno bude hromem a země třesením, a zvukem velikým, vichřicí a bouří a plamenem ohně sžírajícího.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 7, 'I budeť jako zdání vidění nočního množství všech národů bojujících proti Arieli, a všech válčících proti němu a pevnostem jeho, a ssužujících jej.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 8, 'Bude, pravím, jako když se lačnému ve snách zdá, an jí, ale když procítí, prázdný jest život jeho; a jako když se žíznivému ve snách zdá, an pije, a když procítí, žíznivým zůstává, a duše jeho vždy žádá: tak bude množství všech národů, bojujících proti hoře Sion.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 9, 'Jak zpozdilí jste, ješto byste se měli užasnouti; rozkoš provodíte, ješto byste měli na pomoc volati. Zpili se, ale ne vínem; potácejí se, ale ne od nápoje opojného.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 10, 'Nebo naplnil vás Hospodin duchem chropotu, a zavřel oči vaše; proroků i knížat vašich nejopatrnějších oči zastřel.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 11, 'Protož jest vám všeliké vidění podobné slovům knihy zapečetěné, kterouž dadí-li tomu, kterýž zná písmo, řkouce: Čti ji medle, i řekne: Nemohu, nebo zapečetěná jest.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 12, 'Pakli dadí knihu tomu, kterýž nezná písma, řkouce: Čti ji medle, tedy dí: Neznám písma.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 13, 'Nebo praví Pán: Proto že lid tento přibližuje se ústy svými, a rty svými ctí mne, srdce pak své vzdaluje a bázeň jejich, již se mne bojí, jest z přikázaní lidských pošlá:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 14, 'Z té příčiny, aj, já také divně zajdu s lidem tímto, divně, pravím, a zázračně. I zahyne moudrost moudrých jeho, a opatrnost opatrných jeho vymizí.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 15, 'Běda těm, kteříž hluboko před Hospodinem skrývají radu, jejichž každý skutek děje se v temnostech, a říkají: Kdo nás vidí? A kdo nás šetří?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 16, 'Převrácená myšlení vaše zdali nejsou podobná hlině hrnčířově? Zdali říká dílo o dělníku svém: Neučinil mne? A účinek říká-liž o učiniteli svém: Nerozuměl?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 17, 'Zdaliž po maličkém a kratičkém času neobrátí se Libán v pole, a pole za les nebude počteno?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 18, 'I uslyší v ten den hluší slova knihy, a z mrákoty a tmy oči slepých prohlédnou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 19, 'Ale tiší rozveselí se náramně v Hospodinu, a chudí lidé v Svatém Izraelském plésati budou,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 20, 'Kdyžto přestane ukrutník, a zahyne posměvač, a všickni, kteříž jsou pilni marnosti, vypléněni budou,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 21, 'Kteříž obviňují z hříchu člověka pro slovo, a na toho, kterýž je tresce, v bráně lécejí, a pro nic utiskují spravedlivého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 22, 'Protož takto dí o domu Jákobovu Hospodin, kterýž vykoupil Abrahama: Nebudeť již zahanben Jákob, aniž více tvář jeho zbledne.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 23, 'Nebo když uzří syny své, dílo rukou mých u prostřed sebe, an posvěcují jména mého, tedy posvěcovati budou Svatého Jákobova, a k bázni Boha Izraelského sloužiti,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 24, 'Aby bloudící duchem nabyli rozumnosti, a reptáci naučili se umění.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 1, 'Běda synům zpurným, dí Hospodin, skládajícím radu, kteráž není ze mne, a přikrývajícím ji přikrytím, ale ne z ducha mého, aby hřích k hříchu přidávali;');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 2, 'Kteříž chodí a sstupují do Egypta, nedotazujíce se úst mých, aby se zmocňovali v síle Faraonově, a doufali v stínu Egyptském.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 3, 'Nebo síla Faraonova bude vám k hanbě, a to odpočívání v stínu Egyptském k lehkosti,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 4, 'Proto že knížata jeho byli v Soan, a poslové jeho do Chanes chodili.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 5, 'Všeckyť k zahanbení přivede skrze lid, kterýž jim nic neprospěje, aniž bude ku pomoci, ani k užitku, ale k hanbě toliko a k útržce.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 6, 'Břímě hovad poledních v zemi nátisku a ssoužení, odkudž lev a lvíče, ještěrka a drak ohnivý létající, odnesou na hřbetě hovádek bohatství svá, a na hrbu velbloudů poklady své k lidu, kterýž jim nic neprospěje.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 7, 'Nebo Egyptští nadarmo a na prázdno pomáhati budou. Pročež ohlašuji to, že by síla jejich byla s pokojem seděti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 8, 'Nyní jdi, napiš to na tabuli před očima jejich, a na knize vyrej to, aby to zůstávalo do nejposlednějšího dne, a až na věky věků,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 9, 'Že lid tento zpurný jest, synové lháři, synové, kteříž nechtí poslouchati zákona Hospodinova;');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 10, 'Kteříž říkají vidoucím: Nemívejte vidění, a prorokům: Neprorokujte nám toho, což pravého jest; mluvte nám pochlebenství, prorokujte oklamání.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 11, 'Sejděte s cesty, svozujte od stezky, nechať se vzdálí od tváří naší Svatý Izraelský.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 12, 'Protož takto praví Svatý Izraelský: Proto že pohrdáte slovem tím, a doufáte ve lsti a v převrácenosti, a spoléháte na ni:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 13, 'Z té příčiny bude vám tato nepravost jako zed tržená padající, a vydutí na zdi vysoké, jejíž brzké a náhlé bývá oboření.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 14, 'A rozrazí ji, jako rozrážejí nádobu hrnčířskou rozbitou; neodpustíť, tak že nebude nalezena po rozražení jejím ani střepina k nabrání ohně z ohniště, anebo k nabrání vody z louže.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 15, 'Nebo tak řekl Panovník Hospodin, Svatý Izraelský: Obrátíte-li se, a spokojíte-li se, zachováni budete. V utišení se a v doufání bude síla vaše. Ale nechcete.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 16, 'Nýbrž říkáte: Nikoli, ale na koních utečeme. Protož utíkati budete. Na rychlých ujedeme. Ale rychlejší budou stihající vás.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 17, 'Jeden tisíc před okřiknutím jednoho, a před okřiknutím pěti utíkati budete, až (jestliže však vás co pozůstane), budete zanecháni jako okleštěné dřevo na vrchu hory, a jako korouhev na pahrbku.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 18, 'Protoť pak shovívá Hospodin, milost vám čině, a protoť se vyvýší, aby se smiloval nad vámi; nebo Hospodin jest Bůh spravedlivý. Blahoslavení všickni, kteříž očekávají na něj.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 19, 'Lid zajisté na Sionu a v Jeruzalémě bydliti bude. Nikoli plakati nebudeš; k hlasu volání tvého bude všelijak milost činiti s tebou. Hned jakž uslyší, ohlásíť se.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 20, 'A ačkoli Pán dá vám chleba úzkosti a vody ssoužení, však nebudou více odjati tobě učitelé tvoji, ale očima svýma vídati budeš učitele své,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 21, 'A ušima svýma slýchati slovo tobě po zadu řkoucích: Toť jest ta cesta, choďte po ní, buď že byste se na pravo neb na levo uchýlili.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 22, 'Tedy zavržete obestření rytin svých stříbrných, a oděv slitin svých zlatých; odloučíš je jako nemoc svou trpící, řka jim: Táhněte tam.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 23, 'Dáť i déšť na rozsívání tvé, kterýmž bys osíval zemi, a chléb z úrody země, kterýž bude jadrný a zdárný; v ten den pásti se bude i dobytek tvůj na pastvišti širokém.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 24, 'Volové také i oslové, dělající zemi, píci čistou jísti budou, kteráž opálkou a věječkou vyčištěna bývá.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 25, 'Budou také na všeliké hoře vysoké, a na všelikém pahrbku vyvýšeném pramenové a potokové vod, v den porážky veliké, když padnou věže.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 26, 'Bude i světlo měsíce jako světlo slunce, světlo pak slunce bude sedmernásobní, jako světlo sedmi dnů, v den, v kterýž uváže Hospodin zlámání lidu svého, a ránu zbití jeho uzdraví.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 27, 'Aj, jméno Hospodinovo přichází z daleka, jehožto hněv hořící a těžká pomsta; rtové jeho naplněni jsou prchlivostí, a jazyk jeho jako oheň sžírající.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 28, 'Duch pak jeho jako potok rozvodnilý, kterýž až do hrdla dosáhne, aby tříbil národy, až by v nic obráceni byli, a uzdou svíral čelisti národů.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 29, 'I budete zpívati, jako když se v noci zasvěcuje slavnost, a veseliti se srdečně, jako ten, kterýž jde s píšťalkou, bera se na horu Hospodinovu, k skále Izraelově,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 30, 'Když dá slyšeti Hospodin hlas důstojnosti své, a ukáže vztaženou ruku svou s hněvem prchlivosti a plamenem ohně sžírajícího, an vše rozráží i přívalem i kamenným krupobitím.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 31, 'Hlasem zajisté Hospodinovým potřín bude Assur, kterýž jiné kyjem bijíval.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 32, 'Ale stane se, že každé udeření holí, kterouž doloží na něj Hospodin, silně dolehne; s bubny a harfami a bitvou veselou bojovati bude proti němu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 33, 'Nebo připraveno jest již dávno peklo, také i samému králi připraveno jest. Hluboké a široké je učinil, hranic jeho, ohně a dříví mnoho; dmýchání Hospodinovo jako potok siry je zapaluje.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 31, 1, 'Běda těm, kteříž se utíkají do Egypta o pomoc, a v koních zpoléhají, a doufají v vozích, že jich mnoho, a v jezdcích, že jich množství veliké, a nepatří k Svatému Izraelskému, aniž Hospodina hledají,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 31, 2, 'Ještoť i on jest moudrý. Protož uvede pomstu, a nezměníť slov svých, ale povstane proti domu zlostníků a proti pomoci těch, kteříž páší nepravost.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 31, 3, 'Egyptští pak jsou lidé, a ne Bůh silný, a koni jejich tělo, a ne duch. A protož jakž jen Hospodin vztáhne ruku svou, padne i pomocník, padne i ten, jemuž byl ku pomoci; a tak jednostejně všickni ti na nic přijdou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 31, 4, 'Nebo tak řekl Hospodin ke mně: Jako když lev řve aneb lvíče nad loupeží svou, proti němuž byl-li by svolán houf pastýřů, křiku jejich se neděsí, aniž se pro hluk jejich koří: tak sstoupí Hospodin zástupů, aby bojoval o horu Sion, a o pahrbek její.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 31, 5, 'Jako ptáci létajíce, tak hájiti bude Hospodin zástupů Jeruzaléma, anobrž obhajuje vysvobodí, pomíjeje zachová.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 31, 6, 'Navraťtež se k tomu, od něhož hluboko zabředli synové Izraelští.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 31, 7, 'Nebo v ten den zavržete jeden každý modly své stříbrné a modly své zlaté, kterýchž vám nadělaly ruce vaše, abyste hřešili.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 31, 8, 'I padne Assur od meče ne muže, a meč ne člověka zžíře jej; a utíkati bude před mečem, a nejudatnější jeho pod plat uvedeni budou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 31, 9, 'A tak skála jeho pro strach zmizí, a knížata jeho korouhve děsiti se budou, praví Hospodin, jehož jest oheň na Sionu a pec v Jeruzalémě.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 1, 'Aj, v spravedlnosti kralovati bude král, a knížata v soudu panovati budou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 2, 'Nebo bude muž ten jako skrýše před větrem, a schrana před přívalem, jako potokové vod na místě suchém, jako stín skály veliké v zemi vyprahlé.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 3, 'A oči vidoucích nebudou blíkati, a uši slyšících pozorovati budou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 4, 'Pročež srdce bláznů nabude umění, a jazyk zajikavých prostranně a světle mluviti bude.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 5, 'Nebudeť více nazýván nešlechetný šlechetným, a skrbný nebude slouti štědrým.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 6, 'Proto že nešlechetný o nešlechetnosti mluví, a srdce jeho skládá nepravost, jak by provodil ošemetnost, a mluvil proti Hospodinu scestné věci, jak by znuzil duši lačného, a nápoj žíznivému odjal.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 7, 'Také i usilování skrbného jsou škodlivá; nebo nešlechetnosti obmýšlí, jak by k záhubě přivedl ponížené slovy lživými, a mluvil proti nuznému před soudem.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 8, 'Ješto šlechetný obmýšlí šlechetné věci, a takovýť při tom, což šlechetného jest, státi bude.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 9, 'Ženy lhostejné, vstaňte, slyšte hlas můj; dcery bezpečně sobě počínající, ušima pozorujte řeči mé.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 10, 'Za mnohé dny a léta vichrovány budete, ó vy v bezpečnosti bydlící; nebo přestane vinobraní, a klizení úrod nepřijde.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 11, 'Třestež se strachem, ó lhostejné, pohnětež se, bezpečně sobě počínající; svlecte se, a obnažte se, a přepašte se po bedrách.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 12, 'Kvílíce nad prsy, nad poli výbornými a nad kmeny úrodnými.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 13, 'Na zemi lidu mého trní a hloží vzejde, anobrž na všech domích veselých a městě plésajícím.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 14, 'Nebo rozkošný palác opuštěn bude, hluk města přestane, hrad vysoký a věže obráceny budou v jeskyně na věčnost, k radosti divokým oslům, a ku pastvišti stádům.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 15, 'Dokudž nebude vylit na nás duch s výsosti, a nebude obrácena poušť v pole úrodné, a pole úrodné za les počítáno.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 16, 'I bude na poušti soud bydliti, a spravedlnost na poli úrodném přebývati.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 17, 'A zjeví se skutek spravedlnosti, pokoj, ovoce, pravím, spravedlnosti, pokoj a bezpečnost až na věky.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 18, 'Nebo bydliti bude lid můj v obydlí pokojném, totiž v příbytcích nejbezpečnějších a v odpočívání nejpokojnějším,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 19, 'Byť pak i krupobití spadlo na les, a velmi sníženo bylo město.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 20, 'Blaze vám, kteříž sejete na všelikých místech úrodných, vypouštějíc tam vola i osla.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 1, 'Běda tobě, zhoubce, ješto sám nebýváš huben, a kterýž nevěrně děláš, ješto tobě nečinili nevěrně. Když přestaneš býti zhoubcím, pohuben budeš; když přestaneš nevěrně činiti, nevěrněť činiti budou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 2, 'Hospodine, učiň nám milost, na tebeť očekáváme; budiž ramenem svých každého jitra, a vysvobozením naším v čas ssoužení.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 3, 'Před zvukem hřmotu rozprchnou se národové, před vyvýšením tvým budou rozptýleni pohané.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 4, 'A sebrána bude loupež vaše, tak jako sbíráni bývají chroustové; jako připadají kobylky, tak připadnou na ni.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 5, 'Vyvýšíť se Hospodin, nebo na výsosti přebývá, a naplní Sion soudem a spravedlností.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 6, 'I bude upevněním časů tvých, silou i hojným spasením; moudrost a umění, a bázeň Hospodinova poklad tvůj.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 7, 'Aj, rekové jejich naříkali vně, jednatelé pokoje hořce plakali.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 8, 'Zpustly silnice, přestali choditi cestou; zrušil příměří, nevážil sobě měst, za nic položil sobě člověka.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 9, 'Kvílila a zemdlela země, styděti se musil Libán a usvadl; Sáron učiněn jako poušť, Bázan pak a Karmel oklácen.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 10, 'Jižť povstanu, praví Hospodin, již vyvýšen, již vyzdvižen budu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 11, 'Počnouce slámu, porodíte strniště; oheň dýchání vašeho sžíře vás.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 12, 'I budou národové vypálené vápno, trní podťaté, ohněm spáleni budou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 13, 'Slyšte dalecí, co jsem učinil, a poznejte blízcí sílu mou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 14, 'Zděsili se na Sionu hříšníci, podjala hrůza pokrytce, řkoucí: Kdož by z nás mohl ostáti před ohněm sžírajícím? Kdož by z nás mohl ostáti před plamenem věčným?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 15, 'Ten, kterýž chodí v spravedlnosti, a mluví pravé věci, kterýž pohrdá ziskem z útisku, kterýž otřásá ruce své, aby darů nepřijímal, kterýž zacpává uši své, aby neslyšel rady o vraždě, a zavírá oči své, aby se na zlé nedíval:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 16, 'Ten na vysokých místech přebývati bude, hradové na skalách útočiště jeho, tomu chléb dán bude, vody jeho stálé budou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 17, 'Krále v okrase jeho uzří oči tvé, spatří i zemi dalekou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 18, 'Srdce tvé přemyšlovati bude o strachu, řka: Kdež jest písař, kde výběrčí, kde spisovatel velikých domů?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 19, 'Lidu ukrutného neuhlédáš, lidu hluboké řeči, jíž bys neslýchal, a jazyku cizího, jemuž bys nerozuměl.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 20, 'Patř na Sion, město slavností našich, oči tvé nechať hledí na Jeruzalém, obydlí pokojné, stánek, kterýž nebude přenešen, kolíkové jeho na věky se nepohnou, a žádný provaz jeho se neztrhá;');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 21, 'Proto že velikomocný Hospodin jest nám na místě tom řekami toků širokých, po němž nepůjde lodí s vesly, aniž bárka veliká po něm přecházeti bude.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 22, 'Nebo Hospodin jest soudce náš, Hospodin ustanovitel práv našich, Hospodin král náš, onť spasí nás.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 23, 'Oslábliť jsou provazové tvoji, aniž budou moci utvrditi sloupu bárky své, ani roztáhnouti plachty, anť již rozdělena bude kořist loupeže mnohé; i chromí rozchvátají kořist.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 24, 'Aniž dí kdo z obyvatelů: Nemocen jsem. Lid osedlý v něm zproštěn bude nepravosti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 1, 'Přistuptež národové, abyste slyšeli, a lidé pozorujte. Nechať slyší země i plnost její, okršlek zemský i všeliký plod jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 2, 'Proto že hněv Hospodinův jest proti všechněm národům, a prchlivost proti všemu vojsku jejich: vyhubí je jako proklaté, a vydá je k zabití.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 3, 'I budou povrženi zbití jejich, a z těl mrtvých jejich vzejde smrad, a rozplynou se hory od krve jejich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 4, 'Chřadnouti bude i všecko vojsko nebeské, a svinuta budou nebesa jako kniha, a všecko vojsko jejich sprchne, jako prší list s vinného kmene, a jako nezralé ovoce s fíku.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 5, 'Nebo opojen jest na nebi meč můj; na Idumejské sstoupí, a na lid, na nějž jsem klatbu vydal, aby trestán byl.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 6, 'Meč Hospodinův bude plný krve, umastí se tukem a krví beranů a kozlů, tukem ledvin skopových; obět zajisté bude míti Hospodin v Bozra, a zabijení veliké v zemi Idumejské.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 7, 'Sstoupí s nimi i jednorožcové a volčata s voly, i opije se země jejich krví, a prach jejich tukem se omastí.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 8, 'Nebo den pomsty Hospodinovy, léto odplacování se, aby mštěno bylo Siona.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 9, 'A obráceni budou potokové její v smolu, a prach její v siru, a země její obrátí se v smolu hořící.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 10, 'V noci ani ve dne neuhasne, na věky vystupovati bude dým její, od národu až do pronárodu pustá zůstane, na věky věků nebude, kdo by šel přes ni.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 11, 'Ale osednou ji pelikán a výr, kalous také a krkavec budou bydliti v ní, a roztáhne po ní šňůru zahanbení a závaží marnosti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 12, 'Šlechticů jejích volati budou k království, ale nebude tam žádného, nebo všecka knížata její zhynou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 13, 'A vzroste na palácích jejích trní, kopřivy a bodláčí na hradích jejích, a bude příbytkem draků a obydlím sov.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 14, 'Tam se budou potkávati spolu zvěř s ptactvem, a příšera jedna druhé se ozývati; tam toliko noční přeluda se usadí, a odpočinutí sobě nalezne.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 15, 'Tam se zhnízdí sup, a škřečeti bude, a když vysedí, shromáždí je pod stín svůj; tam také shledají se luňáci jeden s druhým.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 16, 'Hledejte v knize Hospodinově, a čtěte. Ani jedno z těch nechybí, a jeden každý bez své druže nebude; nebo to ústa Páně přikázala, a duch jeho shromáždí je.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 17, 'Onť zajisté vrže jim losy, a ruka jeho jim rozdělí ji provazcem; až na věky dědičně ji osednou, od národu až do pronárodu v ní přebývati budou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 35, 1, 'Veseliti se budou z toho poušť a pustina, plésati, pravím, bude poušť, a zkvetne jako růže.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 35, 2, 'Ušlechtile zkvetne, ano i radostně plésati bude s prozpěvováním. Sláva Libánská dána jí bude, okrasa Karmelská a Sáronská. Tyť věci uzří slávu Hospodinovu, důstojnost Boha našeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 35, 3, 'Posilňtež rukou opuštěných, a kolena klesající utvrďte.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 35, 4, 'Rcete těm, kteříž jsou bázlivého srdce: Posilňte se, nebojte se. Aj, Bůh váš s pomstou přijde, s odplatou Bůh sám přijde, a spasí vás.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 35, 5, 'Tehdáž otevrou se oči slepých, otevrou se též i uši hluchých.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 35, 6, 'Tehdáž poskočí kulhavý jako jelen, a jazyk němého prozpěvovati bude; nebo se vyprýští vody na poušti, a potokové na pustinách.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 35, 7, 'A obrátí se místo vyprahlé v jezero, a žíznivé v prameny vod; v doupatech draků, v pelešech jejich tráva, třtí a sítí.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 35, 8, 'Bude také tam silnice a cesta, kteráž cestou svatou slouti bude. Nepůjde po ní nečistý, ale bude samých těchto; tou cestou jdoucí i nejhloupější nezbloudí.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 35, 9, 'Nebude tam lva, a lítá zvěř nebude choditi po ní, aniž tam nalezena bude, ale půjdou po ní ti, jenž budou vysvobozeni.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 35, 10, 'Vykoupení, pravím, Hospodinovi navrátí se, a přijdou na Sion s prozpěvováním, a veselé věčné bude na hlavě jejich; radosti a veselé dojdou, zámutek pak a úpění uteče od nich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 1, 'Stalo se pak čtrnáctého léta kralování Ezechiášova, přitáhl Senacherib král Assyrský proti všechněm městům Judským hrazeným, a zdobýval jich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 2, 'I poslal král Assyrský Rabsaka z Lachis do Jeruzaléma k králi Ezechiášovi s vojskem velikým. Kterýž se postavil u struhy rybníka hořejšího, při silnici pole valchářova.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 3, 'Tedy vyšel k němu Eliakim syn Helkiášův, kterýž byl správce domu, a Sobna písař, a Joach syn Azafův, kancléř.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 4, 'I mluvil k nim Rabsaces: Povězte medle Ezechiášovi: Toto praví král veliký, král Assyrský: Jakéž jest to doufání, na kterémž se zakládáš?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 5, 'Řekl jsem: Jistě žeť jest věc daremní; radyť jest a síly k válce potřebí. A protož v koho doufáš, že mi se protivíš?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 6, 'Aj, spolehl jsi na hůl třtiny té nalomené, na Egypt, na niž zpodepřel-li by se kdo, pronikne ruku jeho, a probodne ji. Takovýť jest Farao král Egyptský všechněm, kteříž v něm doufají.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 7, 'Pakli mi díš: V Hospodinu Bohu svém doufáme: zdaliž on není ten, jehož pobořil Ezechiáš výsosti i oltáře, a přikázal Judovi a Jeruzalému, řka: Před tímto oltářem klaněti se budete?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 8, 'Ale nu, potkej se medle se pánem mým králem Assyrským. Přidámť ještě dva tisíce koní, můžeš-li jen míti, kdo by na nich jeli.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 9, 'Jakž tedy odoláš jednomu knížeti z nejmenších služebníků pána mého, ačkoli máš doufání v Egyptu pro vozy a jezdce?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 10, 'Přesto, zdali jsem bez Hospodina přitáhl do země této, abych ji zkazil? Hospodin řekl mi: Táhni na tu zemi, a zkaz ji.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 11, 'I řekl Eliakim a Sobna a Joach Rabsakovi: Mluv medle k služebníkům svým Syrsky, však rozumíme, a nemluv k nám Židovsky před lidem tímto, kterýž jest na zdech.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 12, 'I odpověděl Rabsaces: Zdaliž ku pánu tvému a k tobě poslal mne pán můj, abych mluvil slova tato? Však k mužům těm, kteříž jsou na zdech, aby lejna svá jedli, a moč svůj spolu s vámi pili.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 13, 'A tak stoje Rabsaces, volal hlasem velikým Židovsky, a řekl: Slyšte slova krále velikého, krále Assyrského:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 14, 'Toto praví král: Nechť vás nesvodí Ezechiáš, neboť nebude moci vyprostiti vás.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 15, 'A nechť vám nevelí Ezechiáš doufati v Hospodina, řka: Zajisté vysvobodí nás Hospodin, a nebudeť dáno město toto v ruku krále Assyrského.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 16, 'Neposlouchejte Ezechiáše. Nebo takto praví král Assyrský: Učiňte mi to k líbosti, a vyjděte ke mně, i bude moci jísti jeden každý z vinice své, a jeden každý z fíku svého, a píti jeden každý vodu z čisterny své,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 17, 'Dokudž nepřijdu, a nepoberu vás do země podobné zemi vaší, do země úrodné, země chleba a vinic.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 18, 'Nechť vás nesvodí Ezechiáš, řka: Hospodin vysvobodí nás. Zdaliž mohli vysvoboditi bohové národů jeden každý zemi svou z ruky krále Assyrského?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 19, 'Kde jsou bohové Emat a Arfad? Kde jsou bohové Sefarvaim? Zdaliž jsou vysvobodili i Samaří z ruky mé?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 20, 'Kteří jsou mezi všemi bohy těch zemí, ješto by vysvobodili zemi svou z ruky mé? Aby pak Hospodin měl vysvoboditi Jeruzalém z ruky mé?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 21, 'Oni pak mlčeli, a neodpověděli jemu slova. Nebo takové bylo rozkázaní královo, řkoucí: Neodpovídejte jemu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 22, 'I přišel Eliakim syn Helkiášův, kterýž byl správcím domu, a Sobna písař, a Joach syn Azafův, kancléř, k Ezechiášovi, majíce roucha roztržená, a oznámili jemu slova Rabsakova.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 1, 'I stalo se, když to uslyšel král Ezechiáš, že roztrhl roucho své, a oděl se žíní, a všel do domu Hospodinova.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 2, 'I poslal Eliakima správce domu, a Sobnu písaře, a starší z kněží, oblečené v žíně k Izaiášovi proroku, synu Amosovu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 3, 'Kteříž řekli jemu: Toto praví Ezechiáš: Den úzkosti a útržky i rouhání jest den tento, proto že se přiblížil plod k vyjití, ale není síly ku porodu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 4, 'Ó by slyšel Hospodin Bůh tvůj slova Rabsakova, jehož poslal král Assyrský pán jeho, aby utrhal Bohu živému, a pomstil Hospodin Bůh tvůj těch slov, kteráž slyšel. Protož pozdvihni modlitby za tento ostatek lidu, kterýž se nalézá.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 5, 'I přišli služebníci krále Ezechiáše k Izaiášovi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 6, 'Jimž odpověděl Izaiáš: Toto povíte pánu svému: Takto praví Hospodin: Nestrachuj se slov těch, kteráž jsi slyšel, jimiž se mně rouhali služebníci krále Assyrského.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 7, 'Aj, já pustím naň vítr, aby uslyše pověst, navrátil se do země své, a učiním to, že padne od meče v zemi své.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 8, 'Navrátiv se pak Rabsaces, nalezl krále Assyrského, an dobývá Lebna. Nebo uslyšel, (pročež odtrhl od Lachis),');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 9, 'Uslyšel, pravím, o Tirhákovi králi Mouřenínském, ano pravili: Táhne, aby bojoval s tebou. A však uslyšev to, vždy poslal posly své k Ezechiášovi s těmito slovy:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 10, 'Takto povíte Ezechiášovi králi Judskému, řkouce: Nechť tebe nesvodí Bůh tvůj, v němž ty doufáš, říkaje: Nebude dán Jeruzalém v ruku krále Assyrského.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 11, 'Aj, slyšels, co jsou učinili králové Assyrští všechněm zemím, pohubivše je, a ty bys měl býti vysvobozen?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 12, 'Zdaliž jsou je vysvobodili bohové těch národů, kteréž zahladili předkové moji, Gozana, Charana, Resefa a syny z Eden, kteříž byli v Telasar?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 13, 'Kde jest král Emat, a král Arfad, a král města Sefarvaim, Ana i Ava?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 14, 'Protož vzav Ezechiáš list z ruky poslů, přečtl jej a vstoupiv do domu Hospodinova, rozvinul jej Ezechiáš před Hospodinem.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 15, 'A modlil se Ezechiáš Hospodinu, řka:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 16, 'Hospodine zástupů, Bože Izraelský, kterýž sedíš nad cherubíny, ty jsi sám Bůh všech království země, ty jsi učinil nebe i zemi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 17, 'Nakloniž, Hospodine, ucha svého a uslyš; otevři, Hospodine, oči své a pohleď; slyš, pravím, všecka slova Senacheribova, kterýž poslal k činění útržek Bohu živému.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 18, 'Takť jest, Hospodine, žeť jsou pohubili králové Assyrští všecky ty krajiny i zemi jejich,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 19, 'A uvrhli bohy jejich do ohně; nebo nebyli bohové, ale dílo ruku lidských, dřevo a kámen, protož zahladili je.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 20, 'A nyní, Hospodine Bože náš, vysvoboď nás z ruky jeho, aťby poznala všecka království země, že jsi ty Hospodin sám.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 21, 'Tedy poslal Izaiáš syn Amosův k Ezechiášovi, řka: Toto praví Hospodin Bůh Izraelský: Zač jsi mi se modlil strany Senacheriba krále Assyrského,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 22, 'Totoť jest slovo, kteréž mluvil Hospodin o něm: Pohrdá tebou, a posmívá se tobě panna, dcera Sionská, potřásá hlavou za tebou dcera Jeruzalémská.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 23, 'Kohož jsi zhaněl? A komus se rouhal? A proti komus povýšil hlasu, a pozdvihl zhůru očí svých? Proti Svatému Izraelskému.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 24, 'Skrze služebníky své utrhal jsi Pánu, a řekl jsi: Ve množství vozů svých já jsem vytáhl na hory vysoké, na stráně Libánské, a zpodtínám vysoké cedry jeho, i spanilé jedle jeho, a vejdu na nejvyšší kraj jeho do lesů a výborných rolí jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 25, 'Já jsem vykopal a pil vody; nebo jsem vysušil nohama svýma všecky potoky míst obležených.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 26, 'Zdalis neslyšel, že jsem již to dávno učinil, a ode dnů starých to sformoval? Nyní pak k tomu přivozuji, aby v poušť a v hromady rumu města hrazená obrácena byla,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 27, 'A jejich obyvatelé ruce oslablé majíc, předěšeni a zahanbeni jsouc, byli jako bylina polní, a zelina vzcházející, jako tráva na střechách, a osení rzí zkažené, prvé než by dorostlo.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 28, 'Sedání pak tvé, a vycházení tvé i vcházení tvé znám, i vzteklost tvou proti sobě.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 29, 'Poněvadž ty se vztěkáš proti mně, a tvé zpouzení přišlo v uši mé, protož vpustím udici svou v chřípě tvé, a udidla svá v ústa tvá, a odvedu tě zase tou cestou, kterouž jsi přišel.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 30, 'A toto měj za znamení: Budete jísti roku prvního, co samo od sebe zroste, též druhého roku, což se samo od sebe zrodí, třetího pak roku budete síti a žíti a štěpovati vinice, a jísti ovoce jejich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 31, 'Ostatek zajisté domu Judova, kterýž pozůstal, vpustí zase kořeny své hluboce, a vydá užitek zhůru.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 32, 'Nebo z Jeruzaléma vyjdou ostatkové, a zachovaní z hory Siona. Horlivost Hospodina zástupů učiní to.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 33, 'A protož toto praví Hospodin o králi Assyrském: Nevejdeť do města tohoto, aniž sem střely vstřelí, aniž na ně dotrou pavézníci, aniž udělají u něho náspu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 34, 'Cestou, kterouž přitáhl, zase navrátí se, a do města tohoto nevejde, praví Hospodin.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 35, 'Nebo chrániti budu města tohoto, abych je zachoval pro sebe a pro Davida služebníka svého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 36, 'Tedy vyšel anděl Hospodinův, a zbil v vojště Assyrském sto osmdesáte a pět tisíců. I vstali velmi ráno, a aj, všickni mrtví.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 37, 'A tak odjel, anobrž utekl, a navrátil se Senacherib král Assyrský, a bydlil v Ninive.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 38, 'I stalo se, když se klaněl v chrámě Nizrocha boha svého, že Adramelech a Sarasar, synové jeho, zabili jej mečem, a utekli do země Ararat. I kraloval Esarchaddon syn jeho místo něho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 1, 'V těch dnech roznemohl se Ezechiáš až k smrti. I přišel k němu Izaiáš syn Amosův, prorok, a řekl jemu: Toto praví Hospodin: Zřeď dům svůj, nebo umřeš, a nebudeš živ.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 2, 'I obrátil Ezechiáš tvář svou k stěně, a modlil se Hospodinu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 3, 'A řekl: Prosím, ó Hospodine, rozpomeň se nyní, že jsem stále chodil před tebou v pravdě a v srdci upřímém, a že jsem to činil, což dobrého jest před očima tvýma. I plakal Ezechiáš pláčem velikým.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 4, 'Tedy stalo se slovo Hospodinovo k Izaiášovi, řkoucí:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 5, 'Jdi a rci Ezechiášovi: Toto praví Hospodin Bůh Davida otce tvého: Slyšelť jsem modlitbu tvou, viděl jsem slzy tvé; aj, já přidám ke dnům tvým patnácte let.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 6, 'A z ruky krále Assyrského vysvobodím tě i město toto, a chrániti budu města tohoto.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 7, 'A toto budeš míti znamení od Hospodina, že Hospodin učiní věc tuto, kterouž mluvil:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 8, 'Aj, já navrátím zpátkem stín po stupních, po nichž sešel na hodinách slunečných Achasových, o deset stupňů. I navrátilo se slunce o deset stupňů, po týchž stupních, po nichž bylo sešlo.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 9, 'Zapsání Ezechiáše krále Judského, když nemocen byl, a ozdravěl po nemoci své:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 10, 'Jáť jsem byl řekl v přestřižení dnů svých, že vejdu do bran hrobu, zbaven budu ostatku let svých.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 11, 'Řekl jsem byl, že neuzřím Hospodina, Hospodina v zemi živých, nebudu vídati člověka více mezi přebývajícími na světě.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 12, 'Přebývání mé pomíjí, a stěhuje se ode mne jako stánek pastýřský; přestřihl jsem jako tkadlec život svůj, od třísní odřeže mne. Dnes dříve než noc přijde, učiníš mi konec.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 13, 'Předkládal jsem sobě v jitře, že jako lev tak potře všecky kosti mé, dnes dříve než noc přijde, že mi učiníš konec.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 14, 'Jako řeřáb a vlaštovice pištěl jsem, lkal jsem jako holubice, oči mé zhůru pozdvižené byly. Pane, násilé trpím, ó prodliž mi života.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 15, 'Ale coť mám více mluviti? I předpověděl mi, i učinil, že živ pobudu mimo všecka léta svá po hořkosti duše své.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 16, 'Pane, kdo po nich i v nich živi budou, všechněm znám bude život dýchání mého, žes mi zdraví navrátil, a mne při životu zachoval.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 17, 'Aj, v čas pokoje potkala mne byla hořkost nejhořčejší, ale tobě zalíbilo se vytrhnouti duši mou z propasti zkažení, proto že jsi zavrhl za hřbet svůj všecky hříchy mé.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 18, 'Nebo ne hrob oslavuje tebe, ani smrt tě chválí, aniž očekávají ti, jenž do jámy sstupují, pravdy tvé.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 19, 'Ale živý, živý, tenť oslavovati bude tebe, jako já dnes, a otec synům v známost uvodí pravdu tvou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 20, 'Hospodin vysvobodil mne, a protož písně mé zpívati budeme po všecky dny života našeho v domě Hospodinově.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 21, 'Řekl pak byl Izaiáš: Nechať vezmou hrudu suchých fíků, a přiloží na vřed, a zdráv bude.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 22, 'I řekl byl Ezechiáš: Jaké jest znamení, že vstoupím do domu Hospodinova?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 39, 1, 'Toho času poslal Merodach Baladan syn Baladanův, král Babylonský, list a dary Ezechiášovi, když uslyšel, že nemocen byv, zase ozdravěl.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 39, 2, 'I zradoval se z toho Ezechiáš, a ukázal jim dům klénotů svých, stříbra a zlata a vonných věcí, a olej nejvýbornější, tolikéž dům zbroje své, a cožkoli mohlo nalezeno býti v pokladích jeho. Ničeho nebylo, čehož by jim neukázal Ezechiáš v domě svém i ve všem panství svém.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 39, 3, 'V tom přišel prorok Izaiáš k králi Ezechiášovi, a řekl jemu: Co pravili ti muži? A odkud přišli k tobě? I odpověděl Ezechiáš: Z země daleké přišli ke mně, z Babylona.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 39, 4, 'Řekl ještě: Co jsou viděli v domě tvém? Odpověděl Ezechiáš: Všecko, což jest v domě mém, viděli. Ničeho není v pokladích mých, čehož bych jim neukázal.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 39, 5, 'Tedy řekl Izaiáš Ezechiášovi: Slyšiž slovo Hospodina zástupů:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 39, 6, 'Aj, dnové přijdou, že odneseno bude do Babylona, cožkoli jest v domě tvém, a cožkoli nachovali otcové tvoji, až do tohoto dne; nezůstaneť ničeho, (praví Hospodin).');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 39, 7, 'I syny tvé také, kteříž pojdou z tebe, kteréž zplodíš, poberou, a budou komorníci při dvoře krále Babylonského.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 39, 8, 'Tedy řekl Ezechiáš Izaiášovi: Dobréť jest slovo Hospodinovo, kteréž jsi mluvil. (A doložil): Proto že pokoj a pravda bude za dnů mých.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 1, 'Potěšujte, potěšujte lidu mého, dí Bůh váš.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 2, 'Mluvte k srdci Jeruzaléma, a ohlašujte jemu, že se již doplnil čas uložený jeho, že jest odpuštěna nepravost jeho, a že vzal z ruky Hospodinovy dvojnásobně za všecky hříchy své.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 3, 'Hlas volajícího: Připravtež na poušti cestu Hospodinovu, přímou učiňte na pustině stezku Boha našeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 4, 'Každé údolí ať jest vyvýšeno, a všeliká hora i pahrbek ať jest snížen; což jest křivého, ať jest přímé, a místa nerovná ať jsou rovinou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 5, 'Nebo se zjeví sláva Hospodinova, a uzří všeliké tělo spolu, že ústa Hospodinova mluvila.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 6, 'Hlas řkoucího: Volej. I řekl: Co mám volati? To, že všeliké tělo jest tráva, a všeliká vzácnost jeho jako květ polní.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 7, 'Usychá tráva, květ prší, jakž vítr Hospodinův povane na něj. V pravděť jsou lidé ta tráva.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 8, 'Usychá tráva, květ prší, ale slovo Boha našeho zůstává na věky.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 9, 'Na horu vysokou vystup sobě, Sione, zvěstovateli věcí potěšených, povyš mocně hlasu svého, Jeruzaléme, zvěstovateli věcí potěšených, povyš, aniž se boj. Rci městům Judským: Aj, Bůh váš.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 10, 'Aj, Panovník Hospodin proti silnému přijde, a rámě jeho panovati bude nad ním; aj, mzda jeho s ním, a dílo jeho před ním.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 11, 'Jako pastýř stádo své pásti bude, do náručí svého shromáždí jehňátka, a v klíně svém je ponese, březí pak poznenáhlu povede.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 12, 'Kdo změřil hrstí svou vody, a nebesa pídí rozměřil? A kdo změřil měrou prach země, a zvážil na váze hory, a pahrbky na závaží?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 13, 'Kdo vystihl ducha Hospodinova, a rádcím jeho byl, že by mu oznámil?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 14, 'S kým se radil, že by mu přidal srozumění, a naučil jej stezce soudu, a vyučil jej umění, a cestu všelijaké rozumnosti jemu v známost uvedl?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 15, 'Aj, národové jako krůpě od okova, a jako prášek na vážkách se počítají, ostrovy jako nejmenší věc zachvacuje.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 16, 'Ani Libán nepostačil by k zanícení ohně, a živočichové jeho nepostačili by k zápalné oběti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 17, 'Všickni národové jsou jako nic před ním, za nic a za marnost pokládají se u něho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 18, 'K komu tedy připodobníte Boha silného? A jaké podobenství přirovnáte jemu?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 19, 'Jakžkoli rytinu líčí řemeslník, a zlatník zlatem ji potahuje, a řetízky stříbrné k ní slévá;');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 20, 'A ten, kterýž pro chudobu nemá co obětovati, dřevo, kteréž by nepráchnivělo, vybírá, a řemeslníka umělého sobě hledá k přistrojení rytiny, aby se nepohnula.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 21, 'Zdaliž nevíte? Zdaliž neslýcháte? Zdaliž se vám nezvěstuje od počátku? Zdaliž nesrozumíváte z základů země?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 22, 'Ten, kterýž sedí nad okršlkem země, jejížto obyvatelé jako kobylky, kterýž rozprostřel jako kortýnu nebesa, a roztáhl je jako stánek k přebývání,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 23, 'Onť přivodí knížata na nic, soudce zemské jako nic rozptyluje,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 24, 'Tak že nebývají štípeni ani sáti, aniž kořene pouští do země pařez jejich. Nebo jakž jen zavane na ně, hned usychají, a vicher jako plevu zanáší je.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 25, 'K komu tedy připodobníte mne, abych podobný byl jemu, praví Svatý?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 26, 'Pozdvihněte zhůru očí svých, a vizte, kdo to stvořil? Kdo vyvodí v počtu vojsko jejich, a všeho toho zejména povolává? Vedlé množství síly a veliké moci ani jedno z nich nehyne.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 27, 'Pročež tedy říkáš, Jákobe, a mluvíš, Izraeli: Skrytať jest cesta má před Hospodinem, a pře má před Boha mého nepřichází?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 28, 'Zdaliž nevíš, zdaž jsi neslýchal, že Bůh věčný Hospodin, kterýž stvořil končiny země, neustává ani zemdlívá, a že vystižena býti nemůže moudrost jeho?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 29, 'On dává ustalému sílu, a tomu, ješto žádné síly nemá, moci hojně udílí.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 30, 'Ustává a umdlévá mládež, a mládenci těžce klesají,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 31, 'Ale ti, jenž očekávají na Hospodina, nabývají nové síly. Vznášejí se peřím jako orlice; běží, a však neumdlévají, chodí, a neustávají.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 1, 'Umlknětež přede mnou ostrovové, a národové nechať se ssilí, nechať přistoupí, a tu ať mluví. Přistupmež spolu k soudu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 2, 'Kdo vzbudil od východu spravedlivého, aby ho následoval? Kdo jemu podmanil národy, a způsobil, aby nad králi panoval, vydav je jako prach meči jeho, a jako plevy rozptýlené lučišti jeho?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 3, 'Sháněje se s nimi, prošel pokojně cestou, po níž nohama svýma nechodíval.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 4, 'Kdo to spravil a učinil, povolávaje rodin od počátku? Já Hospodin, první i poslední, já sám.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 5, 'Viděli ostrovové, a ulekli se, končiny země předěsily se, shromáždili se a sešli.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 6, 'Jeden druhému pomáhal, a bratru svému říkal: Posilň se.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 7, 'A tak posilňoval tesař zlatníka, vyhlazujícího kladivo tlučením na nákovadlí, říkaje: K sletování toto dobré jest. I utvrdil to hřebíky, aby se nepohnulo.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 8, 'Ale ty, Izraeli služebníče můj, ty Jákobe, kteréhož jsem vyvolil, símě Abrahama, přítele mého,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 9, 'Ty, kteréhož jsem vychvátil od končin země, nýbrž pominuv přednějších jejich, povolal jsem tě, řka tobě: Služebník můj jsi, vyvolil jsem tě, aniž jsem zavrhl tebe.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 10, 'Nebojž se, nebo jsem já s tebou; nestrachujž se, nebo já jsem Bůh tvůj. Posilním tě, a pomáhati budu tobě, a podpírati tě budu pravicí spravedlnosti své.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 11, 'Aj, zastydí se, a zahanbeni budou všickni, kteříž se zlobí proti tobě; v nic obráceni budou, a zahynou ti, kteříž tobě odporují.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 12, 'Hledal-li bys jich, nenalezneš jich. Ti, kteříž se s tebou nesnadní, v nic obráceni budou, a na nic přijdou ti, jenž s tebou válčí.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 13, 'Nebo já, Hospodin Bůh tvůj, ujal jsem tě za tvou pravici, a pravímť: Neboj se, já tobě pomáhati budu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 14, 'Neboj se, červíčku Jákobův, hrstko Izraelova, já spomáhati budu tobě, praví Hospodin, a vykupitel tvůj, Svatý Izraelský.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 15, 'Aj, učinil jsem tě jako smyk i s zuby novými po obou stranách; pomlátíš hory, a zetřeš je, a s pahrbky jako s plevami naložíš.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 16, 'Převěješ je, v tom je vítr zachvátí, a vicher rozptýlí, ty pak plésati budeš v Hospodinu, v Svatém Izraelském chlubiti se budeš.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 17, 'Chudé a nuzné, kteříž hledají vody, an jí není, jejichž jazyk žízní prahne, já Hospodin vyslyším, já Bůh Izraelský neopustím jich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 18, 'Vyvedu na vysokých místech řeky, a u prostřed rovin studnice; obrátím poušť v jezero vod, a zemi vyprahlou v prameny vod.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 19, 'Nasadím na poušti cedrů, výborných cedrů, myrtoví, a olivoví; vysadím poušť jedlovím, jilmem, též i pušpanem,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 20, 'Aby viděli, a poznali, a rozvažujíce, srozuměli, že to ruka Hospodinova učinila, a Svatý Izraelský že to stvořil.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 21, 'Veďte při svou, praví Hospodin, ukažte mocné důvody své, dí král Jákobův.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 22, 'Nechať přistoupí, a nechť nám oznámí to, což se státi má. Věci prvé stalé oznamte, abychom povážili v srdci svém, a poznali cíl jejich, aneb aspoň co jest budoucího, povězte nám.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 23, 'Oznamte, co se budoucně státi má, a poznáme, že bohové jste. Pakli, učiňte něco dobrého neb zlého, abychom se děsili, když bychom to viděli spolu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 24, 'Aj, vy naprosto nic nejste, a dílo vaše tolikéž nic není; protož ohavnýť jest, kdo vás zvoluje.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 25, 'Vzbudím od půlnoci, ten přitáhne, od východu slunce, ten svolá ve jménu mém, a oboří se na knížata jako na bláto, a pošlapá je jako hrnčíř hlinu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 26, 'Kdo oznámí od počátku, abychom věděli, aneb od starodávna, abychom řekli: Práv jest? Naprosto žádného není, kdo by oznámil, aniž jest kdo, ješto by se dal slyšeti, aneb ješto by slyšel řeči vaše.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 27, 'Já jsem první, kterýž Sionu předpovídám: Aj, aj, teď jsou; a Jeruzalému: Zvěstovatele potěšených věcí dám.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 28, 'Nebo vidím, že není žádného, není žádného mezi nimi rozumného; ač se jich otazuji, však neodpovídají slova.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 29, 'Aj, všickni ti jsou marnost, za nic nestojí dílo jejich, vítr a daremní věc jsou slitiny jejich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 1, 'Aj, služebník můj, na kteréhož se zpodepru, vyvolený můj, jehož libuje duše má. Ducha svého dám jemu, onť soud národům vynášeti bude.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 2, 'Nebude křičeti, ani se vyvyšovati, ani slyšán bude vně hlas jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 3, 'Třtiny nalomené nedolomí, a lnu kouřícího se neuhasí, ale soud podlé pravdy vynášeti bude.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 4, 'Nebude neochotný, ani přísný, dokudž soudu na zemi nevykoná, a učení jeho ostrovové očekávati budou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 5, 'Tak praví Bůh silný Hospodin, kterýž stvořil nebesa, a roztáhl je, kterýž rozšířil zemi, i to, což z ní pochází, kterýž dává dýchání lidu na ní, a ducha těm, jenž chodí po ní.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 6, 'Já Hospodin povolal jsem tě v spravedlnosti, a ujal jsem tě za ruku tvou; protož ostříhati tě budu, a dám tě v smlouvu lidu, a za světlo národům,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 7, 'Abys otvíral oči slepé, a vyvodil z žaláře vězně, a z vězení ty, kteříž sedí ve tmách.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 8, 'Já jsem Hospodin, toť jest jméno mé, a slávy své jinému nedám, ani chvály své rytinám.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 9, 'Aj, prvnější věci přišly, a i nové předpovídaje, dříve než se začnou, dám o nich slyšeti vám.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 10, 'Zpívejte Hospodinu píseň novou, chvála jeho jest od končin země, kteříž se plavíte po moři, i všecko, což v něm jest, ostrovové i obyvatelé jejich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 11, 'Pozdvihněte hlasu pustiny i města její, i vsi, v nichž bydlí Cedar, prokřikujte obyvatelé skal, s vrchu hor volejte.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 12, 'Vzdejte slávu Hospodinu, a chválu jeho na ostrovích zvěstujte.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 13, 'Hospodin jako silný rek vyjde, jako muž válečný rozhorlí se, troubiti, anobrž i prokřikovati bude, a proti nepřátelům svým zmužile sobě počínati, řka:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 14, 'Mlčel jsem dosti dlouho, činil jsem se neslyše, zdržoval jsem se, ale již jako pracující ku porodu křičeti budu, pohubím a sehltím vše pojednou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 15, 'V pustinu obrátím hory i pahrbky, a všelikou bylinu jejich usuším, a obrátím řeky v ostrovy, a jezera vysuším.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 16, 'I povedu slepé po cestě, kteréž neznali, a po stezkách, kterýchž neuměli, provedu je; obrátím před nimi tmu v světlo, a co nerovného, v rovinu. Toť jest, což jim učiním, a neopustím jich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 17, 'Obrátí se zpět, zahanbeni budou ti, kteříž doufají v rytinu, kteříž říkají slitinám: Vy jste bohové naši.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 18, 'Ó hluší, slyštež, a vy slepí, prohlédněte, abyste viděli.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 19, 'Kdo jest to slepý, jediné služebník můj? A hluchý, než posel můj, kteréhož posílám? Kdo slepý tak jako dokonalý? Slepý, pravím, jako služebník Hospodinův?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 20, 'Hledě na mnohé věci, však nesrozumívá; otevřené maje uši, však neslyší.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 21, 'Mělť jest Hospodin líbost v něm pro spravedlnost svou, zvelebil jej zákonem, a slavného učinil.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 22, 'Že pak lid tento obloupený jest a potlačený, jehožto mládence, což jich koli, jímají a do žalářů skrývají, že jsou dáni v loupež, aniž jest, kdo by je vytrhl, v rozchvátání, aniž jest, kdo by řekl: Navrať zase,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 23, 'Kdo z vás ušima pozoruje toho, srozumívá tomu, aby se bedlivěji chtěl míti napotom?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 24, 'Kdo vydal v potlačení Jákoba, a Izraele loupežníkům? Zdali ne Hospodin, proti němuž jsme zhřešili? Nebo nechtěli po cestách jeho choditi, aniž poslouchali zákona jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 25, 'A protož vylil na něj s prchlivostí hněv svůj, a násilé boje, a zapálil jej vůkol, a však nepoznal toho. Zapálil jej, pravím, a však nepřipustil toho k srdci.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 1, 'Ale nyní takto praví Hospodin stvořitel tvůj, ó Jákobe, a učinitel tvůj, ó Izraeli: Neboj se, nebo vykoupil jsem tě, a povolal jsem tě jménem tvým. Můj jsi ty.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 2, 'Když půjdeš přes vody, s tebou budu, pakli přes řeky, nepřikvačí tě; půjdeš-li přes oheň, nespálíš se, aniž plamen chytí se tebe.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 3, 'Nebo já Hospodin Bůh tvůj, Svatý Izraelský, jsem spasitel tvůj. Dal jsem na výplatu za tebe Egypt, zemi Mouřenínskou a Sábu místo tebe.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 4, 'Hned jakž jsi drahým učiněn před očima mýma, zveleben jsi, a já jsem tě miloval; protož dal jsem lidi za tebe, a národy za život tvůj.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 5, 'Nebojž se, nebo já s tebou jsem. Od východu zase přivedu símě tvé, a od západu shromáždím tě.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 6, 'Dím půlnoční straně: Navrať, a polední: Nezbraňuj. Přiveď zase syny mé zdaleka, a dcery mé od končin země,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 7, 'Každého toho, jenž se nazývá jménem mým, a kteréhož jsem k slávě své stvořil, jejž jsem sformoval, a kteréhož jsem učinil.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 8, 'Vyveď lid slepý, kterýž již má oči, a hluché, kteříž již mají uši.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 9, 'Všickni národové nechať se spolu shromáždí, a sberou se lidé. Kdo jest mezi nimi, ješto by to zvěstoval, a to, což se předně státi má, aby oznámil nám? Nechť vystaví svědky své, a spravedlivi budou, aneb ať slyší, a řeknou: Pravdať jest.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 10, 'Vy svědkové moji jste, praví Hospodin, a služebník můj, kteréhož jsem vyvolil, tak že můžete věděti, a mně věřiti, i rozuměti, že já jsem, a že přede mnou nebyl sformován Bůh silný, aniž po mně bude.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 11, 'Já, já jsem Hospodin, a žádného není kromě mne spasitele.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 12, 'Já oznamuji, i vysvobozuji, jakž předpovídám, a ne někdo mezi vámi z cizích bohů, a vy mi toho svědkové jste, praví Hospodin, že já Bůh silný jsem.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 13, 'Ještě prvé nežli den byl, já jsem, a není žádného, kdož by vytrhl z ruky mé. Když co dělám, kdo ji odvrátí?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 14, 'Takto praví Hospodin vykupitel váš, Svatý Izraelský: Pro vás pošli do Babylona, a sházím závory všecky, i Kaldejské s lodimi veselými jejich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 15, 'Já jsem Hospodin svatý váš, stvořitel Izraele, král váš.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 16, 'Takto praví Hospodin, kterýž způsobuje na moři cestu, a na prudkých vodách stezku,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 17, 'Kterýž vyvodí vozy a koně, vojsko i sílu, činí, že v náhle padají, až i povstati nemohou, hasnou, jako knot hasne:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 18, 'Nezpomínejte na první věci, a na starodávní se neohlédejte.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 19, 'Aj, já učiním věc novou, a tudíž se zjeví. Zdaliž o tom nezvíte? Nadto způsobím na poušti cestu, a na pustinách řeky.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 20, 'I slaviti mne bude zvěř polní, drakové i sovy, že jsem vyvedl na poušti vody a řeky na pustinách, abych dal nápoj lidu svému, vyvolenému svému.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 21, 'Lid, kterýž nastrojím sobě, chválu mou vypravovati bude,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 22, 'Poněvadž jsi mne nevzýval, ó Jákobe, nýbrž steskloť se se mnou, ó Izraeli.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 23, 'Nepřivedl jsi mi hovádka k zápalům svým, a obětmi svými neuctils mne; nenutil jsem tě, abys mi sloužil obětmi suchými, aniž jsem tě tím obtěžoval, abys mi kadil.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 24, 'Nekoupil jsi mi za peníze vonných věcí, ani tukem obětí svých zavlažil jsi mne, ale zaměstknal jsi mne hříchy svými, a obtížils mne nepravostmi svými.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 25, 'Já, já sám shlazuji přestoupení tvá pro sebe, a na hříchy tvé nezpomínám.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 26, 'Přiveď mi ku paměti, suďme se spolu; oznam ty, podlé čeho bys mohl spravedliv býti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 27, 'Otec tvůj první zhřešil, a učitelé tvoji přestoupili proti mně.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 28, 'A protož smeci knížata z míst svatých, a vydám v prokletí Jákoba, a Izraele v pohanění.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 1, 'A však nyní slyš, Jákobe, služebníče můj, a Izraeli, kteréhož jsem vyvolil.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 2, 'Toto dí Hospodin, kterýž tě učinil, a sformoval hned od života matky, a spomáhá tobě: Neboj se, služebníče můj, Jákobe, a upřímý, kteréhož jsem vyvolil.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 3, 'Nebo vyleji vody na žíznivého, a potoky na vyprahlost; vyleji Ducha svého na símě tvé, a požehnání své na potomky tvé.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 4, 'I porostou jako mezi bylinami, jako vrbí vedlé tekutých vod.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 5, 'Tento dí: Hospodinův já jsem, a onen nazůve se jménem Jákobovým, a jiný zapíše se rukou svou Hospodinu, a jménem Izraelským jmenovati se bude.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 6, 'Takto praví Hospodin, král Izraelův a vykupitel jeho, Hospodin zástupů: Já jsem první, a já poslední, a kromě mne není žádného Boha.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 7, 'Nebo kdo tak jako já ohlašuje a oznamuje to, aneb spořádá mi to hned od toho času, jakž jsem rozsadil lidi na světě? A kdo to, což přijíti má, oznámiti jim mohou?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 8, 'Nebojtež se, ani lekejte. Zdali hned zdávna nepověděl jsem tobě a neoznámil, čehož vy sami mně svědkové jste? Zdaliž jest Bůh kromě mne? Neníť jistě žádné skály, jáť o žádné nevím.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 9, 'Ti, kteříž formují rytiny, všickni nic nejsou; tolikéž ty milostné jejich nic neprospívají. Čehož ony sobě samy svědectvím jsou; nic nevidí, aniž čeho znají, aby se styděti mohly.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 10, 'Kdo formuje Boha silného a rytinu slévá, k ničemu se to nehodí.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 11, 'Aj, všickni, i ti, kteříž se k němu přiúčastňují, zahanbeni budou, ovšem řemeslníci ti nad jiné lidi; byť se pak všickni shromáždili a postavili, strašiti se musejí, a spolu zahanbeni budou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 12, 'Kovář pochytě železo, dělá při uhlí, a kladivy formuje modlu. Když ji dělá vší silou svou, ještě k tomu lační až do zemdlení, aniž se vody napije, až i ustává.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 13, 'Tesař roztáhna šňůru, znamenává ji hrudkou, spravuje ji úhelnicemi, a kružidlem rozměřuje ji, až ji udělá tvárnost muže mající a podobnost krásy člověka, aby seděla doma.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 14, 'Nasekaje sobě cedrů, vezme také cypřiš a dub aneb to, kteréž jest nejcelistvější mezi dřívím lesním; i javor štěpuje, a déšť jej k zrostu přivozuje.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 15, 'I bývá člověku k topení; nebo vezma z něho, zhřívá se. Rozněcuje také oheň, aby napekl chleba. Mimo to udělá sobě boha, a klaní se jemu; udělá z něho rytinu, a kleká před ní.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 16, 'Částku jeho pálí ohněm, při druhé částce jeho maso jí, peče pečeni, a nasycen bývá. Zhřívá se také, a říká: Aha, zhřel jsem se, viděl jsem oheň.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 17, 'Z ostatku pak jeho udělá boha, rytinu svou, před níž kleká, a klaní se, a modlí se jí, řka: Vysvoboď mne, nebo Bůh silný můj jsi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 18, 'Neznají ani soudí, proto že zaslepil oči jejich, aby neviděli, a srdce jejich, aby nerozuměli.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 19, 'Aniž považují toho v srdci svém. Není umění, není rozumu, aby kdo řekl: Díl z něho spálil jsem ohněm, a při uhlí jeho napekl jsem chleba, pekl jsem maso, a jedl jsem, a mám z ostatku jeho ohavnost udělati, a před špalkem dřevěným klekati?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 20, 'Popelem se pase takový, srdce svedené skloňuje jej, aby nemohl osvoboditi duše své, ani říci: Není-liž omylu v předsevzetí mém?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 21, 'Pamatujž na to, Jákobe a Izraeli, proto že jsi ty služebník můj. Já jsem tě sformoval, služebník můj jsi, Izraeli, nebudeš u mne v zapomenutí.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 22, 'Zahladím jako hustý oblak přestoupení tvá, a jako mrákotu hříchy tvé; navratiž se ke mně, nebo jsem tě vykoupil.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 23, 'Prozpěvujte nebesa, nebo Hospodin to učinil; zvučte nižiny země, zvučně prozpěvujte hory, les i všeliké dříví v něm, nebo vykoupil Hospodin Jákoba, a v Izraeli sebe oslavil.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 24, 'Takto praví Hospodin vykupitel tvůj, a ten, kterýž tě sformoval hned od života matky: Já Hospodin činím všecko, roztahuji nebesa sám, rozprostírám zemi mocí svou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 25, 'Rozptyluji znamení lhářů, a z hadačů blázny dělám; obracím moudré nazpět, a umění jejich v bláznovství.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 26, 'Potvrzuji slova služebníka svého, a radu poslů svých vykonávám. Kterýž dím o Jeruzalému: Bydleno bude v něm, a o městech Judských: Vystavena budou, nebo pustiny jejich vzdělám.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 27, 'Kterýž dím hlubině: Vyschni, nebo potoky tvé vysuším.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 28, 'Kterýž dím o Cýrovi: Pastýř můj, nebo všelikou vůli mou vykoná, a řekne Jeruzalému: Zase vystaven buď, a chrámu: Založen buď.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 1, 'Takto praví Hospodin pomazanému svému Cýrovi, jehož pravici zmocním, a národy před ním porazím, a bedra králů rozpáši, a zotvírám před ním vrata, a brány nebudou zavírány:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 2, 'Já před tebou půjdu, a cesty křivé zpřímím, vrata měděná potru, a závory železné posekám.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 3, 'A dám tobě poklady skryté, a klénoty schované, abys poznal, že já jsem Hospodin Bůh Izraelský, kterýž tě ze jména volám.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 4, 'Pro služebníka svého Jákoba a Izraele vyvoleného svého jmenoval jsem tě jménem tvým, i příjmím tvým, ačkoli mne neznáš.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 5, 'Já jsem Hospodin, a není žádného více, kromě mne není žádného Boha. Přepásal jsem tě, ačkoli mne neznáš,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 6, 'Aby poznali od východu slunce i od západu, že není žádného kromě mne. Jáť jsem Hospodin, a není, žádného více.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 7, 'Kterýž formuji světlo, a tvořím tmu, působím pokoj, a tvořím zlé, já Hospodin činím to všecko.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 8, 'Rosu dejte nebesa s hůry, a nejvyšší oblakové dštěte spravedlnost; otevři se země, a ať vzejde spasení, a spravedlnost ať spolu vykvete. Já Hospodin způsobím to.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 9, 'Běda tomu, kdož se v odpory dává s tím, jenž jej sformoval, jsa střep jako jiné střepiny hliněné. Zdaliž dí hlina hrnčíři svému: Což děláš? Dílo tvé zajisté ničemné jest.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 10, 'Běda tomu, kterýž říká otci: Co zplodíš? A ženě: Co porodíš?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 11, 'Takto praví Hospodin, Svatý Izraelský, a kterýž jej sformoval: Budoucí-liž věci na mně vyzvídati chcete, o synech mých a díle rukou mých mně vyměřovati?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 12, 'Já jsem učinil zemi, a člověka na ní stvořil; já jsem, jehož ruce roztáhly nebesa, a všemu vojsku jejich rozkazuji.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 13, 'Já vzbudím jej v spravedlnosti, a všecky cesty jeho zpřímím. Onť vzdělá město mé, a zajaté mé propustí, ne ze mzdy, ani pro dar, praví Hospodin zástupů.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 14, 'Takto praví Hospodin: Práce Egyptská, a kupectví Mouřenínská, a Sabejští, muži veliké postavy, k tobě přijdou, a tvoji budou. Za tebou se poberou, v poutech půjdou, tobě se klaněti, a tobě se kořiti budou, říkajíce: Toliko u tebe jest Bůh silný, a neníť žádného více kromě toho Boha.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 15, '(Jistě ty jsi Bůh silný, skrývající se, Bůh Izraelský, spasitel.)');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 16, 'Všickni onino se zastydí, a zahanbeni budou, spolu odejdou s hanbou činitelé obrazů;');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 17, 'Ale Izrael spasen bude skrze Hospodina spasením věčným. Nebudete zahanbeni, ani v lehkost uvedeni na věky věků.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 18, 'Nebo tak praví Hospodin stvořitel nebes, (ten Bůh, kterýž sformoval zemi a učinil ji, kterýž utvrdil ji, ne na prázdno stvořil ji, k bydlení sformoval ji): Já jsem Hospodin, a není žádného více.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 19, 'Nemluvím tajně v místě zemském tmavém, neříkám semeni Jákobovu nadarmo: Hledejte mne. Já Hospodin mluvím spravedlnost, a zvěstuji věci pravé.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 20, 'Shromažďte se a přiďte, přibližte se spolu vy, kteříž jste pozůstali mezi pohany. Nic neznají ti, kteříž se s dřevem rytiny své nosí; nebo se modlí bohu, kterýž nemůže vysvoboditi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 21, 'Oznamte a přiveďte i jiné, a nechať spolu v radu vejdou, a ukáží, kdo to od starodávna předpověděl, a hned zdávna oznámil? Zdali ne já Hospodin? Neboť není žádného jiného Boha kromě mne, není Boha silného, spravedlivého, a spasitele žádného kromě mne.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 22, 'Obraťtež zřetel ke mně, abyste spaseny byly všecky končiny země; nebo já jsem Bůh silný, a není žádného více.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 23, 'Skrze sebe přisáhl jsem, vyšlo z úst mých slovo spravedlnosti, kteréž nepůjde na zpět: Že se mně skláněti bude všeliké koleno, a přisahati každý jazyk,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 24, 'Říkaje: Toliko v Hospodinu mám všelijakou spravedlnost a sílu, a až k samému přijde; ale zahanbeni budou všickni, kteříž se koli zlobí proti němu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 25, 'V Hospodinu ospravedlněni budou, a chlubiti se všecko símě Izraelovo.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 46, 1, 'Klesl Bél, padl Nébo, modly jejich octnou se na hovadech a na dobytku. Tím zajisté, což vy nosíváte, budou náramně obtížena až do ustání.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 46, 2, 'Klesly, padly spolu, aniž budou moci retovati břemene, nýbrž i oni sami v zajetí odejdou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 46, 3, 'Slyšte mne, dome Jákobův, a všickni ostatkové domu Izraelova, kteréž pěstuji hned od života, kteréž nosím hned od narození:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 46, 4, 'Až i do starosti já sám, nýbrž až do šedin já ponesu; já jsem vás učinil, a já nositi budu, já, pravím, ponesu a vysvobodím.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 46, 5, 'K komu mne připodobníte a přirovnáte, aneb podobna učiníte, abychom sobě podobní byli?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 46, 6, 'Ti, kteříž marně vynakládají zlato z měšce, a stříbro na vážkách váží, najímají ze mzdy zlatníka, aby udělal z něho boha, před nímž padají a sklánějí se.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 46, 7, 'Nosí jej na rameni, pěstují se s ním, a stavějí ho na místě jeho, i stojí, z místa svého se nehýbaje. Volá-li kdo k němu, neozývá se, aniž jej z úzkosti jeho vysvobozuje.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 46, 8, 'Pamatujtež na to, a zastyďte se; připusťte to, ó zpronevěřilí, k srdci.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 46, 9, 'Rozpomeňte se na první věci od věků stalé, nebo já jsem Bůh silný, a není žádného více Boha, aniž jest mně podobného.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 46, 10, 'Kterýž oznamuji při počátku dokonání, a hned zdaleka to, což se ještě nestalo; řeknu-li co, rada má se koná, a vše, což mi se líbí, činím.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 46, 11, 'Kterýž zavolám od východu ptáka, z země daleké toho, kterýž by vykonal uložení mé. Řekl jsem, a dovedu toho, umínil jsem, a vykonám to.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 46, 12, 'Slyšte mne, vy urputného srdce, kteříž jste dalecí od spravedlnosti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 46, 13, 'Jáť způsobím, aby se přiblížila spravedlnost má. Nebudeť prodlévati, aniž spasení mé bude meškati; nebo složím v Sionu spasení, a v Izraeli slávu svou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 47, 1, 'Sstup a seď v prachu, panno dcero Babylonská, seď na zemi, a ne na trůnu, dcero Kaldejská; nebo nebudou tě více nazývati milostnou a rozkošnou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 47, 2, 'Chyť se žernovu, a mel mouku; odkrej kadeře své, obnaž nohy, odkrej hnáty, břeď přes řeky.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 47, 3, 'Odkryta bude hanba tvá, a ukáže se mrzkost tvá. Mstíti budu, a nedám sobě žádnému překaziti,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 47, 4, 'Praví vykupitel náš, jehož jméno jest Hospodin zástupů, Svatý Izraelský.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 47, 5, 'Sediž mlče, a vejdi do tmy, dcero Kaldejská; nebo nebudou tě více nazývati paní království.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 47, 6, 'Rozhněval jsem se na lid svůj, v lehkost jsem uvedl dědictví své, a vydal jsem je v ruku tvou, a neprokázalas k nim milosrdenství. Starce jsi obtížila velmi jhem svým,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 47, 7, 'A říkalas: Na věky budu paní, a nikdy jsi nesložila těch věcí v srdci svém, aniž jsi pamatovala na cíl jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 47, 8, 'Protož nyní slyšiž toto, ó rozkošná, (kteráž sedíš bezpečně, a říkáš v srdci svém: Já jsem, a není kromě mne žádné; nebuduť vdovou, aniž zvím o sirobě),');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 47, 9, 'Že obé to přijde na tě pojednou dne jednoho, i siroba i vdovství. Všecko zúplna přijde na tě, i na množství kouzlů tvých, a na velikou moc čárů tvých.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 47, 10, 'Nebo doufáš v zlost svou, a říkáš: Žádný mne nevidí. Moudrost tvá a umění tvé, to tě převrátilo, abys říkala v srdci svém: Já jsem, a není kromě mne žádné.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 47, 11, 'A protož přijde na tě zlé, jehož východu neznáš, a připadne na tě bída, kteréž nebudeš moci se odžehnati, a přijde na tě pojednou hrozné zpuštění, než zvíš.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 47, 12, 'Postav se nyní s čáry svými, a s množstvím kouzlů svých, jimiž jsi se zaměstknávala od mladosti své, budeš-li moci co prospěti, aneb snad zmocniti se.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 47, 13, 'Ustáváš s množstvím rad svých. Nechať se nyní postaví hvězdáři, kteříž spatřují hvězdy, a oznamují na každý měsíc, a vysvobodí tě z toho, což přijíti má na tě.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 47, 14, 'Aj, jako pleva jsou, oheň popálí je, nevychvátí ani sami sebe z prudkosti plamene; žádného uhlí nezůstane k zhřívání se, ani ohně, aby se mohlo poseděti u něho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 47, 15, 'Takť se stane i kupcům tvým, jimiž jsi se zaměstknávala od mladosti své. Jeden každý svou stranou půjde, aniž bude, kdo by tě vysvobodil.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 1, 'Slyštež to, dome Jákobův, kteříž se nazýváte jménem Izraelovým, a z vod Judových jste pošli, kteříž přisaháte ve jménu Hospodinovu, a Boha Izraelského připomínáte, však ne v pravdě, ani v spravedlnosti,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 2, 'Ačkoli od města svatého se jmenujete, a na Boha Izraelského, jehož jméno jest Hospodin zástupů, zpoléháte.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 3, 'Předešlé věci zdávna jsem oznamoval, a což vyšlo z úst mých, i což jsem ohlašoval, brzce jsem činíval, a stávalo se.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 4, 'Věděl jsem, že jsi zatvrdilý, a houžev železná šíje tvá, a čelo tvé ocelivé.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 5, 'A protožť jsem oznamoval z dávna, prvé než přicházelo, ohlašovalť jsem, abys neříkal: Modla má učinila ty věci, a rytina má neb slitina má přikázala to.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 6, 'Slýchals o tom, pohlediž na to na všecko, vy pak, nebudete-liž toho oznamovati? Již nyní ohlašujiť nové a tajné věci, o nichž jsi ty nic nevěděl.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 7, 'Nyní stvořeny jsou, a ne předešlého času, o nichž jsi před tímto dnem nic neslyšel, abys neřekl: Aj, věděl jsem o tom.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 8, 'Anobrž aniž jsi slyšel, ani věděl, aniž se to tehdáž doneslo ucha tvého; nebo jsem věděl, že sobě velmi nevážně počínati budeš, a že jsi převrácenec hned od života matky.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 9, 'Pro jméno své poshovím s prchlivostí svou, a pro chválu svou poukrotím hněvu proti tobě, abych tě nevyplénil.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 10, 'Aj, přepálím tě, ačkoli ne jako stříbro, přeberu tě v peci ssoužení.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 11, 'Pro sebe, pro sebe učiním to. Nebo jakž by mohlo v lehkost vydáno býti? Slávy své zajisté jinému nedám.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 12, 'Slyš mne, Jákobe a Izraeli, povolaný můj: Já jsem, já první, já jsem i poslední.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 13, 'Má zajisté ruka založila zemi, a pravice má dlaní rozměřila nebesa; povolal jsem jich, a hned se postavily.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 14, 'Shromažďte se vy všickni, a slyšte. Kdo z nich oznámil tyto věci: Hospodin miluje jej, onť vykoná vůli jeho proti Babylonu, a rámě jeho proti Kaldejským?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 15, 'Já, já mluvil jsem, protož povolám ho; přivedu jej, a šťastnou bude míti cestu svou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 16, 'Přistupte ke mně, slyšte to: Nemluvíval jsem z počátku v skrytě; od toho času, v kterémž se to dálo, přítomen jsem byl. A nyní Panovník Hospodin poslal mne a duch jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 17, 'Toto praví Hospodin vykupitel tvůj, Svatý Izraelský: Já Hospodin Bůh tvůj učím tě, abys prospěch bral, a vodím tě po cestě, po kteréž bys chodil.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 18, 'Ó kdybys byl šetřil přikázaní mých, bylť by jako potok pokoj tvůj, a spravedlnost tvá jako vlny mořské.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 19, 'A bylo by jako písku semene tvého, a plodu života tvého jako štěrku jeho, aniž by vyťato, ani vyhlazeno bylo jméno jeho před oblíčejem mým.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 20, 'Vyjděte z Babylona, utecte od Kaldejských, hlasem zvučným zvěstujte, ohlašujte to, rozneste to až do končin země. Rcete: Vykoupil Hospodin služebníka svého Jákoba.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 21, 'Nebudouť žízniti, když je po pustinách povede, vody z skály vyvede jim; nebo rozetne skálu, aby tekly vody.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 22, 'Nemajíť žádného pokoje, praví Hospodin, bezbožní.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 1, 'Poslouchejte mne ostrovové, a pozorujte národové dalecí: Hospodin hned z života povolal mne, od života matky mé v pamět uvedl jméno mé,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 2, 'A učinil ústa má podobná meči ostrému. V stínu ruky své skryl mne, a učiniv ze mne střelu vypulerovanou, v toule svém schoval mne.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 3, 'A řekl mi: Služebník můj jsi, v Izraeli skrze tebe oslaven budu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 4, 'Já pak řekl jsem: Nadarmo jsem pracoval, daremně a marně sílu svou jsem strávil. Ale však soud můj jestiť u Hospodina, a práce má u Boha mého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 5, 'A nyní dí Hospodin, kterýž mne sformoval hned od života za služebníka svého, abych zase přivedl k němu Jákoba; (byť pak i nebyl sebrán Izrael, slávu však mám před očima Hospodinovýma; nebo Bůh můj jest síla má);');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 6, 'I to řekl Hospodin: Máloť by to bylo, abys mi byl služebníkem ku pozdvižení pokolení Jákobových, a k navrácení ostatků Izraelských; protož dal jsem tě za světlo pohanům, abys byl spasení mé až do končin země.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 7, 'Toto praví Hospodin vykupitel Izraelův, Svatý jeho, tomu, jímž pohrdá každý, a jehož sobě oškliví národové, služebníku panujících: Králové, vidouce tě, povstanou, a knížata klaněti se budou pro Hospodina, kterýž věrný jest, Svatého Izraelského, jenž tě vyvolil.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 8, 'Toto praví Hospodin: V čas milosti vyslyším tě, a ve dni spasení spomohu tobě. Nadto ostříhati tě budu, a dám tě v smlouvu lidu, abys utvrdil zemi, a v dědictví uvedl dědictví zpuštěná;');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 9, 'Abys řekl vězňům: Vyjděte, těm, kteříž jsou ve tmách: Zjevte se. I budou se pásti podlé cest, a na všech místech vysokých bude pastva jejich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 10, 'Nebudou lačněti ani žízniti, nebude na ně bíti horko ani slunce; nebo slitovník jejich zprovodí je, a podlé pramenů vod povede je.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 11, 'Přes to způsobím na všech horách svých cesty, a silnice mé vyvýšeny budou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 12, 'Aj, tito zdaleka přijdou, aj, onino od půlnoci a od moře, a jiní z země Sinim.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 13, 'Prozpěvujte nebesa, a plésej země, a zvučně prokřikujte hory; neboť jest potěšil Hospodin lidu svého, a nad chudými svými slitoval se.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 14, 'Ale řekl Sion: Opustiltě mne Hospodin, a Pán zapomenul se na mne.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 15, 'I zdaliž se může zapomenouti žena nad nemluvňátkem svým, aby se neslitovala nad plodem života svého? A byť se pak ony zapomněly, já však nezapomenu se na tě.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 16, 'Aj, na dlaních vyryl jsem tě, zdi tvé jsou vždycky přede mnou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 17, 'Pospíšíť k tobě synové tvoji, ti pak, kteříž tě bořili a kazili, odejdou od tebe.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 18, 'Pozdvihni vůkol očí svých, a pohleď, všickni ti shromáždíce se, přijdou k tobě. Živť jsem já, praví Hospodin, že se jimi všemi jako okrasou přioděješ, a otočíš se jimi jako halží nevěsta,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 19, 'Proto že pustiny tvé, a pouště tvé, a zbořeniny země tvé že tehdáž těsné budou, příčinou obyvatelů, když vzdáleni budou ti, kteříž tě zžírali;');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 20, 'Tak že řeknou před tebou synové siroby tvé: Těsné mi jest toto místo, ustup mi, abych bydliti mohl.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 21, 'I díš v srdci svém: Kdo mi naplodil těchto? Nebo jsem já byla osiřelá a osamělá, sem i tam přecházející a odcházející. Tyto, pravím, kdo vychoval? Aj, pozůstala jsem byla sama jediná. Kdež tito byli?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 22, 'Toto praví Panovník Hospodin: Aj, já pozdvihnu k národům ruky své, a k lidem vyzdvihnu korouhev svou, aby přinesli syny tvé na rukou, a dcery tvé aby na plecech neseny byly.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 23, 'I budou králové pěstounové tvoji, a královny jejich chovačky tvé. Tváří k zemi skláněti se budou před tebou, a prach noh tvých lízati budou, a poznáš, že jsem já Hospodin, a že nebývají zahanbeni, kteříž na mne očekávají.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 24, 'Ale díš: Zdaliž odjato bude reku udatnému to, což uchvátil? A zdaž zajatý lid spravedlivého vyproštěn bude?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 25, 'Anobrž tak praví Hospodin: I zajatý lid reku udatnému odjat bude, a to, což uchvátil násilník, vyproštěno bude; nebo s tím, kterýž se s tebou nesnadní, já se nesnadniti budu, a syny tvé já vysvobodím.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 26, 'A nakrmím ty, kteříž tě utiskují, vlastním masem jejich, a jako mstem krví svou se zpijí. I poznáť všeliké tělo, že já Hospodin jsem spasitel tvůj, a vykupitel tvůj Bůh silný Jákobův.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 50, 1, 'Takto praví Hospodin: Kdež jest lístek zapuzení matky vaší, kterýmž jsem ji propustil? Aneb kdo jest z věřitelů mých, jemuž jsem vás prodal? Aj, nepravostmi svými prodali jste sebe, a pro převrácenosti vaše propuštěna jest matka vaše.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 50, 2, 'Proč, když přicházím, není žádného, když volám, žádný se neozývá? Zdaliž jest naprosto ukrácena ruka má, aby nemohla vykoupiti? A žádné-liž není ve mně moci k vysvobození? Aj, žehráním svým vysušuji moře, obracím řeky v poušť, až se smrazují ryby jejich, proto že nebývá vody, a mrou žízní.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 50, 3, 'Obláčím nebesa v smutek, a žíni dávám jim za oděv.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 50, 4, 'Panovník Hospodin dal mi jazyk umělý, abych uměl příhodně ustalému mluviti slova. Probuzuje každého jitra, probuzuje mi uši, abych slyšel, tak jako pilně se učící.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 50, 5, 'Panovník Hospodin otvírá mi uši, a já se nepostavuji zpurně, aniž se nazpět odvracím.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 50, 6, 'Těla svého nastavuji bijícím, a líce svého rvoucím mne, tváři své neskrývám od pohanění a plvání.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 50, 7, 'Nebo Panovník Hospodin spomáhá mi, pročež nebývám zahanben. Pro touž příčinu nastavuji tváři své jako škřemene; nebo vím, že nebudu zahanben.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 50, 8, 'Blízkoť jest ten, kterýž mne ospravedlňuje. Kdož se nesnadniti bude se mnou? Postavme se spolu; kdo jest odpůrce můj, nechť přistoupí ke mně.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 50, 9, 'Aj, Panovník Hospodin spomáhati mi bude. Kdož jest, ješto by mne potupil? Aj, všickni takoví jako roucho zvetšejí, mol sžíře je.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 50, 10, 'Kdo jest mezi vámi, ješto se bojí Hospodina, poslouchej hlasu služebníka jeho. Kdo jest, ješto chodí v temnostech, a nemá žádného světla, doufej ve jméno Hospodinovo, a zpolehni na Boha svého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 50, 11, 'Aj, vy všickni, kteříž zaněcujete oheň, a jiskrami se přepasujete, choďtež v blesku ohně svého, a v jiskrách, kteréž jste roznítili. Od ruky mé toto se vám stane, že v bolesti ležeti budete.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 1, 'Poslouchejte mne, následovníci spravedlnosti, kteříž hledáte Hospodina, pohleďte na skálu, odkudž vyťati jste, a na hlubokost jámy, z níž vykopáni jste.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 2, 'Pohleďte na Abrahama otce vašeho, a na Sáru, kteráž vás porodila, že jsem jej jediného povolal, a požehnal jsem jemu, i rozmnožil jej.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 3, 'Nebo potěší Hospodin Siona, potěší všech pustin jeho, a učiní poušť jeho přerozkošnou, a pustinu jeho podobnou zahradě Hospodinově. Radost a veselí bude nalezeno v něm, díkčinění, a hlas žalmů zpívání.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 4, 'Pozorujte mne, lide můj, a rodino má, nastavte mi uší; nebo zákon ode mne vyjde, a soud svůj za světlo národům vystavím.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 5, 'Blízko jest spravedlnost má, vyjdeť spasení mé, a ramena má národy souditi budou. Na mneť ostrovové čekají, a po mém rameni touží.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 6, 'Pozdvihněte k nebi očí svých, a popatřte na zem dolů. Nebesa zajisté jako dým zmizejí, a země jako roucho zvetší, a obyvatelé její též podobně zemrou: ale spasení mé na věky zůstane, a spravedlnost má nezahyne.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 7, 'Poslouchejte mne, kteříž znáte spravedlnost, lide, v jehož srdci jest zákon můj; nebojte se útržky lidí bídných, a hanění jejich neděste se.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 8, 'Nebo jako roucho zžíře je mol, a jako vlnu zžíře je červ, ale spravedlnost má na věky zůstane, a spasení mé od národu do pronárodu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 9, 'Probuď se, probuď se, oblec se v sílu, ó rámě Hospodinovo, probuď se, jako za dnů starodávních a národů předešlých. Zdaliž ty nejsi to, kteréžs poplénilo Egypt, a ranilo draka?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 10, 'Zdaliž ty nejsi to, kteréžs vysušilo moře, vody propasti veliké, kteréžs obrátilo hlubiny mořské v cestu, aby přešli ti, jenž byli vysvobozeni?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 11, 'A tak ti, kteréž vykoupil Hospodin, ať se navrátí, a přijdou na Sion s prozpěvováním, a veselé věčné ať jest na hlavě jejich; radosti a veselé ať dojdou, zámutek pak a úpění ať utekou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 12, 'Já, já jsem utěšitel váš. Jakáž jsi ty, že se bojíš člověka smrtelného, a syna člověka trávě podobného?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 13, 'Že se zapomínáš na Hospodina učinitele svého, kterýž roztáhl nebesa, a založil zemi, a že se děsíš ustavičně každého dne prchlivosti ssužujícího, jakž se jen postrojí, aby hubil? Ale kdež jest pak ta prchlivost toho, kterýž ssužuje?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 14, 'Pospíšíť, aby zajatý propuštěn byl; neboť neumře v jámě, aniž bude míti jaký nedostatek chleba svého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 15, 'Jáť jsem zajisté Hospodin Bůh tvůj, kterýž rozděluje moře, jehož vlny zvuk vydávají. Hospodin zástupů jest jméno mé,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 16, 'Kterýž jsem vložil slova svá v ústa tvá, a stínem ruky své přikryl jsem tě, abys štípil nebesa, a založil zemi, a řekl Sionu: Lid můj jsi ty.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 17, 'Probuď se, probuď, povstaň, Jeruzaléme, kterýž jsi pil z ruky Hospodinovy kalich prchlivosti jeho, kvasnice z kalicha hrůzy vypil jsi, i vyvážil.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 18, 'Žádný jí nevedl ze všech synů, kterýchž naplodila, a žádný jí neujal za ruku její ze všech synů, kteréž vychovala.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 19, 'Toto dvé tě potkalo, (kdo tě politoval?) zpuštění a setření, hlad a meč. Kdo tě potěšoval?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 20, 'Synové tvoji omráčeni jsouc, leží na rozcestí všech ulic, jako bůvol v leči, plni jsouce prchlivosti Hospodinovy, žehrání Boha tvého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 21, 'A protož slyš nyní toto, ztrápená a opilá, ale ne vínem:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 22, 'Takto praví Pán tvůj, Hospodin a Bůh tvůj, vedoucí při lidu svého: Aj, beru z ruky tvé kalich hrůzy, i kvasnice kalicha prchlivosti mé, nebudeš ho píti více.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 23, 'Ale dám jej do ruky těch, jenž tě ssužují, kteříž říkali duši tvé: Sehni se, ať přes tě přejdeme, jimž jsi podkládala jako zemi hřbet svůj, a jako ulici přecházejícím.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 52, 1, 'Probuď se, probuď se, oblec se v sílu svou, Sione, oblec se v roucho okrasy své, ó Jeruzaléme, město svaté; neboť nebude již více na tě dotírati neobřezaný a nečistý.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 52, 2, 'Otřes se z prachu, povstaň, posaď se, Jeruzaléme; dobuď se z okovů hrdla svého, ó jatá dcerko Sionská.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 52, 3, 'Takto zajisté dí Hospodin: Darmo jste sebe prodali, protož bez peněz budete vykoupeni.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 52, 4, 'Nebo takto praví Panovník Hospodin: Do Egypta sstoupil lid můj předešle, aby tam byl pohostinu, ale Assur bez příčiny jej ssužuje.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 52, 5, 'Nyní tedy což mám činiti? praví Hospodin. Poněvadž jest lid můj zajat darmo, a panovníci jeho k úpění jej přivodí, praví Hospodin. Nad to ustavičně každého dne jménu mému útržka se činí.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 52, 6, 'Protož poznáť lid můj jméno mé, protož poznáť, pravím, v ten den, že já tentýž, kterýž mluvím, aj, přítomen budu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 52, 7, 'Ó jak krásné na horách nohy toho, ješto potěšené věci zvěstuje, a ohlašuje pokoj, toho, ješto zvěstuje dobré, ješto káže spasení, a mluví k Sionu: Kralujeť Bůh tvůj.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 52, 8, 'Strážní tvoji hlasu, hlasu pozdvihnou, a spolu prokřikovati budou; neboť okem v oko uzří, že Hospodin zase přivede Sion.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 52, 9, 'Zvučte, prozpěvujte spolu pustiny Jeruzalémské; neboť jest potěšil Hospodin lidu svého, vykoupil Jeruzalém.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 52, 10, 'Ohrnul Hospodin rámě svatosti své před očima všech národů, aby viděly všecky končiny země spasení Boha našeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 52, 11, 'Odejděte, odejděte, vyjděte z Babylona, nečistého se nedotýkejte; vyjděte z prostředku jeho, očisťte se vy, kteříž nosíte nádobí Hospodinovo.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 52, 12, 'Nebo ne s chvátáním vyjdete, aniž s utíkáním půjdete; předcházeti zajisté bude vás Hospodin, a zbéře vás Bůh Izraelský.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 52, 13, 'Aj, služebníku mému šťastně se povede, vyvýšen, vznešen a zveleben bude velmi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 52, 14, 'A jakož mnozí se nad ním užasnou, že tak zohavena jest nad jiné lidi osoba jeho, způsob jeho nad syny lidské:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 52, 15, 'Tak zase skropí národy mnohé, i králové před ním zacpají ústa svá, proto že což jim nebylo vypravováno, to uzří, a tomu, o čemž neslýchali, porozumějí.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 53, 1, 'Kdo uvěřil kázaní našemu? A rámě Hospodinovo komu jest zjeveno?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 53, 2, 'Nebo před ním vyrostl jako proutek, a jako kořen z země vyprahlé, nemaje podoby ani krásy. Viděliť jsme jej, ale nic nebylo viděti toho, proč bychom ho žádostivi byli.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 53, 3, 'Nejpohrdanější zajisté a nejopovrženější byl z lidí, muž bolestí, a kterýž zkusil nemocí, a jako ukrývající tvář svou; nejpohrdanější, pročež jsme ho za nic nevážili.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 53, 4, 'Ještotě on nemoci naše vzal, a bolesti naše vlastní on nesl, my však domnívali jsme se, že jest raněn, a ubit od Boha, i strápen.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 53, 5, 'On pak raněn jest pro přestoupení naše, potřín pro nepravosti naše; kázeň pokoje našeho na něj vzložena, a zsinalostí jeho lékařství nám způsobeno.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 53, 6, 'Všickni my jako ovce zbloudili jsme, jeden každý na cestu svou obrátili jsme se, a Hospodin uvalil na něj nepravosti všech nás.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 53, 7, 'Pokutován jest i strápen, však neotevřel úst svých. Jako beránek k zabití veden byl, a jako ovce před těmi, kdož ji střihou, oněměl, aniž otevřel úst svých.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 53, 8, 'Z úzkosti a z soudu vyňat jest, a protož rod jeho kdo vypraví, ačkoli vyťat jest z země živých, a zraněn pro přestoupení lidu mého?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 53, 9, 'Kterýžto vydal bezbožným hrob jeho, a bohatému, aby byl usmrcen, ješto však nepravosti neučinil, aniž jest nalezena lest v ústech jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 53, 10, 'Taktě se líbilo Hospodinu jej stírati, a nemocí trápiti, aby polože duši svou v oběť za hřích, viděl símě své, byl dlouhověký, a to, což se líbí Hospodinu, skrze něho šťastně konáno bylo.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 53, 11, 'Z práce duše své uzří užitek, jímž nasycen bude. Známostí svou ospravedlní spravedlivý služebník můj mnohé; nebo nepravosti jejich on sám ponese.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 53, 12, 'A protož dám jemu díl pro mnohé, aby s nesčíslnými dělil se o kořist, proto že vylil na smrt duši svou, a s přestupníky počten jest. Onť sám nesl hřích mnohých, a přestupníků zástupcím byl.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 54, 1, 'Prozpěvuj, neplodná, kteráž nerodíš, zvučně prozpěvuj a prokřikni, kteráž ku porodu nepracuješ, nebo více bude synů opuštěné, nežli synů té, kteráž má muže, praví Hospodin.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 54, 2, 'Rozšiř místo stanu svého, a čalounů příbytků svých roztáhnouti nezbraňuj; natáhni i provazů svých, a kolíky své utvrď.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 54, 3, 'Nebo na pravo i na levo se rozmůžeš, a símě tvé národy dědičně vládnouti bude, a města pustá osadí.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 54, 4, 'Nebojž se, nebo nebudeš zahanbena, aniž se zapyřuj, nebo nebudeš v potupu uvedena; nýbrž na potupu mladosti své zapomeneš, a na pohanění vdovství svého nezpomeneš více.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 54, 5, 'Nebo manželem tvým jest Učinitel tvůj, jehož jméno Hospodin zástupů, a vykupitel tvůj Svatý Izraelský Bohem vší země slouti bude.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 54, 6, 'Nebo jako ženy propuštěné a v duchu sevřené povolá tě Hospodin, a jako ženy mladice, když v pohrdnutí budeš, praví Bůh tvůj.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 54, 7, 'Na maličkou chvilku poopustil jsem tě, ale v slitování převelikém shromáždím tě.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 54, 8, 'V maličkém hněvě skryl jsem tvář svou na maličko před tebou, ale v milosrdenství věčném slituji se nad tebou, praví vykupitel tvůj Hospodin.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 54, 9, 'Neboť jest to u mne, co při potopě Noé. Jakož jsem přisáhl, že se nebudou více rozlévati vody Noé po zemi, tak jsem přisáhl, že se nerozhněvám na tě, aniž tobě přísně domlouvati budu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 54, 10, 'A byť se i hory pohybovaly, a pahrbkové ustupovali, milosrdenství mé však od tebe neodstoupí, a smlouva pokoje mého se nepohne, praví slitovník tvůj Hospodin.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 54, 11, 'Ó ssoužená, vichřicí zmítaná, potěšení zbavená, aj, já položím na karbunkulích kamení tvé, a založím tě na zafiřích.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 54, 12, 'A vzdělám z křištálu skla tvá, a brány tvé z kamení třpytícího se, i všecka pomezí tvá z kamení drahého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 54, 13, 'Synové pak tvoji všickni vyučení budou od Hospodina, a hojnost pokoje budou míti synové tvoji.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 54, 14, 'Na spravedlnosti upevněna budeš. Vzdálíš se od ssoužení, protož se ho nebudeš báti, a od setření, nebo nepřiblíží se k tobě.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 54, 15, 'Aj, budouť nejedni bydliti s tebou, kteříž nejsou moji, ale kdož by bydleje s tebou, byl proti tobě, padne.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 54, 16, 'Aj, já stvořil jsem kováře dýmajícího při ohni na uhlí, a vynášejícího nádobí k dílu svému, já také stvořil jsem zhoubce, aby hubil.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 54, 17, 'Žádný nástroj proti tobě udělaný nepodaří se, a každý jazyk, povstávající proti tobě na soudu, potupíš. Toť jest dědictví služebníků Hospodinových, a spravedlnost jejich ode mne, praví Hospodin.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 55, 1, 'Ej, všickni žízniví, poďte k vodám, i vy, kteříž nemáte žádných peněz. Poďte, kupujte a jezte, poďte, pravím, kupujte bez peněz a bez záplaty víno a mléko.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 55, 2, 'Proč vynakládáte peníze ne za chléb, a práci svou za to, což nenasycuje? Poslechněte mne raději, a jezte to, což jest dobrého, a nechť se kochá v tuku duše vaše.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 55, 3, 'Nakloňte ucha svého, a poďte ke mně, poslechněte, a budeť živa duše vaše; učiním zajisté s vámi smlouvu věčnou, milosrdenství Davidova přepevná.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 55, 4, 'Aj, za svědka národům dal jsem jej, za vůdce a učitele národům.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 55, 5, 'Aj, národu, k němužs se neznal, povoláš, a národové, kteříž tě neznali, k tobě se sběhnou, pro Hospodina Boha tvého, a Svatého Izraelského, nebo tě oslaví.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 55, 6, 'Hledejte Hospodina, pokudž může nalezen býti; vzývejte ho, pokudž blízko jest.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 55, 7, 'Opusť bezbožný cestu svou, a člověk nepravý myšlení svá, a nechť se navrátí k Hospodinu, i slitujeť se nad ním, a k Bohu našemu, nebť jest hojný k odpuštění.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 55, 8, 'Nejsouť zajisté myšlení má jako myšlení vaše, ani cesty vaše jako cesty mé, praví Hospodin.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 55, 9, 'Ale jakož vyšší jsou nebesa než země, tak převyšují cesty mé cesty vaše, a myšlení má myšlení vaše.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 55, 10, 'Nebo jakož prší déšť neb sníh s nebe, a zase se tam nenavracuje, ale napájí zemi, a činí ji plodistvou a úrodnou, tak že vydává símě rozsívajícímu, a chléb jedoucímu,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 55, 11, 'Tak bude slovo mé, kteréž vyjde z úst mých. Nenavrátí se ke mně prázdné, ale učiní to, což mi se líbí, a prospěšně to vykoná, k čemuž je posílám.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 55, 12, 'A protož s veselím vyjdete, a v pokoji sprovozeni budete. Hory i pahrbkové zvučně naproti vám prozpěvovati budou, a všecko dříví polní rukama plésati bude.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 55, 13, 'Místo chrastiny vzejde jedlé, a místo hloží vyroste myrtus, a bude to Hospodinu k slávě, na znamení věčné, kteréž nebude vyhlazeno.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 56, 1, 'Toto praví Hospodin: Ostříhejte soudu, a čiňte spravedlnost; nebo brzo spasení mé přijde, a spravedlnost má zjevena bude.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 56, 2, 'Blahoslavený člověk, kterýž činí to, a syn člověka, kterýž se přídrží toho, ostříhaje soboty, aby jí nepoškvrňoval, a ostříhaje ruky své, aby nic zlého neučinila.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 56, 3, 'Nechť tedy nemluví cizozemec, kterýž se připojuje k Hospodinu, říkaje: Jistě odloučil mne Hospodin od lidu svého. Též ať neříká kleštěnec: Aj, já jsem dřevo suché.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 56, 4, 'Nebo toto praví Hospodin o kleštěncích, kteříž by ostříhali sobot mých, a zvolili to, což mi se líbí, a drželi smlouvu mou:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 56, 5, 'Že dám jim v domě svém a mezi zdmi svými místo, a jméno lepší nežli synů a dcer. Jméno věčné dám jim, kteréž nebude vyhlazeno.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 56, 6, 'Cizozemce pak, kteříž by se připojili k Hospodinu, aby sloužili jemu, a milovali jméno Hospodinovo, jsouce u něho za služebníky, všecky ostříhající soboty, aby jí nepoškvrňovali, a držící smlouvu mou,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 56, 7, 'Ty přivedu k hoře svatosti své, a obveselím je v domě svém modlitebném. Zápalové jejich a oběti jejich příjemné mi budou na oltáři mém; nebo dům můj dům modlitby slouti bude u všech národů.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 56, 8, 'Pravíť Panovník Hospodin, kterýž shromažďuje rozehnané Izraelovy: Ještěť shromáždím k němu a k shromážděným jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 56, 9, 'Všecka zvířata polní poďte žráti, i všecka zvířata lesní.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 56, 10, 'Strážní jeho jsou slepí, všickni napořád nic neznají, všickni jsou psi němí, aniž mohou štěkati; jsou ospalci, leží, milujíce dřímotu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 56, 11, 'Nadto jsou psi obžerní, nevědí, kdy jsou syti; pročež sami se pasou. Neumějí učiti, všickni k cestám svým patří, jeden každý k zisku svému po své straně.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 56, 12, 'Poďte, naberu vína, a opojíme se nápojem opojným, a bude rovně zítřejší jako dnešní den, nýbrž větší a mnohem hojnější.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 1, 'Spravedlivý hyne, a žádný nepřipouští toho k srdci, a muži pobožní odcházejí, a žádný nerozvažuje toho, že před příchodem zlého vychvácen bývá spravedlivý,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 2, 'Že dochází pokoje, a odpočívá na ložci svém, kdožkoli chodí v upřímosti své.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 3, 'Ale vy přistupte sem, synové kouzedlnice, símě cizoložníka a smilnice.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 4, 'Komu se to s takovou chutí posmíváte? Proti komu rozdíráte ústa, vyplazujete jazyk? Zdaliž nejste synové neřádní, símě postranní?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 5, 'Kteříž smilníte v hájích pod každým dřevem zeleným, zabíjejíce syny své při potocích, pod vysokými skalami.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 6, 'Mezi hladkými kameny potočními jest díl tvůj. Tiť jsou, ti los tvůj, na něž také vyléváš mokrou obět, obětuješ suchou obět. V těch-liž bych věcech se kochal?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 7, 'Na hoře vysoké a vyvýšené stavíš lože své, a tam vstupuješ k obětování oběti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 8, 'Pamětné pak znamení své za dvéře a za veřeje stavíš, když ode mne, odkryvši se, vstupuješ, a rozšiřuješ lože své, činíc je prostrannější víc než pohané; miluješ lože jejich, kdež místo oblíbíš.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 9, 'Chodíš i k králi s olejem, a s mnohými vonnými mastmi svými; posíláš zajisté posly své daleko, a ponižuješ se až do hrobu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 10, 'Pro množství cest svých ustáváš, aniž říkáš: Daremnéť jest to. Nalezla jsi sobě zběř ku pomoci, protož neželíš práce.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 11, 'A kohož jsi se děsila a bála, že jsi klamala, a na mne se nerozpomínala, ani připustila k srdci svému? Zdali proto, že jsem já mlčel, a to zdávna, nebojíš se mne?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 12, 'Já tvou spravedlnost oznámím, a skutky tvé, kteřížť nic neprospějí.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 13, 'Když křičeti budeš, nechať tě vysvobodí zběř tvá. Ano pak všecky je zanese vítr, a zachvátí marnost, ale kdož doufá ve mne, vládnouti bude zemí, a dědičně obdrží horu svatou mou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 14, 'Nebo řečeno bude: Vyrovnejte, vyrovnejte, spravte cestu, odkliďte překážky z cesty lidu mého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 15, 'Nebo takto dí ten důstojný a vyvýšený, kterýž u věčnosti přebývá, jehož jméno jest Svatý: Na výsosti a v místě svatém bydlím, ano i s tím, kterýž jest skroušeného a poníženého ducha přebývám, obživuje ducha ponížených, obživuje také srdce skroušených.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 16, 'Nebuduť se zajisté na věky nesnadniti, aniž se budu věčně hněvati, neboť by duch před oblíčejem mým zmizel, i dchnutí, kteréž jsem já učinil.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 17, 'Pro nepravost lakomství jeho rozhněval jsem se, a ubil jsem jej; skryl jsem se a rozhněval proto, že odvrátiv se, odšel cestou srdce svého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 18, 'Vidím cesty jeho, a však uzdravím jej; zprovodím jej, a jemu potěšení navrátím, i těm, kteříž kvílí s ním.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 19, 'Stvořím ovoce rtů, hojný pokoj, dalekému jako blízkému, praví Hospodin, a tak uzdravím jej.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 20, 'Bezbožní pak budou jako moře zbouřené, když se spokojiti nemůže, a jehož vody vymítají nečistotu a bláto.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 21, 'Nemajíť žádného pokoje, praví Bůh můj, bezbožní.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 58, 1, 'Volej vším hrdlem, nezadržuj, jako trouba povyš hlasu svého, a oznam lidu mému převrácenost jejich, a domu Jákobovu hříchy jejich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 58, 2, 'Jakkoli každého dne mne hledají, a znáti cesty mé jsou chtiví, jako by byli národ, kterýž spravedlnost činí, a soudu Boha svého neopouští. Dotazují se mne na soudy spravedlnosti, blízcí Boha býti chtějí,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 58, 3, 'A říkají: Proč se postíváme, poněvadž nepatříš? Trápíváme duše své, a nechceš věděti o tom? Aj, v den postu vašeho líbost provodíte, a ke všem robotám svým přísně doháníte.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 58, 4, 'Aj, k sváru a různici se postíváte, a abyste bili pěstí nemilostivě; nepostíte se tak dnů těch, aby slyšán byl na výsosti hlas váš.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 58, 5, 'Zdaliž to jest takový půst, jakýž oblibuji, a den, v němž by trápil člověk duši svou? Zdali, aby svěsil jako třtina hlavu svou, a podstíral žíni a popel? To-liž nazůveš postem a dnem vzácným Hospodinu?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 58, 6, 'Není-liž toto půst, kterýž oblibuji: Rozvázati svazky bezbožnosti; roztrhnouti snopky obtěžující, a potřené propustiti svobodné, a tak všelijaké jho abyste roztrhli?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 58, 7, 'Není-liž: Abys lámal lačnému chléb svůj, a chudé vypověděné abys uvedl do domu? Viděl-li bys nahého, abys jej přioděl, a před tělem svým abys se neskrýval.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 58, 8, 'Tehdáž se vyrazí jako jitřní záře světlo tvé, a zdraví tvé rychle zkvetne; předcházeti tě zajisté bude spravedlnost tvá, a sláva Hospodinova zbéře tě.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 58, 9, 'Tehdy volati budeš, a Hospodin vyslyší tě; zavoláš, a řekneť: Teď jsem. Jestliže vyvržeš z prostřed sebe jho, a vztahování prstů, a mluvení nepravostí,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 58, 10, 'A vyleješ-li lačnému duši svou, a strápenou duši nasytíš-li: vzejde v temnostech světlo tvé, a mrákota tvá bude jako poledne.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 58, 11, 'Nebo povede tě Hospodin ustavičně, a nasytí i v náramné sucho duši tvou, a kosti tvé tukem naplní. I budeš jako zahrada svlažená, a jako pramen vod, jehož vody nevysychají.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 58, 12, 'A vzdělají od tebe zplození pustiny starodávní; základy od národu do pronárodu vyzdvihneš. I slouti budeš vzdělavatel zbořeniny, a napravovatel stezek k bydlení.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 58, 13, 'Jestliže odvrátíš od soboty nohu svou, abys nevykonával líbosti své v den svatý můj, anobrž nazůveš-li sobotu rozkoší, a svatou Hospodinu slavnou, a budeš-li ji slaviti tak, abys nečinil cest svých, ani vykonával, co by se líbilo, ani nemluvil slova:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 58, 14, 'Tehdy rozkoš míti budeš v Hospodinu, a uvedu tě na vysoká místa země, a způsobím to, abys užíval dědictví Jákoba otce svého; nebo ústa Hospodinova mluvila.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 1, 'Aj, neníť ukrácena ruka Hospodinova, aby nemohla zachovati, aniž jest obtíženo ucho jeho, aby nemohlo slyšeti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 2, 'Ale nepravosti vaše rozloučily vás s Bohem vaším, a hříchové vaši to způsobili, že skryl tvář před vámi, aby neslyšel.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 3, 'Nebo ruce vaše jsou poškvrněné krví, a prstové vaši nepravostí; rtové vaši mluví lež, jazyk váš vynáší převrácenost.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 4, 'Není žádného, ješto by se zasadil o spravedlnost, aniž jest kdo, ješto by zastával pravdy. Doufají v marnost, a mluví daremné věci; počínají nátisk, a rodí nepravost.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 5, 'Vejce bazališková vyseděli, a plátna pavoukového natkali. Kdož by jedl vejce jejich, umře; pakli je roztlačí, vynikne ještěrka.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 6, 'Plátna jejich nehodí se na roucho, aniž se odějí dílem svým; skutkové jejich skutkové nepravosti, a dílo ukrutnosti jest v rukou jejich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 7, 'Nohy jejich k zlému běží, a pospíchají k vylévání krve nevinné. Myšlení jejich jsou myšlení nepravá, zpuštění a setření jest na cestách jejich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 8, 'Cesty pokoje neznají, a není žádné spravedlnosti v šlepějích jejich. Stezky své převracejí tajně; kdožkoli po nich chodí, nemívá pokoje.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 9, 'Protož vzdálil se od nás soud, a nedochází nás spravedlnost. Čekáme-li na světlo, aj, tma, pakli na blesk, v mrákotách chodíme.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 10, 'Makáme jako slepí stěnu, a jako bychom žádných očí neměli, šámáme. Urážíme se o poledni jako v soumrak, u veliké hojnosti podobni jsme mrtvým.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 11, 'Mumleme všickni my jako nedvědi, a jako holubice ustavičně lkáme. Očekáváme na soud, ale není ho, na vysvobození, ale daleké jest od nás.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 12, 'Nebo rozmnožena jsou přestoupení naše před tebou, a hříchové naši svědčí proti nám, poněvadž přestoupení naše jsou při nás, i nepravosti naše. Známeť to,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 13, 'Že jsme se zpronevěřili, a lhali Hospodinu, a odvrátili se od následování Boha svého, že jsme mluvili o nátisku a odvrácení, že jsme ukládali a vynášeli z srdce slova lživá,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 14, 'Tak že odvrácen jest nazpět soud, a spravedlnost zdaleka stojí; nebo klesla na ulici pravda, a pravost nemá průchodu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 15, 'Nýbrž zhynula pravda, a ten, kdož se uchyluje od zlého, loupeži bývá vydán; což vidí Hospodin, a nelíbí se to jemu, že není žádného soudu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 16, 'Když tedy viděl, že není žádného muže, až se užasl, že není žádného prostředníka. A protož vysvobození jemu způsobilo rámě jeho, a spravedlnost jeho sama jej zpodepřela.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 17, 'Nebo oblékl spravedlnost jako pancíř, a lebka spasení na hlavě jeho. Oblékl se v roucho pomsty jako v sukni, a oděl se horlivostí jako pláštěm,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 18, 'Aby podlé skutků, aby podlé nich odplacel prchlivostí protivníkům svým, odměnu nepřátelům svým, i ostrovům odplatu aby dával.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 19, 'I budou se báti na západ jména Hospodinova, a na východu slunce slávy jeho, když se přivalí jako řeka nepřítel, jejž duch Hospodinův preč zažene.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 20, 'Neboť přijde k Sionu vykupitel, a k těm, kteříž se odvracují od přestoupení v Jákobovi, praví Hospodin.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 21, 'Tatoť pak bude smlouva má s nimi, praví Hospodin: Duch můj, kterýž jest v tobě, a slova má, kteráž jsem vložil v ústa tvá, neodejdouť od úst tvých, ani od úst semene tvého, ani od úst potomků semene tvého, praví Hospodin, od tohoto času až na věky.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 1, 'Povstaniž, zastkvěj se, poněvadž přišlo světlo tvé, a sláva Hospodinova vzešla nad tebou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 2, 'Nebo aj, tmy přikryjí zemi, a mrákota národy, ale nad tebou vzejde Hospodin, a sláva jeho nad tebou vidína bude.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 3, 'I budou choditi národové v světle tvém, a králové v blesku, jenž vzejde nad tebou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 4, 'Pozdvihni vůkol očí svých, a popatř. Všickni tito shromáždíce se, k tobě se poberou, synové tvoji zdaleka přijdou, a dcery tvé při boku tvém chovány budou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 5, 'Tehdáž uzříš to, a rozveselíš se, tehdáž podiví se, a rozšíří se srdce tvé; nebo se obrátí k tobě množství mořské, síla pohanů přijde k tobě.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 6, 'Stádo velbloudů přikryje tě, a dromedáři Madianští a Efejští, všickni ti z Sáby přijdou, zlato a kadidlo přinesou, a chvály Hospodinovy zvěstovati budou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 7, 'Všecka stáda Cedarská shromáždí se k tobě, skopcové Nabajotští přisluhovati budou tobě, a obětováni jsouce na mém oltáři, příjemní budou. A takť dům okrasy své ozdobím.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 8, 'I díš: Kdo jsou ti, kteříž se jako hustý oblak sletují, a jako holubice k děrám svým?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 9, 'Na mneť zajisté ostrovové očekávají, a lodí mořské hned zdávna, aby přivedli syny tvé zdaleka, též stříbro své a zlato své s sebou, k slávě Hospodina, Boha tvého a Svatého Izraelského; nebo tě oslaví.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 10, 'I vystavějí cizozemci zdi tvé, a králové jejich přisluhovati budou tobě, když v prchlivosti své ubiji tě, a v dobré líbeznosti své slituji se nad tebou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 11, 'A otevříny budou brány tvé ustavičně, ve dne ani v noci nebudou zavírány, aby přivedli k tobě sílu pohanů, i králové jejich aby přivedeni byli.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 12, 'Národ zajisté ten a království, kteréž by nesloužilo tobě, zahyne; národové, pravím, ti docela pohubeni budou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 13, 'Sláva Libánská přijde k tobě, jedle, jilm, též i pušpan k ozdobě místa svatyně mé, abych místo noh svých oslavil.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 14, 'Také přijdou k tobě s ponížením synové těch, kteříž tě trápili, a klaněti se budou k zpodku noh tvých, kteřížkoli pohrdali tebou, a nazývati tě budou městem Hospodinovým, Sionem Svatého Izraelského.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 15, 'Místo toho, že jsi byla opuštěná a v nenávisti, tak že žádný skrze tě nechodil, způsobímť důstojnost věčnou, a veselí od národu do pronárodu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 16, 'Nebo ssáti budeš mléko národů, a prsy králů ssáti budeš; i poznáš, že jsem já Hospodin vysvoboditel tvůj, a vykupitel tvůj silný Jákobův.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 17, 'Místo mědi dodávati budu zlata, a místo železa dodávati budu stříbra, a místo dříví mědi, a místo kamení železa, a představímť správce pokojné a úředníky spravedlivé.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 18, 'Nebude více slyšáno o bezpraví v zemi tvé, o zpuštění a zhoubě na hranicích tvých, ale hlásati budeš spasení na zdech svých, a v branách svých chválu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 19, 'Nebudeš míti více slunce za světlo denní, a blesk měsíce nebude tě osvěcovati, ale budeť Hospodin světlem tvým věčným, a Bůh tvůj okrasou tvou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 20, 'Nezajdeť více slunce tvé, a měsíc tvůj neschová se, nebo Hospodin bude světlem tvým věčným, a tak dokonáni budou dnové smutku tvého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 21, 'Lid také tvůj, kteříž by koli byli spravedliví, na věky dědičně obdrží zemi, výstřelek štípení mého, dílo rukou mých, abych v něm oslavován byl.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 22, 'Samotný rozmnoží se v tisíce, a nejšpatnější v národ nesčíslný, já Hospodin časem svým brzo způsobím to.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 61, 1, 'Duch Panovníka Hospodina jest nade mnou, proto že pomazal mne Hospodin, abych kázal evangelium tichým. Poslal mne, abych uvázal rány skroušených srdcem, abych vyhlásil jatým svobodu, a vězňům otevření žaláře,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 61, 2, 'Abych vyhlásil léto milostivé Hospodinovo, a den pomsty Boha našeho, abych těšil všecky kvílící,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 61, 3, 'Abych způsobil radost kvílícím Sionským, a dal jim okrasu místo popela, olej veselé místo smutku, oděv chvály místo ducha sevřeného. I nazvání budou stromové spravedlnosti, štípení Hospodinovo, abych oslavován byl.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 61, 4, 'Tedy vzdělají pustiny starodávní, pouště staré spraví, a obnoví města zpuštěná, pustá po mnohé národy.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 61, 5, 'Nebo postaví se cizozemci, a pásti budou stáda vaše, a synové cizozemců oráči vaši a vinaři vaši budou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 61, 6, 'Vy pak kněží Hospodinovi nazváni budete, služebníci Boha našeho slouti budete, zboží pohanů užívati budete, a v slávě jejich zvýšeni budete.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 61, 7, 'Za dvojnásobní zahanbení vaše a pohanění prozpěvovati budete, z podílu jejich a v zemi jejich dvojnásobní dědictví obdržíte, a tak veselé věčné míti budete.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 61, 8, 'Já zajisté Hospodin miluji soud, a nenávidím loupeže při oběti, a protož způsobím, aby skutkové jejich dáli se v pravdě, a smlouvu věčnou s nimi učiním.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 61, 9, 'I vejdeť v známost mezi pohany símě jejich, a potomci jejich u prostřed národů. Všickni, kteříž je uzří, poznají je, že jsou símě, jemuž požehnal Hospodin.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 61, 10, 'Velice se budu radovati v Hospodinu, a plésati bude duše má v Bohu mém; nebo mne oblékl v roucho spasení, a pláštěm spravedlnosti přioděl mne jako ženicha, kterýž se strojí ozdobně, a jako nevěstu okrašlující se ozdobami svými.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 61, 11, 'Nebo jakož země vydává zrostlinu svou, a jakož zahrada símě své vyvodí, tak Panovník Hospodin vyvede spravedlnost a chválu přede všemi národy.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 62, 1, 'Pro Sion nebudu mlčeti, a pro Jeruzalém neupokojím se, dokudž nevyjde jako blesk spravedlnost jeho, a spasení jeho jako pochodně hořeti nebude.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 62, 2, 'I uzří národové spravedlnost tvou, a všickni králové slávu tvou, a nazovou tě jménem novým, kteréž ústa Hospodinova vyřknou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 62, 3, 'Nadto budeš korunou ozdobnou v ruce Hospodinově, a korunou královskou v ruce Boha svého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 62, 4, 'Nebudeš více slouti opuštěná, a země tvá nebude více slouti pustinou, ale ty nazývána budeš rozkoší, a země tvá vdanou; nebo rozkoš míti bude Hospodin v tobě, a země tvá bude vdaná.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 62, 5, 'Nebo jakož pojímá mládenec pannu, tak tě sobě pojmou synové tvoji, a jakou má radost ženich z nevěsty, tak radovati se bude z tebe Bůh tvůj.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 62, 6, 'Na zdech tvých, Jeruzaléme, postavím strážné, kteříž přes celý den i přes celou noc nikdy nebudou mlčeti. Kteříž tedy připomínáte Hospodina, nemlčtež,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 62, 7, 'A nedávejte jemu pokoje, dokudž neutvrdí, a dokudž nezpůsobí, aby Jeruzalém byl slavný na zemi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 62, 8, 'Přisáhltě Hospodin skrze pravici svou, a skrze rámě síly své, řka: Nikoli nedám obilí tvého více za pokrm nepřátelům tvým, aniž píti budou cizozemci vína tvého, o němž jsi pracoval.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 62, 9, 'Ale ti, kteříž je shromažďují, budou je jísti, a chváliti Hospodina, a kteříž je zbírají, budou je píti v síňcích svatosti mé.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 62, 10, 'Vejdětež, vejdětež branami, spravte cestu lidu, vyrovnejte, vyrovnejte silnici, vybeřte kamení, vyzdvihněte korouhev k národům.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 62, 11, 'Aj, Hospodin rozkáže provolati až do končin země: Rcetež dceři Sionské: Aj, Spasitel tvůj béře se, aj, mzda jeho s ním, a dílo jeho před ním.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 62, 12, 'I nazovou syny tvé lidem svatým, vykoupenými Hospodinovými, ty pak slouti budeš městem vzácným a neopuštěným.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 1, 'Kdož jest to, ješto se béře z Edom, v ubroceném rouše z Bozra, ten ozdobený rouchem svým, kráčeje u velikosti síly své? Jáť jsem, kterýž mluvím spravedlivě, dostatečný k vysvobození.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 2, 'Proč jest červené roucho tvé, a oděv tvůj jako toho, kterýž tlačí v presu?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 3, 'Pres jsem tlačil sám, aniž kdo z lidí byl se mnou. Tlačil jsem nepřátely v hněvě svém, a pošlapal jsem je v prchlivosti své, až stříkala krev i nejsilnějších jejich na roucho mé, a tak všecken oděv svůj zkálel jsem.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 4, 'Den zajisté pomsty v srdci mém, a léto, v němž mají vykoupeni býti moji, přišlo.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 5, 'Když jsem pak viděl, že není žádného spomocníka, až jsem se užasl, že žádného nebylo, kdo by podpíral. A protož mi vysvobození způsobilo rámě mé, a prchlivost má, ta mne podepřela.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 6, 'I pošlapal jsem národy v hněvě svém, a opojil jsem je prchlivostí svou, a porazil jsem na zem nejsilnější reky jejich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 7, 'Milosrdenství Hospodinova připomínati budu, a chvály Hospodinovy ze všeho, což učinil nám Hospodin, i množství dobroty, kteréž dokazoval k domu Izraelskému z veliké lítosti své, a z velikého milosrdenství svého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 8, 'Nebo řekl: Vždyť jsou lidem mým, jsou synové, neučiníť mi nevěrně. A protož byl jejich spasitelem.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 9, 'Ve všelikém ssoužení jejich i on měl ssoužení, a anděl přístojící jemu vysvobozoval je. Z milování svého a z lítosti své on sám vykoupil je, a pěstoval je, i nosil je po všecky dny věků.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 10, 'Ale oni zpurní byli, a zarmucovali Ducha svatého jeho; pročež obrátil se jim v nepřítele, a sám bojoval proti nim.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 11, 'I rozpomínal se lid jeho na dny starodávní, i na Mojžíše: Kdež jest ten, kterýž je vyvedl z moře s pastýřem stáda svého? Kde jest ten, kterýž položil u prostřed něho Ducha svatého svého?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 12, 'Kterýž je vedl ramenem velebnosti své po pravici Mojžíšově, kterýž rozdělil vody před nimi, aby sobě způsobil jméno věčné,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 13, 'Kterýž je provedl skrze hlubiny jako koně po poušti, ani se nepoklesli.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 14, 'Jako když hovádko do údolí sstupuje, tak Duch Hospodinův poznenáhlu vedl z nich každého. Tak jsi vedl lid svůj, abys sobě způsobil jméno slavné.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 15, 'Popatřiž s nebe, a pohleď z příbytku svatosti své a okrasy své. Kdež jest horlivost tvá a veliká síla tvá? Kde množství milosrdenství tvých a slitování tvých? Mně-liž se zadržovati budou?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 16, 'Ty jsi zajisté otec náš; nebo Abraham nic neví o nás, a Izrael nezná nás. Ty jsi, Hospodine, otec náš, vykupitel náš, toť jest od věčnosti jméno tvé.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 17, 'Pročež jsi nám dal zblouditi, Hospodine, od cest svých, zatvrdil jsi srdce naše, abychom se nebáli tebe? Navratiž se zase pro služebníky své, pokolení dědictví svého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 18, 'Nejšpatnější vládne lidem svatosti tvé, nepřátelé naši pošlapali svatyni tvou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 19, 'My tvoji jsme od věků; nad nimi jsi nikdy nepanoval, aniž nad nimi jméno tvé vzýváno jest.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 64, 1, 'Ó bys protrhl nebesa a sstoupil, aby se od přítomnosti tvé hory rozplynouti musily,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 64, 2, '(Jako od rozníceného ohně rozpouštějícího voda vře), abys v známost uvedl jméno své nepřátelům svým, a aby se před tváří tvou národové třásli;');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 64, 3, 'Jako když jsi činil hrozné věci, jichž jsme se nenadáli, sstoupil jsi, před oblíčejem tvým hory se rozplývaly;');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 64, 4, 'Čehož se od věků neslýchalo, a ušima nepochopilo, oko nevídalo Boha kromě tebe, aby tak činil tomu, kterýž naň očekává.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 64, 5, 'Vyšel jsi vstříc tomu, kdož ochotně činí spravedlnost, a na cestách tvých na tě se rozpomínali. Aj, ty rozhněvals se, proto že jsme hřešili na nich ustavičně, a však zachováni budeme,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 64, 6, 'Ačkoli jsme jako nečistý my všickni, a jako roucho ohyzdné všecky spravedlnosti naše. Pročež pršíme jako list my všickni, a nepravosti naše jako vítr zachvacují nás.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 64, 7, 'Nadto není žádného, ješto by vzýval jméno tvé, a probudil se k tomu, aby se chopil tebe, aspoň když jsi skryl tvář svou před námi, a způsobil to, abychom mizeli pro nepravosti naše.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 64, 8, 'Ale již, ó Hospodine, ty jsi otec náš, my hlina, ty pak učinitel náš, a tak jsme všickni dílo ruky tvé.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 64, 9, 'Nehněvejž se tak velmi, Hospodine, aniž se na věky rozpomínej na nepravost. Ó vzhlédniž, prosíme, všickni my lid tvůj jsme.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 64, 10, 'Města svatosti tvé obrácena jsou v poušť, Sion v poušť, i Jeruzalém v pustinu obrácen.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 64, 11, 'Dům svatosti naší a okrasy naší, v kterémž tě chválívali otcové naši, ohněm zkažen, a cožkoli jsme měli nejvzácnějšího, jest popléněno.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 64, 12, 'I zdaliž pro ty věci, Hospodine, se zdržíš? Mlčeti a nás tak velmi trápiti budeš?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 1, 'Dal jsem se najíti těm, kteříž se na mne neptávali, nalezen jsem od těch, kteříž mne nehledali, a národu, kterýž se nenazýval jménem mým, řekl jsem: Teď jsem, teď jsem.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 2, 'Rozprostíral jsem ruce své na každý den k lidu zpurnému, kteříž chodí cestou nedobrou za myšlénkami svými,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 3, 'K lidu, kteříž zjevně popouzejí mne ustavičně, obětujíce v zahradách, a kadíce na cihlách,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 4, 'Kteříž sedají při hrobích, a při svých modlách nocují, kteříž jedí maso sviňské, a polívku nečistého z nádob svých,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 5, 'Říkajíce: Táhni preč, nepřistupuj ke mně, nebo světější jsem nežli ty. Tiť jsou dymem v chřípích mých a ohněm hořícím přes celý den.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 6, 'Aj, zapsáno jest to přede mnou: Nebuduť mlčeti, nýbrž nahradím a odplatím do lůna jejich,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 7, 'Za nepravosti vaše, a spolu za nepravosti otců vašich, praví Hospodin, kteříž kadívali na horách, a na pahrbcích v lehkost uvodili mne; pročež odměřím za dílo jejich předešlé do lůna jejich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 8, 'Takto praví Hospodin: Jako někdo nalezna víno v hroznu, i řekl by: Nekaz ho, proto že požehnání jest v něm, tak i já učiním pro služebníky své, že nevyhladím všech těchto.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 9, 'Nebo vyvedu z Jákoba símě, a z Judy toho, kterýž by dědičně obdržel hory mé, i budou ji dědičně držeti vyvolení moji, a služebníci moji bydliti budou tam.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 10, 'Lid pak můj, kteříž by mne hledali, budou míti Sáron za pastviště ovcím, a údolí Achor za odpočivadlo skotům.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 11, 'Ale vás, kteříž opouštíte Hospodina, kteříž se zapomínáte na horu svatosti mé, kteříž strojíte vojsku tomu stůl, a kteříž vykonáváte tomu počtu oběti,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 12, 'Vás, pravím, sečtu pod meč, tak že všickni vy k zabití na kolena padati budete, proto že, když jsem volal, neohlásili jste se, mluvil jsem, a neslyšeli jste, ale činili jste to, což zlého jest před očima mýma, a to, čehož neoblibuji, vyvolili jste.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 13, 'A protož takto dí Panovník Hospodin: Aj, služebníci moji jísti budou, vy pak hlad trpěti budete: aj, služebníci moji píti budou, vy pak žízniti budete; aj, služebníci moji veseliti se budou, vy pak zahanbeni budete.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 14, 'Aj, služebníci moji prozpěvovati budou pro radost srdce, vy pak křičeti budete pro bolest srdce, a pro setření ducha kvíliti budete,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 15, 'A zanecháte jména svého k proklínání vyvoleným mým, když vás pomorduje Panovník Hospodin, služebníky pak své nazůve jménem jiným.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 16, 'Ten, kterýž bude sobě požehnání dávati na zemi, požehnání dávati sobě bude v Bohu pravém, a kdož přisahati bude na zemi, přisahati bude skrze Boha pravého; v zapomenutí zajisté dána budou ta ssoužení první, a budou skryta od očí mých.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 17, 'Nebo aj, já stvořím nebesa nová a zemi novou, a nebudou připomínány první věci, aniž vstoupí na srdce.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 18, 'Anobrž radujte se a veselte se na věky věků z toho, což já stvořím; nebo aj, já stvořím Jeruzalém k plésání, a lid jeho k radosti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 19, 'I já plésati budu v Jeruzalémě, a radovati se v lidu svém, aniž se více bude slýchati v něm hlasu pláče, aneb hlasu křiku.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 20, 'Nebude tam více žádného v věku dětinském, ani starce, kterýž by dnů svých nevyplnil; nebo dítě ve stu letech umře, hříšníku pak, by došel i sta let, zlořečeno bude.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 21, 'Nastavějí též domů, a bydliti budou v nich, i vinice štěpovati budou, a jísti budou ovoce jejich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 22, 'Nebudou stavěti tak, aby jiný bydlil, nebudou štěpovati, aby jiný jedl; nebo jako dnové dřeva budou dnové lidu mého, a díla rukou svých do zvetšení užívati budou vyvolení moji.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 23, 'Nebudouť pracovati nadarmo, aniž ploditi budou k strachu; nebo budou símě požehnaných od Hospodina, i potomkové jejich s nimi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 24, 'Nadto stane se, že prvé než volati budou, já se ohlásím; ještě mluviti budou, a já vyslyším.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 25, 'Vlk s beránkem budou se pásti spolu, a lev jako vůl bude jísti plevy, hadu pak za pokrm bude prach. Neuškodíť, aniž zahubí na vší mé hoře svaté, praví Hospodin.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 1, 'Takto praví Hospodin: Nebe jest mi stolice, a země podnože noh mých. Kdež ten dům bude, kterýž mi vzděláte? Aneb kde bude místo odpočívání mého?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 2, 'Nebo všecko to ruka má učinila, a jí stojí všecko, praví Hospodin. I však na toho patřím, kdož jest chudý a skroušeného ducha, a třese se před slovem mým.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 3, 'Sic jinak ten, kdož zabijí vola, zabil člověka; kdo zabijí hovádko, psa sťal; kdo obětuje obět suchou, krev sviňskou obětoval; kdo kadí kadidlem, dary dával modle. To oni vyvolili na cestách svých, proto že, v ohavnostech svých duše jejich se kochá.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 4, 'I jáť také vyvolím za nešlechetnosti jejich, a to, čehož se strachují, na ně uvedu, proto že, když jsem volal, žádný se neohlásil, když jsem mluvil, neslyšeli, ale činili to, což zlého jest před očima mýma, a to, čehož neoblibuji, vyvolili.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 5, 'Slyšte slovo Hospodinovo, kteříž se třesete před slovem jeho: Říkávají bratří vaši, v nenávisti majíce vás, a vypovídajíce vás pro jméno mé: Nechť se zjeví sláva Hospodinova. Ukážeť se zajisté ku potěšení vašemu, ale oni zahanbeni budou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 6, 'Hlas hřmotu z města, hlas z chrámu, hlas Hospodinův, an odplatu dává nepřátelům svým.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 7, 'Prvé než pracovala ku porodu, porodila; prvé než přišla na ni bolest, porodila pacholátko.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 8, 'Kdo slýchal co takového? Kdo vídal co podobného? Zdaliž může způsobeno býti, aby země zplodila lid dne jednoho? Zdaliž zplozen bývá národ pojednou? Ale Sion jen počal pracovati ku porodu, a porodil syny své.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 9, 'Což bych já, kterýž otvírám život matky, neplodil? praví Hospodin. Což bych já, kterýž činím to, aby rodily, zavřín byl? praví Bůh tvůj.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 10, 'Veselte se s Jeruzalémem, a plésejte v něm všickni, kteříž jej milujete. Radujte se s ním velice, kteříž jste koli kvílili nad ním,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 11, 'Proto že ssáti budete, a sytiti se z prs potěšení jeho, ssáti budete, a rozkoš míti v blesku slávy jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 12, 'Nebo takto praví Hospodin: Aj, já obrátím na něj jako řeku pokoj, a jako potok rozvodnilý slávu národů. I budete ssáti, na rukou pěstováni a na klíně rozkošně chováni budete.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 13, 'Jako ten, kteréhož matka jeho těší, tak já vás těšiti budu, a tak v Jeruzalémě potěšováni budete.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 14, 'Uzříte zajisté, a radovati se bude srdce vaše, a kosti vaše jako bylinka zkvetnou. I seznána bude ruka Hospodinova při služebnících jeho, a prchlivost proti nepřátelům jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 15, 'Nebo aj, Hospodin v ohni přijde, a jako vichřice budou vozové jeho, aby vypustil v prchlivosti hněv svůj, a žehrání své v plameni ohně.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 16, 'Hospodin, pravím, ohněm mstíti bude, a mečem svým nad všelikým tělem, tak že mnoho bude zbitých od Hospodina.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 17, 'I ti, kteříž se posvěcují a očišťují v zahradách, jeden po druhém zjevně, kteříž jedí maso sviňské, a věc ohavnou i myši, též konec vezmou, praví Hospodin.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 18, 'Nebo já, když skutkové a myšlení jejich přijdou, shromáždím všecky národy a jazyky. I přijdou, a uzří slávu mou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 19, 'A položím na ně znamení, a pošli z nich, kteříž zachováni budou, k národům do Tarsu, Pul a Lud, jenž natahují lučiště, do Tubal a Javan, na ostrovy daleké, kteříž neslýchali pověsti o mně, aniž vídali slávy mé. I budou zvěstovati slávu mou mezi národy.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 20, 'A přivedou všecky bratří vaše ze všech národů za dar Hospodinu, na koních a na vozích, a na nůších a na mezcích, a na dromedářích, na horu svatosti mé do Jeruzaléma, praví Hospodin, tak jako přinášejí synové Izraelští dar v nádobě čisté do domu Hospodinova.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 21, 'A z těchť také vezmu za kněží a za Levíty, praví Hospodin.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 22, 'Nebo jakož ta nebesa nová, a země ta nová, kterouž já učiním, stane přede mnou, praví Hospodin, tak stane símě vaše a jméno vaše.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 23, 'I stane se, že od novměsíce do novměsíce, od soboty do soboty přicházeti bude všeliké tělo, aby se klanělo přede mnou, praví Hospodin.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 24, 'A vyjdouce, uzří těla mrtvá lidí těch, kteříž se mi zpronevěřili; nebo červ jejich neumře, a oheň jejich neuhasne. I budouť v ošklivosti všelikému tělu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 1, 'Slova Jeremiáše syna Helkiášova, z kněží, kteříž byli v Anatot, v zemi Beniamin,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 2, 'K němuž se stalo slovo Hospodinovo za dnů Joziáše syna Amonova, krále Judského, třináctého léta kralování jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 3, 'Byl i za dnů Joakima syna Joziášova, krále Judského, až do vyplnění jedenáctého léta Sedechiáše syna Joziášova, krále Judského, až do zajetí Jeruzaléma měsíce pátého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 4, 'Stalo se, pravím, slovo Hospodinovo ke mně, řkoucí:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 5, 'Dříve než jsem tě sformoval v životě, znal jsem tebe, a dříve nežlis vyšel z života, posvětil jsem tě, za proroka národům dal jsem tebe.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 6, 'I řekl jsem: Ach, Panovníče Hospodine, aj, neumím mluviti, nebo dítě jsem.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 7, 'Ale Hospodin řekl mi: Neříkej, dítě jsem, nýbrž k čemuž tě koli pošli, jdi, a vše, cožť přikáži, mluv.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 8, 'Neboj se jich, neboť jsem s tebou, abych tě vysvobozoval, dí Hospodin.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 9, 'A vztáhna ruku svou Hospodin, dotekl se úst mých, a řekl mi Hospodin: Aj, vložil jsem slova svá v ústa tvá.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 10, 'Hle, ustanovuji tě dnešního dne nad národy a nad královstvími, abys plénil a kazil, a hubil a bořil, abys stavěl a štěpoval.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 11, 'Potom se stalo slovo Hospodinovo ke mně, řkoucí: Co vidíš, Jeremiáši? I řekl jsem: Prut mandlový vidím.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 12, 'Tedy řekl mi Hospodin: Dobře vidíš; nebo pospíchám já s slovem svým, abych je vykonal.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 13, 'Opět stalo se slovo Hospodinovo ke mně po druhé, řkoucí: Co vidíš? I řekl jsem: Vidím hrnec, an vře, a přední strana jeho k straně půlnoční.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 14, 'Tedy řekl mi Hospodin: Od půlnoci přivalí se to zlé na všecky obyvatele této země.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 15, 'Nebo aj, já svolám všecky rodiny království půlnočních, dí Hospodin, aby přitáhnouce, postavili jeden každý stolici svou v branách Jeruzalémských, a při všech zdech jeho vůkol, a při všech městech Judských.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 16, 'A tak vypovím úsudky své proti nim, pro všelikou nešlechetnost těch, kteříž opustili mne, a kadili bohům cizím, a skláněli se dílu rukou svých.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 17, 'Protož ty přepaš bedra svá, a vstana, mluv k nim, cožkoli já přikazuji tobě. Nelekej se jich, abych tě nepotřel před oblíčejem jejich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 18, 'Nebo aj, já postavuji tě dnes jako město hrazené, a jako sloup železný, a jako zdi měděné proti vší této zemi, proti králům Judským, proti knížatům jejím, proti kněžím jejím, a lidu země této.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 19, 'Kteříž bojovati budou proti tobě, ale neodolají proti tobě. Nebo já jsem s tebou, praví Hospodin, abych tě vysvobozoval.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 1, 'I stalo se slovo Hospodinovo ke mně, řkoucí:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 2, 'Jdi a volej, tak aby slyšel Jeruzalém, řka: Takto praví Hospodin: Rozpomínám se na tě pro milosrdenství mladosti tvé, a pro lásku snětí tvého, když jsi za mnou chodila po poušti v zemi, kteráž nebývá osívána.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 3, 'Tehdáž svatost Hospodinova byl Izrael, prvotiny úrod jeho. Všickni, kteříž jej zžírali, obviněni byli; zlé věci na ně přišly, praví Hospodin.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 4, 'Slyšte slovo Hospodinovo, dome Jákobův, a všecky čeledi domu Izraelského.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 5, 'Takto praví Hospodin: Jakou shledali otcové vaši při mně nepravost, že se vzdálili ode mne, a chodíce za marností, marní učiněni jsou,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 6, 'Tak že ani neřekli: Kde jest Hospodin, kterýž nás vyvedl z země Egyptské, kterýž nás vodil po poušti, po zemi pusté a strašlivé, po zemi vyprahlé a stínu smrti, po zemi, skrze niž nechodil žádný, a kdež žádný člověk nebydlil?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 7, 'Nýbrž, když jsem vás uvedl do země úrodné, abyste jedli ovoce její i dobré věci její, všedše tam, poškvrnili jste země mé, a dědictví mé zohavili jste.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 8, 'Kněží neřekli: Kde jest Hospodin? a ti, kteříž se obírají s zákonem, nepoznali mne, pastýři pak odstoupili ode mne, a proroci prorokovali skrze Bále, a za věcmi neužitečnými chodili.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 9, 'Pročež vždy nesnáz mám s vámi, praví Hospodin, i s syny synů vašich nesnáz míti musím.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 10, 'Projděte ale ostrovy Citim, a pohleďte, i do Cedar pošlete, a pošetřte pilně, a pohleďte, stalo-li se co takového.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 11, 'Zdali změnil který národ bohy, ačkoli nejsou bohové? Lid pak můj změnil slávu svou v věc neužitečnou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 12, 'Užasněte se nebesa nad tím, a děste se, chřadněte velmi, praví Hospodin.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 13, 'Nebo dvojí zlost spáchal lid můj: Mne opustili pramen vod živých, aby sobě vykopali čisterny, čisterny děravé, kteréž nedrží vody.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 14, 'Zdali otrok jest Izrael? Zdali man doma zplozený? Pročež vydán jest v loupež?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 15, 'Lvíčata řvou na něj, a vydávají hlas svůj, a obracejí zemi jeho v pustinu; města jeho vypálena jsou, tak že není žádného obyvatele.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 16, 'Obyvatelé také Nof a Tachpanes pasou na vrchu hlavy tvé.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 17, 'Zdaliž toho sobě nepůsobíš, opouštějíc Hospodina Boha svého v ten čas, když tě vodí po cestě své?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 18, 'A nyní co tobě do cesty Egyptské, že piješ vodu z Níle? Aneb co tobě do cesty Assyrské, že piješ vodu z řeky?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 19, 'Trestati tě bude zlost tvá, a odvrácení tvá domlouvati budou tobě. Poznejž tedy a viz, že zlá a hořká věc jest, že opouštíš Hospodina Boha svého, a není bázně mé při tobě, dí Panovník Hospodin zástupů.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 20, 'Ačkoli dávno polámal jsem jho tvé, potrhal jsem to, čím jsi svázána byla, a řeklas: Nebuduť sloužiti modlám, však po každém pahrbku vysokém, a pod každým dřevem zeleným touláš se, ó nevěstko.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 21, 'Ješto jsem já tě vysadil vinným kmenem výborným, všecku napořád semenem čistotným, i kterakž jsi mi proměnila se v plané réví cizího kmene?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 22, 'Nebo bys ty se pak umyla sanitrem, a mnoho na sebe mýdla vypotřebovala, předceť patrná jest nepravost tvá před oblíčejem mým, praví Panovník Hospodin.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 23, 'Kterakž můžeš říci: Nepoškvrňovala jsem se, za Báli jsem nechodila? Pohleď na cestu svou v tomto údolí, poznej, cos činila, dromedářko rychlá, kteráž znamení necháváš na cestách svých.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 24, 'Jsi divoká oslice, zvyklá na poušti, kteráž podlé líbosti duše své hltá vítr, když se jí příčina dá. Kdo jí překážku učiní? Všickni ti, kteříž jí hledají, nepotřebí se jim kvaltovati, naleznouť ji v měsíci jejím.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 25, 'Dí-liť kdo: Zdržuj nohu svou, aby bosá nebyla, a hrdlo své od žízně, tedy říkáš: To nic, nikoli; nebo jsem zamilovala cizí, a za nimi choditi budu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 26, 'Jakož k hanbě přichází zloděj, když postižen bývá, tak zahanben bude dům Izraelský, oni, králové jejich, knížata jejich, a kněží jejich, i proroci jejich,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 27, 'Kteříž říkají dřevu: Otec můj jsi, a kameni: Ty jsi mne zplodil. Nebo se hřbetem ke mně obracejí a ne tváří, ale v čas trápení svého říkají: Vstaň a vysvoboď nás.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 28, 'I kdež jsou bohové tvoji, kterýchž jsi nadělal sobě? Nechť vstanou, budou-li tě moci vysvoboditi v čas trápení tvého, poněvadž podlé počtu měst svých máš bohy své, ó Judo.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 29, 'Co se vaditi budete se mnou? Vy všickni odstoupili jste ode mne, dí Hospodin.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 30, 'Nadarmo jsem bil syny vaše, kázně nepřijali; sežral meč váš proroky vaše jako lev, kterýž dáví.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 31, 'Ó národe, vy posuďte slova Hospodinova, zdali jsem byl pouští Izraelovi, zdali zemí tmavou? Proč říká lid můj: Panujeme, nepřijdeme více k tobě?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 32, 'Zdali se zapomíná panna na ozdoby své, a nevěsta na tkanice své? Lid pak můj zapomněl se na mne za dny nesčíslné.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 33, 'Proč zastáváš cesty své, hledajíc toho, což miluješ? Pročež i jiné nešlechetnice učíš cestám svým.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 34, 'Nad to, na podolcích tvých nalézá se krev duší chudých nevinných. Nenesnadně nalézám to, nebo viděti to na těch všech podolcích.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 35, 'A vždy říkáš: Poněvadž nevinná jsem, jistě odvrácena jest prchlivost jeho ode mne. Aj, já v soud vejdu s tebou, proto že pravíš: Nehřešila jsem.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 36, 'Proč tak běháš, proměňujíc cestu svou? Jakož jsi zahanbena od Assyrských, tak i od Egyptských zahanbena budeš.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 37, 'Také odtud vyjdeš, a ruce tvé budou nad hlavou tvou; nebo zamítá Hospodin troštování tvá, a nepovedeť se šťastně v nich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 1, 'Dí dále: Propustil-li by muž ženu svou, a ona odejduc od něho, vdala by se za jiného muže, zdaliž se navrátí k ní více? Zdaliž by hrozně nebyla poškvrněna země ta? Ale ty, ač jsi smilnila s milovníky mnohými, a však navratiž se ke mně, dí Hospodin.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 2, 'Pozdvihni očí svých k vysokým místům, a pohleď, kdes necizoložila? Na cestách usazovalas se jim jako Arab na poušti, a poškvrnila jsi země smilstvím svým a nešlechetností svou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 3, 'A ačkoli zadržáni jsou podzimní dešťové, a deště jarního nebývalo, však čelo ženy nevěstky majíc, nechtělas se styděti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 4, 'Zdali od nynějšího času volati budeš ke mně: Otče můj, ty jsi vůdce mladosti mé?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 5, 'Zdaliž Bůh držeti bude hněv na věčnost? Zdali chovati jej bude na věky? Aj, mluvíš i pášeš zlé věci, jakž jen můžeš.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 6, 'Tedy řekl mi Hospodin za dnů Joziáše krále: Viděl-lis, co činila zpurná dcera Izraelská? Chodívala na každou horu vysokou, i pod každé dřevo zelené, a tam smilnila.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 7, 'A ačkoli jsem řekl, když ty všecky věci ona činila: Nechť se navrátí ke mně, však se nenavrátila. Načež hleděla zpronevěřilá sestra její, dcera Judská.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 8, 'Pročež vidělo mi se pro ty všecky příčiny, poněvadž cizoložila zpurná dcera Izraelská, propustiti ji, a dáti jí lístek zapuzení jejího. Však se vždy neulekla zpronevěřilá sestra její, dcera Judská, ale šedši, smilnila také sama.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 9, 'I stalo se, že hanebným smilstvím svým poškvrnila země; nebo cizoložila s kamenem i s dřevem.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 10, 'A však s tím se vším neobrátila se ke mně zpronevěřilá sestra její, dcera Judská, celým srdcem svým, ale pokrytě, praví Hospodin.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 11, 'Protož řekl Hospodin ke mně: Ospravedlnila duši svou zpurná dcera Izraelská, více nežli zpronevěřilá Judská.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 12, 'Jdi a volej slovy těmito ku půlnoci, a rci: Navrať se, zpurná dcero Izraelská, dí Hospodin, a neoboří se tvář má zůřivá na vás; nebo já dobrotivý jsem, dí Hospodin, aniž držím hněvu na věčnost.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 13, 'Jen toliko poznej nepravost svou, že jsi od Hospodina Boha svého odstoupila, a sem i tam běhala cestami svými k cizím pod každé dřevo zelené, a hlasu mého neposlouchali jste, dí Hospodin.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 14, 'Navraťte se synové zpurní, dí Hospodin; nebo já jsem manžel váš, a přijmu vás, jednoho z města, a dva z čeledi, abych vás uvedl na Sion.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 15, 'Kdežto dám vám pastýře podlé srdce svého, kteříž pásti vás budou uměle a rozumně.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 16, 'I stane se, když se rozmnožíte a rozplodíte v této zemi za dnů těch, dí Hospodin, že nebudou říkati více: Truhla smlouvy Hospodinovy, aniž jim vstoupí na srdce, aniž zpomenou na ni, ani k ní choditi, aniž bude více u vážnosti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 17, 'V ten čas nazývati budou Jeruzalém stolicí Hospodinovou, a shromáždí se tam všickni národové ke jménu Hospodinovu do Jeruzaléma, a nebudou choditi více podlé zdání srdce svého zlého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 18, 'V těch dnech přijdou dům Judský s domem Izraelským, a přiberou se spolu z země půlnoční do země, kterouž jsem v dědictví uvedl otcům vašim;');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 19, 'Ač já pravím: Kterakž bych tě počísti mohl mezi syny, a dáti tobě zemi žádostivou, dědictví slavné zástupů pohanských, leč abys mne vzýval, říkaje: Otče můj, a od následování mne abys se neodvracel?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 20, 'Poněvadž jakož žena zpronevěřuje se manželu svému, tak jste se zpronevěřili mně, dome Izraelský, dí Hospodin.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 21, 'Hlas po místech vysokých buď slyšán, pláč pokorné modlitby synů Izraelských. Nebo převrátivše cesty své, zapomněli se na Hospodina Boha svého, řkoucího:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 22, 'Navraťte se, synové zpurní, a uzdravím odvrácení vaše. Rcete: Aj, my jdeme k tobě, nebo ty, Hospodine, jsi Bůh náš.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 23, 'Právě marné jest v pahrbcích a v množství hor doufání; zajisté v Hospodinu Bohu našem jest spasení Izraelovo.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 24, 'Nebo ohavnost ta zžírala práci otců našich od dětinství našeho, bravy jejich i skoty jejich, syny jejich i dcery jejich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 25, 'Ležíme v hanbě své, a přikrývá nás pohanění naše, že jsme proti Hospodinu Bohu svému hřešili, my i otcové naši, od dětinství svého až do dne tohoto, a neposlouchali jsme hlasu Hospodina Boha svého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 1, 'Budeš-li se míti navrátiti, Izraeli, dí Hospodin, ke mně se navrať. Nebo odejmeš-li ohavnosti své od tváři mé a nebudeš-li se toulati,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 2, 'A budeš-li přisahati právě, náležitě a spravedlivě, říkaje: Živť jest Hospodin, tedy požehnání dávati sobě v něm budou národové, a v něm se chlubiti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 3, 'Nebo takto praví Hospodin mužům Judským a Jeruzalémským: Zořte sobě ouhor, a nerozsívejte do trní.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 4, 'Obřežte se Hospodinu, a odejměte neobřízky srdce vašeho, muži Judští a obyvatelé Jeruzalémští, aby nevyšla jako oheň prchlivost má, a nehořela, tak že by nebyl kdo uhasiti, pro nešlechetnost předsevzetí vašich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 5, 'Oznamte v Judstvu, a v Jeruzalémě ohlaste, a rcete: Trubte trubou v zemi, svolejte a sbeřte lid, a rcete: Shromažďte se, a vejděme do měst hrazených.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 6, 'Vyzdvihněte korouhev na Sionu, zmužile se mějte, nepostávejte; nebo já zlé věci uvedu od půlnoci, a potření veliké.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 7, 'Vychází lev z houště své, a ten, kterýž hubí národy, vyšed z místa svého, táhne, aby obrátil zemi tvou v pustinu, a města tvá aby zbořena byla, tak aby nebylo žádného obyvatele.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 8, 'Protož přepašte se žíněmi, kvělte a naříkejte; nebo není odvrácen hněv prchlivosti Hospodinovy od nás.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 9, 'Stane se zajisté v ten den, dí Hospodin, že zhyne srdce královo a srdce knížat, užasnou se i kněží, a proroci diviti se budou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 10, 'I řekl jsem: Ach, Panovníče Hospodine, jistě že jsi velice podvedl lid tento, i Jeruzalém, říkaje: Pokoj míti budete, a však pronikl meč až k duši.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 11, 'V ten čas řečeno bude lidu tomuto i Jeruzalému: Vítr tuhý z míst vysokých na poušti jde upřímo na lid můj, ne aby převíval, ani přečišťoval.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 12, 'Vítr silnější než oni přijde mi, nyní já také vypovím jim úsudky.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 13, 'Aj, jako oblakové vystupuje, a jako vicher vozové jeho, rychlejší jsou nežli orlice koni jeho. Běda nám, nebo popléněni jsme.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 14, 'Obmej od nešlechetnosti srdce své, Jeruzaléme, abys vysvobozen byl. Dokudž zůstávati budou u prostřed tebe myšlení marnosti tvé?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 15, 'Nebo hlas oznamujícího přichází od Dan, a toho, kterýž ohlašuje nepravost, s hory Efraim.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 16, 'Připomínejte těmto národům, aj, ohlašujte Jeruzalémským, že strážní táhnou z země daleké, a vydávají proti městům Judským hlas svůj.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 17, 'Jako ti, kteříž hlídají polí, položí se proti němu vůkol; nebo jest mi odporný, dí Hospodin.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 18, 'Cesta tvá a skutkové tvoji to způsobili tobě; toť nešlechetnost tvá, žeť to hořké jest, a že dosahá až do srdce tvého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 19, 'Ó, střeva má, střeva má, bolest trpím, ó osrdí mé, kormoutí se ve mně srdce mé, nemohuť mlčeti. Nebo hlas trouby slyšíš, duše má, a prokřikování vojenské.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 20, 'Potření za potřením provolává se, popléněna zajisté bude všecka země, náhle popléněni budou stanové moji, v okamžení kortýny mé.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 21, 'Až dokud vídati budu korouhev, slýchati hlas trouby?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 22, 'Nebo bláznivý lid můj nezná mne, synové nemoudří a nerozumní jsou. Moudří jsou k činění zlého, ale činiti dobře neumějí.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 23, 'Hledím-li na zemi, a aj, nesličná jest a prázdná; pakli na nebe, není na něm žádného světla.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 24, 'Hledím-li na hory, a aj, třesou se, a všickni pahrbkové pohybují se.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 25, 'Hledím-li, a aj, není žádného člověka, a všeliké ptactvo nebeské zaletělo.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 26, 'Hledím-li, a aj, pole úrodné jest pouští, a všecka města jeho zbořena jsou od Hospodina a od hněvu prchlivosti jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 27, 'Nebo takto praví Hospodin: Spustne všecka země, a však konce ještě neučiním.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 28, 'Kvíliti bude nad tím země, a zasmuší se na hoře nebe, proto že jsem mluvil, co jsem myslil, a nelituji, aniž se odvrátím od toho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 29, 'Před hřmotem jezdců a těch, kteříž střílejí z lučiště, uteče všecko město. Vejdou do hustých oblaků, a na skálí vylezou; všecka města opuštěna budou, a žádný nebude bydliti v nich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 30, 'Ty pak pohubena jsuc, což činiti budeš? Ačkoli obláčíš se v šarlat, ačkoli se ozdobuješ ozdobou zlatou, ačkoli líčíš tvář svou líčidlem, darmo se okrašluješ. Pohrdají tebou frejíři, bezživotí tvého hledají.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 31, 'Nebo slyším hlas jako rodičky, svírání jako té, kteráž po nejprvé ku porodu pracuje, hlas dcery Sionské, ustavičně vzdychající, a lomící rukama svýma, říkající: Běda mně nyní, nebo ustala duše má pro vrahy.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 1, 'Zběhejte ulice Jeruzalémské, pohleďte nyní, a zvězte, a hledejte v ulicích jeho, naleznete-li muže, jest-li kdo, ješto by činil soud, a vyhledával toho, což pravého jest, a odpustím jemu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 2, 'Ale i když říkají: Živť jest Hospodin, takovým způsobem křivě přisahají.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 3, 'Ó Hospodine, zdaliž oči tvé nepatří na pravdu? Biješ je, ale necítí bolesti; hubíš je, ale nechtí přijímati kázně. Tvrdší jsou tváře jejich než skála, nechtí se navrátiti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 4, 'I řekl jsem já: Snad tito prostí jsou, nerozumně sobě počínají; nebo nejsou povědomi cesty Hospodinovy, soudu Boha svého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 5, 'Půjdu aspoň k přednějším, a mluviti budu k nim; nebo oni povědomi jsou cesty Hospodinovy, soudu Boha svého. Ale i ti spolu polámali jho, roztrhali svazky.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 6, 'Protož je podáví lev z lesa, vlk večerní pohubí je, pardus číhati bude u měst jejich. Kdožkoli vyjde z nich, roztrhán bude; nebo mnohá jsou přestoupení jejich, rozmohly se převrácenosti jejich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 7, 'Kdež jest to, pročež bych měl odpustiti tobě? Synové tvoji opouštějí mne, a přisahají skrze ty, kteříž nejsou bohové. Jakž jsem jen nasytil je, hned cizoloží, a do domu nevěstky houfem se valí.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 8, 'Ráno vstávajíce, jsou jako koni vytylí; každý k ženě bližního svého řehce.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 9, 'Zdaliž pro takové věci nemám navštíviti? dí Hospodin. A zdali nad národem takovým nemá mstíti duše má?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 10, 'Vstupte na zdi jeho, a zkazte je, a nepřestávejte; svrzte štítky zdí jeho, nebo nejsou Hospodinovy.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 11, 'Velice zajisté zpronevěřili se mi dům Izraelský a dům Judský, dí Hospodin.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 12, 'Sčítali klam na Hospodina, a říkali: Není tak, nikoli nepřijde na nás zlé, a meče ani hladu nepocítíme.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 13, 'Ti pak proroci pominou s větrem, a žádného slova není v nich. Takť se stane jim.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 14, 'Protož takto praví Hospodin Bůh zástupů: Proto že tak mluvíte, aj, já způsobím, aby slova tvá v ústech tvých byla jako oheň, a lid tento dřívím, kteréž on zžíře.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 15, 'Aj, já přivedu na vás národ zdaleka, ó dome Izraelský, dí Hospodin, národ silný, národ starodávní, národ, jehož jazyka nebudeš uměti, ani rozuměti, co mluví.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 16, 'Jehož toul jako hrob otevřený, všickni jsou silní.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 17, 'A vytráví obilé tvé a chléb tvůj, požerou syny tvé a dcery tvé, pojí bravy tvé i skot tvůj, pojí vinné kmeny tvé i fíkoví tvé, města tvá hrazená, v nichž ty doufáš, znuzí mečem.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 18, 'A však ani těch časů, dí Hospodin, neučiním s vámi konce.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 19, 'Nebo stane se, když řeknete: Proč nám činí Hospodin Bůh náš všecko toto? že řekneš jim: Jakož jste opustili mne, a sloužili bohům cizozemců v zemi své, tak sloužiti budete cizozemcům v zemi ne své.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 20, 'Oznamtež to v domě Jákobově, a rozhlaste v Judstvu, řkouce:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 21, 'Slyštež nyní toto, lide bláznivý a nesmyslný, kteříž oči mají a nevidí, kteříž uši mají a neslyší:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 22, 'Což se mne nebudete báti? dí Hospodin. Což před oblíčejem mým nebudete se třásti? Kterýž jsem položil písek za cíl moři ustanovením věčným, jehož nepřekračuje. Ačkoli zmítají se, však neodolají, ačkoli zvučí vlnobití jeho, však ho nepřecházejí.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 23, 'Ale lid tento má srdce zarputilé a zpurné, odstoupili a odešli.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 24, 'Ani neřekli v srdci svém: Bojme se již Hospodina Boha našeho, kterýž dává déšť jarní i podzimní časem svým, téhodnů nařízených ke žni ostříhá nám.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 25, 'Nepravostiť vaše překážku činí těm věcem, a hříchové vaši připravují vás o to dobré.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 26, 'Nebo nalézají se v lidu mém bezbožníci; střeže jako čižebníci, kteříž lécejí, stavějí osídla, lidi lapají.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 27, 'Jako klece plná ptáků, tak domové jejich plní jsou lsti. Protož zrostli a zbohatli,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 28, 'Vytylí jsou, lsknou se, nadto umějí se vyhýbati bídám. Pře nesoudí, ani pře sirotka, a však šťastně se jim vede, ačkoli k spravedlnosti chudým nedopomáhají.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 29, 'Zdaliž pro takové věci nemám navštíviti jich? dí Hospodin. Zdali nad národem takovým nemá mstíti duše má?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 30, 'Věc užasnutí hodná a hrozná děje se v zemi této.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 31, 'Proroci prorokují lživě, a kněží panují skrze ně, a lid můj miluje to. Čeho byste pak neučinili naposledy?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 1, 'Shromažďte se, synové Beniaminovi, z prostředku Jeruzaléma, a v Tekoa trubte trubou, a nad Betkarem vyzdvihněte korouhev; nebo viděti zlé od půlnoci, a potření veliké.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 2, 'Panně krásné a rozkošné připodobnil jsem byl dceru Sionskou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 3, 'Ale přitáhnou k ní pastýři s stády svými, rozbijí proti ní stany vůkol, spase každý místo své.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 4, 'Vyzdvihněte proti ní válku, vstaňte a přitrhněme o poledni. Běda nám, že pomíjí den, že se roztáhli stínové večerní.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 5, 'Vstaňte a přitrhněme v noci, a zkazme paláce její.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 6, 'Takto zajisté praví Hospodin zástupů: Nasekejte dříví, a zdělejte proti Jeruzalému náspy. Toť jest to město, kteréž navštíveno býti musí; což ho koli, jen nátisk jest u prostřed něho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 7, 'Jakož studnice vypryšťuje vodu svou, tak ono vypryšťuje zlost svou. Nátisk a zhoubu slyšeti v něm před oblíčejem mým ustavičně, bolest i bití.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 8, 'Usmysl sobě, ó Jeruzaléme, aby se neodloučila duše má od tebe, abych tě neobrátil v pustinu, v zemi nebydlitelnou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 9, 'Takto praví Hospodin zástupů: Jistě paběrovati budou jako vinný kmen ostatek Izraele, říkajíce: Sahej rukou svou jako ten, kterýž víno zbírá do putny.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 10, 'Komuž mluviti budu, a kým osvědčovati, aby slyšeli? Aj, neobřezané jsou uši jejich, tak že nemohou pozorovati; aj, slovo Hospodinovo mají v posměchu, a nemají líbosti v něm.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 11, 'Protož plný jsem prchlivosti Hospodinovy, ustal jsem, drže ji v sobě. Vylita bude i na maličké vně, spolu i na shromáždění mládenců, ovšem pak muž s ženou jat bude, stařec s kmetem.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 12, 'A dostanou se domové jejich jiným, též pole i ženy, když vztáhnu ruku svou na obyvatele této země, dí Hospodin.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 13, 'Od nejmenšího zajisté z nich, až do největšího z nich, všickni napořád vydali se v lakomství, anobrž od proroka až do kněze všickni napořád provodí faleš.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 14, 'A hojí potření dcery lidu mého povrchu, říkajíce: Pokoj, pokoj, ješto není žádného pokoje.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 15, 'Styděli-liž se pak co proto, že ohavnost páchali? Aniž se lid co styděl, aniž jich proroci k zahanbení přivesti uměli. Protož padnou mezi padajícími; v čas, v němž je navštívím, klesnou, praví Hospodin.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 16, 'Když takto říkával Hospodin: Zastavte se na cestách, a pohleďte, a vyptejte se na stezky staré, která jest cesta dobrá, i choďte po ní, a naleznete odpočinutí duši své, tedy říkávali: Nebudeme choditi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 17, 'Když jsem pak ustanovil nad vámi strážné, řka: Mějtež pozor na zvuk trouby, tedy říkávali: Nebudeme pozorovati.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 18, 'Protož slyšte, ó národové, a poznej, ó shromáždění, co se děje mezi nimi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 19, 'Slyš, ó země: Aj, já uvedu zlé na lid tento, ovoce myšlení jejich, proto že nepozorují slov mých, ani zákona mého, ale jím pohrdají.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 20, 'K čemuž mi kadidlo z Sáby přichází, a vonná třtina výborná z země daleké? Zápalů vašich nelibuji sobě, aniž oběti vaše jsou mi příjemné.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 21, 'Protož takto praví Hospodin: Aj, já nakladu lidu tomuto úrazů, a zurážejí se o ně otcové, tolikéž i synové, soused i bližní jeho, a zahynou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 22, 'Takto praví Hospodin: Aj, lid přitáhne z země půlnoční, a národ veliký povstane od končin země.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 23, 'Lučiště i kopí pochytí, každý ukrutný bude, a neslitují se. Hlas jejich jako moře zvučeti bude, a na koních jezditi budou, zšikovaní jako muž k boji, proti tobě, ó dcero Sionská.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 24, 'Jakž uslyšíme pověst o něm, opadnou ruce naše; ssoužení zachvátí nás, a bolest jako rodičku.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 25, 'Nevycházejte na pole, a na cestu nechoďte; nebo meč nepřítele a strach jest vůkol.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 26, 'Ó dcero lidu mého, přepaš se žíní, a válej se v popele. Vydej se v kvílení, jako po synu jednorozeném, v kvílení přehořké; nebo náhle přitáhne zhoubce na nás.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 27, 'Dal jsem tě za věži v lidu tvém, a za baštu, abys spatřoval a zkušoval cesty jejich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 28, 'Všickni jsou z zarputilých nejzarputilejší, chodí jako utrhač, jsou ocel a železo, všickni napořád zhoubcové jsou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 29, 'Prahnou měchy, od ohně mizí olovo, nadarmo ustavičně přepaluje zlatník; nebo zlé věci nemohou býti odděleny.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 30, 'Stříbrem falešným nazovou je, nebo Hospodin zavrhl je.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 1, 'Slovo, kteréž se stalo k Jeremiášovi od Hospodina, řkoucí:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 2, 'Postav se v braně domu Hospodinova, a ohlašuj tam slovo toto, a rci: Slyšte slovo Hospodinovo všickni Judští, kteříž vcházíte do bran těchto, abyste se klaněli Hospodinu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 3, 'Takto praví Hospodin zástupů, Bůh Izraelský: Polepšte cest svých i předsevzetí svých, a způsobím to, abyste bydlili na místě tomto.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 4, 'Neskládejte naděje své v slovích lživých, říkajíce: Chrám Hospodinův, chrám Hospodinův, chrám Hospodinův jest.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 5, 'Ale jestliže všelijak polepšíte cest svých, a předsevzetí svých, jestliže spravedlivě soud konati budete mezi mužem a mezi bližním jeho;');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 6, 'Příchozího, sirotka a vdovy neutisknete, a krve nevinné nevylejete na místě tomto, a za bohy cizími nebudete-li choditi k svému zlému:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 7, 'Tedy způsobím, abyste bydlili na místě tomto, v zemi, kterouž jsem dal otcům vašim, od věků až na věky.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 8, 'Aj, vy skládáte naději svou v slovích lživých, kteráž neprospívají.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 9, 'Zdaliž kradouce, mordujíce a cizoložíce i křivě přisahajíce a kadíce Bálovi; též chodíce za bohy cizími, jichž neznáte,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 10, 'Předce choditi a postavovati se budete před oblíčejem mým v domě tomto, kterýž nazván jest od jména mého, a říkati: Vyproštěni jsme, abyste páchali ty všecky ohavnosti?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 11, 'Což peleší lotrovskou jest dům tento před očima vašima, kterýž nazván jest od jména mého? Aj, takéť já vidím, dí Hospodin.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 12, 'Ale jděte aspoň na místo mé, kteréž bylo v Sílo, kdež jsem byl způsobil příbytek jménu svému z počátku, a vizte, co jsem učinil jemu pro nešlechetnost lidu svého Izraelského.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 13, 'Protož nyní, že činíte všecky skutky tyto, dí Hospodin, a když mluvím k vám, ráno vstávaje, a to ustavičně, tedy neposloucháte, a když volám na vás, tedy neozýváte se:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 14, 'Protož učiním domu tomuto, kterýž nazván jest od jména mého, v němž vy doufáte, i místu tomuto, kteréž jsem dal vám a otcům vašim, jako jsem učinil Sílo;');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 15, 'A zavrhu vás od tváři své, jako jsem zavrhl bratří vaše, všecko símě Efraimovo.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 16, 'Ty tedy nemodl se za lid tento, aniž pozdvihuj za ně hlasu a modlitby, aniž se přimlouvej ke mně; nebo tě nikoli nevyslyším.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 17, 'Zdaliž sám nevidíš, co oni činí v městech Judských a po ulicích Jeruzalémských?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 18, 'Synové zbírají dříví, a otcové zaněcují oheň, ženy pak zadělávají těsto, aby pekly koláče tvoru nebeskému, a obětovali oběti mokré bohům cizím, aby mne popouzeli.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 19, 'Zdaliž to proti mně jest, že mne oni popouzejí? dí Hospodin. Zdali není proti nim k zahanbení tváři jejich?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 20, 'Pročež takto praví Panovník Hospodin: Aj, hněv můj a prchlivost má vylita bude na místo toto, na lidi i na hovada, i na dříví polní, i na úrody země, a hořeti bude, tak že neuhasne.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 21, 'Takto praví Hospodin zástupů, Bůh Izraelský: Zápaly své přidejte k obětem svým, a jezte maso.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 22, 'Nebo jsem nemluvil s otci vašimi, aniž jsem přikázal jim v ten den, v kterýž jsem je vyvedl z země Egyptské, o zápalích a obětech.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 23, 'Ale toto přikázal jsem jim, řka: Poslouchejte hlasu mého, a budu vaším Bohem, a vy budete mým lidem, a choďte po vší cestě, kterouž jsem vám přikázal, aby vám dobře bylo.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 24, 'Však neposlechli, aniž naklonili ucha svého, ale chodili po radách, a podlé zdání srdce svého zlého. Obrátili se ke mně hřbetem a ne tváří svou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 25, 'Od toho času, jakž vyšli otcové vaši z země Egyptské, až do tohoto dne posílal jsem k vám všecky služebníky své proroky, každý den ráno vstávaje, a to ustavičně.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 26, 'Však neposlechli mne, aniž naklonili ucha svého, ale zatvrdivše šíji svou, hůře činili nežli otcové jejich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 27, 'Když jim mluvíš všecka slova tato, ani tebe neposlouchají, a když voláš na ně, neohlašují se tobě.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 28, 'Protož rciž jim: Tento jest národ, kteříž neposlouchají hlasu Hospodina Boha svého, aniž přijímají naučení. Zhynula pravda, a vymizela z úst jejich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 29, 'Ohol vlasy své a zavrz, a naříkej hlasem na místech vysokých; nebo zavrhl Hospodin a opustil rodinu, na kterouž se velmi hněvá.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 30, 'Činili zajisté synové Judovi, což zlého jest před očima mýma, dí Hospodin. Nastavěli ohavností svých v domě tom, kterýž nazván jest od jména mého, aby poškvrnili jej.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 31, 'Nadto vzdělali výsosti Tofet, kteréž jest v údolí syna Hinnom, aby pálili syny své i dcery své ohněm, čehož jsem nepřikázal, aniž vstoupilo na srdce mé.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 32, 'Protož aj, dnové jdou, dí Hospodin, kdyžto nebude slouti více Tofet, ani údolí syna Hinnom, ale údolí mordu, a pochovávati budou v Tofet, nebo nebude dostávati místa.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 33, 'I budou mrtvá těla lidu tohoto za pokrm ptactvu nebeskému a šelmám zemským, a nebude žádného, kdo by odstrašil.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 34, 'Způsobím také, aby přestal v městech Judských a v ulicích Jeruzalémských hlas radosti a hlas veselé, hlas ženicha a hlas nevěsty; nebo pustinou učiněna bude země.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 1, 'V ten čas, dí Hospodin, vyberou kosti králů Judských, i kosti knížat jejich, i kosti kněží, i kosti proroků, ano i kosti obyvatelů Jeruzalémských z hrobů jejich,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 2, 'A rozmecí je proti slunci a měsíci, i proti všemu vojsku nebeskému, kteréž milují, a kterýmž slouží, a za kterýmiž chodí, a kterýchž hledají, a kterýmž se klanějí. Nebudou sebrány, ani pochovány, budou místo hnoje na svrchku země.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 3, 'I bude žádostivější smrt nežli život všechněm ostatkům těm, kteříž pozůstanou z rodiny této nešlechetné na všech místech, kdež by koli pozůstali, tam kamž je zaženu, dí Hospodin zástupů.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 4, 'Protož díš jim: Takto praví Hospodin: Tak-liž padli, aby nemohli povstati? Tak-liž se odvrátil, aby se nemohl zase navrátiti?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 5, 'Proč se odvrátil lid tento Jeruzalémský odvrácením věčným? Chytají se lsti, a nechtí se navrátiti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 6, 'Pozoroval jsem a poslouchal. Nemluví, což pravého jest; není, kdo by želel zlosti své, říkaje: Což jsem učinil? Každý obrácen jest k běhu svému jako kůň, kterýž prudce běží k boji.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 7, 'Ješto čáp u povětří zná nařízené časy své, a hrdlička i řeřáb i vlaštovice šetří času příletu svého, lid pak můj nezná soudu Hospodinova.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 8, 'Jakž můžete říci: Moudří jsme a zákon Hospodinův máme? Aj, jistě nadarmo dělá písař péro, nadarmo jsou v zákoně zběhlí.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 9, 'Kohož zahanbili ti moudří? Kdo jsou předěšeni a jati? Aj, slovem Hospodinovým pohrdají, jakáž tedy jest moudrost jejich?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 10, 'A protož dám ženy jejich jiným, pole jejich těm, kteříž by je opanovali; nebo od nejmenšího až do největšího všickni napořád vydali se v lakomství, od proroka až do kněze všickni napořád provodí faleš.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 11, 'Nebo hojí potření dcery lidu mého po vrchu, říkajíce: Pokoj, pokoj, ješto není žádného pokoje.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 12, 'Jsou-liž zahanbováni, proto že ohavnost páchali? Ba ani se co ustydli, ani zahanbiti uměli. Protož padnou, když oni padati budou; v čas, v němž je navštívím, klesnou, praví Hospodin.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 13, 'Do konce vykořením je, dí Hospodin. Nebude žádného hroznu na vinném kmenu, ani žádných fíků na fíku, ano i list sprchne, a což dám jim, odjato bude.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 14, 'Proč my tu sedíme? Shromažďte se, a vejděme do měst hrazených, a odpočineme tam. Ale Hospodin Bůh náš káže odpočívati nám, když vodou jedovatou napojí nás, proto že jsme hřešili proti Hospodinu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 15, 'Čekej pokoje, ale nic dobrého, času uzdravení, ale aj, hrůza.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 16, 'Od Dan slyšeti frkání koní jeho, od hlasu prokřikování silných jeho všecka země se třese, kteříž táhnou, aby zžírali zemi i všecko, což jest na ní, město i ty, kteříž bydlejí v něm.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 17, 'Nebo aj, já pošli na vás hady nejjedovatější, proti nimž nic neprospívá zaklínání, a štípati vás budou, dí Hospodin.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 18, 'Srdce mé ve mně, kteréž by mne mělo občerstvovati v zármutku, mdlé jest.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 19, 'Aj, hlas křiku dcery lidu mého z země velmi daleké: Zdali Hospodina není na Sionu? Zdali krále jeho není na něm? Proč mne popouzeli rytinami svými, marnostmi cizozemců?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 20, 'Pominula žeň, dokonalo se léto, a my nejsme vyproštěni.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 21, 'Pro potření dcery lidu mého potřín jsem, smutek nesu, užasnutí podjalo mne.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 22, 'Což není žádného lékařství v Galád? Což není žádného lékaře tam? Proč tedy není zhojena dcera lidu mého?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 1, 'Ó kdo mi to dá, aby hlava má byla vodou, a oči mé pramenem slzí, abych dnem i nocí oplakati mohl zmordovaných dcerky lidu svého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 2, 'Ó kdo mne postaví na poušti v hospodě pocestných, abych opustil lid svůj, a odešel od nich; nebo všickni jsou cizoložníci, zběř zpronevěřilých,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 3, 'A natahují jazyka svého ke lži jako lučiště své. Zmocnili se na zemi, ale ne k pravdě; nebo ze zlého ve zlé jdou, a mne neznají, praví Hospodin.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 4, 'Každý střez se bližního svého, a nekaždému bratru se dověřuj; nebo každý bratr hledí všelijak podtrhnouti, a každý bližní jako utrhač chodí.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 5, 'A jeden každý bližního svého oklamává, a pravdy nemluví; učí jazyk svůj mluviti lež, neprávě činíce, ustávají.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 6, 'Tvůj byt jest u prostřed lidu přelstivého; pro lest nechtějí mne poznati, dí Hospodin.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 7, 'Z té příčiny takto praví Hospodin zástupů: Aj, já přeháněje, pruboval jsem je. Jakž tedy již naložiti mám s dcerou lidu svého?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 8, 'Střela zabíjející jest jazyk jejich, lest mluví. Ústy svými pokojně s bližním svým mluví, ale v srdci svém skládá úklady své.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 9, 'Zdali pro takové věci nemám jich navštíviti? dí Hospodin. Zdaliž nad národem takovým nemá mstíti duše má?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 10, 'Pro tyto hory dám se v pláč a v naříkání, a pro pastviště, kteráž jsou na poušti, v kvílení; nebo popálena budou, tak že nebude žádného, kdo by skrze ně šel, aniž bude slyšán hlas dobytka. Od ptactva nebeského až do hovada všecko se odbéře a odejde.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 11, 'A obrátím Jeruzalém v hromady, příbytek draků, a města Judská obrátím v pustinu, tak že nebude obyvatele.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 12, 'Kdo jest ten muž moudrý, ješto by rozuměl tomu? A k komu mluvila ústa Hospodinova, ješto by oznamoval to, proč zahynouti má tato země, a vypálena býti jako poušť, tak aby nebylo, kdo by skrze ni šel?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 13, 'Nebo praví Hospodin: Proto že opustili zákon můj, kterýž jsem jim předložil, a neposlouchali hlasu mého, aniž chodili za ním,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 14, 'Ale chodili za myšlénkami srdce svého a za Báli, čemuž je naučili otcové jejich:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 15, 'Protož takto praví Hospodin zástupů, Bůh Izraelský: Aj, já nakrmím je, totiž lid tento, pelynkem, a napojím je vodou jedovatou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 16, 'Nebo rozptýlím je mezi národy, kterýchž neznali oni, ani otcové jejich, a posílati budu za nimi meč, až je do konce vyhladím.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 17, 'Takto praví Hospodin zástupů: Pilně považte, a svolejte ty, kteréž naříkávají, ať přijdou, a k těm, kteréž jsou vycvičené, pošlete, aby přišly.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 18, 'Nechť pospíší, a dadí se nad námi v naříkání, aby slzy tekly z očí našich, a víčka naše oplývala vodou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 19, 'Hlas zajisté naříkání slyšeti z Siona: Jak jsme pohubeni! Stydíme se náramně, že jsme ztratili zemi, že boří příbytky naše.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 20, 'Anobrž slyšte, ženy, slovo Hospodinovo, a nechť přijme ucho vaše slovo úst jeho, abyste učily dcerky své naříkání, a jedna každá tovaryšku svou kvílení.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 21, 'Nebo vlezla smrt okny našimi, vešla na paláce naše, aby vyhubila děti z rynků a mládence z ulic.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 22, '(Mluv i to: Takto dí Hospodin:) A padla mrtvá těla lidská jako hnůj po poli, a jako snopové za žencem, a není žádného, kdo by pochoval.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 23, 'Takto praví Hospodin: Nechlub se moudrý v moudrosti své, ani se chlub silný v síle své, aniž se chlub bohatý v bohatství svém.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 24, 'Ale v tom nechť se chlubí, kdo se chlubí, že rozumí a zná mne, že já jsem Hospodin, kterýž činím milosrdenství, soud i spravedlnost na zemi; nebo v těch věcech líbost mám, dí Hospodin.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 25, 'Aj, dnové jdou, praví Hospodin, v nichž navštívím každého, obřezaného i neobřezaného,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 26, 'Egyptské i Judské, a Idumejské i Ammonitské, a Moábské, i všecky, kteříž v nejzadnějším koutě bydlí na poušti. Nebo ti všickni národové jsou neobřezaní, tolikéž všecken dům Izraelský jest neobřezaného srdce.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 1, 'Slyšte slovo toto, kteréž mluví k vám Hospodin, ó dome Izraelský.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 2, 'Takto praví Hospodin: Cestě pohanů neučte se, aniž se znamení nebeských děste, neboť se jich děsí pohané.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 3, 'Ustanovení zajisté těch národů jsou pouhá marnost. Nebo setna dřevo sekerou v lese, dílo rukou řemeslníka,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 4, 'Stříbrem a zlatem ozdobí je, hřebíky a kladivy utvrzují je, aby se neviklalo.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 5, 'Jsou jako palmový špalek tvrdý, ani nemluví; nošeni býti musejí, nebo choditi nemohou. Nebojtež se jich, nebo zle učiniti nemohou, aniž také dobře učiniti mohou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 6, 'Z nichž není žádného tobě podobného, ó Hospodine; veliký jsi, i jméno tvé veliké jest v moci.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 7, 'Kdož by se nebál tebe, králi národů? Na tebeť zajisté to sluší, poněvadž mezi všemi mudrci národů, i ve všem království jejich nikdá nebylo podobného tobě.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 8, 'A však ze spolka zhlupěli, a blázni jsou; z dřeva učiti se jest pouhá marnost.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 9, 'Stříbro tažené z zámoří přivážíno bývá, a zlato z Ufaz, dílo řemeslníka a rukou zlatníka; z postavce modrého a šarlatový jest oděv jejich, všecko to jest dílo umělých.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 10, 'Ale Hospodin jest Bůh pravý, jest Bůh živý a král věčný, před jehož prchlivostí země se třese, aniž mohou snésti národové rozhněvání jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 11, '(Takto říkejte jim: Bohové ti, kteříž nebe ani země neučinili, nechť zahynou z země, a nechť jich není pod nebem.)');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 12, 'Kterýž učinil zemi mocí svou, kterýž utvrdil okršlek světa moudrostí svou, a opatrností svou roztáhl nebesa.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 13, 'Kterýžto když vydává hlas, ječení vod bývá na nebi, a kterýž působí to, aby vystupovaly páry od kraje země, blýskání s deštěm přivodí, a vyvodí vítr z pokladů svých.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 14, 'Tak zhlupěl každý člověk, že nezná toho, že zahanben bývá každý zlatník pro rytinu; nebo slitina jeho jest faleš, a není ducha v nich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 15, 'Marnost jsou a dílo podvodů; v čas, v němž je navštívím, zahynou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 16, 'Neníť podobný těmto díl Jákobův, nebo on jest stvořitel všeho; Izrael tolikéž jest pokolení dědictví toho, jehož jméno jest Hospodin zástupů.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 17, 'Sbeř z země koupi svou, ty kteráž bydlíš v pevnosti této.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 18, 'Nebo takto praví Hospodin: Aj, já vyhodím z praku obyvatele země této pojednou, a ssoužím je, aby shledali toto:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 19, 'Běda mně pro setření mé, přebolestná jest rána má, ješto jsem já byl řekl: Jistě tuto nemoc budu moci snésti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 20, 'Stan můj popléněn jest, a všickni provazové moji potrháni jsou. Synové moji odebrali se ode mne, a není žádného; není žádného, kdo by více rozbíjel stan můj, a roztáhl kortýny mé.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 21, 'Nebo zhlupěli pastýři, a Hospodina se nedotazovali; protož nevede se jim šťastně, a všecko stádo pastvy jejich rozptýleno jest.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 22, 'Aj, pověst jistá přichází, a pohnutí veliké z země půlnoční, aby obrácena byla města Judská v pustinu a v příbytek draků.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 23, 'Vím, Hospodine, že není v moci člověka cesta jeho, aniž jest v moci muže toho, kterýž chodí, aby spravoval krok svůj.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 24, 'Kárej mne, Hospodine, však milostivě, ne v hněvě svém, abys nesetřel mne.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 25, 'Vylí hněv svůj na ty národy, kteříž tebe neznají, a na rodiny, kteréž jména tvého nevzývají; nebo zžírají Jákoba, a tak zžírají jej, aby jej všeho sežrali, a obydlí jeho v poustku obrátili.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 1, 'Slovo, kteréž se stalo k Jeremiášovi od Hospodina, řkoucí:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 2, 'Slyšte slova smlouvy této, kteráž byste mluvili mužům Judským, a obyvatelům Jeruzalémským,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 3, 'A rci jim: Takto praví Hospodin Bůh Izraelský: Zlořečený ten člověk, kterýž by neposlechl slov smlouvy této,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 4, 'Kterouž jsem vydal otcům vašim tehdáž, když jsem je vyvedl z země Egyptské, z peci železné, řka: Poslouchejte hlasu mého, a čiňte to všecko, tak jakž přikazuji vám, i budete lidem mým, a já budu Bohem vaším,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 5, 'Abych splnil přísahu, kterouž jsem učinil otcům vašim, že jim dám zemi oplývající mlékem a strdí, jakž dnešní den jest. Jemuž odpověděv, řekl jsem: Amen, Hospodine.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 6, 'Potom řekl mi Hospodin: Ohlašuj všecka slova tato po městech Judských, a po ulicích Jeruzalémských, řka: Slyšte slova smlouvy této, a čiňte je.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 7, 'Nebo častokrát osvědčoval jsem se otcům vašim, od toho dne, jakž jsem je vyvedl z země Egyptské, až do dne tohoto; ráno přivstávaje a osvědčuje se, říkával jsem: Poslouchejte hlasu mého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 8, 'Ale neposlouchali, aniž naklonili ucha svého, nýbrž chodil jeden každý po zdání srdce svého zlého. Pročež uvedl jsem na ně všecka slova smlouvy této, kterouž jsem přikázal plniti, ale neplnili.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 9, 'Tehdy řekl mi Hospodin: Nalézá se spiknutí mezi muži Judskými, a mezi obyvateli Jeruzalémskými.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 10, 'Obrátili se k nepravostem otců svých starých, kteříž nechtěli poslouchati slov mých. Tolikéž tito chodí za bohy cizími, sloužíce jim; dům Izraelský a dům Judský zrušili smlouvu mou, kterouž jsem učinil s otci jejich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 11, 'Protož takto praví Hospodin: Aj, já uvedu na ně zlé, z něhož nebudou moci vyjíti. By pak volali ke mně, nevyslyším jich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 12, 'I půjdou města Judská i obyvatelé Jeruzalémští, a budou volati k bohům těm, kterýmž kadí, ale nikoli nevysvobodí jich v čas bídy jejich,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 13, 'Ačkoli podlé počtu měst máš bohy své, ó Judo, a podlé počtu ulic Jeruzalémských nastavěli jste oltářů ohavnosti té, oltářů, na nichž byste kadili Bálovi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 14, 'Protož ty nemodl se za lid tento, aniž pozdvihuj za ně hlasu a modlitby; neboť nikoli nevyslyším jich v ten čas, když by volali ke mně příčinou svého zlého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 15, 'Co jest milému mému do mého domu, poněvadž nestydatě páše nešlechetnosti s mnohými, a oběti svaté odešly od tebe, a že v zlosti své pléšeš?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 16, 'Byltě Hospodin nazval jméno tvé olivou zelenající se, pěknou pro ovoce ušlechtilé, ale s zvukem bouře veliké zapálí ji s hůry, když polámí ratolesti její.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 17, 'Nebo Hospodin zástupů, kterýž tě byl štípil, vyřkl zlé proti tobě, pro nešlechetnost domu Izraelského a domu Judského, kterouž mezi sebou páchali, aby mne popouzeli, kadíce Bálovi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 18, 'Hospodin zajisté oznámil mi, i dověděl jsem se. Tehdáž jsi mi ukázal předsevzetí jejich,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 19, 'Když jsem já byl jako beránek a volček, kterýž veden bývá k zabití. Nebo nevěděl jsem, by proti mně rady skládali: Zkazme strom s ovocem jeho, a vyhlaďme jej z země živých, aby jméno jeho nebylo připomínáno více.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 20, 'Ale ó Hospodine zástupů, soudce spravedlivý, kterýž zkušuješ ledví i srdce, nechť se podívám na pomstu tvou nad nimi; nebo jsem tobě zjevil při svou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 21, 'Protož takto praví Hospodin o Anatotských, kteříž hledají bezživotí tvého, říkajíce: Neprorokuj ve jménu Hospodinovu, abys neumřel v ruce naší:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 22, 'Protož takto praví Hospodin zástupů: Aj, já navštívím je. Mládenci zbiti budou mečem, synové jejich i dcery jejich zemrou hladem,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 23, 'A nebudou míti potomků, když uvedu zlé na Anatotské, času toho, v němž je navštívím.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 1, 'Spravedlivý zůstaneš, Hospodine, povedu-li odpor proti tobě, a však o soudech tvých mluviti budu s tebou. Proč se cestě bezbožníků šťastně vede? Mají pokoj všickni, kteříž se pyšně zpronevěřili.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 2, 'Štěpuješ je, ano i vkořeňují se; rostou, ano i ovoce nesou ti, jejichžto úst blízko jsi, ale daleko od ledví jejich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 3, 'Ale ty, Hospodine, znáš mne, prohlédáš mne, a zkusils srdce mého, že s tebou jest, onyno pak táhneš jako ovce k zabíjení, a připravuješ je ke dni zabití.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 4, 'Dokudž by žalostila země, a bylina všeho pole svadla pro zlost přebývajících v ní, a hynulo každé hovado i ptactvo? Nebo říkají: Nevidíť Bůh skončení našeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 5, 'Poněvadž tebe s pěšími běžícího k ustání přivodí, kterakž bys tedy stačil při koních? A poněvadž v zemi pokojné, jíž jsi se dověřil, ustáváš, což pak spravíš při tom zdutém Jordánu?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 6, 'Nebo i bratří tvoji i dům otce tvého zpronevěřili se tobě, a ti také povolávají za tebou plnými ústy. Nevěř jim, byť pak mluvili s tebou přátelsky.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 7, 'Opustil jsem dům svůj, zavrhl jsem dědictví své, dal jsem to, což velice milovala duše má, v ruce nepřátel jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 8, 'Učiněno jest mi dědictví mé podobné lvu v lese, vydává proti mně hlas svůj, pročež ho nenávidím.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 9, 'A což ptákem dravým jest mi dědictví mé? Což ptactvo vůkol bude proti němu? Jdětež nu, shromažďte se všecka zvířata polní, sejděte se k jídlu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 10, 'Mnozí pastýři zkazí vinici mou, pošlapají podíl můj, podíl mně velmi milý obrátí v poušť nejhroznější,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 11, 'Obrátí jej v pustinu. Kvíliti bude, spuštěn jsa ode mne; spustne všecka tato země, nebo není žádného, kdo by to v srdci skládal.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 12, 'Na všecka místa vysoká po poušti potáhnou zhoubcové, meč zajisté Hospodinův zžíře od jednoho kraje země až do druhého, nebude míti pokoje žádné tělo.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 13, 'Nasejí pšenice, ale trní žíti budou; bolestně to ponesou, že užitku nevezmou, a styděti se budou za úrody své pro prchlivost hněvu Hospodinova.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 14, 'Takto praví Hospodin o všech mých sousedech zlých, jenž se dotýkají dědictví, kteréž jsem uvedl v dědictví lidu svému Izraelskému: Aj, já vypléním je z země jejich, když dům Judský vypléním z prostředku jejich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 15, 'Stane se však, když je vypléním, že se navrátím a smiluji se nad nimi, a přivedu zase jednoho každého z nich k dědictví jeho, a jednoho každého do země jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 16, 'Stane se také, jestliže by se pilně učili cestám lidu mého, a přisahali by ve jménu mém, říkajíce: Živť jest Hospodin, jakž oni učívali lid můj přisahati skrze Bále, že vzděláni budou u prostřed lidu mého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 17, 'Jestliže by pak neposlouchali, tedy pléniti budu národ ten ustavičně a hubiti, dí Hospodin.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 1, 'Takto řekl Hospodin ke mně: Jdi a zjednej sobě pás lněný, a opaš jím bedra svá, do vody pak nedávej ho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 2, 'Tedy zjednal jsem ten pás podlé slova Hospodinova, a opásal jsem bedra svá.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 3, 'Potom stalo se slovo Hospodinovo ke mně podruhé, řkoucí:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 4, 'Vezmi ten pás, kterýž jsi zjednal, kterýž jest na bedrách tvých, a vstana, jdi k Eufrates, a skrej jej tam do díry skalní.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 5, 'I šel jsem, a skryl jsem jej u Eufrates, jakž mi byl přikázal Hospodin.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 6, 'Stalo se pak po přeběhnutí dnů mnohých, že řekl Hospodin ke mně: Vstana, jdi k Eufrates, a vezmi odtud ten pás, kterýžť jsem přikázal skrýti tam.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 7, 'I šel jsem k Eufrates, a vykopav, vzal jsem ten pás z místa toho, kdež jsem jej byl skryl. A aj, zkažený byl ten pás, aniž se k čemu hodil.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 8, 'Tehdy stalo se slovo Hospodinovo ke mně, řkoucí:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 9, 'Takto praví Hospodin: Takť zkazím pýchu Judských i pýchu Jeruzalémských velikou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 10, 'Lidu toho přenešlechetného, kteříž nechtí poslouchati slov mých, kteříž chodí podlé zdání srdce svého, a chodí za bohy cizími, sloužíce jim, a klanějíce se jim. I bude podoben pasu tomu, kterýž se nehodí k ničemu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 11, 'Nebo jakož se drží pás na bedrách muže, tak jsem byl připojil k sobě všecken dům Izraelský i všecken dům Judský, dí Hospodin, aby byli lidem mým, a to k slávě, a k chvále, i k ozdobě, ale nebyli poslušni.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 12, 'Protož rci jim slovo toto: Takto praví Hospodin Bůh Izraelský: Všeliká nádoba vinná naplňována bývá vínem. Kdyžť pak řeknou: Zdaliž nevíme dobře, že všeliká nádoba vinná naplňována bývá vínem?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 13, 'I díš jim: Takto praví Hospodin: Aj, já naplním všecky obyvatele země této i krále, kteříž sedí místo Davida na stolici jeho, i kněží i proroky, a tolikéž všecky obyvatele Jeruzalémské opilstvím,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 14, 'A rozrazím jednoho o druhého, jakož otce, tak také syny, dí Hospodin. Nebudu šanovati, aniž odpustím, aniž se smiluji, abych zkaziti jich neměl.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 15, 'Poslouchejte a ušima pozorujte, nepovyšujte se, neboť Hospodin mluví.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 16, 'Dejte Hospodinu Bohu svému čest, dřív než by tmu uvedl, a dříve nežli by se zurážely nohy vaše o hory tmavé. I čekali byste světla, ale obrátil by je v stín smrti, proměnil by je v mrákotu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 17, 'Jestliže pak toho neuposlechnete, v skrýších plakati bude duše má pro pýchu vaši, a náramně kvíliti bude. Potekou, pravím, z očí mých slzy, nebo zajato bude stádce Hospodinovo.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 18, 'Rci králi i královně: Seďte na zemi; nebo odjata bude přednost vaše, koruna ozdoby vaší.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 19, 'Města polední uzavírána budou, tak že nebude žádného, kdo by otevříti mohl. Zastěhováno bude všecko Judstvo, zastěhováno bude docela.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 20, 'Pozdvihněte očí svých, a vizte ty, kteříž táhnou od půlnoci. Kdež jest to stádo, kteréžť dáno bylo, stádce ozdoby tvé?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 21, 'Co díš, když tě navštíví, ještos ty naučila je, aby byli nad tebou vůdcové přední? Zdaliž bolesti tebe nezachvátí jako ženu rodící?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 22, 'Díš-li v srdci svém: Proč by mne to potkati mělo? Pro množství nepravosti tvé odkryti budou podolkové tvoji, násilně odjata bude obuv tvá.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 23, 'Může-li změniti Mouřenín kůži svou, aneb pardus peřestost svou, také vy budete moci dobře činiti, naučivše se zle činiti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 24, 'Protož rozptýlím je, jako vítr pouště rozptyluje plevy.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 25, 'Ten bude los tvůj a díl odměřený tobě ode mne, praví Hospodin, proto žes se zapomněla nade mnou, a úfalas v lež.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 26, 'A tak i já také odkryji podolek tvůj nad hlavu tvou, aby spatřína byla hanba tvá,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 27, 'Cizoložství tvá, a řehtání tvá, nešlechetná smilství tvá, na pahrbcích i na poli. Vidělť jsem ty ohavnosti tvé; běda tobě, Jeruzaléme. A což se ještě neočistíš? I až dokud pak?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 1, 'Slovo, kteréž se stalo k Jeremiášovi o suchu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 2, 'Kvíliti bude země Judská, a brány její zemdlejí, smutek ponesou na zemi, a naříkání Jeruzaléma vzejde.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 3, 'Také nejznamenitější z nich rozsílati budou i nejšpatnější své pro vodu. Přijdouce k čisternám, a nenaleznouce vody, navrátí se s nádobami svými prázdnými, hanbíce a stydíce se; protož přikryjí hlavu svou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 4, 'I oráči stydíce se, přikryjí hlavu svou příčinou země vyprahlé, proto že deště nebude na zemi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 5, 'Anobrž i laň na poli, což porodí, opustí; nebo mladistvé trávy nebude.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 6, 'A divocí oslové stojíce na vysokých místech, hltati budou vítr jako draci; přehledí se oči jejich, nebo nebude žádné trávy.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 7, 'Ó Hospodine, poněvadž nepravosti naše svědčí proti nám, slituj se pro jméno své. Nebo mnohá jsou odvrácení naše, toběť jsme zhřešili.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 8, 'Ó naděje Izraelova, vysvoboditeli jeho v čas ssoužení, proč býti máš jako příchozí v této zemi, a jako pocestný stavující se na noclehu?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 9, 'Proč se ukazuješ jako muž ustalý, jako silný, kterýž nemůže vysvoboditi? Všaks ty u prostřed nás, Hospodine, a jméno tvé nad námi vzýváno jest; neopouštějž nás.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 10, 'Takto praví Hospodin o lidu tomto: Tak milují toulky, noh svých nezdržují, až Hospodin nemá v nich líbosti, a nyní zpomíná nepravost jejich, a navštěvuje hříchy jejich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 11, 'Potom řekl ke mně Hospodin: Nemodl se za lid tento k dobrému.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 12, 'Když se postiti budou, já nikoli nevyslyším volání jejich, a když obětovati budou obět zápalnou a suchou, já nikoli neoblíbím sobě těch věcí, ale mečem a hladem a morem já do konce zhubím je.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 13, 'Tedy řekl jsem: Ach, Panovníče Hospodine, aj, tito proroci říkají jim: Neuzříte meče, a hlad nepřijde na vás, ale pokoj pravý dám vám na místě tomto.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 14, 'I řekl Hospodin ke mně: Lež prorokují ti proroci ve jménu mém. Neposlalť jsem jich, aniž jsem přikázal jim, anobrž aniž jsem mluvil k nim. Vidění lživé a hádání, a marné věci i lest srdce svého oni prorokují vám.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 15, 'Protož takto praví Hospodin o prorocích, kteříž prorokují ve jménu mém, ješto jsem já jich neposlal, a kteříž říkají: Meče ani hladu nebude v zemi této: Mečem a hladem i ti sami proroci zhynou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 16, 'Lid pak ten, jemuž oni prorokují, rozmetán bude po ulicích Jeruzalémských hladem a mečem, aniž bude, kdo by je pochovával, je, manželky jejich, a syny jejich, a dcery jejich. Tak vyleji na ně nešlechetnost jejich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 17, 'Protož rciž jim slovo toto: Z očí mých tekou slzy dnem i nocí bez přestání; nebo potřína bude velmi velice panna dcera lidu mého ranou náramně bolestnou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 18, 'Vyjdu-li na pole, aj, tam zbití mečem; pakli vejdu do města, aj, tam nemocní hladem. Nebo jakož prorok tak kněz obcházejíce, kupčí zemí, a lidé toho neznají.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 19, 'Zdaliž do konce zamítáš Judu? Zdali Sion oškliví sobě duše tvá? Proč nás biješ, tak abychom již nebyli uzdraveni? Čekáme-li pokoje, a aj, nic dobrého pakli času uzdravení, a aj, hrůza.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 20, 'Poznávámeť, Hospodine, bezbožnost svou i nepravost otců svých, že jsme hřešili proti tobě.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 21, 'Nezamítejž pro jméno své, nezlehčuj stolice slávy své; rozpomeň se, neruš smlouvy své s námi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 22, 'Zdaliž jsou mezi marnostmi pohanskými ti, kteříž by déšť dávali? A zdaliž nebesa dávají přívaly? Zdaliž ty nejsi sám, Hospodine, Bůh náš? Protož na tebeť očekáváme, nebo ty působíš všecko to.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 1, 'Tedy řekl Hospodin ke mně: Byť se postavil Mojžíš i Samuel před oblíčejem mým, nikoli srdce nemohu míti k lidu tomuto. Pusť je ode mne, a nechť jdou pryč.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 2, 'A řeknou-liť: Kam bychom šli? tedy díš jim: Takto praví Hospodin: Kdo k smrti, na smrt, a kdo k meči, pod meč, a kdo k hladu, k hladu, a kdo k zajetí, do zajetí.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 3, 'Představím zajisté jim to čtvero, dí Hospodin: Meč k zmordování, a psy, aby je rozsmýkali, a ptactvo nebeské i zvěř zemskou, aby je sežrala a zkazila.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 4, 'A musejí se smýkati po všech královstvích země příčinou Manassesa syna Ezechiášova, krále Judského, pro ty věci, kteréž páchal v Jeruzalémě.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 5, 'Nebo kdo by se slitoval nad tebou, Jeruzaléme? A kdo by tě politoval? Aneb kdo by přišel, aby se zeptal, jakť se vede?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 6, 'Tys opustil mne, dí Hospodin, odšels nazpět; protož vztáhnu ruku svou na tebe, abych tě zkazil. Ustal jsem, želeje.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 7, 'Protož přetříbím je věječkou skrze brány země této, na sirobu přivedu a zkazím lid svůj, nebo se od cest svých nenavracují.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 8, 'Větší bude počet vdov jeho než písku mořského. Přivedu na ně, na matky, na mládence zhoubce i v poledne; způsobím to, aby náhle připadli na to město, i budou zděšeni.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 9, 'Zemdlí i ta, kteráž rodívala po sedmerém; vypustí duši svou, zapadne jí slunce ještě ve dne, hanbiti a styděti se bude. Ostatek pak jich vydám pod meč před oblíčejem nepřátel jejich, dí Hospodin.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 10, 'Běda mně, matko má, že jsi mne porodila, muže sváru a muže různice vší zemi. Nepůjčoval jsem jim, aniž mi oni půjčovali, a každý mi zlořečí.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 11, 'I řekl Hospodin: Zdaliž tobě, kterýž pozůstaneš, nebude dobře? Zdaliž nebudu tvým zástupcím u nepřítele v čas trápení a v čas ssoužení?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 12, 'Zdaliž železo poláme půlnoční železo a ocel?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 13, 'Jmění tvé, ó Judo, i poklady tvé vydám v rozchvátání darmo, po všech končinách tvých, a to pro všelijaké hříchy tvé.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 14, 'A způsobím to, že musíš jíti s nepřátely svými do země cizí, když oheň zanícený v prchlivosti mé na vás pálati bude.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 15, 'Ty znáš mne, Hospodine, rozpomeň se na mne, a navštěv mne, a pomsti mne nad těmi, kteříž dotírají na mne. Shovívaje jim, nezachvacuj mne; věz, že snáším pro tebe pohanění.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 16, 'Když se naskytly řeči tvé, snědl jsem je, a měl jsem slovo tvé za radost a potěšení srdce svého, poněvadž jsi ty mne povolal sám, ó Hospodine Bože zástupů.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 17, 'Nesedám v radě posměvačů, aniž pléši; pro přísnost tvou samotný sedám, nebo prchlivostí naplnils mne.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 18, 'Proč má býti bolest má věčná, a rána má smrtelná, kteráž se nechce zhojiti? Proč mi býti máš naprosto jako oklamavatelný, jako vody nestálé?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 19, 'Protož takto praví Hospodin: Jestliže se obrátíš, také tě zase obrátím, abys stál před oblíčejem mým; oddělíš-li věc drahou od ničemné, jako ústa má budeš. Nechť se oni obrátí k tobě, ty pak neobracej se k nim.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 20, 'Nebo jsem tě postavil proti lidu tomuto jako zed měděnou pevnou. Kteříž bojovati budou proti tobě, ale neodolají tobě; nebo já jsem s tebou, abych tě vysvobozoval a vytrhoval, dí Hospodin.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 21, 'Vytrhnu tě zajisté z rukou nešlechetníků, a vykoupím tě z ruky násilníků.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 1, 'I stalo se slovo Hospodinovo ke mně, řkoucí:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 2, 'Nepojímej sobě ženy, aniž měj synů neb dcer na místě tomto.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 3, 'Nebo takto praví Hospodin o synech i dcerách zplozených v místě tomto, a o matkách jejich, kteréž zrodily je, i o jejich otcích, kteříž zplodili je v zemi této:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 4, 'Smrtmi přebolestnými pomrou, nebudou oplakáni, ani pochováni; místo hnoje na svrchku země budou, a mečem i hladem do konce zhubeni budou. I budou mrtvá těla jejich za pokrm ptactvu nebeskému a šelmám zemským.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 5, 'Nebo takto praví Hospodin: Nevcházej do domu smutku, aniž choď kvíliti, aniž jich lituj; odjal jsem zajisté pokoj svůj od lidu tohoto, dobrotivost i slitování, dí Hospodin.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 6, 'Když pomrou velicí i malí v zemi této, nebudou pochováni, aniž kvíliti budou nad nimi, aniž se zřeží, aniž sobě lysiny zdělají pro ně.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 7, 'Aniž jim dadí jísti, aby v truchlosti potěšovali jich nad mrtvým, aniž jich napojí z číše potěšení po otci jejich neb matce jejich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 8, 'Tolikéž do domu hodování nechoď, abys sedati měl s nimi při jídle a pití.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 9, 'Nebo takto praví Hospodin zástupů, Bůh Izraelský: Aj, já způsobím, aby nebývalo na místě tomto před očima vašima a za dnů vašich hlasu radosti, ani hlasu veselé, hlasu ženicha, ani hlasu nevěsty.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 10, 'Když pak oznámíš lidu tomuto všecka slova tato, a řeknou-liť: Proč vyřkl Hospodin proti nám všecko zlé veliké toto, a jaká jest nepravost naše, aneb jaký hřích náš, jímž jsme hřešili proti Hospodinu Bohu svému?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 11, 'Tedy rci jim: Proto že opustili mne otcové vaši, dí Hospodin, a chodíce za bohy cizími, sloužili jim, a klaněli se jim, mne pak opustili, a zákona mého neostříhali.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 12, 'Vy pak mnohem jste hůře činili nežli otcové vaši; nebo aj, vy chodíte jeden každý podlé zdání srdce svého zlého, neposlouchajíce mne.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 13, 'Pročež hodím vámi z země této do země, o níž nevíte vy, ani otcové vaši, a sloužiti budete tam bohům cizím dnem i nocí, dokudž neučiním vám milosti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 14, 'Protož aj, dnové jdou, dí Hospodin, v nichž nebude říkáno více: Živť jest Hospodin, kterýž vyvedl syny Izraelské z země Egyptské,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 15, 'Ale: Živť jest Hospodin, kterýž vyvedl syny Izraelské z země půlnoční a ze všech zemí, do nichž je byl rozehnal, když je zase přivedu do země jejich, kterouž jsem dal otcům jejich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 16, 'Aj, já pošli k rybářům mnohým, dí Hospodin, aby je vylovili; potom pošli i k mnohým lovcům, aby je zlapali na všeliké hoře, a na všelikém pahrbku, i v děrách skalních.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 17, 'Hledím na všecky cesty jejich, nejsouť tajné přede mnou, aniž jest skryta nepravost jejich před očima mýma.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 18, 'I odplatím jim prvé dvojnásobně za nepravost jejich a hřích jejich, proto že zemi mnou poškvrnili těly mrtvými ohyzdnými, a ohavnostmi svými naplnili dědictví mé.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 19, 'Hospodine, sílo má a hrade můj, i útočiště mé v den ssoužení, k toběť přijdou národové od končin země, a řeknou: Jistě žeť se falše drželi otcové naši, marnosti a právě neužitečných věcí.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 20, 'Zdaliž udělá sobě člověk bohy, poněvadž sami nejsou bohové?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 21, 'Protož aj, já způsobím to, aby poznali té chvíle, způsobím, aby poznali ruku mou i moc mou, a zvědíť, že jméno mé jest Hospodin.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 1, 'Hřích Judův napsán jest pérem železným, rafijí kamene přetvrdého, vyryt jest na tabuli srdce jejich, a na rozích oltářů vašich,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 2, 'Tak když zpomínají synové jejich na oltáře jejich i háje jejich, pod dřívím zeleným, na pahrbcích vysokých.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 3, 'Ó horo, s tím polem jmění tvé i všecky poklady tvé vydám v rozchvátání, pro hřích výsostí tvých, ve všech končinách tvých.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 4, 'A ty musíš lhůtu dáti z strany sebe dědictví svému, kteréž jsem byl dal tobě, a podrobím tě v službu nepřátelům tvým v zemi, o níž nevíš; nebo jste oheň zanítili v prchlivosti mé, kterýž až na věky hořeti bude.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 5, 'Takto praví Hospodin: Zlořečený ten muž, kterýž doufá v člověka, a kterýž klade tělo za rámě své, od Hospodina pak odstupuje srdce jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 6, 'Nebo bude podobný vřesu na pustině, kterýž necítí, když co přichází dobrého, ale bývá na vyprahlých místech na poušti v zemi slatinné, a v níž se nebydlí.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 7, 'Požehnaný ten muž, kterýž doufá v Hospodina, a jehož naděje jest Hospodin.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 8, 'Nebo podobný bude stromu štípenému při vodách, a při potoku pouštějícímu kořeny své, kterýž necítí, když přichází vedro, ale list jeho bývá zelený, a v rok suchý nestará se, aniž přestává nésti ovoce.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 9, 'Nejlstivější jest srdce nade všecko, a nejpřevrácenější. Kdo vyrozumí jemu?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 10, 'Já Hospodin, kterýž zpytuji srdce, a zkušuji ledví, tak abych odplatil jednomu každému podlé cesty jeho, podlé ovoce skutků jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 11, 'Koroptva škřečí, ale nevysedí. Tak kdož dobývá statku však s křivdou, v polovici dnů svých musí opustiti jej, a naposledy bude bláznem.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 12, 'Místo svatyně naší, stolice slavná Nejvyššího, věčně trvá.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 13, 'Ó naděje Izraelova, Hospodine, všickni, kteříž tě opouštějí, nechť jsou zahanbeni. Kárání má v zemi této nechť jsou zapsána; nebo opustili pramen vod živých, Hospodina.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 14, 'Uzdrav mne, Hospodine, a zdráv budu; vysvoboď mne, a vysvobozen budu, ty jsi zajisté chvála má.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 15, 'Aj, oni říkají mi: Kdež jest to, což předpovídal Hospodin? Nechť již přijde.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 16, 'Ješto jsem já se nevetřel, abych pastýřem byl tvým, a dne bolesti nebylť jsem žádostiv, ty víš. Cožkoli vyšlo z rtů mých, před oblíčejem tvým jest.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 17, 'Nebudiž mi k strachu, útočiště mé jsi v čas trápení.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 18, 'Nechť jsou zahanbeni, kteříž mne stihají, já pak ať nejsem zahanben; nechť se oni děsí, já pak ať se neděsím. Uveď na ně den trápení, a dvojím setřením setři je.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 19, 'Takto řekl Hospodin ke mně: Jdi a postav se v bráně lidu tohoto, skrze kterouž chodívají králové Judští, a skrze kterouž vycházívají, anobrž ve všech branách Jeruzalémských,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 20, 'A rci jim: Slyšte slovo Hospodinovo, králové Judští, i všecken Judo, a všickni obyvatelé Jeruzaléma, kteříž chodíváte skrze brány tyto:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 21, 'Takto praví Hospodin: Vystříhejte se s pilností, abyste nenosili břemen v den sobotní, ani vnášeli skrze brány Jeruzalémské.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 22, 'Ani nevynášejte břemen z domů svých v den sobotní, a žádného díla nedělejte, ale svěťte den sobotní, jakž jsem přikázal otcům vašim.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 23, '(Však neuposlechli, aniž naklonili ucha svého, ale zatvrdili šíji svou, neposlouchajíce a nepřijímajíce naučení.)');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 24, 'Stane se zajisté, jestliže s ochotností mne uposlechnete, dí Hospodin, abyste nenosili břemen skrze brány města tohoto v den sobotní, ale světili den sobotní, nedělajíce v něm žádného díla,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 25, 'Že poberou se skrze brány města tohoto králové i knížata sedící na stolici Davidově, jezdíce na vozích i na koních, oni i knížata jejich, muži Judští a obyvatelé Jeruzalémští, a státi bude toto město až na věčnost.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 26, 'I budou přicházeti z měst Judských a z okolí Jeruzaléma, jakož z země Beniaminovy, tak z roviny, i z té hory, i od poledne, nesouce zápal, a obět i dar s kadidlem, také i díků činění nesouce do domu Hospodinova.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 27, 'Jestliže pak neuposlechnete mne, abyste světili den sobotní, a nenosili břemen, chodíce skrze brány Jeruzalémské v den sobotní, tedy zanítím oheň v branách jeho, kterýžto zžíře paláce Jeruzalémské, a neuhasne.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 1, 'Slovo, kteréž se stalo k Jeremiášovi od Hospodina, řkoucí:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 2, 'Vstaň a sejdi do domu hrnčířova, a tam způsobím to, abys slyšel slova má.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 3, 'I sešel jsem do domu hrnčířova, a aj, on dělal dílo na kruzích.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 4, 'Když se pak zkazila nádoba v ruce hrnčířově, kterouž on dělal z hliny, tehdy zase udělal z ní nádobu jinou, jakouž se dobře líbilo hrnčíři udělati.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 5, 'I stalo se slovo Hospodinovo ke mně, řkoucí:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 6, 'Zdaliž jako hrnčíř tento nemohl bych nakládati s vámi, ó dome Izraelský? dí Hospodin. Aj, jakož hlina v ruce hrnčíře, tak jste vy v ruce mé, ó dome Izraelský.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 7, 'Mluvil-li bych proti národu a proti království, že je v okamžení vypléním a zkazím, i vyhubím,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 8, 'Však odvrátil-li by se národ ten od nešlechetnosti své, proti němuž bych mluvil: i já litoval bych toho zlého, kteréž jsem myslil učiniti jemu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 9, 'Zase mluvil-li bych o národu a o království, že je v okamžení vzdělám a vštípím,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 10, 'Však činil-li by, což zlého jest před očima mýma, neposlouchaje hlasu mého: i já litoval bych dobrodiní toho, kteréž bych řekl učiniti jemu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 11, 'Protož nyní rci mužům Judským i obyvatelům Jeruzalémským, řka: Takto praví Hospodin: Aj, já strojím na vás zlou věc, a obrátím na vás pohromu; navraťtež se již jeden každý od cesty své zlé, a polepšte cest svých i předsevzetí svých.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 12, 'Kteřížto řekli: To nic, nebo za myšlénkami svými půjdeme, a jeden každý zdání srdce svého nešlechetného vykonávati budeme.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 13, 'Protož takto praví Hospodin: Vyptejte se nyní mezi pohany, slýchal-li kdo takové věci? Mrzkosti veliké dopustila se panna Izraelská.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 14, 'Zdaliž kdo pohrdá čerstvou vodou Libánskou z skály? Zdaž pohrdají vodami studenými odjinud běžícími?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 15, 'Lid pak můj zapomenuvše se na mne, kadí marnosti. Nebo k úrazu je přivodí na cestách jejich, na stezkách starobylých, chodíce stezkami cesty neprotřené,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 16, 'Tak abych musil obrátiti zemi jejich v poušť na odivu věčnou; každý, kdož by šel skrze ni, aby se užasl, a pokynul hlavou svou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 17, 'Větrem východním rozptýlím je před nepřítelem; hřbetem a ne tváří pohledím na ně v čas bídy jejich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 18, 'I řekli: Poďte a vymyslme proti Jeremiášovi nějakou chytrost; neboť nezhyne zákon od kněze, ani rada od moudrého, ani slovo od proroka. Poďte a zarazme jej jazykem, a nemějme pozoru na žádná slova jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 19, 'Pozoruj mne, Hospodine, a slyš hlas těch, kteříž se vadí se mnou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 20, 'Zdaliž má odplacováno býti za dobré zlým, že mi jámu kopají? Rozpomeň se, že jsem se postavoval před oblíčejem tvým, abych se přimlouval k jejich dobrému, a odvrátil prchlivost tvou od nich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 21, 'Protož dopusť na syny jejich hlad, a způsob to, ať jsou násilně zmordování mečem, a nechť jsou ženy jejich osiřelé a ovdovělé, a muži jejich ať jsou ukrutně zmordováni, a mládenci jejich zbiti mečem v boji.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 22, 'Nechť jest slýchati křik z domů jejich, když přivedeš na ně vojsko náhle. Nebo vykopali jámu, aby popadli mne, a osídla polékli nohám mým;');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 23, 'Ješto ty, Hospodine, povědom jsi vší rady jejich o mém usmrcení. Nebuď milostiv nepravosti jejich, a hříchu jejich před tváří svou neshlazuj, ale nechť jsou k úrazu dostrčeni před oblíčejem tvým, a v čas prchlivosti své s nimi zacházej.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 19, 1, 'Takto řekl Hospodin: Jdi a zjednej báni záhrdlitou od hrnčíře, hliněnou, a pojma některé z starších lidu a z starších kněží,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 19, 2, 'Vejdi do údolí Benhinnom, kteréž jest u vrat brány východní, a ohlašuj tam slova ta, kteráž mluviti budu tobě.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 19, 3, 'A rci: Slyšte slovo Hospodinovo, králové Judští i obyvatelé Jeruzalémští: Takto praví Hospodin zástupů, Bůh Izraelský: Aj, já uvedu bídu na místo toto, o kteréž kdokoli uslyší, zníti mu bude v uších jeho,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 19, 4, 'Proto že mne opustili, a poškvrnili místa tohoto, kadíce na něm bohům cizím, jichž neznali oni, ani otcové jejich, ani králové Judští, a naplnili toto místo krví nevinných.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 19, 5, 'Vzdělali také výsosti Bálovi, aby pálili syny své ohněm v zápaly Bálovi, čehož jsem nepřikázal, aniž jsem o tom mluvil, nýbrž ani nevstoupilo na mé srdce.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 19, 6, 'Protož aj, dnové jdou, dí Hospodin, v nichž nebude slouti více toto místo Tofet, ani údolí Benhinnom, ale údolí mordu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 19, 7, 'Nebo v nic obrátím radu Judovu i Jeruzalémských v místě tomto, způsobě to, aby padli od meče před nepřátely svými, a od ruky těch, kteříž hledají bezživotí jejich, i dám mrtvá těla jejich za pokrm ptactvu nebeskému a šelmám zemským.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 19, 8, 'Obrátím také město toto v poušť na odivu. Každý, kdožkoli půjde mimo ně, užasne se, a ckáti bude pro všelijaké rány jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 19, 9, 'A způsobím to, že žráti budou maso synů svých a maso dcer svých, tolikéž jeden každý maso bližního svého žráti bude, v obležení a v ssoužení, kterýmž ssouží je nepřátelé jejich, a ti, kteříž hledají bezživotí jejich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 19, 10, 'Potom roztluc tu záhrdlitou báni před očima těch lidí, kteříž půjdou s tebou,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 19, 11, 'A rci jim: Takto praví Hospodin zástupů: Tak potluku lid tento i město toto, jako ten, kdož rozráží nádobu hrnčířskou, kteráž nemůže opravena býti více, a v Tofet pochovávati budou, proto že nebude žádného místa ku pohřbu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 19, 12, 'Tak učiním místu tomuto, dí Hospodin, i obyvatelům jeho, a naložím s městem tímto tak jako s Tofet.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 19, 13, 'Nebo budou domové Jeruzalémských i domové králů Judských tak jako toto místo Tofet zanečištěni se všechněmi domy těmi, na jejichž střechách kadili všemu vojsku nebeskému, a obětovali oběti mokré bohům cizím.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 19, 14, 'Tedy navrátiv se Jeremiáš z Tofet, kamž jej byl poslal Hospodin, aby prorokoval tam, postavil se v síňci domu Hospodinova, a řekl ke všemu lidu:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 19, 15, 'Takto praví Hospodin zástupů, Bůh Izraelský: Aj, já uvedu na město toto i na všecka města jeho všecko to zlé, kteréž jsem vyřkl proti němu; nebo zatvrdili šíji svou, aby neposlouchali slov mých.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 1, 'Tedy slyšev Paschur syn Immerův, kněz, kterýž byl přední správce v domě Hospodinově, Jeremiáše prorokujícího o těch věcech,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 2, 'Ubil Paschur Jeremiáše proroka, a dal jej do vězení v bráně Beniaminově hořejší, kteráž byla při domě Hospodinově.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 3, 'Stalo se pak nazejtří, když vyvedl Paschur Jeremiáše z vězení, že řekl jemu Jeremiáš: Nenazval Hospodin jména tvého Paschur, ale Magor missabib.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 4, 'Nebo takto praví Hospodin: Aj, já pustím na tebe strach, na tebe i na všecky přátely tvé, kteříž padnou od meče nepřátel svých, načež oči tvé hleděti budou, když všecken lid Judský vydám v ruku krále Babylonského, kterýž zavede je do Babylona, a mečem je pobije.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 5, 'Vydám i všelijaké bohatství města tohoto, a všecko úsilé jeho, i všelijakou věc drahou jeho, i všecky poklady králů Judských vydám v ruku nepřátel jejich, a rozchvátají je, i poberou je, a dovezou je do Babylona.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 6, 'Ty pak Paschur i všickni, kteříž bydlí v domě tvém, půjdete do zajetí, a do Babylona se dostaneš, a tam umřeš, i tam pochován budeš ty i všickni milující tebe, jimž jsi prorokoval lživě.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 7, 'Namlouvals mne, Hospodine, a dalť jsem se přemluviti; silnějšís byl nežli já, protož zmocnils se mne. Jsem v posměchu každý den, každý se mi posmívá.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 8, 'Nebo jakž jsem začal mluviti, úpím, pro ukrutenství a zhoubu křičím; slovo zajisté Hospodinovo jest mi ku potupě a ku posměchu každého dne.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 9, 'I řekl jsem: Nebuduť ho připomínati, ani mluviti více ve jménu jeho. Ale jest v srdci mém jako oheň hořící, zavřený v kostech mých, jehož snažuje se zdržeti, však nemohu,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 10, 'Ačkoli slýchám utrhání mnohých, i Magor missabiba, říkajících: Povězte něco na něj, a oznámíme to králi. Všickni, kteříž by měli býti přátelé moji, číhají na poklesnutí mé, říkajíce: Snad někde podveden bude, a zmocníme se ho, a pomstíme se nad ním.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 11, 'Ale Hospodin jest se mnou jakožto rek udatný, protož ti, kteříž mne stihají, zurážejí se, a neodolají; styděti se budou náramně, nebo se jim šťastně nezvede, aniž potupa věčná v zapomenutí dána bude.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 12, 'Protož ó Hospodine zástupů, kterýž zkušuješ spravedlivého, kterýž spatřuješ ledví a srdce, nechť se podívám na pomstu tvou nad nimi, tobě zajisté zjevil jsem při svou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 13, 'Zpívejte Hospodinu, chvalte Hospodina, že vytrhl duši nuzného z ruky nešlechetných.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 14, 'Zlořečený ten den, v němžto zplozen jsem, den, v němž porodila mne matka má, ať není požehnaný.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 15, 'Zlořečený ten muž, kterýž zvěstoval otci mému, chtěje zvláštně obradovati jej, řka: Narodiloť se dítě pohlaví mužského.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 16, 'A nechť jest ten muž podobný městům, kteráž podvrátil Hospodin, a neželel; nebo slyšel křik v jitře, a provyskování v čas polední.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 17, 'Ó že mne neusmrtil od života, ješto by mi matka má byla hrobem mým, a život její věčně těhotný.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 18, 'Proč jsem jen z života vyšel, abych okoušel těžkosti a zámutku, a aby stráveni byli v pohanění dnové moji?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 21, 1, 'Slovo, kteréž se stalo k Jeremiášovi od Hospodina, když poslal k němu král Sedechiáš Paschura syna Malkiášova a Sofoniáše syna Maaseiášova, kněze, aby řekli:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 21, 2, 'Poraď se medle o nás s Hospodinem, nebo Nabuchodonozor král Babylonský bojuje proti nám, zdali by snad naložil Hospodin s námi podlé všech divných skutků svých, aby on odtáhl od nás.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 21, 3, 'Tedy řekl Jeremiáš k nim: Tak rcete Sedechiášovi:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 21, 4, 'Takto praví Hospodin Bůh Izraelský: Aj, já odvrátím nástroje válečné, kteréž jsou v rukou vašich, jimiž vy bojujete proti králi Babylonskému a Kaldejským, kteříž oblehli vás vně za zdí, a shromáždím je do prostřed města tohoto.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 21, 5, 'Bojovati zajisté budu já proti vám rukou vztaženou a ramenem silným, a to v hněvě a v rozpálení i v prchlivosti veliké.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 21, 6, 'A raním obyvatele města tohoto, tak že lidé i hovada morem velikým pomrou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 21, 7, 'Potom pak (dí Hospodin), dám Sedechiáše krále Judského a služebníky jeho i lid, totiž ty, kteříž pozůstanou v městě tomto po moru, po meči a po hladu, v ruku Nabuchodonozora krále Babylonského, a v ruku nepřátel jejich, a tak v ruku hledajících bezživotí jejich. Kterýžto je zbije ostrostí meče, neodpustí jim, aniž jich šanovati bude, aniž se smiluje.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 21, 8, 'Protož rci lidu tomuto: Takto praví Hospodin: Aj, já kladu před vás cestu života i cestu smrti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 21, 9, 'Kdokoli zůstane v městě tomto, zahyne od meče, neb hladem, neb morem, ale kdož vyjde a poddá se Kaldejským, kteříž oblehli vás, jistotně živ zůstane, a bude míti život svůj místo kořisti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 21, 10, 'Nebo postavil jsem zůřivou tvář svou proti městu tomuto k zlému, a ne k dobrému, dí Hospodin. V ruku krále Babylonského vydáno bude, i vypálí je ohněm.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 21, 11, 'Domu pak krále Judského rci: Slyšte slovo Hospodinovo,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 21, 12, 'Ó dome Davidův, takto praví Hospodin: Držívejte každého jitra soud, a vychvacujte obloupeného z ruky násilníka, aby nevyšla jako oheň prchlivost má, a nehořela, tak že by nebylo žádného, kdo by uhasiti mohl, pro nešlechetnost předsevzetí vašich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 21, 13, 'Aj já, dí Hospodin, na tebe, kteráž přebýváš v údolí tomto, skálo roviny této, kteříž říkáte: Kdo by přitáhl na nás, aneb kdo by všel do příbytků našich?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 21, 14, 'Nebo trestati vás budu podlé skutků vašich, dí Hospodin, a zanítím oheň v lese tvém, kterýž zžíře všecko vůkol něho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 1, 'Takto řekl Hospodin: Sejdi do domu krále Judského, a mluv tam slovo toto,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 2, 'A rci: Slyš slovo Hospodinovo, králi Judský, kterýž sedíš na stolici Davidově, ty i služebníci tvoji i lid tvůj, kteříž chodíte skrze brány tyto.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 3, 'Takto praví Hospodin: Konejte soud a spravedlnost, a vychvacujte obloupeného z ruky násilníka; příchozímu tolikéž, sirotku, ani vdově nečiňte křivdy, aniž jich utiskujte, a krve nevinné nevylévejte na místě tomto.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 4, 'Nebo budete-li to pilně vykonávati, jistě že poberou se skrze brány domu tohoto králové, sedící místo Davida na stolici jeho, jezdíce na vozích, neb na koních, král s služebníky svými i s lidem svým.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 5, 'Jestliže pak neuposlechnete slov těchto, skrze sebe přisahám, dí Hospodin, že poušť bude dům tento.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 6, 'Nebo takto praví Hospodin o domu krále Judského: Byl jsi mi jako Galád a vrch Libánský, ale obrátím tě jistotně v poušť jako města, v nichž se bydliti nemůže.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 7, 'A přistrojím na tebe zhoubce, jednoho každého se zbrojí jeho, kteřížto zpodtínají nejvýbornější cedry tvé, a vmecí na oheň.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 8, 'A když půjdou národové mnozí mimo město toto, a řekne jeden druhému: Proč tak učinil Hospodin městu tomuto velikému?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 9, 'Tedy řeknou: Proto že opustili smlouvu Hospodina Boha svého, a klaněli se bohům cizím a sloužili jim.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 10, 'Neplačtež mrtvého, aniž ho litujte, ale ustavičně plačte příčinou toho, kterýž odchází; neboť se nenavrátí více, aby pohleděl na zemi, v níž se narodil.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 11, 'Nebo takto praví Hospodin o Sallumovi synu Joziáše, krále Judského, kterýž kraluje místo Joziáše otce svého: Když vyjde z místa tohoto, nenavrátí se sem více.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 12, 'Ale tam v tom místě, kamž jej zastěhují, umře, a tak země této neuzří více.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 13, 'Běda tomu, kdož staví dům svůj s útiskem, a paláce své s křivdou, kterýž bližního svého v službu podrobuje darmo, mzdy pak jeho nedává jemu;');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 14, 'Kterýž říká: Vystavím sobě dům veliký a paláce prostranné, kterýž prolamuje sobě okna, a tafluje cedrovím, a maluje barvou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 15, 'Zdaliž kralovati budeš, že se pleteš v to cedrové stavení? Otec tvůj zdaliž nejídal a nepíjel? Když konal soud a spravedlnost, tedy dobře bylo jemu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 16, 'Když soudíval při chudého a nuzného, tedy dobře bylo. Zdaliž mně to není známé? dí Hospodin.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 17, 'Ale oči tvé i srdce tvé nehledí než lakomství tvého, a abys krev nevinnou proléval, a nátisk a křivdu činil.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 18, 'Protož takto praví Hospodin o Joakimovi synu Joziáše, krále Judského: Nebudouť ho kvíliti: Ach, bratře můj, aneb ach, sestro. Nebudou ho kvíliti: Ach, pane, aneb ach, kdež důstojnost jeho?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 19, 'Pohřbem osličím pohřben bude, vyvlečen a vyvržen jsa za brány Jeruzalémské.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 20, 'Vstup na Libán a křič, i na hoře Bázan vydej hlas svůj; křič také přes brody, když potříni budou všickni milovníci tvoji.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 21, 'Mluvíval jsem s tebou v největším štěstí tvém, říkávalas: Nebuduť poslouchati. Tať jest cesta tvá od dětinství tvého; neuposlechlas zajisté hlasu mého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 22, 'Všecky pastýře tvé zpase vítr, a milovníci tvoji v zajetí půjdou. Tehdáž jistě hanbiti a styděti se budeš za všelikou nešlechetnost svou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 23, 'Ó ty, kteráž jsi usadila se na Libánu, jenž se hnízdíš na cedroví, jak milostná budeš, když na tě přijdou svírání a bolest jako rodičky!');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 24, 'Živť jsem já, dí Hospodin, že byť pak byl Koniáš syn Joakima, krále Judského, prstenem pečetním na mé ruce pravé, však tě i odtud strhnu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 25, 'A vydám tě v ruku těch, kteříž hledají bezživotí tvého, a v ruku těch, jejichž ty se oblíčeje lekáš, totiž v ruku Nabuchodonozora krále Babylonského, a v ruku Kaldejských.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 26, 'A hodím tebou i matkou tvou, kteráž tě porodila, do země cizí, tam, kdež jste se nezrodili, a tam zemřete.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 27, 'Do země pak, po níž toužiti budete, abyste se navrátili tam, tam se nenavrátíte.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 28, 'Zdaliž modlou ničemnou, kteráž roztřískána bývá, bude muž tento Koniáš? Zdali nádobou, v níž není žádné líbosti? Proč by vyházíni byli on i símě jeho, a uvrženi do země, o níž nevědí?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 29, 'Ó země, země, země, slyš slovo Hospodinovo.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 30, 'Takto praví Hospodin: Zapište to, že muž tento bez dětí bude, a že se jemu nepovede šťastně za dnů jeho. Anobrž nepovede se šťastně i tomu muži, kterýž by z semene jeho seděl na stolici Davidově, a panoval ještě nad Judou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 1, 'Běda pastýřům hubícím a rozptylujícím stádce pastvy mé, dí Hospodin.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 2, 'Protož takto praví Hospodin Bůh Izraelský o pastýřích, kteříž pasou lid můj: Vy rozptylujete ovce mé, anobrž rozháníte je, a nenavštěvujete jich; aj, já navštívím vás pro nešlechetnost předsevzetí vašich, dí Hospodin.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 3, 'Ostatek pak ovcí svých já shromáždím ze všech zemí, do nichž jsem je rozehnal, a přivedu je zase do ovčinců jejich, kdežto ploditi a množiti se budou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 4, 'Nadto ustanovím nad nimi pastýře, kteříž by je pásli, aby se nebály více, ani strachovaly, ani hynuly, dí Hospodin.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 5, 'Aj, dnové jdou, dí Hospodin, v nichž vzbudím Davidovi výstřelek spravedlivý, i kralovati bude král, a šťastně se jemu povede; soud zajisté a spravedlnost na zemi konati bude.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 6, 'Za dnů jeho spasen bude Juda, a Izrael bydliti bude bezpečně, a toť jest jméno jeho, kterýmž ho nazývati bude: Hospodin spravedlnost naše.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 7, 'Protož aj, dnové jdou, dí Hospodin, v nichž nebude říkáno více: Živť jest Hospodin, kterýž vyvedl syny Izraelské z země Egyptské,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 8, 'Ale: Živť jest Hospodin, kterýž vyvedl a kterýž zprovodil símě domu Izraelského z země půlnoční i ze všech zemí, do nichž jsem byl je rozehnal, když se osadí v zemi své.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 9, 'Příčinou proroků potříno jest srdce mé ve mně, pohnuly se všecky kosti mé; jsem jako člověk opilý, a jako muž, kteréhož rozešlo víno, pro Hospodina a pro slova svatosti jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 10, 'Nebo cizoložníků plná jest tato země, a příčinou křivých přísah kvílí země, usvadla pastviska na poušti; jest zajisté utiskování těchto nešlechetné, a moc jejich nepravá.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 11, 'Nebo jakož prorok, tak kněz pokrytství páchají. Také v domě svém nacházím nešlechetnost jejich, dí Hospodin.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 12, 'Pročež budou míti cestu svou podobnou plzkosti v mrákotě, na níž postrčeni budou a padnou, když uvedu na ně bídu v čas navštívení jejich, dí Hospodin.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 13, 'Při prorocích zajisté Samařských viděl jsem nesmyslnost; prorokovali skrze Bále, a svodili lid můj Izraelský.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 14, 'Ale při prorocích Jeruzalémských vidím hroznou věc, že cizoložíce a se lží se obcházejíce, posilňují také rukou nešlechetníků, aby se neobrátil žádný od nešlechetnosti své. Mám všecky za podobné Sodomě, a obyvatele jeho za podobné Gomoře.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 15, 'Protož takto praví Hospodin zástupů o prorocích těchto: Aj, já nakrmím je pelynkem, a napojím je vodami jedovatými; nebo od proroků Jeruzalémských vyšla poškvrna na všecku tuto zemi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 16, 'Takto praví Hospodin zástupů: Neposlouchejtež slov těch proroků, jenž prorokují vám, prázdných vás zanechávajíce. Vidění srdce svého mluví, ne z úst Hospodinových.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 17, 'Ustavičně říkají těm, kteříž mnou pohrdají: Pravil Hospodin: Pokoj míti budete, a každému chodícímu podlé zdání srdce svého říkají: Nepřijdeť na vás nic zlého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 18, 'Nebo kdož jest stál v radě Hospodinově, a viděl neb slyšel slovo jeho? Kdo pozoroval slova jeho, neb vyslechl je?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 19, 'Aj, vichřice Hospodinova s prchlivostí vyjde, a to vichřice trvající; nad hlavou nešlechetných trvati bude.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 20, 'Neodvrátíť se hněv Hospodinův, dokudž neučiní a nevykoná úmyslu srdce svého. A tehdáž porozumíte tomu cele,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 21, 'Žeť jsem neposílal těch proroků, ale sami běželi, že jsem nemluvil k nim, a však oni prorokovali.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 22, 'Nebo byť byli stáli v radě mé, jistě že by byli ohlašovali slova má lidu mému, a byliť by je odvraceli od cesty jejich zlé, a od nešlechetnosti předsevzetí jejich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 23, 'Zdaliž jsem já Bůh jen z blízka? dí Hospodin. A nejsem Bůh i z daleka?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 24, 'Zdaž se ukryje kdo v skrýších, abych já ho neshlédl? dí Hospodin. Zdaliž nebe i země já nenaplňuji? dí Hospodin.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 25, 'Slýchávámť, co říkají ti proroci, kteříž prorokují lež ve jménu mém, říkajíce: Měl jsem sen, měl jsem sen.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 26, 'I dokudž to bude? Zdaliž v srdci těch proroků, kteříž prorokují, není lež? Anobrž jsou proroci lsti srdce svého,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 27, 'Kteříž obmýšlejí to, jak by vyrazili z paměti lidu mému jméno mé sny svými, kteréž vypravují jeden každý bližnímu svému, jako se zapomněli otcové jejich na jméno mé za příčinou Bále.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 28, 'Prorok, kterýž má sen, nechť vypravuje sen, ale kterýž má slovo mé, nechť mluví slovo mé právě. Co jest té plevě do pšenice? dí Hospodin.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 29, 'Zdaliž není slovo mé takové jako oheň, dí Hospodin, a jako kladivo rozrážející skálu?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 30, 'Protož aj já, dí Hospodin, proti těm prorokům, kteříž ukrádají slova má jeden každý před bližním svým.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 31, 'Aj já, dí Hospodin, proti těm prorokům, kteříž chlubně mluví, říkajíce: Praví Hospodin.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 32, 'Aj já, dí Hospodin, proti těm, kteříž prorokují sny lživé, a vypravujíce je, svodí lid můj lžmi svými a žvavostí svou, ješto jsem já jich neposlal, aniž jsem jim přikázal. Pročež naprosto nic neprospívají lidu tomuto, dí Hospodin.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 33, 'Protož, když by se tázal tebe lid tento, neb některý prorok neb kněz, řka: Jaké jest břímě Hospodinovo? tedy rci jim: Jaké břímě? I to: Opustím vás, dí Hospodin.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 34, 'Nebo proroka a kněze toho i lid ten, kterýž by řekl: Břímě Hospodinovo, jistě trestati budu muže toho i dům jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 35, 'Ale takto říkejte jeden každý bližnímu svému a jeden každý bratru svému: Co odpověděl Hospodin? aneb: Co mluvil Hospodin?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 36, 'Břemene pak Hospodinova nepřipomínejte více, sic by břemenem bylo jednomu každému slovo jeho, když byste převraceli slova Boha živého, Hospodina zástupů, Boha našeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 37, 'Takto říkati budeš proroku: Coť odpověděl Hospodin? aneb: Co mluvil Hospodin?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 38, 'Ale poněvadž říkáte: Břímě Hospodinovo, tedy takto praví Hospodin: Poněvadž říkáte slovo to: Břímě Hospodinovo, ješto jsem posílal k vám, říkaje: Neříkejte: Břímě Hospodinovo,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 39, 'Protož aj, já jistě zapomenu se na vás do konce, a zavrhu vás i to město, kteréž jsem byl dal vám i otcům vašim, od tváři své,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 40, 'A uvedu na vás pohanění věčné i potupu věčnou, kteráž nepřijde v zapomenutí.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 24, 1, 'Ukázal mi Hospodin, a aj, dva košové fíků postaveni byli před chrámem Hospodinovým, když byl přestěhoval Nabuchodonozor král Babylonský Jekoniáše syna Joakimova, krále Judského, a knížata Judská, i tesaře a kováře z Jeruzaléma, a přivedl je do Babylona.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 24, 2, 'Jeden koš byl fíků velmi dobrých, jacíž bývají fíkové ranní, druhý pak koš fíků velmi zlých, jakýchž nelze jísti pro trpkost.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 24, 3, 'Tedy řekl mi Hospodin: Co vidíš, Jeremiáši? I řekl jsem: Fíky, dobré fíky, a to velmi dobré, zlé pak, a to velmi zlé, jichž nelze jísti pro trpkost.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 24, 4, 'I stalo se slovo Hospodinovo ke mně, řkoucí:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 24, 5, 'Takto praví Hospodin, Bůh Izraelský: Jako fíkové tito dobří, tak mně příjemní budou zajatí Judští, kteréž jsem zaslal z místa tohoto do země Kaldejské k dobrému.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 24, 6, 'Obrátím zajisté oči své k nim k dobrému, a přivedu je zase do země této, kdežto vzdělám je, a nezkazím, štípím je, a nevypléním.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 24, 7, 'Nebo dám jim srdce, aby znali mne, že já jsem Hospodin. I budou mým lidem, a já budu jejich Bohem, když se obrátí ke mně celým srdcem svým.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 24, 8, 'Naodpor, jako fíky zlé, kterýchž nelze jísti pro trpkost, tak zavrhu (toť zajisté praví Hospodin), Sedechiáše krále Judského s knížaty jeho, a ostatek Jeruzalémských pozůstalých v zemi této, i ty, kteříž bydlí v zemi Egyptské.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 24, 9, 'Vydám je, pravím, v posmýkání k zlému po všech královstvích země, v pohanění a v přísloví, v rozprávku a v proklínání po všech těch místech, kamž je rozženu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 24, 10, 'A budu posílati na ně meč, hlad a mor, dokudž by do konce vyhlazeni nebyli z země, kterouž jsem byl dal jim i otcům jejich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 1, 'Slovo, kteréž se stalo k Jeremiášovi proti všemu lidu Judskému, léta čtvrtého Joakima syna Joziášova, krále Judského, (jenž jest první rok Nabuchodonozora krále Babylonského),');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 2, 'Kteréž mluvil Jeremiáš prorok ke všemu lidu Judskému, i ke všechněm obyvatelům Jeruzalémským, řka:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 3, 'Od třináctého léta Joziáše syna Amonova, krále Judského, až do tohoto dne, po těchto třimecítma let, bývalo slovo Hospodinovo ke mně, kteréž jsem vám mluvíval, ráno přivstávaje, a to ustavičně, ale neposlouchali jste.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 4, 'Posílal také Hospodin k vám všecky slouhy své proroky, ráno přivstávaje, a to ustavičně, (jichžto neposlouchali jste, aniž jste naklonili ucha svého, abyste slyšeli).');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 5, 'Kteříž říkali: Navraťtež se již jeden každý z cesty své zlé a od nešlechetnosti předsevzetí svých, a tak osazujte se v té zemi, kterouž dal Hospodin vám i otcům vašim od věků až na věky.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 6, 'A nechoďte za bohy cizími, abyste sloužiti měli jim, aniž se jim klanějte, aniž hněvejte mne dílem rukou svých, a neučinímť vám zle.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 7, 'Ale neposlouchali jste mne, dí Hospodin, abyste jen hněvali mne dílem rukou svých k svému zlému.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 8, 'Protož takto praví Hospodin zástupů: Proto že jste neuposlechli slov mých,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 9, 'Aj, já pošli, a pojmu všecky národy půlnoční, dí Hospodin, i k Nabuchodonozorovi králi Babylonskému, služebníku svému, a přivedu je na zemi tuto i na obyvatele její, i na všecky národy tyto okolní, kteréž jako proklaté vyhladím, a způsobím to, aby byli k užasnutí, na odivu, a poustkou věčnou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 10, 'Také způsobím to, aby zahynul jim hlas radosti i hlas veselé, hlas ženicha i hlas nevěsty, hluk žernovu i světlo svíce.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 11, 'I bude všecka země tato pustinou a pouští, a sloužiti budou národové tito králi Babylonskému sedmdesáte let.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 12, 'Potom pak po vyplnění sedmdesáti let trestati budu na králi Babylonském a na tom národu, dí Hospodin, nepravost jejich, totiž na zemi Kaldejské, tak že obrátím ji v pustiny věčné.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 13, 'A uvedu na zemi tu všecka slova svá, kteráž jsem mluvil o ní, všecko, což psáno jest v knize této, cožkoli prorokoval Jeremiáš o všech národech.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 14, 'Když je v službu podrobí, i jiné národy mnohé a krále veliké, tehdáž odplatím jim podlé skutků jejich a podlé činů rukou jejich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 15, 'Nebo takto mi řekl Hospodin, Bůh Izraelský: Vezmi kalich vína prchlivosti této z ruky mé, a napájej jím všecky ty národy, k kterýmž já pošli tebe,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 16, 'Aby pili a potáceli se, anobrž bláznili příčinou meče, kterýž já pošli mezi ně.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 17, 'I vzal jsem kalich z ruky Hospodinovy, a napájel jsem všecky ty národy, k nimž mne poslal Hospodin,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 18, 'Jeruzalémské i města země Judské, a krále její i knížata její, abych je oddal v pustinu a v zpuštění, na odivu, i k proklínání tohoto dnešního dne,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 19, 'Faraona krále Egyptského i služebníky jeho, i knížata jeho, i všecken lid jeho,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 20, 'I všecku tu směsici, totiž všecky krále země Uz, všecky také krále země Filistinské, i Aškalon, i Gázy, i Akaron, i ostatek Azotu,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 21, 'Idumejské, i Moábské, i syny Ammon,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 22, 'I všecky krále Tyrské, i všecky krále Sidonské, i krále krajiny té, kteráž jest při moři,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 23, 'Dedana a Temu, a Buzu i všecky přebývající v koutech nejzadnějších,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 24, 'I všecky krále Arabské, i všecky krále té směsice, kteříž bydlí na poušti,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 25, 'Všecky také krále Zamritské, i všecky krále Elamitské, též všecky krále Médské,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 26, 'Anobrž všecky krále půlnoční, blízké i daleké, jednoho jako druhého, všecka také království země, kterážkoli jsou na svrchku země. Král pak Sesák píti bude po nich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 27, 'A rci jim: Takto praví Hospodin zástupů, Bůh Izraelský: Pítež a opojte se, anobrž vyvracejte z sebe, a padejte, tak abyste nepovstali pro meč, kterýž já pošli mezi vás.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 28, 'Jestliže by pak nechtěli vzíti kalichu z ruky tvé, aby pili, tedy díš jim: Takto praví Hospodin zástupů: Konečně že píti musíte.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 29, 'Nebo poněvadž na to město, kteréž nazváno jest od jména mého, já začínám uvozovati zlé věci, a vy abyste bez hodné pomsty byli? Nebudete bez pomsty, nebo já zavolám meče na všecky obyvatele té země, dí Hospodin zástupů.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 30, 'Protož ty prorokuj proti nim všecka slova tato, a rci jim: Hospodin s výsosti řváti bude, a z příbytku svatosti své vydá hlas svůj, mocně řváti bude z obydlí svého. Křik ponoukajících se, jako presovníků, rozléhati se bude proti všechněm obyvatelům té země,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 31, 'I průjde hřmot až do konce země. Nebo rozepři má Hospodin s těmi národy, v soud vchází sám se všelikým tělem; bezbožníky vydá pod meč, dí Hospodin.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 32, 'Takto praví Hospodin zástupů: Aj, bída půjde z národu na národ, a vichřice veliká strhne se od končin země.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 33, 'I budou zbiti od Hospodina v ten čas od konce země až do konce země; nebudou oplakáni, ani sklizeni, ani pochováni, místo hnoje na svrchku země budou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 34, 'Kvělte pastýři a křičte, anobrž válejte se v popele, vy nejznamenitější toho stáda; nebo naplnili se dnové vaši, abyste zbiti byli, a abyste rozptýleni byli, i budete padati jako nádoba drahá.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 35, 'I zahyne útočiště pastýřům a utíkání nejznamenitějším toho stáda.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 36, 'Hlas žalostný pastýřů a kvílení nejznamenitějších toho stáda; nebo zkazí Hospodin pastvu jejich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 37, 'Zkažena budou i pastviska pokoj mající, pro prchlivost hněvu Hospodinova,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 38, 'Jako lev opustí jeskyni svou; nebo přijde země jejich na spuštění, pro prchlivost zhoubce a pro prchlivost hněvu jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 1, 'Na počátku kralování Joakima syna Joziášova, krále Judského, stalo se slovo toto od Hospodina, řkoucí:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 2, 'Takto praví Hospodin: Postav se v síňci domu Hospodinova, a mluv ke všechněm městům Judským, přicházejícím klaněti se v domě Hospodinově, všecka slova, kteráž tobě přikazuji mluviti k nim, neujímejž slova,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 3, 'Zdali by aspoň uposlechli, a odvrátili se jeden každý od cesty své zlé, abych litoval zlého kteréž myslím učiniti jim pro nešlechetnost předsevzetí jejich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 4, 'Rciž tedy jim: Takto praví Hospodin: Neuposlechnete-li mne, abyste chodili v zákoně mém, kterýž jsem předložil vám,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 5, 'Poslouchajíce slov služebníků mých proroků, kteréž já posílám k vám, jakož jste, když jsem je, ráno přivstávaje posílal, neposlouchali:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 6, 'Jistě žeť naložím s domem tímto jako s Sílo, a město toto vydám v proklínání všechněm národům země.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 7, 'Slyšeli pak kněží a proroci, i všecken lid Jeremiáše mluvícího slova ta v domu Hospodinovu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 8, 'I stalo se, že hned, jakž přestal Jeremiáš mluviti všeho, cožkoli přikázal Hospodin mluviti ke všemu lidu, jali jej ti kněží a proroci i všecken lid ten, řkouce: Smrtí umřeš.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 9, 'Proč jsi prorokoval ve jménu Hospodinovu, řka: Stane se jako Sílo domu tomuto, a město toto tak spustne, že nebude v něm žádného obyvatele? Shromažďoval se pak všecken lid k Jeremiášovi do domu Hospodinova.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 10, 'Tedy uslyšavše knížata Judská ty věci, přišli z domu královského do domu Hospodinova, a posadili se u dveří brány Hospodinovy nové.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 11, 'I řekli kněží a proroci těm knížatům a všemu lidu, řkouce: Hoden jest smrti muž tento; nebo prorokoval proti městu tomuto, jakž jste slyšeli v své uši.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 12, 'Tedy promluvil Jeremiáš ke všechněm knížatům těm i ke všemu lidu, řka: Hospodin poslal mne, abych prorokoval o domu tomto i o městě tomto všecky ty věci, kteréž jste slyšeli.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 13, 'Protož nyní polepšte cest svých a předsevzetí svých, a poslouchejte hlasu Hospodina Boha svého, i bude litovati Hospodin toho zlého, kteréž vyřkl proti vám.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 14, 'Já pak aj, v rukou vašich jsem, učiňte mi, což se vám za dobré a spravedlivé vidí.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 15, 'Ale však jistotně vězte, usmrtíte-li mne, že krev nevinnou na sebe uvedete, i na město toto, i na obyvatele jeho; nebo v pravdě poslal mne Hospodin k vám, abych mluvil v uši vaše všecka slova tato.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 16, 'I řekli knížata i všecken lid kněžím a těm prorokům: Nemáť nikoli muž tento odsuzován býti na smrt, poněvadž ve jménu Hospodina Boha našeho mluvil nám.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 17, 'Tedy povstali někteří z starších té země, a promluvili ke všemu shromáždění lidu, řkouce:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 18, 'Micheáš Moraštický prorokoval za času Ezechiáše krále Judského, a pravil všemu lidu Judskému, řka: Takto praví Hospodin zástupů: Sion jako pole orán bude, a Jeruzalém jako hromady, hora pak domu tohoto jako lesové vysocí.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 19, 'Zdaliž hned proto usmrtil jej Ezechiáš král Judský a všecken Juda? Zdaliž neulekl se Hospodina, a nemodlil se Hospodinu? I litoval Hospodin toho zlého, kteréž vyřkl proti nim. Protož my činíme velmi zlou věc proti dušem svým.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 20, 'A byl také muž prorokující ve jménu Hospodinovu, Uriáš syn Semaiášův z Kariatjeharim, kterýž prorokoval o městě tomto i o zemi této v táž všecka slova jako Jeremiáš.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 21, 'A když uslyšel král Joakim a všickni udatní jeho, i všecka knížata slova jeho, hned usiloval král usmrtiti jej. O čemž uslyšev Uriáš, bál se, a utíkaje, přišel do Egypta.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 22, 'Ale poslal král Joakim některé do Egypta, Elnatana syna Achborova i jiné s ním do Egypta.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 23, 'Kteříž vyvedše Uriáše z Egypta, přivedli jej k králi Joakimovi. I zabil jej mečem, a vhodil tělo jeho do hrobů lidu obecného.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 24, 'A však ruka Achikamova syna Safanova byla při Jeremiášovi, aby ho nevydával v ruku lidu k usmrcení jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 1, 'Na počátku kralování Joakima syna Joziášova, krále Judského, stalo se slovo toto k Jeremiášovi od Hospodina, řkoucí:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 2, 'Takto řekl Hospodin ke mně: Zdělej sobě oboječky a jha, a dej je na šíji svou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 3, 'Potom je pošli k králi Idumejskému, a k králi Moábskému, a k králi synů Ammonových, a k králi Tyrskému, a k králi Sidonskému po těch poslích, kteříž přijedou do Jeruzaléma k Sedechiášovi králi Judskému.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 4, 'A přikaž jim, ať pánům svým řeknou: Takto praví Hospodin zástupů, Bůh Izraelský: Tak rcete pánům svým:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 5, 'Já jsem učinil zemi, člověka i hovada, kterážkoli jsou na svrchku země, mocí svou velikou a ramenem svým vztaženým. Protož dávám ji, komuž se mi dobře líbí.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 6, 'Jako nyní já dal jsem všecky země tyto v ruku Nabuchodonozora krále Babylonského, služebníka svého, ano i živočichy polní dal jsem jemu, aby sloužili jemu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 7, 'Protož budouť sloužiti jemu všickni ti národové, i synu jeho, i synu syna jeho, dokudž by nepřišel čas země jeho i jeho samého, když v službu podrobí jej sobě národové znamenití a králově velicí.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 8, 'Stane se pak, že národ ten i království to, kteréž by nesloužilo jemu, Nabuchodonozorovi králi Babylonskému, a kterýž by nepoddal šíje své pod jho krále Babylonského, mečem a hladem i morem navštívím národ ten, dí Hospodin, dokudž bych do konce nevyplénil jich rukou jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 9, 'Protož vy neposlouchejte proroků svých, ani hadačů svých, ani snů svých, ani planetářů svých, ani kouzedlníků svých, kteříž mluvívají k vám, říkajíce: Nebudete sloužiti králi Babylonskému.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 10, 'Nebo oni vám lež prorokují, abych vzdálil vás od země vaší, a vyhnal vás, abyste zahynuli.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 11, 'Národu pak, kterýž skloní šíji svou pod jho krále Babylonského a sloužiti bude jemu, toho zajisté nechám v zemi jeho, dí Hospodin, aby dělal ji, a bydlil v ní.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 12, 'Sedechiášovi také, králi Judskému, mluvil jsem naskrze ta všecka slova, řka: Skloňte šíje své pod jho krále Babylonského, a služte jemu i lidu jeho, a buďte živi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 13, 'Proč máte zahynouti, ty i lid tvůj, mečem, hladem a morem, jakž mluvil Hospodin o národu, kterýž by nesloužil králi Babylonskému?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 14, 'Neposlouchejtež tedy slov proroků těch, kteříž mluvíce k vám, říkají: Nebudete sloužiti králi Babylonskému. Nebo oni vám lež prorokují.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 15, 'Neposlalť jsem jich zajisté, dí Hospodin, a však oni prorokují ve jménu mém lživě, abych zahnal vás, kdež byste zahynuli vy i ti proroci, kteříž prorokují vám.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 16, 'Kněžím také i všemu lidu tomu mluvil jsem, řka: Takto praví Hospodin: Neposlouchejte slov proroků svých, kteříž prorokují vám, říkajíce: Aj, nádobí domu Hospodinova navrácena budou z Babylona již brzo. Neboť lež oni prorokují vám.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 17, 'Neposlouchejtež jich, služte králi Babylonskému a živi buďte. Proč má býti toto město pouští?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 18, 'Jestliže pak oni jsou proroci, a jestliže slovo Hospodinovo jest v nich, nechť se medle přimluví k Hospodinu zástupů, ať nádobí to, pozůstávající v domě Hospodinově a v domě krále Judského a v Jeruzalémě, nedostává se do Babylona.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 19, 'Nebo takto praví Hospodin zástupů o těch sloupích, a o tom moři, a o těch podstavcích, i o ostatku nádobí pozůstávajícím v městě tomto,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 20, 'Kteréhož nepobral Nabuchodonozor král Babylonský, když přestěhoval Jekoniáše syna Joakimova, krále Judského, z Jeruzaléma do Babylona, a všecky nejpřednější Judské i Jeruzalémské,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 21, 'Takto zajisté dí Hospodin zástupů, Bůh Izraelský, o těch nádobách, pozůstávajících v domě Hospodinově a v domě krále Judského i v Jeruzalémě:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 22, 'Do Babylona zavezeny budou, a tam budou až do dne toho, v němž je navštívím, dí Hospodin, a rozkáži je přivezti, a zase navrátím je na místo toto.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 1, 'Stalo se pak léta toho, na počátku kralování Sedechiáše krále Judského, léta totiž čtvrtého, měsíce pátého, mluvil ke mně Chananiáš syn Azurův, prorok, kterýž byl z Gabaon, v domě Hospodinově, před očima kněží i všeho lidu, řka:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 2, 'Takto praví Hospodin zástupů, Bůh Izraelský, řka: Polámal jsem jho krále Babylonského.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 3, 'Po dvou letech já navrátím zase na místo toto všecka nádobí domu Hospodinova, kteráž pobral Nabuchodonozor král Babylonský z místa tohoto, a zavezl je do Babylona.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 4, 'Jekoniáše také syna Joakimova, krále Judského, i všecky zajaté Judské, kteříž se dostali do Babylona, já zase přivedu na místo toto, dí Hospodin; nebo polámi jho krále Babylonského.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 5, 'Tedy řekl Jeremiáš prorok Chananiášovi proroku tomu před očima kněží a před očima všeho lidu, kteříž stáli v domě Hospodinově,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 6, 'Řekl, pravím, Jeremiáš prorok: Amen, učiniž tak Hospodin. Potvrdiž Hospodin slov tvých, kteráž jsi prorokoval o navrácení nádobí domu Hospodinova, a všech zajatých z Babylona na místo toto.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 7, 'Ale však poslechni medle slova tohoto, kteréž já mluvím při tvé přítomnosti a při přítomnosti všeho tohoto lidu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 8, 'Proroci, kteříž bývali přede mnou i před tebou od věků, ti prorokovali proti zemím znamenitým a proti královstvím velikým o válce a o ssoužení a o moru.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 9, 'Prorok ten, kterýž prorokuje o pokoji, když dojde slovo toho proroka, ten prorok znám bývá, že jej poslal Hospodin v pravdě.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 10, 'Tedy sňal Chananiáš prorok to jho z šíje Jeremiáše proroka, a polámal je.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 11, 'A mluvil Chananiáš před očima všeho lidu, řka: Takto praví Hospodin: Tak polámi jho Nabuchodonozora krále Babylonského po dvou letech z šíje všech národů. I počal jíti Jeremiáš prorok cestou svou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 12, 'Ale stalo se slovo Hospodinovo k Jeremiášovi, když polámal Chananiáš prorok to jho z šíje Jeremiáše proroka, řkoucí:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 13, 'Jdi a mluv k Chananiášovi, řka: Takto praví Hospodin: Jha dřevěná jsi polámal, protož zdělej místo nich jha železná.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 14, 'Nebo takto praví Hospodin zástupů, Bůh Izraelský: Jho železné vložím na šíji všech národů těchto, aby sloužili Nabuchodonozorovi králi Babylonskému, a budouť sloužiti jemu. Také i živočichy polní dám jemu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 15, 'Zatím řekl Jeremiáš prorok Chananiášovi proroku: Slyšiž nyní, Chananiáši: Neposlal tebe Hospodin, ale ty jsi k tomu přivedl, aby lid tento ve lži skládal doufání.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 16, 'Protož takto praví Hospodin: Aj, já sklidím tě se svrchku země, tento rok ty umřeš; nebo jsi mluvil to, čímž bys odvrátil lid od Hospodina.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 17, 'I umřel Chananiáš prorok roku toho měsíce sedmého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 1, 'Tato jsou slova listu, kterýž poslal Jeremiáš prorok z Jeruzaléma k ostatku starších zajatých a k kněžím i k prorokům i ke všemu lidu, kterýž přestěhoval Nabuchodonozor z Jeruzaléma do Babylona,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 2, 'Když vyšel Jekoniáš král a královna, i komorníci, knížata Judská i Jeruzalémská, tolikéž tesaři i kováři z Jeruzaléma,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 3, 'Po Elasovi synu Safanovu, a Gemariášovi synu Helkiášovu, (kteréž byl poslal Sedechiáš král Judský k králi Babylonskému do Babylona), řka:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 4, 'Takto praví Hospodin zástupů, Bůh Izraelský, všechněm zajatým, kteréž jsem přestěhoval z Jeruzaléma do Babylona:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 5, 'Stavějte domy, a osazujte se, štěpujte také štěpnice, a jezte ovoce jejich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 6, 'Pojímejte ženy, a ploďte syny i dcery, dávejte také synům svým ženy, dcery též své dávejte za muže, ať rodí syny a dcery; množte se tam, a nebeřte umenšení.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 7, 'A hledejte pokoje města toho, do kteréhož jsem zastěhoval vás, a modlívejte se za ně Hospodinu; nebo v pokoji jeho budete míti pokoj.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 8, 'Takto zajisté praví Hospodin zástupů, Bůh Izraelský: Nechť vás nesvodí proroci vaši, kteříž jsou mezi vámi, ani hadači vaši, a nespravujte se sny svými, jichž vy příčinou jste, aby je mívali.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 9, 'Nebo vám oni lživě prorokují ve jménu mém; neposlalť jsem jich, dí Hospodin.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 10, 'Takto zajisté praví Hospodin: Že jakž se jen vyplní Babylonu sedmdesáte let, navštívím vás, a potvrdím vám slova svého výborného o navrácení vás na místo toto.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 11, 'Nebo já nejlépe znám myšlení, kteráž myslím o vás, dí Hospodin, myšlení o pokoji, a ne o trápení, abych učinil vašemu očekávání konec přežádostivý.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 12, 'Když mne vzývati budete, a půjdete, a modliti se mně budete, tedy vyslyším vás.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 13, 'A hledajíce mne, naleznete, když mne hledati budete celým srdcem svým.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 14, 'Dám se zajisté nalezti vám, dí Hospodin, a přivedu zase zajaté vaše, a shromáždím vás ze všech národů i ze všech míst, kamžkoli jsem zahnal vás, dí Hospodin, a uvedu vás zase na místo toto, odkudž jsem vás zastěhoval,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 15, 'Když řeknete: Vzbuzovalť nám Hospodin proroky v Babyloně.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 16, 'Nebo takto praví Hospodin o králi sedícím na stolici Davidově, a o všem lidu obývajícím v městě tomto, bratřích vašich, kteříž nevyšli s vámi v tom zajetí,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 17, 'Takto dí Hospodin zástupů: Aj, já pošli na ně meč, hlad a mor, a naložím s nimi jako s fíky trpkými, kterýchž nelze jísti pro trpkost.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 18, 'Nebo stihati je budu mečem, hladem i morem, a vydám je ku posmýkání po všech královstvích země, k proklínání, a k užasnutí, anobrž na odivu, a k utrhání mezi všemi národy, tam kdež je vypudím,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 19, 'Proto že neposlouchají slov mých, dí Hospodin, když posílám k nim služebníky své proroky, ráno přivstávaje, a to ustavičně, a neposlouchali jste, dí Hospodin.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 20, 'Protož slyštež vy slovo Hospodinovo, všickni zajatí, kteréž jsem vyslal z Jeruzaléma do Babylona.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 21, 'Takto praví Hospodin zástupů, Bůh Izraelský, o Achabovi synu Kolaiášovu, a o Sedechiášovi synu Maaseiášovu, kteříž prorokují vám ve jménu mém lež: Aj, já vydám je v ruku Nabuchodonozora krále Babylonského, aby je zbil před očima vašima.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 22, 'I bude vzato na nich klnutí mezi všecky zajaté Judské, kteříž jsou v Babyloně, aby říkali: Nechť nakládá Hospodin s tebou, jako s Sedechiášem a jako s Echabem, kteréž upekl král Babylonský na ohni,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 23, 'Proto že páchali nešlechetnost v Izraeli, cizoložíce s ženami bližních svých, a mluvíce slovo ve jménu mém lživě, čehož jsem nepřikázal jim. Já pak o tom vím, a jsem toho i svědkem, dí Hospodin.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 24, 'Semaiášovi Nechelamitskému mluv, řka:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 25, 'Takto praví Hospodin zástupů, Bůh Izraelský, řka: Proto že jsi poslal jménem svým listy ke všemu lidu, kterýž jest v Jeruzalémě, a Sofoniášovi synu Maaseiášovu knězi i ke všechněm kněžím, řka:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 26, 'Hospodin dal tě za kněze na místo Joiady kněze, abyste pozor měli v domě Hospodinově na každého muže pošetilého a vystavujícího se za proroka, a abys dal takového do žaláře a do klady.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 27, 'Pročež jsi pak nyní neokřikl Jeremiáše Anatotského, kterýž se vám vystavuje za proroka?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 28, 'Nebo posílal k nám do Babylona, řka: Protáhneť se to dlouho, stavějte domy, a osazujte se, štěpujte také štěpnice, a jezte ovoce jejich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 29, 'Nebo Sofoniáš kněz četl ten list před Jeremiášem prorokem.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 30, 'I stalo se slovo Hospodinovo k Jeremiášovi, řkoucí:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 31, 'Pošli ke všechněm zajatým, řka: Takto praví Hospodin o Semaiášovi Nechelamitském: Proto že prorokuje vám Semaiáš, ješto jsem já ho neposlal, a přivodí vás k tomu, abyste doufání skládali ve lži,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 32, 'Protož takto praví Hospodin: Aj, já trestati budu Semaiáše Nechelamitského i símě jeho. Nebude míti žádného, kdo by bydlil u prostřed lidu tohoto, aniž uzří toho dobrého, kteréž já učiním lidu svému, dí Hospodin; nebo mluvil to, čímž by odvrátil lid od Hospodina.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 1, 'Slovo, kteréž se stalo k Jeremiášovi od Hospodina, řkoucí:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 2, 'Takto praví Hospodin, Bůh Izraelský, řka: Spiš sobě do knihy všecka slova, kterážť jsem mluvil.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 3, 'Aj, dnové zajisté jdou, dí Hospodin, přivedu zase zajaté lidu svého Izraelského i Judského, praví Hospodin, a uvedu je do země, kterouž jsem byl dal otcům jejich, a dědičně ji obdrží,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 4, 'Tatoť pak jsou slova, kteráž mluvil Hospodin o Izraelovi a Judovi:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 5, 'Takto zajisté praví Hospodin: Hlas předěšení a hrůzy slyšíme, a že není žádného pokoje.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 6, 'Ptejte se nyní, a vizte rodívá-li samec. Pročež tedy vidím, an každý muž rukama svýma drží se za bedra svá jako rodička, a obrácené všechněch oblíčeje v zsinalost?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 7, 'Ach, nebo veliký jest den tento, tak že nebylo žádného jemu podobného. Ale jakť koli čas jest ssoužení Jákobova, předceť z něho vysvobozen bude.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 8, 'Stane se zajisté v ten den, dí Hospodin zástupů, že polámi jho jeho z šíje tvé, a svazky tvé potrhám, i nebudou ho více v službu podrobovati cizozemci.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 9, 'Ale sloužiti budou Hospodinu Bohu svému, a Davidovi králi svému, kteréhož jim vzbudím.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 10, 'Protož ty neboj se, služebníče můj Jákobe, dí Hospodin, aniž se strachuj, ó Izraeli, nebo aj, já vysvobodím tě zdaleka, i símě tvé z země zajetí jejich. I navrátí se Jákob, aby odpočíval, a pokoj měl, a nebude žádného, kdo by jej předěsil.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 11, 'Neboť já s tebou jsem, dí Hospodin, abych tě vysvobodil, když učiním konec všechněm národům, mezi kteréž tě rozptýlím. Tobě však neučiním konce, ale budu tě trestati v soudu, ačkoli tě bez trestání naprosto nenechám.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 12, 'Takto zajisté praví Hospodin: Přetěžké bude potření tvé, přebolestná rána tvá.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 13, 'Nebude, kdo by přisoudil při tvou k uléčení; lékařství platného žádného míti nebudeš.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 14, 'Všickni, kteříž tě milují, zapomenou se nad tebou, aniž tě navštíví, když tě raním ranou nepřítele, a trestáním přísným pro mnohou nepravost tvou a nesčíslné hříchy tvé.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 15, 'Proč křičíš nad svým potřením a těžkou bolestí svou? Pro mnohou nepravost tvou a nesčíslné hříchy tvé to činím tobě.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 16, 'A však všickni, kteříž zžírají tebe, sežráni budou, a všickni, kteříž utiskají tebe, všickni, pravím, do zajetí půjdou, a kteříž tě pošlapávají, pošlapáni budou, a všecky, kteříž tě loupí, v loupež vydám,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 17, 'Tehdáž když tobě navrátím zdraví, a na rány tvé zhojím tě, dí Hospodin, proto že zahnanou nazývali tebe, říkajíce: Tato jest Sion, není žádného, kdo by ji navštívil.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 18, 'Takto praví Hospodin: Aj, já zase přivedu zajaté stánků Jákobových, a nad příbytky jeho slituji se, i budeť zase vzděláno město na prvním místě svém, a palác podlé způsobu svého vystaven.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 19, 'A bude pocházeti od nich díků činění a hlas veselících se; nebo je rozmnožím, a nebudou umenšení bráti, zvelebím je, a nebudou sníženi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 20, 'A budou synové jeho tak jako i prvé, a shromáždění jeho přede mnou utvrzeno bude, trestati pak budu všecky, kteříž jej ssužují.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 21, 'A povstane z něho nejdůstojnější jeho, a panovník jeho z prostředku jeho vyjde, kterémuž rozkáži přiblížiti se, aby předstoupil přede mne. Nebo kdo jest ten, ješto by slíbil za sebe, že předstoupí přede mne? dí Hospodin.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 22, 'I budete mým lidem, a já budu vaším Bohem.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 23, 'Aj, vicher Hospodinův s prchlivostí vyjde, vicher trvající nad hlavou nešlechetných trvati bude.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 24, 'Neodvrátíť se prchlivost hněvu Hospodinova, dokudž neučiní toho, a dokudž nevykoná úmyslu srdce svého. Tehdáž porozumíte tomu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 1, 'Toho času, dí Hospodin, budu Bohem všech čeledí Izraelových, a oni budou mým lidem.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 2, 'Takto praví Hospodin: Lid z těch pozůstalých po meči nalezl milost na poušti, když jsem chodil před ním, abych odpočinutí způsobil Izraelovi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 3, 'Za starodávnať se mi ukazoval Hospodin. I však milováním věčným miluji tě, pročež ustavičně činím tobě milosrdenství.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 4, 'Ještě vždy vzdělávati tě budu, a vzdělána budeš, panno Izraelská; ještě se obveselovati budeš bubny svými, a vycházeti s houfem plésajících.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 5, 'Ještě štěpovati budeš vinice v horách Samařských, štěpovati budou štěpaři i jísti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 6, 'Nebo nastane den, v němž volati budou strážní na hoře Efraimově: Vstaňte a vstupme na Sion k Hospodinu Bohu svému.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 7, 'Takto zajisté praví Hospodin: Prozpěvujte Jákobovi o věcech veselých, prokřikujte zjevně před těmi národy; dejte se slyšeti, chválu vzdávejte, a rcete: Vysvoboď, Hospodine, ostatek lidu svého Izraelského.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 8, 'Aj, já přivedu je z země půlnoční, a shromáždím je ze všech stran země, s nimi spolu slepého i kulhavého, těhotnou i rodící; shromáždění veliké sem se navrátí.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 9, 'Kteréžto s pláčem jdoucí a s pokornými modlitbami zase přivedu, a povedu je podlé tekutých vod cestou přímou, na níž by se nepoklesli; neboť jsem Izraelův otec, a Efraim jest prvorozený můj.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 10, 'Slyšte slovo Hospodinovo, ó národové, a zvěstujte na ostrovích dalekých, a rcete: Ten, kterýž rozptýlil Izraele, shromáždí jej, a ostříhati ho bude jako pastýř stáda svého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 11, 'Neboť vykoupil Hospodin Jákoba, protož vysvobodí jej z ruky toho, kterýž silnější jest nad něj.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 12, 'I přijdou, a prozpěvovati budou na výsosti Siona, a pohrnou se k dobrotě Hospodinově s obilím, a s vínem, a s olejem, a s plodem skotů a bravů, duše pak jejich bude podobná zahradě svlažené, a nebudouť se rmoutiti více.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 13, 'Tehdáž veseliti se bude panna s plésáním, a mládenci i starci spolu; obrátím zajisté kvílení jejich v radost, a potěším jich, a obveselím je po zámutku jejich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 14, 'Rozvlažím i duši kněží tukem, a lid můj dobroty mé nasytí se, dí Hospodin.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 15, 'Takto praví Hospodin: Hlas v Ráma slyšán jest, naříkání a pláč přehořký. Ráchel plačeci synů svých, nedala se potěšiti po synech svých, proto že žádného není.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 16, 'Takto praví Hospodin: Zdrž hlas svůj od pláče, a oči své od slz, nebo budeš míti mzdu za práci svou, praví Hospodin, že se navrátí z země nepřátelské.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 17, 'Jest, pravím, čáka, žeť se potom, dí Hospodin, navrátí synové do svého kraje.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 18, 'V pravdě slyším Efraima, an sobě stýště, pravě: Trestals mne, abych strestán byl jako telátko neupřáhané; obrať mne, abych obrácen byl, ty jsi zajisté, Hospodine, Bůh můj.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 19, 'Nebo po obrácení svém pokání činiti budu, a když mi k známosti sebe poslouženo bude, udeřím se v bedra. Stydímť se, anobrž i pýřím, že snáším útržku dětinství svého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 20, 'Zdali Efraim jest mým synem milým, aneb dítě velmi milostné? A však jakž jsem mluvil proti němu, ustavičně se vždy na něj rozpomínám. Pročež pohybují se vnitřnosti mé příčinou jeho; jistě žeť se slituji nad ním, dí Hospodin.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 21, 'Nastavěj sobě pamětných znamení, naklaď sobě hromad kamení, pamatuj na tu silnici a cestu, kterouž jsi šla; navrať se, panno Izraelská, navrať se k městům svým těmto.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 22, 'Dokudž se toulati budeš, ó dcero zpurná? Neboť učiní Hospodin novou věc na zemi: Žena bude vůkol obcházeti muže.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 23, 'Takto praví Hospodin zástupů, Bůh Izraelský: Ještěť říkati budou slovo toto v zemi Judově a v městech jeho, když zase přivedu zajaté jejich: Požehnejž tobě Hospodin, ó příbytku spravedlnosti, horo svatosti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 24, 'Nebo osazovati se budou v zemi Judské, ve všech městech jeho spolu oráči, a kteříž zacházejí s stádem.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 25, 'Rozvlažím zajisté duši ustalou, a všelikou duši truchlou nasytím.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 26, 'V tom jsem procítil, a ohlédl se, a ten můj sen byl mi vděčný.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 27, 'Aj, dnové jdou, dí Hospodin, v nichžto oseji dům Izraelský a dům Judský semenem lidským a semenem hovad.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 28, 'I stane se, že jakož jsem se snažoval, abych je plénil, a bořil, a kazil a hubil, a trápil, tak se snažím, abych je vzdělal a rozsazoval, dí Hospodin.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 29, 'Těch časů nebudou říkati více: Otcové jedli hrozen trpký, pročež zubové synů laskominy mají,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 30, 'Nýbrž raději: Jeden každý pro nepravost svou umře. Každého člověka, kterýž by jedl hrozen trpký, laskominy míti budou zubové jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 31, 'Aj, dnové jdou, dí Hospodin, v nichž učiním s domem Izraelským a s domem Judským smlouvu novou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 32, 'Ne takovou smlouvu, jakouž jsem učinil s otci jejich v ten den, v kterýž jsem je ujal za ruku jejich, abych je vyvedl z země Egyptské. Kteroužto smlouvu mou oni zrušili, a já abych zůstati měl manželem jejich? dí Hospodin.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 33, 'Ale tatoť jest smlouva, kterouž učiním s domem Izraelským po těchto dnech, dí Hospodin: Dám zákon svůj do vnitřnosti jejich, a na srdci jejich napíši jej; i budu Bohem jejich, a oni budou mým lidem.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 34, 'A nebudou učiti více jeden každý bližního svého, a jeden každý bratra svého, říkajíce: Poznejte Hospodina. Všickni zajisté napořád znáti mne budou, od nejmenšího z nich až do největšího z nich, dí Hospodin; milostiv zajisté budu nepravosti jejich, a na hřích jejich nezpomenu více.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 35, 'Takto praví Hospodin, kterýž dává slunce za světlo ve dne, zřízení měsíce a hvězd za světlo v noci, kterýž rozděluje moře, a zvučí vlnobití jeho, jehož jméno jest Hospodin zástupů:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 36, 'Jestliže se pohnou ta nařízení před oblíčejem mým, dí Hospodin, takéť símě Izraelovo přestane býti národem před oblíčejem mým po všecky dny.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 37, 'Takto praví Hospodin: Budou-li moci býti změřena nebesa zhůru, a vyhledáni základové země dolů, takéť já zavrhu docela símě Izraelovo pro všecko to, což činili, dí Hospodin.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 38, 'Aj, dnové jdou, dí Hospodin, v nichž vystaveno bude město toto Hospodinu, od věže Chananeel až k bráně úhlu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 39, 'A půjde ještě šňůra měřící naproti ní, ku pahrbku Gareb, a přitočí se k Gou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 40, 'A všecko údolí těl mrtvých a popela, i všecko to pole až ku potoku Cedron, až k úhlu brány východní koňské posvěcené bude Hospodinu; nebudeť pléněno, ani kaženo více na věky.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 1, 'Slovo, kteréž se stalo k Jeremiášovi od Hospodina léta desátého Sedechiáše krále Judského, kterýžto rok jest osmnáctý Nabuchodonozorův.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 2, '(Bylo pak tehdáž vojsko krále Babylonského oblehlo Jeruzalém, a Jeremiáš prorok byl zavřín v síni stráže, kteráž byla v domě krále Judského.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 3, 'Nebo dal jej byl vsaditi Sedechiáš král Judský, řka: Proč ty prorokuješ, právě: Takto praví Hospodin: Aj, já dám město toto v ruku krále Babylonského, aby je vzal.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 4, 'Sedechiáš také král Judský neznikne ruky Kaldejských, ale jistotně vydán bude v ruku krále Babylonského, a budou mluviti ústa jeho s ústy jeho, a oči jeho uzří oči jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 5, 'Nýbrž do Babylona zavede Sedechiáše, aby tam byl, až ho navštívím, dí Hospodin. Poněvadž bojujete s Kaldejskými, nepovede se vám šťastně.)');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 6, 'Tehdy řekl Jeremiáš: Stalo se slovo Hospodinovo ke mně, řkoucí:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 7, 'Aj, Chanameel syn Salluma, strýce tvého, jde k tobě, aťby řekl: Kup sobě dvůr můj, kterýž jest v Anatot; nebo tobě právem příbuznosti náleží koupiti jej.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 8, 'Když pak přišel ke mně Chanameel syn strýce mého, podlé slova Hospodinova, do síně stráže, a řekl ke mně: Kup medle dvůr můj, kterýž jest v Anatot, jenž jest v zemi Beniaminově; nebo tvůj jest právem dědičným, a právem příbuznosti, kupiž jej sobě: tedy porozuměv, že jest to slovo Hospodinovo,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 9, 'I koupil jsem od Chanameele syna strýce svého ten dvůr, kterýž jest v Anatot, a odvážil jsem jemu peněz sedmnácte lotů stříbra.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 10, 'A zapsav to do cedule, zapečetil jsem, a osvědčil jsem svědky, odváživ peníze na váze.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 11, 'Potom vzal jsem, podlé přikázaní a ustanovení, cedule té koupě zapečetěnou i otevřenou,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 12, 'A dal jsem ceduli té koupě Báruchovi synu Neriášovu, synu Maaseiášovu, před očima Chanameele strýce svého, a před očima svědků, kteříž se podepsali v ceduli té koupě, před očima všech Judských, kteříž se byli posadili v síni stráže.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 13, 'A přikázal jsem Báruchovi před očima jejich, řka:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 14, 'Takto praví Hospodin zástupů, Bůh Izraelský: Vezmi cedule tyto, tuto ceduli té koupě, jakož zapečetěnou, tak ceduli otevřenou tuto, a vlož je do nádoby hliněné, aby trvaly za mnohá léta.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 15, 'Nebo takto praví Hospodin zástupů, Bůh Izraelský: Ještěť kupováni budou domové, a rolí, i vinice v zemi této.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 16, 'Potom modlil jsem se Hospodinu, když jsem dal ceduli té koupě Báruchovi synu Neriášovu, řka:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 17, 'Ach, Panovníče Hospodine, aj, ty jsi učinil nebe i zemi mocí svou velikou a ramenem svým vztaženým, nemůžeť skryta býti před tebou žádná věc.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 18, 'Činíš milosrdenství nad tisíci, a odplacíš za nepravost otců do lůna synů jejich po nich, Bůh veliký, silný, mocný, jehož jméno Hospodin zástupů,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 19, 'Veliký v radě a znamenitý v správě, poněvadž oči tvé otevřené jsou na všecky cesty synů lidských, abys odplatil jednomu každému podlé cest jeho, a podlé ovoce předsevzetí jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 20, 'Kterýž jsi činil divy a zázraky v zemi Egyptské až do tohoto dne, jakož v Izraelovi tak mezi jinými lidmi, a dobyls sobě jména, jakéž jest po dnešní den.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 21, 'Nebo vyvedl jsi lid svůj Izraelský z země Egyptské v divích a v zázracích, a rukou silnou, a ramenem vztaženým, a v strachu velikém,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 22, 'A dals jim zemi tuto, kterouž jsi přisáhl dáti otcům jejich, zemi oplývající mlékem a strdí.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 23, 'Ale že všedše do ní, a dědičně ujavše ji, neposlouchali hlasu tvého, a v zákoně tvém nechodili, všeho, což jsi koli přikázal jim činiti, nečinili, protož způsobils to, aby je potkalo všecko toto zlé.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 24, 'Aj, střelci přitáhli na město, aby je vzali, a město skrze meč a hlad a mor dáno jest v ruku Kaldejských, bojujících proti němu; a tak, což jsi koli promluvil, děje se, jakž to sám vidíš.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 25, 'Ty pak pravíš mi, Panovníče Hospodine: Zjednej sobě dvůr tento za peníze, a osvědč to svědky, ano již město toto dáno jest v ruku Kaldejských.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 26, 'I stalo se slovo Hospodinovo k Jeremiášovi, řkoucí:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 27, 'Aj, já jsem Hospodin Bůh všelikého těla, zdaliž přede mnou může býti skryta která věc?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 28, 'Protož takto praví Hospodin: Aj, já dávám toto město v ruku Kaldejských a v ruku Nabuchodonozora krále Babylonského, aby je vzal.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 29, 'A vejdouce Kaldejští, kteříž bojují proti městu tomuto, zapálí ohněm toto město, a vypálí je, i domy ty, na jejichž střechách kadívali Bálovi, a obětovali oběti mokré bohům cizím, aby mne hněvali.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 30, 'Nebo synové Izraelští a synové Judští od dětinství svého jen toliko činí to, což jest zlého před očima mýma; synové, pravím, Izraelští jen toliko hněvají mne dílem rukou svých, dí Hospodin.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 31, 'Toto zajisté město od toho dne, jakž je vystavěli, až do tohoto dne k hněvu mému a prchlivosti mé popouzí mne, tak že je sklidím od tváři své,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 32, 'Pro všelikou nešlechetnost synů Izraelských a synů Judských, kterouž páchali, aby mne k hněvu popouzeli, oni, králové jejich, knížata jejich, kněží jejich i proroci jejich, jakož muži Judští, tak obyvatelé Jeruzalémští,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 33, 'Obracejíce se ke mně hřbetem, a ne tváří. A když je učím, ráno přivstávaje, a to ustavičně, však nikoli neposlouchají, aby přijímali naučení.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 34, 'Nadto nastavěli ohavností svých v domě tom, kterýž nazván jest od jména mého, aby jej zanečistili.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 35, 'Nastavěli, pravím, výsostí Bálovi, kteréž jsou v údolí Benhinnom, aby vodili syny své a dcery své Molochovi, ješto jsem jim toho nepřikázal, aniž vstoupilo na srdce mé, aby páchati měli tu ohavnost, a Judu k hřešení přivodili.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 36, 'A nyní z příčiny té takto dí Hospodin. Bůh Izraelský, o městě tomto, o kterémž vy říkáte: Dánoť jest v ruku krále Babylonského skrze meč a hlad a mor:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 37, 'Aj, já shromáždím je ze všech zemí, do nichž jsem je rozehnal v hněvě svém, a v rozpálení svém, i v prchlivosti veliké, a přivedu je zase na toto místo, a způsobím to, aby bydlili bezpečně.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 38, 'I budou lidem mým, a já budu jejich Bohem.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 39, 'Dám zajisté jim srdce jedno a cestu jednu, aby se mne báli po všecky dny, tak aby jim dobře bylo i synům jejich po nich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 40, 'A učiním s nimi smlouvu věčnou, že se neodvrátím od nich, abych jim neměl dobře činiti; nadto bázeň svou dám v srdce jejich, aby neodstupovali ode mne.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 41, 'I veseliti se budu z nich, dobře jim čině, když je štípím v zemi této pevně, celým srdcem svým a vší duší svou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 42, 'Nebo takto praví Hospodin: Jakož jsem uvedl všecko toto zlé veliké na lid tento, tak uvedu na ně všecko to dobré, o němž jim mluvím.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 43, 'Tehdáž kupováno bude pole v zemi této, o níž vy říkáte: Pustá jest, tak že není v ní žádného člověka ani hovada, dánať jest v ruku Kaldejských.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 44, 'Pole za peníze kupovati budou, a zapisovati do cedulí, a zpečetíce, svědky osvědčovati v zemi Beniaminově a vůkol Jeruzaléma v městech Judských, jakož v městech, kteráž jsou při horách, tak v městech na rovinách, a v městech poledních, když zase přivedu zajaté jejich, dí Hospodin.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 1, 'Potom stalo se slovo Hospodinovo k Jeremiášovi po druhé, když ještě zavřín byl v síni stráže, řkoucí:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 2, 'Takto praví Hospodin, kterýž učiní to, Hospodin, kterýž sformuje to, potvrdí toho, Hospodin jméno jeho:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 3, 'Volej ke mně, a ohlásímť se, a oznámímť věci veliké a tajné, o nichž nevíš.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 4, 'Nebo takto praví Hospodin, Bůh Izraelský, o domích města tohoto, a o domích králů Judských, kteříž zkaženi býti mají berany válečnými a mečem:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 5, 'Potáhnouť k boji proti Kaldejským, ale aby naplnili tyto domy mrtvými těly lidskými, kteréž zbiji v hněvě svém a v prchlivosti své, pro jejichž všelikou nešlechetnost skryl jsem tvář svou od města tohoto.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 6, 'Aj, já zopravuji je a vzdělám, a uzdravím obyvatele, a zjevím jim hojnost pokoje, a to stálého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 7, 'Nebo přivedu zase zajaté Judské a zajaté Izraelské, a vzdělám je jako prvé,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 8, 'A očistím je od všeliké nepravosti jejich, kterouž hřešili proti mně, a odpustím všecky nepravosti jejich, kterýmiž hřešili proti mně, a jimiž zpronevěřovali se mně.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 9, 'A toť mi bude k jménu, k radosti, k chvále, a k zvelebení mezi všemi národy země, kteříž uslyší o všem tom dobrém, kteréž já jim učiním, a děsíce se, třásti se budou nade vším tím dobrým a nade vším pokojem tím, kterýž já jim způsobím.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 10, 'Takto praví Hospodin: Na tomto místě, o kterémž vy říkáte: Popléněno jest, tak že není ani člověka ani žádného hovada v městech Judských a na ulicích Jeruzalémských zpustlých, tak že není žádného člověka, ani žádného obyvatele, ani žádného hovada,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 11, 'Ještěť bude slýchán hlas radosti a hlas veselé, hlas ženicha a hlas nevěsty, hlas řkoucích: Oslavujte Hospodina zástupů, nebo dobrý jest Hospodin, nebo na věky milosrdenství jeho, a obětujících díkčinění v domě Hospodinově, když zase přivedu zajaté země této jako na počátku, praví Hospodin.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 12, 'Takto praví Hospodin zástupů: Na místě tomto popléněném, tak že není žádného člověka ani hovada, i ve všech městech jeho bude ještě obydlé pastýřů, kdež by chovali stáda.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 13, 'V městech při horách, v městech na rovinách a v městech v straně polední, tolikéž v zemi Beniaminově a vůkol Jeruzaléma, i v městech Judských, ještě procházívati budou stáda skrze ruce počítajícího, praví Hospodin.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 14, 'Aj, dnové jdou, dí Hospodin, v nichž vykonám slovo to výborné, kteréž jsem mluvil o domu Izraelovu a o domu Judovu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 15, 'V těch dnech a za času toho způsobím to, aby zrostl Davidovi výstřelek spravedlivý, kterýž konati bude soud a spravedlnost na zemi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 16, 'V těch dnech spasen bude Juda, a Jeruzalém bydliti bude bezpečně, a toť jest, což jemu přivolá Hospodin, spravedlnost naše.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 17, 'Nebo takto praví Hospodin: Nebudeť vypléněn muž z rodu Davidova, ješto by neseděl na stolici domu Judského.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 18, 'Z kněží také Levítských nebude vypléněn muž od tváři mé, ješto by neobětoval zápalu, a zapaloval suchou obět, a obětoval obět po všecky dny.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 19, 'Potom stalo se slovo Hospodinovo k Jeremiášovi, řkoucí:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 20, 'Takto praví Hospodin: Jestliže budete moci zrušiti smlouvu mou se dnem, a smlouvu mou s nocí, aby nebývalo dne ani noci časem svým:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 21, 'Takéť smlouva má zrušena bude s Davidem služebníkem mým, aby neměl syna, kterýž by kraloval na stolici jeho, a s Levítskými kněžími, aby nebyli služebníky mými.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 22, 'A jakož nemůže sečteno býti vojsko nebeské, ani změřen býti písek mořský, tak rozmnožím símě Davida služebníka svého, a Levítů mně přisluhujících.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 23, 'Opět stalo se slovo Hospodinovo k Jeremiášovi, řkoucí:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 24, 'Což nesoudíš, co lid tento mluví, říkaje: Že dvojí čeled, kterouž byl vyvolil Hospodin, již ji zavrhl, a lidem mým že pohrdají, jako by nebyl více národem před oblíčejem jejich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 25, 'Takto praví Hospodin: Nebude-liť smlouva má se dnem a nocí, a ustanovení nebes i země zdržáno,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 26, 'Také símě Jákobovo a Davida služebníka svého zavrhu, abych nebral z semene jeho těch, kteříž by panovati měli nad semenem Abrahamovým, Izákovým a Jákobovým, když zase přivedu zajaté jejich, a smiluji se nad nimi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 1, 'Slovo, kteréž se stalo k Jeremiášovi od Hospodina, (když Nabuchodonozor král Babylonský, a všecko vojsko jeho, i všecka království země pod moc jeho přináležející, všickni také národové bojovali proti Jeruzalému a proti všechněm městům jeho), řkoucí:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 2, 'Takto praví Hospodin Bůh Izraelský: Jdi a rci Sedechiášovi králi Judskému, rci, pravím, jemu: Takto dí Hospodin: Aj, já dám toto město v ruku krále Babylonského, aby je vypálil ohněm.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 3, 'I ty neznikneš ruky jeho, ale jistotně jat a v ruku jeho vydán budeš, a oči tvé uzří oči krále Babylonského, i ústa jeho s ústy tvými mluviti budou, a do Babylona se dostaneš.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 4, 'A však slyš slovo Hospodinovo, Sedechiáši králi Judský: Takto praví Hospodin o tobě: Neumřeš od meče,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 5, 'V pokoji umřeš. A jakož pálívali otcům tvým, králům předešlým, kteříž byli před tebou, tak páliti budou tobě, a říkajíce: Ach, pane, kvíliti budou nad tebou; nebo slovo toto já mluvil jsem, dí Hospodin.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 6, 'I mluvil Jeremiáš prorok Sedechiášovi, králi Judskému, všecka slova ta v Jeruzalémě,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 7, 'Když vojsko krále Babylonského bojovalo proti Jeruzalému a proti všechněm městům Judským ostatním, proti Lachis a proti Azeku; nebo ta byla pozůstala z měst Judských města hrazená.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 8, 'Slovo, kteréž se stalo k Jeremiášovi od Hospodina, když učinil král Sedechiáš smlouvu se vším lidem, kterýž byl v Jeruzalémě, o vyhlášení jim svobody,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 9, 'Aby propustil jeden každý služebníka svého a jeden každý děvku svou, Hebrejského neb Hebrejskou, svobodné, aby nepodroboval sobě v službu Žida, bratra svého, nižádný.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 10, 'Tedy uposlechla všecka knížata a všecken lid, kterýž byl v smlouvu všel, aby propustil jeden každý služebníka svého a jeden každý děvku svou svobodné, aby nepodroboval jich v službu více; uposlechli, pravím, a propustili.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 11, 'Potom pak rozmyslivše se, zase pobrali služebníky své a děvky své, kteréž byli propustili svobodné, a podrobili je sobě za služebníky a děvky.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 12, 'I stalo se slovo Hospodinovo k Jeremiášovi od Hospodina, řkoucí:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 13, 'Takto praví Hospodin Bůh Izraelský: Já jsem učinil smlouvu s otci vašimi toho dne, když jsem je vyvedl z země Egyptské, z domu služebníků, řka:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 14, 'Po vyplnění sedmi let propouštívejte jeden každý bratra svého Žida, kterýž by prodán byl tobě, a sloužilť by šest let, propusť, pravím, jej svobodného od sebe. Ale neuposlechli otcové vaši mne, aniž naklonili ucha svého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 15, 'Vy zajisté usmyslivše sobě dnes, učinili jste to, což jest spravedlivého před očima mýma, že jste vyhlásili svobodu jeden každý bližnímu svému, učinivše smlouvu před oblíčejem mým v domě tom, kterýž nazván jest od jména mého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 16, 'Ale zase zpáčivše se, zlehčili jste jméno mé, že jste vzali zase jeden každý služebníka svého a jeden každý děvku svou, kteréž jste byli propustili svobodné podlé žádosti jejich, a podrobili jste je, aby byli vaši služebníci a děvky.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 17, 'Protož takto praví Hospodin: Vy neuposlechli jste mne, abyste vyhlásili svobodu jeden každý bratru svému, a jeden každý bližnímu svému, aj, já vyhlašuji proti vám svobodu, dí Hospodin, meči, moru a hladu, a vydám vás ku posmýkání po všech královstvích země.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 18, 'Vydám zajisté ty lidi, jenž přestoupili smlouvu mou, kteříž nevykonali slov smlouvy té, kterouž učinili před oblíčejem mým, když tele rozťali na dvé, a prošli mezi díly jeho,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 19, 'Totiž knížata Judská a knížata Jeruzalémská, komorníci, a kněží, i všecken lid té země, kteříž prošli mezi díly toho telete.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 20, 'Vydám je, pravím, v ruku nepřátel jejich, a v ruku hledajících bezživotí jejich, i budou těla mrtvá jejich za pokrm ptactvu nebeskému, a šelmám zemským.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 21, 'Sedechiáše také krále Judského, i knížata jeho vydám v ruku nepřátel jejich, a v ruku hledajících bezživotí jejich, v ruku, pravím, vojska krále Babylonského, kteříž odtáhli od vás.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 22, 'Aj, já přikáži, dí Hospodin, a přivedu je zase na město toto, aby bojovali proti němu, a vezmouce je, vypálili je ohněm; města také Judská obrátím v poušť, tak že nebude žádného obyvatele.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 1, 'Slovo, kteréž se stalo k Jeremiášovi od Hospodina za dnů Joakima syna Joziášova, krále Judského, řkoucí:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 2, 'Jdi mezi Rechabitské, a promluvě s nimi, doveď je k domu Hospodinovu do jednoho z pokojů, a dej jim píti vína.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 3, 'Tedy pojav Jazaniáše syna Jeremiášova, syna Chabaciniášova, a bratří jeho i všecky syny jeho se vší rodinou Rechabitských,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 4, 'Dovedl jsem je k domu Hospodinovu do pokoje synů Chanana syna Igdaliášova, muže Božího, kterýž byl při pokoji knížat, jenž byl nad pokojem Maaseiáše syna Sallumova, ostříhajícího prahu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 5, 'Potom postavě před syny domu Rechabitských koflíky plné vína a číše, i řekl jsem jim: Píte víno.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 6, 'Kteříž řekli: Nepíjíme vína. Nebo Jonadab syn Rechabův, otec náš, zapověděl nám, řka: Nepíjejte vína, vy, ani synové vaši na věky.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 7, 'A domu nestavějte, ani semene nerozsívejte, vinice také neštěpujte, ani mívejte, ale v staních přebývejte po všecky dny vaše, abyste živi byli mnoho dnů na tváři země, v níž pohostinu jste.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 8, 'Protož uposlechli jsme hlasu Jonadaba syna Rechabova, otce našeho, ve všem, což přikázal nám, abychom nepili vína po všecky dny své, my, manželky naše, synové naši, i dcery naše,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 9, 'Abychom nestavěli domů k bydlení svému, a vinice, ani rolí, ani nic osátého nemívali.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 10, 'Ale abychom bydlili v staních. Uposlechli jsme, pravím, a děláme všecko, jakž přikázal nám Jonadab otec náš.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 11, 'Stalo se pak, když vtrhl Nabuchodonozor král Babylonský do země, že jsme řekli: Poďte, a ujděme do Jeruzaléma před vojskem Kaldejským, a před vojskem Syrským. Takž bydlíme v Jeruzalémě.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 12, 'Tedy stalo se slovo Hospodinovo k Jeremiášovi, řkoucí:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 13, 'Takto praví Hospodin zástupů, Bůh Izraelský: Jdi a rci mužům Judským a obyvatelům Jeruzalémským: Což nepřijmete naučení, abyste poslouchali slov mých? dí Hospodin.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 14, 'K vykonání přichází všeliké slovo Jonadaba syna Rechabova, kterýž přikázal synům svým, aby nepili vína. Nepili zajisté až do tohoto dne, nebo poslouchají přikázaní otce svého. Já pak mluvím k vám, ráno přivstávaje, a to ustavičně, a však neposloucháte mne.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 15, 'Nadto posílám k vám všecky služebníky své proroky, ráno přivstávaje, a to ustavičně, říkaje: Navraťte se již jeden každý z cesty své zlé, a polepšte předsevzetí svých, a nechoďte za bohy cizími, sloužíce jim, a tak přebývejte v zemi této, kterouž jsem dal vám i otcům vašim: však nenakloňujete uší svých, aniž mne posloucháte.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 16, 'Ješto synové Jonadabovi syna Rechabova plní přikázaní otce svého, kteréž přikázal jim, lid pak tento neposlouchají mne.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 17, 'Protož takto praví Hospodin Bůh zástupů, Bůh Izraelský: Aj, já uvedu na Judu a na všecky obyvatele Jeruzalémské všecko to zlé, kteréž jsem vyřkl proti nim, proto že jsem mluvíval k nim, a neposlouchali, a volával jsem na ně, ale neohlásili se.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 18, 'Rodině pak Rechabitských řekl Jeremiáš: Takto praví Hospodin zástupů, Bůh Izraelský: Protože posloucháte přikázaní Jonadaba otce vašeho, a ostříháte všech přikázaní jeho, anobrž děláte všecko, jakž přikázal vám,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 19, 'Protož takto praví Hospodin zástupů, Bůh Izraelský: Nebudeť vypléněn muž z rodu Jonadabova syna Rechabova, ješto by nestál před oblíčejem mým po všecky dny.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 1, 'Stalo se pak léta čtvrtého Joakima syna Joziášova, krále Judského, stalo se slovo toto k Jeremiášovi od Hospodina, řkoucí:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 2, 'Vezmi sobě knihu, a zapiš do ní všecka slova, kteráž jsem mluvil tobě proti Izraelovi, a proti Judovi, i všechněm národům od toho dne, jakž jsem mluvíval s tebou, ode dnů Joziášových, až do dne tohoto,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 3, 'Zdali aspoň uslyšíce dům Judský o všem tom zlém, kteréž já myslím učiniti jim, navrátí se jeden každý z cesty své zlé, abych odpustil nepravost jejich a hřích jejich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 4, 'Protož zavolal Jeremiáš Bárucha syna Neriášova, i sepsal Báruch do knihy z úst Jeremiášových všecka slova Hospodinova, kteráž mluvil jemu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 5, 'Potom přikázal Jeremiáš Báruchovi, řka: Já zápověd maje, nemohu jíti do domu Hospodinova.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 6, 'Protož jdi ty, a čti v knize této, což jsi napsal z úst mých, slova Hospodinova, při přítomnosti lidu v domě Hospodinově, v den postu, též také při přítomnosti všech Judských, kteříž by se z měst svých sešli, čti je,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 7, 'Zda by snad poníženě a pokorně modléce se před Hospodinem, i navrátili by se jeden každý z cesty své zlé; neboť jest veliký hněv a prchlivost, v níž mluvil Hospodin proti lidu tomuto.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 8, 'I učinil Báruch syn Neriášův všecko, jakž přikázal jemu Jeremiáš prorok, čta v knize té slova Hospodinova v domě Hospodinově.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 9, 'Stalo se pak léta pátého za Joakima syna Joziášova, krále Judského, měsíce devátého, že vyhlásili půst před Hospodinem všemu lidu v Jeruzalémě, a všemu lidu, kteříž se byli sešli z měst Judských do Jeruzaléma.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 10, 'I četl Báruch z knihy slova Jeremiášova v domě Hospodinově, v pokoji Gemariáše syna Safanova, písaře, na síni hořejší, u dveří brány domu Hospodinova nové, při přítomnosti všeho lidu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 11, 'Když pak vyslyšel Micheáš syn Gemariášův, syna Safanova, všecka slova Hospodinova z té knihy,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 12, 'Hned šel do domu královského, do pokoje kancléřova, a aj, tam všecka knížata seděla: Elisama ten kancléř, a Delaiáš syn Semaiášův, a Elnatan syn Achborův, a Gemariáš syn Safanův, a Sedechiáš syn Chananiášův, i všecka knížata.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 13, 'A oznámil jim Micheáš všecka slova, kteráž slyšel, když četl Báruch v knize při přítomnosti lidu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 14, 'Protož poslala všecka knížata k Báruchovi Judu syna Netaniášova, syna Selemiášova, syna Chuzova, aby řekl: Tu knihu, v níž jsi četl při přítomnosti lidu, vezmi do ruky své a poď. I vzal Báruch syn Neriášův tu knihu do ruky své, a přišel k nim.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 15, 'Kteříž řekli jemu: Seď medle a čti ji před námi. I četl Báruch před nimi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 16, 'Stalo se pak, když uslyšeli všecka slova ta, že předěšeni byli všickni, a řekli Báruchovi: Jistotně oznámíme králi všecka slova tato.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 17, 'Potom otázali se Bárucha, řkouce: Oznam již nám, jak jsi všecka slova ta sepsal z úst jeho?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 18, 'Jimž řekl Báruch: Z úst svých pravil mi všecka slova tato, a já psal jsem na knihách černidlem.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 19, 'Tedy řekla ta knížata Báruchovi: Jdi schovej se ty i Jeremiáš, ať žádný neví, kde jste.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 20, 'Potom vešli k králi na síň, když tu knihu schovati dali v pokoji Elisama kancléře, a oznámili králi všecka slova ta.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 21, 'I poslal král Judu, aby vzal tu knihu. Kterýžto vzal ji z pokoje Elisama kancléře, a četl ji Juda při přítomnosti krále, a při přítomnosti všech knížat stojících před králem.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 22, 'Král pak seděl v domě, v němž v zimě býval, měsíce devátého, a na ohništi před ním hořelo.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 23, 'Tedy stalo se, jakž jen přečtl Juda tři listy neb čtyři, že pořezal ji škriptorálem, a házel na oheň, kterýž byl na ohništi, až shořela všecka kniha ta ohněm tím, kterýž byl na ohništi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 24, 'Ale neulekli se, aniž roztrhl roucha svá král a všickni služebníci jeho, kteříž slyšeli všecka slova ta.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 25, 'Nýbrž ještě když Elnatan a Delaiáš a Gemariáš přimlouvali se k králi, aby nepálil té knihy, tedy neuposlechl jich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 26, 'Ale přikázal král Jerachmeelovi synu královu, a Saraiášovi synu Azrielovu, a Selemiášovi synu Abdeelovu, aby jali Bárucha písaře a Jeremiáše proroka. Ale skryl je Hospodin.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 27, 'Stalo se pak slovo Hospodinovo k Jeremiášovi, když spálil král tu knihu a slova, kteráž byl sepsal Báruch z úst Jeremiášových, řkoucí:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 28, 'Vezmi sobě zase knihu jinou, a napiš na ní všecka slova první, kteráž byla v té knize prvnější, kterouž spálil Joakim král Judský.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 29, 'O Joakimovi pak králi Judském rci: Takto praví Hospodin: Ty jsi spálil knihu tuto, pravě: Proč jsi psal v ní, řka: Jistotně přitáhne král Babylonský, a zkazí zemi tuto, a vyhladí z ní lidi i hovada?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 30, 'Protož takto praví Hospodin o Joakimovi králi Judském: Nebude míti, kdo by seděl na stolici Davidově, a tělo jeho mrtvé bude vyvrženo na horko ve dne a na mráz v noci.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 31, 'Nebo trestati budu na něm, a na semeni jeho, i na služebnících jeho nepravost jejich, a uvedu na ně, a na obyvatele Jeruzalémské, i na muže Judské všecko to zlé, o kterémž jsem mluvíval jim, a neposlouchali.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 32, 'I vzal Jeremiáš knihu jinou, a dal ji Báruchovi synu Neriášovu, písaři, kterýž sepsal do ní z úst Jeremiášových všecka slova té knihy, kterouž byl spálil Joakim král Judský ohněm. A ještě přidáno jest k těm slovům mnoho těm podobných.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 1, 'Potom kraloval král Sedechiáš syn Joziášův místo Koniáše syna Joakimova, kteréhož ustanovil králem Nabuchodonozor král Babylonský v zemi Judské.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 2, 'Ale neposlouchal on, ani služebníci jeho, ani lid té země slov Hospodinových, kteráž mluvil skrze Jeremiáše proroka.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 3, 'Ač byl poslal Sedechiáš Jehuchale syna Selemiášova a Sofoniáše syna Maaseiášova, kněze, k Jeremiášovi proroku, aby řekli: Modl se medle za nás Hospodinu Bohu našemu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 4, 'Nebo Jeremiáš ještě bydlil svobodně u prostřed lidu, aniž ho ještě byli dali do žaláře.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 5, 'A vojsko Faraonovo bylo vytáhlo z Egypta; (nebo uslyšavše Kaldejští, kteříž oblehli byli Jeruzalém, pověst o nich, odtrhli od Jeruzaléma).');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 6, 'Stalo se pak slovo Hospodinovo k Jeremiášovi proroku, řkoucí:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 7, 'Toto praví Hospodin Bůh Izraelský: Takto rcete králi Judskému, kterýž vás poslal ke mně, abyste se radili se mnou: Aj, vojsko Faraonovo, kteréž potáhne vám na pomoc, navrátí se zase do země své Egyptské.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 8, 'Kaldejští pak navrátí se zase, a bojovati budou proti městu tomuto, a vezmouce je, vypálí je ohněm.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 9, 'Takto praví Hospodin: Nesvoďte sami sebe, říkajíce: Konečně odtrhnou od nás Kaldejští, neboť neodtrhnou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 10, 'Nýbrž byste pobili všecko vojsko Kaldejských bojujících s vámi, tak že by pozůstali z nich toliko ranění, tiť z stanů svých povstanou, a toto město ohněm vypálí.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 11, 'Stalo se pak, když odtrhlo vojsko Kaldejské od Jeruzaléma před vojskem Faraonovým,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 12, 'Že vycházel Jeremiáš z Jeruzaléma, jíti chtěje do země Beniaminovy, aby tak vynikl z prostředku lidu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 13, 'Když pak byl v bráně Beniaminské, byl tu hejtman nad stráží, jménem Jiriáš syn Selemiáše, syna Chananiášova, kterýž jal Jeremiáše proroka, řka: K Kaldejským ty ustupuješ.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 14, 'Jemuž řekl Jeremiáš: Není pravda, neustupujiť já k Kaldejským. Ale nechtěl ho slyšeti, nýbrž jal Jiriáš Jeremiáše, a dovedl jej k knížatům.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 15, 'Tedy rozhněvavše se knížata na Jeremiáše, ubili jej, a dali jej do vězení, do domu Jonatana písaře; nebo z něho byli udělali žalář.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 16, 'Když pak vešel Jeremiáš do té jámy a do sklípků jejích, a seděl tam Jeremiáš mnoho dní.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 17, 'Teprv poslav král Sedechiáš, vzal jej, a tázal se ho král v domě svém tajně, řka: Stalo-li se slovo od Hospodina? Jemuž řekl Jeremiáš: Stalo. Potom řekl: V ruku krále Babylonského vydán budeš.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 18, 'Při tom řekl Jeremiáš králi Sedechiášovi: Coť jsem zavinil aneb služebníkům tvým, aneb lidu tomuto, že jste mne dali do žaláře tohoto?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 19, 'A kdež jsou proroci vaši, kteříž prorokují vám, říkajíce: Nepřitáhneť král Babylonský na vás, ani na zemi tuto?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 20, 'Nyní tedy slyš, žádám, pane můj králi, nechť, prosím, místo má před tebou pokorná prosba má; nedopouštěj mne zase voditi do domu Jonatana písaře, abych tam neumřel.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 21, 'I přikázal král Sedechiáš, aby vsadili Jeremiáše do síně stráže, a dávali jemu pecník chleba na den z ulice pekařů, dokudž by nebyl vytráven všecken chléb v městě. A tak seděl Jeremiáš v síni stráže.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 1, 'Slyšel pak Sefatiáš syn Matanův, a Gedaliáš syn Paschurův, a Juchal syn Selemiášův, a Paschur syn Malkiášův slova, kteráž Jeremiáš mluvil ke všemu lidu, řka:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 2, 'Takto praví Hospodin: Kdo by zůstal v městě tomto, zahyne mečem, hladem aneb morem, ale kdož by vyšel k Kaldejským, že bude živ, a že bude míti život svůj místo kořisti, a živ zůstane.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 3, 'Takto praví Hospodin: Jistotně vydáno bude město toto v ruku vojska krále Babylonského, a vezme je.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 4, 'Protož řekla ta knížata králi: Nechť jest usmrcen muž ten, poněvadž zemdlívá ruce mužů bojovných, pozůstalých v městě tomto, i ruce všeho lidu, mluvě jim slova taková; nebo muž ten nikoli neobmýšlí pokoje lidu tomuto, ale zlé.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 5, 'Tedy řekl král Sedechiáš: Aj, v ruce vaší jest, neboť král zhola nic nemůže proti vám.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 6, 'I vzali Jeremiáše, kterýž byl v síni stráže, a uvrhli jej do jámy Malkiášovy, syna králova, a spustili Jeremiáše po provazích. V té pak jámě nebylo nic vody, ale bláto, tak že Jeremiáš tonul v tom blátě.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 7, 'Ale jakž uslyšel Ebedmelech Mouřenín, dvořan, kterýž byl v domě královském, že dali Jeremiáše do té jámy, (král pak seděl v bráně Beniaminské),');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 8, 'Hned vyšel Ebedmelech z domu královského, a mluvil s králem, řka:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 9, 'Pane můj, králi, zle učinili muži tito všecko, což učinili Jeremiášovi proroku, že jej uvrhli do té jámy; neboť by byl umřel i na prvním místě hladem, poněvadž již není žádného chleba v městě.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 10, 'Protož poručil král Ebedmelechovi Mouřenínu, řka: Vezmi s sebou odsud třidceti mužů, a vytáhni Jeremiáše proroka z té jámy, prvé než by umřel.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 11, 'Tedy vzal Ebedmelech ty muže s sebou, a všel do domu královského pod pokladnici, a nabral starých hadrů strhaných, hadrů, pravím, zkažených, kteréž spustil k Jeremiášovi do té jámy po provazích.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 12, 'A řekl Ebedmelech Mouřenín Jeremiášovi: Nu, podlož ty staré, strhané hadry a zkažené pod paže rukou svých s provazy. I učinil tak Jeremiáš.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 13, 'Takž vytáhli Jeremiáše po provazích, a dobyli jej z té jámy. I seděl Jeremiáš v síni stráže.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 14, 'Potom poslav král Sedechiáš, vzal Jeremiáše proroka k sobě do třetího průchodu, kterýž byl při domu Hospodinovu, a řekl král Jeremiášovi: Zeptám se tebe na něco, netaj přede mnou ničehož.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 15, 'I řekl Jeremiáš Sedechiášovi: Oznámím-liť, zdaliž mne konečně neusmrtíš? A poradím-liť, neuposlechneš mne.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 16, 'Tedy přisáhl král Sedechiáš Jeremiášovi tajně, řka: Živť jest Hospodin, kterýž učinil nám život tento, že tě neusmrtím, aniž tě vydám v ruku mužů těch, kteříž hledají bezživotí tvého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 17, 'I řekl Jeremiáš Sedechiášovi: Takto praví Hospodin Bůh zástupů, Bůh Izraelský: Jestliže dobrovolně vyjdeš k knížatům krále Babylonského, i duše tvá živa bude, i město toto nebude vypáleno ohněm, a tak živ zůstaneš ty i dům tvůj.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 18, 'Jestliže pak nevyjdeš k knížatům krále Babylonského, jistě že vydáno bude město toto v ruku Kaldejských, a vypálí je ohněm, ano i ty neznikneš ruky jejich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 19, 'Tedy řekl král Sedechiáš Jeremiášovi: Velmi se bojím Židů, kteříž ustoupili k Kaldejským, aby mne snad nevydali v ruku jejich, i učinili by sobě ze mne posměch.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 20, 'Ale Jeremiáš řekl: Nevydadí. Uposlechni, prosím, hlasu Hospodinova, o kterémž já mluvím tobě, a bude dobře tobě, i duše tvá živa bude.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 21, 'Jestliže pak nebudeš chtíti vyjíti, toto jest slovo to, kteréž mi ukázal Hospodin,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 22, 'Že aj, všecky ženy, kteréž pozůstaly v domě krále Judského, přivedeny budou knížatům krále Babylonského, a samyť říkati budou: Nabádaliť jsou tě, a obdrželi na tobě ti, kteříž tě troštovali pokojem; uvázlyť v bahně nohy tvé, a nazpět obráceny.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 23, 'Všecky také manželky tvé i syny tvé dovedou k Kaldejským, i ty sám neznikneš ruky jejich, ale rukou krále Babylonského jat budeš, a město toto vypálíš ohněm,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 24, 'Tedy řekl Sedechiáš Jeremiášovi: Žádný ať neví o věcech těchto, abys neumřel.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 25, 'Pakli uslyšíce knížata, že jsem mluvil s tebou, přišli by k tobě, a řekliť by: Oznam medle nám, cos mluvil s králem, netaj před námi, a neusmrtíme tě, a co mluvil s tebou král?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 26, 'Tedy rci jim: Předkládal jsem poníženou a pokornou prosbu svou před krále, aby mne nedal zase voditi do domu Jonatanova, abych tam neumřel.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 27, 'I sešla se všecka knížata k Jeremiášovi, aby se ho tázali. Kterýžto oznámil jim podlé toho všeho, jakž přikázal král. Takž mlčkem odešli od něho, když nebylo slyšeti o té věci.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 28, 'Jeremiáš pak seděl v síni stráže až do toho dne, v němž dobyt jest Jeruzalém, kdežto byl, když dobýván byl Jeruzalém.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 1, 'Léta devátého Sedechiáše krále Judského, měsíce desátého, přitáhl Nabuchodonozor král Babylonský se vším vojskem svým k Jeruzalému, a oblehli jej.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 2, 'Jedenáctého pak léta Sedechiášova, měsíce čtvrtého, devátého dne měsíce, prolomeno jest město.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 3, 'I vešla tam všecka knížata krále Babylonského, a posadila se v bráně prostřední: Nergalšaretser, Samgarnebu, Sarsechim, Rabsaris, Nergalšaretser, Rabmag, a všecka jiná knížata krále Babylonského.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 4, 'Stalo se pak, když je uzřel Sedechiáš král Judský, a že všickni muži bojovní utekli, a vyšli v noci z města cestou zahrady královské skrze bránu mezi dvěma zdmi, ušel také cestou pouště.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 5, 'I honilo je vojsko Kaldejské, a postihli Sedechiáše na rovinách Jerišských, a jali jej a přivedli ho k Nabuchodonozorovi králi Babylonskému do Ribla, do země Emat. Kdežto učinil soud.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 6, 'Nebo zmordoval král Babylonský syny Sedechiášovy v Ribla před očima jeho, i všecky nejpřednější Judské zmordoval král Babylonský.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 7, 'Oči pak Sedechiášovy oslepil, a svázav ho řetězy ocelivými, dovedl jej do Babylona.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 8, 'Dům také královský i domy toho lidu vypálili Kaldejští ohněm, a zdi Jeruzalémské pobořili.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 9, 'Ostatek pak lidu, kterýž byl zůstal v městě, i poběhlce, kteříž byli ustoupili k němu, a jiný lid pozůstalý zavedl Nebuzardan, hejtman nad žoldnéři, do Babylona.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 10, 'Toliko nejchaternějších z lidu, kteříž nikdež neměli nic, zanechal Nebuzardan, hejtman nad žoldnéři, v zemi Judské, jimž rozdal vinice a rolí v ten den.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 11, 'Přikázal pak Nabuchodonozor král Babylonský o Jeremiášovi Nebuzardanovi, hejtmanu nad žoldnéři, řka:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 12, 'Vezmi jej, a pilně ho opatruj, aniž jemu čiň co zlého, ale jakž tobě řekne, tak nalož s ním.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 13, 'Protož poslav Nebuzardan, hejtman nad žoldnéři, a Nebušazban, Rabsaris, a Nergalšaretser, Rabmag, a všickni hejtmané krále Babylonského,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 14, 'Poslavše, pravím, vzali Jeremiáše z síně stráže, a dali jej Godoliášovi synu Achikamovu, syna Safanova, aby jej domů dovedl. Takž bydlil u prostřed lidu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 15, 'Stalo se pak k Jeremiášovi slovo Hospodinovo, když ještě byl zavřín v síni stráže, řkoucí:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 16, 'Jdi a rci Ebedmelechovi Mouřenínu, řka: Takto praví Hospodin zástupů, Bůh Izraelský: Aj, já způsobím to, aby došla slova má na město toto ke zlému a ne k dobrému, a splní se před oblíčejem tvým v ten den.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 17, 'Ale vysvobodím tě v ten den, dí Hospodin, aniž budeš vydán v ruku mužů těch, jejichž oblíčeje se lekáš.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 18, 'Nebo jistotně vychvátím tě, abys od meče nepadl, a budeš míti život svůj místo kořisti, proto že jsi naději složil ve mně, dí Hospodin.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 40, 1, 'Slovo to, kteréž se stalo k Jeremiášovi od Hospodina, když jej propustil Nebuzardan, hejtman nad žoldnéři, z Ráma, vzav jej, když byl svázaný řetězy u prostřed všech zajatých Jeruzalémských a Judských, zajatých do Babylona.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 40, 2, 'Tedy vzal hejtman nad žoldnéři Jeremiáše, a řekl jemu: Hospodin Bůh tvůj byl vyřkl zlé toto proti místu tomuto.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 40, 3, 'Protož je uvedl a učinil Hospodin, jakž mluvil; nebo jste hřešili proti Hospodinu, a neposlouchali jste hlasu jeho, pročež stala se vám věc tato.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 40, 4, 'Již tedy, aj, rozvazuji tě dnes z řetězů těch, kteříž jsou na rukou tvých. Vidí-liť se za dobré jíti se mnou do Babylona, poď, a budu tě pilně opatrovati; jestližeť se pak nevidí za dobré jíti se mnou do Babylona, nech tak. Aj, všecka tato země jest před tebou; kamžť se za dobré a slušné vidí jíti, tam jdi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 40, 5, 'Pakli, (poněvadž se nenavracuje), obrať se k Godoliášovi synu Achikamovu, syna Safanova, kteréhož ustanovil král Babylonský nad městy Judskými, a zůstaň s ním u prostřed lidu, aneb kamžť se koli dobře líbí jíti, jdi. I dal jemu hejtman nad žoldnéři na cestu, a dar, a propustil jej.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 40, 6, 'Takž přišel Jeremiáš k Godoliášovi synu Achikamovu do Masfa, a bydlil s ním u prostřed lidu pozůstalého v zemi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 40, 7, 'Uslyšeli pak všickni hejtmané vojsk, kteříž byli na poli, oni i všecken lid jejich, že ustanovil král Babylonský Godoliáše syna Achikamova nad tou zemí, a že jemu poručil muže a ženy i děti, a to z nejchaternějších té země, z těch kteříž nebyli zajati do Babylona.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 40, 8, 'Protož přišli k Godoliášovi do Masfa, totiž Izmael syn Netaniášův, též Jochanan a Jonatan, synové Kareachovi, a Saraiáš syn Tanchumetův, a synové Efai Netofatského, a Jazaniáš syn Machatův, oni i lid jejich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 40, 9, 'Tedy přisáhl jim Godoliáš syn Achikamův, syna Safanova, i lidu jejich, řka: Nebojte se služby Kaldejských, zůstaňte v zemi, a služte králi Babylonskému, a dobře vám bude.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 40, 10, 'Nebo aj, já bydlím v Masfa, abych sloužil Kaldejským, kteříž přicházejí k nám, vy pak slízejte víno a letní ovoce i olej, a skládejte do nádob svých, a zůstaňte v městech svých, kteráž držíte.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 40, 11, 'Tak i všickni Judští, kteříž byli u Moábských a mezi Ammonitskými, a mezi Idumejskými, a kteříž byli ve všech zemích, uslyšavše, že by pozůstavil král Babylonský ostatek Judských, a že by ustanovil nad nimi Godoliáše syna Achikamova, syna Safanova,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 40, 12, 'Navrátili se všickni Judští ze všech míst, kamž rozehnaní byli, a přišli do země Judské k Godoliášovi do Masfa. I nazbírali vína a letního ovoce velmi mnoho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 40, 13, 'Jochanan pak syn Kareachův, a všecka knížata vojsk, kteráž byla v poli, přišli k Godoliášovi do Masfa,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 40, 14, 'A řekli jemu: Víš-li co o tom, že Baalis král Ammonitský poslal Izmaele syna Netaniášova, aby tě zabil? Ale nevěřil jim Godoliáš syn Achikamův.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 40, 15, 'Nadto Jochanan syn Kareachův řekl Godoliášovi tajně v Masfa, řka: Nechť jdu medle, a zabiji Izmaele syna Netaniášova, však žádný nezví. Proč má zabiti tebe, a mají rozptýleni býti všickni Judští, kteříž shromážděni jsou k tobě, a zahynouti ostatek Judských?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 40, 16, 'Ale řekl Godoliáš syn Achikamův Jochananovi synu Kareachovu: Nečiň toho, nebo lež ty mluvíš o Izmaelovi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 1, 'Stalo se pak měsíce sedmého, že přišel Izmael syn Netaniášův, syna Elisamova z semene královského, a hejtmané královští, totiž deset mužů s ním, k Godoliášovi synu Achikamovu do Masfa, a jedli tam chléb spolu v Masfa.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 2, 'Potom vstav Izmael syn Netaniášův, a deset mužů, kteříž byli s ním, zabili Godoliáše syna Achikamova, syna Safanova, mečem; zamordoval, pravím, toho, kteréhož ustanovil král Babylonský nad tou zemí.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 3, 'Všecky také Židy, kteříž byli s ním, s Godoliášem, v Masfa, i ty Kaldejské, kteříž postiženi byli tam, muže bojovné, pobil Izmael.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 4, 'Stalo se pak druhého dne, jakž zamordoval Godoliáše, (o čemž žádný nezvěděl),');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 5, 'Že přišli někteří z Sichem, z Sílo a z Samaří, mužů osmdesáte, oholivše bradu, a roztrhše roucha, a řežíce se, kteřížto suchou obět a kadidlo v rukou svých měli, aby je nesli do domu Hospodinova.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 6, 'Tedy Izmael syn Netaniášův vyšel jim vstříc z Masfa, ustavičně jda a plače. Stalo se pak, když je potkal, že řekl jim: Poďte k Godoliášovi synu Achikamovu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 7, 'Ale stalo se, když přišli do prostřed města, že pobiv je Izmael syn Netaniášův, vmetal je do prostřed jámy, on i muži, kteříž s ním byli.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 8, 'Deset pak mužů nalezlo se mezi nimi, kteříž řekli Izmaelovi: Nemorduj nás; nebo máme sklady skryté v poli, pšenice a ječmene, též oleje a medu. I nechal tak, a nemordoval jich u prostřed bratří jejich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 9, 'Jáma pak, do níž Izmael vmetal k Godoliášovi všecka těla mužů těch, kteréž pobil, ta jest, kterouž udělal král Aza, boje se Bázy krále Izraelského. Kterouž naplnil Izmael syn Netaniášův zbitými.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 10, 'A zajal Izmael všecken ostatek lidu, kteříž byli v Masfa, dcery královské a všecken lid, kteříž byli pozůstali v Masfa, nad nimiž byl ustanovil Nebuzardan, hejtman nad žoldnéři, Godoliáše syna Achikamova. Kteréžto zajav Izmael syn Netaniášův, šel, aby se dopravil k Ammonitským.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 11, 'V tom uslyšel Jochanan syn Kareachův, i všickni hejtmané těch vojsk, kteříž s ním byli, o všem tom zlém, kteréž učinil Izmael syn Netaniášův.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 12, 'I vzali všecken svůj lid, a táhli k boji proti Izmaelovi synu Netaniášovu, jehož nalezli při vodách velikých, kteréž jsou v Gabaon.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 13, 'Stalo se pak, že když uzřel všecken lid, kterýž byl s Izmaelem, Jochanana syna Kareachova a všecka knížata vojsk, kteříž s ním byli, zradovali se.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 14, 'A obrátiv se všecken ten lid, kterýž byl zajal Izmael z Masfa, navrátil se zase, a přišel k Jochananovi synu Kareachovu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 15, 'Izmael pak syn Netaniášův ušel před Jochananem s osmi muži, a přišel k Ammonitským.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 16, 'Protož vzal Jochanan syn Kareachův, a všecka knížata vojsk, kteříž s ním byli, všecken ostatek lidu, kterýž zase přivedl od Izmaele syna Netaniášova z Masfa, když zabil Godoliáše syna Achikamova, muže bojovné, též ženy a děti i komorníky, kteréž zase přivedl z Gabaon,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 17, 'A odšedše, pobyli v hospodě Chimhamově, kteráž jest u Betléma, aby jdouce, vešli do Egypta,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 18, 'Před Kaldejskými. Nebo báli se jich, proto že zabil Izmael syn Netaniášův Godoliáše syna Achikamova, kteréhož byl ustanovil král Babylonský nad tou zemí.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 1, 'Potom přistoupili všecka knížata vojsk, i Jochanan syn Kareachův i Jazaniáš syn Hosaiášův, i všecken lid, od nejmenšího až do největšího,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 2, 'A řekli Jeremiášovi proroku: Uslyš medle nás v ponížené prosbě naší, a modl se za nás Hospodinu Bohu svému, za všecken ostatek tento, nebo nás maličko zůstalo z mnohých, jakž oči tvé nás vidí,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 3, 'Ať nám oznámí Hospodin Bůh tvůj cestu, po níž bychom jíti, a co činiti měli.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 4, 'Jimž řekl Jeremiáš prorok: Uslyšel jsem. Aj, já modliti se budu Hospodinu Bohu vašemu podlé slov vašich, a cožkoli vám odpoví Hospodin, oznámím vám; nezatajím před vámi slova.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 5, 'Oni zase řekli Jeremiášovi: Nechť jest Hospodin mezi námi svědkem pravým a věrným, jestliže podlé každého slova, pro něž poslal tě Hospodin Bůh tvůj k nám, tak se chovati nebudeme.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 6, 'Buď dobré aneb zlé, hlasu Hospodina Boha našeho, pro nějž tě vysíláme k němu, uposlechneme, aby nám dobře bylo, když uposlechneme hlasu Hospodina Boha našeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 7, 'Stalo se pak po přeběhnutí desíti dnů, když se stalo slovo Hospodinovo k Jeremiášovi,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 8, 'Že povolal Jochanana syna Kareachova, a všech knížat vojsk, kteříž s ním byli, i všeho lidu, od nejmenšího až do největšího,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 9, 'A řekl jim: Takto praví Hospodin Bůh Izraelský, k němuž jste mne poslali, abych rozprostíral poníženou prosbu vaši před oblíčejem jeho:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 10, 'Jestliže navrátíce se, zůstanete v zemi této, zajisté že vzdělám vás, a nezkazím, anobrž vštípím vás, a nevypléním; neboť lituji toho zlého, kteréž jsem učinil vám.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 11, 'Nebojtež se krále Babylonského, jehož se bojíte, nebojte se ho, dí Hospodin; neboť s vámi jsem, abych vás vysvobozoval, a vytrhoval vás z ruky jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 12, 'Nadto způsobím vám milost, aby se slitoval nad vámi, a dal se vám navrátiti do země vaší.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 13, 'Ale řeknete-li: Nezůstaneme v zemi této, neposlouchajíce hlasu Hospodina boha svého,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 14, 'A říkajíce: Nikoli, ale do země Egyptské vejdeme, kdež neuzříme boje, ani zvuku trouby neuslyšíme, a chleba lačněti nebudeme, pročež tam se osadíme:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 15, 'Protož nyní slyštež slovo Hospodinovo, ostatkové Judští: Takto praví Hospodin zástupů, Bůh Izraelský: Jestliže vy zarputile na tom zůstanete, abyste vešli do Egypta, a vejdete-li, abyste tam pobyli,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 16, 'Jistě stane se to, že meč, kteréhož se bojíte, tam v zemi Egyptské vás postihne, a hlad, jehož se obáváte, přijde na vás v Egyptě, a tam pomřete.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 17, 'Tak se stane všechněm těm mužům, kteříž uložili předce jíti do Egypta, aby tam byli pohostinu, že zhynou mečem, hladem a morem, a nezůstane z nich žádného, aniž kdo znikne toho zlého, kteréž já uvedu na ně.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 18, 'Nebo takto praví Hospodin zástupů, Bůh Izraelský: Jakož vylit jest hněv můj a prchlivost má na obyvatele Jeruzalémské, tak vylita bude prchlivost má na vás, když vejdete do Egypta, a budete k proklínání, a k užasnutí, a k zlořečení, a za útržku; nadto neuzříte více místa tohoto.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 19, 'K vámť mluví Hospodin, ó ostatkové Judští: Nevcházejte do Egypta. Jistotně vězte, (neboť se vám dnes osvědčuji),');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 20, 'Poněvadž jste se neupřímě ke mně měli v myšleních svých, poslavše mne k Hospodinu Bohu vašemu, řkouce: Modl se za nás Hospodinu Bohu našemu, a všecko, jakžť koli dí Hospodin Bůh náš, tak nám oznam, a učiníme,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 21, 'Když pak oznamuji vám dnes, však neposloucháte hlasu Hospodina Boha vašeho hned v ničemž, pročež mne k vám poslal:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 22, 'Protož pravím, vězte jistotně, že mečem, hladem a morem pomřete v tom místě, kamž se vám zachtělo jíti, abyste tam byli pohostinu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 43, 1, 'Stalo se pak, když přestal Jeremiáš mluviti ke všemu lidu všech slov Hospodina Boha jejich, s nimiž poslal jej Hospodin Bůh jejich k nim, všech, pravím, slov těch,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 43, 2, 'Že řekl Azariáš syn Hosaiášův, a Jochanan syn Kareachův, i všickni muži ti pyšní, řkouce Jeremiášovi: Lež ty mluvíš, neposlalť tebe Hospodin Bůh náš, abys řekl: Nevcházejte do Egypta, abyste tam byli pohostinu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 43, 3, 'Ale Báruch syn Neriášův ponouká tě proti nám, aby vydal nás v ruku Kaldejských k usmrcení nás, aneb zajetí nás do Babylona.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 43, 4, 'I neuposlechl Jochanan syn Kareachův, i všecka knížata vojsk, též i všecken lid hlasu Hospodinova, aby zůstal v zemi Judské.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 43, 5, 'Ale Jochanan syn Kareachův, a všecka knížata vojsk vzali všecken ostatek Judských, kteříž se byli navrátili ze všech národů, kamž byli rozehnáni, k obývání v zemi Judské,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 43, 6, 'Muže i ženy, též dítky a dcery královské, i všelikou duši, kterýchž Nebuzardan, hejtman nad žoldnéři, s Godoliášem synem Achikamovým, syna Safanova, zanechal, i s Jeremiášem prorokem a Báruchem synem Neriášovým,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 43, 7, 'A šli do země Egyptské, (nebo neuposlechli hlasu Hospodinova), a přišli až do Tachpanches.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 43, 8, 'Stalo se pak slovo Hospodinovo k Jeremiášovi v Tachpanches, řkoucí:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 43, 9, 'Nabeř do ruky své kamení velikého, a schovej je v hlině v cihelni, kteráž jest u brány domu Faraonova v Tachpanches, před očima mužů Judských.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 43, 10, 'A rci jim: Takto praví Hospodin zástupů, Bůh Izraelský: Aj, já pošli, a vezmu Nabuchodonozora krále babylonského, služebníka svého, a postavím stolici jeho na tomto kamení, kteréž jsem schoval, i rozbije majestát svůj na něm.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 43, 11, 'Nebo přitáhne a popléní zemi Egyptskou: Kteříž k smrti, k smrti, a kteříž k zajetí, do zajetí, a kteříž pod meč,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 43, 12, 'A zanítím oheň v domích bohů Egyptských, aby je popálil, a zajal je. A přioděje se zemí Egyptskou, tak jako se odívá pastýř rouchem svým, a vyjde odtud s pokojem,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 43, 13, 'Když poláme sochy Betsemes, kteréž jest v zemi Egyptské, a domy bohů Egyptských popálí ohněm.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 1, 'Slovo, kteréž se stalo k Jeremiášovi proti všechněm Judským bydlícím v zemi Egyptské, kteříž bydlili v Magdol a v Tachpanches, a v Nof, a v zemi Patros, řkoucí:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 2, 'Takto praví Hospodin zástupů, Bůh Izraelský: Vy jste viděli všecko to zlé, kteréž jsem uvedl na Jeruzalém a na všecka města Judská, že aj, pustá jsou podnes, tak že v nich není žádného obyvatele,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 3, 'Pro nešlechetnost jejich, kterouž páchali, aby jen popouzeli mne, chodíce kaditi a sloužiti bohům cizím, jichž neznali sami, vy, ani otcové vaši,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 4, 'Ješto posílal jsem k vám všecky služebníky své proroky, ráno přivstávaje, a to ustavičně, říkaje: Nečiňte medle této věci ohavné, kteréž nenávidím.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 5, 'Ale neuposlechli, aniž naklonili ucha svého, aby se navrátili od nešlechetnosti své, a aby nekadili bohům cizím.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 6, 'Protož vylita jest prchlivost má i hněv můj, a rozpálil se v městech Judských i po ulicích Jeruzalémských, tak že obrácena jsou v poušť a v pustinu, jakž viděti v dnešní den.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 7, 'Nyní pak takto praví Hospodin Bůh zástupů, Bůh Izraelský: Proč vy činíte zlé převeliké proti dušem svým, abyste vyplénili z sebe muže i ženu, dítě i prsí požívajícího z prostředku Judy, abyste nepozůstavili sobě ostatků,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 8, 'Popouzejíce mne dílem ruku svých, kadíce bohům cizím v zemi Egyptské, do níž jste vešli, abyste tam byli pohostinu, abyste vyplénili sebe, a byli k zlořečení a za útržku u všech národů země?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 9, 'Zdali jste zapomenuli na nešlechetnosti otců svých, a na nešlechetnosti králů Judských, a na nešlechetnosti manželek jejich, a na nešlechetnosti své, i na nešlechetnosti manželek svých, kteréž páchali v zemi Judské a po ulicích Jeruzalémských?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 10, 'Nekořili se až do tohoto dne, aniž se báli, aniž chodili v zákoně mém a v ustanoveních mých, kteráž předkládám vám jako i otcům vašim.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 11, 'Protož takto praví Hospodin zástupů, Bůh Izraelský: Aj, já obracím tvář svou proti vám k zlému, totiž abych vyplénil všecky Judské.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 12, 'Zhubím zajisté ostatek Judských, kteříž svévolně vešli do země Egyptské, aby tam byli pohostinu, tak že zhynou docela všickni v zemi Egyptské. Padnou od meče, hladem docela zhynou, od nejmenšího až do největšího, mečem a hladem pomrou; nadto budou k proklínání a k užasnutí, a k zlořečení a za útržku.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 13, 'Nebo navštívím ty, kteříž bydlí v zemi Egyptské, jako jsem navštívil Jeruzalém mečem, hladem a morem,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 14, 'Tak že nebude, kdo by ušel, neb pozůstal z ostatků Judských, kteříž přišli do země Egyptské, aby tam byli pohostinu, aby se zase navrátiti mohli do země Judské. Čímž se však troštují, že se zase navrátí, aby přebývali tam, ale nenavrátíť se, než ti, kteříž sami ujdou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 15, 'Tedy odpověděli Jeremiášovi všickni ti muži, věděvše, že kadívaly manželky jejich bohům cizím, ty všecky ženy, jichž stál veliký zástup, i všecken lid přebývající v zemi Egyptské v Patros, řkouce:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 16, 'V té věci, o kteréž jsi nám mluvil ve jménu Hospodinovu, neuposlechneme tebe.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 17, 'Ale dosti činiti chceme každému slovu, kteréž by pošlo z úst našich, kadíce tvoru nebeskému, a obětujíce jemu oběti mokré, jakž jsme činívali my i otcové naši, králové naši i knížata naše po městech Judských a po ulicích Jeruzalémských; nebo nasyceni jsme bývali chlebem, a bývali jsme veseli, zlého pak neokoušeli jsme.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 18, 'Ale jakž jsme přestali kaditi tvoru nebeskému, a obětovati jemu oběti mokré, nedostatek trpíme ve všem, a mečem i hladem hyneme.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 19, 'Že pak kadíme tvoru nebeskému, a obětujeme jemu oběti mokré, zdaliž bez znamenitých mužů našich pečeme jemu koláče, službu jemu konajíce, a obětujíce jemu oběti mokré?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 20, 'Tedy řekl Jeremiáš všemu lidu, mužům i ženám a všemu lidu, kteříž jemu to odpověděli, řka:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 21, 'Zdaliž na kadidlo, jímž jste kadívali po městech Judských a po ulicích Jeruzalémských vy i otcové vaši, králové vaši i knížata vaše i lid země, nerozpomenul se Hospodin, a zdaž jím to nepohnulo,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 22, 'Tak že nemohl Hospodin více snášeti nešlechetnosti předsevzetí vašich a ohavností, kteréž jste činili? Pročež obrácena jest země vaše v poušť a v pustinu a v zlořečenství, tak že není v ní žádného obyvatele, jakž dnešní den jest.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 23, 'Proto že jste kadívali, a že jste hřešili proti Hospodinu, a neposlouchali jste hlasu Hospodinova, a tak v zákoně jeho a v ustanoveních jeho ani v svědectvích jeho nechodili jste, protož potkalo vás zlé toto, jakž viděti dnešní den.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 24, 'Nadto řekl Jeremiáš všemu tomu lidu i všechněm těm ženám: Slyšte slovo Hospodinovo všickni Judští, kteříž jste v zemi Egyptské:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 25, 'Takto praví Hospodin zástupů, Bůh Izraelský, řka: Vy i ženy vaše ústy svými jste mluvili, a rukami doplnili, říkajíce: Konečněť budeme plniti sliby své, kteréž jsme slíbili, kadíce tvoru nebeskému, a obětujíce jemu oběti mokré, a tak vší snažností vyplňujete sliby vaše, a všelijak slibům vašim dosti činíte.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 26, 'Protož slyšte slovo Hospodinovo všickni Judští, kteříž bydlíte v zemi Egyptské: Aj, já přisahám skrze jméno své veliké, praví Hospodin, že nebude více vzýváno jméno mé ústy žádného muže Judského po vší zemi Egyptské, kterýž by řekl: Živť jest Panovník Hospodin.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 27, 'Aj, já bdíti budu nad nimi k zlému a ne k dobrému, i budou pléněni všickni muži Judští, kteříž jsou v zemi Egyptské, mečem a hladem, dokudž by docela nezhynuli.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 28, 'Kteříž pak ujdou meče, navrátí se z země Egyptské do země Judské, lidu malý počet. I zvědíť všickni ostatkové Judští, kteříž přišli do země Egyptské, aby tam byli pohostinu, čí slovo ostojí, mé-li čili jejich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 29, 'A toto mějte za znamení, dí Hospodin, že já trestati budu vás v místě tomto, abyste věděli, že jistotně ostojí slova má proti vám k zlému.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 30, 'Takto praví Hospodin: Aj, já vydám Faraona Chofra krále Egyptského v ruku nepřátel jeho a v ruku hledajících bezživotí jeho, jako jsem vydal Sedechiáše krále Judského v ruku Nabuchodonozora krále Babylonského, nepřítele jeho, a hledajícího bezživotí jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 45, 1, 'Slovo, kteréž promluvil Jeremiáš prorok k Báruchovi synu Neriášovu, když spisoval slova tato do knihy z úst Jeremiášových, léta čtvrtého Joakima syna Joziášova, krále Judského, řka:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 45, 2, 'Takto praví Hospodin Bůh Izraelský o tobě, ó Báruchu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 45, 3, 'Řekls: Jižtě mi běda, nebo přičiní Hospodin zámutku k bolesti mé. Ustávám v úpění svém, a odpočinutí nenalézám.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 45, 4, 'Takto rci jemu: Takto praví Hospodin: Aj, což jsem vystavěl, já bořím, a což jsem vštípil, já pléním, totiž všecku zemi tuto.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 45, 5, 'A ty bys hledal sobě velikých věcí? Nehledej. Nebo aj, já uvedu bídu na všeliké tělo, dí Hospodin, ale dám tobě život tvůj místo kořisti na všech místech, kamž půjdeš.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 1, 'Slovo Hospodinovo, kteréž se stalo k Jeremiášovi proroku proti národům těmto:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 2, 'O Egyptských. Proti vojsku Faraona Néchy krále Egyptského, (jenž bylo při řece Eufrates u Charkemis, kteréž zbil Nabuchodonozor král Babylonský), léta čtvrtého Joakima syna Joziášova, krále Judského:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 3, 'Připravtež štít a pavézu, a jděte k boji.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 4, 'Zapřáhejte koně, a vsedejte jezdci, postavte se s lebkami, vytírejte kopí, zobláčejte se v pancíře.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 5, 'Proč vidím tyto zděšené, zpět obrácené, a nejsilnější jejich potřené, anobrž prudce utíkající, tak že se ani neohlédnou? Strach jest vůkol, dí Hospodin,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 6, 'Aby neutekl čerstvý, a neušel silný, aby na půlnoci o břeh řeky Eufrates zavadili a padli.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 7, 'Kdo se to valí jako potok, jako řeky, jejichž vody sebou zmítají?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 8, 'Egypt jako potok se valí a jako řeky, když se vody hýbají, tak pravě: Potáhnu, přikryji zemi, zkazím město i přebývající v něm.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 9, 'Křepčtež, ó koni, a běžte s hřmotem, ó vozové; nechť vytáhnou i silní, Mouřenínové a Putští, kteříž užívají pavézy, i Ludimští, kteříž užívají a natahují lučiště.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 10, 'A však ten den Panovníka Hospodina zástupů bude den pomsty, aby uvedl pomstu na nepřátely své, kteréžto zžíře meč a nasytí se, anobrž opojí se krví jejich; nebo obět Panovníka Hospodina zástupů bude v zemi půlnoční u řeky Eufrates.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 11, 'Vyprav se do Galád, a nabeř masti, panno dcero Egyptská, nadarmo však užíváš mnohého lékařství, nebo ty zhojena býti nemůžeš.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 12, 'Slyšíť národové o zlehčení tvém, a naříkání tvého plná jest země, proto že silný na silném se ustrkuje, tak že spolu zaroveň padají.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 13, 'Slovo, kteréž mluvil Hospodin k Jeremiášovi proroku o přitažení Nabuchodonozora krále Babylonského, aby zkazil zemi Egyptskou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 14, 'Oznamte v Egyptě, a ohlaste v Magdol, rozhlaste také v Nof, i v Tachpanches rcete: Postůj a připrav se, ale však zžíře meč všecko, což vůkol tebe jest.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 15, 'Proč poražen jest každý z nejsilnějších tvých? Nemůže ostáti, proto že Hospodin pudí jej.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 16, 'Mnohoť bude těch, kteříž klesnou a padnou jeden na druhého, a řeknou: Vstaň, a navraťme se k lidu svému, a do země, v níž jsme se zrodili, před mečem toho zhoubce.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 17, 'Budou křičeti tam: Faraona krále Egyptského není než sám chřest, jižť pominul volný jeho čas.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 18, 'Živť jsem já, (dí král ten, jehož jméno Hospodin zástupů), že jakž jest Tábor mezi horami, a jako Karmel při moři, tak toto přijde.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 19, 'Připraviž sobě to, co bys s sebou vystěhovati měla, ó ty, kteráž jsi usadila se, dcero Egyptská; neboť Nof v poušť obrácen a vypálen bude, tak že nebude tam žádného obyvatele.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 20, 'Velmi pěkná jalovice jest Egypt, ale zabití její od půlnoci jistotně přijde.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 21, 'Ano i nájemníci jeho u prostřed něho jsou jako telata vytylá, ale takéť i ti obrátíce se, utekou. Neostojí, když den bídy jejich přijde na ně, v čas navštívení jejich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 22, 'Hlas jeho jako hadí siptěti bude, když s vojskem přitáhnou, a s sekerami přijdou na něj jako ti, kteříž sekají dříví.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 23, 'Posekají les jeho, dí Hospodin, ačkoli mu konce není; více jest jich než kobylek, aniž mají počtu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 24, 'Zahanbenať bude dcera Egyptská, vydána bude v ruku lidu půlnočního.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 25, 'Praví Hospodin zástupů, Bůh Izraelský: Aj, já navštívím lidné město No, též Faraona i Egypt s bohy jeho a králíky jeho, Faraona, pravím, a ty, kteříž v něm doufají.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 26, 'A vydám je v ruku těch, kteříž hledají bezživotí jejich, totiž v ruku Nabuchodonozora krále Babylonského, a v ruku služebníků jeho; potom však bydleno bude v něm, jako za dnů starodávních, dí Hospodin.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 27, 'Ale ty neboj se, služebníče můj Jákobe, aniž se strachuj, ó Izraeli; nebo aj, já vysvobodím tě zdaleka, i símě tvé z země zajetí jejich. I navrátí se Jákob, aby odpočíval a pokoj měl, a aby nebylo žádného, kdo by předěsil.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 28, 'Ty, pravím, neboj se, služebníče můj Jákobe, dí Hospodin; neboť jsem s tebou. Učiním zajisté konec všechněm národům, mezi kteréž tě zaženu, tobě pak neučiním konce, ale budu tě trestati v soudu, ačkoli tě naprosto bez trestání nenechám.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 47, 1, 'Slovo Hospodinovo, kteréž se stalo k Jeremiášovi proroku proti Filistinským, prvé než dobyl Farao Gázy.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 47, 2, 'Takto praví Hospodin: Aj, vody vystupují od půlnoci, a obrátí se v potok rozvodnilý, tak že zatopí zemi, i cožkoli jest na ní, město i ty, kteříž bydlí v něm; pročež křičeti budou lidé, a kvíliti všeliký obyvatel té země;');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 47, 3, 'Pro zvuk dusání kopyt silných jeho, pro hřmot vozů jeho, a hrčení kol jeho, neohlédnou se otcové na syny, majíce opuštěné ruce;');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 47, 4, 'Pro ten den, kterýž přijíti má, aby pohubil všecky Filistinské, aby zahladil Týr a Sidon, i všelikou pozůstávající pomoc, když hubiti bude Hospodin Filistinské, ostatek krajiny Kaftor.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 47, 5, 'Přijde lysina na Gázu, vypléněn bude Aškalon i ostatek údolí jejich. Dokudž se řezati budeš?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 47, 6, 'Ach, meči Hospodinův, dokudž se nespokojíš? Navrať se do pošvy své, utiš se, a zastav se.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 47, 7, 'I jakž by se spokojil? Však Hospodin přikázal jemu. Proti Aškalon a proti břehu mořskému, tam postavil jej.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 1, 'Proti Moábovi. Takto praví Hospodin zástupů, Bůh Izraelský: Běda městu Nébo, neboť popléněno bude; zahanbeno a vzato bude Kariataim, zahanbeno bude Misgab a děsiti se bude.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 2, 'Nebudeť míti více žádné pochvaly Moáb z Ezebon, obmýšlejí proti němu zlé: Poďte, a vyhlaďme je z národu. I ty, ó Madmen, vypléněno budeš, půjde za tebou meč.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 3, 'Hlas žalostný z Choronaim: Ó poplénění a potření veliké.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 4, 'Potřín bude Moáb, slyšán bude křik maličkých jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 5, 'Proto že na cestě Luchitské ustavičný bude pláč, a že kudyž se chodí k Choronaim, nepřátelé křik hrozný slyšeti budou:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 6, 'Utecte, vysvoboďte život svůj, a buďte jako vřes na poušti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 7, 'Nebo proto, že doufáš v statku svém a v pokladích svých, také ty jat budeš; i půjde Chámos do zajetí, kněží jeho, též i knížata jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 8, 'Přitáhne zajisté zhoubce na každé město, aniž ho které město znikne; zahyne i údolí, a zahlazena bude rovina, jakž praví Hospodin.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 9, 'Dejte brky Moábovi, ať rychle uletí; nebo města jeho v poušť obrácena budou, tak že nebude žádného obyvatele v nich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 10, 'Zlořečený ten, kdož dělá dílo Hospodinovo lstivě, a zlořečený ten, kdož zdržuje meč svůj od krve.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 11, 'Mělť jest pokoj Moáb od dětinství svého, a usadil se na kvasnicích svých, aniž býval přelíván z nádoby do nádoby, totiž do zajetí nechodíval; pročež zůstala v něm chuť jeho, a vůně jeho není proměněna.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 12, 'Protož aj, dnové jdou, dí Hospodin, že pošli na něj ty, kteříž vpády činí, a zajmou jej, sudy pak jeho vyprázdní, a nádoby jeho roztříští.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 13, 'I zahanben bude Moáb od Chámos, jako zahanbeni jsou dům Izraelský od Bethel naděje své.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 14, 'Kterakž říkáte: Silní jsme a muži stateční k boji?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 15, 'Pohuben bude Moáb a z měst svých vyjde, a nejvýbornější mládenci jeho půjdou k zabití, dí král, jehož jméno Hospodin zástupů.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 16, 'Blízkoť jest bída Moábova, aby přišla, a trápení jeho pospíchá velice.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 17, 'Litujte ho všickni okolní jeho, a všickni, kteříž víte o jménu jeho, rcete: Jak polámána jest hůl nejpevnější, prut nejozdobnější?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 18, 'Sejdi z slávy své, a seď v žíni, ó ty, kterážs se usadila, dcero Dibonská; neboť zhoubce Moábův přitáhne proti tobě, zkazí ohrady tvé.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 19, 'Postav se na cestě, a ohlédni se pilně, obyvatelkyně Aroer; vyptej se toho, kdož utíká, a té, kteráž uchází, rci: Co se děje?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 20, 'Stydí se Moáb, že jest potřín. Kvělte a křičte, oznamte u Arnon, že hubí Moába.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 21, 'Nebo soud přišel na zemi té roviny, na Holon a na Jasa a na Mefat,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 22, 'I na Dibon a Nébo, a na Betdiblataim,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 23, 'I na Kariataim a na Betgamul, a na Betmeon,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 24, 'A na Kariot, a na Bozru i na všecka města země Moábské, daleká i blízká.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 25, 'Odťat bude roh Moábův, a rámě jeho zlámáno bude, dí Hospodin.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 26, 'Opojte jej, poněvadž se proti Hospodinu zpínal, až by se válel Moáb v vývratku svém, a byl za smích i on také.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 27, 'Nebo zdali v posměchu nebyl u tebe Izrael? Zdali mezi zloději zastižen jest, že jakž jen promluvíš o něm, poskakuješ?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 28, 'Zanechte měst, a přebývejte v skále, ó obyvatelé Moábští, a buďte podobni holubici hnízdící se daleko v rozsedlinách.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 29, 'Slýchaliť jsme o pýše Moábově, že velmi pyšný jest, o vysokomyslnosti jeho a pýše jeho, i o nadutosti jeho, a povyšování se srdce jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 30, 'Známť já, dí Hospodin, vzteklost jeho, ale špatnáť jest ona k tomu; lži jeho nedovedouť toho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 31, 'Protož nad Moábskými kvílím, a nade vším Moábem křičím, pro obyvatele Kircheres úpí srdce.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 32, 'Více než plakáno bylo Jazerských, plači tebe, ó vinný kmene Sibma. Rozvodové tvoji dostanouť se za moře, až k moři Jazerskému dosáhnou; na letní ovoce tvé a na vinobraní tvé zhoubce připadne.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 33, 'I přestane veselé a plésání nad polem úrodným v zemi Moábské, a vínu z presu přítrž učiním; nebudou ho tlačívati s prokřikováním. Prokřikování nebudeť prokřikováním.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 34, 'Více křičeti budou než Ezebonští, až do Eleale, až do Jasa vydávati budou hlas svůj, od Ségor až do Choronaim jako jalovice tříletá; nebo také i vody Nimrim vymizejí.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 35, 'A tak učiním, dí Hospodin, přítrž Moábovi, obětujícímu na výsosti a kadícímu bohům jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 36, 'Protož srdce mé nad Moábem jako píšťalky zníti bude, srdce mé i nad obyvateli Kircheres jako píšťalky zníti bude, proto že i zboží nashromážděná se v nic obrátí.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 37, 'Nebo na každé hlavě bude lysina, a každá brada oholena, na všech rukou řezání, a na bedrách žíně.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 38, 'Na všech střechách Moábových i po ulicích jeho všudy jen kvílení; nebo rozrazím Moába jako nádobu neužitečnou, dí Hospodin.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 39, 'Kvíliti budou: Jakť jest potřín, jak se obrátil zpět Moáb s hanbou! A jest Moáb v posměchu a k předěšení všechněm, kteříž jsou vůkol něho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 40, 'Nebo takto praví Hospodin: Aj, jako orlice přiletí a roztáhne křídla svá na Moába.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 41, 'Vzato bude Kariot, i pevnosti pobrány budou, a bude srdce silných Moábských v ten den podobné srdci ženy svírající se.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 42, 'I vyhlazen bude Moáb z lidu, proto že se proti Hospodinu zpínal.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 43, 'Strach a jáma a osídlo nad tebou, ó obyvateli Moábský, praví Hospodin.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 44, 'Kdo uteče před strachem, vpadne do jámy, a kdo vyleze z jámy, osídlem lapen bude; nebo uvedu na něj, totiž na Moába, rok navštívení jejich, dí Hospodin.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 45, 'Stávaliť jsou v stínu Ezebon ti, kteříž utíkávali před násilím, ale oheň vyjde z Ezebon, a plamen z prostřed Seon, a zžíře kout Moábův a vrch hlavy těch, kteříž jen bouří.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 46, 'Běda tobě, Moábe, zahyneť lid Chámosův; nebo pobráni budou synové tvoji do zajetí, i dcery tvé do zajetí.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 47, 'A však zase přivedu zajaté Moábské v posledních dnech, dí Hospodin. Až potud soud o Moábovi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 1, 'Proti Ammonitským. Takto praví Hospodin: Což nemá žádných synů Izrael? Což dědice žádného nemá? Proč dědičně opanoval král jejich Gádu, a lid jeho v městech tohoto bydlí?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 2, 'Protož aj, dnové jdou, dí Hospodin, že způsobím, aby slyšáno bylo proti Rabba Ammonitských troubení válečné, a aby bylo obráceno v hromadu rumu, a jiná města jeho ohněm vypálena. I opanuje Izrael ty, kteříž jej byli opanovali, praví Hospodin.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 3, 'Kvěl Ezebon, když popléněno bude Hai, křičte, ó dcery Rabba, přepašte se žíněmi, plačte, a běžte přes ploty; nebo král váš do zajetí půjde, kněží jeho i knížata jeho spolu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 4, 'Což se chlubíš údolími, když oplývá údolí tvé, ó dcero zpurná, kteráž doufáš v pokladech svých, říkajíc: Kdo by táhl na mne?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 5, 'Aj, já uvedu na tebe strach, praví Panovník Hospodin zástupů, ze všeho vůkolí tvého, jímž rozehnáni budete všickni, a nebude žádného, kdo by shromáždil toulající se.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 6, 'A však potom zase přivedu zajaté Ammonitské, dí Hospodin.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 7, 'Proti Idumejským. Takto praví Hospodin zástupů: Což není více moudrosti v Teman? Zahynula rada od rozumných? Zmařena moudrost jejich?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 8, 'Utíkejte, obraťte se, a hluboko se schovejte, obyvatelé Dedan; nebo bídu uvedu na Ezau v čas navštívení jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 9, 'Kdyby ti, kteříž zbírají víno, přišli na tebe, zdaž by nepozůstavili paběrků? Pakli zloději v noci, zdaž by škodili více nad potřebu svou?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 10, 'Ale já obnažím Ezau, zodkrývám skrýše jeho, tak že se nebude moci ukryti. Pohubenoť bude símě jeho i bratří jeho i sousedé jeho, tak že nebude naprosto, kdo by řekl:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 11, 'Zanech sirotků svých, já živiti je budu, a vdov svých mně se dověřte.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 12, 'Takto zajisté praví Hospodin: Aj, ti, kteříž nemají žádného práva píti kalichu tohoto, předce pijí, ty pak sám abys toho naprosto prázen byl? Nebudeš prázen, ale jistotně píti budeš.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 13, 'Nebo skrze sebe přisahám, dí Hospodin, že pustinou, útržkou, pouští a prokletím bude Bozra, a všecka města jeho budou pouští věčnou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 14, 'Pověst slyšel jsem od Hospodina, že posel k národům poslán jest: Shromažďte se, a táhněte proti němu; nuže, vstaňte k boji.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 15, 'Nebo aj, způsobím to, abys byl za nejšpatnějšího mezi národy, v nevážnosti mezi lidmi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 16, 'To, že jsi hrozný, zklamá tě, i pýcha srdce tvého, ó ty, kterýž bydlíš v rozsedlinách skalních, kterýž se držíš vysokých pahrbků. Bys pak vysoko udělal hnízdo své jako orlice, i odtud tě strhnu, dí Hospodin.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 17, 'I bude země Idumejská pustinou. Každý, kdož půjde skrze ni, užasne se, a diviti se bude nade všemi ranami jejími;');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 18, 'Jako podvrácení Sodomy a Gomory a sousedů jejich, praví Hospodin. Neosadí se tam žádný, aniž bydliti bude v ní syn člověka.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 19, 'Aj, jako lev vystupuje i více než zdutí Jordána proti příbytku Nejsilnějšího, a však v okamžení zaženu jej z této země, a toho, kterýž jest vyvolený, ustanovím nad ní. Nebo kdo jest mně rovný? A kdo mi složí rok? A kdo jest ten pastýř, kterýž by se postavil proti mně?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 20, 'Protož slyšte radu Hospodinovu, kterouž zavřel o Idumejských, a to, což myslil proti obyvatelům Temanským: Zajisté žeť je vyvlekou nejmenší tohoto stáda, zajisté že je popléní i příbytky jejich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 21, 'Od hřmotu pádu jejich třásti se bude ta země, hlas a křik jejich slyšán bude u moře Rudého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 22, 'Aj, jako orlice přitáhne a přiletí, a roztáhne křídla svá na Bozru, i bude srdce silných Idumejských v ten den podobné srdci ženy svírající se.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 23, 'Proti Damašku. Zastydí se Emat i Arfad, nebo novinu zlou uslyší, a užasnou se, tak že se i moře zkormoutí, aniž se bude moci upokojiti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 24, 'Oslábne Damašek, obrátí se k utíkání, a hrůza podejme jej, svírání a bolesti zachvátí jej jako rodičku.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 25, 'Ale řkou: Jakž by nemělo ostáti město slovoutné, město radosti mé?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 26, 'Protož padnou mládenci jeho na ulicích jeho, a všickni muži bojovní vypléněni budou v ten den, dí Hospodin zástupů.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 27, 'A zanítím oheň ve zdi Damašské, kterýž do konce zkazí paláce Benadadovy.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 28, 'Proti Cedar a královstvím Azor, kteráž pohubiti má Nabuchodonozor král Babylonský. Takto praví Hospodin: Vstaňte, táhněte proti Cedar, a vypleňte národy východní.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 29, 'Stany jejich i stáda jejich vezmou, kortýny jejich se vším nádobím jejich, i velbloudy jejich poberou sobě, a volati budou na ně: Strach jest vůkol.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 30, 'Utecte, rozprchněte se rychle, skrejte se hluboce, obyvatelé Azor, dí Hospodin, neboť Nabuchodonozor král Babylonský složil proti vám radu, a vymyslil proti vám chytrost.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 31, 'Vstaňte, táhněte proti národu upokojenému, kterýž sedí bezpečně, praví Hospodin. Nemá ani vrat ani závory, a samotní bydlejí.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 32, 'Budou zajisté velbloudi jejich v loupež, a množství dobytků jejich v kořist, a rozptýlím na všeliký vítr ty, kteříž i v nejzadnějších koutech bydlejí, a ze všech stran uvedu bídu na ně, dí Hospodin.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 33, 'I bude Azor příbytkem draků, pustinou až na věky; neosadí se tam žádný, aniž bude bydleti v něm syn člověka.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 34, 'Slovo Hospodinovo, kteréž se stalo k Jeremiášovi proroku proti Elamitským, na počátku kralování Sedechiáše krále Judského, řkoucí:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 35, 'Takto praví Hospodin zástupů: Aj, já polámi lučiště Elamitských, největší sílu jejich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 36, 'Uvedu zajisté na Elamitské čtyři větry ode čtyř stran světa, a rozptýlím je na všecky ty větry, tak že nebude národu, do něhož by se nedostal někdo z vyhnaných Elamitských.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 37, 'A předěsím Elamitské před nepřátely jejich a před těmi, kteříž hledají bezživotí jejich. Uvedu, pravím, na ně zlé, prchlivost hněvu svého, dí Hospodin, a budu posílati za nimi meč, dokudž jim konce neučiním.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 38, 'I postavím stolici svou mezi Elamitskými, a vypléním odtud krále i knížata, praví Hospodin.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 39, 'A však stane se v posledních dnech, že zase přivedu zajaté Elamitské, dí Hospodin.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 1, 'Slovo, kteréž mluvil Hospodin proti Babylonu a proti zemi Kaldejské skrze Jeremiáše proroka:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 2, 'Oznamujte mezi národy a rozhlašujte, zdvihněte korouhev, rozhlašujte, netajte, rcete: Vzat bude Babylon, zahanben bude Bél, potřín bude Merodach, zahanbeny budou modly jeho, potříni budou ukydaní bohové jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 3, 'Nebo přitáhne na něj národ od půlnoci, kterýž obrátí zemi jeho v pustinu, tak že nebude obyvatele v ní. Od člověka až do hovada vystěhují se, odejdou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 4, 'V těch dnech a toho času, dí Hospodin, přijdou synové Izraelští, oni i synové Judští spolu; plačíce, ochotně půjdou, a Hospodina Boha svého hledati budou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 5, 'Na cestu k Sionu ptáti se budou, a obrátíce se tam, řeknou: Poďte a připojte se k Hospodinu smlouvou věčnou, nepřicházející v zapomenutí.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 6, 'Ovce hynoucí jsou lid můj, pastýři jejich působí to, aby bloudily, a po horách se toulaly, s hůry na pahrbek chodily, zapomenuvše na příbytky své.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 7, 'Všickni, kteříž je nalézají, zžírají je, a nepřátelé jejich říkají: Nebudeme nic vinni, proto že hřeší proti Hospodinu. Příbytek spravedlnosti a otců jejich naděje jest Hospodin.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 8, 'Vystěhujte se z prostředku Babylona, a z země Kaldejské vyjděte, a buďte jako kozlové před stádem.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 9, 'Nebo aj, já vzbudím a přivedu na Babylon shromáždění národů velikých z země půlnoční, kteřížto sšikují se proti němu, i bude dobyt odtud. Kterýchžto střely jsou jako silného, jenž sirobu uvodí; žádnáť se nenavrátí na prázdno.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 10, 'I bude země Kaldejských v loupež; všickni, kteříž ji loupiti budou, nasytí se, dí Hospodin.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 11, 'Proto že se veselíte, proto že pléšete, ó dráči dědictví mého, proto že jste zbujněli jako jalovice vytylá, a provyskujete jako rekové,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 12, 'Zahanbena bude matka vaše velice, a zapýří se rodička vaše: Aj, nejzadnější z národů, poušť, země vyprahlá a pustina.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 13, 'Pro prchlivost Hospodinovu nebude v ní bydleno, ale velmi spustne všecko. Každý, kdož půjde mimo Babylon, užasne se, a diviti se bude nade všemi ranami jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 14, 'Sšikujte se proti Babylonu vůkol všickni, kteříž natahujete lučiště, střílejte proti němu, nelitujte střely; nebo hřešil proti Hospodinu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 15, 'Křičte proti němu vůkol: Poddal se, padli základové jeho, pobořeny jsou zdi jeho. Nebo pomsta Hospodinova jest, uveďte pomstu na něj; jakž činíval, učiňte jemu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 16, 'Vypleňte rozsevače z Babylona, i držícího srp v čas žně; před mečem hubícím každý nechť se k lidu svému obrátí, a každý do země své nechť uteče.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 17, 'Hovádko zahnané jest Izrael, kteréž lvové splašili. Nejprvé zžíral je král Assyrský, tento pak poslednější, Nabuchodonozor král Babylonský, kosti jeho potřel.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 18, 'Protož toto praví Hospodin zástupů, Bůh Izraelský: Aj, já navštívím krále Babylonského i zemi jeho, jako jsem navštívil krále Assyrského.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 19, 'A přivedu zase Izraele do příbytku jeho, aby se pásl na Karmeli a Bázan, a na hoře Efraim, a v Galád aby se sytila duše jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 20, 'V těch dnech a toho času, dí Hospodin, byla-li by vyhledávána nepravost Izraelova, nebude žádné, a hříchové Judovi, však nebudou nalezení; nebo odpustím těm, kteréž pozůstavím.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 21, 'Proti té zemi zpurných táhni, a proti obyvatelům pomsty; zhub je a zahlaď jako proklaté i utíkající, dí Hospodin. Učiniž, pravím, všecko, jakž přikazuji tobě,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 22, 'Ať jest hluk boje v té zemi a potření veliké.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 23, 'Jakž by posekáno a polámáno býti mohlo kladivo vší země? Jak by k užasnutí Babylon býti mohl mezi národy?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 24, 'Polékl jsem na tě, ó Babylone, pročež vzat budeš, než zvíš. Nalezen, ano i polapen budeš, proto že jsi směl potýkati se s Hospodinem.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 25, 'Otevřel Hospodin poklad svůj, a vynesl nástroje hněvu svého; nebo dílo toto jest Panovníka Hospodina zástupů v zemi Kaldejské.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 26, 'Přitáhněte na ni od konce země, zotvírejte obilnice její, šlapejte po ní jako po stozích, a zahlaďte ji jako proklatou, tak aby z ní ničeho nepozůstalo.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 27, 'Zbíte mečem všecky volky její, nechť sstoupí k zabití; běda jim, když přijde den jejich, čas navštívení jejich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 28, 'Hlas utíkajících a ucházejících z země babylonské, aby oznámili na Sionu pomstu Hospodina Boha našeho, pomštění chrámu jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 29, 'Shromažďte proti babylonu nejudatnější, všickni natahující lučiště, položte se proti němu vůkol, ať nelze jemu ujíti. Odplaťte jemu podlé skutků jeho, všecko, jakž dělával, učiňte jemu; nebo proti Hospodinu pýchal, proti Svatému Izraelskému.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 30, 'Protož padnou mládenci jeho na ulicích jeho, a všickni muži bojovní jeho vypléněni budou v ten den, dí Hospodin.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 31, 'Aj, já jsem proti tobě, ó pýcho, praví Panovník Hospodin zástupů; neboť přišel den tvůj, čas, abych tě navštívil.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 32, 'Poklesne se zajisté ten pyšný a padne, a nebude žádného, kdo by jej zdvihl; a zanítím oheň v městech jeho, kterýžto zžíře všecka vůkolí jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 33, 'Takto praví Hospodin zástupů: Utištěni jsou synové Izraelští, i s syny Judskými, a všickni, kteříž je zjímali, drží je, nechtí propustiti jich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 34, 'Ale vykupitel jejich silný, jehož jméno jest Hospodin zástupů, jistotně povede při jejich, aby pokoj způsobil této zemi, a pohnul obyvateli Babylonskými.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 35, 'Meč na Kaldejské, dí Hospodin, a na obyvatele Babylonské, i na knížata jeho i na mudrce jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 36, 'Meč na lháře, aby se zbláznili, meč na silné jeho, aby potříni byli.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 37, 'Meč na koně jeho a na vozy jeho, i na všecku tu směsici, kteráž jest u prostřed něho, aby byli jako ženy; meč na poklady jeho, aby rozchvátáni byli.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 38, 'Sucho na vody jeho, aby vyschly; nebo země plná jest rytin, a při modlách bláznívají.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 39, 'Protož bydliti budou tam šelmy s hroznými potvorami, bydliti budou v ní i mladé sovy; a nebude tam bydleno na věky, ani přebýváno od národu až do pronárodu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 40, 'Podobná bude k podvrácení hroznému Sodomy a Gomory i sousedů jejich, dí Hospodin; neosadí se tam žádný, aniž bydliti bude v ní syn člověka.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 41, 'Aj, lid přitáhne od půlnoci, a národ veliký, i králové znamenití, vzbuzeni jsouce od stran země.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 42, 'Lučiště a kopí pochytí, ukrutní budou, a neslitují se; hlas jejich jako moře zvučeti bude, a na koních pojedou, sšikovaní jako muž udatný k boji proti tobě, ó dcero Babylonská.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 43, 'Král Babylonský jakž uslyší pověst o nich, opadnou ruce jeho, úzkost zachvátí jej, bolest jako rodičku.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 44, 'Aj, jako lev vystupuje, více než zdutí Jordána proti příbytku Nejsilnějšího, a však v okamžení zaženu jej z této země, a toho, kterýž jest vyvolený, ustanovím nad ní. Nebo kdo jest mně rovný? A kdo mi složí rok? A kdo jest ten pastýř, kterýž by se postavil proti mně?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 45, 'Protož slyšte radu Hospodinovu, kterouž zavřel o Babylonu, a to, což myslil proti zemi Kaldejské: Zajisté žeť je vyvlekou nejmenší tohoto stáda, zajisté že je popléní i příbytek jejich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 46, 'Od zvuku při dobývání Babylona třásti se bude ta země, a křik mezi národy slyšán bude.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 1, 'Takto praví Hospodin: Aj, já vzbudím proti Babylonu a proti těm, kteříž bydlejí u prostřed povstávajících proti mně, vítr hubící.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 2, 'A pošli na Babylon ty, jenž vějí, kteřížto převívati budou jej, a vyprázdní zemi jeho, když budou proti němu vůkol v den bídy.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 3, 'Natahujícímu, kterýž silně natahuje lučiště své, a kráčí v pancíři svém, dím: Neslitovávejtež se nad mládenci jeho, zahlaďte jako proklaté všecko vojsko jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 4, 'Ať padnou zbití v zemi Kaldejské, a probodnutí na ulicích jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 5, 'Nebo není opuštěn Izrael a Juda od Boha svého, od Hospodina zástupů, ačkoli země jejich plná jest provinění proti Svatému Izraelskému.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 6, 'Utecte z prostředku Babylona, a zachovejte jeden každý život svůj, abyste nebyli vypléněni v nepravosti jeho. Nebo čas bude pomsty Hospodinovy, sám odplatu dá jemu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 7, 'Byltě koflíkem zlatým Babylon v ruce Hospodinově, opojujícím všecku zemi; víno jeho pili národové, protož se zbláznili národové.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 8, 'Ale v náhle padne Babylon, a potřín bude. Kvělte nad ním, nabeřte masti pro bolesti jeho, snad bude moci zhojen býti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 9, 'Hojili jsme babylon, ale není zhojen, opusťme jej, a poďme jeden každý do země své; nebo až k nebi dosahá soud jeho, a vznesen jest až k nejvyšším oblakům.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 10, 'Vyvedl Hospodin při naši; poďte, a vypravujme na Sionu dílo Hospodina Boha našeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 11, 'Vytřete střely, shledejte, což nejvíc můžete, pavéz, Hospodin vzbudil ducha králů Médských, proto že proti Babylonu usouzení jeho jest, aby jej zkazil; pomsta zajisté jest Hospodinova, pomštění chrámu jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 12, 'Na zdech babylonských zdvihněte korouhev, osaďte stráž, postavte strážné, připravte zálohy; nebo i myslil Hospodin, i učiní, což řekl proti obyvatelům Babylonským.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 13, 'Ó ty, kterýž bydlíš při vodách velikých, ó kterýž máš množství pokladů, přišloť skončení tvé, cíl lakomství tvého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 14, 'Přisáhlť jest Hospodin zástupů skrze samého sebe: Jistotně naplním tě lidmi jako brouky, kteříž by prokřikovali nad tebou radostně:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 15, 'Ten, kterýž učinil zemi mocí svou, kterýž utvrdil okršlek světa moudrostí svou, a opatrností svou roztáhl nebesa,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 16, 'Kterýžto, když vydává hlas, ječí vody na nebi, a kterýž působí to, aby vystupovaly páry od kraje země, blýskání s deštěm přivodí, a vyvodí vítr z pokladů svých.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 17, 'Tak zhlupěl každý člověk, že nezná toho, že zahanben bývá každý zlatník od rytiny; nebo faleš jest slitina jeho, a není ducha v nich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 18, 'Marnost jsou a dílo podvodů; v čas, v němž navštíveni budou, zahynou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 19, 'Neníť jim podobný díl Jákobův; nebo on jest stvořitelem všeho, a částka dědictví jeho, Hospodin zástupů jest jméno jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 20, 'Ty jsi mým kladivem rozrážejícím, nástroji válečnými, abych rozrážel skrze tebe národy, a kazil skrze tebe království,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 21, 'Abych rozrážel skrze tebe koně s jezdcem jeho, abych rozrážel skrze tebe vůz s tím, kdož jezdí na něm.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 22, 'Abych rozrážel skrze tebe muže i ženu, abych rozrážel skrze tebe starého i dítě, abych rozrážel skrze tebe mládence i pannu,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 23, 'Abych rozrážel skrze tebe pastýře s stádem jeho, abych rozrážel skrze tebe oráče s spřežením jeho, abych rozrážel skrze tebe vývody a knížata.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 24, 'Ale jižť odplatím Babylonu i všechněm obyvatelům Kaldejským za všecko bezpráví jejich, kteréž činili Sionu před očima vašima, dí Hospodin.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 25, 'Aj, já jsem proti tobě, ó horo, kteráž hubíš, dí Hospodin, kteráž hubíš všecku zemi; a vztáhna ruku svou na tebe, svalím tě z těch skal, a obrátím tě v horu spálenou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 26, 'A nevezmou z tebe kamene k úhlu, ani kamene k základům; nebo pustinou věčnou budeš, praví Hospodin.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 27, 'Vyzdvihněte korouhev v zemi, trubte trubou mezi národy, připravte proti němu národy, svolejte proti němu království Ararat, Minni, Ascenez, ustanovte hejtmana proti němu, přiveďte koní jako brouků počet nesčíslný.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 28, 'Připravte proti Babylonu národy, krále země Médské, vývody její a všecka knížata její, i všecku zemi panování jejich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 29, 'I bude se třásti země a bolestiti, když vykonáváno bude usouzení Hospodinovo proti Babylonu, aby obrátil zemi Babylonskou v pustinu, v níž by se žádný neosazoval.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 30, 'Přestanou silní Babylonští bojovati, seděti budou v ohradách, zhyne síla jejich, budou jako ženy, zapálí příbytky jejich, polámány budou závory jejich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 31, 'Pošta jedna druhou potká, a posel posla, aby oznámeno bylo králi Babylonskému, že vzato jest město jeho na kraji,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 32, 'A že brodové vzati, i jezera vypálena ohněm, a muži bojovní předěšeni.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 33, 'Nebo takto praví Hospodin zástupů, Bůh Izraelský: Dcera Babylonská jest jako humno, jehož nabíjení čas; ještě maličko, a přijde čas žně její.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 34, 'Vyjídá mne, potírá mne Nabuchodonozor král Babylonský, vystavuje mne nádobu prázdnou, požírá mne jako drak, naplňuje břich svůj rozkošemi mými, vyhání mne.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 35, 'Násilé, kteréž se mně a mému tělu děje, přijdiž na Babylon, praví obyvatelkyně Sionská, a krev má na obyvatele země Kaldejské, praví Jeruzalém.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 36, 'Protož takto praví Hospodin: Aj, já vyvedu při tvou, a pomstím tě; nebo vysuším moře jeho, vysuším i vrchoviště jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 37, 'I bude Babylon v hromady, v příbytek draků, v užasnutí a ckání, tak že nebude v něm žádného obyvatele.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 38, 'Jako lvové spolu řváti budou, skučeti budou jako lvíčata.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 39, 'Když se rozpálí, učiním jim hody, a tak je opojím, že zkřiknouti a snem věčným zesnouti musejí, tak aby neprocítili, dí Hospodin.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 40, 'Povedu je jako berany k zabití, jako skopce s kozly.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 41, 'Jakž by dobyt býti mohl Sesák? Jakž by vzata býti mohla chvála vší země? Jakž by přijíti mohl na spuštění Babylon mezi národy?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 42, 'Vystoupí proti Babylonu moře, množstvím vlnobití jeho přikryt bude.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 43, 'Města jeho budou pustinou, zemí vyprahlou a pustou, zemí, v jejíchž městech neosadí se žádný, aniž projde skrze ně syn člověka.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 44, 'Navštívím také Béle v Babyloně, a vytrhnu, což sehltil, z úst jeho, i nepohrnou se k němu více národové; také i zdi Babylonské padnou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 45, 'Vyjděte z prostředku jeho, lide můj, a vysvoboďte jeden každý duši svou od prchlivosti hněvu Hospodinova.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 46, 'A nebuďtež choulostivého srdce, aniž se bojte pověsti, kteráž slyšána bude v té zemi, když přijde tohoto roku pověst, a potom druhého roku pověst, i ukrutenství v zemi, a pán na pána.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 47, 'Protož aj, dnové přijdou, že navštívím rytiny Babylonské, a všecka země jeho zahanbena bude, i všickni zbití jeho padnou u prostřed něho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 48, 'I budou prozpěvovati nad Babylonem nebesa i země, a cožkoli v nich jest, když na něj od půlnoci přitáhnou ti zhoubcové, dí Hospodin.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 49, 'Ano i Babylon padnouti musí, ó zbití Izraelovi, i s Babylonem padnou zbití vší země jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 50, 'Ó kdož jste znikli meče, jděte, nezastavujte se; zpomínejte, daleko jsouce, na Hospodina, a Jeruzalém nechť vstupuje na srdce vaše.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 51, 'Rcete: Stydímeť se, že slýcháme útržku, hanbí se tváře naše, že cizozemci chodí do svatyní domu Hospodinova.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 52, 'Protož aj, dnové přijdou, dí Hospodin, že navštívím rytiny jeho, a po vší zemi jeho stonati bude zraněný.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 53, 'Byť pak vstoupil Babylon na nebe, a byť pak ohradil velmi vysokou pevnost svou, přitáhnou ode mne na něj zhoubcové, praví Hospodin.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 54, 'Zvuk křiku z Babylona, a potření veliké z země Kaldejské.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 55, 'Nebo Hospodin popléní Babylon, a vyhladí z něho hřmot veliký, byť pak zvučela vlnobití jejich jako vody mnohé, vydáván byl hluk hlasu jejich,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 56, 'Když přitáhne na něj, na Babylon zhoubce. I budou jati silní jeho, potříno bude lučiště jejich; nebo Bůh silný odplatí, Hospodin vrchovatě odplatí.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 57, 'Opojím knížata jeho i moudré jeho, vývody jeho i znamenitější jeho i silné jeho, aby zesnuli snem věčným, a neprocítili, dí král, jehož jméno jest Hospodin zástupů.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 58, 'Takto praví Hospodin zástupů: Oboje zed Babylonská velmi široká do gruntu zbořena bude, a brány jeho vysoké ohněm spáleny budou, a tak nadarmo pracovati budou lidé a národové při ohni, až ustanou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 59, 'Slovo, kteréž přikázal Jeremiáš prorok Saraiášovi synu Neriášovu, synu Maaseiášovu, když se vypravil od Sedechiáše krále Judského do Babylona, léta čtvtého kralování jeho, (byl pak Saraiáš kníže Menuchské),');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 60, 'Když sepsal Jeremiáš všecko zlé, kteréž přijíti mělo na Babylon, do knihy jedné, všecka ta slova, kteráž jsou psána proti Babylonu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 61, 'I řekl Jeremiáš Saraiášovi: Když přijdeš do Babylona, a uzříš jej, tedy čti všecka ta slova.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 62, 'A rci: Ó Hospodine, ty jsi mluvil o místě tomto, že je zkazíš, tak že nebude v něm obyvatele, od člověka až do hovada, ale že hrozně zpuštěno na věky bude.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 63, 'Když pak do konce přečteš knihu tuto, přivaž k ní kámen, a hoď ji do prostřed Eufrates,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 64, 'A rci: Tak potopen bude Babylon, a nepovstane z toho zlého, kteréž já uvedu na něj, ačkoli ustávati budou. Až potud slova Jeremiášova.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 1, 'V jedenmecítma letech byl Sedechiáš, když počal kralovati, a jedenácte let kraloval v Jeruzalémě. Jméno matky jeho bylo Chamutal, dcera Jeremiášova z Lebna.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 2, 'I činil to, což jest zlého před očima Hospodinovýma, všecko tak, jakž byl dělal Joakim.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 3, 'Nebo se to dálo pro rozhněvání Hospodinovo proti Jeruzalému a Judovi, až je i zavrhl od tváři své. V tom zprotivil se Sedechiáš králi Babylonskému.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 4, 'Stalo se pak léta devátého kralování jeho, měsíce desátého, v desátý den téhož měsíce, že přitáhl Nabuchodonozor král Babylonský se vším vojskem svým k Jeruzalému, a položili se u něho, a vzdělali proti němu hradbu vůkol.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 5, 'A bylo město obleženo až do jedenáctého léta krále Sedechiáše.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 6, 'V kterémžto, měsíce čtvrtého, devátého dne téhož měsíce, rozmohl se hlad v městě, a neměl chleba lid země.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 7, 'I prolomeny jsou zdi městské, a všickni muži bojovní utekli, a vyšli z města v noci skrze bránu mezi dvěma zdmi, u zahrady královské, (Kaldejští pak leželi okolo města), a ušli cestou pouště.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 8, 'I honilo vojsko Kaldejské krále, a postihli Sedechiáše na rovinách Jerišských, a všecko vojsko jeho rozprchlo se od něho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 9, 'A tak javše krále, přivedli ho k králi Babylonskému do Ribla v zemi Emat, kdežto učinil o něm soud.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 10, 'I zmordoval král Babylonský syny Sedechiášovy před očima jeho, ano i všecka knížata Judská zmordoval v Ribla.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 11, 'Oči pak Sedechiášovy oslepil, a svázav ho řetězy ocelivými král Babylonský, dal jej dovésti do Babylona, a dal jej do vězení až do dne smrti jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 12, 'Potom měsíce pátého, desátého dne téhož měsíce, léta devatenáctého kralování Nabuchodonozora krále Babylonského, přitáhl Nebuzardan, hejtman nad žoldnéři, kterýž sloužíval králi Babylonskému, do Jeruzaléma.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 13, 'A zapálil dům Hospodinův, i dům královský, i všecky domy v Jeruzalémě, a tak všecky domy veliké vypálil ohněm.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 14, 'Všecky také zdi Jeruzalémské vůkol pobořilo všecko vojsko Kaldejské, kteréž bylo s tím hejtmanem nad žoldnéři.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 15, 'Přitom z chaterného lidu, totiž ostatek lidu, kterýž byl zůstal v městě, i poběhlce, kteříž byli ustoupili k králi Babylonskému, a jiný obecný lid zavedl Nebuzardan, hejtman nad žoldnéři.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 16, 'Toliko něco chaterného lidu země zanechal Nebuzardan, hejtman nad žoldnéři, aby byli vinaři a oráči.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 17, 'Nadto sloupy měděné, kteříž byli v domě Hospodinově, i podstavky i moře měděné, kteréž bylo v domě Hospodinově, ztloukli Kaldejští, a odvezli všecku měď z nich do Babylona.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 18, 'Též hrnce. lopaty a nástroje hudebné, a kotlíky a kadidlnice, i všecky nádoby měděné, jimiž sloužili, pobrali.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 19, 'I medenice a nádoby k oharkům, s kotlíky a hrnci, a svícny, a kadidlnice a koflíky, a cožkoli zlatého a stříbrného bylo, pobral hejtman nad žoldnéři;');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 20, 'Sloupy dva, moře jedno, a volů dvanáct měděných, kteříž byli pod podstavky, jichž byl nadělal král Šalomoun do domu Hospodinova. Nebylo váhy mědi všech těch nádob.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 21, 'Nebo sloupů těch, osmnácti loket byla výška sloupu jednoho, kterýž okolek měl dvanácti loktů, ztlouští pak čtyř prstů byl dutý.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 22, 'A makovice na něm měděná, a makovice jedné výška pěti loket, a mřežování i jablka zrnatá na té makovici vůkol; všecko bylo měděné. Takovýž byl i sloup druhý s zrnatými jablky.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 23, 'A bylo jablek zrnatých devadesát a šest po každé straně; všudy jablek zrnatých bylo po stu na mřežování vůkol.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 24, 'Vzal také hejtman nad žoldnéři Saraiáše kněze předního, a Sofoniáše kněze nižšího, a tři strážné prahu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 25, 'A z města vzal komorníka jednoho, kterýž byl hejtmanem nad muži bojovnými, a sedm mužů, jenž bývali při králi, kteříž nalezeni byli v městě, a předního spisovatele vojska, kterýž popisoval vojsko z lidu země, a šedesáte mužů z lidu země, kteříž nalezeni byli v městě.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 26, 'Zjímav tedy je Nebuzardan, hejtman nad žoldnéři, přivedl je k králi Babylonskému do Ribla.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 27, 'I pobil je král Babylonský, a zmordoval je v Ribla v zemi Emat, a tak zaveden jest Juda z země své.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 28, 'Tenť jest lid, kterýž zavedl Nabuchodonozor léta sedmého, Judských tři tisíce a třimecítma.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 29, 'Léta osmnáctého Nabuchodonozora zavedl z Jeruzaléma duší osm set třidceti a dvě.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 30, 'Léta třimecítmého Nabuchodonozora zavedl Nebuzardan, hejtman nad žoldnéři, Judské, duší sedm set čtyřidceti a pět, všech duší čtyry tisíce a šest set.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 31, 'Stalo se také třidcátého sedmého léta po zajetí Joachina krále Judského, dvanáctého měsíce, dvadcátého pátého dne téhož měsíce, povýšil Evilmerodach král Babylonský toho léta, když počal kralovati, Joachina krále Judského, pustiv ho z žaláře.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 32, 'A mluvil s ním dobrotivě, i stolici jeho postavil nad stolice králů, kteříž s ním byli v Babyloně.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 33, 'Změnil též roucho jeho, kteréž měl v žaláři, a jídal chléb před ním vždycky, po všecky dny života svého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 34, 'Nebo vyměřený pokrm ustavičně dáván byl jemu od krále Babylonského, a to na každý den, až do dne smrti jeho, po všecky dny života jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 1, 'Ach, město tak lidné, jakť jest samotné zůstalo, a učiněno jako vdova! Nejznamenitější mezi národy, přední mezi krajinami pod plat uvedeno.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 2, 'Ustavičně pláče v noci, a slzy jeho na lících jeho, ze všech milovníků svých nemá žádného potěšitele; všickni přátelé jeho nevěrně se k němu mají, obrátili se mu v nepřátely.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 3, 'Zastěhoval se Juda, proto že byl trápen a u veliké porobě, však osadiv se mezi pohany, nenalézá odpočinutí; všickni, kteříž jej honí, postihají jej v těsně.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 4, 'Cesty Siona kvílí, že žádný nepřichází k slavnosti. Všecky brány jeho zpustly, kněží jeho vzdychají, panny jeho smutné jsou, on pak sám pln jest hořkosti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 5, 'Nepřátelé jeho jsou hlavou, odpůrcům jeho šťastně se vede; nebo jej Hospodin zarmoutil pro množství přestoupení jeho. Maličcí jeho odešli do zajetí před oblíčejem nepřítele.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 6, 'A tak odňata od dcery Sionské všecka okrasa její. Knížata její jsou podobná jelenům, kteříž nenalézají pastvy, a ucházejí bez moci před tím, kdož je honí.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 7, 'Rozpomínáť se dcera Jeruzalémská ve dnech trápení svého a kvílení svého na všecka svá utěšení, kteráž mívala ode dnů starodávních, když padá lid její od ruky nepřítele, nemajíc žádného, kdo by ji retoval. Protivníciť se jí dívajíce, posmívají se klesnutí jejímu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 8, 'Těžce hřešila dcera Jeruzalémská, protož jako nečistá odloučena jest. Všickni, kteříž ji v poctivosti mívali, neváží jí sobě, proto že vidí nahotu její; ona pak vzdychá, obrácena jsuci zpět.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 9, 'Nečistota její na podolcích jejích; nepamatovala na skončení své, protož patrně klesá, nemajíc žádného, kdo by ji potěšil. Popatřiž, Hospodine, na trápení mé, neboť se vyvýšil nepřítel.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 10, 'Sáhl rukou svou nepřítel na všecky drahé věci její; nebo musí se dívati pohanům, an chodí do svatyně její, o čemž jsi byl přikázal, aby tobě nevcházeli do shromáždění.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 11, 'Všecken lid její vzdychajíce, hledají chleba, vynakládají nejdražší věci své za pokrm k očerstvení života. Vzezřiž, Hospodine, a popatřiž, neboť jsem v nevážnosti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 12, 'Nic-liž vám do toho, ó všickni, kteříž tudyto jdete? Pohleďte a vizte, jest-li bolest podobná bolesti mé, kteráž jest mi učiněna, jak mne zámutkem naplnil Hospodin v den prchlivosti hněvu svého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 13, 'Seslal s výsosti oheň do kostí mých, kterýž opanoval je; roztáhl sít nohám mým, obrátil mne zpět, obrátil mne v pustinu, celý den neduživá jsem.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 14, 'Tuze svázáno jest rukou jeho jho přestoupení mých, tuze spletené houžve připadly na hrdlo mé, porazilo sílu mou; vydal mne Pán v ruku nepřátel, nemohuť povstati.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 15, 'Pošlapal Pán všecky mé silné u prostřed mne, svolal proti mně zástupy, aby potřel mládence mé, tlačil Pán presem pannu dceru Judskou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 16, 'Pro tyť věci já pláči, z očí mých, z očí mých tekou vody, a že jest vzdálen ode mne potěšitel, kterýž by očerstvil duši mou; synové moji jsou pohubeni, nebo ssilil se nepřítel.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 17, 'Rozprostírá dcera Sionská ruce své, nemá žádného, kdo by ji potěšil; vzbudiltě Hospodin proti Jákobovi všudy vůkol něho nepřátely jeho, mezi nimiž jest dcera Jeruzalémská jako pro nečistotu oddělená.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 18, 'Spravedlivý jest Hospodin, neboť jsem na odpor činila ústům jeho. Slyšte medle všickni lidé, a vizte bolest mou; panny mé i mládenci moji odebrali se do zajetí.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 19, 'Volala jsem na milovníky své, oni oklamali mne; kněží moji a starci moji v městě pomřeli, hledajíce pokrmu, aby posilnili života svého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 20, 'Popatřiž, ó Hospodine, neboť mi úzko; vnitřnosti mé zkormouceny jsou, srdce mé svadne ve mně, proto že jsem na odpor velice činila. Vně meč na sirobu přivodí, v domě pouhá smrt.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 21, 'Slýchajíť, že já vzdychám, ale není žádného, kdo by mne potěšil. Všickni nepřátelé moji slyšíce o mých bídách, radují se, že jsi to učinil, a přivedl den předohlášený, ale budouť mně podobní.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 22, 'Nechť přijde všecka nešlechetnost jejich před oblíčej tvůj, a učiň jim, jakož jsi učinil mně pro všecka přestoupení má; neboť jsou mnohá úpění má, a srdce mé neduživé.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 1, 'Jak hustým oblakem prchlivosti své přikryl Pán dceru Sionskou! Shodil s nebe na zem slávu Izraelovu, aniž se rozpomenul na podnože noh svých v den prchlivosti své.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 2, 'Sehltil Pán beze vší lítosti všecky příbytky Jákobovy, zbořil v prchlivosti své ohrady dcery Judské, udeřil jimi o zem, v potupu uvedl království i knížata její.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 3, 'Odťal v rozpálení hněvu všecken roh Izraelův, odvrátil zpět pravici svou od nepřítele, a rozpáliv se proti Jákobovi jako oheň plápolající, pálí do cela vůkol.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 4, 'Natáhl lučiště své jako nepřítel, postavil pravici svou jako protivník, i zbil všecky nejzdařilejší z lidu, a vylil do stánku dcery Sionské jako oheň prchlivost svou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 5, 'Učiněn jest Pán podobný nepříteli, sehltil Izraele, sehltil všecky paláce jeho, zkazil ohrady jeho, a rozmnožil v lidu Judském zámutek a žalost.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 6, 'Mocí zajisté odtrhl jako od zahrady plot svůj, zkazil stánek svůj, v zapomenutí uvedl Hospodin na Sionu slavnost a sobotu, a v prchlivosti hněvu svého zavrhl krále i kněze.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 7, 'Zavrhl Pán oltář svůj, v ošklivost vzal svatyni svou, vydal v ruku nepřítele zdi a paláce Sionské; křičeli v domě Hospodinově jako v den slavnosti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 8, 'Uložiltě Hospodin zkaziti zed dcery Sionské, roztáhl šňůru, a neodvrátil ruky své od zhouby; pročež val i zed kvílí, a spolu mdlejí.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 9, 'Poraženy jsou na zem brány její, zkazil a polámal závory její; král její i knížata její mezi pohany. Není ani zákona, proroci také její nemívají vidění od Hospodina.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 10, 'Starší dcery Sionské usadivše se na zemi, mlčí, posýpají prachem hlavy své, a přepasují se žíněmi panny Jeruzalémské, svěšují k zemi hlavy své.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 11, 'Zhynuly od slz oči mé, zkormoutily se vnitřnosti mé, a vykydla se na zem játra má, pro potření dcery lidu mého, když i nemluvňátka a prsí požívající na ulicích města se svírají.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 12, 'A říkají matkám svým: Kdež jest obilé a víno? když se jako zraněný svírají po ulicích města, a vypouštějí duše své na klíně matek svých.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 13, 'Kohoť za svědka přivedu? Koho připodobním k tobě, ó dcero Jeruzalémská? Koho tobě přirovnám, abych tě potěšil, panno dcero Sionská? Nebo veliké jest jako moře potření tvé. Kdož by tě zhojiti mohl?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 14, 'Proroci tvoji předpovídali tobě lživé a ničemné věci, a neodkrývali nepravosti tvé, aby odvrátili zajetí tvé, ale předpovídali tobě těžkosti, oklamání a vyhnání.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 15, 'Všickni, kteříž jdou cestou, tleskají nad tebou rukama, diví se a potřásají hlavou svou za tebou, dcero Jeruzalémská, říkajíce: To-li jest to město, o němž říkávali, že jest nejkrásnější a utěšením vší země?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 16, 'Všickni nepřátelé tvoji rozdírají na tebe ústa svá, hvízdají a škřipí zuby, říkajíce: Sehlťme ji. Totoť jest jistě ten den, jehož jsme očekávali; jižtě nastal, vidíme.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 17, 'Učinil Hospodin to, což byl uložil, splnil řeč svou, kterouž přikazoval ode dnů starodávních, bořil bez lítosti, a obveselil nad tebou nepřítele, povýšil rohu protivníků tvých.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 18, 'Vykřikovalo srdce jejich proti Pánu. Ó ty zdi dcery Sionské, vylévej jako potok slzy dnem i nocí, nedávej sobě odpočinutí, aniž se spokojuj zřítelnice oka tvého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 19, 'Vstaň, křič v noci, při počátku bdění, vylévej jako vodu srdce své před oblíčejem Páně; pozdvihuj k němu rukou svých za život dítek svých svírajících se hladem, na rohu všech ulic, a rci:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 20, 'Pohleď, Hospodine, a popatř, komu jsi tak kdy učinil? Zdaliž jídají ženy plod svůj, nemluvňátka rozkošná? Zdaliž mordován býti má v svatyni Páně kněz a prorok?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 21, 'Leží na zemi po ulicích mladý i starý, panny mé i mládenci moji padli od meče, zmordoval jsi je, a zbil v den prchlivosti své bez lítosti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 22, 'Svolal jsi jako ke dni slavnosti z vůkolí ty, jichž se velice straším, a nebylo v den prchlivosti Hospodinovy, kdo by ušel neb pozůstal. Kteréž jsem na rukou pěstovala a vychovala, ty nepřítel můj do konce zhubil.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 1, 'Já jsem muž okoušející trápení od metly rozhněvání Božího.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 2, 'Zahnal mne, a uvedl do tmy a ne k světlu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 3, 'Toliko proti mně se postavuje, a obrací ruku svou přes celý den.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 4, 'Uvedl sešlost na tělo mé a kůži mou, a polámal kosti mé.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 5, 'Zastavěl mne a obklíčil přeodpornou hořkostí.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 6, 'Postavil mne v tmavých místech jako ty, kteříž již dávno zemřeli.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 7, 'Ohradil mne, abych nevyšel; obtížil ocelivý řetěz můj.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 8, 'A jakžkoli volám a křičím, zacpává uši před mou modlitbou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 9, 'Ohradil cesty mé tesaným kamenem, a stezky mé zmátl.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 10, 'Jest nedvěd číhající na mne, lev v skrejších.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 11, 'Cesty mé stočil, anobrž roztrhal mne, a na to mne přivedl, abych byl pustý.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 12, 'Natáhl lučiště své, a vystavil mne za cíl střelám.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 13, 'Postřelil ledví má střelami toulu svého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 14, 'Jsem v posměchu se vším lidem svým, a písničkou jejich přes celý den.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 15, 'Sytí mne hořkostmi, opojuje mne pelynkem.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 16, 'Nadto potřel o kameníčko zuby mé, vrazil mne do popela.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 17, 'Tak jsi vzdálil, ó Bože, duši mou od pokoje, až zapomínám na pohodlí,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 18, 'A říkám: Zahynulatě síla má i naděje má, kterouž jsem měl v Hospodinu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 19, 'A však duše má rozvažujíc trápení svá a pláč svůj, pelynek a žluč,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 20, 'Rozvažujíc to ustavičně, ponižuje se ve mně.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 21, 'A přivodě sobě to ku paměti, (naději mám),');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 22, 'Že veliké jest milosrdenství Hospodinovo, když jsme do konce nevyhynuli. Nepřestávajíť zajisté slitování jeho,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 23, 'Ale nová jsou každého jitra; převeliká jest pravda tvá.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 24, 'Díl můj jest Hospodin, říká duše má; protož naději mám v něm.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 25, 'Dobrý jest Hospodin těm, jenž očekávají na něj, duši té, kteráž ho hledá.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 26, 'Dobré jest trpělivě očekávajícímu na spasení Hospodinovo.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 27, 'Dobré jest muži tomu, kterýž by nosil jho od dětinství svého,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 28, 'Kterýž by pak byl opuštěn, trpělivě se má v tom, což na něj vloženo,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 29, 'Dávaje do prachu ústa svá, až by se ukázala naděje,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 30, 'Nastavuje líce tomu, kdož jej bije, a sytě se potupou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 31, 'Neboť nezamítá Pán na věčnost;');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 32, 'Nýbrž ačkoli zarmucuje, však slitovává se podlé množství milosrdenství svého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 33, 'Netrápíť zajisté z srdce svého, aniž zarmucuje synů lidských.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 34, 'Aby kdo potíral nohama svýma všecky vězně v zemi,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 35, 'Aby nespravedlivě soudil muže před oblíčejem Nejvyššího,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 36, 'Aby převracel člověka v při jeho, Pán nelibuje.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 37, 'Kdo jest, ješto když řekl, stalo se něco, a Pán nepřikázal?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 38, 'Z úst Nejvyššího zdali nepochází zlé i dobré?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 39, 'Proč by tedy sobě stýskal člověk živý, muž nad kázní za hříchy své?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 40, 'Zpytujme raději a ohledujme cest našich, a navraťme se až k Hospodinu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 41, 'Pozdvihujme srdcí i rukou svých k Bohu silnému v nebe.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 42, 'Myť jsme se zpronevěřili, a zpurní jsme byli, protož ty neodpouštíš.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 43, 'Obestřels se hněvem a stiháš nás, morduješ a nešanuješ.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 44, 'Obestřels se oblakem, aby nemohla proniknouti k tobě modlitba.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 45, 'Za smeti a povrhel položil jsi nás u prostřed národů těchto.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 46, 'Rozdírají na nás ústa svá všickni nepřátelé naši.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 47, 'Strach a jáma potkala nás, zpuštění a setření.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 48, 'Potokové vod tekou z očí mých pro potření dcery lidu mého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 49, 'Oči mé slzí bez přestání, proto že není žádného odtušení,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 50, 'Ažby popatřil a shlédl Hospodin s nebe.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 51, 'Oči mé rmoutí duši mou pro všecky dcery města mého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 52, 'Loviliť jsou mne ustavičně, jako ptáče, nepřátelé moji bez příčiny.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 53, 'Uvrhli do jámy život můj, a přimetali mne kamením.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 54, 'Rozvodnily se vody nad hlavou mou, řekl jsem: Jižtě po mně.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 55, 'Vzývám jméno tvé, ó Hospodine, z jámy nejhlubší.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 56, 'Hlas můj vyslýchával jsi; nezacpávejž ucha svého před vzdycháním mým a voláním mým.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 57, 'V ten den, v němž jsem tě vzýval, přicházeje, říkávals: Neboj se.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 58, 'Pane, zasazuje se o při duše mé, vysvobozoval jsi život můj.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 59, 'Vidíš, ó Hospodine, převrácenost, kteráž se mně děje, dopomoziž mi k spravedlnosti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 60, 'Vidíš všecko vymstívání se jejich, všecky úklady jejich proti mně.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 61, 'Slýcháš utrhání jejich, ó Hospodine, i všecky obmysly jejich proti mně,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 62, 'Řeči povstávajících proti mně, a přemyšlování jejich proti mně přes celý den.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 63, 'Pohleď, jak při sedání jejich i povstání jejich jsem písničkou jejich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 64, 'Dej jim odplatu, Hospodine, podlé díla rukou jejich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 65, 'Dej jim zatvrdilé srdce a prokletí své na ně.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 66, 'Stihej v prchlivosti, a vyhlaď je, ať nejsou pod nebem tvým.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 1, 'Jak tě zašlo zlato, změnilo se ryzí zlato nejvýbornější, rozmetáno jest kamení svaté sem i tam po všech ulicích.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 2, 'Synové Sionští nejdražší, kteříž ceněni býti měli za zlato nejčištší, jakť jsou počteni za nádoby hliněné, dílo rukou hrnčíře!');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 3, 'An draci vynímajíce prsy, krmí mladé své, dcera pak lidu mého příčinou ukrutníka podobná jest sovám na poušti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 4, 'Jazyk prsí požívajícího přilnul žízní k dásním jeho; děti prosí za chléb, ale není žádného, kdo by lámal jim.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 5, 'Ti, kteříž jídali rozkošné krmě, hynou na ulicích; kteříž chováni byli v šarlatě, octli se v hnoji.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 6, 'Větší jest trestání dcery lidu mého, než pomsta Sodomy, kteráž podvrácena jest jako v okamžení, aniž trvaly při ní rány.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 7, 'Čistší byli Nazareové její než sníh, bělejší než mléko, rděla se těla jejich více než drahé kamení, jako by z zafiru vytesáni byli.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 8, 'Ale již vzezření jejich temnější jest než černost, nemohou poznáni býti na ulicích; přischla kůže jejich k kostem jejich, prahne, jest jako dřevo.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 9, 'Lépe se stalo těm, jenž zbiti jsou mečem, nežli kteříž mrou hladem, (oni zajisté zhynuli, probodeni byvše), pro nedostatek úrod polních.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 10, 'Ruce žen lítostivých vařily syny své, aby jim byli za pokrm v potření dcery lidu mého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 11, 'Všelijak vypustil Hospodin prchlivost svou, vylévá zůřivost hněvu svého, a zapálil oheň na Sionu, kterýž sežral základy jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 12, 'Králové země i všickni obyvatelé okršlku světa nikoli by neuvěřili, by měl byl vjíti protivník a nepřítel do bran Jeruzalémských,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 13, 'Pro hříchy proroků jeho a nepravosti kněží jeho, vylévajících u prostřed něho krev spravedlivých.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 14, 'Toulali se jako slepí po ulicích, kálejíce se ve krvi, kteréž nemohli se než dotýkati oděvy svými.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 15, 'Volali na ně: Ustupujte nečistí, ustupujte, ustupujte, nedotýkejte se. Právěť jsou ustoupili, anobrž sem i tam se rozlezli, až mezi národy říkají: Nebudouť více míti vlastního bydlení.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 16, 'Tvář hněvivá Hospodinova rozptýlila je, aniž na ně více popatří; nepřátelé kněží nešanují, starcům milosti nečiní.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 17, 'A vždy ještě až do ustání očí svých hledíme o pomoc sobě neprospěšnou, zření majíce k národu, nemohoucímu vysvoboditi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 18, 'Šlakují kroky naše, tak že ani po ulicích našich choditi nemůžeme; přiblížilo se skončení naše, doplnili se dnové naši, přišlo zajisté skončení naše.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 19, 'Rychlejší jsou ti, kteříž nás stihají, než orlice nebeské; po horách stihají nás, na poušti zálohy nám zdělali.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 20, 'Dýchání chřípí našich, totiž pomazaný Hospodinův, lapen jest v jamách jejich, o němž jsme říkali: V stínu jeho živi budeme mezi národy.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 21, 'Raduj se a vesel se, dcero Idumejská, kteráž jsi se usadila v zemi Uz. Takéť k tobě přijde kalich, opiješ se a obnažíš se.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 22, 'Ó dcero Sionská, když vykonána bude kázeň nepravosti tvé, nenechá tě déle v zajetí tvém. Ale tvou nepravost, ó dcero Idumejská, trestati bude a odkryje hříchy tvé.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 1, 'Rozpomeň se, Hospodine, co se nám děje; popatř a viz pohanění naše.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 2, 'Dědictví naše obráceno jest k cizím, domové naši k cizozemcům.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 3, 'Sirotci jsme a bez otce, matky naše jsou jako vdovy.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 4, 'Vody své za peníze pijeme, dříví naše za záplatu přichází.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 5, 'Na hrdle svém protivenství snášíme, pracujeme, nedopouští se nám odpočinouti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 6, 'Egyptským podáváme ruky i Assyrským, abychom nasyceni byli chlebem.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 7, 'Otcové naši hřešili, není jich, my pak trestáni po nich neseme.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 8, 'Služebníci panují nad námi; není žádného, kdo by vytrhl z ruky jejich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 9, 'S opovážením se života svého hledáme chleba svého, pro strach meče i na poušti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 10, 'Kůže naše jako pec zčernaly od náramného hladu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 11, 'Ženám na Sionu i pannám v městech Judských násilé činí.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 12, 'Knížata rukou jejich zvěšena jsou, osoby starých nemají v poctivosti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 13, 'Mládence k žernovu berou, a pacholata pod dřívím klesají.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 14, 'Starci sedati v branách přestali a mládenci od zpěvů svých.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 15, 'Přestala radost srdce našeho, obrátilo se v kvílení plésání naše.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 16, 'Spadla koruna s hlavy naší; běda nám již, že jsme hřešili.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 17, 'Protoť jest mdlé srdce naše, pro tyť věci zatměly se oči naše,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 18, 'Pro horu Sion, že zpuštěna jest; lišky chodí po ní.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 19, 'Ty Hospodine, na věky zůstáváš, a stolice tvá od národu do pronárodu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 20, 'Proč se zapomínáš na věky na nás, a opouštíš nás za tak dlouhé časy?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 21, 'Obrať nás, ó Hospodine, k sobě, a obráceni budeme; obnov dny naše, jakž byly za starodávna.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 22, 'Nebo zdali všelijak zavržeš nás, a hněvati se budeš na nás velice?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 1, 'Stalo se pak třidcátého léta, čtvrtého měsíce, dne pátého, když jsem byl mezi zajatými u řeky Chebar, že otevřína byla nebesa, a viděl jsem vidění Boží.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 2, 'Pátého dne téhož měsíce, pátého léta zajetí krále Joachina,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 3, 'V pravdě stalo se slovo Hospodinovo k Ezechielovi knězi, synu Buzi, v zemi Kaldejské u řeky Chebar, a byla nad ním ruka Hospodinova.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 4, 'I viděl jsem, a aj, vítr tuhý přicházel od půlnoci, a oblak veliký, a oheň plápolající, a okolo něho byl blesk, a z prostředku jeho jako nějaká velmi prudká světlost, z prostředku toho ohně.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 5, 'Z prostředku jeho také ukázalo se podobenství čtyř zvířat, jejichž takový byl způsob: Podobenství člověka měli.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 6, 'A po čtyřech tvářích jedno každé, a po čtyřech křídlích jedno každé mělo.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 7, 'Jejichž nohy nohy přímé, ale zpodek noh jejich jako zpodek nohy telecí, a blyštěly se podobně jako ocel pulerovaná.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 8, 'Ruce pak lidské pod křídly jejich, po čtyřech stranách jejich, a tváři jejich i křídla jejich na čtyřech těch stranách.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 9, 'Spojena byla křídla jejich jednoho s druhým. Neobracela se, když šla; jedno každé přímo na svou stranu šlo.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 10, 'Podobenství pak tváří jejich s předu tvář lidská, a tvář lvová po pravé straně každého z nich; tvář pak volovou po levé straně všech čtvero, též tvář orličí s zadu mělo všech čtvero z nich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 11, 'A tváři jejich i křídla jejich pozdvižena byla zhůru. Každé zvíře dvě křídla pojilo s křídly dvěma druhého, dvěma pak přikrývala těla svá.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 12, 'A každé přímo na svou stranu šlo. Kamkoli ukazoval duch, aby šla, tam šla, neuchylovala se, když chodila.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 13, 'Podobnost také těch zvířat na pohledění byla jako uhlí řeřavého, na pohledění jako pochodně. Kterýžto oheň ustavičně chodil mezi zvířaty, a ten oheň měl blesk, a z téhož ohně vycházelo blýskání.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 14, 'Také ta zvířata běhala, a navracovala se jako prudké blýskání.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 15, 'A když jsem hleděl na ta zvířata, a aj, kolo jedno bylo na zemi při zvířatech u čtyř tváří jednoho každého z nich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 16, 'Na pohledění byla kola, a udělání jich jako barva tarsis, a podobnost jednostejnou měla všecka ta kola, a byla na pohledění i udělání jejich, jako by bylo kolo u prostřed kola.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 17, 'Na čtyři strany své jíti majíce, chodila, a neuchylovala se, když šla.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 18, 'A loukoti své, i vysokost měla, že hrůza z nich šla, a šínové jejich vůkol všech čtyř kol plní byli očí.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 19, 'Když pak chodila zvířata, chodila kola podlé nich, a když se vznášela zvířata vzhůru od země, vznášela se i kola.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 20, 'Kdekoli chtěl Duch, aby šla, tam šla; kde Duch chtěl jíti, i kola vznášela se naproti nim, nebo duch zvířat byl v kolách.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 21, 'Když ona šla, šla, a když ona stála, stála, a když se vznášela od země, vznášela se také kola s nimi, nebo duch zvířat byl v kolách.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 22, 'Podobenství pak oblohy bylo nad hlavami zvířat jako podobenství křištálu roztaženého nad hlavami jejich svrchu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 23, 'A pod oblohou křídla jejich pozdvižená byla, jedno připojené k druhému. Každé mělo dvě, jimiž se přikrývalo, každé, pravím, mělo dvě, jimiž přikrývalo tělo své.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 24, 'I slyšel jsem zvuk křídel jejich jako zvuk vod mnohých, jako zvuk Všemohoucího, když chodila, zvuk hluku jako zvuk vojska. Když pak stála, spustila křídla svá.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 25, 'Byl také zvuk svrchu nad oblohou, kteráž byla nad hlavou jejich, když stála a spustila křídla svá.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 26, 'Svrchu pak na obloze, kteráž byla nad hlavou jejich, bylo podobenství trůnu, na pohledění jako kámen zafirový, a nad podobenstvím trůnu na něm svrchu, na pohledění jako tvárnost člověka.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 27, 'I viděl jsem na pohledění jako velmi prudkou světlost, a u vnitřku jejím vůkol na pohledění jako oheň, od bedr jeho vzhůru; od bedr pak jeho dolů viděl jsem na pohledění jako oheň, a blesk vůkol něho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 28, 'Na pohledění jako duha, kteráž bývá na oblace v čas deště, takový na pohledění byl blesk vůkol. To bylo vidění podobenství slávy Hospodinovy. Kteréžto viděv, padl jsem na tvář svou, a slyšel jsem hlas mluvícího.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 2, 1, 'Kterýž řekl ke mně: Synu člověčí, postav se na nohy své, ať mluvím s tebou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 2, 2, 'I vstoupil do mne duch, když promluvil ke mně, a postavil mne na nohy mé, a slyšel jsem, an mluví ke mně.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 2, 3, 'Kterýž řekl mi: Synu člověčí, já tě posílám k synům Izraelským, k národům zpurným, kteříž zpurně se postavovali proti mně; oni i otcové jejich zpronevěřovali se mi, až právě do tohoto dne.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 2, 4, 'K těch, pravím, synům nestydaté tváři a zatvrdilého srdce já posílám tě, a díš k nim: Takto praví Panovník Hospodin,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 2, 5, 'Již oni slyšte neb nechte: Že dům zpurný jsou. Ať vědí, že prorok byl u prostřed nich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 2, 6, 'Ty pak synu člověčí, neboj se jich, aniž se boj slov jejich, že zpurní a jako trní jsou proti tobě, a že mezi štíry bydlíš. Slov jejich neboj se, a tváři jejich se nestrachuj, proto že dům zpurný jsou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 2, 7, 'Ale mluv slova má k nim, již oni slyšte neb nechte: Že zpurní jsou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 2, 8, 'Ty pak synu člověčí, slyš, co já pravím tobě: Nebuď zpurný jako ten dům zpurný. Otevři ústa svá, a sněz, co já tobě dám.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 2, 9, 'I viděl jsem, a aj, ruka vztažena byla ke mně, a aj, v ní svinutá kniha.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 2, 10, 'Kteroužto rozvinul přede mnou, a byla popsaná s předu i z zadu, a bylo v ní psáno naříkání, kvílení a běda.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 1, 'Tedy řekl mi: Synu člověčí, což před tebou jest, sněz, sněz knihu tuto, a jdi, mluv k domu Izraelskému.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 2, 'I otevřel jsem ústa svá, a dal mi snísti knihu tu,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 3, 'Řka ke mně: Synu člověčí, nakrm břicho své, a střeva svá naplň knihou touto, kteroužť dávám. I snědl jsem, a byla v ústech mých jako med sladká.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 4, 'Za tím řekl mi: Synu člověčí, jdiž k domu Izraelskému, a mluv k nim slovy mými.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 5, 'Nebo nebudeš poslán k lidu hluboké řeči a nesnadného jazyka, ale k domu Izraelskému.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 6, 'Ne k národům mnohým hluboké řeči a nesnadného jazyka, jejichž bys slovům nerozuměl, ješto, kdybych tě k nim poslal, uposlechli by tebe.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 7, 'Ale dům Izraelský nebudou tě chtíti poslouchati, poněvadž nechtí poslouchati mne; nebo všecken dům Izraelský jest tvrdočelný a zatvrdilého srdce.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 8, 'Ale učinil jsem tvář tvou tvrdou proti tváři jejich, a čelo tvé tvrdé proti čelu jejich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 9, 'Jako kámen přetvrdý, pevnější než skálu učinil jsem čelo tvé; nebojž se jich, aniž se strachuj tváři jejich, proto že dům zpurný jsou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 10, 'I řekl ke mně: Synu člověčí, všecka slova má, kterážť mluviti budu, přijmi v srdce své, a ušima svýma slyš.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 11, 'A jdi k zajatým, k synům lidu svého, a mluv k nim, a rci jim: Takto praví Panovník Hospodin, již oni slyšte neb nechte.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 12, 'Tehdy odnesl mne Duch, a slyšel jsem za sebou hlas hřmotu velikého: Požehnaná sláva Hospodinova z místa svého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 13, 'A hlas křídel těch zvířat, kteráž se vespolek dotýkala, a hlas kol naproti nim, a hlas hřmotu velikého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 14, 'Duch pak odnesl mne, a vzal mne, a odšel jsem truchliv, v hněvě ducha svého, ale ruka Hospodinova nade mnou silnější byla.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 15, 'I přišel jsem k zajatým do Telabib, bydlícím při řece Chebar, a seděl jsem, kdež oni bydlili. Seděl jsem, pravím, sedm dní u prostřed nich s užasnutím.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 16, 'I stalo se po dokonání sedmi dnů, že se stalo slovo Hospodinovo ke mně, řkoucí:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 17, 'Synu člověčí, strážným jsem tě postavil nad domem Izraelským, abys slyše slovo z úst mých, napomínal jich ode mne.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 18, 'Když bych já řekl bezbožnému: Smrtí umřeš, a nenapomenul bys ho, ani nemluvil, abys ho odvedl od cesty jeho bezbožné, proto abys ho při životu zachoval: ten bezbožný pro nepravost svou umře, ale krve jeho z ruky tvé vyhledám.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 19, 'Paklibys ty napomenul bezbožného, a neodvrátil by se od bezbožnosti své, a od cesty své bezbožné, onť pro nepravost svou umře, ale ty duši svou vysvobodíš.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 20, 'Odvrátil-li by se pak spravedlivý od spravedlnosti své, a činil by nepravost, a já bych položil urážku před něj, a tak by umřel, ty pak bys ho nenapomenul: pro hříchť svůj umře, aniž na pamět přijde která spravedlnost jeho, kterouž činil, ale krve jeho z ruky tvé vyhledám.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 21, 'Pakli bys ty napomenul spravedlivého, aby nehřešil spravedlivý, a on by nehřešil, jistě že bude živ; nebo napomenut byl. Ty také duši svou vysvobodíš.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 22, 'I byla tam nade mnou ruka Hospodinova, kterýžto řekl mi: Vstaň, jdi do tohoto údolí, a tam mluviti budu s tebou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 23, 'A tak vstav, šel jsem do toho údolí, a aj, sláva Hospodinova stála tam, jako sláva, kterouž jsem viděl u řeky Chebar. I padl jsem na tvář svou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 24, 'Tehdy vstoupil do mne Duch, a postaviv mne na nohy, mluvil ke mně, a řekl mi: Jdiž, zavři se v domě svém.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 25, 'Nebo na tě, synu člověčí, aj, dadí na tě provazy, a sváží tě jimi, a nebudeš moci vyjíti mezi ně.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 26, 'A já učiním, aby jazyk tvůj přilnul k dásním tvým, a abys oněměl, a nebyl jim mužem domlouvajícím, protože dům zpurný jsou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 27, 'Ale když mluviti budu s tebou, otevru ústa tvá, a díš jim: Takto praví Panovník Hospodin: Kdo slyšeti chce, nechť slyší, a kdo nechce, nechť nechá, že dům zpurný jsou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 1, 'Ty pak synu člověčí, vezmi sobě cihlu, a polože ji před sebe, vyrej na ní město Jeruzalém.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 2, 'A postav na ní obležení, a vzdělaje na ní šance, vysyp na ní násyp, a polož na ní vojska, a postav na ní berany válečné vůkol.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 3, 'Potom vezmi sobě pánev železnou, a polož ji místo zdi železné, mezi tebou a mezi městem, a zatvrď tvář svou proti němu, ať jest obleženo, a oblehneš je. Toť bude znamením domu Izraelskému.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 4, 'Ty pak lehni na levý bok svůj, a vlož na něj nepravost domu Izraelského. Podlé počtu dnů, v němž ležeti budeš na něm, poneseš nepravost jejich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 5, 'A já dávám tobě léta nepravosti jejich v počtu dnů, tři sta a devadesáte dnů, v nichž poneseš nepravost domu Izraelského.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 6, 'Když je pak vyplníš, budeš ležeti na pravém boku podruhé, a poneseš nepravost domu Judova čtyřidceti dnů. Den za rok, den za rok dávám tobě.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 7, 'K obležení, pravím, Jeruzaléma zatvrď tvář svou, ohrna ruku svou, a prorokuje proti němu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 8, 'A aj, dávám na tě provazy, abys se neobracel z boku jednoho na druhý, dokudž nevyplníš dnů obležení svého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 9, 'Protož ty vezmi sobě pšenice a ječmene, též bobu, šočovice, i prosa, a špaldy, a dej to do jedné nádoby, abys sobě nastrojil z toho pokrmu podlé počtu dnů, v nichž ležeti budeš na boku svém. Za tři sta a devadesáte dnů jísti jej budeš.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 10, 'Pokrmu pak tvého, kterýž jísti budeš, váha bude dvadceti lotů na den. Od času až do času jísti jej budeš.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 11, 'Vodu také na míru píti budeš, šestý díl hin; od času do času píti budeš.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 12, 'Podpopelný pak chléb ječný, kterýž jísti budeš, ten lejny nečistoty lidské pec před očima jejich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 13, 'I řekl Hospodin: Tak budou jísti synové Izraelští chléb svůj nečistý pro pohany, kteréž tam shromáždím.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 14, 'Tedy řekl jsem: Ach, Panovníče Hospodine, aj, duše má není poškvrněna mrchami, a udáveného nejedl jsem od dětinství svého až podnes, aniž vešlo v ústa má maso ohavné.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 15, 'Kterýž řekl mi: Aj, dávámť kravince místo lejn lidských, abys sobě jimi napekl chleba.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 16, 'Za tím řekl mi: Synu člověčí, aj, já zlámi hůl chleba v Jeruzalémě, tak že jísti budou chléb na váhu, a to s zámutkem, a vodu na míru píti, a to s předěšením,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 17, 'Aby nedostatek majíce v chlebě a v vodě, děsili se jeden každý z nich, a svadli pro nepravost svou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 1, 'Potom ty synu člověčí, vezmi sobě nůž ostrý, totiž břitvu holičů, vezmi jej sobě, a ohol ním hlavu i bradu svou. Potom vezma sobě váhu, rozděl to.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 2, 'Třetinu ohněm spal u prostřed města, když se vyplní dnové obležení; zatím vezma druhou třetinu, posekej mečem okolo něho; ostatní pak třetinu rozptyl u vítr. Nebo mečem dobytým budu je stihati.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 3, 'A však odejmi odtud něco málo, a zavaž do křídel svých.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 4, 'A i z těch ještě vezma, uvrz je do prostřed ohně, a spal je ohněm, odkudž vyjde oheň na všecken dům Izraelský.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 5, 'Takto praví Panovník Hospodin: Tento Jeruzalém, kterýž jsem postavil u prostřed pohanů, a vůkol otočil krajinami,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 6, 'Změnil soudy mé v bezbožnost více než pohané, a ustanovení má více než jiné země, kteréž jsou vůkol něho; nebo soudy mými pohrdli, a v ustanoveních mých nechodili.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 7, 'Protož takto praví Panovník Hospodin: Proto že mnohem více než pohané, kteříž jsou vůkol vás, v ustanoveních mých nechodili jste, a soudů mých nečinili jste, nýbrž ani tak jako pohané, kteříž jsou vůkol vás, soudů nekonali jste:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 8, 'Protož takto praví Panovník Hospodin: Aj, já na tebe, aj já, a vykonám u prostřed tebe soudy před očima pohanů.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 9, 'Nebo učiním při tobě to, čehož jsem prv neučinil, a čehož podobně neučiním více pro všecky ohavnosti tvé,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 10, 'Tak že otcové jísti budou syny u prostřed tebe, a synové jísti budou otce své, a vykonám proti tobě soudy, a rozptýlím všecky ostatky tvé na všecky strany.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 11, 'Protož živť jsem já, praví Panovník Hospodin, že poněvadž jsi ty svatyně mé poškvrnil všelikými mrzkostmi svými, a všelikými ohavnostmi svými, i já také zlehčím tebe, a neodpustíť oko mé, a nikoli se neslituji.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 12, 'Třetina tebe morem zemře a hladem zhyne u prostřed tebe, a třetina druhá mečem padne vůkol tebe, ostatní pak třetinu na všecky stany rozptýlím, a mečem dobytým stihati je budu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 13, 'A tak do konce vylit bude hněv můj, a dotru prchlivostí svou na ně, i potěším se. I zvědíť, že já Hospodin mluvil jsem v horlivosti své, když vykonám prchlivost svou na nich,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 14, 'A obrátím tě v poušť, a dám tě v útržku mezi národy, kteříž jsou vůkol tebe, před očima každého tudy jdoucího.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 15, 'A tak budeš k útržce, posměchu, k hroznému příkladu a k užasnutí národům, kteříž jsou vůkol tebe, tehdáž když vykonám proti tobě soudy v hněvě a v prchlivosti a v žehrání zůřivém. Já Hospodin mluvil jsem.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 16, 'Tehdáš když vystřelím jízlivé střely hladu k záhubě vaší, kteréž vystřelím, abych vás vyhubil, a hlad shromáždě proti vám, zlámi vám hůl chleba.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 17, 'Pošli zajisté na vás hlad a zvěř lítou, kteráž tě na sirobu přivede; i mor a krev přijde na tebe, když uvedu na tě meč. Já Hospodin mluvil jsem.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 6, 1, 'I stalo se ke mně slovo Hospodinovo, řkoucí:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 6, 2, 'Synu člověčí, obrať tvář svou proti horám Izraelským, a prorokuj proti nim,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 6, 3, 'A rci: Hory Izraelské, slyšte slovo Panovníka Hospodina: Takto praví Panovník Hospodin horám a pahrbkům, prudkým potokům a údolím: Aj, já, já uvedu na vás meč, a zkazím výsosti vaše.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 6, 4, 'A tak zpustnou oltářové vaši, a ztroskotáni budou sluneční obrazové vaši, a rozmeci zbité vaše před ukydanými bohy vašimi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 6, 5, 'Povrhu také mrtvá těla synů Izraelských před ukydanými bohy jejich, a rozptýlím kosti vaše okolo oltářů vašich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 6, 6, 'Kdekoli bydliti budete, města zpuštěna budou, a výsosti zpustnou. Pročež popléněni budou a zpustnou i oltářové vaši, potroskotáni budou a přestanou ukydaní bohové vaši, a sluneční obrazové vaši zpodtínáni, a tak vyhlazena budou díla vaše.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 6, 7, 'I padnou zbití u prostřed vás, a zvíte, že já jsem Hospodin.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 6, 8, 'A pozůstavím některé z vás, kteříž by ušli meče, mezi pohany, když rozptýleni budete do zemí.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 6, 9, 'I budou se rozpomínati na mne, kteříž z vás zachováni budou mezi národy, mezi něž budou zajati, že jsem kormoucen byl srdcem jejich smilným, kteréž odstoupilo ode mne, a očima jejich, kteréž smilníce, chodily za ukydanými bohy svými, a tak sami se býti hodné ošklivosti seznají pro nešlechetnosti, kteréž páchali ve všech ohavnostech svých.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 6, 10, 'A zvědí, že já jsem Hospodin, a že jsem ne nadarmo mluvil, že na ně uvedu zlé toto.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 6, 11, 'Takto praví Panovník Hospodin: Tleskni rukou svou, a dupni nohou svou, a rci: Nastojte na dům Izraelský, že pro všecky ohavnosti nejhorší mečem, hladem a morem padnouti mají.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 6, 12, 'Ten, kdož daleko bude, morem umře, a kdo blízko, mečem padne, ostatní pak a obležený hladem umře, a tak docela vyleji prchlivost svou na ně.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 6, 13, 'A zvíte, že já jsem Hospodin, když budou zbití jejich u prostřed ukydaných bohů jejich vůkol oltářů jejich, na všelikém pahrbku vysokém, na všech vrších hor, a pod všelikým dřevem zeleným, i pod všelikým dubem hustým, na kterémkoli místě obětovávali vůni libou všelikým ukydaným bohům svým.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 6, 14, 'Nebo vztáhnu ruku svou na ně, a učiním zemi tuto zpustlou, zpustlejší než poušť Diblat, po všech obydlích jejich. I zvědí, že já jsem Hospodin.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 1, 'Potom stalo se slovo Hospodinovo ke mně, řkoucí:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 2, 'Slyš, synu člověčí: Takto praví Panovník Hospodin o zemi Izraelské: Ach, skončení, přišlo skončení její na čtyři strany země.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 3, 'Jižtě skončení nastalo tobě; nebo vypustím hněv svůj na tě, a budu tě souditi podlé cest tvých, a uvrhu na tě všecky ohavnosti tvé.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 4, 'Neodpustí zajisté oko mé tobě, aniž se slituji, ale cesty tvé na tebe uvrhu, a ohavnosti tvé u prostřed tebe budou. I zvíte, že já jsem Hospodin.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 5, 'Takto praví Panovník Hospodin: Bída jedna, aj hle, přichází bída.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 6, 'Skončení přichází, přichází skončení, procítil na tě, aj, přicházíť.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 7, 'Přicházíť to jitro na tebe, obyvateli země, přicházíť ten čas, přibližuje se ten den hřmotu, a ne hlas rozléhající se po horách.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 8, 'Již tudíž vyliji prchlivost svou na tě, a docela vypustím hněv svůj na tebe, a budu tě souditi podlé cest tvých, a uvrhu na tě všecky ohavnosti tvé.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 9, 'Neodpustíť zajisté oko mé, aniž se slituji, ale podlé cest tvých zaplatím tobě, a budou ohavnosti tvé u prostřed tebe. A tak zvíte, že já jsem Hospodin, ten, kterýž biji.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 10, 'Aj, teď jest ten den, aj, přicházeje, přišlo to jitro, zkvetl prut, vypučila se z něho pýcha,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 11, 'Ukrutnost vzrostla v prut bezbožnosti. Nezůstaneť z nich nic, ani z množství jejich, ani z hluku jejich, aniž bude naříkáno nad nimi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 12, 'Přicházíť ten čas, blízko jest ten den. Kdo koupí, nebude se veseliti, a kdo prodá, nic toho nebude litovati; nebo prchlivost přijde na všecko množství její.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 13, 'Ten zajisté, kdož prodal, k věci prodané nepůjde nazpět, by pak ještě byl mezi živými život jejich, poněvadž vidění na všecko množství její nenavrátí se, a žádný v nepravosti života svého nezmocní se.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 14, 'Troubiti budou v troubu, a připraví všecko, ale nebude žádného, kdo by šel k boji; nebo prchlivost má oboří se na všecko množství její.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 15, 'Meč bude vně, mor pak a hlad doma; kdo bude na poli, mečem zabit bude, toho pak, kdož bude v městě, hlad a mor zahubí.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 16, 'Kteříž pak z nich utekou, ti na horách, jako holubice v údolí, všickni lkáti budou, jeden každý pro nepravost svou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 17, 'Všeliké ruce klesnou, a všeliká kolena rozplynou se jako voda.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 18, 'I přepáší se žíněmi, a hrůza je přikryje, a na všeliké tváři bude stud, a na všech hlavách jejich lysina.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 19, 'Stříbro své po ulicích rozházejí, a zlato jejich bude jako nečistota; stříbro jejich a zlato jejich nebude jich moci vysvoboditi v den prchlivosti Hospodinovy. Nenasytí se, a střev svých nenaplní, proto že nepravost jejich jest jim k urážce,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 20, 'A že v slávě okrasy své, v té, kterouž k důstojnosti postavil Bůh, obrazu ohavností svých a mrzkostí svých nadělali. Protož obrátil jsem jim ji v nečistotu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 21, 'Nebo vydám ji v ruku cizozemců k rozchvátání, a bezbožným na zemi za loupež, kteříž poškvrní jí.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 22, 'Odvrátím též tvář svou od nich, i poškvrní svatyně mé, a vejdou do ní, boříce a poškvrňujíce jí.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 23, 'Udělej řetěz, nebo země plná jest soudů ukrutných, a město plné jest nátisku.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 24, 'Protož přivedu nejhorší z pohanů, aby dědičně vládli domy jejich; i učiním přítrž pýše silných, a poškvrněni budou, kteříž jich posvěcují.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 25, 'Zkažení přišlo, protož hledati budou pokoje, ale žádného nebude.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 26, 'Bída za bídou přijde, a novina bude za novinou, i budou hledati vidění od proroka, ale zákon zahyne od kněze, a rada od starců.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 27, 'Král ustavičně kvíliti bude, a kníže obleče se v smutek, a ruce lidu v zemi předěšeny budou. Podlé cesty jejich učiním jim, a podlé soudů jejich souditi je budu. I zvědí, že já jsem Hospodin.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 1, 'I stalo se léta šestého, v pátý den šestého měsíce, že jsem seděl v domě svém, a starší Judští seděli přede mnou. I připadla na mne tu ruka Panovníka Hospodina.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 2, 'A viděl jsem, a aj, podobenství na pohledění jako oheň. Od bedr jeho dolů oheň, od bedr pak jeho vzhůru na pohledění jako blesk, na pohledění jako nějaká velmi prudká světlost.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 3, 'Tedy vztáh podobenství ruky, vzal mne za kštici hlavy mé, a vyzdvihl mne Duch mezi nebe a mezi zemi, a uvedl mne do Jeruzaléma u viděních Božích, k vratům brány vnitřní, kteráž patří na půlnoci, kdež byla stolice modly k horlivosti a k zůřivosti popouzející.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 4, 'A aj, sláva Boha Izraelského byla tam na pohledění jako ta, kterouž jsem viděl v údolí.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 5, 'I řekl mi: Synu člověčí, pozdvihni nyní očí svých k cestě na půlnoci. Tedy pozdvihl jsem oči svých k cestě na půlnoci, a aj, na půlnoci u brány oltářové ta modla horlení, právě kudyž se vchází.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 6, 'V tom řekl mi: Synu člověčí, vidíš-liž ty, co tito činí, ohavnosti tak veliké, kteréž činí dům Izraelský tuto, tak že se vzdáliti musím od svatyně své? Ale obrátě se, uzříš ještě větší ohavnosti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 7, 'I přivedl mne ke dveřům síně, kdež jsem uzřel, a aj, díra jedna byla v stěně.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 8, 'A řekl mi: Synu člověčí, kopej medle tu stěnu. I kopal jsem stěnu, a aj, dvéře jedny.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 9, 'Tedy řekl mi: Vejdi, a viz ohavnosti tyto nejhorší, kteréž oni činí zde.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 10, 'Protož všed, uzřel jsem, a aj, všeliké podobenství zeměplazů a hovad ohyzdných, i všech ukydaných bohů domu Izraelského vyryto bylo na stěně vůkol a vůkol.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 11, 'A sedmdesáte mužů z starších domu Izraelského, s Jazaniášem synem Safanovým, stojícím u prostřed nich, stáli před nimi, maje každý kadidlnici svou v ruce své, tak že hustý oblak kadění vzhůru vstupoval.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 12, 'I řekl mi: Viděl-lis, synu člověčí, co starší domu Izraelského činí ve tmě, jeden každý v pokojích svých malovaných? Nebo říkají: Nikoli na nás nepatří Hospodin, opustil Hospodin zemi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 13, 'Dále mi řekl: Obrátě se, uzříš ještě větší ohavnosti, kteréž oni činí.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 14, 'I přivedl mne k vratům brány domu Hospodinova, kteráž jest na půlnoci, a aj, ženy seděly tam, plačíce Tammuze.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 15, 'I řekl mi: Viděl-lis, synu člověčí? Obrátě se, uzříš ještě větší ohavnosti nad tyto.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 16, 'Tedy uvedl mne do síně domu Hospodinova vnitřní, a aj, u vrat chrámu Hospodinova, mezi síňcí a oltářem bylo okolo pětmecítma mužů, jejichž záda byla k chrámu Hospodinovu, tváři pak jejich k východu, kteříž klaněli se proti východu slunce.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 17, 'I řekl mi: Viděl-lis, synu člověčí? Zdali lehká věc jest domu Judovu, aby činili ohavnosti tyto, kteréž činí zde? Nebo naplnivše zemi nátiskem, obrátili se, aby mne popouzeli, a aj, přičinějí ratolest vinnou k nosům svým.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 18, 'Protož i já také učiním podlé prchlivosti; neslitujeť se oko mé, aniž se smiluji. I budou volati v uši mé hlasem velikým, a nevyslyším jich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 9, 1, 'Potom zavolal hlasem velikým, tak že jsem slyšel, řka: Přistupte hejtmané k tomuto městu, a jeden každý s zbrojí svou hubící v ruce své.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 9, 2, 'A aj, šest mužů přišlo cestou k bráně hořejší, kteráž patří na půlnoci, maje každý zbroj svou rozrážející v ruce své. Muž pak jeden byl u prostřed nich, oděný rouchem lněným, a kalamář písařský při bedrách jeho; a přišedše, stáli u oltáře měděného.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 9, 3, 'Sláva pak Boha Izraelského sstoupila byla s cherubína, na kterémž byla, k prahu domu, a zvolala na muže toho oděného rouchem lněným, při jehož bedrách byl kalamář písařský.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 9, 4, 'I řekl jemu Hospodin: Přejdi prostředkem města, prostředkem Jeruzaléma, a znamenej znamením na čelích muže ty, kteříž vzdychají a naříkají nade všemi ohavnostmi dějícími se u prostřed něho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 9, 5, 'Oněmno pak řekl tak, že jsem slyšel: Projděte skrze město za ním, a bíte; neodpouštějž oko vaše, aniž se slitovávejte.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 9, 6, 'Starce, mládence i pannu, maličké i ženy mordujte do vyhubení, ale ke všelikému muži, na němž by bylo znamení, nepřistupujte, a od svatyně mé počněte. Takž začali od mužů těch starších, kteříž byli před chrámem.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 9, 7, '(Nebo jim byl řekl: Poškvrňte domu, a naplňte síně zbitými. Jdětež.) A vyšedše, bili v městě.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 9, 8, 'I stalo se, když je bili, a já pozůstal, že jsem padl na tvář svou, a zvolal jsem, řka: Ach, Panovníče Hospodine, zdaliž zahubíš všecken ostatek Izraelský, vylévaje prchlivost svou na Jeruzalém?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 9, 9, 'I řekl mi: Nepravost domu Izraelského a Judského veliká jest velmi velice, a naplněna jest země mordy, a město plné jest převrácenců. Nebo říkali: Opustil Hospodin zemi tuto, a Hospodin nikoli nevidí nás.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 9, 10, 'Protož já také cestu jejich na hlavu jejich obrátím; neodpustí oko mé, aniž se slituji.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 9, 11, 'A aj, muž oděný rouchem lněným, při jehož bedrách byl kalamář, oznámil to, řka: Učinil jsem, jakž jsi mi rozkázal.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 1, 'I viděl jsem, a aj, na obloze, kteráž byla nad hlavou cherubínů, jako kámen zafirový na pohledění, jako podobenství trůnu se ukázalo nad nimi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 2, 'Tedy promluviv k muži tomu oděnému rouchem lněným, řekl: Vejdi do prostřed kol pod cherubíny, a naplň hrsti své uhlím řeřavým z prostředku cherubínů, a roztrus po městě. Kterýžto všel před očima mýma.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 3, '(Cherubínové pak stáli po pravé straně domu, když vcházel muž ten, a oblak hustý naplnil síň vnitřní.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 4, 'Nebo když se byla zdvihla sláva Hospodinova s cherubínů k prahu domu, tedy naplněn byl dům tím hustým oblakem, a síň naplněna byla bleskem slávy Hospodinovy.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 5, 'Zvuk také křídel cherubínů slyšán byl až k té síni zevnitřní jako hlas Boha silného, všemohoucího, když mluví.)');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 6, 'I stalo se, když přikázal muži tomu oděnému rouchem lněným, řka: Vezmi ohně z prostředku kol, z prostředku cherubínů, že všel a postavil se podlé kol.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 7, 'Tedy vztáhl cherubín jeden ruku svou z prostředku cherubínů k ohni tomu, kterýž byl u prostřed cherubínů, a vzav, dal do hrsti toho oděného rouchem lněným. Kterýžto vzal a vyšel.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 8, 'Nebo ukazovalo se na cherubíních podobenství ruky lidské pod křídly jejich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 9, 'I viděl jsem, a aj, čtyři kola podlé cherubínů, jedno kolo podlé jednoho každého cherubína, podobenství pak kol jako barva kamene tarsis.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 10, 'A na pohledění měla podobnost jednostejnou ta kola, jako by bylo kolo u prostřed kola.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 11, 'Když chodili, na čtyři strany jejich chodili. Neuchylovali se, když šli, ale k tomu místu, kamž se obracel vůdce, za ním šli. Neuchylovali se, když šli.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 12, 'Všecko také tělo jejich i hřbetové jejich, i ruce jejich, i křídla jejich, též i kola plná byla očí vůkol jich samých čtyř i kol jejich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 13, 'Kola pak ta nazval okršlkem, jakž slyšely uši mé.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 14, 'Čtyři tváři mělo každé. Tvář první tvář cherubínová, tvář pak druhá tvář člověčí, a třetí tvář lvová, čtvrtá pak tvář orličí.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 15, 'I zdvihli se cherubínové. To jsou ta zvířata, kteráž jsem viděl u řeky Chebar.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 16, 'Když pak šli cherubínové, šla i kola podlé nich, a když vznášeli cherubínové křídla svá, aby se pozdvihli od země, neuchylovala se také kola od nich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 17, 'Když stáli oni, stála, a když se vyzdvihovali, vyzdvihovala se s nimi; nebo duch zvířat byl v nich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 18, 'I odešla sláva Hospodinova od prahu domu, a stála nad cherubíny,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 19, 'Hned jakž pozdvihli cherubínové křídel svých a vznesli se od země, před očima mýma odcházejíce, a kola naproti nim, a stála u vrat brány domu Hospodinova východní, a sláva Boha Izraelského svrchu nad nimi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 20, 'To jsou ta zvířata, kteráž jsem viděl pod Bohem Izraelským u řeky Chebar, a poznal jsem, že cherubínové byli.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 21, 'Po čtyřech tvářích měl jeden každý, a po čtyřech křídlích jeden každý; podobenství také rukou lidských pod křídly jejich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 22, 'Podobenství pak tváří jejich bylo jako tváří, kteréž jsem byl viděl u řeky Chebar, oblíčej jejich i oni sami. Jeden každý přímo k své straně chodil.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 1, 'I vznesl mne Duch, a přivedl mne k bráně východní domu Hospodinova, kteráž patří na východ, a aj, ve vratech brány té pětmecítma mužů, mezi kterýmiž jsem viděl Jazaniáše syna Azurova, a Pelatiáše syna Banaiášova, knížata lidu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 2, 'Tedy řekl mi: Synu člověčí, to jsou ti muži, kteříž smýšlejí nepravost, a skládají radu zlou v městě tomto,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 3, 'Říkajíce: Nestavějme domů blízko, sic město bude hrnec a my maso.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 4, 'Protož prorokuj proti nim, prorokuj, synu člověčí.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 5, 'I sstoupil na mne Duch Hospodinův, a řekl mi: Rci: Takto dí Hospodin: Tak říkáte, dome Izraelský. Nebo což vám koli vstupuje na mysl, o tom já vím.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 6, 'Veliké množství zmordovali jste v městě tomto, a naplnili jste ulice jeho zbitými.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 7, 'Protož takto praví Panovník Hospodin: Ti, kteříž jsou zbiti od vás, kteréž jste skladli u prostřed něho, oniť jsou maso, město pak hrnec, ale vás vyvedu z prostředku jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 8, 'Báli jste se meče, ale meč uvedu na vás, praví Panovník Hospodin.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 9, 'A vyvedu vás z prostředku jeho, a dám vás v ruku cizích, a vykonám nad vámi soudy.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 10, 'Mečem padnete, na pomezí Izraelském souditi vás budu, a zvíte, že já jsem Hospodin.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 11, 'Město nebude vám hrnec, aniž vy budete u prostřed něho maso, na pomezí Izraelském souditi vás budu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 12, 'I zvíte, že já jsem Hospodin, poněvadž jste v ustanoveních mých nechodili, a soudů mých nečinili, a podlé soudů těch národů, kteříž jsou vůkol vás, činili jste.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 13, 'Stalo se pak, když jsem prorokoval, že Pelatiáš syn Banaiášův umřel. Pročež padl jsem na tvář svou, a zvolal jsem hlasem velikým, řka: Ach, Panovníče Hospodine, skonání, činíš ostatkům Izraelským.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 14, 'Tedy stalo se slovo Hospodinovo ke mně, řkoucí:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 15, 'Synu člověčí, bratří tvoji, bratří tvoji, příbuzní tvoji, a všecken dům Izraelský, všecken dům, kterýmž říkali obyvatelé Jeruzalémští: Daleko zajděte od Hospodina, nám jest dána země tato v dědictví.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 16, 'Protož rci: Takto praví Panovník Hospodin: Ačkoli daleko zahnal jsem je mezi národy, a ačkoli rozptýlil jsem je do zemí, však budu jim svatyní i za ten malý čas v zemích těch, do kterýchž přijdou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 17, 'Protož rci: Takto praví Panovník Hospodin: Shromáždím vás z národů a zberu vás z zemí, do kterýchž rozptýleni jste, a dám vám zemi Izraelskou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 18, 'I vejdou tam, a vyvrhou všecky mrzkosti její, i všecky ohavnosti její z ní.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 19, 'Nebo dám jim srdce jedno, a Ducha nového dám do vnitřností vašich, a odejmu srdce kamenné z těla jejich, a dám jim srdce masité,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 20, 'Aby v ustanoveních mých chodili, a soudů mých ostříhali, a činili je. I budou lidem mým, a já budu jejich Bohem.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 21, 'Kterýchž pak srdce chodilo by po žádostech mrzkostí svých a ohavností svých, těch cestu na hlavu jejich obrátím, praví Panovník Hospodin.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 22, 'Tedy vznesli cherubínové křídla svá i kola s nimi, sláva pak Boha Izraelského nad nimi svrchu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 23, 'I odešla sláva Hospodinova z prostředku města, a stála na hoře, kteráž jest na východ městu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 24, 'Duch pak vznesl mne, a zase mne přivedl do země Kaldejské k zajatým, u vidění skrze Ducha Božího. I odešlo ode mne vidění, kteréž jsem viděl.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 25, 'A mluvil jsem k zajatým všecky ty věci Hospodinovy, kteréž mi ukázal.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 1, 'I stalo se slovo Hospodinovo ke mně, řkoucí:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 2, 'Synu člověčí, u prostřed domu zpurného ty bydlíš, kteříž mají oči, aby viděli, však nevidí; uši mají, aby slyšeli, však neslyší, proto že dům zpurný jsou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 3, 'Protož ty, synu člověčí, připrav sobě to, s čím bys se stěhoval, a stěhuj se ve dne před očima jejich. Přestěhuješ se pak z místa svého na místo jiné před očima jejich, zdaby aspoň viděli; nebo dům zpurný jsou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 4, 'Vynesa pak své věci, jakožto ty, s nimiž se stěhovati máš ve dne před očima jejich, vyjdi u večer před očima jejich, jako ti, kteříž se stěhují.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 5, 'Před očima jejich prokopej sobě zed, a vynes skrze ni.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 6, 'Před očima jejich na rameni nes, po tmě vynes, tvář svou přikrej, a nehleď na zemi; nebo za zázrak dal jsem tě domu Izraelskému.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 7, 'I učinil jsem tak, jakž rozkázáno bylo. Věci své vynesl jsem, jakožto ty, s nimiž bych se stěhoval ve dne, u večer pak prokopal jsem sobě zed rukou; po tmě jsem je vynesl, na rameni nesa před očima jejich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 8, 'Opět stalo se slovo Hospodinovo ke mně ráno, řkoucí:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 9, 'Synu člověčí, zdaližť řekli dům Izraelský, dům ten zpurný: Co ty děláš?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 10, 'Rciž jim: Takto praví Panovník Hospodin: Na kníže v Jeruzalémě vztahuje se břímě toto a na všecken dům Izraelský, kteříž jsou u prostřed něho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 11, 'Rciž jim: Já jsem zázrakem vaším. Jakož jsem činil, tak se stane jim, postěhují se a v zajetí půjdou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 12, 'A kníže, kteréž jest u prostřed nich, na rameni ponese po tmě a vyjde. Zed prokopají, aby jej vyvedli skrze ni; tvář svou zakryje, tak že nebude viděti okem svým země.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 13, 'Nebo roztáhnu sít svou na něj, a polapen bude do vrše mé, a zavedu jej do Babylona, země Kaldejské, kteréž neuzří, a tam umře.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 14, 'Všecky také, kteříž jsou vůkol něho na pomoc jemu, i všecky houfy jeho rozptýlím na všecky strany, a mečem dobytým budu je stihati.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 15, 'I zvědí, že já jsem Hospodin, když je rozptýlím mezi národy, a rozženu je po krajinách.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 16, 'Pozůstavím pak z nich muže nemnohé po meči, po hladu a po moru, aby vypravovali všecky ohavnosti své mezi národy, kamž se dostanou, i zvědí, že já jsem Hospodin.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 17, 'Opět stalo se slovo Hospodinovo ke mně, řkoucí:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 18, 'Synu člověčí, chléb svůj s strachem jez, a vodu svou s třesením a s zámutkem pí,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 19, 'A rci lidu země této: Takto praví Panovník Hospodin o obyvatelích Jeruzalémských, o zemi Izraelské: Chléb svůj s zámutkem jísti budou, a vodu svou s předěšením píti, aby obloupena byla země jeho z hojnosti své, pro nátisk všech přebývajících v ní.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 20, 'Města také, v nichž bydlejí, zpustnou, a země pustá bude, a tak zvíte, že já jsem Hospodin.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 21, 'Opět stalo se slovo Hospodinovo ke mně, řkoucí:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 22, 'Synu člověčí, jaké to máte přísloví o zemi Izraelské, říkajíce: Prodlí se dnové, aneb zahyne všeliké vidění?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 23, 'Protož rci jim: Takto praví Panovník Hospodin: Učiním, aby přestalo přísloví toto, aniž užívati budou přísloví toho více v Izraeli. Rci jim: Nýbrž přiblížili se dnové ti a splnění všelikého vidění.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 24, 'Nebo nebude více žádného vidění marného, a hádání pochlebníka u prostřed domu Izraelského,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 25, 'Proto že já Hospodin mluviti budu, a kterékoli slovo promluvím, stane se. Neprodlíť se dlouho, ale za dnů vašich, dome zpurný, mluviti budu slovo, a naplním je, praví Panovník Hospodin.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 26, 'I stalo se slovo Hospodinovo ke mně, řkoucí:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 27, 'Synu člověčí, aj, dům Izraelský říkají: Vidění to, kteréž vidí tento, ke dnům mnohým patří, a na dlouhé časy tento prorokuje.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 28, 'Protož rci jim: Takto praví Panovník Hospodin: Neprodlíť se dlouho všeliké slovo mé, ale slovo, kteréž mluviti budu, stane se, praví Panovník Hospodin.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 1, 'I stalo se slovo Hospodinovo ke mně, řkoucí:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 2, 'Synu člověčí, prorokuj proti prorokům Izraelským, kteříž prorokují, a rci prorokujícím z srdce svého: Slyšte slovo Hospodinovo:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 3, 'Takto praví Panovník Hospodin: Běda prorokům bláznivým, kteříž následují ducha svého, ješto však nic neviděli.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 4, 'Podobni jsou liškám na pustinách proroci tvoji, Izraeli.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 5, 'Nevstupujete k mezerám, aniž děláte hradby okolo domu Izraelského, aby ostáti mohl v boji v den Hospodinův.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 6, 'Vídají marnost a hádání lživé. Říkají: Praví Hospodin, ješto jich neposlal Hospodin, a troštují lidi, aby jen utvrdili slovo své.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 7, 'Zdaliž vidění marného nevídáte, a hádání lživého nevypravujete? A říkáte: Praví Hospodin, ješto jsem já nemluvil.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 8, 'Pročež takto praví Panovník Hospodin: Proto že mluvíte marnost, a vídáte lež, protož aj, já jsem proti vám, praví Panovník Hospodin.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 9, 'Nebo bude ruka má proti prorokům, kteříž vídají marnost a hádají lež. V losu lidu mého nebudou, a v popisu domu Izraelského nebudou zapsáni, aniž do země Izraelské vejdou. I zvíte, že já jsem Panovník Hospodin,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 10, 'Proto, proto že v blud uvedli lid můj, říkajíce: Pokoj, ješto nebylo žádného pokoje. Jeden zajisté ustavěl stěnu hliněnou, a jiní obmítali ji vápnem ničemným.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 11, 'Rciž těm, kteříž obmítají vápnem ničemným: I však to padne. Přijde příval rozvodnilý, a vy, kamenové krupobití velikého, spadnete, a vítr bouřlivý roztrhne ji.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 12, 'A aj, když padne ta stěna, zdaliž vám nebude řečeno: Kdež jest to obmítání, jímž jste obmítali?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 13, 'Protož takto praví Panovník Hospodin: Roztrhnu ji, pravím, větrem bouřlivým v prchlivosti své, a příval rozvodnilý v hněvě mém přijde, a kamení krupobití velikého v prchlivosti mé k vyhlazení jí.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 14, 'Nebo rozbořím stěnu tu, kterouž jste obmetali vápnem ničemným, a porazím ji na zem, tak že odkryt bude grunt její. I padne, a zkaženi budete u prostřed ní, a zvíte, že já jsem Hospodin.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 15, 'A tak vykonaje prchlivost svou na té stěně, a na těch, kteříž ji obmítají vápnem ničemným, dím vám: Není více té stěny, není ani těch, kteříž ji obmítali,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 16, 'Totiž proroků Izraelských, kteříž prorokují Jeruzalému, a ohlašují jemu vidění pokoje, ješto není žádného pokoje, praví Panovník Hospodin.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 17, 'Ty pak, synu člověčí, obrať tvář svou k dcerám lidu svého, kteréž prorokují z srdce svého, a prorokuj i proti nim.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 18, 'A rci: Takto praví Panovník Hospodin: Běda těm, kteréž šijí polštáříky pod všeliké lokty rukou lidu mého, a dělají kukly na hlavu všeliké postavy, aby lovily duše. Zdaliž loviti máte duše lidu mého, abyste se živiti mohly?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 19, 'Nebo zlehčujete mne u lidu mého pro hrst ječmene a pro kus chleba, umrtvujíce duše, kteréž neumrou, a obživujíce duše, kteréž živy nebudou, lhouce lidu mému, kteříž poslouchají lži.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 20, 'Protož takto praví Panovník Hospodin: Aj, já dám se v polštáříky vaše, jimiž vy lovíte tam duše, abyste je oklamaly. Nebo strhnu je s ramenou vašich, a propustím duše, duše, kteréž vy lovíte, abyste je oklamaly.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 21, 'I strhnu kukly vaše, a vytrhnu lid svůj z ruky vaší, tak abyste jich nemohly více loviti, i zvíte, že já jsem Hospodin;');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 22, 'Proto že kormoutíte srdce spravedlivého lžmi, ješto jsem já ho nekormoutil, a posilujete rukou bezbožného, aby se neodvrátil od zlé cesty své, obživujíce jej.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 23, 'Protož nebudete vídati marnosti, a s hádáním nebudete se obírati více; nebo vytrhnu lid svůj z ruky vaší, i zvíte, že já jsem Hospodin.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 1, 'Potom přišedše ke mně muži z starších Izraelských, seděli přede mnou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 2, 'I stalo se slovo Hospodinovo ke mně, řkoucí:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 3, 'Synu člověčí, muži tito složili ukydané bohy své v srdci svém, a nepravost, kteráž jim k urážce jest, položili před tváři své. Zdaliž se upřímě radí se mnou?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 4, 'Protož mluv jim a rci jim: Takto praví Panovník Hospodin: Kdo by koli z domu Izraelského složil ukydané bohy své v srdci svém, a nepravost, kteráž mu k urážce jest, položil před tvář svou, a přišel by k proroku: já Hospodin odpovídati budu tomu, kterýž přišel, o množství ukydaných bohů jeho,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 5, 'Abych polapil dům Izraelský v srdci jejich, že se odvrátili ode mne k ukydaným bohům svým všickni napořád.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 6, 'Protož rci domu Izraelskému: Takto praví Panovník Hospodin: Obraťte se a odvraťte od ukydaných bohů vašich, a ode všech ohavností vašich odvraťte tvář svou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 7, 'Nebo kdož by koli z domu Izraelského i z pohostinných, kteříž jsou pohostinu v Izraeli, odvrátil se od následování mne, a složil by ukydané bohy své v srdci svém, a nepravost, kteráž mu k urážce jest, položil by před tvář svou a přišel by k proroku, aby se mne tázal skrze něho: já Hospodin odpovím jemu o sobě,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 8, 'A obrátím tvář svou hněvivou proti muži tomu, a dám jej za znamení a za přísloví, a vytnu jej z prostřed lidu svého, i zvíte, že já jsem Hospodin.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 9, 'Prorok pak, dal-li by se přivábiti, aby mluvil slovo, já Hospodin přivábil jsem proroka toho. Než vztáhnuť ruku svou na něj, a vyhladím jej z prostřed lidu svého Izraelského.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 10, 'A tak ponesou nepravost svou. Jakáž pokuta na toho, kdož by se tázal, takováž pokuta na proroka bude,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 11, 'Aby nebloudili více dům Izraelský ode mne, a nepoškvrňovali se více žádnými převrácenostmi svými, aby byli lidem mým, a já abych byl jejich Bohem, praví Panovník Hospodin.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 12, 'Opět stalo se slovo Hospodinovo ke mně, řkoucí:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 13, 'Synu člověčí, když by země zhřešila proti mně, dopouštějíc se přestoupení, tehdy vztáhl-li bych ruku svou na ni, a zlámal jí hůl chleba, a poslal bych na ni hlad, a vyhubil z ní lidi i hovada:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 14, 'By pak byli u prostřed ní tito tři muži, Noé, Daniel a Job, oni v spravedlnosti své vysvobodili by sami sebe, praví Panovník Hospodin.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 15, 'Pakli bych zvěř lítou uvedl na zemi, tak že by ji na sirobu přivedla, a byla by pustá, aniž by kdo přes ni jíti mohl pro zvěř:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 16, 'Živť jsem já, praví Panovník Hospodin, že byť tři muži tito u prostřed ní byli, nikoli by nevysvobodili synů ani dcer. Oni by sami vysvobozeni byli, země pak byla by pustá.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 17, 'Aneb meč uvedl-li bych na zemi tu, a řekl bych meči: Projdi skrz zemi tu, abych vyhubil z ní lidi i hovada:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 18, 'Živť jsem já, praví Panovník Hospodin, že byť pak tři muži tito byli u prostřed ní, nikoli by nevysvobodili synů ani dcer, ale oni sami by vysvobozeni byli.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 19, 'Aneb mor poslal-li bych na zemi tu, a vylil prchlivost svou na ni k zhoubě, aby vyhlazeni byli z ní lidé i hovada:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 20, 'Živť jsem já, praví Panovník Hospodin, že byť pak Noé, Daniel a Job u prostřed ní byli, nikoli by ani syna ani dcery nevysvobodili. Oni v spravedlnosti své vysvobodili by sami sebe.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 21, 'Nýbrž takto praví Panovník Hospodin: Bych pak čtyři pokuty své zlé, meč a hlad, zvěř lítou a mor poslal na Jeruzalém, abych vyhubil z něho lidi i hovada,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 22, 'A aj, pozůstali-li by v něm, kteříž by toho ušli, a vyvedeni byli, synové neb dcery: aj, i oni musejí jíti k vám, a uzříte cestu jejich a skutky jejich, i potěšíte se nad tím zlým, kteréž uvedu na Jeruzalém, nade vším, což uvedu na něj.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 23, 'A tak potěší vás, když uzříte cestu jejich a skutky jejich. I zvíte, že jsem ne nadarmo učinil všecko to, což jsem učinil při něm, praví Panovník Hospodin.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 15, 1, 'Tedy stalo se slovo Hospodinovo ke mně, řkoucí:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 15, 2, 'Synu člověčí, co jest dřevo révové proti všelijakému dřevu, aneb proti ratolestem dříví lesního?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 15, 3, 'Zdaliž vzato bude z něho dřevo k udělání něčeho? Zdaliž udělají z něho hřebík k zavěšování na něm všelijaké nádoby?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 15, 4, 'Aj, na oheň dává se k sežrání. Když oba konce jeho sežere oheň, a prostředek jeho obhoří, zdaž se k čemu hoditi může?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 15, 5, 'Aj, když byl celý, nic nemohlo býti z něho uděláno, ovšem když jej oheň sežral, a shořel, k ničemu se více hoditi nebude.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 15, 6, 'Protož takto praví Panovník Hospodin: Jakož jest dřevo révové mezi dřívím lesním, kteréž jsem oddal ohni k sežrání, tak jsem oddal obyvatele Jeruzalémské.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 15, 7, 'Nebo postavím tvář svou hněvivou proti nim. Z ohně jednoho vyjdou, a oheň druhý zžíře je. I zvíte, že já jsem Hospodin, když obrátím tvář svou hněvivou proti nim.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 15, 8, 'A obrátím zemi tuto v poušť, proto že se přestoupení dopouštěli, praví Panovník Hospodin.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 1, 'Opět stalo se slovo Hospodinovo ke mně, řkoucí:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 2, 'Synu člověčí, oznam Jeruzalému ohavnosti jeho,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 3, 'A rci: Takto praví Panovník Hospodin dceři Jeruzalémské: Obcování tvé a rod tvůj jest z země Kananejské, otec tvůj jest Amorejský, a matka tvá Hetejská.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 4, 'Narození pak tvé: V den, v němž jsi se narodila, nebyl přiřezán pupek tvůj, a vodou nebylas obmyta, abys ošetřena byla, aniž jsi byla solí posolena, ani plénkami obvinuta.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 5, 'Neslitovalo se nad tebou oko, aťby v jednom z těch věcí posloužilo, maje lítost nad tebou, ale bylas povržena na svrchku pole, proto že jsi ošklivá byla v den, v kterémž jsi narodila se.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 6, 'A jda mimo tebe, a vida tě ku potlačení vydanou ve krvi tvé, řekl jsem tobě: Ve krvi své živa buď. Řekl jsem, pravím, tobě: Ve krvi své živa buď.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 7, 'Rozmnožil jsem tě jako z rostliny polní, i rozmnožena jsi a zveličena, a přišlas k největší ozdobě. Prsy tvé oduly se, a vlasy tvé zrostly, ač jsi byla nahá a odkrytá.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 8, 'Protož jda mimo tě, a vida tě, an aj, čas tvůj čas milování, vztáhl jsem křídlo své na tě, a přikryl jsem nahotu tvou, a přísahou zavázav se tobě, všel jsem v smlouvu s tebou, praví Panovník Hospodin, a tak jsi má učiněna.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 9, 'I umyl jsem tě vodou, a splákl jsem krev tvou s tebe, a pomazal jsem tě olejem.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 10, 'Nadto přioděl jsem tě rouchem krumpovaným, a obul jsem tě v drahé střevíce, a opásal jsem tě kmentem, a přioděl jsem tě rouchem hedbávným.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 11, 'Ozdobil jsem tě také ozdobou, a dal jsem náramky na ruce tvé, a točenici na hrdlo tvé.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 12, 'Dalť jsem ozdobu i na čelo tvé, a náušnice na uši tvé, a korunu krásnou na hlavu tvou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 13, 'A tak bylas ozdobena zlatem a stříbrem, a oděv tvůj byl kment a roucho hedbávné, a proměnných barev roucho. Běl a med a olej jídala jsi, a krásná jsi učiněna velmi velice, a šťastněť se vedlo v království,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 14, 'Tak že se rozešla pověst o tobě mezi národy pro krásu tvou; nebo dokonalá byla, pro slávu mou, kterouž jsem byl vložil na tebe, praví Panovník Hospodin.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 15, 'Ale úfalas v krásu svou, a smilnilas příčinou pověstí své; nebo jsi páchala smilství s každým mimo tebe jdoucím. Každý snadně užil krásy tvé.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 16, 'A vzavši z roucha svého, nadělalas sobě výsostí rozličných barev, a páchalas smilství při nich, jemuž podobné nikdy nepřijde, aniž kdy potom bude.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 17, 'Nad to, vzavši přípravy ozdoby své z zlata mého a stříbra mého, kteréžť jsem byl dal, nadělalas sobě obrazů pohlaví mužského, a smilnilas s nimi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 18, 'Vzalas také roucha svá krumpovaná, a přiodílas je, olej můj i kadidlo mé kladlas před nimi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 19, 'Ano i chléb můj, kterýžť jsem byl dal, běl a olej i med, jímž jsem tě krmil, kladlas před nimi u vůni příjemnou, a bylo tak, praví Panovník Hospodin.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 20, 'Bralas i syny své a dcery své, kteréž jsi mně zplodila, a obětovalas jim k spálení. Cožť se ještě zdálo málo, taková smilství tvá,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 21, 'Žes i syny mé zabíjela a dávalas je, aby je provodili jim?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 22, 'K tomu ve všech ohavnostech svých a smilstvích svých nerozpomenulas se na dny mladosti své, když jsi byla nahá a odkrytá, ku potlačení vydaná ve krvi své.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 23, 'Ale stalo se přes všecku tuto nešlechetnost tvou, (běda, běda tobě), praví Panovník Hospodin,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 24, 'Že jsi vystavěla sobě i vysoké místo, a vzdělalas sobě výsost v každé ulici.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 25, 'Při všelikém rozcestí udělalas výsost svou, a zohavilas krásu svou, roztahujíc nohy své každému tudy jdoucímu, a příliš jsi smilnila.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 26, 'Nebo smilnila jsi s syny Egyptskými, sousedy svými velikého těla, a příliš jsi smilnila, abys mne k hněvu popouzela.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 27, 'Protož aj, vztáhl jsem ruku svou na tebe, a ujal jsem vyměřeného pokrmu tvého, a vydal jsem tě k líbosti nenávidících tě dcer Filistinských, kteréžto styděly se za cestu tvou nešlechetnou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 28, 'Smilnilas též s syny Assyrskými, proto že jsi nemohla nasytiti se, a smilnivši s nimi, aniž jsi tak se nasytila.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 29, 'A tak příliš jsi smilnila v zemi Kananejské s Kaldejskými, a aniž jsi tak se nasytila.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 30, 'Jakť jest zmámeno srdce tvé, praví Panovník Hospodin, poněvadž se dopouštíš všech těchto skutků ženy nevěstky přenestydaté,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 31, 'Stavěje sobě vysoké místo na rozcestí všeliké silnice, a výsost sobě stroje i v každé ulici. Nýbrž pohrdaje darem, nejsi ani jako nevěstka,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 32, 'A žena cizoložná, kteráž místo muže svého povoluje cizím.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 33, 'Všechněm nevěstkám dávají mzdu, ale ty dávalas mzdu svou všechněm frejířům svým, a darovalas je, aby vcházeli k tobě odevšad pro smilství tvá.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 34, 'A tak jest při tobě naproti obyčeji těch žen při smilstvích tvých, poněvadž tě k smilství nehledají, nýbrž ty dáváš dary, a ne tobě dar dáván bývá. A toť jest naopak.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 35, 'Protož ó nevěstko, slyš slovo Hospodinovo:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 36, 'Takto praví Panovník Hospodin: Proto že vylita jest mrzkost tvá, a odkrývána byla nahota tvá při smilstvích tvých s frejíři tvými, a se všemi ukydanými bohy ohavností tvých, též pro krev synů tvých, kteréž jsi dala jim:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 37, 'Proto aj, já shromáždím všecky frejíře tvé, s nimiž jsi obcovala, a všecky, kteréž jsi milovala, se všechněmi, jichž jsi nenáviděla, a shromáždě je proti tobě odevšad, odkryji nahotu tvou před nimi, aby viděli všecku nahotu tvou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 38, 'A budu tě souditi soudem cizoložnic, a těch, kteříž krev vylévají, a oddám tě k smrti, kteráž přijde na tě z prchlivosti a horlení.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 39, 'Nebo vydám tě v ruku jejich. I rozboří vysoké místo tvé, a rozválejí výsosti tvé, a svlekouce tě z roucha tvého, poberou přípravy ozdoby tvé, a nechají tě nahé a odkryté.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 40, 'I přivedou proti tobě shromáždění, a uházejí tě kamením, a probodnou tě meči svými.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 41, 'Popálí také domy tvé ohněm, a vykonají na tobě pomstu před očima žen mnohých, a tak přítrž učiním tvému smilství, a aniž budeš dávati daru více.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 42, 'A tak odpočineť sobě hněv můj na tobě, a horlení mé odejde od tebe, abych upokojil se a nehněval se více,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 43, 'Proto žes se nerozpomenula na dny mladosti své, ale postavovalas se proti mně ve všem tom. Aj hle, já také cestu tvou na hlavu tvou obrátil jsem, praví Panovník Hospodin, tak že nebudeš páchati nešlechetnosti, ani kterých ohavností svých.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 44, 'Aj, kdožkoli užívá přísloví, o tobě užive přísloví, řka: Jakáž matka, takáž dcera její.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 45, 'Dcera matky své jsi, té, kteráž sobě zošklivila muže svého a dítky své, a sestra obou sestr svých jsi, kteréž zošklivily sobě muže své a dítky své. Matka vaše jest Hetejská, a otec váš Amorejský.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 46, 'Sestra pak tvá starší, kteráž sedí po levici tvé, jest Samaří a dcery její, a sestra tvá mladší, kteráž sedí po pravici tvé, jest Sodoma a dcery její.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 47, 'Nýbrž aniž jsi po cestách jejich chodila, ani podlé ohavností jejich činila, zošklivivši sobě jako věc špatnou, pročež pokazilas se více než ony na všech cestách svých.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 48, 'Živť jsem já, praví Panovník Hospodin, že Sodoma sestra tvá i dcery její nečinily, jako jsi ty činila s dcerami svými.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 49, 'Aj, tatoť byla nepravost Sodomy sestry tvé: Pýcha, sytost chleba a hojnost pokoje. To ona majíc i dcery její, ruky však chudého a nuzného neposilňovala.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 50, 'Ale pozdvihše se, páchaly ohavnost přede mnou; protož sklidil jsem je, jakž mi se vidělo.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 51, 'Samaří také ani polovice hříchů tvých nenahřešila. Nebo jsi rozhojnila ohavnosti své nad ně, a tak jsi spravedlivější býti ukázala sestry své všemi ohavnostmi svými, kteréž jsi páchala.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 52, 'Nesiž i ty také potupu svou, kterouž jsi přisoudila sestrám svým, pro hříchy své, kteréž jsi ohavně páchala více než ony. Spravedlivějšíť byly než ty. I ty, pravím, styď se, a nes potupu svou, poněvadž spravedlivější býti ukazuješ sestry své.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 53, 'Přivedu-li zase zajaté jejich, totiž zajaté Sodomy a dcer jejich, též zajaté Samaří a dcer jejich, takéť zajetí zajatých tvých u prostřed nich,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 54, 'Proto, abys musila nésti potupu svou a hanbiti se za všecko, což jsi páchala, jsuc jejich potěšením.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 55, 'Jestližeť sestry tvé, Sodoma a dcery její, navrátí se k prvnímu způsobu svému, též Samaří a dcery její navrátí-li se k prvnímu způsobu svému: i ty také s dcerami svými navrátíte se k prvnímu způsobu svému.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 56, 'Poněvadž nebyla Sodoma sestra tvá pověstí v ústech tvých v den zvýšení tvého,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 57, 'Prvé než zjevena byla zlost tvá, jako za času útržky od dcer Syrských a všech, kteříž jsou vůkol nich, dcer Filistinských, kteréž tě hubily se všech stran:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 58, 'Nešlechetnost svou a ohavnosti své poneseš, praví Hospodin.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 59, 'Nebo takto praví Panovník Hospodin: Tak učiním tobě, jakž jsi učinila, když jsi pohrdla přísahou, a zrušila smlouvu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 60, 'A však rozpomenu se na smlouvu svou s tebou ve dnech mladosti tvé, potvrdím, pravím, tobě smlouvy věčné.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 61, 'I rozpomeneš se na cesty své, a hanbiti se budeš, když přijmeš sestry své starší, nežli jsi ty, i mladší, nežli jsi ty, a dám je tobě za dcery, ale ne podlé smlouvy tvé.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 62, 'A tak utvrdím smlouvu svou s tebou, i zvíš, že já jsem Hospodin,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 63, 'Abys se rozpomenula a styděla, a nemohla více úst otevříti pro hanbu svou, když tě očistím ode všeho, což jsi činila, praví Panovník Hospodin.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 1, 'Opět stalo se slovo Hospodinovo ke mně, řkoucí:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 2, 'Synu člověčí, vydej pohádku, a předlož podobenství o domu Izraelském,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 3, 'A rci: Takto praví Panovník Hospodin: Orlice veliká, velikých křídel a dlouhých brků, plná peří, strakatá, přiletěvši na Libán, vzala vrch cedru.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 4, 'Vrch mladistvých ratolestí jeho ulomila, a přenesla jej do země kupecké; v městě kupeckém položila jej.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 5, 'Potom vzavši z semene té země, vsadila je v poli úrodném, a vsadila je velmi opatrně při vodách mnohých.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 6, 'Kteréžto bylo by vzešlo, a bylo by révem bujným, jakžkoli nízké postavy, a byly by patřily ratolesti jeho k ní, a kořenové jeho poddáni byli by jí, a tak bylo by kmenem vinným, kterýž by vydal byl ratolesti, a vypustil rozvody.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 7, 'Ale byla orlice jedna veliká velikých křídel a vypeřená, a aj, ten kmen vinný připjal kořeny své k ní, a ratolesti své vztáhl k ní, aby svlažovala jej z brázd štípení svého,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 8, 'Ješto v poli dobrém, při vodách mnohých štípen byl, aby vypustil ratolesti, a nesl ovoce, a byl kmenem slavným.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 9, 'Rci: Takto praví Panovník Hospodin: Zdaliž se podaří? Zdaliž kořenů jeho nevytrhá, a ovoce jeho neotrhá a neusuší? Zdaž všech ratolestí vyrostlých z něho neusuší? Zdaliž s velikou silou a s mnohým lidem nevyhladí ho z kořenů jeho?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 10, 'Aj, jakžkoli štípen, zdaliž se podaří? Zdaliž, jakž se ho dotkne vítr východní, do konce neuschne? Při brázdách, při nichž se ujal, zdaž neuschne?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 11, 'Za tím stalo se slovo Hospodinovo ke mně, řkoucí:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 12, 'Rci nyní domu zpurnému: Nevíte-liž, co je toto? Rci: Aj, přitáhl král Babylonský do Jeruzaléma, a vzal krále jeho i knížata jeho, a zavedl je s sebou do Babylona.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 13, 'Vzal také z semene královského, a učiniv s ním smlouvu, přísahou jej zavázal, a silné země té pobral,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 14, 'Aby bylo království snížené, proto aby se nepozdvihovalo, aby ostříhaje smlouvy jeho, tak stálo.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 15, 'Ale zprotivil se jemu, poslav posly své do Egypta, aby jemu podal koní a lidu mnohého. Zdaž se mu to podaří? Zdaž pomsty ujde ten, kdož tak činí? Ten kdož ruší smlouvu, zdaliž pomsty ujde?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 16, 'Živť jsem já, praví Panovník Hospodin, že v místě krále toho, kterýž jej králem učinil, jehož přísahou pohrdl, a jehož smlouvu zrušil, u něho v Babyloně umře.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 17, 'Aniž mu Farao s vojskem velikým a s zástupem mnohým co napomůže v boji, když vysype násyp, a vzdělá šance, aby zahubil množství lidí,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 18, 'Poněvadž pohrdl přísahou, zrušiv smlouvu. Neb aj, podal ruky své, a však všecko toto činí. Neujdeť pomsty.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 19, 'Protož takto praví Panovník Hospodin: Živť jsem já, že přísahu svou, kterouž pohrdl, a smlouvu svou, kterouž zrušil, jistotně obrátím na hlavu jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 20, 'Nebo roztáhnu na něj sít svou, a polapen bude do vrše mé, i zavedu jej do Babylona, a souditi se s ním budu tam pro přestoupení jeho, kteréhož se dopustil proti mně.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 21, 'Všickni též, kteříž utekli od něho se všemi houfy jeho, od meče padnou, ostatní pak na všecky strany rozprostříni budou. I zvíte, že já Hospodin mluvil jsem.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 22, 'Takto praví Panovník Hospodin: A však vezmu z vrchu cedru toho vysokého a vsadím, z vrchu mladistvých ratolestí jeho mladou větvičku ulomím, a štípím na hoře vysoké a vyvýšené.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 23, 'Na hoře vysoké Izraelské štípím ji, i vypustí ratolesti, a ponese ovoce, a tak učiněna bude cedrem slavným, a bude bydliti pod ním všeliké ptactvo; všecko, což křídla má, v stínu ratolestí jeho bydliti bude.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 24, 'A tak zvědí všecka dříví polní, že já Hospodin snížil jsem dřevo vysoké, a povýšil jsem dřeva nízkého; usušil jsem strom zelený, a způsobil to, aby zkvetl strom suchý. Já Hospodin mluvil jsem to i učiním.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 1, 'Opět stalo se slovo Hospodinovo ke mně, řkoucí:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 2, 'Což jest vám, že užíváte přísloví tohoto o zemi Izraelské, říkajíce: Otcové jedli hrozen trpký, a zubové synů laskominy mají?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 3, 'Živť jsem já, praví Panovník Hospodin, že nebudete moci více užívati přísloví tohoto v Izraeli.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 4, 'Aj, všecky duše mé jsou, jakož duše otcova, tak i duše synova mé jsou. Duše, kteráž hřeší, ta umře.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 5, 'Nebo byl-li by někdo spravedlivý, a činil by soud a spravedlnost;');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 6, 'Na horách by nejídal, a očí svých nepozdvihoval k ukydaným bohům domu Izraelského, a manželky bližního svého by nepoškvrnil, a k ženě pro nečistotu oddělené nepřistoupil;');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 7, 'Kterýž by žádného neutiskal, základ dlužníku svému by navracoval, cizího mocí nebral, chleba svého by lačnému udílel, a nahého přiodíval rouchem;');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 8, 'Na lichvu by nedával, a úroku nebral, od nepravosti ruku svou by odvracoval, soud pravý mezi jedním i druhým by činil;');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 9, 'V ustanoveních mých by chodil, a soudů mých ostříhal, čině, což pravého jest: spravedlivý ten jistě žeť živ bude, praví Panovník Hospodin.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 10, 'Zplodil-li by pak syna lotra, prolevače krve, kterýž by čímkoli z těch věcí škodil bratru,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 11, 'Onoho pak všeho nečinil by, anobrž i na horách by jídal, a ženy bližního svého by poškvrnil;');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 12, 'Chudého a nuzného by utiskl, cizí věci mocí vzal, základu by nenavrátil, a k ukydaným bohům očí svých by pozdvihoval, ohavnost provodil,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 13, 'Na lichvu by dával, a úrok bral: zdaž bude živ? Nebude živ. Poněvadž všecky ohavnosti tyto činil, jistotně umře, krev jeho přijde na něj.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 14, 'A aj, zplodil-li by syna, kterýž by spatřil všecky hříchy otce svého, kteréž činil, a vida, nečinil by tak;');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 15, 'Na horách by nejídal, a očí svých nepozdvihoval k ukydaným bohům domu Izraelského, manželky bližního svého by nepoškvrnil,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 16, 'A aniž by koho utiskal, základu by nezadržoval, cizího mocí nebral, chleba svého lačnému by udílel, a nahého rouchem by přiodíl;');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 17, 'Od chudého by zdržel ruku svou, lichvy a úroku by nebral, soudy mé činil, v ustanoveních mých by chodil: tenť neumře pro nepravost otce svého, jistě živ bude.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 18, 'Otec pak jeho, proto že se bezpráví dopouštěl, cizí věci bratru mocí bral, a to, což není dobré, činil u prostřed lidu svého: protož aj, umře pro nepravost svou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 19, 'Ale říkáte: Jak by to bylo? Zdaž nenese syn nepravosti otcovy? Když syn činí soud a spravedlnost, všech ustanovení mých ostříhá a činí je, jistě žeť živ bude.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 20, 'Duše, kteráž hřeší, ta umře. Syn neponese nepravosti otcovy, aniž otec ponese nepravosti synovy; spravedlnost spravedlivého při něm zůstane, též bezbožnost bezbožného na něj připadne.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 21, 'Pakli by se bezbožný odvrátil ode všech hříchu svých, kteréž činil, a ostříhal by všech ustanovení mých, a činil by soud a spravedlnost, jistě živ bude a neumře.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 22, 'Žádná přestoupení jeho, jichž se dopustil, nebudou jemu připomínána; v spravedlnosti své, kterouž by činil, živ bude.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 23, 'Zdaliž jakou líbost mám, když umírá bezbožný? dí Panovník Hospodin. Zdali ne raději když se odvrací od cest svých, aby živ byl?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 24, 'Pakli by se odvrátil spravedlivý od spravedlnosti své, a činil by nepravost, čině podlé všech ohavností, kteréž činí bezbožný, takový-liž by živ byl? Na žádné spravedlnosti jeho, kteréž činil, nebude pamatováno. Pro přestoupení své, jehož se dopouštěl, a pro hřích svůj, kterýž páchal, pro tyť věci umře.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 25, 'Že pak říkáte: Není pravá cesta Páně, poslyštež nyní, ó dome Izraelský: Zdali má cesta není pravá? Zdali nejsou cesty vaše nepravé?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 26, 'Když by se odvrátil spravedlivý od spravedlnosti své, a čině nepravost, v tom by umřel, pro nepravost svou, kterouž činil, umře.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 27, 'A když by se odvrátil bezbožný od bezbožnosti své, kterouž činil, a činil by soud a spravedlnost, tenť duši svou zachová při životu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 28, 'Nebo prohlédl, a odvrátil, se ode všech přestoupení svých, jichž se dopouštěl; jistě žeť živ bude a neumře.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 29, 'A však vždy říká dům Izraelský: Není pravá cesta Páně. Zdali mé cesty nepravé jsou, ó dome Izraelský? Zdaliž nejsou cesty vaše nepravé?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 30, 'A protož každého z vás podlé cest jeho souditi budu, ó dome Izraelský, dí Panovník Hospodin. Navraťtež se a odvraťte ode všech přestoupení svých, aby vám nebyla k úrazu nepravost.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 31, 'Odvrzte od sebe všecka přestoupení vaše, jichž jste se dopouštěli, a učiňte sobě srdce nové a ducha nového. I pročež mřete, ó dome Izraelský?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 32, 'Však nemám líbosti v smrti toho, jenž umírá, dí Panovník Hospodin. Obraťte se tedy, a živi buďte.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 19, 1, 'Ty pak vydej se v naříkání nad knížaty Izraelskými.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 19, 2, 'A rci: Co byla matka tvá? Lvice mezi lvy odpočívající, a u prostřed dravých lvů vychovávala lvíčátka svá.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 19, 3, 'A když odchovala jedno z lvíčat svých, udělal se z něho dravý lev, tak že naučiv se bráti loupeže, žrával lidi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 19, 4, 'To když uslyšeli národové, v jámě jejich polapen jest, a doveden v řetězích do země Egyptské.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 19, 5, 'To viduc lvice, že očekávaná zhynula jí naděje její, vzavši jedno z lvíčat svých, učinila z něho silného lva;');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 19, 6, 'Kterýž ustavičně chodě mezi lvy, udělal se dravým lvem, a naučiv se bráti loupeže, žrával lidi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 19, 7, 'Pobořil i pusté paláce jejich, a města jejich v poušť uvedl, tak že spustla země, i což v ní bylo, od hlasu řvání jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 19, 8, 'I polékli na něj národové z okolních krajin, a rozestřeli na něj tenata svá, a do jámy jejich lapen jest.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 19, 9, 'I dali jej do klece v řetězích, a dopravili ho k králi Babylonskému, a uvedli jej do vězení nejtěžšího, aby nebyl slýchán hlas jeho více po horách Izraelských.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 19, 10, 'Matka tvá v čas pokoje tvého jako vinný kmen při vodách štípený; plodistvý a rozkladitý byl pro hojnost vod.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 19, 11, 'A měl pruty mocné k berlám panovníků, zrůst pak jeho vyvýšil se nad prostředek hustého větvoví, tak že patrný byl pro svou vysokost a pro množství ratolestí svých.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 19, 12, 'Ale vytržen jsa v prchlivosti, na zemi povržen jest, a vítr východní usušil ovoce jeho; vylomily se a uschly ratolesti silné jeho, oheň sežral je.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 19, 13, 'A nyní štípen jest na poušti, v zemi vyprahlé a žíznivé.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 19, 14, 'Nadto vyšed oheň z prutu ratolestí jeho, sežral ovoce jeho, tak že není na něm prutu mocného k berle panovníka. Toť jest naříkání, a budeť v naříkání.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 1, 'Tedy stalo se léta sedmého, a dne desátého, pátého měsíce, přišli někteří z starších Izraelských raditi se s Hospodinem, a posadili se přede mnou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 2, 'Tehdy stalo se slovo Hospodinovo ke mně, řkoucí:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 3, 'Synu člověčí, mluv k starším Izraelským a rci jim: Takto praví Panovník Hospodin: Zdali, abyste se se mnou radili, vy přicházíte? Živ jsem já, že vy se neradíte se mnou, dí Panovník Hospodin.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 4, 'Zdali jich zastávati budeš? Zdali zastávati budeš, synu člověčí? Oznam jim ohavnosti otců jejich,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 5, 'A rci jim: Takto praví Panovník Hospodin: V ten den, v kterýž jsem zvolil Izraele, zdvihl jsem ruku svou semeni domu Jákobova, a v známost jsem se uvedl jim v zemi Egyptské; zdvihlť jsem jim ruku svou, řka: Já jsem Hospodin Bůh váš.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 6, 'V ten den zdvihl jsem jim ruku svou, že je vyvedu z země Egyptské do země, kterouž jsem jim obhlédl, tekoucí mlékem a strdí, jenž jest okrasa všech jiných zemí.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 7, 'A řekl jsem jim: Jeden každý ohavnosti očí svých zavrzte, a ukydanými bohy Egyptskými se nepoškvrňujte, nebo já jsem Hospodin Bůh váš.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 8, 'Ale zpurně se postavovali proti mně, aniž mne chtěli slyšeti, aniž kdo ohavnosti očí svých zavrhl, a ukydaných bohů Egyptských nezanechali. Protož jsem řekl: Vyleji prchlivost svou na ně, a vyplním hněv svůj na nich u prostřed země Egyptské.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 9, 'A však učinil jsem pro jméno své, aby nebylo zlehčeno před očima těch národů, mezi nimiž byli, před jejichž očima jsem se jim v známost uvedl, že je chci vyvesti z země Egyptské.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 10, 'Takž jsem je vyvedl z země Egyptské, a přivedl jsem je na poušť,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 11, 'A dal jsem jim ustanovení svá, a soudy své v známost jsem jim uvedl, ješto činil-li by je kdo, jistě že by živ byl skrze ně.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 12, 'Nadto i soboty své vydal jsem jim, aby byly na znamení mezi mnou a mezi nimi, aby znali, že já Hospodin jsem posvětitel jejich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 13, 'Ale dům Izraelský zpurně se postavovali proti mně na poušti, v ustanoveních mých nechodili, a soudy mými pohrdli, ješto činil-li by je kdo, jistě že by živ byl skrze ně; též soboty mé poškvrnili náramně. Pročež jsem řekl: Že vyleji prchlivost svou na ně na poušti, abych je docela vyhladil.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 14, 'Ale učinil jsem pro jméno své, aby nebylo zlehčeno před očima těch národů, před jejichž očima jsem je vyvedl.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 15, 'A však i já také přisáhl jsem jim na té poušti, že jich neuvedu do země, kterouž jsem byl dal, tekoucí mlékem a strdí, jenž jest okrasa všech jiných zemí,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 16, 'Proto že soudy mými pohrdli, a v ustanoveních mých nechodili, a soboty mé poškvrnili, a že za ukydanými bohy jejich srdce jejich chodí.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 17, 'Však odpustilo jim oko mé, tak že jsem jich nezahladil, a neučinil jim konce na poušti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 18, 'A řekl jsem synům jejich na též poušti: V ustanoveních otců svých nechoďte, a soudů jejich neostříhejte, a ukydanými bohy jejich se nepoškvrňujte.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 19, 'Já jsem Hospodin Bůh váš, v ustanoveních mých choďte, a soudů mých ostříhejte, a čiňte je.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 20, 'Též soboty mé svěťte, i budou na znamení mezi mnou a vámi, aby známé bylo, že já jsem Hospodin Bůh váš.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 21, 'Ale zpurně se měli ke mně ti synové, v ustanoveních mých nechodili, a soudů mých nešetřili, aby je činili, (ješto činil-li by je kdo, jistě že by živ byl skrze ně), i soboty mé poškvrnili. I řekl jsem: Že vyleji prchlivost svou na ně, abych vyplnil hněv svůj na nich na té poušti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 22, 'Ale odvrátil jsem zase ruku svou; což jsem učinil pro jméno své, aby nebylo zlehčeno před očima těch národů, před jejichž očima jsem je vyvedl.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 23, 'Také i těm přisáhl jsem na poušti, že je rozptýlím mezi pohany, a že je rozženu po krajinách,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 24, 'Proto že soudů mých nečinili, a ustanoveními mými pohrdli, a soboty mé poškvrnili, a že k ukydaným bohům otců svých zření měli.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 25, 'Pročež já také dal jsem jim ustanovení nedobrá, a soudy, skrze něž nebudou živi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 26, 'A poškvrnil jsem jich s jejich dary, (proto že provodili všecko, což otvírá život), abych je zkazil, aby poznali, že já jsem Hospodin.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 27, 'Protož mluv k domu Izraelskému, synu člověčí, a rci jim: Takto praví Panovník Hospodin: Ještě i tímto rouhali se mi otcové vaši, dopouštějíce se proti mně přestoupení,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 28, 'Že, když jsem je uvedl do země, o kteréž jsem přisáhl, že jim ji dám, kdež spatřili který pahrbek vysoký, aneb které dřevo husté, hned tu obětovali oběti své, a tu dávali popouzející dary své, tu kladli i vůni svou příjemnou, a tu obětovali mokré oběti své.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 29, 'A ačkoli jsem říkal jim: Což jest ta výsost, kamž vy chodíváte? ale ona slove výsostí až do tohoto dne.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 30, 'Protož rci domu Izraelskému: Takto praví Panovník Hospodin: Cestou-liž otců vašich vy se máte poškvrňovati, a s ohavnostmi jejich máte smilniti?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 31, 'Též přinášejíce dary své, vodíce syny své skrze oheň, máte-liž se poškvrňovati při všech ukydaných bozích vašich až do tohoto dne, a ode mne vždy rady hledati, ó dome Izraelský? Živť jsem já, dí Panovník Hospodin, že vy se nebudete mne více raditi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 32, 'To pak, což jste sobě v mysli uložili, nikoli se nestane, že říkáte: Budeme jako jiní národové, jako čeledi jiných zemí, sloužíce dřevu a kameni.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 33, 'Živ jsem já, praví Panovník Hospodin, že rukou silnou a ramenem vztaženým, a prchlivostí vylitou kralovati budu nad vámi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 34, 'Vyvedu vás zajisté z národů, a shromáždím vás z zemí, do nichž jste rozptýleni, rukou silnou a ramenem vztaženým, i prchlivostí vylitou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 35, 'A vodě vás po poušti těch národů, souditi se budu s vámi tam tváří v tvář.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 36, 'Tak jako jsem se soudil s otci vašimi na poušti země Egyptské, tak se budu souditi s vámi, praví Panovník Hospodin.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 37, 'A proženu vás pod hůl, abych vás uvedl do závazku smlouvy.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 38, 'Ale ty, jenž se mi zprotivili a zpronevěřili, vymísím z vás; z země, v níž pohostinu jsou, vyvedu je, do země však Izraelské nevejdou. I zvíte, že já jsem Hospodin.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 39, 'Vy tedy, ó dome Izraelský, takto praví Panovník Hospodin: Jdětež, služte každý ukydaným bohům svým i napotom, poněvadž neposloucháte mne, a jména mého svatého nepoškvrňujte více dary svými, a ukydanými bohy svými.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 40, 'Nebo na hoře mé svaté, na hoře vysoké Izraelské, dí Panovník Hospodin, tam mi sloužiti budou všecken dům Izraelský, což jich koli bude v té zemi. Tam je laskavě přijmu, a tam vyhledávati budu od vás obětí vzhůru pozdvižení i prvotin darů vašich, se všemi svatými věcmi vašimi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 41, 'S vůní libou laskavě vás přijmu, když vás vyvedu z národů, a shromáždím vás z těch zemí, do nichž jste rozptýleni byli, a tak posvěcen budu v vás před očima těch národů.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 42, 'I poznáte, že já jsem Hospodin, když vás uvedu do země Izraelské, do země té, o kteréž jsem přisáhl, že ji dám otcům vašim.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 43, 'A tu se rozpomenete na cesty své a na všecky činy své, jimiž jste se poškvrňovali, tak že sami se býti hodné ošklivosti uznáte, pro všecky nešlechetnosti vaše, kteréž jste činívali.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 44, 'Tu poznáte, že já jsem Hospodin, když vám to učiním pro jméno své, ne podlé cest vašich zlých, ani podlé činů vašich porušených, dome Izraelský, praví Panovník Hospodin.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 45, 'I stalo se slovo Hospodinovo ke mně, řkoucí:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 46, 'Synu člověčí, obrať tvář svou k straně polední, a vypusť jako rosu na poledne, a prorokuj proti lesu toho pole, kteréž jest na poledne.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 47, 'A rci lesu polednímu: Slyš slovo Hospodinovo: Takto praví Panovník Hospodin: Aj, já zanítím v tobě oheň, kterýž sežere v tobě každé dřevo zelené i každé dřevo suché; nezhasneť plamen přeprudký, a budou jím opáleny všecky tváře od poledne až na půlnoci.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 48, 'I uzří všeliké tělo, že jsem já Hospodin zapálil jej; nezhasneť.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 49, 'I řekl jsem: Ach, Panovníče Hospodine, oni mi říkají: Však tento v přísloví nám toliko mluví.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 1, 'Opět stalo se slovo Hospodinovo ke mně, řkoucí:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 2, 'Synu člověčí, obrať tvář svou k Jeruzalému, a vypusť jako rosu proti místům svatým, a prorokuj proti zemi Izraelské.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 3, 'A rci zemi Izraelské: Takto praví Hospodin: Aj, já jsem proti tobě, a vytáhnu meč svůj z pošvy jeho, a vypléním z tebe spravedlivého i bezbožného.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 4, 'Proto, abych vyplénil z tebe spravedlivého i bezbožného, proto vyjde meč můj z pošvy své proti všelikému tělu, od poledne až na půlnoci.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 5, 'I zvíť všeliké tělo, že jsem já Hospodin vytáhl meč svůj z pošvy jeho; nenavrátíť se zase více.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 6, 'Ty pak synu člověčí, vzdychej, jako bys zlámaná měl bedra, a to s hořekováním vzdychej před očima jejich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 7, 'I stane se, žeť řeknou: Nad čím ty vzdycháš? Tedy řekneš: Nad pověstí, kteráž přichází, k níž rozplyne se každé srdce, a každé ruce klesnou, a všeliký duch skormoutí se, a každá kolena rozplynou se jako voda. Aj, přicházíť a děje se, praví Panovník Hospodin.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 8, 'Opět stalo se slovo Hospodinovo ke mně, řkoucí:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 9, 'Synu člověčí, prorokuj a rci: Takto praví Hospodin: Rci: Meč, meč nabroušen, také i vyčištěn jest.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 10, 'Aby zabíjel k zabití oddané, nabroušen jest; aby se blyštěl, vyčištěn jest. Radovati-liž se budeme, když prut syna mého pohrdá každým dřevem?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 11, 'Dalť jej vyčistiti, aby v ruku vzat byl; jestiť nabroušený meč, jest i vyčištěný, aby dán byl do ruky mordujícího.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 12, 'Křič a kvěl, synu člověčí, proto že ten bude proti lidu mému, tentýž proti všechněm knížatům Izraelským; uvrženi budou na meč s lidem mým, protož bí se v bedra.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 13, 'Když jsem je trestával, co bylo? Nemám-liž metly hubící již přičiniti? dí Hospodin zástupů.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 14, 'Ty tedy synu člověčí, prorokuj a tleskej rukama; nebo po druhé i po třetí přijde meč, meč mordujících, ten meč mordujících bez lítosti, pronikajících i do pokojů jejich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 15, 'Tak aby se rozplynulo srdce, a rozmnoženi byli úrazové, v každé bráně jejich postavím ostří meče. Ach, vyčištěnť jest, aby se blyštěl, zaostřen, aby zabíjel.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 16, 'Shlukni se a pusť se na pravo i na levo, kamžkoli a načkoli se tobě nahodí.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 17, 'I jáť také tleskati budu rukama svýma, a doložím prchlivost svou. Já Hospodin mluvil jsem.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 18, 'V tom stalo se slovo Hospodinovo ke mně, řkoucí:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 19, 'Ty pak synu člověčí, předlož sobě dvě cesty, kudy by jíti měl meč krále Babylonského. Z země jedné ať vycházejí obě dvě, a na rozcestí vybeř tu k městu, tu vybeř.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 20, 'Ukaž cestu, kudy by jíti měl meč, k Rabbat-li synů Ammon, čili k Judstvu, na Jeruzalémské pevnosti,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 21, 'Proto že stane král Babylonský na rozcestí, na počátku dvou cest, obíraje se s hádáním, vyčistí střely, doptávati se bude modl, hleděti bude do jater.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 22, 'Po pravé ruce jeho hádání ukáže Jeruzalém, aby sšikoval hejtmany, kteříž by ponoukali k mordování, a pozdvihovali hlasu s prokřikováním, aby přistavili berany válečné proti branám, aby vysypán byl násyp, a vzdělání byli šancové.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 23, 'I budou to míti za hádání marné před očima svýma ti, jenž se zavázali přísahami; a toť přivede na pamět nepravost, kterouž by popadeni byli.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 24, 'Protož takto praví Panovník Hospodin: Proto že ku paměti přivodíte nepravost svou, a odkrývá se nevěra vaše, tak že jsou patrní hříchové vaši ve všech činech vašich, proto že na pamět přicházíte, rukou tou popadeni budete.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 25, 'Ty pak nečistý bezbožníče, kníže Izraelské, jehož den přichází, a čas skonání nepravosti,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 26, 'Takto praví Panovník Hospodin: Sejmi tu čepici, a svrz tu korunu, kteráž nikdy již taková nebude; toho, kterýž na snížení přišel, povyš, a vyvýšeného poniž.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 27, 'Zmotanou, zmotanou, zmotanou učiním ji, (čehož prvé nebývalo), až přijde ten, jenž má právo, kteréž jsem jemu dal.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 28, 'Ty pak synu člověčí, prorokuj a rci: Takto praví Panovník Hospodin o synech Ammon, i o pohanění jejich, rci, pravím: Meč, meč dobyt jest, k zabíjení vyčištěn jest, aby hubil všecko, a aby se blyštěl.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 29, 'A ačkoli předpovídají tobě marné věci, a hádají tobě lež, aby tě přiložili k hrdlům zbitých bezbožníků, jejichž den přichází a čas skonání nepravosti:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 30, 'Schovej meč do pošvy jeho. Na místě, na kterémž jsi zplozena, v zemi přebývání tvého, budu tě souditi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 31, 'A vyleji na tě rozhněvání své, ohněm prchlivosti své na tě dmýchati budu, a dám tě v ruku lidí vzteklých, řemeslníků všecko kazících.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 32, 'Budeš ohni k sežrání, krev tvá bude u prostřed země, nebudeš připomínána; neboť jsem já Hospodin mluvil.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 1, 'Opět stalo se slovo Hospodinovo ke mně, řkoucí:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 2, 'Ty pak synu člověčí, zastával-li bys, zastával-liž bys toho města vražedlného? Raději mu oznam všecky ohavnosti jeho,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 3, 'A rci: Takto praví Panovník Hospodin: Přicházíť čas města toho, jenž prolévá krev u prostřed sebe, a dělá ukydané bohy proti sobě, aby se poškvrňovalo.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 4, 'Ty krví svou, kterouž jsi prolilo, zavinivši, a ukydanými bohy svými, jichž jsi nadělalo, sebe poškvrnivši, to jsi způsobilo, že se přiblížili dnové tvoji, a přišlo jsi k letům svým. Protož vydám tě v pohanění národům, a ku posměchu všechněm zemím.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 5, 'Blízké i daleké od tebe budou se tobě posmívati, ó zlopověstné a různic plné.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 6, 'Aj, knížata Izraelská jeden každý vší silou na to se vydali, aby krev v tobě prolévali.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 7, 'Otce i matku zlehčují v tobě, pohostinnému činí nátisk u prostřed tebe, sirotka a vdovu utiskují v tobě.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 8, 'Svatými věcmi mými zhrdáš, a sobot mých poškvrňuješ.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 9, 'Utrhači jsou v tobě, aby prolévali krev, a na horách jídají v tobě; nešlechetnost páší u prostřed tebe.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 10, 'Nahotu otce syn odkrývá v tobě, a nečisté v oddělení ponižují v tobě.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 11, 'Jiný pak s ženou bližního svého páše ohavnost, a jiný s nevěstou svou poškvrňuje se nešlechetností, a jiný sestry své, dcery otce svého, ponižuje v tobě.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 12, 'Dar berou v tobě, aby krev prolili; lichvu a úrok béřeš, a zisku hledáš s útiskem bližního svého, na mne se pak zapomínáš, dí Panovník Hospodin.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 13, 'Protož aj, já tleskl jsem rukama svýma nad ziskem tvým, jehož dobýváš, i nad tou krví, kteráž byla u prostřed tebe.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 14, 'Zdali ostojí srdce tvé? Zdaž odolají ruce tvé dnům, v nichž já budu zacházeti s tebou? Já Hospodin mluvil jsem i učiním.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 15, 'Nebo rozptýlím tě mezi pohany, a rozženu tě po krajinách, a do konce vyprázdním nečistotu tvou z tebe.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 16, 'A zavrženo jsuc před očima pohanů, poznáš, že já jsem Hospodin.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 17, 'Potom stalo se slovo Hospodinovo ke mně, řkoucí:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 18, 'Synu člověčí, obrátili se mi dům Izraelský v trůsku, všickni napořád jsou měď, cín, železo a olovo u prostřed peci, trůsky stříbra jsou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 19, 'Pročež takto praví Panovník Hospodin: Proto že jste vy všickni obrátili se v trůsky, protož aj, já shromáždím vás do Jeruzaléma.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 20, 'Jakž se shromažďuje stříbro a měď, železo, olovo i cín do prostřed peci, k rozdmýchání ohně vůkol něho a k rozpouštění: tak shromáždím v hněvě a v prchlivosti své, a slože, rozpouštěti vás budu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 21, 'Sberu vás, pravím, a rozdmýchám okolo vás oheň prchlivosti své, i rozpustíte se u prostřed města.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 22, 'Jakž se stříbro rozpouští v peci, tak se rozpustíte u prostřed něho, i zvíte, že já Hospodin vylil jsem prchlivost svou na vás.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 23, 'Ještě stalo se slovo Hospodinovo ke mně, řkoucí:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 24, 'Synu člověčí, rci: Ty země jsi nečistá, nebudeš deštěm svlažena v den rozhněvání.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 25, 'Spiknutí proroků jejích u prostřed ní, jsou podobni lvu řvoucímu, uchvacujícímu loupež, duše žerou, bohatství a věci drahé berou, a činí mnoho vdov u prostřed ní.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 26, 'Kněží její natahují zákona mého, a svaté věci mé poškvrňují, mezi svatým a poškvrněným rozdílu nečiní, a mezi nečistým a čistým nerozeznávají. Nadto od sobot mých skrývají oči své, tak že zlehčován bývám mezi nimi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 27, 'Knížata její u prostřed ní jsou jako vlci uchvacující loupež, vylévajíce krev, hubíce duše, aby sháněli mrzký zisk.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 28, 'Proroci pak jejich obmítají jim vápnem ničemným, předpovídají marné věci, a hádají jim lež, říkajíce: Takto praví Panovník Hospodin, ješto Hospodin nemluvil.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 29, 'Lid této země činí nátisk, a cizí věci mocí béře, chudému a nuznému ubližují, a pohostinného utiskují nespravedlivě.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 30, 'Hledaje pak někoho z nich, kterýž by udělal hradbu, a postavil se v mezeře před tváří mou za tuto zemi, abych jí nezkazil, žádného nenacházím.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 31, 'Protož vyleji na ně rozhněvání své, ohněm prchlivosti své konec jim učiním, cestu jejich jim na hlavu obrátím, praví Panovník Hospodin.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 1, 'Opět stalo se slovo Hospodinovo ke mně, řkoucí:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 2, 'Synu člověčí, dvě ženy, dcery jedné mateře byly.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 3, 'Ty smilnily v Egyptě, v mladosti své smilnily. Tam jsou mačkány prsy jejich, tam opiplány prsy panenství jejich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 4, 'Jména pak jejich: větší Ahola, sestry pak její Aholiba. Tyť jsou byly mé, a rozplodily syny a dcery. Jména, pravím, jejich jsou: Samaří Ahola, Jeruzaléma pak Aholiba.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 5, 'Ale Ahola maje mne, smilnila a frejů hleděla s milovníky svými, s Assyrskými blízkými,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 6, 'Oděnými postavcem modrým, s vývodami a knížaty, i všemi napořád mládenci krásnými, a s jezdci jezdícími na koních.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 7, 'Vydala se, pravím, v smilství svá s nimi, se všemi nejpřednějšími syny Assyrskými, a se všemi, jimž frejovala, a poškvrnila se všemi ukydanými bohy jejich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 8, 'A tak smilství svých Egyptských nenechala; nebo ji zléhali v mladosti její, a oni mačkali prsy panenství jejího, a vylili smilství svá na ni.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 9, 'Protož dal jsem ji v ruku frejířů jejích, v ruku Assyrských, jimž frejovala.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 10, 'Oniť jsou odkryli nahotu její, syny i dcery její pobrali, ji pak samu mečem zamordovali. Takž vzata jest na slovo od jiných žen, když soudy vykonali při ní.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 11, 'To viděla sestra její Aholiba, však mnohem více než onano frejovala, a smilství její větší byla než smilství sestry její.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 12, 'S Assyrskými frejů hleděla, s vývodami a knížaty blízkými, oděnými nádherně, s jezdci jezdícími na koních, a všemi mládenci krásnými.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 13, 'I viděl jsem, že se poškvrnila, a že cesta jednostejná jest obou dvou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 14, 'Ale tato ještě to přičinila k smilstvím svým, že viduc muže vyryté na stěně, obrazy Kaldejských vymalované barvou,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 15, 'Přepásané pasem po bedrách jejich, a klobouky barevné na hlavách jejich, a že jsou všickni na pohledění jako hejtmané, podobní synům Babylonským v Kaldejské zemi, jejichž ona vlast jest,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 16, 'I zahořela k nim z pohledění očima svýma, a vyslala posly k nim do země Kaldejské.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 17, 'Tedy vešli k ní Babylonští na lůže nepoctivé, a poškvrnili ji smilstvím svým. A když se poškvrnila s nimi, odloučila se duše její od nich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 18, 'A odkryla smilství svá, odkryla též nahotu svou, i odloučila se duše má od ní, tak jako se odloučila duše má od sestry její.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 19, 'Nebo rozmnožila smilství svá, rozpomínajíc se na dny mladosti své, v nichž smilnila v zemi Egyptské,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 20, 'A frejovala s kuběnáři jejich, jejichž tělo jest jako tělo oslů, a tok jejich jako tok koňský.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 21, 'A tak jsi zase navrátila se k nešlechetnosti mladosti své, když mačkali Egyptští prsy tvé z příčiny prsů mladosti tvé.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 22, 'Protož ó Aholiba, takto praví Panovník Hospodin: Aj, já vzbudím frejíře tvé proti tobě, ty, od nichž se odloučila duše tvá, a přivedu je na tě odevšad,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 23, 'Babylonské a všecky Kaldejské, Pekodské, a Šohejské, i Kohejské, všecky syny Assyrské s nimi, mládence krásné, vývody a knížata všecka, hejtmany a slovoutné, všecky jezdící na koních.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 24, 'A přitáhnou na tě na vozích železných a přikrytých, i kárách, a to s zběří národů, s pavézami a štíty i lebkami, položí se proti tobě vůkol, i předložím jim právo, aby tě soudili soudy svými.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 25, 'Vyleji zajisté horlení své na tebe, tak že naloží s tebou prchlivě, nos tvůj i uši tvé odejmou, a ostatek tebe mečem padne. Ti syny tvé i dcery tvé poberou, a ostatek tebe spáleno bude ohněm.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 26, 'A vyvlekou tě z roucha tvého, a rozberou šperky okrasy tvé.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 27, 'A tak přítrž učiním při tobě nešlechetnosti tvé, i smilství tvému z země Egyptské vzatému, a nepozdvihneš očí svých k nim, a na Egypt nezpomeneš více.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 28, 'Nebo takto praví Panovník Hospodin: Aj, já dám tebe v ruku těch, kterýchž nenávidíš, v ruku těch, od nichž se odloučila duše tvá,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 29, 'I budou nakládati s tebou podlé nenávisti, a poberou všecko úsilé tvé, a nechají tě nahé a obnažené. A tak bude zřejmá nahota smilství tvého a nešlechetnosti tvé, smilství, pravím, tvého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 30, 'Což vše učiní tobě proto, že jsi smilnila, následujíc pohanů, proto že jsi poškvrnila se ukydanými bohy jejich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 31, 'Cestou sestry své chodila jsi, protož dám kalich její v ruku tvou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 32, 'Takto praví Panovník Hospodin: Kalich sestry své píti budeš hluboký a široký; budeť sporý, tak že smích a žert budou míti z tebe.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 33, 'Opilstvím a zámutkem naplněna budeš, kalichem pustiny a zpuštění, kalichem sestry své Samaří.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 34, 'I vypiješ jej a vyvážíš, a než jej polámeš, snáze prsy své roztrháš; neboť jsem já mluvil, praví Panovník Hospodin.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 35, 'Protož takto praví Panovník Hospodin: Z té příčiny, že jsi zapomenula na mne, a zavrhlas mne za hřbet svůj, i ty také vezmi za svou nešlechetnost, a za smilství svá.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 36, 'I řekl Hospodin ke mně: Synu člověčí, budeš-liž zastávati Ahole neb Aholiby? Nýbrž oznam jim ohavnosti jejich,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 37, 'Že cizoložily, a krev jest na rukou jejich, a s ukydanými bohy svými cizoložily. Také i syny své, kteréž mně zplodily, vodily jim, aby sežráni byli.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 38, 'Ještě i toto činily mi, že zanečišťovaly svatyni mou v tentýž den, a sobot mých poškvrňovaly.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 39, 'Nebo obětovavše syny své ukydaným bohům svým, vcházely do svatyně mé v tentýž den, aby ji poškvrnily. Aj hle, takť jsou činívaly u prostřed mého domu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 40, 'Nadto, že vysílaly k mužům, jenž by přišli zdaleka, kteříž, jakž posel vyslán k nim, aj, hned přicházívali. Jimž jsi se umývala, a tvář svou líčila, a okrašlovalas se okrasou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 41, 'A usazovalas se na loži slavném, před nímž stůl připravený byl, na něž jsi i kadidlo mé i masti mé vynakládala.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 42, 'Když pak hlas toho množství poutichl, tedy i k mužům z obecného lidu vysílaly, jenž bývali přivozováni ožralí z pouště. I dávali náramky na ruce jejich, i koruny ozdobné na hlavy jejich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 43, 'A ačkoli jsem se domlouval na cizoložství té lotryně, a že oni jednak s jednou, jednak s druhou smilství provodí,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 44, 'A že každý z nich vchází k ní, tak jako někdo vchází k ženě nevěstce: však vždy vcházeli k Ahole a Aholibě, ženám přenešlechetným.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 45, 'Protož muži spravedliví, tiť je souditi budou soudem cizoložných a soudem těch, jenž vylévaly krev, proto že cizoložily, a krev jest na rukou jejich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 46, 'Nebo takto praví Panovník Hospodin: Přivedu na ně vojsko, a dám je v posmýkání i v loupež.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 47, 'I uhází je to shromáždění kamením, a poseká je meči svými; syny jejich i dcery jejich pomordují, a domy jejich ohněm popálí.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 48, 'A tak přítrž učiním nešlechetnosti v zemi této, i budou se tím káti všecky ženy, a nedopustí se nešlechetnosti podobné vaší.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 49, 'Nebo vzložena bude na vás nešlechetnost vaše, a ponesete hříchy ukydaných bohů svých. I zvíte, že já jsem Panovník Hospodin.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 1, 'Opět stalo se slovo Hospodinovo ke mně léta devátého, měsíce desátého, desátého dne téhož měsíce, řkoucí:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 2, 'Synu člověčí, napiš sobě jméno tohoto dne, vlastně dnešního dne tohoto: nebo oblehl král Babylonský Jeruzalém právě tohoto dnešního dne.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 3, 'A předlož tomu domu zpurnému podobenství, řka k nim: Takto praví Panovník Hospodin: Přistav tento hrnec, přistav a nalej také do něho vody.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 4, 'A sebera kusy náležité do něho, každý kus dobrý, stehno i plece, a nejlepšími kostmi naplň jej.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 5, 'Přivezmi i nejlepších bravů, a udělej oheň z kostí pod ním, způsob, ať to vře, ažby kypělo, ať se i kosti jeho rozvaří v něm.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 6, 'Protož takto praví Panovník Hospodin: Běda městu tomu vražedlnému, hrnci, v němž zůstává připálenina jeho, z něhož, pravím, připálenina jeho nevychází. Po kusích, po kusích vytahuj z něho, nepadneť na něj los.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 7, 'Nebo krev jest u prostřed něho. Na vysedlou skálu vystavilo ji; nevylilo jí na zemi, aby ji prach přikryl.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 8, 'I já zanítě prchlivost k vykonání pomsty, vystavím krev na vysedlou skálu, aby nebyla přikryta.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 9, 'Protož takto praví Panovník Hospodin: Běda městu vražedlnému, i já udělám veliký oheň,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 10, 'Přikládaje dříví, rozněcuje oheň, v nic obraceje maso, a kořeně kořením, tak že i kosti spáleny budou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 11, 'A postavím ten hrnec na uhlí jeho prázdný, aby se zhřela i rozpálila měď jeho, ažby se vyvařila u prostřed něho nečistota jeho, a vyprázdnila připálenina jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 12, 'Klamy svými bylo mi těžké, protož nevyjde z něho množství šumu jeho; do ohně musí šum jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 13, 'V tvé nečistotě jest nešlechetnost, proto že jsem tě očišťoval, však nejsi očištěno. Nebudeš více očišťováno od nečistoty své, až i doložím prchlivost svou na tebe.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 14, 'Já Hospodin mluvil jsem, dojdeť, a učiním to; neustoupímť, aniž se slituji, ani želeti budu. Podlé cest tvých a činů tvých budou tě souditi, praví Panovník Hospodin.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 15, 'Opět stalo se slovo Hospodinovo ke mně, řkoucí:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 16, 'Synu člověčí, aj, já odejmu od tebe žádost očí tvých v náhle, však nekvěl ani plač, a nechť nevycházejí slzy tvé.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 17, 'Stonati přestaň, smutku, jakž bývá nad mrtvým, nenes, klobouk svůj vstav na sebe, a střevíce své obuj na nohy své, a nezastírej brady své, aniž pokrmu čího jez.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 18, 'Což když jsem pověděl lidu ráno, tedy umřela žena má u večer. I učinil jsem na ráno, jakž mi rozkázáno bylo.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 19, 'I řekl ke mně lid: Což nám neoznámíš, co tyto věci nám znamenají, kteréž činíš?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 20, 'Tedy řekl jsem jim: Slovo Hospodinovo stalo se ke mně, řkoucí:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 21, 'Rci domu Izraelskému: Takto praví Panovník Hospodin: Aj, já poškvrním svatyně své, vyvýšenosti síly vaší, žádosti očí vašich a toho, čehož šanuje duše vaše. Též synové vaši i dcery vaše, kterýchž jste zanechali, mečem padnou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 22, 'I budete tak činiti, jakž já činím. Brady nezastřete, aniž čího pokrmu jísti budete.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 23, 'A majíce klobouky své na hlavách svých a střevíce na nohách svých, nebudete kvíliti ani plakati, ale svadnouce pro nepravosti své, úpěti budete jeden s druhým.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 24, 'Nebo jest vám Ezechiel zázrakem. Všecko, což on činí, budete činiti, a když to přijde, tedy zvíte, že já jsem Panovník Hospodin.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 25, 'Ty pak synu člověčí, zdali v ten den, když já odejmu od nich sílu jejich, veselé okrasy jejich, žádost očí jejich, a to, po čemž touží duše jejich, syny jejich i dcery jejich,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 26, 'Zdali v ten den přijde k tobě ten, kdož uteče, vypravuje tu novinu?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 27, 'V ten den otevrou se ústa tvá při přítomnosti toho, kterýž ušel, i budeš mluviti, a nebudeš více němým. Takž jim budeš zázrakem, i zvědí, že já jsem Hospodin.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 1, 'I stalo se slovo Hospodinovo ke mně, řkoucí:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 2, 'Synu člověčí, obrať tvář svou proti synům Ammon, a prorokuj proti nim.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 3, 'A rci synům Ammon: Slyšte slovo Panovníka Hospodina: Takto praví Panovník Hospodin: Proto že jsi nad svatyní mou, když poškvrněna byla, říkal: To dobře to, a nad zemí Izraelskou, když zpuštěna byla, a nad domem Judským, když šel v zajetí,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 4, 'Protož aj, já dám tě národům východním za dědictví, i vzdělají sobě hrady v tobě, a vystavějí v tobě příbytky své. Tiť budou jísti ovoce tvé, a ti budou píti mléko tvé.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 5, 'A dám Rabbu za obydlé velbloudům, a města synů Ammon za odpočivadlo stádům, i zvíte, že já jsem Hospodin.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 6, 'Nebo takto praví Panovník Hospodin: Proto že jsi tleskal rukou, a dupal nohou, a veselil se srdečně, že jsi všelijak loupil zemi Izraelskou,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 7, 'Protož aj, já vztáhnu ruku svou na tebe, a vydám tě v loupež národům, a vypléním tě z lidí, a vyhubím tě z zemí, i zahladím tě. Tu zvíš, že já jsem Hospodin.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 8, 'Takto praví Panovník Hospodin: Z té příčiny, že říkal Moáb a Seir: Hle, podobný jest všechněm jiným národům dům Judský,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 9, 'Protož aj, já otevru bok Moábských, (hned od Arim, od měst jejich na pomezí jejich, rozkošnou zemi Betjesimotských, Balmeonských i Kariataimských),');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 10, 'Národům východním s zemí synů Ammon; nebo jsem ji dal v dědictví, tak aby nebylo zpomínáno na syny Ammon mezi národy.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 11, 'A tak i nad Moábem soudy vykonám, i zvědí, že já jsem Hospodin.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 12, 'Takto praví Panovník Hospodin: Proto že Idumejští nenáležitě se vymstívajíce, ukrutně se měli k domu Judskému, a tak uvodili na se vinu velikou, vymstívajíce se na nich,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 13, 'Protož takto dí Panovník Hospodin: I na Idumea vztáhnu ruku svou, a vypléním z něho lidi i hovada, a obrátím jej v pustinu. Hned od Teman až do Dedan mečem padati budou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 14, 'A tak uvedu pomstu svou na Idumejské skrze ruku lidu mého Izraelského, a naloží s Idumejskými podlé hněvu mého a podlé prchlivosti mé, i poznají pomstu mou, praví Panovník Hospodin.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 15, 'Takto praví Panovník Hospodin: Proto že se Filistinští ukrutně měli z příčiny pomsty, nenáležitě se vymstívajíce, loupíce zlostně, a zhoubu uvodíce z nenávisti starodávní,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 16, 'Protož takto praví Panovník Hospodin: Aj, já vztáhnu ruku svou na Filistinské, a vypléním Ceretejské, a zkazím ostatek přístavu mořského.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 17, 'A tak vykonám při nich pomsty veliké káraními zůřivými, a zvědí, že já jsem Hospodin, když uvedu pomstu svou na ně.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 1, 'Bylo pak jedenáctého léta, prvního dne měsíce, že se stalo slovo Hospodinovo ke mně, řkoucí:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 2, 'Synu člověčí, proto že Týrus o Jeruzalému říká: Dobře se stalo, že jest potříno město bran velmi lidných, obrací se ke mně, naplněn budu, kdyžtě zpuštěno,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 3, 'Protož takto praví Panovník Hospodin: Aj, já proti tobě, ó Týre, a přivedu na tě národy mnohé, tak jako bych přivedl moře s vlnami jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 4, 'I zkazí zdi Týru, a zboří věže jeho; vymetu také z něho prach jeho, a obrátím jej v skálu vysedlou,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 5, 'Tak že budou vysušovati síti u prostřed moře. Nebo jsem já mluvil, praví Panovník Hospodin, protož bude v loupež národům.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 6, 'Dcery pak jeho, kteréž na poli budou, mečem zmordovány budou, i zvědí, že já jsem Hospodin.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 7, 'Nebo takto praví Panovník Hospodin: Aj, já přivedu na Týr Nabuchodonozora krále Babylonského od půlnoci, krále nad králi, s koňmi a s vozy, i s jezdci i s vojskem a s lidem mnohým.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 8, 'Dcery tvé na poli mečem zmorduje, a vzdělá proti tobě šance, a vysype proti tobě násyp, a postaví proti tobě pavézníky.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 9, 'I střelbu zasadí proti zdem tvým, a věže tvé poboří nosatci svými.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 10, 'Od množství koní jeho přikryje tě prach jejich; od hřmotu jezdců a kár i vozů zatřesou se zdi tvé, když on vcházeti bude do bran tvých, jako do průchodů města probořeného.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 11, 'Kopyty koní svých pošlapá všecky ulice tvé, lid tvůj mečem pomorduje, a sloupové pamětní síly tvé na zem padnou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 12, 'I rozberou zboží tvá, a rozchvátají kupectví tvá, a rozválejí zdi tvé, i domy tvé rozkošné poboří, a kamení tvé i dříví tvé, i prach tvůj do vody vmecí.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 13, 'A tak přítrž učiním hluku zpěvů tvých, a zvuku citar tvých aby nebylo slýcháno více.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 14, 'A obrátím tě v skálu vysedlou, budeš k vysušování sítí, nebudeš vystaven více; nebo já Hospodin mluvil jsem, praví Panovník Hospodin.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 15, 'Takto praví Panovník Hospodin Týru: Zdaliž od hřmotu padání tvého, když stonati budou zranění, když ukrutný mord bude u prostřed tebe, nepohnou se ostrovové?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 16, 'A vyvstanou z stolic svých všecka knížata pomořská, a složí z sebe pláště své, i roucha svá krumpovaná svlekou; v hrůzu se oblekou, na zemi seděti budou, a třesouce se každé chvíle, trnouti budou nad tebou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 17, 'I vydadí se nad tebou v naříkání, a řeknou tobě: Jak jsi zahynulo, ó město, v němž bydleno bylo pro moře, město slovoutné, ješto bylo pevné na moři, ono i s obyvateli svými, kteříž pouštěli strach svůj na všecky obyvatele jeho!');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 18, 'Tehdáž třásti se budou ostrovové v den pádu tvého; předěšeni, pravím, budou ostrovové, kteříž jsou na moři, nad zahynutím tvým.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 19, 'Nebo tak praví Panovník Hospodin: Když tě učiním městem zpuštěným jako města, v nichž se nebydlí, když uvedu na tě hlubinu, tak že tě přikryjí vody mnohé,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 20, 'Když učiním, že sstoupíš s sstupujícími do jámy k lidu dávnímu, a posadím tě v nejnižších stranách země, na pustinách starodávních s těmi, jenž sstupují do jámy, aby nebylo bydleno v tobě: prokáži slávu v zemi živých.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 21, 'Nebo učiním to, že budeš k náramné hrůze, když tě nestane, a bys pak bylo hledáno, abys nebylo na věky nalezeno, praví Panovník Hospodin.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 1, 'I stalo se slovo Hospodinovo ke mně, řkoucí:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 2, 'Ty pak synu člověčí, vydej se nad Týrem v naříkání,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 3, 'A rci Týru, jenž sedě tu, kdež se na moře pouštějí, kupectví provodí s národy na ostrovích mnohých: Takto praví Panovník Hospodin: Ó Týre, ty jsi říkal: Já jsem nejkrásnější.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 4, 'U prostřed moře byly hranice tvé, stavitelé tvoji dokonale tě ozdobovali.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 5, 'Z jedloví z Sanir dělávali všecka taflování tvá, cedry z Libánu brávali k dělání sloupů tvých.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 6, 'Z dubů Bázanských dělávali vesla tvá, a lavičky tvé dělávali z kostí slonových, a z pušpanu z ostrovů Citejských.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 7, 'Kment s krumpováním Egyptským býval plátno tvé, z něhož jsi plachty míval; modrý postavec a šarlat z ostrovů Elisa přikrýval tě.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 8, 'Obyvatelé Sidonští i Arvadští bývali plavci tvoji, moudří tvoji v tobě, ó Týre, ti bývali správcové tvoji.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 9, 'Starší Gebalští a moudří jejich opravovali v tobě zbořeniny tvé; všecky lodí mořské i plavci jejich bývali v tobě, směňujíce s tebou kupectví.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 10, 'Perští a Ludští i Putští bývali v vojště tvém bojovníci tvoji, pavézu a lebku zavěšovali v tobě. Tiť jsou přidávali tobě ozdoby.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 11, 'Arvadští s vojskem tvým na zdech tvých vůkol, též Gamadští na věžech tvých bývali, štíty své zavěšovali na zdech tvých vůkol. Tiť jsou tě zvláštně ozdobovali.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 12, 'Zámořští kupci tvoji v množství všelijakého zboží, v stříbře, železe, cínu i olově kupčili na jarmarcích tvých.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 13, 'Javan, Tubal a Mešech, kupci tvoji, lidi a nádobí měděné dávali za směnu tobě.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 14, 'Z domu Togarma v koních a jezdcích i mezcích kupčili na jarmarcích tvých.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 15, 'Synové Dedanovi kupci tvoji, a ostrovové mnozí překupníci byli koupí tvých, tobě k ruce; rohy, kosti slonové i dříví hebénové směňovali za mzdu tvou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 16, 'Syrští kupci tvoji pro množství věcí tvých řemeslně udělaných, v karbunkulích, šarlatu, krumpování i kmentu, a korálích a křištálích kupčívali na jarmarcích tvých.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 17, 'Judští i země Izraelská kupci tvoji, pšenici Mennitskou i Fenickou, a med, olej i kadidlo dávali za směnu tobě.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 18, 'Damašští kupci tvoji, pro množství věcí tvých řemeslně udělaných, kupčili ve množství všelijakého zboží, ve víně Chelbonském a vně bělostkvoucí.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 19, 'Též Dan i Javan chodíce na jarmarky tvé, kupčili, a železo pulerované, kassii i třtinu vonnou tobě směňovali.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 20, 'Dedan kupčíval v tobě v suknech drahých k vozům.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 21, 'Arabští i všecka knížata Cedarská kupčívali tobě k ruce v beranech a skopcích i kozlích, tím kupčívali v tobě.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 22, 'Kupci Sabejští i Ragmejští bývali kupci tvoji ve všelijakých nejpřednějších vonných věcech, i ve všelijakém kamení drahém i zlatě, kupčívali na jarmarcích tvých.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 23, 'Cháran a Kanne i Eden, kupci Sabejští, Assur i Kilmad kupčíval v tobě.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 24, 'Ti bývali kupci tvoji na jarmarcích tvých s nejvýbornějšími věcmi, s štoučkami postavce modrého, a s krumpováním i s klénoty drahých věcí, kteréž se provazy svazují a zavírají do cedru.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 25, 'Lodí mořské předek měly v kupectví tvém. Summou, naplněno jsi i zvelebeno náramně u prostřed moře.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 26, 'Na vodu velikou zavezli tě ti, kteříž tě vesly táhli; vítr východní potříská tě u prostřed moře.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 27, 'Zboží tvá i jarmarkové tvoji, kupectví tvá, plavci tvoji a správcové tvoji, i ti, kteříž opravovali zbořeniny tvé, a směňovali s tebou kupectví, a všickni muži váleční tvoji, kteříž byli v tobě, i všecko shromáždění tvé, kteréž bylo u prostřed tebe, padnou do hlubokosti mořské v den pádu tvého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 28, 'Od hřmotu křiku správců tvých zbouří se i vlnobití.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 29, 'I vystoupí z lodí svých všickni ti, kteříž táhnou veslem, plavci i všickni správcové lodí mořských na zemi stanou,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 30, 'A hlasem velikým nad tebou naříkati a žalostně křičeti budou, a sypouce prach na hlavy své, v popele se váleti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 31, 'Nadto zdělajíce příčinou tvou lysiny, přepáší se žíněmi, a kvílením hořkým nad tebou s žalostí srdečnou plakati budou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 32, 'Vydadí se, pravím, nad tebou s hořekováním svým v naříkání, a budou naříkati nad tebou: Které město podobné Týru, zahlazenému u prostřed moře?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 33, 'Když vycházely koupě tvé z moře, nasycovalo jsi národy mnohé; množstvím zboží svého i kupectví svých zbohacovalos krále zemské.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 34, 'Ale když ztroskotáno budeš od moře v hlubokých vodách, kupectví tvé i všecko shromáždění tvé u prostřed tebe klesne.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 35, 'Všickni obyvatelé ostrovů ztrnou nad tebou, a králové jejich ohromeni jsouce, zhrozí se náramně.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 36, 'Kupci mezi národy ckáti budou nad tebou; k hrůze veliké budeš, a nebude tě na věky.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 1, 'I stalo se slovo Hospodinovo ke mně, řkoucí:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 2, 'Synu člověčí, rci vývodovi Tyrskému: Takto praví Panovník Hospodin: Proto že se vyvyšuje srdce tvé, a říkáš: Bůh silný jsem, na stolici Boží sedím u prostřed moře, ješto jsi člověk a ne Bůh silný, ačkoli sobě přivlastňuješ srdce podobné srdci Božímu,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 3, 'Aj hle, moudřejší jsi nad Daniele, žádná věc tajná není před tebou ukrytá;');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 4, 'Moudrosti svou a rozumností svou nashromáždils sobě zboží, a nahrnuls zlata a stříbra do pokladů svých;');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 5, 'Velikou moudrostí svou v kupectví svém rozmnožil jsi zboží svá, a tak pozdvihlo se srdce tvé zbožím tvým;');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 6, 'Z té příčiny takto praví Panovník Hospodin: Proto že sobě přivlastňuješ srdce podobné srdci Božímu,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 7, 'Protož aj, já přivedu na tě cizozemce, nejukrutnější národy, kteříž vytrhnouce meče své na krásu moudrosti tvé, zabijí jasnost tvou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 8, 'Do jámy spustí tě, a umřeš smrtí hroznou u prostřed moře.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 9, 'Budeš-liž tu ještě říkati před oblíčejem mordéře svého: Bohem jsem, poněvadž jsi člověk a ne Bůh silný, jsa v ruce toho, jenž tě mordovati bude?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 10, 'Smrtí neobřezanců umřeš od ruky cizozemců; nebo já mluvil jsem, praví Panovník Hospodin.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 11, 'I stalo se slovo Hospodinovo ke mně, řkoucí:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 12, 'Synu člověčí, vydej se v naříkání nad králem Tyrským, a rci jemu: Takto praví Panovník Hospodin: Ty, jenž zapečeťuješ summy, plný moudrosti a nejkrásnější,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 13, 'V Eden, zahradě Boží, byl jsi, všelijaké drahé kamení přikrývalo tě, sardius, topazius, jaspis, tarsis, onychin, beryl, zafir, karbunkulus a smaragd i zlato; nástrojové bubnů tvých a píšťal tvých v tobě, hned jakžs se narodil, připraveni jsou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 14, 'Ty jsi cherubem od pomazání. Jakž jsem tě za ochránce představil, na hoře svaté Boží jsi byl, u prostřed kamení ohnivého ustavičně jsi chodil.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 15, 'Byl jsi dokonalý na cestách svých, hned jakžs se narodil, až se našla nepravost při tobě.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 16, 'Pro množství kupectví tvého u prostřed tebe plno jest bezpráví, a velmi jsi prohřešil. Pročež zahubím tě, a vyhladím z hory Boží, ó cherube ochránce, z prostřed kamenů ohnivých.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 17, 'Pozdvihlo se srdce tvé slávou tvou, k zlému jsi užíval moudrosti své příčinou jasnosti své. Porazím tě na zemi, před oblíčej králů povrhu tě, aby se dívali na tebe.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 18, 'Pro množství nepravostí tvých, a pro nespravedlnosti kupectví tvého poškvrnil jsi svatyně své. Protož vyvedu oheň z prostřed tebe, kterýž tě sžíře, a obrátí tě v popel na zemi před očima všech na tě hledících.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 19, 'Všickni, kdož tě znali mezi národy, ztrnou nad tebou; k hrůze veliké budeš, a nebude tě na věky.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 20, 'I stalo se slovo Hospodinovo ke mně, řkoucí:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 21, 'Synu člověčí, obrať tvář svou proti Sidonu, a prorokuj proti němu,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 22, 'A rci: Takto praví Panovník Hospodin: Aj, já proti tobě jsem, ó Sidone, a budu oslaven u prostřed tebe. I zvědí, že já jsem Hospodin, když vykonám při něm soudy, a posvěcen budu v něm.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 23, 'Pošli zajisté na něj mor, a krev na ulice jeho, a padati budou zranění u prostřed něho od meče na všecky strany, i zvědí, že já jsem Hospodin.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 24, 'A tak nebude více míti dům Izraelský trnu urážejícího a bodláku bodoucího ze všech okolních pohrdajících jimi, a zvědí, že já jsem Panovník Hospodin.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 25, 'Takto praví Panovník Hospodin: Když shromáždím dům Izraelský z národů, mezi něž rozptýleni jsou, a posvěcen budu v nich před očima pohanů, a bydliti budou v zemi své, kterouž jsem byl dal služebníku svému Jákobovi:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 26, 'Tehdy bydliti budou v ní bezpečně, a nastavějí domů, a štípí vinice. Bydliti, pravím, budou bezpečně, když vykonám soudy, při všech zhoubcích jejich vůkol nich, i zvědí, že já jsem Hospodin Bůh jejich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 1, 'Léta desátého, desátého měsíce, dvanáctého dne téhož měsíce, stalo se slovo Hospodinovo ke mně, řkoucí:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 2, 'Synu člověčí, obrať tvář svou proti Faraonovi králi Egyptskému, a prorokuj proti němu i proti všemu Egyptu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 3, 'Mluv a rci: Takto praví Panovník Hospodin: Aj, já proti tobě jsem, ó Faraone králi Egyptský, draku veliký, kterýž ležíš u prostřed řek svých, ješto říkáš: Já mám řeku svou, já zajisté jsem ji přivedl sobě.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 4, 'Protož dám udici do čelistí tvých, a učiním, že zváznou ryby řek tvých na tvých šupinách; i vyvleku tě z prostředku řek tvých, i všecky ryby řek tvých na šupinách tvých zvázlé.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 5, 'A nechám tě na poušti, tebe i všech ryb řek tvých. Na svrchku pole padneš, nebudeš sebrán ani shromážděn; šelmám zemským i ptactvu nebeskému dám tě k sežrání.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 6, 'I zvědí všickni obyvatelé Egyptští, že já jsem Hospodin, proto že jste holí třtinovou domu Izraelskému.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 7, 'Když se chytají tebe rukou, lámeš se, a roztínáš jim všecko rameno; a když se na tě zpodpírají, ztroskotána býváš, ačkoli nastavuješ jim všech bedr.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 8, 'Protož takto praví Panovník Hospodin: Aj, já přivedu na tě meč, a vypléním z tebe lidi i hovada.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 9, 'I bude země Egyptská pustinou a pouští, i zvědí, že já jsem Hospodin, proto že říkal: Řeka má jest, já zajisté jsem ji přivedl.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 10, 'Protož aj, já budu proti tobě i proti řece tvé, a obrátím zemi Egyptskou v pustiny, v poušť přehroznou od věže Sevéne až do pomezí Mouřenínského.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 11, 'Nepůjdeť přes ni noha člověka, ani noha dobytčete půjde přes ni, a nebude v ní bydleno za čtyřidceti let.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 12, 'A tak uvedu zemi Egyptskou v pustinu nad jiné země pusté, a města její nad jiná města zpuštěná pustá budou za čtyřidceti let, když rozptýlím Egyptské mezi národy, a rozženu je do rozličných zemí.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 13, 'A však takto praví Panovník Hospodin: Po skonání čtyřidceti let shromáždím Egyptské z národů, kamž rozptýleni budou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 14, 'A přivedu zase zajaté Egyptské, a uvedu je zase do země Patros, do země přebývání jejich, i budou tam královstvím sníženým.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 15, 'Mimo jiná království bude sníženější, aniž se bude vynášeti více nad jiné národy; zmenším je zajisté, aby nepanovali nad národy.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 16, 'I nebude více domu Izraelskému doufáním, kteréž by na pamět přivodilo nepravost, když by se obraceli za nimi; nebo zvědí, že já jsem Panovník Hospodin.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 17, 'Potom bylo dvadcátého sedmého léta, prvního měsíce, prvního dne, že se stalo slovo Hospodinovo ke mně, řkoucí:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 18, 'Synu člověčí, Nabuchodonozor král Babylonský podrobil vojsko své v službu velikou proti Týru. Každá hlava oblezla, a každé rameno odříno jest, mzdy pak nemá, on ani vojsko jeho, z Týru za tu službu, kterouž sloužili proti němu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 19, 'Z té příčiny takto praví Panovník Hospodin: Aj, já dávám Nabuchodonozorovi králi Babylonskému zemi Egyptskou, aby pobral zboží její, a rozebral loupeže její, i rozchvátal kořisti její, aby mělo mzdu vojsko jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 20, 'Za práci jejich, kterouž mi sloužili, dám jim zemi Egyptskou, proto že mně pracovali, praví Panovník Hospodin.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 21, 'V ten den rozkáži vypučiti se rohu domu Izraelského. Tobě též způsobím, že otevřeš ústa u prostřed nich, i zvědí, že já jsem Hospodin.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 1, 'Opět se stalo slovo Hospodinovo ke mně, řkoucí:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 2, 'Synu člověčí, prorokuj a rci: Takto praví Panovník Hospodin: Kvělte: Ach, nastojte na tento den.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 3, 'Nebo blízko jest den, blízko jest, pravím, den Hospodinův, den mrákoty, čas národů bude.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 4, 'A přijde meč do Egypta, a bude přetěžká bolest v Mouřenínské zemi, když padati budou zbití v Egyptě, a poberou zboží jeho, a zbořeni budou základové jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 5, 'Mouřenínové a Putští i Ludští i všelijaká směsice, též Kubští i obyvatelé země smlouvy s nimi mečem padnou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 6, 'Takť praví Hospodin, že padnou podpůrcové Egypta, a snížena bude vyvýšenost síly jeho; od věže Sevéne mečem padati budou v ní, praví Panovník Hospodin.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 7, 'I budou v pustinu obráceni nad jiné země pusté, a města jejich nad jiná města pustá budou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 8, 'I zvědí, že já jsem Hospodin, když zapálím oheň v Egyptě, a potříni budou všickni pomocníci jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 9, 'V ten den vyjdou poslové od tváři mé na lodech, aby přestrašili Mouřenínskou zemi ubezpečenou, i budou míti bolest přetěžkou, jakáž byla ve dni Egypta; nebo aj, přicházíť.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 10, 'Takto praví panovník Hospodin: Učiním zajisté konec množství Egyptskému skrze ruku Nabuchodonozora krále Babylonského.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 11, 'On i lid jeho s ním, nejukrutnější národové přivedeni budou, aby zkazili tu zemi; nebo vytrhnou meče své na Egypt, a naplní tu zemi zbitými.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 12, 'A obrátě řeky v sucho, prodám tu zemi v ruku nešlechetných, a tak v pustinu uvedu zemi, i což v ní jest, skrze ruku cizozemců. Já Hospodin mluvil jsem.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 13, 'Takto praví Panovník Hospodin: Zkazím i ukydané bohy, a konec učiním modlám v Nof, a knížete z země Egyptské nebude více, když pustím strach na zemi Egyptskou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 14, 'Nebo pohubím Patros, a zapálím oheň v Soan, a vykonám soudy v No.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 15, 'Vyleji prchlivost svou i na Sin, pevnost Egyptskou, a vypléním množství No.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 16, 'Když zapálím oheň v Egyptě, velikou bolest bude míti Sin, a No bude roztrháno, Nof pak nepřátely bude míti ve dne.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 17, 'Mládenci On a Bubastští mečem padnou, panny pak v zajetí půjdou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 18, 'A v Tachpanches zatmí se den, když tam polámi závory Egypta, a přítrž se stane v něm vyvýšenosti síly jeho. Mrákota jej přikryje, dcery pak jeho v zajetí půjdou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 19, 'A tak vykonám soudy při Egyptu, i zvědí, že já jsem Hospodin.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 20, 'Opět bylo jedenáctého léta, prvního měsíce, sedmého dne, že se stalo slovo Hospodinovo ke mně, řkoucí:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 21, 'Synu člověčí, rámě Faraona krále Egyptského zlámal jsem, a aj, nebudeť uvázáno, ani přičiněno lékařství, aniž přiložen bude šat pro obvázání jeho a posilnění jeho k držení meče.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 22, 'Protož takto praví panovník Hospodin: Aj, já jsem proti Faraonovi králi Egyptskému, a polámi ramena jeho, i sílu jeho, i budeť zlámané, a vyrazím meč z ruky jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 23, 'A rozptýlím Egyptské mezi národy, a rozženu je do zemí.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 24, 'Posilním zajisté ramen krále Babylonského, a dám meč svůj v ruku jeho, i polámi ramena Faraonova, tak že stonati bude před ním, jakž stonává smrtelně raněný.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 25, 'Posilním, pravím, ramen krále Babylonského, ramena pak Faraonova klesnou. I zvědí, že já jsem Hospodin, když dám meč svůj v ruku krále Babylonského, aby jej vztáhl na zemi Egyptskou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 26, 'A tak rozptýlím Egyptské mezi národy, a rozženu je do zemí, i zvědí, že já jsem Hospodin.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 1, 'Bylo pak jedenáctého léta, třetího měsíce, prvního dne téhož měsíce, že se stalo slovo Hospodinovo ke mně, řkoucí:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 2, 'Synu člověčí, rci Faraonovi králi Egyptskému i množství jeho: K komu jsi podoben v své velikosti?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 3, 'Aj, Assur byl jako cedr na Libánu, pěkných ratolestí, a větvovím zastěňující, a vysokého zrůstu, jehož vrchové byli mezi hustými větvemi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 4, 'Vody k zrůstu přivedly jej, propast jej vyvýšila, potoky jejími opuštěn byl vůkol kmen jeho, ješto jen praménky své vypouštěla na všecka dříví polní.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 5, 'Takž se vyvýšil zrůst jeho nade všecka dříví polní, a rozmnožili se výstřelkové jeho, a pro hojnost vod roztáhly se ratolesti jeho, kteréž vypustil.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 6, 'Na ratolestech jeho hnízdilo se všelijaké ptactvo nebeské, a pod větvemi jeho rodili se všelijací živočichové polní, a v stínu jeho sedali všickni národové velicí.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 7, 'I byl ušlechtilý pro svou velikost, a pro dlouhost větví svých; nebo kořen jeho byl při vodách mnohých.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 8, 'Cedrové v zahradě Boží nepřikryli ho, jedle nevrovnaly se ratolestem jeho, a stromové kaštanoví nebyli podobni větvem jeho. Žádné dřevo v zahradě Boží nebylo rovné jemu v kráse své.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 9, 'Ozdobil jsem jej množstvím větvoví jeho, tak že mu záviděla všecka dříví Eden, kteráž byla v zahradě Boží.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 10, 'Protož takto praví Panovník Hospodin: Proto že vysoce vyrostl, a vypustil vrch svůj mezi husté větvoví, a pozdvihlo se srdce jeho příčinou vysokosti jeho:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 11, 'Protož vydal jsem jej v ruku nejsilnějšího z národů, aby s ním přísně nakládal; pro bezbožnost jeho vyhnal jsem jej.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 12, 'A tak vyťali jej cizozemci, nejukrutnější národové, a nechali ho tu. Po horách i po všech údolích opadly větve jeho, a slomeny jsou ratolesti jeho na všecky prudké potoky té země. Pročež vystoupili z stínu jeho všickni národové země, a opustili jej.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 13, 'Na němž padlém bydlí všelijaké ptactvo nebeské, a na ratolestech jeho jsou všelijací živočichové polní,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 14, 'Proto aby se nevyvyšovalo v zrostu svém žádné dříví při vodách, a aby nevypouštělo vrchů svých mezi hustými větvemi, a nevypínalo se nad jiné vysokostí svou žádné dřevo zapojené vodami, proto že všickni ti oddáni jsou k smrti, dolů do země mezi syny lidské s těmi, kteříž sstupují do jámy.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 15, 'Takto praví Panovník Hospodin: Toho dne, v kterýž on sstoupil do hrobu, přivedl jsem k kvílení, a přikryl jsem příčinou jeho propast, a zadržel jsem potoky její, aby se zastavily vody mnohé, a učinil jsem, aby smutek nesl příčinou jeho Libán, a všecko dříví polní příčinou jeho aby umdlelo.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 16, 'Od hřmotu pádu jeho učinil jsem, že se třásli národové, když jsem jej svedl do hrobu s těmi, kteříž sstupují do jámy. Nad čímž se potěšila na zemi dole všecka dříví Eden, což výborného a dobrého jest na Libánu, vše což zapojeného jest vodou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 17, 'I ti s ním sstoupili do hrobu k těm, kteříž jsou zbiti mečem, i rámě jeho, i kteříž sedali v stínu jeho u prostřed národů.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 18, 'Kterému z stromů Eden podoben jsi tak v slávě a velikosti? Však svržen budeš s dřívím Eden dolů na zem, mezi neobřezanci s zbitými mečem lehneš. Toť jest Farao i všecko množství jeho, praví Panovník Hospodin.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 1, 'Opět bylo dvanáctého léta, dvanáctého měsíce, prvního dne téhož měsíce, že se stalo slovo Hospodinovo ke mně, řkoucí:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 2, 'Synu člověčí, vydej se v naříkání nad Faraonem králem Egyptským, a rci jemu: Lvu mladému mezi národy podoben jsi, a jsi jako velryb v moři, když procházeje se v potocích svých, kalíš vodu nohama svýma, a kormoutíš potoky její.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 3, 'Takto praví Panovník Hospodin: Rozestruť na tě síť svou skrze shromáždění národů mnohých, kteříž tě vytáhnou nevodem mým.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 4, 'I nechám tě na zemi, povrhu tě na svrchku pole, a učiním, že na tobě přebývati bude všelijaké ptactvo nebeské, a nasytím tebou živočichy vší země.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 5, 'A rozmeci maso tvé po horách, a naplním údolí vysokostí tvou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 6, 'A napojím zemi, v níž ploveš, krví tvou až do hor, tak že i potokové naplněni budou tebou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 7, 'V tom, když tě zhasím, zakryji nebesa, a zasmušilé učiním hvězdy jejich; slunce mrákotou zastru, a měsíc nebude svítiti světlem svým.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 8, 'Všecka světla jasná na nebesích zasmušilá učiním příčinou tvou, a uvedu tmu na zemi tvou, praví Panovník Hospodin.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 9, 'Nadto zkormoutím srdce národů mnohých, když způsobím, aby došla pověst o potření tvém mezi národy, do zemí, jichž jsi neznal.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 10, 'Učiním, pravím, že trnouti budou nad tebou národové mnozí, a králové jejich hroziti se příčinou tvou velice, když šermovati budu mečem svým před tváří jejich. Budou se zajisté lekati každé chvilky, každý sám za sebe v den pádu tvého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 11, 'Nebo takto praví Panovník Hospodin: Meč krále Babylonského přijde na tě.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 12, 'Meči udatných porazím množství tvé, nejukrutnějších ze všech národů; tiť zkazí pýchu Egypta, a zahlazeno bude všecko množství jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 13, 'Zahladím i všecka hovada jeho, kteráž jsou při vodách mnohých, tak že jich nezakalí noha člověčí více, aniž jich kaliti budou kopyta hovad.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 14, 'Tuť učiním, že se usadí vody jejich, a potokové jejich že jako olej půjdou, praví Panovník Hospodin,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 15, 'Když obrátím zemi Egyptskou v poušť přehroznou, v zemi prázdnou toho, což prvé v ní bylo, a když zbiji v ní všecky obyvatele. I zvědí, že já jsem Hospodin.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 16, 'Toť jest naříkání, jímž naříkati budou. Tak dcery národů naříkati budou, tak nad Egyptem i nade vším jeho množstvím naříkati budou, dí Panovník Hospodin.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 17, 'Potom bylo dvanáctého léta, patnáctého dne téhož měsíce, že se stalo slovo Hospodinovo ke mně, řkoucí:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 18, 'Synu člověčí, naříkej nad množstvím Egypta, a snes jej i dcery národů těch slavných do zpodních míst země k těm, kteříž sstupují do jámy.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 19, 'A rci: Nad kohož bys utěšenější byl? Sstupiž a lež s neobřezanci.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 20, 'Mezi zbitými mečem padnou, meči vydán jest, vlectež jej i všecko množství jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 21, 'Budouť k němu mluviti hrdiny s jeho pomocníky z prostřed hrobu, kdež neobřezanci mečem zbití sstoupivše, leží.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 22, 'Tam jest Assur i všecka zběř jeho, jehož hrobové jsou vůkol tohoto. Všickni ti byvše zbiti, padli od meče.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 23, 'Jehož hrobové jsou po stranách jámy, aby byla zběř jeho vůkol hrobu tohoto. Všickni ti byvše zbiti, padli od meče, kteříž pouštívali strach v zemi živých.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 24, 'Tam Elam i všecko množství jeho vůkol hrobu tohoto. Všickni ti neobřezanci byvše zbiti, padli od meče, a sstoupili do zpodních míst země, kteříž pouštívali strach svůj v zemi živých. Jižť nesou potupu svou s těmi, kteříž sstupují do jámy.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 25, 'Mezi zbitými postavili jemu lože, i všemu množství jeho, vůkol něhož jsou hrobové tohoto. Všickni ti neobřezanci zbiti mečem, nebo pouštín býval strach jejich v zemi živých. Jižť nesou potupu svou s těmi, jenž sstupují do jámy, mezi zbitými položeni jsouce.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 26, 'Tam Mešech, Tubal i všecko množství jeho, a vůkol něho hrobové tohoto. Všickni ti neobřezanci zbiti mečem, nebo pouštívali strach svůj v zemi živých.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 27, 'Ačťkoli ti ještě nelehli s hrdinami, kteříž padli z neobřezanců, kteříž sstoupili do hrobu s zbrojí svou vojenskou, a podložili meče své pod hlavy své, a však důjdeť nepravost jejich na kosti jejich; nebo strach hrdin byl v zemi živých.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 28, 'I ty mezi neobřezanci potřín budeš, a lehneš s zbitými mečem.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 29, 'Tam Edom, králové jeho, i všecka knížata jeho, kteříž položeni jsou i s svou mocí s zbitými mečem. I ti s neobřezanci lehnou a s těmi, kteříž sstupují do jámy.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 30, 'Tam knížata půlnoční strany všickni napořád, i všickni Sidonští, kteříž sstoupí k zbitým, s strachem svým, za svou moc stydíce se, a ležeti budou ti neobřezanci s zbitými mečem, a ponesou potupu svou s těmi, kteříž sstupují do jámy.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 31, 'Ty uhlédaje Farao, potěší se nade vším množstvím svým, Farao i všecko vojsko jeho, zbiti jsouce mečem, dí Panovník Hospodin.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 32, 'Nebo pustím strach svůj v zemi živých, a položen bude mezi neobřezanci s zbitými mečem Farao i všecko množství jeho, praví Panovník Hospodin.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 1, 'Opět stalo se slovo Hospodinovo ke mně, řkoucí:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 2, 'Synu člověčí, mluv k synům lidu svého a rci jim: Když uvedu na zemi některou meč, jestliže vezme lid té země muže jednoho od končin svých, a ustanoví jej sobě za strážného,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 3, 'A ten vida meč přicházející na tu zemi, troubil-li by na troubu a napomínal lidu,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 4, 'A slyše někdo zvuk trouby, však by se nedal napomenouti, a v tom přijda meč, shladil by jej: krev jeho na hlavu jeho bude.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 5, 'Nebo slyšel hlas trouby, však nedal se napomenouti; krev jeho na něm zůstane. Byť se byl napomenouti dal, duši svou byl by vysvobodil.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 6, 'Pakli strážný vida, an meč přichází, však by nezatroubil na troubu, a lid by nebyl napomenut, a přijda meč, zachvátil by někoho z nich: ten pro nepravost svou zachvácen bude, ale krve jeho z ruky strážného toho vyhledávati budu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 7, 'Tebe pak synu člověčí, tebe jsem strážným ustanovil nad domem Izraelským, abys slyše z úst mých slovo, napomínal jich ode mne.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 8, 'Když bych já řekl bezbožnému: Bezbožníče, smrtí umřeš, a nemluvil bys, vystříhaje bezbožného od cesty jeho: ten bezbožný pro nepravost svou umře, ale krve jeho z ruky tvé vyhledávati budu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 9, 'Pakli bys ty vystříhal bezbožného od cesty jeho, tak aby se od ní odvrátil, a však neodvrátil by se od cesty své: onť pro nepravost svou umře, ale ty duši svou vysvobodíš.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 10, 'Protož ty synu člověčí, rci domu Izraelskému: Takto mluvíte, říkajíce: Proto že přestoupení naše a hříchové naši jsou na nás, a my v nich svadneme, i jakž bychom živi byli?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 11, 'Rci jim: Živť jsem já, dí Panovník Hospodin, žeť nemám líbosti v smrti bezbožného, ale aby se odvrátil bezbožný od cesty své a živ byl. Odvraťtež se, odvraťte od cest svých zlých. I proč mříti máte, ó dome Izraelský?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 12, 'Ty tedy synu člověčí, rci synům lidu svého: Spravedlnost spravedlivého nevytrhne ho v den přestoupení jeho, aniž bezbožný v své bezbožnosti padne, v kterýž by se den odvrátil od bezbožnosti své; tolikéž spravedlivý nebude moci živ býti v ní, v kterýž by den zhřešil.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 13, 'Jestliže dím spravedlivému: Jistě živ budeš, a on doufaje v spravedlnost svou, činil by nepravost: žádná spravedlnost jeho nepřijde na pamět, ale pro tu nepravost svou, kterouž činil, umře.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 14, 'Zase řeknu-li bezbožnému: Smrtí umřeš, však odvrátí-li se od hříchu svého, a činiti bude soud a spravedlnost,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 15, 'Což v zástavě jest, navrátí-li bezbožný, což vydřel, nahradí-li, v ustanoveních života bude-li choditi, nečině nepravosti: jistě že bude živ, neumře.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 16, 'Žádní hříchové jeho, jimiž hřešil, nebudou mu zpomínáni; soud a spravedlnost činil, jistě že bude živ.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 17, 'A vždy říkají synové lidu tvého: Není pravá cesta Páně, ješto jejich cesta není pravá.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 18, 'Když by se odvrátil spravedlivý od spravedlnosti své, a činil by nepravost, umřeť pro ty věci.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 19, 'Ale když by se odvrátil bezbožný od bezbožnosti své, a činil by soud a spravedlnost, podlé těch věcí živ bude.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 20, 'A předce říkáte: Není pravá cesta Páně. Každého z vás podlé cest jeho souditi budu, ó dome Izraelský.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 21, 'Stalo se pak dvanáctého léta, desátého měsíce, pátého dne téhož měsíce od zajetí našeho, že přišel ke mně jeden, kterýž ušel z Jeruzaléma, řka: Dobyto jest město.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 22, 'Ruka pak Hospodinova byla při mně u večer před tím, než přišel ten, kterýž utekl, a otevřela ústa má, až i ke mně přišel ráno; otevřela, pravím, ústa má, abych nebyl němým déle.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 23, 'I stalo se slovo Hospodinovo ke mně, řkoucí:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 24, 'Synu člověčí, obyvatelé pustin těchto v zemi Izraelské mluví, řkouce: Jedinký byl Abraham, a dědičně držel zemi tuto, nás pak mnoho jest; námť dána jest země tato v dědictví.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 25, 'Protož rci jim: Takto praví Panovník Hospodin: Se krví jídáte, a očí svých pozdvihujete k ukydaným modlám svým, i krev vyléváte, a chtěli byste zemí touto dědičně vládnouti?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 26, 'Stojíte na meči svém, pášete ohavnost, a každý ženy bližního svého poškvrňujete, a chtěli byste zemí touto dědičně vládnouti?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 27, 'Takto mluv k nim: Takto praví Panovník Hospodin: Živť jsem já, že ti, kteříž jsou na pustinách, mečem padnou, a kdo na poli, toho zvěři dám k sežrání, kdo pak na hradích neb v jeskyních, morem zemrou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 28, 'I obrátím zemi tu v hroznou poušť a přestane vyvýšenost moci její, a zpustnou hory Izraelské, tak že nebude žádného, kdo by šel přes ně.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 29, 'I zvědí, že já jsem Hospodin, když obrátím zemi tu v hroznou poušť pro všecky ohavnosti jejich, kteréž páchali.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 30, 'Ty pak synu člověčí, slyš, synové lidu tvého často mluvívají o tobě, za stěnami i ve dveřích domů, a říkají jeden druhému a každý bratru svému, řka: Poďte medle a poslechněte, jaké slovo vyšlo od Hospodina.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 31, 'I scházejí se k tobě, tak jako se schází lid, a sedají před tebou lid můj, a poslouchají slov tvých, ale nečiní jich. A ačkoli je sobě ústy svými libují, však za mrzkým ziskem svým srdce jejich odchází.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 32, 'A aj, ty jsi jim jako zpěv libý pěkného zvuku a dobře vznějící. Slyšíť zajisté slova tvá, ale žádný jich nečiní.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 33, 'Než když to přijde, (aj, přicházíť), tedy zvědí, že prorok byl u prostřed nich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 1, 'I stalo se slovo Hospodinovo ke mně, řkoucí:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 2, 'Synu člověčí, prorokuj proti pastýřům Izraelským. Prorokuj a rci jim, těm pastýřům: Takto praví Panovník Hospodin: Běda pastýřům Izraelským, kteříž pasou sami sebe. Zdaliž pastýři nemají stáda pásti?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 3, 'Tuk jídáte, a vlnou se odíváte, což tučného, zabijíte, stáda však nepasete.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 4, 'Neduživých neposilujete, a nemocné nehojíte, a zlámané neuvazujete, a zaplašené zase nepřivodíte, a zahynulé nehledáte, ale přísně a tvrdě panujete nad nimi,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 5, 'Tak že rozptýleny jsou, nemajíce pastýře, a rozptýleny jsouce, jsou za pokrm všelijaké zvěři polní.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 6, 'Bloudí stádo mé po všech horách, a na každém pahrbku vysokém, nýbrž po vší země širokosti rozptýleny jsou ovce stáda mého, a není žádného, kdo by se po nich ptal, ani žádného, kdo by jich hledal.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 7, 'Protož ó pastýři, slyšte slovo Hospodinovo:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 8, 'Živť jsem já, praví Panovník Hospodin, zajisté proto že stádo mé bývá v loupež, a ovce stáda mého bývají k sežrání všelijaké zvěři polní, nemajíce žádného pastýře, aniž se ptají pastýři moji po stádu mém, ale pasou pastýři sami sebe, stáda pak mého nepasou:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 9, 'Protož vy pastýři, slyšte slovo Hospodinovo:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 10, 'Takto praví Panovník Hospodin: Aj, já jsem proti pastýřům těm, a budu vyhledávati stáda mého z ruky jejich, a zastavím jim pasení stáda, aby nepásli více ti pastýři samých sebe. Vytrhnu zajisté ovce své z úst jejich, aby jim nebyly za pokrm.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 11, 'Nebo takto praví Panovník Hospodin: Aj já, já ptáti se budu po ovcích svých a shledávati je.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 12, 'Jakož shledává pastýř stádo své tehdáž, když bývá u prostřed ovec svých rozptýlených: tak shledávati budu stádo své, a vytrhnu je ze všech míst, kamž v den oblaku a mrákoty rozptýleny byly.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 13, 'A vyvedu je z národů, a shromáždím je z zemí, a uvedu je do země jejich, a pásti je budu na horách Izraelských, při potocích i na všech místech k bydlení příhodných v zemi té.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 14, 'Na pastvě dobré pásti je budu, a na horách vysokých Izraelských bude ovčinec jejich. Tamť léhati budou v ovčinci veselém, a pastvou tučnou pásti se budou na horách Izraelských.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 15, 'Já pásti budu stádo své, a já způsobím to, že odpočívati budou, praví Panovník Hospodin.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 16, 'Zahynulé hledati budu, a zaplašenou zase přivedu, a polámanou uvíži, a nemocné posilím, tučnou pak a silnou zahladím; nebo je pásti budu v soudu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 17, 'Vy pak, stádo mé, slyšte: Takto praví Panovník Hospodin: Aj, já soudím mezi dobytčetem a dobytčetem, mezi skopci a kozly.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 18, 'Což jest vám málo pastvou dobrou se pásti, že ještě ostatek pastvy vaší pošlapáváte nohama svýma? a učištěnou vodu píti, že ostatek nohama svýma kalíte,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 19, 'Tak aby ovce mé tím, což vy nohama pošlapáte, se pásti, a kal noh vašich píti musily?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 20, 'Protož takto praví Panovník Hospodin k nim: Aj já, já souditi budu mezi dobytčetem tučným a mezi dobytčetem hubeným,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 21, 'Proto že boky i plecemi strkáte, a rohy svými trkáte všecky neduživé, tak že je vyháníte i ven.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 22, 'Protož vysvobodím stádo své, aby nebylo více v loupež, a souditi budu mezi dobytčetem a dobytčetem.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 23, 'A vzbudím nad nimi pastýře jednoho, kterýž je pásti bude, služebníka svého Davida. Tenť je pásti bude, a ten bude jejich pastýřem.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 24, 'Já pak Hospodin budu jejich Bohem, a služebník můj David knížetem u prostřed nich. Já Hospodin mluvil jsem.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 25, 'A učině s nimi smlouvu pokoje, způsobím, že přestane zvěř zlá na zemi; i budou bydleti na poušti bezpečně, a spáti i po lesích.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 26, 'K tomu obdařím je i okolí pahrbku svého požehnáním, a ssílati budu déšť časem svým; dešťové požehnání budou bývati;');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 27, 'Tak že vydá dřevo polní ovoce své a země vydá úrodu svou; i budou v zemi své bezpeční, a zvědí, že já jsem Hospodin, když polámi závory jha jejich, a vytrhnu je z ruky těch, jenž je v službu podrobují.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 28, 'I nebudou více loupeží národům, a zvěř zemská nebude jich žráti, ale bydliti budou bezpečně, aniž jich kdo přestraší.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 29, 'Nadto vzbudím jim výstřelek k slávě, a nebudou více mříti hladem v té zemi, aniž ponesou více potupy od pohanů.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 30, 'I zvědí, že já Hospodin Bůh jejich jsem s nimi, a oni lid můj, dům Izraelský, praví Panovník Hospodin.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 31, 'Vy pak ovce mé, ovce pastvy mé, jste vy lidé, a já Bůh váš, praví Panovník Hospodin.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 35, 1, 'Opět stalo se slovo Hospodinovo ke mně, řkoucí:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 35, 2, 'Synu člověčí, obrať tvář svou proti hoře Seir, a prorokuj proti ní.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 35, 3, 'A rci jí: Takto praví Panovník Hospodin: Aj, já jsem proti tobě, horo Seir, a vztáhnu ruku svou na tebe, a obrátím tě v hroznou poušť.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 35, 4, 'Města tvá v poušť obrátím, a ty budeš pustinou, i zvíš, že já jsem Hospodin,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 35, 5, 'Proto že máš nepřátelství věčné, a rozptyluješ syny Izraelské mečem v čas bídy jejich, v čas dokonání nepravosti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 35, 6, 'Protož živť jsem já, praví Panovník Hospodin, že k zabití připravím tě, a krev tě stihati bude. Poněvadž krve vylévání v nenávisti nemáš, také tě krev stihati bude.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 35, 7, 'Obrátím, pravím, horu Seir v hroznou poušť, a vypléním z ní jdoucího přes ni i vracujícího se.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 35, 8, 'A naplním hory její zbitými jejími; na pahrbcích tvých i v údolích tvých, i při všech potocích tvých zbití mečem padati budou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 35, 9, 'V pustiny věčné obrátím tě, tak že města tvá nebudou zase vzdělána, i zvíte, že já jsem Hospodin.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 35, 10, 'Proto že říkáš: Tito dva národové a tyto dvě země mé budou, a budeme dědičně vládnouti tou, v níž Hospodin přebýval,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 35, 11, 'Protož živť jsem já, praví Panovník Hospodin, žeť učiním podlé hněvu tvého a podlé závisti tvé, kterouž jsi prokázala z nenávisti své proti nim. I budu poznán od nich, když tě budu souditi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 35, 12, 'A zvíš, že já Hospodin slyšel jsem všecka hanění tvá, kteráž jsi mluvila o horách Izraelských, řkuci: Zpuštěnyť jsou, námť jsou dány k sežrání.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 35, 13, 'Nebo jste se honosili proti mně ústy svými, a množili proti mně slova svá, což jsem sám slyšel.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 35, 14, 'Takto praví Panovník Hospodin: Jakž se veselí všecka ta země, tak pustinu učiním z tebe.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 35, 15, 'Jakž se veselíš nad dědictvím domu Izraelského, proto že zpustl, tak učiním i tobě. Pustinou budeš, ó horo Seir, i všecka země Idumejská naskrze, i zvědíť, že já jsem Hospodin.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 1, 'Ty synu člověčí, prorokuj i o horách Izraelských a rci: Hory Izraelské, slyšte slovo Hospodinovo.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 2, 'Takto praví Panovník Hospodin: Proto že říká ten nepřítel o vás: Aj, to dobře, takéť i výsosti věčné v dědictví se nám dostanou,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 3, 'Protož prorokuj a rci: Takto praví Panovník Hospodin: Proto, proto že poplénili a sehltili vás vůkol, abyste byli za dědictví ostatku národů, a vydáni jste v pomluvu a v zlou pověst lidem,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 4, 'Protož hory Izraelské, slyšte slovo Panovníka Hospodina: Takto praví Panovník Hospodin horám i pahrbkům, potokům i údolím, pustinám hrozným i městům opuštěným, jenž jsou za loupež a posměch ostatku národů okolních,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 5, 'Protož takto dí Panovník Hospodin: jistě že v ohni horlivosti své mluviti budu proti ostatku těch národů, i proti vší zemi Idumejské, kteříž sobě osobili zemi mou za dědictví, veselíce se z celého srdce, a pléníce s chutí, aby sídlo vyhnaných z něho bylo v loupež.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 6, 'Protož prorokuj o zemi Izraelské, a mluv k horám a pahrbkům, potokům i k údolím: Takto praví Panovník Hospodin: Aj, já v horlivosti své a v prchlivosti své mluvím, proto že pohanění od národů snášíte.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 7, 'Protož takto praví Panovník Hospodin: já zdvihna ruku svou, přisahám, že ti národové, kteříž jsou vůkol vás, pohanění své nésti musejí.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 8, 'Vy pak hory Izraelské, ratolesti své vypouštěti, a ovoce své přinášeti budete lidu mému Izraelskému, když se přiblíží a přijdou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 9, 'Nebo aj, já jsem s vámi, a patřím na vás, abyste dělány a osívány byly.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 10, 'A rozmnožím v vás lidi, všecken dům Izraelský, jakýžkoli jest, i budou se osazovati města, a pustiny vzdělávati.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 11, 'Rozmnožím, pravím, v vás lidi i hovada, a budou se množiti a ploditi, i učiním, že bydliti budete jako za předešlých let vašich, čině vám dobře, více než v prvotinách vašich. A zvíte, že já jsem Hospodin.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 12, 'Nebo uvedu do vás lidi, lid svůj Izraelský, a budou tebou dědičně vládnouti; a budeš jim za dědictví, aniž kdy více siroby na ně uvedeš.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 13, 'Takto praví Panovník Hospodin: Proto že říkají vám, že jsi ty ta země, kteráž zžíráš lidi, a sirotky činíš z národů svých,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 14, 'Protož nebudeš více zžírati lidi, a národů svých více k sirobě přivoditi, praví panovník Hospodin.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 15, 'Aniž dopustím, aby více slýcháno bylo v tobě potupy národů, aniž útržky lidské snášeti budeš více, ani ku pádu přivoditi více národů svých, praví Panovník Hospodin.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 16, 'I stalo se slovo Hospodinovo ke mně, řkoucí:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 17, 'Synu člověčí, dům Izraelský, bydlíce v zemi své, poškvrnili jí cestou svou a skutky svými; podobná nečistotě ženy pro nečistotu oddělené byla cesta jejich před očima mýma.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 18, 'Pročež vylil jsem prchlivost svou na ně, proto že krev vylévali na zemi, a ukydanými bohy svými poškvrnili jí.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 19, 'I rozptýlil jsem je po národech, tak že rozplašeni jsou po zemích; podlé cesty jejich a podlé skutků jejich soudil jsem je.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 20, 'Nýbrž odšedše mezi národy, kamž přišli, poškvrnili jména svatosti mé, když říkáno o nich: Že jsou lid Hospodinův, a že z jeho země vyšli.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 21, 'Ale slitoval jsem se pro jméno svatosti své, kteréhož poškvrnili dům Izraelský mezi národy, kamž přišli.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 22, 'Protož rci domu Izraelskému: Takto praví Panovník Hospodin: Ne pro vás já to učiním, ó dome Izraelský, ale pro jméno svatosti své, kteréhož jste poškvrnili mezi národy, kamž jste přišli,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 23, 'Abych posvětil jména svého velikého, kteréž bylo poškvrněno mezi národy, kteréhož jste poškvrnili u prostřed nich, aby poznali národové, že já jsem Hospodin, praví Panovník Hospodin, když posvěcen budu v vás před očima jejich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 24, 'Nebo poberu vás z národů, a shromáždím vás ze všech zemí, a uvedu vás do země vaší.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 25, 'A pokropím vás vodou čistou, a čisti budete; ode všech poškvrn vašich, i ode všech ukydaných bohů vašich očistím vás.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 26, 'A dám vám srdce nové, a ducha nového dám do vnitřností vašich, a odejma srdce kamenné z těla vašeho, dám vám srdce masité.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 27, 'Ducha svého, pravím, dám do vnitřností vašich, a učiním, abyste v ustanoveních mých chodili, a soudů mých ostříhali a činili je.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 28, 'I budete bydliti v zemi, kterouž jsem byl dal otcům vašim, a budete lidem mým, a já budu vaším Bohem.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 29, 'Nebo vysvobodím vás ze všelijakých poškvrn vašich, a přivolám obilé, a rozmnožím je, a nedopustím na vás hladu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 30, 'Rozmnožím i ovoce stromů a úrody polní, tak že neponesete více potupy hladu mezi národy.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 31, 'I rozpomenete se na zlé cesty vaše a na skutky vaše nedobré, tak že sami se býti hodné ošklivosti uznáte pro nepravosti vaše a pro ohavnosti vaše.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 32, 'Ne pro vás já to učiním, praví Panovník Hospodin, známo vám buď. Zahanbětež se a zastyďte za cesty své, dome Izraelský.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 33, 'Takto praví Panovník Hospodin: V ten den, v kterémž vás očistím ode všech nepravostí vašich, osadím města, a vzdělány budou pustiny.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 34, 'A tak země pustá bude dělána, kteráž prvé byla pouští před očima každého tudy jdoucího.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 35, 'I řeknou: Země tato zpuštěná jest jako zahrada Eden, ano i města pustá, zkažená a zbořená jsou ohrazena a osazena.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 36, 'I zvědí národové, kteříž pozůstanou vůkol vás, že já Hospodin vystavěl jsem zbořeniny, a vysadil pustiny. Já Hospodin mluvil jsem i učiním.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 37, 'Takto praví Panovník Hospodin: Ještě toho hledati bude při mně dům Izraelský, abych je rozmnožil. Rozmnožím je lidmi jako stády.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 38, 'Jako stádo k obětem, jako stádo Jeruzalémské při slavnostech jeho, tak města pustá budou plná stád lidí, i zvědí, že já jsem Hospodin.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 1, 'Byla nade mnou ruka Hospodinova, a vyvedl mne Hospodin v duchu, a postavil mne u prostřed údolí, kteréž bylo plné kostí.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 2, 'I provedl mne skrze ně vůkol a vůkol, a aj, bylo jich velmi mnoho v tom údolí, a aj, byly velmi suché.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 3, 'I řekl mi: Synu člověčí, mohly-li by ožiti kosti tyto? I řekl jsem: Panovníče Hospodine, ty víš.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 4, 'V tom řekl mi: Prorokuj o těch kostech a rci jim: Kosti suché, slyšte slovo Hospodinovo.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 5, 'Toto praví Panovník Hospodin kostem těmto: Aj, já uvedu do vás ducha, abyste ožily.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 6, 'A dám na vás žily, a učiním, že zroste na vás maso, a otáhnu vás koží; dám, pravím, do vás ducha, abyste ožily, i zvíte, že já jsem Hospodin.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 7, 'Tedy prorokoval jsem tak, jakž mi rozkázáno bylo. I stal se zvuk, když jsem já prorokoval, a aj, hřmot, když se přibližovaly kosti jedna k druhé.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 8, 'I viděl jsem, a aj, žily a maso na nich se ukázalo, i koží potaženy byly po vrchu, ale ducha žádného nebylo v nich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 9, 'I řekl mi: Prorokuj k duchu, prorokuj, synu člověčí, a rci duchu: Takto praví Panovník Hospodin: Ode čtyř větrů přiď, duchu, a věj na tyto zmordované, ať oživou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 10, 'Tedy prorokoval jsem, jakž mi rozkázal. I všel do nich duch, a ožili, a postavili se na nohách svých, zástup velmi veliký.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 11, 'I řekl mi: Synu člověčí, kosti tyto jsou všecken dům Izraelský. Aj, říkají: Uschly kosti naše, a zhynula čáka naše, jižť jest po nás.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 12, 'Protož prorokuj a rci jim: Takto praví Panovník Hospodin: Aj, já otevru hroby vaše, a vyvedu vás z hrobů vašich, lide můj, a uvedu vás do země Izraelské.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 13, 'I zvíte, že já jsem Hospodin, když otevru hroby vaše, a vyvedu vás z hrobů vašich, lide můj.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 14, 'A dám Ducha svého do vás, abyste ožili, a osadím vás v zemi vaší, i zvíte, že já Hospodin mluvím i činím, dí Hospodin.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 15, 'Opět stalo se slovo Hospodinovo ke mně, řkoucí:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 16, 'Ty pak synu člověčí, vezmi sobě dřevo jedno, a napiš na něm: Judovi, a synům Izraelským, tovaryšům jeho. Zatím vezma dřevo druhé, napiš na něm: Jozefovi dřevo Efraimovo, a všechněm synům Izraelským, tovaryšům jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 17, 'I spojž je sobě jedno k druhému v jedno dřevo, aby byla jako jedno v ruce tvé.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 18, 'A když mluviti budou k tobě synové lidu tvého, řkouce: Což nám neoznámíš, co ty věci znamenají:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 19, 'Mluv k nim: Takto praví panovník Hospodin: Aj, já vezmu dřevo Jozefovo, kteréž jest v ruce Efraimově, a pokolení Izraelských, tovaryšů jeho, a přiložím je s ním k dřevu Judovu, a učiním je dřevem jedním, i budou jedno v ruce mé.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 20, 'A když budou ta dřeva, na kterýchž jsi psal, v ruce tvé před očima jejich,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 21, 'Tedy mluv k nim: Takto praví Panovník Hospodin: Aj, já vezmu syny Izraelské z prostřed národů těch, kamž odešli, a shromáždě je odevšad, uvedu je do země jejich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 22, 'A učiním je, aby byli národem jedním v té zemi na horách Izraelských, a král jeden bude nad nimi nade všemi králem. A nebudou více dva národové, aniž se již více děliti budou na dvoje království.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 23, 'Aniž se budou poškvrňovati více ukydanými bohy svými, a ohavnostmi svými, ani jakými přestoupeními svými, i vysvobodím je ze všech obydlí jejich, v nichž hřešili, a očistím je. I budou mým lidem, a já budu jejich Bohem.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 24, 'A služebník můj David bude králem nad nimi, a pastýře jednoho všickni míti budou, aby v soudech mých chodili, a ustanovení mých ostříhali, i činili je.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 25, 'I budou bydliti v té zemi, kterouž jsem byl dal služebníku svému Jákobovi, v níž bydlili otcové vaši. Budou, pravím, v ní bydliti oni i synové jejich, i synové synů jejich až na věky, a David služebník můj knížetem jejich bude na věky.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 26, 'Nadto učiním s nimi smlouvu pokoje; smlouva věčná bude s nimi. A rozsadím je, i rozmnožím je, a postavím svatyni svou u prostřed nich na věky.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 27, 'Bude i příbytek můj mezi nimi, a budu jejich Bohem, a oni budou lidem mým.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 28, 'I zvědí národové, že jsem já Hospodin, jenž posvěcuji Izraele, když bude svatyně má u prostřed nich na věky.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 1, 'Opět stalo se slovo Hospodinovo ke mně, řkoucí:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 2, 'Synu člověčí, obrať tvář svou proti Gogovi, země Magog, knížeti a hlavě v Mešech a Tubal, a prorokuj proti němu,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 3, 'A rci: Takto praví Panovník Hospodin: Aj, já budu proti tobě, Gogu, kníže a hlavo v Mešech a Tubal.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 4, 'A odvedu tě zpět, dada udice do čelistí tvých, když tě vyvedu i všecko vojsko tvé, koně i jezdce, všecky oblečené v celou zbroj, zástup veliký s pavézami a štíty, všecky ty, kteříž užívají meče:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 5, 'Perské, Mouřeníny i Putské s nimi, všecky ty s štíty a lebkami,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 6, 'Gomera i všecky houfy jeho, dům Togarmy od stran půlnočních, i všecky houfy jeho, národy mnohé s tebou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 7, 'Budiž hotov, a připrav se, ty i všecko shromáždění tvé, těch, kteříž se k tobě sebrali, a buď strážcím jejich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 8, 'Po mnohých dnech navštíven budeš, v potomních letech přitáhneš na lid vysvobozený od meče, a shromážděný z národů mnohých na hory Izraelské, kteréž byly pustinou ustavičně, když oni z národů jsouce vyvedeni, budou bydliti bezpečně všickni.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 9, 'V tom přitáhneš a přijdeš jako bouře, budeš jako oblak přikrývající zemi, ty i všickni houfové tvoji, i národové mnozí s tebou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 10, 'Takto praví Panovník Hospodin: I stane se v ten den, že vstoupí mnohé věci na srdce tvé, a budeš mysliti myšlení zlé.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 11, 'A díš: Potáhnu na zemi, v níž jsou vsi, přitáhnu na ty, jenž pokoje užívají, bydlíce bezpečně, na všecky, kteříž bydlejí beze všech zdí, a nemají žádné závory ani bran,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 12, 'Abych vzebral kořisti, a rozchvátal loupeže, obraceje ruku svou proti pouštěm již osazeným, a proti lidu zase shromážděnému z národů, zacházejícímu s dobytkem a jměním, bydlejícím u prostřed země.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 13, 'Sába a Dedan, a kupci mořští, i všecka lvíčata jeho řeknou tobě: K rozebrání-liž kořistí ty se béřeš? K rozchvátání-li loupeže shromáždil jsi množství své, abys bral stříbro a zlato, abys nabral dobytka i zboží, a nashromáždil loupeže veliké?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 14, 'Protož synu člověčí, prorokuj a rci Gogovi: Takto praví Panovník Hospodin: Zdaliž toho dne, když bude lid můj Izraelský bydliti bezpečně, nezvíš,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 15, 'Kdyžto přitáhnouce z místa svého od stran půlnočních, ty i národové mnozí s tebou, sedíce na koních všickni, shromáždění veliké a vojsko znamenité,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 16, 'Potáhneš na lid můj Izraelský jako oblak, abys přikryl tu zemi? V potomních dnech stane se, že tě přivedu na zemi svou, aby mne poznali národové, když posvěcen budu v tobě před očima jejich, ó Gogu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 17, 'Takto praví Panovník Hospodin: Zdaliž ty nejsi ten, o kterémž jsem mluvil za dnů starodávních skrze služebníky své, proroky Izraelské, kteříž prorokovali za těch dnů a let, že tě přivedu na ně?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 18, 'A však stane se v ten den, v den, v kterýž přitáhne Gog na zemi Izraelskou, praví Panovník Hospodin, že povstane prchlivost má s hněvem mým,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 19, 'A v rozhorlení svém, v ohni prchlivosti své mluviti budu. Jistě že v ten den bude pohnutí veliké v zemi Izraelské,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 20, 'Tak že se pohnou před tváří mou ryby mořské i ptactvo nebeské, a zvěř polní i všeliký zeměplaz plazící se po zemi, i všickni lidé, kteříž jsou na svrchku země. I rozválejí se hory, a padnou výsosti, i každá zed na zem upadne.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 21, 'Nebo zavolám proti němu po všech horách mých meče, praví Panovník Hospodin; meč každého proti bratru jeho bude.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 22, 'A vykonám při něm soud morem a krve prolitím a přívalem rozvodnilým, a kamením krupobití velikého, ohněm a sirou dštíti budu na něj i na houfy jeho, a na národy mnohé, kteříž jsou s ním.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 23, 'A tak zveleben, a posvěcen, a v známost uveden budu před očima národů mnohých, a zvědí, že já jsem Hospodin.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 1, 'Ty synu člověčí, prorokuj ještě proti Gogovi a rci: Takto praví Panovník Hospodin: Aj, já povstanu proti tobě, ó Gogu, kníže a hlavo v Mešech a Tubal.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 2, 'A odvedu tě zpět, navštívě tě šesti ranami, když tě vzbudím, abys přitáhl od stran půlnočních, a přivedu tě na hory Izraelské.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 3, 'Nebo vyrazím lučiště tvé z ruky tvé levé, a střely z ruky tvé pravé vyvrhu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 4, 'Na horách Izraelských padneš ty i všickni houfové tvoji i národové, kteříž budou s tebou; ptákům a všemu ptactvu křídla majícímu i zvěři polní dám tě k sežrání.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 5, 'Na svrchku pole padneš; neboť jsem já mluvil, praví Panovník Hospodin.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 6, 'Vypustím také oheň na Magoga i na ty, kteříž přebývají na ostrovích bezpečně, i zvědíť, že já jsem Hospodin.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 7, 'A jméno svatosti své uvedu v známost u prostřed lidu svého Izraelského. Nedopustím, pravím, více poškvrňovati jména svatosti své, i zvědíť národové, že já jsem Hospodin Svatý v Izraeli.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 8, 'Aj, přijdeť a stane se to, praví Panovník Hospodin, téhož dne, o kterémž jsem mluvil.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 9, 'Tehdy vyjdou obyvatelé měst Izraelských, a zapálíce, popálí zbroj a štíty i pavézy, lučiště i střely, dřevce i kopí, a budou je páliti ohněm sedm let.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 10, 'Aniž nositi budou dříví s pole, ani sekati v lesích, proto že zbrojí zaněcovati budou oheň, když zloupí ty, kteříž je loupívali, a mocí poberou těm, kteříž jim mocí brávali, praví Panovník Hospodin.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 11, 'I stane se v ten den, že dám Gogovi místo ku pohřbu tam v Izraeli, údolí, kudyž se jde k východní straně k moři, kteréžto zacpá ústa tudy jdoucích. I pohřbí tam Goga i všecko množství jeho, a nazovou je údolí množství Gogova.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 12, 'Nebo pochovávati je budou dům Izraelský za sem měsíců proto, aby vyčistili zemi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 13, 'A tak pohřbí je všecken lid té země, a bude jim to ku poctivosti v den, v kterýž oslaven budu, praví Panovník Hospodin.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 14, 'Oddělíť pak muže statečné, kteříž by procházeli tu zemi, proto aby pochovávali ty, kteříž by pozůstali na svrchku země, aby ji vyčistili. Po vyjití sedmi měsíců přehledávati začnou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 15, 'A ti procházejíce, choditi budou po zemi, a když uzří kosti člověčí, vzdělají při nich znamení pamětné, aby je pohřbili hrobaři v údolí množství Gogova.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 16, 'Nýbrž to množství jeho bude k slávě i městu, když vyčistí tu zemi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 17, 'Ty pak synu člověčí, takto praví Panovník Hospodin: Rci ke všelijakým ptákům křídla majícím i ke všelijaké zvěři polní: Shromažďte se a přiďte, zbeřte se odevšad k obětem mým, kterýchž já nabiji vám, obětí velikých na horách Izraelských, a budete jísti maso a píti krev.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 18, 'Maso silných reků jísti budete, a krev knížat zemských píti, skopců, beranů a kozlů, volků, všecko tučných Bázanských.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 19, 'A budete jísti tuk do sytosti, a píti krev do opití z obětí mých, kterýchž vám nabiji.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 20, 'A nasytíte se z stolu mého koňmi i jezdci, silnými reky i všemi muži válečnými, dí Panovník Hospodin.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 21, 'A tak zjevím slávu svou mezi národy, aby viděli všickni národové soud můj, kterýž jsem vykonal, i ruku mou, kterouž jsem doložil na ně.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 22, 'I zvíť dům Izraelský, že já jsem Hospodin Bůh jejich, od tohoto dne i potom.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 23, 'Zvědí také i národové, že pro svou nepravost zajat jest dům Izraelský, proto že se dopouštěli přestoupení proti mně; pročež jsem skryl tvář svou před nimi, a vydal jsem je v ruku protivníků jejich, aby padli mečem všickni napořád.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 24, 'Podlé nečistoty jejich a podlé zpronevěření se jejich učinil jsem jim, a skryl jsem tvář svou před nimi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 25, 'Z té příčiny takto praví Panovník Hospodin: Jižť zase přivedu zajaté Jákobovy, a smiluji se nade vším domem Izraelským a horliti budu příčinou jména svatosti své,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 26, 'Ač ponesou potupu svou a všecko přestoupení své, kteréhož se dopustili proti mně, když bydlili v zemi své bezpečně, aniž byl, kdo by je přestrašil.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 27, 'A však je zase přivedu z národů, a shromáždím je z zemí nepřátel jejich, a posvěcen budu v nich před očima národů mnohých.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 28, 'A tak poznají, že já jsem Hospodin Bůh jejich, když zaveda je do národů, shromáždím je do země jejich, a nepozůstavím tam žádného z nich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 29, 'Aniž skryji více tváři své před nimi, když vyleji Ducha svého na dům Izraelský, praví Panovník Hospodin.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 1, 'Dvadcátého pátého léta od zajetí našeho, na počátku roku, desátého dne měsíce, čtrnáctého léta po dobytí města, právě v tentýž den byla nade mnou ruka Hospodinova, a uvedl mne tam.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 2, 'U viděních Božích přivedl mne do země Izraelské, a postavil mne na hoře velmi vysoké, při níž bylo jako stavení města, ku poledni.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 3, 'I uvedl mne tam, a aj, muž, kterýž na pohledění byl jako měď, maje šňůru lněnou v ruce své, a prut k rozměřování, a ten stál v bráně.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 4, 'I mluvil ke mně ten muž: Synu člověčí, viz očima svýma, a ušima svýma slyš, a přilož srdce své ke všemu, což já ukáži tobě; nebo proto aťbych ukazoval, přiveden jsi sem. Ty pak oznámíš všecko domu Izraelskému, což vidíš.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 5, 'A aj, zed zevnitř při domu vůkol a vůkol, a v ruce muže toho prut míry, šesti loket, (loket o dlaň delší než obecní). Změřil šířku toho stavení jednoho prutu, a výšku jednoho prutu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 6, 'A všed do brány, kteráž byla naproti východu, šel na horu po stupních jejích, i změřil prah brány jednoho prutu zšíří, a prah druhý jednoho prutu zšíří.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 7, 'A pokojíky jednoho prutu zdélí, a jednoho prutu zšíří, mezi pokojíky pak pět loket, a prah brány podlé síňce brány vnitř prutu jednoho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 8, 'I změřil síňci brány vnitř na jeden prut.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 9, 'Změřil také síňci brány osmi loket, a veřeje její dvou loket, totiž síňce brány vnitř.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 10, 'I pokojíky brány východní, tři s jedné a tři s druhé strany. Jedné míry byly všecky tři, a míra jednostejná veřejí po obou stranách.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 11, 'Změřil též i širokost dveří té brány desíti loket, a dlouhost též brány třinácti loket,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 12, 'A přístřeší před pokojíky jednoho lokte, a na jeden loket přístřeší s této strany, pokojíky pak šesti loket s jedné, a šesti loket s druhé strany.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 13, 'A tak změřil bránu od střechy pokojíka do střechy druhého, širokost pětmecítma loket, dvéře naproti dveřím.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 14, 'A udělal veřeje šedesáti loket, a každé veřeje síně i brány vůkol a vůkol jedna míra.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 15, 'Od předku pak brány, kudyž se vchází do předku síňce brány vnitřní, bylo padesáte loket.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 16, 'A byla okna possoužená v pokojících i nad veřejemi jejich, do vnitřku brány vůkol a vůkol, takž i při klenutí, a na okních vůkol a vůkol do vnitřku, a na veřejích byly palmy.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 17, 'Potom mne uvedl do síně zevnitřní, a aj, komůrky a půda udělaná při síni vůkol a vůkol. Třidceti komůrek na té půdě bylo.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 18, 'Ta pak půda po straně těch bran, naproti dlouhosti bran, půda nižší byla.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 19, 'Změřil také šířku od předku brány dolejší až k předku síně vnitřní, zevnitř na sto loket k východu a půlnoci.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 20, 'Též bránu, kteráž byla na půlnoci při síni zevnitřní, změřil na dél i na šíř.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 21, '(Jejíž pokojíkové tři s jedné a tři s druhé strany, i veřeje její i síňce její byly podlé míry brány prvnější.) Padesáti loket dlouhost její, širokost pak pětmecítma loket.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 22, 'Okna také její i síňce její i palmy její byly podlé míry brány té, kteráž byla k východu, a vstupovalo se k ní po sedmi stupních, před nimiž síňce její byly.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 23, 'A byla ta brána u síně vnitřní naproti bráně půlnoční a východní; i odměřil od brány k bráně sto loket.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 24, 'Potom mne vedl ku poledni, a aj, brána ku poledni; i změřil veřeje její, i síňce její podlé těch měr,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 25, '(A okna v ní i síňce její vůkol a vůkol podobná oknům oněm), padesáti loket zdélí a pětmecítma loket zšíří.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 26, 'A k vstupování k ní stupňů sedm, a síňce její před nimi; též palmy při ní, jedna s jedné a druhá s druhé strany při veřejích jejích.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 27, 'Též bránu síně vnitřní ku poledni změřil od brány k bráně, na poledne, sto loket.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 28, 'I uvedl mne do síně vnitřní branou polední, a změřil tu bránu polední podlé týchž měr,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 29, 'I pokojíky její i veřeje její, i síňce její podlé týchž měr, i okna její i síňce její vůkol a vůkol, padesáti loket na dél, a na šíř pětmecítma loket.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 30, 'A síňce vůkol a vůkol zšíří pětmecítma loket, a zdélí padesáti loket.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 31, 'A síňce její jako síň zevnitřní, i palmy při veřejích jejích, též stupňů osm k vstupování k ní.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 32, 'Uvedl mne také do síně vnitřní k východu, i změřil bránu tu podlé týchž měr,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 33, 'Též pokojíky její i veřeje její, i síňce její, podlé týchž měr, i okna její i síňce její vůkol a vůkol, zdélí padesáti loket, zšíří pak pětmecítma loket.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 34, 'Též síňce její při síni zevnitřní, a palmy při veřejích s obou stran, a osm stupňů k vstupování k ní.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 35, 'Přivedl mne též k bráně půlnoční, a změřil ji podlé týchž měr,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 36, 'Pokojíky její, veřeje její i síňce její i okna její vůkol a vůkol, zdélí padesáti loket, a zšíří pětmecítma loket.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 37, 'I veřeje její při síni zevnitřní a palmy při veřejích s obou stran, též osm stupňů k vstupování k ní,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 38, 'I komůrky a dvéře její při veřejích bran, kdež obmývali oběti zápalné.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 39, 'A v síňci brány byli dva štokové s jedné strany, a dva štokové s druhé strany, aby na nich zabíjeli oběti zápalné, a za hřích i vinu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 40, 'A po boku, kudyž se tam vstupuje při dveřích brány půlnoční, dva štokové; tolikéž po boku druhém síňce též brány dva štokové.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 41, 'Čtyři štokové s jedné, a čtyři štokové s druhé strany po boku brány, osm štoků, na nichž zabíjeli.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 42, 'Čtyři pak štokové k zápalu byli z kamení tesaného, zdélí půldruhého lokte, a zšíří půldruhého lokte, a zvýší lokte jednoho, na nichž nechávali nádobí, kterýmž zabíjeli k zápalům a obětem.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 43, 'A kotliska ztlouští na jednu dlaň připravená v domě vůkol a vůkol, na štocích pak maso věcí obětovaných.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 44, 'Potom zevnitř, při bráně vnitřní, komůrky zpěváků v síni vnitřní, kteráž byla po boku brány půlnoční, a ty byly na poledne; jedna při boku brány východní byla na půlnoci.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 45, 'I mluvil ke mně: Tyto komůrky na poledne jsou kněží stráž držících nad domem;');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 46, 'Ty pak komůrky na půlnoci jsou kněží stráž držících nad oltářem, totiž synů Sádochových, kteříž přistupují z synů Léví k Hospodinu, aby sloužili jemu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 47, 'I změřil tu síň čtverhranou zdélí sto loket, a zšíří sto loket, i oltář před domem.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 48, 'I přivedl mne k síňci domu, a změřil veřeje té síňce, pěti loket s jedné a pěti loket s druhé strany, širokost pak brány byla tří loket s jedné a tří loket s druhé strany.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 49, 'Dlouhost síňce dvadcíti loket, širokost pak jedenácti loket i s stupni, po nichž se vstupovalo k ní; sloupové pak byli při veřejích, jeden s jedné, a druhý s druhé strany.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 1, 'Opět přivedl mne k chrámu, a změřil veřeje, šesti loket zšíří s jedné strany, a šesti loket zšíří s druhé strany, podlé širokosti stánku.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 2, 'A širokost dveří desíti loket, boky pak dveří pěti loket s jedné a pěti loket s druhé strany. Změřil také i dlouhost jejich čtyřidcíti loket, širokost pak dvadcíti loket.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 3, 'Přišel také do vnitřku, a změřil veřeje dveří dvou loket, a dvéře šesti loket, širokost pak dveří sedmi loket.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 4, 'Změřil také dlouhost svatyně dvadcíti loket, a širokost dvadcíti loket v chrámě, a řekl mi: Tato jest svatyně svatých.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 5, 'Změřil též zed domu šesti loket, a širokost pavlače čtyř loket, vůkol a vůkol okolo domu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 6, 'Ty pak pavlače, pavlač nad pavlačí, byly tři, a třidcíti noh zdélí, a scházely se při zdi domu vespolek, tak že se pavlače vůkol a vůkol držely, a nedržely se na zdi domu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 7, 'Nebo se rozšiřovala vůkol více a více, svrchu pro pavlače, kteréž byly okolo domu, od vrchu až dolů, vůkol a vůkol domu, poněvadž nejširší dům byl na hoře, a tak nejnižší porozšiřovala se k vrchu pro prostřední.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 8, 'Tak podobně spatřil jsem při domu pavlače, i nejvyšší vůkol a vůkol, jejichž půdy zouplna odměřeny byly šesti loket k výstupkům.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 9, 'Širokost zdi, kteráž byla při pavlačích zevnitř, pěti loket byla, i plac pavlačí, kteréž byly při domu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 10, 'Mezi nimiž a komůrkami byla širokost dvadcíti loket okolo domu vůkol a vůkol.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 11, 'A dvéře pavlačí byly k placu, dvéře jedny na půlnoci, a druhé dvéře na poledne, a širokost placu byla pěti loket vůkol a vůkol.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 12, 'Stavení pak, kteréž bylo před příhradkem v úhlu k západu, širokost byla sedmdesáti loket, a zed téhož stavení pěti loket zšíří vůkol a vůkol, a zdélí devadesáti loket.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 13, 'Potom změřil dům, zdélí sto loket, totiž příhradek i stavení, a zdi jeho zdélí sto loket.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 14, 'Též širokost předku domu i příhradku k východu sto loket.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 15, 'Změřil i dlouhost stavení před příhradkem, kteréž bylo za ním, též i paláce jeho s jedné i s druhé strany, a bylo sto loket; též chrám vnitř i síňce s síní,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 16, 'Prahy i okna possoužená, i paláce vůkol po třech stranách jejich, naproti prahu taflování dřevěné vůkol a vůkol, i od země až do oken, též i okna otaflovaná,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 17, 'Od svrchku dveří až do vnitřní i zevnitřní strany domu, i všecku zed vůkol a vůkol vnitř i zevnitř změřené.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 18, 'Kteréž taflování bylo uděláno s cherubíny a palmami, a to vše palma mezi cherubínem a cherubínem. A cherubín měl dvě tváře.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 19, 'Totiž tvář lidskou naproti palmě s jedné strany, a tvář lvíčete naproti palmě s druhé strany. Tak uděláno bylo ve všem domu vůkol a vůkol.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 20, 'Od země až do vrchu dveří cherubínové a palmy zdělány byly i na zdi chrámu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 21, 'Chrámu veřeje byly čtverhrané, a předek svatyně podobný jemu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 22, 'Oltář dřevěný tří loket zvýší, zdélí pak dvou loket s úhly svými, jehož dlouhost i pobočnice jeho dřevěné byly. I mluvil ke mně: Tento jest stůl, kterýž stojí před Hospodinem.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 23, 'A dvojnásobní dvéře byly u chrámu i u svatyně,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 24, 'A dvojnásobní dvéře ve vratech, totiž dvojnásobní dvéře obracející se, dvojnásobní ve vratech jedněch, a dvojnásobní dvéře v druhých.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 25, 'Byli pak uděláni na nich, na těch dveřích chrámu, cherubínové a palmy, tak jakž uděláni byli na stěnách, trámové také dřevění byli před síňcí vně.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 26, 'Též na oknech possoužených byly palmy s obou stran po bocích síňce, i na pavlačích domu toho i trámích.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 1, 'Potom mne vyvedl k síni zevnitřní, kteráž byla na půlnoci, a přivedl mne k těm komůrkám, kteréž byly před příhradkem, a kteréž byly naproti stavení na půlnoci,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 2, 'Jehož délka při dveřích půlnočních na pohledění byla sto loket, a šířka padesát loket.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 3, 'Naproti síni vnitřní, kteráž měla dvadceti loket, a naproti dlážení, kteréž bylo v síni zevnitřní, byl palác naproti paláci třmi řady.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 4, 'Před komůrkami pak byli pláckové desíti loket zšíří vnitř, cesta k nim lokte jednoho, a dvéře jejich na půlnoci.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 5, 'Komůrky pak nejvyšší byly užší, proto že palácové byli širší než ony, nežli nejzpodnější a prostřední stavení.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 6, 'Nebo o trojím ponebí bylo, ale nemělo žádných sloupů, jacíž byli sloupové síní; protož užší bylo nežli dolejší i než prostřední od země.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 7, 'Ohrady pak, kteráž byla vně naproti komůrkám k síni zevnitřní, před komůrkami, dlouhost byla padesáti loket.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 8, 'Nebo dlouhost komůrek, kteréž byly v síni zevnitřní, byla padesáti loket, před chrámem pak sto loket.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 9, 'Pod těmi pak komůrkami bylo vcházení od východu, skrze kteréž by se vcházelo do nich z síně té zevnitřní.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 10, 'Na šíř ohrady té síně k východu před příhradkem i před stavením byly komůrky.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 11, 'Cesta pak před nimi byla podobná cestě komůrek, kteréž byly na půlnoci. Jakáž byla dlouhost jejich, tak širokost jejich, a všecka vycházení jejich i dvéře jejich podobná oněmno.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 12, 'A dvéře těch komůrek, kteréž byly na poledne, podobné byly dveřím při začátku cesty, cesty před ohradou přímou k východu, kudyž se vchází do nich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 13, 'I řekl mi: Komůrky na půlnoci a komůrky na poledne, kteréž jsou před příhradkem, jsou komůrky svaté, kdežto jídají kněží, kteříž přistupují k Hospodinu, věci nejsvětější. Tam nechávati budou věcí nejsvětějších a obětí suchých, též za hřích a za vinu; nebo to místo svaté jest.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 14, 'Když tam vejdou kněží, tedy nevyjdou z svatyně do síně zevnitřní, leč tam nechají roucha svého, v němž přisluhovali; nebo svaté jest. A oblekou roucha jiná, když budou míti přistupovati k tomu, což se dotýče lidu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 15, 'A dokonav rozměřování domu vnitřního, i vedl mne k bráně, kteráž byla na východ, a změřil jej vůkol a vůkol.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 16, 'Změřil stranu východní prutem, pět set loket prutových tím prutem vůkol.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 17, 'Změřil stranu půlnoční tím prutem, pět set prutů vůkol.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 18, 'Změřil stranu polední tím prutem, pět set prutů.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 19, 'A obrátiv se k straně západní, naměřil tím prutem pět set prutů.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 20, 'Na čtyři strany změřil to, totiž zed vůkol a vůkol, zdélí pěti set, a zšíří pěti set, aby dělila svaté místo od obecného.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 1, 'Potom vedl mne k bráně, kterážto brána patřila k východu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 2, 'A aj, sláva Boha Izraelského přicházela od východu, jejíž zvuk byl jako zvuk vod mnohých, a země svítila se od slávy jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 3, 'A podobné bylo to vidění, kteréž jsem viděl, právě tomu vidění, kteréž jsem byl viděl, když jsem šel, abych kazil město, vidění, pravím, podobná vidění onomu, kteréž jsem viděl při řece Chebar. I padl jsem na tvář svou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 4, 'A když sláva Boží vcházela do domu, cestou brány patřící k východu,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 5, 'Tedy pojal mne Duch, a uvedl mne do síně vnitřní, a aj, dům plný byl slávy Hospodinovy.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 6, 'I slyšel jsem, an mluví ke mně z domu, a muž stál podlé mne.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 7, 'I řekl mi: Synu člověčí, místo stolice mé a místo šlepějí noh mých, kdežto bydliti budu u prostřed synů Izraelských na věky, a nebudou poškvrňovati více dům Izraelský jména svatosti mé, oni ani králové jejich smilstvím svým a mrtvými těly králů svých, ani výsostmi svými,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 8, 'Když kladli prah svůj podlé prahu mého, a veřeji svou podlé veřeje mé, a stěnu mezi mnou a mezi sebou, a tak poškvrňovali jména svatosti mé ohavnostmi svými, kteréž páchali, pročež jsem je sehltil v hněvě svém.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 9, 'Ale nyní vzdálí smilství svá i mrtvá těla králů svých, ode mne, a budu bydliti u prostřed nich na věky.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 10, 'Ty synu člověčí, oznam domu Izraelskému o tomto domu, a nechť se zahanbí pro nepravosti své, a ať změří všecko naskrze.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 11, 'A když se hanbiti budou za všecko, což páchali, způsob domu i formu jeho, i vycházení jeho, též vcházení jeho, i všecky způsoby jeho, všecka ustanovení jeho, všecky, pravím, způsoby jeho i všecky zákony jeho v známost jim uveď, a napiš před očima jejich, ať ostříhají všeho způsobu jeho i všech ustanovení jeho a činí je.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 12, 'Tento jest zákon toho domu: Na vrchu hory všecko obmezení jeho vůkol a vůkol, nejsvětějšíť jest. Aj, ten jest zákon toho domu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 13, 'Tyto pak jsou míry oltáře na též lokty, o dlaň delší: Předně zpodek lokte zvýší a lokte zšíří, obruba pak jeho při kraji jeho vůkol pídi jedné. Takový jest výstupek oltáře,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 14, 'Totiž od zpodku při zemi až do přepásaní dolejšího dva lokty, širokost pak lokte jednoho, a od přepásání menšího až do přepásaní většího čtyři lokty, širokost též na loket.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 15, 'Ale sám oltář ať jest čtyř loket, a z oltáře zhůru čtyři rohové.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 16, 'Oltář pak dvanácti loket zdélí a dvanácti zšíří, čtyřhranatý po čtyřech stranách svých.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 17, 'Přepásaní pak čtrnácti loket zdélí a čtrnácti zšíří po čtyřech stranách jeho, a obruba vůkol něho na půl lokte, a zpodek při něm na loket vůkol, a stupňové jeho naproti východu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 18, 'I řekl ke mně: Synu člověčí, takto praví Panovník Hospodin: Ta jsou ustanovení oltáře v den, v kterýž bude udělán, k obětování na něm zápalů a kropení na něj krví.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 19, 'Nebo dáš kněžím Levítským, kteříž jsou z semene Sádochova, kteříž přistupují ke mně, dí Panovník Hospodin, aby mi sloužili, volka mladého za hřích.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 20, 'A nabera krve jeho, dáš na čtyři rohy jeho, i na čtyři úhly toho přepásaní, i na obrubu vůkol, a tak jej očistíš i vyčistíš.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 21, 'A vezmeš toho volka za hřích, i spálí jej na místě uloženém v tom domě, vně před svatyní.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 22, 'V den pak druhý obětovati budeš kozla bez poškvrny za hřích, a očistí oltář, tak jakž vyčistili volkem.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 23, 'A když dokonáš očišťování, obětuj volka mladého bez vady, a skopce z stáda bez poškvrny.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 24, 'Kteréž když obětovati budeš před Hospodinem, uvrhou kněží na ně soli, a budou je obětovati v zápal Hospodinu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 25, 'Po sedm dní obětuj kozla za hřích, na každý den; též i volka mladého a skopce z stáda bez poškvrny obětovati budou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 26, 'Sedm dní očišťovati budou oltář, a vyčistí jej, a posvětí ruky své.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 27, 'A když vyplní ty dny, osmého dne i potom obětovati budou kněží na oltáři zápaly vaše, a pokojné oběti vaše, i přijmu vás laskavě, praví Panovník Hospodin.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 1, 'Tedy přivedl mne zase cestou k bráně svatyně zevnitřní, kteráž patří k východu, a ta byla zavřená.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 2, 'I řekl ke mně Hospodin: Brána tato zavřená bude, nebudeť otvírána, aniž kdo bude vcházeti skrze ni. Nebo Hospodin Bůh Izraelský všel skrze ni; protož budeť zavřená.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 3, 'Knížecí jest, kníže samo v ní sedati bude, aby jídalo chléb před Hospodinem. Cestou síně této brány vejde, a cestou její vyjde.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 4, 'I vedl mne cestou k bráně půlnoční, k přední straně domu, i viděl jsem, a aj, naplnila sláva Hospodinova dům Hospodinův. I padl jsem na tvář svou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 5, 'I řekl ke mně Hospodin: Synu člověčí, přilož srdce své, a viz očima svýma, i ušima svýma slyš, cožkoli já mluvím tobě o všech ustanoveních domu Hospodinova, i o všech zákonech jeho. Přilož, pravím, srdce své k vcházení do domu, i ke všemu vycházení z svatyně,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 6, 'A rci zpurnému domu Izraelskému: Takto praví Panovník Hospodin: Dosti mějte na všech ohavnostech svých, ó dome Izraelský,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 7, 'Že jste uvodili cizozemce neobřezaného srdce a neobřezaného těla, aby bývali v svatyni mé, a poškvrňovali i domu mého, když jste obětovali chléb můj, tuk i krev, ješto oni sic rušili smlouvu mou, mimo všecky ohavnosti vaše,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 8, 'A nedrželi jste stráže nad svatými věcmi mými, ale postavili jste strážné na stráži mé, v svatyni mé místo sebe.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 9, 'Takto praví Panovník Hospodin: Žádný cizozemec neobřezaného srdce a neobřezaného těla nevejde do svatyně mé, ze všech cizozemců, kteříž mezi syny Izraelskými jsou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 10, 'Nýbrž i Levítové, kteříž se vzdalovali ode mne, když bloudil Izrael, kteříž zbloudili ode mne za ukydanými bohy svými, ponesou nepravost svou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 11, 'Nebo budou v svatyni mé za služebníky, v povinnostech při branách domu, a za slouhy při domu. Oni budou zabíjeti oběti zápalné i oběti lidu, a oni stávati budou před nimi k sloužení jim,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 12, 'Proto že přisluhovali jim před ukydanými bohy jejich, a byli domu Izraelskému příčinou pádu v nepravost. Pročež přisáhl jsem jim, praví Panovník Hospodin, že ponesou nepravost svou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 13, 'Aniž přistoupí ke mně, aby mi kněžský úřad konali, ovšem aby přistupovati měli k kterým svatým věcem mým, neb k nejsvětějším, ale ponesou pohanění své i ohavnosti své, kteréž páchali.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 14, 'Protož postavím je za strážné u domu, ke vší službě jeho i ke všemu, což činěno býti má v něm.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 15, 'Kněží pak Levítští, synové Sádochovi, kteříž drželi stráž nad svatyní mou, když zbloudili synové Izraelští ode mne, ti budou přistupovati ke mně, aby mi přisluhovali, a státi před tváří mou, obětujíce mi tuk i krev, praví Panovník Hospodin.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 16, 'Ti přicházeti budou k svatyni mé, a ti přistupovati k stolu mému, aby mi sloužili a drželi stráž mou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 17, 'I stane se, když budou míti vcházeti do bran síně vnitřní, že roucha lněná oblekou, aniž na se vezmou vlněného, když by služby konati měli v branách síně vnitřní i u vnitřku.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 18, 'Klobouky lněné míti budou na hlavě své, a košilky lněné ať mají na bedrách svých, a nepřepasují se ničímž, což by pot vyvodilo.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 19, 'A majíce vyjíti do síně zevnitřní, do síně zevnitřní k lidu, svlekou roucha svá, v kterýchž služby konali, a nechají jich v komůrkách svatyně, a oblekou roucha jiná, a nebudou posvěcovati lidu rouchem svým.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 20, 'Aniž hlavy své holiti budou, ani vlasů nositi, ale slušně ostříhají vlasy své.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 21, 'Vína též nebude píti žádný z kněží, když budou míti vcházeti do síně vnitřní.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 22, 'Vdovy také aneb zahnané nebudou sobě pojímati za manželky, ale panny z semene domu Izraelského, aneb vdovu, kteráž by ovdověla po knězi, pojíti mohou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 23, 'A lid můj budou rozdílu učiti mezi svatým a nesvatým, též mezi nečistým a čistým ať je učí rozeznávati.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 24, 'V rozepři pak ať se postavují k souzení, a podlé soudu mého soudí ji. Zákonů mých i ustanovení mých při všech slavnostech mých ať ostříhají, a soboty mé světí.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 25, 'K mrtvému pak člověku nepůjde, aby se poškvrniti měl, leč při otci neb při mateři, též při synu a při dceři, při bratru a sestře, kteráž nebyla za mužem, může se poškvrniti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 26, 'Po očištění pak jeho (sedm dní odečtou jemu),');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 27, 'V ten den, v kterýž vejde do svatyně, do síně vnitřní, aby služby konal v svatyni, obětovati bude za hřích svůj, praví Panovník Hospodin.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 28, 'Dědictví pak jejich toto: Já jsem dědictví jejich, protož vládařství nedávejte jim v Izraeli; já jsem vládařství jejich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 29, 'Oběti suché a za hřích i vinu, to oni jísti budou, i všelijaká věc, oddána Bohu v Izraeli, jejich bude.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 30, 'I přední věci všech prvotin ze všeho, i každá obět zhůru pozdvižení všeliké věci, ze všech obětí zhůru pozdvižení vašich, kněžské bude. I prvotiny těsta vašeho dávati budete knězi, aby odpočinulo požehnání v domě tvém.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 31, 'Žádné mrchy a udáveného, ani z ptactva ani z hovad nebudou jídati kněží.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 1, 'Když pak ujmete zemi v dědictví, obětovati budete obět Hospodinu, díl svatý té země, zdélí pětmecítma tisíc loket, zšíří pak deset tisíc, a budeť svatý po všem pomezí svém vůkol.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 2, 'Z něhož bude místo svaté pět set zdélí, a pět set zšíří, čtyřhrané vůkol, a ať má padesáte loket prostranství vůkol.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 3, 'Z toho pak odměření odměříš dýlku pětmecítma tisíc loket, a šířku deset tisíc, aby na něm byla svatyně, i svatyně svatých.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 4, 'Díl ten země svatý jest. Kněží služebníků při svatyni býti má, těch, kteříž přistupují, aby přisluhovali Hospodinu, aby měli místo pro domy i místo svaté pro svatyni.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 5, 'Těch pak pětmecítma tisíc loket dýlka a deset tisíc šířka ať jest také Levítům, služebníkům domu, jim k držení dvadceti komůrek.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 6, 'Místo pak k vystavení na něm města oddělíte pět tisíc loket na šíř, a na dýl pětmecítma tisíc, naproti oběti místa svatého; bude pro všecken dům Izraelský.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 7, 'Knížeti pak s obou stran té oběti místa svatého, i položení města před oběti místa svatého, a před položením města od strany západní díl k západu, a po straně východní díl k východu, dlouhost pak naproti každému z těch dílů od pomezí západního ku pomezí východnímu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 8, 'To bude míti za vládařství v Izraeli, a nebudou více utiskati knížata má lidu mého, ale rozdadí zemi domu Izraelskému po pokoleních jejich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 9, 'Takto praví Panovník Hospodin: Dostitě již, ó knížata Izraelská, nátisk a zhoubu odložte, a soud a spravedlnost konejte, sejměte těžké roboty vaše s lidu mého, praví Panovník Hospodin.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 10, 'Váhu spravedlivou a efi spravedlivou i bát spravedlivý míti budete.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 11, 'Efi i bát v jednu míru ať jest, aby chomer bral v se deset bátů, efi pak desátý díl chomeru; podlé chomeru ať jest míra.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 12, 'Lot dvadceti peněz; dvadceti lotů, pětmecítma lotů, a patnácte lotů libra bude vám.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 13, 'Tato pak obět pozdvižení bude, kterouž obětovati budete: Šestý díl efi z chomeru pšenice, též šestý díl efi dáte z chomeru ječmene.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 14, 'Nařízení pak o oleji (bát jest míra oleje): Desátý díl bátu z míry chomeru, desíti bátů; nebo deset bátů jest chomer.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 15, 'A dobytče jedno ze dvou set bravů z dobrých pastvišť Izraelských, k oběti suché a zápalné a k obětem pokojným, k očištění vás, praví Panovník Hospodin.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 16, 'Všecken lid té země, i s knížetem Izraelským zavázán bude k té oběti zhůru pozdvižení.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 17, 'Nebo kníže povinen bude zápaly, a suché i mokré oběti, v svátky a na novměsíce, i v soboty, na všecky slavnosti domu Izraelského; on obětovati bude za hřích, i obět suchou i zápalnou, i oběti pokojné, aby se očištění dálo za dům Izraelský.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 18, 'Takto praví Panovník Hospodin: Prvního měsíce, prvního dne vezmeš volka mladého bez poškvrny, kterýmž očistíš svatyni.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 19, 'I nabéře kněz krve té oběti za hřích, a pomaže veřejí domu, a čtyř rohů toho přepásání na oltáři, i veřeje brány síně vnitřní.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 20, 'Takž také učiní sedmého dne téhož měsíce, za každého pobloudilého i za hloupého. Tak očistíte dům.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 21, 'Prvního měsíce, čtrnáctého dne, budete míti Fáze, svátek sedmi dnů, chlebové přesní jísti se budou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 22, 'A bude obětovati kníže v ten den za sebe i za všecken lid té země volka za hřích.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 23, 'A po sedm dní svátku obětovati bude zápal Hospodinu, sedm volků a sedm skopců bez poškvrny na den, po těch sedm dní, a za hřích kozla na den.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 24, 'A obět suchou, efi na volka a efi na skopce, připraví též oleje hin na efi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 25, 'Sedmého měsíce, patnáctého dne, v svátek tolikéž obětovati bude po sedm dní, jakož za hřích, tak zápal, tak obět suchou i olej.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 1, 'Takto praví Panovník Hospodin: Brána síně vnitřní, kteráž patří k východu, bude zavřená po šest dní všedních, v den pak sobotní otevřína bude; též v den novměsíce otvírána bude.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 2, 'I přijde kníže cestou síně brány zevnitř, a postaví se u veřeje té brány, a budou obětovati kněží obět zápalnou jeho, i oběti pokojné jeho, a pokloně se na prahu brány, potom vyjde. Brána pak nebude zavírána do večera,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 3, 'Aby se klaněl lid země té u dveří brány té ve dny sobotní, i na novměsíce před Hospodinem.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 4, 'Obět pak zápalná, kterouž obětovati má kníže Hospodinu v den sobotní, šest beránků bez vady a skopec bez poškvrny,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 5, 'A obět suchá, efi na skopce, i na beránky obět suchá, podlé toho, jakž naděleno, a oleje hin na efi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 6, 'Ke dni pak novměsíce ať jest volek mladý bez poškvrny, a šest beránků i skopec bez poškvrny.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 7, 'Též ať obětuje efi oběti suché při volku, a efi při skopci i při beráncích, seč bude moci býti, a oleje hin na efi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 8, 'Kníže pak vcházeje, cestou síňce též brány půjde, a cestou její odejde.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 9, 'Ale když vcházeti bude lid země té před Hospodina na slavnosti, ten kdož vejde cestou brány půlnoční, aby se klaněl, vyjde cestou brány polední; a ten kdož vejde cestou brány polední, vyjde cestou brány půlnoční. Nenavrátí se cestou té brány, kterouž všel, ale naproti ní vyjde.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 10, 'A když oni vcházeti budou, kníže mezi nimi vcházeti bude, a když odcházeti budou, odejde.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 11, 'Též na svátky i na slavnosti ať jest suchá obět, efi na volka a efi na skopce, a na beránky, což naděleno, a oleje hin na efi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 12, 'Bude-li pak obětovati kníže obět dobrovolnou, zápal aneb oběti pokojné dobrovolně Hospodinu, tedy ať jest mu otevřína brána, kteráž k východu patří, a ať obětuje zápal svůj aneb pokojné oběti své, tak jakž obětuje v den sobotní. Potom odejde, a brána bude zavřína po odchodu jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 13, 'K tomu beránka ročního bez poškvrny obětovati bude v zápal každý den Hospodinu; každého jitra beránka obětovati bude.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 14, 'Též suchou obět přičiní k němu, každého jitra šestý díl efi, též oleje třetinu hin k skropení mouky bělné, suchou obět Hospodinu, nařízením věčným ustavičně.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 15, 'A tak budou obětovati beránka i obět suchou, i olej každého jitra, zápal ustavičný.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 16, 'Taktoť praví Panovník Hospodin: Dá-li kníže dar někomu z synů svých, dědictvíť jeho jest, synů jeho buď, k vládařství jejich dědičnému.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 17, 'Jestliže pak dá dar z dědictví svého některému z služebníků svých, také bude jeho až do léta svobodného, kdyžto navrátí se knížeti tomu; však dědictví jeho budou míti synové jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 18, 'Aniž bude bráti kníže z dědictví lidu, z vládařství jejich je vytiskuje; z svého vládařství dědictví dá synům svým, aby nebyl rozptylován lid můj žádný z vládařství svého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 19, 'Potom vedl mne průchodem, kterýž jest po straně brány, k kněžím do komůrek svatých, kteréž patřily na půlnoci, a aj, tu bylo místo po dvou bocích k západu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 20, 'I řekl mi: Toto jest místo, kdež vaří kněží oběti za vinu a za hřích, kdež smaží oběti suché, aby nevynášeli do síně zevnitřní ku posvěcování lidu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 21, 'Vyvedl mne též do síně zevnitřní, a vodil mne po čtyřech koutech síně, a aj, síň byla v každém rohu té síně.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 22, 'Ve čtyřech úhlech té síně byly síně s komíny, čtyřidcíti loket zdélí a třidcíti zšíří; míra jednostejná těch čtyř síní nárožních.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 23, 'A v těch čtyřech byly kuchyňky vůkol, též ohniště zdělána v těch kuchyňkách vůkol.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 24, 'I řekl mi: Ta jsou místa těch, kteříž vaří, kdežto vaří služebníci domu oběti lidu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 1, 'Potom přivedl mne zase ke dveřím domu, a aj, vody vycházely od spodku prahu domu na východ; nebo přední strana domu k východu byla, a vody scházely pozpodu po pravé straně domu, po straně polední oltáře.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 2, 'Odtud mne vyvedl cestou brány půlnoční, a obvedl mne cestou zevnitřní k bráně zevnitřní, cestou, kteráž patří k východu, a aj, vody vyplývaly po pravé straně.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 3, 'Když pak vycházel ten muž k východu, v jehož rukou míra, i naměřil tisíc loket, a provedl mne skrze vodu, vodu do kůtků.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 4, 'Potom naměřiv tisíc, provedl mne skrze vodu, vodu do kolenou; ještě naměřiv tisíc, provedl mne vodou do pasu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 5, 'Opět když naměřil tisíc, byl potok, kteréhož jsem nemohl přebřísti; nebo vyzdvihly se vody, vody, přes něž by se musilo plynouti, potok, kterýž by nemohl přebředen býti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 6, 'Tedy řekl mi: Viděl-lis, synu člověčí? I vedl mne, a posadil mne na břeh toho potoka.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 7, 'Když jsem se pak obrátil, aj, na břehu toho potoka bylo dříví velmi veliké po obou stranách.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 8, 'I řekl mi: Vody tyto vycházejí od Galilee první, a sstupujíce po rovině, vejdou do moře, a když do moře vpadnou, opraví se vody.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 9, 'I stane se, že každý živočich, kterýž se plazí, všudy, kamžkoli přijdou potokové, ožive, a bude ryb velmi mnoho, proto že když přijdou tam tyto vody, očerstvějí, a živy budou všudy, kdežkoli dojde tento potok.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 10, 'Stane se i to, že se postaví podlé něho rybáři od Engadi až do studnice Eglaim; budou tu rozstírány síti. Podlé rozličnosti své bude ryb jejich, jako ryb moře velikého, velmi mnoho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 11, 'Bahna a louže jeho, kteréž se neopraví, soli oddány budou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 12, 'Při potoku pak poroste na břehu jeho po obou stranách všelijaké dříví ovoce nesoucí, jehož list neprší, aniž ovoce jeho přestává, v měsících svých nese prvotiny; nebo vody jeho z svatyně vycházejí, protož ovoce jeho jest ku pokrmu, a lístí jeho k lékařství.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 13, 'Takto praví Panovník Hospodin: Totoť jest obmezení, v němž sobě dědičně přivlastníte zemi po pokoleních Izraelských dvanácti; Jozefovi dva provazcové.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 14, 'Dědičně, pravím, jí vládnouti budete, jeden rovně jako druhý, o níž přisáhl jsem, že ji dám otcům vašim. I připadne vám země tato v dědictví.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 15, 'Toto jest tedy pomezí té země: K straně půlnoční od moře velikého cestou Chetlonu, kudyž se vchází do Sedad,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 16, 'Emat, Berota, Sibraim, kteříž jsou mezi pomezím Damašským, a mezi pomezím Emat, vsi prostřední, kteréž jsou při pomezí Chavrón.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 17, 'A tak bude pomezí od moře Azar Enon, pomezí Damašek, a půlnoční strana na půlnoci, a pomezí Emat. A to jest strana půlnoční.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 18, 'Strana pak východní mezi Chavrón a mezi Damaškem, a mezi Galád, a mezi zemí Izraelskou při Jordánu; od toho pomezí při moři východním měřiti budete. A toť jest strana východní.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 19, 'Strana pak polední na poledne, od Támar až k vodám sváru v Kádes, od potoka až k moři velikému. A to jest strana polední na poledne.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 20, 'Strana pak západní moře veliké, od pomezí až naproti, kudyž se vchází do Emat. Ta jest strana západní.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 21, 'A tak rozdělíte zemi tuto sobě po pokoleních Izraelských.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 22, 'I stane se, že když ji rozměříte, bude vám v dědictví i příchozím, kteříž by pohostinu byli mezi vámi, kteříž by zplodili syny mezi vámi; nebo budou vám jako tu zrodilí mezi syny Izraelskými, s vámiť ujmou dědictví mezi pokoleními Izraelskými.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 23, 'Protož nechť jest v tom pokolení příchozí, u něhož pohostinu jest. Tu dědictví dáte jemu, praví Panovník Hospodin.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 1, 'Tato jsou pak jména pokolení: V končinách na půlnoční stranu podlé cesty Chetlon, kudyž se vchází do Emat, Azar Enan, ku pomezí Damašskému na půlnoční stranu, podlé Emat, od východní strany až do západní, osadí se pokolení jedno, totiž Dan,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 2, 'A při pomezí Dan, od strany východní až k straně západní jedno, totiž Asser,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 3, 'A při pomezí Asser, od strany východní až do strany západní jedno, totiž Neftalím,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 4, 'A při pomezí Neftalím, od strany východní až do strany západní jedno, totiž Manasses,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 5, 'A při pomezí Manasses, od strany východní až do strany západní jedno, totiž Efraim,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 6, 'A při pomezí Efraim, od strany východní až k straně západní jedno, totiž Ruben,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 7, 'A při pomezí Ruben, od strany východní až k straně západní jedno, totiž Juda.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 8, 'A při pomezí Juda, od strany východní až k straně západní bude obět, kterouž obětovati budete, pětmecítma tisíc loket zšíří, zdélí pak zaroveň s jedním z jiných dílů, od strany východní až k straně západní, a bude svatyně u prostřed něho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 9, 'Ta obět, kterouž obětovati máte Hospodinu, bude zdélí pětmecítma tisíc loket, zšíří pak deset tisíc.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 10, 'Těmto pak se dostane ta obět svatá, totiž kněžím, na půlnoci pětmecítma tisíc loket, k západu pak zšíří desíti tisíc, a na východ zšíří desíti tisíc, na poledne též zdélí pětmecítma tisíc, a bude svatyně Hospodinova u prostřed něho,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 11, 'Kněžím, posvěcenému každému z synů Sádochových, kteříž drží stráž mou, kteříž nebloudili, když bloudili synové Izraelští, jako bloudili Levítové.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 12, 'I bude díl jejich obětovaný z oběti té země, věc nejsvětější při pomezí Levítů.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 13, 'Levítů pak díl bude naproti pomezí kněžskému, pětmecítma tisíc loket zdélí, a zšíří deset tisíc; každá dlouhost pětmecítma tisíc, a širokost deset tisíc.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 14, 'A nebudou ho uprodávati, ani směňovati, ani přenášeti prvotin země, proto že jest posvěcená Hospodinu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 15, 'Pět pak tisíc loket pozůstalých na šíř, proti těm pětmecítma tisícům, bude místo obecné, pro město k bydlení a k předměstí, i bude město u prostřed něho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 16, 'Tyto pak jsou míry jeho: Strana půlnoční na čtyři tisíce a pět set loket, též strana polední na čtyři tisíce a pět set, od strany též východní čtyři tisíce a pět set, takž strana západní na čtyři tisíce a pět set.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 17, 'Bude i předměstí při městě k půlnoci na dvě stě a padesáte loket, a ku poledni na dvě stě a padesáte, takž na východ na dvě stě a padesáte, též k západu na dvě stě a padesáte.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 18, 'Ostatek pak na dél, naproti oběti svaté, deset tisíc loket k východu, a deset tisíc k západu; a z toho, což bude naproti té oběti svaté, budou míti důchody ku pokrmu služebníci města.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 19, 'A ti služebníci města sloužiti budou Izraelovi ze všech pokolení Izraelských.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 20, 'Všecku tuto oběť, pětmecítma tisíc loket, podlé těch pětmecítma tisíc, čtverhranou obětovati budete v obět svatou k vládařství městu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 21, 'Což pak pozůstane, knížeti, s obou stran oběti svaté a vládařství města, před těmi pětmecítma tisíci loket oběti, až ku pomezí východnímu, a od západu proti týmž pětmecítma tisíc loket, podlé pomezí západního naproti těm dílům, knížeti bude. A to bude obět svatá, a svatyně domu u prostřed něho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 22, 'Od vládařství pak Levítů a od vládařství města, u prostřed toho, což jest knížecího, mezi pomezím Judovým a mezi pomezím Beniaminovým, knížecí bude.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 23, 'Ostatní pak pokolení, od strany východní až k straně západní, osadí se pokolení jedno, totiž Beniamin.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 24, 'A při pomezí Beniamin, od strany východní až k straně západní jedno, totiž Simeon,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 25, 'A při pomezí Simeon, od strany východní až k straně západní jedno, totiž Izachar,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 26, 'A při pomezí Izachar, od strany východní až k straně západní jedno, totiž Zabulon,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 27, 'A při pomezí Zabulon, od strany východní až k straně západní jedno, totiž Gád.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 28, 'A při pomezí Gád, k straně polední na poledne, tu bude pomezí od Támar až k vodám sváru v Kádes, ku potoku při moři velikém.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 29, 'Toť jest ta země, kterouž ujmete hned od potoka, po pokoleních Izraelských, a ti dílové jejich, praví Panovník Hospodin.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 30, 'Tato pak jsou vymezení města: Od strany půlnoční čtyř tisíc a pět set loket míra.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 31, 'Brány pak města podlé jmen pokolení Izraelských, brány tři na půlnoci, brána Rubenova jedna, brána Judova jedna, brána Léví jedna.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 32, 'A od strany východní čtyř tisíc a pět set, a brány tři, totiž brána Jozefova jedna, brána Beniaminova jedna, brána Danova jedna.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 33, 'Též od strany polední čtyř tisíc a pět set loket míra, a brány tři, brána Simeonova jedna, brána Izacharova jedna, brána Zabulonova jedna.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 34, 'Od strany západní čtyř tisíc a pět set, brány jejich tři, brána Gádova jedna, brána Asserova jedna, brána Neftalímova jedna.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 35, 'Okolek osmnácti tisíc loket, jméno pak města od dnešního dne bude: Hospodin tam přebývá.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 1, 'Léta třetího kralování Joakima krále Judského, přitáhl Nabuchodonozor král Babylonský k Jeruzalému, a oblehl jej.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 2, 'I vydal Pán v ruku jeho Joakima krále Judského, a něco nádobí domu Božího. Kterýž zavezl je do země Sinear, do domu boha svého, a nádobí to dal vnésti do domu pokladu boha svého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 3, 'Rozkázal také král Ašpenazovi, správci dvořanů svých, aby přivedl z synů Izraelských, z semene královského a z knížat,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 4, 'Mládence, na nichž by nebylo žádné poškvrny, a krásného oblíčeje, a vtipné ke vší moudrosti, a schopné k umění i k nabývání jeho, a v kterýchž by byla síla, aby stávali na palácu královském, a učili se liternímu umění a jazyku Kaldejskému.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 5, 'I nařídil jim král odměřený pokrm na každý den z stolu královského, i vína, kteréž on sám pil, a aby je tak choval za tři léta, a po dokonání jich aby stávali před králem.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 6, 'Byli pak mezi nimi z synů Juda: Daniel, Chananiáš, Mizael a Azariáš.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 7, 'I dal jim správce dvořanů jména. Nazval Daniele Baltazarem, Chananiáše pak Sidrachem, a Mizaele Mizachem, a Azariáše Abdenágem.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 8, 'Ale Daniel uložil v srdci svém, aby se nepoškvrňoval pokrmem z stolu královského, a vínem, kteréž král pil. Pročež hledal toho u správce nad dvořany, aby se nemusil poškvrňovati.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 9, 'I způsobil Bůh Danielovi milost a lásku u správce nad dvořany.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 10, 'A řekl správce nad dvořany Danielovi: Já se bojím pána svého krále, kterýž vyměřil pokrm váš a nápoj váš, tak že uzřel-li by, že tváře vaše opadlejší jsou, nežli mládenců těch, kteříž podobně jako i vy chování býti mají, způsobíte mi to u krále, že přijdu o hrdlo.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 11, 'I řekl Daniel služebníku, kteréhož ustanovil správce dvořanů nad Danielem, Chananiášem, Mizaelem a Azariášem:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 12, 'Zkus, prosím, služebníků svých za deset dní, a nechť se nám vaření dává, kteréž bychom jedli, a voda, kterouž bychom pili.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 13, 'A potom nechť se spatří před tebou tváře naše a tváře mládenců, kteříž jídají pokrm z stolu královského, a jakž uhlédáš, učiň s služebníky svými.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 14, 'I uposlechl jich v té věci, a zkusil jich za deset dní.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 15, 'Po skonání pak desíti dnů spatříno jest, že tváře jejich byly krásnější, a byli tlustší na těle než všickni mládenci, kteříž jídali pokrm z stolu královského.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 16, 'Protož služebník brával ten vyměřený pokrm jejich, a víno nápoje jejich, a dával jim vaření.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 17, 'Mládence pak ty čtyři obdařil Bůh povědomostí a rozumností ve všelikém literním umění a moudrostí; nadto Danielovi dal, aby rozuměl všelikému vidění a snům.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 18, 'A když se dokonali dnové, po kterýchž rozkázal král, aby je přivedli, přivedl je správce dvořanů před Nabuchodonozora.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 19, 'I mluvil s nimi král. Ale není nalezen mezi všemi těmi, jako Daniel, Chananiáš, Mizael a Azariáš. I stávali před králem.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 20, 'A ve všelikém slovu moudrosti a rozumnosti, na kteréž se jich doptával král, nalezl je desetkrát zběhlejší nade všecky mudrce a hvězdáře, kteříž byli ve všem království jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 21, 'I zůstával tu Daniel až do léta prvního Cýra krále.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 1, 'Léta pak druhého kralování Nabuchodonozora měl Nabuchodonozor sen, a děsil se duch jeho, až se tudy i ze sna protrhl.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 2, 'I rozkázal král svolati mudrce, a hvězdáře i kouzedlníky a Kaldejské, aby oznámili králi sen jeho. Kteřížto přišli, a postavili se před králem.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 3, 'Tedy řekl jim král: Měl jsem sen, a předěsil se duch můj, tak že nevím, jaký to byl sen.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 4, 'I mluvili Kaldejští králi Syrsky: Králi, na věky buď živ. Pověz sen služebníkům svým, a oznámímeť výklad.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 5, 'Odpověděl král a řekl Kaldejským: Ten sen mi již z paměti vyšel. Neoznámíte-li mi snu i výkladu jeho, na kusy rozsekáni budete, a domové vaši v záchody obráceni budou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 6, 'Pakli mi sen i výklad jeho oznámíte, daru, odplaty a slávy veliké důjdete ode mne. A protož sen i výklad jeho mi oznamte.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 7, 'Odpověděli po druhé a řekli: Nechať král sen poví služebníkům svým, a výklad jeho oznámíme.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 8, 'Odpověděl král a řekl: Jistotně rozumím tomu, že naschvál odtahujete, vidouce, že mi vyšel z paměti ten sen.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 9, 'Neoznámíte-li mi toho snu, jistý jest ten úsudek o vás. Nebo řeč lživou a chytrou smyslili jste sobě, abyste mluvili přede mnou, ažby se čas proměnil. A protož sen mi povězte, a zvím, budete-li mi moci i výklad jeho oznámiti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 10, 'Odpověděli Kaldejští králi a řekli: Není člověka na zemi, kterýž by tu věc králi oznámiti mohl. Nadto žádný král, kníže neb potentát takové věci se nedoptával na žádném mudrci a hvězdáři aneb Kaldeovi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 11, 'Nebo ta věc, na niž se král ptá, nesnadná jest, a není jiného, kdo by ji oznámiti mohl králi, kromě bohů, kteříž bydlení s lidmi nemají.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 12, 'Z té příčiny rozlítil se král a rozhněval velmi, a přikázal, aby zhubili všecky mudrce Babylonské.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 13, 'A když vyšel ortel, a mudrci mordováni byli, hledali i Daniele a tovaryšů jeho, aby zmordováni byli.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 14, 'Tedy Daniel odpověděl moudře a opatrně Ariochovi, hejtmanu nad žoldnéři královskými, kterýž vyšel, aby mordoval mudrce Babylonské.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 15, 'A odpovídaje, řekl Ariochovi, hejtmanu královskému: Proč ta výpověd náhle vyšla od krále? I oznámil tu věc Arioch Danielovi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 16, 'Pročež Daniel všed, prosil krále, aby jemu prodlel času k oznámení výkladu toho králi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 17, 'A odšed Daniel do domu svého, oznámil tu věc Chananiášovi, Mizaelovi a Azariášovi, tovaryšům svým,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 18, 'Aby se za milosrdenství modlili Bohu nebeskému příčinou té věci tajné, a nebyli zahubeni Daniel a tovaryši jeho s pozůstalými mudrci Babylonskými.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 19, 'I zjevena jest Danielovi u vidění nočním ta věc tajná. Pročež Daniel dobrořečil Bohu nebeskému.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 20, 'Mluvil pak Daniel a řekl: Buď jméno Boží požehnáno od věků až na věky, nebo moudrost a síla jeho jest.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 21, 'A on proměňuje časy i chvíle; ssazuje krále, i ustanovuje krále; dává moudrost moudrým a umění majícím rozum.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 22, 'On zjevuje věci hluboké a skryté; zná to, což jest v temnostech, a světlo s ním přebývá.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 23, 'Ó Bože otců mých, těť oslavuji a chválím, že jsi mne moudrostí a silou obdařil, ovšem nyní, že jsi mi oznámil to, čehož jsme žádali od tebe; nebo věc královu oznámil jsi nám.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 24, 'A protož Daniel všel k Ariochovi, kteréhož ustanovil král, aby zhubil mudrce Babylonské. A přišed, takto řekl jemu: Mudrců Babylonských nezahlazuj; uveď mne před krále a výklad ten oznámím.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 25, 'Tedy Arioch s chvátáním uvedl Daniele před krále, a takto řekl jemu: Našel jsem muže z zajatých synů Judských, kterýž výklad ten králi oznámí.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 26, 'Odpověděl král a řekl Danielovi, jehož jméno bylo Baltazar: Budeš-liž ty mi moci oznámiti sen, kterýž jsem viděl, i výklad jeho?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 27, 'Odpověděl Daniel králi a řekl: Té věci tajné, na niž se král doptává, nikoli nemohou mudrci, hvězdáři, věšťci a hadači králi oznámiti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 28, 'Ale však jest Bůh na nebi, kterýž zjevuje tajné věci, a on ukázal králi Nabuchodonozorovi, co se díti bude v potomních dnech. Sen tvůj, a což jsi ty viděl na ložci svém, toto jest:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 29, 'Tobě, ó králi, na mysl přicházelo na ložci tvém, co bude potom, a ten, kterýž zjevuje tajné věci, ukázalť to, což budoucího jest.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 30, 'Strany pak mne, ne skrze moudrost, kteráž by při mně byla nade všecky lidi, ta věc tajná mně zjevena jest, ale skrze modlitbu, aby ten výklad králi oznámen byl, a ty myšlení srdce svého abys zvěděl.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 31, 'Ty králi, viděl jsi, a aj, obraz nějaký veliký, (obraz ten byl znamenitý a blesk jeho náramný), stál naproti tobě, kterýž na pohledění byl hrozný.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 32, 'Toho obrazu hlava byla z zlata výborného, prsy jeho a ramena jeho z stříbra, a břicho jeho i bedra jeho z mědi,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 33, 'Hnátové jeho z železa, nohy jeho z částky z železa a z částky z hliny.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 34, 'Hleděls na to, až se utrhl kámen, kterýž nebýval v rukou, a udeřil obraz ten v nohy jeho železné a hliněné, a potřel je.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 35, 'A tak potříno jest spolu železo, hlina, měď, stříbro i zlato, a bylo to všecko jako plevy z placu letního, a zanesl to vítr, tak že místa jejich není nalezeno. Kámen pak ten, kterýž udeřil v obraz, učiněn jest horou velikou, a naplnil všecku zemi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 36, 'Toť jest ten sen. Výklad jeho také povíme králi:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 37, 'Ty králi, jsi král králů; nebo Bůh nebeský dal tobě království, moc a sílu i slávu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 38, 'A všeliké místo, na němž přebývají synové lidští, zvěř polní i ptactvo nebeské dal v ruku tvou, a pánem tě ustavil nade všemi těmi věcmi. Ty jsi ta hlava zlatá.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 39, 'Ale po tobě povstane království jiné, nižší než tvé, a jiné království třetí měděné, kteréž panovati bude po vší zemi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 40, 'Království pak čtvrté bude tvrdé jako železo. Nebo jakož železo drobí a zemdlévá všecko, tak, pravím, jako železo, kteréž potírá všecko, i ono potře a potříská všecko.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 41, 'Že jsi pak viděl nohy a prsty z částky z hliny hrnčířské a z částky z železa, království rozdílné znamená, v němž bude něco mocnosti železa, tak jakž jsi viděl železo smíšené s hlinou ničemnou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 42, 'Ale prstové noh z částky z železa a z částky z hliny znamenají království z částky mocné a z částky ku potření snadné.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 43, 'A že jsi viděl železo smíšené s hlinou ničemnou, ukazuje, že se přízniti budou vespolek lidé, a však nebude se přídržeti jeden druhého, tak jako železo nedrží se z hlinou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 44, 'Za dnů pak těch králů vzbudí Bůh nebeský království, kteréž na věky nebude zkaženo, a království to na žádného jiného nespadne, ale ono potře a konec učiní všechněm těm královstvím, samo pak státi bude na věky,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 45, 'Tak jakž jsi viděl, že se s hory utrhl kámen, kterýž nebýval v rukou, a potřel železo, měď, hlinu, stříbro a zlato. Bůh veliký oznámil králi, co býti má potom, a pravý jest sen ten i věrný výklad jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 46, 'Tedy král Nabuchodonozor padl na tvář svou, a poklonil se Danielovi, a rozkázal, aby oběti a vůně libé obětovali jemu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 47, 'A odpovídaje král Danielovi, řekl: V pravdě že Bůh váš jest Bůh bohů a Pán králů, kterýž zjevuje skryté věci, poněvadž jsi mohl vyjeviti tajnou věc tuto.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 48, 'Tedy král zvelebil Daniele, a dary veliké a mnohé dal jemu, a pánem ho učinil nade vší krajinou Babylonskou, a knížetem nad vývodami, a nade všemi mudrci Babylonskými.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 49, 'Daniel pak vyžádal na králi, aby představil krajině Babylonské Sidracha, Mizacha a Abdenágo. Ale Daniel býval v bráně královské.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 1, 'Potom Nabuchodonozor král udělav obraz zlatý, jehož výška byla šedesáti loket, šířka pak šesti loket, postavil jej na poli Dura v krajině Babylonské.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 2, 'I poslal Nabuchodonozor král, aby shromáždili knížata, vývody a vůdce, starší, správce nad poklady, v právích zběhlé, úředníky a všecky, kteříž panovali nad krajinami, aby přišli ku posvěcování obrazu, kterýž postavil Nabuchodonozor král.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 3, 'Tedy shromáždili se knížata, vývodové a vůdcové, starší, správcové nad poklady, v právích zběhlí, úředníci a všickni, kteříž panovali nad krajinami ku posvěcování obrazu toho, kterýž postavil Nabuchodonozor král, a stáli před obrazem, kterýž postavil Nabuchodonozor.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 4, 'Biřic pak volal ze vší síly: Vám se to praví lidem, národům a jazykům,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 5, 'Jakž uslyšíte zvuk trouby, píšťalky, citary, huslí, loutny, zpívání a všelijaké muziky, padněte a klanějte se obrazu zlatému, kterýž postavil Nabuchodonozor král.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 6, 'Kdož by pak nepadl a neklaněl se, té hodiny uvržen bude do prostřed peci ohnivé rozpálené.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 7, 'A protož hned, jakž uslyšeli všickni lidé zvuk trouby, píšťalky, citary, huslí, loutny a všelijaké muziky, padli všickni lidé, národové a jazykové, klanějíce se obrazu zlatému, kterýž postavil Nabuchodonozor král.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 8, 'A hned téhož času přistoupili muži Kaldejští, a s křikem žalovali na Židy,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 9, 'A mluvíce, řekli Nabuchodonozorovi králi: Králi, na věky buď živ.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 10, 'Ty králi, vynesls výpověd, aby každý člověk, kterýž by slyšel zvuk trouby, píšťalky, citary, huslí, loutny, zpívání a všelijaké muziky, padl a klaněl se obrazu zlatému,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 11, 'A kdož by nepadl a neklaněl se, aby uvržen byl do prostřed peci ohnivé rozpálené.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 12, 'Našli se pak někteří Židé, kteréž jsi představil krajině Babylonské, totiž Sidrach, Mizach a Abdenágo, kteřížto muži nedbali na tvé, ó králi, nařízení. Bohů tvých nectí, a obrazu zlatému, kterýž jsi postavil, se neklanějí.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 13, 'Tedy Nabuchodonozor v hněvě a v prchlivosti rozkázal přivésti Sidracha, Mizacha a Abdenágo. I přivedeni jsou muži ti před krále.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 14, 'I mluvil Nabuchodonozor a řekl jim: Zoumyslně-li, Sidrachu, Mizachu a Abdenágo, bohů mých nectíte, a obrazu zlatému, kterýž jsem postavil, se neklaníte?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 15, 'Protož nyní, jste-liž hotovi, abyste hned, jakž uslyšíte zvuk trouby, píšťalky, citary, huslí, loutny, zpívání a všelijaké muziky, padli a klaněli se obrazu tomu, kterýž jsem učinil? Pakli se klaněti nebudete, té hodiny uvrženi budete do prostřed peci ohnivé rozpálené, a který jest ten Bůh, ješto by vás vytrhl z ruky mé?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 16, 'Odpověděli Sidrach, Mizach a Abdenágo, a řekli králi: My se nestaráme o to, ó Nabuchodonozoře, co bychom měli odpovědíti tobě.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 17, 'Nebo aj, buďto že Bůh, jehož my ctíme, (kterýž mocen jest vytrhnouti nás z peci ohnivé rozpálené, a tak z ruky tvé, ó králi), vytrhne nás.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 18, 'Buď že nevytrhne, známo buď tobě, ó králi, žeť bohů tvých ctíti a obrazu zlatému, kterýž jsi postavil, klaněti se nebudeme.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 19, 'Tedy Nabuchodonozor naplněn jsa prchlivostí, tak že oblíčej tváři jeho se proměnil proti Sidrachovi, Mizachovi a Abdenágovi, a odpovídaje, rozkázal rozpáliti pec sedmkrát více, než obyčej měli ji rozpalovati.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 20, 'A mužům silným, kteříž byli mezi rytíři jeho, rozkázal, aby svížíce Sidracha, Mizacha a Abdenágo, uvrhli do peci ohnivé rozpálené.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 21, 'Tedy svázali muže ty v pláštích jejich, v košilkách jejich, i v kloboucích jejich a v oděvu jejich, a uvrhli je do prostřed peci ohnivé rozpálené.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 22, 'Že pak rozkaz královský náhlý byl, a pec velmi rozpálená, z té příčiny muže ty, kteříž uvrhli Sidracha, Mizacha a Abdenágo, zadusil plamen ohně.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 23, 'Ale ti tři muži, Sidrach, Mizach a Abdenágo, padli do prostřed peci ohnivé rozpálené svázaní.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 24, 'Tedy Nabuchodonozor král zděsil se, a vstal s chvátáním, a promluviv, řekl hejtmanům svým: Zdaliž jsme neuvrhli tří mužů do prostřed peci svázaných? Odpověděli a řekli králi: Pravda jest, králi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 25, 'On pak odpovídaje, řekl: Aj, vidím čtyři muže rozvázané, procházející se u prostřed ohně, a není žádného porušení při nich, a čtvrtý na pohledění podobný jest synu Božímu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 26, 'A přistoupiv Nabuchodonozor k čelisti peci ohnivé rozpálené, mluvil a řekl: Sidrachu, Mizachu a Abdenágo, služebníci Boha nejvyššího, vyjděte a poďte sem. I vyšli Sidrach, Mizach a Abdenágo z prostředku ohně.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 27, 'Shromáždivše se pak knížata, vývodové a vůdcové a hejtmané královští, hleděli na ty muže, an žádné moci neměl oheň při tělích jejich, ani vlas hlavy jejich nepřiškvrkl, ani plášťové jejich se nezměnili, aniž co ohněm páchli.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 28, 'I mluvil Nabuchodonozor a řekl: Požehnaný Bůh jejich, totiž Sidrachův, Mizachův a Abdenágův, kterýž poslal anděla svého, a vytrhl služebníky své, kteříž doufali v něho, až i rozkazu královského neuposlechli, ale těla svá vydali, aby nesloužili a neklaněli se žádnému bohu, kromě Bohu svému.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 29, 'A protož toto já přikazuji, aby každý ze všelikého lidu, národu a jazyku, kdož by koli co rouhavého řekl proti Bohu Sidrachovu, Mizachovu a Abdenágovu, na kusy rozsekán byl, a dům jeho v záchod obrácen, proto že není Boha jiného, kterýž by mohl vytrhovati, jako tento.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 30, 'Tedy zvelebil zase král Sidracha, Mizacha a Abdenága v krajině Babylonské.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 1, 'Nabuchodonozor král všechněm lidem, národům i jazykům, kteříž bydlí na vší zemi: Pokoj váš rozmnožen buď.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 2, 'Znamení a divy, kteréž učinil při mně Bůh nejvyšší, vidělo mi se za slušné, abych vypravoval.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 3, 'Znamení jeho jak veliká jsou, a divové jeho jak mocní jsou, království jeho království věčné, a panování jeho od národu do pronárodu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 4, 'Já Nabuchodonozor, užívaje pokoje v domě svém, a kveta na palácu svém,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 5, 'Měl jsem sen, kterýž mne zhrozil, a myšlení na ložci svém, a to, což jsem viděl, znepokojilo mne.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 6, 'A protož vyšla ode mne ta výpověd, aby uvedeni byli přede mne mudrci Babylonští, kteříž by mi výklad toho snu oznámili.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 7, 'Tedy předstoupili mudrci, hvězdáři, Kaldejští a hadači. I pověděl jsem jim sen, a však výkladu jeho nemohli mi oznámiti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 8, 'Až naposledy předstoupil přede mne Daniel, jehož jméno Baltazar, podlé jména boha mého, a v němž jest duch bohů svatých. Jemuž jsem oznámil sen:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 9, 'Baltazaře, kníže mudrců, já vím, že duch bohů svatých jest v tobě, a nic tajného není tobě nesnadného. Vidění snu mého, kterýž jsem měl, i výklad jeho oznam.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 10, 'U vidění pak, kteréž jsem viděl na ložci svém, viděl jsem, a aj, strom u prostřed země, jehož vysokost byla veliká.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 11, 'Veliký byl strom ten a mocný, a výsost jeho dosahovala až k nebi, a patrný byl až do končin vší země.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 12, 'Lístí jeho bylo pěkné, a ovoce jeho hojné, všechněm za pokrm, pod stínem pak jeho byla zvěř polní, a na ratolestech jeho bydlili ptáci nebeští, a z něho potravu měl všeliký živočich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 13, 'Viděl jsem také u viděních svých na ložci svém, a aj, hlásný a svatý s nebe sstoupiv,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 14, 'Volal ze vší síly, a tak pravil: Podetněte strom ten, a osekejte ratolesti jeho, a otlucte lístí jeho, a rozmecte ovoce jeho; nechať se vzdálí zvěř od něho, a ptáci z ratolestí jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 15, 'A však kmene kořenů jeho v zemi zanechejte, a v poutech železných a ocelivých na trávě polní, aby rosou nebeskou smáčín byl, a díl jeho s zvěří v bylině zemské.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 16, 'Srdce jeho od lidského ať jest rozdílné, a srdce zvířecí nechť jest dáno jemu, ažby sedm let vyplnilo se při něm.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 17, 'Usouzení hlásných a řeč žádosti svatých stane se, ažby k tomu přišlo, aby poznali lidé, že Nejvyšší panuje nad královstvím lidským, a že komuž chce, dává je, a toho, kterýž jest ponížený mezi lidmi, ustanovuje nad ním.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 18, 'Tento sen viděl jsem já Nabuchodonozor král, ty pak, Baltazaře, oznam výklad jeho. Nebo všickni mudrci v království mém nemohli mi výkladu oznámiti, ale ty můžeš, proto že duch bohů svatých jest v tobě.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 19, 'Tedy Daniel, jemuž jméno Baltazar, předěšený stál za jednu hodinu, a myšlení jeho strašila ho. A odpověděv král, řekl: Baltazaře, sen ani výklad jeho nechť nestraší tebe. Odpověděl Baltazar a řekl: Pane můj, sen tento přiď na ty, kteříž tě v nenávisti mají, a výklad jeho na tvé nepřátely.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 20, 'Strom ten, kterýž jsi viděl, veliký a mocný, jehož výsost dosahovala až k nebi, a kterýž patrný byl po vší zemi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 21, 'A lístí jeho pěkné, a ovoce jeho hojné, a z něhož všickni pokrm měli, pod nímž byla zvěř polní, a na ratolestech jeho bydlili ptáci nebeští,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 22, 'Ty jsi ten, ó králi, kterýž jsi rozšířil se a zmocnil, a velikost tvá vzrostla a vznesla se až k nebi, a panování tvé až do konce země.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 23, 'Že pak viděl král hlásného a svatého sstupujícího s nebe, kterýž řekl: Podetněte strom ten a zkazte jej, a však kmene kořenů jeho v zemi zanechejte, a v okovách železných a ocelivých ať jest na trávě polní, aby rosou nebeskou smáčín byl, a s zvěří polní díl jeho, ažby sedm let vyplnilo se při něm:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 24, 'Tenť jest výklad, ó králi, a ortel Nejvyššího, kterýž vyšel na pána mého krále.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 25, 'Nebo zaženou tě lidé od sebe, a s zvěří polní bude bydlení tvé, a bylinu jako volům tobě jísti dávati budou, a rosou nebeskou smáčín budeš, až se vyplní sedm let při tobě, dokudž bys nepoznal, že panuje Nejvyšší nad královstvím lidským, a že komuž chce, dává je.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 26, 'Že pak řekli, aby zanechán byl kmen kořenů toho stromu, království tvé tobě zůstane, jakž jen poznáš, že nebesa panují.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 27, 'Protož ó králi, přijmi radu mou, a hříchy své spravedlností přetrhuj, a nepravosti své milostivostí k ssouženým, zdaby prodloužen byl pokoj tvůj.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 28, 'Všecko to přišlo na krále Nabuchodonozora.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 29, 'Nebo po dokonání dvanácti měsíců, procházeje se po palácu královském v Babyloně,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 30, 'Mluvil král a řekl: Zdaliž toto není ten Babylon veliký, kterýž jsem já vystavěl mocí síly své, aby byl stolicí království k ozdobě slávy mé?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 31, 'Ještě ta řeč byla v ústech krále, a aj, hlas s nebe přišel: Toběť se praví, Nabuchodonozoře králi, že království odešlo od tebe,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 32, 'Nýbrž tě lidé i z sebe vyvrhou, a s zvěří polní bydliti budeš. Bylinu jako volům tobě jísti dávati budou, ažby sedm let vyplnilo se při tobě, dokudž bys nepoznal, že panuje Nejvyšší nad královstvím lidským, a že komuž chce, dává je.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 33, 'V touž hodinu řeč ta naplnila se při Nabuchodonozorovi. Nebo z spolku lidí vyvržen byl, a bylinu jako vůl jedl, a rosou nebeskou tělo jeho smáčíno bylo, až na něm vlasy zrostly jako peří orličí, a nehty jeho jako pazoury ptačí.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 34, 'Při skonání pak těch dnů já Nabuchodonozor pozdvihl jsem očí svých k nebi, a rozum můj ke mně se zase navrátil. I dobrořečil jsem Nejvyššímu, a živého na věky chválil jsem a oslavoval; nebo panování jeho jest panování věčné, a království jeho od národu do pronárodu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 35, 'A všickni obyvatelé země jako za nic počteni jsou, a podlé vůle své činí mezi vojskem nebeským i obyvateli země, aniž jest kdo, ješto by mu přes ruku dáti mohl, a říci jemu: Co to děláš?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 36, 'Téhož času rozum můj navrátil se ke mně, a k slávě království mého ozdoba má, i důstojnost má navrátila se ke mně; nadto i hejtmané moji a knížata má hledali mne, a zmocněn jsem v království svém, a velebnost větší jest mi přidána.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 37, 'Nyní tedy já Nabuchodonozor chválím, vyvyšuji a oslavuji krále nebeského, jehož všickni skutkové jsou pravda, a stezky jeho soud, a kterýž chodící v pýše může snižovati.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 1, 'Balsazar král učinil hody veliké tisíci knížatům svým, a před nimi víno pil.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 2, 'A když pil víno Balsazar, rozkázal přinésti nádobí zlaté a stříbrné, kteréž vynesl Nabuchodonozor otec jeho z chrámu Jeruzalémského, aby z něho pili král i knížata jeho, ženy jeho i ženiny jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 3, 'I přineseno jest nádobí zlaté, kteréž vynesli z chrámu domu Božího, kterýž byl v Jeruzalémě, a pili z něho král i knížata jeho, ženy jeho i ženiny jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 4, 'Pili víno, a chválili bohy zlaté a stříbrné, měděné, železné, dřevěné a kamenné.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 5, 'V touž hodinu vyšli prstové ruky lidské, a psali naproti svícnu na stěně paláce královského, a král hleděl na částky ruky, kteráž psala.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 6, 'Tedy jasnost královská změnila se, a myšlení jeho zkormoutila ho, a pasové bedr jeho rozpásali se, i kolena jeho jedno o druhé se tlouklo.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 7, 'A zkřikl král ze vší síly, aby přivedeni byli hvězdáři, Kaldejští a hadači. I mluvil král a řekl mudrcům Babylonským: Kdokoli přečte psání toto, a výklad jeho mi oznámí, šarlatem odín bude, a řetěz zlatý na hrdlo jeho, a třetím v království po mně bude.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 8, 'I předstoupili všickni mudrci královští, ale nemohli písma toho čísti, ani výkladu oznámiti králi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 9, 'Pročež král Balsazar velmi předěšen byl, a jasnost jeho změnila se na něm, ano i knížata jeho zkormouceni byli.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 10, 'Královna pak, příčinou té věci královské a knížat jeho, do domu těch hodů vešla, a promluvivši královna, řekla: Králi, na věky živ buď. Nechť tě neděsí myšlení tvá, a jasnost tvá nechť se nemění.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 11, 'Jest muž v království tvém, v němž jest duch bohů svatých, v kterémž za dnů otce tvého osvícení, rozumnost a moudrost, jako moudrost bohů, nalezena, jehož král Nabuchodonozor otec tvůj knížetem mudrců, hvězdářů, Kaldejských a hadačů ustanovil, otec tvůj, ó králi,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 12, 'Proto že duch znamenitý, i umění a rozumnost vykládání snů a oznámení pohádek, i rozvázání věcí nesnadných nalezeno při Danielovi, jemuž král jméno dal Baltazar. Nechať nyní zavolán jest Daniel, a oznámíť výklad ten.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 13, 'Tedy přiveden jest Daniel před krále. I mluvil král a řekl Danielovi: Ty-li jsi ten Daniel, jeden z synů zajatých Judských, kteréhož přivedl král otec můj z Judstva?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 14, 'Slyšel jsem zajisté o tobě, že duch bohů svatých jest v tobě, a osvícení i rozumnost a moudrost znamenitá nalezena jest v tobě.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 15, 'A nyní přivedeni jsou přede mne mudrci a hvězdáři, aby mi písmo toto přečtli, a výklad jeho oznámili, a však nemohli výkladu věci té oznámiti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 16, 'Já pak slyšel jsem o tobě, že můžeš to, což jest nesrozumitelného, vykládati, a což nesnadného, rozvázati. Protož nyní, budeš-li moci písmo to přečísti, a výklad jeho mně oznámiti, v šarlat oblečen budeš, a řetěz zlatý na hrdlo tvé, a třetím v království po mně budeš.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 17, 'Tedy odpověděl Daniel a řekl před králem: Darové tvoji nechť zůstávají tobě, a odplatu svou dej jinému, a však písmo přečtu králi, a výklad oznámím jemu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 18, 'Ty králi, slyš: Bůh nejvyšší královstvím a důstojností i slávou a okrasou obdařil Nabuchodonozora otce tvého,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 19, 'A pro důstojnost, kterouž ho obdařil, všickni lidé, národové a jazykové třásli a báli se před ním. Kohokoli chtěl, zabil, a kterékoli chtěl, bil, kteréž chtěl, povyšoval, a kteréž chtěl, ponižoval.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 20, 'Když se pak bylo pozdvihlo srdce jeho, a duch jeho zmocnil se v pýše, ssazen byl z stolice království svého, a slávu odjali od něho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 21, 'Ano i z spolku synů lidských vyvržen byl, a srdce jeho zvířecímu podobné učiněno bylo, a s divokými osly bylo bydlení jeho. Bylinu jako volům dávali jemu jísti, a rosou nebeskou tělo jeho smáčíno bylo, dokudž nepoznal, že panuje Bůh nejvyšší nad královstvím lidským, a že kohož chce, ustanovuje nad ním.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 22, 'Ty také, synu jeho Balsazaře, neponížil jsi srdce svého, ačkolis o tom o všem věděl.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 23, 'Ale pozdvihls se proti Pánu nebes; nebo nádobí domu jeho přinesli před tebe, a ty i knížata tvá, ženy tvé i ženiny tvé pili jste víno z něho. Nadto bohy stříbrné a zlaté, měděné, železné, dřevěné a kamenné, kteříž nevidí, ani slyší, aniž co vědí, chválil jsi, Boha pak, v jehož ruce jest dýchání tvé i všecky cesty tvé, neoslavoval jsi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 24, 'Protož nyní od něho poslána jest částka ruky této, a písmo to napsáno jest.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 25, 'A totoť jest písmo napsané: Mene, mene, tekel, ufarsin, totiž: Zčetl jsem, zčetl, zvážil a rozděluji.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 26, 'Tento pak jest výklad slov: Mene, zčetl Bůh království tvé, a k konci je přivedl.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 27, 'Tekel, zvážen jsi na váze, a nalezen jsi lehký.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 28, 'Peres, rozděleno jest království tvé, a dáno jest Médským a Perským.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 29, 'Tedy z rozkazu Balsazarova oblékli Daniele v šarlat, a řetěz zlatý dali na hrdlo jeho, a rozhlašovali o něm, že má býti pánem třetím v království.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 30, 'V touž noc zabit jest Balsazar král Kaldejský.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 31, 'Darius pak Médský ujal království v letech okolo šedesáti a dvou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 1, 'Líbilo se pak Dariovi, aby ustanovil nad královstvím úředníků sto a dvadceti, kteříž by byli po všem království.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 2, 'Nad těmi pak hejtmany tři, z nichžto Daniel přední byl, kterýmž by úředníci onino vydávali počet, aby se králi škoda nedála.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 3, 'Tedy Daniel převyšoval ty hejtmany a úředníky, proto že duch znamenitější v něm byl. Pročež král myslil ustanoviti jej nade vším královstvím.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 4, 'Tedy hejtmané a úředníci hledali příčiny proti Danielovi s strany království, a však žádné příčiny ani vady nemohli najíti; nebo věrný byl, aniž jaký omyl neb vada nalézala se při něm.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 5, 'Protož muži ti řekli: Nenajdeme proti Danielovi tomuto žádné příčiny, jediné leč bychom našli něco proti němu s strany zákona Boha jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 6, 'Tedy hejtmané a úředníci ti shromáždivše se k králi, takto mluvili k němu: Darie králi, na věky buď živ.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 7, 'Uradili se všickni hejtmané království, vývodové, úředníci, správcové a vůdcové, abys ustanovil nařízení královské, a utvrdil zápověd: Kdož by koli vložil žádost na kteréhokoli boha neb člověka do třidcíti dnů, kromě na tebe, králi, aby uvržen byl do jámy lvové.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 8, 'Nyní tedy, ó králi, potvrď zápovědi této, a vydej mandát, kterýž by nemohl změněn býti podlé práva Médského a Perského, kteréž jest neproměnitelné.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 9, 'Pročež král Darius vydal mandát a zápověd.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 10, 'Daniel pak, když se dověděl, že jest vydán mandát, všel do domu svého, kdež otevřená byla okna v pokoji jeho proti Jeruzalému, a třikrát za den klekal na kolena svá, a modlíval se a vyznával se Bohu svému, tak jakož prvé to činíval.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 11, 'Tedy muži ti shromáždivše se a nalezše Daniele, an se modlí a pokorně prosí Boha svého,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 12, 'Tedy přistoupili a mluvili k králi o zápovědi královské: Zdaliž jsi nevydal mandátu, aby každý člověk, kdož by koli něčeho žádal od kterého boha neb člověka až do třidcíti dnů, kromě od tebe, králi, uvržen byl do jámy lvové? Odpověděv král, řekl: Pravéť jest slovo to, podlé práva Médského a Perského, kteréž jest neproměnitelné.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 13, 'Tedy odpovídajíce, řekli králi: Daniel ten, kterýž jest z zajatých synů Judských, nechtěl dbáti na tvé, ó králi, nařízení, ani na mandát tvůj, kterýž jsi vydal, ale třikrát za den modlívá se modlitbou svou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 14, 'Tedy král, jakž uslyšel tu řeč, velmi se zarmoutil nad tím, a uložil král v mysli své vysvoboditi Daniele, a až do západu slunce usiloval ho vytrhnouti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 15, 'Ale muži ti shromáždivše se k králi, mluvili jemu: Věz, králi, že jest takové právo u Médských a Perských, aby každá výpověd a nařízení, kteréž by král ustanovil, neproměnitelné bylo.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 16, 'I řekl král, aby přivedli Daniele, a uvrhli jej do jámy lvové. Mluvil pak král a řekl Danielovi: Bůh tvůj, kterémuž sloužíš ustavičně, on vysvobodí tebe.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 17, 'A přinesen jest kámen jeden, a položen na díru té jámy, a zapečetil ji král prstenem svým a prsteny knížat svých, aby nebyl změněn ortel při Danielovi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 18, 'I odšel král na palác svůj, a šel ležeti, nic nejeda, a ničímž se obveseliti nedal, tak že i sen jeho vzdálen byl od něho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 19, 'Tedy král hned ráno vstav na úsvitě, s chvátáním šel k jámě lvové.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 20, 'A jakž se přiblížil k jámě, hlasem žalostným zavolal na Daniele, a promluviv král, řekl Danielovi: Danieli, služebníče Boha živého, Bůh tvůj, kterémuž ty sloužíš ustavičně, mohl-liž tě vysvoboditi od lvů?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 21, 'Tedy Daniel mluvil s králem, řka: Králi, na věky buď živ.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 22, 'Bůh můj poslal anděla svého, kterýž zavřel ústa lvů, aby mi neuškodili; nebo před ním nevina nalezena jest při mně, nýbrž ani proti tobě, králi, nic zlého jsem neučinil.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 23, 'Tedy král velmi se z toho zradoval, a rozkázal Daniele vytáhnouti z jámy. I vytažen byl Daniel z jámy, a žádného úrazu není nalezeno na něm; nebo věřil v Boha svého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 24, 'I rozkázal král, aby přivedeni byli muži ti, kteříž osočili Daniele, a uvrženi jsou do jámy lvové, oni i synové jejich i ženy jejich, a prvé než dopadli dna té jámy, zmocnili se jich lvové, a všecky kosti jejich zetřeli.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 25, 'Tedy Darius král napsal všechněm lidem, národům a jazykům, kteříž bydlili po vší zemi: Pokoj váš rozmnožen buď.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 26, 'Ode mne vyšlo nařízení toto, aby na všem panství království mého třásli a báli se před Bohem Danielovým; nebo on jest Bůh živý a zůstávající na věky, a království jeho nebude zrušeno, ani panování jeho až do konce.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 27, 'Vysvobozuje a vytrhuje, a činí znamení a divy na nebi i na zemi, kterýž vysvobodil Daniele z moci lvů.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 28, 'Danielovi pak šťastně se vedlo v království Dariovu, a v království Cýra Perského.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 1, 'Léta prvního Balsazara krále Babylonského Daniel měl sen a vidění svá na ložci svém, i napsal ten sen krátkými slovy.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 2, 'Mluvil Daniel a řekl? Viděl jsem u vidění svém v noci, a aj, čtyři větrové nebeští bojovali na moři velikém.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 3, 'A čtyři šelmy veliké vystupovaly z moře, jedna od druhé rozdílná.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 4, 'První podobná lvu, a křídla orličí měla. Hleděl jsem, až vytrhána byla křídla její, jimiž se vznášela od země, tak že na nohách jako člověk státi musila, a srdce lidské dáno jest jí.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 5, 'A aj, jiná šelma druhá podobná nedvědu, kteráž panství jedno vyzdvihla, a tři žebra v ústech jejích, mezi zuby jejími, a tak mluveno bylo k ní: Vstaň, nažer se hojně masa.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 6, 'Potom jsem viděl, a aj, jiná podobná pardovi, kteráž měla čtyři křídla ptačí na hřbetě svém, a čtyřhlavá byla šelma ta, jíž moc dána byla.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 7, 'Potom viděl jsem u viděních nočních, a aj, šelma čtvrtá strašlivá a hrozná a velmi silná, mající zuby železné veliké, kteráž zžírala a potírala, ostatek pak nohama svýma pošlapávala; a ta byla rozdílná ode všech šelm, kteréž byly před ní, a měla rohů deset.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 8, 'Pilně jsem šetřil těch rohů, a hle, roh poslední malý vyrostal mezi nimi, a tři z těch rohů prvních vyvráceni jsou před ním; a aj, oči podobné očím lidským v rohu tom, a ústa mluvící pyšně.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 9, 'Hleděl jsem, až trůnové ti svrženi byli, a Starý dnů posadil se, jehož roucho jako sníh bílé, a vlasové hlavy jeho jako vlna čistá, trůn jako jiskry ohně, kola jeho jako oheň hořící.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 10, 'Potok ohnivý tekl a vycházel od něho, tisícové tisíců sloužili jemu, a desetkrát tisíckrát sto tisíců stálo před ním; soud zasedl, a knihy otevříny byly.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 11, 'Patřil jsem tehdáž, hned jakž se začal zvuk té řeči pyšné, kterouž roh mluvil; patřil jsem, dokudž ta šelma nebyla zabita, a vyhlazeno tělo její, a dáno k spálení ohni.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 12, 'A i ostatkům šelm odjali panství; nebo dlouhost života jim odměřena byla až do času, a to uloženého času.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 13, 'Viděl jsem u vidění nočním, a aj, s oblaky nebeskými podobný Synu člověka přicházel; potom až k Starému dnů přišel, a před něj postaven byl.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 14, 'I dáno jest jemu panství a sláva i království, aby všickni lidé, národové a jazykové sloužili jemu; jehož panství jest panství věčné, kteréž nepomíjí, a království jeho, kteréž se neruší.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 15, 'I zhrozil se duch můj ve mně Danielovi u prostřed těla, a vidění má předěsila mne.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 16, 'Tedy přistoupil jsem k jednomu z přístojících, a ptal jsem se ho na jistotu vší té věci. I pověděl mi, a výklad řečí mi oznámil:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 17, 'Ty šelmy veliké, kteréž jsou čtyry, jsou čtyři králové, kteříž povstanou z země,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 18, 'A ujmou království svatých výsostí, kteříž obdržeti mají království až na věky, a až na věky věků.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 19, 'Tedy žádostiv jsem byl zprávy o šelmě čtvrté, kteráž rozdílná byla ode všech jiných, hrozná velmi; zubové její železní, a pazoury její ocelivé, kteráž zžírala, potírala, ostatek pak nohama svýma pošlapávala.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 20, 'Tolikéž o rozích desíti, kteříž byli na hlavě její, a o posledním, kterýž vyrostl, a před ním spadli tři; o tom rohu, pravím, kterýž měl oči a ústa mluvící pyšně, a byl na pohledění větší než jiní.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 21, 'Viděl jsem, an roh ten válku vedl s svatými, a přemáhal je,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 22, 'Až přišel Starý dnů, a oddán jest soud svatým výsostí, a čas přišel, aby to království svatí obdrželi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 23, 'Řekl takto: Šelma čtvrtá znamená království čtvrté na zemi, kteréž rozdílné bude ode všech království, a zžíře všecku zemi, a zmlátí ji a potře ji.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 24, 'Rohů pak deset znamená, že z království toho deset králů povstane, a poslední povstane po nich, kterýž bude rozdílný od prvních, a poníží tří králů.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 25, 'A slova proti Nejvyššímu mluviti bude, a svaté výsostí potře; nadto pomýšleti bude, aby proměnil časy i práva, když vydáni budou v ruku jeho, až do času a časů, i do částky časů.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 26, 'V tom bude soud osazen, a panství jeho odejmou, vypléní a vyhladí je docela.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 27, 'Království pak i panství, a důstojnost královská pode vším nebem dána bude lidu svatých výsostí; jehož království bude království věčné, a všickni páni jemu sloužiti a jeho poslouchati budou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 28, 'Až potud konec té řeči. Mne pak Daniele myšlení má velice zkormoutila, a krása má proměnila se při mně, slovo však toto v srdci svém zachoval jsem.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 1, 'Léta třetího kralování Balsazara krále ukázalo mi se vidění, mně Danielovi po onom, kteréž se mi ukázalo na počátku.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 2, 'I viděl jsem u vidění, (tehdáž pak, když jsem viděl, byl jsem v Susan, na hradě, kterýž jest v krajině Elam), viděl jsem, pravím, byv u potoka Ulai.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 3, 'A pozdvih očí svých, viděl jsem, a aj, u toho potoka stál skopec jeden, kterýž měl dva rohy. A ti dva rohové byli vysocí, a však jeden vyšší než druhý, ale ten vyšší zrostl posléze.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 4, 'Viděl jsem skopce toho, an trkal k západu, půlnoci a poledni, jemuž žádná šelma odolati nemohla, aniž kdo co mohl vytrhnouti z moci jeho; pročež činil podlé vůle své, a to věci veliké.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 5, 'A když jsem to rozvažoval, aj, kozel přicházel od západu na svrchek vší země, a žádný se ho nedotýkal na zemi, a ten kozel měl roh znamenitý mezi očima svýma.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 6, 'A přišel až k tomu skopci majícímu dva rohy, kteréhož jsem byl viděl stojícího u potoka, a přiběhl k němu v prchlivosti síly své.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 7, 'Viděl jsem také, an dotřel na toho skopce, a rozlítiv se proti němu, udeřil jej, tak že zlámal oba rohy jeho, a nebylo síly v skopci k odpírání jemu. A poraziv ho na zemi, pošlapal jej, aniž byl, kdo by vytrhl skopce z moci jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 8, 'Kozel pak velikým učiněn jest velmi. A když se ssilil, zlámal se roh ten veliký, i zrostli znamenití čtyři místo něho, na čtyři strany světa.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 9, 'Z těch pak jednoho vyšel roh jeden maličký, a zrostl velmi ku poledni a východu, a k zemi Judské.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 10, 'A zpjal se až k vojsku nebeskému, a svrhl na zemi některé z vojska toho i z hvězd, a pošlapal je.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 11, 'Anobrž až k vojska toho knížeti zpjal se, nebo od něho zastavena byla ustavičná obět, a zavržen příbytek svatyně Boží,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 12, 'Tak že vojsko to vydáno v převrácenost proti ustavičné oběti, a povrhlo pravdu na zemi, a což činilo, šťastně mu se dařilo.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 13, 'Tedy slyšel jsem jednoho svatého mluvícího, a řekl ten svatý tomu, kterýž tajné věci v počtu maje, mluví: Dokudž toto vidění o oběti ustavičné, a převrácenost na zpuštění přivodící trvati bude, a svaté služby vydávány budou i vojsko v pošlapání?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 14, 'A řekli mi: Až do dvou tisíc a tří set večerů a jiter, a přijdou k obnovení svému svaté služby.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 15, 'Stalo se pak, že když jsem já Daniel hleděl na to vidění, a ptal jsem se na rozum jeho, aj, postavil se podlé mne na pohledění jako muž.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 16, 'Slyšel jsem také hlas lidský mezi Ulaiem, kterýžto zavolav, řekl: Gabrieli, vylož tomuto vidění to.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 17, 'I přišel ke mně, kdež jsem stál, a když přišel, zhrozil jsem se, a padl jsem na tvář svou. I řekl ke mně: Pozoruj, synu člověčí; nebo v času uloženém vidění toto se naplní.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 18, 'Když pak on mluvil se mnou, usnul jsem tvrdě, leže tváří svou na zemi. I dotekl se mne, a postavil mne tu, kdež jsem byl stál,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 19, 'A řekl: Aj, já oznámím tobě to, což se díti bude až do vykonání hněvu toho; nebo v uloženém času konec bude.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 20, 'Skopec ten, kteréhož jsi viděl, an měl dva rohy, jsou králové Médský a Perský.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 21, 'Kozel pak ten chlupatý jest král Řecký, a roh ten veliký, kterýž jest mezi očima jeho, jest král první.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 22, 'Že pak zlámán jest, a povstali čtyři místo něho, čtvero království z svého národu povstane, ale ne s takovou silou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 23, 'Při dokonání pak království jejich, když na vrch vzejdou nešlechetníci, povstane král nestydatý a chytrý.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 24, 'Jehož síla zmocní se, ačkoli ne jeho silou, tak že ku podivení hubiti bude, a šťastně se mu povede, až i vše vykoná; nebo hubiti bude silné i lid svatý.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 25, 'A obmyslností svou šťastně svede lest v předsevzetí svém, a v srdci svém zvelebí sebe, a v čas pokoje zhubí mnohé; nadto i proti knížeti knížat se postaví, a však bez rukou potřín bude.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 26, 'Vidění pak to večerní a jitřní, o němž povědíno, jest jistá pravda; pročež ty zavři to vidění, nebo jest mnohých dnů.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 27, 'Tedy já Daniel zchuravěl jsem, a nemocen jsem byl několik dnů. Potom povstav, konal jsem povinnost od krále poručenou, byv předěšen nad tím viděním, čehož však žádný na mně neseznal.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 1, 'Léta prvního Daria syna Asverova z semene Médského, kteréhož učiněn jest králem v království Kaldejském,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 2, 'Léta prvního kralování jeho já Daniel porozuměl jsem z knih počtu let, o nichž se stalo slovo Hospodinovo k Jeremiášovi proroku, že se vyplní zpuštění Jeruzaléma sedmdesátého léta.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 3, 'A obrátil jsem tvář svou ku Pánu Bohu, hledaje ho modlitbou a pokornými prosbami, v postu, v žíni a popele.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 4, 'I modlil jsem se Hospodinu Bohu svému, a vyznávaje se, řekl jsem: Prosím, Pane Bože silný, veliký a všeliké cti hodný, ostříhající smlouvy a dobrotivosti k těm, kteříž tě milují, a ostříhají přikázaní tvých.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 5, 'Zhřešiliť jsme a převráceně jsme činili, bezbožnost jsme páchali, a protivili jsme se, a odvrátili od přikázaní tvých a soudů tvých.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 6, 'Aniž jsme poslouchali služebníků tvých proroků, kteříž mluvívali ve jménu tvém králům našim, knížatům našim a otcům našim, i všemu lidu země.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 7, 'Toběť, ó Pane, přísluší spravedlnost, nám pak zahanbení tváři, jakž se to děje nyní mužům Judským a obyvatelům Jeruzalémským, a všechněm Izraelským, blízkým i dalekým, ve všech zemích, kamž jsi je zahnal pro přestoupení jejich, jímž přestupovali proti tobě.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 8, 'Námť, ó Hospodine, sluší zahanbení tváři, králům našim, knížatům našim a otcům našim, neboť jsme zhřešili proti tobě,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 9, 'Pánu Bohu pak našemu milosrdenství a slitování, poněvadž jsme se protivili jemu,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 10, 'A neposlouchali jsme hlasu Hospodina Boha našeho, abychom chodili v naučeních jeho, kteréž předkládal před oči naše skrze služebníky své proroky.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 11, 'Nýbrž všickni Izraelští přestoupili zákon tvůj a odvrátili se, aby neposlouchali hlasu tvého; protož vylito jest na nás to prokletí a klatba, kteráž jest zapsána v zákoně Mojžíše služebníka Božího, nebo jsme zhřešili proti němu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 12, 'Pročež splnil slovo své, kteréž mluvil proti nám a proti soudcům našim, kteříž nás soudili, a uvedl na nás toto zlé veliké, jehož se nestalo pode vším nebem, jakéž se stalo v Jeruzalémě.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 13, 'Tak jakž zapsáno jest v zákoně Mojžíšově, všecko to zlé přišlo na nás, a však ani tak jsme se nekořili před tváří hněvivou Hospodina Boha našeho, abychom se odvrátili od nepravostí svých, a šetřili pravdy jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 14, 'Protož neobmeškal Hospodin s tím zlým, ale uvedl je na nás; nebo spravedlivý jest Hospodin Bůh náš ve všech skutcích svých, kteréž činí, jehož hlasu poslušni jsme nebyli.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 15, 'Nyní však, ó Pane Bože náš, kterýž jsi vyvedl lid svůj z země Egyptské rukou silnou, a způsobils sobě jméno, jakéž jest dnešního dne, zhřešili jsme, bezbožně jsme činili.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 16, 'Ó Pane, podlé vší tvé dobrotivosti nechť se, prosím, odvrátí hněv tvůj a prchlivost tvá od města tvého Jeruzaléma, hory svatosti tvé; nebo pro hříchy naše a pro nepravosti otců našich Jeruzalém a lid tvůj v pohanění jest u všech, kteříž jsou vůkol nás.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 17, 'Nyní tedy, ó Bože náš, vyslyš modlitbu služebníka svého, a pokorné prosby jeho, a zasvěť tvář svou nad svatyní svou spuštěnou, pro Pána.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 18, 'Nakloň, Bože můj, ucha svého a slyš, otevři oči své a viz zpuštění naše i města, kteréž jest nazváno od jména tvého; nebo ne pro nějaké naše spravedlnosti padajíce, pokorně prosíme tebe, ale pro milosrdenství tvá mnohá.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 19, 'Vyslyšiž, ó Pane, Pane, odpusť, Pane, pozoruj a učiň; neprodlévejž pro sebe samého, můj Bože, nebo od jména tvého nazváno jest město toto i lid tvůj.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 20, 'Ještě jsem mluvil a modlil se, a vyznával hřích svůj i hřích lidu svého Izraelského, a padna, pokorně jsem se modlil před tváří Hospodina Boha svého, za horu svatosti Boha svého,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 21, 'Ještě, pravím, mluvil jsem při modlitbě, a muž ten Gabriel, kteréhož jsem viděl v tom vidění na počátku, rychle přiletěv, dotekl se mne v čas oběti večerní.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 22, 'A slouže mi k srozumění, mluvil se mnou a řekl: Danieli, nyní jsem vyšel, abych tě naučil vyrozumívati tajemstvím.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 23, 'Při počátku pokorných proseb tvých vyšlo slovo, a já jsem přišel, aťbych je oznámil, nebo jsi velmi milý; pročež pozoruj slova toho, a rozuměj vidění tomu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 24, 'Sedmdesáte téhodnů odečteno jest lidu tvému a městu svatému tvému k zabránění převrácenosti a k zapečetění hříchů, i vyčištění nepravosti a k přivedení spravedlnosti věčné, a k zapečetění vidění i proroctví, a ku pomazání Svatého svatých.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 25, 'Věziž tedy a rozuměj, že od vyjití výpovědi o navrácení a o vystavení Jeruzaléma až do Mesiáše vývody bude téhodnů sedm, potom téhodnů šedesáte dva, když již zase vzdělána bude ulice a příkopa, a ti časové budou přenesnadní.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 26, 'Po téhodnech pak těch šedesáti a dvou zabit bude Mesiáš, však jemu to nic neuškodí; nýbrž to město i tu svatyni zkazí, i lid ten svůj budoucí, tak že skončení jeho bude hrozné, ano i do vykonání boje bude boj stálý všelijak do vyplénění.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 27, 'Utvrdí však smlouvu mnohým v téhodni posledním, u prostřed pak toho téhodne učiní konec oběti zápalné i oběti suché; a skrze vojsko ohavné, až do posledního a uloženého poplénění hubící, na popléněné vylito bude zpuštění.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 1, 'Léta třetího Cýra krále Perského, zjeveno bylo slovo Danielovi, kterýž sloul jménem Baltazar, a pravé bylo slovo to, i uložený čas dlouhý, a rozum toho slova i smysl zjeven jemu u vidění.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 2, 'V těch dnech já Daniel kvílil jsem za tři téhodny dnů.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 3, 'Pokrmu pochotného jsem nejedl, ani maso ani víno nevešlo do úst mých, aniž jsem se mastí mazal, až se vyplnili dnové tří téhodnů.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 4, 'Dne pak dvadcátého čtvrtého měsíce prvního, když jsem byl na břehu řeky veliké, to jest Hiddekel.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 5, 'Pozdvih očí svých, viděl jsem, a aj, muž jeden oděný v roucho lněné, a bedra jeho přepásaná byla zlatem ryzím z Ufaz.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 6, 'Tělo pak jeho jako tarsis, a oblíčej jeho na pohledění jako blesk, a oči jeho podobné pochodním hořícím, a ramena jeho i nohy jeho na pohledění jako měď vypulerovaná, a zvuk slov jeho podobný zvuku množství.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 7, 'Viděl jsem pak já Daniel sám vidění to, ale muži ti, kteříž se mnou byli, neviděli toho vidění, než hrůza veliká připadla na ně, až i utekli, aby se skryli.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 8, 'Pročež já zůstal jsem sám, a viděl jsem vidění to veliké, ale nezůstalo i ve mně síly, a krása má změnila se, a porušila na mně, aniž jsem mohl zadržeti síly.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 9, 'Tedy slyšel jsem zvuk slov jeho, a uslyšav zvuk slov jeho, usnul jsem tvrdě na tváři své, na tváři své na zemi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 10, 'V tom aj, ruka dotkla se mne, a pozdvihla mne na kolena má a na dlaně rukou mých.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 11, 'I řekl mi: Danieli, muži velmi milý, pozoruj slov, kteráž já mluviti budu tobě, a stůj na místě svém, nebo nyní poslán jsem k tobě. A když promluvil ke mně slovo to, stál jsem, třesa se.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 12, 'Pročež řekl mi: Nebojž se, Danieli; nebo od prvního dne, jakž jsi přiložil srdce své, abys rozuměl, a trápil se před Bohem svým, vyslyšána jsou slova tvá, a já přišel jsem příčinou slov tvých.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 13, 'Ale kníže království Perského postavovalo se proti mně za jedenmecítma dnů, až aj, Michal, jeden přední z knížat, přišel mi na pomoc; protož jsem já zůstával tam při králích Perských.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 14, 'Již pak přišel jsem, aťbych oznámil, co potkati má lid tvůj v potomních dnech; nebo ještě vidění bude o těch dnech.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 15, 'A když mluvil ke mně ta slova, sklopiv tvář svou k zemi, oněměl jsem.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 16, 'A aj, jako podobnost člověka dotkla se rtů mých, a otevřev ústa svá, mluvil jsem a řekl tomu, kterýž stál naproti mně: Pane můj, příčinou toho vidění obrátili se bolesti mé na mne, a aniž jsem síly zadržeti mohl.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 17, 'Jakž tedy bude moci služebník Pána mého takový mluviti se Pánem mým takovým, poněvadž ve mně od toho času, ve mně, pravím, nezůstalo síly, ani dchnutí nepozůstalo ve mně?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 18, 'Pročež opět dotkl se mne na pohledění jako člověk, a posilnil mne.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 19, 'A řekl: Neboj se, muži velmi milý, pokoj tobě, posilň se, posilň se, pravím. Když pak on mluvil se mnou, posilněn jsa, řekl jsem: Nechť mluví Pán můj, nebo jsi mne posilnil.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 20, 'I řekl: Víš-liž, proč jsem přišel k tobě? Nebo již navrátím se, abych bojoval s knížetem Perským. A já odcházím, a aj, kníže Řecké přitáhne.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 21, 'Ale oznámímť to, což jest zapsáno v psání pravdomluvném; nebo ani jednoho není, ješto by sobě zmužile počínal se mnou v těch věcech, kromě Michala knížete vašeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 1, 'A tak já léta prvního Daria Médského postavil jsem se, abych ho zmocňoval a posiloval.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 2, 'Již pak oznámímť pravdu: Aj, ještě tři králové kralovati budou v Perské zemi; potom čtvrtý zbohatne bohatstvím velikým nade všecky, a když se zmocní v bohatství svém, vzbudí všecky proti království Řeckému.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 3, 'I povstane král mocný, kterýž bude míti panství široké, a bude činiti podlé vůle své.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 4, 'Když se pak zmocní, potříno bude království jeho, a rozděleno bude na čtyři strany světa, však ne mezi potomky jeho, aniž bude panství jeho takové, jakéž bylo; nebo vykořeněno bude království jeho, a jiným mimo ně se dostane.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 5, 'Pročež posilní se král polední, ano i jedno z knížat jeho, a mocnější bude nad něho, a panovati bude; panství široké bude panství jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 6, 'Po některých pak letech spřízní se; nebo dcera krále poledního dostane se za krále půlnočního, aby učinila příměří. Ale neobdrží síly ramene, aniž on ostojí s ramenem svým, ale vydána bude ona i ti, kteříž ji přivedou, i syn její, i ten, kterýž ji posilňoval v ty časy.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 7, 'Potom povstane z výstřelku kořenů jejích na místo jeho, kterýž přitáhne s vojskem svým, a udeří na pevnost krále půlnočního, a přičiní se, aby se jich zmocnil.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 8, 'Nadto i bohy jejich s knížaty jejich, s nádobami drahými jejich, stříbrem a zlatem v zajetí zavede do Egypta, a bude bezpečen za mnoho let před králem půlnočním.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 9, 'A tak přijde do království král polední, a navrátí se do země své.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 10, 'Ale synové onoho válčiti budou, a seberou množství vojsk velikých. A nenadále přijda, jako povodeň procházeti bude, a navracuje se, válkou dotírati bude až k jeho pevnostem.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 11, 'Pročež rozdrážděn jsa král polední, vytáhne, a bojovati bude s ním, s králem půlnočním, a sšikuje množství veliké, i bude vydáno množství to v ruku jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 12, 'I pozdvihne se množství to, a povýší se srdce jeho, a ačkoli porazí na tisíce, a však se nezmocní.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 13, 'Potom navrátě se král půlnoční, sšikuje množství větší než prvé, a po dokonání času některých let, nenadále přijde s vojskem velikým a s dostatkem hojným.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 14, 'V těch časích mnozí se postaví proti králi polednímu, ale synové nešlechetní z lidu tvého zhubeni budou, a pro stvrzení vidění tohoto padnou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 15, 'Nebo přitáhne král půlnoční, a vzdělaje náspy, dobude měst hrazených, tak že ramena poledního neostojí, ani lid vybraný jeho, aniž budou míti síly k odpírání.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 16, 'A přitáhna proti němu, bude činiti podlé vůle své, a nebude žádného, ješto by se postavil proti němu. Postaví se také v zemi Judské, kterouž docela zkazí rukou svou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 17, 'Potom obrátí tvář svou, aby přitáhna s mocí všeho království svého, a ukazuje se jako by vše upřímě jednal, dovede něčeho. Nebo dá jemu krásnou pannu, aby ho zahubil skrze ni, ale ona nedostojí aniž bude držeti s ním.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 18, 'Zatím obrátí tvář svou k ostrovům, a dobude mnohých, ale vůdce přítrž učiní pohanění jeho, anobrž to hanění jeho na něj obrátí.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 19, 'Pročež obrátí tvář svou k pevnostem země své, ale klesne a padne, i zahyne.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 20, 'I povstane na místo jeho v slávě královské ten, kterýž rozešle výběrčí, ale ten po nemnohých dnech potřín bude, a to ne v hněvě, ani v boji.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 21, 'Na místě tohoto postaví se nevzácný, ačkoli nevloží na něj ozdoby královské, a však přijda pokojně, ujme království skrze úlisnost.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 22, 'A rameny jako povodní zachváceni budou před oblíčejem jeho mnozí, a potříni budou jako i ten vůdce, kterýž s ním smlouvu učinil.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 23, 'Nebo v tovaryšství s ním vejda, prokáže nad ním lest, a přijeda, zmocní se království s malým počtem lidu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 24, 'Bezpečně také i do nejúrodnějších míst té krajiny vpadne, a činiti bude to, čehož nečinili otcové jeho, ani otcové otců jeho; loupež a kořisti a zboží jim rozdělí, ano i proti pevnostem chytrosti své vymýšleti bude, a to do času.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 25, 'Potom vzbudí sílu svou a srdce své proti králi polednímu s vojskem velikým, s nímž král polední vojensky se potýkati bude, s vojskem velikým a velmi silným, ale neostojí, proto že vymyslí proti němu chytrost.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 26, 'Nebo kteříž jídají pokrm, potrou jej, když vojsko onoho se rozvodní; i padnou, zbiti jsouce mnozí.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 27, 'Tehdáž obou těch králů srdce bude činiti zlé, a za jedním a týmž stolem lež mluviti budou, ale nepodaří se, proto že cíl uložený na jiný ještě čas odložen.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 28, 'A protož navrátí se do země své s zbožím velikým, a srdce jeho bude proti smlouvě svaté. Což učině, navrátí se do země své.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 29, 'V uložený čas navrátě se, potáhne na poledne, ale to nebude podobné prvnímu ani poslednímu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 30, 'Nebo přijdou proti němu lodí Citejské, pročež bude jej to boleti, tak že opět zlobiti se bude proti smlouvě svaté. Což učině, navrátí se, a srozumění míti bude s těmi, kteříž opustili smlouvu svatou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 31, 'A vojska veliká podlé něho státi budou, a poškvrní svatyně a pevnosti; odejmou také obět ustavičnou, a postaví ohavnost zpuštění,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 32, 'Tak aby ty, kteříž se bezbožně proti smlouvě chovati budou, v pokrytství posiloval úlisnostmi, lid pak, kterýž zná Boha svého, aby jímali. Což i učiní.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 33, 'Pročež vyučující lid, vyučující mnohé, padati budou od meče a ohně, zajetí a loupeže za mnohé dny.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 34, 'A když padati budou, malou pomoc míti budou; nebo připojí se k nim mnozí pochlebně.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 35, 'Z těch pak, kteříž jiné vyučují, padati budou, aby prubováni a čištěni a bíleni byli až do času jistého; neboť to ještě potrvá až do času uloženého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 36, 'Král zajisté ten bude činiti podlé vůle své, a pozdvihne se a zvelebí nad každého boha, i proti Bohu nade všemi bohy nejsilnějšímu mluviti bude divné věci; a šťastně se mu povede až do vykonání prchlivosti, ažby se to, což uloženo jest, vykonalo.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 37, 'Ani k bohům otců svých se nenakloní, ani k milování žen, aniž k komu z bohů se nakloní, proto že se nade všecko velebiti bude.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 38, 'A na místě Boha nejsilnějšího ctíti bude boha, kteréhož neznali otcové jeho; ctíti bude zlatem a stříbrem, a kamením drahým a klénoty.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 39, 'A tak dovede toho, že pevnosti Nejsilnějšího budou boha cizího, a kteréž se mu viděti bude, poctí slávou, a způsobí, aby panovali nad mnohými, a zemi rozdělí místo mzdy.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 40, 'Při dokonání pak toho času trkati se s ním bude král polední, ale král půlnoční oboří se na něj s vozy a s jezdci a lodími mnohými, a přitáhna do zemí, jako povodeň projde.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 41, 'Potom přitáhne do země Judské, a mnohé země padnou. Tito pak ujdou ruky jeho, Idumejští a Moábští, a prvotiny synů Ammon.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 42, 'A když ruku svou vztáhne na země, ani země Egyptská nebude moci jeho zniknouti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 43, 'Nebo opanuje poklady zlata a stříbra, a všecky klénoty Egyptské; Lubimští také a Mouřenínové za ním půjdou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 44, 'V tom noviny od východu a od půlnoci přestraší jej; pročež vytáhne s prchlivostí velikou, aby hubil a mordoval mnohé.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 45, 'I rozbije stany paláce svého mezi mořemi, na hoře okrasy svatosti; a když přijde k skonání svému, nebude míti žádného spomocníka.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 12, 1, 'Toho času postaví se Michal, kníže veliké, kterýž zastává synů lidu tvého, a bude čas ssoužení, jakéhož nebylo, jakž jest národ, až do toho času; toho, pravím, času vysvobozen bude lid tvůj, kdožkoli nalezen bude zapsaný v knize.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 12, 2, 'Tuť mnozí z těch, kteříž spí v prachu země, procítí, jedni k životu věčnému, druzí pak ku pohanění a ku potupě věčné.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 12, 3, 'Ale ti, kteříž jiné vyučují, stkvíti se budou jako blesk oblohy, a kteříž k spravedlnosti přivozují mnohé, jako hvězdy na věčné věky.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 12, 4, 'Ty pak Danieli, zavři slova tato, a zapečeť knihu tuto až do času jistého. Mnozíť budou pilně zpytovati, a rozmnoženo bude umění.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 12, 5, 'Zatím viděl jsem já Daniel, a aj, jiní dva stáli, jeden z této strany břehu řeky, a druhý z druhé strany břehu též řeky.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 12, 6, 'A řekl muži tomu oblečenému v roucho lněné, kterýž stál nad vodou té řeky: Když bude konec těm divným věcem?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 12, 7, 'I slyšel jsem muže toho oblečeného v roucho lněné, kterýž stál nad vodou té řeky, an zdvihl pravici svou i levici svou k nebi, a přisáhl skrze Živého na věky, že po uloženém času, a uložených časích, i půl času, a když do cela rozptýlí násilí lidu svatého, dokonají se všecky tyto věci.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 12, 8, 'A když jsem já slyše, nerozuměl, řekl jsem: Pane můj, jaký konec bude těch věcí?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 12, 9, 'Tedy řekl: Odejdi, Danieli, nebo zavřína jsou a zapečetěna slova ta až do času jistého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 12, 10, 'Přečišťováni a bíleni a prubováni budou mnozí; bezbožní zajisté bezbožnost páchati budou, aniž co porozumějí kteří z nich, ale moudří porozumějí.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 12, 11, 'Od toho pak času, v němž odjata bude obět ustavičná, a postavena ohavnost hubící, bude dnů tisíc, dvě stě a devadesát.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 12, 12, 'Blahoslavený, kdož dočeká a přijde ke dnům tisíci, třem stům, třidcíti a pěti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 12, 13, 'Ty pak odejdi k místu svému, a odpočívati budeš, a zůstaneš v losu svém na skonání dnů.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 1, 1, 'Slovo Hospodinovo, kteréž se stalo k Ozeášovi synu Bérovu za dnů Uziáše, Jotama, Achasa, Ezechiáše, králů Judských, a za dnů Jeroboáma syna Joasova, krále Izraelského.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 1, 2, 'Když Hospodin začal mluviti k Ozeášovi, řekl Hospodin Ozeášovi: Jdi, pojmi sobě ženu smilnou, a děti z smilstva; nebo nestydatě smilněci tato země, odvrátila se od Hospodina.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 1, 3, 'A tak šel a pojal Gomeru, dceru Diblaimskou, kterážto počala a porodila jemu syna.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 1, 4, 'Tedy řekl jemu Hospodin: Nazoviž jméno jeho Jezreel; nebo po malém času já vyhledávati budu krve Jezreel na domu Jéhu, a přestati káži království domu toho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 1, 5, 'I stane se v ten den, že polámi lučiště Izraelovo v údolí Jezreel.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 1, 6, 'Opět počala znovu a porodila dceru. I řekl jemu: Nazov jméno její Lorucháma; nebo již více neslituji se nad domem Izraelským, abych jim co prominouti měl.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 1, 7, 'Ale nad domem Judským se slituji, a vysvobodím je skrze Hospodina Boha jejich; nebo nevysvobodím jich lučištěm a mečem, ani bojem, koňmi neb jezdci.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 1, 8, 'Potom ostavivši Loruchámu, opět počala a porodila syna.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 1, 9, 'I řekl: Nazov jméno jeho Loammi; nebo vy nejste lid můj, a já také nebudu váš.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 1, 10, 'A však bude počet synů Izraelských jako písku mořského, kterýž ani změřen, ani sečten býti nemůže. A stane se, že místo toho, kdež řečeno jim bylo: Nejste vy lid můj, řečeno jim bude: Synové Boha silného a živého jste.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 1, 11, 'I budou shromážděni synové Judští a synové Izraelští spolu, a ustanovíce nad sebou hlavu jednu, vyjdou z této země, ačkoli veliký bude den Jezreel.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 1, 'Rcete bratřím vašim: Ó lide můj, a sestrám vašim: Ó milosrdenství došlá.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 2, 'Odpor veďte proti matce vaší, dokažte, že ona není manželka má, a že já nejsem muž její, leč odvaruje smilství svých od tváři své, a cizoložství svých z prostřed prsí svých,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 3, 'Abych jí nesvlékl do naha, a nepostavil jí tak, jakž byla v den narození svého, a učině ji podobnou poušti, a obrátě ji jako v zemi vyprahlou, umořil bych ji žízní.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 4, 'Neslitoval bych se ani nad syny jejími, proto že jsou synové z smilstva.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 5, 'Nebo smilní matka jejich, hanebnost páše rodička jejich; říká zajisté: Půjdu za frejíři svými, kteříž mi dodávají chleba mého, vody mé, vlny mé, lnu mého, oleje mého i nápojů mých.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 6, 'A protož aj, já opletu cestu její trním, a ohradím hradbou, aby stezek svých nalezti nemohla.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 7, 'Tehdy běhati bude za frejíři svými, a však nedostihne jich, hledati jich bude, ale nenalezne. I dí: Ej nu, již se navrátím k manželu svému prvnímu, proto že mi lépe tehdáž bylo než nyní.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 8, 'Nebo ona nezná toho, že jsem já dával jí obilé, a mest a olej, anobrž rozmnožoval stříbro i zlato, kteréž vynakládají na Bále.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 9, 'Protož poberu zase obilé své v čas jeho, i mest svůj v jistý čas jeho, a odejmu jí vlnu svou i len svůj k přiodívání nahoty její,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 10, 'A tak v brzce odkryji mrzkost její před očima frejířů jejích, a žádný jí nevytrhne z ruky mé.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 11, 'A učiním přítrž vší radosti její, svátkům jejím, novoměsícům jejím i sobotám jejím, a všechněm slavnostem jejím.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 12, 'Pohubím také révoví její a fíkoví její, proto že říká: Ty věci jsou mzda má, kterouž mi dali frejíři moji; a obrátím je v les, a sžerou je živočichové polní.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 13, 'A budu na ní vyhledávati dnů Bálů, v nichž jim kadí, a ozdoběci se náušnicemi svými a záponami svými, chodí za frejíři svými, na mne se pak zapomíná, praví Hospodin.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 14, 'Protož aj, já namluvím ji, když ji uvedu na poušť; nebo mluviti budu k srdci jejímu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 15, 'A dám jí vinice její od téhož místa, i údolé Achor místo dveří naděje, i bude tam zpívati jako za dnů mladosti své, totiž jako tehdáž, když vycházela z země Egyptské.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 16, 'I stane se v ten den, dí Hospodin, že volati budeš: Muži můj, a nebudeš mne volati více: Báli můj.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 17, 'Nebo vyprázdním jména Bálů z úst tvých, aniž připomínáni budou více v jménu svém.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 18, 'A učiním pro tebe smlouvu v ten den s živočichy polními, a s ptactvem nebeským i s zeměplazy, lučiště pak a meč polámi, i válku odejmu z země, a způsobím to, aby bydleli bezpečně.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 19, 'I zasnoubím tě sobě na věčnost, zasnoubím tě sobě, pravím, v spravedlnosti a v soudu a v dobrotivosti a v hojném milosrdenství.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 20, 'Zasnoubím tě sobě také u víře, abys poznala Hospodina.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 21, 'I stane se v ten den, že vyslýchati budu, dí Hospodin, vyslýchati budu nebesa, a ona vyslyší zemi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 22, 'Země pak vyslyší obilé, i mest, i olej, a ty věci vyslyší Jezreele.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 23, 'Nebo ji rozseji sobě na zemi, a smiluji se nad Loruchámou, Loammi pak řeknu: Lid můj jsi ty, a on dí: Bože můj.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 3, 1, 'Opět řekl mi Hospodin: Ještě jdi, a zamiluj ženu, milou frejíři a cizoložnou, tak jako miluje Hospodin syny Izraelské, ačkoli oni hledí k bohům cizím, a milují kádě vína.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 3, 2, 'Tedy zjednal jsem ji sobě z patnácti stříbrných a z půldruhého chomeru ječmene.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 3, 3, 'A řekl jsem jí: Za mnoho dnů seď mi, nesmilni, aniž se vdávej za muže, a já také příčinou tvou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 3, 4, 'Nebo za mnohé dny budou synové Izraelští bez krále, bez knížete, bez oběti, bez modly, bez efodu a terafim.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 3, 5, 'Potom pak obrátí se synové Izraelští, a hledati budou Hospodina Boha svého i Davida krále svého; a předěšeni jsouce, poběhnou k Hospodinu a k dobrotě jeho v posledních časích.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 1, 'Slyšte slovo Hospodinovo, ó synové Izraelští, neboť má rozepři Hospodin s obyvateli země této, proto že není žádné věrnosti, ani žádného milosrdenství, ani žádné známosti Boží v této zemi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 2, 'Proklínání a lži a vraždy, a zlodějství i cizoložství na vrch zrostlo, a vražda vraždu postihá.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 3, 'Protož kvíliti bude tato země, a umdlí všecko, což v ní přebývá, živočichové polní i ptactvo nebeské, ano i ryby mořské zhynou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 4, 'A však žádný jim nedomlouvej, aniž jich kdo tresci; nebo lid tvůj podobni jsou těm, kteříž se vadí s knězem.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 5, 'Protož ve dne padneš, padne také i prorok s tebou v noci, zahladím i matku tvou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 6, 'Vyhlazen bude lid můj pro neumění. Poněvadž jsi ty pohrdl uměním, i tebou pohrdnu, abys mi kněžství nekonal; a že jsi zapomněl na zákon Boha svého, já také zapomenu se na syny tvé.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 7, 'Čím se více rozmohli, tím více hřešili proti mně; slávu jejich v pohanění směním.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 8, 'Oběti za hřích lidu mého jedí, protož k nepravosti jejich duše své pozdvihují.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 9, 'Pročež stane se jakž lidu tak knězi. Nebo vyhledávati budu na něm cest jeho, a skutky jeho jemu vrátím.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 10, 'I budou jísti, a však se nenasytí, smilniti budou, ale nerozmnoží se; nebo nechtějí pozoru míti na Hospodina.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 11, 'Smilství a víno a mest odjímá srdce.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 12, 'Lid můj dřeva svého se dotazuje, a hůl jeho oznamuje jemu; nebo je duch smilství v blud uvodí, aby smilnili, odcházejíce od Boha svého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 13, 'Na vrších hor obětují, a na pahrbcích kadí, pod doubím a topolím a jilmovím, nebo jest příhodný stín jejich; protož smilní dcery vaše, a nevěsty vaše cizoloží.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 14, 'Nevyhledával-liž bych na dcerách vašich, že smilní, a na nevěstách vašich, že cizoloží, že tito s nevěstkami se oddělují, a s ženkami obětují? Anobrž lid, kterýž sobě nesrozumívá, padne.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 15, 'Jestliže smilníš ty Izraeli, nechažť nehřeší Juda. Protož nechoďtež do Galgala, aniž vstupujte do Betaven, aniž přisahejte: Živť jest Hospodin.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 16, 'Nebo jako jalovice tvrdošijná tvrdošijný jest Izrael, jižť je pásti bude Hospodin jako beránka na prostranně.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 17, 'Efraim stovaryšil se s modlami, nechej ho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 18, 'Zpurné je činí nápoj jejich, velice smilní, milují: Dejte. Ochráncové jeho jsou ohyzda.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 19, 'Zachvátí je vítr křídly svými, i budou zahanbeni pro své oběti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 1, 'Slyštež to, ó kněží, a pozorujte, dome Izraelský, i dome královský, poslouchejte, nebo proti vám soud tento jest, proto že jste osídlo v Masfa, a sítka rozestřená na vrchu Tábor.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 2, 'Nýbrž k zabíjení uchylujíce se, připadají k zemi, ale já ztresci každého z nich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 3, 'Známť já Efraima, a Izrael není ukryt přede mnou; nebo nyní smilníš, Efraime, poškvrňuje se Izrael.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 4, 'Nemají se k tomu, aby se obrátili k Bohu svému, proto že duch smilství mezi nimi jest, Hospodina pak znáti nechtějí,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 5, 'Tak že hrdost Izraelova svědčí vůči proti němu; protož Izrael i Efraim padnou pro nepravost svou, padne také i Juda s nimi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 6, 'S stády bravů a skotů svých půjdou hledati Hospodina, však nenaleznou; vzdáliltě se od nich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 7, 'Hospodinu se zpronevěřili, nebo syny cizí zplodili; jižť je zžíře měsíc i s jměním jejich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 8, 'Trubte trubou v Gabaa, a na pozoun v Ráma; křičte v Betaven: Po tobě, ó Beniamine.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 9, 'Efraim zpuštěn bude v den kázně, v němž po pokoleních Izraelských uvedu v známost pravdu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 10, 'Knížata Judská jsou podobná těm, kteříž přenášejí mezník; vyleji na ně jako vodu prchlivost svou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 11, 'Utištěn jest Efraim, potřín soudem, však sobě libuje choditi za rozkazem.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 12, 'Protož i já byl jsem jako mol Efraimovi, a jako hnis domu Judovu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 13, 'Pročež vida Efraim neduh svůj, a Juda nežit svůj, utekl se Efraim k Assurovi, a poslal k králi, kterýž by se o něj zasadil. Ale on nebude moci zhojiti vás, ani uzdraviti vás od nežitů.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 14, 'Nebo já jsem jako lítý lev Efraimovi, a jako lvíče domu Judovu; já, já uchvátím a ujdu, vezmu, a žádný nevytrhne.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 15, 'Odejda, navrátím se na místo své, až se vinni dadí, a hledati budou tváři mé.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 6, 1, 'V úzkosti své ráno hledati mne budou: Poďte, a navraťme se k Hospodinu; nebo on uchvátil a zhojí nás, ubil a uvíže rány naše.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 6, 2, 'Obživí nás po dvou dnech, dne třetího vzkřísí nás, a budeme živi před oblíčejem jeho,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 6, 3, 'Tak abychom znajíce Hospodina, více poznávati se snažovali; nebo jako jitřní svitání jest vycházení jeho, a přijde nám jako déšť jarní a podzimní na zemi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 6, 4, 'Což mám činiti s tebou, ó Efraime? Což mám činiti s tebou, ó Judo, ano vaše dobrota jest jako oblak ranní, a jako rosa jitřní pomíjející?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 6, 5, 'Protož otesával jsem skrze proroky, zbil jsem je řečmi úst svých, aby soudů tvých světlo vzešlo.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 6, 6, 'Nebo milosrdenství oblibuji a ne obět, a známost Boha více než zápaly.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 6, 7, 'Ale oni smlouvu mou jako lidskou přestoupili, a tu se mi zpronevěřili.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 6, 8, 'Galád město činitelů nepravosti, plné šlepějí krvavých.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 6, 9, 'Rota pak kněžstva jsou jako lotři, kteříž na někoho čekají na cestě, kudyž se jde do Sichem; nebo zúmyslnou nešlechetnost páší.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 6, 10, 'V domě Izraelském vidím hroznou věc: Tam smilstvím Efraimovým poškvrňuje se Izrael.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 6, 11, 'Ano i u tebe, ó Judo, vsadil rouby, když jsem já zase vedl zajatý lid svůj.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 1, 'Když léčím Izraele, tedy zjevuje se nepravost Efraimova a zlosti Samařské; nebo provodí faleš. Vnitř zlodějství, a vně provozují loupežnictví.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 2, 'Aniž na to pomýšlejí v srdci svém, že na všecku nešlechetnost jejich pamatují; již je obkličují skutkové jejich, a před mým oblíčejem jsou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 3, 'Nešlechetností svou obveselují krále, a klamy svými knížata.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 4, 'Všickni napořád cizoloží, podobni jsouce peci zanícené od pekaře, kterýž přestává bdíti, jen ažby zadělané těsto zkynulo.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 5, 'V den krále našeho k nemoci jej přivodí knížata láhvicí vína; vztahuje ruku svou s posměvači.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 6, 'Nebo přiložili k úkladům svým srdce své podobné peci; celou noc spí pekař jejich, v jitře hoří jako plamen ohně.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 7, 'Všickni napořád rozpáleni jsou jako pec, a zžírají soudce své; všickni králové jejich padají, aniž kdo z nich volá ke mně.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 8, 'Efraim s národy smísil se, Efraim bude chléb podpopelný neobrácený.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 9, 'Cizozemci zžírají sílu jeho, ačkoli on toho nezná; i šedinami prokvítaje, však vždy toho nezná.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 10, 'A ačkoli pýcha Izraelova svědčí vůči proti němu, však se nenavracují k Hospodinu Bohu svému, aniž ho hledají s tím se vším.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 11, 'A Efraim jest jako holubice hloupá bez srdce; k Egyptskému králi volají, k Assyrskému se utíkají.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 12, 'Když odejdou, roztáhnu na ně sítku svou, a jako ptactvo nebeské přitrhnu je; kárati je budu tak, jakž slýcháno bylo o tom v shromáždění jejich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 13, 'Běda jim, že jsou poběhli mne. Zpuštění na ně, proto že se mi zpronevěřili, ješto jsem já je vykoupil, ale oni mluvili proti mně lži.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 14, 'Aniž volají ke mně z srdce svého, když kvílí na ložcích svých, a když pro obilé a mest shromažďujíce se, obracejí se ke mně,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 15, 'Ješto já potrestav, posiloval jsem ramen jejich, ale oni proti mně zlé vymýšlejí.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 16, 'Navracujíť se, ale ne k Nejvyššímu, jsou jako lučiště omylné, padají od meče knížata jejich, od rozhněvání jazyka jejich, což jim ku posměchu jest v zemi Egyptské.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 8, 1, 'Přičině k ústům svým troubu, rci: Aj, letí jako orlice na dům Hospodinův, proto že přestoupili smlouvu mou, a proti zákonu mému převráceně činili.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 8, 2, 'Budouť sic volati: Bože můj, znáť tebe Izrael,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 8, 3, 'Ale opustilť jest Izrael dobré, nepřítel jej stihati bude.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 8, 4, 'Oniť ustanovují krále, ale beze mne; knížata vyzdvihují, k nimž já se neznám; z stříbra i z zlata svého činí sobě modly k svému zkažení.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 8, 5, 'Opustíť je tele tvé, ó Samaří, když se zažhne prchlivost má na ně. Až dokudž nebudou moci ostříhati nevinnosti?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 8, 6, 'Však i ono jest od Izraele, řemeslník je udělal, a neníť Bohem; nebo drtiny budou z toho telete Samařského.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 8, 7, 'Poněvadž větru rozsívají, takéť vichřici žíti budou; ani stébla žádného míti nebudou; úroda nevydá mouky, a by pak i vydala, cizozemci to sehltí.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 8, 8, 'Sehlcen bude Izrael, tudíž budou mezi pohany jako nádoba, v níž není žádné líbosti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 8, 9, 'Proto že se oni utíkají k Assurovi, oslu divokému, kterýž jest toliko sám svůj, a že Efraim sobě najímá milovníky,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 8, 10, 'A že posílali dary mezi pohany: protož tudíž je zberu i já, anobrž jižť jsou okusili něčeho pro břímě krále knížat.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 8, 11, 'Nebo vzdělal Efraim mnoho oltářů k hřešení, máť oltáře k hřešení.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 8, 12, 'Vypsal jsem jemu znamenité věci v zákoně svém, ale neváží sobě rovně jako cizí věci.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 8, 13, 'Z obětí darů mých obětují maso a jedí, Hospodin neoblibuje jich. Jižť zpomene na nepravost jejich, a vyhledávati bude hříchy jejich, že se oni do Egypta navracují,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 8, 14, 'A že se zapomenul Izrael na Učinitele svého, a nastavěl chrámů, a Juda vzdělal mnoho měst hrazených. Protož pošli oheň na města jeho, a zžíře paláce jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 1, 'Neraduj se, Izraeli, s plésáním jako jiní národové, že smilníš, odcházeje od Boha svého, a miluješ mzdu po všech obilnicích.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 2, 'Obilnice ani pres nebude jich pásti, a mest pochybí jim.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 3, 'Aniž budou bydliti v zemi Hospodinově, ale navrátí se Efraim do Egypta, a v Assyrii věci nečisté jísti budou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 4, 'Nebudou obětovati Hospodinu vína, aniž příjemné jemu bude. Oběti jejich budou jako chléb kvílících, z něhož kdož by koli jedli, poškvrnili by se, protože chléb jejich pro mrtvé jejich nemá přicházeti do domu Hospodinova.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 5, 'Co pak činiti budete v den slavnosti, a v den svátku Hospodinova?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 6, 'Nebo aj, zahynou skrze poplénění, Egypt zbéře je, a pohřbí je Memfis; nejrozkošnějšími schranami stříbra jejich kopřiva dědičně vládnouti bude, a bodláčí v domích jejich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 7, 'Přijdou dnové navštívení, přijdou dnové odplacení, poznají Izraelští, že ten prorok jest blázen šílený a člověk ničemný, pro množství nepravosti tvé a velikou nenávist tvou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 8, 'Prorok, kterýž stráž drží nad Efraimem spolu s Bohem mým, jest osídlem čihařským na všech cestách svých, nenávist jest v domě Boha jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 9, 'Hlubokoť jsou zabředli a porušili se, tak jako za dnů Gabaa; zpomeneť na nepravost jejich, a vyhledávati bude hříchy jejich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 10, 'Jako hrozny na poušti nalezl jsem byl Izraele, jako ranní fíky v prvotinách jejich popatřil jsem na otce vaše; oni odešli za Belfegor, a oddali se té ohavnosti, protož budouť ohavní, tak jakž se jim líbilo.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 11, 'Efraim jako pták zaletí, i sláva jejich od narození a od života, nýbrž od početí.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 12, 'A byť pak i odchovali syny své, však je zbavím věku zmužilého; nýbrž i jim běda, když já se od nich odvrátím.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 13, 'Efraim, jakýž vidím Týr, vštípen jest v obydlí, a však Efraim vyvede k mordéři syny své.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 14, 'Dej jim, Hospodine; co bys dal? Dej jim život neplodný a prsy vyschlé.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 15, 'Vrch zlosti jejich jest v Galgala, protož i tam jich nenávidím. Pro zlost skutků jejich vyženu je z domu svého, aniž jich více budu milovati; všecka knížata jejich jsou zpurná.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 16, 'Bit bude Efraim, kořen jejich uschne, ovoce nepřinesou, a byť pak zplodili, tedy zmořím nejmilejší života jejich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 17, 'Pohrdne jimi Bůh můj, nebo nechtí ho poslouchati, i budou tuláci mezi pohany.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 1, 'Izrael jest vinný kmen prázdný, ovoce skládá sobě. Čím více mívá ovoce svého, tím více rozmnožuje oltáře, a čím lepší jest země jeho, tím více vzdělává obrazy.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 2, 'Klade díly srdce jejich, pročež vinni jsou. Onť poboří oltáře jejich, popléní obrazy jejich,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 3, 'Poněvadž i říkají: Nemáme žádného krále, nýbrž aniž se bojíme Hospodina, a král co by nám učinil?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 4, 'Mluví slova, klnouce se lživě, když činí smlouvu, a soud podobný jedu roste na záhonech polí mých.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 5, 'Z příčiny jalovic Betavenských děsiti se budou obyvatelé Samařští, když kvíliti bude nad nimi lid jejich i kněží jejich, (kteříž příčinou jejich nyní pléší), proto že sláva jejich zastěhuje se od nich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 6, 'Ano i sám lid do Assyrie zaveden bude v dar králi, kterýž obhájce býti měl; Efraim hanbu ponese, a Izrael styděti se bude za své předsevzetí.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 7, 'Vyhlazen bude král Samařský jako pěna na svrchku vody.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 8, 'Vypléněny budou také výsosti Avenu, hřích Izraelských, trní a hloží zroste na oltářích jejich. I dějí horám: Přikrejte nás, a pahrbkům: Padněte na nás.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 9, 'Ode dnů Gabaa hřešil jsi, Izraeli. Tamť jsou ostáli, nepostihla jich v Gabaa válka proti nešlechetným.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 10, 'A protož podlé líbosti své svíži je; nebo sberou se na ně národové k svázání jich, pro dvojí nepravost jejich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 11, 'Nebo Efraim jest jalovička, kteráž byla vyučována; mlatbu miluje, ačkoli jsem já nastupoval na tučný krk její, abych k jízdě užíval Efraima, Juda aby oral, a Jákob vláčil. A říkal jsem:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 12, 'Rozsívejte sobě k spravedlnosti, žněte k milosrdenství, ořte sobě ouhor, poněvadž čas jest k hledání Hospodina, ažby přišel a dštil vám spravedlností.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 13, 'Ale orali jste bezbožnost, žali jste nepravost, jedli jste ovoce lži; nebo doufáš v cestu svou a ve množství reků svých.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 14, 'Protož povstane rozbroj mezi lidem tvým, i každá pevnost tvá zpuštěna bude, tak jako zpustil Salman Bet Arbel v den boje; matky s syny rozrážíny budou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 15, 'Aj, toť vám způsobí Bethel pro přílišnou nešlechetnost vaši; na svitání docela vyhlazen bude král Izraelský.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 11, 1, 'Když dítětem byl Izrael, miloval jsem jej, a z Egypta povolal jsem syna svého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 11, 2, 'Volali jich, oni tím více ucházeli před nimi, Bálům obětovali, a rytinám kadili,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 11, 3, 'Ješto jsem já na nohy stavěl Efraima, on pak bral je na lokty své; aniž znáti chtěli, že jsem já je uzdravoval.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 11, 4, 'Potahoval jsem jich provázky lidskými, provazy milování, a činil jsem jim tak jako ti, kteříž pozdvihují jha na čelistech hovádka, podávaje potravy jemu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 11, 5, 'Nenavrátíť se do země Egyptské, ale Assur bude králem jeho, proto že se nechtěli obrátiti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 11, 6, 'Nadto bude trvati meč v městech jeho, a zkazí závory jeho, a sžíře je pro rady jejich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 11, 7, 'Nebo lid můj ustrnul na odvrácení se ode mne, a ač ho k Nejvyššímu volají, však žádný ho neoslavuje.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 11, 8, 'Jakž bych tě vydal, ó Efraime? Jakž bych tě vydal, ó Izraeli? Kterak bych tě položil jako Adamu, podvrátil jako Seboim? Zkormouceno jest ve mně srdce mé, ano i střeva slitování mých pohnula se.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 11, 9, 'Nevykonámť prchlivosti hněvu svého, nezkazím více Efraima; nebo jsem já Bůh silný, a ne člověk, u prostřed tebe svatý, aniž přitáhnu na město.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 11, 10, 'I půjdou za Hospodinem řvoucím jako lev; on zajisté řváti bude, tak že s strachem přiběhnou synové od moře.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 11, 11, 'S strachem poběhnou jako ptactvo z Egypta, a jako holubice z země Assyrské, i osadím je v domích jejich, dí Hospodin.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 11, 12, 'Obklíčili mne Efraimští lží, a dům Izraelský lstí, když ještě Juda panoval s Bohem silným, a s svatými věrný byl.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 12, 1, 'Efraim se větrem pase, a vítr východní honí, každého dne lež a zhoubu množí; nebo smlouvu s Assurem činí, a masti do Egypta donášejí se.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 12, 2, 'I s Judou má soud Hospodin; pročež navštívě Jákoba podlé cest jeho, podlé snažností jeho odplatí jemu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 12, 3, 'V životě za patu držel bratra svého, a silou svou knížetsky se potýkal s Bohem.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 12, 4, 'Knížetsky, pravím, potýkal se s andělem, a přemohl; plakal a pokorně ho prosil; v Bethel jej nalezl, a tam s námi mluvil.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 12, 5, 'Toť jest Hospodin Bůh zástupů, pamětné jeho jest Hospodin.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 12, 6, 'Protož ty k Bohu svému se obrať, milosrdenství a soudu ostříhej, a očekávej na Boha svého ustavičně.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 12, 7, 'Kramářem jest, v jehož ruce jsou vážky falešné, rád utiskuje,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 12, 8, 'A říká Efraim: Však jsem zbohatl, dobyl jsem sobě zboží; ve všech mých pracech nenajdou mi nepravosti, jenž by hříchem byla.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 12, 9, 'Já pak Hospodin jsa Bohem tvým od vyjití z země Egyptské, ještě-liž bych tě seděti nechal v stáncích jako ve dnech svátečních?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 12, 10, 'A mluvě skrze proroky, já abych vidění mnoho ukazoval, a skrze proroky podobenství předkládal?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 12, 11, 'Zdali toliko v Galád byla nepravost a marnost? I v Galgala voly obětují, přes to i oltářů jejich jest jako kopců na záhonech polí mých.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 12, 12, 'Tamto utekl byl Jákob z krajiny Syrské, kdež sloužil Izrael pro ženu, a pro ženu byl pastýřem;');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 12, 13, 'Sem pak skrze proroka přivedl Hospodin Izraele z Egypta, též skrze proroka ostříhán jest.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 12, 14, 'Vzbudilť Efraim hněv přehořký, a protož krev jeho na něj se vztáhne, a potupu svou vrátí jemu Pán jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 13, 1, 'Když mluvíval Efraim, býval strach; vznešený byl v Izraeli, ale prohřešiv při Bálovi, tožť umřel.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 13, 2, 'A i nyní ještě předce hřeší. Nebo dělají sobě a slévají z stříbra svého podlé rozumu svého strašidla, ješto všecko to není než dílo řemeslníků, o čemž říkají: Lidé, kteříž obětují, telata ať líbají.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 13, 3, 'Protož budou jako oblak ranní a jako rosa jitřní, kteráž odchází, jako plevy vichřicí zachvácené z humna, a jako dým z komínu,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 13, 4, 'Ješto já jsem Hospodin Bůh tvůj od vyjití z země Egyptské, a Boha kromě mne nepoznal jsi, aniž jest jiný vysvoboditel kromě mne.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 13, 5, 'Jáť jsem tě poznal na poušti v zemi velmi vyprahlé.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 13, 6, 'Dobré pastvy měvše, nasyceni jsou, ale když se nasytili, pozdvihlo se srdce jejich, protož zapomenuli na mne.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 13, 7, 'Pročež budu jim jako lítý lev, jako pardus vedlé cesty číhati budu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 13, 8, 'Potkám se s nimi jako nedvěd osiřelý, a roztrhám všecko srdce jejich, a sežeru je tam jako lev, jako zvěř divoká roztrhující je.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 13, 9, 'Z tebeť jest zhouba tvá, ó Izraeli, ješto ve mně všecka pomoc tvá.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 13, 10, 'Kdež jest král tvůj? Kdež jest? Nechť tě zachová ve všech městech tvých. Aneb soudcové tvoji, o nichž jsi řekl: Dej mi krále a knížata?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 13, 11, 'Dal jsem tobě krále v hněvě svém, a odjal jsem v prchlivosti své.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 13, 12, 'Svázánať jest nepravost Efraimova, schován jest hřích jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 13, 13, 'Bolesti rodičky přijdou na něj; jest syn nemoudrý, sic jinak nezůstával by tak dlouho v životě matky.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 13, 14, 'Z ruky hrobu vyplatím je, od smrti vykoupím je; budu zhoubcím tvým, ó smrti, budu zkažením tvým, ó hrobe, želení skryto bude od očí mých.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 13, 15, 'Nebo on mezi bratřími ovoce ponese, ač prv přijde vítr východní, vítr Hospodinův od pouště vstupující, a vysuší studnice jeho, osuší i vrchoviště jeho; onenno rozchvátá poklad všech nejdražších klénotů.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 13, 16, 'Zpuštěna bude Samaří, proto že se protivila Bohu svému; od meče padnou, dítky jejich zrozrážíny budou, a těhotné ženy jejich zroztínány.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 14, 1, 'Obratiž se, ó Izraeli, cele k Hospodinu Bohu svému, nebo jsi padl příčinou nepravosti své.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 14, 2, 'Vezměte s sebou slova, a obraťte se k Hospodinu, a rcete jemu: Sejmi všelikou nepravost, a dej to, což dobrého jest, a budemeť se odplaceti volky rtů našich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 14, 3, 'Assurť nemůže zachovati nás, na koních nepojedeme, aniž díme více dílu rukou našich: Bůh náš; nebo v tobě smilování nalézá sirotek.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 14, 4, 'Uzdravím odvrácení jejich, budu je milovati dobrovolně; nebo odvrácen bude hněv můj od nich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 14, 5, 'Budu jako rosa Izraelovi, zkvetne jako lilium, a hluboce vpustí kořeny své jako Libán.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 14, 6, 'Rozloží se ratoléstky jeho, a bude jako oliva okrasa jeho, a vůně jeho jako Libánská.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 14, 7, 'Ti, kteříž by seděli pod stínem jeho, navrátí se, oživou jako obilé, a pučiti se budou jako kmen vinný, jehož památka bude jako vína Libánského.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 14, 8, 'Efraime, což jest mi již do modl? Já vyslýchati, a patřiti budu na tě; já jsem jako jedle zelenající se, ze mneť ovoce tvé jest.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 14, 9, 'Kdo jest moudrý, porozuměj těmto věcem, a rozumný poznej je; nebo přímé jsou cesty Hospodinovy, a spravedliví choditi budou po nich, přestupníci pak na nich padnou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 1, 'Slovo Hospodinovo, kteréž se stalo k Joelovi synu Petuelovu:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 2, 'Slyšte to starší, a pozorujte všickni obyvatelé této země, stalo-li se to za dnů vašich, aneb za dnů otců vašich?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 3, 'Vypravujte o tom synům svým, a synové vaši synům svým, synové pak jejich rodině potomní.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 4, 'Co pozůstalo po housenkách, snědly kobylky, a co pozůstalo po kobylkách, snědli brouci, co pak pozůstalo po broucích, dojedli chroustové.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 5, 'Prociťte opilci, a plačte a kvělte všickni, kteříž píjíte víno, proto že odtržen jest mest od úst vašich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 6, 'Nebo přitáhl do země mé národ silný a nesčíslný, jehož zubové zubové lva, a střenovní zubové jeho lvoví.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 7, 'Přivedl vinné kmeny mé v pustinu, a fíkoví mé na zkázu; docela obnažil je a zporážel, zbělely ratolesti jejich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 8, 'Kvěl jako mladice přepásaná žíní pro muže mladosti své.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 9, 'Odjata jest suchá i mokrá obět z domu Hospodinova, kvílí kněží, služebníci Hospodinovi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 10, 'Zpustlo pole, kvílí země, proto že pohubeno obilé, vyschl mest, olej zhynul.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 11, 'Stydí se oráči, kvílí vinaři z příčiny pšenice a ječmene; nebo zahynula žeň polní.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 12, 'Vinný kmen usechl, a fík usvadl, strom zrnatých jablek, též i palma i jabloň, všecko dříví polní poschlo, a že odňato potěšení od synů lidských.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 13, 'Přepašte se a kvělte, ó kněží, úpějte přisluhující oltáři, vejděte a léhejte i v noci v žíních, služebníci Boha mého. Nebo nevnáší se do domu Boha vašeho suché ani mokré oběti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 14, 'Uložte půst, svolejte shromáždění, shromažďte starší i všecky obyvatele země do domu Hospodina Boha vašeho, a volejte k Hospodinu:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 15, 'Ach, nastojte na tento den; nebo blízký jest den Hospodinův, a jako poplénění od Všemohoucího přichází.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 16, 'Ano před očima našima pokrm odjat jest, z domu Boha našeho veselé a plésání.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 17, 'Vyhynulo símě pod hrudami svými, zpustly stodoly, zbořeny jsou obilnice; nebo vyschlo obilé.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 18, 'Aj, jak vzdychá dobytek, svírají se stáda skotů, proto že nemají žádné pastvy, ano i stáda bravů hynou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 19, 'K toběť, ó Hospodine, volám; nebo oheň sežral pastviska pouště; a plamen popálil všecka dříví polní.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 20, 'Také i zvěř polní všecka lká k tobě, proto že vyschli potokové vod, a oheň sežral pastviska na poušti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 1, 'Trubte trubou na Sionu, a křičte na hoře svaté mé, nechť se třesou všickni obyvatelé této země, nebo přichází den Hospodinův, nebo blízký jest,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 2, 'Den temnosti a mračna, den oblaku a mrákoty, jako záře jitřní rozprostřená po horách: Lid mnohý a silný, jemuž rovného nebylo od věků, aniž po něm kdy bude až do let národů i pronárodů.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 3, 'Před tváří jeho oheň zžírati bude, a za ním plamen plápolati; před ním země tato jako zahrada Eden, ale po něm bude poušť přehrozná, a aniž bude, což by ušlo před ním.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 4, 'Způsob jeho bude jako způsob koní, a jako jízdní, tak poběhnou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 5, 'Jako s hřmotem vozů po vrších hor skákati budou, jako hluk plamene ohně zžírajícího strniště, jako lid silný zšikovaný k bitvě.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 6, 'Tváři jeho děsiti se budou lidé, všecky tváře zčernají jako hrnec.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 7, 'Jako rekové poběhnou, jako muži váleční vstoupí na zed, a jeden každý cestou svou půjde, aniž se uchýlí z stezek svých.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 8, 'Jeden druhého nebude tlačiti, každý silnicí svou půjde, a byť i na meč upadli, nebudou raněni.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 9, 'Po městě těkati budou, po zdech běhati, na domy vstupovati, a okny polezou jako zloděj.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 10, 'Před tváří jeho třásti se bude země, pohnou se nebesa, slunce i měsíc se zatmí, a hvězdy potratí blesk svůj.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 11, 'Hospodin pak sám vydá hlas svůj před vojskem svým, proto že velmi veliký bude tábor jeho, proto že silný ten, kdož vykoná slovo jeho. (Nebo veliký bude den Hospodinův a hrozný náramně), i kdož jej bude moci snésti?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 12, 'A protož ještě nyní dí Hospodin: Obraťte se ke mně samému celým srdcem svým, a to s postem a s pláčem i s kvílením.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 13, 'A roztrhněte srdce vaše, a ne roucha vaše, a navraťte se k Hospodinu Bohu vašemu; neboť jest on milostivý a lítostivý, dlouhočekající a hojný v milosrdenství, a kterýž lituje zlého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 14, 'Kdo ví, neobrátí-li se a nebude-li želeti, a nezůstaví-li po něm požehnání, oběti suché a mokré Hospodinu Bohu vašemu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 15, 'Trubte trubou na Sionu, uložte půst, svolejte shromáždění.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 16, 'Shromažďte lid, posvěťte shromáždění, shromažďte starce, shromažďte maličké i ty, jenž prsí požívají; nechť vyjde ženich z pokojíka svého a nevěsta z schrany své.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 17, 'Kněží, služebníci Hospodinovi, ať plačí mezi síňcí a oltářem, a řeknou: Odpusť, ó Hospodine, lidu svému, a nevydávej dědictví svého v pohanění, tak aby nad nimi panovati měli pohané. Proč mají říkati mezi národy: Kde jest Bůh jejich?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 18, 'I bude horlivou milostí zažžen Hospodin k zemi své, a slituje se nad lidem svým.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 19, 'A ohlásí se Hospodin, a řekne lidu svému: Aj, já pošli vám obilé, mest a olej, i budete jím nasyceni, aniž vás vydám více v pohanění mezi pohany.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 20, 'Nebo půlnoční vojsko vzdálím od vás, a zaženu je do země vyprahlé a pusté, přední houf jeho k moři východnímu, konec pak jeho k moři nejdalšímu; i vzejde z něho smrad a puch, jakžkoli sobě mocně počíná.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 21, 'Neboj se země, plésej a vesel se; neboť mocně dělati bude Hospodin dílo své.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 22, 'Nebojtež se zvířátka polí mých; neboť se zotaví pastviska na poušti, a stromoví přinese ovoce své, fík i vinný kmen vydadí moc svou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 23, 'I vy, synové Sionští, plésejte a veselte se v Hospodinu Bohu vašem; nebo vám dá déšť příhodný, a sešle vám déšť hojný, podzimní i jarní, v čas.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 24, 'I budou naplněny stodoly obilím, a oplývati budou presové mstem a olejem.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 25, 'A tak nahradím vám léta, kteráž sežraly kobylky, brouci, chroustové a housenky, vojsko mé veliké, kteréž jsem posílal na vás.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 26, 'Budete zajisté míti co jísti, a nasyceni jsouce, chváliti budete jméno Hospodina Boha svého, kterýž učinil s vámi divné věci, aniž zahanben bude lid můj na věky.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 27, 'A poznáte, že já jsem u prostřed Izraele, a že já Hospodin jsem Bohem vaším, a že není žádného jiného; neboť nebude zahanben lid můj na věky.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 28, 'I stane se potom, že vyleji Ducha svého na všeliké tělo, a budou prorokovati synové vaši i dcery vaše; starci vaši sny mívati budou, mládenci vaši vidění vídati budou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 29, 'Nýbrž i na služebníky a na služebnice v těch dnech vyleji Ducha svého,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 30, 'A ukáži zázraky na nebi i na zemi, krev a oheň a sloupy dymové.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 31, 'Slunce obrátí se v tmu a měsíc v krev, prvé než přijde den Hospodinův veliký a hrozný,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 32, 'A však stane se, že kdož by koli vzýval jméno Hospodinovo, vysvobozen bude; nebo na hoře Sion a v Jeruzalémě bude vysvobození, jakož pověděl Hospodin, totiž v ostatcích, kterýchž povolá Hospodin.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 1, 'Nebo aj, v těch dnech a v ten čas, když zase přivedu zajatý lid Judský a Jeruzalémský,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 2, 'Shromáždím také všecky národy, a svedu je do údolí Jozafat, abych se tam soudil s nimi o lid svůj a dědictví své, Izraele, jejž rozptýlili mezi pohany a zemi mou rozdělili.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 3, 'Také o lid můj metali los, a dávali mládence za nevěstku, mladice pak prodávali za víno, aby pili.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 4, 'Anobrž, co vy máte proti mně, ó Tyrští a Sidonští, i všecky končiny Filistinské? Zdaliž se mi odplacujete? Jestliže mi se odplacujete, snadněť a vnáhleť i já obrátím odplatu vaši na hlavu vaši,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 5, 'Kteříž stříbro mé i zlato mé béřete, a klénoty mé výborné vnášíte do chrámů svých,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 6, 'A syny Judské i syny Jeruzalémské prodáváte synům Javanovým, aby je pryč zavodili od pomezí jejich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 7, 'Aj, já vzbudím je z toho místa, kamž jste je prodali, a obrátím odplatu vaši na hlavu vaši.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 8, 'Prodám zajisté syny i dcery vaše v moc synů Judských, i prodadí je Sabejským, do národu dalekého; neboť jest Hospodin mluvil.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 9, 'Provolejte to mezi národy, vyhlaste boj, probuďte reků, nechť přitáhnou, a dadí se najíti všickni muži váleční.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 10, 'Skujte motyky své v meče, a srpy své v oštípy; ten, kterýž jest mdlý, nechť řekne: Udatný jsem.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 11, 'Shromažďte se a přitáhněte všickni národové okolní, a shlukněte se; způsobiž to, ať tam sstoupí, ó Hospodine, rekové tvoji.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 12, 'Probudíť se a přitáhnou národové ti do údolé Jozafat; nebo tam se posadím, abych soudil všecky ty národy okolní.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 13, 'Přičiňte srp, nebo uzralo obilé; poďte, sstupte, nebo plný jest pres, oplývají kádě; mnohá zajisté jest zlost jejich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 14, 'Ale více hromad, hromad v údolí posekání; nebo blízký jest den Hospodinův, v údolí posekání.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 15, 'Slunce a měsíc zatmí se, a hvězdy potratí blesk svůj.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 16, 'A Hospodin řváti bude z Siona, a z Jeruzaléma vydá hlas svůj, tak že se třásti budou nebesa i země; nebo Hospodin jest útočiště lidu svého, a síla synů Izraelských.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 17, 'I zvíte, že já Hospodin jsem Bohem vaším, kterýž bydlím na Sionu, hoře svatosti své, a tak Jeruzalém bude svatý, a cizí nepůjdou přes něj více.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 18, 'I stane se v ten čas, že hory dštíti budou mstem, a pahrbkové oplývati mlékem, a všickni potokové Judští budou plní vody, a studnice z domu Hospodinova vyjde, kteráž zapojí údolé Setim.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 19, 'Egypt na zpuštění přijde, a země Idumejská hrozně zpuštěna bude pro násilí synům Judským činěné; nebo vylévali krev nevinnou v zemi jejich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 20, 'Juda pak na věky trvati bude, a Jeruzalém od národu do pronárodu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 21, 'A očistím ty, jejichž jsem krve neočistil; nebo Hospodin přebývá na Sionu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 1, 1, 'Slova Amosova, (kterýž byl mezi pastýři) z Tekoa, kteráž viděl o Izraelovi za dnů Uziáše krále Judského, a za dnů Jeroboáma syna Joasova, krále Izraelského, dvě létě před země třesením.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 1, 2, 'I řekl: Hospodin řváti bude z Siona, a z Jeruzaléma vydá hlas svůj, i budou kvíliti salášové pastýřů, a vyschnou pole nejvýbornější.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 1, 3, 'Takto praví Hospodin: Pro troji nešlechetnost Damašku, ovšem pro čtveru neodpustím jemu, proto že mlátili Galáda cepami okovanými.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 1, 4, 'Ale pošli oheň na dům Hazaelův, kterýžto zžíře paláce Benadadovy.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 1, 5, 'I polámi závoru Damašku, a vypléním obyvatele z údolí Aven, a toho, kterýž drží berlu, z domu Eden, i půjde v zajetí lid Syrský do Kir, dí Hospodin.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 1, 6, 'Takto praví Hospodin: Pro troji nešlechetnost Gázy, ovšem pro čtveru neslituji se nad ním, proto že je zajímajíce, v zajetí věčné podrobovali Idumejským.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 1, 7, 'Ale pošli oheň na zed Gázy, kterýžto zžíře paláce její,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 1, 8, 'A vypléním obyvatele z Azotu, i toho, kterýž drží berlu, z Aškalon, a obrátím ruku svou proti Akaron, i zahyne ostatek Filistinských, praví Panovník Hospodin.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 1, 9, 'Takto praví Hospodin: Pro troji nešlechetnost Týru, ovšem pro čtveru neodpustím jemu, proto že je v zajetí věčné podrobili Idumejským, a nepamatovali na smlouvu bratrskou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 1, 10, 'Ale pošli oheň na zed Tyrskou, kterýžto zžíře paláce jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 1, 11, 'Takto praví Hospodin: Pro troji nešlechetnost Edoma, ovšem pro čtveru neslituji se nad ním, proto že udusiv v sobě všecku lítostivost, stihá mečem bratra svého, a hněv jeho ustavičně rozsapává, anobrž vzteklost jeho špehuje bez přestání.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 1, 12, 'Ale pošli oheň na Teman, kterýžto zžíře paláce v Bozra.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 1, 13, 'Toto praví Hospodin: Pro troji nešlechetnost synů Ammon, ovšem pro čtveru neodpustím jemu, proto že roztínali těhotné Galádské, jen aby rozšiřovali pomezí své.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 1, 14, 'Ale zanítím oheň na zdi Rabba, kterýžto zžíře paláce její, s troubením v den boje a s bouří v den vichřice.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 1, 15, 'I půjde král jejich v zajetí, on i knížata jeho s ním, praví Hospodin.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 1, 'Takto praví Hospodin: Pro troji nešlechetnost Moábovu, ovšem pro čtveru neodpustím jemu, proto že spálil kosti krále Idumejského na vápno.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 2, 'Ale pošli oheň na Moába, kterýžto zžíře paláce Kariot, i umře s hlukem Moáb, s křikem a s hlasem trouby.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 3, 'A vypléním soudce jeho, i všecka knížata jeho zmorduji s ním, praví Hospodin.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 4, 'Takto praví Hospodin: Pro troji nešlechetnost Judovu, ovšem pro čtveru neslituji se nad ním, proto že oni pohrdají zákonem Hospodinovým, a ustanovení jeho neostříhají, a svodí se lžmi svými, jichž následovali otcové jejich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 5, 'Ale pošli oheň na Judu, kterýžto zžíře paláce Jeruzalémské.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 6, 'Takto praví Hospodin: Pro troji nešlechetnost Izraelovu, ovšem pro čtveru neodpustím jemu, proto že prodávají spravedlivého za peníze, a nuzného za pár střevíců.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 7, 'Kteříž dychtí, aby chudé s prstí smísili, a cestu tichých převracejí; nadto syn i otec vcházejí k jedné a též mladici, aby poškvrnili jména svatosti mé.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 8, 'A na oděvu zastaveném klanějí se při každém oltáři, a víno pokutovaných pijí v domě bohů svých,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 9, 'Ješto jsem já vyhladil Amorejského od tváři jejich, jehož vysokost byla jako vysokost cedrů. Ačkoli pevně stál jako dub, však jsem zkazil svrchu ovoce jeho, pospodu pak kořeny jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 10, 'A vás já jsem vyvedl z země Egyptské, a vyvedl jsem vás po poušti čtyřidceti let, abyste dědičně vládli zemí Amorejského.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 11, 'A vzbuzoval jsem z synů vašich proroky, a z mládenců vašich Nazarejské. Zdaliž není tak, ó synové Izraelští? praví Hospodin.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 12, 'Ale vy jste napájeli Nazarejské vínem, a prorokům jste zapovídali, řkouce: Neprorokujte.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 13, 'Aj, já tlačiti budu zemi vaši tak, jako vůz těžký tlačí snopy.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 14, 'I zahyne utíkání od rychlého, silný též neužive síly své, a udatný nevysvobodí života svého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 15, 'A ten, kterýž se chápá lučiště, neostojí, a čerstvý na nohy své neuteče, a ten, kterýž jezdí na koni, nevysvobodí života svého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 16, 'Ale i zmužilého srdce mezi nejudatnějšími nahý utíkati bude v ten den, praví Hospodin.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 1, 'Slyšte slovo to, kteréž mluví Hospodin proti vám, synové Izraelští, proti vší té rodině, kterouž jsem vyvedl z země Egyptské, řka:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 2, 'Toliko vás samy poznal jsem ze všeliké rodiny země, protož trestati vás budu ze všech nepravostí vašich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 3, 'Zdaliž půjdou dva spolu, leč by se snesli?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 4, 'Zdaliž zařve lev v lese, když by nebylo žádné loupeže? Vydá-liž lvíček hlas svůj z peleše své, kdyby lapiti neměl?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 5, 'Padne-liž ptáče do osídla na zem, když by žádné léčky nebylo? Bude-liž zdviženo osídlo z země, když by nic neuvázlo?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 6, 'Zdaliž když se troubí trubou v městě, lid s strachem se nezbíhá? Zdaž když se má státi v městě co zlého, Hospodin toho známa nečiní?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 7, 'Nečiníť zajisté Panovník Hospodin ničeho, leč by zjevil tajemství své služebníkům svým prorokům.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 8, 'Lev řve, kdož by se nebál? Panovník Hospodin velí, kdož by neprorokoval?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 9, 'Rozhlaste po palácích v Azotu, a po palácích v zemi Egyptské, a rcete: Sbeřte se na hory Samaří, a vizte znepokojení veliká u prostřed něho a nátisk trpící v něm,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 10, 'A že neumějí dělati upřímě, dí Hospodin. Poklady skládají z nátisku a loupeže na palácích svých.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 11, 'Protož takto praví Panovník Hospodin: Aj, nepřítel, a to na zemi tuto vůkol, a tenť odejme od tebe sílu tvou, i budou rozchvátáni palácové tvoji.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 12, 'Takto praví Hospodin: Jako když vytrhne pastýř z úst lva dva hnáty aneb kus ucha, tak vytrženi budou synové Izraelští, sedící v Samaří lhostejně na postelích, a na ložcích rozkošných.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 13, 'Slyšte a osvědčte v domě Jákobově, dí Panovník Hospodin, Bůh zástupů,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 14, 'Že v ten den, když Izraele trestati budu pro přestoupení jeho, navštívím také oltáře v Bethel, a odťati budou rohové oltáře, tak že spadnou na zem.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 15, 'A udeřím domem zimním o dům letní, i zahynou domové z kostí slonových, a konec vezmou domové velicí, praví Hospodin.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 4, 1, 'Slyšte slovo toto, ó krávy Bázanské, kteréž jste na horách Samařských, kteréž nátisk činíte chudým, a potíráte nuzné, kteréž říkáte pánům jejich: Přineste, ať pijeme.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 4, 2, 'Přisáhl Panovník Hospodin skrze svatost svou, že aj, dnové jdou na vás, v nichž vezme vás na háky, a potomky vaše na udice rybářské.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 4, 3, 'I vyjdete mezerami, každá tak, jakž stojí, a budete rozhazovati, což na palácích, dí Hospodin.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 4, 4, 'Jdětež do Bethel, a buďtež poběhlci Galgala, rozmnožujte převrácenost, a přinášejte každého jitra oběti své, třetího roku desátky své.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 4, 5, 'A pálíce obět chvály z kvašených věcí, provolejte i oběti dobrovolné, a rozhlaste, poněvadž se vám tak líbí, ó synové Izraelští, dí Panovník Hospodin.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 4, 6, 'A ačkoli já dal jsem vám čistotu zubů po všech městech vašich, totiž nedostatek chleba na všech místech vašich, a však jste se ke mně neobrátili, dí Hospodin.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 4, 7, 'Já také zadržel jsem vám déšť, když ještě tři měsícové byli do žně, a dštil jsem na jedno město, a na druhé město jsem nedštil; jeden díl deštěm svlažen byl, a ten díl, na kterýž nepršelo, uschl.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 4, 8, 'A toulali se dvě i tři města k jednomu městu, aby se napili vody, aniž se napiti mohli, a však jste se neobrátili ke mně, dí Hospodin.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 4, 9, 'Bil jsem vás suchem a rzí; hojnost, kterouž přinášely zahrady vaše a vinice vaše, i fíkoví vaše, i olivoví vaše, pojedly housenky, a však jste se neobrátili ke mně, dí Hospodin.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 4, 10, 'Poslal jsem na vás mor tak jako na Egypt, zbil jsem mečem mládence vaše, v zajetí jsem vydal koně vaše, a učinil jsem, že vstupoval smrad vojsk vašich i v chřípě vaše, a však jste se neobrátili ke mně, dí Hospodin.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 4, 11, 'Podvrátil jsem vás, jako podvrátil Bůh Sodomu a Gomoru, tak že jste byli jako hlavně vychvácená z ohně, vždy však neobrátili jste se ke mně, dí Hospodin.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 4, 12, 'A protož takť učiním, ó Izraeli, a poněvadž takť učiniti míním, připraviž se vstříc Bohu svému, ó Izraeli.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 4, 13, 'Nebo aj, on jest sformovatel hor a stvořitel větrů, a oznamuje člověku, jaké by bylo jeho myšlení; činí z záře jitřní tmu, a šlapá po vysokostech země. Hospodin Bůh zástupů jest jméno jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 1, 'Slyšte slovo toto, kteréž já vynáším proti vám, totiž naříkání nad domem Izraelským.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 2, 'Padneť, aniž více povstane panna Izraelská; opuštěna bude v zemi své, nebude žádného, kdo by jí pozdvihl.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 3, 'Nebo takto praví Panovník Hospodin: V městě, z kteréhož vycházelo tisíc, zůstane sto, v tom pak, z kteréhož vycházelo sto, zůstane deset domu Izraelskému.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 4, 'Nebo takto praví Hospodin domu Izraelskému: Hledejte mne a živi buďte.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 5, 'A nehledejte Bethel, aniž choďte do Galgala, a do Bersabé se nesmýkejte; nebo Galgal jistotně se přestěhuje, a Bethel přijde na nic.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 6, 'Hledejte Hospodina, (a živi buďte, aby nepronikl jako oheň domu Jozefova, a nesehltil, a nebylo by žádného, kdo by uhasil Bethelské,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 7, 'Kteříž proměňují v pelynek soud, a spravedlnosti na zemi zanechávají,)');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 8, 'Toho, kterýž učinil Kuřátka i Oriona, kterýž proměňuje stín smrti v jitro, a den v temnosti noční, kterýž přivolává vody mořské, a vylévá je na svrchek země, jehož jméno jest Hospodin,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 9, 'Kterýž očerstvuje zemdleného proti silnému, tak že zemdlený do pevnosti vchází.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 10, 'Nenávidí trescícího v bráně, a toho, kdož mluví věci pravé, v ohavnosti mají.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 11, 'A protož, proto že loupíte chudého, a břímě obilé béřete od něho, domů z tesaného kamení nastavěli jste, ale nebudete bydliti v nich; vinic výborných naštěpovali jste, ale nebudete píti vína z nich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 12, 'Nebo já vím o mnohých nešlechetnostech vašich a velikých hříších vašich, že trápíte spravedlivého, berouce poctu, a nuzných při v bráně převracíte.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 13, 'Protož rozumný v ten čas mlčeti musí, nebo čas ten zlý jest.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 14, 'Hledejte dobrého a ne zlého, abyste živi byli, a budeť tak Hospodin Bůh zástupů s vámi, jakž pravíte.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 15, 'Mějte v nenávisti zlé, a milujte dobré, a ustanovte v bráně soud; snad Hospodin Bůh zástupů milost učiní ostatkům Jozefovým.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 16, 'Protož takto praví Panovník Hospodin, Bůh zástupů: Po všech ulicích bude kvílení, a na všecky strany zkřiknou: Ouvech, ouvech, a povolají oráče k pláči a kvílení s těmi, kteříž umějí naříkati.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 17, 'Nýbrž i po všech vinicích bude kvílení, když projdu prostředkem tebe, dí Hospodin.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 18, 'Běda těm, kteříž žádají dne Hospodinova. K čemuž jest vám ten den Hospodinův, poněvadž jest tmy a ne světla?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 19, 'Jako když by někdo utíkal před lvem, potkal by se s ním nedvěd; aneb když by všel do domu, a zpolehna rukou svou na stěnu, ušťkl by ho had.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 20, 'Zdali není tmy a ne světla den Hospodinův, v němž není blesku, ale mrákota?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 21, 'Nenávidím, zavrhl jsem svátky vaše, aniž sobě chutnám slavností vašich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 22, 'Nebo budete-li mi obětovati zápaly a suché oběti vaše, neoblíbím jich, a na pokojné oběti krmného dobytka vašeho nepopatřím.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 23, 'Odejmi ode mne hluk písní svých, ani hudby louten vašich nechci poslouchati.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 24, 'Ale povalí se jako voda soud, a spravedlnost jako potok silný.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 25, 'Zdali jste mně oběti a dary obětovali na poušti za čtyřidceti let, dome Izraelský?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 26, 'Nýbrž nosili jste stánek Melecha vašeho a Kijuna, obrazy vaše, hvězdu boha vašeho, kteréžto věci sami jste sobě zdělali.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 27, 'Protož přestěhuji vás dále než Damašské, praví Hospodin, jehož jméno jest Bůh zástupů.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 1, 'Běda pokoj majícím na Sionu, a doufajícím v horu Samařskou, kteréžto hory jsou slovoutné mimo jiné u těch národů, k nimž se scházejí dům Izraelský.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 2, 'Projděte až do Chalne, a odtud jděte do Emat veliké, a sstupte do Gát Filistinských, a shlédněte, jsou-li která království lepší nežli tato? Jest-li větší jejich kraj nežli kraj váš?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 3, 'Kteříž smyslíte, že jest daleko den bídy, a přistavujete stolici nátisku.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 4, 'Kteříž léhají na ložcích slonových, a rozkošně sobě počínají na postelích svých, kteříž jídají berany z stáda a telata nejtučnější,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 5, 'Přizpěvujíce k loutně jako David, vymýšlejíce sobě nástroje muzické.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 6, 'Kteříž pijí z bání vinných, a drahými mastmi se maží, aniž jsou čitelni bolesti pro potření Jozefovo.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 7, 'Pročež jižť půjdou v zajetí v prvním houfu stěhujících se, a tak nastane žalost těm, kteříž sobě rozkošně počínají.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 8, 'Přisáhl Panovník Hospodin skrze sebe samého, dí Hospodin Bůh zástupů: V ohavnosti mám pýchu Jákobovu, i paláců jeho nenávidím, pročež vydám město i vše, což v něm jest.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 9, 'I stane se, že pozůstane-li deset osob v domě jednom, i ti zemrou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 10, 'A vezme někoho strýc jeho, aneb ten, kterýž mu strojí pohřeb, aby vynesl kosti z domu, a dí tomu, kdož jest v pokoji domu: Jest-liž ještě s tebou kdo? I dí: Není žádného. I řekne: Mlč, proto že nepřipomínali jména Hospodinova.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 11, 'Nebo aj, Hospodin přikáže, a bíti bude na dům veliký přívaly, a na dům menší rozsedlinami.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 12, 'Zdaliž koni běžeti mohou po skále? Zdaliž ji kdo orati může voly? Nebo jste proměnili soud v jed, a ovoce spravedlnosti v pelynek,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 13, 'Vy, kteříž se veselíte, ano není z čeho, říkajíce: Zdaliž jsme svou silou nevzali sobě rohů?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 14, 'Ale aj, já vzbudím proti vám, ó dome Izraelský, praví Hospodin Bůh zástupů, národ, kterýž vás ssouží, odtud, kudy se jde do Emat, až do potoka roviny.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 1, 'Toto mi ukázal Panovník Hospodin, že aj, formoval kobylky, když nejprvé počala růsti otava, když aj, otava byla po královském posečení.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 2, 'I stalo se, když snědly byliny zemské, že jsem řekl: Panovníče Hospodine, odpustiž, prosím. Kdož zůstane Jákobovi? Neboť ho maličko jest.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 3, 'I želel Hospodin toho. Nestaneť se, řekl Hospodin.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 4, 'Tedy ukázal mi Panovník Hospodin, a aj, Panovník Hospodin volal, že při svou povede ohněm. A spáliv propast velikou, spálil i díl.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 5, 'Já pak řekl jsem: Panovníče Hospodine, přestaniž, prosím. Kdož zůstane Jákobovi? Neboť ho maličko jest.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 6, 'I želel Hospodin toho. A ani toho se nestane, řekl Panovník Hospodin.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 7, 'Potom ukázal mi, a aj, Pán stál na zdi podlé pravidla vzdělané, v jehož ruce bylo pravidlo.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 8, 'I řekl mi Hospodin: Co vidíš, Amose? Řekl jsem: Pravidlo. I řekl Pán: Aj, já položím pravidlo u prostřed lidu svého Izraelského, nebuduť již více promíjeti jemu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 9, 'Nebo zpuštěny budou výsosti Izákovy, a svatyně Izraelovy zpustnou, tehdáž, když povstanu proti domu Jeroboámovu s mečem.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 10, 'Tedy poslal Amaziáš kněz Bethelský k Jeroboámovi králi Izraelskému, řka: Spuntoval se proti tobě Amos u prostřed domu Izraelského, ta země nemohla by snésti všech slov jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 11, 'Nebo takto praví Amos: Od meče umře Jeroboám, a Izrael jistotně přestěhován bude z země své.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 12, 'Potom řekl Amaziáš Amosovi: Ó vidoucí, ujdi, radímť, utec do země Judské, a jez tam chléb, a tam prorokuj.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 13, 'Ale v Bethel již více neprorokuj, nebo ono svatyně králova i dům královský jest.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 14, 'Tedy odpovídaje Amos, řekl Amaziášovi: Nebylť jsem já prorokem, ano ani synem prorockým, ale byl jsem skotákem, a česával jsem plané fíky.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 15, 'Ale Hospodin mne vzal, když jsem chodil za stádem, a řekl mi Hospodin: Jdi, prorokuj lidu mému Izraelskému.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 16, 'Nyní tedy slyšiž slovo Hospodinovo. Ty pravíš: Neprorokuj v Izraeli, a nekaž v domě Izákově.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 17, 'Protož takto praví Hospodin: Žena tvá cizoložiti bude v městě, synové pak tvoji i dcery tvé od meče padnou; a země tvá provazcem dělena bude, a ty v zemi nečisté umřeš, Izrael pak jistotně přestěhován bude z země své.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 8, 1, 'Také mi ukázal Panovník Hospodin, a aj, byl koš ovoce letního.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 8, 2, 'A řekl: Co ty vidíš, Amose? I řekl jsem: Koš ovoce letního. Opět mi řekl Hospodin: Přišeltě konec lidu mému Izraelskému, nebuduť již více promíjeti jemu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 8, 3, 'Pročež kvíliti budou zpěvové chrámoví v ten den, praví Panovník Hospodin. Množství mrtvých, mlče, namece na všelijaké místo.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 8, 4, 'Slyštež to vy, kteříž sehlcujete chudého, abyste vyhladili nuzné z země,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 8, 5, 'Říkajíce: Skoro-liž pomine novměsíce, abychom prodávali obilé, a sobota, abychom otevřeli obilnice, abychom ujímali efi, a přivětšovali váhy, a faleš provodili vážkami falešnými,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 8, 6, 'Kupujíce za peníze nuzné, a chudého za pár střevíců, nadto abychom plevy obilné prodávali?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 8, 7, 'Přisáhl Hospodin skrze důstojnost Jákobovu: Žeť se nezapomenu na věky na všecky skutky jejich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 8, 8, 'Nad tím-liž by se netřásla i země, a nekvílil by každý, kdož přebývá na ní? Proto-liž by neměla vystoupiti všecka jako potok, a zachvácena i zatopena býti jako potokem Egyptským?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 8, 9, 'Anobrž stane se v ten den, praví Panovník Hospodin, učiním, že slunce zajde o poledni, a uvedu tmy na zemi v jasný den.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 8, 10, 'A proměním svátky vaše v kvílení, a všecky zpěvy vaše v naříkání, a způsobím to, že bude na každých bedrách žíně, a na každé hlavě lysina, a bude v zemi této kvílení jako nad jednorozeným, a poslední věci její jako den hořkosti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 8, 11, 'Aj, dnové jdou, dí Panovník Hospodin, že pošli hlad na zemi, ne hlad chleba, ani žízeň vody, ale slyšení slov Hospodinových,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 8, 12, 'Tak že toulati se budou od moře až k moři, a od půlnoci až na východ běhati, hledajíce slova Hospodinova, však nenajdou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 8, 13, 'V ten čas umdlévati budou panny krásné, ano i mládenci tou žízní,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 8, 14, 'Kteříž přisahají skrze ohavnost Samařskou, a říkají: Živť jest Bůh tvůj, ó Dan, a živa jest cesta Bersabé. I padnou, a nepovstanou více.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 9, 1, 'Viděl jsem Pána, an se postavil na oltáři a řekl: Udeř v makovici, až se zatřesou ty veřeje, a rozetni je všecky od vrchu jejich, ostatek pak mečem zmorduji. Neutečeť žádný z nich, aniž kdo z nich bude, ješto by toho znikl.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 9, 2, 'Byť se pak do země zakopali, i odtud by je ruka má vzala; pakli by vstoupili do nebe, i odtud bych je strhl.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 9, 3, 'A jestliže by se schovali na vrchu Karmele, vyhledám a vezmu je odtud; pakli by se skryli před očima mýma na dně moře, přikáži hadu, aby je i odtud vyhryzl.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 9, 4, 'Pakliť by šli v zajetí před nepřátely svými, i tam přikáži meči, aby je zmordoval; obrátím zajisté oko své proti nim k zlému, a ne k dobrému.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 9, 5, 'Nebo Panovník Hospodin zástupů když se jen dotkne země, rozplývá se, a kvílí všickni přebývající na ní, a vystupuje všecka jako potok, a zatopena bývá jako potokem Egyptským,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 9, 6, 'Kterýž vzdělal na nebesích paláce své, a zástup svůj na zemi sšikoval, kterýž může zavolati vody mořské, a vyliti ji na svrchek země, jehož jméno jest Hospodin.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 9, 7, 'Zdaliž nejste podobni synům Mouřenínů přede mnou, ó synové Izraelovi? dí Hospodin. Zdaliž jsem Izraele nevyvedl z země Egyptské, tak jako Filistinské z Kaftor, a Syrské z Kir?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 9, 8, 'Aj, oči Panovníka Hospodina proti království tomuto hřešícímu, abych je vyhladil se svrchku země, a však nevyhladím docela domu Jákobova, dí Hospodin.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 9, 9, 'Nebo aj, já přikázal jsem, a budu zmítati domem Izraelským mezi všemi národy, tak jako zmítáno bývá na říčici, tak že ani kameníčko nepropadne na zem.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 9, 10, 'Mečem zbiti budou všickni hříšníci z lidu mého, kteříž říkají: Nepřiblížíť se, aniž potká nás to zlé.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 9, 11, 'V ten den zdvihnu stánek Davidův, kterýž klesá, a zahradím mezery jeho, a zbořeniny jeho opravím, a vzdělám jej jako za dnů starodávních,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 9, 12, 'Aby dědili s ostatky Idumejských a se všechněmi národy, nad kterýmiž jest vzýváno jméno mé, dí Hospodin, kterýž to učiní.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 9, 13, 'Aj, dnové jdou, dí Hospodin, že postihati bude oráč žence, a ten, kdož tlačí hrozny, rozsevače, hory pak dštíti budou mstem, a všickni pahrbkové oplývati.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 9, 14, 'Přivedu také zase zajatý lid svůj Izraelský, a vystavějí města zpuštěná, aby v nich bydlili; a budou štěpovati vinice, a píti víno jejich, nadělají i zahrad, a jísti budou ovoce jejich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 9, 15, 'A tak je štípím v zemi jejich, že nebudou vykořeněni více z země své, kterouž jsem dal jim, praví Hospodin Bůh tvůj.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 1, 'Vidění Abdiášovo. Takto praví Panovník Hospodin o zemi Idumejské: Pověst jsme slyšeli od Hospodina, a legáta k národům vyslaného: Nuže, povstaňmež k boji proti ní.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 2, 'Aj, způsobím to, abys byl nejšpatnější mezi národy, a abys byl v náramném pohrdání.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 3, 'Pýcha srdce tvého zklamá tě, ó ty, kterýž bydlíš v rozsedlinách skalních, v převysokém obydlí svém, říkaje v srdci svém: Kdož by mne strhl na zem?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 4, 'Bys pak vysoko udělal jako orlice, nýbrž bys mezi hvězdami položil hnízdo své, i odtud strhnu tě, praví Hospodin.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 5, 'Kterak jsi popléněn? Zdali zloději přišli na tebe? Zdali loupežníci noční? Zdaliž by kradli přes spotřebu svou? Kdyby ti, kteříž zbírají víno, přišli na tebe, zdaž by nepozůstavili aspoň paběrků?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 6, 'Jakť jsou vystiženy věci Ezau, vyhledáni pokladové jeho!');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 7, 'Až ku pomezí vystrčí tě všickni, s kterýmiž smlouvu máš; podvedou tě, zmocní se tebe ti, s nimiž pokoj máš; náchlebníci tvoji udělajíť ránu zrádně, již nebude lze vyrozuměti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 8, 'Zdaliž v ten den, praví Hospodin, nevyhladím moudrých z země Idumejské, a rozumných s hory Ezau?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 9, 'I budou se děsiti udatní tvoji, ó Temane, proto, že poraženi jsouce, vypléněni budou všickni s hory Ezau.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 10, 'Pro nátisk bratru tvému Jákobovi činěný přikryje tě hanba, a vypléněn budeš na věčnost.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 11, 'Stál jsi v ten den naproti, a když zajímali cizí vojsko jeho, a když cizozemci vcházeli do bran jeho, a o Jeruzalém metali losy, ty jsi také byl jako jeden z nich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 12, 'Nedívejž se tedy na den bratra svého, na den zajetí jeho, aniž se vesel nad syny Judskými v den zahynutí jejich, aniž pyšně mluv ústy svými v den úzkosti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 13, 'Nevcházej do brány lidu mého v den bídy jejich, aniž se dívej trápení jeho v den bídy jeho, a nechtěj sahati na statek jeho v den bídy jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 14, 'Aniž stůj při mezeře, abys hubil ty, kteříž z nich ucházejí, aniž vydávej nepříteli v moc těch, kteříž z nich pozůstali v den úzkosti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 15, 'Nebo blízko jest den Hospodinův proti všechněm těm národům. Jakž jsi činil, tak se stane tobě, odplata tvá navrátí se na hlavu tvou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 16, 'Nebo poněvadž vy na mé hoře svaté píti budete, nadtoť píti budou všickni národové ustavičně. Píti, pravím, a požírati budou, až budou, jako by jich nebylo.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 17, 'Na hoře pak Sion bude vysvobození, a bude svatá, a tak dědičně držeti bude dům Jákobův dědictví svá.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 18, 'I bude dům Jákobův oheň, a dům Jozefův plamen, dům pak Ezau plevy, i rozpálí se na ně a sehltí je, aniž kdo pozůstane z domu Ezau; nebo Hospodin mluvil.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 19, 'A tak děditi budou v krajině polední s horou Ezau, i v rovině s Filistinskými; vládnouti také budou krajinou Efraimovou i krajinou Samařskou, a Beniaminovou i Galádskou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 20, 'I zajaté vojsko toto synů Izraelských v tom, což bylo Kananejských až do Sarepty, zajatí pak Jeruzalémští v tom, což jest na konci panství, děditi budou s městy na poledne.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 21, 'I vstoupí vysvoboditelé na horu Sion, aby soudili horu Ezau, a tak bude Hospodinovo království.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 1, 'I stalo se slovo Hospodinovo k Jonášovi synu Amaty, řkoucí:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 2, 'Vstaň, jdi do Ninive města toho velikého, a volej proti němu; neboť jest vstoupila nešlechetnost jejich před oblíčej můj.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 3, 'Ale Jonáš vstal, aby utekl do Tarsu od tváři Hospodinovy. A přišed do Joppe, našel lodí, ana jde do Tarsu, a zaplativ od ní, vstoupil na ni, aby se plavil s nimi do Tarsu od tváři Hospodinovy.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 4, 'Ale Hospodin vzbudil vítr veliký na moři. I stala se bouře veliká na moři, až se domnívali, že se lodí ztroskoce.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 5, 'A bojíce se plavci, volali jeden každý k bohu svému, a vyhazovali to, což měli na lodí, do moře, aby sobě tím polehčili. Jonáš pak byl sešel k bokům lodí, a položiv se, spal tvrdě.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 6, 'Tedy přišed k němu správce lodí, řekl jemu: Což ty děláš, ospalče? Vstaň, volej k Bohu svému. Snad ten Bůh rozpomene se na nás, abychom nezahynuli.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 7, 'I řekli jeden druhému: Poďte, vrzme losy, abychom zvěděli, pro koho to zlé přišlo na nás. Tedy metali losy, a padl los na Jonáše.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 8, 'I řekli jemu: Pověz nám medle, pro koho toto zlé na nás? Jaký jest obchod tvůj, a odkud jdeš? Z které jsi země a z kterého národu?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 9, 'I řekl jim: Hebrejský jsem, a Hospodina Boha nebes, kterýž učinil moře i zemi, já ctím.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 10, 'Pročež báli se ti muži bázní velikou, a dověděvše se muži ti, že od tváři Hospodinovy utíká, (nebo jim byl oznámil,) řekli jemu: Což jsi to učinil?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 11, 'Řekli ještě k němu: Což máme učiniti s tebou, aby se moře spokojilo? (Nebo moře vždy více a více bouřilo se.)');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 12, 'Jimžto řekl: Vezměte mne, a uvrzte mne do moře, a utichne moře před vámi; nebo já vím, že příčinou mou bouře tato veliká jest proti vám.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 13, 'Ale muži ti statečně táhli, chtíce k břehu přistati, však nemohli; nebo moře vždy více a více se bouřilo proti nim.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 14, 'I zvolali k Hospodinu, řkouce: Prosímeť, ó Hospodine, abychom nezahynuli pro smrt člověka tohoto, aniž na nás vyhledávej krve nevinné; nebo ty, ó Hospodine, jakž chceš, tak činíš.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 15, 'Tedy vzavše Jonáše, uvrhli ho do moře. I přestalo moře bouřiti se.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 16, 'Pročež báli se muži ti bázní velikou Hospodina, a obětovali obět Hospodinu, a sliby činili.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 17, 'Nastrojil pak byl Hospodin rybu velikou, aby požřela Jonáše. I byl Jonáš v střevách té ryby tři dni a tři noci.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 2, 1, 'I modlil se Jonáš Hospodinu Bohu svému v střevách té ryby,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 2, 2, 'A řekl: Z ssoužení svého volal jsem k Hospodinu, a ozval se mi; z břicha hrobu křičel jsem, a vyslyšel jsi hlas můj.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 2, 3, 'Nebo jsi mne uvrhl do hlubiny, do prostřed moře, a řeka obklíčila mne; všecka vlnobití tvá i rozvodnění tvá na mne se svalila.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 2, 4, 'Bylť jsem již řekl: Vyhnán jsem od očí tvých, ale ještěť pohledím na tvůj svatý chrám.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 2, 5, 'Obklíčily mne vody až k duši, propast obklíčila mne, lekno otočilo se okolo hlavy mé.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 2, 6, 'Až k spodkům hor dostal jsem se, země závorami svými zalehla mi na věčnost, ty jsi však vysvobodil od porušení život můj, ó Hospodine Bože můj.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 2, 7, 'Když se svírala ve mně duše má, na Hospodina jsem se rozpomínal, i přišla k tobě modlitba má do chrámu svatého tvého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 2, 8, 'Kteříž ostříhají marností pouhých, dobroty Boží se zbavují.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 2, 9, 'Já pak s hlasem díkčinění obětovati budu tobě; což jsem slíbil, splním. Hojné vysvobození jest u Hospodina.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 2, 10, 'Rozkázal pak byl Hospodin rybě té, i vyvrátila Jonáše na břeh.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 3, 1, 'I stalo se slovo Hospodinovo k Jonášovi podruhé, řkoucí:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 3, 2, 'Vstaň, jdi do Ninive města toho velikého, a kaž proti němu to, což já poroučím tobě.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 3, 3, 'Tedy vstav Jonáš, šel do Ninive podlé slova Hospodinova. (Bylo pak Ninive město velmi veliké, cesty tří dnů.)');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 3, 4, 'A jakž počal byl Jonáš jíti po městě cestou dne jednoho a volati, pravě: Po čtyřidcíti dnech Ninive vyvráceno bude,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 3, 5, 'Tedy uvěřili Ninivitští Bohu, a vyhlásivše půst, oblékli se v žíně, od největšího z nich až do nejmenšího z nich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 3, 6, 'Nebo jakž došla ta řeč krále Ninivitského, vstav s trůnu svého, složil s sebe oděv svůj, a přioděv se žíní, seděl v popele.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 3, 7, 'A dal provolati a oznámiti v Ninive z usouzení královského i knížat svých, takto řka: Lidé i hovada, volové i ovce, neokoušejte ničeho, nepaste se, ani vody nepíte.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 3, 8, 'Ale přiodějte se žíněmi lidé i hovada, a volejte k Bohu horlivě, a odvrať se jeden každý od cesty své zlé, i loupeže, kteráž jest v rukou jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 3, 9, 'Kdo ví, neobrátí-li se a nebude-li želeti toho Bůh; neodvrátí-li se, pravím, od prchlivosti hněvu svého, abychom nezahynuli.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 3, 10, 'I viděl Bůh skutky jejich, že se odvrátili od cesty své zlé, a lítost měl Bůh nad tím zlým, kteréž řekl učiniti jim. A neučinil.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 4, 1, 'I mrzelo to Jonáše velmi, a rozpálen byl hněv jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 4, 2, 'Pročež modlil se Hospodinu a řekl: Prosím, Hospodine, zdaliž jsem toho neřekl, když jsem ještě byl v zemi své? Protož jsem pospíšil uteci do Tarsu; nebo jsem věděl, že jsi ty Bůh milostivý a lítostivý, dlouhočekající a hojný v milosrdenství, a kterýž lituješ zlého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 4, 3, 'Nyní tedy, ó Hospodine, vezmi, prosím, duši mou ode mne; nebo lépe jest mi umříti nežli živu býti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 4, 4, 'I řekl Hospodin: Jest-liž to dobře, že tak horlíš?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 4, 5, 'Nebo vyšel byl Jonáš z města, a seděl na východ proti městu, a udělav sobě tu boudu, seděl pod ní v stínu, ažby viděl, co se bude díti s tím městem.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 4, 6, 'Přistrojil pak byl Hospodin Bůh břečtan, kterýž vyrostl nad Jonáše, aby zastěňoval hlavu jeho, a chránil ho před horkem. I radoval se Jonáš z toho břečtanu radostí velikou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 4, 7, 'V tom nazejtří v svitání nastrojil Bůh červa, kterýž ranil ten břečtan, tak že uschl.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 4, 8, 'I stalo se, že když vzešlo slunce, nastrojil Bůh vítr východní žhoucí, a bilo slunce na hlavu Jonášovu, tak že umdléval, a žádal sobě, aby umřel, řka: Lépeť mi jest umříti nežli živu býti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 4, 9, 'I řekl Bůh Jonášovi: Jest-liž to dobře, že se tak hněváš pro ten břečtan? Kterýžto řekl: An dobře jest, že se hněvám až na smrt.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 4, 10, 'Jemuž řekl Hospodin: Ty lituješ toho břečtanu, o němž jsi nepracoval, aniž jsi ho k zrostu přivedl, kterýž za jednu noc zrostl, a jedné noci zahynul,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 4, 11, 'A já abych nelitoval Ninive města tak velikého, v němž jest více nežli sto a dvadceti tisíc lidí, kteříž neznají rozdílu mezi pravicí svou a levicí svou, a dobytka mnoho?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 1, 'Slovo Hospodinovo, kteréž se stalo k Micheášovi Moraštickému za dnů Jotama, Achasa a Ezechiáše králů Judských, kteréž u vidění slyšel o Samaří a Jeruzalému.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 2, 'Slyšte všickni lidé napořád, pozoruj země, i což na ní jest, a nechť jest Panovník Hospodin proti vám svědkem, Panovník z chrámu svatosti své.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 3, 'Nebo aj, Hospodin vyjde z místa svého, a sstoupě, šlapati bude po vysokostech země.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 4, 'I budou se rozplývati hory pod ním, a údolé se roztrhovati, tak jako vosk od ohně, a jako vody mající spád dolů,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 5, 'A to všecko pro Jákobovo zpronevěření, a pro hříchy domu Izraelského. Kdo jest příčina zpronevěření Jákobova? Zdali ne Samaří? A kdo výsostí Judských: Zdali ne Jeruzalém?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 6, 'Protož obrátím Samaří v hromadu rumu, k štípení vinic, a svalím do údolí kamení její, i základy její odkryji.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 7, 'A všecky rytiny její ztlučeny budou, i všickni darové její ohněm spáleni, a všecky modly její obrátím v pustinu. Nebo ze mzdy nevěstčí toho nashromáždila, protož se zase ke mzdě nevěstčí to navrátí.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 8, 'Nad čímž kvíliti a naříkati budu, chodě svlečený a nahý, vydám se v naříkání jako drakové, a v kvílení jako mladé sovy,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 9, 'Proto že zneduživěla od ran svých, a že přišlo to až k Judovi, dosáhlo až k bráně lidu mého, až do Jeruzaléma.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 10, 'Neoznamujtež v Gát, aniž hned plačte; v domě Ofra v prachu se válej.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 11, 'Ty, kteráž bydlíš v Safir, zajdi, obnaženou majíc hanbu. Nevyjdeť ta, kteráž bydlí v Zaanan pro kvílení v Betezel, od vás maje živnost svou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 12, 'Bude, pravím, bolestiti pro dobré věci obyvatelkyně Marót, proto že sstoupí zlé od Hospodina až do brány Jeruzalémské.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 13, 'Zapřáhni do vozu rychlé koně, obyvatelkyně Lachis, kteráž jsi původ hřícha dceři Sionské; nebo v tobě nalezena jsou přestoupení Izraelova.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 14, 'Protož pošleš dary své s Morešet v Gát; domové Achzib zklamají krále Izraelské.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 15, 'Ó obyvatelkyně Maresa, i toběť tudíž přivedu dědice; až do Adulam přijde, k slávě Izraelské.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 16, 'Učiniž sobě lysinu, a ohol se pro syny rozkoší svých; rozšiř lysinu svou jako orlice, nebo stěhují se od tebe.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 2, 1, 'Běda těm, kteříž vymýšlejí nepravost a ukládají zlé na ložcích svých, a na úsvitě ráno vykonávají je, když jest v moci rukou jejich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 2, 2, 'Požádají polí, i vydírají, takž i domů, a odjímají; a tak provozují moc nad mužem i domem jeho, nad jedním každým i dědictvím jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 2, 3, 'Protož takto praví Hospodin: Aj, já myslím proti čeledi té věc zlou, odkudž nevyňmete hrdel vašich, aniž budete choditi vysokomyslně; nebo čas zlý bude.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 2, 4, 'V ten den užívati budou o vás přísloví, a naříkati budou naříkáním žalostným, řkouce: Do cela zpuštěni jsme, podíl lidu mého proměnil. Jaktě mi jej odjal, a vzav pole naše, rozdělil!');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 2, 5, 'Protož nebudeš míti, kdožť by vztáhl provazec na los v shromáždění Hospodinovu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 2, 6, 'Neprorokujte. Budou prorokovati, ale nebudou těmto prorokovati, a neponesou pohanění.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 2, 7, 'Ó kteráž sloveš domem Jákobovým, zdali do těsna vehnán býti má duch Hospodinův? To-liž by skutkové jeho byli? Zdaliž slova má nejsou dobrá tomu, kdož upřímě chodí?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 2, 8, 'Včera byl lidem mým, již jako nepřítel povstává. Majíce oděv, plášť strhujete s těch, kteříž chodí bezpečně, vyhýbajíce se bitvě.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 2, 9, 'Manželky lidu mého vyháníte z domu rozkoší jejich, od dítek jejich odjímáte slávu mou na věky.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 2, 10, 'Vstaňte a odejděte, neboť tato není sídlem pro nečistotu. Ztratí vás, a to ztracením jistým.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 2, 11, 'Jestliže za proroka se vydávaje a lež mluvě, říká: Budu tobě prorokovati o víně aneb o nápoji opojujícím, takový bývá prorokem lidu tohoto.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 2, 12, 'Jistotně zberu tě, Jákobe, docela, jistotně shromáždím ostatky Izraele, a seženu je v hromadu jako ovce v Bozra, jako stádo do prostřed ovčince jeho, i vzejde hluk od lidu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 2, 13, 'Vstoupí ten, kterýž prolamovati bude před nimi. Prolomí, a projdou bránu, a vyjdou skrze ni; ano i král jejich půjde před nimi, a Hospodin na špici jejich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 3, 1, 'Protož pravím: Slyštež již přední v Jákobovi, a vůdcové domu Izraelského: Zdaliž vy nemáte povědomi býti soudu?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 3, 2, 'Nenávidí dobrého a milují zlé, sdírají s lidu kůži jejich, a maso jejich s kostí jejich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 3, 3, 'A jedí maso lidu mého, a kůži jejich s nich svláčejí, i kosti jejich rozlamují, a rozdělují jako do hrnce, a jako maso do kotlíku.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 3, 4, 'Tehdy volati budou k Hospodinu, a nevyslyší jich, ale skryje tvář svou před nimi v ten čas, tak jakž oni vykonávali zlá předsevzetí svá.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 3, 5, 'Takto praví Hospodin o těch prorocích, kteříž v blud uvodí lid můj, a hryzouce zuby svými, vyhlašují pokoj, a proti tomu, kdož by jim nic do úst nedal, válku vyzdvihují.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 3, 6, 'A protož obrátí se vám vidění v noc, a předpovídání vaše v tmu; nebo zajde slunce těm prorokům, a zatmí se jim den.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 3, 7, 'I budou se hanbiti ti vidoucí, a styděti ti věštci, a zastrou bradu svou všickni napořád, proto že nebude žádné odpovědi Boží.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 3, 8, 'Ale já naplněn jsem silou Ducha Hospodinova, a soudem i udatností, abych oznámil Jákobovi zpronevěření jeho, a Izraelovi hřích jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 3, 9, 'Slyštež již toto přední v domě Jákobově, a vůdcové domu Izraelského, kteříž v ošklivosti mají soud, a cožkoli jest pravého, převracejí:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 3, 10, 'Každý vzdělává Sion vraždami, a Jeruzalém nepravostí.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 3, 11, 'Jehož přední podlé darů soudí, a kněží jeho ze mzdy učí, a proroci jeho z peněz hádají, a však na Hospodina zpoléhají, říkajíce: Zdaliž Hospodina není u prostřed nás? Nepřijdeť na nás nic zlého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 3, 12, 'A protož vaší příčinou Sion jako pole orán bude, a Jeruzalém v hromady obrácen bude, a hora domu toho v vysoké lesy.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 4, 1, 'Ale stane se v posledních dnech, že utvrzena bude hora domu Hospodinova na vrchu hor, a vyvýšena nad pahrbky, i pohrnou se k ní národové.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 4, 2, 'A půjdou lidé mnozí, říkajíce: Poďte, a vstupme na horu Hospodinovu, totiž do domu Boha Jákobova, a bude nás vyučovati cestám svým, i budeme choditi po stezkách jeho. Nebo z Siona vyjde zákon, a slovo Hospodinovo z Jeruzaléma.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 4, 3, 'Onť bude souditi mezi národy mnohými, a trestati bude národy silné za dlouhé časy. I skují meče své v motyky, a oštípy své v srpy. Nepozdvihne národ proti národu meče, a nebudou se více učiti boji.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 4, 4, 'Ale seděti bude každý pod vinným kmenem svým, a pod fíkovím svým, a nebude žádného, kdo by přestrašil; nebo ústa Hospodina zástupů mluvila.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 4, 5, 'Všickni zajisté národové choditi budou jeden každý ve jménu boha svého, ale my choditi budeme ve jménu Hospodina Boha našeho na věky věků.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 4, 6, 'V ten den, dí Hospodin, zberu zase kulhavou, a zahnanou shromáždím, i tu, kteréž jsem zle činil.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 4, 7, 'I dám té kulhavé potomky, a pryč zahnané národ silný, a bude kralovati Hospodin nad nimi na hoře Sion od tohoto času až na věky.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 4, 8, 'A tak ty věže bravná, bašto dcery Sionské, až k tobě přijde, přijde, pravím, panování první, a království k dceři Jeruzalémské.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 4, 9, 'Pročež nyní tak velice křičíš? Zdaliž není žádného krále v tobě? Zdali rádce tvůj zahynul, že tě zachvátila bolest jako rodičku?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 4, 10, 'Pracujž ku porodu a úpěj, dcero Sionská, jako rodička; nebo již vyjdeš z města, a budeš bydliti na poli, a přijdeš až do Babylona. Tam vytržena budeš, tam tě vykoupí Hospodin z ruky nepřátel tvých.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 4, 11, 'Sbírajíť se nyní sic proti tobě národové mnozí, říkající: Nechť jest poškvrněn Sion, a nechť se podívají na to oči naše.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 4, 12, 'Však oni neznají myšlení Hospodinových, aniž rozumějí radě jeho, že je shromažďuje jako snopy na humno.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 4, 13, 'Vstaniž a mlať, dcero Sionská; nebo rok tvůj učiním železný, a kopyta tvá učiním ocelivá. I zetřeš národy mnohé, a posvětím Hospodinu jmění jejich, a zboží jejich Pánu vší země.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 5, 1, 'Sbeřiž se nyní po houfích, ó záškodnice, oblehni nás, nechať bijí holí v líce soudce Izraelského.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 5, 2, 'A ty Betléme Efrata, jakžkoli jsi nejmenší mezi tisíci Judskými, z tebe mi vyjde ten, kterýž má býti Panovníkem v Izraeli, a jehož východové jsou od starodávna, ode dnů věčných.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 5, 3, 'Protož, ač je vydá v rozptýlení, ažby ta, kteráž rodí, porodila, však ostatek bratří jeho navrátí se s syny Izraelskými.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 5, 4, 'I stane a pásti bude v síle Hospodinově, a u velebnosti jména Hospodina Boha svého. I budou bydliti, nebo již velikomocný bude až do končin země.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 5, 5, 'I budeť takový pokoj, že když Assur přitáhne do země naší, a šlapati bude po palácích našich, tedy postavíme proti němu sedm pastýřů, a osmero knížat z lidu,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 5, 6, 'Kteříž spasou zemi Assyrskou mečem, a zemi Nimrodovu v pomezích jejích. A tak vytrhne od Assura, když přitáhne do země naší, a šlapati bude po našem pomezí.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 5, 7, 'A protož ostatkové Jákobovi u prostřed národů mnohých budou jako rosa od Hospodina, jako tiší dešťové skrápějící bylinu, jichž neočekává od žádného, aniž čeká od synů lidských.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 5, 8, 'Budou též ostatkové Jákobovi mezi pohany, a u prostřed národů mnohých, jako lev mezi zvěří divokou, jako mladý lev mezi stády ovec. Kterýžto když jde, a pošlapává, i lapá, není žádného, kdo by vytrhl.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 5, 9, 'Vyvýšiť se ruka tvá nad tvými nepřátely, a všickni protivníci tvoji vypléněni budou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 5, 10, 'I stane se v ten den, dí Hospodin, že vypléním koně tvé z prostředku tvého, a zkazím vozy tvé.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 5, 11, 'A vypléním města země tvé, a rozbořím všecky pevnosti tvé.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 5, 12, 'Vypléním též kouzly z tebe, a planetářů nebude v tobě.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 5, 13, 'Zahladím i rytiny tvé, i obrazy tvé z prostředku tvého, a nebudeš se klaněti více dílu rukou svých.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 5, 14, 'Vykořením i háje tvé z prostředku tvého, a zkazím nepřátely tvé.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 5, 15, 'A tak v hněvu a v prchlivosti vykonám pomstu nad těmi národy, kteříž nebyli poslušni.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 6, 1, 'Slyštež nyní, co praví Hospodin: Vstaň, suď se s těmito horami, a nechť slyší pahrbkové hlas tvůj.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 6, 2, 'Slyštež hory rozepři Hospodinovu, i nejpevnější základové země; nebo má rozepři Hospodin s lidem svým, a proti Izraelovi odpor povede.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 6, 3, 'Lide můj, cožť jsem učinil? A čím jsem tě obtěžoval? Vydej svědectví proti mně.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 6, 4, 'Ješto jsem tě vyvedl z země Egyptské, a z domu služebníků vykoupil jsem tě, a poslal jsem před tváří tvou Mojžíše, Arona a Marii.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 6, 5, 'Lide můj, rozpomeň se nyní, jakou radu skládal Balák král Moábský, a co jemu odpovídal Balám syn Beorův, od Setim až do Galgala, abys poznal hojnou spravedlnost Hospodinovu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 6, 6, 'Čímž předejdu Hospodina? Skloniti-liž se mám před Bohem nejvyšším? Předejdu-liž ho zápaly, volky ročními?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 6, 7, 'Zalíbí-liž sobě Hospodin v tisících skopců, v mnohokrát desíti tisících potoků oleje? Dám-liž prvorozeného svého za přestoupení své, plod života svého za hřích duše své?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 6, 8, 'Oznámiltě tobě, ó člověče, co jest dobrého, i čehož Hospodin vyhledává od tebe, jediné, abys činil soud, a miloval milosrdenství, a pokorně chodil s Bohem svým.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 6, 9, 'Hlas Hospodinův na město volá (ale sám rozumný spatřuje jméno tvé,): Slyštež o metle, a kdo ji uložil.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 6, 10, 'Ještě-liž jsou v domě bezbožného pokladové nespravedliví, a míra nespravedlivá a ohavná?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 6, 11, 'Zdaliž ospravedlniti mám vážky nepravé, a v pytlíku kamení falešné?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 6, 12, 'Bohatí jeho plní jsou nátisku, a obyvatelé jeho mluví lež, a jazyk jejich lstivý jest v ústech jejich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 6, 13, 'Pročež i já také nemoc dopustím, bíti a pléniti tě budu pro hříchy tvé.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 6, 14, 'Ty budeš jísti, a nenasytíš se, a snížení tvé bude u prostřed tebe. Vyneseš zajisté, ale neodneseš, a co vyneseš, vydám pod meč.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 6, 15, 'Ty budeš síti, ale nebudeš žíti; ty tlačiti budeš olivky, ale nebudeš se pomazovati olejem, i mest, ale nebudeš píti vína.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 6, 16, 'Nebo snažně ostříhá ustanovení Amri, i každého skutku domu Achabova, a spravujete se radami jejich, tak abych tě vydal v zpuštění, a obyvatele jeho v posměch. A protož pohanění lidu mého ponesete.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 1, 'Běda mně, že jsem jako paběrek úrod letních, jako paběrkové po vinobraní. Není žádného hroznu k jídlu, prvotiny z ovoce žádá duše má.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 2, 'Zahynul pobožný z země této, a upřímého mezi lidmi není žádného; všickni napořád o vylití krve úklady činí, jeden každý bratra svého loví sítí.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 3, 'Co zlého oběma rukama páchají, to aby za dobré počteno bylo. Kníže žádá, a soudce z úplatku soudí, a kdož veliký jest, ten mluví převrácenost duše své, a v hromadu ji pletou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 4, 'Nejlepší z nich jest jako bodlák, nejupřímější převyšuje trní. Přicházíť den strážných tvých, navštívení tvé přichází; jižť nastane zpletení jejich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 5, 'Nedověřujte se příteli, nedoufejte v vůdce; před tou, jenž leží v lůnu tvém, ostříhej dveří úst svých.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 6, 'Nebo syn v lehkost uvodí otce, dcera povstává proti mateři své, nevěsta proti svegruši své, a nepřátelé jednoho každého jsou vlastní jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 7, 'Protož já na Hospodina vyhlédati budu, očekávati budu na Boha spasení svého, vyslyšíť mne Bůh můj.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 8, 'Neraduj se ze mne, nepřítelkyně má. Upadla-liť jsem, povstanu; sedím-liť v temnostech, svítí mi Hospodin.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 9, 'Zůřivost Hospodinovu ponesu, nebo jsem proti němu zhřešila, až se vždy zasadí o mou při, a mne zastane. Vyvedeť mne na světlo, budu viděti spravedlnost jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 10, 'Uzříť to nepřítelkyně má, a přikryje ji hanba, ješto mi říká: Kdež jest Hospodin Bůh tvůj? Oči mé podívají se na ni; jižť bude rozšlapána jako bláto na ulicích.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 11, 'Toho dne, v němž vystaveny budou hradby tvé, toho dne daleko se rozejde výpověd.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 12, 'Toho dne k tobě přicházeti budou i z Assyrské země až do pevností, a od pevností až k řece, a od moře k moři, a od hory k hoře.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 13, 'A však země tato zpuštěna bude pro obyvatele své, pro ovoce činů jejich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 14, 'Pasiž lid svůj berlou svou, stádce dědictví svého, kteréž přebývá osamělé v lese u prostřed polí, ať spasou Bázan a Galád jako za dnů starodávních,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 15, 'Jako za dnů v nichž jsi vyšel z země Egyptské. Ukáži jemu divné věci.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 16, 'Což vidouce národové, styděti se budou za všecku sílu svou; vloží ruku na ústa, a uši jejich ohlechnou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 17, 'Lízati budou prach jako had, a jako hadové zemští s třesením polezou z děr svých; k Hospodinu Bohu našemu, předěšeni jsouce, poběhnou, a báti se tebe budou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 18, 'Kdo jest Bůh silný podobný tobě, kterýž by snímal nepravost a promíjel přestoupení ostatkům dědictví svého, kterýž by nedržel na věky hněvu svého, proto že líbost má v slitování se?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 19, 'Navrátě se, slituje se nad námi, podmaní nepravosti naše; nýbrž uvržeš do hlubin mořských všecky hříchy naše.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 20, 'Pravdomluvným se ukážeš Jákobovi, milosrdným Abrahamovi, jakož jsi přisáhl otcům našim ode dnů starodávních.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 1, 1, 'Břímě Ninive: Kniha vidění Nahuma Elkošského.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 1, 2, 'Hospodin jest Bůh horlivý a mstitel, mstitel jestiť Hospodin, a zůřivý. Hospodin uvodí pomstu na protivníky své, a drží hněv proti nepřátelům svým.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 1, 3, 'Hospodin dlouhočekající jest a velikomocný, však nikoli neospravedlňuje vinného. U vichru a bouři jest cesta Hospodinova, a oblak jest prach noh jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 1, 4, 'Když domlouvá moři, vysušuje je, i všecky řeky vysušuje; chřadne Bázan i Karmel, i květ Libánský chřadne.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 1, 5, 'Hory se třesou před ním, a pahrbkové se rozplývají, země pak hoří před tváří jeho, i okršlek zemský a všickni, kteříž přebývají na něm.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 1, 6, 'Před rozhněváním jeho kdo ostojí? A kdo se postaví proti prchlivosti hněvu jeho? Prchlivost jeho vylévá se jako oheň, a skály vyvracejí se před ním.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 1, 7, 'Dobrýť jest Hospodin, silou jest v den ssoužení, a zná ty, kdož v něho doufají.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 1, 8, 'Protož povodní prudkou konec učiní místu jeho, a nepřátely Boží stihati budou temnosti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 1, 9, 'Co myslíte proti Hospodinu? Onť konec učiní, nezdvihne druhé rány.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 1, 10, 'Nebo rovně jako trní spleteni jsouce, a jako vínem opojeni, jako strniště suché docela sehlceni budou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 1, 11, 'Z tebeť vyšel ten, kterýž myslí proti Hospodinu zlé, rádce nešlechetný.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 1, 12, 'Takto dí Hospodin: Byť se byli pokojně měli, byliť by tak v rozšíření zůstali aneb by toliko přemrštěni byli; i bylo by to pominulo, a netrápil bych jich více, tak jako jsem trápil.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 1, 13, 'Nyní pak polámi jho jeho, aby neleželo na tobě, a to, čímž jsi svázán, roztrhám.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 1, 14, 'Nebo přikázaní vydal proti tobě Hospodin, nebudeť rozsíváno ze jména tvého více; z domu Boha tvého vyhladím rytinu i slitinu, a když zlehčen budeš, způsobímť hrob.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 1, 15, 'Aj hle na horách těchto nohy potěšené věci zvěstujícího, ohlašujícího pokoj. Slaviž, o Judo, slavnosti své, plň sliby své. Neboť nepokusí se více ani mimo tebe choditi nešlechetný, docelať jest vyhlazen.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 2, 1, 'Táhneť zhoubce na tebe, ostříhejž pevnosti, vyhlídej na cestu, posilň bedr, dobře se silou opatř.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 2, 2, 'Neboť jest odjal Hospodin pýchu Jákobovu jako pýchu Izraelovu, proto že vyprázdnili je zhoubcové, a réví jejich pokazili.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 2, 3, 'Pavéza udatných jeho červená, bojovníci červcem odění, vozové jako pochodně hořící jiskřiti budou v den mustruňku jeho, a jedle hrozně třásti se budou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 2, 4, 'Po ulicích jezditi budou vozové, a hrčeti po ryncích; na pohledění budou jako pochodně, a jako blesk pronikati budou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 2, 5, 'Sšikuje nejznamenitější své, klesnou v šiku svém, pospíší ke zdem jeho, a skrýše připravována bude.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 2, 6, 'Brány při řekách se otevrou, chrám se rozplyne.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 2, 7, 'A Hutsab zajata jsuc, zavedena bude, a děvečky její poberou se, lkajíce jako holubice, a tepouce prsy své.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 2, 8, 'A ačkoli jako rybník vod bylo Ninive od začátku svého, však již sami utíkají. Stůjte, stůjte a však žádný se neohlédne.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 2, 9, 'Rozchvátejtež stříbro, rozchvátejte zlato a nesčíslná zboží, a cožkoli nejvzácnějšího na všelikých klénotích drahých.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 2, 10, 'Prázdné a vyprázdněné, nýbrž docela zpuštěné bude, a srdce se rozplyne, a tlučení kolen vespolek i bolest na všech bedrách bude, a tváře všech zčernají jako hrnec.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 2, 11, 'Kdež jest peleš lvů a to pastviště lvíčat, kamž chodíval lev, lev i lvíče, a nebylo žádného, kdo by přestrašil.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 2, 12, 'Lev, kterýž hojně lovíval mladým svým, a dávíval lvicím svým, kterýž naplňoval loupeží jeskyně své, a peleše své tím, což nahonil?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 2, 13, 'Aj, já proti tobě, praví Hospodin zástupů, a popálím na prach vozy tvé, a lvíčata tvá sžíře meč; i vypléním z země loupež tvou, a nebude slyšán více hlas poslů tvých.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 1, 'Běda městu vražednému, kteréž všecko lži a ukrutenství plné jest, neodchází z něho loupež.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 2, 'Praskání bičů a hřmot kol, a dusání koní, a vozů skákání bude.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 3, 'Jezdec vyzdvihne třpytící se meč, a blýskající se kopí, i bude množství zbitých, a veliké hromady těl mrtvých, tak že nebude žádného počtu těl mrtvých, až i padati budou přes těla jejich,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 4, 'Pro množství smilství smilnice, velmi milé, mistryně kouzlů, kteráž prodávala národy smilstvými svými, a lidi kouzly svými.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 5, 'Aj, já proti tobě, dí Hospodin zástupů, a odkryji podolek tvůj nad hlavu tvou, a ukáži národům nahotu tvou, a královstvím hanbu tvou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 6, 'A ukydaje tě ohavnými věcmi, uvedu tě v lehkost, a vystavím tě za divadlo.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 7, 'I stane se, že kdožkoli uzří tě, vzdálí se od tebe, a dí: Vyplundrováno jest Ninive. Kdož by ho litovati měl? Kdež bych shledal ty, kteříž by tě těšiti měli?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 8, 'Což by se tobě lépe díti mělo, nežli No lidnému, kteréž sedělo mezi řekami, vodami byvši opuštěno, jehož val bylo moře, zed mělo od moře?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 9, 'Mouřenínská země i Egypt silou jeho byla, a nesčíslní, Putští a Lubimští, byli jemu na pomoc.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 10, 'A však i to v přestěhování přišlo a v zajetí, tak že i maličcí jeho rozrážíni byli na úhlech všech ulic, a o nejslavnější jeho metali los, a všickni znamenití jeho sevříni byli pouty.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 11, 'Takž i ty opiješ se, a pokrývati se musíš, i ty hledati budeš pomoci proti nepříteli.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 12, 'Všecky tvé pevnosti jsou jako fíkové s ovocem ranním, jimž jakž se zatřese, prší do úst toho, kdož by jedl.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 13, 'Aj, lid tvůj jsou ženy u prostřed tebe, nepřátelům tvým dokořen otevříny budou brány země tvé, a oheň sžíře závory tvé.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 14, 'Navaž sobě vody k obležení, upevni ohrady své, vejdi do bláta a šlapej hlinu, oprav cihelnu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 15, 'Tam tě sžíře oheň, vytne tě meč, sžíře tě jako brouky, nechť jest vás veliký počet jako brouků, nechť jest vás veliký počet jako kobylek.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 16, 'Rozmnožilo jsi kupce své nad hvězdy nebeské, brouci připadnou i zaletují.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 17, 'Znamenití tvoji jako kobylky, a hejtmané tvoji jako velicí chroustové, kteříž se kladou vojensky po plotích v čas studena. Slunce vzešlo, tožť letí, aniž znáti místa jejich, kde byli.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 18, 'Zdřímají pastýři tvoji, ó králi Assyrský, ležeti budou znamenití tvoji, hojnost lidu tvého bude po horách, ale nebude žádného, kdo by shromáždil.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 19, 'K potření tvému není žádného léku, bolest rány tvé rozmohla se. Kteřížkoli uslyší pověst o tobě, rukama plésati budou nad tebou. Nebo na koho ustavičně nedocházelo ukrutenství tvé?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 1, 'Břímě, kteréž u vidění viděl Abakuk prorok.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 2, 'Až dokud, ó Hospodine, křičeti budu, a nevyslyšíš? Volati budu k tobě pro nátisk, a nespomůžeš?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 3, 'Proč dopouštíš, abych hleděti musil na nepravost, a na bezpráví se dívati, též na zhoubu a na nátisk proti mně? A vždy jest, kdož svár a různici vzbuzuje.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 4, 'Odkudž se děje opuštění zákona, a nedochází nikdá soud. Nebo bezbožný obkličuje spravedlivého, pročež vychází soud převrácený.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 5, 'Pohleďte na národy a popatřte, nýbrž s velikým podivením se užasněte, proto že dělám dílo ve dnech vašich, o němž když vypravováno bude, neuvěříte.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 6, 'Nebo aj, já vzbudím Kaldejské, národ lítý a rychlý, kterýž zjezdí všecku širokost země, aby dědičně opanoval příbytky jiných,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 7, 'Strašlivý a hrozný, od něhož soud jeho i vyvýšenost jeho vyjde.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 8, 'Koni jeho rychlejší budou než rysové, a lítější nad vlky večerní; veliké množství bude jezdců jeho, kteřížto jezdci jeho zdaleka přijedou, a přiletí jako orlice, kteráž chvátá na pastvu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 9, 'Každý z nich k utiskování přijde, obrátíce tváři své k východu, když seberou jako písek zajaté.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 10, 'Tentýž i králům se posmívati bude, a knížata smích jemu budou; tentýž každé pevnosti smáti se bude, a zdělaje náspy, dobude jí.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 11, 'Tehdy promění se duch jeho, a přestoupí i zaviní, mysle, že ta moc jeho boha jeho jest.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 12, 'Hospodine Bože můj, Svatý můj, zdaliž ty nejsi od věčnosti? Myť nezemřeme. Hospodine, k soudu postavil jsi jej, ty, ó skálo, k trestání nastrojil jsi ho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 13, 'Čistéť jsou tvé oči, tak že na zlé věci hleděti, a na bezpráví se dívati nemůžeš. Pročež přehlídati máš nešlechetníkům a mlčeti, poněvadž bezbožník sehlcuje spravedlivějšího, než sám jest.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 14, 'A zanechávati lidí jako ryb mořských, jako zeměplazu, kterýž nemá pána?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 15, 'Všecky napořád udicí vytahuje, zatahuje je sítí svou, a zahrnuje je nevodem svým, protož veselí se a pléše.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 16, 'Protož síti své obětuje, a kadí nevodu svému; nebo skrze ně ztučněl díl jeho, a strava jeho zlepšena.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 17, 'S tím-liž se vším předce zatahovati má sít svou, a ustavičně národy mordovati bez lítosti?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 1, 'Na stráži své státi budu, a postavím se na baště, vyhlédaje, abych viděti mohl, co mluviti bude ke mně Bůh, a co bych odpovídati měl po svém trestání.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 2, 'I odpověděl mi Hospodin, a řekl: Napiš vidění, a to zřetelně na dskách, aby je přeběhl čtenář,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 3, 'Proto že ještě do jistého času bude vidění, a směle mluviti bude až do konce, a nesklamáť. Jestliže by pak poprodlilo, posečkej na ně; neboť jistotně dojde, aniž bude meškati.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 4, 'Aj ten, kdož se zpíná, tohoť duše není upřímá v něm, ale spravedlivý z víry své živ bude.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 5, 'Ovšem pak více opilec, nešlechetnost a pýchu provodě, neostojí v příbytku; kterýž rozšiřuje jako peklo duši svou, jest jako smrt, kteráž se nemůže nasytiti, byť pak shromáždil k sobě všecky národy, a shrnul k sobě všecky lidi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 6, 'Zdaliž všickni ti proti němu přísloví nevynesou, a světlých slov i pohádek o něm? A neřeknou-liž: Běda tomu, kterýž rozmnožuje věci ne své, (až dokud pak?) a obtěžuje se hustým blátem?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 7, 'Zdaliž nepovstanou rychle, kteříž by tě hryzli, a neprocítí, kteříž by tebou smýkali? A budeš u nich v ustavičném potlačení.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 8, 'Proto že jsi ty zloupil národy mnohé, zloupí tě všickni ostatkové národů, pro krev lidskou, a nátisk země a města, i všech, kteříž přebývají v něm.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 9, 'Běda tomu, kdož lakomě hledá mrzkého zisku domu svému, aby postavil na místě vysokém hnízdo své, a tak znikl nebezpečenství.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 10, 'Uradils se k hanbě domu svému, abys plénil národy mnohé, a zhřešil sobě samému.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 11, 'Nebo kamení ze zdi křičeti bude, a suk z dřeva posvědčovati bude toho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 12, 'Běda tomu, kterýž staví město krví, a utvrzuje město nepravostí.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 13, 'Aj, zdaliž to není od Hospodina zástupů, že, o čemž pracují lidé a národové až do ustání nadarmo, oheň zkazí.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 14, 'Nebo naplněna bude země známostí slávy Hospodinovy, jako vody naplňují moře.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 15, 'Běda tomu, kterýž napájí bližního svého, přičiněje nádoby své, tak aby jej opojil, a díval se na jeho nahotu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 16, 'Sytíš se potupou, proto že jsi slavný. Píti budeš i ty, a obnažen budeš; obejdeť k tobě kalich pravice Hospodinovy, a vývratek mrzutý na slávu tvou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 17, 'Nebo nátisk Libánu a zhouba zvěři, kteráž ji děsila, přikryje tě, pro krev lidskou, a nátisk země a města, i všech, kteříž přebývají v něm.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 18, 'Co prospívá rytina, že ji vyryl řemeslník její? Slitina i učitel lži, že doufá učinitel v účinek svůj, dělaje modly němé?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 19, 'Běda tomu, kterýž říká dřevu: Prociť, a kameni němému: Probuď se. On-liž by učiti mohl? Pohleď na něj. Obloženť jest zlatem a stříbrem, ale není v něm žádného ducha.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 20, 'Hospodin pak v chrámě svatosti své jest, umlkniž před oblíčejem jeho všecka země.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 1, 'Modlitba Abakuka proroka podlé Šigejonót:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 2, 'Ó Hospodine, uslyšev pohrůžku tvou, ulekl jsem se. Hospodine, dílo své u prostřed let při životu zachovej, u prostřed let známé učiň, v hněvě na milosrdenství se rozpomeň.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 3, 'Když se Bůh bral od poledne, a Svatý s hory Fáran, Sélah, slávu jeho přikryla nebesa, a země byla plná chvály jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 4, 'Blesk byl jako světlo, rohy po bocích svých měl, a tu skryta byla síla jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 5, 'Před tváří jeho šlo morní nakažení, a uhlí řeřavé šlo před nohama jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 6, 'Zastavil se, a změřil zemi; pohleděl, a rozptýlil národy. Zrozrážíny jsou hory věčné, sklonili se pahrbkové věční, cesty jeho jsou věčné.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 7, 'Viděl jsem, že stanové Chusan jsou pouhá marnost, a třásli se kobercové země Madianské.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 8, 'Zdaliž se na řeky, ó Hospodine, zdaliž se na řeky rozpálil hněv tvůj? Zdali proti moři rozhněvání tvé, když jsi jel na koních svých a na vozích svých spasitelných?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 9, 'Patrně jest zjeveno lučiště tvé pro přísahy pokolením lidu tvého stalé, Sélah. Řeky země jsi rozdělil,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 10, 'Viděly tě hory, třásly se, povodeň vod ustoupila; vydala propast hlas svůj, hlubina rukou svých pozdvihla.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 11, 'Slunce a měsíc v obydlí svém zastavil se, při světle střely tvé létaly, při blesku stkvoucí kopí tvé.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 12, 'V hněvě šlapal jsi zemi, v prchlivosti mlátil jsi pohany.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 13, 'Vyšel jsi k vysvobození lidu svého, k vysvobození s pomazaným svým; srazil jsi hlavu s domu bezbožníka až do hrdla, obnaživ základ. Sélah.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 14, 'Holemi jeho probodl jsi hlavu vsí jeho, když se bouřili jako vichřice k rozptýlení mému, plésali, jako by sežrati měli chudého v skrytě.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 15, 'Bral jsi se po moři na koních svých, skrze hromadu vod mnohých.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 16, 'Slyšel jsem, a zatřáslo se břicho mé, k hlasu tomu drkotali rtové moji, kosti mé práchnivěly, a všecken jsem se třásl, že se mám upokojiti v den ssoužení, když přitáhne na lid, aby jej válečně hubil.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 17, 'Byť pak fík nekvetl, a nebylo úrody na vinicích; byť i ovoce olivy pochybilo, a rolí nepřinesla užitky; a od ovčince odřezován byl brav, a nebylo žádného skotu v chlévích:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 18, 'Já však v Hospodinu veseliti se budu, plésati budu v Bohu spasení svého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 19, 'Hospodin Panovník jest síla má, kterýž činí nohy mé jako laní, a na vysokých místech mých cestu mi způsobuje. Přednímu zpěváku na můj neginot.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 1, 'Slovo Hospodinovo, kteréž se stalo k Sofoniášovi synu Chusi, syna Godoliášova, syna Amariášova, syna Ezechiášova, za dnů Joziáše syna Amonova, krále Judského.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 2, 'Zajisté že sklidím všecko se svrchku té země, praví Hospodin.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 3, 'Sklidím lidi i hovada, sklidím ptactvo nebeské i ryby mořské, i pohoršení s bezbožnými; vypléním, pravím, lidi se svrchku této země, praví Hospodin.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 4, 'Nebo vztáhna ruku svou na Judu a na všecky obyvatele Jeruzalémské, zahladím z místa tohoto ostatek Bále, i kněží jeho s jich pomocníky,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 5, 'I ty, kteříž se klanějí na střechách vojsku nebeskému, i ty, kteříž klanějíce se, přisahají skrze Hospodina, i ty, kteříž přisahají skrze Melecha svého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 6, 'I ty, kteříž zpět odcházejí, aby nenásledovali Hospodina, a kteříž nehledají Hospodina, aniž se ho dotazují.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 7, 'Umlkni před oblíčejem Panovníka Hospodina, nebo blízký jest den Hospodinův; přistrojil zajisté Hospodin obět, povolal pozvaných svých.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 8, 'I stane se v den oběti Hospodinovy, že navštívím knížata a syny královy i všecky, kteříž se obláčejí v roucho cizozemců.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 9, 'Navštívím v ten den i každého, kterýž vskakuje na prah, kteříž naplňují dům pánů svých nátiskem a lstí.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 10, 'I stane se v ten den, praví Hospodin, hlas křiku od brány rybné, a kvílení od druhé strany a třeskot veliký od pahrbků.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 11, 'Kvělte vy, kteříž bydlíte u vnitřku; nebo vyhlazen bude všecken obor kupců, vypléněni budou všickni snášející stříbro.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 12, 'I stane se v ten čas, že přehledávati budu Jeruzalém s lucernami, a navštívím muže, kteříž ulnuli v kvasnicích svých, kteříž říkají v srdci svém: Nečiníť dobře Hospodin, aniž zle činí.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 13, 'Nebo přijde statek jejich na rozchvátání, a domové jejich na zpuštění. Stavějí zajisté domy, ale nebudou v nich bydliti; a štěpují vinice, ale nebudou píti vína z nich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 14, 'Blízký jest den Hospodinův veliký, blízký jest a rychlý velmi zvuk dne Hospodinova, tuť hořce křičeti bude udatný.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 15, 'Den rozhněvání bude ten den, den úzkosti a trápení, den zpuštění a to hrozného, den temnosti a mračna, den oblaku a mrákoty,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 16, 'Den trouby a troubení proti městům hrazeným, a proti úhlům vysokým,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 17, 'V němž úzkostmi sevru lidi, aby chodili jako slepí, nebo proti Hospodinu zhřešili. I vylita bude krev jejich jako prach, a těla jejich jako lejna.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 18, 'Ani stříbro jejich, ani zlato jejich nebude jich moci vytrhnouti v den rozhněvání Hospodinova; nebo ohněm horlivosti jeho sehlcena bude tato všecka země, proto že konec jistě rychlý učiní všechněm obyvatelům země.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 2, 1, 'Ohledejte sebe, ohledejte, pravím, ó národe nemilý,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 2, 2, 'Prvé než uložení přijde, a den jako plevy pomine, prvé než přijde na vás prchlivost hněvu Hospodinova, prvé než přijde na vás den hněvu Hospodinova.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 2, 3, 'Hledejte Hospodina všickni tiší země, kteříž soud jeho činíte; hledejte spravedlnosti, hledejte tichosti. Snad se ukryjete v den hněvu Hospodinova.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 2, 4, 'Nebo Gáza bude opuštěno, a Aškalon zpustne; Azot o polednách zaženou, a Akaron vykořeněn bude.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 2, 5, 'Běda těm, kteříž bydlí v krajině pomořské, národu Ceretejských. Slovo Hospodinovo proti vám jest, ó země Kananejská Filistinských, že tě tak zahladím, aby nebylo žádného obyvatele.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 2, 6, 'I bude krajina pomořská místo ovčinců, jam pastýřských a stájí dobytka.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 2, 7, 'Bude také i ostatku domu Judského krajinou, kdež by pásli. V domích Aškalonu u večer léhati budou, když je navštíví Hospodin Bůh jejich, a přivede zase zajaté jejich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 2, 8, 'Slyšelť jsem hanění Moábských a utrhání synů Ammonitských, kterýmiž haněli můj lid, a honosili se na pomezí jejich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 2, 9, 'Protož živ jsem já, praví Hospodin zástupů, Bůh Izraelský, že Moáb jako Sodoma bude, a synové Ammonitští jako Gomora, místem kopřiv a domem solným a pustinou až na věky. Ostatkové lidu mého rozchvátají je, a pozůstalí z lidu mého dědičně je obdrží.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 2, 10, 'To jim pro pýchu jejich, že zhaněli a zpínali se nad lid Hospodina zástupů.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 2, 11, 'Hrozný jim bude Hospodin; nebo způsobí, aby zhubeněli všickni bohové země. I bude se jemu klaněti každý z místa svého, všickni ostrovové národu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 2, 12, 'Také i vy, Mouřenínové, mečem mým zbiti budete.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 2, 13, 'Nebo vztáhne ruku svou na půlnoci, a zhubí Assyrii, a obrátí Ninive v pustinu, a v suchost jako poušť.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 2, 14, 'I budou u prostřed něho léhati stáda, všecky šelmy národů, pelikán i výr na makovicích jeho nocovati budou; hlas zníti bude na okně, pustina na veřeji, když cedroví jeho obnaží.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 2, 15, 'Takovéť bude to město plésající, kteréž sedí bezpečně, říkaje v srdci svém: Já jsem, a kromě mne není žádného více. Jakť jest učiněno pusté, peleší šelmám! Kdožkoli půjde skrze ně, ckáti bude a zmítati rukou svou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 1, 'Běda městu tomuto hltavému a poškvrněnému a utiskujícímu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 2, 'Neposlouchá hlasu, aniž přijímá kázně; v Hospodina nedoufá, k Bohu svému nepřibližuje se.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 3, 'Knížata jeho jsou u prostřed něho lvové řvoucí, soudcové jeho vlci večerní, nehryzou kostí až do rána.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 4, 'Proroci jeho kvapní, muži velmi nešlechetní; kněží jeho poškvrňují věci svaté, natahují zákona.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 5, 'Hospodin spravedlivý u prostřed něho jest, nelibuje nepravosti, každého dne soud svůj vynáší na světlo bez přestání, a však nešlechetník neumí se styděti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 6, 'Vyplénil jsem národy, zpustli zámkové jejich, v pustinu obrátil jsem ulice jejich, tak že žádný přes ně nechodí; zpustla města jejich, tak že není člověka, není žádného obyvatele.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 7, 'Řekl jsem: Jistotně báti se mne budeš, přijmeš kázeň, aby nebyl vypléněn příbytek tvůj tím, čím jsem tě navštíviti chtěl. Ale ráno vstanouce, porušují všecky snažnosti své.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 8, 'Protož očekávejtež na mne, praví Hospodin, do dne toho, v kterémž povstanu k loupeži. Nebo soud můj jest, abych sebral národy, shromáždil království, abych vylil na ně rozhněvání své a všecku prchlivost hněvu svého; ohněm zajisté horlivosti mé sehlcena bude všecka tato země.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 9, 'Tehdáž zajisté způsobím národům rty čisté, jimiž by vzývali všickni jméno Hospodinovo, a sloužili jemu jedním ramenem.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 10, 'Ti, kteříž jsou za řekami Mouřenínské země, koříce se mi, se dcerou rozptýlených mých dary mi přinesou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 11, 'V ten den nebudeš se hanbiti za žádné skutky své, jichž jsi se dopustil proti mně; nebo tehdáž odejmu z prostředku tvého ty, kteříž pléší v důstojnosti tvé, a nebudeš se více vyvyšovati na hoře svatosti mé.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 12, 'A pozůstavím u prostřed tebe lid chudý a nuzný, i budou doufati ve jménu Hospodinovu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 13, 'Ostatkové Izraele neučiní nepravosti, aniž mluviti budou lži, aniž se nalezne v ústech jejich jazyk lstivý, ale pásti se budou a odpočívati, a nebude žádného, kdo by je přestrašil.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 14, 'Prozpěvuj, dcero Sionská, prokřikujte, Izraelští, vesel se a plésej vším srdcem, dcero Jeruzalémská,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 15, 'Že odjal Hospodin soudy tvé, odklidil nepřítele tvého. Král Izraelský Hospodin jest u prostřed tebe, nebudeš se báti více zlého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 16, 'V ten den bude řečeno Jeruzalému: Neboj se, a Sionu: Nechť nemdlejí ruce tvé.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 17, 'Hospodin Bůh tvůj u prostřed tebe mocný zachová tě, radovati se bude z tebe velice, přestane na milování svém tebe, plésati bude nad tebou s prozpěvováním, řka:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 18, 'Toužící po Jeruzalému zase sberu, z tebeť jsou, bolestící pro břímě pohanění vzložené na tebe.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 19, 'Aj, já konec učiním všechněm, kteříž tě trápiti budou v ten čas, a zachovám kulhavou, a zahnanou shromáždím; nýbrž způsobím jim chválu a jméno po vší zemi, v níž pohanění nesli.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 20, 'V ten čas přivedu vás, v ten čas, pravím, shromáždím vás; nebo dám vám jméno a chválu mezi všemi národy země, když zase přivedu zajaté vaše před očima vašima, dí Hospodin.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 1, 1, 'Léta druhého Daria krále, měsíce šestého, prvního dne téhož měsíce, stalo se slovo Hospodinovo skrze Aggea proroka k Zorobábelovi synu Salatielovu, knížeti Judskému, a k Jozue synu Jozadakovu, knězi nejvyššímu, řkoucí:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 1, 2, 'Takto dí Hospodin zástupů, řka: Lid tento praví, že nepřišel čas, čas, v němž by dům Hospodinův staven byl.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 1, 3, 'Pročež stalo se slovo Hospodinovo skrze Aggea proroka, řkoucí:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 1, 4, 'Jest-liž vám čas, abyste vy seděli v domích svých taflovaných, a dům tento pustý stál?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 1, 5, 'Protož nyní takto praví Hospodin zástupů: Přiložte srdce své k cestám svým.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 1, 6, 'Sejete mnoho, a shromažďujete málo; jíte, ale nebýváte nasyceni; pijete, ale neuhašujete žízně; obláčíte se, ale žádný nemůže se zahříti; a ten, kdož sobě mzdu shromažďuje, shromažďuje ji do pytlíka děravého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 1, 7, 'Takto praví Hospodin zástupů: Přiložte srdce své k cestám svým.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 1, 8, 'Vstupte na tuto horu, a svezouce dříví, stavějte dům tento, i oblíbím sobě to, a budu oslaven, praví Hospodin.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 1, 9, 'Patříte na mnoho, a aj, maličko jest, a což vnášíte do domu, já to rozdmychuji. Proč se to děje? dí Hospodin zástupů. I pro dům můj, že pustý jest, ješto vy jeden každý pečlivi jste o dům svůj.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 1, 10, 'Protož zavřelo se nebe nad vámi, aby nedávalo rosy, země také zavřela se, aby nevydávala úrody své.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 1, 11, 'A tak zavolal jsem sucha na zemi tuto, a na tyto hory, i na obilé, i na víno, a na olej, i na to, což by měla vydávati země, i na lidi, i na dobytek, i na všecku práci rukou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 1, 12, 'I uposlechl Zorobábel syn Salatielův, a Jozue syn Jozadakův, kněz nejvyšší, i všickni ostatkové lidu hlasu Hospodina Boha svého, a slov Aggea proroka, poněvadž jej poslal Hospodin Bůh jejich; nebo se bál lid tváři Hospodinovy.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 1, 13, 'Tedy Aggeus posel Hospodinův mluvil lidu v poselství Hospodinovu, řka: Já s vámi jsem, praví Hospodin.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 1, 14, 'V tom vzbudil Hospodin ducha Zorobábele syna Salatielova, knížete Judského, a ducha Jozue syna Jozadakova, kněze nejvyššího, a ducha ostatků všeho lidu, a přišedše, dělali dílo v domě Hospodina zástupů, Boha svého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 1, 15, 'Dne dvadcátého čtvrtého, měsíce šestého, léta druhého Daria krále.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 1, 'Měsíce sedmého, dvadcátého prvního dne téhož měsíce, stalo se slovo Hospodinovo skrze Aggea proroka, řkoucí:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 2, 'Mluv nyní k Zorobábelovi synu Salatielovu, knížeti Judskému, a Jozue synu Jozadakovu, knězi nejvyššímu, i k ostatkům lidu, řka:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 3, 'Kdo jest mezi vámi pozůstalý, ješto viděl dům ten v slávě jeho první? A jaký vy jej nyní vidíte? Zdaliž není proti onomu jako nic před očima vašima?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 4, 'A však nyní posilň se Zorobábeli, praví Hospodin, posilň se i Jozue synu Jozadakův, kněže nejvyšší, a posilň se všecken lide země této, praví Hospodin, a dodělejte; nebo já s vámi jsem, praví Hospodin zástupů,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 5, 'Podlé slova, jímž jsem smlouvu učinil s vámi, když jste vycházeli z Egypta. Duch také můj stane u prostřed vás, nebojtež se.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 6, 'Nebo takto praví Hospodin zástupů: Po malém času, aj, já ještě jednou pohnu nebem i zemí, a mořem i suchostí.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 7, 'Pohnu, pravím, všemi národy, a přijdou k Žádoucímu všechněm národům, i naplním dům tento slávou, praví Hospodin zástupů.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 8, 'Méť jest stříbro a mé jest zlato, praví Hospodin zástupů.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 9, 'Větší bude sláva domu tohoto posledního, než onoho prvního, praví Hospodin zástupů; nebo na tomto místě způsobím pokoj, praví Hospodin zástupů.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 10, 'Dvadcátého čtvrtého dne, devátého měsíce, léta druhého Daria, stalo se slovo Hospodinovo skrze Aggea proroka, řkoucí:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 11, 'Takto praví Hospodin zástupů: Vzeptej se nyní kněží na zákon, řka:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 12, 'Ej, kdyby někdo nesl maso svaté v křídle sukně své, aneb dotkl by se křídlem svým chleba, neb vaření, neb vína, neb oleje, neb jakéžkoli krmě, zdali bude posvěcen? I odpověděli kněží a řekli: Nikoli.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 13, 'Tedy řekl Aggeus: Jestliže někdo jsa nečistý od těla mrtvého, dotkl by se něčeho z těch věcí, bude-li nečisté? I odpověděli kněží a řekli: Nečisté bude.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 14, 'Tedy odpovídaje Aggeus, řekl: Tak lid tento a tak národ tento před tváří mou, praví Hospodin, a tak všecko dílo rukou jejich, i cožkoli obětovali tam, nečisté bylo.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 15, 'Nyní tedy přiložte medle srdce své od tohoto dne až do onoho, jakž přestal kladen býti kámen na kameni v domě Hospodinově,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 16, 'Od toho času, když přišel někdo k hromadě dvadcíti, bylo jen deset; když přišel k kádi, aby nabral padesáte z presu, bylo jen dvadcet.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 17, 'Bil jsem vás suchem a rzí, i krupobitím všecko dílo rukou vašich, však žádný z vás neobrátil se ke mně, praví Hospodin.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 18, 'Přiložte již srdce své od tohoto dne až do onoho, ode dne dvadcátého čtvrtého, měsíce devátého, až do dne, v kterémž založen byl chrám Hospodinův, (přiložte srdce své).');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 19, 'Zdali již jest semeno v obilnici? Anobrž ani vinný kmen, ani fík, ani strom jablek zrnatých, ani strom olivový nevydal ovoce. Od tohoto dne požehnám.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 20, 'Potom stalo se slovo Hospodinovo po druhé k Aggeovi, dvadcátého čtvrtého dne téhož měsíce, řkoucí:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 21, 'Mluv k Zorobábelovi knížeti Judskému, řka: Já pohnu nebem i zemí,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 22, 'A podvrátím stolici království, a zkazím sílu království pohanských; podvrátím, pravím, vůz i ty, kteříž na něm jezdí, a sejdou koni i jezdci jejich jeden každý od meče bratra svého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 23, 'V ten den, praví Hospodin zástupů, vezmu tebe, Zorobábeli synu Salatielův, služebníče můj, praví Hospodin, a učiním tě jako pečetní prsten; nebo jsem tě vyvolil, praví Hospodin zástupů.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 1, 'Měsíce osmého, léta druhého Dariova, stalo se slovo Hospodinovo k Zachariášovi synu Barachiáše, syna Iddova, proroku, řkoucí:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 2, 'Rozhněval se Hospodin na otce vaše velice.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 3, 'Protož rci těmto: Takto praví Hospodin zástupů: Navraťte se ke mně, praví Hospodin zástupů, a navrátím se k vám, praví Hospodin zástupů.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 4, 'Nebuďte jako otcové vaši, na něž volávali proroci onino předešlí, říkajíce: Takto praví Hospodin zástupů: Navraťte se nyní od cest svých zlých, i od skutků vašich zlých, ale neuposlechli, ani pozorovali mne, praví Hospodin.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 5, 'Otcové vaši kde jsou? A proroci ti zdali na věky živi jsou?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 6, 'Ale však slova má a soudové moji, kteréž jsem přikázal služebníkům svým prorokům, zdali nepostihli otců vašich? tak že obrátivše se, řekli: Jakž uložil Hospodin zástupů učiniti nám podlé cest našich, a podlé skutků našich, tak učinil nám.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 7, 'Dne čtyřmecítmého, jedenáctého měsíce, kterýž jest měsíc Šebat, léta druhého Dariova, stalo se slovo Hospodinovo k Zachariášovi synu Barachiáše, syna Iddova, proroku, řkoucí:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 8, 'Viděl jsem v noci, a aj, muž sedí na koni ryzím, kterýž stál mezi myrtovím, kteréž bylo v dolině, za ním pak koně ryzí, strakaté a bílé.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 9, 'I řekl jsem: Kdo jsou tito, Pane můj? Řekl mi anděl ten, kterýž mluvil se mnou: Já ukáži tobě, kdo jsou tito.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 10, 'Tedy odpovídaje muž ten, kterýž stál mezi myrtovím, řekl: Tito jsou, kteréž poslal Hospodin, aby zchodili zemi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 11, 'I odpověděli andělu Hospodinovu tomu, kterýž stál mezi myrtovím, a řekli: Zchodili jsme zemi, a aj, všecka země bezpečně bydlí, a pokoje užívá.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 12, 'Tedy odpověděl anděl Hospodinův a řekl: Ó Hospodine zástupů, až dokudž ty se nesmiluješ nad Jeruzalémem a nad městy Judskými, na kteréž jsi hněval se již sedmdesáte let?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 13, 'I odpověděl Hospodin andělu tomu, kterýž mluvil se mnou, slovy dobrými, slovy potěšitelnými.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 14, 'Tedy řekl mi anděl, kterýž mluvil ke mně: Volej a rci: Takto praví Hospodin zástupů: Horlím pro Jeruzalém a Sion horlením velikým.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 15, 'A hněvám se náramně na ty národy, kteříž mají pokoj; nebo když jsem já se málo rozhněval, oni pomáhali k zlému.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 16, 'Protož takto praví Hospodin: Navrátil jsem se k Jeruzalému milosrdenstvím, dům můj staven bude v něm, praví Hospodin zástupů, a pravidlo vztaženo bude na Jeruzalém.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 17, 'Ještě volej a rci: Takto praví Hospodin zástupů: Ještěť se rozsadí města má pro hojnost dobrého; neboť utěší ještě Hospodin Sion, a vyvolí ještě Jeruzalém.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 18, 'Tedy pozdvihl jsem očí svých, a uzřel jsem, a aj, čtyři rohové.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 19, 'I řekl jsem andělu, kterýž mluvil se mnou: Co jest toto? I řekl mi: To jsou ti rohové, kteříž zmítali Judou, Izraelem a Jeruzalémem.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 20, 'Ukázal mi také Hospodin čtyři kováře.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 21, 'I řekl jsem: Co jdou dělati tito? I mluvil, řka: Tito jsou rohové, kteříž zmítali Judou, tak že žádný nemohl pozdvihnouti hlavy své. Protož přišli tito, aby je přestrašili, a srazili rohy těch národů, kteříž pozdvihli rohu proti zemi Judské, aby ní zmítali.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 2, 1, 'Opět pozdvihl jsem očí svých, a uzřel jsem, a aj muž, v jehož ruce byla šnůra míry.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 2, 2, 'I řekl jsem: Kam jdeš? I řekl mi: Měřiti Jeruzaléma, abych viděl, jak veliká širokost jeho, a jak veliká dlouhost jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 2, 3, 'A aj, když anděl ten, kterýž mluvil se mnou, vycházel, jiný anděl vycházel jemu vstříc.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 2, 4, 'A řekl jemu: Běž, mluv k mládenci tomu, řka: Po vsech bydliti budou Jeruzalémští, pro množství lidu a dobytka u prostřed něho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 2, 5, 'A já budu, praví Hospodin, jeho zdí ohnivou vůkol, a slávou budu u prostřed něho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 2, 6, 'Nuže, nuže, utectež již z země půlnoční, praví Hospodin, poněvadž se čtyř stran světa volný průchod učinil jsem vám, praví Hospodin.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 2, 7, 'Nuže, Sione, kterýž přebýváš u dcery Babylonské, vydobuď se.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 2, 8, 'Nebo takto praví Hospodin zástupů: Po slávě poslal mne proti národům těm, kteříž zloupili vás; nebo kdož se dotýká vás, dotýká se zřítelnice oka mého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 2, 9, 'Nebo aj, já zdvihnu ruku svou proti nim, a budou loupež služebníkům svým, i zvíte, že Hospodin zástupů poslal mne.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 2, 10, 'Prozpěvuj a vesel se, dcero Sionská; nebo aj, já přijdu a budu bydliti u prostřed tebe, praví Hospodin.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 2, 11, 'I připojí se národové mnozí k Hospodinu v ten den, a budou mým lidem, a budu bydliti u prostřed tebe, i zvíš, že Hospodin zástupů poslal mne k tobě.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 2, 12, 'Tehdy dědičně ujme Hospodin Judu, díl svůj, v zemi svaté, a vyvolí zase Jeruzalém.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 2, 13, 'Umlkniž všeliké tělo před oblíčejem Hospodinovým, neboť procítí z příbytku svatosti své.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 3, 1, 'Potom mi ukázal Jozue kněze nejvyššího, stojícího před andělem Hospodinovým, a satana stojícího po pravici jeho, aby se mu protivil.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 3, 2, 'Ale Hospodin řekl satanu: Potresciž tě Hospodin, satane, potresciž tě, pravím, Hospodin, kterýž vyvoluje Jeruzalém. Zdaliž tento není jako hlavně vychvácená z ohně?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 3, 3, 'Jozue pak oblečen byl v roucha zmazaná, a stál před andělem.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 3, 4, 'I odpověděl a řekl těm, kteříž stáli před ním, řka: Vezměte roucho to zmazané s něho. A řekl jemu: Pohleď, přenesl jsem s tebe nepravost tvou, a oblékl jsem tě v roucha proměnná.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 3, 5, 'Opět řekl: Nechť vstaví čepici pěknou na hlavu jeho. I vstavili čepici pěknou na hlavu jeho, a oblékli ho v roucha. Anděl pak Hospodinův tu stál.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 3, 6, 'A osvědčil anděl Hospodinův Jozue, řka:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 3, 7, 'Takto praví Hospodin zástupů: Jestliže po cestách mých choditi budeš, a jestliže stráž mou držeti budeš, budeš-li také souditi dům můj, a budeš-li ostříhati síní mých: dámť zajisté to, abys chodil mezi těmito přístojícími.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 3, 8, 'Slyš nyní, Jozue, kněže nejvyšší, ty i tovaryši tvoji, kteříž sedí před tebou: Ačkoli muži ti jsou za zázrak, aj, já však přivedu služebníka svého, Výstřelek.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 3, 9, 'Nebo aj, totoť jest ten kámen, kterýž kladu před Jozue, na kámen jeden sedm očí; aj, já vyřeži na něm řezbu, praví Hospodin zástupů, a odejmu nepravost té země jednoho dne.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 3, 10, 'V ten den, praví Hospodin zástupů, povoláte jeden každý bližního svého pod vinný kmen a pod fík.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 4, 1, 'Potom navrátil se anděl, kterýž mluvil se mnou, a zbudil mne jako muže, kterýž zbuzen bývá ze sna svého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 4, 2, 'I řekl mi: Co vidíš? Jemuž jsem řekl: Vidím, že aj, svícen zlatý všecken, a olejný dčbán na vrchu jeho, a sedm lamp jeho na něm, a sedm nálevek k těm sedmi lampám, kteréž jsou na vrchu jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 4, 3, 'A dvě olivy při něm, jedna po pravé straně dčbánu olejného, a druhá po levé straně jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 4, 4, 'Tehdy odpověděl jsem a řekl jsem andělu tomu, kterýž mluvil ke mně, řka: Co ty věci jsou, pane můj?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 4, 5, 'A odpovídaje anděl, kterýž mluvil se mnou, řekl mi: Což nevíš, co ty věci jsou? I řekl jsem: Nevím, pane můj.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 4, 6, 'Tedy odpovídaje, mluvil ke mně, řka: Toto jest slovo Hospodinovo k Zorobábelovi, řkoucí: Ne silou, ani mocí, ale Duchem mým, praví Hospodin zástupů.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 4, 7, 'Co jsi ty, ó horo veliká, před Zorobábelem? Rovina. Nebo doloží nejvyšší kámen s hlučným prokřikováním: Milost, milost jemu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 4, 8, 'I stalo se slovo Hospodinovo ke mně, řkoucí:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 4, 9, 'Ruce Zorobábelovy založily dům tento, a ruce jeho dokonají. I zvíš, že Hospodin zástupů poslal mne k vám.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 4, 10, 'Nebo kdož by pohrdal dnem malých začátků, poněvadž se veselí, hledíce na ten kámen, totiž na závaží v ruce Zorobábelově, těch sedm očí Hospodinových, procházejících všecku zemi?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 4, 11, 'Tedy odpovídaje jemu, řekl jsem? Co ty dvě olivy po pravé straně toho svícnu, i po levé straně jeho?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 4, 12, 'Opět odpovídaje jemu, řekl jsem: Co ty dvě olivky, kteréž jsou mezi dvěma trubicemi zlatými, kteréž vylévají z sebe zlato?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 4, 13, 'I mluvil ke mně, řka: Víš-liž, co ty věci jsou? I řekl jsem: Nevím, pane můj.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 4, 14, 'Tedy řekl: To jsou ty dvě olivy, kteréž jsou u Panovníka vší země.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 5, 1, 'Potom opět pozdvihna očí svých, uzřel jsem, a aj, kniha letěla.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 5, 2, 'I řekl mi: Co vidíš? Jemuž jsem řekl: Vidím knihu letící, jejíž dlouhost byla dvadcíti loktů a širokost desíti loktů.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 5, 3, 'Tedy řekl mi: Toto prokletí vyjde na širokost vší země. Nebo každý zloděj podlé něho jako i ona vyhlazen, a každý přisahající podlé něho jako i ona vyhlazen bude.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 5, 4, 'Vynesu je, praví Hospodin zástupů, aby došlo na dům zloděje, a na dům přisahajícího skrze jméno mé falešně; anobrž bude bydliti u prostřed domu jeho, a docela zkazí jej, i dříví jeho i kamení jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 5, 5, 'Tedy vyšel anděl ten, kterýž mluvil se mnou, a řekl mi: Pozdvihni nyní očí svých a viz, co jest to, což pochází.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 5, 6, 'I řekl jsem: Co jest? Kterýž odpověděl: Toto jest efi pocházející. Řekl také: Toto jest oko její prohlédající všecku zemi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 5, 7, 'A aj, plech tlustý olověný nesen byl, a přitom žena jedna, kteráž seděla u prostřed té efi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 5, 8, 'I řekl: Toto jest ta bezbožnost. I uvrhl ji do prostřed té efi, uvrhl i ten plech olověný na vrch její.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 5, 9, 'A pozdvihna očí svých, uzřel jsem, a aj, dvě ženy vycházely, majíce vítr v křídlách svých. Měly pak křídla podobná křídlům čápím, a vyzdvihly tu efi mezi zemi a mezi nebe.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 5, 10, 'I řekl jsem andělu tomu, kterýž mluvil se mnou: Kam ony nesou tu efi?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 5, 11, 'Kterýž řekl mi: Aby sobě vystavěla dům v zemi Sinear, kdež by utvrzena byla a postavena na podstavku svém.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 6, 1, 'Potom opět pozdvihna očí svých, viděl jsem, a aj, čtyři vozové vycházeli z prostředku dvou hor, hory pak ty byly hory ocelivé.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 6, 2, 'V prvním voze byli koni ryzí, a v druhém voze byli koni vraní,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 6, 3, 'V voze pak třetím koni bílí, a v voze čtvrtém koni strakatí a hnědí.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 6, 4, 'Tedy odpovídaje, řekl jsem andělu, kterýž mluvil se mnou: Co tyto věci, pane můj?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 6, 5, 'I odpověděl anděl ten a řekl mi: To jsou čtyři větrové nebeští, vycházející odtud, kdež stáli před Panovníkem vší země.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 6, 6, 'Koni vraní zapřežení vycházejí do země půlnoční, a bílí vycházejí za nimi, strakatí pak vycházejí do země polední.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 6, 7, 'Hnědí také vyšedše, chtěli jíti, aby schodili zemi. Protož řekl: Jděte, schoďte zemi. I schodili zemi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 6, 8, 'A povolav mne, mluvil ke mně, řka: Aj ti, kteříž vyšli do země půlnoční, spokojili ducha mého v zemi půlnoční.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 6, 9, 'I stalo se slovo Hospodinovo ke mně, řkoucí:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 6, 10, 'Vezmi od zajatých, od Cheldaje a od Tobiáše a od Jedaiáše, (a přijdeš ty téhož dne, a vejdeš do domu Joziáše syna Sofoniášova), kteříž jdou z Babylona,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 6, 11, 'Vezmi, pravím, stříbro a zlato, a udělej koruny, a vstav na hlavu Jozue syna Jozadakova, kněze nejvyššího.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 6, 12, 'A mluviti budeš k němu, řka: Takto praví Hospodin zástupů, řka: Aj muž, jehož jméno jest Výstřelek, kterýž z místa svého pučiti se bude, ten vystaví chrám Hospodinův.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 6, 13, 'Nebo ten má vystavěti chrám Hospodinův, a tentýž zase přinese slávu, a seděti a panovati bude na trůnu svém, a bude knězem na trůnu svém, a rada pokoje bude mezi nimi oběma.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 6, 14, 'Budou pak ty koruny Chelemovi, a Tobiášovi, a Jedaiášovi, a Chenovi synu Sofoniášovu na památku v chrámě Hospodinově.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 6, 15, 'Nebo dalecí přijdou, a budou stavěti chrám Hospodinův, i zvíte, že Hospodin zástupů poslal mne k vám. A to se stane, jestliže skutečně poslouchati budete hlasu Hospodina Boha svého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 7, 1, 'Potom stalo se léta čtvrtého Daria krále, stalo se slovo Hospodinovo k Zachariášovi, čtvrtého dne měsíce devátého, kterýž jest Kislef,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 7, 2, 'Když poslal do domu Božího Sarezer a Regemmelech, i muži jeho, aby se kořili tváři Hospodinově,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 7, 3, 'A aby mluvili k kněžím, kteříž byli v domě Hospodina zástupů, i k prorokům, řkouce: Budeme-li plakati měsíce pátého, oddělujíce se, jako jsme činili již po mnoho let?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 7, 4, 'I stalo se slovo Hospodina zástupů ke mně, řkoucí:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 7, 5, 'Rci všemu lidu této země i kněžím takto: Když jste se postívali a kvílili, pátého a sedmého měsíce, a to po sedmdesáte let, zdaliž jste se opravdu mně, mně, pravím, postili?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 7, 6, 'A když jíte aneb pijete, zdaliž ne pro sebe jíte a ne pro sebe pijete?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 7, 7, 'Zdaliž tato nejsou slova, kteráž prohlásil Hospodin skrze proroky předešlé, když ještě Jeruzalém seděl bezpečně a užíval pokoje, i města jeho vůkol něho, a lid v straně polední i na rovinách bydlil?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 7, 8, 'I stalo se slovo Hospodinovo k Zachariášovi, řkoucí:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 7, 9, 'Takto mluvíval Hospodin zástupů, řka: Soud pravý vynášejte, a milosrdenství a lítosti dokazujte jeden každý k bližnímu svému.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 7, 10, 'A vdovy ani sirotka, příchozího ani chudého neutiskejte, a zlého žádný bližnímu svému neobmýšlejte v srdci svém.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 7, 11, 'Ale nechtěli pozorovati, a nastavili ramene urputného, a uši své obtížili, aby neslyšeli.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 7, 12, 'A srdce své učinili kámen přetvrdý, aby neslyšeli zákona toho a slov těch, kteráž posílal Hospodin zástupů Duchem svým skrze proroky předešlé. Pročež přišel hněv veliký od Hospodina zástupů.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 7, 13, 'Nebo stalo se, že jakož volajícího neslyšeli, tak když volali, neslyšel jsem, praví Hospodin zástupů.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 7, 14, 'A vichřicí rozptýlil jsem je mezi všecky ty národy, kterýchž neznali, a země tato spustla po nich, tak že nebylo žádného, kdo by tudy chodil, a tak přivedli zemi žádoucí na spuštění.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 1, 'Opět stalo se slovo Hospodina zástupů, řkoucí:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 2, 'Takto praví Hospodin zástupů: Horlil jsem pro Sion horlením velikým, nýbrž rozhněváním velikým horlil jsem pro něj.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 3, 'Takto praví Hospodin: Navrátil jsem se k Sionu, a bydlím u prostřed Jeruzaléma, aby sloul Jeruzalém městem věrným, a hora Hospodina zástupů horou svatosti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 4, 'Takto praví Hospodin zástupů: Ještěť sedati budou starci i baby na ulicích Jeruzalémských, maje každý z nich hůl v ruce své pro sešlost věku.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 5, 'Ulice také města plné budou pacholat a děvčat, hrajících na ulicích jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 6, 'Takto praví Hospodin zástupů: Zdali, že se to nepodobné zdá před očima ostatků lidu tohoto dnů těchto, také před očima mýma nepodobné bude? praví Hospodin zástupů.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 7, 'Takto praví Hospodin zástupů: Aj, já vysvobozuji lid svůj z země východní, a z země na západ slunce,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 8, 'A přivedu je zase. I budou bydliti u prostřed Jeruzaléma, a budou lidem mým, a já budu jejich Bohem v pravdě a v spravedlnosti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 9, 'Takto praví Hospodin zástupů: Posilňtež se ruce vaše, kteříž jste slyšeli těchto dnů slova tato z úst proroků, od toho dne, v němž založen jest dům Hospodina zástupů, že má chrám dostaven býti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 10, 'Nebo před těmito dny práce lidská, ani práce hovádek se nenahražovala, nýbrž ani vycházejícímu ani vcházejícímu nebylo pokoje pro nepřítele, nebo já spustil jsem všecky lidi jedny s druhými.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 11, 'Nyní pak, ne jako ve dnech těch předešlých, činím ostatkům lidu tohoto, praví Hospodin zástupů.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 12, 'Ale rozsívání máte pokojné, vinný kmen vydává ovoce své, a země vydává úrodu svou, nebesa také dávají rosu svou, a to všecko dávám v dědictví ostatkům lidu tohoto.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 13, 'A tak stane se, že jakož jste byli zlořečením mezi pohany, ó dome Judský a dome Izraelský, tak zase vás chrániti budu, a budete požehnáním. Nebojtež se, posilňte se ruce vaše.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 14, 'Nebo takto praví Hospodin zástupů: Jakož jsem byl myslil zle učiniti vám, když mne hněvali otcové vaši, praví Hospodin zástupů, aniž jsem litoval:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 15, 'Tak obrátě se, myslím v těchto dnech dobře činiti Jeruzalému a domu Judskému. Nebojtež se.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 16, 'Tyto pak věci jsou, kteréž činiti budete: Mluvte pravdu každý s bližním svým, pravý a pokojný soud vynášejte v branách svých.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 17, 'Aniž kdo bližnímu svému zlého obmýšlej v srdci svém, též přísahy falešné nemilujte; nebo všecko to jest, čehož nenávidím, praví Hospodin.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 18, 'I stalo se slovo Hospodina zástupů ke mně, řkoucí:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 19, 'Takto praví Hospodin zástupů: Půst čtvrtého měsíce, a půst pátého, a půst sedmého, a půst desátého obrátí se domu Judskému v radost a veselí, i v slavnosti rozkošné, ale pravdu a pokoj milujte.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 20, 'Takto praví Hospodin zástupů: Ještěť budou přicházeti národové a obyvatelé měst mnohých,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 21, 'Přicházeti budou, pravím, obyvatelé jednoho k druhému, řkouce: Poďmež s ochotností kořiti se tváři Hospodinově, a hledati Hospodina zástupů. Půjdu i já.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 22, 'A tak přijdou lidé mnozí a národové nesčíslní, aby hledali Hospodina zástupů v Jeruzalémě, a kořili se tváři Hospodinově.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 23, 'Takto praví Hospodin zástupů: V těch dnech chopí se deset mužů ze všech jazyků těch národů, chopí se, pravím, podolka jednoho Žida, řkouce: Půjdeme s vámi; nebo slyšíme, že jest Bůh s vámi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 9, 1, 'Břímě slova Hospodinova proti zemi, kteráž jest v vůkolí tvém, a Damašek bude odpočinutí jeho. Nebo k Hospodinu zřetel člověka i všech pokolení Izraelských.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 9, 2, 'Ano i do Emat dosáhne, do Týru i Sidonu, ačkoli jest moudrý velmi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 9, 3, 'Vystavěltě sobě Týrus pevnost, a nashromáždil stříbra jako prachu, a ryzího zlata jako bláta na ulicích.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 9, 4, 'Aj, Pán vyžene jej, a vrazí do moře sílu jeho, i on od ohně sežrán bude.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 9, 5, 'Vida to Aškalon, báti se bude, i Gáza velikou bolest míti bude, též i Akaron, proto že jej zahanbilo očekávání jeho. I zahyne král z Gázy, a Aškalon neosedí.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 9, 6, 'A bude bydliti pankhart v Azotu, a tak vypléním pýchu Filistinských.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 9, 7, 'Když pak odejmu vraždu jednoho každého od úst jeho, a ohavnosti jeho od zubů jeho, připojen bude také i on Bohu našemu, aby byl jako vývoda v Judstvu, a Akaron jako Jebuzejský.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 9, 8, 'A položím se vojensky u domu svého pro vojsko a pro ty, kteříž tam i zase jdou; aniž půjde skrze ně více násilník, proto že se tak nyní vidí očím mým.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 9, 9, 'Plésej velice, dcerko Sionská, prokřikuj, dcerko Jeruzalémská. Aj, král tvůj přijde tobě spravedlivý a spasení plný, chudý a sedící na oslu, totiž na oslátku mladém.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 9, 10, 'Nebo vypléním vozy z Efraima a koně z Jeruzaléma, a vypléněna budou lučiště válečná; nadto rozhlásí pokoj národům, a panování jeho od moře až k moři, a od řeky až do končin země.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 9, 11, 'Anobrž ty, pro krev smlouvy své vypustil jsem vězně tvé z jámy, v níž není žádné vody.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 9, 12, 'Navraťtež se k ohradě, ó vězňové v naději postavení. A tak v ten den, jakžť oznamuji, dvojnásobně nahradím tobě,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 9, 13, 'Když sobě napnu Judu a lučiště naplním Efraimem, a vzbudím syny tvé, ó Sione, proti synům tvým, ó Javane, a nastrojím tě jako meč udatného.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 9, 14, 'Nebo Hospodin proti nim se ukáže, a vynikne jako blesk střela jeho. Panovník, pravím, Hospodin trubou troubiti bude, a pobéře se s vichřicemi poledními.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 9, 15, 'Hospodin zástupů chrániti bude lidu svého, aby zmocníce se kamením z praku, jedli a pili, prokřikujíce jako od vína, a naplní jakož číši tak i rohy oltáře.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 9, 16, 'A tak je vysvobodí v ten den Hospodin Bůh jejich, jakožto stádce lid svůj, a vystaveno bude kamení pěkně tesané místo korouhví v zemi jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 9, 17, 'Nebo aj, jaké blahoslavenství jeho, a jak veliká okrasa jeho! Obilé mládence a mest panny učiní mluvné.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 10, 1, 'Žádejte od Hospodina deště v čas příhodný, i způsobí Hospodin pršku, a dá vám déšť hojný, a každému bylinu na poli.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 10, 2, 'Nebo obrazové mluví marnost, a věšťci prorokují faleš, a sny marné mluví, marností potěšují. Protož šli jako stádo, ztrestáni jsou, proto že žádného nebylo pastýře.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 10, 3, 'Proti pastýřům takovým zažžen jest hněv můj, a kozly ty trestati budu, ale stádo své, dům Judský, navštíví Hospodin zástupů, a učiní je jako koně ozdobného k boji.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 10, 4, 'Od něho úhel, od něho hřeb, od něho lučiště válečné, od něho též pojde všeliký úředník.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 10, 5, 'A budou podobni rekům, pošlapávajíce do bláta na ulicích v boji, když bojovati budou; nebo Hospodin s nimi, a zahanbí ty, kteříž jedou na koních.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 10, 6, 'Posilním zajisté domu Judova, a dům Jozefův vysvobodím, a bezpečně je osadím. Nebo lítost mám nad nimi, i budou, jako bych jich nezahnal; nebo já jsem Hospodin Bůh jejich, a vyslyším je.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 10, 7, 'I budou Efraimští jako silný rek, a veseliti se bude srdce jejich jako od vína. I jejich synové vidouce to, rozveselí se, a zpléše srdce jejich v Hospodinu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 10, 8, 'Šeptati jim budu, a tak je shromáždím; nebo je vykoupím, a rozmnoženi budou, jakož rozmnoženi byli.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 10, 9, 'Nadto rozseji je mezi národy, aby na místech dalekých rozpomínali se na mne, a živi jsouce s syny svými, navrátili se.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 10, 10, 'A tak je zase přivedu z země Egyptské, i z Assyrské shromáždím je, a do země Galád a k Libánu přivedu je, ale nepostačí jim.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 10, 11, 'Protož pro těsnost přejde přes moře, a prorazí na moři vlnobití, i vyschnou všecky hlubiny řeky, budeť snížena i pýcha Assyrie, a berla Egypta odjata bude.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 10, 12, 'A posilním jich v Hospodinu, aby ve jménu jeho ustavičně chodili, praví Hospodin.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 11, 1, 'Otevři, Libáne, vrata svá, ať zžíře oheň cedry tvé.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 11, 2, 'Kvěl jedle, nebo padl cedr, nebo znamenití vypléněni jsou; kvělte dubové Bázanští, nebo klesl les ohražený.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 11, 3, 'Hlas kvílení pastýřů, proto že popléněno důstojenství jejich; hlas řvání lvů, proto že popléněna pýcha Jordánu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 11, 4, 'Takto praví Hospodin Bůh můj: Pas ovce tyto k zbití oddané,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 11, 5, 'Kteříž držitelé jejich mordují, aniž bývají obviňováni, a kdož je prodávají, říkají: Požehnaný Hospodin, že jsme zbohatli, a kteříž je pasou, nemají lítosti nad nimi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 11, 6, 'Protož nebudu míti lítosti více nad obyvateli této země, praví Hospodin, ale aj, já uvedu ty lidi jednoho druhému v ruku, a v ruku krále jejich. I budou potírati zemi tuto, a nevytrhnu jí z ruky jejich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 11, 7, 'Nebo jsem pásl ovce k zbití oddané, totiž vás chudé toho stáda, a vzav sobě dvě hole, nazval jsem jednu utěšením, a druhou jsem nazval svazujících. A pásl jsem, pravím, ty ovce,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 11, 8, 'A zahladil jsem tři pastýře měsíce jednoho, ale duše má stýskala sobě s nimi, proto že duše jejich nenáviděla mne.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 11, 9, 'Pročež řekl jsem: Nebudu vás pásti. Kteráž umříti má, nechť umře, a kteráž má vyhlazena býti, nechť jest vyhlazena, a jiné nechažť jedí maso jedna druhé.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 11, 10, 'Protož vzav hůl svou utěšení, posekal jsem ji, zrušiv smlouvu svou, kterouž jsem učinil se vším tím lidem.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 11, 11, 'A v ten den, když zrušena byla, právě poznali chudí toho stáda, kteříž na mne pozor měli, že řeč Hospodinova jest.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 11, 12, 'Nebo jsem řekl jim: Jestliže se vám vidí, dejte mzdu mou; pakli nic, nechte tak. I odvážili mzdu mou třidceti stříbrných.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 11, 13, 'I řekl mi Hospodin: Povrz je před hrnčíře. Znamenitá mzda, kterouž jsem tak draze šacován od nich. A tak vzav třidceti stříbrných, uvrhl jsem je v domě Hospodinově před hrnčíře.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 11, 14, 'Potom posekal jsem hůl svou druhou svazujících, zrušiv bratrství mezi Judou a mezi Izraelem.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 11, 15, 'I řekl mi Hospodin: Vezmi sobě ještě oruží pastýře bláznivého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 11, 16, 'Nebo aj, já vzbudím pastýře v této zemi. Pobloudilých nebude navštěvovati, ani jehňátka hledati, ani což polámaného jest, léčiti, ani toho, což se zastavuje, nositi, ale maso toho, což tučnějšího jest, jísti bude, a kopyta jejich poláme.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 11, 17, 'Běda pastýři tomu ničemnému, kterýž opouští stádo. Meč na rameno jeho a na oko pravé jeho, rámě jeho docela uschne, a oko pravé jeho naprosto zatmí se.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 12, 1, 'Břímě slova Hospodinova příčinou Izraele. Praví Hospodin, kterýž roztáhl nebesa, a založil zemi, a sformoval ducha člověka, kterýž jest v něm:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 12, 2, 'Aj, já postavím Jeruzalém jako číši, kteráž ku potácení přivede všecky národy vůkol, kteříž budou proti Judovi v obležení, i proti Jeruzalému.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 12, 3, 'Nýbrž stane se v ten den, že položím Jeruzalém jako kámen přetěžký všechněm národům, jejž kdožkoli zdvihati budou, velmi se urazí, byť se pak shromáždili proti němu všickni národové země.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 12, 4, 'V ten den, praví Hospodin, raním všelikého koně strnutím, a jezdce jeho zblázněním, ale na dům Judský otevru oči své, a všecky koně národů raním slepotou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 12, 5, 'I dějí vůdcové Judští v srdci svém: Mámeť sílu, i obyvatelé Jeruzalémští, v Hospodinu zástupů, Bohu svém.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 12, 6, 'V ten den učiním vůdce Judské podobné ohni zanícenému mezi dřívím, a pochodni hořící mezi snopy, i zžíře na pravo i na levo všecky národy vůkol, a ostojí Jeruzalém ještě na místě svém v Jeruzalémě.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 12, 7, 'Zachová Hospodin i stánky Judské prvé, aby se nevelebila ozdoba domu Davidova a ozdoba, přebývajících v Jeruzalémě nad Judu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 12, 8, 'V ten den chrániti bude Hospodin obyvatelů Jeruzalémských, a bude nejnestatečnější z nich v ten den podobný Davidovi, a dům Davidův podobný bohům, podobný andělu Hospodinovu před nimi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 12, 9, 'Nebo stane se v ten den, že shledám všecky národy, kteříž přitáhnou proti Jeruzalému, abych je zahladil.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 12, 10, 'A vyleji na dům Davidův a na obyvatele Jeruzalémské Ducha milosti a pokorných proseb. I obrátí zřetel ke mně, kteréhož jsou bodli, a kvíliti budou nad ním jako kvílením nad jednorozeným; hořce, pravím, plakati budou nad ním, jako hořce plačí nad prvorozeným.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 12, 11, 'V ten den bude veliké kvílení v Jeruzalémě, jako kvílení v Adadremmon na poli Mageddo.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 12, 12, 'Nebo kvíliti bude země, každá čeled obzvláštně, čeled domu Davidova obzvláštně, a ženy jejich obzvláštně, čeled domu Nátanova obzvláštně, a ženy jejich obzvláštně,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 12, 13, 'Čeled domu Léví obzvláštně, a ženy jejich obzvláštně, čeled Semei obzvláštně, a ženy jejich obzvláštně,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 12, 14, 'I všecky čeledi jiné, každá čeled obzvláštně, a ženy jejich obzvláštně.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 13, 1, 'V ten den bude studnice otevřená domu Davidovu a obyvatelům Jeruzalémským, k obmytí hřícha i nečistoty.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 13, 2, 'Stane se také v ten den, praví Hospodin zástupů, že vyhladím jména modl z země, tak že nebudou připomínány více, nýbrž také i ty proroky a ducha nečistoty vyprázdním z země.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 13, 3, 'I stane se, prorokoval-li by někdo více, že jemu řeknou otec jeho a matka jeho, kteříž jej zplodili: Nebudeš živ, proto že jsi lež mluvil ve jménu Hospodinovu. I probodnou jej otec jeho a matka jeho, kteříž jej zplodili, že prorokoval.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 13, 4, 'A tak stane se v ten den, že se budou styděti proroci ti, každý za vidění své, když by prorokovali, aniž oblekou sukně z srstí, aby klamali.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 13, 5, 'Ale dí každý: Nejsem já prorok. Muž, kterýž zemi dělá, jsem já; nebo mne učil tomu člověk od dětinství mého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 13, 6, 'A dí-li kdo jemu: Jaké to máš rány na rukou svých? I odpoví: Jimiž jsem zbit v domě těch, kteříž mne milují.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 13, 7, 'Ó meči, prociť na pastýře mého, a na muže bližního mého, praví Hospodin zástupů. Bí pastýře, a rozprchnou se ovce, ale zase obrátím ruku svou k maličkým.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 13, 8, 'Nebo stane se po vší zemi této, praví Hospodin, že dvě částky vyhlazeny budou v ní a zemrou, a třetí v ní zanechána bude.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 13, 9, 'A i tu třetí uvedu do ohně, a přeženu je, jako se přehání stříbro, a zprubuji je, jako prubováno bývá zlato. Každý vzývati bude jméno mé, a já vyslyším jej. Řeknu: Lid můj jest: a on dí: Hospodin jest Bůh můj.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 1, 'Aj, den Hospodinův přichází, a rozděleny budou kořisti tvé u prostřed tebe.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 2, 'Nebo shromáždím všecky národy proti Jeruzalému k boji, i bude dobyto město, a domové zloupeni, a ženy zhanobeny budou. A když vyjde díl města v zajetí, ostatek lidu nebude vyhlazeno z města.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 3, 'Nebo Hospodin vytáhna, bude bojovati proti těm národům, jakž bojuje v den potýkání.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 4, 'I stanou nohy jeho v ten den na hoře Olivetské, kteráž jest naproti Jeruzalému od východu, a rozdvojí se hora Olivetská napoly k východu a k západu údolím velmi velikým, a odstoupí díl té hory na půlnoci, a díl její na poledne.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 5, 'I budete utíkati před údolím hor; nebo dosáhne údolí hor až k Azal. Budete, pravím, utíkati, jako jste utíkali před země třesením za dnů Uziáše krále Judského, když přijde Hospodin Bůh můj, a všickni svatí s ním.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 6, 'I stane se v ten den, že nebude světla drahého, ani tmy husté.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 7, 'A tak bude den jeden, kterýž jest znám Hospodinu, aniž bude den, ani noc; a však stane se, že v čas večera bude světlo.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 8, 'Stane se také v ten den, že vycházeti budou vody živé z Jeruzaléma, díl jich k moři východnímu, a díl jich k moři nejdalšímu. V létě i v zimě bude.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 9, 'A bude Hospodin králem nade vší zemí; v ten den bude Hospodin jediný, a jméno jeho jedno.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 10, 'A učiněna bude všecka tato země jako rovina od Gaba k Remmon na polední straně Jeruzalému, kterýž vyvýšen jsa, státi bude na místě svém, od brány Beniaminovy až k místu brány první, a až k bráně úhlové, a od věže Chananeel až k presu královskému.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 11, 'A budou bydliti v něm, a nebude více v prokletí; město Jeruzalém zajisté bezpečně seděti bude.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 12, 'Tato pak bude rána, kterouž raní Hospodin všecky národy, kteříž by bojovali proti Jeruzalému: Usuší tělo jednoho každého, stojícího na nohách svých, a oči jednoho každého usvadnou v děrách svých, a jazyk jednoho každého usvadne v ústech jejich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 13, 'I stane se v ten den, že bude znepokojení Hospodinovo veliké mezi nimi, tak že uchopí jeden druhého ruku, a vztažena bude ruka jednoho na ruku druhého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 14, 'Také i ty, Judo, bojovati budeš v Jeruzalémě, a shromážděno bude zboží všech národů vůkol, zlato a stříbro, i roucha velmi mnoho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 15, 'A podobná bude rána koní, mezků, velbloudů a oslů i všech hovad, kteráž budou v tom ležení, podobná ráně té.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 16, 'I stane se, že kdožkoli pozůstane ze všech národů, kteříž by přitáhli proti Jeruzalému, přicházeti budou z rok do roka klaněti se králi Hospodinu zástupů a slaviti slavnost stánků.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 17, 'I stane se, kdo z čeledí země nebude přicházeti do Jeruzaléma klaněti se králi Hospodinu zástupů, že nebude na ně pršeti déšt.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 18, 'A jestliže čeled Egyptská nevstoupí, ani přijde, jakkoli na ně ne pršívá, přijde však táž rána, kterouž raní Hospodin národy, kteříž by nepřicházeli k slavení slavnosti stánků.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 19, 'Tať bude pokuta pro hřích Egyptských a pokuta pro hřích všech národů, kteříž by nechodili k slavení slavnosti stánků.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 20, 'V ten den bude na zvoncích koňských: Svatost Hospodinu; a bude hrnců v domě Hospodinově jako číší před oltářem.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 21, 'Nýbrž bude všeliký hrnec v Jeruzalémě a v Judstvu svatost Hospodinu zástupů; a přicházejíce všickni, kteříž obětovati mají, budou je bráti a vařiti v nich. Aniž bude Kananejský více v domě Hospodina zástupů v ten den.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 1, 1, 'Břímě slova Hospodinova proti Izraelovi skrze Malachiáše.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 1, 2, 'Miluji vás, praví Hospodin, vy pak říkáte: V čem nás miluješ? Zdaliž Ezau nebyl bratr Jákobův? praví Hospodin. A však jsem miloval Jákoba.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 1, 3, 'Ezau pak měl jsem v nenávisti; protož zanechal jsem hor jeho pustých, a dědictví jeho drakům pouště.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 1, 4, 'Řekne-li Idumejská země: Ochuzeniť jsme, ale navrátíme se zase, a vystavíme místa pustá, takto praví Hospodin zástupů: Oni nechť stavějí, a já budu bořiti. I budou je nazývati pomezím bezbožnosti a lidem, na nějž hněviv bude Hospodin až na věky.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 1, 5, 'Což oči vaše uzří, a vy díte: Veleben buď Hospodin po pomezích Izraelských.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 1, 6, 'Syn ctí otce, a služebník pána svého. Protož jestližeť jsem já otec, kdež jest čest má? A jestliže jsem pán, kde jest bázeň má? Vám to mluví Hospodin zástupů, ó kněží, kteříž sobě zlehčujete jméno mé. A však říkáte: V čem zlehčujeme jméno tvé?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 1, 7, 'Kteříž přinášejíce na oltář můj obět poškvrněnou, říkáte: Čímž jsme tě poškvrnili? Tím, když říkáte: Stůl Hospodinův v pohrdání jest.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 1, 8, 'Nebo když přivodíte slepé k obětování, což to není nic zlého? A když přivodíte chromé aneb nemocné, což to není nic zlého? Daruj je medle knížeti svému, zalíbíš-li mu se tím, a přijme-li tvář tvou, praví Hospodin zástupů.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 1, 9, 'A protož nyní kořtež se tváři Boha silného, aby nám milost učinil. Ale když to z rukou vašich jest, přijme-liž kterého z vás oblíčej? praví Hospodin zástupů.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 1, 10, 'Anobrž kdo jest mezi vámi, aby zavřel dvéře, aneb zapálil na oltáři mém darmo? Nemámť v vás žádné líbosti, praví Hospodin zástupů, a oběti nepřijmu z ruky vaší.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 1, 11, 'Nebo od východu slunce až na západ jeho veliké bude jméno mé mezi národy, a na všelikém místě kadění přinášíno bude jménu mému, a obět čistá. Veliké zajisté jméno mé bude mezi národy, praví Hospodin zástupů,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 1, 12, 'Ačkoli vy ho poškvrňujete, když říkáte: Stůl Hospodinův v pohrdání jest, a což kladeno bývá na něj, že jest chaterný pokrm.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 1, 13, 'Říkáte také: Ach, větší práce, ješto byste to zdmýchnouti mohli, praví Hospodin zástupů. Nebo přinášíte to, což jest vydřeno, a chromé i nemocné, přinášejíce dar. To-liž mám přijímati z ruky vaší? praví Hospodin.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 1, 14, 'Anobrž zlořečený jest fortelný, kterýž maje v svém stádě samce, činí slib, a obětuje Pánu to, což jest churavého. Nebo král veliký já jsem, praví Hospodin zástupů, a jméno mé jest hrozné mezi národy.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 1, 'A tak nyní k vám přikázání to, ó kněží.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 2, 'Neuposlechnete-li a nesložíte-li v srdci, abyste dali slávu jménu mému, praví Hospodin zástupů, zajisté že pošli na vás zlořečenství, a zlořečiti budu požehnáním vašim. Anobrž již jsem zlořečil každému z nich, nebo jste nikoli nesložili toho v srdci.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 3, 'Aj, já pokazím vám to, což nasejete, a vkydnu lejno na tváře vaše, lejno obětí vašich, tak že vás zachvátí k sobě.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 4, 'Nebo víte, že jsem poslal k vám přikázaní to, aby byla stálá smlouva s Léví, praví Hospodin zástupů.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 5, 'Smlouva má byla s ním života a pokoje, a dal jsem jemu to pro bázeň; nebo se bál mne, a pro jméno mé potřín byl.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 6, 'Zákon pravdy byl v ústech jeho, a nepravost nebyla nalezena ve rtech jeho, v pokoji a upřímosti chodil se mnou, a mnohé odvrátil od nepravosti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 7, 'Nebo rtové kněze mají ostříhati umění, a na zákon doptávati se z úst jeho; posel zajisté Hospodina zástupů jest.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 8, 'Vy pak sešli jste s cesty, byli jste příčinou mnohým, aby činili proti zákonu; zrušili jste smlouvu Levítskou, praví Hospodin zástupů.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 9, 'Pročež i já také vydal jsem vás v potupu a v nevážnost všemu lidu, jakož vy v ničemž neostříháte cest mých, a přijímáte osoby v zákoně.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 10, 'Zdaliž není jeden otec všech nás? Zdaliž Bůh jeden nestvořil nás? Proč nevěrně činiti máme jeden druhému a zlehčovati smlouvu otců našich?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 11, 'Nevěrně činí Juda, a ohavnost se děje v Izraeli a v Jeruzalémě; nebo poškvrňuje Juda svatosti Hospodinovy, kterouž by milovati měl, pojímaje za manželku dceru boha jiného.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 12, 'Vypléní Hospodin muže, kterýž to činí, z stánků Jákobových, bdícího i odpovídajícího, i obětujícího dar Hospodinu zástupů.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 13, 'Již to podruhé činíte, že přikrýváte slzami oltář Hospodinův, pláčem a křikem, pročež nikoli nepatří již více k daru, aniž přijímá oběti vzácné z ruky vaší.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 14, 'A však říkáte? Pro kterou příčinu? Proto že Hospodin jest svědkem mezi tebou a manželkou mladosti tvé, kteréž ty nevěrně činíš, ješto ona jest tovaryška tvá, a manželka smlouvy tvé.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 15, 'Zdaliž neučinil jedno, ačkoli ještě více ducha měl? Proč pak jedno? Aby hledali semene Božího. Protož ostříhejte ducha svého, a manželce mladosti své nečiňte nevěrně.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 16, 'Proto že v nenávisti má propouštění, praví Hospodin Bůh Izraelský, proto že takový přikrývá ukrutnost pláštěm jeho, praví Hospodin zástupů, protož ostříhejte ducha svého, abyste nečinili nevěrně.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 17, 'Těžcí jste Hospodinu slovy svými, a však říkáte: V čem jsme těžcí? Když říkáte: Každý, kdož činí zlé, líbí se Hospodinu, a v těch on líbost má, aneb: Kde jest Bůh soudu?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 1, 'Aj, já posílám anděla svého, kterýž připraví cestu před tváří mou. V tom hned přijde do chrámu svého Panovník, kteréhož vy hledáte, a anděl smlouvy, v němž vy líbost máte. Aj, přijdeť, praví Hospodin zástupů.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 2, 'Ale kdo bude moci snésti den příchodu jeho? A kdo ostojí, když se on ukáže? Nebo on jest jako oheň rozpouštějící a jako mýdlo běličů.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 3, 'I sedna, přeháněti bude a přečišťovati stříbro, a přečistí syny Léví, a vyčistí je jako zlato a jako stříbro. I budou Hospodinovi, obětujíce oběti v spravedlnosti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 4, 'I zachutná sobě Hospodin obět Judovu a Jeruzalémských, jako za dnů prvních, a jako za let starodávních.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 5, 'K vám pak přikročím s pomstou, a budu rychlým svědkem proti kouzedlníkům, a proti cizoložníkům, a proti křivopřísežníkům, i proti těm, kteříž s útiskem zadržují mzdu nájemníka, vdově a sirotku, a příchozímu křivdu činíce, nebojí se mne, praví Hospodin zástupů.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 6, 'Nebo já Hospodin neměním se, protož vy, synové Jákobovi, nevzali jste skončení.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 7, 'Hned ode dnů otců vašich odešli jste od ustanovení mých, a neostříhali jste jich. Navraťtež se ke mně, a navrátím se k vám, praví Hospodin zástupů. Ale říkáte: V čem bychom se navrátiti měli?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 8, 'Loupiti-liž má člověk Boha, že vy loupíte mne? A však říkáte: V čem tě loupíme? V desátcích a obětech.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 9, 'Naprosto zlořečení jste, proto že mne loupíte, vy pokolení všecko.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 10, 'Sneste všecky desátky do obilnice, aby byla potrava v domě mém, a zkuste mne nyní v tom, praví Hospodin zástupů, nezotvírám-liť vám průduchů nebeských, a nevyleji-li na vás požehnání, tak že neodoláte.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 11, 'A přimluvím pro vás tomu, což zžírá, a nebude vám kaziti úrod zemských, aniž vám pochybí vinný kmen na poli, praví Hospodin zástupů.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 12, 'I budou vás blažiti všickni národové; nebo vy budete zemí rozkošnou, praví Hospodin zástupů.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 13, 'Rozmohlať se proti mně slova vaše, praví Hospodin, a však říkáte: Což jsme mluvili proti tobě?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 14, 'Říkáte: Daremná jest věc sloužiti Bohu, a jaký zisk, budeme-li ostříhati nařízení jeho, a budeme-li choditi zasmušile, bojíce se Hospodina zástupů?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 15, 'Nýbrž nyní blahoslavíme pyšné. Ti, kteříž páší bezbožnost, vzdělávají se, a pokoušející Boha vysvobozeni bývají.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 16, 'Tehdy ti, kteříž se bojí Hospodina, tytýž mluvili jeden k druhému. I pozoroval Hospodin a slyšel, a psána jest kniha pamětná před ním pro ty, kteříž se bojí Hospodina, a myslí na jméno jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 17, 'Tiť budou, praví Hospodin zástupů, v den, kterýž já učiním, mým klínotem, a slituji se nad nimi, jako se slitovává otec nad synem svým, kterýž mu slouží.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 18, 'Tehdy obrátíte se, a uzříte rozdíl mezi spravedlivým a bezbožným, mezi tím, kdo slouží Bohu, a tím, kdo jemu neslouží.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 4, 1, 'Nebo aj, den ten přichází hořící jako pec, v němž budou všickni pyšní, a všickni pášící bezbožnost jako strniště. I zažhne je ten den, kterýž přijíti má, praví Hospodin zástupů, tak že neostaví jim ani kořene ani ratolesti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 4, 2, 'Vám pak, kteříž se bojíte jména mého, vzejde slunce spravedlnosti, a zdraví bude na paprslcích jeho. Tedy vycházeti budete, a porostete jako telata vykrmená.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 4, 3, 'A pošlapáte bezbožné, tak že budou jako popel pod nohami vašimi v den, kterýž já učiním, praví Hospodin zástupů.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 4, 4, 'Pamatujtež na zákon Mojžíše služebníka mého, jemuž jsem přikázal na Orébě přednesti všemu Izraeli ustanovení a soudy.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 4, 5, 'Aj, já pošli vám Eliáše proroka, prvé nežli přijde den Hospodinův veliký a hrozný,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 4, 6, 'Aby obrátil srdce otců k synům, a srdce synů k otcům jejich, abych přijda, neranil země prokletím.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 1, 'Kniha rodu Ježíše Krista syna Davidova, syna Abrahamova.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 2, 'Abraham zplodil Izáka. Izák pak zplodil Jákoba. Jákob zplodil Judu a bratří jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 3, 'Judas pak zplodil Fáresa a Záru z Támar. Fáres pak zplodil Ezroma. Ezrom zplodil Arama.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 4, 'Aram pak zplodil Aminadaba. Aminadab pak zplodil Názona. Názon zplodil Salmona.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 5, 'Salmon zplodil Bóza z Raab. A Bóz zplodil Obéda z Rut. Obéd pak zplodil Jesse.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 6, 'Jesse zplodil Davida krále. David pak král zplodil Šalomouna, z té, kteráž byla Uriášova.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 7, 'Šalomoun zplodil Roboáma. Roboám zplodil Abiáše. Abiáš zplodil Azu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 8, 'Aza zplodil Jozafata. Jozafat zplodil Joráma. Jorám zplodil Oziáše.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 9, 'Oziáš pak zplodil Joátama. Joátam pak zplodil Achasa. Achas zplodil Ezechiáše.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 10, 'Ezechiáš pak zplodil Manassesa. A Manasses zplodil Amona. Amon pak zplodil Joziáše.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 11, 'Joziáš pak zplodil Jekoniáše a bratří jeho v zajetí Babylonském.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 12, 'A po zajetí Babylonském Jekoniáš zplodil Salatiele. Salatiel pak zplodil Zorobábele.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 13, 'A Zorobábel zplodil Abiuda. Abiud pak zplodil Eliakima. Eliakim zplodil Azora.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 14, 'Azor potom zplodil Sádocha. Sádoch zplodil Achima. Achim pak zplodil Eliuda.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 15, 'Eliud zplodil Eleazara. Eleazar zplodil Mátana. Mátan zplodil Jákoba.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 16, 'Jákob pak zplodil Jozefa, muže Marie, z nížto narodil se JEŽÍŠ, kterýž slove Kristus.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 17, 'A tak všech rodů od Abrahama až do Davida bylo rodů čtrnácte, a od Davida až do zajetí Babylonského rodů čtrnácte, a od zajetí Babylonského až do Krista rodů čtrnácte.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 18, 'Jezukristovo pak narození takto se stalo: Když matka jeho Maria zasnoubena byla Jozefovi, prvé než se sešli, nalezena jest těhotná z Ducha svatého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 19, 'Ale Jozef muž její spravedlivý jsa, a nechtěv jí v lehkost uvésti, chtěl ji tajně propustiti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 20, 'Když pak on o tom přemyšloval, aj, anděl Páně ve snách ukázal se jemu, řka: Jozefe synu Davidův, neboj se přijíti Marie manželky své; nebo což v ní jest počato, z Ducha svatého jest.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 21, 'Porodíť pak syna, a nazůveš jméno jeho Ježíš; onť zajisté vysvobodí lid svůj od hříchů jejich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 22, 'Toto pak všecko stalo se, aby se naplnilo, což povědíno bylo ode Pána skrze proroka, řkoucího:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 23, 'Aj, panna těhotná bude, a porodí syna, a nazůveš jméno jeho Emmanuel, kteréž se vykládá: S námi Bůh.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 24, 'Procítiv pak Jozef ze sna, učinil, jakož mu přikázal anděl Páně, a přijal manželku svou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 25, 'Ale nepoznal jí, až i porodila Syna svého prvorozeného, a nazvala jméno jeho Ježíš.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 1, 'Když se pak narodil Ježíš v Betlémě Judově za dnů Heródesa krále, aj, mudrci od východu slunce vypravili se do Jeruzaléma,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 2, 'Řkouce: Kde jest ten narozený král Židovský? Nebo viděli jsme hvězdu jeho na východu slunce, a vypravili jsme se, abychom se klaněli jemu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 3, 'To uslyšev Heródes král, zarmoutil se i všecken Jeruzalém s ním.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 4, 'A protož svolav všecky přední kněží {biskupy} a učitele lidu, tázal se jich, kde by se Kristus měl naroditi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 5, 'Oni pak řekli jemu: V Betlémě Judově. Nebo tak jest psáno skrze proroka:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 6, 'A ty Betléme, země Judská, nikoli nejsi nejmenší mezi knížaty Judskými; neboť z tebe vyjde vývoda, kterýž pásti bude lid můj Izraelský.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 7, 'Tehdy Heródes tajně povolav mudrců, pilně se jich vyptával, kterého by se jim času hvězda ukázala.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 8, 'A když je propouštěl do Betléma, řekl: Jdouce, vyptejte se pilně na to děťátko, a když naleznete, zvěstujtež mi, ať i já přijda, pokloním se jemu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 9, 'Oni pak vyslyševše krále, jeli. A aj, hvězda, kterouž byli viděli na východu slunce, předcházela je, až i přišedši, stála nad místem, kdež bylo děťátko.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 10, 'A uzřevše hvězdu, zradovali se radostí velmi velikou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 11, 'I všedše do domu, nalezli děťátko s Marií matkou jeho, a padše, klaněli se jemu; a otevřevše poklady své, obětovali jemu dary, zlato a kadidlo a mirru.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 12, 'A od Boha napomenuti jsouce ve snách, aby se nenavraceli k Heródesovi, jinou cestou navrátili se do krajiny své.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 13, 'Když pak oni odjeli, aj, anděl Páně ukázal se Jozefovi ve snách, řka: Vstana, vezmi děťátko i matku jeho, a utec do Egypta, a buď tam, dokudž nepovím tobě; neboť bude Heródes hledati děťátka, aby je zahubil.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 14, 'Kterýž vstav v noci, vzal děťátko i matku jeho, a odšel do Egypta.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 15, 'A byl tam až do smrti Heródesovy, aby se naplnilo povědění Páně skrze proroka, řkoucího: Z Egypta povolal jsem Syna svého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 16, 'Tehdy Heródes uzřev, že by oklamán byl od mudrců, rozhněval se náramně, a poslav, zmordoval všecky dítky, kteréž byly v Betlémě i ve všech končinách jeho, od dvouletých a níže, podlé času, na kterýž se byl pilně vyptal od mudrců.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 17, 'Tehdy naplněno jest to povědění Jeremiáše proroka, řkoucího:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 18, 'Hlas v Ráma slyšán jest, naříkání a pláč a kvílení mnohé; Ráchel plačící synů svých, a nedala se potěšiti, proto že jich není.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 19, 'Když pak umřel Heródes, aj, anděl Páně ukázal se Jozefovi ve snách v Egyptě,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 20, 'Řka: Vstana, vezmi dítě i matku jeho, a jdiž do země Izraelské; neboť jsou zemřeli ti, kteříž hledali bezživotí dítěte.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 21, 'Kterýžto vstav, vzal dítě i matku jeho, a přišel do země Izraelské.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 22, 'Ale uslyšev, že by Archelaus kraloval v Judstvu místo Heródesa otce svého, obával se tam jíti; avšak napomenut byv od Boha ve snách, obrátil se do krajin Galilejských.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 23, 'A přišed, bydlil v městě, kteréž slove Nazarét, aby se naplnilo, což povědíno bylo skrze proroky, že Nazaretský slouti bude.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 1, 'V těch pak dnech přišel Jan Křtitel, káže na poušti v zemi Judské,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 2, 'A řka: Pokání čiňte, nebo přiblížilo se království nebeské.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 3, 'Totoť jest zajisté ten předpověděný od Izaiáše proroka, řkoucího: Hlas volajícího na poušti: Připravujte cestu Páně, přímé čiňte stezky jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 4, 'Ten pak Jan měl roucho z srstí velbloudových, a pás kožený okolo bedr svých, a pokrm jeho byl kobylky a med lesní.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 5, 'Tedy vycházel k němu Jeruzalém a všecko Judstvo, i všecka okolní krajina Jordánská,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 6, 'A křtěni byli od něho v Jordáně, vyznávajíce hříchy své.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 7, 'Uzřev pak mnohé z farizeů a z saduceů, že jdou k jeho křtu, řekl jim: Pokolení ještěrčí, i kdo vám ukázal, kterak byste utéci měli budoucího hněvu?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 8, 'Protož neste ovoce hodné pokání.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 9, 'A nemyslte, že můžete říkati sami u sebe: Otce máme Abrahama. Neboť pravím vám, že může Bůh z kamení tohoto vzbuditi syny Abrahamovi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 10, 'A jižť jest i sekera k kořenu stromů přiložena. Každý tedy strom, kterýž nenese ovoce dobrého, vyťat a na oheň uvržen bývá.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 11, 'Jáť křtím vás vodou ku pokání, ten pak, kterýž po mně přichází, jestiť mocnější nežli já, jehožto nejsem hoden obuvi nositi. Onť vás křtíti bude Duchem svatým a ohněm.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 12, 'Jehožto věječka v ruce jeho, a vyčistíť humno své, a shromáždí pšenici svou do obilnice, ale plevy páliti bude ohněm neuhasitelným.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 13, 'Tehdy přišel Ježíš od Galilee k Jordánu k Janovi, aby pokřtěn byl od něho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 14, 'Ale Jan velmi zbraňoval jemu, řka: Já mám od tebe křtěn býti, a ty pak jdeš ke mně?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 15, 'A odpovídaje Ježíš, dí jemu: Nechej nyní; neboť tak sluší na nás, abychom plnili všelikou spravedlnost. Tedy nechal ho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 16, 'A pokřtěn jsa Ježíš, vystoupil i hned z vody; a aj, otevřína jsou mu nebesa, a viděl Ducha Božího, sstupujícího jako holubici, a přicházejícího na něj.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 17, 'A aj, hlas s nebe řkoucí: Tentoť jest ten můj milý Syn, v němž mi se dobře zalíbilo.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 1, 'Tehdy Ježíš veden jest na poušť od Ducha, aby pokoušín byl od ďábla.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 2, 'A postiv se čtyřidceti dnů a čtyřidceti nocí, potom zlačněl.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 3, 'A přistoupiv k němu pokušitel, řekl: Jsi-li Syn Boží, rciž, ať kamení toto chlebové jsou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 4, 'On pak odpovídaje, řekl: Psánoť jest: Ne samým chlebem živ bude člověk, ale každým slovem vycházejícím skrze ústa Boží.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 5, 'Tedy pojal jej ďábel do svatého města, a postavil ho na vrchu chrámu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 6, 'A řekl mu: Jsi-li Syn Boží, spustiž se dolů; nebo psáno jest, že andělům svým přikázal o tobě, a na ruce uchopí tebe, abys někde o kámen nohy své neurazil.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 7, 'I řekl mu Ježíš: Zase psáno jest: Nebudeš pokoušeti Pána Boha svého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 8, 'Opět pojal ho ďábel na horu vysokou velmi, a ukázal mu všecka království světa i slávu jejich,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 9, 'A řekl jemu: Toto všecko tobě dám, jestliže padna, budeš mi se klaněti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 10, 'Tedy řekl mu Ježíš: Odejdiž, satane; neboť psáno jest: Pánu Bohu svému klaněti se budeš, a jemu samému sloužiti budeš.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 11, 'Tedy opustil ho ďábel, a aj, andělé přistoupili a sloužili jemu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 12, 'A když uslyšel Ježíš, že by Jan byl vsazen, navrátil se do Galilee.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 13, 'A opustiv Nazarét, přišed, bydlil v Kafarnaum při moři, v krajinách Zabulon a Neftalím,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 14, 'Aby se naplnilo povědění skrze Izaiáše proroka, řkoucího:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 15, 'Země Zabulon a Neftalím při moři za Jordánem, Galilea pohanská,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 16, 'Lid, kterýž bydlil v temnostech, viděl světlo veliké, a sedícím v krajině a stínu smrti, světlo vzešlo jim.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 17, 'Od toho času počal Ježíš kázati a praviti: Pokání čiňte; neboť se přiblížilo království nebeské.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 18, 'A chodě Ježíš podlé moře Galilejského, uzřel dva bratry, Šimona, kterýž slove Petr, a Ondřeje bratra jeho, ani pouštějí síť do moře, (nebo byli rybáři.)');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 19, 'I dí jim: Poďte za mnou, a učiním vás rybáře lidí.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 20, 'A oni hned opustivše síti, šli za ním.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 21, 'A poodšed odtud, uzřel jiné dva bratry, Jakuba syna Zebedeova, a Jana bratra jeho, na lodí s Zebedeem otcem jejich, ani tvrdí síti své. I povolal jich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 22, 'A oni hned opustivše lodí a otce svého, šli za ním.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 23, 'I procházel Ježíš všecku Galilei, uče v shromážděních jejich a káže evangelium království, a uzdravuje všelikou nemoc i všeliký neduh v lidu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 24, 'A rozešla se o něm pověst po vší Syrii. I vodili k němu všecky nemocné, rozličnými neduhy a trápeními obklíčené, i ďábelníky, i náměsičníky, i šlakem poražené, a uzdravoval je.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 25, 'I šli za ním zástupové mnozí z Galilee a z Desíti měst, i z Jeruzaléma i z Judstva i z Zajordání.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 1, 'Vida pak Ježíš zástupy, vstoupil na horu; a když se posadil, přistoupili k němu učedlníci jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 2, 'I otevřev ústa svá, učil je, řka:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 3, 'Blahoslavení chudí duchem, nebo jejich jest království nebeské.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 4, 'Blahoslavení lkající, nebo oni potěšeni budou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 5, 'Blahoslavení tiší, nebo oni dědictví obdrží na zemi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 6, 'Blahoslavení, kteříž lačnějí a žíznějí spravedlnosti, nebo oni nasyceni budou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 7, 'Blahoslavení milosrdní, nebo oni milosrdenství důjdou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 8, 'Blahoslavení čistého srdce, nebo oni Boha viděti budou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 9, 'Blahoslavení pokojní, nebo oni synové Boží slouti budou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 10, 'Blahoslavení, kteříž protivenství trpí pro spravedlnost, nebo jejich jest království nebeské.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 11, 'Blahoslavení budete, když vám zlořečiti budou a protivenství činiti, a mluviti všecko zlé o vás, lhouce, pro mne.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 12, 'Radujte se a veselte se, nebo odplata vaše hojná jest v nebesích. Takť zajisté protivili se prorokům, kteříž byli před vámi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 13, 'Vy jste sůl země. Jestliže sůl zmařena bude, čím bude osolena? K ničemuž se nehodí více, než aby byla ven vyvržena a od lidí pošlapána.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 14, 'Vy jste světlo světa. Nemůžeť město na hoře ležící skryto býti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 15, 'Aniž rozsvěcují svíce a stavějí ji pod kbelec, ale na svícen; i svítí všechněm, kteříž jsou v domě.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 16, 'Tak svěť světlo vaše před lidmi, ať vidí skutky vaše dobré, a slaví Otce vašeho, kterýž jest v nebesích.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 17, 'Nedomnívejte se, že bych přišel rušiti zákona aneb proroků. Nepřišelť jsem rušiti, ale naplniti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 18, 'Amen zajisté pravím vám: Dokudž nepomine nebe i země, jediná literka aneb jeden puňktík nepomine z zákona, až se všecky věci stanou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 19, 'Protož zrušil-li by kdo jedno z přikázaní těchto nejmenších, a učil by tak lidi, nejmenší slouti bude v království nebeském. Kdož by pak koli činil i učil, ten veliký slouti bude v království nebeském.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 20, 'Nebo pravím vám: Nebude-liť hojnější spravedlivost vaše nežli zákonníků a farizeů, nikoli nevejdete do království nebeského.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 21, 'Slyšeli jste, že říkáno jest starým: Nezabiješ. Pakli by kdo zabil, povinen trpěti soud.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 22, 'Ale jáť pravím vám: Že každý, kdož se hněvá na bratra svého bez příčiny, musí trpěti soud. Kdož by pak řekl bratru svému: Rácha, povinen bude před radou státi; a kdož by řekl: Blázne, musí pekelný oheň trpěti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 23, 'Protož obětoval-li bys dar svůj na oltář, a tu bys se rozpomenul, že bratr tvůj má něco proti tobě:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 24, 'Nechejž tu daru svého před oltářem a odejdi; prvé smiř se s bratrem svým, a potom přijda, obětuj dar svůj.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 25, 'Vejdi v dobrou vůli s protivníkem svým rychle, dokudž jsi s ním na cestě, aťby snad nedal tebe protivník tvůj soudci, a soudce dal by tě služebníku, a byl bys uvržen do žaláře.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 26, 'Amen pravím tobě: Nevyjdeš odtud, dokudž i posledního haléře nenavrátíš.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 27, 'Slyšeli jste, že říkáno bylo starým: Nezcizoložíš.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 28, 'Ale jáť pravím vám: Že každý, kdož by pohleděl na ženu ku požádání jí, již zcizoložil s ní v srdci svém.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 29, 'Jestliže pak oko tvé pravé horší tě, vylup je a vrz od sebe; neboť jest užitečněji tobě, aby zahynul jeden oud tvůj, než by celé tělo tvé uvrženo bylo do ohně pekelného.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 30, 'A pakli ruka tvá pravá horší tě, utni ji a vrz od sebe; nebo užitečněji jest tobě, aby zahynul jeden oud tvůj, než by všecko tělo tvé uvrženo bylo do pekelného ohně.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 31, 'Též řečeno jest: Kdož by koli propustil manželku svou, aby jí dal lístek rozloučení.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 32, 'Jáť pak pravím vám: Že kdožkoli propustil by manželku svou, kromě příčiny cizoložstva, uvodí ji v cizoložstvo, a kdož propuštěnou pojme, cizoloží.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 33, 'Opět slyšeli jste, že říkáno bylo starým: Nebudeš křivě přisahati, ale splníš Pánu přísahy své.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 34, 'Ale jáť pravím vám: Abyste nepřisahali všelijak, ani skrze nebe, nebo trůn Boží jest;');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 35, 'Ani skrze zemi, nebo podnož jeho jest; ani skrze Jeruzalém, nebo město velikého toho Krále jest.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 36, 'Ani skrze hlavu svou budeš přisahati, nebo nemůžeš jednoho vlasu učiniti bílého aneb černého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 37, 'Ale buď řeč vaše: Jistě, jistě; nikoli, nikoli. Což pak nad to více jest, to od zlého jest.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 38, 'Slyšeli jste, že říkáno bylo: Oko za oko, a zub za zub.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 39, 'Jáť pak pravím vám: Abyste neodpírali zlému. Ale udeří-li tě kdo v pravé líce tvé, nasaď jemu i druhého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 40, 'A tomu, kdož se s tebou chce souditi a sukni tvou vzíti, nech mu i pláště.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 41, 'A nutil-li by tě kdo míli jednu, jdi s ním dvě.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 42, 'A prosícímu tebe dej, a od toho, kdo by chtěl vypůjčiti od tebe, neodvracuj se.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 43, 'Slyšeli jste, že říkáno bylo: Milovati budeš bližního svého, a nenáviděti budeš nepřítele svého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 44, 'Ale jáť vám pravím: Milujte nepřátely své, dobrořečte těm, kteříž vás proklínají, dobře čiňte nenávidícím vás, a modlte se za ty, kteříž vás utiskují a vám se protiví,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 45, 'Abyste byli synové Otce svého, kterýž jest v nebesích; nebo slunci svému velí vzchoditi na dobré i na zlé, a déšť dává na spravedlivé i na nespravedlivé.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 46, 'Nebo milujete-li ty, kdož vás milují, jakou odplatu máte? Zdaliž i publikáni téhož nečiní?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 47, 'A budete-li pozdravovati toliko bratří svých, což více činíte? Však i publikáni to činí.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 48, 'Buďtež vy tedy dokonalí, jako i Otec váš, kterýž jest v nebesích, dokonalý jest.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 1, 'Pilně se varujte, abyste almužny své nedávali před lidmi, proto abyste vidíni byli od nich, jinak nebudete míti odplaty u Otce svého, kterýž jest v nebesích.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 2, 'Protož když dáváš almužnu, netrub před sebou, jako pokrytci činí v školách a na ryncích, aby chváleni byli od lidí. Amen pravím vám, majíť odplatu svou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 3, 'Ale ty když almužnu dáváš, nechť neví levice tvá, co činí pravice tvá,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 4, 'Aby almužna tvá byla v skrytě, Otec pak tvůj, kterýž vidí v skrytě, odplatí tobě zjevně.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 5, 'A když bys se modlil, nebývej jako pokrytci. Obyčej zajisté mají, v školách a na úhlech ulic stojíce, modliti se, aby byli vidíni od lidí. Amen pravím vám, žeť mají odplatu svou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 6, 'Ale ty když bys se modlil, vejdi do pokojíka svého, a zavra dvéře své, modliž se Otci svému, kterýž jest v skrytě, a Otec tvůj, kterýž vidí v skrytě, odplatí tobě zjevně.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 7, 'Modléce se pak, nebuďtež marnomluvní jako pohané; nebo se domnívají, že pro tu svou mnohomluvnost vyslyšáni budou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 8, 'Nepřirovnávejtež se tedy jim, neboť ví Otec váš, čeho jest vám potřebí, prvé než byste vy ho prosili.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 9, 'A protož vy takto se modlte: Otče náš, kterýž jsi v nebesích, posvěť se jméno tvé.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 10, 'Přiď království tvé. Buď vůle tvá jako v nebi tak i na zemi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 11, 'Chléb náš vezdejší dej nám dnes.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 12, 'A odpusť nám viny naše, jakož i my odpouštíme vinníkům našim.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 13, 'I neuvoď nás v pokušení, ale zbav nás od zlého. Nebo tvé jest království, i moc, i sláva, na věky, Amen.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 14, 'Nebo jestliže odpustíte lidem poklésky jejich, odpustíť i vám nebeský Otec váš.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 15, 'Jestliže pak neodpustíte lidem pádů jejich, aniž Otec váš odpustí vám pádů vašich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 16, 'Když byste se pak postili, nebývejtež jako pokrytci zasmušilí; neboť pošmuřují tváří svých, aby vědomé bylo lidem, že se postí. Amen pravím vám, vzaliť jsou odplatu svou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 17, 'Ty pak, když se postíš, pomaž hlavy své a tvář svou umej,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 18, 'Aby nebylo zjevné lidem, že se postíš, ale Otci tvému, kterýž jest v skrytě. A Otec tvůj, kterýž vidí v skrytosti, odplatí tobě zjevně.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 19, 'Neskládejte sobě pokladů na zemi, kdež mol a rez kazí, a kdež zloději vykopávají a kradou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 20, 'Ale skládejte sobě poklady v nebi, kdež ani mol ani rez nekazí, a kdež zloději nevykopávají ani nekradou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 21, 'Nebo kdež jest poklad váš, tuť jest i srdce vaše.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 22, 'Svíce těla jestiť oko; protož jestliže by oko tvé sprostné bylo, všecko tělo tvé světlé bude.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 23, 'Pakliť by oko tvé bylo nešlechetné, všecko tělo tvé tmavé bude. Jestliže tedy světlo, kteréž jest v tobě, jest tma, sama tma jaká bude?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 24, 'Žádný nemůže dvěma pánům sloužiti. Neb zajisté jednoho nenáviděti bude, a druhého milovati, aneb jednoho přídržeti se bude, a druhým pohrdne. Nemůžte Bohu sloužiti i mammoně.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 25, 'Protož pravím vám: Nepečujte o život svůj, co byste jedli a co pili, ani o tělo své, čím byste se odívali. Zdaliž není život více nežli pokrm, a tělo nežli oděv?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 26, 'Hleďte na ptactvo nebeské, žeť nesejí ani žnou, ani shromažďují do stodol, ale Otec váš nebeský živí je. I zdaliž vy jich mnohem nepřevyšujete?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 27, 'A kdo z vás pečlivě mysle, může přidati ku postavě své loket jeden?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 28, 'A o oděv proč se staráte? Považte kvítí polního, kterak roste, nepracuje ani přede.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 29, 'Pravímť pak vám, že ani Šalomoun ve vší slávě své tak odín nebyl, jako jedno z nich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 30, 'Poněvadž tedy trávu polní, ješto dnes jest, a zítra do peci bývá vložena, Bůh tak odívá, i zdaliž mnohem více vás neodívá, ó malé víry?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 31, 'Nepečujtež tedy, říkajíce: Co budeme jísti? aneb co budeme píti? aneb čím se budeme odívati?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 32, 'Nebo toho všeho pohané hledají. Víť zajisté Otec váš nebeský, že toho všeho potřebujete.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 33, 'Ale hledejte nejprv království Božího a spravedlnosti jeho, a toto vše bude vám přidáno.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 34, 'Protož nepečujte o zítřejší den, nebo zítřejší den pečovati bude o své věci. Dostiť má den na svém trápení.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 1, 'Nesuďtež, abyste nebyli souzeni.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 2, 'Nebo kterýmž soudem soudíte, týmž budete souzeni, a kterou měrou měříte, bude vám zase odměřeno.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 3, 'Kterakž pak vidíš mrvu v oku bratra svého, a v oku svém břevna neznamenáš?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 4, 'Aneb kterak díš bratru svému: Nech ať vyjmu mrvu z oka tvého? A aj, břevno v oku tvém.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 5, 'Pokrytče, vyjmi nejprv břevno z oka svého, a tehdy prohlédneš, abys vyňal mrvu z oka bratra svého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 6, 'Nedávejte svatého psům, aniž mecte perel svých před svině, aťby snad nepotlačily jich nohama svýma, a obrátíce se, neroztrhaly vás.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 7, 'Proste, a dánoť bude vám; hledejte, a naleznete; tlucte, a bude vám otevříno.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 8, 'Nebo každý, kdož prosí, béře; a kdož hledá, nalézá; a tomu, kdož tluče, bude otevříno.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 9, 'An který z vás jest člověk, jehož kdyby prosil syn jeho za chléb, dal by jemu kámen?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 10, 'A prosil-li by za rybu, zdali dá jemu hada?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 11, 'Poněvadž tedy vy, jsouce zlí, umíte dobré dary dávati dětem svým, čím více Otec váš, kterýž jest v nebesích, dá dobré věci těm, kteříž ho, prosí?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 12, 'A protož všecko, jakž byste chtěli, aby vám lidé činili, tak i vy čiňte jim; toť zajisté jest zákon i proroci.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 13, 'Vcházejte těsnou branou; nebo prostranná brána a široká cesta jest, kteráž vede k zahynutí, a mnoho jest těch, kteříž vcházejí skrze ni.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 14, 'Nebo těsná jest brána a úzká cesta, kteráž vede k životu, a málo jest nalézajících ji.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 15, 'Pilně se pak varujte falešných proroků, kteříž přicházejí k vám v rouše ovčím, ale vnitř jsou vlci hltaví.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 16, 'Po ovocích jejich poznáte je. Zdaliž zbírají z trní hrozny, aneb z bodláčí fíky?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 17, 'Takť každý strom dobrý ovoce dobré nese, zlý pak strom zlé ovoce nese.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 18, 'Nemůžeť dobrý strom zlého ovoce nésti, ani strom zlý ovoce dobrého vydávati.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 19, 'Všeliký strom, kterýž nenese ovoce dobrého, vyťat a na oheň uvržen bývá.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 20, 'A tak tedy po ovocích jejich poznáte je.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 21, 'Ne každý, kdož mi říká: Pane, Pane, vejde do království nebeského, ale ten, kdož činí vůli Otce mého, kterýž v nebesích jest.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 22, 'Mnozíť mi dějí v onen den: Pane, Pane, zdaliž jsme ve jménu tvém neprorokovali, a ve jménu tvém ďáblů nevymítali, a v tvém jménu divů mnohých nečinili?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 23, 'A tehdyť jim vyznám, že jsem vás nikdy neznal. Odejděte ode mne, činitelé nepravosti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 24, 'A protož každého, kdož slyší slova má tato a plní je, připodobním muži moudrému, kterýž ustavěl dům svůj na skále.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 25, 'I spadl příval, a přišly řeky, a váli větrové, a obořili se na ten dům, ale nepadl; nebo založen byl na skále.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 26, 'Každý pak, kdož slyší slova má tato, a neplní jich, připodobněn bude muži bláznu, kterýž ustavěl dům svůj na písku.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 27, 'I spadl příval, a přišly řeky, a váli větrové, a obořili se na ten dům, i padl, a byl pád jeho veliký.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 28, 'Stalo se pak, když dokonal Ježíš řeči tyto, že se převelmi divili zástupové učení jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 29, 'Nebo učil je jako moc maje, a ne jako zákonníci.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 1, 'A když sstupoval s hory, šli za ním zástupové mnozí.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 2, 'A aj, malomocný přišed, klaněl se jemu, řka: Pane, kdybys jen chtěl, můžeš mne očistiti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 3, 'I vztáh Ježíš ruku, dotekl se ho, řka: Chci, buď čist. A hned očištěno jest malomocenství jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 4, 'I dí jemu Ježíš: Viziž, abys žádnému nepravil. Ale jdi, ukaž se knězi, a obětuj dar ten, kterýž přikázal Mojžíš, na svědectví jim.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 5, 'A když vcházel Ježíš do Kafarnaum, přistoupil k němu setník, prose ho,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 6, 'A řka: Pane, služebník můj leží doma šlakem poražený, velmi se trápě.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 7, 'I dí jemu Ježíš: Já přijdu a uzdravím ho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 8, 'A odpovídaje setník, řekl: Pane, nejsemť hoden, abys všel pod střechu mou, ale toliko rci slovo, a uzdraven bude služebník můj.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 9, 'Nebo i já jsem člověk pod mocí, maje pod sebou žoldnéře, a dím-li tomuto: Jdi, tedy jde, a jinému: Přiď, a přijde, a služebníku svému: Učiň toto, a učiní.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 10, 'To uslyšev Ježíš, podivil se, a jdoucím za sebou řekl: Amen pravím vám, ani v Izraeli tak veliké víry jsem nenalezl.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 11, 'Pravím pak vám, žeť přijdou mnozí od východu i od západu, a stoliti budou s Abrahamem, s Izákem a s Jákobem v království nebeském,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 12, 'Ale synové království vyvrženi budou do temností zevnitřních. Tamť bude pláč a škřipení zubů.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 13, 'I řekl Ježíš setníkovi: Jdiž, a jakžs uvěřil, staň se tobě. I uzdraven jest služebník jeho v tu hodinu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 14, 'A přišed Ježíš do domu Petrova, uzřel svegruši jeho, ana leží, a má zimnici.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 15, 'I dotekl se ruky její, a přestala jí zimnice. I vstala a posluhovala jim.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 16, 'A když byl večer, přivedli k němu mnohé, kteříž ďábelství měli, a on vymítal duchy slovem, a všecky, kteříž se zle měli, uzdravil,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 17, 'Aby se naplnilo povědění skrze Izaiáše proroka, řkoucího: Onť vzal na se mdloby naše, a neduhy nesl.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 18, 'Vida pak Ježíš zástupy mnohé okolo sebe, kázal přeplaviti se na druhou stranu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 19, 'A přistoupiv jeden zákonník, řekl jemu: Mistře, půjdu za tebou, kamžkoli půjdeš.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 20, 'I dí jemu Ježíš: Lišky doupata mají, a ptactvo nebeské hnízda, ale Syn člověka nemá, kde by hlavu sklonil.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 21, 'Jiný pak z učedlníků jeho řekl jemu: Pane, dopusť mi prvé odjíti a pochovati otce mého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 22, 'Ale Ježíš řekl jemu: Poď za mnou, a nech ať mrtví pochovávají mrtvé své.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 23, 'A když vstoupil na lodí, vstoupili za ním i učedlníci jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 24, 'A aj, bouře veliká stala se na moři, tak že vlny přikrývaly lodí. On pak spal.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 25, 'A přistoupivše učedlníci jeho, zbudili jej, řkouce: Pane, zachovej nás, hynemeť.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 26, 'I dí jim: Proč se bojíte, ó malé víry? Tehdy vstav, přimluvil větrům a moři, i stalo se utišení veliké.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 27, 'Lidé pak divili se, řkouce: Kteraký jest tento, že ho i větrové i moře poslouchají?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 28, 'A když se přeplavil na druhou stranu do krajiny Gergezenských, potkali se s ním dva ďábelníci z hrobů vyšlí, ukrutní náramně, tak že žádný nemohl tou cestou choditi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 29, 'A aj, volali, řkouce: Co je nám po tobě, Ježíši, Synu Boží? Přišel jsi sem před časem trápiti nás.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 30, 'A bylo opodál od nich stádo veliké vepřů, pasoucích se.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 31, 'Ďáblové pak prosili ho, řkouce: Jestliže nás vymítáš, dopustiž nám vjíti do toho stáda vepřů.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 32, 'I řekl jim: Jděte. A oni vyšedše, vešli do stáda těch vepřů. A aj, hnalo se prudce všecko stádo těch vepřů s vrchu dolů do moře, i ztonuli v vodách.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 33, 'Pastýři pak utekli. A přišedše do města, vypravovali to všecko, i o těch ďábelnících.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 34, 'A aj, všecko město vyšlo v cestu Ježíšovi, a uzřevše ho, prosili, aby šel z končin jejich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 1, 'A vstoupiv na lodí, přeplavil se, a přišel do města svého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 2, 'A aj, přinesli mu šlakem poraženého, ležícího na loži. A viděv Ježíš víru jejich, dí šlakem poraženému: Doufej, synu, odpuštěniť jsou tobě hříchové tvoji.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 3, 'A aj, někteří z zákonníků řekli sami v sobě: Tento se rouhá.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 4, 'A viděv Ježíš myšlení jejich, řekl: Proč vy myslíte zlé věci v srdcích svých?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 5, 'Nebo co jest snáze říci: Odpuštěniť jsou tobě hříchové, čili říci: Vstaň a choď?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 6, 'Ale abyste věděli, žeť má moc Syn člověka na zemi odpouštěti hříchy, tehdy dí šlakem poraženému: Vstana, vezmi na sebe lože své, a jdi do domu svého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 7, 'Tedy vstav, odšel do domu svého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 8, 'A vidouce to zástupové, divili se a velebili Boha, kterýž dal takovou moc lidem.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 9, 'A jda odtud Ježíš, uzřel člověka sedícího na cle, jménem Matouše. I dí mu: Poď za mnou. I vstav, šel za ním.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 10, 'Stalo se pak, když seděl Ježíš za stolem v domě, a aj, mnozí celní a hříšníci přišedše, stolili s Ježíšem a s učedlníky jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 11, 'A vidouce to farizeové, řekli učedlníkům jeho: Proč s celnými a hříšníky jí mistr váš?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 12, 'Ježíš pak uslyšev to, řekl jim: Nepotřebujíť zdraví lékaře, ale nemocní.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 13, 'Jdouce pak, učte se, co jest to: Milosrdenství chci a ne oběti. Nebo nepřišel jsem volati spravedlivých, ale hříšných ku pokání.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 14, 'Tehdy přistoupili k němu učedlníci Janovi, řkouce: Proč my a farizeové postíme se často, učedlníci pak tvoji se nepostí?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 15, 'I řekl jim Ježíš: Zdaliž mohou synové ženichovi rmoutiti se, dokudž s nimi jest ženich? Ale přijdou dnové, když bude od nich odjat ženich, a tehdyť se budou postiti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 16, 'Žádný zajisté nepřišívá záplaty sukna nového k rouchu vetchému; nebo ta záplata jeho odtrhla by díl od roucha, a větší by díra byla.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 17, 'Aniž lejí vína nového do nádob starých; sic jinak rozpuknou se sudové, a víno se vyleje, a sudové se zkazí. Ale víno nové lejí do nových nádob, a bývá obé zachováno.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 18, 'A když on to k nim mluvil, aj, kníže přistoupivši, klanělo se jemu, řkuc: Dcera má nyní umřela. Ale poď, vlož na ni ruku svou, a budeť živa.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 19, 'A vstav Ježíš, šel za ním, i učedlníci jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 20, '(A aj žena, kteráž nemocí svou trápena byla ode dvanácti let, přistoupivši po zadu, dotkla se podolka roucha jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 21, 'Nebo řekla sama v sobě: Dotknu-li se jen toliko roucha jeho, uzdravena budu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 22, 'Ježíš pak obrátiv se, a uzřev ji, řekl: Doufej, dcero, víra tvá tě uzdravila. I ozdravěla ta žena té chvíle.)');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 23, 'Přišed pak Ježíš do domu knížete, a uzřev trubače i zástup hlučící,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 24, 'Řekl jim: Odejdětež; nebo neumřela děvečka, ale spí. I posmívali se jemu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 25, 'A když byl vyhnán zástup, všed tam, ujal ji za ruku její. I vstala ta děvečka.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 26, 'A roznesla se pověst ta po vší té zemi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 27, 'A když šel odtud Ježíš, šli za ním dva slepí, volajíce a řkouce: Smiluj se nad námi, Synu Davidův.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 28, 'A když všel do domu, přistoupili k němu ti slepí. I dí jim Ježíš: Věříte-li, že to mohu učiniti? Řekli jemu: Ovšem, Pane.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 29, 'Tedy dotekl se očí jejich, řka: Podlé víry vaší staň se vám.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 30, 'I otevříny jsou oči jejich. Zapověděl jim pak tuze Ježíš, řka: Viztež, ať nižádný nezví.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 31, 'Ale oni vyšedše, rozhlásali jej po vší té zemi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 32, 'A když oni vycházeli, aj, přivedli mu člověka němého, majícího ďábelství.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 33, 'A když vyvrženo bylo ďábelství, mluvil němý. I divili se zástupové, řkouce: Že nikdy nic nebylo vídáno takového v Izraeli.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 34, 'Farizeové pak pravili: Mocí knížete ďábelského vymítá ďábly.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 35, 'I obcházel Ježíš všecka města i městečka, uče v školách jejich a káže evangelium království, a uzdravuje všelikou nemoc i všeliký neduh v lidu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 36, 'A když hleděl na zástupy, slitovalo se mu jich, že byli opuštěni a rozptýleni jako ovce, nemajíce pastýře.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 37, 'Tehdy řekl učedlníkům svým: Žeň zajisté jest mnohá, ale dělníků málo.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 38, 'Protož proste Pána žně, ať vypudí dělníky na žeň svou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 1, 'A svolav dvanácte učedlníků svých, dal jim moc nad duchy nečistými, aby je vymítali, a aby uzdravovali všelikou nemoc, i všeliký neduh.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 2, 'Dvanácti pak apoštolů jména jsou tato: První Šimon, kterýž slove Petr, a Ondřej bratr jeho, Jakub Zebedeův a Jan bratr jeho,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 3, 'Filip a Bartoloměj, Tomáš a Matouš, kterýž býval celný, Jakub Alfeův a Lebbeus, přijmím Taddeus,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 4, 'Šimon Kananitský, a Jidáš Iškariotský, kterýž i zradil ho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 5, 'Těchto dvanácte poslal Ježíš, přikazuje jim, řka: Na cestu pohanů nechoďte, a do města Samaritánských nevcházejte.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 6, 'Ale raději jděte k ovcem zahynulým z domu Izraelského.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 7, 'Jdouce pak, kažte, řkouce: Že se přiblížilo království nebeské.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 8, 'Nemocné uzdravujte, malomocné čisťte, mrtvé křeste, ďábelství vymítejte; darmo jste vzali, darmo dejte.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 9, 'Nebeřte s sebou zlata, ani stříbra, ani peněz do opasků svých,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 10, 'Ani mošny na cestu, ani dvou sukní, ani obuvi, ani hůlky; hodenť jest zajisté dělník pokrmu svého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 11, 'A do kteréhožkoli města neb městečka vešli byste, vzeptejte se, kdo by v něm hodný byl, a tu pobuďte, až i vyjdete.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 12, 'A vcházejíce do domu, pozdravte ho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 13, 'A jestliže bude dům ten hodný, pokoj váš přijdiž naň; pakli by nebyl hodný, pokoj váš navratiž se k vám.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 14, 'A kdožkoli nepřijal by vás, a neuposlechl by řečí vašich, vyjdouce ven z domu neb z města toho, vyrazte prach z noh svých.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 15, 'Amen pravím vám: Lehčeji bude zemi Sodomských a Gomorských v den soudný nežli městu tomu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 16, 'Aj, já posílám vás jako ovce mezi vlky; protož buďte opatrní jako hadové, a sprostní jako holubice.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 17, 'Vystříhejte se pak lidí; neboť vás vydávati budou do sněmů, a v shromážděních svých budou vás bičovati.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 18, 'Ano i před vládaře i před krále vedeni budete pro mne, na svědectví proti nim, i národům.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 19, 'Když pak vás vydadí, nebuďtež pečliví, kterak aneb co byste mluvili; dánoť bude zajisté vám v tu hodinu, co budete míti mluviti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 20, 'Nebo ne vy jste, kteříž mluvíte, ale Duch Otce vašeho, kterýž mluví v vás.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 21, 'Vydáť pak bratr bratra na smrt, i otec syna, a povstanouť dítky proti rodičům, a zmordují je.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 22, 'A budete v nenávisti všechněm pro jméno mé, ale kdož setrvá až do konce, tenť spasen bude.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 23, 'Když se pak vám budou protiviti v tom městě, utecte do jiného. Amen zajisté pravím vám, nezchodíte měst Izraelských, až přijde Syn člověka.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 24, 'Neníť učedlník nad mistra, ani služebník nad pána svého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 25, 'Dostiť jest učedlníku, aby byl jako mistr jeho, a služebník jako pán jeho. Poněvadž hospodáře Belzebubem nazývali, čím pak více domácí jeho?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 26, 'Protož nebojte se jich; nebo není nic skrytého, což by nemělo býti zjeveno, ani tajného, ješto by nemělo zvědíno býti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 27, 'Což vám pravím ve tmách, pravte na světle, a co v uši slyšíte, hlásejte na domích.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 28, 'A nebojte se těch, kteříž mordují tělo, ale duše nemohou zamordovati; než raději se bojte toho, kterýž může i duši i tělo zatratiti v pekelném ohni.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 29, 'Zdaliž nebývají prodáváni dva vrabečkové za penízek? A však jeden z nich nepadá na zem bez Otce vašeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 30, 'Vaši pak i vlasové na hlavě všickni sečteni jsou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 31, 'Protož nebojte se, dražší jste vy nežli mnoho vrabců.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 32, 'Kdožkoli tedy vyzná mne před lidmi, vyznámť i já jej před Otcem svým, kterýž jest v nebesích.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 33, 'Kdož by pak mne zapřel před lidmi, zapřímť ho i já před Otcem svým, kterýž jest v nebesích.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 34, 'Nedomnívejte se, že bych přišel pokoj dáti na zemi. Nepřišelť jsem, abych pokoj uvedl, ale meč.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 35, 'Přišel jsem zajisté, abych rozdělil člověka proti otci jeho, a dceru proti mateři její, a nevěstu proti svegruši její.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 36, 'A nepřátelé člověka domácí jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 37, 'Kdo miluje otce neb matku více nežli mne, neníť mne hoden; a kdož miluje syna neb dceru více nežli mne, neníť mne hoden.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 38, 'A kdož nebéře kříže svého a nenásleduje mne, neníť mne hoden.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 39, 'Kdo nalezne duši svou, ztratíť ji; a kdo by ztratil duši svou pro mne, nalezneť ji.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 40, 'Kdo vás přijímá, mne přijímá; a kdo mne přijímá, přijímá toho, kterýž mne poslal.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 41, 'Kdo přijímá proroka ve jménu proroka, odplatu proroka vezme; a kdož přijímá spravedlivého ve jménu spravedlivého, odplatu spravedlivého vezme.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 42, 'A kdož by koli dal jednomu z těchto maličkých toliko číši vody studené k nápoji ve jménu učedlníka, zajisté pravím vám, neztratíť odplaty své.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 1, 'I stalo se, když přestal Ježíš těch přikázaní dávati dvanácti učedlníkům svým, bral se odtud, aby učil a kázal v městech jejich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 2, 'Jan pak uslyšev v vězení o skutcích Kristových, poslav dva z učedlníků svých,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 3, 'Řekl jemu: Ty-li jsi ten, kterýž přijíti má, čili jiného čekati máme?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 4, 'I odpovídaje Ježíš, řekl jim: Jdouce, zvěstujtež Janovi, co slyšíte a vidíte.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 5, 'Slepí vidí, a kulhaví chodí, malomocní se čistí, a hluší slyší, mrtví z mrtvých vstávají, a chudým evangelium se zvěstuje.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 6, 'A blahoslavený jest, kdož se nehorší na mně.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 7, 'A když oni odešli, počal Ježíš praviti zástupům o Janovi: Co jste vyšli na poušť viděti? Třtinu-li větrem se klátící?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 8, 'Aneb co jste vyšli viděti? Člověka-li měkkým rouchem oděného? Aj, kteříž se měkkým rouchem odívají, v domích královských jsou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 9, 'Aneb co jste vyšli viděti? Proroka-li? Jistě pravím vám, i více nežli proroka.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 10, 'Tento jest zajisté, o němž psáno: Aj, já posílám anděla svého před tváří tvou, kterýž připraví cestu tvou před tebou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 11, 'Amen pravím vám, mezi syny ženskými nepovstal větší nad Jana Křtitele; ale kdo jest nejmenší v království nebeském, jestiť větší nežli on.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 12, 'Ode dnů pak Jana Křtitele až dosavad království nebeské násilí trpí, a ti, kteříž násilí činí, uchvacujíť je.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 13, 'Nebo všickni proroci i ten zákon až do Jana prorokovali.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 14, 'A chcete-li přijíti, onť jest Eliáš, kterýž přijíti měl.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 15, 'Kdo má uši k slyšení, slyš.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 16, 'Ale k komu připodobním pokolení toto? Podobné jest dětem, sedícím na ryncích a na tovaryše své volajícím,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 17, 'A říkajícím: Pískali jsme vám, a neskákali jste; žalostně jsme naříkali, a neplakali jste.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 18, 'Přišel zajisté Jan, nejeda ani nepije, a řkou: Ďábelství má.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 19, 'Přišel Syn člověka, jeda a pije, a řkou: Aj, člověk žráč a piján vína, přítel publikánů a hříšníků. Ale ospravedlněna jest moudrost od synů svých.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 20, 'Tehdy počal přimlouvati městům, v nichž bylo činěno nejvíce divů jeho, že pokání nečinili:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 21, 'Běda tobě Korozaim, běda tobě Betsaido. Nebo kdyby v Týru a Sidonu byli činěni divové ti, kteříž jsou činěni v vás, dávno by byli v žíni a v popele pokání činili.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 22, 'Nýbrž pravím vám: Týru a Sidonu lehčeji bude v den soudný nežli vám.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 23, 'A ty Kafarnaum, kteréž jsi až k nebi vyvýšeno, až do pekla sstrčeno budeš. Nebo kdyby v Sodomě činěni byli divové ti, kteříž jsou činěni v tobě, byliť by zůstali až do dnes.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 24, 'Ano více pravím vám, že zemi Sodomských lehčeji bude v den soudný nežli tobě.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 25, 'V ten čas odpověděv Ježíš, řekl: Chválím tě, Otče, Pane nebe i země, že jsi skryl tyto věci před moudrými a opatrnými, a zjevil jsi je nemluvňátkům.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 26, 'Jistě, Otče, žeť se tak líbilo před tebou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 27, 'Všecky věci dány jsou mi od Otce mého, a žádnýť nezná Syna, jediné Otec, aniž Otce kdo zná, jediné Syn, a komuž by chtěl Syn zjeviti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 28, 'Poďtež ke mně všickni, kteříž pracujete a obtíženi jste, a já vám odpočinutí dám.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 29, 'Vezměte jho mé na se, a učte se ode mne, neboť jsem tichý a pokorný srdcem, a naleznete odpočinutí dušem svým.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 30, 'Jho mé zajisté jestiť rozkošné, a břímě mé lehké.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 1, 'V ten čas šel Ježíš v sobotu skrze obilí, učedlníci pak jeho lační jsouce, počali vymínati klasy a jísti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 2, 'Farizeové pak spatřivše to, řekli jemu: Hle, učedlníci tvoji činí, čehož nesluší činiti v sobotu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 3, 'On pak řekl jim: Co jste nečtli, co učinil David, když lačněl, on i ti, kteříž s ním byli?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 4, 'Kterak všel do domu Božího a chleby posvátné jedl, kterýchž jemu neslušelo jísti, ani těm, kteříž s ním byli, než toliko samým kněžím?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 5, 'Aneb zdali jste nečtli v zákoně, že kněží v sobotu v chrámě sobotu ruší, a jsou bez hříchu?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 6, 'Ale pravímť vám, že větší jest tuto nežli chrám.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 7, 'Než kdybyste věděli, co jest to: Milosrdenství chci a ne oběti, nepotupovali byste nevinných.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 8, 'Syn zajisté člověka jest pánem i soboty.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 9, 'A odšed odtud, přišel do školy jejich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 10, 'A aj, byl tu člověk, maje ruku uschlou. I tázali se ho, řkouce: Sluší-li v sobotu uzdravovati? aby jej obžalovali.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 11, 'On pak dí jim: Který z vás bude člověk, ješto by měl ovci jednu, a kdyby ta upadla do jámy v sobotu, i zdaliž nedosáhne jí a nevytáhne?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 12, 'A čím lepší jest člověk než ovce? A protož slušíť v sobotu dobře činiti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 13, 'Tedy řekl člověku tomu: Vztáhni tu ruku svou. I vztáhl, a přivedena jest k zdraví jako druhá.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 14, 'Farizeové pak vyšedše, drželi radu proti němu, kterak by jej zahladili.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 15, 'A věděv to Ježíš, šel odtud. I šli za ním zástupové mnozí, a uzdravil je všecky.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 16, 'A s pohrůžkou přikázal jim, aby ho nezjevovali,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 17, 'Aby se naplnilo povědění skrze Izaiáše proroka, řkoucího:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 18, 'Aj, služebník ten můj, kteréhož jsem vyvolil, ten milý můj, v němž se dobře zalíbilo duši mé. Položím Ducha svého na něj, a soud národům zvěstovati bude.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 19, 'Nebude se vaditi, ani křičeti, aniž kdo na ulicích uslyší hlas jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 20, 'Třtiny nalomené nedolomí, a lnu kouřícího se neuhasí, až i vypoví soud k vítězství.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 21, 'A ve jménu jeho národové doufati budou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 22, 'Tehdy přiveden k němu ďábelstvím posedlý, slepý a němý. I uzdravil jej, tak že ten slepý a němý i mluvil i viděl.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 23, 'I děsili se všickni zástupové a pravili: Není-liž tento ten Syn Davidův?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 24, 'Ale farizeové to uslyševše, řekli: Tento nevymítá ďáblů než skrze Belzebuba, kníže ďábelské.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 25, 'Ježíš pak znaje myšlení jejich, dí jim: Každé království rozdělené samo proti sobě spustne, a každé město neb dům proti sobě rozdělený nestane.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 26, 'A jestližeť satan satana vymítá, proti sobě rozdělen jest. Kterak tedy stane království jeho?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 27, 'A vymítám-liť já ďábly skrze Belzebuba, synové vaši skrze koho vymítají? Protož oni soudcové vaši budou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 28, 'Pakliť já Duchem Božím ďábly vymítám, přišloť jest jistě mezi vás království Boží.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 29, 'Aneb kterak kdo může do domu silného vjíti a jeho nádobí pobrati, leč by prvé svázal toho silného, a teprv by dům jeho obloupiti mohl?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 30, 'Kdož není se mnou, proti mně jest; a kdo neshromažďuje se mnou, rozptylujeť.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 31, 'Protož pravím vám: Všeliký hřích i rouhání bude lidem odpuštěno, ale rouhání proti Duchu nebude odpuštěno lidem.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 32, 'A kdyby kdo řekl slovo proti Synu člověka, bude jemu odpuštěno, ale kdož by mluvil proti Duchu svatému, nebude jemu odpuštěno, ani v tomto věku, ani v budoucím.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 33, 'Čiňtež aneb strom dobrý, i ovoce jeho dobré; aneb čiňte strom zlý, i ovoce jeho zlé. Neboť po ovoci strom bývá poznán.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 34, 'Pokolení ještěrčí, kterakž byste mohli dobré věci mluviti, jsouce zlí? Nebo z hojnosti srdce ústa mluví.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 35, 'Dobrý člověk z dobrého pokladu srdce vynáší dobré, a zlý člověk ze zlého pokladu vynáší zlé.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 36, 'Ale pravím vám, že z každého slova prázdného, kteréž mluviti budou lidé, vydadí počet v den soudný.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 37, 'Nebo z slov svých spravedliv budeš, a z řečí svých budeš odsouzen.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 38, 'Tehdy odpověděli někteří z zákonníků a farizeů, řkouce: Mistře, chceme od tebe znamení viděti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 39, 'On pak odpovídaje, dí jim: Pokolení zlé a cizoložné znamení hledá, ale znamení jemu nebude dáno, jediné to znamení Jonáše proroka.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 40, 'Nebo jakož byl Jonáš v břiše velryba tři dni a tři noci, takť bude Syn člověka v srdci země tři dni a tři noci.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 41, 'Muži Ninivitští stanou na soudu s pokolením tímto, a potupí je, proto že pokání činili k Jonášovu kázaní, a aj, víceť nežli Jonáš tuto.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 42, 'Královna od poledne povstane k soudu s pokolením tímto, a potupí je; nebo přijela od končin země, aby slyšela moudrost Šalomounovu, a aj, víceť tuto nežli Šalomoun.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 43, 'Když pak nečistý duch vyjde od člověka, chodí po místech suchých, hledaje odpočinutí, ale nenalézá.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 44, 'Tedy říká: Navrátím se do domu svého, odkudž jsem vyšel. A přijda, nalezne prázdný, vyčištěný a ozdobený.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 45, 'Tedy jde a vezme s sebou sedm jiných duchů horších, nežli jest sám, a vejdouce, přebývají tam, i bývají poslední věci člověka toho horší nežli první. Takť se stane i tomuto zlému pokolení.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 46, 'A když on ještě mluvil k zástupům, aj, matka a bratří jeho stáli vně, žádajíce s ním promluviti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 47, 'I řekl jemu jeden: Aj, matka tvá i bratří tvoji stojí vně, chtíce s tebou mluviti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 48, 'On pak odpovídaje, řekl tomu, kterýž jemu pověděl: Kdo jest matka má? A kdo jsou bratří moji?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 49, 'A vztáhna ruku svou na učedlníky své, řekl: Aj, matka má i bratří moji.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 50, 'Nebo kdož by koli činil vůli Otce mého nebeského, ten jest bratr můj, i sestra má, i matka má.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 1, 'A v ten den vyšed Ježíš z domu, sedl podlé moře.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 2, 'I sešli se k němu zástupové mnozí, tak že vstoupiv na lodí, seděl, všecken pak zástup stál na břehu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 3, 'I mluvil jim mnoho v podobenstvích, řka: Aj, vyšel rozsevač, aby rozsíval.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 4, 'A když on rozsíval, některá padla podlé cesty, a přiletěli ptáci, i szobali je.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 5, 'Jiná pak padla na místa skalnatá, kdež neměla mnoho země; a rychle vzešla, proto že neměla hlubokosti země.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 6, 'Ale když slunce vzešlo, vyhořela, a proto že neměla kořene, uschla.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 7, 'Jiná pak padla do trní; i zrostlo trní, a udusilo je.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 8, 'A jiná padla v zemi dobrou; i vydalo užitek, některé stý, jiné šedesátý a jiné třidcátý.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 9, 'Kdo má uši k slyšení, slyš.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 10, 'Tedy přistoupivše učedlníci, řekli jemu: Proč jim v podobenstvích mluvíš?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 11, 'On pak odpověděv, řekl jim: Proto že vám dáno jest znáti tajemství království nebeského, ale jim není dáno.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 12, 'Nebo kdož má, dáno bude jemu, a rozhojníť se; ale kdož nemá, i to, což má, bude od něho odjato.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 13, 'Protoť v podobenstvích mluvím jim, že vidouce, nevidí, a slyšíce, neslyší, ani rozumějí.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 14, 'A plní se na nich proroctví Izaiáše, řkoucí: Slyšením slyšeti budete, ale nesrozumíte; a hledíce, hleděti budete, a nepoznáte.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 15, 'Nebo ztučnělo srdce lidu tohoto, a ušima těžce slyšeli, a oči své zamhouřili, aby někdy neviděli očima, a ušima neslyšeli, a srdcem nesrozuměli, a neobrátili se, abych jich neuzdravil.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 16, 'Ale oči vaše blahoslavené, že vidí, i uši vaše, že slyší.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 17, 'Amen zajisté pravím vám, že mnozí proroci a spravedliví žádali viděti to, co vidíte, ale neviděli, a slyšeti to, což slyšíte, ale neslyšeli.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 18, 'Vy tedy slyšte podobenství rozsevače.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 19, 'Každý, kdož slyší slovo o tom království a nerozumí, přichází ten zlý a uchvacuje to, což jest vsáto v srdce jeho. To jest ten, kterýž podlé cesty vsát jest.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 20, 'V skalnatou pak zemi vsátý jest ten, kterýž slyší slovo, a hned je s radostí přijímá.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 21, 'Než nemá v sobě kořene, ale jest časný, a když přichází ssoužení neb protivenství pro slovo, hned se horší.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 22, 'Mezi trní pak vsátý jest ten, kterýž slyší slovo, ale pečování tohoto světa a oklamání zboží udušuje slovo, i bývá bez užitku.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 23, 'V dobrou pak zemi vsátý ten jest, kterýž slyší slovo a rozumí, totiž kterýž užitek nese. Neseť pak někdo stý, a jiný šedesátý, jiný pak třidcátý.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 24, 'Jiné podobenství předložil jim, řka: Podobno jest království nebeské člověku, rozsívajícímu dobré semeno na poli svém.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 25, 'Když pak lidé zesnuli, přišel nepřítel jeho, a nasál koukole mezi pšenici, a odšel.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 26, 'A když zrostla bylina a užitek přinesla, tedy ukázal se i koukol.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 27, 'I přistoupivše služebníci hospodáře toho, řekli jemu: Pane, zdaližs dobrého semene nenasál na poli svém? Kde že se pak vzal koukol?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 28, 'A on řekl jim: Nepřítel člověk to učinil. Služebníci pak řekli mu: Chceš-liž tedy, ať jdeme a vytrháme jej?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 29, 'On pak odpověděl: Nikoli, abyste trhajíce koukol, spolu s ním nevytrhali pšenice.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 30, 'Nechte ať obé spolu roste až do žně. A v čas žně dím žencům: Vytrhejte nejprv koukol a svažte jej v snopky k spálení, ale pšenici shromažďte do stodoly mé.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 31, 'Jiné podobenství předložil jim, řka: Podobno jest království nebeské zrnu horčičnému, kteréž vzav člověk, vsál na poli svém.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 32, 'Kteréžto zajisté nejmenší jest mezi všemi semeny, když pak zroste, větší jest nežli jiné byliny, a bývá strom, tak že ptáci nebeští přiletíce, hnízda sobě dělají na ratolestech jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 33, 'Jiné podobenství mluvil jim: Podobno jest království nebeské kvasu, kterýž vzavši žena, zadělala ve třech měřicích mouky, až by zkysalo všecko.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 34, 'Toto všecko mluvil Ježíš v podobenstvích k zástupům, a bez podobenství nemluvil jim,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 35, 'Aby se naplnilo povědění skrze proroka, řkoucího: Otevru v podobenstvích ústa svá, vypravovati budu skryté věci od založení světa.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 36, 'Tedy propustiv zástupy, šel domů Ježíš. I přistoupili k němu učedlníci jeho, řkouce: Vylož nám podobenství o koukoli toho pole.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 37, 'On pak odpovídaje, řekl jim: Rozsevač dobrého semene jest Syn člověka.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 38, 'A pole jest tento svět, dobré pak símě jsou synové království, ale koukol jsou synové toho zlostníka.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 39, 'A nepřítel, kterýž jej rozsívá, jestiť ďábel, žeň pak jest skonání světa, a ženci jsou andělé.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 40, 'Protož jakož vybrán bývá koukol a ohněm spálen, takť bude při skonání tohoto světa.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 41, 'Pošle Syn člověka anděly své, i vyberouť z království jeho všecka pohoršení, i ty, kteříž činí nepravost,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 42, 'A uvrhouť je do peci ohnivé. Tamť bude pláč a škřipení zubů.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 43, 'A tehdážť spravedliví stkvíti se budou jako slunce v království Otce svého. Kdo má uši k slyšení, slyš.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 44, 'Opět podobno jest království nebeské pokladu skrytému v poli, kterýž nalezna člověk, skrývá, a radostí naplněn jsa pro něj, odchází a prodává všecko, což má, a koupí pole to.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 45, 'Opět podobno jest království nebeské člověku kupci, hledajícímu pěkných perel.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 46, 'Kterýž když nalezl jednu velmi drahou perlu, odšed, prodal všecko, což měl, a koupil ji.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 47, 'Opět podobno jest království nebeské vrši puštěné do moře, a ze všelikého plodu shromažďující.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 48, 'Kteroužto, když naplněna byla, vytáhše na břeh a sedíce, vybírali, což dobrého bylo, do nádob, a což bylo zlého, preč zamítali.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 49, 'Takť bude při skonání světa. Vyjdou andělé, a oddělí zlé z prostředku spravedlivých,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 50, 'A uvrhou je do peci ohnivé. Tamť bude pláč a škřipení zubů.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 51, 'Dí jim Ježíš: Srozuměli-li jste tomuto všemu? Řekli jemu: I ovšem, Pane.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 52, 'On pak řekl jim: Protož každý učitel umělý v království nebeském podobný jest člověku hospodáři, kterýž vynáší z pokladu svého nové i staré věci.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 53, 'I stalo se, když dokonal Ježíš podobenství ta, bral se odtud.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 54, 'A přišed do vlasti své, učil je v škole jejich, tak že se velmi divili, a říkali: Odkud má tento moudrost tuto a moc?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 55, 'Zdaliž tento není syn tesařův? Zdaliž matka jeho neslove Maria, a bratří jeho Jakub a Jozes a Šimon a Judas?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 56, 'A sestry jeho zdaliž všecky u nás nejsou? Odkudž tedy má tyto všecky věci?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 57, 'I zhoršili se na něm. Ježíš pak řekl jim: Neníť prorok beze cti, než v své vlasti a v domě svém.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 58, 'I neučinil tu mnoho divů pro nevěru jejich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 1, 'V tom čase uslyšel Heródes čtvrták pověst o Ježíšovi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 2, 'I řekl služebníkům svým: To jest Jan Křtitel. Onť jest vstal z mrtvých, a protož se divové dějí skrze něho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 3, 'Nebo jav Heródes Jana, svázal jej byl a dal do žaláře, pro Herodiadu manželku Filipa bratra svého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 4, 'Nebo byl řekl jemu Jan: Nesluší tobě míti jí.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 5, 'A chtěv zabiti jej, bál se lidu; nebo za proroka jej měli.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 6, 'Když pak slaven byl den narození Heródesova, tancovala dcera Herodiady u prostřed, i zalíbila se Heródesovi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 7, 'Pročež s přísahou zaslíbil jí dáti, zač by ho jen požádala.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 8, 'A ona jsuci prvé navedena od mateře své, řekla: Dej mi zde na mise hlavu Jana Křtitele.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 9, 'I zarmoutil se král, ale pro přísahu a pro ty, kteříž spolu s ním stolili, rozkázal dáti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 10, 'A poslav kata, sťal Jana v žaláři.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 11, 'I přinesena jest hlava jeho na mise, a dána té děvečce. I nesla mateři své.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 12, 'A přišedše učedlníci jeho, vzali tělo a pochovali je; a šedše, pověděli Ježíšovi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 13, 'To uslyšev Ježíš, plavil se odtud na lodičce na místo pusté soukromí. Což uslyševše zástupové, šli za ním pěšky z měst.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 14, 'A vyšed Ježíš, uzřel zástup mnohý. I slitovalo mu se jich, a uzdravoval nemocné jejich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 15, 'A když bylo k večerou, přistoupili k němu učedlníci jeho, řkouce: Pusté jest místo toto, a čas již pominul. Propusť zástupy, ať jdouce do městeček, nakoupí sobě pokrmů.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 16, 'Ježíš pak řekl jim: Není jim potřebí odcházeti, dejte vy jim jísti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 17, 'A oni řkou jemu: Nemáme zde, než pět chlebů a dvě rybě.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 18, 'On pak dí jim: Přinestež mi je sem.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 19, 'A rozkázav zástupu posaditi se na trávě, a vzav těch pět chlebů a dvě rybě, vzhléd v nebe, požehnal, a lámaje, dával učedlníkům ty chleby, a učedlníci zástupům.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 20, 'I jedli všickni a nasyceni jsou. I sebrali, což zbylo drobtů, dvanácte košů plných.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 21, 'Těch pak, kteříž jedli, bylo okolo pěti tisíců mužů, kromě žen a dětí.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 22, 'A i hned přinutil Ježíš učedlníky své, aby vstoupili na lodí a předešli jej na druhou stranu, dokudž by nepropustil zástupů.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 23, 'A propustiv zástupy, vstoupil na horu soukromí, aby se modlil. A když byl večer, sám byl tam.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 24, 'Lodí pak již byla u prostřed moře, zmítající se vlnami, nebo byl vítr odporný.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 25, 'Při čtvrtém pak bdění nočním bral se k nim Ježíš, jda po moři.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 26, 'A vidouce jej učedlníci po moři jdoucího, zlekali se, řkouce: Obluda jest. A strachem křičeli.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 27, 'Ale i hned Ježíš promluvil k nim, řka: Doufejtež, jáť jsem, nebojte se.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 28, 'I odpověděv jemu Petr, řekl: Pane, jestliže jsi ty, rozkaž mi k sobě přijíti po vodě.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 29, 'On pak řekl: Poď. A vystoupiv Petr z lodí, šel po vodě, aby přišel k Ježíšovi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 30, 'Ale vida vítr tuhý, bál se. A počav tonouti, zkřikl, řka: Pane, pomoz mi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 31, 'A i hned Ježíš vztáh ruku, ujal jej a řekl jemu, Ó malé víry, pročežs pochyboval?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 32, 'A jakž oni vstoupili na lodí, utišil se vítr.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 33, 'Ti pak, kteříž na lodí byli, přistoupivše, klaněli se jemu, řkouce: Jistě Syn Boží jsi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 34, 'A přeplavivše se, přišli do země Genezaretské.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 35, 'A poznavše jej muži místa toho, rozeslali po vší té krajině vůkol, a shromáždili k němu všecky neduživé.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 36, 'A prosili ho, aby se aspoň podolka roucha jeho dotkli. A kteřížkoli dotkli se, uzdraveni jsou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 1, 'A v tom přistoupí k Ježíšovi Jeruzalémští zákonníci a farizeové, řkouce:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 2, 'Proč učedlníci tvoji přestupují ustanovení starších? Nebo neumývají rukou svých, když mají jísti chléb.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 3, 'A on odpovídaje, řekl jim: Proč i vy přestupujete přikázaní Boží pro ustanovení svá?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 4, 'Nebo přikázal Bůh, řka: Cti otce svého i matku, a kdož by zlořečil otci neb mateři, smrtí ať umře.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 5, 'Ale vy pravíte: Kdož by koli řekl otci neb mateři: Dar jest to, čímž by tobě ode mne pomoženo býti mohlo. A neuctil by otce svého neb mateře své.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 6, 'I zlehčili jste přikázaní Boží pro své ustanovení.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 7, 'Pokrytci, dobře prorokoval o vás Izaiáš, řka:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 8, 'Přibližuje se ke mně lid tento ústy svými, a rty mne ctí, ale srdce jejich daleko jest ode mne.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 9, 'Ale nadarmoť mne ctí, učíce učení přikázaní lidských.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 10, 'A svolav zástup, řekl jim: Slyšte a rozumějte.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 11, 'Ne to, což vchází v ústa, poškvrňuje člověka, ale což z úst pochází, toť poškvrňuje člověka.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 12, 'Tehdy přistoupivše učedlníci jeho, řekli mu: Víš-li, že farizeové, slyševše tu řeč, zhoršili se?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 13, 'A on odpovídaje, řekl: Všeliké štípení, jehož neštípil Otec můj ten nebeský, vykořeněno bude.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 14, 'Nechte jich, vůdcovéť jsou slepí slepých. Povede-liť pak slepý slepého, oba v jámu upadnou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 15, 'I odpověděv Petr, řekl jemu: Vylož nám to podobenství.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 16, 'Ježíš pak řekl: Ještě i vy bez rozumu jste?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 17, 'Nerozumíte-liž, že všecko, což v ústa vchází, do břicha jde, a vypouští se ven?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 18, 'Ale které věci z úst pocházejí, z srdce jdou, a tyť poškvrňují člověka.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 19, 'Z srdce zajisté vycházejí zlá myšlení, vraždy, cizoložstva, smilstva, krádeže, křivá svědectví, rouhání.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 20, 'Tyť jsou věci poškvrňující člověka. Ale neumytýma rukama jísti, toť nepoškvrňuje člověka.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 21, 'A vyšed odtud Ježíš, bral se do krajin Tyrských a Sidonských.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 22, 'A aj, žena Kananejská z končin těch vyšedši, volala, řkuci jemu: Smiluj se nade mnou, Pane, synu Davidův. Dceru mou hrozně trápí ďábelství.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 23, 'On pak neodpověděl jí slova. I přistoupivše učedlníci jeho, prosili ho, řkouce: Odbuď ji, neboť volá za námi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 24, 'On pak odpověděv, řekl: Nejsem poslán než k ovcem zahynulým z domu Izraelského.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 25, 'Ale ona přistoupivši, klaněla se jemu, řkuci: Pane, pomoz mi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 26, 'On pak odpověděv, řekl: Není slušné vzíti chléb dětem a vrci štěňatům.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 27, 'A ona řekla: Takť jest, Pane. A však štěňátka jedí drobty, kteříž padají z stolů pánů jejich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 28, 'Tedy odpovídaje Ježíš, řekl jí: Ó ženo, veliká jest víra tvá. Staniž se tobě, jakž chceš. I uzdravena jest dcera její v tu hodinu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 29, 'A odšed odtud Ježíš, šel k moři Galilejskému, a vstoupiv na horu, posadil se tam.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 30, 'I přišli k němu zástupové mnozí, majíce s sebou kulhavé, slepé, němé, polámané a jiné mnohé. I kladli je k nohám Ježíšovým, a on je uzdravoval,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 31, 'Tak že se zástupové divili, vidouce, ano němí mluví, polámaní zdraví jsou, kulhaví chodí, slepí vidí. I velebili Boha Izraelského.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 32, 'Ježíš pak svolav učedlníky své, řekl: Líto mi zástupu. Nebo již tři dni trvají se mnou, a nemají, co by jedli; a propustiti jich lačných nechci, aby nezhynuli na cestě.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 33, 'I řkou mu učedlníci jeho: Kde bychom vzali tolik chleba na této poušti, abychom takový zástup nasytili?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 34, 'I řekl jim Ježíš: Kolik chlebů máte? A oni řkou: Sedm, a málo rybiček.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 35, 'I rozkázal zástupům, aby se posadili na zemi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 36, 'A vzav těch sedm chlebů a ty ryby, učiniv díky, lámal a dal učedlníkům svým, učedlníci pak zástupu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 37, 'I jedli všickni a nasyceni jsou. A sebrali, což zbylo drobtů, sedm košů plných.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 38, 'Bylo pak těch, kteříž jedli, čtyři tisíce mužů, kromě žen a dětí.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 39, 'A rozpustiv zástupy, vstoupil na lodí. I přišel do krajiny Magdala.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 1, 'I přistoupivše farizeové a saduceové, pokoušejíce, prosili ho, aby jim znamení s nebe ukázal.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 2, 'On pak odpovídaje, řekl jim: Když bývá večer, říkáte: Jasno bude, nebo se červená nebe.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 3, 'A ráno: Dnes bude nečas, nebo se červená zasmušilé nebe. Pokrytci, způsob zajisté nebe rozsouditi umíte, znamení pak časů těchto nemůžete?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 4, 'Národ zlý a cizoložný znamení hledá, ale znamení jemu nebude dáno, než toliko znamení ono Jonáše proroka. A opustiv je, odšel.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 5, 'A plavivše se učedlníci jeho přes moře, zapomenuli vzíti chleba.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 6, 'Ježíš pak řekl jim: Hleďte a varujte se kvasu farizejského a saducejského.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 7, 'Oni pak rozjímali mezi sebou, řkouce: Nevzali jsme chleba.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 8, 'A znaje to Ježíš, řekl jim: Co to rozjímáte mezi sebou, ó malé víry, že jste chlebů nevzali?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 9, 'Ještě-liž nerozumíte, ani nepamatujete na těch pět chlebů a na pět tisíců, a kolik jste košů nazbírali?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 10, 'Ani na těch sedm chlebů, a na čtyři tisíce, a kolik jste košů nazbírali?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 11, 'I kterakž nerozumíte, že ne o chlebu mluvil jsem vám, pravě, abyste se varovali kvasu farizejského a saducejského?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 12, 'Tedy srozuměli, že neřekl, aby se varovali od kvasu chleba, ale od učení farizeů a saduceů.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 13, 'Přišed pak Ježíš do krajin Cesaree Filipovy, otázal se učedlníků svých, řka: Kým praví lidé býti mne, Syna člověka?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 14, 'A oni řekli: Někteří Janem Křtitelem, jiní pak Eliášem, jiní pak Jeremiášem, aneb jedním z proroků.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 15, 'I dí jim: Vy pak kým mne býti pravíte?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 16, 'I odpověděv Šimon Petr, řekl: Ty jsi Kristus, ten Syn Boha živého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 17, 'A odpovídaje Ježíš, řekl mu: Blahoslavený jsi Šimone, synu Jonášův; nebo tělo a krev nezjevilo tobě, ale Otec můj, kterýž jest v nebesích.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 18, 'I jáť pravím tobě, že jsi ty Petr, a na téť skále vzdělám církev svou, a brány pekelné nepřemohou jí.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 19, 'A tobě dám klíče království nebeského. A což bys koli svázal na zemi, budeť svázáno i na nebi; a což bys koli rozvázal na zemi, budeť rozvázáno i na nebi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 20, 'Tedy přikázal učedlníkům svým, aby žádnému nepravili, že by on byl ten Ježíš Kristus.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 21, 'A od té chvíle počal Ježíš oznamovati učedlníkům svým, že musí jíti do Jeruzaléma, a mnoho trpěti od starších a předních kněží {biskupů} a od zákonníků, a zabit býti, a třetího dne z mrtvých vstáti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 22, 'I odved ho Petr, počal mu přimlouvati, řka: Odstup to od tebe, Pane, nikoli nestane se tobě toho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 23, 'Kterýžto obrátiv se, řekl Petrovi: Jdi za mnou, satane, ku pohoršení jsi mi; nebo nechápáš těch věcí, kteréž jsou Boží, ale kteréž jsou lidské.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 24, 'Tedy řekl Ježíš učedlníkům svým: Chce-li kdo za mnou přijíti, zapřiž sebe sám, a vezmi kříž svůj, a následujž mne.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 25, 'Nebo kdož by chtěl duši svou zachovati, ztratíť ji; kdož by pak ztratil duši svou pro mne, nalezneť ji.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 26, 'Nebo co jest platno člověku, by všecken svět získal, své pak duši uškodil? Aneb kterou dá člověk odměnu za duši svou?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 27, 'Syn zajisté člověka přijde v slávě Otce svého s anděly svými, a tehdáž odplatí jednomu každému podlé skutků jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 28, 'Amen pravím vám: Jsou někteří z stojících tuto, kteříž neokusí smrti, až i uzří Syna člověka, přicházejícího v království svém.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 1, 'A po šesti dnech pojal Ježíš Petra a Jakuba a Jana bratra jeho, i uvedl je na horu vysokou soukromí,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 2, 'A proměnil se před nimi. I zastkvěla se tvář jeho jako slunce, roucho pak jeho učiněno bílé jako světlo.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 3, 'A aj, ukázali se jim Mojžíš a Eliáš, rozmlouvající s ním.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 4, 'A odpověděv Petr, řekl Ježíšovi: Pane, dobré jest nám tuto býti. Chceš-li, uděláme tuto tři stánky, tobě jeden a Mojžíšovi jeden a Eliášovi jeden.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 5, 'Když pak on ještě mluvil, aj, oblak světlý zastínil je. A aj, hlas z toho oblaku řkoucí: Tentoť jest ten můj milý Syn, v němž mi se dobře zalíbilo, toho poslouchejte.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 6, 'To uslyšavše učedlníci, padli na tváři své a báli se velmi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 7, 'A přistoupiv Ježíš, dotekl se jich, řka: Vstaňte a nebojte se.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 8, 'Pozdvihše pak očí svých, žádného neviděli, než samého Ježíše.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 9, 'Když pak sstupovali s té hory, přikázal jim Ježíš, řka: Žádnému nepravte tohoto vidění, dokudž by Syn člověka nevstal z mrtvých.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 10, 'I otázali se ho učedlníci jeho, řkouce: Což to pak zákonníci praví, že má Eliáš prvé přijíti?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 11, 'Ježíš pak odpovídaje, řekl jim: Eliáš zajisté přijde prvé, a napraví všecky věci.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 12, 'Ale pravím vám, že Eliáš již přišel, a však nepoznali ho, ale učinili mu, což chtěli. Takť i Syn člověka trpěti bude od nich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 13, 'Tedy srozuměli učedlníci, že jim to pravil o Janovi Křtiteli.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 14, 'A když přišli k zástupu, přistoupil k němu člověk, a poklekl před ním na kolena,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 15, 'A řekl: Pane, smiluj se nad synem mým, nebo náměsičník jest, a těžce se trápí. Často zajisté padá do ohně a častokrát do vody.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 16, 'I přivedl jsem ho učedlníkům tvým, ale nemohli ho uzdraviti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 17, 'Odpovídaje pak Ježíš, řekl: Ó národe nevěrný a převrácený, dokud budu s vámi? Dokudž vás snášeti budu? Přiveďte mi jej sem.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 18, 'I přimluvil tomu ďábelství Ježíš. I vyšlo od něho; a uzdraven jest ten mládenec v tu hodinu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 19, 'Tedy přistoupivše učedlníci k Ježíšovi soukromí, řekli: Proč jsme my ho nemohli vyvrci?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 20, 'Ježíš pak řekl jim: Pro nevěru svou. Amen zajisté pravím vám: Budete-li míti víru jako zrno horčičné, díte hoře této: Přejdi odsud tam, i přejde, a nebudeť vám nic nemožného.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 21, 'Toto pak pokolení nevychází, jediné skrze modlitbu a půst.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 22, 'A když byli v Galilei, řekl jim Ježíš: Syn člověka bude vydán v ruce lidské,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 23, 'A zamordujíť jej, ale třetího dne z mrtvých vstane. I zarmoutili se náramně.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 24, 'A když přišli do Kafarnaum, přistoupili ku Petrovi ti, kteříž plat vybírali, a řekli: Což mistr váš nedává platu?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 25, 'A on řekl: Dává. A když přišel domů, předšel jej Ježíš, řka: Co se tobě zdá, Šimone? Králové zemští od kterých berou daň aneb plat? Od synů-li svých, čili od cizích?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 26, 'Dí jemu Petr: Od cizích. I řekl mu Ježíš: Tedy synové jsou svobodní.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 27, 'Ale abychom jich nepohoršili, jda k moři, vrz udici, a tu rybu, kteráž nejprvé uvázne, vezmi, a otevra ústa její, nalezneš groš. Ten vezma, dej jim za mne i za sebe.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 1, 'V ten čas přistoupili učedlníci k Ježíšovi, řkouce: Kdo pak jest největší v království nebeském?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 2, 'A zavolav Ježíš pacholátka, postavil je u prostřed nich,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 3, 'A řekl: Amen pravím vám: Neobrátíte-li se a nebudete-li jako pacholátka, nikoli nevejdete do království nebeského.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 4, 'Protož kdož by se koli ponížil jako pacholátko toto, tenť jest největší v království nebeském.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 5, 'A kdož by koli přijal pacholátko takové ve jménu mém, mneť přijímá.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 6, 'Kdo by pak pohoršil jednoho z maličkých těchto věřících ve mne, lépe by jemu bylo, aby zavěšen byl žernov osličí na hrdlo jeho, a pohřížen byl do hlubokosti mořské.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 7, 'Běda světu pro pohoršení. Ačkoli musí býti, aby přicházela pohoršení, ale však běda člověku, skrze něhož přichází pohoršení.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 8, 'Protož jestliže ruka tvá aneb noha tvá pohoršuje tě, utniž ji a vrz od sebe. Lépe jest tobě do života vjíti kulhavému aneb bezrukému, nežli dvě ruce aneb dvě noze majícímu uvrženu býti do ohně věčného.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 9, 'A pakli oko tvé pohoršuje tebe, vylup je a vrz od sebe. Lépe jest tobě jednookému do života vjíti, nežli obě oči majícímu uvrženu býti do pekelného ohně.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 10, 'Viztež, abyste nepotupovali žádného z maličkých těchto. Neboť pravím vám, že andělé jejich v nebesích vždycky hledí na tvář Otce mého, kterýž v nebesích jest.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 11, 'Přišel zajisté Syn člověka, aby spasil to, což bylo zahynulo.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 12, 'Co se vám zdá? Kdyby některý člověk měl sto ovec, a zbloudila by jedna z nich, zdaliž nenechá těch devadesáti devíti, a jda na hory, nehledá té pobloudilé?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 13, 'A nahodí-liť mu se nalezti ji, amen pravím vám, že se raduje nad ní více, než nad těmi devadesáti devíti nepobloudilými.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 14, 'Takť není vůle Otce vašeho, kterýž jest v nebesích, aby zhynul jeden z maličkých těchto.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 15, 'Zhřešil-li by pak proti tobě bratr tvůj, jdi a potresci ho mezi sebou a jím samým. Uposlechl-li by tebe, získal jsi bratra svého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 16, 'Jestliže by pak neuposlechl, přijmi k sobě ještě jednoho aneb dva, aby v ústech dvou neb tří svědků stálo každé slovo.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 17, 'Pakliť by jich neuposlechl, pověz církvi. Jestliže pak i církve neuposlechne, budiž tobě jako pohan a publikán.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 18, 'Amen pravím vám: Cožkoli svížete na zemi, budeť svázáno i na nebi; a cožkoli rozvížete na zemi, budeť rozvázáno i na nebi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 19, 'Opět pravím vám: Jestliže by dva z vás svolili se na zemi o všelikou věc, za kterouž by koli prosili, staneť se jim od Otce mého nebeského.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 20, 'Nebo kdežkoli shromáždí se dva neb tři ve jménu mém, tuť jsem já u prostřed nich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 21, 'Tedy přistoupiv k němu Petr, řekl: Pane, kolikrát zhřeší proti mně bratr můj, a odpustím jemu? Do sedmi-likrát?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 22, 'I dí mu Ježíš: Nepravím tobě až do sedmikrát, ale až do sedmdesátikrát sedmkrát.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 23, 'A protož podobno jest království nebeské člověku králi, kterýž chtěl počet klásti s služebníky svými.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 24, 'A když počal klásti, podán mu jeden, kterýž byl dlužen deset tisíců hřiven.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 25, 'A když neměl čím zaplatiti, kázal jej pán jeho prodati, i ženu jeho i děti i všecko, což měl, a zaplatiti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 26, 'Tedy padna služebník ten, klaněl se jemu, řka: Pane, poshověj mi, a všecko zaplatím tobě.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 27, 'I slitovav se pán nad služebníkem tím, propustil ho a dluh jemu odpustil.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 28, 'Vyšed pak služebník ten, nalezl jednoho z spoluslužebníků svých, kterýž mu byl dlužen sto peněz, a chopiv se ho, hrdloval se s ním, řka: Zaplať mi, cos dlužen.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 29, 'Tedy padna spoluslužebník ten k nohám jeho, prosil ho, řka: Poshověj mi, a všecko zaplatím tobě.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 30, 'On pak nechtěl, ale odšed, dal jej do žaláře, dokudž by nezaplatil dluhu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 31, 'Vidouce pak spoluslužebníci jeho, co se dálo, zarmoutili se velmi; a šedše, pověděli pánu svému všecko, co se bylo stalo.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 32, 'Tehdy povolav ho pán jeho, dí mu: Služebníče zlý, všecken ten dluh odpustil jsem tobě, nebs mne prosil.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 33, 'Zdaliž i ty neměl se smilovati nad spoluslužebníkem svým, jako i já smiloval jsem se nad tebou?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 34, 'I rozhněvav se pán jeho, dal jej katům, dokudž by nezaplatil všeho, což mu byl dlužen.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 35, 'Takť i Otec můj nebeský učiní vám, jestliže neodpustíte jeden každý bratru svému z srdcí svých provinění jejich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 1, 'I stalo se, když dokonal Ježíš řeči tyto, bral se z Galilee, a přišel do končin Judských za Jordán.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 2, 'I šli za ním zástupové mnozí, a uzdravil je tam.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 3, 'I přistoupili k němu farizeové, pokoušejíce ho a řkouce jemu: Sluší-li člověku propustiti manželku svou z kterékoli příčiny?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 4, 'On pak odpovídaje, řekl jim: Což jste nečtli, že ten, kterýž stvořil s počátku, muže a ženu učinil je?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 5, 'A řekl: Protož opustí člověk otce i matku, a připojí se k manželce své, i budou dva jedno tělo.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 6, 'A tak již nejsou dva, ale jedno tělo. A protož, což Bůh spojil, člověk nerozlučuj.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 7, 'Řekli jemu: Pročež tedy Mojžíš rozkázal dáti lístek rozloučení, a propustiti ji?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 8, 'Dí jim: Mojžíš pro tvrdost srdce vašeho dopustil vám propouštěti manželky vaše, ale s počátku nebylo tak.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 9, 'Protož pravím vám: Že kdožkoli propustil by manželku svou, (leč pro smilství,) a jinou pojme, cizoloží, i kdož propuštěnou pojme, cizoloží.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 10, 'Řekli jemu učedlníci jeho: Poněvadž jest taková pře s manželkou, není dobré ženiti se.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 11, 'On pak řekl jim: Ne všickniť chápají slova toho, ale ti, jimž jest dáno.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 12, 'Jsouť zajisté panicové, kteříž se tak z života matky zrodili; a jsouť panicové, kteříž učiněni jsou od lidí; a jsouť panicové, kteříž se sami v panictví oddali pro království nebeské. Kdo může pochopiti, pochop.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 13, 'Tehdy přineseny jsou k němu dítky, aby na ně ruce vzkládal a modlil se. Učedlníci pak přimlouvali jim.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 14, 'Ale Ježíš řekl: Nechte dítek a nebraňte jim jíti ke mně; nebo takovýchť jest království nebeské.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 15, 'A po vzkládání na ně rukou odebral se odtud.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 16, 'A aj, jeden přistoupiv, řekl jemu: Mistře dobrý, co dobrého budu činiti, abych měl život věčný?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 17, 'Ale on řekl jemu: Co mne nazýváš dobrým? Žádný není dobrý, než jediný, totiž Bůh. Chceš-li pak vjíti do života, ostříhej přikázaní.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 18, 'Dí jemu: Kterých? Ježíš pak řekl: Nezabiješ, nezcizoložíš, nepokradeš, nepromluvíš křivého svědectví.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 19, 'Cti otce svého i matku, a milovati budeš bližního svého jako sebe samého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 20, 'Dí jemu mládenec: Všeho toho ostříhal jsem od své mladosti. Čehož mi se ještě nedostává?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 21, 'Řekl mu Ježíš: Chceš-li dokonalým býti, jdiž a prodej statek svůj, a rozdej chudým, a budeš míti poklad v nebi, a poď, následuj mne.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 22, 'Uslyšev pak mládenec tu řeč, odšel, smuten jsa; nebo měl statku mnoho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 23, 'Ježíš pak řekl učedlníkům svým: Amen pravím vám, že bohatý nesnadně vejde do království nebeského.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 24, 'A opět pravím vám: Snázeť jest velbloudu skrze uši jehly projíti, nežli bohatému vjíti do království Božího.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 25, 'A uslyšavše to učedlníci jeho, užasli se velmi, řkouce: I kdož tedy může spasen býti?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 26, 'Pohleděv pak Ježíš, řekl jim: U lidíť jest to nemožné, ale u Boha všecko jest možné.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 27, 'Tehdy odpověděv Petr, řekl mu: Aj, my opustili jsme všecky věci, a šli jsme za tebou. Což pak nám bude?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 28, 'Ježíš pak řekl jim: Amen pravím vám, že vy, kteříž jste následovali mne, v druhém narození, když se posadí Syn člověka na trůnu velebnosti své, sednete i vy na dvanácti trůních, soudíce dvanáctero pokolení Izraelské.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 29, 'A každý, kdož opustil by domy, neb bratry, neb sestry, neb otce, neb matku, neb manželku, neb dítky, neb pole pro jméno mé, stokrát více vezme, a život věčný dědičně obdrží.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 30, 'Mnozí pak první budou poslední, a poslední první.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 1, 'Nebo podobno jest království nebeské člověku hospodáři, kterýž vyšel na úsvitě, aby najal dělníky na vinici svou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 2, 'Smluviv pak s dělníky z peníze denního, odeslal je na vinici svou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 3, 'A vyšed okolo hodiny třetí, uzřel jiné, ani stojí na trhu zahálejíce.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 4, 'I těm řekl: Jdětež i vy na vinici, a co bude spravedlivého, dám vám.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 5, 'A oni šli. Opět vyšed při šesté a deváté hodině, učinil též.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 6, 'Při jedenácté pak hodině vyšed, nalezl jiné, ani stojí zahálejíce. I řekl jim: Pročež tu stojíte, celý den zahálejíce?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 7, 'Řkou jemu: Nebo nižádný nás nenajal. Dí jim: Jdětež i vy na vinici, a což by bylo spravedlivého, vezmete.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 8, 'Večer pak řekl pán vinice šafáři svému: Zavolej dělníků a zaplať jim, počna od posledních až do prvních.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 9, 'A přišedše ti při jedenácté hodině najatí, vzali jeden každý po penízi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 10, 'Přišedše pak první, domnívali se, že více vezmou, ale vzali i oni jeden každý po penízi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 11, 'A vzavše, reptali proti hospodáři,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 12, 'Řkouce: Tito poslední jednu hodinu dělali, a rovné jsi je nám učinil, kteříž jsme nesli břímě dne i horko.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 13, 'On pak odpovídaje, řekl jednomu z nich: Příteli, nečiním tobě křivdy. Zdaliž jsi z peníze nesmluvil se mnou?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 14, 'Vezmiž, což tvého jest, a jdi předce, já pak chci tomuto poslednímu dáti jako i tobě.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 15, 'Zdaliž mi nesluší v mém učiniti, což chci? Čili oko tvé nešlechetné jest, že já dobrý jsem?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 16, 'Takť budou poslední první, a první poslední; nebo mnoho jest povolaných, ale málo vyvolených.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 17, 'A vstupuje Ježíš do Jeruzaléma, pojal dvanácte učedlníků soukromí na cestě. I řekl jim:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 18, 'Aj, vstupujeme do Jeruzaléma, a Syn člověka vydán bude předním kněžím {biskupům} a zákonníkům, a odsoudí ho na smrt.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 19, 'A vydadíť jej pohanům ku posmívání a k zbičování a ukřižování, ale třetího dne z mrtvých vstane.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 20, 'Tehdy přistoupila k němu matka synů Zebedeových s syny svými, klanějici se a proseci něco od něho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 21, 'Kterýž řekl jí: Co chceš? Řekla jemu: Rci, ať tito dva synové moji sedají, jeden po pravici tvé a druhý po levici, v království tvém.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 22, 'Odpovídaje pak Ježíš, řekl: Nevíte, zač prosíte. Můžete-li píti kalich, kterýž já píti budu, a křtem, jímž já se křtím, křtěni býti? Řekli jemu: Můžeme.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 23, 'Dí jim: Kalich zajisté můj píti budete, a křtem, jímž já se křtím, pokřtěni budete, ale seděti po pravici mé a po levici mé, neníť mé dáti, ale těm, kterýmž připraveno jest od Otce mého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 24, 'A uslyšavše to deset jiných, rozhněvali se na ty dva bratry.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 25, 'Ale Ježíš svolav je, řekl: Víte, že knížata národů panují nad nimi, a kteříž velicí jsou, moci užívají nad nimi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 26, 'Ale ne tak bude mezi vámi. Nýbrž kdožkoli chtěl by mezi vámi býti velikým, budiž služebník váš.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 27, 'A kdož by koli mezi vámi chtěl býti přední, budiž váš služebník;');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 28, 'Jako i Syn člověka nepřišel, aby jemu slouženo bylo, ale aby on sloužil, a aby dal život svůj mzdu na vykoupení za mnohé.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 29, 'A když vycházeli z Jericho, šel za ním zástup veliký.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 30, 'A aj, dva slepí sedící u cesty, uslyšavše, že by Ježíš tudy šel, zvolali, řkouce: Smiluj se nad námi, Pane, synu Davidův.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 31, 'Zástup pak přimlouval jim, aby mlčeli. Oni pak více volali, řkouce: Smiluj se nad námi, Pane, synu Davidův.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 32, 'I zastaviv se Ježíš, zavolal jich, a řekl: Co chcete, abych vám učinil?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 33, 'Řkou jemu: Pane, ať se otevrou oči naše.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 34, 'I slitovav se nad nimi Ježíš, dotekl se očí jejich, a hned prohlédly oči jejich. I šli za ním.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 1, 'A když se přiblížili k Jeruzalému, a přišli do Betfage k hoře Olivetské, tedy Ježíš poslal dva učedlníky své,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 2, 'Řka jim: Jdětež do městečka, kteréž proti vám jest, a hned naleznete oslici přivázanou a oslátko s ní. Odvěžtež je a přiveďte ke mně.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 3, 'A řekl-liť by kdo co vám, rcete, že Pán jich potřebuje, a hnedť propustí je.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 4, 'Toto se pak všecko stalo, aby se naplnilo povědění skrze proroka, řkoucího:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 5, 'Povězte dceři Sionské: Aj, král tvůj béře se tobě tichý, a sedě na oslici, a na oslátku té jhu podrobené.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 6, 'I jdouce učedlníci, a učinivše tak, jakž jim byl přikázal Ježíš,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 7, 'Přivedli oslici i oslátko, a vložili na ně roucha svá, a jej na vrchu na ně posadili.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 8, 'Mnohý pak zástup stlali roucha svá na cestě, jiní pak ratolesti z stromů sekali, a metali na cestu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 9, 'A zástupové, kteříž s předu i s zadu šli, volali, řkouce: Hosanna synu Davidovu. Požehnaný, kterýž se béře ve jménu Páně. Hosanna na výsostech.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 10, 'A když vjel do Jeruzaléma, zbouřilo se všecko město, řkouce: I kdo jest tento?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 11, 'Zástupové pak pravili: Toto jest ten Ježíš, prorok z Nazaréta Galilejského.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 12, 'I všel Ježíš do chrámu Božího, a vymítal všecky prodávající a kupující v chrámě, a stoly penězoměnců a stolice prodávajících holubice převracel,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 13, 'A řekl jim: Psánoť jest: Dům můj dům modlitby slouti bude, ale vy učinili jste jej peleší lotrovskou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 14, 'I přistoupili k němu slepí a kulhaví v chrámě, a uzdravil je.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 15, 'Vidouce pak přední kněží {biskupové} a zákonníci divy, kteréž činil, a dítky, any volají v chrámě a praví: Hosanna synu Davidovu, rozhněvali se.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 16, 'A řekli jemu: Slyšíš-liž, co tito praví? Ježíš pak řekl jim: I ovšem. Nikdá-liž jste nečtli, že z úst nemluvňátek a těch, kteříž prsí požívají, dokonal jsi chválu?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 17, 'A opustiv je, šel ven z města do Betany, a tu zůstal.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 18, 'Ráno pak navracuje se do města, zlačněl.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 19, 'A vida jeden fíkový strom podlé cesty, šel k němu, a nic na něm nenalezl, než lístí toliko. I dí jemu: Nikdy více neroď se z tebe ovoce na věky. I uschl fík ten pojednou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 20, 'A vidouce to učedlníci, divili se, řkouce: Kterak hned usechl fík ten!');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 21, 'I odpověděv Ježíš, řekl jim: Amen pravím vám: Budete-li míti víru a nebudete-li pochybovati, netoliko to fíkovému stromu učiníte, ale kdybyste i této hoře řekli: Zdvihni se a vrz sebou do moře, staneť se.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 22, 'A všecko, zač byste koli prosili na modlitbě, věříce, vezmete.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 23, 'A když přišel do chrámu, přistoupili k němu přední kněží {biskupové} a starší lidu, když učil, řkouce: Jakou mocí tyto věci činíš? A kdo tobě tu moc dal?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 24, 'Odpovídaje pak Ježíš, řekl jim: Otížiť se i já vás na jednu věc, kterouž povíte-li mi, i já vám povím, jakou mocí tyto věci činím?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 25, 'Křest Janův odkud byl? S nebe-li, čili z lidí? A oni rozvažovali mezi sebou, řkouce: Díme-li s nebe, díť nám: Proč jste pak nevěřili jemu?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 26, 'Pakli díme: Z lidí, bojíme se zástupu. Nebo všickni mají Jana za proroka.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 27, 'I odpovídajíce Ježíšovi, řekli: Nevíme. Řekl jim i on: Aniž já vám povím, jakou mocí tyto věci činím.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 28, 'Ale co se vám zdá? Člověk jeden měl dva syny. A přistoupiv k prvnímu, řekl: Synu, jdi na vinici mou dnes, a dělej.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 29, 'Ale on odpověděv, řekl: Nechci. A potom usmysliv sobě, šel.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 30, 'I přistoupiv k druhému, řekl též. A on odpověděv, řekl: Jdu, pane. Ale nešel.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 31, 'Který z těch dvou naplnil vůli otcovu? Řekli jemu: Ten první. Dí jim Ježíš: Amen pravím vám, že publikáni a nevěstky předcházejí vás do království Božího.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 32, 'Nebo přišel k vám Jan cestou spravedlnosti, a nevěřili jste mu, ale publikáni a nevěstky uvěřili jemu. Vy pak viděvše to, aniž jste potom usmyslili sobě, abyste věřili jemu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 33, 'Jiné podobenství slyšte: Byl jeden hospodář, kterýž vzdělal vinici, a opletl ji plotem, a vkopal v ní pres, a ustavěl věži, i pronajal ji vinařům, a odšel pryč přes pole.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 34, 'A když se přiblížil čas ovoce, poslal služebníky své k vinařům, aby vzali užitky její.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 35, 'Vinaři pak zjímavše služebníky jeho, jiného zmrskali, jiného zabili, a jiného ukamenovali.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 36, 'Opět poslal jiných služebníků více než prvé. I učinili jim též.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 37, 'Naposledy pak poslal k nim syna svého, řka: Ustýdnouť se syna mého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 38, 'Vinaři pak uzřevše toho syna, řekli mezi sebou: Tentoť jest dědic; poďte, zabíme jej, a uvažme se v dědictví jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 39, 'I chytivše ho, vyvrhli jej ven z vinice, a zabili.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 40, 'Protož když přijde pán vinice, co učiní vinařům těm?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 41, 'Řekli jemu: Zlé ty zle zatratí, a vinici svou pronajme jiným vinařům, kteříž budou vydávati jemu užitek časy svými.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 42, 'Řekl jim Ježíš: Nikdy-li jste nečtli v písmích: Kámen, kterýž zavrhli dělníci, ten učiněn jest v hlavu úhlovou? Ode Pána stalo se toto, a jest divné před očima našima.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 43, 'Protož pravím vám, že bude odjato od vás království Boží, a bude dáno lidu činícímu užitky jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 44, 'A kdož by padl na ten kámen, rozrazíť se; a na kohož upadne, setřeť jej.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 45, 'A slyšavše přední kněží {biskupové} ta podobenství jeho, porozuměli, že by o nich mluvil.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 46, 'I hledajíce ho jíti, báli se zástupů; nebo ho měli za proroka.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 1, 'I odpovídaje Ježíš, mluvil jim opět v podobenstvích, řka:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 2, 'Podobno jest království nebeské člověku králi, kterýž učinil svadbu synu svému.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 3, 'I poslal služebníky své, aby povolali pozvaných na svadbu, ale nechtěli přijíti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 4, 'Opět poslal jiné služebníky, řka: Povězte pozvaným: Aj, oběd svůj připravil jsem, volové moji a krmný dobytek zbit jest, a všecko hotovo. Poďtež na svadbu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 5, 'Ale oni nedbavše, odešli, jiný do vsi své, a jiný po kupectví svém.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 6, 'Jiní pak zjímavše služebníky jeho, a posměch jim učinivše, zmordovali.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 7, 'A uslyšav to král, rozhněval se; a poslav vojska svá, zhubil vražedlníky ty, a město jejich zapálil.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 8, 'Tedy řekl služebníkům svým: Svadba zajisté hotova jest, ale ti, kteříž pozváni byli, nebyli hodni.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 9, 'Protož jděte na rozcestí, a kteréžkoli naleznete, zovtež na svadbu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 10, 'I vyšedše služebníci ti na cesty, shromáždili všecky, kteréžkoli nalezli, zlé i dobré. A naplněna jest svadba hodovníky.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 11, 'Tehdy všed král, aby pohleděl na hodovníky, uzřel tam člověka neoděného rouchem svadebním.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 12, 'I řekl jemu: Příteli, kteraks ty sem všel, nemaje roucha svadebního? A on oněměl.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 13, 'Tedy řekl král služebníkům: Svížíce nohy jeho i ruce, vezměte ho, a uvrztež jej do temností těch zevnitřních. Tamť bude pláč a škřipení zubů.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 14, 'Nebo mnoho jest povolaných, ale málo vyvolených.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 15, 'Tehdy odšedše farizeové, radili se, jak by polapili jej v řeči.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 16, 'I poslali k němu učedlníky své s Herodiány, řkouce: Mistře, víme, že pravdomluvný jsi, a cestě Boží v pravdě učíš, a nedbáš na žádného; nebo nepatříš na osobu lidskou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 17, 'Protož pověz nám, co se tobě zdá: Sluší-li daň dáti císaři, čili nic?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 18, 'Znaje pak Ježíš zlost jejich, řekl: Co mne pokoušíte, pokrytci?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 19, 'Ukažte mi peníz daně. A oni podali mu peníze.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 20, 'I řekl jim: Čí jest tento obraz a nápis?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 21, 'Řekli mu: Císařův. Tedy dí jim: Dávejtež tedy, co jest císařova, císaři, a co Božího, Bohu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 22, 'To uslyšavše, divili se, a opustivše jej, odešli.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 23, 'V ten den přišli k němu saduceové, kteříž praví, že není z mrtvých vstání. I otázali se ho,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 24, 'Řkouce: Mistře, Mojžíš pověděl: Umřel-li by kdo, nemaje dětí, aby bratr jeho právem švagrovství pojal ženu jeho, a vzbudil símě bratru svému.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 25, 'I bylo u nás sedm bratrů. První pojav ženu, umřel, a nemaje semene, zůstavil ženu svou bratru svému.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 26, 'Takž podobně i druhý, i třetí, až do sedmého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 27, 'Nejposléze pak po všech umřela i žena.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 28, 'Protož při vzkříšení kterého z těch sedmi bude žena? Nebo všickni ji měli.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 29, 'I odpověděv Ježíš, řekl jim: Bloudíte, neznajíce písem ani moci Boží.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 30, 'Však při vzkříšení nebudou se ani ženiti ani vdávati, ale budou jako andělé Boží v nebi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 31, 'O vzkříšení pak mrtvých zdaliž jste nečtli, co jest vám povědíno od Boha, kterýž dí:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 32, 'Já jsem Bůh Abrahamův, a Bůh Izákův, a Bůh Jákobův? Bůhť není Bůh mrtvých, ale živých.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 33, 'A slyševše to zástupové, divili se učení jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 34, 'Farizeové pak uslyšavše, že by k mlčení přivedl saducejské, sešli se v jedno.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 35, 'I otázal se jeden z nich zákonník, pokoušeje ho, a řka:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 36, 'Mistře, které jest přikázaní veliké v zákoně?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 37, 'I řekl mu Ježíš: Milovati budeš Pána Boha svého z celého srdce svého, a ze vší duše své, a ze vší mysli své.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 38, 'To jest přední a veliké přikázaní.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 39, 'Druhé pak jest podobné tomu: Milovati budeš bližního svého jako sebe samého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 40, 'Na těch dvou přikázaních všecken zákon záleží i proroci.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 41, 'A když se sešli farizeové, otázal se jich Ježíš,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 42, 'Řka: Co se vám zdá o Kristu? Čí jest syn? Řkou jemu: Davidův.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 43, 'Dí jim: Kterakž pak David v Duchu nazývá ho Pánem, řka:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 44, 'Řekl Pán Pánu mému: Seď na pravici mé, dokudž nepoložím nepřátel tvých za podnože noh tvých?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 45, 'Poněvadž tedy David Pánem ho nazývá, i kterakž syn jeho jest?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 46, 'A nižádný nemohl jemu odpovědíti slova, aniž směl kdo více od toho dne jeho se tázati.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 1, 'Tehdy Ježíš mluvil zástupům a učedlníkům svým,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 2, 'Řka: Na stolici Mojžíšově posadili se zákonníci a farizeové.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 3, 'Protož všecko, což by koli rozkázali vám zachovávati, zachovávejte a čiňte, ale podlé skutků jejich nečiňte; neboť praví, ale nečiní.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 4, 'Svazujíť zajisté břemena těžká a nesnesitelná, a vzkládají na ramena lidská, ale prstem svým nechtí jimi ani pohnouti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 5, 'Všecky pak své skutky činí, aby byli vidíni od lidí. Rozšiřují zajisté nápisy své, a veliké dělají podolky plášťů svých,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 6, 'A milují přední místa na večeřích, a přední stolice v shromážděních,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 7, 'A pozdravování na trhu, a aby byli nazýváni od lidí: Mistři, mistři.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 8, 'Ale vy nebývejte nazýváni mistři; nebo jeden jest Mistr váš, Kristus, vy pak všickni bratří jste.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 9, 'A otce nenazývejte sobě na zemi; nebo jeden jest Otec váš, kterýž jest v nebesích.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 10, 'Ani se nazývejte vůdcové; nebo jeden jest vůdce váš, Kristus.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 11, 'Ale kdo z vás největší jest, buď služebníkem vaším.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 12, 'Kdož by pak sám se povyšoval, bude ponížen; a kdož by se ponížil, bude povýšen.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 13, 'Ale běda vám, zákonníci a farizeové pokrytci, že zavíráte království nebeské před lidmi; nebo sami tam nevcházíte, a těm, kteříž by vjíti chtěli, vcházeti nedopouštíte.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 14, 'Běda vám, zákonníci a farizeové pokrytci, že zžíráte domy vdovské, a to pod zámyslem dlouhého modlení; protož těžší soud ponesete.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 15, 'Běda vám, zákonníci a farizeové pokrytci, že obcházíte moře i zemi, abyste učinili jednoho novověrce, a když bude učiněn, učiníte jej syna zatracení, dvakrát více, nežli jste sami.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 16, 'Běda vám, vůdcové slepí, kteříž říkáte: Přisáhl-li by kdo skrze chrám, to nic není; ale kdo by přisáhl skrze zlato chrámové, povinen jest.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 17, 'Blázni a slepci, což jest většího, zlato-li, či chrám, kterýž posvěcuje zlata?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 18, 'A přisáhl-li by kdo skrze oltář, nic není; ale kdo by přisáhl skrze ten dar, kterýž jest na něm, povinen jest.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 19, 'Blázni a slepci, i co jest většího, dar-li, či oltář, kterýž posvěcuje daru?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 20, 'A protož kdožkoli přisahá skrze oltář, přisahá skrze něj, i skrze to všecko, což na něm jest.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 21, 'A kdož přisahá skrze chrám, přisahá skrze něj, i skrze toho, kterýž přebývá v něm.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 22, 'A kdož přisahá skrze nebe, přisahá skrze trůn Boží, i skrze toho, kterýž na něm sedí.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 23, 'Běda vám, zákonníci a farizeové pokrytci, že dáváte desátky z máty a z kopru a z kmínu, a opouštíte to, což těžšího jest v zákoně, soud a milosrdenství a věrnost. Tyto věci měli jste činiti a oněch neopouštěti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 24, 'Vůdcové slepí, kteříž cedíte komára, velblouda pak požíráte.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 25, 'Běda vám, zákonníci a farizeové pokrytci, že čistíte po vrchu konvice a misy, a vnitř plné jsou loupeže a nestředmosti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 26, 'Farizei slepče, vyčisť prvé to, což vnitř jest v konvi a v mise, aby i to, což jest zevnitř, bylo čisto.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 27, 'Běda vám, zákonníci a farizeové pokrytci, že jste se připodobnili hrobům zbíleným, kteříž sic zdadí se zevnitř krásní, ale vnitř jsou plní kostí umrlčích i vší nečistoty.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 28, 'Tak i vy zevnitř zajisté zdáte se lidem spravedliví, ale vnitř plní jste pokrytství a nepravosti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 29, 'Běda vám, zákonníci a farizeové pokrytci, nebo vzděláváte hroby proroků, a ozdobujete hroby spravedlivých,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 30, 'A říkáte: kdybychom byli za dnů otců našich, nebyli bychom účastníci jejich ve krvi proroků.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 31, 'Protož osvědčujete sami proti sobě, že jste synové těch, kteříž proroky zmordovali.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 32, 'I vy také naplňte míru otců svých.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 33, 'Hadové, plémě ještěrčí, i jakž byste ušli odsudku do pekelného ohně?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 34, 'Protož aj, já posílám k vám proroky a moudré a učitele, a vy z těch některé zmordujete a ukřižujete, a některé z nich bičovati budete v školách svých, a budete je honiti z města do města,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 35, 'Aby přišla na vás všeliká krev spravedlivá, vylitá na zemi, od krve Abele spravedlivého, až do krve Zachariáše syna Barachiášova, kteréhož jste zabili mezi chrámem a oltářem.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 36, 'Amen pravím vám: Přijdou tyto všecky věci na pokolení toto.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 37, 'Jeruzaléme, Jeruzaléme, mordéři proroků, a kterýž kamenuješ ty, kteříž byli k tobě posíláni, kolikrát jsem chtěl shromážditi dítky tvé, tak jako slepice shromažďuje kuřátka svá pod křídla, a nechtěli jste.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 38, 'Aj, zanecháváť se vám dům váš pustý.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 39, 'Neboť pravím vám, že mne již více nikoli neuzříte od této chvíle, až i díte: Požehnaný, kterýž se béře ve jménu Páně.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 1, 'A vyšed Ježíš, bral se z chrámu. I přistoupili učedlníci jeho, aby ukázali jemu stavení chrámové.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 2, 'Ježíš pak řekl jim: Vidíte-liž tyto všecky věci? Amen pravím vám: Nebude zůstaven tuto kámen na kameni, kterýž by nebyl zbořen.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 3, 'A když se posadil na hoře Olivetské, přistoupili k němu učedlníci soukromí, řkouce: Pověz nám, kdy to bude, a které znamení příchodu tvého a skonání světa?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 4, 'I odpověděv Ježíš, řekl jim: Vizte, aby vás někdo nesvedl.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 5, 'Nebo mnozí přijdou pod jménem mým, řkouce: Jáť jsem Kristus, a svedouť mnohé.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 6, 'Budete slýchati zajisté boje a pověsti bojů. Hleďtež, abyste se nekormoutili; nebo musí to všecko býti; ale ne i hned bude konec.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 7, 'Nebo povstane národ proti národu a království proti království, a budou hladové a morové a země třesení po místech.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 8, 'Ale tyto všecky věci jsou počátkové bolestí.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 9, 'A tehdy vydadí vás v ssoužení, a budou vás mordovati, a budete v nenávisti u všech národů pro jméno mé.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 10, 'A tehdyť se zhorší mnozí, a vespolek se budou zrazovati, a jedni druhých nenáviděti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 11, 'A mnozí falešní proroci povstanou, a svedou mnohé.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 12, 'A že rozmnožena bude nepravost, ustydne láska mnohých.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 13, 'Ale kdož by setrval až do konce, ten spasen bude.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 14, 'A bude kázáno toto evangelium království po všem světě, na svědectví všechněm národům, a tehdáž přijde skonání.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 15, 'Protož když uzříte ohavnost zpuštění, předpověděnou od Daniele proroka, ana stojí na místě svatém, (kdo čte, rozuměj,)');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 16, 'Tehdáž ti, kteříž by byli v Judstvu, nechť utekou na hory.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 17, 'A kdo na střeše, nesstupuj, aby něco vzal z domu svého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 18, 'A kdo na poli, nevracuj se zase, aby vzal roucha svá.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 19, 'Běda pak těhotným a těm, kteréž kojí v těch dnech.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 20, 'Protož modlte se, aby utíkání vaše nebylo v zimě aneb v svátek.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 21, 'Nebo bude tehdáž ssoužení veliké, jakéhož nebylo od počátku světa až do té chvíle, aniž kdy potom bude.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 22, 'A byť nebyli ukráceni dnové ti, nebyl by spasen žádný člověk. Ale pro vyvolené ukráceni budou ti dnové.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 23, 'Tehdy řekl-li by vám kdo: Aj, tutoť jest Kristus, aneb tamto, nevěřte.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 24, 'Nebo povstanou falešní Kristové a falešní proroci, a činiti budou divy veliké a zázraky, tak že by svedli, (by možné bylo,) také i vyvolené.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 25, 'Aj, předpověděl jsem vám.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 26, 'Protož řeknou-liť vám: Aj, na poušti jest, nevycházejte. Aj, v skrýších, nevěřte.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 27, 'Nebo jakož blesk vychází od východu slunce, a ukazuje se až na západ, tak bude i příchod Syna člověka.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 28, 'Nebo kdežkoli bude tělo, tuť se shromáždí i orlice.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 29, 'A hned po ssoužení těch dnů slunce se zatmí, a měsíc nedá světla svého, a hvězdy budou padati s nebe, a moci nebeské budou se pohybovati.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 30, 'Tehdážť se ukáže znamení Syna člověka na nebi, a tehdyť budou kvíliti všecka pokolení země, a uzříť Syna člověka přicházejícího na oblacích nebeských s mocí a slávou velikou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 31, 'Kterýž pošle anděly své s hlasem velikým trouby, i shromáždíť vyvolené jeho ode čtyř větrů, a od končin nebes až do končin jejich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 32, 'Od stromu pak fíkového naučte se podobenství tomuto: Když již ratolest jeho odmladne, a lístí se pučí, porozumíváte, že blízko jest léto.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 33, 'Takéž i vy, když byste uzřeli toto všecko, vězte, žeť blízko jest a ve dveřích.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 34, 'Amen pravím vám, že nepomine věk tento, až se tyto všecky věci stanou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 35, 'Nebe a země pominou, ale slova má nikoli nepominou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 36, 'O tom pak dni a hodině té žádný neví, ani andělé nebeští, jediné sám Otec můj.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 37, 'Ale jakož bylo za dnů Noé, takť bude i příchod Syna člověka.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 38, 'Nebo jakož za dnů těch před potopou žrali a pili, ženili se a vdávaly se, až do toho dne, když Noé všel do korábu,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 39, 'A nezvěděli, až přišla potopa, a zachvátila všecky: takť bude i příští Syna člověka.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 40, 'Tehdyť dva budou na poli; jeden bude vzat, a druhý zanechán.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 41, 'Dvě budou mleti ve mlýně; jedna bude vzata, a druhá zanechána.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 42, 'Bdětež tedy, poněvadž nevíte, v kterou hodinu Pán váš přijíti má.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 43, 'Toto pak vězte, že byť věděl hospodář, v které by bdění zloděj měl přijíti, bděl by zajisté, a nedal by podkopati domu svého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 44, 'Protož i vy buďte hotovi; nebo v tu hodinu, v kterouž se nenadějete, Syn člověka přijde.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 45, 'Kdož tedy jest ten služebník věrný a opatrný, kteréhož ustanovil pán jeho nad čeledí svou, aby jim dával pokrm v čas?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 46, 'Blahoslavený služebník ten, kteréhož přijda pán jeho, nalezl by, an tak činí.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 47, 'Amen pravím vám, že nade vším statkem svým ustanoví jej.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 48, 'Jestliže by pak řekl zlý služebník ten v srdci svém: Prodlívá pán můj přijíti,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 49, 'I počal by bíti spoluslužebníky, jísti pak a píti s opilci:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 50, 'Přijdeť pán služebníka toho v den, v kterýž se nenaděje, a v hodinu, v kterouž neví.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 51, 'I oddělíť jej, a díl jeho položí s pokrytci. Tamť bude pláč a škřipení zubů.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 1, 'Tehdy podobno bude království nebeské desíti pannám, kteréžto vzavše lampy své, vyšly proti ženichovi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 2, 'Pět pak z nich bylo opatrných, a pět bláznivých.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 3, 'Ty bláznivé vzavše lampy své, nevzaly s sebou oleje.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 4, 'Opatrné pak vzaly olej v nádobkách svých s lampami svými.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 5, 'A když prodlíval ženich, zdřímaly všecky a zesnuly.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 6, 'O půlnoci pak stal se křik: Aj, ženich jde, vyjděte proti němu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 7, 'Tedy vstaly všecky ty panny, a ozdobily lampy své.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 8, 'Bláznivé pak opatrným řekly: Udělte nám oleje svého, nebo lampy naše hasnou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 9, 'I odpověděly ty opatrné, řkouce: Aby se snad nám i vám nenedostalo. Jděte raději k prodavačům, a kupte sobě.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 10, 'A když odešly kupovati, přišel ženich, a které hotovy byly, vešly s ním na svadbu. I zavříny jsou dvéře.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 11, 'Potom pak přišly i ty druhé panny, řkouce: Pane, pane, otevři nám.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 12, 'A on odpověděv, řekl: Amen, pravím vám, neznámť vás.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 13, 'Bdětež tedy; nevíte zajisté dne ani hodiny, v kterou Syn člověka přijde.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 14, 'Nebo jako člověk vycházeje na cestu, povolal služebníků svých, a poručil jim statek svůj.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 15, 'I dal jednomu pět hřiven, jinému pak dvě, a jinému jednu, každému podlé možnosti jeho, i odšel hned na cestu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 16, 'Odšed pak ten, kterýž vzal pět hřiven, těžel jimi, i vydělal jiných pět hřiven.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 17, 'Též i ten, kterýž dvě, získal i on jiné dvě.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 18, 'Ale ten, kterýž vzal jednu, odšed, zakopal ji v zemi, a skryl peníze pána svého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 19, 'Po mnohém pak času přišel pán těch služebníků, i činil s nimi počet.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 20, 'A přistoupiv ten, kterýž byl pět hřiven vzal, podal jiných pět hřiven, řka: Pane, pět hřiven dal jsi mi, aj, jiných pět hřiven získal jsem jimi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 21, 'I řekl mu pán jeho: To dobře, služebníče dobrý a věrný, nad málem byl jsi věrný, nad mnohem tebe ustanovím. Vejdiž v radost pána svého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 22, 'Přistoupiv pak ten, kterýž byl dvě hřivně vzal, dí: Pane, dvě hřivně jsi mi dal, aj, jiné dvě hřivně získal jsem jimi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 23, 'Řekl mu pán jeho: To dobře, služebníče dobrý a věrný, nad málem byl jsi věrný, nad mnohem tebe ustanovím. Vejdiž v radost pána svého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 24, 'Přistoupiv pak i ten, kterýž vzal jednu hřivnu, řekl: Pane, věděl jsem, že jsi ty člověk přísný, žna, kde jsi nerozsíval, a zbíraje, kde jsi nerozsypal.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 25, 'I boje se, odšel jsem a skryl hřivnu tvou v zemi. Aj, teď máš, což tvého jest.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 26, 'A odpovídaje pán jeho, řekl mu: Služebníče zlý a lenivý, věděl jsi, že žnu, kdež jsem nerozsíval, a zbírám, kdež jsem nerozsypal.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 27, 'Protož měl jsi ty peníze mé dáti penězoměncům, a já přijda, byl bych vzal, což jest mého, s požitkem.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 28, 'Nu vezmětež od něho tu hřivnu, a dejte tomu, kterýž má deset hřiven.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 29, '(Nebo každému majícímu bude dáno, a bude více míti, od nemajícího pak i to, což má, bude odjato.)');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 30, 'A toho neužitečného služebníka uvrzte do těch temností zevnitřních. Tamť bude pláč a škřipení zubů.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 31, 'Když pak přijde Syn člověka v slávě své, a všickni svatí andělé s ním, tedy se posadí na trůnu velebnosti své,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 32, 'A shromážděni budou před něj všickni národové. I rozdělí je na různo, jedny od druhých, tak jako pastýř odděluje ovce od kozlů.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 33, 'A postaví ovce zajisté na pravici své, kozly pak na levici.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 34, 'Tedy dí Král těm, kteříž na pravici jeho budou: Poďtež požehnaní Otce mého, dědičně vládněte královstvím, vám připraveným od ustanovení světa.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 35, 'Nebo jsem lačněl, a dali jste mi jísti; žíznil jsem, a dali jste mi píti; hostem jsem byl, a přijímali jste mne;');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 36, 'Nah, a přioděli jste mne; nemocen jsem byl, a navštívili jste mne; v žaláři jsem seděl, a přicházeli jste ke mně.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 37, 'Tedy odpovědí jemu spravedliví, řkouce: Pane, kdy jsme tě vídali lačného, a krmili jsme, neb žíznivého, a dávaliť jsme píti?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 38, 'Aneb kdy jsme tě viděli hostě, a přijali jsme, neb nahého, a přioděli jsme?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 39, 'Aneb kdy jsme tě viděli nemocného neb v žaláři, a přicházeli jsme k tobě?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 40, 'A odpovídaje Král, dí jim: Amen pravím vám: Cožkoli jste činili jednomu z bratří těchto mých nejmenších, mně jste učinili.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 41, 'Potom i těm na levici dí: Jděte ode mne zlořečení do ohně věčného, kterýž jest připraven ďáblu i andělům jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 42, 'Neboť jsem lačněl, a nedali jste mi jísti; žíznil jsem, a nedali jste mi píti;');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 43, 'Hostem jsem byl, a nepřijali jste mne; nah, a neodívali jste mne; nemocen a v žaláři, a nenavštívili jste mne.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 44, 'Tedy odpovědí jemu i oni, řkouce: Pane, kdy jsme tebe vídali lačného, neb žíznivého, neb hostě, neb nahého, neb nemocného, aneb v žaláři, a neposloužili jsme tobě?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 45, 'Tedy odpoví jim, řka: Amen pravím vám: Čehož jste koli nečinili jednomu z nejmenších těchto, ani mně jste nečinili.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 46, 'I půjdou tito do trápení věčného, ale spravedliví do života věčného.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 1, 'I stalo se, když dokonal Ježíš řeči tyto všecky, řekl učedlníkům svým:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 2, 'Víte, že po dvou dnech velikanoc bude, a Syn člověka zrazen bude, aby byl ukřižován.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 3, 'Tehdy sešli se přední kněží {biskupové} a zákonníci, i starší lidu na síň nejvyššího kněze {biskupovu}, kterýž sloul Kaifáš.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 4, 'A radili se spolu, jak by Ježíše lstivě jali a zamordovali.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 5, 'Ale pravili: Ne v den sváteční, aby nebyl rozbroj v lidu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 6, 'Když pak byl Ježíš v Betany, v domu Šimona malomocného,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 7, 'Přistoupila k němu žena, mající nádobu alabastrovou masti velmi drahé, i vylila ji na hlavu jeho, když seděl za stolem.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 8, 'A vidouce to učedlníci jeho, rozhněvali se, řkouce: I k čemu jest ztráta tato?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 9, 'Nebo mohla tato mast prodána býti za mnoho, a dáno býti chudým.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 10, 'A znaje to Ježíš, dí jim: Proč za zlé máte této ženě? Dobrý zajisté skutek učinila nade mnou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 11, 'Nebo chudé vždycky máte s sebou, ale mne ne vždycky míti budete.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 12, 'Vylivši zajisté tato mast tuto na mé tělo, ku pohřebu mému to učinila.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 13, 'Amen pravím vám: Kdežkoli kázáno bude evangelium toto po všem světě, takéť i to bude praveno, co učinila tato, na památku její.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 14, 'Tedy odšed k předním kněžím {biskupům} jeden ze dvanácti, kterýž sloul Jidáš Iškariotský,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 15, 'Řekl: Co mi chcete dáti, a já vám ho zradím? A oni odvážili jemu třidceti stříbrných.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 16, 'A od té chvíle hledal příhodného času, aby ho zradil.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 17, 'Prvního pak dne přesnic, přistoupili k Ježíšovi učedlníci, řkouce jemu: Kde chceš, ať připravíme tobě, abys jedl beránka?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 18, 'On pak řekl: Jděte do města k jednomu, a rcete jemu: Vzkázalť Mistr: Čas můj blízko jest, u tebeť jísti budu beránka s učedlníky svými.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 19, 'I učinili učedlníci tak, jakž jim poručil Ježíš, a připravili beránka.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 20, 'A když byl večer, posadil se za stůl se dvanácti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 21, 'A když jedli, řekl: Amen pravím vám, že jeden z vás mne zradí.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 22, 'I zarmoutivše se velmi, počali každý z nich říci jemu: Zdali já jsem, Pane?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 23, 'On pak odpovídaje, řekl: Kdo omáčívá se mnou rukou v mise, ten mne zradí.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 24, 'Syn zajisté člověka jde, jakož psáno o něm, ale běda člověku tomu, skrze něhož Syn člověka zrazen bude. Dobré by bylo jemu, by se byl nenarodil člověk ten.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 25, 'Odpovídaje pak Jidáš, kterýž ho zrazoval, dí: Zdali já jsem, Mistře? Řekl jemu: Ty jsi řekl.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 26, 'A když oni jedli, vzav Ježíš chléb, a dobrořečiv, lámal, a dal učedlníkům, a řekl: Vezměte, jezte, to jest tělo mé.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 27, 'A vzav kalich, a díky činiv, dal jim, řka: Píte z toho všickni.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 28, 'Nebo to jest krev má nové smlouvy, kteráž za mnohé vylévá se na odpuštění hříchů.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 29, 'Ale pravímť vám, žeť nebudu píti od této chvíle z tohoto plodu vinného kořene, až do onoho dne, když jej píti budu s vámi nový v království Otce svého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 30, 'A sezpívavše písničku, vyšli na horu Olivetskou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 31, 'Tedy dí jim Ježíš: Všickni vy zhoršíte se nade mnou této noci. Nebo psáno jest: Bíti budu pastýře, a rozprchnouť se ovce stáda.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 32, 'Ale když z mrtvých vstanu, předejdu vás do Galilee.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 33, 'Odpovídaje pak Petr, řekl jemu: Byť se pak všickni zhoršili nad tebou, jáť se nikdy nezhorším.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 34, 'Řekl mu Ježíš: Amen pravím tobě, že této noci, prvé než kohout zazpívá, třikrát mne zapříš.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 35, 'Dí jemu Petr: Bychť pak měl s tebou i umříti, nikoli nezapřím tebe. Takž podobně i všickni učedlníci pravili.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 36, 'Tedy přišel s nimi Ježíš na místo, kteréž sloulo Getsemany. I dí učedlníkům: Poseďtež tuto, ažť odejda, pomodlím se tamto.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 37, 'A pojav s sebou Petra a dva syny Zebedeovy, počal se rmoutiti a teskliv býti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 38, 'Tedy dí jim: Smutnáť jest duše má až k smrti. Pozůstaňtež tuto, a bděte se mnou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 39, 'A poodšed maličko, padl na tvář svou, modle se a řka: Otče můj, jest-li možné, nechť odejde ode mne kalich tento. A však ne jakž já chci, ale jakž ty.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 40, 'I přišel k učedlníkům a nalezl je, a oni spí. I řekl Petrovi: Tak-liž jste nemohli jediné hodiny bdíti se mnou?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 41, 'Bdětež a modlte se, abyste nevešli v pokušení. Duchť zajisté hotov jest, ale tělo nemocno.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 42, 'Opět podruhé odšed, modlil se, řka: Otče můj, nemůže-liť tento kalich minouti mne, než abych jej pil, staniž se vůle tvá.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 43, 'I přišed, nalezl je, a oni zase spí; nebo byly oči jejich obtíženy.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 44, 'A nechav jich, opět odšel, a modlil se potřetí, touž řeč říkaje.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 45, 'Tedy přišel k učedlníkům svým, a řekl jim: Spětež již a odpočívejte. Aj, přiblížila se hodina, a Syna člověka zrazují v ruce hříšných.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 46, 'Vstaňtež, poďme. Aj, přiblížil se ten, kterýž mne zrazuje.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 47, 'A když on ještě mluvil, aj, Jidáš, jeden ze dvanácti, přišel, a s ním zástup mnohý s meči a s kyjmi, od předních kněží {biskupů} a starších lidu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 48, 'Ten pak, kterýž jej zrazoval, dal jim znamení, řka: Kteréhokoli políbím, ten jest; držtež jej.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 49, 'A hned přistoupiv k Ježíšovi, řekl: Zdráv buď, Mistře, a políbil jej.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 50, 'Ale Ježíš řekl jemu: Příteli, nač jsi přišel? Tedy přistoupili, a ruce vztáhli na Ježíše, a jali ho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 51, 'A aj, jeden z těch, kteříž byli s Ježíšem, vztáh ruku, vytrhl meč svůj; a udeřiv služebníka nejvyššího kněze {biskupova}, uťal ucho jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 52, 'Tedy dí jemu Ježíš: Obrať meč svůj v místo jeho; nebo všickni, kteříž meč berou, od meče zahynou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 53, 'Zdaliž mníš, že bych nyní nemohl prositi Otce svého, a vydal by mi více nežli dvanácte houfů andělů.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 54, 'Kterakž by se pak naplnila písma, svědčící, že tak musí býti?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 55, 'V tu hodinu řekl Ježíš zástupům: Jako na lotra vyšli jste s meči a s kyjmi jímati mne. Na každý den sedával jsem u vás, uče v chrámě, a nejali jste mne.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 56, 'Ale toto se všecko stalo, aby se naplnila písma prorocká. Tedy učedlníci všickni opustivše ho, utekli.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 57, 'A oni javše Ježíše, vedli ho k Kaifášovi nejvyššímu knězi {biskupovi}, kdež zákonníci a starší byli se sešli.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 58, 'Ale Petr šel za ním zdaleka, až do síně nejvyššího kněze {biskupovy}. A všed vnitř, seděl s služebníky, aby viděl konec.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 59, 'Přední pak kněží {biskupové} a starší i všecka ta rada hledali falešného svědectví proti Ježíšovi, aby jej na smrt vydali,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 60, 'Ale nenalezli. Ani, když mnozí falešní svědkové předstupovali, nic nenalezli. Naposledy pak přišedše dva falešní svědkové,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 61, 'Řekli: Tento pověděl: Mohu zbořiti chrám Boží, a ve třech dnech jej ustavěti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 62, 'A povstav nejvyšší kněz {biskup}, řekl jemu: Nic neodpovídáš, co tito proti tobě svědčí?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 63, 'Ale Ježíš mlčel. I odpovídaje nejvyšší kněz {biskup}, řekl jemu: Zaklínám tě skrze Boha živého, abys nám pověděl, jsi-li ty Kristus Syn Boží?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 64, 'Dí mu Ježíš: Ty jsi řekl. Ale však pravím vám: Od toho času uzříte Syna člověka sedícího na pravici moci Boží, a přicházejícího na oblacích nebeských.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 65, 'Tedy nejvyšší kněz {biskup} roztrhl roucho své, řka: Rouhal se. Což ještě potřebujeme svědků? Aj, nyní jste slyšeli rouhání jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 66, 'Co se vám zdá? A oni odpovídajíce, řekli: Hodenť jest smrti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 67, 'Tedy plili na tvář jeho, a pohlavkovali jej; jiní pak hůlkami jej bili,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 68, 'Říkajíce: Hádej nám, Kriste, kdo jest ten, kterýž tebe udeřil?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 69, 'Ale Petr seděl vně v síni. I přistoupila k němu jedna děvečka, řkuci: I ty jsi byl s Ježíšem tím Galilejským.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 70, 'On pak zapřel přede všemi, řka: Nevím, co pravíš.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 71, 'A když vycházel ze dveří, uzřela jej jiná. I řekla těm, kteříž tu byli: I tento byl s Ježíšem tím Nazaretským.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 72, 'I zapřel opět s přísahou: Neznám toho člověka.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 73, 'A po malé chvíli přistoupivše ti, kteříž tu stáli, řekli Petrovi: Jistě i ty z nich jsi, nebo i řeč tvá známa tebe činí.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 74, 'Tedy počal se proklínati a přisahati, řka: Neznám toho člověka. A hned kohout zazpíval.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 75, 'I rozpomenul se Petr na slovo Ježíšovo, kterýž jemu byl řekl: Prvé než kohout zazpívá, třikrát mne zapříš. A vyšed ven, plakal hořce.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 1, 'A když bylo ráno, vešli v radu všickni přední kněží {biskupové} a starší lidu proti Ježíšovi, aby jej na smrt vydali.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 2, 'I svázavše jej, vedli, a vydali ho Pontskému Pilátovi hejtmanu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 3, 'Tedy vida Jidáš zrádce jeho, že by odsouzen byl, želeje toho, navrátil zase třidceti stříbrných předním kněžím {biskupům} a starším,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 4, 'Řka: Zhřešil jsem, zradiv krev nevinnou. Oni pak řekli: Co nám do toho? Ty viz.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 5, 'A povrh ty stříbrné v chrámě, odšel pryč, a odšed, oběsil se.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 6, 'Přední kněží {biskupové} pak vzavše ty stříbrné, řekli: Neslušíť jich vložiti do pokladnice, nebo mzda krve jest.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 7, 'A poradivše se, koupili za ně pole to hrnčířovo, ku pohřebu poutníků.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 8, 'Protož nazváno jest pole to pole krve, až do dnešního dne.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 9, 'A tehdy naplnilo se povědění proroka řkoucího: A vzali třidceti stříbrných, mzdu ceněného, kterýž šacován byl od synů Izraelských,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 10, 'A dali je za pole hrnčířovo, jakož mi ustanovil Pán.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 11, 'Ježíš pak stál před vládařem. I otázal se ho vládař, řka: Ty-li jsi ten král Židovský? Ježíš pak řekl jemu: Ty pravíš.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 12, 'A když na něj přední kněží {biskupové} a starší žalovali, nic neodpověděl.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 13, 'Tedy dí mu Pilát: Neslyšíš-li, kteraké věci proti tobě svědčí?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 14, 'Ale neodpověděl jemu ani k jednomu slovu, tak že se vládař velmi divil.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 15, 'Měl pak obyčej vládař v svátek propouštěti lidu vězně jednoho, kteréhož by chtěli.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 16, 'I měli v ten čas vězně znamenitého, kterýž sloul Barabáš.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 17, 'Protož když se lidé sešli, řekl jim Pilát: Kterého chcete, ať vám propustím? Barabáše-li, čili Ježíše, kterýž slove Kristus?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 18, 'Nebo věděl, že jej z závisti vydali.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 19, 'A když seděl na soudné stolici, poslala k němu žena jeho, řkuci: Nic neměj činiti s spravedlivým tímto, nebo jsem mnoho trpěla dnes ve snách pro něho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 20, 'Ale přední kněží {biskupové} a starší navedli lid, aby prosili za Barabáše, Ježíše pak aby zahubili.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 21, 'I odpověděv vládař, řekl jim: Kterého chcete z těch dvou, ať vám propustím? A oni řekli: Barabáše.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 22, 'Dí jim Pilát: Co pak učiním s Ježíšem, kterýž slove Kristus? Řekli mu všickni: Ukřižován buď.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 23, 'Vládař pak řekl: I což jest zlého učinil? Oni pak více křičeli, řkouce: Ukřižován buď.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 24, 'A vida Pilát, že by nic neprospěl, ale že by větší rozbroj byl, vzav vodu, umyl ruce před lidem, řka: Čist jsem od krve spravedlivého tohoto. Vy vizte.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 25, 'A odpověděv všecken lid, řekl: Krev jeho na nás i na naše dítky.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 26, 'Tedy propustil jim Barabáše, ale Ježíše zbičovav, vydal, aby byl ukřižován.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 27, 'Tedy žoldnéři hejtmanovi, vzavše Ježíše do rathouzu, shromáždili k němu všecku rotu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 28, 'A svlékše jej, přioděli ho pláštěm brunátným.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 29, 'A spletše korunu z trní, vstavili na hlavu jeho, a dali třtinu v pravou ruku jeho, a klekajíce před ním, posmívali se jemu, řkouce: Zdráv buď, ó králi Židovský.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 30, 'A plijíce na něho, brali tu třtinu a bili jej v hlavu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 31, 'A když se mu naposmívali, svlékli s něho plášť, a oblékli jej v roucho jeho. I vedli ho, aby byl ukřižován.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 32, 'A vyšedše, nalezli člověka Cyrenenského, jménem Šimona. Toho přinutili, aby nesl kříž jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 33, 'I přišedše na místo, kteréž slove Golgota, to jest popravné místo,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 34, 'Dali mu píti octa, smíšeného se žlučí. A okusiv, nechtěl píti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 35, 'Ukřižovavše pak jej, rozdělili roucha jeho, mecíce los, aby se naplnilo povědění proroka: Rozdělili sobě roucho mé, a o můj oděv metali los.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 36, 'A sedíce, ostříhali ho tu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 37, 'I vstavili nad hlavu jeho vinu jeho napsanou: Totoť jest Ježíš, ten král Židovský.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 38, 'I ukřižováni jsou s ním dva lotři, jeden na pravici a druhý na levici.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 39, 'Ti pak, kteříž chodili tudy, rouhali se jemu, ukřivujíce hlav svých.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 40, 'A říkajíce: Hej, ty jako rušíš chrám a ve třech dnech vzděláváš, pomoziž sám sobě. Jsi-li Syn Boží, sstupiž s kříže.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 41, 'Tak podobně i přední kněží {biskupové} posmívajíce se s zákonníky a staršími, pravili:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 42, 'Jiným pomáhal, sám sobě nemůž pomoci. Jestliže jest král Izraelský, nech ať nyní sstoupí s kříže, a uvěříme jemu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 43, 'Doufalť v Boha, nech ať ho nyní vysvobodí, chce-liť mu; nebo pravil: Syn Boží jsem.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 44, 'Takž také i lotři, kteříž byli s ním ukřižováni, utrhali jemu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 45, 'Od šesté pak hodiny tma se stala po vší zemi až do hodiny deváté.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 46, 'A při hodině deváté zvolal Ježíš hlasem velikým, řka: Eli, Eli, lama zabachtani? To jest: Bože můj, Bože můj, proč jsi mne opustil?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 47, 'A někteří z těch, kteříž tu stáli, slyšíce, pravili: Eliáše volá tento.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 48, 'A hned jeden z nich běžev, a vzav hubu, naplnil ji octem, a vloživ na tresť, napájel ho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 49, 'Ale jiní pravili: Nech tak, pohledíme, přijde-li Eliáš, aby ho vysvobodil.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 50, 'Ježíš pak opět zvolav hlasem velikým, vypustil duši.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 51, 'A aj, opona chrámová roztrhla se na dvé, od vrchu až dolů, a země se třásla, a skálé se pukalo,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 52, 'A hrobové se otvírali, a mnohá těla zesnulých svatých vstala.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 53, 'A vyšedše z hrobů po vzkříšení jeho, přišli do svatého města, a ukázali se mnohým.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 54, 'Tedy centurio a ti, kteříž s ním ostříhali Ježíše, vidouce země třesení a to, co se dálo, báli se velmi, řkouce: Jistě Syn Boží byl tento.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 55, 'Byly také tu ženy mnohé, z daleka se dívajíce, kteréž byly přišly za Ježíšem od Galilee, posluhujíce jemu,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 56, 'Mezi nimiž byla Maria Magdaléna, a Maria, matka Jakubova a Jozesova, a matka synů Zebedeových.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 57, 'A když byl večer, přišel člověk bohatý z Arimatie, jménem Jozef, kterýž také byl učedlník Ježíšův.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 58, 'Ten předstoupil před Piláta, a prosil za tělo Ježíšovo. Tedy Pilát rozkázal dáti tělo.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 59, 'A vzav tělo Jozef, obvinul je v plátno čisté.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 60, 'A vložil do svého nového hrobu, kterýž byl vytesal v skále; a přivaliv kámen veliký ke dveřům hrobovým, odšel.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 61, 'A byla tu Maria Magdaléna, a druhá Maria, sedíce naproti hrobu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 62, 'Druhého pak dne, kterýž byl po velikém pátku, sešli se přední kněží {biskupové} a farizeové ku Pilátovi,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 63, 'Řkouce: Pane, rozpomenuli jsme se, že ten svůdce řekl, ještě živ jsa: Po třech dnech vstanu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 64, 'Rozkažiž tedy ostříhati hrobu až do třetího dne, ať by snad učedlníci jeho, přijdouce v noci, neukradli ho, a řekli by lidu: Vstalť jest z mrtvých. I budeť poslední blud horší nežli první.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 65, 'Řekl jim Pilát: Máte stráž; jděte, ostříhejte, jakž víte.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 66, 'A oni šedše, osadili hrob strážnými, zapečetivše kámen.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 1, 'Na skonání pak soboty, když již svitalo na první den toho téhodne, přišla Maria Magdaléna, a druhá Maria, aby pohleděly na hrob.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 2, 'A aj, země třesení stalo se veliké. Nebo anděl Páně sstoupiv s nebe a přistoupiv, odvalil kámen ode dveří, a posadil se na něm.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 3, 'A byl oblíčej jeho jako blesk, a roucho jeho bílé jako sníh.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 4, 'A pro strach jeho zděsili se strážní, a učiněni jsou jako mrtví.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 5, 'I odpověděv anděl, řekl ženám: Nebojte se vy, neboť vím, že Ježíše ukřižovaného hledáte.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 6, 'Neníť ho tuto; nebo vstalť jest, jakož předpověděl. Poďte, vizte místo, kdež ležel Pán.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 7, 'A rychle jdouce, povězte učedlníkům jeho, že vstal z mrtvých. A aj, předchází vás do Galilee, tam jej uzříte. Aj, pověděl jsem vám.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 8, 'I vyšedše rychle z hrobu s bázní a s radostí velikou, běžely, aby učedlníkům jeho zvěstovaly.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 9, 'Když pak šly zvěstovati učedlníkům jeho, aj, Ježíš potkal se s nimi, řka: Zdrávy buďte. A ony přistoupivše, chopily se noh jeho, a klaněly se jemu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 10, 'Tedy dí jim Ježíš: Nebojtež se. Jděte, zvěstujte bratřím mým, ať jdou do Galilee, a tamť mne uzří.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 11, 'Když pak ony odešly, aj, někteří z stráže přišedše do města, oznámili předním kněžím {biskupům} všecko, co se stalo.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 12, 'Kteřížto shromáždivše se s staršími, a uradivše se, mnoho peněz dali žoldnéřům,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 13, 'Řkouce: pravte, že učedlníci jeho nočně přišedše, ukradli jej, když jsme my spali.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 14, 'A uslyší-liť o tom hejtman, myť ho spokojíme, a vás bezpečny učiníme.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 15, 'A oni vzavše peníze, učinili, jakž naučeni byli. I rozhlášeno jest slovo to u Židů až do dnešního dne.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 16, 'Jedenácte pak učedlníků šli do Galilee na horu, kdež jim byl uložil Ježíš.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 17, 'A uzřevše ho, klaněli se jemu. Ale někteří pochybovali.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 18, 'A přistoupiv Ježíš, mluvil jim, řka: Dána jest mi všeliká moc na nebi i na zemi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 19, 'Protož jdouce, učte všecky národy, křtíce je ve jméno Otce i Syna i Ducha svatého,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 20, 'Učíce je zachovávati všecko, což jsem koli přikázal vám. A aj, já s vámi jsem po všecky dny, až do skonání světa. Amen.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 1, 'Počátek evangelium Ježíše Krista, Syna Božího;');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 2, 'Jakož psáno jest v prorocích: Aj, já posílám anděla svého před tváří tvou, kterýž připraví cestu tvou před tebou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 3, 'Hlas volajícího na poušti: Připravujte cestu Páně, přímé čiňte stezky jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 4, 'Křtil Jan na poušti, a kázal křest pokání na odpuštění hříchů.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 5, 'I vycházela k němu všecka krajina Judská i Jeruzalémští, a křtěni byli od něho všickni v Jordáně řece, vyznávajíce hříchy své.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 6, 'Byl pak Jan odín srstmi velbloudovými, a pás kožený na bedrách jeho, a jídal kobylky a med lesní.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 7, 'A kázal, řka: Jde za mnou silnější nežli já, kterémuž nejsem hoden, sehna se, rozvázati řeménka u obuvi jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 8, 'Já zajisté křtil jsem vás vodou, ale onť vás křtíti bude Duchem svatým.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 9, 'I stalo se v těch dnech, přišel Ježíš z Nazarétu Galilejského, a pokřtěn jest od Jana v Jordáně.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 10, 'A hned vystoupiv z vody, uzřel nebesa otevřená a Ducha jako holubici sstupujícího na něj.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 11, 'A hlas stal se s nebe: Ty jsi ten můj milý Syn, v němž mi se dobře zalíbilo.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 12, 'A i hned ho Duch vypudil na poušť.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 13, 'I byl tam na poušti čtyřidceti dnů, a pokoušín byl od satana; a byl s zvěří, a andělé přisluhovali jemu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 14, 'Když pak byl vsazen Jan, přišel Ježíš do Galilee, káže evangelium království Božího,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 15, 'A pravě: Že se naplnil čas, a přiblížilo se království Boží. Čiňte pokání, a věřte evangelium.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 16, 'A chodě podlé moře Galilejského, uzřel Šimona a Ondřeje bratra jeho, ani pouštějí síti do moře, (nebo rybáři byli.)');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 17, 'I řekl jim Ježíš: Poďte za mnou, a učiním vás rybáře lidí.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 18, 'A hned opustivše síti své, šli za ním.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 19, 'A poodšed odtud maličko, uzřel Jakuba syna Zebedeova, a Jana bratra jeho, ani na lodí tvrdí síti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 20, 'A hned povolal jich. A oni opustivše otce svého Zebedea na lodí s pacholky, šli za ním.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 21, 'I vešli do Kafarnaum. A hned v sobotu šed do školy, učil.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 22, 'I divili se náramně učení jeho; nebo učil je, jako moc maje, a ne jako zákonníci.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 23, 'I byl v škole jejich člověk, maje ducha nečistého. Kterýž zvolal,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 24, 'Řka: Ach, což jest tobě do nás, Ježíši Nazaretský? Přišel jsi zatratiti nás. Znám tě, kdo jsi, že ten Svatý Boží.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 25, 'I přimluvil mu Ježíš, řka: Umlkniž a vyjdi z něho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 26, 'I polomcovav jím duch nečistý a křiče hlasem velikým, vyšel z něho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 27, 'I lekli se všickni, tak že se tázali mezi sebou, řkouce: I co jest toto? Jakéž toto nové učení, že mocně i těm duchům nečistým rozkazuje, a poslouchají ho?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 28, 'I roznesla se pověst o něm hned po vší krajině Galilejské.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 29, 'A hned vyšedše ze školy, přišli do domu Šimonova a Ondřejova s Jakubem a s Janem.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 30, 'Šimonova pak svegruše ležela, majíc zimnici. A hned jemu pověděli o ní.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 31, 'A přistoupiv, pozdvihl jí, ujav ji za ruku její, a hned přestala jí zimnice. I posluhovala jim.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 32, 'Večer pak při západu slunce, nosili k němu všecky nemocné i ďábelníky.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 33, 'A bylo se všecko město zběhlo ke dveřím.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 34, 'I uzdravoval mnohé ztrápené rozličnými neduhy, a ďábelství mnohá vymítal, a nedopouštěl mluviti ďáblům; nebo znali ho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 35, 'A přede dnem velmi ráno vstav, vyšel a odšel na pusté místo, a tam se modlil.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 36, 'I šli za ním Šimon i ti, kteříž s ním byli.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 37, 'A nalezše jej, řekli jemu: Všickni tě hledají.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 38, 'I dí jim: Poďmež do okolních městeček, abych i tam kázal. Nebo na to jsem přišel.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 39, 'I kázal v školách jejich ve vší Galilei, a ďábelství vymítal.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 40, 'Tedy přišel k němu malomocný, prose ho, a klekna před ním, řekl jemu: Chceš-li, můžeš mne očistiti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 41, 'Ježíš pak slitovav se, vztáhl ruku, dotekl se ho a řekl jemu: Chci, buď čist.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 42, 'A když to řekl, hned odstoupilo od něho malomocenství, a očištěn jest.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 43, 'I zapověděv mu přísně, hned ho odbyl,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 44, 'A řekl mu: Viziž, abys žádnému nic nepravil. Ale jdi, ukaž se knězi, a obětuj za očištění své to, což přikázal Mojžíš, na svědectví proti nim.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 45, 'On pak vyšed, počal vypravovati mnoho a ohlašovati tu věc, tak že již nemohl Ježíš do města zjevně vjíti, ale vně na místech pustých byl. I scházeli se k němu odevšad.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 1, 'A opět všel do Kafarnaum po kolikas dnech. I uslyšáno jest, že by doma byl.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 2, 'A hned sešlo se jich množství, tak že již nemohli se směstknati ani přede dveřmi. I mluvil jim slovo.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 3, 'Tedy přišli k němu, nesouce šlakem poraženého, kterýž ode čtyř nesen byl.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 4, 'A když k němu nemohli přistoupiti pro zástupy, loupali střechu, kdež byl, a probořivše ji, spustili po provazích dolů ložce, na němž ležel šlakem poražený.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 5, 'A vida Ježíš víru jejich, dí šlakem poraženému: Synu, odpouštějí se tobě hříchové tvoji.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 6, 'A byli tu někteří z zákonníků, sedíce a myslíce v srdcích svých:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 7, 'Co tento tak mluví rouhavě? Kdo můž odpustiti hříchy, jediné sám Bůh?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 8, 'I poznav Ježíš hned duchem svým, že by tak přemyšlovali sami v sobě, řekl jim: Proč o tom přemyšlujete v srdcích svých?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 9, 'Co jest snáze, říci šlakem poraženému: Odpouštějí se tobě hříchové, čili říci: Vstaň, vezmi lože své a choď?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 10, 'Ale abyste věděli, že Syn člověka má moc na zemi odpouštěti hříchy, dí šlakem poraženému:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 11, 'Toběť pravím: Vstaň, a vezmi lože své, a jdi do domu svého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 12, 'I vstal hned, a vzav lože své přede všemi, odšel, tak že se děsili všickni, a chválili Boha, řkouce: Nikdy jsme toho neviděli.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 13, 'I vyšel opět k moři, a všecken zástup přicházel k němu, i učil je.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 14, 'A pomíjeje, uzřel Léví Alfeova, sedícího na cle. I dí jemu: Poď za mnou. A on vstav, šel za ním.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 15, 'I stalo se, když seděl Ježíš za stolem v domě jeho, že i publikáni mnozí a hříšníci seděli spolu s Ježíšem a s učedlníky jeho; nebo mnoho jich bylo, a šlo za ním.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 16, 'Zákonníci pak a farizeové viděvše, že jedl s publikány a s hříšníky, řekli učedlníkům jeho: Což to, že s publikány a hříšníky jí a pije?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 17, 'To uslyšav Ježíš, dí jim: Nepotřebují zdraví lékaře, ale nemocní. Nepřišelť jsem volati spravedlivých, ale hříšných ku pokání.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 18, 'Učedlníci pak Janovi a farizejští postívali se. I přišli a řekli jemu: Proč učedlníci Janovi a farizejští postí se, a tvoji učedlníci se nepostí?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 19, 'I řekl jim Ježíš: Kterakž mohou synové ženichovi postiti se, když jest s nimi ženich? Dokudž mají s sebou ženicha, nemohouť se postiti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 20, 'Ale přijdouť dnové, když od nich odjat bude ženich, a tehdáž se budou postiti v těch dnech.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 21, 'Ano žádný záplaty sukna nového nepřišívá k rouchu starému; jinak odtrhne ta záplata nová od starého, i bývá větší díra.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 22, 'A žádný nevlévá vína nového do nádob starých; jinak rozpučí nové víno nádoby, a víno se vyleje, a nádoby se pokazí. Ale víno nové má lito býti do nádob nových.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 23, 'I stalo se, že šel Ježíš v sobotu skrze obilí, i počali učedlníci jeho, cestou jdouce, vymínati klasy.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 24, 'Tedy farizeové řekli jemu: Pohleď, coť dělají v sobotu, čehož nenáleží.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 25, 'I řekl jim: Nikdy-liž jste nečtli, co učinil David, když nouze byla, a lačněl, on i ti, kteříž s ním byli?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 26, 'Kterak všel do domu Božího za Abiatara nejvyššího kněze {biskupa}, a jedl chleby posvátné, (jichž neslušelo jísti než samým kněžím,) a dal i těm, kteříž s ním byli?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 27, 'I pravil jim: Sobota pro člověka učiněna jest, a ne člověk pro sobotu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 28, 'Protož Syn člověka jest pánem také i soboty.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 1, 'I všel opět do školy, a byl tu člověk, maje ruku uschlou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 2, 'I šetřili ho, uzdraví-li jej v sobotu, aby ho obžalovali.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 3, 'I řekl tomu člověku, kterýž měl uschlou ruku: Povstaň u prostřed.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 4, 'I dí jim: Sluší-li v sobotu dobře činiti, čili zle, život zachovati, čili zamordovati? Oni pak mlčeli.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 5, 'A když pohleděl na ně vůkol s hněvem, zarmoutiv se nad tvrdostí srdce jejich, řekl člověku: Vztáhni tu ruku svou. I vztáhl, a učiněna jest ta ruka jeho zdravá jako druhá.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 6, 'A vyšedše farizeové, hned s Herodiány drželi radu proti němu, kterak by ho zahubili.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 7, 'Ježíš pak odšel s učedlníky svými k moři, a veliké množství od Galilee šlo za ním, i z Judstva,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 8, 'I od Jeruzaléma, i od Idumee, i z Zajordání; i ti, kteříž byli okolo Týru a Sidonu, množství veliké, slyšíce, kteraké věci činí, přišli k němu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 9, 'I rozkázal učedlníkům svým, aby lodičku ustavičně nahotově měli pro zástup, aby ho netiskli.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 10, 'Nebo mnohé uzdravoval, tak že naň padali, aby se ho dotýkali, kteřížkoli měli neduhy.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 11, 'A duchové nečistí, jakž ho zazřeli, padali před ním a křičeli, řkouce: Ty jsi ten Syn Boží.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 12, 'Ale on velmi jim přimlouval, aby ho nezjevovali.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 13, 'I vstoupil na horu, a povolal k sobě těch, kterýchž se jemu vidělo; i přišli k němu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 14, 'I ustanovil jich dvanácte, aby s ním byli, a aby je poslal kázati,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 15, 'A aby měli moc uzdravovati nemoci a vymítati ďábelství:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 16, 'Šimona, jemuž dal jméno Petr,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 17, 'A Jakuba Zebedeova, a Jana bratra Jakubova, (a dal jim jméno Boanerges, to jest synové hromovi,)');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 18, 'A Ondřeje, a Filipa, a Bartoloměje, a Matouše, a Tomáše, a Jakuba Alfeova, a Taddea, a Šimona Kananitského,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 19, 'A Jidáše Iškariotského, kterýž i zradil jej. I šli s ním domů.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 20, 'A opět sšel se zástup, tak že nemohli ani chleba pojísti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 21, 'A slyšavše o tom příbuzní jeho, přišli, aby jej vzali; nebo pravili, že by se smyslem pominul.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 22, 'Zákonníci pak, kteříž byli přišli z Jeruzaléma, pravili, že Belzebuba má, a že v knížeti ďábelském vymítá ďábly.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 23, 'A povolav jich, mluvil k nim v podobenstvích: Kterak může satan satana vymítati?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 24, 'A jestliže království v sobě se rozdvojí, nemůže státi království to.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 25, 'A rozdvojí-li se dům proti sobě, nebude moci dům ten státi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 26, 'Tak jestliže povstal satan sám proti sobě, a rozdvojen jest, nemůže státi, ale konec béře.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 27, 'Žádný nemůže nádobí silného, vejda do domu jeho, rozebrati, leč by prvé silného toho svázal; a tehdyť dům jeho zloupí.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 28, 'Amen pravím vám, že všickni hříchové odpuštěni budou synům lidským, i rouhání, jímž by se rouhali,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 29, 'Ale kdo by se rouhal proti Duchu svatému, nemá odpuštění na věky, ale hoden jest věčného odsouzení.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 30, 'Nebo pravili: Ducha nečistého má.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 31, 'Tehdy přišli bratří a matka jeho, a stojíce vně, poslali k němu, aby ho vyvolali.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 32, 'A seděl okolo něho zástup. I řekli jemu: Aj, matka tvá a bratří tvoji vně hledají tebe.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 33, 'Ale on odpověděl jim, řka: Kdo jest matka má a bratří moji?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 34, 'A obezřev učedlníky vůkol sebe sedící, řekl: Aj, matka má a bratří moji.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 35, 'Nebo kdož by koli činil vůli Boží, ten jest bratr můj, i sestra má, i matka.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 1, 'A opět počal učiti u moře. I shromáždil se k němu zástup mnohý, tak že vstoupiv na lodí, seděl na moři, a všecken zástup byl na zemi podlé moře.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 2, 'I učil je mnohým věcem v podobenstvích, a pravil jim v učení svém:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 3, 'Slyšte. Aj, vyšel rozsevač, aby rozsíval.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 4, 'I stalo se v tom rozsívání, že jedno padlo podlé cesty, a přiletělo ptactvo nebeské, i zzobalo je.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 5, 'A jiné padlo na místo skalnaté, kdež nemělo mnoho země, a hned vzešlo, proto že nemělo hlubokosti země.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 6, 'A když vyšlo slunce, vyhořelo, a proto, že nemělo kořene, uschlo.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 7, 'A jiné padlo mezi trní; i zrostlo trní, a udusilo je. I nevydalo užitku.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 8, 'Jiné pak padlo v zemi dobrou, a dalo užitek zhůru vstupující a rostoucí; přineslo zajisté jedno třidcátý, a jiné šedesátý, a jiné pak stý.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 9, 'I pravil jim: Kdo má uši k slyšení, slyš.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 10, 'Když pak byl sám, tázali se ho ti, kteříž při něm byli, se dvanácti, na to podobenství.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 11, 'I řekl jim: Vámť jest dáno, znáti tajemství království Božího, ale těm, kteříž jsou vně, v podobenství to všecko se děje,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 12, 'Aby hledíce, hleděli, ale neuzřeli a slyšíce, slyšeli, ale nesrozuměli, aby se snad neobrátili, a byli by jim odpuštěni hříchové.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 13, 'I dí jim: Neznáte podobenství tohoto? A kterakž pak všecka podobenství poznáte?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 14, 'Rozsevač ten slovo rozsívá.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 15, 'Tito pak jsou, ješto podlé cesty, jimž se rozsívá slovo, ale když oni slyší, i hned přichází satan, a vynímá slovo, kteréž vsáto jest v srdcích jejich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 16, 'A tak podobně ti, kteříž jako skalnatá země posáti jsou, kteříž jakž uslyší slovo, hned s radostí přijímají je.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 17, 'Než nemají kořene v sobě, ale jsou časní; potom když vznikne ssoužení a protivenství pro slovo, hned se horší.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 18, 'Tito pak jsou, kteříž mezi trní posáti jsou, ti jsou, kteříž slovo slyší,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 19, 'Však pečování tohoto světa a oklamání zboží, a jiné žádosti přistupující, udušují slovo, tak že bez užitku bývá.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 20, 'Tito pak jsou, kteříž v zemi dobrou símě přijali, kteříž slyší slovo, a přijímají, a užitek přinášejí, jiné třidcátý, a jiné šedesátý, a jiné stý.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 21, 'Dále pravil jim: Zdali rozsvícena bývá svíce, aby postavena byla pod nádobu neb pod postel? Však aby na svícen vstavena byla.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 22, 'Nebo nic není skrytého, co by nebylo zjeveno; aniž jest co tak ukrytého, aby na jevo nevyšlo.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 23, 'Jestliže kdo má uši k slyšení, slyš.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 24, 'I mluvil k nim: Vizte, co slyšíte. Kterou měrou budete měřiti, bude vám odměřeno, a přidáno bude vám poslouchajícím.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 25, 'Nebo kdožť má, tomu bude dáno; a kdo nemá, i to, což má, bude od něho odjato.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 26, 'I pravil: Tak jest království Boží, jako kdyby člověk uvrhl símě do země.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 27, 'A spal by, a vstával by ve dne i v noci a semeno by vzešlo a zrostlo, jakž on neví.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 28, 'Nebo sama od sebe země užitek plodí, nejprv bylinu, potom klas, potom plné obilé v klasu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 29, 'A když sezrá úroda, i hned přičiní srp; nebo nastala žeň.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 30, 'I řekl: K čemu připodobníme království Boží? Aneb kterým podobenstvím je ukážeme?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 31, 'Jest jako zrno horčičné, kteréž, když vsáto bývá do země, nejmenší jest ze všech semen, kteráž jsou na zemi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 32, 'Ale když vsáto bývá, roste, a bývá větší než všecky byliny, a činí ratolesti veliké, tak že pod stínem jeho mohou sobě ptáci nebeští hnízda dělati.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 33, 'A takovými mnohými podobenstvími mluvil jim slovo, jakž mohli slyšeti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 34, 'Bez podobenství pak nemluvil jim, ale učedlníkům svým soukromí vykládal všecko.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 35, 'I řekl jim v ten den, když již byl večer: Plavme se na druhou stranu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 36, 'A nechavše zástupu, pojali jej, tak jakž byl na lodičce. Ale i jiné lodičky byly s ním.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 37, 'Tedy stala se bouře veliká od větru, až se vlny na lodí valily, tak že se již naplňovala lodí.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 38, 'A on z zadu na lodí spal na podušce. I zbudili jej, a řekli jemu: Mistře, nedbáš, že hyneme?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 39, 'I probudiv se, přimluvil větru, a řekl moři: Umlkni, a upokoj se. I přestal vítr, a stalo se utišení veliké.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 40, 'I řekl jim: Proč se tak bojíte? Jakž to, že nemáte víry?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 41, 'I báli se bázní velikou, a pravili jeden k druhému: I kdo jest medle tento, že i vítr i moře poslouchají jeho?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 1, 'Tedy přeplavili se přes moře do krajiny Gadarenských.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 2, 'A jakž vyšel z lodí, hned se s ním potkal člověk z hrobů, maje ducha nečistého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 3, 'Kterýž bydlil v hrobích, a aniž ho kdo mohl řetězy svázati,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 4, 'Proto že často byv pouty a řetězy okován, polámal řetězy, a pouta roztrhal, a žádný nemohl ho skrotiti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 5, 'A vždycky ve dne i v noci na horách a v hrobích byl, křiče a tepa se kamením.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 6, 'Uzřev pak Ježíše zdaleka, běžel a poklonil se jemu,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 7, 'A křiče hlasem velikým, řekl: Co jest tobě do mne, Ježíši, Synu Boha nejvyššího? Zaklínám tě skrze Boha, abys mne netrápil.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 8, '(Nebo pravil jemu: Vyjdiž, duchu nečistý, z člověka tohoto.)');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 9, 'I otázal se ho: Jakť říkají? A on odpovídaje, řekl: Množství jméno mé jest, nebo jest nás mnoho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 10, 'I prosil ho velmi, aby jich nevyháněl z té krajiny.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 11, 'Bylo pak tu při horách stádo vepřů veliké pasoucích se.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 12, 'I prosili ho všickni ti ďáblové, řkouce: Pusť nás do vepřů, ať do nich vejdeme.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 13, 'I povolil jim hned Ježíš. A vyšedše duchové nečistí, vešli do těch vepřů. I běželo to stádo s vrchu dolů do moře, (a bylo jich ke dvěma tisícům,) i ztonuli v moři.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 14, 'Ti pak, kteříž ty vepře pásli, utekli, a oznámili to v městě i ve vsech. I vyšli, aby viděli, co by to bylo, což se stalo.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 15, 'I přišli k Ježíšovi, a uzřeli toho, kterýž býval trápen od ďábelství, an sedí, odín jsa, a maje zdravý rozum, toho, kterýž míval množství. I báli se.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 16, 'A kteříž to viděli, vypravovali jim, kterak se stalo tomu, kterýž měl ďábelství i o vepřích.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 17, 'Tedy počali ho prositi, aby odšel z krajin jejich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 18, 'A když vstoupil na lodí, prosil ho ten, kterýž trápen býval od ďábelství, aby s ním byl.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 19, 'Ježíš pak nedopustil mu, ale řekl jemu: Jdi k svým do domu svého, a zvěstuj jim, kterak veliké věci učinil tobě Pán, a že slitoval se nad tebou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 20, 'I odšel, a počal ohlašovati v krajině Desíti měst, kterak veliké věci učinil mu Ježíš. I divili se všickni.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 21, 'A když se přeplavil Ježíš na lodí zase na druhou stranu, sšel se k němu zástup mnohý. A byl u moře.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 22, 'A aj, přišel jeden z knížat školy, jménem Jairus, a uzřev jej, padl k nohám jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 23, 'A velmi ho prosil, řka: Dcerka má skonává. Poď, vlož na ni ruce, aby uzdravena byla, a budeť živa.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 24, 'I šel s ním, a zástup mnohý šel za ním, i tiskl jej.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 25, '(Tedy žena jedna, kteráž tok krve měla dvanácte let,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 26, 'A mnoho byla trápena od mnohých lékařů, a vynaložila všecken statek svůj, a nic jí bylo neprospělo, ale vždy se hůře měla,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 27, 'Uslyšavši o Ježíšovi, přišla v zástupu po zadu, a dotkla se roucha jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 28, 'Nebo řekla byla: Dotknu-li se jen roucha jeho, uzdravena budu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 29, 'A hned přestal krvotok její, a pocítila na těle, že by uzdravena byla od neduhu svého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 30, 'A hned Ježíš poznav sám v sobě, že z něho moc vyšla, obrátiv se v zástupu, řekl: Kdo se dotekl roucha mého?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 31, 'I řekli mu učedlníci jeho: Vidíš, že tě zástup tiskne, a pravíš: Kdo se mne dotekl?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 32, 'I hleděl vůkol, aby ji uzřel, která to učinila.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 33, 'Ta pak žena s bázní a s třesením, věduci, co se stalo při ní, přistoupila a padla před ním, a pověděla mu všecku pravdu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 34, 'On pak řekl jí: Dcero, víra tvá tě uzdravila, jdiž u pokoji, a buď zproštěna od trápení svého.)');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 35, 'A když on ještě mluvil, přišli z domu knížete školy, řkouce: Dcera tvá umřela, proč již zaměstknáváš Mistra?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 36, 'Ježíš pak, hned jakž uslyšel to, což oni mluvili, řekl knížeti školy: Neboj se, toliko věř.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 37, 'I nedal žádnému za sebou jíti, jediné Petrovi, Jakubovi a Janovi, bratru Jakubovu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 38, 'I přišel do domu knížete školy, a viděl tam hluk, ano plačí a kvílí velmi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 39, 'I všed tam, řekl jim: Co se bouříte a plačete? Neumřelať děvečka, ale spí.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 40, 'I posmívali se jemu. On pak vyhnav všecky, pojal otce a matku děvečky, a ty, kteříž s ním byli, i všel tam, kdež děvečka ležela.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 41, 'A vzav ruku děvečky, řekl jí: Talitha kumi. Což se vykládá: Děvečko, (toběť pravím,) vstaň.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 42, 'A hned vstala děvečka, a chodila; nebo byla ve dvanácti letech. I zděsili se divením převelikým.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 43, 'A přikázal jim pilně, aby žádný o tom nezvěděl. I rozkázal jí dáti jísti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 1, 'I vyšel odtud a přišel do vlasti své, a šli za ním učedlníci jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 2, 'A když bylo v sobotu, počal učiti v škole, a mnozí slyšíce, děsili se, řkouce: Odkud tento má tyto věci? A jaká jest to moudrost, kteráž jest dána jemu, že i takové moci dějí se skrze ruce jeho?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 3, 'Zdaliž tento není ten tesař, syn Marie, bratr pak Jakubův a Jozesův a Judův a Šimonův? A zdaliž nejsou i sestry jeho zde u nás? I horšili se na něm.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 4, 'I řekl jim Ježíš: Není prorok beze cti, jediné v vlasti své a v rodině své a v domě svém.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 5, 'I nemohl tu divu žádného učiniti, jediné málo nemocných, vzkládaje na ně ruce, uzdravil.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 6, 'I podivil se jejich nevěře, a obcházel vůkol po městečkách, uče.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 7, 'A svolav k sobě těch dvanácte, počal je posílati po dvou a dvou, a dal jim moc nad duchy nečistými.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 8, 'A přikázal jim, aby ničeho nebrali na cestu, jediné toliko hůl, ani mošny, ani chleba, ani do opasku peněz,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 9, 'Ale aby obuté měli nohy v střevíce, a neobláčeli dvou sukní.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 10, 'A pravil jim: Kdežkoli vešli byste do domu, tu ostaňte, dokudž nevyšli byste odtud.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 11, 'A kdož by koli vás nepřijali, ani vás neposlouchali, vyjdouce odtud, vyrazte prach z noh svých na svědectví jim. Amen pravím vám: Lehčeji bude Sodomským a Gomorským v den soudný než městu tomu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 12, 'Tedy vyšedše, kázali, aby pokání činili.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 13, 'A ďábelství mnohá vymítali, a mazali olejem mnohé nemocné, i uzdravovali.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 14, 'A uslyšev o tom Heródes král, (nebo zjevné učiněno bylo jméno jeho,) pravil, že Jan Křtitel vstal z mrtvých, a protož divové dějí se skrze něho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 15, 'Jiní pak pravili, že jest Eliáš; a jiní pravili, že jest prorok, aneb jako jeden z těch proroků.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 16, 'To uslyšev Heródes, řekl: Totoť jest ten Jan, kteréhož jsem já sťal. Ontě z mrtvých vstal.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 17, 'Ten zajisté Heródes poslav, jal Jana, a vsadil jej do žaláře pro Herodiadu manželku Filipa bratra svého, že ji byl za manželku pojal.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 18, 'Nebo pravil Jan Heródesovi: Neslušíť tobě míti manželky bratra svého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 19, 'Herodias pak lest skládala proti němu, a chtěla jej o hrdlo připraviti, ale nemohla.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 20, 'Nebo Heródes ostýchal se Jana, věda jej býti muže spravedlivého a svatého. I šetřil ho, a slýchaje jej, mnoho i činil, a rád ho poslouchal.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 21, 'Když pak přišel den příhodný, v němž Heródes, pamatuje den svého narození, učinil večeři knížatům svým a hejtmanům a předním mužům z Galilee,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 22, 'A když dcera té Herodiady tam vešla a tancovala, a zalíbila se Heródesovi i spoluhodovníkům, řekl král děvečce: Pros mne, zač chceš, a dámť.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 23, 'I přisáhl jí: Že začkoli prositi budeš, dám tobě, by pak bylo až do polovice království mého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 24, 'Ona pak vyšedši, řekla mateři své: Zač budu prositi? A ona řekla: Za hlavu Jana Křtitele.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 25, 'A všedši hned s chvátáním k králi, prosila, řkuci: Chci, abys mi dal hned na mise hlavu Jana Křtitele.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 26, 'Král pak zarmoutiv se velmi, pro přísahu a pro spoluhodovníky nechtěl jí oslyšeti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 27, 'Protož král ten poslav hned kata, rozkázal přinesti hlavu Janovu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 28, 'A on odšed, sťal jej v žaláři, a přinesl hlavu jeho na mise, a dal ji děvečce, a děvečka dala ji mateři své.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 29, 'Tedy uslyševše to učedlníci jeho, přišli, a vzali tělo jeho, a pochovali je v hrobě.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 30, 'Tehdy sšedše se apoštolé k Ježíšovi, zvěstovali jemu všecko, i to, co činili, i co učili.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 31, 'I řekl jim: Poďte vy sami obzvláštně na pusté místo, a odpočiňte maličko. Nebo bylo množství těch, kteříž přicházeli a odcházeli, tak že ani k jídlu chvíle neměli.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 32, 'I plavili se na lodí na pusté místo soukromí.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 33, 'A vidouce je zástupové, že jdou pryč, poznali jej mnozí. I zběhli se tam ze všech měst pěšky, a předešli je, a shromáždili se k němu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 34, 'Tedy vyšed Ježíš, uzřel zástup mnohý, a slitovalo mu se jich, že byli jako ovce, nemajíce pastýře. I počal je učiti mnohým věcem.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 35, 'A když se již prodlilo, přistoupivše k němu učedlníci jeho, řekli: Pustéť jest toto místo, a již se prodlilo.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 36, 'Propusť je, ať jdouce do okolních vesnic a městeček, nakoupí sobě chleba; nebo nemají, co by jedli.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 37, 'On pak odpověděv, řekl jim: Dejte vy jim jísti. I řkou jemu: Jdouce, koupíme za dvě stě grošů chleba, a dáme jim jísti?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 38, 'I dí jim: Kolik chlebů máte? Jděte a zvězte. A když zvěděli, řekli: Pět, a dvě rybě.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 39, 'I rozkázal jim, aby se kázali posaditi všechněm po houfích na zelené trávě.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 40, 'I usadili se rozdílně, po stu a po padesáti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 41, 'A vzav těch pět chlebů a ty dvě rybě, popatřiv do nebe, dobrořečil, i lámal chleby, a dal učedlníkům svým, aby kladli před ně. A dvě rybě rozdělil mezi všecky.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 42, 'I jedli všickni, a nasyceni jsou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 43, 'Potom sebrali drobtů dvanácte košů plných, i z ryb.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 44, 'A bylo těch, kteříž jedli ty chleby, okolo pěti tisíců mužů.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 45, 'A hned přinutil učedlníky své, aby vstoupili na lodí, a předešli jej přes moře k Betsaidě, až by on propustil zástup.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 46, 'A propustiv je, šel na horu, aby se modlil.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 47, 'A když byl večer, byla lodí u prostřed moře, a on sám na zemi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 48, 'A viděl je, a oni se s těžkostí plavili; (nebo byl vítr odporný jim.) A při čtvrtém bdění nočním přišel k nim, chodě po moři, a chtěl jich pominouti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 49, 'Oni pak uzřevše jej, an chodí po moři, domnívali se, že by obluda byla. I zkřikli.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 50, '(Nebo jej všickni viděli, a zstrašili se.) Ale hned promluvil k nim a řekl jim: Doufejtež, jáť jsem, nebojte se.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 51, 'I vstoupil k nim na lodí, a utišil se vítr; a oni mnohem více sami v sobě se děsili a divili.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 52, 'Nebo nerozuměli z strany chlebů; bylo zajisté srdce jejich zhrublo.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 53, 'A přeplavivše se, přišli do země Genezaretské, a tu lodí přistavili.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 54, 'A když vyšli z lodí, hned jej poznali.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 55, 'A běhajíce po vší krajině té, počali na ložcích nositi nemocné, kdežkoli uslyšeli o něm, že by byl.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 56, 'A kamžkoli vcházel do městeček neb do měst neb do vsí, na ulicech kladli neduživé, a prosili ho, aby se aspoň podolka roucha jeho dotkli. A kolikož jich koli se jeho dotklo, uzdraveni byli.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 1, 'I sešli se k němu farizeové a někteří z zákonníků, kteříž byli přišli z Jeruzaléma.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 2, 'A uzřevše některé z učedlníků jeho obecnýma rukama, (to jest neumytýma,) jísti chleby, reptali o to.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 3, 'Nebo farizeové i všickni Židé nejedí, leč by ruce umyli, držíce ustanovení starších.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 4, 'A po trhu nejedí, leč se umyjí. A jiné mnohé věci jsou, kteréž přijali, aby je zachovávali, jako umývání koflíků, žejdlíků a medenic i stolů.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 5, 'Potom otázali se ho farizeové a zákonníci: Proč učedlníci tvoji nezachovávají ustanovení starších, ale neumytýma rukama jedí chléb?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 6, 'On pak odpověděv, řekl jim: Dobře prorokoval Izaiáš o vás pokrytcích, jakož psáno jest: Lid tento rty mne ctí, srdce pak jejich daleko jest ode mne.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 7, 'Ale nadarmoť mne ctí, učíce učení a ustanovení lidská.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 8, 'Nebo opustivše přikázaní Boží, držíte ustanovení lidská, umývání žejdlíků a koflíků, a jiné věci mnohé těm podobné činíte.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 9, 'I pravil jim: Čistě vy rušíte přikázaní Boží, abyste ustanovení svá zachovali.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 10, 'Nebo Mojžíš pověděl: Cti otce svého i matku svou, a kdož by zlořečil otci neb mateři, ať smrtí umře.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 11, 'Ale vy pravíte: Řekl-li by člověk otci neb mateři: Korban, (totiž, dar jest to,) čímž by tobě ode mne pomoženo býti mohlo.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 12, 'A nedopustíte mu nic více učiniti otci svému neb mateři své,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 13, 'Rušíce slovo Boží ustanovením svým, kteréž jste ustanovili. A mnohé těm podobné věci činíte.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 14, 'I svolav všecken zástup, pravil jim: Slyšte mne všickni a rozumějte.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 15, 'Nic není z zevnitřku vcházejícího do člověka, což by jej poškvrniti mohlo; ale to, což pochází z něho, toť jest, což poškvrňuje člověka.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 16, 'Má-li kdo uši k slyšení, slyš.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 17, 'A když všel do domu od zástupu, tázali se ho učedlníci jeho o tom podobenství.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 18, 'I řekl jim: Tak jste i vy nerozumní? Což nerozumíte, že všecko, což z zevnitřku do člověka vchází, nemůže ho poškvrniti?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 19, 'Nebo nevchází v srdce jeho, ale v břicho, a potom ven vychází, čistěci všeliké pokrmy.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 20, 'Pravil pak, že to, což pochází z člověka, to poškvrňuje člověka.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 21, 'Nebo z vnitřku z srdce lidského zlá myšlení pocházejí, cizoložstva, smilstva, vraždy,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 22, 'Krádeže, lakomství, nešlechetnosti, lest, nestydatost, oko zlé, rouhání, pýcha, bláznovství.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 23, 'Všecky tyto zlé věci pocházejí z vnitřku, a poškvrňují člověka.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 24, 'A vstav odtud, odšel do končin Týru a Sidonu, a všed do domu, nechtěl, aby kdo věděl, ale nemohl se tajiti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 25, 'Nebo uslyševši o něm žena, jejíž dcerka měla ducha nečistého, přišla a padla k nohám jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 26, '(Byla pak ta žena pohanka, Syrofenitská rodem.) I prosila ho, aby ďábelství vyvrhl z její dcery.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 27, 'Ale Ježíš řekl jí: Nechať se prvé nasytí dítky; nebť není slušné vzíti chléb dětem a vrci štěňatům.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 28, 'A ona odpověděla a řekla mu: Ovšem, Pane, nebo štěňátka jedí pod stolem drobty synů.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 29, 'I řekl jí: Pro tu řeč jdi, vyšloť jest ďábelství z tvé dcery.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 30, 'I odšedši do domu svého, nalezla děvečku, ana leží na loži, a ďábelství z ní vyšlo.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 31, 'Tedy vyšed zase z končin Tyrských a Sidonských, přišel k moři Galilejskému, prostředkem krajin Desíti měst.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 32, 'I přivedli jemu hluchého a zajikavého, a prosili ho, aby na něj ruku vzložil.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 33, 'A pojav jej soukromí ven z zástupu, vložil prsty své v uši jeho, a plinuv, dotekl se jazyka jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 34, 'A vzezřev k nebi, vzdechl a řekl jemu: Efata, to jest, otevři se.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 35, 'A hned otevříny jsou uši jeho, a rozvázán jest svazek jazyka jeho, i mluvil právě.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 36, 'I přikázal jim, aby žádnému nepravili. Ale jakžkoli on jim přikazoval, oni mnohem více ohlašovali.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 37, 'A převelmi se divili, řkouce: Dobře všecky věci učinil. I hluchým rozkázal slyšeti, i němým mluviti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 1, 'V těch dnech když velmi veliký zástup byl, a neměli, co by jedli, svolav Ježíš učedlníky své, řekl jim:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 2, 'Lítost mám nad zástupy; nebo již tři dni trvají se mnou, a nemají, co by jedli.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 3, 'A rozpustím-li je lačné do domů jejich, zhynou na cestě; nebo někteří z nich zdaleka přišli.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 4, 'Odpověděli mu učedlníci jeho: I odkud bude moci kdo tyto nakrmiti chleby zde na poušti?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 5, 'I otázal se jich: Kolik máte chlebů? A oni řekli: Sedm.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 6, 'I kázal zástupu posaditi se na zemi. A vzav těch sedm chlebů, díky učiniv, lámal a dával učedlníkům svým, aby předkládali. I kladli před zástup.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 7, 'A měli rybiček maličko. Jichž požehnav, kázal i ty před ně klásti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 8, 'I jedli a nasyceni jsou; a sebrali, což pozůstalo drobtů, sedm košů.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 9, 'Těch pak, kteříž jedli, bylo okolo čtyř tisíců. I propustil je.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 10, 'Potom hned vstoupiv na lodí s učedlníky svými, přeplavil se do krajin Dalmanutských.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 11, 'I vyšli farizeové, a počali se s ním hádati, hledajíce od něho znamení s nebe, pokoušejíce ho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 12, 'A on vzdech duchem svým, dí: Co pokolení toto znamení hledá? Amen pravím vám: Nebude dáno znamení pokolení tomuto.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 13, 'A opustiv je, vstoupil zase na lodí, i plavil se dále.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 14, 'I zapomenuli s sebou vzíti chlebů, a neměli než jeden chléb s sebou na lodí.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 15, 'Tedy přikazoval jim, řka: Vizte a pilně se šetřte kvasu farizejského a kvasu Heródesova.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 16, 'I přemyšlovali, řkouce jeden k druhému: Chleba nemáme.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 17, 'A znaje to Ježíš, řekl jim: Co přemyšlujete o tom, že chleba nemáte? Ještě neznáte, ani nerozumíte? Ještě máte oslepené své srdce?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 18, 'Oči majíce, nevidíte? A uši majíce, neslyšíte? A nepomníte,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 19, 'Že jsem pět chlebů lámal mezi pět tisíců? Kolik jste plných košů drobtů sebrali? Řekli jemu: Dvanácte.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 20, 'A když také sedm chlebů mezi čtyři tisíce, kolik jste plných košů drobtů vzali? I řkou jemu: Sedm.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 21, 'I řekl jim: Kterakž nerozumíte?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 22, 'I přišel do Betsaidy, a přivedli k němu slepého, prosíce ho, aby se ho dotekl.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 23, 'I ujav toho slepého za ruku, vyvedl jej ven z městečka, a plinuv na oči jeho, a vloživ na něj ruce, otázal se ho, viděl-li by co.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 24, 'A on pohleděv zhůru, řekl: Znamenám lidi; nebo vidím, že chodí jako stromové.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 25, 'Potom opět vložil ruce na oči jeho, a kázal mu hleděti zhůru. I uzdraven jest, tak že i zdaleka jasně viděl všecky.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 26, 'I odeslal jej do domu jeho, řka: Aniž do toho městečka choď, aniž komu z městečka prav.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 27, 'Tedy vyšel Ježíš a učedlníci jeho do městeček Cesaree Filipovy. A na cestě tázal se učedlníků svých, řka jim: Kým mne praví býti lidé?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 28, 'Kteříž odpověděli: Janem Křtitelem, a jiní Eliášem, jiní pak jedním z proroků.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 29, 'Tedy on řekl jim: Vy pak kým mne býti pravíte? Odpověděv Petr, řekl jemu: Ty jsi Kristus.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 30, 'I přikázal jim s pohrůžkou, aby o něm žádnému nepravili.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 31, 'I počal učiti je, že Syn člověka musí mnoho trpěti, a potupen býti od starších a předních kněží {biskupů} a zákonníků, a zabit býti, a ve třech dnech z mrtvých vstáti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 32, 'A zjevně to slovo mluvil. Protož chytiv jej Petr, počal mu domlouvati.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 33, 'Kterýžto obrátiv se, a pohleděv na učedlníky své, přimluvil Petrovi, řka: Jdiž za mnou, satane; nebo nechápáš, co jest Božího, ale co lidského.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 34, 'A svolav zástup s učedlníky svými, řekl jim: Chce-li kdo za mnou přijíti, zapři sebe sám, a vezmi kříž svůj, a následuj mne.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 35, 'Nebo chtěl-li by kdo duši svou zachovati, ztratíť ji; pakli by kdo ztratil duši svou pro mne a pro evangelium, tenť ji zachová.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 36, 'Nebo co prospěje člověku, by všecken svět získal, a své duši škodu učinil?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 37, 'Aneb jakou dá člověk odměnu za duši svou?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 38, 'Nebo kdož by se koli za mne styděl a za má slova v tomto pokolení cizoložném a hříšném, i Syn člověka styděti se bude za něj, když přijde v slávě Otce svého s anděly svatými.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 1, 'I pravil jim: Amen pravím vám, žeť jsou někteří z stojících tuto, kteříž neokusí smrti, až i uzří království Boží přicházející v moci.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 2, 'A po šesti dnech pojal Ježíš Petra a Jakuba a Jana, i uvedl je na horu vysokou soukromí samy, a proměnil se před nimi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 3, 'A učiněno jest roucho jeho stkvoucí a bílé velmi jako sníh, ješto tak bílého bělič na zemi učiniti nemůže.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 4, 'I uzřeli Eliáše s Mojžíšem, ani s Ježíšem mluví.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 5, 'A odpověděv Petr, řekl Ježíšovi: Mistře, dobréť jest nám tuto býti. Protož udělejme tři stánky, tobě jeden, Mojžíšovi jeden, a Eliášovi jeden.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 6, 'Nebo nevěděl, co mluví; byli zajisté přestrašeni.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 7, 'I stal se oblak zastěňující je, a přišel hlas z oblaku, řkoucí: Tentoť jest ten Syn můj milý, jeho poslouchejte.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 8, 'A hned obezřevše se, žádného víc neviděli než samého Ježíše s sebou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 9, 'A když sstupovali s hory, přikázal jim, aby toho žádnému nevypravovali, co viděli, než až Syn člověka z mrtvých vstane.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 10, 'I zachovali tu věc u sebe, tížíce mezi sebou, co by to bylo z mrtvých vstáti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 11, 'I otázali se ho, řkouce: Což to pak zákonníci praví, že Eliáš musí přijíti prvé?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 12, 'On pak odpověděv, řekl jim: Eliáš přijda nejprvé, napraví všecky věci, a jakož psáno jest o Synu člověka, že musí mnoho trpěti, a za nic položen býti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 13, 'Ale pravím vám, že i Eliáš přišel, i učinili mu, což chtěli, jakož psáno jest o něm.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 14, 'Tedy přišed k učedlníkům, uzřel zástup veliký okolo nich, a zákonníky, an se hádají s nimi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 15, 'A hned všecken zástup uzřev jej, ulekli se; a zběhše se, přivítali ho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 16, 'I otázal se zákonníků: Co se hádáte spolu?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 17, 'A odpovídaje jeden z zástupu, řekl: Mistře, přivedl jsem syna svého k tobě, kterýž má ducha němého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 18, 'Ten kdyžkoli jej pochopí, lomcuje jím, a on se sliní, a škřipí zubami svými, a svadne. I řekl jsem učedlníkům tvým, aby jej vyvrhli, ale nemohli.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 19, 'A on odpovídaje jemu, řekl: Ó národe nevěrný. Ale dokudž s vámi budu? A dokudž vás trpěti budu? Přiveďte jej ke mně.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 20, 'I přivedli ho k němu. A jakž jej uzřel, hned ním duch lomcoval; a padna na zemi, válel se a slinil.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 21, 'I otázal se otce jeho: Dávno-li se jemu to stalo? A on řekl: Od dětinství.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 22, 'A často jím metal i na oheň i do vody, aby jej zahubil. Ale můžeš-li co, spomoz nám, slituje se nad námi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 23, 'A Ježíš řekl jemu: Můžeš-li tomu věřiti; všeckoť jest možné věřícímu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 24, 'A i hned zvolav otec mládence toho s slzami, řekl: Věřím, Pane, spomoz nedověře mé.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 25, 'Uzřev pak Ježíš, že se zbíhá zástup, přimluvil duchu tomu nečistému, řka jemu: Duchu němý a hluchý, já tobě přikazuji, vyjdi z něho, a nevcházej více do něho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 26, 'Tedy křiče a velmi jím lomcuje, vyšel. I učiněn jest jako mrtvý, tak že mnozí pravili, že umřel.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 27, 'Ale Ježíš ujav jej za ruku, pozdvihl ho. I vstal.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 28, 'A když všel do domu, učedlníci jeho otázali se ho soukromí: Proč jsme my ho nemohli vyvrci?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 29, 'I řekl jim: Toto pokolení nijakž nemůž vyjíti, jediné skrze modlitbu a půst.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 30, 'A jdouce odtud, šli spolu skrze Galilei, ale nechtěl, aby kdo věděl.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 31, 'Nebo učil učedlníky své a pravil jim: Že Syn člověka dán bude v ruce lidské, a zamordujíť jej, ale zamordován jsa, třetího dne z mrtvých vstane.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 32, 'Oni pak nesrozuměli tomu povědění, a však ostýchali se ho otázati.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 33, 'I přišel do Kafarnaum, a v domě byv, otázal se jich: Co jste na cestě mezi sebou rozjímali?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 34, 'Ale oni mlčeli. Nebo hádali se byli na cestě mezi sebou, kdo by z nich byl větší.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 35, 'A posadiv se, zavolal dvanácti, a dí jim: Chce-li kdo první býti, budeť ze všech nejposlednější a všech služebník.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 36, 'A vzav pacholátko, postavil je u prostřed nich, a vzav je na lokty, řekl jim:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 37, 'Kdož by koli jedno z takových pacholátek přijal ve jménu mém, mneť přijímá; a kdož by mne koli přijal, ne mneť přijímá, ale toho, kterýž mne poslal.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 38, 'I odpověděl mu Jan, řka: Mistře, viděli jsme jednoho, an ve jménu tvém ďábly vymítá, kterýž nechodí s námi; i bránili jsme mu, proto že s námi nechodí.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 39, 'Ježíš pak řekl: Nebraňtež mu. Neboť není žádného, kterýž by divy činil ve jménu mém, aby mohl snadně zle mluviti o mně.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 40, 'Nebo kdož není proti nám, s námiť jest.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 41, 'Kdož by koli zajisté dal vám píti číši vody ve jménu mém, proto že jste Kristovi, amen pravím vám, neztratíť nikoli odplaty své.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 42, 'A kdož by koli pohoršil jednoho z těchto maličkých, věřících ve mne, mnohem by mu lépe bylo, aby byl zavěšen na hrdlo jeho žernov mlýnský a vržen byl do moře.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 43, 'A horšila-li by tě ruka tvá, utni ji. Lépeť jest tobě bezrukému vjíti do života, nežli obě ruce majícímu jíti do pekla v ten oheň neuhasitelný,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 44, 'Kdež červ jejich neumírá, a oheň nehasne.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 45, 'A pakli noha tvá horšila by tě, utni ji. Lépeť jest tobě kulhavému vjíti do života, nežli obě noze majícímu uvrženu býti do pekla, v ten oheň neuhasitelný,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 46, 'Kdež červ jejich neumírá, a oheň nehasne.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 47, 'Pakli by tě oko tvé horšilo, vylup je. Lépeť jest tobě jednookému vjíti do království Božího, nežli obě oči majícímu uvrženu býti do ohně pekelného,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 48, 'Kdež červ jejich neumírá, a oheň nehasne.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 49, 'Nebo každý ohněm bude solen, a všeliká obět solí bude osolena.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 50, 'Dobráť jest sůl. Pakli sůl bude neslaná, čím ji osolíte? Mějte sůl sami v sobě, a pokoj mějte mezi sebou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 1, 'A vstav odtud, přišel do končin Judských skrze krajinu za Jordánem ležící. I sešli se k němu zase zástupové, a jakž obyčej měl, opět je učil.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 2, 'Tedy přistoupivše farizeové, otázali se ho: sluší-li muži propustiti ženu? pokoušejíce ho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 3, 'On pak odpovídaje, řekl jim: Co vám přikázal Mojžíš?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 4, 'Kteříž řekli: Mojžíš dopustil lístek rozloučení napsati a propustiti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 5, 'I odpověděv Ježíš, řekl jim: Pro tvrdost srdce vašeho napsal vám to přikázaní.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 6, 'Ale od počátku stvoření muže a ženu učinil je Bůh.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 7, 'Protoť opustí člověk otce svého i matku, a přídržeti se bude ženy své.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 8, 'I budou ti dva jedno tělo. A tak již nejsou dva, ale jedno tělo.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 9, 'Protož což Bůh spojil, člověk nerozlučuj.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 10, 'A v domě opět učedlníci jeho otázali se ho o též věci.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 11, 'I dí jim: Kdož by koli propustil manželku svou a jinou pojal, cizoloží proti ní.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 12, 'A jestliže by žena propustila muže svého a za jiného se vdala, cizoloží.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 13, 'Tedy přinášeli k němu dítky, aby se jich dotýkal. Ale učedlníci přimlouvali těm, kteříž je nesli.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 14, 'To viděv Ježíš, nelibě to nesl, a řekl jim: Nechte dítek jíti ke mně, a nebraňte jim, nebo takovýchť jest království Boží.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 15, 'Amen pravím vám: Kdož by koli nepřijal království Božího jako dítě, nikoliť do něho nevejde.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 16, 'A bera je na lokty své, a vzkládaje na ně ruce, požehnání jim dával.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 17, 'Potom když vyšel na cestu, přiběhl jeden, a poklekna před ním, otázal se ho: Mistře dobrý, co učiním, abych života věčného dědičně došel?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 18, 'I řekl mu Ježíš: Co mne nazýváš dobrým? Žádný není dobrý, než jediný Bůh.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 19, 'Přikázaní umíš: Nezcizoložíš, nezabiješ, neukradneš, nevydáš falešného svědectví, neoklamáž, cti otce svého i matku.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 20, 'A on odpověděv, řekl jemu: Mistře, toho všeho jsem ostříhal od své mladosti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 21, 'Tedy Ježíš pohleděv na něj, zamiloval ho, a řekl jemu: Jednohoť se nedostává. Jdi, a cožkoli máš, prodej, a dej chudým, a budeš míti poklad v nebi; a poď, následuj mne, vezma kříž.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 22, 'On pak zarmoutiv se pro to slovo, odšel, truchliv jsa; nebo měl mnohá zboží.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 23, 'A pohleděv vůkol Ježíš, dí učedlníkům svým: Jak nesnadně ti, kteříž statky mají, vejdou do království Božího.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 24, 'Tedy učedlníci užasli se nad těmi řečmi jeho. Ježíš pak zase odpověděv, dí jim: Synáčkové, kterak nesnadné jest doufajícím v statek do království Božího vjíti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 25, 'Snáze jest velbloudu skrze jehelní ucho projíti, nežli bohatému vjíti do království Božího.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 26, 'Oni pak více se děsili, řkouce mezi sebou: I kdož může spasen býti?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 27, 'A pohleděv na ně Ježíš, dí: U lidíť jest nemožné, ale ne u Boha; nebo u Boha všecko možné jest.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 28, 'I počal Petr mluviti k němu: Aj, my opustili jsme všecko, a šli jsme za tebou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 29, 'Odpověděv pak Ježíš, řekl: Amen pravím vám, žádného není, ješto by opustil dům, neb bratří, neb sestry, neb otce, neb matku, neb manželku, neb dítky, neb rolí pro mne a pro evangelium,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 30, 'Aby nevzal stokrát tolik nyní v času tomto domů a bratrů a sester a matek a dítek a rolí s protivenstvím, a v budoucím věku život věčný.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 31, 'Mnozíť pak první budou poslední, a poslední první.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 32, 'Byli pak na cestě, jdouce do Jeruzaléma, a Ježíš šel napřed. I byli předěšeni, a jdouce za ním, báli se. Tedy pojav opět dvanácte, počal jim praviti, co se jemu má státi,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 33, 'Řka: Aj, vstupujeme do Jeruzaléma, a Syn člověka vydán bude předním kněžím {biskupům} a zákonníkům i odsoudí jej na smrt, a vydadí jej pohanům.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 34, 'Kteřížto posmívati se budou jemu, a ubičují ho, a uplijí i zabijí jej, ale třetího dne z mrtvých vstane.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 35, 'Tedy přistoupili k němu Jakub a Jan, synové Zebedeovi, řkouce: Mistře, chceme, zač bychom koli prosili tebe, abys učinil nám.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 36, 'On pak řekl jim: Co chcete, abych vám učinil?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 37, 'I řekli jemu: Dej nám, abychom jeden na pravici tvé a druhý na levici tvé seděli v slávě tvé.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 38, 'Ježíš pak řekl jim: Nevíte, zač prosíte. Můžete-li píti kalich, kterýž já piji, a křtíti se křtem, kterýmž já se křtím?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 39, 'A oni řekli jemu: Můžeme. Ježíš pak řekl jim: Kalich zajisté, kterýž já piji, píti budete, a křtem, kterýmž já se křtím, křtěni budete,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 40, 'Ale seděti na pravici mé neb na levici mé, neníť má věc dáti, ale kterýmž připraveno jest.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 41, 'A uslyšavše to deset, počali se hněvati na Jakuba a na Jana.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 42, 'Ale Ježíš povolav jich, řekl jim: Víte, že ti, kteříž sobě zalibují vládnouti nad národy, panujíť nad nimi; a kteříž velicí u nich jsou, moc provozují nad nimi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 43, 'Ne takť bude mezi vámi. Ale kdožkoli chtěl by mezi vámi býti veliký, budiž váš služebník.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 44, 'A kdožkoli z vás chtěl by býti přední, budiž služebník všech.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 45, 'Nebo i Syn člověka nepřišel, aby mu sloužili, ale aby sloužil, a aby dal duši svou na vykoupení za mnohé.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 46, 'Tedy přišli do Jericho, a když vycházel on z Jericha, i učedlníci jeho a zástup mnohý, Timeův syn, Bartimeus slepý, seděl podlé cesty, žebře.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 47, 'A když uslyšel, že by byl Ježíš Nazaretský, počal volati a říci: Ježíši, synu Davidův, smiluj se nade mnou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 48, 'I přimlouvali mu mnozí, aby mlčel. Ale on mnohem více volal: Synu Davidův, smiluj se nade mnou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 49, 'Tedy zastaviv se Ježíš, kázal ho zavolati. I zavolali toho slepého, řkouce jemu: Dobré mysli buď, vstaň, volá tě.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 50, 'On pak povrh plášť svůj, a zchopiv se, šel k Ježíšovi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 51, 'I odpověděv Ježíš, dí jemu: Co chceš, ať učiním? A slepý řekl jemu: Mistře, ať vidím.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 52, 'Tedy Ježíš řekl jemu: Jdi, víra tvá tě uzdravila. A hned prohlédl, a šel cestou za Ježíšem.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 1, 'A když se přiblížili k Jeruzalému a Betfagi i Betany při hoře Olivetské, poslal dva z učedlníků svých.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 2, 'A řekl jim: Jděte do městečka, kteréž proti vám jest, a hned vejdouce tam, naleznete oslátko přivázané, na kterémž nižádný z lidí neseděl. Odvížíce, přiveďte.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 3, 'A řekl-liť by vám kdo: Co to činíte? rcete: Že ho Pán potřebuje. A hned je pošle sem.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 4, 'I odešli, a nalezli oslátko přivázané vně u dveří na rozcestí. I odvázali je.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 5, 'Tedy někteří z těch, kteříž tu stáli, řekli jim: Co činíte, odvazujíce oslátko?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 6, 'Oni pak řekli jim, jakož byl přikázal Ježíš. I nechali jich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 7, 'Protož přivedli oslátko k Ježíšovi, a vložili na ně roucha svá. I vsedl na ně.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 8, 'Mnozí pak stlali roucha svá na cestě, a jiní ratolesti sekali z stromů, a metali na cestu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 9, 'A kteříž napřed šli, i ti, kteříž za ním šli, volali, řkouce: Hosanna. Požehnaný, kterýž se béře ve jménu Páně.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 10, 'Požehnané království otce našeho Davida, kteréž přišlo ve jménu Páně. Hosanna na výsostech.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 11, 'I všel do Jeruzaléma Ježíš, i do chrámu. A spatřiv tu všecko, když již byla večerní hodina, vyšel do Betany se dvanácti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 12, 'A druhého dne, když vycházel z Betany, zlačněl.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 13, 'A uzřev z daleka fík, an má lístí, šel, zda by co nalezl na něm. A když přišel k němu, nic nenalezl kromě lístí; nebo nebyl čas fíků.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 14, 'Tedy odpověděv Ježíš, řekl jemu: Již více na věky nižádný z tebe ovoce nejez. A slyšeli to učedlníci jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 15, 'I přišli do Jeruzaléma. A všed Ježíš do chrámu, počal vymítati ty, kteříž prodávali a kupovali v chrámě, a stoly penězoměnců a stolice prodávajících holuby převracel.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 16, 'A nedopustil, aby kdo nádobu nesl skrze chrám.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 17, 'I učil je, řka jim: Zdaliž není psáno, že dům můj dům modlitby slouti bude u všech národů? Vy pak učinili jste jej peleší lotrů.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 18, 'Slyšeli pak to zákonníci i přední kněží {biskupové}, a hledali, kterak by jej zahubili; nebo se ho báli, proto že všecken zástup divil se učení jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 19, 'A když byl večer, vyšel z města.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 20, 'A jdouce ráno, uzřeli ten fík, an usechl z kořene.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 21, 'Tedy zpomenuv Petr, řekl jemu: Mistře, aj, ten fík, kterémuž jsi zlořečil, usechl.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 22, 'I odpověděv Ježíš, řekl jim: Mějte víru Boží.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 23, 'Nebo amen pravím vám, že kdož by koli řekl hoře této: Zdvihni se a vrz sebou do moře, a nepochyboval by v srdci svém, ale věřil by, že se stane, cožkoli dí, staneť se jemu tak, což by koli řekl.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 24, 'Protož pravím vám: Zač byste koli, modléce se, prosili, věřte, že vezmete, a staneť se vám.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 25, 'A když se postavíte k modlení, odpouštějte, máte-li co proti komu, aby i Otec váš nebeský odpustil vám hříchy vaše.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 26, 'Nebo jestliže vy neodpustíte, ani Otec váš, kterýž v nebesích jest, odpustí vám hříchů vašich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 27, 'I přišli zase do Jeruzaléma. A když on procházel se v chrámě, přistoupili k němu přední kněží {biskupové} a zákonníci a starší.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 28, 'I řekli jemu: Jakou mocí to činíš? A kdo tobě dal tu takovou moc, abys tyto věci činil?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 29, 'Tedy odpovídaje Ježíš, řekl jim: Otížiť se i já vás na jednu věc. Odpovězte mi, a povím vám, jakou mocí to činím.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 30, 'Křest Janův s nebe-li byl, čili z lidí? Odpovězte mi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 31, 'I rozjímali sami mezi sebou, řkouce: Díme-li: S nebe, díť: Proč jste tedy neuvěřili jemu?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 32, 'Pakli díme: Z lidí, bojíme se lidu. Nebo všickni o Janovi smyslili, že právě byl prorok.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 33, 'I odpověděvše, řekli Ježíšovi: Nevíme. A Ježíš odpovídaje, řekl jim: Aniž já vám povím, jakou mocí to činím.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 1, 'Tedy počal jim mluviti v podobenstvích: Vinici štípil člověk, a opletl ji plotem, a vkopal pres, a ustavěl věži, a pronajal ji vinařům, i odšel na cestu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 2, 'A když toho čas byl, poslal k vinařům služebníka, aby od vinařů vzal ovoce z vinice.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 3, 'Oni pak javše jej, zmrskali ho, a odeslali prázdného.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 4, 'I poslal k nim zase jiného služebníka. I toho též kamenovavše, ranili v hlavu, a odeslali zohaveného.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 5, 'I poslal opět jiného. I toho zabili, a mnoho jiných, z nichž některé zmrskali, a jiné zmordovali.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 6, 'Ještě pak maje jediného syna milého, i toho poslal k nim naposledy, řka: Ustýdnouť se syna mého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 7, 'Ale vinaři řekli jedni k druhým: Tentoť jest dědic; poďte, zabíme jej, a budeť naše dědictví.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 8, 'Tedy javše jej, zabili ho, a vyvrhli ven z vinice.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 9, 'Což tedy učiní pán vinice? Přijde, a zatratí vinaře ty, a dá vinici jiným.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 10, 'Zdaliž jste písma toho nečtli? Kámen, kterýž zavrhli stavitelé, ten učiněn jest hlavou úhlovou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 11, 'Ode Pána stalo se toto, a jest divné před očima našima.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 12, 'I hledali ho jíti, ale báli se zástupu; nebo poznali, že podobenství to proti nim pověděl. A nechavše ho, odešli pryč.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 13, 'Potom poslali k němu některé z farizeů a Herodiánů, aby jej polapili v řeči.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 14, 'Kteřížto přišedše, řekli jemu: Mistře, víme, že jsi pravdomluvný, a nedbáš na žádného; nebo nepatříš na osobu lidskou, ale v pravdě cestě Boží učíš. Sluší-li daň dávati císaři, čili nic? Dáme-liž, čili nedáme?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 15, 'On pak znaje pokrytství jejich, řekl jim: Co mne pokoušíte? Přineste mi peníz, ať pohledím.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 16, 'A oni podali. Tedy řekl jim: Čí jest tento obraz a nápis? A oni řekli mu: Císařův.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 17, 'I odpověděv Ježíš, řekl jim: Dávejtež tedy, což jest císařova, císaři, a což jest Božího, Bohu. I podivili se tomu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 18, 'Potom přišli k němu saduceové, kteříž praví, že není z mrtvých vstání. I otázali se ho, řkouce:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 19, 'Mistře, Mojžíš nám napsal: Kdyby čí bratr umřel, a ostavil manželku, a synů by neměl, aby bratr jeho pojal manželku jeho, a vzbudil símě bratru svému.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 20, 'I bylo sedm bratrů. A první pojav manželku, a umřev, nepozůstavil semene.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 21, 'A druhý pojav ji, také umřel, a aniž ten ostavil semene. A třetí tolikéž.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 22, 'A tak ji pojalo těch sedm, a nezůstavili semene. Nejposléze pak po všech umřela i ta žena.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 23, 'Protož při vzkříšení, když z mrtvých vstanou, čí z těch bude manželka? Nebo jich sedm mělo ji za manželku.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 24, 'A odpovídaje Ježíš, řekl jim: Zdaliž ne proto bloudíte, že neznáte písem ani moci Boží?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 25, 'Nebo když vstanou z mrtvých, nebudou se ženiti ani vdávati, ale budou jako andělé nebeští.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 26, 'O mrtvých pak, že mají vstáti, zdaliž jste nečtli v knize Mojžíšově, kterak ve kři promluvil k němu Bůh, řka: Já jsem Bůh Abrahamův, a Bůh Izákův, a Bůh Jákobův?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 27, 'Neníť Bůh mrtvých, ale Bůh živých. Protož vy velmi bloudíte.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 28, 'Tedy přistoupil jeden z zákonníků, slyšev je spolu se hádající, a vida, že jim dobře odpověděl, otázal se ho: Které jest přikázaní první ze všech?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 29, 'A Ježíš odpověděl jemu, že první ze všech přikázaní jest: Slyš, Izraeli, Pán Bůh náš Pán jeden jest.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 30, 'Protož milovati budeš Pána Boha svého ze všeho srdce svého, a ze vší duše své, a ze vší mysli své, i ze všech mocí svých. To jest první přikázaní.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 31, 'Druhé pak podobné toto: Milovati budeš bližního svého jako sebe samého. Většího přikázaní jiného nad tato není.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 32, 'I řekl jemu ten zákonník: Mistře, dobře jsi v pravdě pověděl. Nebo jeden jest Bůh, a není jiného kromě něho;');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 33, 'A milovati ho ze všeho srdce, a ze vší mysli, a ze vší duše, i ze všech mocí, a milovati bližního jako sebe samého jest nade všecky zápaly a oběti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 34, 'A viděv Ježíš, že by moudře odpověděl, dí jemu: Nejsi daleko od království Božího. A žádný více nesměl se ho tázati.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 35, 'I odpovídaje Ježíš, řekl, uče v chrámě: Kterak praví zákonníci, že Kristus jest syn Davidův?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 36, 'Nebo David praví v Duchu svatém: Řekl Pán Pánu mému: Seď na pravici mé, ažť i položím nepřátely tvé za podnože noh tvých.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 37, 'Poněvadž sám David nazývá jej Pánem, kterakž tedy syn jeho jest? A mnohý zástup rád ho poslouchal.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 38, 'I mluvil jim v učení svém: Varujte se zákonníků, kteříž chtějí v krásném rouše choditi, a pozdravováni býti na trzích,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 39, 'A na předních stolicech seděti v školách, a přední místa míti na večeřech,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 40, 'Kteřížto zžírají domy vdovské, a to pod zámyslem dlouhých modliteb. Tiť vezmou soud těžší.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 41, 'A posadiv se Ježíš proti pokladnici, díval se, kterak zástup metal peníze do pokladnice. A mnozí bohatí metali mnoho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 42, 'A přišedši jedna chudá vdova, i vrhla dva šarty, což jest čtvrtá částka peníze.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 43, 'I svolav učedlníky své, dí jim: Amen pravím vám, že tato chudá vdova více uvrhla, než tito všickni, kteříž metali do pokladnice.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 44, 'Nebo všickni z toho, což jim zbývalo, metali, ale tato z své chudoby, všecko, což měla, uvrhla, všecku živnost svou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 1, 'A když vycházel z chrámu, dí jemu jeden z učedlníků jeho: Mistře, pohleď, kteraké kamení a jaké stavení!');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 2, 'Tedy Ježíš odpovídaje, řekl jemu: Vidíš tato tak veliká stavení? Nebudeť ostaven kámen na kameni, kterýž by nebyl zbořen.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 3, 'A když se posadil na hoře Olivetské proti chrámu, otázali se jeho soukromí Petr, Jakub a Jan a Ondřej:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 4, 'Pověz nám, kdy to bude? A které znamení, když se toto všecko bude plniti?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 5, 'Ježíš pak odpovídaje jim, počal praviti: Vizte, aby vás někdo nesvedl.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 6, 'Neboť mnozí přijdou ve jménu mém, řkouce: Já jsem Kristus, a mnohéť svedou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 7, 'Když pak uslyšíte o boji a pověst o válkách, nestrachujte se; nebo musí to býti, ale ne i hned konec.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 8, 'Povstaneť zajisté národ proti národu a království proti království, a budou země třesení po místech, a hladové i bouřky.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 9, 'A toť počátkové bolestí. Vy pak šetřte se. Nebo vydávati vás budou na sněmy a do shromáždění; budete biti, a před vládaři a králi stanete pro mne, na svědectví jim.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 10, 'Ale ve všech národech nejprv musí býti kázáno evangelium.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 11, 'Když pak vás povedou, vyzrazujíce, nestarejte se předtím, co byste mluvili, aniž pečlivě přemyšlujte, ale což vám bude dáno v tu hodinu, to mluvte; nebo nejste vy, kteříž mluvíte, ale Duch svatý.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 12, 'Vydáť pak bratr bratra na smrt a otec syna, a povstanou děti proti rodičům, a budou je mordovati.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 13, 'A budete v nenávisti všechněm pro jméno mé. Ale kdož setrvá až do konce, tenť spasen bude.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 14, 'Když pak uzříte ohavnost zpuštění, o kteréž povědíno jest skrze Daniele proroka, ana stojí, kdež by státi neměla, (kdo čte, rozuměj,) tehdáž ti, kdož by v Židovstvu byli, ať utekou na hory.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 15, 'A kdož by na střeše byl, nesstupuj do domu, ani vcházej, aby co vzal z domu svého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 16, 'A kdo na poli, nevracuj se zase, aby vzal roucho své.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 17, 'Běda pak těhotným a těm, kteréž krmí v těch dnech.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 18, 'Protož modlte se, aby utíkání vaše nebylo v zimě.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 19, 'Neboť budou ti dnové ssoužení, jakéhož nebylo od počátku stvoření, kteréž Bůh stvořil, až dosavad, aniž bude.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 20, 'A byť nebyl ukrátil Pán těch dnů, nebyl by spasen žádný člověk. Ale pro vyvolené, kteréž vyvolil, ukrátil těch dnů.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 21, 'A tehdáž řekl-li by vám kdo: Aj, teď jest Kristus, aneb aj, tamto, nevěřte.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 22, 'Neboť povstanou falešní Kristové a falešní proroci, a budou činiti divy a zázraky k svedení, by možné bylo, také i vyvolených.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 23, 'Vy pak šetřte se. Aj, předpověděl jsem vám všecko.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 24, 'V těch pak dnech, po ssoužení tom, slunce se zatmí, a měsíc nedá světla svého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 25, 'A hvězdy nebeské budou padati, a moci, které jsou na nebi, pohnou se.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 26, 'A tehdážť uzří Syna člověka, an se béře v oblacích s mocí velikou a s slávou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 27, 'I tehdyť pošle anděly své, a shromáždí vyvolené své ode čtyř větrů, od končin země až do končin nebe.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 28, 'Od fíku pak učte se podobenství tomuto: Když již ratolest jeho odmladne, a vypučí se lístí, znáte, že blízko jest léto.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 29, 'Takž i vy, když uzříte, ano se tyto věci dějí, vězte, že blízko jest a ve dveřích.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 30, 'Amen pravím vám, žeť nepomine pokolení toto, až se tyto všecky věci stanou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 31, 'Nebe a země pominou, ale slova má nikoli nepominou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 32, 'Ale o tom dni a hodině žádný neví, ani andělé, kteříž jsou v nebesích, ani Syn, jediné Otec.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 33, 'Vizte, bděte a modlte se; nebo nevíte, kdy bude ten čas.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 34, 'Jako člověk, kterýž daleko odšel, opustiv dům svůj, a poručiv služebníkům svým vládařství, a jednomu každému práci jeho, vrátnému přikázal, aby bděl.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 35, 'Protož bděte; nebo nevíte, kdy Pán domu přijde, u večer-li, čili o půlnoci, čili když kohouti zpívají, čili ráno.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 36, 'Aby snad přijda v nenadále, nenalezl vás, a vy spíte.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 37, 'A cožť vám pravím, všechněmť pravím: Bděte.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 1, 'Po dvou pak dnech byl hod beránka a přesnic; i hledali přední kněží {biskupové} a zákonníci, kterak by jej lstivě jmouce, zamordovali.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 2, 'Ale pravili: Ne v svátek, aby snad nebyl rozbroj v lidu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 3, 'A když byl v Betany, v domu Šimona malomocného, a seděl za stolem, přišla žena, mající nádobu alabastrovou masti velmi drahé, z nardového koření. A rozbivši alabastrovou nádobu, vylila ji na hlavu jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 4, 'I hněvali se někteří mezi sebou, řkouce: I proč ztráta masti této stala se?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 5, 'Nebo mohlo toto prodáno býti, dráže než za tři sta peněz, a dáno býti chudým. I zpouzeli se na ni.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 6, 'Ale Ježíš řekl: Nechte jí. Proč ji rmoutíte? Dobrýť skutek učinila nade mnou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 7, 'Však chudé máte vždycky s sebou, a když budete chtíti, můžete jim dobře činiti, ale mne ne vždycky míti budete.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 8, 'Ona což mohla, to učinila; předešlať, aby těla mého pomazala ku pohřebu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 9, 'Amen pravím vám: Kdežkoli bude kázáno toto evangelium po všem světě, takéť i to, což učinila tato, bude vypravováno na památku její.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 10, 'Tedy Jidáš Iškariotský, jeden ze dvanácti, odšel k předním kněžím {biskupům}, aby jim ho zradil.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 11, 'Oni pak uslyševše, zradovali se, a slíbili mu peníze dáti. I hledal, kterak by ho příhodně zradil.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 12, 'Prvního pak dne přesnic, když velikonoční beránek zabíjín býval, řkou jemu učedlníci jeho: Kde chceš, ať jdouce, připravíme, abys jedl beránka?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 13, 'I poslal dva z učedlníků svých, a řekl jim: Jděte do města, a potkáť vás člověk dčbán vody nesa. Jdětež za ním.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 14, 'A kamžkoli vejde, rcete hospodáři: Mistrť praví: Kde jest večeřadlo, v němž bych jedl beránka s učedlníky svými?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 15, 'A on vám ukáže večeřadlo veliké, podlážené a připravené. Tu nám připravte.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 16, 'I odešli učedlníci jeho, a přišli do města, a nalezli tak, jakož jim byl pověděl. I připravili beránka.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 17, 'Když pak byl večer, přišel se dvanácti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 18, 'A když seděli za stolem a jedli, řekl Ježíš: Amen pravím vám, že jeden z vás mne zradí, kterýž jí se mnou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 19, 'A oni se počali rmoutiti, a praviti jemu jeden každý obzvláštně: Zdali já jsem? A jiný: Zdali já?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 20, 'On pak odpověděv, řekl jim: Jeden ze dvanácti, kterýž omáčívá se mnou v mise.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 21, 'Syn zajisté člověka jde, jakož psáno o něm, ale běda člověku tomu, skrze něhož Syn člověka bude zrazen. Dobré by bylo jemu, aby se byl nenarodil člověk ten.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 22, 'A když oni jedli, vzav Ježíš chléb, a dobrořečiv, lámal a dával jim, řka: Vezměte, jezte, to jest tělo mé.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 23, 'A vzav kalich, a díky učiniv, dal jim. A pili z něho všickni.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 24, 'I řekl jim: To jest krev má smlouvy té nové, kteráž se za mnohé vylévá.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 25, 'Amen pravím vám, žeť již více nikoli nebudu píti z plodu vinného kořene, až do onoho dne, když jej píti budu nový v království Božím.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 26, 'A sezpívavše písničku, vyšli na horu Olivetskou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 27, 'Potom řekl jim Ježíš: Všickni vy zhoršíte se nade mnou této noci. Nebo psáno jest: Bíti budu pastýře, a rozprchnou se ovce.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 28, 'Ale když z mrtvých vstanu, předejduť vás do Galilee.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 29, 'Tedy Petr řekl jemu: Byť se pak všickni zhoršili, ale já nic.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 30, 'I řekl jemu Ježíš: Amen pravím tobě, že dnes této noci, prvé než kohout po dvakrát zazpívá, třikrát mne zapříš.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 31, 'On pak mnohem více mluvil: Bychť pak měl s tebou i umříti, nikoliť nezapřím tebe. A takž také i všickni mluvili.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 32, 'I přišli na místo, kterémuž jméno Getsemany. Tedy řekl učedlníkům svým: Seďtež tuto, až se pomodlím.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 33, 'A pojav s sebou Petra a Jakuba a Jana, počal se lekati a velmi teskliv býti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 34, 'I dí jim: Smutnáť jest duše má až k smrti. Počekejtež tuto a bděte.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 35, 'A poodšed maličko, padl na zemi a modlil se, aby, bylo-li by možné, odešla od něho hodina ta.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 36, 'I řekl: Abba, Otče, všecko jest možné tobě. Přenes kalich tento ode mne, ale však ne, což já chci, ale co ty.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 37, 'I přišel a nalezl je, ani spí. I řekl Petrovi: Šimone, spíš? Nemohl-lis jediné hodiny bdíti?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 38, 'Bděte a modlte se, abyste nevešli v pokušení. Duchť zajisté hotov jest, ale tělo nemocno.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 39, 'A opět odšed, modlil se, táž slova mluvě.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 40, 'A navrátiv se, nalezl je, ani opět spí, (nebo oči jejich byly obtíženy;) aniž věděli, co by jemu odpověděli.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 41, 'I přišel po třetí, a řekl jim: Spětež již a odpočívejte; dostiť jest. Přišlať ta hodina; aj, Syna člověka zrazují v ruce hříšných.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 42, 'Vstaňte, poďme. Aj, kterýž mne zrazuje, blízkoť jest.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 43, 'A hned, když on ještě mluvil, přišel Jidáš, kterýž byl jeden ze dvanácti, a s ním zástup veliký s meči a s kyjmi, od předních kněží {biskupů} a od zákonníků a starších.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 44, 'Zrádce pak jeho byl jim dal znamení, řka: Kteréhožkoli políbím, tenť jest; jmětež ho, a veďte opatrně.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 45, 'A přišed, hned přistoupiv k němu, řekl: Mistře, Mistře, a políbil ho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 46, 'Tedy oni vztáhli naň ruce své, a jali jej.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 47, 'Jeden pak z těch, kteříž tu okolo stáli, vytrh meč, udeřil služebníka nejvyššího kněze {biskupova}, a uťal jemu ucho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 48, 'I odpověděv Ježíš, řekl jim: Jako na lotra vyšli jste s meči a s kyjmi, abyste mne jali?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 49, 'Na každý den býval jsem u vás, uče v chrámě, a nejali jste mne. Ale aby se naplnila písma.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 50, 'Tedy opustivše jej, všickni utekli.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 51, 'Jeden pak mládenček šel za ním, odín jsa rouchem lněným po nahém těle. I popadli jej mládenci.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 52, 'On pak opustiv roucho, nahý utekl od nich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 53, 'I přivedli Ježíše k nejvyššímu knězi {biskupovi}, a sešli se k němu všickni přední kněží {biskupové} i starší i zákonníci.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 54, 'Petr pak šel za ním zdaleka až na dvůr nejvyššího kněze {biskupův}; i seděl s služebníky, zhřívaje se u ohně.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 55, 'Ale přední kněží {biskupové} i všecka ta rada hledali proti Ježíšovi svědectví, aby jej na smrt vydali, a však nenalezli.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 56, 'Nebo ač mnozí křivé svědectví vydávali proti němu, však svědectví jejich nebyla jednostejná.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 57, 'Tedy někteří povstavše, křivé svědectví dávali proti němu, řkouce:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 58, 'My jsme slyšeli tohoto, že řekl: Já zbořím chrám tento rukou udělaný, a ve třech dnech jiný ne rukou udělaný postavím.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 59, 'Ale ani to jejich svědectví nebylo jednostejné.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 60, 'Tedy povstav nejvyšší kněz {biskup} u prostřed, otázal se Ježíše, řka: Neodpovídáš ničeho, což tito na tebe svědčí?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 61, 'Ale on mlčel, a nic neodpověděl. Opět nejvyšší kněz {biskup} otázal se ho a řekl jemu: Jsi-liž ty Kristus, ten Syn toho Požehnaného?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 62, 'A Ježíš řekl: Jáť jsem, a uzříte Syna člověka, an sedí na pravici moci Boží, a přichází s oblaky nebeskými.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 63, 'Tedy nejvyšší kněz {biskup} roztrh roucha svá, řekl: I což ještě potřebujeme svědků?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 64, 'Slyšeli jste rouhání. Co se vám zdá? Oni pak všickni potupili jej, že jest hoden smrti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 65, 'I počali někteří naň plvati, a tvář jeho zakrývati, a jej poličkovati, a říkati jemu: Prorokuj. A služebníci kyji jej bili.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 66, 'A když byl Petr v síni dole, přišla jedna z děvek nejvyššího kněze {biskupových}.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 67, 'A uzřevši Petra, an se ohřívá, a popatřivši naň, dí: I ty s Ježíšem Nazaretským byl jsi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 68, 'Ale on zapřel, řka: Aniž vím, ani rozumím, co ty pravíš. I vyšel ven před síň, a kohout zazpíval.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 69, 'Tedy děvka, uzřevši jej opět, počala praviti těm, kteříž tu okolo stáli, že tento z nich jest.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 70, 'A on opět zapřel. A po malé chvíli opět ti, kteříž tu stáli, řekli Petrovi: Jistě z nich jsi, nebo i Galilejský jsi, i řeč tvá podobná jest.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 71, 'On pak počal se proklínati a přisahati: Neznám člověka toho, o němž pravíte.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 72, 'A hned po druhé kohout zazpíval. I rozpomenul se Petr na slovo, kteréž byl řekl jemu Ježíš: Že prvé než kohout dvakrát zazpívá, třikrát mne zapříš. A vyšed, plakal.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 1, 'A hned ráno, uradivše se přední kněží {biskupové} s staršími a s zákonníky i se vším shromážděním, svázavše Ježíše, vedli jej a dali Pilátovi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 2, 'I otázal se ho Pilát: Ty-li jsi ten král Židovský? A on odpověděv, řekl jemu: Ty pravíš.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 3, 'I žalovali na něj přední kněží {biskupové} mnoho. On pak nic neodpovídal.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 4, 'Tedy Pilát otázal se ho opět, řka: Nic neodpovídáš? Hle, jak mnoho proti tobě svědčí.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 5, 'Ale Ježíš předce nic neodpověděl, tak že se podivil Pilát.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 6, 'V svátek pak propouštíval jim jednoho z vězňů, za kteréhož by koli prosili.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 7, 'I byl jeden, kterýž sloul Barabáš, s svárlivými v vězení, kteříž v svadě vraždu byli spáchali.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 8, 'A zvolav zástup, počal prositi, aby učinil, jakož jim vždycky činíval.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 9, 'Pilát pak odpověděl jim, řka: Chcete-li, propustím vám krále Židovského?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 10, '(Nebo věděl, že jej z závisti vydali přední kněží {biskupové}.)');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 11, 'Ale přední kněží {biskupové} ponukli zástupu, aby jim raději propustil Barabáše.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 12, 'A Pilát odpověděv, řekl jim zase: Což pak chcete, ať učiním tomu, kteréhož králem Židovským nazýváte?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 13, 'A oni opět zvolali: Ukřižuj ho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 14, 'A Pilát pravil jim: I co zlého učinil? Oni pak více volali: Ukřižuj ho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 15, 'Tedy Pilát, chtě lidu dosti učiniti, pustil jim Barabáše, a dal jim Ježíše ubičovaného, aby byl ukřižován.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 16, 'Žoldnéři pak uvedli jej vnitř do síně, do rathouzu, a svolali všecku zběř.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 17, 'I oblékli jej v šarlat, a korunu zpletše z trní, vložili naň.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 18, 'I počali ho pozdravovati: Zdráv buď, králi Židovský.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 19, 'A bili hlavu jeho třtinou, a plili na něj, a sklánějíce kolena, klaněli se jemu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 20, 'A když se jemu naposmívali, svlékli s něho šarlat, a oblékli jej v roucho jeho vlastní. I vedli jej, aby ho ukřižovali.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 21, 'I přinutili nějakého Šimona Cyrenenského, pomíjejícího, (kterýž šel z pole, otce Alexandrova a Rufova,) aby nesl kříž jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 22, 'I vedli jej až na místo Golgota, to jest, (vyložil-li by,) popravné místo.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 23, 'I dávali mu píti víno s mirrou, ale on nepřijal.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 24, 'A ukřižovavše jej, rozdělili roucha jeho, mecíce o ně los, kdo by co vzíti měl.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 25, 'A byla hodina třetí, když ho ukřižovali.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 26, 'A byl nápis viny jeho napsán: Král Židovský.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 27, 'Ukřižovali také s ním dva lotry, jednoho na pravici, a druhého na levici jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 28, 'I naplněno jest písmo, řkoucí: A s nepravými počten jest.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 29, 'A kteříž chodili mimo něj, rouhali se jemu, potřásajíce hlavami svými, a říkajíce: Hahá, kterýž rušíš chrám, a ve třech dnech vzděláváš,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 30, 'Spomoz sobě samému, a sstup s kříže.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 31, 'Též i přední kněží {biskupové} posmívajíce se, jeden k druhému s zákonníky pravili: Jinýmť pomáhal, sám sobě pomoci nemůže.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 32, 'Kristus, ten král Izraelský, nechažť nyní sstoupí s kříže, ať uzříme, a uvěříme. A i ti, kteříž s ním ukřižování byli, útržku mu činili.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 33, 'A když byla hodina šestá, stala se tma po vší zemi až do hodiny deváté.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 34, 'A v hodinu devátou zvolal Ježíš hlasem velikým, řka: Elói, Elói, lama zabachtani? Což se vykládá: Bože můj, Bože můj, pročs mne opustil?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 35, 'A někteří z okolo stojících, slyševše to, pravili: Hle, Eliáše volá.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 36, 'A běžev jeden, naplnil hubu octem, a vloživ na tresť, dával jemu píti, řka: Ponechte, uzříme, přijde-li Eliáš, aby jej složil.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 37, 'Ježíš pak zvolav hlasem velikým, pustil duši.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 38, 'A opona v chrámě roztrhla se na dvé, od vrchu až dolů.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 39, 'Viděv pak centurio, kterýž tu naproti stál, že tak volaje, vypustil duši, řekl: Jistě člověk tento Syn Boží byl.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 40, 'Byly pak tu i ženy, zdaleka se dívajíce, mezi nimiž byla Maria Magdaléna, a Maria Jakuba menšího, a Jozesova mátě, a Salome,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 41, 'Kteréž, když ještě byl v Galilei, chodily za ním a posluhovaly jemu, i jiné mnohé, kteréž byly s ním vstoupily do Jeruzaléma.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 42, 'A když již byl večer, (že byl den připravování, to jest před sobotou,)');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 43, 'Přišed Jozef z Arimatie, počestná osoba úřadná, kterýž také očekával království Božího, směle všel ku Pilátovi, a prosil za tělo Ježíšovo.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 44, 'Pilát pak podivil se, již-li by umřel. A povolav centuriona, otázal se ho, dávno-li je umřel.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 45, 'A zvěděv od centuriona, dal tělo Jozefovi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 46, 'I koupiv plátna, a sňav ho, obvinul v plátno, a položil do hrobu, kterýž byl vytesán z skály, a přivalil kámen ke dveřům hrobovým.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 47, 'Ale Maria Magdaléna a Maria Jozesova dívaly se, kde by byl položen.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 1, 'A když pominula sobota, Maria Magdaléna a Maria Jakubova a Salome nakoupily vonných věcí, aby přijdouce, pomazaly Ježíše.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 2, 'Protož velmi ráno v první den po sobotě přišly k hrobu, an již slunce vzešlo.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 3, 'I pravily vespolek: Kdo nám odvalí kámen ode dveří hrobových?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 4, '(A vzhlédše, uzřely odvalený kámen.) Byl zajisté veliký velmi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 5, 'A všedše do hrobu, uzřely mládence, an sedí na pravici, oděného rouchem bílým. I ulekly se.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 6, 'On pak řekl jim: Nebojte se. Ježíše hledáte Nazaretského, toho ukřižovaného. Vstalť jest, neníť ho tuto; aj, místo, kdež jej byli položili.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 7, 'Ale jděte, povězte učedlníkům jeho i Petrovi, žeť vás předejde do Galilee. Tam jej uzříte, jakž pověděl vám.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 8, 'A vyšedše rychle, utekly od hrobu; nebo přišel na ně strach a hrůza. A aniž komu co řekly, nebo se bály.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 9, 'Vstav pak Ježíš z mrtvých ráno v neděli, ukázal se nejprv Marii Magdaléně, z níž byl vyvrhl sedm ďáblů.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 10, 'Ona pak šedši, zvěstovala těm, kteříž s ním bývali, lkajícím a plačícím.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 11, 'A oni slyšavše, že by živ byl, a vidín od ní, nevěřili.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 12, 'Potom pak dvěma z nich jdoucím ukázal se v jiné způsobě, když šli přes pole.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 13, 'A ti šedše, pověděli jiným. Ani těm nevěřili.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 14, 'Potom sedícím spolu jedenácti ukázal se, a trestal nedověru jejich a tvrdost srdce, že těm, kteříž jej viděli vzkříšeného, nevěřili.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 15, 'A řekl jim: Jdouce po všem světě, kažte evangelium všemu stvoření.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 16, 'Kdož uvěří a pokřtí se, spasen bude; kdož pak neuvěří, budeť zatracen.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 17, 'Znamení pak ti, kteříž uvěří, tato míti budou: Ve jménu mém ďábly budou vymítati, jazyky novými mluviti,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 18, 'Hady bráti, a jestliže by co jedovatého pili, nikoliť jim neuškodí; na nemocné ruce vzkládati budou, a dobře se míti budou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 19, 'Když pak jim odmluvil Pán, zhůru vzat jest do nebe, a sedí na pravici Boží.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 20, 'A oni vyšedše, kázali všudy, a Pán jim pomáhal, a slov jejich potvrzoval činěním divů.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 1, 'Poněvadž mnozí usilovali sepsati pořádně vypravování těch věcí, kteréž u nás jisté jsou,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 2, 'Jakž nám vydali ti, kteříž od počátku sami viděli, a služebníci toho Slova byli:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 3, 'Vidělo se i mně, kterýž jsem toho všeho pravé povědomosti z gruntu bedlivě došel, tobě o tom pořádně vypsati, výborný Teofile,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 4, 'Abys zvěděl jistotu těch věcí, jimž jsi vyučován.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 5, 'Byl za dnů Heródesa krále Judského kněz nějaký, jménem Zachariáš, z třídy Abiášovy, a manželka jeho ze dcer Aronových, a jméno její Alžběta.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 6, 'Byli pak oba spravedliví před oblíčejem Božím, chodíce ve všech přikázaních a spravedlnostech Páně bez ouhony.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 7, 'A neměli plodu, proto že Alžběta byla neplodná, a oba se byli zstarali ve dnech svých.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 8, 'I stalo se, když on úřad kněžský konal v pořádku třídy své před Bohem,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 9, 'Že vedlé obyčeje úřadu kněžského los naň přišel, aby položil zápal, vejda do chrámu Páně.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 10, 'A všecko množství lidu bylo vně, modlíce se v hodinu zápalu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 11, 'Tedy ukázal se jemu anděl Páně, stoje na pravé straně oltáře zápalu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 12, 'A uzřev jej Zachariáš, zstrašil se, a bázeň připadla na něj.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 13, 'I řekl jemu anděl: Neboj se, Zachariáši, neboť jest uslyšána modlitba tvá, a Alžběta manželka tvá porodí tobě syna, a nazůveš jméno jeho Jan.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 14, 'Z čehož budeš míti radost a veselé, a mnozí se z jeho narození budou radovati.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 15, 'Bude zajisté veliký před oblíčejem Páně, a vína i nápoje opojného nebude píti, a Duchem svatým bude naplněn hned od života matky své.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 16, 'A mnohé z synů Izraelských obrátí ku Pánu Bohu jejich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 17, 'Neboť on předejde před oblíčejem jeho v duchu a v moci Eliášově, aby obrátil srdce otců k synům, a nevěřící k opatrnosti spravedlivých, aby postavil Pánu lid hotový.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 18, 'I řekl Zachariáš andělu: Po čemž to poznám? Nebo já starý jsem, a manželka má zstarala se ve dnech svých.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 19, 'I odpověděv anděl, řekl jemu: Jáť jsem Gabriel, kterýž stojím před oblíčejem Božím, a poslán jsem, abych mluvil s tebou, a tyto věci veselé tobě zvěstoval.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 20, 'A aj, budeš němý, a nebudeš moci mluviti až do dne, v kterémž se tyto věci stanou, proto že jsi neuvěřil řečem mým, kteréž se naplní časem svým.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 21, 'Lid pak očekával Zachariáše, a divili se, že on tak prodléval v chrámě.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 22, 'Vyšed pak, nemohl mluviti k nim. I srozuměli, že vidění viděl v chrámě. Nebo on návěští jim dával, a zůstal němý.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 23, 'I stalo se, když se vyplnili dnové konání úřadu jeho, odšel do domu svého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 24, 'A po těch dnech počala Alžběta manželka jeho, a tajila se za pět měsíců, řkuci:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 25, 'Že tak mi učinil Pán ve dnech, v nichž vzezřel, aby odjal mé pohanění mezi lidmi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 26, 'V měsíci pak šestém poslán jest anděl Gabriel od Boha do města Galilejského, kterémuž jméno Nazarét,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 27, 'Ku panně zasnoubené muži, kterémuž jméno bylo Jozef, z domu Davidova, a jméno panny Maria.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 28, 'I všed k ní anděl, dí: Zdráva buď milostí obdařená, Pán s tebou, požehnaná ty mezi ženami.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 29, 'Ona pak uzřevši ho, zarmoutila se nad řečí jeho, a myslila, jaké by to bylo pozdravení.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 30, 'I řekl jí anděl: Neboj se, Maria, nebo jsi nalezla milost u Boha.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 31, 'A počneš v životě, a porodíš syna, a nazůveš jméno jeho Ježíš.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 32, 'Tenť bude veliký, a Syn Nejvyššího slouti bude, a dáť jemu Pán Bůh stolici Davida otce jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 33, 'A kralovati bude v domě Jákobově na věky, a království jeho nebude konce.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 34, 'I řekla Maria andělu: Kterak se to stane, poněvadž já muže nepoznávám?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 35, 'A odpověděv anděl, řekl jí: Duch svatý sstoupí v tě, a moc Nejvyššího zastíní tobě; a protož i to, což se z tebe svatého narodí, slouti bude Syn Boží.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 36, 'A aj, Alžběta, přítelkyně tvá, i ona počala syna v starosti své, a tento jest jí šestý měsíc, kteráž sloula neplodná.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 37, 'Neboť nebude nemožné u Boha žádné slovo.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 38, 'I řekla Maria: Aj, děvka Páně, staniž mi se podlé slova tvého. I odšel od ní anděl.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 39, 'Tedy povstavši Maria v těch dnech, odešla na hory s chvátáním do města Judova.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 40, 'I vešla do domu Zachariášova, a pozdravila Alžběty.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 41, 'I stalo se, jakž uslyšela Alžběta pozdravení Marie, zplésalo nemluvňátko v životě jejím, a naplněna jest Duchem svatým Alžběta.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 42, 'I zvolala hlasem velikým a řekla: Požehnaná ty mezi ženami, a požehnaný plod života tvého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 43, 'A odkud mi to, aby přišla matka Pána mého ke mně?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 44, 'Nebo aj, jakž se stal hlas pozdravení tvého v uších mých, zplésalo radostně nemluvňátko v životě mém.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 45, 'A blahoslavená, kteráž uvěřila, neboť dokonány budou ty věci, kteréž jsou povědíny jí ode Pána.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 46, 'Tedy řekla Maria: Velebí duše má Hospodina,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 47, 'A veselí se duch můj v Bohu, spasiteli svém,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 48, 'Že vzezřel na ponížení děvky své; neb aj, od této chvíle blahoslaviti mne budou všickni národové.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 49, 'Neboť mi učinil veliké věci ten, kterýž mocný jest, a svaté jméno jeho,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 50, 'A jehož milosrdenství od pokolení až do pokolení bojícím se jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 51, 'Dokázal moci ramenem svým, rozptýlil pyšné myšlením srdce jejich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 52, 'Sházel mocné s stolic, a povýšil ponížených.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 53, 'Lačné nakrmil dobrými věcmi, a bohaté pustil prázdné.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 54, 'Přijal Izraele, služebníka svého, byv pamětliv na milosrdenství,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 55, 'Jakož mluvil otcům našim, Abrahamovi a semeni jeho na věky.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 56, 'I zůstala Maria s ní asi za tři měsíce, a navrátila se do domu svého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 57, 'Alžbětě pak naplnil se čas, aby porodila, i porodila syna.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 58, 'A uslyšeli sousedé a přátelé její, že Hospodin veliké učinil s ní milosrdenství své, i radovali se spolu s ní.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 59, 'Stalo se pak v den osmý, přišli obřezovati dítěte, a nazývali jej jménem otce jeho Zachariášem.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 60, 'Ale odpověděvši matka jeho, řekla: Nikoli, ale slouti bude Jan.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 61, 'I řekli jí: Však žádného není v rodu tvém, kterýž by sloul jménem tím.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 62, 'I dávali návěští otci jeho, jak by ho chtěl nazývati.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 63, 'A on požádav deštičky, napsal, řka: Jan jest jméno jeho. I divili se všickni.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 64, 'A hned otevřela se ústa jeho a jazyk jeho, i mluvil, velebě Boha.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 65, 'Tedy přišla bázeň na všecky sousedy jejich, a po všech horách Judských rozhlásána jsou všecka ta slova.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 66, 'A všickni, kteříž o tom slyšeli, skládali to v srdci svém, řkouce: I jaké dítě toto bude? A ruka Páně byla s ním.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 67, 'Zachariáš pak otec jeho naplněn jest Duchem svatým, a prorokoval, řka:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 68, 'Požehnaný Pán Bůh Izraelský, že navštívil a učinil vykoupení lidu svému.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 69, 'A vyzdvihl nám roh spasení v domě Davida, služebníka svého,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 70, 'Jakož mluvil skrze ústa proroků svých svatých, kteříž byli od věků,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 71, 'O vysvobození z nepřátel našich, a z ruky všech, kteříž nás nenáviděli,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 72, 'Aby učinil milosrdenství s otci našimi, a rozpomenul se na smlouvu svou svatou,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 73, 'Na přísahu, kterouž přisáhl Abrahamovi, otci našemu, žeť nám to dá,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 74, 'Abychom bez strachu, z ruky nepřátel svých jsouce vysvobozeni, sloužili jemu,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 75, 'V svatosti a v spravedlnosti před oblíčejem jeho, po všecky dny života svého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 76, 'Ty pak, dítě, prorokem Nejvyššího slouti budeš, nebo předejdeš před tváří Páně připravovati cesty jeho,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 77, 'Aby dáno bylo umění spasitelné lidu jeho na odpuštění hříchů jejich,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 78, 'Skrze střeva milosrdenství Boha našeho, v nichž navštívil nás, vyšed z výsosti,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 79, 'Aby se ukázal sedícím v temnostech a v stínu smrti, k spravení noh našich na cestu pokoje.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 80, 'Dítě pak rostlo, a posilovalo se v duchu, a bylo na poušti až do dne zjevení svého lidu Izraelskému.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 1, 'I stalo se v těch dnech, vyšlo poručení od císaře Augusta, aby byl popsán všecken svět.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 2, '(To popsání nejprvé stalo se, když vládařem Syrským byl Cyrenius.)');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 3, 'I šli všickni, aby zapsáni byli, jeden každý do svého města.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 4, 'Vstoupil pak i Jozef od Galilee z města Nazarétu do Judstva, do města Davidova, kteréž slove Betlém, (proto že byl z domu a z čeledi Davidovy,)');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 5, 'Aby zapsán byl s Marií, zasnoubenou sobě manželkou těhotnou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 6, 'I stalo se, když tam byli, naplnili se dnové, aby porodila.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 7, 'I porodila Syna svého prvorozeného, a plénkami ho obvinula, a položila jej v jeslech, proto že neměli místa v hospodě.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 8, 'A pastýři byli v krajině té, ponocujíce, a stráž noční držíce nad svým stádem.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 9, 'A aj, anděl Páně postavil se podlé nich, a sláva Páně osvítila je. I báli se bázní velikou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 10, 'Tedy řekl jim anděl: Nebojtež se; nebo aj, zvěstuji vám radost velikou, kteráž bude všemu lidu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 11, 'Nebo narodil se vám dnes spasitel, kterýž jest Kristus Pán, v městě Davidově.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 12, 'A toto vám bude za znamení: Naleznete nemluvňátko plénkami obvinuté, ležící v jeslech.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 13, 'A hned s andělem zjevilo se množství rytířstva nebeského, chválících Boha a řkoucích:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 14, 'Sláva na výsostech Bohu, a na zemi pokoj, lidem dobrá vůle.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 15, 'I stalo se, jakž odešli od nich andělé do nebe, že ti pastýři řekli vespolek: Poďme až do Betléma, a vizme tu věc, kteráž se stala, o níž Pán oznámil nám.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 16, 'I přišli, chvátajíce, a nalezli Marii a Jozefa, i to nemluvňátko ležící v jeslech.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 17, 'A viděvše, rozhlašovali, což jim povědíno bylo o tom děťátku.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 18, 'I divili se všickni, kteříž slyšeli o tom, což jim bylo mluveno od pastýřů.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 19, 'Ale Maria zachovávala všecky věci tyto, skládajici je v srdci svém.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 20, 'I navrátili se pastýři, velebíce a chválíce Boha ze všeho, což slyšeli a viděli, tak jakž bylo jim povědíno.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 21, 'A když se naplnilo dní osm, aby obřezáno bylo to děťátko, i nazváno jest jméno jeho Ježíš, kterýmž bylo nazváno od anděla, prvé než se v životě počalo.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 22, 'A když se naplnili dnové očišťování Marie podlé zákona Mojžíšova, přinesli jej do Jeruzaléma, aby ho postavili Pánu,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 23, '(Jakož psáno jest v zákoně Páně, že každý pacholík, otvíraje život, svatý Pánu slouti bude,)');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 24, 'A aby dali obět, jakož povědíno jest v zákoně Páně, dvě hrdličky aneb dvé holoubátek.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 25, 'A aj, byl člověk v Jeruzalémě, jemuž jméno Simeon. A člověk ten byl spravedlivý a nábožný, očekávající potěšení Izraelského, a Duch svatý byl v něm.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 26, 'A bylo jemu zjeveno od Ducha svatého, že neuzří smrti, až by prvé uzřel Krista Páně.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 27, 'Ten přišel, ponuknut byv od Ducha, do chrámu. A když uvodili rodičové Ježíše děťátko, aby učinili podlé obyčeje zákona při něm,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 28, 'Tedy on vzal jej na lokty své, i chválil Boha a řekl:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 29, 'Nyní propouštíš služebníka svého, Pane, podlé slova svého, v pokoji.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 30, 'Nebo viděly oči mé spasení tvé,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 31, 'Kteréž jsi připravil před oblíčejem všech lidí,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 32, 'Světlo k zjevení národům, a slávu lidu tvého Izraelského.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 33, 'Otec pak a matka jeho divili se těm věcem, kteréž praveny byly o něm.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 34, 'I požehnal jim Simeon, a řekl Marii, matce jeho: Aj, položen jest tento ku pádu a ku povstání mnohým v Izraeli, a na znamení, kterémuž bude odpíráno,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 35, '(A tvou vlastní duši pronikne meč,) aby zjevena byla z mnohých srdcí myšlení.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 36, 'Byla také Anna prorokyně, dcera Fanuelova z pokolení Asser. Ta se byla zstarala ve dnech mnohých, a živa byla s mužem sedm let od panenství svého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 37, 'A ta vdova byla, v letech okolo osmdesáti a čtyřech, kteráž nevycházela z chrámu, posty a modlitbami sloužeci Bohu dnem i nocí.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 38, 'A ta v touž hodinu přišedši, chválila Pána, a mluvila o něm všechněm, kteříž čekali vykoupení v Jeruzalémě.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 39, 'Vykonavše pak všecko podlé zákona Páně, vrátili se do Galilee, do města svého Nazaréta.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 40, 'Děťátko pak rostlo, a posilovalo se v duchu, plné moudrosti, a milost Boží byla v něm.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 41, 'I chodívali rodičové jeho každého roku do Jeruzaléma na den slavný velikonoční.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 42, 'A když byl ve dvanácti letech, a oni vstupovali do Jeruzaléma, podlé obyčeje toho dne svátečního,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 43, 'A když vykonali ty dni, a již se navracovali, zůstalo dítě Ježíš v Jeruzalémě, a nevěděli Jozef a matka jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 44, 'Domnívajíce se pak o něm, že by byl v zástupu, ušli den cesty. I hledali ho mezi příbuznými a mezi známými.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 45, 'A nenalezše jeho, navrátili se do Jeruzaléma, hledajíce ho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 46, 'I stalo se po třech dnech, že nalezli jej v chrámě, an sedí mezi doktory, poslouchaje jich, a otazuje se jich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 47, 'A děsili se všickni, kteříž jej slyšeli, nad rozumností a odpovědmi jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 48, 'A uzřevše ho, ulekli se. I řekla matka jeho k němu: Synu, proč jsi nám tak učinil? Aj, otec tvůj a já s bolestí hledali jsme tebe.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 49, 'I řekl jim: Co, že jste mne hledali? Zdaliž jste nevěděli, že v těch věcech, kteréž jsou Otce mého, musím já býti?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 50, 'Ale oni nesrozuměli těm slovům, kteráž jim mluvil.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 51, 'I šel s nimi, a přišel do Nazaréta, a byl poddán jim. Matka pak jeho zachovávala všecka slova ta v srdci svém.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 52, 'A Ježíš prospíval moudrostí, a věkem, a milostí, u Boha i u lidí.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 1, 'Léta pak patnáctého císařství Tiberia císaře, když Pontský Pilát spravoval Judstvo, a Heródes byl čtvrtákem v Galilei, Filip pak bratr jeho byl čtvrtákem Iturejské a Trachonitidské krajiny, a Lyzaniáš čtvrtákem Abilinským,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 2, 'Za nejvyššího kněze {biskupa} Annáše a Kaifáše, stalo se slovo Páně k Janovi synu Zachariášovu na poušti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 3, 'I chodil po vší okolní krajině Jordánské, káže křest pokání na odpuštění hříchů,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 4, 'Jakož psáno jest v knize proroctví Izaiáše proroka, řkoucího: Hlas volajícího na poušti: Připravujte cestu Páně, přímé čiňte stezky jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 5, 'Každé údolí bude vyplněno, a každá hora a pahrbek bude ponížen; i budou křivé věci spraveny, a ostré cesty budou hladké.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 6, 'A uzříť všeliké tělo spasení Boží.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 7, 'Pravil pak zástupům vycházejícím, aby se křtili od něho: Plemeno ještěrčí, kdo vám ukázal, kterak byste utekli budoucího hněvu?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 8, 'Protož neste ovoce hodné pokání, a neříkejtež u sebe: Otce máme Abrahama. Neboť pravím vám, že jest mocen Bůh z kamení tohoto vzbuditi syny Abrahamovi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 9, 'A jižť jest i sekera k kořenu stromů přiložena. Protož každý strom, kterýž nenese ovoce dobrého, vyťat a na oheň uvržen bývá.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 10, 'I tázali se ho zástupové, řkouce: Což tedy činiti budeme?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 11, 'A odpovídaje, pravil jim: Kdo má dvě sukně, dej nemajícímu, a kdo má pokrmy, tolikéž učiň.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 12, 'Přišli pak i celní křtíti se, i řekli jemu: Mistře, co budeme činiti?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 13, 'A on řekl jim: Nic více nevybírejte mimo to, což jest ustaveno.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 14, 'I tázali se ho také i žoldnéři, řkouce: A my což činiti budeme? I řekl jim: Nad žádným se nepotřásejte, aniž podvodně čiňte, a dosti mějte na svých žoldích.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 15, 'A když pak lid očekával, a myslili všickni v srdcích svých o Janovi, nebyl-li by snad on Kristus,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 16, 'Odpověděl Jan všechněm, řka: Jáť zajisté křtím vás vodou, ale jdeť silnější nežli já, kterémuž nejsem hoden rozvázati řeménka u obuvi jeho. Tenť vás křtíti bude Duchem svatým a ohněm.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 17, 'Jehožto věječka v ruce jeho, a vyčistíť humno své, a shromáždí pšenici do obilnice své, ale plevy páliti bude ohněm neuhasitelným.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 18, 'A tak mnohé i jiné věci, napomínaje, zvěstoval lidu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 19, 'Heródes pak čtvrták, když od něho byl trestán pro Herodiadu manželku Filipa bratra svého, i ze všech nešlechetností, kteréž činil Heródes,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 20, 'Přidal i toto nade všecko, že vsadil Jana do žaláře.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 21, 'I stalo se, když se křtil všecken lid, a když se pokřtil i Ježíš, a modlil se, že otevřelo se nebe.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 22, 'A sstoupil Duch svatý v tělesné způsobě jako holubice na něj, a stal se hlas s nebe, řkoucí: Ty jsi ten Syn můj milý, v toběť mi se zalíbilo.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 23, 'Ježíš pak počínal býti jako ve třidcíti letech, jakž domnín byl, syn Jozefův, kterýž byl syn Heli,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 24, 'Kterýž byl Matatův, kterýž byl Léví, kterýž byl Melchův, kterýž byl Jannův, kterýž byl Jozefův,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 25, 'Kterýž byl Matatiášův, kterýž byl Amosův, kterýž byl Naum, kterýž byl Esli, kterýž byl Nagge,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 26, 'Kterýž byl Mahatův, kterýž byl Matatiášův, kterýž byl Semei, kterýž byl Jozefův, kterýž byl Judův,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 27, 'Kterýž byl Johannův, kterýž byl Resův, kterýž byl Zorobábelův, kterýž byl Salatielův, kterýž byl Neriův,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 28, 'Kterýž byl Melchiův, kterýž byl Addiův, kterýž byl Kozamův, kterýž byl Elmódamův, kterýž byl Erův,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 29, 'Kterýž byl Józův, kterýž byl Eliezerův, kterýž byl Jórimův, kterýž byl Matatův, kterýž byl Léví,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 30, 'Kterýž byl Simeonův, kterýž byl Judův, kterýž byl Jozefův, kterýž byl Jónamův, kterýž byl Eliachimův,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 31, 'Kterýž byl Meleův, kterýž byl Ménamův, kterýž byl Matatanův, kterýž byl Nátanův, kterýž byl Davidův,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 32, 'Kterýž byl Jesse, kterýž byl Obédův, kterýž byl Bózův, kterýž byl Salmonův, kterýž byl Názonův,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 33, 'Kterýž byl Aminadabův, kterýž byl Aramův, kterýž byl Ezromův, kterýž byl Fáresův, kterýž byl Judův, kterýž byl Jákobův,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 34, 'Kterýž byl Izákův, kterýž byl Abrahamův, kterýž byl Táre, kterýž byl Náchorův,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 35, 'Kterýž byl Sáruchův, kterýž byl Ragaův, kterýž byl Fálekův, kterýž byl Heberův, kterýž byl Sále,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 36, 'Kterýž byl Kainanův, kterýž byl Arfaxadův, kterýž byl Semův, kterýž byl Noé, kterýž byl Lámechův,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 37, 'Kterýž byl Matuzalémův, kterýž byl Enochův, kterýž byl Járedův, kterýž byl Malalehelův, kterýž byl Kainanův.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 38, 'Kterýž byl Enosův, kterýž byl Setův, kterýž byl Adamův, kterýž byl Boží.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 1, 'Ježíš pak, pln byv Ducha svatého, vrátil se od Jordánu, a puzen jest v Duchu na poušť.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 2, 'A za čtyřidceti dní pokoušín byl od ďábla, a nic nejedl v těch dnech. Ale když se skonali, potom zlačněl.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 3, 'I řekl jemu ďábel: Jestliže jsi Syn Boží, rci kamenu tomuto, ať jest chléb.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 4, 'I odpověděl jemu Ježíš, řka: Psánoť jest: Že ne samým chlebem živ bude člověk, ale každým slovem Božím.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 5, 'I vedl jej ďábel na horu vysokou, a ukázal mu všecka království okršlku země pojednou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 6, 'A řekl jemu ďábel: Toběť dám tuto všecku moc i slávu; nebo mně dána jest, a komuž bych koli chtěl, dám ji.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 7, 'Protož ty pokloníš-li se přede mnou, budeť všecko tvé.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 8, 'I odpověděv Ježíš, řekl jemu: Jdi pryč ode mne, satanáši; nebo psáno jest: Pánu Bohu svému budeš se klaněti, a jemu samému sloužiti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 9, 'Tedy vedl jej do Jeruzaléma, a postavil ho na vrchu chrámu, a řekl mu: Jsi-li Syn Boží, pusť se odtud dolů.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 10, 'Nebo psáno jest: Že andělům svým přikáže o tobě, aby tě ostříhali,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 11, 'A že tě na ruce uchopí, abys neurazil o kámen nohy své.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 12, 'A odpovídaje, dí mu Ježíš: Povědínoť jest: Nebudeš pokoušeti Pána Boha svého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 13, 'A dokonav všecka pokušení ďábel, odšel od něho až do času.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 14, 'I navrátil se Ježíš v moci Ducha do Galilee, a vyšla pověst o něm po vší té okolní krajině.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 15, 'A on učil v školách jejich, a slaven byl ode všech.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 16, 'I přišel do Nazaréta, kdež byl vychován, a všel podlé obyčeje svého v den sobotní do školy. I vstal, aby četl.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 17, 'I dána jemu kniha Izaiáše proroka. A otevřev knihu, nalezl místo, kdež bylo napsáno:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 18, 'Duch Páně nade mnou, proto že pomazal mne, kázati evangelium chudým poslal mne, a uzdravovati skroušené srdcem, zvěstovati jatým propuštění a slepým vidění, a propustiti ssoužené v svobodu,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 19, 'A zvěstovati léto Páně vzácné.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 20, 'A zavřev knihu, a vrátiv služebníku, posadil se. A všech v škole oči byly obráceny naň.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 21, 'I počal mluviti k nim: Že dnes naplnilo se písmo toto v uších vašich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 22, 'A všickni jemu posvědčovali, a divili se libým slovům, pocházejícím z úst jeho, a pravili: Zdaliž tento není syn Jozefův?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 23, 'I dí k nim: Zajisté díte mi toto podobenství: Lékaři, uzdrav se sám. Které věci slyšeli jsme, žes činil v Kafarnaum, učiň i zde v své vlasti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 24, 'I řekl jim: Amen pravím vám, žeť žádný prorok není vzácen v vlasti své.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 25, 'Ale v pravdě pravím vám, že mnoho vdov bylo za dnů Eliáše v lidu Izraelském, když zavříno bylo nebe za tři léta a za šest měsíců, a když byl hlad veliký po vší zemi,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 26, 'Však Eliáš k žádné z nich není poslán, než toliko do Sarepty Sidonské k ženě vdově.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 27, 'A mnoho malomocných bylo v lidu Izraelském za Elizea proroka, a však žádný z nich není očištěn, než Náman Syrský.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 28, 'I naplněni byli všickni v škole hněvem, slyšíce to.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 29, 'A povstavše, vyvedli jej ven z města, a vedli ho až na vrch hory, na níž město jejich bylo vzděláno, aby jej dolů sstrčili.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 30, 'Ale on bera se prostředkem jich, ušel.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 31, 'I sstoupil do Kafarnaum, města Galilejského, a učil je ve dny sobotní.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 32, 'I divili se velmi učení jeho, nebo mocná byla řeč jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 33, 'Byl pak v škole člověk, mající ducha ďábelství nečistého. I zvolal hlasem velikým,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 34, 'Řka: Ach, což jest tobě do nás, Ježíši Nazaretský? Přišel jsi zatratiti nás? Znám tě, kdo jsi, že ten Svatý Boží.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 35, 'I přimluvil jemu Ježíš, řka: Umlkniž a vyjdi od něho. A povrha jej ďábel mezi ně, vyšel od něho, a nic mu neuškodil.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 36, 'I přišel strach na všecky, a rozmlouvali vespolek, řkouce: Jaké jest toto slovo, že v moci a síle přikazuje nečistým duchům, a vycházejí?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 37, 'I rozcházela se o něm pověst po všelikém místě té okolní krajiny.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 38, 'Vstav pak ze školy, všel do domu Šimonova. Svegruše pak Šimonova trápena byla těžkou zimnicí. I prosili ho za ni.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 39, 'Tedy stoje nad ní, přimluvil zimnici, i přestala jí. A ona hned vstavši, posluhovala jim.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 40, 'Při západu pak slunce všickni, kteříž měli nemocné rozličnými neduhy, vodili je k němu, a on na jednoho každého z nich ruce vzkládav, uzdravoval je.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 41, 'Od mnohých také ďábelství vycházela, křičící a říkající: Ty jsi Kristus, Syn Boží. Ale přimlouvaje, nedopouštěl jim mluviti; nebo věděli, že jest on Kristus.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 42, 'A jakž byl den, vyšed, bral se na pusté místo. I hledali ho zástupové, a přišli až k němu, a zdržovali ho, aby neodcházel od nich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 43, 'On pak řekl jim: I jinýmť městům musím zvěstovati království Boží; nebo na to poslán jsem.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 44, 'I kázal v školách Galilejských.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 1, 'Stalo se pak, když se zástup na něj valil, aby slyšeli slovo Boží, že on stál podlé jezera Genezaretského.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 2, 'I uzřel dvě lodí, any stojí u jezera, rybáři pak sstoupivše z nich, vypírali sítí.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 3, 'I vstoupiv na jednu z těch lodí, kteráž byla Šimonova, prosil ho, aby od země odvezl maličko. A posadiv se, učil z lodí zástupy.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 4, 'A když přestal mluviti, dí k Šimonovi: Vez na hlubinu, a rozestřete síti své k lovení.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 5, 'I odpověděv Šimon, řekl jemu: Mistře, přes celou noc pracovavše, nic jsme nepopadli, ale k slovu tvému rozestru síť.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 6, 'A když to učinili, zahrnuli množství veliké ryb, tak že se trhala síť jejich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 7, 'I ponukli tovaryšů, kteříž byli na druhé lodí, aby přišli a pomohli jim. I přišli a naplnili obě lodí, tak že se pohřižovaly.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 8, 'To uzřev Šimon Petr, padl k nohám Ježíšovým, řka: Odejdi ode mne, Pane, neboť jsem člověk hříšný.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 9, 'Hrůza zajisté byla jej obklíčila, i všecky, kteříž s ním byli, nad tím lovením ryb, kteréž byli popadli,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 10, 'A též Jakuba a Jana, syny Zebedeovy, kteříž byli tovaryši Šimonovi. I dí Šimonovi Ježíš: Nebojž se. Již od tohoto času lidi budeš loviti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 11, 'A přivezše k břehu lodí, a všecko opustivše, šli za ním.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 12, 'I stalo se, když byl v jednom městě, a aj, muž plný malomocenství. A uzřev Ježíše, padl na tvář, a prosil ho, řka: Pane, kdybys chtěl, můžeš mne očistiti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 13, 'I vztáhl ruku, dotekl se ho, řka: Chci, buď čist. A hned odešlo od něho malomocenství.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 14, 'I přikázal jemu, aby žádnému nepravil, ale jdi, ukaž se knězi, a obětuj za očištění své, jakož přikázal Mojžíš, na svědectví jim.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 15, 'Tedy rozhlašovala se více řeč o něm, a scházeli se zástupové mnozí, aby jej slyšeli, a uzdravováni byli od něho v svých nemocech.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 16, 'On pak odcházel na pouště, a modlil se.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 17, 'I stalo se v jeden den, že on učil. A seděli také tu i farizeové a zákona učitelé, kteříž se byli sešli ze všech městeček Galilejských a Judských i z Jeruzaléma, a moc Páně přítomna byla k uzdravování jich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 18, 'A aj, muži nesli na loži člověka, kterýž byl šlakem poražený, i hledali vnésti ho a položiti před něj.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 19, 'A nenalezše, kterou by jej stranou vnesli pro zástup, vstoupili na dům, a skrze podlahu spustili jej s ložem u prostřed před Ježíše.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 20, 'Kterýžto viděv víru jejich, řekl mu: Člověče, odpuštěniť jsou tobě hříchové tvoji.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 21, 'Tedy počali přemyšlovati zákonníci a farizeové, řkouce: Kdo jest tento, kterýž mluví rouhání? Kdo může odpustiti hříchy, jediné sám Bůh?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 22, 'Poznav pak Ježíš myšlení jejich, odpovídaje, řekl jim: Co přemyšlujete v srdcích svých?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 23, 'Co jest snáze říci: Odpouštějí se tobě hříchové tvoji, čili říci: Vstaň a choď?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 24, 'Ale abyste věděli, že Syn člověka má moc na zemi odpouštěti hříchy, řekl šlakem poraženému: Toběť pravím: Vstaň, a vezma lože své, jdi do domu svého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 25, 'A hned vstav před nimi, vzal, na čemž ležel, i odšel do domu svého, velebě Boha.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 26, 'I užasli se všickni, a velebili Boha, a naplněni jsou bázní, řkouce: Viděli jsme dnes divné věci.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 27, 'A potom vyšel a uzřel celného, jménem Léví, sedícího na cle. I řekl jemu: Poď za mnou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 28, 'A opustiv všecko, vstav, šel za ním.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 29, 'I učinil jemu hody veliké Léví v domě svém, a byl zástup veliký publikánů i jiných, kteříž s ním stolili.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 30, 'Tedy reptali zákonníci a farizeové, řkouce učedlníkům jeho: Proč s publikány a hříšníky jíte a pijete?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 31, 'I odpověděv Ježíš, řekl jim: Nepotřebujíť zdraví lékaře, ale nemocní.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 32, 'Nepřišelť jsem volati spravedlivých, ale hříšných ku pokání.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 33, 'A oni řekli jemu: Proč učedlníci Janovi postí se často a modlí se, podobně i farizejští, tvoji pak jedí a pijí?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 34, 'On pak řekl jim: Zdali můžete synům ženicha, dokudž s nimi jest ženich, kázati se postiti?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 35, 'Přijdouť pak dnové, když odjat bude od nich ženich, tehdážť se budou postiti v těch dnech.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 36, 'Pravil pak jim i podobenství. Že žádný záplaty roucha nového nepřišívá k rouchu vetchému; sic jinak to nové roztrhuje, a vetchému nepřipadá záplata z nového.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 37, 'A žádný nevlévá vína nového do nádob starých; sic jinak víno nové rozpučí nádoby, a samo vyteče, a nádoby se pokazí.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 38, 'Ale víno nové v nádoby nové má lito býti, a obé bude zachováno.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 39, 'A aniž kdo, když pije staré, hned chce nového, ale díť: Staré lepší jest.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 1, 'I stalo se v druhou sobotu, že šel Ježíš skrze obilí. I trhali učedlníci jeho klasy, a rukama vymínajíce, jedli.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 2, 'Tehdy někteří z farizeů řekli jim: Proč činíte, čehož nesluší činiti v sobotu?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 3, 'I odpověděv Ježíš, řekl jim: Což jste ani toho nečtli, co učinil David, když lačněl, on i ti, kteříž s ním byli?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 4, 'Kterak všel do domu Božího, a chleby posvátné vzal a jedl, a dal i těm, kteříž s ním byli, jichž nenáleží jísti než toliko samým kněžím?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 5, 'I řekl jim: Že jest Syn člověka pánem také i dne sobotního.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 6, 'Stalo se pak i v jinou sobotu, že všel do školy Ježíš a učil. A byl tu člověk, jehož pravá ruka byla uschlá.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 7, 'I šetřili ho zákonníci a farizeové, bude-li v sobotu uzdravovati, aby nalezli, z čeho by jej obžalovali.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 8, 'Ale on znal přemyšlování jejich. I dí člověku, kterýž měl ruku uschlou: Vstaň, a stůj v prostředku. A on vstav, stál.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 9, 'Tedy řekl jim Ježíš: Otíži se vás na jednu věc: Sluší-li v sobotu dobře činiti, čili zle, duši zachovati, čili zatratiti?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 10, 'A pohleděv na ně na všecky vůkol, dí člověku tomu: Vztáhni tu ruku svou. A on učinil tak. I přivedena jest k zdraví ruka jeho jako druhá.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 11, 'Oni pak naplněni jsou hněvivou nemoudrostí, a rozmlouvali mezi sebou, co by učiniti měli Ježíšovi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 12, 'I stalo se v těch dnech, vyšel na horu k modlení. I byl tam přes noc na modlitbě Boží.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 13, 'A když byl den, povolal učedlníků svých, a vyvolil z nich dvanácte, kteréž i apoštoly nazval:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 14, '(Šimona, kterémuž také dal jméno Petr, a Ondřeje bratra jeho, Jakuba a Jana, Filipa a Bartoloměje,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 15, 'Matouše a Tomáše, Jakuba Alfeova, a Šimona, kterýž slove Zelótes,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 16, 'Judu Jakubova, a Jidáše Iškariotského, kterýž potom byl zrádce.)');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 17, 'I sstoupiv s nimi, stál na místě polním, a zástup učedlníků jeho, a množství veliké lidu ze všeho Judstva i z Jeruzaléma, i z Týru i z Sidonu, kteříž při moři jsou, kteříž byli přišli, aby jej slyšeli, a uzdraveni byli od neduhů svých,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 18, 'I kteříž trápeni byli od duchů nečistých. A byli uzdravováni.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 19, 'A všecken zástup hledal se ho dotknouti; nebo moc z něho vycházela, a uzdravovala všecky.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 20, 'A on pozdvih očí svých na učedlníky, pravil: Blahoslavení chudí, nebo vaše jest království Boží.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 21, 'Blahoslavení, kteříž nyní lačníte, nebo nasyceni budete. Blahoslavení, kteříž nyní plačete, nebo smáti se budete.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 22, 'Blahoslavení budete, když vás nenáviděti budou lidé, a když vás vyobcují, a haněti budou, a vyvrhou jméno vaše jako zlé, pro Syna člověka.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 23, 'Radujte se v ten den, a veselte se, nebo aj, odplata vaše mnohá v nebesích. Takť zajisté činívali prorokům otcové jejich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 24, 'Ale běda vám bohatým, nebo vy již máte potěšení své.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 25, 'Běda vám, kteříž jste nasyceni, nebo lačněti budete. Běda vám, kteříž se nyní smějete, nebo kvíliti a plakati budete.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 26, 'Běda vám, když by dobře o vás mluvili všickni lidé; nebo tak činívali falešným prorokům otcové jejich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 27, 'Ale vámť pravím, kteříž slyšíte: Milujte nepřátely své, dobře čiňte těm, kteříž vás nenávidí,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 28, 'Dobrořečte těm, kteříž vás proklínají, a modlte se za ty, kteříž vám bezpráví činí.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 29, 'A udeřil-li by tebe kdo v líce, nasaď mu i druhého, a tomu, kterýž tobě odjímá plášť, také i sukně nebraň.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 30, 'Každému pak prosícímu tebe dej, a od toho, kterýž béře tvé věci, zase nežádej.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 31, 'A jakž chcete, aby vám lidé činili, i vy jim též podobně čiňte.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 32, 'Nebo jestliže milujete ty, kteříž vás milují, jakou míti budete milost? Nebo i hříšníci milují ty, od nichž milováni bývají.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 33, 'A budete-li dobře činiti těm, kteříž vám dobře činí, jakou máte milost? Však i hříšnící totéž činí.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 34, 'A budete-li půjčovati těm, od kterýchž se nadějete zase vzíti, jakou máte milost? Však i hříšníci hříšníkům půjčují, aby tolikéž zase vzali.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 35, 'Nýbrž milujte nepřátely své, a dobře čiňte, a půjčujte, nic se odtud nenadějíce, a budeť odplata vaše mnohá, a budete synové Nejvyššího. Nebo on dobrotivý jest i k nevděčným a zlým.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 36, 'Protož buďte milosrdní, jako i Otec váš milosrdný jest.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 37, 'Nesuďte, a nebudete souzeni. Nepotupujte, a nebudete potupeni. Odpouštějte, a budeť vám odpuštěno.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 38, 'Dávejte, a budeť vám dáno. Míru dobrou, natlačenou, a natřesenou, a osutou dadíť v lůno vaše; touž zajisté měrou, kterouž měříte, bude vám zase odměřeno.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 39, 'Pověděl jim také i podobenství: Zdali může slepý slepého vésti? Zdaž oba do jámy neupadnou?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 40, 'Neníť učedlník nad mistra svého, ale dokonalý bude každý, bude-li jako mistr jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 41, 'Což pak vidíš mrvu v oku bratra svého, a břevna, kteréž jest v tvém vlastním oku, neznamenáš?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 42, 'Aneb kterak můžeš říci bratru svému: Bratře, nechať vyňmu mrvu, kteráž jest v oku tvém, sám v oku svém břevna nevida? Pokrytče, vyvrz prvé břevno z oka svého, a tehdy prohlédneš, abys vyňal mrvu, kteráž jest v oku bratra tvého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 43, 'Neboť není ten strom dobrý, kterýž nese ovoce zlé, aniž jest strom zlý, kterýž nese ovoce dobré.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 44, 'Každý zajisté strom po svém vlastním ovoci bývá poznán; nebo nezbírají s trní fíků, ani s hloží zbírají hroznů.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 45, 'Dobrý člověk z dobrého pokladu srdce svého vynáší dobré, a zlý člověk ze zlého pokladu srdce svého vynáší zlé. Nebo z hojnosti srdce mluví ústa jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 46, 'Co pak mi říkáte: Pane, Pane, a nečiníte, což pravím?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 47, 'Každý kdož přichází ke mně, a slyší slovo mé, a zachovává je, ukáži vám, komu by podoben byl.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 48, 'Podoben jest člověku stavějícímu dům, kterýž kopal a vytesal hluboko, a založil grunty v skále. A když se povodeň strhla, obořila se řeka na dům ten, ale nemohla ním pohnouti, nebo byl založen na skále.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 49, 'Ale kdož slyší a nečiní, podoben jest člověku, kterýž staví dům svůj na zemi bez gruntu. Na kterýž obořila se řeka, a on hned padl, i byl pád domu toho veliký.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 1, 'A když vykonal všecka slova svá při přitomnosti lidu, všel do Kafarnaum.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 2, 'Setníka pak nějakého služebník nemocen jsa, k smrti se přibližoval, kteréhož on sobě mnoho vážil.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 3, 'I uslyšav o Ježíšovi, poslal k němu starší Židovské, prose ho, aby přišel a uzdravil služebníka jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 4, 'A oni přišedše k Ježíšovi, prosili ho snažně, řkouce: Hoden jest, abys mu to učinil.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 5, 'Nebo miluje národ náš, a školu on nám vystavěl.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 6, 'Tedy Ježíš šel s nimi. A když již nedaleko byl od domu, poslal k němu ten setník přátely, řka jemu: Pane, nepřidávej sobě práce. (Nejsem zajisté hoden, abys všel pod střechu mou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 7, 'A protož jsem i sebe samého za nehodného položil, abych přišel k tobě.) Ale rci slovem, a budeť uzdraven služebník můj.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 8, 'Nebo i já jsem člověk pod mocí postavený, maje pod sebou žoldnéře, a dím tomuto: Jdi, a jde, a jinému: Přiď, a přijde, a služebníku svému: Učiň toto, a učiní.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 9, 'Tedy uslyšav to Ježíš, podivil se jemu, a obrátiv se, řekl zástupu, kterýž za ním šel: Pravím vám, že ani v Izraeli nenalezl jsem tak veliké víry.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 10, 'Vrátivše se pak domů ti, kteříž posláni byli, nalezli služebníka, kterýž nemocen byl, zdravého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 11, 'I stalo se potom, šel do města, kteréž slove Naim, a šli s ním učedlníci jeho mnozí a zástup veliký.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 12, 'A když se přiblížil k bráně města, aj, mrtvý byl nesen ven, syn jediný matky své, a ta vdova byla, a zástup města mnohý s ní.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 13, 'Kteroužto uzřev Pán, milosrdenstvím hnut jest k ní, a řekl jí: Neplačiž.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 14, 'A přistoupiv, dotekl se már. (Ti pak, kteříž nesli, zastavili se.) I řekl: Mládenče, toběť pravím, vstaň.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 15, 'I posadil se ten mrtvý, a počal mluviti. I dal jej mateři jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 16, 'Tedy podjala všecky bázeň, i velebili Boha, řkouce: Prorok veliký povstal mezi námi, a Bůh navštívil lid svůj.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 17, 'I vyšla řeč ta o něm po všem Judstvu i po vší okolní krajině.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 18, 'I zvěstovali Janovi učedlníci jeho o všech těchto věcech. A zavolav kterýchs dvou z učedlníků svých Jan,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 19, 'Poslal k Ježíšovi, řka: Ty-li jsi ten, kterýž přijíti má, čili jiného čekati máme?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 20, 'Přišedše pak k němu muži ti, řekli: Jan Křtitel poslal nás k tobě řka: Ty-li jsi ten, kterýž přijíti má, čili jiného čekati máme?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 21, 'A v touž hodinu mnohé uzdravil od neduhů, od nemocí a duchů zlých, a slepým mnohým zrak dal.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 22, 'Odpověděv pak Ježíš, řekl jim: Jdouce, povězte Janovi, co jste viděli a slyšeli, že slepí vidí, kulhaví chodí, malomocní očištění přijímají, hluší slyší, mrtví z mrtvých vstávají, chudým se zvěstuje evangelium.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 23, 'A blahoslavený jest, kdož by se na mně nezhoršil.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 24, 'A když odešli poslové Janovi, počal praviti zástupům o Janovi: Co jste vyšli na poušť spatřovati? Třtinu-li, kteráž se větrem klátí?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 25, 'Aneb nač jste hleděti vyšli? Na člověka-li měkkým rouchem oděného? Aj, kteříž v rouše slavném a v rozkoši jsou, v domích královských jsou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 26, 'Aneb co jste vyšli viděti? Proroka-li? Jistě pravím vám, i více nežli proroka.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 27, 'Tentoť jest, o kterémž jest psáno: Aj, já posílám anděla svého před tváří tvou, kterýž připraví cestu tvou před tebou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 28, 'Nebo pravím vám, většího proroka mezi syny ženskými nad Jana Křtitele není žádného, ale kdož jest menší v království Božím, většíť jest nežli on.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 29, 'Tedy všecken lid slyše to i publikáni, velebili Boha, byvše pokřtěni křtem Janovým.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 30, 'Ale farizeové a zákonníci pohrdli radou Boží sami proti sobě, nebyvše pokřtěni od něho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 31, 'I řekl Pán: Komu tedy přirovnám lidi pokolení tohoto, a čemu podobni jsou?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 32, 'Podobni jsou dětem, kteříž na rynku sedí, a jedni na druhé volají, říkajíce: Pískali jsme vám, a neskákali jste; žalostně jsme naříkali vám, a neplakali jste.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 33, 'Nebo přišel Jan Křtitel, ani chleba nejeda, ani nepije vína, a pravíte: Ďábelství má.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 34, 'Přišel Syn člověka, jeda a pije, a pravíte: Aj, člověk žráč a piján vína, přítel publikánů a hříšníků.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 35, 'Ale ospravedlněna jest moudrost ode všech synů svých.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 36, 'Prosil ho pak jeden z farizeů, aby jedl s ním. Pročež všed do domu toho farizea, posadil se za stůl.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 37, 'A aj, žena v městě, kteráž byla hříšnice, zvěděvši, že by seděl za stolem v domě farizea, přinesla nádobu alabastrovou masti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 38, 'A stojeci z zadu u noh jeho s pláčem, počala slzami smáčeti nohy jeho, a vlasy hlavy své vytírala, a líbala nohy jeho, a mastí mazala.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 39, 'Uzřev pak to farizeus, kterýž ho byl pozval, řekl sám v sobě tak: Byť tento byl prorok, vědělť by, která a jaká jest to žena, kteráž se ho dotýká; nebo hříšnice jest.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 40, 'I odpověděv Ježíš, dí jemu: Šimone, mámť něco povědíti. A on řekl: Mistře, pověz.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 41, 'Dva dlužníky měl nějaký věřitel. Jeden dlužen byl pět set peněz, a druhý padesát.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 42, 'A když neměli, odkud by zaplatili, odpustil oběma. Pověziž tedy, který z nich více bude jej milovati?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 43, 'I odpověděv Šimon, řekl: Mám za to, že ten, kterémuž více odpustil. A on řekl jemu: Právě jsi rozsoudil.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 44, 'A obrátiv se k ženě, řekl Šimonovi: Vidíš tuto ženu? Všel jsem do domu tvého, vody nohám mým nedal jsi, ale tato slzami smáčela nohy mé, a vlasy hlavy své vytřela.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 45, 'Nepolíbil jsi mne, ale tato, jakž jsem všel, nepřestala líbati noh mých.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 46, 'Olejem hlavy mé nepomazal jsi, ale tato mastí mazala nohy mé.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 47, 'Protož pravím tobě: Odpuštěniť jsou jí hříchové mnozí, neboť milovala mnoho. Komuť se pak málo odpouští, málo miluje.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 48, 'I řekl jí: Odpuštěniť jsou tobě hříchové.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 49, 'Tedy počali, kteříž tu spolu seděli za stolem, říci sami mezi sebou: Kdo jest tento, kterýž i hříchy odpouští?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 50, 'I řekl ženě: Víra tvá tebe k spasení přivedla. Jdiž u pokoji.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 1, 'I stalo se potom, že on chodil po městech a po městečkách, káže a zvěstuje království Boží, a dvanácte s ním.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 2, 'I ženy některé, kteréž byl uzdravil od duchů zlých a od nemocí: Maria, kteráž slove Magdaléna, z níž bylo sedm ďáblů vyšlo,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 3, 'A Johanna manželka Chuzova, úředníka Heródesova, a Zuzanna, a jiné mnohé, kteréž posluhovaly jemu z statků svých.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 4, 'Když se pak scházel zástup mnohý, a z měst hrnuli se k němu, mluvil v podobenství:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 5, 'Vyšel rozsevač, aby rozsíval símě své. A když on rozsíval, jedno padlo podlé cesty, i pošlapáno jest, a ptáci nebeští zzobali je.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 6, 'A jiné padlo na skálu, a vzešlé uvadlo, proto že nemělo vláhy.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 7, 'Jiné pak padlo mezi trní, a spolu zrostlé trní udusilo je.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 8, 'A jiné padlo v zemi dobrou, a když vzešlo, učinilo užitek stý. To pověděv, volal: Kdo má uši k slyšení, slyš.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 9, 'I otázali se ho učedlníci jeho, řkouce: Jaké jest to podobenství?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 10, 'A on řekl: Vám dáno jest znáti tajemství království Božího, ale jiným v podobenství, aby hledíce, neviděli, a slyšíce, nerozuměli.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 11, 'Jestiť pak podobenství toto: Símě jest slovo Boží.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 12, 'A kteréž padlo podlé cesty, jsou ti, kteříž slyší, a potom přichází ďábel, a vynímá slovo z srdce jejich, aby nevěříce, spaseni nebyli.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 13, 'Ale kteříž na skálu, ti když slyší, s radostí přijímají slovo, ale ti kořenů nemají; ti na čas věří, a v čas pokušení odstupují.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 14, 'Kteréž pak mezi trní padlo, tiť jsou, kteříž slyší, ale po pečování a zboží a rozkošech života jdouce, bývají udušeni, a nepřinášejí užitku.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 15, 'Ale kteréž v zemi dobrou, ti jsou, kteříž v srdci ctném a dobrém, slyšíce slovo, zachovávají, a užitek přinášejí v trpělivosti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 16, 'Žádný pak rozsvítě svíci, nepřikrývá jí nádobou, ani staví pod postel, ale na svícen staví, aby ti, kteříž vcházejí, světlo viděli.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 17, 'Nebo nic není tajného, což by nemělo býti zjeveno, ani co ukrytého, což by nemělo poznáno býti, a na světlo vyjíti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 18, 'Protož vizte, jak slyšíte. Nebo kdož má, tomu bude dáno, a kdo nemá, i to, což domnívá se míti, bude odjato od něho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 19, 'Tedy přišli k němu matka a bratří jeho, ale nemohli ho dojíti pro zástup.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 20, 'I pověděli mu, řkouce: Matka tvá a bratří tvoji stojí vně, chtíce tebe viděti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 21, 'A on odpověděv, řekl jim: Matka má a bratří moji jsou ti, kteříž slovo Boží slyší a plní je.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 22, 'Stalo se pak v jeden den, že on vstoupil na lodí i učedlníci jeho. I řekl jim: Přeplavme se přes jezero. I pustili se.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 23, 'A když se plavili, usnul. Tedy přišel vítr bouřlivý na jezero, a lodí se naplňovala, tak že v nebezpečenství byli.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 24, 'I přistoupivše, zbudili ho, řkouce: Mistře, Mistře, hyneme. A on procítiv, přimluvil větru a zdutí vod. I spokojili se, a stalo se utišení.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 25, 'I řekl jim: Kdež jest víra vaše? Kteřížto bojíce se, podivili se, vespolek řkouce: I kdo jest tento, že i větrům přikazuje i vodám, a poslouchají ho?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 26, 'I přeplavili se do krajiny Gadarenské, kteráž jest proti Galilei.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 27, 'A když vystoupil na zemi, potkal jej muž nějaký z města, kterýž měl ďábelství od mnoha časů, a rouchem se neodíval, ani v domě nebýval, ale v hrobích.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 28, 'Uzřev pak Ježíše a zkřikna, padl před ním, a hlasem velikým řekl: Co jest tobě do mne, Ježíši, Synu Boha nejvyššího? Prosím tebe, netrap mne.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 29, 'Nebo přikazoval tomu duchu nečistému, aby vyšel z toho člověka. Po mnohé zajisté časy jím lomcoval, tak že býval ukován řetězy, a v poutech ostříhán, ale on polámaje okovy, býval od ďábelství puzen na poušť.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 30, 'I otázal se ho Ježíš, řka: Jakť říkají? A on řekl: Množství. Nebo bylo mnoho ďáblů vešlo do něho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 31, 'Tedy prosili ho, aby jim nepřikazoval odtud odjíti do propasti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 32, 'Bylo pak tu veliké stádo vepřů, kteříž se pásli na hoře. I prosili ho, aby jim dopustil do nich vjíti. I dopustil jim.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 33, 'I vyšedše ďáblové z toho člověka, vešli do vepřů, i hnalo se to stádo prudce s vrchu do jezera, a ztonulo.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 34, 'A viděvše pastýři, co se stalo, utekli, a šedše, vypravovali to v městě i po vsech.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 35, 'I vyšli, aby viděli, co se stalo. I přišli k Ježíšovi, a nalezli člověka toho, z kteréhož ďáblové vyšli, oděného a majícího rozum, an sedí u noh Ježíšových. I báli se.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 36, 'A vypravovali jim také ti, kteříž byli viděli, kterak jest ten vyproštěn, kterýž ďábelství měl.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 37, 'I prosilo ho všecko množství té okolní krajiny Gadarenských, aby odšel od nich; nebo bázní velikou naplněni byli. A on vstoupiv na lodí, navrátil se.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 38, 'Prosil ho pak muž ten, z kteréhož ďáblové vyšli, aby s ním byl. Ale Ježíš propustil ho, řka:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 39, 'Navrať se do domu svého, a vypravuj, kterak veliké věci učinil tobě Bůh. I odšel, po všem městě vypravuje, jak veliké věci učinil jemu Ježíš.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 40, 'Stalo se pak, když se navrátil Ježíš, že přijal jej zástup; nebo všickni očekávali ho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 41, 'A aj, přišel muž, kterémuž jméno bylo Jairus, a ten byl kníže školy. I padna k nohám Ježíšovým, prosil ho, aby všel do domu jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 42, 'Nebo měl dceru jedinou, asi ve dvanácti letech, a ta umírala. A když šel, tiskli jej zástupové.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 43, 'Tedy žena, kteráž nemoc svou trpěla od let dvanácti, a byla na lékaře vynaložila všecken statek, a od žádného nemohla uzdravena býti,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 44, 'Přistoupivši po zadu, dotkla se podolka roucha jeho, a hned přestala nemoc její.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 45, 'I řekl Ježíš: Kdo jest, ješto se mne dotekl? A když všickni zapírali, řekl Petr, a kteříž s ním byli: Mistře, zástupové tebe tisknou a tlačí, a pravíš: Kdo se mne dotekl?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 46, 'I řekl Ježíš: Dotekl se mne někdo, nebo poznal jsem já, že moc ode mne vyšla.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 47, 'A viduci ta žena, že by tajno nebylo, třesuci se, přistoupila a padla před ním, a pro kterou příčinu dotkla se ho, pověděla jemu přede vším lidem, a kterak jest hned uzdravena.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 48, 'A on řekl jí: Dobré mysli buď, dcero, víra tvá tebe uzdravila. Jdiž u pokoji.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 49, 'A když on ještě mluvil, přišel jeden od knížete školy, řka jemu: Umřela dcera tvá, nezaměstknávej Mistra.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 50, 'Ale Ježíš uslyšav to, odpověděl jemu: Neboj se, věř toliko, a zdrávať bude.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 51, 'A všed do domu, nedopustil s sebou vjíti žádnému, než Petrovi a Jakubovi a Janovi, a otci a mateři té děvečky.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 52, 'Plakali jí pak všickni a kvílili. A on řekl: Neplačtež. Neumřelať, ale spí.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 53, 'I posmívali se jemu, vědouce, že umřela.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 54, 'On pak vyhnav ven všecky, a ujav ruku její, zvolal, řka: Děvečko, vstaň.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 55, 'I navrátil se duch její, a vstala hned. I kázal jí dáti jísti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 56, 'I divili se náramně rodičové její. A on jim kázal, aby žádnému nepravili o tom, co se bylo stalo.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 1, 'I svolav dvanácte učedlníků svých, dal jim sílu a moc nad všelikým ďábelstvím, a aby neduhy uzdravovali.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 2, 'I poslal je, aby kázali království Boží, a uzdravovali nemocné.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 3, 'A řekl jim: Nic nebeřte na tu cestu, ani hůlky, ani mošny, ani chleba, ani peněz, ani po dvou sukních mívejte.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 4, 'A do kteréhožkoli domu vešli byste, tu zůstaňte, a odtud vyjděte.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 5, 'A kteříž by vás koli nepřijali, vyjdouce z města toho, také i ten prach z noh svých vyrazte na svědectví proti nim.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 6, 'I vyšedše, chodili po městečkách vůkol, zvěstujíce evangelium, a uzdravujíce všudy.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 7, 'Uslyšel pak Heródes čtvrták o všech věcech, kteréž se dály od něho. I rozjímal to v mysli své, proto že bylo praveno od některých, že by Jan vstal z mrtvých,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 8, 'A od jiných, že by se Eliáš zjevil, od některých pak, že by jeden z proroků starých vstal.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 9, 'I řekl Heródes: Jana jsem já sťal. Kdož pak jest tento, o kterémž já slyším takové věci? I žádostiv byl ho viděti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 10, 'Vrátivše se pak apoštolé, vypravovali jemu, cožkoli činili. A pojav je, odšel soukromí na místo pusté města řečeného Betsaida.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 11, 'Zvěděvše pak zástupové, šli za ním; i přijal je, a mluvil jim o království Božím, a ty, kteříž uzdravení potřebovali, uzdravoval.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 12, 'Den pak počal se nachylovati. I přistoupivše dvanácte, řekli jemu: Propusť zástupy, ať rozejdouce se do městeček okolních a do vesnic, jdou a hledají pokrmů, nebo jsme tuto na místě pustém.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 13, 'I řekl jim: Dejte vy jim jísti. A oni řekli: Nemámeť víc než pět chlebů a dvě rybě, leč bychom my snad šli a nakoupili na tento všecken lid pokrmů?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 14, 'Nebo bylo mužů okolo pěti tisíců. I řekl učedlníkům svým. Rozkažte se jim posaditi v každém řadu po padesáti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 15, 'I učinili tak, a posadili se všickni.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 16, 'A vzav těch pět chlebů a ty dvě rybě, vzhlédl v nebe, a dobrořečil jim, i lámal, a rozdával učedlníkům, aby kladli před zástup.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 17, 'I jedli, a nasyceni jsou všickni. A sebráno jest, což jim bylo ostalo drobtů, dvanácte košů.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 18, 'I stalo se, když se on modlil obzvláštně, že byli s ním učedlníci. I otázal se jich, řka: Kým mne praví býti zástupové?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 19, 'A oni odpověděvše, řekli: Janem Křtitelem, a jiní Eliášem, jiní pak, že prorok jeden z starých vstal.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 20, 'I řekl jim: Vy pak kým mne býti pravíte? Odpověděv Petr, řekl: Krista toho Božího.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 21, 'A on s pohrůžkou jim přikázal, aby toho žádnému nepravili,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 22, 'Pravě: Že Syn člověka musí mnoho trpěti, a potupen býti od starších a od předních kněží {biskupů} i od zákonníků, a zamordován býti, a třetího dne z mrtvých vstáti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 23, 'I pravil všechněm: Chce-li kdo přijíti za mnou, zapři sám sebe, a beř svůj kříž na každý den, a následuj mne.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 24, 'Nebo kdož bude chtíti duši svou zachovati, ztratíť ji; a kdož ztratí duši svou pro mne, tenť ji zachová,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 25, 'Nebo co jest platno člověku, by všecken svět získal, kdyby sám sebe ztratil, aneb sám sebe zmrhal?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 26, 'Nebo kdož by se za mne styděl a za mé řeči, za tohoť se Syn člověka styděti bude, když přijde v slávě své a Otcově i svatých andělů.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 27, 'Ale pravímť vám jistě: Jsou někteří z stojících tuto, kteříž neokusí smrti, až uzří království Boží.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 28, 'I stalo se po těch řečech, jako po osmi dnech, že vzav s sebou Petra a Jakuba a Jana, vstoupil na horu, aby se modlil.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 29, 'A když se modlil, učiněna jest tvář jeho proměněná, a oděv jeho bílý a stkvoucí.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 30, 'A aj, dva muži mluvili s ním, a ti byli Mojžíš a Eliáš.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 31, 'Kteříž okázavše se v slávě, vypravovali o smrti jeho, kterouž měl podstoupiti v Jeruzalémě.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 32, 'Petr pak a ti, kteříž s ním byli, obtíženi byli snem, a procítivše, viděli slávu jeho a ty dva muže, ani stojí s ním.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 33, 'I stalo se, když oni odešli od něho, řekl Petr Ježíšovi: Mistře, dobréť jest nám zde býti. Protož udělejme tři stánky, tobě jeden, a Mojžíšovi jeden, a Eliášovi jeden, nevěda, co mluví.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 34, 'A když on to mluvil, stal se oblak, i zastínil je. Báli se pak, když onino vcházeli do oblaku.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 35, 'I stal se hlas z oblaku řkoucí: Tentoť jest ten Syn můj milý, toho poslouchejte.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 36, 'A když se ten hlas stal, nalezen jest Ježíš sám. A oni mlčeli, a nepravili žádnému v těch dnech ničeho z těch věcí, kteréž viděli.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 37, 'Stalo se pak druhého dne, když sstupovali s hory, potkal jej zástup mnohý.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 38, 'A aj, muž z zástupu zvolal, řka: Mistře, prosím tebe, vzhlédni na syna mého, neboť jediného toho mám.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 39, 'A aj, duch jej napadá, a on i hned křičí, a lomcuje jím slinícím se, a nesnadně odchází od něho, sápaje jím.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 40, 'I prosil jsem učedlníků tvých, aby jej vyvrhli, ale nemohli.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 41, 'I odpověděv Ježíš, řekl: Ó pokolení nevěrné a převrácené, dokudž budu u vás, a snášeti budu vás? Přiveď sem syna svého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 42, 'A v tom, když on přicházel, porazil jej ďábel, a lomcoval jím. I přimluvil duchu nečistému Ježíš, a uzdravil toho mládence, a navrátil jej otci jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 43, 'I děsili se všickni nad velikomocností Božskou. A když se všickni divili všem věcem, kteréž činil Ježíš, řekl učedlníkům svým:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 44, 'Složte vy v uších svých řeči tyto, neboť Syn člověka bude vydán v ruce lidské.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 45, 'Ale oni nesrozuměli slovu tomu, a bylo před nimi skryto, aby nevyrozuměli jemu. A nesměli se ho otázati o tom slovu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 46, 'I vznikla mezi nimi hádka o to, kdo by z nich byl největší.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 47, 'Ježíš pak viděv přemyšlování srdce jejich, vzav dítě, postavil je podlé sebe,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 48, 'A řekl jim: Kdožkoli přijal by dítě toto ve jménu mém, mneť přijímá; a kdož by koli mne přijal, přijímá toho, kterýž mne poslal. Nebo kdožť jest nejmenší mezi všemi vámi, tenť bude veliký.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 49, 'I odpověděv Jan, řekl: Mistře, viděli jsme jednoho, an ve jménu tvém ďábly vymítá; i bránili jsme mu, proto že nechodí s námi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 50, 'I dí jemu Ježíš: Nebraňtež. Nebo kdoť není proti nám, s námiť jest.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 51, 'I stalo se, když se doplnili dnové vzetí jeho zhůru, že on se na tom ustavil, aby šel do Jeruzaléma.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 52, 'I poslal posly před sebou. A oni jdouce, vešli do městečka Samaritánského, aby jemu připravili.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 53, 'Ale nepřijali ho, proto že oblíčej jeho byl obrácen k jití do Jeruzaléma.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 54, 'A viděvše to učedlníci jeho Jakub a Jan, řekli: Pane, chceš-li, ať díme, aby oheň sstoupil s nebe, a spálil je, jako i Eliáš učinil?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 55, 'Ale obrátiv se, potrestal jich, řka: Nevíte, čího jste vy duchu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 56, 'Syn zajisté člověka nepřišel zatracovati duší lidských, ale aby spasil. I odešli do jiného městečka.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 57, 'Stalo se pak, když šli, že řekl jemu na cestě jeden: Pane, půjdu za tebou, kam se koli obrátíš.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 58, 'I řekl jemu Ježíš: Lišky doupata mají, a ptáci nebeští hnízda, ale Syn člověka nemá, kde by hlavu sklonil.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 59, 'I řekl jinému: Poď za mnou. Ale on řekl: Pane, dopusť mi prvé jíti a pochovati otce mého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 60, 'I dí jemu Ježíš: Nech ať mrtví pochovávají mrtvé své, ale ty jda, zvěstuj království Boží.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 61, 'I řekl opět jiný: Půjdu za tebou, Pane, ale prvé dopusť mi, ať se rozžehnám s těmi, kteříž jsou v domě mém.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 62, 'Řekl jemu Ježíš: Žádný, kdož vztáhna ruku svou k pluhu, ohlídal by se nazpět, není způsobný k království Božímu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 1, 'Potom pak vyvolil Pán i jiných sedmdesát, a poslal je po dvou před tváří svou do každého města i místa, kamž měl sám přijíti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 2, 'A pravil jim: Žeň zajisté jest mnohá, ale dělníků málo. Protož proste Pána žně, ať vypudí dělníky na žeň svou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 3, 'Jdětež. Aj, já posílám vás jako berany mezi vlky.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 4, 'Nenostež pytlíka, ani mošny, ani obuvi, a žádného na cestě nepozdravujte.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 5, 'A do kteréhožkoli domu vejdete, nejprvé rcete: Pokoj tomuto domu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 6, 'A bude-liť tu syn pokoje, odpočineť na něm pokoj váš; pakli nic, k vámť se navrátí.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 7, 'A v témž domu ostaňte, jedouce a pijíce, což u nich jest, nebo hoden jest dělník mzdy své. Nechoďtež z domu do domu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 8, 'Ale do kteréhožkoli města vešli byste, a přijali by vás, jezte, což před vás předloží.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 9, 'A uzdravujte nemocné, kteříž by v něm byli, a rcete jim: Přiblížiloť se k vám království Boží.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 10, 'A do kteréhožkoli města vešli byste, a nepřijali by vás, vyjdouce na ulice jeho, rcetež:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 11, 'Také i ten prach, kterýž se přichytil nás z města vašeho, vyrážíme na vás. Ale však to vězte, žeť se jest přiblížilo k vám království Boží.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 12, 'Pravím zajisté vám, že Sodomským v onen den lehčeji bude než tomu městu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 13, 'Běda tobě Korozaim, běda tobě Betsaido. Nebo kdyby v Týru a v Sidonu činěni byli divové ti, kteříž v vás činěni jsou, dávno by v žíni a v popele sedíce, pokání činili.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 14, 'A protož Týru a Sidonu lehčeji bude na soudu nežli vám.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 15, 'A ty Kafarnaum, kteréž jsi až do nebe zvýšeno, až do pekla sníženo budeš.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 16, 'Kdož vás slyší, mne slyší; a kdo vámi pohrdá, mnou pohrdá; kdož pak mnou pohrdá, pohrdáť tím, kdož mne poslal.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 17, 'Potom navrátilo se s radostí těch sedmdesáte, řkouce: Pane, také i ďáblové se nám poddávají ve jménu tvém.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 18, 'I řekl jim: Viděl jsem satana jako blesk padajícího s nebe.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 19, 'Aj, dávámť vám moc šlapati na hady a na štíry i na všelikou moc nepřítele, a nic vám neuškodí.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 20, 'A však z toho se neradujte, že se vám poddávají duchové, ale raději se radujte, že jména vaše napsána jsou v nebesích.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 21, 'V tu hodinu rozveselil se v duchu Ježíš, a řekl: Chválím tě, Otče, Pane nebe i země, že jsi tyto věci skryl před moudrými a opatrnými, a zjevils je nemluvňátkům. Ovšem, Otče, nebo se tak líbilo před tebou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 22, 'Všecky věci dány jsou mi od Otce mého, a žádný neví, kdo by byl Syn, jediné Otec, a kdo by byl Otec, jediné Syn, a komuž by chtěl Syn zjeviti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 23, 'A obrátiv se k učedlníkům obzvláštně, řekl: Blahoslavené oči, kteréž vidí, co vy vidíte.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 24, 'Nebo pravím vám, že mnozí proroci i králové chtěli viděti, což vy vidíte, ale neviděli, a slyšeti, což vy slyšíte, ale neslyšeli.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 25, 'A aj, jeden zákonník vstal, pokoušeje ho, a řka: Mistře, co čině, život věčný dědičně obdržím?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 26, 'A on řekl jemu: V zákoně co jest psáno? Kterak čteš?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 27, 'A on odpověděv, řekl: Milovati budeš Pána Boha svého ze všeho srdce svého, a ze vší duše své, a ze vší síly své, i ze vší mysli své, a bližního svého jako sebe samého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 28, 'I řekl mu: Právě jsi odpověděl. To čiň, a živ budeš.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 29, 'On pak chtěje se sám ospravedlniti, dí Ježíšovi: A kdo jest můj bližní?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 30, 'I odpověděv Ježíš, řekl: Člověk jeden šel z Jeruzaléma do Jericho, i upadl mezi lotry. Kteříž obloupivše jej a zranivše, odešli, odpolu živého nechavše.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 31, 'I přihodilo se, že kněz jeden šel touž cestou, a uzřev jej, pominul.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 32, 'Též i Levíta přišed až k tomu místu, a uzřev jej, pominul.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 33, 'Samaritán pak jeden, cestou se ubíraje, přišel až k němu, a uzřev jej, milosrdenstvím hnut jest.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 34, 'A přistoupiv, uvázal rány jeho, naliv oleje a vína, a vloživ jej na hovado své, vedl do hospody, a péči o něj měl.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 35, 'Druhého pak dne odjíti maje, vyňav dva peníze, dal hospodáři, a řekl jemu: Měj o něj péči, a cožkoli nad to vynaložíš, já když se vrátím, zaplatím tobě.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 36, 'Kdo tedy z těch tří zdá se tobě bližním býti tomu, kterýž upadl mezi lotry?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 37, 'A on řekl: Ten, kterýž prokázal milosrdenství nad ním. I řekl jemu Ježíš: Jdi, i ty učiň též.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 38, 'I stalo se, když šli, že on všel do jednoho městečka. Žena pak jedna, jménem Marta, přijala jej do domu svého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 39, 'A ta měla sestru, jménem Marii, kteráž seděci u noh Ježíšových, poslouchala slova jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 40, 'Ale Marta pečlivá byla při mnohé službě. Kteráž přistoupivši, řekla: Pane, nemáš-liž o to péče, že sestra má nechala mne samé sloužiti? Protož rci jí, ať mi pomůž.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 41, 'A odpověděv, řekl jí Ježíš: Marta, Marta, pečlivá jsi, a rmoutíš se při mnohých věcech.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 42, 'Ale jednohoť jest potřebí. Mariať dobrou stránku vyvolila, kteráž nebude odjata od ní.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 1, 'I stalo se, když se na jednom místě modlil, když přestal, řekl jemu jeden z učedlníků jeho: Pane, nauč nás modliti se, jako i Jan učil učedlníky své.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 2, 'I řekl jim: Když se modlíte, říkejte: Otče náš, kterýž jsi v nebesích, posvěť se jméno tvé. Přiď království tvé. Buď vůle tvá, jako v nebi tak i na zemi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 3, 'Chléb náš vezdejší dávej nám každého dne.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 4, 'I odpusť nám hříchy naše, nebo i my odpouštíme všelikému vinníku svému. A neuvoď nás v pokušení, ale zbav nás od zlého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 5, 'I řekl jim: Kdo z vás bude míti přítele, a půjde k němu o půlnoci, a dí jemu: Příteli, půjč mi tří chlebů.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 6, 'Nebo přítel můj přišel s cesty ke mně, a nemám, co bych předložil před něj.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 7, 'A on vnitř jsa, odpověděl by: Nečiň mi nevole; dvéře již zavříny, a dítky mé se mnou jsou v pokoji. Nemohuť vstáti a dáti tobě.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 8, 'Pravím vám: Ačť nedá jemu, vstana, proto že jest přítel jeho, ale však pro nezbednost jeho vstana, dá jemu, kolikžkoli potřebuje.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 9, 'I jáť pravím vám: Proste, a budeť vám dáno; hledejte, a naleznete; tlucte, a budeť vám otevříno.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 10, 'Nebo každý, kdož prosí, béře; a kdož hledá, nalézá; a tomu, kdož tluče, bude otevříno.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 11, 'Kterého pak z vás otce prosil by syn za chléb, zdali kamene podá jemu? Aneb za rybu, zdali místo ryby dá jemu hada?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 12, 'Aneb prosil-li by za vejce, zdali podá jemu štíra?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 13, 'Poněvadž tedy vy, jsouce zlí, umíte dobré dary dávati dětem svým, čím více Otec váš nebeský dá Ducha svatého těm, kteříž ho prosí?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 14, 'I vymítal ďábelství, a to bylo němé. Stalo se pak, když vyšlo ďábelství, mluvil ten němý. I divili se zástupové.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 15, 'Ale někteří z nich pravili: Skrze Belzebuba, kníže ďábelské, vymítá ďábly.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 16, 'A jiní pokoušejíce, znamení od něho hledali s nebe.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 17, 'Ale on znaje myšlení jejich, řekl jim: Každé království samo v sobě rozdělené pustne, i dům rozdvojený padá.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 18, 'Jestližeť jest pak i satan proti sobě rozdělen, kterakž stane království jeho? Nebo pravíte, že já skrze Belzebuba vymítám ďábly.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 19, 'Jestliže já skrze Belzebuba vymítám ďábly, synové vaši skrze koho vymítají? Protož oni soudcové vaši budou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 20, 'Pakliť prstem Božím vymítám ďábly, jistěť přišlo k vám království Boží.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 21, 'Když silný oděnec ostříhá síně své, v pokoji jsou všecky věci, kteréž má.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 22, 'Pakli by silnější než on přijda, přemohl jej, všecka odění jeho odejme, v něž úfal, a loupeže jeho rozdělí.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 23, 'Kdož není se mnou, proti mně jest; a kdož neshromažďuje se mnou, rozptylujeť.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 24, 'Když nečistý duch vyjde od člověka, chodí po místech suchých, hledaje odpočinutí. A nenalezna, dí: Vrátím se do domu svého, odkudž jsem vyšel.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 25, 'A přijda, nalezne vymetený a ozdobený.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 26, 'Tehdy jde, a přijme k sobě jiných sedm duchů horších, než jest sám, a vejdouce, přebývají tam. I jsou poslední věci člověka toho horší nežli první.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 27, 'I stalo se, když on to mluvil, že pozdvihši hlasu jedna žena z zástupu, řekla jemu: Blahoslavený život, kterýž tebe nosil, a prsy, kterýchž jsi požíval.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 28, 'On pak řekl: Anobrž blahoslavení, kteříž slyší slovo Boží, a ostříhají jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 29, 'A když se zástupové scházeli k němu, počal praviti: Pokolení toto nešlechetné jest. Znamení vyhledává, ale znamení jemu nebude dáno, než znamení to Jonáše proroka.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 30, 'Nebo jakož Jonáš učiněn byl znamením Ninivitským, takť bude i Syn člověka pokolení tomuto.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 31, 'Královna od poledne stane na soudu s muži pokolení tohoto, a odsoudí je. Nebo přijela od končin země, aby slyšela moudrost Šalomounovu, a aj, více než Šalomoun tuto.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 32, 'Muži Ninivitští povstanou na soudu s pokolením tímto, a odsoudí je. Nebo činili pokání k kázaní Jonášovu, a aj, více nežli Jonáš tuto.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 33, 'Žádný rozsvítě svíci, nepostaví jí do skrýše, ani pod kbelec, ale na svícen, aby ti, kteříž vcházejí, světlo viděli.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 34, 'Svíce těla jest oko. Když by tedy oko tvé sprostné bylo, i tělo tvé všecko bude světlé; a pakliť bude nešlechetné, i tělo tvé tmavé bude.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 35, 'Viziž tedy, aby světlo, kteréž jest v tobě, nebylo tmou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 36, 'Pakli celé tělo tvé světlé bude, nemaje žádné částky tmavé, budeť všecko tak světlé, že tě jako svíce bleskem osvítí.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 37, 'A když on mluvil, prosil ho jeden farizeus, aby obědval u něho. A všed, posadil se za stůl.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 38, 'Farizeus pak viděv to, podivil se, že se neumyl před obědem.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 39, 'I řekl Pán jemu: Nyní vy farizeové povrchu konvice a misy čistíte, ale to, což vnitř jest u vás, plno jest loupeže a nešlechetnosti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 40, 'Blázni, zdaliž ten, kterýž učinil, což zevnitř jest, neučinil také i toho, což jest vnitř?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 41, 'Ale však i z toho, což máte, dávejte almužnu, a aj, všecky věci vaše čisté budou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 42, 'Ale běda vám farizeům, že desátky dáváte z máty a z routy a ze všeliké byliny, ale opouštíte soud a lásku Boží. Tyto věci měli jste činiti, a oněch neopouštěti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 43, 'Běda vám farizeům, nebo milujete první místa v školách a pozdravování na trzích.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 44, 'Běda vám, zákonníci a farizeové pokrytci, nebo jste jako hrobové nepatrní, a lidé chodíce po nich, nevědí.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 45, 'I odpověděv jeden z zákonníků, řekl jemu: Mistře, tyto věci mluvě, i nám také lehkost činíš.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 46, 'A on řekl: I vám zákonníkům běda, nebo obtěžujete lidi břemeny nesnesitelnými, a sami se těch břemen jedním prstem nedotýkáte.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 47, 'Běda vám, proto že vzděláváte hroby prorocké, kteréž otcové vaši zmordovali.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 48, 'A tak osvědčujete a potvrzujete skutků otců svých. Nebo oni zajisté zmordovali je, vy pak vzděláváte hroby jejich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 49, 'Protož i Moudrost Boží řekla: Pošliť k nim proroky a apoštoly, a z těch některé mordovati budou, a jiné vyháněti,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 50, 'Aby požádáno bylo od tohoto pokolení krve všech proroků, kteráž vylita jest od ustanovení světa,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 51, 'Od krve Abelovy až do krve Zachariášovy, kterýž zahynul mezi oltářem a chrámem. Jistě, pravím vám, požádáno jí bude od pokolení tohoto.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 52, 'Běda vám zákonníkům, nebo jste vzali klíč umění; sami jste nevešli, a těm, kteříž vcházeli, zbránili jste.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 53, 'A když jim to mluvil, počali zákonníci a farizeové přísně na něj dotírati, a k mnohým řečem příčiny jemu dávati.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 54, 'Úklady činíce jemu, a hledajíce popadnouti něco z úst jeho, aby jej obžalovali.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 1, 'A v tom, když se na tisíce lidu sešlo, tak že jedni druhé velmi tlačili, počal mluviti k učedlníkům svým: Nejpředněji se varujte od kvasu farizeů, kterýž jest pokrytství.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 2, 'Neboť nic není skrytého, což by nemělo býti zjeveno; aniž jest co tajného, ješto by nemělo býti zvědíno.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 3, 'Protož to, co jste pravili ve tmách, bude na světle slyšáno, a co jste v uši šeptali v pokojích, hlásánoť bude na střechách.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 4, 'Pravím pak vám přátelům svým: Nestrachujte se těch, kteříž tělo zabíjejí, a potom nemají, co by více učinili.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 5, 'Ale ukážiť vám, koho se máte báti: Bojte se toho, kterýž, když zabije, má moc uvrci do pekelného ohně. Jistě pravím vám, toho se bojte.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 6, 'Zdaliž nebývá pět vrabečků prodáváno za dva penížky? A jeden z nich není v zapomenutí před Bohem.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 7, 'Nýbrž i vlasové hlavy vaší všickni v počtu jsou. Protož nebojtež se, mnohoť vy vrabečků převyšujete.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 8, 'Pravímť pak vám: Každý kdož by koli vyznal mne před lidmi, i Syn člověka vyzná jej před anděly Božími.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 9, 'Kdož by mne pak zapřel před lidmi, zapřínť bude před anděly Božími.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 10, 'A každý kdož dí slovo proti Synu člověka, bude mu odpuštěno, ale tomu, kdož by se Duchu svatému rouhal, nebudeť odpuštěno.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 11, 'Když pak vás voditi budou do škol a k vládařům a k mocným, nepečujte, kterak aneb co byste odpovídali, aneb co byste mluvili.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 12, 'Duch svatý zajisté naučí vás v tu hodinu, co byste měli mluviti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 13, 'I řekl jemu jeden z zástupu: Mistře, rci bratru mému, ať rozdělí se mnou dědictví.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 14, 'A on řekl jemu: Člověče, kdo mne ustavil soudcím aneb děličem nad vámi?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 15, 'I řekl jim: Viztež a vystříhejte se od lakomství; neboť ne v rozhojnění statku něčího život jeho záleží.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 16, 'Pověděl pak jim podobenství, řka: Člověka jednoho bohatého hojné úrody pole přineslo.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 17, 'I přemyšloval sám v sobě, řka: Co učiním? Nebo nemám, kde bych shromáždil úrody své.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 18, 'I řekl: Toto učiním: Zbořím stodoly své, a větších nastavím, a tu shromáždím všecky své úrody i zboží svá.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 19, 'A dím duši své: Duše, máš mnoho statku složeného za mnohá léta, odpočívej, jez, pí, měj dobrou vůli.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 20, 'I řekl jemu Bůh: Ó blázne, této noci požádají duše tvé od tebe, a to, cožs připravil, čí bude?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 21, 'Takť jest, kdož sobě poklady shromažďuje, a není v Bohu bohatý.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 22, 'Řekl pak učedlníkům svým: Protož pravím vám: Nebuďte pečliví o život svůj, co byste jedli, ani o tělo, čím byste se odívali.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 23, 'Život více jest nežli pokrm, i tělo nežli oděv.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 24, 'Patřte na havrany, žeť nesejí, ani nežnou, a nemají špižírny {pivnice}, ani stodoly a však Bůh živí je. I čím v větší vážnosti jste vy než ptactvo?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 25, 'A kdož pak z vás pečlivě mysle, můž přidati ku postavě své loket jeden?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 26, 'Poněvadž tedy nemůžete s to býti, což nejmenšího jest, proč se o jiné věci staráte?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 27, 'Patřte na kvítí, kterak rostou, nedělají, ani předou, pravímť pak vám, že ani Šalomoun ve vší slávě své nebyl tak odín, jako jedno z těchto.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 28, 'A poněvadž trávu, kteráž dnes na poli jest, a zítra do peci uvržena bývá, Bůh tak odívá, čím více vás, ó malé víry?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 29, 'I vy nehledejtež toho, co byste jedli, aneb co byste pili, aniž o to roztržité mysli buďte.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 30, 'Nebo těch všech věcí národové světa tohoto hledají, Otec pak váš ví, že těch věcí potřebujete.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 31, 'Ale raději hledejte království Božího, a tyto všecky věci budou vám přidány.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 32, 'Neboj se, ó maličké stádce, neboť se zalíbilo Otci vašemu dáti vám království.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 33, 'Prodávejte statky své, a dávejte almužnu. Dělejte sobě pytlíky, kteříž nevetšejí, poklad, kterýž nehyne v nebesích, kdež zloděj dojíti nemůž, aniž mol kazí.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 34, 'Nebo kdež jest poklad váš, tuť bude i srdce vaše.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 35, 'Buďtež bedra vaše přepásaná, a svíce hořící.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 36, 'A vy podobni lidem očekávajícím Pána svého, až by se vrátil z svadby, aby hned, jakž by přišel a potloukl, otevřeli jemu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 37, 'Blaze služebníkům těm, kteréž přijda Pán, nalezl by, a oni bdí. Amen pravím vám, že přepáše se, a vsadí je za stůl, a chodě, bude jim sloužiti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 38, 'A přišel-liť by v druhé bdění, a pakliť by v třetím bdění přišel, a tak je nalezl, blahoslavení jsou ti služebníci,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 39, 'Toto pak vězte, že byť věděl hospodář, v kterou by hodinu měl zloděj přijíti, bděl by zajisté, a nedal by podkopati domu svého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 40, 'Protož i vy buďte hotovi, nebo v kterou hodinu nenadějete se, Syn člověka přijde.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 41, 'I řekl jemu Petr: Pane, nám-li pravíš toto podobenství, čili všechněm?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 42, 'I dí Pán: Kdo jest věrný šafář a opatrný, jehož by ustanovil pán nad čeledí svou, aby jim v čas dával vyměřený pokrm?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 43, 'Blahoslavený služebník ten, kteréhož, když by přišel pán jeho, nalezne, an tak činí.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 44, 'V pravdě pravím vám, že nade vším statkem svým ustanoví jej.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 45, 'Pakli by řekl služebník ten v srdci svém: Prodlévá přijíti pán můj, i počal by bíti služebníky a děvky, a jísti a píti i opíjeti se:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 46, 'Přijdeť pán služebníka toho v den, v kterýž se nenaděje, a v hodinu, kteréž neví. I oddělíť jej, a díl jeho položí s nevěrnými.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 47, 'Služebník pak ten, kterýž by znal vůli pána svého, a nebyl hotov, a nečinil podlé vůle jeho, bit bude velmi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 48, 'Ale kterýž neznal, a činil hodné věci trestání, bit bude méně. Každému pak, komuž jest mnoho dáno, mnoho bude od něho požádáno; a komuť mnoho poručili, víceť požádají od něho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 49, 'Oheň přišel jsem pustiti na zemi, a co chci, jestliže již hoří?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 50, 'Ale křtem mám křtěn býti, a kterak jsem ssoužen, dokudž se nevykoná!');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 51, 'Což se domníváte, že bych přišel pokoj uvésti na zemi? Nikoli, pravím vám, ale rozdělení.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 52, 'Nebo již od této chvíle bude jich pět v jednom domě rozděleno, tři proti dvěma, a dva proti třem.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 53, 'Bude rozdělen otec proti synu, a syn proti otci, mátě proti dceři, a dcera proti mateři, svegruše proti nevěstě své, a nevěsta proti svegruši své.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 54, 'Pravil také i zástupům: Když vídáte oblak, an vzchází od západu, hned pravíte: Příval jde, a tak bývá.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 55, 'A když od poledne vítr věje, říkáte: Bude horko, a býváť.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 56, 'Pokrytci, způsob země i nebe umíte souditi, a kterakž pak tohoto času nesoudíte?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 57, 'Ano proč i sami od sebe nesoudíte, což spravedlivého?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 58, 'Když pak jdeš s protivníkem svým k vrchnosti, na cestě přičiň se o to, abys byl zproštěn od něho, aby snad netáhl tebe k soudci, a soudce dal by tebe biřici, a biřic vsadil by tě do žaláře.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 59, 'Pravím tobě: Nevyjdeš odtud, dokudž bys i toho posledního haléře nenavrátil.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 1, 'Byli pak tu přítomní času toho někteří, vypravujíce jemu o Galilejských, kterýchž krev Pilát smísil s obětmi jejich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 2, 'I odpověděv Ježíš, řekl jim: Co mníte, že ti Galilejští byli větší hříšníci nežli všickni Galilejští, že takové věci trpěli?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 3, 'Nikoli, pravím vám. Nýbrž nebudete-li pokání činiti, všickni též zahynete.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 4, 'Aneb oněch osmnácte, na kteréž upadla věže v Siloe, a zbila je, zdali se domníváte, že by oni vinni byli nad všecky lidi, přebývající v Jeruzalémě?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 5, 'Nikoli, pravím vám. Nýbrž nebudete-li pokání činiti, všickni též zahynete.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 6, 'Pověděl pak toto podobenství: Člověk jeden měl strom fíkový štípený na vinici své. I přišel, hledaje ovoce na něm, ale nenalezl.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 7, 'I řekl vinaři: Aj, po tři léta přicházím, hledaje ovoce na tom fíku, ale nenalézám. Vytniž jej. Proč i tu zemi darmo kazí?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 8, 'On pak odpověděv, řekl jemu: Pane, ponechejž ho i tohoto léta, ažť jej okopám a ohnojím,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 9, 'Zdali by nesl ovoce. Pakliť neponese, potom vytneš jej.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 10, 'Učil pak v jedné škole v sobotu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 11, 'A aj, byla tu žena, kteráž měla ducha nemoci osmnáct let, a byla sklíčena, a nijakž se nemohla zpřímiti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 12, 'A uzřev ji Ježíš, zavolal jí k sobě, a řekl jí: Ženo, zproštěna jsi od nemoci své.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 13, 'I vložil na ni ruce, a i hned zdvihla se, a velebila Boha.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 14, 'Tedy kníže školní odpověděv, hněvaje se proto, že v den sobotní uzdravoval Ježíš, řekl zástupu: Šest dní jest, v nichž náleží dělati; protož v těch přicházejíce, buďte uzdravováni, a ne v den sobotní.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 15, 'I odpověděv jemu Pán, řekl: Pokrytče, zdali jeden každý z vás v sobotu neodvazuje vola svého neb osla od jeslí, a nevodí napájeti?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 16, 'Tato pak dcera Abrahamova, kterouž byl svázal satan, aj, již osmnácte let, což neměla býti rozvázána z svazku tohoto v den sobotní?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 17, 'A když on to pověděl, zastyděli se všickni protivníci jeho, ale všecken lid radoval se ze všech těch slavných skutků, kteříž se dáli od něho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 18, 'I řekl: Čemu podobno jest království Boží, a k čemu je přirovnám?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 19, 'Podobno jest zrnu horčičnému, kteréž vzav člověk, uvrhl do zahrady své. I rostlo, a učiněno jest v strom veliký, a ptactvo nebeské hnízda sobě dělali na ratolestech jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 20, 'A opět řekl: K čemu připodobním království Boží?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 21, 'Podobno jest kvasu, kterýž vzavši žena, zadělala ve třech měřicích mouky, až zkysalo všecko.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 22, 'I chodil po městech a městečkách, uče, bera se do Jeruzaléma.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 23, 'I řekl jemu jeden: Pane, co nemnozí jsou ti, kteří spaseni býti mají? On pak řekl jim:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 24, 'Snažujte se vcházeti těsnou branou; neboť (pravím vám,) mnozí usilovati budou vjíti, ale nebudou moci.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 25, 'Když vstane hospodář, a zavře dvéře, a počnete vně státi a tlouci na dvéře, řkouce: Pane, Pane, otevři nám, a on odpovídaje, díť vám: Neznám vás, odkud jste:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 26, 'Tedy počnete říci: Jídali jsme a píjeli před tebou, a na ulicech našich jsi učíval.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 27, 'I dí: Pravím vám, neznám vás, odkud jste. Odejdětež ode mne všickni činitelé nepravosti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 28, 'Tamť bude pláč a škřipení zubů, když uzříte Abrahama, a Izáka, a Jákoba, a všecky proroky v království Božím, sami pak sebe vyhnané ven.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 29, 'I přijdouť od východu, a od západu, a od půlnoci, i od poledne, a budou stoliti v království Božím.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 30, 'A aj, jsouť poslední, kteříž budou první, a jsou první, kteříž budou poslední.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 31, 'A v ten den přistoupili někteří z farizeů, řkouce jemu: Vyjdi, a odejdi odsud, nebo Heródes chce tě zamordovati.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 32, 'I řekl jim: Jdouce, povězte lišce té: Aj, vymítám ďábly, a uzdravuji dnes a zítra, a třetího dne dokonám.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 33, 'Ale však musím dnes a zítra i po zejtří choditi; neboť nelze proroku zahynouti kromě Jeruzaléma.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 34, 'Jeruzaléme, Jeruzaléme, ješto morduješ proroky, a kamenuješ ty, kteříž k tobě bývají posláni, kolikrát jsem chtěl shromážditi dítky tvé, jako slepice kuřátka svá pod křídla? Ale nechtěli jste.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 35, 'Aj, zanechán bude vám dům váš pustý. Ale jistě pravím vám, že nikoli mne neuzříte, ažť přijde, když díte: Požehnaný, kterýž se béře ve jménu Páně.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 1, 'I stalo se, když všel Ježíš do domu nějakého knížete farizejského v sobotu, aby jedl chléb, že oni šetřili ho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 2, 'A aj, člověk nějaký vodnotelný byl před ním.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 3, 'I odpověděv Ježíš, dí zákonníkům a farizeům, řka: Sluší-li v sobotu uzdravovati?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 4, 'Oni pak mlčeli. Tedy on dosáh jeho, uzdravil a propustil.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 5, 'A odpověděv jim, řekl: Čí z vás osel aneb vůl upadl by do studnice, a ne i hned by ho vytáhl v den sobotní?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 6, 'I nemohli jemu na to odpovědíti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 7, 'Pověděl také i pozvaným podobenství, (spatřiv to, kterak přední místa vyvolovali,) řka jim:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 8, 'Kdybys byl od někoho pozván na svadbu, nesedej na předním místě, aťby snad vzácnější než ty nebyl pozván od něho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 9, 'A přijda ten, kterýž tebe i onoho pozval, řekl by tobě: Dej tomuto místo. A tehdy počal bys s hanbou na posledním místě seděti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 10, 'Ale když bys byl pozván, jda, posaď se na posledním místě. A kdyby přišel ten, kterýž tebe pozval, řekl by tobě: Příteli, posedni výše, tedy budeš míti chválu před spolustolícími.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 11, 'Nebo každý, kdož se povyšuje, bude ponížen; a kdož se ponižuje, bude povýšen.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 12, 'Pravil také i tomu, kterýž ho byl pozval: Když činíš oběd neb večeři, nezov přátel svých, ani bratří svých, ani příbuzných svých, ani sousedů bohatých, aťby snad i oni zase nezvali tebe, a měl bys odplatu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 13, 'Ale když činíš hody, povolej chudých, chromých, kulhavých, slepých,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 14, 'A blahoslavený budeš. Neboť nemají, odkud by odplatili tobě, ale budeť odplaceno při vzkříšení spravedlivých.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 15, 'I uslyšav to jeden z spolupřísedících, řekl jemu: Blahoslavený, kdož jí chléb v království Božím.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 16, 'On pak řekl jemu: Člověk nějaký učinil večeři velikou, a pozval mnohých.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 17, 'I poslal služebníka svého v hodinu večeře, aby řekl pozvaným: Poďte, nebo již připraveno jest všecko.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 18, 'I počali se všickni jednomyslně vymlouvati. První řekl jemu: Ves jsem koupil, i musím vyjíti a shlédnouti ji; prosím tebe, vymluv mne.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 19, 'A druhý řekl: Patero spřežení volů koupil jsem, a jdu, abych jich zkusil; prosím tebe, vymluv mne.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 20, 'A jiný dí: Ženu jsem pojal, a protož nemohu přijíti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 21, 'I navrátiv se ten služebník, zvěstoval ty věci pánu svému. Tedy rozhněvav se hospodář, řekl služebníku svému: Vyjdi rychle na rynky a na ulice města, a chudé, i chromé, i kulhavé, a slepé uveď sem.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 22, 'I řekl služebník: Pane, stalo se, jakž jsi rozkázal, a ještěť místo jest.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 23, 'Tedy řekl pán služebníku: Vyjdiž na cesty a mezi ploty, a přinuť vjíti, ať se naplní dům můj.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 24, 'Nebo pravímť vám, že žádný z mužů těch, kteříž pozváni byli, neokusí večeře mé.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 25, 'Šli pak mnozí zástupové s ním. A obrátiv se, řekl jim:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 26, 'Jde-li kdo ke mně, a nemá-li v nenávisti otce svého, i mateře, i ženy, i dětí, i bratří, i sestr, ano i té duše své, nemůž býti mým učedlníkem.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 27, 'A kdožkoli nenese kříže svého, a jde za mnou, nemůž býti mým učedlníkem.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 28, 'Nebo kdo z vás jest, chtěje stavěti věži, aby prvé sedna, nepočetl nákladu, má-li to, nač by ji dokonal?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 29, 'Aby snad, když by základ položil, a dokonati nemohl, všickni, kteříž by to viděli, nepočali se posmívati jemu,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 30, 'Řkouce: Tento člověk počal stavěti, a nemohl dokonati.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 31, 'Aneb který král, bera se k boji proti jinému králi, zdaliž prvé nesedne, aby se poradil, mohl-li by s desíti tisíci potkati se s tím, kterýž s dvadcíti tisíci táhne proti němu?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 32, 'Sic jinak, když by onen ještě podál od něho byl, pošle posly k němu, žádaje za to, což jest ku pokoji.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 33, 'Tak zajisté každý z vás, kdož se neodřekne všech věcí, kterýmiž vládne, nemůž býti mým učedlníkem.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 34, 'Dobráť jest sůl. Pakli sůl bude zmařena, čím bude napravena?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 35, 'Ani do země, ani do hnoje se nehodí; ven ji vymítají. Kdo má uši k slyšení, slyš.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 1, 'Přibližovali se pak k němu všickni publikáni a hříšníci, aby ho slyšeli.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 2, 'I reptali farizeové a zákonníci, řkouce: Tento hříšníky přijímá, a jí s nimi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 3, 'I pověděl jim podobenství toto, řka:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 4, 'Kdyby někdo z vás měl sto ovec, a ztratil by jednu z nich, zdaliž by nenechal devadesáti devíti na poušti, a nešel k té, kteráž zahynula, až by i nalezl ji?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 5, 'A nalezna, vložil by na ramena svá s radostí.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 6, 'A přijda domů, svolal by přátely a sousedy, řka jim: Spolu radujte se se mnou, nebo jsem nalezl ovci svou, kteráž byla zahynula.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 7, 'Pravímť vám, že tak jest radost v nebi nad jedním hříšníkem pokání činícím větší, než nad devadesáti devíti spravedlivými, kteříž nepotřebují pokání.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 8, 'Aneb žena některá mající grošů deset, ztratila-li by jeden groš, zdaliž nezažže svíce, a nemete domu, a nehledá pilně, dokudž nenalezne?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 9, 'A když nalezne, svolá přítelkyně a sousedy, řkuci: Spolu radujte se se mnou, nebo jsem nalezla groš, kterýž jsem byla ztratila.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 10, 'Takť, pravím vám, že jest radost před anděly Božími nad jedním hříšníkem pokání činícím.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 11, 'Řekl také: Člověk jeden měl dva syny.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 12, 'Z nichž mladší řekl otci: Otče, dej mi díl statku, kterýž mně náleží. I rozdělil jim statek.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 13, 'A po nemnohých dnech, shromáždiv všecko mladší ten syn, odšel do daleké krajiny, a tam rozmrhal statek svůj, byv prostopašně živ.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 14, 'A když všecko utratil, stal se hlad veliký v krajině té, a on počal nouzi trpěti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 15, 'I všed, přídržel se jednoho měštěnína krajiny té; a on jej poslal na pole své, aby pásl vepře.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 16, 'I žádal nasytiti břicho své mlátem, kteréž svině jedly, ale žádný nedával jemu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 17, 'Přišed pak sám k sobě, řekl: Jak mnozí nájemníci u otce mého hojnost mají chleba, a já hladem mru!');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 18, 'Vstana, půjdu k otci svému, a dím jemu: Otče, zhřešil jsem proti nebi a před tebou,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 19, 'Aniž jsem hoden více slouti synem tvým. Učiň mne jako jednoho z nájemníků svých.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 20, 'I vstav, šel k otci svému. A když ještě opodál byl, uzřel jej otec jeho, a milosrdenstvím byv hnut, přiběh, padl na šíji jeho, a políbil ho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 21, 'I řekl jemu syn: Otče, zhřešil jsem proti nebi a před tebou, aniž jsem hoden více slouti synem tvým.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 22, 'I řekl otec služebníkům svým: Přineste to roucho první, a oblecte jej, a dejte prsten na ruku jeho a obuv na nohy.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 23, 'A přivedouce to tele tučné, zabíte, a hodujíce, buďme veseli.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 24, 'Nebo tento syn můj byl umřel, a zase ožil; byl zahynul, a nalezen jest. I počali veseli býti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 25, 'Byl pak syn jeho starší na poli. A jda, když se přibližoval k domu, uslyšel zpívání a hluk veselících se.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 26, 'I povolav jednoho z služebníků, otázal se, co by to bylo.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 27, 'A on řekl jemu: Bratr tvůj přišel, i zabil otec tvůj tučné tele, že ho zdravého přijal.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 28, 'I rozhněval se, a nechtěl vjíti. Otec pak jeho vyšed, prosil ho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 29, 'A on odpověděv, řekl otci: Aj, tolik let sloužím tobě, a nikdy jsem přikázaní tvého nepřestoupil, a však nikdy jsi mi nedal kozelce, abych s přátely svými vesel pobyl.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 30, 'Ale když syn tvůj tento, kterýž prožral statek tvůj s nevěstkami, přišel, zabils jemu to tele tučné.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 31, 'A on řekl jemu: Synu, ty vždycky se mnou jsi, a všecky věci mé jsou tvé.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 32, 'Ale veseliti a radovati se náleželo. Nebo bratr tvůj tento byl umřel, a zase ožil; zahynul byl, a nalezen jest.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 1, 'Pravil pak i učedlníkům svým: Člověk jeden byl bohatý, kterýž měl šafáře; a ten obžalován jest před ním, jako by mrhal statek jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 2, 'I povolav ho, řekl jemu: Což to slyším o tobě? Vydej počet z vládařství svého, nebo již nebudeš moci déle vládnouti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 3, 'I dí vládař sám v sobě: Co učiním? Teď pán můj odjímá ode mne vládařství. Kopati nemohu, žebrati se stydím.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 4, 'Vím, co učiním, aby, když budu zsazen z vládařství, přijali mne do svých domů.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 5, 'I zavolav jednoho každého dlužníka pána svého, řekl prvnímu: Jaks mnoho dlužen pánu mému?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 6, 'A on řekl: Sto tun oleje. I řekl mu: Vezmi rejistra svá, a sedna rychle, napiš padesát.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 7, 'Potom druhému řekl: Ty pak jaks mnoho dlužen? Kterýž řekl: Sto korců pšenice. I dí mu: Vezmi rejistra svá, a napiš osmdesát.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 8, 'I pochválil ten pán vládaře toho nepravého, že opatrně učinil. Nebo synové tohoto světa opatrnější jsou, než synové světla v svých věcech.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 9, 'I jáť pravím vám: Čiňte sobě přátely z mamony nepravosti, aby, když byste zhynuli, přijali vás do oněch věčných stanů.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 10, 'Kdo jest věrný v mále, i ve mnoze věrný jest. A kdož v mále jest nepravý, i ve mnozeť nepravý jest.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 11, 'Poněvadž tedy v mamoně nepravé věrni jste nebyli, spravedlivé kdo vám svěří?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 12, 'A když jste v cizím věrni nebyli, což vašeho jest, kdo vám dá?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 13, 'Žádný čeledín nemůž dvěma pánům sloužiti. Nebť zajisté jednoho nenáviděti bude, a druhého milovati, aneb jednoho přídržeti se bude, a druhým pohrdne. Nemůžte Bohu sloužiti a mamoně.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 14, 'Slyšeli pak toto všecko i farizeové, kteříž byli lakomí, a posmívali se jemu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 15, 'I dí jim: Vy jste, ješto se sami spravedliví činíte před lidmi, ale Bůhť zná srdce vaše; nebo což jest u lidí vysokého, ohavnost jest před Bohem.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 16, 'Zákon a proroci až do Jana, a od té chvíle království Boží zvěstuje se, a každý se do něho násilně tiskne.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 17, 'Snázeť jest zajisté nebi i zemi pominouti, nežli v zákoně jednomu tytlíku zahynouti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 18, 'Každý, kdož propustí manželku svou, a jinou pojímá, cizoloží; a kdož propuštěnou od muže pojímá, cizoloží.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 19, 'Byl pak člověk jeden bohatý, a obláčel se v šarlat a v kment, a hodoval na každý den stkvostně.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 20, 'A byl jeden žebrák, jménem Lazar, kterýž ležel u vrat jeho vředovitý,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 21, 'Žádaje nasycen býti těmi drobty, kteříž padali z stolu bohatce. Ale i psi přicházejíce, lízali vředy jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 22, 'I stalo se, že ten žebrák umřel, a nesen jest od andělů do lůna Abrahamova. Umřel pak i bohatec, a pohřben jest.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 23, 'Potom v pekle pozdvih očí svých, v mukách jsa, uzřel Abrahama zdaleka, a Lazara v lůnu jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 24, 'I zvolav bohatec, řekl: Otče Abrahame, smiluj se nade mnou, a pošli Lazara, ať omočí konec prstu svého v vodě, a svlaží jazyk můj; nebo se mučím v tomto plameni.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 25, 'I řekl Abraham: Synu, rozpomeň se, žes ty vzal dobré věci své v životě svém, a Lazar též zlé. Nyní pak tento se těší, ale ty se mučíš.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 26, 'A nad to nade všecko mezi námi a vámi propast veliká utvrzena jest, aby ti, kteříž chtí odsud k vám jíti, nemohli, ani od onud k nám přejíti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 27, 'I řekl: Ale prosím tebe, otče, abys ho poslal do domu otce mého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 28, 'Neboť mám pět bratrů. Ať jim svědčí, aby i oni nepřišli do tohoto místa muk.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 29, 'I řekl jemu Abraham: Majíť Mojžíše a proroky, nechť jich poslouchají.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 30, 'A on řekl: Nic, otče Abrahame, ale kdyby kdo z mrtvých šel s nim, budou pokání činiti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 31, 'I řekl mu: Poněvadž Mojžíše a proroků neposlouchají, aniž byť kdo z mrtvých vstal, uvěří jemu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 1, 'Tedy řekl učedlníkům: Není možné, aby nepřišla pohoršení, ale běda, skrze kohož přicházejí.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 2, 'Lépe by mu bylo, aby žernov osličí vložen byl na hrdlo jeho, a uvržen byl do moře, než by pohoršil jednoho z těchto maličkých.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 3, 'Šetřte se. Zhřešil-li by pak proti tobě bratr tvůj, potresci ho, a bude-liť toho želeti, odpusť mu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 4, 'A byť pak sedmkrát za den zhřešil proti tobě, a sedmkrát za den obrátil se k tobě, řka: Žel mi toho, odpusť mu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 5, 'I řekli apoštolé Pánu: Přispoř nám víry.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 6, 'I dí Pán: Kdybyste měli víru jako zrno horčičné, řekli byste této moruši: Vykořeň se, a přesaď se do moře, a uposlechla by vás.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 7, 'Kdo pak jest z vás, maje služebníka, ješto oře aneb pase, aby jemu, když by se s pole navrátil, hned řekl: Poď a sedni za stůl?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 8, 'Anobrž zdali nedí jemu: Připrav, ať povečeřím, a opáše se, služ mi, až se najím a napím, a potom i ty jez a pí?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 9, 'Zdali děkuje služebníku tomu, že učinil to, což mu bylo rozkázáno? Nezdá mi se.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 10, 'Tak i vy, když učiníte všecko, což vám přikázáno, rcete: Služebníci neužiteční jsme. Což jsme povinni byli učiniti, učinili jsme.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 11, 'I stalo se, když se bral do Jeruzaléma, že šel skrze Samaří a Galilei.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 12, 'A když vcházel do nějakého městečka, potkalo se s ním deset mužů malomocných, kteříž stáli zdaleka.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 13, 'A pozdvihše hlasu, řekli: Ježíši přikazateli, smiluj se nad námi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 14, 'Kteréžto on uzřev, řekl jim: Jdouce, ukažte se kněžím. I stalo se, když šli, že očištěni jsou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 15, 'Jeden pak z nich uzřev, že jest uzdraven, navrátil se, s velikým hlasem velebě Boha.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 16, 'A padl na tvář k nohám jeho, díky čině jemu. A ten byl Samaritán.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 17, 'I odpověděv Ježíš, řekl: Zdaliž jich deset není očištěno? A kdež jich devět?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 18, 'Nenalezli se, aby vrátíce se, chválu Bohu vzdali, jediné cizozemec tento?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 19, 'I řekl jemu: Vstana jdi, víra tvá tě uzdravila.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 20, 'Byv pak otázán od farizeů, kdy přijde království Boží, odpověděl jim, a řekl: Nepřijdeť království Boží s šetřením.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 21, 'Aniž řeknou: Aj, tuto, aneb aj, tamto. Nebo aj, království Boží jestiť mezi vámi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 22, 'I řekl učedlníkům: Přijdou dnové, že budete žádati viděti v jeden den Syna člověka, ale neuzříte.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 23, 'A dějíť vám: Aj, zde, aneb hle, tamto. Ale nechoďte, aniž následujte.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 24, 'Nebo jakož blesk osvěcující se z jedné krajiny, kteráž pod nebem jest, až do druhé, kteráž též pod nebem jest, svítí, tak bude i Syn člověka ve dni svém.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 25, 'Ale nejprvé musí mnoho trpěti, a zavržen býti od národu tohoto.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 26, 'A jakož se dálo za dnů Noé, tak bude i za dnů Syna člověka.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 27, 'Jedli, pili, ženili se, vdávaly se až do toho dne, v kterémž Noé všel do korábu; i přišla potopa, a zahladila všecky.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 28, 'A též podobně, jakž se dálo ve dnech Lotových: Jedli, pili, kupovali, prodávali, štěpovali, stavěli.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 29, 'Ale dne toho, když vyšel Lot z Sodomy, dštil ohněm a sirou s nebe, a zahladil všecky.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 30, 'Takť nápodobně bude v ten den, když se Syn člověka zjeví.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 31, 'V ten den kdo by byl na střeše, a nádobí jeho v domu, nesstupuj, aby je pobral; a kdo na poli, též nevracuj se zase.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 32, 'Pomněte na Lotovu ženu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 33, 'Kdož by koli hledal duši svou zachovati, ztratíť ji; a kdož by ji koli ztratil, obživíť ji.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 34, 'Pravímť vám: V tu noc budou dva na loži jednom; jeden bude vzat, a druhý opuštěn.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 35, 'Dvě budou mleti spolu; jedna bude vzata, a druhá opuštěna.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 36, 'Dva budou na poli; jeden bude vzat, a druhý opuštěn.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 37, 'I odpověděvše, řekli jemu: Kde, Pane? On pak řekl jim: Kdežť bude tělo, tamť se shromáždí i orlice.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 1, 'Pověděl jim také i podobenství, kterak by potřebí bylo vždycky se modliti a neoblevovati,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 2, 'Řka: Byl jeden soudce v městě jednom, kterýž se Boha nebál, a člověka nestyděl.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 3, 'Byla pak vdova v témž městě. I přišla k němu, řkuci: Pomsti mne nad protivníkem mým.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 4, 'On pak dlouho nechtěl. Ale potom řekl sám v sobě: Ač se Boha nebojím, ani člověka nestydím,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 5, 'Však že mi pokoje nedá tato vdova, pomstím jí, aby naposledy přijduci, neuhaněla mne.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 6, 'I dí Pán: Slyšte, co praví ten soudce nepravý.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 7, 'A což by pak Bůh nepomstil vyvolených svých, volajících k němu dnem i nocí, ačkoli i prodlévá jim?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 8, 'Pravímť vám, žeť jich brzo pomstí. Ale když přijde Syn člověka, zdaliž nalezne víru na zemi?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 9, 'I řekl také proti některým, kteříž v sebe doufali, že by spravedliví byli, jiných za nic nevážíce, podobenství toto:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 10, 'Dva muži vstupovali do chrámu, aby se modlili, jeden farizeus, a druhý publikán.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 11, 'Farizeus stoje, takto se sám v sobě modlil: Bože, děkuji tobě, že nejsem jako jiní lidé, dráči, nespravedliví, cizoložníci, aneb jako i tento publikán.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 12, 'Postím se dvakrát do téhodne, desátky dávám ze všech věcí, kterýmiž vládnu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 13, 'Publikán pak zdaleka stoje, nechtěl ani očí k nebi pozdvihnouti. Ale bil se v prsy své, řka: Bože, buď milostiv mně hříšnému.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 14, 'Pravímť vám: Odšel tento, ospravedlněn jsa, do domu svého, a ne onen. Nebo každý, kdož se povyšuje, bude ponížen; a kdož se ponižuje, bude povýšen.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 15, 'Přinášeli také k němu i nemluvňátka, aby se jich dotýkal. To viděvše učedlníci, přimlouvali jim.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 16, 'Ale Ježíš svolav je, řekl: Nechte dítek, ať jdou ke mně, a nebraňte jim, nebo takovýchť jest království Boží.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 17, 'Amen pravím vám: Kdož by koli nepřijal království Božího jako dítě, nevejdeť nikoli do něho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 18, 'I otázalo se ho jedno kníže, řka: Mistře dobrý, co čině, život věčný obdržím?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 19, 'I řekl jemu Ježíš: Co mne nazýváš dobrým? Žádný není dobrý, než jediný, totiž Bůh.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 20, 'Umíš přikázaní: Nezcizoložíš, nezabiješ, nepokradeš, nepromluvíš křivého svědectví, cti otce svého i matku svou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 21, 'On pak řekl: Toho všeho ostříhal jsem od své mladosti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 22, 'Ale slyšav to Ježíš, řekl mu: Ještěť se jednoho nedostává. Všecko, což máš, prodej, a rozdej chudým, a budeš míti poklad v nebi, a poď, následuj mne.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 23, 'On pak uslyšav to, zarmoutil se; byl zajisté bohatý velmi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 24, 'A viděv jej Ježíš zarmouceného, řekl: Aj, jak nesnadně ti, kdož statky mají, do království Božího vejdou!');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 25, 'Snáze jest zajisté velbloudu skrze jehelnou dírku projíti, nežli bohatému vjíti do království Božího.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 26, 'Tedy řekli ti, kteříž to slyšeli: I kdož může spasen býti?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 27, 'A on dí: Což jest nemožného u lidí, možné jest u Boha.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 28, 'I řekl Petr: Aj, my opustili jsme všecko, a šli jsme za tebou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 29, 'On pak řekl jim: Amen pravím vám, že není žádného, kterýž by opustil dům, neb rodiče, neb bratří, neb manželku, neb dítky, pro království Boží,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 30, 'Aby nevzal v tomto času mnohem více, v budoucím pak věku života věčného.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 31, 'Tedy pojav dvanácte, řekl jim: Aj, vstupujeme do Jeruzaléma, a naplníť se všecko Synu člověka to, což psáno jest skrze proroky.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 32, 'Nebo vydán bude pohanům, a bude posmíván, a zlehčen, i uplván.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 33, 'A ubičujíce, zamordují jej, ale třetího dne z mrtvých vstane.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 34, 'Oni pak tomu nic nerozuměli, a bylo slovo to skryto před nimi, aniž věděli, co se pravilo.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 35, 'I stalo se, když se přibližovali k Jericho, slepý jeden seděl podlé cesty, žebře.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 36, 'A slyšev zástup pomíjející, otázal se, co by to bylo.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 37, 'I oznámili jemu, že Ježíš Nazaretský tudy jde.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 38, 'I zvolal, řka: Ježíši, synu Davidův, smiluj se nade mnou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 39, 'A ti, kteříž napřed šli, přimlouvali mu, aby mlčal. Ale on mnohem více volal: Synu Davidův, smiluj se nade mnou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 40, 'Tedy zastaviv se Ježíš, rozkázal ho k sobě přivésti. A když se přibližoval, otázal se ho,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 41, 'Řka: Co chceš, ať učiním? On pak dí: Pane, ať vidím.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 42, 'A Ježíš řekl jemu: Prohlédni. Víra tvá tě uzdravila.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 43, 'A i hned prohlédl, a šel za ním, velebě Boha. A všecken lid viděv to, vzdal chválu Bohu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 1, 'A všed, bral se přes Jericho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 2, 'A aj, muž, jménem Zacheus, a ten byl hejtman nad celnými, a byl bohatý.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 3, 'I žádostiv byl viděti Ježíše, kdo by byl; a nemohl pro zástup, nebo postavy malé byl.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 4, 'A předběh napřed, vstoupil na strom planého fíku, aby jej viděl; nebo tudy měl jíti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 5, 'A když přišel k tomu místu, pohleděv zhůru Ježíš, uzřel jej, i řekl jemu: Zachee, spěšně sstup dolů, nebo dnes v domu tvém musím zůstati.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 6, 'I sstoupil rychle, a přijal jej radostně.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 7, 'A viděvše to všickni, reptali, řkouce: K člověku hříšnému se obrátil.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 8, 'Stoje pak Zacheus, řekl Pánu: Aj, polovici statku svého, Pane, dávám chudým, a oklamal-li jsem v čem koho, navracuji to čtvernásob.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 9, 'I dí jemu Ježíš: Dnes spasení stalo se domu tomuto, proto že i on jest syn Abrahamův.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 10, 'Nebo přišel Syn člověka, aby hledal a spasil, což bylo zahynulo.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 11, 'Toho když oni poslouchali, promluvil k nim dále podobenství, proto že byl blízko od Jeruzaléma, a že se oni domnívali, že by se hned mělo zjeviti království Boží.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 12, 'I řekl: Člověk jeden rodu znamenitého odšel do daleké krajiny, aby přijal království, a zase se navrátil.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 13, 'I povolav desíti služebníků svých, dal jim deset hřiven, a řekl jim: Kupčtež, dokudž nepřijdu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 14, 'Měšťané pak jeho nenáviděli ho, a poslali poselství za ním, řkouce: Nechcemeť, aby tento kraloval nad námi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 15, 'I stalo se, když se navrátil, přijav království, že rozkázal zavolati těch svých služebníků, kterýmž byl dal peníze, aby zvěděl, jak kdo mnoho získal.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 16, 'I přišel první, řka: Pane, hřivna tvá deset hřiven získala.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 17, 'I řekl jemu: To dobře, služebníče dobrý. Že jsi nad málem byl věrný, mějž moc nad desíti městy.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 18, 'A druhý přišel, řka: Pane, hřivna tvá získala pět hřiven.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 19, 'I tomu řekl: I ty budiž nad pěti městy.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 20, 'A jiný přišel, řka: Pane, aj, teď hřivna tvá, kterouž jsem měl složenou v šátku.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 21, 'Nebo jsem se bál tebe, ješto jsi člověk přísný; béřeš, čeho jsi nepoložil, a žneš, čeho jsi nerozsíval.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 22, 'I řekl jemu: Z úst tvých soudím tebe, služebníče zlý. Věděl jsi, že jsem já člověk přísný, bera, což jsem nepoložil, a žna, čehož jsem nerozsíval.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 23, 'I proč jsi tedy nedal peněz mých na stůl, a já přijda, byl bych je vzal i s užitky.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 24, 'I řekl těm, kteříž tu stáli: Vezměte od něho tu hřivnu, a dejte tomu, kterýž má deset hřiven.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 25, 'I řekli jemu: Pane, máť deset hřiven.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 26, 'Jistě pravím vám: Že každému, kdož má, bude dáno, ale od toho, kterýž nemá, i to, což má, bude odjato.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 27, 'Ty pak nepřátely mé, kteříž nechtěli, abych nad nimi kraloval, přiveďte sem, a zmordujte přede mnou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 28, 'To pověděv, šel napřed, vstupuje k Jeruzalému.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 29, 'I stalo se, když se přiblížil k Betfagi a k Betany, k hoře, kteráž slove Olivetská, poslal dva učedlníky své,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 30, 'Řka: Jděte do městečka, kteréž proti vám jest. Do kteréhož vejdouce, naleznete oslátko přivázané, na němž nikdy žádný z lidí neseděl. Odvěžtež je, a přiveďte ke mně.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 31, 'A optal-liť by se vás kdo, proč odvazujete, tak díte jemu: Proto že Pán ho potřebuje.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 32, 'Tedy odšedše ti, kteříž byli posláni, nalezli, jakž jim byl pověděl.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 33, 'A když odvazovali to oslátko, řekli páni jeho k nim: Proč odvazujete oslátko?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 34, 'A oni řekli: Pán ho potřebuje.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 35, 'I přivedli je k Ježíšovi, a vloživše roucha svá na to oslátko, vsadili na ně Ježíše.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 36, 'A když on jel, stlali roucha svá na cestě.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 37, 'Když se pak již přibližoval k místu tomu, kudyž scházejí s hory Olivetské, počalo všecko množství učedlníků radostně chváliti Boha hlasem velikým ze všech divů, kteréž byli viděli,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 38, 'Řkouce: Požehnaný král, kterýž se béře ve jménu Páně. Pokoj na nebi, a sláva na výsostech.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 39, 'Ale někteří z farizeů, kteříž tu byli v zástupu, řekli jemu: Mistře, potresci učedlníků svých.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 40, 'I odpověděv, řekl jim: Pravímť vám: Budou-li tito mlčeti, kamení hned bude volati.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 41, 'A když se přiblížil, uzřev město, plakal nad ním,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 42, 'Řka: Ó kdybys poznalo i ty, a to aspoň v takový tento den tvůj, které by věci ku pokoji tobě byly, ale skrytoť jest to nyní před očima tvýma.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 43, 'Nebo přijdou na tě dnové, obklíčí tě nepřátelé tvoji valem, a oblehnou tebe, a ssouží tě se všech stran.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 44, 'A s zemí srovnají tě, i syny tvé v tobě, a nenechajíť v tobě kamene na kameni, proto že jsi nepoznalo času navštívení svého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 45, 'A všed do chrámu, počal vymítati prodavače a kupce z něho,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 46, 'Řka jim: Psáno jest: Dům můj dům modlitby jest, vy jste jej pak učinili peleší lotrovskou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 47, 'I učil na každý den v chrámě. Přední pak kněží {biskupové} a zákonníci i přední v lidu hledali ho zahladiti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 48, 'Ale nenalezli, co by učinili. Nebo všecken lid jej sobě liboval, poslouchaje ho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 1, 'I stalo se těch dnů v jeden den, když on učil lid v chrámě, a kázal evangelium, že přišli k tomu přední kněží {biskupové} a zákonníci s staršími.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 2, 'I řekli jemu: pověz nám, jakou mocí tyto věci činíš, aneb kdo jest ten, kterýž tobě tuto moc dal?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 3, 'I odpověděv, řekl jim: Otížiť se i já vás na jednu věc; protož pověztež mi:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 4, 'Křest Janův s nebe-li byl, čili z lidí?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 5, 'Oni pak uvažovali to mezi sebou, řkouce: Jestliže bychom řekli: S nebe, díť: Pročež jste tedy neuvěřili jemu?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 6, 'Pakli díme: Z lidí, lid všecken ukamenuje nás; nebo cele tak drží, že Jan jest prorok.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 7, 'I odpověděli: Že nevědí, odkud byl.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 8, 'I řekl jim Ježíš: Aniž já vám povím, jakou mocí toto činím.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 9, 'I počal lidu praviti podobenství toto: Člověk jeden štípil vinici, a pronajal ji vinařům, a sám odšel přes pole na dlouhé časy.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 10, 'A v čas slušný poslal k těm vinařům služebníka, aby užitek z vinice dali jemu. Ti pak vinaři zmrskavše jej, pustili prázdného.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 11, 'I poslal druhého služebníka. Oni pak i toho zmrskavše a zohavivše, pustili prázdného.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 12, 'I poslal třetího. Ale oni i toho zranivše, vystrčili ven.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 13, 'Tedy řekl pán té vinice: Co učiním? Pošli svého milého syna. Snad když toho uzří, ustýdnou se.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 14, 'Ale vinaři uzřevše jej, rozmlouvali mezi sebou, řkouce: Tentoť jest dědic; poďte, zabíme jej, aby naše bylo to dědictví.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 15, 'A vystrčivše jej ven z vinice, zamordovali. Což tedy učiní jim pán té vinice?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 16, 'Přijde a vyhladí vinaře ty, a dá vinici jiným. To uslyšavše, řekli: Odstup to.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 17, 'Ale on pohleděv na ně, řekl: Co jest pak to, což napsáno jest: Kámen, kterýmž pohrdli stavitelé, ten učiněn jest v hlavu úhelní?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 18, 'Každý, kdož padne na ten kámen, rozrazí se; a na kohož by on upadl, potřeť jej.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 19, 'I hledali přední kněží {biskupové} a zákonníci, jak by naň vztáhli ruce v tu hodinu, ale báli se lidu. Nebo porozuměli, že by na ně mluvil podobenství to.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 20, 'Tedy střehouce ho, poslali špehéře, kteříž by se spravedlivými činili, aby ho polapili v řeči, a potom jej vydali vrchnosti a v moc hejtmanu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 21, 'I otázali se ho, řkouce: Mistře, víme, že právě mluvíš a učíš, a nepřijímáš osoby, ale v pravdě cestě Boží učíš.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 22, 'Sluší-li nám daň dávati císaři, čili nic?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 23, 'Ale porozuměv chytrosti jejich, dí jim: Co mne pokoušíte?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 24, 'Ukažte mi peníz. Čí má obraz a nápis? I odpověděvše, řekli: Císařův.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 25, 'On pak řekl jim: Dejtež tedy, co jest císařova, císaři, a co jest Božího, Bohu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 26, 'I nemohli ho za slovo popadnouti před lidem, a divíce se odpovědi jeho, umlkli.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 27, 'Přistoupivše pak někteří z saduceů, (kteříž odpírají býti vzkříšení,) otázali se ho,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 28, 'Řkouce: Mistře, Mojžíš napsal nám: Kdyby bratr něčí umřel, maje manželku, a umřel by bez dětí, aby ji pojal bratr jeho za manželku, a vzbudil símě bratru svému.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 29, 'I bylo sedm bratří, a první pojav ženu, umřel bez dětí.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 30, 'I pojal druhý tu ženu, a umřel i ten bez dětí.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 31, 'Potom třetí pojal ji, též i všech těch sedm, a nezůstavivše dětí, zemřeli.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 32, 'Nejposléze po všech umřela i ta žena.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 33, 'Protož při vzkříšení, kterého z nich bude ta žena, poněvadž sedm jich mělo ji za manželku?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 34, 'A odpovídaje, řekl jim Ježíš: Synové tohoto věku žení se a vdávají.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 35, 'Ale ti, kteříž hodni jmíni budou dosáhnouti onoho věku a vzkříšení z mrtvých, ani se ženiti nebudou ani vdávati.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 36, 'Nebo ani umírati více nebudou moci, andělům zajisté rovni budou. A jsou synové Boží, poněvadž jsou synové vzkříšení.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 37, 'A že mrtví vstanou z mrtvých, i Mojžíš ukázal při onom kři, když nazývá Pána Bohem Abrahamovým, a Bohem Izákovým, a Bohem Jákobovým.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 38, 'Bůhť pak není mrtvých, ale živých, nebo všickni jsou jemu živi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 39, 'Tedy odpověděvše někteří z zákonníků, řekli: Mistře, dobře jsi pověděl.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 40, 'I nesměli se jeho na nic více tázati.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 41, 'Řekl pak jim: Kterak praví Krista býti synem Davidovým?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 42, 'A sám David praví v knize žalmů: Řekl Pán Pánu mému: Seď na pravici mé,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 43, 'Ažť položím nepřátely tvé v podnož noh tvých?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 44, 'Poněvadž David jej Pánem nazývá, i kterakž syn jeho jest?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 45, 'I řekl učedlníkům svým přede vším lidem:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 46, 'Varujte se zákonníků, kteříž rádi chodí v krásném rouše, a milují pozdravování na trzích a přední stolice v školách, a první místo na večeřích.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 47, 'Kteříž zžírají domy vdovské pod zámyslem dlouhé modlitby. Tiť vezmou těžší odsouzení.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 1, 'A pohleděv, uzřel bohaté, kteříž metali dary své do pokladnice.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 2, 'Uzřel pak i jednu vdovu chudičkou, ana uvrhla tam dva šarty.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 3, 'I řekl: V pravdě pravím vám, že vdova tato chudá více než všickni uvrhla.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 4, 'Nebo všickni tito z toho, což jim zbývalo, dali dary Bohu, tato pak z své chudoby všecku živnost svou, kterouž měla, uvrhla.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 5, 'A když někteří pravili o chrámu, kterak by kamením pěkným i okrasami ozdoben byl, řekl:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 6, 'Nač se to díváte? Přijdouť dnové, v nichž nebude zůstaven kámen na kameni, kterýž by nebyl zbořen.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 7, 'I otázali se ho, řkouce: Mistře, kdy to bude? A které znamení, když se to bude míti státi?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 8, 'On pak řekl: Vizte, abyste nebyli svedeni. Nebo mnozí přijdou ve jménu mém, řkouce: Já jsem, a čas se blíží. Protož nepostupujte po nich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 9, 'Když pak uslyšíte o válkách a různicech, nestrachujte se; neboť musí to prvé býti, ale ne i hned konec.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 10, 'Tehdy pravil jim: Povstaneť národ proti národu, a království proti království.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 11, 'A země třesení veliká budou po místech, a hladové, a morové, hrůzy i zázrakové s nebe velicí.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 12, 'Ale před tím přede vším vztáhnou ruce své na vás, a protiviti se budou, vydávajíce vás do škol a žalářů, vodíce k králům a k vládařům pro jméno mé.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 13, 'A toť se vám díti bude na svědectví.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 14, 'Protož složtež to v srdcích svých, abyste se nestarali, kterak byste odpovídati měli.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 15, 'Jáť zajisté dám vám ústa a moudrost, kteréž nebudou moci odolati, ani proti ní ostáti všickni protivníci vaši.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 16, 'Budete pak zrazováni i od rodičů a od bratří, od příbuzných i od přátel, a zmordují některé z vás.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 17, 'A budete v nenávisti u všech pro jméno mé.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 18, 'Ale ani vlas s hlavy vaší nikoli nezahyne.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 19, 'V trpělivosti své vládněte dušemi svými.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 20, 'Když pak uzříte obležený od vojska Jeruzalém, tehdy vězte, žeť se přiblížilo zkažení jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 21, 'Tehdy ti, kdož jsou v Judstvu, utíkejte k horám, a kdo u prostřed něho, vyjděte, a kteří v končinách, nevcházejte do něho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 22, 'Neboť budou dnové pomsty, aby se naplnilo všecko, což psáno jest.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 23, 'Ale běda těhotným a těm, kteréž kojí v těch dnech. Neboť bude dav veliký v této zemi, a hněv nad lidem tímto.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 24, 'I padati budou ostrostí meče, a zjímaní vedeni budou mezi všecky národy, a Jeruzalém tlačen bude od pohanů, dokudž se nenaplní časové pohanů.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 25, 'I budouť znamení na slunci a na měsíci i na hvězdách, a na zemi ssoužení národů, nevědoucích se kam díti, když zvuk vydá moře a vlnobití,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 26, 'Tak že zmrtvějí lidé pro strach a pro očekávání těch věcí, kteréž přijdou na všecken svět. Nebo moci nebeské pohybovati se budou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 27, 'A tehdyť uzří Syna člověka, an se béře v oblace s mocí a slavou velikou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 28, 'A když se toto počne díti, pohleďtež a pozdvihnětež hlav svých, proto že se přibližuje vykoupení vaše.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 29, 'I pověděl jim podobenství: Patřte na fíkový strom i na všecka stromoví.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 30, 'Když se již pučí, vidouce to, sami to znáte, že blízko jest již léto.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 31, 'Takž i vy, když uzříte, ano se tyto věci dějí, vězte, že blízko jest království Boží.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 32, 'Amen pravím vám, že nepomine věk tento, až se všecko stane.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 33, 'Nebe a země pominou, ale slova má nepominou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 34, 'Pilně se pak varujte, aby snad nebyla obtížená srdce vaše obžerstvím a opilstvím a pečováním o tento život, a v náhle přikvačil by vás ten den.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 35, 'Nebo jako osídlo přijde na všecky, kteříž přebývají na tváři vší země.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 36, 'Protož bděte, všelikého času modléce se, abyste hodni byli ujíti všech těch věcí, kteréž se budou díti, a postaviti se před Synem člověka.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 37, 'I býval ve dne v chrámě, uče, ale v noci vycházeje, přebýval na hoře, kteráž slove Olivetská.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 38, 'A všecken lid na úsvitě přicházel k němu do chrámu, aby ho poslouchal.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 1, 'Přibližoval se pak svátek přesnic, kterýž slove velikanoc.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 2, 'I hledali přední kněží {biskupové} a zákonníci, kterak by jej vyhladili; nebo obávali se lidu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 3, 'Tedy vstoupil satan do Jidáše, přijmím Iškariotského, kterýž byl z počtu dvanácti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 4, 'A on odšed, mluvil s předními kněžími {biskupy}, a s úředníky, kterak by ho jim zradil.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 5, 'I zradovali se, a smluvili s ním, že mu chtí peníze dáti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 6, 'I slíbil, a hledal příhodného času, aby ho jim zradil bez zástupu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 7, 'Tedy přišel den přesnic, v kterémž zabit měl býti beránek.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 8, 'I poslal Petra a Jana, řka: Jdouce, připravte nám beránka, abychom jedli.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 9, 'A oni řekli mu: Kde chceš, ať připravíme?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 10, 'On pak řekl jim: Aj, když vcházeti budete do města, potkáť vás člověk, dčbán vody nesa. Jdětež za ním do domu, do kteréhož vejde.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 11, 'A díte hospodáři toho domu: Vzkazuje tobě Mistr: Kde jest síň, kdež budu jísti beránka s učedlníky svými?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 12, 'A onť vám ukáže večeřadlo veliké podlážené. Tam připravte.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 13, 'I odšedše, nalezli, jakž jim pověděl, a připravili beránka.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 14, 'A když přišel čas, posadil se za stůl, a dvanácte apoštolů s ním.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 15, 'I řekl jim: Žádostí žádal jsem tohoto beránka jísti s vámi, prvé než bych trpěl.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 16, 'Nebo pravímť vám, žeť ho již více nebudu jísti, ažť se naplní v království Božím.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 17, 'A vzav kalich, a díky činiv, řekl: Vezměte jej a dělte mezi sebou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 18, 'Nebo pravím vám, žeť nebudu píti z plodu vinného kořene, ažť království Boží přijde.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 19, 'A vzav chléb, a díky činiv, lámal a dal jim, řka: To jest tělo mé, kteréž se za vás dává. To čiňte na mou památku.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 20, 'Takž i kalich, když bylo po večeři, řka: Tento kalich jest ta nová smlouva v mé krvi, kteráž se za vás vylévá.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 21, 'Ale aj, ruka zrádce mého se mnou za stolem.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 22, 'A Syn zajisté člověka jde, tak jakž jest uloženo, ale běda člověku tomu, kterýž ho zrazuje.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 23, 'Tedy oni počali vyhledávati mezi sebou, kdo by z nich byl, kterýž by to měl učiniti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 24, 'Stal se pak i svár mezi nimi, kdo by z nich zdál se býti největší.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 25, 'On pak řekl jim: Králové národů panují nad nimi, a kteříž moc mají nad nimi, dobrodincové slovou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 26, 'Ale vy ne tak. Nýbrž kdož největší jest mezi vámi, budiž jako nejmenší, a kdož vůdce jest, jako sloužící.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 27, 'Nebo kdo větší, ten-li, kterýž sedí, čili ten, kterýž slouží? Zdali ne ten, kterýž sedí? Ale já mezi vámi jsem jako ten, kterýž slouží.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 28, 'Vy pak jste ti, kteříž jste v mých pokušeních se mnou zůstali.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 29, 'A jáť vám způsobuji, jakož mi způsobil Otec můj, království,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 30, 'Abyste jedli a pili za stolem mým v království mém, a seděli na stolicích, soudíce dvanáctero pokolení Izraelské.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 31, 'I řekl Pán: Šimone, Šimone, aj, satan vyprosil, aby vás tříbil jako pšenici.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 32, 'Ale jáť jsem prosil za tebe, aby nezhynula víra tvá. A ty někdy obrátě se, potvrzuj bratří svých.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 33, 'A on řekl jemu: Pane, s tebou hotov jsem i do žaláře i na smrt jíti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 34, 'On pak dí: Pravím tobě, Petře, nezazpíváť dnes kohout, až prvé třikrát zapříš, že neznáš mne.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 35, 'I řekl jim: Když jsem vás posílal bez pytlíka, a bez mošny, a bez obuvi, zdali jste v čem nedostatek měli? A oni řekli: V ničemž.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 36, 'Tedy dí jim: Ale nyní, kdo má pytlík, vezmi a též i mošnu; a kdož meče nemá, prodej sukni svou, a kup sobě.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 37, 'Nebo pravím vám, že se ještě to písmo naplniti musí na mně: A s nešlechetnými počten jest. Nebo ty věci, kteréž svědčí o mně, konec berou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 38, 'Oni pak řekli: Pane, aj, dva meče teď. A on řekl jim: Dostiť jest.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 39, 'A vyšed, šel podlé obyčeje svého na horu Olivovou, a šli za ním i učedlníci jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 40, 'A když přišel na místo, řekl jim: Modlte se, abyste nevešli v pokušení.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 41, 'A sám vzdáliv se od nich, jako by mohl kamenem dohoditi, a poklek na kolena, modlil se,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 42, 'Řka: Otče, chceš-li, přenes kalich tento ode mne, ale však ne má vůle, ale tvá staň se.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 43, 'I ukázal se jemu anděl s nebe, posiluje ho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 44, 'A jsa v boji, horlivěji se modlil. I učiněn jest pot jeho jako krůpě krve tekoucí na zemi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 45, 'A vstav od modlitby, a přišed k učedlníkům, nalezl je, ani spí zámutkem.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 46, 'I řekl jim: Co spíte? Vstaňte a modlte se, abyste nevešli v pokušení.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 47, 'A když on ještě mluvil, aj, zástup, a ten, kterýž sloul Jidáš, jeden ze dvanácti, šel napřed, a přiblížil se k Ježíšovi, aby jej políbil.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 48, 'Ježíš pak řekl jemu: Jidáši, políbením Syna člověka zrazuješ.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 49, 'A vidouce ti, kteříž při něm byli, k čemu se chýlí, řekli jemu: Pane, budeme-liž bíti mečem?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 50, 'I udeřil jeden z nich služebníka nejvyššího kněze {biskupova}, a uťal ucho jeho pravé.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 51, 'A Ježíš odpověděv, řekl: Nechtež až potud. A dotek se ucha jeho, uzdravil jej.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 52, 'I dí Ježíš těm, kteříž přišli na něho, předním kněžím {biskupům} a úředníkům chrámu a starším: Jako na lotra vyšli jste s meči a s kyjmi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 53, 'Ješto na každý den býval jsem s vámi v chrámě, a nevztáhli jste rukou na mne. Ale totoť jest ta vaše hodina, a moc temnosti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 54, 'I javše jej, vedli, a uvedli do domu nejvyššího kněze {biskupova}. Petr pak šel za ním zdaleka.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 55, 'A když zanítili oheň u prostřed síně, a posadili se vůkol, sedl Petr mezi ně.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 56, 'A uzřevši ho jedna děvečka, an sedí u ohně, a pilně naň pohleděvši, řekla: I tento byl s ním.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 57, 'On pak zapřel ho, řka: Ženo, neznám ho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 58, 'A po malé chvíli jiný, vida jej, řekl: I ty z nich jsi. Petr pak řekl: Ó člověče, nejsem.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 59, 'A potom asi po jedné hodině jiný potvrzoval, řka: V pravdě i tento s ním byl, nebo také Galilejský jest.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 60, 'I řekl Petr: Člověče, nevím, co pravíš. A hned, když on ještě mluvil, kohout zazpíval.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 61, 'I obrátiv se Pán, pohleděl na Petra. I rozpomenul se Petr na slovo Páně, kterak jemu byl řekl: Že prvé než kohout zazpívá, třikrát mne zapříš.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 62, 'I vyšed ven Petr, plakal hořce.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 63, 'Muži pak ti, kteříž drželi Ježíše, posmívali se jemu, tepouce ho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 64, 'A zakrývajíce ho, bili jej v tvář, a tázali se ho, řkouce: Prorokuj, kdo jest, kterýž tebe udeřil?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 65, 'A jiného mnoho, rouhajíce se, mluvili proti němu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 66, 'A když byl den, sešli se starší lidu a přední kněží {biskupové} a zákonníci, a vedli ho do rady své,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 67, 'Řkouce: Jsi-li ty Kristus? Pověz nám. I dí jim: Povím-li vám, nikoli neuvěříte.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 68, 'A pakli se vás co otíži, neodpovíte mi, ani nepropustíte.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 69, 'Od této chvíle Syn člověka sedne na pravici moci Boží.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 70, 'I řekli všickni: Tedy jsi ty Syn Boží? On pak řekl jim: Vy pravíte, nebo já jsem.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 71, 'A oni řekli: Což ještě potřebujeme svědectví? Však jsme sami slyšeli z úst jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 1, 'Tehdy povstavši všecko množství jich, vedli jej ku Pilátovi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 2, 'A počali naň žalovati, řkouce: Tohoto jsme nalezli, an převrací lid, a brání daně dávati císaři, pravě se býti Kristem králem.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 3, 'Pilát pak otázal se ho, řka: Jsi-liž ty král ten Židovský? A on odpověděv, řekl jemu: Ty pravíš.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 4, 'I dí Pilát předním kněžím {biskupům} a zástupům: Žádné viny nenalézám na tomto člověku.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 5, 'Oni pak více se silili, řkouce: Bouříť lid, uče po všem Judstvu, počav od Galilee až sem.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 6, 'Tedy Pilát uslyšav o Galilei, otázal se, byl-li by člověk Galilejský.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 7, 'A když zvěděl, že by byl z panství Heródesova, poslal jej k Heródesovi, kterýž také v Jeruzalémě byl v ty dni.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 8, 'Heródes pak uzřev Ježíše, zradoval se velmi. Nebo dávno žádal viděti jej, proto že mnoho o něm slýchal, a nadál se, že nějaký div uzří od něho učiněný.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 9, 'I tázal se ho mnohými řečmi, ale on jemu nic neodpovídal.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 10, 'Stáli pak přední kněží {biskupové} a zákonníci, tuze na něj žalujíce.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 11, 'A pohrdna jím Heródes s svým rytířstvem, a naposmívav se jemu, oblékl jej v roucho bílé, i odeslal zase ku Pilátovi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 12, 'I učiněni jsou přátelé Pilát s Heródesem v ten den. Nebo před tím nepřátelé byli vespolek.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 13, 'Pilát pak svolav přední kněží {biskupy} a úřadné osoby i lid,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 14, 'Řekl jim: Dali jste mi tohoto člověka, jako by lid odvracel, a aj, já před vámi vyptávaje se ho, žádné viny jsem nenalezl na tom člověku v tom, což na něj žalujete.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 15, 'Ano ani Heródes; nebo odeslal jsem vás k němu, a aj, nic hodného smrti nestalo se jemu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 16, 'Protože potrestaje, propustím ho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 17, 'Musil pak propouštívati jim jednoho v svátek.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 18, 'Protož zkřiklo spolu všecko množství, řkouce: Zahlaď tohoto, a propusť nám Barabáše.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 19, 'Kterýž byl pro bouřku nějakou v městě učiněnou a pro vraždu vsazen do žaláře.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 20, 'Tedy Pilát opět mluvil, chtěje propustiti Ježíše.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 21, 'Oni pak vždy volali, řkouce: Ukřižuj ho, ukřižuj.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 22, 'A on potřetí řekl jim: Což pak zlého učinil tento? Žádné příčiny smrti nenalezl jsem na něm. Protož potresce, propustím ho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 23, 'Oni pak předce dotírali křikem velikým, žádajíce, aby byl ukřižován. A rozmáhali se hlasové jejich i předních kněží {biskupů}.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 24, 'Pilát pak přisoudil, aby se naplnila žádost jejich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 25, 'I propustil jim toho, kterýž pro bouřku a vraždu vsazen byl do žaláře, za něhož prosili, ale Ježíše vydal k vůli jejich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 26, 'A když jej vedli, chytivše Šimona nějakého Cyrenenského, jdoucího s pole, vložili na něj kříž, aby nesl za Ježíšem.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 27, 'I šlo za ním veliké množství lidu i žen, kteréž plakaly a kvílily ho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 28, 'A obrátiv se k nim Ježíš, dí: Dcery Jeruzalémské, neplačte nade mnou, ale raději samy nad sebou plačte a nad svými dětmi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 29, 'Nebo aj, dnové jdou, v nichž řeknou: Blahoslavené neplodné, a břicha, kteráž nerodila, a prsy, kteréž nekrmily.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 30, 'Tehdyť počnou říci k horám: Padněte na nás, a pahrbkům: Přikrejte nás.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 31, 'Nebo poněvadž na zeleném dřevě toto se děje, i co pak bude na suchém?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 32, 'Vedeni pak byli i jiní dva zločinci, aby spolu s ním byli ukřižováni.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 33, 'A když přišli na místo, kteréž slove popravištné, tu jej ukřižovali, i ty zločince, jednoho na pravici, druhého pak na levici.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 34, 'Tedy Ježíš řekl: Otče, odpusť jim, neboť nevědí, co činí. A rozdělivše roucho jeho, metali los.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 35, 'I stál lid, dívaje se. A posmívali se jemu knížata {biskupové} s nimi, řkouce: Jinýmť spomáhal, nechať pomůže sám sobě, jestliže on jest Kristus, ten Boží zvolený.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 36, 'Posmívali se pak jemu i žoldnéři, přistupujíce a octa podávajíce jemu,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 37, 'A říkajíce: Jsi-li ty král ten Židovský, spomoziž sám sobě.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 38, 'A byl také i nápis napsaný nad ním, literami Řeckými a Latinskými a Židovskými: Tento jest král Židovský.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 39, 'Jeden pak z těch zločinců, kteříž s ním viseli, rouhal se jemu, řka: Jsi-li ty Kristus, spomoziž sobě i nám.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 40, 'A odpověděv druhý, trestal ho, řka: Ani ty se Boha nebojíš, ješto jsi v témž potupení?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 41, 'A my zajisté spravedlivě, nebo hodnou pomstu za skutky své béřeme, ale tento nic zlého neučinil.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 42, 'I dí Ježíšovi: Pane, rozpomeň se na mne, když přijdeš do království svého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 43, 'I řekl mu Ježíš: Amen pravím tobě, dnes budeš se mnou v ráji.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 44, 'A bylo okolo hodiny šesté. I stala se tma po vší zemi až do hodiny deváté.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 45, 'I zatmělo se slunce, a opona chrámová roztrhla se napoly.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 46, 'A zvolav Ježíš hlasem velikým, řekl: Otče, v ruce tvé poroučím ducha svého. A to pověděv, umřel.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 47, 'A viděv centurio, co se stalo, velebil Boha, řka: Jistě člověk tento spravedlivý byl.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 48, 'A všickni zástupové, přítomní tomu divadlu, hledíce na to, co se dálo, tepouce prsy své, navracovali se.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 49, 'Stáli pak všickni známí jeho zdaleka, hledíce na to, i ženy, kteréž byly přišly za ním z Galilee.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 50, 'A aj, muž jménem Jozef, jeden z úřadu, muž dobrý a spravedlivý,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 51, 'Kterýž byl nepovolil radě a skutku jejich, z Arimatie města Judského, kterýž také očekával království Božího;');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 52, 'Ten přistoupiv ku Pilátovi, vyprosil tělo Ježíšovo.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 53, 'A složiv je, obvinul v kment, a pochoval je v hrobě vytesaném, v kterémž ještě nikdy nebyl žádný pochován.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 54, 'A byl den připravování, a sobota se začínala.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 55, 'Šedše pak také za ním ženy, kteréž byly s Ježíšem přišly z Galilee, pohleděly na hrob, a kterak pochováno bylo tělo jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 56, 'Vrátivše se pak, připravily vonné věci a masti, ale v sobotu odpočinuly, podlé přikázaní.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 1, 'Prvního pak dne po sobotě velmi ráno šly k hrobu, nesouce vonné věci, kteréž byly připravily, a některé jiné s nimi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 2, 'I nalezly kámen odvalený od hrobu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 3, 'A všedše, nenalezly těla Pána Ježíše.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 4, 'I stalo se, když ony se toho užasly, aj, muži dva postavili se podlé nich v rouše stkvoucím.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 5, 'Když se pak ony bály, a sklonily tváři své k zemi, řekli jim: Co hledáte živého s mrtvými?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 6, 'Neníť ho tuto, ale vstalť jest. Rozpomeňte se, kterak mluvil vám, když ještě v Galilei byl,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 7, 'Řka: Že Syn člověka musí vydán býti v ruce hříšných lidí, a ukřižován býti, a v třetí den z mrtvých vstáti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 8, 'I rozpomenuly se na slova jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 9, 'A navrátivše se od hrobu, zvěstovaly to všecko těm jedenácti i jiným všechněm.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 10, 'Byly pak Maria Magdaléna a Johanna a Maria Jakubova, a jiné s nimi, kteréž vypravovaly to apoštolům.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 11, 'Ale oni měli za bláznovství slova jejich, a nevěřili jim.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 12, 'Tedy Petr vstav, běžel k hrobu, a pohleděv do něho, uzřel prostěradla, ana sama leží. I odšel, divě se sám v sobě, co se to stalo.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 13, 'A aj, dva z nich šli toho dne do městečka, kteréž bylo vzdálí od Jeruzaléma honů šedesáte, jemuž jméno Emaus.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 14, 'A rozmlouvali vespolek o těch všech věcech, kteréž se byly staly.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 15, 'I stalo se, když rozmlouvali, a sebe se otazovali, že i Ježíš, přiblíživ se, šel s nimi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 16, 'Ale oči jejich držány byly, aby ho nepoznali.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 17, 'I řekl jim: Které jsou to věci, o nichž rozjímáte vespolek, jdouce, a jste smutní?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 18, 'A odpověděv jeden, kterémuž jméno Kleofáš, řekl jemu: Ty sám jsi z příchozích do Jeruzaléma, ještos nezvěděl, co se stalo v něm těchto dnů?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 19, 'Kterýmž on řekl: I co? Oni pak řekli jemu: O Ježíšovi Nazaretském, kterýž byl muž prorok, mocný v slovu i v skutku, před Bohem i přede vším lidem,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 20, 'Totiž kterak jej vydali přední kněží {biskupové} a knížata naše na odsouzení k smrti, i ukřižovali jej.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 21, 'My pak jsme se nadáli, že by on měl vykoupiti Izraele. Ale nyní tomu všemu třetí den jest dnes, jakž se to stalo.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 22, 'Ale i ženy některé z našich zděsily nás, kteréž ráno byly u hrobu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 23, 'A nenalezše tělo jeho, přišly, pravíce, že také vidění andělské viděly, kteříž praví, že by živ byl.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 24, 'I chodili někteří z našich k hrobu, a nalezli tak, jakž pravily ženy, ale jeho neviděli.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 25, 'Tedy on řekl jim: Ó nesmyslní a zpozdilí srdcem k věření všemu tomu, což mluvili proroci.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 26, 'Zdaliž nemusil těch věcí trpěti Kristus a vjíti v slávu svou?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 27, 'A počav od Mojžíše a všech proroků, vykládal jim všecka ta písma, kteráž o něm byla.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 28, 'I přiblížili se k městečku, do kteréhož šli, a on potrh se, jako by chtěl dále jíti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 29, 'Ale přinutili ho, řkouce: Zůstaň s námi, nebo se již připozdívá, a den se nachýlil. I všel, aby s nimi zůstal.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 30, 'I stalo se, když seděl s nimi za stolem, vzav chléb, dobrořečil, a lámaje, podával jim.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 31, 'I otevříny jsou oči jejich, a poznali ho. On pak odnesl se od nich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 32, 'I řekli vespolek: Zdaliž srdce naše v nás nehořelo, když mluvil nám na cestě, a když otvíral nám písma?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 33, 'A vstavše v tu hodinu, vrátili se do Jeruzaléma, a nalezli shromážděných těch jedenácte, a ty, kteříž s nimi byli,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 34, 'Ani praví: Že vstal Pán právě, a ukázal se Šimonovi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 35, 'I vypravovali oni také to, co se stalo na cestě, a kterak ho poznali v lámání chleba.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 36, 'A když oni o tom rozmlouvali, postavil se Ježíš u prostřed nich, a řekl jim: Pokoj vám.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 37, 'Oni pak zhrozivše se a přestrašeni byvše, domnívali se, že by ducha viděli.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 38, 'I dí jim: Co se strašíte, a proč myšlení vstupují na srdce vaše?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 39, 'Vizte ruce mé i nohy mé, já zajisté jsem ten. Dotýkejte se mne a vizte; neboť duch těla a kostí nemá, jako mne vidíte míti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 40, 'A pověděv to, ukázal jim ruce i nohy.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 41, 'Když pak oni ještě nevěřili pro radost, ale divili se, řekl jim: Máte-li tu co k jídlu?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 42, 'A oni podali jemu kusu ryby pečené a plástu strdi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 43, 'A vzav, pojedl před nimi,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 44, 'A řekl jim: Tatoť jsou slova, kteráž jsem mluvil vám, ještě byv s vámi: Že se musí naplniti všecko, což psáno jest v zákoně Mojžíšově a v prorocích i v žalmích o mně.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 45, 'Tedy otevřel jim mysl, aby rozuměli písmům.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 46, 'A řekl jim: Takť jest psáno, a tak musil Kristus trpěti, a třetího dne z mrtvých vstáti,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 47, 'A aby bylo kázáno ve jménu jeho pokání a odpuštění hříchů mezi všemi národy, počna od Jeruzaléma.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 48, 'Vy pak jste svědkové toho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 49, 'A aj, já pošli zaslíbení Otce svého na vás. Vy pak čekejte v městě Jeruzalémě, dokudž nebudete oblečeni mocí s výsosti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 50, 'I vyvedl je ven až do Betany, a pozdvih rukou svých, dal jim požehnání.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 51, 'I stalo se, když jim žehnal, bral se od nich, a nesen jest do nebe.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 52, 'A oni poklonivše se jemu, navrátili se do Jeruzaléma s radostí velikou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 53, 'A byli vždycky v chrámě, chválíce a dobrořečíce Boha. Amen.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 1, 'Na počátku bylo Slovo, a to Slovo bylo u Boha, a to Slovo byl Bůh.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 2, 'To bylo na počátku u Boha.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 3, 'Všecky věci skrze ně učiněny jsou, a bez něho nic není učiněno, což učiněno jest.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 4, 'V něm život byl, a život byl světlo lidí.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 5, 'A to světlo v temnostech svítí, ale tmy ho neobsáhly.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 6, 'Byl člověk poslaný od Boha, jemuž jméno bylo Jan.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 7, 'Ten přišel na svědectví, aby svědčil o tom světle, aby všickni uvěřili skrze něho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 8, 'Nebyl on to světlo, ale přišel, aby svědectví vydával o tom světle.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 9, 'Tentoť byl to pravé světlo, kteréž osvěcuje každého člověka přicházejícího na svět.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 10, 'Na světě byl, a svět skrze něho učiněn jest, ale svět ho nepoznal.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 11, 'Do svého vlastního přišel, ale vlastní jeho nepřijali ho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 12, 'Kteříž pak koli přijali jej, dal jim moc syny Božími býti, těm, kteříž věří ve jméno jeho,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 13, 'Kteříž ne ze krví, ani z vůle těla, ani z vůle muže, ale z Boha zplozeni jsou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 14, 'A Slovo to tělo učiněno jest, a přebývalo mezi námi, (a viděli jsme slávu jeho, slávu jakožto jednorozeného od Otce,) plné milosti a pravdy.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 15, 'Jan svědectví vydával o něm, a volal, řka: Tentoť jest, o němž jsem pravil, že po mně přišed, předšel mne; nebo přednější jest než já.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 16, 'A z plnosti jeho my všickni vzali jsme, a to milost za milost.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 17, 'Nebo zákon skrze Mojžíše dán jest, milost a pravda skrze Ježíše Krista stala se.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 18, 'Boha žádný nikdy neviděl; jednorozený ten Syn, kterýž jest v lůnu Otce, onť vypravil.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 19, 'A totoť jest svědectví Janovo, když poslali Židé z Jeruzaléma kněží a Levíty, aby se ho otázali: Ty kdo jsi?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 20, 'I vyznal a nezapřel, a vyznal: Že já nejsem Kristus.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 21, 'I otázali se ho: Což pak? Eliáš jsi ty? I řekl: Nejsem. Jsi ten prorok? Odpověděl: Nejsem.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 22, 'I řekli jemu: Kdožs pak? Ať odpověd dáme těm, kteříž nás poslali. Co pravíš sám o sobě?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 23, 'Řekl: Já jsem hlas volajícího na poušti: Spravte cestu Páně, jakož pověděl Izaiáš prorok.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 24, 'Ti pak, kteříž byli posláni, z farizeů byli.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 25, 'I otázali se ho a řekli jemu: Proč tedy křtíš, jestliže ty nejsi Kristus, ani Eliáš, ani ten prorok?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 26, 'Odpověděl jim Jan, řka: Já křtím vodou, ale u prostřed vás stojí, jehož vy neznáte.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 27, 'Totoť jest ten, kterýž po mně přišed, předšel mne, u jehož obuvi já nejsem hoden rozvázati řeménka.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 28, 'Toto v Betabaře stalo se za Jordánem, kdež Jan křtil.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 29, 'Druhého dne uzřel Jan Ježíše, an jde k němu. I dí: Aj, Beránek Boží, kterýž snímá hřích světa.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 30, 'Tentoť jest, o kterémž jsem já pravil, že za mnou jde muž, kterýž mne předšel; nebo přednější jest než já.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 31, 'A já jsem ho neznal, ale aby zjeven byl lidu Izraelskému, proto jsem já přišel, křtě vodou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 32, 'A svědectví vydal Jan, řka: Viděl jsem Ducha sstupujícího jako holubici s nebe, a zůstal na něm.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 33, 'A já jsem ho neznal, ale kterýž mne poslal křtíti vodou, ten mi řekl: Nad kýmž uzříš Ducha sstupujícího a zůstávajícího na něm, tenť jest, kterýž křtí Duchem svatým.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 34, 'A já jsem viděl, a svědectví jsem vydal, že on jest ten Syn Boží.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 35, 'Druhého pak dne opět stál Jan, a z učedlníků jeho dva,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 36, 'A uzřev Ježíše, an se prochází, řekl: Aj, Beránek Boží.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 37, 'I slyšeli ho ti dva učedlníci mluvícího, a šli za Ježíšem.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 38, 'I obrátiv se Ježíš, a uzřev je, ani jdou, dí jim:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 39, 'Co hledáte? A oni řekli jemu: Rabbi, (což se vykládá: Mistře,) kde bydlíš?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 40, 'Dí jim: Poďte a vizte. I šli a viděli, kde bydlil, a zůstali u něho ten den; nebo bylo okolo desáté hodiny.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 41, 'Byl Ondřej, bratr Šimona Petra, jeden z těch dvou, kteříž byli to slyšeli od Jana, a šli za ním.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 42, 'I nalezl ten první bratra svého vlastního Šimona, a řekl mu: Nalezli jsme Mesiáše, což se vykládá Kristus.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 43, 'I přivedl jej k Ježíšovi. A pohleděv naň Ježíš, dí: Ty jsi Šimon, syn Jonášův, ty slouti budeš Céfas, což se vykládá Petr.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 44, 'Na druhý den chtěl Ježíš vyjíti do Galilee, i nalezl Filipa, a řekl jemu: Poď za mnou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 45, 'A byl Filip z Betsaidy, města Ondřejova a Petrova.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 46, 'Nalezl Filip Natanaele. I dí jemu: O kterémž psal Mojžíš v zákoně a proroci, nalezli jsme, Ježíše, syna Jozefova z Nazaréta.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 47, 'I řekl jemu Natanael: A může z Nazaréta co dobrého býti? Řekl jemu Filip: Poď a viz.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 48, 'Vida Ježíš Natanaele, an jde k němu, i dí o něm: Aj, právě Izraelitský, v němžto lsti není.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 49, 'Řekl mu Natanael: Jakž ty mne znáš? Odpověděl Ježíš a řekl jemu: Prvé než tě Filip zavolal, kdyžs byl pod fíkem, viděl jsem tebe.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 50, 'Odpověděl Natanael a řekl jemu: Mistře, ty jsi Syn Boží, ty jsi ten král Izraelský.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 51, 'Odpověděl Ježíš a řekl jemu: Žeť jsem řekl: Viděl jsem tebe pod fíkem, věříš. Větší věci nad tyto uzříš. I dí mu: Amen, amen pravím vám: Od tohoto času uzříte nebe otevřené, a anděly Boží vstupující a sstupující na Syna člověka.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 1, 'Třetího pak dne stala se svadba v Káni Galilejské, a byla matka Ježíšova tam.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 2, 'A pozván jest také Ježíš i učedlníci jeho na tu svadbu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 3, 'Když se pak nedostalo vína, řekla matka Ježíšova jemu: Vína nemají.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 4, 'Dí jí Ježíš: Co mně a tobě ženo? Ještě nepřišla hodina má.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 5, 'Dí matka jeho služebníkům: Což by koli vám řekl, učiňte.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 6, 'I bylo tu kamenných stoudví šest postaveno, podlé očišťování Židovského, beroucí v sebe jedna každá dvě neb tři míry.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 7, 'Řekl jim Ježíš: Naplňte ty stoudve vodou. I naplnili je až do vrchu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 8, 'I dí jim: Nalévejtež již, a neste vrchnímu správci svadby. I nesli.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 9, 'A jakž okusil vrchní správce svadby té vody, vínem učiněné, (nevěděl pak, odkud by bylo, ale služebníci věděli, kteříž vážili vodu,) povolal ženicha ten vrchní správce,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 10, 'A řekl mu: Každý člověk nejprvé dobré víno dává, a když by se hojně napili, tedy to, kteréž horší. Ty zachoval jsi víno dobré až dosavad.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 11, 'To učinil Ježíš počátek divů v Káni Galilejské, a zjevil slávu svou. I uvěřili v něho učedlníci jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 12, 'Potom sstoupil do Kafarnaum, on i matka jeho, i bratří jeho, i učedlníci jeho, a pobyli tam nemnoho dní;');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 13, 'Nebo blízko byla velikanoc Židovská. I vstoupil Ježíš do Jeruzaléma.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 14, 'A nalezl v chrámě prodavače volů a ovec i holubic, a penězoměnce sedící.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 15, 'A udělav bič z provázků, všecky vyhnal z chrámu, i ovce i voly, a penězoměncům rozsypal peníze, a stoly zpřevracel.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 16, 'A těm, kteříž holuby prodávali, řekl: Odneste tyto věci odsud, a nečiňte domu Otce mého domem kupeckým.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 17, 'I rozpomenuli se učedlníci jeho, že psáno jest: Horlivost domu tvého snědla mne.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 18, 'Tedy odpověděli Židé a řekli jemu: Jaké znamení nám ukážeš, že tyto věci činíš?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 19, 'Odpověděl Ježíš a řekl jim: Zrušte chrám tento, a ve třech dnech zase vzdělám jej.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 20, 'I řekli Židé: Čtyřidceti a šest let dělán jest chrám tento, a ty ve třech dnech vzděláš jej?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 21, 'Ale on mluvil o chrámu těla svého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 22, 'A protož když z mrtvých vstal, rozpomenuli se učedlníci jeho, že jim to byl pověděl. I uvěřili písmu a slovu, kteréž pověděl Ježíš.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 23, 'A když byl v Jeruzalémě na velikunoc v den sváteční, mnozí uvěřili ve jméno jeho, vidouce divy jeho, kteréž činil.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 24, 'Ale Ježíš nesvěřil sebe samého jim, proto že on znal všecky.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 25, 'Aniž potřeboval, aby kdo svědectví vydával o člověku; nebo on věděl, co by bylo v člověku.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 1, 'Byl pak člověk z farizeů, jménem Nikodém, kníže Židovské.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 2, 'Ten přišel k Ježíšovi v noci, a řekl jemu: Mistře, víme, že jsi od Boha přišel mistr; nebo žádný nemůže těch divů činiti, kteréž ty činíš, leč by Bůh byl s ním.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 3, 'Odpověděl Ježíš a řekl jemu: Amen, amen pravím tobě: Nenarodí-li se kdo znovu, nemůž viděti království Božího.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 4, 'Řekl jemu Nikodém: Kterak můž člověk naroditi se, starý jsa? Zdali může po druhé v život matky své vjíti a naroditi se?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 5, 'Odpověděl Ježíš: Amen, amen pravím tobě: Nenarodí-li se kdo z vody a z Ducha, nemůž vjíti do království Božího.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 6, 'Což se narodilo z těla, tělo jest, a což se narodilo z Ducha, duch jest.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 7, 'Nediviž se, že jsem řekl tobě: Musíte se znovu zroditi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 8, 'Vítr, kam chce věje, a hlas jeho slyšíš, ale nevíš, odkud přichází, a kam jde. Takť jest každý, kdo se z Ducha narodil.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 9, 'Odpověděl Nikodém a řekl jemu: Kterak mohou tyto věci býti?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 10, 'Odpověděl Ježíš a řekl jemu: Ty jsi mistr v Izraeli, a toho neznáš?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 11, 'Amen, amen pravím tobě: Že což víme, mluvíme, a což jsme viděli, svědčíme, ale svědectví našeho nepřijímáte.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 12, 'Poněvadž zemské věci mluvil jsem vám, a nevěříte, kterak, budu-li vám praviti nebeské, uvěříte?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 13, 'A jistě žádnýť nevstoupil v nebe, než ten, kterýž sstoupil s nebe, Syn člověka, kterýž jest v nebi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 14, 'A jakož Mojžíš povýšil hada na poušti, takť musí povýšen býti Syn člověka,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 15, 'Aby každý, kdož věří v něho, nezahynul, ale měl život věčný.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 16, 'Nebo tak Bůh miloval svět, že Syna svého jednorozeného dal, aby každý, kdož věří v něho, nezahynul, ale měl život věčný.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 17, 'Neboť neposlal Bůh Syna svého na svět, aby odsoudil svět, ale aby spasen byl svět skrze něho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 18, 'Kdož věří v něho, nebude odsouzen, ale kdož nevěří, jižť jest odsouzen; nebo neuvěřil ve jméno jednorozeného Syna Božího.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 19, 'Totoť pak jest ten soud, že světlo přišlo na svět, ale milovali lidé více tmu nežli světlo; nebo skutkové jejich byli zlí.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 20, 'Každý zajisté, kdož zle činí, nenávidí světla, a nejde k světlu, aby nebyli trestáni skutkové jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 21, 'Ale kdož činí pravdu, jde k světlu, aby zjeveni byli skutkové jeho, že v Bohu učiněni jsou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 22, 'Potom přišel Ježíš i učedlníci jeho do země Judské, a tu přebýval s nimi, a křtil.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 23, 'A Jan také křtil v Enon, blízko Sálim, nebo byly tam vody mnohé. I přicházeli, a křtili se.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 24, 'Nebo ještě Jan nebyl vsazen do žaláře.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 25, 'Tedy vznikla otázka mezi učedlníky Janovými a Židy o očišťování.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 26, 'I přišli k Janovi a řekli jemu: Mistře, ten kterýž byl s tebou za Jordánem, jemužs ty svědectví vydal, aj, on křtí, a všickni jdou k němu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 27, 'Odpověděl Jan a řekl: Nemůžť člověk vzíti ničeho, leč by jemu dáno bylo s nebe.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 28, 'Vy sami svědkové jste mi, že jsem pověděl: Nejsem já Kristus, ale že jsem poslán před ním.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 29, 'Kdož má nevěstu, ženichť jest, přítel pak ženicha, kterýž stojí a slyší ho, radostí raduje se pro hlas ženicha. Protož ta radost má naplněna jest.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 30, 'Onť musí růsti, já pak menšiti se.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 31, 'Kdožť s hůry přišel, nade všeckyť jest; kdož jest z země, zemskýť jest, a zemské věci mluví. Ten, kterýž s nebe přišel, nade všecky jest.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 32, 'A což viděl a slyšel, toť svědčí, ale svědectví jeho žádný nepřijímá.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 33, 'Kdož přijímá svědectví jeho, zpečetil to, že Bůh pravdomluvný jest.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 34, 'Nebo ten, kteréhož Bůh poslal, slovo Boží mluví, nebo jemu ne v míru dává Bůh Ducha.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 35, 'Otec miluje Syna, a všecko dal v ruku jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 36, 'Kdož věří v Syna, má život věčný; ale kdožť jest nevěřící Synu, neuzříť života, ale hněv Boží zůstává na něm.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 1, 'A jakž poznal Pán, že slyšeli farizeové, že by Ježíš více učedlníků činil a křtil než Jan,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 2, '(Ačkoli Ježíš sám nekřtil, ale učedlníci jeho,)');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 3, 'Opustil Judstvo, a odšel opět do Galilee.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 4, 'Musil pak jíti skrze Samaří.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 5, 'I přišel k městu Samařskému, kteréž slove Sichar, vedlé popluží, kteréž byl dal Jákob Jozefovi, synu svému.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 6, 'Byla pak tu studnice Jákobova. Protož ustav na cestě Ježíš, posadil se tak na studnici. A bylo okolo šesté hodiny.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 7, 'I přišla žena z Samaří vážiti vody. Kteréž řekl Ježíš: Dej mi píti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 8, 'Nebo učedlníci jeho byli odešli do města, aby nakoupili pokrmů.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 9, 'I řekla jemu žena ta Samaritánka: Kterakž ty, jsa Žid, žádáš ode mne nápoje od ženy Samaritánky? (Nebo neobcují Židé s Samaritány.)');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 10, 'Odpověděl Ježíš a řekl jí: Kdybys znala ten dar Boží, a kdo jest ten, kterýž praví tobě: Dej mi píti, ty bys prosila jeho, a dal by tobě vody živé.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 11, 'I dí jemu žena: Pane, aniž máš, čím bys navážil, a studnice jest hluboká. Odkudž tedy máš tu vodu živou?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 12, 'Zdaliž jsi ty větší nežli otec náš Jákob, kterýž nám dal tuto studnici, a sám z ní pil, i synové jeho, i dobytek jeho?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 13, 'Odpověděl Ježíš a řekl jí: Každý, kdož pije vodu tuto, žízniti bude opět.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 14, 'Ale kdož by se napil vody té, kterouž já dám jemu, nežíznil by na věky, ale voda ta, kterouž já dám jemu, bude v něm studnicí vody prýštící se k životu věčnému.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 15, 'Řekla jemu žena: Pane, dej mi té vody, abych nežíznila, ani chodila sem vážiti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 16, 'Řekl jí Ježíš: Jdi, zavolej muže svého, a přiď sem.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 17, 'Odpověděla žena a řekla: Nemám muže. Dí jí Ježíš: Dobřes řekla: Nemám muže.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 18, 'Nebos pět mužů měla, a nyní kteréhož máš, není tvůj muž. To jsi pravdu pověděla.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 19, 'Řekla jemu žena: Pane, vidím, že jsi ty prorok.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 20, 'Otcové naši na této hoře modlívali se, a vy pravíte, že v Jeruzalémě jest místo, kdež náleží se modliti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 21, 'Dí jí Ježíš: Ženo, věř mi, žeť jde hodina, kdyžto ani na této hoře, ani v Jeruzalémě nebudete se modliti Otci.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 22, 'Vy se modlíte, a nevíte, čemu; my se modlíme, čemuž víme, nebo spasení z Židů jest.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 23, 'Ale jdeť hodina, a nyníť jest, kdyžto praví modlitebníci modliti se budou Otci v duchu a v pravdě. Neboť takových Otec hledá, aby se modlili jemu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 24, 'Bůh duch jest, a ti, kteříž se jemu modlí, v duchu a v pravdě musejí se modliti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 25, 'Dí jemu žena: Vím, že Mesiáš přijde, kterýž slove Kristus. Ten, když přijde, oznámí nám všecko.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 26, 'Dí jí Ježíš: Jáť jsem, kterýž mluvím s tebou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 27, 'A v tom přišli učedlníci jeho, i divili se, že by s ženou mluvil, a však žádný neřekl: Nač se ptáš, aneb proč mluvíš s ní?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 28, 'I nechala tu žena vědra svého, a šla do města, a řekla těm lidem:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 29, 'Poďte, vizte člověka, kterýž pověděl mi všecko, což jsem koli činila. Není-li on ale Kristus?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 30, 'Tedy vyšli z města, a přišli k němu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 31, 'Mezi tím pak prosili ho učedlníci, řkouce: Mistře, pojez.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 32, 'A on řekl jim: Jáť mám pokrm jísti, kteréhož vy nevíte.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 33, 'Učedlníci pak mluvili vespolek: Zdali jemu kdo přinesl jísti?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 34, 'Dí jim Ježíš: Můjť pokrm jest, abych činil vůli toho, kterýž mne poslal, a dokonal dílo jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 35, 'Však vy pravíte, že ještě čtyři měsícové jsou, a žeň přijde. Aj, pravím vám: Pozdvihněte očí svých, a patřte na krajiny, žeť se již bělejí ke žni.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 36, 'Kdož pak žne, odplatuť béře, a shromažďuje užitek k životu věčnému, aby i ten, kdož rozsívá, radoval se spolu, i kdo žne.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 37, 'Nebo v tom pravé jest slovo, žeť jiný jest, kdož rozsívá, a jiný, kterýž žne.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 38, 'Jáť jsem vás poslal žíti, o čemž jste vy nepracovali. Jiníť pracovali, a vy jste v jejich práce vešli.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 39, 'Z města pak toho mnozí z Samaritánů uvěřili v něho, pro řeč té ženy, svědčící: Že mi pověděl všecko, což jsem činila.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 40, 'A když k němu přišli Samaritáni, prosili ho, aby s nimi zůstal. I pobyl tu za dva dni.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 41, 'A mnohem jich více uvěřilo pro řeč jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 42, 'A ženě té řekli: Již ne pro tvé vypravování věříme; nebo sami jsme slyšeli, a víme, že tento jest právě spasitel světa, Kristus.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 43, 'Po dvou pak dnech vyšel odtud, a šel do Galilee.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 44, 'Nebo sám Ježíš byl svědectví vydal, že prorok v vlasti své v poctivosti není.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 45, 'A když přišel do Galilee, přijali jej Galilejští, všecko viděvše, co činil v Jeruzalémě v svátek; nebo i oni byli přišli k svátku.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 46, 'Tedy opět přišel Ježíš do Kány Galilejské, kdež učinil byl z vody víno. I byl jeden královský služebník v Kafarnaum, jehožto syn nemocen byl.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 47, 'Ten uslyšev, že by Ježíš přišel z Judstva do Galilee, šel k němu, a prosil ho, aby sstoupil a uzdravil syna jeho; nebo počínal umírati.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 48, 'I řekl jemu Ježíš: Neuzříte-li divů a zázraků, neuvěříte.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 49, 'Dí jemu ten královský služebník: Pane, podiž prvé, nežli umře syn můj.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 50, 'Dí jemu Ježíš: Jdi, syn tvůj živ jest. I uvěřil člověk řeči, kterouž mluvil jemu Ježíš, a šel.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 51, 'Když pak on již šel, potkali se s ním služebníci jeho a zvěstovali, řkouce: Syn tvůj živ jest.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 52, 'Tedy otázal se jich na hodinu, v kterou by se lépe měl. I řekli jemu: Včera v hodinu sedmou přestala mu zimnice.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 53, 'Tedy poznal otec, že právě ta hodina byla, v kterouž řekl byl jemu Ježíš: Syn tvůj živ jest. I uvěřil on i dům jeho všecken.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 54, 'To opět druhý div učinil Ježíš, přišed z Judstva do Galilee.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 1, 'Potom byl svátek Židovský, i šel Ježíš do Jeruzaléma.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 2, 'Byl pak v Jeruzalémě rybník bravný, kterýž slove Židovsky Bethesda, patero přístřeší maje.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 3, 'Kdež leželo množství veliké neduživých, slepých, kulhavých, suchých, očekávajících hnutí vody.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 4, 'Nebo anděl jistým časem sstupoval do rybníka, a kormoutil vodu. Protož kdož nejprvé sstoupil po tom zkormoucení vody, uzdraven býval, od kterékoli nemoci trápen byl.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 5, 'I byl tu člověk jeden, kterýž osm a třidceti let nemocen byl.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 6, 'Toho uzřev Ježíš ležícího, a poznav, že jest již dávno nemocen, dí jemu: Chceš-li zdráv býti?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 7, 'Odpověděl mu ten nemocný: Pane, nemám člověka, kterýž by, když se zkormoutí voda, uvrhl mne do rybníka, ale když já jdu, jiný přede mnou sstupuje.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 8, 'Dí jemu Ježíš: Vstaň, vezmi lože své a choď.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 9, 'A hned zdráv jest učiněn člověk ten, a vzav lože své, i chodil. Byla pak sobota v ten den.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 10, 'Tedy řekli Židé tomu uzdravenému: Sobota jest, nesluší tobě lože nositi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 11, 'Odpověděl jim: Ten, kterýž mne uzdravil, onť mi řekl: Vezmi lože své a choď.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 12, 'I otázali se ho: Kdo jest ten člověk, kterýž tobě řekl: Vezmi lože své a choď?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 13, 'Ten pak uzdravený nevěděl, kdo by byl. Nebo Ježíš byl poodšel od zástupu shromážděného na tom místě.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 14, 'Potom pak nalezl jej Ježíš v chrámě, a řekl jemu: Aj, zdráv jsi učiněn; nikoli víc nehřeš, aťby se něco horšího nepřihodilo.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 15, 'Odšel ten člověk, a pověděl Židům, že by Ježíš byl ten, kterýž ho zdravého učinil.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 16, 'A protož protivili se Židé Ježíšovi, a hledali ho zabiti, že to učinil v sobotu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 17, 'Ježíš pak odpověděl jim: Otec můj až dosavad dělá, i jáť dělám.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 18, 'Tedy Židé ještě víc proto hledali ho zamordovati, že by netoliko rušil sobotu, ale že Otce svého pravil býti Boha, rovného se čině Bohu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 19, 'I odpověděl Ježíš a řekl jim: Amen, amen pravím vám: Nemůžeť Syn sám od sebe nic činiti, jediné což vidí, an Otec činí. Nebo cožkoli on činí, toť i Syn též podobně činí.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 20, 'Otec zajisté miluje Syna, a ukazuje mu všecko, což sám činí; a větší nad to ukáže jemu skutky, abyste vy se divili.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 21, 'Nebo jakož Otec křísí mrtvé a obživuje, tak i Syn, kteréž chce, obživuje.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 22, 'Aniž zajisté Otec soudí koho, ale všecken soud dal Synu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 23, 'Aby všickni ctili Syna, tak jakž Otce ctí. Kdo nectí Syna, nectí ani Otce, kterýž ho poslal.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 24, 'Amen, amen pravím vám: Že kdož slovo mé slyší, a věří tomu, kterýž mne poslal, máť život věčný, a na soud nepřijde, ale přešelť jest z smrti do života.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 25, 'Amen, amen pravím vám: Že přijde hodina, a nyníť jest, když mrtví uslyší hlas Syna Božího, a kteříž uslyší, živi budou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 26, 'Nebo jakož Otec má život sám v sobě, tak dal i Synu, aby měl život v samém sobě.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 27, 'A dal jemu moc i soud činiti, nebo Syn člověka jest.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 28, 'Nedivtež se tomu; neboť přijde hodina, v kterouž všickni, kteříž v hrobích jsou, uslyší hlas jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 29, 'A půjdou ti, kteříž dobré věci činili, na vzkříšení života, ale ti, kteříž zlé věci činili, na vzkříšení soudu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 30, 'Nemohuť já sám od sebe nic činiti. Jakžť slyším, takť soudím, a soud můj spravedlivý jest. Nebo nehledám vůle své, ale vůle toho, kterýž mne poslal, Otcovy.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 31, 'Vydám-liť já svědectví sám o sobě, svědectví mé není pravé.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 32, 'Jinýť jest, kterýž svědectví vydává o mně, a vím, že pravé jest svědectví, kteréž vydává o mně.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 33, 'Vy jste byli poslali k Janovi, a on svědectví vydal pravdě.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 34, 'Ale jáť nepřijímám svědectví od člověka, než totoť pravím, abyste vy spaseni byli.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 35, 'Onť byl svíce hořící a svítící, vy pak chtěli jste se na čas poradovati v světle jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 36, 'Ale já mám větší svědectví, než Janovo. Nebo skutkové, kteréž mi dal Otec, abych je vykonal, tiť skutkové, kteréž já činím, svědčí o mně, že mne Otec poslal.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 37, 'A kterýž mne poslal, Otec, onť svědectví vydal o mně, jehož jste vy hlasu nikdy neslyšeli, ani tváři jeho neviděli.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 38, 'A slova jeho nemáte v sobě zůstávajícího. Nebo kteréhož on poslal, tomu vy nevěříte.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 39, 'Ptejte se na písma; nebo vy domníváte se v nich věčný život míti, a tať svědectví vydávají o mně.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 40, 'Ale nechcete přijíti ke mně, abyste život měli.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 41, 'Chvály od lidí nepřijímám.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 42, 'Ale poznal jsem vás, že milování Božího nemáte v sobě.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 43, 'Já jsem přišel ve jménu Otce svého, a nepřijímáte mne. Kdyby jiný přišel ve jménu svém, toho přijmete.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 44, 'Kterak vy můžete věřiti, chvály jedni od druhých hledajíce, poněvadž chvály, kteráž jest od samého Boha, nehledáte?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 45, 'Nedomnívejte se, bychť já na vás žalovati měl před Otcem. Jestiť, kdo by žaloval na vás, Mojžíš, v němž vy naději máte.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 46, 'Nebo kdybyste věřili Mojžíšovi, věřili byste i mně; neb on o mně psal.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 47, 'Ale poněvadž jeho písmům nevěříte, i kterak slovům mým uvěříte?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 1, 'Potom odšel Ježíš za moře Galilejské neb Tiberiadské.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 2, 'A šel za ním zástup veliký; nebo viděli divy jeho, kteréž činil nad nemocnými.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 3, 'I všel na horu Ježíš, a tam seděl s učedlníky svými.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 4, 'Byla pak blízko velikanoc, svátek Židovský.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 5, 'Tedy pozdvih očí Ježíš, a viděv, že zástup veliký jde k němu, dí Filipovi: Kde nakoupíme chlebů, aby pojedli tito?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 6, '(Ale to řekl, pokoušeje ho; nebo on věděl, co by měl učiniti.)');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 7, 'Odpověděl jemu Filip: Za dvě stě peněz chlebů nepostačí jim, aby jeden každý z nich něco maličko vzal.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 8, 'Dí jemu jeden z učedlníků jeho, Ondřej, bratr Šimona Petra:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 9, 'Jestiť mládenček jeden zde, kterýž má pět chlebů ječných a dvě rybičky. Ale coť jest to mezi tak mnohé?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 10, 'I řekl Ježíš: Rozkažte lidu, ať se usadí. A bylo trávy mnoho na tom místě. I posadilo se mužů v počtu okolo pěti tisíců.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 11, 'Tedy Ježíš vzal ty chleby, a díky učiniv, rozdával učedlníkům, učedlníci pak sedícím; též podobně z těch rybiček, jakž mnoho chtěli.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 12, 'A když byli nasyceni, řekl učedlníkům svým: Zbeřte ty drobty, kteříž zůstali, ať nezhynou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 13, 'I sebrali a naplnili dvanácte košů drobtů z těch pěti chlebů ječných, kteříž pozůstali po těch, kteříž jedli.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 14, 'Ti pak lidé, uzřevše ten div, kterýž učinil Ježíš, pravili: Tento jest jistě prorok, kterýž měl přijíti na svět.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 15, 'Tedy Ježíš věda, že by měli přijíti a chytiti jej, aby ho učinili králem, ušel na horu opět sám jediný.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 16, 'Když pak byl večer, sstoupili učedlníci jeho k moři.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 17, 'A vstoupivše na lodí, plavili se přes moře do Kafarnaum. A bylo již tma, a nepřišel byl Ježíš k nim.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 18, 'Moře pak dutím velikého větru zdvihalo se.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 19, 'A odplavivše se honů jako pětmecítma neb třidceti, uzřeli Ježíše, an chodí po moři, a přibližuje se k lodí. I báli se.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 20, 'On pak řekl jim: Jáť jsem, nebojte se.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 21, 'I vzali ho na lodí ochotně, a hned lodí přiběhla k zemi, do kteréž se plavili.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 22, 'Nazejtří zástup, kterýž byl za mořem, viděv, že jiné lodičky nebylo, než ta jedna, na kterouž byli vstoupili učedlníci jeho, a že Ježíš nebyl všel s učedlníky svými na lodí, ale sami učedlníci jeho byli se plavili,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 23, '(Jiné pak lodí byly připlouly od Tiberiady k tomu místu blízko, kdež byli jedli chléb, když díky učinil Pán,)');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 24, 'Když tedy uzřel zástup, že Ježíše tu není, ani učedlníků jeho, vstoupili i oni na lodí, a přijeli do Kafarnaum, hledajíce Ježíše.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 25, 'A nalezše ho za mořem, řekli jemu: Mistře, kdy jsi sem přišel?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 26, 'Odpověděl jim Ježíš a řekl: Amen, amen pravím vám: Hledáte mne, ne proto že jste divy viděli, ale že jste jedli chleby a nasyceni jste.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 27, 'Pracujte ne o pokrm, kterýž hyne, ale o ten pokrm, kterýž zůstává k životu věčnému, kterýž Syn člověka dá vám. Nebo tohoť potvrdil Bůh Otec.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 28, 'Tedy řekli jemu: Co budeme činiti, abychom dělali dílo Boží?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 29, 'Odpověděl Ježíš a řekl jim: Totoť jest to dílo Boží, abyste věřili v toho, kteréhož on poslal.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 30, 'I řekli jemu: Jakéž pak ty znamení činíš, abychom viděli a věřili tobě? Co děláš?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 31, 'Otcové naši jedli mannu na poušti, jakož psáno jest: Chléb s nebe dal jim jísti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 32, 'Tedy řekl jim Ježíš: Amen, amen pravím vám: Ne Mojžíš dal vám chléb s nebe, ale Otec můj vám dává ten chléb s nebe pravý.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 33, 'Nebo chléb Boží ten jest, kterýž sstupuje s nebe, a dává život světu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 34, 'I řekli jemu: Pane, dávejž nám chléb ten vždycky.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 35, 'Ježíš pak řekl jim: Jáť jsem ten chléb života. Kdož přichází ke mně, nebude nikoli lačněti, a kdož věří ve mne, nebude žízniti nikdy.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 36, 'Ale pověděl jsem vám, anobrž viděli jste mne, a nevěříte.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 37, 'Všecko, což mi dává Otec, ke mně přijde, a toho, kdož ke mně přijde, nevyvrhu ven.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 38, 'Nebo jsem sstoupil s nebe, ne abych činil vůli svou, ale vůli toho, kterýž mne poslal.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 39, 'Tatoť jest pak vůle toho, kterýž mne poslal, Otcova, abych ničeho toho, což mi dal, neztratil, ale vzkřísil to v nejposlednější den.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 40, 'A tatoť jest vůle toho, kterýž mne poslal, aby každý, kdož vidí Syna a věří v něho, měl život věčný. A jáť jej vzkřísím v den nejposlednější.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 41, 'I reptali Židé na něho, že řekl: Já jsem chléb ten, kterýž jsem s nebe sstoupil.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 42, 'A pravili: Zdaliž tento není Ježíš, syn Jozefův, jehož my otce i matku známe? Kterak pak dí tento: S nebe jsem sstoupil?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 43, 'Tedy odpověděl Ježíš a řekl jim: Nerepcete vespolek.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 44, 'Žádný nemůž přijíti ke mně, jediné leč Otec můj, kterýž mne poslal, přitrhl by jej; a jáť jej vzkřísím v den nejposlednější.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 45, 'Psáno jest v prorocích: A budou všickni učeni od Boha. Protož každý, kdož slyšel od Otce a naučil se, jdeť ke mně.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 46, 'Ne že by kdo viděl Otce, jediné ten, kterýž jest od Boha, tenť viděl Otce.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 47, 'Amen, amen pravím vám: Kdož věří ve mne, máť život věčný.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 48, 'Jáť jsem ten chléb života.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 49, 'Otcové vaši jedli mannu na poušti, a zemřeli.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 50, 'Totoť jest chléb ten s nebe sstupující. Kdož by koli jej jedl, neumřeť.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 51, 'Jáť jsem ten chléb živý, kterýž jsem s nebe sstoupil. Bude-li kdo jísti ten chléb, živ bude na věky. A chléb, kterýž já dám, tělo mé jest, kteréž já dám za život světa.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 52, 'Tedy hádali se Židé vespolek, řkouce: Kterak tento může nám dáti tělo jísti?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 53, 'I řekl jim Ježíš: Amen, amen pravím vám: Nebudete-li jísti těla Syna člověka a píti krve jeho, nemáte života v sobě.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 54, 'Kdož jí mé tělo a pije mou krev, máť život věčný, a jáť jej vzkřísím v nejposlednější den.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 55, 'Nebo tělo mé právě jest pokrm, a krev má právě jest nápoj.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 56, 'Kdo jí mé tělo a pije mou krev, ve mně přebývá a já v něm.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 57, 'Jakož mne poslal ten živý Otec, a já živ jsem skrze Otce, tak kdož jí mne, i on živ bude skrze mne.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 58, 'Totoť jest ten chléb, kterýž s nebe sstoupil. Ne jako otcové vaši jedli mannu, a zemřeli. Kdož jí chléb tento, živť bude na věky.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 59, 'Toto mluvil v škole, uče v Kafarnaum.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 60, 'Tedy mnozí z učedlníků jeho, slyševše to, řekli: Tvrdáť jest tato řeč. Kdo ji může slyšeti?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 61, 'Ale věda Ježíš sám v sobě, že by proto reptali učedlníci jeho, řekl jim: To vás uráží?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 62, 'Co pak, kdybyste uzřeli Syna člověka, an vstupuje, kdež prvé byl?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 63, 'Duch jest, kterýž obživuje, těloť nic neprospívá. Slova, kteráž já mluvím vám, Duch jsou a život jsou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 64, 'Ale jsouť někteří z vás, ješto nevěří. Nebo věděl Ježíš od počátku, kdo by byli nevěřící, a kdo by ho měl zraditi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 65, 'I pravil: Protož jsem vám řekl, že žádný nemůže přijíti ke mně, leč by jemu bylo dáno od Otce mého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 66, 'A z toho mnozí z učedlníků jeho odešli zpět, a nechodili s ním více.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 67, 'Tedy řekl Ježíš ke dvanácti: Zdaliž i vy chcete odjíti?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 68, 'I odpověděl jemu Šimon Petr: Pane, k komu půjdeme? Slova věčného života máš.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 69, 'A my jsme uvěřili, a poznali, že jsi ty Kristus, Syn Boha živého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 70, 'Odpověděl jim Ježíš: Však jsem já vás dvanácte vyvolil, a jeden z vás ďábel jest.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 71, 'A to řekl o Jidášovi Šimona Iškariotského; nebo ten jej měl zraditi, byv jeden ze dvanácti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 1, 'Potom pak chodil Ježíš po Galilei; nebo nechtěl býti v Judstvu, proto že ho hledali Židé zabiti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 2, 'A byl blízko svátek Židovský, stánků.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 3, 'Tedy řekli jemu bratří jeho: Vyjdi odsud, a jdi do Judstva, ať i učedlníci tvoji vidí skutky tvé, kteréž činíš.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 4, 'Nižádný zajisté v skrytě nic nedělá, kdož chce vidín býti. Protož ty, činíš-li takové věci, zjev se světu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 5, 'Nebo ani bratří jeho nevěřili v něho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 6, 'I dí jim Ježíš: Čas můj ještě nepřišel, ale čas váš vždycky jest hotov.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 7, 'Nemůžeť vás svět nenáviděti, ale mneť nenávidí; nebo já svědectví vydávám o něm, že skutkové jeho zlí jsou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 8, 'Jděte vy k svátku tomuto. Jáť ještě nepůjdu k svátku tomuto, nebo čas můj se ještě nenaplnil.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 9, 'To pak pověděv jim, zůstal v Galilei.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 10, 'A když odešli bratří jeho, tehdy i on šel k svátku, ne zjevně, ale jako ukrytě.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 11, 'Židé pak hledali ho v svátek, a pravili: Kde jest onen?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 12, 'A mnoho řečí bylo o něm v zástupu. Nebo někteří pravili, že dobrý jest, a jiní pravili: Není, ale svodí zástup.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 13, 'Žádný však o něm nemluvil zjevně pro bázeň Židů.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 14, 'Když pak již polovici svátku se vykonalo, vstoupil Ježíš do chrámu, a učil.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 15, 'I divili se Židé, řkouce: Kterak tento písmo umí, neučiv se?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 16, 'Odpověděl jim Ježíš a řekl: Mé učení neníť mé, ale toho, kterýž mne poslal.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 17, 'Bude-li kdo chtíti vůli jeho činiti, tenť bude uměti rozeznati, jest-li to učení z Boha, čili mluvím já sám od sebe.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 18, 'Kdoť sám od sebe mluví, chvály své vlastní hledá, ale kdož hledá chvály toho, kterýž ho poslal, tenť pravdomluvný jest, a nepravosti v něm není.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 19, 'Však Mojžíš dal vám zákon, a žádný z vás neplní zákona. Proč mne hledáte zamordovati?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 20, 'Odpověděl zástup a řekl: Ďábelství máš. Kdo tě hledá zamordovati?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 21, 'Odpověděl Ježíš a řekl jim: Jeden skutek učinil jsem, a všickni se tomu divíte.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 22, 'Však Mojžíš vydal vám obřízku, (ne že by z Mojžíše byla, ale z otců,) a v sobotu obřezujete člověka.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 23, 'Poněvadž člověk obřízku přijímá v sobotu, aby nebyl rušen zákon Mojžíšův, proč se na mne hněváte, že jsem celého člověka uzdravil v sobotu?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 24, 'Nesuďte podlé osoby, ale spravedlivý soud suďte.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 25, 'Tedy někteří z Jeruzalémských pravili: Zdaliž toto není ten, kteréhož hledají zabiti?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 26, 'A aj, svobodně mluví a nic mu neříkají. Zdali již právě poznali knížata, že tento jest právě Kristus?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 27, 'Ale o tomto víme, odkud jest, Kristus pak když přijde, žádný nebude věděti, odkud by byl.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 28, 'I volal Ježíš v chrámě, uče a řka: I mne znáte, i odkud jsem, víte. A nepřišelť jsem sám od sebe, ale jestiť pravdomluvný ten, kterýž mne poslal, jehož vy neznáte.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 29, 'Ale já znám jej, nebo od něho jsem, a on mne poslal.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 30, 'I hledali ho jíti, ale žádný nevztáhl ruky na něho, nebo ještě byla nepřišla hodina jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 31, 'Z zástupu pak mnozí uvěřili v něho, a pravili: Kristus když přijde, zdali více divů činiti bude nad ty, kteréž tento činí?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 32, 'Slyšeli pak farizeové zástup, an o něm takové věci rozmlouvá, i poslali farizeové a přední kněží {biskupové} služebníky, aby jej jali.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 33, 'Tedy řekl jim: Ještě maličký čas jsem s vámi, potom odejdu k tomu, kterýž mne poslal.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 34, 'Hledati mne budete, ale nenaleznete, a kdež já budu, vy nemůžte přijíti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 35, 'I řekli Židé k sobě vespolek: Kam tento půjde, že my ho nenalezneme? Zdali v rozptýlení pohanů půjde, a bude učiti pohany?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 36, 'Jaká jest to řeč, kterouž promluvil: Hledati mne budete, ale nenaleznete, a kdež já budu, vy nemůžete přijíti?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 37, 'V poslední pak den ten veliký svátku toho, stál Ježíš a volal, řka: Žízní-li kdo, poď ke mně, a napí se.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 38, 'Kdož věří ve mne, jakož dí písmo, řeky z břicha jeho poplynou vody živé.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 39, '(A to řekl o Duchu, kteréhož měli přijíti věřící v něho; nebo ještě nebyl dán Duch svatý, proto že ještě Ježíš nebyl oslaven.)');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 40, 'Tedy mnozí z zástupu uslyševše tu řeč, pravili: Tentoť jest právě prorok ten.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 41, 'Jiní pravili: Tentoť jest Kristus. Ale někteří pravili: Zdaliž z Galilee přijde Kristus?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 42, 'Zdaž nepraví písmo, že z semene Davidova a z Betléma městečka, kdež býval David, přijíti má Kristus?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 43, 'A tak různice v zástupu stala se pro něj.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 44, 'Někteří pak z nich chtěli ho jíti, ale žádný nevztáhl ruky na něj.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 45, 'Tedy přišli služebníci k předním kněžím {biskupům} a k farizeům, kteříž řekli jim: Proč jste ho nepřivedli?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 46, 'Odpověděli ti služebníci: Nikdy tak člověk nemluvil, jako tento člověk.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 47, 'I odpověděli jim farizeové: Zdali i vy jste svedeni?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 48, 'Zdaliž kdo z knížat uvěřil v něho aneb z farizeů?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 49, 'Než zástup ten, kterýž nezná zákona. Zlořečeníť jsou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 50, 'I dí jim Nikodém, ten kterýž byl přišel k němu v noci, byv jeden z nich:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 51, 'Zdali zákon náš soudí člověka, leč prvé uslyší od něho a zví, co by činil?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 52, 'Odpověděli a řekli jemu: Nejsi-li i ty Galilejský? Ptej se a viz, žeť prorok z Galilee nepovstal.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 53, 'I šel jeden každý do domu svého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 1, 'Ježíš pak odšel na horu Olivetskou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 2, 'Potom na úsvitě zase přišel do chrámu, a všecken lid sšel se k němu. I posadiv se, učil je.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 3, 'I přivedli k němu zákonníci a farizeové ženu v cizoložstvu popadenou, a postavivše ji v prostředku,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 4, 'Řekli jemu: Mistře, tato žena jest postižena při skutku, když cizoložila.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 5, 'A v zákoně Mojžíš přikázal nám takové kamenovati. Ty pak co pravíš?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 6, 'A to řekli, pokoušejíce ho, aby jej mohli obžalovati. Ježíš pak skloniv se dolů, prstem psal na zemi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 7, 'A když se nepřestávali otazovati jeho, zdvihl se a řekl jim: Kdo jest z vás bez hříchu, nejprv hoď na ni kamenem.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 8, 'A opět schýliv se, psal na zemi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 9, 'A oni uslyševše to, a v svědomích svých obvinění byvše, jeden po druhém odcházeli, počavše od starších až do posledních. I zůstal tu Ježíš sám, a ta žena u prostřed stojeci.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 10, 'A pozdvih se Ježíš, a žádného neviděv, než tu ženu, řekl jí: Ženo, kde jsou ti, kteříž na tebe žalovali? Žádný-li tě neodsoudil?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 11, 'Kteráž řekla: Žádný, Pane. I řekl jí Ježíš: Aniž já tebe odsuzuji. Jdiž a nehřeš více.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 12, 'Tedy Ježíš opět jim mluvil, řka: Já jsem světlo světa. Kdož mne následuje, nebude choditi v temnostech, ale bude míti světlo života.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 13, 'I řekli jemu farizeové: Ty sám o sobě svědectví vydáváš, svědectví tvé není pravé.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 14, 'Odpověděl Ježíš a řekl jim: Ačkoli já svědectví vydávám sám o sobě, pravé jest svědectví mé; nebo vím, odkud jsem přišel, a kam jdu. Ale vy nevíte, odkud jsem přišel, aneb kam jdu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 15, 'Vy podlé těla soudíte, já nesoudím žádného.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 16, 'A bychť pak i já soudil, soud můj jest pravý; nebo nejsem sám, ale jsem já a ten, kterýž mne poslal, Otec.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 17, 'A v zákoně vašem psáno jest: Že dvou člověků svědectví pravé jest.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 18, 'Jáť svědectví vydávám sám o sobě, a svědectví vydává o mně ten, kterýž mne poslal, Otec.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 19, 'Tedy řekli jemu: Kdež jest ten tvůj otec? Odpověděl Ježíš: Aniž mne znáte, ani Otce mého. Kdybyste mne znali, i Otce mého znali byste.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 20, 'Tato slova mluvil Ježíš u pokladnice, uče v chrámě, a žádný ho nejal, nebo ještě byla nepřišla hodina jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 21, 'I řekl jim opět Ježíš: Já jdu, a hledati budete mne, a v hříchu svém zemřete. Kam já jdu, vy nemůžete přijíti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 22, 'I pravili Židé: Zdali se sám zabije, že praví: Kam já jdu, vy nemůžete přijíti?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 23, 'I řekl jim: Vy z důlu jste, já s hůry jsem. Vy jste z tohoto světa, já nejsem z světa tohoto.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 24, 'Protož jsem řekl vám: Že zemřete v hříších svých. Nebo jestliže nebudete věřiti, že já jsem, zemřete v hříších svých.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 25, 'I řekli jemu: Kdo jsi ty? I řekl jim Ježíš: To, což z počátku pravím vám.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 26, 'Mnohoť mám o vás mluviti a souditi, ale ten, kterýž mne poslal, pravdomluvný jest, a já, což jsem slyšel od něho, to mluvím na světě.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 27, 'Ale neporozuměli, že by o Otci pravil jim.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 28, 'Protož řekl jim Ježíš: Když povýšíte Syna člověka, tehdy poznáte, že já jsem. A sám od sebe nic nečiním, ale jakž mne naučil Otec můj, tak mluvím.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 29, 'A ten, kterýž mne poslal, se mnou jest. Neopustilť mne samého Otec; nebo což jest jemu libého, to já činím vždycky.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 30, 'Ty věci když mluvil, mnozí uvěřili v něho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 31, 'Tedy řekl Ježíš těm Židům, kteříž uvěřili jemu: Jestliže vy zůstanete v řeči mé, právě učedlníci moji budete.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 32, 'A poznáte pravdu, a pravda vás vysvobodí.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 33, 'I odpověděli jemu: Símě Abrahamovo jsme, a žádnému jsme nesloužili nikdy. I kterakž ty díš: že svobodní budete?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 34, 'Odpověděl jim Ježíš: Amen, amen pravím vám: Že každý, kdož činí hřích, služebník jest hřícha.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 35, 'A služebník nezůstává v domě na věky; Syn zůstává na věky.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 36, 'Protož jestližeť vás Syn vysvobodí, právě svobodní budete.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 37, 'Vím, že jste símě Abrahamovo, ale hledáte mne zabiti; nebo řeč má nemá místa u vás.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 38, 'Já, což jsem viděl u Otce svého, mluvím; i vy tedy, co jste viděli u otce svého, činíte.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 39, 'Odpověděli a řekli jemu: Otec náš jest Abraham. Dí jim Ježíš: Kdybyste synové Abrahamovi byli, činili byste skutky Abrahamovy.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 40, 'Ale nyní hledáte mne zabiti, člověka toho, kterýž jsem pravdu mluvil vám, kterouž jsem slyšel od Boha. Tohoť Abraham nečinil.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 41, 'Vy činíte skutky otce svého. I řekli jemu: Myť z smilstva nejsme zplozeni, jednohoť Otce máme, Boha.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 42, 'Tedy řekl jim Ježíš: Byť Bůh Otec váš byl, milovali byste mne. Nebo já jsem z Boha pošel, a přišel jsem; aniž jsem sám od sebe přišel, ale on mne poslal.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 43, 'Proč mluvení mého nechápáte? Proto že slyšeti nemůžete řeči mé.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 44, 'Vy z otce ďábla jste, a žádosti otce svého chcete činiti. On byl vražedlník od počátku, a v pravdě nestál; nebo pravdy v něm není. Když mluví lež, z svého vlastního mluví; nebo lhář jest a otec lži.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 45, 'Já pak že pravdu pravím, nevěříte mi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 46, 'Kdo z vás uviní mne z hříchu? A poněvadž pravdu pravím, proč vy mi nevěříte?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 47, 'Kdo z Boha jest, slova Boží slyší; protož vy neslyšíte, že z Boha nejste.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 48, 'Tedy odpověděli Židé a řekli jemu: Zdaliž my dobře nepravíme, že jsi ty Samaritán, a ďábelství máš?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 49, 'Odpověděl Ježíš: Jáť ďábelství nemám, ale ctím Otce svého; než vy jste mne neuctili.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 50, 'Jáť pak nehledám chvály své; jestiť, kdo hledá a soudí.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 51, 'Amen, amen pravím, vám: Bude-li kdo zachovávati slovo mé, smrti neuzří na věky.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 52, 'Tedy řekli mu Židé: Nyní jsme poznali, že ďábelství máš. Abraham umřel i proroci, a ty pravíš: Bude-li kdo zachovávati řeč mou, smrti neokusí na věky.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 53, 'Zdali jsi ty větší otce našeho Abrahama, kterýž umřel? I proroci zemřeli. Kým ty se činíš?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 54, 'Odpověděl Ježíš: Chválím-liť já se sám, chvála má nic není. Jestiť Otec můj, kterýž mne chválí, o němž vy pravíte, že Bůh váš jest.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 55, 'Ale nepoznali jste ho, já pak jej znám. A kdybych řekl, že ho neznám, byl bych podobný vám, lhář. Ale známť jej, a řeč jeho zachovávám.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 56, 'Abraham, otec váš, veselil se, aby viděl den můj, i viděl, a radoval se.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 57, 'Tedy řekli jemu Židé: Padesáti let ještě nemáš, a Abrahama jsi viděl?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 58, 'Řekl jim Ježíš: Amen, amen pravím vám: Prvé nežli Abraham byl, já jsem.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 59, 'I zchápali kamení, aby házeli na něj. Ježíš pak skryl se, a prošed skrze ně, vyšel z chrámu, a tak odšel.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 1, 'A pomíjeje, uzřel člověka slepého od narození.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 2, 'I otázali se ho učedlníci jeho, řkouce: Mistře, kdo zhřešil, tento-li, čili rodičové jeho, že se slepý narodil?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 3, 'Odpověděl Ježíš: Ani tento zhřešil, ani rodičové jeho, ale aby zjeveni byli skutkové Boží na něm.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 4, 'Jáť musím dělati dílo toho, kterýž mne poslal, dokudž den jest. Přicházíť noc, když žádný nebude moci dělati.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 5, 'Dokudž jsem na světě, světlo jsem světa.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 6, 'To pověděv, plinul na zemi, a učinil bláto z sliny, i pomazal tím blátem oči slepého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 7, 'A řekl jemu: Jdi, umej se v rybníku Siloe, což se vykládá: Poslaný. A on šel a umyl se, i přišel, vida.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 8, 'Sousedé pak a ti, kteříž jej prvé vídali slepého, řekli: Není-liž toto ten, kterýž sedával a žebrával?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 9, 'Jiní pravili, že ten jest, a jiní, že jest podoben k němu. Ale on pravil: Já jsem.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 10, 'Tedy řekli jemu: Kterak jsou otevříny oči tvé?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 11, 'On odpověděl a řekl: Člověk ten, kterýž slove Ježíš, bláto učinil, a pomazal očí mých, a řekl mi: Jdi k rybníku Siloe, a umej se. I odšed a umyv se, prohlédl jsem.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 12, 'I řekli jemu: Kde jest ten? Řekl: Nevím.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 13, 'Tedy přivedli toho, kterýž někdy byl slepý, k farizeům.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 14, 'Byla pak sobota, když Ježíš učinil bláto, a otevřel oči jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 15, 'I otázali se ho opět i farizeové, kterak by prozřel. On pak řekl jim: Bláto položil na oči mé, a umyl jsem se, i vidím.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 16, 'Tedy někteří z farizeů řekli: Ten člověk není z Boha, nebo neostříhá soboty. Jiní pravili: Kterak může člověk hříšný takové divy činiti? I byla různice mezi nimi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 17, 'Řekli opět slepému: Co ty o něm pravíš, poněvadž otevřel oči tvé? A on řekl: Že prorok jest.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 18, 'I nevěřili Židé o něm, by slepý býval a prozřel, až povolali rodičů toho, kterýž byl prozřel.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 19, 'A otázali se jich, řkouce: Jest-li tento syn váš, o kterémž vy pravíte, že by se slepý narodil? Kterakž pak nyní vidí?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 20, 'Odpověděli jim rodičové jeho a řekli: Vímeť, že tento jest syn náš, a že se slepý narodil.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 21, 'Ale kterak nyní vidí, nevíme; aneb kdo otevřel oči jeho, myť nevíme. Máť léta, ptejte se ho, on sám za sebe mluviti bude.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 22, 'Tak mluvili rodičové jeho, že se báli Židů; nebo již tak byli uložili Židé, aby, kdož by ho koli vyznal Kristem, vyobcován byl ze školy.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 23, 'Protož řekli rodičové jeho: Máť léta, ptejte se jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 24, 'Tedy zavolali po druhé člověka toho, kterýž býval slepý, a řekli jemu: Vzdej chválu Bohu. My víme, že člověk ten hříšník jest.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 25, 'I odpověděl on a řekl: Jest-li hříšník, nevím, než to vím, že byv slepý, nyní vidím.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 26, 'I řekli jemu opět: Coť učinil? Kterak otevřel oči tvé?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 27, 'Odpověděl jim: Již jsem vám pověděl, a neslyšeli jste? Což opět chcete slyšeti? Zdaliž i vy chcete učedlníci jeho býti?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 28, 'I zlořečili jemu a řekli: Ty jsi učedlník jeho, ale my jsme Mojžíšovi učedlníci.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 29, 'My víme, že Mojžíšovi mluvil Bůh, tento pak nevíme, odkud jest.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 30, 'Odpověděl ten člověk a řekl jim: Toť jest jistě divná věc, že vy nevíte, odkud jest, a otevřel oči mé.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 31, 'Víme pak, že Bůh hříšníků neslyší, ale kdo by ctitel Boží byl, a vůli jeho činil, tohoť slyší.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 32, 'Od věků není slýcháno, aby kdo otevřel oči slepého narozeného.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 33, 'Byť tento nebyl od Boha, nemohlť by nic učiniti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 34, 'Odpověděli a řekli jemu: Ty jsi všecken se v hříších narodil, a ty nás učíš? I vyhnali jej ven.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 35, 'Uslyšel pak Ježíš, že jej vyhnali ven. A když jej nalezl, řekl jemu: Věříš-liž ty v Syna Božího?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 36, 'Odpověděl on a řekl: I kdož jest, Pane, abych věřil v něho?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 37, 'I řekl jemu Ježíš: I viděl jsi ho, a kterýž mluví s tebou, onť jest.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 38, 'A on řekl: Věřím, Pane, a klaněl se jemu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 39, 'I řekl jemu Ježíš: Na soud přišel jsem já na tento svět, aby ti, kteříž nevidí, viděli, a ti, kteříž vidí, aby slepí byli.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 40, 'I uslyšeli to někteří z farizeů, kteříž s ním byli, a řekli jemu: Zdali i my slepí jsme?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 41, 'Řekl jim Ježíš: Byste slepí byli, hříchu byste neměli; ale nyní pravíte: Vidíme, protož hřích váš zůstává.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 1, 'Amen, amen pravím vám: Kdož nevchází dveřmi do ovčince ovcí, ale vchází jinudy, ten zloděj jest a lotr.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 2, 'Ale kdož vchází dveřmi, pastýř jest ovcí.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 3, 'Tomuť vrátný otvírá, a ovce hlas jeho slyší, a on svých vlastních ovec ze jména povolává, a vyvodí je.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 4, 'A jakž ovce své vlastní vypustí, před nimi jde, a ovce jdou za ním; nebo znají hlas jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 5, 'Cizího pak nikoli následovati nebudou, ale utekou od něho; nebo neznají hlasu cizích.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 6, 'To podobenství pověděl jim Ježíš, ale oni nevěděli, co by to bylo, což jim mluvil.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 7, 'Tedy opět řekl jim Ježíš: Amen, amen pravím vám: Že já jsem dvéře ovcí.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 8, 'Všickni, kolikž jich koli přede mnou příšlo, zloději jsou a lotři, ale neslyšeli jich ovce.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 9, 'Já jsem dvéře. Skrze mne všel-li by kdo, spasen bude, a vejde i vyjde, a pastvu nalezne.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 10, 'Zloděj nepřichází, než aby kradl a mordoval a hubil; já jsem přišel, aby život měly, a hojně měly.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 11, 'Já jsem ten pastýř dobrý. Dobrý pastýř duši svou pokládá za ovce.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 12, 'Ale nájemník a ten, kterýž není pastýř, jehož nejsou ovce vlastní, vida vlka, an jde, i opouští ovce i utíká, a vlk lapá a rozhání ovce.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 13, 'Nájemník pak utíká; nebo nájemník jest, a nemá péče o ovce.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 14, 'Já jsem ten dobrý pastýř, a známť své, a znajíť mne mé.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 15, 'Jakož mne zná Otec, a já znám Otce, a duši svou pokládám za ovce.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 16, 'A mámť i jiné ovce, kteréž nejsou z tohoto ovčince. I tyť musím přivesti; nebo hlas můj slyšeti budou. A budeť jeden ovčinec a jeden pastýř.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 17, 'Protož mne Otec miluje, že já pokládám duši svou, abych ji zase vzal.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 18, 'Nižádnýť jí nebéře ode mne, ale já pokládám ji sám od sebe. Mám moc položiti ji, a mám moc zase vzíti ji. To přikázaní vzal jsem od Otce svého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 19, 'Tedy stala se opět různice mezi Židy pro ty řeči.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 20, 'A pravili mnozí z nich: Ďábelství má a blázní. Co ho posloucháte?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 21, 'Jiní pravili: Tato slova nejsou ďábelství majícího. Zdaliž ďábelství může slepých oči otvírati?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 22, 'Bylo pak posvícení v Jeruzalémě, a zima byla.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 23, 'I procházel se Ježíš v chrámě po síňci Šalomounově.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 24, 'Tedy obstoupili jej Židé, a řekli jemu: Dokudž duši naši držíš: Jestliže jsi ty Kristus, pověz nám zjevně.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 25, 'Odpověděl jim Ježíš: Pověděl jsem vám, a nevěříte. Skutkové, kteréž já činím ve jménu Otce svého, tiť svědectví vydávají o mně.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 26, 'Ale vy nevěříte, nebo nejste z ovcí mých, jakož jsem vám pověděl.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 27, 'Ovceť mé hlas můj slyší, a já je znám, a následujíť mne.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 28, 'A jáť život věčný dávám jim, a nezahynouť na věky, aniž jich kdo vytrhne z ruky mé.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 29, 'Otec můj, kterýž mi je dal, větší jest nade všecky, a žádnýť jich nemůže vytrhnouti z ruky Otce mého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 30, 'Já a Otec jedno jsme.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 31, 'Tedy zchápali opět kamení Židé, aby jej kamenovali.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 32, 'Odpověděl jim Ježíš: Mnohé dobré skutky ukázal jsem vám od Otce svého. Pro který z těch skutků kamenujete mne?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 33, 'Odpověděli jemu Židé, řkouce. Pro dobrý skutek tebe nekamenujeme, ale pro rouhání, totiž že ty, člověk jsa, děláš se Bohem.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 34, 'Odpověděl jim Ježíš: Však psáno jest v zákoně vašem: Já jsem řekl: Bohové jste.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 35, 'Poněvadž ty nazval bohy, k nimž řeč Boží stala se, a nemůže zrušeno býti písmo,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 36, 'Mně pak, kteréhož posvětil Otec a poslal na svět, vy pravíte: Rouháš se, že jsem řekl: Syn Boží jsem?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 37, 'Nečiním-liť skutků Otce svého, nevěřte mi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 38, 'Pakliť činím, byste pak mně nevěřili, skutkům věřte, abyste poznali a věřili, že Otec ve mně jest, a já v něm.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 39, 'Tedy opět hledali ho jíti, ale vyšel z rukou jejich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 40, 'I odšel opět za Jordán na to místo, kdež nejprvé Jan křtil, a pozůstal tam.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 41, 'I přišli k němu mnozí, a pravili: Jan zajisté žádného divu neučinil, ale všecko, cožkoli mluvil Jan o tomto, pravé bylo.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 42, 'A mnozí tam uvěřili v něho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 1, 'Byl pak nemocen nějaký Lazar z Betany, z městečka Marie a Marty, sestry její.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 2, 'A to byla ta Maria, kteráž pomazala Pána mastí, a vytřela nohy jeho vlasy svými, jejíž bratr Lazar byl nemocen.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 3, 'Tedy poslaly k němu ty sestry, řkouce: Pane, aj, ten, kteréhož miluješ, nemocen jest.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 4, 'A uslyšav to Ježíš, řekl: Nemoc ta není k smrti, ale pro slávu Boží, aby oslaven byl Syn Boží skrze ni.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 5, 'Miloval pak Ježíš Martu i sestru její i Lazara.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 6, 'A jakž uslyšel, že by nemocen byl, tedy pozůstal za dva dni na tom místě, kdež byl.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 7, 'Potom pak dí učedlníkům: Poďme zase do Judstva.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 8, 'Řekli jemu učedlníci: Mistře, nyní hledali tě Židé kamenovati, a zase tam chceš jíti?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 9, 'Odpověděl Ježíš: Zdaliž není dvanácte hodin za den? Chodí-li kdo ve dne, neurazí se; nebo světlo tohoto světa vidí.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 10, 'Pakliť by kdo chodil v noci, urazíť se; nebo světla není v něm.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 11, 'To pověděl, a potom dí jim: Lazar, přítel náš, spí, ale jduť, abych jej ze sna probudil.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 12, 'I řekli učedlníci jeho: Pane, spí-liť, zdráv bude.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 13, 'Ale Ježíš řekl o smrti jeho, oni pak domnívali se, že by o spání sna mluvil.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 14, 'Tedy řekl jim Ježíš zjevně: Lazar umřel.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 15, 'A raduji se pro vás, že jsem tam nebyl, abyste věřili. Ale poďme k němu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 16, 'I řekl Tomáš, kterýž slove Didymus, spoluučedlníkům: Poďme i my, abychom zemřeli s ním.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 17, 'Přišel tedy Ježíš, a nalezl ho již čtyři dni v hrobě pochovaného.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 18, 'Byla pak Betany blízko od Jeruzaléma, okolo honů patnácte.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 19, 'Mnozí pak z Židů byli přišli k Martě a Marii, aby je těšili pro bratra jejich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 20, 'Tedy Marta, jakž uslyšela, že Ježíš jde, vyšla proti němu, ale Maria doma seděla.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 21, 'I řekla Marta Ježíšovi: Pane, kdybys ty byl zde, bratr můj byl by neumřel.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 22, 'Ale i nyníť vím, že cožkoli požádal bys od Boha, dá tobě Bůh.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 23, 'Dí jí Ježíš: Vstaneť bratr tvůj.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 24, 'Řekla jemu Marta: Vím, že vstane při vzkříšení v den nejposlednější.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 25, 'Řekl jí Ježíš: já jsem vzkříšení i život. Kdo věří ve mne, byť pak i umřel, živ bude.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 26, 'A každý, kdož jest živ, a věří ve mne, neumřeť na věky. Věříš-li tomu?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 27, 'Řekla jemu: Ovšem, Pane, já jsem uvěřila, že jsi ty Kristus, Syn Boží, kterýž měl přijíti na svět.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 28, 'A když to pověděla, odešla a zavolala tajně Marie, sestry své, řkuci: Mistr zde jest, a volá tebe.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 29, 'Ona jakž uslyšela, vstala rychle, a šla k němu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 30, 'Ještě pak byl Ježíš nepřišel do městečka, ale byl na tom místě, kdež vyšla byla proti němu Marta.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 31, 'Tedy Židé, kteříž s ní byli v domě, a těšili ji, viděvše Marii, že rychle vstala a vyšla, šli za ní, řkouce: Jde k hrobu, aby tam plakala.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 32, 'Ale Maria, když tam přišla, kdež byl Ježíš, uzřevši jej, padla k nohám jeho, řkuci jemu: Pane, bys ty byl zde, bratr můj byl by neumřel.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 33, 'Ježíš pak jakž uzřel, ana pláče, i Židy, kteříž byli s ní přišli, ani plačí, zastonal duchem, a zkormoutil se.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 34, 'A řekl: Kdež jste jej položili? Řkou jemu: Pane, poď a pohleď.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 35, 'I zaplakal Ježíš.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 36, 'Tedy řekli Židé: Aj, kterak ho miloval!');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 37, 'Někteří pak z nich řekli: Nemohl-liž tento, kterýž otevřel oči slepého, učiniti aby tento neumřel?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 38, 'Ježíš pak opět zastonav sám v sobě, přišel k hrobu. Byla pak jeskyně, a kámen byl svrchu položen na ni.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 39, 'Dí Ježíš: Zdvihněte kámen. Řekla jemu Marta, sestra toho mrtvého: Pane, jižť smrdí; nebo čtyři dni v hrobě jest.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 40, 'Dí jí Ježíš: Všakť jsem řekl, že budeš-li věřiti, uzříš slávu Boží.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 41, 'Tedy zdvihli kámen, kdež byl ten mrtvý pochován. Ježíš pak pozdvihl zhůru očí a řekl: Otče, děkuji tobě, že jsi mne slyšel.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 42, 'Já zajisté vím, že mne vždycky slyšíš, ale pro zástup, kterýž okolo stojí, řekl jsem, aby věřili, že jsi ty mne poslal.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 43, 'A to pověděv, zavolal hlasem velikým: Lazaře, poď ven.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 44, 'I vyšel ten, kterýž byl umřel, maje svázané ruce i nohy rouchami, a tvář jeho šatem byla obvinuta. Řekl jim Ježíš: Rozvěžtež jej, a nechte, ať odejde.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 45, 'Tedy mnozí z Židů, kteříž byli přišli k Marii, viděvše, co učinil Ježíš, uvěřili v něho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 46, 'Někteří pak z nich odešli k farizeům, a pověděli jim, co učinil Ježíš.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 47, 'I sešli se přední kněží {biskupové} a farizeové v radu, a pravili: Co činíme? Nebo tento člověk divy mnohé činí.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 48, 'Necháme-li ho tak, všickni uvěří v něho, i přijdou Římané, a odejmou místo naše i lid.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 49, 'Jeden pak z nich, Kaifáš, nejvyšším knězem {biskupem} byv toho léta, řekl jim: Vy nic nevíte,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 50, 'Aniž přemyšlujete, že jest užitečné nám, aby jeden člověk umřel za lid, a ne, aby všecken tento národ zahynul.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 51, 'Toho pak neřekl sám od sebe, ale nejvyšším knězem {biskupem} byv léta toho, prorokoval, že měl Ježíš umříti za tento národ.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 52, 'A netoliko za tento národ, ale také, aby syny Boží rozptýlené shromáždil v jedno.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 53, 'Protož od toho dne radu společně drželi, aby jej zabili.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 54, 'Ježíš pak již nechodil zjevně mezi Židy, ale odšel odtud do krajiny blízko pouště, do města, kteréž slove Efraim, a tu bydlil s učedlníky svými.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 55, 'Byla pak blízko velikanoc Židovská. I šli mnozí do Jeruzaléma z krajiny té před velikonocí, aby se očistili.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 56, 'I hledali Ježíše, a rozmlouvali vespolek, v chrámě stojíce: Co se vám zdá, že nepřišel k svátku?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 57, 'Vydali pak byli přední kněží {biskupové} a farizeové mandát, jestliže by kdo zvěděl, kde by byl, aby pověděl, aby jej jali.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 1, 'Tedy Ježíš šestý den před velikonocí přišel do Betany, kdež byl Lazar ten, kterýž byl umřel, jehož vzkřísil z mrtvých.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 2, 'I připravili jemu tu večeři, a Marta posluhovala, Lazar pak byl jeden z stolících s ním.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 3, 'Maria pak vzavši libru masti drahé z nardu výborného, pomazala noh Ježíšových, a vytřela vlasy svými nohy jeho. I naplněn jest dům vůní té masti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 4, 'Tedy řekl jeden z učedlníků jeho, Jidáš Šimona Iškariotského, kterýž jej měl zraditi:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 5, 'Proč tato mast není prodána za tři sta peněz, a není dáno chudým?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 6, 'To pak řekl, ne že by měl péči o chudé, ale že zloděj byl, a měšec měl, a to, což do něho kladeno bylo, nosil.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 7, 'Tedy řekl Ježíš: Nech jí, ke dni pohřbu mého zachovala to.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 8, 'Nebo chudé vždycky máte s sebou, ale mne ne vždycky míti budete.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 9, 'Zvěděl pak zástup veliký z Židů, že by tu byl. I přišli, ne pro Ježíše toliko, ale také aby Lazara viděli, kteréhož byl vzkřísil z mrtvých.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 10, 'Radili se pak přední kněží {biskupové}, aby i Lazara zamordovali.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 11, 'Nebo mnozí z Židů odcházeli pro něho, a uvěřili v Ježíše.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 12, 'Nazejtří mnohý zástup, kterýž byl přišel k svátku, když uslyšeli, že Ježíš jde do Jeruzaléma,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 13, 'Nabrali ratolestí palmových, a vyšli proti němu, a volali: Hosanna, požehnaný, kterýž se béře ve jménu Páně, král Izraelský.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 14, 'I dostav Ježíš oslátka, vsedl na ně, jakož psáno jest:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 15, 'Neboj se, dcero Sionská, aj, král tvůj béře se, na oslátku sedě.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 16, 'Tomu pak nesrozuměli učedlníci jeho sprvu, ale když oslaven byl Ježíš, tedy se rozpomenuli, že to psáno bylo o něm, a že jemu to učinili.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 17, 'Vydával pak svědectví zástup, kterýž byl s ním, že Lazara povolal z hrobu, a vzkřísil jej z mrtvých.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 18, 'Protož i v cestu vyšel jemu zástup, když slyšeli, že by ten div učinil.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 19, 'Tedy farizeové pravili mezi sebou: Vidíte-li, že nic neprospíváte? Aj, svět postoupil po něm.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 20, 'Byli pak někteří Řekové z těch, kteříž přicházívali, aby se modlili v svátek.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 21, 'Ti tedy přistoupili k Filipovi, kterýž byl od Betsaidy Galilejské, a prosili ho, řkouce: Pane, chtěli bychom Ježíše viděti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 22, 'Přišel Filip a pověděl Ondřejovi, Ondřej pak zase a Filip pověděli Ježíšovi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 23, 'A Ježíš odpověděl jim, řka: Přišlať hodina, aby oslaven byl Syn člověka.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 24, 'Amen, amen pravím vám: Zrno pšeničné padna v zemi, neumře-li, onoť samo zůstane, a pakliť umře, mnohý užitek přinese.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 25, 'Kdož miluje duši svou, ztratíť ji; a kdož nenávidí duše své na tomto světě, k životu věčnému ostříhá jí.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 26, 'Slouží-li mi kdo, následujž mne; a kdež jsem já, tuť i můj služebník bude. A bude-li mi kdo sloužiti, poctíť ho Otec.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 27, 'Nyní duše má zkormoucena jest, a což dím? Otče, vysvoboď mne z této hodiny. Ale proto jsem přišel k hodině této.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 28, 'Otče, oslaviž jméno své. Tedy přišel hlas s nebe: I oslavil jsem, i ještě oslavím.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 29, 'Ten pak zástup, kterýž tu stál a slyšel, pravil: Zahřmělo. Jiní pravili: Anděl k němu mluvil.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 30, 'Odpověděl Ježíš a řekl: Ne pro mneť hlas tento se stal, ale pro vás.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 31, 'Nyníť jest soud světa tohoto, nyní kníže světa tohoto vyvrženo bude ven.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 32, 'A já budu-liť povýšen od země, všecky potáhnu k sobě.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 33, '(To pak pověděl, znamenaje, kterou by smrtí měl umříti.)');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 34, 'Odpověděl jemu zástup: My jsme slýchali z zákona, že Kristus zůstává na věky, a kterakž ty pravíš, že musí býti povýšen Syn člověka? Kdo jest to Syn člověka?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 35, 'Tedy řekl jim Ježíš: Ještě na malý čas světlo s vámi jest. Choďte, dokud světlo máte, ať vás tma nezachvátí; nebo kdo chodí ve tmách, neví, kam jde.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 36, 'Dokud světlo máte, věřte v světlo, abyste synové světla byli. Toto pověděl Ježíš, a odšed, skryl se před nimi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 37, 'A ačkoli tak mnohá znamení činil před nimi, však neuvěřili v něho,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 38, 'Aby se naplnila řeč Izaiáše proroka, kterouž pověděl: Pane, kdo uvěřil kázaní našemu, a rámě Páně komu jest zjeveno?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 39, 'Protoť nemohli věřiti, že opět Izaiáš řekl:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 40, 'Oslepil oči jejich, a zatvrdil srdce jejich, aby očima neviděli, a srdcem nerozuměli, a neobrátili se, abych jich neuzdravil.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 41, 'To pověděl Izaiáš, když viděl slávu jeho, a mluvil o něm.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 42, 'A ačkoli mnozí i z knížat uvěřili v něho, však pro farizee nevyznávali, aby ze školy nebyli vyobcování.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 43, 'Nebo milovali slávu lidskou více než slávu Boží.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 44, 'Ježíš pak zvolal a řekl: Kdo věří ve mne, ne ve mneť věří, ale v toho, kterýž mne poslal.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 45, 'A kdož vidí mne, vidí toho, kterýž mne poslal.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 46, 'Já světlo na svět jsem přišel, aby žádný, kdož věří ve mne, ve tmě nezůstal.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 47, 'A slyšel-liť by kdo slova má, a nevěřil by, jáť ho nesoudím; nebo nepřišel jsem, abych soudil svět, ale abych spasil svět.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 48, 'Kdož mnou pohrdá, a nepřijímá slov mých, máť, kdo by jej soudil. Slova, kteráž jsem mluvil, tať jej souditi budou v nejposlednější den.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 49, 'Nebo já sám od sebe jsem nemluvil, ale ten, kterýž mne poslal, Otec, on mi přikázaní dal, co bych měl praviti a mluviti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 50, 'A vím, že přikázaní jeho jest život věčný. A protož, což já mluvím, jakž mi pověděl Otec, takť mluvím.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 1, 'Před svátkem pak velikonočním, věda Ježíš, že přišla hodina jeho, aby šel z tohoto světa k Otci, milovav své, kteříž byli na světě, až do konce je miloval.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 2, 'A když večeřeli, (a ďábel již byl vnukl v srdce Jidáše Šimona Iškariotského, aby jej zradil,)');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 3, 'Věda Ježíš, že jemu Otec všecko v ruce dal, a že od Boha vyšel a k Bohu jde,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 4, 'Vstal od večeře, a složil roucho, a vzav rouchu, přepásal se.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 5, 'Potom nalil vody do medenice, i počal umývati nohy učedlníků a vytírati rouchou, kterouž byl přepásán.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 6, 'Tedy přišel k Šimonovi Petrovi, a on řekl jemu: Pane, ty mi chceš nohy mýti?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 7, 'Odpověděl Ježíš a řekl jemu: Co já činím, ty nevíš nyní, ale potom zvíš.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 8, 'Dí jemu Petr: Nebudeš ty mýti noh mých na věky. Odpověděl jemu Ježíš: Neumyji-liť tebe, nebudeš míti dílu se mnou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 9, 'Dí jemu Šimon Petr: Pane, netoliko nohy mé, ale i ruce i hlavu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 10, 'Řekl jemu Ježíš: Kdož jest umyt, nepotřebuje, než aby nohy umyl; nebo čist jest všecken. I vy čisti jste, ale ne všickni.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 11, 'Nebo věděl o zrádci svém; protož řekl: Ne všickni čisti jste.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 12, 'Když pak umyl nohy jejich, a vzal roucho své, posadiv se za stůl zase, řekl jim: Víte-liž, co jsem učinil vám?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 13, 'Vy nazýváte mne Mistrem a Pánem, a dobře pravíte, jsemť zajisté.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 14, 'Poněvadž tedy já umyl jsem nohy vaše, Pán a Mistr, i vy máte jeden druhému nohy umývati.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 15, 'Příklad zajisté dal jsem vám, abyste, jakož jsem já učinil vám, i vy činili.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 16, 'Amen, amen pravím vám: Není služebník větší nad pána svého, ani posel větší nežli ten, kdož jej poslal.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 17, 'Znáte-li tyto věci, blahoslavení jste, budete-li je činiti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 18, 'Ne o všechť vás pravím. Já vím, které jsem vyvolil, ale musíť se naplniti písmo: Ten, kdož jí chléb se mnou, pozdvihl proti mně paty své.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 19, 'Nyní pravím, vám, prvé než by se stalo, abyste, když se stane, uvěřili, že já jsem.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 20, 'Amen, amen pravím vám: Kdo přijímá toho, kohož bych já poslal, mneť přijímá; a kdož mne přijímá, přijímá toho, kterýž mne poslal.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 21, 'A to pověděv Ježíš, zkormoutil se v duchu, a osvědčil, řka: Amen, amen pravím vám, že jeden z vás mne zradí.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 22, 'Tedy učedlníci vzhlédali na sebe vespolek, pochybujíce, o kom by to pravil.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 23, 'Byl pak jeden z učedlníků Ježíšových, kterýž zpolehl na klíně jeho, ten, jehož miloval Ježíš.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 24, 'Protož tomu návěští dal Šimon Petr, aby se zeptal, kdo by to byl, o němž praví.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 25, 'A on odpočívaje na prsech Ježíšových, řekl jemu: Pane, kdo jest?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 26, 'Odpověděl Ježíš: Ten jest, komuž já omočené skyvy chleba podám. A omočiv skyvu chleba, podal Jidášovi, synu Šimona Iškariotského.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 27, 'A hned po té skyvě chleba vstoupil do něho satan. I řekl jemu Ježíš: Co činíš, čiň spěšně.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 28, 'Tomu pak žádný z přísedících nerozuměl, k čemu by jemu to řekl.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 29, 'Nebo někteří se domnívali, poněvadž Jidáš měšec měl, že by jemu řekl Ježíš: Nakup těch věcí, kterýchž jest nám potřebí k svátku, aneb aby něco chudým dal.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 30, 'A on vzav skyvu chleba, hned vyšel, A byla noc.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 31, 'Když pak on vyšel, dí Ježíš: Nyníť oslaven jest Syn člověka, a Bůh oslaven jest v něm.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 32, 'A poněvadž Bůh oslaven jest v něm, i Bůh oslaví jej sám v sobě, a to hned oslaví jej.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 33, 'Synáčkové, ještě maličko s vámi jsem. Hledati mne budete, ale jakož jsem řekl Židům: Kam já jdu, vy nemůžete přijíti, i vám pravím nyní.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 34, 'Přikázaní nové dávám vám, abyste se milovali vespolek; jakož já miloval jsem vás, abyste i vy milovali jeden druhého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 35, 'Po tomť poznají všickni, že jste moji učedlníci, budete-li míti lásku jedni k druhým.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 36, 'Dí jemu Šimon Petr: Pane, kam jdeš? Odpověděl mu Ježíš: Kam jdu, nemůžeš ty nyní jíti za mnou, ale půjdeš potom.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 37, 'Dí jemu Petr: Pane, proč bych nemohl nyní jíti za tebou? Duši svou za tebe položím.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 38, 'Odpověděl jemu Ježíš: Duši svou za mne položíš? Amen, amen pravím tobě: Nezazpíváť kohout, až mne třikrát zapříš.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 1, 'Nermutiž se srdce vaše. Věříte v Boha, i ve mne věřte.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 2, 'V domě Otce mého příbytkové mnozí jsou. Byť nebylo tak, pověděl bych vám.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 3, 'Jduť, abych vám připravil místo. A když odejdu, a připravím vám místo, zase přijdu, a poberu vás k sobě samému, abyste, kde jsem já, i vy byli.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 4, 'A kam já jdu, víte, i cestu víte.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 5, 'Dí jemu Tomáš: Pane, nevíme, kam jdeš. A kterak můžeme cestu věděti?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 6, 'Dí jemu Ježíš: Já jsem ta cesta, i pravda, i život. Žádný nepřichází k Otci než skrze mne.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 7, 'Byste znali mne, také i Otce mého znali byste; a již nyní jej znáte, a viděli jste ho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 8, 'Řekl jemu Filip: Pane, ukaž nám Otce, a dostiť jest nám.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 9, 'Dí jemu Ježíš: Tak dlouhý čas s vámi jsem, a nepoznal jsi mne? Filipe, kdož vidí mne, vidí Otce, a kterakž ty pravíš: Ukaž nám Otce?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 10, 'Nevěříš, že já v Otci a Otec ve mně jest? Slova, kteráž já mluvím vám, sám od sebe nemluvím, ale Otec ve mně přebývaje, onť činí skutky.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 11, 'Věřtež mi, že jsem já v Otci a Otec ve mně; aneb aspoň pro ty samy skutky věřte mi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 12, 'Amen, amen pravím vám: Kdož věří ve mne, skutky, kteréž já činím, i on činiti bude, a větší nad ty činiti bude; nebo já jdu k Otci svému.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 13, 'A jestliže byste co prosili ve jménu mém, toť učiním, aby oslaven byl Otec v Synu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 14, 'Budete-li zač prositi ve jménu mém, jáť učiním.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 15, 'Milujete-li mne, přikázaní mých ostříhejte.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 16, 'A jáť prositi budu Otce, a jiného Utěšitele dá vám, aby s vámi zůstal na věky,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 17, 'Toho Ducha pravdy, jehož svět nemůže přijíti. Nebo nevidí ho, aniž ho zná, ale vy znáte jej, neboť u vás přebývá, a v vás bude.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 18, 'Neopustímť vás sirotků, přijduť k vám.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 19, 'Ještě maličko, a svět mne více neuzří, ale vy uzříte mne; nebo já živ jsem, i vy živi budete.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 20, 'V ten den vy poznáte, že já jsem v Otci svém, a vy ve mně, a já v vás.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 21, 'Kdož by měl přikázaní má, a ostříhal jich, onť jest ten, kterýž mne miluje. A kdož mne miluje, milován bude od Otce mého, a jáť jej budu milovati, a zjevím jemu samého sebe.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 22, 'Řekl jemu Judas, ne onen Iškariotský: Pane, jakž jest to, že sebe nám zjeviti chceš, a ne světu?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 23, 'Odpověděl Ježíš a řekl jemu: Miluje-li mne kdo, slova mého ostříhati bude, a Otec můj bude jej milovati, a k němu přijdeme, a příbytek u něho učiníme.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 24, 'Kdožť nemiluje mne, slov mých neostříhá; a slovo, kteréž slyšíte, neníť mé, ale toho, kterýž mne poslal, Otcovo.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 25, 'Toto mluvil jsem vám, u vás přebývaje.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 26, 'Utěšitel pak, ten Duch svatý, kteréhož pošle Otec ve jménu mém, onť vás naučí všemu, a připomeneť vám všecko, což jsem koli mluvil vám.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 27, 'Pokoj zůstavuji vám, pokoj svůj dávám vám; ne jako svět dává, já dávám vám. Nermutiž se srdce vaše, ani strachuj.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 28, 'Slyšeli jste, že já řekl jsem vám: Jdu, a zase přijdu k vám. Kdybyste mne milovali, radovali byste se jistě, že jsem řekl: Jdu k Otci; nebo Otec větší jest nežli já.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 29, 'A nyní pověděl jsem vám, prvé než by se stalo, abyste, když se stane, uvěřili.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 30, 'Již nemnoho mluviti budu s vámi; neboť jde kníže tohoto světa, ale nemáť nic na mně.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 31, 'Ale aby poznal svět, že miluji Otce, a jakož mi přikázal Otec, tak činím. Vstaňte, poďme odtud.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 1, 'Já jsem ten vinný kmen pravý, a Otec můj vinař jest.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 2, 'Každou ratolest, kteráž ve mně nenese ovoce, odřezuje, a každou, kteráž nese ovoce, čistí, aby hojnější ovoce nesla.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 3, 'Již vy čisti jste pro řeč, kterouž jsem mluvil vám.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 4, 'Zůstaňtež ve mně, a já v vás. Jakož ratolest nemůže nésti ovoce sama od sebe, nezůstala-li by při kmenu, takž ani vy, leč zůstanete ve mně.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 5, 'Já jsem vinný kmen a vy ratolesti. Kdo zůstává ve mně, a já v něm, ten nese ovoce mnohé; nebo beze mne nic nemůžete učiniti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 6, 'Nezůstal-li by kdo ve mně, vyvržen bude ven jako ratolest, a uschneť, a budouť sebrány, a na oheň uvrženy, a shoříť.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 7, 'Zůstanete-li ve mně, a slova má zůstanou-liť v vás, což byste koli chtěli, proste, a staneť se vám.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 8, 'V tomť bývá oslaven Otec můj, když ovoce nesete hojné, a budete moji učedlníci.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 9, 'Jakož miloval mne Otec, i já miloval jsem vás. Zůstaňtež v milování mém.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 10, 'Budete-li zachovávati přikázaní má, zůstanete v mém milování, jakož i já přikázaní Otce svého zachoval jsem, i zůstávám v jeho milování.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 11, 'Toto mluvil jsem vám, aby radost má zůstávala v vás, a radost vaše byla plná.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 12, 'Totoť jest přikázaní mé, abyste se milovali vespolek, jako já miloval jsem vás.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 13, 'Většího milování nad to žádný nemá, než aby duši svou položil za přátely své.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 14, 'Vy přátelé moji jste, učiníte-li to, což já přikazuji vám.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 15, 'Nebudu vás více nazývati služebníky, nebo služebník neví, co by činil pán jeho. Ale vás jsem nazval přátely, nebo všecko, což jsem koli slyšel od Otce svého, oznámil jsem vám.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 16, 'Ne vy jste mne vyvolili, ale já jsem vás vyvolil, a postavil, abyste šli a ovoce přinesli, a ovoce vaše aby zůstalo, aby zač byste koli prosili Otce ve jménu mém, dal vám.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 17, 'Toto přikazuji vám, abyste se milovali vespolek.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 18, 'Jestližeť vás svět nenávidí, víte, žeť mne prvé než vás v nenávisti měl.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 19, 'Byste byli z světa, svět, což jest jeho, miloval by; že pak nejste z světa, ale já z světa vyvolil jsem vás, protož vás svět nenávidí.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 20, 'Pamatujte na tu řeč, kterouž jsem já mluvil vám: Neníť služebník větší nežli pán jeho. Poněvadž se mně protivili, i vámť se protiviti budou; poněvadž řeči mé šetřili, i vaší šetřiti budou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 21, 'Ale toto všecko učiní vám pro jméno mé; nebo neznají toho, kterýž mne poslal.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 22, 'Kdybych byl nepřišel, a nemluvil jim, hříchu by neměli; ale nyní výmluvy nemají z hříchu svého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 23, 'Kdož mne nenávidí, i Otceť mého nenávidí.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 24, 'Bych byl skutků nečinil mezi nimi, jichž žádný jiný nečinil, hříchu by neměli; ale nyní i viděli, i nenáviděli i mne i Otce mého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 25, 'Ale aby se naplnila řeč, kteráž v zákoně jejich napsána jest: Že v nenávisti měli mne darmo.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 26, 'Když pak přijde ten Utěšitel, kteréhož já pošli vám od Otce, Duch pravdy, kterýž od Otce pochází, tenť svědectví vydávati bude o mně.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 27, 'Ano i vy svědectví vydávati budete, nebo od počátku se mnou jste.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 1, 'Toto mluvil jsem vám, abyste se nezhoršili.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 2, 'Vypovědíť vás ze škol, ano přijdeť čas, že všeliký, kdož vás mordovati bude, domnívati se bude, že tím Bohu slouží.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 3, 'A toť učiní vám proto, že nepoznali Otce ani mne.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 4, 'Ale toto mluvil jsem vám, abyste, když přijde ten čas, rozpomenuli se na to, že jsem já předpověděl vám. Tohoť pak jsem vám s počátku nemluvil, nebo jsem byl s vámi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 5, 'Nyní pak jdu k tomu, kterýž mne poslal, a žádný z vás neptá se mne: Kam jdeš?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 6, 'Ale že jsem vám tyto věci mluvil, zámutek naplnil srdce vaše.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 7, 'Já pak pravdu pravím vám, že jest vám užitečné, abych já odšel. Nebo neodejdu-liť, Utěšitel nepřijde k vám; a pakliť odejdu, pošli ho k vám.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 8, 'A onť přijda, obviňovati bude svět z hříchu, a z spravedlnosti, a z soudu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 9, 'Z hříchu zajisté, že nevěří ve mne.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 10, 'A z spravedlnosti, proto že jdu k Otci, a již více neuzříte mne.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 11, 'Z soudu pak, proto že kníže tohoto světa již jest odsouzeno.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 12, 'Ještěť bych měl mnoho mluviti vám, ale nemůžete snésti nyní.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 13, 'Když pak přijde ten Duch pravdy, uvedeť vás ve všelikou pravdu. Nebo nebude mluviti sám od sebe, ale cožkoli uslyší, toť mluviti bude; ano i budoucí věci zvěstovati bude vám.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 14, 'Onť mne oslaví; nebo z mého vezme, a zvěstuje vám.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 15, 'Všecko, cožkoli má Otec, mé jest. Protož jsem řekl, že z mého vezme, a zvěstuje vám.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 16, 'Maličko, a neuzříte mne, a opět maličko, a uzříte mne; nebo já jdu k Otci.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 17, 'I řekli někteří z učedlníků jeho mezi sebou: Co jest to, že praví nám: Maličko, a neuzříte mne, a opět maličko, a uzříte mne, a že já jdu k Otci?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 18, 'Protož pravili: Co jest to, že praví: Maličko? Nevíme, co praví.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 19, 'I poznal Ježíš, že se ho chtěli otázati. I řekl jim: O tom tížete mezi sebou, že jsem řekl: Maličko, a neuzříte mne, a opět maličko, a uzříte mne?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 20, 'Amen, amen pravím vám, že plakati a kvíliti budete vy, ale svět se bude radovati; vy pak se budete rmoutiti, ale zámutek váš obrátíť se v radost.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 21, 'Žena, když rodí, zámutek má, nebo přišla hodina její; ale když porodí děťátko, již nepamatuje na ssoužení, pro radost, proto že se narodil člověk na svět.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 22, 'Protož i vy zámutek máte nyní, ale opět uzřím vás, a radovati se bude srdce vaše, a radosti vaší žádný neodejme od vás.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 23, 'A v ten den nebudete se mne tázati o ničemž. Amen, amen pravím vám: Že zač byste koli prosili Otce ve jménu mém, dáť vám.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 24, 'Až dosavad za nic jste neprosili ve jménu mém. Prostež, a vezmete, aby radost vaše doplněna byla.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 25, 'Toto v příslovích mluvil jsem vám, ale přijdeť hodina, když více nebudu v příslovích mluviti vám, nýbrž zjevně o Otci zvěstovati budu vám.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 26, 'V ten den ve jménu mém prositi budete, a nepravímť vám, že já budu prositi Otce za vás.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 27, 'Nebo sám Otec miluje vás, proto že jste vy mne milovali, a uvěřili, že jsem já od Boha vyšel.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 28, 'Vyšelť jsem od Otce, a přišel jsem na svět; a opět opouštím svět, a jdu k Otci.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 29, 'Řkou jemu učedlníci jeho: Aj, nyní zjevně mluvíš, a přísloví žádného nepravíš.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 30, 'Nyní víme, že víš všecko, a nepotřebuješ, aby se kdo tebe tázal. Skrze to věříme, že jsi od Boha přišel.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 31, 'Odpověděl jim Ježíš: Nyní věříte?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 32, 'Aj, přijdeť hodina, anobrž již přišla, že se rozprchnete jeden každý k svému, a mne samého necháte. Ale nejsemť sám, nebo Otec se mnou jest.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 33, 'Tyto věci mluvil jsem vám, abyste ve mně pokoj měli. Na světě ssoužení míti budete, ale doufejtež, jáť jsem přemohl svět.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 1, 'To pověděv Ježíš, i pozdvihl oči svých k nebi a řekl: Otče, přišlať hodina, oslaviž Syna svého, aby i Syn tvůj oslavil tebe;');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 2, 'Jakož jsi dal jemu moc nad každým člověkem, aby těm všechněm, kteréž jsi dal jemu, život věčný dal.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 3, 'Totoť jest pak věčný život, aby poznali tebe samého pravého Boha, a kteréhož jsi poslal, Ježíše Krista.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 4, 'Jáť jsem oslavil tebe na zemi; dílo jsem vykonal, kteréž jsi mi dal, abych činil.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 5, 'A nyní oslaviž ty mne, Otče, u sebe samého touž slavou, kterouž jsem měl u tebe, prvé nežli svět byl.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 6, 'Oznámil jsem jméno tvé lidem, kteréž jsi mi dal z světa. Tvojiť byli, a mně jsi je dal, a řeč tvou zachovali.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 7, 'A nyní poznali, že všecky věci, kteréž jsi mi dal, od tebe jsou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 8, 'Nebo slova, kteráž jsi mi dal, dal jsem jim; a oni přijali, a poznali právě, že jsem od tebe vyšel, a uvěřili, že jsi ty mne poslal.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 9, 'Já za ně prosím, ne za svět prosím, ale za ty, kteréž jsi mi dal, nebo tvoji jsou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 10, 'A všecky věci mé tvé jsou, a tvé mé jsou, a oslaven jsem v nich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 11, 'Již pak více nejsem na světě, ale oni jsou na světě, a já k tobě jdu. Otče svatý, ostříhejž jich ve jménu svém, kteréž jsi mi dal, aťby byli jedno jako my.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 12, 'Dokudž jsem s nimi byl na světě, já jsem jich ostříhal ve jménu tvém. Kteréž jsi mi dal, zachoval jsem, a žádný z nich nezahynul, než syn zatracení, aby se písmo naplnilo.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 13, 'Ale nyní k tobě jdu, a toto mluvím na světě, aby měli radost mou plnou v sobě.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 14, 'Já jsem jim dal slovo tvé, a svět jich nenáviděl; nebo nejsou z světa, jako já nejsem z světa.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 15, 'Neprosímť, abys je vzal z světa, ale abys je zachoval od toho zlého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 16, 'Z světať nejsou, jako i já nejsem z světa.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 17, 'Posvětiž jich v pravdě své, slovo tvé pravda jest.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 18, 'Jakož jsi mne poslal na svět, i já jsem je poslal na svět.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 19, 'A já posvěcuji sebe samého za ně, aby i oni posvěceni byli v pravdě.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 20, 'Ne za tytoť pak toliko prosím, ale i za ty, kteříž skrze slovo jejich mají uvěřiti ve mne,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 21, 'Aby všickni jedno byli, jako ty, Otče, ve mně, a já v tobě, aby i oni v nás jedno byli, aby uvěřil svět, že jsi ty mne poslal.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 22, 'A já slávu, kterouž jsi mi dal, dal jsem jim, aby byli jedno, jako my jedno jsme.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 23, 'Já v nich, a ty ve mně, aby dokonáni byli v jedno, a aby poznal svět, že jsi ty mne poslal, a že jsi je miloval, jakožs mne miloval.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 24, 'Otče, kteréž jsi mi dal, chciť, kdež jsem já, aby i oni byli se mnou, aby hleděli na slávu mou, kteroužs mi dal; nebo jsi mne miloval před ustanovením světa.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 25, 'Otče spravedlivý, tebeť svět nepoznal, ale já jsem tebe poznal, a i tito poznali, že jsi ty mne poslal.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 26, 'A známéť jsem jim učinil jméno tvé, a známo učiním, aby milování, kterýmž jsi mne miloval, bylo v nich, a i já v nich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 1, 'To když pověděl Ježíš, vyšel s učedlníky svými přes potok Cedron, kdež byla zahrada; do kteréžto všel on i učedlníci jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 2, 'Věděl pak i Jidáš, zrádce jeho, to místo; nebo často chodíval tam Ježíš s učedlníky svými.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 3, 'Protož Jidáš pojav zástup, a od předních kněží {biskupů} a farizeů služebníky, přišel tam s lucernami a s pochodněmi a s zbrojí.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 4, 'Ježíš pak věda všecko, což přijíti mělo na něj, vyšed, řekl jim: Koho hledáte?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 5, 'Odpověděli jemu: Ježíše Nazaretského. Řekl jim Ježíš: Jáť jsem. Stál pak s nimi i Jidáš, zrádce jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 6, 'A jakž řekl jim: Já jsem, postoupili nazpět, a padli na zem.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 7, 'I otázal se jich opět: Koho hledáte? A oni řekli: Ježíše Nazaretského.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 8, 'Odpověděl Ježíš: Pověděl jsem vám, že já jsem. Poněvadž tedy mne hledáte, nechtež těchto, ať odejdou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 9, 'Aby se naplnila řeč, kterouž byl pověděl: Z těch, kteréž jsi mi dal, neztratil jsem žádného.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 10, 'Tedy Šimon Petr, maje meč, vytrhl jej, a udeřil služebníka nejvyššího kněze {biskupova}, a uťal mu ucho jeho pravé. Bylo pak jméno služebníka toho Malchus.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 11, 'I řekl Ježíš Petrovi: Schovej meč svůj do pošvy. Což nemám píti kalicha, kterýž mi dal Otec?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 12, 'Tedy zástup a hejtman a služebníci Židovští jali Ježíše, a svázali jej.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 13, 'A vedli ho k Annášovi nejprvé; nebo byl test Kaifášův, kterýž byl nejvyšším knězem {biskupem} toho léta.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 14, 'Kaifáš pak byl ten, kterýž byl radu dal Židům, že by užitečné bylo, aby člověk jeden umřel za lid.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 15, 'Šel pak za Ježíšem Šimon Petr a jiný učedlník. A ten učedlník byl znám nejvyššímu knězi {biskupovi}, i všel s Ježíšem do síně nejvyššího kněze {biskupovy}.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 16, 'Ale Petr stál u dveří vně. I vyšel ten druhý učedlník, kterýž byl znám nejvyššímu knězi {biskupovi}, a promluvil s vrátnou, i uvedl tam Petra.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 17, 'Tedy řekla Petrovi děvka vrátná: Nejsi-liž i ty z učedlníků člověka toho? Řekl on: Nejsem.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 18, 'Stáli pak tu služebníci a pacholci, kteříž oheň udělali, nebo zima bylo, i zhřívali se. A byl s nimi také i Petr, stoje a zhřívaje se.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 19, 'Tedy nejvyšší kněz {biskup} tázal se Ježíše o učedlnících jeho a o učení jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 20, 'Odpověděl jemu Ježíš: Já zjevně mluvil jsem světu, já vždycky učíval jsem v škole a v chrámě, kdež se odevšad Židé scházejí, a tajně jsem nic nemluvil.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 21, 'Co se mne ptáš? Ptej se těch, kteříž slýchali, co jsem jim mluvil. Aj, tiť vědí, co jsem já mluvil.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 22, 'A když on to pověděl, jeden z služebníků, stoje tu, dal hůlkou Ježíšovi, řka: Tak-liž odpovídáš nejvyššímu knězi {biskupovi}?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 23, 'Odpověděl mu Ježíš: Mluvil-li jsem zle, svědectví vydej o zlém; pakli dobře, proč mne tepeš?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 24, 'I poslal jej Annáš svázaného k Kaifášovi nejvyššímu knězi {biskupovi}.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 25, 'Stál pak Šimon Petr, a zhříval se. Tedy řekli jemu: Nejsi-liž i ty z učedlníků jeho? Zapřel on a řekl: Nejsem.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 26, 'Dí jemu jeden z služebníků nejvyššího kněze {biskupových}, příbuzný toho, kterémuž Petr uťal ucho: Zdaž jsem já tebe neviděl s ním v zahradě?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 27, 'Tedy Petr opět zapřel. A hned kohout zazpíval.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 28, 'I vedli Ježíše od Kaifáše do radného domu, a bylo ráno. Oni pak nevešli do radného domu, aby se nepoškvrnili, ale aby jedli beránka.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 29, 'Tedy vyšel k nim Pilát a řekl: Jakou žalobu vedete proti člověku tomuto?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 30, 'Odpověděli a řekli jemu: Byť tento nebyl zločinec, nevydali bychom ho tobě.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 31, 'I řekl jim Pilát: Vezměte vy jej, a podlé zákona svého suďte ho. I řekli mu Židé: Námť nesluší zabiti žádného.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 32, 'Aby se řeč Ježíšova naplnila, kterouž řekl, znamenaje, kterou by smrtí měl umříti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 33, 'Tedy Pilát všel opět do radného domu, i povolal Ježíše a řekl jemu: Ty-li jsi král Židovský?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 34, 'Odpověděl Ježíš: Sám-li od sebe to pravíš, čili jiní tobě pověděli o mně?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 35, 'Odpověděl Pilát: Zdaliž jsem já Žid? Národ tvůj a přední kněží {biskupové} dali mi tebe. Co jsi učinil?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 36, 'Odpověděl Ježíš: Království mé není z tohoto světa. Byť z tohoto světa bylo království mé, služebníci moji bránili by, abych nebyl vydán Židům. Ale nyní mé království není odsud.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 37, 'I řekl jemu Pilát: Tedy král jsi ty? Odpověděl Ježíš: Ty pravíš, že já král jsem. Jáť jsem se k tomu narodil, a proto jsem na svět přišel, abych svědectví vydal pravdě. Každý, kdož jest z pravdy, slyší hlas můj.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 38, 'Dí jemu Pilát: Co jest pravda? A to pověděv, opět vyšel k Židům, a dí jim: Já na něm žádné viny nenalézám.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 39, 'Ale jest obyčej váš, abych vám propustil jednoho na velikunoc. Chcete-liž tedy, ať vám propustím toho krále Židovského?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 40, 'I zkřikli opět všickni, řkouce: Ne toho, ale Barabáše. Byl pak ten Barabáš lotr.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 1, 'Tedy vzal Pilát Ježíše, a zbičoval.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 2, 'A žoldnéři zpletše korunu z trní, vstavili na hlavu jeho, a pláštěm šarlatovým přioděli jej.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 3, 'A říkali: Zdráv buď, králi Židovský. A bili jej hůlkami.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 4, 'I vyšel opět ven Pilát, a řekl jim: Aj, vyvedu jej vám ven, abyste poznali, žeť na něm žádné viny nenalézám.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 5, 'Tedy vyšel Ježíš ven, nesa tu korunu trnovou, a ten plášť šarlatový. I řekl jim Pilát: Aj člověk.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 6, 'A jakž jej uzřeli přední kněží {biskupové} a služebníci, zkřikli, řkouce: Ukřižuj, ukřižuj ho. Dí jim Pilát: Vezměte vy jej a ukřižujte, nebo já na něm viny nenalézám.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 7, 'Odpověděli jemu Židé: My zákon máme, a podlé zákona našeho máť umříti, nebo Synem Božím se činil.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 8, 'A když Pilát uslyšel tuto řeč, více se obával.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 9, 'I všel do radného domu zase, a řekl Ježíšovi: Odkud jsi ty? Ale Ježíš nedal jemu odpovědi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 10, 'Tedy řekl jemu Pilát: Nemluvíš se mnou? Nevíš-liž, že mám moc ukřižovati tě, a moc mám propustiti tebe?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 11, 'Odpověděl Ježíš: Neměl bys nade mnou moci nižádné, byť nebylo dáno s hůry; protož kdo mne tobě vydal, většíť hřích má.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 12, 'Od té chvíle hledal Pilát propustiti ho. Ale Židé volali, řkouce: Propustíš-li tohoto, nejsi přítel císařův; každý, kdož se králem činí, protiví se císaři.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 13, 'Tedy Pilát uslyšev tu řeč, vyvedl ven Ježíše, a sedl na soudné stolici na místě, kteréž slove Litostrotos, a Židovsky Gabbata.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 14, 'A bylo v pátek před velikonocí, okolo šesté hodiny. I řekl Židům: Aj, král váš.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 15, 'Oni pak zkřikli: Vezmi, vezmi, ukřižuj jej. Řekl jim Pilát: Krále vašeho ukřižuji? Odpověděli přední kněží {biskupové}: Nemámeť krále, než císaře.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 16, 'Tehdy vydal jim ho, aby byl ukřižován. I pojali Ježíše a vedli.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 17, 'A nesa kříž svůj, šel na místo, kteréž slove popravné, a Židovsky Golgota.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 18, 'Kdež ukřižovali ho, a s ním jiné dva s obou stran, a v prostředku Ježíše.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 19, 'Napsal pak i nápis Pilát, a vstavil na kříž. A bylo napsáno: Ježíš Nazaretský, král Židovský.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 20, 'Ten pak nápis mnozí z Židů čtli; nebo blízko města bylo to místo, kdež ukřižován byl Ježíš. A bylo psáno Židovsky, Řecky a Latině.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 21, 'Tedy přední kněží {biskupové} Židovští řekli Pilátovi: Nepiš: Král Židovský, ale že on řekl: Král Židovský jsem.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 22, 'Odpověděl Pilát: Co jsem psal, psal jsem.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 23, 'Žoldnéři pak, když Ježíše ukřižovali, vzali roucha jeho, (a učinili čtyři díly, každému rytíři díl,) a sukni. Byla pak sukně nesšívaná, ale od vrchu všecka naskrze setkaná.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 24, 'I řekli mezi sebou: Neroztrhujme jí, ale losujme o ni, čí bude. Aby se naplnilo písmo, řkoucí: Rozdělili sobě roucho mé, a o můj oděv metali los. Tedy žoldnéři tak učinili.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 25, 'Stály pak u kříže Ježíšova matka jeho a sestra matky jeho, Maria Kleofášova, a Maria Magdaléna.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 26, 'Tedy Ježíš uzřev matku, a učedlníka tu stojícího, kteréhož miloval, řekl matce své: Ženo, aj, syn tvůj.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 27, 'Potom řekl učedlníkovi: Aj, matka tvá. A od té hodiny přijal ji učedlník ten k sobě.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 28, 'Potom věda Ježíš, že již všecko dokonáno jest, aby se naplnilo písmo, řekl: Žízním.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 29, 'Byla pak tu postavena nádoba plná octa. Tedy oni naplnivše hubu octem, a obloživše yzopem, podali ústům jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 30, 'A když okusil Ježíš octa, řekl: Dokonánoť jest. A nakloniv hlavy, ducha Otci poručil.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 31, 'Židé pak, aby nezůstala na kříži těla na sobotu, poněvadž byl den připravování, (byl zajisté veliký ten den sobotní,) prosili Piláta, aby zlámáni byli hnátové jejich, a byli složeni.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 32, 'I přišli žoldnéři, a prvnímu zajisté zlámali hnáty, i druhému, kterýž ukřižován byl s ním.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 33, 'Ale k Ježíšovi přišedše, jakž uzřeli jej již mrtvého, nelámali hnátů jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 34, 'Ale jeden z žoldnéřů bok jeho kopím otevřel, a hned vyšla krev a voda.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 35, 'A ten, kterýž viděl, svědectví vydal, a pravé jest svědectví jeho. Onť ví, že pravé věci praví, abyste vy věřili.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 36, 'Stalo se pak to, aby se naplnilo to písmo: Kost jeho nebude zlámána.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 37, 'A opět jiné písmo dí: Uzříť, v koho jsou bodli.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 38, 'Potom pak prosil Piláta Jozef z Arimatie, (kterýž byl učedlník Ježíšův, ale tajný, pro strach Židovský,) aby sňal tělo Ježíšovo. I dopustil Pilát. A on přišed, sňal tělo Ježíšovo.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 39, 'Přišel pak i Nikodém, (kterýž byl prvé přišel k Ježíšovi v noci,) nesa smíšení mirry a aloes okolo sta liber.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 40, 'Tedy vzali tělo Ježíšovo, a obvinuli je prostěradly s těmi vonnými věcmi, jakž obyčej jest Židům se pochovávati.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 41, 'A byla na tom místě, kdež ukřižován byl, zahrada, a v zahradě hrob nový, v němž ještě žádný nebyl pochován.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 42, 'Protož tu pro den připravování Židovský, že blízko byl ten hrob, položili Ježíše.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 1, 'Prvního pak dne po sobotě Maria Magdaléna šla ráno k hrobu, když ještě tma bylo. I uzřela kámen odvalený od hrobu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 2, 'I běžela a přišla k Šimonovi Petrovi a k druhému učedlníkovi, tomu, jehož miloval Ježíš, a řekla jim: Vzali Pána z hrobu, a nevíme, kde jej položili.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 3, 'Tedy vyšel Petr i ten druhý učedlník, a šli k hrobu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 4, 'Běželi pak oba spolu. Ale ten druhý učedlník předběhl Petra, a přišel prvé k hrobu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 5, 'A nachýliv se, uzřel prostěradla položená, ale však tam nevšel.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 6, 'Tedy přišel Šimon Petr, za ním jda, a všel do hrobu. I uzřel prostěradla položená,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 7, 'A rouchu, kteráž byla na hlavě jeho, ne s prostěradly položenou, ale obzvláštně svinutou na jednom místě.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 8, 'Potom všel i ten druhý učedlník, kterýž byl prvé přišel k hrobu, i uzřel a uvěřil.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 9, 'Nebo ještě neznali písma, že měl z mrtvých vstáti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 10, 'I odešli zase ti učedlníci tam, kdež prvé byli.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 11, 'Ale Maria stála u hrobu vně, plačeci. A když plakala, naklonila se do hrobu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 12, 'A uzřela dva anděly v bílém rouše sedící, jednoho u hlavy, a druhého u noh, tu kdež bylo položeno tělo Ježíšovo.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 13, 'Kteříž řekli jí: Ženo, co pláčeš? I dí jim: Vzali Pána mého, a nevím, kde ho položili.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 14, 'To když řekla, obrátila se zpátkem, a uzřela Ježíše, an stojí, ale nevěděla, by Ježíš byl.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 15, 'Dí jí Ježíš: Ženo, co pláčeš? Koho hledáš? Ona domnívajici se, že by zahradník byl, řekla jemu: Pane, vzal-lis ty jej, pověz mi, kdes ho položil, ať já jej vezmu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 16, 'Řekl jí Ježíš: Maria. Obrátivši se ona, řekla jemu: Rabbóni, což se vykládá: Mistře.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 17, 'Dí jí Ježíš: Nedotýkejž se mne; nebo jsem ještě nevstoupil k Otci svému. Ale jdiž k bratřím mým, a pověz jim: Vstupuji k Otci svému, a k Otci vašemu, k Bohu svému, a k Bohu vašemu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 18, 'Přišla Maria Magdaléna, zvěstujici učedlníkům, že by viděla Pána, a že jí to pověděl.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 19, 'Když pak byl večer toho dne, kterýž jest první po sobotě, a dvéře byly zavříny, kdež byli učedlníci shromážděni, pro strach Židovský, přišel Ježíš, a stál u prostřed, a řekl jim: Pokoj vám.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 20, 'A to pověděv, ukázal jim ruce i bok svůj. I zradovali se učedlníci, vidouce Pána.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 21, 'Tedy řekl jim Ježíš opět: Pokoj vám. Jakož mne poslal Otec, tak i já posílám vás.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 22, 'A to pověděv, dechl, a řekl jim: Přijměte Ducha svatého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 23, 'Kterýmžkoli odpustili byste hříchy, odpouštějíť se jim; kterýmžkoli zadrželi byste, zadržániť jsou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 24, 'Tomáš pak jeden ze dvanácti, kterýž sloul Didymus, nebyl s nimi, když byl přišel Ježíš.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 25, 'I řekli jemu jiní učedlníci: Viděli jsme Pána. Ale on řekl jim: Leč uzřím v rukou jeho bodení hřebů, a vpustím prst svůj v místo hřebů, a ruku svou vložím v bok jeho, nikoli neuvěřím.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 26, 'A po osmi dnech opět učedlníci jeho byli vnitř, a Tomáš s nimi. Přišel Ježíš, a dvéře byly zavříny, i stál u prostřed a řekl: Pokoj vám.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 27, 'Potom řekl Tomášovi: Vložiž prst svůj sem, a viz ruce mé, a vztáhni ruku svou, a vpusť v bok můj, a nebudiž nevěřící, ale věrný.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 28, 'I odpověděl Tomáš a řekl jemu: Pán můj a Bůh můj!');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 29, 'Dí jemu Ježíš: Žes mne viděl, Tomáši, uvěřil jsi. Blahoslavení, kteříž neviděli, a uvěřili.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 30, 'Mnohé zajisté i jiné divy činil Ježíš před oblíčejem učedlníků svých, kteříž nejsou zapsáni v knize této.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 31, 'Ale tito zapsáni jsou, abyste věřili, že Ježíš jest Kristus, Syn Boží, a abyste věříce, život měli ve jménu jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 1, 'Potom zjevil se opět Ježíš učedlníkům u moře Tiberiadského. Zjevil se pak takto:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 2, 'Byli spolu Šimon Petr a Tomáš, kterýž sloul Didymus, a Natanael, kterýž byl z Kány Galilejské, a synové Zebedeovi, a jiní z učedlníků jeho dva.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 3, 'Dí jim Šimon Petr: Půjdu ryb loviti. Řekli jemu: Půjdeme i my s tebou. I šli, a vstoupili na lodí hned; a té noci nic nepopadli.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 4, 'A když bylo již ráno, stál Ježíš na břehu. Nevěděli však učedlníci, by Ježíš byl.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 5, 'Tedy dí jim Ježíš: Dítky, máte-li jakou krmičku? Odpověděli jemu: Nemáme.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 6, 'On pak řekl jim: Zavrztež síť na pravou stranu lodí, a naleznete. I zavrhli, a hned nemohli ji táhnouti pro množství ryb.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 7, 'I řekl učedlník ten, kteréhož miloval Ježíš, Petrovi: Pán jest. A Šimon Petr, jakž uslyšel, že Pán jest, opásal se po košili, (nebo byl nah,) a pustil se do moře.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 8, 'Jiní také učedlníci na lodí připlavili se (nebo nedaleko byli od břehu, asi okolo dvou set loket,) táhnouce tu síť s rybami.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 9, 'A jakž vystoupili na břeh, uzřeli řeřavé uhlí a rybu svrchu položenou a chléb.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 10, 'Řekl jim Ježíš: Přineste ryb, kterýchž jste nalapali nyní.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 11, 'Vstoupil pak Šimon Petr, a vytáhl síť na zem, plnou ryb velikých, sto padesáte a tři. A ačkoli jich tak mnoho bylo, neztrhala se síť.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 12, 'Řekl jim Ježíš: Poďte, obědujte. Žádný pak z učedlníků nesměl se ho otázati: Ty kdo jsi? vědouce, že Pán jest.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 13, 'I přišel Ježíš, a vzal ten chléb, a dával jim, i rybu též.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 14, 'To již po třetí ukázal se Ježíš učedlníkům svým, vstav z mrtvých.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 15, 'A když poobědvali, řekl Ježíš Šimonovi Petrovi: Šimone Jonášův, miluješ-li mne více než tito? Řekl jemu: Ovšem, Pane, ty víš, že tě miluji. Dí jemu: Pasiž beránky mé.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 16, 'Řekl jemu opět po druhé: Šimone Jonášův, miluješ-li mne? Řekl jemu: Ovšem, Pane, ty víš, že tě miluji. Dí jemu: Pasiž ovce mé.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 17, 'Řekl jemu potřetí: Šimone Jonášův, miluješ-li mne? I zarmoutil se Petr, protože jemu řekl potřetí: Miluješ-li mne? A odpověděl jemu: Pane, ty znáš všecko, ty víš, že tě miluji. Řekl jemu Ježíš: Pasiž ovce mé.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 18, 'Amen, amen pravím tobě: Když jsi byl mladší, opasovals se, a chodíval jsi, kams chtěl: ale když se sstaráš, ztáhneš ruce své, a jiný tě opáše, a povede, kamž bys ty nechtěl.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 19, 'To pak pověděl, znamenaje, kterou by smrtí měl oslaviti Boha. A to pověděv, řekl jemu: Poď za mnou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 20, 'I obrátiv se Petr, uzřel toho učedlníka, kteréhož miloval Ježíš, an jde za ním, kterýž i odpočíval za večeří na prsech jeho, a byl řekl: Pane, kdo jest ten, kterýž tě zradí?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 21, 'Toho viděv Petr, dí Ježíšovi: Pane, co pak tento?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 22, 'Řekl jemu Ježíš: Chci-li ho nechati, dokudž nepřijdu, co tobě po tom? Ty poď za mnou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 23, 'I vyšla řeč ta mezi bratří, že by učedlník ten neměl umříti. Ale neřekl byl jemu Ježíš, že by neměl umříti, ale: Chci-li ho nechati, dokudž nepřijdu, co tobě po tom?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 24, 'Toť jest učedlník ten, kterýž svědectví vydává o těchto věcech, a napsal toto, a víme, že pravé jest svědectví jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 25, 'Jestiť pak i jiných mnoho věcí, kteréž činil Ježíš, kteréž kdyby měly všecky, každá obzvláštně, psány býti, mám za to, že by ten svět nemohl přijíti těch knih, kteréž by napsány byly. Amen.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 1, 'První zajisté knihu sepsalť jsem, ó Teofile, o všech věcech, kteréž začal Ježíš i činiti i učiti,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 2, 'Až do toho dne, v němž dav přikázaní apoštolům, kteréž byl skrze Ducha svatého vyvolil, vzhůru vzat jest.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 3, 'Kterýmž i zjevoval sebe samého živého po svém umučení ve mnohých jistých důvodích, za čtyřidceti dnů ukazuje se jim, a mluvě o království Božím.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 4, 'A shromáždiv je, přikázal jim, aby z Jeruzaléma neodcházeli, ale aby očekávali zaslíbení Otcova, o kterémž jste prý slyšeli ode mne.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 5, 'Nebo Jan zajisté křtil vodou, ale vy pokřtěni budete Duchem svatým po nemnohých těchto dnech.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 6, 'Oni pak sšedše se, otázali se ho, řkouce: Pane, v tomto-li času napravíš království Izraelské?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 7, 'I řekl jim: Neníť vaše věc znáti časy aneb příhodnosti časů, kteréž Otec v moci své položil.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 8, 'Ale přijmete moc Ducha svatého, přicházejícího na vás, a budete mi svědkové, i v Jeruzalémě, i ve všem Judstvu, i v Samaří, a až do posledních končin země.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 9, 'A to pověděv, ani na to hledí, zhůru vyzdvižen jest, a oblak vzal jej od očí jejich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 10, 'A když za ním v nebe jdoucím pilně hleděli, aj, dva muži postavili se podlé nich v rouše bílém,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 11, 'A řekli: Muži Galilejští, co stojíte, hledíce do nebe? Tento Ježíš, kterýž zhůru vzat jest od vás do nebe, takť přijde, jakž jste spatřili způsob jeho jdoucího do nebe.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 12, 'Tehdy navrátili se do Jeruzaléma, od hory, kteráž slove Olivetská, kteráž jest blízko od Jeruzaléma, vzdálí cesty jednoho dne sobotního.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 13, 'A všedše, vstoupili do vrchního příbytku domu, kdež přebývali, i Petr i Jakub, i Jan a Ondřej, Filip a Tomáš, Bartoloměj a Matouš, Jakub Alfeův a Šimon Zelótes a Judas Jakubův.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 14, 'Ti všickni trvali jednomyslně na modlitbě a pokorné prosbě s ženami a s Marií, matkou Ježíšovou, i s bratřími jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 15, 'V těch pak dnech povstav Petr u prostřed učedlníků, řekl (a byl zástup lidí spolu shromážděných okolo sta a dvadcíti,):');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 16, 'Muži bratří, musilo se naplniti písmo to, kteréž předpověděl Duch svatý skrze ústa Davidova o Jidášovi, kterýž byl vůdce těch, kteříž jímali Ježíše.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 17, 'Nebo byl přičten k nám, a byl došel losu přisluhování tohoto.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 18, 'Ten zajisté obdržel pole ze mzdy nepravosti, a oběsiv se, rozpukl se na dvé, i vykydla se všecka střeva jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 19, 'A to známé jest učiněno všechněm přebývajícím v Jeruzalémě, tak že jest nazváno pole to vlastním jazykem jejich Akeldama, to jest pole krve.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 20, 'Psáno jest zajisté v knize žalmů: Budiž příbytek jeho pustý, a nebuď, kdo by přebýval v něm, a biskupství jeho vezmi jiný.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 21, 'Protož musíť jeden z těch mužů, kteříž s námi bývali po všecken čas, v němž přebýval mezi námi Pán Ježíš,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 22, 'Počav od křtu Janova až do dne toho, v kterémž zhůru vzat jest od nás, býti svědkem spolu s námi vzkříšení jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 23, 'Tedy postavili dva, Jozefa, kterýž sloul Barsabáš, kterýž měl přijmí Justus, a Matěje.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 24, 'A modléce se, řekli: Ty, Pane, všech srdcí zpytateli, ukažiž, kterého jsi vyvolil z těchto dvou,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 25, 'Aby přijal los přisluhování tohoto a apoštolství, z něhož vypadl Jidáš, aby odšel na místo své.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 26, 'I dali jim losy. Spadl pak los na Matěje, i připojen jest z společného snešení k jedenácti apoštolům.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 1, 'A když přišel den padesátý, byli všickni jednomyslně spolu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 2, 'I stal se rychle zvuk s nebe, jako valícího se větru prudkého, a naplnil všecken dům, kdež seděli.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 3, 'I ukázali se jim rozdělení jazykové jako oheň, kterýž posadil se na každém z nich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 4, 'I naplněni jsou všickni Duchem svatým, a počali mluviti jinými jazyky, jakž ten Duch dával jim vymlouvati.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 5, 'Byli pak v Jeruzalémě přebývající Židé, muži nábožní, ze všelikého národu, kterýž pod nebem jest.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 6, 'A když se stal ten hlas, sešlo se množství, a užasli se, že je slyšel jeden každý, ani mluví přirozeným jazykem jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 7, 'I děsili se všickni, a divili, řkouce jedni k druhým: Aj, zdaliž nejsou tito všickni, kteříž mluví, Galilejští?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 8, 'A kterak my slyšíme jeden každý jazyk náš, v kterémž jsme se zrodili?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 9, 'Partští, a Médští, a Elamitští, a kteříž přebýváme v Mezopotamii, v Židovstvu a v Kappadocii, v Pontu a v Azii,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 10, 'V Frygii a v Pamfylii, v Egyptě a v krajinách Libye, kteráž jest vedlé Cyrénu, a příchozí Římané, Židé, i v nově na víru obrácení,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 11, 'Kretští i Arabští, slyšíme je, ani mluví jazyky našimi veliké věci Boží.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 12, 'I děsili se všickni a divili, jeden k druhému řkouce: I což toto bude?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 13, 'Jiní pak posmívajíce se, pravili: Mstem se zpili tito.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 14, 'A stoje Petr s jedenácti, pozdvihl hlasu svého, a promluvil k nim: Muži Židé, a všickni, kteříž bydlíte v Jeruzalémě, toto vám známo buď, a ušima pozorujte slov mých.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 15, 'Jistě nejsou tito, jakž vy se domníváte, zpilí, poněvadž jest teprv třetí hodina na den.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 16, 'Ale totoť jest, což jest předpovědíno skrze proroka Joele:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 17, 'A budeť v posledních dnech, (dí Bůh,) vyleji z Ducha svého na všeliké tělo, a prorokovati budou synové vaši, i dcery vaše, a mládenci vaši vidění vídati budou, a starci vaši sny míti budou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 18, 'A zajisté na služebníky a na služebnice své v těch dnech vyleji z Ducha svého, a budou prorokovati.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 19, 'A ukáži zázraky na nebi svrchu, a znamení na zemi dole, krev a oheň a páru dymovou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 20, 'Slunce obrátí se v temnost, a měsíc v krev, prvé než přijde ten den Páně veliký a zjevný.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 21, 'A staneť se, že každý, kdožkoli vzýval by jméno Páně, spasen bude.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 22, 'Muži Izraelští, slyšte slova tato: Ježíše toho Nazaretského, muže od Boha zveličeného mezi vámi mocmi a zázraky a znameními, kteréž činil skrze něho Bůh u prostřed vás, jakož i vy sami víte,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 23, 'Toho vydaného z uložené rady a předzvědění Božího vzavše, a skrze ruce nešlechetných ukřižovavše, zamordovali jste.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 24, 'Jehož Bůh vzkřísil, zprostiv bolestí smrti, jakož nebylo možné jemu držánu býti od ní.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 25, 'Nebo David praví o něm: Spatřoval jsem Pána před sebou vždycky; nebo jest mi po pravici, abych se nepohnul.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 26, 'Protož rozveselilo se srdce mé, a zplésal jazyk můj, nýbrž i tělo mé odpočine v naději.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 27, 'Nebo nenecháš duše mé v pekle, aniž dáš viděti svatému svému porušení.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 28, 'Známé jsi mi učinil cesty života, a naplníš mne utěšením před oblíčejem svým.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 29, 'Muži bratří, sluší směle mluviti k vám o patriarchovi Davidovi, že i umřel, i pochován jest, i hrob jeho jest u nás až do dnešního dne.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 30, 'Prorok tedy byv, a věděv, že přísahou zavázal se jemu Bůh, že z plodu ledví jeho podlé těla vzbudí Krista, a posadí na stolici jeho,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 31, 'To předzvěděv, mluvil o vzkříšení Kristovu, že není opuštěna duše jeho v pekle, ani tělo jeho vidělo porušení.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 32, 'Toho Ježíše vzkřísil Bůh, jehož my všickni svědkové jsme.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 33, 'Protož pravicí Boží jsa zvýšen, a vzav zaslíbení Ducha svatého od Otce, vylil to, což vy nyní vidíte a slyšíte.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 34, 'Neboť David nevstoupil v nebe, ale on praví: Řekl Pán Pánu mému: Seď na pravici mé,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 35, 'Dokudž nepoložím nepřátel tvých za podnože noh tvých.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 36, 'Věziž tedy jistotně všecken dům Izraelský, žeť Bůh i Pánem ho učinil i Kristem, toho Ježíše, kteréhož jste vy ukřižovali.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 37, 'To slyševše, zkormouceni jsou v srdci, a řekli Petrovi a jiným apoštolům: Což máme činiti, muži bratří?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 38, 'Tedy Petr řekl jim: Pokání čiňte, a pokřti se jeden každý z vás ve jménu Ježíše Krista na odpuštění hříchů, a přijmete dar Ducha svatého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 39, 'Vámť zajisté zaslíbení to svědčí a synům vašim, i všechněm, kteříž daleko jsou, kterýchžkoli povolal by Pán Bůh náš.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 40, 'A jinými slovy mnohými osvědčoval a napomínal, řka: Oddělte se od pokolení toho zlého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 41, 'Tedy ti, kteříž ochotně přijali slova jeho, pokřtěni jsou, a připojilo se v ten den duší okolo tří tisíců.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 42, 'I zůstávali v učení apoštolském, a v společnosti, a v lámání chleba, a na modlitbách.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 43, 'I přišla na všelikou duši bázeň, a mnozí divové a zázrakové dáli se skrze apoštoly.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 44, 'Všickni pak věřící byli pospolu, a měli všecky věci obecné.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 45, 'A prodávali vládařství a statky, a dělili mezi všecky, jakž komu potřebí bylo.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 46, 'A na každý den trvajíce jednomyslně v chrámě, a lámajíce po domích chléb, přijímali pokrm s potěšením a sprostností srdce,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 47, 'Chválíce Boha, a milost majíce u všeho lidu. Pán pak přidával církvi na každý den těch, kteříž by spaseni byli.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 1, 'Potom pak Petr a Jan vstupovali do chrámu v hodinu modlitebnou devátou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 2, 'A muž nějaký, byv chromý od života matky své, nesen byl, kteréhož sázeli na každý den u dveří chrámových, kteréž slouly krásné, aby prosil za almužnu těch, kteříž vcházeli do chrámu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 3, 'Ten uzřev Petra a Jana, ani vcházeti měli do chrámu, prosil, aby mu almužnu dali.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 4, 'I pohleděv naň Petr s Janem, řekl: Hleď na nás.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 5, 'A on pilně pohleděl na ně, naděje se, že něco vezme od nich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 6, 'Tedy řekl Petr: Stříbra a zlata nemám, ale což mám, to tobě dám. Ve jménu Ježíše Krista Nazaretského vstaň a choď.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 7, 'I ujav jej za ruku jeho pravou, pozdvihl ho, a hned utvrzeny jsou nohy jeho i kloubové.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 8, 'A zchytiv se, stál, a chodil, a všel s nimi do chrámu, chodě, a poskakuje, a chvále Boha.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 9, 'A viděl jej všecken lid, an chodí, a chválí Boha.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 10, 'I poznali ho, že jest ten, kterýž na almužně sedával u dveří krásných chrámových. I naplněni jsou strachem a děšením nad tím, což se stalo jemu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 11, 'A když se ten uzdravený přídržel Petra a Jana, zběhl se k nim všecken lid do síňce, kteráž sloula Šalomounova, předěšen jsa.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 12, 'To viděv Petr, promluvil k lidu: Muži Izraelští, co se divíte tomuto? Aneb co na nás tak pilně hledíte, jako bychom my svou vlastní mocí aneb nábožností učinili to, aby tento chodil?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 13, 'Bůh Abrahamův a Izákův a Jákobův, Bůh otců našich, oslavil Syna svého Ježíše, kteréhož jste vy vydali, a odepřeli se před tváří Pilátovou, kterýž ho soudil býti hodného propuštění.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 14, 'Vy pak toho svatého a spravedlivého odepřeli jste se, a prosili jste za muže vražedlníka, aby vám byl dán,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 15, 'Dárce pak života zamordovali jste. Kteréhož Bůh vzkřísil z mrtvých; čehož my svědkové jsme.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 16, 'A skrze víru ve jméno jeho, tohoto, kteréhož vy vidíte a znáte, utvrdilo jméno jeho. Víra, pravím, kteráž jest skrze něho, dala jemu celé zdraví toto před oblíčejem všech vás.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 17, 'Ale nyní, bratří, vím, že jste to z nevědomí učinili, jako i knížata vaše.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 18, 'Bůh pak to, což předzvěstoval skrze ústa všech proroků svých, že měl Kristus trpěti, tak naplnil.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 19, 'Protož čiňte pokání, a obraťte se, aby byli shlazeni hříchové vaši, když by přišli časové rozvlažení od tváři Páně,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 20, 'A poslal by toho, kterýž vám kázán jest, Ježíše Krista.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 21, 'Kteréhož zajisté musejí přijíti nebesa, až do času napravení všech věcí; což byl předpověděl Bůh skrze ústa všech svých svatých proroků od věků.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 22, 'Mojžíš zajisté otcům řekl: Proroka vám vzbudí Pán Bůh váš z bratří vašich jako mne, jehož poslouchati budete ve všem, cožkoli bude mluviti vám.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 23, 'Staneť se pak, že každá duše, kteráž by neposlouchala toho proroka, vyhlazena bude z lidu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 24, 'Ano i všickni proroci od Samuele a potomních, kteřížkoli mluvili, také o těchto dnech předzvěstovali.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 25, 'Vy jste synové proroků a úmluvy, kterouž učinil Bůh s otci našimi, řka Abrahamovi: V semeni tvém požehnány budou všecky čeledi země.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 26, 'Vám nejprvé Bůh, vzbudiv Syna svého Ježíše, poslal ho dobrořečícího vám, aby se jeden každý z vás odvrátil od nepravostí svých.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 1, 'A když oni mluvili k lidu, přišli na ně kněží, a úředník chrámu a saduceové,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 2, 'Těžce to nesouce, že lid učili, a zvěstovali ve jménu Ježíše vzkříšení z mrtvých.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 3, 'I vztáhli na ně ruce, a vsadili je do žaláře až do jitra, nebo již byl večer.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 4, 'Mnozí pak z těch, kteříž slyšeli slovo, uvěřili. I učiněn jest počet mužů okolo pěti tisíců.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 5, 'Stalo se pak nazejtří, že se sešla knížata jejich, a starší, a zákonníci v Jeruzalémě,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 6, 'A Annáš nejvyšší kněz {biskup}, a Kaifáš, a Jan a Alexander, a kteřížkoli byli z pokolení nejvyššího kněze {biskupa}.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 7, 'I postavivše je mezi sebou, otázali se: Jakou mocí aneb v kterém jménu učinili jste to vy?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 8, 'Tehdy Petr, jsa pln Ducha svatého, řekl jim: Knížata lidu a starší Izraelští,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 9, 'Poněvadž my dnes k soudu jsme přivedeni pro dobrodiní člověku nemocnému, kterak by on zdráv učiněn byl:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 10, 'Známo buď všechněm vám i všemu lidu Izraelskému, že ve jménu Ježíše Krista Nazaretského, kteréhož jste vy ukřižovali, jehož Bůh vzkřísil z mrtvých, skrze toho jméno tento stojí před vámi zdravý.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 11, 'Toť jest ten kámen za nic položený od vás stavitelů, kterýž jest v hlavu úhelní.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 12, 'A neníť v žádném jiném spasení; neboť není jiného jména pod nebem daného lidem, skrze kteréž bychom mohli spaseni býti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 13, 'I vidouce takovou udatnost a smělost v mluvení Petrovu a Janovu, a shledavše, že jsou lidé neučení a prostí, divili se, a poznali je, že s Ježíšem bývali.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 14, 'Člověka také toho vidouce, an stojí s nimi, kterýž byl uzdraven, neměli co mluviti proti nim.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 15, 'I rozkázavše jim vystoupiti z rady, rozmlouvali vespolek,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 16, 'Řkouce: Co učiníme lidem těmto? Nebo že zjevný zázrak stal se skrze ně, všechněm přebývajícím v Jeruzalémě známé jest, aniž můžeme zapříti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 17, 'Ale aby se to více nerozhlašovalo v lidu, s pohrůžkou přikažme jim, aby více v tom jménu žádnému z lidí nemluvili.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 18, 'I povolavše jich, přikázali jim, aby nikoli nemluvili, ani neučili ve jménu Ježíšovu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 19, 'Tedy Petr a Jan odpovídajíce jim, řekli: Jest-li to spravedlivé před oblíčejem Božím, abychom vás více poslouchali než Boha, suďte.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 20, 'Neboť my nemůžeme nemluviti toho, co jsme viděli a slyšeli.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 21, 'A oni pohrozivše jim, propustili je, nenalezše na nich příčiny trestání, pro lid; nebo všickni velebili Boha z toho, co se bylo stalo.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 22, 'Byl zajisté v letech více než ve čtyřidcíti člověk ten, při kterémž se byl stal zázrak ten uzdravení.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 23, 'A jsouce propuštěni, přišli k svým, a pověděli, co k nim přední kněží {biskupové} a starší mluvili.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 24, 'Kteříž uslyševše to, jednomyslně pozdvihli hlasu k Bohu a řekli: Hospodine, ty jsi Bůh, kterýž jsi učinil nebe i zemi, i moře i všecko, což v nich jest,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 25, 'Kterýž jsi skrze ústa Davida, služebníka svého, řekl: Proč se bouřili národové, a lidé myslili marné věci?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 26, 'Postavili se králové zemští, a knížata sešla se vespolek proti Pánu a proti pomazanému jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 27, 'Právěť se jistě sešli proti svatému Synu tvému Ježíšovi, kteréhož jsi pomazal, Heródes a Pontský Pilát, s pohany a lidem Izraelským,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 28, 'Aby učinili to, což ruka tvá a rada tvá předuložila, aby se stalo.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 29, 'A nyní, Pane, pohlediž na pohrůžky jejich, a dejž služebníkům svým mluviti slovo své svobodně a směle,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 30, 'Vztahuje ruku svou k uzdravování a k činění divů a zázraků, skrze jméno svatého Syna tvého Ježíše.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 31, 'A když se oni modlili, zatřáslo se to místo, na kterémž byli shromážděni, a naplněni jsou všickni Duchem svatým, a mluvili slovo Boží směle a svobodně.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 32, 'Toho pak množství věřících bylo jedno srdce a jedna duše. Aniž kdo co z těch věcí, kteréž měl, svým vlastním býti pravil, ale měli všecky věci obecné.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 33, 'A mocí velikou vydávali apoštolé svědectví o vzkříšení Pána Ježíše, a milost veliká přítomná byla všechněm jim.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 34, 'Žádný zajisté mezi nimi nebyl nuzný; nebo kteřížkoli měli pole neb domy, prodávajíce, přinášeli peníze, za kteréž prodávali,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 35, 'A kladli před nohy apoštolské. I bylo rozdělováno to jednomu každému, jakž komu potřebí bylo.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 36, 'Jozes pak, kterýž přijmí měl od apoštolů Barnabáš, (což se vykládá syn utěšení,) z pokolení Levítského, z Cypru rodem,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 37, 'Měv pole, prodal je, a přinesl peníze, a položil k nohám apoštolským.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 1, 'Muž pak nějaký, jménem Ananiáš, s Zafirou, manželkou svou, prodal statek.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 2, 'A lstivě těch peněz ujal s vědomím manželky své, a přinesa díl nějaký, položil k nohám apoštolským.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 3, 'I řekl Petr: Ananiáši, proč naplnil satan srdce tvé, tak abys lhal Duchu svatému, a lstivě ujal peněz za to pole?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 4, 'Zdaliž nebylo tvé, kdybys ho byl sobě nechal? A když bylo prodáno, v moci tvé bylo. I proč jsi tuto věc složil v srdci svém? Neselhal jsi lidem, ale Bohu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 5, 'Tedy uslyšav Ananiáš ta slova, padna, zdechl. I spadla bázeň veliká na všecky, kteříž to slyšeli.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 6, 'A vstavše mládenci, vzali jej, a vynesše ven, pochovali.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 7, 'I stalo se po chvíli, jako po třech hodinách, že i jeho žena, nevěduci, co se bylo stalo, přišla.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 8, 'I řekl jí Petr: Pověz mi, za tolik-li jste pole prodali? A ona řekla: Ano, za tolik.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 9, 'Tedy dí jí Petr: I proč jste se smluvili, abyste pokoušeli Ducha Páně? Aj, nohy těch, kteříž pochovali muže tvého, přede dveřmi, a vynesouť tebe.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 10, 'I padla hned před nohy jeho, a zdechla. A všedše mládenci, nalezli ji mrtvou; i vynesše, pochovali podlé muže jejího.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 11, 'I byla bázeň veliká po vší církvi, i mezi všemi, kteříž to slyšeli.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 12, 'Skrze ruce pak apoštolů dáli se divové a zázrakové mnozí v lidu. (A bývali všickni jednomyslně v síňci Šalomounově.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 13, 'Jiný pak žádný nesměl se připojiti k nim, ale velebil je lid.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 14, 'Anobrž vždy více se rozmáhalo množství věřících Pánu, mužů i také žen.)');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 15, 'Tak že i na ulice vynášeli nemocné, a kladli na ložcích a na nosidlách, aby, když by šel Petr, aspoň stín jeho stínil na některé z nich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 16, 'Scházelo se pak množství z okolních měst do Jeruzaléma, nesouce nemocné a trápené od duchů nečistých, a uzdravováni byli všickni.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 17, 'Tedy povstav nejvyšší kněz {biskup} a všickni, kteříž byli s ním, (jenž byli saducejské sekty,) naplněni jsou závistí.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 18, 'I vztáhli ruce na apoštoly, a vsázeli je do žaláře obecného.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 19, 'Ale anděl Páně v noci otevřev dvéře u žaláře, vyvedl je ven a řekl:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 20, 'Jděte, a postavíce se, mluvte lidu v chrámě všecka slova života tohoto.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 21, 'Tedy oni uslyševše, vešli na úsvitě do chrámu a učili. Přišed pak nejvyšší kněz {biskup} a ti, kteříž s ním byli, svolali radu a všecky starší synů Izraelských, i poslali do žaláře, aby oni byli přivedeni.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 22, 'A služebníci přišedše, nenalezli jich v žaláři. A navrátivše se, vypravovali,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 23, 'Řkouce: Žalář zajisté nalezli jsme zavřený se vší pilností, a strážné vně stojící u dveří, ale otevřevše, žádného jsme tam nenalezli.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 24, 'A když uslyšeli řeči tyto i nejvyšší kněz {biskup} i úředník chrámu i přední kněží, nerozuměli, co by se to stalo.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 25, 'A přišed kdosi, pověděl jim, řka: Aj, muži, kteréž jste vsázeli do žaláře, v chrámě stojí a učí lid.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 26, 'Tehdy odšed úředník s služebníky, přivedl je bez násilé; (nebo se báli lidu, aby nebyli ukamenováni.)');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 27, 'A přivedše je, postavili je v radě. I otázal se jich nejvyšší kněz {biskup},');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 28, 'Řka: Zdaliž jsme vám přísně nepřikázali, abyste neučili v tom jménu? A aj, naplnili jste Jeruzalém učením svým, a chcete na nás uvésti krev člověka toho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 29, 'Odpověděv pak Petr a apoštolé, řekli: Více sluší poslouchati Boha než lidí.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 30, 'Bůh otců našich vzkřísil Ježíše, kteréhož jste vy zamordovali, pověsivše na dřevě.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 31, 'Toho Bůh, kníže a spasitele, povýšil pravicí svou, aby bylo dáno lidu Izraelskému pokání a odpuštění hříchů.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 32, 'A my jsme svědkové toho, což mluvíme, ano i Duch svatý, kteréhož dal Bůh těm, kteříž jsou poslušni jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 33, 'Oni pak slyševše to, rozzlobili se, a radili se o to, kterak by je vyhladili.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 34, 'Tedy povstav v radě jeden farizeus, jménem Gamaliel, zákona učitel, vzácný u všeho lidu, rozkázal, aby na malou chvíli ven vyvedli apoštoly.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 35, 'I řekl jim: Muži Izraelští, pilně se rozmyslte při těchto lidech, co máte činiti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 36, 'Nebo před těmito časy byl povstal Teudas, pravě se býti něčím, jehož se přídrželo mužů v počtu okolo čtyř set. Kterýž zahynul, i všickni, kteříž přistoupili k němu, rozptýleni jsou a v nic obráceni.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 37, 'Po něm pak povstal Judas Galilejský za dnů popisu, a mnoho lidu po sobě obrátil. Ale i ten zahynul, a všickni, kteřížkoli přistoupili k němu, rozptýleni jsou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 38, 'A protož nyní pravím vám: Dejte pokoj těmto lidem, a nechte jich. Nebo jestližeť jest z lidí rada tato aneb dílo toto, rozprchneť se;');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 39, 'Pakliť jest z Boha, nebudete moci toho zkaziti. Abyste snad i Bohu odporní nalezeni nebyli.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 40, 'I povolili jemu. A povolavše apoštolů, a zmrskavše je, přikázali, aby nemluvili ve jménu Ježíšovu. I propustili je.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 41, 'Oni pak šli z toho shromáždění, radujíce se, že jsou hodni učiněni trpěti protivenství pro jméno Pána Ježíše.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 42, 'Na každý pak den nepřestávali v chrámě i po domích učiti a zvěstovati Ježíše Krista.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 1, 'A v těch dnech, když se rozmnožovali učedlníci, stalo se reptání Řeků proti Židům, že by zanedbávány byly v přisluhování vezdejším vdovy jejich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 2, 'Tedy dvanácte svolavše množství učedlníků, řekli: Není slušné, abychom my, opustíce slovo Boží, přisluhovali stolům.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 3, 'Protož, bratří, vybeřte z sebe mužů sedm dobropověstných, plných Ducha svatého a moudrosti, jimž bychom poručili tu práci.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 4, 'My pak modlitby a služby slova pilni budeme.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 5, 'I líbila se ta řeč všemu množství. I vyvolili Štěpána, muže plného víry a Ducha svatého, a Filipa, a Prochora, a Nikánora, a Timona, a Parména, a Mikuláše Antiochenského, k víře v nově obráceného.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 6, 'Ty postavili před oblíčejem apoštolů, kteříž pomodlivše se, vzkládali na ně ruce.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 7, 'I rostlo slovo Boží a rozmáhal se počet učedlníků v Jeruzalémě velmi. Mnohý také zástup kněží poslouchal víry.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 8, 'Štěpán pak, jsa plný víry a moci, činil divy a zázraky veliké v lidu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 9, 'I povstali někteří z školy, kteráž sloula Libertinských, a Cyrenenských, a Alexandrinských, a těch, kteříž byli z Cilicie a Azie, hádajíce se s Štěpánem.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 10, 'Ale nemohli odolati moudrosti a Duchu, kterýž mluvil.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 11, 'Tedy lstivě nastrojili muže, kteříž řekli: My jsme jej slyšeli mluviti slova rouhavá proti Mojžíšovi a proti Bohu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 12, 'A tak zbouřili lid a starší i zákonníky, a obořivše se na něj, chytili jej, a vedli do rady.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 13, 'I vystavili falešné svědky, kteříž řekli: Člověk tento nepřestává mluviti slov rouhavých proti místu tomuto svatému i zákonu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 14, 'Nebo jsme slyšeli jej, an praví: Že ten Ježíš Nazaretský zkazí místo toto, a promění ustanovení, kteráž nám vydal Mojžíš.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 15, 'A pilně patříce na něj všickni, kteříž seděli v radě, viděli tvář jeho, jako tvář anděla.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 1, 'Tedy řekl nejvyšší kněz {biskup}: Jestli-liž to tak?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 2, 'A on řekl: Muži bratří a otcové, slyšte. Bůh slávy ukázal se otci našemu Abrahamovi, když byl v Mezopotamii, prvé než bydlil v Cháran.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 3, 'A řekl jemu: Vyjdi z země své a z příbuznosti své, a poď do země, kterouž ukáži tobě.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 4, 'Tedy vyšed z země Kaldejské, bydlil v Cháran. A odtud, když umřel otec jeho, přestěhoval jej do země této, v kteréž vy nyní bydlíte.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 5, 'A nedal jemu dědictví v ní, ani šlepěje nožné, ač byl jemu ji slíbil dáti k vládařství, i semeni jeho po něm, když ještě neměl syna.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 6, 'Mluvil pak Bůh takto: Budeť símě tvé pohostinu v zemi cizí, a bude v službu podrobeno, a zle s ním budou nakládati za čtyři sta let.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 7, 'Ale národ ten, jemuž sloužiti budou, já souditi budu, pravíť Bůh. A potom zase vyjdou, a sloužiti mi budou na tomto místě.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 8, 'I vydal jemu smlouvu obřízky. A tak zplodil Izáka, a obřezal jej osmého dne, a Izák Jákoba, a Jákob dvanácte patriarchů.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 9, 'A patriarchové v nenávisti měvše Jozefa, prodali jej do Egypta. Ale Bůh byl s ním.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 10, 'A vysvobodil ho ze všech úzkostí jeho, a dal jemu milost a moudrost před tváří Faraona, krále Egyptského, kterýž ho ustanovil úředníkem nad Egyptem a nade vším domem svým.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 11, 'Potom přišel hlad na všecku zemi Egyptskou i Kananejskou, a ssoužení veliké, aniž měli pokrmů otcové naši.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 12, 'A uslyšev Jákob, že by obilé bylo v Egyptě, poslal otce naše jednou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 13, 'A podruhé poznán jest Jozef od bratří svých, a zjevena jest Faraonovi rodina Jozefova.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 14, 'Tedy poslav Jozef, přistěhoval otce svého Jákoba, i všecku rodinu svou v osobách sedmdesáti pěti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 15, 'I vstoupil Jákob do Egypta, a umřel on i otcové naši.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 16, 'I přeneseni jsou do Sichem, a pochováni v hrobě, kterýž byl koupil Abraham za stříbro od synů Emorových, otce Sichemova.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 17, 'Když se pak přibližoval čas zaslíbení, o kterémž byl přisáhl Bůh Abrahamovi, rostl lid a množil se v Egyptě,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 18, 'Až v tom povstal jiný král, kterýž neznal Jozefa.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 19, 'Ten lstivě nakládaje s pokolením naším, trápil otce naše, tak že musili vyhazovati nemluvňátka svá, aby se nerozplozovali.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 20, 'V tom času narodil se Mojžíš, a byl velmi krásný, kterýž chován jest za tři měsíce v domě otce svého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 21, 'A když vyložen byl, vzala jej dcera Faraonova, a vychovala jej sobě za syna.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 22, 'I vyučen jest Mojžíš vší moudrosti Egyptské, a byl mocný v řečech i v skutcích.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 23, 'A když jemu bylo čtyřidceti let, vstoupilo na srdce jeho, aby navštívil bratří své, syny Izraelské.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 24, 'A uzřev jednoho, an bezpráví trpí, zastal ho, a pomstil toho, kterýž bezpráví trpěl, zabiv Egyptského.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 25, 'Domníval se zajisté, že bratří jeho rozumějí, že skrze ruku jeho chce jim dáti Bůh vysvobození, ale oni nerozuměli.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 26, 'Druhého pak dne ukázal se jim, když se vadili, i vedl je ku pokoji, řka: Muži bratří jste, i proč křivdu činíte sobě vespolek?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 27, 'Ten pak, kterýž činil křivdu bližnímu, odehnal ho, řka: Kdo tě ustanovil knížetem a soudcím nad námi?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 28, 'Což ty mne chceš zamordovati, jako jsi včera zabil Egyptského?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 29, 'I utekl Mojžíš pro to slovo, a bydlil pohostinu v zemi Madianské, kdež zplodil dva syny.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 30, 'A když se vyplnilo let čtyřidceti, ukázal se jemu na poušti hory Sinai anděl Páně, v plameni ohně ve kři.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 31, 'A Mojžíš uzřev, divil se tomu vidění. A když blíže přistoupil, aby to pilněji spatřil, stal se k němu hlas Páně:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 32, 'Jáť jsem Bůh otců tvých, Bůh Abrahamův, a Bůh Izákův, a Bůh Jákobův. I zhroziv se Mojžíš, nesměl patřiti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 33, 'I řekl jemu Pán: Zzuj obuv s noh svých; nebo místo, na kterémž stojíš, země svatá jest.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 34, 'Viděl jsem, viděl trápení lidu svého, kterýž jest v Egyptě, a vzdychání jejich uslyšel jsem, a sstoupil jsem, abych je vysvobodil. Protož nyní poď, pošli tě do Egypta.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 35, 'Toho Mojžíše, kteréhož se odepřeli, řkouce: Kdo tě ustanovil knížetem a soudcím? tohoť Bůh kníže a vysvoboditele poslal, skrze ruku anděla, kterýž se jemu ukázal ve kři.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 36, 'A ten je vyvedl, čině divy a zázraky v zemi Egyptské a na moři červeném, i na poušti za čtyřidceti let.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 37, 'Toť jest ten Mojžíš, kterýž řekl synům Izraelským: Proroka vám vzbudí Pán Bůh váš z bratří vašich, jako mne; toho poslouchejte.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 38, 'Onť jest, kterýž byl mezi lidem na poušti s andělem, kterýž mluvil k němu na hoře Sinai, i s otci našimi, kterýž přijal slova živá, aby je nám vydal.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 39, 'Jehož nechtěli poslušni býti otcové naši, ale zavrhli jej, a odvrátili se srdci svými do Egypta,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 40, 'Řkouce Aronovi: Učiň nám bohy, kteříž by šli před námi; nebo Mojžíšovi tomu, kterýž nás vyvedl z země Egyptské, nevíme, co se přihodilo.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 41, 'I udělali v těch dnech tele, a obětovali oběti té modle, a veselili se v díle rukou svých.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 42, 'I odvrátil se Bůh, a vydal je, aby sloužili vojsku nebeskému, jakož napsáno jest v knihách prorockých: Zdaliž jste mi oběti aneb dary obětovali za čtyřidceti let na poušti, dome Izraelský?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 43, 'Nýbrž nosili jste stánek Molochův, a hvězdu boha svého Remfan, ta podobenství, kteráž jste zdělali sobě, abyste se jim klaněli. Protož přestěhuji vás za Babylon.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 44, 'Stánek svědectví měli otcové naši na poušti, jakož byl nařídil ten, kterýž řekl Mojžíšovi, aby jej udělal podlé způsobu toho, kterýž byl viděl.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 45, 'Kterýž přijavše otcové naši, vnesli s Jozue tam, kdež bylo vládařství pohanů, kteréž vyhnal Bůh od tváři otců našich, až do dnů Davida.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 46, 'Kterýž nalezl milost před oblíčejem Božím, a prosil, aby nalezl stánek Bohu Jákobovu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 47, 'Šalomoun pak udělal jemu dům.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 48, 'Ale Nejvyšší nebydlí v chrámích rukou udělaných, jakož dí prorok:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 49, 'Nebe jest mi stolice a země podnož noh mých, i jakýž mi dům uděláte? praví Pán. Aneb jaké jest místo odpočívání mého?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 50, 'Zdaliž ruka má všeho toho neučinila?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 51, 'Tvrdošijní a neobřezaného srdce i uší, vy jste se vždycky Duchu svatému protivili, jakž otcové vaši, tak i vy.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 52, 'Kterému z proroků otcové vaši se neprotivili? Zmordovali zajisté ty, kteříž předzvěstovali příchod spravedlivého tohoto, jehož vy nyní zrádci a vražedlníci jste.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 53, 'Kteříž jste vzali zákon působením andělským, a neostříhali jste.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 54, 'Tedy slyšíce to, rozzlobili se v srdcích svých, a škřipěli zuby na něho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 55, 'On pak pln jsa Ducha svatého, pohleděv do nebe, uzřel slávu Boží a Ježíše stojícího na pravici Boží.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 56, 'I řekl: Aj, vidím, nebesa otevřená a Syna člověka stojícího na pravici Boží.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 57, 'A oni zkřikše hlasem velikým, zacpali uši své, a obořili se jednomyslně na něj.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 58, 'A vyvedše jej z města, kamenovali ho. A svědkové složili roucha svá u noh mládence, kterýž sloul Saul.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 59, 'I kamenovali Štěpána modlícího se a řkoucího: Pane Ježíši, přijmi ducha mého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 60, 'A poklek na kolena, zvolal hlasem velikým: Pane, nepokládej jim toho za hřích. A to pověděv, usnul.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 1, 'Saul pak přivolil k usmrcení jeho. I přišlo v ten čas veliké protivenství na církev, kteráž byla v Jeruzalémě, a všickni se rozprchli po krajinách Judských a Samařských, kromě apoštolů.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 2, 'I pochovali Štěpána muži pobožní, a plakali velmi nad ním.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 3, 'Saul pak hubil církev, do domů vcházeje, a jímaje muže i ženy, dával je do žaláře.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 4, 'Ti pak, kteříž se byli rozprchli, chodili, kážíce slovo.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 5, 'A Filip všed do města Samaří, kázal jim Krista.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 6, 'I pozorovali zástupové jednomyslně toho, což se pravilo od Filipa, slyšíce a vidouce divy, kteréž činil.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 7, 'Nebo duchové nečistí z mnohých, kteříž je měli, křičíce hlasem velikým, vycházeli, a mnozí šlakem poražení a kulhaví uzdraveni jsou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 8, 'A stala se radost veliká v tom městě.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 9, 'Muž pak nějaký, jménem Šimon, před tím v tom městě čáry provodil, a lid Samařský mámil, pravě se býti nějakým velikým.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 10, 'Na něhož pozor měli všickni, od nejmenšího až do největšího, říkajíce: Tentoť jest Boží moc veliká.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 11, 'Pozor pak měli na něho, proto že je za mnohý čas mámil čáry.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 12, 'A když uvěřivše Filipovi zvěstujícímu o království Božím a o jménu Ježíše Krista, křtili se muži i ženy,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 13, 'Tedy i ten Šimon uvěřil, a pokřtěn byv, přídržel se Filipa, a vida zázraky a moci veliké činěné, děsil se.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 14, 'Uslyšavše pak v Jeruzalémě apoštolé, že by Samaří přijala slovo Boží, poslali k nim Petra a Jana.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 15, 'Kteříž přišedše, modlili se za ně, aby přijali Ducha svatého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 16, '(Nebo ještě byl na žádného z nich nesstoupil, ale pokřtěni toliko byli ve jménu Pána Ježíše.)');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 17, 'Tehdy vzkládali na ně ruce, a oni přijali Ducha svatého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 18, 'I uzřev Šimon, že skrze vzkládání rukou apoštolských dává se Duch svatý, přinesl jim peníze,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 19, 'Řka: Dejte i mně tu moc, ať, na kohož bych koli vzložil ruce, přijme Ducha svatého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 20, 'I řekl jemu Petr: Peníze tvé buďtež s tebou na zatracení, proto že jsi se domníval, že by dar Boží mohl býti zjednán za peníze.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 21, 'Nemáš dílu ani losu v této věci; nebo srdce tvé není upřímé před Bohem.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 22, 'Protož čiň pokání z této své nešlechetnosti, a pros Boha, zda by odpuštěno bylo tobě to myšlení srdce tvého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 23, 'Nebo v žluči hořkosti a v svazku nepravosti tebe býti vidím.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 24, 'I odpověděv Šimon, řekl: Modltež vy se za mne Pánu, aby na mne nepřišlo něco z těch věcí, kteréž jste mluvili.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 25, 'Oni pak osvědčovavše a mluvivše slovo Páně, navrátili se do Jeruzaléma, a ve mnohých městečkách Samaritánských kázali evangelium.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 26, 'Anděl pak Páně mluvil k Filipovi, řka: Vstaň a jdi ku polední straně na cestu, kteráž vede od Jeruzaléma do Gázy, kteréž jest pusté.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 27, 'I vstav, šel. A aj, muž Mouřenín, kleštěnec, komorník královny Mouřenínské Kandáces, kterýž vládl všemi poklady jejími, a byl přijel do Jeruzaléma, aby se modlil,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 28, 'Navracoval se, na voze svém sedě, a četl Izaiáše proroka.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 29, 'I řekl Duch Filipovi: Přistup, a přiviň se k vozu tomu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 30, 'A přiběh Filip, slyšel jej, an čte Izaiáše proroka. I řekl: Rozumíš-liž medle, co čteš?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 31, 'A on řekl: Kterakž bych mohl, leč by mi kdo vyložil? I prosil Filipa, aby vstoupil a seděl s ním.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 32, 'Místo pak toho písma, kteréž četl, toto bylo: Jako ovce k zabití veden jest, a jako beránek němý před tím, kdož jej střiže, tak neotevřel úst svých.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 33, 'V ponížení jeho odsouzení jeho vyhlazeno jest, rod pak jeho kdo vypraví, ačkoli zahlazen byl z země život jeho?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 34, 'A odpovídaje komorník Filipovi, dí: Prosím tebe, o kom toto mluví prorok? Sám-li o sobě, čili o někom jiném?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 35, 'Tedy otevřev Filip ústa svá, a počav od toho písma, zvěstoval jemu Ježíše.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 36, 'A když jeli cestou, přijeli k jedné vodě. I řekl komorník: Aj, voda. Proč nemám býti pokřtěn?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 37, 'I řekl Filip: Věříš-li celým srdcem, slušíť. A on odpověděv, řekl: Věřím, že Ježíš Kristus jest Syn Boží.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 38, 'I rozkázal státi vozu, a sstoupili oba do té vody, i Filip i komorník. I pokřtil ho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 39, 'A když vystoupili z vody, Duch Páně pochopil Filipa, a neviděl ho více komorník; nebo jel cestou svou, raduje se.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 40, 'Filip pak nalezen jest v Azotu; a chodě, kázal evangelium všechněm městům, až přišel do Cesaree.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 1, 'Saul pak ještě dychtě po pohrůžkách a po mordu proti učedlníkům Páně, šel k nejvyššímu knězi {biskupovi},');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 2, 'A vyžádal od něho listy do Damašku do škol, nalezl-li by tam té cesty které muže neb ženy, aby svázané přivedl do Jeruzaléma.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 3, 'A když byl na cestě, stalo se, že již přibližoval se k Damašku. Tedy pojednou rychle obklíčilo jej světlo s nebe.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 4, 'A padna na zem, uslyšel hlas k sobě řkoucí: Sauli, Sauli, proč mi se protivíš?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 5, 'Kterýž řekl: I kdo jsi Pane? A Pán řekl: Já jsem Ježíš, jemuž ty se protivíš. Tvrdoť jest tobě proti ostnům se zpěčovati.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 6, 'A on třesa se a boje se, řekl: Pane, co chceš, abych činil? A Pán k němu: Vstaň a jdi do města, a bude tobě povědíno, co bys ty měl činiti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 7, 'Ti pak muži, kteříž šli s ním, stáli, ohromeni jsouce, hlas zajisté slyšíce, ale žádného nevidouce.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 8, 'I vstal Saul z země, a otevřev oči své, nic neviděl. Tedy pojavše ho za ruce, uvedli jej do Damašku.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 9, 'I byl tu za tři dni, nevida, a nejedl, ani nepil.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 10, 'Byl pak jeden učedlník v Damašku, jménem Ananiáš. I řekl jemu Pán u vidění: Ananiáši. A on řekl: Aj, já, Pane.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 11, 'A Pán k němu: Vstaň a jdi do ulice, kteráž slove přímá, a hledej v domě Judově Saule, jménem Tarsenského. Nebo aj, modlí se.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 12, 'A viděl u vidění muže, Ananiáše jménem, an jde k němu, a vzkládá naň ruku, aby prohlédl.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 13, 'I odpověděl Ananiáš: Pane, slyšel jsem od mnohých o tom muži, kterak mnoho zlého činil svatým tvým v Jeruzalémě.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 14, 'A i zdeť má moc od předních kněží {biskupů}, aby jímal všecky, kteříž vzývají jméno tvé.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 15, 'I řekl jemu Pán: Jdi, neboť jest on má nádoba vyvolená, aby nosil jméno mé před pohany i krále, i před syny Izraelské.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 16, 'Jáť zajisté ukáži jemu, kterak on mnoho musí trpěti pro jméno mé.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 17, 'I šel Ananiáš, a všel do toho domu, a vloživ ruce naň, řekl: Sauli bratře, Pán Ježíš poslal mne, kterýž se ukázal tobě na cestě, po níž jsi šel, abys prohlédl, a naplněn byl Duchem svatým.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 18, 'A hned spadly s očí jeho jako lupiny, i prohlédl pojednou; a vstav, pokřtěn jest.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 19, 'A přijav pokrm, posilnil se. I zůstal Saul s učedlníky, kteříž byli v Damašku, za několik dní.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 20, 'A hned v školách kázal Krista, že on jest Syn Boží.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 21, 'I divili se náramně všickni, kteříž jej slyšeli, a pravili: Zdaliž toto není ten, kterýž hubil v Jeruzalémě ty, kteříž vzývali jméno toto, a sem na to přišel, aby je svázané vedl k předním kněžím {biskupům}?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 22, 'Saul pak více se zmocňoval, a zahanboval Židy, kteříž bydleli v Damašku, potvrzuje toho, že ten jest Kristus.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 23, 'A když přeběhlo drahně dnů, radu mezi sebou na tom zavřeli Židé, aby jej zabili.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 24, 'Ale zvěděl Saul o těch úkladech jejich. Ostříhali také i bran ve dne i v noci, aby jej zahubili.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 25, 'Ale učedlníci v noci vzavše ho, spustili jej po provaze přes zed v koši.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 26, 'Přišed pak Saul do Jeruzaléma, pokoušel se přitovaryšiti k učedlníkům, ale báli se ho všickni, nevěříce, by byl učedlníkem.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 27, 'Barnabáš pak přijav jej, vedl ho k apoštolům, a vypravoval jim, kterak na cestě viděl Pána, a že mluvil s ním, a kterak v Damašku svobodně mluvil ve jménu Ježíše.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 28, 'I bydlil s nimi v Jeruzalémě,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 29, 'A směle mluvil ve jménu Pána Ježíše, a hádal se s Řeky; oni pak usilovali ho zabiti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 30, 'To zvěděvše bratří, dovedli ho do Cesaree, a poslali jej do Tarsu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 31, 'A tak zborové po všem Judstvu a Galilei i Samaří měli pokoj, vzdělávajíce se, a chodíce v bázni Páně, a rozhojňovali se potěšením Ducha svatého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 32, 'Stalo se pak, že Petr, když procházel všecky, přišel také k svatým, kteříž bydleli v Lyddě.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 33, 'I nalezl tu člověka jednoho, jménem Eneáše, již od osmi let na loži ležícího, kterýž byl šlakem poražený.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 34, 'I řekl mu Petr: Eneáši, uzdravuje tebe Ježíš Kristus; vstaň, a ustel sobě. A hned vstal.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 35, 'I viděli jej všickni, kteříž bydlili v Lyddě a v Sároně, kteříž se obrátili ku Pánu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 36, 'Byla pak jedna učedlnice v Joppen, jménem Tabita, což se vykládá Dorkas. Ta byla plná skutků dobrých a almužen, kteréž činila.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 37, 'I stalo se v těch dnech, že roznemohši se, umřela. Kterouž umyvše, položili na síň vrchní.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 38, 'A že byla blízko Lydda od Joppen, uslyšavše učedlníci, že by tam byl Petr, poslali k němu dva muže, prosíce ho, aby sobě neobtěžoval přijíti až k nim.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 39, 'Tedy vstav Petr, šel s nimi. A když přišel, vedli jej na síň. I obstoupily ho všecky vdovy, plačíce, a ukazujíce sukně a pláště, kteréž jim dělala, dokudž s nimi byla, Dorkas.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 40, 'I rozkázav všechněm vyjíti ven Petr, poklek na kolena, modlil se, a obrátiv se k tomu tělu, řekl: Tabito, vstaň. A ona otevřela oči své, a uzřevši Petra, posadila se.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 41, 'A podav jí ruky, pozdvihl jí; a povolav svatých a vdov, ukázal jim ji živou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 42, 'I rozhlášeno jest to po všem Joppen, a uvěřili mnozí v Pána.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 43, 'I stalo se, že za mnohé dni pozůstal Petr v Joppen u nějakého Šimona koželuha.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 1, 'Muž pak nějaký byl v Cesarii, jménem Kornelius, setník z zástupu, kterýž sloul Vlaský,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 2, 'Nábožný a bohobojný se vším domem svým, čině almužny mnohé lidu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 3, 'A modlívaje se vždycky Bohu, viděl u vidění zřetelně, jako v hodinu devátou na den, anděla Božího, an všel k němu, a řekl jemu: Kornéli.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 4, 'A on pilně popatřiv naň, a sstrašiv se, řekl: Co chceš, Pane? I řekl jemu: Modlitby tvé a almužny tvé vstoupily na pamět před tváří Boží.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 5, 'Protož nyní pošli muže do Joppen, a povolej Šimona, kterýž má přijmí Petr.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 6, 'Tenť hospodu má u nějakého Šimona koželuha, kterýž má dům u moře. Onť poví tobě, co bys ty měl činiti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 7, 'A když odšel anděl, kterýž mluvil Korneliovi, zavolal dvou služebníků svých, a rytíře pobožného z těch, kteříž vždycky při něm byli.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 8, 'A oznámiv jim všecko to, poslal je do Joppen.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 9, 'Nazejtří pak, když oni šli, a přibližovali se k městu, všel Petr na horu, aby se modlil, okolo hodiny šesté.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 10, 'A potom velice zlačněv, chtěl pojísti. Když pak oni strojili, připadlo na něj mysli vytržení.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 11, 'I uzřel nebe otevřené a sstupující k sobě nádobu jakous jako prostěradlo veliké, za čtyři rohy uvázanou, ana se spouští na zem,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 12, 'Na níž byla všeliká zemská hovada čtvernohá, a zvířata, a zeměplazové, i ptactvo nebeské.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 13, 'I stal se hlas k němu: Vstaň, Petře, bí a jez.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 14, 'I řekl Petr: Nikoli, Pane, neboť jsem nikdy nejedl nic obecného aneb nečistého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 15, 'Tedy opět podruhé stal se hlas k němu: Cožť Bůh očistil, neměj ty toho za nečisté.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 16, 'A to se stalo potřikrát. I vzata jest zase ta nádoba do nebe.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 17, 'A když Petr sám u sebe rozjímal, co by znamenalo vidění to, kteréž viděl, aj, muži ti, kteříž posláni byli od Kornelia, ptajíce se na dům Šimonův, stáli přede dveřmi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 18, 'A zavolavše, tázali se: Má-li zde hospodu Šimon, kterýž má přijmí Petr?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 19, 'A když Petr přemyšloval o tom vidění, řekl jemu Duch: Aj, muži tři hledají tebe.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 20, 'Protož vstana, sejdi dolů, a jdi s nimi, nic se nerozpakuje; neboť jsem já je poslal.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 21, 'Tedy sšed Petr k těm mužům, kteříž posláni byli k němu od Kornelia, řekl: Aj, jáť jsem ten, kteréhož hledáte. Jaká jest příčina, pro niž jste přišli?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 22, 'Oni pak řekli: Kornelius setník, muž spravedlivý a bohabojící, i svědectví dobré mající ode všeho národu Židovského, u vidění napomenut jest od anděla svatého, aby povolal tebe do domu svého, a slyšel řeč od tebe.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 23, 'Tedy zavolav jich do domu, přijal je do hospody. Druhého pak dne Petr šel s nimi, a někteří bratří z Joppen šli s ním.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 24, 'A nazejtří přišli do Cesaree. Kornelius pak očekával jich, svolav příbuzné své a přátely blízké.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 25, 'I stalo se, když vcházel Petr, vyšel proti němu Kornelius, a padna k nohám jeho, klaněl se mu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 26, 'Ale Petr pozdvihl ho, řka: Vstaň, i jáť také sám člověk jsem.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 27, 'A rozmlouvaje s ním, všel, a nalezl mnoho těch, kteříž se byli sešli.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 28, 'I řekl jim: Vy víte, že neslušné jest muži Židu připojiti se aneb přistoupiti k cizozemci, ale mně ukázal Bůh, abych žádného člověka nepravil obecným neb nečistým býti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 29, 'Protož bez odporu přišel jsem, povolán jsa. I ptám se, pro kterou příčinu poslali jste pro mne?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 30, 'A Kornelius řekl: Před čtyřmi dny postil jsem se až do této hodiny, a v hodinu devátou modlil jsem se v domě svém. A aj, postavil se přede mnou muž v rouše bělostkvoucím.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 31, 'A řekl: Kornéli, uslyšánať jest modlitba tvá, a almužny tvé jsouť v paměti před tváří Boží.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 32, 'Protož pošli do Joppen, a povolej Šimona, kterýž slove Petr. Tenť má hospodu v domě Šimona koželuha u moře; on přijda, bude mluviti tobě.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 33, 'Protož hned té chvíle jsem poslal k tobě, a ty jsi dobře učinil, žes přišel. Nyní tedy my všickni před oblíčejem Božím hotovi jsme slyšeti všecko, což jest koli přikázáno tobě od Boha.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 34, 'Tedy Petr otevřev ústa, řekl: V pravdě jsem shledal, že Bůh není přijimač osob.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 35, 'Ale v každém národu, kdož se ho bojí, a činí spravedlnost, příjemný jest jemu;');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 36, 'Jakž to oznámil synům Izraelským, zvěstuje pokoj skrze Ježíše Krista, kterýž jest Pánem všeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 37, 'Vy sami víte, co se dálo po všem Židovstvu, počna od Galilee, po křtu, kterýž kázal Jan:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 38, 'Kterak Ježíše od Nazaréta pomazal Bůh Duchem svatým a mocí. Kterýž chodil, dobře čině, a uzdravuje všecky posedlé od ďábla; nebo Bůh s ním byl.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 39, 'A my jsme svědkové všeho toho, což činil v krajině Judské a v Jeruzalémě. Kteréhož zamordovali, pověsivše na dřevě.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 40, 'Toho Bůh vzkřísil třetího dne, a způsobil to, aby zjeven byl,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 41, 'Ne všemu lidu, ale svědkům prvé k tomu zřízeným od Boha, nám, kteříž jsme s ním jedli a pili po jeho z mrtvých vstání.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 42, 'A přikázal nám kázati lidu a svědčiti, že on jest ten ustanovený od Boha soudce živých i mrtvých.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 43, 'Jemuť všickni proroci svědectví vydávají, že odpuštění hříchů vezme skrze jméno jeho všeliký, kdožkoli uvěřil by v něho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 44, 'A když ještě Petr mluvil slova tato, sstoupil Duch svatý na všecky, kteříž poslouchali slova.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 45, 'I užasli se ti, kteříž z obřezaných věřící byli, kteříž byli přišli s Petrem, že i na pohany dar Ducha svatého jest vylit.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 46, 'Nebo slyšeli je, ani mluví jazyky rozličnými, a velebí Boha. Tehdy odpověděl Petr:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 47, 'Zdali může kdo zabrániti vody, aby tito nebyli pokřtěni, kteříž Ducha svatého přijali jako i my?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 48, 'A rozkázal je pokřtiti ve jménu Páně. I prosili ho, aby u nich pobyl za některý den.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 1, 'Uslyšeli pak apoštolé a bratří, kteříž byli v Judstvu, že by i pohané přijali slovo Boží.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 2, 'A když přišel Petr do Jeruzaléma, domlouvali se naň ti, kteříž byli z obřezaných,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 3, 'Řkouce: K mužům neobřezaným všel jsi, a jedl jsi s nimi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 4, 'Tedy začav Petr, vypravoval jim pořád, řka:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 5, 'Byl jsem v městě Joppen, modle se. I viděl jsem u vytržení mysli vidění, nádobu nějakou sstupující jako prostěradlo veliké, za čtyři rohy spouštějící se s nebe, a přišla až ke mně.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 6, 'Do kteréž pohleděv pilně, spatřil jsem hovada zemská čtvernohá i zvířata, a zeměplazy, i ptactvo nebeské.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 7, 'Slyšel jsem k sobě také hlas řkoucí: Vstaň, Petře, bí a jez.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 8, 'I řekl jsem: Nikoli, Pane, nebo nic obecného aneb nečistého nikdy nevcházelo v ústa má.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 9, 'I odpověděl mi hlas podruhé s nebe: Co Bůh očistil, neměj ty toho za nečisté.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 10, 'A to se stalo potřikrát. I vtrženo jest zase to všecko do nebe.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 11, 'A aj, hned té chvíle tři muži stáli u domu, v kterémž jsem byl, posláni jsouce ke mně z Cesaree.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 12, 'I řekl mi Duch, abych šel s nimi, nic se nerozpakuje. A šlo se mnou i těchto šest bratří, a vešli jsme do domu muže toho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 13, 'Kterýž vypravoval nám, kterak viděl anděla v domě svém, an se před ním postavil, a řekl jemu: Pošli do Joppen muže, a povolej Šimona, kterýž slove Petr.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 14, 'Onť tobě bude mluviti slova, skrze něž spasen budeš ty i všecken tvůj dům.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 15, 'Když jsem pak já mluviti začal, sstoupil Duch svatý na ně jako i na nás na počátku.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 16, 'I rozpomenul jsem se na slovo Páně, kteréž byl pověděl: Jan zajisté křtil vodou, ale vy pokřtěni budete Duchem svatým.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 17, 'Poněvadž tedy jednostejný dar dal jim Bůh jako i nám věřícím v Pána Ježíše Krista, i kdož jsem já byl, abych mohl zabrániti Bohu?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 18, 'To uslyšavše, spokojili se, a slavili Boha, řkouce: Tedy i pohanům Bůh pokání dal k životu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 19, 'Ti pak, kteříž se byli rozprchli příčinou ssoužení, kteréž se bylo stalo pro Štěpána, přišli až do Fenicen a Cypru a do Antiochie, žádnému nemluvíce slova než samým toliko Židům.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 20, 'A byli někteří z nich muži z Cypru a z Cyrénu, kteříž přišedše do Antiochie, mluvili Řekům, zvěstujíce Pána Ježíše.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 21, 'A byla ruka Páně s nimi, a veliký počet věřících obrátil se ku Pánu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 22, 'I přišla pověst o tom k církvi, kteráž byla v Jeruzalémě. I poslali Barnabáše, aby šel až do Antiochie.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 23, 'Kterýž přišed tam, a uzřev milost Boží, zradoval se, a napomínal všech, aby v úmyslu srdce trvali v Pánu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 24, 'Nebo byl muž dobrý, a plný Ducha svatého a víry. I přibyl veliký zástup Pánu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 25, 'Tedy odšel Barnabáš do Tarsu hledati Saule, a nalezna jej, přivedl ho do Antiochie.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 26, 'I byli přes celý rok při tom zboru, a učili zástup veliký, tak že nejprv tu v Antiochii učedlníci nazváni jsou křesťané.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 27, 'V těch pak dnech přišli z Jeruzaléma proroci do Antiochie.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 28, 'I povstav jeden z nich, jménem Agabus, oznamoval skrze Ducha, že bude hlad veliký po všem okršlku zemském. Kterýž i stal se za císaře Klaudia.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 29, 'Tedy učedlníci, jeden každý podlé možnosti své, umínili poslati ku pomoci bratřím přebývajícím v Judstvu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 30, 'Což i učinili, poslavše k starším skrze ruce Barnabáše a Saule.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 1, 'A při tom času dal se v to Heródes král, aby ssužoval některé z církve.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 2, 'I zamordoval Jakuba, bratra Janova, mečem.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 3, 'A vida, že se to líbilo Židům, umínil jíti i Petra. (A byli dnové přesnic.)');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 4, 'Kteréhož jav, do žaláře vsadil, poručiv jej šestnácti žoldnéřům k ostříhání, chtěje po velikonoci vyvesti jej lidu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 5, 'I byl Petr ostříhán v žaláři, modlitba pak ustavičná k Bohu dála se za něj od církve.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 6, 'A když jej již vyvesti měl Heródes, té noci spal Petr mezi dvěma žoldnéři, svázán byv dvěma řetězy, a strážní přede dveřmi ostříhali žaláře.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 7, 'A aj, anděl Páně postavil se, a světlo se zastkvělo v žaláři; a udeřiv Petra v bok, zbudil ho, řka: Vstaň rychle. I spadli jemu ti řetězové z rukou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 8, 'Tedy řekl jemu anděl: Opaš se a podvaž obuv svou. Tedy učinil tak. I řekl jemu: Oděj se pláštěm svým, a poď za mnou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 9, 'Tedy vyšed, bral se za ním, a nevěděl, by to pravé bylo, co se dálo skrze anděla, ale domníval se, že by vidění viděl.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 10, 'A prošedše skrze první i druhou stráž, přišli k bráně železné, kteráž vede do města, a ta se jim sama od sebe otevřela. A vyšedše, přešli ulici jednu, a hned odšel anděl od něho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 11, 'Tedy Petr přišed sám k sobě, řekl: Nyní právě vím, že poslal Pán anděla svého, a vytrhl mne z ruky Heródesovy, a ze všeho očekávání lidu Židovského.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 12, 'A pováživ toho, šel k domu Marie, matky Janovy, kterýž přijmí měl Marek, kdež se jich bylo mnoho sešlo, a modlili se.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 13, 'A když Petr potloukl na dvéře, vyšla děvečka, aby poslechla, jménem Ródé.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 14, 'A poznavši hlas Petrův, pro radost neotevřela dveří, ale vběhši, zvěstovala, že Petr stojí u dveří.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 15, 'A oni řekli jí: Blázníš. Ona pak potvrzovala, že tak jest. Tedy oni řekli: Anděl jeho jest.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 16, 'Ale Petr předce tloukl. A otevřevše, uzřeli jej, i ulekli se.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 17, 'A pokynuv na ně rukou, aby mlčeli, vypravoval jim, kterak jej Pán vyvedl z žaláře, a řekl: Pověztež to Jakubovi a bratřím. A vyšed, bral se na jiné místo.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 18, 'A když byl den, stal se rozbroj nemalý mezi žoldnéři o to, co se stalo při Petrovi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 19, 'Heródes pak ptaje se na něj, a nenalezna, vytazovav se na strážných, kázal je pryč vésti; a odebrav se z Judstva do Cesaree, přebýval tam.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 20, 'A v ten čas Heródes rozzlobil se proti Tyrským a Sidonským. Kteřížto jednomyslně přišli k němu, a namluvivše Blasta, předního komorníka královského, žádali za pokoj, proto že jejich krajiny potravu měly z království.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 21, 'V uložený pak den Heródes, obleka se v královské roucho, a posadiv se na soudné stolici, učinil k nim řeč.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 22, 'I zvolal lid, řka: Boží hlas, a ne lidský.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 23, 'A i hned ranil jej anděl Páně, proto že nevzdal slávy Bohu; a rozlez se červy, umřel.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 24, 'A slovo Páně rostlo a rozmáhalo se.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 25, 'Barnabáš pak a Saul navrátili se z Jeruzaléma, vykonavše službu, pojavše s sebou i Jana, kterýž přijmí měl Marek.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 1, 'Byli pak v církvi, kteráž byla v Antiochii, někteří proroci a učitelé, jako Barnabáš a Šimon, kterýž měl přijmí Černý, a Lucius Cyrenenský, a Manahen, kterýž byl spolu vychován s Heródesem tetrarchou, a Saul.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 2, 'A když oni služby Páně konali, a postili se, dí Duch svatý: Oddělte mi Barnabáše a Saule k dílu, k kterémuž jsem jich povolal.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 3, 'Tedy postíce se, a modlíce se, a vzkládajíce na ně ruce, propustili je.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 4, 'A oni posláni byvše od Ducha svatého, přišli do Seleucie, a odtud plavili se do Cypru.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 5, 'A přišedše do Salaminy, zvěstovali slovo Boží v školách Židovských; a měli s sebou i Jana k službě.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 6, 'A když zchodili ten ostrov až do Páfu, nalezli jakéhos čarodějníka, falešného proroka Žida, jemuž jméno Barjezus,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 7, 'Kterýž byl u znamenitého vládaře Sergia Pavla, může opatrného. Ten povolav Barnabáše a Saule, žádal slyšeti slovo Boží.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 8, 'Ale protivil se jim Elymas, ten čarodějník, (nebo se tak vykládá jméno jeho,) usiluje odvrátiti vládaře od víry.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 9, 'Tedy Saul, kterýž slove i Pavel, naplněn byv Duchem svatým, a pilně pohleděv na něj,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 10, 'Řekl: Ó plný vší lsti a vší nešlechetnosti, synu ďáblův, nepříteli vší spravedlnosti, což nepřestaneš převraceti cest Páně přímých?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 11, 'A aj, nyní ruka Páně nad tebou, a budeš slepý, nevida slunce až do času. A pojednou připadla na něj mrákota a tma, a jda vůkol, hledal, kdo by ho za ruku vedl.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 12, 'Tehdy vládař uzřev, co se stalo, uvěřil, divě se učení Páně.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 13, 'A pustivše se od Páfu Pavel a ti, kteříž s ním byli, přišli do Pergen v Pamfylii. Jan pak odšed od nich, vrátil se do Jeruzaléma.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 14, 'Oni pak šedše z Pergen, přišli do Antiochie Pisidické, a všedše do školy v den sobotní, posadili se.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 15, 'A když bylo po přečtení zákona a proroků, poslali k nim knížata školy té, řkouce: Muži bratří, máte-li úmysl jaké napomenutí učiniti k lidu, mluvte.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 16, 'Tedy Pavel povstav, a rukou pokynuv, řekl: Muži Izraelští, a kteříž se bojíte Boha, slyšte.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 17, 'Bůh lidu tohoto Izraelského vyvolil otce naše, a lidu povýšil, když byl pohostinu v zemi Egyptské, a v rameni vztaženém vyvedl je z ní.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 18, 'A za čas čtyřidceti let snášel jejich obyčeje na poušti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 19, 'A zahladiv sedm národů v zemi Kanán, rozdělil losem mezi ně zemi jejich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 20, 'A potom, téměř za čtyři sta a padesáte let, dával jim soudce až do Samuele proroka.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 21, 'A v tom žádali za krále, i dal jim Bůh Saule, syna Cis, muže z pokolení Beniaminova, za čtyřidceti let.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 22, 'A když toho zavrhl, vzbudil jim Davida krále, kterémuž svědectví dávaje, řekl: Nalezl jsem Davida, syna Jesse, muže podlé srdce svého, kterýž bude činiti všecku vůli mou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 23, 'Z jehož semene Bůh podlé zaslíbení vzbudil Izraelovi spasitele Ježíše,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 24, 'Před jehož příštím kázal Jan křest pokání všemu lidu Izraelskému.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 25, 'A když Jan běh dokonával, pravil: Kteréhož se mne domníváte býti, nejsem já, ale aj, jdeť po mně, u jehož noh obuvi rozvázati nejsem hoden.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 26, 'Muži bratří, synové rodu Abrahamova, a kteříž mezi vámi bojí se Boha, vám slovo spasení tohoto posláno jest.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 27, 'Nebo ti, kteříž přebývají v Jeruzalémě, a knížata jejich, toho Ježíše neznajíce, odsoudili, a tak hlasy prorocké, kteříž se na každou sobotu čtou, naplnili.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 28, 'A žádné příčiny smrti na něm nenalezše, prosili Piláta, aby zamordován byl.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 29, 'A když dokonali všecko, což o něm psáno bylo, složivše s dřeva, do hrobu jej položili.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 30, 'Bůh pak vzkřísil jej z mrtvých.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 31, 'Kterýž vidín jest po mnohé dni od těch, jenž spolu s ním byli přišli z Galilee do Jeruzaléma, kteříž jsou svědkové jeho k lidu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 32, 'A my vám zvěstujeme to zaslíbení, kteréž se stalo otcům, že Bůh naplnil je nám synům jejich, vzkřísiv Ježíše;');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 33, 'Jakož i v druhém žalmu napsáno jest: Syn můj jsi ty, já dnes zplodil jsem tebe.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 34, 'A že jej z mrtvých vzkřísil, aby se již více nenavracoval k porušení, takto řekl: Dám vám svaté věci Davidovy věrné.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 35, 'Protož i jinde dí: Nedáš svatému svému viděti porušení.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 36, 'David zajisté za svého věku poslouživ vůli Boží, usnul, a přiložen jest k otcům svým, a viděl porušení.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 37, 'Ale ten, kteréhož Bůh vzkřísil, neviděl porušení.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 38, 'Protož známo vám buď, muži bratří, že skrze toho zvěstuje se vám odpuštění hříchů.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 39, 'A to ode všech, od kterýchž jste nemohli skrze zákon Mojžíšův ospravedlněni býti, skrze tohoto, každý kdož věří, bývá ospravedlněn.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 40, 'Protož vizte, ať na vás nepřijde to, což jest v prorocích povědíno:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 41, 'Vizte potupníci, a podivte se, a na nic přiďte; nebo já dílo dělám za dnů vašich, dílo to, jemuž neuvěříte, byť vám kdo o něm vypravoval.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 42, 'A když vycházeli ze školy Židovské, prosili pohané, aby jim v druhou sobotu mluvili táž slova.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 43, 'A když bylo propuštěno shromáždění, šlo mnoho Židů, a nábožných znovu na víru obrácených za Pavlem a Barnabášem, kteříž promlouvajíce k nim, radili jim, aby trvali v milosti Boží.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 44, 'V druhou pak sobotu téměř všecko město sešlo se k slyšení slova Božího.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 45, 'A Židé vidouce zástupy, naplněni jsou závistí, a odporovali tomu, co bylo praveno od Pavla, protivíce a rouhajíce se.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 46, 'Tedy svobodně Pavel a Barnabáš řekli: Vámť mělo nejprv mluveno býti slovo Boží, ale poněvadž je zamítáte, a za nehodné sebe soudíte věčného života, aj, obracíme se ku pohanům.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 47, 'Neboť nám tak přikázal Pán, řka: Položil jsem tebe světlo pohanům, abys ty byl spasení až do končin země.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 48, 'A slyševše to pohané, radovali se, a velebili slovo Páně; a uvěřili všickni, což jich koli bylo předzřízeno k životu věčnému.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 49, 'I rozhlašovalo se slovo Páně po vší té krajině.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 50, 'Tedy Židé zbouřili ženy nábožné a poctivé a přední měšťany, a vzbudili protivenství proti Pavlovi a Barnabášovi, i vyhnali je z končin svých.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 51, 'A oni vyrazivše prach z noh svých na ně, přišli do Ikonie.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 52, 'Učedlníci pak naplněni byli radostí a Duchem svatým.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 1, 'I stalo se tolikéž v Ikonii, že vešli do školy Židovské, a mluvili, tak že uvěřilo i Židů i Řeků veliké množství.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 2, 'Ale kteříž z Židů nepovolní byli, ti zbouřili a zdráždili mysli pohanů proti bratřím.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 3, 'I byli tu za dlouhý čas, svobodně mluvíce v Pánu, kterýž svědectví vydával slovu milosti své, a působil to, aby se dáli divové a zázrakové skrze ruce jejich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 4, 'I rozdělilo se množství města, a jedni byli s Židy, jiní s apoštoly.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 5, 'A když se obořili i pohané i Židé s knížaty svými, aby jim posměch učinili, a kamenovali je,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 6, 'Srozuměvše tomu, utekli do měst Lykaonitských, do Lystry a do Derben, a do toho okolí,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 7, 'A tu kázali evangelium.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 8, 'Muž pak nějaký v Lystře, nemocný na nohy, sedával, byv chromý z života matky své, kterýž nikdy nechodil.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 9, 'Ten poslouchal Pavla mluvícího. Kterýž pohleděv naň, a vida, an věří, že uzdraven bude,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 10, 'Řekl velikým hlasem: Postav se přímě na nohách svých. I zchopil se a chodil.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 11, 'Zástupové pak viděvše, co učinil Pavel, pozdvihli hlasu svého, Lykaonitsky řkouce: Bohové připodobnivše se lidem, sstoupili k nám.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 12, 'I nazvali Barnabáše Jupiterem, a Pavla Merkuriášem; nebo on mluvil slovo.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 13, 'Tedy kněz Jupiterův, kterýž byl před městem jejich, přivedl býky s věnci před bránu, a chtěl s lidem oběti obětovati.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 14, 'To když uslyšeli apoštolé, Barnabáš a Pavel, roztrhše sukně své, vyběhli k zástupům, křičíce,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 15, 'A řkouce: Muži, což to činíte? Však i my lidé jsme, týmž bídám jako i vy poddáni, kteříž vám zvěstujeme, abyste se obrátili od těchto marností k Bohu živému, kterýž učinil nebe i zemi, i moře, i všecko, což v nich jest.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 16, 'Kterýž za předešlých věků všech pohanů nechával, aby chodili po cestách svých,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 17, 'Ačkoli proto nenechal sebe bez osvědčení, dobře čině, dávaje nám s nebe déšť a časy úrodné, naplňuje pokrmem a potěšením srdce naše.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 18, 'A to mluvíce, sotva spokojili zástupy, aby jim neobětovali.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 19, 'A v tom přišli od Antiochie a Ikonie Židé, kteříž navedše zástupy, a ukamenovavše Pavla, vytáhli před město, domnívavše se, že umřel.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 20, 'A když jej obstoupili učedlníci, vstal, a všel do města, a nazejtří odšel s Barnabášem do Derben.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 21, 'A kázavše evangelium městu tomu, a učedlníků mnoho získavše, navrátili se do Lystry a do Ikonie a do Antiochie,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 22, 'Potvrzujíce duší učedlníků, a napomínajíce, aby trvali u víře, a že musíme skrze mnohá ssoužení vjíti do království Božího.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 23, 'A zřídivše jim, podlé daných hlasů, starší po církvech, a modlivše se s postem, poručili je Pánu, v kteréhož uvěřili.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 24, 'A prošedše Pisidii, přišli do Pamfylie,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 25, 'A mluvivše slovo v Pergen, šli do Attalie.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 26, 'A odtud plavili se do Antiochie, odkudž poručeni byli milosti Boží k dílu, kteréž vykonali.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 27, 'A když tam přišli, a shromáždili církev, vypravovali, kteraké věci Bůh skrze ně učinil, a že otevřel pohanům dvéře víry.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 28, 'I byli tu za nemalý čas s učedlníky.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 1, 'Přišedše pak někteří z Židovstva, učili bratří: Že nebudete-li se obřezovati podlé obyčeje Mojžíšova, nebudete moci spaseni býti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 2, 'A když různici a nemalou hádku Pavel a Barnabáš s nimi měl, i zůstali na tom, aby Pavel a Barnabáš a někteří jiní z nich šli k apoštolům a starším do Jeruzaléma o tu otázku.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 3, 'Tedy oni jsouce vyprovozeni od církve, šli skrze Fenicen a Samaří, vypravujíce o obrácení pohanů, i způsobili radost velikou všechněm bratřím.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 4, 'A když se dostali do Jeruzaléma, přijati jsou od církve a od apoštolů a starších. I zvěstovali, cožkoli činil skrze ně Bůh.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 5, 'Ale povstali někteří z sekty farizejské, kteříž byli uvěřili, pravíce, že musejí obřezováni býti, a aby jim bylo přikázáno zachovávati zákon Mojžíšův.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 6, 'Tedy sešli se apoštolé a starší, aby toho povážili.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 7, 'A když mnohé vyhledávání toho bylo, povstav Petr, řekl jim: Muži bratří, vy víte, že od dávních dnů mezi námi Bůh vyvolil, aby skrze ústa má slyšeli pohané slovo evangelium, a uvěřili.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 8, 'A Bůh, zpytatel srdce, svědectví jim vydal, dav jim Ducha svatého, jako i nám.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 9, 'A neučinil rozdílu mezi nimi a námi, věrou očistiv srdce jejich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 10, 'Protož nyní, proč pokoušíte Boha, vzkládajíce na hrdlo učedlníků jho, kteréhož ani otcové naši, ani my nésti jsme nemohli?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 11, 'Ale skrze milost Pána Ježíše Krista věříme, že spaseni budeme, rovně jako i oni.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 12, 'I mlčelo všecko to množství, a poslouchali Barnabáše a Pavla, vypravujících, kteraké divy a zázraky činil Bůh skrze ně mezi pohany.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 13, 'A když oni umlkli, odpověděl Jakub, řka: Muži bratří, slyšte mne.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 14, 'Šimon teď vypravoval, kterak Bůh nejprvé popatřil na pohany, aby přijal lid jménu svému.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 15, 'A s tím se srovnávají i řeči prorocké, jakož psáno jest:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 16, 'Potom se navrátím, a vzdělám zase stánek Davidův, kterýž byl klesl, a zbořeniny jeho zase vzdělám, a vyzdvihnu jej,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 17, 'Tak aby ti ostatkové toho lidu hledali Pána, i všickni pohané, nad kterýmiž jest vzýváno jméno mé, dí Pán, kterýž činí tyto všecky věci.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 18, 'Známáť jsou Bohu od věků všecka díla jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 19, 'Protož já tak soudím, aby nebyli kormouceni ti, kteříž se z pohanů obracejí k Bohu,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 20, 'Ale aby jim napsáno bylo, ať se zdržují od poškvrn modl, a smilstva, a toho, což jest udáveného, a od krve.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 21, 'Nebo Mojžíš od dávních věků má po městech, kdo by jej kázal, poněvadž v školách na každou sobotu čítán bývá.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 22, 'Tehdy vidělo se apoštolům a starším se vší církví, aby vybrané z sebe muže poslali do Antiochie s Pavlem a Barnabášem, totiž Judu, kterýž sloul Barsabáš, a Sílu, muže znamenité mezi bratřími,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 23, 'Napsavše po nich toto: Apoštolé a starší i bratří těm, kteříž jsou v Antiochii a v Sýrii a v Cilicii bratřím, kteříž jsou z pohanů, pozdravení vzkazují.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 24, 'Poněvadž jsme slyšeli, že někteří vyšedše od nás, zkormoutili vás, řečmi zemdlévajíce duše vaše, pravíce, že se musíte obřezovati a zákon zachovávati, jimž jsme toho neporučili:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 25, 'I vidělo se nám shromážděným jednomyslně vybrané muže poslati k vám s těmito nejmilejšími svými, Barnabášem a Pavlem,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 26, 'Lidmi těmi, kteříž vydali duše své pro jméno Pána našeho Ježíše Krista.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 27, 'Protož poslali jsme Judu a Sílu, a tiť i ústně povědí totéž.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 28, 'Vidělo se zajisté Duchu svatému i nám, žádného více na vás břemene nevzkládati, kromě těchto věcí potřebných,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 29, 'Abyste se zdržovali od obětovaného modlám, a od krve, a od udáveného, a od smilstva. Od těch věcí budete-li se ostříhati, dobře budete činiti. Mějte se dobře.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 30, 'Tedy oni propuštěni byvše, přišli do Antiochie, a shromáždivše množství, dodali toho listu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 31, 'Kterýžto čtouce, radovali se z toho potěšení.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 32, 'Judas pak a Sílas, byvše i oni proroci, širokou řečí napomínali bratří a potvrzovali.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 33, 'A pobyvše tu za některý čas, propuštěni jsou od bratří v pokoji k apoštolům.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 34, 'Ale Sílovi se vidělo, aby tu zůstal.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 35, 'Tolikéž Pavel i Barnabáš pobyli v Antiochii, učíce a zvěstujíce i s mnohými jinými slovo Páně.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 36, 'Po několika pak dnech řekl Pavel Barnabášovi: Vracujíce se, navštěvme bratří své po všech městech, v kterýchž jsme kázali slovo Páně, kterak se mají.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 37, 'Tedy Barnabáš radil, aby pojali s sebou i Jana kterýž přijmí měl Marek.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 38, 'Ale Pavlovi se nezdálo pojíti toho s sebou, kterýž byl odšel od nich z Pamfylie, aniž šel s nimi ku práci.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 39, 'I vznikl mezi nimi tuhý odpor, tak že se rozešli různo. Barnabáš pak pojav s sebou Marka, plavil se do Cypru.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 40, 'A Pavel přivzav Sílu, odšel, poručen byv milosti Boží od bratří.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 41, 'I procházel Syrii a Cilicii, potvrzuje církví.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 1, 'Přišel pak do Derben a do Lystry, aj, učedlník jeden tu byl, jménem Timoteus, syn nějaké ženy Židovky věřící, ale otce měl Řeka.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 2, 'Tomu svědectví vydávali bratří ti, kteříž byli v Lystře a v Ikonii.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 3, 'Toho sobě oblíbil Pavel, aby s ním šel. I pojav ho, obřezal jej, pro Židy, kteříž byli v těch místech; nebo věděli všickni, že otec jeho byl Řek.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 4, 'A když chodili po městech, vydávali jim k ostříhání ustanovení zřízená od apoštolů a od starších, kteříž byli v Jeruzalémě.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 5, 'A tak církve utvrzovaly se u víře, a rozmáhaly se v počtu na každý den.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 6, 'A prošedše Frygii i Galatskou krajinu, když jim zabráněno od Ducha svatého, aby nemluvili slova v Azii,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 7, 'Přišedše do Myzie, pokoušeli se jíti do Bitynie. Ale nedal jim Duch.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 8, 'Tedy pominuvše Myzii, šli do Troady.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 9, 'I ukázalo se Pavlovi v noci vidění. Muž nějaký Macedonský stál, prose ho a řka: Přijda do Macedonie, pomoz nám.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 10, 'A jakž to vidění viděl, i hned jsme usilovali o to, abychom šli do Macedonie, tím ujištěni jsouce, že nás povolal Pán, abychom jim kázali evangelium.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 11, 'Protož pustivše se od Troady, přímým během připlavili jsme se do Samotracie, a nazejtří do Neapolis,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 12, 'A odtud do Filippis, kteréž jest první město krajiny Macedonské, obyvateli cizími osazené. I zůstali jsme v tom městě za několik dní.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 13, 'V den pak sobotní vyšli jsme ven za město k řece, kdež býval obyčej modliti se. A usadivše se, mluvili jsme ženám, kteréž se tu byly sešly.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 14, 'Jedna pak žena, jménem Lydia, kteráž šarlaty prodávala v městě Tyatirských, bohabojící, poslouchala. Jejíž srdce otevřel Pán, aby to pilně rozsuzovala, co se od Pavla pravilo.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 15, 'A když pokřtěna byla i dům její, prosila, řkuci: Poněvadž jste mne soudili věrnou Pánu býti, vejdouce, v domě mém pobuďte. I přinutila nás.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 16, 'I stalo se, když jsme šli k modlitbě, že děvečka nějaká, mající ducha věštího, potkala se s námi, kteráž veliký užitek přinášela pánům svým budoucích věcí předpovídáním.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 17, 'Ta šedši za Pavlem a za námi, volala, řkuci: Tito lidé jsou služebníci Boha nejvyššího, kteříž zvěstují nám cestu spasení.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 18, 'A to činívala za mnoho dní. Pavel pak těžce to nesa, a obrátiv se, řekl duchu tomu: Přikazuji tobě ve jménu Ježíše Krista, abys vyšel z ní. I vyšel hned té chvíle.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 19, 'A viděvše páni její, že odešla naděje zisku jejich, chytivše Pavla a Sílu, vedli je na rynk před úřad.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 20, 'A postavivše je před úředníky, řekli: Tito lidé bouří město naše, jsouce Židé,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 21, 'A zvěstují obyčeje, kterýchž nám nesluší přijíti ani zachovávati, poněvadž jsme Římané.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 22, 'I povstala obec proti nim. A úředníci, roztrhše sukně jejich, kázali je metlami mrskati.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 23, 'A množství ran jim davše, vsadili do žaláře, přikázavše strážnému žaláře, aby jich pilně ostříhal.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 24, 'Tedy on takové maje přikázaní, vsadil je do nejhlubšího žaláře, a nohy jejich sevřel kladou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 25, 'O půlnoci pak Pavel a Sílas modléce se, zpívali písničky o Bohu, tak že je slyšeli vězňové.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 26, 'A v tom pojednou země třesení stalo se veliké, až se pohnuli gruntové žaláře, a hned se všecky dvéře otevřely, a všech okovové spadli.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 27, 'A procítiv strážný žaláře, a viděv dvéře žaláře otevřené, vytrhl meč, aby se zabil, domnívaje se, že vězňové utekli.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 28, 'I zkřikl Pavel hlasem velikým, řka: Nečiň sobě nic zlého, však jsme teď všickni.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 29, 'A požádav světla, vběhl k nim, a třesa se, padl u Pavla a Síly.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 30, 'I vyved je ven, řekl: Páni, co já mám činiti, abych spasen byl?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 31, 'A oni řekli: Věř v Pána Ježíše Krista, a budeš spasen ty i dům tvůj.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 32, 'I mluvili jemu slovo Páně, i všechněm, kteříž byli v domě jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 33, 'A pojav je v tu hodinu v noci, umyl jim rány. I pokřtěn jest hned on i všickni domácí jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 34, 'A když je uvedl do domu svého, připravil stůl, a veselil se, že se vším domem svým uvěřil Bohu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 35, 'A když bylo ve dne, poslali úředníci služebníky, řkouce: Vypusť ty lidi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 36, 'I oznámil strážný žaláře slova ta Pavlovi: Že poslali úředníci, abyste byli propuštěni. Protož nyní vyjdouce, jdětež v pokoji.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 37, 'Ale Pavel řekl jim: Zmrskavše nás zjevně a bez vyslyšení, lidi Římany, vsázeli do žaláře, a nyní nás chtějí tajně vyhnati? Nikoli, ale nechať sami přijdou, a vyvedou nás.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 38, 'Tedy pověděli úředníkům služebníci slova ta. I báli se, uslyšavše, že by Římané byli.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 39, 'A přišedše, prosili jich; a vyvedše je, žádali jich, aby šli z města.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 40, 'I vyšedše z žaláře, vešli k Lydii, a uzřevše bratří, potěšili jich, a odešli.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 1, 'A prošedše Amfipolim a Apollonii, přišli do Tessaloniky, kdež byla škola Židovská.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 2, 'Tedy Pavel podlé obyčeje svého všel k nim, a po tři soboty kázal jim z písem,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 3, 'Otvíraje a předkládaje to, že měl Kristus trpěti a z mrtvých vstáti, a že ten jest Kristus Ježíš, kteréhož já zvěstuji vám.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 4, 'I uvěřili někteří z nich, a připojili se Pavlovi a Sílovi, i Řeků nábožných veliké množství, i žen znamenitých nemalo.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 5, 'Ale zažženi byvše závistí Židé nepovolní, a přivzavše k sobě některé lehkomyslné a nešlechetné lidi, a shlukše se, zbouřili město, a útok učinivše na dům Jázonův, hledali jich, aby je vyvedli před lid.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 6, 'A nenalezše jich, táhli Jázona a některé bratří k starším města, křičíce: Tito, kteříž všecken svět bouří, ti sem také přišli.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 7, 'Kteréž přijal Jázon. A ti všickni proti ustanovení císařskému činí, pravíce býti králem jiného, totiž Ježíše.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 8, 'A tak zbouřili obec i starší města, kteříž to slyšeli.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 9, 'Ale přijavše dosti učinění od Jázona a jiných, propustili je.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 10, 'Bratří pak hned v noci vyslali i Pavla i Sílu do Berie. Kteříž přišedše tam, vešli do školy Židovské.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 11, 'A ti byli udatnější nežli Tessalonitští, kteříž přijali slovo Boží se vší chtivostí, na každý den rozvažujíce písma, tak-li by ty věci byly.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 12, 'A tak mnozí z nich uvěřili, i Řecké ženy poctivé i mužů nemalo.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 13, 'A když zvěděli Židé v Tessalonice, že by i v Berii kázáno bylo slovo Boží od Pavla, přišli také tam, bouříce zástupy.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 14, 'Ale hned bratří vyslali Pavla, aby šel jako k moři; Sílas pak a Timoteus pozůstali tu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 15, 'Ti pak, kteříž provodili Pavla, dovedli ho až do Atén. A vzavše poručení k Sílovi a k Timoteovi, aby přišli k němu, což nejspíše mohou, šli zase.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 16, 'A když Pavel čekal jich v Atenách, rozněcoval se v něm duch jeho, vida to město oddané býti modloslužbě.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 17, 'I rozmlouval s Židy a nábožnými v škole, ano i na rynku, po všecky dni, s těmi, kteříž se koli nahodili.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 18, 'Tedy někteří z Epikureů a Stoických mudrců hádali se s ním. A někteří řekli: I co tento žváč chce povědíti? Jiní pak: Zdá se býti cizích bohů zvěstovatel. Nebo jim o Ježíšovi a o z mrtvých vstání vypravoval.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 19, 'I popadše jej, vedli ho do Areopágu, řkouce: Můžeme-li věděti, jaké jest to učení nové, kteréž vypravuješ?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 20, 'Nebo nové jakési věci vkládáš v uši naše, protož chceme věděti, co by to bylo.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 21, '(Atenští zajisté všickni, i ti, kteříž tu byli hosté, k ničemu jinému tak hotovi nebyli, než praviti neb slyšeti něco nového.)');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 22, 'Tedy Pavel, stoje u prostřed Areopágu, řekl: Muži Atenští, vidím vás býti všelijak příliš nábožné lidi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 23, 'Nebo procházeje a spatřuje náboženství vaše, nalezl jsem také oltář, na kterémž napsáno jest: Neznámému Bohu. Protož kteréhož ctíte neznajíce, tohoť já zvěstuji vám.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 24, 'Bůh ten, kterýž stvořil svět i všecko, což jest na něm, ten jsa Pánem nebe i země, nebydlí v chrámích rukou udělaných;');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 25, 'Aniž bývá ctěn lidskýma rukama, jako by něčeho potřeboval, poněvadž on dává všechněm život i dýchání i všecko.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 26, 'A učinil z jedné krve všecko lidské pokolení, aby přebývalo na tváři vší země, vyměřiv jim uložené časy a cíle přebývání jejich,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 27, 'Aby hledali Pána, zda by snad makajíce, mohli nalezti jej, ačkoli není daleko od jednoho každého z nás.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 28, 'Nebo jím živi jsme, a hýbeme se, i trváme, jakož i někteří z vašich poetů pověděli: Že i rodina jeho jsme.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 29, 'Rodina tedy Boží jsouce, nemámeť se domnívati, že by Bůh zlatu neb stříbru neb kamenu, řemeslem aneb důvtipem lidským vyrytému, byl podoben.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 30, 'Nebo časy této neznámosti přehlídaje Bůh, již nyní zvěstuje lidem všechněm všudy, aby pokání činili,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 31, 'Proto že uložil den, v kterémž souditi bude všecken svět v spravedlnosti skrze toho muže, kteréhož k tomu vystavil, slouže k víře všechněm, vzkříšením jeho z mrtvých.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 32, 'Uslyševše pak o vzkříšení z mrtvých, někteří se posmívali, a někteří řekli: Budeme tě slyšeti o tom podruhé.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 33, 'A tak Pavel vyšel z prostředku jejich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 34, 'Někteří pak muži, přídržíce se ho, uvěřili, mezi kterýmiž byl i Dionyzius Areopagitský, i žena, jménem Damaris, a jiní s nimi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 1, 'Potom pak Pavel vyšed z Atén, přišel do Korintu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 2, 'A nalez jednoho Žida, jménem Akvilu, kterýž byl rodem z Pontu, kterýž nedávno byl přišel z Vlach, i Priscillu manželku jeho, (proto že byl rozkázal Klaudius, aby všickni Židé z Říma vyšli,) i přivinul se k nim.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 3, 'A že byl téhož řemesla, bydlil u nich, a dělal; nebo řemeslo jejich bylo stany dělati.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 4, 'I hádal se v škole na každou sobotu, a k získání přivodil i Židy i Řeky.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 5, 'A když přišli z Macedonie Sílas a Timoteus, rozněcoval se v duchu Pavel, osvědčuje Židům, že Ježíš jest Kristus.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 6, 'A když oni odporovali a rouhali se, vyraziv prach z roucha, řekl jim: Krev vaše na hlavu vaši. Já čist jsa, hned půjdu ku pohanům.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 7, 'A jda odtud, všel do domu nějakého Justa jménem, ctitele Božího, kteréhož dům byl u samé školy.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 8, 'Krispus pak, kníže školy, uvěřil Pánu se vším domem svým, a mnozí z Korintských slyšavše, uvěřili a pokřtěni byli.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 9, 'I řekl Pán v noci u vidění Pavlovi: Neboj se, ale mluv a nemlč.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 10, 'Nebo já s tebou jsem, a žádnýť nesáhne na tebe, aťby zle učinil; nebo mnoho mám lidu v tomto městě.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 11, 'I byl tu půl druhého léta, káže jim slovo Boží.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 12, 'Když pak Gallio vládařem byl v Achaii, povstali jednomyslně Židé proti Pavlovi, a přivedli jej před soudnou stolici,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 13, 'Pravíce: Tento navodí lidi, aby proti zákonu ctili Boha.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 14, 'A když Pavel měl již otevříti ústa, řekl Gallio Židům: Ó Židé, jestliže by co nepravého stalo se, neb nešlechetnost nějaká, slušně bych vás vyslyšel.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 15, 'Pakliť jsou jaké hádky o slovích a o jméních a zákonu vašem, vy sami k tomu přihlédněte. Já zajisté toho soudce býti nechci.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 16, 'I odehnal je od soudné stolice.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 17, 'Tedy Řekové všickni, uchopivše Sostena, kníže školy, bili jej před soudnou stolicí, a Gallio na to nic nedbal.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 18, 'Pavel pak, pobyv tam ještě za mnoho dní, i rozžehnav se s bratřími, plavil se do Syrie, a s ním spolu Priscilla a Akvila, oholiv hlavu v Cenchreis; nebo byl učinil slib.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 19, 'I přišed do Efezu, nechal jich tu; sám pak všed do školy, hádal se s Židy.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 20, 'A když ho prosili, aby déle pobyl u nich, nepovolil.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 21, 'Ale požehnav jich, řekl: Musím já jistotně svátek ten, kterýž nastává, v Jeruzalémě slaviti, ale navrátím se k vám zase, bude-li vůle Boží. I bral se z Efezu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 22, 'A přišed do Cesaree, vstoupil, a pozdraviv církve, odtud šel do Antiochie.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 23, 'A pobyv tu za některý čas, odšel a procházel pořád Galatskou krajinu a Frygii, potvrzuje všech učedlníků.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 24, 'Žid pak nějaký, jménem Apollo, rodem z Alexandrie, muž výmluvný, přišel do Efezu, učený v písmě.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 25, 'Ten byl počátečně naučen cestě Páně, a byv vroucího ducha, mluvil a učil pilně těm věcem, kteréž jsou Páně, znaje toliko křest Janův.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 26, 'A ten počal svobodně mluviti v škole. Kteréhož slyševše Priscilla a Akvila, přijali ho k sobě, a dokonaleji vypravovali jemu o cestě Boží.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 27, 'A když chtěl jíti do Achaie, bratří napomenuvše ho, psali učedlníkům, aby jej přijali. Kterýž když tam přišel, mnoho prospěl těm, kteříž uvěřili skrze milost Boží.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 28, 'Nebo náramně přemáhal Židy, zjevně přede všemi toho dokazuje z písem, že Ježíš jest Kristus.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 1, 'I stalo se, když Apollo byl v Korintu, že Pavel prošed vrchní krajiny, přišel do Efezu, a nalezna tu některé učedlníky,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 2, 'Řekl jim: Přijali-li jste Ducha svatého, uvěřivše? A oni řekli jemu: Ba aniž jsme slýchali, jest-li Duch svatý.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 3, 'Tedy řekl jim: Načež tedy pokřtěni jste? A oni řekli: Křtěni jsme křtem Janovým.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 4, 'I řekl Pavel: Janť zajisté křtil křtem pokání, pravě lidu, aby v toho, kterýž měl po něm přijíti, věřili, to jest v Krista Ježíše.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 5, 'Kteříž pak uposlechli, pokřtěni jsou ve jméno Pána Ježíše.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 6, 'A když vzkládal na tyto ruce Pavel, sstoupil Duch svatý na ně, i mluvili jazyky, a prorokovali.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 7, 'A bylo všech spolu okolo dvanácti mužů.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 8, 'Tedy všed do školy, svobodně mluvil za tři měsíce, hádaje se, a uče o království Božím.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 9, 'A když se někteří zatvrdili a nepovolovali, zle mluvíce o cestě Boží přede vším množstvím, odstoupiv od nich, oddělil učedlníky, na každý den kázaní čině v škole nějakého Tyranna.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 10, 'A to se dálo za dvě létě, tak že všickni, kteříž přebývali v Azii, poslouchali slova Pána Ježíše, i Židé i Řekové.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 11, 'A divy veliké činil Bůh skrze ruce Pavlovy,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 12, 'Tak že i na nemocné nosívali od jeho těla šátky a fěrtochy, a odstupovaly od nich nemoci, a duchové nečistí vycházeli z nich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 13, 'Tedy pokusili se někteří z Židů tuláků, kteříž se s zaklínáním obírali, vzývati jméno Pána Ježíše nad těmi, kteříž měli duchy nečisté, říkajíce: Zaklínáme vás skrze Ježíše, kteréhož káže Pavel.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 14, 'A bylo jich sedm synů jednoho Žida, jménem Scevy, předního kněze {biskupa}, kteříž to činili.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 15, 'Tedy odpověděv duch zlý, řekl: Ježíše znám, a o Pavlovi vím, ale vy kdo jste?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 16, 'A obořiv se na ně člověk ten, v kterémž byl duch zlý, opanovav je, zmocnil se jich, tak že nazí a zranění vyběhli z domu toho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 17, 'A to známo učiněno jest všechněm Židům i Řekům bydlícím v Efezu, a spadla bázeň na ně na všecky. I osloveno jest jméno Pána Ježíše.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 18, 'Mnozí pak z věřících přicházeli, vyznávajíce se a zjevujíce skutky své.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 19, 'Mnozí také z těch, kteříž se s marnými uměními obírali, snesše knihy, spálili je přede všemi; a početše cenu jejich, shledali toho padesáte tisíců peněz.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 20, 'Tak mocně rostlo slovo Páně, a zmocňovalo se.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 21, 'A když se to dokonalo, uložil Pavel v duchu, aby projda Macedonii a Achaii, šel do Jeruzaléma, řka: Když pobudu tam, musímť také i na Řím pohleděti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 22, 'I poslav do Macedonie dva z těch, kteříž mu přisluhovali, Timotea a Erasta, sám pozůstal v Azii do času.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 23, 'Tedy stala se v ten čas nemalá bouřka pro cestu Boží.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 24, 'Nebo zlatník jeden, jménem Demetrius, kterýž dělával chrámy stříbrné Diány, nemalý zisk přivodil řemeslníkům.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 25, 'Kteréž svolav, i ty, kteříž byli k těm podobných věcí dělníci, řekl: Muži, víte, že z tohoto řemesla jest živnost naše.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 26, 'A vidíte i slyšíte, že netoliko v Efezu, ale téměř po vší Azii tento Pavel svedl a odvrátil veliké množství, pravě: Že to nejsou bohové, kteříž jsou rukama udělaní.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 27, 'A protož strach jest, netoliko aby se nám v živnosti přítrž nestala, ale také i veliké bohyně Diány chrám aby za nic nebyl jmín, a aby nepřišlo k zkáze důstojenství její, kterouž ctí všecka Azia i světa okršlek.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 28, 'To uslyšavše, a naplněni byvše hněvem, zkřikli, řkouce: Veliká jest Diána Efezských.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 29, 'I naplněno jest všecko město rozbrojem, a valili se všickni spolu na plac, pochopivše Gáia a Aristarcha, Macedonské, tovaryše cesty Pavlovy.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 30, 'Pavlovi pak, když chtěl jíti k lidu, nedopustili učedlníci.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 31, 'Ano i někteří z předních mužů Azianských, kteříž jemu přáli, poslavše k němu, prosili, aby se nedával do toho hluku.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 32, 'A jedni tak, jiní jinak křičeli; nebo byla ta obec zbouřena, a mnozí nevěděli, proč se zběhli.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 33, 'Z zástupu pak Alexandra nějakého táhli, kteréhož i Židé nutili. Alexander pak pokynuv rukou, chtěl zprávu dáti lidu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 34, 'Ale jakž poznali, že jest Žid, stal se jednostejný všech hlas, jako za dvě hodině volajících: Veliká jest Diána Efezských.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 35, 'A když písař pokojil zástup, řekl: Muži Efezští, i kdož z lidí jest, ješto by nevěděl, že město Efezské slouží veliké bohyni Diáně a od Jupitera spadlé podobizně?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 36, 'A poněvadž tomu odpíráno býti nemůže, slušné jest, abyste se upokojili, a nic kvapně nečinili.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 37, 'Přivedli jste zajisté lidi tyto, kteříž nejsou ani svatokrádcové ani rouhači bohyně vaší.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 38, 'Jestliže pak Demetrius, a ti, kteříž jsou s ním, řemeslníci mají s kým jakou při, bývá obecný soud, a jsou konšelé. Nechať jedni druhé viní.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 39, 'Pakli čeho jiného hledáte, i toť můž v pořádném svolání obce skoncováno býti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 40, 'Nebo strach jest, abychom nedošli nesnáze pro tu bouřku dnešní, poněvadž žádné příčiny není, kterouž bychom mohli předložiti, proč jsme se tuto zběhli.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 41, 'A to pověděv, propustil lid.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 1, 'Když pak přestala ta bouřka, povolav Pavel učedlníků, a požehnav jich, vyšel odtud, aby se bral do Macedonie.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 2, 'A když prošel ty krajiny, a napomenutí jim učiniv mnohými řečmi, přišel do země Řecké.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 3, 'A pobyv tam za tři měsíce, (kdež Židé učinili jemu zálohy,) když se měl plaviti do Syrie, umínil navrátiti se skrze Macedonii.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 4, 'I šel s ním Sópater Berienský až do Azie, a z Tessalonicenských Aristarchus a Sekundus a Gáius Derbeus a Timoteus, z Azianských pak Tychikus a Trofimus.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 5, 'Ti šedše napřed, dočkali nás v Troadě.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 6, 'My pak plavili jsme se po velikonoci z Filippis, a přišli jsme k nim do Troady v pěti dnech, a tu jsme pobyli za sedm dní.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 7, 'Tedy první den po sobotě, když se učedlníci sešli k lámání chleba, Pavel mluvil k nim, maje nazejtří jíti pryč, i prodlil řečí až do půlnoci.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 8, 'A bylo mnoho světel na té síni, kdež byli shromážděni.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 9, 'Jeden pak mládenec, jménem Eutychus, sedě na okně, jsa obtížen hlubokým snem, když tak dlouho Pavel kázal, spě, spadl s třetího ponebí dolů a vzat jest mrtvý.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 10, 'I sstoupiv dolů Pavel, zpolehl na něj, a objav jej, řekl: Nermuťtež se, však duše jeho v něm jest.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 11, 'A vstoupiv, lámal chléb a jedl, a kázaní jim učiniv dlouho až do svitání, tak odšel pryč.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 12, 'I přivedli toho mládence živého, a byli velice potěšeni.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 13, 'My pak vstoupivše na lodí, plavili jsme se do Asson, odtud majíce k sobě vzíti Pavla; nebo byl tak poručil, maje sám jíti po zemi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 14, 'A když se k nám připojil v Asson, vzavše jej, přijeli jsme do Mitylénu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 15, 'A odtud plavíce se, druhý den byli jsme proti Chium, a třetího dne připlavili jsme se k Sámu, a pobyvše v Trogyllí, nazejtří přišli jsme do Milétu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 16, 'Nebo Pavel byl umínil pominouti Efez, aby se nemeškal v Azii; nebo pospíchal, by možné jemu bylo, aby byl o letnicích v Jeruzalémě.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 17, 'Tedy z Milétu poslav do Efezu, povolal k sobě starších církve.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 18, 'Kteříž když přišli k němu, řekl jim: Vy víte od prvního dne, v kterýž přišel jsem do Azie, kterak jsem po všecken ten čas s vámi byl,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 19, 'Slouže Pánu se vší pokorou i s mnohými slzami a pokušeními, kteráž na mne přicházela z úkladů Židovských,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 20, 'Kterak jsem ničeho nepominul, což by užitečného bylo, abych vám neoznámil, a neučil vás vůbec zjevně i po domích,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 21, 'Svědectví vydávaje i Židům i Řekům o pokání k Bohu, a o víře v Pána našeho Ježíše Krista.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 22, 'A aj, nyní já sevřín jsa duchem, beru se do Jeruzaléma, nevěda, co mi se v něm má státi,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 23, 'Než že Duch svatý po městech osvědčuje mi, pravě, že vězení a ssoužení mne očekávají.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 24, 'Však já nic na to nedbám, aniž jest mi tak drahá duše má, jen abych běh svůj s radostí vykonal, a přisluhování, kteréž jsem přijal od Pána Ježíše, k osvědčování evangelium milosti Boží.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 25, 'A aj, já nyní vím, že již více neuzříte tváři mé vy všickni, mezi kterýmiž jsem chodil, káže o království Božím.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 26, 'Protož osvědčujiť vám v dnešní den, žeť jsem čist od krve všech.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 27, 'Nebo jsem neobmeškal zvěstovati vám všeliké rady Boží.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 28, 'Buďtež tedy sebe pilni i všeho stáda, v němž Duch svatý ustanovil vás biskupy, abyste pásli církev Boží, kteréž sobě dobyl svou vlastní krví.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 29, 'Nebo já to vím, že po mém odjití vejdou mezi vás vlci hltaví, kteříž nebudou odpouštěti stádu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 30, 'A z vás samých povstanou muži, kteříž budou mluviti převrácené věci, aby obrátili učedlníky po sobě.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 31, 'Protož bděte, v paměti majíce, že jsem po tři léta nepřestával dnem i nocí s pláčem napomínati jednoho každého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 32, 'A již nyní, bratří, poroučím vás Bohu a slovu milosti jeho, kterýž mocen jest vzdělati, a dáti vám dědictví mezi všemi posvěcenými.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 33, 'Stříbra neb zlata neb roucha nežádal jsem od žádného.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 34, 'Nýbrž sami víte, že toho, čehož mi kdy potřebí bylo, i těm, kteříž jsou se mnou, dobývaly ruce tyto.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 35, 'Vše ukázal jsem vám, že tak pracujíce, musíme snášeti mdlé, a pamatovati na slova Pána Ježíše; nebť on řekl: Blahoslaveněji jest dáti nežli bráti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 36, 'A to pověděv, klekna na kolena svá, modlil se s nimi se všemi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 37, 'I stal se pláč veliký ode všech, a padajíce na hrdlo Pavlovo, líbali jej,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 38, 'Rmoutíce se nejvíce nad tím slovem, kteréž řekl, že by již více neměli tváři jeho viděti. I provodili jej až k lodí.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 1, 'Když jsme se pak plavili, rozloučivše se s nimi, přímým během přijeli jsme do Koum, a druhý den do Ródu, a odtud do Patary.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 2, 'I nalezše tu lodí, kteráž měla plouti do Fenicen, a vstoupivše na ni, plavili jsme se.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 3, 'A když se nám počal ukazovati Cyprus, nechavše ho na levé straně, plavili jsme se do Syrie, a připlavili jsme se do Týru; nebo tu měli složiti náklad z lodí.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 4, 'A nalezše učedlníky, pobyli jsme tam za sedm dní, kteříž pravili Pavlovi skrze Ducha, aby nechodil do Jeruzaléma.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 5, 'A když jsme vyplnili ty dni, vyšedše, brali jsme se pryč, a sprovodili nás všickni s ženami i s dětmi až za město. A poklekše na kolena na břehu, pomodlili jsme se.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 6, 'A když jsme se vespolek rozžehnali, vstoupili jsme na lodí, a oni se vrátili domů.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 7, 'My pak přeplavivše se od Týru, dostali jsme se až do Ptolemaidy, a pozdravivše bratří, pobyli jsme u nich jeden den.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 8, 'A nazejtří vyšedše Pavel a my, kteříž jsme s ním byli, přišli jsme do Cesaree, a všedše do domu Filipa evangelisty (kterýž byl jeden z oněch sedmi,) pobyli jsme u něho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 9, 'A ten měl čtyři dcery panny, prorokyně.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 10, 'A když jsme tu pobyli za drahně dní, přišel prorok nějaký z Judstva, jménem Agabus.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 11, 'Ten když k nám přišel, vzal pás Pavlův, a svázav sobě ruce i nohy, řekl: Totoť praví Duch svatý: Muže toho, jehož jest pás tento, tak Židé sváží v Jeruzalémě, a vydadí v ruce pohanům.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 12, 'A jakž jsme to uslyšeli, prosili jsme i my i ti, kteříž byli v tom místě, aby nechodil do Jeruzaléma.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 13, 'Tedy odpověděl Pavel: I co činíte, plačíce a trápíce srdce mé? Však já netoliko svázán býti, ale i umříti hotov jsem v Jeruzalémě pro jméno Pána Ježíše.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 14, 'A když nechtěl povoliti, dali jsme tomu pokoj, řkouce: Staň se vůle Páně.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 15, 'Po těch pak dnech připravivše se, brali jsme se do Jeruzaléma.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 16, 'A šli s námi i učedlníci z Cesaree, vedouce s sebou nějakého Mnázona z Cypru, starého učedlníka, u něhož bychom hospodu měli.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 17, 'A když jsme přišli do Jeruzaléma, vděčně nás přijali bratří.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 18, 'Druhého pak dne všel Pavel s námi k Jakubovi, a tu se byli všickni starší sešli.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 19, 'Jichž pozdraviv, vypravoval všecko, což Bůh skrze službu jeho činil mezi pohany.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 20, 'A oni slyševše, velebili Pána, a řekli jemu: Vidíš, bratře, kterak jest mnoho tisíců Židů věřících, a ti všickni jsou horliví milovníci zákona.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 21, 'Ale o toběť mají zprávu, že bys ty vedl od zákona Mojžíšova všecky ty Židy, kteříž jsou mezi pohany, pravě, že nemají obřezovati synů, ani zachovávati ustanovení.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 22, 'Což tedy? Musíť zajisté shromážděno býti množství, neboť uslyší o tobě, že jsi přišel.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 23, 'Učiniž tedy toto, cožť povíme: Máme tu čtyři muže, kteříž mají slib na sobě.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 24, 'Ty přijma k sobě, posvěť se s nimi, a náklad učiň s nimi, aby oholili hlavy. I zvědí všickni, že to, což slyšeli o tobě, nic není, ale že i sám ty chodíš, ostříhaje zákona.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 25, 'Z strany pak těch, kteříž z pohanů uvěřili, my jsme psali, usoudivše, aby tohoto ničeho nešetřili, toliko aby se varovali modlám obětovaného, a krve, a udáveného, a smilstva.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 26, 'Tedy Pavel, přijav k sobě ty muže, na druhý den posvětiv se s nimi, všel do chrámu, a vypravoval o vyplnění dní toho posvěcení, až i obětována jest obět za jednoho každého z nich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 27, 'A když se vyplniti mělo dní sedm, Židé někteří z Azie, uzřevše jej v chrámě, zbouřili všecken lid, a vztáhli naň ruce,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 28, 'Křičíce: Muži Izraelští, pomozte. Totoť jest ten člověk, kterýž proti lidu i zákonu i místu tomuto všecky všudy učí, a k tomu i pohany uvedl do chrámu, a poškvrnil svatého tohoto místa.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 29, '(Nebo byli viděli prvé Trofima Efezského s ním v městě, kteréhož domnívali se, že by Pavel do chrámu uvedl.)');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 30, 'Takž se zbouřilo všecko město, a zběhli se lidé, a uchopivše Pavla, táhli jej ven z chrámu. A hned zavříny jsou dvéře.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 31, 'A když jej chtěli zamordovati, povědíno hejtmanu vojska, že se bouří všecken Jeruzalém.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 32, 'Kterýž hned pojav s sebou žoldnéře a setníky, přiběhl na ně. A oni uzřevše hejtmana a žoldnéře, přestali bíti Pavla.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 33, 'Tedy přistoupiv hejtman, dosáhl ho, a rozkázal svázati dvěma řetězy, a ptal se, kdo jest, a co učinil.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 34, 'V zástupu pak jedni tak, jiní jinak křičeli. A nemoha nic jistého zvěděti pro hluk, rozkázal jej vésti do vojska.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 35, 'A když přišel k stupňům, nahodilo se, že nesen byl od žoldnéřů pro násilé lidu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 36, 'Nebo šlo za ním množství lidu, křičíce: Zahlaď jej.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 37, 'A když měl již uveden býti do vojska Pavel, řekl hejtmanu: Mohu-li co promluviti k tobě? Kterýž řekl: Umíš Řecky?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 38, 'Nejsi-liž ty ten Egyptský, kterýž jsi před těmito dny byl bouřku učinil, a vyvedls na poušť ty čtyři tisíce mužů těch lotrů?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 39, 'I řekl Pavel: Já jsem člověk Žid Tarsenský, neposledního města v Cilicii obyvatel; protož prosím tebe, dopusť mi promluviti k lidu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 40, 'A když mu on dopustil, Pavel stoje na stupních, pokynul rukou na lid. A když se veliké mlčení stalo, mluvil k nim Židovsky, řka:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 1, 'Muži bratří a otcové, poslechněte této mé před vámi omluvy.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 2, '(Uslyševše pak, že by k nim mluvil Židovským jazykem, tím raději mlčeli.) I řekl:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 3, 'Já zajisté jsem muž Žid, narozený v Tarsu Cilickém, ale vychován jsem v tomto městě u noh Gamalielových, vyučený s pilností zákonu otcovskému, horlivý jsa milovník Boha, jakož i vy všickni podnes jste.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 4, 'Kterýž jsem se této cestě protivil až k smrti, svazuje a dávaje do žaláře i muže i ženy,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 5, 'Jakož i nejvyšší kněz {biskup} svědek mi toho jest, i všickni starší. Od nichž i listy k bratřím vzav, šel jsem do Damašku, abych i ty, kteříž tam byli, svázané přivedl do Jeruzaléma, aby byli trápeni.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 6, 'I stalo se, když jsem se bral cestou, a přibližoval k Damašku, okolo poledne, že pojednou s nebe obklíčilo mne světlo veliké.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 7, 'I padl jsem na zem, a slyšel jsem hlas, an mi dí: Sauli, Sauli, proč mi se protivíš?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 8, 'A já odpověděl jsem: Kdo jsi, Pane? I řekl ke mně: Jáť jsem Ježíš Nazaretský, kterémuž ty se protivíš.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 9, 'Ti pak, kteříž se mnou byli, světlo zajisté viděli, a přestrašeni jsou, ale hlasu toho, kterýž se mnou mluvil, neslyšeli.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 10, 'I řekl jsem: Pane, což mám činiti? A Pán řekl ke mně: Vstana, jdi do Damašku, a tu tobě bude povědíno všecko, což jest uloženo, abys ty činil.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 11, 'A že jsem byl nevidomý od blesku světla toho, za ruce jsa veden od těch, kteříž se mnou byli, přišel jsem do Damašku.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 12, 'Ananiáš pak nějaký, muž pobožný podlé zákona, svědectví maje ode všech spolusousedů Židů,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 13, 'Přišel ke mně, a stoje, řekl mi: Sauli, bratře, prohlédni. A já hned té chvíle pohleděl jsem na něj.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 14, 'On pak řekl: Bůh otců našich vyvolil tě, abys poznal vůli jeho, a uzřel spravedlivého tohoto, a slyšel hlas z úst jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 15, 'Nebo svědkem jemu budeš u všech lidí toho, což jsi viděl a slyšel.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 16, 'A protož nyní co prodléváš? Vstana, pokřti se, a obmej hříchy své, vzývaje jméno Páně.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 17, 'Stalo se pak, když jsem se navrátil do Jeruzaléma, a modlil jsem se v chrámě, že jsem byl u vytržení mysli.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 18, 'I viděl jsem jej, an dí ke mně: Pospěš a vyjdi rychle z Jeruzaléma, neboť nepřijmou svědectví tvého o mně.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 19, 'A já řekl jsem: Pane, oniť vědí, že jsem já do žaláře dával, a bil jsem v školách ty, kteříž věřili v tebe.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 20, 'A když vylévali krev Štěpána, svědka tvého, já také jsem tu stál, a přivolil jsem k usmrcení jeho, a ostříhal jsem roucha těch, kteříž jej mordovali.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 21, 'Tedy řekl mi: Jdi, neboť já ku pohanům daleko pošli tebe.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 22, 'I poslouchali ho až do toho slova. A tu pozdvihli hlasu svého, řkouce: Zahlaď z země takového, neboť nesluší jemu živu býti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 23, 'A když oni křičeli, a metali roucha, a prachem házeli v povětří,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 24, 'Rozkázal jej hejtman do vojska uvesti, a kázal biči mrskati, aby zvěděl, pro kterou příčinu na něj tak křičí.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 25, 'A když jej svázali řemením, řekl Pavel setníkovi, kterýž tu stál: Sluší-liž vám člověka Římana a neodsouzeného mrskati?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 26, 'To uslyšev setník, přistoupě k hejtmanu, pověděl jemu, řka: Viz, co chceš činiti; nebo člověk tento jest Říman.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 27, 'A přistoupiv hejtman, řekl mu: Pověz mi, jsi-li ty Říman? A on řekl: A já jsem.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 28, 'I odpověděl hejtman: Já jsem za veliké peníze toho měšťanství dosáhl. Pavel pak řekl: Ale já jsem se i narodil.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 29, 'Tedy i hned odstoupili od něho ti, kteříž jej měli trápiti. Ano i hejtman bál se, zvěděv, že jest Říman, a proto že jej byl kázal svázati.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 30, 'Nazejtří pak, chtěje zvěděti jistotu, z čeho by jej vinili Židé, propustil jej z pout, a rozkázal, aby se sešli přední kněží {biskupové} i všecka rada jejich. I vyvedl Pavla, a postavil před nimi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 1, 'Tedy Pavel, pohleděv pilně na to shromáždění, řekl: Muži bratří, já všelijak s dobrým svědomím obcoval jsem před Bohem až do dnešního dne.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 2, 'Tedy nejvyšší kněz {biskup} Ananiáš kázal těm, kteříž u něho stáli, aby jej bili v ústa.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 3, 'Pavel pak řekl jemu: Budeť tebe bíti Bůh, stěno zbílená. A ty sedíš, soudě mne vedlé zákona, a proti zákonu velíš mne bíti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 4, 'Ti pak, kteříž tu stáli, řekli: Nejvyššímu knězi {biskupovi} Božímu zlořečíš?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 5, 'I řekl Pavel: Nevědělť jsem, bratří, byť nejvyšším knězem {biskupem} byl; psánoť jest zajisté: Knížeti lidu svého nebudeš zlořečiti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 6, 'A věda Pavel, že tu byla jedna strana saduceů a druhá farizeů, zvolal v radě: Muži bratří, já jsem farizeus, syn farizeův; pro naději a z mrtvých vstání já tuto k soudu stojím.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 7, 'A když on to promluvil, stal se rozbroj mezi farizei a saducei, a rozdvojilo se množství.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 8, 'Nebo saduceové praví, že není vzkříšení, ani anděla, ani ducha, ale farizeové obé to vyznávají.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 9, 'I stal se křik veliký. A povstavše učitelé strany farizejské, zastávali ho, řkouce: Nic jsme zlého nenalezli na tomto člověku; protož buď že mluvil jemu duch neb anděl, nebojujme s Bohem.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 10, 'A když veliký rozbroj vznikl, obávaje se hejtman, aby Pavel nebyl od nich roztrhán, rozkázal žoldnéřům sjíti dolů a vychvátiti ho z prostředku jejich, a vésti do vojska.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 11, 'V druhou pak noc postaviv se při něm Pán, řekl: Budiž stálý, Pavle; nebo jakož jsi svědčil o mně v Jeruzalémě, tak musíš svědčiti i v Římě.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 12, 'A když byl den, sšedše se někteří z Židů, zapřisáhli se s klatbou, řkouce, že nebudou jísti ani píti, až zabijí Pavla.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 13, 'A bylo jich více než čtyřidceti, kteříž se byli tak spikli.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 14, 'Kteřížto přistoupivše k předním kněžím {biskupům} a k starším, řekli: Prokletím prokleli jsme se, že neokusíme ničeho, dokudž nezabijeme Pavla.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 15, 'Protož vy nyní dejte věděti hejtmanu, s svolením vší rady, aby jej zítra k vám přivedl, jako byste něco jistšího chtěli zvěděti o jeho věcech; my pak, prvé nežli se přiblíží, hotovi jsme jej zabiti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 16, 'Slyšev pak syn sestry Pavlovy o těch úkladech, odšel, a všed do vojska, pověděl Pavlovi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 17, 'Tedy zavolav Pavel k sobě jednoho z setníků, řekl: Doveď mládence tohoto k hejtmanu; nebo má jemu něco povědíti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 18, 'A on pojav jej, vedl k hejtmanu, a řekl: Vězeň Pavel zavolav mne, prosil, abych tohoto mládence přivedl k tobě, že by měl něco mluvit s tebou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 19, 'I vzav jej hejtman za ruku, a odstoupiv s ním soukromí, otázal se: Co jest to, ješto mi máš oznámiti?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 20, 'Tedy on řekl: Že uložili Židé prositi tebe, abys zítra do rady uvedl Pavla, jako by něco jistšího chtěli vyzvěděti o něm.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 21, 'Ale ty nepovoluj jim; neboť úklady činí jemu více než čtyřidceti mužů z nich, kteříž se zapřisáhli s klatbou, že nebudou ani jísti, ani píti, až jej zabijí. A jižť jsou hotovi, čekajíce na odpověd od tebe.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 22, 'Tedy hejtman propustil toho mládence, přikázav: Abys žádnému nepravil, žes mi to oznámil.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 23, 'A zavolav dvou setníků, řekl: Připravte žoldnéřů dvě stě, aby šli až do Cesaree, a jezdců sedmdesáte, a drabantů dvě stě k třetí hodině na noc.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 24, 'I hovada přiveďte, aby vsadíce na ně Pavla, ve zdraví jej dovedli k Felixovi vládaři;');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 25, 'Napsav jemu i list v tento rozum:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 26, 'Klaudius Lyziáš výbornému vládaři Felixovi vzkazuje pozdravení.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 27, 'Muže tohoto javše Židé, hned zamordovati měli. Kteréhož, přispěv s houfem žoldnéřů, vydřel jsem, zvěděv, že jest Říman.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 28, 'A chtěje zvěděti, z čeho by jej vinili, uvedl jsem ho do rady jejich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 29, 'I shledal jsem, že na něj žalují o nějaké pohádky zákona jejich, a že nemá žádné viny, pro kterouž by byl hoden smrti neb vězení.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 30, 'A když mi povědíno o úkladech, kteréž o něm skládali Židé, i hned jsem jej poslal k tobě, přikázav také i těm žalobníkům, aby, což mají proti němu, oznámili před tebou. Měj se dobře.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 31, 'Tedy žoldnéři, jakž jim poručeno bylo, pojavše Pavla, přivedli jej v noci do Antipatridy.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 32, 'A nazejtří, nechavše jízdných, aby s ním jeli, vrátili se do vojska.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 33, 'Oni pak přijevše do Cesaree, a dodavše listu vládaři, Pavla také postavili před ním.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 34, 'A přečta list vládař, otázal se ho, z které by krajiny byl. A zvěděv, že jest z Cilicie,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 35, 'Řekl: Budu tě slyšeti, když tvoji žalobníci také přijdou. I rozkázal ho ostříhati v domě Heródesově.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 1, 'Po pěti pak dnech sstoupil nejvyšší kněz {biskup} Ananiáš s staršími a s nějakým Tertullem řečníkem. Kteříž postavili se před vládařem proti Pavlovi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 2, 'A když povolán byl, počal žalovati Tertullus, řka:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 3, 'Kterak mnohý pokoj způsoben jest nám skrze tebe, a mnohé věci v tomto národu výborně se dějí skrze tvou opatrnost, to my i všelijak i všudy se vším děkováním vyznáváme, výborný Felix.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 4, 'Ale abych tě déle nezaměstknával, prosím, vyslyšiž nás maličko podlé obyčeje přívětivosti své.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 5, 'Nalezli jsme zajisté muže tohoto nešlechetného, a vzbuzujícího různice mezi všemi Židy po všem světě, a vůdci té sekty Nazaretské.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 6, 'Kterýž také i o to se pokoušel, aby chrámu poškvrnil; a kteréhož javše, vedlé zákona svého chtěli jsme souditi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 7, 'Ale přišed hejtman Lyziáš s mocí velikou, vzal ho z rukou našich,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 8, 'Rozkázav, aby žalobníci jeho šli k tobě. Od něhož ty sám budeš moci, vyptaje se, zvěděti o tom o všem, z čeho my jej viníme.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 9, 'A k tomu se přimluvili i Židé, pravíce, že to tak jest.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 10, 'Tedy Pavel odpověděl, když mu návěští dal vládař, aby mluvil: Od mnohých let věda tebe býti soudcím národu tomuto představeným, s lepší myslí k tomu, což se mne dotýče, odpovídati budu,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 11, 'Poněvadž ty můžeš to věděti, že není tomu dní více než dvanácte, jakž jsem přišel do Jeruzaléma, abych se modlil.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 12, 'A aniž mne nalezli v chrámě s někým se hádajícího, aneb činícího roty v zástupu, ani v školách, ani v městě,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 13, 'Aniž toho prokázati mohou, což na mne nyní žalují.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 14, 'Ale totoť před tebou vyznávám, že podlé té cesty, kterouž nazývají kacířstvím, tak sloužím Bohu otců, věře všemu, cožkoli psáno jest v zákoně a v prorocích,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 15, 'Maje naději v Bohu, že bude, jehož i oni čekají, vzkříšení z mrtvých, i spravedlivých i nespravedlivých.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 16, 'Sám pak o to pracuji, abych měl svědomí bez úrazu před Bohem i před lidmi vždycky.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 17, 'Po mnohých pak letech přišel jsem, almužny nesa národu svému a oběti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 18, 'Při čemž mne nalezli v chrámě očištěného, ne s zástupem, ani s bouřkou, někteří Židé z Azie,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 19, 'Kteříž by měli tuto také před tebou státi a žalovati, měli-li by co proti mně.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 20, 'Aneb nechať tito sami povědí, nalezli-li na mně jakou nepravost, když jsem stál v radě.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 21, 'Leč to jedno promluvení, že jsem zavolal, stoje mezi nimi: Pro vzkříšení z mrtvých já k soudu potažen jsem dnes od vás.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 22, 'A vyslyšav to Felix, odložil jim, řka: Až bych o té cestě něco místnějšího vyzvěděl, když hejtman Lyziáš sem přijede, posoudím té pře vaší.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 23, 'I poručil setníkovi, aby Pavla ostříhal, a polehčil mu, a nebránil žádnému z přátel jeho posluhovati jemu aneb navštěvovati ho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 24, 'Po několika pak dnech přišed Felix s Druzillou, manželkou svou, kteráž byla Židovka, zavolal Pavla, a slyšel od něho o víře v Krista.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 25, 'A když on vypravoval o spravedlnosti a o zdrželivosti a o budoucím soudu, ulekl se Felix, a odpověděl: Nyní odejdi, a v čas příhodný povolám tě.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 26, 'Přitom pak nadál se, že jemu Pavel dá peníze, aby jej propustil, pročež i tím častěji, povolávaje ho, mluvíval s ním.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 27, 'Po dvou pak letech měl po sobě náměstka Felix Porcia Festa, a chtěje se zalíbiti Židům Felix, nechal Pavla v vězení.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 1, 'Tedy Festus vládařství ujav, po třech dnech přijel z Cesaree do Jeruzaléma.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 2, 'I postavili se nejvyšší kněz {biskup} a přednější z Židů proti Pavlovi, a prosili ho,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 3, 'Žádajíce té milosti proti němu, aby jej kázal přivesti do Jeruzaléma, zálohy učinivše jemu, aby ho zabili na cestě.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 4, 'Ale Festus odpověděl, že má Pavel ostříhán býti v Cesaree, a on sám že tudíž přijede.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 5, 'Protož (řekl,) kteříž z vás mohou, nechť tam také se vypraví spolu se mnou, a jest-li jaká vina na tom muži, nechať naň žalují.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 6, 'A pobyv mezi nimi nic více než deset dní, jel do Cesaree. A druhého dne posadiv se na soudné stolici, kázal Pavla přivesti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 7, 'Kterýž když byl přiveden, obstoupili ti, kteříž byli přišli z Jeruzaléma, Židé, mnohé a těžké žaloby proti Pavlovi přednášejíce, kterýchž nemohli dovesti,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 8, 'Když on při všem mírnou zprávu dával, že ani proti zákonu Židovskému, ani proti chrámu, ani proti císaři nic neprovinil.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 9, 'Ale Festus, chtěje se Židům zalíbiti, odpověděv, řekl Pavlovi: Chceš-li jíti do Jeruzaléma, a tam o to souzen býti přede mnou?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 10, 'I řekl Pavel: Před stolicí císařovou chci státi a tam souzen býti. Židům jsem nic neublížil, jakož i ty dobře to víš.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 11, 'Nebo jestližeť jsem křiv, aneb něco smrti hodného jsem spáchal, neodpírámť umříti; a pakliť nic toho není, z čehož mne oni viní, žádnýť mne jim nemůže dáti. K císaři se odvolávám.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 12, 'Tehdy Festus promluviv s radou, odpověděl: K císařis se odvolal? K císaři půjdeš.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 13, 'A po několika dnech král Agrippa a Bernice přijeli do Cesaree, aby pozdravili Festa.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 14, 'A když tu za mnoho dní byli, oznámil Festus králi o Pavlově při, řka: Muž nějaký zanechán jest od Felixa v vězení,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 15, 'O kterémž, když jsem byl v Jeruzalémě, oznámili přední kněží {biskupové} a starší Židovští, žádajíce na něj ortele.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 16, 'Kterýmž jsem odpověděl, že není obyčej Římanům vydati člověka na smrt, prvé než by ten, na kohož se žaloba děje, přítomné měl žalobníky, a volnost k odpovídání na to, z čehož by byl obviňován.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 17, 'A protož když se byli sem sešli, hned beze všeho meškání, druhý den posadiv se na soudné stolici, rozkázal jsem přivesti toho muže.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 18, 'Jehož žalobníci tu stojíce, z ničeho takového nevinili ho, o čemž jsem já se domníval.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 19, 'Ale o nějaké otázky při tom svém náboženství měli s ním nesnáz, a o jakémsi Ježíšovi mrtvém, o kterémž jistil Pavel, že jest živ.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 20, 'Já pak maje tu při v pochybnosti, řekl jsem, chtěl-li by jíti do Jeruzaléma, a tam o ty věci souzen býti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 21, 'A když se on odvolal, aby byl chován k soudu Augustovu, kázal jsem ho hlídati, až bych jej poslal k císaři.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 22, 'Tedy Agrippa řekl Festovi: Chtělť bych i já rád člověka toho slyšeti. A on řekl: Zítra ho uslyšíš.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 23, 'Nazejtří pak, když přišel Agrippa a Bernice s velikou slávou, a vešli na síň s hejtmany a s lidmi nejznamenitějšími města toho, k rozkázaní Festovu přiveden jest Pavel.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 24, 'I řekl Festus: Králi Agrippo a všickni muži, kteříž jste tuto s námi, vidíte tohoto, za nějž všecko množství Židů prosili mne, i v Jeruzalémě i zde, křičíce, že takový nemá více živ býti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 25, 'Já pak shledav to, že nic hodného smrti neučinil, však když se sám k Augustovi odvolal, umínil jsem jej poslati.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 26, 'O němž, co bych jistého napsal pánu, nevím. Protož jsem jej teď přivedl před vás, a zvláště před tebe, králi Agrippo, abych vyptaje se, věděl co psáti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 27, 'Nebo zdá mi se to neslušné býti poslati vězně, a pře jeho neoznámiti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 1, 'Potom Agrippa řekl Pavlovi: Dopouštíť se, abys sám za sebe promluvil. Tedy Pavel vztáh ruku, tuto zprávu dával:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 2, 'Na všecky ty věci, z kterýchž mne viní Židé, králi Agrippo, za šťastného se počítám, že dnes před tebou odpovídati mám,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 3, 'A zvláště proto, poněvadž jsi ty povědom všech těch, kteříž u Židů jsou, obyčejů a otázek. Protož prosím tebe, vyslyšiž mne trpělivě.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 4, 'O životu mém od mladosti, jaký byl od počátku v národu mém v Jeruzalémě, vědí všickni Židé,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 5, 'Měvše mne prvé zdávna v dobré známosti, (kdyby chtěli svědectví vydati,) kterak vedlé nejjistší sekty v našem náboženství byl jsem živ farizeus.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 6, 'A nyní pro naději toho zaslíbení, kteréž se stalo otcům od Boha, stojím, soudu jsa poddán,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 7, 'K kterémuž dvanáctero pokolení naše, sloužíce Bohu ustavičně dnem i nocí, naději má, že přijde. Pro tuť naději žalují na mne Židé, ó králi Agrippo.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 8, 'A tak-liž se to od vás za nepodobné k víře soudí, že Bůh křísí mrtvé?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 9, 'Ačť mně se zdálo, že by náležité bylo, proti jménu Ježíše Nazaretského mnoho odporného činiti,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 10, 'Jakož jsem i činil v Jeruzalémě, a mnohé z svatých já jsem do žalářů dával, vzav moc od předních kněží {biskupů}. A když měli mordování býti, já jsem pomáhal ortele vynášeti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 11, 'A po všech školách často je trápě, přinucoval jsem rouhati se; a náramně rozlítiv se na ně, sháněl jsem se po nich i v jiných městech.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 12, 'A v tom, když jsem šel do Damašku, s mocí a s poručením předních kněží {biskupů},');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 13, 'O poledni na cestě, ó králi, uzřel jsem, ano světlo s nebe, jasnější nad blesk slunečný, obklíčilo mne, i ty, kteříž se mnou šli.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 14, 'A když jsme my všickni na zem padli, slyšel jsem hlas mluvící k sobě, a řkoucí Židovským jazykem: Sauli, Sauli, proč mi se protivíš? Tvrdoť jest tobě proti ostnům se zpěčovati.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 15, 'A já jsem řekl: I kdo jsi, Pane? A on řekl: Já jsem Ježíš, kterémuž ty se protivíš.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 16, 'Ale vstaň a stůj na nohách svých; nebo protoť jsem se tobě ukázal, abych tebe učinil služebníkem a svědkem i těch věcí, kteréž jsi viděl, i těch, v kterýchž ukazovati se budu tobě,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 17, 'Vysvobozuje tebe z lidu tohoto, i z pohanů, k nimž tě nyní posílám,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 18, 'Otvírati oči jejich, aby se obrátili od temností k světlu, a z moci ďábelské k Bohu, aby tak hříchů odpuštění a díl s posvěcenými vzali skrze víru, kteráž jest ve mne.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 19, 'A protož, ó králi Agrippo, nebyl jsem nevěřící tomu nebeskému vidění.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 20, 'Ale nejprv těm, kteříž jsou v Damašku a v Jeruzalémě, i po vší krajině Judské i pohanům zvěstoval jsem, aby pokání činili, a obrátili se k Bohu, skutky hodné činíce pokání.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 21, 'A pro tu příčinu Židé javše mne v chrámě, pokoušeli se rukama zamordovati.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 22, 'Ale s pomocí Boží ještě až do dnešního dne stojím, vydávaje svědectví i malému i velikému, nic jiného nevypravuje, než to, což proroci a Mojžíš zvěstovali, že se mělo státi:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 23, 'Že měl Kristus trpěti, a z mrtvých vstana první, zvěstovati světlo lidu tomuto i pohanům.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 24, 'To když od sebe promluvil Pavel, Festus hlasem velikým řekl: Blázníš, Pavle. Mnohé tvé umění k bláznovství tebe přivodí.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 25, 'On pak řekl: Neblázním, výborný Feste, ale slova pravdy a středmosti mluvím.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 26, 'Víť zajisté o těch věcech král, před kterýmž svobodně mluvím; nebo mám za to, žeť ho nic z těchto věcí tajno není, poněvadž se toto nedálo pokoutně.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 27, 'Věříš-li, králi Agrippo, prorokům? Vím, že věříš.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 28, 'Tedy Agrippa řekl Pavlovi: Téměř bys mne k tomu naklonil, abych byl křesťanem.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 29, 'A Pavel řekl: Žádalť bych od Boha, abyste i poněkud i z cela, netoliko ty, ale všickni, kteříž slyší mne dnes, byli takoví, jakýž já jsem, kromě okovů těchto.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 30, 'A když to Pavel promluvil, vstal král i vládař a Bernice, i ti, kteříž s nimi seděli.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 31, 'A odšedše na stranu, mluvili spolu, řkouce: Nic hodného smrti neb vězení nečiní člověk tento.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 32, 'Agrippa pak Festovi řekl: Mohl propuštěn býti člověk tento, kdyby se byl neodvolal k císaři.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 1, 'A když bylo již usouzeno, abychom my se plavili do Vlach, poručen jest i Pavel i někteří jiní vězňové setníku, jménem Juliovi, kterýž byl nad houfem Augustovým.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 2, 'Tedy všedše na lodí Adramyttenskou, abychom se plavili podlé krajin Azie, pustili jsme se. A byl s námi Aristarchus Macedonský z Tessaloniky.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 3, 'Druhý pak den připlavili jsme se k Sidonu. A tu Julius přívětivě se maje ku Pavlovi, dopustil mu, aby jda k přátelům, u nich měl pohodlí.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 4, 'A berouce se odtud, plavili jsme se podlé Cypru, proto že byli větrové odporní.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 5, 'A tak přeplavivše se přes moře Cilické a Pamfylické, přišli jsme do Myry, města Lycického.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 6, 'A tu našed setník bárku Alexandrinskou, kteráž měla plouti do Vlach, uvedl nás na ni.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 7, 'A když jsme za mnoho dní znenáhla se plavili, a sotva přijeli proti Gnidum, proto že vítr nám bránil, i podjeli jsme Krétu podlé Salmóny.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 8, 'A sotva ji pomíjeti mohše, přijeli jsme na jedno místo, kteréž slove Pěkný břeh, od kteréhož nedaleko bylo město Lasea.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 9, 'Když pak drahný čas přešel, a již bylo nebezpečné plavení, (nebo již byl i půst pominul,) napomínal Pavel,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 10, 'Řka jim: Muži, vidím, že s ublížením a s mnohou škodou netoliko nákladu a lodí, ale i životů našich toto plavení bude.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 11, 'Ale setník více věřil správci lodí a marináři, než tomu, co Pavel pravil.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 12, 'A když nebylo tu příhodného přístavu, kdež by pobyli přes zimu, mnozí tak radili, aby se předce pustili odtud, zda by jak mohli, přijedouce do Fenicen, přes zimu tu pobyti na břehu Kréty, kterýž leží k větru nešpornímu, a k větru mezi západním a půlnočním vějícímu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 13, 'A když počal vítr víti od poledne, za to měli, že se budou umíněnou cestou držeti, ale pustivše se, jeli blízko Kréty.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 14, 'Po neveliké pak chvíli udeřil na ně vítr bouřlivý půlnoční, kterýž slove Euroklydon.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 15, 'A když lodí zachvácena byla, a nemohla odolati větru, pustivše, tak jsme se vezli.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 16, 'A v běhu snešeni byvše pod jeden ostrov neveliký, kterýž slove Klauda, sotva jsme mohli obdržeti člun.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 17, 'Kterýž zdvihše, pomoci užívali, podpásavše bárku; a bojíce se, aby neuhodili na místo nebezpečné, spustivše plachtu, tak se plavili.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 18, 'A když bouře vichrová námi velmi zmítala, nazejtří náklad ven metali.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 19, 'A v třetí den i to nádobí bárce potřebné svýma rukama vyházeli jsme.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 20, 'A když ani slunce se neukázalo ani hvězdy za mnoho dní, a bouře vždy větší nastávala, již byla všecka naděje o vysvobození našem odjata.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 21, 'A když jsme již byli hladem velmi ztrápeni, tehdy stoje Pavel u prostřed nich, řekl: Měli jste zajisté, ó muži, uposlechnouce mne, nehýbati se od Kréty, a uvarovati se nebezpečenství tohoto a škody.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 22, 'A i nyní vás napomínám, abyste dobré mysli byli; neboť nezahyne žádný z vás, kromě bárky samé.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 23, 'Nebo této noci ukázal mi se anděl Boha toho, jehož já jsem, a kterémuž sloužím,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 24, 'Řka: Neboj se, Pavle, před císařem máš státi, a aj, dalť tobě Bůh všecky, kteříž se plaví s tebou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 25, 'Protož buďte dobré mysli, muži; neboť věřím Bohu, že se tak stane, jakž jest mi mluveno.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 26, 'Mámeť se pak dostati na nějaký ostrov.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 27, 'A když již byla čtrnáctá noc, a my se plavili po moři Adriatickém, okolo půlnoci, domnívali se plavci, že by se jim okazovala krajina nějaká.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 28, 'Kteříž spustivše olovnici, nalezli hlubokost dvadcíti loktů; a odjevše odtud maličko, opět spustivše olovnici, nalezli patnácti loktů.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 29, 'A bojíce se, aby na místa skalnatá neuhodili, spustivše z bárky čtyři kotve, žádali, aby den byl.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 30, 'Když pak chtěli marináři uteci z bárky, a pustiti člun do moře, pod zámyslem, jako by chtěli od předku lodí kotve roztahovati,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 31, 'Řekl Pavel setníkovi a žoldnéřům: Nezůstanou-li tito na lodí, vy nebudete moci zachováni býti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 32, 'Tedy žoldnéři utínali provazy u člunu, a pustili jej, aby pryč plynul.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 33, 'A když již dnělo, napomínal Pavel všech, aby pojedli, řka: Již jest tomu dnes čtrnáctý den, jakž očekávajíce, trváte lační, nic nejedouce.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 34, 'Protož prosím vás, abyste pojedli, neboť to k zachování vašeho zdraví slouží; žádnéhoť zajisté z vás vlas s hlavy nespadne.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 35, 'To pověděv, a vzav chléb, díky vzdával Bohu přede všemi, a rozlomiv, počal jísti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 36, 'A tak potěšeni byvše všickni, pojedli i oni.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 37, 'Bylo pak nás všech osob na lodí dvě stě sedmdesáte a šest.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 38, 'A nasyceni byvše pokrmem, oblehčovali bárku, vysýpajíce pšenici do moře.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 39, 'A když byl den, nemohli země viděti, než okřídlí nějaké znamenali, ano má břeh, k němuž myslili, kdyby jak mohli přistati s lodí.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 40, 'A vytáhše kotvy, pustili se po moři, rozpustivše také provazy pravidl; a zdvihše plachtu k větru, táhli se k břehu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 41, 'Ale když trefili na to místo, kdež se dvoje moře schází, tu se zastavila lodí. A přední konec lodí uváznutý stál, nehýbaje se, zadní pak konec lámal se násilím vln.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 42, 'Tedy žoldnéři radili, aby vězně zmordovali, aby jim některý vyplyna, neutekl.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 43, 'Ale setník chtěje zachovati Pavla, nedal toho učiniti. I rozkázal těm, kteříž mohli plovati, aby se pustili nejprv, a vyplynuli na zem,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 44, 'Jiní pak na dskách, a někteří na kusích lodí. A tak se stalo, že všickni zdraví vyšli na zemi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 1, 'A tak zachováni byvše, teprv poznali, že ostrov ten sloul Melita.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 2, 'Lidé pak toho ostrova velikou přívětivost k nám ukázali. Nebo zapálivše hranici drev, přijali nás všecky, pro déšť, kterýž v tu chvíli byl, a pro zimu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 3, 'A když Pavel sebral drahně roždí, a kladl na oheň, ještěrka, utíkajíc před horkem, připjala se k ruce jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 4, 'A když uzřeli lidé toho ostrova, ano ještěrka visí u ruky jeho, řekli jedni druhým: Jistě člověk tento jest vražedlník; nebo ač z moře vyšel, však pomsta nedá jemu živu býti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 5, 'Ale on střásl tu ještěrku do ohně, a nic se jemu zlého nestalo.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 6, 'Oni pak očekávali, že oteče, aneb padna, pojednou umře. A když toho dlouho čekali a viděli, že se mu nic zlého nestalo, změnivše se, pravili, že jest on bůh.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 7, 'Na těch pak místech měl popluží kníže toho ostrova, jménem Publius. Kterýž přijav nás k sobě, za tři dni přátelsky u sebe v hospodě choval.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 8, 'I přihodilo se, že otec toho Publia ležel, maje zimnici a červenou nemoc. K němuž všed Pavel, a pomodliv se, vložil na něj ruce, a uzdravil jej.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 9, 'A když se to stalo, tedy jiní, kteříž na ostrově tom nemocní byli, přistupovali, a byli uzdravováni.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 10, 'Ctili nás pak velice, a když jsme se měli pryč plaviti, nakladli toho, čehož potřebí bylo.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 11, 'A po třech měsících plavili jsme se na bárce Alexandrinské, kteráž tu byla na tom ostrově přes zimu, mající za erb Kastora a Polluxa.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 12, 'A když jsme přijeli do Syrakusis, zůstali jsme tu za tři dni.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 13, 'A odtud okolo plavíce se, přišli jsme do Regium; a po jednom dni, když vál vítr od poledne, druhý den přijeli jsme do Puteolos.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 14, 'Kdežto nalezše bratří, žádáni jsme byli od nich, abychom pobyli u nich za sedm dní. A tak jsme se k Římu brali.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 15, 'Odkudž, když o nás uslyšeli bratří, vyšli proti nám až na rynk Appiův a ke Třem krčmám. Kteréž uzřev Pavel, poděkoval Bohu, a počal býti dobré mysli.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 16, 'A když jsme přišli do Říma, setník dal vězně v moc hejtmanu vojska, ale Pavlovi dopuštěno, aby sám bydlil s žoldnéřem, kterýž ho ostříhal.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 17, 'I stalo se po třech dnech, svolal Pavel přední z Židů. A když se sešli, řekl jim: Muži bratří, já nic neučiniv proti lidu ani proti obyčejům otcovským, jat jsa z Jeruzaléma, vydán jsem v ruce Římanům.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 18, 'Kteříž vyslyševše mne, chtěli propustiti, proto že žádné viny hodné smrti na mně nebylo.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 19, 'Ale když Židé odpírali, přinucen jsem odvolati se k císaři, ne jako bych měl co na svůj národ žalovati.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 20, 'A protož z té příčiny povolal jsem vás, abych vás viděl, a s vámi promluvil; nebo pro naději lidu Izraelského řetězem tímto svázán jsem.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 21, 'A oni řekli jemu: Myť jsme žádného psání neměli o tobě z Židovstva, aniž kdo z bratří přijda, vypravoval neb mluvil co zlého o tobě.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 22, 'Ale žádámeť od tebe slyšeti, jak smyslíš; nebo víme o té sektě, že se jí všudy odpírá.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 23, 'A když jemu uložili den, sešlo se jich mnoho do hospody k němu, jimž s osvědčováním vypravoval o království Božím, slouže jim k víře o Ježíšovi z zákona Mojžíšova a proroků, od jitra až do večera.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 24, 'A někteří uvěřili tomu, což vypravoval, někteří pak nevěřili.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 25, 'A tak nejsouce mezi sebou svorní, rozešli se, když promluvil Pavel to jedno slovo: Jistě žeť dobře Duch svatý skrze proroka Izaiáše mluvil k otcům našim,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 26, 'Řka: Jdi k lidu tomuto a rci jim: Slyšením slyšeti budete, ale nesrozumíte, a hledíce, hleděti budete, ale neuzříte.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 27, 'Nebo zhrublo srdce lidu tohoto, a ušima těžce slyšeli, a oči své zamhouřili, aby snad neviděli očima, a ušima neslyšeli, a srdcem nesrozuměli, a neobrátili se, abych jich neuzdravil.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 28, 'Budiž vám tedy známo, že jest pohanům posláno toto spasení Boží, a oniť slyšeti budou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 29, 'A když on to propověděl, odešli Židé, majíce mezi sebou hádky mnohé.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 30, 'Pavel pak trval za celé dvě létě v hospodě své, a přijímal všecky, kteříž přicházeli k němu,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 31, 'Káže o království Božím, a uče těm věcem, kteréž jsou o Pánu Ježíši Kristu, se vší doufanlivostí bez překážky.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 1, 'Pavel, služebník Jezukristův, povolaný apoštol, oddělený k kázaní evangelium Božího,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 2, 'Kteréž zdávna zaslíbil skrze proroky své v písmích svatých,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 3, 'O Synu svém zplozeném z semene Davidova s strany těla,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 4, 'Kterýž prokázán jest býti Synem Božím mocně, podlé Ducha posvěcení, skrze z mrtvých vstání, totiž o Ježíši Kristu, Pánu našem,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 5, 'Skrze něhož jsme přijali milost a apoštolství ku poslušenství víry mezi všemi národy pro jméno jeho,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 6, 'Z nichž i vy jste povolaní Ježíše Krista,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 7, 'Všechněm, kteříž jste v Římě, milým Božím, povolaným svatým: Milost vám a pokoj od Boha Otce našeho a Pána Ježíše Krista.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 8, 'Nejprvé pak díky činím Bohu svému skrze Ježíše Krista ze všech vás, že víra vaše rozhlašuje se po všem světě.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 9, 'Svědek mi jest zajisté Bůh, kterémuž sloužím duchem svým v evangelium Syna jeho, žeť bez přestání zmínku o vás činím,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 10, 'Vždycky na svých modlitbách žádaje, abych aspoň někdy mohl šťastně, byla-li by vůle Boží, k vám přijíti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 11, 'Neboť velice žádám viděti vás, abych vám udělil částku nějakou milosti duchovní ku potvrzení vašemu,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 12, 'To jest, abych spolu s vámi potěšen byl, skrze společnou i vaši i mou víru.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 13, 'Nechciť pak, bratří, abyste nevěděli, žeť jsem mnohokrát uložil přijíti k vám, (ale překážky jsem měl až dosavad,) abych nějaký užitek také i mezi vámi měl, jako i mezi jinými národy.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 14, 'Nebo Řeků i kterýchkoli jiných národů, i moudrých i nemoudrých, dlužník jsem.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 15, 'A tak, pokudž na mně jest, hotov jsem i vám, kteříž v Římě jste, zvěstovati evangelium.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 16, 'Neboť se nestydím za evangelium Kristovo; moc zajisté Boží jest k spasení každému věřícímu, Židu předně, potom i Řeku.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 17, 'Nebo spravedlnost Boží zjevuje se skrze ně z víry u víru, jakož psáno jest: Spravedlivý pak z víry živ bude.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 18, 'Zjevuje se zajisté hněv Boží s nebe proti každé bezbožnosti a nepravosti lidí, pravdu Boží v nepravosti zadržujících.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 19, 'Nebo což poznáno býti může o Bohu, známé jest jim, Bůh zajisté zjevil jim.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 20, 'Nebo neviditelné věci jeho, hned od stvoření světa, po věcech učiněných rozumem pochopeny bývají, totiž ta jeho věčná moc a Božství, tak aby oni byli bez výmluvy,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 21, 'Proto že poznavše Boha, nectili jako Boha, ani jemu děkovali, ale marní učiněni jsou v myšleních svých, a zatmíno jest nemoudré srdce jejich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 22, 'Měvše se za moudré, blázni učiněni jsou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 23, 'Nebo směnili slávu neporušitelného Boha v podobenství obrazu porušitelného člověka, i ptactva, i hovad čtvernohých, i zeměplazů.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 24, 'Protož i Bůh vydal je v žádosti srdce jejich k nečistotě, aby zprznili těla svá vespolek.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 25, 'Jako ty, kteříž směnili pravdu Boží za lež, a ctili i sloužili stvoření raději nežli stvořiteli, kterýž jest požehnaný na věky. Amen.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 26, 'Protož je vydal Bůh v žádosti ohavné. Nebo i ženy jejich změnily přirozené sebe užívání v to, kteréž jest proti přirození.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 27, 'A podobně i mužské pohlaví, opustivše přirozené užívání ženy, rozpálili se v žádosti své jedni k druhým, mužské pohlaví s mužským pohlavím mrzkost pášíce, a spravedlivou mzdu, kteráž na jejich blud slušela, sami na sebe uvodíce.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 28, 'A jakož sobě nevážili známosti Boha, tak i Bůh vydal je v převrácený smysl, aby činili to, což nesluší,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 29, 'Jsouce naplněni vší nepravostí, smilstvem, nešlechetností, lakomstvím, zlostí, plní závisti, vraždy, svárů, lsti, zlých obyčejů,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 30, 'Utrhači, pomluvači, Boha nenávidící, hánliví, pyšní, chlubní, nalezači zlých věcí, rodičů neposlušní,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 31, 'Nemoudří, smluv nezdrželiví, beze vší lítosti, neukojitelní a nemilosrdní.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 32, 'Kteříž vědouce o tom právu Božím, (že ti, kteříž takové věci činí, hodni jsou smrti,) netoliko ty věci činí, ale i činícím nakládají.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 1, 'Protož nemůžeš se vymluviti, ó člověče, každý potupující. Nebo tím, že jiného potupuješ, sám sebe odsuzuješ, poněvadž totéž činíš, což tupíš.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 2, 'Vímeť zajisté, že soud Boží jest podlé pravdy proti těm, kteříž takové věci činí.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 3, 'Zdali se domníváš, ó člověče, kterýž soudíš ty, kdož takové věci činí, a sám totéž čině, že ty ujdeš soudu Božího?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 4, 'Čili bohatstvím dobrotivosti jeho a snášelivosti i dlouhočekání pohrdáš, nevěda, že dobrotivost Boží ku pokání tebe vede?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 5, 'Ale podlé tvrdosti své a srdce nekajícího shromažďuješ sám sobě hněv ke dni hněvu a zjevení spravedlivého soudu Božího.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 6, 'Kterýž odplatí jednomu každému podlé skutků jeho,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 7, 'Těm zajisté, kteříž trvajíce v dobrém skutku, slávy a cti a nesmrtelnosti hledají, životem věčným,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 8, 'Těm pak, kteříž jsou svárliví, a pravdě nepovolují, ale povolují nepravosti, prchlivostí a hněvem,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 9, 'Trápením a úzkostí, každé duši člověka činícího zlé, i Žida předně, i Řeka.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 10, 'Ale sláva a čest a pokoj každému, kdo činí dobré, i Židu předně, i Řeku.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 11, 'Neboť není přijímání osob u Boha.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 12, 'Kteřížkoli zajisté bez zákona hřešili, bez zákona i zahynou; a kteřížkoli pod zákonem hřešili, skrze zákon odsouzeni budou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 13, '(Nebo ne ti, kteříž slyší zákon, spravedlivi jsou před Bohem, ale činitelé zákona spravedlivi budou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 14, 'Nebo když pohané zákona nemajíce, od přirození činí to, což přikazuje zákon, takoví zákona nemajíce, sami sobě zákonem jsou,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 15, 'Jako ti, kteříž ukazují dílo zákona napsané na srdcích svých, když jim to osvědčuje svědomí jejich i myšlení, kteráž se vespolek obviňují, aneb také vymlouvají.)');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 16, 'V ten den, když souditi bude Bůh tajné věci lidské, podlé evangelium mého skrze Jezukrista.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 17, 'Aj, ty sloveš Žid, a zpoléháš na zákon, a chlubíš se Bohem,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 18, 'A znáš vůli jeho, a rozeznáváš, co sluší, naučen jsa z zákona,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 19, 'A za to máš, že jsi ty vůdcím slepých, světlem těch, kteříž jsou ve tmě,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 20, 'Ředitelem nemoudrých, učitelem nemluvňat, majícím formu umění a pravdy v zákoně.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 21, 'Kterakž tedy jiného uče, sám sebe neučíš? Vyhlašuje, že nemá kradeno býti, kradeš?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 22, 'Pravě: Nezcizoložíš, cizoložství pácháš? V ohavnosti maje modly, svatokrádeže se dopouštíš?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 23, 'Zákonem se chlubě, přestupováním zákona Bohu neúctu činíš?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 24, 'Nebo jméno Boží pro vás v porouhání jest mezi pohany, jakož psáno jest.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 25, 'Obřezáníť zajisté prospěje, budeš-li zákon plniti; pakli budeš přestupitelem zákona, obřezání tvé učiněno jest neobřezáním.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 26, 'A protož jestližeť by neobřízka ostříhala práv zákona, zdaliž nebude počtena neobřízka jejich za obřízku?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 27, 'A ti, kteříž jsou z přirození neobřízka, zachovávajíce zákon, zdaliž nepotupí tebe, kterýž pod literou a obřízkou přestupník jsi zákona?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 28, 'Nebo ne ten jest Žid, kterýž jest zjevně; aniž to jest obřezání, kteréž bývá zjevně na těle;');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 29, 'Ale ten jest Žid, kterýž vnitř jest Židem, obřezání maje srdečné v duchu, a ne podlé litery; jehož chvála ne z lidí jest, ale z Boha.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 1, 'Což tedy má více Žid? Aneb jaký jest užitek obřízky?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 2, 'Mnohý všelijak. Přední zajisté, že jest jim svěřen zákon Boží.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 3, 'Nebo co jest do toho, jestliže byli někteří nevěrní? Zdaliž nevěra jejich věrnost Boží vyprázdní?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 4, 'Nikoli, nýbrž budiž Bůh pravdomluvný, ale každý člověk lhář, jakož psáno jest: Abys ospravedlněn byl v řečech svých, a přemohl, když bys soudil.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 5, 'Jestližeť pak nepravost naše spravedlnost Boží zvelebuje, což díme? Zdali nespravedlivý jest Bůh, kterýž uvodí hněv? (Po lidskuť pravím.)');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 6, 'Nikoli, sic jinak kterakž by Bůh soudil svět?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 7, 'Nebo jestližeť pravda Boží mou lží rozmohla se k slávě jeho, i pročež pak já ještě jako hříšník bývám souzen?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 8, 'A ne raději (jakž o nás zle mluví, a jakož někteří praví, že bychom my říkali,): Čiňme zlé věci, aby přišly dobré? Jichž spravedlivé jest odsouzení.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 9, 'Což tedy? Máme něco napřed? Nikoli, nebo jsme prvé dokázali toho, že jsou, i Židé i Řekové, všickni pod hříchem,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 10, 'Jakož psáno jest: Že není spravedlivého, ani jednoho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 11, 'Není rozumného, není, kdo by hledal Boha.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 12, 'Všickni se uchýlili, spolu neužiteční učiněni jsou; není, kdo by činil dobré, není ani jednoho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 13, 'Hrob otevřený jest hrdlo jejich, jazyky svými lstivě mluvili, jed lítých hadů jest pod rty jejich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 14, 'Kterýchž ústa plná jsou zlořečení a hořkosti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 15, 'Nohy jejich rychlé k vylévání krve.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 16, 'Setření a bída na cestách jejich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 17, 'A cesty pokoje nepoznali.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 18, 'Není bázně Boží před očima jejich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 19, 'Víme pak, že cožkoli zákon mluví, těm, kteříž jsou pod zákonem mluví, aby všeliká ústa zacpána byla, a aby vinen byl všecken svět Bohu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 20, 'Protož z skutků zákona nebude ospravedlněn žádný člověk před oblíčejem jeho; nebo skrze zákon poznání hřícha.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 21, 'Ale nyní bez zákona spravedlnost Boží zjevena jest, osvědčená zákonem i proroky,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 22, 'Spravedlnost totiž Boží, skrze víru Ježíše Krista, ke všem a na všecky věřící.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 23, 'Neboť není rozdílu. Všickniť zajisté zhřešili, a nemají slávy Boží.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 24, 'Spravedlivi pak učiněni bývají darmo, milostí jeho, skrze vykoupení, kteréž se stalo v Kristu Ježíši,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 25, 'Jehož Bůh vydal za smírci, skrze víru ve krvi jeho, k ukázaní spravedlnosti své, skrze odpuštění předešlých hříchů,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 26, 'V shovívání Božím, k dokázaní spravedlnosti své v nynějším času, k tomu, aby on spravedlivým byl, a ospravedlňujícím toho, kterýž jest z víry Ježíšovy.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 27, 'Kdež jest tedy ta chlouba? Vyprázděna jest. Skrze který zákon? Skutků-li? Nikoli, ale skrze zákon víry.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 28, 'Protož za to máme, že člověk bývá spravedliv učiněn věrou bez skutků zákona.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 29, 'Zdaliž jest toliko Bůh Židů? Zdali také není i pohanů? Jistě i pohanů,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 30, 'Poněvadž jeden jest Bůh, kterýž ospravedlňuje obřízku z víry, a neobřízku skrze víru.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 31, 'Což tedy zákon vyprazdňujeme skrze víru? Nikoli, nýbrž zákon tvrdíme.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 1, 'Což tedy díme, že došel Abraham, otec náš, podlé těla?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 2, 'Nebo byl-liť Abraham z skutků spravedliv učiněn, máť se čím chlubiti, ale ne u Boha.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 3, 'Nebo co praví písmo? Uvěřil pak Abraham Bohu, i počteno jemu za spravedlnost.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 4, 'Kdožť skutky činí, tomuť odplata nebývá počtena podlé milosti, ale podlé dluhu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 5, 'Tomu pak, kdož nečiní skutků, ale věří v toho, kterýž spravedlivého činí bezbožníka, bývá počtena víra jeho za spravedlnost,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 6, 'Jakož i David vypravuje blahoslavenství člověka, jemuž Bůh přivlastňuje spravedlnost bez skutků, řka:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 7, 'Blahoslavení, jichž odpuštěny jsou nepravosti, a jejichž přikryti jsou hříchové.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 8, 'Blahoslavený muž, kterémuž Pán nepočítá hříchu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 9, 'Blahoslavenství tedy toto k obřízce-li přináleží, čili také k neobřízce? Nebo pravíme, že Abrahamovi víra jest počtena za spravedlnost.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 10, 'Kterak pak jest počtena? Když byl obřezán, či před obřezáním? Ne v obřízce, ale před obřezáním.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 11, 'A znamení obřízku přijal za znamení spravedlnosti víry, kteráž byla před obřezáním, na to, aby byl otcem všech věřících v neobřízce, aby i jim přičtena byla spravedlnost,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 12, 'A otcem obřízky těch, kteříž ne z obřízky toliko jsou, ale kteříž kráčejí šlepějemi víry otce našeho Abrahama, kteráž byla před obřezáním.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 13, 'Nebo ne skrze zákon stalo se zaslíbení Abrahamovi, aneb semeni jeho, aby byl dědicem světa, ale skrze spravedlnost víry.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 14, 'Nebo jestliže ti, kteří jsou z zákona, dědicové jsou, zmařena jest víra, a zrušeno jest to zaslíbení.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 15, 'Zákon zajisté hněv působí; nebo kdež není zákona, tu ani přestoupení.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 16, 'A protož z víry jde, aby šlo podlé milosti, proto aby pevné bylo zaslíbení všemu semeni, netoliko tomu, kteréž z zákona jest, ale i tomu, kteréž jest z víry Abrahamovy, kterýž jest otec všech nás,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 17, '(Jakož psáno jest: Otcem mnohých národů postavil jsem tebe,) před oblíčejem Boha, jemuž uvěřil, kterýž obživuje mrtvé, a povolává i těch věcí, jichž není, jako by byly.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 18, 'Kterýž v naději proti naději uvěřil, že bude otcem mnohých národů, podlé toho povědění: Takť bude símě tvé.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 19, 'A nezemdlev u víře, nehleděl na své tělo již umrtvené, ješto téměř ve stu letech byl, ani na život Sáry umrtvený.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 20, 'O zaslíbení tedy Božím nepochyboval z nedověry, nýbrž posilnil se věrou, dav chválu Bohu,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 21, 'Jsa tím jist, že cožkoli zaslíbil, mocen jest i učiniti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 22, 'A protož počteno jest jemu to za spravedlnost.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 23, 'Jestiť pak to napsáno ne pro něj toliko, že jemu počteno bylo,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 24, 'Ale i pro nás, kterýmž bude počteno, věřícím totiž v toho, kterýž vzkřísil Ježíše Pána našeho z mrtvých,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 25, 'Kterýž vydán jest pro hříchy naše, a vstal z mrtvých pro ospravedlnění naše.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 1, 'Ospravedlněni tedy jsouce z víry, pokoj máme s Bohem skrze Pána našeho Jezukrista,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 2, 'Skrze něhož i přístup měli jsme věrou k milosti této, kterouž stojíme. A chlubíme se nadějí slávy Boží.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 3, 'A ne jen nadějí, ale také chlubíme se ssouženími, vědouce, že ssoužení trpělivost působí,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 4, 'A trpělivost zkušení, zkušení pak naději.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 5, 'A nadějeť nezahanbuje; nebo láska Boží rozlita jest v srdcích našich skrze Ducha svatého, kterýž dán jest nám.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 6, 'Kristus zajisté, když jsme my ještě mdlí byli, v čas příhodný za bezbožné umřel,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 7, 'Ješto sotva kdo za spravedlivého umře, ač za dobréhoť by někdo snad i umříti směl.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 8, 'Dokazujeť pak Bůh lásky své k nám; nebo když jsme ještě hříšníci byli, Kristus umřel za nás.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 9, 'Čím tedy více nyní ospravedlněni jsouce krví jeho, spaseni budeme skrze něho od hněvu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 10, 'Poněvadž byvše nepřátelé, smířeni jsme s Bohem skrze smrt Syna jeho, nadtoť smířeni jsouce, spaseni budeme skrze život jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 11, 'A ne jen to, ale chlubíme se i Bohem, skrze Pána našeho Jezukrista, skrze něhož nyní smíření jsme došli.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 12, 'A protož jakož skrze jednoho člověka hřích na svět všel a skrze hřích smrt, a tak na všecky lidi smrt přišla, v němž všickni zhřešili.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 13, 'Nebo až do zákona hřích byl na světě, ale hřích se nepočítá, když zákona není.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 14, 'Kralovala pak smrt od Adama až do Mojžíše také i nad těmi, kteříž nehřešili ku podobenství přestoupení Adamova, kterýž jest figůra toho budoucího.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 15, 'Ale ne jako hřích, tak i milost. Nebo poněvadž onoho jednoho pádem mnoho jich zemřelo, mnohemť více milost Boží a dar z milosti toho jednoho člověka Jezukrista na mnohé rozlit jest.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 16, 'Aniž jako skrze jednoho, kterýž zhřešil, tak milost. Nebo vina z jednoho pádu ku potupení, ale milost z mnohých hříchů k ospravedlnění.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 17, 'Nebo poněvadž pro ten pád jeden smrt kralovala pro toho jednoho, mnohemť více, kteříž rozhojněnou milost a dar spravedlnosti přijímají, v životě kralovati budou skrze toho jediného Jezukrista.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 18, 'A tak tedy, jakž skrze pád jeden na všecky lidi přišla vina ku potupení, tak i skrze jediné ospravedlnění na všecky lidi přišla milost k ospravedlnění života.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 19, 'Nebo jakož skrze neposlušenství jednoho člověka učiněno jest mnoho hříšných, tak i skrze poslušenství jednoho spravedlivi učiněni budou mnozí.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 20, 'Zákon pak k tomu přistoupil, aby se rozhojnil hřích, a kdež se rozhojnil hřích, tu ještě více rozhojnila se milost,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 21, 'Aby jakož kraloval hřích k smrti, tak aby i milost kralovala skrze spravedlnost k životu věčnému, skrze Jezukrista Pána našeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 1, 'Což tedy díme? Zůstaneme v hříchu, aby se milost rozhojnila?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 2, 'Nikoli. Kdož jsme zemřeli hříchu, kterakž ještě živi budeme v něm?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 3, 'Zdaliž nevíte, že kteřížkoli pokřtěni jsme v Krista Ježíše, v smrt jeho pokřtěni jsme?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 4, 'Pohřbeni jsme tedy s ním skrze křest v smrt, abychom, jakož z mrtvých vstal Kristus k slávě Otce, tak i my v novotě života chodili.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 5, 'Nebo poněvadž jsme s ním vštípeni připodobněním smrti jeho, tedyť i vzkříšením budeme,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 6, 'To vědouce, že starý člověk náš s ním spolu ukřižován jest, aby bylo umrtveno tělo hřícha, abychom již potom nesloužili hříchu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 7, 'Nebo kdožť umřel, ospravedlněn jest od hříchu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 8, 'Jestližeť jsme pak zemřeli s Kristem, věřímeť, že spolu s ním také živi budeme,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 9, 'Vědouce, že Kristus vstav z mrtvých, již více neumírá, smrt nad ním již více nepanuje.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 10, 'Nebo žeť umřel, hříchu umřel jednou; že pak jest živ, živ jest Bohu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 11, 'Tak i vy za to mějte, že jste zemřeli zajisté hříchu, ale živi jste Bohu v Kristu Ježíši, Pánu našem.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 12, 'Nepanujž tedy hřích v smrtelném těle vašem, abyste povolovali jemu v žádostech jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 13, 'Aniž vydávejte oudů svých za odění nepravosti hříchu, ale vydávejte se k službě Bohu, jako byvše mrtví, již živí, a oudy své za odění spravedlnosti Bohu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 14, 'Nebo hřích nebude panovati nad vámi; nejste zajisté pod zákonem, ale pod milostí.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 15, 'Což pak? Hřešiti budeme, když nejsme pod zákonem, ale pod milostí? Nikoli.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 16, 'Zdaliž nevíte, že komuž se vydáváte za služebníky ku poslušenství, toho jste služebníci, kohož posloucháte, buď hříchu k smrti, buď poslušenství k spravedlnosti?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 17, 'Ale díka Bohu, že byvše služebníci hřícha, uposlechli jste z srdce způsobu učení toho, v kteréž uvedeni jste.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 18, 'Vysvobozeni pak jsouce od hříchu, učiněni jste služebníci spravedlnosti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 19, 'Po lidsku pravím, pro mdlobu těla vašeho: Jakž jste vydávali oudy své v službu nečistotě a nepravosti k činění nepravosti, tak nyní vydávejte oudy své v službu spravedlnosti ku posvěcení.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 20, 'Nebo když jste byli služebníci hřícha, cizí jste byli od spravedlnosti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 21, 'Jaký jste pak užitek měli tehdáž toho, začež se nyní stydíte? Konec zajisté těch věcí jest smrt.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 22, 'Nyní pak vysvobozeni jsouce od hříchu, a podmaněni v službu Bohu, máte užitek svůj ku posvěcení, cíl pak život věčný.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 23, 'Nebo odplata za hřích jest smrt, ale milost Boží život věčný v Kristu Ježíši, Pánu našem.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 1, 'Zdaliž nevíte, bratří, (nebo povědomým zákona mluvím,) že zákon panuje nad člověkem, dokudž živ jest?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 2, 'Nebo žena, kteráž za mužem jest, živému muži přivázána jest zákonem; pakli by umřel muž, svobodná jest od zákona muže.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 3, 'A protož dokudž jest živ muž, slouti bude cizoložnice, bude-li s jiným mužem; pakliť by muž její umřel, jest svobodna od zákona toho, tak že již nebude cizoložnice, bude-li s jiným mužem.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 4, 'Takž tedy, bratří moji, i vy umrtveni jste zákonu skrze tělo Kristovo, abyste byli jiného, toho totiž, kterýž z mrtvých vstal, abychom ovoce nesli Bohu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 5, 'Nebo když jsme byli v těle, žádosti hříchů skrze zákon moc svou provodily v oudech našich k nesení ovoce smrti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 6, 'Nyní pak osvobozeni jsme od zákona, když umřel ten, v němž jsme držáni byli, tak abychom sloužili v novotě ducha, a ne v vetchosti litery.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 7, 'Což tedy díme? Že zákon jest hříchem? Nikoli; nýbrž hříchu jsem nepoznal, než skrze zákon. Nebo i o žádosti byl bych nevěděl, kdyby byl zákon neřekl: Nepožádáš.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 8, 'Ale příčinu vzav hřích skrze přikázaní, zplodil ve mně všelikou žádost. Bez zákona zajisté hřích mrtev jest.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 9, 'Jáť pak byl jsem živ někdy bez zákona, ale když přišlo přikázaní, hřích ožil,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 10, 'A já umřel. I shledáno jest, že to přikázaní, kteréž mělo býti k životu, jest mi k smrti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 11, 'Nebo hřích, vzav příčinu skrze to přikázaní, podvedl mne, a skrze ně zabil.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 12, 'A tak zákon zajisté jest svatý, a přikázaní svaté i spravedlivé a dobré.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 13, 'Tedy to dobré učiněno jest mi smrt? Nikoli, ale hřích, aby se okázal býti hříchem, skrze to dobré zplodil mi smrt, aby byl příliš velmi hřešící hřích skrze přikázaní.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 14, 'Víme zajisté, že zákon jest duchovní, ale já jsem tělesný, prodaný hříchu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 15, 'Nebo toho, což činím, neoblibuji; nebo ne, což chci, to činím, ale, což v nenávisti mám, to činím.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 16, 'Jestližeť pak, což nechci, to činím, povoluji zákonu, že jest dobrý.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 17, 'A tak nyní více ne já to činím, ale ten hřích, kterýž ve mně přebývá.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 18, 'Vímť zajisté, že nepřebývá ve mně, (to jest v těle mém,) dobré. Nebo chtění hotové mám, ale abych vykonati mohl dobré, tohoť nenalézám.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 19, 'Nebo nečiním dobrého, kteréž chci, ale činím to zlé, jehož nechci.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 20, 'A poněvadž pak, čehož já nechci, to činím, tedyť již ne já činím to, ale ten hřích, kterýž ve mně přebývá.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 21, 'Nalézám tedy zákon, když chci činiti dobré, že se mne přídrží zlé.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 22, 'Nebo zvláštní líbost mám v zákoně Božím podlé vnitřního člověka;');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 23, 'Ale vidím jiný zákon v oudech svých, odporující zákonu mysli mé, a jímající mne zákonu hřícha, kterýž jest v oudech mých.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 24, 'Bídný já člověk! Kdo mne vysvobodí z toho těla smrti?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 25, 'Děkujiť Bohu skrze Jezukrista Pána našeho. A takž tedy tentýž já sloužím myslí zákonu Božímu, ale tělem zákonu hřícha.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 1, 'A protož neníť již žádného potupení těm, kteříž jsou v Kristu Ježíši, nechodícím podlé těla, ale podlé Ducha.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 2, 'Nebo zákon Ducha života v Kristu Ježíši vysvobodil mne od zákona hřícha i smrti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 3, 'Nebo seč nemohl býti zákon, jelikož byl mdlý pro tělo, Bůh poslav Syna svého v podobnosti těla hřícha, a příčinou hřícha, potupil hřích na těle,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 4, 'Aby spravedlnost zákona vyplněna byla v nás, kteříž nechodíme podlé těla, ale podlé Ducha.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 5, 'Ti zajisté, kteříž jsou podlé těla, chutnají to, což jest těla, ale ti, kteříž podlé Ducha, to, což jest Ducha.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 6, 'Nebo opatrnost těla jest smrt, opatrnost pak Ducha život a pokoj,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 7, 'Proto že opatrnost těla jest nepřítelkyně Bohu; nebo zákonu Božímu není poddána, aniž hned může býti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 8, 'Protož ti, kteříž jsou v těle, Bohu se líbiti nemohou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 9, 'Vy pak nejste v těle, ale v Duchu, poněvadž Duch Boží v vás přebývá. Jestližeť pak kdo Ducha Kristova nemá, tenť není jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 10, 'A jestliť Kristus v vás, tedy ač tělo umrtveno jest pro hřích, však duch živ jest pro spravedlnost.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 11, 'Jestližeť pak Duch toho, kterýž vzkřísil Ježíše z mrtvých, v vás přebývá, tedy ten, kterýž vzkřísil Krista z mrtvých, obživí i smrtelná těla vaše, pro přebývajícího Ducha jeho v vás.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 12, 'A takž tedy, bratří, dlužníciť jsme ne tělu, abychom podlé těla živi byli.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 13, 'Nebo budete-li podlé těla živi, zemřete; pakli byste Duchem skutky těla mrtvili, živi budete.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 14, 'Nebo kteřížkoli Duchem Božím vedeni bývají, ti jsou synové Boží.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 15, 'Nepřijali jste zajisté ducha služby opět k bázni, ale přijali jste Ducha synovství, v němž voláme Abba, totiž Otče.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 16, 'Tenť Duch osvědčuje duchu našemu, že jsme synové Boží.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 17, 'A jestliže synové, tedy i dědicové, dědicové zajisté Boží, spolu pak dědicové Kristovi, však jestliže spolu trpíme, abychom spolu i oslaveni byli.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 18, 'Nebo tak za to mám, že nejsou rovná utrpení nynější oné budoucí slávě, kteráž se zjeviti má na nás.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 19, 'Nebo stvoření pečlivě jako vyhlídaje, očekává zjevení synů Božích.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 20, 'Marnosti zajisté poddáno jest stvoření, nechtě, ale pro toho, kterýž je poddal,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 21, 'V naději, že i to stvoření vysvobozeno bude od služby porušení v svobodu slávy synů Božích.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 22, 'Nebo víme, že všecko stvoření spolu lká, a spolu ku porodu pracuje až posavad.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 23, 'A netoliko ono, ale i my, prvotiny Ducha mající, i myť sami v sobě lkáme, zvolení synů očekávajíce, a tak vykoupení těla svého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 24, 'Nebo nadějí spaseni jsme. Naděje pak, kteráž se vidí, není naděje. Nebo což kdo vidí, proč by se toho nadál?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 25, 'Pakli čehož nevidíme, toho se nadějeme, tedy toho skrze trpělivost očekáváme.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 26, 'Ano také i Duch pomocen jest mdlobám našim. Nebo zač bychom se měli modliti, jakž by náleželo, nevíme, ale ten Duch prosí za nás lkáními nevypravitelnými.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 27, 'Ten pak, kterýž jest zpytatel srdcí, zná, jaký by byl smysl Ducha, že podlé Boha prosí za svaté.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 28, 'Vímeť pak, že milujícím Boha všecky věci napomáhají k dobrému, totiž těm, kteříž podlé uložení jeho povoláni jsou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 29, 'Nebo kteréž předzvěděl, ty i předzřídil, aby byli připodobněni obrazu Syna jeho, aby on byl prvorozený mezi mnohými bratřími.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 30, 'Kteréž pak předzřídil, těch i povolal, a kterýchž povolal, ty i ospravedlnil, a kteréž ospravedlnil, ty i oslavil.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 31, 'Což tedy díme k tomu? Kdyžť jest Bůh s námi, i kdo proti nám?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 32, 'Kterýž ani vlastnímu Synu svému neodpustil, ale za nás za všecky vydal jej, i kterakž by tedy nám s ním všech věcí nedal?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 33, 'Kdo bude žalovati na vyvolené Boží? Bůh jest, kterýž ospravedlňuje.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 34, 'Kdo jest, ješto by potupil? Kristus jest, kterýž umřel, nýbrž i z mrtvých vstal, a kterýž i na pravici Boží jest, kterýž i oroduje za nás.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 35, 'Kdo nás odloučí od lásky Kristovy? Zarmoucení-li, aneb úzkost, neb protivenství? Zdali hlad, čili nahota? Zdali nebezpečenství, čili meč?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 36, 'Jakož psáno jest: Pro tebe mrtveni býváme celý den, jmíni jsme jako ovce oddané k zabití.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 37, 'Ale v tom ve všem udatně vítězíme, skrze toho, kterýž nás zamiloval.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 38, 'Jist jsem zajisté, že ani smrt, ani život, ani andělé, ani knížatstvo, ani mocnosti, ani nastávající věci, ani budoucí,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 39, 'Ani vysokost, ani hlubokost, ani kterékoli jiné stvoření, nebude moci nás odloučiti od lásky Boží, kteráž jest v Kristu Ježíši, Pánu našem.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 1, 'Pravduť pravím v Kristu, a neklamámť, čemuž i svědomí mé svědectví vydává v Duchu svatém,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 2, 'Žeť mám veliký zámutek, a ustavičnou bolest v srdci svém.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 3, 'Nebo žádal bych já sám zavrženým býti od Krista místo bratří svých, příbuzných svých podlé těla.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 4, 'Kteřížto jsou Izraelští, jejichž jest přijetí za syny, i sláva, i smlouvy, i zákona dání, i služba, i zaslíbení.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 5, 'Jejichž jsou otcové, a ti, z nichž jest Kristus podlé těla, kterýž jest nade všecky Bůh požehnaný na věky. Amen.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 6, 'A však nemůže zmařeno býti slovo Boží. Nebo ne všickni, kteříž jsou z Izraele, Izraelští jsou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 7, 'Aniž proto, že jsou símě Abrahamovo, všickni jsou synové, ale v Izákovi nazváno bude tvé símě.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 8, 'To jest, ne ti, kteříž jsou synové těla, jsou synové Boží, ale kteříž jsou synové zaslíbení, ti se počítají za símě.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 9, 'Nebo toto jest slovo zaslíbení: V týž čas přijdu, a Sára bude míti syna.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 10, 'A netoliko to, ale i Rebeka z jednoho počavši, totiž z Izáka, otce našeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 11, 'Nebo ještě před narozením, a prvé než co dobrého neb zlého učinili, aby uložení Boží, kteréž jest podlé vyvolení, ne z skutků, ale z toho, kterýž povolává, pevné bylo,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 12, 'Řečeno jest jí: Větší sloužiti bude menšímu,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 13, 'Jakož psáno jest: Jákoba jsem miloval, ale Ezau nenáviděl jsem.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 14, 'I což tedy díme? Zdali nespravedlnost jest u Boha? Nikoli.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 15, 'Nebo Mojžíšovi dí: Smiluji se, nad kým se smiluji, a slituji se, nad kýmž se slituji.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 16, 'A tak tedy není na tom, kdož chce, ani na tom, kdož běží, ale na Bohu, kterýž se smilovává.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 17, 'Nebo dí písmo Faraonovi: Proto jsem vzbudil tebe, abych na tobě ukázal moc svou, a aby rozhlášeno bylo jméno mé po vší zemi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 18, 'A tak tedy, nad kýmž chce, smilovává se, a koho chce, zatvrzuje.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 19, 'Ale díš mi: I proč se pak hněvá? nebo vůli jeho kdo odepřel?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 20, 'Nýbrž, ó člověče, kdo jsi ty, že odmlouváš Bohu? Zdaž hrnec dí hrnčíři: Pročs mne tak udělal?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 21, 'Zdaliž hrnčíř nemá moci nad hlinou, aby z jednostejného truple udělal jednu nádobu ke cti, a jinou ku potupě?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 22, 'Což pak, že Bůh, chtěje ukázati hněv, a oznámiti moc svou, snášel ve mnohé trpělivosti nádoby hněvu, připravené k zahynutí,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 23, 'A známé učiniti bohatství slávy své při nádobách milosrdenství, kteréž připravil k slávě?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 24, 'Kterýchž i povolal, totiž nás, netoliko z Židů, ale také i z pohanů,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 25, 'Jakož i skrze Ozé dí: Nazovu nelid svůj lidem svým, a nemilou milou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 26, 'A staneť se, že místo toho, kdež řečeno bylo jim: Nejste vy lid můj, tuť nazváni budou synové Boha živého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 27, 'Izaiáš pak volá nad Izraelem, řka: Byť pak byl počet synů Izraelských jako písek mořský, ostatkové spaseni budou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 28, 'Nebo pohubení učiní spravedlivé, a to jisté, pohubení zajisté učiní Pán na zemi, a to jisté.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 29, 'A jakož prvé pověděl Izaiáš: Byť byl Pán zástupů nepozůstavil nám semene, jako Sodoma učiněni bychom byli, a Gomoře byli bychom podobni.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 30, 'Což tedy díme? I to, že pohané, kteříž nenásledovali spravedlnosti, dosáhli spravedlnosti, a to spravedlnosti té, kteráž jest z víry;');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 31, 'Izrael pak následovav zákona spravedlnosti, k zákonu spravedlnosti nepřišel.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 32, 'Proč? Nebo ne z víry, ale jako z skutků zákona jí hledali. Urazili se zajisté o kámen urážky,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 33, 'Jakož psáno jest: Aj, kladu na Sionu kámen urážky a skálu pohoršení, a každý, kdož uvěří v něj, nebude zahanben.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 1, 'Bratří, příchylnost zajisté s zvláštní líbostí srdce mého jestiť k Izraelovi, i modlitba za něj k Bohu, aby spasen byl.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 2, 'Neboť jim svědectví vydávám, žeť horlivost Boží mají, ale ne podlé umění.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 3, 'Nebo neznajíce Boží spravedlnosti, a svou vlastní spravedlnost usilujíce vystaviti, spravedlnosti Boží nebyli poddáni.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 4, 'Konec zajisté zákona jest Kristus k ospravedlnění všelikému věřícímu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 5, 'Nebo Mojžíš píše o spravedlnosti, kteráž jest z zákona, pravě: Který by koli člověk činil ty věci, živ bude v nich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 6, 'Ta pak spravedlnost, kteráž jest z víry, takto praví: Neříkej v srdci svém: Kdo vstoupí na nebe? To jest Krista s výsosti svésti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 7, 'Aneb kdo sstoupí do propasti? To jest Krista z mrtvých vzbuditi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 8, 'Ale co dí? Blízko tebe jestiť slovo, v ústech tvých a v srdci tvém. Toť jest slovo to víry, kteréž kážeme:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 9, 'Vyznáš-li ústy svými Pána Ježíše, a srdcem svým uvěříš-li, že jej Bůh vzkřísil z mrtvých, spasen budeš.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 10, 'Srdcem se zajisté věří k spravedlnosti, ale ústy vyznání se děje k spasení.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 11, 'Nebo dí písmo: Všeliký, kdož věří v něj, nebude zahanben.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 12, 'Neníť zajisté rozdílu mezi Židem a Řekem; nebo tentýž Pán všech, bohatý jest ke všechněm vzývajícím jej.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 13, 'Každý zajisté, kdožkoli vzýval by jméno Páně, spasen bude.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 14, 'Ale kterak budou vzývati toho, v kteréhož neuvěřili? A kterak uvěří tomu, o němž neslyšeli? A kterak uslyší bez kazatele?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 15, 'A kterak kázati budou, jestliže nebudou posláni? Jakož psáno jest: Jak krásné nohy zvěstujících pokoj, zvěstujících dobré věci.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 16, 'Ale nevšickni uposlechli evangelium. Nebo Izaiáš praví: Pane, kdo uvěřil kázaní našemu?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 17, 'Tedy víra z slyšení, slyšení pak skrze slovo Boží.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 18, 'Ale pravímť: Zdaliž neslyšeli? Anobrž po vší zemi rozšel se zvuk jejich, a do končin okršlku země slova jejich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 19, 'Ale pravím: Zdaliž nepoznal Izrael? Ano první Mojžíš řekl: Já k závisti vás přivedu skrze národ ten, kterýž není národ; skrze národ nemoudrý k hněvu popudím vás.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 20, 'A Izaiáš směle dí: Nalezen jsem od těch, kteříž mne nehledali; zjeven jsem těm, kteříž se na mne neptali.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 21, 'Ale proti Izraelovi dí: Přes celý den roztahoval jsem ruce své k lidu nepovolnému a protivnému.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 1, 'Protož pravím: Zdaliž Bůh zavrhl lid svůj? Nikoli; nebo i já Izraelský jsem, z semene Abrahamova, z pokolení Beniaminova.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 2, 'Nezavrhlť Bůh lidu svého, kterýž předzvěděl. Zdali nevíte, co písmo praví o Eliášovi, kterak se modlí Bohu proti lidu Izraelskému, řka:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 3, 'Pane, proroky tvé zmordovali, a oltáře tvé rozkopali, já pak zůstal jsem sám, a i méť duše hledají?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 4, 'Ale co jemu dí odpověď Boží? Pozůstavil jsem sobě sedm tisíců mužů, kteříž neskláněli kolen před Bálem.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 5, 'Takť i nyní ostatkové podlé vyvolení milosti zůstali,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 6, 'A poněvadž z milosti, tedy ne z skutků, sic jinak milost již by nebyla milost. Pakli z skutků, již není milost, jinak skutek nebyl by skutek.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 7, 'Což tedy? Čeho hledá Izrael, toho nedošel, ale vyvolení došli toho, jiní pak zatvrzeni jsou,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 8, '(Jakož psáno jest: Dal jim Bůh ducha zkormoucení, oči aby neviděli, a uši, aby neslyšeli,) až do dnešního dne.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 9, 'A David dí: Budiž jim stůl jejich osídlem a pastmi a pohoršením i odplacením.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 10, 'Zatmětež se oči jejich, ať nevidí, a hřbet jejich vždycky shýbej.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 11, 'Pravím tedy: Tak-liž pak klesli, aby padli? Nikoli, ale jejich pádem spasení přišlo pohanům, aby je k závidění přivedl.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 12, 'A poněvadž pak jejich pád jest bohatství světa, a zmenšení jejich jest bohatství pohanů, čím více plnost jich?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 13, 'Vámť zajisté pravím pohanům, že jelikož jsem já apoštol pohanský, přisluhování své oslavuji,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 14, 'Zda bych jak k závidění vzbuditi mohl tělo mé, a k spasení přivesti některé z nich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 15, 'Nebo kdyžť zavržení jich jest smíření světa, co pak zase jich přijetí, než život z mrtvých?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 16, 'Poněvadž prvotiny svaté, takéť i těsto; a jestliť kořen svatý, i ratolesti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 17, 'Žeť jsou pak některé ratolesti vylomeny, a ty, byv planou olivou, vštípen jsi místo nich, a učiněn jsi účastník kořene i tučnosti olivy.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 18, 'Nechlub se proti ratolestem. Pakli se chlubíš, věz, že ne ty kořen neseš, ale kořen tebe.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 19, 'Pakli díš: Vylomeny jsou ratolesti, abych já byl vštípen,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 20, 'Dobře. Pro nevěru vylomeny jsou, ale ty věrou stojíš. Nebudiž vysokomyslný, ale boj se.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 21, 'Nebo poněvadž Bůh ratolestem přirozeným neodpustil, věz, žeť by ani tobě neodpustil.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 22, 'A protož viz dobrotivost i zůřivost Boží. K těm zajisté, kteříž padli, zůřivost, ale k tobě dobrotivost, ač budeš-li trvati v dobrotě. Sic jinak i ty vyťat budeš.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 23, 'Ano i oni, jestliže nezůstanou v nevěře, zase vštípeni budou. Mocenť jest zajisté Bůh zase vštípiti je.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 24, 'Nebo poněvadž ty vyťat jsi z přirozené plané olivy, a proti přirození vštípen jsi v dobrou olivu, čím více ti, kteříž podlé přirození jsou, vštípeni budou v svou vlastní olivu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 25, 'Neboť nechci, bratří, abyste nevěděli tohoto tajemství, (abyste nebyli sami u sebe moudří,) že zatvrdilost z částky přihodila se Izraelovi, dokudž by nevešla plnost pohanů.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 26, 'A takť všecken Izrael spasen bude, jakož psáno jest: Přijde z Siona vysvoboditel, a odvrátíť bezbožnosti od Jákoba.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 27, 'A tatoť bude smlouva má s nimi, když shladím hříchy jejich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 28, 'A tak s strany evangelium jsouť nepřátelé pro vás, ale podlé vyvolení jsou milí pro otce.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 29, 'Darů zajisté svých a povolání Bůh nelituje.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 30, 'Nebo jakož i vy někdy jste nebyli poslušni Boha, ale nyní milosrdenství jste došli pro jejich nevěru,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 31, 'Tak i oni nyní neuposlechli, aby pro učiněné vám milosrdenství i oni milosrdenství dosáhli.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 32, 'Zavřel zajisté Bůh všecky v nevěře, aby se nade všemi smiloval.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 33, 'Ó hlubokosti bohatství i moudrosti i umění Božího! Jak jsou nezpytatelní soudové jeho, a nevystižitelné cesty jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 34, 'Nebo kdo poznal mysl Páně? Aneb kdo jemu radil?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 35, 'Nebo kdo prvé dal jemu, a budeť mu odplaceno?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 36, 'Nebo z něho, a skrze něho, a v něm jsou všecky věci, jemuž sláva na věky. Amen.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 1, 'Protož prosím vás, bratří, skrze milosrdenství Boží, abyste vydávali těla svá v obět živou, svatou, Bohu libou, rozumnou službu svou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 2, 'A nepřipodobňujte se světu tomuto, ale proměňtež se obnovením mysli své, tak abyste zkusili, jaká by byla vůle Boží dobrá, libá a dokonalá.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 3, 'Neboť pravím (skrze milost, kteráž dána jest mi,) každému, kdož jest mezi vámi, aby nesmyslil více, než sluší smysliti, ale aby smyslil v středmosti, tak jakž komu Bůh udělil míru víry.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 4, 'Nebo jakož v jednom těle mnohé oudy máme, ale nemají všickni oudové jednostejného díla,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 5, 'Tak mnozí jedno tělo jsme v Kristu, a obzvláštně jedni druhých oudové.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 6, 'Ale majíce obdarování rozdílná podlé milosti, kteráž dána jest nám, buďto proroctví, to ať se koná podlé pravidla víry;');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 7, 'Buďto úřad, v přisluhování; buďto ten, kdož učí, v vyučování.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 8, 'Též kdo napomíná, v napomínání; ten, kdo rozdává, v upřímnosti; kdož předložen jest, v pilnosti; kdo milosrdenství činí, čiň to s ochotností.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 9, 'Milování buď bez pokrytství; v ošklivosti mějte zlé, připojeni jsouce k dobrému.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 10, 'Láskou bratrskou jedni k druhým nakloněni jsouce, poctivostí se vespolek předcházejte,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 11, 'V pracech neleniví, duchem vroucí, Pánu sloužíce,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 12, 'Nadějí se veselíce, v ssouženích trpěliví, na modlitbě ustaviční,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 13, 'V potřebách s svatými se zdělujíce, přívětivosti k hostem následujíce.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 14, 'Dobrořečte protivníkům svým, dobrořečte a nezlořečte.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 15, 'Radujte s radujícími, a plačte s plačícími.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 16, 'Buďte vespolek jednomyslní, ne vysoce o sobě smýšlejíce, ale k nízkým se nakloňujíce.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 17, 'Nebuďte opatrní sami u sebe. Žádnému zlého za zlé neodplacujte, opatrujíce dobré přede všemi lidmi,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 18, 'Jestliže jest možné, pokudž na vás jest, se všemi lidmi pokoj majíce,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 19, 'Ne sami sebe mstíce, nejmilejší, ale dejte místo hněvu; nebo psáno jest: Mně pomsta, já odplatím, praví Pán.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 20, 'A protož lační-li nepřítel tvůj, nakrm jej, a žízní-li, dej mu píti. Nebo to učině, uhlí řeřavé shrneš na hlavu jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 21, 'Nedej se přemoci zlému, ale přemáhej v dobrém zlé.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 13, 1, 'Každá duše vrchnostem poddána buď. Neboť není vrchnosti, jediné od Boha, a kteréž vrchnosti jsou, od Boha zřízené jsou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 13, 2, 'A protož kdož se vrchnosti protiví, Božímu zřízení se protiví; kteříž se pak protiví, odsouzení sobě dobudou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 13, 3, 'Nebo vrchnosti nejsou k strachu dobře činícím, ale zle činícím. Chceš-li se pak nebáti vrchnosti, čiň dobře, a budeš míti chválu od ní.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 13, 4, 'Boží zajisté služebník jest, tobě k dobrému. Pakli bys zle činil, boj se; neboť ne nadarmo nese meč. Boží zajisté služebník jest, mstitel zůřivý nad tím, kdož zle činí.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 13, 5, 'A protož náležíť poddánu býti, netoliko pro hněv, ale i pro svědomí.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 13, 6, 'Nebo proto i daň dáváte, že služebníci Boží jsou, pilnou práci o to samo vedouce.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 13, 7, 'Každému tedy, což jste povinni, dávejte. Komu daň, tomu daň; komu clo, tomu clo; komu bázeň, tomu bázeň; komu čest, tomu čest.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 13, 8, 'Žádnému nebývejte nic dlužni, než to, abyste se vespolek milovali. Nebo kdož miluje bližního, zákon naplnil,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 13, 9, 'Poněvadž to přikázaní: Nesesmilníš, nezabiješ, neukradneš, nepromluvíš křivého svědectví, nepožádáš, a jestli které jiné přikázaní, v tomto slovu se zavírá: Milovati budeš bližního svého jako sebe samého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 13, 10, 'Láska bližnímu zle neučiní, a protož plnost zákona jest láska.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 13, 11, 'A zvláště pak vidouce takovou příhodnost, žeť jest se nám již čas ze sna probuditi. Nyníť zajisté blíže nás jest spasení, nežli když jsme uvěřili.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 13, 12, 'Noc pominula, ale den se přiblížil. Odvrzmež tedy skutky temnosti, a oblecme se v odění světla.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 13, 13, 'Jakožto ve dne poctivě choďme, ne v hodování a v opilství, ne v smilstvích a v chlipnostech, ne v sváru a v závisti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 13, 14, 'Ale oblecte se v Pána Jezukrista, a nepečujte o tělo podlé žádosti jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 1, 'Mdlého pak u víře přijímejte ne k hádkám o otázkách.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 2, 'Nebo někdo věří, že může jísti všecko; jiný pak mdlý jsa, jí zelí.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 3, 'Ten kdož jí, nepokládej sobě za nic toho, kdož nejí; a kdo nejí, toho nepotupuj, kdož jí. Nebo Bůh přijal jej.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 4, 'Ty kdo jsi, abys tupil cizího služebníka? Však Pánu svému stojí, aneb padá. Budeť pak ustaven; mocen jest zajisté Bůh utvrditi jej.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 5, 'Nebo někdo rozsuzuje mezi dnem a dnem, a někdo soudí každý den. Jeden každý v svém smyslu ujištěn buď.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 6, 'Kdož dnů šetří, Pánu šetří; a kdo nešetří, Pánu nešetří. A kdo jí, Pánu jí, nebo děkuje Bohu; a kdož nejí, Pánu nejí, a děkuje Bohu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 7, 'Žádný zajisté z nás není sám sobě živ, a žádný sobě sám neumírá.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 8, 'Nebo buď že jsme živi, Pánu živi jsme; buď že mřeme, Pánu mřeme. A tak buď že jsme živi, buď že umíráme, Páně jsme.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 9, 'Na toť zajisté Kristus i umřel, i z mrtvých vstal, i ožil, aby nad živými i nad mrtvými panoval.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 10, 'Ty pak proč potupuješ bratra svého? Aneb také ty proč za nic pokládáš bratra svého? Však všickni staneme před stolicí Kristovou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 11, 'Psáno jest zajisté: Živť jsem já, praví Pán, žeť přede mnou bude klekati každé koleno, a každý jazyk vyznávati bude Boha.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 12, 'A takť jeden každý z nás sám za sebe počet vydávati bude Bohu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 13, 'Nesuďmež tedy více jedni druhých, ale toto raději rozsuzujte, abyste nekladli úrazu neb pohoršení bratru.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 14, 'Vímť a ujištěn jsem v Pánu Ježíši, žeť nic nečistého není samo z sebe; než tomu, kdož tak soudí, že by nečisté bylo, jemuť nečisté jest.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 15, 'Ale bývá-liť rmoucen bratr tvůj pro pokrm, již nechodíš podlé lásky. Nepřivozujž k zahynutí pokrmem svým toho, za kteréhož Kristus umřel.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 16, 'Nebudiž tedy v porouhání dáno dobré vaše.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 17, 'Království zajisté Boží není pokrm a nápoj, ale spravedlnost a pokoj a radost v Duchu svatém.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 18, 'Nebo kdož v tom slouží Kristu, milý jest Bohu a lidem příjemný.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 19, 'Protož následujme toho, což jest ku pokoji a k vzdělání společnému.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 20, 'Nekaziž pro pokrm díla Božího. Všecko zajisté čisté jest, ale zlé jest člověku, kterýž jí s pohoršením.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 21, 'Dobré jest nejísti masa a nepiti vína, ani na čem se koli uráží bratr tvůj, neb horší, aneb zemdlívá.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 22, 'Ty víru máš? Mějž ji sám u sebe před Bohem. Blahoslavený, kdož nesoudí sebe samého v tom, což oblibuje.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 23, 'Ale kdož pak rozpakuje se, kdyby jedl, potupen jest, nebo ne z víry jí. A cožkoli není z víry, hřích jest.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 1, 'Povinniť jsme pak my silní mdloby nemocných snášeti, a ne sami sobě se líbiti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 2, 'A protož jeden každý z nás bližnímu se lib k dobrému pro vzdělání.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 3, 'Nebo i Kristus ne sám se sobě líbil, ale jakož psáno jest: Hanění hanějících tebe připadla na mne.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 4, 'Nebo kteréžkoli věci napsány jsou, k našemu naučení napsány jsou, abychom skrze snášelivost a potěšení písem naději měli.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 5, 'Bůh pak snášelivosti a potěšení dejž vám býti jednomyslnými vespolek podlé Jezukrista,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 6, 'Abyste jednomyslně jedněmi ústy oslavovali Boha a Otce Pána našeho Jezukrista.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 7, 'Protož přijímejte se vespolek, jakož i Kristus přijal nás v slávu Boží.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 8, 'Neboť pravím, že Kristus Ježíš byl služebníkem obřízky pro Boží pravost, aby potvrdil slibů otcům,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 9, 'A aby pohané z milosrdenství slavili Boha, jakož psáno jest: Protož vyznávati tebe budu mezi pohany, a jménu tvému plésati budu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 10, 'A opět dí: Veselte se pohané s lidem jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 11, 'A opět: Chvalte Hospodina všickni národové, a velebtež ho všickni lidé.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 12, 'A opět Izaiáš dí: Budeť kořen Jesse, a v tom, kterýž povstane, aby panoval nad pohany, pohané doufati budou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 13, 'Bůh pak naděje naplňujž vás všelikou radostí a pokojem u víře, abyste se rozhojnili v naději skrze moc Ducha svatého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 14, 'Jist jsem zajisté, bratří moji, i já také o vás, že i vy jste plní dobroty, naplněni jsouce všelikou známostí, tak že se i napomínati můžete vespolek.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 15, 'A však psal jsem vám, bratří, poněkud směle, jako napomínaje vás, podlé milosti, kteráž jest mi dána od Boha,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 16, 'K tomu abych byl služebníkem Ježíše Krista mezi pohany, slouže evangelium Božímu, aby byla obět pohanů vzácná, posvěcena jsuci skrze ducha svatého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 17, 'Mám se tedy čím chlubiti v Kristu Ježíši, v Božích věcech.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 18, 'Neboť bych nesměl mluviti toho, čehož by skrze mne neučinil Kristus, ku poslušenství pohanů, slovem i skutkem,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 19, 'V moci divů a zázraků, v síle Ducha Božího, tak že jsem od Jeruzaléma vůkol až k Illyrické zemi naplnil evangelium Kristovým,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 20, 'A to tak byv žádostiv kázati evangelium, kdež ani jmenován nebyl Kristus, abych na cizí základ nestavěl,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 21, 'Ale jakož psáno jest: Kterýmž není zvěstováno o něm, uzří, a ti, kteříž neslýchali, srozumějí.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 22, 'A tímť jest mi mnohokrát překaženo přijíti k vám.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 23, 'Nyní pak nemaje již více místa v těchto krajinách, a žádost maje přijíti k vám od mnoha let,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 24, 'Kdyžkoli půjdu do Hišpanie, přijdu k vám. Mámť zajisté naději, že tudy jda, uzřím vás, a že vy mne provodíte tam, a však až bych prvé u vás poněkud pobyl.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 25, 'Nyní pak beru se do Jeruzaléma, službu čině svatým.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 26, 'Nebo za dobré se vidělo Macedonským a Achaiským, aby zbírku nějakou učinili na chudé svaté, kteříž jsou v Jeruzalémě.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 27, 'Takť sobě to oblíbili, a také povinni jsou jim to. Nebo poněvadž duchovním věcem jejich obcovali pohané, povinniť jsou jim také sloužiti tělesnými.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 28, 'A protož když to vykonám, a jim odvedu užitek ten, půjduť skrze vás do Hišpanie.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 29, 'A vímť, že když přijdu k vám, v hojnosti požehnání evangelium Kristova přijdu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 30, 'Prosímť pak vás, bratří, skrze Pána našeho Jezukrista a skrze lásku Ducha, abyste spolu se mnou modlili se za mne Bohu snažně,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 31, 'Abych vysvobozen byl od protivníků v Judstvu, a aby služba tato má příjemná byla svatým v Jeruzalémě,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 32, 'Abych k vám bohdá s radostí přišel, a s vámi poodpočinul.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 33, 'Bůh pak pokoje se všemi vámi. Amen.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 1, 'Poroučímť pak vám Fében, sestru naši, služebnici církve Cenchrenské,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 2, 'Abyste ji přijali v Pánu, tak jakž sluší na svaté, a abyste jí pomocni byli, jestliže by vás v čem potřebovala. Nebo i ona mnohým hostem ochotně posluhovala, až i mně také.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 3, 'Pozdravte Priscilly a Akvily, pomocníků mých v Kristu Ježíši,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 4, 'Kteříž pro můj život svých vlastních hrdel nasadili, jimž ne já sám toliko děkuji, ale i všecky církve pohanské,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 5, 'I domácího jejich shromáždění. Pozdravte mého milého Epéneta, kterýž jest prvotiny Achaie v Kristu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 6, 'Pozdravte Marie, kteráž mnoho práce měla s námi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 7, 'Pozdravte Andronika a Junia, příbuzných mých a spoluvězňů mých, kteříž jsou vzácní u apoštolů, a kteříž přede mnou byli v Kristu Ježíši.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 8, 'Pozdravte Amplia mně v Pánu milého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 9, 'Pozdravte Urbana, pomocníka našeho v Kristu, a Stachyna mého milého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 10, 'Pozdravte Apella zkušeného v Kristu. Pozdravte domácích Aristobulových.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 11, 'Pozdravte Herodiona, příbuzného mého. Pozdravte domácích Narcissových, kteříž jsou v Pánu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 12, 'Pozdravte Tryfény a Tryfózy, kteréž práci vedou v Pánu. Pozdravte Persidy milé, kteráž mnoho pracovala v Pánu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 13, 'Pozdravte Rufa, zvláštního v Pánu, a matky jeho i mé.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 14, 'Pozdravte Asynkrita, Flegonta, Hermy, Patroba, Hermena, i bratří, kteříž jsou s nimi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 15, 'Pozdravte Filologa i Julie, Nerea a sestry jeho, i Olympa i všech svatých, kteříž jsou s nimi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 16, 'Pozdravte sebe vespolek v políbení svatém. Pozdravujíť vás církve Kristovy.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 17, 'Prosímť pak vás, bratří, abyste šetřili těch, kteříž různice a pohoršení činí, na odpor učení tomu, kterémuž jste vy se naučili, a varujte se jich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 18, 'Nebo takoví Pánu našemu Ježíši Kristu neslouží, ale svému břichu; a lahodnými řečmi a pochlebenstvím svodí srdce prostých.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 19, 'Nebo vaše poslušenství všech došlo. A protož raduji se z vás. Než chciť, abyste byli moudří k dobrému, a prostí k zlému.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 20, 'Bůh pak pokoje potře satana pod nohy vaše brzo. Milost Pána našeho Jezukrista s vámi. Amen.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 21, 'Pozdravují vás Timoteus, pomocník můj, a Lucius, a Jázon, a Sozipater, příbuzní moji.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 22, 'Pozdravuji vás v Pánu já Tercius, kterýž jsem psal tento list.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 23, 'Pozdravuje vás Gáius, hospodář můj i vší církve. Pozdravuje vás Erastus, důchodní písař městský, a Kvartus bratr.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 24, 'Milost Pána našeho Jezukrista se všemi vámi. Amen.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 25, 'Tomu pak, kterýž může vás utvrditi podlé evangelium mého a kázaní Ježíše Krista, podlé zjevení tajemství od časů věčných skrytého,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 26, 'Nyní pak zjeveného i skrze písma prorocká, podlé poručení věčného Boha, ku poslušenství víry všechněm národům oznámeného,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 27, 'Tomu samému moudrému Bohu sláva skrze Jezukrista na věky. Amen.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 1, 'Pavel, povolaný apoštol Ježíše Krista, skrze vůli Boží, a bratr Sostenes,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 2, 'Církvi Boží, kteráž jest v Korintu, posvěceným v Kristu Ježíši, povolaným svatým, spolu se všechněmi, kteříž vzývají jméno Pána našeho Jezukrista na všelikém místě, i jejich i našem:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 3, 'Milost vám a pokoj od Boha Otce našeho a Pána Jezukrista.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 4, 'Děkuji Bohu svému vždycky z vás pro tu milost Boží, kteráž dána jest vám v Kristu Ježíši,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 5, 'Že všemi věcmi obohaceni jste v něm, každým slovem i všelikým uměním,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 6, 'Jakož svědectví Kristovo upevněno jest mezi vámi,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 7, 'Tak že, nemáte žádného nedostatku v žádném daru, očekávajíce zjevení Pána našeho Jezukrista,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 8, 'Kterýž i utvrdí vás až do konce bez ouhony ke dni Pána našeho Jezukrista.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 9, 'Věrnýť jest Bůh, skrze něhož povoláni jste k účastenství Syna jeho Jezukrista, Pána našeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 10, 'Prosímť pak vás, bratří, skrze jméno Pána našeho Jezukrista, abyste jednostejně mluvili všickni, a aby nebylo mezi vámi roztržek, ale buďte spojeni jednostejnou myslí, a jednostejným smyslem.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 11, 'Nebo oznámeno jest mi o vás, bratří moji, od domácích Chloe, že by mezi vámi byly různice.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 12, 'Míním pak toto, že jeden každý z vás říká: Já jsem Pavlův, já Apollův, já Petrův, já pak Kristův.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 13, 'Rozdělen-liž jest Kristus? Zdali Pavel ukřižován jest za vás? aneb zdali jste ve jménu Pavlovu pokřtěni byli?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 14, 'Děkuji Bohu, že jsem žádného z vás nekřtil, než Krispa a Gáia,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 15, 'Aby někdo neřekl, že jsem ve jménu svém křtil.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 16, 'Křtilť jsem také i Štěpánovu čeled. Více nevím, abych koho jiného křtil.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 17, 'Nebo neposlal mne Kristus křtíti, ale evangelium kázati, ne v moudrosti řeči, aby nebyl vyprázdněn kříž Kristův.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 18, 'Nebo slovo kříže těm, kteříž hynou, bláznovstvím jest, ale nám, kteříž spasení dosahujeme, moc Boží jest.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 19, 'Nebo psáno jest: Zahladím moudrost moudrých, a opatrnost opatrných zavrhu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 20, 'Kde jest moudrý? A kde učený? A kde chytrák tohoto světa? Zdaliž Bůh neobrátil moudrosti tohoto světa v bláznovství?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 21, 'Nebo když v moudrosti Boží svět nepoznal skrze moudrost Boha, zalíbilo se Bohu skrze bláznové kázaní spasiti věřící,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 22, 'Poněvadž i Židé zázraků žádají, i Řekové hledají moudrosti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 23, 'Myť pak kážeme Krista ukřižovaného, Židům zajisté pohoršení, a Řekům bláznovství,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 24, 'Ale povolaným i Židům i Řekům Krista, Boží moc a Boží moudrost.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 25, 'Nebo to bláznovství Boží jest moudřejší nežli lidé, a mdloba Boží jest silnější než lidé.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 26, 'Vidíte zajisté povolání své, bratří, že nemnozí moudří podlé těla, nemnozí mocní, nemnozí urození.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 27, 'Ale což bláznivého jest u světa, to vyvolil Bůh, aby zahanbil moudré, a to, což jest u světa mdlé, vyvolil Bůh, aby zahanbil silné.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 28, 'A neurozené u světa a za nic položené vyvolil Bůh, anobrž kteréž nejsou, aby ty věci, kteréž jsou, zahladil,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 29, 'Proto aby se nechlubilo před oblíčejem jeho žádné tělo.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 30, 'Vy pak jste z něho v Kristu Ježíši, kterýž učiněn jest nám moudrost od Boha, i spravedlnost, i posvěcení, i vykoupení,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 31, 'Aby, jakož jest napsáno, kdo se chlubí, v Pánu se chlubil.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 1, 'I já přišed k vám, bratří, nepřišel jsem s důstojností řeči neb moudrosti, zvěstuje vám svědectví Boží.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 2, 'Nebo tak jsem usoudil nic jiného neuměti mezi vámi, nežli Ježíše Krista, a to toho ukřižovaného.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 3, 'A byl jsem já u vás v mdlobě, a v bázni, i v strachu mnohém.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 4, 'A řeč má a kázaní mé nebylo v slibných lidské moudrosti řečech, ale v dokázaní Ducha a moci,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 5, 'Aby víra vaše nebyla na moudrosti lidské založena, ale na moci Boží.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 6, 'Moudrost pak mluvíme mezi dokonalými, ale moudrost ne tohoto světa, ani knížat světa tohoto, kteráž hynou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 7, 'Ale mluvíme tu moudrost Boží v tajemství skrytou, kterouž Bůh předuložil před věky k slávě naší,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 8, 'Jíž žádný z knížat světa tohoto nepoznal. Nebo kdyby byli poznali, nebyliť by Pána slávy ukřižovali.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 9, 'Ale jakož psáno jest: Čeho oko nevídalo, ani ucho neslýchalo, ani na srdce lidské nevstoupilo, co připravil Bůh těm, kteříž jej milují.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 10, 'Nám pak Bůh zjevil skrze Ducha svého. Nebo Duch zpytuje všecky věci, i hlubokosti Božské.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 11, 'Nebo kdo z lidí ví, co jest v člověku, jediné duch člověka, kterýž jest v něm? Takť i Božích věcí nezná žádný, jediné Duch Boží.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 12, 'My pak nepřijali jsme ducha světa, ale Ducha toho, kterýž jest z Boha, abychom věděli, které věci od Boha darovány jsou nám.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 13, 'O nichž i mluvíme ne těmi slovy, jimž lidská moudrost učí, ale kterýmž vyučuje Duch svatý, duchovním to, což duchovního jest, přivlastňujíce.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 14, 'Ale tělesný člověk nechápá těch věcí, kteréž jsou Ducha Božího; nebo jsou jemu bláznovství, aniž jich může poznati, proto že ony duchovně mají rozsuzovány býti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 15, 'Duchovní pak rozsuzuje všecko, sám pak od žádného nebývá souzen.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 16, 'Nebo kdo pozná mysl toho Pána, kterýž jej vyučovati bude? My pak mysl Kristovu máme.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 1, 'A já, bratří, nemohl jsem vám mluviti jako duchovním, ale jako tělesným, jako maličkým v Kristu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 2, 'Mlékem jsem vás živil, a ne pokrmem; nebo jste ještě nemohli, ano i nyní ještě nemůžete.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 3, 'Ještě zajisté tělesní jste. Nebo poněvadž jest mezi vámi nenávist, svárové a různice, zdaž ještě tělesní nejste, a podlé člověka nechodíte?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 4, 'Nebo když někdo říká: Já jsem Pavlův, jiný pak: Já Apollův, zdaliž nejste tělesní?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 5, 'Kdo tedy jest Pavel, kdo Apollo, než služebníci, skrze něž jste uvěřili, a jakž jednomu každému dal Pán?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 6, 'Jáť jsem štípil, Apollo zaléval, ale Bůh dal zrůst.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 7, 'A protož aniž ten, kdož štěpuje, jest něco, ani ten, kdož zalévá, ale Bůh, kterýž zrůst dává.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 8, 'Ten pak, kdož štěpuje, a ten, kdož zalévá, jedno jsou, a však jeden každý svou vlastní odplatu vezme podlé své práce.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 9, 'Božíť jsme zajisté pomocníci, Boží rolí, Boží vzdělání jste.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 10, 'Podlé milosti Boží sobě dané, jako moudrý stavitel, základ jsem založil, jiný pak na něm staví. Ale jeden každý viz, jak na něm staví.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 11, 'Nebo základu jiného žádný položiti nemůž, mimo ten, kterýž položen jest, jenž jest Ježíš Kristus.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 12, 'Staví-liť pak kdo na ten základ zlato, stříbro, kamení drahé, dříví, seno, strniště,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 13, 'Jednohoť každého dílo zjeveno bude. Den zajisté to okáže; nebo v ohni zjeví se, a jednoho každého dílo, jaké by bylo, oheň zprubuje.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 14, 'Zůstane-liť čí dílo, kteréž na něm stavěl, vezme odplatu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 15, 'Pakliť čí dílo shoří, vezme škodu, ale sám spasen bude, a však tak, jako skrze oheň.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 16, 'Zdaliž nevíte, že chrám Boží jste, a Duch Boží v vás přebývá?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 17, 'Jestližeť kdo chrámu Božího poškvrňuje, tohoť zatratí Bůh; nebo chrám Boží svatý jest, jenž jste vy.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 18, 'Žádný sám sebe nesvoď. Zdá-li se komu z vás, že jest moudrý na tomto světě, budiž bláznem, aby byl učiněn moudrým.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 19, 'Moudrost zajisté světa tohoto bláznovství jest u Boha. Nebo psáno jest: Kterýž lapá moudré v chytrosti jejich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 20, 'A opět: Znáť Pán přemyšlování moudrých, že jsou marná.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 21, 'A tak nechlub se žádný lidmi; nebo všecky věci vaše jsou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 22, 'Buď Pavel, buď Apollo, buď Petr, buď svět, buď život, buď smrt, buď přítomné věci, buďto budoucí, všecko jest vaše,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 23, 'Vy pak Kristovi, a Kristus Boží.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 1, 'Tak o nás smýšlej člověk, jako o služebnících Kristových a šafářích tajemství Božích.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 2, 'Dále pak vyhledává se při šafářích, aby každý věrný nalezen byl.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 3, 'Mně pak to za nejmenší jest, abych od vás souzen byl, aneb od lidského soudu; nýbrž ani sám sebe soudím.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 4, 'Nebo ač do sebe nic nevím, však ne skrze to jsem spravedliv; nebo ten, ješto mne soudí, Pán jest.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 5, 'Protož nesuďte nic před časem, až by přišel Pán, kterýž i osvítí to, což skrytého jest ve tmě, a zjeví rady srdcí. A tehdážť bude míti chválu jeden každý od Boha.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 6, 'Tyto pak věci, bratří, v podobenství obrátil jsem na sebe a na Apollo pro vás, abyste se na nás učili nad to, což psáno jest, výše nesmýšleti, abyste jeden pro druhého nenadýmali se proti někomu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 7, 'Nebo kdož tě soudí? A co máš, ješto bys nevzal? A když jsi vzal, proč se chlubíš, jako bys nevzal?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 8, 'Již jste nasyceni, již jste zbohatli, bez nás kralujete. Ale ó byste kralovali, abychom i my spolu s vámi kralovali.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 9, 'Za to mám jistě, že nás Bůh apoštoly poslední okázal jako k smrti oddané; nebo učiněni jsme divadlo tomuto světu, i andělům, i lidem.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 10, 'My blázni pro Krista, ale vy opatrní v Kristu; my mdlí, vy pak silní; vy slavní, ale my opovržení.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 11, 'Až do tohoto času i lačníme, i žízníme, i nahotu trpíme, i poličkováni býváme, i místa nemáme,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 12, 'A pracujeme, dělajíce rukama vlastníma. Uhaněni jsouce, dobrořečíme; protivenství trpíce, snášíme.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 13, 'Když se nám rouhají, modlíme se; jako smeti tohoto světa učiněni jsme, povrhel u všech, až posavad.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 14, 'Ne proto, abych vás zahanbil, píši toto, ale jako svých milých synů napomínám.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 15, 'Nebo byste pak deset tisíc pěstounů měli v Kristu, však proto nemnoho otců. Nebo v Kristu Ježíši skrze evangelium já jsem vás zplodil.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 16, 'Protož prosím vás, buďte následovníci moji.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 17, 'Pro tu příčinu poslal jsem vám Timotea, kterýž jest syn můj milý a věrný v Pánu. Tenť vám připomínati bude, které jsou cesty mé v Kristu, jakž všudy v každé církvi učím.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 18, 'Rovně jako bych neměl k vám přijíti, naduli se někteří.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 19, 'Ale přijduť k vám brzo, bude-li Pán chtíti, a poznám ne řeč těch nadutých, ale moc.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 20, 'Neboť ne záleží v řeči království Boží, ale v moci.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 21, 'Co chcete? S metlou-li abych přišel k vám, čili s láskou, a s duchem tichosti?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 5, 1, 'Naprosto slyšeti, že jest mezi vámi smilstvo, a to takové smilstvo, jakéž se ani mezi pohany nejmenuje, aby někdo měl manželku otcovu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 5, 2, 'A vy nadutí jste, než byste raději rmoutili se, aby vyvržen byl z prostředku vás ten, kdož takový skutek spáchal.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 5, 3, 'Já zajisté, ač vzdálený tělem, ale přítomný duchem, již jsem to usoudil, jako bych přítomen byl, abyste toho, kterýž to tak spáchal,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 5, 4, 'Ve jménu Pána našeho Jezukrista sejdouce se spolu, i s mým duchem, s mocí Pána našeho Jezukrista,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 5, 5, 'Vydali takového satanu k zahubení těla, aby duch spasen byl v den Pána Ježíše.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 5, 6, 'Neníť dobrá chlouba vaše. Zdaliž nevíte, že maličko kvasu všecko těsto nakvašuje?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 5, 7, 'Vyčisťtež tedy starý kvas, abyste byli nové zadělání, jakož jste nenakvašení. Neboť jest Beránek náš velikonoční za nás obětován, Kristus.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 5, 8, 'A protož hodujmež ne v kvasu starém, ani v kvasu zlosti a nešlechetnosti, ale v přesnicích upřímnosti a pravdy.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 5, 9, 'Psal jsem vám v listu, abyste se nesměšovali s smilníky.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 5, 10, 'Ale nevšelijak s smilníky tohoto světa, neb s lakomci, neb s dráči, aneb s modláři, sic jinak musili byste z tohoto světa vyjíti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 5, 11, 'Nyní pak psal jsem vám, abyste se nesměšovali, kdyby kdo, maje jméno bratr, byl smilník, neb lakomec, neb modlář, neb zlolejce, neb opilec, neb dráč. S takovým ani nejezte.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 5, 12, 'Nebo proč já mám i ty, kteříž jsou vně, souditi? Však ty, kteříž jsou vnitř, vy soudíte.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 5, 13, 'Ty pak, kteříž jsou vně, Bůh soudí. Vyvrztež tedy toho zlého sami z sebe.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 1, 'Smí někdo z vás, maje při s druhým, souditi se před nepravými, a ne před svatými?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 2, 'Nevíte-liž, že svatí svět souditi budou? I poněvadž od vás souzen býti má svět, kterakž nehodni jste těch nejmenších věcí rozsuzovati?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 3, 'Zdaliž nevíte, že anděly souditi budeme? Co pak tyto časné věci?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 4, 'Protož když byste měli míti soud o tyto časné věci, těmi, kteříž nejzadnější jsou v církvi, soud osaďte.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 5, 'K zahanbeníť vašemu to pravím. Tak-liž není mezi vámi moudrého ani jednoho, kterýž by mohl rozsouditi mezi bratřími svými?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 6, 'Ale bratr s bratrem soudí se, a to před nevěřícími?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 7, 'Již tedy konečně nedostatek mezi vámi jest, že soudy máte mezi sebou. Proč raději křivdy netrpíte? Proč raději škody nebéřete?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 8, 'Nýbrž vy křivdu činíte, a k škodě přivodíte, a to bratří své.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 9, 'Zdaliž nevíte, že nespravedliví dědictví království Božího nedosáhnou? Nemylte se, ani smilníci, ani modláři, ani cizoložníci, ani měkcí, ani samcoložníci,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 10, 'Ani zloději, ani lakomci, ani opilci, ani zlolejci, ani dráči dědictví království Božího nedůjdou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 11, 'A takoví jste někteří byli, ale obmyti jste, ale posvěceni jste, ale ospravedlněni jste ve jménu Pána Jezukrista a skrze Ducha Boha našeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 12, 'Všecko mi sluší, ale ne všecko prospívá; všecko mi sluší, ale jáť žádné z těch věcí v moc nebudu podmaněn.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 13, 'Pokrmové břichu, a břicho pokrmům; Bůh pak i břicho i pokrmy zkazí. Ale tělo ne smilstvu, ale Pánu, a Pán tělu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 14, 'Bůh pak i Pána vzkřísil, i nás také vzkřísí mocí svou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 15, 'Nevíte-liž, že těla vaše jsou oudové Kristovi? Což tedy vezma oudy Kristovy, učiním je oudy nevěstky? Odstup to.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 16, 'Zdaliž nevíte, že kdož se připojuje k nevěstce, jedno tělo jest s ní? Nebo dí: Budou dva jedno tělo.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 17, 'Ten pak, kdož se připojuje Pánu, jeden duch jest s ním.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 18, 'Utíkejte smilstva. Všeliký hřích, kterýžkoli učinil by člověk, kromě těla jest, ale kdož smilní, ten proti svému vlastnímu tělu hřeší.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 19, 'Zdaliž nevíte, že tělo vaše jest chrám Ducha svatého v vás? Kteréhož máte od Boha, a nejste sami svoji.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 20, 'Nebo koupeni jste za mzdu. Oslavujtež tedy Boha tělem svým i duchem svým, kteréžto věci Boží jsou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 1, 'S strany pak toho, o čemž jste mi psali, dobréť by bylo člověku ženy se nedotýkati.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 2, 'Ale z příčiny smilstva, jeden každý manželku svou měj, a jedna každá měj muže svého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 3, 'Muž k ženě povinnou přívětivost prokazuj, podobně též i žena k muži.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 4, 'Žena svého vlastního těla v moci nemá, ale muž; též podobně i muž těla svého vlastního v moci nemá, ale žena.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 5, 'Neoklamávejte jeden druhého, leč by to bylo z společného svolení na čas, abyste se uprázdnili ku postu a k modlitbě; a zase spolu se sejděte, aby vás nepokoušel satan pro nezdrželivost vaši.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 6, 'Ale totoť pravím podlé dopuštění, ne podlé rozkazu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 7, 'Nebo chtěl bych, aby všickni lidé tak byli jako já, ale jeden každý svůj vlastní dar od Boha má, jeden tak a jiný jinak.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 8, 'Pravím pak neženatým a vdovám: Dobré jest jim, zůstali-li by tak jako já.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 9, 'Pakliť se nemohou zdržeti, nechažť v stav manželský vstoupí; nebo lépe jest v stav manželský vstoupiti nežli páliti se.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 10, 'Manželům pak přikazuji ne já, ale Pán, řka: Manželko od muže neodcházej.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 11, 'Pakliť by odešla, zůstaniž nevdaná, aneb smiř se s mužem. Tolikéž muži nepropouštěj ženy.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 12, 'Jiným pak pravím já, a ne Pán: Má-li který bratr manželku nevěřící, a ta povoluje býti s ním, nepropouštějž jí.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 13, 'A má-li která žena muže nevěřícího, a on chce býti s ní, nepropouštěj ho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 14, 'Posvěcenť jest zajisté nevěřící muž pro ženu, a žena nevěřící posvěcena jest pro muže; sic jinak děti vaši nečistí by byli, ale nyní svatí jsou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 15, 'Pakliť nevěřící odjíti chce, nechť jde. Neníť manem bratr neb sestra v takových věcech, ale ku pokoji povolal nás Bůh.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 16, 'A kterak ty víš, ženo, získáš-li muže svého? Aneb co ty víš, muži, získáš-li ženu?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 17, 'Ale jakž jednomu každému odměřil Bůh, a jakž jednoho každého povolal Pán, tak choď. A takť ve všech církvech řídím.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 18, 'Obřezaný někdo povolán jest? Neuvodiž na sebe neobřízky. V neobřízce někdo povolán jest? Neobřezuj se.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 19, 'Obřízka nic není, též neobřízka nic není, ale zachovávání přikázaní Božích.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 20, 'Jeden každý v tom povolání, v němž povolán jest, zůstávej.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 21, 'Služebníkem povolán jsi? Nedbej na to. Pakli bys mohl býti svobodný, raději toho užívej.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 22, 'Nebo kdož jest v Pánu povolán služebníkem, osvobozený jest Páně. Též podobně kdož jest povolán svobodný, služebník jest Kristův.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 23, 'Za mzdu koupeni jste, nebuďtež služebníci lidští.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 24, 'Jeden každý jakž povolán jest, bratří, v tom zůstávej před Bohem.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 25, 'O pannách pak přikázaní Páně nemám, ale však radu dávám, jako ten, jemuž z milosrdenství svého Pán dal věrným býti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 26, 'Za toť pak mám, že jest to dobré pro nastávající potřebu, totiž že jest dobré člověku tak býti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 27, 'Přivázáns k ženě? Nehledej rozvázání. Jsi prost od ženy? Nehledej ženy.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 28, 'Pakli bys se i oženil, nezhřešils, a vdala-li by se panna, nezhřešila; ale trápení těla míti budou takoví; jáť pak vám odpouštím.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 29, 'Ale totoť pravím, bratří, poněvadž čas ostatní jest ukrácený, aby i ti, kteříž mají ženy, byli, jako by jich neměli,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 30, 'A kteříž plačí, jako by neplakali, a kteříž radují se, jako by se neradovali, a kteříž kupují, jako by nevládli,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 31, 'A kteříž užívají tohoto světa, jako by neužívali. Neboť pomíjí způsob tohoto světa.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 32, 'Chciť pak, abyste vy bez pečování byli. Nebo kdo ženy nemá, pečuje o to, což jest Páně, kterak by se líbil Pánu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 33, 'Ale kdo se oženil, pečuje o věci tohoto světa, jak by se líbil ženě.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 34, 'Rozdílnéť jsou žena a panna. Nevdaná pečuje o to, což jest Páně, aby byla svatá i tělem i duchem, ale vdaná pečuje o věci tohoto světa, kterak by se líbila muži.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 35, 'Totoť pak k vašemu dobrému pravím, ne abych na vás osídlo uvrhl, ale abyste slušně a případně Pána se přídrželi, bez všeliké roztržitosti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 36, 'Pakli kdo za neslušnou věc své panně pokládá pomíjení času k vdání, a tak by se státi mělo, učiň, jakžkoli chce, nezhřeší. Nechažť ji vdá.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 37, 'Ale kdož se pevně ustavil v srdci, a není mu toho nouze, ale v moci má svou vlastní vůli, a to uložil v srdci svém, aby choval pannu svou, dobře činí.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 38, 'A tak ten, kdož vdává, dobře činí, ale kdo nevdává, lépe činí.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 39, 'Žena přivázána jest zákonem dotud, dokudž její muž živ jest. Pakli by umřel muž její, svobodná jest; můž se vdáti, za kohož chce, toliko v Pánu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 40, 'Ale blahoslavenější jest, zůstala-li by tak, podlé mého soudu. Mámť pak za to, žeť i já mám Ducha Božího.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 8, 1, 'V těch pak věcech, kteréž modlám obětovány bývají, víme, že všickni známost máme. A známost nadýmá, ale láska vzdělává.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 8, 2, 'Zdá-li se pak komu, že něco umí, ještě nic nepoznal, tak jakž by měl znáti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 8, 3, 'Ale jestliže kdo miluje Boha, tenť jest vyučen od něho,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 8, 4, 'A protož o pokrmích, kteříž se modlám obětují, víme, že modla na světě nic není, a že není jiného žádného Boha než jeden.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 8, 5, 'Nebo ačkoli jsou někteří, ješto slovou bohové, i na nebi i na zemi, (jakož jsou mnozí bohové, a páni mnozí,)');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 8, 6, 'Ale my máme jediného Boha Otce, z něhož všecko, a my v něm, a jednoho Pána Ježíše Krista, skrze něhož všecko, i my skrze něho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 8, 7, 'Ale ne ve všechť jest to umění. Nebo někteří s svědomím pro modlu až do dnes jako modlám obětované jedí, a svědomí jejich, jsuci mdlé, poškvrňuje se.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 8, 8, 'Nečiníť pak nás pokrm vzácných Bohu. Nebo budeme-li jísti, nic tím lepší nebudeme, a nebudeme-li jísti, nic horší nebudeme.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 8, 9, 'Ale vizte, aťby snad ta vaše moc nebyla k urážce mdlým.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 8, 10, 'Nebo uzří-li kdo tebe, majícího známost, a ty sedíš při pokrmu modlám obětovaném, zdaliž svědomí toho, kterýž jest mdlý, nebude přivedeno k tomu, aby také jedl modlám obětované?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 8, 11, 'I zahyne pro to tvé vědění bratr mdlý, za kteréhož Kristus umřel.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 8, 12, 'A tak hřešíce proti bratřím, a urážejíce svědomí jejich mdlé, proti Kristu hřešíte.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 8, 13, 'A protož jestližeť pohoršuje pokrm bratra mého, nebudu jísti masa na věky, abych nezhoršil bratra svého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 1, 'Zdaliž nejsem apoštol? Zdaliž nejsem svobodný? Zdaliž jsem Jezukrista Pána našeho neviděl? Zdaliž vy nejste práce má v Pánu?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 2, 'Bychť pak jiným nebyl apoštolem, tedy vám jsem; nebo pečet mého apoštolství vy jste v Pánu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 3, 'Odpověd má před těmi, kteříž mne soudí, ta jest:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 4, 'Zdaliž nemáme moci jísti a píti?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 5, 'Zdaliž nemáme moci sestry ženy při sobě míti, jako i jiní apoštolé, i bratří Páně, i Petr?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 6, 'Zdaliž sám já a Barnabáš nemáme moci díla zanechati?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 7, 'I kdo bojuje kdy na svůj náklad? Kdo štěpuje vinici, a ovoce jejího nejí? Aneb kdo pase stádo, a mléka od stáda nejí?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 8, 'Zdali podlé člověka to pravím? Zdaliž i zákon toho nepraví?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 9, 'Nebo v zákoně Mojžíšově psáno jest: Nezavížeš úst volu mlátícímu. I zdali Bůh o voly pečuje?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 10, 'Čili naprosto pro nás to praví? Pro násť jistě napsáno jest. Nebo kdo oře, v naději orati má; a kdo mlátí v naději, naděje své má účasten býti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 11, 'Poněvadž jsme my vám duchovní věci rozsívali, veliká-liž by věc byla, kdybychom my vaše časné věci žali?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 12, 'Kdyžť jiní práva svého k vám užívají, proč ne raději my? A však neužívali jsme práva toho, ale všecko snášíme, abychom žádné překážky neučinili evangelium Kristovu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 13, 'Zdaliž nevíte, že ti, kteříž o svatých věcech pracují, z svatých věcí jedí, a kteříž oltáři přístojí, s oltářem spolu díl mají?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 14, 'Tak i Pán nařídil těm, kteříž evangelium zvěstují, aby z evangelium živi byli.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 15, 'Jáť jsem však ničeho toho neužíval. Aniž jsem toho proto psal, aby se to při mně tak dálo, anoť by mi mnohem lépe bylo umříti, nežli aby kdo chválu mou vyprázdnil.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 16, 'Nebo káži-li evangelium, nemám se čím chlubiti, poněvadž jsem to povinen; ale běda by mně bylo, kdybych nekázal.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 17, 'Jestliže pak dobrovolně to činím, mámť odplatu; pakli bezděk, úřadť jest mi svěřen.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 18, 'Jakouž tedy mám odplatu? Abych evangelium káže, ukázal, že jest bez nákladů evangelium Kristovo, proto abych zle neužíval práva svého při evangelium.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 19, 'Svoboden zajisté jsa ode všech, všechněm sebe samého v službu jsem vydal, abych mnohé získal.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 20, 'A učiněn jsem Židům jako Žid, abych Židy získal; těm, kteříž pod zákonem jsou, jako bych pod zákonem byl, abych ty, kteříž pod zákonem jsou, získal.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 21, 'Těm, kteříž jsou bez zákona, jako bych bez zákona byl, (nejsa bez zákona Bohu, ale jsa pod zákonem Kristu,) abych získal ty, kteříž jsou bez zákona.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 22, 'Učiněn jsem mdlým jako mdlý, abych mdlé získal. Všechněm všecko jsem učiněn, abych vždy některé k spasení přivedl.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 23, 'A toť činím pro evangelium, abych účastník jeho byl.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 24, 'Zdaliž nevíte, že ti, kteříž v závod běží, všickni zajisté běží, ale jeden béře základ? Tak běžte, abyste dosáhli.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 25, 'A všeliký, kdož bojuje, ve všem jest zdrželivý. A oni zajisté proto, aby porušitelnou korunu vzali, ale my neporušitelnou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 26, 'Protož já tak běžím, ne jako v nejistotu, tak bojuji, ne jako vítr rozrážeje,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 27, 'Ale podmaňuji tělo své, a v službu podrobuji, abych snad jiným káže, sám nebyl nešlechetný.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 1, 'Nechciť pak, abyste nevěděli, bratří, že otcové naši všickni pod oním oblakem byli, a všickni moře přešli,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 2, 'A všickni v Mojžíše pokřtěni jsou v oblace a v moři,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 3, 'A všickni týž pokrm duchovní jedli,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 4, 'A všickni týž nápoj duchovní pili. Pili zajisté z duchovní skály, kteráž za nimi šla. Ta pak skála byl Kristus.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 5, 'Ale ne ve mnohých z nich zalíbilo se Bohu; nebo zhynuli na poušti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 6, 'Ty pak věci ku příkladu nám se staly, abychom nebyli žádostivi zlého, jako oni žádali.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 7, 'Protož nebuďte modláři, jako někteří z nich, jakož psáno jest: Posadil se lid, aby jedl a pil, a vstali, aby hrali.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 8, 'Aniž smilněme, jako někteří z nich smilnili, a padlo jich jeden den třímecítma tisíců.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 9, 'Ani pokoušejme Krista, jako někteří z nich pokoušeli, a od hadů zhynuli.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 10, 'Ani repcete, jako i někteří z nich reptali, a zhynuli od záhubce.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 11, 'Toto pak všecko u figůře dálo se jim, a napsáno jest k napomenutí našemu, kteříž jsme na konci světa.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 12, 'A protož kdo se domnívá, že stojí, hlediž, aby nepadl.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 13, 'Pokušení vás nezachvátilo, než lidské. Ale věrnýť jest Bůh, kterýž nedopustí vás pokoušeti nad vaši možnost, ale způsobíť s pokušením také i vysvobození, abyste mohli snésti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 14, 'Protož, moji milí, utíkejtež modlářství.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 15, 'Jakožto opatrným mluvím. Vy suďte, co pravím.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 16, 'Kalich dobrořečení, kterémuž dobrořečíme, zdaliž není společnost krve Kristovy? A chléb, kterýž lámeme, zdaliž není společnost těla Kristova?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 17, 'Poněvadž jeden chléb, jedno tělo mnozí jsme; všickni zajisté jednoho chleba účastni jsme.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 18, 'Pohleďte na Izraele podlé těla. Zdaliž ti, kteříž jedí oběti, nejsou účastníci oltáře?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 19, 'Což tedy dím? Že modla jest něco? Aneb že modlám obětované něco jest?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 20, 'Anobrž což obětují pohané, ďáblům obětují, a ne Bohu. Nechtělť bych pak, abyste vy byli účastníci ďáblů.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 21, 'Nemůžete kalicha Páně píti i kalicha ďáblů; nemůžete účastníci býti stolu Páně i stolu ďáblů.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 22, 'Či k hněvu popouzíme Pána? Zdaž silnější jsme jeho?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 23, 'Všecko mi sluší, ale ne všecko jest užitečné; všecko mi sluší, ale ne všecko vzdělává.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 24, 'Žádný nehledej svých věcí, ale jeden každý toho, což jest bližního.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 25, 'Všecko, což se v masných krámích prodává, jezte, nic se nevyptávajíce pro svědomí.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 26, 'Nebo Páněť jest země i plnost její.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 27, 'Pozval-liť by vás pak kdo z nevěřících, a chcete jíti, vše, cožkoli bylo by vám předloženo, jezte, nic se nevyptávajíce pro svědomí.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 28, 'Pakli by vám někdo řekl: Toto jest modlám obětované, nejezte pro toho, kdož oznámil, a pro svědomí. Páně zajisté jest země i plnost její.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 29, 'Svědomí pak pravím ne tvé, ale toho druhého. Nebo proč by měla svoboda má potupena býti od cizího svědomí?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 30, 'A poněvadž já s díků činěním požívám, proč za bezbožného jmín býti mám pro to, z čehož já díky činím?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 31, 'Protož buď že jíte, neb pijete, aneb cožkoli činíte, všecko k slávě Boží čiňte.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 32, 'Bez úrazu buďte i Židům i Řekům i církvi Boží,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 33, 'Jakož i já ve všem líbím se všechněm, nehledaje v tom svého užitku, ale mnohých, aby spaseni byli.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 1, 'Následovníci moji buďte, jako i já Kristův.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 2, 'Chválímť pak vás, bratří, že všecky věci mé v paměti máte, a jakž jsem vydal vám, ustanovení zachováváte.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 3, 'Chciť pak, abyste věděli, že všelikého muže hlava jest Kristus, a hlava ženy muž, hlava pak Kristova Bůh.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 4, 'Každý muž, modle se aneb prorokuje s přikrytou hlavou, ohyžďuje hlavu svou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 5, 'Každá pak žena, modleci se aneb prorokujici s nepřikrytou hlavou, ohyžďuje hlavu svou; nebo jednostejná věc jest, jako by se oholila.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 6, 'Nebo nezavíjí-liť se žena, nechažť se také ostříhá. Pakli jest mrzká věc ženě oholiti se neb ostříhati, nechažť se zavíjí.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 7, 'Mužť nemá zavíjeti hlavy, jsa obraz a sláva Boží, ale žena jest sláva mužova.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 8, 'Nebo není muž z ženy, ale žena z muže.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 9, 'Není zajisté muž stvořen pro ženu, ale žena pro muže.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 10, 'Protož máť žena míti obestření na hlavě pro anděly.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 11, 'A však ani muž bez ženy, ani žena bez muže v Pánu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 12, 'Nebo jakož žena z muže, tak i muž skrze ženu, všecky pak věci z Boha.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 13, 'Vy sami mezi sebou suďte, sluší-li se ženě bez zavití modliti Bohu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 14, 'Zdaliž vás i samo přirození neučí, žeť jest ohyzda muži míti dlouhé vlasy?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 15, 'Ale ženě míti dlouhé vlasy poctivé jest; nebo vlasové k zastírání dáni jsou jí.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 16, 'Jestliže pak komu se vidí neustupným býti, myť takového obyčeje nemáme, ani církev Boží.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 17, 'Tyto pak věci předkládaje, nechválím, že ne k lepšímu, ale k horšímu se scházíte.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 18, 'Nejprvé zajisté, když se scházíte do shromáždění, slyším, že jsou roztržky mezi vámi, a poněkud tomu věřím.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 19, 'Neboť musejí i kacířstva mezi vámi býti, aby právě pobožní zjeveni byli mezi vámi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 20, 'Když tedy tak se scházíte vespolek, toť není večeři Páně jísti,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 21, 'Poněvadž jeden každý nejprv s jídlem večeře své se uspíší, a tu někdo lační, a jiný se přepil.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 22, 'A což pak domů nemáte k jídlu a ku pití? Čili církev Boží tupíte, a zahanbujete ty, kteříž nemají? Což vám dím? Chváliti budu vás? V tom nechválím.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 23, 'Já zajisté přijal jsem ode Pána, což i vydal jsem vám, že Pán Ježíš v tu noc, v kterouž zrazen jest, vzal chléb,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 24, 'A díky činiv, lámal a řekl: Vezměte, jezte, to jest tělo mé, kteréž se za vás láme. To čiňte na mou památku.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 25, 'Takž i kalich, když povečeřel, řka: Tento kalich jest ta nová smlouva v mé krvi. To čiňte, kolikrátkoli píti budete, na mou památku.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 26, 'Nebo kolikrátž byste koli jedli chléb tento a kalich tento pili, smrt Páně zvěstujete, dokudž nepřijde.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 27, 'A protož kdokoli jedl by chléb tento, a pil kalich Páně nehodně, vinen bude tělem a krví Páně.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 28, 'Zkusiž tedy sám sebe člověk, a tak chléb ten jez, a z toho kalicha pí.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 29, 'Nebo kdož jí a pije nehodně, odsouzení sobě jí a pije, nerozsuzuje těla Páně.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 30, 'Protož mezi vámi jsou mnozí mdlí a nemocní, a spí mnozí,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 31, 'Ješto kdybychom se sami rozsuzovali, nebyli bychom souzeni.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 32, 'Ale když býváme souzeni, ode Pána býváme poučováni, abychom s světem nebyli potupeni.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 33, 'A tak, bratří moji, když se scházíte k jídlu, jedni na druhé čekávejte.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 34, 'Pakli kdo lační, doma jez, abyste se nescházeli k odsouzení. Jiné pak věci, když přijdu, zřídím.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 1, 'O duchovních pak dařích, bratří, nechci, abyste nevěděli.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 2, 'Víte, že jste byli pohané, kteříž k modlám němým, jakž jste bývali vedeni, tak jste chodili.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 3, 'Protož známoť vám činím, že žádný v Duchu Božím mluvě, nezlořečí Ježíši, a žádný nemůže říci Pán Ježíš, jediné v Duchu svatém.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 4, 'Rozdílníť pak darové jsou, ale tentýž Duch,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 5, 'A rozdílná jsou přisluhování, ale tentýž Pán,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 6, 'A rozdílné jsou moci, ale tentýž jest Bůh, kterýž působí všecko ve všech.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 7, 'Jednomu pak každému dáno bývá zjevení Ducha k užitku.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 8, 'Nebo někomu dána bývá skrze Ducha řeč moudrosti, jinému pak řeč umění podlé téhož Ducha.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 9, 'Jinému pak víra v témž Duchu, jinému darové uzdravování v jednostejném Duchu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 10, 'Někomu pak divů činění, jinému pak proroctví, jinému pak rozeznání duchů, jinému pak rozličnost jazyků, jinému pak vykládání jazyků.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 11, 'Ale to vše působí jeden a týž Duch, rozděluje jednomu každému obzvláštně, jakž ráčí.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 12, 'Nebo jakož tělo jedno jest a mnoho má oudů, ale všickni ti jednoho těla oudové, mnozí jsouce, jedno tělo jsou: tak i Kristus.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 13, 'Skrze jednoho zajisté Ducha my všickni v jedno tělo pokřtěni jsme, buď Židé, buď Řekové, buď služebníci, neb svobodní, a všickni v jeden duch zapojeni jsme.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 14, 'Nebo tělo není jeden oud, ale mnozí.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 15, 'Dí-li noha: Poněvadž nejsem rukou, nejsem z těla, zdaliž proto není z těla?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 16, 'A dí-li ucho: Když nejsem oko, nejsem z těla, zdaliž proto není z těla?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 17, 'Jestliže všecko tělo jest oko, kde pak sluch? Pakli všecko sluch, kde povonění?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 18, 'Ale zřídil Bůh oudy, jeden každý z nich v těle, tak jakž chtěl.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 19, 'Pakliť by všickni byli jeden oud, kde by bylo tělo?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 20, 'Ale nyní ač mnozí oudové jsou, jest však jedno tělo.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 21, 'Nemůžeť tedy oko říci ruce: Nepotřebí mi tebe, aneb opět hlava nohám: Nepotřebuji vás.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 22, 'Nýbrž mnohem více oudové, kteříž se zdadí nejmdlejší v těle býti, potřební jsou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 23, 'A kteréž máme za nejnepoctivější v těle, těm větší poctivost činíme; a nepoctiví naši hojnější ozdobu mají,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 24, 'Poctiví pak oudové naši toho nepotřebují. Ale Bůh tak způsobil tělo, dav poslednějšímu hojnější poctivost,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 25, 'Aby nebyla roztržitost v těle, ale aby oudové jedni o druhé vespolek pečovali.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 26, 'A protož jestliže co trpí jeden oud, spolu s ním trpí všickni oudové; pakli jest v slávě jeden oud, radují se spolu s ním všickni oudové.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 27, 'Vy pak jste tělo Kristovo, a oudové z částky.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 28, 'A některé zajisté postavil Bůh v církvi nejprv apoštoly, druhé proroky, třetí učitele, potom moci, potom dary uzdravování, pomocníky, správce, rozličnost jazyků.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 29, 'Zdaliž jsou všickni apoštolé? Zdali všickni proroci? Zdali všickni učitelé? Zdali všickni divy činí?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 30, 'Zdali všickni mají dary k uzdravování? Zdali všickni jazyky mluví? Zdali všickni vykládají?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 31, 'Snažujte se pak dojíti darů lepších, a ještěť vyšší cestu vám ukáži.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 13, 1, 'Bych jazyky lidskými mluvil i andělskými, a lásky kdybych neměl, učiněn jsem měď zvučící aneb zvonec znějící.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 13, 2, 'A bychť měl proroctví, a povědom byl všelikého tajemství i všelikého umění, a kdybych měl tak velikou víru, že bych hory přenášel, lásky pak kdybych neměl, nic nejsem.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 13, 3, 'A kdybych vynaložil na pokrmy všecken statek svůj, a bych vydal tělo své k spálení, a lásky bych neměl, nic mi to neprospívá.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 13, 4, 'Láska trpělivá jest, dobrotivá jest, láska nezávidí, láska není všetečná, nenadýmá se.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 13, 5, 'V nic neslušného se nevydává, nehledá svých věcí, nezpouzí se, neobmýšlí zlého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 13, 6, 'Neraduje se z nepravosti, ale spolu raduje se pravdě.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 13, 7, 'Všecko snáší, všemu věří, všeho se naděje, všeho trpělivě čeká.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 13, 8, 'Láska nikdy nevypadá, ješto buď že proroctví jsou, ta přestanou, buď jazykové, ti utichnou, buď učení, to v nic přijde.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 13, 9, 'Z částky zajisté poznáváme, a z částky prorokujeme.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 13, 10, 'Ale jakž by přišlo dokonalé, tehdyť to, což jest z částky, vyhlazeno bude.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 13, 11, 'Dokudž jsem byl dítě, mluvil jsem jako dítě, myslil jsem jako dítě, smýšlel jsem jako dítě, ale když jsem muž, opustil jsem dětinské věci.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 13, 12, 'Nyní zajisté vidíme v zrcadle a skrze podobenství, ale tehdáž tváří v tvář. Nyní poznávám z částky, ale tehdy poznám, tak jakž i známostí obdařen budu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 13, 13, 'Nyní pak zůstává víra, naděje, láska, to tré, ale největší z nich jestiť láska.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 1, 'Stůjtež o lásku, horlivě žádejte duchovních věcí, nejvíce však, abyste prorokovali.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 2, 'Nebo ten, kdož mluví cizím jazykem, ne lidem mluví, ale Bohu; nebo žádný neposlouchá, ale duchem vypravuje tajemství.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 3, 'Kdož pak prorokuje, lidem mluví vzdělání, i napomínání, i potěšení.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 4, 'Kdož mluví cizím jazykem, sám sebe vzdělává, ale ten, kdož prorokuje, církev vzdělává.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 5, 'Chtělť bych pak, abyste všickni jazyky mluvili, ale však raději, abyste prorokovali. Nebo větší jest ten, kterýž prorokuje, nežli ten, kdož jazyky mluví, leč by také vykládal, aby se vzdělávala církev.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 6, 'A protož, bratří, přišel-li bych k vám, jazyky mluvě, což vám prospěji, nebudu-liť vám mluviti, buď v zjevení neb v umění, buď v proroctví neb v učení?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 7, 'Však i bezdušné věci, vydávající zvuk, jako píšťalka neb harfa, kdyby rozdílného zvuku nevydávaly, kterak by vědíno bylo, co se píská, aneb na harfu hrá?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 8, 'Ano trouba vydala-li by nejistý hlas, kdož se bude strojiti k boji?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 9, 'Tak i vy, nevydali-li byste jazykem srozumitelných slov, kterak bude rozumíno, co se mluví? Budete jen u vítr mluviti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 10, 'Tak mnoho, (jakž vidíme,) rozdílů hlasů jest na světě, a nic není bez hlasu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 11, 'Protož nebudu-liť znáti moci hlasu, budu tomu, kterýž mluví, cizozemec, a ten, kdož mluví, bude mi cizozemec.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 12, 'Tak i vy, poněvadž jste horliví milovníci duchovních věcí, toho hledejte, abyste se k vzdělání církve rozhojnili.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 13, 'A protož, kdož mluví jazykem, modl se, aby mohl vykládati.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 14, 'Nebo modlím-liť se jazykem, duch můj se modlí, ale mysl má bez užitku jest.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 15, 'Což tedy jest? Modliti se budu duchem a modliti se budu i myslí; plésati budu duchem, a plésati budu i myslí.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 16, 'Nebo kdybys dobrořečil duchem, kterakž ten, kterýž prostý člověk jest, k tvému díků činění řekne Amen, poněvadž neví, co pravíš?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 17, 'Nebo ač ty dobře díky činíš, ale jiný se nevzdělává.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 18, 'Děkuji Bohu svému, že více než vy všickni jazyky mluvím;');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 19, 'Ale v zboru raději bych chtěl pět slov srozumitelně promluviti, abych také jiných poučil, nežli deset tisíců slov jazykem.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 20, 'Bratří, nebuďte děti v smyslu, ale zlostí buďte děti, smyslem pak buďte dospělí.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 21, 'Psáno jest v zákoně: Protož rozličnými jazyky a cizími rty budu mluviti lidu tomuto, a aniž tak mne slyšeti budou, praví Pán.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 22, 'A tak jazykové jsou za div ne těm, kteříž věří, ale nevěřícím, proroctví pak ne nevěřícím, ale věřícím.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 23, 'A protož když by se sešla všecka církev spolu, a všickni by jazyky mluvili, a vešli by tam i neučení neb nevěřící, zdaliž neřeknou, že blázníte?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 24, 'Ale kdyby všickni prorokovali, a všel by někdo nevěřící neb neučený, přemáhán by byl ode všech, a souzen ode všech.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 25, 'A tak tajnosti srdce jeho zjeveny budou, a padna na tvář, klaněti se bude Bohu, vyznávaje, že jistě Bůh jest mezi vámi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 26, 'Což tedy, bratří? Když se scházíte, jeden každý z vás píseň má, učení má, jazyk má, zjevení má, vykládání má, všecko to budiž k vzdělání.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 27, 'Buď že kdo jazykem mluví, tedy skrze dva neb nejvíce tři, a to jeden po druhém, a jeden ať vykládá.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 28, 'Pakli by nebylo vykladače, nechť mlčí v shromáždění, sám pak sobě nechažť mluví a Bohu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 29, 'Proroci pak dva neb tři ať mluví, a jiní nechť rozsuzují.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 30, 'Pakliť by jinému tu přísedícímu zjeveno bylo, první mlč.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 31, 'Nebo můžete všickni, jeden po druhém, prorokovati, aby se všickni učili, a všickni se potěšovali.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 32, 'Duchovéť pak proroků prorokům poddání jsou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 33, 'Neboť Bůh není původ neřádu, ale pokoje, jako i ve všech shromážděních svatých.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 34, 'Ženy vaše v shromážděních ať mlčí, nebo nedopouští se jim mluviti, ale aby poddány byly, jakž i zákon praví.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 35, 'Pakli se chtí čemu naučiti, doma mužů svých nechať se ptají. Nebo mrzká věc jest ženám mluviti v shromáždění.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 36, 'Zdali od vás slovo Boží pošlo? Zdali k samým vám přišlo?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 37, 'Zdá-li se sobě kdo býti prorokem neb duchovním, nechažť pozná, co vám píši, žeť jsou přikázaní Páně.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 38, 'Pakli kdo neví, nevěz.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 39, 'A takž, bratří, snažte se o to, abyste prorokovali, a jazyky mluviti nezbraňujte.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 40, 'Všecko slušně a podlé řádu ať se děje.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 1, 'Připomínámť pak vám, bratří, evangelium, kteréž jsem zvěstoval vám, kteréž jste i přijali, v němž i stojíte,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 2, 'Skrze kteréž, (jestliže, kterak jsem vám kázal, v paměti máte,) i spasení béřete, leč byste na darmo uvěřili.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 3, 'Vydal jsem zajisté vám nejpředněji, což jsem i vzal, že Kristus umřel za hříchy naše podlé písem,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 4, 'A že jest pohřben, a že vstal z mrtvých třetího dne podlé písem,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 5, 'A že vidín jest od Petra, potom od dvanácti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 6, 'Potom vidín více než od pěti set bratří spolu, z nichž mnozí ještě živi jsou až dosavad, a někteří zesnuli.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 7, 'Potom vidín jest od Jakuba, potom ode všech apoštolů.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 8, 'Nejposléze pak ze všech, jako nedochůdčeti, ukázal se i mně.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 9, 'Nebo já jsem nejmenší z apoštolů, kterýž nejsem hoden slouti apoštol, proto že jsem se protivil církvi Boží.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 10, 'Ale milostí Boží jsem to, což jsem, a milost jeho ve mně daremná nebyla, ale hojněji, než oni všickni, pracoval jsem, a však ne já, ale milost Boží mně přítomná.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 11, 'Protož i já i oni tak kážeme, a tak jste uvěřili.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 12, 'Poněvadž se pak káže o Kristu, že z mrtvých vstal, kterakž někteří mezi vámi praví, že by nebylo z mrtvých vstání?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 13, 'Nebo není-liť z mrtvých vstání, anižť Kristus z mrtvých vstal.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 14, 'A nevstal-liť z mrtvých Kristus, tedyť jest daremné kázaní naše, a daremnáť jest i víra vaše.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 15, 'A byli bychom nalezeni i křiví svědkové Boží; nebo vydali jsme svědectví o Bohu, že vzkřísil z mrtvých Krista. Kteréhož nevzkřísil, (totiž) jestliže mrtví z mrtvých nevstávají.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 16, 'Nebo jestližeť mrtví z mrtvých nevstávají, anižť Kristus vstal.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 17, 'A nevstal-liť z mrtvých Kristus, marná jest víra vaše, ještě jste v svých hříších.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 18, 'A takť i ti, kteříž zesnuli v Kristu, zahynuli.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 19, 'Jestližeť pak v tomto životě toliko naději máme v Kristu, nejbídnější jsme ze všech lidí.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 20, 'Ale vstalť z mrtvých Kristus, prvotiny těch, kteříž zesnuli.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 21, 'Nebo poněvadž skrze člověka smrt, skrze člověka i vzkříšení z mrtvých.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 22, 'Nebo jakož v Adamovi všickni umírají, tak i skrze Krista všickni obživeni budou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 23, 'Ale jeden každý v svém pořádku: Prvotiny Kristus, potom ti, kteříž jsou Kristovi, v příští jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 24, 'Potom bude konec, když vzdá království Bohu a Otci, když vyprázdní všeliké knížatstvo, i všelikou vrchnost i moc.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 25, 'Neboť musí on kralovati, dokudž nepoloží všech nepřátel pod nohy jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 26, 'Nejposlednější pak nepřítel zahlazen bude smrt.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 27, 'Nebo všecky věci poddal pod nohy jeho. Když pak praví, že všecky věci poddány jsou, zjevnéť jest, že kromě toho, kterýž jemu poddal všecko.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 28, 'A když poddáno jemu bude všecko, tehdy i sám Syn poddá se tomu, kterýž jemu poddati má všecko, aby byl Bůh všecko ve všech.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 29, 'Sic jinak co činí ti, kteříž se křtí za mrtvé? Jestližeť jistotně nevstávají mrtví z mrtvých, i proč se křtí za mrtvé.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 30, 'Proč i my nebezpečenství trpíme každé hodiny?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 31, 'Na každý den umírám, skrze slávu naši, kterouž mám v Kristu Ježíši Pánu našem.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 32, 'Jestližeť jsem obyčejem jiných lidí bojoval s šelmami v Efezu, co mi to prospěje, nevstanou-liť mrtví? Jezme tedy a píme, nebo zítra zemřeme.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 33, 'Nedejte se svoditi. Porušujíť dobré obyčeje zlá rozmlouvání.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 34, 'Prociťte k konání spravedlnosti, a nehřešte. Nebo někteří neznají Boha; k zahanbení vašemu mluvím.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 35, 'Ale řekneť někdo: Kterakž vstanou mrtví? V jakém pak těle přijdou?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 36, 'Ó nemoudrý, to, což ty rozsíváš, nebývá obživeno, leč umře.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 37, 'A což rozsíváš, ne to tělo, kteréž potom zroste, rozsíváš, ale holé zrno, jaké se trefí, pšenice neb kteréžkoli jiné.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 38, 'Bůh pak dává jemu tělo, jakž ráčí, a jednomu každému z těch semen jeho vlastní tělo.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 39, 'Ne každé tělo jest jednostejné tělo, ale jiné zajisté tělo lidské, jiné pak tělo hovadí, jiné pak rybí, a jiné ptačí.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 40, 'A jsou těla nebeská, a jsou těla zemská, ale jináť jest zajisté sláva nebeských, a jiná zemských,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 41, 'Jiná sláva slunce, a jiná sláva měsíce, a jiná sláva hvězd; nebo hvězda od hvězdy dělí se v slávě.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 42, 'Takť bude i vzkříšení z mrtvých. Rozsívá se porušitelné, vstane neporušitelné;');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 43, 'Rozsívá se nesličné, vstane slavné; rozsívá se nemocné, vstane mocné;');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 44, 'Rozsívá se tělo tělesné, vstane tělo duchovní. Jest tělo tělesné, jest i duchovní tělo.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 45, 'Takť i psáno jest: Učiněn jest první člověk Adam v duši živou, ale ten poslední Adam v ducha obživujícího.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 46, 'Však ne nejprvé duchovní, ale tělesné, potom duchovní.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 47, 'První člověk z země zemský, druhý člověk sám Pán s nebe.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 48, 'Jakýž jest ten zemský, takoví jsou i zemští, a jakýž ten nebeský, takovíž budou i nebeští.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 49, 'A jakož jsme nesli obraz zemského, takť poneseme obraz nebeského.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 50, 'Totoť pak pravím, bratří: Že tělo a krev království Božího dědictví dosáhnouti nemohou, aniž porušitelnost neporušitelnosti dědičně obdrží.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 51, 'Aj, tajemství vám pravím: Ne všickni zajisté zesneme, ale všickni proměněni budeme, hned pojednou, v okamžení, k zatroubení poslednímu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 52, 'Neboť zatroubí, a mrtví vstanou neporušitelní, a my proměněni budeme.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 53, 'Musí zajisté toto porušitelné tělo obléci neporušitelnost, a smrtelné toto obléci nesmrtelnost.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 54, 'A když porušitelné toto obleče neporušitelnost, a smrtelné toto obleče nesmrtelnost, tehdy se naplní řeč, kteráž napsána jest: Pohlcena jest smrt v vítězství.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 55, 'Kde jest, ó smrti, osten tvůj? Kde jest, ó peklo, vítězství tvé?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 56, 'Osten pak smrti jestiť hřích, a moc hřícha jest zákon.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 57, 'Ale Bohu díka, kterýž dal nám vítězství skrze Pána našeho Jezukrista.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 58, 'Protož, bratří moji milí, stálí buďte a nepohnutelní, rozhojňujíce se v díle Páně vždycky, vědouce, že práce vaše není daremná v Pánu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 1, 'O zbírce pak na svaté, jakž jsem nařídil v církvích Galatských, tak i vy čiňte.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 2, 'V každou neděli jeden každý z vás sám u sebe slož, schovaje podlé možnosti, aby ne tehdáž, když bych přišel, zbírky se dály.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 3, 'Když pak přijdu, kterékoli schválíte skrze listy, tyť pošli, aby donesli tuto milost vaši do Jeruzaléma.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 4, 'Pakliť by se za hodné vidělo, abych i já šel, půjdouť se mnou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 5, 'Přijduť pak k vám, když Macedonii projdu; (nebo Macedonii míním projíti.)');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 6, 'Ale u vásť snad poostanu, aneb i přes zimu pobudu, abyste vy mne doprovodili, kamž bych koli šel.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 7, 'Nechci zajisté s vámi se toliko na zastavení shledati, ale naději se, že za nějaký čas pobudu u vás, bude-li Pán chtíti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 8, 'Zůstanuť pak v Efezu až do letnic.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 9, 'Nebo otevříny jsou mi tu veliké a mocné dvéře, a protivníků mnoho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 10, 'Přišel-liť by pak Timoteus, hleďtež, aby bezpečně byl u vás; neboť dílo Páně dělá jako i já.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 11, 'Protož nechť jím žádný nepohrdá, ale vyprovoďte jej v pokoji, ať přijde ke mně; neboť na něj čekám s bratřími.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 12, 'O Apollovi pak bratru vězte, že jsem ho velmi prosil, aby šel k vám s bratřími. Ale nikoli nebyl té vůle, aby nyní přišel, než přijdeť, když bude míti čas příhodný.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 13, 'Bděte, stůjte u víře, zmužile sobě počínejte, buďtež silní.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 14, 'Všecky věci vaše ať se dějí v lásce.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 15, 'Prosímť pak vás, bratří, víte, že čeled Štěpánova jest prvotiny Achaie, a že se v službu svatým vydali,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 16, 'Abyste i vy poddáni byli takovým, i všelikému pomáhajícímu a pracujícímu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 17, 'Těšímť se pak z příchodu Štěpána, a Fortunáta, a Achaika; nebo nedostatek váš oni doplnili.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 18, 'Potěšili zajisté mého ducha i vašeho. Protož znejtež takové.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 19, 'Pozdravujíť vás zborové, kteříž jsou v Azii. Pozdravujíť vás v Pánu velice Akvila a Priscilla, s církví tou, kteráž jest v domě jejich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 20, 'Pozdravují vás všickni bratří. Pozdravte sebe vespolek v políbení svatém.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 21, 'Pozdravení vlastní rukou Pavlovou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 22, 'Jestliže kdo nemiluje Pána Jezukrista, budiž proklatý: Maran atha.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 23, 'Milost Pána Jezukrista s vámi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 24, 'I láska má v Kristu Ježíši se všechněmi vámi. Amen.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 1, 'Pavel apoštol Ježíše Krista skrze vůli Boží, a Timoteus bratr, církvi Boží, kteráž jest v Korintu, se všechněmi svatými, kteříž jsou ve vší Achaii:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 2, 'Milost vám a pokoj od Boha Otce našeho a Pána Jezukrista.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 3, 'Požehnaný Bůh a Otec Pána našeho Jezukrista, Otec milosrdenství, a Bůh všelikého potěšení,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 4, 'Kterýž těší nás ve všelikém ssoužení našem, abychom i my mohli potěšovati těch, kteříž by byli v jakémkoli ssoužení, tím potěšením, kterýmž i my potěšeni jsme od Boha.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 5, 'Nebo jakož se rozhojňují utrpení Kristova při nás, tak skrze Krista rozhojňuje se i potěšení naše.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 6, 'Nebo buď že ssouženi jsme, pro vaše potěšení a spasení, kteréž se působí v snášení týchž trápení, kteráž i my trpíme; buď že potěšováni býváme, pro vaše potěšení a spasení. A naděje naše pevná jest o vás,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 7, 'Poněvadž víme, že jakož jste účastníci utrpení, tak i potěšení.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 8, 'Nechcemeť zajisté, abyste nevěděli, bratří, o ssoužení našem, kteréž jsme měli v Azii, že jsme nad míru přetíženi byli a nad možnost, tak že jsme již i o životu svém byli pochybili.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 9, 'Nýbrž sami v sobě již jsme byli tak usoudili, že nebylo lze než umříti, abychom nedoufali sami v sobě, ale v Bohu i mrtvé křísícím.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 10, 'Kterýž od takové smrti vytrhl nás, a vytrhuje, v něhož doufáme, že i ještě vytrhne,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 11, 'Když i vy nám pomáhati budete modlitbami za nás, aby z daru toho, příčinou mnohých osob nám daného, od mnohých děkováno bylo z nás.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 12, 'Nebo chlouba naše tato jest, svědectví svědomí našeho, že v sprostnosti a v upřímosti Boží, ne v moudrosti tělesné, ale v milosti Boží obcovali jsme na světě, zvláště pak u vás.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 13, 'Neboť nepíšeme vám nic jiného, než to, což čtete, aneb což prvé znáte. A naději mám, že až do konce tak znáti budete,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 14, 'Jakož jste i poznali nás z částky, žeť jsme chlouba vaše, podobně jako i vy naše, v den Pána Ježíše.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 15, 'A v tomť doufání chtěl jsem k vám přijíti nejprvé, abyste druhou milost měli,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 16, 'A skrze vás jíti do Macedonie, a zase z Macedonie přijíti k vám, a od vás abych byl doprovozen do Judstva.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 17, 'O tom pak když jsem přemyšloval, zdali jsem co lehkomyslně činil? Aneb což přemyšluji, zdali podlé těla přemyšluji, tak aby bylo při mně: Jest, jest, není, není?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 18, 'Anobrž víť věrný Bůh, že řeč naše k vám nebyla: Jest, a není.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 19, 'Nebo Syn Boží Ježíš Kristus, kterýž mezi vámi kázán jest skrze nás, skrze mne a Silvána a Timotea, nebyl: Jest, a není, ale bylo v něm: Jest.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 20, 'Nebo kolikžkoli jest zaslíbení Božích, v němť jsou: Jest, a v němť jest: Amen, k slávě Bohu skrze nás.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 21, 'Ten pak, kterýž potvrzuje nás s vámi v Kristu, a kterýž pomazal nás, Bůh jest.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 22, 'Kterýž i znamenal nás, a dal závdavek Ducha v srdce naše.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 23, 'Já pak Boha za svědka beru na svou duši, že lituje vás, ještě jsem nepřišel do Korintu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 24, 'Ne jako bychom panovali nad věrou vaší, ale pomocníci jsme radosti vaší; nebo věrou stojíte.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 1, 'Toto jsem pak sobě uložil, abych k vám zase s zámutkem nepřišel.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 2, 'Nebo jestliže já vás zarmoutím, i kdo jest, ješto by mne obveselil, než ten, kterýž jest ode mne zarmoucen?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 3, 'A toto samo psal jsem vám, abych přijda, neměl zámutku z těch, z nichž bych se měl radovati, doufaje o všech o vás, že radost má jest všech vás.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 4, 'Nebo z velikého ssoužení a bolesti srdce psal jsem vám, s mnohými slzami, ne abyste zarmouceni byli, ale abyste poznali lásku, kterouž k vám velikou mám.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 5, 'Jestližeť pak kdo zarmoutil, ne mneť zarmoutil, ale poněkud, (abych nepřetížil,) všecky vás.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 6, 'Dostiť má takový na tom trestání od mnohých,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 7, 'Tak abyste naproti tomu již raději odpustili, a potěšili ho, aby snad přílišným zámutkem nebyl sehlcen takový.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 8, 'Protož prosím vás, abyste utvrdili k němu lásku.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 9, 'Nebo i proto psal jsem, abych zkušením zvěděl, jste-li ve všem poslušni.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 10, 'Komuž pak vy co odpouštíte, i já. Nebo i já, jestliže jsem co odpustil, komuž jsem odpustil, pro vás jsem učinil, před oblíčejem Kristovým, abychom nebyli oklamáni od satana.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 11, 'Neboť nejsou nám myšlení jeho neznámá.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 12, 'Když jsem pak přišel do Troady, příčinou evangelium Kristova, ačkoli dvéře mi otevříny byly skrze Pána, však neměl jsem upokojení v duchu svém, proto že jsem nenalezl Tita, bratra svého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 13, 'Ale požehnav jich, odšel jsem do Macedonie.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 14, 'Bohu pak chvála, kterýž vždycky dává nám vítězství v Kristu, a vůni známosti své zjevuje skrze nás na každém místě.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 15, 'Neboť jsme Kristova vůně dobrá Bohu v těch, kteříž k spasení přicházejí, i v těch, kteříž hynou,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 16, 'Těmto zajisté vůně smrtelná k smrti, oněmno pak vůně života k životu. Ale k tomu kdo jest způsobný?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 17, 'Neboť nejsme, jako mnozí, cizoložící slovo Boží, ale jako z upřímnosti, ale jako z Boha, před oblíčejem Božím, o Kristu mluvíme.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 1, 'Začínáme opět sami sebe chváliti? Zdaliž potřebujeme, jako někteří, schvalujících listů k vám, neb od vás k jiným?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 2, 'List náš vy jste, napsaný v srdcích našich, kterýž znají a čtou všickni lidé.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 3, 'Nebo to zjevné jest, že jste list Kristův způsobený skrze přisluhování naše, napsaný ne černidlem, ale Duchem Boha živého, ne na dskách kamenných, ale na dskách srdce masitých.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 4, 'Doufání pak takové máme skrze Krista k Bohu,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 5, 'Ne že bychom dostateční byli mysliti něco sami z sebe, jakožto sami z sebe, ale dostatečnost naše z Boha jest.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 6, 'Kterýž i hodné nás učinil služebníky Nového Zákona, ne litery, ale Ducha. Nebo litera zabijí, ale Duch obživuje.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 7, 'Jestližeť pak přisluhování smrti, literami vyryté na dskách kamenných, bylo slavné, tak že nemohli patřiti synové Izraelští v tvář Mojžíšovu, pro slávu oblíčeje jeho, kteráž pominouti měla,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 8, 'I kterakž by ovšem přisluhování Ducha nemělo býti slavné?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 9, 'Nebo jestližeť přisluhování pomsty slavné bylo, mnohemť se více přisluhování spravedlnosti rozhojňuje v slávě.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 10, 'Nebo to, což oslaveno bylo, aniž oslaveno bylo v té částce, u přirovnání této předůstojné slávy.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 11, 'Nebo jestližeť to pomíjející bylo slavné, mnohemť více to, což zůstává, jestiť slavné.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 12, 'Protož majíce takovou naději, mnohé svobody v mluvení užíváme,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 13, 'A ne jako Mojžíš kladl zástěru na tvář svou, aby nepatřili synové Izraelští k cíli té věci pomíjející.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 14, 'Pročež ztupeni jsou smyslové jejich. Nebo až do dnes ta zástěra v čítání Starého Zákona zůstává neodkrytá; nebo skrze Krista se odnímá.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 15, 'Protož až do dnes, když čten bývá Mojžíš, zástěra jest položena na jejich srdci.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 16, 'Než jakž by se obrátilo ku Pánu, odňata bude ta zástěra.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 17, 'Nebo Pán jest Duch ten, a kdež jest ten Duch Páně, tu i svoboda.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 18, 'My pak všickni odkrytou tváří slávu Páně jako v zrcadle spatřujíce, v týž obraz proměněni býváme od slávy v slávu, jakožto od Ducha Páně.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 1, 'Protož majíce toto přisluhování, jakž jsme milosrdenství došli, neoblevujeme.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 2, 'Ale odmítáme ukrývání neslušnosti, nechodíce v chytrosti, aniž se lstivě obírajíce s slovem Božím, ale zjevováním pravdy v příjemnost uvodíce sebe u každého svědomí lidského před oblíčejem Božím.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 3, 'Pakliť zakryté jest evangelium naše, před těmi, kteříž hynou, zakryté jest.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 4, 'V nichž Bůh světa tohoto oslepil mysli, totiž v nevěrných, aby se jim nezasvítilo světlo evangelium slávy Kristovy, kterýž jest obraz Boží.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 5, 'Neboť ne sami sebe kážeme, ale Krista Ježíše Pána, sebe pak služebníky vašimi pro Ježíše.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 6, 'Bůh zajisté, kterýž rozkázal, aby se z temností světlo zablesklo, tenť se osvítil v srdcích našich k osvícení známosti slávy Boží v tváři Ježíše Krista.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 7, 'Mámeť pak poklad tento v nádobách hliněných, aby důstojnost té moci byla Boží, a ne z nás,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 8, 'Když se všech stran úzkost míváme, ale nebýváme cele potlačeni; býváme vrtkáni, ale nebýváme docela zvrtkáni;');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 9, 'Protivenství trpíme, ale nebýváme opuštěni; býváme opovrženi, ale nehyneme.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 10, 'Vždycky mrtvení Pána Ježíše na těle nosíme, aby i život Ježíšův na těle našem zjeven byl.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 11, 'Vždycky zajisté my, kteříž živi jsme, na smrt býváme vydáváni pro Ježíše, aby i život Ježíšův zjeven byl na smrtelném těle našem.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 12, 'A tak smrt v nás moc provodí, ale v vás život.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 13, 'Majíce tedy téhož ducha víry, podlé toho, jakž psáno jest: Uvěřil jsem, protož jsem mluvil, i myť věříme, protož i mluvíme,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 14, 'Vědouce, že ten, kterýž vzkřísil Pána Ježíše, i nás skrze Ježíše vzkřísí, a postaví s vámi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 15, 'Nebo to všecko děje se pro vás, aby ta přehojná milost skrze díků činění od mnohých rozmohla se k slávě Boží.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 16, 'Protož neoblevujeme, ale ačkoli ten zevnitřní člověk náš ruší se, však ten vnitřní obnovuje se den ode dne.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 17, 'Nebo toto nynější lehoučké ssoužení naše převelmi veliké věčné slávy břímě nám působí,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 18, 'Když nepatříme na ty věci, kteréž se vidí, ale na ty, kteréž se nevidí. Nebo ty věci, kteréž se vidí, jsou časné, ale které se nevidí, jsou věčné.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 1, 'Víme zajisté, že byl-li by tohoto našeho zemského přebývání stánek zbořen, stavení od Boha máme, příbytek ne rukou udělaný, věčný v nebesích.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 2, 'Pročež i v tomto vzdycháme, v příbytek svůj, kterýž jest s nebe, oblečeni býti žádajíce,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 3, 'Jestliže však oblečení, a ne nazí nalezeni budeme.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 4, 'Nebo kteříž jsme v tomto stánku, lkáme, jsouce obtíženi, poněvadž bychom nechtěli svlečeni býti, ale přiodíni, aby pohlcena byla smrtelnost od života.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 5, 'Ten pak, kdož nás tak k tomu způsobil, Bůhť jest, kterýž také dal nám závdavek Ducha.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 6, 'Protož doufanlivé mysli vždycky jsouce, a vědouce, že dokudž pohostinu jsme v tomto těle, vzdáleni jsme ode Pána,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 7, '(Nebo skrze víru chodíme, ne skrze vidění,)');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 8, 'Doufanlivéť pak mysli jsme, a oblibujeme raději vyjíti z těla, a přijíti ku Pánu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 9, 'Protož i usilujeme buď v těle pohostinu jsouce, buďto z těla se berouce, jemu se líbiti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 10, 'Všickni my zajisté ukázati se musíme před soudnou stolicí Kristovou, aby přijal jeden každý to, což skrze tělo působil, podlé toho, jakž práce čí byla, buď v dobrém, neb ve zlém.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 11, 'Protož znajíce tu hrůzu Páně, lidem k víře sloužíme, Bohuť pak známi jsme. A nadějiť mám, že i svědomí vašemu známi jsme.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 12, 'Neboť ne sami sebe opět vám chválíme, ale příčinu vám dáváme, abyste se chlubili námi, a abyste to měli proti těm, kteříž se v tvárnosti chlubí, a ne v srdci.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 13, 'Nebo buď že nesmyslní jsme, Bohu; buď že jsme rozumní, vám.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 14, 'Láska zajisté Kristova víže nás,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 15, 'Jakožto ty, kteříž tak soudíme, že poněvadž jeden za všecky umřel, tedyť všickni zemřeli, a že za všecky umřel, aby ti, kteříž živi jsou, již ne sami sobě živi byli, ale tomu, kterýž za ně umřel i z mrtvých vstal.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 16, 'A tak my již od toho času žádného neznáme podlé těla. A ačkoli jsme znali Krista podlé těla, ale nyní již více neznáme.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 17, 'Protož jestli kdo v Kristu, nové stvoření jest. Staré věci pominuly, aj, nové všecko učiněno jest.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 18, 'To pak všecko jest z Boha, kterýž smířil nás s sebou skrze Jezukrista, a dal nám služebnost smíření toho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 19, 'Neboť Bůh byl v Kristu, v mír uvodě svět s sebou, nepočítaje jim hříchů jejich, a složil v nás to slovo smíření.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 20, 'Protož my na místě Kristově poselství dějíce, jako by Bůh skrze náš žádal, prosíme na místě Kristově, smiřte se s Bohem.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 21, 'Nebo toho, kterýž hříchu nepoznal, za nás učinil hříchem, abychom my učiněni byli spravedlností Boží v něm.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 1, 'Protož napomáhajíce, i napomínáme vás, abyste milosti Boží nadarmo nebrali,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 2, '(Neboť praví: V čas příhodný uslyšel jsem tě, a v den spasení spomohl jsem tobě. Aj, nyníť jest čas příhodný, aj, nyní dnové spasení.)');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 3, 'Žádného nedávajíce v ničemž pohoršení, aby bylo bez ouhony přisluhování,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 4, 'Ale ve všem se chovajíce jako Boží služebníci, ve mnohé trpělivosti, v utištěních, v nedostatcích, v úzkostech,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 5, 'V ranách, v žalářích, v nepokojích, v pracech, v bděních, v postech,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 6, 'V čistotě, v umění, v dlouhočekání, v dobrotivosti, v Duchu svatém, v lásce neošemetné,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 7, 'V slovu pravdy, v moci Boží, skrze odění spravedlnosti na pravo i na levo,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 8, 'Skrze slávu i pohanění, skrze zlou i dobrou pověst, jako bludní, a jsouce pravdomluvní,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 9, 'Jako neznámí, a jsouce známí, jako umírající, a aj, živi jsme, jako potrestaní, a nezmordovaní,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 10, 'Jako smutní, a však se vždycky radujíce, jako chudí, však mnohé zbohacujíce, jako nic nemajíce, a však všemi věcmi vládnouce.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 11, 'Ústa naše otevřína jsou k vám, ó Korinští, srdce naše rozšířeno jest.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 12, 'Nejste v nás ssouženi, než ssouženi jste v střevách svých.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 13, 'O takovéžť pak odměně jakožto synům pravím: Rozšiřtež se i vy.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 14, 'Netáhněte jha s nevěřícími. Nebo jaký jest spolek spravedlnosti s nepravostí? A jaké obcování světla s temnostmi?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 15, 'A jaké srovnání Krista s Beliálem? Aneb jaký díl věrnému s nevěrným?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 16, 'A jaké spolčení chrámu Božího s modlami? Nebo vy jste chrám Boha živého, jakž pověděl Bůh: Přebývati budu v nich, a procházeti se, a budu jejich Bohem, a oni budou mým lidem.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 17, 'A protož vyjdětež z prostředku jejich, a oddělte se, praví Pán; a nečistého se nedotýkejte, a já přijmu vás.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 18, 'A budu vám za Otce, a vy mi budete za syny a za dcery, praví Pán všemohoucí.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 1, 'Taková tedy majíce zaslíbení, nejmilejší, očišťujmež se od všeliké poškvrny těla i ducha, konajíce posvěcení v bázni Boží.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 2, 'Přijmětež nás. Žádnémuť jsme neublížili, žádnému neuškodili, žádného neoklamali.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 3, 'Nepravím toho ku potupě, poněvadž jsem napřed pověděl, že jste v srdcích našich, abychom spolu mřeli, i spolu živi byli.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 4, 'Mnohéť jsem k vám v mluvení důvěrnosti, mnohoť se vámi chlubím; naplněn jsem potěšením, rozhojňujiť se v radosti ve všelikém ssoužení našem.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 5, 'Nebo i když jsme byli přišli do Macedonie, žádného odpočinutí nemělo tělo naše, ale ve všem ssouženi jsme byli; zevnitř boje, vnitř strachy.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 6, 'Ale ten, kterýž těší ponížené, potěšil nás, Bůh, skrze příchod Titův.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 7, 'A netoliko příchodem jeho, ale také i potěšením tím, kteréž on měl z vás, vypravovav nám o vaší veliké žádosti, o vašem kvílení, a vaší ke mně horlivé milosti, tak že jsem se velmi zradoval.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 8, 'A ačkoli zarmoutil jsem vás listem, nelituji toho, ač jsem byl litoval. Nebo vidím, že ten list, ačkoli na čas, zarmoutil vás.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 9, 'Nyní raduji se, ne že jste zarmouceni byli, ale že jste se ku pokání zarmoutili. Zarmoutili jste se zajisté podlé Boha, tak že jste k žádné škodě nepřišli skrze nás.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 10, 'Nebo zámutek, kterýž jest podlé Boha, ten pokání k spasení působí, jehož nikdy líto nebývá, ale zámutek světa smrt způsobuje.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 11, 'Ano hle, to samo, že jste podlé Boha zarmouceni byli, jakou v vás způsobilo snažnost, nýbrž omluvu, nýbrž zažhnutí hněvu, nýbrž bázeň, nýbrž žádost vroucí, nýbrž horlivost, anobrž pomstu? Všelijak prokázali jste to, že jste nevinni v té věci.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 12, 'A ač psal jsem vám, však ne pro toho, kterýž tu nepravost spáchal, ani pro toho, komuž se křivda stala, ale aby vám zjevena byla pilnost naše o vás před oblíčejem Božím.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 13, 'Protož potěšeniť jsme z potěšení vašeho. Ale mnohem hojněji zradovali jsme se z radosti Titovy, že poočerstven jest duch jeho ode všech vás,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 14, 'A že chlubil-li jsem se v čem vámi před ním, nebyl jsem zahanben, ale jakož všecko mluvili jsme vám v pravdě, tak i chlouba naše, kteráž byla před Titem, pravá jest shledána.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 15, 'Ano i srdce jeho k vám jest příchylnější, když rozpomíná se na poslušenství všech vás, kterak jste ho s bázní a s strachem přijali.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 16, 'Protož raduji se, že ve všem mohu se vám dověřiti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 1, 'Známuť pak vám činíme, bratří, milost Boží, danou zborům Macedonským,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 2, 'Že v mnohém zkušení ssoužení rozhojnilá radost jejich a převeliká chudoba jejich rozhojněna jest v bohatství upřímosti jejich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 3, 'Nebo svědectví jim vydávám, že podlé možnosti, ba i nad možnost hotovi byli,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 4, 'Mnohými žádostmi prosíce nás, abychom tu milost a zbírku, kteráž se děje na svaté, na se přijali.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 5, 'A netoliko tak, jakž jsme se nadáli, ale sami sebe nejprvé dali Pánu, i nám z vůle Boží,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 6, 'Tak že jsme musili napomenouti Tita, aby jakož byl prvé započal, tak také i dokonal při vás milost tuto.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 7, 'A protož jakž ve všech věcech jste hojní, u víře i v řeči i v známosti i ve všeliké snažnosti i v lásce své k nám, tak i v této milosti hojní buďte.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 8, 'Ne jako rozkazuje, pravím, ale snažností jiných i vaši upřímou lásku zkušenou ukázati chtěje.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 9, 'Nebo znáte milost Pána našeho Jezukrista, že pro vás učiněn jest chudý, jsa bohatý, abyste vy jeho chudobou zbohatli.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 10, 'A k tomuť vám radu dávám; nebo jest vám to užitečné, kteříž jste netoliko činiti, ale i chtíti prvé začali léta předešlého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 11, 'Protož nyní již to skutkem vykonejte, aby jakož hotové bylo chtění, tak bylo i vykonání z toho, což máte.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 12, 'Nebo jest-liť prvé vůle hotová, podlé toho, což kdo má, vzácná jest, ne podlé toho, čehož nemá.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 13, 'Nebo ne, aby jiní měli polehčení, a vy úzkost, ale rovnost ať jest, nyní přítomně vaše hojnost spomoz jejich chudobě,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 14, 'Aby také jejich hojnost vaší chudobě byla ku pomoci, aby tak byla rovnost;');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 15, 'Jakož psáno: Kdo mnoho, nic mu nezbývalo, a kdo málo, neměl nedostatku.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 16, 'Ale díka Bohu, kterýž takovou snažnost k vám dal v srdce Titovo,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 17, 'Tak že to napomenutí přijal, anobrž jsa opravdový, sám z své dobré vůle šel k vám.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 18, 'Poslaliť jsme pak s ním bratra toho, kterýž má velikou chválu v evangelium po všech zbořích,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 19, '(A netoliko to, ale také vyvolen jest od církví za tovaryše putování našeho, s touto milostí, kterouž sloužíme k slávě Pánu a vůli vaší,)');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 20, 'Varujíce se toho, aby nám někdo neutrhal pro tu hojnost, kterouž my přisluhujeme,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 21, 'Dobré opatrujíce netoliko před oblíčejem Páně, ale i před lidmi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 22, 'Poslali jsme pak s nimi bratra svého, kteréhož jsme mnohokrát ve mnohých věcech zkusili, že jest pilný, a nyní mnohem pilnější pro mnohé doufání mé o vás.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 23, 'Z strany Tita, tovaryš můj jest, a mezi vámi pomocník; z strany bratří našich, poslové jsou církví a sláva Kristova.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 24, 'Protož jistoty lásky své a chlouby naší o vás k nim dokažte, před oblíčejem církví.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 1, 'Nebo o pomoci, kteráž se děje svatým, jest zbytečné psáti vám.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 2, 'Vím zajisté o vaší hotovosti, pro kterouž chlubím se vámi Macedonským, že Achaia hotova jest od předešlého léta. A ta vaše horlivost mnohými pohnula.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 3, 'I poslal jsem tyto bratří, aby chlouba naše vámi nebyla marná v té stránce, ale abyste, (jakž jsem řekl,) byli hotovi,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 4, 'Abychom snad, přišli-li by se mnou Macedonští, a nalezli vás nehotové, nemusili se styděti, (ať nedím vy,) za tak podstatnou chloubu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 5, 'Protož vidělo se mi za potřebné těchto bratří napomenouti, aby napřed šli k vám, a připravili prvé opověděnou zbírku vaši, aby byla hotová jako dobrovolná zbírka, a ne jako bezděčná.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 6, 'Ale totoť pravím: Kdo skoupě rozsívá, skoupě i žíti bude; a kdož rozsívá ochotně, ochotně i žíti bude.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 7, 'Jeden každý jakž uložil v srdci, ne s neochotnou myslí aneb z mušení. Neboť ochotného dárce miluje Bůh.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 8, 'Mocenť jest pak Bůh všelikou milost rozhojniti v vás, abyste ve všem všudy všeliký dostatek majíce, hojní byli ke všelikému skutku dobrému,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 9, 'Jakož psáno jest: Rozsypal a dal chudým, spravedlnost jeho zůstává na věky.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 10, 'Ten pak, kterýž dává símě rozsívajícímu, dejž i vám chléb k jedení, a rozmnožiž símě vaše, a přispořiž úrody spravedlnosti vaší,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 11, 'Abyste všelijak zbohaceni byli ke všeliké sprostnosti, kteráž působí skrze nás, aby díky činěny byly Bohu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 12, 'Nebo služba oběti této netoliko doplňuje nedostatky svatých, ale také rozhojňuje se v mnohé díků činění Bohu, příčinou schválení služby této,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 13, 'Když chválí Boha z jednomyslné poddanosti vaší k evangelium Kristovu, a z upřímé té zdílnosti k sobě i ke všechněm,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 14, 'A modlí se za vás ti, kteříž vás převelice milují pro vyvýšenou milost Boží v vás.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 15, 'Díka pak Bohu z nevymluvného daru jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 1, 'Já pak sám Pavel prosím vás skrze tichost a dobrotivost Kristovu, kterýžto v přítomnosti u vás jsem pokorný, ale v nepřítomnosti jsem k vám směle dověrný.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 2, 'Prosímť pak, abych přítomen jsa, nemusil se osvoboditi tou smělostí, na kterouž myslím, abych smělý byl proti některým, kteříž za to mají, že bychom my podlé těla chodili.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 3, 'V těle zajisté chodíce, ne podlé těla rytěřujeme,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 4, '(Nebo odění rytěřování našeho není tělesné, ale mocné v Bohu k vyvrácení ohrad,)');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 5, 'Podvracejíce rady, i všelikou vysokost, povyšující se proti umění Božímu, a jímajíce všelikou mysl v poddanost Kristu,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 6, 'A nahotově majíce pomstu proti každému neposlušenství, když naplněno bude vaše poslušenství.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 7, 'Na to-liž jen, co před očima jest, hledíte? Má-li kdo tu naději o sobě, že by Kristův byl, pomysliž také na to sám u sebe, že jakož on jest Kristův, tak i my Kristovi jsme.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 8, 'Nebo bychť se pak i ještě hojněji chlubil mocí naší, kterouž nám dal Pán k vzdělání, a ne k zkažení vašemu, nebuduť zahanben;');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 9, 'Abych se nezdál listy strašiti vás.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 10, 'Nebo listové prý jsou těžcí a mocní, ale přítomnost osobná jest mdlá, a řeč chaterná.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 11, 'Toto nechať myslí takový, že jacíž jsme v slovu skrze psání, vzdáleni jsouce, takoví také budeme i v skutku, přijdouce.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 12, 'Neboť my se nesmíme přimísiti aneb přirovnati k některým, kteříž sami sebe chválí. Ale ti nerozumějí, že sami sebou sebe měří, a přirovnávají sebe sobě.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 13, 'My pak tím, což není odměřeno, nebudeme se chlubiti, ale podlé míry pravidla, kteroužto míru odměřil nám Bůh, tak že jsme dosáhli až k vám.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 14, 'Nebo ne jako bychom nedosáhli až k vám, rozšiřujeme se nad míru. Až i k vám zajisté přišli jsme v evangelium Kristovu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 15, 'My tedy tím, což není odměřeno, nechlubíme se, cizími pracemi, ale naději máme, když víra vaše růsti bude v vás, že se rozšíříme dále podlé toho, jakž nám odměřeno,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 16, 'Abych ještě tam za vámi kázal evangelium, ne abych v tom, což jinému odměřeno jest, a jest hotové, chlubil se.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 17, 'Ale kdo se chlubí, v Pánu se chlub.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 18, 'Nebo ne ten, kdož se sám chválí, zkušený jest, ale ten, kohož Pán chválí.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 1, 'Ó byste mne maličko posnesli v nemoudrosti, nýbrž posneste mne.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 2, 'Neboť miluji vás Božím milováním. Zasnoubilť jsem zajisté vás čistou pannu oddati jednomu muži, Kristu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 3, 'Ale bojím se, aby snad, jakž onen had svedl Evu chytrostí svou, tak nebyly porušeny mysli vaše od sprostnosti, kteráž jest v Kristu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 4, 'Nebo kdyby někdo přijda, jiného Ježíše kázal, kteréhož jsme nekázali, aneb kdybyste jiného ducha přijali, kteréhož jste nepřijali, aneb jiné evangelium, kteréhož jste nevzali, slušně byste toho snášeli.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 5, 'Neboť za to mám, že jsem nic menší nebyl nežli ti velicí apoštolé.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 6, 'Jestližeť pak jsem nedospělý v řeči, však ne v umění, ale ve všem všudy zjevní jsme vám.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 7, 'Zdali jsem zhřešil, ponižuje se, abyste vy povýšeni byli, že jsem darmo evangelium Boží kázal vám?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 8, 'Jiné jsem církve loupil, bera od nich žold, abych vám sloužil. A byv u vás, i jsa potřeben, nezahálel jsem s obtížením žádného.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 9, 'Nebo ten nedostatek můj doplnili bratří, přišedše z Macedonie. A ve všech věcech varoval jsem se, a varovati budu, abych vás neobtěžoval.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 10, 'Jestiť pravda Kristova ve mně, že chlouba tato nebude mi zmařena v krajinách Achaiských.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 11, 'Z které příčiny? Že vás nemiluji? Bůhť ví.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 12, 'Ale což činím, ještěť činiti budu, abych odňal příčinu těm, kteříž chtějí dostati příčiny, aby v tom, v čemž se chlubí, nalezeni byli takoví jako i my.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 13, 'Nebo takoví falešní apoštolé jsou dělníci lstiví, proměňujíce se v apoštoly Kristovy.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 14, 'A není div. Nebo i sám satan proměňuje se v anděla světlosti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 15, 'Protož neníť to tak veliká věc, jestliže i služebníci jeho proměňují se, aby se zdáli býti služebníci spravedlnosti, jichžto konec bude podlé skutků jejich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 16, 'Opět pravím, aby mne někdo neměl za nemoudrého; nýbrž i jako nemoudrého přijměte mne, ať i já se maličko něco pochlubím.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 17, 'Což mluvím, nemluvímť jako ode Pána, ale jako v nemoudrosti z strany této podstatné chlouby.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 18, 'Kdyžť se mnozí chlubí podlé těla, i jáť se pochlubím.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 19, 'Rádi zajisté snášíte nemoudré, jsouce moudří.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 20, 'Nebo snášíte i to, by vás kdo v službu podroboval, by kdo zžíral, by kdo bral, by se kdo pozdvihoval, by vás kdo v tvář bil.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 21, 'O zahanbování pravím, rovně jako bychom my nějací špatní byli. Nýbrž v čem kdo smí, (v nemoudrosti mluvím,) smímť i já.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 22, 'Židé jsou? Jsem i já. Izraelští jsou? Jsem i já. Símě Abrahamovo jsou? Jsem i já.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 23, 'Služebníci Kristovi jsou? (Nemoudře dím:) Nadto já. V pracech hojněji, v ranách přílišně, v žalářích hojněji, v smrtech častokrát.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 24, 'Od Židů pětkrát čtyřidceti ran bez jedné trpěl jsem.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 25, 'Třikrát metlami mrskán jsem, jednou jsem byl kamenován, třikrát jsem na moři tonul, ve dne i v noci v hlubokosti byl jsem.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 26, 'Na cestách často, v nebezpečenství na řekách, v nebezpečenství od lotrů, v nebezpečenství od svého pokolení, v nebezpečenství od pohanů, v nebezpečenství v městě, v nebezpečenství na poušti, v nebezpečenství na moři, v nebezpečenství mezi falešnými bratřími.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 27, 'V práci a v ustání, v bděních často, v hladu a v žízni, v postech častokrát, na zimě a v nahotě.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 28, 'Kromě toho, což zevnitř jest, vojsko na každý den povstává proti mně, totiž péče o všecky zbory.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 29, 'Kdo umdlévá, ješto bych já nemdlel? Kdo se uráží, abych já se nepálil?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 30, 'Jestližeť se mám chlubiti, nemocmi svými se chlubiti budu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 31, 'Bůh a Otec Pána našeho Jezukrista, kterýž jest požehnaný na věky, ví, žeť nelhu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 32, 'Hejtman v Damašku lidu Aréty krále, ostříhal města Damašku, chtěje mne do vězení vzíti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 33, 'Ale oknem po provaze spuštěn jsem v koši přes zed, i ušel jsem rukou jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 1, 'Ale chlubiti mi se není dobré, nebo přišel bych k viděním a zjevením Páně.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 2, 'Znám člověka v Kristu před lety čtrnácti, (v těle-li, nevím, čili krom těla, nevím, Bůhť ví,) kterýž byl vtržen až do třetího nebe.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 3, 'A vím takového člověka, (bylo-li v těle, čili krom těla, nevím, Bůh ví,)');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 4, 'Že byl vtržen do ráje, a slyšel nevypravitelná slova, kterýchž nesluší člověku mluviti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 5, 'Takovým budu se chlubiti, ale sám sebou nebudu se chlubiti, než toliko nemocmi svými.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 6, 'Nebo budu-li se chtíti chlubiti, nebuduť nemoudrým, pravdu zajisté povím; ale uskrovnímť, aby někdo nesmýšlel více o mně, nežli vidí při mně, aneb slyší ode mne.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 7, 'A abych se vysokostí zjevení nad míru nepozdvihl, dán mi jest osten do těla, anděl satan, aby mne zašijkoval, abych se nad míru nepovyšoval.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 8, 'Za to třikrát jsem Pána prosil, aby to odstoupilo ode mne.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 9, 'Ale řekl mi: Dosti máš na mé milosti, neboť moc má v nemoci dokonává se. Nejraději tedy chlubiti se budu nemocmi svými, aby ve mně přebývala moc Kristova.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 10, 'Protož líbost mám v nemocech, v pohaněních, v nedostatcích, v protivenstvích, a v úzkostech, pro Krista. Nebo když mdlím, tehdy silen jsem.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 11, 'Učiněn jsem nemoudrým, chlubě se; vy jste mne k tomu přinutili. Nebo já od vás měl jsem chválen býti; neboť jsem nic menší nebyl nežli ti velicí apoštolé, ačkoli nic nejsem.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 12, 'Znamení zajisté apoštolství prokázána jsou mezi vámi ve vší trpělivosti, i v divích, a v zázracích, a v mocech.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 13, 'Nebo co jest, čeho byste vy méně měli nežli jiné církve, leč to, že jsem já nezahálel s obtížením vaším? Odpusťtež mi to bezpráví.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 14, 'Aj, již potřetí hotov jsem přijíti k vám, a nebuduť zaháleti s obtížením vaším. Neboť nehledám toho, což jest vašeho, ale vás. Nemajíť zajisté synové rodičům pokladů shromažďovati, ale rodičové synům.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 15, 'Jáť pak velmi rád náklad učiním, i sám se vynaložím za duše vaše, ačkoli velmi vás miluje, málo jsem milován.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 16, 'Ale nechť jest tak, že jsem já vás neobtěžoval, než chytrý jsa, lstí jsem vás zjímal.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 17, 'Zdali skrze někoho z těch, kteréž jsem poslal k vám, obloupil jsem vás?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 18, 'Dožádal jsem se Tita, a poslal jsem s ním bratra toho. Zdali vás Titus podvedl? Zdaliž jsme jedním duchem nechodili? Zdaliž ne jedněmi šlepějemi?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 19, 'A zase domníváte-li se, že se vymlouváme před vámi? Před oblíčejemť Božím v Kristu mluvíme, a to všecko, nejmilejší, k vašemu vzdělání.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 20, 'Neboť se bojím, abych snad přijda, nenalezl vás takových, jakýchž bych nechtěl, a já nebyl nalezen od vás, jakéhož byste vy nechtěli, aby snad nebylo svárů, závistí, hněvů, vád, utrhání, reptání, nadýmání, různic,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 21, 'Aby mne opět, když bych přišel, neponížil Bůh můj u vás, a plakal bych mnohých z těch, kteříž prvé hřešili, a nečinili pokání z nečistoty, a z smilstva, a z nestydatosti, kterouž páchali.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 1, 'Toto potřetí jdu k vám. V ústech dvou neb tří svědků staneť každé slovo.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 2, 'Předpovědělť jsem, a předpovídám podruhé jako přítomný, a nyní nepřítomný píši těm, kteříž prvé hřešili, i jiným všechněm, že přijdu-liť opět znovu, neodpustím,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 3, 'Poněvadž usilujete zkusiti toho, kterýž skrze mne mluví, Krista, kterýžto k vám není nemocný, ale mocný jest v vás.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 4, 'Nebo ačkoli ukřižován jest jako nemocný, ale živ jest z moci Boží. A tak i my mdlí jsme s ním, ale živi budeme s ním, z moci Boží na vás.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 5, 'Sami sebe zkušujte, jste-li u víře; sami sebe ohledujte. Čili sami sebe neznáte, že Ježíš Kristus jest v vás? Leč jste snad zavrženi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 6, 'Ale naději mám, že poznáte, žeť my nejsme zavrženi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 7, 'Modlímť se pak Bohu, abyste nic zlého nečinili, ne proto, abychom my se dokonalí ukázali, ale abyste vy to, což jest dobrého, činili, my pak jako zavrženi abychom byli.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 8, 'Neboť nic nemůžeme proti pravdě, ale k pravdě.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 9, 'Radujeme se zajisté, že ač jsme mdlí, ale vy jste silní, a za toť se i modlíme, abyste vy byli dokonalí.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 10, 'Protož toto nepřítomný jsa, píši, abych přítomen jsa, nemusil býti přísný, podlé moci, kterouž mi dal Pán k vzdělání, a ne k zkáze.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 11, 'Naposledy, bratří, mějtež se dobře, dokonalí buďte, potěšujte se, jednostejně smyslte, pokoj mějte, a Bůh lásky a pokoje budeť s vámi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 12, 'Pozdravtež jedni druhých políbením svatým.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 13, 'Pozdravují vás všickni svatí.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 14, 'Milost Pána Jezukrista, a láska Boží, a účastenství Ducha svatého se všechněmi vámi. Amen.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 1, 'Pavel apoštol, (ne od lidí, ani skrze člověka, ale skrze Jezukrista, a Boha Otce, kterýž jej vzkřísil z mrtvých,)');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 2, 'I ti, kteříž se mnou jsou, všickni bratří zborům Galatským:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 3, 'Milost vám a pokoj od Boha Otce a Pána našeho Jezukrista,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 4, 'Kterýž vydal sebe samého za hříchy naše, aby nás vytrhl z tohoto přítomného věku zlého, podlé vůle Boha a Otce našeho,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 5, 'Jemuž buď sláva na věky věků. Amen.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 6, 'Divím se, že jste tak rychle od toho, kterýž vás povolal v milost Kristovu, uchýlili se k jinému evangelium.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 7, 'Kteréž není jiné, ale jsou někteří, ješto vás kormoutí, a převrátiti chtějí evangelium Kristovo.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 8, 'Ale bychom pak i my neb anděl s nebe kázal vám mimo to, což jsme vám kázali, prokletý buď.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 9, 'Jakož jsme prvé pověděli, a ještě znovu pravím: Jestliže by vám kdo jiné evangelium kázal mimo to, kteréž jste přijali, prokletý buď.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 10, 'Nebo lidské-liž věci, čili Boží předkládám? Zdaliž lidem se líbiti hledám? Kdybych se zajisté ještě lidem zaliboval, služebník Kristův bych nebyl.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 11, 'Oznamujiť pak vám, bratří, že evangelium to, kteréž kázáno jest ode mne, není podlé člověka.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 12, 'Nebo aniž jsem já ho přijal od člověka, ani se naučil, ale skrze zjevení Ježíše Krista.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 13, 'Slýchali jste zajisté o mém obcování někdejším v Židovstvu, že jsem se převelice protivil církvi Boží, a hubil jsem ji,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 14, 'A že jsem prospíval v Židovstvu nad mnohé mně rovné v pokolení svém, byv velmi horlivý milovník otcovských ustanovení.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 15, 'Ale když se zalíbilo Bohu, kterýž mne byl oddělil z života matky mé, a povolal skrze milost svou,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 16, 'Zjeviti Syna svého mně, abych jej kázal mezi pohany, hned jsem se neporadil s tělem a krví;');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 17, 'Aniž jsem se vrátil do Jeruzaléma k těm, kteříž prvé byli apoštolé nežli já, ale šel jsem do Arabie, přišel jsem pak zase do Damašku.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 18, 'Potom po třech letech navrátil jsem se do Jeruzaléma, abych navštívil Petra, a pobyl jsem u něho patnácte dní.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 19, 'Jiného pak z apoštolů žádného jsem neviděl než Jakuba, bratra Páně.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 20, 'Cožť pak píši vám, aj, před Bohem, žeť neklamám.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 21, 'Potom přišel jsem do krajin Syrských a Cilických.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 22, 'Nebyl jsem pak známý osobou zborům Židovským, kteříž byli v Kristu,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 23, 'Než toliko slýchali: Že ten, kterýž se nám někdy protivil, již nyní káže víru, kterouž někdy vybojovával.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 24, 'A slavili ve mně Boha.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 1, 'Potom po čtrnácti letech opět vstoupil jsem do Jeruzaléma s Barnabášem, pojav s sebou i Tita.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 2, 'Vstoupil jsem pak podlé zjevení, a vypravoval jsem jim evangelium, kteréž káži mezi pohany, a zvláště pak znamenitějším, abych snad nadarmo neběžel nyní i prvé.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 3, 'Ale ani Titus, kterýž se mnou byl, pohan byv, nebyl přinucen obřezati se,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 4, 'Totiž pro podešlé falešné bratří, kteříž se byli vloudili k vyšpehování svobody naší, kterouž máme v Kristu Ježíši, aby nás v službu podrobili.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 5, 'Kterýmž ani na chvilku neustoupili jsme, a nepoddali se, aby pravda evangelium zůstala u vás.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 6, 'Od těch pak, kteříž se zdadí něco býti, ač jací někdy byli, mně potom nic není, Bůhť osoby člověka nepřijímá, ti, pravím, kteříž se něco zdadí býti, nic mi nepřidali.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 7, 'Nýbrž naodpor, když uzřeli, že jest mi svěřeno evangelium, abych je kázal neobřezaným, jako i Petrovi mezi Židy,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 8, '(Nebo ten, kterýž mocný byl skrze Petra z strany apoštolství mezi Židy, byl mocný i skrze mne mezi pohany,)');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 9, 'A poznavše milost mně danou, Jakub a Petr a Jan, kteříž se zdadí sloupové býti, podali pravic mně a Barnabášovi na tovaryšství, abychom my mezi pohany, a oni mezi Židy kázali.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 10, 'Toliko abychom na chudé pamatovali, což jsem se i činiti snažoval.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 11, 'A když byl přišel Petr do Antiochie, zjevně jsem jemu odepřel; hoden zajisté byl trestání.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 12, 'Nebo prvé než přišli někteří od Jakuba, jídal s pohany, a když přišli, ucházel a odděloval se, boje se těch, kteříž byli z Židovstva.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 13, 'A spolu s ním v tom pokrytství byli i jiní Židé, tak že i Barnabáš uveden byl v to jejich pokrytství.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 14, 'Ale já uzřev, že nesprostně chodí v pravdě evangelium, řekl jsem Petrovi přede všemi: Poněvadž ty jsa Žid, pohansky živ jsi, a ne Židovsky, proč pohany k Židovskému způsobu nutíš?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 15, 'My přirození Židé, a ne pohané hříšní,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 16, 'Vědouce, že nebývá člověk ospravedlněn z skutků zákona, ale skrze víru v Jezukrista, i my v Krista uvěřili jsme, abychom ospravedlněni byli z víry Kristovy, a ne z skutků zákona, proto že nebude ospravedlněn z skutků zákona žádný člověk.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 17, 'Jestliže pak hledajíce ospravedlněni býti v Kristu, nalézáme se i my hříšníci, tedy jest Kristus služebník hřícha? Nikoli.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 18, 'Nebo budu-li to, což jsem zbořil, opět zase vzdělávati, přestupníkem sebe činím.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 19, 'Já zajisté skrze zákon zákonu umřel jsem, abych živ byl Bohu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 20, 'S Kristem ukřižován jsem. Živť jsem pak již ne já, ale živ jest ve mně Kristus. Že pak nyní živ jsem v těle, u víře Syna Božího živ jsem, kterýž zamiloval mne, a vydal sebe samého za mne.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 21, 'Nepohrdámť tou milostí Boží. Nebo jestližeť jest z zákona spravedlnost, tedyť Kristus nadarmo umřel.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 1, 'Ó nemoudří Galatští, kdo vás tak zmámil, abyste nebyli povolni pravdě, kterýmž před očima Ježíš Kristus prvé byl vypsán, a mezi vámi ukřižován?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 2, 'Toto bych jen rád chtěl zvěděti od vás, z skutků-li zákona Ducha jste přijali, čili z slyšení víry?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 3, 'Tak nemoudří jste? Počavše Duchem, nyní tělem konáte?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 4, 'Tak mnoho trpěli jste nadarmo? A ještě nadarmo-li.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 5, 'Ten tedy, kterýž vám dává Ducha, a činí divy mezi vámi, z skutků-li zákona, čili z slyšení víry?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 6, 'Jako Abraham uvěřil Bohu, a počteno jemu to k spravedlnosti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 7, 'A tak vidíte, že ti, kteříž jsou z víry, ti jsou synové Abrahamovi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 8, 'Předzvěděvši pak písmo, že z víry ospravedlňuje pohany Bůh, předpovědělo Abrahamovi: Že v tobě budou požehnáni všickni národové.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 9, 'A tak ti, kteříž jsou z víry, docházejí požehnání s věrným Abrahamem.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 10, 'Kteříž pak koli z skutků zákona jsou, pod zlořečenstvím jsou. Nebo psáno jest: Zlořečený každý, kdož nezůstává ve všem, což jest psáno v knize zákona, aby to plnil.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 11, 'A že z zákona nebývá žádný ospravedlněn před Bohem, zjevné jest, nebo spravedlivý z víry živ bude.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 12, 'Zákon pak není z víry, ale: Ten člověk, kterýž by plnil je, živ bude skrze ně.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 13, 'Ale vykoupilť nás Kristus z zlořečenství zákona, učiněn byv pro nás zlořečenstvím, (nebo psáno jest: Zlořečený každý, kdož visí na dřevě,)');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 14, 'Aby na pohany to požehnání Abrahamovo přišlo v Kristu Ježíši, a abychom zaslíbení Ducha přijali skrze víru.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 15, 'Bratří, po lidsku pravím: Však utvrzené člověka smlouvy žádný neruší, aniž k ní co přidává.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 16, 'Abrahamovi pak učiněna jsou zaslíbení, i semeni jeho. Nedí: A semenům, jako o mnohých, ale jako o jednom: A semenu tvému, jenž jest Kristus.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 17, 'Totoť pak pravím: Že smlouvy prvé od Boha stvrzené, vztahující se k Kristu, zákon, kterýž po čtyřech stech a po třidcíti letech začal se, nevyprazdňuje, aby slib Boží v nic obrátil.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 18, 'Nebo jestližeť z zákona dědictví, již ne z zaslíbení. Ale Abrahamovi skrze zaslíbení Bůh daroval.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 19, 'Což pak zákon? Pro přestupování ustanoven jest, dokudž by nepřišlo to símě, jemuž se stalo zaslíbení, způsobený skrze anděly v ruce prostředníka.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 20, 'Ale prostředník není jednoho, Bůh pak jeden jest.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 21, 'Tedy zákon jest proti slibům Božím? Odstup to. Nebo kdyby byl zákon dán, kterýž by mohl obživiti, jistě z zákona byla by spravedlnost.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 22, 'Ale zavřelo písmo všecky pod hřích, aby zaslíbení z víry Jezukristovy dáno bylo věřícím.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 23, 'Prvé pak, než přišla víra, pod zákonem byli jsme ostříháni, zavříni jsouce k té víře, kteráž potom měla zjevena býti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 24, 'A tak zákon pěstounem naším byl k Kristu, abychom z víry ospravedlněni byli.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 25, 'Ale když přišla víra, již nejsme pod pěstounem.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 26, 'Všickni zajisté synové Boží jste v Kristu Ježíši skrze víru.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 27, 'Nebo kteřížkoli v Krista pokřtěni jste, Krista jste oblékli.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 28, 'Neníť ani Žid, ani Řek, ani slouha, ani svobodný, ani muž, ani žena. Nebo všickni vy jedno jste v Kristu Ježíši.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 29, 'A když Kristovi jste, tedy símě Abrahamovo jste, a podlé zaslíbení dědicové.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 1, 'Pravímť pak, že pokudž dědic maličký jest, nic není rozdílný od služebníka, jsa pánem všeho,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 2, 'Ale pod ochráncemi a správcemi jest až do času uloženého od otce.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 3, 'Tak i my když jsme byli maličcí, pod živly světa byli jsme v službu podrobeni.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 4, 'Ale když přišla plnost času, poslal Bůh Syna svého učiněného z ženy, učiněného pod zákonem,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 5, 'Aby ty, kteříž pod zákonem byli, vykoupil, abychom právo synů přijali.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 6, 'A že jste synové, poslal Bůh Ducha Syna svého v srdce vaše, volajícího: Abba, Otče.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 7, 'A tak již nejsi slouha, ale syn, a poněvadž syn, tedy i dědic Boží skrze Krista.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 8, 'Ale tehdáž, neznavše Boha, sloužili jste těm, kteříž z přirození nejsou bohové.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 9, 'Nyní pak, znajíce Boha, nýbrž poznáni jsouce od Boha, kterakž se zpátkem zase obracíte k mdlým a bídným živlům, jimž opět znovu chcete sloužiti?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 10, 'Dnů šetříte, a měsíců, a časů, i let.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 11, 'Bojím se za vás, abych snad nadarmo nepracoval mezi vámi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 12, 'Buďte jako já, nebo i já jsem jako vy, bratří, prosím vás. Nic jste mi neublížili.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 13, 'Nebo víte, že s mdlobou těla kázal jsem vám evangelium ponejprvé.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 14, 'A pokušení mé na těle mém nebylo u vás málo váženo, aniž jste pohrdli, ale jako anděla Božího přijali jste mne, jako Krista Ježíše.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 15, 'Jaké tehdy bylo blahoslavenství vaše? Svědectvíť vám zajisté dávám, že kdyby to možné bylo, oči své vyloupíce, byli byste mi dali.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 16, 'Což tedy učiněn jsem vaším nepřítelem, pravdu vám pravě?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 17, 'Milujíť vás nedobře, nýbrž odstrčiti nás chtějí, abyste vy je milovali.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 18, 'Slušnéť jest pak horlivě milovati v dobrém vždycky, a ne jen toliko tehdáž, když jsem přítomen vám.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 19, 'Synáčkové moji, (kteréž opět rodím, až by Kristus zformován byl v vás,)');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 20, 'Chtěl bych přítomen vám býti nyní, a proměniti hlas svůj; nebo v pochybnosti jsem o vás.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 21, 'Povězte mi, kteří pod zákonem chcete býti, nepozorujete-liž zákona?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 22, 'Nebo psáno jest: Že Abraham měl dva syny, jednoho z děvky, a druhého z svobodné.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 23, 'Ale ten z děvky podlé těla se narodil, ten pak z svobodné podlé zaslíbení.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 24, 'Kteréžto věci u figůře se staly. Nebo toť jsou ti dva zákonové, jeden s hory Sinai, k manství zplozující, a tenť jest jako Agar.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 25, 'Agar zajisté jest hora Sinai v Arabii. Dobřeť se pak k ní trefuje nynější Jeruzalém, nebo v službu podroben jest s syny svými.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 26, 'Ale ten svrchní Jeruzalém svobodný jest, kterýž jest matka všech nás.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 27, 'Nebo psáno jest: Vesel se neplodná, kteráž nerodíš, vykřikni a zvolej, kteráž nepracuješ ku porodu; nebo ta opuštěná mnoho má synů, více než ta, kteráž má muže.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 28, 'Myť jsme tedy, ó bratří, tak jako Izák, synové zaslíbení.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 29, 'Ale jakož tehdáž ten podlé těla zplozený protivil se tomu, kterýž byl podlé Ducha, tak i nyní.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 30, 'Než co praví písmo? Vyvrz děvku i syna jejího; nebo nebudeť dědicem syn děvky s synem svobodné.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 31, 'A tak, bratří, nejsmeť synové děvky, ale svobodné.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 1, 'Protož v svobodě, kterouž Kristus nás osvobodil, stůjte, a nezapletejte se zase v jho služebnosti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 2, 'Aj, já Pavel pravím vám, že budete-li se obřezovati, Kristus vám nic neprospěje.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 3, 'A zase osvědčuji všelikému člověku, kterýž se obřezuje, že jest povinen všecken zákon naplniti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 4, 'Zbavili jste se Krista, kteřížkoli v zákoně ospravedlněni býti hledáte; vypadli jste z milosti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 5, 'My zajisté duchem z víry naděje spravedlnosti očekáváme.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 6, 'Nebo v Kristu Ježíši ani obřízka nic neprospívá, ani neobřízka, ale víra skrze lásku dělající.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 7, 'Běželi jste dobře. Kdo vám překazil, abyste pravdy neposlouchali?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 8, 'Neníť ta rada z toho, kterýž vás volá.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 9, 'Maličko kvasu všecko těsto nakvašuje.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 10, 'Jáť mám naději o vás v Pánu, že nic jiného smýšleti nebudete; ale ten, kterýž kormoutí vás, trpěti bude soud, kdožť jest on koli.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 11, 'Já pak, bratří, káži-li také obřízku, i pročež ještě protivenství trpím? Tedy jest vyprázdněno pohoršení kříže.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 12, 'Ó by také odřezáni byli, kteříž vás nepokojí.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 13, 'Nebo vy v svobodu povoláni jste, bratří, toliko abyste pod zámyslem té svobody nepovolovali tělu, ale skrze lásku posluhujte sobě vespolek.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 14, 'Nebo všecken zákon v jednom slovu se zavírá, totiž v tom: Milovati budeš bližního svého jako sebe samého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 15, 'Pakli se vespolek koušete a žerete, hleďtež, abyste jedni od druhých zkaženi nebyli.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 16, 'Ale pravímť: Duchem choďte, a žádosti těla nevykonáte.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 17, 'Nebo tělo žádá proti Duchu, a Duch proti tělu. Ty pak věci jsou sobě vespolek odporné, tak abyste ne, což byste chtěli, to činili.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 18, 'Jestliže pak Duchem vedeni býváte, nejste pod zákonem.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 19, 'Zjevníť jsou pak skutkové těla, jenž jsou: Cizoložstvo, smilstvo, nečistota, chlipnost,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 20, 'Modloslužba, čarování, nepřátelství, svárové, nenávisti, hněvové, dráždění, různice, sekty,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 21, 'Závisti, vraždy, opilství, hodování, a těm podobné věci. Kteréž kdokoli činí, toť vám předpovídám, jakož jsem i prvé pravil, že království Božího dědicové nebudou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 22, 'Ovoce pak Ducha jestiť: Láska, radost, pokoj, tichost, dobrotivost, dobrota, věrnost, krotkost, středmost.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 23, 'Proti takovýmť není zákon.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 24, 'Nebo kteříž jsou Kristovi, ti své tělo ukřižovali s vášněmi a s žádostmi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 25, 'Jsme-liť Duchem živi, Duchem i choďme.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 26, 'Nebývejme marné chvály žádostivi, jedni druhých popouzejíce, a jedni druhým závidíce.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 1, 'Bratří, by pak byl zachvácen člověk v nějakém pádu, vy duchovní napravte takového v duchu tichosti, prohlédaje sám k sobě, abys i ty nebyl pokoušín.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 2, 'Jedni druhých břemena neste, a tak plňte zákon Kristův.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 3, 'Nebo zdá-li se komu, že by něco byl, nic nejsa, takového vlastní mysl jeho svodí.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 4, 'Ale díla svého zkus jeden každý, a tehdyť sám v sobě chválu míti bude, a ne v jiném.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 5, 'Nebo jeden každý své břímě ponese.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 6, 'Zdílejž se pak ten, kterýž naučení přijímá v slovu s tím, od kohož naučení béře, vším statkem.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 7, 'Nemylte se, Bůhť nebude oklamán; nebo cožkoli rozsíval by člověk, toť bude i žíti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 8, 'Nebo kdož rozsívá tělu svému, z těla žití bude porušení; ale kdož rozsívá Duchu, z Duchať žíti bude život věčný.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 9, 'Činíce pak dobře, neoblevujme; nebo časem svým budeme žíti, neustávajíce.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 10, 'A protož dokudž čas máme, čiňme dobře všechněm, nejvíce pak domácím víry.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 11, 'Pohleďte, jaký jsem vám list napsal svou rukou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 12, 'Ti, kteříž chtějí tvární býti podlé těla, nutí vás, abyste se obřezovali, jedné aby protivenství pro kříž Kristův netrpěli.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 13, 'Nebo ani sami ti, kteříž se obřezují, nezachovávají zákona, ale chtí, abyste se obřezovali, aby se tělem vaším chlubili.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 14, 'Ale ode mne odstup to, abych se chlubil, jediné v kříži Pána našeho Jezukrista, skrze něhož jest mi svět ukřižován, a já světu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 15, 'Nebo v Kristu Ježíši ani obřízka nic neprospívá, ani neobřízka, ale nové stvoření.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 16, 'A kteřížkoli tohoto pravidla následují, pokoj přijde na ně a milosrdenství, i na lid Boží Izraelský.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 17, 'Dále pak žádný mi nečiň zaměstknání, já zajisté jízvy Pána Ježíše nosím na těle svém.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 18, 'Milost Pána Ježíše Krista s duchem vaším, bratří. Amen.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 1, 'Pavel apoštol Jezukristův, skrze vůli Boží, svatým, kteří jsou v Efezu, a věrným v Kristu Ježíši:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 2, 'Milost vám a pokoj od Boha Otce našeho a Pána Jezukrista.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 3, 'Požehnaný Bůh a Otec Pána našeho Jezukrista, kterýž požehnal nám všelikým požehnáním duchovním v nebeských věcech v Kristu,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 4, 'Jakož vyvolil nás v něm před ustanovením světa, abychom byli svatí a nepoškvrnění před oblíčejem jeho v lásce,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 5, 'Předzřídiv nás k zvolení za syny skrze Ježíše Krista pro sebe, podlé dobře libé vůle své,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 6, 'K chvále slávy milosti své, kterouž vzácné nás učinil v tom nejmilejším.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 7, 'V němž máme vykoupení skrze krev jeho, totiž odpuštění hříchů, podlé bohatství milosti jeho,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 8, 'Kterouž rozhojnil k nám ve vší moudrosti a opatrnosti,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 9, 'Oznámiv nám tajemství vůle své podlé dobré líbosti své, kterouž předuložil byl sám v sobě,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 10, 'Aby v dokonání plnosti časů v jedno shromáždil všecko v Kristu, buď nebeské věci, buď zemské.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 11, 'V kterémž i k losu připuštěni jsme, předzřízeni byvše, podlé předuložení toho, kterýž všecko působí podlé rady vůle své,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 12, 'Abychom tak byli k chvále slávy jeho my, kteříž jsme prvé naději měli v Kristu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 13, 'V kterémž i vy naději máte, slyševše slovo pravdy, totiž evangelium spasení svého, skrze kteréž také, uvěřivše, znamenáni jste Duchem zaslíbení svatým,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 14, 'Kterýž jest závdavek dědictví našeho, na vykoupení toho, což jím dobyto jest, k chvále slávy jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 15, 'Protož i já, slyšev o vaší víře v Pánu Ježíši, a o lásce ke všechněm svatým,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 16, 'Nepřestávám díků činiti z vás, zmínku čině o vás na modlitbách svých,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 17, 'Aby Bůh Pána našeho Jezukrista, Otec slávy, dal vám Ducha moudrosti a zjevení ku poznání jeho,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 18, 'A tak osvícené oči mysli vaší, abyste věděli, která by byla naděje povolání jeho, a jaké bohatství slávy dědictví jeho v svatých,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 19, 'A kterak jest nesmírná velikost moci jeho k nám věřícím podlé působení mocnosti síly jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 20, 'Kteréž dokázal na Kristu, vzkřísiv jej z mrtvých, a posadiv na pravici své na nebesích,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 21, 'Vysoce nade všecko knížatstvo, i mocnosti, i moci, i panstvo, i nad každé jméno, kteréž se jmenuje, netoliko v věku tomto, ale i v budoucím.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 22, 'A všecko poddal pod nohy jeho, a jej dal hlavu nade všecko církvi,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 23, 'Kteráž jest tělo jeho, a plnost všecko ve všech naplňujícího.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 1, 'I vás obživil mrtvé v vinách a hříších,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 2, 'V nichž jste někdy chodili podlé obyčeje světa tohoto, a podlé knížete mocného v povětří, ducha toho, kterýž nyní dělá v synech zpoury.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 3, 'Mezi nimiž i my všickni obcovali jsme někdy v žádostech těla svého, činivše to, což se líbilo tělu a mysli, a byli jsme z přirození synové hněvu jako i jiní.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 4, 'Ale Bůh, bohatý jsa v milosrdenství pro velikou lásku svou, kterouž zamiloval nás,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 5, 'Také i nás, když jsme mrtví byli v hříších, obživil spolu s Kristem, (milostí spaseni jste,)');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 6, 'A spolu s ním vzkřísil, i posadil na nebesích v Kristu Ježíši,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 7, 'Aby ukázal v věku budoucím nepřevýšené bohatství milosti své, z dobroty své k nám v Kristu Ježíši.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 8, 'Nebo milostí spaseni jste skrze víru, (a to ne sami z sebe, darť jest to Boží,)');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 9, 'Ne z skutků, aby se někdo nechlubil.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 10, 'Jsme zajisté jeho dílo, jsouce stvořeni v Kristu Ježíši k skutkům dobrým, kteréž Bůh připravil, abychom v nich chodili.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 11, 'Protož pamatujte, že vy někdy pohané podlé těla, kteříž jste slouli neobřízka od těch, kteříž slouli obřízka na těle, kteráž se působí rukama,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 12, 'Vy jste byli onoho času bez Krista, odcizení od společnosti Izraele, a cizí od úmluv zaslíbení, naděje nemající, a bez Boha na světě.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 13, 'Ale nyní v Kristu Ježíši vy, kteříž jste někdy byli dalecí, blízcí učiněni jste skrze krev Kristovu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 14, 'Nebo onť jest pokoj náš, kterýž učinil oboje jedno, zbořiv hradbu dělící na různo,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 15, 'A nepřátelství, totiž zákon přikázaní v ustanoveních, vyprázdniv skrze tělo své, aby ty oboje vzdělal v samém sobě v jednoho nového člověka, tak čině pokoj,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 16, 'A v mír uvodě oboje v jenom těle Bohu skrze kříž, vyhladiv nepřátelství skrze něj.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 17, 'A přišed, zvěstoval pokoj vám, dalekým i blízkým.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 18, 'Neboť skrze něho obojí máme přístup v jednom Duchu k Otci.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 19, 'Aj, již tedy nejste hosté a příchozí, ale spoluměšťané svatých a domácí Boží,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 20, 'Vzdělaní na základ apoštolský a prorocký, kdež jest gruntovní úhelný kámen sám Ježíš Kristus,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 21, 'Na němž všecko stavení příslušně vzdělané roste v chrám svatý v Pánu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 22, 'Na kterémž i vy spolu vzděláváte se v příbytek Boží, v Duchu svatém.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 1, 'Pro tu příčinu já Pavel ten vězeň Krista Ježíše pro vás pohany,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 2, 'Jestliže však jste slyšeli o milosti Boží, kteréž jest mi uděleno k přisluhování vám,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 3, 'Že skrze zjevení oznámil mi tajemství, (jakož jsem prvé psal krátce;');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 4, 'Z čehož můžete, čtouce, porozuměti známosti mé v tajemství Kristovu;)');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 5, 'Kteréž za jiných věků nebylo známo synům lidským, tak jako nyní zjeveno jest svatým apoštolům jeho a prorokům skrze Ducha,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 6, 'Že jsou pohané spoludědicové a jednotělní, i spoluúčastníci zaslíbení jeho v Kristu skrze evangelium.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 7, 'Kteréhož jsem učiněn slouha z daru milosti Boží sobě dané, podlé působení moci jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 8, 'Mně nejmenšímu ze všech svatých dána jest milost ta, abych mezi pohany zvěstoval ta nestihlá bohatství Kristova,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 9, 'A vysvětlil všechněm, jaké by bylo obcování tajemství skrytého od věků v Bohu, kterýž všecko stvořil skrze Ježíše Krista,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 10, 'Aby nyní oznámena byla knížatstvu a mocem na nebesích skrze církev rozličná moudrost Boží,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 11, 'Podlé předuložení věčného, kteréž uložil v Kristu Ježíši Pánu našem,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 12, 'V němž máme smělost a přístup s doufáním skrze víru jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 13, 'Protož prosím, abyste nehynuli v mých ssouženích pro vás, kteráž jsou sláva vaše.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 14, 'Pro tuť příčinu klekám na kolena svá před Otcem Pána našeho Jezukrista,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 15, 'Z něhož všeliká rodina na nebi i na zemi se jmenuje,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 16, 'Aby vám dal, podlé bohatství slávy své, mocí posilněnu býti skrze Ducha svého na vnitřním člověku,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 17, 'Aby Kristus skrze víru přebýval v srdcích vašich,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 18, 'Abyste v lásce vkořeněni a založeni jsouce, mohli stihnouti se všechněmi svatými, kteraká by byla širokost, a dlouhost, a hlubokost, a vysokost,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 19, 'A poznati přenesmírnou lásku Kristovu, abyste naplněni byli ve všelikou plnost Boží.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 20, 'Tomu pak, kterýž mocen jest nade všecko učiniti mnohem hojněji, než my prosíme aneb rozumíme, podlé moci té, kterouž dělá v nás,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 21, 'Tomu buď sláva v církvi skrze Krista Ježíše po všecky věky věků. Amen.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 1, 'Prosímť tedy vás já vězeň v Pánu, abyste chodili tak, jakž hodné jest na to povolání, kterýmž povoláni jste,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 2, 'Se vší pokorou, tichostí, i s snášelivostí, snášejíce se vespolek v lásce,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 3, 'Usilujíce zachovávati jednotu Ducha v svazku pokoje.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 4, 'Jedno jest tělo, a jeden Duch, jakož i povoláni jste v jedné naději povolání svého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 5, 'Jeden Pán, jedna víra, jeden křest,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 6, 'Jeden Bůh a Otec všech, kterýž jest nade všecko, a skrze všecko, i ve všech vás.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 7, 'Ale jednomu každému z nás dána jest milost podlé míry obdarování Kristova.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 8, 'Protož dí: Vstoupiv na výsost, jaté vedl vězně, a dal dary lidem.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 9, 'Ale to, že vstoupil, co jest, jediné že i sstoupil prvé do nejnižších stran země?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 10, 'Ten pak, kterýž sstoupil, onť jest, kterýž i vstoupil vysoko nade všecka nebesa, aby naplnil všecko.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 11, 'A onť dal některé zajisté apoštoly, některé pak proroky, jiné pak evangelisty, jiné pak pastýře a učitele,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 12, 'Pro spořádání svatých, k dílu služebnosti, pro vzdělání těla Kristova,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 13, 'Až bychom se sběhli všickni v jednotu víry a známosti Syna Božího, v muže dokonalého, v míru postavy plného věku Kristova,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 14, 'Abychom již více nebyli děti, zmítající se a točící každým větrem učení v neustavičnosti lidské, v chytrosti k oklamávání lstivému;');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 15, 'Ale upřímě se majíce v lásce, rosťme v toho všelijak, kterýž jest hlava, totiž v Krista.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 16, 'Z kteréhož všecko tělo příslušně spojené a svázané po všech kloubích přisluhování, podlé vnitřní moci v míru jednoho každého ouda, zrůst, jakž na tělo přísluší, béře, k vzdělání svému v lásce.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 17, 'A protož totoť pravím a osvědčuji skrze Pána, abyste již více nechodili, jako i jiní pohané chodí, v marnosti mysli své,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 18, 'Zatemnění v rozumu, odcizeni jsouce od života Božího, pro neznámost, kteráž jest v nich z zatvrzení srdce jejich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 19, 'Kteříž zoufavše sobě, vydali se v nestydatost, aby všelikou nečistotu páchali s chtivostí.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 20, 'Ale vy ne tak jste se vyučili od Krista,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 21, 'Ač jestliže jste ho slyšeli, a o něm byli vyučeni, jakž jest pravda v Ježíšovi,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 22, 'Totiž, žeť vám náleží složiti ono první obcování podlé toho starého člověka, rušícího se, podlé žádosti oklamávajících,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 23, 'Obnoviti se pak duchem mysli své,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 24, 'A obléci toho nového člověka, podlé Boha stvořeného, v spravedlnosti a v svatosti pravdy.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 25, 'Protož složíce lež, mluvtež pravdu jeden každý s bližním svým; nebo jsme vespolek oudové.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 26, 'Hněvejte se, a nehřešte; slunce nezapadej na hněvivost vaši.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 27, 'Nedávejte místa ďáblu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 28, 'Kdo kradl, již více nekraď, ale raději pracuj, dělaje rukama, což dobrého jest, aby měl, z čeho uděliti nuznému.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 29, 'Žádná řeč mrzutá nevycházej z úst vašich, ale jestli jaká dobrá k vzdělání užitečnému, aby dala milost posluchačům.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 30, 'A nezarmucujte Ducha svatého Božího, kterýmž znamenáni jste ke dni vykoupení.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 31, 'Všeliká hořkost, a rozzlobení se, i hněv, i křik, i rouhání buď odjato od vás, se vší zlostí,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 32, 'Ale buďte k sobě vespolek dobrotiví, milosrdní, odpouštějíce sobě vespolek, jakož i Bůh v Kristu odpustil vám.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 1, 'Buďtež tedy následovníci Boží, jakožto synové milí.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 2, 'A choďte v lásce, jako i Kristus miloval nás, a vydal sebe samého za nás, dar a obět Bohu u vůni rozkošnou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 3, 'Smilstvo pak a všeliká nečistota, neb lakomství, aniž jmenováno buď mezi vámi, jakož sluší na svaté,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 4, 'A mrzkost, ani bláznové mluvení, ani šprymování, kteréžto věci jsou nenáležité, ale raději díků činění.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 5, 'Víte zajisté o tom, že žádný smilník aneb nečistý, ani lakomec, (jenž jest modloslužebník,) nemá dědictví v království Kristově a Božím.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 6, 'Žádný vás nesvoď marnými řečmi; nebo pro takové věci přichází hněv Boží na syny nepoddané.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 7, 'Nebývejtež tedy účastníci jejich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 8, 'Byli jste zajisté někdy temnosti, ale nyní jste světlo v Pánu. Jakožto synové světla choďte,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 9, '(Nebo ovoce Ducha záleží ve vší dobrotě, a spravedlnosti, a v pravdě,)');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 10, 'O to stojíce, což by se dobře líbilo Pánu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 11, 'A neobcujte s skutky neužitečnými tmy, ale raději je trescete.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 12, 'Nebo což se tajně děje od nich, mrzko jest o tom i mluviti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 13, 'Ale to všecko, když bývá od světla trestáno, bývá zjeveno; cožkoli zajisté zjevné bývá, světlo jest.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 14, 'Protož praví: Probuď se ty, kdož spíš, a vstaň z mrtvých, a zasvítíť se tobě Kristus.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 15, 'Viztež tedy, kterak byste opatrně chodili, ne jako nemoudří, ale jako moudří,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 16, 'Vykupujíce čas; nebo dnové zlí jsou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 17, 'Protož nebývejte neopatrní, ale rozumějící, která by byla vůle Páně.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 18, 'A neopíjejte se vínem, v němž jest prostopašnost, ale naplněni buďte Duchem,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 19, 'Mluvíce sobě vespolek v žalmích, a v chvalách, a v písničkách duchovních, zpívajíce a plésajíce v srdcích svých Pánu,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 20, 'Díky činíce vždycky ze všeho ve jménu Pána našeho Jezukrista Bohu a Otci,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 21, 'Poddáni jsouce jedni druhým v bázni Boží.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 22, 'Ženy mužům svým poddány buďte, jako Pánu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 23, 'Nebo muž jest hlava ženy, jako i Kristus hlava církve, a onť jest spasitel těla.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 24, 'A protož jakož církev poddána jest Kristu, tak i ženy mužům svým ve všem.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 25, 'Muži milujte ženy své, jako i Kristus miloval církev, a vydal sebe samého za ni,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 26, 'Aby ji posvětil, očistiv obmytím vody skrze slovo,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 27, 'Aby ji sobě postavil slavnou církev, nemající poškvrny, ani vrásky, neb cokoli takového, ale aby byla svatá, a bez úhony.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 28, 'Takť jsou povinni muži milovati ženy své jako svá vlastní těla. Kdo miluje ženu svou, sebeť samého miluje,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 29, 'Žádný zajisté nikdy těla svého neměl v nenávisti, ale krmí a chová je, jakožto i Pán církev.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 30, 'Neboť jsme oudové těla jeho, z masa jeho, a z kostí jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 31, 'A protoť opustí člověk otce svého i matku, a připojí se k manželce své, i budouť ti dva jedno tělo.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 32, 'Tajemství toto veliké jest, ale já pravím o Kristu a o církvi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 33, 'A však i vy, jeden každý z vás, manželku svou tak jako sám sebe miluj. Žena pak ať se bojí muže.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 1, 'Dítky poslouchejte rodičů svých v Pánu; neboť jest to spravedlivé.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 2, 'Cti otce svého i matku, (toť jest přikázaní první s zaslíbením,)');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 3, 'Aby dobře bylo tobě, a abys byl dlouhověký na zemi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 4, 'A vy otcové nepopouzejte k hněvu dítek svých, ale vychovávejte je v cvičení a v napomínání Páně.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 5, 'Služebníci buďte poslušni pánů tělesných s bázní a s strachem, v sprostnosti srdce svého, jako Krista,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 6, 'Ne na oko sloužíce, jako ti, kteříž se lidem líbiti usilují, ale jako služebníci Kristovi, činíce vůli Boží z té duše,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 7, 'S dobrou myslí sloužíce, jakožto Pánu, a ne lidem,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 8, 'Vědouce, že, což by koli jeden každý učinil dobrého, za to odplatu vzíti má ode Pána, buďto služebník, buďto svobodný.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 9, 'A vy páni též se tak mějte k nim, odpouštějíce pohrůžky, vědouce, že i vy také máte Pána svého v nebesích, a přijímání osob není u něho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 10, 'Dále pak, bratří moji, posilňte se v Pánu a v moci síly jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 11, 'Oblecte se v celé odění Boží, abyste mohli státi proti útokům ďábelským.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 12, 'Neboť není bojování naše proti tělu a krvi, ale proti knížatstvu, proti mocnostem, proti světa pánům temností věku tohoto, proti duchovním zlostem vysoko.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 13, 'A protož vezměte celé odění Boží, abyste mohli odolati v den zlý, a všecko vykonajíce, státi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 14, 'Stůjtež tedy, majíce podpásaná bedra svá pravdou, a oblečeni jsouce v pancíř spravedlnosti,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 15, 'A obuté majíce nohy v hotovost k evangelium pokoje,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 16, 'A zvláště pak vezmouce štít víry, kterýmž byste mohli všecky šípy ohnivé nešlechetníka toho uhasiti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 17, 'Lebku také spasení vezměte, i meč Ducha, jenž jest slovo Boží,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 18, 'Všelikou modlitbou a prosbou modléce se každého času v Duchu, a v tom bedliví jsouce se vší ustavičností a prošením za všecky svaté,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 19, 'I za mne, aby mi dána byla řeč k otevření úst mých s smělou doufanlivostí, abych oznamoval tajemství evangelium,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 20, 'Pro něž úřad konám v řetězu, abych v něm směle mluvil, jakž mně mluviti náleží.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 21, 'Abyste pak věděli i vy, co se se mnou děje, a co činím, všecko vám to oznámí Tychikus, milý bratr a věrný služebník v Pánu,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 22, 'Jehož jsem pro to samo k vám poslal, abyste věděli o našich věcech, a aby potěšil srdcí vašich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 23, 'Pokoj bratřím, a láska s věrou od Boha Otce a Pána Jezukrista.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 24, 'Milost Boží se všechněmi milujícími Pána našeho Jezukrista k neporušitelnosti. Amen.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 1, 'Pavel a Timoteus, služebníci Ježíše Krista, všechněm svatým v Kristu Ježíši, kteříž jsou v městě Filippis, s biskupy a s jahny:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 2, 'Milost vám a pokoj od Boha Otce našeho a Pána Jezukrista.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 3, 'Děkuji Bohu svému, když se koli na vás rozpomenu,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 4, 'Vždycky při každé modlitbě své, s radostí za všecky za vás prosbu čině,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 5, 'Z vašeho obcování evangelium, hned od prvního dne až posavad,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 6, 'Jist jsa tím, že ten, kterýž začal v vás dílo dobré, dokoná až do dne Ježíše Krista,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 7, 'Jakož jest mi spravedlivé tak smysliti o všech vás, proto že vás v srdci mám i v vězení svém, a v obraňování i v utvrzování evangelium, vás všecky účastníky milosti mně dané.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 8, 'Svědek mi jest zajisté Bůh, kterak po všech po vás toužím v střevách Ježíše Krista.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 9, 'A za to se modlím, aby láska vaše ještě více a více se rozhojňovala v známosti a ve všelikém smyslu,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 10, 'K tomu, abyste zkušením rozeznati mohli užitečné věci od neužitečných, tak abyste byli upřímí a bez úrazu, až ke dni Kristovu,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 11, 'Naplněni jsouce ovocem spravedlnosti, kteréž nesete skrze Jezukrista, k slávě a k chvále Boží.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 12, 'Chciť pak, bratří, abyste věděli, že to, což mne obklíčilo, k většímu prospěchu evangelium přišlo,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 13, 'Tak že vězení mé pro Krista rozhlášeno jest po všem rathouzu, i jinde všudy.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 14, 'A mnozí z bratří v Pánu, spolehše na vězení mé, hojnější smělost mají bez strachu mluviti slovo.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 15, 'A však někteří z závisti a navzdoru, někteří pak také z oblíbení Krista káží.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 16, 'Ti pak, kteříž navzdoru Krista zvěstují, ne v čistotě, domnívají se, že mi k vězení mému ssoužení přidadí;');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 17, 'Kteří pak z lásky, ti vědí, že jsem k obraně evangelium postaven.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 18, 'Ale což pak o to? Nýbrž jakýmkoli způsobem, buď v samé tvárnosti, buď v pravdě Kristus se zvěstuje, i z tohoť se raduji, a ještě radovati budu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 19, 'Nebo vím, že mi to přijde k spasení skrze vaši modlitbu, a pomoc Ducha Jezukristova,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 20, 'Podlé pečlivého očekávání a naděje mé, že v ničem nebudu zahanben, ale ve vší doufanlivé smělosti, jakž prvé vždycky, tak i nyní veleben bude Kristus na těle mém, buď skrze život, buď skrze smrt.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 21, 'Mně zajisté živu býti jest Kristus, a umříti zisk.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 22, 'Jestli mi pak prospěšněji živu býti v těle pro práci, tedy nevím, co bych vyvolil.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 23, 'K obémuť se k tomu nakloňuji, žádost maje umříti, a býti s Kristem, což by mnohem lépe bylo,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 24, 'Ale pozůstati v těle potřebněji jest pro vás.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 25, 'Načež spoléhaje, vím, že pobudu, a s vámi se všemi spolu pozůstanu k vašemu prospěchu, a k radosti víry,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 26, 'Aby se vaše ze mne chlouba v Kristu Ježíši rozhojnila, skrze mou vám zase přítomnost.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 27, 'Toliko, jakž sluší evangelium Kristovu, obcujte, abych, buď přijda a vás vida, buď vzdálen jsa, slyšel o vás, že stojíte v jednom duchu, jednomyslně pracujíce u víře evangelium,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 28, 'A v ničemž se nestrachujíce protivníků, což jest jim jistým znamením zahynutí, vám pak spasení, a to od Boha.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 29, 'Nebo vám jest to z milosti dáno pro Krista, abyste netoliko v něho věřili, ale také pro něj i trpěli,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 30, 'Týž boj majíce, jakýž jste při mně viděli, i nyní o mně slyšíte.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 1, 'Protož jestli jaké potěšení v Kristu, jestli které utěšení lásky, jestli která společnost Ducha, jsou-li která střeva a slitování,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 2, 'Naplňte radost mou, abyste jednostejného smyslu byli, jednostejnou lásku majíce, jednodušní jsouce, jednostejně smýšlejíce,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 3, 'Nic nečiníce skrze svár aneb marnou chválu, ale v pokoře jedni druhé za důstojnější nežli sebe majíce.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 4, 'Nehledejte jeden každý jen svých věcí, ale každý také toho, což jest jiných.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 5, 'To tedy, ciťte při sobě, co i při Kristu Ježíši.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 6, 'Kterýž jsa v způsobu Božím, nepoložil sobě toho za loupež rovný býti Bohu,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 7, 'Ale samého sebe zmařil, způsob služebníka přijav, podobný lidem učiněn.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 8, 'A v způsobu nalezen jako člověk, ponížil se, poslušný byv až do smrti, a to smrti kříže.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 9, 'Protož i Bůh povýšil ho nade vše, a dal jemu jméno nad každé jméno,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 10, 'Aby ve jménu Ježíše každé koleno klekalo, těch, kteříž jsou na nebesích, a těch, kteříž jsou na zemi, i těch, kteříž jsou pod zemí,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 11, 'A každý jazyk aby vyznával, že Ježíš Kristus jest Pánem v slávě Boha Otce.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 12, 'A tak, moji milí, jakož jste vždycky poslušni byli, netoliko v přítomnosti mé, ale nyní mnohem více v nepřítomnosti mé, s bázní a s třesením spasení své konejte.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 13, 'Bůh zajisté jest, kterýž působí v vás i chtění i skutečné činění, podlé dobře libé vůle své.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 14, 'Všecko čiňte bez reptání, a bez pochybování,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 15, 'Abyste byli bez úhony, a upřímí synové Boží, bez obvinění u prostřed národu zlého a převráceného. Mezi kterýmižto svěťte jako světla na světě,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 16, 'Slovo života zachovávajíce, ku poctivosti mé v den Kristův, že jsem ne nadarmo běžel, ani nadarmo pracoval.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 17, 'A bychť pak i obětován byl pro obět a službu víře vaší, raduji se, a spolu raduji se se všechněmi vámi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 18, 'A též i vy radujte se, a spolu radujte se se mnou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 19, 'Mámť pak naději v Pánu Ježíši, že Timotea brzy pošli vám, abych i já pokojné mysli byl, zvěda, kterak vy se máte.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 20, 'Nebo žádného tak jednomyslného nemám, kterýž by tak vlastně o vaše věci pečoval.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 21, 'Všickni zajisté svých věcí hledají, a ne těch, kteréž jsou Krista Ježíše.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 22, 'Ale jej zkušeného býti víte, že jako syn s otcem, se mnou přisluhoval v evangelium.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 23, 'Tohoť hle, naději mám, že pošli, jakž jen uzřím, co se bude díti se mnou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 24, 'Mámť pak naději v Pánu, že i sám brzo přijdu k vám.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 25, 'Ale zdálo se mi za potřebné Epafrodita, bratra a pomocníka a spolurytíře mého, vašeho pak apoštola i služebníka, v potřebě mé poslati k vám,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 26, 'Poněvadž toužil po všech vás, a velmi těžek nad tím byl, že jste o něm slyšeli, že by byl nemocen.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 27, 'A bylť jistě nemocen, i blízek smrti, ale Bůh se nad ním smiloval, a ne nad ním toliko, ale i nade mnou, abych zámutku na zámutek neměl.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 28, 'Protož tím chtivěji poslal jsem ho, abyste, vidouce jej zase, radovali se, a já abych byl bez zámutku.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 29, 'Přijmětež jej tedy v Pánu se vší radostí, a mějtež takové v poctivosti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 30, 'Neboť pro dílo Kristovo až k smrti se přiblížil, opováživ se života, aby doplnil to, v čemž jste vy měli nedostatek při posloužení mně.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 1, 'Dále pak, bratří moji, radujte se v Pánu. Jednostejných vám věcí psáti mně se jistě nestýště, vám pak to bezpečné jest.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 2, 'Vizte psy, vizte zlé dělníky, vizte roztržku.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 3, 'Neboť myť jsme obřízka, kteříž duchem sloužíme Bohu, a chlubíme se v Kristu Ježíši, a nedoufáme v těle,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 4, 'Ačkoli i já mohl bych doufati v těle. Zdá-liť se komu jinému, že by mohl doufati v těle, já více,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 5, 'Obřezán jsa osmého dne, jsa z rodu Izraelského, pokolení Beniaminova, Žid z Židů, podlé zákona farizeus,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 6, 'A z strany horlivosti protivník církve, z strany pak spravedlnosti zákonní jsa bez úhony.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 7, 'Ale to, což mi bylo ziskem, položil jsem sobě pro Krista za škodu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 8, 'Nýbrž i všecky věci pokládám škodou býti pro vyvýšenost známosti Krista Ježíše Pána svého, pro nějž jsem to všecko ztratil, a mám to jako za lejna, abych Krista získal,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 9, 'A v něm nalezen byl nemající své spravedlnosti, kteráž jest z zákona, ale tu, kteráž jest z víry Kristovy, tu spravedlnost, kteráž jest z Boha, a u víře záleží,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 10, 'Abych poznal jej, a moc vzkříšení jeho, i společnost utrpení jeho, připodobňuje se k smrti jeho,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 11, 'Zda bych tak přišel k vzkříšení z mrtvých.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 12, 'Ne že bych již dosáhl, aneb již dokonalým byl, ale snažně běžím, zda bych i uchvátiti mohl, načež uchvácen jsem od Krista Ježíše.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 13, 'Bratří, jáť nemám za to, že bych již dosáhl.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 14, 'Ale to jedno činím, na ty věci, kteréž jsou za mnou, zapomínaje, k těm pak, kteréž jsou přede mnou, úsilně chvátaje, k cíli běžím, k odplatě svrchovaného povolání Božího v Kristu Ježíši.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 15, 'Protož kteřížkoli jsme dokonalí, to smýšlejme. A pakli v čem jinak smyslíte, i toť vám Bůh zjeví.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 16, 'Ale k čemuž jsme již přišli, v tom při jednostejném zůstávejme pravidle, a jednostejně smyslme.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 17, 'Spolunásledovníci moji buďte, bratří, a šetřte těch, kteříž tak chodí, jakož máte příklad na nás.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 18, 'Neboť mnozí chodí, o nichž jsem častokrát pravil vám, a nyní s pláčem pravím, že jsou nepřátelé kříže Kristova,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 19, 'Jichžto konec jest zahynutí, jejichž Bůh jest břicho, a sláva v mrzkostech jejich, kteříž o zemské věci stojí.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 20, 'Ale naše obcování jest v nebesích, odkudž i spasitele očekáváme Pána Jezukrista,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 21, 'Kterýž promění tělo naše ponížené, aby bylo podobné k tělu slávy jeho, podlé mocnosti té, kterouž mocen jest i všecky věci podmaniti sobě.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 1, 'A tak, bratří moji milí a přežádoucí, radost a koruno má, tak stůjte v Pánu, milí.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 2, 'Evody prosím, i Syntychény prosím, aby jednostejně smyslily v Pánu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 3, 'Ano i tebe prosím, tovaryši můj vlastní, budiž jim pomocen, kteréžto v evangelium spolu se mnou pracovaly, i spolu s Klimentem a s jinými pomocníky mými, jejichž jména jsou v knize života.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 4, 'Radujte se v Pánu vždycky; opět pravím, radujte se.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 5, 'Mírnost vaše známa buď všechněm lidem. Pán blízko.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 6, 'O nic nebuďte pečliví, ale ve všech věcech skrze modlitbu a poníženou žádost s díků činěním prosby vaše známy buďte Bohu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 7, 'A pokoj Boží, kterýž převyšuje všeliký rozum, hájiti bude srdcí vašich i smyslů vašich v Kristu Ježíši.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 8, 'Dále pak, bratří, kterékoli věci jsou pravé, kterékoli poctivé, kterékoli spravedlivé, kterékoli čisté, kterékoli milé, kterékoli dobropověstné, jestli která ctnost, a jestli která chvála, o těch věcech přemyšlujte.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 9, 'Kterýmž jste se i naučili, je i přijali, a slyšeli i viděli na mně. Ty věci čiňte, a Bůh pokoje budeť s vámi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 10, 'Zradoval jsem se v Pánu velice, že již opět zase rozzelenala se péče vaše o mne. Načež však byli jste myslili, ale nedostalo se vám příhodného času.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 11, 'Ne proto, že bych jakou nouzi měl, toto pravím; nebo já naučil jsem se dosti míti na tom, což mám.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 12, 'Umímť i snížen býti, umím také i hojnost míti; všudy a ve všech věcech pocvičen jsem, i nasycen býti i lačněti, totiž hojnost míti i nouzi trpěti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 13, 'Všecko mohu v Kristu, kterýž mne posiluje.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 14, 'A však dobře jste učinili, obcovavše mému ssoužení.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 15, 'Víte pak i vy, Filipenští, že při počátku evangelium, když jsem šel z Macedonie, žádný zbor neudělil mi z strany dání a vzetí, než vy sami.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 16, 'Ano i do Tessaloniky jednou i podruhé, čehož jsem potřeboval, poslali jste mi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 17, 'Ne proto že bych hledal darů, ale hledám užitku hojného k vašemu prospěchu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 18, 'Přijalť jsem pak všecko, a hojněť mám, naplněnť jsem, vzav od Epafrodita to, což posláno od vás, vůni sladkosti, obět vzácnou a libou Bohu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 19, 'Bůh pak můj naplníť všelikou potřebu vaši podlé bohatství svého slavně v Kristu Ježíši.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 20, 'Bohu pak a Otci našemu sláva na věky věků. Amen.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 21, 'Pozdravtež všech svatých v Kristu Ježíši. Pozdravujíť vás bratří, kteříž jsou se mnou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 22, 'Pozdravujíť vás všickni svatí, zvláště pak ti, kteříž jsou z domu císařova.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 23, 'Milost Pána našeho Jezukrista se všechněmi vámi. Amen.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 1, 'Pavel apoštol Ježíše Krista, skrze vůli Boží, a Timoteus,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 2, 'Těm, kteříž jsou v Kolossis, svatým a věrným bratřím v Kristu Ježíši: Milost vám a pokoj od Boha Otce našeho a Pána Ježíše Krista.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 3, 'Díky činíme Bohu a Otci Pána našeho Jezukrista, vždycky za vás modléce se,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 4, 'Slyšavše o víře vaší v Kristu Ježíši, a o lásce ke všechněm svatým,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 5, 'Pro naději složenou vám v nebesích, o níž jste prvé slyšeli v slovu pravdy, to jest evangelium.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 6, 'Kteréž jest přišlo k vám, jako i na všecken svět, a ovoce nese, jako i u vás od toho dne, v kterémž jste slyšeli, a poznali milost Boží v pravdě,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 7, 'Jakož jste se i naučili od Epafry, milého spoluslužebníka našeho, kterýž jest věrný k vám služebník Kristův,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 8, 'Kterýž také oznámil nám lásku vaši v Duchu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 9, 'Protož i my, od toho dne, jakž jsme to uslyšeli, nepřestáváme modliti se za vás a žádati, abyste naplněni byli známostí vůle jeho ve vší moudrosti a rozumnosti duchovní,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 10, 'Abyste chodili hodně Pánu ke vší jeho líbeznosti, v každém skutku dobrém, ovoce vydávajíce a rostouce v známosti Boží,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 11, 'Všelikou mocí zmocněni jsouce, podlé síly slávy jeho, ke vší trpělivosti a dobrotivosti s radostí,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 12, 'Díky činíce Otci, kterýž hodné nás učinil účastnosti losu svatých v světle,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 13, 'Kterýž vytrhl nás z moci temnosti, a přenesl do království milého Syna svého,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 14, 'V němž máme vykoupení skrze krev jeho, totiž odpuštění hříchů,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 15, 'Kterýž jest obraz Boha neviditelného, prvorozený všeho stvoření.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 16, 'Nebo skrze něho stvořeny jsou všecky věci, kteréž jsou na nebi i na zemi, viditelné i neviditelné, buďto trůnové neb panstva, buďto knížatstva neb mocnosti; všecko skrze něho a pro něho stvořeno jest.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 17, 'A on jest přede vším, a všecko jím stojí.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 18, 'A onť jest hlava těla církve, kterýž jest počátek a prvorozený z mrtvých, aby tak on ve všem prvotnost držel,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 19, 'Poněvadž se zalíbilo Otci, aby v něm všecka plnost přebývala,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 20, 'A skrze něho aby smířil s sebou všecko, v pokoj uvodě skrze krev kříže jeho, skrze něj, pravím, buďto ty věci, kteréž jsou na zemi, buď ty, kteréž jsou na nebi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 21, 'Ano i vás, někdy odcizené a nepřátely v mysli, skrze skutky zlé, nyní již smířil,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 22, 'Tělem svým skrze smrt, aby vás postavil svaté, a nepoškvrněné, a bez úhony před oblíčejem svým,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 23, 'Však jestliže zůstáváte u víře založení a pevní, a neuchylujete se od naděje evangelium, kteréž jste slyšeli, jenž jest kázáno všemu stvoření, kteréž jest pod nebem, jehož já Pavel učiněn jsem služebník.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 24, 'Kterýž nyní raduji se z utrpení svých pro vás, a doplňuji ostatky ssoužení Kristových na těle svém za jeho tělo, jenž jest církev,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 25, 'Jejíž učiněn jsem já služebník, tak jakž mi to svěřil Bůh na to, abych vám sloužil, a tak naplnil slovo Boží,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 26, 'To tajemství skryté od věků a národů, nyní pak zjevené svatým jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 27, 'Jimžto Bůh ráčil známo učiniti, kteraké by bylo bohatství slavného tajemství tohoto mezi pohany, jenž jest Kristus v vás, ta naděje slávy,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 28, 'Kteréhož my zvěstujeme, napomínajíce všelikého člověka, a učíce všelikého člověka ve vší moudrosti, abychom postavili každého člověka dokonalého v Kristu Ježíši.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 29, 'O čež i pracuji, bojuje podlé té jeho mocnosti, kteráž dělá ve mně mocně.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 1, 'Chciť zajisté, abyste věděli, jakou nesnáz mám o vás, a o ty, kteříž jsou v Laodicii, a kteřížkoli neviděli tváři mé podlé těla,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 2, 'Aby potěšena byla srdce jejich, spojená v lásce, a to ke všemu bohatství přejistého smyslu, ku poznání tajemství Boha i Otce i Krista,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 3, 'V němž jsou skryti všickni pokladové moudrosti a známosti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 4, 'A totoť pravím, aby vás žádný, falešně dovodě, neoklamal podobnou k pravdě řečí.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 5, 'Nebo ačkoli vzdálen jsem tělem, však duchem s vámi jsem, raduje se, a vida řád váš, a utvrzení té víry vaší v Krista.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 6, 'Protož jakž jste přijali Krista Ježíše Pána, tak v něm choďte,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 7, 'Vkořenění a vzdělaní na něm, a utvrzení u víře, jakž jste naučeni, rozhojňujíce se v ní s díků činěním.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 8, 'Hleďtež, aťby vás někdo neobloupil moudrostí světa, a marným zklamáním, uče podlé ustanovení lidských, podlé živlů světa, a ne podlé Krista.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 9, 'Nebo v něm přebývá všecka plnost Božství tělesně.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 10, 'A v něm jste doplněni, kterýž jest hlava všeho knížatstva i mocnosti,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 11, 'V němž i obřezáni jste obřezáním ne rukou učiněným, svlékše tělo hříchů skrze obřezání Kristovo,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 12, 'Pohřbeni jsouce s ním skrze křest, skrze nějž i spolu s ním z mrtvých vstali jste skrze víru, kteráž jest mocné dílo Boží, kterýž vzkřísil jej z mrtvých.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 13, 'Ano i vás, mrtvé v hříších a v neobřízce těla vašeho, spolu s ním obživil, odpustiv vám všecky hříchy,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 14, 'A smazav proti nám ten zápis záležející v ustanoveních, kterýž byl odporný nám. I vyzdvihl jej z prostředku, přibiv jej k kříži;');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 15, 'A obloupiv knížatstva i moci, vedl je na odivu zjevně, triumf slaviv nad nimi skrze něj.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 16, 'Protož žádný vás nesuď pro pokrm, aneb pro nápoj, aneb z strany svátku, neb novuměsíce, aneb sobot.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 17, 'Kteréžto jsou stín věcí budoucích, ale pravda tělo jest Kristovo.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 18, 'Nižádný vás nepředchvacuj svémyslně pokorou a náboženstvím andělským, v to, čehož neviděl, se vydávaje, a marně se nadýmaje smyslem těla svého,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 19, 'A nedrže se hlavy, od níž všecko tělo po kloubích a svazích vzdělané a spojené roste Božím zrůstem.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 20, 'Jestliže tedy zemřeli jste s Kristem živlům světa, proč, jako byste živi byli světu, těmi ceremoniemi dáte se obtěžovati,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 21, '(Když se říká: Nedotýkej se, ani okoušej, aniž se s tím obírej?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 22, 'Kteréžto všecky věci samým užíváním jich kazí se,) podlé přikázaní a učení lidských.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 23, 'Kteréžto věci mají sic tvárnost moudrosti, v způsobu té nábožnosti, a v pokoře pošmourné, i v neodpuštění tělu, a však nejsou v žádné platnosti, toliko k nasycení těla.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 1, 'Protož povstali-li jste s Kristem, vrchních věcí hledejte, kdež Kristus na pravici Boží sedí.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 2, 'O svrchní věci pečujte, ne o zemské.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 3, 'Nebo zemřeli jste, a život váš skryt jest s Kristem v Bohu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 4, 'Když se pak ukáže Kristus, život náš, tehdy i vy ukážete se s ním v slávě.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 5, 'Protož mrtvěte oudy své zemské, smilstvo, nečistotu, chlipnost, žádost zlou, i lakomství, jenž jest modlám sloužení.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 6, 'Pro kteréž věci přichází hněv Boží na syny zpurné.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 7, 'V kterýchž i vy někdy chodili jste, když jste živi byli v nich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 8, 'Ale nyní složtež i vy všecko to, hněv, prchlivost, zlobivost, zlořečení, i mrzkomluvnost z úst svých.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 9, 'Nelžete jedni na druhé, když jste svlékli s sebe starého člověka s skutky jeho,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 10, 'A oblékli toho nového, obnovujícího se k známosti, podlé obrazu toho, kterýž jej stvořil,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 11, 'Kdežto není Řek a Žid, obřízka a neobřízka, cizozemec a Scýta, služebník a svobodný, ale všecko a ve všech Kristus.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 12, 'Protož oblectež se jako vyvolení Boží, svatí, a milí, v střeva milosrdenství, v dobrotivost, nízké o sobě smýšlení, krotkost, trpělivost,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 13, 'Snášejíce jeden druhého, a odpouštějíce sobě vespolek, měl-li by kdo proti komu žalobu. Jako i Kristus odpustil vám, tak i vy.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 14, 'Nadto pak nade všecko v lásku, kteráž jest svazek dokonalosti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 15, 'A pokoj Boží vítěziž v srdcích vašich, k němuž i povoláni jste v jedno tělo; a buďtež vděčni.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 16, 'Slovo Kristovo přebývejž v vás bohatě se vší moudrostí, učíce a napomínajíce sebe vespolek žalmy, a zpěvy, a písničkami duchovními, s milostí zpívajíce v srdci svém Pánu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 17, 'A všecko, cožkoli činíte v slovu neb v skutku, všecko čiňte ve jménu Pána Ježíše, díky činíce Bohu a Otci skrze něho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 18, 'Ženy poddány buďte mužům svým tak, jakž sluší, v Pánu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 19, 'Muži milujte ženy své, a nemějte se přísně k nim.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 20, 'Dítky poslouchejte rodičů ve všem; nebo to jest dobře libé Pánu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 21, 'Otcové nepopouzejte k hněvivosti dítek svých, aby sobě nezoufaly.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 22, 'Služebníci poslušni buďte ve všem pánů tělesných, ne na oko sloužíce, jako ti, jenž se usilují lidem líbiti, ale v sprostnosti srdce, bojíce se Boha.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 23, 'A všecko, což byste koli činili, z té duše čiňte, jako Pánu, a ne lidem,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 24, 'Vědouce, že ode Pána vzíti máte odplatu dědictví; nebo Pánu Kristu sloužíte.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 25, 'Kdož by pak nepravost páchal, odměnu své nepravosti vezme. A neníť přijímání osob u Boha.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 1, 'Páni spravedlivě a slušně s služebníky nakládejte, vědouce, že i vy Pána máte v nebesích.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 2, 'Na modlitbě buďte ustaviční, bdíce v tom s díků činěním,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 3, 'Modléce se spolu i za nás, aby Bůh otevřel nám dvéře slova, k mluvení o tajemství Kristovu, pro něž i v vězení jsem,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 4, 'Abych je zjevoval, tak jakž mi náleží mluviti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 5, 'Choďtež v moudrosti před těmi, kteříž jsou vně, čas kupujíce.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 6, 'Řeč vaše vždycky budiž příjemná, ozdobená solí, tak abyste věděli, kterak byste měli jednomu každému odpovědíti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 7, 'O věcech mých o všech oznámí vám Tychikus, bratr milý, a věrný slouha, a spoluslužebník v Pánu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 8, 'Kteréhož jsem poslal k vám pro to samo, aby zvěděl, co se děje u vás, a potěšil srdcí vašich,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 9, 'S Onezimem, věrným a milým bratrem, kterýž jest tam od vás. Tiť vám všecko oznámí, co se děje u nás.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 10, 'Pozdravuje vás Aristarchus, spoluvězeň můj, a Marek, sestřenec Barnabášův, (o kterémž jsem vám poručil; přišel-li by k vám, přijmětež jej;)');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 11, 'A Jezus, kterýž slove Justus, kteříž jsou Židé. Ti toliko jsou pomocníci moji v království Božím, kteříž byli mé potěšení.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 12, 'Pozdravuje vás Epafras, kterýž od vás jest, slouha Kristův, kterýž vždycky úsilně pracuje na modlitbách za vás, abyste stáli dokonalí a plní ve vší vůli Boží.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 13, 'Nebo svědectví jemu vydávám, žeť vás velmi horlivě miluje, a též i ty, kteříž jsou v Laodicii, i kteříž jsou v Hierapoli.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 14, 'Pozdravuje vás Lukáš lékař milý a Démas.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 15, 'Pozdravte bratří Laodicenských, i Nymfy, i té církve, kteráž jest v domě jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 16, 'A když bude přečten u vás tento list, spravtež to, ať jest i v Laodicenském zboru čten; a ten, kterýž jest psán z Laodicie, i vy také přečtěte.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 17, 'A rcete Archippovi: Viz, abys služebnost, kterouž jsi přijal od Pána, vyplnil.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 18, 'Pozdravení mou rukou Pavlovou. Pamatujtež na mé vězení. Milost Boží s vámi. Amen.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 1, 1, 'Pavel a Silván a Timoteus církvi Tessalonicenských v Bohu Otci a Pánu Ježíši Kristu: Milost vám a pokoj od Boha Otce našeho a Pána Jezukrista.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 1, 2, 'Díky činíme Bohu vždycky ze všech vás, zmínku činíce o vás na modlitbách svých.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 1, 3, 'Bez přestání pamatujíce na skutek víry vaší a na práci lásky, a na trpělivost naděje Pána našeho Jezukrista, před Bohem a Otcem naším,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 1, 4, 'Vědouce, bratří Bohu milí, o vyvolení vašem.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 1, 5, 'Nebo evangelium naše k vám nezáleželo toliko v slovu, ale i v moci, i v Duchu svatém, a v jistotě mnohé, jakož víte, jací jsme byli mezi vámi pro vás.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 1, 6, 'A vy následovníci naši i Páně učiněni jste, přijavše slovo ve mnohé úzkosti, s radostí Ducha svatého,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 1, 7, 'Tak že jste učiněni příklad všem věřícím v Macedonii a v Achaii.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 1, 8, 'Nebo od vás rozhlásilo se slovo Páně netoliko v Macedonii a v Achaii, ale i na všelikém místě víra vaše, kteráž jest v Boha, roznesla se, tak že nepotřebí nám o tom nic mluviti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 1, 9, 'Oniť zajisté sami o nás vypravují, jaký byl příchod náš k vám, a kterak jste se obrátili k Bohu od modl, abyste sloužili Bohu živému a pravému,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 1, 10, 'A očekávali Syna jeho s nebe, kteréhož vzkřísil z mrtvých, totiž Ježíše, kterýž vysvobodil nás od hněvu budoucího.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 1, 'Nebo vy sami víte, bratří, že příchod náš k vám nebyl daremný.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 2, 'Ale i prvé trpěvše, i pohanění snáševše, (jakož víte,) v městě Filippis, osvobodili jsme se v Bohu svém mluviti vám směle evangelium Boží s mnohými odpory.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 3, 'Napomínání zajisté naše nebylo z podvodu, ani z nečistoty, ani ve lsti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 4, 'Ale jakož Bůh nás oblíbil, aby nám svěřeno bylo evangelium, takť mluvíme, ne jako lidem se líbíce, ale Bohu, kterýž libuje srdce naše.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 5, 'Anižť jsme zajisté kdy užívali řeči pochlebné, jakož víte, ani za příčinou něčeho lakomství provodili. Bůhť jest svědek.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 6, 'Ani jsme hledali od lidí chvály, ani od vás, ani od jiných, ač jsme mohli vás obtěžovati, jako Kristovi apoštolé.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 7, 'Ale byli jsme tiší mezi vámi, jako když matka chová dítky své.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 8, 'Tak nakloněni k vám byvše, hotovi jsme byli s velikou chutí vydati vám netoliko evangelium Boží, ale také i duše své, proto že jste nám byli milí.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 9, 'Nebo pamatujete, bratří, na práci naši a ustávání. Ve dne i v noci zajisté pracovavše, proto abychom žádného z vás neobtěžovali, kázali jsme u vás evangelium Boží.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 10, 'Vy jste svědkové i Bůh, žeť jsme svatě, a spravedlivě, a bez úhony obcovali mezi vámi, kteříž jste uvěřili,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 11, 'Jakož víte, že jednoho každého z vás, jako otec dítek svých, napomínali jsme a potěšovali,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 12, 'I s osvědčováním, abyste chodili hodně Bohu, kterýž povolal vás do království svého a v slávu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 13, 'Protož i my díky činíme Bohu bez přestání, že přijavše slovo Boží, kteréž jste slyšeli od nás, přijali jste ne jako slovo lidské, ale (jakož v pravdě jest,) jako slovo Boží, kterýž i dílo své působí v vás věřících.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 14, 'Vy zajisté, bratří, následovníci učiněni jste církví Božích, kteréž jsou v Židovstvu v Kristu Ježíši; nebo jste takovéž věci i vy trpěli od svého pokolení, jako i oni od Židů.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 15, 'Kteříž i Pána Ježíše zabili, i své vlastní proroky, a nás vyhnali, a Bohu se nelíbí, a všechněm lidem jsou odporní,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 16, 'Nedopouštějíce nám mluviti pohanům, aby spaseni byli, aby tak vždy doplňovali hříchy své. Nebo vylit jest na ně hněv konečný.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 17, 'My pak, bratří, zbaveni byvše vás na chvíli, tělem ne srdcem, opravdověji usilovali jsme viděti tvář vaši s mnohou žádostí.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 18, 'Protož chtěli jsme přijíti k vám, (zvláště já Pavel,) jednou i podruhé, ale překazil nám satan.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 19, 'Nebo která jest naše naděje neb radost aneb koruna chlouby? Zdali ne i vy před oblíčejem Pána našeho Jezukrista v příchodu jeho?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 20, 'Vy jistě jste sláva naše i radost.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 3, 1, 'Protož nemohše se déle zdržeti, za nejlepší se nám vidělo, abychom v Atenách pozůstali my sami.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 3, 2, 'A poslali jsme Timotea, bratra svého, a služebníka Božího, a pomocníka svého v evangelium Kristovu, aby potvrdil vás, a napomenul k tomu, což náleží k víře vaší,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 3, 3, 'Aby se žádný nepohnul v takových těchto ssouženích. Nebo i sami víte, že jsme k tomu postaveni.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 3, 4, 'Ještě zajisté, když jsme u vás byli, předpovídali jsme vám, že budeme ssouženi. Jakož se i stalo, jakž víte.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 3, 5, 'Protož i já, nemoha se déle zdržeti, poslal jsem, abych zvěděl o víře vaší, aťby snad nějak nepokoušel vás ten pokušitel, i byla by daremná práce naše.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 3, 6, 'Nyní pak když k nám přišel Timoteus od vás, a zvěstoval nám novinu veselou o víře a lásce vaší, a že nás připomínáte dobře, žádajíce vždycky nás viděti, jako i my vás,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 3, 7, 'Protož potěšeni jsme, bratří, z vás ve všelikém ssoužení a nesnadnosti své skrze víru vaši.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 3, 8, 'Nebo aj, živi jsme, jestliže vy stojíte v Pánu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 3, 9, 'A jakým děkováním z vás můžeme se odměniti Bohu za všecku tu radost, kterouž radujeme se pro vás před Bohem svým,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 3, 10, 'Dnem i noci přehorlivě modléce se, abychom uzřeli tvář vaši, a doplnili to, čehož by se nedostávalo víře vaší?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 3, 11, 'Sám pak Bůh a Otec náš, a Pán náš Ježíš Kristus spraviž cestu naši k vám.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 3, 12, 'Vás pak ten Pán račiž rozmnožiti a rozhojniti v lásce k sobě vespolek, i ke všechněm, jako i nás k vám,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 3, 13, 'Aby tak utvrzena byla srdce vaše nepoškvrněná v svatosti, před Bohem a Otcem naším, ku příští Pána našeho Jezukrista, se všechněmi svatými jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 1, 'Dále pak, bratří, prosíme vás, a napomínáme v Pánu Ježíši, jakož jste přijali od nás, kterak byste měli choditi, a líbiti se Bohu, v tom abyste se rozhojnili více.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 2, 'Víte zajisté, jaká přikázaní vydali jsme vám skrze Pána Ježíše.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 3, 'Tať jest zajisté vůle Boží, totiž posvěcení vaše, abyste se zdržovali od smilstva,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 4, 'A aby uměl jeden každý z vás svým osudím vládnouti v svatosti a v poctivosti,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 5, 'Ne v líbosti žádostí jako i pohané, kteříž Boha neznají;');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 6, 'A aby neutiskal ani oklamával v jednání bratra svého, proto že mstitel jest Pán všeho toho, jakož i předpověděli jsme vám, a osvědčili.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 7, 'Nebo nepovolal nás Bůh k nečistotě, ale ku posvěcení.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 8, 'A protož kdo tím pohrdá, ne člověkem pohrdá, ale Bohem, kterýž i nám dal Ducha svého svatého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 9, 'O lásce pak bratrské není potřebí psáti vám; nebo jste vy od Boha naučeni, abyste milovali jedni druhé.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 10, 'A jistě činíte to všechněm bratřím ve vší Macedonii. Napomínámeť pak vás, bratří, abyste se v tom více rozhojnili,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 11, 'A snažili se pokojni býti, a hleděti toho, což komu náleží, a pracovati rukama svýma vlastníma, jakož jsme přikázali vám,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 12, 'Abyste poctivě chodili před těmi, kteříž jsou vně, a v ničemž abyste neměli nedostatku.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 13, 'Nechciť pak, abyste nevěděli, bratří, o těch, kteříž zesnuli, abyste se nermoutili, jako i jiní, kteříž naděje nemají.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 14, 'Nebo jakož věříme, že Ježíš umřel, a z mrtvých vstal, takť Bůh i ty, kteříž by zesnuli v Ježíšovi, přivede s ním.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 15, 'Toto zajisté vám pravíme slovem Páně, že my, kteříž živi pozůstaneme do příchodu Páně, nepředejdeme těch, kteříž zesnuli.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 16, 'Nebo sám ten Pán s zvukem ponoukajícím, s hlasem archanděla a s troubou Boží sstoupí s nebe, a mrtví v Kristu vstanou nejprvé.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 17, 'Potom my živí pozůstavení spolu s nimi zachváceni budeme do oblaků, vstříc Pánu v povětří, a tak vždycky se Pánem budeme.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 18, 'A protož potěšujte jedni druhých těmito slovy.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 1, 'O časích pak a chvilech, bratří, nepotřebujete, aby vám psáno bylo.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 2, 'Nebo vy sami výborně víte, že ten den Páně jako zloděj v noci, tak přijde.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 3, 'Nebo když dějí: Pokoj a bezpečnost, tedy rychle přijde na ně zahynutí, jako bolest ženě těhotné, a neujdouť.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 4, 'Ale vy, bratří, nejste ve tmě, aby vás ten den jako zloděj zachvátil.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 5, 'Všickni vy synové světla jste, a synové dne. Nejsmeť noci, ani tmy.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 6, 'Nespěmež tedy, jako jiní, ale bděme, a střízliví buďme.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 7, 'Nebo kteříž spí, v noci spí, a kteříž se opíjejí, v noci opilí jsou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 8, 'Ale my, synové dne jsouce, střízliví buďme, oblečeni jsouce v pancíř víry a lásky, a v lebku naděje spasení.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 9, 'Nebo nepostavil nás Bůh k hněvu, ale k nabytí spasení, skrze Pána našeho Jezukrista,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 10, 'Kterýž umřel za nás, abychom, buď že bdíme, buď že spíme, spolu s ním živi byli.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 11, 'Protož napomínejte se vespolek, a vzdělávejte jeden druhého, jakož i činíte.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 12, 'Prosímeť pak vás, bratří, znejtež ty, kteříž pracují mezi vámi, a předloženi jsou vám v Pánu, a napomínají vás,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 13, 'A velice je milujte pro práci jejich. A mějte se k sobě vespolek pokojně.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 14, 'Prosímeť pak vás, bratří, napomínejte z řádu vystupujících, potěšujte choulostivých, snášejte mdlé, trpělivě se mějte ke všechněm.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 15, 'Vizte, aby někdo zlého za zlé neodplacoval, ale vždycky účinnosti dokazujte, i k sobě vespolek i ke všechněm.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 16, 'Vždycky se radujte,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 17, 'Bez přestání se modlte,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 18, 'Ze všeho díky čiňte; nebo ta jest vůle Boží v Kristu Ježíši při vás.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 19, 'Ducha neuhašujte,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 20, 'Proroctvím nepohrdejte,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 21, 'Všeho zkuste; což dobrého jest, toho se držte.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 22, 'Od všeliké zlé tvárnosti se varujte.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 23, 'Sám pak Bůh pokoje posvětiž vás ve všem, a celý váš duch i duše i tělo bez úhony ku příští Pána našeho Jezukrista zachováno budiž.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 24, 'Věrnýť jest ten, kterýž povolal vás, kterýž také i učiní to.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 25, 'Bratří, modlte se za nás.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 26, 'Pozdravte všech bratří s políbením svatým.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 27, 'Zavazujiť vás skrze Pána, aby čten byl list tento všechněm bratřím svatým.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 28, 'Milost Pána našeho Jezukrista s vámi. Amen.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 1, 'Pavel a Silván a Timoteus církvi Tessalonicenské v Bohu Otci našem a Pánu Ježíši Kristu:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 2, 'Milost vám a pokoj od Boha Otce našeho a Pána Jezukrista.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 3, 'Povinniť jsme díky činiti Bohu vždycky z vás, bratří, tak jakž hodné jest, proto že velmi roste víra vaše, a rozmáhá se láska jednoho každého z vás, všechněch k sobě vespolek,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 4, 'Tak že my se vámi v zbořích Božích chlubíme, vaší trpělivostí a věrou ve všech protivenstvích vašich a ssouženích, kteráž snášíte.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 5, 'A tať jsou zjevný důvod spravedlivého soudu Božího, abyste tak za hodné jmíni byli království Božího, pro něž i trpíte,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 6, 'Poněvadž spravedlivé jest u Boha, aby zase odplaceno bylo těm, kteříž vás ssužují, ssoužením,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 7, 'Vám pak, kteříž úzkost trpíte, odpočinutím s námi, při zjevení Pána Ježíše s nebe s anděly moci jeho,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 8, 'V plameni ohně, kterýž pomstu uvede na ty, ješto neznají Boha, a neposlouchají evangelium Pána našeho Jezukrista.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 9, 'Kteříž pomstu ponesou, věčné zahynutí, od tváři Páně a od slávy moci jeho,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 10, 'Když přijde, aby oslaven byl v svatých, a předivný ukázal se ve všech věřících, (nebo uvěřeno jest svědectví našemu u vás,) v onen den.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 11, 'Pročež i modlíme se vždycky za vás, aby vás hodné učiniti ráčil povolání toho Bůh náš, a vyplnil všecku dobře libou vůli dobrotivosti, i skutek víry mocně,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 12, 'Aby oslaveno bylo jméno Pána našeho Jezukrista v vás, a vy v něm, podlé milosti Boha našeho, a Pána Jezukrista.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 1, 'Prosímeť pak vás, bratří, skrze příští Pána našeho Jezukrista, a naše shromáždění v něj,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 2, 'Abyste se nedali rychle vyrážeti z mysli, ani kormoutiti, buď skrze ducha, buď skrze řeč, neb skrze list, jako od nás poslaný, jako by nastával den Kristův.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 3, 'Nesvodiž vás žádný nižádným obyčejem. Neboť nenastane, leč až prvé přijde odstoupení, a zjeven bude ten člověk hřícha, syn zatracení,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 4, 'Protivící a povyšující se nade všecko, což slove Bůh, aneb čemuž se děje Božská čest, tak že se v chrámě Božím jako Bůh posadí, počínaje sobě, jako by byl Bůh.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 5, 'Nepomníte-liž, že ještě byv u vás, o tom jsem vám pravil?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 6, 'A nyní co mešká, víte, totiž aby on zjeven byl časem svým.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 7, 'Nebo již tajemství nepravosti působí, toliko až by ten, kterýž jej zdržuje nyní, z prostředku byl vyvržen.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 8, 'A tehdážť zjeven bude ten bezbožník, kteréhož Pán zabije duchem úst svých, a zkazí zjevením jasné přítomnosti své,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 9, 'Toho nešlechetníka, jehož příští jest podlé mocného díla satanova, se vší mocí a divy i zázraky lživými,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 10, 'A se všelikým podvodem nepravosti, v těch, kteříž hynou, proto že lásky pravdy nepřijali, aby spaseni byli.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 11, 'A protož pošle jim Bůh mocné dílo podvodů aby věřili lži,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 12, 'A aby odsouzeni byli všickni, kteříž neuvěřili pravdě, ale oblíbili sobě nepravost.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 13, 'Myť pak jsme povinni děkovati Bohu vždycky z vás, bratří Pánu milí, že vyvolil vás Bůh od počátku k spasení, v posvěcení Ducha, a u víře pravdy,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 14, 'K čemuž povolal vás skrze evangelium naše, k dojití slávy Pána našeho Jezukrista.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 15, 'A protož, bratří, stůjtež, a držtež se učení vydaného, jemuž jste se naučili, buď skrze řeč, buď skrze list náš.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 16, 'Ten pak náš Pán Ježíš Kristus, a Bůh i Otec náš, kterýž zamiloval nás, a dal potěšení věčné, a naději dobrou z milosti,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 17, 'Potěšujž srdcí vašich, a utvrdiž vás v každém slovu i skutku dobrém.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 1, 'Dále pak, bratří, modlte se za nás, aby slovo Páně rozmáhalo se a slaveno bylo, jako i u vás,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 2, 'A abychom vysvobozeni byli od nezbedných a zlých lidí. Neboť ne všech jest víra.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 3, 'Ale věrnýť jest Pán, kterýž utvrdí vás, a ostříhati bude od zlého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 4, 'Doufámeť pak v Pánu o vás, že to, což vám předkládáme, činíte i činiti budete.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 5, 'Pán pak spravujž srdce vaše k lásce Boží, a k trpělivému očekávání Krista.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 6, 'Přikazujemeť pak vám, bratří, ve jménu Pána našeho Jezukrista, abyste se oddělovali od každého bratra, kterýž by se choval neřádně, a ne podlé naučení vydaného, kteréž přijal od nás.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 7, 'Nebo sami víte, kterak jest potřebí následovati nás, poněvadž jsme se nechovali mezi vámi neslušně.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 8, 'Aniž jsme darmo chleba jedli u koho, ale s prací a s těžkostí, ve dne i v noci dělajíce, abychom žádnému z vás nebyli k obtížení.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 9, 'Ne jako bychom neměli k tomu práva, ale abychom se vám za příklad vydali, abyste nás následovali.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 10, 'Nebo i když jsme byli u vás, to jsme vám předkládali: Kdo nechce dělati, aby také nejedl.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 11, 'Slyšímeť zajisté, že někteří mezi vámi chodí nezpůsobně, nic nedělajíce, ale v neužitečné věci se vydávajíce.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 12, 'Protož takovým přikazujeme, a napomínáme jich skrze Pána našeho Jezukrista, aby pokojně pracujíce, svůj chléb jedli.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 13, 'Vy pak, bratří, neoblevujte dobře činíce.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 14, 'Pakli kdo neuposlechne skrze psání řeči naší, toho znamenejte, a nemějte s ním nic činiti, aťby se zastyděl.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 15, 'A však nemějte ho za nepřítele, ale napomínejte jako bratra.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 16, 'Sám pak ten Pán pokoje dejž vám vždycky pokoj všelijakým způsobem. Pán budiž se všemi vámi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 17, 'Pozdravení mou rukou Pavlovou, což jest za znamení v každém listu. Takť obyčejně píši.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 18, 'Milost Pána našeho Jezukrista se všechněmi vámi. Amen.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 1, 'Pavel, apoštol Ježíše Krista, podlé zřízení Boha spasitele našeho, a Pána Jezukrista, naděje naší,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 2, 'Timoteovi, vlastnímu synu u víře: Milost, milosrdenství a pokoj od Boha Otce našeho, a od Krista Ježíše Pána našeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 3, 'Jakož jsem prosil tebe, abys pozůstal v Efezu, když jsem šel do Macedonie, viziž, abys přikázal některým jiného učení neučiti,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 4, 'Ani oblibovati básní a vypravování rodů, čemuž konce není, odkudž jen hádky pocházejí, více nežli vzdělání Boží, kteréž jest u víře.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 5, 'Ješto konec přikázaní jest láska z srdce čistého, a z svědomí dobrého a z víry neošemetné.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 6, 'Od čehož někteří jako od cíle pobloudivše, uchýlili se k marnomluvnosti,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 7, 'Chtěvše býti učitelé zákona, a nerozuměvše, ani co mluví, ani čeho zastávají.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 8, 'Víme pak, že dobrý jest zákon, když by ho kdo náležitě užíval,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 9, 'Toto znaje, že spravedlivému není uložen zákon, ale nepravým a nepoddaným, bezbožným a hříšníkům, nešlechetným a nečistým, mordéřům otců a matek, vražedlníkům,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 10, 'Smilníkům, samcoložníkům, těm, kteříž lidi kradou, lhářům, křivým přísežníkům, a jestli co jiného, ješto by bylo na odpor zdravému učení,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 11, 'Podlé slavného evangelium blahoslaveného Boha, kteréž mně jest svěřeno.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 12, 'Protož děkuji tomu, kterýž mne zmocnil, Kristu Ježíši Pánu našemu, že mne za věrného soudil, aby mne v službě té postavil,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 13, 'Ješto jsem prvé byl ruhač, a protivník, a ukrutník. Ale milosrdenství jsem došel; nebo jsem to z neznámosti činil v nevěře.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 14, 'Rozhojnila se pak náramně milost Pána našeho, s věrou a s milováním v Kristu Ježíši.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 15, 'Věrnáť jest tato řeč a všelijak oblíbení hodná, že Kristus Ježíš přišel na svět, aby hříšné spasil, z nichž já první jsem.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 16, 'Ale proto milosrdenství jsem došel, aby na mně prvním dokázal Ježíš Kristus všeliké dobrotivosti, ku příkladu těm, kteříž mají uvěřiti v něho k životu věčnému.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 17, 'Protož králi věků nesmrtelnému, neviditelnému, samému moudrému Bohu budiž čest i sláva na věky věků. Amen.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 18, 'Totoť přikázaní poroučím tobě, synu Timotee, abys podlé předešlých o tobě proroctví bojoval v tom dobrý boj,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 19, 'Maje víru a dobré svědomí, kteréž někteří potrativše, zhynuli u víře.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 20, 'Z nichž jest Hymeneus a Alexander, kteréž jsem vydal satanu, aby strestáni jsouce, učili se nerouhati.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 1, 'Napomínámť pak, aby přede vším činěny bývaly pokorné modlitby, prosby, žádosti a díků činění za všecky lidi,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 2, 'Za krále i za všecky v moci postavené, abychom pohodlný a pokojný život vedli ve vší pobožnosti a šlechetnosti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 3, 'Nebo toť jest dobré a vzácné před spasitelem naším Bohem,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 4, 'Kterýž chce, aby všickni lidé spaseni byli, a k známosti pravdy přišli.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 5, 'Jedenť jest zajisté Bůh, jeden také i prostředník Boží a lidský, člověk Kristus Ježíš,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 6, 'Kterýž dal sebe samého mzdu na vykoupení za všecky, na osvědčení časem svým.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 7, 'K čemuž postaven jsem já za kazatele a apoštola, (pravduť pravím v Kristu a neklamámť,) za učitele pohanů u víře a pravdě.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 8, 'Protož chtěl bych, aby se modlili muži na všelikém místě, pozdvihujíce čistých rukou, bez hněvu a bez roztržitosti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 9, 'Takž také i ženy aby se oděvem slušným s stydlivostí a s středmostí ozdobovaly, ne křtaltováním sobě vlasů, neb zlatem, aneb perlami, aneb drahým rouchem,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 10, 'Ale (tak, jakž sluší ženám, kteréž dokazují při sobě pobožnosti,) dobrými skutky.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 11, 'Žena ať se učí mlčeci, ve všeliké poddanosti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 12, 'Nebo ženě nedopouštím učiti, ani vládnouti nad mužem, ale aby byla v mlčení.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 13, 'Adam zajisté prvé jest stvořen, potom Eva.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 14, 'A Adam nebyl sveden, ale žena svedena jsuci, příčinou přestoupení byla.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 15, 'Ale však spasena bude v plození dětí, jestliže by zůstala u víře, a v lásce, a v posvěcení, s středmostí.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 1, 'Věrnáť jest řeč, žádá-li kdo biskupství, žeť výborné práce žádá.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 2, 'Ale musíť biskup býti bez úhony, jedné manželky muž, bedlivý, středmý, vážný, k hostem přívětivý, způsobný k učení,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 3, 'Ne piján vína, ne bitec, ani mrzkého zisku žádostivý, ale mírný, ne svárlivý, ne lakomec,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 4, 'Kterýž by dům svůj dobře spravoval, kterýž by dítky měl v poddanosti se vší poctivostí.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 5, '(Nebo jestliže kdo domu svého spraviti neumí, kterak o církev Páně pečovati bude?)');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 6, 'Ne novák, aby nadut jsa, neupadl v potupení ďáblovo.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 7, 'Musíť také i svědectví dobré míti od těch, kteříž jsou vně, aby neupadl v pohanění a v osídlo ďáblovo.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 8, 'Takž podobně jahnové mají býti poctiví, ne dvojího jazyka, ne mnoho vína pijící, ne žádostiví mrzkého zisku,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 9, 'Mající tajemství víry v svědomí čistém.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 10, 'A ti také ať jsou nejprv zkušeni, a tak ať přisluhují, jsouce bez úhony.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 11, 'Též i manželky ať mají poctivé, neutrhavé, středmé, ve všem věrné.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 12, 'Jahnové buďtež jedné manželky muži, kteříž by dítky dobře spravovali i své domy.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 13, 'Nebo kteříž by dobře přisluhovali, dobrého stupně sobě dobudou, a mnohé doufanlivosti u víře, kteráž jest v Kristu Ježíši.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 14, 'Totoť píši tobě, maje naději, že brzo příjdu k tobě.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 15, 'Pakliť prodlím, abys věděl, kterak máš v domě Božím obcovati, kterýž jest církev Boha živého, sloup a utvrzení pravdy.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 16, 'A v pravdě velikéť jest tajemství pobožnosti, že Bůh zjeven jest v těle, ospravedlněn v Duchu, ukázal se andělům, kázán jest pohanům, uvěřeno jemu na světě, zhůru přijat jest v slávu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 1, 'Duch pak světle praví, že v posledních časích odvrátí se někteří od víry, poslouchajíce duchů bludných a učení ďábelských,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 2, 'V pokrytství lež mluvících, a cejchované majících svědomí své,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 3, 'Zbraňujících ženiti se, přikazujících zdržovati se od pokrmů, kteréž Bůh stvořil k užívání s díkčiněním věřícím a těm, kteříž poznali pravdu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 4, 'Nebo všeliké stvoření Boží dobré jest, a nic nemá zamítáno býti, což se s díků činěním přijímá.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 5, 'Posvěcuje se zajisté skrze slovo Boží a modlitbu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 6, 'Toto předkládaje bratřím, budeš dobrý služebník Jezukristův, vykrmený slovy víry a pravého učení, kteréhož jsi následoval.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 7, 'Světské pak a babské básně zavrz, ale cvič se v pobožnosti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 8, 'Nebo tělesné cvičení malého jest užitku, ale pobožnost ke všemu jest užitečná, a má i nynějšího i budoucího života zaslíbení.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 9, 'Věrnáť jest tato řeč, a hodná, aby všelijak oblíbena byla.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 10, 'Proto zajisté i pracujeme, i pohanění neseme, že naději máme v Bohu živém, kterýž jest ochránce všech lidí, a zvláště věřících.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 11, 'Ty věci předkládej, a uč.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 12, 'Nižádný mladostí tvou nepohrdej, ale buď příkladem věrných v řeči, v obcování, v lásce, v duchu, u víře, v čistotě.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 13, 'Dokudž nepřijdu, buď pilen čítání, napomínání, učení.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 14, 'Nezanedbávej daru, kterýž jest v tobě, jenžť jest dán skrze proroctví s vzkládáním rukou starších.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 15, 'O tom přemyšluj, v tom buď, aby prospěch tvůj zjevný byl všechněm.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 16, 'Budiž sebe pilen i učení, v tom trvej; nebo to čině, i samého sebe spasíš, i ty, kteříž tebe poslouchají.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 1, 'Staršího netresci, ale napomínej jako otce, mladších jako bratří,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 2, 'Starých žen jako matek, mladic jako sestr, ve vší čistotě.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 3, 'Vdovy měj v poctivosti, kteréž pravé vdovy jsou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 4, 'Pakli která vdova dítky neb vnuky má, nechažť se učí předně k svému domu pobožnosti dokazovati, a zase rodičům se odplacovati; neboť jest to chvalitebné a vzácné před oblíčejem Božím.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 5, 'Kteráž pak právě vdova jest a osamělá, máť naději v Bohu, a trváť na modlitbách a svatých žádostech dnem i nocí.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 6, 'Ale rozkošná, živa jsuci, již umřela.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 7, 'Protož to přikaž, ať jsou bez úhony.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 8, 'Jestliže pak kdo o své, a zvláště o domácí péče nemá, zapřelť víry, a jest horší než nevěřící.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 9, 'Vdova buď vyvolena, kteráž by neměla méně šedesáti let, kteráž byla jednoho muže manželka,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 10, 'O níž by svědectví bylo, že dobré skutky činila, jestliže dítky vychovala, jestliže do domu pocestné přijímala, jestliže svatým nohy umývala, jestliže bídným posluhovala, jestliže každého skutku dobrého pilna byla.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 11, 'Ale mladých vdov nepřijímej; nebo když, nedbajíce na Krista, v chlipnost se vydadí, vdávati se chtějí,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 12, 'Jsouce již hodné potupení, proto že první víru zrušily.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 13, 'Nýbrž také jsouce i zahálevé, učí se choditi po domích; a netoliko zahálevé, ale i klevetné a všetečné, mluvíce, což nesluší.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 14, 'Protož chci, aby se mladší vdávaly, děti rodily, hospodyně byly, a žádné příčiny protivníku nedávaly ku pomlouvání.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 15, 'Nebo již se některé uchýlily zpět po satanu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 16, 'Protož má-liť kdo věřící neb která věřící vdovy, opatrujž je, a nebuď obtěžována církev, aby těm, kteréž právě vdovy jsou, postačilo.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 17, 'Předložení, kteříž dobře spravují, dvojí cti hodni jmíni buďte, zvláště ti, kteříž pracují v slovu a v učení.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 18, 'Nebo praví písmo: Volu mlátícímu nezavížeš úst. A hodenť jest dělník své mzdy.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 19, 'Proti staršímu žaloby nepřijímej, leč pode dvěma neb třmi svědky.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 20, 'Ty pak, kteříž hřeší, přede všemi tresci, aby i jiní bázeň měli.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 21, 'Osvědčujiť před oblíčejem Božím, a Pána Jezukrista, i vyvolených andělů, abys těchto věcí ostříhal bez přijímání osob, nic nečině podlé náchylnosti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 22, 'Nevzkládej rukou rychle na žádného, a neobcuj hříchům cizím. Sebe samého ostříhej v čistotě.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 23, 'Nepí již více vody, ale vína skrovně užívej, pro svůj žaludek a časté nemoci své.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 24, 'Některých lidí hříchové prvé zjevní jsou, předcházející soud, některých pak i následují.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 25, 'A takž také i skutkové dobří prvé zjevní jsou. Což pak jest jinak, ukryti se nemůže.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 1, 'Kteřížkoli pod jhem jsou služebníci, ať mají pány své za hodné vší poctivosti, aby jméno Boží a učení nebylo rouháno.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 2, 'Kteříž pak mají pány věřící, nechažť jich sobě nezlehčují, proto že jsou bratřími, ale tím raději slouží, proto že jsou věřící a milí, dobrodiní Božího účastníci. Tomu vyučuj, a napomínej.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 3, 'Jestližeť kdo jinak učí, a nepovoluje zdravým řečem Pána našeho Jezukrista, a tomu učení, kteréž jest podlé pobožnosti,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 4, 'Nadutýť jest, nic neuměje, ale nemoudrost provodí při otázkách a hádkách o slova, z kterýchž pochází závist, svár, rouhání, zlá domnění,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 5, 'Marné hádky lidí na mysli porušených a pravdy zbavených, domnívajících se, že by pobožnost byla zisk tělesný. Takových se varuj.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 6, 'Jestiť pak zisk veliký pobožnost, s takovou myslí, kteráž na tom, což má, přestati umí.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 7, 'Nic jsme zajisté nepřinesli na tento svět, bez pochyby že také nic odnesti nemůžeme.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 8, 'Ale majíce pokrm a oděv, na tom přestaneme.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 9, 'Kteříž pak chtí zbohatnouti, upadají v pokušení, a v osídlo, a v žádosti mnohé nerozumné a škodlivé, kteréž pohřižují lidi v zahynutí a v zatracení.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 10, 'Kořen zajisté všeho zlého jestiť milování peněz, kterýchž někteří žádostivi byvše, pobloudili od víry, a sami se naplnili bolestmi mnohými.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 11, 'Ale ty, ó člověče Boží, takových věcí utíkej, následuj pak spravedlnosti, pobožnosti, víry, lásky, trpělivosti, tichosti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 12, 'Bojuj ten dobrý boj víry, dosáhni věčného života, k němuž i povolán jsi, a vyznals dobré vyznání před mnohými svědky.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 13, 'Přikazujiť tobě před Bohem, kterýž všecko obživuje, a před Kristem Ježíšem, kterýž osvědčil před Pontským Pilátem dobré vyznání,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 14, 'Abys ostříhal přikázaní tohoto, jsa bez poškvrny a bez úhony, až do zjevení se Pána našeho Ježíše Krista,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 15, 'Kteréž časem svým ukáže ten blahoslavený a sám mocný, Král kralujících, a Pán panujících,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 16, 'Kterýž sám má nesmrtelnost, a přebývá v světle nepřistupitelném, jehož žádný z lidí neviděl, aniž viděti může, kterémužto čest a síla věčná. Amen.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 17, 'Bohatým tohoto světa přikazuj, ať nejsou vysokomyslní, a ať nedoufají v nejistém zboží, ale v Bohu živém, kterýž dává nám hojnost všeho ku požívání.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 18, 'A ať dobře činí, a bohatnou v dobrých skutcích, a snadní ať jsou k udílení, i přívětiví,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 19, 'Skládajíce sobě základ dobrý k času budoucímu, aby dosáhli věčného života.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 20, 'Ó Timotee, cožť jest svěřeno, ostříhej, utíkaje nepobožných daremních křiků, a odporů falešně nazvaného umění.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 21, 'Kterýmž někteří chlubíce se, z strany víry pobloudili od cíle. Milost Boží s tebou. Amen.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 1, 'Pavel, apoštol Ježíše Krista, skrze vůli Boží, podlé zaslíbení života, kterýž jest v Kristu Ježíši,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 2, 'Timoteovi milému synu: Milost, milosrdenství, pokoj od Boha Otce a Krista Ježíše Pána našeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 3, 'Díky činím Bohu, jemuž sloužím, jako i předkové, v svědomí čistém, že mám na tě ustavičnou pamět na svých modlitbách ve dne i v noci,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 4, 'Žádaje viděti tebe, zpomínaje na tvé slzy, abych radostí naplněn byl,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 5, 'Rozpomínaje se na tu víru, kteráž v tobě jest bez pokrytství, kteráž byla nejprv v bábě tvé Loidě, a v matce tvé Eunice, a tak smyslím, že i v tobě.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 6, 'Pro kterouž příčinu napomínám tebe, abys rozněcoval v sobě dar Boží, kterýž jest dán skrze vzkládání rukou mých.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 7, 'Nebo nedal nám Bůh ducha bázně, ale moci, a milování, a mysli způsobné.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 8, 'Protož nestyď se za svědectví Pána našeho, ani za mne, vězně jeho, ale čitedlen buď úzkostí pro evangelium podlé moci Boží,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 9, 'Kterýž spasil nás, a povolal povoláním svatým, ne podlé skutků našich, ale podlé uložení svého a milosti nám dané v Kristu Ježíši před časy věků,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 10, 'Nyní pak zjevené skrze příští patrné spasitele našeho Jezukrista, kterýž zahladil smrt, život pak na světlo vyvedl, i nesmrtelnost skrze evangelium,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 11, 'Jehož já ustanoven jsem kazatelem, a apoštolem, i učitelem pohanů.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 12, 'A pro tu příčinu toto trpím, ale nestydímť se za to; nebo vím, komu jsem uvěřil, a jist jsem tím, že mocen jest toho, což jsem u něho složil, ostříhati až do onoho dne.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 13, 'Mějž jistý příklad zdravých řečí, kteréž jsi slýchal ode mne, u víře a v lásce, kteráž jest v Kristu Ježíši.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 14, 'Výborného toho pokladu ostříhej, skrze Ducha svatého přebývajícího v nás.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 15, 'Víš snad o tom, že se odvrátili ode mne všickni, kteříž jsou v Azii, z nichž jest Fygellus a Hermogenes.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 16, 'Dejž milosrdenství Pán domu Oneziforovu; nebo často mi činil pohodlí, aniž se styděl za řetězy mé.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 17, 'Nýbrž přišed do Říma, pilně mne hledal, i nalezl.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 18, 'Dejž jemu Pán nalezti milosrdenství u Pána v onen den. A jak mi mnoho posluhoval v Efezu, ty výborně víš.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 1, 'Protož ty, synu můj, zmocniž se v milosti, kteráž jest v Kristu Ježíši.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 2, 'A což jsi slyšel ode mne před mnohými svědky, svěřujž to lidem věrným, kteříž by způsobní byli i jiné učiti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 3, 'A tak ty snášej protivenství, jako ctný rytíř Ježíše Krista.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 4, 'Žádný, kdož rytěřuje, neplete se v obecné živnosti, aby se svému hejtmanu líbil.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 5, 'A jestliže by kdo i bojoval, nebudeť korunován, leč by řádně bojoval.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 6, 'Pracovati musí i oráč, prvé nežli užitku okusí.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 7, 'Rozuměj, což pravím, a dejž tobě Pán ve všem rozum.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 8, 'Pamatuj, že Ježíš Kristus vstal z mrtvých, z semene Davidova, podlé evangelium mého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 9, 'V kterémžto protivenství trpím, až i vězení, jako bych zločinec byl, ale slovo Boží není u vězení.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 10, 'Protož všecko snáším pro vyvolené, aby i oni spasení došli, kteréž jest v Kristu Ježíši, s slávou věčnou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 11, 'Věrná jest tato řeč. Nebo jestližeť jsme s ním zemřeli, tedy také spolu s ním živi budeme.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 12, 'A trpíme-liť, budeme také spolu s ním kralovati; pakli ho zapíráme, i onť nás zapře.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 13, 'Pakliť jsme nevěrní, onť zůstává věrný; zapříti sám sebe nemůže.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 14, 'Tyto věci připomínej, s osvědčováním před oblíčejem Páně, ať se o slova nevadí, což k ničemu není užitečné, ale ku podvrácení posluchačů.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 15, 'Pilně se snažuj vydati sebe Bohu milého dělníka, za nějž by se nebylo proč styděti, kterýž by právě slovo pravdy rozděloval.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 16, 'Nepobožné pak ty křiky daremní zastavuj, neboť velmi rozmnožují bezbožnost,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 17, 'A řeč jejich jako rak rozjídá se. Z nichž jest Hymeneus a Filétus,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 18, 'Kteříž při pravdě pobloudili od cíle, pravíce, že by se již stalo vzkříšení, a převracejí víru některých.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 19, 'Ale však pevný základ Boží stojí, maje znamení toto: Znáť Pán ty, kteříž jsou jeho, a: Odstup od nepravosti každý, kdož vzývá jméno Kristovo.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 20, 'V domě pak velikém netoliko jsou nádoby zlaté a stříbrné, ale také dřevěné i hliněné, a některé zajisté ke cti, některé pak ku potupě.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 21, 'Protož jestliže by se kdo očistil od těch věcí, bude nádobou ke cti, posvěcenou, a užitečnou Pánu, ke všelikému skutku dobrému hotovou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 22, 'Mládenčích pak žádostí utíkej, ale následuj spravedlnosti, víry, lásky, pokoje, s těmi, kteříž vzývají Pána z srdce čistého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 23, 'Bláznivých pak a nevzdělavatelných otázek varuj se, věda, že plodí sváry.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 24, 'Neslušíť pak na služebníka Páně vaditi se, ale aby byl přívětivý ke všechněm, způsobný k učení, trpělivý,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 25, 'Kterýž by v tichosti vyučoval ty, kteříž se protiví, zda by někdy dal jim Bůh pokání ku poznání pravdy.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 26, 'Aby sami k sobě přijdouce, dobyli se z osídla ďáblova, od něhož jsou zjímáni k činění jeho vůle.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 1, 'Toto pak věz, že v posledních dnech nastanou časové nebezpeční.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 2, 'Nebo nastanou lidé sami sebe milující, peníze milující, chlubní, pyšní, zlolejcí, rodičů neposlušní, nevděční, bezbožní,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 3, 'Nelítostiví, smluv nezdrželiví, utrhači, nestředmí, plaší, kterýmž nic dobrého milo není.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 4, 'Zrádci, přívažčiví, nadutí, rozkoší milovníci více nežli milovníci Boha,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 5, 'Majíce způsob pobožnosti, ale moci její zapírajíce. A od takových se odvracuj.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 6, 'Nebo z těch jsou i ti, kteříž nacházejí do domů, a jímajíce, vodí ženky obtížené hříchy, kteréž vedeny bývají rozličnými žádostmi,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 7, 'Kteréž vždycky se učí, ale nikdy ku poznání pravdy přijíti nemohou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 8, 'Jakož zajisté Jannes a Jambres zprotivili se Mojžíšovi, tak i tito protiví se pravdě, lidé na mysli porušení, a při víře zpletení.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 9, 'Ale nebudouť více průchodu míti. Nebo nemoudrost jejich zjevná bude všechněm, jako i oněch byla.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 10, 'Ale ty jsi došel mého učení, způsobu života mého, úmyslu, víry, snášelivosti, lásky, trpělivosti,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 11, 'Protivenství, utrpení, kteráž na mne přišla v Antiochii, v Ikonii, a v Lystře. Kterážto protivenství snášel jsem, ale ze všech vysvobodil mne Pán.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 12, 'A takž i všickni, kteříž chtějí pobožně živi býti v Kristu Ježíši, protivenství míti budou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 13, 'Zlí pak lidé a svůdcové půjdou v horší, i ti, kteříž v blud uvodí, i ti, kteříž jsou bludem pojati.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 14, 'Ale ty zůstávej v tom, čemužs se naučil, a cožť jest svěřeno, věda, od kohos se naučil,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 15, 'A že od dětinství svatá písma znáš, kteráž tě mohou moudrého učiniti k spasení skrze víru, kteráž jest v Kristu Ježíši.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 16, 'Všelikéť písmo od Boha jest vdechnuté, a užitečné k učení, k trestání, k napravování, k správě, kteráž náleží k spravedlnosti,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 17, 'Aby byl dokonalý člověk Boží, ke všelikému skutku dobrému hotový.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 1, 'Protož já osvědčuji před oblíčejem Božím a Pána Jezukrista, kterýž má souditi živé i mrtvé v příchodu svém slavném a království svém,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 2, 'Kaž slovo Boží, ponoukej v čas neb ne v čas, tresci, žehři, napomínej, ve vší tichosti a učení.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 3, 'Nebo přijde čas, že zdravého učení nebudou trpěti, ale majíce svrablavé uši, podlé svých vlastních žádostí shromažďovati sami sobě budou učitele.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 4, 'A odvrátíť uši od pravdy, a k básněm obrátí.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 5, 'Ale ty ve všem buď bedliv, protivenství snášej, dílo kazatele konej, dokazuj toho dostatečně, že jsi věrný služebník.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 6, 'Nebo já se již k tomu blížím, abych obětován byl, a čas rozdělení mého nastává.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 7, 'Boj výborný bojoval jsem, běh jsem dokonal, víru jsem zachoval.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 8, 'Již za tím odložena jest mi koruna spravedlnosti, kterouž dá mi v onen den Pán, ten spravedlivý soudce, a netoliko mně, ale i všechněm těm, kteříž milují to slavné příští jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 9, 'Přičiň se k tomu, abys ke mně brzo přišel.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 10, 'Nebo Démas mne opustil, zamilovav tento svět, a šel do Tessaloniky, Krescens do Galacie, Titus do Dalmacie.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 11, 'Sám toliko Lukáš se mnou jest. Marka vezmi s sebou; nebo jest mi velmi potřebný k službě.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 12, 'Tychikať jsem poslal do Efezu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 13, 'Truhličku, kteréž jsem nechal v Troadě u Karpa, když půjdeš, přines, i knihy, zvláště pargamén.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 14, 'Alexander kotlář mnoho mi zlého způsobil; odplatiž jemu Pán podlé skutků jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 15, 'Kteréhož i ty se vystříhej; nebo velmi se protivil řečem našim.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 16, 'Při prvním mém odpovídání žádný se mnou nebyl, ale všickni mne opustili. Nebudiž jim to počítáno.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 17, 'Pán pak byl se mnou, a posilnil mne, aby skrze mne utvrzeno bylo kázaní, a slyšeli je všickni národové. I vytržen jsem byl z úst lva.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 18, 'A vysvobodíť mne Pán od každého skutku zlého, a zachovává k království svému nebeskému, jemuž sláva na věky věků. Amen.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 19, 'Pozdrav Prišky a Akvile, i Oneziforova domu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 20, 'Erastus zůstal v Korintu, Trofima pak nechal jsem v Milétu nemocného.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 21, 'Pospěš před zimou přijíti. Pozdravuje tebe Eubulus a Pudens a Línus a Klaudia, i všickni bratří.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 22, 'Pán Ježíš Kristus s duchem tvým. Milost Boží s vámi. Amen.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 1, 'Pavel, služebník Boží, apoštol pak Ježíše Krista, podlé víry vyvolených Božích, a známosti pravdy, kteráž jest podlé pobožnosti,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 2, 'K naději života věčného, kterýž zaslíbil před časy věků ten, kterýž nikdy neklamá, Bůh,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 3, 'Zjevil pak časy svými to slovo své, skrze kázaní mně svěřené, podlé zřízení spasitele našeho Boha,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 4, 'Titovi, vlastnímu synu u víře obecné: Milost, milosrdenství a pokoj od Boha Otce a Pána Jezukrista spasitele našeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 5, 'Z té příčiny zanechal jsem tebe v Krétě, abys to, čehož tam ještě potřebí, spravil, a ustanovil po městech starší, jakož i já při tobě jsem zřídil,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 6, 'Jest-li kdo bez úhony, jedné manželky muž, dítky maje věřící, na kteréž by nemohlo touženo býti, že by byli bůjní, aneb nepoddaní.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 7, 'Neboť biskup má býti bez úhony, jako Boží šafář, ne svémyslný, ne hněvivý, ne piján vína, ne bitec, ne žádostivý mrzkého zisku,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 8, 'Ale přívětivý k hostem, milovník dobrých, opatrný, spravedlivý, svatý, zdrželivý,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 9, 'Pilně se přídržící věrné řeči k vyučování dostatečné, aby mohl i napomínati učením zdravým, i ty, kteříž odpírají, přemáhati.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 10, 'Neboť jsou mnozí nepoddaní, marnomluvní, i svůdcové myslí, zvláště ti, kteříž jsou z obřízky.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 11, 'Jimž musejí ústa zacpána býti; kteříž celé domy převracejí, učíce neslušným věcem, pro mrzký zisk.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 12, 'Řekl jeden z nich, vlastní jejich prorok: Kretenští jsou vždycky lháři, zlá hovada, břicha lenivá.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 13, 'Svědectví to pravé jest. A protož tresciž je přísně, ať jsou zdraví u víře,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 14, 'Nešetříce Židovských básní a přikázaní lidí těch, kteříž se odvracují od pravdy.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 15, 'Všecko zajisté čisté jest čistým, poškvrněným pak a nevěřícím nic není čistého, ale poškvrněna jest i mysl jejich i svědomí.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 16, 'Vypravují o tom, že Boha znají, ale skutky svými toho zapírají, ohavní jsouce, a nepoddaní, a ke všelikému skutku dobrému nehodní.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 1, 'Ty pak mluv, což sluší na zdravé učení.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 2, 'Starci, ať jsou střízliví, vážní, opatrní, zdraví u víře, v lásce, v snášelivosti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 3, 'Též i staré ženy ať chodí pobožně, v oděvu příslušném, a ať nejsou převrhlé, ani mnoho vína pijící, poctivým věcem učící.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 4, 'Aby mladice vyučovaly, jak by muže své i dítky milovati měly,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 5, 'A byly šlechetné, čistotné, netoulavé, dobrotivé, mužům svým poddané, aby nebylo dáno v porouhání slovo Boží.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 6, 'Takž i mládenců napomínej k středmosti,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 7, 'Ve všech věcech sebe samého vydávaje za příklad dobrých skutků, maje v učení celost, vážnost,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 8, 'Slovo zdravé, bez úhony, aby ten, kterýž by se protivil, zastyděti se musil, nemaje co zlého mluviti o vás.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 9, 'Služebníky uč, ať jsou poddáni pánům svým, ve všem jim se líbíce, neodmlouvajíce,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 10, 'Neokrádajíce, ale ve všem věrnosti pravé dokazujíce, aby učení spasitele našeho Boha ve všem ozdobovali.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 11, 'Zjevilať se zajisté ta milost Boží spasitelná všechněm lidem,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 12, 'Vyučující nás, abychom odřeknouce se bezbožnosti, a světských žádostí, střízlivě, a spravedlivě, a pobožně živi byli na tomto světě,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 13, 'Očekávajíce té blahoslavené naděje, a příští slávy velikého Boha a spasitele našeho Jezukrista,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 14, 'Kterýž dal sebe samého za nás, aby nás vykoupil od všeliké nepravosti, a očistil sobě samému lid zvláštní, horlivě následovný dobrých skutků.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 15, 'Toto mluv, a napomínej, a tresci mocně. Žádný tebou nepohrzej.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 1, 'Napomínej jich, ať jsou knížatům a mocnostem poddáni, jich poslušni, a ať jsou k každému skutku dobrému hotovi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 2, 'Žádnému ať se nerouhají, nejsou svárliví, ale přívětiví, dokazujíce všeliké tichosti ke všechněm lidem.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 3, 'Byliť jsme zajisté i my někdy nesmyslní, tvrdošijní, bloudící, sloužíce žádostem a rozkošem rozličným, v zlosti a v závisti bydlíce, ohyzdní, vespolek se nenávidíce.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 4, 'Ale když se zjevila dobrota a láska k lidem spasitele našeho Boha,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 5, 'Ne z skutků spravedlnosti, kteréž bychom my činili, ale podlé milosrdenství svého spasil nás, skrze obmytí druhého narození, a obnovení Ducha svatého;');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 6, 'Kteréhož vylil na nás hojně, skrze Jezukrista spasitele našeho,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 7, 'Abychom, ospravedlněni jsouce milostí jeho, byli dědicové v naději života věčného.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 8, 'Věrnáť jest řeč tato, a chciť, abys těch věcí potvrzoval, ať se snaží v dobrých skutcích předčiti, kteříž uvěřili Bohu. A toť jsou ty věci poctivé, i lidem užitečné.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 9, 'Nemoudré pak otázky, a vyčítání rodů, a sváry, a hádky zákonní zastavuj; neboť jsou neužitečné a marné.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 10, 'Člověka kacíře po jednom neb druhém napomínání vyvrz.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 11, 'Věda, že takový jest převrácený, a hřeší, svým vlastním soudem jsa odsouzen.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 12, 'Když pošli k tobě Artemana aneb Tychika, snaž se přijíti ke mně do Nikopolim; nebo jsem umínil tam přes zimu pobyti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 13, 'Zéna, učeného v zákoně, a Apollo s pilností vyprovoď, ať v ničemž nemají nedostatku.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 14, 'A nechažť se také učí i naši v dobrých skutcích předčiti, kdež jsou toho potřeby, aby nebyli neužiteční.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 15, 'Pozdravují tě, kteříž jsou se mnou, všickni. Pozdraviž těch, kteříž nás milují u víře. Milost Boží se všechněmi vámi. Amen.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 1, 'Pavel, vězeň Krista Ježíše, a Timoteus bratr, Filemonovi milému, a pomocníku našemu,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 2, 'A Apfie milé, a Archippovi spolurytíři našemu, i církvi, kteráž jest v domě tvém:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 3, 'Milost vám a pokoj od Boha Otce našeho a Pána Jezukrista.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 4, 'Díky činím Bohu svému, vždycky zmínku o tobě čině na svých modlitbách,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 5, 'Slyše o lásce tvé, a víře, kterouž máš ku Pánu Ježíšovi, i ke všechněm svatým,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 6, 'Aby společnost víry tvé mocná byla ku poznání všeho toho, cožkoli dobrého jest v vás skrze Krista Ježíše.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 7, 'Radost zajisté máme velikou, a potěšení z lásky tvé, že střeva svatých občerstvena jsou skrze tebe, bratře.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 8, 'Protož ačkoli mnohou smělost mám v Kristu rozkázati tobě, což by náleželo,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 9, 'Však pro lásku raději prosím, jsa takový, totiž Pavel starý, a nyní i vězeň Ježíše Krista.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 10, 'Prosímť pak tebe za syna svého, kteréhož jsem zplodil v vězení svém, Onezima,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 11, 'Kterýž byl někdy tobě neužitečný, ale nyní tobě i mně velmi užitečný, jehožť jsem odeslal.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 12, 'Protož ty jej, totiž střeva má, přijmi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 13, 'Kteréhož já chtěl jsem byl při sobě zdržeti, aby mi posluhoval místo tebe v vězení pro evangelium;');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 14, 'Ale bez vědomí tvého nechtěl jsem nic učiniti, aby dobrý skutek tvůj nebyl bezděčný, ale dobrovolný.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 15, 'Ano snad proto byl odšel na chvíli, abys jej věčného měl,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 16, 'Již ne jako služebníka, ale více než služebníka, totiž bratra milého, zvláště mně, a čím více tobě, i podlé těla, i v Pánu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 17, 'Protož máš-li mne za tovaryše, přijmiž jej, jako mne.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 18, 'Jestližeť pak v čem ublížil, aneb dlužen-liť co, to mně přičti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 19, 'Já Pavel psal jsem svou rukou, jáť zaplatím; ať nedím tobě, že ty i sám sebe jsi mi dlužen.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 20, 'Tak, bratře, ať já uživu tebe v Pánu; očerstviž střeva má v Pánu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 21, 'Jist jsa tvým poslušenstvím, napsal jsem tobě, věda, že i více, než pravím, učiníš.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 22, 'A mezi tím připrav mi také hospodu; neboť naději mám, že k modlitbám vašim budu vám navrácen.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 23, 'Pozdravují tě Epafras, (spoluvězeň můj pro Krista Ježíše,)');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 24, 'Marek, Aristarchus, Démas, a Lukáš, pomocníci moji.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 25, 'Milost Pána našeho Jezukrista s duchem vaším. Amen.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 1, 'Častokrát a rozličnými způsoby mluvíval někdy Bůh otcům skrze proroky, v těchto pak posledních dnech mluvil nám skrze Syna svého,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 2, 'Kteréhož ustanovil dědicem všeho, skrze něhož i věky učinil.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 3, 'Kterýžto jsa blesk slávy, a obraz osoby jeho, a zdržuje všecko slovem mocnosti své, očištění hříchů našich skrze sebe samého učiniv, posadil se na pravici velebnosti na výsostech,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 4, 'Tím důstojnější nad anděly učiněn, čím vyvýšenější nad ně jméno dědičně obdržel.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 5, 'Nebo kterému kdy z andělů řekl: Syn můj jsi ty, já dnes zplodil jsem tebe? A opět: Já budu jemu otcem, a on mi bude synem?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 6, 'A opět, když uvodí prvorozeného na okršlek země, dí: A klanějte se jemu všickni andělé Boží.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 7, 'A o andělích zajisté dí: Kterýž činí anděly své duchy, a služebníky své plamen ohně;');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 8, 'Ale k Synu dí: Stolice tvá, ó Bože, na věky věků, berla pravosti jest berla království tvého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 9, 'Miloval jsi spravedlnost, a nenáviděl jsi nepravosti, protož pomazal tebe, ó Bože, Bůh tvůj olejem veselé nad spoluúčastníky tvé.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 10, 'A ty, Pane, na počátku založil jsi zemi, a díla rukou tvých jsouť nebesa.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 11, 'Onať pominou, ty pak zůstáváš; a všecka jako roucho zvetšejí,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 12, 'A jako oděv svineš je, i budouť změněna. Ale ty jsi tentýž, a léta tvá nepřestanou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 13, 'A kterému kdy z andělů řekl: Seď na pravici mé, dokudž nepoložím nepřátel tvých za podnože noh tvých?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 14, 'Zdaliž všickni nejsou služební duchové, kteříž posílání bývají k službě pro ty, jenž mají dědičně obdržeti spasení?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 1, 'Protož musímeť my tím snažněji šetřiti toho, což jsme slýchali, aby nám to nevymizelo.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 2, 'Nebo poněvadž skrze anděly mluvené slovo bylo pevné, a každé přestoupení a neposlušenství vzalo spravedlivou odměnu pomsty,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 3, 'Kterakž my utečeme, takového zanedbávajíce spasení? Kteréžto nejprvé začavši vypravováno býti skrze samého Pána, od těch, kteříž jej slýchali, nám jest utvrzeno.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 4, 'Čemuž i Bůh svědectví vydával skrze divy, a zázraky, a rozličné moci, i podělování Duchem svatým, podlé vůle své.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 5, 'Nebo nepoddal andělům okršlku země budoucího, o kterémž mluvíme.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 6, 'Osvědčilť pak na jednom místě jeden, řka: Co jest člověk, že naň pomníš, aneb syn člověka, že na něj patříš?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 7, 'Maličkos jej menšího než anděly učinil, slavou a ctí korunoval jsi ho, a ustanovils jej nad dílem rukou svých.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 8, 'Všecko jsi podmanil pod nohy jeho. Poddav pak jemu všecko, ničeho nezanechal nepodmaněného jemu. I však nyní ještě nevidíme, aby jemu všecko poddáno bylo.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 9, 'Ale toho Ježíše, kterýž maličko nižší byl nežli andělé, vidíme pro utrpení smrti slavou a ctí korunovaného, aby z milosti Boží za všecky okusil smrti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 10, 'Slušeloť zajisté na toho, pro kteréhož jest všecko, a skrze kteréhož jest všecko, aby mnohé syny k slávě přiveda, vůdce spasení jejich skrze utrpení posvětil.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 11, 'Nebo i ten, kterýž posvěcuje, i ti, kteříž posvěceni bývají, z jednoho jsou všickni. Pro kteroužto příčinu nestydí se jich nazývati bratřími,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 12, 'Řka: Zvěstovati budu jméno tvé bratřím svým, u prostřed shromáždění prozpěvovati budu tobě.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 13, 'A opět: Já budu v něm doufati. A opět: Aj, já a dítky, kteréž dal mi Bůh.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 14, 'Poněvadž tedy dítky účastnost mají těla a krve, i on též podobně účasten jest jich, aby skrze smrt zahladil toho, kterýž má vládařství smrti, to jest ďábla,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 15, 'A vysvobodil ty, kteříž bázní smrti po všecken čas života podrobeni byli v službu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 16, 'Neboť nikoli nepřijal andělů, ale símě Abrahamovo přijal.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 17, 'Pročež ve všem připodobněn býti měl bratřím, aby milosrdný byl, a věrný nejvyšší kněz {biskup} v tom, což se u Boha k očištění hříchů lidu díti mělo.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 18, 'Nebo že sám trpěl, pokoušín byv, může také pokušení trpícím spomáhati.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 1, 'A protož, bratří svatí, povolání nebeského účastníci, spatřujte apoštola a nejvyššího kněze {biskupa} vyznání našeho, Krista Ježíše,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 2, 'Věrného tomu, kdož jej ustanovil, jako i Mojžíš byl ve všem domě jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 3, 'Tím větší zajisté slávy tento nad Mojžíše jest hoden, čím větší má čest stavitel nežli sám dům.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 4, 'Nebo všeliký dům ustaven bývá od někoho, ten pak, kdož všecky tyto věci ustavěl, Bůh jest.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 5, 'A Mojžíš zajisté věrný byl v celém domě jeho, jako služebník, na osvědčení toho, což potom mělo mluveno býti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 6, 'Ale Kristus, jako Syn, panuje nad domem svým. Kterýžto dům my jsme, jestliže tu svobodnou doufanlivost, a tu chloubu naděje až do konce pevnou zachováme.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 7, 'Protož jakž praví Duch svatý: Dnes, uslyšeli-li byste hlas jeho,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 8, 'Nezatvrzujtež srdcí svých, jako při onom popuzení v den pokušení toho na poušti;');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 9, 'Kdež pokoušeli mne otcové vaši, zkusiliť mne, a viděli skutky mé po čtyřidceti let.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 10, 'Protož hněviv jsem byl na pokolení to, a řekl jsem: Tito vždycky bloudí srdcem, a nepoznávají cest mých.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 11, 'Pročež přisáhl jsem v hněvě svém, že nevejdou v odpočinutí mé.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 12, 'Viztež, bratří, aby snad v někom z vás nebylo srdce zlé a nevěrné, kteréž by odstupovalo od Boha živého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 13, 'Ale napomínejte se vespolek po všecky dny, dokudž se dnes jmenuje, aby někdo z vás nebyl zatvrzen oklamáním hřícha.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 14, 'Účastníci zajisté Krista učiněni jsme, jestliže však ten počátek podstaty až do konce pevný zachováme.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 15, 'Protož dokudž se říká: Dnes, uslyšeli-li byste hlas jeho, nezatvrzujte srdcí svých, jako při onom popuzení.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 16, 'Nebo někteří slyševše, popouzeli ho, ale ne všickni, kteříž vyšli z Egypta skrze Mojžíše.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 17, 'Na které se pak hněval čtyřidceti let? Zdali ne na ty, kteříž hřešili, jejichž těla padla na poušti?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 18, 'A kterým zapřisáhl, že nevejdou do odpočinutí jeho? Však těm, kteříž byli neposlušní.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 19, 'A vidíme, žeť nemohli vjíti pro nevěru.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 1, 'Bojmež se tedy, aby snad opustě zaslíbení o vjití do odpočinutí jeho, neopozdil se někdo z vás.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 2, 'Nebo i nám zvěstováno jest, jako i oněmno, ale neprospěla jim řeč slyšená, nepřipojená k víře těch, kteříž slyšeli.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 3, 'Neboť vcházíme v odpočinutí my, kteříž jsme uvěřili, jakož řekl: Protož jsem přisáhl v hněvě svém, žeť nevejdou v odpočinutí mé, ačkoli dokonána jsou díla od ustanovení světa.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 4, 'Nebo pověděl na jednom místě o sedmém dni takto: I odpočinul Bůh dne sedmého ode všech skutků svých.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 5, 'A tuto zase: Že nevejdou v odpočinutí mé.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 6, 'A poněvadž vždy na tom jest, že někteří mají vjíti do něho, a ti, kterýmž prvé zvěstováno jest, nevešli pro nevěru,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 7, 'Opět ukládá den jakýsi: Dnes, skrze Davida, po takovém času pravě, (jakož řečeno jest:) Dnes uslyšíte-li hlas jeho, nezatvrzujte srdcí svých.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 8, 'Nebo byť byl Jozue v odpočinutí je uvedl, nebylť by potom mluvil o jiném dni.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 9, 'A protož zůstáváť svátek lidu Božímu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 10, 'Nebo kdožkoli všel v odpočinutí jeho, takéť i on odpočinul od skutků svých, jako i Bůh od svých.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 11, 'Snažmež se tedy vjíti do toho odpočinutí, aby někdo neupadl v týž příklad nedověry.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 12, 'Živáť jest zajisté řeč Boží a mocná, a pronikavější nad všeliký meč na obě strany ostrý, a dosahujeť až do rozdělení i duše i ducha i kloubů i mozku v kostech, a rozeznává myšlení i mínění srdce.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 13, 'A neníť stvoření, kteréž by nebylo zjevné před oblíčejem jeho, nýbrž všecky věci jsou nahé a odkryté očima toho, o kterémž jest řeč naše.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 14, 'Protož majíce velikého nejvyššího kněze {biskupa}, kterýž pronikl nebesa, Ježíše Syna Božího, držmež to vyznání.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 15, 'Nebo nemáme nejvyššího kněze {biskupa}, kterýž by nemohl čitedlen býti mdlob našich, ale zkušeného ve všem nám podobně, kromě hříchu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 16, 'Přistupmež tedy směle s doufáním k trůnu milosti, abychom dosáhli milosrdenství, a milost nalezli ku pomoci v čas příhodný.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 1, 'Všeliký zajisté nejvyšší kněz {biskup} z lidu vzatý za lidi bývá postaven v jednání s Bohem, totiž aby obětoval i dary i oběti za hříchy,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 2, 'Kterýž by mohl, jakž sluší, lítost míti nad neznajícími a bloudícími, jsa i sám obklíčen nemocí.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 3, 'A pro ni povinen jest, jakož za lid, tak i za sebe samého obětovati za hříchy.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 4, 'A aniž kdo sobě sám té cti osobuje, ale ten, kterýž by byl povolán od Boha, jako i Aron.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 5, 'Tak i Kristus ne sám sobě té cti osobil, aby byl nejvyšším knězem {biskupem}, ale ten, kterýž řekl jemu: Syn můj jsi ty, já dnes zplodil jsem tebe.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 6, 'Jakž i jinde praví: Ty jsi kněz na věky podlé řádu Melchisedechova.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 7, 'Kterýž za dnů těla svého modlitby a ponížené prosby k tomu, kterýž ho mohl zachovati od smrti, s křikem velikým a slzami obětoval, a vyslyšán jest v tom strachu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 8, 'A ačkoli byl Syn Boží, z toho však, což strpěl, naučil se poslušenství.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 9, 'A tak dokonalý jsa, učiněn jest všechněm sebe poslušným původem spasení věčného,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 10, 'Nazván jsa od Boha nejvyšším knězem {biskupem} podlé řádu Melchisedechova.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 11, 'O kterémž mnoho by se mělo mluviti, a to nesnadných věci k vypravení, ale vy jste nezpůsobných uší.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 12, 'Nebo měvše býti v tak dlouhém času mistři, opět potřebujete učeni býti prvním počátkům výmluvností Božích, a učiněni jste mléka potřebující, a ne pokrmu hrubšího.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 13, 'Kdožkoli zajisté mléka se drží, nechápá slova spravedlnosti; (nebo nemluvně jest.)');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 14, 'Ale dokonalých jest hrubý pokrm, totiž těch, kteříž pro zvyklost mají smysly způsobné k rozeznání dobrého i zlého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 1, 'Protož opustíce řeč počátku Kristova, k dokonalosti se nesme, ne opět zakládajíce gruntu pokání z skutků mrtvých, a víry v Boha,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 2, 'Křtů učení, a vzkládání rukou, a vzkříšení z mrtvých, i soudu věčného.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 3, 'A toť učiníme, dopustí-li Bůh.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 4, 'Nebo nemožné jest jednou již osvíceným, kteříž i zakusili daru nebeského, a účastníci učiněni byli Ducha svatého,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 5, 'Okusili také dobrého Božího slova, a moci věka budoucího,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 6, 'Kdyby padli, zase obnoviti se ku pokání, jakožto těm, kteříž opět sobě znovu křižují Syna Božího, a v porouhání vydávají.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 7, 'Země zajisté, kteráž často na sebe přicházející déšť pije, a rodí bylinu příhodnou těm, od kterýchž bývá dělána, dochází požehnání od Boha.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 8, 'Ale vydávající trní a bodláky zavržená jest, a blízká zlořečení, jejížto konec bývá spálení.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 9, 'A však, nejmilejší, nadějemeť se o vás lepších věcí, a náležejících k spasení, ač pak koli tak mluvíme.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 10, 'Neboť není nespravedlivý Bůh, aby se zapomenul na práci vaši, a na pracovitou lásku, kteréž jste dokazovali ke jménu jeho, slouživše svatým, a ještě sloužíce.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 11, 'Žádámeť pak, aby jeden každý z vás až do konce prokazoval tu opravdovou pilnost plné jistoty naděje,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 12, 'Tak abyste nebyli leniví, ale následovníci těch, kteříž skrze víru a snášelivost obdrželi dědictví zaslíbené.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 13, 'Bůh zajisté zaslíbení čině Abrahamovi, když neměl skrze koho většího přisáhnouti, přisáhl skrze sebe samého,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 14, 'Řka: Jistě požehnám velmi tobě, a velice rozmnožím tebe.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 15, 'A tak trpělivě očekávaje, dosáhl zaslíbení.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 16, 'Lidé zajisté skrze většího přisahají, a všeliké rozepře mezi nimi konec jest, když bývá potvrzena přísahou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 17, 'A takž Bůh, chtěje dostatečně ukázati dědicům zaslíbení neproměnitelnost rady své, vložil mezi to přísahu,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 18, 'Abychom skrze ty dvě věci nepohnutelné, (v nichž nemožné jest, aby Bůh klamal,) měli přepevné potěšení, my, kteříž jsme se utekli k obdržení předložené naděje.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 19, 'Kterouž máme jako kotvu duše, i bezpečnou i pevnou, a vcházející až do vnitřku za oponu,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 20, 'Kdežto předchůdce pro nás všel Ježíš, jsa učiněn podlé řádu Melchisedechova nejvyšším knězem {biskupem} na věky.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 1, 'Nebo ten Melchisedech byl král Sálem, kněz Boha nejvyššího, kterýž vyšel v cestu Abrahamovi, navracujícímu se od pobití králů, a dal jemu požehnání.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 2, 'Kterémuž Abraham i desátek dal ze všeho. Kterýž nejprvé vykládá se král spravedlnosti, potom pak i král Sálem, to jest král pokoje,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 3, 'Bez otce, bez matky, bez rodu, ani počátku dnů, ani skonání života nemaje, ale připodobněn jsa Synu Božímu, zůstává knězem věčně.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 4, 'Pohleďtež tedy, kteraký ten byl, jemuž i desátky z kořistí dal Abraham patriarcha.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 5, 'A ješto ti, kteříž jsou z synů Léví kněžství přijímající, přikázaní mají desátky bráti od lidu podlé zákona, to jest od bratří svých, ačkoli pošlých z bedr Abrahamových,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 6, 'Tento pak, jehož rod není počten mezi nimi, desátky vzal od Abrahama, a tomu, kterýž měl zaslíbení, požehnání dal.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 7, 'A jistě beze všeho odporu menší od většího požehnání béře.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 8, 'A tuto desátky berou smrtelní lidé, ale tamto ten, o němž se vysvědčuje, že jest živ.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 9, 'A ať tak dím, i sám Léví, kterýž desátky béře, v Abrahamovi desátky dal.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 10, 'Nebo ještě v bedrách otce byl, když vyšel proti němu Melchisedech.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 11, 'A protož byla-liť dokonalost skrze Levítské kněžství, (nebo za něho vydán jest lidu zákon,) jakáž toho byla potřeba, aby jiný kněz podlé řádu Melchisedechova povstal, a nebyl podlé řádu Aronova jmenován?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 12, 'A poněvadž jest kněžství přeneseno, musiloť také i zákona přenesení býti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 13, 'Nebo ten, o kterémž se to praví, jiného jest pokolení, z kteréhož žádný při oltáři v službě nebyl.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 14, 'Zjevné jest zajisté, že z pokolení Judova pošel Pán náš, o kterémžto pokolení nic z strany kněžství nemluvil Mojžíš.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 15, 'Nýbrž hojněji to ještě zjevné jest, že povstal jiný kněz podlé řádu Melchisedechova,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 16, 'Kterýž učiněn jest ne podlé zákona přikázaní tělesného, ale podlé moci života neporušitelného.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 17, 'Nebo svědčí: Ty jsi kněz na věky podlé řádu Melchisedechova.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 18, 'Stalo se zajisté složení onoho předešlého přikázaní, proto že bylo mdlé a neužitečné.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 19, 'Nebo ničeho k dokonalosti nepřivedl zákon, ale na místo jeho uvedena lepší naděje, skrze niž přibližujeme se k Bohu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 20, 'A to i podlé toho, že ne bez přísahy jest uvedena.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 21, 'Nebo onino bez přísahy kněžími učiněni bývali, tento pak s přísahou, skrze toho, kterýž řekl k němu: Přisáhl Pán, a nebudeť toho litovati: Ty jsi kněz na věky podlé řádu Melchisedechova.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 22, 'Podlé čehož lepší smlouvy prostředníkem učiněn jest Ježíš.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 23, 'A také onino mnozí bývali kněží, proto že smrt bránila jim vždycky trvati;');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 24, 'Ale tento poněvadž zůstává na věky, věčné má kněžství.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 25, 'A protož i dokonale spasiti může ty, kteříž přistupují skrze něho k Bohu, vždycky jsa živ k orodování za ně.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 26, 'Takovéhoť zajisté nám slušelo míti nejvyššího kněze {biskupa}, svatého, nevinného, nepoškvrněného, odděleného od hříšníků, a kterýž by vyšší nad nebesa učiněn byl,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 27, 'Kterýž by nepotřeboval na každý den, jako onino kněží, nejprv za své vlastní hříchy oběti obětovati, potom za lid. Nebo učinil to jednou, samého sebe obětovav.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 28, 'Zákon zajisté lidi mající nedostatky ustavoval za nejvyšší kněží {biskupy}, ale slovo přísežné, kteréž se stalo po zákonu, ustanovilo Syna dokonalého na věky.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 1, 'Ale summa toho mluvení jest, že takového máme nejvyššího kněze {biskupa}, kterýž se posadil na pravici trůnu velebnosti v nebesích.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 2, 'Služebník jsa svatyně, a pravého toho stánku, kterýž Pán vzdělal, a ne člověk.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 3, 'Všeliký zajisté nejvyšší kněz {biskup} k obětování darů a obětí bývá ustanoven, a protož potřebí bylo, aby i tento měl, co by obětoval.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 4, 'Nebo kdyby byl na zemi, aniž by knězem byl, když by zůstávali ti kněží, kteříž obětují dary podlé zákona,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 5, 'Sloužíce podobenství a stínu nebeských věcí, jakož Mojžíšovi od Boha řečeno bylo, když dokonávati měl stánek: Hlediž, prý, abys udělal všecko ku podobenství, kteréžť jest ukázáno na této hoře.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 6, 'Nyní pak tím důstojnějšího došel úřadu, čímž i lepší smlouvy prostředníkem jest, kterážto lepšími zaslíbeními jest utvrzena.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 7, 'Nebo kdyby ona první byla bez úhony, nebylo by hledáno místa druhé.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 8, 'Nebo obviňuje Židy, dí: Aj, dnové jdou, praví Pán, v nichž vejdu s domem Izraelským a s domem Judským v smlouvu novou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 9, 'Ne podlé smlouvy té, kterouž jsem učinil s otci jejich v ten den, když jsem je vzal za ruku jejich, abych je vyvedl z země Egyptské. Nebo oni nezůstali v té smlouvě mé, a já opustil jsem je, praví Pán.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 10, 'Protož tatoť jest smlouva, v kterouž vejdu s domem Izraelským po těch dnech, praví Pán: Dám, zákony své v mysl jejich, a na srdcích jejich napíši je, a budu jejich Bohem, a oni budou mým lidem.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 11, 'A nebudouť učiti jeden každý bližního svého, a jeden každý bratra svého, říkajíce: Poznej Pána, proto že mne všickni znáti budou, od nejmenšího z nich až do největšího z nich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 12, 'Nebo milostiv budu nepravostem jejich, a na hříchy jejich, ani na nepravosti jejich nikoli nezpomenu více.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 13, 'A kdyžť praví o nové, tedy pokládá první za vetchou; což pak vetší a schází, blízké jest zahynutí.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 1, 'Mělať pak i první ona smlouva nařízené služby a svatyni světskou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 2, 'Nebo udělán byl stánek první, v kterémž byl svícen, a stůl, a posvátní chlebové, a ten sloul svatyně.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 3, 'Za druhou pak oponou byl stánek, kterýž sloul svatyně svatých,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 4, 'Zlatou maje kadidlnici, a truhlu smlouvy, všudy obloženou zlatem, kdežto bylo věderce zlaté, mající v sobě mannu, a hůl Aronova, kteráž byla zkvetla, a dsky zákona,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 5, 'Nad truhlou pak cherubínové slávy, zastěňující slitovnici. O kterýchž věcech není potřebí nyní vypravovati o jedné každé obzvláštně.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 6, 'To pak když tak jest zřízeno, do prvního stánku vždycky vcházejí kněží, služby vykonávajíce,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 7, 'Do druhého pak jedinou v rok sám nejvyšší kněz {biskup}, ne bez krve, kterouž obětuje sám za sebe, i za lidské nevědomosti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 8, 'Čímž Duch svatý ukazuje to, že ještě nebyla zjevena cesta k svatyni, dokudž první stánek trval.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 9, 'Kterýž byl podobenstvím na ten tehdejší čas, v němž darové a oběti se obětují, kteréž nemohou dokonalého v svědomí učiniti toho, kdož obětuje,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 10, 'Toliko v pokrmích a v nápojích, a v rozličných umýváních a ospravedlňováních tělesných, až do času napravení, záležející.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 11, 'Ale Kristus přišed, nejvyšší kněz {biskup} budoucího dobrého, skrze větší a dokonalejší stánek, ne rukou udělaný, to jest ne tohoto stavení,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 12, 'Ani skrze krev kozlů a telat, ale skrze svou vlastní krev, všed jednou do svatyně, věčné vykoupení nalezl.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 13, 'Nebo jestližeť krev býků a kozlů, a popel jalovice, pokropující poškvrněných, posvěcuje k očištění těla,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 14, 'Čím více krev Kristova, kterýž skrze Ducha věčného samého sebe obětoval nepoškvrněného Bohu, očistí svědomí vaše od skutků mrtvých k sloužení Bohu živému?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 15, 'A pro tu příčinu nové smlouvy prostředník jest, aby, když by smrt mezi to vkročila k vyplacení přestoupení těch, kteráž byla za první smlouvy, zaslíbení věčného dědictví přijali ti, kdož jsou povoláni.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 16, 'Nebo kdež jest kšaft, potřebí jest, aby k tomu smrt přikročila toho, kdož činí kšaft.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 17, 'Kšaft zajisté těch, kteříž zemřeli, stálý jest, poněvadž ještě nemá moci, dokudž živ jest ten, kdož kšaft činil.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 18, 'Protož ani první onen bez krve nebyl posvěcován.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 19, 'Nebo když Mojžíš všecka přikázaní podlé zákona všemu lidu předložil, vzav krev telat a kozlů, s vodou a s vlnou červenou a s yzopem, tak spolu i knihy i všeho lidu pokropil,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 20, 'Řka: Tatoť jest krev zákona, kterýž vám Bůh vydal.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 21, 'Ano i stánku i všech nádob k službě náležitých rovně též krví pokropil.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 22, 'A téměř všecko podlé zákona krví očišťováno bývá, a bez krve vylití nebývá odpuštění vin.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 23, 'Protož potřebí bylo, aby věcí nebeských příkladové těmi věcmi očišťováni byli, nebeské pak věci lepšími obětmi, nežli jsou ty.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 24, 'Neboť nevšel Kristus do svatyně rukou udělané, kteráž by nesla figůru pravé, ale v samo nebe, aby nyní přítomný byl tváři Boží za nás.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 25, 'Ne aby častokrát obětoval sebe samého, jako nejvyšší kněz {biskup} vcházel do svatyně každý rok se krví cizí,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 26, '(Sic jinak by byl musil častokrát trpěti od počátku světa,) ale nyní jednou při skonání věků, na shlazení hřícha skrze obětování sebe samého, zjeven jest.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 27, 'A jakož uloženo lidem jednou umříti, a potom bude soud,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 28, 'Tak i Kristus jednou jest obětován, k shlazení mnohých lidí hříchů; podruhé bez hříchu ukáže se těm, kteříž ho čekají k spasení.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 1, 'Zákon zajisté, maje stín budoucího dobrého, a ne sám obraz těch věcí, jednostejnými obětmi, kteréž po všecka léta obětují, nikdy nemůž přistupujících dokonalých učiniti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 2, 'Sic jinak zdaliž by již nepřestaly obětovány býti, proto že by již neměli žádného svědomí z hříchů ti, kteříž obětují, jsouce jednou očištěni?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 3, 'Ale při těch obětech připomínání hříchů děje se každého roku.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 4, 'Neboť možné není, aby krev býků a kozlů shladila hříchy.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 5, 'Protož vcházeje na svět, dí: Oběti a daru nechtěl jsi, ale tělo jsi mi způsobil.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 6, 'Zápalných obětí, ani obětí za hřích jsi neoblíbil.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 7, 'Tehdy řekl jsem: Aj, jduť, (jakož v knihách psáno jest o mně,) abych činil, ó Bože, vůli tvou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 8, 'Pověděv napřed: Že oběti a daru, a zápalů, i obětí za hřích, (kteréž se podlé zákona obětují,) nechtěl jsi, aniž jsi oblíbil,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 9, 'Tehdy řekl: Aj, jduť, abych činil, ó Bože, vůli tvou. Ruší první, aby druhé ustanovil.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 10, 'V kteréžto vůli posvěceni jsme skrze obětování těla Ježíše Krista jednou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 11, 'A všeliký zajisté kněz přístojí, na každý den službu konaje, a jednostejné často obětuje oběti, kteréž nikdy nemohou odjíti hříchů.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 12, 'Ale tento, jednu obět obětovav za hříchy, vždycky sedí na pravici Boží,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 13, 'Již dále očekávaje, až by položeni byli nepřátelé jeho za podnož noh jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 14, 'Nebo jednou obětí dokonalé učinil na věky ty, kteříž posvěceni bývají.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 15, 'Svědčíť pak nám to i sám Duch svatý. Nebo prvé pověděv:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 16, 'Tatoť jest smlouva, kterouž učiním s nimi po těch dnech, praví Pán: Dám zákony své v srdce jejich, a na myslech jejich napíši je,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 17, 'A na hříchy jejich, i na nepravosti jejich nikoli nezpomenu více.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 18, 'Kdežť pak jest odpuštění jich, neníť více oběti za hřích.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 19, 'Majíce tedy, bratří, plnou svobodu k vjití do svatyně skrze krev Ježíšovu,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 20, '(Tou cestou novou a živou, kterouž nám způsobil skrze oponu, to jest tělo své,)');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 21, 'A kněze velikého nad domem Božím,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 22, 'Přistupmež s pravým srdcem, v plné jistotě víry, očištěná majíce srdce od svědomí zlého,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 23, 'A umyté tělo vodou čistou, držmež nepochybné vyznání naděje; (nebo věrnýť jest ten, kterýž zaslíbil.)');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 24, 'A šetřme jedni druhých, k rozněcování se v lásce a dobrých skutcích,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 25, 'Neopouštějíce společného shromáždění svého, jako někteří obyčej mají, ale napomínajíce se, a to tím více, čímž více vidíte, že se ten den přibližuje.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 26, 'Nebo jestliže bychom dobrovolně hřešili po přijetí známosti pravdy, nezůstávalo by již oběti za hříchy,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 27, 'Ale hrozné nějaké očekávání soudu, a ohně prudká pálivost, kterýž žráti má protivníky.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 28, 'Kdož by koli pohrdal zákonem Mojžíšovým, bez lítosti pode dvěma neb třmi svědky umírá.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 29, 'Což se vám zdá, čím přísnějšího trestání hoden jest ten, kdož by Syna Božího pošlapával, a krev smlouvy, kterouž byl posvěcen, za nehodnou drahého vážení by měl, a Duchu milosti potupu učinil?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 30, 'Známeť zajisté toho, jenž řekl: Mně pomsta, já odplatím, praví Pán. A opět: Pán souditi bude lid svůj.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 31, 'Hroznéť jest upadnouti v ruce Boha živého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 32, 'Rozpomeňtež se pak na předešlé dny, v nichž osvíceni byvše, mnohý boj utrpení snášeli jste,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 33, 'Buďto když jste byli i pohaněními i ssouženími jako divadlo učiněni, buďto účastníci učiněni byvše těch, kteříž tak zmítáni byli.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 34, 'Nebo i vězení mého čitelni jste byli, a rozchvátání statků svých s radostí jste strpěli, vědouce, že v sobě máte lepší zboží nebeské a trvanlivé.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 35, 'Protož nezamítejtež smělé doufanlivosti své, kteráž velikou má odplatu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 36, 'Než potřebíť jest vám trpělivosti, abyste vůli Boží činíce, dosáhli zaslíbení.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 37, 'Nebo ještě velmi, velmi maličko, a aj, ten, kterýž přijíti má, přijde, a nebudeť meškati,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 38, 'Spravedlivý pak z víry živ bude. Pakli by se jinam obrátil, nezalibuje sobě duše má v něm.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 39, 'Ale myť nejsme poběhlci k zahynutí, ale věřící k získání duše.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 1, 'Víra pak jest nadějných věcí podstata, a důvod neviditelných.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 2, 'Pro ni zajisté svědectví došli předkové.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 3, 'Věrou rozumíme, že učiněni jsou věkové slovem Božím, tak že z ničeho jest to, což vidíme, učiněno.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 4, 'Věrou lepší obět Bohu obětoval Abel, nežli Kain, skrze kterouž svědectví obdržel, že jest spravedlivý, jakž sám Bůh darům jeho svědectví vydal. A skrze tu, umřev, ještě mluví.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 5, 'Věrou Enoch přenesen jest, aby neviděl smrti, a není nalezen, proto že jej Bůh přenesl. Prvé zajisté, než jest přenesen, svědectví měl, že se líbil Bohu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 6, 'Bez víry pak nemožné jest líbiti se jemu; nebo přistupující k Bohu věřiti musí, že jest Bůh, a těm, kteříž ho hledají, že odplatu dává.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 7, 'Věrou napomenut jsa od Boha Noé o tom, čehož ještě nebylo viděti, boje se, připravoval koráb k zachování domu svého; skrze nějž potupil svět, a spravedlnosti té, kteráž jest z víry, učiněn jest dědicem.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 8, 'Věrou, povolán jsa Abraham, uposlechl Boha, aby odšel na to místo, kteréž měl vzíti za dědictví; i šel, nevěda, kam přijde.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 9, 'Věrou bydlil v zemi zaslíbené jako v cizí, v staních přebývaje s Izákem a s Jákobem, spoludědici téhož zaslíbení.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 10, 'Nebo očekával města základy majícího, jehožto řemeslník a stavitel jest Bůh.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 11, 'Věrou také i Sára moc ku početí semene přijala, a mimo čas věku porodila, když věřila, že jest věrný ten, kterýž zaslíbil.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 12, 'A protož i z jednoho, a to již umrtveného, rozplodilo se potomků, jako jest množství hvězd nebeských, a jako písek nesčíslný, kterýž jest na břehu mořském.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 13, 'Podlé víry zemřeli ti všickni, nevzavše zaslíbení, ale zdaleka je viděvše, jim i věřili, i je vítali, a vyznávali, že jsou hosté a příchozí na zemi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 14, 'Nebo ti, kteříž tak mluví, zjevně to prokazují, že vlasti hledají.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 15, 'A jistě, kdyby se byli na onu rozpomínali, z kteréž vyšli, měli dosti času zase se navrátiti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 16, 'Ale oni lepší žádají, to jest nebeské. Protož i sám Bůh nestydí se slouti jejich Bohem; nebo připravil jim město.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 17, 'Věrou obětoval Abraham Izáka, byv pokoušín, a to jednorozeného obětoval ten, kterýž byl zaslíbení přijal,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 18, 'K němuž bylo řečeno: V Izákovi nazváno bude tobě símě,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 19, 'Tak o tom smýšleje, že jest mocen Bůh i z mrtvých vzkřísiti. Pročež jej jako z mrtvých vzkříšeného přijal.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 20, 'Věrou o budoucích věcech požehnání dal Izák Jákobovi a Ezau.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 21, 'Věrou Jákob, umíraje, každému z synů Jozefových požehnání dával, a poklonil se na vrch hůlky své.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 22, 'Věrou Jozef, dokonávaje, o vyjití synů Izraelských zmínku učinil, a o kostech svých poručil.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 23, 'Věrou Mojžíš, narodiv se, ukryt byl za tři měsíce od rodičů svých, proto že viděli krásné pacholátko, a nebáli se rozkazu královského.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 24, 'Věrou Mojžíš, byv již dorostlý, odepřel slouti synem dcery Faraonovy,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 25, 'Vyvoliv sobě raději protivenství trpěti s lidem Božím, nežli časné a hříšné pohodlí míti,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 26, 'Větší sobě pokládaje zboží nad Egyptské poklady pohanění Kristovo; nebo prohlédal k odplatě.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 27, 'Věrou opustil Egypt, neboje se hněvu královského; nebo jako by viděl neviditelného, tak se utvrdil.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 28, 'Věrou slavil hod beránka a vylití krve, aby ten, kterýž hubil prvorozené, nedotekl se jich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 29, 'Věrou přešli moře červené jako po suchu; o čež pokusivše se Egyptští, ztonuli.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 30, 'Věrou zdi Jericha padly, když je obcházeli za sedm dní.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 31, 'Věrou Raab nevěstka nezahynula s neposlušnými, pokojně přijavši špehéře.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 32, 'A coť mám více praviti: Nepostačíť mi zajisté čas k vypravování o Gedeonovi, a Barákovi, a Samsonovi a Jefte, a Davidovi, a Samuelovi, a prorocích.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 33, 'Kteříž skrze víru vybojovávali království, činili spravedlnost, docházeli zaslíbení, zacpávali ústa lvům,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 34, 'Uhašovali moc ohně, utekli ostrosti meče, zmocněni bývali v mdlobách, silní učiněni v boji, vojska zaháněli cizozemců.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 35, 'Ženy přijímaly mrtvé své vzkříšené. Jiní pak roztahováni jsou, neoblíbivše sobě vysvobození, aby lepšího dosáhli vzkříšení.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 36, 'Jiní pak posměchy a mrskáním trápeni, ano i vězeními a žaláři.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 37, 'Kamenováni jsou, sekáni, pokoušíni, mečem zmordováni; chodili v kožích ovčích a kozelčích, opuštěni, ssouženi, a zle s nimi nakládáno,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 38, 'Jichžto nebyl svět hoden, po pustinách bloudíce, i po horách, a jeskyních, i v doupatech země.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 39, 'A ti všickni svědectví dosáhše skrze víru, neobdrželi zaslíbení,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 40, 'Proto že Bůh něco lepšího nám obmýšlel, aby oni bez nás nepřišli k dokonalosti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 1, 'Protož i my, takový oblak svědků vůkol sebe majíce, odvrhouce všeliké břímě, i snadně obkličující nás hřích, skrze trpělivost konejme běh uloženého sobě boje,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 2, 'Patříce na vůdce a dokonavatele víry Ježíše, kterýž místo předložené sobě radosti strpěl kříž, opováživ se hanby, i posadil se na pravici trůnu Božího.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 3, 'A považte, jaký jest ten, kterýž snášel od hříšníků taková proti sobě odmlouvání, abyste neustávali, v myslech svých hynouce.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 4, 'Ještě jste se až do krve nezprotivili, proti hříchu bojujíce.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 5, 'A což jste zapomenuli na napomenutí, kteréž k vám jako k synům mluví: Synu můj, nepohrdej kázní Páně, aniž sobě stýskej, když od něho trestán býváš?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 6, 'Nebo kohož miluje Pán, tohoť tresce, a švihá každého, kteréhož za syna přijímá.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 7, 'Jestliže kázeň snášíte, Bůh se vám podává jako synům. Nebo který jest syn, jehož by netrestal otec?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 8, 'Pakli jste bez kázně, kteréž všickni účastni jsou, tedy jste cizoložňata, a ne synové.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 9, 'Ano tělesné otce své měli jsme, kteříž nás trestali, a měli jsme je u vážnosti, i zdaliž nemáme mnohem více poddáni býti Otci duchů, abychom živi byli?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 10, 'A onino zajisté po nemnohé dny, jakž se jim vidělo, trestali, ale tento v věcech přeužitečných, totiž k tomu, abychom došli účastnosti svatosti jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 11, 'Každé pak trestání, když přítomné jest, nezdá se býti potěšené, ale smutné, než potomť rozkošné ovoce spravedlnosti přináší těm, kteříž by v něm pocvičeni byli.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 12, 'Protož opuštěných rukou a zemdlených kolen posilňte,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 13, 'A přímé kroky čiňte nohama svýma, aby, což zkulhavělo, do konce se nevyvinulo, ale raději uzdraveno bylo.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 14, 'Pokoje následujte se všechněmi a svatosti, bez níž žádný neuzří Pána,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 15, 'Prohlédajíce, aby někdo neodpadl od milosti Boží, a aby nějaký kořen hořkosti nepodrostl, a neučinil překážky, skrze nějž by poškvrněni byli mnozí;');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 16, 'Aby někdo nebyl smilník, aneb ohyzdný, jako Ezau, kterýž za jednu krmi prodal prvorozenství své.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 17, 'Víte zajisté, že potom, chtěje dědičně dosáhnouti požehnání, pohrdnut jest. Nebo nenalezl místa ku pokání, ačkoli ho s pláčem hledal.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 18, 'Nebo nepřistoupili jste k hmotné hoře a k hořícímu ohni, a k vichru, a k mrákotě, a k bouři,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 19, 'A k zvuku trouby a k hlasu slov, kterýž kdož slyšeli, prosili, aby k nim nebylo více mluveno.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 20, '(Nebo nemohli snésti toho, což bylo praveno: Kdyby se i hovado dotklo hory, budeť ukamenováno, aneb šípem postřeleno.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 21, 'A tak hrozné bylo to, což viděli, že Mojžíš řekl: Lekl jsem se, až se třesu.)');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 22, 'Ale přistoupili jste k hoře Sionu, a k městu Boha živého, Jeruzalému nebeskému, a k nesčíslnému zástupu andělů,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 23, 'K veřejnému shromáždění a k církvi prvorozených, kteříž zapsáni jsou v nebesích, a k Bohu soudci všech, a k duchům spravedlivých dokonalých,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 24, 'A k prostředníku Nového Zákona Ježíšovi, a ku pokropení krví, lépe mluvící než Abelova.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 25, 'Viztež, abyste neodpírali mluvícímu. Nebo poněvadž onino neušli, kteříž odpírali tomu, jenž na zemi na místě Božím mluvil, čím více my, jestliže tím, kterýž s nebe jest, pohrdneme?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 26, 'Jehož hlas tehdáž byl zemí pohnul, nyní pak zaslíbil, řka: Ještěť já jednou pohnu netoliko zemí, ale i nebem.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 27, 'To pak, že dí: Ještě jednou, světle ukazuje pohnutelných věcí přenesení, jakožto učiněných, aby zůstávaly ty, kteréž jsou nepohnutelné.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 28, 'Protož království přijímajíce nepohnutelné, mějmež milost, skrze kteroužto služme libě Bohu, s vážností a uctivostí.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 29, 'Neboť Bůh náš jest oheň spalující.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 1, 'Láska bratrská ať zůstává.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 2, 'Na přívětivost k hostem nezapomínejte; skrze ni zajisté někteří, nevěděvše, anděly za hostě přijímali.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 3, 'Pomněte na vězně, jako byste spoluvězňové byli, na ssoužené, jakožto ti, kteříž také v těle jste.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 4, 'Poctivéť jest u všech manželství a lože nepoškvrněné, smilníky pak a cizoložníky souditi bude Bůh.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 5, 'Obcování veďte bez lakomství, dosti majíce na tom, což máte. Onť zajisté řekl: Nikoli nenechám tebe, aniž tě opustím;');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 6, 'Tak abychom doufanlivě říkali: Pán spomocník můj, aniž se budu báti, by mi co učiniti mohl člověk.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 7, 'Zpomínejte na vůdce své, kteříž vám mluvili slovo Boží, jejichžto obcování jaký byl cíl, spatřujíce, následujtež jejich víry.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 8, 'Ježíš Kristus včera i dnes tentýž jest, i na věky.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 9, 'Učením rozličným a cizím nedejte se točiti. Výbornéť jest zajisté, aby milostí upevněno bylo srdce, a ne pokrmy, kteříž neprospěli těm, kteříž se jimi vázali.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 10, 'Mámeť oltář, z něhož ti nemají práva jísti, kdož stánku slouží.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 11, 'Nebo kterýchž hovad krev vnášína bývá za hřích do svatyně skrze nejvyššího kněze {biskupa}, těch pálena bývají těla vně za stany.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 12, 'Protož i Ježíš, aby posvětil lidu svou vlastní krví, vně za branou trpěl.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 13, 'Vyjděmež tedy k němu ven z stanů, pohanění jeho nesouce.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 14, 'Neboť nemáme zde města zůstávajícího, ale onoho budoucího hledáme.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 15, 'Protož skrze něho obětujme Bohu obět chvály vždycky, to jest ovoce rtů, oslavujících jméno jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 16, 'Na účinnost pak a na zdílnost nezapomínejte; nebo v takových obětech zvláštní svou líbost má Bůh.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 17, 'Povolni buďte správcům svým a poslušni; oniť zajisté bdějí nad dušemi vašimi, jako ti, kteříž počet mají vydati, aby to s radostí činili, a ne s stýskáním. Neboť by vám to nebylo užitečné.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 18, 'Modltež se za nás; doufámeť zajisté, že dobré svědomí máme, jako ti, kteříž se chceme ve všem chvalitebně chovati.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 19, 'Tím pak více prosím vás, abyste to činili, proto abych tím dříve navrácen byl vám.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 20, 'Bůh pak pokoje, kterýž toho velikého pro krev smlouvy věčné pastýře ovcí vzkřísil z mrtvých, Pána našeho Ježíše,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 21, 'Učiniž vás způsobné ve všelikém skutku dobrém, k činění vůle své, působě v vás to, což jest libé před oblíčejem jeho, skrze Jezukrista, jemuž sláva na věky věků. Amen.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 22, 'Prosímť pak vás, bratří, snestež trpělivě slovo napomenutí tohoto; neboť jsem krátce psal vám.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 23, 'Věztež o bratru Timoteovi, že jest propuštěn, s kterýmžto, (přišel-li by brzo,) navštívím vás.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 24, 'Pozdravtež všech správců svých, i všech svatých. Pozdravují vás bratří z Vlach.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 25, 'Milost Boží se všechněmi vámi. Amen.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 1, 'Jakub, Boží a Pána Jezukrista služebník, dvanácteru pokolení rozptýlenému pozdravení.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 2, 'Za největší radost mějte, bratří moji, kdyžkoli v rozličná pokušení upadáte,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 3, 'Vědouce, že zkušení víry vaší působí trpělivost.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 4, 'Trpělivost pak ať má dokonalý skutek, abyste byli dokonalí a celí, v ničemž nemajíce nedostatku.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 5, 'Jestliže pak komu z vás nedostává se moudrosti, žádejž jí od Boha, kterýž všechněm dává ochotně a neomlouvá, i budeť dána jemu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 6, 'Žádejž pak důvěrně, nic nepochybuje. Nebo kdož pochybuje, podoben jest vlnám mořským, kteréž vítr sem i tam žene, a jimi zmítá.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 7, 'Nedomnívej se zajisté člověk ten, by co vzíti měl ode Pána.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 8, 'Muž dvojí mysli, jest neustavičný ve všech cestách svých.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 9, 'Chlubiž se pak bratr ponížený v povýšení svém,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 10, 'A bohatý v ponižování se; nebo jako květ byliny pomine.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 11, 'Nebo jakož slunce vzešlé s horkostí usušilo bylinu, a květ její spadl, i ušlechtilost postavy jeho zhynula, takť i bohatý v svých cestách usvadne.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 12, 'Blahoslavený muž, kterýž snáší pokušení; nebo když bude zkušen, vezme korunu života, kterouž zaslíbil Pán těm, kdož ho milují.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 13, 'Žádný, když bývá pokoušín, neříkej, že by od Boha pokoušín byl; neboť Bůh nemůže pokoušín býti ve zlém, aniž také on koho pokouší.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 14, 'Ale jeden každý pokoušín bývá, od svých vlastních žádostí jsa zachvacován a oklamáván.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 15, 'Potom žádost když počne, porodí hřích, hřích pak vykonaný zplozuje smrt.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 16, 'Nebluďtež, bratří moji milí.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 17, 'Všeliké dání dobré a každý dar dokonalý shůry jest sstupující od Otce světel, u něhož není proměnění, ani pro obrácení se jinam zastínění.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 18, 'On proto, že chtěl, zplodil nás slovem pravdy, k tomu, abychom byli prvotiny nějaké stvoření jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 19, 'A tak, bratří moji milí, budiž každý člověk rychlý k slyšení, ale zpozdilý k mluvení, zpozdilý k hněvu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 20, 'Nebo hněv muže spravedlnosti Boží nepůsobí.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 21, 'Protož odvrhouce všelikou nečistotu, a ohyzdnost zlosti, s tichostí přijímejte vsáté slovo, kteréž může spasiti duše vaše.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 22, 'Buďtež pak činitelé slova, a ne posluchači toliko, oklamávajíce sami sebe.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 23, 'Nebo byl-li by kdo posluchač slova, a ne činitel, ten podoben jest muži spatřujícímu oblíčej přirozený svůj v zrcadle.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 24, 'Vzhlédl se zajisté, i odšel, a hned zapomenul, jaký by byl.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 25, 'Ale kdož by se vzhlédl v dokonalý zákon svobody, a zůstával by v něm, ten nejsa posluchač zapominatelný, ale činitel skutku, blahoslavený bude v skutku svém.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 26, 'Zdá-li se pak komu z vás, že jest nábožný, a v uzdu nepojímá jazyka svého, ale svodí srdce své, takového marné jest náboženství.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 27, 'Náboženství čisté a nepoškvrněné před Bohem a Otcem totoť jest: Navštěvovati sirotky a vdovy v ssouženích jejich, a ostříhati sebe nepoškvrněného od světa.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 1, 'Bratří moji, nepřipojujtež přijímání osob k víře slavného Pána našeho Jezukrista.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 2, 'Nebo kdyby přišel do shromáždění vašeho muž, maje prsten zlatý v drahém rouše, a všel by také i chudý v chaterném oděvu,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 3, 'A popatřili byste k tomu, kterýž drahé roucho má, a řekli byste jemu: Ty sedni tuto poctivě; chudému pak řekli byste: Ty stůj tamto, aneb sedni tuto, pod podnoží noh mých:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 4, 'Zdaliž jste již neučinili rozdílu mezi sebou a učiněni jste soudcové v myšleních zlých?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 5, 'Slyšte, bratří moji milí, zdaliž Bůh nevyvolil chudých na tomto světě, aby bohatí byli u víře a dědicové království, kteréž zaslíbil těm, kdož jej milují?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 6, 'Ale vy jste neuctili chudého. Zdaliž bohatí mocí neutiskují vás? A oniť vás i k soudům přivozují?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 7, 'Zdali oni nerouhají se tomu slavnému jménu, kteréž vzýváno jest nad vámi?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 8, 'Jestliže pak plníte zákon královský podlé písma: Milovati budeš bližního svého, jako sebe samého, dobře činíte.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 9, 'Pakliť osoby přijímáte, hřešíte, a zákon vás tresce jako přestupníky.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 10, 'Nebo kdo by koli celého zákona ostříhal, přestoupil by pak jediné, všechněmi jest vinen.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 11, 'Ten zajisté, kterýž řekl: Nesesmilníš, takéť řekl: Nezabiješ. Pakli bys nesesmilnil, ale zabil bys, učiněn jsi přestupníkem zákona.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 12, 'Tak mluvte, a tak čiňte, jako ti, kteříž podlé zákona svobody souzeni býti máte.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 13, 'Nebo odsouzení bez milosrdenství stane se tomu, kdož nečiní milosrdenství, ale chlubíť se milosrdenstvím proti odsudku.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 14, 'Co prospěje, bratří moji, praví-li se kdo víru míti, a nemá-li skutků? Zdaliž jej ta víra může spasiti?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 15, 'A kdyby bratr neb sestra neodění byli, a opuštění z strany živnosti vezdejší,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 16, 'Řekl by pak jim někdo z vás: Jděte v pokoji, shřejte se, a najezte se, a však nedali byste jim potřeby tělesné, což to platí?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 17, 'Takž i víra, nemá-li skutků, mrtváť jest sama v sobě.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 18, 'Ale dí někdo: Ty víru máš, a já mám skutky. Ukažiž ty mi víru svou z skutků svých, a já tobě ukáži víru svou z skutků svých.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 19, 'Ty věříš, že jest jeden Bůh. Dobře činíš. I ďáblovéť tomu věří, a však třesou se.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 20, 'Ale chceš-liž věděti, ó člověče marný, že víra bez skutků jest mrtvá?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 21, 'Abraham otec náš zdali ne z skutků ospravedlněn jest, obětovav syna svého Izáka na oltář?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 22, 'Vidíš-li, že víra napomáhala skutkům jeho, a z skutků víra dokonalá byla?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 23, 'A tak naplněno jest písmo, řkoucí: I uvěřil Abraham Bohu, a počteno jest jemu za spravedlnost, a přítelem Božím nazván jest.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 24, 'Vidíte-liž tedy, že z skutků ospravedlněn bývá člověk, a ne z víry toliko?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 25, 'Též podobně i Raab nevěstka zdali ne z skutků ospravedlněna jest, přijavši ony posly, a jinou cestou pryč vypustivši?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 26, 'Nebo jakož tělo bez duše jest mrtvé, takť i víra bez skutků jest mrtvá.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 1, 'Nebuďtež mnozí mistři, bratří moji, vědouce, že bychom těžší odsouzení vzali.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 2, 'V mnohém zajisté klesáme všickni. Kdožť neklesá v slovu, tenť jest dokonalý muž, mohoucí jako uzdou spravovati také všecko tělo.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 3, 'An, my koňům udidla v ústa dáváme, aby nám povolni byli, a vším tělem jejich vládneme.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 4, 'An, i lodí tak veliké jsouce, a prudkými větry hnány bývajíce, však i nejmenším veslem bývají sem i tam obracíny, kamžkoli líbí se tomu, kdož je spravuje.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 5, 'Tak i jazyk malý oud jest, a však veliké věci provodí. Aj, maličký oheň, kterak veliký les zapálí!');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 6, 'Jazyk pak jest oheň a svět nepravosti. Takť jest postaven jazyk mezi oudy našimi, nanečišťující celé tělo, a rozpalující kolo narození našeho, jsa rozněcován od ohně pekelného.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 7, 'Všeliké zajisté přirození i zvěři, i ptactva, i zeměplazů, i mořských potvor bývá skroceno, a jest okroceno od lidí;');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 8, 'Ale jazyka žádný z lidí skrotiti nemůže. Tak jest neskrotitelné zlé, pln jsa jedu smrtelného.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 9, 'Jím dobrořečíme Bohu Otci, a jím zlořečíme lidem, ku podobenství Božímu stvořeným.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 10, 'Z jedněch a týchž úst pochází dobrořečení i zlořečení. Ne takť býti má, bratří moji.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 11, 'Zdaliž studnice jedním pramenem vydává sladkost i hořkost?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 12, 'Zdaliž může, bratří moji, fíkový strom nésti olivky, aneb vinný kmen fíky? Takť žádná studnice slané i sladké vody nevydává.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 13, 'Kdo jest moudrý a umělý mezi vámi? Ukažiž dobrým obcováním skutky své v krotké moudrosti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 14, 'Pakliť máte hořkou závist, a dráždění v srdci svém, nechlubte se, a neklamejte proti pravdě.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 15, 'Neníť ta moudrost s hůry sstupující, ale jest zemská, hovadná, ďábelská.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 16, 'Nebo kdež jest závist a rozdráždění, tu i roztržka i všeliké dílo zlé.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 17, 'Ale moudrost, kteráž jest s hůry, nejprvé zajisté jest čistotná, potom pokojná, mírná, povolná, plná milosrdenství a ovoce dobrého, bez rozsuzování a bez pokrytství.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 18, 'Ovoce pak spravedlnosti v pokoji rozsívá se těm, kteříž pokoj působí.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 1, 'Odkud jdou bojové a svády mezi vámi? Zdali ne odtud, totiž z líbostí vašich, kteréž rytěřují v oudech vašich?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 2, 'Žádáte, a nemáte; závidíte a dychtíte, a nemůžete dosáhnouti; bojujete a válčíte, a však neobdržíváte, proto že neprosíte.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 3, 'Prosíte, a nebéřete, proto že zle prosíte, abyste na své líbosti vynakládali.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 4, 'Cizoložníci a cizoložnice, což nevíte, že přízeň světa jest nepřítelkyně Boží? A protož kdo by koli chtěl býti přítelem tohoto světa, nepřítelem Božím učiněn bývá.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 5, 'Což mníte, že nadarmo dí písmo: Zdali k závisti nakloňuje duch ten, kterýž přebývá v nás?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 6, 'Nýbrž hojnější dává milost. Nebo dí: Bůh se pyšným protiví, ale pokorným dává milost.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 7, 'Poddejtež se tedy Bohu, a zepřete se ďáblu, i utečeť od vás.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 8, 'Přibližte se k Bohu, a přiblížíť se k vám. Umejte ruce, hříšníci, a očisťte srdce vy, kteříž jste dvojité mysli.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 9, 'Ssouženi buďte, a kvělte, a plačte; smích váš obratiž se v kvílení, a radost v zámutek.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 10, 'Ponižte se před oblíčejem Páně, a povýšíť vás.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 11, 'Neutrhejtež jedni druhým, bratří. Kdož utrhá bratru, a potupuje bratra svého, utrhá zákonu, a potupuje zákon. Tupíš-li pak zákon, nejsi plnitel zákona, ale soudce.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 12, 'Jedenť jest vydavatel zákona, kterýž může spasiti i zatratiti. Ty kdo jsi, ješto tupíš jiného?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 13, 'Ale nuže vy, kteříž říkáte: Dnes neb zítra vypravíme se do onoho města, a pobudeme tam přes celý rok, a budeme kupčiti, a něco zištěme;');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 14, '(Ješto nevíte, co zítra bude. Nebo jaký jest život váš? Pára zajisté jest, kteráž se na maličko ukáže, a potom zmizí.)');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 15, 'Místo toho, co byste měli říci: Bude-li Pán chtíti, a budeme-li živi, učiníme toto neb onono.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 16, 'Vy pak chlubíte se v pýše své. Všeliká taková chlouba zlá jest.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 17, 'A protož kdo umí dobře činiti, a nečiní, hřích má.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 1, 'Nuže nyní, boháči, plačte, kvílíce nad bídami svými, kteréž přijdou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 2, 'Zboží vaše shnilo, a roucho vaše zmolovatělo.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 3, 'Zlato vaše a stříbro zerzavělo, a rez jejich bude na svědectví proti vám, a zžířeť těla vaše jako oheň. Shromáždili jste poklad ku posledním dnům.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 4, 'Aj, mzda dělníků, kteříž žali krajiny vaše, při vás zadržaná, křičí, a hlas volání ženců v uši Pána zástupů vešel.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 5, 'Rozkoš jste provodili na zemi, a zbůjněli jste; vykrmili jste srdce svá jako ke dni zabití.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 6, 'Odsoudili jste, zamordovali jste spravedlivého, a neodpíral vám.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 7, 'A protož trpěliví buďte, bratří, až do příchodu Páně. Aj, oráč očekává drahého užitku zemského, trpělivě naň očekávaje, až by přijal podzimní i jarní déšť.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 8, 'Buďtež i vy trpěliví, potvrzujte srdcí svých; neboť se přibližuje příští Páně.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 9, 'Nevzdychejtež jedni proti druhým, bratří, abyste nebyli odsouzeni. Aj, soudce již přede dveřmi stojí.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 10, 'Ku příkladu snášení protivenství a dlouhočekání, bratří moji, vezměte proroky, kteříž mluvívali ve jménu Páně.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 11, 'Aj, blahoslavíme ty trpělivé. O trpělivosti Jobově slýchali jste, a dokonání Páně viděli jste; nebo velmi jest milosrdný Pán a lítostivý.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 12, 'Přede všemi pak věcmi, bratří moji, nepřisahejte, ani skrze nebe, ani skrze zemi, ani kteroukoli jinou přísahou, ale buď řeč vaše: Jistě, jistě, nikoli, nikoli, abyste neupadli v odsouzení.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 13, 'Jest-li kdo z vás zkormoucený? Modl se. Pakli jest kdo mysli dobré? Prozpěvuj.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 14, 'Stůně-li kdo z vás? Zavolej starších zboru, ať se modlí za něho, mažíce jej olejem ve jménu Páně.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 15, 'A modlitba víry uzdraví neduživého, a pozdvihneť ho Pán; a jestliže jest co prohřešil, budeť jemu odpuštěno.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 16, 'Vyznávejtež se pak jedni druhým z hříchů, a modlte se jedni za druhé, abyste uzdraveni byli. Mnohoť může modlitba spravedlivého opravdová.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 17, 'Eliáš byl člověk týmž bídám jako i my poddaný, a modlitbou modlil se, aby nepršelo, i nepršel déšť na zemi za tři léta a za šest měsíců.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 18, 'A zase modlil se, i vydalo nebe déšť, a země zplodila ovoce své.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 19, 'Bratří, jestliže by kdo z vás pobloudil od pravdy, a někdo by jej zase obrátil,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 20, 'Věziž, že ten, kdož by odvrátil hříšníka od bludné cesty jeho, vysvobodí duši od smrti, a přikryje množství hříchů.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 1, 'Petr, apoštol Ježíše Krista, příchozím rozptýleným v Pontu, Galacii, Kappadocii, v Azii, a v Bitynii,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 2, 'Vyvoleným podlé předzvědění Boha Otce, v posvěcení Ducha, ku poslušenství a skropení krví Ježíše Krista: Milost vám a pokoj rozmnožen buď.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 3, 'Požehnaný Bůh a Otec Pána našeho Ježíše Krista, kterýž podlé mnohého milosrdenství svého znovu zplodil nás v naději živou skrze vzkříšení Ježíše Krista z mrtvých,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 4, 'K dědictví neporušitelnému a nepoškvrněnému a neuvadlému, kteréž se chová v nebesích, vám,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 5, 'Kteříž mocí Boží ostříháni býváte skrze víru k spasení, kteréž hotovo jest, aby zjeveno bylo v času posledním.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 6, 'V čemžto veselíte se, maličko nyní, (jestliže kdy potřebí jest,) zkormouceni jsouce v rozličných pokušeních,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 7, 'Aby zkušení víry vaší, mnohem dražší nežli zlato, kteréž hyne, a však se v ohni zkušuje, nalezeno bylo vám k chvále, a ke cti i k slávě při zjevení Ježíše Krista.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 8, 'Kteréhož neviděvše, milujete; kteréhož nyní nevidouce, a však v něho věříce, veselíte se radostí nevymluvnou a oslavenou,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 9, 'Docházejíce konce víry své, spasení duší.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 10, 'O kterémž spasení bedlivě přemyšlovali, a je vystihati usilovali proroci, kteříž o té milosti, kteráž se vám státi měla, prorokovali,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 11, 'Vystihajíce to, na který aneb jaký čas mínil by ten, kterýž v nich byl, Duch Kristův, předpovídající o utrpeních Kristových a o veliké za tím slávě.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 12, 'Kterýmžto zjeveno jest, že ne sobě, ale nám tím přisluhovali, což jest vám nyní zvěstováno skrze ty, kteříž vám kázali evangelium, v Duchu svatém seslaném s nebe, na kteréž věci žádostivi jsou andělé patřiti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 13, 'Protož přepášíce bedra mysli své, a střízlivi jsouce, dokonale doufejte v té milosti, kteráž vám dána bude při zjevení Ježíše Krista,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 14, 'Jakožto synové poslušní, nepřirovnávající se prvním neznámosti své žádostem.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 15, 'Ale jakž ten, kterýž vás povolal, svatý jest, i vy svatí ve všem obcování buďte;');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 16, 'Jakož napsáno jest: Svatí buďte, nebo já svatý jsem.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 17, 'A poněvadž Otcem nazýváte toho, kterýž bez přijímání osob soudí vedlé skutků jednoho každého, viztež, abyste v bázni čas svého zde putování konali,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 18, 'Vědouce, že ne porušitelnými věcmi, stříbrem neb zlatem, vykoupeni jste z marného svého obcování toho, od otců vydaného,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 19, 'Ale drahou krví jakožto Beránka nevinného a nepoškvrněného, Krista,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 20, 'Předzvěděného zajisté před ustanovením světa, zjeveného pak v časích posledních pro vás,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 21, 'Kteříž skrze něho věříte v Boha, jenž jej vzkřísil z mrtvých, a dal jemu slávu, aby víra vaše a naděje byla v Bohu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 22, 'Poněvadž duše své očistili jste poslušenstvím pravdy skrze Ducha, k milování neošemetnému bratrstva, z čistého srdce jedni druhé milujte snažně,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 23, 'Znovu zrozeni jsouce ne z porušitelného semene, ale z neporušitelného, skrze živé slovo Boží a zůstávající na věky.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 24, 'Nebo všeliké tělo jest jako tráva, a všeliká sláva člověka jako květ trávy. Usvadla tráva, a květ její spadl.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 25, 'Ale slovo Páně zůstává na věky. Totoť pak jest to slovo, kteréž zvěstováno jest vám.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 1, 'Protož složíce všelikou zlost, a všelikou lest, a pokrytství, a závist, i všecka utrhání,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 2, 'Jakožto nyní zrozená nemluvňátka, mléka beze lsti, Božího slova žádostivi buďte, abyste jím rostli,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 3, 'Jestliže však okusili jste, kterak dobrotivý jest Pán.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 4, 'K kterémuž přistupujíce k kameni živému, od lidí zajisté zavrženému, ale od Boha vyvolenému a drahému,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 5, 'I vy, jako kamení živé, vzdělávejte se v dům duchovní, kněžstvo svaté, k obětování duchovních obětí, vzácných Bohu skrze Jezukrista.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 6, 'A protož praví písmo: Aj, zakládámť na Sionu kámen úhelný, vybraný, drahý, v kterýž kdokoli věří, nikoli nebude zahanben.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 7, 'Vám tedy věřícím jest poctivost, ale nepovolným kámen, kterýž zavrhli stavitelé, tenť jest učiněn v hlavu úhelní, a kámen úrazu, a skála pohoršení,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 8, 'Těm, kteříž se urážejí na slovu, nepovolní jsouce, k čemuž i odloženi jsou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 9, 'Ale vy jste rod vyvolený, královské kněžstvo, národ svatý, lid dobytý, abyste zvěstovali ctnosti toho, kterýž vás povolal ze tmy v předivné světlo své.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 10, 'Kteříž jste někdy ani lidem nebyli, nyní pak jste lid Boží; kteříž jste někdy byli nedošli milosrdenství, nyní pak jste došli milosrdenství.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 11, 'Nejmilejší, prosímť vás, abyste jakožto příchozí a pohostinní zdržovali se od tělesných žádostí, kteréž rytěřují proti duši,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 12, 'Obcování své mezi pohany majíce dobré, aby místo toho, kdež utrhají vám jako zločincům, dobré skutky vaše spatřujíce, velebili Boha v den navštívení.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 13, 'Poddáni tedy buďte všelikému lidskému zřízení pro Pána, buďto králi, jako nejvyššímu,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 14, 'Buďto vládařům, jako od něho poslaným, ku pomstě zle činících, a k chvále dobře činících.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 15, 'Nebo tak jest vůle Boží, abyste dobře činíce, zacpali ústa nemoudrých a neumělých lidí.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 16, 'Buďtež jako svobodní, však ne jako zástěru majíce své zlosti svobodu, ale jakožto služebníci Boží.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 17, 'Všecky ctěte, bratrstvo milujte, Boha se bojte, krále v poctivosti mějte.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 18, 'Služebníci poddáni buďte ve vší bázni pánům, netoliko dobrým a mírným, ale i zlým.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 19, 'Nebo toť jest milé, jestliže kdo pro svědomí Boží snáší zámutky, trpě bez viny.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 20, 'Nebo jaká jest chvála, byste pak i snášeli pohlavkování, hřešíce? Ale jestliže dobře činíce, a bez viny trpíce, snášíte, toť jest milé před Bohem.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 21, 'Nebo i k tomu povoláni jste, jako i Kristus trpěl za nás, nám pozůstaviv příklad, abyste následovali šlepějí jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 22, 'Kterýž hříchu neučinil, aniž jest lest nalezena v ústech jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 23, 'Kterýžto, když mu zlořečili, nezlořečil zase; trpěv, nehrozil, ale poroučel tomu, kterýž spravedlivě soudí.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 24, 'Kterýžto hříchy naše na svém těle sám vnesl na dřevo, abychom hříchům zemrouce, spravedlnosti živi byli, jehož zsinalostí uzdraveni jste.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 25, 'Nebo jste byli jako ovce bloudící, ale nyní obráceni jste ku pastýři a biskupu duší svých.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 1, 'Též podobně i ženy buďte poddané mužům svým, aby, byť pak kteří i nevěřili slovu, skrze pobožné obcování žen bez slova získáni byli,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 2, 'Spatřujíce v bázni svaté vaše obcování,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 3, 'Kterýchžto ozdoba budiž ne ta zevnitřní, v zpletání vlasů, a províjení zlatem, aneb v odívání plášťů,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 4, 'Ale ten skrytý srdce člověk, záležející v neporušitelnosti krotkého a pokojného ducha, kterýž před oblíčejem Božím velmi drahý jest.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 5, 'Tak zajisté někdy i ony svaté ženy, kteréž naději měly v Bohu, ozdobovaly se, poddány byvše mužům svým,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 6, 'Jako Sára poslušna byla Abrahama, pánem jej nazývajíc; jejížto vy jste dcerky, dobře činíce, a nebojíce se žádného přestrašení.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 7, 'Též podobně i muži spolu s nimi bydlíce podlé umění, jakožto mdlejšímu osudí ženskému udělujíce cti, jakožto i spoludědičkám života milosti, aby modlitby vaše neměly překážky.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 8, 'A tak summou, všickni buďte jednomyslní, jedni druhých bíd čitelní, bratrstva milovníci, milosrdní, dobrotiví,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 9, 'Neodplacujíce zlého za zlé, ani zlořečenství za zlořečenství, ale raději dobrořečíce, vědouce, že jste k tomu povoláni, abyste požehnání dědičně obdrželi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 10, 'Nebo kdož chce milovati život, a viděti dny dobré, skrocujž jazyk svůj od zlého, a ústa jeho ať nemluví lsti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 11, 'Uchyl se od zlého, a čiň dobré; hledej pokoje, a stihej jej.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 12, 'Nebo oči Páně na spravedlivé, a uši jeho k prosbám jejich, ale zůřivý oblíčej Páně na ty, kteříž činí zlé věci.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 13, 'A kdo jest, ješto by vám zle učinil, jestliže budete následovníci dobrého?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 14, 'Ale kdybyste pak i trpěli pro spravedlnost, blahoslavení jste. Strachu pak jejich nebojte se, ani se kormuťte,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 15, 'Ale Pána Boha posvěcujte v srdcích svých. Hotovi pak buďte vždycky k vydání počtu všelikému, kdož by od vás požádal zprávy z naděje té, kteráž jest v vás, a to s tichostí a s bázní,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 16, 'Majíce dobré svědomí, aby za to, že utrhají vám jako zločincům, zahanbeni byli ti, kteříž hanějí vaše ctné v Kristu obcování.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 17, 'Lépeť jest zajisté, abyste dobře činíce, líbilo-li by se tak vůli Boží, trpěli, nežli zle činíce.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 18, 'Nebo i Kristus jedinou za hříchy trpěl, spravedlivý za nespravedlivé, aby nás přivedl k Bohu, umrtven jsa z strany těla, ale obživen Duchem.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 19, 'Skrze něhož i těm, kteříž jsou v žaláři, duchům, přišed, kázal,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 20, 'Tehdáž nepovolným, když ono jednou očekávala Boží snášelivost za dnů Noé, když dělán byl koráb, v kterémžto málo, to jest osm duší, zachováno jest u vodě.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 21, 'K čemuž připodobněn jsa nyní křest, i nás spaseny činí, ne to tělesné špiny smytí, ale dobrého svědomí u Boha dotázání, skrze vzkříšení Ježíše Krista.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 22, 'Kterýž všed v nebe, jest na pravici Boží, podmaniv sobě anděly, i mocnosti, i moci.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 1, 'Poněvadž tedy Kristus trpěl za nás na těle, i vy také týmž myšlením odíni buďte, že ten, kdož trpěl na těle, přestal od hříchu,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 2, 'K tomu, aby již nebyl více tělesným žádostem, ale vůli Boží v těle živ, po ten čas, což ho ještě zůstává.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 3, 'Dostiť jest zajisté nám na tom přeběhlém času života, v němž jsme líbosti pohanů páchali, chodivše v nestydatých chlipnostech, v žádostech, v zbytečném pití vína, v hodování, v opilství, a v ohyzdném modlosloužení.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 4, 'A protož když s nimi neběháte k takovému vydávání se v rozpustilost, zdá se jim to cosi nového býti, a rouhají se tomu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 5, 'Tiť vydadí počet tomu, kterýž hotov jest souditi živé i mrtvé.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 6, 'Proto jest zajisté i mrtvým kázáno evangelium, aby souzeni byli podlé lidí z strany těla, ale živi byli podlé Boha duchem.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 7, 'Všemuť se pak přibližuje konec.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 8, 'A protož buďte středmí a bedliví k modlitbám. Přede vším pak lásku jedni k druhým opravdovou mějte; nebo láska přikryje množství hříchů.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 9, 'Buďte vespolek přívětiví k hostem, bez reptání.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 10, 'Jeden každý jakž vzal dar, tak vespolek tím sobě přisluhujte, jako dobří šafáři rozličné milosti Boží.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 11, 'Mluví-li kdo, mluviž jako řeči Boží; jestliže kdo přisluhuje, čiň to jako z moci, kteréž jemu uděluje Bůh, aby ve všem slaven byl Bůh skrze Jezukrista, kterýž má slávu a císařství na věky věků. Amen.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 12, 'Nejmilejší, nebudiž vám divný ten přišlý na vás oheň, pro zkušení vás, jako by se vám něco nového přihodilo.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 13, 'Ale z toho, že jste účastni utrpení Kristových, radujte se, abyste i při zjevení slávy jeho radovali se s veselím.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 14, 'Trpíte-li pohanění pro jméno Kristovo, blahoslavení jste. Nebo Duch ten slávy a Boží na vás odpočívá, kterýž z strany jich zajisté rouhán, ale z strany vaší oslavován bývá.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 15, 'Žádný pak z vás netrp jako vražedlník, neb zloděj, neb zločinec, neb všetečný.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 16, 'Jestliže pak jako křesťan, nestyď se za to, ale oslavuj Boha v té částce.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 17, 'Nebo jest čas, aby se začal soud od domu Božího. A poněvadž nejprv od nás, jakýž bude konec těch, kteříž nejsou povolni evangelium Božímu?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 18, 'A poněvadž spravedlivý sotva k spasení přichází, bezbožný a hříšník kde se ukáže?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 19, 'A protož i ti, kteříž trpí podlé vůle Boží, jakožto věrnému stvořiteli ať poroučejí duše své, dobře činíce.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 1, 'Starších, kteříž mezi vámi jsou, prosím já spolustarší, a svědek Kristových utrpení, a budoucí, kteráž zjevena bude, slávy účastník,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 2, 'Paste stádo Boží, kteréž při vás jest, opatrujíce je, ne bezděky, ale dobrovolně, ne pro mrzký zisk, ale ochotně,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 3, 'Ani jako panujíce nad dědictvím Páně, ale příkladem jsouce stádu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 4, 'A když se ukáže kníže pastýřů, vezmete tu neuvadlou korunu slávy.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 5, 'Podobně mládenci, buďte poddáni starším. A všickni poddanost jedni druhým ukazujte, pokorou vnitř se ozdobte. Bůh zajisté pyšným se protiví, ale pokorným dává milost.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 6, 'Pokořtež se tedy pod mocnou ruku Boží, aby vás povýšil časem svým,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 7, 'Všelikou péči svou uvrhouce na něj. Nebo on má péči o vás.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 8, 'Střízliví buďte, bděte; nebo protivník váš ďábel jako lev řvoucí obchází, hledaje, koho by sežral.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 9, 'Jemuž odpírejte, silní jsouce u víře, vědouce, že tatáž utrpení bratrstvo vaše, kteréž na světě jest, obkličují.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 10, 'Bůh pak všeliké milosti, kterýž povolal nás k věčné slávě své v Kristu Ježíši, když maličko potrpíte, on dokonalé vás učiň, utvrď, zmocni, i upevni,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 11, 'Jemuž sláva a císařství na věky věků. Amen.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 12, 'Po Silvánovi, vám věrném bratru, tak za to mám, že jsem psal krátce, napomínaje a osvědčuje, že tato jest pravá milost Boží, v kteréž stojíte.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 13, 'Pozdravuje vás ta církev, kteráž jest v Babyloně, účastnice vyvolení vašeho, a Marek syn můj.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 14, 'Pozdravtež jedni druhých v políbení laskavém. Pokoj vám všechněm, kteříž jste v Kristu Ježíši. Amen.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 1, 'Šimon Petr, služebník a apoštol Ježíše Krista, těm, kteříž spolu s námi zaroveň drahé dosáhli víry, pro spravedlnost Boha našeho a spasitele Jezukrista:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 2, 'Milost vám a pokoj rozmnožen buď skrze známost Boha a Ježíše Pána našeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 3, 'Jakož nám od jeho Božské moci všecko, což k životu a ku pobožnosti náleželo, darováno jest, skrze známost toho, kterýž povolal nás k slávě a k ctnosti;');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 4, 'Pročež veliká nám a drahá zaslíbení dána jsou, abyste skrze ně Božského přirození účastni učiněni byli, utekše porušení toho, kteréž jest na světě v žádostech.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 5, 'Na to tedy samo všecku snažnost vynaložíce, přičinějte k víře své ctnost, a k ctnosti umění,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 6, 'K umění pak zdrželivost, a k zdrželivosti trpělivost, k trpělivosti pak pobožnost,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 7, 'Ku pobožnosti pak bratrstva milování, a k milování bratrstva lásku.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 8, 'Ty zajisté věci když budou při vás a rozhojní se, ne prázdné, ani neužitečné postaví vás v známosti Pána našeho Jezukrista.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 9, 'Nebo při komž není těchto věcí, slepýť jest, toho, což vzdáleno jest, nevida, zapomenuv se na očištění svých starých hříchů.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 10, 'Protož raději, bratří, snažujte se povolání a vyvolení své upevňovati; nebo to činíce, nepadnete nikdy.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 11, 'Takť zajisté hojné způsobeno vám bude vjití k věčnému království Pána našeho a spasitele Jezukrista.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 12, 'Protož nezanedbámť vždycky vám připomínati těch věcí, ačkoli umělí i utvrzení jste v přítomné pravdě.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 13, 'Neboť to mám za spravedlivé, dokudž jsem v tomto stánku, abych vás probuzoval napomínáním,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 14, 'Věda, že brzké jest složení stánku mého, jakož mi i Pán náš Ježíš Kristus oznámil.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 15, 'Přičinímť se tedy všelijak o to, abyste vy po odchodu mém na ty věci rozpomínati se mohli.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 16, 'Nebo ne nějakých vtipně složených básní následujíce, známu učinili jsme vám Pána našeho Jezukrista moc a příchod, ale jakožto ti, kteříž jsme očima svýma viděli jeho velebnost.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 17, 'Přijalť zajisté od Boha Otce čest a slávu, když se stal k němu hlas takový od velebné slávy: Tentoť jest ten můj milý Syn, v němž mi se zalíbilo.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 18, 'A ten hlas my jsme slyšeli s nebe pošlý, s ním byvše na oné hoře svaté.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 19, 'A mámeť přepevnou řeč prorockou, kteréžto že šetříte jako svíce v temném místě svítící, dobře činíte, až by se den rozednil, a dennice vzešla v srdcích vašich,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 20, 'Toto nejprvé znajíce, že žádného proroctví písma výklad nezáleží na rozumu lidském.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 21, 'Nebo nikdy z lidské vůle nepošlo proroctví, ale Duchem svatým puzeni byvše, mluvili svatí Boží lidé.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 1, 'Bývali pak i falešní proroci v lidu, jakož i mezi vámi budou falešní učitelé, kteříž uvedou sekty zatracení, i toho Pána, kterýž je vykoupil, zapírajíce, uvodíce na sebe rychlé zahynutí.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 2, 'A mnozí následovati budou jejich zahynutí, skrze něž cesta pravdy bude v porouhání dávána.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 3, 'A lakomě skrze vymyšlené řeči vámi kupčiti budou; kterýchž odsouzení již dávno nemešká, a zahynutí jejich nespí.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 4, 'Nebo poněvadžť Bůh andělům, kteříž zhřešili, neodpustil, ale strhna je do žaláře, řetězům mrákoty oddal, aby k odsouzení chováni byli,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 5, 'I prvnímu světu neodpustil, ale sama osmého Noé, kazatele spravedlnosti, zachoval, když potopu na svět bezbožníků uvedl,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 6, 'A města Sodomských a Gomorských v popel obrátiv, podvrácením potupil, příklad budoucím bezbožníkům ukázav,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 7, 'A spravedlivého Lota, těch nešlechetníků prostopašným obcováním ztrápeného, vytrhl;');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 8, 'Ten zajisté spravedlivý, bydliv mezi nimi, den ode dne hleděním i slyšením spravedlivou duši nešlechetnými jejich skutky trápil:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 9, 'Umíť Pán pobožné z pokušení vytrhnouti, nepravých pak ke dni soudu potrestaných dochovati,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 10, 'A zvláště těch, kteříž po těle v žádosti nečisté chodí, a vrchností pohrdají, smělí, sobě se zalibující, neostýchají se důstojnostem porouhati;');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 11, 'Ješto andělé, jsouce větší v síle a v moci nevynášejí proti nim přede Pánem potupného soudu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 12, 'Tito pak jako nerozumná hovada, kteráž za přirozením jdou, zplozená k zjímání a k zahynutí, tomu, čemuž nerozumějí, rouhajíce se, v tom svém porušení zahynou,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 13, 'A odplatu nepravosti ponesou, jakožto ti, kteříž sobě za rozkoš položili, aby se na každý den v líbostech svých kochali, poškvrny a mrzkosti, ti, kteříž s vámi hodujíce, v svých lstech se kochají,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 14, 'Oči majíce plné cizoložstva, a bez přestání hřešící, přeluzujíce duše neustavičné, srdce majíce vycvičené v lakomství, synové zlořečenství.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 15, 'Kteříž opustivše cestu přímou, zbloudili, následujíce cesty Balámovy syna Bozorova, kterýž mzdu nepravosti zamiloval.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 16, 'Ale měl, od koho by pokárán byl pro svůj výstupek. Nebo jhu poddaná oslice němá, člověčím hlasem promluvivši, zbránila nemoudrosti proroka.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 17, 'Tiť jsou studnice bez vody, mlhy vichrem zbouřené, jimžto mrákota tmy schována jest na věčnost.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 18, 'Nebo přepyšně marné věci vypravujíce, žádostmi těla a chlipnostmi loudí ty, kteříž byli v pravdě utekli od těch, jenž bludu obcují,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 19, 'Slibujíce jim svobodu, ješto sami jsou služebníci porušení, poněvadž, od kohož kdo jest přemožen, tomu jest i v službu podroben.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 20, 'Jestliže by pak ti, kteříž ušli poškvrn světa, skrze známost Pána a spasitele Jezukrista, opět zase v to zapleteni jsouce, přemoženi byli, učiněn jest poslední způsob jejich horší nežli první.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 21, 'Lépe by zajisté jim bylo nepoznávati cesty spravedlnosti, nežli po nabytí známosti odvrátiti se od vydaného jim svatého přikázaní.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 22, 'Ale přihodilo se jim to, což se v přísloví pravém říkává: Pes navrátil se k vývratku svému, a svině umytá do kaliště bláta.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 1, 'Nejmilejší, již toto druhý list vám píši, jimižto vzbuzuji skrze napomínání vaši upřímou mysl,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 2, 'Abyste pamatovali na slova předpověděná od svatých proroků, a na přikázaní vydané od nás apoštolů Pána a spasitele,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 3, 'Toto nejprvé vědouce, žeť přijdou v posledních dnech posměvači, podlé svých vlastních žádostí chodící,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 4, 'A říkající: Kdež jest to zaslibování o příchodu jeho? Nebo jakž otcové zesnuli, všecko tak trvá od počátku stvoření.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 5, 'Tohoť zajisté z úmysla věděti nechtí, že nebesa již dávno slovem Božím byla učiněna, i země z vody a na vodě upevněna.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 6, 'Pročež onen první svět vodou jsa zatopen, zahynul.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 7, 'Ta pak nebesa, kteráž nyní jsou, i země, týmž slovem odložená, chovají se k ohni, ke dni soudu a zatracení bezbožných lidí.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 8, 'Ale tato jedna věc nebuď před vámi skryta, nejmilejší, že jeden den u Pána jest jako tisíc let, a tisíc let jako jeden den.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 9, 'Nemeškáť Pán s naplněním slibů, (jakož někteří za to mají, že obmeškává,) ale shovívá nám, nechtě, aby kteří zahynuli, ale všickni ku pokání se obrátili.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 10, 'Přijdeť pak ten den Páně, jako zloděj v noci, v kterémž nebesa jako v prudkosti vichru pominou, a živlové pálivostí ohně rozplynou se, země pak i ty věci, kteréž jsou na ní, vypáleny budou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 11, 'Poněvadž tedy to všecko má se rozplynouti, jací pak vy býti máte v svatých obcováních a v pobožnostech,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 12, 'Očekávajíce a chvátajíce ku příští dne Božího, v němžto nebesa, hoříce, rozpustí se, a živlové pálivostí ohně rozplynou se?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 13, 'Nového pak nebe a nové země podlé zaslíbení jeho čekáme, v kterýchž spravedlnost přebývá.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 14, 'Protož, nejmilejší, takových věcí čekajíce, snažtež se, abyste bez poškvrny a bez úhony před ním nalezeni byli v pokoji.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 15, 'A Pána našeho dlouhočekání za spasení mějte, jakž i milý bratr náš Pavel, podlé sobě dané moudrosti, psal vám,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 16, 'Jako i ve všech epištolách svých, mluvě v nich o těch věcech. Mezi nimiž některé jsou nesnadné k vyrozumění, kterýchžto neučení a neutvrzení natahují, jako i jiných písem, k svému vlastnímu zatracení.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 17, 'Vy tedy, nejmilejší, to prvé vědouce, střeztež se, abyste bludem těch nešlechetných nebyli pojati, a nevypadli od své pevnosti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 18, 'Ale rozmáhejte se v milosti a v známosti Pána našeho a spasitele Jezukrista, jemuž sláva i nyní i na časy věčné. Amen.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 1, 1, 'Což bylo od počátku, což jsme slýchali, co jsme očima svýma viděli, a co jsme pilně spatřili, a čeho se ruce naše dotýkaly, o slovu života,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 1, 2, '(Nebo ten život zjeven jest, a my jsme viděli, a svědčíme, i zvěstujeme vám ten život věčný, kterýž byl u Otce, a zjeven jest nám,)');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 1, 3, 'Což jsme viděli a slyšeli, zvěstujeme vám, abyste i vy s námi obecenství měli, a obecenství naše aby bylo s Otcem i s Synem jeho Jezukristem.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 1, 4, 'A totoť píšeme vám, aby radost vaše byla plná.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 1, 5, 'Toť jest tedy zvěstování to, kteréž jsme slýchali od něho, a zvěstujeme vám: Že Bůh jest světlo, a tmy v něm nižádné není.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 1, 6, 'Díme-li, že s ním obecenství máme, a ve tmě chodíme, lžeme, a nečiníme pravdy.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 1, 7, 'Pakliť chodíme v světle, jako on jest v světle, obecenství máme vespolek, a krev Krista Ježíše Syna jeho očišťuje nás od všelikého hříchu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 1, 8, 'Pakliť díme, že hříchu nemáme, sami se svodíme, a pravdy v nás není.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 1, 9, 'Jestliže pak budeme vyznávati hříchy své, věrnýť jest Bůh a spravedlivý, aby nám odpustil hříchy, a očistil nás od všeliké nepravosti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 1, 10, 'Díme-li, že jsme nehřešili, činíme jej lhářem, a neníť v nás slova jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 1, 'Synáčkové moji, totoť vám píši, abyste nehřešili. Pakliť by kdo zhřešil, přímluvci máme u Otce, Ježíše Krista spravedlivého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 2, 'A onť jest obět slitování za hříchy naše, a netoliko za naše, ale i za všeho světa.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 3, 'A po tomť známe, že jsme jej poznali, jestliže přikázaní jeho ostříháme.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 4, 'Dí-liť kdo: Znám jej, a přikázaní jeho neostříhá, lhářť jest, a pravdy v něm není.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 5, 'Ale kdožť ostříhá slova jeho, v pravděť láska Boží v tom jest dokonalá. Po tomť známe, že jsme v něm.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 6, 'Kdo praví, že v něm zůstává, tenť má, jakž on chodil, tak choditi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 7, 'Bratří, ne nové přikázaní píši vám, ale přikázaní staré, kteréž jste měli od počátku. A to přikázaní staré jestiť slovo to, kteréž jste slyšeli od počátku.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 8, 'A zase přikázaní nové píši vám, kteréž jest pravé i v něm i v vás. Nebo tma pomíjí, a světlo to pravé již svítí.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 9, 'Kdo praví, že jest v světle, a bratra svého nenávidí, v temnostiť jest až posavad.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 10, 'Kdož miluje bratra svého, v světle zůstává, a pohoršení v něm není.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 11, 'Ale kdož nenávidí bratra svého, v temnosti jest, a v temnosti chodí, a neví, kam jde; nebo temnost oslepila oči jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 12, 'Píši vám, synáčkové, žeť jsou vám odpuštěni hříchové pro jméno jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 13, 'Píši vám, otcové, že jste poznali toho, kterýž jest od počátku. Píši vám, mládenci, že jste svítězili nad tím zlostníkem.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 14, 'Píši vám, dítky, že jste poznali Otce. Psal jsem vám, otcové, že jste poznali toho, kterýž jest od počátku. Psal jsem vám, mládenci, že silní jste, a slovo Boží v vás zůstává, a že jste svítězili nad tím zlostníkem.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 15, 'Nemilujtež světa, ani těch věcí, kteréž na světě jsou. Miluje-liť kdo svět, neníť lásky Otcovy v něm.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 16, 'Nebo všecko, což jest na světě, jako žádost těla, a žádost očí, a pýcha života, toť není z Otce, ale jest z světa.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 17, 'Svět pak hyne i žádost jeho, ale kdož činí vůli Boží, tenť trvá na věky.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 18, 'Dítky, poslední hodina jest, a jakož jste slýchali, že antikrist přijíti má, i nyníť antikristové mnozí povstali. Odkudž známe, že poslední hodina jest.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 19, 'Z násť vyšli, ale nebyli z nás. Nebo byť byli z nás, byliť by zůstali s námi, ale vyšli z nás, aby zjeveni byli, že nejsou všickni z nás.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 20, 'Vy pak máte pomazání od Svatého, a znáte všecko.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 21, 'Nepsal jsem vám, proto že byste neznali pravdy, ale že ji znáte, a že všeliká lež není z pravdy.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 22, 'A kdo jest lhář? Není-li ten, kdož zapírá, že by Ježíš nebyl Kristus? Tenť jest antikrist, kdož zapírá Otce i Syna.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 23, 'Každý kdož zapírá Syna, nemáť ani Otce.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 24, 'A protož zůstaniž v vás to, což jste slýchali od počátku. Zůstane-liť v vás to, co jste slýchali od počátku, i vy také v Synu i v Otci zůstanete.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 25, 'A toť jest to zaslíbení, kteréž on nám zaslíbil, totiž ten život věčný.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 26, 'Tyto věci psal jsem vám o těch, kteříž vás svodí.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 27, 'Ale pomazání to, kteréž jste vzali od něho, v vás zůstává, aniž potřebujete, aby kdo učil vás, ale jakž pomazání to učí vás o všech věcech, a pravéť jest a neoklamavatelné, a jakž naučilo vás, tak v něm zůstávejte.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 28, 'A nyní, synáčkové, zůstávejtež v něm, abychom, když by se ukázal, smělé doufání měli, a nebyli zahanbeni od něho v příchodu jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 29, 'Poněvadž víte, že on spravedlivý jest, znejtež také, že každý, kdož činí spravedlnost, z něho jest narozen.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 1, 'Pohleďte, jakou lásku dal nám Otec, totiž abychom synové Boží slouli. Protoť svět nezná nás, že jeho nezná.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 2, 'Nejmilejší, nyní synové Boží jsme, ale ještěť se neokázalo, co budeme. Vímeť pak, že když se okáže, podobni jemu budeme; nebo viděti jej budeme tak, jakž jest.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 3, 'A každý, kdož má takovou naději v něm, očišťuje se, jakož i on čistý jest.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 4, 'Každý, kdož činí hřích, činíť proti zákonu; nebo hřích jest přestoupení zákona.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 5, 'A víte, že on se okázal, aby hříchy naše sňal, a hříchu v něm není.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 6, 'Každý tedy, kdož v něm zůstává, nehřeší; ale každý, kdož hřeší, neviděl ho, aniž ho poznal.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 7, 'Synáčkové, nižádný vás nesvoď. Kdož činí spravedlnost, spravedlivý jest, jakož i on jest spravedlivý.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 8, 'Kdož činí hřích, z ďábla jest; nebo ďábel od počátku hřeší. Na toť jest zjeven Syn Boží, aby kazil skutky ďáblovy.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 9, 'Každý, kdož se narodil z Boha, hříchu nečiní; nebo símě jeho v něm zůstává, aniž může hřešiti, nebo z Boha narozen jest.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 10, 'Po tomtoť zjevní jsou synové Boží a synové ďáblovi. Každý, kdož nečiní spravedlnosti, neníť z Boha, a kdož nemiluje bratra svého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 11, 'Nebo toť jest to zvěstování, kteréž jste slýchali od počátku, abychom milovali jedni druhé.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 12, 'Ne jako Kain, kterýž z toho zlostníka byl, a zamordoval bratra svého. A pro kterou příčinu zamordoval ho? Proto že skutkové jeho byli zlí, bratra pak jeho spravedliví.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 13, 'Nedivtež se, bratří moji, jestliže vás svět nenávidí.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 14, 'My víme, že jsme přeneseni z smrti do života, nebo milujeme bratří. Kdož nemiluje bratra, zůstáváť v smrti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 15, 'Každý, kdož nenávidí bratra svého, vražedlník jest, a víte, že žádný vražedlník nemá života věčného v sobě zůstávajícího.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 16, 'Po tomto jsme poznali lásku, že on duši svou za nás položil, i myť tedy máme za bratří duše klásti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 17, 'Kdo by pak měl statek tohoto světa, a viděl by bratra svého, an nouzi trpí, a zavřel by střeva svá před ním, kterak láska Boží zůstává v něm?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 18, 'Synáčkové moji, nemilujmež slovem, ani jazykem, ale skutkem a pravdou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 19, 'A po tomť poznáváme, že z pravdy jsme, a před oblíčejem jeho spokojíme srdce svá.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 20, 'Nebo potupovalo-liť by nás srdce naše, ovšemť Bůh, kterýž jest větší nežli srdce naše, a zná všecko.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 21, 'Nejmilejší, jestližeť by nás srdce naše nepotupovalo, smělou doufanlivost máme k Bohu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 22, 'A zač bychom ho koli prosili, béřeme od něho; nebo přikázaní jeho ostříháme, a to, což jest libého před oblíčejem jeho, číníme.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 23, 'A totoť jest to přikázaní jeho, abychom věřili jménu Syna jeho Jezukrista, a milovali jedni druhé, jakož nám vydal přikázaní.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 24, 'Nebo kdož ostříhá přikázaní jeho, v němť zůstává, a on také v něm. A po tomť poznáváme, že zůstává v nás, totiž po Duchu, kteréhož dal nám.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 1, 'Nejmilejší, ne každému duchu věřte, ale zkušujte duchů, jsou-li z Boha; nebo mnozí falešní proroci vyšli na svět.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 2, 'Po tomto znejte Ducha Božího: Všeliký duch, kterýž vyznává Jezukrista v těle přišlého, z Boha jest.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 3, 'Ale všeliký duch, kterýž nevyznává Jezukrista v těle přišlého, není z Boha; nýbrž toť jest ten duch antikristův, o kterémž jste slýchali, že přijíti má, a jižť jest nyní na světě.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 4, 'Vy z Boha jste, synáčkové, a svítězili jste nad nimi; nebo většíť jest ten, kterýž v vás, nežli ten, kterýž jest v světě.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 5, 'Oni z světa jsou, a protož o světu mluví, a svět jich poslouchá.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 6, 'My z Boha jsme. Kdo zná Boha, posloucháť nás; kdož není z Boha, neposloucháť nás. A po tomť poznáváme ducha pravdy a ducha bludu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 7, 'Nejmilejší, milujmež jedni druhé; nebo láska z Boha jest, a každý, kdož miluje, z Boha se narodil, a znáť Boha.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 8, 'Kdož nemiluje, nezná Boha; nebo Bůh láska jest.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 9, 'V tomť zjevena jest láska Boží k nám, že Syna svého toho jednorozeného poslal Bůh na svět, abychom živi byli skrze něho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 10, 'V tomť jest láska, ne že bychom my Boha milovali, ale že on miloval nás, a poslal Syna svého obět slitování za hříchy naše.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 11, 'Nejmilejší, poněvadž tak miloval nás Bůh, i myť máme jedni druhé milovati.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 12, 'Boha žádný nikdy nespatřil, ale milujeme-liť jedni druhé, Bůh v nás přebývá, a láska jeho dokonalá jest v nás.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 13, 'Po tomtoť poznáváme, že v něm přebýváme, a on v nás, že z Ducha svého dal nám.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 14, 'A myť jsme viděli, a svědčíme, že Otec poslal Syna spasitele světa.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 15, 'Kdož by koli vyznával, že Ježíš jest Syn Boží, Bůh v něm přebývá, a on v Bohu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 16, 'A myť jsme poznali, a uvěřili o lásce, kterouž Bůh má k nám. Bůh láska jest, a kdož v lásce přebývá, v Bohu přebývá, a Bůh v něm.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 17, 'V tomtoť jest k dokonání svému přišla láska Boží s námi, abychom bezpečné doufání měli v den soudný, kdyžto, jakýž jest on, takoví i my jsme na tomto světě.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 18, 'Bázněť není v lásce, ale láska dokonalá ven vyhání bázeň; nebo bázeň trápení má, kdož se pak bojí, není dokonalý v lásce.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 19, 'My milujeme jej, nebo on prvé miloval nás.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 20, 'Řekl-li by kdo: Miluji Boha, a bratra svého nenáviděl by, lhář jest. Nebo kdož nemiluje bratra svého, kteréhož viděl, Boha, kteréhož neviděl, kterak může milovati?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 21, 'A totoť přikázaní máme od něho, aby ten, kdož miluje Boha, miloval i bratra svého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 1, 'Každý, kdož věří, že Ježíš jest Kristus, z Boha se narodil; a každý, kdož miluje toho, kterýž zplodil, milujeť i toho, kterýž zplozen jest z něho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 2, 'Po tomť poznáváme, že milujeme syny Boží, když Boha milujeme, a přikázaní jeho ostříháme.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 3, 'Nebo toť je láska Boží, abychom přikázaní jeho ostříhali; a přikázaní jeho nejsou těžká.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 4, 'Všecko zajisté, což se narodilo z Boha, přemáhá svět; a toť jest to vítězství, kteréž přemáhá svět, víra naše.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 5, 'Kdo jest, ješto přemáhá svět, jediné, kdož věří, že Ježíš jest Syn Boží?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 6, 'Toť jest ten, kterýž přišel skrze vodu a krev, Ježíš Kristus, ne u vodě toliko, ale u vodě a ve krvi. A Duch jest, kterýž svědectví vydává, že Duch jest pravda.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 7, 'Nebo tři jsou, kteříž svědectví vydávají na nebi: Otec, Slovo, a Duch svatý, a ti tři jedno jsou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 8, 'A tři jsou, kteříž svědectví vydávají na zemi: Duch, a voda, a krev, a ti tři jedno jsou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 9, 'Poněvadž svědectví lidské přijímáme, svědectvíť Boží větší jest. Nebo totoť svědectví jest Boží, kteréž vysvědčil o Synu svém.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 10, 'Kdož věří v Syna Božího, máť svědectví sám v sobě. Kdož nevěří Bohu, lhářem jej učinil; nebo neuvěřil tomu svědectví, kteréž vysvědčil Bůh o Synu svém.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 11, 'A totoť jest svědectví to, že život věčný dal nám Bůh, a ten život v Synu jeho jest.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 12, 'Kdožť má Syna, máť život; kdož nemá Syna Božího, života nemá.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 13, 'Tyto věci psal jsem vám věřícím ve jménu Syna Božího, abyste věděli, že máte věčný život, a abyste věřili ve jméno Syna Božího.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 14, 'A totoť jest to smělé doufání, kteréž máme k němu, že zač bychom koli prosili podlé vůle jeho, slyší nás.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 15, 'Že pak víme, že nás slyší, prosili-li bychom zač, podlé toho víme, že máme prosby naplněné, kteréž jsme předkládali jemu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 16, 'Viděl-li by kdo bratra svého hřešícího hříchem ne k smrti, modliž se za něj, a dá jemu Bůh život, totiž hřešícím ne k smrti. Jestiť hřích k smrti; ne za ten, pravím, aby se modlil.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 17, 'Každá nepravost jestiť hřích, ale jestiť hřích ne k smrti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 18, 'Víme, že každý, kdož se narodil z Boha, nehřeší; ale ten, kdož narozen jest z Boha, ostříhá sebe samého, a ten zlostník se ho nedotýká.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 19, 'Víme, že z Boha jsme, ale svět všecken ve zlém leží.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 20, 'A vímeť, že Syn Boží přišel a dal nám smysl, abychom poznali toho pravého, a jsmeť v tom pravém, i v Synu jeho Ježíši Kristu. Onť jest ten pravý Bůh a život věčný.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 21, 'Synáčkové, vystříhejte se modl. Amen.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 1, 'Starší v Kristu vyvolené paní i synům jejím, kteréž já miluji v pravdě, a ne sám já, ale i všickni, kteříž poznali pravdu,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 2, 'Pro pravdu, kteráž zůstává v nás, a s námiť bude na věky:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 3, 'Budiž s vámi milost, milosrdenství, a pokoj od Boha Otce, i od Pána Jezukrista, Syna Otcova, v pravdě a v lásce.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 4, 'Zradoval jsem se velmi, že jsem nalezl některé z synů tvých, an chodí v pravdě, jakož jsme přikázaní vzali od Otce.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 5, 'A nyní prosím tebe, paní, ne jako nové přikázaní předkládaje tobě, ale to, kteréž jsme měli od počátku, abychom milovali jedni druhé.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 6, 'A totoť jest ta láska, abychom chodili podlé přikázaní jeho. Přikázaní pak toto jest, jakž jste slýchali od počátku, abyste v něm chodili.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 7, 'Nebo mnozí bludaři vyšli na svět, kteříž nevyznávají Jezukrista přišlého v těle. Takový každý jest bludař a antikrist.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 8, 'Hleďtež sebe, abychom neztratili toho, o čemž jsme pracovali, ale odplatu plnou abychom vzali.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 9, 'Každý, kdož přestupuje, a nezůstává v učení Kristovu, nemá Boha; kdož zůstává v učení Kristovu, tenť i Otce i Syna má.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 10, 'Přichází-li kdo k vám, a tohoto učení nepřináší, nepřijímejte ho do domu, aniž ho pozdravujte.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 11, 'Nebo kdož takového pozdravuje, obcuje skutkům jeho zlým.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 12, 'Mnoho vám psáti měv, nechtěl jsem se svěřiti černidlu a papíru, ale mámť naději, že k vám přijdu, a ústy k ústům mluviti budu, aby radost naše plná byla.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 13, 'Pozdravují tě synové sestry tvé v Pánu vyvolené. Amen.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 1, 'Starší Gáiovi milému, kteréhož já miluji v pravdě.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 2, 'Nejmilejší, žádámť obzvláštně, abys se dobře měl, a zdráv byl, tak jako duše tvá dobře se má.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 3, 'Zradovalť jsem se zajisté velice, když přišli bratří, a svědectví vydávali o tvé upřímnosti, kterak ty v upřímnosti chodíš.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 4, 'Nemámť větší radosti, než abych slyšel, že synové moji chodí v upřímnosti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 5, 'Nejmilejší, věrně děláš, cožkoli činíš bratřím a hostem,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 6, 'Kteříž svědectví vydali o lásce tvé před církví. Kteréžto vyprovodíš-li, tak jakž sluší na Boha, dobře učiníš.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 7, 'Neboť pro jméno jeho vyšli, a nic nevzali od pohanů.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 8, 'Mámeť tedy my takové přijímati, abychom byli pomocníci pravdy.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 9, 'Psal jsem zboru vašemu, ale Diotrefes, kterýž stojí o prvotnost mezi nimi, nepřijímá nás.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 10, 'Protož přijdu-li tam, připomenuť skutky jeho, kteréž činí, mluvě proti nám zlé řeči. A nemaje dosti na tom, i sám bratří nepřijímá, i těm, kteříž by chtěli, nedopouští, a ze zboru je vylučuje.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 11, 'Nejmilejší, nenásledujž zlého, ale dobrého. Kdož dobře činí, z Boha jest; ale kdož zle činí, nevidí Boha.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 12, 'Demetriovi svědectví vydáno jest ode všech, i od samé pravdy; ano i my svědectví o něm vydáváme, a víte, že svědectví naše pravé jest.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 13, 'Mnohoť jsem měl psáti, ale nechciť psáti černidlem a pérem.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 14, 'Nebo mám naději, že tě tudíž uzřím, a ústy k ústům mluviti budeme. Pokoj tobě. Pozdravují tě přátelé. Pozdraviž i ty přátel ze jména.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 1, 'Judas, Ježíše Krista služebník, bratr pak Jakubův, posvěceným od Boha Otce, a Kristu Ježíši zachovaným i povolaným:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 2, 'Milosrdenství vám a pokoj i láska budiž rozmnožena.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 3, 'Nejmilejší, všecku snažnost vynakládaje na to, abych vám psal o obecném spasení, musil jsem psáti, vás napomínaje, abyste statečně bojovali o víru, kteráž jest jednou dána svatým.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 4, 'Neboť podešli někteří lidé bezbožní, prvé již dávno poznamenaní k tomu potupení, kteříž milost Boha našeho přenášejí v chlipnost, a toho, kterýž jest sám Hospodin, Boha a Pána našeho Jezukrista zapírají.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 5, 'Protož vidělo mi se vám to připomenouti, kteříž jednou již o tom víte, že když Pán lid z země Egyptské vysvobodil, potom ty, kteříž nevěřící byli, zatratil.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 6, 'A ty anděly, kteříž neostříhali svého knížetství, ale opustili příbytek svůj, k soudu velikého toho dne vazbou věčnou pod mrákotou schoval.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 7, 'Jako Sodoma a Gomora, a okolní města, když podobným způsobem, jako i tito, v smilstvo se vydali, a odešli po těle cizím, předložena jsou za příklad, pokutu věčného ohně snášejíce.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 8, 'Takéž podobně i tito, jako v hluboký sen pohřižení, tělo zajisté poškvrňují, panstvím pak pohrdají, a důstojnosti se rouhají;');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 9, 'Ješto Michal archanděl, když s ďáblem odpor maje, hádal se o tělo Mojžíšovo, nesměl vynésti soudu zlořečení, ale řekl: Ztresciž tě Pán.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 10, 'Tito pak, čehož neznají, tomu se rouhají; a což od přirození znají, jako nerozumná hovada, v tom se poškvrňují.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 11, 'Běda jim, nebo cestou Kainovou odešli, a poblouzením Balámovy mzdy se vylili, a odporováním Chóre zahynuli.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 12, 'Tiť jsou na hodech vašich poškvrny, kteříž s vámi hodujíce bezstoudně, sami se pasou; jsou oblakové bez vody, jimiž vítr sem i tam točí, stromové uvadlí, neužiteční, dvakrát mrtví a vykořenění,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 13, 'Vzteklé vody mořské, vymítající své hanebnosti, hvězdy bludné, jimžto mrákota tmy zachována jest na věčnost.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 14, 'Prorokoval pak také o nich sedmý od Adama Enoch, řka: Aj, Pán se béře s svatými tisíci svými,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 15, 'Aby učinil soud všechněm, a trestal všecky, kteříž by koli mezi nimi byli bezbožní, ze všech skutků bezbožnosti jejich, v nichž bezbožnost páchali, i ze všech tvrdých řečí, kteréž mluvili proti němu hříšníci bezbožní.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 16, 'Tiť jsou reptáci, stýskaví, podlé žádostí svých chodíce, jejichž ústa mluví pýchu, pochlebujíce osobám pro svůj užitek.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 17, 'Ale vy, nejmilejší, pamatujte na slova předpověděná od apoštolů Pána našeho Jezukrista.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 18, 'Neboť pověděli vám, že v posledním času budou posměvači, podlé svých bezbožných žádostí chodící.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 19, 'Toť jsou ti, kteříž se sami odtrhují, hovadní, Ducha Kristova nemající.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 20, 'Ale vy, nejmilejší, vzdělávajíce se na té nejsvětější víře své, v Duchu svatém modléce se,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 21, 'Ostříhejte se v lásce Boží, očekávajíce milosrdenství Pána našeho Jezukrista k věčnému životu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 22, 'A nad některými zajisté lítost mějte, rozeznání v tom majíce.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 23, 'Jiné pak strašením k spasení přivozujte, z ohně je vychvacujíce, v nenávisti majíce i tu skrze tělo poškvrněnou sukni.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 24, 'Tomu pak, kterýž mocen jest, zachovati vás bez úrazu, a postaviti před oblíčejem slávy své bez úhony s veselím,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 25, 'Samému moudrému Bohu, spasiteli našemu, budiž sláva a velebnost, císařství i moc, i nyní i po všecky věky. Amen.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 1, 'Zjevení Ježíše Krista, kteréž dal jemu Bůh, aby ukázal služebníkům svým, které věci měly by se díti brzo, on pak zjevil, poslav je skrze anděla svého služebníku svému Janovi,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 2, 'Kterýž osvědčil slovo Boží, a svědectví Jezukristovo, a cožkoli viděl.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 3, 'Blahoslavený, kdož čte, i ti, kteříž slyší slova proroctví tohoto, a ostříhají toho, což napsáno jest v něm; nebo čas blízko jest.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 4, 'Jan sedmi zborům, kteříž jsou v Azii: Milost vám a pokoj od toho, kterýž jest, a kterýž byl, a kterýž přijíti má, a od sedmi duchů, kteříž jsou před oblíčejem trůnu jeho,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 5, 'A od Ježíše Krista, jenž jest svědek věrný, ten prvorozený z mrtvých, a kníže králů země, kterýž zamiloval nás, a umyl nás od hříchů našich krví svou,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 6, 'A učinil nás krále a kněží Bohu a Otci svému, jemuž buď sláva a moc na věky věků. Amen.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 7, 'Aj, béře se s oblaky, a uzříť jej všeliké oko, i ti, kteříž ho bodli; a budou plakati pro něj všecka pokolení země, jistě. Amen.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 8, 'Jáť jsem Alfa i Oméga, totiž počátek i konec, praví Pán, kterýž jest, a kterýž byl, a kterýž přijíti má, ten všemohoucí.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 9, 'Já Jan, i bratr váš, i spoluúčastník v ssoužení, i v království, i v trpělivosti Ježíše Krista, byl jsem na ostrově, kterýž slove Patmos, pro slovo Boží a pro svědectví Ježíše Krista.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 10, 'A byl jsem u vytržení ducha v den Páně, i uslyšel jsem za sebou hlas veliký jako trouby,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 11, 'An dí: Já jsem Alfa i Oméga, ten první i poslední, a což vidíš, piš do knihy, a pošli sedmi zborům, kteříž jsou v Azii, do Efezu, a do Smyrny, a do Pergamu, a do Tyatiru, a do Sardy, a do Filadelfie, i do Laodicie.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 12, 'I obrátil jsem se, abych viděl ten hlas, kterýž mluvil se mnou, a obrátiv se, uzřel jsem sedm svícnů zlatých,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 13, 'A u prostřed těch sedmi svícnů podobného Synu člověka, oblečeného v dlouhé roucho, a přepásaného na prsech pasem zlatým.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 14, 'Hlava pak jeho a vlasové bílí, jako bílá vlna, jako sníh, a oči jeho jako plamen ohně.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 15, 'Nohy pak jeho podobné mosazi, jako v peci hořící; a hlas jeho jako hlas vod mnohých.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 16, 'A měl v pravé ruce své sedm hvězd, a z úst jeho meč s obou stran ostrý vycházel; a tvář jeho jako slunce, když jasně svítí.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 17, 'A jakž jsem jej uzřel, padl jsem k nohám jeho, jako mrtvý. I položil ruku svou pravou na mne, řka ke mně: Neboj se. Já jsem ten první i poslední,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 18, 'A živý, ješto jsem byl mrtvý, a aj, živý jsem na věky věků. Amen. A mám klíče pekla i smrti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 19, 'Napiš ty věci, kteréž jsi viděl, a kteréž jsou, a kteréž se mají díti potom.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 20, 'Tajemství těch sedmi hvězd, kteréž jsi viděl v pravici mé, a sedm svícnů zlatých: Sedm těch hvězd jsou andělé sedmi zborů, a sedm svícnů, kteréžs viděl, jest sedm zborů.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 1, 'Andělu Efezské církve piš: Totoť praví ten, kterýž drží těch sedm hvězd v pravici své, kterýž se prochází u prostřed těch sedmi svícnů zlatých:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 2, 'Známť skutky tvé, a práci tvou, i trpělivost tvou, a že nemůžeš trpěti zlých; a zkusil jsi těch, kteříž se praví býti apoštolé, ale nejsou, a shledals je, že jsou lháři.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 3, 'A snášel jsi, a trpělivost máš, a pro jméno mé pracovals a neustal.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 4, 'Ale mámť proti tobě to, že jsi tu první lásku svou opustil.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 5, 'Protož pomni, odkud jsi vypadl, a čiň pokání, a první skutky. Pakliť toho nebude, přijdu na tebe rychle, a pohnuť svícnem tvým z místa jeho, nebudeš-li pokání činiti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 6, 'Ale toto máš, že nenávidíš skutků Mikulášenců, kterýchž i já nenávidím.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 7, 'Kdo má uši, slyš, co Duch praví církvím: Tomu, kdož svítězí, dám jísti z dřeva života, kteréž jest u prostřed ráje Božího.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 8, 'Andělu pak Smyrnenské církve piš: Toto praví ten první i poslední, kterýž byl mrtvý, a ožil:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 9, 'Vím o skutcích tvých, i o ssoužení, a chudobě, (ale bohatý jsi,) i o rouhání těch, kteříž se praví býti Židé, a nejsou, ale zběř satanova.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 10, 'Nebojž se nic toho, co trpěti máš. Aj, uvržeť ďábel některé z vás do vězení, abyste zkušeni byli, a budete míti úzkost za deset dní. Budiž věrný až do smrti, a dámť korunu života.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 11, 'Kdo má uši, slyš, co Duch praví církvím: Kdo svítězí, nebude uražen od smrti druhé.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 12, 'Andělu pak Pergamenské církve piš: Totoť praví ten, kterýž má ten meč s obou stran ostrý:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 13, 'Vím skutky tvé, i kde bydlíš, totiž tu, kdež jest stolice satanova, a že držíš se jména mého, a nezapřel jsi víry mé, ani v těch dnech, když Antipas, svědek můj věrný, zamordován jest u vás, tu, kdež bydlí satan.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 14, 'Ale mámť málo proti tobě, že tam máš ty, kteříž drží učení Balámovo, kterýž učil Baláka pohoršení klásti před oblíčejem synů Izraelských, aby jedli modlám obětované, a smilnili.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 15, 'Tak i ty máš ty, kteříž drží učení Mikulášenců, což já v nenávisti mám.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 16, 'Činiž pokání. Pakli nebudeš, přijdu na tebe brzy, a bojovati budu s nimi mečem úst svých.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 17, 'Kdo má uši, slyš, co Duch praví církvím: Tomu, kdož vítězí, dám jísti tu mannu skrytou, a dám jemu kamének bílý, a na tom kaménku jméno nové napsané, kteréhož žádný neví, než ten, kdož je přijímá.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 18, 'Andělu pak Tyatirské církve piš: Totoť praví Syn Boží, kterýž má oči jako plamen ohně, a jehož nohy podobné jsou mosazi:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 19, 'Známť skutky tvé, i lásku, i přisluhování, i věrnost, i trpělivost tvou, a skutky tvé, i ty poslední větší nežli první.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 20, 'Ale mámť málo proti tobě, že necháváš ženy Jezábel, kteráž se býti praví prorokyní, aby učila a svozovala služebníky mé, aby smilnili, a jedli modlám obětované.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 21, 'Ale dalť jsem jí čas, aby pokání činila z smilstva svého, a však nečinila.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 22, 'Aj, já uvrhu ji na lože, i ty, kteříž cizoloží s ní, v ssoužení převeliké, jestliže nebudou činiti pokání z skutků svých.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 23, 'A syny její zmorduji smrtí; i zvědíť všecky církve, žeť jsem já zpytatel ledví i srdce, a odplatím vám jednomu každému podlé skutků vašich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 24, 'Vámť pak pravím i jiným Tyatirským, kteřížkoli nemají učení tohoto, a kteříž nepoznali hlubokosti satanovy, jakž říkají: Nevzložímť na vás jiného břemene.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 25, 'A však to, což máte, držte, dokudž nepřijdu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 26, 'Kdož by pak vítězil, a ostříhal až do konce skutků mých, dám jemu moc nad pohany.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 27, 'I budeť je spravovati prutem železným, a jako nádoba hrnčířova střískáni budou, jakž i já vzal jsem od Otce svého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 28, 'A dám jemu hvězdu jitřní.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 29, 'Kdo má uši, slyš, co Duch praví církvím.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 1, 'Andělu pak církve Sardinské piš: Toto praví ten, kterýž má sedm duchů Božích a sedm těch hvězd: Vím skutky tvé, že máš jméno, že jsi živ, ale jsi mrtvý.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 2, 'Budiž bedlivý, a utvrzujž jiné umírající. Neboť jsem nenalezl skutků tvých plných před Bohem.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 3, 'Pomniž tedy, co jsi přijal a slyšel, a ostříhej, a čiň pokání. Pakli bdíti nebudeš, přijduť na tě jako zloděj, a nezvíš, v kterou hodinu na tě přijdu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 4, 'Ale máš některé osoby i v Sardis, kteréž nepoškvrnily roucha svého, protož budouť se se mnou procházeti v bílém rouše; nebo jsou hodni.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 5, 'Kdo svítězí, tenť bude odín rouchem bílým; a nikoliť nevymaži jména jeho z knihy života, ale vyznámť jméno jeho před oblíčejem Otce svého i před anděly jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 6, 'Kdo má uši, slyš, co Duch praví církvím.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 7, 'Andělu pak Filadelfitské církve piš: Totoť praví ten svatý a pravý, kterýž má klíč Davidův, kterýžto otvírá, a žádný nezavírá, a zavírá, žádný pak neotvírá:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 8, 'Vím skutky tvé. Aj, postavil jsem před tebou dvéře otevřené, a žádnýť jich nemůže zavříti. Nebo máš ač nevelikou moc, a ostříhal jsi slova mého, a nezapřels jména mého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 9, 'Aj, dávámť z zběři satanovy ty, kteříž se praví býti Židé, a nejsou, ale klamají. Aj, způsobím to, žeť přijdou a budou se klaněti před nohama tvýma, a poznajíť, že jsem já tě miloval.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 10, 'A poněvadž jsi ostříhal slova trpělivosti mé, i jáť tebe ostříhati budu od hodiny pokušení, kteráž přijíti má na všecken svět, aby zkušeni byli obyvatelé země.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 11, 'Aj, přijduť brzy. Drž se toho, co máš, aby žádný nevzal koruny tvé.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 12, 'Kdo svítězí, učiním jej sloupem v chrámě Boha svého, a nevyjdeť již více ven; a napíšiť na něm jméno Boha svého, a jméno města Boha svého, nového Jeruzaléma sstupujícího s nebe od Boha mého, i jméno své nové.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 13, 'Kdo má uši, slyš, co Duch praví církvím.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 14, 'Andělu pak církve Laodicenské piš: Toto praví Amen, svědek ten věrný a pravý, počátek stvoření Božího:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 15, 'Vímť skutky tvé, že ani jsi studený, ani horký. Ó bys studený byl aneb horký.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 16, 'A tak že jsi vlažný, a ani studený, ani horký, vyvrhu tě z úst svých.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 17, 'Nebo pravíš: Bohatý jsem, a zbohatl jsem, a žádného nepotřebuji, a nevíš, že jsi bídný, a mizerný, i chudý, i slepý, i nahý.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 18, 'Radímť, abys sobě koupil ode mne zlata ohněm zprubovaného, abys byl bohatý, a roucho bílé, abys oblečen byl, a neokazovala se hanba nahoty tvé. A očí svých pomaž kollyrium, abys viděl.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 19, 'Já kteréžkoli miluji, kárám a tresci; rozhorliž se tedy, a čiň pokání.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 20, 'Aj, stojímť u dveří, a tluku. Jestližeť by kdo uslyšel hlas můj, a otevřel dvéře, vejduť k němu, a budu s ním večeřeti, a on se mnou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 21, 'Kdož svítězí, dám jemu seděti s sebou na trůnu svém, jako i já svítězil jsem, a sedím s Otcem svým na trůnu jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 22, 'Kdo má uši, slyš, co Duch praví církvím.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 4, 1, 'Potom jsem viděl, a aj, dvéře otevřené v nebi, a ten hlas první, kterýž jsem byl slyšel jako trouby, an mluví se mnou, řkoucí: Vstup sem, a ukážiť, co se má díti potom.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 4, 2, 'A hned jsem byl u vytržení ducha, a aj, trůn postaven byl na nebi, a na trůnu jeden seděl.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 4, 3, 'A ten, kterýž seděl, podoben byl oblíčejem kameni jaspidu a sardiovi; a vůkol toho trůnu byla duha, na pohledění podobná smaragdu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 4, 4, 'A okolo toho trůnu bylo trůnů čtyřmecítma, a na těch trůních viděl jsem čtyřmecítma starců sedících, oblečených v roucha bílá. A měli na hlavách svých koruny zlaté.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 4, 5, 'A z toho trůnu pocházelo blýskání, a hromobití, a hlasové. A sedm lamp ohnivých hořících před trůnem, jenž jsou sedm duchů Božích.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 4, 6, 'Bylo také před tím trůnem moře sklené, podobné křištálu, a u prostřed trůnu a vůkol trůnu čtvero zvířat, plných očí s předu i s zadu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 4, 7, 'První pak to zvíře podobné bylo lvu, a druhé zvíře podobné teleti, a třetí zvíře mající tvárnost člověka, a čtvrté zvíře podobné orlu letícímu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 4, 8, 'A jedno každé z těch čtyř zvířat mělo šest křídel okolo, a vnitř plná byla očí, a neměla odpočinutí dnem i nocí, říkajíce: Svatý, svatý, svatý Pán Bůh všemohoucí, kterýž byl, a jest, i přijíti má.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 4, 9, 'A když ta zvířata vzdávala slávu, a čest, i díků činění sedícímu na trůnu, tomu živému na věky věků,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 4, 10, 'Padlo těch čtyřmecítma starců před oblíčejem toho sedícího na trůnu, a klanělo se tomu živému na věky věků, a metali koruny své před trůnem, řkouce:');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 4, 11, 'Hoden jsi, Pane, přijíti slávu, a čest, i moc; nebo ty jsi stvořil všecky věci, a pro vůli tvou trvají, i stvořeny jsou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 1, 'I viděl jsem po pravici sedícího na trůnu knihu popsanou vnitř i zevnitř, zapečetěnou sedmi pečetmi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 2, 'A viděl jsem anděla silného, volajícího hlasem velikým: Kdo jest hoden otevříti tu knihu, a zrušiti pečeti její?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 3, 'I nemohl žádný, ani na nebi, ani na zemi, ani pod zemí, otevříti té knihy, ani pohleděti do ní.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 4, 'Pročež já plakal jsem velmi, že není nalezen žádný, kdo by hoden byl otevříti a čísti tu knihu, ani pohleděti do ní.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 5, 'Tedy jeden z těch starců řekl mi: Neplač. Aj, svítězilť lev, ten kterýž jest z pokolení Judova, kořen Davidův, aby otevřel tu knihu, a zrušil sedm pečetí jejích.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 6, 'I pohleděl jsem, a aj, mezi trůnem a čtyřmi těmi zvířaty a mezi těmi starci Beránek stojí jako zabitý, maje sedm rohů a sedm očí, jenž jsou sedm duchů Božích, poslaných na všecku zemi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 7, 'I přišel a vzal tu knihu z pravice toho, kterýž seděl na trůnu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 8, 'A jakž vzal tu knihu, hned těch čtvero zvířat a těch čtyřmecítma starců padlo před tím Beránkem, majíce jeden každý z nich harfu, a báně zlaté plné vůně, jenž jsou modlitby svatých.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 9, 'A zpívali píseň novou, řkouce: Hoden jsi vzíti tu knihu, a otevříti pečeti její. Nebo jsi zabit, a vykoupils nás Bohu krví svou ze všelikého pokolení a jazyku a lidu i národu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 10, 'A učinil jsi nás Bohu našemu krále a kněží, a budeme kralovati na zemi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 11, 'I viděl jsem a slyšel hlas andělů mnohých okolo toho trůnu a těch zvířat i starců, a byl jich počet stokrát tisíc tisíců a desetkrát sto tisíců,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 12, 'Řkoucích velikým hlasem: Hodenť jest ten Beránek zabitý vzíti moc, a bohatství, i moudrost, i sílu, i čest, i slávu, i požehnání.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 13, 'Též všecko stvoření, kteréž jest na nebi, i na zemi, i pod zemí, i v moři, i všecko, což v nich jest, slyšel jsem řkoucí: Sedícímu na trůnu a Beránkovi požehnání, čest a sláva i síla na věky věků.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 14, 'Čtvero pak těch zvířat řeklo: Amen. A těch čtyřmecítma starců padlo, a klaněli se živému na věky věků.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 1, 'I viděl jsem, když otevřel ten Beránek jednu z těch pečetí, a slyšel jsem jedno ze čtyř zvířat, ano praví, jako hlasem hromovým: Poď, a viz.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 2, 'I pohleděl jsem, a aj, kůň bílý, a ten, kterýž seděl na něm, měl lučiště. A dána jest jemu koruna, i vyjel, přemáhaje, a aby přemáhal.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 3, 'A když otevřel pečet druhou, slyšel jsem druhé zvíře, řkoucí: Poď, a viz.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 4, 'I vyšel jiný kůň ryzí. A sedícímu na něm dáno jest, aby pokoj vyzdvihl z země, aby se vespolek mordovali; a dán jemu meč veliký.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 5, 'A když otevřel pečet třetí, slyšel jsem třetí zvíře, řkoucí: Poď, a viz. I pohleděl jsem, a aj, kůň vraný, a ten, kterýž na něm seděl, měl váhu v ruce své.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 6, 'I slyšel jsem hlas z prostředku těch čtyř zvířat, an praví: Měřice pšenice za peníz, a tři měřice ječmene za peníz, oleji pak a vínu neškoď.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 7, 'A když otevřel pečet čtvrtou, slyšel jsem hlas čtvrtého zvířete, řkoucí: Poď, a viz.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 8, 'I pohleděl jsem, a aj, kůň plavý, a toho, kterýž seděl na něm, jméno bylo smrt, a peklo šlo za ním. I dána jest jim moc nad čtvrtým dílem země, aby mordovali mečem, a hladem, a morem, a šelmami zemskými.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 9, 'A když otevřel pečet pátou, viděl jsem pod oltářem duše zmordovaných pro slovo Boží a pro svědectví, kteréž vydávali.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 10, 'I volali hlasem velikým, řkouce: Až dokud, Pane svatý a pravý, nesoudíš, a nemstíš krve naší nad těmi, kteříž přebývají na zemi?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 11, 'Tedy dáno jednomu každému z nich roucho bílé, a řečeno jim, aby odpočívali ještě za malý čas, až by se naplnil počet spoluslužebníků jejich a bratří jejich, kteříž zmordování býti mají, jako i oni.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 12, 'I pohleděl jsem, když otevřel pečet šestou, a aj, země třesení veliké stalo se, a slunce zčernalo, jako pytel žíněný, a měsíc všecken byl jako krev.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 13, 'A hvězdy nebeské padaly na zemi, podobně jako dřevo fíkové smítá s sebe ovoce své, když od velikého větru kláceno bývá.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 14, 'A nebe se schovalo jako kniha zavřená, a všeliká hora i ostrovové z místa svého pohnuli se.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 15, 'A králové země, i knížata, i bohatí, a úředníci, a mocní, i každý služebník, i všeliký svobodný, skryli se v jeskyních a v skálí hor.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 16, 'A řekli horám i skálí: Padněte na nás, a skrejte nás před tváří toho, kterýž sedí na trůnu, a před hněvem toho Beránka.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 17, 'Neboť jest přišel ten den veliký hněvu jeho. I kdo bude moci ostáti?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 7, 1, 'Potom pak viděl jsem čtyři anděly, stojící na čtyřech úhlech země, držící čtyři větry zemské, aby nevál vítr na zemi, ani na moře, ani na žádný strom.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 7, 2, 'A viděl jsem jiného anděla, vystupujícího od východu slunce, majícího pečet Boha živého. Kterýž zvolal hlasem velikým na ty čtyři anděly, jimž dáno, aby škodili zemi a moři,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 7, 3, 'Řka: Neškoďte zemi, ani moři, ani stromům, dokudž neznamenáme služebníků Boha svého na čelích jejich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 7, 4, 'I slyšel jsem počet znamenaných, sto čtyřidceti a čtyři tisíce jich znamenáno ze všech pokolení synů Izraelských.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 7, 5, 'Z pokolení Juda dvanácte tisíců znamenaných, z pokolení Ruben dvanácte tisíců znamenaných, z pokolení Gád dvanácte tisíců znamenaných.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 7, 6, 'Z pokolení Asser dvanácte tisíců znamenaných, z pokolení Neftalím dvanácte tisíců znamenaných, z pokolení Manasses dvanácte tisíců znamenaných.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 7, 7, 'Z pokolení Simeon dvanácte tisíců znamenaných, z pokolení Léví dvanácte tisíců znamenaných, z pokolení Izachar dvanácte tisíců znamenaných.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 7, 8, 'Z pokolení Zabulon dvanácte tisíců znamenaných, z pokolení Jozef dvanácte tisíců znamenaných, z pokolení Beniamin dvanácte tisíců znamenaných.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 7, 9, 'Potom pohleděl jsem, a aj, zástup veliký, kteréhož by žádný přečísti nemohl, ze všech národů a pokolení a lidí i jazyků, ani stojí před trůnem a před oblíčejem Beránka, oblečeni jsouce v bílé roucho, a palmy v rukou jejich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 7, 10, 'A volali hlasem velikým, řkouce: Spasení jest od Boha našeho na trůnu sedícího a od Beránka.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 7, 11, 'A všickni andělé stáli okolo trůnu a starců a čtyř zvířat. I padli před trůnem na tváři své, a klaněli se Bohu,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 7, 12, 'Řkouce: Amen. Požehnání, a sláva, a moudrost, a díků činění, a čest, a moc, i síla Bohu našemu na věky věků. Amen.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 7, 13, 'I promluvil ke mně jeden z těch starců, a řekl mi: Kdo jsou tito oblečení v bílé roucho? A odkud přišli?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 7, 14, 'I řekl jsem jemu: Pane, ty víš. I řekl mi: To jsou ti, kteříž přišli z velikého ssoužení, a umyli roucha svá, a zbílili je ve krvi Beránkově.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 7, 15, 'Protož jsou před trůnem Božím, a slouží jemu dnem i nocí v chrámě jeho; a ten, kterýž sedí na trůnu, zastěňovati je bude.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 7, 16, 'Nebudouť lačněti více, ani žízniti více, a nebude bíti na ně slunce, ani žádné horko.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 7, 17, 'Nebo Beránek, kterýž jest u prostřed trůnu, pásti je bude, a dovedeť je k živým studnicím vod, a setře Bůh všelikou slzu s očí jejich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 8, 1, 'A když otevřel pečet sedmou, stalo se mlčení na nebi, jako za půl hodiny.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 8, 2, 'I viděl jsem sedm těch andělů, kteříž stojí před oblíčejem Božím, jimž dáno sedm trub.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 8, 3, 'A jiný anděl přišel, a postavil se před oltářem, maje kadidlnici zlatou. I dáni jsou jemu zápalové mnozí, aby je obětoval s modlitbami všech svatých na oltáři zlatém, kterýž jest před trůnem.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 8, 4, 'I vstoupil dým zápalů s modlitbami svatých z ruky anděla před oblíčej Boží.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 8, 5, 'I vzal anděl kadidlnici, a naplnil ji ohněm z oltáře, a svrhl ji na zem. I stalo se hromobití, a hlasové, a blýskání, i země třesení.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 8, 6, 'A těch sedm andělů, kteříž měli sedm trub, připravili se, aby troubili.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 8, 7, 'I zatroubil první anděl, a stalo se krupobití a oheň smíšený se krví, a svrženo jest to na zem. A třetí díl stromů shořel, a všecka tráva zelená spálena jest.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 8, 8, 'Potom zatroubil druhý anděl, a jako hora veliká ohněm hořící uvržena jest do moře. I obrácen jest v krev třetí díl moře.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 8, 9, 'A zemřel v moři třetí díl stvoření těch, kteráž měla duši, a třetí díl lodí zhynul.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 8, 10, 'A třetí anděl zatroubil, i spadla s nebe hvězda veliká, hořící jako pochodně, a padla na třetí díl řek a do studnic vod.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 8, 11, 'Té pak hvězdy jméno bylo Pelynek. I obrátil se třetí díl vod v pelynek, a mnoho lidí zemřelo od těch vod, nebo byly zhořkly.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 8, 12, 'Potom čtvrtý anděl zatroubil, i udeřena jest třetina slunce, a třetina měsíce, a třetí díl hvězd, tak že se třetí díl jich zatměl, a třetina dne nesvítila, a též podobně i noci.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 8, 13, 'I viděl jsem a slyšel anděla jednoho, an letí po prostředku nebe, a praví hlasem velikým: Běda, běda, běda těm, kteříž přebývají na zemi, pro jiné hlasy trub tří andělů, kteříž mají troubiti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 1, 'Potom anděl pátý zatroubil, i viděl jsem, že hvězda s nebe spadla na zem, a dán jest jí klíč od studnice propasti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 2, 'Kterážto otevřela studnici propasti. I vyšel dým z té studnice jako dým z peci veliké, i zatmělo se slunce i povětří od dymu té studnice.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 3, 'A z toho dymu vyšly kobylky na zemi, jimž dána jest moc, jakouž moc mají štírové zemští.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 4, 'Ale řečeno jim, aby neškodily trávě zemské, ani čemu zelenému, ani kterémukoli stromoví, než toliko lidem, kteříž nemají znamení Božího na čelích svých.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 5, 'Dáno jest pak jim, ne aby je zabíjely, ale trápily za pět měsíců, a aby trápení jich bylo jako trápení od štíra, když by ušťkl člověka.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 6, 'Protož v těch dnech hledati budou lidé smrti, ale nenaleznou jí, a žádati budou zemříti, ale smrt uteče od nich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 7, 'Způsob pak těch kobylek podobný byl koňům připraveným k boji, a na hlavách jejich byly jako koruny podobné zlatu, a tváři jejich jako tváři lidské.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 8, 'A měly vlasy jako vlasy ženské, a zubové jejich byli jako lvů.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 9, 'Měly také pancíře jako pancíře železné, a zvuk křídel jejich jako zvuk vozů, když množství koní běží k boji.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 10, 'A měly ocasy podobné štírům, a žihadla v ocasích jejich byla, a moc jejich byla škoditi lidem za pět měsíců.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 11, 'Měly pak nad sebou krále, anděla propasti, jemuž jméno Židovsky Abaddon, a Řecky Apollyon.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 12, 'Bída jedna pominula, a aj, přijdou ještě dvě bídy potom.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 13, 'Tedy šestý anděl zatroubil, i slyšel jsem hlas jeden ze čtyř rohů oltáře zlatého, kterýž jest před oblíčejem Božím,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 14, 'Řkoucí šestému andělu, kterýž měl troubu: Rozvěž ty čtyři anděly, kteříž jsou u vězení při veliké řece Eufrates.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 15, 'I rozvázáni jsou ti čtyři andělé, kteříž byli připraveni k hodině, a ke dni, a k měsíci, a k roku, aby zmordovali třetí díl lidí.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 16, 'A byl počet vojska lidu jízdného dvěstěkrát tisíc tisíců; nebo slyšel jsem počet jich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 17, 'A též viděl jsem koně u vidění, a ti, kteříž seděli na nich, měli pancíře ohnivé a hyacintové a z siry. Hlavy pak těch koní byly jako hlavy lvové, a z úst jejich vycházel oheň, a dým, a sira.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 18, 'A tímto trojím zmordována jest třetina lidu, ohněm, a dymem, a sirou, kteréž vycházely z úst jejich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 19, 'Nebo moc jejich jest v ústech jejich a v ocasích jejich; ocasové zajisté jejich jsou podobni hadům, majíce hlavy, jimiž škodí.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 20, 'Jiní pak lidé, kteříž nejsou zmordováni těmi ranami, nečinili pokání z skutků rukou svých, aby se neklaněli ďáblům, a modlám zlatým, a stříbrným, a měděným, i kamenným, i dřevěným, kteréž ani hleděti nemohou, ani slyšeti, ani choditi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 21, 'Aniž činili pokání z vražd svých, ani z trávení svých, ani z smilstva svého, ani z krádeží svých.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 10, 1, 'I viděl jsem jiného anděla silného, sstupujícího s nebe, oděného oblakem, a duha na hlavě jeho byla, a tvář jeho jako slunce, a nohy jeho jako sloupové ohniví.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 10, 2, 'A v ruce své měl knížku otevřenou. I postavil nohu svou pravou na moři, a levou na zemi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 10, 3, 'A volal hlasem velikým, jako by lev řval. A když dokonal volání, mluvilo sedm hromů hlasy své.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 10, 4, 'A když odmluvilo sedm hromů hlasy své, byl bych psal. Ale slyšel jsem hlas s nebe řkoucí ke mně: Zapečeť to, co mluvilo sedm hromů, než nepiš toho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 10, 5, 'Tedy anděl, kteréhož jsem viděl stojícího na moři a na zemi, pozdvihl ruky své k nebi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 10, 6, 'A přisáhl skrze živého na věky věků, kterýž stvořil nebe i to, což v něm jest, a zemi i to, což na ní jest, a moře i to, což v něm jest, že již více času nebude.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 10, 7, 'Ale ve dnech hlasu sedmého anděla, když bude troubiti, dokonánoť bude tajemství Boží, jakož zvěstoval služebníkům svým prorokům.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 10, 8, 'A ten hlas, kterýž jsem byl slyšel s nebe, opět mluvil se mnou, a řekl: Jdi, a vezmi tu knížku otevřenou z ruky anděla, stojícího na moři a na zemi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 10, 9, 'I šel jsem k andělu, a řekl jsem jemu: Dej mi tu knížku. I řekl mi: Vezmi, a požři ji, a učiníť hořkost v břiše tvém, ale v ústech tvých budeť sladká jako med.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 10, 10, 'I vzal jsem tu knížku z ruky anděla, a požřel jsem ji. I byla v ústech mých sladká jako med, ale když jsem ji požřel, hořko mi bylo v břiše mém.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 10, 11, 'I dí mi: Musíš opět prorokovati lidem, a národům, a jazykům, i králům mnohým.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 1, 'I dána mi třtina, podobná prutu, a postavil se tu anděl, řka: Vstaň, a změř chrám Boží, i oltář, i ty, kteříž se modlí v něm.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 2, 'Ale síň, kteráž vně jest před chrámem, vyvrz ven, a neměř jí. Neboť jest dána pohanům, a budouť tlačiti město svaté za čtyřidceti a dva měsíce.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 3, 'Ale dám je dvěma svědkům svým, kteříž budou prorokovati tisíc dvě stě a šedesáte dnů, oblečeni jsouce v pytle.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 4, 'Tiť jsou dvě olivy a dva svícnové, stojící před oblíčejem Boha vší země.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 5, 'Jimžto jestliže by kdo chtěl ubližovati, oheň vyjde z úst jejich, a sžíře nepřátely jejich; a kdož by koli jim škoditi chtěl, takť musí zabit býti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 6, 'Tiť mají moc zavříti nebe, aby nepršel déšť za dnů proroctví jejich; a mají moc nad vodami, aby je obrátili v krev, a bili zemi všelikou ranou, kolikrát by koli chtěli.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 7, 'Ale když dokonají svědectví své, šelma ta vystupující z propasti válku povede proti nim, a svítězí nad nimi, i zmorduje je.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 8, 'A ležeti budou těla jejich mrtvá na rynku města velikého, kteréž slove duchovně Sodoma a Egypt, kdež i Pán náš ukřižován jest.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 9, 'A vídati budou mnozí z pokolení, a z lidu, a z jazyků, i z národů ta těla jejich mrtvá za půl čtvrta dne, ale těl jejich mrtvých nedadí pochovati v hrobích.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 10, 'Anobrž ti, kteříž přebývají na zemi, radovati se budou nad nimi a veseliti se, a dary budou posílati jedni druhým; nebo ti dva proroci trápili ty, kteříž přebývají na zemi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 11, 'Ale po půl čtvrtu dni duch života od Boha vstoupil do nich, i postavili se na nohách svých, a bázeň veliká spadla na ty, kteříž je viděli.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 12, 'Potom slyšeli hlas veliký s nebe, řkoucí k nim: Vstupte sem. I vstoupili na nebe v oblace, a hleděli na ně nepřátelé jejich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 13, 'A v tu hodinu stalo se země třesení veliké, a desátý díl města padl, a zbito jest v tom země třesení sedm tisíců lidu, a jiní zstrašeni jsou, a vzdali slávu Bohu nebeskému.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 14, 'Bída druhá pominula, a aj, třetí bída přijde rychle.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 15, 'A sedmý anděl zatroubil, i stali se hlasové velicí v nebi, řkoucí: Učiněnať jsou království světa Pána našeho a Krista jeho, a kralovatiť bude na věky věků.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 16, 'Tedy těch čtyřmecítma starců, kteříž před oblíčejem Božím sedí na stolicích svých, padli na tváři své, a klaněli se Bohu,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 17, 'Řkouce: Díky činíme tobě, Pane Bože všemohoucí, kterýž jsi, a kterýžs byl, a kterýž přijíti máš; nebo jsi přijal moc svou velikou, a království ujal.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 18, 'I rozhněvali se národové, a přišel hněv tvůj, a čas mrtvých, aby souzeni byli, a aby dána byla odplata služebníkům tvým, prorokům a svatým, a bojícím se jména tvého, malým i velikým, a aby zkaženi byli ti, kteříž nakažují zemi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 19, 'I otevřín jest chrám Boží na nebi, a vidína jest truhla smlouvy jeho v chrámě jeho. I stalo se blýskání, a hlasové, a hromobití, a země třesení, i krupobití veliké.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 12, 1, 'I ukázal se div veliký na nebi: žena oděná sluncem, pod jejímiž nohama byl měsíc, a na jejíž hlavě byla koruna dvanácti hvězd.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 12, 2, 'A jsuci těhotná, křičela, pracujici ku porodu, a trápěci se, aby porodila.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 12, 3, 'I vidín jest jiný div na nebi. Nebo aj, drak veliký ryšavý ukázal se, maje hlav sedm a rohů deset, a na těch hlavách svých sedm korun.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 12, 4, 'Jehož ocas strhl třetinu hvězd s nebe, a svrhl je na zem. Ten pak drak stál před ženou, kteráž měla poroditi, aby, jakž by porodila, syna jejího sežral.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 12, 5, 'I porodila syna pacholíka, kterýž měl spravovati všecky národy prutem železným. I vytržen jest syn její k Bohu a k trůnu jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 12, 6, 'A žena utekla na poušť, kdež měla místo od Boha připravené, aby ji tam živili za dnů tisíc dvě stě a šedesát.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 12, 7, 'I stal se boj na nebi: Michal a andělé jeho bojovali s drakem, a drak bojoval i andělé jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 12, 8, 'Ale nic neobdrželi, aniž jest nalezeno více místo jejich na nebi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 12, 9, 'I svržen jest drak ten veliký, had starý, kterýž slove ďábel a satanáš, svodící všecken okršlek světa; svržen jest na zem, i andělé jeho s ním svrženi jsou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 12, 10, 'I slyšel jsem hlas veliký, řkoucí na nebi: Nyní stalo se spasení, a moc, i království Boha našeho, a moc Krista jeho; nebo svržen jest žalobník bratří našich, kterýž žaloval na ně před oblíčejem Boha našeho dnem i nocí.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 12, 11, 'Ale oni svítězili nad ním skrze krev Beránka, a skrze slovo svědectví svého, a nemilovali duší svých až do smrti.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 12, 12, 'Protož veselte se nebesa, a kteříž přebýváte v nich. Běda těm, kteříž přebývají na zemi a na moři; nebo ďábel sstoupil k vám, maje hněv veliký, věda, že krátký čas má.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 12, 13, 'A když uzřel drak, že jest svržen na zem, honil ženu tu, kteráž porodila toho pacholíka.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 12, 14, 'Ale dána jsou té ženě dvě křídla orlice veliké, aby letěla od tváři hada na poušť, na místo své, kdež by ji živili do času a časů, a do půl času.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 12, 15, 'I vypustil had z úst svých po té ženě vodu jako řeku, aby ji řeka zachvátila.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 12, 16, 'Ale země pomohla ženě; nebo otevřela země ústa svá, a požřela řeku, kterouž vypustil drak z úst svých.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 12, 17, 'I rozhněval se drak na tu ženu, a šel bojovati s jinými z semene jejího, kteříž ostříhají přikázaní Božích, a mají svědectví Ježíše Krista.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 1, 'I stál jsem na písku mořském. I viděl jsem šelmu vystupující z moře, kteráž měla sedm hlav a deset rohů. A na rozích jejích deset korun, a na hlavách jejích jméno rouhání.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 2, 'Byla pak šelma ta, kterouž jsem viděl, podobná pardovi, a nohy její jako nedvědí, a ústa její jako ústa lvová. I dal jí drak sílu svou, a trůn svůj, i moc velikou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 3, 'A viděl jsem, ano jedna z hlav jejích jako zbitá byla až na smrt, ale rána její smrtelná uzdravena jest. Tedy divivši se všecka země, šla za tou šelmou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 4, 'A klaněli se tomu draku, kterýž dal moc šelmě; klaněli se i šelmě, řkouce: Kdo jest podobný té šelmě? Kdo bude moci bojovati s ní?');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 5, 'I dána jsou jí ústa mluvící veliké věci a rouhání, a dána jí moc vládnouti za čtyřidceti a dva měsíce.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 6, 'Protož otevřela ústa svá k rouhání se Bohu, aby se jménu jeho rouhala, i stánku jeho, i těm, kteříž přebývají na nebi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 7, 'Dáno jí i bojovati s svatými, a přemáhati je; a dána jí moc nad všelikým pokolením, nad jazykem, i nad národem.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 8, 'Protož klaněti se jí budou všickni, kteříž přebývají na zemi, jichžto jména nejsou napsaná v knize života Beránka, toho zabitého od počátku světa.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 9, 'Má-li kdo uši, slyš.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 10, 'Jestliže kdo do vězení povede, do vězení půjde; zabije-li kdo mečem, musí mečem zabit býti. Zdeť jest trpělivost a víra svatých.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 11, 'Potom viděl jsem jinou šelmu vystupující z země, a měla dva rohy, podobné Beránkovým, ale mluvila jako drak.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 12, 'Kteráž všecku moc první té šelmy provozuje před tváří její; a působí to, že země i ti, kteříž přebývají na ní, klanějí se šelmě té první, jejížto rána smrtelná uzdravena byla.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 13, 'A činí divy veliké, tak že i ohni rozkazuje sstupovati s nebe na zem před oblíčejem lidským.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 14, 'A svodí ty, kteříž přebývají na zemi, těmi divy, kteréž dáno jí činiti před oblíčejem šelmy, říkající obyvatelům země, aby udělali obraz té šelmě, kteráž měla ránu od meče, ale ožila zase.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 15, 'I dáno jí, aby dáti mohla ducha tomu obrazu šelmy, aby i mluvil obraz té šelmy, a aby to způsobila, kteřížkoli neklaněli by se obrazu té šelmy, aby byli zmordováni.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 16, 'A rozkazuje všechněm, malým i velikým, bohatým, i chudým, svobodným i v službu podrobeným, aby měli znamení na pravé ruce své, aneb na čelích svých,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 17, 'A aby žádný nemohl kupovati ani prodávati, než ten, kdož má znamení aneb jméno té šelmy, aneb počet jména jejího.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 18, 'Tuť jest moudrost. Kdo má rozum, sečtiž počet té šelmy. Nebo jest počet člověka, a jestiť počet ten šest set šedesáte a šest.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 1, 'Tedy pohleděl jsem, a aj, Beránek stál na hoře Sion, a s ním sto čtyřidceti a čtyři tisíce majících jméno Otce jeho napsané na čelích svých.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 2, 'A slyšel jsem hlas s nebe, jako hlas vod mnohých, a jako hlas hromu velikého. A hlas slyšel jsem těch, kteříž hrají na harfy své.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 3, 'A zpívali jakožto píseň novou, před trůnem, a před těmi čtyřmi zvířaty, a před těmi starci, a žádný nemohl se naučiti té písni, jediné těch sto čtyřidceti a čtyři tisíce, kteříž jsou koupeni z země.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 4, 'Totoť jsou ti, kteříž s ženami nejsou poškvrněni; nebo panicové jsou. Tiť jsou, kteříž následují Beránka, kamž by koli šel; tiť jsou koupeni z lidí, prvotiny Bohu a Beránkovi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 5, 'A v ústech jejich není nalezena lest; neboť jsou bez úhony před trůnem Božím.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 6, 'I viděl jsem jiného anděla letícího po prostředku nebe, majícího evangelium věčné, aby je zvěstoval těm, kteříž bydlí na zemi, a všelikému národu, i pokolení, i jazyku, i lidu,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 7, 'Řkoucího velikým hlasem: Bojte se Boha, a vzdejte jemu chválu, neboť přišla hodina soudu jeho; a klanějte se tomu, kterýž učinil nebe i zemi i moře i studnice vod.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 8, 'A jiný anděl letěl za ním, řka: Padl, padl Babylon, to město veliké, nebo vínem hněvu smilství svého napájelo všecky národy.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 9, 'A třetí anděl letěl za nimi, pravě velikým hlasem: Bude-li se kdo klaněti šelmě a obrazu jejímu, a vezme-li znamení její na čelo své aneb na ruku svou,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 10, 'I tenť bude píti víno hněvu Božího, víno, kteréž jest vlito do kalichu hněvu jeho; a trápen bude ohněm a sirou před oblíčejem svatých andělů a před oblíčejem Beránka.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 11, 'A dým muk jejich vstoupíť na věky věků, a nebudouť míti odpočinutí dnem i nocí ti, kteříž se klanějí šelmě a obrazu jejímu, a jestliže kdo přijme znamení jména jejího.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 12, 'Tuť jest trpělivost svatých, tu jsou ti, kteříž ostříhají přikázaní Božích a víry Ježíšovy.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 13, 'I slyšel jsem hlas s nebe, řkoucí ke mně: Piš: Blahoslavení jsou od této chvíle mrtví, kteříž v Pánu umírají. Duch zajisté dí jim, aby odpočinuli od prací svých, skutkové pak jejich jdou za nimi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 14, 'I pohleděl jsem, a aj, oblak bělostkvoucí, a na tom oblaku seděl podobný Synu člověka, maje na hlavě své korunu zlatou, a v ruce své srp ostrý.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 15, 'A jiný anděl vyšel z chrámu, volaje hlasem velikým na toho, kterýž seděl na oblaku: Pusť srp svůj, a žni; neboť přišla tobě hodina žně, nebo již dozrala žeň země.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 16, 'I spustil ten, kterýž seděl na oblaku, srp svůj na zem, a požata jest země.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 17, 'A jiný anděl vyšel z chrámu toho, kterýž jest na nebi, maje i on srp ostrý.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 18, 'Opět vyšel jiný anděl z oltáře, kterýž měl moc nad ohněm, a volal křikem velikým na toho, kterýž měl srp ostrý, řka: Pusť srp svůj ostrý, a zbeř hrozny vinice zemské; neboť jsou uzrali hroznové její.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 19, 'I spustil anděl srp svůj na zem, a sebral vinici země, a vmetal do jezera velikého hněvu Božího.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 20, 'I tlačeno jest jezero před městem, a vyšla krev z jezera až do udidl koňům za tisíc a za šest set honů.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 15, 1, 'Potom viděl jsem jiný zázrak na nebi veliký a předivný: Sedm těch andělů majících sedm ran posledních; nebo skrze ně má dokonán býti hněv Boží.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 15, 2, 'A viděl jsem jako moře sklené, smíšené s ohněm, a ty, kteříž svítězili nad tou šelmou a obrazem jejím a nad charakterem jejím i nad počtem jména jejího, ani stojí nad tím mořem skleným, majíce harfy Boží,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 15, 3, 'A zpívají píseň Mojžíše, služebníka Božího, a píseň Beránkovu, řkouce: Velicí a předivní jsou skutkové tvoji, Pane Bože všemohoucí, spravedlivé a pravé jsou cesty tvé, ó Králi svatých.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 15, 4, 'Kdož by se nebál tebe, Pane, a nezveleboval jména tvého? Nebo ty sám svatý jsi. Všickni zajisté národové přijdou, a klaněti se budou před oblíčejem tvým; nebo soudové tvoji zjeveni jsou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 15, 5, 'Potom pak pohleděl jsem, a aj, otevřín byl chrám stánku svědectví na nebi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 15, 6, 'I vyšlo sedm těch andělů z chrámu, majících sedm ran, oblečeni jsouce rouchem lněným, čistým a bělostkvoucím, a přepásáni na prsech pasy zlatými.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 15, 7, 'A jedno ze čtyř zvířat dalo sedmi andělům sedm koflíků zlatých, plných hněvu Boha živého na věky věků.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 15, 8, 'I naplněn jest chrám dymem od slávy Boží a od moci jeho, a žádný nemohl vjíti do chrámu, dokudž se nevykonalo sedm ran těch sedmi andělů.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 1, 'I slyšel jsem hlas veliký z chrámu, řkoucí těm sedmi andělům: Jděte, vylíte sedm koflíků hněvu Božího na zem.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 2, 'I šel první, a vylil koflík svůj na zem, i vyvrhli se vředové škodliví a zlí na lidech, majících znamení šelmy, a na těch, kteříž se klaněli obrazu jejímu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 3, 'Zatím druhý anděl vylil koflík svůj na moře, a učiněno jest jako krev umrlého, a všeliká duše živá v moři umřela.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 4, 'Potom třetí anděl vylil koflík svůj na řeky a na studnice vod, i obráceny jsou v krev.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 5, 'I slyšel jsem anděla vod, řkoucího: Spravedlivý jsi, Pane, kterýž jsi, a kterýžs byl, a svatý, žes to usoudil.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 6, 'Poněvadž krev svatých a proroků vylévali, i dal jsi jim krev píti; nebo jsou hodni.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 7, 'I slyšel jsem jiného od oltáře, kterýž řekl: Jistě, Pane Bože všemohoucí, praví jsou a spravedliví soudové tvoji.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 8, 'Potom čtvrtý anděl vylil koflík svůj na slunce, i dáno jest jemu páliti lidi ohněm.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 9, 'I pálili se lidé horkem velikým, a rouhali se jménu Boha toho, kterýž má moc nad těmi ranami, a však nečinili pokání, aby vzdali slávu jemu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 10, 'Tedy pátý anděl vylil koflík svůj na stolici té šelmy, i učiněno jest království její tmavé, i kousali jazyky své pro bolest.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 11, 'A rouhali se Bohu nebeskému pro bolesti své a pro vředy své, a však nečinili pokání z skutků svých.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 12, 'Šestý pak anděl vylil koflík svůj na tu velikou řeku Eufrates, i vyschla voda její, aby připravena byla cesta králům od východu slunce.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 13, 'A viděl jsem, ano z úst draka a z úst šelmy a z úst falešného proroka vyšli tři duchové nečistí, podobní žabám.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 14, 'Nebo jsou duchové ďábelští, ješto činí divy, a chodí mezi krále zemské a všeho okršlku světa, aby je shromáždili k boji, k tomu velikému dni Boha všemohoucího.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 15, 'Aj, přicházímť jako zloděj. Blahoslavený, kdož bdí a ostříhá roucha svého, aby nah nechodil, aby neviděli hanby jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 16, 'I shromáždil je na místo, kteréž slove Židovsky Armageddon.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 17, 'Tedy sedmý anděl vylil koflík svůj na povětří, i vyšel hlas veliký z chrámu nebeského, z trůnu, řkoucí: Stalo se.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 18, 'I stali se zvukové a hromobití a blýskání, i země třesení stalo se veliké, jakéhož nikdy nebylo, jakž jsou lidé na zemi, země třesení tak velikého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 19, 'I roztrhlo se to veliké město na tři strany, a města národů padla. A Babylon veliký přišel na pamět před oblíčejem Božím, aby dal jemu kalich vína prchlivosti hněvu svého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 20, 'A všickni ostrovové pominuli, a hory nejsou nalezeny.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 21, 'A kroupy veliké jako centnéřové pršely s nebe na lidi. I rouhali se Bohu lidé pro ránu těch krup; nebo velmi veliká byla ta jejich rána.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 1, 'I přišel jeden z sedmi andělů, kteříž měli sedm koflíků, a mluvil se mnou, řka ke mně: Poď, ukážiť odsouzení nevěstky veliké, kteráž sedí na vodách mnohých,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 2, 'S kterouž smilnili králové země, a zpili se vínem smilství jejího obyvatelé země.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 3, 'I odnesl mne na poušť v duchu, a viděl jsem ženu sedící na šelmě brunátné, plné jmen rouhání, mající sedm hlav a deset rohů.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 4, 'Žena pak odína byla šarlatem a brunátným rouchem, a ozdobena zlatem a kamením drahým i perlami, mající koflík zlatý v ruce své, plný ohavností a nečistoty smilstva svého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 5, 'A na čele jejím napsané jméno: Tajemství, Babylon veliký, mátě smilstva a ohavností země.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 6, 'A viděl jsem ženu tu opilou krví svatých, a krví mučedlníků Ježíšových, a viděv ji, divil jsem se divením velikým.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 7, 'I řekl mi anděl: Co se divíš? Já tobě povím tajemství té ženy i šelmy, kteráž ji nese, mající hlav sedm a rohů deset.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 8, 'Šelma, kteroužs viděl, byla, a není, a máť vystoupiti z propasti, a na zahynutí jíti. I diviti se budou bydlitelé země, (ti, kterýchž jména nejsou napsána v knize života od ustanovení světa,) vidouce šelmu, kteráž byla, a není, a však jest.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 9, 'Tentoť pak jest smysl, a máť moudrost: Sedm hlav jest sedm hor, na kterýchž ta žena sedí.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 10, 'A králů sedm jest. Pět jich padlo, jeden jest, jiný ještě nepřišel; a když přijde, na malou chvíli musí trvati.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 11, 'A šelma, kteráž byla, a není, onať jest osmý, a z těch sedmi jest, i na zahynutí jde.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 12, 'Deset pak rohů, kteréžs viděl, jestiť deset králů, kteříž ještě království nepřijali, ale přijmouť moc jako králové jedné hodiny spolu s šelmou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 13, 'Tiť jednu radu mají, a sílu i moc svou šelmě dadí.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 14, 'Tiť bojovati budou s Beránkem, a Beránek svítězí nad nimi, neboť Pán pánů jest a Král králů, i ti, kteříž jsou s ním, povolaní, a vyvolení, a věrní.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 15, 'I řekl mi: Vody, kteréžs viděl, kdež nevěstka sedí, jsouť lidé, a zástupové, a národové, a jazykové.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 16, 'Deset pak rohů, kteréžs viděl na šelmě, ti v nenávist vezmou nevěstku, a učiní ji opuštěnou a nahou, a tělo její jísti budou, a ji páliti budou ohněm.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 17, 'Neboť dal Bůh v srdce jejich, aby činili vůli jeho, a aby se sjednomyslnili, a království své šelmě dali, dokudž by nebyla vykonána slova Boží.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 18, 'A žena, kteroužs viděl, jest město to veliké, kteréž má království nad králi země.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 1, 'Potom pak viděl jsem anděla sstupujícího s nebe, majícího moc velikou, a země osvícena byla od slávy jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 2, 'I zkřikl silně hlasem velikým, řka: Padl, padl Babylon ten veliký, a učiněn jest příbytkem ďáblů, a stráží každého ducha nečistého, a stráží všelikého ptactva nečistého a ohyzdného.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 3, 'Nebo z vína hněvu smilstva jeho pili všickni národové, a králové zemští smilnili s ním, a kupci zemští z zboží rozkoší jeho zbohatli.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 4, 'I slyšel jsem jiný hlas s nebe, řkoucí: Vyjděte z něho, lide můj, abyste neobcovali hříchům jeho, a abyste nepřijali z jeho ran.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 5, 'Neboť dosáhli hříchové jeho až k nebi, a rozpomenul se Bůh na nepravosti jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 6, 'Dejtež jemu, jakož i on dával vám, a dejte jemu dvénásob podlé skutků jeho; v koflík, kterýž naléval, nalíte jemu dvénásob.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 7, 'Jakž se mnoho chlubil a zbůjněl byl, tak mnoho dejte jemu muk a pláče. Neboť v srdci svém praví: Sedím královna, a nejsemť vdovou, a pláče neuzřím.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 8, 'Protož v jeden den přijdou rány jeho, smrt a pláč i hlad, a ohněm spálen bude; nebo silný jest Pán, kterýž jej potupí.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 9, 'I plakati ho budou, a kvíliti nad ním králové země, kteříž s ním smilnili, a svou rozkoš měli, když uzří dým zapálení jeho,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 10, 'Zdaleka stojíce, pro bázeň muk jeho, a řkouce: Běda, běda, veliké město Babylon, to město silné, že jedné hodiny přišel odsudek tvůj.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 11, 'Ano i kupci zemští budou plakati a kvíliti nad ním; nebo koupí jejich žádný nebude kupovati více,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 12, 'Koupě zlata, a stříbra, a drahého kamene, i perel, i kmentu, i šarlatu, i hedbáví, i brunátného roucha, i všelikého dřeva thyinového, a všech nádob z kostí slonových, i všelikého nádobí z nejdražšího dříví, i z mědi, i z železa, i z mramoru;');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 13, 'A skořice, i vonných věcí, a mastí, i kadidla, i vína, i oleje, i bělí, i pšenice, i dobytka, i ovec, i koní, a vozů, i služebníků, i duší lidských.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 14, 'I ovoce žádostivá duši tvé odešla od tebe, a všecko tučné a krásné odešlo od tebe, a aniž toho již více nalezneš.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 15, 'Ti kupci, kteříž v tom kupčili, a jím zbohatli, zdaleka stanou pro strach muk jeho, plačíce, a kvílíce,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 16, 'A řkouce: Běda, běda, město veliké, kteréž odíno bylo kmentem, a šarlatem, a brunátným rouchem, a ozdobeno bylo zlatem, a kamením drahým, i perlami; nebo v jednu hodinu zahynula tak veliká bohatství.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 17, 'I všeliký marinář, i všecko množství lidí, kteříž jsou na lodech, i plavci, a kteřížkoli svou živnost na moři mají, zdaleka stanou,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 18, 'A zkřiknou, vidouce dým zapálení jeho, řkouce: Které bylo podobné městu tomuto velikému!');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 19, 'A sypouce prach na hlavy své, křičeti budou, plačíce, a kvílíce, a řkouce: Běda, běda, město veliké, v němž zbohatli všickni, kteříž měli lodí na moři, ze mzdy jeho; nebo jedné hodiny zpustlo.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 20, 'Raduj se nad ním nebe i svatí apoštolé i proroci; nebo pomstilť vás Bůh nad ním.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 21, 'I zdvihl jeden silný anděl kámen jako žernov veliký, a hodil jím do moře, řka: Tak prudce uvržen bude Babylon, to město veliké, a nikoli více nebude nalezen.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 22, 'A hlas na harfy hrajících, a zpěváků, a pišťců, a trubačů nikoli nebude více v tobě slyšán, a žádný řemeslník žádného řemesla nebude v tobě více nalezen, a zvuk žernovu nebude v tobě více slyšán.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 23, 'Ani světlo svíce nebude v tobě více svítiti, a hlas ženicha ani nevěsty nebude v tobě více slyšán, ješto kupci tvoji bývala knížata zemská, a tráveními tvými v blud uvedeni byli všickni národové.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 24, 'Ale v něm nalezena jest krev proroků a svatých i všech zmordovaných na zemi.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 1, 'Potom jsem slyšel veliký hlas velikého zástupu na nebi, řkoucího: Halelujah. Spasení, a sláva, a čest, i moc Pánu Bohu našemu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 2, 'Neboť jsou praví a spravedliví soudové jeho, kterýž odsoudil nevěstku tu velikou, kteráž byla porušila zemi smilstvem svým, a pomstil krve služebníků svých z ruky její.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 3, 'I řekli podruhé: Halelujah. A dým její vstupoval na věky věků.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 4, 'I padlo, čtyřmecítma starců a čtvero zvířat, a klaněli se Bohu sedícímu na trůnu, řkouce: Amen, Halelujah.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 5, 'I vyšel z trůnu hlas, řkoucí: Chvalte Boha našeho všickni služebníci jeho, a kteříž se bojíte jeho, i malí i velicí.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 6, 'A slyšel jsem hlas jako zástupu velikého, a jako hlas vod mnohých, a jako zvuk hromů silných, řkoucích: Halelujah. Kralovalť Pán Bůh náš všemohoucí.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 7, 'Radujme se, a veselme se, a chválu vzdejme jemu. Neboť přišla svadba Beránkova, a manželka jeho připravila se.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 8, 'A dáno jest jí, aby se oblékla v kment čistý a stkvoucí, a ten kment jsouť ospravedlňování svatých.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 9, 'I řekl mi: Piš: Blahoslavení, kteříž jsou k večeři svatby Beránkovy povoláni. A řekl mi: Tato slova Boží jsou pravá.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 10, 'I padl jsem k nohám jeho, abych se klaněl jemu. Ale řekl mi: Hleď, abys toho nečinil. Jsemť spoluslužebník tvůj i bratří tvých, těch, kteříž mají svědectví Ježíšovo. Bohu se klaněj. Svědectví pak Ježíšovo jestiť duch proroctví.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 11, 'I viděl jsem nebe otevřené, a aj, kůň bílý, a ten, kterýž seděl na něm, sloul Věrný a Pravý, a spravedlivě soudí i bojuje.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 12, 'Oči pak jeho byly jako plamen ohně, a na hlavě jeho korun množství, a měl jméno napsané, kteréhož žádný neví, než on sám.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 13, 'A byl odín rouchem pokropeným krví, a sloveť jméno jeho Slovo Boží.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 14, 'A rytířstvo nebeské jelo za ním na bílých koních, jsouce odíni kmentem bílým a čistým.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 15, 'A z úst jeho vycházel meč ostrý, aby jím bil národy. Nebo on bude je spravovati prutem železným; onť i pres vína hněvu a prchlivosti Boha všemohoucího tlačiti bude.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 16, 'A máť na rouchu a na bedrách svých napsané jméno: Král králů a Pán pánů.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 17, 'I viděl jsem jednoho anděla, an stojí v slunci, a zkřikl hlasem velikým, řka všechněm ptákům, kteříž létali po prostřed nebes: Poďte, a shromažďte se k večeři velikého Boha,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 18, 'Abyste jedli těla králů, a těla hejtmanů, a těla silných, a těla koňů, i těch, kteříž na nich sedí, a těla všech svobodných i služebníků, i malých i velikých.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 19, 'I viděl jsem šelmu a krále země a vojska jejich, ani se sjeli, aby bojovali s tím, kterýž seděl na tom koni, a s rytířstvem jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 20, 'I jata jest ta šelma, a s ní falešný prorok ten, kterýž činíval divy před ní, jimiž svodil ty, kteříž přijali znamení šelmy, a kteříž se klaněli obrazu jejímu. I uvrženi jsou oba za živa do jezera ohnivého, hořícího sirou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 21, 'A jiní zbiti jsou mečem toho, kterýž seděl na koni, vycházejícím z úst jeho. A všickni ptáci nasyceni jsou těly jejich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 20, 1, 'I viděl jsem anděla sstupujícího s nebe, majícího klíč od propasti a řetěz veliký v ruce své.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 20, 2, 'I chopil draka, hada toho starého, kterýž jest ďábel a satan, i svázal jej za tisíc let.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 20, 3, 'A uvrhl ho do propasti, i zavřel, a svrchu nad ním zapečetil, aby nesvodil více národů, až by se vyplnilo tisíc let; neboť potom musí býti propuštěn na malý čas.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 20, 4, 'I viděl jsem stolice, a posadili se na nich, i dán jest jim soud, a duše stínaných pro svědectví Ježíšovo a pro slovo Boží, a kteříž se neklaněli šelmě, ani obrazu jejímu, a aniž přijali znamení jejího na čela svá, aneb na ruce své. A ožili, a kralovali s Kristem tisíc let.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 20, 5, 'Jiní pak mrtví neožili, dokudž by se nevyplnilo těch tisíc let. Toť jest první vzkříšení.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 20, 6, 'Blahoslavený a svatý, kdož má díl v prvním vzkříšení. Nad těmiť ta druhá smrt nemá moci, ale budou kněží Boží a Kristovi, a kralovati s ním budou tisíc let.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 20, 7, 'A když se vyplní tisíc let, propuštěn bude satan z žaláře svého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 20, 8, 'I vyjde, aby svodil národy, kteříž jsou na čtyřech stranách země, Goga a Magoga, a aby je shromáždil k boji, kterýchžto počet jest jako písku mořského.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 20, 9, 'I vstoupili na širokost země, a obklíčili stany svatých, i to město milé, ale sstoupil oheň od Boha s nebe, a spálil je.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 20, 10, 'A ďábel, kterýž je svodil, uvržen jest do jezera ohně a siry, kdež jest i šelma, i falešný prorok, a budouť mučeni dnem i nocí na věky věků.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 20, 11, 'I viděl jsem trůn veliký bílý, a sedícího na něm, před jehož tváří utekla země i nebe, a místo jim není nalezeno.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 20, 12, 'I viděl jsem mrtvé, malé i veliké, stojící před oblíčejem Božím, a knihy otevříny jsou. A jiná kniha také jest otevřína, to jest kniha života, i souzeni jsou mrtví podlé toho, jakž psáno bylo v knihách, totiž podlé skutků svých.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 20, 13, 'A vydalo moře mrtvé, kteříž byli v něm, tolikéž smrt i peklo vydali ty, kteříž v nich byli, i souzeni jsou jeden každý podlé skutků svých.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 20, 14, 'Smrt pak a peklo uvrženi jsou do jezera ohnivého, a toť jest smrt druhá.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 20, 15, 'I ten, kdož není nalezen v knize života zapsán, uvržen jest do jezera ohnivého.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 1, 'Potom viděl jsem nebe nové a zemi novou. Nebo první nebe a první země byla pominula, a moře již nebylo.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 2, 'A já Jan viděl jsem město svaté, Jeruzalém nový, sstupující od Boha s nebe, připravený jako nevěstu okrášlenou muži svému.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 3, 'I slyšel jsem hlas veliký s nebe, řkoucí: Aj, stánek Boží s lidmi, a bydlitiť bude s nimi, a oni budou lid jeho, a on Bůh s nimi bude, jsa Bůh jejich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 4, 'A setřeť Bůh všelikou slzu s očí jejich, a smrti již více nebude, ani kvílení, ani křiku, ani bolesti nebude více; nebo první věci pominuly.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 5, 'I řekl ten, kterýž seděl na trůnu: Aj, nové činím všecko. I řekl mi: Piš. Nebo jsou tato slova věrná a pravá.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 6, 'I dí mi: Stalo se. Jáť jsem Alfa i Oméga, počátek i konec. Jáť dám žíznivému z studnice vody živé darmo.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 7, 'Kdož svítězí, obdržíť dědičně všecko, a buduť jemu Bohem, a on mi bude synem.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 8, 'Strašlivým pak, a nevěrným, a ohyzdným, a vražedlníkům, a smilníkům, a čarodějníkům, a modlářům, i všechněm lhářům, díl jejich v jezeře, kteréž hoří ohněm a sirou, jenž jest smrt druhá.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 9, 'I přišel ke mně jeden z těch sedmi andělů, kteříž měli sedm koflíků plných sedmi ran nejposlednějších, a mluvil se mnou, řka: Poď, ukážiť nevěstu, manželku Beránkovu.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 10, 'I vnesl mne v duchu na horu velikou a vysokou, a ukázal mi město veliké, ten svatý Jeruzalém, sstupující s nebe od Boha,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 11, 'Mající slávu Boží. Jehož světlost byla podobná k kameni nejdražšímu, jako k kameni jaspidu, kterýž by byl způsobu křištálového,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 12, 'A mající zed velikou a vysokou, mající dvanácte bran, a na těch branách dvanácte andělů, a jména napsaná, kterážto jsou dvanáctera pokolení synů Izraelských.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 13, 'Od východu slunce brány tři, od půlnoci brány tři, od poledne brány tři, od západu brány tři.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 14, 'A zed městská měla základů dvanácte, a na nich jména dvanácti apoštolů Beránkových.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 15, 'A ten, kterýž mluvil se mnou, měl třtinu zlatou, aby změřil město i brány jeho i zed jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 16, 'Položení pak města toho čtverhrané jest, jehož dlouhost tak veliká jest jako i širokost. I naměřil toho města tou třtinou dvanácte tisíců honů; dlouhost pak jeho, i širokost, i vysokost jednostejná jest.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 17, 'I změřil zed jeho, sto čtyřidceti a čtyři loktů, měrou člověka, kteráž jest míra anděla.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 18, 'A bylo stavení zdi jeho jaspis, město pak samo bylo zlato čisté, podobné sklu čistému.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 19, 'A základové zdi městské všelikým kamenem drahým ozdobeni byli. Základ první byl jaspis, druhý zafir, třetí chalcedon, čtvrtý smaragd,');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 20, 'Pátý sardonyx, šestý sardius, sedmý chryzolit, osmý beryllus, devátý topazion, desátý chryzoprassus, jedenáctý hyacint, dvanáctý ametyst.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 21, 'Dvanácte pak bran dvanácte perel jest, jedna každá brána jest z jedné perly; a rynk města zlato čisté jako sklo, kteréž se naskrze prohlédnouti může.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 22, 'Ale chrámu jsem v něm neviděl; nebo Pán Bůh všemohoucí chrám jeho jest a Beránek.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 23, 'A to město nepotřebuje slunce ani měsíce, aby svítili v něm; nebo sláva Boží je osvěcuje, a svíce jeho jest Beránek.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 24, 'A národové, kteříž by k spasení přišli, v světle jeho procházeti se budou, a králové zemští přenesou slávu a čest svou do něho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 25, 'A brány jeho nebudou zavírány ve dne; noci zajisté tam nebude.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 26, 'A snesou do něho slávu a čest národů.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 27, 'A nevejdeť do něho nic poškvrňujícího, aneb působícího ohyzdnost a lež, než toliko ti, kteříž napsáni jsou v knize života Beránkova.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 1, 'I ukázal mi potok čistý vody živé, světlý jako křištál, tekoucí z trůnu Božího a Beránkova.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 2, 'U prostřed pak rynku jeho a s obou stran potoka bylo dřevo života, přinášející dvanáctero ovoce, na každý měsíc vydávající ovoce své, a lístí své k zdraví národů.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 3, 'A ničeho zlořečeného již více nebude, ale trůn Boží a Beránkův bude v něm, a služebníci jeho sloužiti jemu budou.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 4, 'A tvář jeho viděti budou, a jméno jeho bude na čelích jejich.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 5, 'A noci tam nebude, aniž budou potřebovati svíce, ani světla slunečného; nebo Pán Bůh je osvěcuje, a kralovati budou na věky věků.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 6, 'I řekl mi: Slova tato jsou věrná a pravá, a Pán Bůh svatých proroků poslal anděla svého, aby ukázal služebníkům svým, co se díti musí brzo.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 7, 'Aj, přijduť rychle. Blahoslavený, kdož ostříhá slov proroctví knihy této.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 8, 'Já pak Jan viděl jsem a slyšel tyto věci. A když jsem slyšel a viděl, padl jsem, klaněti se chtěje před nohama anděla toho, kterýž mi tyto věci ukazoval.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 9, 'Ale řekl mi: Hleď, abys toho nečinil. Neboť jsem spoluslužebník tvůj a bratří tvých proroků, a těch, kteříž ostříhají slov knihy této. Bohu se klaněj.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 10, 'Potom řekl mi: Nezapečeťuj slov proroctví knihy této; neboť jest blízko čas.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 11, 'Kdo škodí, škoď ještě; a kdo smrdí, smrď ještě; a kdo jest spravedlivý, ospravedlni se ještě; a svatý posvěť se ještě.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 12, 'A aj, přijduť brzo, a odplata má se mnou, abych odplatil jednomu každému podlé skutků jeho.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 13, 'Jáť jsem Alfa i Oméga, počátek i konec, první i poslední.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 14, 'Blahoslavení, kteříž zachovávají přikázaní jeho, aby měli právo k dřevu života, a aby branami vešli do města.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 15, 'Vně pak budou psi a čarodějníci, a smilníci, a vražedlníci, a modláři, i každý, kdož miluje a činí lež.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 16, 'Já Ježíš poslal jsem anděla svého, aby vám svědčil o těchto věcech v církvích. Já jsem kořen a rod Davidův, a hvězda jasná a jitřní.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 17, 'A Duch i nevěsta řkou: Poď. A kdož slyší, rciž: Přiď. A kdož žízní, přijdiž, a kdo chce, nabeř vody života darmo.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 18, 'Osvědčujiť pak každému, kdož by slyšel slova proroctví knihy této, jestliže by kdo přidal k těmto věcem, žeť jemu přidá Bůh ran napsaných v knize této.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 19, 'A jestliže by kdo ujal od slov proroctví tohoto, odejmeť Bůh díl jeho z knihy života, a z města svatého, a z těch věcí, kteréž jsou napsány v knize této.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 20, 'Takť praví ten, kterýž svědectví vydává o těchto věcech: Jistěť přijdu brzo. Amen. Přijdiž tedy, Pane Ježíši.');
INSERT INTO `CzeBKR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 21, 'Milost Pána našeho Jezukrista se všechněmi vámi. Amen.');
